INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'In principio creavit Deus cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Terra autem erat inanis et vacua, et tenebræ erant super faciem abyssi: et spiritus Dei ferebatur super aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Dixitque Deus: Fiat lux. Et facta est lux.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Et vidit Deus lucem quod esset bona: et divisit lucem a tenebris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Appellavitque lucem Diem, et tenebras Noctem: factumque est vespere et mane, dies unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Dixit quoque Deus: Fiat firmamentum in medio aquarum: et dividat aquas ab aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Et fecit Deus firmamentum, divisitque aquas, quæ erant sub firmamento, ab his, quæ erant super firmamentum. Et factum est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Vocavitque Deus firmamentum, Cælum: et factum est vespere et mane, dies secundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Dixit vero Deus: Congregentur aquæ, quæ sub cælo sunt, in locum unum: et appareat arida. Et factum est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Et vocavit Deus aridam Terram, congregationesque aquarum appellavit Maria. Et vidit Deus quod esset bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Et ait: Germinet terra herbam virentem, et facientem semen, et lignum pomiferum faciens fructum juxta genus suum, cujus semen in semetipso sit super terram. Et factum est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Et protulit terra herbam virentem, et facientem semen juxta genus suum, lignumque faciens fructum, et habens unumquodque sementem secundum speciem suam. Et vidit Deus quod esset bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Et factum est vespere et mane, dies tertius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Dixit autem Deus: Fiant luminaria in firmamento cæli, et dividant diem ac noctem, et sint in signa et tempora, et dies et annos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'ut luceant in firmamento cæli, et illuminent terram. Et factum est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Fecitque Deus duo luminaria magna: luminare majus, ut præesset diei: et luminare minus, ut præesset nocti: et stellas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Et posuit eas in firmamento cæli, ut lucerent super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'et præessent diei ac nocti, et dividerent lucem ac tenebras. Et vidit Deus quod esset bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Et factum est vespere et mane, dies quartus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Dixit etiam Deus: Producant aquæ reptile animæ viventis, et volatile super terram sub firmamento cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Creavitque Deus cete grandia, et omnem animam viventem atque motabilem, quam produxerant aquæ in species suas, et omne volatile secundum genus suum. Et vidit Deus quod esset bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Benedixitque eis, dicens: Crescite, et multiplicamini, et replete aquas maris: avesque multiplicentur super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Et factum est vespere et mane, dies quintus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Dixit quoque Deus: Producat terra animam viventem in genere suo, jumenta, et reptilia, et bestias terræ secundum species suas. Factumque est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Et fecit Deus bestias terræ juxta species suas, et jumenta, et omne reptile terræ in genere suo. Et vidit Deus quod esset bonum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'et ait: Faciamus hominem ad imaginem et similitudinem nostram: et præsit piscibus maris, et volatilibus cæli, et bestiis, universæque terræ, omnique reptili, quod movetur in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Et creavit Deus hominem ad imaginem suam: ad imaginem Dei creavit illum, masculum et feminam creavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Benedixitque illis Deus, et ait: Crescite et multiplicamini, et replete terram, et subjicite eam, et dominamini piscibus maris, et volatilibus cæli, et universis animantibus, quæ moventur super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Dixitque Deus: Ecce dedi vobis omnem herbam afferentem semen super terram, et universa ligna quæ habent in semetipsis sementem generis sui, ut sint vobis in escam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'et cunctis animantibus terræ, omnique volucri cæli, et universis quæ moventur in terra, et in quibus est anima vivens, ut habeant ad vescendum. Et factum est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Viditque Deus cuncta quæ fecerat, et erant valde bona. Et factum est vespere et mane, dies sextus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Igitur perfecti sunt cæli et terra, et omnis ornatus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Complevitque Deus die septimo opus suum quod fecerat: et requievit die septimo ab universo opere quod patrarat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et benedixit diei septimo, et sanctificavit illum, quia in ipso cessaverat ab omni opere suo quod creavit Deus ut faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Istæ sunt generationes cæli et terræ, quando creata sunt, in die quo fecit Dominus Deus cælum et terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'et omne virgultum agri antequam oriretur in terra, omnemque herbam regionis priusquam germinaret: non enim pluerat Dominus Deus super terram, et homo non erat qui operaretur terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'sed fons ascendebat e terra, irrigans universam superficiem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Formavit igitur Dominus Deus hominem de limo terræ, et inspiravit in faciem ejus spiraculum vitæ, et factus est homo in animam viventem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Plantaverat autem Dominus Deus paradisum voluptatis a principio, in quo posuit hominem quem formaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Produxitque Dominus Deus de humo omne lignum pulchrum visu, et ad vescendum suave lignum etiam vitæ in medio paradisi, lignumque scientiæ boni et mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Et fluvius egrediebatur de loco voluptatis ad irrigandum paradisum, qui inde dividitur in quatuor capita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Nomen uni Phison: ipse est qui circuit omnem terram Hevilath, ubi nascitur aurum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'et aurum terræ illius optimum est; ibi invenitur bdellium, et lapis onychinus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Et nomen fluvii secundi Gehon; ipse est qui circumit omnem terram \'thiopiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Nomen vero fluminis tertii, Tigris: ipse vadit contra Assyrios. Fluvius autem quartus, ipse est Euphrates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Tulit ergo Dominus Deus hominem, et posuit eum in paradiso voluptatis, ut operaretur, et custodiret illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'præcepitque ei, dicens: Ex omni ligno paradisi comede;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'de ligno autem scientiæ boni et mali ne comedas: in quocumque enim die comederis ex eo, morte morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Dixit quoque Dominus Deus: Non est bonum esse hominem solum: faciamus ei adjutorium simile sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Formatis igitur Dominus Deus de humo cunctis animantibus terræ, et universis volatilibus cæli, adduxit ea ad Adam, ut videret quid vocaret ea: omne enim quod vocavit Adam animæ viventis, ipsum est nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Appellavitque Adam nominibus suis cuncta animantia, et universa volatilia cæli, et omnes bestias terræ: Adæ vero non inveniebatur adjutor similis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Immisit ergo Dominus Deus soporem in Adam: cumque obdormisset, tulit unam de costis ejus, et replevit carnem pro ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Et ædificavit Dominus Deus costam, quam tulerat de Adam, in mulierem: et adduxit eam ad Adam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Dixitque Adam: Hoc nunc os ex ossibus meis, et caro de carne mea: hæc vocabitur Virago, quoniam de viro sumpta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Quam ob rem relinquet homo patrem suum, et matrem, et adhærebit uxori suæ: et erunt duo in carne una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Erat autem uterque nudus, Adam scilicet et uxor ejus: et non erubescebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Sed et serpens erat callidior cunctis animantibus terræ quæ fecerat Dominus Deus. Qui dixit ad mulierem: Cur præcepit vobis Deus ut non comederetis de omni ligno paradisi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Cui respondit mulier: De fructu lignorum, quæ sunt in paradiso, vescimur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'de fructu vero ligni quod est in medio paradisi, præcepit nobis Deus ne comederemus, et ne tangeremus illud, ne forte moriamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Dixit autem serpens ad mulierem: Nequaquam morte moriemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Scit enim Deus quod in quocumque die comederitis ex eo, aperientur oculi vestri, et eritis sicut dii, scientes bonum et malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Vidit igitur mulier quod bonum esset lignum ad vescendum, et pulchrum oculis, aspectuque delectabile: et tulit de fructu illius, et comedit: deditque viro suo, qui comedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Et aperti sunt oculi amborum; cumque cognovissent se esse nudos, consuerunt folia ficus, et fecerunt sibi perizomata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Et cum audissent vocem Domini Dei deambulantis in paradiso ad auram post meridiem, abscondit se Adam et uxor ejus a facie Domini Dei in medio ligni paradisi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Vocavitque Dominus Deus Adam, et dixit ei: Ubi es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Qui ait: Vocem tuam audivi in paradiso, et timui, eo quod nudus essem, et abscondi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Cui dixit: Quis enim indicavit tibi quod nudus esses, nisi quod ex ligno de quo præceperam tibi ne comederes, comedisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Dixitque Adam: Mulier, quam dedisti mihi sociam, dedit mihi de ligno, et comedi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Et dixit Dominus Deus ad mulierem: Quare hoc fecisti? Quæ respondit: Serpens decepit me, et comedi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Et ait Dominus Deus ad serpentem: Quia fecisti hoc, maledictus es inter omnia animantia, et bestias terræ: super pectus tuum gradieris, et terram comedes cunctis diebus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Inimicitias ponam inter te et mulierem, et semen tuum et semen illius: ipsa conteret caput tuum, et tu insidiaberis calcaneo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Mulieri quoque dixit: Multiplicabo ærumnas tuas, et conceptus tuos: in dolore paries filios, et sub viri potestate eris, et ipse dominabitur tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Adæ vero dixit: Quia audisti vocem uxoris tuæ, et comedisti de ligno, ex quo præceperam tibi ne comederes, maledicta terra in opere tuo: in laboribus comedes ex ea cunctis diebus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Spinas et tribulos germinabit tibi, et comedes herbam terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'In sudore vultus tui vesceris pane, donec revertaris in terram de qua sumptus es: quia pulvis es et in pulverem reverteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Et vocavit Adam nomen uxoris suæ, Heva: eo quod mater esset cunctorum viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Fecit quoque Dominus Deus Adæ et uxori ejus tunicas pelliceas, et induit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'et ait: Ecce Adam quasi unus ex nobis factus est, sciens bonum et malum: nunc ergo ne forte mittat manum suam, et sumat etiam de ligno vitæ, et comedat, et vivat in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Et emisit eum Dominus Deus de paradiso voluptatis, ut operaretur terram de qua sumptus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Ejecitque Adam: et collocavit ante paradisum voluptatis cherubim, et flammeum gladium, atque versatilem, ad custodiendam viam ligni vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Adam vero cognovit uxorem suam Hevam, quæ concepit et peperit Cain, dicens: Possedi hominem per Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Rursumque peperit fratrem ejus Abel. Fuit autem Abel pastor ovium, et Cain agricola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Factum est autem post multos dies ut offerret Cain de fructibus terræ munera Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Abel quoque obtulit de primogenitis gregis sui, et de adipibus eorum: et respexit Dominus ad Abel, et ad munera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Ad Cain vero, et ad munera illius non respexit: iratusque est Cain vehementer, et concidit vultus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Dixitque Dominus ad eum: Quare iratus es? et cur concidit facies tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'nonne si bene egeris, recipies: sin autem male, statim in foribus peccatum aderit? sed sub te erit appetitus ejus, et tu dominaberis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Dixitque Cain ad Abel fratrem suum: Egrediamur foras. Cumque essent in agro, consurrexit Cain adversus fratrem suum Abel, et interfecit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Et ait Dominus ad Cain: Ubi est Abel frater tuus? Qui respondit: Nescio: num custos fratris mei sum ego?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Dixitque ad eum: Quid fecisti? vox sanguinis fratris tui clamat ad me de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Nunc igitur maledictus eris super terram, quæ aperuit os suum, et suscepit sanguinem fratris tui de manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Cum operatus fueris eam, non dabit tibi fructus suos: vagus et profugus eris super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Dixitque Cain ad Dominum: Major est iniquitas mea, quam ut veniam merear.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Ecce ejicis me hodie a facie terræ, et a facie tua abscondar, et ero vagus et profugus in terra: omnis igitur qui invenerit me, occidet me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Dixitque ei Dominus: Nequaquam ita fiet: sed omnis qui occiderit Cain, septuplum punietur. Posuitque Dominus Cain signum, ut non interficeret eum omnis qui invenisset eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Egressusque Cain a facie Domini, habitavit profugus in terra ad orientalem plagam Eden.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Cognovit autem Cain uxorem suam, quæ concepit, et peperit Henoch: et ædificavit civitatem, vocavitque nomen ejus ex nomine filii sui, Henoch.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Porro Henoch genuit Irad, et Irad genuit Maviaël, et Maviaël genuit Mathusaël, et Mathusaël genuit Lamech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Qui accepit duas uxores, nomen uni Ada, et nomen alteri Sella.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Genuitque Ada Jabel, qui fuit pater habitantium in tentoriis, atque pastorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et nomen fratris ejus Jubal: ipse fuit pater canentium cithara et organo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Sella quoque genuit Tubalcain, qui fuit malleator et faber in cuncta opera æris et ferri. Soror vero Tubalcain, Noëma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Dixitque Lamech uxoribus suis Adæ et Sellæ: Audite vocem meam, uxores Lamech; auscultate sermonem meum: quoniam occidi virum in vulnus meum, et adolescentulum in livorem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Septuplum ultio dabitur de Cain: de Lamech vero septuagies septies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Cognovit quoque adhuc Adam uxorem suam: et peperit filium, vocavitque nomen ejus Seth, dicens: Posuit mihi Deus semen aliud pro Abel, quem occidit Cain.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Sed et Seth natus est filius, quem vocavit Enos: iste cœpit invocare nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Hic est liber generationis Adam. In die qua creavit Deus hominem, ad similitudinem Dei fecit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Masculum et feminam creavit eos, et benedixit illis: et vocavit nomen eorum Adam, in die quo creati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Vixit autem Adam centum triginta annis: et genuit ad imaginem et similitudinem suam, vocavitque nomen ejus Seth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Et facti sunt dies Adam, postquam genuit Seth, octingenti anni: genuitque filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Et factum est omne tempus quod vixit Adam, anni nongenti triginta, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Vixit quoque Seth centum quinque annis, et genuit Enos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Vixitque Seth, postquam genuit Enos, octingentis septem annis, genuitque filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Et facti sunt omnes dies Seth nongentorum duodecim annorum, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Vixit vero Enos nonaginta annis, et genuit Cainan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Post cujus ortum vixit octingentis quindecim annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Factique sunt omnes dies Enos nongenti quinque anni, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Vixit quoque Cainan septuaginta annis, et genuit Malaleel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et vixit Cainan, postquam genuit Malaleel, octingentis quadraginta annis, genuitque filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Et facti sunt omnes dies Cainan nongenti decem anni, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Vixit autem Malaleel sexaginta quinque annis, et genuit Jared.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et vixit Malaleel, postquam genuit Jared, octingentis triginta annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Et facti sunt omnes dies Malaleel octingenti nonaginta quinque anni, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Vixitque Jared centum sexaginta duobus annis, et genuit Henoch.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et vixit Jared, postquam genuit Henoch, octingentis annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Et facti sunt omnes dies Jared nongenti sexaginta duo anni, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Porro Henoch vixit sexaginta quinque annis, et genuit Mathusalam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Et ambulavit Henoch cum Deo: et vixit, postquam genuit Mathusalam, trecentis annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Et facti sunt omnes dies Henoch trecenti sexaginta quinque anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Ambulavitque cum Deo, et non apparuit: quia tulit eum Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Vixit quoque Mathusala centum octoginta septem annis, et genuit Lamech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Et vixit Mathusala, postquam genuit Lamech, septingentis octoginta duobus annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Et facti sunt omnes dies Mathusala nongenti sexaginta novem anni, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Vixit autem Lamech centum octoginta duobus annis, et genuit filium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'vocavitque nomen ejus Noë, dicens: Iste consolabitur nos ab operibus et laboribus manuum nostrarum in terra, cui maledixit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Vixitque Lamech, postquam genuit Noë, quingentis nonaginta quinque annis, et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Et facti sunt omnes dies Lamech septingenti septuaginta septem anni, et mortuus est. Noë vero cum quingentorum esset annorum, genuit Sem, Cham et Japheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Cumque cœpissent homines multiplicari super terram, et filias procreassent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'videntes filii Dei filias hominum quod essent pulchræ, acceperunt sibi uxores ex omnibus, quas elegerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Dixitque Deus: Non permanebit spiritus meus in homine in æternum, quia caro est: eruntque dies illius centum viginti annorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Gigantes autem erant super terram in diebus illis: postquam enim ingressi sunt filii Dei ad filias hominum, illæque genuerunt, isti sunt potentes a sæculo viri famosi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Videns autem Deus quod multa malitia hominum esset in terra, et cuncta cogitatio cordis intenta esset ad malum omni tempore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'pœnituit eum quod hominum fecisset in terra. Et tactus dolore cordis intrinsecus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Delebo, inquit, hominem, quem creavi, a facie terræ, ab homine usque ad animantia, a reptili usque ad volucres cæli: pœnitet enim me fecisse eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Noë vero invenit gratiam coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Hæ sunt generationes Noë: Noë vir justus atque perfectus fuit in generationibus suis; cum Deo ambulavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et genuit tres filios, Sem, Cham et Japheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Corrupta est autem terra coram Deo, et repleta est iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Cumque vidisset Deus terram esse corruptam (omnis quippe caro corruperat viam suam super terram),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'dixit ad Noë: Finis universæ carnis venit coram me: repleta est terra iniquitate a facie eorum, et ego disperdam eos cum terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Fac tibi arcam de lignis lævigatis; mansiunculas in arca facies, et bitumine linies intrinsecus et extrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Et sic facies eam: trecentorum cubitorum erit longitudo arcæ, quinquaginta cubitorum latitudo, et triginta cubitorum altitudo illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Fenestram in arca facies, et in cubito consummabis summitatem ejus: ostium autem arcæ pones ex latere; deorsum, cœnacula et tristega facies in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ecce ego adducam aquas diluvii super terram, ut interficiam omnem carnem, in qua spiritus vitæ est subter cælum: universa quæ in terra sunt, consumentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Ponamque fœdus meum tecum: et ingredieris arcam tu et filii tui, uxor tua, et uxores filiorum tuorum tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Et ex cunctis animantibus universæ carnis bina induces in arcam, ut vivant tecum: masculini sexus et feminini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'De volucribus juxta genus suum, et de jumentis in genere suo, et ex omni reptili terræ secundum genus suum: bina de omnibus ingredientur tecum, ut possint vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Tolles igitur tecum ex omnibus escis, quæ mandi possunt, et comportabis apud te: et erunt tam tibi, quam illis in cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Fecit igitur Noë omnia quæ præceperat illi Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Dixitque Dominus ad eum: Ingredere tu et omnis domus tua in arcam: te enim vidi justum coram me in generatione hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Ex omnibus animantibus mundis tolle septena et septena, masculum et feminam: de animantibus vero immundis duo et duo, masculum et feminam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Sed et de volatilibus cæli septena et septena, masculum et feminam: ut salvetur semen super faciem universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Adhuc enim, et post dies septem ego pluam super terram quadraginta diebus et quadraginta noctibus: et delebo omnem substantiam, quam feci, de superficie terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Fecit ergo Noë omnia quæ mandaverat ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Eratque sexcentorum annorum quando diluvii aquæ inundaverunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Et ingressus est Noë et filii ejus, uxor ejus et uxores filiorum ejus cum eo in arcam propter aquas diluvii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'De animantibus quoque mundis et immundis, et de volucribus, et ex omni quod movetur super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'duo et duo ingressa sunt ad Noë in arcam, masculus et femina, sicut præceperat Dominus Noë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Cumque transissent septem dies, aquæ diluvii inundaverunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Anno sexcentesimo vitæ Noë, mense secundo, septimodecimo die mensis, rupti sunt omnes fontes abyssi magnæ, et cataractæ cæli apertæ sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'et facta est pluvia super terram quadraginta diebus et quadraginta noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'In articulo diei illius ingressus est Noë, et Sem, et Cham, et Japheth filii ejus; uxor illius, et tres uxores filiorum ejus cum eis in arcam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'ipsi et omne animal secundum genus suum, universaque jumenta in genere suo, et omne quod movetur super terram in genere suo, cunctumque volatile secundum genus suum, universæ aves, omnesque volucres,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'ingressæ sunt ad Noë in arcam, bina et bina ex omni carne, in qua erat spiritus vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Et quæ ingressa sunt, masculus et femina ex omni carne introierunt, sicut præceperat ei Deus: et inclusit eum Dominus deforis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Factumque est diluvium quadraginta diebus super terram: et multiplicatæ sunt aquæ, et elevaverunt arcam in sublime a terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Vehementer enim inundaverunt, et omnia repleverunt in superficie terræ: porro arca ferebatur super aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Et aquæ prævaluerunt nimis super terram: opertique sunt omnes montes excelsi sub universo cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Quindecim cubitis altior fuit aqua super montes, quos operuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Consumptaque est omnis caro quæ movebatur super terram, volucrum, animantium, bestiarum, omniumque reptilium, quæ reptant super terram: universi homines,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'et cuncta, in quibus spiraculum vitæ est in terra, mortua sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Et delevit omnem substantiam quæ erat super terram, ab homine usque ad pecus, tam reptile quam volucres cæli: et deleta sunt de terra. Remansit autem solus Noë, et qui cum eo erant in arca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Obtinueruntque aquæ terram centum quinquaginta diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Recordatus autem Deus Noë, cunctorumque animantium, et omnium jumentorum, quæ erant cum eo in arca, adduxit spiritum super terram, et imminutæ sunt aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Et clausi sunt fontes abyssi, et cataractæ cæli: et prohibitæ sunt pluviæ de cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Reversæque sunt aquæ de terra euntes et redeuntes: et cœperunt minui post centum quinquaginta dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Requievitque arca mense septimo, vigesimo septimo die mensis, super montes Armeniæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'At vero aquæ ibant et decrescebant usque ad decimum mensem: decimo enim mense, primo die mensis, apparuerunt cacumina montium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Cumque transissent quadraginta dies, aperiens Noë fenestram arcæ, quam fecerat, dimisit corvum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'qui egrediebatur, et non revertebatur, donec siccarentur aquæ super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Emisit quoque columbam post eum, ut videret si jam cessassent aquæ super faciem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Quæ cum non invenisset ubi requiesceret pes ejus, reversa est ad eum in arcam: aquæ enim erant super universam terram: extenditque manum, et apprehensam intulit in arcam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Expectatis autem ultra septem diebus aliis, rursum dimisit columbam ex arca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'At illa venit ad eum ad vesperam, portans ramum olivæ virentibus foliis in ore suo: intellexit ergo Noë quod cessassent aquæ super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Expectavitque nihilominus septem alios dies: et emisit columbam, quæ non est reversa ultra ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Igitur sexcentesimo primo anno, primo mense, prima die mensis, imminutæ sunt aquæ super terram: et aperiens Noë tectum arcæ, aspexit, viditque quod exsiccata esset superficies terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Mense secundo, septimo et vigesimo die mensis arefacta est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Locutus est autem Deus ad Noë, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Egredere de arca, tu et uxor tua, filii tui et uxores filiorum tuorum tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Cuncta animantia, quæ sunt apud te, ex omni carne, tam in volatilibus quam in bestiis et universis reptilibus, quæ reptant super terram, educ tecum, et ingredimini super terram: crescite et multiplicamini super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Egressus est ergo Noë, et filii ejus: uxor illius, et uxores filiorum ejus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Sed et omnia animantia, jumenta, et reptilia quæ reptant super terram, secundum genus suum, egressa sunt de arca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, '\'dificavit autem Noë altare Domino: et tollens de cunctis pecoribus et volucribus mundis, obtulit holocausta super altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Odoratusque est Dominus odorem suavitatis, et ait: Nequaquam ultra maledicam terræ propter homines: sensus enim et cogitatio humani cordis in malum prona sunt ab adolescentia sua: non igitur ultra percutiam omnem animam viventem sicut feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Cunctis diebus terræ, sementis et messis, frigus et æstus, æstas et hiems, nox et dies non requiescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Benedixitque Deus Noë et filiis ejus. Et dixit ad eos: Crescite, et multiplicamini, et replete terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Et terror vester ac tremor sit super cuncta animalia terræ, et super omnes volucres cæli, cum universis quæ moventur super terram: omnes pisces maris manui vestræ traditi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Et omne, quod movetur et vivit, erit vobis in cibum: quasi olera virentia tradidi vobis omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Excepto, quod carnem cum sanguine non comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Sanguinem enim animarum vestrarum requiram de manu cunctarum bestiarum: et de manu hominis, de manu viri, et fratris ejus requiram animam hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Quicumque effuderit humanum sanguinem, fundetur sanguis illius: ad imaginem quippe Dei factus est homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vos autem crescite et multiplicamini, et ingredimini super terram, et implete eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Hæc quoque dixit Deus ad Noë, et ad filios ejus cum eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Ecce ego statuam pactum meum vobiscum, et cum semine vestro post vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'et ad omnem animam viventem, quæ est vobiscum, tam in volucribus quam in jumentis et pecudibus terræ cunctis, quæ egressa sunt de arca, et universis bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Statuam pactum meum vobiscum, et nequaquam ultra interficietur omnis caro aquis diluvii, neque erit deinceps diluvium dissipans terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Dixitque Deus: Hoc signum fœderis quod do inter me et vos, et ad omnem animam viventem, quæ est vobiscum in generationes sempiternas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'arcum meum ponam in nubibus, et erit signum fœderis inter me et inter terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Cumque obduxero nubibus cælum, apparebit arcus meus in nubibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'et recordabor fœderis mei vobiscum, et cum omni anima vivente quæ carnem vegetat: et non erunt ultra aquæ diluvii ad delendum universam carnem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Eritque arcus in nubibus, et videbo illum, et recordabor fœderis sempiterni quod pactum est inter Deum et omnem animam viventem universæ carnis quæ est super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dixitque Deus ad Noë: Hoc erit signum fœderis, quod constitui inter me et omnem carnem super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Erant ergo filii Noë, qui egressi sunt de arca, Sem, Cham et Japheth: porro Cham ipse est pater Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Tres isti filii sunt Noë: et ab his disseminatum est omne genus hominum super universam terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Cœpitque Noë vir agricola exercere terram, et plantavit vineam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Bibensque vinum inebriatus est, et nudatus in tabernaculo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Quod cum vidisset Cham, pater Chanaan, verenda scilicet patris sui esse nudata, nuntiavit duobus fratribus suis foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'At vero Sem et Japheth pallium imposuerunt humeris suis, et incedentes retrorsum, operuerunt verenda patris sui: faciesque eorum aversæ erant, et patris virilia non viderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Evigilans autem Noë ex vino, cum didicisset quæ fecerat ei filius suus minor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'ait: Maledictus Chanaan, servus servorum erit fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dixitque: Benedictus Dominus Deus Sem, sit Chanaan servus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Dilatet Deus Japheth, et habitet in tabernaculis Sem, sitque Chanaan servus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Vixit autem Noë post diluvium trecentis quinquaginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Et impleti sunt omnes dies ejus nongentorum quinquaginta annorum: et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Hæ sunt generationes filiorum Noë, Sem, Cham et Japheth: natique sunt eis filii post diluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Filii Japheth: Gomer, et Magog, et Madai, et Javan, et Thubal, et Mosoch, et Thiras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Porro filii Gomer: Ascenez et Riphath et Thogorma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Filii autem Javan: Elisa et Tharsis, Cetthim et Dodanim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Ab his divisæ sunt insulæ gentium in regionibus suis, unusquisque secundum linguam suam et familias suas in nationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Filii autem Cham: Chus, et Mesraim, et Phuth, et Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Filii Chus: Saba, et Hevila, et Sabatha, et Regma, et Sabatacha. Filii Regma: Saba et Dadan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Porro Chus genuit Nemrod: ipse cœpit esse potens in terra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'et erat robustus venator coram Domino. Ob hoc exivit proverbium: Quasi Nemrod robustus venator coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Fuit autem principium regni ejus Babylon, et Arach et Achad, et Chalanne, in terra Sennaar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De terra illa egressus est Assur, et ædificavit Niniven, et plateas civitatis, et Chale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Resen quoque inter Niniven et Chale: hæc est civitas magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'At vero Mesraim genuit Ludim, et Anamim et Laabim, Nephthuim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'et Phetrusim, et Chasluim: de quibus egressi sunt Philisthiim et Caphtorim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Chanaan autem genuit Sidonem primogenitum suum. Hethæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'et Jebusæum, et Amorrhæum, Gergesæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hevæum, et Aracæum: Sinæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'et Aradium, Samaræum, et Amathæum: et post hæc disseminati sunt populi Chananæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Factique sunt termini Chanaan venientibus a Sidone Geraram usque Gazam, donec ingrediaris Sodomam et Gomorrham, et Adamam, et Seboim usque Lesa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Hi sunt filii Cham in cognationibus, et linguis, et generationibus, terrisque et gentibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'De Sem quoque nati sunt, patre omnium filiorum Heber, fratre Japheth majore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Filii Sem: \'lam, et Assur, et Arphaxad, et Lud, et Aram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Filii Aram: Us, et Hul, et Gether, et Mes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'At vero Arphaxad genuit Sale, de quo ortus est Heber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Natique sunt Heber filii duo: nomen uni Phaleg, eo quod in diebus ejus divisa sit terra: et nomen fratris ejus Jectan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Qui Jectan genuit Elmodad, et Saleph, et Asarmoth, Jare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'et Aduram, et Uzal, et Decla,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'et Ebal, et Abimaël, Saba,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'et Ophir, et Hevila, et Jobab: omnes isti, filii Jectan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Et facta est habitatio eorum de Messa pergentibus usque Sephar montem orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Isti filii Sem secundum cognationes, et linguas, et regiones in gentibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Hæ familiæ Noë juxta populos et nationes suas. Ab his divisæ sunt gentes in terra post diluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Erat autem terra labii unius, et sermonum eorumdem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Cumque proficiscerentur de oriente, invenerunt campum in terra Sennaar, et habitaverunt in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Dixitque alter ad proximum suum: Venite, faciamus lateres, et coquamus eos igni. Habueruntque lateres pro saxis, et bitumen pro cæmento:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'et dixerunt: Venite, faciamus nobis civitatem et turrim, cujus culmen pertingat ad cælum: et celebremus nomen nostrum antequam dividamur in universas terras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Descendit autem Dominus ut videret civitatem et turrim, quam ædificabant filii Adam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'et dixit: Ecce, unus est populus, et unum labium omnibus: cœperuntque hoc facere, nec desistent a cogitationibus suis, donec eas opere compleant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Venite igitur, descendamus, et confundamus ibi linguam eorum, ut non audiat unusquisque vocem proximi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Atque ita divisit eos Dominus ex illo loco in universas terras, et cessaverunt ædificare civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Et idcirco vocatum est nomen ejus Babel, quia ibi confusum est labium universæ terræ: et inde dispersit eos Dominus super faciem cunctarum regionum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Hæ sunt generationes Sem: Sem erat centum annorum quando genuit Arphaxad, biennio post diluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Vixitque Sem, postquam genuit Arphaxad, quingentis annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Porro Arphaxad vixit triginta quinque annis, et genuit Sale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Vixitque Arphaxad, postquam genuit Sale, trecentis tribus annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Sale quoque vixit triginta annis, et genuit Heber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Vixitque Sale, postquam genuit Heber, quadringentis tribus annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Vixit autem Heber triginta quatuor annis, et genuit Phaleg.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et vixit Heber postquam genuit Phaleg, quadringentis triginta annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Vixit quoque Phaleg triginta annis, et genuit Reu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Vixitque Phaleg, postquam genuit Reu, ducentis novem annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Vixit autem Reu triginta duobus annis, et genuit Sarug.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Vixit quoque Reu, postquam genuit Sarug, ducentis septem annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Vixit vero Sarug triginta annis, et genuit Nachor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Vixitque Sarug, postquam genuit Nachor, ducentis annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Vixit autem Nachor viginti novem annis, et genuit Thare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Vixitque Nachor, postquam genuit Thare, centum decem et novem annis: et genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Vixitque Thare septuaginta annis, et genuit Abram, et Nachor, et Aran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Hæ sunt autem generationes Thare: Thare genuit Abram, Nachor et Aran. Porro Aran genuit Lot.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Mortuusque est Aran ante Thare patrem suum, in terra nativitatis suæ, in Ur Chaldæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Duxerunt autem Abram et Nachor uxores: nomen uxoris Abram, Sarai: et nomen uxoris Nachor, Melcha filia Aran, patris Melchæ, et patris Jeschæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Erat autem Sarai sterilis, nec habebat liberos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Tulit itaque Thare Abram filium suum, et Lot filium Aran, filium filii sui, et Sarai nurum suam, uxorem Abram filii sui, et eduxit eos de Ur Chaldæorum, ut irent in terram Chanaan: veneruntque usque Haran, et habitaverunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et facti sunt dies Thare ducentorum quinque annorum, et mortuus est in Haran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Dixit autem Dominus ad Abram: Egredere de terra tua, et de cognatione tua, et de domo patris tui, et veni in terram quam monstrabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Faciamque te in gentem magnam, et benedicam tibi, et magnificabo nomen tuum, erisque benedictus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Benedicam benedicentibus tibi, et maledicam maledicentibus tibi, atque in te benedicentur universæ cognationes terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Egressus est itaque Abram sicut præceperat ei Dominus, et ivit cum eo Lot: septuaginta quinque annorum erat Abram cum egrederetur de Haran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Tulitque Sarai uxorem suam, et Lot filium fratris sui, universamque substantiam quam possederant, et animas quas fecerant in Haran: et egressi sunt ut irent in terram Chanaan. Cumque venissent in eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'pertransivit Abram terram usque ad locum Sichem, usque ad convallem illustrem: Chananæus autem tunc erat in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Apparuit autem Dominus Abram, et dixit ei: Semini tuo dabo terram hanc. Qui ædificavit ibi altare Domino, qui apparuerat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Et inde transgrediens ad montem, qui erat contra orientem Bethel, tetendit ibi tabernaculum suum, ab occidente habens Bethel, et ab oriente Hai: ædificavit quoque ibi altare Domino, et invocavit nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Perrexitque Abram vadens, et ultra progrediens ad meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Facta est autem fames in terra: descenditque Abram in \'gyptum, ut peregrinaretur ibi: prævaluerat enim fames in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Cumque prope esset ut ingrederetur \'gyptum, dixit Sarai uxori suæ: Novi quod pulchra sis mulier:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'et quod cum viderint te \'gyptii, dicturi sunt: Uxor ipsius est: et interficient me, et te reservabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dic ergo, obsecro te, quod soror mea sis: ut bene sit mihi propter te, et vivat anima mea ob gratiam tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Cum itaque ingressus esset Abram \'gyptum, viderunt \'gyptii mulierem quod esset pulchra nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Et nuntiaverunt principes Pharaoni, et laudaverunt eam apud illum: et sublata est mulier in domum Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Abram vero bene usi sunt propter illam: fueruntque ei oves et boves et asini, et servi et famulæ, et asinæ et cameli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Flagellavit autem Dominus Pharaonem plagis maximis, et domum ejus, propter Sarai uxorem Abram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Vocavitque Pharao Abram, et dixit ei: Quidnam est hoc quod fecisti mihi? quare non indicasti quod uxor tua esset?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'quam ob causam dixisti esse sororem tuam, ut tollerem eam mihi in uxorem? Nunc igitur ecce conjux tua, accipe eam, et vade.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Præcepitque Pharao super Abram viris: et deduxerunt eum, et uxorem illius, et omnia quæ habebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Ascendit ergo Abram de \'gypto, ipse et uxor ejus, et omnia quæ habebat, et Lot cum eo, ad australem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Erat autem dives valde in possessione auri et argenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Reversusque est per iter, quo venerat, a meridie in Bethel, usque ad locum ubi prius fixerat tabernaculum inter Bethel et Hai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'in loco altaris quod fecerat prius: et invocavit ibi nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Sed et Lot qui erat cum Abram, fuerunt greges ovium, et armenta, et tabernacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Nec poterat eos capere terra, ut habitarent simul: erat quippe substantia eorum multa, et nequibant habitare communiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Unde et facta est rixa inter pastores gregum Abram et Lot. Eo autem tempore Chananæus et Pherezæus habitabant in terra illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Dixit ergo Abram ad Lot: Ne quæso sit jurgium inter me et te, et inter pastores meos et pastores tuos: fratres enim sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Ecce universa terra coram te est: recede a me, obsecro: si ad sinistram ieris, ego dexteram tenebo: si tu dexteram elegeris, ego ad sinistram pergam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Elevatis itaque Lot oculis, vidit omnem circa regionem Jordanis, quæ universa irrigabatur antequam subverteret Dominus Sodomam et Gomorrham, sicut paradisus Domini, et sicut \'gyptus venientibus in Segor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Elegitque sibi Lot regionem circa Jordanem, et recessit ab oriente: divisique sunt alterutrum a fratre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram habitavit in terra Chanaan; Lot vero moratus est in oppidis, quæ erant circa Jordanem, et habitavit in Sodomis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Homines autem Sodomitæ pessimi erant, et peccatores coram Domino nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Dixitque Dominus ad Abram, postquam divisus est ab eo Lot: Leva oculos tuos et vide a loco, in quo nunc es, ad aquilonem et meridiem, ad orientem et occidentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Omnem terram, quam conspicis, tibi dabo, et semini tuo usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Faciamque semen tuum sicut pulverem terræ: si quis potest hominum numerare pulverem terræ, semen quoque tuum numerare poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Surge, et perambula terram in longitudine et in latitudine sua: quia tibi daturus sum eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Movens igitur tabernaculum suum Abram, venit, et habitavit juxta convallem Mambre, quæ est in Hebron: ædificavitque ibi altare Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Factum est autem in illo tempore, ut Amraphel rex Sennaar, et Arioch rex Ponti, et Chodorlahomor rex Elamitarum, et Thadal rex gentium');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'inirent bellum contra Bara regem Sodomorum, et contra Bersa regem Gomorrhæ, et contra Sennaab regem Adamæ, et contra Semeber regem Seboim, contraque regem Balæ, ipsa est Segor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Omnes hi convenerunt in vallem Silvestrem, quæ nunc est mare salis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Duodecim enim annis servierunt Chodorlahomor, et tertiodecimo anno recesserunt ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Igitur quartodecimo anno venit Chodorlahomor, et reges qui erant cum eo: percusseruntque Raphaim in Astarothcarnaim, et Zuzim cum eis, et Emim in Save Cariathaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'et Chorræos in montibus Seir, usque ad Campestria Pharan, quæ est in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Reversique sunt, et venerunt ad fontem Misphat, ipsa est Cades: et percusserunt omnem regionem Amalecitarum, et Amorrhæum, qui habitabat in Asasonthamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Et egressi sunt rex Sodomorum, et rex Gomorrhæ, rexque Adamæ, et rex Seboim, necnon et rex Balæ, quæ est Segor: et direxerunt aciem contra eos in valle Silvestri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'scilicet adversus Chodorlahomor regem Elamitarum, et Thadal regem Gentium, et Amraphel regem Sennaar, et Arioch regem Ponti: quatuor reges adversus quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Vallis autem Silvestris habebat puteos multos bituminis. Itaque rex Sodomorum, et Gomorrhæ, terga verterunt, cecideruntque ibi: et qui remanserant, fugerunt ad montem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Tulerunt autem omnem substantiam Sodomorum et Gomorrhæ, et universa quæ ad cibum pertinent, et abierunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'necnon et Lot, et substantiam ejus, filium fratris Abram, qui habitabat in Sodomis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Et ecce unus, qui evaserat, nuntiavit Abram Hebræo, qui habitabat in convalle Mambre Amorrhæi, fratris Escol, et fratris Aner: hi enim pepigerant fœdus cum Abram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Quod cum audisset Abram, captum videlicet Lot fratrem suum, numeravit expeditos vernaculos suos trecentos decem et octo: et persecutus est usque Dan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Et divisis sociis, irruit super eos nocte: percussitque eos, et persecutus est eos usque Hoba, quæ est ad lævam Damasci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Reduxitque omnem substantiam, et Lot fratrem suum cum substantia illius, mulieres quoque et populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Egressus est autem rex Sodomorum in occursum ejus postquam reversus est a cæde Chodorlahomor, et regum qui cum eo erant in valle Save, quæ est vallis regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'At vero Melchisedech rex Salem, proferens panem et vinum, erat enim sacerdos Dei altissimi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'benedixit ei, et ait: Benedictus Abram Deo excelso, qui creavit cælum et terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'et benedictus Deus excelsus, quo protegente, hostes in manibus tuis sunt. Et dedit ei decimas ex omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Dixit autem rex Sodomorum ad Abram: Da mihi animas, cetera tolle tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Qui respondit ei: Levo manum meam ad Dominum Deum excelsum possessorem cæli et terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'quod a filo subtegminis usque ad corigiam caligæ, non accipiam ex omnibus quæ tua sunt, ne dicas: Ego ditavi Abram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'exceptis his, quæ comederunt juvenes, et partibus virorum, qui venerunt mecum, Aner, Escol et Mambre: isti accipient partes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'His itaque transactis, factus est sermo Domini ad Abram per visionem dicens: Noli timere, Abram: ego protector tuus sum, et merces tua magna nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Dixitque Abram: Domine Deus, quid dabis mihi? ego vadam absque liberis, et filius procuratoris domus meæ iste Damascus Eliezer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Addiditque Abram: Mihi autem non dedisti semen, et ecce vernaculus meus, hæres meus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Statimque sermo Domini factus est ad eum, dicens: Non erit hic hæres tuus, sed qui egredietur de utero tuo, ipsum habebis hæredem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Eduxitque eum foras, et ait illi: Suspice cælum, et numera stellas, si potes. Et dixit ei: Sic erit semen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Credidit Abram Deo, et reputatum est illi ad justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Dixitque ad eum: Ego Dominus qui eduxi te de Ur Chaldæorum ut darem tibi terram istam, et possideres eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'At ille ait: Domine Deus, unde scire possum quod possessurus sim eam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Et respondens Dominus: Sume, inquit, mihi vaccam triennem, et capram trimam, et arietem annorum trium, turturem quoque et columbam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Qui tollens universa hæc, divisit ea per medium, et utrasque partes contra se altrinsecus posuit; aves autem non divisit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Descenderuntque volucres super cadavera, et abigebat eas Abram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Cumque sol occumberet, sopor irruit super Abram, et horror magnus et tenebrosus invasit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Dictumque est ad eum: Scito prænoscens quod peregrinum futurum sit semen tuum in terra non sua, et subjicient eos servituti, et affligent quadringentis annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Verumtamen gentem, cui servituri sunt, ego judicabo: et post hæc egredientur cum magna substantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Tu autem ibis ad patres tuos in pace, sepultus in senectute bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Generatione autem quarta revertentur huc: necdum enim completæ sunt iniquitates Amorrhæorum usque ad præsens tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Cum ergo occubuisset sol, facta est caligo tenebrosa, et apparuit clibanus fumans, et lampas ignis transiens inter divisiones illas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'In illo die pepigit Dominus fœdus cum Abram, dicens: Semini tuo dabo terram hanc a fluvio \'gypti usque ad fluvium magnum Euphraten,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Cinæos, et Cenezæos, Cedmonæos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'et Hethæos, et Pherezæos, Raphaim quoque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'et Amorrhæos, et Chananæos, et Gergesæos, et Jebusæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Igitur Sarai, uxor Abram, non genuerat liberos: sed habens ancillam ægyptiam nomine Agar,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'dixit marito suo: Ecce, conclusit me Dominus, ne parerem. Ingredere ad ancillam meam, si forte saltem ex illa suscipiam filios. Cumque ille acquiesceret deprecanti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'tulit Agar ægyptiam ancillam suam post annos decem quam habitare cœperant in terra Chanaan: et dedit eam viro suo uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Qui ingressus est ad eam. At illa concepisse se videns, despexit dominam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Dixitque Sarai ad Abram: Inique agis contra me: ego dedi ancillam meam in sinum tuum, quæ videns quod conceperit, despectui me habet: judicet Dominus inter me et te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Cui respondens Abram: Ecce, ait, ancilla tua in manu tua est, utere ea ut libet. Affligente igitur eam Sarai, fugam iniit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Cumque invenisset eam angelus Domini juxta fontem aquæ in solitudine, qui est in via Sur in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'dixit ad illam: Agar ancilla Sarai, unde venis? et quo vadis? Quæ respondit: A facie Sarai dominæ meæ ego fugio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Dixitque ei angelus Domini: Revertere ad dominam tuam, et humiliare sub manu illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Et rursum: Multiplicans, inquit, multiplicabo semen tuum, et non numerabitur præ multitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Ac deinceps: Ecce, ait, concepisti, et paries filium: vocabisque nomen ejus Ismaël, eo quod audierit Dominus afflictionem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Hic erit ferus homo: manus ejus contra omnes, et manus omnium contra eum: et e regione universorum fratrum suorum figet tabernacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Vocavit autem nomen Domini qui loquebatur ad eam: Tu Deus qui vidisti me. Dixit enim: Profecto hic vidi posteriora videntis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Propterea appellavit puteum illum Puteum viventis et videntis me. Ipse est inter Cades et Barad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Peperitque Agar Abræ filium: qui vocavit nomen ejus Ismaël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Octoginta et sex annorum erat Abram quando peperit ei Agar Ismaëlem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Postquam vero nonaginta et novem annorum esse cœperat, apparuit ei Dominus, dixitque ad eum: Ego Deus omnipotens: ambula coram me, et esto perfectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ponamque fœdus meum inter me et te, et multiplicabo te vehementer nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Cecidit Abram pronus in faciem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Dixitque ei Deus: Ego sum, et pactum meum tecum, erisque pater multarum gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Nec ultra vocabitur nomen tuum Abram, sed appellaberis Abraham: quia patrem multarum gentium constitui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Faciamque te crescere vehementissime, et ponam te in gentibus, regesque ex te egredientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Et statuam pactum meum inter me et te, et inter semen tuum post te in generationibus suis, fœdere sempiterno: ut sim Deus tuus, et seminis tui post te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Daboque tibi et semini tuo terram peregrinationis tuæ, omnem terram Chanaan in possessionem æternam, eroque Deus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Dixit iterum Deus ad Abraham: Et tu ergo custodies pactum meum, et semen tuum post te in generationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Hoc est pactum meum quod observabitis inter me et vos, et semen tuum post te: circumcidetur ex vobis omne masculinum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'et circumcidetis carnem præputii vestri, ut sit in signum fœderis inter me et vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Infans octo dierum circumcidetur in vobis, omne masculinum in generationibus vestris: tam vernaculus, quam emptitius circumcidetur, et quicumque non fuerit de stirpe vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'eritque pactum meum in carne vestra in fœdus æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Masculus, cujus præputii caro circumcisa non fuerit, delebitur anima illa de populo suo: quia pactum meum irritum fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dixit quoque Deus ad Abraham: Sarai uxorem tuam non vocabis Sarai, sed Saram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Et benedicam ei, et ex illa dabo tibi filium cui benedicturus sum: eritque in nationes, et reges populorum orientur ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Cecidit Abraham in faciem suam, et risit, dicens in corde suo: Putasne centenario nascetur filius? et Sara nonagenaria pariet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Dixitque ad Deum: Utinam Ismaël vivat coram te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Et ait Deus ad Abraham: Sara uxor tua pariet tibi filium, vocabisque nomen ejus Isaac, et constituam pactum meum illi in fœdus sempiternum, et semini ejus post eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Super Ismaël quoque exaudivi te: ecce, benedicam ei, et augebo, et multiplicabo eum valde: duodecim duces generabit, et faciam illum in gentem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Pactum vero meum statuam ad Isaac, quem pariet tibi Sara tempore isto in anno altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Cumque finitus esset sermo loquentis cum eo, ascendit Deus ab Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Tulit autem Abraham Ismaël filium suum, et omnes vernaculos domus suæ, universosque quos emerat, cunctos mares ex omnibus viris domus suæ: et circumcidit carnem præputii eorum statim in ipsa die, sicut præceperat ei Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham nonaginta et novem erat annorum quando circumcidit carnem præputii sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Et Ismaël filius tredecim annos impleverat tempore circumcisionis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Eadem die circumcisus est Abraham et Ismaël filius ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'et omnes viri domus illius, tam vernaculi, quam emptitii et alienigenæ pariter circumcisi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Apparuit autem ei Dominus in convalle Mambre sedenti in ostio tabernaculi sui in ipso fervore diei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Cumque elevasset oculos, apparuerunt ei tres viri stantes prope eum: quos cum vidisset, cucurrit in occursum eorum de ostio tabernaculi, et adoravit in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Et dixit: Domine, si inveni gratiam in oculis tuis, ne transeas servum tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'sed afferam pauxillum aquæ, et lavate pedes vestros, et requiescite sub arbore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Ponamque buccellam panis, et confortate cor vestrum: postea transibitis: idcirco enim declinastis ad servum vestrum. Qui dixerunt: Fac ut locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Festinavit Abraham in tabernaculum ad Saram, dixitque ei: Accelera, tria sata similæ commisce, et fac subcinericios panes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Ipse vero ad armentum cucurrit, et tulit inde vitulum tenerrimum et optimum, deditque puero: qui festinavit et coxit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Tulit quoque butyrum et lac, et vitulum quem coxerat, et posuit coram eis: ipse vero stabat juxta eos sub arbore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Cumque comedissent, dixerunt ad eum: Ubi est Sara uxor tua? Ille respondit: Ecce in tabernaculo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Cui dixit: Revertens veniam ad te tempore isto, vita comite, et habebit filium Sara uxor tua. Quo audito, Sara risit post ostium tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Erant autem ambo senes, provectæque ætatis, et desierant Saræ fieri muliebria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Quæ risit occulte dicens: Postquam consenui, et dominus meus vetulus est, voluptati operam dabo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Dixit autem Dominus ad Abraham: Quare risit Sara, dicens: Num vere paritura sum anus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Numquid Deo quidquam est difficile? juxta condictum revertar ad te hoc eodem tempore, vita comite, et habebit Sara filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Negavit Sara, dicens: Non risi, timore perterrita. Dominus autem: Non est, inquit, ita: sed risisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Cum ergo surrexissent inde viri, direxerunt oculos contra Sodomam: et Abraham simul gradiebatur, deducens eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Dixitque Dominus: Num celare potero Abraham quæ gesturus sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'cum futurus sit in gentem magnam, ac robustissimam, et benedicendæ sint in illo omnes nationes terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Scio enim quod præcepturus sit filiis suis, et domui suæ post se ut custodiant viam Domini, et faciant judicium et justitiam: ut adducat Dominus propter Abraham omnia quæ locutus est ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Dixit itaque Dominus: Clamor Sodomorum et Gomorrhæ multiplicatus est, et peccatum eorum aggravatum est nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Descendam, et videbo utrum clamorem qui venit ad me, opere compleverint; an non est ita, ut sciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Converteruntque se inde, et abierunt Sodomam: Abraham vero adhuc stabat coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Et appropinquans ait: Numquid perdes justum cum impio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'si fuerint quinquaginta justi in civitate, peribunt simul? et non parces loco illi propter quinquaginta justos, si fuerint in eo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Absit a te ut rem hanc facias, et occidas justum cum impio, fiatque justus sicut impius, non est hoc tuum: qui judicas omnem terram, nequaquam facies judicium hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Dixitque Dominus ad eum: Si invenero Sodomis quinquaginta justos in medio civitatis, dimittam omni loco propter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Respondensque Abraham, ait: Quia semel cœpi, loquar ad Dominum meum, cum sim pulvis et cinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Quid si minus quinquaginta justis quinque fuerint? delebis, propter quadraginta quinque, universam urbem? Et ait: Non delebo, si invenero ibi quadraginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Rursumque locutus est ad eum: Sin autem quadraginta ibi inventi fuerint, quid facies? Ait: Non percutiam propter quadraginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Ne quæso, inquit, indigneris, Domine, si loquar: quid si ibi inventi fuerint triginta? Respondit: Non faciam, si invenero ibi triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Quia semel, ait, cœpi loquar ad Dominum meum: quid si ibi inventi fuerint viginti? Ait: Non interficiam propter viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Obsecro, inquit, ne irascaris, Domine, si loquar adhuc semel: quid si inventi fuerint ibi decem? Et dixit: Non delebo propter decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Abiitque Dominus, postquam cessavit loqui ad Abraham: et ille reversus est in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Veneruntque duo angeli Sodomam vespere, et sedente Lot in foribus civitatis. Qui cum vidisset eos, surrexit, et ivit obviam eis: adoravitque pronus in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'et dixit: Obsecro, domini, declinate in domum pueri vestri, et manete ibi: lavate pedes vestros, et mane proficiscemini in viam vestram. Qui dixerunt: Minime, sed in platea manebimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Compulit illos oppido ut diverterent ad eum: ingressisque domum illius fecit convivium, et coxit azyma, et comederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Prius autem quam irent cubitum, viri civitatis vallaverunt domum a puero usque ad senem, omnis populus simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Vocaveruntque Lot, et dixerunt ei: Ubi sunt viri qui introierunt ad te nocte? educ illos huc, ut cognoscamus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Egressus ad eos Lot, post tergum occludens ostium, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Nolite, quæso, fratres mei, nolite malum hoc facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Habeo duas filias, quæ necdum cognoverunt virum: educam eas ad vos, et abutimini eis sicut vobis placuerit, dummodo viris istis nihil mali faciatis, quia ingressi sunt sub umbra culminis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'At illi dixerunt: Recede illuc. Et rursus: Ingressus es, inquiunt, ut advena; numquid ut judices? te ergo ipsum magis quam hos affligemus. Vimque faciebant Lot vehementissime: jamque prope erat ut effringerent fores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Et ecce miserunt manum viri, et introduxerunt ad se Lot, clauseruntque ostium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'et eos, qui foris erant, percusserunt cæcitate a minimo usque ad maximum, ita ut ostium invenire non possent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Dixerunt autem ad Lot: Habes hic quempiam tuorum? generum, aut filios, aut filias, omnes, qui tui sunt, educ de urbe hac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'delebimus enim locum istum, eo quod increverit clamor eorum coram Domino, qui misit nos ut perdamus illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Egressus itaque Lot, locutus est ad generos suos qui accepturi erant filias ejus, et dixit: Surgite, egredimini de loco isto: quia delebit Dominus civitatem hanc. Et visus est eis quasi ludens loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Cumque esset mane, cogebant eum angeli, dicentes: Surge, tolle uxorem tuam, et duas filias quas habes: ne et tu pariter pereas in scelere civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Dissimulante illo, apprehenderunt manum ejus, et manum uxoris, ac duarum filiarum ejus, eo quod parceret Dominus illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Eduxeruntque eum, et posuerunt extra civitatem: ibique locuti sunt ad eum, dicentes: Salva animam tuam: noli respicere post tergum, nec stes in omni circa regione: sed in monte salvum te fac, ne et tu simul pereas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Dixitque Lot ad eos: Quæso, domine mi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'quia invenit servus tuus gratiam coram te, et magnificasti misericordiam tuam quam fecisti mecum, ut salvares animam meam, nec possum in monte salvari, ne forte apprehendat me malum, et moriar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'est civitas hæc juxta, ad quam possum fugere, parva, et salvabor in ea: numquid non modica est, et vivet anima mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Dixitque ad eum: Ecce etiam in hoc suscepi preces tuas, ut non subvertam urbem pro qua locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Festina, et salvare ibi: quia non potero facere quidquam donec ingrediaris illuc. Idcirco vocatum est nomen urbis illius Segor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Sol egressus est super terram, et Lot ingressus est Segor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Igitur Dominus pluit super Sodomam et Gomorrham sulphur et ignem a Domino de cælo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'et subvertit civitates has, et omnem circa regionem, universos habitatores urbium, et cuncta terræ virentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Respiciensque uxor ejus post se, versa est in statuam salis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham autem consurgens mane, ubi steterat prius cum Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'intuitus est Sodomam et Gomorrham, et universam terram regionis illius: viditque ascendentem favillam de terra quasi fornacis fumum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Cum enim subverteret Deus civitates regionis illius, recordatus Abrahæ, liberavit Lot de subversione urbium in quibus habitaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Ascenditque Lot de Segor, et mansit in monte, duæ quoque filiæ ejus cum eo (timuerat enim manere in Segor) et mansit in spelunca ipse, et duæ filiæ ejus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Dixitque major ad minorem: Pater noster senex est, et nullus virorum remansit in terra, qui possit ingredi ad nos juxta morem universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Veni, inebriemus eum vino, dormiamusque cum eo, ut servare possimus ex patre nostro semen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Dederunt itaque patri suo bibere vinum nocte illa. Et ingressa est major, dormivitque cum patre; at ille non sensit, nec quando accubuit filia, nec quando surrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Altera quoque die dixit major ad minorem: Ecce dormivi heri cum patre meo, demus ei bibere vinum etiam hac nocte, et dormies cum eo, ut salvemus semen de patre nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Dederunt etiam et illa nocte patri suo bibere vinum, ingressaque minor filia, dormivit cum eo: et ne tunc quidem sensit quando concubuerit, vel quando illa surrexerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Conceperunt ergo duæ filiæ Lot de patre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Peperitque major filium, et vocavit nomen ejus Moab: ipse est pater Moabitarum usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Minor quoque peperit filium, et vocavit nomen ejus Ammon, id est, Filius populi mei: ipse est pater Ammonitarum usque hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Profectus inde Abraham in terram australem, habitavit inter Cades et Sur: et peregrinatus est in Geraris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Dixitque de Sara uxore suo: Soror mea est. Misit ergo Abimelech rex Geraræ, et tulit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Venit autem Deus ad Abimelech per somnium nocte, et ait illi: En morieris propter mulierem quam tulisti: habet enim virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech vero non tetigerat eam, et ait: Domine, num gentem ignorantem et justam interficies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'nonne ipse dixit mihi: Soror mea est: et ipsa ait: Frater meus est? In simplicitate cordis mei, et munditia manuum mearum feci hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Dixitque ad eum Deus: Et ego scio quod simplici corde feceris: et ideo custodivi te ne peccares in me, et non dimisi ut tangeres eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Nunc ergo redde viro suo uxorem, quia propheta est: et orabit pro te, et vives: si autem nolueris reddere, scito quod morte morieris tu, et omnia quæ tua sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Statimque de nocte consurgens Abimelech, vocavit omnes servos suos: et locutus est universa verba hæc in auribus eorum, timueruntque omnes viri valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Vocavit autem Abimelech etiam Abraham, et dixit ei: Quid fecisti nobis? quid peccavimus in te, quia induxisti super me et super regnum meum peccatum grande? quæ non debuisti facere, fecisti nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Rursumque expostulans, ait: Quid vidisti, ut hoc faceres?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Respondit Abraham: Cogitavi mecum, dicens: Forsitan non est timor Dei in loco isto: et interficient me propter uxorem meam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'alias autem et vere soror mea est, filia patris mei, et non filia matris meæ, et duxi eam in uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Postquam autem eduxit me Deus de domo patris mei, dixi ad eam: Hanc misericordiam facies mecum: in omni loco, ad quem ingrediemur, dices quod frater tuus sim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Tulit igitur Abimelech oves et boves, et servos et ancillas, et dedit Abraham: reddiditque illi Saram uxorem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'et ait: Terra coram vobis est, ubicumque tibi placuerit habita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Saræ autem dixit: Ecce mille argenteos dedi fratri tuo, hoc erit tibi in velamen oculorum ad omnes qui tecum sunt, et quocumque perrexeris: mementoque te deprehensam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Orante autem Abraham, sanavit Deus Abimelech et uxorem, ancillasque ejus, et pepererunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'concluserat enim Dominus omnem vulvam domus Abimelech propter Saram uxorem Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Visitavit autem Dominus Saram, sicut promiserat: et implevit quæ locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Concepitque et peperit filium in senectute sua, tempore quo prædixerat ei Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Vocavitque Abraham nomen filii sui, quem genuit ei Sara, Isaac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'et circumcidit eum octavo die, sicut præceperat ei Deus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'cum centum esset annorum: hac quippe ætate patris, natus est Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Dixitque Sara: Risum fecit mihi Deus: quicumque audierit, corridebit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Rursumque ait: Quis auditurus crederet Abraham quod Sara lactaret filium, quem peperit ei jam seni?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Crevit igitur puer, et ablactatus est: fecitque Abraham grande convivium in die ablactationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Cumque vidisset Sara filium Agar \'gyptiæ ludentem cum Isaac filio suo, dixit ad Abraham:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Ejice ancillam hanc, et filium ejus: non enim erit hæres filius ancillæ cum filio meo Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dure accepit hoc Abraham pro filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Cui dixit Deus: Non tibi videatur asperum super puero, et super ancilla tua: omnia quæ dixerit tibi Sara, audi vocem ejus: quia in Isaac vocabitur tibi semen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Sed et filium ancillæ faciam in gentem magnam, quia semen tuum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Surrexit itaque Abraham mane, et tollens panem et utrem aquæ, imposuit scapulæ ejus, tradiditque puerum, et dimisit eam. Quæ cum abiisset, errabat in solitudine Bersabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Cumque consumpta esset aqua in utre, abjecit puerum subter unam arborum, quæ ibi erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Et abiit, seditque e regione procul quantum potest arcus jacere: dixit enim: Non videbo morientem puerum: et sedens contra, levavit vocem suam et flevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Exaudivit autem Deus vocem pueri: vocavitque angelus Dei Agar de cælo, dicens: Quid agis Agar? noli timere: exaudivit enim Deus vocem pueri de loco in quo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Surge, tolle puerum, et tene manum illius: quia in gentem magnam faciam eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Aperuitque oculos ejus Deus: quæ videns puteum aquæ, abiit, et implevit utrem, deditque puero bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Et fuit cum eo: qui crevit, et moratus est in solitudine, factusque est juvenis sagittarius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Habitavitque in deserto Pharan, et accepit illi mater sua uxorem de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Eodem tempore dixit Abimelech, et Phicol princeps exercitus ejus, ad Abraham: Deus tecum est in universis quæ agis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Jura ergo per Deum, ne noceas mihi, et posteris meis, stirpique meæ: sed juxta misericordiam, quam feci tibi, facies mihi, et terræ in qua versatus es advena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Dixitque Abraham: Ego jurabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Et increpavit Abimelech propter puteum aquæ quem vi abstulerunt servi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Responditque Abimelech: Nescivi quis fecerit hanc rem: sed et tu non indicasti mihi, et ego non audivi præter hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Tulit itaque Abraham oves et boves, et dedit Abimelech: percusseruntque ambo fœdus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Et statuit Abraham septem agnas gregis seorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Cui dixit Abimelech: Quid sibi volunt septem agnæ istæ, quas stare fecisti seorsum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'At ille: Septem, inquit, agnas accipies de manu mea: ut sint mihi in testimonium, quoniam ego fodi puteum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Idcirco vocatus est locus ille Bersabee: quia ibi uterque juravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Et inierunt fœdus pro puteo juramenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Surrexit autem Abimelech, et Phicol princeps exercitus ejus, reversique sunt in terram Palæstinorum. Abraham vero plantavit nemus in Bersabee, et invocavit ibi nomen Domini Dei æterni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et fuit colonus terræ Palæstinorum diebus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Quæ postquam gesta sunt, tentavit Deus Abraham, et dixit ad eum: Abraham, Abraham. At ille respondit: Adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Ait illi: Tolle filium tuum unigenitum, quem diligis, Isaac, et vade in terram visionis, atque ibi offeres eum in holocaustum super unum montium quem monstravero tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Igitur Abraham de nocte consurgens, stravit asinum suum, ducens secum duos juvenes, et Isaac filium suum: cumque concidisset ligna in holocaustum, abiit ad locum quem præceperat ei Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Die autem tertio, elevatis oculis, vidit locum procul:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'dixitque ad pueros suos: Expectate hic cum asino: ego et puer illuc usque properantes, postquam adoraverimus, revertemur ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Tulit quoque ligna holocausti, et imposuit super Isaac filium suum: ipse vero portabat in manibus ignem et gladium. Cumque duo pergerent simul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'dixit Isaac patri suo: Pater mi. At ille respondit: Quid vis, fili? Ecce, inquit, ignis et ligna: ubi est victima holocausti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Dixit autem Abraham: Deus providebit sibi victimam holocausti, fili mi. Pergebant ergo pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Et venerunt ad locum quem ostenderat ei Deus, in quo ædificavit altare, et desuper ligna composuit; cumque alligasset Isaac filium suum, posuit eum in altare super struem lignorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Extenditque manum, et arripuit gladium, ut immolaret filium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Et ecce angelus Domini de cælo clamavit, dicens: Abraham, Abraham. Qui respondit: Adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Dixitque ei: Non extendas manum tuam super puerum, neque facias illi quidquam: nunc cognovi quod times Deum, et non pepercisti unigenito filio tuo propter me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Levavit Abraham oculos suos, viditque post tergum arietem inter vepres hærentem cornibus, quem assumens obtulit holocaustum pro filio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Appellavitque nomen loci illius, Dominus videt. Unde usque hodie dicitur: In monte Dominus videbit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Vocavit autem angelus Domini Abraham secundo de cælo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Per memetipsum juravi, dicit Dominus: quia fecisti hanc rem, et non pepercisti filio tuo unigenito propter me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'benedicam tibi, et multiplicabo semen tuum sicut stellas cæli, et velut arenam quæ est in littore maris: possidebit semen tuum portas inimicorum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'et benedicentur in semine tuo omnes gentes terræ, quia obedisti voci meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Reversus est Abraham ad pueros suos, abieruntque Bersabee simul, et habitavit ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'His ita gestis, nuntiatum est Abrahæ quod Melcha quoque genuisset filios Nachor fratri suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Hus primogenitum, et Buz fratrem ejus, et Camuel patrem Syrorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'et Cased, et Azau, Pheldas quoque et Jedlaph,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'ac Bathuel, de quo nata est Rebecca: octo istos genuit Melcha, Nachor fratri Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Concubina vero illius, nomine Roma, peperit Tabee, et Gaham, et Thahas, et Maacha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Vixit autem Sara centum viginti septem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Et mortua est in civitate Arbee, quæ est Hebron, in terra Chanaan: venitque Abraham ut plangeret et fleret eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Cumque surrexisset ab officio funeris, locutus est ad filios Heth, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Advena sum et peregrinus apud vos: date mihi jus sepulchri vobiscum, ut sepeliam mortuum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Responderunt filii Heth, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Audi nos, domine: princeps Dei es apud nos: in electis sepulchris nostris sepeli mortuum tuum, nullusque te prohibere poterit quin in monumento ejus sepelias mortuum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Surrexit Abraham, et adoravit populum terræ, filios videlicet Heth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'dixitque ad eos: Si placet animæ vestræ ut sepeliam mortuum meum, audite me, et intercedite pro me apud Ephron filium Seor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'ut det mihi speluncam duplicem, quam habet in extrema parte agri sui: pecunia digna tradat eam mihi coram vobis in possessionem sepulchri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Habitabat autem Ephron in medio filiorum Heth. Responditque Ephron ad Abraham, cunctis audientibus qui ingrediebantur portam civitatis illius, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nequaquam ita fiat, domine mi, sed tu magis ausculta quod loquor. Agrum trado tibi, et speluncam quæ in eo est, præsentibus filiis populi mei; sepeli mortuum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Adoravit Abraham coram populo terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Et locutus est ad Ephron circumstante plebe: Quæso ut audias me: dabo pecuniam pro agro: suscipe eam, et sic sepeliam mortuum meum in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Responditque Ephron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Domine mi, audi me: terra, quam postulas, quadringentis siclis argenti valet: istud est pretium inter me et te: sed quantum est hoc? sepeli mortuum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Quod cum audisset Abraham, appendit pecuniam, quam Ephron postulaverat, audientibus filiis Heth, quadringentos siclos argenti probatæ monetæ publicæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Confirmatusque est ager quondam Ephronis, in quo erat spelunca duplex, respiciens Mambre, tam ipse, quam spelunca, et omnes arbores ejus in cunctis terminis ejus per circuitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abrahæ in possessionem, videntibus filiis Heth, et cunctis qui intrabant portam civitatis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Atque ita sepelivit Abraham Saram uxorem suam in spelunca agri duplici, quæ respiciebat Mambre. Hæc est Hebron in terra Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Et confirmatus est ager, et antrum quod erat in eo, Abrahæ in possessionem monumenti a filiis Heth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Erat autem Abraham senex, dierumque multorum: et Dominus in cunctis benedixerat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Dixitque ad servum seniorem domus suæ, qui præerat omnibus quæ habebat: Pone manum tuam subter femur meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'ut adjurem te per Dominum Deum cæli et terræ, ut non accipias uxorem filio meo de filiabus Chananæorum, inter quos habito:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sed ad terram et cognationem meam proficiscaris et inde accipias uxorem filio meo Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Respondit servus: Si noluerit mulier venire mecum in terram hanc, numquid reducere debeo filium tuum ad locum, de quo egressus es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Dixitque Abraham: Cave nequando reducas filium meum illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Dominus Deus cæli, qui tulit me de domo patris mei, et de terra nativitatis meæ, qui locutus est mihi, et juravit mihi, dicens: Semini tuo dabo terram hanc: ipse mittet angelum suum coram te, et accipies inde uxorem filio meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'sin autem mulier noluerit sequi te, non teneberis juramento: filium meum tantum ne reducas illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Posuit ergo servus manum sub femore Abraham domini sui, et juravit illi super sermone hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Tulitque decem camelos de grege domini sui, et abiit, ex omnibus bonis ejus portans secum, profectusque perrexit in Mesopotamiam ad urbem Nachor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Cumque camelos fecisset accumbere extra oppidum juxta puteum aquæ vespere, tempore quo solent mulieres egredi ad hauriendam aquam, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Domine Deus domini mei Abraham, occurre, obsecro, mihi hodie, et fac misericordiam cum domino meo Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Ecce ego sto prope fontem aquæ, et filiæ habitatorum hujus civitatis egredientur ad hauriendam aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Igitur puella, cui ego dixero: Inclina hydriam tuam ut bibam: et illa responderit: Bibe, quin et camelis tuis dabo potum: ipsa est quam præparasti servo tuo Isaac: et per hoc intelligam quod feceris misericordiam cum domino meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Necdum intra se verba compleverat, et ecce Rebecca egrediebatur, filia Bathuel, filii Melchæ uxoris Nachor fratris Abraham, habens hydriam in scapula sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'puella decora nimis, virgoque pulcherrima, et incognita viro: descenderat autem ad fontem, et impleverat hydriam, ac revertebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Occurritque ei servus, et ait: Pauxillum aquæ mihi ad bibendum præbe de hydria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Quæ respondit: Bibe, domine mi: celeriterque deposuit hydriam super ulnam suam, et dedit ei potum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Cumque ille bibisset, adjecit: Quin et camelis tuis hauriam aquam, donec cuncti bibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Effundensque hydriam in canalibus, recurrit ad puteum ut hauriret aquam: et haustam omnibus camelis dedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Ipse autem contemplabatur eam tacitus, scire volens utrum prosperum iter suum fecisset Dominus, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Postquam autem biberunt cameli, protulit vir inaures aureas, appendentes siclos duos, et armillas totidem pondo siclorum decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Dixitque ad eam: Cujus es filia? indica mihi, est in domo patris tui locus ad manendum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Quæ respondit: Filia sum Bathuelis, filii Melchæ, quem peperit ipsi Nachor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Et addidit, dicens: Palearum quoque et fœni plurimum est apud nos, et locus spatiosus ad manendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Inclinavit se homo, et adoravit Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'dicens: Benedictus Dominus Deus domini mei Abraham, qui non abstulit misericordiam et veritatem suam a domino meo, et recto itinere me perduxit in domum fratris domini mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Cucurrit itaque puella, et nuntiavit in domum matris suæ omnia quæ audierat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Habebat autem Rebecca fratrem nomine Laban, qui festinus egressus est ad hominem, ubi erat fons.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Cumque vidisset inaures et armillas in manibus sororis suæ, et audisset cuncta verba referentis: Hæc locutus est mihi homo: venit ad virum qui stabat juxta camelos, et prope fontem aquæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'dixitque ad eum: Ingredere, benedicte Domini: cur foris stas? præparavi domum, et locum camelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Et introduxit eum in hospitium: ac destravit camelos, deditque paleas et fœnum, et aquam ad lavandos pedes ejus, et virorum qui venerant cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Et appositus est in conspectu ejus panis. Qui ait: Non comedam, donec loquar sermones meos. Respondit ei: Loquere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'At ille: Servus, inquit, Abraham sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'et Dominus benedixit domino meo valde, magnificatusque est: et dedit ei oves et boves, argentum et aurum, servos et ancillas, camelos et asinos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Et peperit Sara uxor domini mei filium domino meo in senectute sua, deditque illi omnia quæ habuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et adjuravit me dominus meus, dicens: Non accipies uxorem filio meo de filiabus Chananæorum, in quorum terra habito:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sed ad domum patris mei perges, et de cognatione mea accipies uxorem filio meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ego vero respondi domino meo: Quid si noluerit venire mecum mulier?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Dominus, ait, in cujus conspectu ambulo, mittet angelum suum tecum, et diriget viam tuam: accipiesque uxorem filio meo de cognatione mea, et de domo patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Innocens eris a maledictione mea, cum veneris ad propinquos meos, et non dederint tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Veni ergo hodie ad fontem aquæ, et dixi: Domine Deus domini mei Abraham, si direxisti viam meam, in qua nunc ambulo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ecce sto juxta fontem aquæ, et virgo, quæ egredietur ad hauriendam aquam, audierit a me: Da mihi pauxillum aquæ ad bibendum ex hydria tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'et dixerit mihi: Et tu bibe, et camelis tuis hauriam: ipsa est mulier, quam præparavit Dominus filio domini mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Dumque hæc tacitus mecum volverem, apparuit Rebecca veniens cum hydria, quam portabat in scapula: descenditque ad fontem, et hausit aquam. Et aio ad eam: Da mihi paululum bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Quæ festinans deposuit hydriam de humero, et dixit mihi: Et tu bibe, et camelis tuis tribuam potum. Bibi, et adaquavit camelos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Interrogavique eam, et dixi: Cujus es filia? Quæ respondit: Filia Bathuelis sum, filii Nachor, quem peperit ei Melcha. Suspendi itaque inaures ad ornandam faciem ejus, et armillas posui in manibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Pronusque adoravi Dominum, benedicens Domino Deo domini mei Abraham, qui perduxit me recto itinere, ut sumerem filiam fratris domini mei filio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Quam ob rem si facitis misericordiam et veritatem cum domino meo, indicate mihi: sin autem aliud placet, et hoc dicite mihi, ut vadam ad dextram, sive ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Responderuntque Laban et Bathuel: A Domino egressus est sermo: non possumus extra placitum ejus quidquam aliud loqui tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'En Rebecca coram te est, tolle eam, et proficiscere, et sit uxor filii domini tui, sicut locutus est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Quod cum audisset puer Abraham, procidens adoravit in terram Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Prolatisque vasis argenteis, et aureis, ac vestibus, dedit ea Rebeccæ pro munere: fratribus quoque ejus et matri dona obtulit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Inito convivio, vescentes pariter et bibentes manserunt ibi. Surgens autem mane, locutus est puer: Dimitte me, ut vadam ad dominum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Responderuntque fratres ejus et mater: Maneat puella saltem decem dies apud nos, et postea proficiscetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Nolite, ait, me retinere, quia Dominus direxit viam meam: dimittite me ut pergam ad dominum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Et dixerunt: Vocemus puellam, et quæramus ipsius voluntatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Cumque vocata venisset, sciscitati sunt: Vis ire cum homine isto? Quæ ait: Vadam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Dimiserunt ergo eam, et nutricem illius, servumque Abraham, et comites ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'imprecantes prospera sorori suæ, atque dicentes: Soror nostra es, crescas in mille millia, et possideat semen tuum portas inimicorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Igitur Rebecca et puellæ illius, ascensis camelis, secutæ sunt virum: qui festinus revertebatur ad dominum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Eo autem tempore deambulabat Isaac per viam quæ ducit ad puteum, cujus nomen est Viventis et videntis: habitabat enim in terra australi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'et egressus fuerat ad meditandum in agro, inclinata jam die: cumque elevasset oculos, vidit camelos venientes procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebecca quoque, conspecto Isaac, descendit de camelo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'et ait ad puerum: Quis est ille homo qui venit per agrum in occursum nobis? Dixitque ei: Ipse est dominus meus. At illa tollens cito pallium, operuit se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Servus autem cuncta, quæ gesserat, narravit Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Qui introduxit eam in tabernaculum Saræ matris suæ, et accepit eam uxorem: et in tantum dilexit eam, ut dolorem, qui ex morte matris ejus acciderat, temperaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham vero aliam duxit uxorem nomine Ceturam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'quæ peperit ei Zamran et Jecsan, et Madan, et Madian, et Jesboc, et Sue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jecsan quoque genuit Saba et Dadan. Filii Dadan fuerunt Assurim, et Latusim, et Loomin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'At vero ex Madian ortus est Epha, et Opher, et Henoch, et Abida, et Eldaa: omnes hi filii Ceturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Deditque Abraham cuncta quæ possederat, Isaac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'filiis autem concubinarum largitus est munera, et separavit eos ab Isaac filio suo, dum adhuc ipse viveret, ad plagam orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Fuerunt autem dies vitæ Abrahæ, centum septuaginta quinque anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Et deficiens mortuus est in senectute bona, provectæque ætatis et plenus dierum: congregatusque est ad populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Et sepelierunt eum Isaac et Ismaël filii sui in spelunca duplici, quæ sita est in agro Ephron filii Seor Hethæi, e regione Mambre,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'quem emerat a filiis Heth: ibi sepultus est ipse, et Sara uxor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Et post obitum illius benedixit Deus Isaac filio ejus, qui habitabat juxta puteum nomine Viventis et videntis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Hæ sunt generationes Ismaël filii Abrahæ, quem peperit ei Agar \'gyptia, famula Saræ: et');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'hæc nomina filiorum ejus in vocabulis et generationibus suis. Primogenitus Ismaëlis Nabaioth, deinde Cedar, et Adbeel, et Mabsam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Masma quoque, et Duma, et Massa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, et Thema, et Jethur, et Naphis, et Cedma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Isti sunt filii Ismaëlis: et hæc nomina per castella et oppida eorum, duodecim principes tribuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Et facti sunt anni vitæ Ismaëlis centum triginta septem, deficiensque mortuus est, et appositus ad populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Habitavit autem ab Hevila usque Sur, quæ respicit \'gyptum introëuntibus Assyrios; coram cunctis fratribus suis obiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Hæ quoque sunt generationes Isaac filii Abraham: Abraham genuit Isaac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'qui cum quadraginta esset annorum, duxit uxorem Rebeccam filiam Bathuelis Syri de Mesopotamia, sororem Laban.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Deprecatusque est Isaac Dominum pro uxore sua, eo quod esset sterilis: qui exaudivit eum, et dedit conceptum Rebeccæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Sed collidebantur in utero ejus parvuli; quæ ait: Si sic mihi futurum erat, quid necesse fuit concipere? perrexitque ut consuleret Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Qui respondens ait: Duæ gentes sunt in utero tuo, et duo populi ex ventre tuo dividentur, populusque populum superabit, et major serviet minori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Jam tempus pariendi advenerat, et ecce gemini in utero ejus reperti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Qui prior egressus est, rufus erat, et totus in morem pellis hispidus: vocatumque est nomen ejus Esau. Protinus alter egrediens, plantam fratris tenebat manu: et idcirco appellavit eum Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Sexagenarius erat Isaac quando nati sunt ei parvuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Quibus adultis, factus est Esau vir gnarus venandi, et homo agricola: Jacob autem vir simplex habitabat in tabernaculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaac amabat Esau, eo quod de venationibus illius vesceretur: et Rebecca diligebat Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Coxit autem Jacob pulmentum: ad quem cum venisset Esau de agro lassus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'ait: Da mihi de coctione hac rufa, quia oppido lassus sum. Quam ob causam vocatum est nomen ejus Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Cui dixit Jacob: Vende mihi primogenita tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ille respondit: En morior, quid mihi proderunt primogenita?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Ait Jacob: Jura ergo mihi. Juravit ei Esau et vendidit primogenita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Et sic, accepto pane et lentis edulio, comedit et bibit, et abiit, parvipendens quod primogenita vendidisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Orta autem fame super terram post eam sterilitatem, quæ acciderat in diebus Abraham, abiit Isaac ad Abimelech regem Palæstinorum in Gerara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Apparuitque ei Dominus, et ait: Ne descendas in \'gyptum, sed quiesce in terra quam dixero tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'et peregrinare in ea: eroque tecum, et benedicam tibi: tibi enim et semini tuo dabo universas regiones has, complens juramentum quod spopondi Abraham patri tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Et multiplicabo semen tuum sicut stellas cæli: daboque posteris tuis universas regiones has: et benedicentur in semine tuo omnes gentes terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'eo quod obedierit Abraham voci meæ, et custodierit præcepta et mandata mea, et cæremonias legesque servaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Mansit itaque Isaac in Geraris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Qui cum interrogaretur a viris loci illius super uxore sua, respondit: Soror mea est: timuerat enim confiteri quod sibi esset sociata conjugio, reputans ne forte interficerent eum propter illius pulchritudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Cumque pertransissent dies plurimi, et ibidem moraretur, prospiciens Abimelech rex Palæstinorum per fenestram, vidit eum jocantem cum Rebecca uxore sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Et accersito eo, ait: Perspicuum est quod uxor tua sit: cur mentitus es eam sororem tuam esse? Respondit: Timui ne morerer propter eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Dixitque Abimelech: Quare imposuisti nobis? potuit coire quispiam de populo cum uxore tua, et induxeras super nos grande peccatum. Præcepitque omni populo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Qui tetigerit hominis hujus uxorem, morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Sevit autem Isaac in terra illa, et invenit in ipso anno centuplum: benedixitque ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Et locupletatus est homo, et ibat proficiens atque succrescens, donec magnus vehementer effectus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'habuit quoque possessiones ovium et armentorum, et familiæ plurimum. Ob hoc invidentes ei Palæstini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'omnes puteos, quos foderant servi patris illius Abraham, illo tempore obstruxerunt, implentes humo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'in tantum, ut ipse Abimelech diceret ad Isaac: Recede a nobis, quoniam potentior nobis factus es valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Et ille discedens, ut veniret ad torrentem Geraræ, habitaretque ibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'rursum fodit alios puteos, quos foderant servi patris sui Abraham, et quos, illo mortuo, olim obstruxerant Philisthiim: appellavitque eos eisdem nominibus quibus ante pater vocaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Foderuntque in torrente, et repererunt aquam vivam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Sed et ibi jurgium fuit pastorum Geraræ adversus pastores Isaac, dicentium: Nostra est aqua, quam ob rem nomen putei ex eo, quod acciderat, vocavit Calumniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Foderunt autem et alium: et pro illo quoque rixati sunt, appellavitque eum Inimicitias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Profectus inde fodit alium puteum, pro quo non contenderunt: itaque vocavit nomen ejus Latitudo, dicens: Nunc dilatavit nos Dominus, et fecit crescere super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Ascendit autem ex illo loco in Bersabee,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'ubi apparuit ei Dominus in ipsa nocte, dicens: Ego sum Deus Abraham patris tui: noli timere, quia ego tecum sum: benedicam tibi, et multiplicabo semen tuum propter servum meum Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Itaque ædificavit ibi altare: et invocato nomine Domini, extendit tabernaculum, præcepitque servis suis ut foderent puteum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Ad quem locum cum venissent de Geraris Abimelech, et Ochozath amicus illius, et Phicol dux militum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'locutus est eis Isaac: Quid venistis ad me, hominem quem odistis, et expulistis a vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Qui responderunt: Vidimus tecum esse Dominum, et idcirco nos diximus: Sit juramentum inter nos, et ineamus fœdus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ut non facias nobis quidquam mali, sicut et nos nihil tuorum attigimus, nec fecimus quod te læderet: sed cum pace dimisimus auctum benedictione Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Fecit ergo eis convivium, et post cibum et potum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'surgentes mane, juraverunt sibi mutuo: dimisitque eos Isaac pacifice in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Ecce autem venerunt in ipso die servi Isaac annuntiantes ei de puteo, quem foderant, atque dicentes: Invenimus aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Unde appellavit eum Abundantiam: et nomen urbi impositum est Bersabee, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Esau vero quadragenarius duxit uxores, Judith filiam Beeri Hethæi, et Basemath filiam Elon ejusdem loci:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'quæ ambæ offenderant animum Isaac et Rebeccæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Senuit autem Isaac, et caligaverunt oculi ejus, et videre non poterat: vocavitque Esau filium suum majorem, et dixit ei: Fili mi? Qui respondit: Adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Cui pater: Vides, inquit, quod senuerim, et ignorem diem mortis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Sume arma tua, pharetram, et arcum, et egredere foras: cumque venatu aliquid apprehenderis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'fac mihi inde pulmentum sicut velle me nosti, et affer ut comedam: et benedicat tibi anima mea antequam moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Quod cum audisset Rebecca, et ille abiisset in agrum ut jussionem patris impleret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'dixit filio suo Jacob: Audivi patrem tuum loquentem cum Esau fratre tuo, et dicentem ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Affer mihi de venatione tua, et fac cibos ut comedam, et benedicam tibi coram Domino antequam moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Nunc ergo, fili mi, acquiesce consiliis meis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'et pergens ad gregem, affer mihi duos hædos optimos, ut faciam ex eis escas patri tuo, quibus libenter vescitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'quas cum intuleris, et comederit, benedicat tibi priusquam moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Cui ille respondit: Nosti quod Esau frater meus homo pilosus sit, et ego lenis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'si attrectaverit me pater meus, et senserit, timeo ne putet me sibi voluisse illudere, et inducam super me maledictionem pro benedictione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Ad quem mater: In me sit, ait, ista maledictio, fili mi: tantum audi vocem meam, et pergens, affer quæ dixi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Abiit, et attulit, deditque matri. Paravit illa cibos, sicut velle noverat patrem illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Et vestibus Esau valde bonis, quas apud se habebat domi, induit eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'pelliculasque hædorum circumdedit manibus, et colli nuda protexit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'deditque pulmentum, et panes, quos coxerat, tradidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Quibus illatis, dixit: Pater mi? At ille respondit: Audio. Quis es tu, fili mi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Dixitque Jacob: Ego sum primogenitus tuus Esau: feci sicut præcepisti mihi: surge, sede, et comede de venatione mea, ut benedicat mihi anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Rursumque Isaac ad filium suum: Quomodo, inquit, tam cito invenire potuisti, fili mi? Qui respondit: Voluntas Dei fuit ut cito occurreret mihi quod volebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Dixitque Isaac: Accede huc, ut tangam te, fili mi, et probem utrum tu sis filius meus Esau, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Accessit ille ad patrem, et palpato eo, dixit Isaac: Vox quidem, vox Jacob est: sed manus, manus sunt Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et non cognovit eum, quia pilosæ manus similitudinem majoris expresserant. Benedicens ergo illi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'ait: Tu es filius meus Esau? Respondit: Ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'At ille: Affer mihi, inquit, cibos de venatione tua, fili mi, ut benedicat tibi anima mea. Quos cum oblatos comedisset, obtulit ei etiam vinum. Quo hausto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'dixit ad eum: Accede ad me, et da mihi osculum, fili mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Accessit, et osculatus est eum. Statimque ut sensit vestimentorum illius fragrantiam, benedicens illi, ait: Ecce odor filii mei sicut odor agri pleni, cui benedixit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Det tibi Deus de rore cæli et de pinguedine terræ abundantiam frumenti et vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Et serviant tibi populi, et adorent te tribus: esto dominus fratrum tuorum, et incurventur ante te filii matris tuæ: qui maledixerit tibi, sit ille maledictus, et qui benedixerit tibi, benedictionibus repleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Vix Isaac sermonem impleverat, et egresso Jacob foras, venit Esau,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'coctosque de venatione cibos intulit patri, dicens: Surge, pater mi, et comede de venatione filii tui, ut benedicat mihi anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Dixitque illi Isaac: Quis enim es tu? Qui respondit: Ego sum filius tuus primogenitus Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Expavit Isaac stupore vehementi: et ultra quam credi potest admirans, ait: Quis igitur ille est qui dudum captam venationem attulit mihi, et comedi ex omnibus priusquam tu venires; benedixique ei, et erit benedictus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Auditis Esau sermonibus patris, irrugiit clamore magno: et consternatus, ait: Benedic etiam et mihi, pater mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Qui ait: Venit germanus tuus fraudulenter, et accepit benedictionem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'At ille subjunxit: Juste vocatum est nomen ejus Jacob: supplantavit enim me en altera vice: primogenita mea ante tulit, et nunc secundo surripuit benedictionem meam. Rursumque ad patrem: Numquid non reservasti, ait, et mihi benedictionem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Respondit Isaac: Dominum tuum illum constitui, et omnes fratres ejus servituti illius subjugavi; frumento et vino stabilivi eum: et tibi post hæc, fili mi, ultra quid faciam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Cui Esau: Num unam, inquit, tantum benedictionem habes, pater? mihi quoque obsecro ut benedicas. Cumque ejulatu magno fleret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'motus Isaac, dixit ad eum: In pinguedine terræ, et in rore cæli desuper,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'erit benedictio tua. Vives in gladio, et fratri tuo servies: tempusque veniet, cum excutias et solvas jugum ejus de cervicibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Oderat ergo semper Esau Jacob pro benedictione qua benedixerat ei pater: dixitque in corde suo: Venient dies luctus patris mei, et occidam Jacob fratrem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Nuntiata sunt hæc Rebeccæ: quæ mittens et vocans Jacob filium suum, dixit ad eum: Ecce Esau frater tuus minatur ut occidat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Nunc ergo, fili mi, audi vocem meam, et consurgens fuge ad Laban fratrem meum in Haran:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'habitabisque cum eo dies paucos, donec requiescat furor fratris tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'et cesset indignatio ejus, obliviscaturque eorum quæ fecisti in eum: postea mittam, et adducam te inde huc: cur utroque orbabor filio in uno die?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Dixitque Rebecca ad Isaac: Tædet me vitæ meæ propter filias Heth: si acceperit Jacob uxorem de stirpe hujus terræ, nolo vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Vocavit itaque Isaac Jacob, et benedixit eum, præcepitque ei dicens: Noli accipere conjugem de genere Chanaan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'sed vade, et proficiscere in Mesopotamiam Syriæ, ad domum Bathuel patris matris tuæ, et accipe tibi inde uxorem de filiabus Laban avunculi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Deus autem omnipotens benedicat tibi, et crescere te faciat, atque multiplicet, ut sis in turbas populorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Et det tibi benedictiones Abrahæ, et semini tuo post te: ut possideas terram peregrinationis tuæ, quam pollicitus est avo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Cumque dimisisset eum Isaac, profectus venit in Mesopotamiam Syriæ ad Laban filium Bathuel Syri, fratrem Rebeccæ matris suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Videns autem Esau quod benedixisset pater suus Jacob, et misisset eum in Mesopotamiam Syriæ, ut inde uxorem duceret; et quod post benedictionem præcepisset ei, dicens: Non accipies uxorem de filiabus Chanaan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'quodque obediens Jacob parentibus suis isset in Syriam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'probans quoque quod non libenter aspiceret filias Chanaan pater suus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'ivit ad Ismaëlem, et duxit uxorem absque iis, quas prius habebat, Maheleth filiam Ismaël filii Abraham, sororem Nabaioth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Igitur egressus Jacob de Bersabee, pergebat Haran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Cumque venisset ad quemdam locum, et vellet in eo requiescere post solis occubitum, tulit de lapidibus qui jacebant, et supponens capiti suo, dormivit in eodem loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Viditque in somnis scalam stantem super terram, et cacumen illius tangens cælum: angelos quoque Dei ascendentes et descendentes per eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'et Dominum innixum scalæ dicentem sibi: Ego sum Dominus Deus Abraham patris tui, et Deus Isaac: terram, in qua dormis, tibi dabo et semini tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Eritque semen tuum quasi pulvis terræ: dilataberis ad occidentem, et orientem, et septentrionem, et meridiem: et benedicentur in te et in semine tuo cunctæ tribus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Et ero custos tuus quocumque perrexeris, et reducam te in terram hanc: nec dimittam nisi complevero universa quæ dixi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Cumque evigilasset Jacob de somno, ait: Vere Dominus est in loco isto, et ego nesciebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Pavensque, Quam terribilis est, inquit, locus iste! non est hic aliud nisi domus Dei, et porta cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Surgens ergo Jacob mane, tulit lapidem quem supposuerat capiti suo, et erexit in titulum, fundens oleum desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Appellavitque nomen urbis Bethel, quæ prius Luza vocabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Vovit etiam votum, dicens: Si fuerit Deus mecum, et custodierit me in via, per quam ego ambulo, et dederit mihi panem ad vescendum, et vestimentum ad induendum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'reversusque fuero prospere ad domum patris mei: erit mihi Dominus in Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'et lapis iste, quem erexi in titulum, vocabitur Domus Dei: cunctorumque quæ dederis mihi, decimas offeram tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Profectus ergo Jacob venit in terram orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Et vidit puteum in agro, tres quoque greges ovium accubantes juxta eum: nam ex illo adaquabantur pecora, et os ejus grandi lapide claudebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Morisque erat ut cunctis ovibus congregatis devolverent lapidem, et refectis gregibus rursum super os putei ponerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Dixitque ad pastores: Fratres, unde estis? Qui responderunt: De Haran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Quos interrogans, Numquid, ait, nostis Laban filium Nachor? Dixerunt: Novimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Sanusne est? inquit. Valet, inquiunt: et ecce Rachel filia ejus venit cum grege suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Dixitque Jacob: Adhuc multum diei superest, nec est tempus ut reducantur ad caulas greges: date ante potum ovibus, et sic eas ad pastum reducite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Qui responderunt: Non possumus, donec omnia pecora congregentur, et amoveamus lapidem de ore putei, ut adaquemus greges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Adhuc loquebantur, et ecce Rachel veniebat cum ovibus patris sui: nam gregem ipsa pascebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Quam cum vidisset Jacob, et sciret consobrinam suam, ovesque Laban avunculi sui, amovit lapidem quo puteus claudebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et adaquato grege, osculatus est eam: et elevata voce flevit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'et indicavit ei quod frater esset patris sui, et filius Rebeccæ: at illa festinans nuntiavit patri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Qui cum audisset venisse Jacob filium sororis suæ, cucurrit obviam ei: complexusque eum, et in oscula ruens, duxit in domum suam. Auditis autem causis itineris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'respondit: Os meum es, et caro mea. Et postquam impleti sunt dies mensis unius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'dixit ei: Num quia frater meus es, gratis servies mihi? dic quid mercedis accipias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Habebat vero duas filias: nomen majoris Lia, minor vero appellabatur Rachel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Sed Lia lippis erat oculis: Rachel decora facie, et venusto aspectu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Quam diligens Jacob, ait: Serviam tibi pro Rachel filia tua minore, septem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Respondit Laban: Melius est ut tibi eam dem quam alteri viro: mane apud me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Servivit ergo Jacob pro Rachel septem annis: et videbantur illi pauci dies præ amoris magnitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Dixitque ad Laban: Da mihi uxorem meam: quia jam tempus impletum est, ut ingrediar ad illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Qui vocatis multis amicorum turbis ad convivium, fecit nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Et vespere Liam filiam suam introduxit ad eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'dans ancillam filiæ, Zelpham nomine. Ad quam cum ex more Jacob fuisset ingressus, facto mane vidit Liam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'et dixit ad socerum suum: Quid est quod facere voluisti? nonne pro Rachel servivi tibi? quare imposuisti mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Respondit Laban: Non est in loco nostro consuetudinis, ut minores ante tradamus ad nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Imple hebdomadam dierum hujus copulæ: et hanc quoque dabo tibi pro opere quo serviturus es mihi septem annis aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Acquievit placito: et hebdomada transacta, Rachel duxit uxorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'cui pater servam Balam tradiderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Tandemque potitus optatis nuptiis, amorem sequentis priori prætulit, serviens apud eum septem annis aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Videns autem Dominus quod despiceret Liam, aperuit vulvam ejus, sorore sterili permanente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Quæ conceptum genuit filium, vocavitque nomen ejus Ruben, dicens: Vidit Dominus humilitatem meam: nunc amabit me vir meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Rursumque concepit et peperit filium, et ait: Quoniam audivit me Dominus haberi contemptui, dedit etiam istum mihi; vocavitque nomen ejus Simeon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Concepitque tertio, et genuit alium filium: dixitque: Nunc quoque copulabitur mihi maritus meus: eo quod pepererim ei tres filios: et idcirco appellavit nomen ejus Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Quarto concepit, et peperit filium, et ait: Modo confitebor Domino, et ob hoc vocavit eum Judam: cessavitque parere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Cernens autem Rachel quod infecunda esset, invidit sorori suæ, et ait marito suo: Da mihi liberos, alioquin moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Cui iratus respondit Jacob: Num pro Deo ego sum, qui privavit te fructu ventris tui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'At illa: Habeo, inquit, famulam Balam: ingredere ad illam, ut pariat super genua mea, et habeam ex illa filios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Deditque illi Balam in conjugium: quæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'ingresso ad se viro, concepit, et peperit filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Dixitque Rachel: Judicavit mihi Dominus, et exaudivit vocem meam, dans mihi filium, et idcirco appellavit nomen ejus Dan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Rursumque Bala concipiens, peperit alterum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'pro quo ait Rachel: Comparavit me Deus cum sorore mea, et invalui: vocavitque eum Nephthali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Sentiens Lia quod parere desiisset, Zelpham ancillam suam marito tradidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Qua post conceptum edente filium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'dixit: Feliciter, et idcirco vocavit nomen ejus Gad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Peperit quoque Zelpha alterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Dixitque Lia: Hoc pro beatitudine mea: beatam quippe me dicent mulieres: propterea appellavit eum Aser.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Egressus autem Ruben tempore messis triticeæ in agrum, reperit mandragoras, quas matri Liæ detulit. Dixitque Rachel: Da mihi partem de mandragoris filii tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Illa respondit: Parumne tibi videtur quod præripueris maritum mihi, nisi etiam mandragoras filii mei tuleris? Ait Rachel: Dormiat tecum hac nocte pro mandragoris filii tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Redeuntique ad vesperam Jacob de agro, egressa est in occursum ejus Lia, et Ad me, inquit, intrabis: quia mercede conduxi te pro mandragoris filii mei. Dormivitque cum ea nocte illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Et exaudivit Deus preces ejus, concepitque et peperit filium quintum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'et ait: Dedit Deus mercedem mihi, quia dedi ancillam meam viro meo: appellavitque nomen ejus Issachar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Rursum Lia concipiens, peperit sextum filium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'et ait: Dotavit me Deus dote bona: etiam hac vice mecum erit maritus meus, eo quod genuerim ei sex filios: et idcirco appellavit nomen ejus Zabulon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Post quem peperit filiam, nomine Dinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Recordatus quoque Dominus Rachelis, exaudivit eam, et aperuit vulvam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Quæ concepit, et peperit filium, dicens: Abstulit Deus opprobrium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Et vocavit nomen ejus Joseph, dicens: Addat mihi Dominus filium alterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Nato autem Joseph, dixit Jacob socero suo: Dimitte me ut revertar in patriam, et ad terram meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Da mihi uxores, et liberos meos, pro quibus servivi tibi, ut abeam: tu nosti servitutem qua servivi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Ait illi Laban: Inveniam gratiam in conspectu tuo, experimento didici, quia benedixerit mihi Deus propter te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'constitue mercedem tuam quam dem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'At ille respondit: Tu nosti quomodo servierim tibi, et quanta in manibus meis fuerit possessio tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Modicum habuisti antequam venirem ad te, et nunc dives effectus es: benedixitque tibi Dominus ad introitum meum. Justum est igitur ut aliquando provideam etiam domui meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Dixitque Laban: Quid tibi dabo? At ille ait: Nihil volo: sed si feceris quod postulo, iterum pascam, et custodiam pecora tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Gyra omnes greges tuos, et separa cunctas oves varias, et sparso vellere; quodcumque furvum, et maculosum, variumque fuerit, tam in ovibus quam in capris, erit merces mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Respondebitque mihi cras justitia mea, quando placiti tempus advenerit coram te: et omnia quæ non fuerint varia, et maculosa, et furva, tam in ovibus quam in capris, furti me arguent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Dixitque Laban: Gratum habeo quod petis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Et separavit in die illa capras, et oves, et hircos, et arietes varios, atque maculosos: cunctum autem gregem unicolorem, id est albi et nigri velleris, tradidit in manu filiorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et posuit spatium itineris trium dierum inter se et generum, qui pascebat reliquos greges ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Tollens ergo Jacob virgas populeas virides, et amygdalinas, et ex platanis, ex parte decorticavit eas: detractisque corticibus, in his, quæ spoliata fuerant, candor apparuit: illa vero quæ integra fuerant, viridia permanserunt: atque in hunc modum color effectus est varius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Posuitque eas in canalibus, ubi effundebatur aqua: ut cum venissent greges ad bibendum, ante oculos haberent virgas, et in aspectu earum conciperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Factumque est ut in ipso calore coitus, oves intuerentur virgas, et parerent maculosa, et varia, et diverso colore respersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Divisitque gregem Jacob, et posuit virgas in canalibus ante oculos arietum: erant autem alba et nigra quæque, Laban; cetera vero, Jacob, separatis inter se gregibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Igitur quando primo tempore ascendebantur oves, ponebat Jacob virgas in canalibus aquarum ante oculos arietum et ovium, ut in earum contemplatione conciperent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'quando vero serotina admissura erat, et conceptus extremus, non ponebat eas. Factaque sunt ea quæ erant serotina, Laban: et quæ primi temporis, Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Ditatusque est homo ultra modum, et habuit greges multos, ancillas et servos, camelos et asinos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Postquam autem audivit verba filiorum Laban dicentium: Tulit Jacob omnia quæ fuerunt patris nostri, et de illius facultate ditatus, factus est inclytus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'animadvertit quoque faciem Laban, quod non esset erga se sicut heri et nudiustertius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'maxime dicente sibi Domino: Revertere in terram patrum tuorum, et ad generationem tuam, eroque tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Misit, et vocavit Rachel et Liam in agrum, ubi pascebat greges,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'dixitque eis: Video faciem patris vestri quod non sit erga me sicut heri et nudiustertius: Deus autem patris mei fuit mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Et ipsæ nostis quod totis viribus meis servierim patri vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Sed et pater vester circumvenit me et mutavit mercedem meam decem vicibus: et tamen non dimisit eum Deus ut noceret mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Si quando dixit: Variæ erunt mercedes tuæ: pariebant omnes oves varios fœtus; quando vero e contrario, ait: Alba quæque accipies pro mercede: omnes greges alba pepererunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Tulitque Deus substantiam patris vestri, et dedit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Postquam enim conceptus ovium tempus advenerat, levavi oculos meos, et vidi in somnis ascendentes mares super feminas, varios et maculosos, et diversorum colorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Dixitque angelus Dei ad me in somnis: Jacob? Et ego respondi: Adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Qui ait: Leva oculos tuos, et vide universos masculos ascendentes super feminas, varios, maculosos, atque respersos. Vidi enim omnia quæ fecit tibi Laban.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ego sum Deus Bethel, ubi unxisti lapidem, et votum vovisti mihi. Nunc ergo surge, et egredere de terra hac, revertens in terram nativitatis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Responderuntque Rachel et Lia: Numquid habemus residui quidquam in facultatibus et hæreditate domus patris nostri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'nonne quasi alienas reputavit nos, et vendidit, comeditque pretium nostrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Sed Deus tulit opes patris nostri, et eas tradidit nobis, ac filiis nostris: unde omnia quæ præcepit tibi Deus, fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Surrexit itaque Jacob, et impositis liberis ac conjugibus suis super camelos, abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Tulitque omnem substantiam suam, et greges, et quidquid in Mesopotamia acquisierat, pergens ad Isaac patrem suum in terram Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Eo tempore ierat Laban ad tondendas oves, et Rachel furata est idola patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Noluitque Jacob confiteri socero suo quod fugeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Cumque abiisset tam ipse quam omnia quæ juris sui erant, et amne transmisso pergeret contra montem Galaad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'nuntiatum est Laban die tertio quod fugeret Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Qui, assumptis fratribus suis, persecutus est eum diebus septem: et comprehendit eum in monte Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Viditque in somnis dicentem sibi Deum: Cave ne quidquam aspere loquaris contra Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Jamque Jacob extenderat in monte tabernaculum: cumque ille consecutus fuisset eum cum fratribus suis, in eodem monte Galaad fixit tentorium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Et dixit ad Jacob: Quare ita egisti, ut clam me abigeres filias meas quasi captivas gladio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'cur ignorante me fugere voluisti, nec indicare mihi, ut prosequerer te cum gaudio, et canticis, et tympanis, et citharis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Non es passus ut oscularer filios meos et filias: stulte operatus es: et nunc quidem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'valet manus mea reddere tibi malum: sed Deus patris vestri heri dixit mihi: Cave ne loquaris contra Jacob quidquam durius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Esto, ad tuos ire cupiebas, et desiderio erat tibi domus patris tui: cur furatus es deos meos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Respondit Jacob: Quod inscio te profectus sum, timui ne violenter auferres filias tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Quod autem furti me arguis: apud quemcumque inveneris deos tuos, necetur coram fratribus nostris: scrutare, quidquid tuorum apud me inveneris, et aufer. Hæc dicens, ignorabat quod Rachel furata esset idola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Ingressus itaque Laban tabernaculum Jacob, et Liæ, et utriusque famulæ, non invenit. Cumque intrasset tentorium Rachelis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'illa festinans abscondit idola subter stramenta cameli, et sedit desuper: scrutantique omne tentorium, et nihil invenienti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'ait: Ne irascatur dominus meus quod coram te assurgere nequeo: quia juxta consuetudinem feminarum nunc accidit mihi: sic delusa sollicitudo quærentis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Tumensque Jacob, cum jurgio ait: Quam ob culpam meam, et ob quod peccatum meum sic exarsisti post me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'et scrutatus es omnem supellectilem meam? quid invenisti de cuncta substantia domus tuæ? pone hic coram fratribus meis, et fratribus tuis, et judicent inter me et te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Idcirco viginti annis fui tecum? oves tuæ et capræ steriles non fuerunt, arietes gregis tui non comedi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'nec captum a bestia ostendi tibi, ego damnum omne reddebam: quidquid furto peribat, a me exigebas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'die noctuque æstu urebar, et gelu, fugiebatque somnus ab oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Sicque per viginti annos in domo tua servivi tibi, quatuordecim pro filiabus, et sex pro gregibus tuis: immutasti quoque mercedem meam decem vicibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Nisi Deus patris mei Abraham, et timor Isaac affuisset mihi, forsitan modo nudum me dimisisses: afflictionem meam et laborem manuum mearum respexit Deus, et arguit te heri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Respondit ei Laban: Filiæ meæ et filii, et greges tui, et omnia quæ cernis, mea sunt: quid possum facere filiis et nepotibus meis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Veni ergo, et ineamus fœdus, ut sit in testimonium inter me et te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Tulit itaque Jacob lapidem, et erexit illum in titulum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'dixitque fratribus suis: Afferte lapides. Qui congregantes fecerunt tumulum, comederuntque super eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'quem vocavit Laban Tumulum testis: et Jacob, Acervum testimonii, uterque juxta proprietatem linguæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Dixitque Laban: Tumulus iste erit testis inter me et te hodie, et idcirco appellatum est nomen ejus Galaad, id est, Tumulus testis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Intueatur et judicet Dominus inter nos quando recesserimus a nobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'si afflixeris filias meas, et si introduxeris alias uxores super eas: nullus sermonis nostri testis est absque Deo, qui præsens respicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Dixitque rursus ad Jacob: En tumulus hic, et lapis quem erexi inter me et te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'testis erit: tumulus, inquam, iste et lapis sint in testimonium, si aut ego transiero illum pergens ad te, aut tu præterieris, malum mihi cogitans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Deus Abraham, et Deus Nachor, judicet inter nos, Deus patris eorum. Juravit ergo Jacob per timorem patris sui Isaac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'immolatisque victimis in monte, vocavit fratres suos ut ederent panem. Qui cum comedissent, manserunt ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Laban vero de nocte consurgens, osculatus est filios, et filias suas, et benedixit illis: reversusque est in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jacob quoque abiit itinere quo cœperat: fueruntque ei obviam angeli Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Quos cum vidisset, ait: Castra Dei sunt hæc: et appellavit nomen loci illius Mahanaim, id est, Castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Misit autem et nuntios ante se ad Esau fratrem suum in terram Seir, in regionem Edom:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'præcepitque eis, dicens: Sic loquimini domino meo Esau: Hæc dicit frater tuus Jacob: Apud Laban peregrinatus sum, et fui usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Habeo boves, et asinos, et oves, et servos, et ancillas: mittoque nunc legationem ad dominum meum, ut inveniam gratiam in conspectu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Reversique sunt nuntii ad Jacob, dicentes: Venimus ad Esau fratrem tuum, et ecce properat tibi in occursum cum quadringentis viris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Timuit Jacob valde: et perterritus divisit populum qui secum erat, greges quoque et oves, et boves, et camelos, in duas turmas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'dicens: Si venerit Esau ad unam turmam, et percusserit eam, alia turma, quæ relicta est, salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Dixitque Jacob: Deus patris mei Abraham, et Deus patris mei Isaac: Domine qui dixisti mihi: Revertere in terram tuam, et in locum nativitatis tuæ, et benefaciam tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'minor sum cunctis miserationibus tuis, et veritate tua quam explevisti servo tuo. In baculo meo transivi Jordanem istum: et nunc cum duabus turmis regredior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Erue me de manu fratris mei Esau, quia valde eum timeo: ne forte veniens percutiat matrem cum filiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Tu locutus es quod benefaceres mihi, et dilatares semen meum sicut arenam maris, quæ præ multitudine numerari non potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Cumque dormisset ibi nocte illa, separavit de his quæ habebat, munera Esau fratri suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'capras ducentas, hircos viginti, oves ducentas, et arietes viginti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'camelos fœtas cum pullis suis triginta, vaccas quadraginta, et tauros viginti, asinas viginti et pullos earum decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Et misit per manus servorum suorum singulos seorsum greges, dixitque pueris suis: Antecedite me, et sit spatium inter gregem et gregem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Et præcepit priori, dicens: Si obvium habueris fratrem meum Esau, et interrogaverit te: Cujus es? aut, Quo vadis? aut, Cujus sunt ista quæ sequeris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'respondebis: Servi tui Jacob, munera misit domino meo Esau, ipse quoque post nos venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Similiter dedit mandata secundo, et tertio, et cunctis qui sequebantur greges, dicens: Iisdem verbis loquimini ad Esau cum inveneritis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Et addetis: Ipse quoque servus tuus Jacob iter nostrum insequitur. Dixit enim: Placabo illum muneribus quæ præcedunt, et postea videbo illum: forsitan propitiabitur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Præcesserunt itaque munera ante eum, ipse vero mansit nocte illa in castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Cumque mature surrexisset, tulit duas uxores suas, et totidem famulas cum undecim filiis, et transivit vadum Jaboc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Traductisque omnibus quæ ad se pertinebant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'mansit solus: et ecce vir luctabatur cum eo usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Qui cum videret quod eum superare non posset, tetigit nervum femoris ejus, et statim emarcuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Dixitque ad eum: Dimitte me: jam enim ascendit aurora. Respondit: Non dimittam te, nisi benedixeris mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Ait ergo: Quod nomen est tibi? Respondit: Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'At ille: Nequaquam, inquit, Jacob appellabitur nomen tuum, sed Israël: quoniam si contra Deum fortis fuisti, quanto magis contra homines prævalebis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Interrogavit eum Jacob: Dic mihi, quo appellaris nomine? Respondit: Cur quæris nomen meum? Et benedixit ei in eodem loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Vocavitque Jacob nomen loci illius Phanuel, dicens: Vidi Deum facie ad faciem, et salva facta est anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Ortusque est ei statim sol, postquam transgressus est Phanuel: ipse vero claudicabat pede.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Quam ob causam non comedunt nervum filii Israël, qui emarcuit in femore Jacob, usque in præsentem diem: eo quod tetigerit nervum femoris ejus, et obstupuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Elevans autem Jacob oculos suos, vidit venientem Esau, et cum eo quadringentos viros: divisitque filios Liæ et Rachel, ambarumque famularum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'et posuit utramque ancillam, et liberos earum, in principio: Liam vero, et filios ejus, in secundo loco: Rachel autem et Joseph novissimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Et ipse progrediens adoravit pronus in terram septies, donec appropinquaret frater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Currens itaque Esau obviam fratri suo, amplexatus est eum: stringensque collum ejus, et osculans flevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Levatisque oculis, vidit mulieres et parvulos earum, et ait: Quid sibi volunt isti? et si ad te pertinent? Respondit: Parvuli sunt quos donavit mihi Deus servo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Et appropinquantes ancillæ et filii earum, incurvati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Accessit quoque Lia cum pueris suis: et cum similiter adorassent, extremi Joseph et Rachel adoraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Dixitque Esau: Quænam sunt istæ turmæ quas obviam habui? Respondit: Ut invenirem gratiam coram domino meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'At ille ait: Habeo plurima, frater mi, sint tua tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Dixitque Jacob: Noli ita, obsecro: sed si inveni gratiam in oculis tuis, accipe munusculum de manibus meis. Sic enim vidi faciem tuam, quasi viderim vultum Dei: esto mihi propitius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'et suscipe benedictionem quam attuli tibi, et quam donavit mihi Deus tribuens omnia. Vix fratre compellente, suscipiens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'ait: Gradiamur simul, eroque socius itineris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Dixitque Jacob: Nosti, domine mi, quod parvulos habeam teneros, et oves, et boves fœtas mecum: quas si plus in ambulando fecero laborare, morientur una die cuncti greges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Præcedat dominus meus ante servum suum: et ego sequar paulatim vestigia ejus, sicut videro parvulos meos posse, donec veniam ad dominum meum in Seir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Respondit Esau: Oro te, ut de populo qui mecum est, saltem socii remaneant viæ tuæ. Non est, inquit, necesse: hoc uno tantum indigeo, ut inveniam gratiam in conspectu tuo, domine mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Reversus est itaque illo die Esau itinere quo venerat in Seir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Et Jacob venit in Socoth: ubi ædificata domo et fixis tentoriis appellavit nomen loci illius Socoth, id est, Tabernacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Transivitque in Salem urbem Sichimorum, quæ est in terra Chanaan, postquam reversus est de Mesopotamia Syriæ: et habitavit juxta oppidum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Emitque partem agri, in qua fixerat tabernacula, a filiis Hemor patris Sichem centum agnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Et erecto ibi altari, invocavit super illud fortissimum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Egressa est autem Dina filia Liæ ut videret mulieres regionis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Quam cum vidisset Sichem filius Hemor Hevæi, princeps terræ illius, adamavit eam: et rapuit, et dormivit cum illa, vi opprimens virginem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Et conglutinata est anima ejus cum ea, tristemque delinivit blanditiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Et pergens ad Hemor patrem suum: Accipe, inquit, mihi puellam hanc conjugem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Quod cum audisset Jacob absentibus filiis, et in pastu pecorum occupatis, siluit donec redirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Egresso autem Hemor patre Sichem ut loqueretur ad Jacob,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'ecce filii ejus veniebant de agro: auditoque quod acciderat, irati sunt valde, eo quod fœdam rem operatus esset in Israël et, violata filia Jacob, rem illicitam perpetrasset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Locutus est itaque Hemor ad eos: Sichem filii mei adhæsit anima filiæ vestræ: date eam illi uxorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'et jungamus vicissim connubia: filias vestras tradite nobis, et filias nostras accipite,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'et habitate nobiscum: terra in potestate vestra est: exercete, negotiamini, et possidete eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sed et Sichem ad patrem et ad fratres ejus ait: Inveniam gratiam coram vobis: et quæcumque statueritis, dabo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'augete dotem, et munera postulate, et libenter tribuam quod petieritis: tantum date mihi puellam hanc uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Responderunt filii Jacob Sichem et patri ejus in dolo, sævientes ob stuprum sororis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Non possumus facere quod petitis, nec dare sororem nostram homini incircumciso: quod illicitum et nefarium est apud nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Sed in hoc valebimus fœderari, si volueritis esse similes nostri, et circumcidatur in vobis omne masculini sexus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'tunc dabimus et accipiemus mutuo filias vestras ac nostras: et habitabimus vobiscum, erimusque unus populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Si autem circumcidi nolueritis, tollemus filiam nostram, et recedemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Placuit oblatio eorum Hemor, et Sichem filio ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'nec distulit adolescens quin statim quod petebatur expleret: amabat enim puellam valde, et ipse erat inclytus in omni domo patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Ingressique portam urbis, locuti sunt ad populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Viri isti pacifici sunt, et volunt habitare nobiscum: negotientur in terra, et exerceant eam, quæ spatiosa et lata cultoribus indiget: filias eorum accipiemus uxores, et nostras illis dabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Unum est quo differtur tantum bonum: si circumcidamus masculos nostros, ritum gentis imitantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Et substantia eorum, et pecora, et cuncta quæ possident, nostra erunt: tantum in hoc acquiescamus, et habitantes simul, unum efficiemus populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Assensique sunt omnes, circumcisis cunctis maribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Et ecce, die tertio, quando gravissimus vulnerum dolor est: arreptis duo filii Jacob, Simeon et Levi fratres Dinæ, gladiis, ingressi sunt urbem confidenter: interfectisque omnibus masculis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Hemor et Sichem pariter necaverunt, tollentes Dinam de domo Sichem sororem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Quibus egressis, irruerunt super occisos ceteri filii Jacob: et depopulati sunt urbem in ultionem stupri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Oves eorum, et armenta, et asinos, cunctaque vastantes quæ in domibus et in agris erant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'parvulos quoque eorum et uxores duxerunt captivas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Quibus patratis audacter, Jacob dixit ad Simeon et Levi: Turbastis me, et odiosum fecistis me Chananæis, et Pherezæis habitatoribus terræ hujus: nos pauci sumus; illi congregati percutient me, et delebor ego, et domus mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Responderunt: Numquid ut scorto abuti debuere sorore nostra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Interea locutus est Deus ad Jacob: Surge, et ascende Bethel, et habita ibi, facque altare Deo qui apparuit tibi quando fugiebas Esau fratrem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Jacob vero convocata omni domo sua, ait: Abjicite deos alienos qui in medio vestri sunt, et mundamini, ac mutate vestimenta vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Surgite, et ascendamus in Bethel, ut faciamus ibi altare Deo: qui exaudivit me in die tribulationis meæ, et socius fuit itineris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Dederunt ergo ei omnes deos alienos quos habebant, et inaures quæ erant in auribus eorum: at ille infodit ea subter terebinthum, quæ est post urbem Sichem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Cumque profecti essent, terror Dei invasit omnes per circuitum civitates, et non sunt ausi persequi recedentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Venit igitur Jacob Luzam, quæ est in terra Chanaan, cognomento Bethel: ipse et omnis populus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, '\'dificavitque ibi altare, et appellavit nomen loci illius, Domus Dei: ibi enim apparuit ei Deus cum fugeret fratrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Eodem tempore mortua est Debora nutrix Rebeccæ, et sepulta est ad radices Bethel subter quercum: vocatumque est nomen loci illius, Quercus fletus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Apparuit autem iterum Deus Jacob postquam reversus est de Mesopotamia Syriæ, benedixitque ei');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'dicens: Non vocaberis ultra Jacob, sed Israël erit nomen tuum. Et appellavit eum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'dixitque ei: Ego Deus omnipotens: cresce, et multiplicare: gentes et populi nationum ex te erunt, reges de lumbis tuis egredientur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'terramque quam dedi Abraham et Isaac, dabo tibi et semini tuo post te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Et recessit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Ille vero erexit titulum lapideum in loco quo locutus fuerat ei Deus: libans super eum libamina, et effundens oleum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'vocansque nomen loci illius Bethel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Egressus autem inde, venit verno tempore ad terram quæ ducit Ephratam: in qua cum parturiret Rachel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'ob difficultatem partus periclitari cœpit. Dixitque ei obstetrix: Noli timere, quia et hunc habebis filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Egrediente autem anima præ dolore, et imminente jam morte, vocavit nomen filii sui Benomi, id est, Filius doloris mei: pater vero appellavit eum Benjamin, id est, Filius dextræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Mortua est ergo Rachel, et sepulta est in via quæ ducit Ephratam, hæc est Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Erexitque Jacob titulum super sepulchrum ejus: hic est titulus monumenti Rachel, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Egressus inde, fixit tabernaculum trans Turrem gregis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Cumque habitaret in illa regione, abiit Ruben, et dormivit cum Bala concubina patris sui: quod illum minime latuit. Erant autem filii Jacob duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Filii Liæ: primogenitus Ruben, et Simeon, et Levi, et Judas, et Issachar, et Zabulon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Filii Rachel: Joseph et Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Filii Balæ ancillæ Rachelis: Dan et Nephthali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Filii Zelphæ ancillæ Liæ: Gad et Aser: hi sunt filii Jacob, qui nati sunt ei in Mesopotamia Syriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Venit etiam ad Isaac patrem suum in Mambre, civitatem Arbee, hæc est Hebron, in qua peregrinatus est Abraham et Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Et completi sunt dies Isaac centum octoginta annorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Consumptusque ætate mortuus est: et appositus est populo suo senex et plenus dierum: et sepelierunt eum Esau et Jacob filii sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Hæ sunt autem generationes Esau, ipse est Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau accepit uxores de filiabus Chanaan: Ada filiam Elon Hethæi, et Oolibama filiam Anæ filiæ Sebeon Hevæi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Basemath quoque filiam Ismaël sororem Nabaioth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Peperit autem Ada Eliphaz: Basemath genuit Rahuel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oolibama genuit Jehus et Ihelon et Core. Hi filii Esau qui nati sunt ei in terra Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Tulit autem Esau uxores suas et filios et filias, et omnem animam domus suæ, et substantiam, et pecora, et cuncta quæ habere poterat in terra Chanaan: et abiit in alteram regionem, recessitque a fratre suo Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Divites enim erant valde, et simul habitare non poterant: nec sustinebat eos terra peregrinationis eorum præ multitudine gregum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Habitavitque Esau in monte Seir, ipse est Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Hæ autem sunt generationes Esau patris Edom in monte Seir,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'et hæc nomina filiorum ejus: Eliphaz filius Ada uxoris Esau: Rahuel quoque filius Basemath uxoris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Fueruntque Eliphaz filii: Theman, Omar, Sepho, et Gatham, et Cenez.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Erat autem Thamna concubina Eliphaz filii Esau: quæ peperit ei Amalech. Hi sunt filii Ada uxoris Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Filii autem Rahuel: Nahath et Zara, Samma et Meza: hi filii Basemath uxoris Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Isti quoque erant filii Oolibama filiæ Anæ filiæ Sebeon, uxoris Esau, quos genuit ei, Jehus et Ihelon et Core.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Hi duces filiorum Esau: filii Eliphaz primogeniti Esau: dux Theman, dux Omra, dux Sepho, dux Cenez,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'dux Core, dux Gathan, dux Amalech. Hi filii Eliphaz in terra Edom, et hi filii Ada.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Hi quoque filii Rahuel filii Esau: dux Nahath, dux Zara, dux Samma, dux Meza: hi autem duces Rahuel in terra Edom: isti filii Basemath uxoris Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Hi autem filii Oolibama uxoris Esau: dux Jehus, dux Ihelon, dux Core: hi duces Oolibama filiæ Anæ uxoris Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Isti sunt filii Esau, et hi duces eorum: ipse est Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Isti sunt filii Seir Horræi, habitatores terræ: Lotan, et Sobal, et Sebeon, et Ana,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'et Dison, et Eser, et Disan: hi duces Horræi, filii Seir in terra Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Facti sunt autem filii Lotan: Hori et Heman. Erat autem soror Lotan, Thamna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Et isti filii Sobal: Alvan et Manahat et Ebal, et Sepho et Onam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Et hi filii Sebeon: Aja et Ana. Iste est Ana qui invenit aquas calidas in solitudine, cum pasceret asinos Sebeon patris sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'habuitque filium Dison, et filiam Oolibama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Et isti filii Dison: Hamdan, et Eseban, et Jethram, et Charan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Hi quoque filii Eser: Balaan, et Zavan, et Acan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Habuit autem filios Disan: Hus et Aram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Hi duces Horræorum: dux Lotan, dux Sobal, dux Sebeon, dux Ana,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'dux Dison, dux Eser, dux Disan: isti duces Horræorum qui imperaverunt in terra Seir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Reges autem qui regnaverunt in terra Edom antequam haberent regem filii Israël, fuerunt hi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela filius Beor, nomenque urbis ejus Denaba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Mortuus est autem Bela, et regnavit pro eo Jobab filius Zaræ de Bosra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Cumque mortuus esset Jobab, regnavit pro eo Husam de terra Themanorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Hoc quoque mortuo, regnavit pro eo Adad filius Badad, qui percussit Madian in regione Moab: et nomen urbis ejus Avith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Cumque mortuus esset Adad, regnavit pro eo Semla de Masreca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Hoc quoque mortuo regnavit pro eo Saul de fluvio Rohoboth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Cumque et hic obiisset, successit in regnum Balanan filius Achobor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Isto quoque mortuo regnavit pro eo Adar, nomenque urbis ejus Phau: et appellabatur uxor ejus Meetabel, filia Matred filiæ Mezaab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Hæc ergo nomina ducum Esau in cognationibus, et locis, et vocabulis suis: dux Thamna, dux Alva, dux Jetheth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'dux Oolibama, dux Ela, dux Phinon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'dux Cenez, dux Theman, dux Mabsar,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'dux Magdiel, dux Hiram: hi duces Edom habitantes in terra imperii sui, ipse est Esau pater Idumæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Habitavit autem Jacob in terra Chanaan, in qua pater suus peregrinatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Et hæ sunt generationes ejus: Joseph cum sedecim esset annorum, pascebat gregem cum fratribus suis adhuc puer: et erat cum filiis Balæ et Zelphæ uxorum patris sui: accusavitque fratres suos apud patrem crimine pessimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israël autem diligebat Joseph super omnes filios suos, eo quod in senectute genuisset eum: fecitque ei tunicam polymitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Videntes autem fratres ejus quod a patre plus cunctis filiis amaretur, oderant eum, nec poterant ei quidquam pacifice loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Accidit quoque ut visum somnium referret fratribus suis: quæ causa majoris odii seminarium fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Dixitque ad eos: Audite somnium meum quod vidi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'putabam nos ligare manipulos in agro: et quasi consurgere manipulum meum, et stare, vestrosque manipulos circumstantes adorare manipulum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Responderunt fratres ejus: Numquid rex noster eris? aut subjiciemur ditioni tuæ? Hæc ergo causa somniorum atque sermonum, invidiæ et odii fomitem ministravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Aliud quoque vidit somnium, quod narrans fratribus, ait: Vidi per somnium, quasi solem, et lunam, et stellas undecim adorare me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Quod cum patri suo, et fratribus retulisset, increpavit eum pater suus, et dixit: Quid sibi vult hoc somnium quod vidisti? num ego et mater tua, et fratres tui adorabimus te super terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Invidebant ei igitur fratres sui: pater vero rem tacitus considerabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Cumque fratres illius in pascendis gregibus patris morarentur in Sichem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'dixit ad eum Israël: Fratres tui pascunt oves in Sichimis: veni, mittam te ad eos. Quo respondente,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Præsto sum, ait ei: Vade, et vide si cuncta prospera sint erga fratres tuos, et pecora: et renuntia mihi quid agatur. Missus de valle Hebron, venit in Sichem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'invenitque eum vir errantem in agro, et interrogavit quid quæreret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'At ille respondit: Fratres meos quæro: indica mihi ubi pascant greges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Dixitque ei vir: Recesserunt de loco isto: audivi autem eos dicentes: Eamus in Dothain. Perrexit ergo Joseph post fratres suos, et invenit eos in Dothain.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Qui cum vidissent eum procul, antequam accederet ad eos, cogitaverunt illum occidere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'et mutuo loquebantur: Ecce somniator venit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'venite, occidamus eum, et mittamus in cisternam veterem: dicemusque: Fera pessima devoravit eum: et tunc apparebit quid illi prosint somnia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Audiens autem hoc Ruben, nitebatur liberare eum de manibus eorum, et dicebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Non interficiatis animam ejus, nec effundatis sanguinem: sed projicite eum in cisternam hanc, quæ est in solitudine, manusque vestras servate innoxias: hoc autem dicebat, volens eripere eum de manibus eorum, et reddere patri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Confestim igitur ut pervenit ad fratres suos, nudaverunt eum tunica talari et polymita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'miseruntque eum in cisternam veterem, quæ non habebat aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Et sedentes ut comederent panem, viderunt Ismaëlitas viatores venire de Galaad, et camelos eorum portantes aromata, et resinam, et stacten in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Dixit ergo Judas fratribus suis: Quid nobis prodest si occiderimus fratrem nostrum, et celaverimus sanguinem ipsius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'melius est ut venundetur Ismaëlitis, et manus nostræ non polluantur: frater enim et caro nostra est. Acquieverunt fratres sermonibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Et prætereuntibus Madianitis negotiatoribus, extrahentes eum de cisterna, vendiderunt eum Ismaëlitis, viginti argenteis: qui duxerunt eum in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Reversusque Ruben ad cisternam, non invenit puerum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'et scissis vestibus pergens ad fratres suos, ait: Puer non comparet, et ego quo ibo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Tulerunt autem tunicam ejus, et in sanguine hædi, quem occiderant, tinxerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'mittentes qui ferrent ad patrem, et dicerent: Hanc invenimus: vide utrum tunica filii tui sit, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Quam cum agnovisset pater, ait: Tunica filii mei est: fera pessima comedit eum, bestia devoravit Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Scissisque vestibus, indutus est cilicio, lugens filium suum multo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Congregatis autem cunctis liberis ejus ut lenirent dolorem patris, noluit consolationem accipere, sed ait: Descendam ad filium meum lugens in infernum. Et illo perseverante in fletu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Madianitæ vendiderunt Joseph in \'gypto Putiphari eunucho Pharaonis, magistro militum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Eodem tempore, descendens Judas a fratribus suis, divertit ad virum Odollamitem, nomine Hiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Viditque ibi filiam hominis Chananæi, vocabulo Sue: et accepta uxore, ingressus est ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Quæ concepit, et peperit filium, et vocavit nomen ejus Her.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Rursumque concepto fœtu, natum filium vocavit Onan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Tertium quoque peperit: quem appellavit Sela; quo nato, parere ultra cessavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Dedit autem Judas uxorem primogenito suo Her, nomine Thamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Fuit quoque Her primogenitus Judæ nequam in conspectu Domini: et ab eo occisus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Dixit ergo Judas ad Onan filium suum: Ingredere uxorem fratris tui, et sociare illi, ut suscites semen fratri tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Ille sciens non sibi nasci filios, introiens ad uxorem fratris sui, semen fundebat in terram, ne liberi fratris nomine nascerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et idcirco percussit eum Dominus, quod rem detestabilem faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Quam ob rem dixit Judas Thamar nurui suæ: Esto vidua in domo patris tui, donec crescat Sela filius meus: timebat enim ne et ipse moreretur, sicut fratres ejus. Quæ abiit, et habitavit in domo patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Evolutis autem multis diebus, mortua est filia Sue uxor Judæ: qui, post luctum consolatione suscepta, ascendebat ad tonsores ovium suarum, ipse et Hiras opilio gregis Odollamites, in Thamnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Nuntiatumque est Thamar quod socer illius ascenderet in Thamnas ad tondendas oves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Quæ, depositis viduitatis vestibus, assumpsit theristrum: et mutato habitu, sedit in bivio itineris, quod ducit Thamnam: eo quod crevisset Sela, et non eum accepisset maritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Quam cum vidisset Judas, suspicatus est esse meretricem: operuerat enim vultum suum, ne agnosceretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Ingrediensque ad eam, ait: Dimitte me ut coëam tecum: nesciebat enim quod nurus sua esset. Qua respondente: Quid dabis mihi ut fruaris concubitu meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'dixit: Mittam tibi hædum de gregibus. Rursumque illa dicente: Patiar quod vis, si dederis mihi arrhabonem, donec mittas quod polliceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Ait Judas: Quid tibi vis pro arrhabone dari? Respondit: Annulum tuum, et armillam, et baculum quem manu tenes. Ad unum igitur coitum mulier concepit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'et surgens abiit: depositoque habitu quem sumpserat, induta est viduitatis vestibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Misit autem Judas hædum per pastorem suum Odollamitem, ut reciperet pignus quod dederat mulieri: qui cum non invenisset eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'interrogavit homines loci illius: Ubi est mulier quæ sedebat in bivio? Respondentibus cunctis: Non fuit in loco ista meretrix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Reversus est ad Judam, et dixit ei: Non inveni eam: sed et homines loci illius dixerunt mihi, numquam sedisse ibi scortum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Ait Judas: Habeat sibi, certe mendacii arguere nos non potest, ego misi hædum quem promiseram: et tu non invenisti eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Ecce autem post tres menses nuntiaverunt Judæ, dicentes: Fornicata est Thamar nurus tua, et videtur uterus illius intumescere. Dixitque Judas: Producite eam ut comburatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Quæ cum duceretur ad pœnam, misit ad socerum suum, dicens: De viro, cujus hæc sunt, concepi: cognosce cujus sit annulus, et armilla, et baculus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Qui, agnitis muneribus, ait: Justior me est: quia non tradidi eam Sela filio meo. Attamen ultra non cognovit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Instante autem partu, apparuerunt gemini in utero: atque in ipsa effusione infantium unus protulit manum, in qua obstetrix ligavit coccinum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Iste egredietur prior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Illo vero retrahente manum, egressus est alter: dixitque mulier: Quare divisa est propter te maceria? et ob hanc causam, vocavit nomen ejus Phares.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Postea egressus est frater ejus, in cujus manu erat coccinum: quem appellavit Zara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Igitur Joseph ductus est in \'gyptum, emitque eum Putiphar eunuchus Pharaonis, princeps exercitus, vir ægyptius, de manu Ismaëlitarum, a quibus perductus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Fuitque Dominus cum eo, et erat vir in cunctis prospere agens: habitavitque in domo domini sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'qui optime noverat Dominum esse cum eo, et omnia, quæ gerebat, ab eo dirigi in manu illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Invenitque Joseph gratiam coram domino suo, et ministrabat ei: a quo præpositus omnibus gubernabat creditam sibi domum, et universa quæ ei tradita fuerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'benedixitque Dominus domui \'gyptii propter Joseph, et multiplicavit tam in ædibus quam in agris cunctam ejus substantiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'nec quidquam aliud noverat, nisi panem quo vescebatur. Erat autem Joseph pulchra facie, et decorus aspectu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Post multos itaque dies injecit domina sua oculos suos in Joseph, et ait: Dormi mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Qui nequaquam acquiescens operi nefario, dixit ad eam: Ecce dominus meus, omnibus mihi traditis, ignorat quid habeat in domo sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'nec quidquam est quod non in mea sit potestate, vel non tradiderit mihi, præter te, quæ uxor ejus es: quomodo ergo possum hoc malum facere, et peccare in Deum meum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Hujuscemodi verbis per singulos dies, et mulier molesta erat adolescenti: et ille recusabat stuprum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Accidit autem quadam die ut intraret Joseph domum, et operis quippiam absque arbitris faceret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'et illa, apprehensa lacinia vestimenti ejus, diceret: Dormi mecum. Qui relicto in manu ejus pallio fugit, et egressus est foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Cumque vidisset mulier vestem in manibus suis, et se esse contemptam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'vocavit ad se homines domus suæ, et ait ad eos: En introduxit virum hebræum, ut illuderet nobis: ingressus est ad me, ut coiret mecum: cumque ego succlamassem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'et audisset vocem meam, reliquit pallium quod tenebam, et fugit foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'In argumentum ergo fidei retentum pallium ostendit marito revertenti domum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'et ait: Ingressus est ad me servus hebræus quem adduxisti, ut illuderet mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'cumque audisset me clamare, reliquit pallium quod tenebam, et fugit foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'His auditis dominus, et nimium credulus verbis conjugis, iratus est valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'tradiditque Joseph in carcerem, ubi vincti regis custodiebantur, et erat ibi clausus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Fuit autem Dominus cum Joseph, et misertus illius dedit ei gratiam in conspectu principis carceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Qui tradidit in manu illius universos vinctos qui in custodia tenebantur: et quidquid fiebat, sub ipso erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Nec noverat aliquid, cunctis ei creditis: Dominus enim erat cum illo, et omnia opera ejus dirigebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'His ita gestis, accidit ut peccarent duo eunuchi, pincerna regis \'gypti, et pistor, domino suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Iratusque contra eos Pharao (nam alter pincernis præerat, alter pistoribus),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'misit eos in carcerem principis militum, in quo erat vinctus et Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'At custos carceris tradidit eos Joseph, qui et ministrabat eis: aliquantulum temporis fluxerat, et illi in custodia tenebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Videruntque ambo somnium nocte una, juxta interpretationem congruam sibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'ad quos cum introisset Joseph mane, et vidisset eos tristes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'sciscitatus est eos, dicens: Cur tristior est hodie solito facies vestra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Qui responderunt: Somnium vidimus, et non est qui interpretetur nobis. Dixitque ad eos Joseph: Numquid non Dei est interpretatio? referte mihi quid videritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Narravit prior, præpositus pincernarum, somnium suum: Videbam coram me vitem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'in qua erant tres propagines, crescere paulatim in gemmas, et post flores uvas maturescere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'calicemque Pharaonis in manu mea: tuli ergo uvas, et expressi in calicem quem tenebam, et tradidi poculum Pharaoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Respondit Joseph: Hæc est interpretatio somnii: tres propagines, tres adhuc dies sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'post quos recordabitur Pharao ministerii tui, et restituet te in gradum pristinum: dabisque ei calicem juxta officium tuum, sicut ante facere consueveras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Tantum memento mei, cum bene tibi fuerit, et facias mecum misericordiam: ut suggeras Pharaoni ut educat me de isto carcere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'quia furto sublatus sum de terra Hebræorum, et hic innocens in lacum missus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Videns pistorum magister quod prudenter somnium dissolvisset, ait: Et ego vidi somnium: quod tria canistra farinæ haberem super caput meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'et in uno canistro quod erat excelsius, portare me omnes cibos qui fiunt arte pistoria, avesque comedere ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Respondit Joseph: Hæc est interpretatio somnii: tria canistra, tres adhuc dies sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'post quos auferet Pharao caput tuum, ac suspendet te in cruce, et lacerabunt volucres carnes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Exinde dies tertius natalitius Pharaonis erat: qui faciens grande convivium pueris suis, recordatus est inter epulas magistri pincernarum, et pistorum principis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Restituitque alterum in locum suum, ut porrigeret ei poculum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'alterum suspendit in patibulo, ut conjectoris veritas probaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Et tamen succedentibus prosperis, præpositus pincernarum oblitus est interpretis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Post duos annos vidit Pharao somnium. Putabat se stare super fluvium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'de quo ascendebant septem boves, pulchræ et crassæ nimis: et pascebantur in locis palustribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Aliæ quoque septem emergebant de flumine, fœdæ confectæque macie: et pascebantur in ipsa amnis ripa in locis virentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'devoraveruntque eas, quarum mira species et habitudo corporum erat. Expergefactus Pharao,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'rursum dormivit, et vidit alterum somnium: septem spicæ pullulabant in culmo uno plenæ atque formosæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'aliæ quoque totidem spicæ tenues, et percussæ uredine oriebantur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'devorantes omnium priorum pulchritudinem. Evigilans Pharao post quietem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'et facto mane, pavore perterritus, misit ad omnes conjectores \'gypti, cunctosque sapientes, et accersitis narravit somnium, nec erat qui interpretaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tunc demum reminiscens pincernarum magister, ait: Confiteor peccatum meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'iratus rex servis suis, me et magistrum pistorum retrudi jussit in carcerem principis militum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'ubi una nocte uterque vidimus somnium præsagum futurorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Erat ibi puer hebræus, ejusdem ducis militum famulus: cui narrantes somnia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'audivimus quidquid postea rei probavit eventus; ego enim redditus sum officio meo, et ille suspensus est in cruce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Protinus ad regis imperium eductum de carcere Joseph totonderunt: ac veste mutata obtulerunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Cui ille ait: Vidi somnia, nec est qui edisserat: quæ audivi te sapientissime conjicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Respondit Joseph: Absque me Deus respondebit prospera Pharaoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Narravit ergo Pharao quod viderat: Putabam me stare super ripam fluminis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'et septem boves de amne conscendere, pulchras nimis, et obesis carnibus: quæ in pastu paludis virecta carpebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Et ecce, has sequebantur aliæ septem boves, in tantum deformes et macilentæ, ut numquam tales in terra \'gypti viderim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'quæ, devoratis et consumptis prioribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'nullum saturitatis dedere vestigium: sed simili macie et squalore torpebant. Evigilans, rursus sopore depressus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'vidi somnium. Septem spicæ pullulabant in culmo uno plenæ atque pulcherrimæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Aliæ quoque septem tenues et percussæ uredine, oriebantur e stipula:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'quæ priorum pulchritudinem devoraverunt. Narravi conjectoribus somnium, et nemo est qui edisserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Respondit Joseph: Somnium regis unum est: quæ facturus est Deus, ostendit Pharaoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Septem boves pulchræ, et septem spicæ plenæ, septem ubertatis anni sunt: eamdemque vim somnii comprehendunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Septem quoque boves tenues atque macilentæ, quæ ascenderunt post eas, et septem spicæ tenues, et vento urente percussæ, septem anni venturæ sunt famis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Qui hoc ordine complebuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'ecce septem anni venient fertilitatis magnæ in universa terra \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'quos sequentur septem anni alii tantæ sterilitatis, ut oblivioni tradatur cuncta retro abundantia: consumptura est enim fames omnem terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'et ubertatis magnitudinem perditura est inopiæ magnitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Quod autem vidisti secundo ad eamdem rem pertinens somnium: firmitatis indicium est, eo quod fiat sermo Dei, et velocius impleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nunc ergo provideat rex virum sapientem et industrium, et præficiat eum terræ \'gypti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'qui constituat præpositos per cunctas regiones: et quintam partem fructuum per septem annos fertilitatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'qui jam nunc futuri sunt, congreget in horrea: et omne frumentum sub Pharaonis potestate condatur, serveturque in urbibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Et præparetur futuræ septem annorum fami, quæ oppressura est \'gyptum, et non consumetur terra inopia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Placuit Pharaoni consilium et cunctis ministris ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'locutusque est ad eos: Num invenire poterimus talem virum, qui spiritu Dei plenus sit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Dixit ergo ad Joseph: Quia ostendit tibi Deus omnia quæ locutus es, numquid sapientiorem et consimilem tui invenire potero?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tu eris super domum meam, et ad tui oris imperium cunctus populus obediet: uno tantum regni solio te præcedam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dixitque rursus Pharao ad Joseph: Ecce, constitui te super universam terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Tulitque annulum de manu sua, et dedit eum in manu ejus: vestivitque eum stola byssina, et collo torquem auream circumposuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Fecitque eum ascendere super currum suum secundum, clamante præcone, ut omnes coram eo genu flecterent, et præpositum esse scirent universæ terræ \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Dixit quoque rex ad Joseph: Ego sum Pharao: absque tuo imperio non movebit quisquam manum aut pedem in omni terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Vertitque nomen ejus, et vocavit eum, lingua ægyptiaca, Salvatorem mundi. Deditque illi uxorem Aseneth filiam Putiphare sacerdotis Heliopoleos. Egressus est itaque Joseph ad terram \'gypti');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, '(triginta autem annorum erat quando stetit in conspectu regis Pharaonis), et circuivit omnes regiones \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Venitque fertilitas septem annorum: et in manipulos redactæ segetes congregatæ sunt in horrea \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Omnis etiam frugum abundantia in singulis urbibus condita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Tantaque fuit abundantia tritici, ut arenæ maris coæquaretur, et copia mensuram excederet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Nati sunt autem Joseph filii duo antequam veniret fames: quos peperit ei Aseneth filia Putiphare sacerdotis Heliopoleos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Vocavitque nomen primogeniti Manasses, dicens: Oblivisci me fecit Deus omnium laborum meorum, et domus patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Nomen quoque secundi appellavit Ephraim, dicens: Crescere me fecit Deus in terra paupertatis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Igitur transactis septem ubertatis annis, qui fuerant in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'cœperunt venire septem anni inopiæ, quos prædixerat Joseph: et in universo orbe fames prævaluit, in cuncta autem terra \'gypti panis erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Qua esuriente, clamavit populus ad Pharaonem, alimenta petens. Quibus ille respondit: Ite ad Joseph: et quidquid ipse vobis dixerit, facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Crescebat autem quotidie fames in omni terra: aperuitque Joseph universa horrea, et vendebat \'gyptiis: nam et illos oppresserat fames.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Omnesque provinciæ veniebant in \'gyptum, ut emerent escas, et malum inopiæ temperarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Audiens autem Jacob quod alimenta venderentur in \'gypto, dixit filiis suis: Quare negligitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'audivi quod triticum venundetur in \'gypto: descendite, et emite nobis necessaria, ut possimus vivere, et non consumamur inopia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Descendentes igitur fratres Joseph decem, ut emerent frumenta in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamin domi retento a Jacob, qui dixerat fratribus ejus: Ne forte in itinere quidquam patiatur mali:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'ingressi sunt terram \'gypti cum aliis qui pergebant ad emendum. Erat autem fames in terra Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Et Joseph erat princeps in terra \'gypti, atque ad ejus nutum frumenta populis vendebantur. Cumque adorassent eum fratres sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'et agnovisset eos, quasi ad alienos durius loquebatur, interrogans eos: Unde venistis? Qui responderunt: De terra Chanaan, ut emamus victui necessaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Et tamen fratres ipse cognoscens, non est cognitus ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Recordatusque somniorum, quæ aliquando viderat, ait ad eos: Exploratores estis: ut videatis infirmiora terræ venistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Qui dixerunt: Non est ita, domine, sed servi tui venerunt ut emerent cibos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Omnes filii unius viri sumus: pacifici venimus, nec quidquam famuli tui machinantur mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Quibus ille respondit: Aliter est: immunita terræ hujus considerare venistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'At illi: Duodecim, inquiunt, servi tui, fratres sumus, filii viri unius in terra Chanaan: minimus cum patre nostro est, alius non est super.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Hoc est, ait, quod locutus sum: exploratores estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Jam nunc experimentum vestri capiam: per salutem Pharaonis non egrediemini hinc, donec veniat frater vester minimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Mittite ex vobis unum, et adducat eum: vos autem eritis in vinculis, donec probentur quæ dixistis utrum vera an falsa sint: alioquin per salutem Pharaonis exploratores estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Tradidit ergo illos custodiæ tribus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Die autem tertio eductis de carcere, ait: Facite quæ dixi, et vivetis: Deum enim timeo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si pacifici estis, frater vester unus ligetur in carcere: vos autem abite, et ferte frumenta quæ emistis, in domos vestras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'et fratrem vestrum minimum ad me adducite, ut possim vestros probare sermones, et non moriamini. Fecerunt ut dixerat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'et locuti sunt ad invicem: Merito hæc patimur, quia peccavimus in fratrem nostrum, videntes angustiam animæ illius, dum deprecaretur nos, et non audivimus: idcirco venit super nos ista tribulatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'E quibus unus Ruben, ait: Numquid non dixi vobis: Nolite peccare in puerum: et non audistis me? en sanguis ejus exquiritur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Nesciebant autem quod intelligeret Joseph, eo quod per interpretem loqueretur ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Avertitque se parumper, et flevit: et reversus locutus est ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Tollensque Simeon, et ligans illis præsentibus, jussit ministris ut implerent eorum saccos tritico, et reponerent pecunias singulorum in sacculis suis, datis supra cibariis in viam: qui fecerunt ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'At illi portantes frumenta in asinis suis, profecti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Apertoque unus sacco, ut daret jumento pabulum in diversorio, contemplatus pecuniam in ore sacculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'dixit fratribus suis: Reddita est mihi pecunia, en habetur in sacco. Et obstupefacti, turbatique, mutuo dixerunt: Quidnam est hoc quod fecit nobis Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Veneruntque ad Jacob patrem suum in terram Chanaan, et narraverunt ei omnia quæ accidissent sibi, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Locutus est nobis dominus terræ dure, et putavit nos exploratores esse provinciæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Cui respondimus: Pacifici sumus, nec ullas molimur insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Duodecim fratres uno patre geniti sumus: unus non est super, minimus cum patre nostro est in terra Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Qui ait nobis: Sic probabo quod pacifici sitis: fratrem vestrum unum dimittite apud me, et cibaria domibus vestris necessaria sumite, et abite,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'fratremque vestrum minimum adducite ad me, ut sciam quod non sitis exploratores: et istum, qui tenetur in vinculis, recipere possitis: ac deinceps quæ vultis, emendi habeatis licentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'His dictis, cum frumenta effunderent, singuli repererunt in ore saccorum ligatas pecunias, exterritisque simul omnibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'dixit pater Jacob: Absque liberis me esse fecistis: Joseph non est super, Simeon tenetur in vinculis, et Benjamin auferetis: in me hæc omnia mala reciderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Cui respondit Ruben: Duos filios meos interfice, si non reduxero illum tibi: trade illum in manu mea, et ego eum tibi restituam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'At ille: Non descendet, inquit, filius meus vobiscum: frater ejus mortuus est, et ipse solus remansit: si quid ei adversi acciderit in terra ad quam pergitis, deducetis canos meos cum dolore ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Interim fames omnem terram vehementer premebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Consumptisque cibis quos ex \'gypto detulerant, dixit Jacob ad filios suos: Revertimini, et emite nobis pauxillum escarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Respondit Judas: Denuntiavit nobis vir ille sub attestatione jurisjurandi, dicens: Non videbitis faciem meam, nisi fratrem vestrum minimum adduxeritis vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si ergo vis eum mittere nobiscum, pergemus pariter, et ememus tibi necessaria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'sin autem non vis, non ibimus: vir enim, ut sæpe diximus, denuntiavit nobis, dicens: Non videbitis faciem meam absque fratre vestro minimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Dixit eis Israël: In meam hoc fecistis miseriam, ut indicaretis ei et alium habere vos fratrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'At illi responderunt: Interrogavit nos homo per ordinem nostram progeniem: si pater viveret: si haberemus fratrem: et nos respondimus ei consequenter juxta id quod fuerat sciscitatus: numquid scire poteramus quod dicturus esset: Adducite fratrem vestrum vobiscum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Judas quoque dixit patri suo: Mitte puerum mecum, ut proficiscamur, et possimus vivere: ne moriamur nos et parvuli nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ego suscipio puerum: de manu mea require illum: nisi reduxero, et reddidero eum tibi, ero peccati reus in te omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Si non intercessisset dilatio, jam vice alter venissemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Igitur Israël pater eorum dixit ad eos: Si sic necesse est, facite quod vultis: sumite de optimis terræ fructibus in vasis vestris, et deferte viro munera, modicum resinæ, et mellis, et storacis, stactes, et terebinthi, et amygdalarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Pecuniam quoque duplicem ferte vobiscum: et illam, quam invenistis in sacculis, reportate, ne forte errore factum sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'sed et fratrem vestrum tollite, et ite ad virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Deus autem meus omnipotens faciat vobis eum placabilem: et remittat vobiscum fratrem vestrum quem tenet, et hunc Benjamin: ego autem quasi orbatus absque liberis ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Tulerunt ergo viri munera, et pecuniam duplicem, et Benjamin: descenderuntque in \'gyptum, et steterunt coram Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Quos cum ille vidisset et Benjamin simul, præcepit dispensatori domus suæ, dicens: Introduc viros domum, et occide victimas, et instrue convivium: quoniam mecum sunt comesturi meridie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Fecit ille quod sibi fuerat imperatum, et introduxit viros domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Ibique exterriti, dixerunt mutuo: Propter pecuniam, quam retulimus prius in saccis nostris, introducti sumus: ut devolvat in nos calumniam, et violenter subjiciat servituti et nos, et asinos nostros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Quam ob rem in ipsis foribus accedentes ad dispensatorem domus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'locuti sunt: Oramus, domine, ut audias nos. Jam ante descendimus ut emeremus escas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'quibus emptis, cum venissemus ad diversorium, aperuimus saccos nostros, et invenimus pecuniam in ore saccorum: quam nunc eodem pondere reportavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Sed et aliud attulimus argentum, ut emamus quæ nobis necessaria sunt: non est in nostra conscientia quis posuerit eam in marsupiis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'At ille respondit: Pax vobiscum, nolite timere: Deus vester, et Deus patris vestri, dedit vobis thesauros in saccis vestris: nam pecuniam, quam dedistis mihi, probatam ego habeo. Eduxitque ad eos Simeon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Et introductis domum, attulit aquam, et laverunt pedes suos, deditque pabulum asinis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Illi vero parabant munera, donec ingrederetur Joseph meridie: audierant enim quod ibi comesturi essent panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Igitur ingressus est Joseph domum suam, obtuleruntque ei munera, tenentes in manibus suis: et adoraverunt proni in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'At ille, clementer resalutatis eis, interrogavit eos, dicens: Salvusne est pater vester senex, de quo dixeratis mihi? adhuc vivit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Qui responderunt: Sospes est servus tuus pater noster, adhuc vivit. Et incurvati, adoraverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Attollens autem Joseph oculos, vidit Benjamin fratrem suum uterinum, et ait: Iste est frater vester parvulus, de quo dixeratis mihi? Et rursum: Deus, inquit, misereatur tui, fili mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Festinavitque, quia commota fuerant viscera ejus super fratre suo, et erumpebant lacrimæ: et introiens cubiculum flevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Rursumque lota facie egressus, continuit se, et ait: Ponite panes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Quibus appositis, seorsum Joseph, et seorsum fratribus, \'gyptiis quoque qui vescebantur simul, seorsum (illicitum est enim \'gyptiis comedere cum Hebræis, et profanum putant hujuscemodi convivium)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'sederunt coram eo, primogenitus juxta primogenita sua, et minimus juxta ætatem suam. Et mirabantur nimis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'sumptis partibus quas ab eo acceperant: majorque pars venit Benjamin, ita ut quinque partibus excederet. Biberuntque et inebriati sunt cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Præcepit autem Joseph dispensatori domus suæ, dicens: Imple saccos eorum frumento, quantum possunt capere: et pone pecuniam singulorum in summitate sacci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Scyphum autem meum argenteum, et pretium quod dedit tritici, pone in ore sacci junioris. Factumque est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Et orto mane, dimissi sunt cum asinis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Jamque urbem exierant, et processerant paululum: tunc Joseph accersito dispensatore domus, Surge, inquit, et persequere viros: et apprehensis dicito: Quare reddidistis malum pro bono?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'scyphus, quem furati estis, ipse est in quo bibit dominus meus, et in quo augurari solet: pessimam rem fecistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Fecit ille ut jusserat: et apprehensis per ordinem locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Qui responderunt: Quare sic loquitur dominus noster, ut servi tui tantum flagitii commiserint?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'pecuniam, quam invenimus in summitate saccorum, reportavimus ad te de terra Chanaan: et quomodo consequens est ut furati simus de domo domini tui aurum vel argentum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'apud quemcumque fuerit inventum servorum tuorum quod quæris, moriatur, et nos erimus servi domini nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Qui dixit eis: Fiat juxta vestram sententiam: apud quemcumque fuerit inventum, ipse sit servus meus, vos autem eritis innoxii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Itaque festinato deponentes in terram saccos, aperuerunt singuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Quos scrutatus, incipiens a majore usque ad minimum, invenit scyphum in sacco Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'At illi, scissis vestibus, oneratisque rursum asinis, reversi sunt in oppidum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Primusque Judas cum fratribus ingressus est ad Joseph (necdum enim de loco abierat) omnesque ante eum pariter in terram corruerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Quibus ille ait: Cur sic agere voluistis? an ignoratis quod non sit similis mei in augurandi scientia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Cui Judas: Quid respondebimus, inquit, domino meo? vel quid loquemur, aut juste poterimus obtendere? Deus invenit iniquitatem servorum tuorum: en omnes servi sumus domini mei, et nos, et apud quem inventus est scyphus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Respondit Joseph: Absit a me ut sic agam: qui furatus est scyphum, ipse sit servus meus: vos autem abite liberi ad patrem vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Accedens autem propius Judas, confidenter ait: Oro, domine mi, loquatur servus tuus verbum in auribus tuis, et ne irascaris famulo tuo: tu es enim post Pharaonem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'dominus meus. Interrogasti prius servos tuos: Habetis patrem aut fratrem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'et nos respondimus tibi domino meo: Est nobis pater senex, et puer parvulus, qui in senectute illius natus est: cujus uterinus frater mortuus est: et ipsum solum habet mater sua, pater vero tenere diligit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Dixistique servis tuis: Adducite eum ad me, et ponam oculos meos super illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Suggessimus domino meo: Non potest puer relinquere patrem suum: si enim illum dimiserit, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Et dixisti servis tuis: Nisi venerit frater vester minimus vobiscum, non videbitis amplius faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Cum ergo ascendissemus ad famulum tuum patrem nostrum, narravimus ei omnia quæ locutus est dominus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Et dixit pater noster: Revertimini, et emite nobis parum tritici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Cui diximus: Ire non possumus: si frater noster minimus descenderit nobiscum, proficiscemur simul: alioquin illo absente, non audemus videre faciem viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Ad quæ ille respondit: Vos scitis quod duos genuerit mihi uxor mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Egressus est unus, et dixistis: Bestia devoravit eum: et hucusque non comparet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Si tuleritis et istum, et aliquid ei in via contigerit, deducetis canos meos cum mœrore ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Igitur si intravero ad servum tuum patrem nostrum, et puer defuerit (cum anima illius ex hujus anima pendeat),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'videritque eum non esse nobiscum, morietur, et deducent famuli tui canos ejus cum dolore ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ego proprie servus tuus sim qui in meam hunc recepi fidem, et spopondi dicens: Nisi reduxero eum, peccati reus ero in patrem meum omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Manebo itaque servus tuus pro puero in ministerio domini mei, et puer ascendat cum fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Non enim possum redire ad patrem meum, absente puero: ne calamitatis, quæ oppressura est patrem meum, testis assistam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Non se poterat ultra cohibere Joseph multis coram astantibus: unde præcepit ut egrederentur cuncti foras, et nullus interesset alienus agnitioni mutuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Elevavitque vocem cum fletu, quam audierunt \'gyptii, omnisque domus Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Et dixit fratribus suis: Ego sum Joseph: adhuc pater meus vivit? Non poterant respondere fratres nimio terrore perterriti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Ad quos ille clementer: Accedite, inquit, ad me. Et cum accessissent prope: Ego sum, ait, Joseph, frater vester, quem vendidistis in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Nolite pavere, neque vobis durum esse videatur quod vendidistis me in his regionibus: pro salute enim vestra misit me Deus ante vos in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Biennium est enim quod cœpit fames esse in terra: et adhuc quinque anni restant, quibus nec arari poterit, nec meti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Præmisitque me Deus ut reservemini super terram, et escas ad vivendum habere possitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Non vestro consilio, sed Dei voluntate huc missus sum: qui fecit me quasi patrem Pharaonis, et dominum universæ domus ejus, ac principem in omni terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Festinate, et ascendite ad patrem meum, et dicetis ei: Hæc mandat filius tuus Joseph: Deus fecit me dominum universæ terræ \'gypti: descende ad me, ne moreris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'et habitabis in terra Gessen: erisque juxta me tu, et filii tui, et filii filiorum tuorum, oves tuæ, et armenta tua, et universa quæ possides:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'ibique te pascam (adhuc enim quinque anni residui sunt famis) ne et tu pereas, et domus tua, et omnia quæ possides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'En oculi vestri, et oculi fratris mei Benjamin, vident quod os meum loquatur ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Nuntiate patri meo universam gloriam meam, et cuncta quæ vidistis in \'gypto: festinate, et adducite eum ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Cumque amplexatus recidisset in collum Benjamin fratris sui, flevit: illo quoque similiter flente super collum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Osculatusque est Joseph omnes fratres suos, et ploravit super singulos: post quæ ausi sunt loqui ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Auditumque est, et celebri sermone vulgatum in aula regis: Venerunt fratres Joseph: et gavisus est Pharao, atque omnis familia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Dixitque ad Joseph ut imperaret fratribus suis, dicens: Onerantes jumenta, ite in terram Chanaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'et tollite inde patrem vestrum et cognationem, et venite ad me: et ego dabo vobis omnia bona \'gypti, ut comedatis medullam terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Præcipe etiam ut tollant plaustra de terra \'gypti, ad subvectionem parvulorum suorum ac conjugum: et dicito: Tollite patrem vestrum, et properate quantocius venientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Nec dimittatis quidquam de supellectili vestra: quia omnes opes \'gypti vestræ erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Feceruntque filii Israël ut eis mandatum fuerat. Quibus dedit Joseph plaustra, secundum Pharaonis imperium, et cibaria in itinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Singulis quoque proferri jussit binas stolas: Benjamin vero dedit trecentos argenteos cum quinque stolis optimis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'tantumdem pecuniæ et vestium mittens patri suo, addens et asinos decem, qui subveherent ex omnibus divitiis \'gypti, et totidem asinas, triticum in itinere, panesque portantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Dimisit ergo fratres suos, et proficiscentibus ait: Ne irascamini in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Qui ascendentes ex \'gypto, venerunt in terram Chanaan ad patrem suum Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Et nuntiaverunt ei, dicentes: Joseph filius tuus vivit: et ipse dominatur in omni terra \'gypti. Quo audito Jacob, quasi de gravi somno evigilans, tamen non credebat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Illi e contra referebant omnem ordinem rei. Cumque vidisset plaustra et universa quæ miserat, revixit spiritus ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'et ait: Sufficit mihi si adhuc Joseph filius meus vivit: vadam, et videbo illum antequam moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Profectusque Israël cum omnibus quæ habebat, venit ad Puteum juramenti: et mactatis ibi victimis Deo patris sui Isaac,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'audivit eum per visionem noctis vocantem se, et dicentem sibi: Jacob, Jacob. Cui respondit: Ecce adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Ait illi Deus: Ego sum fortissimus Deus patris tui: noli timere, descende in \'gyptum, quia in gentem magnam faciam te ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ego descendam tecum illuc, et ego inde adducam te revertentem: Joseph quoque ponet manus suas super oculos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Surrexit autem Jacob a Puteo juramenti: tuleruntque eum filii cum parvulis et uxoribus suis in plaustris quæ miserat Pharao ad portandum senem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'et omnia quæ possederat in terra Chanaan: venitque in \'gyptum cum omni semine suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'filii ejus, et nepotes, filiæ, et cuncta simul progenies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Hæc sunt autem nomina filiorum Israël, qui ingressi sunt in \'gyptum, ipse cum liberis suis. Primogenitus Ruben.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Filii Ruben: Henoch et Phallu et Hesron et Charmi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Filii Simeon: Jamuel et Jamin et Ahod, et Jachin et Sohar, et Saul filius Chanaanitidis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Filii Levi: Gerson et Caath et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Filii Juda: Her et Onan et Sela et Phares et Zara; mortui sunt autem Her et Onan in terra Chanaan. Natique sunt filii Phares: Hesron et Hamul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Filii Issachar: Thola et Phua et Job et Semron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Filii Zabulon: Sared et Elon et Jahelel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Hi filii Liæ quos genuit in Mesopotamia Syriæ cum Dina filia sua: omnes animæ filiorum ejus et filiarum, triginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Filii Gad: Sephion et Haggi et Suni et Esebon et Heri et Arodi et Areli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Filii Aser: Jamne et Jesua et Jessui et Beria, Sara quoque soror eorum. Filii Beria: Heber et Melchiel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Hi filii Zelphæ, quam dedit Laban Liæ filiæ suæ: et hos genuit Jacob sedecim animas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Filii Rachel uxoris Jacob: Joseph et Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Natique sunt Joseph filii in terra \'gypti, quos genuit ei Aseneth filia Putiphare sacerdotis Heliopoleos: Manasses et Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Filii Benjamin: Bela et Bechor et Asbel et Gera et Naaman et Echi et Ros et Mophim et Ophim et Ared.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Hi filii Rachel quos genuit Jacob: omnes animæ, quatuordecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Filii Dan: Husim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Filii Nephthali: Jasiel et Guni et Jeser et Sallem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Hi filii Balæ, quam dedit Laban Racheli filiæ suæ: et hos genuit Jacob: omnes animæ, septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Cunctæ animæ, quæ ingressæ sunt cum Jacob in \'gyptum, et egressæ sunt de femore illius, absque uxoribus filiorum ejus, sexaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Filii autem Joseph, qui nati sunt ei in terra \'gypti, animæ duæ. Omnes animæ domus Jacob, quæ ingressæ sunt in \'gyptum, fuere septuaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Misit autem Judam ante se ad Joseph, ut nuntiaret ei, et occurreret in Gessen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Quo cum pervenisset, juncto Joseph curro suo, ascendit obviam patri suo ad eumdem locum: vidensque eum, irruit super collum ejus, et inter amplexus flevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Dixitque pater ad Joseph: Jam lætus moriar, quia vidi faciem tuam, et superstitem te relinquo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'At ille locutus est ad fratres suos, et ad omnem domum patris sui: Ascendam, et nuntiabo Pharaoni, dicamque ei: Fratres mei, et domus patris mei, qui erant in terra Chanaan, venerunt ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'et sunt viri pastores ovium, curamque habent alendorum gregum: pecora sua, et armenta, et omnia quæ habere potuerunt, adduxerunt secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Cumque vocaverit vos, et dixerit: Quod est opus vestrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'respondebitis: Viri pastores sumus servi tui, ab infantia nostra usque in præsens, et nos et patres nostri. Hæc autem dicetis, ut habitare possitis in terra Gessen: quia detestantur \'gyptii omnes pastores ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Ingressus ergo Joseph nuntiavit Pharaoni, dicens: Pater meus et fratres, oves eorum et armenta, et cuncta quæ possident, venerunt de terra Chanaan: et ecce consistunt in terra Gessen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Extremos quoque fratrum suorum quinque viros constituit coram rege:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'quos ille interrogavit: Quid habetis operis? Responderunt: Pastores ovium sumus servi tui, et nos et patres nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Ad peregrinandum in terra tua venimus: quoniam non est herba gregibus servorum tuorum, ingravescente fame in terra Chanaan: petimusque ut esse nos jubeas servos tuos in terra Gessen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Dixit itaque rex ad Joseph: Pater tuus et fratres tui venerunt ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Terra \'gypti in conspectu tuo est: in optimo loco fac eos habitare, et trade eis terram Gessen. Quod si nosti in eis esse viros industrios, constitue illos magistros pecorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Post hæc introduxit Joseph patrem suum ad regem, et statuit eum coram eo: qui benedicens illi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'et interrogatus ab eo: Quot sunt dies annorum vitæ tuæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'respondit: Dies peregrinationis meæ centum triginta annorum sunt, parvi et mali, et non pervenerunt usque ad dies patrum meorum quibus peregrinati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Et benedicto rege, egressus est foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph vero patri et fratribus suis dedit possessionem in \'gypto in optimo terræ loco, Ramesses, ut præceperat Pharao.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et alebat eos, omnemque domum patris sui, præbens cibaria singulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'In toto enim orbe panis deerat, et oppresserat fames terram, maxime \'gypti et Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'E quibus omnem pecuniam congregavit pro venditione frumenti, et intulit eam in ærarium regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Cumque defecisset emptoribus pretium, venit cuncta \'gyptus ad Joseph, dicens: Da nobis panes: quare morimur coram te, deficiente pecunia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Quibus ille respondit: Adducite pecora vestra, et dabo vobis pro eis cibos, si pretium non habetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Quæ cum adduxissent, dedit eis alimenta pro equis, et ovibus, et bobus, et asinis: sustentavitque eos illo anno pro commutatione pecorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Venerunt quoque anno secundo, et dixerunt ei: Non celabimus dominum nostrum quod deficiente pecunia, pecora simul defecerunt: nec clam te est, quod absque corporibus et terra nihil habeamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Cur ergo moriemur te vidente? et nos et terra nostra tui erimus: eme nos in servitutem regiam, et præbe semina, ne pereunte cultore redigatur terra in solitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Emit igitur Joseph omnem terram \'gypti, vendentibus singulis possessiones suas præ magnitudine famis. Subjecitque eam Pharaoni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'et cunctos populos ejus a novissimis terminis \'gypti usque ad extremos fines ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'præter terram sacerdotum, quæ a rege tradita fuerat eis: quibus et statuta cibaria ex horreis publicis præbebantur, et idcirco non sunt compulsi vendere possessiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Dixit ergo Joseph ad populos: En ut cernitis, et vos et terram vestram Pharao possidet: accipite semina, et serite agros,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'ut fruges habere possitis. Quintam partem regi dabitis: quatuor reliquas permitto vobis in sementem, et in cibum familiis et liberis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Qui responderunt: Salus nostra in manu tua est: respiciat nos tantum dominus noster, et læti serviemus regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Ex eo tempore usque in præsentem diem, in universa terra \'gypti regibus quinta pars solvitur, et factum est quasi in legem, absque terra sacerdotali, quæ libera ab hac conditione fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Habitavit ergo Israël in \'gypto, id est, in terra Gessen, et possedit eam: auctusque est, et multiplicatus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Et vixit in ea decem et septem annis: factique sunt omnes dies vitæ illius, centum quadraginta septem annorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Cumque appropinquare cerneret diem mortis suæ, vocavit filium suum Joseph, et dixit ad eum: Si inveni gratiam in conspectu tuo, pone manum tuam sub femore meo: et facies mihi misericordiam et veritatem, ut non sepelias me in \'gypto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sed dormiam cum patribus meis, et auferas me de terra hac, condasque in sepulchro majorum meorum. Cui respondit Joseph: Ego faciam quod jussisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Et ille: Jura ergo, inquit, mihi. Quo jurante, adoravit Israël Deum, conversus ad lectuli caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'His ita transactis, nuntiatum est Joseph quod ægrotaret pater suus: qui, assumptis duobus filiis Manasse et Ephraim, ire perrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Dictumque est seni: Ecce filius tuus Joseph venit ad te. Qui confortatus sedit in lectulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Et ingresso ad se ait: Deus omnipotens apparuit mihi in Luza, quæ est in terra Chanaan: benedixitque mihi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'et ait: Ego te augebo et multiplicabo, et faciam te in turbas populorum: daboque tibi terram hanc, et semini tuo post te in possessionem sempiternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Duo ergo filii tui, qui nati sunt tibi in terra \'gypti antequam huc venirem ad te, mei erunt: Ephraim et Manasses, sicut Ruben et Simeon reputabuntur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Reliquos autem quos genueris post eos, tui erunt, et nomine fratrum suorum vocabuntur in possessionibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Mihi enim, quando veniebam de Mesopotamia, mortua est Rachel in terra Chanaan in ipso itinere, eratque vernum tempus: et ingrediebar Ephratam, et sepelivi eam juxta viam Ephratæ, quæ alio nomine appellatur Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Videns autem filios ejus dixit ad eum: Qui sunt isti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Respondit: Filii mei sunt, quos donavit mihi Deus in hoc loco. Adduc, inquit, eos ad me, ut benedicam illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Oculi enim Israël caligabant præ nimia senectute, et clare videre non poterat. Applicitosque ad se, deosculatus et circumplexus eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'dixit ad filium suum: Non sum fraudatus aspectu tuo: insuper ostendit mihi Deus semen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Cumque tulisset eos Joseph de gremio patris, adoravit pronus in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Et posuit Ephraim ad dexteram suam, id est, ad sinistram Israël: Manassen vero in sinistra sua, ad dexteram scilicet patris, applicuitque ambos ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Qui extendens manum dexteram, posuit super caput Ephraim minoris fratris: sinistram autem super caput Manasse qui major natu erat, commutans manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Benedixitque Jacob filiis Joseph, et ait: Deus, in cujus conspectu ambulaverunt patres mei Abraham, et Isaac; Deus qui pascit me ab adolescentia mea usque in præsentem diem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'angelus, qui eruit me de cunctis malis, benedicat pueris istis: et invocetur super eos nomen meum, nomina quoque patrum meorum Abraham et Isaac, et crescant in multitudinem super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Videns autem Joseph quod posuisset pater suus dexteram manum super caput Ephraim, graviter accepit: et apprehensam manum patris levare conatus est de capite Ephraim, et transferre super caput Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Dixitque ad patrem: Non ita convenit, pater: quia hic est primogenitus, pone dexteram tuam super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Qui renuens, ait: Scio, fili mi, scio: et iste quidem erit in populos, et multiplicabitur: sed frater ejus minor, major erit illo: et semen illius crescet in gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Benedixitque eis in tempore illo, dicens: In te benedicetur Israël, atque dicetur: Faciat tibi Deus sicut Ephraim, et sicut Manasse. Constituitque Ephraim ante Manassen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Et ait ad Joseph filium suum: En ego morior, et erit Deus vobiscum, reducetque vos ad terram patrum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Do tibi partem unam extra fratres tuos, quam tuli de manu Amorrhæi in gladio et arcu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Vocavit autem Jacob filios suos, et ait eis: Congregamini, ut annuntiem quæ ventura sunt vobis in diebus novissimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Congregamini, et audite, filii Jacob, audite Israël patrem vestrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, primogenitus meus, tu fortitudo mea, et principium doloris mei; prior in donis, major in imperio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Effusus es sicut aqua, non crescas: quia ascendisti cubile patris tui, et maculasti stratum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon et Levi fratres vasa iniquitatis bellantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'In consilium eorum non veniat anima mea, et in cœtu illorum non sit gloria mea: quia in furore suo occiderunt virum, et in voluntate sua suffoderunt murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maledictus furor eorum, quia pertinax: et indignatio eorum, quia dura: dividam eos in Jacob, et dispergam eos in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, te laudabunt fratres tui: manus tua in cervicibus inimicorum tuorum, adorabunt te filii patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Catulus leonis Juda: ad prædam, fili mi, ascendisti: requiescens accubuisti ut leo, et quasi leæna: quis suscitabit eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Non auferetur sceptrum de Juda, et dux de femore ejus, donec veniat qui mittendus est, et ipse erit expectatio gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Ligans ad vineam pullum suum, et ad vitem, o fili mi, asinam suam, lavabit in vino stolam suam et in sanguine uvæ pallium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Pulchriores sunt oculi ejus vino, et dentes ejus lacte candidiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon in littore maris habitabit, et in statione navium pertingens usque ad Sidonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issachar asinus fortis accubans inter terminos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Vidit requiem, quod esset bona et terram, quod optima: et supposuit humerum suum ad portandum, factusque est tributis serviens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan judicabit populum suum sicut et alia tribus in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Fiat Dan coluber in via, cerastes in semita, mordens ungulas equi, ut cadat ascensor ejus retro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Salutare tuum expectabo, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, accinctus præliabitur ante eum: et ipse accingetur retrorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Aser, pinguis panis ejus, et præbebit delicias regibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephthali, cervus emissus, et dans eloquia pulchritudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Filius accrescens Joseph, filius accrescens et decorus aspectu: filiæ discurrerunt super murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Sed exasperaverunt eum et jurgati sunt, invideruntque illi habentes jacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Sedit in forti arcus ejus, et dissoluta sunt vincula brachiorum et manuum illius per manus potentis Jacob: inde pastor egressus est, lapis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Deus patris tui erit adjutor tuus, et omnipotens benedicet tibi benedictionibus cæli desuper, benedictionibus abyssi jacentis deorsum, benedictionibus uberum et vulvæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Benedictiones patris tui confortatæ sunt benedictionibus patrum ejus, donec veniret desiderium collium æternorum: fiant in capite Joseph, et in vertice Nazaræi inter fratres suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin lupus rapax, mane comedat prædam, et vespere dividet spolia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Omnes hi in tribubus Israël duodecim: hæc locutus est eis pater suus, benedixitque singulis benedictionibus propriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Et præcepit eis, dicens: Ego congregor ad populum meum: sepelite me cum patribus meis in spelunca duplici quæ est in agro Ephron Hethæi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'contra Mambre in terra Chanaan, quam emit Abraham cum agro ab Ephron Hethæo in possessionem sepulchri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ibi sepelierunt eum, et Saram uxorem ejus: ibi sepultus est Isaac cum Rebecca conjuge sua: ibi et Lia condita jacet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Finitisque mandatis quibus filios instruebat, collegit pedes suos super lectulum, et obiit: appositusque est ad populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Quod cernens Joseph, ruit super faciem patris, flens et deosculans eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Præcepitque servis suis medicis ut aromatibus condirent patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Quibus jussa explentibus, transierunt quadraginta dies: iste quippe mos erat cadaverum conditorum: flevitque eum \'gyptus septuaginta diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Et expleto planctus tempore, locutus est Joseph ad familiam Pharaonis: Si inveni gratiam in conspectu vestro, loquimini in auribus Pharaonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'eo quod pater meus adjuraverit me dicens: En morior: in sepulchro meo, quod fodi mihi in terra Chanaan, sepelies me. Ascendam igitur, et sepeliam patrem meum, ac revertar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Dixitque ei Pharao: Ascende, et sepeli patrem tuum sicut adjuratus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Quo ascendente, ierunt cum eo omnes senes domus Pharaonis, cunctique majores natu terræ \'gypti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'domus Joseph cum fratribus suis, absque parvulis, et gregibus atque armentis, quæ dereliquerant in terra Gessen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Habuit quoque in comitatu currus et equites: et facta est turba non modica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Veneruntque ad Aream Atad, quæ sita est trans Jordanem: ubi celebrantes exequias planctu magno atque vehementi impleverunt septem dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Quod cum vidissent habitatores terræ Chanaan, dixerunt: Planctus magnus est iste \'gyptiis. Et idcirco vocatum est nomen loci illius, Planctus \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Fecerunt ergo filii Jacob sicut præceperat eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'et portantes eum in terram Chanaan, sepelierunt eum in spelunca duplici, quam emerat Abraham cum agro in possessionem sepulchri ab Ephron Hethæo, contra faciem Mambre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Reversusque est Joseph in \'gyptum cum fratribus suis, et omni comitatu, sepulto patre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Quo mortuo, timentes fratres ejus, et mutuo colloquentes: Ne forte memor sit injuriæ quam passus est, et reddat nobis omne malum quod fecimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'mandaverunt ei dicentes: Pater tuus præcepit nobis antequam moreretur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'ut hæc tibi verbis illius diceremus: Obsecro ut obliviscaris sceleris fratrum tuorum, et peccati atque malitiæ quam exercuerunt in te: nos quoque oramus ut servis Dei patris tui dimittas iniquitatem hanc. Quibus auditis flevit Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Veneruntque ad eum fratres sui: et proni adorantes in terram, dixerunt: Servi tui sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Quibus ille respondit: Nolite timere: num Dei possumus resistere voluntati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vos cogitastis de me malum: sed Deus vertit illud in bonum, ut exaltaret me, sicut in præsentiarum cernitis, et salvos faceret multos populos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Nolite timere: ego pascam vos et parvulos vestros: consolatusque est eos, et blande ac leniter est locutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Et habitavit in \'gypto cum omni domo patris sui: vixitque centum decem annis. Et vidit Ephraim filios usque ad tertiam generationem. Filii quoque Machir filii Manasse nati sunt in genibus Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Quibus transactis, locutus est fratribus suis: Post mortem meam Deus visitabit vos, et ascendere vos faciet de terra ista ad terram quam juravit Abraham, Isaac et Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Cumque adjurasset eos atque dixisset: Deus visitabit vos, asportate ossa mea vobiscum de loco isto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'mortuus est, expletis centum decem vitæ suæ annis. Et conditus aromatibus, repositus est in loculo in \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Hæc sunt nomina filiorum Israël qui ingressi sunt in \'gyptum cum Jacob: singuli cum domibus suis introierunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi, Judas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachar, Zabulon et Benjamin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan et Nephthali, Gad et Aser.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Erant igitur omnes animæ eorum qui egressi sunt de femore Jacob, septuaginta: Joseph autem in \'gypto erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Quo mortuo, et universis fratribus ejus, omnique cognatione illa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'filii Israël creverunt, et quasi germinantes multiplicati sunt: ac roborati nimis, impleverunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Surrexit interea rex novus super \'gyptum, qui ignorabat Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Et ait ad populum suum: Ecce, populus filiorum Israël multus, et fortior nobis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Venite, sapienter opprimamus eum, ne forte multiplicetur: et si ingruerit contra nos bellum, addatur inimicis nostris, expugnatisque nobis egrediatur de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Præposuit itaque eis magistros operum, ut affligerent eos oneribus: ædificaveruntque urbes tabernaculorum Pharaoni, Phithom et Ramesses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Quantoque opprimebant eos, tanto magis multiplicabantur, et crescebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'oderantque filios Israël \'gyptii, et affligebant illudentes eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'atque ad amaritudinem perducebant vitam eorum operibus duris luti et lateris, omnique famulatu, quo in terræ operibus premebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Dixit autem rex \'gypti obstetricibus Hebræorum, quarum una vocabatur Sephora, altera Phua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'præcipiens eis: Quando obstetricabitis Hebræas, et partus tempus advenerit: si masculus fuerit, interficite eum: si femina, reservate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Timuerunt autem obstetrices Deum, et non fecerunt juxta præceptum regis \'gypti, sed conservabant mares.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Quibus ad se accersitis, rex ait: Quidnam est hoc quod facere voluistis, ut pueros servaretis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Quæ responderunt: Non sunt Hebreæ sicut ægyptiæ mulieres: ipsæ enim obstetricandi habent scientiam, et priusquam veniamus ad eas, pariunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Bene ergo fecit Deus obstetricibus: et crevit populus, confortatusque est nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Et quia timuerunt obstetrices Deum, ædificavit eis domos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Præcepit ergo Pharao omni populo suo, dicens: Quidquid masculini sexus natum fuerit, in flumen projicite: quidquid feminini, reservate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Egressus est post hæc vir de domo Levi: et accepit uxorem stirpis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Quæ concepit, et peperit filium: et videns eum elegantem, abscondit tribus mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Cumque jam celare non posset, sumpsit fiscellam scirpeam, et linivit eam bitumine ac pice: posuitque intus infantulum, et exposuit eum in carecto ripæ fluminis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'stante procul sorore ejus, et considerante eventum rei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Ecce autem descendebat filia Pharaonis ut lavaretur in flumine: et puellæ ejus gradiebantur per crepidinem alvei. Quæ cum vidisset fiscellam in papyrione, misit unam e famulabus suis: et allatam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'aperiens, cernensque in ea parvulum vagientem, miserta ejus, ait: De infantibus Hebræorum est hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Cui soror pueri: Vis, inquit, ut vadam, et vocem tibi mulierem hebræam, quæ nutrire possit infantulum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Respondit: Vade. Perrexit puella et vocavit matrem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Ad quam locuta filia Pharaonis: Accipe, ait, puerum istum, et nutri mihi: ego dabo tibi mercedem tuam. Suscepit mulier, et nutrivit puerum: adultumque tradidit filiæ Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Quem illa adoptavit in locum filii, vocavitque nomen ejus Moyses, dicens: Quia de aqua tuli eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'In diebus illis postquam creverat Moyses, egressus est ad fratres suos: viditque afflictionem eorum, et virum ægyptium percutientem quemdam de Hebræis fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Cumque circumspexisset huc atque illuc, et nullum adesse vidisset, percussum \'gyptium abscondit sabulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Et egressus die altero conspexit duos Hebræos rixantes: dixitque ei qui faciebat injuriam: Quare percutis proximum tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Qui respondit: Quis te constituit principem et judicem super nos? num occidere me tu vis, sicut heri occidisti \'gyptium? Timuit Moyses, et ait: Quomodo palam factum est verbum istud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Audivitque Pharao sermonem hunc, et quærebat occidere Moysen: qui fugiens de conspectu ejus, moratus est in terra Madian, et sedit juxta puteum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Erant autem sacerdoti Madian septem filiæ, quæ venerunt ad hauriendam aquam: et impletis canalibus adaquare cupiebant greges patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Supervenere pastores, et ejecerunt eas: surrexitque Moyses, et defensis puellis, adaquavit oves earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Quæ cum revertissent ad Raguel patrem suum, dixit ad eas: Cur velocius venistis solito?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Responderunt: Vir ægyptius liberavit nos de manu pastorum: insuper et hausit aquam nobiscum, potumque dedit ovibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'At ille: Ubi est? inquit: quare dimisistis hominem? vocate eum ut comedat panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Juravit ergo Moyses quod habitaret cum eo. Accepitque Sephoram filiam ejus uxorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'quæ peperit ei filium, quem vocavit Gersam, dicens: Advena fui in terra aliena. Alterum vero peperit, quem vocavit Eliezer, dicens: Deus enim patris mei adjutor meus eripuit me de manu Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Post multum vero tempore mortuus est rex \'gypti: et ingemiscentes filii Israël, propter opera vociferati sunt: ascenditque clamor eorum ad Deum ab operibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Et audivit gemitum eorum, ac recordatus est fœderis quod pepigit cum Abraham, Isaac et Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Et respexit Dominus filios Israël et cognovit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moyses autem pascebat oves Jethro soceri sui sacerdotis Madian: cumque minasset gregem ad interiora deserti, venit ad montem Dei Horeb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Apparuitque ei Dominus in flamma ignis de medio rubi: et videbat quod rubus arderet, et non combureretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Dixit ergo Moyses: Vadam, et videbo visionem hanc magnam, quare non comburatur rubus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Cernens autem Dominus quod pergeret ad videndum, vocavit eum de medio rubi, et ait: Moyses, Moyses. Qui respondit: Adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'At ille: Ne appropies, inquit, huc: solve calceamentum de pedibus tuis: locus enim, in quo stas, terra sancta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Et ait: Ego sum Deus patris tui, Deus Abraham, Deus Isaac et Deus Jacob. Abscondit Moyses faciem suam: non enim audebat aspicere contra Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Cui ait Dominus: Vidi afflictionem populi mei in \'gypto, et clamorem ejus audivi propter duritiam eorum qui præsunt operibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'et sciens dolorem ejus, descendi ut liberem eum de manibus \'gyptiorum, et educam de terra illa in terram bonam, et spatiosam, in terram quæ fluit lacte et melle, ad loca Chananæi et Hethæi, et Amorrhæi, et Pherezæi, et Hevæi, et Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Clamor ergo filiorum Israël venit ad me: vidique afflictionem eorum, qua ab \'gyptiis opprimuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Sed veni, et mittam te ad Pharaonem, ut educas populum meum, filios Israël, de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Dixitque Moyses ad Deum: Quis sum ego ut vadam ad Pharaonem, et educam filios Israël de \'gypto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Qui dixit ei: Ego ero tecum: et hoc habebis signum, quod miserim te: cum eduxeris populum meum de \'gypto, immolabis Deo super montem istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Ait Moyses ad Deum: Ecce ego vadam ad filios Israël, et dicam eis: Deus patrum vestrorum misit me ad vos. Si dixerint mihi: Quod est nomen ejus? quid dicam eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Dixit Deus ad Moysen: Ego sum qui sum. Ait: Sic dices filiis Israël: Qui est, misit me ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Dixitque iterum Deus ad Moysen: Hæc dices filiis Israël: Dominus Deus patrum vestrorum, Deus Abraham, Deus Isaac et Deus Jacob, misit me ad vos: hoc nomen mihi est in æternum, et hoc memoriale meum in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Vade, et congrega seniores Israël, et dices ad eos: Dominus Deus patrum vestrorum apparuit mihi, Deus Abraham, Deus Isaac et Deus Jacob, dicens: Visitans visitavi vos: et vidi omnia quæ acciderunt vobis in \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Et dixi ut educam vos de afflictione \'gypti in terram Chananæi, et Hethæi, et Amorrhæi, et Pherezæi, et Hevæi, et Jebusæi, ad terram fluentem lacte et melle.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Et audient vocem tuam: ingredierisque tu, et seniores Israël, ad regem \'gypti, et dices ad eum: Dominus Deus Hebræorum vocavit nos: ibimus viam trium dierum in solitudinem, ut immolemus Domino Deo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Sed ego scio quod non dimittet vos rex \'gypti ut eatis nisi per manum validam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Extendam enim manum meam, et percutiam \'gyptum in cunctis mirabilibus meis, quæ facturus sum in medio eorum: post hæc dimittet vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Daboque gratiam populo huic coram \'gyptiis: et cum egrediemini, non exibitis vacui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'sed postulabit mulier a vicina sua et ab hospita sua, vasa argentea et aurea, ac vestes: ponetisque eas super filios et filias vestras, et spoliabitis \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Respondens Moyses ait: Non credent mihi, neque audient vocem meam, sed dicent: Non apparuit tibi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Dixit ergo ad eum: Quid est quod tenes in manu tua? Respondit: Virga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Dixitque Dominus: Projice eam in terram. Projecit, et versa est in colubrum, ita ut fugeret Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Dixitque Dominus: Extende manum tuam, et apprehende caudam ejus. Extendit, et tenuit, versaque est in virgam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Ut credant, inquit, quod apparuerit tibi Dominus Deus patrum suorum, Deus Abraham, Deus Isaac et Deus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Dixitque Dominus rursum: Mitte manum tuam in sinum tuum. Quam cum misisset in sinum, protulit leprosam instar nivis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Retrahe, ait, manum tuam in sinum tuum. Retraxit, et protulit iterum, et erat similis carni reliquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Si non crediderint, inquit, tibi, neque audierint sermonem signi prioris, credent verbo signi sequentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Quod si nec duobus quidem his signis crediderint, neque audierint vocem tuam: sume aquam fluminis, et effunde eam super aridam, et quidquid hauseris de fluvio, vertetur in sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Ait Moyses: Obsecro, Domine, non sum eloquens ab heri et nudiustertius: et ex quo locutus es ad servum tuum, impeditioris et tardioris linguæ sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Dixit Dominus ad eum: Quis fecit os hominis? aut quis fabricatus est mutum et surdum, videntem et cæcum? nonne ego?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Perge, igitur, et ego ero in ore tuo: doceboque te quid loquaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'At ille: Obsecro, inquit, Domine, mitte quem missurus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Iratus Dominus in Moysen, ait: Aaron frater tuus Levites, scio quod eloquens sit: ecce ipse egreditur in occursum tuum, vidensque te lætabitur corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Loquere ad eum, et pone verba mea in ore ejus: et ego ero in ore tuo, et in ore illius, et ostendam vobis quid agere debeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ipse loquetur pro te ad populum, et erit os tuum: tu autem eris ei in his quæ ad Deum pertinent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Virgam quoque hanc sume in manu tua, in qua facturus es signa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Abiit Moyses, et reversus est ad Jethro socerum suum, dixitque ei: Vadam et revertar ad fratres meos in \'gyptum, ut videam si adhuc vivant. Cui ait Jethro: Vade in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Dixit ergo Dominus ad Moysen in Madian: Vade, et revertere in \'gyptum, mortui sunt enim omnes qui quærebant animam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Tulit ergo Moyses uxorem suam, et filios suos, et imposuit eos super asinum: reversusque est in \'gyptum, portans virgam Dei in manu sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Dixitque ei Dominus revertenti in \'gyptum: Vide ut omnia ostenta quæ posui in manu tua, facias coram Pharaone: ego indurabo cor ejus, et non dimittet populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Dicesque ad eum: Hæc dicit Dominus: Filius meus primogenitus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Dixi tibi: Dimitte filium meum ut serviat mihi; et noluisti dimittere eum: ecce ego interficiam filium tuum primogenitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Cumque esset in itinere, in diversorio occurrit ei Dominus, et volebat occidere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tulit idcirco Sephora acutissimam petram, et circumcidit præputium filii sui, tetigitque pedes ejus, et ait: Sponsus sanguinum tu mihi es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Et dimisit eum postquam dixerat: Sponsus sanguinum ob circumcisionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Dixit autem Dominus ad Aaron: Vade in occursum Moysi in desertum. Qui perrexit obviam ei in montem Dei, et osculatus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Narravitque Moyses Aaron omnia verba Domini quibus miserat eum, et signa quæ mandaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Veneruntque simul, et congregaverunt cunctos seniores filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Locutusque est Aaron omnia verba quæ dixerat Dominus ad Moysen: et fecit signa coram populo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'et credidit populus. Audieruntque quod visitasset Dominus filios Israël, et respexisset afflictionem illorum: et proni adoraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Post hæc ingressi sunt Moyses et Aaron, et dixerunt Pharaoni: Hæc dicit Dominus Deus Israël: Dimitte populum meum ut sacrificet mihi in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'At ille respondit: Quis est Dominus, ut audiam vocem ejus, et dimittam Israël? nescio Dominum, et Israël non dimittam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Dixeruntque: Deus Hebræorum vocavit nos, ut eamus viam trium dierum in solitudinem, et sacrificemus Domino Deo nostro: ne forte accidat nobis pestis aut gladius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Ait ad eos rex \'gypti: Quare Moyses et Aaron sollicitatis populum ab operibus suis? ite ad onera vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Dixitque Pharao: Multus est populus terræ: videtis quod turba succreverit: quanto magis si dederitis eis requiem ab operibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Præcepit ergo in die illo præfectis operum et exactoribus populi, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Nequaquam ultra dabitis paleas populo ad conficiendos lateres, sicut prius: sed ipsi vadant, et colligant stipulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Et mensuram laterum, quam prius faciebant, imponetis super eos, nec minuetis quidquam: vacant enim, et idcirco vociferantur, dicentes: Eamus, et sacrificemus Deo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Opprimantur operibus, et expleant ea: ut non acquiescant verbis mendacibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Igitur egressi præfecti operum et exactores ad populum, dixerunt: Sic dicit Pharao: Non do vobis paleas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'ite, et colligite sicubi invenire poteritis, nec minuetur quidquam de opere vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Dispersusque est populus per omnem terram \'gypti ad colligendas paleas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Præfecti quoque operum instabant, dicentes: Complete opus vestrum quotidie, ut prius facere solebatis quando dabantur vobis paleæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Flagellatique sunt qui præerant operibus filiorum Israël, ab exactoribus Pharaonis, dicentibus: Quare non impletis mensuram laterum sicut prius, nec heri, nec hodie?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Veneruntque præpositi filiorum Israël, et vociferati sunt ad Pharaonem dicentes: Cur ita agis contra servos tuos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'paleæ non dantur nobis, et lateres similiter imperantur: en famuli tui flagellis cædimur, et injuste agitur contra populum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Qui ait: Vacatis otio, et idcirco dicitis: Eamus, et sacrificemus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Ite ergo, et operamini: paleæ non dabuntur vobis, et reddetis consuetum numerum laterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Videbantque se præpositi filiorum Israël in malo, eo quod diceretur eis: Non minuetur quidquam de lateribus per singulos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Occurreruntque Moysi et Aaron, qui stabant ex adverso, egredientibus a Pharaone:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'et dixerunt ad eos: Videat Dominus et judicet, quoniam fœtere fecistis odorem nostrum coram Pharaone et servis ejus, et præbuistis ei gladium, ut occideret nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Reversusque est Moyses ad Dominum, et ait: Domine, cur afflixisti populum istum? quare misisti me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'ex eo enim quo ingressus sum ad Pharaonem ut loquerer in nomine tuo, afflixit populum tuum: et non liberasti eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Dixitque Dominus ad Moysen: Nunc videbis quæ facturus sim Pharaoni: per manum enim fortem dimittet eos, et in manu robusta ejiciet illos de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Locutusque est Dominus ad Moysen dicens: Ego Dominus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'qui apparui Abraham, Isaac et Jacob in Deo omnipotente: et nomen meum Adonai non indicavi eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Pepigique fœdus cum eis, ut darem eis terram Chanaan, terram peregrinationis eorum, in qua fuerunt advenæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ego audivi gemitum filiorum Israël, quo \'gyptii oppresserunt eos: et recordatus sum pacti mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Ideo dic filiis Israël: Ego Dominus qui educam vos de ergastulo \'gyptiorum, et eruam de servitute, ac redimam in brachio excelso et judiciis magnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Et assumam vos mihi in populum, et ero vester Deus: et scietis quod ego sum Dominus Deus vester qui eduxerim vos de ergastulo \'gyptiorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'et induxerim in terram, super quam levavi manum meam ut darem eam Abraham, Isaac et Jacob: daboque illam vobis possidendam. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Narravit ergo Moyses omnia filiis Israël: qui non acquieverunt ei propter angustiam spiritus, et opus durissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Ingredere, et loquere ad Pharaonem regem \'gypti, ut dimittat filios Israël de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Respondit Moyses coram Domino: Ecce filii Israël non audiunt me: et quomodo audiet Pharao, præsertim cum incircumcisus sim labiis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Locutusque est Dominus ad Moysen et Aaron, et dedit mandatum ad filios Israël, et ad Pharaonem regem \'gypti ut educerent filios Israël de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Isti sunt principes domorum per familias suas. Filii Ruben primogeniti Israëlis: Henoch et Phallu, Hesron et Charmi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'hæ cognationes Ruben. Filii Simeon: Jamuel, et Jamin, et Ahod, et Jachin, et Soar, et Saul filius Chananitidis: hæ progenies Simeon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Et hæc nomina filiorum Levi per cognationes suas: Gerson, et Caath, et Merari. Anni autem vitæ Levi fuerunt centum triginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Filii Gerson: Lobni et Semei, per cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Filii Caath: Amram, et Isaar, et Hebron, et Oziel; anni quoque vitæ Caath, centum triginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Filii Merari: Moholi et Musi: hæ cognationes Levi per familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Accepit autem Amram uxorem Jochabed patruelem suam: quæ peperit ei Aaron et Moysen. Fueruntque anni vitæ Amram, centum triginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Filii quoque Isaar: Core, et Nepheg, et Zechri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Filii quoque Oziel: Misaël, et Elisaphan, et Sethri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Accepit autem Aaron uxorem Elisabeth filiam Aminadab, sororem Nahason, quæ peperit ei Nadab, et Abiu, et Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Filii quoque Core: Aser, et Elcana, et Abiasaph: hæ sunt cognationes Coritarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'At vero Eleazar filius Aaron accepit uxorem de filiabus Phutiel: quæ peperit ei Phinees. Hi sunt principes familiarum Leviticarum per cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Iste est Aaron et Moyses, quibus præcepit Dominus ut educerent filios Israël de terra \'gypti per turmas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Hi sunt, qui loquuntur ad Pharaonem regem \'gypti, ut educant filios Israël de \'gypto: iste est Moyses et Aaron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'in die qua locutus est Dominus ad Moysen, in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Et locutus est Dominus ad Moysen, dicens: Ego Dominus: loquere ad Pharaonem regem \'gypti, omnia quæ ego loquor tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Et ait Moyses coram Domino: En incircumcisus labiis sum, quomodo audiet me Pharao?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Dixitque Dominus ad Moysen: Ecce constitui te Deum Pharaonis: et Aaron frater tuus erit propheta tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu loqueris ei omnia quæ mando tibi: et ille loquetur ad Pharaonem, ut dimittat filios Israël de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Sed ego indurabo cor ejus, et multiplicabo signa et ostenta mea in terra \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'et non audiet vos: immittamque manum meam super \'gyptum, et educam exercitum et populum meum filios Israël de terra \'gypti per judicia maxima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Et scient \'gyptii quia ego sum Dominus qui extenderim manum meam super \'gyptum, et eduxerim filios Israël de medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Fecit itaque Moyses et Aaron sicut præceperat Dominus: ita egerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Erat autem Moyses octoginta annorum, et Aaron octoginta trium, quando locuti sunt ad Pharaonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Dixitque Dominus ad Moysen et Aaron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Cum dixerit vobis Pharao, Ostendite signa: dices ad Aaron: Tolle virgam tuam, et projice eam coram Pharaone, ac vertetur in colubrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Ingressi itaque Moyses et Aaron ad Pharaonem, fecerunt sicut præceperat Dominus: tulitque Aaron virgam coram Pharaone et servis ejus, quæ versa est in colubrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Vocavit autem Pharao sapientes et maleficos: et fecerunt etiam ipsi per incantationes ægyptiacas et arcana quædam similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Projeceruntque singuli virgas suas, quæ versæ sunt in dracones: sed devoravit virga Aaron virgas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Induratumque est cor Pharaonis, et non audivit eos, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Dixit autem Dominus ad Moysen: Ingravatum est cor Pharaonis: non vult dimittere populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Vade ad eum mane, ecce egredietur ad aquas: et stabis in occursum ejus super ripam fluminis: et virgam quæ conversa est in draconem, tolles in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Dicesque ad eum: Dominus Deus Hebræorum misit me ad te, dicens: Dimitte populum meum ut sacrificet mihi in deserto: et usque ad præsens audire noluisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Hæc igitur dicit Dominus: In hoc scies quod sim Dominus: ecce percutiam virga, quæ in manu mea est, aquam fluminis, et vertetur in sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Pisces quoque, qui sunt in fluvio, morientur, et computrescent aquæ, et affligentur \'gyptii bibentes aquam fluminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Dixit quoque Dominus ad Moysen: Dic ad Aaron: Tolle virgam tuam, et extende manum tuam super aquas \'gypti, et super fluvios eorum, et rivos ac paludes, et omnes lacus aquarum, ut vertantur in sanguinem: et sit cruor in omni terra \'gypti, tam in ligneis vasis quam in saxeis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Feceruntque Moyses et Aaron sicut præceperat Dominus: et elevans virgam percussit aquam fluminis coram Pharaone et servis ejus: quæ versa est in sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Et pisces, qui erant in flumine, mortui sunt: computruitque fluvius, et non poterant \'gyptii bibere aquam fluminis, et fuit sanguis in tota terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Feceruntque similiter malefici \'gyptiorum incantationibus suis: et induratum est cor Pharaonis, nec audivit eos, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Avertitque se, et ingressus est domum suam, nec apposuit cor etiam hac vice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Foderunt autem omnes \'gyptii per circuitum fluminis aquam ut biberent: non enim poterant bibere de aqua fluminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Impletique sunt septem dies, postquam percussit Dominus fluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Dixit quoque Dominus ad Moysen: Ingredere ad Pharaonem, et dices ad eum: Hæc dicit Dominus: Dimitte populum meum, ut sacrificet mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'sin autem nolueris dimittere, ecce ego percutiam omnes terminos tuos ranis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'et ebulliet fluvius ranas: quæ ascendent, et ingredientur domum tuam, et cubiculum lectuli tui, et super stratum tuum, et in domos servorum tuorum, et in populum tuum, et in furnos tuos, et in reliquias ciborum tuorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'et ad te, et ad populum tuum, et ad omnes servos tuos intrabunt ranæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Dixitque Dominus ad Moysen: Dic ad Aaron: Extende manum tuam super fluvios ac super rivos et paludes, et educ ranas super terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Et extendit Aaron manum super aquas \'gypti, et ascenderunt ranæ, operueruntque terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Fecerunt autem et malefici per incantationes suas similiter, eduxeruntque ranas super terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Vocavit autem Pharao Moysen et Aaron, et dixit eis: Orate Dominum ut auferat ranas a me et a populo meo, et dimittam populum ut sacrificet Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Dixitque Moyses ad Pharaonem: Constitue mihi quando deprecer pro te, et pro servis tuis, et pro populo tuo, ut abigantur ranæ a te, et a domo tua, et a servis tuis, et a populo tuo: et tantum in flumine remaneant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Qui respondit: Cras. At ille: Juxta, inquit, verbum tuum faciam: ut scias quoniam non est sicut Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Et recedent ranæ a te, et a domo tua, et a servis tuis, et a populo tuo: et tantum in flumine remanebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Egressique sunt Moyses et Aaron a Pharaone: et clamavit Moyses ad Dominum pro sponsione ranarum quam condixerat Pharaoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Fecitque Dominus juxta verbum Moysi: et mortuæ sunt ranæ de domibus, et de villis, et de agris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Congregaveruntque eas in immensos aggeres, et computruit terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Videns autem Pharao quod data esset requies, ingravavit cor suum, et non audivit eos, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Dixitque Dominus ad Moysen: Loquere ad Aaron: Extende virgam tuam, et percute pulverem terræ: et sint sciniphes in universa terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Feceruntque ita. Et extendit Aaron manum, virgam tenens: percussitque pulverem terræ, et facti sunt sciniphes in hominibus, et in jumentis: omnis pulvis terræ versus est in sciniphes per totam terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Feceruntque similiter malefici incantationibus suis, ut educerent sciniphes, et non potuerunt: erantque sciniphes tam in hominibus quam in jumentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Et dixerunt malefici ad Pharaonem: Digitus Dei est hic; induratumque est cor Pharaonis, et non audivit eos sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Dixit quoque Dominus ad Moysen: Consurge diluculo, et sta coram Pharaone: egredietur enim ad aquas: et dices ad eum: Hæc dicit Dominus: Dimitte populum meum ut sacrificet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Quod si non dimiseris eum, ecce ego immittam in te, et in servos tuos, et in populum tuum, et in domos tuas, omne genus muscarum: et implebuntur domus \'gyptiorum muscis diversi generis, et universa terra in qua fuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Faciamque mirabilem in die illa terram Gessen, in qua populus meus est, ut non sint ibi muscæ: et scias quoniam ego Dominus in medio terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ponamque divisionem inter populum meum et populum tuum: cras erit signum istud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Fecitque Dominus ita. Et venit musca gravissima in domos Pharaonis et servorum ejus, et in omnem terram \'gypti: corruptaque est terra ab hujuscemodi muscis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Vocavitque Pharao Moysen et Aaron, et ait eis: Ite et sacrificate Deo vestro in terra hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Et ait Moyses: Non potest ita fieri: abominationes enim \'gyptiorum immolabimus Domino Deo nostro: quod si mactaverimus ea quæ colunt \'gyptii coram eis, lapidibus nos obruent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Viam trium dierum pergemus in solitudinem: et sacrificabimus Domino Deo nostro, sicut præcepit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Dixitque Pharao: Ego dimittam vos ut sacrificetis Domino Deo vestro in deserto: verumtamen longius ne abeatis, rogate pro me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'At ait Moyses: Egressus a te, orabo Dominum: et recedet musca a Pharaone, et a servis suis, et a populo ejus cras: verumtamen noli ultra fallere, ut non dimittas populum sacrificare Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Egressusque Moyses a Pharaone, oravit Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Qui fecit juxta verbum illius, et abstulit muscas a Pharaone, et a servis suis, et a populo ejus: non superfuit ne una quidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Et ingravatum est cor Pharaonis, ita ut nec hac quidem vice dimitteret populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Dixit autem Dominus ad Moysen: Ingredere ad Pharaonem, et loquere ad eum: Hæc dicit Dominus Deus Hebræorum: Dimitte populum meum ut sacrificet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Quod si adhuc renuis, et retines eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'ecce manus mea erit super agros tuos, et super equos, et asinos, et camelos, et boves, et oves, pestis valde gravis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Et faciet Dominus mirabile inter possessiones Israël et possessiones \'gyptiorum, ut nihil omnino pereat ex eis quæ pertinent ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Constituitque Dominus tempus, dicens: Cras faciet Dominus verbum istud in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Fecit ergo Dominus verbum hoc altera die: mortuaque sunt omnia animantia \'gyptiorum; de animalibus vero filiorum Israël, nihil omnino periit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et misit Pharao ad videndum: nec erat quidquam mortuum de his quæ possidebat Israël. Ingravatumque est cor Pharaonis, et non dimisit populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Et dixit Dominus ad Moysen et Aaron: Tollite plenas manus cineris de camino, et spargat illum Moyses in cælum coram Pharaone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Sitque pulvis super omnem terram \'gypti: erunt enim in hominibus et jumentis ulcera, et vesicæ turgentes in universa terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Tuleruntque cinerem de camino, et steterunt coram Pharaone, et sparsit illum Moyses in cælum: factaque sunt ulcera vesicarum turgentium in hominibus et jumentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'nec poterant malefici stare coram Moyse propter ulcera quæ in illis erant, et in omni terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Induravitque Dominus cor Pharaonis, et non audivit eos, sicut locutus est Dominus ad Moysen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Dixitque Dominus ad Moysen: Mane consurge, et sta coram Pharaone, et dices ad eum: Hæc dicit Dominus Deus Hebræorum: Dimitte populum meum ut sacrificet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Quia in hac vice mittam omnes plagas meas super cor tuum, et super servos tuos, et super populum tuum: ut scias quod non sit similis mei in omni terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Nunc enim extendens manum percutiam te, et populum tuum peste, peribisque de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Idcirco autem posui te, ut ostendam in te fortitudinem meam, et narretur nomen meum in omni terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Adhuc retines populum meum, et non vis dimittere eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'En pluam cras hac ipsa hora grandinem multam nimis, qualis non fuit in \'gypto a die qua fundata est, usque in præsens tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Mitte ergo jam nunc, et congrega jumenta tua, et omnia quæ habes in agro: homines enim, et jumenta, et universa quæ inventa fuerint foris, nec congregata de agris, cecideritque super ea grando, morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Qui timuit verbum Domini de servis Pharaonis, facit confugere servos suos et jumenta in domos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'qui autem neglexit sermonem Domini, dimisit servos suos et jumenta in agris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Et dixit Dominus ad Moysen: Extende manum tuam in cælum, ut fiat grando in universa terra \'gypti super homines, et super jumenta, et super omnem herbam agri in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Extenditque Moyses virgam in cælum, et Dominus dedit tonitrua, et grandinem, ac discurrentia fulgura super terram: pluitque Dominus grandinem super terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Et grando et ignis mista pariter ferebantur: tantæque fuit magnitudinis, quanta ante numquam apparuit in universa terra \'gypti ex quo gens illa condita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Et percussit grando in omni terra \'gypti cuncta quæ fuerunt in agris, ab homine usque ad jumentum: cunctamque herbam agri percussit grando, et omne lignum regionis confregit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Tantum in terra Gessen, ubi erant filii Israël, grando non cecidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Misitque Pharao, et vocavit Moysen et Aaron, dicens ad eos: Peccavi etiam nunc: Dominus justus; ego et populus meus, impii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Orate Dominum ut desinant tonitrua Dei, et grando: ut dimittam vos, et nequaquam hic ultra maneatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Ait Moyses: Cum egressus fuero de urbe, extendam palmas meas ad Dominum, et cessabunt tonitrua, et grando non erit, ut scias quia Domini est terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'novi autem quod et tu et servi tui necdum timeatis Dominum Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Linum ergo et hordeum læsum est, eo quod hordeum esset virens, et linum jam folliculos germinaret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'triticum autem et far non sunt læsa, quia serotina erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Egressusque Moyses a Pharaone ex urbe, tetendit manus ad Dominum: et cessaverunt tonitrua et grando, nec ultra stillavit pluvia super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Videns autem Pharao quod cessasset pluvia, et grando, et tonitrua, auxit peccatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'et ingravatum est cor ejus, et servorum illius, et induratum nimis: nec dimisit filios Israël, sicut præceperat Dominus per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Et dixit Dominus ad Moysen: Ingredere ad Pharaonem: ego enim induravi cor ejus, et servorum illius, ut faciam signa mea hæc in eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'et narres in auribus filii tui, et nepotum tuorum, quoties contriverim \'gyptios, et signa mea fecerim in eis: et sciatis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Introierunt ergo Moyses et Aaron ad Pharaonem, et dixerunt ei: Hæc dicit Dominus Deus Hebræorum: Usquequo non vis subjici mihi? dimitte populum meum, ut sacrificet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Sin autem resistis, et non vis dimittere eum: ecce ego inducam cras locustam in fines tuos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'quæ operiat superficiem terræ, ne quidquam ejus appareat, sed comedatur quod residuum fuerit grandini: corrodet enim omnia ligna quæ germinant in agris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Et implebunt domos tuas, et servorum tuorum, et omnium \'gyptiorum, quantam non viderunt patres tui, et avi, ex quo orti sunt super terram, usque in præsentem diem. Avertitque se, et egressus est a Pharaone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Dixerunt autem servi Pharaonis ad eum: Usquequo patiemur hoc scandalum? dimitte homines, ut sacrificent Domino Deo suo; nonne vides quod perierit \'gyptus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Revocaveruntque Moysen et Aaron ad Pharaonem: qui dixit eis: Ite, sacrificate Domino Deo vestro: quinam sunt qui ituri sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Ait Moyses: Cum parvulis nostris, et senioribus pergemus, cum filiis et filiabus, cum ovibus et armentis: est enim solemnitas Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Et respondit Pharao: Sic Dominus sit vobiscum, quomodo ego dimittam vos, et parvulos vestros, cui dubium est quod pessime cogitetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'non fiet ita, sed ite tantum viri, et sacrificate Domino: hoc enim et ipsi petistis. Statimque ejecti sunt de conspectu Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Dixit autem Dominus ad Moysen: Extende manum tuam super terram \'gypti ad locustam, ut ascendat super eam, et devoret omnem herbam quæ residua fuerit grandini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Et extendit Moyses virgam super terram \'gypti: et Dominus induxit ventum urentem tota die illa et nocte: et mane facto, ventus urens levavit locustas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Quæ ascenderunt super universam terram \'gypti: et sederunt in cunctis finibus \'gyptiorum innumerabiles, quales ante illud tempus non fuerant, nec postea futuræ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Operueruntque universam superficiem terræ, vastantes omnia. Devorata est igitur herba terræ, et quidquid pomorum in arboribus fuit, quæ grando dimiserat: nihilque omnino virens relictum est in lignis et in herbis terræ, in cuncta \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Quam ob rem festinus Pharao vocavit Moysen et Aaron, et dixit eis: Peccavi in Dominum Deum vestrum, et in vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Sed nunc dimittite peccatum mihi etiam hac vice, et rogate Dominum Deum vestrum, ut auferat a me mortem istam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Egressusque Moyses de conspectu Pharaonis, oravit Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Qui flare fecit ventum ab occidente vehementissimum, et arreptam locustam projecit in mare Rubrum: non remansit ne una quidem in cunctis finibus \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Et induravit Dominus cor Pharaonis, nec dimisit filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Dixit autem Dominus ad Moysen: Extende manum tuam in cælum: et sint tenebræ super terram \'gypti tam densæ, ut palpari queant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Extenditque Moyses manum in cælum: et factæ sunt tenebræ horribiles in universa terra \'gypti tribus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Nemo vidit fratrem suum, nec movit se de loco in quo erat: ubicumque autem habitabant filii Israël, lux erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Vocavitque Pharao Moysen et Aaron, et dixit eis: Ite, sacrificate Domino: oves tantum vestræ et armenta remaneant, parvuli vestri eant vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Ait Moyses: Hostias quoque et holocausta dabis nobis, quæ offeramus Domino Deo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Cuncti greges pergent nobiscum; non remanebit ex eis ungula: quæ necessaria sunt in cultum Domini Dei nostri: præsertim cum ignoremus quid debeat immolari, donec ad ipsum locum perveniamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Induravit autem Dominus cor Pharaonis, et noluit dimittere eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Dixitque Pharao ad Moysen: Recede a me, et cave ne ultra videas faciem meam: quocumque die apparueris mihi, morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Respondit Moyses: Ita fiet ut locutus es: non videbo ultra faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Et dixit Dominus ad Moysen: Adhuc una plaga tangam Pharaonem et \'gyptum, et post hæc dimittet vos, et exire compellet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Dices ergo omni plebi ut postulet vir ab amico suo, et mulier a vicina sua, vasa argentea et aurea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Dabit autem Dominus gratiam populo suo coram \'gyptiis. Fuitque Moyses vir magnus valde in terra \'gypti coram servis Pharaonis et omni populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et ait: Hæc dicit Dominus: Media nocte egrediar in \'gyptum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'et morietur omne primogenitum in terra \'gyptiorum, a primogenito Pharaonis, qui sedet in solio ejus, usque ad primogenitum ancillæ quæ est ad molam, et omnia primogenita jumentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Eritque clamor magnus in universa terra \'gypti, qualis nec ante fuit, nec postea futurus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Apud omnes autem filios Israël non mutiet canis ab homine usque ad pecus: ut sciatis quanto miraculo dividat Dominus \'gyptios et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Descendentque omnes servi tui isti ad me, et adorabunt me, dicentes: Egredere tu, et omnis populus qui subjectus est tibi: post hæc egrediemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Et exivit a Pharaone iratus nimis. Dixit autem Dominus ad Moysen: Non audiet vos Pharao ut multa signa fiant in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Moyses autem et Aaron fecerunt omnia ostenta, quæ scripta sunt, coram Pharaone. Et induravit Dominus cor Pharaonis, nec dimisit filios Israël de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Dixit quoque Dominus ad Moysen et Aaron in terra \'gypti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Mensis iste, vobis principium mensium: primus erit in mensibus anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Loquimini ad universum cœtum filiorum Israël, et dicite eis: Decima die mensis hujus tollat unusquisque agnum per familias et domos suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Sin autem minor est numerus ut sufficere possit ad vescendum agnum, assumet vicinum suum qui junctus est domui suæ, juxta numerum animarum quæ sufficere possunt ad esum agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Erit autem agnus absque macula, masculus, anniculus: juxta quem ritum tolletis et hædum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Et servabitis eum usque ad quartamdecimam diem mensis hujus: immolabitque eum universa multitudo filiorum Israël ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Et sument de sanguine ejus, ac ponent super utrumque postem, et in superliminaribus domorum, in quibus comedent illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Et edent carnes nocte illa assas igni, et azymos panes cum lactucis agrestibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Non comedetis ex eo crudum quid, nec coctum aqua, sed tantum assum igni: caput cum pedibus ejus et intestinis vorabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Nec remanebit quidquam ex eo usque mane; si quid residuum fuerit, igne comburetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Sic autem comedetis illum: renes vestros accingetis, et calceamenta habebitis in pedibus, tenentes baculos in manibus, et comedetis festinanter: est enim Phase (id est, transitus) Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Et transibo per terram \'gypti nocte illa, percutiamque omne primogenitum in terra \'gypti ab homine usque ad pecus: et in cunctis diis \'gypti faciam judicia. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Erit autem sanguis vobis in signum in ædibus in quibus eritis: et videbo sanguinem, et transibo vos: nec erit in vobis plaga disperdens quando percussero terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Habebitis autem hunc diem in monimentum: et celebrabitis eam solemnem Domino in generationibus vestris cultu sempiterno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Septem diebus azyma comedetis: in die primo non erit fermentum in domibus vestris: quicumque comederit fermentatum, peribit anima illa de Israël, a primo die usque ad diem septimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Dies prima erit sancta atque solemnis, et dies septima eadem festivitate venerabilis: nihil operis facietis in eis, exceptis his, quæ ad vescendum pertinent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Et observabitis azyma: in eadem enim ipsa die educam exercitum vestrum de terra \'gypti, et custodietis diem istum in generationes vestras ritu perpetuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Primo mense, quartadecima die mensis ad vesperam, comedetis azyma usque ad diem vigesimam primam ejusdem mensis ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Septem diebus fermentum non invenietur in domibus vestris: qui comederit fermentatum, peribit anima ejus de cœtu Israël, tam de advenis quam de indigenis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Omne fermentatum non comedetis: in cunctis habitaculis vestris edetis azyma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Vocavit autem Moyses omnes seniores filiorum Israël, et dixit ad eos: Ite tollentes animal per familias vestras, et immolate Phase.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Fasciculumque hyssopi tingite in sanguine qui est in limine, et aspergite ex eo superliminare, et utrumque postem: nullus vestrum egrediatur ostium domus suæ usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Transibit enim Dominus percutiens \'gyptios: cumque viderit sanguinem in superliminari, et in utroque poste, transcendet ostium domus, et non sinet percussorem ingredi domos vestras et lædere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Custodi verbum istud legitimum tibi et filiis tuis usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Cumque introieritis terram, quam Dominus daturus est vobis ut pollicitus est, observabitis cæremonias istas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Et cum dixerint vobis filii vestri: Quæ est ista religio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Dicetis eis: Victima transitus Domini est, quando transivit super domos filiorum Israël in \'gypto, percutiens \'gyptios, et domos nostras liberans. Incurvatusque populus adoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Et egressi filii Israël fecerunt sicut præceperat Dominus Moysi et Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Factum est autem in noctis medio, percussit Dominus omne primogenitum in terra \'gypti, a primogenito Pharaonis, qui in solio ejus sedebat, usque ad primogenitum captivæ quæ erat in carcere, et omne primogenitum jumentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Surrexitque Pharao nocte, et omnes servi ejus, cunctaque \'gyptus: et ortus est clamor magnus in \'gypto: neque enim erat domus in qua non jaceret mortuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Vocatisque Pharao Moyse et Aaron nocte, ait: Surgite et egredimini a populo meo, vos et filii Israël: ite, immolate Domino sicut dicitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Oves vestras et armenta assumite ut petieratis, et abeuntes benedicite mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Urgebantque \'gyptii populum de terra exire velociter, dicentes: Omnes moriemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Tulit igitur populus conspersam farinam antequam fermentaretur: et ligans in palliis, posuit super humeros suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Feceruntque filii Israël sicut præceperat Moyses: et petierunt ab \'gyptiis vasa argentea et aurea, vestemque plurimam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Dominus autem dedit gratiam populo coram \'gyptiis ut commodarent eis: et spoliaverunt \'gyptios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Profectique sunt filii Israël de Ramesse in Socoth, sexcenta fere millia peditum virorum, absque parvulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Sed et vulgus promiscuum innumerabile ascendit cum eis, oves et armenta et animantia diversi generis multa nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Coxeruntque farinam, quam dudum de \'gypto conspersam tulerant: et fecerunt subcinericios panes azymos: neque enim poterant fermentari, cogentibus exire \'gyptiis, et nullam facere sinentibus moram: nec pulmenti quidquam occurrerat præparare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Habitatio autem filiorum Israël qua manserunt in \'gypto, fuit quadringentorum triginta annorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Quibus expletis, eadem die egressus est omnis exercitus Domini de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Nox ista est observabilis Domini, quando eduxit eos de terra \'gypti: hanc observare debent omnes filii Israël in generationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Dixitque Dominus ad Moysen et Aaron: Hæc est religio Phase: omnis alienigena non comedet ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Omnis autem servus emptitius circumcidetur, et sic comedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Advena et mercenarius non edent ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In una domo comedetur, nec efferetis de carnibus ejus foras, nec os illius confringetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Omnis cœtus filiorum Israël faciet illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Quod si quis peregrinorum in vestram voluerit transire coloniam, et facere Phase Domini, circumcidetur prius omne masculinum ejus, et tunc rite celebrabit: eritque sicut indigena terræ: si quis autem circumcisus non fuerit, non vescetur ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Eadem lex erit indigenæ et colono qui peregrinatur apud vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Feceruntque omnes filii Israël sicut præceperat Dominus Moysi et Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Et eadem die eduxit Dominus filios Israël de terra \'gypti per turmas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Sanctifica mihi omne primogenitum quod aperit vulvam in filiis Israël, tam de hominibus quam de jumentis: mea sunt enim omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Et ait Moyses ad populum: Mementote diei hujus in qua egressi estis de \'gypto et de domo servitutis, quoniam in manu forti eduxit vos Dominus de loco isto: ut non comedatis fermentatum panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Hodie egredimini mense novarum frugum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Cumque introduxerit te Dominus in terram Chananæi, et Hethæi, et Amorrhæi, et Hevæi, et Jebusæi, quam juravit patribus tuis ut daret tibi, terram fluentem lacte et melle, celebrabis hunc morem sacrorum mense isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Septem diebus vesceris azymis: et in die septimo erit solemnitas Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Azyma comedetis septem diebus: non apparebit apud te aliquid fermentatum, nec in cunctis finibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Narrabisque filio tuo in die illo, dicens: Hoc est quod fecit mihi Dominus quando egressus sum de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et erit quasi signum in manu tua, et quasi monimentum ante oculos tuos: et ut lex Domini semper sit in ore tuo, in manu enim forti eduxit te Dominus de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Custodies hujuscemodi cultum statuto tempore a diebus in dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Cumque introduxerit te Dominus in terram Chananæi, sicut juravit tibi et patribus tuis, et dederit tibi eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'separabis omne quod aperit vulvam Domino, et quod primitivum est in pecoribus tuis: quidquid habueris masculini sexus, consecrabis Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Primogenitum asini mutabis ove: quod si non redemeris, interficies. Omne autem primogenitum hominis de filiis tuis, pretio redimes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Cumque interrogaverit te filius tuus cras, dicens: Quid est hoc? respondebis ei: In manu forti eduxit nos Dominus de terra \'gypti, de domo servitutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Nam cum induratus esset Pharao, et nollet nos dimittere, occidit Dominus omne primogenitum in terra \'gypti, a primogenito hominis usque ad primogenitum jumentorum: idcirco immolo Domino omne quod aperit vulvam masculini sexus, et omnia primogenita filiorum meorum redimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Erit igitur quasi signum in manu tua, et quasi appensum quid, ob recordationem, inter oculos tuos: eo quod in manu forti eduxit nos Dominus de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Igitur cum emisisset Pharao populum, non eos duxit Deus per viam terræ Philisthiim quæ vicina est: reputans ne forte pœniteret eum, si vidisset adversum se bella consurgere, et reverteretur in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Sed circumduxit per viam deserti, quæ est juxta mare Rubrum: et armati ascenderunt filii Israël de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Tulit quoque Moyses ossa Joseph secum: eo quod adjurasset filios Israël, dicens: Visitabit vos Deus; efferte ossa mea hinc vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Profectique de Socoth castrametati sunt in Etham, in extremis finibus solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Dominus autem præcedebat eos ad ostendendam viam per diem in columna nubis, et per noctem in columna ignis: ut dux esset itineris utroque tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Numquam defuit columna nubis per diem, nec columna ignis per noctem, coram populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Locutus est autem Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Loquere filiis Israël: Reversi castrametentur e regione Phihahiroth, quæ est inter Magdalum et mare contra Beelsephon: in conspectu ejus castra ponetis super mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Dicturusque est Pharao super filiis Israël: Coarctati sunt in terra; conclusit eos desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Et indurabo cor ejus, ac persequetur vos: et glorificabor in Pharaone, et in omni exercitu ejus; scientque \'gyptii quia ego sum Dominus. Feceruntque ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Et nuntiatum est regi \'gyptiorum quod fugisset populus: immutatumque est cor Pharaonis et servorum ejus super populo, et dixerunt: Quid voluimus facere ut dimitteremus Israël, ne serviret nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Junxit ergo currum, et omnem populum suum assumpsit secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Tulitque sexcentos currus electos, et quidquid in \'gypto curruum fuit: et duces totius exercitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Induravitque Dominus cor Pharaonis regis \'gypti, et persecutus est filios Israël: at illi egressi sunt in manu excelsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Cumque persequerentur \'gyptii vestigia præcedentium, repererunt eos in castris super mare: omnis equitatus et currus Pharaonis, et universus exercitus, erant in Phihahiroth contra Beelsephon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Cumque appropinquasset Pharao, levantes filii Israël oculos, viderunt \'gyptios post se, et timuerunt valde: clamaveruntque ad Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'et dixerunt ad Moysen: Forsitan non erant sepulchra in \'gypto, ideo tulisti nos ut moreremur in solitudine: quid hoc facere voluisti, ut educeres nos ex \'gypto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'nonne iste est sermo, quem loquebamur ad te in \'gypto, dicentes: Recede a nobis, ut serviamus \'gyptiis? multo enim melius erat servire eis, quam mori in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Et ait Moyses ad populum: Nolite timere: state, et videte magnalia Domini quæ facturus est hodie: \'gyptios enim, quos nunc videtis, nequaquam ultra videbitis usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Dominus pugnabit pro vobis, et vos tacebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Dixitque Dominus ad Moysen: Quid clamas ad me? loquere filiis Israël ut proficiscantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Tu autem eleva virgam tuam, et extende manum tuam super mare, et divide illud: ut gradiantur filii Israël in medio mari per siccum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ego autem indurabo cor \'gyptiorum ut persequantur vos: et glorificabor in Pharaone, et in omni exercitu ejus, et in curribus et in equitibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Et scient \'gyptii quia ego sum Dominus cum glorificatus fuero in Pharaone, et in curribus atque in equitibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Tollensque se angelus Dei, qui præcedebat castra Israël, abiit post eos: et cum eo pariter columna nubis, priora dimittens, post tergum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'stetit, inter castra \'gyptiorum et castra Israël: et erat nubes tenebrosa, et illuminans noctem, ita ut ad se invicem toto noctis tempore accedere non valerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Cumque extendisset Moyses manum super mare, abstulit illud Dominus flante vento vehementi et urente tota nocte, et vertit in siccum: divisaque est aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Et ingressi sunt filii Israël per medium sicci maris: erat enim aqua quasi murus a dextra eorum et læva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Persequentesque \'gyptii ingressi sunt post eos, et omnis equitatus Pharaonis, currus ejus et equites per medium maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Jamque advenerat vigilia matutina, et ecce respiciens Dominus super castra \'gyptiorum per columnam ignis et nubis, interfecit exercitum eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'et subvertit rotas curruum, ferebanturque in profundum. Dixerunt ergo \'gyptii: Fugiamus Israëlem: Dominus enim pugnat pro eis contra nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Et ait Dominus ad Moysen: Extende manum tuam super mare, ut revertantur aquæ ad \'gyptios super currus et equites eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Cumque extendisset Moyses manum contra mare, reversum est primo diluculo ad priorem locum: fugientibusque \'gyptiis occurrerunt aquæ, et involvit eos Dominus in mediis fluctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Reversæque sunt aquæ, et operuerunt currus et equites cuncti exercitus Pharaonis, qui sequentes ingressi fuerant mare: nec unus quidem superfuit ex eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Filii autem Israël perrexerunt per medium sicci maris, et aquæ eis erant quasi pro muro a dextris et a sinistris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'liberavitque Dominus in die illa Israël de manu \'gyptiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Et viderunt \'gyptios mortuos super littus maris, et manum magnam quam exercuerat Dominus contra eos: timuitque populus Dominum, et crediderunt Domino, et Moysi servo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tunc cecinit Moyses et filii Israël carmen hoc Domino, et dixerunt: Cantemus Domino: gloriose enim magnificatus est, equum et ascensorem dejecit in mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Fortitudo mea, et laus mea Dominus, et factus est mihi in salutem: iste Deus meus, et glorificabo eum: Deus patris mei, et exaltabo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Dominus quasi vir pugnator, Omnipotens nomen ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'currus Pharaonis et exercitum ejus projecit in mare: electi principes ejus submersi sunt in mari Rubro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Abyssi operuerunt eos; descenderunt in profundum quasi lapis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Dextera tua, Domine, magnificata est in fortitudine: dextera tua, Domine, percussit inimicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Et in multitudine gloriæ tuæ deposuisti adversarios tuos: misisti iram tuam, quæ devoravit eos sicut stipulam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Et in spiritu furoris tui congregatæ sunt aquæ: stetit unda fluens, congregata sunt abyssi in medio mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Dixit inimicus: Persequar et comprehendam, dividam spolia, implebitur anima mea: evaginabo gladium meum, interficiet eos manus mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Flavit spiritus tuus, et operuit eos mare: submersi sunt quasi plumbum in aquis vehementibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Quis similis tui in fortibus, Domine? quis similis tui, magnificus in sanctitate, terribilis atque laudabilis, faciens mirabilia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Extendisti manum tuam, et devoravit eos terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Dux fuisti in misericordia tua populo quem redemisti: et portasti eum in fortitudine tua, ad habitaculum sanctum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Ascenderunt populi, et irati sunt: dolores obtinuerunt habitatores Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tunc conturbati sunt principes Edom, robustos Moab obtinuit tremor: obriguerunt omnes habitatores Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Irruat super eos formido et pavor, in magnitudine brachii tui: fiant immobiles quasi lapis, donec pertranseat populus tuus, Domine, donec pertranseat populus tuus iste, quem possedisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Introduces eos, et plantabis in monte hæreditatis tuæ, firmissimo habitaculo tuo quod operatus es, Domine: sanctuarium tuum, Domine, quod firmaverunt manus tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Dominus regnabit in æternum et ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Ingressus est enim eques Pharao cum curribus et equitibus ejus in mare: et reduxit super eos Dominus aquas maris: filii autem Israël ambulaverunt per siccum in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Sumpsit ergo Maria prophetissa, soror Aaron, tympanum in manu sua: egressæque sunt omnes mulieres post eam cum tympanis et choris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'quibus præcinebat, dicens: Cantemus Domino, gloriose enim magnificatus est: equum et ascensorem ejus dejecit in mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Tulit autem Moyses Israël de mari Rubro, et egressi sunt in desertum Sur: ambulaveruntque tribus diebus per solitudinem, et non inveniebant aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Et venerunt in Mara, nec poterant bibere aquas de Mara, eo quod essent amaræ: unde et congruum loco nomen imposuit, vocans illum Mara, id est, amaritudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Et murmuravit populus contra Moysen, dicens: Quid bibemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'At ille clamavit ad Dominum, qui ostendit ei lignum: quod cum misisset in aquas, in dulcedinem versæ sunt: ibi constituit ei præcepta, atque judicia, et ibi tentavit eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'dicens: Si audieris vocem Domini Dei tui, et quod rectum est coram eo feceris, et obedieris mandatis ejus, custodierisque omnia præcepta illius, cunctum languorem, quem posui in \'gypto, non inducam super te: ego enim Dominus sanator tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Venerunt autem in Elim filii Israël, ubi erant duodecim fontes aquarum, et septuaginta palmæ: et castrametati sunt juxta aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Profectique sunt de Elim, et venit omnis multitudo filiorum Israël in desertum Sin, quod est inter Elim et Sinai, quintodecimo die mensis secundi, postquam egressi sunt de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Et murmuravit omnis congregatio filiorum Israël contra Moysen et Aaron in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Dixeruntque filii Israël ad eos: Utinam mortui essemus per manum Domini in terra \'gypti, quando sedebamus super ollas carnium, et comedebamus panem in saturitate: cur eduxistis nos in desertum istud, ut occideretis omnem multitudinem fame?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Dixit autem Dominus ad Moysen: Ecce ego pluam vobis panes de cælo: egrediatur populus, et colligat quæ sufficiunt per singulos dies: ut tentem eum utrum ambulet in lege mea, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Die autem sexto parent quod inferant: et sit duplum quam colligere solebant per singulos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Dixeruntque Moyses et Aaron ad omnes filios Israël: Vespere scietis quod Dominus eduxerit vos de terra \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'et mane videbitis gloriam Domini: audivit enim murmur vestrum contra Dominum: nos vero quid sumus, quia mussitastis contra nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Et ait Moyses: Dabit vobis Dominus vespere carnes edere, et mane panes in saturitate: eo quod audierit murmurationes vestras quibus murmurati estis contra eum: nos enim quid sumus? nec contra nos est murmur vestrum, sed contra Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Dixit quoque Moyses ad Aaron: Dic universæ congregationi filiorum Israël: Accedite coram Domino: audivit enim murmur vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Cumque loqueretur Aaron ad omnem cœtum filiorum Israël, respexerunt ad solitudinem: et ecce gloria Domini apparuit in nube.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Locutus est autem Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Audivi murmurationes filiorum Israël. Loquere ad eos: Vespere comedetis carnes, et mane saturabimini panibus: scietisque quod ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Factum est ergo vespere, et ascendens coturnix, cooperuit castra: mane quoque ros jacuit per circuitum castrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Cumque operuisset superficiem terræ, apparuit in solitudine minutum, et quasi pilo tusum in similitudinem pruinæ super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Quod cum vidissent filii Israël, dixerunt ad invicem: Manhu? quod significat: Quid est hoc? ignorabant enim quid esset. Quibus ait Moyses: Iste est panis quem Dominus dedit vobis ad vescendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Hic est sermo, quem præcepit Dominus: Colligat unusquisque ex eo quantum sufficit ad vescendum: gomor per singula capita, juxta numerum animarum vestrarum quæ habitant in tabernaculo sic tolletis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Feceruntque ita filii Israël: et collegerunt, alius plus, alius minus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Et mensi sunt ad mensuram gomor: nec qui plus collegerat, habuit amplius: nec qui minus paraverat, reperit minus: sed singuli juxta id quod edere poterant, congregaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Dixitque Moyses ad eos: Nullus relinquat ex eo in mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Qui non audierunt eum, sed dimiserunt quidam ex eis usque mane, et scatere cœpit vermibus, atque computruit: et iratus est contra eos Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Colligebant autem mane singuli, quantum sufficere poterat ad vescendum: cumque incaluisset sol, liquefiebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'In die autem sexta collegerunt cibos duplices, id est, duo gomor per singulos homines: venerunt autem omnes principes multitudinis, et narraverunt Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Qui ait eis: Hoc est quod locutus est Dominus: Requies sabbati sanctificata est Domino cras: quodcumque operandum est, facite, et quæ coquenda sunt coquite: quidquid autem reliquum fuerit, reponite usque in mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Feceruntque ita ut præceperat Moyses, et non computruit, neque vermis inventus est in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Dixitque Moyses: Comedite illud hodie, quia sabbatum est Domini: non invenietur hodie in agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sex diebus colligite: in die autem septimo sabbatum est Domini, idcirco non invenietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Venitque septima dies: et egressi de populo ut colligerent, non invenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Dixit autem Dominus ad Moysen: Usquequo non vultis custodire mandata mea et legem meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'videte quod Dominus dederit vobis sabbatum, et propter hoc die sexta tribuit vobis cibos duplices: maneat unusquisque apud semetipsum; nullus egrediatur de loco suo die septimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Et sabbatizavit populus die septimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Appellavitque domus Israël nomen ejus Man: quod erat quasi semen coriandri album, gustusque ejus quasi similæ cum melle.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Dixit autem Moyses: Iste est sermo, quem præcepit Dominus: Imple gomor ex eo, et custodiatur in futuras retro generationes: ut noverint panem, quo alui vos in solitudine, quando educti estis de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Dixitque Moyses ad Aaron: Sume vas unum, et mitte ibi man, quantum potest capere gomor, et repone coram Domino ad servandum in generationes vestras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'sicut præcepit Dominus Moysi. Posuitque illud Aaron in tabernaculo reservandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Filii autem Israël comederunt man quadraginta annis, donec venirent in terram habitabilem: hoc cibo aliti sunt, usquequo tangerent fines terræ Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Gomor autem decima pars est ephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Igitur profecta omnis multitudo filiorum Israël de deserto Sin per mansiones suas, juxta sermonem Domini, castrametati sunt in Raphidim, ubi non erat aqua ad bibendum populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Qui jurgatus contra Moysen, ait: Da nobis aquam, ut bibamus. Quibus respondit Moyses: Quid jurgamini contra me? cur tentatis Dominum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Sitivit ergo ibi populus præ aquæ penuria, et murmuravit contra Moysen, dicens: Cur fecisti nos exire de \'gypto, ut occideres nos, et liberos nostros, ac jumenta siti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Clamavit autem Moyses ad Dominum, dicens: Quid faciam populo huic? adhuc paululum, et lapidabit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et ait Dominus ad Moysen: Antecede populum, et sume tecum de senioribus Israël: et virgam qua percussisti fluvium, tolle in manu tua, et vade.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'En ego stabo ibi coram te, supra petram Horeb: percutiesque petram, et exibit ex ea aqua, ut bibat populus. Fecit Moyses ita coram senioribus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'et vocavit nomen loci illius, Tentatio, propter jurgium filiorum Israël, et quia tentaverunt Dominum, dicentes: Estne Dominus in nobis, an non?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Venit autem Amalec, et pugnabat contra Israël in Raphidim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Dixitque Moyses ad Josue: Elige viros: et egressus, pugna contra Amalec: cras ego stabo in vertice collis, habens virgam Dei in manu mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Fecit Josue ut locutus erat Moyses, et pugnavit contra Amalec: Moyses autem et Aaron et Hur ascenderunt super verticem collis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Cumque levaret Moyses manus, vincebat Israël: sin autem paululum remisisset, superabat Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Manus autem Moysi erant graves: sumentes igitur lapidem, posuerunt subter eum, in quo sedit: Aaron autem et Hur sustentabant manus ejus ex utraque parte. Et factum est ut manus illius non lassarentur usque ad occasum solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Fugavitque Josue Amalec, et populum ejus in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Dixit autem Dominus ad Moysen: Scribe hoc ob monimentum in libro, et trade auribus Josue: delebo enim memoriam Amalec sub cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, '\'dificavitque Moyses altare: et vocavit nomen ejus, Dominus exaltatio mea, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Quia manus solii Domini, et bellum Domini erit contra Amalec, a generatione in generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Cumque audisset Jethro, sacerdos Madian, cognatus Moysi, omnia quæ fecerat Deus Moysi, et Israëli populo suo, et quod eduxisset Dominus Israël de \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'tulit Sephoram uxorem Moysi quam remiserat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'et duos filios ejus: quorum unus vocabatur Gersam, dicente patre: Advena fui in terra aliena;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'alter vero Eliezer: Deus enim, ait, patris mei adjutor meus, et eruit me de gladio Pharaonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Venit ergo Jethro cognatus Moysi, et filii ejus, et uxor ejus ad Moysen in desertum, ubi erat castrametatus juxta montem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Et mandavit Moysi, dicens: Ego Jethro cognatus tuus venio ad te, et uxor tua, et duo filii cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Qui egressus in occursum cognati sui, adoravit, et osculatus est eum: salutaveruntque se mutuo verbis pacificis. Cumque intrasset tabernaculum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'narravit Moyses cognato suo cuncta quæ fecerat Dominus Pharaoni et \'gyptiis propter Israël: universumque laborem, qui accidisset eis in itinere, et quod liberaverat eos Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Lætatusque est Jethro super omnibus bonis, quæ fecerat Dominus Israëli, eo quod eruisset eum de manu \'gyptiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Et ait: Benedictus Dominus, qui liberavit vos de manu \'gyptiorum, et de manu Pharaonis; qui eruit populum suum de manu \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nunc cognovi, quia magnus Dominus super omnes deos: eo quod superbe egerint contra illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Obtulit ergo Jethro cognatus Moysi holocausta et hostias Deo: veneruntque Aaron et omnes seniores Israël, ut comederent panem cum eo coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Altera autem die sedit Moyses ut judicaret populum, qui assistebat Moysi a mane usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Quod cum vidisset cognatus ejus, omnia scilicet quæ agebat in populo, ait: Quid est hoc quod facis in plebe? cur solus sedes, et omnis populus præstolatur de mane usque ad vesperam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Cui respondit Moyses: Venit ad me populus quærens sententiam Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'cumque acciderit eis aliqua disceptatio, veniunt ad me ut judicem inter eos, et ostendam præcepta Dei, et leges ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'At ille: Non bonam, inquit, rem facis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Stulto labore consumeris et tu, et populus iste qui tecum est: ultra vires tuas est negotium; solus illud non poteris sustinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Sed audi verba mea atque consilia, et erit Deus tecum. Esto tu populo in his quæ ad Deum pertinent, ut referas quæ dicuntur ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'ostendasque populo cæremonias et ritum colendi, viamque per quam ingredi debeant, et opus quod facere debeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Provide autem de omni plebe viros potentes, et timentes Deum, in quibus sit veritas, et qui oderint avaritiam, et constitue ex eis tribunos, et centuriones, et quinquagenarios, et decanos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'qui judicent populum omni tempore: quidquid autem majus fuerit, referant ad te, et ipsi minora tantummodo judicent: leviusque sit tibi, partito in alios onere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si hoc feceris, implebis imperium Dei, et præcepta ejus poteris sustentare: et omnis hic populus revertetur ad loca sua cum pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Quibus auditis, Moyses fecit omnia quæ ille suggesserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Et electis viris strenuis de cuncto Israël, constituit eos principes populi, tribunos, et centuriones, et quinquagenarios, et decanos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Qui judicabant plebem omni tempore: quidquid autem gravius erat, referebant ad eum, faciliora tantummodo judicantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Dimisitque cognatum suum: qui reversus abiit in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Mense tertio egressionis Israël de terra \'gypti, in die hac venerunt in solitudinem Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Nam profecti de Raphidim, et pervenientes usque in desertum Sinai, castrametati sunt in eodem loco, ibique Israël fixit tentoria e regione montis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Moyses autem ascendit ad Deum: vocavitque eum Dominus de monte, et ait: Hæc dices domui Jacob, et annuntiabis filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vos ipsi vidistis quæ fecerim \'gyptiis, quomodo portaverim vos super alas aquilarum, et assumpserim mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Si ergo audieritis vocem meam, et custodieritis pactum meum, eritis mihi in peculium de cunctis populis: mea est enim omnis terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'et vos eritis mihi in regnum sacerdotale, et gens sancta. Hæc sunt verba quæ loqueris ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Venit Moyses: et convocatis majoribus natu populi, exposuit omnes sermones quos mandaverat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Responditque omnis populus simul: Cuncta quæ locutus est Dominus, faciemus. Cumque retulisset Moyses verba populi ad Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'ait ei Dominus: Jam nunc veniam ad te in caligine nubis, ut audiat me populus loquentem ad te, et credat tibi in perpetuum. Nuntiavit ergo Moyses verba populi ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Qui dixit ei: Vade ad populum, et sanctifica illos hodie, et cras, laventque vestimenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Et sint parati in diem tertium: in die enim tertia descendet Dominus coram omni plebe super montem Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Constituesque terminos populo per circuitum, et dices ad eos: Cavete ne ascendatis in montem, nec tangatis fines illius: omnis qui tetigerit montem, morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Manus non tanget eum, sed lapidibus opprimetur, aut confodietur jaculis: sive jumentum fuerit, sive homo, non vivet: cum cœperit clangere buccina, tunc ascendant in montem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Descenditque Moyses de monte ad populum, et sanctificavit eum. Cumque lavissent vestimenta sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'ait ad eos: Estote parati in diem tertium, et ne appropinquetis uxoribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Jamque advenerat tertius dies, et mane inclaruerat: et ecce cœperunt audiri tonitrua, ac micare fulgura, et nubes densissima operire montem, clangorque buccinæ vehementius perstrepebat: et timuit populus qui erat in castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Cumque eduxisset eos Moyses in occursum Dei de loco castrorum, steterunt ad radices montis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Totus autem mons Sinai fumabat, eo quod descendisset Dominus super eum in igne: et ascenderet fumus ex eo quasi de fornace, eratque omnis mons terribilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Et sonitus buccinæ paulatim crescebat in majus, et prolixius tendebatur: Moyses loquebatur, et Deus respondebat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Descenditque Dominus super montem Sinai in ipso montis vertice, et vocavit Moysen in cacumen ejus. Quo cum ascendisset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'dixit ad eum: Descende, et contestare populum: ne forte velit transcendere terminos ad videndum Dominum, et pereat ex eis plurima multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Sacerdotes quoque qui accedunt ad Dominum, sanctificentur, ne percutiat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Dixitque Moyses ad Dominum: Non poterit vulgus ascendere in montem Sinai: tu enim testificatus es, et jussisti, dicens: Pone terminos circa montem, et sanctifica illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Cui ait Dominus: Vade, descende: ascendesque tu, et Aaron tecum: sacerdotes autem et populus ne transeant terminos, nec ascendant ad Dominum, ne forte interficiat illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Descenditque Moyses ad populum, et omnia narravit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Locutusque est Dominus cunctos sermones hos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ego sum Dominus Deus tuus, qui eduxi te de terra \'gypti, de domo servitutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Non habebis deos alienos coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Non facies tibi sculptile, neque omnem similitudinem quæ est in cælo desuper, et quæ in terra deorsum, nec eorum quæ sunt in aquis sub terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Non adorabis ea, neque coles: ego sum Dominus Deus tuus fortis, zelotes, visitans iniquitatem patrum in filios, in tertiam et quartam generationem eorum qui oderunt me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'et faciens misericordiam in millia his qui diligunt me, et custodiunt præcepta mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Non assumes nomen Domini Dei tui in vanum: nec enim habebit insontem Dominus eum qui assumpserit nomen Domini Dei sui frustra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Memento ut diem sabbati sanctifices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sex diebus operaberis, et facies omnia opera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Septimo autem die sabbatum Domini Dei tui est: non facies omne opus in eo, tu, et filius tuus et filia tua, servus tuus et ancilla tua, jumentum tuum, et advena qui est intra portas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Sex enim diebus fecit Dominus cælum et terram, et mare, et omnia quæ in eis sunt, et requievit in die septimo: idcirco benedixit Dominus diei sabbati, et sanctificavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honora patrem tuum et matrem tuam, ut sis longævus super terram, quam Dominus Deus tuus dabit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Non occides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Non mœchaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Non furtum facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Non loqueris contra proximum tuum falsum testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Non concupisces domum proximi tui, nec desiderabis uxorem ejus, non servum, non ancillam, non bovem, non asinum, nec omnia quæ illius sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Cunctus autem populus videbat voces et lampades, et sonitum buccinæ, montemque fumantem: et perterriti ac pavore concussi, steterunt procul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'dicentes Moysi: Loquere tu nobis, et audiemus: non loquatur nobis Dominus, ne forte moriamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Et ait Moyses ad populum: Nolite timere: ut enim probaret vos venit Deus, et ut terror illius esset in vobis, et non peccaretis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Stetitque populus de longe. Moyses autem accessit ad caliginem in qua erat Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Dixit præterea Dominus ad Moysen: Hæc dices filiis Israël: Vos vidistis quod de cælo locutus sim vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Non facietis deos argenteos, nec deos aureos facietis vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Altare de terra facietis mihi, et offeretis super eo holocausta et pacifica vestra, oves vestras et boves in omni loco in quo memoria fuerit nominis mei: veniam ad te, et benedicam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Quod si altare lapideum feceris mihi, non ædificabis illud de sectis lapidibus: si enim levaveris cultrum super eo, polluetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Non ascendes per gradus ad altare meum, ne reveletur turpitudo tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Hæc sunt judicia quæ propones eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si emeris servum hebræum, sex annis serviet tibi: in septimo egredietur liber gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Cum quali veste intraverit, cum tali exeat: si habens uxorem, et uxor egredietur simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Sin autem dominus dederit illi uxorem, et pepererit filios et filias: mulier et liberi ejus erunt domini sui, ipse vero exibit cum vestitu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Quod si dixerit servus: Diligo dominum meum et uxorem ac liberos; non egrediar liber:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'offeret eum dominus diis, et applicabitur ad ostium et postes, perforabitque aurem ejus subula: et erit ei servus in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Si quis vendiderit filiam suam in famulam, non egredietur sicut ancillæ exire consueverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si displicuerit oculis domini sui cui tradita fuerat, dimittet eam: populo autem alieno vendendi non habebit potestatem, si spreverit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Sin autem filio suo desponderit eam, juxta morem filiarum faciet illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Quod si alteram ei acceperit, providebit puellæ nuptias, et vestimenta, et pretium pudicitiæ non negabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Si tria ista non fecerit, egredietur gratis absque pecunia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Qui percusserit hominem volens occidere, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Qui autem non est insidiatus, sed Deus illum tradidit in manus ejus, constituam tibi locum in quem fugere debeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Si quis per industriam occiderit proximum suum, et per insidias: ab altari meo evelles eum, ut moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Qui percusserit patrem suum aut matrem, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Qui furatus fuerit hominem, et vendiderit eum, convictus noxæ, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Qui maledixerit patri suo, vel matri, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Si rixati fuerint viri, et percusserit alter proximum suum lapide vel pugno, et ille mortuus non fuerit, sed jacuerit in lectulo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'si surrexerit, et ambulaverit foris super baculum suum, innocens erit qui percusserit, ita tamen ut operas ejus et impensas in medicos restituat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Qui percusserit servum suum, vel ancillam virga, et mortui fuerint in manibus ejus, criminis reus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Sin autem uno die vel duobus supervixerit, non subjacebit pœnæ, quia pecunia illius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Si rixati fuerint viri, et percusserit quis mulierem prægnantem, et abortivum quidem fecerit, sed ipsa vixerit: subjacebit damno quantum maritus mulieris expetierit, et arbitri judicaverint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Sin autem mors ejus fuerit subsecuta, reddet animam pro anima,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'oculum pro oculo, dentem pro dente, manum pro manu, pedem pro pede,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'adustionem pro adustione, vulnus pro vulnere, livorem pro livore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Si percusserit quispiam oculum servi sui aut ancillæ, et luscos eos fecerit, dimittet eos liberos pro oculo quem eruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Dentem quoque si excusserit servo vel ancillæ suæ, similiter dimittet eos liberos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Si bos cornu percusserit virum aut mulierem, et mortui fuerint, lapidibus obruetur: et non comedentur carnes ejus, dominus quoque bovis innocens erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Quod si bos cornupeta fuerit ab heri et nudiustertius, et contestati sunt dominum ejus, nec recluserit eum, occideritque virum aut mulierem: et bos lapidibus obruetur, et dominum ejus occident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Quod si pretium fuerit ei impositum, dabit pro anima sua quidquid fuerit postulatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Filium quoque et filiam si cornu percusserit, simili sententiæ subjacebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si servum ancillamque invaserit, triginta siclos argenti domino dabit, bos vero lapidibus opprimetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Si quis aperuerit cisternam, et foderit, et non operuerit eam, cecideritque bos aut asinus in eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'reddet dominus cisternæ pretium jumentorum: quod autem mortuum est, ipsius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Si bos alienus bovem alterius vulneraverit, et ille mortuus fuerit: vendent bovem vivum, et divident pretium, cadaver autem mortui inter se dispertient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Sin autem sciebat quod bos cornupeta esset ab heri et nudiustertius, et non custodivit eum dominus suus: reddet bovem pro bove, et cadaver integrum accipiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Si quis furatus fuerit bovem aut ovem, et occiderit vel vendiderit: quinque boves pro uno bove restituet, et quatuor oves pro una ove.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si effringens fur domum sive suffodiens fuerit inventus, et accepto vulnere mortuus fuerit, percussor non erit reus sanguinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Quod si orto sole hoc fecerit, homicidium perpetravit, et ipse morietur. Si non habuerit quod pro furto reddat, ipse venundabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si inventum fuerit apud eum quod furatus est, vivens: sive bos, sive asinus, sive ovis, duplum restituet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si læserit quispiam agrum vel vineam, et dimiserit jumentum suum ut depascatur aliena: quidquid optimum habuerit in agro suo, vel in vinea, pro damni æstimatione restituet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Si egressus ignis invenerit spinas, et comprehenderit acervos frugum, sive stantes segetes in agris, reddet damnum qui ignem succenderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Si quis commendaverit amico pecuniam aut vas in custodiam, et ab eo, qui susceperat, furto ablata fuerint: si invenitur fur, duplum reddet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'si latet fur, dominus domus applicabitur ad deos, et jurabit quod non extenderit manum in rem proximi sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'ad perpetrandam fraudem, tam in bove quam in asino, et ove ac vestimento, et quidquid damnum inferre potest: ad deos utriusque causa perveniet, et si illi judicaverint, duplum restituet proximo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si quis commendaverit proximo suo asinum, bovem, ovem, et omne jumentum ad custodiam, et mortuum fuerit, aut debilitatum, vel captum ab hostibus, nullusque hoc viderit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'jusjurandum erit in medio, quod non extenderit manum ad rem proximi sui: suscipietque dominus juramentum, et ille reddere non cogetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Quod si furto ablatum fuerit, restituet damnum domino;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'si comestum a bestia, deferat ad eum quod occisum est, et non restituet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Qui a proximo suo quidquam horum mutuo postulaverit, et debilitatum aut mortuum fuerit domino non præsente, reddere compelletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Quod si impræsentiarum dominus fuerit, non restituet, maxime si conductum venerat pro mercede operis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si seduxerit quis virginem necdum desponsatam, dormieritque cum ea: dotabit eam, et habebit eam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si pater virginis dare noluerit, reddet pecuniam juxta modum dotis, quam virgines accipere consueverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Maleficos non patieris vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Qui coierit cum jumento, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Qui immolat diis, occidetur, præterquam Domino soli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Advenam non contristabis, neque affliges eum: advenæ enim et ipsi fuistis in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Viduæ et pupillo non nocebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si læseritis eos, vociferabuntur ad me, et ego audiam clamorem eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'et indignabitur furor meus, percutiamque vos gladio, et erunt uxores vestræ viduæ, et filii vestri pupilli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si pecuniam mutuam dederis populo meo pauperi qui habitat tecum, non urgebis eum quasi exactor, nec usuris opprimes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si pignus a proximo tuo acceperis vestimentum, ante solis occasum reddes ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Ipsum enim est solum, quo operitur, indumentum carnis ejus, nec habet aliud in quo dormiat: si clamaverit ad me, exaudiam eum, quia misericors sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Diis non detrahes, et principi populi tui non maledices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Decimas tuas et primitias tuas non tardabis reddere: primogenitum filiorum tuorum dabis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'De bobus quoque, et ovibus similiter facies: septem diebus sit cum matre sua, die octava reddes illum mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Viri sancti eritis mihi: carnem, quæ a bestiis fuerit prægustata, non comedetis, sed projicietis canibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Non suscipies vocem mendacii, nec junges manum tuam ut pro impio dicas falsum testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Non sequeris turbam ad faciendum malum: nec in judicio, plurimorum acquiesces sententiæ, ut a vero devies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Pauperis quoque non misereberis in judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si occurreris bovi inimici tui, aut asino erranti, reduc ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si videris asinum odientis te jacere sub onere, non pertransibis, sed sublevabis cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Non declinabis in judicium pauperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Mendacium fugies. Insontem et justum non occides: quia aversor impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Nec accipies munera, quæ etiam excæcant prudentes, et subvertunt verba justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Peregrino molestus non eris. Scitis enim advenarum animas: quia et ipsi peregrini fuistis in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sex annis seminabis terram tuam, et congregabis fruges ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'anno autem septimo dimittes eam, et requiescere facies, ut comedant pauperes populi tui: et quidquid reliquum fuerit, edant bestiæ agri: ita facies in vinea et in oliveto tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sex diebus operaberis: septimo die cessabis, ut requiescat bos et asinus tuus, et refrigeretur filius ancillæ tuæ, et advena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Omnia quæ dixi vobis, custodite. Et per nomen externorum deorum non jurabitis, neque audietur ex ore vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tribus vicibus per singulos annos mihi festa celebrabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Solemnitatem azymorum custodies. Septem diebus comedes azyma, sicut præcepi tibi, tempore mensis novorum, quando egressus es de \'gypto: non apparebis in conspectu meo vacuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Et solemnitatem messis primitivorum operis tui, quæcumque seminaveris in agro: solemnitatem quoque in exitu anni, quando congregaveris omnes fruges tuas de agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Ter in anno apparebit omne masculinum tuum coram Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Non immolabis super fermento sanguinem victimæ meæ, nec remanebit adeps solemnitatis meæ usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Primitias frugum terræ tuæ deferes in domum Domini Dei tui. Non coques hædum in lacte matris suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ecce ego mittam angelum meum, qui præcedat te, et custodiat in via, et introducat in locum quem paravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Observa eum, et audi vocem ejus, nec contemnendum putes: quia non dimittet cum peccaveris, et est nomen meum in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Quod si audieris vocem ejus, et feceris omnia quæ loquor, inimicus ero inimicis tuis, et affligam affligentes te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Præcedetque te angelus meus, et introducet te ad Amorrhæum, et Hethæum, et Pherezæum, Chananæumque, et Hevæum, et Jebusæum, quos ego conteram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Non adorabis deos eorum, nec coles eos: non facies opera eorum, sed destrues eos, et confringes statuas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Servietisque Domino Deo vestro, ut benedicam panibus tuis et aquis, et auferam infirmitatem de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Non erit infœcunda, nec sterilis in terra tua: numerum dierum tuorum implebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Terrorem meum mittam in præcursum tuum, et occidam omnem populum, ad quem ingredieris: cunctorumque inimicorum tuorum coram te terga vertam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'emittens crabrones prius, qui fugabunt Hevæum, et Chananæum, et Hethæum, antequam introëas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Non ejiciam eos a facie tua anno uno: ne terra in solitudinem redigatur, et crescant contra te bestiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Paulatim expellam eos de conspectu tuo, donec augearis, et possideas terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Ponam autem terminos tuos a mari Rubro usque ad mare Palæstinorum, et a deserto usque ad fluvium: tradam in manibus vestris habitatores terræ, et ejiciam eos de conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Non inibis cum eis fœdus, nec cum diis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Non habitent in terra tua, ne forte peccare te faciant in me, si servieris diis eorum: quod tibi certe erit in scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Moysi quoque dixit: Ascende ad Dominum tu, et Aaron, Nadab et Abiu, et septuaginta senes ex Israël, et adorabitis procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Solusque Moyses ascendet ad Dominum, et illi non appropinquabunt: nec populus ascendet cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Venit ergo Moyses et narravit plebi omnia verba Domini, atque judicia: responditque omnis populus una voce: Omnia verba Domini, quæ locutus est, faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Scripsit autem Moyses universos sermones Domini: et mane consurgens, ædificavit altare ad radices montis, et duodecim titulos per duodecim tribus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Misitque juvenes de filiis Israël, et obtulerunt holocausta, immolaveruntque victimas pacificas Domino, vitulos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Tulit itaque Moyses dimidiam partem sanguinis, et misit in crateras: partem autem residuam fudit super altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Assumensque volumen fœderis, legit audiente populo: qui dixerunt: Omnia quæ locutus est Dominus, faciemus, et erimus obedientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Ille vero sumptum sanguinem respersit in populum, et ait: Hic est sanguis fœderis quod pepigit Dominus vobiscum super cunctis sermonibus his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Ascenderuntque Moyses et Aaron, Nadab et Abiu, et septuaginta de senioribus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'et viderunt Deum Israël: et sub pedibus ejus quasi opus lapidis sapphirini, et quasi cælum, cum serenum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Nec super eos qui procul recesserant de filiis Israël, misit manum suam, videruntque Deum, et comederunt, ac biberunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Dixit autem Dominus ad Moysen: Ascende ad me in montem, et esto ibi: daboque tibi tabulas lapideas, et legem, ac mandata quæ scripsi: ut doceas eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Surrexerunt Moyses et Josue minister ejus: ascendensque Moyses in montem Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'senioribus ait: Expectate hic donec revertamur ad vos. Habetis Aaron et Hur vobiscum: si quid natum fuerit quæstionis, referetis ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Cumque ascendisset Moyses, operuit nubes montem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'et habitavit gloria Domini super Sinai, tegens illum nube sex diebus: septimo autem die vocavit eum de medio caliginis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Erat autem species gloriæ Domini quasi ignis ardens super verticem montis in conspectu filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Ingressusque Moyses medium nebulæ, ascendit in montem: et fuit ibi quadraginta diebus, et quadraginta noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Loquere filiis Israël, ut tollant mihi primitias: ab omni homine qui offeret ultroneus, accipietis eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Hæc sunt autem quæ accipere debeatis: aurum, et argentum, et æs,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'hyacinthum et purpuram, coccumque bis tinctum, et byssum, pilos caprarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'et pelles arietum rubricatas, pellesque janthinas, et ligna setim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'oleum ad luminaria concinnanda: aromata in unguentum, et thymiamata boni odoris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'lapides onychinos, et gemmas ad ornandum ephod, ac rationale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Facientque mihi sanctuarium, et habitabo in medio eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'juxta omnem similitudinem tabernaculi quod ostendam tibi, et omnium vasorum in cultum ejus. Sicque facietis illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'arcam de lignis setim compingite, cujus longitudo habeat duos et semis cubitos: latitudo, cubitum et dimidium: altitudo, cubitum similiter ac semissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Et deaurabis eam auro mundissimo intus et foris: faciesque supra, coronam auream per circuitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'et quatuor circulos aureos, quos pones per quatuor arcæ angulos: duo circuli sint in latere uno, et duo in altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Facies quoque vectes de lignis setim, et operies eos auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Inducesque per circulos qui sunt in arcæ lateribus, ut portetur in eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'qui semper erunt in circulis, nec umquam extrahentur ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Ponesque in arca testificationem quam dabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Facies et propitiatorium de auro mundissimo: duos cubitos et dimidium tenebit longitudo ejus, et cubitum ac semissem latitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Duos quoque cherubim aureos et productiles facies, ex utraque parte oraculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Cherub unus sit in latere uno, et alter in altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Utrumque latus propitiatorii tegant expandentes alas, et operientes oraculum, respiciantque se mutuo versis vultibus in propitiatorium quo operienda est arca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'in qua pones testimonium quod dabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Inde præcipiam, et loquar ad te supra propitiatorium, ac de medio duorum cherubim, qui erunt super arcam testimonii, cuncta quæ mandabo per te filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Facies et mensam de lignis setim, habentem duos cubitos longitudinis, et in latitudine cubitum, et in altitudine cubitum et semissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Et inaurabis eam auro purissimo: faciesque illi labium aureum per circuitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'et ipsi labio coronam interrasilem altam quatuor digitis: et super illam, alteram coronam aureolam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Quatuor quoque circulos aureos præparabis, et pones eis in quatuor angulis ejusdem mensæ per singulos pedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Subter coronam erunt circuli aurei, ut mittantur vectes per eos, et possit mensa portari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Ipsos quoque vectes facies de lignis setim, et circumdabis auro ad subvehendam mensam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Parabis et acetabula, ac phialas, thuribula, et cyathos, in quibus offerenda sunt libamina, ex auro purissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et pones super mensam panes propositionis in conspectu meo semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Facies et candelabrum ductile de auro mundissimo, hastile ejus, et calamos, scyphos, et sphærulas, ac lilia ex ipso procedentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sex calami egredientur de lateribus, tres ex uno latere, et tres ex altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tres scyphi quasi in nucis modum per calamos singulos, sphærulaque simul, et lilium: et tres similiter scyphi instar nucis in calamo altero, sphærulaque simul et lilium. Hoc erit opus sex calamorum, qui producendi sunt de hastili:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'in ipso autem candelabro erunt quatuor scyphi in nucis modum, sphærulæque per singulos, et lilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Sphærulæ sub duobus calamis per tria loca, qui simul sex fiunt procedentes de hastili uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Et sphærulæ igitur et calami ex ipso erunt, universa ductilia de auro purissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Facies et lucernas septem, et pones eas super candelabrum, ut luceant ex adverso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Emunctoria quoque, et ubi quæ emuncta sunt extinguantur, fiant de auro purissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Omne pondus candelabri cum universis vasis suis habebit talentum auri purissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Inspice, et fac secundum exemplar quod tibi in monte monstratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Tabernaculum vero ita facies: decem cortinas de bysso retorta, et hyacintho, ac purpura, coccoque bis tincto, variatas opere plumario facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Longitudo cortinæ unius habebit viginti octo cubitos: latitudo, quatuor cubitorum erit. Unius mensuræ fient universa tentoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Quinque cortinæ sibi jungentur mutuo, et aliæ quinque nexu simili cohærebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Ansulas hyacinthinas in lateribus ac summitatibus facies cortinarum, ut possint invicem copulari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Quinquagenas ansulas cortina habebit in utraque parte, ita insertas ut ansa contra ansam veniat, et altera alteri possit aptari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Facies et quinquaginta circulos aureos quibus cortinarum vela jungenda sunt, ut unum tabernaculum fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Facies et saga cilicina undecim, ad operiendum tectum tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Longitudo sagi unius habebit triginta cubitos, et latitudo, quatuor: æqua erit mensura sagorum omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'E quibus quinque junges seorsum, et sex sibi mutuo copulabis, ita ut sextum sagum in fronte tecti duplices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Facies et quinquaginta ansas in ora sagi unius, ut conjungi cum altero queat, et quinquaginta ansas in ora sagi alterius, ut cum altero copuletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Facies et quinquaginta fibulas æneas quibus jungantur ansæ, ut unum ex omnibus operimentum fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Quod autem superfuerit in sagis quæ parantur tecto, id est unum sagum quod amplius est, ex medietate ejus operies posteriora tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Et cubitus ex una parte pendebit, et alter ex altera qui plus est in sagorum longitudine, utrumque latus tabernaculi protegens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Facies et operimentum aliud tecto de pellibus arietum rubricatis: et super hoc rursum aliud operimentum de janthinis pellibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Facies et tabulas stantes tabernaculi de lignis setim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'quæ singulæ denos cubitos in longitudine habeant, et in latitudine singulos ac semissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'In lateribus tabulæ, duæ incastraturæ fient, quibus tabula alteri tabulæ connectatur: atque in hunc modum cunctæ tabulæ parabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Quarum viginti erunt in latere meridiano quod vergit ad austrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Quibus quadraginta bases argenteas fundes, ut binæ bases singulis tabulis per duos angulos subjiciantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'In latere quoque secundo tabernaculi quod vergit ad aquilonem, viginti tabulæ erunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'quadraginta habentes bases argenteas, binæ bases singulis tabulis supponentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Ad occidentalem vero plagam tabernaculi facies sex tabulas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'et rursum alias duas quæ in angulis erigantur post tergum tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Eruntque conjunctæ a deorsum usque sursum, et una omnes compago retinebit. Duabus quoque tabulis quæ in angulis ponendæ sunt, similis junctura servabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Et erunt simul tabulæ octo, bases earum argenteæ sedecim, duabus basibus per unam tabulam supputatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Facies et vectes de lignis setim quinque ad continendas tabulas in uno latere tabernaculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'et quinque alios in altero, et ejusdem numeri ad occidentalem plagam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'qui mittentur per medias tabulas a summo usque ad summum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Ipsas quoque tabulas deaurabis, et fundes in eis annulos aureos per quos vectes tabulata contineant: quos operies laminis aureis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Et eriges tabernaculum juxta exemplar quod tibi in monte monstratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Facies et velum de hyacintho, et purpura, coccoque bis tincto, et bysso retorta, opere plumario et pulchra varietate contextum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'quod appendes ante quatuor columnas de lignis setim, quæ ipsæ quidem deauratæ erunt, et habebunt capita aurea, sed bases argenteas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Inseretur autem velum per circulos, intra quod pones arcam testimonii, quo et sanctuarium, et sanctuarii sanctuaria dividentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Pones et propitiatorium super arcam testimonii in Sancto sanctorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'mensamque extra velum, et contra mensam candelabrum in latere tabernaculi meridiano: mensa enim stabit in parte aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Facies et tentorium in introitu tabernaculi de hyacintho, et purpura, coccoque bis tincto, et bysso retorta, opere plumarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Et quinque columnas deaurabis lignorum setim, ante quas ducetur tentorium: quarum erunt capita aurea, et bases æneæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Facies et altare de lignis setim, quod habebit quinque cubitus in longitudine, et totidem in latitudine, id est, quadrum, et tres cubitos in altitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Cornua autem per quatuor angulos ex ipso erunt: et operies illud ære.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Faciesque in usus ejus lebetes ad suscipiendos cineres, et forcipes atque fuscinulas, et ignium receptacula; omnia vasa ex ære fabricabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Craticulamque in modum retis æneam: per cujus quatuor angulos erunt quatuor annuli ænei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Quos pones subter arulam altaris: eritque craticula usque ad altaris medium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Facies et vectes altaris de lignis setim duos, quos operies laminis æneis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'et induces per circulos, eruntque ex utroque latere altaris ad portandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Non solidum, sed inane et cavum intrinsecus facies illud, sicut tibi in monte monstratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Facies et atrium tabernaculi, in cujus australi plaga contra meridiem erunt tentoria de bysso retorta: centum cubitos unum latus tenebit in longitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Et columnas viginti cum basibus totidem æneis, quæ capita cum cælaturis suis habebunt argentea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Similiter et in latere aquilonis per longum erunt tentoria centum cubitorum, columnæ viginti, et bases æneæ ejusdem numeri, et capita earum cum cælaturis suis argentea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'In latitudine vero atrii, quod respicit ad occidentem, erunt tentoria per quinquaginta cubitos, et columnæ decem, basesque totidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'In ea quoque atrii latitudine, quæ respicit ad orientem, quinquaginta cubiti erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'In quibus quindecim cubitorum tentoria lateri uno deputabuntur, columnæque tres et bases totidem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'et in latere altero erunt tentoria cubitos obtinentia quindecim, columnæ tres, et bases totidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'In introitu vero atrii fiet tentorium cubitorum viginti ex hyacintho et purpura, coccoque bis tincto, et bysso retorta, opere plumarii: columnas habebit quatuor, cum basibus totidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Omnes columnæ atrii per circuitum vestitæ erunt argenteis laminis, capitibus argenteis, et basibus æneis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'In longitudine occupabit atrium cubitos centum, in latitudine quinquaginta, altitudo quinque cubitorum erit: fietque de bysso retorta, et habebit bases æneas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Cuncta vasa tabernaculi in omnes usus et cæremonias, tam paxillos ejus quam atrii, ex ære facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Præcipe filiis Israël ut afferant tibi oleum de arboribus olivarum purissimum, piloque contusum, ut ardeat lucerna semper');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'in tabernaculo testimonii, extra velum quod oppansum est testimonio. Et collocabunt eam Aaron et filii ejus, ut usque mane luceat coram Domino. Perpetuus erit cultus per successiones eorum a filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Applica quoque ad te Aaron fratrem tuum cum filiis suis de medio filiorum Israël, ut sacerdotio fungantur mihi: Aaron, Nadab, et Abiu, Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Faciesque vestem sanctam Aaron fratri tuo in gloriam et decorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Et loqueris cunctis sapientibus corde quos replevi spiritu prudentiæ, ut faciant vestes Aaron, in quibus sanctificatus ministret mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Hæc autem erunt vestimenta quæ faciet: rationale et superhumerale, tunicam et lineam strictam, cidarim et balteum. Facient vestimenta sancta fratri tuo Aaron et filiis ejus, ut sacerdotio fungantur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Accipientque aurum, et hyacinthum, et purpuram, coccumque bis tinctum, et byssum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Facient autem superhumerale de auro et hyacintho et purpura, coccoque bis tincto, et bysso retorta, opere polymito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Duas oras junctas habebit in utroque latere summitatum, ut in unum redeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Ipsa quoque textura et cuncta operis varietas erit ex auro et hyacintho, et purpura, coccoque bis tincto, et bysso retorta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Sumesque duos lapides onychinos, et sculpes in eis nomina filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sex nomina in lapide uno, et sex reliqua in altero, juxta ordinem nativitatis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Opere sculptoris et cælatura gemmarii, sculpes eos nominibus filiorum Israël, inclusos auro atque circumdatos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'et pones in utroque latere superhumeralis, memoriale filiis Israël. Portabitque Aaron nomina eorum coram Domino super utrumque humerum, ob recordationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Facies et uncinos ex auro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'et duas catenulas ex auro purissimo sibi invicem cohærentes, quas inseres uncinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Rationale quoque judicii facies opere polymito juxta texturam superhumeralis, ex auro, hyacintho, et purpura, coccoque bis tincto, et bysso retorta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Quadrangulum erit et duplex: mensuram palmi habebit tam in longitudine quam in latitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Ponesque in eo quatuor ordines lapidum: in primo versu erit lapis sardius, et topazius, et smaragdus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'in secundo carbunculus, sapphirus, et jaspis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'in tertio ligurius, achates, et amethystus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'in quarto chrysolithus, onychinus, et beryllus. Inclusi auro erunt per ordines suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Habebuntque nomina filiorum Israël: duodecim nominibus cælabuntur, singuli lapides nominibus singulorum per duodecim tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Facies in rationali catenas sibi invicem cohærentes ex auro purissimo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'et duos annulos aureos, quos pones in utraque rationalis summitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'catenasque aureas junges annulis, qui sunt in marginibus ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'et ipsarum catenarum extrema duobus copulabis uncinis in utroque latere superhumeralis quod rationale respicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Facies et duos annulos aureos, quos pones in summitatibus rationalis, in oris, quæ e regione sunt superhumeralis, et posteriora ejus aspiciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Necnon et alios duos annulos aureos, qui ponendi sunt in utroque latere superhumeralis deorsum, quod respicit contra faciem juncturæ inferioris, ut aptari possit cum superhumerali,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'et stringatur rationale annulis suis cum annulis superhumeralis vitta hyacinthina, ut maneat junctura fabrefacta, et a se invicem rationale et superhumerale nequeant separari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Portabitque Aaron nomina filiorum Israël in rationali judicii super pectus suum, quando ingredietur Sanctuarium, memoriale coram Domino in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Pones autem in rationali judicii Doctrinam et Veritatem, quæ erunt in pectore Aaron, quando ingredietur coram Domino: et gestabit judicium filiorum Israël in pectore suo, in conspectu Domini semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Facies et tunicam superhumeralis totam hyacinthinam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'in cujus medio supra erit capitium, et ora per gyrum ejus textilis, sicut fieri solet in extremis vestium partibus, ne facile rumpatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Deorsum vero, ad pedes ejusdem tunicæ, per circuitum, quasi mala punica facies, ex hyacintho, et purpura, et cocco bis tincto, mistis in medio tintinnabulis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'ita ut tintinnabulum sit aureum et malum punicum: rursumque tintinnabulum aliud aureum et malum punicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Et vestietur ea Aaron in officio ministerii, ut audiatur sonitus quando ingreditur et egreditur sanctuarium in conspectu Domini, et non moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Facies et laminam de auro purissimo, in qua sculpes opere cælatoris, Sanctum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Ligabisque eam vitta hyacinthina, et erit super tiaram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'imminens fronti pontificis. Portabitque Aaron iniquitates eorum, quæ obtulerunt et sanctificaverunt filii Israël, in cunctis muneribus et donariis suis. Erit autem lamina semper in fronte ejus, ut placatus sit eis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Stringesque tunicam bysso, et tiaram byssinam facies, et balteum opere plumarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Porro filiis Aaron tunicas lineas parabis et balteos ac tiaras in gloriam et decorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'vestiesque his omnibus Aaron fratrem tuum et filios ejus cum eo. Et cunctorum consecrabis manus, sanctificabisque illos, ut sacerdotio fungantur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Facies et feminalia linea, ut operiant carnem turpitudinis suæ, a renibus usque ad femora:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'et utentur eis Aaron et filii ejus quando ingredientur tabernaculum testimonii, vel quando appropinquant ad altare ut ministrent in sanctuario, ne iniquitatis rei moriantur. Legitimum sempiternum erit Aaron, et semini ejus post eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Sed et hoc facies, ut mihi in sacerdotio consecrentur. Tolle vitulum de armento, et arietes duos immaculatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'panesque azymos, et crustulam absque fermento, quæ conspersa sit oleo, lagana quoque azyma oleo lita: de simila triticea cuncta facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Et posita in canistro offeres: vitulum autem et duos arietes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Et Aaron ac filios ejus applicabis ad ostium tabernaculi testimonii. Cumque laveris patrem cum filiis suis aqua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'indues Aaron vestimentis suis, id est, linea et tunica, et superhumerali et rationali, quod constringes balteo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Et pones tiaram in capite ejus, et laminam sanctam super tiaram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'et oleum unctionis fundes super caput ejus: atque hoc ritu consecrabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Filios quoque illius applicabis, et indues tunicis lineis, cingesque balteo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Aaron scilicet et liberos ejus, et impones eis mitras: eruntque sacerdotes mihi religione perpetua. Postquam initiaveris manus eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'applicabis et vitulum coram tabernaculo testimonii. Imponentque Aaron et filii ejus manus super caput illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'et mactabis eum in conspectu Domini, juxta ostium tabernaculi testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Sumptumque de sanguine vituli, pones super cornua altaris digito tuo, reliquum autem sanguinem fundes juxta basim ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Sumes et adipem totum qui operit intestina, et reticulum jecoris, ac duos renes, et adipem qui super eos est, et offeres incensum super altare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'carnes vero vituli et corium et fimum combures foris extra castra, eo quod pro peccato sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Unum quoque arietem sumes, super cujus caput ponent Aaron et filii ejus manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Quem cum mactaveris, tolles de sanguine ejus, et fundes circa altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Ipsum autem arietem secabis in frustra: lotaque intestina ejus ac pedes, pones super concisas carnes, et super caput illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Et offeres totum arietem in incensum super altare: oblatio est Domino, odor suavissimus victimæ Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Tolles quoque arietem alterum, super cujus caput Aaron et filii ejus ponent manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Quem cum immolaveris, sumes de sanguine ejus, et pones super extremum auriculæ dextræ Aaron et filiorum ejus, et super pollices manus eorum ac pedis dextri, fundesque sanguinem super altare per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Cumque tuleris de sanguine qui est super altare, et de oleo unctionis, asperges Aaron et vestes ejus, filios et vestimenta eorum. Consecratisque ipsis et vestibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'tolles adipem de ariete, et caudam et arvinam, quæ operit vitalia, ac reticulum jecoris, et duos renes, atque adipem, qui super eos est, armumque dextrum, eo quod sit aries consecrationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'tortamque panis unius, crustulam conspersam oleo, laganum de canistro azymorum, quod positum est in conspectu Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'ponesque omnia super manus Aaron et filiorum ejus, et sanctificabis eos elevans coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Suscipiesque universa de manibus eorum: et incendes super altare in holocaustum, odorem suavissimum in conspectu Domini, quia oblatio ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Sumes quoque pectusculum de ariete, quo initiatus est Aaron, sanctificabisque illud elevatum coram Domino, et cedet in partem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Sanctificabisque et pectusculum consecratum, et armum quem de ariete separasti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'quo initiatus est Aaron et filii ejus, cedentque in partem Aaron et filiorum ejus jure perpetuo a filiis Israël: quia primitiva sunt et initia de victimis eorum pacificis quæ offerunt Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Vestem autem sanctam, qua utetur Aaron, habebunt filii ejus post eum, ut ungantur in ea, et consecrantur manus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Septem diebus utetur illa qui pontifex pro eo fuerit constitutus de filiis ejus, et qui ingredietur tabernaculum testimonii ut ministret in sanctuario.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Arietem autem consecrationis tolles, et coques carnes ejus in loco sancto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'quibus vescetur Aaron et filii ejus. Panes quoque, qui sunt in canistro, in vestibulo tabernaculi testimonii comedent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'ut sit placabile sacrificium, et sanctificentur offerentium manus. Alienigena non vescetur ex eis, quia sancti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Quod si remanserit de carnibus consecratis, sive de panibus usque mane, combures reliquias igni: non comedentur, quia sanctificata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Omnia, quæ præcepi tibi, facies super Aaron et filiis ejus. Septem diebus consecrabis manus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'et vitulum pro peccato offeres per singulos dies ad expiandum. Mundabisque altare cum immolaveris expiationis hostiam, et unges illud in sanctificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Septem diebus expiabis altare, et sanctificabis, et erit Sanctum sanctorum: omnis, qui tetigerit illud, sanctificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Hoc est quod facies in altari: agnos anniculos duos per singulos dies jugiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'unum agnum mane, et alterum vespere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'decimam partem similæ conspersæ oleo tuso, quod habeat mensuram quartam partem hin, et vinum ad libandum ejusdem mensuræ in agno uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Alterum vero agnum offeres ad vesperam juxta ritum matutinæ oblationis, et juxta ea quæ diximus, in odorem suavitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'sacrificium est Domino, oblatione perpetua in generationes vestras, ad ostium tabernaculi testimonii coram Domino, ubi constituam ut loquar ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Ibique præcipiam filiis Israël, et sanctificabitur altare in gloria mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Sanctificabo et tabernaculum testimonii cum altari, et Aaron cum filiis suis, ut sacerdotio fungantur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Et habitabo in medio filiorum Israël, eroque eis Deus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'et scient quia ego Dominus Deus eorum, qui eduxi eos de terra \'gypti, ut manerem inter illos, ego Dominus Deus ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Facies quoque altare ad adolendum thymiama, de lignis setim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'habens cubitum longitudinis, et alterum latitudinis, id est, quadrangulum, et duos cubitos in altitudine. Cornua ex ipso procedent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Vestiesque illud auro purissimo, tam craticulam ejus, quam parietes per circuitum, et cornua. Faciesque ei coronam aureolam per gyrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'et duos annulos aureos sub corona per singula latera, ut mittantur in eos vectes, et altare portetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Ipsos quoque vectes facies de lignis setim, et inaurabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Ponesque altare contra velum, quod ante arcum pendet testimonii coram propitiatorio quo tegitur testimonium, ubi loquar tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et adolebit incensum super eo Aaron, suave fragrans, mane. Quando componet lucernas, incendet illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'et quando collocabit eas ad vesperum, uret thymiama sempiternum coram Domino in generationes vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Non offeretis super eo thymiama compositionis alterius, nec oblationem, et victimam, nec libabitis libamina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Et deprecabitur Aaron super cornua ejus semel per annum, in sanguine quod oblatum est pro peccato, et placabit super eo in generationibus vestris. Sanctum sanctorum erit Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Quando tuleris summam filiorum Israël juxta numerum, dabunt singuli pretium pro animabus suis Domino, et non erit plaga in eis, cum fuerint recensiti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Hoc autem dabit omnis qui transit ad nomen, dimidium sicli juxta mensuram templi (siclus viginti obolos habet); media pars sicli offeretur Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Qui habetur in numero, a viginti annis et supra, dabit pretium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Dives non addet ad medium sicli, et pauper nihil minuet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Susceptamque pecuniam, quæ collata est a filiis Israël, trades in usus tabernaculi testimonii, ut sit monimentum eorum coram Domino, et propitietur animabus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Facies et labrum æneum cum basi sua ad lavandum: ponesque illud inter tabernaculum testimonii et altare. Et missa aqua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'lavabunt in ea Aaron et filii ejus manus suas ac pedes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'quando ingressuri sunt tabernaculum testimonii, et quando accessuri sunt ad altare, ut offerant in eo thymiama Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'ne forte moriantur; legitimum sempiternum erit ipsi, et semini ejus per successiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Locutusque est Dominus ad Moysen,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'dicens: Sume tibi aromata, primæ myrrhæ et electæ quingentos siclos, et cinnamomi medium, id est, ducentos quinquaginta siclos, calami similiter ducentos quinquaginta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'casiæ autem quingentos siclos, in pondere sanctuarii, olei de olivetis mensuram hin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'faciesque unctionis oleum sanctum, unguentum compositum opere unguentarii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'et unges ex eo tabernaculum testimonii, et arcam testamenti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'mensamque cum vasis suis, et candelabrum, et utensilia ejus, altaria thymiamatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'et holocausti, et universam supellectilem quæ ad cultum eorum pertinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Sanctificabisque omnia, et erunt Sancta sanctorum; qui tetigerit ea, sanctificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aaron et filios ejus unges, sanctificabisque eos, ut sacerdotio fungantur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Filiis quoque Israël dices: Hoc oleum unctionis sanctum erit mihi in generationes vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Caro hominis non ungetur ex eo, et juxta compositionem ejus non facietis aliud, quia sanctificatum est, et sanctum erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Homo quicumque tale composuerit, et dederit ex eo alieno, exterminabitur de populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Dixitque Dominus ad Moysen: Sume tibi aromata, stacten et onycha, galbanum boni odoris, et thus lucidissimum; æqualis ponderis erunt omnia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'faciesque thymiama compositum opere unguentarii, mistum diligenter, et purum, et sanctificatione dignissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Cumque in tenuissimum pulverem universa contuderis, pones ex eo coram tabernaculo testimonii, in quo loco apparebo tibi. Sanctum sanctorum erit vobis thymiama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Talem compositionem non facietis in usus vestros, quia sanctum est Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Homo quicumque fecerit simile, ut odore illius perfruatur, peribit de populis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Ecce, vocavi ex nomine Beseleel filium Uri filii Hur de tribu Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'et implevi spiritu Dei, sapientia, et intelligentia et scientia in omni opere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'ad excogitandum quidquid fabrefieri potest ex auro, et argento, et ære,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'marmore, et gemmis, et diversitate lignorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Dedique ei socium Ooliab filium Achisamech de tribu Dan. Et in corde omnis eruditi posui sapientiam: ut faciant cuncta quæ præcepi tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'tabernaculum fœderis, et arcam testimonii, et propitiatorium, quod super eam est, et cuncta vasa tabernaculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'mensamque et vasa ejus, candelabrum purissimum cum vasis suis, et altaris thymiamatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'et holocausti, et omnia vasa eorum, labrum cum basi sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'vestes sanctas in ministerio Aaron sacerdoti, et filiis ejus, ut fungantur officio suo in sacris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'oleum unctionis, et thymiama aromatum in sanctuario, omnia quæ præcepi tibi, facient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Loquere filiis Israël, et dices ad eos: Videte ut sabbatum meum custodiatis: quia signum est inter me et vos in generationibus vestris: ut sciatis quia ego Dominus, qui sanctifico vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Custodite sabbatum meum, sanctum est enim vobis: qui polluerit illud, morte morietur; qui fecerit in eo opus, peribit anima illius de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sex diebus facietis opus: in die septimo sabbatum est, requies sancta Domino; omnis qui fecerit opus in hac die, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Custodiant filii Israël sabbatum, et celebrent illud in generationibus suis. Pactum est sempiternum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'inter me et filios Israël, signumque perpetuum; sex enim diebus fecit Dominus cælum et terram, et in septimo ab opere cessavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Deditque Dominus Moysi, completis hujuscemodi sermonibus in monte Sinai, duas tabulas testimonii lapideas, scriptas digito Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Videns autem populus quod moram faceret descendendi de monte Moyses, congregatus adversus Aaron, dixit: Surge, fac nobis deos, qui nos præcedant: Moysi enim huic viro, qui nos eduxit de terra \'gypti, ignoramus quid acciderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Dixitque ad eos Aaron: Tollite inaures aureas de uxorum, filiorumque et filiarum vestrarum auribus, et afferte ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Fecitque populus quæ jusserat, deferens inaures ad Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Quas cum ille accepisset, formavit opere fusorio, et fecit ex eis vitulum conflatilem: dixeruntque: Hi sunt dii tui Israël, qui te eduxerunt de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Quod cum vidisset Aaron, ædificavit altare coram eo, et præconis voce clamavit dicens: Cras solemnitas Domini est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Surgentesque mane, obtulerunt holocausta, et hostias pacificas, et sedit populus manducare, et bibere, et surrexerunt ludere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Locutus est autem Dominus ad Moysen, dicens: Vade, descende: peccavit populus tuus, quem eduxisti de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Recesserunt cito de via, quam ostendisti eis: feceruntque sibi vitulum conflatilem, et adoraverunt, atque immolantes ei hostias, dixerunt: Isti sunt dii tui Israël, qui te eduxerunt de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Rursumque ait Dominus ad Moysen: Cerno quod populus iste duræ cervicis sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'dimitte me, ut irascatur furor meus contra eos, et deleam eos, faciamque te in gentem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Moyses autem orabat Dominum Deum suum, dicens: Cur, Domine, irascitur furor tuus contra populum tuum, quem eduxisti de terra \'gypti, in fortitudine magna, et in manu robusta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Ne quæso dicant \'gyptii: Callide eduxit eos, ut interficeret in montibus, et deleret e terra: quiescat ira tua, et esto placabilis super nequitia populi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Recordare Abraham, Isaac, et Israël servorum tuorum, quibus jurasti per temetipsum, dicens: Multiplicabo semen vestrum sicut stellas cæli; et universam terram hanc, de qua locutus sum, dabo semini vestro, et possidebitis eam semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Placatusque est Dominus ne faceret malum quod locutus fuerat adversus populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Et reversus est Moyses de monte, portans duas tabulas testimonii in manu sua, scriptas ex utraque parte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'et factas opere Dei: scriptura quoque Dei erat sculpta in tabulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Audiens autem Josue tumultum populi vociferantis, dixit ad Moysen: Ululatus pugnæ auditur in castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Qui respondit: Non est clamor adhortantium ad pugnam, neque vociferatio compellentium ad fugam: sed vocem cantantium ego audio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Cumque appropinquasset ad castra, vidit vitulum, et choros: iratusque valde, projecit de manu tabulas, et confregit eas ad radicem montis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'arripiensque vitulum quem fecerant, combussit, et contrivit usque ad pulverem, quem sparsit in aquam, et dedit ex eo potum filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Dixitque ad Aaron: Quid tibi fecit hic populus, ut induceres super eum peccatum maximum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Cui ille respondit: Ne indignetur dominus meus: tu enim nosti populum istum, quod pronus sit ad malum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'dixerunt mihi: Fac nobis deos, qui nos præcedant: huic enim Moysi, qui nos eduxit de terra \'gypti, nescimus quid acciderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Quibus ego dixi: Quis vestrum habet aurum? Tulerunt, et dederunt mihi: et projeci illud in ignem, egressusque est hic vitulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Videns ergo Moyses populum quod esset nudatus (spoliaverat enim eum Aaron propter ignominiam sordis, et inter hostes nudum constituerat),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'et stans in porta castrorum, ait: Si quis est Domini, jungatur mihi. Congregatique sunt ad eum omnes filii Levi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'quibus ait: Hæc dicit Dominus Deus Israël: Ponat vir gladium super femur suum: ite, et redite de porta usque ad portam per medium castrorum, et occidat unusquisque fratrem, et amicum, et proximum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Feceruntque filii Levi juxta sermonem Moysi, cecideruntque in die illa quasi viginti tria millia hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Et ait Moyses: Consecrastis manus vestras hodie Domino, unusquisque in filio, et in fratre suo, ut detur vobis benedictio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Facto autem altero die, locutus est Moyses ad populum: Peccastis peccatum maximum: ascendam ad Dominum, si quomodo quivero eum deprecari pro scelere vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Reversusque ad Dominum, ait: Obsecro, peccavit populus iste peccatum maximum, feceruntque sibi deos aureos: aut dimitte eis hanc noxam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'aut si non facis, dele me de libro tuo quem scripsisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Cui respondit Dominus: Qui peccaverit mihi, delebo eum de libro meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'tu autem vade, et duc populum istum quo locutus sum tibi: angelus meus præcedet te. Ego autem in die ultionis visitabo et hoc peccatum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Percussit ergo Dominus populum pro reatu vituli, quem fecerat Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Locutusque est Dominus ad Moysen, dicens: Vade, ascende de loco isto tu, et populus tuus quem eduxisti de terra \'gypti, in terram quam juravi Abraham, Isaac et Jacob, dicens: Semini tuo dabo eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'et mittam præcursorem tui angelum, ut ejiciam Chananæum, et Amorrhæum, et Hethæum, et Pherezæum, et Hevæum, et Jebusæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'et intres in terram fluentem lacte et melle. Non enim ascendam tecum, quia populus duræ cervicis es: ne forte disperdam te in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Audiensque populus sermonem hunc pessimum, luxit: et nullus ex more indutus est cultu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Dixitque Dominus ad Moysen: Loquere filiis Israël: Populus duræ cervicis es: semel ascendam in medio tui, et delebo te. Jam nunc depone ornatum tuum, ut sciam quid faciam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Deposuerunt ergo filii Israël ornatum suum a monte Horeb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moyses quoque tollens tabernaculum, tetendit extra castra procul, vocavitque nomen ejus, Tabernaculum fœderis. Et omnis populus, qui habebat aliquam quæstionem, egrediebatur ad tabernaculum fœderis, extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Cumque egrederetur Moyses ad tabernaculum, surgebat universa plebs, et stabat unusquisque in ostio papilionis sui, aspiciebantque tergum Moysi, donec ingrederetur tentorium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Ingresso autem illo tabernaculum fœderis, descendebat columna nubis, et stabat ad ostium, loquebaturque cum Moyse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'cernentibus universis quod columna nubis staret ad ostium tabernaculi. Stabantque ipsi, et adorabant per fores tabernaculorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Loquebatur autem Dominus ad Moysen facie ad faciem, sicut solet loqui homo ad amicum suum. Cumque ille reverteretur in castra, minister ejus Josue filius Nun, puer, non recedebat de tabernaculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Dixit autem Moyses ad Dominum: Præcipis ut educam populum istum: et non indicas mihi quem missurus es mecum, præsertim cum dixeris: Novi te ex nomine, et invenisti gratiam coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Si ergo inveni gratiam in conspectu tuo, ostende mihi faciem tuam, ut sciam te, et inveniam gratiam ante oculos tuos: respice populum tuum gentem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Dixitque Dominus: Facies mea præcedet te, et requiem dabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Et ait Moyses: Si non tu ipse præcedas, ne educas nos de loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'In quo enim scire poterimus ego et populus tuus invenisse nos gratiam in conspectu tuo, nisi ambulaveris nobiscum, ut glorificemur ab omnibus populis qui habitant super terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Dixit autem Dominus ad Moysen: Et verbum istud, quod locutus es, faciam: invenisti enim gratiam coram me, et teipsum novi ex nomine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Qui ait: Ostende mihi gloriam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Respondit: Ego ostendam omne bonum tibi, et vocabo in nomine Domini coram te: et miserebor cui voluero, et clemens ero in quem mihi placuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Rursumque ait: Non poteris videre faciem meam: non enim videbit me homo et vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Et iterum: Ecce, inquit, est locus apud me, et stabis supra petram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Cumque transibit gloria mea, ponam te in foramine petræ, et protegam dextera mea, donec transeam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'tollamque manum meam, et videbis posteriora mea: faciem autem meam videre non poteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Ac deinceps: Præcide, ait, tibi duas tabulas lapideas instar priorum, et scribam super eas verba, quæ habuerunt tabulæ quas fregisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Esto paratus mane, ut ascendas statim in montem Sinai, stabisque mecum super verticem montis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Nullus ascendat tecum, nec videatur quispiam per totum montem: boves quoque et oves non pascantur e contra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Excidit ergo duas tabulas lapideas, quales antea fuerant: et de nocte consurgens ascendit in montem Sinai, sicut præceperat ei Dominus, portans secum tabulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Cumque descendisset Dominus per nubem, stetit Moyses cum eo, invocans nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Quo transeunte coram eo, ait: Dominator Domine Deus, misericors et clemens, patiens et multæ miserationis, ac verax,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'qui custodis misericordiam in millia; qui aufers iniquitatem, et scelera, atque peccata, nullusque apud te per se innocens est; qui reddis iniquitatem patrum filiis, ac nepotibus in tertiam et quartam progeniem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Festinusque Moyses, curvatus est pronus in terram, et adorans');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'ait: Si inveni gratiam in conspectu tuo, Domine, obsecro ut gradiaris nobiscum (populus enim duræ cervicis est) et auferas iniquitates nostras atque peccata, nosque possideas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Respondit Dominus: Ego inibo pactum videntibus cunctis: signa faciam quæ numquam visa sunt super terram, nec in ullis gentibus, ut cernat populus iste, in cujus es medio, opus Domini terribile quod facturus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Observa cuncta quæ hodie mando tibi: ego ipse ejiciam ante faciem tuam Amorrhæum, et Chananæum, et Hethæum, Pherezæum quoque, et Hevæum, et Jebusæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Cave ne umquam cum habitatoribus terræ illius jungas amicitias, quæ sint tibi in ruinam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'sed aras eorum destrue, confringe statuas, lucosque succide:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'noli adorare deum alienum. Dominus zelotes nomen ejus; Deus est æmulator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ne ineas pactum cum hominibus illarum regionum: ne, cum fornicati fuerint cum diis suis, et adoraverint simulacra eorum, vocet te quispiam ut comedas de immolatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Nec uxorem de filiabus eorum accipies filiis tuis: ne, postquam ipsæ fuerint fornicatæ, fornicari faciant et filios tuos in deos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Deos conflatiles non facies tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Solemnitatem azymorum custodies. Septem diebus vesceris azymis, sicut præcepi tibi, in tempore mensis novorum: mense enim verni temporis egressus es de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Omne quod aperit vulvam generis masculini, meum erit. De cunctis animantibus, tam de bobus, quam de ovibus, meum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Primogenitum asini redimes ove: sin autem nec pretium pro eo dederis, occidetur. Primogenitum filiorum tuorum redimes: nec apparebis in conspectu meo vacuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sex diebus operaberis; die septimo cessabis arare et metere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Solemnitatem hebdomadarum facies tibi in primitiis frugum messis tuæ triticeæ, et solemnitatem, quando redeunte anni tempore cuncta conduntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tribus temporibus anni apparebit omne masculinum tuum in conspectu omnipotentis Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Cum enim tulero gentes a facie tua, et dilatavero terminos tuos, nullus insidiabitur terræ tuæ, ascendente te, et apparente in conspectu Domini Dei tui ter in anno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Non immolabis super fermento sanguinem hostiæ meæ: neque residebit mane de victima solemnitatis Phase.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Primitias frugum terræ tuæ offeres in domo Domini Dei tui. Non coques hædum in lacte matris suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Dixitque Dominus ad Moysen: Scribe tibi verba hæc, quibus et tecum et cum Israël pepigi fœdus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Fuit ergo ibi cum Domino quadraginta dies et quadraginta noctes: panem non comedit, et aquam non bibit, et scripsit in tabulis verba fœderis decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Cumque descenderet Moyses de monte Sinai, tenebat duas tabulas testimonii, et ignorabat quod cornuta esset facies sua ex consortio sermonis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Videntes autem Aaron et filii Israël cornutam Moysi faciem, timuerunt prope accedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Vocatique ab eo, reversi sunt tam Aaron, quam principes synagogæ. Et postquam locutus est ad eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'venerunt ad eum etiam omnes filii Israël: quibus præcepit cuncta quæ audierat a Domino in monte Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Impletisque sermonibus, posuit velamen super faciem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Quod ingressus ad Dominum, et loquens cum eo, auferebat donec exiret, et tunc loquebatur ad filios Israël omnia quæ sibi fuerant imperata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Qui videbant faciem egredientis Moysi esse cornutam, sed operiebat ille rursus faciem suam, siquando loquebatur ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Igitur congregata omni turba filiorum Israël, dixit ad eos: Hæc sunt quæ jussit Dominus fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sex diebus facietis opus: septimus dies erit vobis sanctus, sabbatum, et requies Domini: qui fecerit opus in eo, occidetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Non succendetis ignem in omnibus habitaculis vestris per diem sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Et ait Moyses ad omnem catervam filiorum Israël: Iste est sermo quem præcepit Dominus, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Separate apud vos primitias Domino. Omnis voluntarius et prono animo offerat eas Domino: aurum et argentum, et æs,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'hyacinthum et purpuram, coccumque bis tinctum, et byssum, pilos caprarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'pellesque arietum rubricatas, et janthinas, ligna setim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'et oleum ad luminaria concinnanda, et ut conficiatur unguentum, et thymiama suavissimum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'lapides onychinos, et gemmas ad ornatum superhumeralis et rationalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Quisque vestrum sapiens est, veniat, et faciat quod Dominus imperavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'tabernaculum scilicet, et tectum ejus, atque operimentum, annulos, et tabulata cum vectibus, paxillos, et bases:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'arcam et vectes, propitiatorium, et velum, quod ante illud oppanditur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'mensam cum vectibus et vasis, et propositionis panibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'candelabrum ad luminaria sustentanda, vasa illius et lucernas, et oleum ad nutrimenta ignium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'altare thymiamatis, et vectes, et oleum unctionis et thymiama ex aromatibus: tentorium ad ostium tabernaculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'altare holocausti, et craticulam ejus æneam cum vectibus et vasis suis: labrum et basim ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'cortinas atrii cum columnis et basibus, tentorium in foribus vestibuli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'paxillos tabernaculi et atrii cum funiculis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'vestimenta, quorum usus est in ministerio sanctuarii, vestes Aaron pontificis ac filiorum ejus, ut sacerdotio fungantur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Egressaque omnis multitudo filiorum Israël de conspectu Moysi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'obtulerunt mente promptissima atque devota primitias Domino, ad faciendum opus tabernaculi testimonii. Quidquid ad cultum et ad vestes sanctas necessarium erat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'viri cum mulieribus præbuerunt, armillas et inaures, annulos et dextralia: omne vas aureum in donaria Domini separatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Si quis habebat hyacinthum, et purpuram, coccumque bis tinctum, byssum et pilos caprarum, pelles arietum rubricatas, et janthinas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'argenti, ærisque metalla, obtulerunt Domino, lignaque setim in varios usus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Sed et mulieres doctæ, quæ neverant, dederunt hyacinthum, purpuram, et vermiculum, ac byssum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'et pilos caprarum, sponte propria cuncta tribuentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Principes vero obtulerunt lapides onychinos, et gemmas ad superhumerale et rationale,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'aromataque et oleum ad luminaria concinnanda, et ad præparandum unguentum, ac thymiama odoris suavissimi componendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Omnes viri et mulieres mente devota obtulerunt donaria, ut fierent opera, quæ jusserat Dominus per manum Moysi. Cuncti filii Israël voluntaria Domino dedicaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Dixitque Moyses ad filios Israël: Ecce, vocavit Dominus ex nomine Beseleel filium Uri, filii Hur de tribu Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'implevitque eum spiritu Dei, sapientia et intelligentia, et scientia et omni doctrina,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'ad excogitandum, et faciendum opus in auro, et argento, et ære,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'sculpendisque lapidibus, et opere carpentario, quidquid fabre adinveniri potest,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'dedit in corde ejus: Ooliab quoque filium Achisamech de tribu Dan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'ambos erudivit sapientia, ut faciant opera abietarii, polymitarii, ac plumarii, de hyacintho ac purpura, coccoque bis tincto, et bysso, et texant omnia, ac nova quæque reperiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Fecit ergo Beseleel, et Ooliab, et omnis vir sapiens, quibus dedit Dominus sapientiam et intellectum, ut scirent fabre operari quæ in usus sanctuarii necessaria sunt, et quæ præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Cumque vocasset eos Moyses et omnem eruditum virum, cui dederat Dominus sapientiam, et qui sponte sua obtulerant se ad faciendum opus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'tradidit eis universa donaria filiorum Israël. Qui cum instarent operi, quotidie mane vota populus offerebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Unde artifices venire compulsi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'dixerunt Moysi: Plus offert populus quam necessarium est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Jussit ergo Moyses præconis voce cantari: Nec vir, nec mulier quidquam offerat ultra in opere sanctuarii. Sicque cessatum est a muneribus offerendis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'eo quod oblata sufficerent et superabundarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Feceruntque omnes corde sapientes ad explendum opus tabernaculi, cortinas decem de bysso retorta, et hyacintho, et purpura, coccoque bis tincto, opere vario, et arte polymita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'quarum una habebat in longitudine viginti octo cubitos, et in latitudine quatuor; una mensura erat omnium cortinarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Conjunxitque cortinas quinque, alteram alteri, et alias quinque sibi invicem copulavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Fecit et ansas hyacinthinas in ora cortinæ unius ex utroque latere, et in ora cortinæ alterius similiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'ut contra se invicem venirent ansæ, et mutuo jungerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Unde et quinquaginta fudit circulos aureos, qui morderent cortinarum ansas, et fieret unum tabernaculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Fecit et saga undecim de pilis caprarum ad operiendum tectum tabernaculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'unum sagum in longitudine habebat cubitos triginta, et in latitudine cubitos quatuor: unius mensuræ erant omnia saga:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'quorum quinque junxit seorsum, et sex alia separatim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Fecitque ansas quinquaginta in ora sagi unius, et quinquaginta in ora sagi alterius, ut sibi invicem jungerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Et fibulas æneas quinquaginta, quibus necteretur tectum, ut unum pallium ex omnibus sagis fieret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Fecit et opertorium tabernaculi de pellibus arietum rubricatis: aliudque desuper velamentum de pellibus janthinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Fecit et tabulas tabernaculi de lignis setim stantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Decem cubitorum erat longitudo tabulæ unius: et unum ac semis cubitum latitudo retinebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Binæ incastraturæ erant per singulas tabulas, ut altera alteri jungeretur. Sic fecit in omnibus tabernaculi tabulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'E quibus viginti ad plagam meridianam erant contra austrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'cum quadraginta basibus argenteis. Duæ bases sub una tabula ponebantur ex utraque parte angulorum, ubi incastraturæ laterum in angulis terminantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Ad plagam quoque tabernaculi, quæ respicit ad aquilonem, fecit viginti tabulas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'cum quadraginta basibus argenteis, duas bases per singulas tabulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Contra occidentem vero, id est, ad eam partem tabernaculi quæ mare respicit, fecit sex tabulas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'et duas alias per singulos angulos tabernaculi retro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'quæ junctæ erant a deorsum usque sursum, et in unam compaginem pariter ferebantur. Ita fecit ex utraque parte per angulos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'ut octo essent simul tabulæ, et haberent bases argenteas sedecim, binas scilicet bases sub singulis tabulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Fecit et vectes de lignis setim, quinque ad continendas tabulas unius lateris tabernaculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'et quinque alios ad alterius lateris coaptandas tabulas: et extra hos, quinque alios vectes ad occidentalem plagam tabernaculi contra mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Fecit quoque vectem alium, qui per medias tabulas ab angulo usque ad angulum perveniret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Ipsa autem tabulata deauravit, fusis basibus earum argenteis. Et circulos eorum fecit aureos, per quos vectes induci possent: quos et ipsos laminis aureis operuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Fecit et velum de hyacintho, et purpura, vermiculo, ac bysso retorta, opere polymitario, varium atque distinctum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'et quatuor columnas de lignis setim, quas cum capitibus deauravit, fusis basibus earum argenteis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Fecit et tentorium in introitu tabernaculi ex hyacintho, purpura, vermiculo, byssoque retorta, opere plumarii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'et columnas quinque cum capitibus suis, quas operuit auro, basesque earum fudit æneas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Fecit autem Beseleel et arcam de lignis setim, habentem duos semis cubitos in longitudine, et cubitum ac semissem in latitudine, altitudo quoque unius cubiti fuit et dimidii: vestivitque eam auro purissimo intus ac foris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Et fecit illi coronam auream per gyrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'conflans quatuor annulos aureos per quatuor angulos ejus: duos annulos in latere uno, et duos in altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Vectes quoque fecit de lignis setim, quos vestivit auro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'et quos misit in annulos, qui erant in lateribus arcæ ad portandum eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Fecit et propitiatorium, id est, oraculum, de auro mundissimo, duorum cubitorum et dimidii in longitudine, et cubiti ac semis in latitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Duos etiam cherubim ex auro ductili, quos posuit ex utraque parte propitiatorii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'cherub unum in summitate unius partis, et cherub alterum in summitate partis alterius: duos cherubim in singulis summitatibus propitiatorii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'extendentes alas, et tegentes propitiatorium, seque mutuo et illud respicientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Fecit et mensam de lignis setim in longitudine duorum cubitorum, et in latitudine unius cubiti, quæ habebat in altitudine cubitum ac semissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Circumdeditque eam auro mundissimo, et fecit illi labium aureum per gyrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'ipsique labio coronam auream interrasilem quatuor digitorum, et super eamdem, alteram coronam auream.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Fudit et quatuor circulos aureos, quos posuit in quatuor angulis per singulos pedes mensæ');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'contra coronam: misitque in eos vectes, ut possit mensa portari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Ipsos quoque vectes fecit de lignis setim, et circumdedit eos auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Et vasa ad diversos usus mensæ, acetabula, phialas, et cyathos, et thuribula, ex auro puro, in quibus offerenda sunt libamina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Fecit et candelabrum ductile de auro mundissimo, de cujus vecte calami, scyphi, sphærulæque, ac lilia procedebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'sex in utroque latere, tres calami ex parte una, et tres ex altera:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'tres scyphi in nucis modum per calamos singulos, sphærulæque simul et lilia: et tres scyphi instar nucis in calamo altero, sphærulæque simul et lilia. \'quum erat opus sex calamorum, qui procedebant de stipite candelabri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'In ipso autem vecte erant quatuor scyphi in nucis modum, sphærulæque per singulos simul et lilia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'et sphærulæ sub duobus calamis per loca tria, qui simul sex fiunt calami procedentes de vecte uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Et sphærulæ igitur, et calami ex ipso erant, universa ductilia ex auro purissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Fecit et lucernas septem cum emunctoriis suis, et vasa ubi ea, quæ emuncta sunt, extinguantur, de auro mundissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Talentum auri appendebat candelabrum cum omnibus vasis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Fecit et altare thymiamatis de lignis setim, per quadrum singulos habens cubitos, et in altitudine duos: e cujus angulis procedebant cornua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Vestivitque illud auro purissimo cum craticula ac parietibus et cornibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Fecitque ei coronam aureolam per gyrum, et duos annulos aureos sub corona per singula latera, ut mittantur in eos vectes, et possit altare portari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Ipsos autem vectes fecit de lignis setim, et operuit laminis aureis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Composuit et oleum ad sanctificationis unguentum, et thymiama de aromatibus mundissimis opere pigmentarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Fecit et altare holocausti de lignis setim, quinque cubitorum per quadrum, et trium in altitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'cujus cornua de angulis procedebant, operuitque illum laminis æneis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Et in usus ejus paravit ex ære vasa diversa, lebetes, forcipes, fuscinulas, uncinos, et ignium receptacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Craticulamque ejus in modum retis fecit æneam, et subter eam in altaris medio arulam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'fusis quatuor annulis per totidem retiaculi summitates, ad immittendos vectes ad portandum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'quos et ipsos fecit de lignis setim, et operuit laminis æneis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'induxitque in circulos, qui in lateribus altaris eminebant. Ipsum autem altare non erat solidum, sed cavum ex tabulis, et intus vacuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Fecit et labrum æneum cum basi sua de speculis mulierum, quæ excubabant in ostio tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Fecit et atrium, in cujus australi plaga erant tentoria de bysso retorta, cubitorum centum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'columnæ æneæ viginti cum basibus suis, capita columnarum, et tota operis cælatura, argentea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, '\'que ad septentrionalem plagam tentoria columnæ, basesque et capita columnarum ejusdem mensuræ, et operis ac metalli, erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'In ea vero plaga, quæ ad occidentem respicit, fuerunt tentoria cubitorum quinquaginta, columnæ decem cum basibus suis æneæ, et capita columnarum, et tota operis cælatura, argentea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Porro contra orientem quinquaginta cubitorum paravit tentoria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'e quibus, quindecim cubitos columnarum trium, cum basibus suis, unum tenebat latus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'et in parte altera (quia inter utraque introitum tabernaculi fecit) quindecim æque cubitorum erant tentoria, columnæque tres, et bases totidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Cuncta atrii tentoria byssus retorta texuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Bases columnarum fuere æneæ, capita autem earum cum cunctis cælaturis suis argentea: sed et ipsas columnas atrii vestivit argento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Et in introitu ejus opere plumario fecit tentorium ex hyacintho, purpura, vermiculo, ac bysso retorta, quod habebat viginti cubitos in longitudine, altitudo vero quinque cubitorum erat juxta mensuram, quam cuncta atrii tentoria habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Columnæ autem in ingressu fuere quatuor cum basibus æneis, capitaque earum et cælaturæ argenteæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Paxillos quoque tabernaculi et atrii per gyrum fecit æneos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Hæc sunt instrumenta tabernaculi testimonii, quæ enumerata sunt juxta præceptum Moysi in cæremoniis Levitarum per manum Ithamar filii Aaron sacerdotis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'quæ Beseleel filius Uri filii Hur de tribu Juda, Domino per Moysen jubente, compleverat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'juncto sibi socio Ooliab filio Achisamech de tribu Dan: qui et ipse artifex lignorum egregius fuit, et polymitarius atque plumarius ex hyacintho, purpura, vermiculo et bysso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Omne aurum quod expensum est in opere sanctuarii, et quod oblatum est in donariis, viginti novem talentorum fuit, et septingentorum triginta siclorum ad mensuram sanctuarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Oblatum est autem ab his qui transierunt ad numerum a viginti annis et supra, de sexcentis tribus millibus et quingentis quinquaginta armatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Fuerunt præterea centum talenta argenti e quibus conflatæ sunt bases sanctuarii, et introitus, ubi velum pendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Centum bases factæ sunt de talentis centum, singulis talentis per bases singulas supputatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'De mille autem septingentis et septuaginta quinque, fecit capita columnarum, quas et ipsas vestivit argento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, '\'ris quoque oblata sunt talenta septuaginta duo millia, et quadringenti supra sicli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'ex quibus fusæ sunt bases in introitu tabernaculi testimonii, et altare æneum cum craticula sua, omniaque vasa quæ ad usum ejus pertinent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'et bases atrii tam in circuitu quam in ingressu ejus, et paxilli tabernaculi atque atrii per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'De hyacintho vero et purpura, vermiculo ac bysso, fecit vestes, quibus indueretur Aaron quando ministrabat in sanctis, sicut præcepit Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Fecit igitur superhumerale de auro, hyacintho, et purpura, coccoque bis tincto, et bysso retorta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'opere polymitario: inciditque bracteas aureas, et extenuavit in fila, ut possent torqueri cum priorum colorum subtegmine,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'duasque oras sibi invicem copulatas in utroque latere summitatum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'et balteum ex eisdem coloribus, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Paravit et duos lapides onychinos, astrictos et inclusos auro, et sculptos arte gemmaria nominibus filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'posuitque eos in lateribus superhumeralis in monimentum filiorum Israël, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Fecit et rationale opere polymito juxta opus superhumeralis, ex auro, hyacintho, purpura, coccoque bis tincto, et bysso retorta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'quadrangulum, duplex, mensuræ palmi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Et posuit in eo gemmarum ordines quatuor. In primo versu erat sardius, topazius, smaragdus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'In secundo, carbunculus, sapphirus, et jaspis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'In tertio, ligurius, achates, et amethystus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'In quarto, chrysolithus, onychinus, et beryllus, circumdati et inclusi auro per ordines suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Ipsique lapides duodecim sculpti erant nominibus duodecim tribuum Israël, singuli per nomina singulorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Fecerunt in rationali et catenulas sibi invicem cohærentes, de auro purissimo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'et duos uncinos, totidemque annulos aureos. Porro annulos posuerunt in utroque latere rationalis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'e quibus penderent duæ catenæ aureæ, quas inseruerunt uncinis, qui in superhumeralis angulis eminebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Hæc et ante et retro ita conveniebant sibi, ut superhumerale et rationale mutuo necterentur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'stricta ad balteum et annulis fortius copulata, quos jungebat vitta hyacinthina, ne laxa fluerent, et a se invicem moverentur, sicut præcepit Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Feceruntque quoque tunicam superhumeralis totam hyacinthinam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'et capitium in superiori parte contra medium, oramque per gyrum capitii textilem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'deorsum autem ad pedes mala punica ex hyacintho, purpura, vermiculo, ac bysso retorta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'et tintinnabula de auro purissimo, quæ posuerunt inter malogranata, in extrema parte tunicæ per gyrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'tintinnabulum autem aureum, et malum punicum, quibus ornatus incedebat pontifex quando ministerio fungebatur, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Fecerunt et tunicas byssinas opere textili Aaron et filiis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'et mitras cum coronulis suis ex bysso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'feminalia quoque linea, byssina:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'cingulum vero de bysso retorta, hyacintho, purpura, ac vermiculo bis tincto, arte plumaria, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Fecerunt et laminam sacræ venerationis de auro purissimo, scripseruntque in ea opere gemmario, Sanctum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'et strinxerunt eam cum mitra vitta hyacinthina, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Perfectum est igitur omne opus tabernaculi et tecti testimonii: feceruntque filii Israël cuncta quæ præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Et obtulerunt tabernaculum et tectum et universam supellectilem, annulos, tabulas, vectes, columnas ac bases,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'opertorium de pellibus arietum rubricatis, et aliud operimentum de janthinis pellibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'velum; arcam, vectes, propitiatorium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'mensam cum vasis suis et propositionis panibus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'candelabrum, lucernas, et utensilia earum cum oleo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'altare aureum, et unguentum, et thymiama ex aromatibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'et tentorium in introitu tabernaculi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'altare æneum, retiaculum, vectes, et vasa ejus omnia; labrum cum basi sua; tentoria atrii, et columnas cum basibus suis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'tentorium in introitu atrii, funiculosque illius et paxillos. Nihil ex vasis defuit, quæ in ministerium tabernaculi, et in tectum fœderis jussa sunt fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Vestes quoque, quibus sacerdotes utuntur in sanctuario, Aaron scilicet et filii ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'obtulerunt filii Israël, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Quæ postquam Moyses cuncta vidit completa, benedixit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Mense primo, prima die mensis, eriges tabernaculum testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'et pones in eo arcam, dimittesque ante illam velum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'et illata mensa, pones super eam quæ rite præcepta sunt. Candelabrum stabit cum lucernis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'et altare aureum, in quo adoletur incensum, coram arca testimonii. Tentorium in introitu tabernaculi pones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'et ante illud altare holocausti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'labrum inter altare et tabernaculum, quod implebis aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Circumdabisque atrium tentoriis, et ingressum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Et assumpto unctionis oleo unges tabernaculum cum vasis suis, ut sanctificentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'altare holocausti et omnia vasa ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'labrum cum basi sua: omnia unctionis oleo consecrabis, ut sint Sancta sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Applicabisque Aaron et filios ejus ad fores tabernaculi testimonii, et lotos aqua');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'indues sanctis vestibus, ut ministrent mihi, et unctio eorum in sacerdotium sempiternum proficiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Fecitque Moyses omnia quæ præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Igitur mense primo anni secundi, prima die mensis, collocatum est tabernaculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Erexitque Moyses illud, et posuit tabulas ac bases et vectes, statuitque columnas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'et expandit tectum super tabernaculum, imposito desuper operimento, sicut Dominus imperaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Posuit et testimonium in arca, subditis infra vectibus, et oraculum desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Cumque intulisset arcam in tabernaculum, appendit ante eam velum ut expleret Domini jussionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Posuit et mensam in tabernaculo testimonii ad plagam septentrionalem extra velum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'ordinatis coram propositionis panibus, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Posuit et candelabrum in tabernaculo testimonii e regione mensæ in parte australi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'locatis per ordinem lucernis, juxta præceptum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Posuit et altare aureum sub tecto testimonii contra velum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'et adolevit super eo incensum aromatum, sicut jusserat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Posuit et tentorium in introitu tabernaculi testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'et altare holocausti in vestibulo testimonii, offerens in eo holocaustum, et sacrificia, ut Dominus imperaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Labrum quoque statuit inter tabernaculum testimonii et altare, implens illud aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Laveruntque Moyses et Aaron ac filii ejus manus suas et pedes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'cum ingrederentur tectum fœderis, et accederent ad altare, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Erexit et atrium per gyrum tabernaculi et altaris, ducto in introitu ejus tentorio. Postquam omnia perfecta sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'operuit nubes tabernaculum testimonii, et gloria Domini implevit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Nec poterat Moyses ingredi tectum fœderis, nube operiente omnia, et majestate Domini coruscante, quia cuncta nubes operuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Siquando nubes tabernaculum deserebat, proficiscebantur filii Israël per turmas suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'si pendebat desuper, manebant in eodem loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Nubes quippe Domini incubabat per diem tabernaculo, et ignis in nocte, videntibus cunctis populis Israël per cunctas mansiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Vocavit autem Moysen, et locutus est ei Dominus de tabernaculo testimonii, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Loquere filiis Israël, et dices ad eos: Homo, qui obtulerit ex vobis hostiam Domino de pecoribus, id est, de bobus et ovibus offerens victimas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'si holocaustum fuerit ejus oblatio, ac de armento: masculum immaculatum offeret ad ostium tabernaculi testimonii, ad placandum sibi Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'ponetque manum super caput hostiæ, et acceptabilis erit, atque in expiationem ejus proficiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Immolabitque vitulum coram Domino, et offerent filii Aaron sacerdotes sanguinem ejus, fundentes per altaris circuitum, quod est ante ostium tabernaculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'detractaque pelle hostiæ, artus in frusta concident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Et subjicient in altari ignem, strue lignorum ante composita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'et membra quæ sunt cæsa, desuper ordinantes, caput videlicet, et cuncta quæ adhærent jecori,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'intestinis et pedibus lotis aqua: adolebitque ea sacerdos super altare in holocaustum et suavem odorem Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Quod si de pecoribus oblatio est, de ovibus sive de capris holocaustum, masculum absque macula offeret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'immolabitque ad latus altaris, quod respicit ad aquilonem, coram Domino: sanguinem vero illius fundent super altare filii Aaron per circuitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'dividentque membra, caput, et omnia quæ adhærent jecori, et ponent super ligna, quibus subjiciendus est ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'intestina vero et pedes lavabunt aqua. Et oblata omnia adolebit sacerdos super altare in holocaustum et odorem suavissimum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Si autem de avibus, holocausti oblatio fuerit Domino, de turturibus, aut pullis columbæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'offeret eam sacerdos ad altare: et retorto ad collum capite, ac rupto vulneris loco, decurrere faciet sanguinem super crepidinem altaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'vesiculam vero gutturis, et plumas projiciet prope altare ad orientalem plagam, in loco in quo cineres effundi solent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'confringetque ascellas ejus, et non secabit, neque ferro dividet eam, et adolebit super altare, lignis igne supposito. Holocaustum est et oblatio suavissimi odoris Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Anima cum obtulerit oblationem sacrificii Domino, simila erit ejus oblatio; fundetque super eam oleum, et ponet thus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'ac deferet ad filios Aaron sacerdotes: quorum unus tollet pugillum plenum similæ et olei, ac totum thus, et ponet memoriale super altare in odorem suavissimum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Quod autem reliquum fuerit de sacrificio, erit Aaron et filiorum ejus, Sanctum sanctorum de oblationibus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Cum autem obtuleris sacrificium coctum in clibano: de simila, panes scilicet absque fermento, conspersos oleo, et lagana azyma oleo lita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Si oblatio tua fuerit de sartagine, similæ conspersæ oleo et absque fermento,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'divides eam minutatim, et fundes super eam oleum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Sin autem de craticula fuerit sacrificium, æque simila oleo conspergetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'quam offerens Domino, trades manibus sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Qui cum obtulerit eam, tollet memoriale de sacrificio, et adolebit super altare in odorem suavitatis Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'quidquid autem reliquum est, erit Aaron, et filiorum ejus, Sanctum sanctorum de oblationibus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Omnis oblatio quæ offeretur Domino, absque fermento fiet, nec quidquam fermenti ac mellis adolebitur in sacrificio Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Primitias tantum eorum offeretis ac munera: super altare vero non imponentur in odorem suavitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Quidquid obtuleris sacrificii, sale condies, nec auferes sal fœderis Dei tui de sacrificio tuo: in omni oblatione tua offeres sal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Si autem obtuleris munus primarum frugum tuarum Domino de spicis adhuc virentibus, torrebis igni, et confringes in morem farris, et sic offeres primitias tuas Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'fundens supra oleum, et thus imponens, quia oblatio Domini est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'de qua adolebit sacerdos in memoriam muneris partem farris fracti, et olei, ac totum thus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Quod si hostia pacificorum fuerit ejus oblatio, et de bobus voluerit offerre, marem sive feminam, immaculata offeret coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Ponetque manum super caput victimæ suæ, quæ immolabitur in introitu tabernaculi testimonii, fundentque filii Aaron sacerdotes sanguinem per altaris circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Et offerent de hostia pacificorum in oblationem Domino, adipem qui operit vitalia, et quidquid pinguedinis est intrinsecus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'duos renes cum adipe quo teguntur ilia, et reticulum jecoris cum renunculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Adolebuntque ea super altare in holocaustum, lignis igne supposito, in oblationem suavissimi odoris Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Si vero de ovibus fuerit ejus oblatio et pacificorum hostia, sive masculum obtulerit, sive feminam, immaculata erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si agnum obtulerit coram Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'ponet manum suam super caput victimæ suæ: quæ immolabitur in vestibulo tabernaculi testimonii: fundentque filii Aaron sanguinem ejus per circuitum altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Et offerent de pacificorum hostia sacrificium Domino: adipem et caudam totam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'cum renibus, et pinguedinem quæ operit ventrem atque universa vitalia, et utrumque renunculum cum adipe qui est juxta ilia, reticulumque jecoris cum renunculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Et adolebit ea sacerdos super altare in pabulum ignis et oblationis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Si capra fuerit ejus oblatio, et obtulerit eam Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'ponet manum suam super caput ejus: immolabitque eam in introitu tabernaculi testimonii, et fundent filii Aaron sanguinem ejus per altaris circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Tollentque ex ea in pastum ignis dominici, adipem qui operit ventrem, et qui tegit universa vitalia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'duos renunculos cum reticulo, quod est super eos juxta ilia, et arvinam jecoris cum renunculis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'adolebitque ea super altare sacerdos in alimoniam ignis, et suavissimi odoris. Omnis adeps, Domini erit');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'jure perpetuo in generationibus, et cunctis habitaculis vestris: nec sanguinem nec adipem omnino comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Loquere filiis Israël: Anima, quæ peccaverit per ignorantiam, et de universis mandatis Domini, quæ præcepit ut non fierent, quippiam fecerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'si sacerdos, qui unctus est, peccaverit, delinquere faciens populum, offeret pro peccato suo vitulum immaculatum Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'et adducet illum ad ostium tabernaculi testimonii coram Domino, ponetque manum super caput ejus, et immolabit eum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Hauriet quoque de sanguine vituli, inferens illum in tabernaculum testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Cumque intinxerit digitum in sanguine, asperget eo septies coram Domino contra velum sanctuarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Ponetque de eodem sanguine super cornua altaris thymiamatis gratissimi Domino, quod est in tabernaculo testimonii: omnem autem reliquum sanguinem fundet in basim altaris holocausti in introitu tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Et adipem vituli auferet pro peccato, tam eum qui vitalia operit quam omnia quæ intrinsecus sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'duos renunculos et reticulum quod est super eos juxta ilia, et adipem jecoris cum renunculis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'sicut aufertur de vitulo hostiæ pacificorum: et adolebit ea super altare holocausti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Pellem vero et omnes carnes, cum capite et pedibus et intestinis et fimo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'et reliquo corpore, efferet extra castra in locum mundum, ubi cineres effundi solent: incendetque ea super lignorum struem, quæ in loco effusorum cinerum cremabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Quod si omnis turba Israël ignoraverit, et per imperitiam fecerit quod contra mandatum Domini est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'et postea intellexerit peccatum suum, offeret pro peccato suo vitulum, adducetque eum ad ostium tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Et ponent seniores populi manus super caput ejus coram Domino. Immolatoque vitulo in conspectu Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'inferet sacerdos, qui unctus est, de sanguine ejus in tabernaculum testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'tincto digito aspergens septies contra velum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Ponetque de eodem sanguine in cornibus altaris, quod est coram Domino in tabernaculo testimonii: reliquum autem sanguinem fundet juxta basim altaris holocaustorum, quod est in ostio tabernaculi testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Omnemque ejus adipem tollet, et adolebit super altare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'sic faciens et de hoc vitulo quomodo fecit et prius: et rogante pro eis sacerdote, propitius erit eis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ipsum autem vitulum efferet extra castra, atque comburet sicut et priorem vitulum: quia est pro peccato multitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Si peccaverit princeps, et fecerit unum e pluribus per ignorantiam, quod Domini lege prohibetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'et postea intellexerit peccatum suum, offeret hostiam Domino, hircum de capris immaculatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Ponetque manum suam super caput ejus: cumque immolaverit eum loco ubi solet mactari holocaustum coram Domino, quia pro peccato est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'tinget sacerdos digitum in sanguine hostiæ pro peccato, tangens cornua altaris holocausti, et reliquum fundens ad basim ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Adipem vero adolebit supra, sicut in victimis pacificorum fieri solet: rogabitque pro eo sacerdos, et pro peccato ejus, et dimittetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Quod si peccaverit anima per ignorantiam, de populo terræ, ut faciat quidquam de his, quæ Domini lege prohibentur, atque delinquat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'et cognoverit peccatum suum, offeret capram immaculatam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Ponetque manum super caput hostiæ quæ pro peccato est, et immolabit eam in loco holocausti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Tolletque sacerdos de sanguine in digito suo: et tangens cornua altaris holocausti, reliquum fundet ad basim ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Omnem autem adipem auferens, sicut auferri solet de victimis pacificorum, adolebit super altare in odorem suavitatis Domino: rogabitque pro eo, et dimittetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Sin autem de pecoribus obtulerit victimam pro peccato, ovem scilicet immaculatam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'ponet manum super caput ejus, et immolabit eam in loco ubi solent cædi holocaustorum hostiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Sumetque sacerdos de sanguine ejus digito suo, et tangens cornua altaris holocausti, reliquum fundet ad basim ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Omnem quoque adipem auferens, sicut auferri solet adeps arietis, qui immolatur pro pacificis, cremabit super altare in incensum Domini: rogabitque pro eo, et pro peccato ejus, et dimittetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Si peccaverit anima, et audierit vocem jurantis, testisque fuerit quod aut ipse vidit, aut conscius est: nisi indicaverit, portabit iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Anima quæ tetigerit aliquid immundum, sive quod occisum a bestia est, aut per se mortuum, aut quodlibet aliud reptile: et oblita fuerit immunditiæ suæ, rea est, et deliquit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'et si tetigerit quidquam de immunditia hominis juxta omnem impuritatem, qua pollui solet, oblitaque cognoverit postea, subjacebit delicto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Anima, quæ juraverit, et protulerit labiis suis, ut vel male quid faceret, vel bene, et idipsum juramento et sermone firmaverit, oblitaque postea intellexerit delictum suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'agat pœnitentiam pro peccato,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'et offerat de gregibus agnam sive capram, orabitque pro ea sacerdos et pro peccato ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Sin autem non potuerit offerre pecus, offerat duos turtures, vel duos pullos columbarum Domino, unum pro peccato, et alterum in holocaustum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'dabitque eos sacerdoti: qui primum offerens pro peccato, retorquebit caput ejus ad pennulas, ita ut collo hæreat, et non penitus abrumpatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Et asperget de sanguine ejus parietem altaris; quidquid autem reliquum fuerit, faciet distillare ad fundamentum ejus, quia pro peccato est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Alterum vero adolebit in holocaustum, ut fieri solet: rogabitque pro eo sacerdos et pro peccato ejus, et dimittetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Quod si non quiverit manus ejus duos offerre turtures, aut duos pullos columbarum, offeret pro peccato suo similæ partem ephi decimam: non mittet in eam oleum, nec thuris aliquid imponet, quia pro peccato est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Tradetque eam sacerdoti: qui plenum ex ea pugillum hauriens, cremabit super altare in monimentum ejus qui obtulerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'rogans pro illo et expians: reliquam vero partem ipse habebit in munere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Anima si prævaricans cæremonias, per errorem, in his quæ Domino sunt sanctificata, peccaverit, offeret pro delicto suo arietem immaculatum de gregibus, qui emi potest duobus siclis, juxta pondus sanctuarii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'ipsumque quod intulit damni restituet, et quintam partem ponet supra, tradens sacerdoti, qui rogabit pro eo offerens arietem, et dimittetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Anima si peccaverit per ignorantiam, feceritque unum ex his quæ Domini lege prohibentur, et peccati rea intellexerit iniquitatem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'offeret arietem immaculatum de gregibus sacerdoti, juxta mensuram æstimationemque peccati: qui orabit pro eo, quia nesciens fecerit: et dimittetur ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'quia per errorem deliquit in Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Anima quæ peccaverit, et contempto Domino, negaverit proximo suo depositum quod fidei ejus creditum fuerat, vel vi aliquid extorserit, aut calumniam fecerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'sive rem perditam invenerit, et inficians insuper pejeraverit, et quodlibet aliud ex pluribus fecerit, in quibus solent peccare homines,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'convicta delicti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'reddet omnia, quæ per fraudem voluit obtinere, integra, et quintam insuper partem domino cui damnum intulerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Pro peccato autem suo offeret arietem immaculatum de grege, et dabit eum sacerdoti, juxta æstimationem mensuramque delicti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'qui rogabit pro eo coram Domino, et dimittetur illi pro singulis quæ faciendo peccavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Præcipe Aaron et filiis ejus: Hæc est lex holocausti: cremabitur in altari tota nocte usque mane: ignis ex eodem altari erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Vestietur tunica sacerdos et feminalibus lineis: tolletque cineres, quos vorans ignis exussit, et ponens juxta altare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'spoliabitur prioribus vestimentis, indutusque aliis, efferret eos extra castra, et in loco mundissimo usque ad favillam consumi faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Ignis autem in altari semper ardebit, quem nutriet sacerdos subjiciens ligna mane per singulos dies, et imposito holocausto, desuper adolebit adipes pacificorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ignis est iste perpetuus, qui numquam deficiet in altari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Hæc est lex sacrificii et libamentorum, quæ offerent filii Aaron coram Domino, et coram altari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Tollet sacerdos pugillum similæ, quæ conspersa est oleo, et totum thus, quod super similam positum est: adolebitque illud in altari in monimentum odoris suavissimi Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'reliquam autem partem similæ comedet Aaron cum filiis suis, absque fermento: et comedet in loco sancto atrii tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ideo autem non fermentabitur, quia pars ejus in Domini offertur incensum. Sanctum sanctorum erit, sicut pro peccato atque delicto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Mares tantum stirpis Aaron comedent illud. Legitimum ac sempiternum erit in generationibus vestris de sacrificiis Domini: omnis qui tetigerit illa, sanctificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Hæc est oblatio Aaron, et filiorum ejus, quam offerre debent Domino in die unctionis suæ. Decimam partem ephi offerent similæ in sacrificio sempiterno, medium ejus mane, et medium ejus vespere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'quæ in sartagine oleo conspersa frigetur. Offeret autem eam calidam in odorem suavissimum Domino');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'sacerdos, qui jure patri successerit, et tota cremabitur in altari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Omne enim sacrificium sacerdotum igne consumetur, nec quisquam comedet ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Locutus est autem Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Loquere Aaron et filiis ejus: Ista est lex hostiæ pro peccato: in loco ubi offertur holocaustum, immolabitur coram Domino. Sanctum sanctorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Sacerdos, qui offert, comedet eam in loco sancto, in atrio tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Quidquid tetigerit carnes ejus, sanctificabitur. Si de sanguine illius vestis fuerit aspersa, lavabitur in loco sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Vas autem fictile, in quo cocta est, confringetur; quod si vas æneum fuerit, defricabitur, et lavabitur aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Omnis masculus de genere sacerdotali vescetur de carnibus ejus, quia Sanctum sanctorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Hostia enim quæ cæditur pro peccato, cujus sanguis infertur in tabernaculum testimonii ad expiandum in sanctuario, non comedetur, sed comburetur igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Hæc quoque lex hostiæ pro delicto, Sancta sanctorum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'idcirco ubi immolabitur holocaustum, mactabitur et victima pro delicto: sanguis ejus per gyrum altaris fundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Offerent ex ea caudam et adipem qui operit vitalia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'duos renunculos, et pinguedinem quæ juxta ilia est, reticulumque jecoris cum renunculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et adolebit ea sacerdos super altare: incensum est Domini pro delicto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Omnis masculus de sacerdotali genere, in loco sancto vescetur his carnibus, quia Sanctum sanctorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Sicut pro peccato offertur hostia, ita et pro delicto: utriusque hostiæ lex una erit: ad sacerdotem, qui eam obtulerit, pertinebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Sacerdos qui offert holocausti victimam, habebit pellem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Et omne sacrificium similæ, quod coquitur in clibano, et quidquid in craticula, vel in sartagine præparatur, ejus erit sacerdotis a quo offertur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'sive oleo conspersa, sive arida fuerint, cunctis filiis Aaron mensura æqua per singulos dividetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Hæc est lex hostiæ pacificorum quæ offertur Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si pro gratiarum actione oblatio fuerit, offerent panes absque fermento conspersos oleo, et lagana azyma uncta oleo, coctamque similam, et collyridas olei admistione conspersas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'panes quoque fermentatos cum hostia gratiarum, quæ immolatur pro pacificis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'ex quibus unus pro primitiis offeretur Domino, et erit sacerdotis qui fundet hostiæ sanguinem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'cujus carnes eadem comedentur die, nec remanebit ex eis quidquam usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Si voto, vel sponte quispiam obtulerit hostiam, eadem similiter edetur die: sed et si quid in crastinum remanserit, vesci licitum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'quidquid autem tertius invenerit dies, ignis absumet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Si quis de carnibus victimæ pacificorum die tertio comederit, irrita fiet oblatio, nec proderit offerenti: quin potius quæcumque anima tali se edulio contaminaverit, prævaricationis rea erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Caro, quæ aliquid tetigerit immundum, non comedetur, sed comburetur igni: qui fuerit mundus, vescetur ex ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Anima polluta quæ ederit de carnibus hostiæ pacificorum, quæ oblata est Domino, peribit de populis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Et quæ tetigerit immunditiam hominis, vel jumenti, sive omnis rei quæ polluere potest, et comederit de hujuscemodi carnibus, interibit de populis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Loquere filiis Israël: Adipem ovis, et bovis, et capræ non comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Adipem cadaveris morticini, et ejus animalis, quod a bestia captum est, habebitis in varios usus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Si quis adipem, qui offerri debet in incensum Domini, comederit, peribit de populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Sanguinem quoque omnis animalis non sumetis in cibo, tam de avibus quam de pecoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Omnis anima, quæ ederit sanguinem, peribit de populis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Loquere filiis Israël, dicens: Qui offert victimam pacificorum Domino, offerat simul et sacrificium, id est, libamenta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Tenebit manibus adipem hostiæ, et pectusculum: cumque ambo oblata Domino consecraverit, tradet sacerdoti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'qui adolebit adipem super altare, pectusculum autem erit Aaron et filiorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Armus quoque dexter de pacificorum hostiis cedet in primitias sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Qui obtulerit sanguinem et adipem filiorum Aaron, ipse habebit et armum dextrum in portione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Pectusculum enim elevationis, et armum separationis, tuli a filiis Israël de hostiis eorum pacificis, et dedi Aaron sacerdoti, et filiis ejus, lege perpetua, ab omni populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Hæc est unctio Aaron et filiorum ejus in cæremoniis Domini die qua obtulit eos Moyses, ut sacerdotio fungerentur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'et quæ præcepit eis dari Dominus a filiis Israël religione perpetua in generationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Ista est lex holocausti, et sacrificii pro peccato atque delicto, et pro consecratione et pacificorum victimis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'quam constituit Dominus Moysi in monte Sinai, quando mandabit filiis Israël ut offerrent oblationes suas Domino in deserto Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Tolle Aaron cum filiis suis, vestes eorum, et unctionis oleum, vitulum pro peccato, duos arietes, canistrum cum azymis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'et congregabis omnem cœtum ad ostium tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Fecit Moyses ut Dominus imperaverat. Congregataque omni turba ante fores tabernaculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'ait: Iste est sermo, quem jussit Dominus fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Statimque obtulit Aaron et filios ejus. Cumque lavisset eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'vestivit pontificem subucula linea, accingens eum balteo, et induens eum tunica hyacinthina, et desuper humerale imposuit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'quod astringens cingulo aptavit rationali, in quo erat Doctrina et Veritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Cidari quoque texit caput: et super eam, contra frontem, posuit laminam auream consecratam in sanctificatione, sicut præceperat ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Tulit et unctionis oleum, quo linivit tabernaculum cum omni supellectili sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Cumque sanctificans aspersisset altare septem vicibus, unxit illud, et omnia vasa ejus, labrumque cum basi sua sanctificavit oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Quod fundens super caput Aaron, unxit eum, et consecravit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'filios quoque ejus oblatos vestivit tunicis lineis, et cinxit balteis, imposuitque mitras, ut jusserat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Obtulit et vitulum pro peccato: cumque super caput ejus posuisset Aaron et filii ejus manus suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'immolavit eum, hauriens sanguinem, et tincto digito, tetigit cornua altaris per gyrum: quo expiato et sanctificato, fudit reliquum sanguinem ad fundamenta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Adipem vero qui erat super vitalia, et reticulum jecoris, duosque renunculos, cum arvinulis suis, adolevit super altare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'vitulum cum pelle, et carnibus, et fimo, cremans extra castra, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Obtulit et arietem in holocaustum: super cujus caput cum imposuissent Aaron et filii ejus manus suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'immolavit eum, et fudit sanguinem ejus per circuitum altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Ipsumque arietem in frusta concidens, caput ejus, et artus, et adipem adolevit igni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'lotis prius intestinis et pedibus: totumque simul arietem incendit super altare, eo quod esset holocaustum suavissimi odoris Domino, sicut præceperat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Obtulit et arietem secundum in consecratione sacerdotum, posueruntque super caput ejus Aaron et filii ejus manus suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'quem cum immolasset Moyses, sumens de sanguine ejus, tetigit extremum auriculæ dextræ Aaron, et pollicem manus ejus dextræ, similiter et pedis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Obtulit et filios Aaron: cumque de sanguine arietis immolati tetigisset extremum auriculæ singulorum dextræ, et pollices manus ac pedis dextri, reliquum fudit super altare per circuitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'adipem vero, et caudam, omnemque pinguedinem quæ operit intestina, reticulumque jecoris, et duos renes cum adipibus suis et armo dextro separavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Tollens autem de canistro azymorum, quod erat coram Domino, panem absque fermento, et collyridam conspersam oleo, laganumque, posuit super adipes, et armum dextrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'tradens simul omnia Aaron et filiis ejus. Qui postquam levaverunt ea coram Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'rursum suscepta de manibus eorum, adolevit super altare holocausti, eo quod consecrationis esset oblatio, in odorem suavitatis, sacrificii Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Tulitque pectusculum, elevans illud coram Domino, de ariete consecrationis in partem suam, sicut præceperat ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Assumensque unguentum, et sanguinem qui erat in altari, aspersit super Aaron et vestimenta ejus, et super filios illius ac vestes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Cumque sanctificasset eos in vestitu suo, præcepit eis, dicens: Coquite carnes ante fores tabernaculi, et ibi comedite eas; panes quoque consecrationis edite, qui positi sunt in canistro, sicut præcepit mihi Dominus, dicens: Aaron et filii ejus comedent eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'quidquid autem reliquum fuerit de carne et panibus, ignis absumet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'De ostio quoque tabernaculi non exibitis septem diebus, usque ad diem quo complebitur tempus consecrationis vestræ; septem enim diebus finitur consecratio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'sicut et impræsentiarum factum est, ut ritus sacrificii compleretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Die ac nocte manebitis in tabernaculo observantes custodias Domini, ne moriamini: sic enim mihi præceptum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Feceruntque Aaron et filii ejus cuncta quæ locutus est Dominus per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Facto autem octavo die, vocavit Moyses Aaron, et filios ejus, ac majores natu Israël, dixitque ad Aaron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Tolle de armento vitulum pro peccato, et arietem in holocaustum, utrumque immaculatum, et offer illos coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et ad filios Israël loqueris: Tollite hircum pro peccato, et vitulum, atque agnum, anniculos, et sine macula in holocaustum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'bovem et arietem pro pacificis: et immolate eos coram Domino, in sacrificio singulorum similam conspersam oleo offerentes: hodie enim Dominus apparebit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Tulerunt ergo cuncta quæ jusserat Moyses ad ostium tabernaculi: ubi cum omnis multitudo astaret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'ait Moyses: Iste est sermo, quem præcepit Dominus: facite, et apparebit vobis gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Et dixit ad Aaron: Accede ad altare, et immola pro peccato tuo: offer holocaustum, et deprecare pro te et pro populo: cumque mactaveris hostiam populi, ora pro eo, sicut præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Statimque Aaron accedens ad altare, immolavit vitulum pro peccato suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'cujus sanguinem obtulerunt ei filii sui: in quo tingens digitum, tetigit cornua altaris, et fudit residuum ad basim ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Adipemque, et renunculos, ac reticulum jecoris, quæ sunt pro peccato, adolevit super altare, sicut præceperat Dominus Moysi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'carnes vero et pellem ejus extra castra combussit igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Immolavit et holocausti victimam: obtuleruntque ei filii sui sanguinem ejus, quem fudit per altaris circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Ipsam etiam hostiam in frusta concisam, cum capite et membris singulis obtulerunt; quæ omnia super altare cremavit igni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'lotis aqua prius intestinis et pedibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Et pro peccato populi offerens, mactavit hircum: expiatoque altari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'fecit holocaustum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'addens in sacrificio libamenta, quæ pariter offeruntur, et adolens ea super altare, absque cæremoniis holocausti matutini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Immolavit et bovem atque arietem, hostias pacificas populi: obtuleruntque ei filii sui sanguinem, quem fudit super altare in circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Adipem autem bovis, et caudam arietis, renunculosque cum adipibus suis, et reticulum jecoris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'posuerunt super pectora: cumque cremati essent adipes super altare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'pectora eorum, et armos dextros separavit Aaron, elevans coram Domino, sicut præceperat Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Et extendens manus ad populum, benedixit ei. Sicque completis hostiis pro peccato, et holocaustis, et pacificis, descendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Ingressi autem Moyses et Aaron in tabernaculum testimonii, et deinceps egressi, benedixerunt populo. Apparuitque gloria Domini omni multitudini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'et ecce egressus ignis a Domino, devoravit holocaustum, et adipes qui erant super altare. Quod cum vidissent turbæ, laudaverunt Dominum, ruentes in facies suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Arreptisque Nadab et Abiu filii Aaron thuribulis, posuerunt ignem, et incensum desuper, offerentes coram Domino ignem alienum: quod eis præceptum non erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Egressusque ignis a Domino, devoravit eos, et mortui sunt coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Dixitque Moyses ad Aaron: Hoc est quod locutus est Dominus: Sanctificabor in iis qui appropinquant mihi, et in conspectu omnis populi glorificabor. Quod audiens tacuit Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Vocatis autem Moyses Misaële et Elisaphan filiis Oziel, patrui Aaron, ait ad eos: Ite, et tollite fratres vestros de conspectu sanctuarii, et asportate extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Confestimque pergentes, tulerunt eos sicut jacebant, vestitos lineis tunicis, et ejecerunt foras, ut sibi fuerat imperatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Locutusque est Moyses ad Aaron, et ad Eleazar, et Ithamar, filios ejus: Capita vestra nolite nudare, et vestimenta nolite scindere, ne forte moriamini, et super omnem cœtum oriatur indignatio. Fratres vestri, et omnis domus Israël, plangant incendium quod Dominus suscitavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'vos autem non egrediemini fores tabernaculi, alioquin peribitis: oleum quippe sanctæ unctionis est super vos. Qui fecerunt omnia juxta præceptum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Dixit quoque Dominus ad Aaron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vinum, et omne quod inebriare potest, non bibetis tu et filii tui, quando intratis in tabernaculum testimonii, ne moriamini: quia præceptum sempiternum est in generationes vestras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'et ut habeatis scientiam discernendi inter sanctum et profanum, inter pollutum et mundum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'doceatisque filios Israël omnia legitima mea quæ locutus est Dominus ad eos per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Locutusque est Moyses ad Aaron, et ad Eleazar, et Ithamar, filios ejus, qui erant residui: Tollite sacrificium, quod remansit de oblatione Domini, et comedite illud absque fermento juxta altare, quia Sanctum sanctorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Comedetis autem in loco sancto: quod datum est tibi et filiis tuis de oblationibus Domini, sicut præceptum est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Pectusculum quoque quod oblatum est, et armum qui separatus est, edetis in loco mundissimo tu et filii tui, et filiæ tuæ tecum: tibi enim ac liberis tuis reposita sunt de hostiis salutaribus filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'eo quod armum et pectus, et adipes qui cremantur in altari, elevaverunt coram Domino, et pertineant ad te, et ad filios tuos, lege perpetua, sicut præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Inter hæc, hircum, qui oblatus fuerat pro peccato, cum quæreret Moyses, exustum reperit: iratusque contra Eleazar et Ithamar filios Aaron, qui remanserant, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Cur non comedistis hostiam pro peccato in loco sancto, quæ Sancta sanctorum est, et data vobis ut portetis iniquitatem multitudinis, et rogetis pro ea in conspectu Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'præsertim cum de sanguine illius non sit illatum intra sancta, et comedere debueritis eam in Sanctuario, sicut præceptum est mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Respondit Aaron: Oblata est hodie victima pro peccato, et holocaustum coram Domino: mihi autem accidit quod vides; quomodo potui comedere eam, aut placere Domino in cæremoniis mente lugubri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Quod cum audisset Moyses, recepit satisfactionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Dicite filiis Israël: Hæc sunt animalia quæ comedere debetis de cunctis animantibus terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'omne quod habet divisam ungulam, et ruminat in pecoribus, comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Quidquid autem ruminat quidem, et habet ungulam, sed non dividit eam, sicut camelus et cetera, non comedetis illud, et inter immunda reputabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Chœrogryllus qui ruminat, ungulamque non dividit, immundus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Lepus quoque: nam et ipse ruminat, sed ungulam non dividit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Et sus: qui cum ungulam dividat, non ruminat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Horum carnibus non vescemini, nec cadavera contingetis, quia immunda sunt vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Hæc sunt quæ gignuntur in aquis, et vesci licitum est: omne quod habet pinnulas et squamas, tam in mari quam in fluminibus et stagnis, comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Quidquid autem pinnulas et squamas non habet, eorum quæ in aquis moventur et vivunt, abominabile vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'execrandumque erit: carnes eorum non comedetis, et morticina vitabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Cuncta quæ non habent pinnulas et squamas in aquis, polluta erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Hæc sunt quæ de avibus comedere non debetis, et vitanda sunt vobis: aquilam, et gryphem, et haliæetum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'et milvum ac vulturem juxta genus suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'et omne corvini generis in similitudinem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'struthionem, et noctuam, et larum, et accipitrem juxta genus suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'bubonem, et mergulum, et ibin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'et cygnum, et onocrotalum, et porphyrionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'herodionem, et charadrion juxta genus suum, upupam quoque, et vespertilionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Omne de volucribus quod graditur super quatuor pedes, abominabile erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Quidquid autem ambulat quidem super quatuor pedes, sed habet longiora retro crura, per quæ salit super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'comedere debetis, ut est bruchus in genere suo, et attacus atque ophiomachus, ac locusta, singula juxta genus suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Quidquid autem ex volucribus quatuor tantum habet pedes, execrabile erit vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'et quicumque morticina eorum tetigerit, polluetur, et erit immundus usque ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'et si necesse fuerit ut portet quippiam horum mortuum, lavabit vestimenta sua, et immundus erit usque ad occasum solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Omne animal quod habet quidem ungulam, sed non dividit eam, nec ruminat, immundum erit: et qui tetigerit illud, contaminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Quod ambulat super manus ex cunctis animantibus, quæ incedunt quadrupedia, immundum erit: qui tetigerit morticina eorum, polluetur usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Et qui portaverit hujuscemodi cadavera, lavabit vestimenta sua, et immundus erit usque ad vesperum: quia omnia hæc immunda sunt vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Hæc quoque inter polluta reputabuntur de his quæ moventur in terra, mustela et mus et crocodilus, singula juxta genus suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'mygale, et chamæleon, et stellio, et lacerta, et talpa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Omnia hæc immunda sunt. Qui tetigerit morticina eorum, immundus erit usque ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'et super quod ceciderit quidquam de morticinis eorum, polluetur, tam vas ligneum et vestimentum, quam pelles et cilicia: et in quocumque fit opus, tingentur aqua, et polluta erunt usque ad vesperum, et sic postea mundabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Vas autem fictile, in quod horum quidquam intro cecidit, polluetur, et idcirco frangendum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Omnis cibus, quem comedetis, si fusa fuerit super eum aqua, immundus erit: et omne liquens quod bibitur de universo vase, immundum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Et quidquid de morticinis hujuscemodi ceciderit super illud, immundum erit: sive clibani, sive chytropodes, destruentur, et immundi erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Fontes vero et cisternæ, et omnis aquarum congregatio munda erit. Qui morticinum eorum tetigerit, polluetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Si ceciderit super sementem, non polluet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Si autem quispiam aqua sementem perfuderit, et postea morticinis tacta fuerit, illico polluetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Si mortuum fuerit animal, quod licet vobis comedere, qui cadaver ejus tetigerit, immundus erit usque ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'et qui comederit ex eo quippiam, sive portaverit, lavabit vestimenta sua, et immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Omne quod reptat super terram, abominabile erit, nec assumetur in cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Quidquid super pectus quadrupes graditur, et multos habet pedes, sive per humum trahitur, non comedetis, quia abominabile est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nolite contaminare animas vestras, nec tangatis quidquam eorum, ne immundi sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Ego enim sum Dominus Deus vester: sancti estote, quia ego sanctus sum. Ne polluatis animas vestras in omni reptili quod movetur super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Ego enim sum Dominus, qui eduxi vos de terra \'gypti, ut essem vobis in Deum. Sancti eritis, quia ego sanctus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ista est lex animantium ac volucrum, et omnis animæ viventis, quæ movetur in aqua, et reptat in terra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'ut differentias noveritis mundi et immundi, et sciatis quid comedere et quid respuere debeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Loquere filiis Israël, et dices ad eos: Mulier, si suscepto semine pepererit masculum, immunda erit septem diebus juxta dies separationis menstruæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Et die octavo circumcidetur infantulus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'ipsa vero triginta tribus diebus manebit in sanguine purificationis suæ. Omne sanctum non tanget, nec ingredietur in sanctuarium, donec impleantur dies purificationis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Sin autem feminam pepererit, immunda erit duabus hebdomadibus juxta ritum fluxus menstrui, et sexaginta sex diebus manebit in sanguine purificationis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Cumque expleti fuerint dies purificationis suæ, pro filio sive pro filia, deferet agnum anniculum in holocaustum, et pullum columbæ sive turturem pro peccato, ad ostium tabernaculi testimonii, et tradet sacerdoti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'qui offeret illa coram Domino, et orabit pro ea, et sic mundabitur a profluvio sanguinis sui: ista est lex parientis masculum aut feminam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Quod si non invenerit manus ejus, nec potuerit offerre agnum, sumet duos turtures vel duos pullos columbarum, unum in holocaustum, et alterum pro peccato: orabitque pro ea sacerdos, et sic mundabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Locutusque est Dominus ad Moysen, et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Homo, in cujus cute et carne ortus fuerit diversus color, sive pustula, aut quasi lucens quippiam, id est, plaga lepræ, adducetur ad Aaron sacerdotem, vel ad unum quemlibet filiorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Qui cum viderit lepram in cute, et pilos in album mutatos colorem, ipsamque speciem lepræ humiliorem cute et carne reliqua: plaga lepræ est, et ad arbitrium ejus separabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Sin autem lucens candor fuerit in cute, nec humilior carne reliqua, et pili coloris pristini, recludet eum sacerdos septem diebus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'et considerabit die septimo: et si quidem lepra ultra non creverit, nec transierit in cute priores terminos, rursum recludet eum septem diebus aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Et die septimo contemplabitur: si obscurior fuerit lepra, et non creverit in cute, mundabit eum, quia scabies est: lavabitque homo vestimenta sua, et mundus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Quod si postquam a sacerdote visus est, et redditus munditiæ, iterum lepra creverit: adducetur ad eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'et immunditiæ condemnabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Plaga lepræ si fuerit in homine, adducetur ad sacerdotem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'et videbit eum. Cumque color albus in cute fuerit, et capillorum mutaverit aspectum, ipsa quoque caro viva apparuerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'lepra vetustissima judicabitur, atque inolita cuti. Contaminabit itaque eum sacerdos, et non recludet, quia perspicuæ immunditiæ est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Sin autem effloruerit discurrens lepra in cute, et operuerit omnem cutem a capite usque ad pedes, quidquid sub aspectum oculorum cadit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'considerabit eum sacerdos, et teneri lepra mundissima judicabit: eo quod omnis in candorem versa sit, et idcirco homo mundus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Quando vero caro vivens in eo apparuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'tunc sacerdotis judicio polluetur, et inter immundos reputabitur: caro enim viva, si lepra aspergitur, immunda est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Quod si rursum versa fuerit in alborem, et totum hominem operuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'considerabit eum sacerdos, et mundum esse decernet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Caro autem et cutis in qua ulcus natum est, et sanatum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'et in loco ulceris cicatrix alba apparuerit, sive subrufa, adducetur homo ad sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Qui cum viderit locum lepræ humiliorem carne reliqua, et pilos versos in candorem, contaminabit eum: plaga enim lepræ orta est in ulcere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Quod si pilus coloris est pristini, et cicatrix subobscura, et vicina carne non est humilior, recludet eum septem diebus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'et si quidem creverit, adjudicabit eum lepræ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'sin autem steterit in loco suo, ulceris est cicatrix, et homo mundus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Caro autem et cutis, quam ignis exusserit, et sanata albam sive rufam habuerit cicatricem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'considerabit eam sacerdos: et ecce versa est in alborem, et locus ejus reliqua cute est humilior, contaminabit eum, quia plaga lepræ in cicatrice orta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Quod si pilorum color non fuerit immutatus, nec humilior plaga carne reliqua, et ipsa lepræ species fuerit subobscura, recludet eum septem diebus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'et die septimo contemplabitur: si creverit in cute lepra, contaminabit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Sin autem in loco suo candor steterit non satis clarus, plaga combustionis est, et idcirco mundabitur, quia cicatrix est combusturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Vir, sive mulier, in cujus capite vel barba germinaverit lepra, videbit eos sacerdos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Et si quidem humilior fuerit locus carne reliqua, et capillus flavus, solitoque subtilior, contaminabit eos, quia lepra capitis ac barbæ est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Sin autem viderit locum maculæ æqualem vicinæ carni, et capillum nigrum: recludet eum septem diebus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'et die septimo intuebitur. Si non creverit macula, et capillus sui coloris est, et locus plagæ carni reliquæ æqualis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'radetur homo absque loco maculæ, et includetur septem diebus aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Si die septimo visa fuerit stetisse plaga in loco suo, nec humilior carne reliqua, mundabit eum: lotisque vestibus suis, mundus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Sin autem post emundationem rursus creverit macula in cute,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'non quæret amplius utrum capillus in flavum colorem sit immutatus, quia aperte immundus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Porro si steterit macula, et capilli nigri fuerint, noverit hominem sanatum esse, et confidenter eum pronuntiet mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Vir, sive mulier, in cujus cute candor apparuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'intuebitur eos sacerdos. Si deprehenderit subobscurum alborem lucere in cute, sciat non esse lepram, sed maculam coloris candidi, et hominem mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Vir, de cujus capite capilli fluunt, calvus et mundus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'et si a fronte ceciderint pili, recalvaster et mundus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Sin autem in calvitio sive in recalvatione albus vel rufus color fuerit exortus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'et hoc sacerdos viderit, condemnabit eum haud dubiæ lepræ, quæ orta est in calvitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Quicumque ergo maculatus fuerit lepra, et separatus est ad arbitrium sacerdotis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'habebit vestimenta dissuta, caput nudum, os veste contectum, contaminatum ac sordidum se clamabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Omni tempore quo leprosus est et immundus, solus habitabit extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Vestis lanea sive linea, quæ lepram habuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'in stamine atque subtegmine, aut certe pellis, vel quidquid ex pelle confectum est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'si alba vel rufa macula fuerit infecta, lepra reputabitur, ostendeturque sacerdoti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'qui consideratam recludet septem diebus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'et die septimo rursus aspiciens, si deprehenderit crevisse, lepra perseverans est: pollutum judicabit vestimentum, et omne in quo fuerit inventa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'et idcirco comburetur flammis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Quod si eam viderit non crevisse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'præcipiet, et lavabunt id in quo lepra est, recludetque illud septem diebus aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Et cum viderit faciem quidem pristinam non reversam, nec tamen crevisse lepram, immundum judicabit, et igne comburet, eo quod infusa sit in superficie vestimenti, vel per totum, lepra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Sin autem obscurior fuerit locus lepræ, postquam vestis est lota, abrumpet eum, et a solido dividet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Quod si ultra apparuerit in his locis, quæ prius immaculata erant, lepra volatilis et vaga, debet igne comburi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Si cessaverit, lavabit aqua ea, quæ pura sunt, secundo, et munda erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Ista est lex lepræ vestimenti lanei et linei, staminis, atque subtegminis, omnisque supellectilis pelliceæ, quomodo mundari debeat, vel contaminari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Hic est ritus leprosi, quando mundandus est. Adducetur ad sacerdotem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'qui egressus de castris, cum invenerit lepram esse mundatam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'præcipiet ei, qui purificatur, ut offerat duos passeres vivos pro se, quibus vesci licitum est, et lignum cedrinum, vermiculumque et hyssopum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Et unum ex passeribus immolari jubebit in vase fictili super aquas viventes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'alium autem vivum cum ligno cedrino, et cocco et hyssopo, tinget in sanguine passeris immolati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'quo asperget illum, qui mundandus est, septies, ut jure purgetur: et dimittet passerem vivum, ut in agrum avolet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Cumque laverit homo vestimenta sua, radet omnes pilos corporis, et lavabitur aqua: purificatusque ingredietur castra, ita dumtaxat ut maneat extra tabernaculum suum septem diebus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'et die septimo radet capillos capitis, barbamque et supercilia, ac totius corporis pilos. Et lotis rursum vestibus et corpore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'die octavo assumet duos agnos immaculatos, et ovem anniculam absque macula, et tres decimas similæ in sacrificium, quæ conspersa sit oleo, et seorsum olei sextarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Cumque sacerdos purificans hominem, statuerit eum, et hæc omnia coram Domino in ostio tabernaculi testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'tollet agnum et offeret eum pro delicto, oleique sextarium: et oblatis ante Dominum omnibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'immolabit agnum, ubi solet immolari hostia pro peccato, et holocaustum, id est, in loco sancto. Sicut enim pro peccato, ita et pro delicto ad sacerdotem pertinet hostia: Sancta sanctorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Assumensque sacerdos de sanguine hostiæ, quæ immolata est pro delicto, ponet super extremum auriculæ dextræ ejus qui mundatur, et super pollices manus dextræ et pedis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'et de olei sextario mittet in manum suam sinistram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'tingetque digitum dextrum in eo, et asperget coram Domino septies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Quod autem reliquum est olei in læva manu, fundet super extremum auriculæ dextræ ejus qui mundatur, et super pollices manus ac pedis dextri, et super sanguinem qui effusus est pro delicto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'et super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Rogabitque pro eo coram Domino, et faciet sacrificium pro peccato: tunc immolabit holocaustum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'et ponet illud in altari cum libamentis suis, et homo rite mundabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Quod si pauper est, et non potest manus ejus invenire quæ dicta sunt pro delicto, assumet agnum ad oblationem, ut roget pro eo sacerdos, decimamque partem similæ conspersæ oleo in sacrificium, et olei sextarium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'duosque turtures sive duos pullos columbæ, quorum unus sit pro peccato, et alter in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'offeretque ea die octavo purificationis suæ sacerdoti, ad ostium tabernaculi testimonii coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Qui suscipiens agnum pro delicto et sextarium olei, levabit simul:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'immolatoque agno, de sanguine ejus ponet super extremum auriculæ dextræ illius qui mundatur, et super pollices manus ejus ac pedis dextri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'olei vero partem mittet in manum suam sinistram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'in quo tingens digitum dextræ manus asperget septies coram Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'tangetque extremum dextræ auriculæ illius qui mundatur, et pollices manus ac pedis dextri, in loco sanguinis qui effusus est pro delicto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'reliquam autem partem olei, quæ est in sinistra manu, mittet super caput purificati, ut placet pro eo Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'et turturem sive pullum columbæ offeret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'unum pro delicto, et alterum in holocaustum cum libamentis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Hoc est sacrificium leprosi, qui habere non potest omnia in emundationem sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Cum ingressi fueritis terram Chanaan, quam ego dabo vobis in possessionem, si fuerit plaga lepræ in ædibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'ibit cujus est domus, nuntians sacerdoti, et dicet: Quasi plaga lepræ videtur mihi esse in domo mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'At ille præcipiet ut efferant universa de domo, priusquam ingrediatur eam, et videat utrum leprosa sit, ne immunda fiant omnia quæ in domo sunt. Intrabitque postea ut consideret lepram domus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'et cum viderit in parietibus illius quasi valliculas pallore sive rubore deformes, et humiliores superficie reliqua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'egredietur ostium domus, et statim claudet illam septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Reversusque die septimo, considerabit eam: si invenerit crevisse lepram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'jubebit erui lapides in quibus lepra est, et projici eos extra civitatem in locum immundum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'domum autem ipsam radi intrinsecus per circuitum, et spargi pulverem rasuræ extra urbem in locum immundum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'lapidesque alios reponi pro his qui ablati fuerint, et luto alio liniri domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Sin autem postquam eruti sunt lapides, et pulvis erasus, et alia terra lita,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'ingressus sacerdos viderit reversam lepram, et parietes respersos maculis, lepra est perseverans, et immunda domus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'quam statim destruent, et lapides ejus ac ligna, atque universum pulverem projicient extra oppidum in locum immundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Qui intraverit domum quando clausa est, immundus erit usque ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'et qui dormierit in ea, et comederit quippiam, lavabit vestimenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Quod si introiens sacerdos viderit lepram non crevisse in domo, postquam denuo lita fuerit, purificabit eam reddita sanitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'et in purificationem ejus sumet duos passeres, lignumque cedrinum, et vermiculum atque hyssopum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'et immolato uno passere in vase fictili super aquas vivas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'tollet lignum cedrinum, et hyssopum, et coccum, et passerem vivum, et tinget omnia in sanguine passeris immolati, atque in aquis viventibus, et asperget domum septies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'purificabitque eam tam in sanguine passeris quam in aquis viventibus, et in passere vivo, lignoque cedrino et hyssopo atque vermiculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Cumque dimiserit passerem avolare in agrum libere, orabit pro domo, et jure mundabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ista est lex omnis lepræ et percussuræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'lepræ vestium et domorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'cicatricis et erumpentium papularum, lucentis maculæ, et in varias species, coloribus immutatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'ut possit sciri quo tempore mundum quid, vel immundum sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Loquimini filiis Israël, et dicite eis: Vir, qui patitur fluxum seminis, immundus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Et tunc judicabitur huic vitio subjacere, cum per singula momenta adhæserit carni ejus, atque concreverit fœdus humor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Omne stratum, in quo dormierit, immundum erit, et ubicumque sederit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Si quis hominum tetigerit lectum ejus, lavabit vestimenta sua, et ipse lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Si sederit ubi ille sederat, et ipse lavabit vestimenta sua: et lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Qui tetigerit carnem ejus, lavabit vestimenta sua: et ipse lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Si salivam hujuscemodi homo jecerit super eum qui mundus est, lavabit vestimenta sua: et lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Sagma, super quo sederit, immundum erit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'et quidquid sub eo fuerit, qui fluxum seminis patitur, pollutum erit usque ad vesperum. Qui portaverit horum aliquid, lavabit vestimenta sua: et ipse lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Omnis, quem tetigerit qui talis est, non lotis ante manibus, lavabit vestimenta sua, et lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Vas fictile quod tetigerit confringetur: vas autem ligneum lavabitur aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Si sanatus fuerit qui hujuscemodi sustinet passionem, numerabit septem dies post emundationem sui, et lotis vestibus et toto corpore in aquis viventibus, erit mundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Die autem octavo sumet duos turtures, aut duos pullos columbæ, et veniet in conspectum Domini ad ostium tabernaculi testimonii, dabitque eos sacerdoti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'qui faciet unum pro peccato et alterum in holocaustum: rogabitque pro eo coram Domino, ut emundetur a fluxi seminis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Vir de quo egreditur semen coitus, lavabit aqua omne corpus suum: et immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Vestem et pellem, quam habuerit, lavabit aqua, et immunda erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Mulier, cum qua coierit, lavabitur aqua, et immunda erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Mulier, quæ redeunte mense patitur fluxum sanguinis, septem diebus separabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Omnis qui tetigerit eam, immundus erit usque ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'et in quo dormierit vel sederit diebus separationis suæ, polluetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Qui tetigerit lectum ejus, lavabit vestimenta sua: et ipse lotus aqua, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Omne vas, super quo illa sederit, quisquis attigerit, lavabit vestimenta sua: et ipse lotus aqua, pollutus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Si coierit cum ea vir tempore sanguinis menstrualis, immundus erit septem diebus: et omne stratum, in quo dormierit, polluetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Mulier, quæ patitur multis diebus fluxum sanguinis non in tempore menstruali, vel quæ post menstruum sanguinem fluere non cessat, quamdiu subjacet huic passioni, immunda erit quasi sit in tempore menstruo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Omne stratum, in quo dormierit, et vas in quo sederit, pollutum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Quicumque tetigerit ea, lavabit vestimenta sua: et ipse lotus aqua, immundus erit usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Si steterit sanguis, et fluere cessaverit, numerabit septem dies purificationis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'et die octavo offeret pro se sacerdoti duos turtures, aut duos pullos columbarum, ad ostium tabernaculi testimonii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'qui unum faciet pro peccato, et alterum in holocaustum, rogabitque pro ea coram Domino, et pro fluxu immunditiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Docebitis ergo filios Israël ut caveant immunditiam, et non moriantur in sordibus suis, cum polluerint tabernaculum meum quod est inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Ista est lex ejus, qui patitur fluxum seminis, et qui polluitur coitu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'et quæ menstruis temporibus separatur, vel quæ jugi fluit sanguine, et hominis qui dormierit cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Locutusque est Dominus ad Moysen post mortem duorum filiorum Aaron, quando offerentes ignem alienum interfecti sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'et præcepit ei, dicens: Loquere ad Aaron fratrem tuum, ne omni tempore ingrediatur sanctuarium, quod est intra velum coram propitiatorio quo tegitur arca, ut non moriatur (quia in nube apparebo super oraculum),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'nisi hæc ante fecerit: vitulum pro peccato offeret, et arietem in holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Tunica linea vestietur, feminalibus lineis verenda celabit: accingetur zona linea, cidarim lineam imponet capiti: hæc enim vestimenta sunt sancta: quibus cunctis, cum lotus fuerit, induetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Suscipietque ab universa multitudine filiorum Israël duos hircos pro peccato, et unum arietem in holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Cumque obtulerit vitulum, et oraverit pro se et pro domo sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'duos hircos stare faciet coram Domino in ostio tabernaculi testimonii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'mittensque super utrumque sortem, unam Domino, alteram capro emissario:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'cujus exierit sors Domino, offeret illum pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'cujus autem in caprum emissarium, statuet eum vivum coram Domino, ut fundat preces super eo, et emittat eum in solitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'His rite celebratis, offeret vitulum, et rogans pro se, et pro domo sua, immolabit eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'assumptoque thuribulo, quod de prunis altaris impleverit, et hauriens manu compositum thymiama in incensum, ultra velum intrabit in sancta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'ut, positis super ignem aromatibus, nebula eorum et vapor operiat oraculum quod est supra testimonium, et non moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Tollet quoque de sanguine vituli, et asperget digito septies contra propitiatorium ad orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Cumque mactaverit hircum pro peccato populi, inferet sanguinem ejus intra velum, sicut præceptum est de sanguine vituli, ut aspergat e regione oraculi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'et expiet sanctuarium ab immunditiis filiorum Israël, et a prævaricationibus eorum, cunctisque peccatis. Juxta hunc ritum faciet tabernaculo testimonii, quod fixum est inter eos, in medio sordium habitationis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Nullus hominum sit in tabernaculo, quando pontifex sanctuarium ingreditur, ut roget pro se, et pro domo sua, et pro universo cœtu Israël, donec egrediatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Cum autem exierit ad altare quod coram Domino est, oret pro se, et sumptum sanguinem vituli atque hirci fundat super cornua ejus per gyrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'aspergensque digito septies, expiet, et sanctificet illud ab immunditiis filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Postquam emundaverit sanctuarium, et tabernaculum, et altare, tunc offerat hircum viventem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'et posita utraque manu super caput ejus, confiteatur omnes iniquitates filiorum Israël, et universa delicta atque peccata eorum: quæ imprecans capiti ejus, emittet illum per hominem paratum, in desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Cumque portaverit hircus omnes iniquitates eorum in terram solitariam, et dimissus fuerit in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'revertetur Aaron in tabernaculum testimonii, et depositis vestibus, quibus prius indutus erat, cum intraret sanctuarium, relictisque ibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'lavabit carnem suam in loco sancto, indueturque vestibus suis. Et postquam egressus obtulerit holocaustum suum, ac plebis, rogabit tam pro se quam pro populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'et adipem, qui oblatus est pro peccatis, adolebit super altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Ille vero, qui dimiserit caprum emissarium, lavabit vestimenta sua, et corpus aqua, et sic ingredietur in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Vitulum autem, et hircum, qui pro peccato fuerant immolati, et quorum sanguis illatus est in sanctuarium, ut expiatio compleretur, asportabunt foras castra, et comburent igni tam pelles quam carnes eorum, ac fimum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'et quicumque combusserit ea, lavabit vestimenta sua et carnem aqua, et sic ingredietur in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Eritque vobis hoc legitimum sempiternum: mense septimo, decima die mensis, affligetis animas vestras, nullumque opus facietis, sive indigena, sive advena qui peregrinatur inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'In hac die expiatio erit vestri, atque mundatio ab omnibus peccatis vestris: coram Domino mundabimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sabbatum enim requietionis est, et affligetis animas vestras religione perpetua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Expiabit autem sacerdos, qui unctus fuerit, et cujus manus initiatæ sunt ut sacerdotio fungatur pro patre suo: indueturque stola linea et vestibus sanctis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'et expiabit sanctuarium et tabernaculum testimonii atque altare, sacerdotes quoque et universum populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Eritque vobis hoc legitimum sempiternum, ut oretis pro filiis Israël, et pro cunctis peccatis eorum semel in anno. Fecit igitur sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Loquere Aaron et filiis ejus, et cunctis filiis Israël, dicens ad eos: Iste est sermo quem mandavit Dominus, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Homo quilibet de domo Israël, si occiderit bovem aut ovem, sive capram, in castris vel extra castra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'et non obtulerit ad ostium tabernaculi oblationem Domino, sanguinis reus erit: quasi si sanguinem fuderit, sic peribit de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Ideo sacerdoti offerre debent filii Israël hostias suas, quas occident in agro, ut sanctificentur Domino ante ostium tabernaculi testimonii, et immolent eas hostias pacificas Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Fundetque sacerdos sanguinem super altare Domini ad ostium tabernaculi testimonii, et adolebit adipem in odorem suavitatis Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'et nequaquam ultra immolabunt hostias suas dæmonibus, cum quibus fornicati sunt. Legitimum sempiternum erit illis et posteris eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Et ad ipsos dices: Homo de domo Israël, et de advenis qui peregrinantur apud vos, qui obtulerit holocaustum sive victimam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'et ad ostium tabernaculi testimonii non adduxerit eam, ut offeratur Domino, interibit de populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Homo quilibet de domo Israël et de advenis qui peregrinantur inter eos, si comederit sanguinem, obfirmabo faciem meam contra animam illius, et disperdam eam de populo suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'quia anima carnis in sanguine est: et ego dedi illum vobis, ut super altare in eo expietis pro animabus vestris, et sanguis pro animæ piaculo sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Idcirco dixi filiis Israël: Omnis anima ex vobis non comedet sanguinem, nec ex advenis qui peregrinantur apud vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Homo quicumque de filiis Israël, et de advenis qui peregrinantur apud vos, si venatione atque aucupio ceperit feram, vel avem, quibus vesci licitum est, fundat sanguinem ejus, et operiat illum terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Anima enim omnis carnis in sanguine est: unde dixi filiis Israël: Sanguinem universæ carnis non comedetis, quia anima carnis in sanguine est: et quicumque comederit illum, interibit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Anima, quæ comederit morticinum, vel captum a bestia, tam de indigenis, quam de advenis, lavabit vestimenta sua et semetipsum aqua, et contaminatus erit usque ad vesperum: et hoc ordine mundus fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Quod si non laverit vestimenta sua et corpus, portabit iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Loquere filiis Israël, et dices ad eos: Ego Dominus Deus vester:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'juxta consuetudinem terræ \'gypti, in qua habitastis, non facietis: et juxta morem regionis Chanaan, ad quam ego introducturus sum vos, non agetis, nec in legitimis eorum ambulabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Facietis judicia mea, et præcepta mea servabitis, et ambulabitis in eis. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Custodite leges meas atque judicia, quæ faciens homo, vivet in eis. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Omnis homo ad proximam sanguinis sui non accedet, ut revelet turpitudinem ejus. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Turpitudinem patris tui et turpitudinem matris tuæ non discooperies: mater tua est: non revelabis turpitudinem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Turpitudinem uxoris patris tui non discooperies: turpitudo enim patris tui est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Turpitudinem sororis tuæ ex patre sive ex matre, quæ domi vel foris genita est, non revelabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Turpitudinem filiæ filii tui vel neptis ex filia non revelabis: quia turpitudo tua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Turpitudinem filiæ uxoris patris tui, quam peperit patri tuo, et est soror tua, non revelabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Turpitudinem sororis patris tui non discooperies: quia caro est patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Turpitudinem sororis matris tuæ non revelabis, eo quod caro sit matris tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Turpitudinem patrui tui non revelabis, nec accedes ad uxorem ejus, quæ tibi affinitate conjungitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Turpitudinem nurus tuæ non revelabis, quia uxor filii tui est: nec discooperies ignominiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Turpitudinem uxoris fratris tui non revelabis: quia turpitudo fratris tui est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Turpitudinem uxoris tuæ et filiæ ejus non revelabis. Filiam filii ejus, et filiam filiæ illius non sumes, ut reveles ignominiam ejus: quia caro illius sunt, et talis coitus incestus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Sororem uxoris tuæ in pellicatum illius non accipies, nec revelabis turpitudinem ejus adhuc illa vivente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Ad mulierem quæ patitur menstrua non accedes, nec revelabis fœditatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Cum uxore proximi tui non coibis, nec seminis commistione maculaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'De semine tuo non dabis ut consecretur idolo Moloch, nec pollues nomen Dei tui. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Cum masculo non commiscearis coitu femineo, quia abominatio est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Cum omni pecore non coibis, nec maculaberis cum eo. Mulier non succumbet jumento, nec miscebitur ei, quia scelus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Nec polluamini in omnibus his quibus contaminatæ sunt universæ gentes, quas ego ejiciam ante conspectum vestrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'et quibus polluta est terra: cujus ego scelera visitabo, ut evomat habitatores suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Custodite legitima mea atque judicia, et non faciatis ex omnibus abominationibus istis, tam indigena quam colonus qui peregrinantur apud vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Omnes enim execrationes istas fecerunt accolæ terræ qui fuerunt ante vos, et polluerunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Cavete ergo ne et vos similiter evomat, cum paria feceritis, sicut evomuit gentem, quæ fuit ante vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Omnis anima, quæ fecerit de abominationibus his quippiam, peribit de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Custodite mandata mea. Nolite facere quæ fecerunt hi qui fuerunt ante vos, et ne polluamini in eis. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Loquere ad omnem cœtum filiorum Israël, et dices ad eos: Sancti estote, quia ego sanctus sum, Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Unusquisque patrem suum, et matrem suam timeat. Sabbata mea custodite. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Nolite converti ad idola, nec deos conflatiles faciatis vobis. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Si immolaveritis hostiam pacificorum Domino, ut sit placabilis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'eo die quo fuerit immolata, comedetis eam, et die altero: quidquid autem residuum fuerit in diem tertium, igne comburetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Si quis post biduum comederit ex ea, profanus erit, et impietatis reus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'portabitque iniquitatem suam, quia sanctum Domini polluit, et peribit anima illa de populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Cumque messueris segetes terræ tuæ, non tondebis usque ad solum superficiem terræ, nec remanentes spicas colliges,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'neque in vinea tua racemos et grana decidentia congregabis: sed pauperibus et peregrinis carpenda dimittes. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Non facietis furtum. Non mentiemini, nec decipiet unusquisque proximum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Non perjurabis in nomine meo, nec pollues nomen Dei tui. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Non facies calumniam proximo tuo nec vi opprimes eum. Non morabitur opus mercenarii tui apud te usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Non maledices surdo, nec coram cæco pones offendiculum: sed timebis Dominum Deum tuum, quia ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Non facies quod iniquum est, nec injuste judicabis. Non consideres personam pauperis, nec honores vultum potentis. Juste judica proximo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Non eris criminator, nec susurro in populo. Non stabis contra sanguinem proximi tui. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Non oderis fratrem tuum in corde tuo, sed publice argue eum, ne habeas super illo peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Non quæras ultionem, nec memor eris injuriæ civium tuorum. Diliges amicum tuum sicut teipsum. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Leges meas custodite. Jumentum tuum non facies coire cum alterius generis animantibus. Agrum tuum non seres diverso semine. Veste, quæ ex duobus texta est, non indueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Homo, si dormierit cum muliere coitu seminis, quæ sit ancilla etiam nubilis, et tamen pretio non redempta, nec libertate donata: vapulabunt ambo, et non morientur, quia non fuit libera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Pro delicto autem suo offeret Domino ad ostium tabernaculi testimonii arietem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'orabitque pro eo sacerdos, et pro peccato ejus coram Domino, et repropitiabitur ei, dimitteturque peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Quando ingressi fueritis terram, et plantaveritis in ea ligna pomifera, auferetis præputia eorum: poma, quæ germinant, immunda erunt vobis, nec edetis ex eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Quarto autem anno omnis fructus eorum sanctificabitur, laudabilis Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Quinto autem anno comedetis fructus, congregantes poma, quæ proferunt. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Non comedetis cum sanguine. Non augurabimini, nec observabitis somnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Neque in rotundum attondebitis comam, nec radetis barbam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Et super mortuo non incidetis carnem vestram, neque figuras aliquas aut stigmata facietis vobis. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne prostituas filiam tuam, ne contaminetur terra et impleatur piaculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Sabbata mea custodite, et sanctuarium meum metuite. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Non declinetis ad magos, nec ab ariolis aliquid sciscitemini, ut polluamini per eos. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Coram cano capite consurge, et honora personam senis: et time Dominum Deum tuum. Ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Si habitaverit advena in terra vestra, et moratus fuerit inter vos, non exprobretis ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'sed sit inter vos quasi indigena, et diligetis eum quasi vosmetipsos: fuistis enim et vos advenæ in terra \'gypti. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nolite facere iniquum aliquid in judicio, in regula, in pondere, in mensura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Statera justa, et æqua sint pondera, justus modius, æquusque sextarius. Ego Dominus Deus vester, qui eduxi vos de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Custodite omnia præcepta mea, et universa judicia, et facite ea. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Hæc loqueris filiis Israël: Homo de filiis Israël, et de advenis qui habitant in Israël, si quis dederit de semine suo idolo Moloch, morte moriatur: populus terræ lapidabit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Et ego ponam faciem meam contra illum: succidamque eum de medio populi sui, eo quod dederit de semine suo Moloch, et contaminaverit sanctuarium meum, ac polluerit nomen sanctum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Quod si negligens populus terræ, et quasi parvipendens imperium meum, dimiserit hominem qui dedit de semine suo Moloch, nec voluerit eum occidere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'ponam faciem meam super hominem illum, et super cognationem ejus, succidamque et ipsum, et omnes qui consenserunt ei ut fornicarentur cum Moloch, de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Anima, quæ declinaverit ad magos et ariolos, et fornicata fuerit cum eis, ponam faciem meam contra eam, et interficiam illam de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Sanctificamini et estote sancti, quia ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Custodite præcepta mea, et facite ea: ego Dominus qui sanctifico vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Qui maledixerit patri suo, aut matri, morte moriatur: patri matrique maledixit: sanguis ejus sit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Si mœchatus quis fuerit cum uxore alterius, et adulterium perpetraverit cum conjuge proximi sui, morte moriantur et mœchus et adultera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Qui dormierit cum noverca sua, et revelaverit ignominiam patris sui, morte moriantur ambo: sanguis eorum sit super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Si quis dormierit cum nuru sua, uterque moriatur, quia scelus operati sunt: sanguis eorum sit super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Qui dormierit cum masculo coitu femineo, uterque operatus est nefas: morte moriantur: sit sanguis eorum super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Qui supra uxorem filiam, duxerit matrem ejus, scelus operatus est: vivus ardebit cum eis, nec permanebit tantum nefas in medio vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Qui cum jumento et pecore coierit, morte moriatur: pecus quoque occidite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Mulier, quæ succubuerit cuilibet jumento, simul interficietur cum eo: sanguis eorum sit super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Qui acceperit sororem suam filiam patris sui, vel filiam matris suæ, et viderit turpitudinem ejus, illaque conspexerit fratris ignominiam, nefariam rem operati sunt: occidentur in conspectu populi sui, eo quod turpitudinem suam mutuo revelaverint, et portabunt iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Qui coierit cum muliere in fluxu menstruo, et revelaverit turpitudinem ejus, ipsaque aperuerit fontem sanguinis sui, interficientur ambo de medio populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Turpitudinem materteræ et amitæ tuæ non discooperies: qui hoc fecerit, ignominiam carnis suæ nudavit; portabunt ambo iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Qui coierit cum uxore patrui vel avunculi sui, et revelaverit ignominiam cognationis suæ, portabunt ambo peccatum suum: absque liberis morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Qui duxerit uxorem fratris sui, rem facit illicitam: turpitudinem fratris sui revelavit: absque liberis erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Custodite leges meas, atque judicia, et facite ea: ne et vos evomat terra quam intraturi estis et habitaturi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Nolite ambulare in legitimis nationum, quas ego expulsurus sum ante vos. Omnia enim hæc fecerunt, et abominatus sum eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Vobis autem loquor. Possidete terram eorum, quam dabo vobis in hæreditatem, terram fluentem lacte et melle. Ego Dominus Deus vester, qui separavi vos a ceteris populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Separate ergo et vos jumentum mundum ab immundo, et avem mundam ab immunda: ne polluatis animas vestras in pecore, et avibus, et cunctis quæ moventur in terra, et quæ vobis ostendi esse polluta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Eritis mihi sancti, quia sanctus sum ego Dominus, et separavi vos a ceteris populis, ut essetis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Vir, sive mulier, in quibus pythonicus, vel divinationis fuerit spiritus, morte moriantur: lapidibus obruent eos: sanguis eorum sit super illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Dixit quoque Dominus ad Moysen: Loquere ad sacerdotes filios Aaron, et dices ad eos: Ne contaminetur sacerdos in mortibus civium suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'nisi tantum in consanguineis, ac propinquis, id est, super patre et matre, et filio, et filia, fratre quoque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'et sorore virgine quæ non est nupta viro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'sed nec in principe populi sui contaminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Non radent caput, nec barbam, neque in carnibus suis facient incisuras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sancti erunt Deo suo, et non polluent nomen ejus: incensum enim Domini, et panes Dei sui offerunt, et ideo sancti erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Scortum et vile prostibulum non ducent uxorem, nec eam quæ repudiata est a marito: quia consecrati sunt Deo suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'et panes propositionis offerunt. Sint ergo sancti, quia et ego sanctus sum, Dominus qui sanctifico eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Sacerdotis filia si deprehensa fuerit in stupro, et violaverit nomen patris sui, flammis exuretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Pontifex, id est, sacerdos maximus inter fratres suos, super cujus caput fusum est unctionis oleum, et cujus manus in sacerdotio consecratæ sunt, vestitusque est sanctis vestibus, caput suum non discooperiet, vestimenta non scindet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'et ad omnem mortuum non ingredietur omnino: super patre quoque suo et matre non contaminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Nec egredietur de sanctis, ne polluat sanctuarium Domini, quia oleum sanctæ unctionis Dei sui super eum est. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Virginem ducet uxorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'viduam autem et repudiatam, et sordidam, atque meretricem non accipiet, sed puellam de populo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'ne commisceat stirpem generis sui vulgo gentis suæ: quia ego Dominus, qui sanctifico eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Loquere ad Aaron: Homo de semine tuo per familias qui habuerit maculam, non offeret panes Deo suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'nec accedet ad ministerium ejus: si cæcus fuerit, si claudus, si parvo vel grandi, vel torto naso,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'si fracto pede, si manu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'si gibbus, si lippus, si albuginem habens in oculo, si jugem scabiem, si impetiginem in corpore, vel herniosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Omnis qui habuerit maculam de semine Aaron sacerdotis, non accedet offerre hostias Domino, nec panes Deo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'vescetur tamen panibus qui offeruntur in sanctuario,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'ita dumtaxat, ut intra velum non ingrediatur, nec accedat ad altare, quia maculam habet, et contaminare non debet sanctuarium meum. Ego Dominus qui sanctifico eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Locutus est ergo Moyses ad Aaron, et ad filios ejus, et ad omnem Israël cuncta quæ fuerant sibi imperata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Locutus quoque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Loquere ad Aaron et ad filios ejus, ut caveant ab his quæ consecrata sunt filiorum Israël, et non contaminent nomen sanctificatorum mihi, quæ ipsi offerunt. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dic ad eos, et ad posteros eorum: Omnis homo qui accesserit de stirpe vestra ad ea quæ consecrata sunt, et quæ obtulerunt filii Israël Domino, in quo est immunditia, peribit coram Domino. Ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Homo de semine Aaron, qui fuerit leprosus, aut patiens fluxum seminis, non vescetur de his quæ sanctificata sunt mihi, donec sanetur. Qui tetigerit immundum super mortuo, et ex quo egreditur semen quasi coitus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'et qui tangit reptile, et quodlibet immundum cujus tactus est sordidus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'immundus erit usque ad vesperum, et non vescetur his quæ sanctificata sunt: sed cum laverit carnem suam aqua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'et occubuerit sol, tunc mundatus vescetur de sanctificatis, quia cibus illius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Morticinum et captum a bestia non comedent, nec polluentur in eis. Ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Custodiant præcepta mea, ut non subjaceant peccato, et moriantur in sanctuario, cum polluerint illud. Ego Dominus qui sanctifico eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Omnis alienigena non comedet de sanctificatis; inquilinus sacerdotis et mercenarius non vescentur ex eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Quem autem sacerdos emerit, et qui vernaculus domus ejus fuerit, his comedent ex eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Si filia sacerdotis cuilibet ex populo nupta fuerit, de his quæ sanctificata sunt, et de primitiis non vescetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Sin autem vidua, vel repudiata, et absque liberis reversa fuerit ad domum patris sui: sicut puella consueverat, aletur cibis patris sui. Omnis alienigena comedendi ex eis non habet potestatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Qui comederit de sanctificatis per ignorantiam, addet quintam partem cum eo quod comedit, et dabit sacerdoti in sanctuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Nec contaminabunt sanctificata filiorum Israël, quæ offerunt Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'ne forte sustineant iniquitatem delicti sui, cum sanctificata comederint. Ego Dominus qui sanctifico eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Loquere ad Aaron et filios ejus, et ad omnes filios Israël, dicesque ad eos: Homo de domo Israël, et de advenis qui habitant apud vos, qui obtulerit oblationem suam, vel vota solvens, vel sponte offerens, quidquid illud obtulerit in holocaustum Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'ut offeratur per vos, masculus immaculatus erit ex bobus, et ovibus, et ex capris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'si maculam habuerit, non offeretis, neque erit acceptabile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Homo qui obtulerit victimam pacificorum Domino, vel vota solvens, vel sponte offerens, tam de bobus quam de ovibus, immaculatum offeret ut acceptabile sit: omnis macula non erit in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Si cæcum fuerit, si fractum, si cicatricem habens, si papulas, aut scabiem, aut impetiginem: non offeretis ea Domino, nec adolebitis ex eis super altare Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Bovem et ovem, aure et cauda amputatis, voluntarie offerre potes, votum autem ex eis solvi non potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Omne animal, quod vel contritis, vel tusis, vel sectis ablatisque testiculis est, non offeretis Domino, et in terra vestra hoc omnino ne faciatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'De manu alienigenæ non offeretis panes Deo vestro, et quidquid aliud dare voluerit, quia corrupta, et maculata sunt omnia: non suscipietis ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Bos, ovis et capra, cum genita fuerint, septem diebus erunt sub ubere matris suæ: die autem octavo, et deinceps, offerri poterunt Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Sive illa bos, sive ovis, non immolabuntur una die cum fœtibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Si immolaveritis hostiam pro gratiarum actione Domino, ut possit esse placabilis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'eodem die comedetis eam: non remanebit quidquam in mane alterius diei. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Custodite mandata mea, et facite ea. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Ne polluatis nomen meum sanctum, ut sanctificer in medio filiorum Israël. Ego Dominus qui sanctifico vos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'et eduxi de terra \'gypti, ut essem vobis in Deum. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Loquere filiis Israël, et dices ad eos: Hæ sunt feriæ Domini, quas vocabitis sanctas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sex diebus facietis opus: dies septimus, quia sabbati requies est, vocabitur sanctus: omne opus non facietis in eo: sabbatum Domini est in cunctis habitationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Hæ sunt ergo feriæ Domini sanctæ, quas celebrare debetis temporibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Mense primo, quartadecima die mensis ad vesperum, Phase Domini est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'et quintadecima die mensis hujus, solemnitas azymorum Domini est. Septem diebus azyma comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Dies primus erit vobis celeberrimus, sanctusque: omne opus servile non facietis in eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'sed offeretis sacrificium in igne Domino septem diebus. Dies autem septimus erit celebrior et sanctior: nullumque servile opus facietis in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Loquere filiis Israël, et dices ad eos: Cum ingressi fueritis terram, quam ego dabo vobis, et messueritis segetem, feretis manipulos spicarum, primitias messis vestræ, ad sacerdotem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'qui elevabit fasciculum coram Domino, ut acceptabile sit pro vobis, altero die sabbati, et sanctificabit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Atque in eodem die quo manipulus consecratur, cædetur agnus immaculatus anniculus in holocaustum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Et libamenta offerentur cum eo, duæ decimæ similæ conspersæ oleo in incensum Domini, odoremque suavissimum: liba quoque vini, quarta pars hin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Panem, et polentam, et pultes non comedetis ex segete, usque ad diem qua offeretis ex ea Deo vestro. Præceptum est sempiternum in generationibus, cunctisque habitaculis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Numerabitis ergo ab altero die sabbati, in quo obtulistis manipulum primitiarum, septem hebdomadas plenas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'usque ad alteram diem expletionis hebdomadæ septimæ, id est, quinquaginta dies: et sic offeretis sacrificium novum Domino');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'ex omnibus habitaculis vestris, panes primitiarum duos de duabus decimis similæ fermentatæ, quos coquetis in primitias Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Offeretisque cum panibus septem agnos immaculatos anniculos, et vitulum de armento unum, et arietes duos, et erunt in holocaustum cum libamentis suis, in odorem suavissimum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Facietis et hircum pro peccato, duosque agnos anniculos hostias pacificorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Cumque elevaverit eos sacerdos cum panibus primitiarum coram Domino, cedent in usum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Et vocabitis hunc diem celeberrimum, atque sanctissimum: omne opus servile non facietis in eo. Legitimum sempiternum erit in cunctis habitaculis, et generationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Postquam autem messueritis segetem terræ vestræ, nec secabitis eam usque ad solum, nec remanentes spicas colligetis: sed pauperibus et peregrinis dimittetis eas. Ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Loquere filiis Israël: Mense septimo, prima die mensis, erit vobis sabbatum, memoriale, clangentibus tubis, et vocabitur sanctum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'omne opus servile non facietis in eo, et offeretis holocaustum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Decimo die mensis hujus septimi, dies expiationum erit celeberrimus, et vocabitur sanctus: affligetisque animas vestras in eo, et offeretis holocaustum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Omne opus servile non facietis in tempore diei hujus: quia dies propitiationis est, ut propitietur vobis Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Omnis anima, quæ afflicta non fuerit die hac, peribit de populis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'et quæ operis quippiam fecerit, delebo eam de populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nihil ergo operis facietis in eo: legitimum sempiternum erit vobis in cunctis generationibus, et habitationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sabbatum requietionis est, et affligetis animas vestras die nono mensis: a vespera usque ad vesperam celebrabitis sabbata vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Loquere filiis Israël: A quintodecimo die mensis hujus septimi, erunt feriæ tabernaculorum septem diebus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Dies primus vocabitur celeberrimus atque sanctissimus: omne opus servile non facietis in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Et septem diebus offeretis holocausta Domino. Dies quoque octavus erit celeberrimus, atque sanctissimus, et offeretis holocaustum Domino: est enim cœtus atque collectæ: omne opus servile non facietis in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Hæ sunt feriæ Domini, quas vocabitis celeberrimas atque sanctissimas, offeretisque in eis oblationes Domino, holocausta et libamenta juxta ritum uniuscujusque diei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'exceptis sabbatis Domini, donisque vestris, et quæ offeretis ex voto, vel quæ sponte tribuetis Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'A quintodecimo ergo die mensis septimi, quando congregaveritis omnes fructus terræ vestræ, celebrabitis ferias Domini septem diebus: die primo et die octavo erit sabbatum, id est, requies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Sumetisque vobis die primo fructus arboris pulcherrimæ, spatulasque palmarum, et ramos ligni densarum frondium, et salices de torrente, et lætabimini coram Domino Deo vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Celebrabitisque solemnitatem ejus septem diebus per annum: legitimum sempiternum erit in generationibus vestris. Mense septimo festa celebrabitis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'et habitabitis in umbraculis septem diebus: omnis, qui de genere est Israël, manebit in tabernaculis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'ut discant posteri vestri quod in tabernaculis habitare fecerim filios Israël, cum educerem eos de terra \'gypti. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Locutusque est Moyses super solemnitatibus Domini ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Præcipe filiis Israël, ut afferant tibi oleum de olivis purissimum, ac lucidum, ad concinnandas lucernas jugiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'extra velum testimonii in tabernaculo fœderis. Ponetque eas Aaron a vespere usque ad mane coram Domino, cultu rituque perpetuo in generationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Super candelabrum mundissimum ponentur semper in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Accipies quoque similam, et coques ex ea duodecim panes, qui singuli habebunt duas decimas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'quorum senos altrinsecus super mensam purissimam coram Domino statues:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'et pones super eos thus lucidissimum, ut sit panis in monimentum oblationis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Per singula sabbata mutabuntur coram Domino suscepti a filiis Israël fœdere sempiterno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'eruntque Aaron et filiorum ejus, ut comedant eos in loco sancto: quia Sanctum sanctorum est de sacrificiis Domini jure perpetuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Ecce autem egressus filius mulieris Israëlitidis, quem pepererat de viro ægyptio inter filios Israël, jurgatus est in castris cum viro Israëlita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Cumque blasphemasset nomen, et maledixisset ei, adductus est ad Moysen. (Vocabatur autem mater ejus Salumith, filia Dabri de tribu Dan.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Miseruntque eum in carcerem, donec nossent quid juberet Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Qui locutus est ad Moysen,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'dicens: Educ blasphemum extra castra, et ponant omnes qui audierunt, manus suas super caput ejus, et lapidet eum populus universus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Et ad filios Israël loqueris: Homo, qui maledixerit Deo suo, portabit peccatum suum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'et qui blasphemaverit nomen Domini, morte moriatur: lapidibus opprimet eum omnis multitudo, sive ille civis, sive peregrinus fuerit. Qui blasphemaverit nomen Domini, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Qui percusserit, et occiderit hominem, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Qui percusserit animal, reddet vicarium, id est, animam pro anima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Qui irrogaverit maculam cuilibet civium suorum, sicut fecit, sic fiet ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'fracturam pro fractura, oculum pro oculo, dentem pro dente restituet: qualem inflixerit maculam, talem sustinere cogetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Qui percusserit jumentum, reddet aliud. Qui percusserit hominem, punietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, '\'quum judicium sit inter vos, sive peregrinus, sive civis peccaverit: quia ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Locutusque est Moyses ad filios Israël: et eduxerunt eum, qui blasphemaverat, extra castra, ac lapidibus oppresserunt. Feceruntque filii Israël sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Locutusque est Dominus ad Moysen in monte Sinai, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Loquere filiis Israël, et dices ad eos: Quando ingressi fueritis terram quam ego dabo vobis, sabbatizes sabbatum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sex annis seres agrum tuum, et sex annis putabis vineam tuam, colligesque fructus ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'septimo autem anno sabbatum erit terræ, requietionis Domini: agrum non seres, et vineam non putabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Quæ sponte gignet humus, non metes: et uvas primitiarum tuarum non colliges quasi vindemiam: annus enim requietionis terræ est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'sed erunt vobis in cibum, tibi et servo tuo, ancillæ et mercenario tuo, et advenæ qui peregrinantur apud te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'jumentis tuis et pecoribus, omnia quæ nascuntur præbebunt cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Numerabis quoque tibi septem hebdomadas annorum, id est, septies septem, quæ simul faciunt annos quadraginta novem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'et clanges buccina mense septimo, decima die mensis, propitiationis tempore, in universa terra vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Sanctificabisque annum quinquagesimum, et vocabis remissionem cunctis habitatoribus terræ tuæ: ipse est enim jubilæus. Revertetur homo ad possessionem suam, et unusquisque rediet ad familiam pristinam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'quia jubilæus est, et quinquagesimus annus. Non seretis neque metetis sponte in agro nascentia, et primitias vindemiæ non colligetis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'ob sanctificationem jubilæi: sed statim oblata comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Anno jubilæi, redient omnes ad possessiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Quando vendes quippiam civi tuo, vel emes ab eo, ne contristes fratrem tuum, sed juxta numerum annorum jubilæi emes ab eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'et juxta supputationem frugum vendet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Quanto plures anni remanserint post jubilæum, tanto crescet et pretium: et quanto minus temporis numeraveris, tanto minoris et emptio constabit: tempus enim frugum vendet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Nolite affligere contribules vestros, sed timeat unusquisque Deum suum, quia ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Facite præcepta mea, et judicia custodite, et implete ea: ut habitare possitis in terra absque ullo pavore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'et gignat vobis humus fructus suos, quibus vescamini usque ad saturitatem, nullius impetum formidantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Quod si dixeritis: Quid comedemus anno septimo, si non severimus, neque collegerimus fruges nostras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'dabo benedictionem meam vobis anno sexto, et faciet fructus trium annorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'seretisque anno octavo, et comedetis veteres fruges usque ad nonum annum: donec nova nascantur, edetis vetera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Terra quoque non vendetur in perpetuum, quia mea est, et vos advenæ et coloni mei estis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'unde cuncta regio possessionis vestræ sub redemptionis conditione vendetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si attenuatus frater tuus vendiderit possessiunculam suam, et voluerit propinquus ejus, potest redimere quod ille vendiderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Sin autem non habuerit proximum, et ipse pretium ad redimendum potuerit invenire,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'computabuntur fructus ex eo tempore quo vendidit: et quod reliquum est, reddet emptori, sicque recipiet possessionem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Quod si non invenerit manus ejus ut reddat pretium, habebit emptor quod emerat, usque ad annum jubilæum. In ipso enim omnis venditio redibit ad dominum et ad possessorem pristinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Qui vendiderit domum intra urbis muros, habebit licentiam redimendi, donec unus impleatur annus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Si non redemerit, et anni circulus fuerit evolutus, emptor possidebit eam, et posteri ejus in perpetuum, et redimi non poterit, etiam in jubilæo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Sin autem in villa domus, quæ muros non habet, agrorum jure vendetur: si ante redempta non fuerit, in jubilæo revertetur ad dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, '\'des Levitarum quæ in urbibus sunt, semper possunt redimi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'si redemptæ non fuerint, in jubilæo revertentur ad dominos, quia domus urbium Levitarum pro possessionibus sunt inter filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Suburbana autem eorum non veneant, quia possessio sempiterna est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Si attenuatus fuerit frater tuus, et infirmus manu, et susceperis eum quasi advenam et peregrinum, et vixerit tecum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'ne accipias usuras ab eo, nec amplius quam dedisti: time Deum tuum, ut vivere possit frater tuus apud te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Pecuniam tuam non dabis ei ad usuram, et frugum superabundantiam non exiges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ego Dominus Deus vester, qui eduxi vos de terra \'gypti, ut darem vobis terram Chanaan, et essem vester Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Si paupertate compulsus vendiderit se tibi frater tuus, non eum opprimes servitute famulorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'sed quasi mercenarius et colonus erit: usque ad annum jubilæum operabitur apud te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'et postea egredietur cum liberis suis, et revertetur ad cognationem, ad possessionem patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Mei enim servi sunt, et ego eduxi eos de terra \'gypti: non veneant conditione servorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'ne affligas eum per potentiam, sed metuito Deum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Servus et ancilla sint vobis de nationibus quæ in circuitu vestro sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'et de advenis qui peregrinantur apud vos, vel qui ex his nati fuerint in terra vestra, hos habebitis famulos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'et hæreditario jure transmittetis ad posteros, ac possidebitis in æternum: fratres autem vestros filios Israël ne opprimatis per potentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Si invaluerit apud vos manus advenæ atque peregrini, et attenuatus frater tuus vendiderit se ei, aut cuiquam de stirpe ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'post venditionem potest redimi. Qui voluerit ex fratribus suis, redimet eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'et patruus, et patruelis, et consanguineus, et affinis. Sin autem et ipse potuerit, redimet se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'supputatis dumtaxat annis a tempore venditionis suæ usque ad annum jubilæum: et pecunia, qua venditus fuerat, juxta annorum numerum, et rationem mercenarii supputata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Si plures fuerint anni qui remanent usque ad jubilæum, secundum hos reddet et pretium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'si pauci, ponet rationem cum eo juxta annorum numerum, et reddet emptori quod reliquum est annorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'quibus ante servivit mercedibus imputatis: non affliget eum violenter in conspectu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Quod si per hæc redimi non potuerit, anno jubilæo egredietur cum liberis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Mei enim sunt servi filii Israël, quos eduxi de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ego Dominus Deus vester: non facietis vobis idolum, et sculptile, nec titulos erigetis, nec insignem lapidem ponetis in terra vestra, ut adoretis eum. Ego enim sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Custodite sabbata mea, et pavete ad sanctuarium meum. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si in præceptis meis ambulaveritis, et mandata mea custodieritis, et feceritis ea, dabo vobis pluvias temporibus suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'et terra gignet germen suum, et pomis arbores replebuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Apprehendet messium tritura vindemiam, et vindemia occupabit sementem: et comedetis panem vestrum in saturitate, et absque pavore habitabitis in terra vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Dabo pacem in finibus vestris: dormietis, et non erit qui exterreat. Auferam malas bestias, et gladius non transibit terminos vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Persequemini inimicos vestros, et corruent coram vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Persequentur quinque de vestris centum alienos, et centum de vobis decem millia: cadent inimici vestri gladio in conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Respiciam vos, et crescere faciam: multiplicabimini, et firmabo pactum meum vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Comedetis vetustissima veterum, et vetera novis supervenientibus projicietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ponam tabernaculum meum in medio vestri, et non abjiciet vos anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ambulabo inter vos, et ero Deus vester, vosque eritis populus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ego Dominus Deus vester, qui eduxi vos de terra \'gyptiorum, ne serviretis eis: et qui confregi catenas cervicum vestrarum, ut incederetis erecti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Quod si non audieritis me, nec feceritis omnia mandata mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'si spreveritis leges meas, et judicia mea contempseritis, ut non faciatis ea quæ a me constituta sunt, et ad irritum perducatis pactum meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'ego quoque hæc faciam vobis: visitabo vos velociter in egestate, et ardore, qui conficiat oculos vestros, et consumat animas vestras. Frustra seretis sementem, quæ ab hostibus devorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Ponam faciem meam contra vos, et corruetis coram hostibus vestris, et subjiciemini his qui oderunt vos: fugietis, nemine persequente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Sin autem nec sic obedieritis mihi, addam correptiones vestras septuplum propter peccata vestra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'et conteram superbiam duritiæ vestræ. Daboque vobis cælum desuper sicut ferrum, et terram æneam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Consumetur incassum labor vester, non proferet terra germen, nec arbores poma præbebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Si ambulaveritis ex adverso mihi, nec volueritis audire me, addam plagas vestras in septuplum propter peccata vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'immittamque in vos bestias agri, quæ consumant vos, et pecora vestra, et ad paucitatem cuncta redigant, desertæque fiant viæ vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Quod si nec sic volueritis recipere disciplinam, sed ambulaveritis ex adverso mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'ego quoque contra vos adversus incedam, et percutiam vos septies propter peccata vestra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'inducamque super vos gladium ultorem fœderis mei. Cumque confugeritis in urbes, mittam pestilentiam in medio vestri, et trademini in manibus hostium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'postquam confregero baculum panis vestri: ita ut decem mulieres in uno clibano coquant panes, et reddant eos ad pondus: et comedetis, et non saturabimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Sin autem nec per hæc audieritis me, sed ambulaveritis contra me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'et ego incedam adversus vos in furore contrario, et corripiam vos septem plagis propter peccata vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'ita ut comedatis carnes filiorum vestrorum et filiarum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Destruam excelsa vestra, et simulacra confringam. Cadetis inter ruinas idolorum vestrorum, et abominabitur vos anima mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'in tantum ut urbes vestras redigam in solitudinem, et deserta faciam sanctuaria vestra, nec recipiam ultra odorem suavissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Disperdamque terram vestram, et stupebunt super ea inimici vestri, cum habitatores illius fuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Vos autem dispergam in gentes, et evaginabo post vos gladium, eritque terra vestra deserta, et civitates vestræ dirutæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tunc placebunt terræ sabbata sua cunctis diebus solitudinis suæ: quando fueritis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'in terra hostili, sabbatizabit, et requiescet in sabbatis solitudinis suæ, eo quod non requieverit in sabbatis vestris quando habitabatis in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Et qui de vobis remanserint, dabo pavorem in cordibus eorum in regionibus hostium, terrebit eos sonitus folii volantis, et ita fugient quasi gladium: cadent, nullo persequente,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'et corruent singuli super fratres suos, quasi bella fugientes, nemo vestrum inimicis audebit resistere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Peribitis inter gentes, et hostilis vos terra consumet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Quod si et de iis aliqui remanserint, tabescent in iniquitatibus suis, in terra inimicorum suorum, et propter peccata patrum suorum et sua affligentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'donec confiteantur iniquitates suas, et majorum suorum, quibus prævaricati sunt in me, et ambulaverunt ex adverso mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Ambulabo igitur et ego contra eos, et inducam illos in terram hostilem, donec erubescat incircumcisa mens eorum: tunc orabunt pro impietatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Et recordabor fœderis mei, quod pepigi cum Jacob, et Isaac, et Abraham. Terræ quoque memor ero:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'quæ cum relicta fuerit ab eis, complacebit sibi in sabbatis suis, patiens solitudinem propter illos. Ipsi vero rogabunt pro peccatis suis, eo quod abjecerint judicia mea, et leges meas despexerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Et tamen etiam cum essent in terra hostili, non penitus abjeci eos, neque sic despexi ut consumerentur, et irritum facerent pactum meum cum eis. Ego enim sum Dominus Deus eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'et recordabor fœderis mei pristini, quando eduxi eos de terra \'gypti in conspectu gentium, ut essem Deus eorum. Ego Dominus. Hæc sunt judicia atque præcepta et leges quas dedit Dominus inter se et filios Israël in monte Sinai per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Loquere filiis Israël, et dices ad eos: Homo qui votum fecerit, et spoponderit Deo animam suam, sub æstimatione dabit pretium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Si fuerit masculus a vigesimo anno usque ad sexagesimum annum, dabit quinquaginta siclos argenti ad mensuram sanctuarii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'si mulier, triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'A quinto autem anno usque ad vigesimum, masculus dabit viginti siclos: femina, decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ab uno mense usque ad annum quintum, pro masculo dabuntur quinque sicli: pro femina, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Sexagenarius et ultra masculus dabit quindecim siclos: femina, decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Si pauper fuerit, et æstimationem reddere non valebit, stabit coram sacerdote: et quantum ille æstimaverit, et viderit eum posse reddere, tantum dabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Animal autem, quod immolari potest Domino, si quis voverit, sanctum erit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'et mutari non poterit, id est, nec melius malo, nec pejus bono: quod si mutaverit, et ipsum quod mutatum est, et illud pro quo mutatum est, consecratum erit Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Animal immundum, quod immolari Domino non potest, si quis voverit, adducetur ante sacerdotem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'qui judicans utrum bonum an malum sit, statuet pretium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Quod si dare voluerit is qui offert, addet supra æstimationem quintam partem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Homo si voverit domum suam, et sanctificaverit Domino, considerabit eam sacerdos utrum bona an mala sit, et juxta pretium, quod ab eo fuerit constitutum, venundabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'sin autem ille qui voverat, voluerit redimere eam, dabit quintam partem æstimationis supra, et habebit domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Quod si agrum possessionis suæ voverit, et consecraverit Domino, juxta mensuram sementis æstimabitur pretium: si triginta modiis hordei seritur terra, quinquaginta siclis venundetur argenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Si statim ab anno incipientis jubilæi voverit agrum, quanto valere potest, tanto æstimabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Sin autem post aliquantum temporis, supputabit sacerdos pecuniam juxta annorum, qui reliqui sunt, numerum usque ad jubilæum, et detrahetur ex pretio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Quod si voluerit redimere agrum ille qui voverat, addet quintam partem æstimatæ pecuniæ, et possidebit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Sin autem noluerit redimere, sed alteri cuilibet fuerit venundatus, ultra eum qui voverat redimere non poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Quia cum jubilæi venerit dies, sanctificatus erit Domino, et possessio consecrata ad jus pertinet sacerdotum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Si ager emptus est, et non de possessione majorum sanctificatus fuerit Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'supputabit sacerdos juxta annorum numerum usque ad jubilæum, pretium: et dabit ille qui voverat eum, Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'In jubilæo autem revertetur ad priorem dominum, qui vendiderat eum, et habuerat in sorte possessionis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Omnis æstimatio siclo sanctuarii ponderabitur. Siclus viginti obolos habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Primogenita, quæ ad Dominum pertinent, nemo sanctificare poterit et vovere: sive bos, sive ovis fuerit, Domini sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Quod si immundum est animal, redimet qui obtulit, juxta æstimationem tuam, et addet quintam partem pretii: si redimere noluerit, vendetur alteri quantocumque a te fuerit æstimatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Omne quod Domino consecratur, sive homo fuerit, sive animal, sive ager, non vendetur, nec redimi poterit. Quidquid semel fuerit consecratum, Sanctum sanctorum erit Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'et omnis consecratio, quæ offertur ab homine, non redimetur, sed morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Omnes decimæ terræ, sive de frugibus, sive de pomis arborum, Domini sunt, et illi sanctificantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Si quis autem voluerit redimere decimas suas, addet quintam partem earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Omnium decimarum bovis et ovis et capræ, quæ sub pastoris virga transeunt, quidquid decimum venerit, sanctificabitur Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Non eligetur nec bonum nec malum, nec altero commutabitur, si quis mutaverit: et quod mutatum est, et pro quo mutatum est, sanctificabitur Domino, et non redimetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Hæc sunt præcepta, quæ mandavit Dominus Moysi ad filios Israël in monte Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Locutusque est Dominus ad Moysen in deserto Sinai in tabernaculo fœderis, prima die mensis secundi, anno altero egressionis eorum ex \'gypto, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tollite summam universæ congregationis filiorum Israël per cognationes et domos suas, et nomina singulorum, quidquid sexus est masculini');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'a vigesimo anno et supra, omnium virorum fortium ex Israël, et numerabitis eos per turmas suas, tu et Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Eruntque vobiscum principes tribuum ac domorum in cognationibus suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'quorum ista sunt nomina: de Ruben, Elisur, filius Sedeur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'de Simeon, Salamiel filius Surisaddai;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'de Juda, Nahasson filius Aminadab;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'de Issachar, Nathanaël filius Suar;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'de Zabulon, Eliab filius Helon;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'filiorum autem Joseph, de Ephraim, Elisama filius Ammiud; de Manasse, Gamaliel filius Phadassur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'de Benjamin, Abidan filius Gedeonis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'de Dan, Ahiezer filius Ammisaddai;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'de Aser, Phegiel filius Ochran;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'de Gad, Eliasaph filius Duel;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'de Nephthali, Ahira filius Enan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Hi nobilissimi principes multitudinis per tribus et cognationes suas, et capita exercitus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'quos tulerunt Moyses et Aaron cum omni vulgi multitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'et congregaverunt primo die mensis secundi, recensentes eos per cognationes, et domos, ac familias, et capita, et nomina singulorum a vigesimo anno et supra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'sicut præceperat Dominus Moysi. Numeratique sunt in deserto Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'De Ruben primogenito Israëlis per generationes et familias ac domos suas, et nomina capitum singulorum, omne quod sexus est masculini a vigesimo anno et supra, procedentium ad bellum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'quadraginta sex millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'De filiis Simeon per generationes et familias ac domos cognationum suarum recensiti sunt per nomina et capita singulorum, omne quod sexus est masculini a vigesimo anno et supra, procedentium ad bellum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'quinquaginta novem millia trecenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'De filiis Gad per generationes et familias ac domos cognationum suarum recensiti sunt per nomina singulorum a viginti annis et supra, omnes qui ad bella procederent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'quadraginta quinque millia sexcenti quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'De filiis Juda per generationes et familias ac domos cognationum suarum, per nomina singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'recensiti sunt septuaginta quatuor millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'De filiis Issachar, per generationes et familias ac domos cognationum suarum, per nomina singulorum a vigesimo anno et supra, omnes qui ad bella procederent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'recensiti sunt quinquaginta quatuor millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'De filiis Zabulon per generationes et familias ac domos cognationum suarum recensiti sunt per nomina singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'quinquaginta septem millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'De filiis Joseph, filiorum Ephraim per generationes et familias ac domos cognationum suarum recensiti sunt per nomina singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'quadraginta millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Porro filiorum Manasse per generationes et familias ac domos cognationum suarum recensiti sunt per nomina singulorum a viginti annis et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'triginta duo millia ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'De filiis Benjamin per generationes et familias ac domos cognationum suarum recensiti sunt nominibus singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'triginta quinque millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'De filiis Dan per generationes et familias ac domos cognationum suarum recensiti sunt nominibus singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'sexaginta duo millia septingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'De filiis Aser per generationes et familias ac domos cognationum suarum recensiti sunt per nomina singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'quadraginta millia et mille quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'De filiis Nephthali per generationes et familias ac domos cognationum suarum recensiti sunt nominibus singulorum a vigesimo anno et supra, omnes qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'quinquaginta tria millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Hi sunt, quos numeraverunt Moyses et Aaron, et duodecim principes Israël, singulos per domos cognationum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Fueruntque omnis numerus filiorum Israël per domos et familias suas a vigesimo anno et supra, qui poterant ad bella procedere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'sexcenta tria millia virorum quingenti quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Levitæ autem in tribu familiarum suarum non sunt numerati cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Tribum Levi noli numerare, neque pones summam eorum cum filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sed constitue eos super tabernaculum testimonii et cuncta vasa ejus, et quidquid ad cæremonias pertinet. Ipsi portabunt tabernaculum et omnia utensilia ejus: et erunt in ministerio, ac per gyrum tabernaculi metabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Cum proficiscendum fuerit, deponent Levitæ tabernaculum; cum castrametandum, erigent. Quisquis externorum accesserit, occidetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Metabuntur autem castra filii Israël unusquisque per turmas et cuneos atque exercitum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Porro Levitæ per gyrum tabernaculi figent tentoria, ne fiat indignatio super multitudinem filiorum Israël, et excubabunt in custodiis tabernaculi testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Fecerunt ergo filii Israël juxta omnia quæ præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Singuli per turmas, signa, atque vexilla, et domos cognationum suarum, castrametabuntur filii Israël, per gyrum tabernaculi fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Ad orientem Judas figet tentoria per turmas exercitus sui: eritque princeps filiorum ejus Nahasson filius Aminadab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Et omnis de stirpe ejus summa pugnantium, septuaginta quatuor millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Juxta eum castrametati sunt de tribu Issachar, quorum princeps fuit Nathanaël filius Suar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Et omnis numerus pugnatorum ejus quinquaginta quatuor millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'In tribu Zabulon princeps fuit Eliab filius Helon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Omnis de stirpe ejus exercitus pugnatorum, quinquaginta septem millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Universi qui in castris Judæ enumerati sunt, fuerunt centum octoginta sex millia quadringenti: et per turmas suas primi egredientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'In castris filiorum Ruben ad meridianam plagam erit princeps Elisur filius Sedeur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Et cunctus exercitus pugnatorum ejus qui numerati sunt, quadraginta sex millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Juxta eum castrametati sunt de tribu Simeon: quorum princeps fuit Salamiel filius Surisaddai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Et cunctus exercitus pugnatorum ejus qui numerati sunt, quinquaginta novem millia trecenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'In tribu Gad princeps fuit Eliasaph filius Duel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Et cunctus exercitus pugnatorum ejus, qui numerati sunt, quadraginta quinque millia sexcenti quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Omnes qui recensiti sunt in castris Ruben, centum quinquaginta millia et mille quadringenti quinquaginta per turmas suas: in secundo loco proficiscentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Levabitur autem tabernaculum testimonii per officia Levitarum, et turmas eorum: quomodo erigetur, ita et deponetur. Singuli per loca et ordines suos proficiscentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Ad occidentalem plagam erunt castra filiorum Ephraim, quorum princeps fuit Elisama filius Ammiud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Cunctus exercitus pugnatorum ejus, qui numerati sunt, quadraginta millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Et cum eis tribus filiorum Manasse, quorum princeps fuit Gamaliel filius Phadassur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Cunctusque exercitus pugnatorum ejus, qui numerati sunt, triginta duo millia ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'In tribu filiorum Benjamin princeps fuit Abidan filius Gedeonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Et cunctus exercitus pugnatorum ejus, qui recensiti sunt, triginta quinque millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Omnes qui numerati sunt in castris Ephraim, centum octo millia centum per turmas suas: tertii proficiscentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Ad aquilonis partem castrametati sunt filii Dan: quorum princeps fuit Ahiezer filius Ammisaddai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Cunctus exercitus pugnatorum ejus, qui numerati sunt, sexaginta duo millia septingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Juxta eum fixere tentoria de tribu Aser: quorum princeps fuit Phegiel filius Ochran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Cunctus exercitus pugnatorum ejus, qui numerati sunt, quadraginta millia et mille quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'De tribu filiorum Nephthali princeps fuit Ahira filius Enan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Cunctus exercitus pugnatorum ejus, quinquaginta tria millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Omnes qui numerati sunt in castris Dan, fuerunt centum quinquaginta septem millia sexcenti: et novissimi proficiscentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Hic numerus filiorum Israël, per domos cognationum suarum et turmas divisi exercitus, sexcenta tria millia quingenti quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Levitæ autem non sunt numerati inter filios Israël: sic enim præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Feceruntque filii Israël juxta omnia quæ mandaverat Dominus. Castrametati sunt per turmas suas, et profecti per familias ac domos patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Hæ sunt generationes Aaron et Moysi in die qua locutus est Dominus ad Moysen in monte Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Et hæc nomina filiorum Aaron: primogenitus ejus Nadab, deinde Abiu, et Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Hæc nomina filiorum Aaron sacerdotum qui uncti sunt, et quorum repletæ et consecratæ manus ut sacerdotio fungerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mortui sunt enim Nadab et Abiu cum offerrent ignem alienum in conspectu Domini in deserto Sinai, absque liberis: functique sunt sacerdotio Eleazar et Ithamar coram Aaron patre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Applica tribum Levi, et fac stare in conspectu Aaron sacerdotis ut ministrent ei, et excubent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'et observent quidquid ad cultum pertinet multitudinis coram tabernaculo testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'et custodiant vasa tabernaculi, servientes in ministerio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Dabisque dono Levitas');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron et filiis ejus, quibus traditi sunt a filiis Israël. Aaron autem et filios ejus constitues super cultum sacerdotii. Externus, qui ad ministrandum accesserit, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Ego tuli Levitas a filiis Israël pro omni primogenito, qui aperit vulvam in filiis Israël, eruntque Levitæ mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Meum est enim omne primogenitum: ex quo percussi primogenitos in terra \'gypti, sanctificavi mihi quidquid primum nascitur in Israël: ab homine usque ad pecus, mei sunt. Ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Locutusque est Dominus ad Moysen in deserto Sinai, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Numera filios Levi per domos patrum suorum et familias, omnem masculum ab uno mense et supra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Numeravit Moyses, ut præceperat Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'et inventi sunt filii Levi per nomina sua, Gerson et Caath et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Filii Gerson: Lebni et Semei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Filii Caath: Amram et Jesaar, Hebron et Oziel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Filii Merari: Moholi et Musi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gerson fuere familiæ duæ, Lebnitica, et Semeitica:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'quarum numeratus est populus sexus masculini ab uno mense et supra, septem millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Hi post tabernaculum metabuntur ad occidentem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'sub principe Eliasaph filio Laël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Et habebunt excubias in tabernaculo fœderis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'ipsum tabernaculum et operimentum ejus, tentorium quod trahitur ante fores tecti fœderis, et cortinas atrii: tentorium quoque quod appenditur in introitu atrii tabernaculi, et quidquid ad ritum altaris pertinet, funes tabernaculi et omnia utensilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Cognatio Caath habebit populos Amramitas et Jesaaritas et Hebronitas et Ozielitas. Hæ sunt familiæ Caathitarum recensitæ per nomina sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Omnes generis masculini ab uno mense et supra, octo millia sexcenti habebunt excubias sanctuarii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'et castrametabuntur ad meridianam plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Princepsque eorum erit Elisaphan filius Oziel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'et custodient arcam, mensamque et candelabrum, altaria et vasa sanctuarii, in quibus ministratur, et velum, cunctamque hujuscemodi supellectilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Princeps autem principum Levitarum Eleazar filius Aaron sacerdotis, erit super excubitores custodiæ sanctuarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'At vero de Merari erunt populi Moholitæ et Musitæ recensiti per nomina sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'omnes generis masculini ab uno mense et supra, sex millia ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Princeps eorum Suriel filius Abihaiel: in plaga septentrionali castrametabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Erunt sub custodia eorum tabulæ tabernaculi et vectes, et columnæ ac bases earum, et omnia quæ ad cultum hujuscemodi pertinent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'columnæque atrii per circuitum cum basibus suis, et paxilli cum funibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Castrametabuntur ante tabernaculum fœderis, id est, ad orientalem plagam, Moyses et Aaron cum filiis suis, habentes custodiam sanctuarii in medio filiorum Israël. Quisquis alienus accesserit, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Omnes Levitæ, quos numeraverunt Moyses et Aaron juxta præceptum Domini per familias suas in genere masculino a mense uno et supra, fuerunt viginti duo millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Et ait Dominus ad Moysen: Numera primogenitos sexus masculini de filiis Israël ab uno mense et supra, et habebis summam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Tollesque Levitas mihi pro omni primogenito filiorum Israël: ego sum Dominus: et pecora eorum pro universis primogenitis pecorum filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Recensuit Moyses, sicut præceperat Dominus, primogenitos filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'et fuerunt masculi per nomina sua, a mense uno et supra, viginti duo millia ducenti septuaginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Tolle Levitas pro primogenitis filiorum Israël, et pecora Levitarum pro pecoribus eorum, eruntque Levitæ mei. Ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'In pretio autem ducentorum septuaginta trium, qui excedunt numerum Levitarum de primogenitis filiorum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'accipies quinque siclos per singula capita ad mensuram sanctuarii (siclus habet viginti obolos):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'dabisque pecuniam Aaron et filiis ejus pretium eorum qui supra sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Tulit igitur Moyses pecuniam eorum, qui fuerant amplius, et quos redemerant a Levitis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'pro primogenitis filiorum Israël, mille trecentorum sexaginta quinque siclorum juxta pondus sanctuarii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'et dedit eam Aaron et filiis ejus juxta verbum quod præceperat sibi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Tolle summam filiorum Caath de medio Levitarum per domos et familias suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'a trigesimo anno et supra, usque ad quinquagesimum annum, omnium qui ingrediuntur ut stent et ministrent in tabernaculo fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Hic est cultus filiorum Caath: tabernaculum fœderis, et Sanctum sanctorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'ingredientur Aaron et filii ejus, quando movenda sunt castra, et deponent velum quod pendet ante fores, involventque eo arcam testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'et operient rursum velamine janthinarum pellium, extendentque desuper pallium totum hyacinthinum, et inducent vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Mensam quoque propositionis involvent hyacinthino pallio, et ponent cum ea thuribula et mortariola, cyathos et crateras ad liba fundenda: panes semper in ea erunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'extendentque desuper pallium coccineum, quod rursum operient velamento janthinarum pellium, et inducent vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Sument et pallium hyacinthinum, quo operient candelabrum cum lucernis et forcipibus suis et emunctoriis et cunctis vasis olei, quæ ad concinnandas lucernas necessaria sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'et super omnia ponent operimentum janthinarum pellium, et inducent vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Necnon et altare aureum involvent hyacinthino vestimento, et extendent desuper operimentum janthinarum pellium, inducentque vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Omnia vasa, quibus ministratur in sanctuario, involvent hyacinthino pallio, et extendent desuper operimentum janthinarum pellium, inducentque vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Sed et altare mundabunt cinere, et involvent illud purpureo vestimento,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'ponentque cum eo omnia vasa, quibus in ministerio ejus utuntur, id est, ignium receptacula, fuscinulas ac tridentes, uncinos et batilla. Cuncta vasa altaris operient simul velamine janthinarum pellium, et inducent vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Cumque involverint Aaron et filii ejus sanctuarium et omnia vasa ejus in commotione castrorum, tunc intrabunt filii Caath ut portent involuta: et non tangent vasa sanctuarii, ne moriantur. Ista sunt onera filiorum Caath in tabernaculo fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'super quos erit Eleazar filius Aaron sacerdotis, ad cujus curam pertinet oleum ad concinnandas lucernas, et compositionis incensum, et sacrificium, quod semper offertur, et oleum unctionis, et quidquid ad cultum tabernaculi pertinet, omniumque vasorum, quæ in sanctuario sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Nolite perdere populum Caath de medio Levitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sed hoc facite eis, ut vivant, et non moriantur, si tetigerint Sancta sanctorum. Aaron et filii ejus intrabunt, ipsique disponent opera singulorum, et divident quid portare quis debeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Alii nulla curiositate videant quæ sunt in sanctuario priusquam involvantur, alioquin morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Tolle summam etiam filiorum Gerson per domos ac familias et cognationes suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'a triginta annis et supra, usque ad annos quinquaginta. Numera omnes qui ingrediuntur et ministrant in tabernaculo fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Hoc est officium familiæ Gersonitarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'ut portent cortinas tabernaculi et tectum fœderis, operimentum aliud, et super omnia velamen janthinum tentoriumque quod pendet in introitu tabernaculi fœderis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'cortinas atrii, et velum in introitu quod est ante tabernaculum. Omnia quæ ad altare pertinent, funiculos, et vasa ministerii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'jubente Aaron et filiis ejus, portabunt filii Gerson: et scient singuli cui debeant oneri mancipari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Hic est cultus familiæ Gersonitarum in tabernaculo fœderis, eruntque sub manu Ithamar filii Aaron sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Filios quoque Merari per familias et domos patrum suorum recensebis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'a triginta annis et supra, usque ad annos quinquaginta, omnes qui ingrediuntur ad officium ministerii sui et cultum fœderis testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Hæc sunt onera eorum: portabunt tabulas tabernaculi et vectes ejus, columnas ac bases earum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'columnas quoque atrii per circuitum cum basibus et paxillis et funibus suis. Omnia vasa et supellectilem ad numerum accipient, sicque portabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Hoc est officium familiæ Meraritarum et ministerium in tabernaculo fœderis: eruntque sub manu Ithamar filii Aaron sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Recensuerunt igitur Moyses et Aaron et principes synagogæ filios Caath per cognationes et domos patrum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'a triginta annis et supra, usque ad annum quinquagesimum, omnes qui ingrediuntur ad ministerium tabernaculi fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'et inventi sunt duo millia septingenti quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Hic est numerus populi Caath qui intrant tabernaculum fœderis: hos numeravit Moyses et Aaron juxta sermonem Domini per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Numerati sunt et filii Gerson per cognationes et domos patrum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'a triginta annos et supra, usque ad quinquagesimum annum, omnes qui ingrediuntur ut ministrent in tabernaculo fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'et inventi sunt duo millia sexcenti triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Hic est populus Gersonitarum, quos numeraverunt Moyses et Aaron juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Numerati sunt et filii Merari per cognationes et domos patrum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'a triginta annis et supra, usque ad annum quinquagesimum, omnes qui ingrediuntur ad explendos ritus tabernaculi fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'et inventi sunt tria millia ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Hic est numerus filiorum Merari, quos recensuerunt Moyses et Aaron juxta imperium Domini per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Omnes qui recensiti sunt de Levitis, et quos recenseri fecit ad nomen Moyses et Aaron, et principes Israël per cognationes et domos patrum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'a triginta annis et supra, usque ad annum quinquagesimum, ingredientes ad ministerium tabernaculi, et onera portanda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'fuerunt simul octo millia quingenti octoginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Juxta verbum Domini recensuit eos Moyses, unumquemque juxta officium et onera sua, sicut præceperat ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Præcipe filiis Israël, ut ejiciant de castris omnem leprosum, et qui semine fluit, pollutusque est super mortuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'tam masculum quam feminam ejicite de castris, ne contaminent ea cum habitaverint vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Feceruntque ita filii Israël, et ejecerunt eos extra castra, sicut locutus erat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Loquere ad filios Israël: Vir, sive mulier, cum fecerint ex omnibus peccatis, quæ solent hominibus accidere, et per negligentiam transgressi fuerint mandatum Domini, atque deliquerint,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'confitebuntur peccatum suum, et reddent ipsum caput, quintamque partem desuper, ei in quem peccaverint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Sin autem non fuerit qui recipiat, dabunt Domino, et erit sacerdotis, excepto ariete, qui offertur pro expiatione, ut sit placabilis hostia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Omnes quoque primitiæ, quas offerunt filii Israël, ad sacerdotem pertinent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'et quidquid in sanctuarium offertur a singulis, et traditur manibus sacerdotis, ipsius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Loquere ad filios Israël, et dices ad eos: Vir cujus uxor erraverit, maritumque contemnens');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'dormierit cum altero viro, et hoc maritus deprehendere non quiverit, sed latet adulterium, et testibus argui non potest, quia non est inventa in stupro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'si spiritus zelotypiæ concitaverit virum contra uxorem suam, quæ vel polluta est, vel falsa suspicione appetitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'adducet eam ad sacerdotem, et offeret oblationem pro illa, decimam partem sati farinæ hordeaceæ: non fundet super eam oleum, nec imponet thus: quia sacrificium zelotypiæ est, et oblatio investigans adulterium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Offeret igitur eam sacerdos, et statuet coram Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'assumetque aquam sanctam in vase fictili, et pauxillum terræ de pavimento tabernaculi mittet in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Cumque steterit mulier in conspectu Domini, discooperiet caput ejus, et ponet super manus illius sacrificium recordationis, et oblationem zelotypiæ: ipse autem tenebit aquas amarissimas, in quibus cum execratione maledicta congessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Adjurabitque eam, et dicet: Si non dormivit vir alienus tecum, et si non polluta es deserto mariti thoro, non te nocebunt aquæ istæ amarissimæ, in quas maledicta congessi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Sin autem declinasti a viro tuo, atque polluta es, et concubuisti cum altero viro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'his maledictionibus subjacebis: det te Dominus in maledictionem, exemplumque cunctorum in populo suo: putrescere faciat femur tuum, et tumens uterus tuus disrumpatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Ingrediantur aquæ maledictæ in ventrem tuum, et utero tumescente putrescat femur. Et respondebit mulier: Amen, amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Scribetque sacerdos in libello ista maledicta, et delebit ea aquis amarissimis, in quas maledicta congessit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'et dabit ei bibere. Quas cum exhauserit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'tollet sacerdos de manu ejus sacrificium zelotypiæ, et elevabit illud coram Domino, imponetque illud super altare, ita dumtaxat ut prius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'pugillum sacrificii tollat de eo, quod offertur, et incendat super altare: et sic potum det mulieri aquas amarissimas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Quas cum biberit, si polluta est, et contempto viro adulterii rea, pertransibunt eam aquæ maledictionis, et inflato ventre, computrescet femur: eritque mulier in maledictionem, et in exemplum omni populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Quod si polluta non fuerit, erit innoxia, et faciet liberos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ista est lex zelotypiæ. Si declinaverit mulier a viro suo, et si polluta fuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'maritusque zelotypiæ spiritu concitatus adduxerit eam in conspectu Domini, et fecerit ei sacerdos juxta omnia quæ scripta sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'maritus absque culpa erit, et illa recipiet iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Loquere ad filios Israël, et dices ad eos: Vir, sive mulier, cum fecerint votum ut sanctificentur, et se voluerint Domino consecrare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'a vino, et omni quod inebriare potest, abstinebunt. Acetum ex vino, et ex qualibet alia potione, et quidquid de uva exprimitur, non bibent: uvas recentes siccasque non comedent');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'cunctis diebus quibus ex voto Domino consecrantur: quidquid ex vinea esse potest, ab uva passa usque ad acinum non comedent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Omni tempore separationis suæ novacula non transibit per caput ejus usque ad completum diem, quo Domino consecratur. Sanctus erit, crescente cæsarie capitis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Omni tempore consecrationis suæ, super mortuum non ingredietur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'nec super patris quidem et matris et fratris sororisque funere contaminabitur, quia consecratio Dei sui super caput ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Omnibus diebus separationis suæ sanctus erit Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Sin autem mortuus fuerit subito quispiam coram eo, polluetur caput consecrationis ejus: quod radet illico in eadem die purgationis suæ, et rursum septima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'In octava autem die offeret duos turtures, vel duos pullos columbæ sacerdoti in introitu fœderis testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Facietque sacerdos unum pro peccato, et alterum in holocaustum, et deprecabitur pro eo, quia peccavit super mortuo: sanctificabitque caput ejus in die illo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'et consecrabit Domino dies separationis illius, offerens agnum anniculum pro peccato: ita tamen ut dies priores irriti fiant, quoniam polluta est sanctificatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Ista est lex consecrationis. Cum dies, quos ex voto decreverat, complebuntur, adducet eum ad ostium tabernaculi fœderis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'et offeret oblationes ejus Domino, agnum anniculum immaculatum in holocaustum, et ovem anniculam immaculatam pro peccato, et arietem immaculatum, hostiam pacificam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'canistrum quoque panum azymorum qui conspersi sint oleo, et lagana absque fermento uncta oleo, ac libamina singulorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'quæ offeret sacerdos coram Domino, et faciet tam pro peccato, quam in holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Arietem vero immolabit hostiam pacificam Domino, offerens simul canistrum azymorum, et libamenta quæ ex more debentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Tunc radetur nazaræus ante ostium tabernaculi fœderis cæsarie consecrationis suæ: tolletque capillos ejus, et ponet super ignem, qui est suppositus sacrificio pacificorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'et armum coctum arietis, tortamque absque fermento unam de canistro, et laganum azymum unum, et tradet in manus nazaræi, postquam rasum fuerit caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Susceptaque rursum ab eo, elevabit in conspectu Domini: et sanctificata sacerdotis erunt, sicut pectusculum, quod separari jussum est, et femur. Post hæc, potest bibere nazaræus vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Ista est lex nazaræi, cum voverit oblationem suam Domino tempore consecrationis suæ, exceptis his, quæ invenerit manus ejus: juxta quod mente devoverat, ita faciet ad perfectionem sanctificationis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Loquere Aaron et filiis ejus: Sic benedicetis filiis Israël, et dicetis eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Benedicat tibi Dominus, et custodiat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Ostendat Dominus faciem suam tibi, et misereatur tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Convertat Dominus vultum suum ad te, et det tibi pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Invocabuntque nomen meum super filios Israël, et ego benedicam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Factum est autem in die qua complevit Moyses tabernaculum, et erexit illud, unxitque et sanctificavit cum omnibus vasis suis, altare similiter et omnia vasa ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'obtulerunt principes Israël et capita familiarum, qui erant per singulas tribus, præfectique eorum, qui numerati fuerant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'munera coram Domino sex plaustra tecta cum duodecim bobus. Unum plaustrum obtulere duo duces, et unum bovem singuli, obtuleruntque ea in conspectu tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Ait autem Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Suscipe ab eis ut serviant in ministerio tabernaculi, et trades ea Levitis juxta ordinem ministerii sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Itaque cum suscepisset Moyses plaustra et boves, tradidit eos Levitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Duo plaustra et quatuor boves dedit filiis Gerson, juxta id quod habebant necessarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Quatuor alia plaustra et octo boves dedit filiis Merari secundum officia et cultum suum, sub manu Ithamar filii Aaron sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Filiis autem Caath non dedit plaustra et boves: quia in sanctuario serviunt, et onera propriis portant humeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Igitur obtulerunt duces in dedicationem altaris, die qua unctum est, oblationem suam ante altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Dixitque Dominus ad Moysen: Singuli duces per singulos dies offerant munera in dedicationem altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Primo die obtulit oblationem suam Nahasson filius Aminadab de tribu Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'fueruntque in ea acetabulum argenteum pondo centum triginta siclorum, phiala argentea habens septuaginta siclos, juxta pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'mortariolum ex decem siclis aureis plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'et in sacrificio pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc est oblatio Nahasson filii Aminadab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Secundo die obtulit Nathanaël filius Suar, dux de tribu Issachar,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, juxta pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'mortariolum aureum habens decem siclos plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'et in sacrificio pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Nathanaël filii Suar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Tertio die princeps filiorum Zabulon, Eliab filius Helon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'mortariolum aureum appendens decem siclos, plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
