INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'et in sacrificio pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc est oblatio Eliab filii Helon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Die quarto princeps filiorum Ruben, Elisur filius Sedeur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificum:');
