INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'et in hostias pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Elisur filii Sedeur.');
