INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Die octavo, princeps filiorum Manasse, Gamaliel filius Phadassur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'mortariolum aureum appendens decem siclos, plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'et in hostias pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Gamaliel filii Phadassur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Die nono princeps filiorum Benjamin, Abidan filius Gedeonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificum:');
