INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'et in hostias pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Abidan filii Gedeonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Die decimo princeps filiorum Dan, Ahiezer filius Ammisaddai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'mortariolum aureum appendens decem siclos, plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'hircumque pro peccato:');
