INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Die undecimo princeps filiorum Aser, Phegiel filius Ochran,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila conspersa oleo in sacrificum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'mortariolum aureum appendens decem siclos, plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'et in hostias pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Phegiel filii Ochran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Die duodecimo princeps filiorum Nephthali, Ahira filius Enan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'obtulit acetabulum argenteum appendens centum triginta siclos, phialam argenteam habentem septuaginta siclos, ad pondus sanctuarii, utrumque plenum simila oleo conspersa in sacrificum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'mortariolum aureum appendens decem siclos, plenum incenso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'bovem de armento, et arietem, et agnum anniculum in holocaustum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'et in hostias pacificorum boves duos, arietes quinque, hircos quinque, agnos anniculos quinque. Hæc fuit oblatio Ahira filii Enan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Hæc in dedicatione altaris oblata sunt a principibus Israël, in die qua consecratum est: acetabula argentea duodecim: phialæ argenteæ duodecim: mortariola aurea duodecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'ita ut centum triginta siclos argenti haberet unum acetabulum, et septuaginta siclos haberet una phiala: id est, in commune vasorum omnium ex argento sicli duo millia quadringenti, pondere sanctuarii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'mortariola aurea duodecim plena incenso, denos siclos appendentia pondere sanctuarii: id est, simul auri sicli centum viginti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'boves de armento in holocaustum duodecim, arietes duodecim, agni anniculi duodecim, et libamenta eorum: hirci duodecim pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'In hostias pacificorum, boves viginti quatuor, arietes sexaginta, hirci sexaginta, agni anniculi sexaginta. Hæc oblata sunt in dedicatione altaris, quando unctum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Cumque ingrederetur Moyses tabernaculum fœderis, ut consuleret oraculum, audiebat vocem loquentis ad se de propitiatorio quod erat super arcam testimonii inter duos cherubim, unde et loquebatur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Loquere Aaron, et dices ad eum: Cum posueris septem lucernas, candelabrum in australi parte erigatur. Hoc igitur præcipe ut lucernæ contra boream e regione respiciant ad mensam panum propositionis, contra eam partem, quam candelabrum respicit, lucere debebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Fecitque Aaron, et imposuit lucernas super candelabrum, ut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Hæc autem erat factura candelabri, ex auro ductili, tam medius stipes, quam cuncta quæ ex utroque calamorum latere nascebantur: juxta exemplum quod ostendit Dominus Moysi, ita operatus est candelabrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Tolle Levitas de medio filiorum Israël, et purificabis eos');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'juxta hunc ritum: aspergantur aqua lustrationis, et radant omnes pilos carnis suæ. Cumque laverint vestimenta sua, et mundati fuerint,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'tollent bovem de armentis, et libamentum ejus similam oleo conspersam: bovem autem alterum de armento tu accipies pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'et applicabis Levitas coram tabernaculo fœderis, convocata omni multitudine filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Cumque Levitæ fuerint coram Domino, ponent filii Israël manus suas super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Et offeret Aaron Levitas, munus in conspectu Domini a filiis Israël, ut serviant in ministerio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Levitæ quoque ponent manus suas super capita boum, e quibus unum facies pro peccato, et alterum in holocaustum Domini, ut depreceris pro eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Statuesque Levitas in conspectu Aaron et filiorum ejus, et consecrabis oblatos Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'ac separabis de medio filiorum Israël, ut sint mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Et postea ingredientur tabernaculum fœderis, ut serviant mihi. Sicque purificabis et consecrabis eos in oblationem Domini: quoniam dono donati sunt mihi a filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Pro primogenitis quæ aperiunt omnem vulvam in Israël, accepi eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Mea sunt enim omnia primogenita filiorum Israël, tam ex hominibus quam ex jumentis. Ex die quo percussi omne primogenitum in terra \'gypti, sanctificavi eos mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'et tuli Levitas pro cunctis primogenitis filiorum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'tradidique eos dono Aaron et filiis ejus de medio populi, ut serviant mihi pro Israël in tabernaculo fœderis, et orent pro eis ne sit in populo plaga, si ausi fuerint accedere ad sanctuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Feceruntque Moyses et Aaron et omnis multitudo filiorum Israël super Levitas quæ præceperat Dominus Moysi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'purificatique sunt, et laverunt vestimenta sua. Elevavitque eos Aaron in conspectu Domini, et oravit pro eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'ut purificati ingrederentur ad officia sua in tabernaculum fœderis coram Aaron et filiis ejus. Sicut præceperat Dominus Moysi de Levitis, ita factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Hæc est lex Levitarum: a viginti quinque annis et supra, ingredientur ut ministrent in tabernaculo fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Cumque quinquagesimum annum ætatis impleverint, servire cessabunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'eruntque ministri fratrum suorum in tabernaculo fœderis, ut custodiant quæ sibi fuerunt commendata: opera autem ipsa non faciant. Sic dispones Levitis in custodiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Locutus est Dominus ad Moysen in deserto Sinai anno secundo, postquam egressi sunt de terra \'gypti, mense primo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Faciant filii Israël Phase in tempore suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'quartadecima die mensis hujus ad vesperam, juxta omnes cæremonias et justificationes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Præcepitque Moyses filiis Israël ut facerent Phase.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Qui fecerunt tempore suo, quartadecima die mensis ad vesperam, in monte Sinai. Juxta omnia quæ mandaverat Dominus Moysi, fecerunt filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Ecce autem quidam immundi super anima hominis, qui non poterant facere Phase in die illo, accedentes ad Moysen et Aaron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'dixerunt eis: Immundi sumus super anima hominis: quare fraudamur ut non valeamus oblationem offerre Domino in tempore suo inter filios Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Quibus respondit Moyses: State ut consulam quid præcipiat Dominus de vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Loquere filiis Israël: Homo, qui fuerit immundus super anima, sive in via procul in gente vestra, faciat Phase Domino');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'in mense secundo, quartadecima die mensis ad vesperam. Cum azymis et lactucis agrestibus comedent illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'non relinquent ex eo quippiam usque mane, et os ejus non confringent: omnem ritum Phase observabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Si quis autem et mundus est, et in itinere non fuit, et tamen non fecit Phase, exterminabitur anima illa de populis suis, quia sacrificium Domino non obtulit tempore suo: peccatum suum ipse portabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Peregrinus quoque et advena si fuerint apud vos, facient Phase Domino juxta cæremonias et justificationes ejus. Præceptum idem erit apud vos tam advenæ quam indigenæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Igitur die qua erectum est tabernaculum, operuit illud nubes. A vespere autem super tentorium erat quasi species ignis usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Sic fiebat jugiter: per diem operiebat illud nubes, et per noctem quasi species ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Cumque ablata fuisset nubes, quæ tabernaculum protegebat, tunc proficiscebantur filii Israël: et in loco ubi stetisset nubes, ibi castrametabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Ad imperium Domini proficiscebantur, et ad imperium illius figebant tabernaculum. Cunctis diebus quibus stabat nubes super tabernaculum, manebant in eodem loco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'et si evenisset ut multo tempore maneret super illud, erant filii Israël in excubiis Domini, et non proficiscebantur');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'quot diebus fuisset nubes super tabernaculum. Ad imperium Domini erigebant tentoria, et ad imperium illius deponebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Si fuisset nubes a vespere usque mane, et statim diluculo tabernaculum reliquisset, proficiscebantur: et si post diem et noctem recessisset, dissipabant tentoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Si vero biduo aut uno mense vel longiori tempore fuisset super tabernaculum, manebant filii Israël in eodem loco, et non proficiscebantur: statim autem ut recessisset, movebant castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Per verbum Domini figebant tentoria, et per verbum illius proficiscebantur: erantque in excubiis Domini juxta imperium ejus per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Fac tibi duas tubas argenteas ductiles, quibus convocare possis multitudinem quando movenda sunt castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Cumque increpueris tubis, congregabitur ad te omnis turba ad ostium tabernaculi fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Si semel clangueris, venient ad te principes, et capita multitudinis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Si autem prolixior atque concisus clangor increpuerit, movebunt castra primi qui sunt ad orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'In secundo autem sonitu et pari ululatu tubæ, levabunt tentoria qui habitant ad meridiem; et juxta hunc modum reliqui facient, ululantibus tubis in profectionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Quando autem congregandus est populus, simplex tubarum clangor erit, et non concise ululabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Filii autem Aaron sacerdotes clangent tubis: eritque hoc legitimum sempiternum in generationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Si exieritis ad bellum de terra vestra contra hostes qui dimicant adversum vos, clangetis ululantibus tubis, et erit recordatio vestri coram Domino Deo vestro, ut eruamini de manibus inimicorum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Siquando habebitis epulum, et dies festos, et calendas, canetis tubis super holocaustis, et pacificis victimis, ut sint vobis in recordationem Dei vestri. Ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Anno secundo, mense secundo, vigesima die mensis, elevata est nubes de tabernaculo fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'profectique sunt filii Israël per turmas suas de deserto Sinai, et recubuit nubes in solitudine Pharan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Moveruntque castra primi juxta imperium Domini in manu Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Filii Juda per turmas suas: quorum princeps erat Nahasson filius Aminadab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'In tribu filiorum Issachar fuit princeps Nathanaël filius Suar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'In tribu Zabulon erat princeps Eliab filius Helon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Depositumque est tabernaculum, quod portantes egressi sunt filii Gerson et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Profectique sunt et filii Ruben, per turmas et ordinem suum: quorum princeps erat Helisur filius Sedeur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'In tribu autem filiorum Simeon, princeps fuit Salamiel filius Surisaddai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Porro in tribu Gad erat princeps Eliasaph filius Duel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Profectique sunt et Caathitæ portantes sanctuarium. Tamdiu tabernaculum portabatur, donec venirent ad erectionis locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Moverunt castra et filii Ephraim per turmas suas, in quorum exercitu princeps erat Elisama filius Ammiud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'In tribu autem filiorum Manasse princeps fuit Gamaliel filius Phadassur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Et in tribu Benjamin erat dux Abidan filius Gedeonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Novissimi castrorum omnium profecti sunt filii Dan per turmas suas, in quorum exercitu princeps fuit Ahiezer filius Ammisaddai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'In tribu autem filiorum Aser erat princeps Phegiel filius Ochran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Et in tribu filiorum Nephthali princeps fuit Ahira filius Enan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Hæc sunt castra, et profectiones filiorum Israël per turmas suas quando egrediebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Dixitque Moyses Hobab filio Raguel Madianitæ, cognato suo: Proficiscimur ad locum quem Dominus daturus est nobis: veni nobiscum, ut benefaciamus tibi, quia Dominus bona promisit Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Cui ille respondit: Non vadam tecum, sed revertar in terram meam, in qua natus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Et ille: Noli, inquit, nos relinquere: tu enim nosti in quibus locis per desertum castra ponere debeamus, et eris ductor noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Cumque nobiscum veneris, quidquid optimum fuerit ex opibus, quas nobis traditurus est Dominus, dabimus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Profecti sunt ergo de monte Domini viam trium dierum, arcaque fœderis Domini præcedebat eos, per dies tres providens castrorum locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Nubes quoque Domini super eos erat per diem cum incederent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Cumque elevaretur arca, dicebat Moyses: Surge, Domine, et dissipentur inimici tui, et fugiant qui oderunt te, a facie tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Cum autem deponeretur, aiebat: Revertere, Domine, ad multitudinem exercitus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Interea ortum est murmur populi, quasi dolentium pro labore, contra Dominum. Quod cum audisset Dominus, iratus est. Et accensus in eos ignis Domini, devoravit extremam castrorum partem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Cumque clamasset populus ad Moysen, oravit Moyses ad Dominum, et absorptus est ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Vocavitque nomen loci illius, Incensio: eo quod incensus fuisset contra eos ignis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Vulgus quippe promiscuum, quod ascenderat cum eis, flagravit desiderio, sedens et flens, junctis sibi pariter filiis Israël, et ait: Quis dabit nobis ad vescendum carnes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'recordamur piscium quos comedebamus in \'gypto gratis: in mentem nobis veniunt cucumeres, et pepones, porrique, et cæpe, et allia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Anima nostra arida est: nihil aliud respiciunt oculi nostri nisi man.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Erat autem man quasi semen coriandri, coloris bdellii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Circuibatque populus, et colligens illud, frangebat mola, sive terebat in mortario, coquens in olla, et faciens ex eo tortulas saporis quasi panis oleati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Cumque descenderet nocte super castra ros, descendebat pariter et man.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Audivit ergo Moyses flentem populum per familias, singulos per ostia tentorii sui. Iratusque est furor Domini valde: sed et Moysi intoleranda res visa est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'et ait ad Dominum: Cur afflixisti servum tuum? quare non invenio gratiam coram te? et cur imposuisti pondus universi populi hujus super me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Numquid ego concepi omnem hanc multitudinem, vel genui eam, ut dicas mihi: Porta eos in sinu tuo sicut portare solet nutrix infantulum, et defer in terram, pro qua jurasti patribus eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Unde mihi carnes ut dem tantæ multitudini? flent contra me, dicentes: Da nobis carnes ut comedamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Non possum solus sustinere omnem hunc populum, quia gravis est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Sin aliter tibi videtur, obsecro ut interficias me, et inveniam gratiam in oculis tuis, ne tantis afficiar malis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Et dixit Dominus ad Moysen: Congrega mihi septuaginta viros de senibus Israël, quos tu nosti quod senes populi sint ac magistri: et duces eos ad ostium tabernaculi fœderis, faciesque ibi stare tecum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'ut descendam et loquar tibi: et auferam de spiritu tuo, tradamque eis, ut sustentent tecum onus populi, et non tu solus graveris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Populo quoque dices: Sanctificamini (cras comedetis carnes: ego enim audivi vos dicere: Quis dabit nobis escas carnium? bene nobis erat in \'gypto), ut det vobis Dominus carnes, et comedatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'non uno die, nec duobus, vel quinque aut decem, nec viginti quidem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'sed usque ad mensem dierum, donec exeat per nares vestras, et vertatur in nauseam, eo quod repuleritis Dominum, qui in medio vestri est, et fleveritis coram eo, dicentes: Quare egressi sumus ex \'gypto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Et ait Moyses: Sexcenta millia peditum hujus populi sunt: et tu dicis: Dabo eis esum carnium mense integro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'numquid ovium et boum multitudo cædetur, ut possit sufficere ad cibum? vel omnes pisces maris in unum congregabuntur, ut eos satient?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Cui respondit Dominus: Numquid manus Domini invalida est? jam nunc videbis utrum meus sermo opere compleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Venit igitur Moyses, et narravit populo verba Domini, congregans septuaginta viros de senibus Israël, quos stare fecit circa tabernaculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Descenditque Dominus per nubem, et locutus est ad eum, auferens de spiritu qui erat in Moyse, et dans septuaginta viris. Cumque requievisset in eis spiritus, prophetaverunt, nec ultra cessaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Remanserat autem in castris duo viri, quorum unus vocabatur Eldad, et alter Medad, super quos requievit spiritus. Nam et ipsi descripti fuerant, et non exierant ad tabernaculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Cumque prophetarent in castris, cucurrit puer, et nuntiavit Moysi, dicens: Eldad et Medad prophetant in castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Statim Josue filius Nun, minister Moysi, et electus e pluribus, ait: Domine mi Moyses, prohibe eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'At ille: Quid, inquit æmularis pro me? quis tribuat ut omnis populus prophetet, et det eis Dominus spiritum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Reversusque est Moyses, et majores natu Israël in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Ventus autem egrediens a Domino, arreptans trans mare coturnices detulit, et demisit in castra itinere quantum uno die confici potest, ex omni parte castrorum per circuitum, volabantque in aëre duobus cubitis altitudine super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Surgens ergo populus toto die illo, et nocte, ac die altero, congregavit coturnicum: qui parum, decem coros: et siccaverunt eas per gyrum castrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Adhuc carnes erant in dentibus eorum, nec defecerat hujuscemodi cibus: et ecce furor Domini concitatus in populum, percussit eum plaga magna nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Vocatusque est ille locus, Sepulchra concupiscentiæ: ibi enim sepelierunt populum qui desideraverat. Egressi autem de Sepulchris concupiscentiæ, venerunt in Haseroth, et manserunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Locutaque est Maria et Aaron contra Moysen propter uxorem ejus \'thiopissam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'et dixerunt: Num per solum Moysen locutus est Dominus? nonne et nobis similiter est locutus? Quod cum audisset Dominus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(erat enim Moyses vir mitissimus super omnes homines qui morabantur in terra),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'statim locutus est ad eum, et ad Aaron et Mariam: Egredimini vos tantum tres ad tabernaculum fœderis. Cumque fuissent egressi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'descendit Dominus in columna nubis, et stetit in introitu tabernaculi, vocans Aaron et Mariam. Qui cum issent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'dixit ad eos: Audite sermones meos: si quis fuerit inter vos propheta Domini, in visione apparebo ei, vel per somnium loquar ad illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'At non talis servus meus Moyses, qui in omni domo mea fidelissimus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'ore enim ad os loquor ei: et palam, et non per ænigmata et figuras Dominum videt. Quare ergo non timuistis detrahere servo meo Moysi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Iratusque contra eos, abiit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'nubes quoque recessit quæ erat super tabernaculum: et ecce Maria apparuit candens lepra quasi nix. Cumque respexisset eam Aaron, et vidisset perfusam lepra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'ait ad Moysen: Obsecro, domine mi, ne imponas nobis hoc peccatum quod stulte commisimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'ne fiat hæc quasi mortua, et ut abortivum quod projicitur de vulva matris suæ: ecce jam medium carnis ejus devoratum est a lepra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Clamavitque Moyses ad Dominum, dicens: Deus, obsecro, sana eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Cui respondit Dominus: Si pater ejus spuisset in faciem illius, nonne debuerat saltem septem diebus rubore suffundi? separetur septem diebus extra castra, et postea revocabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Exclusa est itaque Maria extra castra septem diebus: et populus non est motus de loco illo, donec revocata est Maria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Profectusque est populus de Haseroth, fixis tentoriis in deserto Pharan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Ibique locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Mitte viros, qui considerent terram Chanaan, quam daturus sum filiis Israël, singulos de singulis tribubus, ex principibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Fecit Moyses quod Dominus imperaverat, de deserto Pharan mittens principes viros, quorum ista sunt nomina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'De tribu Ruben, Sammua filium Zechur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'De tribu Simeon, Saphat filium Huri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'De tribu Juda, Caleb filium Jephone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'De tribu Issachar, Igal filium Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'De tribu Ephraim, Osee filium Nun.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'De tribu Benjamin, Phalti filium Raphu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'De tribu Zabulon, Geddiel filium Sodi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'De tribu Joseph, sceptri Manasse, Gaddi filium Susi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'De tribu Dan, Ammiel filium Gemalli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'De tribu Aser, Sthur filium Michaël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'De tribu Nephthali, Nahabi filium Vapsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'De tribu Gad, Guel filium Machi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Hæc sunt nomina virorum, quos misit Moyses ad considerandam terram: vocavitque Osee filium Nun, Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Misit ergo eos Moyses ad considerandam terram Chanaan, et dixit ad eos: Ascendite per meridianam plagam. Cumque veneritis ad montes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'considerate terram, qualis sit: et populum qui habitator est ejus, utrum fortis sit an infirmus: si pauci numero an plures:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'ipsa terra, bona an mala: urbes quales, muratæ an absque muris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'humus, pinguis an sterilis, nemorosa an absque arboribus. Confortamini, et afferte nobis de fructibus terræ. Erat autem tempus quando jam præcoquæ uvæ vesci possunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Cumque ascendissent, exploraverunt terram a deserto Sin, usque Rohob intrantibus Emath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Ascenderuntque ad meridiem, et venerunt in Hebron, ubi erant Achiman et Sisai et Tholmai filii Enac: nam Hebron septem annis ante Tanim urbem \'gypti condita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Pergentesque usque ad Torrentem botri, absciderunt palmitem cum uva sua, quem portaverunt in vecte duo viri. De malis quoque granatis et de ficis loci illius tulerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'qui appellatus est Nehelescol, id est Torrens botri, eo quod botrum portassent inde filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Reversique exploratores terræ post quadraginta dies, omni regione circuita,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'venerunt ad Moysen et Aaron et ad omnem cœtum filiorum Israël in desertum Pharan, quod est in Cades. Locutique eis et omni multitudini ostenderunt fructus terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'et narraverunt, dicentes: Venimus in terram, ad quam misisti nos, quæ revera fluit lacte et melle, ut ex his fructibus cognosci potest:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'sed cultores fortissimos habet, et urbes grandes atque muratas. Stirpem Enac vidimus ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Amalec habitat in meridie, Hethæus et Jebusæus et Amorrhæus in montanis: Chananæus vero moratur juxta mare et circa fluenta Jordanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Inter hæc Caleb compescens murmur populi, qui oriebatur contra Moysen, ait: Ascendamus, et possideamus terram, quoniam poterimus obtinere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Alii vero, qui fuerant cum eo, dicebant: Nequaquam ad hunc populum valemus ascendere, quia fortior nobis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Detraxeruntque terræ, quam inspexerant, apud filios Israël, dicentes: Terra, quam lustravimus, devorat habitatores suos: populus, quem aspeximus, proceræ staturæ est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 34, 'Ibi vidimus monstra quædam filiorum Enac de genere giganteo: quibus comparati, quasi locustæ videbamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Igitur vociferans omnis turba flevit nocte illa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'et murmurati sunt contra Moysen et Aaron cuncti filii Israël, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Utinam mortui essemus in \'gypto: et in hac vasta solitudine utinam pereamus, et non inducat nos Dominus in terram istam, ne cadamus gladio, et uxores ac liberi nostri ducantur captivi. Nonne melius est reverti in \'gyptum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Dixeruntque alter ad alterum: Constituamus nobis ducem, et revertamur in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Quo audito, Moyses et Aaron ceciderunt proni in terram coram omni multitudine filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'At vero Josue filius Nun et Caleb filius Jephone, qui et ipsi lustraverant terram, sciderunt vestimenta sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'et ad omnem multitudinem filiorum Israël locuti sunt: Terra, quam circuivimus, valde bona est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Si propitius fuerit Dominus, inducet nos in eam, et tradet humum lacte et melle manantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Nolite rebelles esse contra Dominum: neque timeatis populum terræ hujus, quia sicut panem ita eos possumus devorare. Recessit ab eis omne præsidium: Dominus nobiscum est, nolite metuere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Cumque clamaret omnis multitudo, et lapidibus eos vellet opprimere, apparuit gloria Domini super tectum fœderis cunctis filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Et dixit Dominus ad Moysen: Usquequo detrahet mihi populus iste? quousque non credent mihi, in omnibus signis quæ feci coram eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Feriam igitur eos pestilentia, atque consumam: te autem faciam principem super gentem magnam, et fortiorem quam hæc est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Et ait Moyses ad Dominum: Ut audiant \'gyptii, de quorum medio eduxisti populum istum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'et habitatores terræ hujus, qui audierunt quod tu, Domine, in populo isto sis, et facie videaris ad faciem, et nubes tua protegat illos, et in columna nubis præcedas eos per diem, et in columna ignis per noctem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'quod occideris tantam multitudinem quasi unum hominem, et dicant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Non poterat introducere populum in terram pro qua juraverat: idcirco occidit eos in solitudine?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Magnificetur ergo fortitudo Domini sicut jurasti, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Dominus patiens et multæ misericordiæ, auferens iniquitatem et scelera, nullumque innoxium derelinquens, qui visitas peccata patrum in filios in tertiam et quartam generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Dimitte, obsecro, peccatum populi hujus secundum magnitudinem misericordiæ tuæ, sicut propitius fuisti egredientibus de \'gypto usque ad locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Dixitque Dominus: Dimisi juxta verbum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Vivo ego: et implebitur gloria Domini universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Attamen omnes homines qui viderunt majestatem meam, et signa quæ feci in \'gypto et in solitudine, et tentaverunt me jam per decem vices, nec obedierunt voci meæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'non videbunt terram pro qua juravi patribus eorum, nec quisquam ex illis qui detraxit mihi, intuebitur eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Servum meum Caleb, qui plenus alio spiritu secutus est me, inducam in terram hanc, quam circuivit; et semen ejus possidebit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Quoniam Amalecites et Chananæus habitant in vallibus. Cras movete castra, et revertimini in solitudinem per viam maris Rubri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Usquequo multitudo hæc pessima murmurat contra me? querelas filiorum Israël audivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dic ergo eis: Vivo ego, ait Dominus: sicut locuti estis audiente me, sic faciam vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'In solitudine hac jacebunt cadavera vestra. Omnes qui numerati estis a viginti annis et supra, et murmurastis contra me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'non intrabitis terram, super quam levavi manum meam ut habitare vos facerem, præter Caleb filium Jephone, et Josue filium Nun.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Parvulos autem vestros, de quibus dixistis quod prædæ hostibus forent, introducam, ut videant terram, quæ vobis displicuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Vestra cadavera jacebunt in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Filii vestri erunt vagi in deserto annis quadraginta, et portabunt fornicationem vestram, donec consumantur cadavera patrum in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'juxta numerum quadraginta dierum, quibus considerastis terram: annus pro die imputabitur. Et quadraginta annis recipietis iniquitates vestras, et scietis ultionem meam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'quoniam sicut locutus sum, ita faciam omni multitudini huic pessimæ, quæ consurrexit adversum me: in solitudine hac deficiet, et morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Igitur omnes viri, quos miserat Moyses ad contemplandam terram, et qui reversi murmurare fecerant contra eum omnem multitudinem, detrahentes terræ quod esset mala,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'mortui sunt atque percussi in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Josue autem filius Nun, et Caleb filius Jephone, vixerunt ex omnibus qui perrexerant ad considerandam terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Locutusque est Moyses universa verba hæc ad omnes filios Israël, et luxit populus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Et ecce mane primo surgentes ascenderunt verticem montis, atque dixerunt: Parati sumus ascendere ad locum, de quo Dominus locutus est: quia peccavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Quibus Moyses: Cur, inquit, transgredimini verbum Domini, quod vobis non cedet in prosperum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'nolite ascendere: non enim est Dominus vobiscum: ne corruatis coram inimicis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Amalecites et Chananæus ante vos sunt, quorum gladio corruetis, eo quod nolueritis acquiescere Domino: nec erit Dominus vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'At illi contenebrati ascenderunt in verticem montis. Arca autem testamenti Domini et Moyses non recesserunt de castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Descenditque Amalecites et Chananæus, qui habitabat in monte: et percutiens eos atque concidens, persecutus est eos usque Horma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Loquere ad filios Israël, et dices ad eos: Cum ingressi fueritis terram habitationis vestræ, quam ego dabo vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'et feceritis oblationem Domino in holocaustum, aut victimam, vota solventes, vel sponte offerentes munera, aut in solemnitatibus vestris adolentes odorem suavitatis Domino, de bobus sive de ovibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'offeret quicumque immolaverit victimam, sacrificium similæ, decimam partem ephi, conspersæ oleo, quod mensuram habebit quartam partem hin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'et vinum ad liba fundenda ejusdem mensuræ dabit in holocaustum sive in victimam. Per agnos singulos');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'et arietes erit sacrificium similæ duarum decimarum, quæ conspersa sit oleo tertiæ partis hin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'et vinum ad libamentum tertiæ partis ejusdem mensuræ offeret in odorem suavitatis Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Quando vero de bobus feceris holocaustum aut hostiam, ut impleas votum vel pacificas victimas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'dabis per singulos boves similæ tres decimas conspersæ oleo, quod habeat medium mensuræ hin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'et vinum ad liba fundenda ejusdem mensuræ in oblationem suavissimi odoris Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Sic facies');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'per singulos boves et arietis et agnos et hædos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Tam indigenæ quam peregrini');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'eodem ritu offerent sacrificia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Unum præceptum erit atque judicium tam vobis quam advenis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Loquere filiis Israël, et dices ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Cum veneritis in terram, quam dabo vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'et comederitis de panibus regionis illius, separabitis primitias Domino');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'de cibis vestris. Sicut de areis primitias separatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'ita et de pulmentis dabitis primitiva Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Quod si per ignorantiam præterieritis quidquam horum, quæ locutus est Dominus ad Moysen,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'et mandavit per eum ad vos, a die qua cœpit jubere et ultra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'oblitaque fuerit facere multitudo: offeret vitulum de armento, holocaustum in odorem suavissimum Domino, et sacrificum ejus ac liba, ut cæremoniæ postulant, hircumque pro peccato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'et rogabit sacerdos pro omni multitudine filiorum Israël, et dimittetur eis, quoniam non sponte peccaverunt, nihilominus offerentes incensum Domino pro se et pro peccato atque errore suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'et dimittetur universæ plebi filiorum Israël, et advenis qui peregrinantur inter eos: quoniam culpa est omnis populi per ignorantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Quod si anima una nesciens peccaverit, offeret capram anniculam pro peccato suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'et deprecabitur pro ea sacerdos, quod inscia peccaverit coram Domino: impetrabitque ei veniam, et dimittetur illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Tam indigenis quam advenis una lex erit omnium, qui peccaverint ignorantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Anima vero, quæ per superbiam aliquid commiserit, sive civis sit ille, sive peregrinus (quoniam adversus Dominum rebellis fuit), peribit de populo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'verbum enim Domini contempsit, et præceptum illius fecit irritum: idcirco delebitur, et portabit iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Factum est autem, cum essent filii Israël in solitudine, et invenissent hominem colligentem ligna in die sabbati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'obtulerunt eum Moysi et Aaron et universæ multitudini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Qui recluserunt eum in carcerem, nescientes quid super eo facere deberent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Dixitque Dominus ad Moysen: Morte moriatur homo iste: obruat eum lapidibus omnis turba extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Cumque eduxissent eum foras, obruerunt lapidibus, et mortuus est, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Dixit quoque Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Loquere filiis Israël, et dices ad eos ut faciant sibi fimbrias per angulos palliorum, ponentes in eis vittas hyacinthinas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'quas cum viderint, recordentur omnium mandatorum Domini, nec sequantur cogitationes suas et oculos per res varias fornicantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'sed magis memores præceptorum Domini faciant ea, sintque sancti Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ego Dominus Deus vester, qui eduxi vos de terra \'gypti, ut essem Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Ecce autem Core filius Isaar, filii Caath, filii Levi, et Dathan atque Abiron filii Eliab, Hon quoque filius Pheleth de filiis Ruben,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'surrexerunt contra Moysen, aliique filiorum Israël ducenti quinquaginta viri proceres synagogæ, et qui tempore concilii per nomina vocabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Cumque stetissent adversum Moysen et Aaron, dixerunt: Sufficiat vobis, quia omnis multitudo sanctorum est, et in ipsis est Dominus: cur elevamini super populum Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Quod cum audisset Moyses, cecidit pronus in faciem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'locutusque ad Core et ad omnem multitudinem: Mane, inquit, notum faciet Dominus qui ad se pertineant, et sanctos applicabit sibi: et quos elegerit, appropinquabunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Hoc igitur facite: tollat unusquisque thuribula sua, tu Core, et omne concilium tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'et hausto cras igne, ponite desuper thymiama coram Domino: et quemcumque elegerit, ipse erit sanctus: multum erigimini filii Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Dixitque rursum ad Core: Audite, filii Levi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'num parum vobis est quod separavit vos Deus Israël ab omni populo, et junxit sibi, ut serviretis ei in cultu tabernaculi, et staretis coram frequentia populi, et ministraretis ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'idcirco ad se fecit accedere te et omnes fratres tuos filios Levi, ut vobis etiam sacerdotium vindicetis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'et omnis globus tuus stet contra Dominum? quid est enim Aaron ut murmuretis contra eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Misit ergo Moyses ut vocaret Dathan et Abiron filios Eliab. Qui responderunt: Non venimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Numquid parum est tibi quod eduxisti nos de terra, quæ lacte et melle manabat, ut occideres in deserto, nisi et dominatus fueris nostri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Revera induxisti nos in terram, quæ fluit rivis lactis et mellis, et dedisti nobis possessiones agrorum et vinearum: an et oculos nostros vis eruere? non venimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Iratusque Moyses valde, ait ad Dominum: Ne respicias sacrificia eorum: tu scis quod ne asellum quidem umquam acceperim ab eis, nec afflixerim quempiam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Dixitque ad Core: Tu, et omnis congregatio tua, state seorsum coram Domino, et Aaron die crastino separatim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Tollite singuli thuribula vestra, et ponite super ea incensum, offerentes Domino ducenta quinquaginta thuribula: Aaron quoque teneat thuribulum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Quod cum fecissent, stantibus Moyses et Aaron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'et coacervassent adversum eos omnem multitudinem ad ostium tabernaculi, apparuit cunctis gloria Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Locutusque Dominus ad Moysen et Aaron, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Separamini de medio congregationis hujus, ut eos repente disperdam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Qui ceciderunt proni in faciem, atque dixerunt: Fortissime Deus spirituum universæ carnis, num uno peccante, contra omnes ira tua desæviet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Et ait Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Præcipe universo populo ut separetur a tabernaculis Core et Dathan et Abiron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Surrexitque Moyses, et abiit ad Dathan et Abiron: et sequentibus eum senioribus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'dixit ad turbam: Recedite a tabernaculis hominum impiorum, et nolite tangere quæ ad eos pertinent, ne involvamini in peccatis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Cumque recessissent a tentoriis eorum per circuitum, Dathan et Abiron egressi stabant in introitu papilionum suorum cum uxoribus et liberis, omnique frequentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Et ait Moyses: In hoc scietis quod Dominus miserit me ut facerem universa quæ cernitis, et non ex proprio ea corde protulerim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'si consueta hominum morte interierint, et visitaverit eos plaga, qua et ceteri visitari solent, non misit me Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'sin autem novam rem fecerit Dominus, ut aperiens terra os suum deglutiat eos et omnia quæ ad illos pertinent, descenderintque viventes in infernum, scietis quod blasphemaverint Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Confestim igitur ut cessavit loqui, dirupta est terra sub pedibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'et aperiens os suum, devoravit illos cum tabernaculis suis et universa substantia eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'descenderuntque vivi in infernum operti humo, et perierunt de medio multitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'At vero omnis Israël, qui stabat per gyrum, fugit ad clamorem pereuntium, dicens: Ne forte et nos terra deglutiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Sed et ignis egressus a Domino interfecit ducentos quinquaginta viros, qui offerebant incensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Præcipe Eleazaro filio Aaron sacerdoti ut tollat thuribula quæ jacent in incendio, et ignem huc illucque dispergat: quoniam sanctificata sunt');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'in mortibus peccatorum: producatque ea in laminas, et affigat altari, eo quod oblatum sit in eis incensum Domino, et sanctificata sint, ut cernant ea pro signo et monimento filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Tulit ergo Eleazar sacerdos thuribula ænea, in quibus obtulerant hi quos incendium devoravit, et produxit ea in laminas, affigens altari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'ut haberent postea filii Israël, quibus commonerentur ne quis accedat alienigena, et qui non est de semine Aaron ad offerendum incensum Domino, ne patiatur sicut passus est Core, et omnis congregatio ejus, loquente Domino ad Moysen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Murmuravit autem omnis multitudo filiorum Israël sequenti die contra Moysen et Aaron, dicens: Vos interfecistis populum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Cumque oriretur seditio, et tumultus incresceret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Moyses et Aaron fugerunt ad tabernaculum fœderis. Quod, postquam ingressi sunt, operuit nubes, et apparuit gloria Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Dixitque Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Recedite de medio hujus multitudinis, etiam nunc delebo eos. Cumque jacerent in terra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'dixit Moyses ad Aaron: Tolle thuribulum, et hausto igne de altari, mitte incensum desuper, pergens cito ad populum, ut roges pro eis: jam enim egressa est ira a Domino, et plaga desævit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Quod cum fecisset Aaron, et cucurrisset ad mediam multitudinem, quam jam vastabat incendium, obtulit thymiama:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'et stans inter mortuos ac viventes, pro populo deprecatus est, et plaga cessavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Fuerunt autem qui percussi sunt, quatuordecim millia hominum, et septingenti, absque his qui perierant in seditione Core.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Reversusque est Aaron ad Moysen ad ostium tabernaculi fœderis postquam quievit interitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Et locutus est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Loquere ad filios Israël, et accipe ab eis virgas singulas per cognationes suas, a cunctis principibus tribuum, virgas duodecim, et uniuscujusque nomen superscribes virgæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Nomen autem Aaron erit in tribu Levi, et una virga cunctas seorsum familias continebit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'ponesque eas in tabernaculo fœderis coram testimonio, ubi loquar ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Quem ex his elegero, germinabit virga ejus: et cohibebo a me querimonias filiorum Israël, quibus contra vos murmurant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Locutusque est Moyses ad filios Israël: et dederunt ei omnes principes virgas per singulas tribus: fueruntque virgæ duodecim absque virga Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Quas cum posuisset Moyses coram Domino in tabernaculo testimonii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'sequenti die regressus invenit germinasse virgam Aaron in domo Levi: et turgentibus gemmis eruperant flores, qui, foliis dilatatis, in amygdalas deformati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Protulit ergo Moyses omnes virgas de conspectu Domini ad cunctos filios Israël: videruntque, et receperunt singuli virgas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Dixitque Dominus ad Moysen: Refer virgam Aaron in tabernaculum testimonii, ut servetur ibi in signum rebellium filiorum Israël, et quiescant querelæ eorum a me, ne moriantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Fecitque Moyses sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Dixerunt autem filii Israël ad Moysen: Ecce consumpti sumus, omnes perivimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Quicumque accedit ad tabernaculum Domini, moritur. Num usque ad internecionem cuncti delendi sumus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Dixitque Dominus ad Aaron: Tu, et filii tui, et domus patris tui tecum, portabitis iniquitatem sanctuarii: et tu et filii tui simul sustinebitis peccata sacerdotii vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Sed et fratres tuos de tribu Levi, et sceptrum patris tui sume tecum, præstoque sint, et ministrent tibi: tu autem et filii tui ministrabitis in tabernaculo testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Excubabuntque Levitæ ad præcepta tua, et ad cuncta opera tabernaculi: ita dumtaxat ut ad vasa sanctuarii et ad altare non accedant, ne et illi moriantur, et vos pereatis simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Sint autem tecum, et excubent in custodiis tabernaculi, et in omnibus cæremoniis ejus. Alienigena non miscebitur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Excubate in custodia sanctuarii, et in ministerio altaris: ne oriatur indignatio super filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ego dedi vobis fratres vestros Levitas de medio filiorum Israël, et tradidi donum Domino, ut serviant in ministeriis tabernaculi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Tu autem et filii tui custodite sacerdotium vestrum: et omnia quæ ad cultum altaris pertinent, et intra velum sunt, per sacerdotes administrabuntur: si quis externus accesserit, occidetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Locutusque est Dominus ad Aaron: Ecce dedi tibi custodiam primitiarum mearum. Omnia quæ sanctificantur a filiis Israël, tradidi tibi et filiis tuis pro officio sacerdotali legitima sempiterna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Hæc ergo accipies de his, quæ sanctificantur et oblata sunt Domino. Omnis oblatio, et sacrificium, et quidquid pro peccato atque delicto redditur mihi, et cedit in Sancta sanctorum, tuum erit, et filiorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'In sanctuario comedes illud: mares tantum edent ex eo, quia consecratum est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Primitias autem, quas voverint et obtulerint filii Israël, tibi dedi, et filiis tuis, ac filiabus tuis, jure perpetuo: qui mundus est in domo tua, vescetur eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Omnem medullam olei, et vini, ac frumenti, quidquid offerunt primitiarum Domino, tibi dedi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Universa frugum initia, quas gignit humus, et Domino deportantur, cedent in usus tuos: qui mundus est in domo tua, vescetur eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Omne quod ex voto reddiderint filii Israël, tuum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Quidquid primum erumpit e vulva cunctæ carnis, quam offerunt Domino, sive ex hominibus, sive de pecoribus fuerit, tui juris erit: ita dumtaxat ut pro hominis primogenito pretium accipias, et omne animal quod immundum est redimi facias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'cujus redemptio erit post unum mensem, siclis argenti quinque, pondere sanctuarii. Siclus viginti obolos habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Primogenitum autem bovis, et ovis, et capræ, non facies redimi, quia sanctificata sunt Domino. Sanguinem tantum eorum fundes super altare, et adipes adolebis in suavissimum odorem Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Carnes vero in usum tuum cedent, sicut pectusculum consecratum, et armus dexter: tua erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Omnes primitias sanctuarii, quas offerunt filii Israël Domino, tibi dedi, et filiis, ac filiabus tuis, jure perpetuo. Pactum salis est sempiternum coram Domino, tibi ac filiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Dixitque Dominus ad Aaron: In terra eorum nihil possidebitis, nec habebitis partem inter eos: ego pars et hæreditas tua in medio filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Filiis autem Levi dedi omnes decimas Israëlis in possessionem, pro ministerio, quo serviunt mihi in tabernaculo fœderis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'ut non accedant ultra filii Israël ad tabernaculum, nec committant peccatum mortiferum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'solis filiis Levi mihi in tabernaculo servientibus, et portantibus peccata populi. Legitimum sempiternum erit in generationibus vestris. Nihil aliud possidebunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'decimarum oblatione contenti, quas in usus eorum et necessaria separavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Præcipe Levitis, atque denuntia: Cum acceperitis a filiis Israël decimas, quas dedi vobis, primitias earum offerte Domino, id est, decimam partem decimæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'ut reputetur vobis in oblationem primitivorum, tam de areis quam de torcularibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'et universis quorum accipitis primitias, offerte Domino, et date Aaron sacerdoti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Omnia quæ offeretis ex decimis, et in donaria Domini separabitis, optima et electa erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Dicesque ad eos: Si præclara et meliora quæque obtuleritis ex decimis, reputabitur vobis quasi de area, et torculari dederitis primitias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'et comedetis eas in omnibus locis vestris, tam vos quam familiæ vestræ: quia pretium est pro ministerio, quo servitis in tabernaculo testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Et non peccabitis super hoc, egregia vobis et pinguia reservantes, ne polluatis oblationes filiorum Israël, et moriamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Locutusque est Dominus ad Moysen et Aaron, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Ista est religio victimæ, quam constituit Dominus. Præcipe filiis Israël, ut adducant ad te vaccam rufam ætatis integræ, in qua nulla sit macula, nec portaverit jugum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'tradetisque eam Eleazaro sacerdoti, qui eductam extra castra, immolabit in conspectu omnium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'et tingens digitum in sanguine ejus, asperget contra fores tabernaculi septem vicibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'comburetque eam cunctis videntibus, tam pelle et carnibus ejus quam sanguine et fimo flammæ traditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Lignum quoque cedrinum, et hyssopum, coccumque bis tinctum sacerdos mittet in flammam, quæ vaccam vorat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Et tunc demum, lotis vestibus et corpore suo, ingredietur in castra, commaculatusque erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Sed et ille qui combusserit eam, lavabit vestimenta sua et corpus, et immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Colliget autem vir mundus cineres vaccæ, et effundet eos extra castra in loco purissimo, ut sint multitudini filiorum Israël in custodiam, et in aquam aspersionis: quia pro peccato vacca combusta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Cumque laverit qui vaccæ portaverat cineres vestimenta sua, immundus erit usque ad vesperum. Habebunt hoc filii Israël, et advenæ qui habitant inter eos, sanctum jure perpetuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Qui tetigerit cadaver hominis, et propter hoc septem diebus fuerit immundus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'aspergetur ex hac aqua die tertio et septimo, et sic mundabitur. Si die tertio aspersus non fuerit, septimo non poterit emundari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Omnis qui tetigerit humanæ animæ morticinum, et aspersus hac commistione non fuerit, polluet tabernaculum Domini et peribit ex Israël: quia aqua expiationis non est aspersus, immundus erit, et manebit spurcitia ejus super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Ista est lex hominis qui moritur in tabernaculo: omnes qui ingrediuntur tentorium illius, et universa vasa quæ ibi sunt, polluta erunt septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Vas, quod non habuerit operculum nec ligaturam desuper, immundum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Si quis in agro tetigerit cadaver occisi hominis, aut per se mortui, sive os illius, vel sepulchrum, immundus erit septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Tollentque de cineribus combustionis atque peccati, et mittent aquas vivas super eos in vas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'in quibus cum homo mundus tinxerit hyssopum, asperget ex eo omne tentorium, et cunctam supellectilem, et homines hujuscemodi contagione pollutos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'atque hoc modo mundus lustrabit immundum tertio et septimo die: expiatusque die septimo, lavabit et se et vestimenta sua, et immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Si quis hoc ritu non fuerit expiatus, peribit anima illius de medio ecclesiæ: quia sanctuarium Domini polluit, et non est aqua lustrationis aspersus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Erit hoc præceptum legitimum sempiternum. Ipse quoque qui aspergit aquas, lavabit vestimenta sua. Omnis qui tetigerit aquas expiationis, immundus erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Quidquid tetigerit immundus, immundum faciet: et anima, quæ horum quippiam tetigerit, immunda erit usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Veneruntque filii Israël et omnis multitudo in desertum Sin, mense primo, et mansit populus in Cades. Mortuaque est ibi Maria, et sepulta in eodem loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Cumque indigeret aqua populus, convenerunt adversum Moysen et Aaron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'et versi in seditionem, dixerunt: Utinam periissemus inter fratres nostros coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Cur eduxistis ecclesiam Domini in solitudinem, ut et nos et nostra jumenta moriamur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'quare nos fecistis ascendere de \'gypto, et adduxistis in locum istum pessimum, qui seri non potest, qui nec ficum gignit, nec vineas, nec malogranata, insuper et aquam non habet ad bibendum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Ingressusque Moyses et Aaron, dimissa multitudine, tabernaculum fœderis, corruerunt proni in terram, clamaveruntque ad Dominum, atque dixerunt: Domine Deus, audi clamorem hujus populi, et aperi eis thesaurum tuum fontem aquæ vivæ, ut satiati, cesset murmuratio eorum. Et apparuit gloria Domini super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Tolle virgam, et congrega populum, tu et Aaron frater tuus, et loquimini ad petram coram eis, et illa dabit aquas. Cumque eduxeris aquam de petra, bibet omnis multitudo et jumenta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Tulit igitur Moyses virgam, quæ erat in conspectu Domini, sicut præceperat ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'congregata multitudine ante petram: dixitque eis: Audite, rebelles et increduli: num de petra hac vobis aquam poterimus ejicere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Cumque elevasset Moyses manum, percutiens virga bis silicem, egressæ sunt aquæ largissimæ, ita ut populus biberet et jumenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Dixitque Dominus ad Moysen et Aaron: Quia non credidistis mihi, ut sanctificaretis me coram filiis Israël, non introducetis hos populos in terram, quam dabo eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Hæc est aqua contradictionis, ubi jurgati sunt filii Israël contra Dominum, et sanctificatus est in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Misit interea nuntios Moyses de Cades ad regem Edom, qui dicerent: Hæc mandat frater tuus Israël: Nosti omnem laborem qui apprehendit nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'quomodo descenderint patres nostri in \'gyptum, et habitaverimus ibi multo tempore, afflixerintque nos \'gyptii, et patres nostros:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'et quomodo clamaverimus ad Dominum, et exaudierit nos, miseritque angelum, qui eduxerit nos de \'gypto. Ecce in urbe Cades, quæ est in extremis finibus tuis, positi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'obsecramus ut nobis transire liceat per terram tuam. Non ibimus per agros, nec per vineas; non bibemus aquas de puteis tuis: sed gradiemur via publica, nec ad dexteram nec ad sinistram declinantes, donec transeamus terminos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Cui respondit Edom: Non transibis per me, alioquin armatus occurram tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Dixeruntque filii Israël: Per tritam gradiemur viam: et si biberimus aquas tuas, nos et pecora nostra, dabimus quod justum est: nulla erit in pretio difficultas, tantum velociter transeamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'At ille respondit: Non transibis. Statimque egressus est obvius, cum infinita multitudo, et manu forti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'nec voluit acquiescere deprecanti, ut concederet transitum per fines suos. Quam ob rem divertit ab eo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Cumque castra movissent de Cades, venerunt in montem Hor, qui est in finibus terræ Edom:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'ubi locutus est Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Pergat, inquit, Aaron ad populos suos: non enim intrabit terram, quam dedi filiis Israël, eo quod incredulus fuerit ori meo, ad aquas contradictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Tolle Aaron et filium ejus cum eo, et duces eos in montem Hor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Cumque nudaveris patrem veste sua, indues ea Eleazarum filium ejus: Aaron colligetur, et morietur ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Fecit Moyses ut præceperat Dominus: et ascenderunt in montem Hor coram omni multitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Cumque Aaron spoliasset vestibus suis, induit eis Eleazarum filium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Illo mortuo in montis supercilio, descendit cum Eleazaro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 30, 'Omnis autem multitudo videns occubuisse Aaron, flevit super eo triginta diebus per cunctas familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Quod cum audisset Chananæus rex Arad, qui habitabat ad meridiem, venisse scilicet Israël per exploratorum viam, pugnavit contra illum, et victor existens, duxit ex eo prædam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'At Israël voto se Domino obligans, ait: Si tradideris populum istum in manu mea, delebo urbes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Exaudivitque Dominus preces Israël, et tradidit Chananæum, quem ille interfecit subversis urbibus ejus: et vocavit nomen loci illius Horma, id est, anathema.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Profecti sunt autem et de monte Hor, per viam quæ ducit ad mare Rubrum, ut circumirent terram Edom. Et tædere cœpit populum itineris ac laboris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'locutusque contra Deum et Moysen, ait: Cur eduxisti nos de \'gypto, ut moreremur in solitudine? deest panis, non sunt aquæ: anima nostra jam nauseat super cibo isto levissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Quam ob rem misit Dominus in populum ignitos serpentes, ad quorum plagas et mortes plurimorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'venerunt ad Moysen, atque dixerunt: Peccavimus, quia locuti sumus contra Dominum et te: ora ut tollat a nobis serpentes. Oravitque Moyses pro populo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'et locutus est Dominus ad eum: Fac serpentem æneum, et pone eum pro signo: qui percussus aspexerit eum, vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Fecit ergo Moyses serpentem æneum, et posuit eum pro signo: quem cum percussi aspicerent, sanabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Profectique filii Israël castrametati sunt in Oboth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Unde egressi fixere tentoria in Jeabarim, in solitudine quæ respicit Moab contra orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Et inde moventes, venerunt ad torrentem Zared.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Quem relinquentes castrametati sunt contra Arnon, quæ est in deserto, et prominet in finibus Amorrhæi. Siquidem Arnon terminus est Moab, dividens Moabitas et Amorrhæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Unde dicitur in libro bellorum Domini: Sicut fecit in mari Rubro, sic faciet in torrentibus Arnon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Scopuli torrentium inclinati sunt, ut requiescerent in Ar, et recumberent in finibus Moabitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Ex eo loco apparuit puteus, super quo locutus est Dominus ad Moysen: Congrega populum, et dabo ei aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tunc cecinit Israël carmen istud: Ascendat puteus. Concinebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Puteus, quem foderunt principes et paraverunt duces multitudinis in datore legis, et in baculis suis. De solitudine, Matthana.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'De Matthana in Nahaliel: de Nahaliel in Bamoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'De Bamoth, vallis est in regione Moab, in vertice Phasga, quod respicit contra desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Misit autem Israël nuntios ad Sehon regem Amorrhæorum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Obsecro ut transire mihi liceat per terram tuam: non declinabimus in agros et vineas; non bibemus aquas ex puteis: via regia gradiemur, donec transeamus terminos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Qui concedere noluit ut transiret Israël per fines suos: quin potius exercitu congregato, egressus est obviam in desertum, et venit in Jasa, pugnavitque contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'A quo percussus est in ore gladii, et possessa est terra ejus ab Arnon usque Jeboc, et filios Ammon: quia forti præsidio tenebantur termini Ammonitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Tulit ergo Israël omnes civitates ejus, et habitavit in urbibus Amorrhæi, in Hesebon scilicet, et viculis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Urbs Hesebon fuit Sehon regis Amorrhæi, qui pugnavit contra regem Moab: et tulit omnem terram, quæ ditionis illius fuerat usque Arnon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Idcirco dicitur in proverbio: Venite in Hesebon: ædificetur, et construatur civitas Sehon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'ignis egressus est de Hesebon, flamma de oppido Sehon, et devoravit Ar Moabitarum, et habitatores excelsorum Arnon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Væ tibi Moab; peristi popule Chamos. Dedit filios ejus in fugam, et filias in captivitatem regi Amorrhæorum Sehon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Jugum ipsorum disperiit ad Hesebon usque Dibon: lassi pervenerunt in Nophe, et usque Medaba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Habitavit itaque Israël in terra Amorrhæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Misitque Moyses qui explorarent Jazer: cujus ceperunt viculos, et possederunt habitatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Verteruntque se, et ascenderunt per viam Basan, et occurrit eis Og, rex Basan, cum omni populo suo, pugnaturus in Edrai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Dixitque Dominus ad Moysen: Ne timeas eum, quia in manu tua tradidi illum, et omnem populum ac terram ejus: faciesque illi sicut fecisti Sehon, regi Amorrhæorum habitatori Hesebon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Percusserunt igitur et hunc cum filiis suis, universumque populum ejus usque ad internecionem, et possederunt terram illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Profectique castrametati sunt in campestribus Moab, ubi trans Jordanem Jericho sita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Videns autem Balac filius Sephor omnia quæ fecerat Israël Amorrhæo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'et quod pertimuissent eum Moabitæ, et impetum ejus ferre non possent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'dixit ad majores natu Madian: Ita delebit hic populus omnes, qui in nostris finibus commorantur, quomodo solet bos herbas usque ad radices carpere. Ipse erat eo tempore rex in Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Misit ergo nuntios ad Balaam filium Beor ariolum, qui habitabat super flumen terræ filiorum Ammon, ut vocarent eum, et dicerent: Ecce egressus est populus ex \'gypto, qui operuit superficiem terræ, sedens contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Veni igitur, et maledic populo huic, quia fortior me est: si quomodo possim percutere et ejicere eum de terra mea. Novi enim quod benedictus sit cui benedixeris, et maledictus in quem maledicta congesseris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Perrexeruntque seniores Moab, et majores natu Madian, habentes divinationis pretium in manibus. Cumque venissent ad Balaam, et narrassent ei omnia verba Balac,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'ille respondit: Manete hic nocte, et respondebo quidquid mihi dixerit Dominus. Manentibus illis apud Balaam, venit Deus, et ait ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Quid sibi volunt homines isti apud te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Respondit: Balac filius Sephor rex Moabitarum misit ad me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'dicens: Ecce populus qui egressus est de \'gypto, operuit superficiem terræ: veni, et maledic ei, si quomodo possim pugnans abigere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Dixitque Deus ad Balaam: Noli ire cum eis, neque maledicas populo: quia benedictus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Qui mane consurgens dixit ad principes: Ite in terram vestram, quia prohibuit me Dominus venire vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Reversi principes dixerunt ad Balac: Noluit Balaam venire nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Rursum ille multo plures et nobiliores quam ante miserat, misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Qui cum venissent ad Balaam, dixerunt: Sic dicit Balac filius Sephor: Ne cuncteris venire ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'paratus sum honorare te, et quidquid volueris, dabo tibi: veni, et maledic populo isti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Respondit Balaam: Si dederit mihi Balac plenam domum suam argenti et auri, non potero immutare verbum Domini Dei mei, ut vel plus, vel minus loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Obsecro ut hic maneatis etiam hac nocte, et scire queam quid mihi rursum respondeat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Venit ergo Deus ad Balaam nocte, et ait ei: Si vocare te venerunt homines isti, surge, et vade cum eis: ita dumtaxat, ut quod tibi præcepero, facias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Surrexit Balaam mane, et strata asina sua profectus est cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Et iratus est Deus. Stetitque angelus Domini in via contra Balaam, qui insidebat asinæ, et duos pueros habebat secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Cernens asina angelum stantem in via, evaginato gladio, avertit se de itinere, et ibat per agrum. Quam cum verberaret Balaam, et vellet ad semitam reducere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'stetit angelus in angustiis duarum maceriarum, quibus vineæ cingebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Quem videns asina, junxit se parieti, et attrivit sedentis pedem. At ille iterum verberabat eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'et nihilominus angelus ad locum angustum transiens, ubi nec ad dexteram, nec ad sinistram poterat deviare, obvius stetit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Cumque vidisset asina stantem angelum, concidit sub pedibus sedentis: qui iratus, vehementius cædebat fuste latera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Aperuitque Dominus os asinæ, et locuta est: Quid feci tibi? cur percutis me ecce jam tertio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Respondit Balaam: Quia commeruisti, et illusisti mihi: utinam haberem gladium, ut te percuterem!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Dixit asina: Nonne animal tuum sum, cui semper sedere consuevisti usque in præsentem diem? dic quid simile umquam fecerim tibi. At ille ait: Numquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Protinus aperuit Dominus oculos Balaam, et vidit angelum stantem in via, evaginato gladio, adoravitque eum pronus in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Cui angelus: Cur, inquit, tertio verberas asinam tuam? ego veni ut adversarer tibi, quia perversa est via tua, mihique contraria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'et nisi asina declinasset de via, dans locum resistenti, te occidissem, et illa viveret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Dixit Balaam: Peccavi, nesciens quod tu stares contra me: et nunc si displicet tibi ut vadam, revertar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Ait angelus: Vade cum istis, et cave ne aliud quam præcepero tibi loquaris. Ivit igitur cum principibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Quod cum audisset Balac, egressus est in occursum ejus in oppido Moabitarum, quod situm est in extremis finibus Arnon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Dixitque ad Balaam: Misi nuntios ut vocarent te: cur non statim venisti ad me? an quia mercedem adventui tuo reddere nequeo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Cui ille respondit: Ecce adsum: numquid loqui potero aliud, nisi quod Deus posuerit in ore meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Perrexerunt ergo simul, et venerunt in urbem, quæ in extremis regni ejus finibus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Cumque occidisset Balac boves et oves, misit ad Balaam, et principes qui cum eo erant, munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Mane autem facto, duxit eum ad excelsa Baal, et intuitus est extremam partem populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Dixitque Balaam ad Balac: \'difica mihi hic septem aras, et para totidem vitulos, ejusdemque numeri arietes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Cumque fecisset juxta sermonem Balaam, imposuerunt simul vitulum et arietem super aram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Dixitque Balaam ad Balac: Sta paulisper juxta holocaustum tuum, donec vadam, si forte occurrat mihi Dominus, et quodcumque imperaverit, loquar tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Cumque abiisset velociter, occurrit illi Deus. Locutusque ad eum Balaam: Septem, inquit, aras erexi, et imposui vitulum et arietem desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Dominus autem posuit verbum in ore ejus, et ait: Revertere ad Balac, et hæc loqueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Reversus invenit stantem Balac juxta holocaustum suum, et omnes principes Moabitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'assumptaque parabola sua, dixit: De Aram adduxit me Balac rex Moabitarum, de montibus orientis: Veni, inquit, et maledic Jacob; propera, et detestare Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Quomodo maledicam, cui non maledixit Deus? qua ratione detester, quem Dominus non detestatur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'De summis silicibus videbo eum, et de collibus considerabo illum. Populus solus habitabit, et inter gentes non reputabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Quis dinumerare possit pulverem Jacob, et nosse numerum stirpis Israël? Moriatur anima mea morte justorum, et fiant novissima mea horum similia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Dixitque Balac ad Balaam: Quid est hoc quod agis? ut malediceres inimicis meis vocavi te, et tu e contrario benedicis eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Cui ille respondit: Num aliud possum loqui, nisi quod jusserit Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Dixit ergo Balac: Veni mecum in alterum locum unde partem Israël videas, et totum videre non possis: inde maledicito ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Cumque duxisset eum in locum sublimem, super verticem montis Phasga, ædificavit Balaam septem aras, et impositis supra vitulo atque ariete,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'dixit ad Balac: Sta hic juxta holocaustum tuum, donec ego obvius pergam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Cui cum Dominus occurrisset, posuissetque verbum in ore ejus, ait: Revertere ad Balac, et hæc loqueris ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Reversus invenit eum stantem juxta holocaustum suum, et principes Moabitarum cum eo. Ad quem Balac: Quid, inquit, locutus est Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'At ille, assumpta parabola sua, ait: Sta, Balac, et ausculta; audi, fili Sephor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'non est Deus quasi homo, ut mentiatur, nec ut filius hominis, ut mutetur. Dixit ergo, et non faciet? locutus est, et non implebit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Ad benedicendum adductus sum: benedictionem prohibere non valeo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Non est idolum in Jacob, nec videtur simulacrum in Israël. Dominus Deus ejus cum eo est, et clangor victoriæ regis in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Deus eduxit illum de \'gypto, cujus fortitudo similis est rhinocerotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Non est augurium in Jacob, nec divinatio in Israël: temporibus suis dicetur Jacob et Israëli quid operatus sit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Ecce populus ut leæna consurget, et quasi leo erigetur: non accubabit donec devoret prædam, et occisorum sanguinem bibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Dixitque Balac ad Balaam: Nec maledicas ei, nec benedicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Et ille ait: Nonne dixi tibi quod quidquid mihi Deus imperaret, hoc facerem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Et ait Balac ad eum: Veni, et ducam te ad alium locum: si forte placeat Deo ut inde maledicas eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Cumque duxisset eum super verticem montis Phogor, qui respicit solitudinem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'dixit ei Balaam: \'difica mihi hic septem aras, et para totidem vitulos, ejusdemque numeri arietes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Fecit Balac ut Balaam dixerat: imposuitque vitulos et arietes per singulas aras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Cumque vidisset Balaam quod placeret Domino ut benediceret Israëli, nequaquam abiit ut ante perrexerat, ut augurium quæreret: sed dirigens contra desertum vultum suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'et elevans oculos, vidit Israël in tentoriis commorantem per tribus suas: et irruente in se spiritu Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'assumpta parabola, ait: Dixit Balaam filius Beor: dixit homo, cujus obturatus est oculus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'dixit auditor sermonum Dei, qui visionem Omnipotentis intuitus est, qui cadit, et sic aperiuntur oculi ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Quam pulchra tabernacula tua, Jacob, et tentoria tua, Israël!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'ut valles nemorosæ, ut horti juxta fluvios irrigui, ut tabernacula quæ fixit Dominus, quasi cedri prope aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Fluet aqua de situla ejus, et semen illius erit in aquas multas. Tolletur propter Agag, rex ejus, et auferetur regnum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Deus eduxit illum de \'gypto, cujus fortitudo similis est rhinocerotis. Devorabunt gentes hostes illius, ossaque eorum confringent, et perforabunt sagittis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Accubans dormivit ut leo, et quasi leæna, quam suscitare nullus audebit. Qui benedixerit tibi, erit et ipse benedictus: qui maledixerit, in maledictione reputabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Iratusque Balac contra Balaam, complosis manibus ait: Ad maledicendum inimicis meis vocavi te, quibus e contrario tertio benedixisti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'revertere ad locum tuum. Decreveram quidem magnifice honorare te, sed Dominus privavit te honore disposito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Respondit Balaam ad Balac: Nonne nuntiis tuis, quos misisti ad me, dixi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Si dederit mihi Balac plenam domum suam argenti et auri, non potero præterire sermonem Domini Dei mei, ut vel boni quid vel mali proferam ex corde meo: sed quidquid Dominus dixerit, hoc loquar?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'verumtamen pergens ad populum meum, dabo consilium, quid populus tuus populo huic faciat extremo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Sumpta igitur parabola, rursum ait: Dixit Balaam filius Beor: dixit homo, cujus obturatus est oculus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'dixit auditor sermonum Dei, qui novit doctrinam Altissimi, et visiones Omnipotentis videt, qui cadens apertos habet oculos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Videbo eum, sed non modo: intuebor illum, sed non prope. Orietur stella ex Jacob, et consurget virga de Israël: et percutiet duces Moab, vastabitque omnes filios Seth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Et erit Idumæa possessio ejus: hæreditas Seir cedet inimicis suis: Israël vero fortiter aget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'De Jacob erit qui dominetur, et perdat reliquias civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Cumque vidisset Amalec, assumens parabolam, ait: Principium gentium Amalec, cujus extrema perdentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Vidit quoque Cinæum: et assumpta parabola, ait: Robustum quidem est habitaculum tuum: sed si in petra posueris nidum tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'et fueris electus de stirpe Cin, quamdiu poteris permanere? Assur enim capiet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Assumptaque parabola iterum locutus est: Heu! quis victurus est, quando ista faciet Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Venient in trieribus de Italia: superabunt Assyrios, vastabuntque Hebræos, et ad extremum etiam ipsi peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Surrexitque Balaam, et reversus est in locum suum: Balac quoque via, qua venerat, rediit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Morabatur autem eo tempore Israël in Settim, et fornicatus est populus cum filiabus Moab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'quæ vocaverunt eos ad sacrificia sua. At ille comederunt et adoraverunt deos earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Initiatusque est Israël Beelphegor: et iratus Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'ait ad Moysen: Tolle cunctos principes populi, et suspende eos contra solem in patibulis, ut avertatur furor meus ab Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Dixitque Moyses ad judices Israël: Occidat unusquisque proximos suos, qui initiati sunt Beelphegor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Et ecce unus de filiis Israël intravit coram fratribus suis ad scortum Madianitidem, vidente Moyse, et omni turba filiorum Israël, qui flebant ante fores tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Quod cum vidisset Phinees filius Eleazari filii Aaron sacerdotis, surrexit de medio multitudinis, et arrepto pugione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ingressus est post virum Israëlitem in lupanar, et perfodit ambos simul, virum scilicet et mulierem in locis genitalibus. Cessavitque plaga a filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'et occisi sunt viginti quatuor millia hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Dixitque Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Phinees filius Eleazari filii Aaron sacerdotis avertit iram meam a filiis Israël: quia zelo meo commotus est contra eos, ut non ipse delerem filios Israël in zelo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Idcirco loquere ad eum: Ecce do ei pacem fœderis mei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'et erit tam ipsi quam semini ejus pactum sacerdotii sempiternum: quia zelatus est pro Deo suo, et expiavit scelus filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Erat autem nomen viri Israëlitæ, qui occisus est cum Madianitide, Zambri filius Salu, dux de cognatione et tribu Simeonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Porro mulier Madianitis, quæ pariter interfecta est, vocabatur Cozbi filia Sur principis nobilissimi Madianitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Hostes vos sentiant Madianitæ, et percutite eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'quia et ipsi hostiliter egerunt contra vos, et decepere insidiis per idolum Phogor, et Cozbi filiam ducis Madian sororem suam, quæ percussa est in die plagæ pro sacrilegio Phogor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Postquam noxiorum sanguis effusus est, dixit Dominus ad Moysen et Eleazarum filium Aaron sacerdotem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Numerate omnem summam filiorum Israël a viginti annis et supra, per domos et cognationes suas, cunctos qui possunt ad bella procedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Locuti sunt itaque Moyses et Eleazar sacerdos, in campestribus Moab super Jordanem contra Jericho, ad eos qui erant');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'a viginti annis et supra, sicut Dominus imperaverat, quorum iste est numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben primogenitus Israël: hujus filius, Henoch, a quo familia Henochitarum: et Phallu, a quo familia Phalluitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'et Hesron, a quo familia Hesronitarum: et Charmi, a quo familia Charmitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Hæ sunt familiæ de stirpe Ruben: quarum numerus inventus est quadraginta tria millia, et septingenti triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Filius Phallu, Eliab:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'hujus filii, Namuel et Dathan et Abiron: isti sunt Dathan et Abiron principes populi, qui surrexerunt contra Moysen et Aaron in seditione Core, quando adversus Dominum rebellaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'et aperiens terra os suum devoravit Core, morientibus plurimis, quando combussit ignis ducentos quinquaginta viros. Et factum est grande miraculum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'ut, Core pereunte, filii illius non perirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Filii Simeon per cognationes suas: Namuel, ab hoc familia Namuelitarum: Jamin, ab hoc familia Jaminitarum: Jachin, ab hoc familia Jachinitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Zare, ab hoc familia Zareitarum: Saul, ab hoc familia Saulitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Hæ sunt familiæ de stirpe Simeon, quarum omnis numerus fuit viginti duo millia ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Filii Gad per cognationes suas: Sephon, ab hoc familia Sephonitarum: Aggi, ab hoc familia Aggitarum: Suni, ab hoc familia Sunitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Ozni, ab hoc familia Oznitarum: Her, ab hoc familia Heritarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, ab hoc familia Aroditarum: Ariel, ab hoc familia Arielitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Istæ sunt familiæ Gad, quarum omnis numerus fuit quadraginta millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Filii Juda, Her et Onan, qui ambo mortui sunt in terra Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Fueruntque filii Juda per cognationes suas: Sela, a quo familia Selaitarum: Phares, a quo familia Pharesitarum: Zare, a quo familia Zareitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Porro filii Phares: Hesron, a quo familia Hesronitarum: et Hamul, a quo familia Hamulitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Istæ sunt familiæ Juda, quarum omnis numerus fuit septuaginta sex millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Filii Issachar per cognationes suas: Thola, a quo familia Tholaitarum: Phua, a quo familia Phuaitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, a quo familia Jasubitarum: Semran, a quo familia Semranitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Hæ sunt cognationes Issachar, quarum numerus fuit sexaginta quatuor millia trecenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Filii Zabulon per cognationes suas: Sared, a quo familia Sareditarum: Elon, a quo familia Elonitarum: Jalel, a quo familia Jalelitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Hæ sunt cognationes Zabulon, quarum numerus fuit sexaginta millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Filii Joseph per cognationes suas, Manasse et Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'De Manasse ortus est Machir, a quo familia Machiritarum. Machir genuit Galaad, a quo familia Galaaditarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Galaad habuit filios: Jezer, a quo familia Jezeritarum: et Helec, a quo familia Helecitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'et Asriel, a quo familia Asrielitarum: et Sechem, a quo familia Sechemitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'et Semida, a quo familia Semidaitarum: et Hepher, a quo familia Hepheritarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Fuit autem Hepher pater Salphaad, qui filios non habebat, sed tantum filias: quarum ista sunt nomina: Maala, et Noa, et Hegla, et Melcha, et Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Hæ sunt familiæ Manasse, et numerus earum quinquaginta duo millia septingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Filii autem Ephraim per cognationes suas fuerunt hi: Suthala, a quo familia Suthalaitarum: Becher, a quo familia Becheritarum: Thehen, a quo familia Thehenitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Porro filius Suthala fuit Heran, a quo familia Heranitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Hæ sunt cognationes filiorum Ephraim: quarum numerus fuit triginta duo millia quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Isti sunt filii Joseph per familias suas. Filii Benjamin in cognationibus suis: Bela, a quo familia Belaitarum: Asbel, a quo familia Asbelitarum: Ahiram, a quo familia Ahiramitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Supham, a quo familia Suphamitarum: Hupham, a quo familia Huphamitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Filii Bela: Hered, et Noëman. De Hered, familia Hereditarum: de Noëman, familia Noëmanitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Hi sunt filii Benjamin per cognationes suas: quorum numerus fuit quadraginta quinque millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Filii Dan per cognationes suas: Suham, a quo familia Suhamitarum. Hæ sunt cognationes Dan per familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Omnes fuere Suhamitæ, quorum numerus erat sexaginta quatuor millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Filii Aser per cognationes suas: Jemna, a quo familia Jemnaitarum: Jessui, a quo familia Jessuitarum: Brie, a quo familia Brieitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Filii Brie: Heber, a quo familia Heberitarum: et Melchiel, a quo familia Melchielitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Nomen autem filiæ Aser fuit Sara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Hæ cognationes filiorum Aser, et numerus eorum quinquaginta tria millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Filii Nephthali per cognationes suas: Jesiel, a quo familia Jesielitarum: Guni, a quo familia Gunitarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jeser, a quo familia Jeseritarum: Sellem, a quo familia Sellemitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Hæ sunt cognationes filiorum Nephthali per familias suas: quorum numerus quadraginta quinque millia quadringenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ista est summa filiorum Israël, qui recensiti sunt, sexcenta millia, et mille septingenti triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Istis dividetur terra juxta numerum vocabulorum in possessiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Pluribus majorem partem dabis, et paucioribus minorem: singulis, sicut nunc recensiti sunt, tradetur possessio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'ita dumtaxat ut sors terram tribubus dividat et familiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Quidquid sorte contigerit, hoc vel plures accipiant, vel pauciores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Hic quoque est numerus filiorum Levi per familias suas: Gerson, a quo familia Gersonitarum: Caath, a quo familia Caathitarum: Merari, a quo familia Meraritarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Hæ sunt familiæ Levi: familia Lobni, familia Hebroni, familia Moholi, familia Musi, familia Core. At vero Caath genuit Amram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'qui habuit uxorem Jochabed filiam Levi, quæ nata est ei in \'gypto. Hæc genuit Amram viro suo filios, Aaron, et Moysen, et Mariam sororem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'De Aaron orti sunt Nadab et Abiu, et Eleazar et Ithamar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'quorum Nadab et Abiu mortui sunt, cum obtulissent ignem alienum coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Fueruntque omnes qui numerati sunt, viginti tria millia generis masculini ab uno mense et supra: quia non sunt recensiti inter filios Israël, nec eis cum ceteris data possessio est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Hic est numerus filiorum Israël, qui descripti sunt a Moyse et Eleazaro sacerdote, in campestribus Moab supra Jordanem contra Jericho:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'inter quos, nullus fuit eorum qui ante numerati sunt a Moyse et Aaron in deserto Sinai:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'prædixerat enim Dominus quod omnes morerentur in solitudine. Nullusque remansit ex eis, nisi Caleb filius Jephone, et Josue filius Nun.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Accesserunt autem filiæ Salphaad, filii Hepher, filii Galaad, filii Machir, filii Manasse, qui fuit filius Joseph: quarum sunt nomina, Maala, et Noa, et Hegla, et Melcha, et Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Steteruntque coram Moyse et Eleazaro sacerdote et cunctis principibus populi ad ostium tabernaculi fœderis, atque dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Pater noster mortuus est in deserto, nec fuit in seditione, quæ concitata est contra Dominum sub Core, sed in peccato suo mortuus est: hic non habuit mares filios. Cur tollitur nomen illius de familia sua, quia non habuit filium? date nobis possessionem inter cognatos patris nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Retulitque Moyses causam earum ad judicium Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Qui dixit ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Justam rem postulant filiæ Salphaad: da eis possessionem inter cognatos patris sui, et ei in hæreditatem succedant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Ad filios autem Israël loqueris hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Homo cum mortuus fuerit absque filio, ad filiam ejus transibit hæreditas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Si filiam non habuerit, habebit successores fratres suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Quod si et fratres non fuerint, dabitis hæreditatem fratribus patris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Sin autem nec patruos habuerit, dabitur hæreditas his qui ei proximi sunt. Eritque hoc filiis Israël sanctum lege perpetua, sicut præcepit Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Dixit quoque Dominus ad Moysen: Ascende in montem istum Abarim, et contemplare inde terram, quam daturus sum filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Cumque videris eam, ibis et tu ad populum tuum, sicut ivit frater tuus Aaron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'quia offendistis me in deserto Sin in contradictione multitudinis, nec sanctificare me voluistis coram ea super aquas. Hæ sunt aquæ contradictionis in Cades deserti Sin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Cui respondit Moyses:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Provideat Dominus Deus spirituum omnis carnis hominem, qui sit super multitudinem hanc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'et possit exire et intrare ante eos, et educere eos vel introducere: ne sit populus Domini sicut oves absque pastore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Dixitque Dominus ad eum: Tolle Josue filium Nun, virum in quo est spiritus, et pone manum tuam super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Qui stabit coram Eleazaro sacerdote et omni multitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'et dabis ei præcepta cunctis videntibus, et partem gloriæ tuæ, ut audiat eum omnis synagoga filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Pro hoc, si quid agendum erit, Eleazar sacerdos consulet Dominum. Ad verbum ejus egredietur et ingredietur ipse, et omnes filii Israël cum eo, et cetera multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Fecit Moyses ut præceperat Dominus: cumque tulisset Josue, statuit eum coram Eleazaro sacerdote et omni frequentia populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Et impositis capiti ejus manibus, cuncta replicavit quæ mandaverat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Dixit quoque Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Præcipe filiis Israël, et dices ad eos: Oblationem meam et panes, et incensum odoris suavissimi offerte per tempora sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Hæc sunt sacrificia quæ offerre debetis: agnos anniculos immaculatos duos quotidie in holocaustum sempiternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'unum offeretis mane, et alterum ad vesperum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'decimam partem ephi similæ, quæ conspersa sit oleo purissimo, et habeat quartam partem hin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Holocaustum juge est quod obtulistis in monte Sinai in odorem suavissimum incensi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Et libabitis vini quartam partem hin per agnos singulos in sanctuario Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Alterumque agnum similiter offeretis ad vesperam juxta omnem ritum sacrificii matutini, et libamentorum ejus, oblationem suavissimi odoris Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Die autem sabbati offeretis duos agnos anniculos immaculatos, et duas decimas similæ oleo conspersæ in sacrificio, et liba:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'quæ rite funduntur per singula sabbata in holocaustum sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'In calendis autem offeretis holocaustum Domino, vitulos de armento duos, arietem unum, agnos anniculos septem immaculatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'et tres decimas similæ oleo conspersæ in sacrificio per singulos vitulos: et duas decimas similæ oleo conspersæ per singulos arietes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'et decimam decimæ similæ ex oleo in sacrificio per agnos singulos: holocaustum suavissimi odoris atque incensi est Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Libamenta autem vini, quæ per singulas fundenda sunt victimas, ista erunt: media pars hin per singulos vitulos, tertia per arietem, quarta per agnum. Hoc erit holocaustum per omnes menses, qui sibi anno vertente succedunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Hircus quoque offeretur Domino pro peccatis in holocaustum sempiternum cum libamentis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Mense autem primo, quartadecima die mensis, Phase Domini erit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'et quintadecima die solemnitas: septem diebus vescentur azymis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Quarum dies prima venerabilis et sancta erit: omne opus servile non facietis in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Offeretisque incensum holocaustum Domino, vitulos de armento duos, arietem unum, agnos anniculos immaculatos septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'et sacrificia singulorum ex simila quæ conspersa sit oleo, tres decimas per singulos vitulos, et duas decimas per arietem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'et decimam decimæ per agnos singulos, id est, per septem agnos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Et hircum pro peccato unum, ut expietur pro vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'præter holocaustum matutinum, quod semper offeretis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Ita facietis per singulos dies septem dierum in fomitem ignis, et in odorem suavissimum Domino, qui surget de holocausto, et de libationibus singulorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Dies quoque septimus celeberrimus et sanctus erit vobis: omne opus servile non facietis in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Dies etiam primitivorum, quando offeretis novas fruges Domino, expletis hebdomadibus, venerabilis et sancta erit: omne opus servile non facietis in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Offeretisque holocaustum in odorem suavissimum Domino, vitulos de armento duos, arietem unum, et agnos anniculos immaculatos septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'atque in sacrificiis eorum, similæ oleo conspersæ tres decimas per singulos vitulos, per arietes duas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'per agnos decimam decimæ, qui simul sunt agni septem. Hircum quoque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'qui mactatur pro expiatione: præter holocaustum sempiternum et liba ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Immaculata offeretis omnia cum libationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Mensis etiam septimi prima dies venerabilis et sancta erit vobis. Omne opus servile non facietis in ea, quia dies clangoris est et tubarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Offeretisque holocaustum in odorem suavissimum Domino, vitulum de armento unum, arietem unum, et agnos anniculos immaculatos septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'et in sacrificiis eorum, similæ oleo conspersæ tres decimas per singulos vitulos, duas decimas per arietem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'unam decimam per agnum, qui simul sunt agni septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'et hircum pro peccato, qui offertur in expiationem populi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'præter holocaustum calendarum cum sacrificiis suis, et holocaustum sempiternum cum libationibus solitis: eisdem cæremoniis offeretis in odorem suavissimum incensum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Decima quoque dies mensis hujus septimi erit vobis sancta atque venerabilis, et affligetis animas vestras: omne opus servile non facietis in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Offeretisque holocaustum Domino in odorem suavissimum, vitulum de armento unum, arietem unum, agnos anniculos immaculatos septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'et in sacrificiis eorum similæ oleo conspersæ tres decimas per singulos vitulos, duas decimas per arietem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'decimam decimæ per agnos singulos, qui sunt simul agni septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'et hircum pro peccato, absque his quæ offerri pro delicto solent in expiationem, et holocaustum sempiternum, cum sacrificio et libaminibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Quintadecima vero die mensis septimi, quæ vobis sancta erit atque venerabilis, omne opus servile non facietis in ea, sed celebrabitis solemnitatem Domino septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Offeretisque holocaustum in odorem suavissimum Domino, vitulos de armento tredecim, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'et in libamentis eorum, similæ oleo conspersæ tres decimas per vitulos singulos, qui sunt simul vituli tredecim, et duas decimas arieti uno, id est, simul arietibus duobus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'et decimam decimæ agnis singulis, qui sunt simul agni quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'et hircum pro peccato, absque holocausto sempiterno, et sacrificio, et libamine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'In die altero offeretis vitulos de armento duodecim, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque et libamine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Die tertio offeretis vitulos undecim, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque et libamine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Die quarto offeretis vitulos decem, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque ejus et libamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Die quinto offeretis vitulos novem, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque ejus et libamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Die sexto offeretis vitulos octo, arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque ejus et libamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Die septimo offeretis vitulos septem, et arietes duos, agnos anniculos immaculatos quatuordecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque ejus et libamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Die octavo, qui est celeberrimus, omne opus servile non facietis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'offerentes holocaustum in odorem suavissimum Domino, vitulum unum, arietem unum, agnos anniculos immaculatos septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'sacrificiaque et libamina singulorum, per vitulos, et arietes, et agnos rite celebrabitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'et hircum pro peccato, absque holocausto sempiterno, sacrificioque ejus et libamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Hæc offeretis Domino in solemnitatibus vestris: præter vota et oblationes spontaneas in holocausto, in sacrificio, in libamine, et in hostiis pacificis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Narravitque Moyses filiis Israël omnia quæ ei Dominus imperarat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Et locutus est ad principes tribuum filiorum Israël: Iste est sermo quem præcepit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Si quis virorum votum Domino voverit, aut se constrinxerit juramento: non faciet irritum verbum suum, sed omne quod promisit, implebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Mulier si quippiam voverit, et se constrinxerit juramento, quæ est in domo patris sui, et in ætate adhuc puellari: si cognoverit pater votum quod pollicita est, et juramentum quo obligavit animam suam, et tacuerit, voti rea erit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'quidquid pollicita est, et juravit, opere complebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Sin autem statim ut audierit, contradixerit pater: et vota et juramenta ejus irrita erunt, nec obnoxia tenebitur sponsioni, eo quod contradixerit pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Si maritum habuerit, et voverit aliquid, et semel de ore ejus verbum egrediens animam ejus obligaverit juramento:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'quo die audierit vir, et non contradixerit, voti rea erit, reddetque quodcumque promiserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Sin autem audiens statim contradixerit, et irritas fecerit pollicitationes ejus, verbaque quibus obstrinxerat animam suam, propitius erit ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Vidua et repudiata quidquid voverint, reddent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Uxor in domo viri cum se voto constrinxerit et juramento,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'si audierit vir, et tacuerit, nec contradixerit sponsioni, reddet quodcumque promiserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Sin autem extemplo contradixerit, non tenebitur promissionis rea: quia maritus contradixit, et Dominus ei propitius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Si voverit, et juramento se constrinxerit, ut per jejunium, vel ceterarum rerum abstinentiam affligat animam suam, in arbitrio viri erit ut faciat, sive non faciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Quod si audiens vir tacuerit, et in alteram diem distulerit sententiam, quidquid voverat atque promiserat, reddet: quia statim ut audivit, tacuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Sin autem contradixerit postquam rescivit, portabit ipse iniquitatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Istæ sunt leges, quas constituit Dominus Moysi inter virum et uxorem, inter patrem et filiam, quæ in puellari adhuc ætate est, vel quæ manet in parentis domo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Ulciscere prius filios Israël de Madianitis, et sic colligeris ad populum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Statimque Moyses: Armate, inquit, ex vobis viros ad pugnam, qui possint ultionem Domini expetere de Madianitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Mille viri de singulis tribubus eligantur ex Israël qui mittantur ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Dederuntque millenos de singulis tribubus, id est, duodecim millia expeditorum ad pugnam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'quos misit Moyses cum Phinees filio Eleazari sacerdotis, vasa quoque sancta, et tubas ad clangendum tradidit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Cumque pugnassent contra Madianitas atque vicissent, omnes mares occiderunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'et reges eorum, Evi, et Recem, et Sur, et Hur, et Rebe, quinque principes gentis: Balaam quoque filium Beor interfecerunt gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Ceperuntque mulieres eorum, et parvulos, omniaque pecora, et cunctam supellectilem: quidquid habere potuerant depopulati sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'tam urbes quam viculos et castella flamma consumpsit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Et tulerunt prædam, et universa quæ ceperant tam ex hominibus quam ex jumentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'et adduxerunt ad Moysen, et Eleazarum sacerdotem, et ad omnem multitudinem filiorum Israël: reliqua autem utensilia portaverunt ad castra in campestribus Moab juxta Jordanem contra Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Egressi sunt autem Moyses et Eleazar sacerdos, et omnes principes synagogæ, in occursum eorum extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Iratusque Moyses principibus exercitus, tribunis, et centurionibus qui venerant de bello,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'ait: Cur feminas reservastis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'nonne istæ sunt, quæ deceperunt filios Israël ad suggestionem Balaam, et prævaricari vos fecerunt in Domino super peccato Phogor, unde et percussus est populus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'ergo cunctos interficite quidquid est generis masculini, etiam in parvulis: et mulieres, quæ noverunt viros in coitu, jugulate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'puellas autem et omnes feminas virgines reservate vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'et manete extra castra septem diebus. Qui occiderit hominem, vel occisum tetigerit, lustrabitur die tertio et septimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Et de omni præda, sive vestimentum fuerit, sive vas, et aliquid in utensilia præparatum, de caprarum pellibus, et pilis, et ligno, expiabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Eleazar quoque sacerdos ad viros exercitus, qui pugnaverunt, sic locutus est: Hoc est præceptum legis, quod mandavit Dominus Moysi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'aurum, et argentum, et æs, et ferrum, et plumbum, et stannum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'et omne, quod potest transire per flammas, igne purgabitur: quidquid autem ignem non potest sustinere, aqua expiationis sanctificabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'et lavabitis vestimenta vestra die septimo, et purificati postea castra intrabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Dixit quoque Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Tollite summam eorum quæ capta sunt, ab homine usque ad pecus, tu et Eleazar sacerdos et principes vulgi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'dividesque ex æquo prædam inter eos qui pugnaverunt egressique sunt ad bellum, et inter omnem reliquam multitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Et separabis partem Domino ab his qui pugnaverunt et fuerunt in bello, unam animam de quingentis, tam ex hominibus quam ex bobus et asinis et ovibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'et dabis eam Eleazaro sacerdoti, quia primitiæ Domini sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Ex media quoque parte filiorum Israël accipies quinquagesimum caput hominum, et boum, et asinorum, et ovium, cunctorum animantium, et dabis ea Levitis, qui excubant in custodiis tabernaculi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Feceruntque Moyses et Eleazar sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Fuit autem præda, quam exercitus ceperat, ovium sexcenta septuaginta quinque millia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'boum septuaginta duo millia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'asinorum sexaginta millia et mille:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'animæ hominum sexus feminei, quæ non cognoverant viros, triginta duo millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Dataque est media pars his qui in prælio fuerant, ovium trecenta triginta septem millia quingentæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'e quibus in partem Domini supputatæ sunt oves sexcentæ septuaginta quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'et de bobus triginta sex millibus, boves septuaginta et duo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'de asinis triginta millibus quingentis, asini sexaginta unus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'de animabus hominum sedecim millibus, cesserunt in partem Domini triginta duæ animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Tradiditque Moyses numerum primitiarum Domini Eleazaro sacerdoti, sicut fuerat ei imperatum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'ex media parte filiorum Israël, quam separaverat his qui in prælio fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'De media vero parte, quæ contigerat reliquæ multitudini, id est, de ovibus trecentis triginta septem millibus quingentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'et de bobus triginta sex millibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'et de asinis triginta millibus quingentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'et de hominibus sedecim millibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'tulit Moyses quinquagesimum caput, et dedit Levitis, qui excubabant in tabernaculo Domini, sicut præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Cumque accessissent principes exercitus ad Moysen, et tribuni, centurionesque, dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Nos servi tui recensuimus numerum pugnatorum, quos habuimus sub manu nostra: et ne unus quidem defuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Ob hanc causam offerimus in donariis Domini singuli quod in præda auri potuimus invenire, periscelides et armillas, annulos et dextralia, ac murænulas, ut depreceris pro nobis Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Susceperuntque Moyses et Eleazar sacerdos omne aurum in diversis speciebus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'pondo sedecim millia septingentos quinquaginta siclos, a tribunis et centurionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Unusquisque enim quod in præda rapuerat, suum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Et susceptum intulerunt in tabernaculum testimonii, in monimentum filiorum Israël coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Filii autem Ruben et Gad habebant pecora multa, et erat illis in jumentis infinita substantia. Cumque vidissent Jazer et Galaad aptas animalibus alendis terras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'venerunt ad Moysen, et ad Elezarum sacerdotem, et principes multitudinis, atque dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth, et Dibon, et Jazer, et Nemra, Hesebon, et Eleale, et Saban, et Nebo, et Beon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'terra, quam percussit Dominus in conspectu filiorum Israël, regio uberrima est ad pastum animalium: et nos servi tui habemus jumenta plurima,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'precamurque si invenimus gratiam coram te, ut des nobis famulis tuis eam in possessionem, nec facias nos transire Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Quibus respondit Moyses: Numquid fratres vestri ibunt ad pugnam, et vos hic sedebitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'cur subvertitis mentes filiorum Israël, ne transire audeant in locum, quem eis daturus est Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Nonne ita egerunt patres vestri, quando misi de Cadesbarne ad explorandam terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'cumque venissent usque ad Vallem botri, lustrata omni regione, subverterunt cor filiorum Israël, ut non intrarent fines, quos eis Dominus dedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Qui iratus juravit, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Si videbunt homines isti, qui ascenderunt ex \'gypto a viginti annis et supra, terram, quam sub juramento pollicitus sum Abraham, Isaac, et Jacob: et noluerunt sequi me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'præter Caleb filium Jephone Cenezæum, et Josue filium Nun: isti impleverunt voluntatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Iratusque Dominus adversum Israël, circumduxit eum per desertum quadraginta annis, donec consumeretur universa generatio, quæ fecerat malum in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Et ecce, inquit, vos surrexistis pro patribus vestris, incrementa et alumni hominum peccatorum, ut augeretis furorem Domini contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Quod si nolueritis sequi eum, in solitudine populum derelinquet, et vos causa eritis necis omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'At illi prope accedentes, dixerunt: Caulas ovium fabricabimus, et stabula jumentorum, parvulis quoque nostris urbes munitas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'nos autem ipsi armati et accincti pergemus ad prælium ante filios Israël, donec introducamus eos ad loca sua. Parvuli nostri, et quidquid habere possumus, erunt in urbibus muratis, propter habitatorum insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Non revertemur in domos nostras, usque dum possideant filii Israël hæreditatem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'nec quidquam quæremus trans Jordanem, quia jam habemus nostram possessionem in orientali ejus plaga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Quibus Moyses ait: Si facitis quod promittitis, expediti pergite coram Domino ad pugnam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'et omnis vir bellator armatus Jordanem transeat, donec subvertat Dominus inimicos suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'et subjiciatur ei omnis terra: tunc eritis inculpabiles apud Dominum et apud Israël, et obtinebitis regiones, quas vultis, coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Sin autem quod dicitis, non feceritis, nulli dubium est quin peccetis in Deum: et scitote quoniam peccatum vestrum apprehendet vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, '\'dificate ergo urbes parvulis vestris, et caulas, et stabula ovibus ac jumentis: et quod polliciti estis, implete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Dixeruntque filii Gad et Ruben ad Moysen: Servi tui sumus: faciemus quod jubet dominus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Parvulos nostros, et mulieres, et pecora, ac jumenta relinquemus in urbibus Galaad:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'nos autem famuli tui omnes expediti pergemus ad bellum, sicut tu, domine, loqueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Præcepit ergo Moyses Eleazaro sacerdoti, et Josue filio Nun, et principibus familiarum per tribus Israël, et dixit ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Si transierint filii Gad et filii Ruben vobiscum Jordanem omnes armati ad bellum coram Domino, et vobis fuerit terra subjecta, date eis Galaad in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Sin autem noluerint transire armati vobiscum in terram Chanaan, inter vos habitandi accipiant loca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Responderuntque filii Gad et filii Ruben: Sicut locutus est Dominus servis suis, ita faciemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'ipsi armati pergemus coram Domino in terram Chanaan, et possessionem jam suscepisse nos confitemur trans Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Dedit itaque Moyses filiis Gad et Ruben, et dimidiæ tribui Manasse filii Joseph, regnum Sehon regis Amorrhæi, et regnum Og regis Basan, et terram eorum cum urbibus suis per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Igitur exstruxerunt filii Gad, Dibon, et Ataroth, et Aroër,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'et Etroth, et Sophan, et Jazer, et Jegbaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'et Bethnemra, et Betharan, urbes munitas, et caulas pecoribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Filii vero Ruben ædificaverunt Hesebon, et Eleale, et Cariathaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'et Nabo, et Baalmeon versis nominibus, Sabama quoque: imponentes vocabula urbibus, quas exstruxerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Porro filii Machir filii Manasse, perrexerunt in Galaad, et vastaverunt eam interfecto Amorrhæo habitatore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Dedit ergo Moyses terram Galaad Machir filio Manasse, qui habitavit in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair autem filius Manasse abiit, et occupavit vicos ejus, quos appellavit Havoth Jair, id est, Villas Jair.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobe quoque perrexit, et apprehendit Chanath cum viculis suis: vocavitque eam ex nomine suo Nobe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Hæ sunt mansiones filiorum Israël, qui egressi sunt de \'gypto per turmas suas in manu Moysi et Aaron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'quas descripsit Moyses juxta castrorum loca, quæ Domini jussione mutabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Profecti igitur de Ramesse mense primo, quintadecima die mensis primi, altera die Phase, filii Israël in manu excelsa, videntibus cunctis \'gyptiis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'et sepelientibus primogenitos, quos percusserat Dominus (nam et in diis eorum exercuerat ultionem),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'castrametati sunt in Soccoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Et de Soccoth venerunt in Etham, quæ est in extremis finibus solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Inde egressi venerunt contra Phihahiroth, quæ respicit Beelsephon, et castrametati sunt ante Magdalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Profectique de Phihahiroth, transierunt per medium mare in solitudinem: et ambulantes tribus diebus per desertum Etham, castrametati sunt in Mara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Profectique de Mara, venerunt in Elim, ubi erant duodecim fontes aquarum, et palmæ septuaginta: ibique castrametati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Sed et inde egressi, fixerunt tentoria super mare Rubrum. Profectique de mari Rubro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'castrametati sunt in deserto Sin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Unde egressi, venerunt in Daphca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Profectique de Daphca, castrametati sunt in Alus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Egressique de Alus, in Raphidim fixere tentoria, ubi populo defuit aqua ad bibendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Profectique de Raphidim, castrametati sunt in deserto Sinai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Sed et de solitudine Sinai egressi, venerunt ad sepulchra concupiscentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Profectique de sepulchris concupiscentiæ, castrametati sunt in Haseroth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Et de Haseroth venerunt in Rethma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Profectique de Rethma, castrametati sunt in Remmomphares.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Unde egressi venerunt in Lebna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'De Lebna castrametati sunt in Ressa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Egressique de Ressa, venerunt in Ceelatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Unde profecti, castrametati sunt in monte Sepher.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Egressi de monte Sepher, venerunt in Arada.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Inde proficiscentes, castrametati sunt in Maceloth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Profectique de Maceloth, venerunt in Thahath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'De Thahath, castrametati sunt in Thare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Unde egressi, fixere tentoria in Methca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Et de Methca, castrametati sunt in Hesmona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Profectique de Hesmona, venerunt in Moseroth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Et de Moseroth, castrametati sunt in Benejaacan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Profectique de Benejaacan, venerunt in montem Gadgad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Unde profecti, castrametati sunt in Jetebatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Et de Jetebatha venerunt in Hebrona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Egressique de Hebrona, castrametati sunt in Asiongaber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Inde profecti, venerunt in desertum Sin, hæc est Cades.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Egressique de Cades, castrametati sunt in monte Hor, in extremis finibus terræ Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Ascenditque Aaron sacerdos in montem Hor jubente Domino: et ibi mortuus est anno quadragesimo egressionis filiorum Israël ex \'gypto, mense quinto, prima die mensis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'cum esset annorum centum viginti trium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Audivitque Chananæus rex Arad, qui habitabat ad meridiem, in terram Chanaan venisse filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Et profecti de monte Hor, castrametati sunt in Salmona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Unde egressi, venerunt in Phunon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Profectique de Phunon, castrametati sunt in Oboth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Et de Oboth venerunt in Ijeabarim, quæ est in finibus Moabitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Profectique de Ijeabarim, fixere tentoria in Dibongad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Unde egressi, castrametati sunt in Helmondeblathaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Egressique de Helmondeblathaim, venerunt ad montes Abarim contra Nabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Profectique de montibus Abarim, transierunt ad campestria Moab, supra Jordanem, contra Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Ibique castrametati sunt de Bethsimoth usque ad Abelsatim in planioribus locis Moabitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Ubi locutus est Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Præcipe filiis Israël, et dic ad eos: Quando transieritis Jordanem, intrantes terram Chanaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'disperdite cunctos habitatores terræ illius: confringite titulos, et statuas comminuite, atque omnia excelsa vastate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'mundantes terram, et habitantes in ea. Ego enim dedi vobis illam in possessionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'quam dividetis vobis sorte. Pluribus dabitis latiorem, et paucis angustiorem. Singulis ut sors ceciderit, ita tribuetur hæreditas. Per tribus et familias possessio dividetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Sin autem nolueritis interficere habitatores terræ: qui remanserint, erunt vobis quasi clavi in oculis, et lanceæ in lateribus, et adversabuntur vobis in terra habitationis vestræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'et quidquid illis cogitaveram facere, vobis faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Locutusque est Dominus ad Moysen, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Præcipe filiis Israël, et dices ad eos: Cum ingressi fueritis terram Chanaan, et in possessionem vobis sorte ceciderit, his finibus terminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Pars meridiana incipiet a solitudine Sin, quæ est juxta Edom: et habebit terminos contra orientem mare salsissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Qui circuibunt australem plagam per ascensum Scorpionis, ita ut transeant in Senna, et perveniant a meridie usque ad Cadesbarne, unde egredientur confinia ad villam nomine Adar, et tendent usque ad Asemona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Ibitque per gyrum terminus ab Asemona usque ad torrentem \'gypti, et maris magni littore finietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Plaga autem occidentalis a mari magno incipiet, et ipso fine claudetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Porro ad septentrionalem plagam a mari magno termini incipient, pervenientes usque ad montem altissimum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'a quo venient in Emath usque ad terminos Sedada:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'ibuntque confinia usque ad Zephrona, et villam Enan. Hi erunt termini in parte aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Inde metabuntur fines contra orientalem plagam de villa Enan usque Sephama,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'et de Sephama descendent termini in Rebla contra fontem Daphnim: inde pervenient contra orientem ad mare Cenereth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'et tendent usque ad Jordanem, et ad ultimum salsissimo claudentur mari. Hanc habebitis terram per fines suos in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Præcepitque Moyses filiis Israël, dicens: Hæc erit terra, quam possidebitis sorte, et quam jussit Dominus dari novem tribubus, et dimidiæ tribui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Tribus enim filiorum Ruben per familias suas, et tribus filiorum Gad juxta cognationum numerum, media quoque tribus Manasse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'id est, duæ semis tribus, acceperunt partem suam trans Jordanem contra Jericho ad orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Et ait Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Hæc sunt nomina virorum qui terram vobis divident, Eleazar sacerdos, et Josue filius Nun,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'et singuli principes de tribubus singulis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'quorum ista sunt vocabula. De tribu Juda, Caleb filius Jephone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'De tribu Simeon, Samuel filius Ammiud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'De tribu Benjamin, Elidad filius Chaselon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'De tribu filiorum Dan, Bocci filius Jogli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Filiorum Joseph de tribu Manasse, Hanniel filius Ephod.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'De tribu Ephraim, Camuel filius Sephthan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'De tribu Zabulon, Elisaphan filius Pharnach.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'De tribu Issachar, dux Phaltiel filius Ozan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'De tribu Aser, Ahiud filius Salomi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'De tribu Nephthali, Phedaël filius Ammiud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Hi sunt, quibus præcepit Dominus ut dividerent filiis Israël terram Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Hæc quoque locutus est Dominus ad Moysen in campestribus Moab supra Jordanem, contra Jericho:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Præcipe filiis Israël ut dent Levitis de possessionibus suis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'urbes ad habitandum, et suburbana earum per circuitum: ut ipsi in oppidis maneant, et suburbana sint pecoribus ac jumentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'quæ a muris civitatum forinsecus, per circuitum, mille passuum spatio tendentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Contra orientem duo millia erunt cubiti, et contra meridiem similiter erunt duo millia: ad mare quoque, quod respicit ad occidentem, eadem mensura erit, et septentrionalis plaga æquali termino finietur, eruntque urbes in medio, et foris suburbana.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'De ipsis autem oppidis, quæ Levitis dabitis, sex erunt in fugitivorum auxilia separata, ut fugiat ad ea qui fuderit sanguinem: et exceptis his, alia quadraginta duo oppida,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'id est, simul quadraginta octo cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Ipsæque urbes, quæ dabuntur de possessionibus filiorum Israël, ab his qui plus habent, plures auferentur: et qui minus, pauciores: singuli juxta mensuram hæreditatis suæ dabunt oppida Levitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Ait Dominus ad Moysen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Loquere filiis Israël, et dices ad eos: Quando transgressi fueritis Jordanem in terram Chanaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'decernite quæ urbes esse debeant in præsidia fugitivorum, qui nolentes sanguinem fuderint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'in quibus cum fuerit profugus, cognatus occisi non poterit eum occidere, donec stet in conspectu multitudinis, et causa illius judicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'De ipsis autem urbibus, quæ ad fugitivorum subsidia separantur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'tres erunt trans Jordanem, et tres in terra Chanaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'tam filiis Israël quam advenis atque peregrinis, ut confugiat ad eas qui nolens sanguinem fuderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Si quis ferro percusserit, et mortuus fuerit qui percussus est, reus erit homicidii, et ipse morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Si lapidem jecerit, et ictus occubuerit, similiter punietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Si ligno percussus interierit, percussoris sanguine vindicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Propinquus occisi, homicidam interficiet: statim ut apprehenderit eum, interficiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Si per odium quis hominem impulerit, vel jecerit quippiam in eum per insidias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'aut cum esset inimicus, manu percusserit, et ille mortuus fuerit: percussor homicidii reus erit: cognatus occisi statim ut invenerit eum, jugulabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Quod si fortuitu, et absque odio');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'et inimicitiis quidquam horum fecerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'et hoc audiente populo fuerit comprobatum, atque inter percussorem et propinquum sanguinis quæstio ventilata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'liberabitur innocens de ultoris manu, et reducetur per sententiam in urbem, ad quam confugerat, manebitque ibi, donec sacerdos magnus, qui oleo sancto unctus est, moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Si interfector extra fines urbium, quæ exulibus deputatæ sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'fuerit inventus, et percussus ab eo qui ultor est sanguinis: absque noxa erit qui eum occiderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Debuerat enim profugus usque ad mortem pontificis in urbe residere. Postquam autem ille obierit, homicida revertetur in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Hæc sempiterna erunt, et legitima in cunctis habitationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Homicida sub testibus punietur: ad unius testimonium nullus condemnabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Non accipietis pretium ab eo qui reus est sanguinis, statim et ipse morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Exules et profugi ante mortem pontificis nullo modo in urbes suas reverti poterunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'ne polluatis terram habitationis vestræ, quæ insontium cruore maculatur: nec aliter expiari potest, nisi per ejus sanguinem, qui alterius sanguinem fuderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Atque ita emundabitur vestra possessio me commorante vobiscum. Ego enim sum Dominus qui habito inter filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Accesserunt autem et principes familiarum Galaad filii Machir filii Manasse, de stirpe filiorum Joseph: locutique sunt Moysi coram principibus Israël, atque dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Tibi domino nostro præcepit Dominus ut terram sorte divideres filiis Israël, et ut filiabus Salphaad fratris nostri dares possessionem debitam patri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'quas si alterius tribus homines uxores acceperint, sequetur possessio sua, et translata ad aliam tribum, de nostra hæreditate minuetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Atque ita fiet, ut cum jubilæus, id est, quinquagesimus annus remissionis advenerit, confundatur sortium distributio, et aliorum possessio ad alios transeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Respondit Moyses filiis Israël, et Domino præcipiente ait: Recte tribus filiorum Joseph locuta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Et hæc lex super filiabus Salphaad a Domino promulgata est: nubant quibus volunt, tantum ut suæ tribus hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'ne commisceatur possessio filiorum Israël de tribu in tribum. Omnes enim viri ducent uxores de tribu et cognatione sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'et cunctæ feminæ de eadem tribu maritos accipient: ut hæreditas permaneat in familiis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'nec sibi misceantur tribus, sed ita maneant');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'ut a Domino separatæ sunt. Feceruntque filiæ Salphaad ut fuerat imperatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'et nupserunt Maala, et Thersa, et Hegla, et Melcha, et Noa, filiis patrui sui');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'de familia Manasse, qui fuit filius Joseph: et possessio, quæ illis fuerat attributa, mansit in tribu et familia patris earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Hæc sunt mandata atque judicia, quæ mandavit Dominus per manum Moysi ad filios Israël, in campestribus Moab supra Jordanem contra Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Hæc sunt verba quæ locutus est Moyses ad omnem Israël trans Jordanem in solitudine campestri, contra mare Rubrum, inter Pharan et Tophel et Laban et Haseroth, ubi auri est plurimum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'undecim diebus de Horeb per viam montis Seir usque ad Cadesbarne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Quadragesimo anno, undecimo mense, prima die mensis, locutus est Moyses ad filios Israël omnia quæ præceperat illi Dominus, ut diceret eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'postquam percussit Sehon regem Amorrhæorum, qui habitabat in Hesebon, et Og regem Basan, qui mansit in Astaroth, et in Edrai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'trans Jordanem in terra Moab. Cœpitque Moyses explanare legem, et dicere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Dominus Deus noster locutus est ad nos in Horeb, dicens: Sufficit vobis quod in hoc monte mansistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'revertimini, et venite ad montem Amorrhæorum, et ad cetera quæ ei proxima sunt campestria atque montana et humiliora loca contra meridiem, et juxta littus maris, terram Chananæorum, et Libani usque ad flumen magnum Euphraten.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'En, inquit, tradidi vobis: ingredimini et possidete eam, super qua juravit Dominus patribus vestris Abraham, Isaac, et Jacob, ut daret illam eis, et semini eorum post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Dixique vobis illo in tempore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Non possum solus sustinere vos: quia Dominus Deus vester multiplicavit vos, et estis hodie sicut stellæ cæli, plurimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '(Dominus Deus patrum vestrorum addat ad hunc numerum multa millia, et benedicat vobis sicut locutus est.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Non valeo solus negotia vestra sustinere, et pondus ac jurgia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Date ex vobis viros sapientes et gnaros, et quorum conversatio sit probata in tribubus vestris, ut ponam eos vobis principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Tunc respondistis mihi: Bona res est, quam vis facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Tulique de tribubus vestris viros sapientes et nobiles, et constitui eos principes, tribunos, et centuriones, et quinquagenarios ac decanos, qui docerent vos singula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Præcepique eis, dicens: Audite illos, et quod justum est judicate: sive civis sit ille, sive peregrinus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Nulla erit distantia personarum: ita parvum audietis ut magnum, nec accipietis cujusquam personam, quia Dei judicium est. Quod si difficile vobis visum aliquid fuerit, referte ad me, et ego audiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Præcepique omnia quæ facere deberetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Profecti autem de Horeb, transivimus per eremum terribilem et maximam, quam vidistis, per viam montis Amorrhæi, sicut præceperat Dominus Deus noster nobis. Cumque venissemus in Cadesbarne,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'dixi vobis: Venistis ad montem Amorrhæi, quem Dominus Deus noster daturus est nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'vide terram, quam Dominus Deus tuus dat tibi: ascende et posside eam, sicut locutus est Dominus Deus noster patribus tuis: noli timere, nec quidquam paveas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Et accessistis ad me omnes, atque dixistis: Mittamus viros qui considerent terram: et renuntient per quod iter debeamus ascendere, et ad quas pergere civitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Cumque mihi sermo placuisset, misi ex vobis duodecim viros, singulos de tribubus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Qui cum perrexissent, et ascendissent in montana, venerunt usque ad Vallem botri: et considerata terra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'sumentes de fructibus ejus, ut ostenderent ubertatem, attulerunt ad nos, atque dixerunt: Bona est terra, quam Dominus Deus noster daturus est nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Et noluistis ascendere, sed increduli ad sermonem Domini Dei nostri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'murmurastis in tabernaculis vestris, atque dixistis: Odit nos Dominus, et idcirco eduxit nos de terra \'gypti, ut traderet nos in manu Amorrhæi, atque deleret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Quo ascendemus? nuntii terruerunt cor nostrum, dicentes: Maxima multitudo est, et nobis statura procerior; urbes magnæ, et ad cælum usque munitæ: filios Enacim vidimus ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Et dixi vobis: Nolite metuere, nec timeatis eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Dominus Deus, qui ductor est vester, pro vobis ipse pugnabit, sicut fecit in \'gypto cunctis videntibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Et in solitudine (ipse vidisti) portavit te Dominus Deus tuus, ut solet homo gestare parvulum filium suum, in omni via per quam ambulastis, donec veniretis ad locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Et nec sic quidem credidistis Domino Deo vestro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'qui præcessit vos in via, et metatus est locum in quo tentoria figere deberetis, nocte ostendens vobis iter per ignem, et die per columnam nubis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Cumque audisset Dominus vocem sermonum vestrorum, iratus juravit, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Non videbit quispiam de hominibus generationis hujus pessimæ terram bonam, quam sub juramento pollicitus sum patribus vestris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'præter Caleb filium Jephone: ipse enim videbit eam, et ipsi dabo terram, quam calcavit, et filiis ejus, quia secutus est Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Nec miranda indignatio in populum, cum mihi quoque iratus Dominus propter vos dixerit: Nec tu ingredieris illuc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'sed Josue filius Nun minister tuus, ipse intrabit pro te. Hunc exhortare et robora, et ipse sorte terram dividet Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Parvuli vestri, de quibus dixistis quod captivi ducerentur, et filii qui hodie boni ac mali ignorant distantiam, ipsi ingredientur: et ipsis dabo terram, et possidebunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Vos autem revertimini, et abite in solitudinem per viam maris Rubri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Et respondistis mihi: Peccavimus Domino: ascendemus et pugnabimus, sicut præcepit Dominus Deus noster. Cumque instructi armis pergeretis in montem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'ait mihi Dominus: Dic ad eos: Nolite ascendere, neque pugnetis: non enim sum vobiscum: ne cadatis coram inimicis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Locutus sum, et non audistis: sed adversantes imperio Domini, et tumentes superbia, ascendistis in montem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Itaque egressus Amorrhæus, qui habitabat in montibus, et obviam veniens, persecutus est vos, sicut solent apes persequi: et cecidit de Seir usque Horma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Cumque reversi ploraretis coram Domino, non audivit vos, nec voci vestræ voluit acquiescere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Sedistis ergo in Cadesbarne multo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Profectique inde, venimus in solitudinem, quæ ducit ad mare Rubrum, sicut mihi dixerat Dominus: et circuivimus montem Seir longo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Dixitque Dominus ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Sufficit vobis circuire montem istum: ite contra aquilonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'et populo præcipe, dicens: Transibitis per terminos fratrum vestrorum filiorum Esau, qui habitant in Seir, et timebunt vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Videte ergo diligenter ne moveamini contra eos. Neque enim dabo vobis de terra eorum quantum potest unius pedis calcare vestigium, quia in possessionem Esau dedi montem Seir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Cibos emetis ab eis pecunia, et comedetis: aquam emptam haurietis, et bibetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Dominus Deus tuus benedixit tibi in omni opere manuum tuarum: novit iter tuum, quomodo transieris solitudinem hanc magnam, per quadraginta annos habitans tecum Dominus Deus tuus, et nihil tibi defuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Cumque transissemus fratres nostros filios Esau, qui habitabant in Seir, per viam campestrem de Elath, et de Asiongaber, venimus ad iter quod ducit in desertum Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Dixitque Dominus ad me: Non pugnes contra Moabitas, nec ineas adversus eos prælium: non enim dabo tibi quidquam de terra eorum, quia filiis Loth tradidi Ar in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Emim primi fuerunt habitatores ejus, populus magnus, et validus, et tam excelsus ut de Enacim stirpe,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'quasi gigantes crederentur, et essent similes filiorum Enacim. Denique Moabitæ appellant eos Emim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'In Seir autem prius habitaverunt Horrhæi: quibus expulsis atque deletis, habitaverunt filii Esau, sicut fecit Israël in terra possessionis suæ, quam dedit illi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Surgentes ergo ut transiremus torrentem Zared, venimus ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Tempus autem, quo ambulavimus de Cadesbarne usque ad transitum torrentis Zared, triginta et octo annorum fuit: donec consumeretur omnis generatio hominum bellatorum de castris, sicut juraverat Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'cujus manus fuit adversum eos, ut interirent de castrorum medio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Postquam autem universi ceciderunt pugnatores,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'locutus est Dominus ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu transibis hodie terminos Moab, urbem nomine Ar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'et accedens in vicina filiorum Ammon, cave ne pugnes contra eos, nec movearis ad prælium: non enim dabo tibi de terra filiorum Ammon, quia filiis Loth dedi eam in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Terra gigantum reputata est: et in ipsa olim habitaverunt gigantes, quos Ammonitæ vocant Zomzommim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'populus magnus, et multus, et proceræ longitudinis, sicut Enacim, quos delevit Dominus a facie eorum: et fecit illos habitare pro eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'sicut fecerat filiis Esau, qui habitant in Seir, delens Horrhæos, et terram eorum illis tradens, quam possident usque in præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Hevæos quoque, qui habitabant in Haserim usque Gazan, Cappadoces expulerunt: qui egressi de Cappadocia deleverunt eos, et habitaverunt pro illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Surgite, et transite torrentem Arnon: ecce tradidi in manu tua Sehon regem Hesebon Amorrhæum, et terram ejus incipe possidere, et committe adversus eum prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Hodie incipiam mittere terrorem atque formidinem tuam in populos, qui habitant sub omni cælo: ut audito nomine tuo paveant, et in morem parturientium contremiscant, et dolore teneantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Misi ergo nuntios de solitudine Cademoth ad Sehon regem Hesebon verbis pacificis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Transibimus per terram tuam: publica gradiemur via; non declinabimus neque ad dexteram, neque ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Alimenta pretio vende nobis, ut vescamur: aquam pecunia tribue, et sic bibemus. Tantum est ut nobis concedas transitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'sicut fecerunt filii Esau, qui habitant in Seir, et Moabitæ, qui morantur in Ar: donec veniamus ad Jordanem, et transeamus ad terram, quam Dominus Deus noster daturus est nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Noluitque Sehon rex Hesebon dare nobis transitum: quia induraverat Dominus Deus tuus spiritum ejus, et obfirmaverat cor illius, ut traderetur in manus tuas, sicut nunc vides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Dixitque Dominus ad me: Ecce cœpi tibi tradere Sehon, et terram ejus: incipe possidere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Egressusque est Sehon obviam nobis cum omni populo suo ad prælium in Jasa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Et tradidit eum Dominus Deus noster nobis: percussimusque eum cum filiis suis et omni populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Cunctasque urbes in tempore illo cepimus, interfectis habitatoribus earum, viris ac mulieribus et parvulis: non reliquimus in eis quidquam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'absque jumentis, quæ in partem venere prædantium: et spoliis urbium, quas cepimus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'ab Aroër, quæ est super ripam torrentis Arnon, oppido quod in valle situm est, usque Galaad. Non fuit vicus et civitas, quæ nostras effugeret manus: omnes tradidit Dominus Deus noster nobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'absque terra filiorum Ammon, ad quam non accessimus: et cunctis quæ adjacent torrenti Jeboc, et urbibus montanis, universisque locis, a quibus nos prohibuit Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Itaque conversi ascendimus per iter Basan: egressusque est Og rex Basan in occursum nobis cum populo suo ad bellandum in Edrai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Dixitque Dominus ad me: Ne timeas eum: quia in manu tua traditus est cum omni populo ac terra sua: faciesque ei sicut fecisti Sehon regi Amorrhæorum, qui habitavit in Hesebon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Tradidit ergo Dominus Deus noster in manibus nostris etiam Og regem Basan, et universum populum ejus: percussimusque eos usque ad internecionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'vastantes cunctas civitates illius uno tempore. Non fuit oppidum, quod nos effugeret: sexaginta urbes, omnem regionem Argob regni Og in Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Cunctæ urbes erant munitæ muris altissimis, portisque et vectibus, absque oppidis innumeris, quæ non habebant muros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Et delevimus eos, sicut feceramus Sehon regi Hesebon, disperdentes omnem civitatem, virosque ac mulieres et parvulos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'jumenta autem et spolia urbium diripuimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Tulimusque illo in tempore terram de manu duorum regum Amorrhæorum, qui erant trans Jordanem: a torrente Arnon usque ad montem Hermon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'quem Sidonii Sarion vocant, et Amorrhæi Sanir:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'omnes civitates, quæ sitæ sunt in planitie, et universam terram Galaad et Basan usque ad Selcha, et Edrai civitates regni Og in Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Solus quippe Og rex Basan restiterat de stirpe gigantum. Monstratur lectus ejus ferreus, qui est in Rabbath filiorum Ammon, novem cubitos habens longitudinis, et quatuor latitudinis ad mensuram cubiti virilis manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Terramque possedimus tempore illo ab Aroër, quæ est super ripam torrentis Arnon, usque ad mediam partem montis Galaad: et civitates illius dedi Ruben et Gad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Reliquam autem partem Galaad, et omnem Basan regni Og, tradidi mediæ tribui Manasse, omnem regionem Argob: cunctaque Basan vocatur Terra gigantum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair filius Manasse possedit omnem regionem Argob usque ad terminos Gessuri et Machati. Vocavitque ex nomine suo Basan, Havoth Jair, id est, Villas Jair, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Machir quoque dedi Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Et tribubus Ruben et Gad dedi de terra Galaad usque ad torrentem Arnon medium torrentis, et confinium usque ad torrentem Jeboc, qui est terminus filiorum Ammon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'et planitiem solitudinis, atque Jordanem, et terminos Cenereth usque ad mare deserti, quod est salsissimum, ad radices montis Phasga contra orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Præcepique vobis in tempore illo, dicens: Dominus Deus vester dat vobis terram hanc in hæreditatem: expediti præcedite fratres vestros filios Israël omnes viri robusti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'absque uxoribus, et parvulis, atque jumentis. Novi enim quod plura habeatis pecora, et in urbibus remanere debebunt, quas tradidi vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'donec requiem tribuat Dominus fratribus vestris, sicut vobis tribuit: et possideant ipsi etiam terram, quam daturus est eis trans Jordanem: tunc revertetur unusquisque in possessionem suam, quam dedi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Josue quoque in tempore illo præcepi, dicens: Oculi tui viderunt quæ fecit Dominus Deus vester duobus his regibus: sic faciet omnibus regnis, ad quæ transiturus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne timeas eos: Dominus enim Deus vester pugnabit pro vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Precatusque sum Dominum in tempore illo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Domine Deus, tu cœpisti ostendere servo tuo magnitudinem tuam, manumque fortissimam: neque enim est alius deus vel in cælo, vel in terra, qui possit facere opera tua, et comparari fortitudini tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Transibo igitur, et videbo terram hanc optimam trans Jordanem, et montem istum egregium, et Libanum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Iratusque est Dominus mihi propter vos, nec exaudivit me, sed dixit mihi: Sufficit tibi: nequaquam ultra loquaris de hac re ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Ascende cacumen Phasgæ, et oculos tuos circumfer ad occidentem, et ad aquilonem, austrumque et orientem, et aspice; nec enim transibis Jordanem istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Præcipe Josue, et corrobora eum atque conforta: quia ipse præcedet populum istum, et dividet eis terram quam visurus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Mansimusque in valle contra fanum Phogor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Et nunc, Israël, audi præcepta et judicia, quæ ego doceo te: ut faciens ea, vivas, et ingrediens possideas terram, quam Dominus Deus patrum vestrorum daturus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Non addetis ad verbum, quod vobis loquor, nec auferetis ex eo: custodite mandata Domini Dei vestri, quæ ego præcipio vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Oculi vestri viderunt omnia quæ fecit Dominus contra Beelphegor, quomodo contriverit omnes cultores ejus de medio vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Vos autem qui adhæretis Domino Deo vestro, vivitis universi usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Scitis quod docuerim vos præcepta atque justitias, sicut mandavit mihi Dominus Deus meus: sic facietis ea in terra, quam possessuri estis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'et observabitis et implebitis opere. Hæc est enim vestra sapientia, et intellectus coram populis, ut audientes universa præcepta hæc, dicant: En populus sapiens et intelligens, gens magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Nec est alia natio tam grandis, quæ habeat deos appropinquantes sibi, sicut Deus noster adest cunctis obsecrationibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Quæ est enim alia gens sic inclyta, ut habeat cæremonias, justaque judicia, et universam legem, quam ego proponam hodie ante oculos vestros?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Custodi igitur temetipsum, et animam tuam sollicite. Ne obliviscaris verborum, quæ viderunt oculi tui, et ne excidant de corde tuo cunctis diebus vitæ tuæ. Docebis ea filios ac nepotes tuos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'a die in quo stetisti coram Domino Deo tuo in Horeb, quando Dominus locutus est mihi, dicens: Congrega ad me populum, ut audiant sermones meos, et discant timere me omni tempore quo vivunt in terra, doceantque filios suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Et accessistis ad radices montis, qui ardebat usque ad cælum: erantque in eo tenebræ, et nubes, et caligo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Locutusque est Dominus ad vos de medio ignis. Vocem verborum ejus audistis, et formam penitus non vidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Et ostendit vobis pactum suum, quod præcepit ut faceretis, et decem verba, quæ scripsit in duabus tabulis lapideis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mihique mandavit in illo tempore ut docerem vos cæremonias et judicia, quæ facere deberetis in terra, quam possessuri estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Custodite igitur sollicite animas vestras. Non vidistis aliquam similitudinem in die, qua locutus est vobis Dominus in Horeb de medio ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'ne forte decepti faciatis vobis sculptam similitudinem, aut imaginem masculi vel feminæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'similitudinem omnium jumentorum, quæ sunt super terram, vel avium sub cælo volantium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'atque reptilium, quæ moventur in terra, sive piscium qui sub terra morantur in aquis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'ne forte elevatis oculis ad cælum, videas solem et lunam, et omnia astra cæli, et errore deceptus adores ea, et colas quæ creavit Dominus Deus tuus in ministerium cunctis gentibus, quæ sub cælo sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Vos autem tulit Dominus, et eduxit de fornace ferrea \'gypti, ut haberet populum hæreditarium, sicut est in præsenti die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Iratusque est Dominus contra me propter sermones vestros, et juravit ut non transirem Jordanem, nec ingrederer terram optimam, quam daturus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Ecce morior in hac humo; non transibo Jordanem: vos transibitis, et possidebitis terram egregiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Cave nequando obliviscaris pacti Domini Dei tui, quod pepigit tecum, et facias tibi sculptam similitudinem eorum, quæ fieri Dominus prohibuit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'quia Dominus Deus tuus ignis consumens est, Deus æmulator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Si genueritis filios ac nepotes, et morati fueritis in terra, deceptique feceritis vobis aliquam similitudinem, patrantes malum coram Domino Deo vestro, ut eum ad iracundiam provocetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'testes invoco hodie cælum et terram, cito perituros vos esse de terra, quam transito Jordane possessuri estis: non habitabitis in ea longo tempore, sed delebit vos Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'atque disperget in omnes gentes, et remanebitis pauci in nationibus, ad quas vos ducturus est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Ibique servietis diis, qui hominum manu fabricati sunt, ligno et lapidi qui non vident, nec audiunt, nec comedunt, nec odorantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Cumque quæsieris ibi Dominum Deum tuum, invenies eum: si tamen toto corde quæsieris, et tota tribulatione animæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Postquam te invenerint omnia quæ prædicta sunt, novissimo tempore reverteris ad Dominum Deum tuum, et audies vocem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Quia Deus misericors Dominus Deus tuus est: non dimittet te, nec omnino delebit, neque obliviscetur pacti, in quo juravit patribus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Interroga de diebus antiquis, qui fuerunt ante te ex die quo creavit Deus hominem super terram, a summo cælo usque ad summum ejus, si facta est aliquando hujuscemodi res, aut umquam cognitum est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'ut audiret populus vocem Dei loquentis de medio ignis, sicut tu audisti, et vixisti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'si fecit Deus ut ingrederetur, et tolleret sibi gentem de medio nationum, per tentationes, signa atque portenta, per pugnam et robustam manum, extentumque brachium, et horribiles visiones juxta omnia quæ fecit pro vobis Dominus Deus vester in \'gypto, videntibus oculis tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'ut scires quoniam Dominus ipse est Deus, et non est alius præter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'De cælo te fecit audire vocem suam, ut doceret te, et in terra ostendit tibi ignem suum maximum, et audisti verba illius de medio ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'quia dilexit patres tuos, et elegit semen eorum post eos. Eduxitque te præcedens in virtute sua magna ex \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'ut deleret nationes maximas et fortiores te in introitu tuo: et introduceret te, daretque tibi terram earum in possessionem, sicut cernis in præsenti die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Scito ergo hodie, et cogitato in corde tuo quod Dominus ipse sit Deus in cælo sursum, et in terra deorsum, et non sit alius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Custodi præcepta ejus atque mandata, quæ ego præcipio tibi: ut bene sit tibi, et filiis tuis post te, et permaneas multo tempore super terram, quam Dominus Deus tuus daturus est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tunc separavit Moyses tres civitates trans Jordanem ad orientalem plagam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'ut confugiat ad eas qui occiderit nolens proximum suum, nec sibi fuerit inimicus ante unum et alterum diem, et ad harum aliquam urbium possit evadere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bosor in solitudine, quæ sita est in terra campestri de tribu Ruben: et Ramoth in Galaad, quæ est in tribu Gad: et Golan in Basan, quæ est in tribu Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Ista est lex, quam proposuit Moyses coram filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'et hæc testimonia et cæremoniæ atque judicia, quæ locutus est ad filios Israël, quando egressi sunt de \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'trans Jordanem in valle contra fanum Phogor in terra Sehon regis Amorrhæi, qui habitavit in Hesebon, quem percussit Moyses. Filii quoque Israël egressi ex \'gypto');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'possederunt terram ejus, et terram Og regis Basan, duorum regum Amorrhæorum, qui erant trans Jordanem ad solis ortum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'ab Aroër, quæ sita est super ripam torrentis Arnon, usque ad montem Sion, qui est et Hermon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'omnem planitiem trans Jordanem ad orientalem plagam, usque ad mare solitudinis, et usque ad radices montis Phasga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Vocavitque Moyses omnem Israëlem, et dixit ad eum: Audi, Israël, cæremonias atque judicia, quæ ego loquor in auribus vestris hodie: discite ea, et opere complete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Dominus Deus noster pepigit nobiscum fœdus in Horeb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Non cum patribus nostris iniit pactum, sed nobiscum qui in præsentiarum sumus, et vivimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Facie ad faciem locutus est nobis in monte de medio ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ego sequester et medius fui inter Dominum et vos in tempore illo, ut annuntiarem vobis verba ejus: timuistis enim ignem, et non ascendistis in montem. Et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ego Dominus Deus tuus, qui eduxi te de terra \'gypti, de domo servitutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Non habebis deos alienos in conspectu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Non facies tibi sculptile, nec similitudinem omnium, quæ in cælo sunt desuper, et quæ in terra deorsum, et quæ versantur in aquis sub terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Non adorabis ea, et non coles. Ego enim sum Dominus Deus tuus: Deus æmulator, reddens iniquitatem patrum super filios in tertiam et quartam generationem his qui oderunt me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'et faciens misericordiam in multa millia diligentibus me, et custodientibus præcepta mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Non usurpabis nomen Domini Dei tui frustra: quia non erit impunitus qui super re vana nomen ejus assumpserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Observa diem sabbati, ut sanctifices eum, sicut præcepit tibi Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sex diebus operaberis, et facies omnia opera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Septimus dies sabbati est, id est, requies Domini Dei tui. Non facies in eo quidquam operis tu, et filius tuus, et filia, servus et ancilla, et bos, et asinus, et omne jumentum tuum, et peregrinus qui est intra portas tuas: ut requiescat servus tuus, et ancilla tua, sicut et tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Memento quod et ipse servieris in \'gypto, et eduxerit te inde Dominus Deus tuus in manu forti, et brachio extento. Idcirco præcepit tibi ut observares diem sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honora patrem tuum et matrem, sicut præcepit tibi Dominus Deus tuus, ut longo vivas tempore, et bene sit tibi in terra, quam Dominus Deus tuus daturus est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Non occides,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'neque mœchaberis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'furtumque non facies:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'nec loqueris contra proximum tuum falsum testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Non concupisces uxorem proximi tui: non domum, non agrum, non servum, non ancillam, non bovem, non asinum, et universa quæ illius sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Hæc verba locutus est Dominus ad omnem multitudinem vestram in monte de medio ignis et nubis, et caliginis, voce magna, nihil addens amplius: et scripsit ea in duabus tabulis lapideis, quas tradidit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Vos autem postquam audistis vocem de medio tenebrarum, et montem ardere vidistis, accessistis ad me omnes principes tribuum et majores natu, atque dixistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Ecce ostendit nobis Dominus Deus noster majestatem et magnitudinem suam: vocem ejus audivimus de medio ignis, et probavimus hodie, quod loquente Deo cum homine, vixerit homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Cur ergo moriemur, et devorabit nos ignis hic maximus? si enim audierimus ultra vocem Domini Dei nostri, moriemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Quid est omnis caro, ut audiat vocem Dei viventis, qui de medio ignis loquitur sicut nos audivimus, et possit vivere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Tu magis accede: et audi cuncta quæ dixerit Dominus Deus noster tibi: loquerisque ad nos, et nos audientes faciemus ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Quod cum audisset Dominus, ait ad me: Audivi vocem verborum populi hujus quæ locuti sunt tibi: bene omnia sunt locuti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Quis det talem eos habere mentem, ut timeant me, et custodiant universa mandata mea in omni tempore, ut bene sit eis et filiis eorum in sempiternum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Vade et dic eis: Revertimini in tentoria vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Tu vero hic sta mecum, et loquar tibi omnia mandata mea, et cæremonias atque judicia: quæ docebis eos, ut faciant ea in terra, quam dabo illis in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Custodite igitur et facite quæ præcepit Dominus Deus vobis: non declinabitis neque ad dexteram, neque ad sinistram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'sed per viam, quam præcepit Dominus Deus vester, ambulabitis, ut vivatis, et bene sit vobis, et protelentur dies in terra possessionis vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Hæc sunt præcepta, et cæremoniæ, atque judicia, quæ mandavit Dominus Deus vester ut docerem vos, et faciatis ea in terra, ad quam transgredimini possidendam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'ut timeas Dominum Deum tuum, et custodias omnia mandata et præcepta ejus, quæ ego præcipio tibi, et filiis, ac nepotibus tuis, cunctis diebus vitæ tuæ, ut prolongentur dies tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Audi, Israël, et observa ut facias quæ præcepit tibi Dominus, et bene sit tibi, et multipliceris amplius, sicut pollicitus est Dominus Deus patrum tuorum tibi terram lacte et melle manantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Audi, Israël: Dominus Deus noster, Dominus unus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Diliges Dominum Deum tuum ex toto corde tuo, et ex tota anima tua, et ex tota fortitudine tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Eruntque verba hæc, quæ ego præcipio tibi hodie, in corde tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'et narrabis ea filiis tuis, et meditaberis in eis sedens in domo tua, et ambulans in itinere, dormiens atque consurgens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Et ligabis ea quasi signum in manu tua, eruntque et movebuntur inter oculos tuos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'scribesque ea in limine, et ostiis domus tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Cumque introduxerit te Dominus Deus tuus in terram, pro qua juravit patribus tuis Abraham, Isaac, et Jacob, et dederit tibi civitates magnas et optimas, quas non ædificasti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'domos plenas cunctarum opum, quas non exstruxisti, cisternas, quas non fodisti, vineta et oliveta, quæ non plantasti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'et comederis, et saturatus fueris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'cave diligenter ne obliviscaris Domini, qui eduxit te de terra \'gypti, de domo servitutis. Dominum Deum tuum timebis, et illi soli servies, ac per nomen illius jurabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Non ibitis post deos alienos cunctarum gentium, quæ in circuitu vestro sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'quoniam Deus æmulator Dominus Deus tuus in medio tui: nequando irascatur furor Domini Dei tui contra te, et auferat te de superficie terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Non tentabis Dominum Deum tuum, sicut tentasti in loco tentationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Custodi præcepta Domini Dei tui, ac testimonia et cæremonias, quas præcepit tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'et fac quod placitum est et bonum in conspectu Domini, ut bene sit tibi: et ingressus possideas terram optimam, de qua juravit Dominus patribus tuis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'ut deleret omnes inimicos tuos coram te, sicut locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Cumque interrogaverit te filius tuus cras, dicens: Quid sibi volunt testimonia hæc, et cæremoniæ, atque judicia, quæ præcepit Dominus Deus noster nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'dices ei: Servi eramus Pharaonis in \'gypto, et eduxit nos Dominus de \'gypto in manu forti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'fecitque signa atque prodigia magna et pessima in \'gypto contra Pharaonem, et omnem domum illius in conspectu nostro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'et eduxit nos inde, ut introductis daret terram, super qua juravit patribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Præcepitque nobis Dominus ut faciamus omnia legitima hæc, et timeamus Dominum Deum nostrum, ut bene sit nobis cunctis diebus vitæ nostræ, sicut est hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Eritque nostri misericors, si custodierimus et fecerimus omnia præcepta ejus coram Domino Deo nostro, sicut mandavit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Cum introduxerit te Dominus Deus tuus in terram, quam possessurus ingrederis, et deleverit gentes multas coram te, Hethæum, et Gergezæum, et Amorrhæum, Chananæum, et Pherezæum, et Hevæum, et Jebusæum, septem gentes multo majoris numeri quam tu es, et robustiores te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'tradideritque eas Dominus Deus tuus tibi, percuties eas usque ad internecionem. Non inibis cum eis fœdus, nec misereberis earum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'neque sociabis cum eis conjugia. Filiam tuam non dabis filio ejus, nec filiam illius accipies filio tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'quia seducet filium tuum, ne sequatur me, et ut magis serviat diis alienis: irasceturque furor Domini, et delebit te cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Quin potius hæc facietis eis: aras eorum subvertite, et confringite statuas, lucosque succidite, et sculptilia comburite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'quia populus sanctus es Domino Deo tuo. Te elegit Dominus Deus tuus, ut sis ei populus peculiaris de cunctis populis, qui sunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Non quia cunctas gentes numero vincebatis, vobis junctus est Dominus, et elegit vos, cum omnibus sitis populis pauciores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'sed quia dilexit vos Dominus, et custodivit juramentum, quod juravit patribus vestris: eduxitque vos in manu forti, et redemit de domo servitutis, de manu Pharaonis regis \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Et scies, quia Dominus Deus tuus, ipse est Deus fortis et fidelis, custodiens pactum et misericordiam diligentibus se, et his qui custodiunt præcepta ejus in mille generationes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'et reddens odientibus se statim, ita ut disperdat eos, et ultra non differat, protinus eis restituens quod merentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Custodi ergo præcepta et cæremonias atque judicia, quæ ego mando tibi hodie ut facias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Si postquam audieris hæc judicia, custodieris ea, et feceris, custodiet et Dominus Deus tuus pactum tibi, et misericordiam quam juravit patribus tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'et diliget te, ac multiplicabit, benedicetque fructui ventris tui, et fructui terræ tuæ, frumento tuo, atque vindemiæ, oleo, et armentis, gregibus ovium tuarum super terram, pro qua juravit patribus tuis ut daret eam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Benedictus eris inter omnes populos. Non erit apud te sterilis utriusque sexus, tam in hominibus quam in gregibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Auferet Dominus a te omnem languorem: et infirmitates \'gypti pessimas, quas novisti, non inferet tibi, sed cunctis hostibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Devorabis omnes populos, quos Dominus Deus tuus daturus est tibi. Non parcet eis oculus tuus, nec servies diis eorum, ne sint in ruinam tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Si dixeris in corde tuo: Plures sunt gentes istæ quam ego: quomodo potero delere eas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'noli metuere, sed recordare quæ fecerit Dominus Deus tuus Pharaoni, et cunctis \'gyptiis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'plagas maximas, quas viderunt oculi tui, et signa atque portenta, manumque robustam, et extentum brachium, ut educeret te Dominus Deus tuus: sic faciet cunctis populis, quos metuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Insuper et crabrones mittet Dominus Deus tuus in eos, donec deleat omnes atque disperdat qui te fugerint, et latere potuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Non timebis eos, quia Dominus Deus tuus in medio tui est, Deus magnus et terribilis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'ipse consumet nationes has in conspectu tuo paulatim atque per partes. Non poteris eas delere pariter: ne forte multiplicentur contra te bestiæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Dabitque eos Dominus Deus tuus in conspectu tuo: et interficiet illos, donec penitus deleantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Tradetque reges eorum in manus tuas, et disperdes nomina eorum sub cælo: nullus poterit resistere tibi, donec conteras eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Sculptilia eorum igne combures: non concupisces argentum et aurum, de quibus facta sunt, neque assumes ex eis tibi quidquam, ne offendas, propterea quia abominatio est Domini tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'nec inferes quippiam ex idolo in domum tuam, ne fias anathema, sicut et illud est. Quasi spurcitiam detestaberis, et velut inquinamentum ac sordes abominationi habebis, quia anathema est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Omne mandatum, quod ego præcipio tibi hodie, cave diligenter ut facias, ut possitis vivere, et multiplicemini, ingressique possideatis terram, pro qua juravit Dominus patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Et recordaberis cuncti itineris, per quod adduxit te Dominus Deus tuus quadraginta annis per desertum, ut affligeret te, atque tentaret, et nota fierent quæ in tuo animo versabantur, utrum custodires mandata illius, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Afflixit te penuria, et dedit tibi cibum manna, quod ignorabas tu et patres tui: ut ostenderet tibi quod non in solo pane vivat homo, sed in omni verbo quod egreditur de ore Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Vestimentum tuum, quo operiebaris, nequaquam vetustate defecit, et pes tuus non est subtritus, en quadragesimus annus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'ut recogites in corde tuo, quia sicut erudit filium suum homo, sic Dominus Deus tuus erudivit te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'ut custodias mandata Domini Dei tui, et ambules in viis ejus, et timeas eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Dominus enim Deus tuus introducet te in terram bonam, terram rivorum, aquarumque et fontium, in cujus campis et montibus erumpunt fluviorum abyssi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'terram frumenti, hordei ac vinearum, in qua ficus, et malogranata, et oliveta nascuntur: terram olei ac mellis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'ubi absque ulla penuria comedes panem tuum, et rerum omnium abundantia perfrueris: cujus lapides ferrum sunt, et de montibus ejus æris metalla fodiuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'ut cum comederis, et satiatus fueris, benedicas Domino Deo tuo pro terra optima, quam dedit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Observa, et cave nequando obliviscaris Domini Dei tui, et negligas mandata ejus atque judicia et cæremonias, quas ego præcipio tibi hodie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'ne postquam comederis et satiatus fueris, domos pulchras ædificaveris, et habitaveris in eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'habuerisque armenta boum, et ovium greges, argenti et auri, cunctarumque rerum copiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'elevetur cor tuum, et non reminiscaris Domini Dei tui, qui eduxit te de terra \'gypti, de domo servitutis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'et ductor tuus fuit in solitudine magna atque terribili, in qua erat serpens flatu adurens, et scorpio, ac dipsas, et nullæ omnino aquæ: qui eduxit rivos de petra durissima,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'et cibavit te manna in solitudine, quod nescierunt patres tui. Et postquam afflixit ac probavit, ad extremum misertus est tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'ne diceres in corde tuo: Fortitudo mea, et robur manus meæ, hæc mihi omnia præstiterunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'sed recorderis Domini Dei tui, quod ipse vires tibi præbuerit, ut impleret pactum suum, super quo juravit patribus tuis, sicut præsens indicat dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Sin autem oblitus Domini Dei tui, secutus fueris deos alienos, coluerisque illos et adoraveris: ecce nunc prædico tibi quod omnino dispereas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Sicut gentes, quas delevit Dominus in introitu tuo, ita et vos peribitis, si inobedientes fueritis voci Domini Dei vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Audi, Israël: tu transgredieris hodie Jordanem, ut possideas nationes maximas et fortiores te, civitates ingentes, et ad cælum usque muratas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'populum magnum atque sublimem, filios Enacim, quos ipse vidisti et audisti, quibus nullus potest ex adverso resistere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Scies ergo hodie quod Dominus Deus tuus ipse transibit ante te, ignis devorans atque consumens, qui conterat eos, et deleat atque disperdat ante faciem tuam velociter, sicut locutus est tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'ne dicas in corde tuo, cum deleverit eos Dominus Deus tuus in conspectu tuo: Propter justitiam meam introduxit me Dominus ut terram hanc possiderem, cum propter impietates suas istæ deletæ sint nationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Neque enim propter justitias tuas, et æquitatem cordis tui ingredieris, ut possideas terras earum: sed quia illæ egerunt impie, introëunte te deletæ sunt: et ut compleret verbum suum Dominus, quod sub juramento pollicitus est patribus tuis, Abraham, Isaac, et Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Scito ergo quod non propter justitias tuas Dominus Deus tuus dederit tibi terram hanc optimam in possessionem, cum durissimæ cervicis sis populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Memento, et ne obliviscaris, quomodo ad iracundiam provocaveris Dominum Deum tuum in solitudine. Ex eo die, quo egressus es ex \'gypto usque ad locum istum, semper adversum Dominum contendisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Nam et in Horeb provocasti eum, et iratus delere te voluit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'quando ascendi in montem, ut acciperem tabulas lapideas, tabulas pacti quod pepigit vobiscum Dominus: et perseveravi in monte quadraginta diebus ac noctibus, panem non comedens, et aquam non bibens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Deditque mihi Dominus duas tabulas lapideas scriptas digito Dei, et continentes omnia verba quæ vobis locutus est in monte de medio ignis, quando concio populi congregata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Cumque transissent quadraginta dies, et totidem noctes, dedit mihi Dominus duas tabulas lapideas, tabulas fœderis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'dixitque mihi: Surge, et descende hinc cito: quia populus tuus, quem eduxisti de \'gypto, deseruerunt velociter viam, quam demonstrasti eis, feceruntque sibi conflatile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Rursumque ait Dominus ad me: Cerno quod populus iste duræ cervicis sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'dimitte me ut conteram eum, et deleam nomen ejus de sub cælo, et constituam te super gentem, quæ hac major et fortior sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Cumque de monte ardente descenderem, et duas tabulas fœderis utraque tenerem manu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'vidissemque vos peccasse Domino Deo vestro, et fecisse vobis vitulum conflatilem, ac deseruisse velociter viam ejus, quam vobis ostenderat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'projeci tabulas de manibus meis, confregique eas in conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Et procidi ante Dominum sicut prius, quadraginta diebus et noctibus panem non comedens, et aquam non bibens, propter omnia peccata vestra quæ gessistis contra Dominum, et eum ad iracundiam provocastis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'timui enim indignationem et iram illius, qua adversum vos concitatus, delere vos voluit. Et exaudivit me Dominus etiam hac vice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Adversum Aaron quoque vehementer iratus, voluit eum conterere, et pro illo similiter deprecatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Peccatum autem vestrum quod feceratis, id est, vitulum, arripiens, igne combussi, et in frusta comminuens, omninoque in pulverem redigens, projeci in torrentem, qui de monte descendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'In incendio quoque, et in tentatione, et in Sepulchris concupiscentiæ provocastis Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'et quando misit vos de Cadesbarne, dicens: Ascendite, et possidete terram, quam dedi vobis, et contempsistis imperium Domini Dei vestri, et non credidistis ei, neque vocem ejus audire voluistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'sed semper fuistis rebelles a die qua nosse vos cœpi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Et jacui coram Domino quadraginta diebus ac noctibus, quibus eum suppliciter deprecabar, ne deleret vos ut fuerat comminatus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'et orans dixi: Domine Deus, ne disperdas populum tuum, et hæreditatem tuam, quam redemisti in magnitudine tua, quos eduxisti de \'gypto in manu forti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Recordare servorum tuorum Abraham, Isaac, et Jacob: ne aspicias duritiam populi hujus, et impietatem atque peccatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'ne forte dicant habitatores terræ, de qua eduxisti nos: Non poterat Dominus introducere eos in terram, quam pollicitus est eis, et oderat illos: idcirco eduxit, ut interficeret eos in solitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'qui sunt populus tuus et hæreditas tua, quos eduxisti in fortitudine tua magna, et in brachio tuo extento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'In tempore illo dixit Dominus ad me: Dola tibi duas tabulas lapideas, sicut priores fuerunt, et ascende ad me in montem: faciesque arcam ligneam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'et scribam in tabulis verba quæ fuerunt in his qui ante confregisti: ponesque eas in arca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Feci igitur arcam de lignis setim. Cumque dolassem duas tabulas lapideas instar priorum, ascendi in montem, habens eas in manibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Scripsitque in tabulis, juxta id quod prius scripserat, verba decem, quæ locutus est Dominus ad vos in monte de medio ignis, quando populus congregatus est: et dedit eas mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Reversusque de monte, descendi, et posui tabulas in arcam, quam feceram, quæ hucusque ibi sunt, sicut mihi præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Filii autem Israël moverunt castra ex Beroth filiorum Jacan in Mosera, ubi Aaron mortuus ac sepultus est, pro quo sacerdotio functus est Eleazar filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Inde venerunt in Gadgad: de quo loco profecti, castrametati sunt in Jetebatha, in terra aquarum atque torrentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Eo tempore separavit tribum Levi, ut portaret arcam fœderis Domini, et staret coram eo in ministerio, ac benediceret in nomine illius usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Quam ob rem non habuit Levi partem, neque possessionem cum fratribus suis: quia ipse Dominus possessio ejus est, sicut promisit ei Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ego autem steti in monte, sicut prius, quadraginta diebus ac noctibus: exaudivitque me Dominus etiam hac vice, et te perdere noluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Dixitque mihi: Vade, et præcede populum, ut ingrediatur, et possideat terram, quam juravi patribus eorum ut traderem eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Et nunc Israël, quid Dominus Deus tuus petit a te, nisi ut timeas Dominum Deum tuum, et ambules in viis ejus, et diligas eum, ac servias Domino Deo tuo in toto corde tuo, et in tota anima tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'custodiasque mandata Domini, et cæremonias ejus, quas ego hodie præcipio tibi, ut bene sit tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'En Domini Dei tui cælum est, et cælum cæli, terra, et omnia quæ in ea sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'et tamen patribus tuis conglutinatus est Dominus, et amavit eos, elegitque semen eorum post eos, id est, vos, de cunctis gentibus, sicut hodie comprobatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Circumcidite igitur præputium cordis vestri, et cervicem vestram ne induretis amplius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'quia Dominus Deus vester ipse est Deus deorum, et Dominus dominantium, Deus magnus, et potens, et terribilis, qui personam non accipit, nec munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Facit judicium pupillo et viduæ; amat peregrinum, et dat ei victum atque vestitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Et vos ergo amate peregrinos, quia et ipsi fuistis advenæ in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Dominum Deum tuum timebis, et ei soli servies: ipsi adhærebis, jurabisque in nomine illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Ipse est laus tua, et Deus tuus, qui fecit tibi hæc magnalia et terribilia, quæ viderunt oculi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'In septuaginta animabus descenderunt patres tui in \'gyptum, et ecce nunc multiplicavit te Dominus Deus tuus sicut astra cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Ama itaque Dominum Deum tuum, et observa præcepta ejus et cæremonias, judicia atque mandata, omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Cognoscite hodie quæ ignorant filii vestri, qui non viderunt disciplinam Domini Dei vestri, magnalia ejus et robustam manum, extentumque brachium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'signa et opera quæ fecit in medio \'gypti Pharaoni regi, et universæ terræ ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'omnique exercitui \'gyptiorum, et equis ac curribus: quomodo operuerint eos aquæ maris Rubri, cum vos persequerentur, et deleverit eos Dominus usque in præsentem diem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'vobisque quæ fecerit in solitudine donec veniretis ad hunc locum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'et Dathan atque Abiron filiis Eliab, qui fuit filius Ruben: quos aperto ore suo terra absorbuit, cum domibus et tabernaculis, et universa substantia eorum, quam habebant in medio Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Oculi vestri viderunt opera Domini magna quæ fecit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'ut custodiatis universa mandata illius, quæ ego hodie præcipio vobis, et possitis introire, et possidere terram, ad quam ingredimini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'multoque in ea vivatis tempore: quam sub juramento pollicitus est Dominus patribus vestris, et semini eorum, lacte et melle manantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Terra enim, ad quam ingrederis possidendam, non est sicut terra \'gypti, de qua existi, ubi jacto semine in hortorum morem aquæ ducuntur irriguæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'sed montuosa est et campestris, de cælo expectans pluvias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'quam Dominus Deus tuus semper invisit, et oculi illius in ea sunt a principio anni usque ad finem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Si ergo obedieritis mandatis meis, quæ ego hodie præcipio vobis, ut diligatis Dominum Deum vestrum, et serviatis ei in toto corde vestro, et in tota anima vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'dabit pluviam terræ vestræ temporaneam et serotinam, ut colligatis frumentum, et vinum, et oleum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'fœnumque ex agris ad pascenda jumenta, et ut ipsi comedatis ac saturemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Cavete ne forte decipiatur cor vestrum, et recedatis a Domino, serviatisque diis alienis, et adoretis eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'iratusque Dominus claudat cælum, et pluviæ non descendant, nec terra det germen suum, pereatisque velociter de terra optima, quam Dominus daturus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Ponite hæc verba mea in cordibus et in animis vestris, et suspendite ea pro signo in manibus, et inter oculos vestros collocate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Docete filios vestros ut illa meditentur: quando sederis in domo tua, et ambulaveris in via, et accubueris atque surrexeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Scribes ea super postes et januas domus tuæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'ut multiplicentur dies tui, et filiorum tuorum in terra, quam juravit Dominus patribus tuis, ut daret eis quamdiu cælum imminet terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Si enim custodieritis mandata quæ ego præcipio vobis, et feceritis ea, ut diligatis Dominum Deum vestrum, et ambuletis in omnibus viis ejus, adhærentes ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'disperdet Dominus omnes gentes istas ante faciem vestram, et possidebitis eas, quæ majores et fortiores vobis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Omnis locus, quem calcaverit pes vester, vester erit. A deserto, et a Libano, a flumine magno Euphrate usque ad mare occidentale erunt termini vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nullus stabit contra vos: terrorem vestrum et formidinem dabit Dominus Deus vester super omnem terram quam calcaturi estis, sicut locutus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'En propono in conspectu vestro hodie benedictionem et maledictionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'benedictionem, si obedieritis mandatis Domini Dei vestri, quæ ego hodie præcipio vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'maledictionem, si non obedieritis mandatis Domini Dei vestri, sed recesseritis de via, quam ego nunc ostendo vobis, et ambulaveritis post deos alienos, quos ignoratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Cum vero introduxerit te Dominus Deus tuus in terram, ad quam pergis habitandam, pones benedictionem super montem Garizim, maledictionem super montem Hebal:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'qui sunt trans Jordanem, post viam quæ vergit ad solis occubitum in terra Chananæi, qui habitat in campestribus contra Galgalam, quæ est juxta vallem tendentem et intrantem procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Vos enim transibitis Jordanem, ut possideatis terram quam Dominus Deus vester daturus est vobis, ut habeatis et possideatis illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Videte ergo ut impleatis cæremonias atque judicia, quæ ego hodie ponam in conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Hæc sunt præcepta atque judicia, quæ facere debetis in terra, quam Dominus Deus patrum tuorum daturus est tibi, ut possideas eam cunctis diebus, quibus super humum gradieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Subvertite omnia loca, in quibus coluerunt gentes, quas possessuri estis, deos suos super montes excelsos, et colles, et subter omne lignum frondosum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Dissipate aras eorum, et confringite statuas: lucos igne comburite, et idola comminuite: disperdite nomina eorum de locis illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Non facietis ita Domino Deo vestro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'sed ad locum, quem elegerit Dominus Deus vester de cunctis tribubus vestris, ut ponat nomen suum ibi, et habitet in eo, venietis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'et offeretis in loco illo holocausta et victimas vestras, decimas et primitias manuum vestrarum, et vota atque donaria, primogenita boum et ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Et comedetis ibi in conspectu Domini Dei vestri: ac lætabimini in cunctis, ad quæ miseritis manum vos et domus vestræ, in quibus benedixerit vobis Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Non facietis ibi quæ nos hic facimus hodie, singuli quod sibi rectum videtur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'neque enim usque in præsens tempus venistis ad requiem, et possessionem, quam Dominus Deus vester daturus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Transibitis Jordanem, et habitabitis in terra, quam Dominus Deus vester daturus est vobis, ut requiescatis a cunctis hostibus per circuitum: et absque ullo timore habitetis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'in loco, quem elegerit Dominus Deus vester, ut sit nomen ejus in eo: illuc omnia, quæ præcipio, conferetis, holocausta, et hostias, ac decimas, et primitias manuum vestrarum: et quidquid præcipuum est in muneribus, quæ vovebitis Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Ibi epulabimini coram Domino Deo vestro, vos et filii ac filiæ vestræ, famuli et famulæ, atque Levites qui in urbibus vestris commoratur: neque enim habet aliam partem et possessionem inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Cave ne offeras holocausta tua in omni loco, quem videris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'sed in eo, quem elegerit Dominus, in una tribuum tuarum offeres hostias, et facies quæcumque præcipio tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Sin autem comedere volueris, et te esus carnium delectaverit, occide, comede juxta benedictionem Domini Dei tui, quam dedit tibi in urbibus tuis: sive immundum fuerit, hoc est, maculatum et debile: sive mundum, hoc est, integrum et sine macula, quod offerri licet, sicut capream et cervum, comedes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'absque esu dumtaxat sanguinis, quem super terram quasi aquam effundes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Non poteris comedere in oppidis tuis decimam frumenti, et vini, et olei tui, primogenita armentorum et pecorum, et omnia quæ voveris, et sponte offerre volueris, et primitias manuum tuarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'sed coram Domino Deo tuo comedes ea in loco, quem elegerit Dominus Deus tuus, tu et filius tuus, et filia tua, et servus et famula, atque Levites qui manet in urbibus tuis: et lætaberis et reficieris coram Domino Deo tuo in cunctis ad quæ extenderis manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Cave ne derelinquas Levitem in omni tempore quo versaris in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Quando dilataverit Dominus Deus tuus terminos tuos, sicut locutus est tibi, et volueris vesci carnibus, quas desiderat anima tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'locus autem, quem elegerit Dominus Deus tuus ut sit nomen ejus ibi, si procul fuerit, occides de armentis et pecoribus, quæ habueris, sicut præcepi tibi, et comedes in oppidis tuis, ut tibi placet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Sicut comeditur caprea et cervus, ita vesceris eis: et mundus et immundus in commune vescentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Hoc solum cave, ne sanguinem comedas: sanguis enim eorum pro anima est, et idcirco non debes animam comedere cum carnibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'sed super terram fundes quasi aquam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'ut bene sit tibi et filiis tuis post te, cum feceris quod placet in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Quæ autem sanctificaveris, et voveris Domino, tolles, et venies ad locum, quem elegerit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'et offeres oblationes tuas carnem et sanguinem super altare Domini Dei tui: sanguinem hostiarum fundes in altari; carnibus autem ipse vesceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Observa et audi omnia quæ ego præcipio tibi, ut bene sit tibi et filiis tuis post te in sempiternum, cum feceris quod bonum est et placitum in conspectu Domini Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Quando disperdiderit Dominus Deus tuus ante faciem tuam gentes, ad quas ingredieris possidendas, et possederis eas, atque habitaveris in terra earum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'cave ne imiteris eas, postquam te fuerint introëunte subversæ, et requiras cæremonias earum, dicens: Sicut coluerunt gentes istæ deos suos, ita et ego colam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Non facies similiter Domino Deo tuo. Omnes enim abominationes, quas aversatur Dominus, fecerunt diis suis, offerentes filios et filias, et comburentes igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Quod præcipio tibi, hoc tantum facito Domino: nec addas quidquam, nec minuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Si surrexerit in medio tui prophetes, aut qui somnium vidisse se dicat, et prædixerit signum atque portentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'et evenerit quod locutus est, et dixerit tibi: Eamus, et sequamur deos alienos quos ignoras, et serviamus eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'non audies verba prophetæ illius aut somniatoris: quia tentat vos Dominus Deus vester, ut palam fiat utrum diligatis eum an non, in toto corde, et in tota anima vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Dominum Deum vestrum sequimini, et ipsum timete, et mandata illius custodite, et audite vocem ejus: ipsi servietis, et ipsi adhærebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Propheta autem ille aut fictor somniorum interficietur: quia locutus est ut vos averteret a Domino Deo vestro, qui eduxit vos de terra \'gypti, et redemit vos de domo servitutis: ut errare te faceret de via, quam tibi præcepit Dominus Deus tuus: et auferes malum de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Si tibi voluerit persuadere frater tuus filius matris tuæ, aut filius tuus vel filia, sive uxor quæ est in sinu tuo, aut amicus, quem diligis ut animam tuam, clam dicens: Eamus, et serviamus diis alienis, quos ignoras tu, et patres tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'cunctarum in circuitu gentium, quæ juxta vel procul sunt, ab initio usque ad finem terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'non acquiescas ei, nec audias, neque parcat ei oculus tuus ut miserearis et occultes eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'sed statim interficies: sit primum manus tua super eum, et postea omnis populus mittat manum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Lapidibus obrutus necabitur: quia voluit te abstrahere a Domino Deo tuo, qui eduxit te de terra \'gypti, de domo servitutis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'ut omnis Israël audiens timeat, et nequaquam ultra faciat quippiam hujus rei simile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Si audieris in una urbium tuarum, quas Dominus Deus tuus dabit tibi ad habitandum, dicentes aliquos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Egressi sunt filii Belial de medio tui, et averterunt habitatores urbis suæ, atque dixerunt: Eamus, et serviamus diis alienis quos ignoratis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'quære sollicite et diligenter, rei veritate perspecta, si inveneris certum esse quod dicitur, et abominationem hanc opere perpetratam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'statim percuties habitatores urbis illius in ore gladii, et delebis eam ac omnia quæ in illa sunt, usque ad pecora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Quidquid etiam supellectilis fuerit, congregabis in medio platearum ejus, et cum ipsa civitate succendes, ita ut universa consumas Domino Deo tuo, et sit tumulus sempiternus. Non ædificabitur amplius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'et non adhærebit de illo anathemate quidquam in manu tua: ut avertatur Dominus ab ira furoris sui, et misereatur tui, multiplicetque te sicut juravit patribus tuis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'quando audieris vocem Domini Dei tui custodiens omnia præcepta ejus, quæ ego præcipio tibi hodie, ut facias quod placitum est in conspectu Domini Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Filii estote Domini Dei vestri: non vos incidetis, nec facietis calvitium super mortuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'quoniam populus sanctus es Domino Deo tuo, et te elegit ut sis ei in populum peculiarem de cunctis gentibus, quæ sunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Ne comedatis quæ immunda sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Hoc est animal quod comedere debetis: bovem, et ovem, et capram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'cervum et capream, bubalum, tragelaphum, pygargum, orygem, camelopardalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Omne animal, quod in duas partes findit ungulam, et ruminat, comedetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'De his autem, quæ ruminant, et ungulam non findunt, comedere non debetis, ut camelum, leporem, chœrogryllum: hæc, quia ruminant et non dividunt ungulam, immunda erunt vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Sus quoque, quoniam dividat ungulam et non ruminat, immunda erit. Carnibus eorum non vescemini, et cadavera non tangetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Hæc comedetis ex omnibus quæ morantur in aquis: quæ habent pinnulas et squamas, comedite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'quæ absque pinnulis et squamis sunt, ne comedatis, quia immunda sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Omnes aves mundas comedite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Immundas ne comedatis: aquilam scilicet, et gryphem, et haliæetum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'ixion et vulturem ac milvum juxta genus suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'et omne corvini generis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'et struthionem, ac noctuam, et larum, atque accipitrem juxta genus suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'herodium ac cygnum, et ibin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'ac mergulum, porphyrionem, et nycticoracem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'onocrotalum, et charadrium, singula in genere suo: upupam quoque et vespertilionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Et omne quod reptat et pennulas habet, immundum erit, et non comedetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Omne quod mundum est, comedite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Quidquid autem morticinum est, ne vescamini ex eo. Peregrino, qui intra portas tuas est, da ut comedat, aut vende ei: quia tu populus sanctus Domini Dei tui es. Non coques hædum in lacte matris suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Decimam partem separabis de cunctis fructibus tuis qui nascuntur in terra per annos singulos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'et comedes in conspectu Domini Dei tui in loco quem elegerit, ut in eo nomen illius invocetur, decimam frumenti tui, et vini, et olei, et primogenita de armentis et ovibus tuis: ut discas timere Dominum Deum tuum omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Cum autem longior fuerit via, et locus quem elegerit Dominus Deus tuus, tibique benedixerit, nec potueris ad eum hæc cuncta portare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'vendes omnia, et in pretium rediges, portabisque manu tua, et proficisceris ad locum quem elegerit Dominus Deus tuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'et emes ex eadem pecunia quidquid tibi placuerit, sive ex armentis, sive ex ovibus, vinum quoque et siceram, et omne quod desiderat anima tua: et comedes coram Domino Deo tuo, et epulaberis tu et domus tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'et Levites qui intra portas tuas est, cave ne derelinquas eum, quia non habet aliam partem in possessione tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Anno tertio separabis aliam decimam ex omnibus quæ nascuntur tibi eo tempore, et repones intra januas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Venietque Levites qui aliam non habet partem nec possessionem tecum, et peregrinus ac pupillus et vidua, qui intra portas tuas sunt, et comedent et saturabuntur: ut benedicat tibi Dominus Deus tuus in cunctis operibus manuum tuarum quæ feceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Septimo anno facies remissionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'quæ hoc ordine celebrabitur. Cui debetur aliquid ab amico vel proximo ac fratre suo, repetere non poterit, quia annus remissionis est Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'A peregrino et advena exiges: civem et propinquum repetendi non habebis potestatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Et omnino indigens et mendicus non erit inter vos: ut benedicat tibi Dominus Deus tuus in terra, quam traditurus est tibi in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Si tamen audieris vocem Domini Dei tui, et custodieris universa quæ jussit, et quæ ego hodie præcipio tibi, benedicet tibi, ut pollicitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Fœnerabis gentibus multis, et ipse a nullo accipies mutuum. Dominaberis nationibus plurimis, et tui nemo dominabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Si unus de fratribus tuis, qui morantur intra portas civitatis tuæ in terra quam Dominus Deus tuus daturus est tibi, ad paupertatem venerit, non obdurabis cor tuum, nec contrahes manum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'sed aperies eam pauperi, et dabis mutuum, quo eum indigere perspexeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Cave ne forte subrepat tibi impia cogitatio, et dicas in corde tuo: Appropinquat septimus annus remissionis: et avertas oculos tuos a paupere fratre tuo, nolens ei quod postulat mutuum commodare: ne clamet contra te ad Dominum, et fiat tibi in peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Sed dabis ei: nec ages quippiam callide in ejus necessitatibus sublevandis, ut benedicat tibi Dominus Deus tuus in omni tempore, et in cunctis ad quæ manum miseris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Non deerunt pauperes in terra habitationis tuæ: idcirco ego præcipio tibi, ut aperias manum fratri tuo egeno et pauperi, qui tecum versatur in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Cum tibi venditus fuerit frater tuus Hebræus aut Hebræa, et sex annis servierit tibi, in septimo anno dimittes eum liberum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'et quem libertate donaveris, nequaquam vacuum abire patieris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'sed dabis viaticum de gregibus, et de area, et torculari tuo, quibus Dominus Deus tuus benedixerit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Memento quod et ipse servieris in terra \'gypti, et liberaverit te Dominus Deus tuus, et idcirco ego nunc præcipio tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Sin autem dixerit: Nolo egredi: eo quod diligat te, et domum tuam, et bene sibi apud te esse sentiat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'assumes subulam, et perforabis aurem ejus in janua domus tuæ, et serviet tibi usque in æternum. Ancillæ quoque similiter facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Non avertas ab eis oculos tuos, quando dimiseris eos liberos, quoniam juxta mercedem mercenarii per sex annos servivit tibi: ut benedicat tibi Dominus Deus tuus in cunctis operibus quæ agis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'De primogenitis, quæ nascuntur in armentis, et in ovibus tuis, quidquid est sexus masculini, sanctificabis Domino Deo tuo. Non operaberis in primogenito bovis, et non tondebis primogenita ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'In conspectu Domini Dei tui comedes ea per annos singulos in loco quem elegerit Dominus, tu et domus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Sin autem habuerit maculam, vel claudum fuerit, vel cæcum, aut in aliqua parte deforme vel debile, non immolabitur Domino Deo tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'sed intra portas urbis tuæ comedes illud: tam mundus quam immundus similiter vescentur eis, quasi caprea et cervo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Hoc solum observabis, ut sanguinem eorum non comedas, sed effundes in terram quasi aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Observa mensem novarum frugum, et verni primum temporis, ut facias Phase Domino Deo tuo: quoniam in isto mense eduxit te Dominus Deus tuus de \'gypto nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Immolabisque Phase Domino Deo tuo de ovibus, et de bobus, in loco quem elegerit Dominus Deus tuus, ut habitet nomen ejus ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Non comedes in eo panem fermentatum: septem diebus comedes absque fermento afflictionis panem, quoniam in pavore egressus es de \'gypto: ut memineris diei egressionis tuæ de \'gypto, omnibus diebus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Non apparebit fermentum in omnibus terminis tuis septem diebus, et non remanebit de carnibus ejus, quod immolatum est vespere in die primo, usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Non poteris immolare Phase in qualibet urbium tuarum, quas Dominus Deus tuus daturus est tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'sed in loco quem elegerit Dominus Deus tuus, ut habitet nomen ejus ibi: immolabis Phase vespere ad solis occasum, quando egressus es de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Et coques, et comedes in loco quem elegerit Dominus Deus tuus, maneque consurgens vades in tabernacula tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sex diebus comedes azyma: et in die septima, quia collecta est Domini Dei tui, non facies opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Septem hebdomadas numerabis tibi ab ea die qua falcem in segetem miseris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Et celebrabis diem festum hebdomadarum Domino Deo tuo, oblationem spontaneam manus tuæ, quam offeres juxta benedictionem Domini Dei tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'et epulaberis coram Domino Deo tuo, tu, filius tuus et filia tua, servus tuus et ancilla tua, et Levites qui est intra portas tuas, advena ac pupillus et vidua, qui morantur vobiscum: in loco quem elegerit Dominus Deus tuus, ut habitet nomen ejus ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Et recordaberis quoniam servus fueris in \'gypto: custodiesque ac facies quæ præcepta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Solemnitatem quoque tabernaculorum celebrabis per septem dies, quando collegeris de area et torculari fruges tuas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'et epulaberis in festivitate tua, tu, filius tuus et filia, servus tuus et ancilla, Levites quoque et advena, pupillus et vidua qui intra portas tuas sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Septem diebus Domino Deo tuo festa celebrabis in loco quem elegerit Dominus: benedicetque tibi Dominus Deus tuus in cunctis frugibus tuis, et in omni opere manuum tuarum, erisque in lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Tribus vicibus per annum apparebit omne masculinum tuum in conspectu Domini Dei tui in loco quem elegerit: in solemnitate azymorum, in solemnitate hebdomadarum, et in solemnitate tabernaculorum. Non apparebit ante Dominum vacuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'sed offeret unusquisque secundum quod habuerit juxta benedictionem Domini Dei sui, quam dederit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Judices et magistros constitues in omnibus portis tuis, quas Dominus Deus tuus dederit tibi, per singulas tribus tuas: ut judicent populum justo judicio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'nec in alteram partem declinent. Non accipies personam, nec munera: quia munera excæcant oculos sapientum, et mutant verba justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Juste quod justum est persequeris: ut vivas, et possideas terram, quam Dominus Deus tuus dederit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Non plantabis lucum, et omnem arborem juxta altare Domini Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Nec facies tibi, neque constitues statuam: quæ odit Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Non immolabis Domino Deo tuo ovem, et bovem, in quo est macula, aut quippiam vitii: quia abominatio est Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Cum reperti fuerint apud te intra unam portarum tuarum, quas Dominus Deus tuus dabit tibi, vir aut mulier qui faciant malum in conspectu Domini Dei tui, et transgrediantur pactum illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'ut vadant et servant diis alienis, et adorent eos, solem et lunam, et omnem militiam cæli, quæ non præcepi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'et hoc tibi fuerit nuntiatum, audiensque inquisieris diligenter et verum esse repereris, et abominatio facta est in Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'educes virum ac mulierem, qui rem sceleratissimam perpetrarunt, ad portas civitatis tuæ, et lapidibus obruentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'In ore duorum aut trium testium peribit qui interficietur. Nemo occidatur, uno contra se dicente testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Manus testium prima interficiet eum, et manus reliqui populi extrema mittetur: ut auferas malum de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Si difficile et ambiguum apud te judicium esse perspexeris inter sanguinem et sanguinem, causam et causam, lepram et lepram: et judicum intra portas tuas videris verba variari: surge, et ascende ad locum, quem elegerit Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Veniesque ad sacerdotes Levitici generis, et ad judicem qui fuerit illo tempore: quæresque ab eis, qui indicabunt tibi judicii veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Et facies quodcumque dixerint qui præsunt loco quem elegerit Dominus, et docuerint te');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'juxta legem ejus, sequerisque sententiam eorum, nec declinabis ad dexteram neque ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Qui autem superbierit, nolens obedire sacerdotis imperio, qui eo tempore ministrat Domino Deo tuo, et decreto judicis, morietur homo ille, et auferes malum de Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'cunctusque populus audiens timebit, ut nullus deinceps intumescat superbia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Cum ingressus fueris terram, quam Dominus Deus tuus dabit tibi, et possederis eam, habitaverisque in illa, et dixeris: Constituam super me regem, sicut habent omnes per circuitum nationes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'eum constitues, quem Dominus Deus tuus elegerit de numero fratrum tuorum. Non poteris alterius gentis hominem regem facere, qui non sit frater tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Cumque fuerit constitutus, non multiplicabit sibi equos, nec reducet populum in \'gyptum, equitatus numero sublevatus, præsertim cum Dominus præceperit vobis ut nequaquam amplius per eamdem viam revertamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Non habebit uxores plurimas, quæ alliciant animum ejus, neque argenti et auri immensa pondera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Postquam autem sederit in solio regni sui, describet sibi Deuteronomium legis hujus in volumine, accipiens exemplar a sacerdotibus Leviticæ tribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'et habebit secum, legetque illud omnibus diebus vitæ suæ, ut discat timere Dominum Deum suum, et custodire verba et cæremonias ejus, quæ in lege præcepta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Nec elevetur cor ejus in superbiam super fratres suos, neque declinet in partem dexteram vel sinistram, ut longo tempore regnet ipse et filii ejus super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Non habebunt sacerdotes et Levitæ, et omnes qui de eadem tribu sunt, partem et hæreditatem cum reliquo Israël, quia sacrificia Domini, et oblationes ejus comedent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'et nihil aliud accipient de possessione fratrum suorum: Dominus enim ipse est hæreditas eorum, sicut locutus est illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Hoc erit judicium sacerdotum a populo, et ab his qui offerunt victimas: sive bovem, sive ovem immolaverint, dabunt sacerdoti armum ac ventriculum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'primitias frumenti, vini, et olei, et lanarum partem ex ovium tonsione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Ipsum enim elegit Dominus Deus tuus de cunctis tribubus tuis, ut stet, et ministret nomini Domini, ipse, et filii ejus in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Si exierit Levites ex una urbium tuarum ex omni Israël in qua habitat, et voluerit venire, desiderans locum quem elegerit Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'ministrabit in nomine Domini Dei sui, sicut omnes fratres ejus Levitæ, qui stabunt eo tempore coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Partem ciborum eamdem accipiet, quam et ceteri: excepto eo, quod in urbe sua ex paterna ei successione debetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Quando ingressus fueris terram, quam Dominus Deus tuus dabit tibi, cave ne imitari velis abominationes illarum gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Nec inveniatur in te qui lustret filium suum, aut filiam, ducens per ignem: aut qui ariolos sciscitetur, et observet somnia atque auguria, nec sit maleficus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'nec incantator, nec qui pythones consulat, nec divinos, aut quærat a mortuis veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Omnia enim hæc abominatur Dominus, et propter istiusmodi scelera delebit eos in introitu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Perfectus eris, et absque macula cum Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Gentes istæ, quarum possidebis terram, augures et divinos audiunt: tu autem a Domino Deo tuo aliter institutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Prophetam de gente tua et de fratribus tuis, sicut me, suscitabit tibi Dominus Deus tuus: ipsum audies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'ut petisti a Domino Deo tuo in Horeb, quando concio congregata est, atque dixisti: Ultra non audiam vocem Domini Dei mei, et ignem hunc maximum amplius non videbo, ne moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Et ait Dominus mihi: Bene omnia sunt locuti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Prophetam suscitabo eis de medio fratrum suorum similem tui: et ponam verba mea in ore ejus, loqueturque ad eos omnia quæ præcepero illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Qui autem verba ejus, quæ loquetur in nomine meo, audire noluerit, ego ultor existam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Propheta autem qui arrogantia depravatus voluerit loqui in nomine meo, quæ ego non præcepi illi ut diceret, aut ex nomine alienorum deorum, interficietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Quod si tacita cogitatione responderis: Quomodo possum intelligere verbum, quod Dominus non est locutus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'hoc habebis signum: quod in nomine Domini propheta ille prædixerit, et non evenerit: hoc Dominus non est locutus, sed per tumorem animi sui propheta confinxit: et idcirco non timebis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Cum disperdiderit Dominus Deus tuus gentes, quarum tibi traditurus est terram, et possederis eam, habitaverisque in urbibus ejus et in ædibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'tres civitates separabis tibi in medio terræ, quam Dominus Deus tuus dabit tibi in possessionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'sternens diligenter viam: et in tres æqualiter partes totam terræ tuæ provinciam divides: ut habeat e vicino qui propter homicidium profugus est, quo possit evadere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Hæc erit lex homicidæ fugientis, cujus vita servanda est: qui percusserit proximum suum nesciens, et qui heri et nudiustertius nullum contra eum odium habuisse comprobatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'sed abiisse cum eo simpliciter in silvam ad ligna cædenda, et in succisione lignorum securis fugerit manu, ferrumque lapsum de manubrio amicum ejus percusserit, et occiderit: hic ad unam supradictarum urbium confugiet, et vivet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'ne forsitan proximus ejus, cujus effusus est sanguis, dolore stimulatus, persequatur, et apprehendat eum si longior via fuerit, et percutiat animam ejus, qui non est reus mortis: quia nullum contra eum, qui occisus est, odium prius habuisse monstratur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Idcirco præcipio tibi, ut tres civitates æqualis inter se spatii dividas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Cum autem dilataverit Dominus Deus tuus terminos tuos, sicut juravit patribus tuis, et dederit tibi cunctam terram, quam eis pollicitus est');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(si tamen custodieris mandata ejus, et feceris, quæ hodie præcipio tibi, ut diligas Dominum Deum tuum, et ambules in viis ejus omni tempore), addes tibi tres alias civitates, et supradictarum trium urbium numerum duplicabis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'ut non effundatur sanguis innoxius in medio terræ, quam Dominus Deus tuus dabit tibi possidendam, ne sis sanguinis reus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Si quis autem, odio habens proximum suum, insidiatus fuerit vitæ ejus, surgensque percusserit illum, et mortuus fuerit, fugeritque ad unam de supradictis urbibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'mittent seniores civitatis illius, et arripient eum de loco effugii, tradentque in manu proximi, cujus sanguis effusus est, et morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Non miseraberis ejus, et auferes innoxium sanguinem de Israël, ut bene sit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Non assumes, et transferes terminos proximi tui, quos fixerunt priores in possessione tua, quam Dominus Deus tuus dabit tibi in terra quam acceperis possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Non stabit testis unus contra aliquem, quidquid illud peccati, et facinoris fuerit: sed in ore duorum aut trium testium stabit omne verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Si steterit testis mendax contra hominem, accusans eum prævaricationis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'stabunt ambo, quorum causa est, ante Dominum in conspectu sacerdotum et judicum qui fuerint in diebus illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Cumque diligentissime perscrutantes, invenerint falsum testem dixisse contra fratrem suum mendacium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'reddent ei sicut fratri suo facere cogitavit, et auferes malum de medio tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'ut audientes ceteri timorem habeant, et nequaquam talia audeant facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Non misereberis ejus, sed animam pro anima, oculum pro oculo, dentem pro dente, manum pro manu, pedem pro pede exiges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Si exieris ad bellum contra hostes tuos, et videris equitatus et currus, et majorem quam tu habeas adversarii exercitus multitudinem, non timebis eos: quia Dominus Deus tuus tecum est, qui eduxit te de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Appropinquante autem jam prælio, stabit sacerdos ante aciem, et sic loquetur ad populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Audi, Israël: vos hodie contra inimicos vestros pugnam committitis: non pertimescat cor vestrum, nolite metuere, nolite cedere, nec formidetis eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'quia Dominus Deus vester in medio vestri est, et pro vobis contra adversarios dimicabit, ut eruat vos de periculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Duces quoque per singulas turmas audiente exercitu proclamabunt: Quis est homo qui ædificavit domum novam, et non dedicavit eam? vadat, et revertatur in domum suam, ne forte moriatur in bello, et alius dedicet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Quis est homo qui plantavit vineam, et necdum fecit eam esse communem, de qua vesci omnibus liceat? vadat, et revertatur in domum suam, ne forte moriatur in bello, et alius homo ejus fungatur officio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Quis est homo, qui despondit uxorem, et non accepit eam? vadat, et revertatur in domum suam, ne forte moriatur in bello, et alius homo accipiat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'His dictis addent reliqua, et loquentur ad populum: Quis est homo formidolosus, et corde pavido? vadat, et revertatur in domum suam, ne pavere faciat corda fratrum suorum, sicut ipse timore perterritus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Cumque siluerint duces exercitus, et finem loquendi fecerint, unusquisque suos ad bellandum cuneos præparabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Siquando accesseris ad expugnandam civitatem, offeres ei primum pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Si receperit, et aperuerit tibi portas, cunctus populus, qui in ea est, salvabitur, et serviet tibi sub tributo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Sin autem fœdus inire noluerit, et cœperit contra te bellum, oppugnabis eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Cumque tradiderit Dominus Deus tuus illam in manu tua, percuties omne quod in ea generis masculini est, in ore gladii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'absque mulieribus et infantibus, jumentis et ceteris quæ in civitate sunt. Omnem prædam exercitui divides, et comedes de spoliis hostium tuorum, quæ Dominus Deus tuus dederit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Sic facies cunctis civitatibus, quæ a te procul valde sunt, et non sunt de his urbibus, quas in possessionem accepturus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'De his autem civitatibus, quæ dabuntur tibi, nullum omnino permittes vivere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'sed interficies in ore gladii, Hethæum videlicet, et Amorrhæum, et Chananæum, Pherezæum, et Hevæum, et Jebusæum, sicut præcepit tibi Dominus Deus tuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'ne forte doceant vos facere cunctas abominationes, quas ipsi operati sunt diis suis, et peccetis in Dominum Deum vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quando obsederis civitatem multo tempore, et munitionibus circumdederis ut expugnes eam, non succides arbores, de quibus vesci potest, nec securibus per circuitum debes vastare regionem: quoniam lignum est, et non homo, nec potest bellantium contra te augere numerum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Si qua autem ligna non sunt pomifera, sed agrestia, et in ceteros apta usus, succide, et instrue machinas, donec capias civitatem, quæ contra te dimicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Quando inventum fuerit in terra, quam Dominus Deus tuus daturus est tibi, hominis cadaver occisi, et ignorabitur cædis reus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'egredientur majores natu, et judices tui, et metientur a loco cadaveris singularum per circuitum spatia civitatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'et quam viciniorem ceteris esse perspexerint, seniores civitatis illius tollent vitulam de armento, quæ non traxit jugum, nec terram scidit vomere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'et ducent eam ad vallem asperam atque saxosam, quæ numquam arata est, nec sementem recepit: et cædent in ea cervices vitulæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'accedentque sacerdotes filii Levi, quos elegerit Dominus Deus tuus ut ministrent ei, et benedicant in nomine ejus, et ad verbum eorum omne negotium, et quidquid mundum, vel immundum est, judicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Et venient majores natu civitatis illius ad interfectum, lavabuntque manus suas super vitulam, quæ in valle percussa est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'et dicent: Manus nostræ non effuderunt sanguinem hunc, nec oculi viderunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'propitius esto populo tuo Israël, quem redemisti, Domine, et ne reputes sanguinem innocentem in medio populi tui Israël. Et auferetur ab eis reatus sanguinis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'tu autem alienus eris ab innocentis cruore, qui fusus est, cum feceris quod præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Si egressus fueris ad pugnam contra inimicos tuos, et tradiderit eos Dominus Deus tuus in manu tua, captivosque duxeris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'et videris in numero captivorum mulierem pulchram, et adamaveris eam, voluerisque habere uxorem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'introduces eam in domum tuam: quæ radet cæsariem, et circumcidet ungues,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'et deponet vestem, in qua capta est: sedensque in domo tua, flebit patrem et matrem suam uno mense: et postea intrabis ad eam, dormiesque cum illa, et erit uxor tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Si autem postea non sederit animo tuo, dimittes eam liberam, nec vendere poteris pecunia, nec opprimere per potentiam: quia humiliasti eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Si habuerit homo uxores duas, unam dilectam, et alteram odiosam, genuerintque ex eo liberos, et fuerit filius odiosæ primogenitus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'volueritque substantiam inter filios suos dividere, non poterit filium dilectæ facere primogenitum, et præferre filio odiosæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'sed filium odiosæ agnoscet primogenitum, dabitque ei de his quæ habuerit cuncta duplicia: iste est enim principium liberorum ejus, et huic debentur primogenita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Si genuerit homo filium contumacem et protervum, qui non audiat patris aut matris imperium, et coërcitus obedire contempserit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'apprehendent eum, et ducent ad seniores civitatis illius, et ad portam judicii,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'dicentque ad eos: Filius noster iste protervus et contumax est: monita nostra audire contemnit, comessationibus vacat, et luxuriæ atque conviviis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'lapidibus eum obruet populus civitatis, et morietur, ut auferatis malum de medio vestri, et universus Israël audiens pertimescat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Quando peccaverit homo quod morte plectendum est, et adjudicatus morti appensus fuerit in patibulo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'non permanebit cadaver ejus in ligno, sed in eadem die sepelietur: quia maledictus a Deo est qui pendet in ligno: et nequaquam contaminabis terram tuam, quam Dominus Deus tuus dederit tibi in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Non videbis bovem fratris tui, aut ovem errantem, et præteribis: sed reduces fratri tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'etiamsi non est propinquus frater tuus, nec nosti eum: duces in domum tuam, et erunt apud te quamdiu quærat ea frater tuus, et recipiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Similiter facies de asino, et de vestimento, et de omni re fratris tui, quæ perierit: si inveneris eam, ne negligas quasi alienam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Si videris asinum fratris tui aut bovem cecidisse in via, non despicies, sed sublevabis cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Non induetur mulier veste virili, nec vir utetur veste feminea: abominabilis enim apud Deum est qui facit hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Si ambulans per viam, in arbore vel in terra nidum avis inveneris, et matrem pullis vel ovis desuper incubantem: non tenebis eam cum filiis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'sed abire patieris, captos tenens filios: ut bene sit tibi, et longo vivas tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Cum ædificaveris domum novam, facies murum tecti per circuitum: ne effundatur sanguis in domo tua, et sis reus labente alio, et in præceps ruente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Non seres vineam tuam altero semine: ne et sementis quam sevisti, et quæ nascuntur ex vinea, pariter sanctificentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Non arabis in bove simul et asino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Non indueris vestimento, quod ex lana linoque contextum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Funiculos in fimbriis facies per quatuor angulos pallii tui, quo operieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Si duxerit vir uxorem, et postea odio habuerit eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'quæsieritque occasiones quibus dimittat eam, objiciens ei nomen pessimum, et dixerit: Uxorem hanc accepi, et ingressus ad eam non inveni virginem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'tollent eam pater et mater ejus, et ferent secum signa virginitatis ejus ad seniores urbis qui in porta sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'et dicet pater: Filiam meam dedi huic uxorem: quam quia odit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'imponit ei nomen pessimum, ut dicat: Non inveni filiam tuam virginem: et ecce hæc sunt signa virginitatis filiæ meæ. Expandent vestimentum coram senioribus civitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'apprehendentque senes urbis illius virum, et verberabunt illum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'condemnantes insuper centum siclis argenti, quos dabit patri puellæ, quoniam diffamavit nomen pessimum super virginem Israël: habebitque eam uxorem, et non poterit dimittere eam omnibus diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Quod si verum est quod objicit, et non est in puella inventa virginitas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'ejicient eam extra fores domus patris sui, et lapidibus obruent viri civitatis illius, et morietur: quoniam fecit nefas in Israël, ut fornicaretur in domo patris sui: et auferes malum de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Si dormierit vir cum uxore alterius, uterque morietur, id est, adulter et adultera: et auferes malum de Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Si puellam virginem desponderit vir, et invenerit eam aliquis in civitate, et concubuerit cum ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'educes utrumque ad portam civitatis illius, et lapidibus obruentur: puella, quia non clamavit, cum esset in civitate: vir, quia humiliavit uxorem proximi sui: et auferes malum de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Sin autem in agro repererit vir puellam, quæ desponsata est, et apprehendens concubuerit cum ea, ipse morietur solus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'puella nihil patietur, nec est rea mortis: quoniam sicut latro consurgit contra fratrem suum, et occidit animam ejus, ita et puella perpessa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Sola erat in agro: clamavit, et nullus affuit qui liberaret eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Si invenerit vir puellam virginem, quæ non habet sponsum, et apprehendens concubuerit cum illa, et res ad judicium venerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'dabit qui dormivit cum ea, patri puellæ quinquaginta siclos argenti, et habebit eam uxorem, quia humiliavit illam: non poterit dimittere eam cunctis diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Non accipiet homo uxorem patris sui, nec revelabit operimentum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Non intravit eunuchus, attritis vel amputatis testiculis et abscisso veretro, ecclesiam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Non ingredietur mamzer, hoc est, de scorto natus, in ecclesiam Domini, usque ad decimam generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ammonites et Moabites etiam post decimam generationem non intrabunt ecclesiam Domini in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'quia noluerunt vobis occurrere cum pane et aqua in via quando egressi estis de \'gypto: et quia conduxerunt contra te Balaam filium Beor de Mesopotamia Syriæ, ut malediceret tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'et noluit Dominus Deus tuus audire Balaam, vertitque maledictionem ejus in benedictionem tuam, eo quod diligeret te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Non facies cum eis pacem, nec quæras eis bona cunctis diebus vitæ tuæ in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Non abominaberis Idumæum, quia frater tuus est: nec \'gyptium, quia advena fuisti in terra ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Qui nati fuerint ex eis, tertia generatione intrabunt in ecclesiam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Quando egressus fueris adversus hostes tuos in pugnam, custodies te ab omni re mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Si fuerit inter vos homo, qui nocturno pollutus sit somnio, egredietur extra castra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'et non revertetur, priusquam ad vesperam lavetur aqua: et post solis occasum regredietur in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Habebis locum extra castra, ad quem egrediaris ad requisita naturæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'gerens paxillum in balteo: cumque sederis, fodies per circuitum, et egesta humo operies');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'quo revelatus es: Dominus enim Deus tuus ambulat in medio castrorum, ut eruat te, et tradat tibi inimicos tuos: et sint castra tua sancta, et nihil in eis appareat fœditatis, ne derelinquat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Non trades servum domino suo, qui ad te confugerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Habitabit tecum in loco, qui ei placuerit, et in una urbium tuarum requiescet: ne contristes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Non erit meretrix de filiabus Israël, nec scortator de filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Non offeres mercedem prostibuli, nec pretium canis in domo Domini Dei tui, quidquid illud est quod voveris: quia abominatio est utrumque apud Dominum Deum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Non fœnerabis fratri tuo ad usuram pecuniam, nec fruges, nec quamlibet aliam rem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'sed alieno. Fratri autem tuo absque usura id quo indiget, commodabis: ut benedicat tibi Dominus Deus tuus in omni opere tuo in terra, ad quam ingredieris possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Cum votum voveris Domino Deo tuo, non tardabis reddere: quia requiret illud Dominus Deus tuus, et si moratus fueris, reputabitur tibi in peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Si nolueris polliceri, absque peccato eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Quod autem semel egressum est de labiis tuis, observabis, et facies sicut promisisti Domino Deo tuo, et propria voluntate et ore tuo locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ingressus vineam proximi tui, comede uvas, quantum tibi placuerit: foras autem ne efferas tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Si intraveris in segetem amici tui, franges spicas, et manu conteres: falce autem non metes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Si acceperit homo uxorem, et habuerit eam, et non invenerit gratiam ante oculos ejus propter aliquam fœditatem: scribet libellum repudii, et dabit in manu illius, et dimittet eam de domo sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Cumque egressa alterum maritum duxerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'et ille quoque oderit eam, dederitque ei libellum repudii, et dimiserit de domo sua, vel certe mortuus fuerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'non poterit prior maritus recipere eam in uxorem: quia polluta est, et abominabilis facta est coram Domino: ne peccare facias terram tuam, quam Dominus Deus tuus tradiderit tibi possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Cum acceperit homo nuper uxorem, non procedet ad bellum, nec ei quippiam necessitatis injungetur publicæ, sed vacabit absque culpa domi suæ, ut uno anno lætetur cum uxore sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Non accipies loco pignoris inferiorem, et superiorem molam: quia animam suam opposuit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Si deprehensus fuerit homo sollicitans fratrem suum de filiis Israël, et vendito eo acceperit pretium, interficietur, et auferes malum de medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Observa diligenter ne incurras plagam lepræ, sed facies quæcumque docuerint te sacerdotes Levitici generis, juxta id quod præcepi eis, et imple sollicite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Mementote quæ fecerit Dominus Deus vester Mariæ in via cum egrederemini de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Cum repetes a proximo tuo rem aliquam, quam debet tibi, non ingredieris domum ejus ut pignus auferas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'sed stabis foris, et ille tibi proferet quod habuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Sin autem pauper est, non pernoctabit apud te pignus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'sed statim reddes ei ante solis occasum: ut dormiens in vestimento suo, benedicat tibi, et habeas justitiam coram Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Non negabis mercedem indigentis, et pauperis fratris tui, sive advenæ, qui tecum moratur in terra, et intra portas tuas est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'sed eadem die reddes ei pretium laboris sui ante solis occasum, quia pauper est, et ex eo sustentat animam suam: ne clamet contra te ad Dominum, et reputetur tibi in peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Non occidentur patres pro filiis, nec filii pro patribus, sed unusquisque pro peccato suo morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Non pervertes judicium advenæ et pupilli, nec auferes pignoris loco viduæ vestimentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Memento quod servieris in \'gypto, et eruerit te Dominus Deus tuus inde. Idcirco præcipio tibi ut facias hanc rem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Quando messueris segetem in agro tuo, et oblitus manipulum reliqueris, non reverteris, ut tollas illum: sed advenam, et pupillum, et viduam auferre patieris, ut benedicat tibi Dominus Deus tuus in omni opere manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Si fruges collegeris olivarum, quidquid remanserit in arboribus, non reverteris ut colligas: sed relinques advenæ, pupillo, ac viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Si vindemiaveris vineam tuam, non colliges remanentes racemos: sed cedent in usus advenæ, pupilli, ac viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Memento quod et tu servieris in \'gypto, et idcirco præcipio tibi ut facias hanc rem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Si fuerit causa inter aliquos, et interpellaverint judices: quem justum esse perspexerint, illi justitiæ palmam dabunt: quem impium, condemnabunt impietatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Sin autem eum, qui peccavit, dignum viderint plagis: prosternent, et coram se facient verberari. Pro mensura peccati erit et plagarum modus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'ita dumtaxat, ut quadragenarium numerum non excedant: ne fœde laceratus ante oculos tuos abeat frater tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Non ligabis os bovis terentis in area fruges tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Quando habitaverint fratres simul, et unus ex eis absque liberis mortuus fuerit, uxor defuncti non nubet alteri: sed accipiet eam frater ejus, et suscitabit semen fratris sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'et primogenitum ex ea filium nomine illius appellabit, ut non deleatur nomen ejus ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Sin autem noluerit accipere uxorem fratris sui, quæ ei lege debetur, perget mulier ad portam civitatis, et interpellabit majores natu, dicetque: Non vult frater viri mei suscitare nomen fratris sui in Israël, nec me in conjugem sumere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Statimque accersiri eum facient, et interrogabunt. Si responderit: Nolo eam uxorem accipere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'accedet mulier ad eum coram senioribus, et tollet calceamentum de pede ejus, spuetque in faciem illius, et dicet: Sic fiet homini, qui non ædificat domum fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Et vocabitur nomen illius in Israël, Domus discalceati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Si habuerint inter se jurgium viri duo, et unus contra alterum rixari cœperit, volensque uxor alterius eruere virum suum de manu fortioris, miseritque manum, et apprehenderit verenda ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'abscides manum illius, nec flecteris super eam ulla misericordia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Non habebis in sacculo diversa pondera, majus et minus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'nec erit in domo tua modius major, et minor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Pondus habebis justum et verum, et modius æqualis et verus erit tibi: ut multo vivas tempore super terram, quam Dominus Deus tuus dederit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Abominatur enim Dominus tuus eum qui facit hæc, et aversatur omnem injustitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Memento quæ fecerit tibi Amalec in via quando egrediebaris ex \'gypto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'quomodo occurrerit tibi, et extremos agminis tui, qui lassi residebant, ceciderit, quando tu eras fame et labore confectus: et non timuerit Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Cum ergo Dominus Deus tuus dederit tibi requiem, et subjecerit cunctas per circuitum nationes in terra, quam tibi pollicitus est: delebis nomen ejus sub cælo. Cave ne obliviscaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Cumque intraveris terram, quam Dominus Deus tuus tibi daturus est possidendam, et obtinueris eam, atque habitaveris in ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'tolles de cunctis frugibus tuis primitias, et pones in cartallo, pergesque ad locum quem Dominus Deus tuus elegerit, ut ibi invocetur nomen ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'accedesque ad sacerdotem, qui fuerit in diebus illis, et dices ad eum: Profiteor hodie coram Domino Deo tuo, quod ingressus sum in terram, pro qua juravit patribus nostris, ut daret eam nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Suscipiensque sacerdos cartallum de manu tua, ponet ante altare Domini Dei tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'et loqueris in conspectu Domini Dei tui: Syrus persequebatur patrem meum, qui descendit in \'gyptum, et ibi peregrinatus est in paucissimo numero: crevitque in gentem magnam ac robustam et infinitæ multitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Afflixeruntque nos \'gyptii, et persecuti sunt, imponentes onera gravissima:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'et clamavimus ad Dominum Deum patrum nostrorum: qui exaudivit nos, et respexit humilitatem nostram, et laborem, atque angustiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'et eduxit nos de \'gypto in manu forti, et brachio extento, in ingenti pavore, in signis atque portentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'et introduxit ad locum istum, et tradidit nobis terram lacte et melle manantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Et idcirco nunc offero primitias frugum terræ, quam Dominus dedit mihi. Et dimittes eas in conspectu Domini Dei tui, et adorato Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Et epulaberis in omnibus bonis, quæ Dominus Deus tuus dederit tibi et domui tuæ, tu et Levites, et advena qui tecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quando compleveris decimam cunctarum frugum tuarum, anno decimarum tertio, dabis Levitæ, et advenæ, et pupillo et viduæ, ut comedant intra portas tuas, et saturentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'loquerisque in conspectu Domini Deo tui: Abstuli quod sanctificatum est de domo mea, et dedi illud Levitæ et advenæ, et pupillo ac viduæ, sicut jussisti mihi: non præterivi mandata tua, nec sum oblitus imperii tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Non comedi ex eis in luctu meo, nec separavi ea in qualibet immunditia, nec expendi ex his quidquam in re funebri. Obedivi voci Domini Dei mei, et feci omnia sicut præcepisti mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Respice de sanctuario tuo, et de excelso cælorum habitaculo, et benedic populo tuo Israël, et terræ, quam dedisti nobis, sicut jurasti patribus nostris, terræ lacte et melle mananti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Hodie Dominus Deus tuus præcepit tibi ut facias mandata hæc atque judicia: et custodias et impleas ex toto corde tuo, et ex tota anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Dominum elegisti hodie, ut sit tibi Deus, et ambules in viis ejus, et custodias cæremonias illius, et mandata atque judicia, et obedias ejus imperio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Et Dominus elegit te hodie ut sis ei populus peculiaris, sicut locutus est tibi, et custodias omnia præcepta illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'et faciat te excelsiorem cunctis gentibus quas creavit, in laudem, et nomen, et gloriam suam: ut sis populus sanctus Domini Dei tui, sicut locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Præcepit autem Moyses et seniores Israël populo, dicentes: Custodite omne mandatum quod præcipio vobis hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Cumque transieritis Jordanem in terram, quam Dominus Deus tuus dabit tibi, eriges ingentes lapides, et calce lævigabis eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'ut possis in eis scribere omnia verba legis hujus, Jordane transmisso: ut introëas terram, quam Dominus Deus tuus dabit tibi, terram lacte et melle manantem, sicut juravit patribus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Quando ergo transieritis Jordanem, erigite lapides, quos ego hodie præcipio vobis in monte Hebal, et lævigabis eos calce:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'et ædificabis ibi altare Domino Deo tuo de lapidibus, quos ferrum non tetigit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'et de saxis informibus et impolitis: et offeres super eo holocausta Domino Deo tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'et immolabis hostias pacificas, comedesque ibi, et epulaberis coram Domino Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Et scribes super lapides omnia verba legis hujus plane et lucide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Dixeruntque Moyses et sacerdotes Levitici generis ad omnem Israëlem: Attende, et audi, Israël: hodie factus es populus Domini Dei tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'audies vocem ejus, et facies mandata atque justitias, quas ego præcipio tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Præcepitque Moyses populo in die illo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Hi stabunt ad benedicendum populo super montem Garizim, Jordane transmisso: Simeon, Levi, Judas, Issachar, Joseph, et Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Et e regione isti stabunt ad maledicendum in monte Hebal: Ruben, Gad, et Aser, et Zabulon, Dan, et Nephthali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Et pronuntiabunt Levitæ, dicentque ad omnes viros Israël excelsa voce:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maledictus homo qui facit sculptile et conflatile, abominationem Domini, opus manuum artificum, ponetque illud in abscondito: et respondebit omnis populus, et dicet: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maledictus qui non honorat patrem suum, et matrem: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maledictus qui transfert terminos proximi sui: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maledictus qui errare facit cæcum in itinere: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maledictus qui pervertit judicium advenæ, pupilli et viduæ: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maledictus qui dormit cum uxore patris sui, et revelat operimentum lectuli ejus: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maledictus qui dormit cum omni jumento: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maledictus qui dormit cum sorore sua, filia patris sui, vel matris suæ: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maledictus qui dormit cum socru sua: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maledictus qui clam percusserit proximum suum: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maledictus qui accipit munera, ut percutiat animam sanguinis innocentis: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maledictus qui non permanet in sermonibus legis hujus, nec eos opere perficit: et dicet omnis populus: Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Si autem audieris vocem Domini Dei tui, ut facias atque custodias omnia mandata ejus, quæ ego præcipio tibi hodie, faciet te Dominus Deus tuus excelsiorem cunctis gentibus, quæ versantur in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Venientque super te universæ benedictiones istæ, et apprehendent te: si tamen præcepta ejus audieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Benedictus tu in civitate, et benedictus in agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Benedictus fructus ventris tui, et fructus terræ tuæ, fructusque jumentorum tuorum, greges armentorum tuorum, et caulæ ovium tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Benedicta horrea tua, et benedictæ reliquiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Benedictus eris tu ingrediens et egrediens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Dabit Dominus inimicos tuos, qui consurgunt adversum te, corruentes in conspectu tuo: per unam viam venient contra te, et per septem fugient a facie tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Emittet Dominus benedictionem super cellaria tua, et super omnia opera manuum tuarum: benedicetque tibi in terra, quam acceperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Suscitabit te Dominus sibi in populum sanctum, sicut juravit tibi: si custodieris mandata Domini Dei tui, et ambulaveris in viis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Videbuntque omnes terrarum populi quod nomen Domini invocatum sit super te, et timebunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Abundare te faciet Dominus omnibus bonis, fructu uteri tui, et fructu jumentorum tuorum, fructu terræ tuæ, quam juravit Dominus patribus tuis ut daret tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Aperiet Dominus thesaurum suum optimum, cælum, ut tribuat pluviam terræ tuæ in tempore suo: benedicetque cunctis operibus manuum tuarum. Et fœnerabis gentibus multis, et ipse a nullo fœnus accipies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Constituet te Dominus in caput, et non in caudam: et eris semper supra, et non subter: si tamen audieris mandata Domini Dei tui quæ ego præcipio tibi hodie, et custodieris et feceris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'ac non declinaveris ab eis nec ad dexteram, nec ad sinistram, nec secutus fueris deos alienos, neque colueris eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Quod si audire nolueris vocem Domini Dei tui, ut custodias, et facias omnia mandata ejus et cæremonias, quas ego præcipio tibi hodie, venient super te omnes maledictiones istæ, et apprehendent te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Maledictus eris in civitate, maledictus in agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Maledictum horreum tuum, et maledictæ reliquiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Maledictus fructus ventris tui, et fructus terræ tuæ, armenta boum tuorum, et greges ovium tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Maledictus eris ingrediens, et maledictus egrediens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Mittet Dominus super te famem et esuriem, et increpationem in omnia opera tua, quæ tu facies: donec conterat te, et perdat velociter, propter adinventiones tuas pessimas in quibus reliquisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Adjungat tibi Dominus pestilentiam, donec consumat te de terra ad quam ingredieris possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Percutiat te Dominus egestate, febri et frigore, ardore et æstu, et aëre corrupto ac rubigine, et persequatur donec pereas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Sit cælum, quod supra te est, æneum: et terra, quam calcas, ferrea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Det Dominus imbrem terræ tuæ pulverem, et de cælo descendat super te cinis, donec conteraris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Tradat te Dominus corruentem ante hostes tuos: per unam viam egrediaris contra eos, et per septem fugias, et dispergaris per omnia regna terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'sitque cadaver tuum in escam cunctis volatilibus cæli, et bestiis terræ, et non sit qui abigat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Percutiat te Dominus ulcere \'gypti, et partem corporis, per quam stercora egeruntur, scabie quoque et prurigine: ita ut curari nequeas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Percutiat te Dominus amentia et cæcitate ac furore mentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'et palpes in meridie sicut palpare solet cæcus in tenebris, et non dirigas vias tuas. Omnique tempore calumniam sustineas, et opprimaris violentia, nec habeas qui liberet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Uxorem accipias, et alius dormiat cum ea. Domum ædifices, et non habites in ea. Plantes vineam, et non vindemies eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Bos tuus immoletur coram te, et non comedas ex eo. Asinus tuus rapiatur in conspectu tuo, et non reddatur tibi. Oves tuæ dentur inimicis tuis, et non sit qui te adjuvet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Filii tui et filiæ tuæ tradantur alteri populo, videntibus oculis tuis, et deficientibus ad conspectum eorum tota die, et non sit fortitudo in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Fructus terræ tuæ, et omnes labores tuos, comedat populus quem ignoras: et sis semper calumniam sustinens, et oppressus cunctis diebus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'et stupens ad terrorem eorum quæ videbunt oculi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Percutiat te Dominus ulcere pessimo in genibus et in suris, sanarique non possis a planta pedis usque ad verticem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Ducet te Dominus, et regem tuum, quem constitueris super te, in gentem, quam ignoras tu et patres tui: et servies ibi diis alienis, ligno et lapidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Et eris perditus in proverbium ac fabulam omnibus populis, ad quos te introduxerit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Sementem multam jacies in terram, et modicum congregabis: quia locustæ devorabunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vineam plantabis, et fodies: et vinum non bibes, nec colliges ex ea quippiam: quoniam vastabitur vermibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olivas habebis in omnibus terminis tuis, et non ungeris oleo: quia defluent, et peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Filios generabis et filias, et non frueris eis: quoniam ducentur in captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Omnes arbores tuas et fruges terræ tuæ rubigo consumet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Advena, qui tecum versatur in terra, ascendet super te, eritque sublimior: tu autem descendes, et eris inferior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Ipse fœnerabit tibi, et tu non fœnerabis ei. Ipse erit in caput, et tu eris in caudam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Et venient super te omnes maledictiones istæ, et persequentes apprehendent te, donec intereas: quia non audisti vocem Domini Dei tui, nec servasti mandata ejus et cæremonias, quas præcepit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Et erunt in te signa atque prodigia, et in semine tuo usque in sempiternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'eo quod non servieris Domino Deo tuo in gaudio, cordisque lætitia, propter rerum omnium abundantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Servies inimico tuo, quem immittet tibi Dominus, in fame, et siti, et nuditate, et omni penuria: et ponet jugum ferreum super cervicem tuam, donec te conterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Adducet Dominus super te gentem de longinquo, et de extremis terræ finibus in similitudinem aquilæ volantis cum impetu, cujus linguam intelligere non possis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'gentem procacissimam, quæ non deferat seni, nec misereatur parvuli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'et devoret fructum jumentorum tuorum, ac fruges terræ tuæ: donec intereas, et non relinquat tibi triticum, vinum, et oleum, armenta boum, et greges ovium: donec te disperdat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'et conterat in cunctis urbibus tuis, et destruantur muri tui firmi atque sublimes, in quibus habebas fiduciam in omni terra tua. Obsideberis intra portas tuas in omni terra tua, quam dabit tibi Dominus Deus tuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'et comedes fructum uteri tui, et carnes filiorum tuorum et filiarum tuarum, quas dederit tibi Dominus Deus tuus, in angustia et vastitate qua opprimet te hostis tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Homo delicatus in te, et luxuriosus valde, invidebit fratri suo, et uxori, quæ cubat in sinu suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'ne det eis de carnibus filiorum suorum, quas comedet: eo quod nihil aliud habeat in obsidione et penuria, qua vastaverint te inimici tui intra omnes portas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Tenera mulier et delicata, quæ super terram ingredi non valebat, nec pedis vestigium figere, propter mollitiem et teneritudinem nimiam, invidebit viro suo, qui cubat in sinu ejus, super filii et filiæ carnibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'et illuvie secundarum, quæ egrediuntur de medio feminum ejus, et super liberis qui eadem hora nati sunt. Comedent enim eos clam propter rerum omnium penuriam in obsidione et vastitate, qua opprimet te inimicus tuus intra portas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Nisi custodieris et feceris omnia verba legis hujus, quæ scripta sunt in hoc volumine, et timueris nomen ejus gloriosum et terribile, hoc est, Dominum Deum tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'augebit Dominus plagas tuas, et plagas seminis tui, plagas magnas et perseverantes, infirmitates pessimas et perpetuas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'et convertet in te omnes afflictiones \'gypti, quas timuisti, et adhærebunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Insuper et universos languores, et plagas, quæ non sunt scriptæ in volumine legis hujus, inducet Dominus super te, donec te conterat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'et remanebitis pauci numero, qui prius eratis sicut astra cæli præ multitudine, quoniam non audisti vocem Domini Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Et sicut ante lætatus est Dominus super vos, bene vobis faciens, vosque multiplicans: sic lætabitur disperdens vos atque subvertens, ut auferamini de terra, ad quam ingredieris possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Disperget te Dominus in omnes populos, a summitate terræ usque ad terminos ejus: et servies ibi diis alienis, quos et tu ignoras et patres tui, lignis et lapidibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'In gentibus quoque illis non quiesces, neque erit requies vestigio pedis tui. Dabit enim tibi Dominus ibi cor pavidum, et deficientes oculos, et animam consumptam mœrore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'et erit vita tua quasi pendens ante te. Timebis nocte et die, et non credes vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Mane dices: Quis mihi det vesperum? et vespere: Quis mihi det mane? propter cordis tui formidinem, qua terreberis, et propter ea, quæ tuis videbis oculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Reducet te Dominus classibus in \'gyptum per viam de qua dixit tibi ut eam amplius non videres. Ibi venderis inimicis tuis in servos et ancillas, et non erit qui emat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Hæc sunt verba fœderis quod præcepit Dominus Moysi ut feriret cum filiis Israël in terra Moab: præter illud fœdus, quod cum eis pepigit in Horeb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Vocavitque Moyses omnem Israël, et dixit ad eos: Vos vidistis universa, quæ fecit Dominus coram vobis in terra \'gypti Pharaoni, et omnibus servis ejus, universæque terræ illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'tentationes magnas, quas viderunt oculi tui, signa illa, portentaque ingentia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'et non dedit vobis Dominus cor intelligens, et oculos videntes, et aures quæ possunt audire, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Adduxit vos quadraginta annis per desertum: non sunt attrita vestimenta vestra, nec calceamenta pedum vestrorum vetustate consumpta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Panem non comedistis, vinum et siceram non bibistis: ut sciretis quia ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Et venistis ad hunc locum: egressusque est Sehon rex Hesebon, et Og rex Basan, occurrentes nobis ad pugnam. Et percussimus eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'et tulimus terram eorum, ac tradidimus possidendam Ruben et Gad, et dimidiæ tribui Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Custodite ergo verba pacti hujus, et implete ea: ut intelligatis universa quæ facitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vos statis hodie cuncti coram Domino Deo vestro, principes vestri, et tribus, ac majores natu, atque doctores, omnis populus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'liberi et uxores vestræ, et advena qui tecum moratur in castris, exceptis lignorum cæsoribus, et his qui comportant aquas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'ut transeas in fœdere Domini Dei tui, et in jurejurando quod hodie Dominus Deus tuus percutit tecum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'ut suscitet te sibi in populum, et ipse sit Deus tuus sicut locutus est tibi, et sicut juravit patribus tuis, Abraham, Isaac, et Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Nec vobis solis ego hoc fœdus ferio, et hæc juramenta confirmo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'sed cunctis præsentibus et absentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Vos enim nostis quomodo habitaverimus in terra \'gypti, et quomodo transierimus per medium nationum, quas transeuntes');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'vidistis abominationes et sordes, id est, idola eorum, lignum et lapidem, argentum et aurum, quæ colebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Ne forte sit inter vos vir aut mulier, familia aut tribus, cujus cor aversum est hodie a Domino Deo nostro, ut vadat et serviat diis illarum gentium: et sit inter vos radix germinans fel et amaritudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Cumque audierit verba juramenti hujus, benedicat sibi in corde suo, dicens: Pax erit mihi, et ambulabo in pravitate cordis mei: et absumat ebria sitientem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'et Dominus non ignoscat ei: sed tunc quam maxime furor ejus fumet, et zelus contra hominem illum, et sedeant super eum omnia maledicta, quæ scripta sunt in hoc volumine: et deleat Dominus nomen ejus sub cælo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'et consumat eum in perditionem ex omnibus tribubus Israël, juxta maledictiones, quæ in libro legis hujus ac fœderis continentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Dicetque sequens generatio, et filii qui nascentur deinceps, et peregrini qui de longe venerint, videntes plagas terræ illius, et infirmitates, quibus eam afflixerit Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'sulphure, et salis ardore comburens, ita ut ultra non seratur, nec virens quippiam germinet, in exemplum subversionis Sodomæ et Gomorrhæ, Adamæ et Seboim, quas subvertit Dominus in ira et furore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Et dicent omnes gentes: Quare sic fecit Dominus terræ huic? quæ est hæc ira furoris ejus immensa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Et respondebunt: Quia dereliquerunt pactum Domini, quod pepigit cum patribus eorum, quando eduxit eos de terra \'gypti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'et servierunt diis alienis, et adoraverunt eos, quos nesciebant, et quibus non fuerant attributi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'idcirco iratus est furor Domini contra terram istam, ut induceret super eam omnia maledicta, quæ in hoc volumine scripta sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'et ejecit eos de terra sua in ira et in furore, et in indignatione maxima, projecitque in terram alienam, sicut hodie comprobatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Abscondita, Domino Deo nostro; quæ manifesta sunt, nobis et filiis nostris usque in sempiternum, ut faciamus universa verba legis hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Cum ergo venerint super te omnes sermones isti, benedictio sive maledictio, quam proposui in conspectu tuo: et ductus pœnitudine cordis tui in universis gentibus, in quas disperserit te Dominus Deus tuus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'et reversus fueris ad eum, et obedieris ejus imperiis, sicut ego hodie præcipio tibi, cum filiis tuis, in toto corde tuo, et in tota anima tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'reducet Dominus Deus tuus captivitatem tuam, ac miserebitur tui, et rursum congregabit te de cunctis populis, in quos te ante dispersit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Si ad cardines cæli fueris dissipatus, inde te retrahet Dominus Deus tuus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'et assumet, atque introducet in terram, quam possederunt patres tui, et obtinebis eam: et benedicens tibi, majoris numeri te esse faciat quam fuerunt patres tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Circumcidet Dominus Deus tuus cor tuum, et cor seminis tui, ut diligas Dominum Deum tuum in toto corde tuo, et in tota anima tua, ut possis vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Omnes autem maledictiones has convertet super inimicos tuos, et eos qui oderunt te et persequuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Tu autem reverteris, et audies vocem Domini Dei tui, faciesque universa mandata quæ ego præcipio tibi hodie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'et abundare te faciet Dominus Deus tuus in cunctis operibus manuum tuarum, in sobole uteri tui, et in fructu jumentorum tuorum, in ubertate terræ tuæ, et in rerum omnium largitate. Revertetur enim Dominus, ut gaudeat super te in omnibus bonis, sicut gavisus est in patribus tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'si tamen audieris vocem Domini Dei tui, et custodieris præcepta ejus et cæremonias, quæ in hac lege conscripta sunt: et revertaris ad Dominum Deum tuum in toto corde tuo, et in tota anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Mandatum hoc, quod ego præcipio tibi hodie, non supra te est, neque procul positum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'nec in cælo situm, ut possis dicere: Quis nostrum valet ad cælum ascendere, ut deferat illud ad nos, et audiamus atque opere compleamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'neque trans mare positum: ut causeris, et dicas: Quis ex nobis poterit transfretare mare, et illud ad nos usque deferre, ut possimus audire et facere quod præceptum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'sed juxta te est sermo valde, in ore tuo, et in corde tuo, ut facias illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Considera quod hodie proposuerim in conspectu tuo, vitam et bonum, et e contrario mortem et malum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'ut diligas Dominum Deum tuum, et ambules in viis ejus, et custodias mandata illius ac cæremonias atque judicia: et vivas, atque multiplicet te, benedicatque tibi in terra, ad quam ingredieris possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Si autem aversum fuerit cor tuum, et audire nolueris, atque errore deceptus adoraveris deos alienos, et servieris eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'prædico tibi hodie quod pereas, et parvo tempore moreris in terra, ad quam, Jordane transmisso, ingredieris possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Testes invoco hodie cælum et terram, quod proposuerim vobis vitam et mortem, benedictionem et maledictionem. Elige ergo vitam, ut et tu vivas, et semen tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'et diligas Dominum Deum tuum, atque obedias voci ejus, et illi adhæreas (ipse est enim vita tua, et longitudo dierum tuorum), ut habites in terra, pro qua juravit Dominus patribus tuis, Abraham, Isaac, et Jacob, ut daret eam illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Abiit itaque Moyses, et locutus est omnia verba hæc ad universum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'et dixit ad eos: Centum viginti annorum sum hodie; non possum ultra egredi et ingredi, præsertim cum et Dominus dixerit mihi: Non transibis Jordanem istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Dominus ergo Deus tuus transibit ante te: ipse delebit omnes gentes has in conspectu tuo, et possidebis eas: et Josue iste transibit ante te, sicut locutus est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Facietque Dominus eis sicut fecit Sehon et Og regibus Amorrhæorum, et terræ eorum, delebitque eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Cum ergo et hos tradiderit vobis, similiter facietis eis, sicut præcepi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Viriliter agite, et confortamini: nolite timere, nec paveatis ad conspectum eorum: quia Dominus Deus tuus ipse est ductor tuus, et non dimittet, nec derelinquet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Vocavitque Moyses Josue, et dixit ei coram omni Israël: Confortare, et esto robustus: tu enim introduces populum istum in terram, quam daturum se patribus eorum juravit Dominus, et tu eam sorte divides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Et Dominus qui ductor est vester, ipse erit tecum: non dimittet, nec derelinquet te: noli timere, nec paveas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Scripsit itaque Moyses legem hanc, et tradidit eam sacerdotibus filiis Levi, qui portabant arcam fœderis Domini, et cunctis senioribus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Præcepitque eis, dicens: Post septem annos, anno remissionis, in solemnitate tabernaculorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'convenientibus cunctis ex Israël, ut appareant in conspectu Domini Dei tui in loco quem elegerit Dominus, leges verba legis hujus coram omni Israël, audientibus eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'et in unum omni populo congregato, tam viris quam mulieribus, parvulis, et advenis, qui sunt intra portas tuas: ut audientes discant, et timeant Dominum Deum vestrum, et custodiant, impleantque omnes sermones legis hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Filii quoque eorum qui nunc ignorant, ut audire possint, et timeant Dominum Deum suum cunctis diebus quibus versantur in terra, ad quam vos, Jordane transmisso, pergitis obtinendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Et ait Dominus ad Moysen: Ecce prope sunt dies mortis tuæ: voca Josue, et state in tabernaculo testimonii, ut præcipiam ei. Abierunt ergo Moyses et Josue, et steterunt in tabernaculo testimonii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'apparuitque Dominus ibi in columna nubis, quæ stetit in introitu tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Dixitque Dominus ad Moysen: Ecce tu dormies cum patribus tuis, et populus iste consurgens fornicabitur post deos alienos in terra, ad quam ingreditur ut habitet in ea: ibi derelinquet me, et irritum faciet fœdus, quod pepigi cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Et irascetur furor meus contra eum in die illo: et derelinquam eum, et abscondam faciem meam ab eo, et erit in devorationem: invenient eum omnia mala et afflictiones, ita ut dicat in illo die: Vere quia non est Deus mecum, invenerunt me hæc mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ego autem abscondam, et celabo faciem meam in die illo propter omnia mala, quæ fecit, quia secutus est deos alienos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Nunc itaque scribite vobis canticum istud, et docete filios Israël: ut memoriter teneant, et ore decantent, et sit mihi carmen istud pro testimonio inter filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Introducam enim eum in terram, pro qua juravi patribus ejus, lacte et melle manantem. Cumque comederint, et saturati, crassique fuerint, avertentur ad deos alienos, et servient eis: detrahentque mihi, et irritum facient pactum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Postquam invenerint eum mala multa et afflictiones, respondebit ei canticum istud pro testimonio, quod nulla delebit oblivio ex ore seminis sui. Scio enim cogitationes ejus, quæ facturus sit hodie, antequam introducam eum in terram, quam ei pollicitus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Scripsit ergo Moyses canticum, et docuit filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Præcepitque Dominus Josue filio Nun, et ait: Confortare, et esto robustus: tu enim introduces filios Israël in terram, quam pollicitus sum, et ego ero tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Postquam ergo scripsit Moyses verba legis hujus in volumine, atque complevit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'præcepit Levitis, qui portabant arcam fœderis Domini, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Tollite librum istum, et ponite eum in latere arcæ fœderis Domini Dei vestri: ut sit ibi contra te in testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Ego enim scio contentionem tuam, et cervicem tuam durissimam. Adhuc vivente me et ingrediente vobiscum, semper contentiose egistis contra Dominum: quanto magis cum mortuus fuero?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Congregate ad me omnes majores natu per tribus vestras, atque doctores, et loquar audientibus eis sermones istos, et invocabo contra eos cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Novi enim quod post mortem meam inique agetis, et declinabitis cito de via, quam præcepi vobis: et occurrent vobis mala in extremo tempore, quando feceritis malum in conspectu Domini, ut irritetis eum per opera manuum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Locutus est ergo Moyses, audiente universo cœtu Israël, verba carminis hujus, et ad finem usque complevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Audite, cæli, quæ loquor: audiat terra verba oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Concrescat ut pluvia doctrina mea, fluat ut ros eloquium meum, quasi imber super herbam, et quasi stillæ super gramina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Quia nomen Domini invocabo: date magnificentiam Deo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Dei perfecta sunt opera, et omnes viæ ejus judicia: Deus fidelis, et absque ulla iniquitate, justus et rectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Peccaverunt ei, et non filii ejus in sordibus: generatio prava atque perversa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Hæccine reddis Domino, popule stulte et insipiens? numquid non ipse est pater tuus, qui possedit te, et fecit, et creavit te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Memento dierum antiquorum, cogita generationes singulas: interroga patrem tuum, et annuntiabit tibi: majores tuos, et dicent tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quando dividebat Altissimus gentes, quando separabat filios Adam, constituit terminos populorum juxta numerum filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Pars autem Domini, populus ejus: Jacob funiculus hæreditatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Invenit eum in terra deserta, in loco horroris, et vastæ solitudinis: circumduxit eum, et docuit: et custodivit quasi pupillam oculi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Sicut aquila provocans ad volandum pullos suos, et super eos volitans, expandit alas suas, et assumpsit eum, atque portavit in humeris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Dominus solus dux ejus fuit, et non erat cum eo deus alienus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'constituit eum super excelsam terram, ut comederet fructus agrorum: ut sugeret mel de petra, oleumque de saxo durissimo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'butyrum de armento, et lac de ovibus cum adipe agnorum, et arietum filiorum Basan: et hircos cum medulla tritici, et sanguinem uvæ biberet meracissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Incrassatus est dilectus, et recalcitravit: incrassatus, impinguatus, dilatatus, dereliquit Deum factorem suum, et recessit a Deo salutari suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Provocaverunt eum in diis alienis, et in abominationibus ad iracundiam concitaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Immolaverunt dæmoniis et non Deo, diis quos ignorabant: novi recentesque venerunt, quos non coluerunt patres eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Deum qui te genuit dereliquisti, et oblitus es Domini creatoris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Vidit Dominus, et ad iracundiam concitatus est: quia provocaverunt eum filii sui et filiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Et ait: Abscondam faciem meam ab eis, et considerabo novissima eorum: generatio enim perversa est, et infideles filii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ipsi me provocaverunt in eo qui non erat Deus, et irritaverunt in vanitatibus suis: et ego provocabo eos in eo qui non est populus, et in gente stulta irritabo illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Ignis succensus est in furore meo, et ardebit usque ad inferni novissima: devorabitque terram cum germine suo, et montium fundamenta comburet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Congregabo super eos mala, et sagittas meas complebo in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Consumentur fame, et devorabunt eos aves morsu amarissimo: dentes bestiarum immittam in eos, cum furore trahentium super terram, atque serpentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Foris vastabit eos gladius, et intus pavor, juvenem simul ac virginem, lactentem cum homine sene.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Dixi: Ubinam sunt? cessare faciam ex hominibus memoriam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Sed propter iram inimicorum distuli: ne forte superbirent hostes eorum, et dicerent: Manus nostra excelsa, et non Dominus, fecit hæc omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Gens absque consilio est, et sine prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Utinam saperent, et intelligerent, ac novissima providerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Quomodo persequatur unus mille, et duo fugent decem millia? nonne ideo, quia Deus suus vendidit eos, et Dominus conclusit illos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Non enim est Deus noster ut dii eorum: et inimici nostri sunt judices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'De vinea Sodomorum, vinea eorum, et de suburbanis Gomorrhæ: uva eorum, uva fellis, et botri amarissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Fel draconum vinum eorum, et venenum aspidum insanabile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Nonne hæc condita sunt apud me, et signata in thesauris meis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mea est ultio, et ego retribuam in tempore, ut labatur pes eorum: juxta est dies perditionis, et adesse festinant tempora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Judicabit Dominus populum suum, et in servis suis miserebitur: videbit quod infirmata sit manus, et clausi quoque defecerunt, residuique consumpti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Et dicet: Ubi sunt dii eorum, in quibus habebant fiduciam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'de quorum victimis comedebant adipes, et bibebant vinum libaminum: surgant, et opitulentur vobis, et in necessitate vos protegant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Videte quod ego sim solus, et non sit alius deus præter me: ego occidam, et ego vivere faciam: percutiam, et ego sanabo, et non est qui de manu mea possit eruere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Levabo ad cælum manum meam, et dicam: Vivo ego in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Si acuero ut fulgur gladium meum, et arripuerit judicium manus mea: reddam ultionem hostibus meis, et his qui oderunt me retribuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Inebriabo sagittas meas sanguine, et gladius meus devorabit carnes; de cruore occisorum et de captivitate, nudati inimicorum capitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Laudate, gentes, populum ejus, quia sanguinem servorum suorum ulciscetur: et vindictam retribuet in hostes eorum, et propitius erit terræ populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Venit ergo Moyses, et locutus est omnia verba cantici hujus in auribus populi, ipse et Josue filius Nun.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Complevitque omnes sermones istos, loquens ad universum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'et dixit ad eos: Ponite corda vestra in omnia verba, quæ ego testificor vobis hodie: ut mandetis ea filiis vestris custodire et facere, et implere universa quæ scripta sunt legis hujus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'quia non incassum præcepta sunt vobis, sed ut singuli in eis viverent: quæ facientes longo perseveretis tempore in terra, ad quam, Jordane transmisso, ingredimini possidendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Locutusque est Dominus ad Moysen in eadem die, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Ascende in montem istum Abarim, id est, transitum, in montem Nebo, qui est in terra Moab contra Jericho: et vide terram Chanaan, quam ego tradam filiis Israël obtinendam, et morere in monte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Quem conscendens jungeris populis tuis, sicut mortuus est Aaron frater tuus in monte Hor, et appositus populis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'quia prævaricati estis contra me in medio filiorum Israël ad aquas contradictionis in Cades deserti Sin: et non sanctificastis me inter filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'E contra videbis terram, et non ingredieris in eam, quam ego dabo filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Hæc est benedictio, qua benedixit Moyses, homo Dei, filiis Israël ante mortem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Et ait: Dominus de Sinai venit, et de Seir ortus est nobis: apparuit de monte Pharan, et cum eo sanctorum millia. In dextera ejus ignea lex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Dilexit populos, omnes sancti in manu illius sunt: et qui appropinquant pedibus ejus, accipient de doctrina illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Legem præcepit nobis Moyses, hæreditatem multitudinis Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Erit apud rectissimum rex, congregatis principibus populi cum tribubus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Vivat Ruben, et non moriatur, et sit parvus in numero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Hæc est Judæ benedictio: Audi, Domine, vocem Judæ, et ad populum suum introduc eum: manus ejus pugnabunt pro eo, et adjutor illius contra adversarios ejus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Levi quoque ait: Perfectio tua, et doctrina tua viro sancto tuo, quem probasti in tentatione, et judicasti ad aquas contradictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Qui dixit patri suo et matri suæ: Nescio vos: et fratribus suis: Ignoro vos: et nescierunt filios suos. Hi custodierunt eloquium tuum, et pactum tuum servaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Judicia tua, o Jacob, et legem tuam, o Israël: ponent thymiama in furore tuo, et holocaustum super altare tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Benedic, Domine, fortitudini ejus: et opera manuum illius suscipe. Percute dorsa inimicorum ejus: et qui oderunt eum, non consurgant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Et Benjamin ait: Amantissimus Domini habitabit confidenter in eo: quasi in thalamo tota die morabitur, et inter humeros illius requiescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Joseph quoque ait: De benedictione Domini terra ejus, de pomis cæli, et rore, atque abysso subjacente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'De pomis fructuum solis ac lunæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'de vertice antiquorum montium, de pomis collium æternorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'et de frugibus terræ, et de plenitudine ejus. Benedictio illius qui apparuit in rubo, veniat super caput Joseph, et super verticem nazaræi inter fratres suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Quasi primogeniti tauri pulchritudo ejus, cornua rhinocerotis cornua illius: in ipsis ventilabit gentes usque ad terminos terræ. Hæ sunt multitudines Ephraim: et hæc millia Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Et Zabulon ait: Lætare, Zabulon, in exitu tuo, et Issachar in tabernaculis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Populos vocabunt ad montem: ibi immolabunt victimas justitiæ. Qui inundationem maris quasi lac sugent, et thesauros absconditos arenarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Et Gad ait: Benedictus in latitudine Gad: quasi leo requievit, cepitque brachium et verticem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Et vidit principatum suum, quod in parte sua doctor esset repositus: qui fuit cum principibus populi, et fecit justitias Domini, et judicium suum cum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Dan quoque ait: Dan catulus leonis, fluet largiter de Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Et Nephthali dixit: Nephthali abundantia perfruetur, et plenus erit benedictionibus Domini: mare et meridiem possidebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Aser quoque ait: Benedictus in filiis Aser, sit placens fratribus suis, et tingat in oleo pedem suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'ferrum et æs calceamentum ejus. Sicut dies juventutis tuæ, ita et senectus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Non est deus alius ut Deus rectissimi, ascensor cæli, auxiliator tuus. Magnificentia ejus discurrunt nubes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'habitaculum ejus sursum, et subter brachia sempiterna ejiciet a facie tua inimicum, dicetque: Conterere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Habitabit Israël confidenter, et solus. Oculus Jacob in terra frumenti et vini, cælique caligabunt rore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Beatus es tu, Israël: quis similis tui, popule, qui salvaris in Domino? Scutum auxilii tui, et gladius gloriæ tuæ: negabunt te inimici tui, et tu eorum colla calcabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Ascendit ergo Moyses de campestribus Moab super montem Nebo, in verticem Phasga contra Jericho: ostenditque ei Dominus omnem terram Galaad usque Dan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'et universum Nephthali, terramque Ephraim et Manasse, et omnem terram Juda usque ad mare novissimum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'et australem partem, et latitudinem campi Jericho civitatis palmarum usque Segor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Dixitque Dominus ad eum: Hæc est terra, pro qua juravi Abraham, Isaac, et Jacob, dicens: Semini tuo dabo eam. Vidisti eam oculis tuis, et non transibis ad illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Mortuusque est ibi Moyses servus Domini, in terra Moab, jubente Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'et sepelivit eum in valle terræ Moab contra Phogor: et non cognovit homo sepulchrum ejus usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Moyses centum et viginti annorum erat quando mortuus est: non caligavit oculus ejus, nec dentes illius moti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Fleveruntque eum filii Israël in campestribus Moab triginta diebus: et completi sunt dies planctus lugentium Moysen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Josue vero filius Nun repletus est spiritu sapientiæ, quia Moyses posuit super eum manus suas. Et obedierunt ei filii Israël, feceruntque sicut præcepit Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Et non surrexit ultra propheta in Israël sicut Moyses, quem nosset Dominus facie ad faciem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'in omnibus signis atque portentis, quæ misit per eum, ut faceret in terra \'gypti Pharaoni, et omnibus servis ejus, universæque terræ illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'et cunctam manum robustam, magnaque mirabilia, quæ fecit Moyses coram universo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Et factum est post mortem Moysi servi Domini, ut loqueretur Dominus ad Josue filium Nun, ministrum Moysi, et diceret ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Moyses servus meus mortuus est: surge, et transi Jordanem istum tu, et omnis populus tecum, in terram quam ego dabo filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Omnem locum, quem calcaverit vestigium pedis vestri, vobis tradam, sicut locutus sum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'A deserto et Libano usque ad fluvium magnum Euphraten, omnis terra Hethæorum usque ad mare magnum contra solis occasum erit terminus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nullus poterit vobis resistere cunctis diebus vitæ tuæ: sicut fui cum Moyse, ita ero tecum: non dimittam, nec derelinquam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Confortare, et esto robustus: tu enim sorte divides populo huic terram, pro qua juravi patribus suis, ut traderem eam illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Confortare igitur, et esto robustus valde, ut custodias, et facias omnem legem, quam præcepit tibi Moyses servus meus: ne declines ab ea ad dexteram vel ad sinistram, ut intelligas cuncta quæ agis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Non recedat volumen legis hujus ab ore tuo: sed meditaberis in eo diebus ac noctibus, ut custodias et facias omnia quæ scripta sunt in eo: tunc diriges viam tuam, et intelliges eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Ecce præcipio tibi: confortare, et esto robustus. Noli metuere, et noli timere: quoniam tecum est Dominus Deus tuus in omnibus ad quæcumque perrexeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Præcepitque Josue principibus populi, dicens: Transite per medium castrorum, et imperate populo, ac dicite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Præparate vobis cibaria: quoniam post diem tertium transibitis Jordanem, et intrabitis ad possidendam terram quam Dominus Deus vester daturus est vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rubenitis quoque et Gaditis, et dimidiæ tribui Manasse, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Mementote sermonis, quem præcepit vobis Moyses famulus Domini, dicens: Dominus Deus vester dedit vobis requiem, et omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Uxores vestræ, et filii, ac jumenta manebunt in terra, quam tradidit vobis Moyses trans Jordanem: vos autem transite armati ante fratres vestros, omnes fortes manu, et pugnate pro eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'donec det Dominus requiem fratribus vestris sicut et vobis dedit, et possideant ipsi quoque terram quam Dominus Deus vester daturus est eis: et sic revertimini in terram possessionis vestræ, et habitabitis in ea, quam vobis dedit Moyses famulus Domini trans Jordanem contra solis ortum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Responderuntque ad Josue, atque dixerunt: Omnia quæ præcepisti nobis, faciemus: et quocumque miseris, ibimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Sicut obedivimus in cunctis Moysi, ita obediemus et tibi: tantum sit Dominus Deus tuus tecum, sicut fuit cum Moyse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Qui contradixerit ori tuo, et non obedierit cunctis sermonibus, quos præceperis ei, moriatur. Tu tantum confortare, et viriliter age.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Misit igitur Josue filius Nun de Setim duos viros exploratores in abscondito: et dixit eis: Ite, et considerate terram, urbemque Jericho. Qui pergentes ingressi sunt domum mulieris meretricis, nomine Rahab, et quieverunt apud eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Nuntiatumque est regi Jericho, et dictum: Ecce viri ingressi sunt huc per noctem de filiis Israël, ut explorarent terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Misitque rex Jericho ad Rahab, dicens: Educ viros, qui venerunt ad te, et ingressi sunt domum tuam: exploratores quippe sunt, et omnem terram considerare venerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Tollensque mulier viros, abscondit, et ait: Fateor, venerunt ad me, sed nesciebam unde essent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'cumque porta clauderetur in tenebris, et illi pariter exierunt; nescio quo abierunt: persequimini cito, et comprehendetis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Ipsa autem fecit ascendere viros in solarium domus suæ, operuitque eos stipula lini, quæ ibi erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Hi autem, qui missi fuerant, secuti sunt eos per viam, quæ ducit ad vadum Jordanis: illisque egressis statim porta clausa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Necdum obdormierant qui latebant, et ecce mulier ascendit ad eos, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Novi quod Dominus tradiderit vobis terram: etenim irruit in nos terror vester, et elanguerunt omnes habitatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Audivimus quod siccaverit Dominus aquas maris Rubri ad vestrum introitum, quando egressi estis ex \'gypto: et quæ feceritis duobus Amorrhæorum regibus, qui erant trans Jordanem, Sehon et Og, quos interfecistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Et hæc audientes pertimuimus, et elanguit cor nostrum, nec remansit in nobis spiritus ad introitum vestrum: Dominus enim Deus vester ipse est Deus in cælo sursum et in terra deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Nunc ergo jurate mihi per Dominum, ut quomodo ego misericordiam feci vobiscum, ita et vos faciatis cum domo patris mei: detisque mihi verum signum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'ut salvetis patrem meum et matrem, et fratres ac sorores meas, et omnia quæ illorum sunt, et eruatis animas nostras a morte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Qui responderunt ei: Anima nostra sit pro vobis in mortem, si tamen non prodideris nos: cumque tradiderit nobis Dominus terram, faciemus in te misericordiam et veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Demisit ergo eos per funem de fenestra: domus enim ejus hærebat muro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Dixitque ad eos: Ad montana conscendite, ne forte occurrant vobis revertentes: ibique latitate tribus diebus, donec redeant, et sic ibitis per viam vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Qui dixerunt ad eam: Innoxii erimus a juramento hoc, quo adjurasti nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'si ingredientibus nobis terram, signum fuerit funiculus iste coccineus, et ligaveris eum in fenestra, per quam demisisti nos: et patrem tuum ac matrem, fratresque et omnem cognationem tuam congregaveris in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Qui ostium domus tuæ egressus fuerit, sanguis ipsius erit in caput ejus, et nos erimus alieni. Cunctorum autem sanguis, qui tecum in domo fuerint, redundabit in caput nostrum, si eos aliquis tetigerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Quod si nos prodere volueris, et sermonem istum proferre in medium, erimus mundi ab hoc juramento, quo adjurasti nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Et illa respondit: Sicut locuti estis, ita fiat: dimittensque eos ut pergerent, appendit funiculum coccineum in fenestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Illi vero ambulantes pervenerunt ad montana, et manserunt ibi tres dies, donec reverterentur qui fuerant persecuti: quærentes enim per omnem viam, non repererunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Quibus urbem ingressis, reversi sunt, et descenderunt exploratores de monte: et, transmisso Jordane, venerunt ad Josue filium Nun, narraveruntque ei omnia quæ acciderant sibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'atque dixerunt: Tradidit Dominus omnem terram hanc in manus nostras, et timore prostrati sunt cuncti habitatores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Igitur Josue de nocte consurgens movit castra: egredientesque de Setim, venerunt ad Jordanem ipse et omnes filii Israël, et morati sunt ibi tres dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Quibus evolutis transierunt præcones per castrorum medium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'et clamare cœperunt: Quando videritis arcam fœderis Domini Dei vestri, et sacerdotes stirpis Leviticæ portantes eam, vos quoque consurgite, et sequimini præcedentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'sitque inter vos et arcam spatium cubitorum duum millium: ut procul videre possitis, et nosse per quam viam ingrediamini: quia prius non ambulastis per eam: et cavete ne appropinquetis ad arcam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Dixitque Josue ad populum: Sanctificamini: cras enim faciet Dominus inter vos mirabilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Et ait ad sacerdotes: Tollite arcam fœderis, et præcedite populum. Qui jussa complentes, tulerunt, et ambulaverunt ante eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Dixitque Dominus ad Josue: Hodie incipiam exaltare te coram omni Israël: ut sciant quod sicut cum Moyse fui, ita et tecum sim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Tu autem præcipe sacerdotibus, qui portant arcam fœderis, et dic eis: Cum ingressi fueritis partem aquæ Jordanis, state in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Dixitque Josue ad filios Israël: Accedite huc, et audite verbum Domini Dei vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Et rursum: In hoc, inquit, scietis quod Dominus Deus vivens in medio vestri est, et disperdet in conspectu vestro Chananæum et Hethæum, Hevæum et Pherezæum, Gergesæum quoque et Jebusæum, et Amorrhæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Ecce arca fœderis Domini omnis terræ antecedet vos per Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Parate duodecim viros de tribubus Israël, singulos per singulas tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Et cum posuerint vestigia pedum suorum sacerdotes qui portant arcam Domini Dei universæ terræ in aquis Jordanis, aquæ quæ inferiores sunt, decurrent atque deficient: quæ autem desuper veniunt, in una mole consistent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Igitur egressus est populus de tabernaculis suis, ut transiret Jordanem: et sacerdotes, qui portabant arcam fœderis, pergebant ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Ingressisque eis Jordanem, et pedibus eorum in parte aquæ tinctis (Jordanis autem ripas alvei sui tempore messis impleverat),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'steterunt aquæ descendentes in loco uno, et ad instar montis intumescentes apparebant procul, ab urbe quæ vocatur Adom usque ad locum Sarthan: quæ autem inferiores erant, in mare Solitudinis (quod nunc vocatur Mortuum) descenderunt, usquequo omnino deficerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Populus autem incedebat contra Jericho: et sacerdotes qui portabant arcam fœderis Domini, stabant super siccam humum in medio Jordanis accincti, omnisque populus per arentem alveum transibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Quibus transgressis, dixit Dominus ad Josue:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Elige duodecim viros singulos per singulas tribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'et præcipe eis ut tollant de medio Jordanis alveo, ubi steterunt pedes sacerdotum, duodecim durissimos lapides, quos ponetis in loco castrorum, ubi fixeritis hac nocte tentoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Vocavitque Josue duodecim viros, quos elegerat de filiis Israël, singulos de singulis tribubus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'et ait ad eos: Ite ante arcam Domini Dei vestri ad Jordanis medium, et portate inde singuli singulos lapides in humeris vestris, juxta numerum filiorum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'ut sit signum inter vos: et quando interrogaverint vos filii vestri cras, dicentes: Quid sibi volunt isti lapides?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'respondebitis eis: Defecerunt aquæ Jordanis ante arcam fœderis Domini, cum transiret eum: idcirco positi sunt lapides isti in monimentum filiorum Israël usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Fecerunt ergo filii Israël sicut præcepit eis Josue, portantes de medio Jordanis alveo duodecim lapides, ut Dominus ei imperarat, juxta numerum filiorum Israël, usque ad locum in quo castrametati sunt, ibique posuerunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Alios quoque duodecim lapides posuit Josue in medio Jordanis alveo, ubi steterunt sacerdotes qui portabant arcam fœderis: et sunt ibi usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Sacerdotes autem qui portabant arcam, stabant in Jordanis medio, donec omnia complerentur, quæ Josue, ut loqueretur ad populum, præceperat Dominus, et dixerat ei Moyses. Festinavitque populus, et transiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Cumque transissent omnes, transivit et arca Domini, sacerdotesque pergebant ante populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Filii quoque Ruben, et Gad, et dimidia tribus Manasse, armati præcedebant filios Israël, sicut eis præceperat Moyses:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'et quadraginta pugnatorum millia per turmas, et cuneos, incedebant per plana atque campestria urbis Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'In die illo magnificavit Dominus Josue coram omni Israël, ut timerent eum, sicut timuerant Moysen, dum adviveret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Dixitque ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Præcipe sacerdotibus, qui portant arcam fœderis, ut ascendant de Jordane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Qui præcepit eis, dicens: Ascendite de Jordane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Cumque ascendissent portantes arcam fœderis Domini, et siccam humum calcare cœpissent, reversæ sunt aquæ in alveum suum, et fluebant sicut ante consueverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Populus autem ascendit de Jordane decimo die mensis primi, et castrametati sunt in Galgalis contra orientalem plagam urbis Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Duodecim quoque lapides, quos de Jordanis alveo sumpserant, posuit Josue in Galgalis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'et dixit ad filios Israël: Quando interrogaverint filii vestri cras patres suos, et dixerint eis: Quid sibi volunt lapides isti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'docebitis eos, atque dicetis: Per arentem alveum transivit Israël Jordanem istum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'siccante Domino Deo vestro aquas ejus in conspectu vestro, donec transiretis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'sicut fecerat prius in mari Rubro, quod siccavit donec transiremus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 25, 'ut discant omnes terrarum populi fortissimam Domini manum, ut et vos timeatis Dominum Deum vestrum omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Postquam ergo audierunt omnes reges Amorrhæorum, qui habitabant trans Jordanem ad occidentalem plagam, et cuncti reges Chanaan, qui propinqua possidebant magni maris loca, quod siccasset Dominus fluenta Jordanis coram filiis Israël donec transirent, dissolutum est cor eorum, et non remansit in eis spiritus, timentium introitum filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Eo tempore ait Dominus ad Josue: Fac tibi cultros lapideos, et circumcide secundo filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Fecit quod jusserat Dominus, et circumcidit filios Israël in colle præputiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Hæc autem causa est secundæ circumcisionis: omnis populus, qui egressus est de \'gypto generis masculini, universi bellatores viri, mortui sunt in deserto per longissimos viæ circuitus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'qui omnes circumcisi erant. Populus autem qui natus est in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'per quadraginta annos itineris latissimæ solitudinis incircumcisus fuit: donec consumerentur qui non audierant vocem Domini, et quibus ante juraverat ut non ostenderet eis terram lacte et melle manantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Horum filii in locum successerunt patrum, et circumcisi sunt a Josue: quia sicut nati fuerant, in præputio erant, nec eos in via aliquis circumciderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Postquam autem omnes circumcisi sunt, manserunt in eodem castrorum loco, donec sanarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Dixitque Dominus ad Josue: Hodie abstuli opprobrium \'gypti a vobis. Vocatumque est nomen loci illius Galgala, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Manseruntque filii Israël in Galgalis, et fecerunt Phase quartadecima die mensis ad vesperum in campestribus Jericho:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'et comederunt de frugibus terræ die altero, azymos panes, et polentam ejusdem anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Defecitque manna postquam comederunt de frugibus terræ, nec usi sunt ultra cibo illo filii Israël, sed comederunt de frugibus præsentis anni terræ Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Cum autem esset Josue in agro urbis Jericho, levavit oculos, et vidit virum stantem contra se, evaginatum tenentem gladium: perrexitque ad eum, et ait: Noster es, an adversariorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Qui respondit: Nequaquam: sed sum princeps exercitus Domini, et nunc venio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Cecidit Josue pronus in terram, et adorans ait: Quid dominus meus loquitur ad servum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 16, 'Solve, inquit, calceamentum tuum de pedibus tuis: locus enim, in quo stas, sanctus est. Fecitque Josue ut sibi fuerat imperatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho autem clausa erat atque munita, timore filiorum Israël, et nullus egredi audebat aut ingredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Dixitque Dominus ad Josue: Ecce dedi in manu tua Jericho, et regem ejus, omnesque fortes viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Circuite urbem cuncti bellatores semel per diem: sic facietis sex diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Septimo autem die, sacerdotes tollant septem buccinas, quarum usus est in jubilæo, et præcedant arcam fœderis: septiesque circuibitis civitatem, et sacerdotes clangent buccinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Cumque insonuerit vox tubæ longior atque concisior, et in auribus vestris increpuerit, conclamabit omnis populus vociferatione maxima, et muri funditus corruent civitatis, ingredienturque singuli per locum contra quem steterint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Vocavit ergo Josue filius Nun sacerdotes, et dixit ad eos: Tollite arcam fœderis: et septem alii sacerdotes tollant septem jubilæorum buccinas, et incedant ante arcam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Ad populum quoque ait: Ite, et circuite civitatem, armati, præcedentes arcam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Cumque Josue verba finisset, et septem sacerdotes septem buccinis clangerent ante arcam fœderis Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'omnisque præcederet armatus exercitus, reliquum vulgus arcam sequebatur, ac buccinis omnia concrepabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Præceperat autem Josue populo, dicens: Non clamabitis, nec audietur vox vestra, neque ullus sermo ex ore vestro egredietur, donec veniat dies in quo dicam vobis: Clamate, et vociferamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Circuivit ergo arca Domini civitatem semel per diem, et reversa in castra mansit ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Igitur Josue de nocte consurgente, tulerunt sacerdotes arcam Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'et septem ex eis septem buccinas, quarum in jubilæo usus est: præcedebantque arcam Domini ambulantes atque clangentes: et armatus populus ibat ante eos, vulgus autem reliquum sequebatur arcam, et buccinis personabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Circuieruntque civitatem secundo die semel, et reversi sunt in castra. Sic fecerunt sex diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Dies autem septimo, diluculo consurgentes, circuierunt urbem, sicut dispositum erat, septies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Cumque septimo circuitu clangerent buccinis sacerdotes, dixit Josue ad omnem Israël: Vociferamini: tradidit enim vobis Dominus civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Sitque civitas hæc anathema, et omnia quæ in ea sunt, Domino: sola Rahab meretrix vivat, cum universis qui cum ea in domo sunt: abscondit enim nuntios quos direximus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Vos autem cavete ne de his, quæ præcepta sunt, quippiam contingatis, et sitis prævaricationis rei, et omnia castra Israël sub peccato sint atque turbentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Quidquid autem auri et argenti fuerit, et vasorum æneorum ac ferri, Domino consecretur, repositum in thesauris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Igitur omni populo vociferante, et clangentibus tubis, postquam in aures multitudinis vox sonitusque increpuit, muri illico corruerunt: et ascendit unusquisque per locum qui contra se erat: ceperuntque civitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'et interfecerunt omnia quæ erant in ea, a viro usque ad mulierem, ab infante usque ad senem. Boves quoque et oves et asinos in ore gladii percusserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Duobus autem viris, qui exploratores missi fuerant, dixit Josue: Ingredimini domum mulieris meretricis, et producite eam, et omnia quæ illius sunt, sicut illi juramento firmastis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Ingressique juvenes eduxerunt Rahab, et parentes ejus, fratres quoque, et cunctam supellectilem ac cognationem illius, et extra castra Israël manere fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Urbem autem, et omnia quæ erant in ea, succenderunt, absque auro et argento, et vasis æneis, ac ferro, quæ in ærarium Domini consecrarunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Rahab vero meretricem, et domum patris ejus, et omnia quæ habebat, fecit Josue vivere, et habitaverunt in medio Israël, usque in præsentem diem: eo quod absconderit nuntios, quos miserat ut explorarent Jericho. In tempore illo, imprecatus est Josue, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Maledictus vir coram Domino, qui suscitaverit et ædificaverit civitatem Jericho. In primogenito suo fundamenta illius jaciat, et in novissimo liberorum ponat portas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Fuit ergo Dominus cum Josue, et nomen ejus vulgatum est in omni terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Filii autem Israël prævaricati sunt mandatum, et usurpaverunt de anathemate. Nam Achan filius Charmi filii Zabdi filii Zare de tribu Juda tulit aliquid de anathemate: iratusque est Dominus contra filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Cumque mitteret Josue de Jericho viros contra Hai, quæ est juxta Bethaven, ad orientalem plagam oppidi Bethel, dixit eis: Ascendite, et explorate terram. Qui præcepta complentes exploraverunt Hai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Et reversi dixerunt ei: Non ascendat omnis populus, sed duo vel tria millia virorum pergant, et deleant civitatem: quare omnis populus frustra vexabitur contra hostes paucissimos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Ascenderunt ergo tria millia pugnatorum. Qui statim terga vertentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'percussi sunt a viris urbis Hai, et corruerunt ex eis triginta sex homines: persecutique sunt eos adversarii de porta usque ad Sabarim, et ceciderunt per prona fugientes: pertimuitque cor populi, et instar aquæ liquefactum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Josue vero scidit vestimenta sua, et pronus cecidit in terram coram arca Domini usque ad vesperam, tam ipse quam omnes senes Israël: miseruntque pulverem super capita sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'et dixit Josue: Heu Domine Deus, quid voluisti traducere populum istum Jordanem fluvium, ut traderes nos in manus Amorrhæi, et perderes? utinam ut cœpimus, mansissemus trans Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Mi Domine Deus, quid dicam, videns Israëlem hostibus suis terga vertentem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Audient Chananæi, et omnes habitatores terræ, et pariter conglobati circumdabunt nos, atque delebunt nomen nostrum de terra: et quid facies magno nomini tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Dixitque Dominus ad Josue: Surge: cur jaces pronus in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Peccavit Israël, et prævaricatus est pactum meum: tuleruntque de anathemate, et furati sunt atque mentiti, et absconderunt inter vasa sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Nec poterit Israël stare ante hostes suos, eosque fugiet: quia pollutus est anathemate. Non ero ultra vobiscum, donec conteratis eum qui hujus sceleris reus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Surge, sanctifica populum, et dic eis: Sanctificamini in crastinum: hæc enim dicit Dominus Deus Israël: Anathema in medio tui est, Israël: non poteris stare coram hostibus tuis, donec deleatur ex te qui hoc contaminatus est scelere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Accedetisque mane singuli per tribus vestras: et quamcumque tribum sors invenerit, accedet per cognationes suas, et cognatio per domos, domusque per viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Et quicumque ille in hoc facinore fuerit deprehensus, comburetur igni cum omni substantia sua: quoniam prævaricatus est pactum Domini, et fecit nefas in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Surgens itaque Josue mane, applicuit Israël per tribus suas, et inventa est tribus Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Quæ cum juxta familias suas esset oblata, inventa est familia Zare. Illam quoque per domos offerens, reperit Zabdi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'cujus domum in singulos dividens viros, invenit Achan filium Charmi filii Zabdi filii Zare de tribu Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Et ait Josue ad Achan: Fili mi, da gloriam Domino Deo Israël, et confitere, atque indica mihi quid feceris, ne abscondas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Responditque Achan Josue, et dixit ei: Vere ego peccavi Domino Deo Israël, et sic et sic feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Vidi enim inter spolia pallium coccineum valde bonum, et ducentos siclos argenti, regulamque auream quinquaginta siclorum: et concupiscens abstuli, et abscondi in terra contra medium tabernaculi mei, argentumque fossa humo operui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Misit ergo Josue ministros: qui currentes ad tabernaculum illius, repererunt cuncta abscondita in eodem loco, et argentum simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Auferentesque de tentorio, tulerunt ea ad Josue, et ad omnes filios Israël, projeceruntque ante Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Tollens itaque Josue Achan filium Zare, argentumque et pallium, et auream regulam, filios quoque et filias ejus, boves et asinos et oves, ipsumque tabernaculum, et cunctam supellectilem (et omnis Israël cum eo), duxerunt eos ad vallem Achor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'ubi dixit Josue: Quia turbasti nos, exturbet te Dominus in die hac. Lapidavitque eum omnis Israël: et cuncta quæ illius erant, igne consumpta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Congregaveruntque super eum acervum magnum lapidum, qui permanet usque in præsentem diem. Et aversus est furor Domini ab eis. Vocatumque est nomen loci illius, vallis Achor, usque hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Dixit autem Dominus ad Josue: Ne timeas, neque formides: tolle tecum omnem multitudinem pugnatorum, et consurgens ascende in oppidum Hai. Ecce tradidi in manu tua regem ejus et populum, urbemque et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Faciesque urbi Hai, et regi ejus, sicut fecisti Jericho, et regi illius: prædam vero, et omnia animantia diripietis vobis: pone insidias urbi post eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Surrexitque Josue, et omnis exercitus bellatorum cum eo, ut ascenderent in Hai: et electa triginta millia virorum fortium misit nocte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'præcepitque eis, dicens: Ponite insidias post civitatem, nec longius recedatis: et eritis omnes parati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ego autem, et reliqua multitudo, quæ mecum est, accedemus ex adverso contra urbem. Cumque exierint contra nos, sicut ante fecimus, fugiemus, et terga vertemus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'donec persequentes ab urbe longius protrahantur: putabunt enim nos fugere sicut prius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Nobis ergo fugientibus, et illis persequentibus, consurgetis de insidiis, et vastabitis civitatem: tradetque eam Dominus Deus vester in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Cumque ceperitis, succendite eam, et sic omnia facietis, ut jussi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Dimisitque eos, et perrexerunt ad locum insidiarum, sederuntque inter Bethel et Hai, ad occidentalem plagam urbis Hai: Josue autem nocte illa in medio mansit populi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'surgensque diluculo recensuit socios, et ascendit cum senioribus in fronte exercitus, vallatus auxilio pugnatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Cumque venissent et ascendissent ex adverso civitatis, steterunt ad septentrionalem urbis plagam, inter quam et eos erat vallis media.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Quinque autem millia viros elegerat, et posuerat in insidiis inter Bethel et Hai ex occidentali parte ejusdem civitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'omnis vero reliquus exercitus ad aquilonem aciem dirigebat, ita ut novissimi illius multitudinis occidentalem plagam urbis attingerent. Abiit ergo Josue nocte illa, et stetit in vallis medio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Quod cum vidisset rex Hai, festinavit mane, et egressus est cum omni exercitu civitatis, direxitque aciem contra desertum, ignorans quod post tergum laterent insidiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josue vero et omnis Israël cesserunt loco, simulantes metum, et fugientes per solitudinis viam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'At illi vociferantes pariter, et se mutuo cohortantes, persecuti sunt eos. Cumque recessissent a civitate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'et ne unus quidem in urbe Hai et Bethel remansisset qui non persequeretur Israël (sicut eruperant aperta oppida relinquentes),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'dixit Dominus ad Josue: Leva clypeum, qui in manu tua est, contra urbem Hai, quoniam tibi tradam eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Cumque elevasset clypeum ex adverso civitatis, insidiæ, quæ latebant, surrexerunt confestim: et pergentes ad civitatem, ceperunt, et succenderunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Viri autem civitatis, qui persequebantur Josue, respicientes et videntes fumum urbis ad cælum usque conscendere, non potuerunt ultra huc illucque diffugere: præsertim cum hi qui simulaverant fugam, et tendebant ad solitudinem, contra persequentes fortissime restitissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Vidensque Josue et omnis Israël quod capta esset civitas, et fumus urbis ascenderet, reversus percussit viros Hai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Siquidem et illi qui ceperant et succenderant civitatem, egressi ex urbe contra suos, medios hostium ferire cœperunt. Cum ergo ex utraque parte adversarii cæderentur, ita ut nullus de tanta multitudine salvaretur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'regem quoque urbis Hai apprehenderunt viventem, et obtulerunt Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Igitur omnibus interfectis, qui Israëlem ad deserta tendentem fuerant persecuti, et in eodem loco gladio corruentibus, reversi filii Israël percusserunt civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Erant autem qui in eodem die conciderant a viro usque ad mulierem, duodecim millia hominum, omnes urbis Hai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josue vero non contraxit manum, quam in sublime porrexerat, tenens clypeum donec interficerentur omnes habitatores Hai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Jumenta autem et prædam civitatis diviserunt sibi filii Israël, sicut præceperat Dominus Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Qui succendit urbem, et fecit eam tumulum sempiternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'regem quoque ejus suspendit in patibulo usque ad vesperam et solis occasum. Præcepitque Josue, et deposuerunt cadaver ejus de cruce: projeceruntque in ipso introitu civitatis, congesto super eum magno acervo lapidum, qui permanet usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tunc ædificavit Josue altare Domino Deo Israël in monte Hebal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'sicut præceperat Moyses famulus Domini filiis Israël, et scriptum est in volumine legis Moysi: altare vero de lapidibus impolitis, quos ferrum non tetigit: et obtulit super eo holocausta Domino, immolavitque pacificas victimas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Et scripsit super lapides Deuteronomium legis Moysi, quod ille digesserat coram filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Omnis autem populus, et majores natu, ducesque ac judices, stabant ex utraque parte arcæ, in conspectu sacerdotum qui portabant arcam fœderis Domini, ut advena, ita et indigena. Media pars eorum juxta montem Garizim, et media juxta montem Hebal, sicut præceperat Moyses famulus Domini. Et primum quidem benedixit populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Post hæc legit omnia verba benedictionis et maledictionis, et cuncta quæ scripta erant in legis volumine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nihil ex his quæ Moyses jusserat, reliquit intactum, sed universa replicavit coram omni multitudine Israël, mulieribus ac parvulis, et advenis qui inter eos morabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Quibus auditis, cuncti reges trans Jordanem, qui versabantur in montanis et campestribus, in maritimis ac littore magni maris, hi quoque qui habitabant juxta Libanum, Hethæus et Amorrhæus, Chananæus, Pherezæus, et Hevæus, et Jebusæus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'congregati sunt pariter, ut pugnarent contra Josue et Israël uno animo, eademque sententia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'At hi qui habitabant in Gabaon, audientes cuncta quæ fecerat Josue Jericho, et Hai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'et callide cogitantes, tulerunt sibi cibaria, saccos veteres asinis imponentes, et utres vinarios scissos atque consutos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'calceamentaque perantiqua quæ ad indicium vetustatis pittaciis consuta erant, induti veteribus vestimentis: panes quoque, quos portabant ob viaticum, duri erant, et in frustra comminuti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'perrexeruntque ad Josue, qui tunc morabatur in castris Galgalæ, et dixerunt ei, atque simul omni Israëli: De terra longinqua venimus, pacem vobiscum facere cupientes. Responderuntque viri Israël ad eos, atque dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Ne forte in terra, quæ nobis sorte debetur, habitetis, et non possimus fœdus inire vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'At illi ad Josue: Servi, inquiunt, tui sumus. Quibus Josue ait: Quinam estis vos? et unde venistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Responderunt: De terra longinqua valde venerunt servi tui in nomine Domini Dei tui. Audivimus enim famam potentiæ ejus, cuncta quæ fecit in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'et duobus regibus Amorrhæorum qui fuerunt trans Jordanem, Sehon regi Hesebon, et Og regi Basan, qui erat in Astaroth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'dixeruntque nobis seniores, et omnes habitatores terræ nostræ: Tollite in manibus cibaria ob longissimam viam, et occurrite eis, et dicite: Servi vestri sumus: fœdus inite nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'En panes quando egressi sumus de domibus nostris, ut veniremus ad vos, calidos sumpsimus; nunc sicci facti sunt, et vetustate nimia comminuti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Utres vini novos implevimus; nunc rupti sunt et soluti. Vestes et calceamenta quibus induimur, et quæ habemus in pedibus, ob longitudinem longioris viæ trita sunt, et pene consumpta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Susceperunt igitur de cibariis eorum, et os Domini non interrogaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Fecitque Josue cum eis pacem, et inito fœdere pollicitus est quod non occiderentur: principes quoque multitudinis juraverunt eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Post dies autem tres initi fœderis, audierunt quod in vicino habitarent, et inter eos futuri essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Moveruntque castra filii Israël, et venerunt in civitates eorum die tertio, quarum hæc vocabula sunt: Gabaon, et Caphira, et Beroth, et Cariathiarim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Et non percusserunt eos, eo quod jurassent eis principes multitudinis in nomine Domini Dei Israël. Murmuravit itaque omne vulgus contra principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Qui responderunt eis: Juravimus illis in nomine Domini Dei Israël, et idcirco non possumus eos contingere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Sed hoc faciemus eis: reserventur quidem ut vivant, ne contra nos ira Domini concitetur, si pejeraverimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'sed sic vivant, ut in usus universæ multitudinis ligna cædant, aquasque comportent. Quibus hæc loquentibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'vocavit Gabaonitas Josue, et dixit eis: Cur nos decipere fraude voluistis, ut diceretis: Procul valde habitamus a vobis, cum in medio nostri sitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'itaque sub maledictione eritis, et non deficiet de stirpe vestra ligna cædens, aquasque comportans in domum Dei mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Qui responderunt: Nuntiatum est nobis servis tuis, quod promisisset Dominus Deus tuus Moysi servo suo ut traderet vobis omnem terram, et disperderet cunctos habitatores ejus. Timuimus igitur valde, et providimus animabus nostris, vestro terrore compulsi, et hoc consilium inivimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Nunc autem in manu tua sumus: quod tibi bonum et rectum videtur, fac nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Fecit ergo Josue ut dixerat, et liberavit eos de manu filiorum Israël, ut non occiderentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Decrevitque in illo die eos esse in ministerio cuncti populi, et altaris Domini, cædentes ligna, et aquas comportantes, usque in præsens tempus, in loco quem Dominus elegisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Quæ cum audisset Adonisedec rex Jerusalem, quod scilicet cepisset Josue Hai, et subvertisset eam (sicut enim fecerat Jericho et regi ejus, sic fecit Hai et regi illius), et quod transfugissent Gabaonitæ ad Israël, et essent fœderati eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'timuit valde. Urbs enim magna erat Gabaon, et una civitatum regalium, et major oppido Hai, omnesque bellatores ejus fortissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Misit ergo Adonisedec rex Jerusalem ad Oham regem Hebron, et ad Pharam regem Jerimoth, ad Japhia quoque regem Lachis, et ad Dabir regem Eglon, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Ad me ascendite, et ferte præsidium, ut expugnemus Gabaon, quare transfugerit ad Josue, et ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Congregati igitur ascenderunt quinque reges Amorrhæorum: rex Jerusalem, rex Hebron, rex Jerimoth, rex Lachis, rex Eglon, simul cum exercitibus suis: et castrametati sunt circa Gabaon, oppugnantes eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Habitatores autem Gabaon urbis obsessæ miserunt ad Josue, qui tunc morabatur in castris apud Galgalam, et dixerunt ei: Ne retrahas manus tuas ab auxilio servorum tuorum: ascende cito, et libera nos, ferque præsidium: convenerunt enim adversum nos omnes reges Amorrhæorum, qui habitant in montanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Ascenditque Josue de Galgalis, et omnis exercitus bellatorum cum eo, viri fortissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Dixitque Dominus ad Josue: Ne timeas eos: in manus enim tuas tradidi illos: nullus ex eis tibi resistere poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Irruit itaque Josue super eos repente, tota nocte ascendens de Galgalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Et conturbavit eos Dominus a facie Israël: contrivitque plaga magna in Gabaon, ac persecutus est eos per viam ascensus Bethoron, et percussit usque Azeca et Maceda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Cumque fugerent filios Israël, et essent in descensu Bethoron, Dominus misit super eos lapides magnos de cælo usque ad Azeca: et mortui sunt multo plures lapidibus grandinis, quam quos gladio percusserant filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tunc locutus est Josue Domino, in die qua tradidit Amorrhæum in conspectu filiorum Israël, dixitque coram eis: Sol, contra Gabaon ne movearis, et luna contra vallem Ajalon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Steteruntque sol et luna, donec ulcisceretur se gens de inimicis suis. Nonne scriptum est hoc in libro justorum? Stetit itaque sol in medio cæli, et non festinavit occumbere spatio unius diei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Non fuit antea nec postea tam longa dies, obediente Domino voci hominis, et pugnante pro Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Reversusque est Josue cum omni Israël in castra Galgalæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Fugerant enim quinque reges et se absconderant in spelunca urbis Maceda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Nuntiatumque est Josue quod inventi essent quinque reges latentes in spelunca urbis Maceda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Qui præcepit sociis, et ait: Volvite saxa ingentia ad os speluncæ, et ponite viros industrios, qui clausos custodiant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'vos autem nolite stare, sed persequimini hostes, et extremos quosque fugientium cædite: nec dimittatis eos urbium suarum intrare præsidia, quos tradidit Dominus Deus in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Cæsis ergo adversariis plaga magna, et usque ad internecionem pene consumptis, hi qui Israël effugere potuerunt, ingressi sunt civitates munitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Reversusque est omnis exercitus ad Josue in Maceda, ubi tunc erant castra, sani et integro numero: nullusque contra filios Israël mutire ausus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Præcepitque Josue, dicens: Aperite os speluncæ, et producite ad me quinque reges, qui in ea latitant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Feceruntque ministri ut sibi fuerat imperatum: et eduxerunt ad eum quinque reges de spelunca, regem Jerusalem, regem Hebron, regem Jerimoth, regem Lachis, regem Eglon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Cumque educti essent ad eum, vocavit omnes viros Israël, et ait ad principes exercitus qui secum erant: Ite, et ponite pedes super colla regum istorum. Qui cum perrexissent, et subjectorum colla pedibus calcarent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'rursum ait ad eos: Nolite timere, nec paveatis: confortamini, et estote robusti: sic enim faciet Dominus cunctis hostibus vestris, adversum quos dimicatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Percussitque Josue, et interfecit eos, atque suspendit super quinque stipites: fueruntque suspensi usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Cumque occumberet sol, præcepit sociis ut deponerent eos de patibulis. Qui depositos projecerunt in speluncam in qua latuerant, et posuerunt super os ejus saxa ingentia, quæ permanent usque in præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Eodem quoque die, Macedam cepit Josue, et percussit eam in ore gladii, regemque illius interfecit, et omnes habitatores ejus: non dimisit in ea saltem parvas reliquias. Fecitque regi Maceda sicut fecerat regi Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Transivit autem cum omni Israël de Maceda in Lebna, et pugnabat contra eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'quam tradidit Dominus cum rege suo in manus Israël: percusseruntque urbem in ore gladii, et omnes habitatores ejus: non dimiserunt in ea ullas reliquias. Feceruntque regi Lebna sicut fecerant regi Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'De Lebna transivit in Lachis cum omni Israël: et exercitu per gyrum disposito, oppugnabat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Tradiditque Dominus Lachis in manus Israël, et cepit eam die altero, atque percussit in ore gladii, omnemque animam quæ fuerat in ea, sicut fecerat Lebna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Eo tempore ascendit Horam rex Gazer, ut auxiliaretur Lachis: quem percussit Josue cum omni populo ejus usque ad internecionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Transivitque de Lachis in Eglon, et circumdedit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'atque expugnavit eam eadem die: percussitque in ore gladii omnes animas quæ erant in ea, juxta omnia quæ fecerat Lachis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Ascendit quoque cum omni Israël de Eglon in Hebron, et pugnavit contra eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'cepit eam, et percussit in ore gladii, regem quoque ejus, et omnia oppida regionis illius, universasque animas quæ in ea fuerant commoratæ: non reliquit in ea ullas reliquias: sicut fecerat Eglon, sic fecit et Hebron, cuncta quæ in ea reperit consumens gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Inde reversus in Dabir,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'cepit eam atque vastavit: regem quoque ejus atque omnia per circuitum oppida percussit in ore gladii: non dimisit in ea ullas reliquias: sicut fecerat Hebron et Lebna et regibus earum, sic fecit Dabir et regi illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Percussit itaque Josue omnem terram montanam et meridianam atque campestrem, et Asedoth, cum regibus suis: non dimisit in ea ullas reliquias, sed omne quod spirare poterat interfecit, sicut præceperat ei Dominus Deus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'a Cadesbarne usque Gazam. Omnem terram Gosen usque Gabaon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'universosque reges, et regiones eorum uno impetu cepit atque vastavit: Dominus enim Deus Israël pugnavit pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Reversusque est cum omni Israël ad locum castrorum in Galgala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Quæ cum audisset Jabin rex Asor, misit ad Jobab regem Madon, et ad regem Semeron, atque ad regem Achsaph:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'ad reges quoque aquilonis, qui habitabant in montanis et in planitie contra meridiem Ceneroth, in campestribus quoque et in regionibus Dor juxta mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Chananæum quoque ab oriente et occidente, et Amorrhæum atque Hethæum ac Pherezæum et Jebusæum in montanis: Hevæum quoque qui habitabat ad radices Hermon in terra Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Egressique sunt omnes cum turmis suis, populus multus nimis sicut arena quæ est in littore maris, equi quoque et currus immensæ multitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Conveneruntque omnes reges isti in unum ad aquas Merom, ut pugnarent contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Dixitque Dominus ad Josue: Ne timeas eos: cras enim hac eadem hora ego tradam omnes istos vulnerandos in conspectu Israël: equos eorum subnervabis, et currus igne combures.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Venitque Josue, et omnis exercitus cum eo, adversus illos ad aquas Merom subito, et irruerunt super eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'tradiditque illos Dominus in manus Israël. Qui percusserunt eos, et persecuti sunt usque ad Sidonem magnam, et aquas Maserephoth, campumque Masphe, qui est ad orientalem illius partem. Ita percussit omnes, ut nullas dimitteret ex eis reliquias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'fecitque sicut præceperat ei Dominus: equos eorum subnervavit, currusque combussit igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Reversusque statim cepit Asor, et regem ejus percussit gladio. Asor enim antiquitus inter omnia regna hæc principatum tenebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Percussitque omnes animas quæ ibidem morabantur: non dimisit in ea ullas reliquias, sed usque ad internecionem universa vastavit, ipsamque urbem peremit incendio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Et omnes per circuitum civitates, regesque earum, cepit, percussit atque delevit, sicut præceperat ei Moyses famulus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Absque urbibus, quæ erant in collibus et in tumulis sitæ, ceteras succendit Israël: unam tantum Asor munitissimam flamma consumpsit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Omnemque prædam istarum urbium ac jumenta diviserunt sibi filii Israël, cunctis hominibus interfectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Sicut præceperat Dominus Moysi servo suo, ita præcepit Moyses Josue, et ille universa complevit: non præteriit de universis mandatis, nec unum quidem verbum quod jusserat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Cepit itaque Josue omnem terram montanam et meridianam, terramque Gosen, et planitiem, et occidentalem plagam, montemque Israël, et campestria ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'et partem montis, quæ ascendit Seir usque Baalgad, per planitiem Libani subter montem Hermon: omnes reges eorum cepit, percussit, et occidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Multo tempore pugnavit Josue contra reges istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Non fuit civitas quæ se traderet filiis Israël, præter Hevæum, qui habitabat in Gabaon: omnes enim bellando cepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Domini enim sententia fuerat, ut indurarentur corda eorum, et pugnarent contra Israël, et caderent, et non mererentur ullam clementiam, ac perirent, sicut præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'In illo tempore venit Josue, et interfecit Enacim de montanis, Hebron, et Dabir, et Anab, et de omni monte Juda et Israël, urbesque eorum delevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Non reliquit ullum de stirpe Enacim, in terra filiorum Israël: absque civitatibus Gaza, et Geth, et Azoto, in quibus solis relicti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Cepit ergo Josue omnem terram, sicut locutus est Dominus ad Moysen, et tradidit eam in possessionem filiis Israël secundum partes et tribus suas: quievitque terra a præliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Hi sunt reges, quos percusserunt filii Israël, et possederunt terram eorum trans Jordanem ad solis ortum, a torrente Arnon usque ad montem Hermon, et omnem orientalem plagam, quæ respicit solitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sehon rex Amorrhæorum, qui habitavit in Hesebon, dominatus est ab Aroër, quæ sita est super ripam torrentis Arnon, et mediæ partis in valle, dimidiæque Galaad, usque ad torrentem Jaboc, qui est terminus filiorum Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Et a solitudine usque ad mare Ceneroth contra orientem, et usque ad mare deserti, quod est mare salsissimum, ad orientalem plagam per viam quæ ducit Bethsimoth: et ab australi parte, quæ subjacet Asedoth, Phasga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Terminus Og regis Basan, de reliquiis Raphaim, qui habitavit in Astaroth, et in Edrai, et dominatus est in monte Hermon, et in Salecha, atque in universa Basan, usque ad terminos');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Gessuri, et Machati, et dimidiæ partis Galaad: terminos Sehon regis Hesebon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moyses famulus Domini et filii Israël percusserunt eos, tradiditque terram eorum Moyses in possessionem Rubenitis, et Gaditis, et dimidiæ tribui Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Hi sunt reges terræ, quos percussit Josue et filii Israël trans Jordanem ad occidentalem plagam, a Baalgad in campo Libani, usque ad montem cujus pars ascendit in Seir: tradiditque eam Josue in possessionem tribubus Israël, singulis partes suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'tam in montanis quam in planis atque campestribus. In Asedoth, et in solitudine, ac in meridie, Hethæus fuit et Amorrhæus, Chananæus, et Pherezæus, Hevæus et Jebusæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Rex Jericho unus: rex Hai, quæ est ex latere Bethel, unus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'rex Jerusalem unus, rex Hebron unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'rex Jerimoth unus, rex Lachis unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'rex Eglon unus, rex Gazer unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'rex Dabir unus, rex Gader unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'rex Herma unus, rex Hered unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'rex Lebna unus, rex Odullam unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'rex Maceda unus, rex Bethel unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'rex Taphua unus, rex Opher unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'rex Aphec unus, rex Saron unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'rex Madon unus, rex Asor unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'rex Semeron unus, rex Achsaph unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'rex Thenac unus, rex Mageddo unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'rex Cades unus, rex Jachanan Carmeli unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'rex Dor et provinciæ Dor unus, rex gentium Galgal unus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'rex Thersa unus: omnes reges triginta unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Josue senex provectæque ætatis erat, et dixit Dominus ad eum: Senuisti, et longævus es, terraque latissima derelicta est, quæ necdum sorte divisa est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'omnis videlicet Galilæa, Philisthiim, et universa Gessuri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'A fluvio turbido, qui irrigat \'gyptum, usque ad terminos Accaron contra aquilonem: terra Chanaan, quæ in quinque regulos Philisthiim dividitur, Gazæos, et Azotios, Ascalonitas, Gethæos, et Accaronitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Ad meridiem vero sunt Hevæi, omnis terra Chanaan, et Maara Sidoniorum, usque Apheca et terminos Amorrhæi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'ejusque confinia. Libani quoque regio contra orientem, a Baalgad sub monte Hermon, donec ingrediaris Emath;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'omnium qui habitant in monte a Libano usque ad aquas Maserephoth, universique Sidonii. Ego sum qui delebo eos a facie filiorum Israël. Veniat ergo in partem hæreditatis Israël, sicut præcepi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Et nunc divide terram in possessionem novem tribubus, et dimidiæ tribui Manasse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'cum qua Ruben et Gad possederunt terram, quam tradidit eis Moyses famulus Domini trans fluenta Jordanis, ad orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Ab Aroër, quæ sita est in ripa torrentis Arnon, et in vallis medio, universaque campestria Medaba, usque Dibon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'et cunctas civitates Sehon regis Amorrhæi, qui regnavit in Hesebon, usque ad terminos filiorum Ammon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'et Galaad, ac terminum Gessuri et Machati, et omnem montem Hermon, et universam Basan, usque ad Salecha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'omne regnum Og in Basan, qui regnavit in Astaroth et Edrai, ipse fuit de reliquiis Raphaim: percussitque eos Moyses, atque delevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Nolueruntque disperdere filii Israël Gessuri et Machati: et habitaverunt in medio Israël usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Tribui autem Levi non dedit possessionem: sed sacrificia et victimæ Domini Dei Israël, ipsa est ejus hæreditas, sicut locutus est illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Dedit ergo Moyses possessionem tribui filiorum Ruben juxta cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Fuitque terminus eorum ab Aroër, quæ sita est in ripa torrentis Arnon, et in valle ejusdem torrentis media: universam planitiem, quæ ducit Medaba,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'et Hesebon, cunctosque viculos earum, qui sunt in campestribus: Dibon quoque et Bamothbaal, et oppidum Baalmaon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'et Jassa, et Cedimoth, et Mephaath,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'et Cariathaim, et Sabama, et Sarathasar in monte convallis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bethphogor et Asedoth, Phasga et Bethiesimoth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'et omnes urbes campestres, universaque regna Sehon regis Amorrhæi, qui regnavit in Hesebon, quem percussit Moyses cum principibus Madian: Hevæum, et Recem, et Sur, et Hur, et Rebe duces Sehon habitatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Et Balaam filium Beor ariolum occiderunt filii Israël gladio cum ceteris interfectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Factusque est terminus filiorum Ruben Jordanis fluvius. Hæc est possessio Rubenitarum per cognationes suas urbium et viculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Deditque Moyses tribui Gad et filiis ejus per cognationes suas possessionem, cujus hæc divisio est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Terminus Jaser, et omnes civitates Galaad, et dimidiam partem terræ filiorum Ammon, usque ad Aroër, quæ est contra Rabba,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'et ab Hesebon usque Ramoth, Masphe et Betonim: et a Manaim usque ad terminos Dabir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'In valle quoque Betharan, et Bethnemra, et Socoth, et Saphon reliquam partem regni Sehon regis Hesebon: hujus quoque finis, Jordanis est, usque ad extremam partem maris Cenereth trans Jordanem ad orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Hæc est possessio filiorum Gad per familias suas, civitates et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Dedit et dimidiæ tribui Manasse, filiisque ejus juxta cognationes suas, possessionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'cujus hoc principium est: a Manaim universam Basan, et cuncta regna Og regis Basan, omnesque vicos Jair, qui sunt in Basan, sexaginta oppida:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'et dimidiam partem Galaad, et Astaroth, et Edrai, urbes regni Og in Basan: filiis Machir, filii Manasse, dimidiæ parti filiorum Machir juxta cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Hanc possessionem divisit Moyses in campestribus Moab trans Jordanem contra Jericho ad orientalem plagam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Tribui autem Levi non dedit possessionem: quoniam Dominus Deus Israël ipse est possessio ejus, ut locutus est illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Hoc est quod possederunt filii Israël in terra Chanaan, quam dederunt eis Eleazar sacerdos, et Josue filius Nun, et principes familiarum per tribus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'sorte omnia dividentes, sicut præceperat Dominus in manu Moysi, novem tribubus, et dimidiæ tribui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Duabus enim tribubus, et dimidiæ, dederat Moyses trans Jordanem possessionem: absque Levitis, qui nihil terræ acceperunt inter fratres suos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'sed in eorum successerunt locum filii Joseph in duas divisi tribus, Manasse et Ephraim: nec acceperunt Levitæ aliam in terra partem, nisi urbes ad habitandum, et suburbana earum ad alenda jumenta et pecora sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Sicut præceperat Dominus Moysi, ita fecerunt filii Israël, et diviserunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Accesserunt itaque filii Juda ad Josue in Galgala, locutusque est ad eum Caleb filius Jephone Cenezæus: Nosti quid locutus sit Dominus ad Moysen hominem Dei de me et te in Cadesbarne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Quadraginta annorum eram quando misit me Moyses famulus Domini de Cadesbarne, ut considerarem terram, nuntiavique ei quod mihi verum videbatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Fratres autem mei, qui ascenderant mecum, dissolverunt cor populi: et nihilominus ego secutus sum Dominum Deum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Juravitque Moyses in die illo, dicens: Terra, quam calcavit pes tuus, erit possessio tua, et filiorum tuorum in æternum: quia secutus es Dominum Deum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Concessit ergo Dominus vitam mihi, sicut pollicitus est, usque in præsentem diem. Quadraginta et quinque anni sunt, ex quo locutus est Dominus verbum istud ad Moysen, quando ambulabat Israël per solitudinem: hodie octoginta quinque annorum sum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'sic valens ut eo valebam tempore quando ad explorandum missus sum: illius in me temporis fortitudo usque hodie perseverat, tam ad bellandum quam ad gradiendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Da ergo mihi montem istum, quem pollicitus est Dominus, te quoque audiente, in quo Enacim sunt, et urbes magnæ atque munitæ: si forte sit Dominus mecum, et potuero delere eos, sicut promisit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Benedixitque ei Josue, et tradidit ei Hebron in possessionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'atque ex eo fuit Hebron Caleb filio Jephone Cenezæo usque in præsentem diem, quia secutus est Dominum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Nomen Hebron ante vocabatur Cariath Arbe: Adam maximus ibi inter Enacim situs est: et terra cessavit a præliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Igitur sors filiorum Judæ per cognationes suas ista fuit: a termino Edom, desertum Sin, contra meridiem, et usque ad extremam partem australis plagæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Initium ejus a summitate maris salsissimi, et a lingua ejus, quæ respicit meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Egrediturque contra ascensum Scorpionis, et pertransit in Sina: ascenditque in Cadesbarne, et pervenit in Esron, ascendens ad Addar, et circuiens Carcaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'atque inde pertransiens in Asemona, et perveniens ad torrentem \'gypti: eruntque termini ejus mare magnum. Hic erit finis meridianæ plagæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Ab oriente vero erit initium, mare salsissimum usque ad extrema Jordanis: et ea quæ respiciunt ad aquilonem, a lingua maris usque ad eumdem Jordanis fluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Ascenditque terminus in Beth Hagla, et transit ab aquilone in Beth Araba, ascendens ad lapidem Boën filii Ruben:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'et tendens usque ad terminos Debera de valle Achor, contra aquilonem respiciens Galgala, quæ est ex adverso ascensionis Adommim, ab australi parte torrentis: transitque aquas, quæ vocantur fons solis: et erunt exitus ejus ad fontem Rogel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Ascenditque per convallem filii Ennom ex latere Jebusæi ad meridiem, hæc est Jerusalem: et inde se erigens ad verticem montis, qui est contra Geennom ad occidentem in summitate vallis Raphaim contra aquilonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'pertransitque a vertice montis usque ad fontem aquæ Nephtoa: et pervenit usque ad vicos montis Ephron: inclinaturque in Baala, quæ est Cariathiarim, id est, urbs silvarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Et circuit de Baala contra occidentem, usque ad montem Seir: transitque juxta latus montis Jarim ad aquilonem in Cheslon: et descendit in Bethsames, transitque in Thamna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Et pervenit contra aquilonem partis Accaron ex latere: inclinaturque Sechrona, et transit montem Baala: pervenitque in Jebneel, et magni maris contra occidentem fine concluditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Hi sunt termini filiorum Juda per circuitum in cognationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Caleb vero filio Jephone dedit partem in medio filiorum Juda, sicut præceperat ei Dominus: Cariath Arbe patris Enac, ipsa est Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Delevitque ex ea Caleb tres filios Enac, Sesai et Ahiman et Tholmai de stirpe Enac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Atque inde conscendens venit ad habitatores Dabir, quæ prius vocabatur Cariath Sepher, id est, civitas litterarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Dixitque Caleb: Qui percusserit Cariath Sepher, et ceperit eam, dabo ei Axam filiam meam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Cepitque eam Othoniel filius Cenez frater Caleb junior: deditque ei Axam filiam suam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Quæ, cum pergerent simul, suasa est a viro suo ut peteret a patre suo agrum. Suspiravitque ut sedebat in asino: cui Caleb: Quid habes? inquit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'At illa respondit: Da mihi benedictionem: terram australem et arentem dedisti mihi; junge et irriguam. Dedit itaque ei Caleb irriguum superius et inferius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Hæc est possessio tribus filiorum Juda per cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Erantque civitates ab extremis partibus filiorum Juda juxta terminos Edom a meridie: Cabseel et Eder et Jagur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'et Cyna et Dimona et Adada,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'et Cades et Asor et Jethnam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Ziph et Telem et Baloth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Asor nova et Carioth, Hesron, hæc est Asor;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sama, et Molada,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'et Asergadda et Hassemon et Bethphelet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'et Hasersual et Bersabee et Baziothia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'et Baala et Jim et Esem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'et Eltholad et Cesil et Harma,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'et Siceleg et Medemena et Sensenna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth et Selim et Aën et Remon. Omnes civitates viginti novem, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In campestribus vero: Estaol et Sarea et Asena,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'et Zanoë et \'ngannim et Taphua et Enaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'et Jerimoth et Adullam, Socho et Azeca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'et Saraim et Adithaim et Gedera et Gederothaim: urbes quatuordecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Sanan et Hadassa et Magdalgad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Delean et Masepha et Jecthel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis et Bascath et Eglon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chebbon et Leheman et Cethlis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'et Gideroth et Bethdagon et Naama et Maceda: civitates sedecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Labana et Ether et Asan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jephtha et Esna et Nesib,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'et Ceila et Achzib et Maresa: civitates novem, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Accaron cum vicis et villulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Ab Accaron usque ad mare: omnia quæ vergunt ad Azotum et viculos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Azotus cum vicis et villulis suis. Gaza cum vicis et villulis suis, usque ad torrentem \'gypti, et mare magnum terminus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Et in monte: Samir et Jether et Socoth');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'et Danna et Cariathsenna, hæc est Dabir:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab et Istemo et Anim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen et Olon et Gilo: civitates undecim et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab et Ruma et Esaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'et Janum et Beththaphua et Apheca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Athmatha, et Cariath Arbe, hæc est Hebron, et Sior: civitates novem, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon et Carmel et Ziph et Jota,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezraël et Jucadam et Zanoë,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Accain, Gabaa et Thamna: civitates decem et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, et Besur, et Gedor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Mareth, et Bethanoth, et Eltecon: civitates sex et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Cariathbaal, hæc est Cariathiarim urbs silvarum, et Arebba: civitates duæ, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In deserto Betharaba, Meddin, et Sachacha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'et Nebsan, et civitas salis, et Engaddi: civitates sex, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Jebusæum autem habitatorem Jerusalem non potuerunt filii Juda delere: habitavitque Jebusæus cum filiis Juda in Jerusalem usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Cecidit quoque sors filiorum Joseph ab Jordane contra Jericho et aquas ejus ab oriente: solitudo quæ ascendit de Jericho ad montem Bethel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'et egreditur de Bethel Luza: transitque terminum Archi, Ataroth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'et descendit ad occidentem juxta terminum Jephleti, usque ad terminos Beth-horon inferioris, et Gazer: finiunturque regiones ejus mari magno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'possederuntque filii Joseph, Manasses et Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Et factus est terminus filiorum Ephraim per cognationes suas: et possessio eorum contra orientem Ataroth Addar usque Beth-horon superiorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Egrediunturque confinia in mare: Machmethath vero aquilonem respicit, et circuit terminos contra orientem in Thanathselo: et pertransit ab oriente Janoë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Descenditque de Janoë in Ataroth et Naaratha: et pervenit in Jericho, egrediturque ad Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'De Taphua pertransit contra mare in vallem arundineti, suntque egressus ejus in mare salsissimum. Hæc est possessio tribus filiorum Ephraim per familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Urbesque separatæ sunt filiis Ephraim in medio possessionis filiorum Manasse, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Et non interfecerunt filii Ephraim Chananæum, qui habitabat in Gazer: habitavitque Chananæus in medio Ephraim usque in diem hanc tributarius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Cecidit autem sors tribui Manasse (ipse enim est primogenitus Joseph): Machir primogenito Manasse patri Galaad, qui fuit vir pugnator, habuitque possessionem Galaad et Basan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'et reliquis filiorum Manasse juxta familias suas, filiis Abiezer, et filiis Helec, et filiis Esriel, et filiis Sechem, et filiis Hepher, et filiis Semida. Isti sunt filii Manasse filii Joseph, mares, per cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Salphaad vero filio Hepher filii Galaad filii Machir filii Manasse non erant filii, sed solæ filiæ: quarum ista sunt nomina: Maala et Noa et Hegla et Melcha et Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Veneruntque in conspectu Eleazari sacerdotis, et Josue filii Nun, et principum, dicentes: Dominus præcepit per manum Moysi, ut daretur nobis possessio in medio fratrum nostrorum. Deditque eis juxta imperium Domini possessionem in medio fratrum patris earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Et ceciderunt funiculi Manasse, decem, absque terra Galaad et Basan trans Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Filiæ enim Manasse possederunt hæreditatem in medio filiorum ejus. Terra autem Galaad cecidit in sortem filiorum Manasse qui reliqui erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Fuitque terminus Manasse ab Aser, Machmethath quæ respicit Sichem: et egreditur ad dexteram juxta habitatores fontis Taphuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Etenim in sorte Manasse ceciderat terra Taphuæ, quæ est juxta terminos Manasse filiorum Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Descenditque terminus vallis arundineti in meridiem torrentis civitatum Ephraim, quæ in medio sunt urbium Manasse: terminus Manasse ab aquilone torrentis, et exitus ejus pergit ad mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'ita ut possessio Ephraim sit ab austro, et ab aquilone Manasse, et utramque claudat mare, et conjungantur sibi in tribu Aser ab aquilone, et in tribu Issachar ab oriente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Fuitque hæreditas Manasse in Issachar et in Aser, Bethsan et viculi ejus, et Jeblaam cum viculis suis, et habitatores Dor cum oppidis suis, habitatores quoque Endor cum viculis suis: similiterque habitatores Thenac cum viculis suis, et habitatores Mageddo cum viculis suis, et tertia pars urbis Nopheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Nec potuerunt filii Manasse has civitates subvertere, sed cœpit Chananæus habitare in terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Postquam autem convaluerunt filii Israël, subjecerunt Chananæos, et fecerunt sibi tributarios, nec interfecerunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Locutique sunt filii Joseph ad Josue, et dixerunt: Quare dedisti mihi possessionem sortis et funiculi unius, cum sim tantæ multitudinis, et benedixerit mihi Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Ad quos Josue ait: Si populus multus es, ascende in silvam, et succide tibi spatia in terra Pherezæi et Raphaim: quia angusta est tibi possessio montis Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Cui responderunt filii Joseph: Non poterimus ad montana conscendere, cum ferreis curribus utantur Chananæi, qui habitant in terra campestri, in qua sitæ sunt Bethsan cum viculis suis, et Jezraël mediam possidens vallem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Dixitque Josue ad domum Joseph, Ephraim et Manasse: Populus multus es, et magnæ fortitudinis: non habebis sortem unam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'sed transibis ad montem, et succides tibi, atque purgabis ad habitandum spatia: et poteris ultra procedere cum subverteris Chananæum, quem dicis ferreos habere currus, et esse fortissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Congregatique sunt omnes filii Israël in Silo, ibique fixerunt tabernaculum testimonii, et fuit eis terra subjecta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Remanserant autem filiorum Israël septem tribus, quæ necdum acceperant possessiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Ad quos Josue ait: Usquequo marcetis ignavia, et non intratis ad possidendam terram, quam Dominus Deus patrum vestrorum dedit vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Eligite de singulis tribubus ternos viros, ut mittam eos, et pergant atque circumeant terram, et describant eam juxta numerum uniuscujusque multitudinis: referantque ad me quod descripserint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Dividite vobis terram in septem partes: Judas sit in terminis suis ab australi plaga, et domus Joseph ab aquilone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Mediam inter hos terram in septem partes describite: et huc venietis ad me, ut coram Domino Deo vestro mittam vobis hic sortem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'quia non est inter vos pars Levitarum, sed sacerdotium Domini est eorum hæreditas. Gad autem et Ruben, et dimidia tribus Manasse, jam acceperant possessiones suas trans Jordanem ad orientalem plagam, quas dedit eis Moyses famulus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Cumque surrexissent viri, ut pergerent ad describendam terram, præcepit eis Josue, dicens: Circuite terram, et describite eam, ac revertimini ad me: ut hic coram Domino, in Silo, mittam vobis sortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Itaque perrexerunt: et lustrantes eam, in septem partes diviserunt, scribentes in volumine. Reversique sunt ad Josue in castra Silo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Qui misit sortes coram Domino in Silo, divisitque terram filiis Israël in septem partes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Et ascendit sors prima filiorum Benjamin per familias suas, ut possiderent terram inter filios Juda et filios Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Fuitque terminus eorum contra aquilonem a Jordane: pergens juxta latus Jericho septentrionalis plagæ, et inde contra occidentem ad montana conscendens et perveniens ad solitudinem Bethaven,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'atque pertransiens juxta Luzam ad meridiem, ipsa est Bethel: descenditque in Ataroth Addar, in montem qui est ad meridiem Beth-horon inferioris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'et inclinatur circuiens contra mare ad meridiem montis qui respicit Beth-horon contra Africum: suntque exitus ejus in Cariath-baal, quæ vocatur et Cariathiarim, urbem filiorum Juda. Hæc est plaga contra mare, ad occidentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'A meridie autem ex parte Cariathiarim egreditur terminus contra mare, et pervenit usque ad fontem aquarum Nephtoa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Descenditque in partem montis, qui respicit vallem filiorum Ennom: et est contra septentrionalem plagam in extrema parte vallis Raphaim. Descenditque in Geennom (id est, vallem Ennom) juxta latus Jebusæi ad austrum: et pervenit ad fontem Rogel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'transiens ad aquilonem, et egrediens ad Ensemes, id est, fontem solis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'et pertransit usque ad tumulos, qui sunt e regione ascensus Adommim: descenditque ad Abenboën, id est, lapidem Boën filii Ruben: et pertransit ex latere aquilonis ad campestria: descenditque in planitiem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'et prætergreditur contra aquilonem Beth Hagla: suntque exitus ejus contra linguam maris salsissimi ab aquilone in fine Jordanis ad australem plagam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'qui est terminus illius ab oriente. Hæc est possessio filiorum Benjamin per terminos suos in circuitu, et familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Fueruntque civitates ejus, Jericho et Beth Hagla et vallis Casis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beth Araba et Samaraim et Bethel');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'et Avim et Aphara et Ophera,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'villa Emona et Ophni et Gabee: civitates duodecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabaon et Rama et Beroth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'et Mesphe et Caphara, et Amosa');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'et Recem, Jarephel et Tharela,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'et Sela, Eleph, et Jebus, quæ est Jerusalem, Gabaath et Cariath: civitates quatuordecim, et villæ earum. Hæc est possessio filiorum Benjamin juxta familias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Et egressa est sors secunda filiorum Simeon per cognationes suas: fuitque hæreditas');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'eorum in medio possessionis filiorum Juda: Bersabee et Sabee et Molada');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'et Hasersual, Bala et Asem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'et Eltholad, Bethul et Harma');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'et Siceleg et Bethmarchaboth et Hasersusa');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'et Bethlebaoth et Sarohen: civitates tredecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain et Remmon et Athar et Asan: civitates quatuor, et villæ earum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'omnes viculi per circuitum urbium istarum usque ad Baalath Beer Ramath contra australem plagam. Hæc est hæreditas filiorum Simeon juxta cognationes suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'in possessione et funiculo filiorum Juda: quia major erat, et idcirco filii Simeon possederunt in medio hæreditatis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Ceciditque sors tertia filiorum Zabulon per cognationes suas: factus est terminus possessionis eorum usque Sarid.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Ascenditque de mari et Merala, et pervenit in Debbaseth, usque ad torrentem qui est contra Jeconam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Et revertitur de Sared contra orientem in fines Ceseleththabor: et egreditur ad Dabereth, ascenditque contra Japhie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Et inde pertransit usque ad orientalem plagam Gethepher et Thacasin: et egreditur in Remmon, Amthar et Noa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Et circuit ad aquilonem Hanathon: suntque egressus ejus vallis Jephthaël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'et Cateth et Naalol et Semeron et Jerala et Bethlehem: civitates duodecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Hæc est hæreditas tribus filiorum Zabulon per cognationes suas, urbes et viculi earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Issachar egressa est sors quarta per cognationes suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'fuitque ejus hæreditas Jezraël et Casaloth et Sunem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'et Hapharaim et Seon, et Anaharath');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'et Rabboth et Cesion, Abes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'et Rameth, et Engannim, et Enhadda et Bethpheses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Et pervenit terminus ejus usque Thabor et Sehesima et Bethsames, eruntque exitus ejus Jordanis: civitates sedecim, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Hæc est possessio filiorum Issachar per cognationes suas, urbes et viculi earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Ceciditque sors quinta tribui filiorum Aser per cognationes suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'fuitque terminus eorum Halcath et Chali et Beten et Axaph');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'et Elmelech et Amaad et Messal: et pervenit usque ad Carmelum maris et Sihor et Labanath,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'ac revertitur contra orientem Bethdagon: et pertransit usque Zabulon et vallem Jephthaël contra aquilonem in Bethemec et Nehiel. Egrediturque ad lævam Cabul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'et Abran et Rohob et Hamon et Cana, usque ad Sidonem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Revertiturque in Horma usque ad civitatem munitissimam Tyrum, et usque Hosa: eruntque exitus ejus in mare de funiculo Achziba:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'et Amma et Aphec et Rohob: civitates viginti duæ, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Hæc est possessio filiorum Aser per cognationes suas, urbesque et viculi earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Filiorum Nephthali sexta sors cecidit per familias suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'et cœpit terminus de Heleph et Elon in Saananim, et Adami, quæ est Neceb, et Jebnaël usque Lecum: et egressus eorum usque ad Jordanem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'revertiturque terminus contra occidentem in Azanotthabor, atque inde egreditur in Hucuca, et pertransit in Zabulon contra meridiem, et in Aser contra occidentem, et in Juda ad Jordanem contra ortum solis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'civitates munitissimæ, Assedim, Ser, et Emath, et Reccath et Cenereth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'et Edema et Arama, Asor');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'et Cedes et Edrai, Enhasor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'et Jeron et Magdalel, Horem et Bethanath et Bethsames: civitates decem et novem, et villæ earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Hæc est possessio tribus filiorum Nephthali per cognationes suas, urbes et viculi earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Tribui filiorum Dan per familias suas egressa est sors septima:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'et fuit terminus possessionis ejus Sara et Esthaol, et Hirsemes, id est, civitas solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Selebin et Ajalon et Jethela,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon et Themna et Acron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elthece, Gebbethon et Balaath,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'et Jud et Bane et Barach et Gethremmon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'et Mejarcon et Arecon, cum termino qui respicit Joppen,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'et ipso fine concluditur. Ascenderuntque filii Dan, et pugnaverunt contra Lesem, ceperuntque eam: et percusserunt eam in ore gladii, et possederunt, et habitaverunt in ea, vocantes nomen ejus Lesem Dan, ex nomine Dan patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Hæc est possessio tribus filiorum Dan, per cognationes suas, urbes et viculi earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Cumque complesset sorte dividere terram singulis per tribus suas, dederunt filii Israël possessionem Josue filio Nun in medio sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'juxta præceptum Domini, urbem quam postulavit Thamnath Saraa in monte Ephraim: et ædificavit civitatem, habitavitque in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Hæ sunt possessiones, quas sorte diviserunt Eleazar sacerdos, et Josue filius Nun, et principes familiarum ac tribuum filiorum Israël in Silo, coram Domino ad ostium tabernaculi testimonii: partitique sunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Et locutus est Dominus ad Josue, dicens: Loquere filiis Israël, et dic eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Separate urbes fugitivorum, de quibus locutus sum ad vos per manum Moysi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'ut confugiat ad eas quicumque animam percusserit nescius, et possit evadere iram proximi, qui ultor est sanguinis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'cum ad unam harum confugerit civitatum, stabit ante portam civitatis, et loquetur senioribus urbis illius ea quæ se comprobent innocentem: sicque suscipient eum, et dabunt ei locum ad habitandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Cumque ultor sanguinis eum fuerit persecutus, non tradent in manus ejus: quia ignorans percussit proximum ejus, nec ante biduum triduumve ejus probatur inimicus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Et habitabit in civitate illa, donec stet ante judicium, causam reddens facti sui, et moriatur sacerdos magnus, qui fuerit in illo tempore: tunc revertetur homicida, et ingredietur civitatem et domum suam de qua fugerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Decreveruntque Cedes in Galilæa montis Nephthali, et Sichem in monte Ephraim, et Cariatharbe, ipsa est Hebron in monte Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Et trans Jordanem contra orientalem plagam Jericho, statuerunt Bosor, quæ sita est in campestri solitudine de tribu Ruben, et Ramoth in Galaad de tribu Gad, et Gaulon in Basan de tribu Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Hæ civitates constitutæ sunt cunctis filiis Israël, et advenis qui habitabant inter eos, ut fugeret ad eas qui animam nescius percussisset, et non moreretur in manu proximi, effusum sanguinem vindicare cupientis, donec staret ante populum expositurus causam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Accesseruntque principes familiarum Levi ad Eleazarum sacerdotem, et Josue filium Nun, et ad duces cognationum per singulas tribus filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'locutique sunt ad eos in Silo terræ Chanaan, atque dixerunt: Dominus præcepit per manum Moysi, ut darentur nobis urbes ad habitandum, et suburbana earum ad alenda jumenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Dederuntque filii Israël de possessionibus suis juxta imperium Domini, civitates et suburbana earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Egressaque est sors in familiam Caath filiorum Aaron sacerdotis, de tribubus Juda, et Simeon, et Benjamin, civitates tredecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'et reliquis filiorum Caath, id est Levitis, qui superfuerant, de tribubus Ephraim, et Dan, et dimidia tribu Manasse, civitates decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Porro filii Gerson egressa est sors, ut acciperent de tribubus Issachar et Aser et Nephthali, dimidiaque tribu Manasse in Basan, civitates numero tredecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Et filiis Merari per cognationes suas de tribubus Ruben et Gad et Zabulon urbes duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Dederuntque filii Israël Levitis civitates et suburbana earum, sicut præcepit Dominus per manum Moysi, singulis sorte tribuentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'De tribubus filiorum Juda et Simeon dedit Josue civitates, quarum ista sunt nomina,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'filiis Aaron per familias Caath Levitici generis (prima enim sors illis egressa est),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Cariatharbe patris Enac, quæ vocatur Hebron, in monte Juda, et suburbana ejus per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Agros vero et villas ejus dederat Caleb filio Jephone ad possidendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Dedit ergo filiis Aaron sacerdotis Hebron confugii civitatem, ac suburbana ejus: et Lobnam cum suburbanis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'et Jether, et Esthemo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'et Holon, et Dabir,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'et Ain, et Jeta, et Bethsames, cum suburbanis suis: civitates novem de tribubus, ut dictum est, duabus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'De tribu autem filiorum Benjamin, Gabaon, et Gabæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'et Anathoth et Almon, cum suburbanis suis: civitates quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Omnes simul civitates filiorum Aaron sacerdotis, tredecim, cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Reliquis vero per familias filiorum Caath Levitici generis, hæc est data possessio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'De tribu Ephraim urbes confugii, Sichem cum suburbanis suis in monte Ephraim, et Gazer');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'et Cibsaim et Beth-horon, cum suburbanis suis, civitates quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'De tribu quoque Dan, Eltheco et Gabathon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'et Ajalon et Gethremmon, cum suburbanis suis, civitates quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Porro de dimidia tribu Manasse, Thanach et Gethremmon, cum suburbanis suis, civitates duæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Omnes civitates decem, et suburbana earum, datæ sunt filiis Caath inferioris gradus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Filiis quoque Gerson Levitici generis dedit de dimidia tribu Manasse confugii civitates, Gaulon in Basan, et Bosram, cum suburbanis suis, civitates duas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Porro de tribu Issachar, Cesion, et Dabereth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'et Jaramoth, et Engannim, cum suburbanis suis, civitates quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'De tribu autem Aser, Masal et Abdon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'et Helcath, et Rohob, cum suburbanis suis, civitates quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'De tribu quoque Nephthali civitates confugii, Cedes in Galilæa, et Hammoth Dor, et Carthan, cum suburbanis suis, civitates tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Omnes urbes familiarum Gerson, tredecim, cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Filiis autem Merari Levitis inferioris gradus per familias suas data est de tribu Zabulon, Jecnam, et Cartha');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'et Damna et Naalol, civitates quatuor cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'De tribu Ruben ultra Jordanem contra Jericho civitates refugii, Bosor in solitudine, Misor et Jaser et Jethson et Mephaath, civitates quatuor cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'De tribu Gad civitates confugii, Ramoth in Galaad, et Manaim et Hesebon et Jazer, civitates quatuor cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Omnes urbes filiorum Merari per familias et cognationes suas, duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Itaque civitates universæ Levitarum in medio possessionis filiorum Israël fuerunt quadraginta octo');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'cum suburbanis suis, singulæ per familias distributæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Deditque Dominus Deus Israëli omnem terram, quam traditurum se patribus eorum juraverat: et possederunt illam, atque habitaverunt in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Dataque est ab eo pax in omnes per circuitum nationes: nullusque eis hostium resistere ausus est, sed cuncti in eorum ditionem redacti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Ne unum quidem verbum, quod illis præstiturum se esse promiserat, irritum fuit, sed rebus expleta sunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Eodem tempore vocavit Josue Rubenitas, et Gaditas, et dimidiam tribum Manasse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'dixitque ad eos: Fecistis omnia quæ præcepit vobis Moyses famulus Domini: mihi quoque in omnibus obedistis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'nec reliquistis fratres vestros longo tempore, usque in præsentem diem, custodientes imperium Domini Dei vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Quia igitur dedit Dominus Deus vester fratribus vestris quietem et pacem, sicut pollicitus est: revertimini, et ite in tabernacula vestra, et in terram possessionis, quam tradidit vobis Moyses famulus Domini trans Jordanem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'ita dumtaxat ut custodiatis attente, et opere compleatis mandatum et legem quam præcepit vobis Moyses famulus Domini, ut diligatis Dominum Deum vestrum, et ambuletis in omnibus viis ejus, et observetis mandata illius, adhæreatisque ei, ac serviatis in omni corde, et in omni anima vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Benedixitque eis Josue, et dimisit eos. Qui reversi sunt in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Dimidiæ autem tribui Manasse possessionem Moyses dederat in Basan: et idcirco mediæ, quæ superfuit, dedit Josue sortem inter ceteros fratres suos trans Jordanem ad occidentalem plagam. Cumque dimitteret eos in tabernacula sua, et benedixisset eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'dixit ad eos: In multa substantia atque divitiis revertimini ad sedes vestras, cum argento et auro, ære ac ferro, et veste multiplici: dividite prædam hostium cum fratribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Reversique sunt, et abierunt filii Ruben, et filii Gad, et dimidia tribus Manasse, a filiis Israël de Silo, quæ sita est in Chanaan, ut intrarent Galaad terram possessionis suæ, quam obtinuerant juxta imperium Domini in manu Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Cumque venissent ad tumulos Jordanis in terram Chanaan, ædificaverunt juxta Jordanem altare infinitæ magnitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Quod cum audissent filii Israël, et ad eos certi nuntii detulissent, ædificasse filios Ruben, et Gad, et dimidiæ tribus Manasse, altare in terra Chanaan, super Jordanis tumulos, contra filios Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'convenerunt omnes in Silo, ut ascenderent, et dimicarent contra eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Et interim miserunt ad illos in terram Galaad Phinees filium Eleazari sacerdotis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'et decem principes cum eo, singulos de singulis tribubus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Qui venerunt ad filios Ruben, et Gad, et dimidiæ tribus Manasse in terram Galaad, dixeruntque ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Hæc mandat omnis populus Domini: Quæ est ista transgressio? cur reliquistis Dominum Deum Israël, ædificantes altare sacrilegum, et a cultu illius recedentes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'an parum vobis est quod peccastis in Beelphegor, et usque in præsentem diem macula hujus sceleris in nobis permanet, multique de populo corruerunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Et vos hodie reliquistis Dominum, et cras in universum Israël ira ejus desæviet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Quod si putatis immundam esse terram possessionis vestræ, transite ad terram, in qua tabernaculum Domini est, et habitate inter nos: tantum ut a Domino et a nostro consortio non recedatis, ædificato altari præter altare Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Nonne Achan filius Zare præteriit mandatum Domini, et super omnem populum Israël ira ejus incubuit? et ille erat unus homo, atque utinam solum periisset in scelere suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Responderuntque filii Ruben et Gad, et dimidia tribus Manasse, principibus legationis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Fortissimus Deus Dominus, fortissimus Deus Dominus, ipse novit, et Israël simul intelliget: si prævaricationis animo hoc altare construximus, non custodiat nos, sed puniat nos in præsenti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'et si ea mente fecimus ut holocausta, et sacrificium, et pacificas victimas super eo imponeremus, ipse quærat et judicet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'et non ea magis cogitatione atque tractatu, ut diceremus: Cras dicent filii vestri filiis nostris: Quid vobis et Domino Deo Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'terminum posuit Dominus inter nos et vos, o filii Ruben, et filii Gad, Jordanem fluvium, et idcirco partem non habetis in Domino: et per hanc occasionem avertent filii vestri filios nostros a timore Domini. Putavimus itaque melius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'et diximus: Exstruamus nobis altare, non in holocausta, neque ad victimas offerendas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sed in testimonium inter nos et vos, et sobolem nostram vestramque progeniem, ut serviamus Domino, et juris nostri sit offerre et holocausta, et victimas, et pacificas hostias: et nequaquam dicant cras filii vestri filiis nostris: Non est vobis pars in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Quod si voluerint dicere, respondebunt eis: Ecce altare Domini, quod fecerunt patres nostri, non in holocausta, neque in sacrificium, sed in testimonium nostrum ac vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Absit a nobis hoc scelus, ut recedamus a Domino, et ejus vestigia relinquamus, exstructo altari ad holocausta, et sacrificia, et victimas offerendas, præter altare Domini Dei nostri, quod exstructum est ante tabernaculum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Quibus auditis, Phinees sacerdos, et principes legationis Israël, qui erant cum eo, placati sunt: et verba filiorum Ruben, et Gad, et dimidiæ tribus Manasse, libentissime susceperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Dixitque Phinees filius Eleazari sacerdos ad eos: Nunc scimus quod nobiscum sit Dominus, quoniam alieni estis a prævaricatione hac, et liberastis filios Israël de manu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Reversusque est cum principibus a filiis Ruben et Gad de terra Galaad, finium Chanaan, ad filios Israël, et retulit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Placuitque sermo cunctis audientibus. Et laudaverunt Deum filii Israël, et nequaquam ultra dixerunt, ut ascenderent contra eos, atque pugnarent, et delerent terram possessionis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Vocaveruntque filii Ruben, et filii Gad, altare quod exstruxerant, Testimonium nostrum, quod Dominus ipse sit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Evoluto autem multo tempore, postquam pacem dederat Dominus Israëli, subjectis in gyro nationibus universis, et Josue jam longævo, et persenilis ætatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'vocavit Josue omnem Israëlem, majoresque natu, et principes ac duces, et magistros, dixitque ad eos: Ego senui, et progressioris ætatis sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'vosque cernitis omnia, quæ fecerit Dominus Deus vester cunctis per circuitum nationibus, quomodo pro vobis ipse pugnaverit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'et nunc quia vobis sorte divisit omnem terram, ab orientali parte Jordanis usque ad mare magnum, multæque adhuc supersunt nationes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Dominus Deus vester disperdet eas et auferet a facie vestra, et possidebitis terram, sicut vobis pollicitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Tantum confortamini, et estote solliciti, ut custodiatis cuncta quæ scripta sunt in volumine legis Moysi: et non declinetis ab eis neque ad dexteram neque ad sinistram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'ne postquam intraveritis ad gentes quæ inter vos futuræ sunt, juretis in nomine deorum earum, et serviatis eis, et adoretis illos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'sed adhæreatis Domino Deo vestro: quod fecistis usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Et tunc auferet Dominus Deus in conspectu vestro gentes magnas et robustissimas, et nullus vobis resistere poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Unus e vobis persequetur hostium mille viros: quia Dominus Deus vester pro vobis ipse pugnabit, sicut pollicitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Hoc tantum diligentissime præcavete: ut diligatis Dominum Deum vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Quod si volueritis gentium harum, quæ inter vos habitant, erroribus adhærere, et cum eis miscere connubia, atque amicitias copulare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'jam nunc scitote quod Dominus Deus vester non eas deleat ante faciem vestram, sed sint vobis in foveam ac laqueum, et offendiculum ex latere vestro, et sudes in oculis vestris, donec vos auferat atque disperdat de terra hac optima, quam tradidit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'En ego hodie ingredior viam universæ terræ, et toto animo cognoscetis quod de omnibus verbis, quæ se Dominus præstiturum vobis esse pollicitus est, unum non præterierit incassum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Sicut ergo implevit opere quod promisit, et prospera cuncta venerunt: sic adducet super vos quidquid malorum comminatus est, donec vos auferat atque disperdat de terra hac optima, quam tradidit vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'eo quod præterieritis pactum Domini Dei vestri, quod pepigit vobiscum, et servieritis diis alienis, et adoraveritis eos: cito atque velociter consurget in vos furor Domini, et auferemini ab hac terra optima, quam tradidit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Congregavitque Josue omnes tribus Israël in Sichem, et vocavit majores natu, ac principes, et judices, et magistros: steteruntque in conspectu Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'et ad populum sic locutus est: Hæc dicit Dominus Deus Israël: Trans fluvium habitaverunt patres vestri ab initio, Thare pater Abraham et Nachor: servieruntque diis alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Tuli ergo patrem vestrum Abraham de Mesopotamiæ finibus, et adduxi eum in terram Chanaan, multiplicavique semen ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'et dedi ei Isaac: illique rursum dedi Jacob et Esau. E quibus, Esau dedi montem Seir ad possidendum: Jacob vero et filii ejus descenderunt in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Misique Moysen et Aaron, et percussi \'gyptum multis signis atque portentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Eduxique vos et patres vestros de \'gypto, et venistis ad mare: persecutique sunt \'gyptii patres vestros cum curribus et equitatu, usque ad mare Rubrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Clamaverunt autem ad Dominum filii Israël: qui posuit tenebras inter vos et \'gyptios, et adduxit super eos mare, et operuit eos. Viderunt oculi vestri cuncta quæ in \'gypto fecerim, et habitastis in solitudine multo tempore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'et introduxi vos in terram Amorrhæi, qui habitabat trans Jordanem. Cumque pugnarent contra vos, tradidi eos in manus vestras, et possedistis terram eorum, atque interfecistis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Surrexit autem Balac filius Sephor rex Moab, et pugnavit contra Israëlem. Misitque et vocavit Balaam filium Beor, ut malediceret vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'et ego nolui audire eum, sed e contrario per illum benedixi vobis, et liberavi vos de manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Transistisque Jordanem, et venistis ad Jericho. Pugnaveruntque contra vos viri civitatis ejus, Amorrhæus et Pherezæus, et Chananæus, et Hethæus, et Gergezæus, et Hevæus, et Jebusæus: et tradidi illos in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Misique ante vos crabrones: et ejeci eos de locis suis, duos reges Amorrhæorum, non in gladio nec in arcu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Dedique vobis terram, in qua non laborastis, et urbes quas non ædificastis, ut habitaretis in eis: vineas, et oliveta, quæ non plantastis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Nunc ergo timete Dominum, et servite ei perfecto corde atque verissimo: et auferte deos quibus servierunt patres vestri in Mesopotamia et in \'gypto, ac servite Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Sin autem malum vobis videtur ut Domino serviatis, optio vobis datur: eligite hodie quod placet, cui servire potissimum debeatis: utrum diis, quibus servierunt patres vestri in Mesopotamia, an diis Amorrhæorum, in quorum terra habitatis: ego autem et domus mea serviemus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Responditque populus, et ait: Absit a nobis ut relinquamus Dominum, et serviamus diis alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Dominus Deus noster, ipse eduxit nos et patres nostros de terra \'gypti, de domo servitutis: fecitque videntibus nobis signa ingentia, et custodivit nos in omni via per quam ambulavimus, et in cunctis populis per quos transivimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Et ejecit universas gentes, Amorrhæum habitatorem terræ quam nos intravimus. Serviemus igitur Domino, quia ipse est Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Dixitque Josue ad populum: Non poteritis servire Domino: Deus enim sanctus et fortis æmulator est, nec ignoscet sceleribus vestris atque peccatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Si dimiseritis Dominum, et servieritis diis alienis, convertet se, et affliget vos atque subvertet, postquam vobis præstiterit bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Dixitque populus ad Josue: Nequaquam ita ut loqueris erit, sed Domino serviemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Et Josue ad populum: Testes, inquit, vos estis, quia ipsi elegeritis vobis Dominum ut serviatis ei. Responderuntque: Testes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Nunc ergo, ait, auferte deos alienos de medio vestri, et inclinate corda vestra ad Dominum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Dixitque populus ad Josue: Domino Deo nostro serviemus, et obedientes erimus præceptis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Percussit ergo Josue in die illo fœdus, et proposuit populo præcepta atque judicia in Sichem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Scripsit quoque omnia verba hæc in volumine legis Domini: et tulit lapidem pergrandem, posuitque eum subter quercum, quæ erat in sanctuario Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'et dixit ad omnem populum: En lapis iste erit vobis in testimonium, quod audierit omnia verba Domini, quæ locutus est vobis: ne forte postea negare velitis, et mentiri Domino Deo vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Dimisitque populum, singulos in possessionem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Et post hæc mortuus est Josue filius Nun servus Domini, centum et decem annorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'sepelieruntque eum in finibus possessionis suæ in Thamnathsare, quæ est sita in monte Ephraim, a septentrionali parte montis Gaas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Servivitque Israël Domino cunctis diebus Josue et seniorum, qui longo vixerunt tempore post Josue, et qui noverunt omnia opera Domini quæ fecerat in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Ossa quoque Joseph, quæ tulerant filii Israël de \'gypto, sepelierunt in Sichem, in parte agri quem emerat Jacob a filiis Hemor patris Sichem, centum novellis ovibus, et fuit in possessionem filiorum Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleazar quoque filius Aaron mortuus est: et sepelierunt eum in Gabaath Phinees filii ejus, quæ data est ei in monte Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Post mortem Josue, consuluerunt filii Israël Dominum, dicentes: Quis ascendet ante nos contra Chananæum, et erit dux belli?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Dixitque Dominus: Judas ascendet: ecce tradidi terram in manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Et ait Judas Simeoni fratri suo: Ascende mecum in sortem meam, et pugna contra Chananæum, ut et ego pergam tecum in sortem tuam. Et abiit cum eo Simeon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Ascenditque Judas, et tradidit Dominus Chananæum ac Pherezæum in manus eorum: et percusserunt in Bezec decem millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Inveneruntque Adonibezec in Bezec, et pugnaverunt contra eum, ac percusserunt Chananæum et Pherezæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Fugit autem Adonibezec: quem persecuti comprehenderunt, cæsis summitatibus manuum ejus ac pedum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Dixitque Adonibezec: Septuaginta reges amputatis manuum ac pedum summitatibus colligebant sub mensa mea ciborum reliquias: sicut feci, ita reddidit mihi Deus. Adduxeruntque eum in Jerusalem, et ibi mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Oppugnantes ergo filii Juda Jerusalem, ceperunt eam, et percusserunt in ore gladii, tradentes cunctam incendio civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Et postea descendentes pugnaverunt contra Chananæum, qui habitabat in montanis, et ad meridiem, et in campestribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Pergensque Judas contra Chananæum, qui habitabat in Hebron (cujus nomen fuit antiquitus Cariath Arbe), percussit Sesai, et Ahiman, et Tholmai:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'atque inde profectus abiit ad habitatores Dabir, cujus nomen vetus erat Cariath Sepher, id est, civitas litterarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Dixitque Caleb: Qui percusserit Cariath Sepher, et vastaverit eam, dabo ei Axam filiam meam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Cumque cepisset eam Othoniel filius Cenez frater Caleb minor, dedit ei Axam filiam suam conjugem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Quam pergentem in itinere monuit vir suus ut peteret a patre suo agrum. Quæ cum suspirasset sedens in asino, dixit ei Caleb: Quid habes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'At illa respondit: Da mihi benedictionem, quia terram arentem dedisti mihi: da et irriguam aquis. Dedit ergo ei Caleb irriguum superius, et irriguum inferius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Filii autem Cinæi cognati Moysi ascenderunt de civitate palmarum cum filiis Juda, in desertum sortis ejus, quod est ad meridiem Arad, et habitaverunt cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Abiit autem Judas cum Simeone fratre suo, et percusserunt simul Chananæum qui habitabat in Sephaath, et interfecerunt eum. Vocatumque est nomen urbis, Horma, id est, anathema.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Cepitque Judas Gazam cum finibus suis, et Ascalonem, atque Accaron cum terminis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Fuitque Dominus cum Juda, et montana possedit: nec potuit delere habitatores vallis, quia falcatis curribus abundabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Dederuntque Caleb Hebron, sicut dixerat Moyses, qui delevit ex ea tres filios Enac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Jebusæum autem habitatorem Jerusalem non deleverunt filii Benjamin: habitavitque Jebusæus cum filiis Benjamin in Jerusalem, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Domus quoque Joseph ascendit in Bethel, fuitque Dominus cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Nam cum obsiderent urbem, quæ prius Luza vocabatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'viderunt hominem egredientem de civitate, dixeruntque ad eum: Ostende nobis introitum civitatis, et faciemus tecum misericordiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Qui cum ostendisset eis, percusserunt urbem in ore gladii: hominem autem illum, et omnem cognationem ejus, dimiserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Qui dimissus, abiit in terram Hetthim, et ædificavit ibi civitatem, vocavitque eam Luzam: quæ ita appellatur usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manasses quoque non delevit Bethsan, et Thanac cum viculis suis, et habitatores Dor, et Jeblaam, et Mageddo cum viculis suis, cœpitque Chananæus habitare cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Postquam autem confortatus est Israël, fecit eos tributarios, et delere noluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ephraim etiam non interfecit Chananæum, qui habitabat in Gazer, sed habitavit cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon non delevit habitatores Cetron, et Naalol: sed habitavit Chananæus in medio ejus, factusque est ei tributarius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser quoque non delevit habitatores Accho, et Sidonis, Ahalab, et Achazib, et Helba, et Aphec, et Rohob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'habitavitque in medio Chananæi habitatoris illius terræ, nec interfecit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nephthali quoque non delevit habitatores Bethsames, et Bethanath: et habitavit inter Chananæum habitatorem terræ, fueruntque ei Bethsamitæ et Bethanitæ tributarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Arctavitque Amorrhæus filios Dan in monte, nec dedit eis locum ut ad planiora descenderent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'habitavitque in monte Hares, quod interpretatur testaceo, in Ajalon et Salebim. Et aggravata est manus domus Joseph, factusque est ei tributarius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Fuit autem terminus Amorrhæi ab ascensu Scorpionis, petra, et superiora loca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Ascenditque angelus Domini de Galgalis ad Locum flentium, et ait: Eduxi vos de \'gypto, et introduxi in terram, pro qua juravi patribus vestris: et pollicitus sum ut non facerem irritum pactum meum vobiscum in sempiternum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'ita dumtaxat ut non feriretis fœdus cum habitatoribus terræ hujus, sed aras eorum subverteretis: et noluistis audire vocem meam: cur hoc fecistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Quam ob rem nolui delere eos a facie vestra: ut habeatis hostes, et dii eorum sint vobis in ruinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Cumque loqueretur angelus Domini hæc verba ad omnes filios Israël, elevaverunt ipsi vocem suam, et fleverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Et vocatum est nomen loci illius, Locus flentium, sive lacrimarum: immolaveruntque ibi hostias Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Dimisit ergo Josue populum, et abierunt filii Israël unusquisque in possessionem suam, ut obtinerent eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'servieruntque Domino cunctis diebus ejus, et seniorum, qui longo post eum vixerunt tempore, et noverant omnia opera Domini quæ fecerat cum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Mortuus est autem Josue filius Nun, famulus Domini, centum et decem annorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'et sepelierunt eum in finibus possessionis suæ in Thamnathsare in monte Ephraim, a septentrionali plaga montis Gaas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Omnisque illa generatio congregata est ad patres suos: et surrexerunt alii, qui non noverant Dominum, et opera quæ fecerat cum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Feceruntque filii Israël malum in conspectu Domini, et servierunt Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Ac dimiserunt Dominum Deum patrum suorum, qui eduxerat eos de terra \'gypti, et secuti sunt deos alienos, deosque populorum, qui habitabant in circuitu eorum, et adoraverunt eos: et ad iracundiam concitaverunt Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'dimittentes eum, et servientes Baal et Astaroth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Iratusque Dominus contra Israël, tradidit eos in manus diripientium: qui ceperunt eos, et vendiderunt hostibus qui habitabant per gyrum: nec potuerunt resistere adversariis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'sed quocumque pergere voluissent, manus Domini super eos erat, sicut locutus est, et juravit eis, et vehementer afflicti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Suscitavitque Dominus judices, qui liberarent eos de vastantium manibus: sed nec eos audire voluerunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'fornicantes cum diis alienis, et adorantes eos. Cito deseruerunt viam, per quam ingressi fuerant patres eorum: et audientes mandata Domini, omnia fecere contraria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Cumque Dominus judices suscitaret, in diebus eorum flectebatur misericordia, et audiebat afflictorum gemitus, et liberabat eos de cæde vastantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Postquam autem mortuus esset judex, revertebantur, et multo faciebant pejora quam fecerant patres eorum, sequentes deos alienos, servientes eis, et adorantes illos. Non dimiserunt adinventiones suas, et viam durissimam per quam ambulare consueverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Iratusque est furor Domini in Israël, et ait: Quia irritum fecit gens ista pactum meum, quod pepigeram cum patribus eorum, et vocem meam audire contempsit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'et ego non delebo gentes, quas dimisit Josue, et mortuus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'ut in ipsis experiar Israël, utrum custodiant viam Domini, et ambulent in ea, sicut custodierunt patres eorum, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Dimisit ergo Dominus omnes nationes has, et cito subvertere noluit, nec tradidit in manus Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Hæ sunt gentes quas Dominus dereliquit, ut erudiret in eis Israëlem, et omnes qui non noverant bella Chananæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'ut postea discerent filii eorum certare cum hostibus, et habere consuetudinem præliandi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'quinque satrapas Philisthinorum, omnemque Chananæum, et Sidonium, atque Hevæum, qui habitabat in monte Libano, de monte Baal Hermon usque ad introitum Emath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Dimisitque eos, ut in ipsis experiretur Israëlem, utrum audiret mandata Domini quæ præceperat patribus eorum per manum Moysi, an non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Itaque filii Israël habitaverunt in medio Chananæi, et Hethæi, et Amorrhæi, et Pherezæi, et Hevæi, et Jebusæi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'et duxerunt uxores filias eorum, ipsique filias suas filiis eorum tradiderunt, et servierunt diis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Feceruntque malum in conspectu Domini, et obliti sunt Dei sui, servientes Baalim et Astaroth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Iratusque contra Israël Dominus, tradidit eos in manus Chusan Rasathaim regis Mesopotamiæ, servieruntque ei octo annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Et clamaverunt ad Dominum, qui suscitavit eis salvatorem, et liberavit eos, Othoniel videlicet filium Cenez, fratrem Caleb minorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'fuitque in eo spiritus Domini, et judicavit Israël. Egressusque est ad pugnam, et tradidit Dominus in manus ejus Chusan Rasathaim regem Syriæ, et oppressit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Quievitque terra quadraginta annis, et mortuus est Othoniel filius Cenez.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Addiderunt autem filii Israël facere malum in conspectu Domini: qui confortavit adversum eos Eglon regem Moab, quia fecerunt malum in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Et copulavit ei filios Ammon, et Amalec: abiitque et percussit Israël, atque possedit urbem palmarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Servieruntque filii Israël Eglon regi Moab decem et octo annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Et postea clamaverunt ad Dominum, qui suscitavit eis salvatorem vocabulo Aod, filium Gera, filii Jemini, qui utraque manu pro dextera utebatur. Miseruntque filii Israël per illum munera Eglon regi Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Qui fecit sibi gladium ancipitem, habentem in medio capulum longitudinis palmæ manus, et accinctus est eo subter sagum in dextro femore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Obtulitque munera Eglon regi Moab. Erat autem Eglon crassus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Cumque obtulisset ei munera, prosecutus est socios, qui cum eo venerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Et reversus de Galgalis, ubi erant idola, dixit ad regem: Verbum secretum habeo ad te, o rex. Et ille imperavit silentium: egressisque omnibus qui circa eum erant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'ingressus est Aod ad eum: sedebat autem in æstivo cœnaculo solus: dixitque: Verbum Dei habeo ad te. Qui statim surrexit de throno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Extenditque Aod sinistram manum, et tulit sicam de dextro femore suo, infixitque eam in ventre ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'tam valide, ut capulus sequeretur ferrum in vulnere, ac pinguissimo adipe stringeretur. Nec eduxit gladium, sed ita ut percusserat, reliquit in corpore: statimque per secreta naturæ alvi stercora proruperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Aod autem clausis diligentissime ostiis cœnaculi, et obfirmatis sera,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'per posticum egressus est. Servique regis ingressi viderunt clausas fores cœnaculi, atque dixerunt: Forsitan purgat alvum in æstivo cubiculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Expectantesque diu donec erubescerent, et videntes quod nullus aperiret, tulerunt clavem: et aperientes invenerunt dominum suum in terra jacentem mortuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Aod autem, dum illi turbarentur, effugit, et pertransiit locum idolorum, unde reversus fuerat. Venitque in Seirath:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'et statim insonuit buccina in monte Ephraim, descenderuntque cum eo filii Israël, ipso in fronte gradiente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Qui dixit ad eos: Sequimini me: tradidit enim Dominus inimicos nostros Moabitas in manus nostras. Descenderuntque post eum, et occupaverunt vada Jordanis quæ transmittunt in Moab: et non dimiserunt transire quemquam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'sed percusserunt Moabitas in tempore illo, circiter decem millia, omnes robustos et fortes viros. Nullus eorum evadere potuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Humiliatusque est Moab in die illo sub manu Israël: et quievit terra octoginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Post hunc fuit Samgar filius Anath, qui percussit de Philisthiim sexcentos viros vomere: et ipse quoque defendit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Addideruntque filii Israël facere malum in conspectu Domini post mortem Aod,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'et tradidit illos Dominus in manus Jabin regis Chanaan, qui regnavit in Asor: habuitque ducem exercitus sui nomine Sisaram, ipse autem habitabat in Haroseth gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Clamaveruntque filii Israël ad Dominum: nongentos enim habebat falcatos currus, et per viginti annos vehementer oppresserat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Erat autem Debbora prophetis uxor Lapidoth, quæ judicabat populum in illo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Et sedebat sub palma, quæ nomine illius vocabatur, inter Rama et Bethel in monte Ephraim: ascendebantque ad eam filii Israël in omne judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Quæ misit et vocavit Barac filium Abinoëm de Cedes Nephthali: dixitque ad eum: Præcepit tibi Dominus Deus Israël: Vade, et duc exercitum in montem Thabor, tollesque tecum decem millia pugnatorum de filiis Nephthali, et de filiis Zabulon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'ego autem adducam ad te in loco torrentis Cison, Sisaram principem exercitus Jabin, et currus ejus, atque omnem multitudinem, et tradam eos in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Dixitque ad eam Barac: Si venis mecum, vadam: si nolueris venire mecum, non pergam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Quæ dixit ad eum: Ibo quidem tecum, sed in hac vice victoria non reputabitur tibi, quia in manu mulieris tradetur Sisara. Surrexit itaque Debbora, et perrexit cum Barac in Cedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Qui, accitis Zabulon et Nephthali, ascendit cum decem millibus pugnatorum, habens Debboram in comitatu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Haber autem Cinæus recesserat quondam a ceteris Cinæis fratribus suis, filiis Hobab cognati Moysi: et tetenderat tabernacula usque ad vallem, quæ vocatur Sennim, et erat juxta Cedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Nuntiatumque est Sisaræ quod ascendisset Barac filius Abinoëm in montem Thabor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'et congregavit nongentos falcatos currus, et omnem exercitum de Haroseth gentium ad torrentem Cison.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Dixitque Debbora ad Barac: Surge, hæc est enim dies, in qua tradidit Dominus Sisaram in manus tuas: en ipse ductor est tuus. Descendit itaque Barac de monte Thabor, et decem millia pugnatorum cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Perterruitque Dominus Sisaram, et omnes currus ejus, universamque multitudinem in ore gladii ad conspectum Barac: in tantum, ut Sisara de curru desiliens, pedibus fugeret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'et Barac persequeretur fugientes currus, et exercitum usque ad Haroseth gentium, et omnis hostium multitudo usque ad internecionem caderet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisara autem fugiens pervenit ad tentorium Jahel uxoris Haber Cinæi. Erat enim pax inter Jabin regem Asor, et domum Haber Cinæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Egressa igitur Jahel in occursum Sisaræ, dixit ad eum: Intra ad me, domine mi: intra, ne timeas. Qui ingressus tabernaculum ejus, et opertus ab ea pallio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'dixit ad eam: Da mihi, obsecro, paululum aquæ, quia sitio valde. Quæ aperuit utrem lactis, et dedit ei bibere, et operuit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Dixitque Sisara ad eam: Sta ante ostium tabernaculi: et cum venerit aliquis interrogans te, et dicens: Numquid hic est aliquis? respondebis: Nullus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Tulit itaque Jahel uxor Haber clavum tabernaculi, assumens pariter et malleum: et ingressa abscondite et cum silentio, posuit supra tempus capitis ejus clavum, percussumque malleo defixit in cerebrum usque ad terram: qui soporem morti consocians defecit, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Et ecce Barac sequens Sisaram veniebat: egressaque Jahel in occursum ejus, dixit ei: Veni, et ostendam tibi virum quem quæris. Qui cum intrasset ad eam, vidit Sisaram jacentem mortuum, et clavum infixum in tempore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Humiliavit ergo Deus in die illo Jabin regem Chanaan coram filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'qui crescebant quotidie, et forti manu opprimebant Jabin regem Chanaan, donec delerent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Cecineruntque Debbora et Barac filius Abinoëm in illo die, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Qui sponte obtulistis de Israël animas vestras ad periculum, benedicite Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Audite, reges; auribus percipite, principes: ego sum, ego sum, quæ Domino canam, psallam Domino Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Domine, cum exires de Seir, et transires per regiones Edom, terra mota est, cælique ac nubes distillaverunt aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Montes fluxerunt a facie Domini, et Sinai a facie Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'In diebus Samgar filii Anath, in diebus Jahel quieverunt semitæ: et qui ingrediebantur per eas, ambulaverunt per calles devios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Cessaverunt fortes in Israël, et quieverunt: donec surgeret Debbora, surgeret mater in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Nova bella elegit Dominus, et portas hostium ipse subvertit: clypeus et hasta si apparuerint in quadraginta millibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Cor meum diligit principes Israël: qui propria voluntate obtulistis vos discrimini, benedicite Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Qui ascenditis super nitentes asinos, et sedetis in judicio, et ambulatis in via, loquimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Ubi collisi sunt currus, et hostium suffocatus est exercitus, ibi narrentur justitiæ Domini, et clementia in fortes Israël: tunc descendit populus Domini ad portas, et obtinuit principatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Surge, surge Debbora; surge, surge, et loquere canticum: surge Barac, et apprehende captivos tuos, fili Abinoëm.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Salvatæ sunt reliquiæ populi: Dominus in fortibus dimicavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Ex Ephraim delevit eos in Amalec, et post eum ex Benjamin in populos tuos, o Amalec: de Machir principes descenderunt, et de Zabulon qui exercitum ducerent ad bellandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Duces Issachar fuere cum Debbora, et Barac vestigia sunt secuti, qui quasi in præceps ac barathrum se discrimini dedit: diviso contra se Ruben, magnanimorum reperta est contentio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Quare habitas inter duos terminos, ut audias sibilos gregum? diviso contra se Ruben, magnanimorum reperta est contentio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad trans Jordanem quiescebat, et Dan vacabat navibus: Aser habitabat in littore maris, et in portubus morabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulon vero et Nephthali obtulerunt animas suas morti in regione Merome.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Venerunt reges et pugnaverunt: pugnaverunt reges Chanaan in Thanach juxta aquas Mageddo, et tamen nihil tulere prædantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'De cælo dimicatum est contra eos: stellæ manentes in ordine et cursu suo, adversus Sisaram pugnaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Torrens Cison traxit cadavera eorum, torrens Cadumim, torrens Cison: conculca, anima mea, robustos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Ungulæ equorum ceciderunt, fugientibus impetu, et per præceps ruentibus fortissimis hostium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Maledicite terræ Meroz, dixit angelus Domini: maledicite habitatoribus ejus, quia non venerunt ad auxilium Domini, in adjutorium fortissimorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Benedicta inter mulieres Jahel uxor Haber Cinæi, et benedicatur in tabernaculo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Aquam petenti lac dedit, et in phiala principum obtulit butyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Sinistram manum misit ad clavum, et dexteram ad fabrorum malleos. Percussitque Sisaram quærens in capite vulneri locum, et tempus valide perforans:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'inter pedes ejus ruit; defecit, et mortuus est: volvebatur ante pedes ejus, et jacebat exanimis et miserabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Per fenestram respiciens, ululabat mater ejus: et de cœnaculo loquebatur: Cur moratur regredi currus ejus? quare tardaverunt pedes quadrigarum illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Una sapientior ceteris uxoribus ejus, hæc socrui verba respondit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Forsitan nunc dividit spolia, et pulcherrima feminarum eligitur ei: vestes diversorum colorum Sisaræ traduntur in prædam, et supellex varia ad ornanda colla congeritur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Sic pereant omnes inimici tui, Domine: qui autem diligunt te, sicut sol in ortu suo splendet, ita rutilent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 32, 'Quievitque terra per quadraginta annos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Fecerunt autem filii Israël malum in conspectu Domini: qui tradidit illos in manu Madian septem annis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'et oppressi sunt valde ab eis. Feceruntque sibi antra et speluncas in montibus, et munitissima ad repugnandum loca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Cumque sevisset Israël, ascendebat Madian et Amalec, ceterique orientalium nationum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'et apud eos figentes tentoria, sicut erant in herbis cuncta vastabant usque ad introitum Gazæ: nihilque omnino ad vitam pertinens relinquebant in Israël, non oves, non boves, non asinos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Ipsi enim et universi greges eorum veniebant cum tabernaculis suis, et instar locustarum universa complebant, innumera multitudo hominum et camelorum, quidquid tetigerant devastantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Humiliatusque est Israël valde in conspectu Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Et clamavit ad Dominum postulans auxilium contra Madianitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Qui misit ad eos virum prophetam, et locutus est: Hæc dicit Dominus Deus Israël: Ego vos feci conscendere de \'gypto, et eduxi vos de domo servitutis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'et liberavi de manu \'gyptiorum, et omnium inimicorum qui affligebant vos: ejecique eos ad introitum vestrum, et tradidi vobis terram eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Et dixi: Ego Dominus Deus vester: ne timeatis deos Amorrhæorum, in quorum terra habitatis. Et noluistis audire vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Venit autem angelus Domini, et sedit sub quercu, quæ erat in Ephra, et pertinebat ad Joas patrem familiæ Ezri. Cumque Gedeon filius ejus excuteret atque purgaret frumenta in torculari, ut fugeret Madian,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'apparuit ei angelus Domini, et ait: Dominus tecum, virorum fortissime.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Dixitque ei Gedeon: Obsecro, mi domine, si Dominus nobiscum est, cur apprehenderunt nos hæc omnia? ubi sunt mirabilia ejus, quæ narraverunt patres nostri, atque dixerunt: De \'gypto eduxit nos Dominus? nunc autem dereliquit nos Dominus, et tradidit in manu Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Respexitque ad eum Dominus, et ait: Vade in hac fortitudine tua, et liberabis Israël de manu Madian: scito quod miserim te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Qui respondens ait: Obsecro, mi domine, in quo liberabo Israël? ecce familia mea infima est in Manasse, et ego minimus in domo patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Dixitque ei Dominus: Ego ero tecum: et percuties Madian quasi unum virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Et ille: Si inveni, inquit, gratiam coram te, da mihi signum quod tu sis qui loqueris ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'nec recedas hinc, donec revertar ad te, portans sacrificium, et offerens tibi. Qui respondit: Ego præstolabor adventum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Ingressus est itaque Gedeon, et coxit hædum, et de farinæ modio azymos panes: carnesque ponens in canistro, et jus carnium mittens in ollam, tulit omnia sub quercu, et obtulit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Cui dixit angelus Domini: Tolle carnes et azymos panes, et pone supra petram illam, et jus desuper funde. Cumque fecisset ita,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'extendit angelus Domini summitatem virgæ, quam tenebat in manu, et tetigit carnes et panes azymos: ascenditque ignis de petra, et carnes azymosque panes consumpsit: angelus autem Domini evanuit ex oculis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Vidensque Gedeon quod esset angelus Domini, ait: Heu mi Domine Deus: quia vidi angelum Domini facie ad faciem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Dixitque ei Dominus: Pax tecum: ne timeas, non morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, '\'dificavit ergo ibi Gedeon altare Domino, vocavitque illud, Domini pax, usque in præsentem diem. Cumque adhuc esset in Ephra, quæ est familiæ Ezri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'nocte illa dixit Dominus ad eum: Tolle taurum patris tui, et alterum taurum annorum septem, destruesque aram Baal, quæ est patris tui, et nemus, quod circa aram est, succide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Et ædificabis altare Domino Deo tuo in summitate petræ hujus, super quam ante sacrificium posuisti: tollesque taurum secundum, et offeres holocaustum super struem lignorum, quæ de nemore succideris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Assumptis ergo Gedeon decem viris de servis suis, fecit sicut præceperat ei Dominus. Timens autem domum patris sui, et homines illius civitatis, per diem noluit id facere, sed omnia nocte complevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Cumque surrexissent viri oppidi ejus mane, viderunt destructam aram Baal, lucumque succisum, et taurum alterum impositum super altare, quod tunc ædificatum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Dixeruntque ad invicem: Quis hoc fecit? Cumque perquirerent auctorem facti, dictum est: Gedeon filius Joas fecit hæc omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Et dixerunt ad Joas: Produc filium tuum huc, ut moriatur: quia destruxit aram Baal, et succidit nemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Quibus ille respondit: Numquid ultores estis Baal, ut pugnetis pro eo? qui adversarius est ejus, moriatur antequam lux crastina veniat: si deus est, vindicet se de eo, qui suffodit aram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Ex illo die vocatus est Gedeon Jerobaal, eo quod dixisset Joas: Ulciscatur se de eo Baal, qui suffodit aram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Igitur omnis Madian, et Amalec, et orientales populi, congregati sunt simul: et transeuntes Jordanem, castrametati sunt in valle Jezraël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Spiritus autem Domini induit Gedeon, qui clangens buccina convocavit domum Abiezer, ut sequeretur se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Misitque nuntios in universum Manassen, qui et ipse secutus est eum: et alios nuntios in Aser et Zabulon et Nephthali, qui occurrerunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Dixitque Gedeon ad Deum: Si salvum facis per manum meam Israël, sicut locutus es,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'ponam hoc vellus lanæ in area: si ros in solo vellere fuerit, et in omni terra siccitas, sciam quod per manum meam, sicut locutus es, liberabis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Factumque est ita. Et de nocte consurgens expresso vellere, concham rore implevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Dixitque rursus ad Deum: Ne irascatur furor tuus contra me si adhuc semel tentavero, signum quærens in vellere. Oro ut solum vellus siccum sit, et omnis terra rore madens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Fecitque Deus nocte illa ut postulaverat: et fuit siccitas in solo vellere, et ros in omni terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Igitur Jerobaal qui et Gedeon, de nocte consurgens, et omnis populus cum eo, venit ad fontem qui vocatur Harad. Erant autem castra Madian in valle ad septentrionalem plagam collis excelsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Dixitque Dominus ad Gedeon: Multus tecum est populus, nec tradetur Madian in manus ejus: ne glorietur contra me Israël, et dicat: Meis viribus liberatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Loquere ad populum, et cunctis audientibus prædica: Qui formidolosus et timidus est, revertatur. Recesseruntque de monte Galaad, et reversi sunt de populo viginti duo millia virorum, et tantum decem millia remanserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Dixitque Dominus ad Gedeon: Adhuc populus multus est: duc eos ad aquas et ibi probabo illos: et de quo dixero tibi ut tecum vadat, ipse pergat; quem ire prohibuero, revertatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Cumque descendisset populus ad aquas, dixit Dominus ad Gedeon: Qui lingua lambuerint aquas, sicut solent canes lambere, separabis eos seorsum: qui autem curvatis genibus biberint, in altera parte erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Fuit itaque numerus eorum qui manu ad os projiciente lambuerunt aquas, trecenti viri: omnis autem reliqua multitudo flexo poplite biberat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Et ait Dominus ad Gedeon: In trecentis viris qui lambuerunt aquas, liberabo vos, et tradam in manu tua Madian: omnis autem reliqua multitudo revertatur in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Sumptis itaque pro numero cibariis et tubis, omnem reliquam multitudinem abire præcepit ad tabernacula sua: et ipse cum trecentis viris se certamini dedit. Castra autem Madian erant subter in valle.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Eadem nocte dixit Dominus ad eum: Surge, et descende in castra: quia tradidi eos in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Sin autem solus ire formidas, descendat tecum Phara puer tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Et cum audieris quid loquantur, tunc confortabuntur manus tuæ, et securior ad hostium castra descendes. Descendit ergo ipse et Phara puer ejus in partem castrorum, ubi erant armatorum vigiliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Madian autem et Amalec, et omnes orientales populi, fusi jacebant in valle, ut locustarum multitudo: cameli quoque innumerabiles erant, sicut arena quæ jacet in littore maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Cumque venisset Gedeon, narrabat aliquis somnium proximo suo: et in hunc modum referebat quod viderat: Vidi somnium, et videbatur mihi quasi subcinericius panis ex hordeo volvi, et in castra Madian descendere: cumque pervenisset ad tabernaculum, percussit illud, atque subvertit, et terræ funditus coæquavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Respondit is, cui loquebatur: Non est hoc aliud, nisi gladius Gedeonis filii Joas viri Israëlitæ: tradidit enim Dominus in manus ejus Madian, et omnia castra ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Cumque audisset Gedeon somnium, et interpretationem ejus, adoravit: et reversus est ad castra Israël, et ait: Surgite, tradidit enim Dominus in manus nostras castra Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Divisitque trecentos viros in tres partes, et dedit tubas in manibus eorum, lagenasque vacuas, ac lampades in medio lagenarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Et dixit ad eos: Quod me facere videritis, hoc facite: ingrediar partem castrorum, et quod fecero, sectamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Quando personuerit tuba in manu mea, vos quoque per castrorum circuitum clangite, et conclamate: Domino et Gedeoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Ingressusque est Gedeon, et trecenti viri qui erant cum eo, in partem castrorum, incipientibus vigiliis noctis mediæ: et custodibus suscitatis, cœperunt buccinis clangere, et complodere inter se lagenas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Cumque per gyrum castrorum in tribus personarent locis, et hydrias confregissent, tenuerunt sinistris manibus lampades, et dextris sonantes tubas, clamaveruntque: Gladius Domini et Gedeonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'stantes singuli in loco suo per circuitum castrorum hostilium. Omnia itaque castra turbata sunt, et vociferantes ululantesque fugerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'et nihilominus insistebant trecenti viri buccinis personantes. Immisitque Dominus gladium omnibus castris, et mutua se cæde truncabant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'fugientes usque ad Bethsetta, et crepidinem Abelmehula in Tebbath. Conclamantes autem viri Israël de Nephthali, et Aser, et omni Manasse, persequebantur Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Misitque Gedeon nuntios in omnem montem Ephraim, dicens: Descendite in occursum Madian, et occupate aquas usque Bethbera atque Jordanem. Clamavitque omnis Ephraim, et præoccupavit aquas atque Jordanem usque Bethbera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Apprehensosque duos viros Madian, Oreb et Zeb, interfecit Oreb in petra Oreb, Zeb vero in torculari Zeb. Et persecuti sunt Madian, capita Oreb et Zeb portantes ad Gedeon trans fluenta Jordanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Dixeruntque ad eum viri Ephraim: Quid est hoc quod facere voluisti, ut nos non vocares, cum ad pugnam pergeres contra Madian? jurgantes fortiter, et prope vim inferentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Quibus ille respondit: Quod enim tale facere potui, quale vos fecistis? nonne melior est racemus Ephraim, vindemiis Abiezer?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'In manus vestras Dominus tradidit principes Madian, Oreb et Zeb: quid tale facere potui, quale vos fecistis? Quod cum locutus esset, requievit spiritus eorum, quo tumebant contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Cumque venisset Gedeon ad Jordanem, transivit eum cum trecentis viris, qui secum erant: et præ lassitudine, fugientes persequi non poterant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Dixitque ad viros Soccoth: Date, obsecro, panes populo qui mecum est, quia valde defecerunt: ut possimus persequi Zebee et Salmana reges Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Responderunt principes Soccoth: Forsitan palmæ manuum Zebee et Salmana in manu tua sunt, et idcirco postulas ut demus exercitui tuo panes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Quibus ille ait: Cum ergo tradiderit Dominus Zebee et Salmana in manus meas, conteram carnes vestras cum spinis tribulisque deserti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Et inde conscendens, venit in Phanuel: locutusque est ad viros loci illius similia. Cui et illi responderunt, sicut responderant viri Soccoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Dixit itaque et eis: Cum reversus fuero victor in pace, destruam turrim hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebee autem et Salmana requiescebant cum omni exercitu suo. Quindecim enim millia viri remanserant ex omnibus turmis orientalium populorum, cæsis centum viginti millibus bellatorum educentium gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Ascendensque Gedeon per viam eorum, qui in tabernaculis morabantur, ad orientalem partem Nobe et Jegbaa, percussit castra hostium, qui securi erant, et nihil adversi suspicabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Fugeruntque Zebee et Salmana, quos persequens Gedeon comprehendit, turbato omni exercitu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Revertensque de bello ante solis ortum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'apprehendit puerum de viris Soccoth: interrogavitque eum nomina principum et seniorum Soccoth, et descripsit septuaginta septem viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Venitque ad Soccoth, et dixit eis: En Zebee et Salmana, super quibus exprobrastis mihi, dicentes: Forsitan manus Zebee et Salmana in manibus tuis sunt, et idcirco postulas ut demus viris, qui lassi sunt et defecerunt, panes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Tulit ergo seniores civitatis et spinas deserti ac tribulos, et contrivit cum eis atque comminuit viros Soccoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Turrim quoque Phanuel subvertit, occisis habitatoribus civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Dixitque ad Zebee et Salmana: Quales fuerunt viri, quos occidistis in Thabor? Qui responderunt: Similes tui, et unus ex eis quasi filius regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Quibus ille respondit: Fratres mei fuerunt, filii matris meæ. Vivit Dominus, quia si servassetis eos, non vos occiderem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Dixitque Jether primogenito suo: Surge, et interfice eos. Qui non eduxit gladium: timebat enim, quia adhuc puer erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Dixeruntque Zebee et Salmana: Tu surge, et irrue in nos: quia juxta ætatem robur est hominis. Surrexit Gedeon, et interfecit Zebee et Salmana: et tulit ornamenta ac bullas quibus colla regalium camelorum decorari solent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Dixeruntque omnes viri Israël ad Gedeon: Dominare nostri tu, et filius tuus, et filius filii tui: quia liberasti nos de manu Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Quibus ille ait: Non dominabor vestri, nec dominabitur in vos filius meus, sed dominabitur vobis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Dixitque ad eos: Unam petitionem postulo a vobis: date mihi inaures ex præda vestra. Inaures enim aureas Ismaëlitæ habere consueverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Qui responderunt: Libentissime dabimus. Expandentesque super terram pallium, projecerunt in eo inaures de præda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'et fuit pondus postulatarum inaurium, mille septingenti auri sicli, absque ornamentis, et monilibus, et veste purpurea, quibus reges Madian uti soliti erant, et præter torques aureas camelorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Fecitque ex eo Gedeon ephod, et posuit illud in civitate sua Ephra. Fornicatusque est omnis Israël in eo, et factum est Gedeoni et omni domui ejus in ruinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Humiliatus est autem Madian coram filiis Israël, nec potuerunt ultra cervices elevare: sed quievit terra per quadraginta annos, quibus Gedeon præfuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Abiit itaque Jerobaal filius Joas, et habitavit in domo sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'habuitque septuaginta filios, qui egressi sunt de femore ejus: eo quod plures haberet uxores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Concubina autem illius, quam habebat in Sichem, genuit ei filium nomine Abimelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Mortuusque est Gedeon filius Joas in senectute bona, et sepultus est in sepulchro Joas patris sui in Ephra de familia Ezri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Postquam autem mortuus est Gedeon, aversi sunt filii Israël, et fornicati sunt cum Baalim. Percusseruntque cum Baal fœdus, ut esset eis in deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'nec recordati sunt Domini Dei sui, qui eruit eos de manibus inimicorum suorum omnium per circuitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'nec fecerunt misericordiam cum domo Jerobaal Gedeon, juxta omnia bona quæ fecerat Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abiit autem Abimelech filius Jerobaal in Sichem ad fratres matris suæ, et locutus est ad eos, et ad omnem cognationem domus patris matris suæ, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Loquimini ad omnes viros Sichem: Quid vobis est melius, ut dominentur vestri septuaginta viri omnes filii Jerobaal, an ut dominetur unus vir? simulque considerate quod os vestrum et caro vestra sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Locutique sunt fratres matris ejus de eo ad omnes viros Sichem universos sermones istos, et inclinaverunt cor eorum post Abimelech, dicentes: Frater noster est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Dederuntque illi septuaginta pondo argenti de fano Baalberit. Qui conduxit sibi ex eo viros inopes et vagos, secutique sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Et venit in domum patris sui in Ephra, et occidit fratres suos filios Jerobaal, septuaginta viros super lapidem unum: remansitque Joatham filius Jerobaal minimus, et absconditus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Congregati sunt autem omnes viri Sichem, et universæ familiæ urbis Mello: abieruntque et constituerunt regem Abimelech, juxta quercum quæ stabat in Sichem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Quod cum nuntiatum esset Joatham, ivit, et stetit in vertice montis Garizim: elevataque voce, clamavit, et dixit: Audite me, viri Sichem; ita audiat vos Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Ierunt ligna, ut ungerent super se regem: dixeruntque olivæ: Impera nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Quæ respondit: Numquid possum deserere pinguedinem meam, qua et dii utuntur et homines, et venire ut inter ligna promovear?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Dixeruntque ligna ad arborem ficum: Veni, et super nos regnum accipe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Quæ respondit eis: Numquid possum deserere dulcedinem meam, fructusque suavissimos, et ire ut inter cetera ligna promovear?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Locutaque sunt ligna ad vitem: Veni, et impera nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Quæ respondit eis: Numquid possum deserere vinum meum, quod lætificat Deum et homines, et inter ligna cetera promoveri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Dixeruntque omnia ligna ad rhamnum: Veni, et impera super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Quæ respondit eis: Si vere me regem vobis constituitis, venite, et sub umbra mea requiescite: si autem non vultis, egrediatur ignis de rhamno, et devoret cedros Libani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Nunc igitur, si recte et absque peccato constituistis super vos regem Abimelech, et bene egistis cum Jerobaal, et cum domo ejus, et reddidistis vicem beneficiis ejus, qui pugnavit pro vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'et animam suam dedit periculis, ut erueret vos de manu Madian,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'qui nunc surrexistis contra domum patris mei, et interfecistis filios ejus septuaginta viros super unum lapidem, et constituistis regem Abimelech filium ancillæ ejus super habitatores Sichem, eo quod frater vester sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'si ergo recte et absque vitio egistis cum Jerobaal et domo ejus, hodie lætamini in Abimelech, et ille lætetur in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Sin autem perverse: egrediatur ignis ex eo, et consumat habitatores Sichem, et oppidum Mello: egrediaturque ignis de viris Sichem, et de oppido Mello, et devoret Abimelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Quæ cum dixisset, fugit, et abiit in Bera: habitavitque ibi ob metum Abimelech fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Regnavit itaque Abimelech super Israël tribus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Misitque Dominus spiritum pessimum inter Abimelech et habitatores Sichem: qui cœperunt eum detestari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'et scelus interfectionis septuaginta filiorum Jerobaal, et effusionem sanguinis eorum conferre in Abimelech fratrem suum, et in ceteros Sichimorum principes, qui eum adjuverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Posueruntque insidias adversus eum in summitate montium: et dum illius præstolabantur adventum, exercebant latrocinia, agentes prædas de prætereuntibus: nuntiatumque est Abimelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Venit autem Gaal filius Obed cum fratribus suis, et transivit in Sichimam. Ad cujus adventum erecti habitatores Sichem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'egressi sunt in agros, vastantes vineas, uvasque calcantes: et factis cantantium choris, ingressi sunt fanum dei sui, et inter epulas et pocula maledicebant Abimelech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'clamante Gaal filio Obed: Quis est Abimelech, et quæ est Sichem, ut serviamus ei? numquid non est filius Jerobaal, et constituit principem Zebul servum suum super viros Emor patris Sichem? cur ergo serviemus ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'utinam daret aliquis populum istum sub manu mea, ut auferrem de medio Abimelech. Dictumque est Abimelech: Congrega exercitus multitudinem, et veni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Zebul enim princeps civitatis, auditis sermonibus Gaal filii Obed, iratus est valde,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'et misit clam ad Abimelech nuntios, dicens: Ecce Gaal filius Obed venit in Sichimam cum fratribus suis, et oppugnat adversum te civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Surge itaque nocte cum populo qui tecum est, et latita in agro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'et primo mane, oriente sole, irrue super civitatem. Illo autem egrediente adversum te cum populo suo, fac ei quod potueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Surrexit itaque Abimelech cum omni exercitu suo nocte, et tetendit insidias juxta Sichimam in quatuor locis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Egressusque est Gaal filius Obed, et stetit in introitu portæ civitatis. Surrexit autem Abimelech, et omnis exercitus cum eo, de insidiarum loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Cumque vidisset populum Gaal, dixit ad Zebul: Ecce de montibus multitudo descendit. Cui ille respondit: Umbras montium vides quasi capita hominum, et hoc errore deciperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Rursumque Gaal ait: Ecce populus de umbilico terræ descendit, et unus cuneus venit per viam quæ respicit quercum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Cui dixit Zebul: Ubi est nunc os tuum, quo loquebaris: Quis est Abimelech ut serviamus ei? nonne hic populus est, quem despiciebas? egredere, et pugna contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Abiit ergo Gaal, spectante Sichimorum populo, et pugnavit contra Abimelech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'qui persecutus est eum fugientem, et in urbem compulit: cecideruntque ex parte ejus plurimi, usque ad portam civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Et Abimelech sedit in Ruma: Zebul autem Gaal et socios ejus expulit de urbe, nec in ea passus est commorari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Sequenti ergo die, egressus est populus in campum. Quod cum nuntiatum esset Abimelech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'tulit exercitum suum, et divisit in tres turmas, tendens insidias in agris. Vidensque quod egrederetur populus de civitate, surrexit, et irruit in eos');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'cum cuneo suo, oppugnans et obsidens civitatem: duæ autem turmæ palantes per campum adversarios persequebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Porro Abimelech omni die illo oppugnabat urbem: quam cepit, interfectis habitatoribus ejus, ipsaque destructa, ita ut sal in ea dispergeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Quod cum audissent qui habitabant in turre Sichimorum, ingressi sunt fanum dei sui Berith, ubi fœdus cum eo pepigerant, et ex eo locus nomen acceperat: qui erat munitus valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Abimelech quoque audiens viros turris Sichimorum pariter conglobatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'ascendit in montem Selmon cum omni populo suo: et arrepta securi, præcidit arboris ramum, impositumque ferens humero, dixit ad socios: Quod me videtis facere, cito facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Igitur certatim ramos de arboribus præcidentes, sequebantur ducem. Qui circumdantes præsidium, succenderunt: atque ita factum est, ut fumo et igne mille homines necarentur, viri pariter et mulieres, habitatorum turris Sichem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Abimelech autem inde proficiscens venit ad oppidum Thebes, quod circumdans obsidebat exercitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Erat autem turris excelsa in media civitate, ad quam confugerant simul viri ac mulieres, et omnes principes civitatis, clausa firmissime janua, et super turris tectum stantes per propugnacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Accedensque Abimelech juxta turrim, pugnabat fortiter: et appropinquans ostio, ignem supponere nitebatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'et ecce una mulier fragmen molæ desuper jaciens, illisit capiti Abimelech, et confregit cerebrum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Qui vocavit cito armigerum suum, et ait ad eum: Evagina gladium tuum, et percute me, ne forte dicatur quod a femina interfectus sim. Qui jussa perficiens, interfecit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Illoque mortuo, omnes qui cum eo erant de Israël, reversi sunt in sedes suas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'et reddidit Deus malum quod fecerat Abimelech contra patrem suum, interfectis septuaginta fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Sichimitis quoque quod operati erant, retributum est, et venit super eos maledictio Joatham filii Jerobaal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Post Abimelech surrexit dux in Israël Thola filius Phua patrui Abimelech, vir de Issachar, qui habitavit in Samir montis Ephraim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'et judicavit Israëlem viginti et tribus annis, mortuusque est, ac sepultus in Samir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Huic successit Jair Galaadites, qui judicavit Israël per viginti et duos annos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'habens triginta filios sedentes super triginta pullos asinarum, et principes triginta civitatum, quæ ex nomine ejus sunt appellatæ Havoth Jair, id est, oppida Jair, usque in præsentem diem, in terra Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Mortuusque est Jair, ac sepultus in loco cui est vocabulum Camon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Filii autem Israël peccatis veteribus jungentes nova, fecerunt malum in conspectu Domini, et servierunt idolis, Baalim et Astaroth, et diis Syriæ ac Sidonis et Moab et filiorum Ammon et Philisthiim: dimiseruntque Dominum, et non coluerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Contra quos Dominus iratus, tradidit eos in manus Philisthiim et filiorum Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Afflictique sunt, et vehementer oppressi per annos decem et octo, omnes qui habitabant trans Jordanem in terra Amorrhæi, qui est in Galaad:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'in tantum ut filii Ammon, Jordane transmisso, vastarent Judam et Benjamin et Ephraim: afflictusque est Israël nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Et clamantes ad Dominum, dixerunt: Peccavimus tibi, quia dereliquimus Dominum Deum nostrum, et servivimus Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Quibus locutus est Dominus: Numquid non \'gyptii et Amorrhæi, filiique Ammon et Philisthiim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Sidonii quoque et Amalec et Chanaan oppresserunt vos, et clamastis ad me, et erui vos de manu eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Et tamen reliquistis me, et coluistis deos alienos: idcirco non addam ut ultra vos liberem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'ite, et invocate deos quos elegistis: ipsi vos liberent in tempore angustiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Dixeruntque filii Israël ad Dominum: Peccavimus, redde tu nobis quidquid tibi placet: tantum nunc libera nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Quæ dicentes, omnia de finibus suis alienorum deorum idola projecerunt, et servierunt Domino Deo: qui doluit super miseriis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Itaque filii Ammon conclamantes in Galaad fixere tentoria, contra quos congregati filii Israël in Maspha castrametati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Dixeruntque principes Galaad singuli ad proximos suos: Qui primus ex nobis contra filios Ammon cœperit dimicare, erit dux populi Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Fuit illo tempore Jephte Galaadites vir fortissimus atque pugnator, filius mulieris meretricis, qui natus est de Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Habuit autem Galaad uxorem, de qua suscepit filios: qui postquam creverant, ejecerunt Jephte, dicentes: Hæres in domo patris nostri esse non poteris, quia de altera matre natus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Quos ille fugiens atque devitans, habitavit in terra Tob: congregatique sunt ad eum viri inopes, et latrocinantes, et quasi principem sequebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'In illis diebus pugnabant filii Ammon contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Quibus acriter instantibus perrexerunt majores natu de Galaad, ut tollerent in auxilium sui Jephte de terra Tob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'dixeruntque ad eum: Veni et esto princeps noster, et pugna contra filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Quibus ille respondit: Nonne vos estis, qui odistis me, et ejecistis de domo patris mei? et nunc venistis ad me necessitate compulsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Dixeruntque principes Galaad ad Jephte: Ob hanc igitur causam nunc ad te venimus, ut proficiscaris nobiscum, et pugnes contra filios Ammon, sisque dux omnium qui habitant in Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jephte quoque dixit eis: Si vere venistis ad me, ut pugnem pro vobis contra filios Ammon, tradideritque eos Dominus in manus meas, ego ero vester princeps?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Qui responderunt ei: Dominus, qui hæc audit, ipse mediator ac testis est quod nostra promissa faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Abiit itaque Jephte cum principibus Galaad, fecitque eum omnis populus principem sui. Locutusque est Jephte omnes sermones suos coram Domino in Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Et misit nuntios ad regem filiorum Ammon, qui ex persona sua dicerent: Quid mihi et tibi est, quia venisti contra me, ut vastares terram meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Quibus ille respondit: Quia tulit Israël terram meam, quando ascendit de \'gypto, a finibus Arnon usque Jaboc atque Jordanem: nunc ergo cum pace redde mihi eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Per quos rursum mandavit Jephte, et imperavit eis ut dicerent regi Ammon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Hæc dicit Jephte: Non tulit Israël terram Moab, nec terram filiorum Ammon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'sed quando de \'gypto conscenderunt, ambulavit per solitudinem usque ad mare Rubrum, et venit in Cades.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Misitque nuntios ad regem Edom, dicens: Dimitte me ut transeam per terram tuam. Qui noluit acquiescere precibus ejus. Misit quoque ad regem Moab, qui et ipse transitum præbere contempsit. Mansit itaque in Cades,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'et circuivit ex latere terram Edom et terram Moab: venitque contra orientalem plagam terræ Moab, et castrametatus est trans Arnon: nec voluit intrare terminos Moab. (Arnon quippe confinium est terræ Moab.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Misit itaque Israël nuntios ad Sehon regem Amorrhæorum, qui habitabat in Hesebon, et dixerunt ei: Dimitte ut transeam per terram tuam usque ad fluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Qui et ipse Israël verba despiciens, non dimisit eum transire per terminos suos: sed infinita multitudine congregata, egressus est contra eum in Jasa, et fortiter resistebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Tradiditque eum Dominus in manus Israël cum omni exercitu suo: qui percussit eum, et possedit omnem terram Amorrhæi habitatoris regionis illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'et universos fines ejus, de Arnon usque Jaboc, et de solitudine usque ad Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Dominus ergo Deus Israël subvertit Amorrhæum, pugnante contra illum populo suo Israël, et tu nunc vis possidere terram ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'nonne ea quæ possidet Chamos deus tuus, tibi jure debentur? quæ autem Dominus Deus noster victor obtinuit, in nostram cedent possessionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'nisi forte melior es Balac filio Sephor rege Moab; aut docere potes, quod jurgatus sit contra Israël, et pugnaverit contra eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'quando habitavit in Hesebon et viculis ejus, et in Aroër et villis illius, vel in cunctis civitatibus juxta Jordanem, per trecentos annos. Quare tanto tempore nihil super hac repetitione tentastis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Igitur non ego pecco in te, sed tu contra me male agis, indicens mihi bella non justa. Judicet Dominus arbiter hujus diei inter Israël, et inter filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Noluitque acquiescere rex filiorum Ammon verbis Jephte, quæ per nuntios mandaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Factus est ergo super Jephte spiritus Domini, et circuiens Galaad et Manasse, Maspha quoque Galaad, et inde transiens ad filios Ammon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'votum vovit Domino, dicens: Si tradideris filios Ammon in manus meas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'quicumque primus fuerit egressus de foribus domus meæ, mihique occurrerit revertenti cum pace a filiis Ammon, eum holocaustum offeram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Transivitque Jephte ad filios Ammon, ut pugnaret contra eos: quos tradidit Dominus in manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Percussitque ab Aroër usque dum venias in Mennith, viginti civitates, et usque ad Abel, quæ est vineis consita, plaga magna nimis: humiliatique sunt filii Ammon a filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Revertente autem Jephte in Maspha domum suam, occurrit ei unigenita filia sua cum tympanis et choris: non enim habebat alios liberos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Qua visa, scidit vestimenta sua, et ait: Heu me, filia mea! decepisti me, et ipsa decepta es: aperui enim os meum ad Dominum, et aliud facere non potero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Cui illa respondit: Pater mi, si aperuisti os tuum ad Dominum, fac mihi quodcumque pollicitus es, concessa tibi ultione atque victoria de hostibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Dixitque ad patrem: Hoc solum mihi præsta quod deprecor: dimitte me ut duobus mensibus circumeam montes, et plangam virginitatem meam cum sodalibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Cui ille respondit: Vade. Et dimisit eam duobus mensibus. Cumque abiisset cum sociis ac sodalibus suis, flebat virginitatem suam in montibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Expletisque duobus mensibus, reversa est ad patrem suum, et fecit ei sicut voverat, quæ ignorabat virum. Exinde mos increbruit in Israël, et consuetudo servata est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'ut post anni circulum conveniant in unum filiæ Israël, et plangant filiam Jephte Galaaditæ diebus quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Ecce autem in Ephraim orta est seditio: nam transeuntes contra aquilonem, dixerunt ad Jephte: Quare vadens ad pugnam contra filios Ammon, vocare nos noluisti, ut pergeremus tecum? igitur incendemus domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Quibus ille respondit: Disceptatio erat mihi et populo meo contra filios Ammon vehemens: vocavique vos, ut præberetis mihi auxilium, et facere noluistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Quod cernens, posui animam meam in manibus meis, transivique ad filios Ammon, et tradidit eos Dominus in manus meas. Quid commerui, ut adversum me consurgatis in prælium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Vocatis itaque ad se cunctis viris Galaad, pugnabat contra Ephraim: percusseruntque viri Galaad Ephraim, quia dixerat: Fugitivus est Galaad de Ephraim, et habitat in medio Ephraim et Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Occupaveruntque Galaaditæ vada Jordanis, per quæ Ephraim reversurus erat. Cumque venisset ad ea de Ephraim numero, fugiens, atque dixisset: Obsecro ut me transire permittatis: dicebant ei Galaaditæ: Numquid Ephrathæus es? quo dicente: Non sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'interrogabant eum: Dic ergo Scibboleth, quod interpretatur Spica. Qui respondebat: Sibboleth: eadem littera spicam exprimere non valens. Statimque apprehensum jugulabant in ipso Jordanis transitu. Et ceciderunt in illo tempore de Ephraim quadraginta duo millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Judicavit itaque Jephte Galaadites Israël sex annis: et mortuus est, ac sepultus in civitate sua Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Post hunc judicavit Israël Abesan de Bethlehem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'qui habuit triginta filios, et totidem filias, quas emittens foras, maritis dedit, et ejusdem numeri filiis suis accepit uxores, introducens in domum suam. Qui septem annis judicavit Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'mortuusque est, ac sepultus in Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Cui successit Ahialon Zabulonites: et judicavit Israël decem annis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'mortuusque est, ac sepultus in Zabulon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Post hunc judicavit Israël Abdon filius Illel Pharathonites:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'qui habuit quadraginta filios, et triginta ex eis nepotes, ascendentes super septuaginta pullos asinarum. Et judicavit Israël octo annis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'mortuusque est, ac sepultus in Pharathon terræ Ephraim, in monte Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Rursumque filii Israël fecerunt malum in conspectu Domini: qui tradidit eos in manus Philisthinorum quadraginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Erat autem quidam vir de Saraa, et de stirpe Dan, nomine Manue, habens uxorem sterilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Cui apparuit angelus Domini, et dixit ad eam: Sterilis es et absque liberis: sed concipies, et paries filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Cave ergo ne bibas vinum ac siceram, nec immundum quidquam comedas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'quia concipies, et paries filium, cujus non tanget caput novacula: erit enim nazaræus Dei ab infantia sua et ex matris utero, et ipse incipiet liberare Israël de manu Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Quæ cum venisset ad maritum suum, dixit ei: Vir Dei venit ad me, habens vultum angelicum, terribilis nimis. Quem cum interrogassem quis esset, et unde venisset, et quo nomine vocaretur, noluit mihi dicere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'sed hoc respondit: Ecce concipies et paries filium: cave ne vinum bibas, nec siceram, et ne aliquo vescaris immundo: erit enim puer nazaræus Dei ab infantia sua, ex utero matris suæ usque ad diem mortis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Oravit itaque Manue Dominum, et ait: Obsecro, Domine, ut vir Dei, quem misisti, veniat iterum, et doceat nos quid debeamus facere de puero, qui nasciturus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Exaudivitque Dominus deprecantem Manue, et apparuit rursum angelus Dei uxori ejus sedenti in agro: Manue autem maritus ejus non erat cum ea. Quæ cum vidisset angelum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'festinavit, et cucurrit ad virum suum: nuntiavitque ei, dicens: Ecce apparuit mihi vir, quem ante videram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Qui surrexit, et secutus est uxorem suam: veniensque ad virum, dixit ei: Tu es qui locutus es mulieri? Et ille respondit: Ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Cui Manue: Quando, inquit, sermo tuus fuerit expletus, quid vis ut faciat puer? aut a quo se observare debebit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Dixitque angelus Domini ad Manue: Ab omnibus, quæ locutus sum uxori tuæ, abstineat se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'et quidquid ex vinea nascitur, non comedat: vinum et siceram non bibat; nullo vescatur immundo: et quod ei præcepi, impleat atque custodiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Dixitque Manue ad angelum Domini: Obsecro te ut acquiescas precibus meis, et faciamus tibi hædum de capris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Cui respondit angelus: Si me cogis, non comedam panes tuos: si autem vis holocaustum facere, offer illud Domino. Et nesciebat Manue quod angelus Domini esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Dixitque ad eum: Quod est tibi nomen, ut, si sermo tuus fuerit expletus, honoremus te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Cui ille respondit: Cur quæris nomen meum, quod est mirabile?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Tulit itaque Manue hædum de capris, et libamenta, et posuit super petram, offerens Domino, qui facit mirabilia: ipse autem et uxor ejus intuebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Cumque ascenderet flamma altaris in cælum, angelus Domini pariter in flamma ascendit. Quod cum vidissent Manue et uxor ejus, proni ceciderunt in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'et ultra eis non apparuit angelus Domini. Statimque intellexit Manue angelum Domini esse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'et dixit ad uxorem suam: Morte moriemur, quia vidimus Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Cui respondit mulier: Si Dominus nos vellet occidere, de manibus nostris holocaustum et libamenta non suscepisset, nec ostendisset nobis hæc omnia, neque ea quæ sunt ventura dixisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Peperit itaque filium, et vocavit nomen ejus Samson. Crevitque puer, et benedixit ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Cœpitque spiritus Domini esse cum eo in castris Dan inter Saraa et Esthaol.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Descendit ergo Samson in Thamnatha: vidensque ibi mulierem de filiabus Philisthiim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'ascendit, et nuntiavit patri suo et matri suæ, dicens: Vidi mulierem in Thamnatha de filiabus Philisthinorum: quam quæso ut mihi accipiatis uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Cui dixerunt pater et mater sua: Numquid non est mulier in filiabus fratrum tuorum, et in omni populo meo, quia vis accipere uxorem de Philisthiim, qui incircumcisi sunt? Dixitque Samson ad patrem suum: Hanc mihi accipe: quia placuit oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Parentes autem ejus nesciebant quod res a Domino fieret, et quæreret occasionem contra Philisthiim: eo enim tempore Philisthiim dominabantur Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Descendit itaque Samson cum patre suo et matre in Thamnatha. Cumque venissent ad vineas oppidi, apparuit catulus leonis sævus, et rugiens, et occurrit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Irruit autem spiritus Domini in Samson, et dilaceravit leonem, quasi hædum in frustra discerpens, nihil omnino habens in manu: et hoc patri et matri noluit indicare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Descenditque, et locutus est mulieri quæ placuerat oculis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Et post aliquot dies revertens ut acciperet eam, declinavit ut videret cadaver leonis, et ecce examen apum in ore leonis erat ac favus mellis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Quem cum sumpsisset in manibus comedebat in via: veniensque ad patrem suum et matrem, dedit eis partem, qui et ipsi comederunt: nec tamen eis voluit indicare quod mel de corpore leonis assumpserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Descendit itaque pater ejus ad mulierem, et fecit filio suo Samson convivium: sic enim juvenes facere consueverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Cum ergo cives loci illius vidissent eum, dederunt ei sodales triginta ut essent cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Quibus locutus est Samson: Proponam vobis problema: quod si solveritis mihi intra septem dies convivii, dabo vobis triginta sindones, et totidem tunicas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'sin autem non potueritis solvere, vos dabitis mihi triginta sindones, et ejusdem numeri tunicas. Qui responderunt ei: Propone problema, ut audiamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Dixitque eis: De comedente exivit cibus, et de forti egressa est dulcedo. Nec potuerunt per tres dies propositionem solvere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Cumque adesset dies septimus, dixerunt ad uxorem Samson: Blandire viro tuo et suade ei ut indicet tibi quid significet problema: quod si facere nolueris, incendemus te, et domum patris tui: an idcirco vocastis nos ad nuptias ut spoliaretis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Quæ fundebat apud Samson lacrimas, et quærebatur, dicens: Odisti me, et non diligis: idcirco problema, quod proposuisti filiis populi mei, non vis mihi exponere. At ille respondit: Patri meo et matri nolui dicere: et tibi indicare potero?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Septem igitur diebus convivii flebat ante eum: tandemque die septimo cum ei esset molesta, exposuit. Quæ statim indicavit civibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Et illi dixerunt ei die septimo ante solis occubitum: Quid dulcius melle, et quid fortius leone? Qui ait ad eos: Si non arassetis in vitula mea, non invenissetis propositionem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Irruit itaque in eum spiritus Domini, descenditque Ascalonem, et percussit ibi triginta viros: quorum ablatas vestes dedit iis qui problema solverant. Iratusque nimis ascendit in domum patris sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'uxor autem ejus accepit maritum unum de amicis ejus et pronubis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Post aliquantulum autem temporis, cum dies triticeæ messis instarent, venit Samson, invisere volens uxorem suam, et attulit ei hædum de capris. Cumque cubiculum ejus solito vellet intrare, prohibuit eum pater illius, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Putavi quod odisses eam, et ideo tradidi illam amico tuo: sed habet sororem, quæ junior et pulchrior illa est: sit tibi pro ea uxor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Cui Samson respondit: Ab hac die non erit culpa in me contra Philisthæos: faciam enim vobis mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Perrexitque et cepit trecentas vulpes, caudasque earum junxit ad caudas, et faces ligavit in medio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'quas igne succendens, dimisit ut huc illucque discurrerent. Quæ statim perrexerunt in segetes Philisthinorum. Quibus succensis, et comportatæ jam fruges, et adhuc stantes in stipula, concrematæ sunt, in tantum ut vineas quoque et oliveta flamma consumeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Dixeruntque Philisthiim: Quis fecit hanc rem? Quibus dictum est: Samson gener Thamnathæi: quia tulit uxorem ejus, et alteri tradidit, hæc operatus est. Ascenderuntque Philisthiim, et combusserunt tam mulierem quam patrem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Quibus ait Samson: Licet hæc feceritis, tamen adhuc ex vobis expetam ultionem, et tunc quiescam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Percussitque eos ingenti plaga, ita ut stupentes suram femori imponerent. Et descendens habitavit in spelunca petræ Etam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Igitur ascendentes Philisthiim in terram Juda, castrametati sunt in loco, qui postea vocatus est Lechi, id est, Maxilla, ubi eorum effusus est exercitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Dixeruntque ad eos de tribu Juda: Cur ascendistis adversum nos? Qui responderunt: Ut ligemus Samson venimus, et reddamus ei quæ in nos operatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Descenderunt ergo tria millia virorum de Juda ad specum silicis Etam, dixeruntque ad Samson: Nescis quod Philisthiim imperent nobis? quare hoc facere voluisti? Quibus ille ait: Sicut fecerunt mihi, sic feci eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Ligare, inquiunt, te venimus, et tradere in manus Philisthinorum. Quibus Samson: Jurate, ait, et spondete mihi quod non occidatis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Dixerunt: Non te occidemus, sed vinctum trademus. Ligaveruntque eum duobus novis funibus, et tulerunt eum de petra Etam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Qui cum venisset ad locum Maxillæ, et Philisthiim vociferantes occurrissent ei, irruit spiritus Domini in eum: et sicut solent ad odorem ignis lina consumi, ita vincula, quibus ligatus erat, dissipata sunt et soluta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Inventamque maxillam, id est, mandibulam asini, quæ jacebat, arripiens interfecit in ea mille viros,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'et ait: In maxilla asini, in mandibula pulli asinarum, delevi eos, et percussi mille viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Cumque hæc verba canens complesset, projecit mandibulam de manu, et vocavit nomen loci illius Ramathlechi, quod interpretatur, Elevatio maxillæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Sitiensque valde, clamavit ad Dominum, et ait: Tu dedisti in manu servi tui salutem hanc maximam atque victoriam: en siti morior, incidamque in manus incircumcisorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Aperuit itaque Dominus molarem dentem in maxilla asini, et egressæ sunt ex eo aquæ. Quibus haustis, refocillavit spiritum, et vires recepit. Idcirco appellatum est nomen loci illius, Fons invocantis de maxilla, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Judicavitque Israël in diebus Philisthiim viginti annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Abiit quoque in Gazam, et vidit ibi mulierem meretricem, ingressusque est ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Quod cum audissent Philisthiim, et percrebruisset apud eos intrasse urbem Samson, circumdederunt eum, positis in porta civitatis custodibus: et ibi tota nocte cum silentio præstolantes, ut facto mane exeuntem occiderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Dormivit autem Samson usque ad medium noctem: et inde consurgens, apprehendit ambas portæ fores cum postibus suis et sera, impositasque humeris suis portavit ad verticem montis, qui respicit Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Post hæc amavit mulierem, quæ habitabat in valle Sorec, et vocabatur Dalila.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Veneruntque ad eam principes Philisthinorum, atque dixerunt: Decipe eum, et disce ab illo, in quo habeat tantam fortitudinem, et quomodo eum superare valeamus, et vinctum affligere: quod si feceris, dabimus tibi singuli mille et centum argenteos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Locuta est ergo Dalila ad Samson: Dic mihi, obsecro, in quo sit tua maxima fortitudo, et quid sit quo ligatus erumpere nequeas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Cui respondit Samson: Si septem nerviceis funibus necdum siccis, et adhuc humentibus, ligatus fuero, infirmus ero ut ceteri homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Attuleruntque ad eam satrapæ Philisthinorum septem funes, ut dixerat: quibus vinxit eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'latentibus apud se insidiis, et in cubiculo finem rei expectantibus: clamavitque ad eum: Philisthiim super te, Samson. Qui rupit vincula, quomodo si rumpat quis filum de stuppæ tortum putamine, cum odorem ignis acceperit: et non est cognitum in quo esset fortitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Dixitque ad eum Dalila: Ecce illusisti mihi, et falsum locutus es: saltem nunc indica mihi quo ligari debeas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Cui ille respondit: Si ligatus fuero novis funibus, qui numquam fuerunt in opere, infirmus ero, et aliorum hominum similis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Quibus rursum Dalila vinxit eum, et clamavit: Philisthiim super te, Samson: in cubiculo insidiis præparatis. Qui ita rupit vincula quasi fila telarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Dixitque Dalila rursum ad eum: Usquequo decipis me, et falsum loqueris? ostende quo vinciri debeas. Cui respondit Samson: Si septem crines capitis mei cum licio plexueris, et clavum his circumligatum terræ fixeris, infirmus ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Quod cum fecisset Dalila, dixit ad eum: Philisthiim super te, Samson. Qui consurgens de somno extraxit clavum cum crinibus et licio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Dixitque ad eum Dalila: Quomodo dicis quod amas me, cum animus tuus non sit mecum? Per tres vices mentitus es mihi, et noluisti dicere in quo sit maxima fortitudo tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Cumque molesta esset ei, et per multos dies jugiter adhæreret, spatium ad quietem non tribuens, defecit anima ejus, et ad mortem usque lassata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Tunc aperiens veritatem rei, dixit ad eam: Ferrum numquam ascendit super caput meum, quia nazaræus, id est, consecratus Deo, sum de utero matris meæ: si rasum fuerit caput meum, recedet a me fortitudo mea, et deficiam, eroque sicut ceteri homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Vidensque illa quod confessus ei esset omnem animum suum, misit ad principes Philisthinorum ac mandavit: Ascende adhuc semel, quia nunc mihi aperuit cor suum. Qui ascenderunt assumpta pecunia, quam promiserant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'At illa dormire eum fecit super genua sua, et in sinu suo reclinare caput. Vocavitque tonsorem, et rasit septem crines ejus, et cœpit abigere eum, et a se repellere: statim enim ab eo fortitudo discessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Dixitque: Philisthiim super te, Samson. Qui de somno consurgens, dixit in animo suo: Egrediar sicut ante feci, et me excutiam: nesciens quod recessisset ab eo Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Quem cum apprehendissent Philisthiim, statim eruerunt oculos ejus, et duxerunt Gazam vinctum catenis, et clausum in carcere molere fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Jamque capilli ejus renasci cœperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Et principes Philisthinorum convenerunt in unum ut immolarent hostias magnificas Dagon deo suo, et epularentur, dicentes: Tradidit deus noster inimicum nostrum Samson in manus nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Quod etiam populus videns, laudabat deum suum, eademque dicebat: Tradidit deus noster adversarium nostrum in manus nostras, qui delevit terram nostram, et occidit plurimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Lætantesque per convivia, sumptis jam epulis, præceperunt ut vocaretur Samson, et ante eos luderet. Qui adductus de carcere ludebat ante eos, feceruntque eum stare inter duas columnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Qui dixit puero regenti gressus suos: Dimitte me, ut tangam columnas, quibus omnis imminet domus, et recliner super eas, et paululum requiescam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Domus autem erat plena virorum ac mulierum, et erant ibi omnes principes Philisthinorum, ac de tecto et solario circiter tria millia utriusque sexus spectantes ludentem Samson.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'At ille invocato Domino ait: Domine Deus, memento mei, et redde mihi nunc fortitudinem pristinam, Deus meus, ut ulciscar me de hostibus meis, et pro amissione duorum luminum unam ultionem recipiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Et apprehendens ambas columnas quibus innitebatur domus, alteramque earum dextera et alteram læva tenens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'ait: Moriatur anima mea cum Philisthiim. Concussisque fortiter columnis, cecidit domus super omnes principes, et ceteram multitudinem quæ ibi erat: multoque plures interfecit moriens, quam ante vivus occiderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Descendentes autem fratres ejus et universa cognatio, tulerunt corpus ejus, et sepelierunt inter Saraa et Esthaol in sepulchro patris sui Manue: judicavitque Israël viginti annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Fuit eo tempore vir quidam de monte Ephraim nomine Michas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'qui dixit matri suæ: Mille et centum argenteos, quos separaveras tibi, et super quibus me audiente juraveras, ecce ego habeo, et apud me sunt. Cui illa respondit: Benedictus filius meus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Reddidit ergo eos matri suæ, quæ dixerat ei: Consecravi et vovi hoc argentum Domino, ut de manu mea suscipiat filius meus, et faciat sculptile atque conflatile: et nunc trado illud tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Reddidit igitur eos matri suæ: quæ tulit ducentos argenteos, et dedit eos argentario, ut faceret ex eis sculptile atque conflatile, quod fuit in domo Michæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Qui ædiculam quoque in ea deo separavit, et fecit ephod, et theraphim, id est, vestem sacerdotalem, et idola: implevitque unius filiorum suorum manum, et factus est ei sacerdos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'In diebus illis non erat rex in Israël, sed unusquisque quod sibi rectum videbatur, hoc faciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Fuit quoque alter adolescens de Bethlehem Juda, ex cognatione ejus: eratque ipse Levites, et habitabat ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Egressusque de civitate Bethlehem, peregrinari voluit ubicumque sibi commodum reperisset. Cumque venisset in montem Ephraim, iter faciens, et declinasset parumper in domum Michæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'interrogatus est ab eo unde venisset. Qui respondit: Levita sum de Bethlehem Juda, et vado ut habitem ubi potuero, et utile mihi esse perspexero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Dixitque Michas: Mane apud me, et esto mihi parens ac sacerdos: daboque tibi per annos singulos decem argenteos, ac vestem duplicem, et quæ ad victum sunt necessaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Acquievit, et mansit apud hominem, fuitque illi quasi unus de filiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Implevitque Michas manum ejus, et habuit puerum sacerdotem apud se:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Nunc scio, dicens, quod benefaciet mihi Deus habenti Levitici generis sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'In diebus illis non erat rex in Israël, et tribus Dan quærebat possessionem sibi, ut habitaret in ea: usque ad illum enim diem inter ceteras tribus sortem non acceperat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Miserunt ergo filii Dan stirpis et familiæ suæ quinque viros fortissimos de Saraa et Esthaol, ut explorarent terram, et diligenter inspicerent: dixeruntque eis: Ite, et considerate terram. Qui cum pergentes venissent in montem Ephraim, et intrassent domum Michæ, requieverunt ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'et agnoscentes vocem adolescentis Levitæ, utentesque illius diversorio, dixerunt ad eum: Quis te huc adducit? quid hic agis? quam ob causam huc venire voluisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Qui respondit eis: Hæc et hæc præstitit mihi Michas, et me mercede conduxit, ut sim ei sacerdos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Rogaverunt autem eum ut consuleret Dominum ut scire possent an prospero itinere pergerent, et res haberet effectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Qui respondit eis: Ite in pace: Dominus respicit viam vestram, et iter quo pergitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Euntes igitur quinque viri venerunt Lais: videruntque populum habitantem in ea absque ullo timore, juxta consuetudinem Sidoniorum, securum et quietum, nullo ei penitus resistente, magnarumque opum, et procul a Sidone atque a cunctis hominibus separatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Reversique ad fratres suos in Saraa et Esthaol, et quid egissent sciscitantibus responderunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Surgite, ascendamus ad eos: vidimus enim terram valde opulentam et uberem. Nolite negligere, nolite cessare: eamus, et possideamus eam: nullus erit labor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Intrabimus ad securos, in regionem latissimam, tradetque nobis Dominus locum, in quo nullius rei est penuria eorum quæ gignuntur in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Profecti igitur sunt de cognatione Dan, id est, de Saraa et Esthaol, sexcenti viri accincti armis bellicis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'ascendentesque manserunt in Cariathiarim Judæ: qui locus ex eo tempore Castrorum Dan nomen accepit, et est post tergum Cariathiarim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Inde transierunt in montem Ephraim. Cumque venissent ad domum Michæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'dixerunt quinque viri, qui prius missi fuerant ad considerandam terram Lais, ceteris fratribus suis: Nostis quod in domibus istis sit ephod, et theraphim, et sculptile, atque conflatile: videte quid vobis placeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Et cum paululum declinassent, ingressi sunt domum adolescentis Levitæ, qui erat in domo Michæ: salutaveruntque eum verbis pacificis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Sexcenti autem viri ita ut erant armati, stabant ante ostium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'At illi, qui ingressi fuerant domum juvenis, sculptile, et ephod, et theraphim, atque conflatile tollere nitebantur, et sacerdos stabat ante ostium, sexcentis viris fortissimis haud procul expectantibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Tulerunt igitur qui intraverant sculptile, ephod, et idola, atque conflatile. Quibus dixit sacerdos: Quid facitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Cui responderunt: Tace et pone digitum super os tuum: venique nobiscum, ut habeamus te patrem, ac sacerdotem. Quid tibi melius est, ut sis sacerdos in domo unius viri, an in una tribu et familia in Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Quod cum audisset, acquievit sermonibus eorum, et tulit ephod, et idola, ac sculptile, et profectus est cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Qui cum pergerent, et ante se ire fecissent parvulos ac jumenta, et omne quod erat pretiosum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'et jam a domo Michæ essent procul, viri qui habitabant in ædibus Michæ conclamantes secuti sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'et post tergum clamare cœperunt. Qui cum respexissent, dixerunt ad Micham: Quid tibi vis? cur clamas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Qui respondit: Deos meos, quos mihi feci, tulistis, et sacerdotem, et omnia quæ habeo, et dicitis: Quid tibi est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Dixeruntque ei filii Dan: Cave ne ultra loquaris ad nos, et veniant ad te viri animo concitati, et ipse cum omni domo tua pereas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Et sic cœpto itinere perrexerunt. Videns autem Michas quod fortiores se essent, reversus est in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Sexcenti autem viri tulerunt sacerdotem, et quæ supra diximus: veneruntque in Lais ad populum quiescentem atque securum, et percusserunt eos in ore gladii: urbemque incendio tradiderunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'nullo penitus ferente præsidium, eo quod procul habitarent a Sidone, et cum nullo hominum haberent quidquam societatis ac negotii. Erat autem civitas sita in regione Rohob: quam rursum exstruentes habitaverunt in ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'vocato nomine civitatis Dan, juxta vocabulum patris sui, quem genuerat Israël, quæ prius Lais dicebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Posueruntque sibi sculptile, et Jonathan filium Gersam filii Moysi ac filios ejus sacerdotes in tribu Dan, usque ad diem captivitatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Mansitque apud eos idolum Michæ omni tempore quo fuit domus Dei in Silo. In diebus illis non erat rex in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Fuit quidam vir Levites habitans in latere montis Ephraim, qui accepit uxorem de Bethlehem Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'quæ reliquit eum, et reversa est in domum patris sui in Bethlehem, mansitque apud eum quatuor mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Secutusque est eam vir suus, volens reconciliari ei, atque blandiri, et secum reducere, habens in comitatu puerum et duos asinos: quæ suscepit eum, et introduxit in domum patris sui. Quod cum audisset socer ejus, eumque vidisset, occurrit ei lætus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'et amplexatus est hominem. Mansitque gener in domo soceri tribus diebus, comedens cum eo et bibens familiariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Die autem quarto de nocte consurgens, proficisci voluit: quem tenuit socer, et ait ad eum: Gusta prius pauxillum panis, et conforta stomachum, et sic proficisceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Sederuntque simul, ac comederunt et biberunt. Dixitque pater puellæ ad generum suum: Quæso te ut hodie hic maneas, pariterque lætemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'At ille consurgens, cœpit velle proficisci. Et nihilominus obnixe eum socer tenuit, et apud se fecit manere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Mane autem facto, parabat Levites iter. Cui socer rursum: Oro te, inquit, ut paululum cibi capias, et assumptis viribus donec increscat dies, postea proficiscaris. Comederunt ergo simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Surrexitque adolescens, ut pergeret cum uxore sua et puero. Cui rursum locutus est socer: Considera quod dies ad occasum declivior sit, et propinquat ad vesperum: mane apud me etiam hodie, et duc lætum diem, et cras proficisceris ut vadas in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Noluit gener acquiescere sermonibus ejus: sed statim perrexit, et venit contra Jebus, quæ altero nomine vocatur Jerusalem, ducens secum duos asinos onustos, et concubinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Jamque erant juxta Jebus, et dies mutabatur in noctem: dixitque puer ad dominum suum: Veni, obsecro: declinemus ad urbem Jebusæorum, et maneamus in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Cui respondit dominus: Non ingrediar oppidum gentis alienæ, quæ non est de filiis Israël: sed transibo usque Gabaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'et cum illuc pervenero, manebimus in ea, aut certe in urbe Rama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Transierunt ergo Jebus, et cœptum carpebant iter, occubuitque eis sol juxta Gabaa, quæ est in tribu Benjamin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'diverteruntque ad eam, ut manerent ibi. Quo cum intrassent, sedebant in platea civitatis, et nullus eos recipere voluit hospitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Et ecce, apparuit homo senex, revertens de agro et de opere suo vesperi, qui et ipse de monte erat Ephraim, et peregrinus habitabat in Gabaa: homines autem regionis illius erant filii Jemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Elevatisque oculis, vidit senex sedentem hominem cum sarcinulis suis in platea civitatis, et dixit ad eum: Unde venis? et quo vadis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Qui respondit ei: Profecti sumus de Bethlehem Juda, et pergimus ad locum nostrum, qui est in latere montis Ephraim, unde ieramus in Bethlehem: et nunc vadimus ad domum Dei, nullusque sub tectum suum nos vult recipere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'habentes paleas et fœnum in asinorum pabulum, et panem ac vinum in meos et ancillæ tuæ usus, et pueri qui mecum est: nulla re indigemus nisi hospitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Cui respondit senex: Pax tecum sit, ego præbebo omnia quæ necessaria sunt: tantum, quæso, ne in platea maneas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Introduxitque eum in domum suam, et pabulum asinis præbuit: ac postquam laverunt pedes suos, recepit eos in convivium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Illis epulantibus, et post laborem itineris cibo et potu reficientibus corpora, venerunt viri civitatis illius, filii Belial (id est, absque jugo), et circumdantes domum senis, fores pulsare cœperunt, clamantes ad dominum domus atque dicentes: Educ virum, qui ingressus est domum tuam, ut abutamur eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Egressusque est ad eos senex, et ait: Nolite, fratres, nolite facere malum hoc, quia ingressus est homo hospitium meum: et cessate ab hac stultitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Habeo filiam virginem, et hic homo habet concubinam: educam eas ad vos, ut humilietis eas, et vestram libidinem compleatis: tantum, obsecro, ne scelus hoc contra naturam operemini in virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Nolebant acquiescere sermonibus illius: quod cernens homo, eduxit ad eos concubinam suam, et eis tradidit illudendam: qua cum tota nocte abusi essent, dimiserunt eam mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'At mulier, recedentibus tenebris, venit ad ostium domus, ubi manebat dominus suus, et ibi corruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Mane facto, surrexit homo, et aperuit ostium, ut cœptam expleret viam: et ecce concubina ejus jacebat ante ostium sparsis in limine manibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Cui ille, putans eam quiescere, loquebatur: Surge, et ambulemus. Qua nihil respondente, intelligens quod erat mortua, tulit eam, et imposuit asino, reversusque est in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Quam cum esset ingressus, arripuit gladium, et cadaver uxoris cum ossibus suis in duodecim partes ac frustra concidens, misit in omnes terminos Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Quod cum vidissent singuli, conclamabant: Numquam res talis facta est in Israël, ex eo die quo ascenderunt patres nostri de \'gypto usque in præsens tempus: ferte sententiam, et in commune decernite quid facto opus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Egressi itaque sunt omnes filii Israël, et pariter congregati, quasi vir unus, de Dan usque Bersabee, et terra Galaad, ad Dominum in Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Omnesque anguli populorum, et cunctæ tribus Israël in ecclesiam populi Dei convenerunt, quadringenta millia peditum pugnatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(Nec latuit filios Benjamin quod ascendissent filii Israël in Maspha.) Interrogatusque Levita, maritus mulieris interfectæ, quomodo tantum scelus perpetratum esset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'respondit: Veni in Gabaa Benjamin cum uxore mea, illucque diverti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'et ecce homines civitatis illius circumdederunt nocte domum in qua manebam, volentes me occidere, et uxorem meam incredibili furore libidinis vexantes, denique mortua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Quam arreptam, in frustra concidi, misique partes in omnes terminos possessionis vestræ: quia numquam tantum nefas, et tam grande piaculum, factum est in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Adestis, omnes filii Israël: decernite quid facere debeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Stansque omnis populus, quasi unius hominis sermone respondit: Non recedemus in tabernacula nostra, nec suam quisquam intrabit domum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'sed hoc contra Gabaa in commune faciamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Decem viri eligantur e centum ex omnibus tribubus Israël, et centum de mille, et mille de decem millibus, ut comportent exercitui cibaria, et possimus pugnare contra Gabaa Benjamin, et reddere ei pro scelere, quod meretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Convenitque universus Israël ad civitatem, quasi homo unus eadem mente, unoque consilio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Et miserunt nuntios ad omnem tribum Benjamin, qui dicerent: Cur tantum nefas in vobis repertum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Tradite homines de Gabaa, qui hoc flagitium perpetrarunt, ut moriantur, et auferatur malum de Israël. Qui noluerunt fratrum suorum filiorum Israël audire mandatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'sed ex cunctis urbibus, quæ sortis suæ erant, convenerunt in Gabaa, ut illis ferrent auxilium, et contra universum populum Israël dimicarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Inventique sunt viginti quinque millia de Benjamin educentium gladium, præter habitatores Gabaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'qui septingenti erant viri fortissimi, ita sinistra ut dextra præliantes: et sic fundis lapides ad certum jacientes, ut capillum quoque possent percutere, et nequaquam in alteram partem ictus lapidis deferretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Virorum quoque Israël, absque filiis Benjamin, inventa sunt quadringenta millia educentium gladium, et paratorum ad pugnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Qui surgentes venerunt in domum Dei, hoc est, in Silo: consulueruntque Deum, atque dixerunt: Quis erit in exercitu nostro princeps certaminis contra filios Benjamin? Quibus respondit Dominus: Judas sit dux vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Statimque filii Israël surgentes mane, castrametati sunt juxta Gabaa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'et inde procedentes ad pugnam contra Benjamin, urbem oppugnare cœperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Egressique filii Benjamin de Gabaa, occiderunt de filiis Israël die illo viginti duo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Rursum filii Israël et fortitudine et numero confidentes, in eodem loco in quo prius certaverant, aciem direxerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'ita tamen ut prius ascenderent et flerent coram Domino usque ad noctem, consulerentque eum, et dicerent: Debeo ultra procedere ad dimicandum contra filios Benjamin fratres meos, an non? Quibus ille respondit: Ascendite ad eos, et inite certamen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Cumque filii Israël altera die contra filios Benjamin ad prælium processissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'eruperunt filii Benjamin de portis Gabaa: et occurrentes eis tanta in illos cæde bacchati sunt, ut decem et octo millia virorum educentium gladium prosternerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Quam ob rem omnes filii Israël venerunt in domum Dei, et sedentes flebant coram Domino: jejunaveruntque die illo usque ad vesperam, et obtulerunt ei holocausta, atque pacificas victimas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'et super statu suo interrogaverunt. Eo tempore ibi erat arca fœderis Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'et Phinees filius Eleazari filii Aaron præpositus domus. Consuluerunt igitur Dominum, atque dixerunt: Exire ultra debemus ad pugnam contra filios Benjamin fratres nostros, an quiescere? Quibus ait Dominus: Ascendite: cras enim tradam eos in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Posueruntque filii Israël insidias per circuitum urbis Gabaa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'et tertia vice, sicut semel et bis, contra Benjamin exercitum produxerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Sed et filii Benjamin audacter eruperunt de civitate, et fugientes adversarios longius persecuti sunt, ita ut vulnerarent ex eis sicut primo die et secundo, et cæderent per duas semitas vertentes terga, quarum una ferebatur in Bethel et altera in Gabaa, atque prosternerent triginta circiter viros:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'putaverunt enim solito eos more cedere. Qui fugam arte simulantes inierunt consilium ut abstraherent eos de civitate, et quasi fugientes ad supradictas semitas perducerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Omnes itaque filii Israël surgentes de sedibus suis, tetenderunt aciem in loco qui vocatur Baalthamar. Insidiæ quoque, quæ circa urbem erant, paulatim se aperire cœperunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'et ab occidentali urbis parte procedere. Sed et alia decem millia virorum de universo Israël, habitatores urbis ad certamina provocabant. Ingravatumque est bellum contra filios Benjamin: et non intellexerunt quod ex omni parte illis instaret interitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Percussitque eos Dominus in conspectu filiorum Israël, et interfecerunt ex eis in illo die viginti quinque millia, et centum viros, omnes bellatores et educentes gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Filii autem Benjamin cum se inferiores esse vidissent, cœperunt fugere. Quod cernentes filii Israël, dederunt eis ad fugiendum locum, ut ad præparatas insidias devenirent, quas juxta urbem posuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Qui cum repente de latibulis surrexissent, et Benjamin terga cædentibus daret, ingressi sunt civitatem, et percusserunt eam in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Signum autem dederant filii Israël his quos in insidiis collocaverant, ut postquam urbem cepissent, ignem accenderent: ut ascendente in altum fumo, captam urbem demonstrarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Quod cum cernerent filii Israël in ipso certamine positi (putaverunt enim filii Benjamin eos fugere, et instantius persequebantur, cæsis de exercitu eorum triginta viris),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'et viderent quasi columnam fumi de civitate conscendere: Benjamin quoque aspiciens retro, cum captam cerneret civitatem, et flammas in sublime ferri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'qui prius simulaverant fugam, versa facie fortius resistebant. Quod cum vidissent filii Benjamin, in fugam versi sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'et ad viam deserti ire cœperunt, illuc quoque eos adversariis persequentibus: sed et hi qui urbem succenderant, occurrerunt eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Atque ita factum est, ut ex utraque parte ab hostibus cæderentur, nec erat ulla requies morientium. Ceciderunt, atque prostrati sunt ad orientalem plagam urbis Gabaa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Fuerunt autem qui in eodem loco interfecti sunt, decem et octo millia virorum, omnes robustissimi pugnatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Quod cum vidissent qui remanserant de Benjamin, fugerunt in solitudinem: et pergebant ad petram, cujus vocabulum est Remmon. In illa quoque fuga palantes, et in diversa tendentes, occiderunt quinque millia virorum. Et cum ultra tenderent, persecuti sunt eos, et interfecerunt etiam alia duo millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Et sic factum est, ut omnes qui ceciderant de Benjamin in diversis locis essent viginti quinque millia pugnatores ad bella promptissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Remanserunt itaque de omni numero Benjamin, qui evadere et fugere in solitudinem potuerunt, sexcenti viri: sederuntque in petra Remmon mensibus quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Regressi autem filii Israël, omnes reliquias civitatis a viris usque ad jumenta gladio percusserunt, cunctasque urbes et viculos Benjamin vorax flamma consumpsit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Juraverunt quoque filii Israël in Maspha, et dixerunt: Nullus nostrum dabit filiis Benjamin de filiabus suis uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Veneruntque omnes ad domum Dei in Silo, et in conspectu ejus sedentes usque ad vesperam, levaverunt vocem, et magno ululatu cœperunt flere, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Quare, Domine Deus Israël, factum est hoc malum in populo tuo, ut hodie una tribus auferretur ex nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Altera autem die diluculo consurgentes, exstruxerunt altare: obtuleruntque ibi holocausta, et pacificas victimas, et dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Quis non ascendit in exercitu Domini de universis tribubus Israël? grandi enim juramento se constrinxerant, cum essent in Maspha, interfici eos qui defuissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Ductique pœnitentia filii Israël super fratre suo Benjamin, cœperunt dicere: Ablata est tribus una de Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'unde uxores accipient? omnes enim in commune juravimus, non daturos nos his filias nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Idcirco dixerunt: Quis est de universis tribubus Israël, qui non ascendit ad Dominum in Maspha? Et ecce inventi sunt habitatores Jabes Galaad in illo exercitu non fuisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, '(Eo quoque tempore cum essent in Silo, nullus ex eis ibi repertus est.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Miserunt itaque decem millia viros robustissimos, et præceperunt eis: Ite, et percutite habitatores Jabes Galaad in ore gladii, tam uxores quam parvulos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Et hoc erit quod observare debebitis: omne generis masculini, et mulieres quæ cognoverunt viros, interficite; virgines autem reservate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Inventæque sunt de Jabes Galaad quadringentæ virgines, quæ nescierunt viri thorum: et adduxerunt eas ad castra in Silo, in terram Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Miseruntque nuntios ad filios Benjamin, qui erant in petra Remmon, et præceperunt eis, ut eos susciperent in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Veneruntque filii Benjamin in illo tempore, et datæ sunt eis uxores de filiabus Jabes Galaad: alias autem non repererunt, quas simili modo traderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Universusque Israël valde doluit, et egit pœnitentiam super interfectione unius tribus ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Dixeruntque majores natu: Quid faciemus reliquis, qui non acceperunt uxores? omnes in Benjamin feminæ conciderunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'et magna nobis cura, ingentique studio providendum est, ne una tribus deleatur ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Filias enim nostras eis dare non possumus, constricti juramento et maledictione qua diximus: Maledictus qui dederit de filiabus suis uxorem Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Ceperuntque consilium, atque dixerunt: Ecce solemnitas Domini est in Silo anniversaria, quæ sita est ad septentrionem urbis Bethel, et ad orientalem plagam viæ, quæ de Bethel tendit ad Sichimam, et ad meridiem oppidi Lebona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Præceperuntque filiis Benjamin, atque dixerunt: Ite, et latitate in vineis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Cumque videritis filias Silo ad ducendos choros ex more procedere, exite repente de vineis, et rapite ex eis singuli uxores singulas, et pergite in terram Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Cumque venerint patres earum, ac fratres, et adversum vos queri cœperint atque jurgari, dicemus eis: Miseremini eorum: non enim rapuerunt eas jure bellantium atque victorum: sed rogantibus ut acciperent, non dedistis, et a vestra parte peccatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Feceruntque filii Benjamin ut sibi fuerat imperatum: et juxta numerum suum, rapuerunt sibi de his quæ ducebant choros, uxores singulas: abieruntque in possessionem suam ædificantes urbes, et habitantes in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Filii quoque Israël reversi sunt per tribus et familias in tabernacula sua. In diebus illis non erat rex in Israël: sed unusquisque quod sibi rectum videbatur, hoc faciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'In diebus unius judicis, quando judices præerant, facta est fames in terra. Abiitque homo de Bethlehem Juda, ut peregrinaretur in regione Moabitide cum uxore sua ac duobus liberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Ipse vocabatur Elimelech, et uxor ejus Noëmi: et duo filii, alter Mahalon, et alter Chelion, Ephrathæi de Bethlehem Juda. Ingressique regionem Moabitidem, morabantur ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Et mortuus est Elimelech maritus Noëmi: remansitque ipsa cum filiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Qui acceperunt uxores Moabitidas, quarum una vocabatur Orpha, altera vero Ruth. Manseruntque ibi decem annis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'et ambo mortui sunt, Mahalon videlicet et Chelion: remansitque mulier orbata duobus liberis ac marito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Et surrexit ut in patriam pergeret cum utraque nuru sua de regione Moabitide: audierat enim quod respexisset Dominus populum suum, et dedisset eis escas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Egressa est itaque de loco peregrinationis suæ, cum utraque nuru: et jam in via revertendi posita in terram Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'dixit ad eas: Ite in domum matris vestræ: faciat vobiscum Dominus misericordiam, sicut fecistis cum mortuis, et mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Det vobis invenire requiem in domibus virorum quos sortituræ estis. Et osculata est eas. Quæ elevata voce flere cœperunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'et dicere: Tecum pergemus ad populum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Quibus illa respondit: Revertimini, filiæ meæ, cur venitis mecum? num ultra habeo filios in utero meo, ut viros ex me sperare possitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Revertimini, filiæ meæ, et abite: jam enim senectute confecta sum, nec apta vinculo conjugali: etiamsi possem hac nocte concipere, et parere filios,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'si eos expectare velitis donec crescant, et annos pubertatis impleant, ante eritis vetulæ quam nubatis. Nolite, quæso, filiæ meæ: quia vestra angustia magis me premit, et egressa est manus Domini contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Elevata igitur voce, rursum flere cœperunt: Orpha osculata est socrum, ac reversa est; Ruth adhæsit socrui suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'cui dixit Noëmi: En reversa est cognata tua ad populum suum, et ad deos suos, vade cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Quæ respondit: Ne adverseris mihi ut relinquam te et abeam: quocumque enim perrexeris, pergam, et ubi morata fueris, et ego pariter morabor. Populus tuus populus meus, et Deus tuus Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Quæ te terra morientem susceperit, in ea moriar: ibique locum accipiam sepulturæ. Hæc mihi faciat Dominus, et hæc addat, si non sola mors me et te separaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Videns ergo Noëmi quod obstinato animo Ruth decrevisset secum pergere, adversari noluit, nec ad suos ultra reditum persuadere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'profectæque sunt simul, et venerunt in Bethlehem. Quibus urbem ingressis, velox apud cunctos fama percrebruit: dicebantque mulieres: Hæc est illa Noëmi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Quibus ait: Ne vocetis me Noëmi (id est, pulchram), sed vocate me Mara (id est, amaram), quia amaritudine valde replevit me Omnipotens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Egressa sum plena, et vacuam reduxit me Dominus. Cur ergo vocatis me Noëmi, quam Dominus humiliavit, et afflixit Omnipotens?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Venit ergo Noëmi cum Ruth Moabitide nuru sua, de terra peregrinationis suæ: ac reversa est in Bethlehem, quando primum hordea metebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Erat autem viro Elimelech consanguineus, homo potens, et magnarum opum, nomine Booz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Dixitque Ruth Moabitis ad socrum suam: Si jubes, vadam in agrum, et colligam spicas quæ fugerint manus metentium, ubicumque clementis in me patrisfamilias reperero gratiam. Cui illa respondit: Vade, filia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Abiit itaque et colligebat spicas post terga metentium. Accidit autem ut ager ille haberet dominum nomine Booz, qui erat de cognatione Elimelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Et ecce, ipse veniebat de Bethlehem, dixitque messoribus: Dominus vobiscum. Qui responderunt ei: Benedicat tibi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Dixitque Booz juveni, qui messoribus præerat: Cujus est hæc puella?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Cui respondit: Hæc est Moabitis, quæ venit cum Noëmi, de regione Moabitide,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'et rogavit ut spicas colligeret remanentes, sequens messorum vestigia: et de mane usque nunc stat in agro, et ne ad momentum quidem domum reversa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Et ait Booz ad Ruth: Audi, filia, ne vadas in alterum agrum ad colligendum, nec recedas ab hoc loco: sed jungere puellis meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'et ubi messuerint, sequere. Mandavi enim pueris meis, ut nemo molestus sit tibi: sed etiam si sitieris, vade ad sarcinulas, et bibe aquas, de quibus et pueri bibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Quæ cadens in faciem suam et adorans super terram, dixit ad eum: Unde mihi hoc, ut invenirem gratiam ante oculos tuos, et nosse me dignareris peregrinam mulierem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Cui ille respondit: Nuntiata sunt mihi omnia quæ feceris socrui tuæ post mortem viri tui: et quod reliqueris parentes tuos, et terram in qua nata es, et veneris ad populum, quem antea nesciebas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Reddat tibi Dominus pro opere tuo, et plenam mercedem recipias a Domino Deo Israël, ad quem venisti, et sub cujus confugisti alas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Quæ ait: Inveni gratiam apud oculos tuos, domine mi, qui consolatus es me, et locutus es ad cor ancillæ tuæ, quæ non sum similis unius puellarum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Dixitque ad eam Booz: Quando hora vescendi fuerit, veni huc, et comede panem, et intinge buccellam tuam in aceto. Sedit itaque ad messorum latus, et congessit polentam sibi, comeditque et saturata est, et tulit reliquias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Atque inde surrexit, ut spicas ex more colligeret. Præcepit autem Booz pueris suis, dicens: Etiamsi vobiscum metere voluerit, ne prohibeatis eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'et de vestris quoque manipulis projicite de industria, et remanere permittite, ut absque rubore colligat, et colligentem nemo corripiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Collegit ergo in agro usque ad vesperam: et quæ collegerat virga cædens et excutiens, invenit hordei quasi ephi mensuram, id est, tres modios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Quos portans reversa est in civitatem, et ostendit socrui suæ: insuper protulit, et dedit ei de reliquiis cibi sui, quo saturata fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Dixitque ei socrus sua: Ubi hodie collegisti, et ubi fecisti opus? sit benedictus qui misertus est tui. Indicavitque ei apud quem fuisset operata: et nomen dixit viri, quod Booz vocaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Cui respondit Noëmi: Benedictus sit a Domino: quoniam eamdem gratiam, quam præbuerat vivis, servavit et mortuis. Rursumque ait: Propinquus noster est homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Et ait Ruth: Hoc quoque, inquit, præcepit mihi, ut tamdiu messoribus ejus jungerer, donec omnes segetes meterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Cui dixit socrus: Melius est, filia mea, ut cum puellis ejus exeas ad metendum, ne in alieno agro quispiam resistat tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Juncta est itaque puellis Booz: et tamdiu cum eis messuit, donec hordea et triticum in horreis conderentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Postquam autem reversa est ad socrum suam, audivit ab ea: Filia mea, quæram tibi requiem, et providebo ut bene sit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Booz iste, cujus puellis in agro juncta es, propinquus noster est, et hac nocte aream hordei ventilat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Lavare igitur, et ungere, et induere cultioribus vestimentis, et descende in aream: non te videat homo, donec esum potumque finierit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Quando autem ierit ad dormiendum, nota locum in quo dormiat: veniesque et discooperies pallium, quo operitur a parte pedum, et projicies te, et ibi jacebis: ipse autem dicet quid agere debeas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Quæ respondit: Quidquid præceperis, faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Descenditque in aream, et fecit omnia quæ sibi imperaverat socrus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Cumque comedisset Booz, et bibisset, et factus esset hilarior, issetque ad dormiendum juxta acervum manipulorum, venit abscondite, et discooperto pallio, a pedibus ejus se projecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Et ecce, nocte jam media expavit homo, et conturbatus est: viditque mulierem jacentem ad pedes suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'et ait illi: Quæ es? Illaque respondit: Ego sum Ruth ancilla tua: expande pallium tuum super famulam tuam, quia propinquus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Et ille: Benedicta, inquit, es a Domino, filia, et priorem misericordiam posteriore superasti: quia non est secuta juvenes, pauperes sive divites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Noli ergo metuere, sed quidquid dixeris mihi, faciam tibi. Scit enim omnis populus, qui habitat intra portas urbis meæ, mulierem te esse virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Nec abnuo me propinquum, sed est alius me propinquior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Quiesce hac nocte: et facto mane, si te voluerit propinquitatis jure retinere, bene res acta est: sin autem ille noluerit, ego te absque ulla dubitatione suscipiam, vivit Dominus. Dormi usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Dormivit itaque ad pedes ejus, usque ad noctis abscessum. Surrexit itaque antequam homines se cognoscerent mutuo, et dixit Booz: Cave ne quis noverit quod huc veneris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Et rursum: Expande, inquit, pallium tuum, quo operiris, et tene utraque manu. Qua extendente, et tenente, mensus est sex modios hordei, et posuit super eam. Quæ portans ingressa est civitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'et venit ad socrum suam. Quæ dixit ei: Quid egisti, filia? Narravitque ei omnia, quæ sibi fecisset homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Et ait: Ecce sex modios hordei dedit mihi, et ait: Nolo vacuam te reverti ad socrum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Dixitque Noëmi: Expecta, filia, donec videamus quem res exitum habeat: neque enim cessabit homo, nisi compleverit quod locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Ascendit ergo Booz ad portam, et sedit ibi. Cumque vidisset propinquum præterire, de quo prius sermo habitus est, dixit ad eum: Declina paulisper, et sede hic: vocans eum nomine suo. Qui divertit, et sedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Tollens autem Booz decem viros de senioribus civitatis, dixit ad eos: Sedete hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Quibus sedentibus, locutus est ad propinquum: Partem agri fratris nostri Elimelech vendet Noëmi, quæ reversa est de regione Moabitide:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'quod audire te volui, et tibi dicere coram cunctis sedentibus, et majoribus natu de populo meo. Si vis possidere jure propinquitatis, eme, et posside: sin autem displicet tibi, hoc ipsum indica mihi, ut sciam quid facere debeam: nullus enim est propinquus, excepto te, qui prior es, et me, qui secundus sum. At ille respondit: Ego agrum emam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Cui dixit Booz: Quando emeris agrum de manu mulieris, Ruth quoque Moabitidem, quæ uxor defuncti fuit, debes accipere: ut suscites nomen propinqui tui in hæreditate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Qui respondit: Cedo juri propinquitatis: neque enim posteritatem familiæ meæ delere debeo: tu meo utere privilegio, quo me libenter carere profiteor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Hic autem erat mos antiquitus in Israël inter propinquos, ut siquando alter alteri suo juri cedebat, ut esset firma concessio, solvebat homo calceamentum suum, et dabat proximo suo: hoc erat testimonium cessionis in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Dixit ergo propinquo suo Booz: Tolle calceamentum tuum. Quod statim solvit de pede suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'At ille majoribus natu, et universo populo: Testes vos, inquit, estis hodie, quod possederim omnis quæ fuerunt Elimelech, et Chelion, et Mahalon, tradente Noëmi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'et Ruth Moabitidem, uxorem Mahalon, in conjugium sumpserim, ut suscitem nomen defuncti in hæreditate sua, ne vocabulum ejus de familia sua ac fratribus et populo deleatur. Vos, inquam, hujus rei testes estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Respondit omnis populus, qui erat in porta, et majores natu: Nos testes sumus: faciat Dominus hanc mulierem, quæ ingreditur domum tuam, sicut Rachel et Liam, quæ ædificaverunt domum Israël: ut sit exemplum virtutis in Ephratha, et habeat celebre nomen in Bethlehem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'fiatque domus tua sicut domus Phares, quem Thamar peperit Judæ, de semine quod tibi dederit Dominus ex hac puella.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Tulit itaque Booz Ruth, et accepit uxorem: ingressusque est ad eam, et dedit illi Dominus ut conciperet, et pareret filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Dixeruntque mulieres ad Noëmi: Benedictus Dominus, qui non est passus ut deficeret successor familiæ tuæ, et vocaretur nomen ejus in Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'et habeas qui consoletur animam tuam, et enutriat senectutem: de nuru enim tua natus est, quæ te diligit, et multo tibi melior est, quam si septem haberes filios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Susceptumque Noëmi puerum posuit in sinu suo, et nutricis ac gerulæ fungebatur officio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Vicinæ autem mulieris congratulantes ei, et dicentes: Natus est filius Noëmi: vocaverunt nomen ejus Obed: hic est pater Isai, patris David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Hæ sunt generationes Phares: Phares genuit Esron,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Esron genuit Aram, Aram genuit Aminadab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadab genuit Nahasson, Nahasson genuit Salmon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon genuit Booz, Booz genuit Obed,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed genuit Isai, Isai genuit David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Fuit vir unus de Ramathaimsophim, de monte Ephraim, et nomen ejus Elcana, filius Jeroham, filii Eliu, filii Thohu, filii Suph, Ephrathæus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'et habuit duas uxores, nomen uni Anna, et nomen secundæ Phenenna. Fueruntque Phenennæ filii: Annæ autem non erant liberi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Et ascendebat vir ille de civitate sua statutis diebus, ut adoraret et sacrificaret Domino exercituum in Silo. Erant autem ibi duo filii Heli, Ophni et Phinees, sacerdotes Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Venit ergo dies, et immolavit Elcana, deditque Phenennæ uxori suæ, et cunctis filiis ejus et filiabus, partes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Annæ autem dedit partem unam tristis, quia Annam diligebat. Dominus autem concluserat vulvam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Affligebat quoque eam æmula ejus, et vehementer angebat, in tantum ut exprobraret quod Dominus conclusisset vulvam ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'sicque faciebat per singulos annos: cum redeunte tempore ascenderent ad templum Domini, et sic provocabat eam: porro illa flebat, et non capiebat cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Dixit ergo ei Elcana vir suus: Anna, cur fles? et quare non comedis? et quam ob rem affligitur cor tuum? numquid non ego melior tibi sum, quam decem filii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Surrexit autem Anna postquam comederat et biberat in Silo. Et Heli sacerdote sedente super sellam ante postes templi Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'cum esset Anna amaro animo, oravit ad Dominum, flens largiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'et votum vovit, dicens: Domine exercituum, si respiciens videris afflictionem famulæ tuæ, et recordatus mei fueris, nec oblitus ancillæ tuæ, dederisque servæ tuæ sexum virilem: dabo eum Domino omnibus diebus vitæ ejus, et novacula non ascendet super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Factum est autem, cum illa multiplicaret preces coram Domino, ut Heli observaret os ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Porro Anna loquebatur in corde suo, tantumque labia illius movebantur, et vox penitus non audiebatur. \'stimavit ergo eam Heli temulentam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'dixitque ei: Usquequo ebria eris? digere paulisper vinum, quo mades.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Respondens Anna: Nequaquam, inquit, domine mi: nam mulier infelix nimis ego sum: vinumque et omne quod inebriare potest, non bibi, sed effudi animam meam in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne reputes ancillam tuam quasi unam de filiabus Belial: quia ex multitudine doloris et mœroris mei locuta sum usque in præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Tunc Heli ait ei: Vade in pace: et Deus Israël det tibi petitionem tuam quam rogasti eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Et illa dixit: Utinam inveniat ancilla tua gratiam in oculis tuis. Et abiit mulier in viam suam, et comedit, vultusque illius non sunt amplius in diversa mutati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Et surrexerunt mane, et adoraverunt coram Domino: reversique sunt, et venerunt in domum suam Ramatha. Cognovit autem Elcana Annam uxorem suam: et recordatus est ejus Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Et factum est post circulum dierum, concepit Anna, et peperit filium: vocavitque nomen ejus Samuel, eo quod a Domino postulasset eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Ascendit autem vir ejus Elcana, et omnis domus ejus, ut immolaret Domino hostiam solemnem, et votum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Et Anna non ascendit: dixit enim viro suo: Non vadam donec ablactetur infans, et ducam eum, ut appareat ante conspectum Domini, et maneat ibi jugiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Et ait ei Elcana vir suus: Fac quod bonum tibi videtur, et mane donec ablactes eum: precorque ut impleat Dominus verbum suum. Mansit ergo mulier, et lactavit filium suum, donec amoveret eum a lacte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Et adduxit eum secum, postquam ablactaverat, in vitulis tribus, et tribus modiis farinæ, et amphora vini, et adduxit eum ad domum Domini in Silo. Puer autem erat adhuc infantulus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'et immolaverunt vitulum, et obtulerunt puerum Heli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Et ait Anna: Obsecro mi domine, vivit anima tua, domine: ego sum illa mulier, quæ steti coram te hic orans Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Pro puero isto oravi, et dedit mihi Dominus petitionem meam quam postulavi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Idcirco et ego commodavi eum Domino cunctis diebus quibus fuerit commodatus Domino. Et adoraverunt ibi Dominum. Et oravit Anna, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Exultavit cor meum in Domino, et exaltatum est cornu meum in Deo meo; dilatatum est os meum super inimicos meos: quia lætata sum in salutari tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Non est sanctus, ut est Dominus, neque enim est alius extra te, et non est fortis sicut Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Nolite multiplicare loqui sublimia gloriantes; recedant vetera de ore vestro: quia Deus scientiarum Dominus est, et ipsi præparantur cogitationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Arcus fortium superatus est, et infirmi accincti sunt robore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Repleti prius, pro panibus se locaverunt: et famelici saturati sunt, donec sterilis peperit plurimos: et quæ multos habebat filios, infirmata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Dominus mortificat et vivificat; deducit ad inferos et reducit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Dominus pauperem facit et ditat, humiliat et sublevat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Suscitat de pulvere egenum, et de stercore elevat pauperem: ut sedeat cum principibus, et solium gloriæ teneat. Domini enim sunt cardines terræ, et posuit super eos orbem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Pedes sanctorum suorum servabit, et impii in tenebris conticescent: quia non in fortitudine sua roborabitur vir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Dominum formidabunt adversarii ejus: et super ipsos in cælis tonabit. Dominus judicabit fines terræ, et dabit imperium regi suo, et sublimabit cornu christi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Et abiit Elcana Ramatha, in domum suam: puer autem erat minister in conspectu Domini ante faciem Heli sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Porro filii Heli, filii Belial, nescientes Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'neque officium sacerdotum ad populum: sed quicumque immolasset victimam, veniebat puer sacerdotis, dum coquerentur carnes, et habebat fuscinulam tridentem in manu sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'et mittebat eam in lebetem, vel in caldariam, aut in ollam, sive in cacabum: et omne quod levabat fuscinula, tollebat sacerdos sibi: sic faciebant universo Israëli venientium in Silo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Etiam antequam adolerent adipem, veniebat puer sacerdotis, et dicebat immolanti: Da mihi carnem, ut coquam sacerdoti: non enim accipiam a te carnem coctam, sed crudam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Dicebatque illi immolans: Incendatur primum juxta morem hodie adeps, et tolle tibi quantumcumque desiderat anima tua. Qui respondens aiebat ei: Nequaquam: nunc enim dabis, alioquin tollam vi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Erat ergo peccatum puerorum grande nimis coram Domino: quia retrahebant homines a sacrificio Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel autem ministrabat ante faciem Domini, puer accinctus ephod lineo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Et tunicam parvam faciebat ei mater sua, quam afferebat statutis diebus, ascendens cum viro suo, ut immolaret hostiam solemnem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Et benedixit Heli Elcanæ et uxori ejus: dixitque ei: Reddat tibi Dominus semen de muliere hac, pro fœnore quod commodasti Domino. Et abierunt in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Visitavit ergo Dominus Annam, et concepit, et peperit tres filios, et duas filias: et magnificatus est puer Samuel apud Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Heli autem erat senex valde, et audivit omnia quæ faciebant filii sui universo Israëli, et quomodo dormiebant cum mulieribus quæ observabant ad ostium tabernaculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'et dixit eis: Quare facitis res hujuscemodi quas ego audio, res pessimas, ab omni populo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nolite, filii mei: non enim est bona fama quam ego audio, ut transgredi faciatis populum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Si peccaverit vir in virum, placari ei potest Deus: si autem in Dominum peccaverit vir, quis orabit pro eo? Et non audierunt vocem patris sui: quia voluit Dominus occidere eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Puer autem Samuel proficiebat atque crescebat, et placebat tam Domino quam hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Venit autem vir Dei ad Heli, et ait ad eum: Hæc dicit Dominus: Numquid non aperte revelatus sum domui patris tui, cum essent in \'gypto in domo Pharaonis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Et elegi eum ex omnibus tribubus Israël mihi in sacerdotem, ut ascenderet ad altare meum, et adoleret mihi incensum, et portaret ephod coram me: et dedi domui patris tui omnia de sacrificiis filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Quare calce abjecistis victimam meam, et munera mea quæ præcepi ut offerrentur in templo: et magis honorasti filios tuos quam me, ut comederetis primitias omnis sacrificii Israël populi mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Propterea ait Dominus Deus Israël: Loquens locutus sum, ut domus tua, et domus patris tui, ministraret in conspectu meo usque in sempiternum. Nunc autem dicit Dominus: Absit hoc a me: sed quicumque glorificaverit me, glorificabo eum: qui autem contemnunt me, erunt ignobiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Ecce dies veniunt, et præcidam brachium tuum, et brachium domus patris tui, ut non sit senex in domo tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Et videbis æmulum tuum in templo, in universis prosperis Israël: et non erit senex in domo tua omnibus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Verumtamen non auferam penitus virum ex te ab altari meo: sed ut deficiant oculi tui, et tabescat anima tua: et pars magna domus tuæ morietur cum ad virilem ætatem venerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Hoc autem erit tibi signum, quod venturum est duobus filiis tuis, Ophni et Phinees: in die uno morientur ambo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Et suscitabo mihi sacerdotem fidelem, qui juxta cor meum et animam meam faciet: et ædificabo ei domum fidelem, et ambulabit coram christo meo cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Futurum est autem, ut quicumque remanserit in domo tua, veniat ut oretur pro eo, et offerat nummum argenteum, et tortam panis, dicatque: Dimitte me, obsecro, ad unam partem sacerdotalem, ut comedam buccellam panis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Puer autem Samuel ministrabat Domino coram Heli, et sermo Domini erat pretiosus in diebus illis: non erat visio manifesta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Factum est ergo in die quadam, Heli jacebat in loco suo, et oculi ejus caligaverant, nec poterat videre:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'lucerna Dei antequam extingueretur, Samuel dormiebat in templo Domini, ubi erat arca Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Et vocavit Dominus Samuel. Qui respondens, ait: Ecce ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Et cucurrit ad Heli, et dixit: Ecce ego: vocasti enim me. Qui dixit: Non vocavi: revertere, et dormi. Et abiit, et dormivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Et adjecit Dominus rursum vocare Samuelem. Consurgensque Samuel, abiit ad Heli, et dixit: Ecce ego, quia vocasti me. Qui respondit: Non vocavi te, fili mi: revertere et dormi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Porro Samuel necdum sciebat Dominum, neque revelatus fuerat ei sermo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Et adjecit Dominus, et vocavit adhuc Samuelem tertio. Qui consurgens abiit ad Heli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'et ait: Ecce ego, quia vocasti me. Intellexit ergo Heli quia Dominus vocaret puerum: et ait ad Samuelem: Vade, et dormi: et si deinceps vocaverit te, dices: Loquere, Domine, quia audit servus tuus. Abiit ergo Samuel, et dormivit in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Et venit Dominus, et stetit: et vocavit, sicut vocaverat secundo: Samuel, Samuel. Et ait Samuel: Loquere, Domine, quia audit servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Et dixit Dominus ad Samuelem: Ecce ego facio verbum in Israël, quod quicumque audierit, tinnient ambæ aures ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'In die illa suscitabo adversum Heli omnia quæ locutus sum super domum ejus: incipiam, et complebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Prædixi enim ei quod judicaturus essem domum ejus in æternum propter iniquitatem, eo quod noverat indigne agere filios suos, et non corripuerit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Idcirco juravi domui Heli quod non expietur iniquitas domus ejus victimis et muneribus usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Dormivit autem Samuel usque mane, aperuitque ostia domus Domini. Et Samuel timebat indicare visionem Heli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Vocavit ergo Heli Samuelem, et dixit: Samuel fili mi? Qui respondens ait: Præsto sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Et interrogavit eum: Quis est sermo, quem locutus est Dominus ad te? oro te ne celaveris me: hæc faciat tibi Deus, et hæc addat, si absconderis a me sermonem ex omnibus verbis quæ dicta sunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Indicavit itaque ei Samuel universos sermones, et non abscondit ab eo. Et ille respondit: Dominus est: quod bonum est in oculis suis faciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Crevit autem Samuel, et Dominus erat cum eo, et non cecidit ex omnibus verbis ejus in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Et cognovit universus Israël, a Dan usque Bersabee, quod fidelis Samuel propheta esset Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Et addidit Dominus ut appareret in Silo, quoniam revelatus fuerat Dominus Samueli in Silo juxta verbum Domini. Et evenit sermo Samuelis universo Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Et factum est in diebus illis, convenerunt Philisthiim in pugnam: et egressus est Israël obviam Philisthiim in prælium, et castrametatus est juxta lapidem Adjutorii. Porro Philisthiim venerunt in Aphec,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'et instruxerunt aciem contra Israël. Inito autem certamine, terga vertit Israël Philisthæis: et cæsa sunt in illo certamine passim per agros, quasi quatuor millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Et reversus est populus ad castra: dixeruntque majores natu de Israël: Quare percussit nos Dominus hodie coram Philisthiim? afferamus ad nos de Silo arcam fœderis Domini, et veniat in medium nostri, ut salvet nos de manu inimicorum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Misit ergo populus in Silo, et tulerunt inde arcam fœderis Domini exercituum sedentis super cherubim: erantque duo filii Heli cum arca fœderis Dei, Ophni et Phinees.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Cumque venisset arca fœderis Domini in castra, vociferatus est omnis Israël clamore grandi, et personuit terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Et audierunt Philisthiim vocem clamoris, dixeruntque: Quænam est hæc vox clamoris magni in castris Hebræorum? Et cognoverunt quod arca Domini venisset in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Timueruntque Philisthiim, dicentes: Venit Deus in castra. Et ingemuerunt, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Væ nobis: non enim fuit tanta exultatio heri et nudiustertius: væ nobis. Quis nos salvabit de manu deorum sublimium istorum? hi sunt dii, qui percusserunt \'gyptum omni plaga in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Confortamini, et estote viri, Philisthiim, ne serviatis Hebræis, sicut et illi servierunt vobis: confortamini, et bellate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Pugnaverunt ergo Philisthiim, et cæsus est Israël, et fugit unusquisque in tabernaculum suum: et facta est plaga magna nimis, et ceciderunt de Israël triginta millia peditum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Et arca Dei capta est: duo quoque filii Heli mortui sunt, Ophni et Phinees.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Currens autem vir de Benjamin ex acie, venit in Silo in die illa, scissa veste, et conspersus pulvere caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Cumque ille venisset, Heli sedebat super sellam contra viam spectans. Erat enim cor ejus pavens pro arca Dei. Vir autem ille postquam ingressus est, nuntiavit urbi: et ululavit omnis civitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Et audivit Heli sonitum clamoris, dixitque: Quis est hic sonitus tumultus hujus? At ille festinavit, et venit, et nuntiavit Heli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Heli autem erat nonaginta et octo annorum, et oculi ejus caligaverant, et videre non poterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Et dixit ad Heli: Ego sum qui veni de prælio, et ego qui de acie fugi hodie. Cui ille ait: Quid actum est, fili mi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Respondens autem ille qui nuntiabat: Fugit, inquit, Israël coram Philisthiim, et ruina magna facta est in populo: insuper et duo filii tui mortui sunt, Ophni et Phinees, et arca Dei capta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Cumque ille nominasset arcam Dei, cecidit de sella retrorsum juxta ostium, et fractis cervicibus mortuus est. Senex enim erat vir et grandævus: et ipse judicavit Israël quadraginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Nurus autem ejus, uxor Phinees, prægnans erat, vicinaque partui: et audito nuntio quod capta esset arca Dei, et mortuus esset socer suus et vir suus, incurvavit se et peperit: irruerant enim in eam dolores subiti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'In ipso autem momento mortis ejus, dixerunt ei quæ stabant circa eam: Ne timeas, quia filium peperisti. Quæ non respondit eis, neque animadvertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Et vocabit puerum Ichabod, dicens: Translata est gloria de Israël, quia capta est arca Dei, et pro socero suo et pro viro suo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'et ait: Translata est gloria ab Israël, eo quod capta esset arca Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Philisthiim autem tulerunt arcam Dei, et asportaverunt eam a lapide Adjutorii in Azotum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Tuleruntque Philisthiim arcam Dei, et intulerunt eam in templum Dagon, et statuerunt eam juxta Dagon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Cumque surrexissent diluculo Azotii altera die, ecce Dagon jacebat pronus in terra ante arcam Domini: et tulerunt Dagon, et restituerunt eum in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Rursumque mane die altera consurgentes, invenerunt Dagon jacentem super faciem suam in terra coram arca Domini: caput autem Dagon, et duæ palmæ manuum ejus abscissæ erant super limen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'porro Dagon solus truncus remanserat in loco suo. Propter hanc causam non calcant sacerdotes Dagon, et omnes qui ingrediuntur templum ejus, super limen Dagon in Azoto, usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Aggravata est autem manus Domini super Azotios, et demolitus est eos: et percussit in secretiori parte natium Azotum, et fines ejus. Et ebullierunt villæ et agri in medio regionis illius, et nati sunt mures et facta est confusio mortis magnæ in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Videntes autem viri Azotii hujuscemodi plagam, dixerunt: Non maneat arca Dei Israël apud nos: quoniam dura est manus ejus super nos, et super Dagon deum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Et mittentes congregaverunt omnes satrapas Philisthinorum ad se, et dixerunt: Quid faciemus de arca Dei Israël? Responderuntque Gethæi: Circumducatur arca Dei Israël. Et circumduxerunt arcam Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Illis autem circumducentibus eam, fiebat manus Domini per singulas civitates interfectionis magnæ nimis: et percutiebat viros uniuscujusque urbis, a parvo usque ad majorem, et computrescebant prominentes extales eorum. Inieruntque Gethæi consilium, et fecerunt sibi sedes pelliceas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Miserunt ergo arcam Dei in Accaron. Cumque venisset arca Dei in Accaron, exclamaverunt Accaronitæ, dicentes: Adduxerunt ad nos arcam Dei Israël ut interficiat nos et populum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Miserunt itaque et congregaverunt omnes satrapas Philisthinorum: qui dixerunt: Dimittite arcam Dei Israël, et revertatur in locum suum, et non interficiat nos cum populo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Fiebat enim pavor mortis in singulis urbibus, et gravissima valde manus Dei. Viri quoque qui mortui non fuerant, percutiebantur in secretiori parte natium: et ascendebat ululatus uniuscujusque civitatis in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Fuit ergo arca Domini in regione Philisthinorum septem mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Et vocaverunt Philisthiim sacerdotes et divinos, dicentes: Quid faciemus de arca Domini? indicate nobis quomodo remittamus eam in locum suum. Qui dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Si remittitis arcam Dei Israël, nolite dimittere eam vacuam, sed quod debetis, reddite ei pro peccato, et tunc curabimini: et scietis quare non recedat manus ejus a vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Qui dixerunt: Quid est quod pro delicto reddere debeamus ei? Responderuntque illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Juxta numerum provinciarum Philisthinorum quinque anos aureos facietis, et quinque mures aureos: quia plaga una fuit omnibus vobis, et satrapis vestris. Facietisque similitudines anorum vestrorum, et similitudines murium, qui demoliti sunt terram: et dabitis Deo Israël gloriam, si forte relevet manum suam a vobis, et a diis vestris, et a terra vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Quare aggravatis corda vestra, sicut aggravavit \'gyptus et Pharao cor suum? nonne postquam percussus est, tunc dimisit eos, et abierunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Nunc ergo arripite et facite plaustrum novum unum: et duas vaccas fœtas, quibus non est impositum jugum, jungite in plaustro, et recludite vitulos earum domi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Tolletisque arcam Domini, et ponetis in plaustro, et vasa aurea quæ exsolvistis ei pro delicto, ponetis in capsellam ad latus ejus: et dimittite eam ut vadat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Et aspicietis: et si quidem per viam finium suorum ascenderit contra Bethsames, ipse fecit nobis hoc malum grande: sin autem, minime: sciemus quia nequaquam manus ejus tetigit nos, sed casu accidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Fecerunt ergo illi hoc modo: et tollentes duas vaccas quæ lactabant vitulos, junxerunt ad plaustrum, vitulosque earum concluserunt domi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Et posuerunt arcam Dei super plaustrum, et capsellam quæ habebat mures aureos et similitudines anorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Ibant autem in directum vaccæ per viam quæ ducit Bethsames, et itinere uno gradiebantur, pergentes et mugientes: et non declinabant neque ad dextram neque ad sinistram: sed et satrapæ Philisthiim sequebantur usque ad terminos Bethsames.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Porro Bethsamitæ metebant triticum in valle: et elevantes oculos suos, viderunt arcam, et gavisi sunt cum vidissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Et plaustrum venit in agrum Josue Bethsamitæ, et stetit ibi. Erat autem ibi lapis magnus, et conciderunt ligna plaustri, vaccasque imposuerunt super ea holocaustum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Levitæ autem deposuerunt arcam Dei, et capsellam quæ erat juxta eam, in qua erant vasa aurea, et posuerunt super lapidem grandem. Viri autem Bethsamitæ obtulerunt holocausta, et immolaverunt victimas in die illa Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Et quinque satrapæ Philisthinorum viderunt, et reversi sunt in Accaron in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Hi sunt autem ani aurei quos reddiderunt Philisthiim pro delicto, Domino: Azotus unum, Gaza unum, Ascalon unum, Geth unum, Accaron unum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'et mures aureos secundum numerum urbium Philisthiim, quinque provinciarum, ab urbe murata usque ad villam quæ erat absque muro, et usque ad Abelmagnum, super quem posuerunt arcam Domini, quæ erat usque in illum diem in agro Josue Bethsamitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Percussit autem de viris Bethsamitibus, eo quod vidissent arcam Domini: et percussit de populo septuaginta viros, et quinquaginta millia plebis. Luxitque populus, eo quod Dominus percussisset plebem plaga magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Et dixerunt viri Bethsamitæ: Quis poterit stare in conspectu Domini Dei sancti hujus? et ad quem ascendet a nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Miseruntque nuntios ad habitatores Cariathiarim, dicentes: Reduxerunt Philisthiim arcam Domini: descendite, et reducite eam ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Venerunt ergo viri Cariathiarim, et reduxerunt arcam Domini, et intulerunt eam in domum Abinadab in Gabaa: Eleazarum autem filium ejus sanctificaverunt, ut custodiret arcam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Et factum est, ex qua die mansit arca Domini in Cariathiarim, multiplicati sunt dies (erat quippe jam annus vigesimus), et requievit omnis domus Israël post Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Ait autem Samuel ad universam domum Israël, dicens: Si in toto corde vestro revertimini ad Dominum, auferte deos alienos de medio vestri, Baalim et Astaroth: et præparate corda vestra Domino, et servite ei soli, et eruet vos de manu Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Abstulerunt ergo filii Israël Baalim et Astaroth, et servierunt Domino soli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Dixit autem Samuel: Congregate universum Israël in Masphath, ut orem pro vobis Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Et convenerunt in Masphath: hauseruntque aquam, et effuderunt in conspectu Domini: et jejunaverunt in die illa atque dixerunt ibi: Peccavimus Domino. Judicavitque Samuel filios Israël in Masphath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Et audierunt Philisthiim quod congregati essent filii Israël in Masphath, et ascenderunt satrapæ Philisthinorum ad Israël. Quod cum audissent filii Israël, timuerunt a facie Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Dixeruntque ad Samuelem: Ne cesses pro nobis clamare ad Dominum Deum nostrum, ut salvet nos de manu Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Tulit autem Samuel agnum lactentem unum, et obtulit illum holocaustum integrum Domino: et clamavit Samuel ad Dominum pro Israël, et exaudivit eum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Factum est autem, cum Samuel offerret holocaustum, Philisthiim iniere prælium contra Israël: intonuit autem Dominus fragore magno in die illa super Philisthiim, et exterruit eos, et cæsi sunt a facie Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Egressique viri Israël de Masphath, persecuti sunt Philisthæos, et percusserunt eos usque ad locum qui erat subter Bethchar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tulit autem Samuel lapidem unum, et posuit eum inter Masphath et inter Sen: et vocavit nomen loci illius, Lapis adjutorii. Dixitque: Hucusque auxiliatus est nobis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Et humiliati sunt Philisthiim, nec apposuerunt ultra ut venirent in terminos Israël. Facta est itaque manus Domini super Philisthæos cunctis diebus Samuelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Et redditæ sunt urbes quas tulerant Philisthiim ab Israël, Israëli, ab Accaron usque Geth, et terminos suos: liberavitque Israël de manu Philisthinorum, eratque pax inter Israël et Amorrhæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Judicabat quoque Samuel Israëlem cunctis diebus vitæ suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'et ibat per singulos annos circuiens Bethel et Galgala et Masphath, et judicabat Israëlem in supradictis locis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Revertebaturque in Ramatha: ibi enim erat domus ejus, et ibi judicabat Israëlem: ædificavit etiam ibi altare Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Factum est autem cum senuisset Samuel, posuit filios suos judices Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Fuitque nomen filii ejus primogeniti Joël: et nomen secundi Abia, judicum in Bersabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Et non ambulaverunt filii illius in viis ejus: sed declinaverunt post avaritiam, acceperuntque munera, et perverterunt judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Congregati ergo universi majores natu Israël, venerunt ad Samuelem in Ramatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Dixeruntque ei: Ecce tu senuisti, et filii tui non ambulant in viis tuis: constitue nobis regem, ut judicet nos, sicut et universæ habent nationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Displicuit sermo in oculis Samuelis, eo quod dixissent: Da nobis regem, ut judicet nos. Et oravit Samuel ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Dixit autem Dominus ad Samuelem: Audi vocem populi in omnibus quæ loquuntur tibi: non enim te abjecerunt, sed me, ne regnem super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Juxta omnia opera sua quæ fecerunt, a die qua eduxi eos de \'gypto usque ad diem hanc: sicut dereliquerunt me, et servierunt diis alienis, sic faciunt etiam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Nunc ergo vocem eorum audi: verumtamen contestare eos, et prædic eis jus regis, qui regnaturus est super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Dixit itaque Samuel omnia verba Domini ad populum, qui petierat a se regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Et ait: Hoc erit jus regis, qui imperaturus est vobis: filios vestros tollet, et ponet in curribus suis: facietque sibi equites et præcursores quadrigarum suarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'et constituet sibi tribunos, et centuriones, et aratores agrorum suorum, et messores segetum, et fabros armorum et curruum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Filias quoque vestras faciet sibi unguentarias, et focarias, et panificas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Agros quoque vestros, et vineas, et oliveta optima tollet, et dabit servis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Sed et segetes vestras et vinearum reditus addecimabit, ut det eunuchis et famulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Servos etiam vestros, et ancillas, et juvenes optimos, et asinos, auferet, et ponet in opere suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Greges quoque vestros addecimabit, vosque eritis ei servi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Et clamabitis in die illa a facie regis vestri, quem elegistis vobis: et non exaudiet vos Dominus in die illa, quia petistis vobis regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Noluit autem populus audire vocem Samuelis, sed dixerunt: Nequaquam: rex enim erit super nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'et erimus nos quoque sicut omnes gentes: et judicabit nos rex noster, et egredietur ante nos, et pugnabit bella nostra pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Et audivit Samuel omnia verba populi, et locutus est ea in auribus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Dixit autem Dominus ad Samuelem: Audi vocem eorum, et constitue super eos regem. Et ait Samuel ad viros Israël: Vadat unusquisque in civitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Et erat vir de Benjamin nomine Cis, filius Abiel, filii Seror, filii Bechorath, filii Aphia, filii viri Jemini, fortis robore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Et erat ei filius vocabulo Saul, electus et bonus: et non erat vir de filiis Israël melior illo: ab humero et sursum eminebat super omnem populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Perierant autem asinæ Cis patris Saul: et dixit Cis ad Saul filium suum: Tolle tecum unum de pueris, et consurgens vade, et quære asinas. Qui cum transissent per montem Ephraim');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'et per terram Salisa, et non invenissent, transierunt etiam per terram Salim, et non erant: sed et per terram Jemini, et minime repererunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Cum autem venissent in terram Suph, dixit Saul ad puerum qui erat cum eo: Veni et revertamur, ne forte dimiserit pater meus asinas, et sollicitus sit pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Qui ait ei: Ecce vir Dei est in civitate hac, vir nobilis: omne quod loquitur, sine ambiguitate venit. Nunc ergo eamus illuc, si forte indicet nobis de via nostra, propter quam venimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Dixitque Saul ad puerum suum: Ecce ibimus: quid feremus ad virum Dei? panis defecit in sitarciis nostris, et sportulam non habemus ut demus homini Dei, nec quidquam aliud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Rursum puer respondit Sauli, et ait: Ecce inventa est in manu mea quarta pars stateris argenti: demus homini Dei, ut indicet nobis viam nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Olim in Israël sic loquebatur unusquisque vadens consulere Deum: Venite, et eamus ad videntem. Qui enim propheta dicitur hodie, vocabatur olim videns.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Et dixit Saul ad puerum suum: Optimus sermo tuus. Veni, eamus. Et ierunt in civitatem in qua erat vir Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Cumque ascenderent clivum civitatis, invenerunt puellas egredientes ad hauriendam aquam, et dixerunt eis: Num hic est videns?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Quæ respondentes, dixerunt illis: Hic est: ecce ante te, festina nunc: hodie enim venit in civitatem, quia sacrificium est hodie populi in excelso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Ingredientes urbem, statim invenietis eum antequam ascendat excelsum ad vescendum, neque enim comesurus est populus donec ille veniat: quia ipse benedicit hostiæ, et deinceps comedunt qui vocati sunt. Nunc ergo conscendite, quia hodie reperietis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Et ascenderunt in civitatem. Cumque illi ambularent in medio urbis, apparuit Samuel egrediens obviam eis, ut ascenderet in excelsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Dominus autem revelaverat auriculam Samuelis ante unam diem quam veniret Saul, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Hac ipsa hora quæ nunc est, cras mittam virum ad te de terra Benjamin, et unges eum ducem super populum meum Israël: et salvabit populum meum de manu Philisthinorum, quia respexi populum meum: venit enim clamor eorum ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Cumque aspexisset Samuel Saulem, Dominus dixit ei: Ecce vir quem dixeram tibi: iste dominabitur populo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Accessit autem Saul ad Samuelem in medio portæ, et ait: Indica, oro, mihi, ubi est domus videntis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Et respondit Samuel Sauli, dicens: Ego sum videns: ascende ante me in excelsum, ut comedatis mecum hodie, et dimittam te mane: et omnia quæ sunt in corde tuo indicabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Et de asinis quas nudiustertius perdidisti, ne sollicitus sis, quia inventæ sunt. Et cujus erunt optima quæque Israël? nonne tibi et omni domui patris tui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Respondens autem Saul, ait: Numquid non filius Jemini ego sum de minima tribu Israël, et cognatio mea novissima inter omnes familias de tribu Benjamin? quare ergo locutus es mihi sermonem istum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Assumens itaque Samuel Saulem et puerum ejus, introduxit eos in triclinium, et dedit eis locum in capite eorum qui fuerant invitati: erant enim quasi triginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Dixitque Samuel coco: Da partem quam dedi tibi, et præcepi ut reponeres seorsum apud te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Levavit autem cocus armum, et posuit ante Saul. Dixitque Samuel: Ecce quod remansit: pone ante te, et comede, quia de industria servatum est tibi quando populum vocavi. Et comedit Saul cum Samuele in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Et descenderunt de excelso in oppidum, et locutus est cum Saule in solario: stravitque Saul in solario, et dormivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Cumque mane surrexissent, et jam elucesceret, vocavit Samuel Saulem in solario, dicens: Surge, et dimittam te. Et surrexit Saul: egressique sunt ambo, ipse videlicet, et Samuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Cumque descenderent in extrema parte civitatis, Samuel dixit ad Saul: Dic puero ut antecedat nos et transeat: tu autem subsiste paulisper, ut indicem tibi verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tulit autem Samuel lenticulam olei, et effudit super caput ejus: et deosculatus est eum, et ait: Ecce unxit te Dominus super hæreditatem suam in principem, et liberabis populum suum de manibus inimicorum ejus qui in circuitu ejus sunt. Et hoc tibi signum, quia unxit te Deus in principem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Cum abieris hodie a me, invenies duos viros juxta sepulchrum Rachel in finibus Benjamin, in meridie: dicentque tibi: Inventæ sunt asinæ ad quas ieras perquirendas: et intermissis pater tuus asinis, sollicitus est pro vobis, et dicit: Quid faciam de filio meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Cumque abieris inde, et ultra transieris, et veneris ad quercum Thabor, invenient te ibi tres viri ascendentes ad Deum in Bethel, unus portans tres hædos, et alius tres tortas panis, et alius portans lagenam vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Cumque te salutaverint, dabunt tibi duos panes, et accipies de manu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Post hæc venies in collem Dei, ubi est statio Philisthinorum: et cum ingressus fueris ibi urbem, obvium habebis gregem prophetarum descendentium de excelso, et ante eos psalterium, et tympanum, et tibiam, et citharam, ipsosque prophetantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Et insiliet in te spiritus Domini, et prophetabis cum eis, et mutaberis in virum alium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Quando ergo evenerint signa hæc omnia tibi, fac quæcumque invenerit manus tua, quia Dominus tecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Et descendes ante me in Galgala (ego quippe descendam ad te), ut offeras oblationem, et immoles victimas pacificas: septem diebus expectabis, donec veniam ad te, et ostendam tibi quid facias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Itaque cum avertisset humerum suum ut abiret a Samuele, immutavit ei Deus cor aliud, et venerunt omnia signa hæc in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Veneruntque ad prædictum collem, et ecce cuneus prophetarum obvius ei: et insiluit super eum spiritus Domini, et prophetavit in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Videntes autem omnes qui noverant eum heri et nudiustertius quod esset cum prophetis, et prophetaret, dixerunt ad invicem: Quænam res accidit filio Cis? num et Saul inter prophetas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Responditque alius ad alterum, dicens: Et quis pater eorum? Propterea versum est in proverbium: Num et Saul inter prophetas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Cessavit autem prophetare, et venit ad excelsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Dixitque patruus Saul ad eum, et ad puerum ejus: Quo abistis? Qui responderunt: Quærere asinas: quas cum non reperissemus, venimus ad Samuelem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Et dixit ei patruus suus: Indica mihi quid dixerit tibi Samuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Et ait Saul ad patruum suum: Indicavit nobis quia inventæ essent asinæ. De sermone autem regni non indicavit ei quem locutus fuerat ei Samuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Et convocavit Samuel populum ad Dominum in Maspha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'et ait ad filios Israël: Hæc dicit Dominus Deus Israël: Ego eduxi Israël de \'gypto, et erui vos de manu \'gyptiorum, et de manu omnium regum qui affligebant vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Vos autem hodie projecistis Deum vestrum, qui solus salvavit vos de universis malis et tribulationibus vestris: et dixistis: Nequaquam: sed regem constitue super nos. Nunc ergo state coram Domino per tribus vestras, et per familias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Et applicuit Samuel omnes tribus Israël, et cecidit sors tribus Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Et applicuit tribum Benjamin et cognationes ejus, et cecidit cognatio Metri: et pervenit usque ad Saul filium Cis. Quæsierunt ergo eum, et non est inventus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Et consuluerunt post hæc Dominum utrumnam venturus esset illuc. Responditque Dominus: Ecce absconditus est domi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Cucurrerunt itaque et tulerunt eum inde: stetitque in medio populi, et altior fuit universo populo ab humero et sursum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Et ait Samuel ad omnem populum: Certe videtis quem elegit Dominus, quoniam non sit similis illi in omni populo. Et clamavit omnis populus, et ait: Vivat rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Locutus est autem Samuel ad populum legem regni, et scripsit in libro, et reposuit coram Domino: et dimisit Samuel omnem populum, singulos in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Sed et Saul abiit in domum suam in Gabaa: et abiit cum eo pars exercitus, quorum tetigerat Deus corda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Filii vero Belial dixerunt: Num salvare nos poterit iste? Et despexerunt eum, et non attulerunt ei munera: ille vero dissimulabat se audire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Et factum est quasi post mensem, ascendit Naas Ammonites, et pugnare cœpit adversum Jabes Galaad. Dixeruntque omnes viri Jabes ad Naas: Habeto nos fœderatos, et serviemus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Et respondit ad eos Naas Ammonites: In hoc feriam vobiscum fœdus, ut eruam omnium vestrum oculos dextros, ponamque vos opprobrium in universo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Et dixerunt ad eum seniores Jabes: Concede nobis septem dies, ut mittamus nuntios ad universos terminos Israël, et si non fuerit qui defendat nos, egrediemur ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Venerunt ergo nuntii in Gabaa Saulis: et locuti sunt verba hæc, audiente populo: et levavit omnis populus vocem suam, et flevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Et ecce Saul veniebat, sequens boves de agro, et ait: Quid habet populus quod plorat? Et narraverunt ei verba virorum Jabes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Et insilivit spiritus Domini in Saul cum audisset verba hæc, et iratus est furor ejus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Et assumens utrumque bovem, concidit in frustra, misitque in omnes terminos Israël per manum nuntiorum, dicens: Quicumque non exierit, et secutus fuerit Saul et Samuel, sic fiet bobus ejus. Invasit ergo timor Domini populum, et egressi sunt quasi vir unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Et recensuit eos in Bezech: fueruntque filiorum Israël trecenta millia, virorum autem Juda triginta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Et dixerunt nuntiis qui venerant: Sic dicetis viris qui sunt in Jabes Galaad: Cras erit vobis salus, cum incaluerit sol. Venerunt ergo nuntii, et annuntiaverunt viris Jabes: qui lætati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Et dixerunt: Mane exibimus ad vos: et facietis nobis omne quod placuerit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Et factum est, cum dies crastinus venisset, constituit Saul populum in tres partes: et ingressus est media castra in vigilia matutina, et percussit Ammon usque dum incalesceret dies: reliqui autem dispersi sunt, ita ut non relinquerentur in eis duo pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Et ait populus ad Samuelem: Quis est iste qui dixit: Saul num regnabit super nos? Date viros, et interficiemus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Et ait Saul: Non occidetur quisquam in die hac, quia hodie fecit Dominus salutem in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Dixit autem Samuel ad populum: Venite, et eamus in Galgala, et innovemus ibi regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Et perrexit omnis populus in Galgala, et fecerunt ibi regem Saul coram Domino in Galgala, et immolaverunt ibi victimas pacificas coram Domino. Et lætatus est ibi Saul, et cuncti viri Israël nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Dixit autem Samuel ad universum Israël: Ecce audivi vocem vestram juxta omnia quæ locuti estis ad me, et constitui super vos regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Et nunc rex graditur ante vos: ego autem senui, et incanui: porro filii mei vobiscum sunt: itaque conversatus coram vobis ab adolescentia mea usque ad hanc diem, ecce præsto sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Loquimini de me coram Domino, et coram christo ejus, utrum bovem cujusquam tulerim, aut asinum: si quempiam calumniatus sum, si oppressi aliquem, si de manu cujusquam munus accepi: et contemnam illud hodie, restituamque vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Et dixerunt: Non es calumniatus nos, neque oppressisti, neque tulisti de manu alicujus quippiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Dixitque ad eos: Testis est Dominus adversum vos, et testis christus ejus in die hac, quia non inveneritis in manu mea quippiam. Et dixerunt: Testis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Et ait Samuel ad populum: Dominus, qui fecit Moysen et Aaron, et eduxit patres nostros de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Nunc ergo state, ut judicio contendam adversum vos coram Domino de omnibus misericordiis Domini quas fecit vobiscum et cum patribus vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'quomodo Jacob ingressus est in \'gyptum, et clamaverunt patres vestri ad Dominum: et misit Dominus Moysen et Aaron, et eduxit patres vestros de \'gypto, et collocavit eos in loco hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Qui obliti sunt Domini Dei sui, et tradidit eos in manu Sisaræ magistri militiæ Hasor, et in manu Philisthinorum, et in manu regis Moab: et pugnaverunt adversum eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Postea autem clamaverunt ad Dominum, et dixerunt: Peccavimus, quia dereliquimus Dominum, et servivimus Baalim et Astaroth: nunc ergo erue nos de manu inimicorum nostrorum, et serviemus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Et misit Dominus Jerobaal, et Badan, et Jephte, et Samuel, et eruit vos de manu inimicorum vestrorum per circuitum, et habitastis confidenter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Videntes autem quod Naas rex filiorum Ammon venisset adversum vos, dixistis mihi: Nequaquam, sed rex imperabit nobis: cum Dominus Deus vester regnaret in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nunc ergo præsto est rex vester, quem elegistis et petistis: ecce dedit vobis Dominus regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Si timueritis Dominum, et servieritis ei, et audieritis vocem ejus, et non exasperaveritis os Domini, eritis et vos, et rex qui imperat vobis, sequentes Dominum Deum vestrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'si autem non audieritis vocem Domini, sed exasperaveritis sermones ejus, erit manus Domini super vos, et super patres vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Sed et nunc state, et videte rem istam grandem quam facturus est Dominus in conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Numquid non messis tritici est hodie? invocabo Dominum, et dabit voces et pluvias: et scietis, et videbitis, quia grande malum feceritis vobis in conspectu Domini, petentes super vos regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Et clamavit Samuel ad Dominum, et dedit Dominus voces et pluvias in illa die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Et timuit omnis populus nimis Dominum et Samuelem, et dixit universus populus ad Samuelem: Ora pro servis tuis ad Dominum Deum tuum, ut non moriamur: addidimus enim universis peccatis nostris malum, ut peteremus nobis regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Dixit autem Samuel ad populum: Nolite timere: vos fecistis universum malum hoc, verumtamen nolite recedere a tergo Domini, sed servite Domino in omni corde vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Et nolite declinare post vana, quæ non proderunt vobis, neque eruent vos, quia vana sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Et non derelinquet Dominus populum suum propter nomen suum magnum: quia juravit Dominus facere vos sibi populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Absit autem a me hoc peccatum in Dominum, ut cessem orare pro vobis, et docebo vos viam bonam et rectam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Igitur timete Dominum, et servite ei in veritate, et ex toto corde vestro: vidistis enim magnifica quæ in vobis gesserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Quod si perseveraveritis in malitia, et vos et rex vester pariter peribitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Filius unius anni erat Saul cum regnare cœpisset: duobus autem annis regnavit super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Et elegit sibi Saul tria millia de Israël: et erant cum Saul duo millia in Machmas, et in monte Bethel: mille autem cum Jonatha in Gabaa Benjamin: porro ceterum populum remisit unumquemque in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Et percussit Jonathas stationem Philisthinorum quæ erat in Gabaa. Quod cum audissent Philisthiim, Saul cecinit buccina in omni terra, dicens: Audiant Hebræi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Et universus Israël audivit hujuscemodi famam: Percussit Saul stationem Philisthinorum, et erexit se Israël adversus Philisthiim. Clamavit ergo populus post Saul in Galgala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Et Philisthiim congregati sunt ad præliandum contra Israël, triginta millia curruum, et sex millia equitum, et reliquum vulgus, sicut arena quæ est in littore maris plurima. Et ascendentes castrametati sunt in Machmas ad orientem Bethaven.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Quod cum vidissent viri Israël se in arcto positos (afflictus enim erat populus), absconderunt se in speluncis, et in abditis, in petris quoque, et in antris, et in cisternis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Hebræi autem transierunt Jordanem in terram Gad et Galaad. Cumque adhuc esset Saul in Galgala, universus populus perterritus est qui sequebatur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Et expectavit septem diebus juxta placitum Samuelis, et non venit Samuel in Galgala, dilapsusque est populus ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Ait ergo Saul: Afferte mihi holocaustum et pacifica. Et obtulit holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Cumque complesset offerens holocaustum, ecce Samuel veniebat: et egressus est Saul obviam ei ut salutaret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Locutusque est ad eum Samuel: Quid fecisti? Respondit Saul: Quia vidi quod populus dilaberetur a me, et tu non veneras juxta placitos dies, porro Philisthiim congregati fuerant in Machmas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'dixi: Nunc descendent Philisthiim ad me in Galgala, et faciem Domini non placavi. Necessitate compulsus, obtuli holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Dixitque Samuel ad Saul: Stulte egisti, nec custodisti mandata Domini Dei tui quæ præcepit tibi. Quod si non fecisses, jam nunc præparasset Dominus regnum tuum super Israël in sempiternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'sed nequaquam regnum tuum ultra consurget. Quæsivit Dominus sibi virum juxta cor suum: et præcepit ei Dominus ut esset dux super populum suum, eo quod non servaveris quæ præcepit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Surrexit autem Samuel, et ascendit de Galgalis in Gabaa Benjamin. Et reliqui populi ascenderunt post Saul obviam populo, qui expugnabant eos venientes de Galgala in Gabaa, in colle Benjamin. Et recensuit Saul populum qui inventi fuerant cum eo, quasi sexcentos viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Et Saul et Jonathas filius ejus, populusque qui inventus fuerat cum eis, erat in Gabaa Benjamin: porro Philisthiim consederant in Machmas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Et egressi sunt ad prædandum de castris Philisthinorum tres cunei. Unus cuneus pergebat contra viam Ephra ad terram Sual:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'porro alius ingrediebatur per viam Beth-horon: tertius autem verterat se ad iter termini imminentis valli Seboim contra desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Porro faber ferrarius non inveniebatur in omni terra Israël: caverant enim Philisthiim, ne forte facerent Hebræi gladium aut lanceam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Descendebat ergo omnis Israël ad Philisthiim, ut exacueret unusquisque vomerem suum, et ligonem, et securim, et sarculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Retusæ itaque erant acies vomerum, et ligonum, et tridentum, et securium, usque ad stimulum corrigendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Cumque venisset dies prælii, non est inventus ensis et lancea in manu totius populi qui erat cum Saule et Jonatha, excepto Saul et Jonatha filio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Egressa est autem statio Philisthiim, ut transcenderet in Machmas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Et accidit quadam die ut diceret Jonathas filius Saul ad adolescentem armigerum suum: Veni, et transeamus ad stationem Philisthinorum, quæ est trans locum illum. Patri autem suo hoc ipsum non indicavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Porro Saul morabatur in extrema parte Gabaa sub malogranato, quæ erat in Magron: et erat populus cum eo quasi sexcentorum virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Et Achias filius Achitob fratris Ichabod filii Phinees, qui ortus fuerat ex Heli sacerdote Domini in Silo, portabat ephod. Sed et populus ignorabat quo isset Jonathas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Erant autem inter ascensus per quos nitebatur Jonathas transire ad stationem Philisthinorum, eminentes petræ ex utraque parte, et quasi in modum dentium scopuli hinc et inde prærupti: nomen uni Boses, et nomen alteri Sene:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'unus scopulus prominens ad aquilonem ex adverso Machmas, et alter ad meridiem contra Gabaa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Dixit autem Jonathas ad adolescentem armigerum suum: Veni, transeamus ad stationem incircumcisorum horum, si forte faciat Dominus pro nobis: quia non est Domino difficile salvare, vel in multis, vel in paucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Dixitque ei armiger suus: Fac omnia quæ placent animo tuo: perge quo cupis, et ero tecum ubicumque volueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Et ait Jonathas: Ecce nos transimus ad viros istos. Cumque apparuerimus eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'si taliter locuti fuerint ad nos: Manete donec veniamus ad vos: stemus in loco nostro, nec ascendamus ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Si autem dixerint: Ascendite ad nos: ascendamus, quia tradidit eos Dominus in manibus nostris: hoc erit nobis signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Apparuit igitur uterque stationi Philisthinorum: dixeruntque Philisthiim: En Hebræi egrediuntur de cavernis in quibus absconditi fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Et locuti sunt viri de statione ad Jonathan et ad armigerum ejus, dixeruntque: Ascendite ad nos, et ostendemus vobis rem. Et ait Jonathas ad armigerum suum: Ascendamus: sequere me: tradidit enim Dominus eos in manus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Ascendit autem Jonathas manibus et pedibus reptans, et armiger ejus post eum. Itaque alii cadebant ante Jonathan, alios armiger ejus interficiebat sequens eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Et facta est plaga prima qua percussit Jonathas et armiger ejus, quasi viginti virorum in media parte jugeri quam par boum in die arare consuevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Et factum est miraculum in castris per agros: sed et omnis populus stationis eorum qui ierant ad prædandum, obstupuit, et conturbata est terra: et accidit quasi miraculum a Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Et respexerunt speculatores Saul qui erant in Gabaa Benjamin, et ecce multitudo prostrata, et huc illucque diffugiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Et ait Saul populo qui erat cum eo: Requirite, et videte quis abierit ex nobis. Cumque requisissent, repertum est non adesse Jonathan et armigerum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Et ait Saul ad Achiam: Applica arcam Dei. (Erat enim ibi arca Dei in die illa cum filiis Israël.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Cumque loqueretur Saul ad sacerdotem, tumultus magnus exortus est in castris Philisthinorum: crescebatque paulatim, et clarius resonabat. Et ait Saul ad sacerdotem: Contrahe manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Conclamavit ergo Saul, et omnis populus qui erat cum eo, et venerunt usque ad locum certaminis: et ecce versus fuerat gladius uniuscujusque ad proximum suum, et cædes magna nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Sed et Hebræi qui fuerant cum Philisthiim heri et nudiustertius, ascenderantque cum eis in castris, reversi sunt ut essent cum Israël qui erant cum Saul et Jonatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Omnes quoque Israëlitæ qui se absconderant in monte Ephraim, audientes quod fugissent Philisthæi, sociaverunt se cum suis in prælio. Et erant cum Saul quasi decem millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Et salvavit Dominus in die illa Israël: pugna autem pervenit usque ad Bethaven.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Et viri Israël sociati sunt sibi in die illa: adjuravit autem Saul populum, dicens: Maledictus vir qui comederit panem usque ad vesperam, donec ulciscar de inimicis meis. Et non manducavit universus populus panem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'omneque terræ vulgus venit in saltum, in quo erat mel super faciem agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Ingressus est itaque populus saltum, et apparuit fluens mel, nullusque applicuit manum ad os suum: timebat enim populus juramentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Porro Jonathas non audierat cum adjuraret pater ejus populum: extenditque summitatem virgæ quam habebat in manu, et intinxit in favum mellis: et convertit manum suam ad os suum, et illuminati sunt oculi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Respondensque unus de populo, ait: Jurejurando constrinxit pater tuus populum, dicens: Maledictus vir qui comederit panem hodie. (Defecerat autem populus.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Dixitque Jonathas: Turbavit pater meus terram: vidistis ipsi quia illuminati sunt oculi mei, eo quod gustaverim paululum de melle isto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'quanto magis si comedisset populus de præda inimicorum suorum, quam reperit? nonne major plaga facta fuisset in Philisthiim?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Percusserunt ergo in die illa Philisthæos a Machmis usque in Ajalon. Defatigatus est autem populus nimis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'et versus ad prædam tulit oves, et boves, et vitulos, et mactaverunt in terra: comeditque populus cum sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Nuntiaverunt autem Sauli dicentes quod populus peccasset Domino, comedens cum sanguine. Qui ait: Prævaricati estis: volvite ad me jam nunc saxum grande.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Et dixit Saul: Dispergimini in vulgus, et dicite eis ut adducat ad me unusquisque bovem suum et arietem, et occidite super istud, et vescimini, et non peccabitis Domino comedentes cum sanguine. Adduxit itaque omnis populus unusquisque bovem in manu sua usque ad noctem: et occiderunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, '\'dificavit autem Saul altare Domino, tuncque primum cœpit ædificare altare Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Et dixit Saul: Irruamus super Philisthæos nocte, et vastemus eos usque dum illucescat mane, nec relinquamus ex eis virum. Dixitque populus: Omne quod bonum videtur in oculis tuis, fac. Et ait sacerdos: Accedamus huc ad Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Et consuluit Saul Dominum: Num persequar Philisthiim? si trades eos in manus Israël? Et non respondit ei in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Dixitque Saul: Applicate huc universos angulos populi: et scitote, et videte per quem acciderit peccatum hoc hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Vivit Dominus salvator Israël, quia si per Jonathan filium meum factum est, absque retractione morietur. Ad quod nullus contradixit ei de omni populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Et ait ad universum Israël: Separamini vos in partem unam, et ego cum Jonatha filio meo ero in parte altera. Responditque populus ad Saul: Quod bonum videtur in oculis tuis, fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Et dixit Saul ad Dominum Deum Israël: Domine Deus Israël, da indicium: quid est quod non responderis servo tuo hodie? si in me, aut in Jonatha filio meo, est iniquitas hæc, da ostensionem: aut si hæc iniquitas est in populo tuo, da sanctitatem. Et deprehensus est Jonathas et Saul: populus autem exivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Et ait Saul: Mittite sortem inter me et inter Jonathan filium meum. Et captus est Jonathas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Dixit autem Saul ad Jonathan: Indica mihi quid feceris. Et indicavit ei Jonathas, et ait: Gustans gustavi in summitate virgæ quæ erat in manu mea, paululum mellis, et ecce ego morior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Et ait Saul: Hæc faciat mihi Deus, et hæc addat, quia morte morieris, Jonatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Dixitque populus ad Saul: Ergone Jonathas morietur, qui fecit salutem hanc magnam in Israël? hoc nefas est: vivit Dominus, si ceciderit capillus de capite ejus in terram, quia cum Deo operatus est hodie. Liberavit ergo populus Jonathan, ut non moreretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Recessitque Saul, nec persecutus est Philisthiim: porro Philisthiim abierunt in loca sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Et Saul, confirmato regno super Israël, pugnabat per circuitum adversum omnes inimicos ejus, contra Moab, et filios Ammon, et Edom, et reges Soba, et Philisthæos: et quocumque se verterat, superabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Congregatoque exercitu, percussit Amalec, et eruit Israël de manu vastatorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Fuerunt autem filii Saul, Jonathas, et Jessui, et Melchisua: et nomina duarum filiarum ejus, nomen primogenitæ Merob, et nomen minoris Michol.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Et nomen uxoris Saul Achinoam filia Achimaas: et nomen principis militiæ ejus Abner filius Ner, patruelis Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Porro Cis fuit pater Saul, et Ner pater Abner, filius Abiel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Erat autem bellum potens adversum Philisthæos omnibus diebus Saul. Nam quemcumque viderat Saul virum fortem, et aptum ad prælium, sociabat eum sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Et dixit Samuel ad Saul: Me misit Dominus ut ungerem te in regem super populum ejus Israël: nunc ergo audi vocem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Hæc dicit Dominus exercituum: Recensui quæcumque fecit Amalec Israëli: quomodo restitit ei in via cum ascenderet de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Nunc ergo vade, et percute Amalec, et demolire universa ejus: non parcas ei, et non concupiscas ex rebus ipsius aliquid, sed interfice a viro usque ad mulierem, et parvulum atque lactentem, bovem et ovem, camelum et asinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Præcepit itaque Saul populo, et recensuit eos quasi agnos: ducenta millia peditum, et decem millia virorum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Cumque venisset Saul usque ad civitatem Amalec, tetendit insidias in torrente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Dixitque Saul Cinæo: Abite, recedite, atque descendite ab Amalec, ne forte involvam te cum eo: tu enim fecisti misericordiam cum omnibus filiis Israël, cum ascenderent de \'gypto. Et recessit Cinæus de medio Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Percussitque Saul Amalec ab Hevila donec venias ad Sur, quæ est e regione \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Et apprehendit Agag regem Amalec vivum: omne autem vulgus interfecit in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Et pepercit Saul et populus Agag, et optimis gregibus ovium et armentorum, et vestibus et arietibus, et universis quæ pulchra erant, nec voluerunt disperdere ea: quidquid vero vile fuit et reprobum, hoc demoliti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Factum est autem verbum Domini ad Samuel, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Pœnitet me quod constituerim Saul regem: quia dereliquit me, et verba mea opere non implevit. Contristatusque est Samuel, et clamavit ad Dominum tota nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Cumque de nocte surrexisset Samuel ut iret ad Saul mane, nuntiatum est Samueli eo quod venisset Saul in Carmelum, et erexisset sibi fornicem triumphalem, et reversus transisset, descendissetque in Galgala. Venit ergo Samuel ad Saul, et Saul offerebat holocaustum Domino de initiis prædarum quæ attulerat ex Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Et cum venisset Samuel ad Saul, dixit ei Saul: Benedictus tu Domino: implevi verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Dixitque Samuel: Et quæ est hæc vox gregum, quæ resonat in auribus meis, et armentorum, quam ego audio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Et ait Saul: De Amalec adduxerunt ea: pepercit enim populus melioribus ovibus et armentis ut immolarentur Domino Deo tuo, reliqua vero occidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Ait autem Samuel ad Saul: Sine me, et indicabo tibi quæ locutus sit Dominus ad me nocte. Dixitque ei: Loquere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Et ait Samuel: Nonne cum parvulus esses in oculis tuis, caput in tribubus Israël factus es? unxitque te Dominus in regem super Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'et misit te Dominus in viam, et ait: Vade, et interfice peccatores Amalec, et pugnabis contra eos usque ad internecionem eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Quare ergo non audisti vocem Domini: sed versus ad prædam es, et fecisti malum in oculis Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Et ait Saul ad Samuelem: Immo audivi vocem Domini, et ambulavi in via per quam misit me Dominus, et adduxi Agag regem Amalec, et Amalec interfeci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Tulit autem de præda populus oves et boves, primitias eorum quæ cæsa sunt, ut immolet Domino Deo suo in Galgalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Et ait Samuel: Numquid vult Dominus holocausta et victimas, et non potius ut obediatur voci Domini? melior est enim obedientia quam victimæ, et auscultare magis quam offerre adipem arietum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Quoniam quasi peccatum ariolandi est, repugnare: et quasi scelus idololatriæ, nolle acquiescere. Pro eo ergo quod abjecisti sermonem Domini, abjecit te Dominus ne sis rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Dixitque Saul ad Samuelem: Peccavi, quia prævaricatus sum sermonem Domini et verba tua, timens populum, et obediens voci eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Sed nunc porta, quæso, peccatum meum, et revertere mecum, ut adorem Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Et ait Samuel ad Saul: Non revertar tecum, quia projecisti sermonem Domini, et projecit te Dominus ne sis rex super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Et conversus est Samuel ut abiret: ille autem apprehendit summitatem pallii ejus, quæ et scissa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Et ait ad eum Samuel: Scidit Dominus regnum Israël a te hodie, et tradidit illud proximo tuo meliori te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Porro triumphator in Israël non parcet, et pœnitudine non flectetur: neque enim homo est ut agat pœnitentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'At ille ait: Peccavi: sed nunc honora me coram senioribus populi mei et coram Israël, et revertere mecum, ut adorem Dominum Deum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Reversus ergo Samuel secutus est Saulem: et adoravit Saul Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Dixitque Samuel: Adducite ad me Agag regem Amalec. Et oblatus est ei Agag, pinguissimus et tremens. Et dixit Agag: Siccine separat amara mors?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Et ait Samuel: Sicut fecit absque liberis mulieres gladius tuus, sic absque liberis erit inter mulieres mater tua. Et in frustra concidit eum Samuel coram Domino in Galgalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Abiit autem Samuel in Ramatha: Saul vero ascendit in domum suam in Gabaa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Et non vidit Samuel ultra Saul usque ad diem mortis suæ: verumtamen lugebat Samuel Saulem, quoniam Dominum pœnitebat quod constituisset eum regem super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Dixitque Dominus ad Samuelem: Usquequo tu luges Saul, cum ego projecerim eum ne regnet super Israël? Imple cornu tuum oleo, et veni, ut mittam te ad Isai Bethlehemitem: providi enim in filiis ejus mihi regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Et ait Samuel: Quomodo vadam? audiet enim Saul, et interficiet me. Et ait Dominus: Vitulum de armento tolles in manu tua, et dices: Ad immolandum Domino veni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Et vocabis Isai ad victimam, et ego ostendam tibi quid facias, et unges quemcumque monstravero tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Fecit ergo Samuel sicut locutus est ei Dominus. Venitque in Bethlehem, et admirati sunt seniores civitatis occurrentes ei: dixeruntque: Pacificusne est ingressus tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Et ait: Pacificus: ad immolandum Domino veni: sanctificamini, et venite mecum ut immolem. Sanctificavit ergo Isai et filios ejus, et vocavit eos ad sacrificium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Cumque ingressi essent, vidit Eliab, et ait: Num coram Domino est christus ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Et dixit Dominus ad Samuelem: Ne respicias vultum ejus, neque altitudinem staturæ ejus: quoniam abjeci eum, nec juxta intuitum hominis ego judico: homo enim videt ea quæ parent, Dominus autem intuetur cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Et vocavit Isai Abinadab, et adduxit eum coram Samuele. Qui dixit: Nec hunc elegit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Adduxit autem Isai Samma, de quo ait: Etiam hunc non elegit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Adduxit itaque Isai septem filios suos coram Samuele: et ait Samuel ad Isai: Non elegit Dominus ex istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Dixitque Samuel ad Isai: Numquid jam completi sunt filii? Qui respondit: Adhuc reliquus est parvulus, et pascit oves. Et ait Samuel ad Isai: Mitte, et adduc eum: nec enim discumbemus priusquam huc ille veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Misit ergo, et adduxit eum. Erat autem rufus, et pulcher aspectu, decoraque facie: et ait Dominus: Surge, unge eum: ipse est enim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Tulit ergo Samuel cornu olei, et unxit eum in medio fratrum ejus: et directus est spiritus Domini a die illa in David, et deinceps. Surgensque Samuel abiit in Ramatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Spiritus autem Domini recessit a Saul, et exagitabat eum spiritus nequam a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Dixeruntque servi Saul ad eum: Ecce spiritus Dei malus exagitat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Jubeat dominus noster, et servi tui qui coram te sunt quærent hominem scientem psallere cithara, ut quando arripuerit te spiritus Domini malus, psallat manu sua, et levius feras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Et ait Saul ad servos suos: Providete ergo mihi aliquem bene psallentem, et adducite eum ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Et respondens unus de pueris, ait: Ecce vidi filium Isai Bethlehemitem scientem psallere, et fortissimum robore, et virum bellicosum, et prudentem in verbis, et virum pulchrum: et Dominus est cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Misit ergo Saul nuntios ad Isai, dicens: Mitte ad me David filium tuum, qui est in pascuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tulit itaque Isai asinum plenum panibus, et lagenam vini, et hædum de capris unum, et misit per manum David filii sui Sauli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Et venit David ad Saul, et stetit coram eo: at ille dilexit eum nimis, et factus est ejus armiger.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Misitque Saul ad Isai, dicens: Stet David in conspectu meo: invenit enim gratiam in oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Igitur quandocumque spiritus Domini malus arripiebat Saul, David tollebat citharam, et percutiebat manu sua, et refocillabatur Saul, et levius habebat: recedebat enim ab eo spiritus malus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Congregantes autem Philisthiim agmina sua in prælium, convenerunt in Socho Judæ: et castrametati sunt inter Socho et Azeca in finibus Dommim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Porro Saul et filii Israël congregati venerunt in Vallem terebinthi, et direxerunt aciem ad pugnandum contra Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Et Philisthiim stabant super montem ex parte hac, et Israël stabat supra montem ex altera parte: vallisque erat inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Et egressus est vir spurius de castris Philisthinorum nomine Goliath, de Geth, altitudinis sex cubitorum et palmi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'et cassis ærea super caput ejus, et lorica squamata induebatur. Porro pondus loricæ ejus, quinque millia siclorum æris erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'et ocreas æreas habebat in cruribus, et clypeus æreus tegebat humeros ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Hastile autem hastæ ejus erat quasi liciatorium texentium: ipsum autem ferrum hastæ ejus sexcentos siclos habebat ferri: et armiger ejus antecedebat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Stansque clamabat adversum phalangas Israël, et dicebat eis: Quare venistis parati ad prælium? numquid ego non sum Philisthæus, et vos servi Saul? eligite ex vobis virum, et descendat ad singulare certamen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Si quiverit pugnare mecum, et percusserit me, erimus vobis servi: si autem ego prævaluero, et percussero eum, vos servi eritis, et servietis nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Et aiebat Philisthæus: Ego exprobravi agminibus Israël hodie: date mihi virum, et ineat mecum singulare certamen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Audiens autem Saul et omnes Israëlitæ sermones Philisthæi hujuscemodi, stupebant, et metuebant nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David autem erat filius viri Ephrathæi, de quo supra dictum est, de Bethlehem Juda, cui nomen erat Isai, qui habebat octo filios, et erat vir in diebus Saul senex, et grandævus inter viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Abierunt autem tres filii ejus majores post Saul in prælium: et nomina trium filiorum ejus qui perrexerunt ad bellum, Eliab primogenitus, et secundus Abinadab, tertiusque Samma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David autem erat minimus. Tribus ergo majoribus secutis Saulem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'abiit David, et reversus est a Saul ut pasceret gregem patris sui in Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Procedebat vero Philisthæus mane et vespere, et stabat quadraginta diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Dixit autem Isai ad David filium suum: Accipe fratribus tuis ephi polentæ, et decem panes istos, et curre in castra ad fratres tuos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'et decem formellas casei has deferes ad tribunum: et fratres tuos visitabis, si recte agant: et cum quibus ordinati sunt, disce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul autem, et illi, et omnes filii Israël, in Valle terebinthi pugnabant adversum Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Surrexit itaque David mane, et commendavit gregem custodi: et onustus abiit, sicut præceperat ei Isai. Et venit ad locum Magala, et ad exercitum, qui egressus ad pugnam vociferatus erat in certamine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Direxerat enim aciem Israël, sed et Philisthiim ex adverso fuerant præparati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Derelinquens ergo David vasa quæ attulerat sub manu custodis ad sarcinas, cucurrit ad locum certaminis, et interrogabat si omnia recte agerentur erga fratres suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Cumque adhuc ille loqueretur eis, apparuit vir ille spurius ascendens, Goliath nomine, Philisthæus de Geth, de castris Philisthinorum: et loquente eo hæc eadem verba audivit David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Omnes autem Israëlitæ, cum vidissent virum, fugerunt a facie ejus, timentes eum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Et dixit unus quispiam de Israël: Num vidistis virum hunc, qui ascendit? ad exprobrandum enim Israëli ascendit. Virum ergo qui percusserit eum, ditabit rex divitiis magnis, et filiam suam dabit ei, et domum patris ejus faciet absque tributo in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Et ait David ad viros qui stabant secum, dicens: Quid dabitur viro qui percusserit Philisthæum hunc, et tulerit opprobrium de Israël? quis enim est hic Philisthæus incircumcisus, qui exprobravit acies Dei viventis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Referebat autem ei populus eumdem sermonem, dicens: Hæc dabuntur viro qui percusserit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Quod cum audisset Eliab frater ejus major, loquente eo cum aliis, iratus est contra David, et ait: Quare venisti, et quare dereliquisti pauculas oves illas in deserto? Ego novi superbiam tuam, et nequitiam cordis tui: quia ut videres prælium, descendisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Et dixit David: Quid feci? numquid non verbum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Et declinavit paululum ab eo ad alium: dixitque eumdem sermonem. Et respondit ei populus verbum sicut prius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Audita sunt autem verba quæ locutus est David, et annuntiata in conspectu Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Ad quem cum fuisset adductus, locutus est ei: Non concidat cor cujusquam in eo: ego servus tuus vadam, et pugnabo adversus Philisthæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Et ait Saul ad David: Non vales resistere Philisthæo isti, nec pugnare adversus eum, quia puer es: hic autem vir bellator est ab adolescentia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Dixitque David ad Saul: Pascebat servus tuus patris sui gregem, et veniebat leo vel ursus, et tollebat arietem de medio gregis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'et persequebar eos, et percutiebam, eruebamque de ore eorum: et illi consurgebant adversum me, et apprehendebam mentum eorum, et suffocabam, interficiebamque eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Nam et leonem et ursum interfeci ego servus tuus: erit igitur et Philisthæus hic incircumcisus quasi unus ex eis. Nunc vadam, et auferam opprobrium populi: quoniam quis est iste Philisthæus incircumcisus, qui ausus est maledicere exercitui Dei viventis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Et ait David: Dominus qui eripuit me de manu leonis, et de manu ursi, ipse me liberabit de manu Philisthæi hujus. Dixit autem Saul ad David: Vade, et Dominus tecum sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Et induit Saul David vestimentis suis, et imposuit galeam æream super caput ejus, et vestivit eum lorica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Accinctus ergo David gladio ejus super vestem suam, cœpit tentare si armatus posset incedere: non enim habebat consuetudinem. Dixitque David ad Saul: Non possum sic incedere, quia non usum habeo. Et deposuit ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'et tulit baculum suum, quem semper habebat in manibus: et elegit sibi quinque limpidissimos lapides de torrente, et misit eos in peram pastoralem quam habebat secum, et fundam manu tulit: et processit adversum Philisthæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Ibat autem Philisthæus incedens, et appropinquans adversum David, et armiger ejus ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Cumque inspexisset Philisthæus, et vidisset David, despexit eum. Erat enim adolescens, rufus, et pulcher aspectu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Et dixit Philisthæus ad David: Numquid ego canis sum, quod tu venis ad me cum baculo? Et maledixit Philisthæus David in diis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'dixitque ad David: Veni ad me, et dabo carnes tuas volatilibus cæli et bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Dixit autem David ad Philisthæum: Tu venis ad me cum gladio, et hasta, et clypeo: ego autem venio ad te in nomine Domini exercituum, Dei agminum Israël quibus exprobrasti');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'hodie, et dabit te Dominus in manu mea, et percutiam te, et auferam caput tuum a te: et dabo cadavera castrorum Philisthiim hodie volatilibus cæli, et bestiis terræ, ut sciat omnis terra quia est Deus in Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'et noverit universa ecclesia hæc, quia non in gladio nec in hasta salvat Dominus: ipsius enim est bellum, et tradet vos in manus nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Cum ergo surrexisset Philisthæus, et veniret, et appropinquaret contra David, festinavit David et cucurrit ad pugnam ex adverso Philisthæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Et misit manum suam in peram, tulitque unum lapidem, et funda jecit, et circumducens percussit Philisthæum in fronte: et infixus est lapis in fronte ejus, et cecidit in faciem suam super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Prævaluitque David adversum Philisthæum in funda et lapide, percussumque Philisthæum interfecit. Cumque gladium non haberet in manu David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'cucurrit, et stetit super Philisthæum, et tulit gladium ejus, et eduxit eum de vagina sua: et interfecit eum, præciditque caput ejus. Videntes autem Philisthiim quod mortuus esset fortissimus eorum, fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Et consurgentes viri Israël et Juda vociferati sunt, et persecuti sunt Philisthæos usque dum venirent in vallem, et usque ad portas Accaron: cecideruntque vulnerati de Philisthiim in via Saraim, et usque ad Geth, et usque ad Accaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Et revertentes filii Israël postquam persecuti fuerant Philisthæos, invaserunt castra eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Assumens autem David caput Philisthæi, attulit illud in Jerusalem: arma vero ejus posuit in tabernaculo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Eo autem tempore quo viderat Saul David egredientem contra Philisthæum, ait ad Abner principem militiæ: De qua stirpe descendit hic adolescens, Abner? Dixitque Abner: Vivit anima tua, rex, si novi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Et ait rex: Interroga tu, cujus filius sit iste puer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Cumque regressus esset David, percusso Philisthæo, tulit eum Abner, et introduxit coram Saule, caput Philisthæi habentem in manu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Et ait ad eum Saul: De qua progenie es, o adolescens? Dixitque David: Filius servi tui Isai Bethlehemitæ ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Et factum est cum complesset loqui ad Saul, anima Jonathæ conglutinata est animæ David, et dilexit eum Jonathas quasi animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Tulitque eum Saul in die illa, et non concessit ei ut reverteretur in domum patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Inierunt autem David et Jonathas fœdus: diligebat enim eum quasi animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Nam expoliavit se Jonathas tunica qua erat indutus, et dedit eam David, et reliqua vestimenta sua, usque ad gladium et arcum suum, et usque ad balteum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Egrediebatur quoque David ad omnia quæcumque misisset eum Saul, et prudenter se agebat: posuitque eum Saul super viros belli, et acceptus erat in oculis universi populi, maximeque in conspectu famulorum Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Porro cum reverteretur percusso Philisthæo David, egressæ sunt mulieres de universis urbibus Israël, cantantes, chorosque ducentes in occursum Saul regis, in tympanis lætitiæ, et in sistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Et præcinebant mulieres, ludentes, atque dicentes: Percussit Saul mille, et David decem millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Iratus est autem Saul nimis, et displicuit in oculis ejus sermo iste: dixitque: Dederunt David decem millia, et mihi mille dederunt: quid ei superest, nisi solum regnum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Non rectis ergo oculis Saul aspiciebat David a die illa et deinceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Post diem autem alteram, invasit spiritus Dei malus Saul, et prophetabat in medio domus suæ: David autem psallebat manu sua, sicut per singulos dies. Tenebatque Saul lanceam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'et misit eam, putans quod configere posset David cum pariete: et declinavit David a facie ejus secundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Et timuit Saul David, eo quod Dominus esset cum eo, et a se recessisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Amovit ergo eum Saul a se, et fecit eum tribunum super mille viros: et egrediebatur, et intrabat in conspectu populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'In omnibus quoque viis suis David prudenter agebat, et Dominus erat cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Vidit itaque Saul quod prudens esset nimis, et cœpit cavere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Omnis autem Israël et Juda diligebat David: ipse enim ingrediebatur et egrediebatur ante eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Dixitque Saul ad David: Ecce filia mea major Merob: ipsam dabo tibi uxorem: tantummodo esto vir fortis, et præliare bella Domini. Saul autem reputabat, dicens: Non sit manus mea in eum, sed sit super eum manus Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Ait autem David ad Saul: Quis ego sum, aut quæ est vita mea, aut cognatio patris mei in Israël, ut fiam gener regis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Factum est autem tempus cum deberet dari Merob filia Saul David, data est Hadrieli Molathitæ uxor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Dilexit autem David Michol filia Saul altera. Et nuntiatum est Saul, et placuit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Dixitque Saul: Dabo eam illi, ut fiat ei in scandalum, et sit super eum manus Philisthinorum. Dixitque Saul ad David: In duabus rebus gener meus eris hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Et mandavit Saul servis suis: Loquimini ad David clam me, dicentes: Ecce places regi, et omnes servi ejus diligunt te: nunc ergo esto gener regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Et locuti sunt servi Saul in auribus David omnia verba hæc. Et ait David: Num parum videtur vobis, generum esse regis? ego autem sum vir pauper et tenuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Et renuntiaverunt servi Saul dicentes: Hujuscemodi verba locutus est David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Dixit autem Saul: Sic loquimini ad David: Non habet rex sponsalia necesse, nisi tantum centum præputia Philisthinorum, ut fiat ultio de inimicis regis. Porro Saul cogitabat tradere David in manus Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Cumque renuntiassent servi ejus David verba quæ dixerat Saul, placuit sermo in oculis David, ut fieret gener regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Et post paucos dies surgens David, abiit cum viris qui sub eo erant. Et percussit ex Philisthiim ducentos viros, et attulit eorum præputia et annumeravit ea regi, ut esset gener ejus. Dedit itaque Saul ei Michol filiam suam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Et vidit Saul, et intellexit quod Dominus esset cum David. Michol autem filia Saul diligebat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Et Saul magis cœpit timere David: factusque est Saul inimicus David cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Et egressi sunt principes Philisthinorum. A principio autem egressionis eorum, prudentius se gerebat David quam omnes servi Saul, et celebre factum est nomen ejus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Locutus est autem Saul ad Jonathan filium suum, et ad omnes servos suos, ut occiderent David. Porro Jonathas filius Saul diligebat David valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'et indicavit Jonathas David, dicens: Quærit Saul pater meus occidere te: quapropter observa te, quæso, mane: et manebis clam, et absconderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ego autem egrediens stabo juxta patrem meum in agro, ubicumque fueris: et ego loquar de te ad patrem meum, et quodcumque videro, nuntiabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Locutus est ergo Jonathas de David bona ad Saul patrem suum: dixitque ad eum: Ne pecces rex in servum tuum David, quia non peccavit tibi, et opera ejus bona sunt tibi valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Et posuit animam suam in manu sua, et percussit Philisthæum, et fecit Dominus salutem magnam universo Israëli: vidisti, et lætatus es. Quare ergo peccas in sanguine innoxio, interficiens David, qui est absque culpa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Quod cum audisset Saul, placatus voce Jonathæ, juravit: Vivit Dominus, quia non occidetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Vocavit itaque Jonathas David, et indicavit ei omnia verba hæc: et introduxit Jonathas David ad Saul, et fuit ante eum sicut fuerat heri et nudiustertius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Motum est autem rursum bellum: et egressus David, pugnavit adversum Philisthiim: percussitque eos plaga magna, et fugerunt a facie ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Et factus est spiritus Domini malus in Saul: sedebat autem in domo sua, et tenebat lanceam: porro David psallebat manu sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Nisusque est Saul configere David lancea in pariete, et declinavit David a facie Saul: lancea autem casso vulnere perlata est in parietem, et David fugit, et salvatus est nocte illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Misit ergo Saul satellites suos in domum David, ut custodirent eum, et interficeretur mane. Quod cum annuntiasset David Michol uxor sua, dicens: Nisi salvaveris te nocte hac, cras morieris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'deposuit eum per fenestram. Porro ille abiit et aufugit, atque salvatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Tulit autem Michol statuam, et posuit eam super lectum, et pellem pilosam caprarum posuit ad caput ejus, et operuit eam vestimentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Misit autem Saul apparitores, qui raperent David: et responsum est quod ægrotaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Rursumque misit Saul nuntios ut viderent David, dicens: Afferte eum ad me in lecto, ut occidatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Cumque venissent nuntii, inventum est simulacrum super lectum, et pellis caprarum ad caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Dixitque Saul ad Michol: Quare sic illusisti mihi, et dimisisti inimicum meum ut fugeret? Et respondit Michol ad Saul: Quia ipse locutus est mihi: Dimitte me, alioquin interficiam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David autem fugiens salvatus est, et venit ad Samuel in Ramatha, et nuntiavit ei omnia quæ fecerat sibi Saul: et abierunt ipse et Samuel, et morati sunt in Najoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Nuntiatum est autem Sauli a dicentibus: Ecce David in Najoth in Ramatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Misit ergo Saul lictores, ut raperent David: qui cum vidissent cuneum prophetarum vaticinantium, et Samuelem stantem super eos, factus est etiam spiritus Domini in illis, et prophetare cœperunt etiam ipsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Quod cum nuntiatum esset Sauli, misit et alios nuntios: prophetaverunt autem et illi. Et rursum misit Saul tertios nuntios: qui et ipsi prophetaverunt. Et iratus iracundia Saul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'abiit etiam ipse in Ramatha, et venit usque ad cisternam magnam quæ est in Socho, et interrogavit, et dixit: In quo loco sunt Samuel et David? Dictumque est ei: Ecce in Najoth sunt in Ramatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Et abiit in Najoth in Ramatha, et factus est etiam super eum spiritus Domini, et ambulabat ingrediens, et prophetabat usque dum veniret in Najoth in Ramatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Et expoliavit etiam ipse se vestimentis suis, et prophetavit cum ceteris coram Samuele, et cecidit nudus tota die illa et nocte. Unde et exivit proverbium: Num et Saul inter prophetas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Fugit autem David de Najoth, quæ est in Ramatha, veniensque locutus est coram Jonatha: Quid feci? quæ est iniquitas mea, et quod peccatum meum in patrem tuum, quia quærit animam meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Qui dixit ei: Absit, non morieris: neque enim faciet pater meus quidquam grande vel parvum, nisi prius indicaverit mihi: hunc ergo celavit me pater meus sermonem tantummodo? nequaquam erit istud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Et juravit rursum Davidi. Et ille ait: Scit profecto pater tuus quia inveni gratiam in oculis tuis, et dicet: Nesciat hoc Jonathas, ne forte tristetur. Quinimmo vivit Dominus, et vivit anima tua, quia uno tantum (ut ita dicam) gradu ego morsque dividimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Et ait Jonathas ad David: Quodcumque dixerit mihi anima tua, faciam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Dixit autem David ad Jonathan: Ecce calendæ sunt crastino, et ego ex more sedere soleo juxta regem ad vescendum: dimitte ergo me ut abscondar in agro usque ad vesperam diei tertiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Si respiciens requisierit me pater tuus, respondebis ei: Rogavit me David ut iret celeriter in Bethlehem civitatem suam, quia victimæ solemnes ibi sunt universis contribulibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Si dixerit: Bene: pax erit servo tuo. Si autem fuerit iratus, scito quia completa est malitia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Fac ergo misericordiam in servum tuum, quia fœdus Domini me famulum tuum tecum inire fecisti: si autem est iniquitas aliqua in me, tu me interfice, et ad patrem tuum ne introducas me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Et ait Jonathas: Absit hoc a te: neque enim fieri potest, ut si certe cognovero completam esse patris mei malitiam contra te, non annuntiem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Responditque David ad Jonathan: Quis renuntiabit mihi, si quid forte responderit tibi pater tuus dure de me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Et ait Jonathas ad David: Veni, et egrediamur foras in agrum. Cumque exissent ambo in agrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'ait Jonathas ad David: Domine Deus Israël, si investigavero sententiam patris mei crastino vel perendie, et aliquid boni fuerit super David, et non statim misero ad te, et notum tibi fecero,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'hæc faciat Dominus Jonathæ, et hæc addat. Si autem perseveraverit patris mei malitia adversum te, revelabo aurem tuam, et dimittam te, ut vadas in pace, et sit Dominus tecum, sicut fuit cum patre meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Et si vixero, facies mihi misericordiam Domini: si vero mortuus fuero,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'non auferes misericordiam tuam a domo mea usque in sempiternum, quando eradicaverit Dominus inimicos David, unumquemque de terra: auferat Jonathan de domo sua, et requirat Dominus de manu inimicorum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Pepigit ergo Jonathas fœdus cum domo David: et requisivit Dominus de manu inimicorum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Et addidit Jonathas dejerare David, eo quod diligeret illum: sicut enim animam suam, ita diligebat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Dixitque ad eum Jonathas: Cras calendæ sunt, et requireris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'requiretur enim sessio tua usque perendie. Descendes ergo festinus, et venies in locum ubi celandus es in die qua operari licet, et sedebis juxta lapidem cui nomen est Ezel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Et ego tres sagittas mittam juxta eum, et jaciam quasi exercens me ad signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Mittam quoque et puerum, dicens ei: Vade, et affer mihi sagittas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Si dixero puero: Ecce sagittæ intra te sunt, tolle eas: tu veni ad me, quia pax tibi est, et nihil est mali, vivit Dominus. Si autem sic locutus fuero puero: Ecce sagittæ ultra te sunt: vade in pace, quia dimisit te Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'De verbo autem quod locuti sumus ego et tu, sit Dominus inter me et te usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Absconditus est ergo David in agro, et venerunt calendæ, et sedit rex ad comedendum panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Cumque sedisset rex super cathedram suam (secundum consuetudinem) quæ erat juxta parietem, surrexit Jonathas, et sedit Abner ex latere Saul: vacuusque apparuit locus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Et non est locutus Saul quidquam in die illa: cogitabat enim quod forte evenisset ei, ut non esset mundus, nec purificatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Cumque illuxisset dies secunda post calendas, rursus apparuit vacuus locus David. Dixitque Saul ad Jonathan filium suum: Cur non venit filius Isai nec heri nec hodie ad vescendum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Responditque Jonathas Sauli: Rogavit me obnixe ut iret in Bethlehem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'et ait: Dimitte me, quoniam sacrificium solemne est in civitate, unus de fratribus meis accersivit me: nunc ergo si inveni gratiam in oculis tuis, vadam cito, et videbo fratres meos. Ob hanc causam non venit ad mensam regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Iratus autem Saul adversum Jonathan, dixit ei: Fili mulieris virum ultro rapientis, numquid ignoro quia diligis filium Isai in confusionem tuam, et in confusionem ignominiosæ matris tuæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Omnibus enim diebus quibus filius Isai vixerit super terram, non stabilieris tu, neque regnum tuum. Itaque jam nunc mitte, et adduc eum ad me: quia filius mortis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Respondens autem Jonathas Sauli patri suo, ait: Quare morietur? quid fecit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Et arripuit Saul lanceam ut percuteret eum. Et intellexit Jonathas quod definitum esset a patre suo, ut interficeret David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Surrexit ergo Jonathas a mensa in ira furoris, et non comedit in die calendarum secunda panem. Contristatus est enim super David, eo quod confudisset eum pater suus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Cumque illuxisset mane, venit Jonathas in agrum juxta placitum David, et puer parvulus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Et ait ad puerum suum: Vade, et affer mihi sagittas quas ego jacio. Cumque puer cucurrisset, jecit aliam sagittam trans puerum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Venit itaque puer ad locum jaculi quod miserat Jonathas: et clamavit Jonathas post tergum pueri, et ait: Ecce ibi est sagitta porro ultra te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Clamavitque iterum Jonathas post tergum pueri, dicens: Festina velociter, ne steteris. Collegit autem puer Jonathæ sagittas, et attulit ad dominum suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'et quid ageretur, penitus ignorabat, tantummodo enim Jonathas et David rem noverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Dedit ergo Jonathas arma sua puero, et dixit ei: Vade, et defer in civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Cumque abiisset puer, surrexit David de loco qui vergebat ad austrum, et cadens pronus in terram, adoravit tertio: et osculantes se alterutrum, fleverunt pariter, David autem amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Dixit ergo Jonathas ad David: Vade in pace: quæcumque juravimus ambo in nomine Domini, dicentes: Dominus sit inter me et te, et inter semen meum et semen tuum usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 43, 'Et surrexit David, et abiit: sed et Jonathas ingressus est civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Venit autem David in Nobe ad Achimelech sacerdotem: et obstupuit Achimelech, eo quod venisset David. Et dixit ei: Quare tu solus, et nullus est tecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Et ait David ad Achimelech sacerdotem: Rex præcepit mihi sermonem, et dixit: Nemo sciat rem propter quam missus es a me, et cujusmodi præcepta tibi dederim: nam et pueris condixi in illum et illum locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Nunc ergo si quid habes ad manum, vel quinque panes, da mihi, aut quidquid inveneris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Et respondens sacerdos ad David, ait illi: Non habeo laicos panes ad manum, sed tantum panem sanctum: si mundi sunt pueri, maxime a mulieribus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Et respondit David sacerdoti, et dixit ei: Equidem, si de mulieribus agitur: continuimus nos ab heri et nudiustertius quando egrediebamur, et fuerunt vasa puerorum sancta. Porro via hæc polluta est, sed et ipsa hodie sanctificabitur in vasis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Dedit ergo ei sacerdos sanctificatum panem: neque enim erat ibi panis, nisi tantum panes propositionis, qui sublati fuerant a facie Domini, ut ponerentur panes calidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Erat autem ibi vir quidam de servis Saul in die illa, intus in tabernaculo Domini: et nomen ejus Doëg Idumæus, potentissimus pastorum Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Dixit autem David ad Achimelech: Si habes hic ad manum hastam aut gladium? quia gladium meum et arma mea non tuli mecum: sermo enim regis urgebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Et dixit sacerdos: Ecce hic gladius Goliath Philisthæi, quem percussisti in Valle terebinthi: est involutus pallio post ephod: si istum vis tollere, tolle: neque enim hic est alius absque eo. Et ait David: Non est huic alter similis: da mihi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Surrexit itaque David, et fugit in die illa a facie Saul: et venit ad Achis regem Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Dixeruntque servi Achis ad eum cum vidissent David: Numquid non iste est David rex terræ? nonne huic cantabant per choros, dicentes: Percussit Saul mille, et David decem millia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Posuit autem David sermones istos in corde suo, et extimuit valde a facie Achis regis Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Et immutavit os suum coram eis, et collabebatur inter manus eorum: et impingebat in ostia portæ, defluebantque salivæ ejus in barbam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Et ait Achis ad servos suos: Vidistis hominem insanum: quare adduxistis eum ad me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'an desunt nobis furiosi, quod introduxistis istum, ut fureret me præsente? hiccine ingredietur domum meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Abiit ergo David inde, et fugit in speluncam Odollam. Quod cum audissent fratres ejus, et omnis domus patris ejus, descenderunt ad eum illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Et convenerunt ad eum omnes qui erant in angustia constituti, et oppressi ære alieno, et amaro animo: et factus est eorum princeps, fueruntque cum eo quasi quadringenti viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Et profectus est David inde in Maspha, quæ est Moab: et dixit ad regem Moab: Maneat, oro, pater meus et mater mea vobiscum, donec sciam quid faciat mihi Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Et reliquit eos ante faciem regis Moab: manseruntque apud eum cunctis diebus quibus David fuit in præsidio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Dixitque Gad propheta ad David: Noli manere in præsidio: proficiscere, et vade in terram Juda. Et profectus est David, et venit in saltum Haret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Et audivit Saul quod apparuisset David, et viri qui erant cum eo. Saul autem cum maneret in Gabaa, et esset in nemore quod est in Rama, hastam manu tenens, cunctique servi ejus circumstarent eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'ait ad servos suos qui assistebant ei: Audite nunc, filii Jemini: numquid omnibus vobis dabit filius Isai agros et vineas, et universos vos faciet tribunos et centuriones?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'quoniam conjurastis omnes adversum me, et non est qui mihi renuntiet, maxime cum et filius meus fœdus inierit cum filio Isai. Non est qui vicem meam doleat ex vobis, nec qui annuntiet mihi: eo quod suscitaverit filius meus servum meum adversum me, insidiantem mihi usque hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Respondens autem Doëg Idumæus, qui assistebat, et erat primus inter servos Saul: Vidi, inquit, filium Isai in Nobe apud Achimelech filium Achitob sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Qui consuluit pro eo Dominum, et cibaria dedit ei: sed et gladium Goliath Philisthæi dedit illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Misit ergo rex ad accersendum Achimelech sacerdotem filium Achitob, et omnem domum patris ejus, sacerdotum qui erant in Nobe, qui universi venerunt ad regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Et ait Saul ad Achimelech: Audi, fili Achitob. Qui respondit: Præsto sum, domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Dixitque ad eum Saul: Quare conjurastis adversum me, tu et filius Isai, et dedisti ei panes et gladium, et consuluisti pro eo Deum, ut consurgeret adversum me, insidiator usque hodie permanens?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Respondensque Achimelech regi, ait: Et quis in omnibus servis tuis sicut David, fidelis, et gener regis, et pergens ad imperium tuum, et gloriosus in domo tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'num hodie cœpi pro eo consulere Deum? absit hoc a me: ne suspicetur rex adversus servum suum rem hujuscemodi, in universa domo patris mei: non enim scivit servus tuus quidquam super hoc negotio, vel modicum vel grande.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Dixitque rex: Morte morieris Achimelech, tu et omnis domus patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Et ait rex emissariis qui circumstabant eum: Convertimini, et interficite sacerdotes Domini, nam manus eorum cum David est: scientes quod fugisset, et non indicaverunt mihi. Noluerunt autem servi regis extendere manus suas in sacerdotes Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Et ait rex ad Doëg: Convertere tu, et irrue in sacerdotes. Conversusque Doëg Idumæus, irruit in sacerdotes, et trucidavit in die illa octoginta quinque viros vestitos ephod lineo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Nobe autem civitatem sacerdotum percussit in ore gladii, viros et mulieres, et parvulos et lactentes, bovemque, et asinum, et ovem in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Evadens autem unus filius Achimelech filii Achitob, cujus nomen erat Abiathar, fugit ad David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'et annuntiavit ei quod occidisset Saul sacerdotes Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Et ait David ad Abiathar: Sciebam in die illa quod cum ibi esset Doëg Idumæus, procul dubio annuntiaret Sauli: ego sum reus omnium animarum patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Mane mecum: ne timeas: si quis quæsierit animam meam, quæret et animam tuam, mecumque servaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Et annuntiaverunt David, dicentes: Ecce Philisthiim oppugnant Ceilam et diripiunt areas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Consuluit ergo David Dominum, dicens: Num vadam, et percutiam Philisthæos istos? Et ait Dominus ad David: Vade, et percuties Philisthæos, et Ceilam salvabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Et dixerunt viri qui erant cum David ad eum: Ecce nos hic in Judæa consistentes timemus: quanto magis si ierimus in Ceilam adversum agmina Philisthinorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Rursum ergo David consuluit Dominum. Qui respondens, ait ei: Surge, et vade in Ceilam: ego enim tradam Philisthæos in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Abiit ergo David et viri ejus in Ceilam, et pugnavit adversum Philisthæos: et abegit jumenta eorum, et percussit eos plaga magna: et salvavit David habitatores Ceilæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Porro eo tempore quo fugiebat Abiathar filius Achimelech ad David in Ceilam, ephod secum habens descenderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Nuntiatum est autem Sauli quod venisset David in Ceilam: et ait Saul: Tradidit eum Deus in manus meas, conclususque est introgressus urbem, in qua portæ et seræ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Et præcepit Saul omni populo ut ad pugnam descenderet in Ceilam, et obsideret David et viros ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Quod cum David rescisset quia præpararet ei Saul clam malum, dixit ad Abiathar sacerdotem: Applica ephod.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Et ait David: Domine Deus Israël, audivit famam servus tuus, quod disponat Saul venire in Ceilam, ut evertat urbem propter me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'si tradent me viri Ceilæ in manus ejus? et si descendet Saul, sicut audivit servus tuus? Domine Deus Israël, indica servo tuo. Et ait Dominus: Descendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Dixitque David: Si tradent me viri Ceilæ, et viros qui sunt mecum, in manus Saul? Et dixit Dominus: Tradent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Surrexit ergo David et viri ejus quasi sexcenti, et egressi de Ceila, huc atque illuc vagabantur incerti: nuntiatumque est Sauli quod fugisset David de Ceila, et salvatus esset: quam ob rem dissimulavit exire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Morabatur autem David in deserto in locis firmissimis, mansitque in monte solitudinis Ziph, in monte opaco: quærebat eum tamen Saul cunctis diebus, et non tradidit eum Deus in manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Et vidit David quod egressus esset Saul ut quæreret animam ejus. Porro David erat in deserto Ziph in silva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Et surrexit Jonathas filius Saul, et abiit ad David in silvam, et confortavit manus ejus in Deo: dixitque ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Ne timeas: neque enim inveniet te manus Saul patris mei, et tu regnabis super Israël, et ego ero tibi secundus: sed et Saul pater meus scit hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Percussit ergo uterque fœdus coram Domino: mansitque David in silva, Jonathas autem reversus est in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Ascenderunt autem Ziphæi ad Saul in Gabaa, dicentes: Nonne ecce David latitat apud nos in locis tutissimis silvæ, in colle Hachila, quæ est ad dexteram deserti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Nunc ergo, sicut desideravit anima tua ut descenderes, descende: nostrum autem erit ut tradamus eum in manus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Dixitque Saul: Benedicti vos a Domino, quia doluistis vicem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Abite ergo, oro, et diligentius præparate, et curiosius agite, et considerate locum ubi sit pes ejus, vel quis viderit eum ibi: recogitat enim de me, quod callide insidier ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Considerate, et videte omnia latibula ejus in quibus absconditur: et revertimini ad me ad rem certam, ut vadam vobiscum. Quod si etiam in terram se abstruserit, perscrutabor eum in cunctis millibus Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'At illi surgentes abierunt in Ziph ante Saul: David autem et viri ejus erant in deserto Maon, in campestribus ad dexteram Jesimon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Ivit ergo Saul et socii ejus ad quærendum eum. Et nuntiatum est David: statimque descendit ad petram, et versabatur in deserto Maon: quod cum audisset Saul, persecutus est David in deserto Maon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Et ibat Saul ad latus montis ex parte una: David autem et viri ejus erant in latere montis ex parte altera. Porro David desperabat se posse evadere a facie Saul: itaque Saul et viri ejus in modum coronæ cingebant David et viros ejus, ut caperent eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Et nuntius venit ad Saul, dicens: Festina, et veni, quoniam infuderunt se Philisthiim super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Reversus est ergo Saul desistens persequi David, et perrexit in occursum Philisthinorum: propter hoc vocaverunt locum illum, Petram dividentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Ascendit ergo David inde: et habitavit in locis tutissimis Engaddi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Cumque reversus esset Saul, postquam persecutus est Philisthæos, nuntiaverunt ei, dicentes: Ecce David in deserto est Engaddi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Assumens ergo Saul tria millia electorum virorum ex omni Israël, perrexit ad investigandum David et viros ejus, etiam super abruptissimas petras, quæ solis ibicibus perviæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Et venit ad caulas ovium, quæ se offerebant vianti: eratque ibi spelunca, quam ingressus est Saul ut purgaret ventrem: porro David et viri ejus in interiore parte speluncæ latebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Et dixerunt servi David ad eum: Ecce dies de qua locutus est Dominus ad te: Ego tradam tibi inimicum tuum, ut facias ei sicut placuerit in oculis tuis. Surrexit ergo David, et præcidit oram chlamydis Saul silenter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Post hæc percussit cor suum David, eo quod abscidisset oram chlamydis Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Dixitque ad viros suos: Propitius sit mihi Dominus, ne faciam hanc rem domino meo, christo Domini, ut mittam manum meam in eum: quia christus Domini est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Et confregit David viros suos sermonibus, et non permisit eos ut consurgerent in Saul: porro Saul exsurgens de spelunca, pergebat cœpto itinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Surrexit autem et David post eum: et egressus de spelunca, clamavit post tergum Saul, dicens: Domine mi rex. Et respexit Saul post se: et inclinans se David pronus in terram adoravit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'dixitque ad Saul: Quare audis verba hominum loquentium: David quærit malum adversum te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Ecce hodie viderunt oculi tui quod tradiderit te Dominus in manu mea in spelunca: et cogitavi ut occiderem te, sed pepercit tibi oculus meus: dixi enim: Non extendam manum meam in dominum meum, quia christus Domini est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Quin potius pater mi, vide, et cognosce oram chlamydis tuæ in manu mea: quoniam cum præscinderem summitatem chlamydis tuæ, nolui extendere manum meam in te: animadverte, et vide, quoniam non est in manu mea malum, neque iniquitas, neque peccavi in te: tu autem insidiaris animæ meæ ut auferas eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Judicet Dominus inter me et te, et ulciscatur me Dominus ex te: manus autem mea non sit in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Sicut et in proverbio antiquo dicitur: Ab impiis egredietur impietas: manus ergo mea non sit in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Quem persequeris, rex Israël? quem persequeris? canem mortuum persequeris, et pulicem unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Sit Dominus judex, et judicet inter me et te: et videat, et judicet causam meam, et eruat me de manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Cum autem complesset David loquens sermones hujuscemodi ad Saul, dixit Saul: Numquid vox hæc tua est, fili mi David? Et levavit Saul vocem suam, et flevit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'dixitque ad David: Justior tu es quam ego: tu enim tribuisti mihi bona, ego autem reddidi tibi mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Et tu indicasti hodie quæ feceris mihi bona: quomodo tradiderit me Dominus in manum tuam, et non occideris me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Quis enim cum invenerit inimicum suum, dimittet eum in via bona? sed Dominus reddat tibi vicissitudinem hanc pro eo quod hodie operatus es in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Et nunc quia scio quod certissime regnaturus sis, et habiturus in manu tua regnum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'jura mihi in Domino, ne deleas semen meum post me, neque auferas nomen meum de domo patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Et juravit David Sauli. Abiit ergo Saul in domum suam: et David et viri ejus ascenderunt ad tutiora loca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Mortuus est autem Samuel, et congregatus est universus Israël, et planxerunt eum, et sepelierunt eum in domo sua in Ramatha. Consurgensque David descendit in desertum Pharan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Erat autem vir quispiam in solitudine Maon, et possessio ejus in Carmelo, et homo ille magnus nimis: erantque ei oves tria millia, et mille capræ: et accidit ut tonderetur grex ejus in Carmelo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Nomen autem viri illius erat Nabal. Et nomen uxoris ejus Abigail: eratque mulier illa prudentissima, et speciosa: porro vir ejus durus, et pessimus, et malitiosus: erat autem de genere Caleb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Cum ergo audisset David in deserto quod tonderet Nabal gregem suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'misit decem juvenes, et dixit eis: Ascendite in Carmelum, et venietis ad Nabal, et salutabitis eum ex nomine meo pacifice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Et dicetis: Sit fratribus meis et tibi pax, et domui tuæ pax, et omnibus, quæcumque habes, sit pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Audivi quod tonderent pastores tui, qui erant nobiscum in deserto: numquam eis molesti fuimus, nec aliquando defuit quidquam eis de grege, omni tempore quo fuerunt nobiscum in Carmelo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Interroga pueros tuos, et indicabunt tibi. Nunc ergo inveniant pueri tui gratiam in oculis tuis: in die enim bona venimus: quodcumque invenerit manus tua, da servis tuis, et filio tuo David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Cumque venissent pueri David, locuti sunt ad Nabal omnia verba hæc ex nomine David: et siluerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Respondens autem Nabal pueris David, ait: Quis est David? et quis est filius Isai? hodie increverunt servi qui fugiunt dominos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Tollam ergo panes meos, et aquas meas, et carnes pecorum quæ occidi tonsoribus meis, et dabo viris quos nescio unde sint?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Regressi sunt itaque pueri David per viam suam, et reversi venerunt, et nuntiaverunt ei omnia verba quæ dixerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Tunc ait David pueris suis: Accingatur unusquisque gladio suo. Et accincti sunt singuli gladiis suis, accinctusque est et David ense suo: et secuti sunt David quasi quadringenti viri: porro ducenti remanserunt ad sarcinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Abigail autem uxori Nabal nuntiavit unus de pueris suis, dicens: Ecce David misit nuntios de deserto, ut benedicerent domino nostro: et aversatus est eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Homines isti boni satis fuerant nobis, et non molesti: nec quidquam aliquando periit omni tempore quo fuimus conversati cum eis in deserto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'pro muro erant nobis tam in nocte quam in die, omnibus diebus quibus pavimus apud eos greges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Quam ob rem considera, et recogita quid facias: quoniam completa est malitia adversum virum tuum, et adversum domum tuam, et ipse est filius Belial, ita ut nemo possit ei loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Festinavit igitur Abigail, et tulit ducentos panes, et duos utres vini, et quinque arietes coctos, et quinque sata polentæ, et centum ligaturas uvæ passæ, et ducentas massas caricarum, et posuit super asinos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'dixitque pueris suis: Præcedite me: ecce ego post tergum sequar vos: viro autem suo Nabal non indicavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Cum ergo ascendisset asinum, et descenderet ad radices montis, David et viri ejus descendebant in occursum ejus: quibus et illa occurrit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Et ait David: Vere frustra servavi omnia quæ hujus erant in deserto, et non periit quidquam de cunctis quæ ad eum pertinebant: et reddidit mihi malum pro bono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Hæc faciat Deus inimicis David, et hæc addat, si reliquero de omnibus quæ ad ipsum pertinent usque mane mingentem ad parietem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Cum autem vidisset Abigail David, festinavit, et descendit de asino, et procidit coram David super faciem suam, et adoravit super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'et cecidit ad pedes ejus, et dixit: In me sit, domine mi, hæc iniquitas: loquatur, obsecro, ancilla tua in auribus tuis, et audi verba famulæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Ne ponat, oro, dominus meus rex cor suum super virum istum iniquum Nabal: quoniam secundum nomen suum stultus est, et stultitia est cum eo: ego autem ancilla tua non vidi pueros tuos, domine mi, quos misisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Nunc ergo, domine mi, vivit Dominus, et vivit anima tua, qui prohibuit te ne venires in sanguinem, et salvavit manum tuam tibi: et nunc fiant sicut Nabal inimici tui, et qui quærunt domino meo malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Quapropter suscipe benedictionem hanc, quam attulit ancilla tua tibi domino meo, et da pueris qui sequuntur te dominum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Aufer iniquitatem famulæ tuæ: faciens enim faciet Dominus tibi domino meo domum fidelem, quia prælia Domini, domine mi, tu præliaris: malitia ergo non inveniatur in te omnibus diebus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Si enim surrexerit aliquando homo persequens te, et quærens animam tuam, erit anima domini mei custodita quasi in fasciculo viventium apud Dominum Deum tuum: porro inimicorum tuorum anima rotabitur, quasi in impetu et circulo fundæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Cum ergo fecerit Dominus tibi domino meo omnia quæ locutus est bona de te, et constituerit te ducem super Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'non erit tibi hoc in singultum, et in scrupulum cordis domino meo, quod effuderis sanguinem innoxium, aut ipse te ultus fueris: et cum benefecerit Dominus domino meo, recordaberis ancillæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Et ait David ad Abigail: Benedictus Dominus Deus Israël, qui misit hodie te in occursum meum, et benedictum eloquium tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'et benedicta tu, quæ prohibuisti me hodie ne irem ad sanguinem, et ulciscerer me manu mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Alioquin vivit Dominus Deus Israël, qui prohibuit me ne malum facerem tibi: nisi cito venisses in occursum mihi, non remansisset Nabal usque ad lucem matutinam mingens ad parietem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Suscepit ergo David de manu ejus omnia quæ attulerat ei, dixitque ei: Vade pacifice in domum tuam: ecce audivi vocem tuam, et honoravi faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Venit autem Abigail ad Nabal: et ecce erat ei convivium in domo ejus quasi convivium regis, et cor Nabal jucundum: erat enim ebrius nimis: et non indicavit ei verbum pusillum aut grande usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Diluculo autem cum digessisset vinum Nabal, indicavit ei uxor sua verba hæc: et emortuum est cor ejus intrinsecus, et factus est quasi lapis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Cumque pertransissent decem dies, percussit Dominus Nabal, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Quod cum audisset David mortuum Nabal, ait: Benedictus Dominus, qui judicavit causam opprobrii mei de manu Nabal, et servum suum custodivit a malo, et malitiam Nabal reddidit Dominus in caput ejus. Misit ergo David, et locutus est ad Abigail, ut sumeret eam sibi in uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Et venerunt pueri David ad Abigail in Carmelum, et locuti sunt ad eam, dicentes: David misit nos ad te, ut accipiat te sibi in uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Quæ consurgens, adoravit prona in terram, et ait: Ecce famula tua sit in ancillam, ut lavet pedes servorum domini mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Et festinavit, et surrexit Abigail, et ascendit super asinum, et quinque puellæ ierunt cum ea, pedissequæ ejus, et secuta est nuntios David: et facta est illi uxor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Sed et Achinoam accepit David de Jezraël: et fuit utraque uxor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul autem dedit Michol filiam suam, uxorem David, Phalti filio Lais, qui erat de Gallim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Et venerunt Ziphæi ad Saul in Gabaa, dicentes: Ecce David absconditus est in colle Hachila, quæ est ex adverso solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Et surrexit Saul, et descendit in desertum Ziph, et cum eo tria millia virorum de electis Israël, ut quæreret David in deserto Ziph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Et castrametatus est Saul in Gabaa Hachila, quæ erat ex adverso solitudinis in via: David autem habitabat in deserto. Videns autem quod venisset Saul post se in desertum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'misit exploratores, et didicit quod illuc venisset certissime.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Et surrexit David clam, et venit ad locum ubi erat Saul: cumque vidisset locum in quo dormiebat Saul, et Abner filius Ner, princeps militiæ ejus, et Saulem dormientem in tentorio, et reliquum vulgus per circuitum ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'ait David ad Achimelech Hethæum, et Abisai filium Sarviæ fratrem Joab, dicens: Quis descendet mecum ad Saul in castra? Dixitque Abisai: Ego descendam tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Venerunt ergo David et Abisai ad populum nocte, et invenerunt Saul jacentem et dormientem in tentorio, et hastam fixam in terra ad caput ejus: Abner autem et populum dormientes in circuitu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Dixitque Abisai ad David: Conclusit Deus inimicum tuum hodie in manus tuas: nunc ergo perfodiam eum lancea in terra semel, et secundo opus non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Et dixit David ad Abisai: Ne interficias eum: quis enim extendet manum suam in christum Domini, et innocens erit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Et dixit David: Vivit Dominus, quia nisi Dominus percusserit eum, aut dies ejus venerit ut moriatur, aut in prælium descendens perierit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'propitius sit mihi Dominus ne extendam manum meam in christum Domini. Nunc igitur tolle hastam quæ est ad caput ejus, et scyphum aquæ, et abeamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Tulit igitur David hastam, et scyphum aquæ qui erat ad caput Saul, et abierunt: et non erat quisquam qui videret, et intelligeret, et evigilaret, sed omnes dormiebant, quia sopor Domini irruerat super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Cumque transisset David ex adverso, et stetisset in vertice montis de longe, et esset grande intervallum inter eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'clamavit David ad populum, et ad Abner filium Ner, dicens: Nonne respondebis, Abner? Et respondens Abner, ait: Quis es tu, qui clamas, et inquietas regem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Et ait David ad Abner: Numquid non vir tu es? et quis alius similis tui in Israël? quare ergo non custodisti dominum tuum regem? ingressus est enim unus de turba ut interficeret regem dominum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Non est bonum hoc, quod fecisti: vivit Dominus, quoniam filii mortis estis vos, qui non custodistis dominum vestrum, christum Domini: nunc ergo vide ubi sit hasta regis, et ubi sit scyphus aquæ qui erat ad caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Cognovit autem Saul vocem David, et dixit: Numquid vox hæc tua, fili mi David? Et ait David: Vox mea, domine mi rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Et ait: Quam ob causam dominus meus persequitur servum suum? quid feci? aut quod est malum in manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Nunc ergo audi, oro, domine mi rex, verba servi tui: si Dominus incitat te adversum me, odoretur sacrificium: si autem filii hominum, maledicti sunt in conspectu Domini qui ejecerunt me hodie ut non habitem in hæreditate Domini, dicentes: Vade, servi diis alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Et nunc non effundatur sanguis meus in terram coram Domino: quia egressus est rex Israël ut quærat pulicem unum, sicut persequitur perdix in montibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Et ait Saul: Peccavi: revertere, fili mi David: nequaquam enim ultra tibi malefaciam, eo quod pretiosa fuerit anima mea in oculis tuis hodie: apparet enim quod stulte egerim, et ignoraverim multa nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Et respondens David, ait: Ecce hasta regis: transeat unus de pueris regis, et tollat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Dominus autem retribuet unicuique secundum justitiam suam et fidem: tradidit enim te Dominus hodie in manum meam, et nolui extendere manum meam in christum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Et sicut magnificata est anima tua hodie in oculis meis, sic magnificetur anima mea in oculis Domini, et liberet me de omni angustia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Ait ergo Saul ad David: Benedictus tu, fili mi David: et quidem faciens facies, et potens poteris. Abiit autem David in viam suam, et Saul reversus est in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Et ait David in corde suo: Aliquando incidam una die in manus Saul: nonne melius est ut fugiam, et salver in terra Philisthinorum, ut desperet Saul, cessetque me quærere in cunctis finibus Israël? fugiam ergo manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Et surrexit David, et abiit ipse, et sexcenti viri cum eo, ad Achis filium Maoch regem Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Et habitavit David cum Achis in Geth, ipse et viri ejus: vir et domus ejus: et David, et duæ uxores ejus, Achinoam Jezrahelitis, et Abigail uxor Nabal Carmeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Et nuntiatum est Sauli quod fugisset David in Geth, et non addidit ultra quærere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Dixit autem David ad Achis: Si inveni gratiam in oculis tuis, detur mihi locus in una urbium regionis hujus, ut habitem ibi: cur enim manet servus tuus in civitate regis tecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Dedit itaque ei Achis in die illa Siceleg: propter quam causam facta est Siceleg regum Juda usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Fuit autem numerus dierum quibus habitavit David in regione Philisthinorum, quatuor mensium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Et ascendit David et viri ejus, et agebant prædas de Gessuri, et de Gerzi, et de Amalecitis: hi enim pagi habitabantur in terra antiquitus, euntibus Sur usque ad terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Et percutiebat David omnem terram, nec relinquebat viventem virum et mulierem: tollensque oves, et boves, et asinos, et camelos, et vestes, revertebatur, et veniebat ad Achis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Dicebat autem ei Achis: In quem irruisti hodie? Respondebat David: Contra meridiem Judæ, et contra meridiem Jerameel, et contra meridiem Ceni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Virum et mulierem non vivificabat David, nec adducebat in Geth, dicens: Ne forte loquantur adversum nos: Hæc fecit David: et hoc erat decretum illi omnibus diebus quibus habitavit in regione Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Credidit ergo Achis David, dicens: Multa mala operatus est contra populum suum Israël: erit igitur mihi servus sempiternus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Factum est autem in diebus illis, congregaverunt Philisthiim agmina sua, ut præpararentur ad bellum contra Israël: dixitque Achis ad David: Sciens nunc scito quoniam mecum egredieris in castris, tu et viri tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Dixitque David ad Achis: Nunc scies quæ facturus est servus tuus. Et ait Achis ad David: Et ego custodem capitis mei ponam te cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel autem mortuus est, planxitque eum omnis Israël, et sepelierunt eum in Ramatha urbe sua. Et Saul abstulit magos et hariolos de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Congregatique sunt Philisthiim, et venerunt, et castrametati sunt in Sunam: congregavit autem et Saul universum Israël, et venit in Gelboë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Et vidit Saul castra Philisthiim, et timuit, et expavit cor ejus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Consuluitque Dominum, et non respondit ei neque per somnia, neque per sacerdotes, neque per prophetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Dixitque Saul servis suis: Quærite mihi mulierem habentem pythonem, et vadam ad eam, et sciscitabor per illam. Et dixerunt servi ejus ad eum: Est mulier pythonem habens in Endor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Mutavit ergo habitum suum, vestitusque est aliis vestimentis, et abiit ipse, et duo viri cum eo: veneruntque ad mulierem nocte, et ait illi: Divina mihi in pythone, et suscita mihi quem dixero tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Et ait mulier ad eum: Ecce, tu nosti quanta fecerit Saul, et quomodo eraserit magos et hariolos de terra: quare ergo insidiaris animæ meæ, ut occidar?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Et juravit ei Saul in Domino, dicens: Vivit Dominus, quia non eveniet tibi quidquam mali propter hanc rem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Dixitque ei mulier: Quem suscitabo tibi? Qui ait: Samuelem mihi suscita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Cum autem vidisset mulier Samuelem, exclamavit voce magna, et dixit ad Saul: Quare imposuisti mihi? tu es enim Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Dixitque ei rex: Noli timere: quid vidisti? Et ait mulier ad Saul: Deos vidi ascendentes de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Dixitque ei: Qualis est forma ejus? Quæ ait: Vir senex ascendit, et ipse amictus est pallio. Et intellexit Saul quod Samuel esset, et inclinavit se super faciem suam in terra, et adoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Dixit autem Samuel ad Saul: Quare inquietasti me ut suscitarer? Et ait Saul: Coarctor nimis: siquidem Philisthiim pugnant adversum me, et Deus recessit a me, et exaudire me noluit neque in manu prophetarum, neque per somnia: vocavi ergo te, ut ostenderes mihi quid faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Et ait Samuel: Quid interrogas me, cum Dominus recesserit a te, et transierit ad æmulum tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Faciet enim tibi Dominus sicut locutus est in manu mea, et scindet regnum tuum de manu tua et dabit illud proximo tuo David:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'quia non obedisti voci Domini, neque fecisti iram furoris ejus in Amalec: idcirco quod pateris, fecit tibi Dominus hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Et dabit Dominus etiam Israël tecum in manus Philisthiim: cras autem tu et filii tui mecum eritis: sed et castra Israël tradet Dominus in manus Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Statimque Saul cecidit porrectus in terram: extimuerat enim verba Samuelis, et robur non erat in eo, quia non comederat panem tota die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Ingressa est itaque mulier illa ad Saul (conturbatus enim erat valde), dixitque ad eum: Ecce obedivit ancilla tua voci tuæ, et posui animam meam in manu mea: et audivi sermones tuos, quos locutus es ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Nunc igitur audi et tu vocem ancillæ tuæ, et ponam coram te buccellam panis, ut comedens convalescas, et possis iter agere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Qui renuit, et ait: Non comedam. Coëgerunt autem eum servi sui et mulier, et tandem audita voce eorum surrexit de terra, et sedit super lectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Mulier autem illa habebat vitulum pascualem in domo, et festinavit, et occidit eum: tollensque farinam, miscuit eam, et coxit azyma,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'et posuit ante Saul et ante servos ejus. Qui cum comedissent, surrexerunt, et ambulaverunt per totam noctem illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Congregata sunt ergo Philisthiim universa agmina in Aphec: sed et Israël castrametatus est super fontem qui erat in Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Et satrapæ quidem Philisthiim incedebant in centuriis et millibus: David autem et viri ejus erant in novissimo agmine cum Achis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Dixeruntque principes Philisthiim ad Achis: Quid sibi volunt Hebræi isti? Et ait Achis ad principes Philisthiim: Num ignoratis David, qui fuit servus Saul regis Israël, et est apud me multis diebus, vel annis, et non inveni in eo quidquam ex die qua transfugit ad me usque ad diem hanc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Irati sunt autem adversus eum principes Philisthiim, et dixerunt ei: Revertatur vir iste, et sedeat in loco suo in quo constituisti eum, et non descendat nobiscum in prælium, ne fiat nobis adversarius, cum præliari cœperimus: quomodo enim aliter poterit placare dominum suum, nisi in capitibus nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Nonne iste est David, cui cantabant in choris, dicentes: Percussit Saul in millibus suis, et David in decem millibus suis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Vocavit ergo Achis David, et ait ei: Vivit Dominus, quia rectus es tu, et bonus in conspectu meo: et exitus tuus, et introitus tuus mecum est in castris: et non inveni in te quidquam mali ex die qua venisti ad me usque in diem hanc: sed satrapis non places.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Revertere ergo, et vade in pace, et non offendas oculos satraparum Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Dixitque David ad Achis: Quid enim feci, et quid invenisti in me servo tuo, a die qua fui in conspectu tuo usque in diem hanc, ut non veniam et pugnem contra inimicos domini mei regis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Respondens autem Achis, locutus est ad David: Scio quia bonus es tu in oculis meis, sicut angelus Dei: sed principes Philisthinorum dixerunt: Non ascendet nobiscum in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Igitur consurge mane tu, et servi domini tui qui venerunt tecum: et cum de nocte surrexeritis, et cœperit dilucescere, pergite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Surrexit itaque de nocte David, ipse et viri ejus, ut proficiscerentur mane, et reverterentur ad terram Philisthiim: Philisthiim autem ascenderunt in Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Cumque venissent David et viri ejus in Siceleg die tertia, Amalecitæ impetum fecerant ex parte australi in Siceleg, et percusserant Siceleg, et succenderant eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Et captivas duxerant mulieres ex ea, a minimo usque ad magnum: et non interfecerant quemquam, sed secum duxerant, et pergebant itinere suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Cum ergo venissent David et viri ejus ad civitatem, et invenissent eam succensam igni, et uxores suas, et filios suos et filias, ductas esse captivas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'levaverunt David et populus qui erat cum eo voces suas, et planxerunt donec deficerent in eis lacrimæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Siquidem et duæ uxores David captivæ ductæ fuerant, Achinoam Jezrahelites, et Abigail uxor Nabal Carmeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Et contristatus est David valde: volebat enim eum populus lapidare, quia amara erat anima uniuscujusque viri super filiis suis et filiabus: confortatus est autem David in Domino Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Et ait ad Abiathar sacerdotem filium Achimelech: Applica ad me ephod. Et applicavit Abiathar ephod ad David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Et consuluit David Dominum, dicens: Persequar latrunculos hos, et comprehendam eos, an non? Dixitque ei Dominus: Persequere: absque dubio enim comprehendes eos, et excuties prædam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Abiit ergo David, ipse et sexcenti viri qui erant cum eo, et venerunt usque ad torrentem Besor: et lassi quidam substiterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Persecutus est autem David ipse, et quadringenti viri: substiterant enim ducenti, qui lassi transire non poterant torrentem Besor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Et invenerunt virum ægyptium in agro, et adduxerunt eum ad David: dederuntque ei panem ut comederet, et biberet aquam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'sed et fragmen massæ caricarum, et duas ligaturas uvæ passæ. Quæ cum comedisset, reversus est spiritus ejus, et refocillatus est: non enim comederat panem, neque biberat aquam, tribus diebus et tribus noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Dixit itaque ei David: Cujus es tu? vel unde? et quo pergis? Qui ait: Puer ægyptius ego sum, servus viri Amalecitæ: dereliquit autem me dominus meus, quia ægrotare cœpi nudiustertius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Siquidem nos erupimus ad australem plagam Cerethi, et contra Judam, et ad meridiem Caleb, et Siceleg succendimus igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Dixitque ei David: Potes me ducere ad cuneum istum? Qui ait: Jura mihi per Deum quod non occidas me, et non tradas me in manus domini mei, et ego ducam te ad cuneum istum. Et juravit ei David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Qui cum duxisset eum, ecce illi discumbebant super faciem universæ terræ comedentes et bibentes, et quasi festum celebrantes diem, pro cuncta præda et spoliis quæ ceperant de terra Philisthiim et de terra Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Et percussit eos David a vespere usque ad vesperam alterius diei, et non evasit ex eis quisquam, nisi quadringenti viri adolescentes, qui ascenderant camelos et fugerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Eruit ergo David omnia quæ tulerant Amalecitæ, et duas uxores suas eruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nec defuit quidquam a parvo usque ad magnum, tam de filiis quam de filiabus, et de spoliis, et quæcumque rapuerant: omnia reduxit David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Et tulit universos greges et armenta, et minavit ante faciem suam: dixeruntque: Hæc est præda David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Venit autem David ad ducentos viros qui lassi substiterant, nec sequi potuerant David, et residere eos jusserat in torrente Besor: qui egressi sunt obviam David et populo qui erat cum eo. Accedens autem David ad populum, salutavit eos pacifice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Respondensque omnis vir pessimus et iniquus de viris qui ierant cum David, dixit: Quia non venerunt nobiscum, non dabimus eis quidquam de præda quam eruimus: sed sufficiat unicuique uxor sua et filii: quos cum acceperint, recedant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Dixit autem David: Non sic facietis, fratres mei, de his quæ tradidit nobis Dominus, et custodivit nos, et dedit latrunculos qui eruperant adversum nos, in manus nostras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'nec audiet vos quisquam super sermone hoc: æqua enim pars erit descendentis ad prælium, et remanentis ad sarcinas, et similiter divident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Et factum est hoc ex die illa et deinceps, constitutum et præfinitum, et quasi lex in Israël usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Venit ergo David in Siceleg, et misit dona de præda senioribus Juda proximis suis, dicens: Accipite benedictionem de præda hostium Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'his qui erant in Bethel, et qui in Ramoth ad meridiem, et qui in Jether,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'et qui in Aroër, et qui in Sephamoth, et qui in Esthamo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'et qui in Rachal, et qui in urbibus Jerameel, et qui in urbibus Ceni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'et qui in Arama, et qui in lacu Asan, et qui in Athach,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'et qui in Hebron, et reliquis qui erant in his locis in quibus commoratus fuerat David, ipse et viri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Philisthiim autem pugnabant adversum Israël: et fugerunt viri Israël ante faciem Philisthiim, et ceciderunt interfecti in monte Gelboë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Irrueruntque Philisthiim in Saul et in filios ejus, et percusserunt Jonathan, et Abinadab, et Melchisua filios Saul:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'totumque pondus prælii versum est in Saul, et consecuti sunt eum viri sagittarii, et vulneratus est vehementer a sagittariis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Dixitque Saul ad armigerum suum: Evagina gladium tuum, et percute me: ne forte veniant incircumcisi isti, et interficiant me, illudentes mihi. Et noluit armiger ejus: fuerat enim nimio terrore perterritus. Arripuit itaque Saul gladium, et irruit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Quod cum vidisset armiger ejus, videlicet quod mortuus esset Saul, irruit etiam ipse super gladium suum, et mortuus est cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Mortuus est ergo Saul, et tres filii ejus, et armiger illius, et universi viri ejus in die illa pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Videntes autem viri Israël qui erant trans vallem et trans Jordanem, quod fugissent viri Israëlitæ, et quod mortuus esset Saul et filii ejus, reliquerunt civitates suas, et fugerunt: veneruntque Philisthiim, et habitaverunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Facta autem die altera, venerunt Philisthiim ut spoliarent interfectos, et invenerunt Saul et tres filios ejus jacentes in monte Gelboë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Et præciderunt caput Saul, et spoliaverunt eum armis: et miserunt in terram Philisthinorum per circuitum, ut annuntiaretur in templo idolorum, et in populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Et posuerunt arma ejus in templo Astaroth, corpus vero ejus suspenderunt in muro Bethsan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Quod cum audissent habitatores Jabes Galaad, quæcumque fecerant Philisthiim Saul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'surrexerunt omnes viri fortissimi, et ambulaverunt tota nocte, et tulerunt cadaver Saul, et cadavera filiorum ejus, de muro Bethsan: veneruntque Jabes Galaad, et combusserunt ea ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'et tulerunt ossa eorum, et sepelierunt in nemore Jabes, et jejunaverunt septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Factum est autem, postquam mortuus est Saul, ut David reverteretur a cæde Amalec, et maneret in Siceleg duos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'In die autem tertia apparuit homo veniens de castris Saul veste conscissa, et pulvere conspersus caput: et ut venit ad David, cecidit super faciem suam, et adoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Dixitque ad eum David: Unde venis? Qui ait ad eum: De castris Israël fugi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Et dixit ad eum David: Quod est verbum quod factum est? indica mihi. Qui ait: Fugit populus ex prælio, et multi corruentes e populo mortui sunt: sed et Saul et Jonathas filius ejus interierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Dixitque David ad adolescentem qui nuntiabat ei: Unde scis quia mortuus est Saul, et Jonathas filius ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Et ait adolescens qui nuntiabat ei: Casu veni in montem Gelboë, et Saul incumbebat super hastam suam: porro currus et equites appropinquabant ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'et conversus post tergum suum, vidensque me, vocavit. Cui cum respondissem: Adsum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'dixit mihi: Quisnam es tu? Et aio ad eum: Amalecites ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Et locutus est mihi: Sta super me, et interfice me: quoniam tenent me angustiæ, et adhuc tota anima mea in me est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Stansque super eum, occidi illum: sciebam enim quod vivere non poterat post ruinam: et tuli diadema quod erat in capite ejus, et armillam de brachio illius, et attuli ad te dominum meum huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Apprehendens autem David, vestimenta sua scidit, omnesque viri qui erant cum eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'et planxerunt, et fleverunt, et jejunaverunt usque ad vesperam super Saul, et super Jonathan filium ejus, et super populum Domini, et super domum Israël, eo quod corruissent gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Dixitque David ad juvenem qui nuntiaverat ei: Unde es tu? Qui respondit: Filius hominis advenæ Amalecitæ ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Et ait ad eum David: Quare non timuisti mittere manum tuam ut occideres christum Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Vocansque David unum de pueris suis, ait: Accedens irrue in eum. Qui percussit illum, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Et ait ad eum David: Sanguis tuus super caput tuum: os enim tuum locutum est adversum te, dicens: Ego interfeci christum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Planxit autem David planctum hujuscemodi super Saul, et super Jonathan filium ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(et præcepit ut docerent filios Juda arcum, sicut scriptum est in libro justorum), et ait: Considera, Israël, pro his qui mortui sunt, super excelsa tua vulnerati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Inclyti Israël super montes tuos interfecti sunt: quomodo ceciderunt fortes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Nolite annuntiare in Geth, neque annuntietis in compitis Ascalonis: ne forte lætentur filiæ Philisthiim; ne exultent filiæ incircumcisorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montes Gelboë, nec ros, nec pluvia veniant super vos, neque sint agri primitiarum: quia ibi abjectus est clypeus fortium: clypeus Saul, quasi non esset unctus oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'A sanguine interfectorum, ab adipe fortium, sagitta Jonathæ numquam rediit retrorsum, et gladius Saul non est reversus inanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul et Jonathas amabiles, et decori in vita sua, in morte quoque non sunt divisi: aquilis velociores, leonibus fortiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filiæ Israël, super Saul flete, qui vestiebat vos coccino in deliciis, qui præbebat ornamenta aurea cultui vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Quomodo ceciderunt fortes in prælio? Jonathas in excelsis tuis occisus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Doleo super te, frater mi Jonatha, decore nimis, et amabilis super amorem mulierum. Sicut mater unicum amat filium suum, ita ego te diligebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Quomodo ceciderunt robusti, et perierunt arma bellica?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Igitur post hæc consuluit David Dominum, dicens: Num ascendam in unam de civitatibus Juda? Et ait Dominus ad eum: Ascende. Dixitque David: Quo ascendam? Et respondit ei: In Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Ascendit ergo David, et duæ uxores ejus, Achinoam Jezraëlites, et Abigail uxor Nabal Carmeli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'sed et viros, qui erant cum eo, duxit David singulos cum domo sua: et manserunt in oppidis Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Veneruntque viri Juda, et unxerunt ibi David ut regnaret super domum Juda. Et nuntiatum est David quod viri Jabes Galaad sepelissent Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Misit ergo David nuntios ad viros Jabes Galaad, dixitque ad eos: Benedicti vos Domino, qui fecistis misericordiam hanc cum domino vestro Saul, et sepelistis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Et nunc retribuet vobis quidem Dominus misericordiam et veritatem: sed et ego reddam gratiam, eo quod fecistis verbum istud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Confortentur manus vestræ, et estote filii fortitudinis: licet enim mortuus sit dominus vester Saul, tamen me unxit domus Juda in regem sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner autem filius Ner, princeps exercitus Saul, tulit Isboseth filium Saul, et circumduxit eum per castra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'regemque constituit super Galaad, et super Gessuri, et super Jezraël, et super Ephraim, et super Benjamin, et super Israël universum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Quadraginta annorum erat Isboseth filius Saul cum regnare cœpisset super Israël, et duobus annis regnavit: sola autem domus Juda sequebatur David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Et fuit numerus dierum quos commoratus est David imperans in Hebron super domum Juda, septem annorum et sex mensium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Egressusque est Abner filius Ner, et pueri Isboseth filii Saul, de castris in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Porro Joab filius Sarviæ, et pueri David, egressi sunt, et occurrerunt eis juxta piscinam Gabaon. Et cum in unum convenissent, e regione sederunt: hi ex una parte piscinæ, et illi ex altera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Dixitque Abner ad Joab: Surgant pueri, et ludant coram nobis. Et respondit Joab: Surgant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Surrexerunt ergo, et transierunt numero duodecim de Benjamin, ex parte Isboseth filii Saul, et duodecim de pueris David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Apprehensoque unusquisque capite comparis sui, defixit gladium in latus contrarii, et ceciderunt simul: vocatumque est nomen loci illius: Ager robustorum, in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Et ortum est bellum durum satis in die illa: fugatusque est Abner et viri Israël a pueris David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Erant autem ibi tres filii Sarviæ, Joab, et Abisai, et Asaël: porro Asaël cursor velocissimus fuit, quasi unus de capreis quæ morantur in silvis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Persequebatur autem Asaël Abner, et non declinavit ad dextram neque ad sinistram omittens persequi Abner.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Respexit itaque Abner post tergum suum, et ait: Tune es Asaël? Qui respondit: Ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Dixitque ei Abner: Vade ad dexteram, sive ad sinistram, et apprehende unum de adolescentibus, et tolle tibi spolia ejus. Noluit autem Asaël omittere quin urgeret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Rursumque locutus est Abner ad Asaël: Recede, noli me sequi, ne compellar confodere te in terram, et levare non potero faciem meam ad Joab fratrem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Qui audire contempsit, et noluit declinare: percussit ergo eum Abner aversa hasta in inguine, et transfodit, et mortuus est in eodem loco: omnesque qui transibant per locum illum, in quo ceciderat Asaël et mortuus erat, subsistebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Persequentibus autem Joab et Abisai fugientem Abner, sol occubuit: et venerunt usque ad collem aquæductus, qui est ex adverso vallis itineris deserti in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Congregatique sunt filii Benjamin ad Abner: et conglobati in unum cuneum, steterunt in summitate tumuli unius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Et exclamavit Abner ad Joab, et ait: Num usque ad internecionem tuus mucro desæviet? an ignoras quod periculosa sit desperatio? usquequo non dicis populo ut omittat persequi fratres suos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Et ait Joab: Vivit Dominus, si locutus fuisses, mane recessisset populus persequens fratrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Insonuit ergo Joab buccina, et stetit omnis exercitus, nec persecuti sunt ultra Israël, neque iniere certamen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner autem et viri ejus abierunt per campestria, tota nocte illa: et transierunt Jordanem, et lustrata omni Beth-horon, venerunt ad castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Porro Joab reversus, omisso Abner, congregavit omnem populum: et defuerunt de pueris David decem et novem viri, excepto Asaële.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Servi autem David percusserunt de Benjamin, et de viris qui erant cum Abner, trecentos sexaginta, qui et mortui sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Tuleruntque Asaël, et sepelierunt eum in sepulchro patris sui in Bethlehem: et ambulaverunt tota nocte Joab et viri qui erant cum eo, et in ipso crepusculo pervenerunt in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Facta est ergo longa concertatio inter domum Saul et inter domum David: David proficiscens, et semper seipso robustior, domus autem Saul decrescens quotidie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Natique sunt filii David in Hebron: fuitque primogenitus ejus Amnon, de Achinoam Jezraëlitide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Et post eum Cheleab, de Abigail uxore Nabal Carmeli: porro tertius Absalom, filius Maacha filiæ Tholmai regis Gessur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Quartus autem Adonias, filius Haggith: et quintus Saphathia, filius Abital.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Sextus quoque Jethraam, de Egla uxore David: hi nati sunt David in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Cum ergo esset prælium inter domum Saul et domum David, Abner filius Ner regebat domum Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Fuerat autem Sauli concubina nomine Respha, filia Aja. Dixitque Isboseth ad Abner:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Quare ingressus es ad concubinam patris mei? Qui iratus nimis propter verba Isboseth, ait: Numquid caput canis ego sum adversum Judam hodie, qui fecerim misericordiam super domum Saul patris tui, et super fratres et proximos ejus, et non tradidi te in manus David, et tu requisisti in me quod argueres pro muliere hodie?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Hæc faciat Deus Abner, et hæc addat ei, nisi quomodo juravit Dominus David, sic faciam cum eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'ut transferatur regnum de domo Saul, et elevetur thronus David super Israël et super Judam, a Dan usque Bersabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Et non potuit respondere ei quidquam, quia metuebat illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Misit ergo Abner nuntios ad David pro se dicentes: Cujus est terra? et ut loquerentur: Fac mecum amicitias, et erit manus mea tecum, et reducam ad te universum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Qui ait: Optime: ego faciam tecum amicitias: sed unam rem peto a te, dicens: Non videbis faciem meam antequam adduxeris Michol filiam Saul: et sic venies, et videbis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Misit autem David nuntios ad Isboseth filium Saul, dicens: Redde uxorem meam Michol, quam despondi mihi centum præputiis Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Misit ergo Isboseth, et tulit eam a viro suo Phaltiel filio Lais.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Sequebaturque eam vir suus, plorans usque Bahurim: et dixit ad eum Abner: Vade, et revertere. Qui reversus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Sermonem quoque intulit Abner ad seniores Israël, dicens: Tam heri quam nudiustertius quærebatis David ut regnaret super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Nunc ergo facite: quoniam Dominus locutus est ad David, dicens: In manu servi mei David salvabo populum meum Israël de manu Philisthiim, et omnium inimicorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Locutus est autem Abner etiam ad Benjamin. Et abiit ut loqueretur ad David in Hebron omnia quæ placuerant Israëli et universo Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Venitque ad David in Hebron cum viginti viris: et fecit David Abner, et viris ejus qui venerant cum eo, convivium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Et dixit Abner ad David: Surgam, ut congregem ad te dominum meum regem omnem Israël, et ineam tecum fœdus, et imperes omnibus, sicut desiderat anima tua. Cum ergo deduxisset David Abner, et ille isset in pace,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'statim pueri David et Joab venerunt, cæsis latronibus, cum præda magna nimis: Abner autem non erat cum David in Hebron, quia jam dimiserat eum, et profectus fuerat in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Et Joab, et omnis exercitus qui erat cum eo, postea venerunt: nuntiatum est itaque Joab a narrantibus: Venit Abner filius Ner ad regem, et dimisit eum, et abiit in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Et ingressus est Joab ad regem, et ait: Quid fecisti? Ecce venit Abner ad te: quare dimisisti eum, et abiit et recessit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'ignoras Abner filium Ner, quoniam ad hoc venit ad te ut deciperet te, et sciret exitum tuum et introitum tuum, et nosset omnia quæ agis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Egressus itaque Joab a David, misit nuntios post Abner, et reduxit eum a cisterna Sira, ignorante David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Cumque rediisset Abner in Hebron, seorsum adduxit eum Joab ad medium portæ ut loqueretur ei, in dolo: et percussit illum ibi in inguine, et mortuus est in ultionem sanguinis Asaël fratris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Quod cum audisset David rem jam gestam, ait: Mundus ego sum, et regnum meum apud Dominum usque in sempiternum, a sanguine Abner filii Ner:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'et veniat super caput Joab, et super omnem domum patris ejus: nec deficiat de domo Joab fluxum seminis sustinens, et leprosus, et tenens fusum, et cadens gladio, et indigens pane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Igitur Joab et Abisai frater ejus interfecerunt Abner, eo quod occidisset Asaël fratrem eorum in Gabaon in prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Dixit autem David ad Joab, et ad omnem populum qui erat cum eo: Scindite vestimenta vestra, et accingimini saccis, et plangite ante exequias Abner. Porro rex David sequebatur feretrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Cumque sepelissent Abner in Hebron, levavit rex David vocem suam, et flevit super tumulum Abner: flevit autem et omnis populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Plangensque rex, et lugens Abner, ait: Nequaquam ut mori solent ignavi, mortuus est Abner.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Manus tuæ ligatæ non sunt, et pedes tui non sunt compedibus aggravati: sed sicut solent cadere coram filiis iniquitatis, sic corruisti. Congeminansque omnis populus flevit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Cumque venisset universa multitudo cibum capere cum David, clara adhuc die juravit David, dicens: Hæc faciat mihi Deus, et hæc addat, si ante occasum solis gustavero panem vel aliud quidquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Omnisque populus audivit, et placuerunt eis cuncta quæ fecit rex in conspectu totius populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Et cognovit omne vulgus et universus Israël in die illa, quoniam non actum fuisset a rege ut occideretur Abner filius Ner.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Dixit quoque rex ad servos suos: Num ignoratis quoniam princeps et maximus cecidit hodie in Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ego autem adhuc delicatus, et unctus rex: porro viri isti filii Sarviæ duri sunt mihi: retribuat Dominus facienti malum juxta malitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Audivit autem Isboseth filius Saul quod cecidisset Abner in Hebron: et dissolutæ sunt manus ejus, omnisque Israël perturbatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Duo autem viri principes latronum erant filio Saul, nomen uni Baana, et nomen alteri Rechab, filii Remmon Berothitæ de filiis Benjamin: siquidem et Beroth reputata est in Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Et fugerunt Berothitæ in Gethaim, fueruntque ibi advenæ usque ad tempus illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Erat autem Jonathæ filio Saul filius debilis pedibus: quinquennis enim fuit, quando venit nuntius de Saul et Jonatha ex Jezrahel. Tollens itaque eum nutrix sua, fugit: cumque festinaret ut fugeret, cecidit, et claudus effectus est: habuitque vocabulum Miphiboseth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Venientes igitur filii Remmon Berothitæ, Rechab et Baana, ingressi sunt fervente die domum Isboseth: qui dormiebat super stratum suum meridie. Et ostiaria domus purgans triticum, obdormivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Ingressi sunt autem domum latenter assumentes spicas tritici, et percusserunt eum in inguine Rechab, et Baana frater ejus, et fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Cum autem ingressi fuissent domum, ille dormiebat super lectum suum in conclavi, et percutientes interfecerunt eum: sublatoque capite ejus, abierunt per viam deserti tota nocte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'et attulerunt caput Isboseth ad David in Hebron: dixeruntque ad regem: Ecce caput Isboseth filii Saul inimici tui, qui quærebat animam tuam: et dedit Dominus domino meo regi ultionem hodie de Saul, et de semine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Respondens autem David Rechab, et Baana fratri ejus, filiis Remmon Berothitæ, dixit ad eos: Vivit Dominus, qui eruit animam meam de omni angustia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'quoniam eum qui annuntiaverat mihi, et dixerat: Mortuus est Saul: qui putabat se prospera nuntiare, tenui, et occidi eum in Siceleg, cui oportebat mercedem dare pro nuntio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Quanto magis nunc cum homines impii interfecerunt virum innoxium in domo sua, super lectum suum, non quæram sanguinem ejus de manu vestra, et auferam vos de terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Præcepit itaque David pueris suis, et interfecerunt eos: præcidentesque manus et pedes eorum, suspenderunt eos super piscinam in Hebron: caput autem Isboseth tulerunt, et sepelierunt in sepulchro Abner in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Et venerunt universæ tribus Israël ad David in Hebron, dicentes: Ecce nos os tuum et caro tua sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Sed et heri et nudiustertius cum esset Saul rex super nos, tu eras educens et reducens Israël: dixit autem Dominus ad te: Tu pasces populum meum Israël, et tu eris dux super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Venerunt quoque et seniores Israël ad regem in Hebron, et percussit cum eis rex David fœdus in Hebron coram Domino: unxeruntque David in regem super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Filius triginta annorum erat David cum regnare cœpisset, et quadraginta annis regnavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'In Hebron regnavit super Judam septem annis et sex mensibus: in Jerusalem autem regnavit triginta tribus annis super omnem Israël et Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Et abiit rex, et omnes viri qui erant cum eo, in Jerusalem, ad Jebusæum habitatorem terræ: dictumque est David ab eis: Non ingredieris huc, nisi abstuleris cæcos et claudos dicentes: Non ingredietur David huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Cepit autem David arcem Sion: hæc est civitas David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Proposuerat enim David in die illa præmium, qui percussisset Jebusæum, et tetigisset domatum fistulas, et abstulisset cæcos et claudos odientes animam David. Idcirco dicitur in proverbio: Cæcus et claudus non intrabunt in templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Habitavit autem David in arce, et vocavit eam civitatem David: et ædificavit per gyrum a Mello et intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Et ingrediebatur proficiens atque succrescens, et Dominus Deus exercituum erat cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Misit quoque Hiram rex Tyri nuntios ad David, et ligna cedrina, et artifices lignorum, artificesque lapidum ad parietes: et ædificaverunt domum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Et cognovit David quoniam confirmasset eum Dominus regem super Israël, et quoniam exaltasset regnum ejus super populum suum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Accepit ergo David adhuc concubinas et uxores de Jerusalem, postquam venerat de Hebron: natique sunt David et alii filii et filiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'et hæc nomina eorum, qui nati sunt ei in Jerusalem: Samua, et Sobab, et Nathan, et Salomon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'et Jebahar, et Elisua, et Nepheg,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'et Japhia, et Elisama, et Elioda, et Eliphaleth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Audierunt ergo Philisthiim quod unxissent David in regem super Israël, et ascenderunt universi ut quærerent David: quod cum audisset David, descendit in præsidium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Philisthiim autem venientes diffusi sunt in valle Raphaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Et consuluit David Dominum, dicens: Si ascendam ad Philisthiim? et si dabis eos in manu mea? Et dixit Dominus ad David: Ascende, quia tradens dabo Philisthiim in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Venit ergo David in Baal Pharasim: et percussit eos ibi, et dixit: Divisit Dominus inimicos meos coram me, sicut dividuntur aquæ. Propterea vocatum est nomen loci illius, Baal Pharasim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Et reliquerunt ibi sculptilia sua, quæ tulit David et viri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Et addiderunt adhuc Philisthiim ut ascenderent, et diffusi sunt in valle Raphaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Consuluit autem David Dominum: Si ascendam contra Philisthæos, et tradas eos in manus meas? Qui respondit: Non ascendas contra eos, sed gyra post tergum eorum, et venies ad eos ex adverso pyrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Et cum audieris sonitum gradientis in cacumine pyrorum, tunc inibis prælium: quia tunc egredietur Dominus ante faciem tuam, ut percutiat castra Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Fecit itaque David sicut præceperat ei Dominus, et percussit Philisthiim de Gabaa usque dum venias Gezer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Congregavit autem rursum David omnes electos ex Israël, triginta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Surrexitque David, et abiit, et universus populus qui erat cum eo de viris Juda, ut adducerent arcam Dei, super quam invocatum est nomen Domini exercituum, sedentis in cherubim super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Et imposuerunt arcam Dei super plaustrum novum: tuleruntque eam de domo Abinadab, qui erat in Gabaa: Oza autem et Ahio, filii Abinadab, minabant plaustrum novum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Cumque tulissent eam de domo Abinadab, qui erat in Gabaa, custodiens arcam Dei Ahio præcedebat arcam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'David autem et omnis Israël ludebant coram Domino in omnibus lignis fabrefactis, et citharis et lyris et tympanis et sistris et cymbalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Postquam autem venerunt ad aream Nachon, extendit Oza manum ad arcam Dei, et tenuit eam: quoniam calcitrabant boves, et declinaverunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Iratusque est indignatione Dominus contra Ozam, et percussit eum super temeritate: qui mortuus est ibi juxta arcam Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Contristatus est autem David, eo quod percussisset Dominus Ozam, et vocatum est nomen loci illius: Percussio Ozæ, usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Et extimuit David Dominum in die illa, dicens: Quomodo ingredietur ad me arca Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Et noluit divertere ad se arcam Domini in civitatem David: sed divertit eam in domum Obededom Gethæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Et habitavit arca Domini in domo Obededom Gethæi tribus mensibus: et benedixit Dominus Obededom, et omnem domum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Nuntiatumque est regi David quod benedixisset Dominus Obededom, et omnia ejus, propter arcam Dei. Abiit ergo David, et adduxit arcam Dei de domo Obededom in civitatem David cum gaudio: et erant cum David septem chori, et victima vituli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Cumque transcendissent qui portabant arcam Domini sex passus, immolabat bovem et arietem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'et David saltabat totis viribus ante Dominum: porro David erat accinctus ephod lineo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Et David et omnis domus Israël ducebant arcam testamenti Domini in jubilo, et in clangore buccinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Cumque intrasset arca Domini in civitatem David, Michol filia Saul, prospiciens per fenestram, vidit regem David subsilientem atque saltantem coram Domino: et despexit eum in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Et introduxerunt arcam Domini, et imposuerunt eam in loco suo in medio tabernaculi, quod tetenderat ei David: et obtulit David holocausta et pacifica coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Cumque complesset offerens holocausta et pacifica, benedixit populo in nomine Domini exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Et partitus est universæ multitudini Israël tam viro quam mulieri singulis collyridam panis unam, et assaturam bubulæ carnis unam, et similam frixam oleo: et abiit omnis populus, unusquisque in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Reversusque est David ut benediceret domui suæ: et egressa Michol filia Saul in occursum David, ait: Quam gloriosus fuit hodie rex Israël discooperiens se ante ancillas servorum suorum, et nudatus est, quasi si nudetur unus de scurris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Dixitque David ad Michol: Ante Dominum, qui elegit me potius quam patrem tuum et quam omnem domum ejus, et præcepit mihi ut essem dux super populum Domini in Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'et ludam, et vilior fiam plus quam factus sum: et ero humilis in oculis meis, et cum ancillis de quibus locuta es, gloriosior apparebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Igitur Michol filiæ Saul non est natus filius usque in diem mortis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Factum est autem cum sedisset rex in domo sua, et Dominus dedisset ei requiem undique ab universis inimicis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'dixit ad Nathan prophetam: Videsne quod ego habitem in domo cedrina, et arca Dei posita sit in medio pellium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Dixitque Nathan ad regem: Omne quod est in corde tuo, vade, fac: quia Dominus tecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Factum est autem in illa nocte: et ecce sermo Domini ad Nathan, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Vade, et loquere ad servum meum David: Hæc dicit Dominus: Numquid tu ædificabis mihi domum ad habitandum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Neque enim habitavi in domo ex die illa, qua eduxi filios Israël de terra \'gypti, usque in diem hanc: sed ambulabam in tabernaculo, et in tentorio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Per cuncta loca quæ transivi cum omnibus filiis Israël, numquid loquens locutus sum ad unam de tribubus Israël, cui præcepi ut pasceret populum meum Israël, dicens: Quare non ædificastis mihi domum cedrinam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Et nunc hæc dices servo meo David: Hæc dicit Dominus exercituum: Ego tuli te de pascuis sequentem greges, ut esses dux super populum meum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'et fui tecum in omnibus ubicumque ambulasti, et interfeci universos inimicos tuos a facie tua: fecique tibi nomen grande, juxta nomen magnorum qui sunt in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Et ponam locum populo meo Israël, et plantabo eum, et habitabit sub eo, et non turbabitur amplius: nec addent filii iniquitatis ut affligant eum sicut prius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'ex die qua constitui judices super populum meum Israël: et requiem dabo tibi ab omnibus inimicis tuis: prædicitque tibi Dominus quod domum faciat tibi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Cumque completi fuerint dies tui, et dormieris cum patribus tuis, suscitabo semen tuum post te, quod egredietur de utero tuo, et firmabo regnum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Ipse ædificabit domum nomini meo, et stabiliam thronum regni ejus usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ego ero ei in patrem, et ipse erit mihi in filium: qui si inique aliquid gesserit, arguam eum in virga virorum, et in plagis filiorum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Misericordiam autem meam non auferam ab eo, sicut abstuli a Saul, quem amovi a facie mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Et fidelis erit domus tua, et regnum tuum usque in æternum ante faciem tuam, et thronus tuus erit firmus jugiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Secundum omnia verba hæc, et juxta universam visionem istam, sic locutus est Nathan ad David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Ingressus est autem rex David, et sedit coram Domino, et dixit: Quis ego sum, Domine Deus, et quæ domus mea, quia adduxisti me hucusque?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Sed et hoc parum visum est in conspectu tuo, Domine Deus, nisi loquereris etiam de domo servi tui in longinquum: ista est enim lex Adam, Domine Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Quid ergo addere poterit adhuc David, ut loquatur ad te? tu enim scis servum tuum, Domine Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Propter verbum tuum, et secundum cor tuum, fecisti omnia magnalia hæc, ita ut notum faceres servo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Idcirco magnificatus es, Domine Deus, quia non est similis tui, neque est deus extra te, in omnibus quæ audivimus auribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Quæ est autem ut populus tuus Israël gens in terra, propter quam ivit Deus ut redimeret eam sibi in populum, et poneret sibi nomen, faceretque eis magnalia et horribilia super terram a facie populi tui quem redemisti tibi ex \'gypto, gentem, et deum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Firmasti enim tibi populum tuum Israël in populum sempiternum: et tu, Domine Deus, factus es eis in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Nunc ergo Domine Deus, verbum quod locutus es super servum tuum, et super domum ejus, suscita in sempiternum: et fac sicut locutus es,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'ut magnificetur nomen tuum usque in sempiternum, atque dicatur: Dominus exercituum, Deus super Israël. Et domus servi tui David erit stabilita coram Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'quia tu, Domine exercituum Deus Israël, revelasti aurem servi tui, dicens: Domum ædificabo tibi: propterea invenit servus tuus cor suum ut oraret te oratione hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nunc ergo Domine Deus, tu es Deus, et verba tua erunt vera: locutus es enim ad servum tuum bona hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Incipe ergo, et benedic domui servi tui, ut sit in sempiternum coram te: quia tu, Domine Deus, locutus es, et benedictione tua benedicetur domus servi tui in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Factum est autem post hæc, percussit David Philisthiim, et humiliavit eos, et tulit David frenum tributi de manu Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Et percussit Moab, et mensus est eos funiculo, coæquans terræ: mensus est autem duos funiculos, unum ad occidendum, et unum ad vivificandum: factusque est Moab David serviens sub tributo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Et percussit David Adarezer filium Rohob regem Soba, quando profectus est ut dominaretur super flumen Euphraten.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Et captis David ex parte ejus mille septingentis equitibus, et viginti millibus peditum, subnervavit omnes jugales curruum: dereliquit autem ex eis centum currus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Venit quoque Syria Damasci, ut præsidium ferret Adarezer regi Soba: et percussit David de Syria viginti duo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Et posuit David præsidium in Syria Damasci: factaque est Syria David serviens sub tributo: servavitque Dominus David in omnibus ad quæcumque profectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Et tulit David arma aurea quæ habebant servi Adarezer, et detulit ea in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Et de Bete et de Beroth, civitatibus Adarezer, tulit rex David æs multum nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Audivit autem Thou rex Emath quod percussisset David omne robur Adarezer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'et misit Thou Joram filium suum ad regem David, ut salutaret eum congratulans, et gratias ageret: eo quod expugnasset Adarezer, et percussisset eum. Hostis quippe erat Thou Adarezer, et in manu ejus erant vasa aurea, et vasa argentea, et vasa ærea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'quæ et ipsa sanctificavit rex David Domino cum argento et auro quæ sanctificaverat de universis gentibus quas subegerat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'de Syria, et Moab, et filiis Ammon, et Philisthiim, et Amalec, et de manubiis Adarezer filii Rohob regis Soba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Fecit quoque sibi David nomen cum reverteretur capta Syria in valle Salinarum, cæsis decem et octo millibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'et posuit in Idumæa custodes, statuitque præsidium: et facta est universa Idumæa serviens David, et servavit Dominus David in omnibus ad quæcumque profectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Et regnavit David super omnem Israël: faciebat quoque David judicium et justitiam omni populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab autem filius Sarviæ erat super exercitum: porro Josaphat filius Ahilud erat a commentariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'et Sadoc filius Achitob, et Achimelech filius Abiathar, erant sacerdotes: et Saraias, scriba:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Banaias autem filius Jojadæ super Cerethi et Phelethi: filii autem David sacerdotes erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Et dixit David: Putasne est aliquis qui remanserit de domo Saul, ut faciam cum eo misericordiam propter Jonathan?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Erat autem de domo Saul servus nomine Siba: quem cum vocasset rex ad se, dixit ei: Tune es Siba? Et ille respondit: Ego sum servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Et ait rex: Numquid superest aliquis de domo Saul, ut faciam cum eo misericordiam Dei? Dixitque Siba regi: Superest filius Jonathæ, debilis pedibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Ubi, inquit, est? Et Siba ad regem: Ecce, ait, in domo est Machir filii Ammiel, in Lodabar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Misit ergo rex David, et tulit eum de domo Machir filii Ammiel, de Lodabar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Cum autem venisset Miphiboseth filius Jonathæ filii Saul ad David, corruit in faciem suam, et adoravit. Dixitque David: Miphiboseth? Qui respondit: Adsum servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Et ait ei David: Ne timeas, quia faciens faciam in te misericordiam propter Jonathan patrem tuum, et restituam tibi omnes agros Saul patris tui: et tu comedes panem in mensa mea semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Qui adorans eum, dixit: Quis ego sum servus tuus, quoniam respexisti super canem mortuum similem mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Vocavit itaque rex Sibam puerum Saul, et dixit ei: Omnia quæcumque fuerunt Saul, et universam domum ejus, dedi filio domini tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Operare igitur ei terram tu, et filii tui, et servi tui, et inferes filio domini tui cibos ut alatur: Miphiboseth autem filius domini tui comedet semper panem super mensam meam. Erant autem Sibæ quindecim filii, et viginti servi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Dixitque Siba ad regem: Sicut jussisti, domine mi rex, servo tuo, sic faciet servus tuus: et Miphiboseth comedet super mensam meam, quasi unus de filiis regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Habebat autem Miphiboseth filium parvulum nomine Micha: omnis vero cognatio domus Sibæ serviebat Miphiboseth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Porro Miphiboseth habitabat in Jerusalem, quia de mensa regis jugiter vescebatur: et erat claudus utroque pede.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Factum est autem post hæc ut moreretur rex filiorum Ammon, et regnavit Hanon filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Dixitque David: Faciam misericordiam cum Hanon filio Naas, sicut fecit pater ejus mecum misericordiam. Misit ergo David, consolans eum per servos suos super patris interitu. Cum autem venissent servi David in terram filiorum Ammon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'dixerunt principes filiorum Ammon ad Hanon dominum suum: Putas quod propter honorem patris tui miserit David ad te consolatores, et non ideo ut investigaret, et exploraret civitatem, et everteret eam, misit David servos suos ad te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Tulit itaque Hanon servos David, rasitque dimidiam partem barbæ eorum et præscidit vestes eorum medias usque ad nates, et dimisit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Quod cum nuntiatum esset David, misit in occursum eorum: erant enim viri confusi turpiter valde, et mandavit eis David: Manete in Jericho donec crescat barba vestra, et tunc revertimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Videntes autem filii Ammon quod injuriam fecissent David, miserunt, et conduxerunt mercede Syrum Rohob, et Syrum Soba, viginti millia peditum, et a rege Maacha mille viros, et ab Istob duodecim millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Quod cum audisset David, misit Joab et omnem exercitum bellatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Egressi sunt ergo filii Ammon, et direxerunt aciem ante ipsum introitum portæ: Syrus autem Soba, et Rohob, et Istob, et Maacha, seorsum erant in campo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Videns igitur Joab quod præparatum esset adversum se prælium et ex adverso et post tergum, elegit ex omnibus electis Israël, et instruxit aciem contra Syrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'reliquam autem partem populi tradidit Abisai fratri suo, qui direxit aciem adversus filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Et ait Joab: Si prævaluerint adversum me Syri, eris mihi in adjutorium: si autem filii Ammon prævaluerint adversum te, auxiliabor tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Esto vir fortis, et pugnemus pro populo nostro et civitate Dei nostri: Dominus autem faciet quod bonum est in conspectu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Iniit itaque Joab, et populus qui erat cum eo, certamen contra Syros: qui statim fugerunt a facie ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Filii autem Ammon videntes quia fugissent Syri, fugerunt et ipsi a facie Abisai, et ingressi sunt civitatem: reversusque est Joab a filiis Ammon, et venit Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Videntes igitur Syri quoniam corruissent coram Israël, congregati sunt pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Misitque Adarezer, et eduxit Syros qui erant trans fluvium, et adduxit eorum exercitum: Sobach autem, magister militiæ Adarezer, erat princeps eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Quod cum nuntiatum esset David, contraxit omnem Israëlem, et transivit Jordanem, venitque in Helam: et direxerunt aciem Syri ex adverso David, et pugnaverunt contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Fugeruntque Syri a facie Israël, et occidit David de Syris septingentos currus, et quadraginta millia equitum: et Sobach principem militiæ percussit, qui statim mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Videntes autem universi reges qui erant in præsidio Adarezer, se victos esse ab Israël, expaverunt, et fugerunt quinquaginta et octo millia coram Israël. Et fecerunt pacem cum Israël, et servierunt eis: timueruntque Syri auxilium præbere ultra filiis Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Factum est autem, vertente anno, eo tempore quo solent reges ad bella procedere, misit David Joab, et servos suos cum eo, et universum Israël, et vastaverunt filios Ammon, et obsederunt Rabba: David autem remansit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Dum hæc agerentur, accidit ut surgeret David de strato suo post meridiem, et deambularet in solario domus regiæ: viditque mulierem se lavantem ex adverso super solarium suum: erat autem mulier pulchra valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Misit ergo rex, et requisivit quæ esset mulier. Nuntiatumque est ei quod ipsa esset Bethsabee filia Eliam, uxor Uriæ Hethæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Missis itaque David nuntiis, tulit eam: quæ cum ingressa esset ad illum, dormivit cum ea: statimque sanctificata est ab immunditia sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'et reversa est domum suam concepto fœtu. Mittensque nuntiavit David, et ait: Concepi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Misit autem David ad Joab, dicens: Mitte ad me Uriam Hethæum. Misitque Joab Uriam ad David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Et venit Urias ad David. Quæsivitque David quam recte ageret Joab et populus, et quomodo administraretur bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Et dixit David ad Uriam: Vade in domum tuam, et lava pedes tuos. Et egressus est Urias de domo regis, secutusque est eum cibus regius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Dormivit autem Urias ante portam domus regiæ cum aliis servis domini sui, et non descendit ad domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Nuntiatumque est David a dicentibus: Non ivit Urias in domum suam. Et ait David ad Uriam: Numquid non de via venisti? quare non descendisti in domum tuam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Et ait Urias ad David: Arca Dei et Israël et Juda habitant in papilionibus, et dominus meus Joab et servi domini mei super faciem terræ manent: et ego ingrediar domum meam, ut comedam et bibam, et dormiam cum uxore mea? Per salutem tuam, et per salutem animæ tuæ, non faciam rem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Ait ergo David ad Uriam: Mane hic etiam hodie, et cras dimittam te. Mansit Urias in Jerusalem in die illa et altera:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'et vocavit eum David ut comederet coram se et biberet, et inebriavit eum: qui egressus vespere, dormivit in strato suo cum servis domini sui, et in domum suam non descendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Factum est ergo mane, et scripsit David epistolam ad Joab: misitque per manum Uriæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'scribens in epistola: Ponite Uriam ex adverso belli, ubi fortissimum est prælium: et derelinquite eum, ut percussus intereat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Igitur cum Joab obsideret urbem, posuit Uriam in loco ubi sciebat viros esse fortissimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Egressique viri de civitate, bellabant adversum Joab, et ceciderunt de populo servorum David, et mortuus est etiam Urias Hethæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Misit itaque Joab, et nuntiavit David omnia verba prælii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'præcepitque nuntio, dicens: Cum compleveris universos sermones belli ad regem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'si eum videris indignari, et dixerit: Quare accessistis ad murum, ut præliaremini? an ignorabatis quod multa desuper ex muro tela mittantur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Quis percussit Abimelech filium Jerobaal? nonne mulier misit super eum fragmen molæ de muro, et interfecit eum in Thebes? quare juxta murum accessistis? dices: Etiam servus tuus Urias Hethæus occubuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Abiit ergo nuntius, et venit, et narravit David omnia quæ ei præceperat Joab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Et dixit nuntius ad David: Prævaluerunt adversum nos viri, et egressi sunt ad nos in agrum: nos autem facto impetu persecuti eos sumus usque ad portam civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Et direxerunt jacula sagittarii ad servos tuos ex muro desuper, mortuique sunt de servis regis: quin etiam servus tuus Urias Hethæus mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Et dixit David ad nuntium: Hæc dices Joab: Non te frangat ista res: varius enim eventus est belli, nunc hunc, et nunc illum consumit gladius: conforta bellatores tuos adversus urbem ut destruas eam, et exhortare eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Audivit autem uxor Uriæ quod mortuus esset Urias vir suus, et planxit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Transacto autem luctu, misit David, et introduxit eam in domum suam, et facta est ei uxor, peperitque ei filium: et displicuit verbum hoc quod fecerat David, coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Misit ergo Dominus Nathan ad David: qui cum venisset ad eum, dixit ei: Duo viri erant in civitate una, unus dives, et alter pauper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Dives habebat oves et boves plurimos valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Pauper autem nihil habebat omnino, præter ovem unam parvulam quam emerat et nutrierat, et quæ creverat apud eum cum filiis ejus simul, de pane illius comedens, et de calice ejus bibens, et in sinu illius dormiens: eratque illi sicut filia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Cum autem peregrinus quidam venisset ad divitem, parcens ille sumere de ovibus et de bobus suis, ut exhiberet convivium peregrino illi qui venerat ad se, tulit ovem viri pauperis, et præparavit cibos homini qui venerat ad se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Iratus autem indignatione David adversus hominem illum nimis, dixit ad Nathan: Vivit Dominus, quoniam filius mortis est vir qui fecit hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Ovem reddet in quadruplum, eo quod fecerit verbum istud, et non pepercerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Dixit autem Nathan ad David: Tu es ille vir. Hæc dicit Dominus Deus Israël: Ego unxi te in regem super Israël, et ego erui te de manu Saul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'et dedi tibi domum domini tui, et uxores domini tui in sinu tuo, dedique tibi domum Israël et Juda: et si parva sunt ista, adjiciam tibi multo majora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Quare ergo contempsisti verbum Domini, ut faceres malum in conspectu meo? Uriam Hethæum percussisti gladio, et uxorem illius accepisti in uxorem tibi, et interfecisti eum gladio filiorum Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Quam ob rem non recedet gladius de domo tua usque in sempiternum, eo quod despexeris me, et tuleris uxorem Uriæ Hethæi ut esset uxor tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Itaque hæc dicit Dominus: Ecce ego suscitabo super te malum de domo tua, et tollam uxores tuas in oculis tuis, et dabo proximo tuo: et dormiet cum uxoribus tuis in oculis solis hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Tu enim fecisti abscondite: ego autem faciam verbum istud in conspectu omnis Israël, et in conspectu solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Et dixit David ad Nathan: Peccavi Domino. Dixitque Nathan ad David: Dominus quoque transtulit peccatum tuum: non morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Verumtamen quoniam blasphemare fecisti inimicos Domini, propter verbum hoc, filius qui natus est tibi, morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Et reversus est Nathan in domum suam. Percussit quoque Dominus parvulum quem pepererat uxor Uriæ David, et desperatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Deprecatusque est David Dominum pro parvulo: et jejunavit David jejunio, et ingressus seorsum, jacuit super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Venerunt autem seniores domus ejus, cogentes eum ut surgeret de terra: qui noluit, nec comedit cum eis cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Accidit autem die septima ut moreretur infans: timueruntque servi David nuntiare ei quod mortuus esset parvulus: dixerunt enim: Ecce cum parvulus adhuc viveret, loquebamur ad eum, et non audiebat vocem nostram: quanto magis si dixerimus: Mortuus est puer, se affliget?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Cum ergo David vidisset servos suos mussitantes, intellexit quod mortuus esset infantulus: dixitque ad servos suos: Num mortuus est puer? Qui responderunt ei: Mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Surrexit ergo David de terra, et lotus unctusque est: cumque mutasset vestem, ingressus est domum Domini: et adoravit, et venit in domum suam, petivitque ut ponerent ei panem, et comedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Dixerunt autem ei servi sui: Quis est sermo quem fecisti? propter infantem, cum adhuc viveret, jejunasti et flebas: mortuo autem puero, surrexisti, et comedisti panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Qui ait: Propter infantem, dum adhuc viveret, jejunavi et flevi: dicebam enim: Quis scit si forte donet eum mihi Dominus, et vivat infans?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nunc autem quia mortuus est, quare jejunem? numquid potero revocare eum amplius? ego vadam magis ad eum: ille vero non revertetur ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Et consolatus est David Bethsabee uxorem suam, ingressusque ad eam dormivit cum ea: quæ genuit filium, et vocavit nomen ejus Salomon: et Dominus dilexit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Misitque in manu Nathan prophetæ, et vocavit nomen ejus, Amabilis Domino, eo quod diligeret eum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Igitur pugnabat Joab contra Rabbath filiorum Ammon, et expugnabat urbem regiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Misitque Joab nuntios ad David, dicens: Dimicavi adversum Rabbath, et capienda est Urbs aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Nunc igitur congrega reliquam partem populi, et obside civitatem, et cape eam: ne cum a me vastata fuerit urbs, nomini meo ascribatur victoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Congregavit itaque David omnem populum, et profectus est adversum Rabbath: cumque dimicasset, cepit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Et tulit diadema regis eorum de capite ejus, pondo auri talentum, habens gemmas pretiosissimas: et impositum est super caput David. Sed et prædam civitatis asportavit multam valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'populum quoque ejus adducens serravit, et circumegit super eos ferrata carpenta: divisitque cultris, et traduxit in typo laterum: sic fecit universis civitatibus filiorum Ammon. Et reversus est David et omnis exercitus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Factum est autem post hæc ut Absalom filii David sororem speciosissimam, vocabulo Thamar, adamaret Amnon filius David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'et deperiret eam valde, ita ut propter amorem ejus ægrotaret: quia cum esset virgo, difficile ei videbatur ut quippiam inhoneste ageret cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Erat autem Amnon amicus nomine Jonadab, filius Semmaa fratris David, vir prudens valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Qui dixit ad eum: Quare sic attenuaris macie, fili regis, per singulos dies? cur non indicas mihi? Dixitque ei Amnon: Thamar sororem fratris mei Absalom amo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Cui respondit Jonadab: Cuba super lectum tuum, et languorem simula: cumque venerit pater tuus ut visitet te, dic ei: Veniat, oro, Thamar soror mea, ut det mihi cibum, et faciat pulmentum, ut comedam de manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Accubuit itaque Amnon, et quasi ægrotare cœpit: cumque venisset rex ad visitandum eum, ait Amnon ad regem: Veniat, obsecro, Thamar soror mea, ut faciat in oculis meis duas sorbitiunculas, et cibum capiam de manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Misit ergo David ad Thamar domum, dicens: Veni in domum Amnon fratris tui, et fac ei pulmentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Venitque Thamar in domum Amnon fratris sui: ille autem jacebat. Quæ tollens farinam commiscuit, et liquefaciens, in oculis ejus coxit sorbitiunculas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Tollensque quod coxerat, effudit, et posuit coram eo, et noluit comedere: dixitque Amnon: Ejicite universos a me. Cumque ejecissent omnes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'dixit Amnon ad Thamar: Infer cibum in conclave, ut vescar de manu tua. Tulit ergo Thamar sorbitiunculas quas fecerat, et intulit ad Amnon fratrem suum in conclave.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Cumque obtulisset ei cibum, apprehendit eam, et ait: Veni, cuba mecum, soror mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Quæ respondit ei: Noli frater mi, noli opprimere me: neque enim hoc fas est in Israël: noli facere stultitiam hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Ego enim ferre non potero opprobrium meum, et tu eris quasi unus de insipientibus in Israël: quin potius loquere ad regem, et non negabit me tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Noluit autem acquiescere precibus ejus, sed prævalens viribus oppressit eam, et cubavit cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Et exosam eam habuit Amnon odio magno nimis: ita ut majus esset odium quo oderat eam, amore quo ante dilexerat. Dixitque ei Amnon: Surge, et vade.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Quæ respondit ei: Majus est hoc malum quod nunc agis adversum me, quam quod ante fecisti, expellens me. Et noluit audire eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'sed vocato puero qui ministrabat ei, dixit: Ejice hanc a me foras, et claude ostium post eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Quæ induta erat talari tunica: hujuscemodi enim filiæ regis virgines vestibus utebantur. Ejecit itaque eam minister illius foras: clausitque fores post eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Quæ aspergens cinerem capiti suo, scissa talari tunica, impositisque manibus super caput suum, ibat ingrediens, et clamans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Dixit autem ei Absalom frater suus: Numquid Amnon frater tuus concubuit tecum? sed nunc soror, tace: frater tuus est: neque affligas cor tuum pro hac re. Mansit itaque Thamar contabescens in domo Absalom fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Cum autem audisset rex David verba hæc, contristatus est valde: et noluit contristare spiritum Amnon filii sui, quoniam diligebat eum, quia primogenitus erat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Porro non est locutus Absalom ad Amnon nec malum nec bonum: oderat enim Absalom Amnon, eo quod violasset Thamar sororem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Factum est autem post tempus biennii ut tonderentur oves Absalom in Baalhasor, quæ est juxta Ephraim: et vocavit Absalom omnes filios regis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'venitque ad regem, et ait ad eum: Ecce tondentur oves servi tui: veniat, oro, rex cum servis suis ad servum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Dixitque rex ad Absalom: Noli fili mi, noli rogare ut veniamus omnes et gravemus te. Cum autem cogeret eum, et noluisset ire, benedixit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Et ait Absalom: Si non vis venire, veniat, obsecro, nobiscum saltem Amnon frater meus. Dixitque ad eum rex: Non est necesse ut vadat tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Coëgit itaque Absalom eum, et dimisit cum eo Amnon et universos filios regis. Feceratque Absalom convivium quasi convivium regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Præceperat autem Absalom pueris suis, dicens: Observate cum temulentus fuerit Amnon vino, et dixero vobis: Percutite eum, et interficite: nolite timere: ego enim sum qui præcipio vobis: roboramini, et estote viri fortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Fecerunt ergo pueri Absalom adversum Amnon sicut præceperat eis Absalom. Surgentesque omnes filii regis ascenderunt singuli mulas suas, et fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Cumque adhuc pergerent in itinere, fama pervenit ad David, dicens: Percussit Absalom omnes filios regis, et non remansit ex eis saltem unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Surrexit itaque rex, et scidit vestimenta sua, et cecidit super terram: et omnes servi illius qui assistebant ei, sciderunt vestimenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Respondens autem Jonadab filius Semmaa fratris David, dixit: Ne æstimet dominus meus rex quod omnes pueri filii regis occisi sint: Amnon solus mortuus est, quoniam in ore Absalom erat positus ex die qua oppressit Thamar sororem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Nunc ergo ne ponat dominus meus rex super cor suum verbum istud, dicens: Omnes filii regis occisi sunt: quoniam Amnon solus mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Fugit autem Absalom. Et elevavit puer speculator oculos suos, et aspexit: et ecce populus multus veniebat per iter devium ex latere montis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Dixit autem Jonadab ad regem: Ecce filii regis adsunt: juxta verbum servi tui, sic factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Cumque cessasset loqui, apparuerunt et filii regis: et intrantes levaverunt vocem suam, et fleverunt: sed et rex et omnes servi ejus fleverunt ploratu magno nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Porro Absalom fugiens abiit ad Tholomai filium Ammiud regem Gessur. Luxit ergo David filium suum cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom autem cum fugisset, et venisset in Gessur, fuit ibi tribus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Cessavitque rex David persequi Absalom, eo quod consolatus esset super Amnon interitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Intelligens autem Joab filius Sarviæ quod cor regis versum esset ad Absalom,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'misit Thecuam, et tulit inde mulierem sapientem: dixitque ad eam: Lugere te simula, et induere veste lugubri, et ne ungaris oleo, ut sis quasi mulier jam plurimo tempore lugens mortuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'et ingredieris ad regem, et loqueris ad eum sermones hujuscemodi. Posuit autem Joab verba in ore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Itaque cum ingressa fuisset mulier Thecuitis ad regem, cecidit coram eo super terram, et adoravit, et dixit: Serva me, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Et ait ad eam rex: Quid causæ habes? Quæ respondit: Heu, mulier vidua ego sum: mortuus est enim vir meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Et ancillæ tuæ erant duo filii: qui rixati sunt adversum se in agro, nullusque erat qui eos prohibere posset: et percussit alter alterum, et interfecit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Et ecce consurgens universa cognatio adversum ancillam tuam, dicit: Trade eum qui percussit fratrem suum, ut occidamus eum pro anima fratris sui quem interfecit, et deleamus hæredem: et quærunt extinguere scintillam meam quæ relicta est, ut non supersit viro meo nomen, et reliquiæ super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Et ait rex ad mulierem: Vade in domum tuam, et ego jubebo pro te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Dixitque mulier Thecuitis ad regem: In me, domine mi rex, sit iniquitas, et in domum patris mei: rex autem et thronus ejus sit innocens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Et ait rex: Qui contradixerit tibi, adduc eum ad me, et ultra non addet ut tangat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Quæ ait: Recordetur rex Domini Dei sui, ut non multiplicentur proximi sanguinis ad ulciscendum, et nequaquam interficiant filium meum. Qui ait: Vivit Dominus, quia non cadet de capillis filii tui super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Dixit ergo mulier: Loquatur ancilla tua ad dominum meum regem verbum. Et ait: Loquere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Dixitque mulier: Quare cogitasti hujuscemodi rem contra populum Dei, et locutus est rex verbum istud, ut peccet, et non reducat ejectum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Omnes morimur, et quasi aquæ dilabimur in terram, quæ non revertuntur: nec vult Deus perire animam, sed retractat cogitans ne penitus pereat qui abjectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Nunc igitur veni, ut loquar ad dominum meum regem verbum hoc, præsente populo. Et dixit ancilla tua: Loquar ad regem, si quomodo faciat rex verbum ancillæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Et audivit rex, ut liberaret ancillam suam de manu omnium qui volebant de hæreditate Dei delere me, et filium meum simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Dicat ergo ancilla tua, ut fiat verbum domini mei regis sicut sacrificium. Sicut enim angelus Dei, sic est dominus meus rex, ut nec benedictione, nec maledictione moveatur: unde et Dominus Deus tuus est tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Et respondens rex, dixit ad mulierem: Ne abscondas a me verbum quod te interrogo. Dixitque ei mulier: Loquere, domine mi rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Et ait rex: Numquid manus Joab tecum est in omnibus istis? Respondit mulier, et ait: Per salutem animæ tuæ, domine mi rex, nec ad sinistram, nec ad dexteram est ex omnibus his quæ locutus est dominus meus rex: servus enim tuus Joab, ipse præcepit mihi, et ipse posuit in os ancillæ tuæ omnia verba hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Ut verterem figuram sermonis hujus, servus tuus Joab præcepit istud: tu autem, domine mi rex, sapiens es, sicut habet sapientiam angelus Dei, ut intelligas omnia super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Et ait rex ad Joab: Ecce placatus feci verbum tuum: vade ergo, et revoca puerum Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Cadensque Joab super faciem suam in terram, adoravit, et benedixit regi: et dixit Joab: Hodie intellexit servus tuus quia inveni gratiam in oculis tuis, domine mi rex: fecisti enim sermonem servi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Surrexit ergo Joab et abiit in Gessur, et adduxit Absalom in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Dixit autem rex: Revertatur in domum suam, et faciem meam non videat. Reversus est itaque Absalom in domum suam, et faciem regis non vidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Porro sicut Absalom, vir non erat pulcher in omni Israël, et decorus nimis: a vestigio pedis usque ad verticem non erat in eo ulla macula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Et quando tondebat capillum (semel autem in anno tondebatur, quia gravabat eum cæsaries), ponderabat capillos capitis sui ducentis siclis, pondere publico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Nati sunt autem Absalom filii tres, et filia una nomine Thamar, elegantis formæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Mansitque Absalom in Jerusalem duobus annis, et faciem regis non vidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Misit itaque ad Joab, ut mitteret eum ad regem: qui noluit venire ad eum. Cumque secundo misisset, et ille noluisset venire ad eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'dixit servis suis: Scitis agrum Joab juxta agrum meum, habentem messem hordei: ite igitur, et succendite eum igni. Succenderunt ergo servi Absalom segetem igni. Et venientes servi Joab, scissis vestibus suis, dixerunt: Succenderunt servi Absalom partem agri igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Surrexitque Joab, et venit ad Absalom in domum ejus, et dixit: Quare succenderunt servi tui segetem meam igni?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Et respondit Absalom ad Joab: Misi ad te obsecrans ut venires ad me, et mitterem te ad regem, et diceres ei: Quare veni de Gessur? melius mihi erat ibi esse: obsecro ergo ut videam faciem regis: quod si memor est iniquitatis meæ, interficiat me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Ingressus itaque Joab ad regem, nuntiavit ei omnia: vocatusque est Absalom, et intravit ad regem, et adoravit super faciem terræ coram eo: osculatusque est rex Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Igitur post hæc fecit sibi Absalom currus, et equites, et quinquaginta viros qui præcederent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Et mane consurgens Absalom, stabat juxta introitum portæ, et omnem virum qui habebat negotium ut veniret ad regis judicium, vocabat Absalom ad se, et dicebat: De qua civitate es tu? Qui respondens aiebat: Ex una tribu Israël ego sum servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Respondebatque ei Absalom: Videntur mihi sermones tui boni et justi, sed non est qui te audiat constitutus a rege. Dicebatque Absalom:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Quis me constituat judicem super terram, ut ad me veniant omnes qui habent negotium, et juste judicem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Sed et cum accederet ad eum homo ut salutaret illum, extendebat manum suam, et apprehendens osculabatur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Faciebatque hoc omni Israël venienti ad judicium ut audiretur a rege, et sollicitabat corda virorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Post quadraginta autem annos, dixit Absalom ad regem David: Vadam, et reddam vota mea quæ vovi Domino in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Vovens enim vovit servus tuus cum esset in Gessur Syriæ, dicens: Si reduxerit me Dominus in Jerusalem, sacrificabo Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Dixitque ei rex David: Vade in pace. Et surrexit, et abiit in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Misit autem Absalom exploratores in universas tribus Israël, dicens: Statim ut audieritis clangorem buccinæ, dicite: Regnavit Absalom in Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Porro cum Absalom ierunt ducenti viri de Jerusalem vocati, euntes simplici corde, et causam penitus ignorantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Accersivit quoque Absalom Achitophel Gilonitem consiliarium David, de civitate sua Gilo. Cumque immolaret victimas, facta est conjuratio valida, populusque concurrens augebatur cum Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Venit igitur nuntius ad David, dicens: Toto corde universus Israël sequitur Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Et ait David servis suis qui erant cum eo in Jerusalem: Surgite, fugiamus: neque enim erit nobis effugium a facie Absalom: festinate egredi, ne forte veniens occupet nos, et impellat super nos ruinam, et percutiat civitatem in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Dixeruntque servi regis ad eum: Omnia quæcumque præceperit dominus noster rex, libenter exequemur servi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Egressus est ergo rex et universa domus ejus pedibus suis: et dereliquit rex decem mulieres concubinas ad custodiendam domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Egressusque rex et omnis Israël pedibus suis, stetit procul a domo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'et universi servi ejus ambulabant juxta eum, et legiones Cerethi, et Phelethi, et omnes Gethæi, pugnatores validi, sexcenti viri qui secuti eum fuerant de Geth pedites, præcedebant regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Dixit autem rex ad Ethai Gethæum: Cur venis nobiscum? revertere, et habita cum rege, quia peregrinus es, et egressus es de loco tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Heri venisti, et hodie compelleris nobiscum egredi? ego autem vadam quo iturus sum: revertere, et reduc tecum fratres tuos, et Dominus faciet tecum misericordiam et veritatem, quia ostendisti gratiam et fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Et respondit Ethai regi dicens: Vivit Dominus, et vivit dominus meus rex, quoniam in quocumque loco fueris, domine mi rex, sive in morte, sive in vita, ibi erit servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Et ait David Ethai: Veni, et transi. Et transivit Ethai Gethæus, et omnes viri qui cum eo erant, et reliqua multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Omnesque flebant voce magna, et universus populus transibat: rex quoque transgrediebatur torrentem Cedron, et cunctus populus incedebat contra viam quæ respicit ad desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Venit autem et Sadoc sacerdos, et universi Levitæ cum eo, portantes arcam fœderis Dei: et deposuerunt arcam Dei. Et ascendit Abiathar, donec expletus esset omnis populus qui egressus fuerat de civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Et dixit rex ad Sadoc: Reporta arcam Dei in urbem: si invenero gratiam in oculis Domini, reducet me, et ostendet mihi eam, et tabernaculum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Si autem dixerit mihi: Non places: præsto sum: faciat quod bonum est coram se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Et dixit rex ad Sadoc sacerdotem: O videns, revertere in civitatem in pace: et Achimaas filius tuus, et Jonathas filius Abiathar, duo filii vestri, sint vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Ecce ego abscondar in campestribus deserti, donec veniat sermo a vobis indicans mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Reportaverunt ergo Sadoc et Abiathar arcam Dei in Jerusalem, et manserunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Porro David ascendebat clivum Olivarum, scandens et flens, nudis pedibus incedens, et operto capite: sed et omnis populus qui erat cum eo, operto capite ascendebat plorans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Nuntiatum est autem David quod et Achitophel esset in conjuratione cum Absalom: dixitque David: Infatua, quæso, Domine, consilium Achitophel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Cumque ascenderet David summitatem montis in quo adoraturus erat Dominum, ecce occurrit ei Chusai Arachites, scissa veste, et terra pleno capite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Et dixit ei David: Si veneris mecum, eris mihi oneri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'si autem in civitatem revertaris, et dixeris Absalom: Servus tuus sum, rex: sicut fui servus patris tui, sic ero servus tuus: dissipabis consilium Achitophel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Habes autem tecum Sadoc et Abiathar sacerdotes: et omne verbum quodcumque audieris de domo regis, indicabis Sadoc et Abiathar sacerdotibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Sunt autem cum eis duo filii eorum Achimaas filius Sadoc, et Jonathas filius Abiathar: et mittetis per eos ad me omne verbum quod audieritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Veniente ergo Chusai amico David in civitatem, Absalom quoque ingressus est Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Cumque David transisset paululum montis verticem, apparuit Siba puer Miphiboseth in occursum ejus, cum duobus asinis, qui onerati erant ducentis panibus, et centum alligaturis uvæ passæ, et centum massis palatharum, et utre vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Et dixit rex Sibæ: Quid sibi volunt hæc? Responditque Siba: Asini, domesticis regis ut sedeant: panes et palathæ ad vescendum pueris tuis: vinum autem ut bibat siquis defecerit in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Et ait rex: Ubi est filius domini tui? Responditque Siba regi: Remansit in Jerusalem, dicens: Hodie restituet mihi domus Israël regnum patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Et ait rex Sibæ: Tua sint omnia quæ fuerunt Miphiboseth. Dixitque Siba: Oro ut inveniam gratiam coram te, domine mi rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Venit ergo rex David usque Bahurim: et ecce egrediebatur inde vir de cognatione domus Saul, nomine Semei, filius Gera: procedebatque egrediens, et maledicebat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'mittebatque lapides contra David et contra universos servos regis David: omnis autem populus, et universi bellatores, a dextro et a sinistro latere regis incedebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Ita autem loquebatur Semei cum malediceret regi: Egredere, egredere, vir sanguinum, et vir Belial.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Reddidit tibi Dominus universum sanguinem domus Saul: quoniam invasisti regnum pro eo, et dedit Dominus regnum in manu Absalom filii tui: et ecce premunt te mala tua, quoniam vir sanguinum es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Dixit autem Abisai filius Sarviæ regi: Quare maledicit canis hic mortuus domino meo regi? vadam, et amputabo caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Et ait rex: Quid mihi et vobis est, filii Sarviæ? dimittite eum, ut maledicat: Dominus enim præcepit ei ut malediceret David: et quis est qui audeat dicere quare sic fecerit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Et ait rex Abisai, et universis servis suis: Ecce filius meus qui egressus est de utero meo, quærit animam meam: quanto magis nunc filius Jemini? Dimittite eum ut maledicat juxta præceptum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'si forte respiciat Dominus afflictionem meam, et reddat mihi Dominus bonum pro maledictione hac hodierna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Ambulabat itaque David et socii ejus per viam cum eo. Semei autem per jugum montis ex latere contra illum gradiebatur, maledicens, et mittens lapides adversum eum, terramque spargens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Venit itaque rex, et universus populus cum eo lassus, et refocillati sunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom autem et omnis populus ejus ingressi sunt Jerusalem, sed et Achitophel cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Cum autem venisset Chusai Arachites amicus David ad Absalom, locutus est ad eum: Salve rex, salve rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Ad quem Absalom: Hæc est, inquit, gratia tua ad amicum tuum? quare non ivisti cum amico tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Responditque Chusai ad Absalom: Nequaquam: quia illius ero, quem elegit Dominus, et omnis hic populus, et universus Israël: et cum eo manebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Sed ut et hoc inferam, cui ego serviturus sum? nonne filio regis? Sicut parui patri tuo, ita parebo et tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Dixit autem Absalom ad Achitophel: Inite consilium quid agere debeamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Et ait Achitophel ad Absalom: Ingredere ad concubinas patris tui, quas dimisit ad custodiendam domum: ut cum audierit omnis Israël quod fœdaveris patrem tuum, roborentur tecum manus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Tetenderunt ergo Absalom tabernaculum in solario, ingressusque est ad concubinas patris sui coram universo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Consilium autem Achitophel quod dabat in diebus illis, quasi si quis consuleret Deum: sic erat omne consilium Achitophel, et cum esset cum David, et cum esset cum Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Dixit ergo Achitophel ad Absalom: Eligam mihi duodecim millia virorum, et consurgens persequar David hac nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Et irruens super eum (quippe qui lassus est, et solutis manibus), percutiam eum: cumque fugerit omnis populus qui cum eo est, percutiam regem desolatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Et reducam universum populum, quomodo unus homo reverti solet: unum enim virum tu quæris: et omnis populus erit in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Placuitque sermo ejus Absalom, et cunctis majoribus natu Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Ait autem Absalom: Vocate Chusai Arachiten, et audiamus quid etiam ipse dicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Cumque venisset Chusai ad Absalom, ait Absalom ad eum: Hujuscemodi sermonem locutus est Achitophel: facere debemus an non? quod das consilium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Et dixit Chusai ad Absalom: Non est bonum consilium quod dedit Achitophel hac vice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Et rursum intulit Chusai: Tu nosti patrem tuum, et viros qui cum eo sunt, esse fortissimos et amaro animo, veluti si ursa raptis catulis in saltu sæviat: sed et pater tuus vir bellator est, nec morabitur cum populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Forsitan nunc latitat in foveis, aut in uno, quo voluerit, loco: et cum ceciderit unus quilibet in principio, audiet quicumque audierit, et dicet: Facta est plaga in populo qui sequebatur Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Et fortissimus quisque, cujus cor est quasi leonis, pavore solvetur: scit enim omnis populus Israël fortem esse patrem tuum, et robustos omnes qui cum eo sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Sed hoc mihi videtur rectum esse consilium. Congregetur ad te universus Israël, a Dan usque Bersabee, quasi arena maris innumerabilis: et tu eris in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Et irruemus super eum in quocumque loco inventus fuerit, et operiemus eum, sicut cadere solet ros super terram: et non relinquemus de viris qui cum eo sunt, ne unum quidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Quod si urbem aliquam fuerit ingressus, circumdabit omnis Israël civitati illi funes, et trahemus eam in torrentem, ut non reperiatur ne calculus quidem ex ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Dixitque Absalom, et omnes viri Israël: Melius est consilium Chusai Arachitæ, consilio Achitophel: Domini autem nutu dissipatum est consilium Achitophel utile, ut induceret Dominus super Absalom malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Et ait Chusai Sadoc et Abiathar sacerdotibus: Hoc et hoc modo consilium dedit Achitophel Absalom et senioribus Israël: et ego tale et tale dedi consilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Nunc ergo mittite cito, et nuntiate David, dicentes: Ne moreris nocte hac in campestribus deserti, sed absque dilatione transgredere: ne forte absorbeatur rex, et omnis populus qui cum eo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonathas autem et Achimaas stabant juxta fontem Rogel: abiit ancilla et nuntiavit eis. Et illi profecti sunt, ut referrent ad regem David nuntium: non enim poterant videri, aut introire civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Vidit autem eos quidam puer, et indicavit Absalom: illi vero concito gradu ingressi sunt domum cujusdam viri in Bahurim, qui habebat puteum in vestibulo suo: et descenderunt in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Tulit autem mulier, et expandit velamen super os putei, quasi siccans ptisanas: et sic latuit res.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Cumque venissent servi Absalom in domum, ad mulierem dixerunt: Ubi est Achimaas et Jonathas? Et respondit eis mulier: Transierunt festinanter, gustata paululum aqua. At hi qui quærebant, cum non reperissent, reversi sunt in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Cumque abiissent, ascenderunt illi de puteo, et pergentes nuntiaverunt regi David, et dixerunt: Surgite, et transite cito fluvium: quoniam hujuscemodi dedit consilium contra vos Achitophel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Surrexit ergo David, et omnis populus qui cum eo erat, et transierunt Jordanem, donec dilucesceret: et ne unus quidem residuus fuit, qui non transisset fluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Porro Achitophel videns quod non fuisset factum consilium suum, stravit asinum suum, surrexitque, et abiit in domum suam et in civitatem suam: et disposita domo sua, suspendio interiit, et sepultus est in sepulchro patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David autem venit in castra, et Absalom transivit Jordanem, ipse et omnes viri Israël cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Amasam vero constituit Absalom pro Joab super exercitum: Amasa autem erat filius viri qui vocabatur Jetra de Jezraëli, qui ingressus est ad Abigail filiam Naas, sororem Sarviæ, quæ fuit mater Joab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Et castrametatus est Israël cum Absalom in terra Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Cumque venisset David in castra, Sobi filius Naas de Rabbath filiorum Ammon, et Machir filius Ammihel de Lodabar, et Berzellai Galaadites de Rogelim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'obtulerunt ei stratoria, et tapetia, et vasa fictilia, frumentum, et hordeum, et farinam, et polentam, et fabam, et lentem, et frixum cicer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'et mel, et butyrum, oves, et pingues vitulos: dederuntque David, et populo qui cum eo erat, ad vescendum: suspicati enim sunt populum fame et siti fatigari in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Igitur considerato David populo suo, constituit super eos tribunos et centuriones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'et dedit populi tertiam partem sub manu Joab, et tertiam partem sub manu Abisai filii Sarviæ fratris Joab, et tertiam partem sub manu Ethai, qui erat de Geth. Dixitque rex ad populum: Egrediar et ego vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Et respondit populus: Non exibis: sive enim fugerimus, non magnopere ad eos de nobis pertinebit: sive media pars ceciderit e nobis, non satis curabunt, quia tu unus pro decem millibus computaris: melius est igitur ut sis nobis in urbe præsidio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Ad quos rex ait: Quod vobis videtur rectum, hoc faciam. Stetit ergo rex juxta portam: egrediebaturque populus per turmas suas centeni et milleni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Et præcepit rex Joab, et Abisai, et Ethai, dicens: Servate mihi puerum Absalom. Et omnis populus audiebat præcipientem regem cunctis principibus pro Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Itaque egressus est populus in campum contra Israël, et factum est prælium in saltu Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Et cæsus est ibi populus Israël ab exercitu David, factaque est plaga magna in die illa, viginti millium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Fuit autem ibi prælium dispersum super faciem omnis terræ, et multo plures erant quos saltus consumpserat de populo, quam hi quos voraverat gladius in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Accidit autem ut occurreret Absalom servis David, sedens mulo: cumque ingressus fuisset mulus subter condensam quercum et magnam, adhæsit caput ejus quercui: et illo suspenso inter cælum et terram, mulus cui insederat, pertransivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Vidit autem hoc quispiam, et nuntiavit Joab, dicens: Vidi Absalom pendere de quercu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Et ait Joab viro qui nuntiaverat ei: Si vidisti, quare non confodisti eum cum terra, et ego dedissem tibi decem argenti siclos, et unum balteum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Qui dixit ad Joab: Si appenderes in manibus meis mille argenteos, nequaquam mitterem manum meam in filium regis: audientibus enim nobis præcepit rex tibi, et Abisai, et Ethai, dicens: Custodite mihi puerum Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Sed etsi fecissem contra animam meam audacter, nequaquam hoc regem latere potuisset, et tu stares ex adverso?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Et ait Joab: Non sicut tu vis, sed aggrediar eum coram te. Tulit ergo tres lanceas in manu sua, et infixit eas in corde Absalom: cumque adhuc palpitaret hærens in quercu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'cucurrerunt decem juvenes armigeri Joab, et percutientes interfecerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Cecinit autem Joab buccina, et retinuit populum, ne persequeretur fugientem Israël, volens parcere multitudini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Et tulerunt Absalom, et projecerunt eum in saltu, in foveam grandem, et comportaverunt super eum acervum lapidum magnum nimis: omnis autem Israël fugit in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Porro Absalom erexerat sibi, cum adhuc viveret, titulum qui est in Valle regis: dixerat enim: Non habeo filium, et hoc erit monimentum nominis mei. Vocavitque titulum nomine suo, et appellatur Manus Absalom, usque ad hanc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Achimaas autem filius Sadoc, ait: Curram, et nuntiabo regi quia judicium fecerit ei Dominus de manu inimicorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Ad quem Joab dixit: Non eris nuntius in hac die, sed nuntiabis in alia: hodie nolo te nuntiare: filius enim regis est mortuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Et ait Joab Chusi: Vade, et nuntia regi quæ vidisti. Adoravit Chusi Joab, et cucurrit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Rursus autem Achimaas filius Sadoc dixit ad Joab: Quid impedit si etiam ego curram post Chusi? Dixitque ei Joab: Quid vis currere, fili mi? non eris boni nuntii bajulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Qui respondit: Quid enim si cucurrero? Et ait ei: Curre. Currens ergo Achimaas per viam compendii, transivit Chusi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David autem sedebat inter duas portas: speculator vero, qui erat in fastigio portæ super murum, elevans oculos, vidit hominem currentem solum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Et exclamans indicavit regi: dixitque rex: Si solus est, bonus est nuntius in ore ejus. Properante autem illo, et accedente propius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'vidit speculator hominem alterum currentem, et vociferans in culmine, ait: Apparet mihi alter homo currens solus. Dixitque rex: Et iste bonus est nuntius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Speculator autem: Contemplor, ait, cursum prioris, quasi cursum Achimaas filii Sadoc. Et ait rex: Vir bonus est, et nuntium portans bonum venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Clamans autem Achimaas, dixit ad regem: Salve rex. Et adorans regem coram eo pronus in terram, ait: Benedictus Dominus Deus tuus, qui conclusit homines qui levaverunt manus suas contra dominum meum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Et ait rex: Estne pax puero Absalom? Dixitque Achimaas: Vidi tumultum magnum cum mitteret Joab servus tuus, o rex, me servum tuum: nescio aliud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Ad quem rex: Transi, ait, et sta hic. Cumque ille transisset, et staret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'apparuit Chusi: et veniens ait: Bonum apporto nuntium, domine mi rex: judicavit enim pro te Dominus hodie de manu omnium qui surrexerunt contra te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Dixit autem rex ad Chusi: Estne pax puero Absalom? Cui respondens Chusi: Fiant, inquit, sicut puer, inimici domini mei regis, et universi qui consurgunt adversus eum in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Contristatus itaque rex, ascendit cœnaculum portæ, et flevit. Et sic loquebatur, vadens: Fili mi Absalom, Absalom fili mi: quis mihi tribuat ut ego moriar pro te, Absalom fili mi, fili mi Absalom?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Nuntiatum est autem Joab quod rex fleret et lugeret filium suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'et versa est victoria in luctum in die illa omni populo: audivit enim populus in die illa dici: Dolet rex super filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Et declinavit populus in die illa ingredi civitatem, quomodo declinare solet populus versus et fugiens de prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Porro rex operuit caput suum, et clamabat voce magna: Fili mi Absalom, Absalom fili mi, fili mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Ingressus ergo Joab ad regem in domum, dixit: Confudisti hodie vultus omnium servorum tuorum, qui salvam fecerunt animam tuam, et animam filiorum tuorum et filiarum tuarum, et animam uxorum tuarum, et animam concubinarum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Diligis odientes te, et odio habes diligentes te: et ostendisti hodie quia non curas de ducibus tuis et de servis tuis: et vere cognovi modo, quia si Absalom viveret, et omnes nos occubuissemus, tunc placeret tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Nunc igitur surge, et procede, et alloquens satisfac servis tuis: juro enim tibi per Dominum quod si non exieris, ne unus quidem remansurus sit tecum nocte hac: et pejus erit hoc tibi quam omnia mala quæ venerunt super te ab adolescentia tua usque in præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Surrexit ergo rex et sedit in porta: et omni populo nuntiatum est quod rex sederet in porta. Venitque universa multitudo coram rege: Israël autem fugit in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Omnis quoque populus certabat in cunctis tribubus Israël, dicens: Rex liberavit nos de manu inimicorum nostrorum; ipse salvavit nos de manu Philisthinorum: et nunc fugit de terra propter Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absalom autem, quem unximus super nos, mortuus est in bello: usquequo siletis, et non reducitis regem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Rex vero David misit ad Sadoc et Abiathar sacerdotes, dicens: Loquimini ad majores natu Juda, dicentes: Cur venitis novissimi ad reducendum regem in domum suam? (Sermo autem omnis Israël pervenerat ad regem in domo ejus.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Fratres mei vos, os meum, et caro mea vos, quare novissimi reducitis regem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Et Amasæ dicite: Nonne os meum, et caro mea es? hæc faciat mihi Deus, et hæc addat, si non magister militiæ fueris coram me omni tempore pro Joab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Et inclinavit cor omnium virorum Juda quasi viri unius: miseruntque ad regem, dicentes: Revertere tu, et omnes servi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Et reversus est rex, et venit usque ad Jordanem: et omnis Juda venit usque in Galgalam ut occurreret regi, et traduceret eum Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Festinavit autem Semei filius Gera filii Jemini de Bahurim, et descendit cum viris Juda in occursum regis David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'cum mille viris de Benjamin, et Siba puer de domo Saul: et quindecim filii ejus, ac viginti servi erant cum eo: et irrumpentes Jordanem, ante regem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'transierunt vada, ut traducerent domum regis, et facerent juxta jussionem ejus: Semei autem filius Gera prostratus coram rege, cum jam transisset Jordanem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'dixit ad eum: Ne reputes mihi, domine mi, iniquitatem, neque memineris injuriarum servi tui in die qua egressus es, domine mi rex, de Jerusalem, neque ponas, rex, in corde tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Agnosco enim servus tuus peccatum meum: et idcirco hodie primus veni de omni domo Joseph, descendique in occursum domini mei regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Respondens vero Abisai filius Sarviæ, dixit: Numquid pro his verbis non occidetur Semei, quia maledixit christo Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Et ait David: Quid mihi et vobis, filii Sarviæ? cur efficimini mihi hodie in satan? ergone hodie interficietur vir in Israël? an ignoro hodie me factum regem super Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Et ait rex Semei: Non morieris. Juravitque ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Miphiboseth quoque filius Saul descendit in occursum regis, illotis pedibus et intonsa barba: vestesque suas non laverat a die qua egressus fuerat rex, usque ad diem reversionis ejus in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Cumque Jerusalem occurrisset regi, dixit ei rex: Quare non venisti mecum, Miphiboseth?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Et respondens ait: Domine mi rex, servus meus contempsit me: dixique ei ego famulus tuus ut sterneret mihi asinum, et ascendens abirem cum rege: claudus enim sum servus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Insuper et accusavit me servum tuum ad te dominum meum regem: tu autem, domine mi rex, sicut angelus Dei es: fac quod placitum est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Neque enim fuit domus patris mei, nisi morti obnoxia domino meo regi: tu autem posuisti me servum tuum inter convivas mensæ tuæ: quid ergo habeo justæ querelæ? aut quid possum ultra vociferari ad regem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Ait ergo ei rex: Quid ultra loqueris? fixum est quod locutus sum: tu et Siba dividite possessiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Responditque Miphiboseth regi: Etiam cuncta accipiat, postquam reversus est dominus meus rex pacifice in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Berzellai quoque Galaadites, descendens de Rogelim, traduxit regem Jordanem, paratus etiam ultra fluvium prosequi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Erat autem Berzellai Galaadites senex valde, id est, octogenarius, et ipse præbuit alimenta regi cum moraretur in castris: fuit quippe vir dives nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Dixit itaque rex ad Berzellai: Veni mecum, ut requiescas securus mecum in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Et ait Berzellai ad regem: Quot sunt dies annorum vitæ meæ, ut ascendam cum rege in Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Octogenarius sum hodie: numquid vigent sensus mei ad discernendum suave aut amarum? aut delectare potest servum tuum cibus et potus? vel audire possum ultra vocem cantorum atque cantatricum? quare servus tuus sit oneri domino meo regi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Paululum procedam famulus tuus ab Jordane tecum: non indigeo hac vicissitudine,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'sed obsecro ut revertar servus tuus, et moriar in civitate mea, et sepeliar juxta sepulchrum patris mei et matris meæ. Est autem servus tuus Chamaam: ipse vadat tecum, domine mi rex, et fac ei quidquid tibi bonum videtur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Dixit itaque ei rex: Mecum transeat Chamaam, et ego faciam ei quidquid tibi placuerit: et omne quod petieris a me, impetrabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Cumque transisset universus populus et rex Jordanem, osculatus est rex Berzellai, et benedixit ei: et ille reversus est in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Transivit ergo rex in Galgalam, et Chamaam cum eo. Omnis autem populus Juda traduxerat regem, et media tantum pars adfuerat de populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Itaque omnes viri Israël concurrentes ad regem dixerunt ei: Quare te furati sunt fratres nostri viri Juda, et traduxerunt regem et domum ejus Jordanem, omnesque viros David cum eo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Et respondit omnis vir Juda ad viros Israël: Quia mihi propior est rex: cur irasceris super hac re? numquid comedimus aliquid ex rege, aut munera nobis data sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Et respondit vir Israël ad viros Juda, et ait: Decem partibus major ego sum apud regem, magisque ad me pertinet David quam ad te: cur fecisti mihi injuriam, et non mihi nuntiatum est priori, ut reducerem regem meum? Durius autem responderunt viri Juda viris Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Accidit quoque ut ibi esset vir Belial, nomine Seba, filius Bochri, vir Jemineus: et cecinit buccina, et ait: Non est nobis pars in David, neque hæreditas in filio Isai: revertere in tabernacula tua, Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Et separatus est omnis Israël a David, secutusque est Seba filium Bochri: viri autem Juda adhæserunt regi suo a Jordane usque Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Cumque venisset rex in domum suam in Jerusalem, tulit decem mulieres concubinas quas dereliquerat ad custodiendam domum, et tradidit eas in custodiam, alimenta eis præbens: et non est ingressus ad eas, sed erant clausæ usque in diem mortis suæ in viduitate viventes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Dixit autem rex Amasæ: Convoca mihi omnes viros Juda in diem tertium, et tu adesto præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Abiit ergo Amasa ut convocaret Judam, et moratus est extra placitum quod ei constituerat rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Ait autem David ad Abisai: Nunc magis afflicturus est nos Seba filius Bochri quam Absalom: tolle igitur servos domini tui, et persequere eum, ne forte inveniat civitates munitas, et effugiat nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Egressi sunt ergo cum eo viri Joab, Cerethi quoque et Phelethi: et omnes robusti exierunt de Jerusalem ad persequendum Seba filium Bochri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Cumque illi essent juxta lapidem grandem qui est in Gabaon, Amasa veniens occurrit eis. Porro Joab vestitus erat tunica stricta ad mensuram habitus sui, et desuper accinctus gladio dependente usque ad ilia, in vagina, qui fabricatus levi motu egredi poterat, et percutere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Dixit itaque Joab ad Amasam: Salve mi frater. Et tenuit manu dextera mentum Amasæ, quasi osculans eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Porro Amasa non observavit gladium quem habebat Joab: qui percussit eum in latere, et effudit intestina ejus in terram, nec secundum vulnus apposuit: et mortuus est. Joab autem, et Abisai frater ejus, persecuti sunt Seba filium Bochri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Interea quidam viri, cum stetissent juxta cadaver Amasæ, de sociis Joab, dixerunt: Ecce qui esse voluit pro Joab comes David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa autem conspersus sanguine jacebat in media via. Vidit hoc quidam vir, quod subsisteret omnis populus ad videndum eum, et amovit Amasam de via in agrum, operuitque eum vestimento, ne subsisterent transeuntes propter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Amoto ergo illo de via, transibat omnis vir sequens Joab ad persequendum Seba filium Bochri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Porro ille transierat per omnes tribus Israël in Abelam et Bethmaacha: omnesque viri electi congregati fuerant ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Venerunt itaque, et oppugnabant eum in Abela et in Bethmaacha, et circumdederunt munitionibus civitatem, et obsessa est urbs: omnis autem turba quæ erat cum Joab, moliebatur destruere muros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Et exclamavit mulier sapiens de civitate: Audite, audite: dicite Joab: Appropinqua huc, et loquar tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Qui cum accessisset ad eam, ait illi: Tu es Joab? Et ille respondit: Ego. Ad quem sic locuta est: Audi sermones ancillæ tuæ. Qui respondit: Audio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Rursumque illa: Sermo, inquit, dicebatur in veteri proverbio: Qui interrogant, interrogent in Abela: et sic perficiebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Nonne ego sum quæ respondeo veritatem in Israël, et tu quæris subvertere civitatem et evertere matrem in Israël? quare præcipitas hæreditatem Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Respondensque Joab, ait: Absit, absit hoc a me: non præcipito, neque demolior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Non sic se habet res, sed homo de monte Ephraim, Seba filius Bochri cognomine, levavit manum suam contra regem David: tradite illum solum, et recedemus a civitate. Et ait mulier ad Joab: Ecce caput ejus mittetur ad te per murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Ingressa est ergo ad omnem populum, et locuta est eis sapienter: qui abscissum caput Seba filii Bochri projecerunt ad Joab. Et ille cecinit tuba, et recesserunt ab urbe, unusquisque in tabernacula sua: Joab autem reversus est Jerusalem ad regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Fuit ergo Joab super omnem exercitum Israël: Banaias autem filius Jojadæ super Cerethæos et Phelethæos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Aduram vero super tributa: porro Josaphat filius Ahilud, a commentariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Siva autem, scriba: Sadoc vero et Abiathar, sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Ira autem Jairites erat sacerdos David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Facta est quoque fames in diebus David tribus annis jugiter: et consuluit David oraculum Domini. Dixitque Dominus: Propter Saul, et domum ejus sanguinum, quia occidit Gabaonitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Vocatis ergo Gabaonitis rex, dixit ad eos (porro Gabaonitæ non erant de filiis Israël, sed reliquiæ Amorrhæorum: filii quippe Israël juraverant eis, et voluit Saul percutere eos zelo, quasi pro filiis Israël et Juda),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'dixit ergo David ad Gabaonitas: Quid faciam vobis? et quod erit vestri piaculum, ut benedicatis hæreditati Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Dixeruntque ei Gabaonitæ: Non est nobis super argento et auro quæstio, sed contra Saul, et contra domum ejus: neque volumus ut interficiatur homo de Israël. Ad quos rex ait: Quid ergo vultis ut faciam vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Qui dixerunt regi: Virum qui attrivit nos et oppressit inique, ita delere debemus, ut ne unus quidem residuus sit de stirpe ejus in cunctis finibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Dentur nobis septem viri de filiis ejus, ut crucifigamus eos Domino in Gabaa Saul, quondam electi Domini. Et ait rex: Ego dabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Pepercitque rex Miphiboseth filio Jonathæ filii Saul, propter jusjurandum Domini quod fuerat inter David et inter Jonathan filium Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Tulit itaque rex duos filios Respha filiæ Aja quos peperit Sauli, Armoni, et Miphiboseth: et quinque filios Michol filiæ Saul quos genuerat Hadrieli filio Berzellai, qui fuit de Molathi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'et dedit eos in manus Gabaonitarum: qui crucifixerunt eos in monte coram Domino: et ceciderunt hi septem simul occisi in diebus messis primis, incipiente messione hordei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Tollens autem Respha filia Aja cilicium, substravit sibi supra petram ab initio messis, donec stillaret aqua super eos de cælo: et non dimisit aves lacerare eos per diem, neque bestias per noctem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Et nuntiata sunt David quæ fecerat Respha filia Aja, concubina Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Et abiit David, et tulit ossa Saul, et ossa Jonathæ filii ejus, a viris Jabes Galaad, qui furati fuerant ea de platea Bethsan in qua suspenderant eos Philisthiim cum interfecissent Saul in Gelboë:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'et asportavit inde ossa Saul, et ossa Jonathæ filii ejus: et colligentes ossa eorum qui affixi fuerant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'sepelierunt ea cum ossibus Saul et Jonathæ filii ejus in terra Benjamin, in latere, in sepulchro Cis patris ejus: feceruntque omnia quæ præceperat rex, et repropitiatus est Deus terræ post hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Factum est autem rursum prælium Philisthinorum adversum Israël, et descendit David, et servi ejus cum eo, et pugnabant contra Philisthiim. Deficiente autem David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jesbibenob, qui fuit de genere Arapha, cujus ferrum hastæ trecentas uncias appendebat, et accinctus erat ense novo, nisus est percutere David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Præsidioque ei fuit Abisai filius Sarviæ, et percussum Philisthæum interfecit. Tunc juraverunt viri David, dicentes: Jam non egredieris nobiscum in bellum, ne extinguas lucernam Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Secundum quoque bellum fuit in Gob contra Philisthæos: tunc percussit Sobochai de Husati, Saph de stirpe Arapha de genere gigantum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Tertium quoque fuit bellum in Gob contra Philisthæos, in quo percussit Adeodatus filius Saltus polymitarius Bethlehemites Goliath Gethæum, cujus hastile hastæ erat quasi liciatorium texentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Quartum bellum fuit in Geth: in quo vir fuit excelsus, qui senos in manibus pedibusque habebat digitos, id est, viginti quatuor: et erat de origine Arapha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Et blasphemavit Israël: percussit autem eum Jonathan filius Samaa fratris David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Hi quatuor nati sunt de Arapha in Geth, et ceciderunt in manu David et servorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Locutus est autem David Domino verba carminis hujus in die qua liberavit eum Dominus de manu omnium inimicorum suorum, et de manu Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Et ait: Dominus petra mea, et robur meum, et salvator meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Deus fortis meus: sperabo in eum; scutum meum, et cornu salutis meæ: elevator meus, et refugium meum; salvator meus: de iniquitate liberabis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Laudabilem invocabo Dominum, et ab inimicis meis salvus ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Quia circumdederunt me contritiones mortis: torrentes Belial terruerunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Funes inferni circumdederunt me: prævenerunt me laquei mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'In tribulatione mea invocabo Dominum, et ad Deum meum clamabo: et exaudiet de templo suo vocem meam, et clamor meus veniet ad aures ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Commota est et contremuit terra; fundamenta montium concussa sunt, et conquassata: quoniam iratus est eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Ascendit fumus de naribus ejus, et ignis de ore ejus vorabit: carbones succensi sunt ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Inclinavit cælos, et descendit: et caligo sub pedibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Et ascendit super cherubim, et volavit: et lapsus est super pennas venti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Posuit tenebras in circuitu suo latibulum, cribrans aquas de nubibus cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Præ fulgore in conspectu ejus, succensi sunt carbones ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Tonabit de cælo Dominus, et excelsus dabit vocem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Misit sagittas et dissipavit eos; fulgur, et consumpsit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Et apparuerunt effusiones maris, et revelata sunt fundamenta orbis ab increpatione Domini, ab inspiratione spiritus furoris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Misit de excelso, et assumpsit me, et extraxit me de aquis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Liberavit me ab inimico meo potentissimo, et ab his qui oderant me: quoniam robustiores me erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Prævenit me in die afflictionis meæ, et factus est Dominus firmamentum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Et eduxit me in latitudinem: liberavit me, quia complacui ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Retribuet mihi Dominus secundum justitiam meam: et secundum munditiam manuum mearum reddet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Quia custodivi vias Domini, et non egi impie a Deo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Omnia enim judicia ejus in conspectu meo, et præcepta ejus non amovi a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Et ero perfectus cum eo, et custodiam me ab iniquitate mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Et restituet mihi Dominus secundum justitiam meam, et secundum munditiam manuum mearum in conspectu oculorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Cum sancto sanctus eris, et cum robusto perfectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Cum electo electus eris, et cum perverso perverteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Et populum pauperem salvum facies: oculisque tuis excelsos humiliabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Quia tu lucerna mea, Domine, et tu, Domine, illuminabis tenebras meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'In te enim curram accinctus: in Deo meo transiliam murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Deus, immaculata via ejus; eloquium Domini igne examinatum: scutum est omnium sperantium in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Quis est Deus præter Dominum, et quis fortis præter Deum nostrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Deus qui accinxit me fortitudine, et complanavit perfectam viam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Coæquans pedes meos cervis, et super excelsa mea statuens me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'docens manus meas ad prælium, et componens quasi arcum æreum brachia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Dedisti mihi clypeum salutis tuæ, et mansuetudo tua multiplicavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Dilatabis gressus meos subtus me, et non deficient tali mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Persequar inimicos meos, et conteram, et non convertar donec consumam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Consumam eos et confringam, ut non consurgant: cadent sub pedibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Accinxisti me fortitudine ad prælium: incurvasti resistentes mihi subtus me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Inimicos meos dedisti mihi dorsum; odientes me, et disperdam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Clamabunt, et non erit qui salvet; ad Dominum, et non exaudiet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Delebo eos ut pulverem terræ; quasi lutum platearum comminuam eos atque confringam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Salvabis me a contradictionibus populi mei; custodies me in caput gentium: populus quem ignoro serviet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Filii alieni resistent mihi; auditu auris obedient mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Filii alieni defluxerunt, et contrahentur in angustiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Vivit Dominus, et benedictus Deus meus, et exaltabitur Deus fortis salutis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Deus qui das vindictas mihi, et dejicis populos sub me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Qui educis me ab inimicis meis, et a resistentibus mihi elevas me: a viro iniquo liberabis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Propterea confitebor tibi, Domine, in gentibus, et nomini tuo cantabo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'magnificans salutes regis sui, et faciens misericordiam christo suo David, et semini ejus in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Hæc autem sunt verba David novissima. Dixit David filius Isai: Dixit vir, cui constitutum est de christo Dei Jacob, egregius psaltes Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Spiritus Domini locutus est per me, et sermo ejus per linguam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Dixit Deus Israël mihi, locutus est fortis Israël: Dominator hominum, justus dominator in timore Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'sicut lux auroræ, oriente sole, mane absque nubibus rutilat: et sicut pluviis germinat herba de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Nec tanta est domus mea apud Deum, ut pactum æternum iniret mecum, firmum in omnibus atque munitum. Cuncta enim salus mea, et omnis voluntas, nec est quidquam ex ea quod non germinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Prævaricatores autem quasi spinæ evellentur universi, quæ non tolluntur manibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Et si quis tangere voluerit eas, armabitur ferro et ligno lanceato, igneque succensæ comburentur usque ad nihilum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Hæc nomina fortium David. Sedens in cathedra sapientissimus princeps inter tres, ipse est quasi tenerrimus ligni vermiculus, qui octingentos interfecit impetu uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Post hunc, Eleazar filius patrui ejus Ahohites inter tres fortes, qui erant cum David quando exprobraverunt Philisthiim, et congregati sunt illuc in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Cumque ascendissent viri Israël, ipse stetit et percussit Philisthæos donec deficeret manus ejus, et obrigesceret cum gladio: fecitque Dominus salutem magnam in die illa: et populus qui fugerat, reversus est ad cæsorum spolia detrahenda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Et post hunc, Semma filius Age de Arari. Et congregati sunt Philisthiim in statione: erat quippe ibi ager lente plenus. Cumque fugisset populus a facie Philisthiim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'stetit ille in medio agri, et tuitus est eum, percussitque Philisthæos: et fecit Dominus salutem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Necnon et ante descenderant tres qui erant principes inter triginta, et venerant tempore messis ad David in speluncam Odollam: castra autem Philisthinorum erant posita in Valle gigantum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Et David erat in præsidio: porro statio Philisthinorum tunc erat in Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Desideravit ergo David, et ait: O si quis mihi daret potum aquæ de cisterna quæ est in Bethlehem juxta portam!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Irruperunt ergo tres fortes castra Philisthinorum, et hauserunt aquam de cisterna Bethlehem, quæ erat juxta portam, et attulerunt ad David: at ille noluit bibere, sed libavit eam Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'dicens: Propitius sit mihi Dominus, ne faciam hoc: num sanguinem hominum istorum qui profecti sunt, et animarum periculum bibam? Noluit ergo bibere. Hæc fecerunt tres robustissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai quoque frater Joab filius Sarviæ, princeps erat de tribus: ipse est qui levavit hastam suam contra trecentos, quos interfecit: nominatus in tribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'et inter tres nobilior, eratque eorum princeps, sed usque ad tres primos non pervenerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Et Banaias filius Jojadæ viri fortissimi, magnorum operum, de Cabseel. Ipse percussit duos leones Moab, et ipse descendit, et percussit leonem in media cisterna in diebus nivis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ipse quoque interfecit virum ægyptium, virum dignum spectaculo, habentem in manu hastam: itaque cum descendisset ad eum in virga, vi extorsit hastam de manu \'gyptii, et interfecit eum hasta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Hæc fecit Banaias filius Jojadæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Et ipse nominatus inter tres robustos, qui erant inter triginta nobiliores: verumtamen usque ad tres non pervenerat: fecitque eum sibi David auricularium, a secreto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asaël frater Joab inter triginta, Elehanan filius patrui ejus de Bethlehem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Semma de Harodi, Elica de Harodi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles de Phalti, Hira filius Acces de Thecua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer de Anathoth, Mobonnai de Husati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Selmon Ahohites, Maharai Netophathites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heled filius Baana, et ipse Netophathites, Ithai filius Ribai de Gabaath filiorum Benjamin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Banaia Pharathonites, Heddai de torrente Gaas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon Arbathites, Azmaveth de Beromi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliaba de Salaboni. Filii Jassen, Jonathan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Semma de Orori, Ajam filius Sarar Arorites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet filius Aasbai filii Machati, Eliam filius Achitophel Gelonites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hesrai de Carmelo, Pharai de Arbi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igaal filius Nathan de Soba, Bonni de Gadi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Selec de Ammoni, Naharai Berothites armiger Joab filii Sarviæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira Jethrites, Gareb et ipse Jethrites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urias Hethæus: omnes triginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Et addidit furor Domini irasci contra Israël, commovitque David in eis dicentem: Vade, numera Israël et Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Dixitque rex ad Joab principem exercitus sui: Perambula omnes tribus Israël a Dan usque Bersabee, et numerate populum, ut sciam numerum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Dixitque Joab regi: Adaugeat Dominus Deus tuus ad populum tuum, quantus nunc est, iterumque centuplicet in conspectu domini mei regis: sed quid sibi dominus meus rex vult in re hujuscemodi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Obtinuit autem sermo regis verba Joab et principum exercitus: egressusque est Joab et princeps militum a facie regis, ut numerarent populum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Cumque pertransissent Jordanem, venerunt in Aroër ad dexteram urbis, quæ est in valle Gad:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'et per Jazer transierunt in Galaad, et in terram inferiorem Hodsi, et venerunt in Dan silvestria. Circumeuntesque juxta Sidonem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'transierunt prope mœnia Tyri, et omnem terram Hevæi et Chananæi, veneruntque ad meridiem Juda in Bersabee:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'et lustrata universa terra, affuerunt post novem menses et viginti dies in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Dedit ergo Joab numerum descriptionis populi regi, et inventa sunt de Israël octingenta millia virorum fortium qui educerent gladium, et de Juda quingenta millia pugnatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Percussit autem cor David eum, postquam numeratus est populus: et dixit David ad Dominum: Peccavi valde in hoc facto: sed precor, Domine, ut transferas iniquitatem servi tui, quia stulte egi nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Surrexit itaque David mane, et sermo Domini factus est ad Gad prophetam et videntem David, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Vade, et loquere ad David: Hæc dicit Dominus: Trium tibi datur optio: elige unum quod volueris ex his, ut faciam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Cumque venisset Gad ad David, nuntiavit ei, dicens: Aut septem annis veniet tibi fames in terra tua: aut tribus mensibus fugies adversarios tuos, et ille te persequentur: aut certe tribus diebus erit pestilentia in terra tua. Nunc ergo delibera, et vide quem respondeam ei qui me misit sermonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Dixit autem David ad Gad: Coarctor nimis: sed melius est ut incidam in manus Domini (multæ enim misericordiæ ejus sunt) quam in manus hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Immisitque Dominus pestilentiam in Israël, de mane usque ad tempus constitutum, et mortui sunt ex populo a Dan usque ad Bersabee septuaginta millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Cumque extendisset manum suam angelus Domini super Jerusalem ut disperderet eam, misertus est Dominus super afflictione, et ait angelo percutienti populum: Sufficit: nunc contine manum tuam. Erat autem angelus Domini juxta aream Areuna Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Dixitque David ad Dominum cum vidisset angelum cædentem populum: Ego sum qui peccavi, ego inique egi: isti qui oves sunt, quid fecerunt? vertatur, obsecro, manus tua contra me, et contra domum patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Venit autem Gad ad David in die illa, et dixit ei: Ascende, et constitue altare Domino in area Areuna Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Et ascendit David juxta sermonem Gad, quem præceperat ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Conspiciensque Areuna, animadvertit regem et servos ejus transire ad se:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'et egressus adoravit regem prono vultu in terram, et ait: Quid causæ est ut veniat dominus meus rex ad servum suum? Cui David ait: Ut emam a te aream, et ædificem altare Domino, et cesset interfectio quæ grassatur in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Et ait Areuna ad David: Accipiat, et offerat dominus meus rex sicut placet ei: habes boves in holocaustum, et plaustrum, et juga boum in usum lignorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Omnia dedit Areuna rex regi: dixitque Areuna ad regem: Dominus Deus tuus suscipiat votum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Cui respondens rex, ait: Nequaquam ut vis, sed emam pretio a te, et non offeram Domino Deo meo holocausta gratuita. Emit ergo David aream, et boves, argenti siclis quinquaginta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'et ædificavit ibi David altare Domino, et obtulit holocausta et pacifica: et propitiatus est Dominus terræ, et cohibita est plaga ab Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Et rex David senuerat, habebatque ætatis plurimos dies: cumque operiretur vestibus, non calefiebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Dixerunt ergo ei servi sui: Quæramus domino nostro regi adolescentulam virginem, et stet coram rege, et foveat eum, dormiatque in sinu suo, et calefaciat dominum nostrum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Quæsierunt igitur adolescentulam speciosam in omnibus finibus Israël, et invenerunt Abisag Sunamitidem, et adduxerunt eam ad regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Erat autem puella pulchra nimis, dormiebatque cum rege, et ministrabat ei: rex vero non cognovit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adonias autem filius Haggith elevabatur, dicens: Ego regnabo. Fecitque sibi currus et equites, et quinquaginta viros qui currerent ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Nec corripuit eum pater suus aliquando, dicens: Quare hoc fecisti? Erat autem et ipse pulcher valde, secundus natu post Absalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Et sermo ei cum Joab filio Sarviæ, et cum Abiathar sacerdote, qui adjuvabant partes Adoniæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Sadoc vero sacerdos, et Banaias filius Jojadæ, et Nathan propheta, et Semei et Rei, et robur exercitus David, non erat cum Adonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Immolatis ergo Adonias arietibus et vitulis, et universis pinguibus, juxta lapidem Zoheleth, qui erat vicinus fonti Rogel, vocavit universos fratres suos filios regis, et omnes viros Juda servos regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Nathan autem prophetam, et Banaiam, et robustos quosque, et Salomonem fratrem suum non vocavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Dixit itaque Nathan ad Bethsabee matrem Salomonis: Num audisti quod regnaverit Adonias filius Haggith, et dominus noster David hoc ignorat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Nunc ergo veni, accipe consilium a me, et salva animam tuam, filiique tui Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Vade, et ingredere ad regem David, et dic ei: Nonne tu, domine mi rex, jurasti mihi ancillæ tuæ, dicens: Salomon filius tuus regnabit post me, et ipse sedebit in solio meo? quare ergo regnat Adonias?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Et adhuc ibi te loquente cum rege, ego veniam post te, et complebo sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Ingressa est itaque Bethsabee ad regem in cubiculum: rex autem senuerat nimis, et Abisag Sunamitis ministrabat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Inclinavit se Bethsabee, et adoravit regem. Ad quam rex: Quid tibi, inquit, vis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Quæ respondens, ait: Domine mi, tu jurasti per Dominum Deum tuum ancillæ tuæ: Salomon filius tuus regnabit post me, et ipse sedebit in solio meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Et ecce nunc Adonias regnat, te, domine mi rex, ignorante.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Mactavit boves, et pinguia quæque, et arietes plurimos, et vocavit omnes filios regis, Abiathar quoque sacerdotem, et Joab principem militiæ: Salomonem autem servum tuum non vocavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Verumtamen, domine mi rex, in te oculi respiciunt totius Israël, ut indices eis quis sedere debeat in solio tuo, domine mi rex, post te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Eritque, cum dormierit dominus meus rex cum patribus suis, erimus ego et filius meus Salomon peccatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Adhuc illa loquente cum rege, Nathan propheta venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Et nuntiaverunt regi, dicentes: Adest Nathan propheta. Cumque introisset in conspectu regis, et adorasset eum pronus in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'dixit Nathan: Domine mi rex, tu dixisti: Adonias regnet post me, et ipse sedeat super thronum meum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Quia descendit hodie, et immolavit boves, et pinguia, et arietes plurimos, et vocavit universos filios regis et principes exercitus, Abiathar quoque sacerdotem, illisque vescentibus et bibentibus coram eo, et dicentibus: Vivat rex Adonias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'me servum tuum, et Sadoc sacerdotem, et Banaiam filium Jojadæ, et Salomonem famulum tuum non vocavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Numquid a domino meo rege exivit hoc verbum, et mihi non indicasti servo tuo quis sessurus esset super thronum domini mei regis post eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Et respondit rex David, dicens: Vocate ad me Bethsabee. Quæ cum fuisset ingressa coram rege, et stetisset ante eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'juravit rex, et ait: Vivit Dominus, qui eruit animam meam de omni angustia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'quia sicut juravi tibi per Dominum Deum Israël, dicens: Salomon filius tuus regnabit post me, et ipse sedebit super solium meum pro me: sic faciam hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Summissoque Bethsabee in terram vultu, adoravit regem, dicens: Vivat dominus meus David in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Dixit quoque rex David: Vocate mihi Sadoc sacerdotem, et Nathan prophetam, et Banaiam filium Jojadæ. Qui cum ingressi fuissent coram rege,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'dixit ad eos: Tollite vobiscum servos domini vestri, et imponite Salomonem filium meum super mulam meam, et ducite eum in Gihon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Et ungat eum ibi Sadoc sacerdos et Nathan propheta in regem super Israël: et canetis buccina, atque dicetis: Vivat rex Salomon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Et ascendetis post eum, et veniet, et sedebit super solium meum, et ipse regnabit pro me: illique præcipiam ut sit dux super Israël et super Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Et respondit Banaias filius Jojadæ regi, dicens: Amen: sic loquatur Dominus Deus domini mei regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Quomodo fuit Dominus cum domino meo rege, sic sit cum Salomone, et sublimius faciat solium ejus a solio domini mei regis David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Descendit ergo Sadoc sacerdos, et Nathan propheta, et Banaias filius Jojadæ, et Cerethi, et Phelethi: et imposuerunt Salomonem super mulam regis David, et adduxerunt eum in Gihon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Sumpsitque Sadoc sacerdos cornu olei de tabernaculo, et unxit Salomonem: et cecinerunt buccina, et dixit omnis populus: Vivat rex Salomon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Et ascendit universa multitudo post eum, et populus canentium tibiis, et lætantium gaudio magno: et insonuit terra a clamore eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Audivit autem Adonias, et omnes qui invitati fuerant ab eo: jamque convivium finitum erat: sed et Joab, audita voce tubæ, ait: Quid sibi vult clamor civitatis tumultuantis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Adhuc illo loquente, Jonathas filius Abiathar sacerdotis venit: cui dixit Adonias: Ingredere, quia vir fortis es, et bona nuntians.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Responditque Jonathas Adoniæ: Nequaquam: dominus enim noster rex David regem constituit Salomonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'misitque cum eo Sadoc sacerdotem, et Nathan prophetam, et Banaiam filium Jojadæ, et Cerethi, et Phelethi, et imposuerunt eum super mulam regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Unxeruntque eum Sadoc sacerdos et Nathan propheta regem in Gihon: et ascenderunt inde lætantes, et insonuit civitas: hæc est vox quam audistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Sed et Salomon sedet super solium regni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Et ingressi servi regis benedixerunt domino nostro regi David, dicentes: Amplificet Deus nomen Salomonis super nomen tuum, et magnificet thronus ejus super thronum tuum. Et adoravit rex in lectulo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'et locutus est: Benedictus Dominus Deus Israël, qui dedit hodie sedentem in solio meo, videntibus oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Territi sunt ergo, et surrexerunt omnes qui invitati fuerant ab Adonia, et ivit unusquisque in viam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonias autem timens Salomonem, surrexit, et abiit, tenuitque cornu altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Et nuntiaverunt Salomoni, dicentes: Ecce Adonias timens regem Salomonem, tenuit cornu altaris, dicens: Juret mihi rex Salomon hodie, quod non interficiat servum suum gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Dixitque Salomon: Si fuerit vir bonus, non cadet ne unus quidem capillus ejus in terram: sin autem malum inventum fuerit in eo, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Misit ergo rex Salomon, et eduxit eum ab altari: et ingressus adoravit regem Salomonem: dixitque ei Salomon: Vade in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Appropinquaverunt autem dies David ut moreretur: præcepitque Salomoni filio suo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Ego ingredior viam universæ terræ: confortare, et esto vir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Et observa custodias Domini Dei tui, ut ambules in viis ejus: ut custodias cæremonias ejus, et præcepta ejus, et judicia, et testimonia, sicut scriptum est in lege Moysi: ut intelligas universa quæ facis, et quocumque te verteris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'ut confirmet Dominus sermones suos quos locutus est de me, dicens: Si custodierint filii tui vias suas, et ambulaverint coram me in veritate, in omni corde suo et in omni anima sua, non auferetur tibi vir de solio Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Tu quoque nosti quæ fecerit mihi Joab filius Sarviæ, quæ fecerit duobus principibus exercitus Israël, Abner filio Ner, et Amasæ filio Jether: quos occidit, et effudit sanguinem belli in pace, et posuit cruorem prælii in balteo suo qui erat circa lumbos ejus, et in calceamento suo quod erat in pedibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Facies ergo juxta sapientiam tuam, et non deduces canitiem ejus pacifice ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Sed et filiis Berzellai Galaaditis reddes gratiam, eruntque comedentes in mensa tua: occurrerunt enim mihi quando fugiebam a facie Absalom fratris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Habes quoque apud te Semei filium Gera filii Jemini de Bahurim, qui maledixit mihi maledictione pessima quando ibam ad castra: sed quia descendit mihi in occursum cum transirem Jordanem, et juravi ei per Dominum, dicens: Non te interficiam gladio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'tu noli pati eum esse innoxium. Vir autem sapiens es, ut scias quæ facies ei: deducesque canos ejus cum sanguine ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Dormivit igitur David cum patribus suis, et sepultus est in civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Dies autem quibus regnavit David super Israël, quadraginta anni sunt: in Hebron regnavit septem annis; in Jerusalem, triginta tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Salomon autem sedit super thronum David patris sui, et firmatum est regnum ejus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Et ingressus est Adonias filius Haggith ad Bethsabee matrem Salomonis. Quæ dixit ei: Pacificusne est ingressus tuus? Qui respondit: Pacificus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Addiditque: Sermo mihi est ad te. Cui ait: Loquere. Et ille:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tu, inquit, nosti, quia meum erat regnum, et me præposuerat omnis Israël sibi in regem: sed translatum est regnum, et factum est fratris mei: a Domino enim constitutum est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nunc ergo petitionem unam precor a te: ne confundas faciem meam. Quæ dixit ad eum: Loquere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Et ille ait: Precor ut dicas Salomoni regi (neque enim negare tibi quidquam potest) ut det mihi Abisag Sunamitidem uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Et ait Bethsabee: Bene: ego loquar pro te regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Venit ergo Bethsabee ad regem Salomonem ut loqueretur ei pro Adonia: et surrexit rex in occursum ejus, adoravitque eam, et sedit super thronum suum: positusque est thronus matri regis, quæ sedit ad dexteram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Dixitque ei: Petitionem unam parvulam ego deprecor a te: ne confundas faciem meam. Et dixit ei rex: Pete, mater mea: neque enim fas est ut avertam faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Quæ ait: Detur Abisag Sunamitis Adoniæ fratri tuo uxor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Responditque rex Salomon, et dixit matri suæ: Quare postulas Abisag Sunamitidem Adoniæ? postula ei et regnum: ipse est enim frater meus major me, et habet Abiathar sacerdotem, et Joab filium Sarviæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Juravit itaque rex Salomon per Dominum, dicens: Hæc faciat mihi Deus, et hæc addat, quia contra animam suam locutus est Adonias verbum hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Et nunc vivit Dominus, qui firmavit me, et collocavit me super solium David patris mei, et qui fecit mihi domum, sicut locutus est, quia hodie occidetur Adonias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Misitque rex Salomon per manum Banaiæ filii Jojadæ, qui interfecit eum, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Abiathar quoque sacerdoti dixit rex: Vade in Anathoth ad agrum tuum: equidem vir mortis es: sed hodie te non interficiam, quia portasti arcam Domini Dei coram David patre meo, et sustinuisti laborem in omnibus in quibus laboravit pater meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Ejecit ergo Salomon Abiathar ut non esset sacerdos Domini, ut impleretur sermo Domini quem locutus est super domum Heli in Silo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Venit autem nuntius ad Joab, quod Joab declinasset post Adoniam, et post Salomonem non declinasset: fugit ergo Joab in tabernaculum Domini, et apprehendit cornu altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Nuntiatumque est regi Salomoni quod fugisset Joab in tabernaculum Domini, et esset juxta altare: misitque Salomon Banaiam filium Jojadæ, dicens: Vade, interfice eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Et venit Banaias ad tabernaculum Domini, et dixit ei: Hæc dicit rex: Egredere. Qui ait: Non egrediar, sed hic moriar. Renuntiavit Banaias regi sermonem, dicens: Hæc locutus est Joab, et hæc respondit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Dixitque ei rex: Fac sicut locutus est, et interfice eum, et sepeli: et amovebis sanguinem innocentem qui effusus est a Joab, a me, et a domo patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Et reddet Dominus sanguinem ejus super caput ejus, quia interfecit duos viros justos, melioresque se: et occidit eos gladio, patre meo David ignorante, Abner filium Ner principem militiæ Israël, et Amasam filium Jether principem exercitus Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'et revertetur sanguis illorum in caput Joab, et in caput seminis ejus in sempiternum. David autem et semini ejus, et domui, et throno illius, sit pax usque in æternum a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Ascendit itaque Banaias filius Jojadæ, et aggressus eum interfecit: sepultusque est in domo sua in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Et constituit rex Banaiam filium Jojadæ pro eo super exercitum, et Sadoc sacerdotem posuit pro Abiathar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Misit quoque rex, et vocavit Semei: dixitque ei: \'difica tibi domum in Jerusalem, et habita ibi: et non egredieris inde huc atque illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Quacumque autem die egressus fueris, et transieris torrentem Cedron, scito te interficiendum: sanguis tuus erit super caput tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Dixitque Semei regi: Bonus sermo: sicut locutus est dominus meus rex, sic faciet servus tuus. Habitavit itaque Semei in Jerusalem diebus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Factum est autem post annos tres ut fugerent servi Semei ad Achis filium Maacha regem Geth: nuntiatumque est Semei quod servi ejus issent in Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Et surrexit Semei, et stravit asinum suum, ivitque ad Achis in Geth ad requirendum servos suos, et adduxit eos de Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Nuntiatum est autem Salomoni quod isset Semei in Geth de Jerusalem, et rediisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Et mittens vocavit eum, dixitque illi: Nonne testificatus sum tibi per Dominum, et prædixi tibi: Quacumque die egressus ieris huc et illuc, scito te esse moriturum: et respondisti mihi: Bonus sermo, quem audivi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'quare ergo non custodisti jusjurandum Domini, et præceptum quod præceperam tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Dixitque rex ad Semei: Tu nosti omne malum cujus tibi conscium est cor tuum, quod fecisti David patri meo: reddidit Dominus malitiam tuam in caput tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'et rex Salomon benedictus, et thronus David erit stabilis coram Domino usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Jussit itaque rex Banaiæ filio Jojadæ, qui egressus, percussit eum, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Confirmatum est igitur regnum in manu Salomonis, et affinitate conjunctus est Pharaoni regi \'gypti: accepit namque filiam ejus, et adduxit in civitatem David, donec compleret ædificans domum suam, et domum Domini, et murum Jerusalem per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Attamen populus immolabat in excelsis: non enim ædificatum erat templum nomini Domini usque in diem illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Dilexit autem Salomon Dominum, ambulans in præceptis David patris sui, excepto quod in excelsis immolabat, et accendebat thymiama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Abiit itaque in Gabaon, ut immolaret ibi: illud quippe erat excelsum maximum: mille hostias in holocaustum obtulit Salomon super altare illud in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Apparuit autem Dominus Salomoni per somnium nocte, dicens: Postula quod vis ut dem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Et ait Salomon: Tu fecisti cum servo tuo David patre meo misericordiam magnam, sicut ambulavit in conspectu tuo in veritate et justitia, et recto corde tecum: custodisti ei misericordiam tuam grandem, et dedisti ei filium sedentem super thronum ejus, sicut est hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Et nunc Domine Deus, tu regnare fecisti servum tuum pro David patre meo: ego autem sum puer parvulus, et ignorans egressum et introitum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Et servus tuus in medio est populi quem elegisti, populi infiniti, qui numerari et supputari non potest præ multitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Dabis ergo servo tuo cor docile, ut populum tuum judicare possit, et discernere inter bonum et malum. Quis enim poterit judicare populum istum, populum tuum hunc multum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Placuit ergo sermo coram Domino, quod Salomon postulasset hujuscemodi rem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Et dixit Dominus Salomoni: Quia postulasti verbum hoc, et non petisti tibi dies multos, nec divitias, aut animas inimicorum tuorum, sed postulasti tibi sapientiam ad discernendum judicium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'ecce feci tibi secundum sermones tuos, et dedi tibi cor sapiens et intelligens, in tantum ut nullus ante te similis tui fuerit, nec post te surrecturus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Sed et hæc quæ non postulasti, dedi tibi: divitias scilicet, et gloriam, ut nemo fuerit similis tui in regibus cunctis retro diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Si autem ambulaveris in viis meis, et custodieris præcepta mea et mandata mea, sicut ambulavit pater tuus, longos faciam dies tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Igitur evigilavit Salomon, et intellexit quod esset somnium: cumque venisset Jerusalem, stetit coram arca fœderis Domini, et obtulit holocausta, et fecit victimas pacificas, et grande convivium universis famulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tunc venerunt duæ mulieres meretrices ad regem, steteruntque coram eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'quarum una ait: Obsecro, mi domine: ego et mulier hæc habitabamus in domo una, et peperi apud eam in cubiculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Tertia autem die postquam ego peperi, peperit et hæc: et eramus simul, nullusque alius nobiscum in domo, exceptis nobis duabus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Mortuus est autem filius mulieris hujus nocte: dormiens quippe oppressit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Et consurgens intempestæ noctis silentio, tulit filium meum de latere meo, ancillæ tuæ dormientis, et collocavit in sinu suo: suum autem filium, qui erat mortuus, posuit in sinu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Cumque surrexissem mane ut darem lac filio meo, apparuit mortuus: quem diligentius intuens clara luce, deprehendi non esse meum quem genueram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Responditque altera mulier: Non est ita ut dicis, sed filius tuus mortuus est, meus autem vivit. E contrario illa dicebat: Mentiris: filius quippe meus vivit, et filius tuus mortuus est. Atque in hunc modum contendebant coram rege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Tunc rex ait: Hæc dicit: Filius meus vivit, et filius tuus mortuus est: et ista respondit: Non, sed filius tuus mortuus est, meus autem vivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Dixit ergo rex: Afferte mihi gladium. Cumque attulissent gladium coram rege,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Dividite, inquit, infantem vivum in duas partes, et date dimidiam partem uni, et dimidiam partem alteri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Dixit autem mulier, cujus filius erat vivus, ad regem (commota sunt quippe viscera ejus super filio suo): Obsecro, domine, date illi infantem vivum, et nolite interficere eum. E contrario illa dicebat: Nec mihi nec tibi sit, sed dividatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Respondit rex, et ait: Date huic infantem vivum, et non occidatur: hæc est enim mater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Audivit itaque omnis Israël judicium quod judicasset rex, et timuerunt regem, videntes sapientiam Dei esse in eo ad faciendum judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Erat autem rex Salomon regnans super omnem Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'et hi principes quos habebat: Azarias filius Sadoc sacerdotis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph et Ahia filii Sisa scribæ: Josaphat filius Ahilud a commentariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Banaias filius Jojadæ super exercitum: Sadoc autem et Abiathar sacerdotes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarias filius Nathan super eos qui assistebant regi: Zabud filius Nathan sacerdos, amicus regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'et Ahisar præpositus domus: et Adoniram filius Abda super tributa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Habebat autem Salomon duodecim præfectos super omnem Israël, qui præbebant annonam regi et domui ejus: per singulos enim menses in anno, singuli necessaria ministrabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Et hæc nomina eorum: Benhur in monte Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Bendecar in Macces, et in Salebim, et in Bethsames, et in Elon, et in Bethanan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Benhesed in Aruboth: ipsius erat Socho, et omnis terra Epher.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Benabinadab, cujus omnis Nephath Dor: Tapheth filiam Salomonis habebat uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Bana filius Ahilud regebat Thanac et Mageddo, et universam Bethsan, quæ est juxta Sarthana subter Jezrahel, a Bethsan usque Abelmehula e regione Jecmaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Bengaber in Ramoth Galaad: habebat Avothjair filii Manasse in Galaad: ipse præerat in omni regione Argob, quæ est in Basan, sexaginta civitatibus magnis atque muratis quæ habebant seras æreas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab filius Addo præerat in Manaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas in Nephthali: sed et ipse habebat Basemath filiam Salomonis in conjugio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana filius Husi in Aser, et in Baloth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat filius Pharue in Issachar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Semei filius Ela in Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Gaber filius Uri in terra Galaad, in terra Sehon regis Amorrhæi et Og regis Basan, super omnia quæ erant in illa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda et Israël innumerabiles, sicut arena maris in multitudine: comedentes, et bibentes, atque lætantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Salomon autem erat in ditione sua, habens omnia regna a flumine terræ Philisthiim usque ad terminum \'gypti: offerentium sibi munera, et servientium ei cunctis diebus vitæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Erat autem cibus Salomonis per dies singulos triginta cori similæ, et sexaginta cori farinæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'decem boves pingues, et viginti boves pascuales, et centum arietes, excepta venatione cervorum, caprearum, atque bubalorum, et avium altilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Ipse enim obtinebat omnem regionem quæ erat trans flumen, a Thaphsa usque ad Gazan, et cunctos reges illarum regionum: et habebat pacem ex omni parte in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Habitabatque Juda et Israël absque timore ullo, unusquisque sub vite sua et sub ficu sua, a Dan usque Bersabee, cunctis diebus Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Et habebat Salomon quadraginta millia præsepia equorum currilium, et duodecim millia equestrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Nutriebantque eos supradicti regis præfecti: sed et necessaria mensæ regis Salomonis cum ingenti cura præbebant in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Hordeum quoque, et paleas equorum et jumentorum, deferebant in locum ubi erat rex, juxta constitutum sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Dedit quoque Deus sapientiam Salomoni, et prudentiam multam nimis, et latitudinem cordis quasi arenam quæ est in littore maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Et præcedebat sapientia Salomonis sapientiam omnium Orientalium et \'gyptiorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'et erat sapientior cunctis hominibus: sapientior Ethan Ezrahita, et Heman, et Chalcol, et Dorda filiis Mahol: et erat nominatus in universis gentibus per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Locutus est quoque Salomon tria millia parabolas: et fuerunt carmina ejus quinque et mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Et disputavit super lignis a cedro quæ est in Libano, usque ad hyssopum quæ egreditur de pariete: et disseruit de jumentis, et volucribus, et reptilibus, et piscibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Et veniebant de cunctis populis ad audiendam sapientiam Salomonis, et ab universis regibus terræ qui audiebant sapientiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Misit quoque Hiram rex Tyri servos suos ad Salomonem: audivit enim quod ipsum unxissent regem pro patre ejus: quia amicus fuerat Hiram David omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Misit autem Salomon ad Hiram, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu scis voluntatem David patris mei, et quia non potuerit ædificare domum nomini Domini Dei sui propter bella imminentia per circuitum, donec daret Dominus eos sub vestigio pedum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Nunc autem requiem dedit Dominus Deus meus mihi per circuitum, et non est satan, neque occursus malus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Quam ob rem cogito ædificare templum nomini Domini Dei mei, sicut locutus est Dominus David patri meo, dicens: Filius tuus, quem dabo pro te super solium tuum, ipse ædificabit domum nomini meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Præcipe igitur ut præcidant mihi servi tui cedros de Libano, et servi mei sint cum servis tuis: mercedem autem servorum tuorum dabo tibi quamcumque petieris: scis enim quomodo non est in populo meo vir qui noverit ligna cædere sicut Sidonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Cum ergo audisset Hiram verba Salomonis, lætatus est valde, et ait: Benedictus Dominus Deus hodie, qui dedit David filium sapientissimum super populum hunc plurimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Et misit Hiram ad Salomonem, dicens: Audivi quæcumque mandasti mihi: ego faciam omnem voluntatem tuam in lignis cedrinis et abiegnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Servi mei deponent ea de Libano ad mare, et ego componam ea in ratibus in mari usque ad locum quem significaveris mihi: et applicabo ea ibi, et tu tolles ea: præbebisque necessaria mihi, ut detur cibus domui meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Itaque Hiram dabat Salomoni ligna cedrina, et ligna abiegna, juxta omnem voluntatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomon autem præbebat Hiram coros tritici viginti millia in cibum domui ejus, et viginti coros purissimi olei: hæc tribuebat Salomon Hiram per singulos annos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Dedit quoque Dominus sapientiam Salomoni, sicut locutus est ei: et erat pax inter Hiram et Salomonem, et percusserunt ambo fœdus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Elegitque rex Salomon operarios de omni Israël, et erat indictio triginta millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Mittebatque eos in Libanum, decem millia per menses singulos vicissim, ita ut duobus mensibus essent in domibus suis: et Adoniram erat super hujuscemodi indictione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Fueruntque Salomoni septuaginta millia eorum qui onera portabant, et octoginta millia latomorum in monte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'absque præpositis qui præerant singulis operibus, numero trium millium et trecentorum, præcipientium populo et his qui faciebant opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Præcepitque rex ut tollerent lapides grandes, lapides pretiosos in fundamentum templi, et quadrarent eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'quos dolaverunt cæmentarii Salomonis et cæmentarii Hiram: porro Giblii præparaverunt ligna et lapides ad ædificandam domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Factum est ergo quadringentesimo et octogesimo anno egressionis filiorum Israël de terra \'gypti, in anno quarto, mense Zio (ipse est mensis secundus), regni Salomonis super Israël, ædificari cœpit domus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Domus autem quam ædificabat rex Salomon Domino, habebat sexaginta cubitos in longitudine, et viginti cubitos in latitudine, et triginta cubitos in altitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Et porticus erat ante templum viginti cubitorum longitudinis, juxta mensuram latitudinis templi: et habebat decem cubitos latitudinis ante faciem templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Fecitque in templo fenestras obliquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Et ædificavit super parietem templi tabulata per gyrum, in parietibus domus per circuitum templi et oraculi, et fecit latera in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Tabulatum quod subter erat, quinque cubitos habebat latitudinis, et medium tabulatum sex cubitorum latitudinis, et tertium tabulatum septem habens cubitos latitudinis. Trabes autem posuit in domo per circuitum forinsecus, ut non hærerent muris templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Domus autem cum ædificaretur, de lapidibus dolatis atque perfectis ædificata est: et malleus, et securis, et omne ferramentum non sunt audita in domo cum ædificaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Ostium lateris medii in parte erat domus dextræ: et per cochleam ascendebant in medium cœnaculum, et a medio in tertium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Et ædificavit domum, et consummavit eam: texit quoque domum laquearibus cedrinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Et ædificavit tabulatum super omnem domum quinque cubitis altitudinis, et operuit domum lignis cedrinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Et factus est sermo Domini ad Salomonem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Domus hæc, quam ædificas, si ambulaveris in præceptis meis, et judicia mea feceris, et custodieris omnia mandata mea, gradiens per ea, firmabo sermonem meum tibi, quem locutus sum ad David patrem tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'et habitabo in medio filiorum Israël, et non derelinquam populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Igitur ædificavit Salomon domum, et consummavit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Et ædificavit parietes domus intrinsecus tabulatis cedrinis: a pavimento domus usque ad summitatem parietum, et usque ad laquearia, operuit lignis cedrinis intrinsecus: et texit pavimentum domus tabulis abiegnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, '\'dificavitque viginti cubitorum ad posteriorem partem templi tabulata cedrina, a pavimento usque ad superiora: et fecit interiorem domum oraculi in Sanctum sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Porro quadraginta cubitorum erat ipsum templum pro foribus oraculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Et cedro omnis domus intrinsecus vestiebatur, habens tornaturas et juncturas suas fabrefactas, et cælaturas eminentes: omnia cedrinis tabulis vestiebantur: nec omnino lapis apparere poterat in pariete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Oraculum autem in medio domus, in interiori parte fecerat, ut poneret ibi arcam fœderis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Porro oraculum habebat viginti cubitos longitudinis, et viginti cubitos latitudinis, et viginti cubitos altitudinis: et operuit illud atque vestivit auro purissimo: sed et altare vestivit cedro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Domum quoque ante oraculum operuit auro purissimo, et affixit laminas clavis aureis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Nihilque erat in templo quod non auro tegeretur: sed et totum altare oraculi texit auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Et fecit in oraculo duos cherubim de lignis olivarum, decem cubitorum altitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Quinque cubitorum ala cherub una, et quinque cubitorum ala cherub altera: id est, decem cubitos habentes, a summitate alæ unius usque ad alæ alterius summitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Decem quoque cubitorum erat cherub secundus: in mensura pari, et opus unum erat in duobus cherubim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'id est, altitudinem habebat unus cherub decem cubitorum, et similiter cherub secundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Posuitque cherubim in medio templi interioris: extendebant autem alas suas cherubim, et tangebat ala una parietem, et ala cherub secundi tangebat parietem alterum: alæ autem alteræ in media parte templi se invicem contingebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Texit quoque cherubim auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Et omnes parietes templi per circuitum sculpsit variis cælaturis et torno: et fecit in eis cherubim, et palmas, et picturas varias, quasi prominentes de pariete, et egredientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Sed et pavimentum domus texit auro intrinsecus et extrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Et in ingressu oraculi fecit ostiola de lignis olivarum, postesque angulorum quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Et duo ostia de lignis olivarum: et sculpsit in eis picturam cherubim, et palmarum species, et anaglypha valde prominentia: et texit ea auro, et operuit tam cherubim quam palmas, et cetera, auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Fecitque in introitu templi postes de lignis olivarum quadrangulatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'et duo ostia de lignis abiegnis altrinsecus: et utrumque ostium duplex erat, et se invicem tenens aperiebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Et sculpsit cherubim, et palmas, et cælaturas valde eminentes: operuitque omnia laminis aureis opere quadro ad regulam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Et ædificavit atrium interius tribus ordinibus lapidum politorum, et uno ordine lignorum cedri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Anno quarto fundata est domus Domini in mense Zio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'et in anno undecimo, mense Bul (ipse est mensis octavus), perfecta est domus in omni opere suo, et in universis utensilibus suis: ædificavitque eam annis septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Domum autem suam ædificavit Salomon tredecim annis, et ad perfectum usque perduxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, '\'dificavit quoque domum saltus Libani centum cubitorum longitudinis, et quinquaginta cubitorum latitudinis, et triginta cubitorum altitudinis: et quatuor deambulacra inter columnas cedrinas: ligna quippe cedrina exciderat in columnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Et tabulatis cedrinis vestivit totam cameram, quæ quadraginta quinque columnis sustentabatur. Unus autem ordo habebat columnas quindecim');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'contra se invicem positas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'et e regione se respicientes, æquali spatio inter columnas, et super columnas quadrangulata ligna in cunctis æqualia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Et porticum columnarum fecit quinquaginta cubitorum longitudinis, et triginta cubitorum latitudinis: et alteram porticum in facie majoris porticus: et columnas, et epistylia super columnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Porticum quoque solii, in qua tribunal est, fecit: et texit lignis cedrinis a pavimento usque ad summitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Et domuncula, in qua sedebatur ad judicandum, erat in media porticu simili opere. Domum quoque fecit filiæ Pharaonis (quam uxorem duxerat Salomon) tali opere, quali et hanc porticum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Omnia lapidibus pretiosis, qui ad normam quamdam atque mensuram tam intrinsecus quam extrinsecus serrati erant: a fundamento usque ad summitatem parietum, et extrinsecus usque ad atrium majus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Fundamenta autem de lapidibus pretiosis, lapidibus magnis, decem sive octo cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Et desuper lapides pretiosi æqualis mensuræ secti erant, similiterque de cedro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Et atrium majus rotundum trium ordinum de lapidibus sectis, et unius ordinis de dolata cedro: necnon et in atrio domus Domini interiori, et in porticu domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Misit quoque rex Salomon, et tulit Hiram de Tyro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'filium mulieris viduæ de tribu Nephthali, patre Tyrio, artificem ærarium, et plenum sapientia, et intelligentia, et doctrina, ad faciendum omne opus ex ære. Qui cum venisset ad regem Salomonem, fecit omne opus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Et finxit duas columnas æreas, decem et octo cubitorum altitudinis columnam unam: et linea duodecim cubitorum ambiebat columnam utramque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Duo quoque capitella fecit, quæ ponerentur super capita columnarum, fusilia ex ære: quinque cubitorum altitudinis capitellum unum, et quinque cubitorum altitudinis capitellum alterum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'et quasi in modum retis, et catenarum sibi invicem miro opere contextarum. Utrumque capitellum columnarum fusile erat: septena versuum retiacula in capitello uno, et septena retiacula in capitello altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Et perfecit columnas, et duos ordines per circuitum retiaculorum singulorum, ut tegerent capitella quæ erant super summitatem, malogranatorum: eodem modo fecit et capitello secundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Capitella autem quæ erant super capita columnarum, quasi opere lilii fabricata erant in porticu quatuor cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Et rursum alia capitella in summitate columnarum desuper juxta mensuram columnæ contra retiacula: malogranatorum autem ducenti ordines erant in circuitu capitelli secundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Et statuit duas columnas in porticu templi: cumque statuisset columnam dexteram, vocavit eam nomine Jachin: similiter erexit columnam secundam, et vocavit nomen ejus Booz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Et super capita columnarum opus in modum lilii posuit: perfectumque est opus columnarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Fecit quoque mare fusile decem cubitorum a labio usque ad labium, rotundum in circuitu: quinque cubitorum altitudo ejus, et resticula triginta cubitorum cingebat illud per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Et sculptura subter labium circuibat illud decem cubitis ambiens mare: duo ordines sculpturarum striatarum erant fusiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Et stabat super duodecim boves, e quibus tres respiciebant ad aquilonem, et tres ad occidentem, et tres ad meridiem, et tres ad orientem: et mare super eos desuper erat: quorum posteriora universa intrinsecus latitabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Grossitudo autem luteris, trium unciarum erat: labiumque ejus quasi labium calicis, et folium repandi lilii: duo millia batos capiebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Et fecit decem bases æneas, quatuor cubitorum longitudinis bases singulas, et quatuor cubitorum latitudinis, et trium cubitorum altitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Et ipsum opus basium, interrasile erat: et sculpturæ inter juncturas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Et inter coronulas et plectas, leones et boves et cherubim, et in juncturis similiter desuper: et subter leones et boves, quasi lora ex ære dependentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Et quatuor rotæ per bases singulas, et axes ærei: et per quatuor partes quasi humeruli subter luterem fusiles, contra se invicem respectantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Os quoque luteris intrinsecus erat in capitis summitate: et quod forinsecus apparebat, unius cubiti erat totum rotundum, pariterque habebat unum cubitum et dimidium: in angulis autem columnarum variæ cælaturæ erant: et media intercolumnia, quadrata non rotunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Quatuor quoque rotæ quæ per quatuor angulos basis erant, cohærebant sibi subter basim: una rota habebat altitudinis cubitum et semis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Tales autem rotæ erant quales solent in curru fieri: et axes earum, et radii, et canthi, et modioli, omnia fusilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Nam et humeruli illi quatuor per singulos angulos basis unius, ex ipsa basi fusiles et conjuncti erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'In summitate autem basis erat quædam rotunditas dimidii cubiti, ita fabrefacta ut luter desuper posset imponi, habens cælaturas suas, variasque sculpturas ex semetipsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Sculpsit quoque in tabulatis illis quæ erant ex ære, et in angulis, cherubim, et leones, et palmas, quasi in similitudinem hominis stantis, ut non cælata, sed apposita per circuitum viderentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'In hunc modum fecit decem bases, fusura una, et mensura, sculpturaque consimili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Fecit quoque decem luteres æneos: quadraginta batos capiebat luter unus, eratque quatuor cubitorum: singulos quoque luteres per singulas, id est, decem bases, posuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Et constituit decem bases, quinque ad dexteram partem templi, et quinque ad sinistram: mare autem posuit ad dexteram partem templi contra orientem ad meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Fecit ergo Hiram lebetes, et scutras, et hamulas, et perfecit omne opus regis Salomonis in templo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Columnas duas, et funiculos capitellorum super capitella columnarum duos: et retiacula duo, ut operirent duos funiculos qui erant super capita columnarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Et malogranata quadringenta in duobus retiaculis: duos versus malogranatorum in retiaculis singulis, ad operiendos funiculos capitellorum qui erant super capita columnarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Et bases decem, et luteres decem super bases.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Et mare unum, et boves duodecim subter mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Et lebetes, et scutras, et hamulas, omnia vasa quæ fecit Hiram regi Salomoni in domo Domini, de auricalco erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'In campestri regione Jordanis fudit ea rex in argillosa terra, inter Sochoth et Sarthan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Et posuit Salomon omnia vasa: propter multitudinem autem nimiam non erat pondus æris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Fecitque Salomon omnia vasa in domo Domini: altare aureum, et mensam super quam ponerentur panes propositionis, auream:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'et candelabra aurea, quinque ad dexteram, et quinque ad sinistram contra oraculum, ex auro puro: et quasi lilii flores, et lucernas desuper aureas: et forcipes aureos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'et hydrias, et fuscinulas, et phialas, et mortariola, et thuribula, de auro purissimo: et cardines ostiorum domus interioris Sancti sanctorum, et ostiorum domus templi, ex auro erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Et perfecit omne opus quod faciebat Salomon in domo Domini, et intulit quæ sanctificaverat David pater suus, argentum, et aurum, et vasa, reposuitque in thesauris domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tunc congregati sunt omnes majores natu Israël cum principibus tribuum, et duces familiarum filiorum Israël, ad regem Salomonem in Jerusalem, ut deferrent arcam fœderis Domini de civitate David, id est, de Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Convenitque ad regem Salomonem universus Israël in mense Ethanim, in solemni die: ipse est mensis septimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Veneruntque cuncti senes de Israël, et tulerunt arcam sacerdotes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'et portaverunt arcam Domini, et tabernaculum fœderis, et omnia vasa sanctuarii quæ erant in tabernaculo: et ferebant ea sacerdotes et Levitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Rex autem Salomon, et omnis multitudo Israël quæ convenerat ad eum, gradiebatur cum illo ante arcam, et immolabant oves et boves absque æstimatione et numero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Et intulerunt sacerdotes arcam fœderis Domini in locum suum, in oraculum templi, in Sanctum sanctorum, subter alas cherubim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Siquidem cherubim expandebant alas super locum arcæ, et protegebant arcam, et vectes ejus desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Cumque eminerent vectes, et apparerent summitates eorum foris sanctuarium ante oraculum, non apparebant ultra extrinsecus, qui et fuerunt ibi usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'In arca autem non erat aliud nisi duæ tabulæ lapideæ quas posuerat in ea Moyses in Horeb, quando pepigit Dominus fœdus cum filiis Israël, cum egrederentur de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Factum est autem cum exissent sacerdotes de sanctuario, nebula implevit domum Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'et non poterant sacerdotes stare et ministrare propter nebulam: impleverat enim gloria Domini domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tunc ait Salomon: Dominus dixit ut habitaret in nebula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, '\'dificans ædificavi domum in habitaculum tuum: firmissimum solium tuum in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Convertitque rex faciem suam, et benedixit omni ecclesiæ Israël: omnia enim ecclesia Israël stabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et ait Salomon: Benedictus Dominus Deus Israël, qui locutus est ore suo ad David patrem meum, et in manibus ejus perfecit, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'A die qua eduxi populum meum Israël de \'gypto, non elegi civitatem de universis tribubus Israël, ut ædificaretur domus, et esset nomen meum ibi: sed elegi David ut esset super populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Voluitque David pater meus ædificare domum nomini Domini Dei Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'et ait Dominus ad David patrem meum: Quod cogitasti in corde tuo ædificare domum nomini meo, bene fecisti, hoc ipsum mente tractans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Verumtamen tu non ædificabis mihi domum, sed filius tuus, qui egredietur de renibus tuis, ipse ædificabit domum nomini meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Confirmavit Dominus sermonem suum quem locutus est: stetique pro David patre meo, et sedi super thronum Israël, sicut locutus est Dominus: et ædificavi domum nomini Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Et constitui ibi locum arcæ in qua fœdus Domini est, quod percussit cum patribus nostris quando egressi sunt de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Stetit autem Salomon ante altare Domini in conspectu ecclesiæ Israël, et expandit manus suas in cælum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'et ait: Domine Deus Israël, non est similis tui deus in cælo desuper, et super terram deorsum: qui custodis pactum et misericordiam servis tuis qui ambulant coram te in toto corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Qui custodisti servo tuo David patri meo quæ locutus es ei: ore locutus es, et manibus perfecisti, ut hæc dies probat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nunc igitur Domine Deus Israël, conserva famulo tuo David patri meo quæ locutus es ei, dicens: Non auferetur de te vir coram me, qui sedeat super thronum Israël: ita tamen si custodierint filii tui viam suam, ut ambulent coram me sicut tu ambulasti in conspectu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Et nunc Domine Deus Israël, firmentur verba tua quæ locutus es servo tuo David patri meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Ergone putandum est quod vere Deus habitet super terram? si enim cælum, et cæli cælorum, te capere non possunt, quanto magis domus hæc, quam ædificavi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Sed respice ad orationem servi tui, et ad preces ejus, Domine Deus meus: audi hymnum et orationem quam servus tuus orat coram te hodie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'ut sint oculi tui aperti super domum hanc nocte ac die: super domum, de qua dixisti: Erit nomen meum ibi: ut exaudias orationem quam orat in loco isto ad te servus tuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'ut exaudias deprecationem servi tui et populi tui Israël, quodcumque oraverint in loco isto, et exaudies in loco habitaculi tui in cælo: et cum exaudieris, propitius eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Si peccaverit homo in proximum suum, et habuerit aliquod juramentum quo teneatur astrictus, et venerit propter juramentum coram altari tuo in domum tuam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'tu exaudies in cælo: et facies, et judicabis servos tuos, condemnans impium, et reddens viam suam super caput ejus, justificansque justum, et retribuens ei secundum justitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Si fugerit populus tuus Israël inimicos suos (quia peccaturus est tibi), et agentes pœnitentiam, et confitentes nomini tuo, venerint, et oraverint, et deprecati te fuerint in domo hac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'exaudi in cælo, et dimitte peccatum populi tui Israël, et reduces eos in terram quam dedisti patribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Si clausum fuerit cælum, et non pluerit propter peccata eorum, et orantes in loco isto, pœnitentiam egerint nomini tuo, et a peccatis suis conversi fuerint propter afflictionem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'exaudi eos in cælo, et dimitte peccata servorum tuorum, et populi tui Israël: et ostende eis viam bonam per quam ambulent, et da pluviam super terram tuam, quam dedisti populo tuo in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Fames si oborta fuerit in terra, aut pestilentia, aut corruptus aër, aut ærugo, aut locusta, vel rubigo, et afflixerit eum inimicus ejus portas obsidens: omnis plaga, universa infirmitas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'cuncta devotatio, et imprecatio quæ acciderit omni homini de populo tuo Israël: si quis cognoverit plagam cordis sui, et expanderit manus suas in domo hac,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'tu exaudies in cælo in loco habitationis tuæ, et repropitiaberis, et facies ut des unicuique secundum omnes vias suas, sicut videris cor ejus (quia tu nosti solus cor omnium filiorum hominum),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'ut timeant te cunctis diebus quibus vivunt super faciem terræ quam dedisti patribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Insuper et alienigena, qui non est de populo tuo Israël, cum venerit de terra longinqua propter nomen tuum (audietur enim nomen tuum magnum, et manus tua fortis, et brachium tuum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'extentum ubique), cum venerit ergo, et oraverit in hoc loco,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'tu exaudies in cælo, in firmamento habitaculi tui, et facies omnia pro quibus invocaverit te alienigena: ut discant universi populi terrarum nomen tuum timere, sicut populus tuus Israël, et probent quia nomen tuum invocatum est super domum hanc quam ædificavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Si egressus fuerit populus tuus ad bellum contra inimicos suos per viam, quocumque miseris eos, orabunt te contra viam civitatis quam elegisti, et contra domum quam ædificavi nomini tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'et exaudies in cælo orationes eorum et preces eorum, et facies judicium eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Quod si peccaverint tibi (non est enim homo qui non peccet) et iratus tradideris eos inimicis suis, et captivi ducti fuerint in terram inimicorum longe vel prope,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'et egerint pœnitentiam in corde suo in loco captivitatis, et conversi deprecati te fuerint in captivitate sua, dicentes: Peccavimus: inique egimus, impie gessimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'et reversi fuerint ad te in universo corde suo et tota anima sua in terra inimicorum suorum, ad quam captivi ducti fuerint: et oraverint te contra viam terræ suæ, quam dedisti patribus eorum, et civitatis quam elegisti, et templi quod ædificavi nomini tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'exaudies in cælo, in firmamento solii tui, orationes eorum et preces eorum, et facies judicium eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'et propitiaberis populo tuo qui peccavit tibi, et omnibus iniquitatibus eorum quibus prævaricati sunt in te: et dabis misericordiam coram eis qui eos captivos habuerint, ut misereantur eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Populus enim tuus est, et hæreditas tua, quos eduxisti de terra \'gypti, de medio fornacis ferreæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Ut sint oculi tui aperti ad deprecationem servi tui, et populi tui Israël, et exaudias eos in universis pro quibus invocaverint te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Tu enim separasti eos tibi in hæreditatem de universis populis terræ, sicut locutus es per Moysen servum tuum quando eduxisti patres nostros de \'gypto, Domine Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Factum est autem, cum complesset Salomon orans Dominum omnem orationem et deprecationem hanc, surrexit de conspectu altaris Domini: utrumque enim genu in terram fixerat, et manus expanderat in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Stetit ergo, et benedixit omni ecclesiæ Israël voce magna, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Benedictus Dominus, qui dedit requiem populo suo Israël, juxta omnia quæ locutus est: non cecidit ne unus quidem sermo ex omnibus bonis quæ locutus est per Moysen servum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Sit Dominus Deus noster nobiscum, sicut fuit cum patribus nostris, non derelinquens nos, neque projiciens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Sed inclinet corda nostra ad se, ut ambulemus in universis viis ejus, et custodiamus mandata ejus, et cæremonias ejus, et judicia quæcumque mandavit patribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Et sint sermones mei isti, quibus deprecatus sum coram Domino, appropinquantes Domino Deo nostro die ac nocte, ut faciat judicium servo suo, et populo suo Israël per singulos dies:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'ut sciant omnes populi terræ quia Dominus ipse est Deus, et non est ultra absque eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Sit quoque cor nostrum perfectum cum Domino Deo nostro, ut ambulemus in decretis ejus, et custodiamus mandata ejus, sicut et hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Igitur rex, et omnis Israël cum eo, immolabant victimas coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Mactavitque Salomon hostias pacificas, quas immolavit Domino, boum viginti duo millia, et ovium centum viginti millia: et dedicaverunt templum Domini rex et filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'In die illa sanctificavit rex medium atrii quod erat ante domum Domini: fecit quippe holocaustum ibi, et sacrificium, et adipem pacificorum: quoniam altare æreum quod erat coram Domino, minus erat, et capere non poterat holocaustum, et sacrificium, et adipem pacificorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Fecit ergo Salomon in tempore illo festivitatem celebrem, et omnis Israël cum eo, multitudo magna ab introitu Emath usque ad rivum \'gypti, coram Domino Deo nostro, septem diebus et septem diebus, id est, quatuordecim diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Et in die octava dimisit populos: qui benedicentes regi, profecti sunt in tabernacula sua lætantes, et alacri corde super omnibus bonis quæ fecerat Dominus David servo suo, et Israël populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Factum est autem cum perfecisset Salomon ædificium domus Domini, et ædificium regis, et omne quod optaverat et voluerat facere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'apparuit ei Dominus secundo, sicut apparuerat ei in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Dixitque Dominus ad eum: Exaudivi orationem tuam et deprecationem tuam, quam deprecatus es coram me: sanctificavi domum hanc quam ædificasti, ut ponerem nomen meum ibi in sempiternum, et erunt oculi mei et cor meum ibi cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Tu quoque si ambulaveris coram me sicut ambulavit pater tuus, in simplicitate cordis et in æquitate, et feceris omnia quæ præcepi tibi, et legitima mea et judicia mea servaveris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'ponam thronum regni tui super Israël in sempiternum, sicut locutus sum David patri tuo, dicens: Non auferetur vir de genere tuo de solio Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Si autem aversione aversi fueritis vos et filii vestri, non sequentes me, nec custodientes mandata mea et cæremonias meas quas proposui vobis, sed abieritis et colueritis deos alienos, et adoraveritis eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'auferam Israël de superficie terræ quam dedi eis, et templum quod sanctificavi nomini meo, projiciam a conspectu meo: eritque Israël in proverbium, et in fabulam cunctis populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Et domus hæc erit in exemplum: omnis qui transierit per eam, stupebit, et sibilabit, et dicet: Quare fecit Dominus sic terræ huic, et domui huic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Et respondebunt: Quia dereliquerunt Dominum Deum suum, qui eduxit patres eorum de terra \'gypti, et secuti sunt deos alienos, et adoraverunt eos, et coluerunt eos: idcirco induxit Dominus super eos omne malum hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Expletis autem annis viginti postquam ædificaverat Salomon duas domos, id est, domum Domini, et domum regis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(Hiram rege Tyri præbente Salomoni ligna cedrina et abiegna, et aurum juxta omne quod opus habuerat), tunc dedit Salomon Hiram viginti oppida in terra Galilææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et egressus est Hiram de Tyro ut videret oppida quæ dederat ei Salomon, et non placuerunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et ait: Hæccine sunt civitates quas dedisti mihi, frater? Et appellavit eas terram Chabul, usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Misit quoque Hiram ad regem Salomonem centum viginti talenta auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Hæc est summa expensarum quam obtulit rex Salomon ad ædificandam domum Domini et domum suam, et Mello, et murum Jerusalem, et Heser, et Mageddo, et Gazer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Pharao rex \'gypti ascendit, et cepit Gazar, succenditque eam igni, et Chananæum, qui habitabat in civitate, interfecit: et dedit eam in dotem filiæ suæ uxori Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, '\'dificavit ergo Salomon Gazer, et Bethoron inferiorem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'et Balaath, et Palmiram in terra solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Et omnes vicos qui ad se pertinebant et erant absque muro, munivit, et civitates curruum et civitates equitum, et quodcumque ei placuit ut ædificaret in Jerusalem, et in Libano, et in omni terra potestatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Universum populum qui remanserat de Amorrhæis, et Hethæis, et Pherezæis, et Hevæis, et Jebusæis, qui non sunt de filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'horum filios qui remanserant in terra, quos scilicet non potuerant filii Israël exterminare, fecit Salomon tributarios usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'De filiis autem Israël non constituit Salomon servire quemquam, sed erant viri bellatores, et ministri ejus, et principes, et duces, et præfecti curruum et equorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Erant autem principes super omnia opera Salomonis præpositi quingenti quinquaginta, qui habebant subjectum populum, et statutis operibus imperabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Filia autem Pharaonis ascendit de civitate David in domum suam, quam ædificaverat ei Salomon: tunc ædificavit Mello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Offerebat quoque Salomon, tribus vicibus per annos singulos, holocausta et pacificas victimas super altare quod ædificaverat Domino, et adolebat thymiama coram Domino: perfectumque est templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Classem quoque fecit rex Salomon in Asiongaber, quæ est juxta Ailath in littore maris Rubri, in terra Idumææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Misitque Hiram in classe illa servos suos viros nauticos et gnaros maris, cum servis Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Qui cum venissent in Ophir, sumptum inde aurum quadringentorum viginti talentorum, detulerunt ad regem Salomonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Sed et regina Saba, audita fama Salomonis in nomine Domini, venit tentare eum in ænigmatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Et ingressa Jerusalem multo cum comitatu et divitiis, camelis portantibus aromata, et aurum infinitum nimis, et gemmas pretiosas, venit ad regem Salomonem, et locuta est ei universa quæ habebat in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Et docuit eam Salomon omnia verba quæ proposuerat: non fuit sermo qui regem posset latere, et non responderet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Videns autem regina Saba omnem sapientiam Salomonis, et domum quam ædificaverat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'et cibos mensæ ejus, et habitacula servorum, et ordines ministrantium, vestesque eorum, et pincernas, et holocausta quæ offerebat in domo Domini: non habebat ultra spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Dixitque ad regem: Verus est sermo quem audivi in terra mea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'super sermonibus tuis, et super sapientia tua: et non credebam narrantibus mihi, donec ipsa veni, et vidi oculis meis, et probavi quod media pars mihi nuntiata non fuerit: major est sapientia et opera tua, quam rumor quem audivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Beati viri tui, et beati servi tui, qui stant coram te semper, et audiunt sapientiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Sit Dominus Deus tuus benedictus, cui complacuisti, et posuit te super thronum Israël, eo quod dilexerit Dominus Israël in sempiternum, et constituit te regem ut faceres judicium et justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Dedit ergo regi centum viginti talenta auri, et aromata multa nimis, et gemmas pretiosas: non sunt allata ultra aromata tam multa, quam ea quæ dedit regina Saba regi Salomoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '(Sed et classis Hiram, quæ portabat aurum de Ophir, attulit ex Ophir ligna thyina multa nimis, et gemmas pretiosas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Fecitque rex de lignis thyinis fulcra domus Domini et domus regiæ, et citharas lyrasque cantoribus: non sunt allata hujuscemodi ligna thyina, neque visa usque in præsentem diem.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Rex autem Salomon dedit reginæ Saba omnia quæ voluit et petivit ab eo, exceptis his quæ ultro obtulerat ei munere regio. Quæ reversa est, et abiit in terram suam cum servis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Erat autem pondus auri quod afferebatur Salomoni per annos singulos, sexcentorum sexaginta sex talentorum auri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'excepto eo quod afferebant viri qui super vectigalia erant, et negotiatores, universique scruta vendentes, et omnes reges Arabiæ, ducesque terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Fecit quoque rex Salomon ducenta scuta de auro purissimo: sexcentos auri siclos dedit in laminas scuti unius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Et trecentas peltas ex auro probato: trecentæ minæ auri unam peltam vestiebant: posuitque eas rex in domo saltus Libani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Fecit etiam rex Salomon thronum de ebore grandem: et vestivit eum auro fulvo nimis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'qui habebat sex gradus: et summitas throni rotunda erat in parte posteriori: et duæ manus hinc atque inde tenentes sedile: et duo leones stabant juxta manus singulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Et duodecim leunculi stantes super sex gradus hinc atque inde: non est factum tale opus in universis regnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Sed et omnia vasa quibus potabat rex Salomon, erant aurea: et universa supellex domus saltus Libani de auro purissimo: non erat argentum, nec alicujus pretii putabatur in diebus Salomonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'quia classis regis per mare cum classe Hiram semel per tres annos ibat in Tharsis, deferens inde aurum, et argentum, et dentes elephantorum, et simias, et pavos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Magnificatus est ergo rex Salomon super omnes reges terræ divitiis et sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Et universa terra desiderabat vultum Salomonis, ut audiret sapientiam ejus, quam dederat Deus in corde ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et singuli deferebant ei munera, vasa argentea et aurea, vestes et arma bellica, aromata quoque, et equos et mulos per annos singulos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Congregavitque Salomon currus et equites, et facti sunt ei mille quadringenti currus, et duodecim millia equitum: et disposuit eos per civitates munitas, et cum rege in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Fecitque ut tanta esset abundantia argenti in Jerusalem, quanta et lapidum: et cedrorum præbuit multitudinem quasi sycomoros quæ nascuntur in campestribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Et educebantur equi Salomoni de \'gypto, et de Coa. Negotiatores enim regis emebant de Coa, et statuto pretio perducebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Egrediebatur autem quadriga ex \'gypto sexcentis siclis argenti, et equus centum quinquaginta. Atque in hunc modum cuncti reges Hethæorum et Syriæ equos venundabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Rex autem Salomon adamavit mulieres alienigenas multas, filiam quoque Pharaonis, et Moabitidas, et Ammonitidas, Idumæas, et Sidonias, et Hethæas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'de gentibus super quibus dixit Dominus filiis Israël: Non ingrediemini ad eas, neque de illis ingredientur ad vestras: certissime enim avertent corda vestra ut sequamini deos earum. His itaque copulatus est Salomon ardentissimo amore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Fueruntque ei uxores quasi reginæ septingentæ, et concubinæ trecentæ: et averterunt mulieres cor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Cumque jam esset senex, depravatum est cor ejus per mulieres, ut sequeretur deos alienos: nec erat cor ejus perfectum cum Domino Deo suo, sicut cor David patris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Sed colebat Salomon Astarthen deam Sidoniorum, et Moloch idolum Ammonitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Fecitque Salomon quod non placuerat coram Domino, et non adimplevit ut sequeretur Dominum sicut David pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tunc ædificavit Salomon fanum Chamos idolo Moab in monte qui est contra Jerusalem, et Moloch idolo filiorum Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Atque in hunc modum fecit universis uxoribus suis alienigenis, quæ adolebant thura, et immolabant diis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Igitur iratus est Dominus Salomoni, quod aversa esset mens ejus a Domino Deo Israël, qui apparuerat ei secundo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'et præceperat de verbo hoc ne sequeretur deos alienos: et non custodivit quæ mandavit ei Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Dixit itaque Dominus Salomoni: Quia habuisti hoc apud te, et non custodisti pactum meum, et præcepta mea quæ mandavi tibi, disrumpens scindam regnum tuum, et dabo illud servo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Verumtamen in diebus tuis non faciam propter David patrem tuum: de manu filii tui scindam illud,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'nec totum regnum auferam, sed tribum unam dabo filio tuo propter David servum meum, et Jerusalem, quam elegi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Suscitavit autem Dominus adversarium Salomoni Adad Idumæum de semine regio, qui erat in Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Cum enim esset David in Idumæa, et ascendisset Joab princeps militiæ ad sepeliendum eos qui fuerant interfecti, et occidisset omnem masculinum in Idumæa');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(sex enim mensibus ibi moratus est Joab, et omnis Israël, donec interimeret omne masculinum in Idumæa),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'fugit Adad ipse, et viri Idumæi de servis patris ejus cum eo, ut ingrederetur \'gyptum: erat autem Adad puer parvulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Cumque surrexissent de Madian, venerunt in Pharan, tuleruntque secum viros de Pharan, et introierunt \'gyptum ad Pharaonem regem \'gypti: qui dedit ei domum, et cibos constituit, et terram delegavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Et invenit Adad gratiam coram Pharaone valde, in tantum ut daret ei uxorem sororem uxoris suæ germanam Taphnes reginæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Genuitque ei soror Taphnes Genubath filium, et nutrivit eum Taphnes in domo Pharaonis: eratque Genubath habitans apud Pharaonem cum filiis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Cumque audisset Adad in \'gypto dormisse David cum patribus suis, et mortuum esse Joab principem militiæ, dixit Pharaoni: Dimitte me, ut vadam in terram meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Dixitque ei Pharao: Qua enim re apud me indiges, ut quæras ire ad terram tuam? At ille respondit: Nulla: sed obsecro te ut dimittas me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Suscitavit quoque ei Deus adversarium Razon filium Eliada, qui fugerat Adarezer regem Soba dominum suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'et congregavit contra eum viros, et factus est princeps latronum cum interficeret eos David: abieruntque Damascum, et habitaverunt ibi, et constituerunt eum regem in Damasco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'eratque adversarius Israëli cunctis diebus Salomonis: et hoc est malum Adad, et odium contra Israël: regnavitque in Syria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboam quoque filius Nabat, Ephrathæus, de Sareda, servus Salomonis, cujus mater erat nomine Sarva, mulier vidua, levavit manum contra regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Et hæc est causa rebellionis adversus eum, quia Salomon ædificavit Mello, et coæquavit voraginem civitatis David patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Erat autem Jeroboam vir fortis et potens: vidensque Salomon adolescentem bonæ indolis et industrium, constituerat eum præfectum super tributa universæ domus Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Factum est igitur in tempore illo, ut Jeroboam egrederetur de Jerusalem, et inveniret eum Ahias Silonites propheta in via, opertus pallio novo: erant autem duo tantum in agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Apprehendensque Ahias pallium suum novum quo coopertus erat, scidit in duodecim partes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Et ait ad Jeroboam: Tolle tibi decem scissuras: hæc enim dicit Dominus Deus Israël: Ecce ego scindam regnum de manu Salomonis, et dabo tibi decem tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Porro una tribus remanebit ei propter servum meum David, et Jerusalem civitatem, quam elegi ex omnibus tribubus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'eo quod dereliquerit me, et adoraverit Astarthen deam Sidoniorum, et Chamos deum Moab, et Moloch deum filiorum Ammon: et non ambulaverit in viis meis, ut faceret justitiam coram me, et præcepta mea et judicia, sicut David pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Nec auferam omne regnum de manu ejus, sed ducem ponam eum cunctis diebus vitæ suæ, propter David servum meum quem elegi, qui custodivit mandata mea et præcepta mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Auferam autem regnum de manu filii ejus, et dabo tibi decem tribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'filio autem ejus dabo tribum unam, ut remaneat lucerna David servo meo cunctis diebus coram me in Jerusalem civitate, quam elegi ut esset nomen meum ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Te autem assumam, et regnabis super omnia quæ desiderat anima tua, erisque rex super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Si igitur audieris omnia quæ præcepero tibi, et ambulaveris in viis meis, et feceris quod rectum est coram me, custodiens mandata mea et præcepta mea, sicut fecit David servus meus: ero tecum, et ædificabo tibi domum fidelem, quomodo ædificavi David domum: et tradam tibi Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'et affligam semen David super hoc, verumtamen non cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Voluit ergo Salomon interficere Jeroboam: qui surrexit, et aufugit in \'gyptum ad Sesac regem \'gypti, et fuit in \'gypto usque ad mortem Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Reliquum autem verborum Salomonis, et omnia quæ fecit, et sapientia ejus, ecce universa scripta sunt in libro verborum dierum Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Dies autem quos regnavit Salomon in Jerusalem super omnem Israël, quadraginta anni sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Dormivitque Salomon cum patribus suis, et sepultus est in civitate David patris sui: regnavitque Roboam filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Venit autem Roboam in Sichem: illuc enim congregatus erat omnis Israël ad constituendum eum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'At vero Jeroboam filius Nabat, cum adhuc esset in \'gypto profugus a facie regis Salomonis, audita morte ejus, reversus est de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Miseruntque et vocaverunt eum: venit ergo Jeroboam, et omnis multitudo Israël, et locuti sunt ad Roboam, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Pater tuus durissimum jugum imposuit nobis: tu itaque nunc imminue paululum de imperio patris tui durissimo, et de jugo gravissimo quod imposuit nobis, et serviemus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Qui ait eis: Ite usque ad tertium diem, et revertimini ad me. Cumque abiisset populus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'iniit consilium rex Roboam cum senioribus qui assistebant coram Salomone patre ejus cum adhuc viveret, et ait: Quod datis mihi consilium, ut respondeam populo huic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Qui dixerunt ei: Si hodie obedieris populo huic, et servieris, et petitioni eorum cesseris, locutusque fueris ad eos verba lenia, erunt tibi servi cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Qui dereliquit consilium senum, quod dederant ei, et adhibuit adolescentes, qui nutriti fuerant cum eo, et assistebant illi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'dixitque ad eos: Quod mihi datis consilium, ut respondeam populo huic, qui dixerunt mihi: Levius fac jugum quod imposuit pater tuus super nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Et dixerunt ei juvenes qui nutriti fuerant cum eo: Sic loqueris populo huic, qui locuti sunt ad te, dicentes: Pater tuus aggravavit jugum nostrum: tu releva nos. Sic loqueris ad eos: Minimus digitus meus grossior est dorso patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Et nunc pater meus posuit super vos jugum grave, ego autem addam super jugum vestrum: pater meus cecidit vos flagellis, ego autem cædam vos scorpionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Venit ergo Jeroboam et omnis populus ad Roboam die tertia, sicut locutus fuerat rex, dicens: Revertimini ad me die tertia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Responditque rex populo dura, derelicto consilio seniorum quod ei dederant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'et locutus est eis secundum consilium juvenum, dicens: Pater meus aggravavit jugum vestrum, ego autem addam jugo vestro: pater meus cecidit vos flagellis, ego autem cædam vos scorpionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Et non acquievit rex populo: quoniam aversatus fuerat eum Dominus, ut suscitaret verbum suum quod locutus fuerat in manu Ahiæ Silonitæ, ad Jeroboam filium Nabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Videns itaque populus quod noluisset eos audire rex, respondit ei dicens: Quæ nobis pars in David? vel quæ hæreditas in filio Isai? vade in tabernacula tua, Israël: nunc vide domum tuam, David. Et abiit Israël in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Super filios autem Israël, quicumque habitabant in civitatibus Juda, regnavit Roboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Misit ergo rex Roboam Aduram, qui erat super tributa: et lapidavit eum omnis Israël, et mortuus est. Porro rex Roboam festinus ascendit currum, et fugit in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'recessitque Israël a domo David usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Factum est autem cum audisset omnis Israël quod reversus esset Jeroboam, miserunt, et vocaverunt eum congregato cœtu, et constituerunt eum regem super omnem Israël: nec secutus est quisquam domum David præter tribum Juda solam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Venit autem Roboam Jerusalem, et congregavit universam domum Juda, et tribum Benjamin, centum octoginta millia electorum virorum bellatorum, ut pugnarent contra domum Israël, et reducerent regnum Roboam filio Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Factus est autem sermo Domini ad Semeiam virum Dei, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Loquere ad Roboam filium Salomonis regem Juda, et ad omnem domum Juda, et Benjamin, et reliquos de populo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Hæc dicit Dominus: Non ascendetis, neque bellabitis contra fratres vestros filios Israël: revertatur vir in domum suam: a me enim factum est verbum hoc. Audierunt sermonem Domini, et reversi sunt de itinere, sicut eis præceperat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, '\'dificavit autem Jeroboam Sichem in monte Ephraim, et habitavit ibi: et egressus inde ædificavit Phanuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Dixitque Jeroboam in corde suo: Nunc revertetur regnum ad domum David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'si ascenderit populus iste ut faciat sacrificia in domo Domini in Jerusalem: et convertetur cor populi hujus ad dominum suum Roboam regem Juda, interficientque me, et revertentur ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Et excogitato consilio fecit duos vitulos aureos, et dixit eis: Nolite ultra ascendere in Jerusalem: ecce dii tui Israël, qui te eduxerunt de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Posuitque unum in Bethel, et alterum in Dan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'et factum est verbum hoc in peccatum: ibat enim populus ad adorandum vitulum usque in Dan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Et fecit fana in excelsis, et sacerdotes de extremis populi, qui non erant de filiis Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Constituitque diem solemnem in mense octavo, quintadecima die mensis, in similitudinem solemnitatis quæ celebrabatur in Juda. Et ascendens altare, similiter fecit in Bethel, ut immolaret vitulis quos fabricatus fuerat: constituitque in Bethel sacerdotes excelsorum quæ fecerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Et ascendit super altare quod exstruxerat in Bethel, quintadecima die mensis octavi, quem finxerat de corde suo: et fecit solemnitatem filiis Israël, et ascendit super altare, ut adoleret incensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Et ecce vir Dei venit de Juda in sermone Domini in Bethel, Jeroboam stante super altare, et thus jaciente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et exclamavit contra altare in sermone Domini, et ait: Altare, altare, hæc dicit Dominus: Ecce filius nascetur domui David, Josias nomine, et immolabit super te sacerdotes excelsorum, qui nunc in te thura succendunt: et ossa hominum super te incendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Deditque in illa die signum, dicens: Hoc erit signum quod locutus est Dominus: ecce altare scindetur, et effundetur cinis qui in eo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Cumque audisset rex sermonem hominis Dei quem inclamaverat contra altare in Bethel, extendit manum suam de altari, dicens: Apprehendite eum. Et exaruit manus ejus quam extenderat contra eum, nec valuit retrahere eam ad se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Altare quoque scissum est, et effusus est cinis de altari, juxta signum quod prædixerat vir Dei in sermone Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Et ait rex ad virum Dei: Deprecare faciem Domini Dei tui, et ora pro me, ut restituatur manus mea mihi. Oravitque vir Dei faciem Domini, et reversa est manus regis ad eum, et facta est sicut prius fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Locutus est autem rex ad virum Dei: Veni mecum domum ut prandeas, et dabo tibi munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Responditque vir Dei ad regem: Si dederis mihi mediam partem domus tuæ, non veniam tecum, nec comedam panem, neque bibam aquam in loco isto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'sic enim mandatum est mihi in sermone Domini præcipientis: Non comedes panem, neque bibes aquam, nec reverteris per viam qua venisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Abiit ergo per aliam viam, et non est reversus per iter quo venerat in Bethel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Prophetes autem quidam senex habitabat in Bethel: ad quem venerunt filii sui, et narraverunt ei omnia opera quæ fecerat vir Dei illa die in Bethel: et verba quæ locutus fuerat ad regem, narraverunt patri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Et dixit eis pater eorum: Per quam viam abiit? Ostenderunt ei filii sui viam per quam abierat vir Dei, qui venerat de Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et ait filiis suis: Sternite mihi asinum. Qui cum stravissent, ascendit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'et abiit post virum Dei, et invenit eum sedentem subtus terebinthum: et ait illi: Tune es vir Dei qui venisti de Juda? Respondit ille: Ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Dixitque ad eum: Veni mecum domum, ut comedas panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Qui ait: Non possum reverti, neque venire tecum: nec comedam panem, neque bibam aquam in loco isto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'quia locutus est Dominus ad me in sermone Domini, dicens: Non comedes panem, et non bibes aquam ibi, nec reverteris per viam qua ieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Qui ait illi: Et ego propheta sum similis tui: et angelus locutus est mihi in sermone Domini, dicens: Reduc eum tecum in domum tuam, ut comedat panem, et bibat aquam. Fefellit eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'et reduxit secum: comedit ergo panem in domo ejus, et bibit aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Cumque sederent ad mensam, factus est sermo Domini ad prophetam qui reduxerat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Et exclamavit ad virum Dei qui venerat de Juda, dicens: Hæc dicit Dominus: Quia non obediens fuisti ori Domini, et non custodisti mandatum quod præcepit tibi Dominus Deus tuus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'et reversus es, et comedisti panem, et bibisti aquam in loco in quo præcepit tibi ne comederes panem neque biberes aquam, non inferetur cadaver tuum in sepulchrum patrum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Cumque comedisset et bibisset, stravit asinum suum prophetæ quem reduxerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Qui cum abiisset, invenit eum leo in via, et occidit, et erat cadaver ejus projectum in itinere: asinus autem stabat juxta illum, et leo stabat juxta cadaver.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et ecce viri transeuntes viderunt cadaver projectum in via, et leonem stantem juxta cadaver. Et venerunt, et divulgaverunt in civitate in qua prophetes ille senex habitabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Quod cum audisset propheta ille qui reduxerat eum de via, ait: Vir Dei est, qui inobediens fuit ori Domini, et tradidit eum Dominus leoni, et confregit eum, et occidit juxta verbum Domini quod locutus est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Dixitque ad filios suos: Sternite mihi asinum. Qui cum stravissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'et ille abiisset, invenit cadaver ejus projectum in via, et asinum et leonem stantes juxta cadaver: non comedit leo de cadavere, nec læsit asinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Tulit ergo prophetes cadaver viri Dei, et posuit illud super asinum, et reversus intulit in civitatem prophetæ senis ut plangeret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Et posuit cadaver ejus in sepulchro suo, et planxerunt eum: Heu, heu mi frater!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Cumque planxissent eum, dixit ad filios suos: Cum mortuus fuero, sepelite me in sepulchro in quo vir Dei sepultus est: juxta ossa ejus ponite ossa mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Profecto enim veniet sermo quem prædixit in sermone Domini contra altare quod est in Bethel, et contra omnia fana excelsorum quæ sunt in urbibus Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Post verba hæc non est reversus Jeroboam de via sua pessima, sed e contrario fecit de novissimis populi sacerdotes excelsorum: quicumque volebat, implebat manum suam, et fiebat sacerdos excelsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Et propter hanc causam peccavit domus Jeroboam, et eversa est, et deleta de superficie terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'In tempore illo ægrotavit Abia filius Jeroboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Dixitque Jeroboam uxori suæ: Surge, et commuta habitum, ne cognoscaris quod sis uxor Jeroboam, et vade in Silo, ubi est Ahias propheta, qui locutus est mihi quod regnaturus essem super populum hunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Tolle quoque in manu tua decem panes, et crustulam, et vas mellis, et vade ad illum: ipse enim indicabit tibi quid eventurum sit puero huic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Fecit ut dixerat, uxor Jeroboam: et consurgens abiit in Silo, et venit in domum Ahiæ: at ille non poterat videre, quia caligaverant oculi ejus præ senectute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Dixit autem Dominus ad Ahiam: Ecce uxor Jeroboam ingreditur ut consulat te super filio suo qui ægrotat: hæc et hæc loqueris ei. Cum ergo illa intraret, et dissimularet se esse quæ erat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'audivit Ahias sonitum pedum ejus introëuntis per ostium, et ait: Ingredere, uxor Jeroboam: quare aliam te esse simulas? ego autem missus sum ad te durus nuntius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Vade, et dic Jeroboam: Hæc dicit Dominus Deus Israël: Quia exaltavi te de medio populi, et dedi te ducem super populum meum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'et scidi regnum domus David, et dedi illud tibi, et non fuisti sicut servus meus David, qui custodivit mandata mea, et secutus est me in toto corde suo, faciens quod placitum esset in conspectu meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'sed operatus es mala super omnes qui fuerunt ante te, et fecisti tibi deos alienos et conflatiles, ut me ad iracundiam provocares, me autem projecisti post corpus tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'idcirco ecce ego inducam mala super domum Jeroboam, et percutiam de Jeroboam mingentem ad parietem, et clausum, et novissimum in Israël: et mundabo reliquias domus Jeroboam, sicut mundari solet fimus usque ad purum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Qui mortui fuerint de Jeroboam in civitate, comedent eos canes: qui autem mortui fuerint in agro, vorabunt eos aves cæli: quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Tu igitur surge, et vade in domum tuam: et in ipso introitu pedum tuorum in urbem, morietur puer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'et planget eum omnis Israël, et sepeliet: iste enim solus inferetur de Jeroboam in sepulchrum, quia inventus est super eo sermo bonus a Domino Deo Israël in domo Jeroboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Constituet autem sibi Dominus regem super Israël, qui percutiet domum Jeroboam in hac die, et in hoc tempore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'et percutiet Dominus Deus Israël, sicut moveri solet arundo in aqua: et evellet Israël de terra bona hac, quam dedit patribus eorum, et ventilabit eos trans flumen: quia fecerunt sibi lucos, ut irritarent Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Et tradet Dominus Israël propter peccata Jeroboam, qui peccavit, et peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Surrexit itaque uxor Jeroboam, et abiit, et venit in Thersa: cumque illa ingrederetur limen domus, puer mortuus est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'et sepelierunt eum. Et planxit eum omnis Israël juxta sermonem Domini, quem locutus est in manu servi sui Ahiæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Reliqua autem verborum Jeroboam, quomodo pugnaverit, et quomodo regnaverit, ecce scripta sunt in libro verborum dierum regum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Dies autem quibus regnavit Jeroboam, viginti duo anni sunt: et dormivit cum patribus suis, regnavitque Nadab filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Porro Roboam filius Salomonis regnavit in Juda. Quadraginta et unius anni erat Roboam cum regnare cœpisset: decem et septem annos regnavit in Jerusalem civitate, quam elegit Dominus ut poneret nomen suum ibi, ex omnibus tribubus Israël. Nomen autem matris ejus Naama Ammanitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Et fecit Judas malum coram Domino, et irritaverunt eum super omnibus quæ fecerant patres eorum in peccatis suis quæ peccaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, '\'dificaverunt enim et ipsi sibi aras, et statuas, et lucos super omnem collem excelsum, et subter omnem arborem frondosam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'sed et effeminati fuerunt in terra, feceruntque omnes abominationes gentium quas attrivit Dominus ante faciem filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'In quinto autem anno regni Roboam, ascendit Sesac rex \'gypti in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'et tulit thesauros domus Domini, et thesauros regios, et universa diripuit: scuta quoque aurea, quæ fecerat Salomon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'pro quibus fecit rex Roboam scuta ærea, et tradidit ea in manum ducum scutariorum, et eorum qui excubabant ante ostium domus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Cumque ingrederetur rex in domum Domini, portabant ea qui præeundi habebant officium: et postea reportabant ad armamentarium scutariorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Reliqua autem sermonum Roboam, et omnia quæ fecit, ecce scripta sunt in libro sermonum dierum regum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Fuitque bellum inter Roboam et Jeroboam cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Dormivitque Roboam cum patribus suis, et sepultus est cum eis in civitate David: nomen autem matris ejus Naama Ammanitis: et regnavit Abiam filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Igitur in octavodecimo anno regni Jeroboam filii Nabat, regnavit Abiam super Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tribus annis regnavit in Jerusalem: nomen matris ejus Maacha filia Abessalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ambulavitque in omnibus peccatis patris sui, quæ fecerat ante eum: nec erat cor ejus perfectum cum Domino Deo suo, sicut cor David patris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Sed propter David dedit ei Dominus Deus suus lucernam in Jerusalem, ut suscitaret filium ejus post eum, et statueret Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'eo quod fecisset David rectum in oculis Domini, et non declinasset ab omnibus quæ præceperat ei cunctis diebus vitæ suæ, excepto sermone Uriæ Hethæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Attamen bellum fuit inter Roboam et Jeroboam omni tempore vitæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Reliqua autem sermonum Abiam, et omnia quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda? Fuitque prælium inter Abiam et inter Jeroboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Et dormivit Abiam cum patribus suis, et sepelierunt eum in civitate David, regnavitque Asa filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'In anno ergo vigesimo Jeroboam regis Israël regnavit Asa rex Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'et quadraginta et uno anno regnavit in Jerusalem. Nomen matris ejus Maacha filia Abessalom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et fecit Asa rectum ante conspectum Domini, sicut David pater ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'et abstulit effeminatos de terra, purgavitque universas sordes idolorum quæ fecerant patres ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Insuper et Maacham matrem suam amovit, ne esset princeps in sacris Priapi, et in luco ejus quem consecraverat: subvertitque specum ejus, et confregit simulacrum turpissimum, et combussit in torrente Cedron:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'excelsa autem non abstulit. Verumtamen cor Asa perfectum erat cum Domino cunctis diebus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'et intulit ea quæ sanctificaverat pater suus, et voverat, in domum Domini, argentum, et aurum, et vasa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Bellum autem erat inter Asa, et Baasa regem Israël cunctis diebus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Ascendit quoque Baasa rex Israël in Judam, et ædificavit Rama, ut non posset quispiam egredi vel ingredi de parte Asa regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Tollens itaque Asa omne argentum et aurum quod remanserat in thesauris domus Domini, et in thesauris domus regiæ, et dedit illud in manus servorum suorum: et misit ad Benadad filium Tabremon filii Hezion, regem Syriæ, qui habitabat in Damasco, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Fœdus est inter me et te, et inter patrem meum et patrem tuum: ideo misi tibi munera, argentum et aurum: et peto ut venias, et irritum facias fœdus quod habes cum Baasa rege Israël, et recedat a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Acquiescens Benadad regi Asa, misit principes exercitus sui in civitates Israël, et percusserunt Ahion, et Dan, et Abeldomum Maacha, et universam Cenneroth, omnem scilicet terram Nephthali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Quod cum audisset Baasa, intermisit ædificare Rama, et reversus est in Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Rex autem Asa nuntium misit in omnem Judam, dicens: Nemo sit excusatus. Et tulerunt lapides de Rama, et ligna ejus, quibus ædificaverat Baasa, et exstruxit de eis rex Asa Gabaa Benjamin, et Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Reliqua autem omnium sermonum Asa, et universæ fortitudines ejus, et cuncta quæ fecit, et civitates quas exstruxit, nonne hæc scripta sunt in libro verborum dierum regum Juda? Verumtamen in tempore senectutis suæ doluit pedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et dormivit cum patribus suis, et sepultus est cum eis in civitate David patris sui. Regnavitque Josaphat filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab vero filius Jeroboam regnavit super Israël anno secundo Asa regis Juda: regnavitque super Israël duobus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et fecit quod malum est in conspectu Domini, et ambulavit in viis patris sui, et in peccatis ejus quibus peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Insidiatus est autem ei Baasa filius Ahiæ de domo Issachar, et percussit eum in Gebbethon, quæ est urbs Philisthinorum: siquidem Nadab et omnis Israël obsidebant Gebbethon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Interfecit ergo illum Baasa in anno tertio Asa regis Juda, et regnavit pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Cumque regnasset, percussit omnem domum Jeroboam: non dimisit ne unam quidem animam de semine ejus donec deleret eum, juxta verbum Domini quod locutus fuerat in manu servi sui Ahiæ Silonitis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'propter peccata Jeroboam, quæ peccaverat, et quibus peccare fecerat Israël: et propter delictum quo irritaverat Dominum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Reliqua autem sermonum Nadab, et omnia quæ operatus est, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Fuitque bellum inter Asa, et Baasa regem Israël, cunctis diebus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Anno tertio Asa regis Juda, regnavit Baasa filius Ahiæ super omnem Israël in Thersa, viginti quatuor annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et fecit malum coram Domino, ambulavitque in via Jeroboam, et in peccatis ejus quibus peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Factus est autem sermo Domini ad Jehu filium Hanani contra Baasa, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Pro eo quod exaltavi te de pulvere, et posui te ducem super populum meum Israël, tu autem ambulasti in via Jeroboam, et peccare fecisti populum meum Israël, ut me irritares in peccatis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'ecce ego demetam posteriora Baasa, et posteriora domus ejus, et faciam domum tuam sicut domum Jeroboam filii Nabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Qui mortuus fuerit de Baasa in civitate, comedent eum canes: et qui mortuus fuerit ex eo in regione, comedent eum volucres cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Reliqua autem sermonum Baasa, et quæcumque fecit, et prælia ejus, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Dormivit ergo Baasa cum patribus suis, sepultusque est in Thersa: et regnavit Ela filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Cum autem in manu Jehu filii Hanani prophetæ verbum Domini factum esset contra Baasa, et contra domum ejus, et contra omne malum quod fecerat coram Domino, ad irritandum eum in operibus manuum suarum, ut fieret sicut domus Jeroboam: ob hanc causam occidit eum, hoc est, Jehu filium Hanani prophetam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Anno vigesimo sexto Asa regis Juda, regnavit Ela filius Baasa super Israël in Thersa, duobus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et rebellavit contra eum servus suus Zambri, dux mediæ partis equitum: erat autem Ela in Thersa bibens, et temulentus in domo Arsa præfecti Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Irruens ergo Zambri, percussit et occidit eum, anno vigesimo septimo Asa regis Juda, et regnavit pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Cumque regnasset, et sedisset super solium ejus, percussit omnem domum Baasa, et non dereliquit ex ea mingentem ad parietem: et propinquos et amicos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Delevitque Zambri omnem domum Baasa, juxta verbum Domini quod locutus fuerat ad Baasa in manu Jehu prophetæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'propter universa peccata Baasa, et peccata Ela filii ejus, qui peccaverunt, et peccare fecerunt Israël, provocantes Dominum Deum Israël in vanitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Reliqua autem sermonum Ela, et omnia quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Anno vigesimo septimo Asa regis Juda, regnavit Zambri septem diebus in Thersa: porro exercitus obsidebat Gebbethon urbem Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Cumque audisset rebellasse Zambri, et occidisse regem, fecit sibi regem omnis Israël Amri, qui erat princeps militiæ super Israël in die illa in castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Ascendit ergo Amri, et omnis Israël cum eo, de Gebbethon, et obsidebant Thersa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Videns autem Zambri quod expugnanda esset civitas, ingressus est palatium, et succendit se cum domo regia: et mortuus est');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'in peccatis suis quæ peccaverat, faciens malum coram Domino, et ambulans in via Jeroboam, et in peccato ejus, quo fecit peccare Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Reliqua autem sermonum Zambri, et insidiarum ejus, et tyrannidis, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tunc divisus est populus Israël in duas partes: media pars populi sequebatur Thebni filium Gineth, ut constitueret eum regem: et media pars Amri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Prævaluit autem populus qui erat cum Amri, populo qui sequebatur Thebni filium Gineth: mortuusque est Thebni, et regnavit Amri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Anno trigesimo primo Asa regis Juda, regnavit Amri super Israël, duodecim annis: in Thersa regnavit sex annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Emitque montem Samariæ a Somer duobus talentis argenti: et ædificavit eum, et vocavit nomen civitatis quam exstruxerat, nomine Semer domini montis, Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Fecit autem Amri malum in conspectu Domini, et operatus est nequiter, super omnes qui fuerunt ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Ambulavitque in omni via Jeroboam filii Nabat, et in peccatis ejus quibus peccare fecerat Israël, ut irritaret Dominum Deum Israël in vanitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Reliqua autem sermonum Amri, et prælia ejus quæ gessit, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Dormivitque Amri cum patribus suis, et sepultus est in Samaria: regnavitque Achab filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Achab vero filius Amri regnavit super Israël anno trigesimo octavo Asa regis Juda. Et regnavit Achab filius Amri super Israël in Samaria viginti et duobus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et fecit Achab filius Amri malum in conspectu Domini super omnes qui fuerunt ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Nec suffecit ei ut ambularet in peccatis Jeroboam filii Nabat: insuper duxit uxorem Jezabel filiam Ethbaal regis Sidoniorum. Et abiit, et servivit Baal, et adoravit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Et posuit aram Baal in templo Baal, quod ædificaverat in Samaria,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'et plantavit lucum: et addidit Achab in opere suo, irritans Dominum Deum Israël super omnes reges Israël qui fuerunt ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'In diebus ejus ædificavit Hiel de Bethel Jericho: in Abiram primitivo suo fundavit eam, et in Segub novissimo suo posuit portas ejus, juxta verbum Domini quod locutus fuerat in manu Josue filii Nun.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Et dixit Elias Thesbites de habitatoribus Galaad ad Achab: Vivit Dominus Deus Israël, in cujus conspectu sto, si erit annis his ros et pluvia, nisi juxta oris mei verba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Et factum est verbum Domini ad eum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Recede hinc, et vade contra orientem, et abscondere in torrente Carith, qui est contra Jordanem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'et ibi de torrente bibes: corvisque præcepi ut pascant te ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Abiit ergo, et fecit juxta verbum Domini: cumque abiisset, sedit in torrente Carith, qui est contra Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Corvi quoque deferebant ei panem et carnes mane, similiter panem et carnes vesperi, et bibebat de torrente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Post dies autem siccatus est torrens: non enim pluerat super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Factus est ergo sermo Domini ad eum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Surge, et vade in Sarephta Sidoniorum, et manebis ibi: præcepi enim ibi mulieri viduæ ut pascat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Surrexit, et abiit in Sarephta. Cumque venisset ad portam civitatis, apparuit ei mulier vidua colligens ligna, et vocavit eam, dixitque ei: Da mihi paululum aquæ in vase ut bibam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Cumque illa pergeret ut afferret, clamavit post tergum ejus, dicens: Affer mihi, obsecro, et buccellam panis in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Quæ respondit: Vivit Dominus Deus tuus, quia non habeo panem, nisi quantum pugillus capere potest farinæ in hydria, et paululum olei in lecytho: en colligo duo ligna ut ingrediar et faciam illum mihi et filio meo, ut comedamus, et moriamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Ad quam Elias ait: Noli timere, sed vade, et fac sicut dixisti: verumtamen mihi primum fac de ipsa farinula subcinericium panem parvulum, et affer ad me: tibi autem et filio tuo facies postea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Hæc autem dicit Dominus Deus Israël: Hydria farinæ non deficiet, nec lecythus olei minuetur, usque ad diem in qua Dominus daturus est pluviam super faciem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Quæ abiit, et fecit juxta verbum Eliæ: et comedit ipse, et illa, et domus ejus: et ex illa die');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'hydria farinæ non defecit, et lecythus olei non est imminutus, juxta verbum Domini quod locutus fuerat in manu Eliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Factum est autem post hæc, ægrotavit filius mulieris matrisfamilias, et erat languor fortissimus, ita ut non remaneret in eo halitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Dixit ergo ad Eliam: Quid mihi et tibi, vir Dei? ingressus es ad me, ut rememorarentur iniquitates meæ, et interficeres filium meum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et ait ad eam Elias: Da mihi filium tuum. Tulitque eum de sinu ejus, et portavit in cœnaculum ubi ipse manebat, et posuit super lectulum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Et clamavit ad Dominum, et dixit: Domine Deus meus, etiam ne viduam apud quam ego utcumque sustentor, afflixisti ut interficeres filium ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Et expandit se, atque mensus est super puerum tribus vicibus, et clamavit ad Dominum, et ait: Domine Deus meus, revertatur, obsecro, anima pueri hujus in viscera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et exaudivit Dominus vocem Eliæ: et reversa est anima pueri intra eum, et revixit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Tulitque Elias puerum, et deposuit eum de cœnaculo in inferiorem domum, et tradidit matri suæ, et ait illi: En vivit filius tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Dixitque mulier ad Eliam: Nunc in isto cognovi quoniam vir Dei es tu, et verbum Domini in ore tuo verum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Post dies multos factum est verbum Domini ad Eliam, in anno tertio, dicens: Vade, et ostende te Achab, ut dem pluviam super faciem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Ivit ergo Elias, ut ostenderet se Achab: erat autem fames vehemens in Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Vocavitque Achab Abdiam dispensatorem domus suæ: Abdias autem timebat Dominum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Nam cum interficeret Jezabel prophetas Domini, tulit ille centum prophetas, et abscondit eos quinquagenos et quinquagenos in speluncis, et pavit eos pane et aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Dixit ergo Achab ad Abdiam: Vade in terram ad universos fontes aquarum, et in cunctas valles, si forte possimus invenire herbam, et salvare equos et mulos, et non penitus jumenta intereant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Diviseruntque sibi regiones ut circuirent eas: Achab ibat per viam unam, et Abdias per viam alteram seorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Cumque esset Abdias in via, Elias occurrit ei: qui cum cognovisset eum, cecidit super faciem suam, et ait: Num tu es, domine mi, Elias?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Cui ille respondit: Ego. Vade, et dic domino tuo: Adest Elias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Et ille: Quid peccavi, inquit, quoniam tradis me servum tuum in manu Achab, ut interficiat me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Vivit Dominus Deus tuus, quia non est gens aut regnum quo non miserit dominus meus te requirens: et respondentibus cunctis: Non est hic: adjuravit regna singula et gentes, eo quod minime reperireris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et nunc tu dicis mihi: Vade, et dic domino tuo: Adest Elias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Cumque recessero a te, spiritus Domini asportabit te in locum quem ego ignoro: et ingressus nuntiabo Achab, et non inveniens te, interficiet me: servus autem tuus timet Dominum ab infantia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Numquid non indicatum est tibi domino meo quid fecerim cum interficeret Jezabel prophetas Domini, quod absconderim de prophetis Domini centum viros, quinquagenos et quinquagenos, in speluncis, et paverim eos pane et aqua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'et nunc tu dicis: Vade, et dic domino tuo: Adest Elias: ut interficiat me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Et dixit Elias: Vivit Dominus exercituum, ante cujus vultum sto, quia hodie apparebo ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Abiit ergo Abdias in occursum Achab, et indicavit ei: venitque Achab in occursum Eliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Et cum vidisset eum, ait: Tune es ille, qui conturbas Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et ille ait: Non ego turbavi Israël, sed tu, et domus patris tui, qui dereliquistis mandata Domini, et secuti estis Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Verumtamen nunc mitte, et congrega ad me universum Israël in monte Carmeli, et prophetas Baal quadringentos quinquaginta, prophetasque lucorum quadringentos, qui comedunt de mensa Jezabel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Misit Achab ad omnes filios Israël, et congregavit prophetas in monte Carmeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Accedens autem Elias ad omnem populum, ait: Usquequo claudicatis in duas partes? si Dominus est Deus, sequimini eum: si autem Baal, sequimini illum. Et non respondit ei populus verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Et ait rursus Elias ad populum: Ego remansi propheta Domini solus: prophetæ autem Baal quadringenti et quinquaginta viri sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Dentur nobis duo boves, et illi eligant sibi bovem unum, et in frusta cædentes ponant super ligna, ignem autem non supponant: et ego faciam bovem alterum, et imponam super ligna, ignem autem non supponam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Invocate nomina deorum vestrorum, et ego invocabo nomen Domini mei: et Deus qui exaudierit per ignem, ipse sit Deus. Respondens omnis populus ait: Optima propositio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Dixit ergo Elias prophetis Baal: Eligite vobis bovem unum, et facite primi, quia vos plures estis: et invocate nomina deorum vestrorum, ignemque non supponatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Qui cum tulissent bovem quem dederat eis, fecerunt: et invocabant nomen Baal de mane usque ad meridiem, dicentes: Baal, exaudi nos. Et non erat vox, nec qui responderet: transiliebantque altare quod fecerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Cumque esset jam meridies, illudebat illis Elias, dicens: Clamate voce majore: deus enim est, et forsitan loquitur, aut in diversorio est, aut in itinere, aut certe dormit, ut excitetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Clamabant ergo voce magna, et incidebant se juxta ritum suum cultris et lanceolis, donec perfunderentur sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Postquam autem transiit meridies, et illis prophetantibus venerat tempus quo sacrificium offerri solet, nec audiebatur vox, nec aliquis respondebat, nec attendebat orantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'dixit Elias omni populo: Venite ad me. Et accedente ad se populo, curavit altare Domini quod destructum fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Et tulit duodecim lapides juxta numerum tribuum filiorum Jacob, ad quem factus est sermo Domini, dicens: Israël erit nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Et ædificavit de lapidibus altare in nomine Domini: fecitque aquæductum, quasi per duas aratiunculas in circuitu altaris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'et composuit ligna: divisitque per membra bovem, et posuit super ligna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'et ait: Implete quatuor hydrias aqua, et fundite super holocaustum et super ligna. Rursumque dixit: Etiam secundo hoc facite. Qui cum fecissent secundo, ait: Etiam tertio idipsum facite. Feceruntque tertio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'et currebant aquæ circum altare, et fossa aquæductus repleta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Cumque jam tempus esset ut offerretur holocaustum, accedens Elias propheta ait: Domine Deus Abraham, et Isaac, et Israël, ostende hodie quia tu es Deus Israël, et ego servus tuus, et juxta præceptum tuum feci omnia verba hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Exaudi me, Domine, exaudi me: ut discat populus iste quia tu es Dominus Deus, et tu convertisti cor eorum iterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Cecidit autem ignis Domini, et voravit holocaustum, et ligna, et lapides, pulverem quoque, et aquam quæ erat in aquæductu lambens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Quod cum vidisset omnis populus, cecidit in faciem suam, et ait: Dominus ipse est Deus, Dominus ipse est Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Dixitque Elias ad eos: Apprehendite prophetas Baal, et ne unus quidem effugiat ex eis. Quos cum apprehendissent, duxit eos Elias ad torrentem Cison, et interfecit eos ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Et ait Elias ad Achab: Ascende, comede, et bibe, quia sonus multæ pluviæ est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Ascendit Achab ut comederet et biberet: Elias autem ascendit in verticem Carmeli, et pronus in terram posuit faciem suam inter genua sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'et dixit ad puerum suum: Ascende, et prospice contra mare. Qui cum ascendisset, et contemplatus esset, ait: Non est quidquam. Et rursum ait illi: Revertere septem vicibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'In septima autem vice, ecce nubecula parva quasi vestigium hominis ascendebat de mari. Qui ait: Ascende, et dic Achab: Junge currum tuum et descende, ne occupet te pluvia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Cumque se verteret huc atque illuc, ecce cæli contenebrati sunt, et nubes, et ventus, et facta est pluvia grandis. Ascendens itaque Achab, abiit in Jezrahel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'et manus Domini facta est super Eliam, accinctisque lumbis currebat ante Achab, donec veniret in Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Nuntiavit autem Achab Jezabel omnia quæ fecerat Elias, et quomodo occidisset universos prophetas gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Misitque Jezabel nuntium ad Eliam, dicens: Hæc mihi faciant dii, et hæc addant, nisi hac hora cras posuero animam tuam sicut animam unius ex illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Timuit ergo Elias, et surgens abiit quocumque eum ferebat voluntas: venitque in Bersabee Juda, et dimisit ibi puerum suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'et perrexit in desertum, viam unius diei. Cumque venisset, et sederet subter unam juniperum, petivit animæ suæ ut moreretur, et ait: Sufficit mihi, Domine: tolle animam meam: neque enim melior sum quam patres mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Projecitque se, et obdormivit in umbra juniperi: et ecce angelus Domini tetigit eum, et dixit illi: Surge, et comede.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Respexit, et ecce ad caput suum subcinericius panis, et vas aquæ: comedit ergo, et bibit, et rursum obdormivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Reversusque est angelus Domini secundo, et tetigit eum, dixitque illi: Surge, comede: grandis enim tibi restat via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Qui cum surrexisset, comedit et bibit, et ambulavit in fortitudine cibi illius quadraginta diebus et quadraginta noctibus usque ad montem Dei Horeb.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Cumque venisset illuc, mansit in spelunca: et ecce sermo Domini ad eum, dixitque illi: Quid hic agis, Elia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'At ille respondit: Zelo zelatus sum pro Domino Deo exercituum, quia dereliquerunt pactum tuum filii Israël: altaria tua destruxerunt, prophetas tuos occiderunt gladio, derelictus sum ego solus, et quærunt animam meam ut auferant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Et ait ei: Egredere, et sta in monte coram Domino: et ecce Dominus transit. Et spiritus grandis et fortis subvertens montes, et conterens petras, ante Dominum: non in spiritu Dominus. Et post spiritum commotio: non in commotione Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Et post commotionem ignis: non in igne Dominus. Et post ignem sibilus auræ tenuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Quod cum audisset Elias, operuit vultum suum pallio, et egressus stetit in ostio speluncæ. Et ecce vox ad eum dicens: Quid hic agis, Elia? Et ille respondit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Zelo zelatus sum pro Domino Deo exercituum, quia dereliquerunt pactum tuum filii Israël: altaria tua destruxerunt, prophetas tuos occiderunt gladio, derelictus sum ego solus, et quærunt animam meam ut auferant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Et ait Dominus ad eum: Vade, et revertere in viam tuam per desertum in Damascum: cumque perveneris illuc, unges Hazaël regem super Syriam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'et Jehu filium Namsi unges regem super Israël: Eliseum autem filium Saphat, qui est de Abelmehula, unges prophetam pro te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Et erit: quicumque fugerit gladium Hazaël, occidet eum Jehu: et quicumque fugerit gladium Jehu, interficiet eum Eliseus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Et derelinquam mihi in Israël septem millia virorum, quorum genua non sunt incurvata ante Baal, et omne os quod non adoravit eum osculans manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Profectus ergo inde Elias, reperit Eliseum filium Saphat, arantem in duodecim jugis boum. Et ipse in duodecim jugis boum arantibus unus erat: cumque venisset Elias ad eum, misit pallium suum super illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Qui statim relictis bobus cucurrit post Eliam, et ait: Osculer, oro, patrem meum, et matrem meam, et sic sequar te. Dixitque ei: Vade, et revertere: quod enim meum erat, feci tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Reversus autem ab eo, tulit par boum, et mactavit illud, et in aratro boum coxit carnes, et dedit populo, et comederunt: consurgensque abiit, et secutus est Eliam, et ministrabat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Porro Benadad rex Syriæ congregavit omnem exercitum suum, et triginta duos reges secum, et equos, et currus: et ascendens pugnabat contra Samariam, et obsidebat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Mittensque nuntios ad Achab regem Israël in civitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'ait: Hæc dicit Benadad: Argentum tuum, et aurum tuum meum est: et uxores tuæ, et filii tui optimi, mei sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Responditque rex Israël: Juxta verbum tuum, domine mi rex, tuus sum ego, et omnia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Revertentesque nuntii, dixerunt: Hæc dicit Benadad, qui misit nos ad te: Argentum tuum, et aurum tuum, et uxores tuas, et filios tuos, dabis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Cras igitur hac eadem hora mittam servos meos ad te, et scrutabuntur domum tuam, et domum servorum tuorum: et omne quod eis placuerit, ponent in manibus suis, et auferent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Vocavit autem rex Israël omnes seniores terræ, et ait: Animadvertite, et videte quoniam insidietur nobis: misit enim ad me pro uxoribus meis, et filiis, et pro argento et auro: et non abnui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Dixeruntque omnes majores natu, et universus populus, ad eum: Non audias, neque acquiescas illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Respondit itaque nuntiis Benadad: Dicite domino meo regi: Omnia propter quæ misisti ad me servum tuum in initio, faciam: hanc autem rem facere non possum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Reversique nuntii retulerunt ei. Qui remisit, et ait: Hæc faciant mihi dii, et hæc addant, si suffecerit pulvis Samariæ pugillis omnis populi qui sequitur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Et respondens rex Israël, ait: Dicite ei: Ne glorietur, accinctus æque ut discinctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Factum est autem cum audisset Benadad verbum istud, bibebat ipse et reges in umbraculis: et ait servis suis: Circumdate civitatem. Et circumdederunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Et ecce propheta unus accedens ad Achab regem Israël, ait ei: Hæc dicit Dominus: Certe vidisti omnem multitudinem hanc nimiam? ecce ego tradam eam in manu tua hodie, ut scias quia ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Et ait Achab: Per quem? Dixitque ei: Hæc dicit Dominus: Per pedissequos principum provinciarum. Et ait: Quis incipiet præliari? Et ille dixit: Tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Recensuit ergo pueros principum provinciarum, et reperit numerum ducentorum triginta duorum: et recensuit post eos populum, omnes filios Israël, septem millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Et egressi sunt meridie. Benadad autem bibebat temulentus in umbraculo suo, et reges triginta duo cum eo, qui ad auxilium ejus venerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Egressi sunt autem pueri principum provinciarum in prima fronte. Misit itaque Benadad: qui nuntiaverunt ei, dicentes: Viri egressi sunt de Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Et ille ait: Sive pro pace veniunt, apprehendite eos vivos: sive ut prælientur, vivos eos capite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Egressi sunt ergo pueri principum provinciarum, ac reliquus exercitus sequebatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'et percussit unusquisque virum qui contra se veniebat: fugeruntque Syri, et persecutus est eos Israël. Fugit quoque Benadad rex Syriæ in equo cum equitibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Necnon egressus rex Israël percussit equos et currus, et percussit Syriam plaga magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Accedens autem propheta ad regem Israël, dixit ei: Vade, et confortare, et scito, et vide quid facias: sequenti enim anno rex Syriæ ascendet contra te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Servi vero regis Syriæ dixerunt ei: Dii montium sunt dii eorum, ideo superaverunt nos: sed melius est ut pugnemus contra eos in campestribus, et obtinebimus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tu ergo verbum hoc fac: amove reges singulos ab exercitu tuo, et pone principes pro eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'et instaura numerum militum qui ceciderunt de tuis, et equos secundum equos pristinos, et currus secundum currus quos ante habuisti: et pugnabimus contra eos in campestribus, et videbis quod obtinebimus eos. Credidit consilio eorum, et fecit ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Igitur postquam annus transierat, recensuit Benadad Syros, et ascendit in Aphec ut pugnaret contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Porro filii Israël recensiti sunt, et acceptis cibariis profecti ex adverso, castraque metati sunt contra eos, quasi duo parvi greges caprarum: Syri autem repleverunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, '(Et accedens unus vir Dei, dixit ad regem Israël: Hæc dicit Dominus: Quia dixerunt Syri: Deus montium est Dominus, et non est Deus vallium: dabo omnem multitudinem hanc grandem in manu tua, et scietis quia ego sum Dominus.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Dirigebantque septem diebus ex adverso hi atque illi acies, septima autem die commissum est bellum: percusseruntque filii Israël de Syris centum millia peditum in die una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Fugerunt autem qui remanserant in Aphec, in civitatem: et cecidit murus super viginti septem millia hominum qui remanserant. Porro Benadad fugiens ingressus est civitatem, in cubiculum quod erat intra cubiculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Dixeruntque ei servi sui: Ecce, audivimus quod reges domus Israël clementes sint: ponamus itaque saccos in lumbis nostris, et funiculos in capitibus nostris, et egrediamur ad regem Israël: forsitan salvabit animas nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Accinxerunt saccis lumbos suos, et posuerunt funiculos in capitibus suis, veneruntque ad regem Israël, et dixerunt ei: Servus tuus Benadad dicit: Vivat, oro te, anima mea. Et ille ait: Si adhuc vivit, frater meus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Quod acceperunt viri pro omine: et festinantes rapuerunt verbum ex ore ejus, atque dixerunt: Frater tuus Benadad. Et dixit eis: Ite, et adducite eum ad me. Egressus est ergo ad eum Benadad, et levavit eum in currum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Qui dixit ei: Civitates quas tulit pater meus a patre tuo, reddam: et plateas fac tibi in Damasco, sicut fecit pater meus in Samaria, et ego fœderatus recedam a te. Pepigit ergo fœdus, et dimisit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Tunc vir quidam de filiis prophetarum dixit ad socium suum in sermone Domini: Percute me. At ille noluit percutere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Cui ait: Quia noluisti audire vocem Domini, ecce recedes a me, et percutiet te leo. Cumque paululum recessisset ab eo, invenit eum leo, atque percussit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Sed et alterum inveniens virum, dixit ad eum: Percute me. Qui percussit eum, et vulneravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Abiit ergo propheta, et occurrit regi in via, et mutavit aspersione pulveris os et oculos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Cumque rex transisset, clamavit ad regem, et ait: Servus tuus egressus est ad præliandum cominus: cumque fugisset vir unus, adduxit eum quidam ad me, et ait: Custodi virum istum: qui si lapsus fuerit, erit anima tua pro anima ejus, aut talentum argenti appendes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Dum autem ego turbatus huc illucque me verterem, subito non comparuit. Et ait rex Israël ad eum: Hoc est judicium tuum, quod ipse decrevisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'At ille statim abstersit pulverem de facie sua, et cognovit eum rex Israël, quod esset de prophetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Qui ait ad eum: Hæc dicit Dominus: Quia dimisisti virum dignum morte de manu tua, erit anima tua pro anima ejus, et populus tuus pro populo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Reversus est igitur rex Israël in domum suam, audire contemnens, et furibundus venit in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Post verba autem hæc, tempore illo vinea erat Naboth Jezrahelitæ, quæ erat in Jezrahel, juxta palatium Achab regis Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Locutus est ergo Achab ad Naboth, dicens: Da mihi vineam tuam, ut faciam mihi hortum olerum, quia vicina est, et prope domum meam: daboque tibi pro ea vineam meliorem, aut si commodius tibi putas, argenti pretium, quanto digna est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Cui respondit Naboth: Propitius sit mihi Dominus, ne dem hæreditatem patrum meorum tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Venit ergo Achab in domum suam indignans, et frendens super verbo quod locutus fuerat ad eum Naboth Jezrahelites, dicens: Non dabo tibi hæreditatem patrum meorum. Et projiciens se in lectulum suum, avertit faciem suam ad parietem, et non comedit panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Ingressa est autem ad eum Jezabel uxor sua, dixitque ei: Quid est hoc, unde anima tua contristata est? et quare non comedis panem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Qui respondit ei: Locutus sum Naboth Jezrahelitæ, et dixi ei: Da mihi vineam tuam, accepta pecunia: aut, si tibi placet, dabo tibi vineam meliorem pro ea. Et ille ait: Non dabo tibi vineam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Dixit ergo ad eum Jezabel uxor ejus: Grandis auctoritatis es, et bene regis regnum Israël. Surge, et comede panem, et æquo animo esto: ego dabo tibi vineam Naboth Jezrahelitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Scripsit itaque litteras ex nomine Achab, et signavit eas annulo ejus, et misit ad majores natu, et optimates, qui erant in civitate ejus, et habitabant cum Naboth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Litterarum autem hæc erat sententia: Prædicate jejunium, et sedere facite Naboth inter primos populi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'et submittite duos viros filios Belial contra eum, et falsum testimonium dicant: Benedixit Deum et regem: et educite eum, et lapidate, sicque moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Fecerunt ergo cives ejus majores natu et optimates, qui habitabant cum eo in urbe, sicut præceperat eis Jezabel, et sicut scriptum erat in litteris quas miserat ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'prædicaverunt jejunium, et sedere fecerunt Naboth inter primos populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Et adductis duobus viris filiis diaboli, fecerunt eos sedere contra eum: at illi, scilicet ut viri diabolici, dixerunt contra eum testimonium coram multitudine: Benedixit Naboth Deum et regem: quam ob rem eduxerunt eum extra civitatem, et lapidibus interfecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Miseruntque ad Jezabel, dicentes: Lapidatus est Naboth, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Factum est autem, cum audisset Jezabel lapidatum Naboth et mortuum, locuta est ad Achab: Surge, et posside vineam Naboth Jezrahelitæ, qui noluit tibi acquiescere, et dare eam accepta pecunia: non enim vivit Naboth, sed mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Quod cum audisset Achab, mortuum videlicet Naboth, surrexit, et descendebat in vineam Naboth Jezrahelitæ, ut possideret eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Factus est igitur sermo Domini ad Eliam Thesbiten, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Surge, et descende in occursum Achab regis Israël, qui est in Samaria: ecce ad vineam Naboth descendit, ut possideat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Et loqueris ad eum, dicens: Hæc dicit Dominus: Occidisti, insuper et possedisti. Et post hæc addes: Hæc dicit Dominus: In loco hoc, in quo linxerunt canes sanguinem Naboth, lambent quoque sanguinem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et ait Achab ad Eliam: Num invenisti me inimicum tibi? Qui dixit: Inveni, eo quod venundatus sis, ut faceres malum in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Ecce ego inducam super te malum, et demetam posteriora tua, et interficiam de Achab mingentem ad parietem, et clausum et ultimum in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Et dabo domum tuam sicut domum Jeroboam filii Nabat, et sicut domum Baasa filii Ahia: quia egisti ut me ad iracundiam provocares, et peccare fecisti Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Sed et de Jezabel locutus est Dominus, dicens: Canes comedent Jezabel in agro Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Si mortuus fuerit Achab in civitate, comedent eum canes: si autem mortuus fuerit in agro, comedent eum volucres cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Igitur non fuit alter talis sicut Achab, qui venundatus est ut faceret malum in conspectu Domini: concitavit enim eum Jezabel uxor sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'et abominabilis factus est, in tantum ut sequeretur idola quæ fecerant Amorrhæi, quos consumpsit Dominus a facie filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Itaque cum audisset Achab sermones istos, scidit vestimenta sua, et operuit cilicio carnem suam, jejunavitque et dormivit in sacco, et ambulavit demisso capite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Et factus est sermo Domini ad Eliam Thesbiten, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Nonne vidisti humiliatum Achab coram me? quia igitur humiliatus est mei causa, non inducam malum in diebus ejus, sed in diebus filii sui inferam malum domui ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Transierunt igitur tres anni absque bello inter Syriam et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'In anno autem tertio, descendit Josaphat rex Juda ad regem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, '(Dixitque rex Israël ad servos suos: Ignoratis quod nostra sit Ramoth Galaad, et negligimus tollere eam de manu regis Syriæ?)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Et ait ad Josaphat: Veniesne mecum ad præliandum in Ramoth Galaad?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Dixitque Josaphat ad regem Israël: Sicut ego sum, ita et tu: populus meus et populus tuus unum sunt: et equites mei, equites tui. Dixitque Josaphat ad regem Israël: Quære, oro te, hodie sermonem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Congregavit ergo rex Israël prophetas, quadringentos circiter viros, et ait ad eos: Ire debeo in Ramoth Galaad ad bellandum, an quiescere? Qui responderunt: Ascende, et dabit eam Dominus in manu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Dixit autem Josaphat: Non est hic propheta Domini quispiam, ut interrogemus per eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Et ait rex Israël ad Josaphat: Remansit vir unus per quem possumus interrogare Dominum: sed ego odi eum, quia non prophetat mihi bonum, sed malum: Michæas filius Jemla. Cui Josaphat ait: Ne loquaris ita, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Vocavit ergo rex Israël eunuchum quemdam, et dixit ei: Festina adducere Michæam filium Jemla.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Rex autem Israël, et Josaphat rex Juda, sedebant unusquisque in solio suo, vestiti cultu regio, in area juxta ostium portæ Samariæ: et universi prophetæ prophetabant in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Fecit quoque sibi Sedecias filius Chanaana cornua ferrea, et ait: Hæc dicit Dominus: His ventilabis Syriam, donec deleas eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Omnesque prophetæ similiter prophetabant, dicentes: Ascende in Ramoth Galaad, et vade prospere, et tradet Dominus in manus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Nuntius vero qui ierat ut vocaret Michæam, locutus est ad eum, dicens: Ecce sermones prophetarum ore uno regi bona prædicant: sit ergo sermo tuus similis eorum, et loquere bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Cui Michæas ait: Vivit Dominus, quia quodcumque dixerit mihi Dominus, hoc loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Venit itaque ad regem, et ait illi rex: Michæa, ire debemus in Ramoth Galaad ad præliandum, an cessare? Cui ille respondit: Ascende, et vade prospere, et tradet eam Dominus in manus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Dixit autem rex ad eum: Iterum atque iterum adjuro te, ut non loquaris mihi nisi quod verum est, in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Et ille ait: Vidi cunctum Israël dispersum in montibus, quasi oves non habentes pastorem. Et ait Dominus: Non habent isti dominum: revertatur unusquisque in domum suam in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, '(Dixit ergo rex Israël ad Josaphat: Numquid non dixi tibi, quia non prophetat mihi bonum, sed semper malum?)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Ille vero addens, ait: Propterea audi sermonem Domini: vidi Dominum sedentem super solium suum, et omnem exercitum cæli assistentem ei a dextris et a sinistris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'et ait Dominus: Quis decipiet Achab regem Israël, ut ascendat, et cadat in Ramoth Galaad? Et dixit unus verba hujuscemodi, et alius aliter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Egressus est autem spiritus, et stetit coram Domino, et ait: Ego decipiam illum. Cui locutus est Dominus: In quo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et ille ait: Egrediar, et ero spiritus mendax in ore omnium prophetarum ejus. Et dixit Dominus: Decipies, et prævalebis: egredere, et fac ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Nunc igitur ecce dedit Dominus spiritum mendacii in ore omnium prophetarum tuorum, qui hic sunt, et Dominus locutus est contra te malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Accessit autem Sedecias filius Chanaana, et percussit Michæam in maxillam, et dixit: Mene ergo dimisit spiritus Domini, et locutus est tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Et ait Michæas: Visurus es in die illa quando ingredieris cubiculum intra cubiculum ut abscondaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Et ait rex Israël: Tollite Michæam, et maneat apud Amon principem civitatis, et apud Joas filium Amelech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'et dicite eis: Hæc dicit rex: Mittite virum istum in carcerem, et sustentate eum pane tribulationis, et aqua angustiæ, donec revertar in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Dixitque Michæas: Si reversus fueris in pace, non est locutus in me Dominus. Et ait: Audite, populi omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Ascendit itaque rex Israël, et Josaphat rex Juda, in Ramoth Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Dixit itaque rex Israël ad Josaphat: Sume arma, et ingredere prælium, et induere vestibus tuis. Porro rex Israël mutavit habitum suum, et ingressus est bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Rex autem Syriæ præceperat principibus curruum triginta duobus, dicens: Non pugnabitis contra minorem et majorem quempiam, nisi contra regem Israël solum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Cum ergo vidissent principes curruum Josaphat, suspicati sunt quod ipse esset rex Israël, et impetu facto pugnabant contra eum: et exclamavit Josaphat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Intellexeruntque principes curruum quod non esset rex Israël, et cessaverunt ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Vir autem quidam tetendit arcum, in incertum sagittam dirigens, et casu percussit regem Israël inter pulmonem et stomachum. At ille dixit aurigæ suo: Verte manum tuam, et ejice me de exercitu, quia graviter vulneratus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Commissum est ergo prælium in die illa, et rex Israël stabat in curru suo contra Syros, et mortuus est vespere: fluebat autem sanguis plagæ in sinum currus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'et præco insonuit in universo exercitu antequam sol occumberet, dicens: Unusquisque revertatur in civitatem, et in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Mortuus est autem rex, et perlatus est in Samariam: sepelieruntque regem in Samaria,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'et laverunt currum ejus in piscina Samariæ: et linxerunt canes sanguinem ejus, et habenas laverunt, juxta verbum Domini quod locutus fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Reliqua autem sermonum Achab, et universa quæ fecit, et domus eburnea quam ædificavit, cunctarumque urbium quas exstruxit, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Dormivit ergo Achab cum patribus suis, et regnavit Ochozias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Josaphat vero filius Asa regnare cœperat super Judam anno quarto Achab regis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Triginta quinque annorum erat cum regnare cœpisset, et viginti quinque annis regnavit in Jerusalem: nomen matris ejus Azuba filia Salai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et ambulavit in omni via Asa patris sui, et non declinavit ex ea: fecitque quod rectum erat in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Verumtamen excelsa non abstulit: adhuc enim populus sacrificabat, et adolebat incensum in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Pacemque habuit Josaphat cum rege Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Reliqua autem verborum Josaphat, et opera ejus quæ gessit, et prælia, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Sed et reliquias effeminatorum qui remanserant in diebus Asa patris ejus, abstulit de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Nec erat tunc rex constitutus in Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Rex vero Josaphat fecerat classes in mari, quæ navigarent in Ophir propter aurum: et ire non potuerunt, quia confractæ sunt in Asiongaber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Tunc ait Ochozias filius Achab ad Josaphat: Vadant servi mei cum servis tuis in navibus. Et noluit Josaphat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Dormivitque Josaphat cum patribus suis, et sepultus est cum eis in civitate David patris sui: regnavitque Joram filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ochozias autem filius Achab regnare cœperat super Israël in Samaria, anno septimodecimo Josaphat regis Juda: regnavitque super Israël duobus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Et fecit malum in conspectu Domini, et ambulavit in via patris sui et matris suæ, et in via Jeroboam filii Nabat, qui peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Servivit quoque Baal, et adoravit eum, et irritavit Dominum Deum Israël, juxta omnia quæ fecerat pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Prævaricatus est autem Moab in Israël, postquam mortuus est Achab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ceciditque Ochozias per cancellos cœnaculi sui, quod habebat in Samaria, et ægrotavit: misitque nuntios, dicens ad eos: Ite, consulite Beelzebub deum Accaron, utrum vivere queam de infirmitate mea hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Angelus autem Domini locutus est ad Eliam Thesbiten, dicens: Surge, et ascende in occursum nuntiorum regis Samariæ, et dices ad eos: Numquid non est Deus in Israël, ut eatis ad consulendum Beelzebub deum Accaron?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Quam ob rem hæc dicit Dominus: De lectulo, super quem ascendisti, non descendes, sed morte morieris. Et abiit Elias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Reversique sunt nuntii ad Ochoziam. Qui dixit eis: Quare reversi estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'At illi responderunt ei: Vir occurrit nobis, et dixit ad nos: Ite, et revertimini ad regem qui misit vos, et dicetis ei: Hæc dicit Dominus: Numquid quia non erat Deus in Israël, mittis ut consulatur Beelzebub deus Accaron? idcirco de lectulo, super quem ascendisti, non descendes, sed morte morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Qui dixit eis: Cujus figuræ et habitus est vir ille, qui occurrit vobis, et locutus est verba hæc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'At illi dixerunt: Vir pilosus, et zona pellicea accinctus renibus. Qui ait: Elias Thesbites est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Misitque ad eum quinquagenarium principem, et quinquaginta qui erant sub eo. Qui ascendit ad eum: sedentique in vertice montis, ait: Homo Dei, rex præcepit ut descendas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Respondensque Elias, dixit quinquagenario: Si homo Dei sum, descendat ignis de cælo, et devoret te, et quinquaginta tuos. Descendit itaque ignis de cælo, et devoravit eum, et quinquaginta qui erant cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Rursumque misit ad eum principem quinquagenarium alterum, et quinquaginta cum eo. Qui locutus est illi: Homo Dei, hæc dicit rex: Festina, descende.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Respondens Elias, ait: Si homo Dei ego sum, descendat ignis de cælo, et devoret te, et quinquaginta tuos. Descendit ergo ignis de cælo, et devoravit illum, et quinquaginta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Iterum misit principem quinquagenarium tertium, et quinquaginta qui erant cum eo. Qui cum venisset, curvavit genua contra Eliam, et precatus est eum, et ait: Homo Dei, noli despicere animam meam, et animas servorum tuorum qui mecum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Ecce descendit ignis de cælo, et devoravit duos principes quinquagenarios primos, et quinquagenos qui cum eis erant: sed nunc obsecro ut miserearis animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Locutus est autem angelus Domini ad Eliam, dicens: Descende cum eo: ne timeas. Surrexit igitur, et descendit cum eo ad regem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'et locutus est ei: Hæc dicit Dominus: Quia misisti nuntios ad consulendum Beelzebub deum Accaron, quasi non esset Deus in Israël a quo posses interrogare sermonem, ideo de lectulo super quem ascendisti, non descendes, sed morte morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Mortuus est ergo juxta sermonem Domini quem locutus est Elias, et regnavit Joram frater ejus pro eo, anno secundo Joram filii Josaphat regis Judæ: non enim habebat filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Reliqua autem verborum Ochoziæ quæ operatus est, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Factum est autem cum levare vellet Dominus Eliam per turbinem in cælum, ibant Elias et Eliseus de Galgalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Dixitque Elias ad Eliseum: Sede hic, quia Dominus misit me usque in Bethel. Cui ait Eliseus: Vivit Dominus, et vivit anima tua, quia non derelinquam te. Cumque descendissent Bethel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'egressi sunt filii prophetarum qui erant in Bethel, ad Eliseum, et dixerunt ei: Numquid nosti quia hodie Dominus tollet dominum tuum a te? Qui respondit: Et ego novi: silete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Dixit autem Elias ad Eliseum: Sede hic, quia Dominus misit me in Jericho. Et ille ait: Vivit Dominus, et vivit anima tua, quia non derelinquam te. Cumque venissent Jericho,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'accesserunt filii prophetarum qui erant in Jericho, ad Eliseum, et dixerunt ei: Numquid nosti quia Dominus hodie tollet dominum tuum a te? Et ait: Et ego novi: silete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Dixit autem ei Elias: Sede hic, quia Dominus misit me usque ad Jordanem. Qui ait: Vivit Dominus, et vivit anima tua, quia non derelinquam te. Ierunt igitur ambo pariter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'et quinquaginta viri de filiis prophetarum secuti sunt eos, qui et steterunt e contra, longe: illi autem ambo stabant super Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tulitque Elias pallium suum, et involvit illud, et percussit aquas: quæ divisæ sunt in utramque partem, et transierunt ambo per siccum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Cumque transissent, Elias dixit ad Eliseum: Postula quod vis ut faciam tibi, antequam tollar a te. Dixitque Eliseus: Obsecro ut fiat in me duplex spiritus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Qui respondit: Rem difficilem postulasti: attamen si videris me quando tollar a te, erit tibi quod petisti: si autem non videris, non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Cumque pergerent, et incedentes sermocinarentur, ecce currus igneus, et equi ignei diviserunt utrumque: et ascendit Elias per turbinem in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Eliseus autem videbat, et clamabat: Pater mi, pater mi, currus Israël, et auriga ejus. Et non vidit eum amplius: apprehenditque vestimenta sua, et scidit illa in duas partes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Et levavit pallium Eliæ, quod ceciderat ei: reversusque stetit super ripam Jordanis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'et pallio Eliæ, quod ceciderat ei, percussit aquas, et non sunt divisæ: et dixit: Ubi est Deus Eliæ etiam nunc? Percussitque aquas, et divisæ sunt huc atque illuc, et transiit Eliseus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Videntes autem filii prophetarum qui erant in Jericho e contra, dixerunt: Requievit spiritus Eliæ super Eliseum. Et venientes in occursum ejus, adoraverunt eum proni in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'dixeruntque illi: Ecce cum servis tuis sunt quinquaginta viri fortes qui possunt ire, et quærere dominum tuum, ne forte tulerit eum spiritus Domini, et projecerit eum in unum montium, aut in unam vallium. Qui ait: Nolite mittere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Coëgeruntque eum donec acquiesceret, et diceret: Mittite. Et miserunt quinquaginta viros: qui cum quæsissent tribus diebus, non invenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Et reversi sunt ad eum: at ille habitabat in Jericho, et dixit eis: Numquid non dixi vobis: Nolite mittere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Dixerunt quoque viri civitatis ad Eliseum: Ecce habitatio civitatis hujus optima est, sicut tu ipse, domine, perspicis: sed aquæ pessimæ sunt, et terra sterilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'At ille ait: Afferte mihi vas novum, et mittite in illud sal. Quod cum attulissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'egressus ad fontem aquarum misit in illum sal, et ait: Hæc dicit Dominus: Sanavi aquas has, et non erit ultra in eis mors, neque sterilitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Sanatæ sunt ergo aquæ usque in diem hanc, juxta verbum Elisei quod locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Ascendit autem inde in Bethel: cumque ascenderet per viam, pueri parvi egressi sunt de civitate, et illudebant ei, dicentes: Ascende calve, ascende calve.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Qui cum respexisset, vidit eos, et maledixit eis in nomine Domini: egressique sunt duo ursi de saltu, et laceraverunt ex eis quadraginta duos pueros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Abiit autem inde in montem Carmeli, et inde reversus est in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram vero filius Achab regnavit super Israël in Samaria anno decimooctavo Josaphat regis Judæ: regnavitque duodecim annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et fecit malum coram Domino, sed non sicut pater suus et mater: tulit enim statuas Baal quas fecerat pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Verumtamen in peccatis Jeroboam filii Nabat, qui peccare fecit Israël, adhæsit, nec recessit ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Porro Mesa rex Moab nutriebat pecora multa, et solvebat regi Israël centum millia agnorum, et centum millia arietum cum velleribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Cumque mortuus fuisset Achab, prævaricatus est fœdus quod habebat cum rege Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Egressus est igitur rex Joram in die illa de Samaria, et recensuit universum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Misitque ad Josaphat regem Juda, dicens: Rex Moab recessit a me: veni mecum contra eum ad prælium. Qui respondit: Ascendam: qui meus est, tuus est: populus meus, populus tuus, et equi mei, equi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Dixitque: Per quam viam ascendemus? At ille respondit: Per desertum Idumææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Perrexerunt igitur rex Israël, et rex Juda, et rex Edom, et circuierunt per viam septem dierum, nec erat aqua exercitui et jumentis quæ sequebantur eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Dixitque rex Israël: Heu! heu! heu! congregavit nos Dominus tres reges ut traderet in manus Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et ait Josaphat: Estne hic propheta Domini, ut deprecemur Dominum per eum? Et respondit unus de servis regis Israël: Est hic Eliseus filius Saphat, qui fundebat aquam super manus Eliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Et ait Josaphat: Est apud eum sermo Domini. Descenditque ad eum rex Israël, et Josaphat rex Juda, et rex Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Dixit autem Eliseus ad regem Israël: Quid mihi et tibi est? vade ad prophetas patris tui et matris tuæ. Et ait illi rex Israël: Quare congregavit Dominus tres reges hos ut traderet eos in manus Moab?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Dixitque ad eum Eliseus: Vivit Dominus exercituum, in cujus conspectu sto, quod si non vultum Josaphat regis Judæ erubescerem, non attendissem quidem te, nec respexissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Nunc autem adducite mihi psaltem. Cumque caneret psaltes, facta est super eum manus Domini, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Hæc dicit Dominus: Facite alveum torrentis hujus fossas et fossas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Hæc enim dicit Dominus: Non videbitis ventum, neque pluviam: et alveus iste replebitur aquis, et bibetis vos, et familiæ vestræ, et jumenta vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Parumque est hoc in conspectu Domini: insuper tradet etiam Moab in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Et percutietis omnem civitatem munitam, et omnem urbem electam, et universum lignum fructiferum succidetis, cunctosque fontes aquarum obturabitis, et omnem agrum egregium operietis lapidibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Factum est igitur mane, quando sacrificium offerri solet, et ecce aquæ veniebant per viam Edom, et repleta est terra aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Universi autem Moabitæ audientes quod ascendissent reges ut pugnarent adversum eos, convocaverunt omnes qui accincti erant balteo desuper, et steterunt in terminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Primoque mane surgentes, et orto jam sole ex adverso aquarum, viderunt Moabitæ e contra aquas rubras quasi sanguinem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'dixeruntque: Sanguis gladii est: pugnaverunt reges contra se, et cæsi sunt mutuo: nunc perge ad prædam, Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Perrexeruntque in castra Israël: porro consurgens Israël, percussit Moab: at illi fugerunt coram eis. Venerunt igitur qui vicerant, et percusserunt Moab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'et civitates destruxerunt: et omnem agrum optimum, mittentes singuli lapides, repleverunt: et universos fontes aquarum obturaverunt: et omnia ligna fructifera succiderunt, ita ut muri tantum fictiles remanerent: et circumdata est civitas a fundibulariis, et magna ex parte percussa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Quod cum vidisset rex Moab, prævaluisse scilicet hostes, tulit secum septingentos viros educentes gladium, ut irrumperent ad regem Edom: et non potuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Arripiensque filium suum primogenitum, qui regnaturus erat pro eo, obtulit holocaustum super murum: et facta est indignatio magna in Israël, statimque recesserunt ab eo, et reversi sunt in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Mulier autem quædam de uxoribus prophetarum clamabat ad Eliseum, dicens: Servus tuus vir meus mortuus est, et tu nosti quia servus tuus fuit timens Dominum: et ecce creditor venit ut tollat duos filios meos ad serviendum sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Cui dixit Eliseus: Quid vis ut faciam tibi? dic mihi, quid habes in domo tua? At illa respondit: Non habeo ancilla tua quidquam in domo mea, nisi parum olei quo ungar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Cui ait: Vade, pete mutuo ab omnibus vicinis tuis vasa vacua non pauca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'et ingredere, et claude ostium tuum cum intrinsecus fueris tu, et filii tui: et mitte inde in omnia vasa hæc, et cum plena fuerint, tolles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Ivit itaque mulier, et clausit ostium super se, et super filios suos: illi offerebant vasa, et illa infundebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Cumque plena fuissent vasa, dixit ad filium suum: Affer mihi adhuc vas. Et ille respondit: Non habeo. Stetitque oleum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Venit autem illa, et indicavit homini Dei. Et ille: Vade, inquit, vende oleum, et redde creditori tuo: tu autem, et filii tui vivite de reliquo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Facta est autem quædam dies, et transibat Eliseus per Sunam: erat autem ibi mulier magna, quæ tenuit eum ut comederet panem: cumque frequenter inde transiret, divertebat ad eam ut comederet panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Quæ dixit ad virum suum: Animadverto quod vir Dei sanctus est iste, qui transit per nos frequenter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Faciamus ergo ei cœnaculum parvum, et ponamus ei in eo lectulum, et mensam, et sellam, et candelabrum, ut cum venerit ad nos, maneat ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Facta est ergo dies quædam, et veniens divertit in cœnaculum, et requievit ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Dixitque ad Giezi puerum suum: Voca Sunamitidem istam. Qui cum vocasset eam, et illa stetisset coram eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'dixit ad puerum suum: Loquere ad eam: Ecce, sedule in omnibus ministrasti nobis: quid vis ut faciam tibi? numquid habes negotium, et vis ut loquar regi, sive principi militiæ? Quæ respondit: In medio populi mei habito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Et ait: Quid ergo vult ut faciam ei? Dixitque Giezi: Ne quæras: filium enim non habet, et vir ejus senex est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Præcepit itaque ut vocaret eam: quæ cum vocata fuisset, et stetisset ante ostium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'dixit ad eam: In tempore isto, et in hac eadem hora, si vita comes fuerit, habebis in utero filium. At illa respondit: Noli quæso, domine mi vir Dei, noli mentiri ancillæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Et concepit mulier, et peperit filium in tempore, et in hora eadem, qua dixerat Eliseus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Crevit autem puer: et cum esset quædam dies, et egressus isset ad patrem suum, ad messores,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'ait patri suo: Caput meum doleo, caput meum doleo. At ille dixit puero: Tolle, et duc eum ad matrem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Qui cum tulisset, et duxisset eum ad matrem suam, posuit eum illa super genua sua usque ad meridiem, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ascendit autem, et collocavit eum super lectulum hominis Dei, et clausit ostium: et egressa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'vocavit virum suum, et ait: Mitte mecum, obsecro, unum de pueris, et asinam, ut excurram usque ad hominem Dei, et revertar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Qui ait illi: Quam ob causam vadis ad eum? hodie non sunt calendæ, neque sabbatum. Quæ respondit: Vadam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Stravitque asinam, et præcepit puero: Mina, et propera: ne mihi moram facias in eundo: et hoc age quod præcipio tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Profecta est igitur, et venit ad virum Dei in montem Carmeli: cumque vidisset eam vir Dei e contra, ait ad Giezi puerum suum: Ecce Sunamitis illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Vade ergo in occursum ejus, et dic ei: Recte ne agitur circa te, et circa virum tuum, et circa filium tuum? Quæ respondit: Recte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Cumque venisset ad virum Dei in montem, apprehendit pedes ejus: et accessit Giezi ut amoveret eam. Et ait homo Dei: Dimitte illam: anima enim ejus in amaritudine est, et Dominus celavit a me, et non indicavit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Quæ dixit illi: Numquid petivi filium a domino meo? numquid non dixi tibi: Ne illudas me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et ille ait ad Giezi: Accinge lumbos tuos, et tolle baculum meum in manu tua, et vade. Si occurrerit tibi homo, non salutes eum: et si salutaverit te quispiam, non respondeas illi: et pones baculum meum super faciem pueri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Porro mater pueri ait: Vivit Dominus, et vivit anima tua, non dimittam te. Surrexit ergo, et secutus est eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Giezi autem præcesserat ante eos, et posuerat baculum super faciem pueri, et non erat vox, neque sensus: reversusque est in occursum ejus, et nuntiavit ei, dicens: Non surrexit puer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Ingressus est ergo Eliseus domum, et ecce puer mortuus jacebat in lectulo ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'ingressusque clausit ostium super se et super puerum, et oravit ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Et ascendit, et incubuit super puerum: posuitque os suum super os ejus, et oculos suos super oculos ejus, et manus suas super manus ejus: et incurvavit se super eum, et calefacta est caro pueri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'At ille reversus, deambulavit in domo, semel huc atque illuc: et ascendit, et incubuit super eum: et oscitavit puer septies, aperuitque oculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'At ille vocavit Giezi, et dixit ei: Voca Sunamitidem hanc. Quæ vocata, ingressa est ad eum. Qui ait: Tolle filium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Venit illa, et corruit ad pedes ejus, et adoravit super terram: tulitque filium suum, et egressa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Et Eliseus reversus est in Galgala. Erat autem fames in terra, et filii prophetarum habitabant coram eo. Dixitque uni de pueris suis: Pone ollam grandem, et coque pulmentum filiis prophetarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Et egressus est unus in agrum ut colligeret herbas agrestes: invenitque quasi vitem silvestrem, et collegit ex ea colocynthidas agri, et implevit pallium suum, et reversus concidit in ollam pulmenti: nesciebat enim quid esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Infuderunt ergo sociis ut comederent: cumque gustassent de coctione, clamaverunt, dicentes: Mors in olla, vir Dei. Et non potuerunt comedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'At ille: Afferte, inquit, farinam. Cumque tulissent, misit in ollam, et ait: Infunde turbæ, ut comedant. Et non fuit amplius quidquam amaritudinis in olla.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Vir autem quidam venit de Baalsalisa deferens viro Dei panes primitiarum, viginti panes hordeaceos, et frumentum novum in pera sua. At ille dixit: Da populo, ut comedat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Responditque ei minister ejus: Quantum est hoc, ut apponam centum viris? Rursum ille ait: Da populo, ut comedat: hæc enim dicit Dominus: Comedent, et supererit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Posuit itaque coram eis: qui comederunt, et superfuit juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman princeps militiæ regis Syriæ erat vir magnus apud dominum suum, et honoratus: per illum enim dedit Dominus salutem Syriæ: erat autem vir fortis et dives, sed leprosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Porro de Syria egressi fuerant latrunculi, et captivam duxerant de terra Israël puellam parvulam, quæ erat in obsequio uxoris Naaman:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'quæ ait ad dominam suam: Utinam fuisset dominus meus ad prophetam qui est in Samaria, profecto curasset eum a lepra quam habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Ingressus est itaque Naaman ad dominum suum, et nuntiavit ei, dicens: Sic et sic locuta est puella de terra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Dixitque ei rex Syriæ: Vade, et mittam litteras ad regem Israël. Qui cum profectus esset, et tulisset secum decem talenta argenti, et sex millia aureos, et decem mutatoria vestimentorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'detulit litteras ad regem Israël in hæc verba: Cum acceperis epistolam hanc, scito quod miserim ad te Naaman servum meum, ut cures eum a lepra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Cumque legisset rex Israël litteras, scidit vestimenta sua, et ait: Numquid deus ego sum, ut occidere possim et vivificare, quia iste misit ad me ut curem hominem a lepra sua? animadvertite, et videte quod occasiones quærat adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Quod cum audisset Eliseus vir Dei, scidisse videlicet regem Israël vestimenta sua, misit ad eum, dicens: Quare scidisti vestimenta tua? veniat ad me, et sciat esse prophetam in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Venit ergo Naaman cum equis et curribus, et stetit ad ostium domus Elisei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'misitque ad eum Eliseus nuntium, dicens: Vade, et lavare septies in Jordane, et recipiet sanitatem caro tua, atque mundaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Iratus Naaman recedebat, dicens: Putabam quod egrederetur ad me, et stans invocaret nomen Domini Dei sui, et tangeret manu sua locum lepræ, et curaret me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Numquid non meliores sunt Abana et Pharphar fluvii Damasci, omnibus aquis Israël, ut laver in eis, et munder? Cum ergo vertisset se, et abiret indignans,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'accesserunt ad eum servi sui, et locuti sunt ei: Pater, etsi rem grandem dixisset tibi propheta, certe facere debueras: quanto magis quia nunc dixit tibi: Lavare, et mundaberis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Descendit, et lavit in Jordane septies juxta sermonem viri Dei: et restituta est caro ejus sicut caro pueri parvuli, et mundatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Reversusque ad virum Dei cum universo comitatu suo, venit, et stetit coram eo, et ait: Vere scio quod non sit alius deus in universa terra, nisi tantum in Israël. Obsecro itaque ut accipias benedictionem a servo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'At ille respondit: Vivit Dominus, ante quem sto, quia non accipiam. Cumque vim faceret, penitus non acquievit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Dixitque Naaman: Ut vis: sed, obsecro, concede mihi servo tuo ut tollam onus duorum burdonum de terra: non enim faciet ultra servus tuus holocaustum aut victimam diis alienis, nisi Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Hoc autem solum est, de quo depreceris Dominum pro servo tuo, quando ingredietur dominus meus templum Remmon ut adoret: et illo innitente super manum meam, si adoravero in templo Remmon, adorante eo in eodem loco, ut ignoscat mihi Dominus servo tuo pro hac re.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Qui dixit ei: Vade in pace. Abiit ergo ab eo electo terræ tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Dixitque Giezi puer viri Dei: Pepercit dominus meus Naaman Syro isti, ut non acciperet ab eo quæ attulit: vivit Dominus, quia curram post eum, et accipiam ab eo aliquid.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Et secutus est Giezi post tergum Naaman: quem cum vidisset ille currentem ad se, desiliit de curru in occursum ejus, et ait: Rectene sunt omnia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et ille ait: Recte. Dominus meus misit me ad te dicens: Modo venerunt ad me duo adolescentes de monte Ephraim, ex filiis prophetarum: da eis talentum argenti, et vestes mutatorias duplices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Dixitque Naaman: Melius est ut accipias duo talenta. Et coëgit eum, ligavitque duo talenta argenti in duobus saccis, et duplicia vestimenta, et imposuit duobus pueris suis, qui et portaverunt coram eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Cumque venisset jam vesperi, tulit de manu eorum, et reposuit in domo, dimisitque viros, et abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Ipse autem ingressus, stetit coram domino suo. Et dixit Eliseus: Unde venis, Giezi? Qui respondit: Non ivit servus tuus quoquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'At ille ait: Nonne cor meum in præsenti erat, quando reversus est homo de curru suo in occursum tui? nunc igitur accepisti argentum, et accepisti vestes ut emas oliveta, et vineas, et oves, et boves, et servos, et ancillas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Sed et lepra Naaman adhærebit tibi, et semini tuo usque in sempiternum. Et egressus est ab eo leprosus quasi nix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Dixerunt autem filii prophetarum ad Eliseum: Ecce locus in quo habitamus coram te, angustus est nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Eamus usque ad Jordanem, et tollant singuli de silva materias singulas, ut ædificemus nobis ibi locum ad habitandum. Qui dixit: Ite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Et ait unus ex illis: Veni ergo et tu cum servis tuis. Respondit: Ego veniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Et abiit cum eis. Cumque venissent ad Jordanem, cædebant ligna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Accidit autem ut cum unus materiam succidisset, caderet ferrum securis in aquam: exclamavitque ille, et ait: Heu! heu! heu! domine mi: et hoc ipsum mutuo acceperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Dixit autem homo Dei: Ubi cecidit? At ille monstravit ei locum. Præcidit ergo lignum, et misit illuc: natavitque ferrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'et ait: Tolle. Qui extendit manum, et tulit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Rex autem Syriæ pugnabat contra Israël, consiliumque iniit cum servis suis, dicens: In loco illo et illo ponamus insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Misit itaque vir Dei ad regem Israël, dicens: Cave ne transeas in locum illum: quia ibi Syri in insidiis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Misit itaque rex Israël ad locum quem dixerat ei vir Dei, et præoccupavit eum, et observavit se ibi non semel neque bis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Conturbatumque est cor regis Syriæ pro hac re: et convocatis servis suis, ait: Quare non indicatis mihi quis proditor mei sit apud regem Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Dixitque unus servorum ejus: Nequaquam, domine mi rex, sed Eliseus propheta qui est in Israël, indicat regi Israël omnia verba quæcumque locutus fueris in conclavi tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Dixitque eis: Ite, et videte ubi sit, ut mittam, et capiam eum. Annuntiaveruntque ei, dicentes: Ecce in Dothan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Misit ergo illuc equos et currus, et robur exercitus: qui cum venissent nocte, circumdederunt civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Consurgens autem diluculo minister viri Dei, egressus vidit exercitum in circuitu civitatis, et equos et currus: nuntiavitque ei, dicens: Heu! heu! heu! domine mi: quid faciemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'At ille respondit: Noli timere: plures enim nobiscum sunt, quam cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Cumque orasset Eliseus, ait: Domine, aperi oculos hujus, ut videat. Et aperuit Dominus oculos pueri, et vidit: et ecce mons plenus equorum et curruum igneorum in circuitu Elisei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Hostes vero descenderunt ad eum: porro Eliseus oravit ad Dominum, dicens: Percute, obsecro, gentem hanc cæcitate. Percussitque eos Dominus ne viderent, juxta verbum Elisei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Dixit autem ad eos Eliseus: Non est hæc via, neque ista est civitas: sequimini me, et ostendam vobis virum quem quæritis. Duxit ergo eos in Samariam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'cumque ingressi fuissent in Samariam, dixit Eliseus: Domine, aperi oculos istorum, ut videant. Aperuitque Dominus oculos eorum, et viderunt se esse in medio Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Dixitque rex Israël ad Eliseum, cum vidisset eos: Numquid percutiam eos, pater mi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'At ille ait: Non percuties: neque enim cepisti eos gladio et arcu tuo, ut percutias: sed pone panem et aquam coram eis, ut comedant et bibant, et vadant ad dominum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Appositaque est eis ciborum magna præparatio, et comederunt et biberunt, et dimisit eos, abieruntque ad dominum suum, et ultra non venerunt latrones Syriæ in terram Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Factum est autem post hæc, congregavit Benadad rex Syriæ universum exercitum suum, et ascendit, et obsidebat Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Factaque est fames magna in Samaria: et tamdiu obsessa est, donec venundaretur caput asini octoginta argenteis, et quarta pars cabi stercoris columbarum quinque argenteis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Cumque rex Israël transiret per murum, mulier quædam exclamavit ad eum, dicens: Salva me, domine mi rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Qui ait: Non te salvat Dominus: unde te possum salvare? de area, vel de torculari? Dixitque ad eam rex: Quid tibi vis? Quæ respondit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Mulier ista dixit mihi: Da filium tuum, ut comedamus eum hodie, et filium meum comedemus cras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Coximus ergo filium meum, et comedimus. Dixique ei die altera: Da filium tuum, ut comedamus eum. Quæ abscondit filium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Quod cum audisset rex, scidit vestimenta sua, et transibat per murum. Viditque omnis populus cilicium quo vestitus erat ad carnem intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Et ait rex: Hæc mihi faciat Deus, et hæc addat, si steterit caput Elisei filii Saphat super ipsum hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Eliseus autem sedebat in domo sua, et senes sedebant cum eo. Præmisit itaque virum: et antequam veniret nuntius ille, dixit ad senes: Numquid scitis quod miserit filius homicidæ hic, ut præcidatur caput meum? videte ergo: cum venerit nuntius, claudite ostium, et non sinatis eum introire: ecce enim sonitus pedum domini ejus post eum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Adhuc illo loquente eis, apparuit nuntius qui veniebat ad eum. Et ait: Ecce, tantum malum a Domino est: quid amplius expectabo a Domino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Dixit autem Eliseus: Audite verbum Domini: Hæc dicit Dominus: In tempore hoc cras modius similæ uno statere erit, et duo modii hordei statere uno, in porta Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Respondens unus de ducibus, super cujus manum rex incumbebat, homini Dei, ait: Si Dominus fecerit etiam cataractas in cælo, numquid poterit esse quod loqueris? Qui ait: Videbis oculis tuis, et inde non comedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Quatuor ergo viri erant leprosi juxta introitum portæ: qui dixerunt ad invicem: Quid hic esse volumus donec moriamur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'sive ingredi voluerimus civitatem, fame moriemur: sive manserimus hic, moriendum nobis est: venite ergo, et transfugiamus ad castra Syriæ: si pepercerint nobis, vivemus: si autem occidere voluerint, nihilominus moriemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Surrexerunt ergo vesperi, ut venirent ad castra Syriæ. Cumque venissent ad principium castrorum Syriæ, nullum ibidem repererunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Siquidem Dominus sonitum audiri fecerat in castris Syriæ, curruum, et equorum, et exercitus plurimi: dixeruntque ad invicem: Ecce mercede conduxit adversum nos rex Israël reges Hethæorum et \'gyptiorum, et venerunt super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Surrexerunt ergo, et fugerunt in tenebris, et dereliquerunt tentoria sua, et equos et asinos, in castris, fugeruntque animas tantum suas salvare cupientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Igitur cum venissent leprosi illi ad principium castrorum, ingressi sunt unum tabernaculum, et comederunt et biberunt: tuleruntque inde argentum, et aurum, et vestes, et abierunt, et absconderunt: et rursum reversi sunt ad aliud tabernaculum, et inde similiter auferentes absconderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Dixeruntque ad invicem: Non recte facimus: hæc enim dies boni nuntii est. Si tacuerimus et noluerimus nuntiare usque mane, sceleris arguemur: venite, eamus, et nuntiemus in aula regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Cumque venissent ad portam civitatis, narraverunt eis, dicentes: Ivimus ad castra Syriæ, et nullum ibidem reperimus hominem, nisi equos et asinos alligatos, et fixa tentoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Ierunt ergo portarii, et nuntiaverunt in palatio regis intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Qui surrexit nocte, et ait ad servos suos: Dico vobis quid fecerint nobis Syri: sciunt quia fame laboramus, et idcirco egressi sunt de castris, et latitant in agris, dicentes: Cum egressi fuerint de civitate, capiemus eos vivos, et tunc civitatem ingredi poterimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Respondit autem unus servorum ejus: Tollamus quinque equos qui remanserunt in urbe (quia ipsi tantum sunt in universa multitudine Israël, alii enim consumpti sunt), et mittentes, explorare poterimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Adduxerunt ergo duos equos, misitque rex in castra Syrorum, dicens: Ite, et videte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Qui abierunt post eos usque ad Jordanem: ecce autem omnis via plena erat vestibus et vasis quæ projecerant Syri cum turbarentur: reversique nuntii indicaverunt regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Et egressus populus diripuit castra Syriæ: factusque est modius similæ statere uno, et duo modii hordei statere uno, juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Porro rex ducem illum, in cujus manu incumbebat, constituit ad portam: quem conculcavit turba in introitu portæ, et mortuus est, juxta quod locutus fuerat vir Dei, quando descenderat rex ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Factumque est secundum sermonem viri Dei quem dixerat regi, quando ait: Duo modii hordei statere uno erunt, et modius similæ statere uno, hoc eodem tempore cras in porta Samariæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'quando responderat dux ille viro Dei, et dixerat: Etiamsi Dominus fecerit cataractas in cælo, numquid poterit fieri quod loqueris? Et dixit ei: Videbis oculis tuis, et inde non comedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Evenit ergo ei sicut prædictum fuerat, et conculcavit eum populus in porta, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Eliseus autem locutus est ad mulierem cujus vivere fecerat filium, dicens: Surge, vade tu et domus tua, et peregrinare ubicumque repereris: vocavit enim Dominus famem, et veniet super terram septem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Quæ surrexit, et fecit juxta verbum hominis Dei: et vadens cum domo sua, peregrinata est in terra Philisthiim diebus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Cumque finiti essent anni septem, reversa est mulier de terra Philisthiim: et egressa est ut interpellaret regem pro domo sua, et pro agris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Rex autem loquebatur cum Giezi puero viri Dei, dicens: Narra mihi omnia magnalia quæ fecit Eliseus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Cumque ille narraret regi quomodo mortuum suscitasset, apparuit mulier cujus vivificaverat filium, clamans ad regem pro domo sua, et pro agris suis. Dixitque Giezi: Domine mi rex, hæc est mulier, et hic est filius ejus quem suscitavit Eliseus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Et interrogavit rex mulierem: quæ narravit ei. Deditque ei rex eunuchum unum, dicens: Restitue ei omnia quæ sua sunt, et universos reditus agrorum, a die qua reliquit terram usque ad præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Venit quoque Eliseus Damascum, et Benadad rex Syriæ ægrotabat: nuntiaveruntque ei, dicentes: Venit vir Dei huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Et ait rex ad Hazaël: Tolle tecum munera, et vade in occursum viri Dei, et consule Dominum per eum, dicens: Si evadere potero de infirmitate mea hac?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Ivit igitur Hazaël in occursum ejus, habens secum munera, et omnia bona Damasci, onera quadraginta camelorum. Cumque stetisset coram eo, ait: Filius tuus Benadad rex Syriæ misit me ad te, dicens: Si sanari potero de infirmitate mea hac?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Dixitque ei Eliseus: Vade, dic ei: Sanaberis: porro ostendit mihi Dominus quia morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Stetique cum eo, et conturbatus est usque ad suffusionem vultus: flevitque vir Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Cui Hazaël ait: Quare dominus meus flet? At ille dixit: Quia scio quæ facturus sis filiis Israël mala. Civitates eorum munitas igne succendes, et juvenes eorum interficies gladio, et parvulos eorum elides, et prægnantes divides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Dixitque Hazaël: Quid enim sum servus tuus canis, ut faciam rem istam magnam? Et ait Eliseus: Ostendit mihi Dominus te regem Syriæ fore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Qui cum recessisset ab Eliseo, venit ad dominum suum. Qui ait ei: Quid dixit tibi Eliseus? At ille respondit: Dixit mihi: Recipies sanitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Cumque venisset dies altera, tulit stragulum, et infudit aquam, et expandit super faciem ejus: quo mortuo, regnavit Hazaël pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Anno quinto Joram filii Achab regis Israël, et Josaphat regis Juda, regnavit Joram filius Josaphat rex Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Triginta duorum annorum erat cum regnare cœpisset, et octo annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Ambulavitque in viis regum Israël, sicut ambulaverat domus Achab: filia enim Achab erat uxor ejus: et fecit quod malum est in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Noluit autem Dominus disperdere Judam, propter David servum suum, sicut promiserat ei, ut daret illi lucernam, et filiis ejus cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'In diebus ejus recessit Edom ne esset sub Juda, et constituit sibi regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Venitque Joram Seira, et omnes currus cum eo: et surrexit nocte, percussitque Idumæos qui eum circumdederant, et principes curruum: populus autem fugit in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Recessit ergo Edom ne esset sub Juda, usque ad diem hanc. Tunc recessit et Lobna in tempore illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Reliqua autem sermonum Joram, et universa quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et dormivit Joram cum patribus suis, sepultusque est cum eis in civitate David, et regnavit Ochozias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Anno duodecimo Joram filii Achab regis Israël regnavit Ochozias filius Joram regis Judæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Viginti duorum annorum erat Ochozias cum regnare cœpisset, et uno anno regnavit in Jerusalem: nomen matris ejus Athalia filia Amri regis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Et ambulavit in viis domus Achab: et fecit quod malum est coram Domino, sicut domus Achab: gener enim domus Achab fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Abiit quoque cum Joram filio Achab ad præliandum contra Hazaël regem Syriæ in Ramoth Galaad, et vulneraverunt Syri Joram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Qui reversus est ut curaretur in Jezrahel, quia vulneraverant eum Syri in Ramoth præliantem contra Hazaël regem Syriæ. Porro Ochozias filius Joram rex Juda descendit invisere Joram filium Achab in Jezrahel, quia ægrotabat ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Eliseus autem prophetes vocavit unum de filiis prophetarum, et ait illi: Accinge lumbos tuos, et tolle lenticulam olei hanc in manu tua, et vade in Ramoth Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Cumque veneris illuc, videbis Jehu filium Josaphat filii Namsi: et ingressus suscitabis eum de medio fratrum suorum, et introduces in interius cubiculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Tenensque lenticulam olei, fundes super caput ejus, et dices: Hæc dicit Dominus: Unxi te regem super Israël. Aperiesque ostium, et fugies, et non ibi subsistes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Abiit ergo adolescens puer prophetæ in Ramoth Galaad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'et ingressus est illuc: ecce autem principes exercitus sedebant: et ait: Verbum mihi ad te, o princeps. Dixitque Jehu: Ad quem ex omnibus nobis? At ille dixit: Ad te, o princeps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Et surrexit, et ingressus est cubiculum: at ille fudit oleum super caput ejus, et ait: Hæc dicit Dominus Deus Israël: Unxi te regem super populum Domini Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'et percuties domum Achab domini tui, et ulciscar sanguinem servorum meorum prophetarum, et sanguinem omnium servorum Domini de manu Jezabel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Perdamque omnem domum Achab: et interficiam de Achab mingentem ad parietem, et clausum et novissimum in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Et dabo domum Achab sicut domum Jeroboam filii Nabat, et sicut domum Baasa filii Ahia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Jezabel quoque comedent canes in agro Jezrahel, nec erit qui sepeliat eam. Aperuitque ostium, et fugit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Jehu autem egressus est ad servos domini sui: qui dixerunt ei: Rectene sunt omnia? quid venit insanus iste ad te? Qui ait eis: Nostis hominem, et quid locutus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'At ille responderunt: Falsum est, sed magis narra nobis. Qui ait eis: Hæc et hæc locutus est mihi, et ait: Hæc dicit Dominus: Unxi te regem super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Festinaverunt itaque, et unusquisque tollens pallium suum posuerunt sub pedibus ejus in similitudinem tribunalis, et cecinerunt tuba, atque dixerunt: Regnavit Jehu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Conjuravit ergo Jehu filius Josaphat filii Namsi contra Joram: porro Joram obsederat Ramoth Galaad, ipse et omnis Israël contra Hazaël regem Syriæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'et reversus fuerat ut curaretur in Jezrahel propter vulnera, quia percusserant eum Syri præliantem contra Hazaël regem Syriæ. Dixitque Jehu: Si placet vobis, nemo egrediatur profugus de civitate, ne vadat, et nuntiet in Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Et ascendit, et profectus est in Jezrahel: Joram enim ægrotabat ibi, et Ochozias rex Juda descenderat ad visitandum Joram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Igitur speculator qui stabat super turrim Jezrahel, vidit globum Jehu venientis, et ait: Video ego globum. Dixitque Joram: Tolle currum, et mitte in occursum eorum, et dicat vadens: Rectene sunt omnia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Abiit ergo qui ascenderat currum, in occursum ejus, et ait: Hæc dicit rex: Pacatane sunt omnia? Dixitque Jehu: Quid tibi et paci? transi, et sequere me. Nuntiavit quoque speculator, dicens: Venit nuntius ad eos, et non revertitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Misit etiam currum equorum secundum: venitque ad eos, et ait: Hæc dicit rex: Numquid pax est? Et ait Jehu: Quid tibi et paci? transi, et sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Nuntiavit autem speculator, dicens: Venit usque ad eos, et non revertitur: est autem incessus quasi incessus Jehu filii Namsi, præceps enim graditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Et ait Joram: Junge currum. Junxeruntque currum ejus, et egressus est Joram rex Israël, et Ochozias rex Juda, singuli in curribus suis, egressique sunt in occursum Jehu, et invenerunt eum in agro Naboth Jezrahelitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Cumque vidisset Joram Jehu, dixit: Pax est, Jehu? At ille respondit: Quæ pax? adhuc fornicationes Jezabel matris tuæ, et veneficia ejus multa, vigent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Convertit autem Joram manum suam, et fugiens ait ad Ochoziam: Insidiæ, Ochozia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Porro Jehu tetendit arcum manu, et percussit Joram inter scapulas: et egressa est sagitta per cor ejus, statimque corruit in curru suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Dixitque Jehu ad Badacer ducem: Tolle, projice eum in agro Naboth Jezrahelitæ: memini enim quando ego et tu sedentes in curru sequebamur Achab patrem hujus, quod Dominus onus hoc levaverit super eum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Si non pro sanguine Naboth, et pro sanguine filiorum ejus, quem vidi heri, ait Dominus, reddam tibi in agro isto, dicit Dominus. Nunc ergo tolle, et projice eum in agrum juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Ochozias autem rex Juda videns hoc, fugit per viam domus horti: persecutusque est eum Jehu, et ait: Etiam hunc percutite in curru suo. Et percusserunt eum in ascensu Gaver, qui est juxta Jeblaam: qui fugit in Mageddo, et mortuus est ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Et imposuerunt eum servi ejus super currum suum, et tulerunt in Jerusalem: sepelieruntque eum in sepulchro cum patribus suis in civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Anno undecimo Joram filii Achab, regnavit Ochozias super Judam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'venitque Jehu in Jezrahel. Porro Jezabel, introitu ejus audito, depinxit oculos suos stibio, et ornavit caput suum, et respexit per fenestram');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'ingredientem Jehu per portam, et ait: Numquid pax potest esse Zambri, qui interfecit dominum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Levavitque Jehu faciem suam ad fenestram, et ait: Quæ est ista? et inclinaverunt se ad eum duo vel tres eunuchi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'At ille dixit eis: Præcipitate eam deorsum: et præcipitaverunt eam, aspersusque est sanguine paries, et equorum ungulæ conculcaverunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Cumque introgressus esset ut comederet biberetque, ait: Ite, et videte maledictam illam, et sepelite eam: quia filia regis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Cumque issent ut sepelirent eam, non invenerunt nisi calvariam, et pedes, et summas manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Reversique nuntiaverunt ei. Et ait Jehu: Sermo Domini est, quem locutus est per servum suum Eliam Thesbiten, dicens: In agro Jezrahel comedent canes carnes Jezabel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'et erunt carnes Jezabel sicut stercus super faciem terræ in agro Jezrahel, ita ut prætereuntes dicant: Hæccine est illa Jezabel?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Erant autem Achab septuaginta filii in Samaria: scripsit ergo Jehu litteras, et misit in Samariam, ad optimates civitatis, et ad majores natu, et ad nutritios Achab, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Statim ut acceperitis litteras has, qui habetis filios domini vestri, et currus, et equos, et civitates firmas, et arma,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'eligite meliorem, et eum qui vobis placuerit de filiis domini vestri, et eum ponite super solium patris sui, et pugnate pro domo domini vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Timuerunt illi vehementer, et dixerunt: Ecce duo reges non potuerunt stare coram eo, et quomodo nos valebimus resistere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Miserunt ergo præpositi domus, et præfecti civitatis, et majores natu, et nutritii, ad Jehu, dicentes: Servi tui sumus: quæcumque jusseris faciemus, nec constituemus nobis regem: quæcumque tibi placent, fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Rescripsit autem eis litteras secundo, dicens: Si mei estis, et obeditis mihi, tollite capita filiorum domini vestri, et venite ad me hac eadem hora cras in Jezrahel. Porro filii regis, septuaginta viri, apud optimates civitates nutriebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Cumque venissent litteras ad eos, tulerunt filios regis, et occiderunt septuaginta viros, et posuerunt capita eorum in cophinis, et miserunt ad eum in Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Venit autem nuntius, et indicavit ei, dicens: Attulerunt capita filiorum regis. Qui respondit: Ponite ea ad duos acervos juxta introitum portæ usque mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Cumque diluxisset, egressus est, et stans dixit ad omnem populum: Justi estis: si ego conjuravi contra dominum meum et interfeci eum, quis percussit omnes hos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'videte ergo nunc quoniam non cecidit de sermonibus Domini in terram, quos locutus est Dominus super domum Achab: et Dominus fecit quod locutus est in manu servi sui Eliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Percussit igitur Jehu omnes qui reliqui erant de domo Achab in Jezrahel, et universos optimates ejus, et notos, et sacerdotes, donec non remanerent ex eo reliquiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Et surrexit, et venit in Samariam: cumque venisset ad Cameram pastorum in via,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'invenit fratres Ochoziæ regis Juda: dixitque ad eos: Quinam estis vos? Qui responderunt: Fratres Ochoziæ sumus, et descendimus ad salutandos filios regis, et filios reginæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Qui ait: Comprehendite eos vivos. Quos cum comprehendissent vivos, jugulaverunt eos in cisterna juxta Cameram, quadraginta duos viros: et non reliquit ex eis quemquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Cumque abiisset inde, invenit Jonadab filium Rechab in occursum sibi, et benedixit ei. Et ait ad eum: Numquid est cor tuum rectum, sicut cor meum cum corde tuo? Et ait Jonadab: Est. Si est, inquit, da manum tuam. Qui dedit ei manum suam. At ille levavit eum ad se in currum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'dixitque ad eum: Veni mecum, et vide zelum meum pro Domino. Et impositum in curru suo');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'duxit in Samariam. Et percussit omnes qui reliqui fuerant de Achab in Samaria usque ad unum, juxta verbum Domini quod locutus est per Eliam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Congregavit ergo Jehu omnem populum, et dixit ad eos: Achab coluit Baal parum, ego autem colam eum amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Nunc igitur omnes prophetas Baal, et universos servos ejus, et cunctos sacerdotes ipsius vocate ad me: nullus sit qui non veniat: sacrificium enim grande est mihi Baal: quicumque defuerit, non vivet. Porro Jehu faciebat hoc insidiose, ut disperderet cultores Baal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Et dixit: Sanctificate diem solemnem Baal. Vocavitque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'et misit in universos terminos Israël, et venerunt cuncti servi Baal: non fuit residuus ne unus quidem qui non veniret. Et ingressi sunt templum Baal: et repleta est domus Baal, a summo usque ad summum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Dixitque his qui erant super vestes: Proferte vestimenta universis servis Baal. Et protulerunt eis vestes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Ingressusque Jehu, et Jonadab filius Rechab, templum Baal, ait cultoribus Baal: Perquirite, et videte, ne quis forte vobiscum sit de servis Domini, sed ut sint servi Baal soli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Ingressi sunt igitur ut facerent victimas et holocausta: Jehu autem præparaverat sibi foris octoginta viros, et dixerat eis: Quicumque fugerit de hominibus his, quos ego adduxero in manus vestras, anima ejus erit pro anima illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Factum est autem, cum completum esset holocaustum, præcepit Jehu militibus et ducibus suis: Ingredimini, et percutite eos: nullus evadat. Percusseruntque eos in ore gladii, et projecerunt milites et duces: et ierunt in civitatem templi Baal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'et protulerunt statuam de fano Baal, et combusserunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'et comminuerunt eam. Destruxerunt quoque ædem Baal, et fecerunt pro ea latrinas usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Delevit itaque Jehu Baal de Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'verumtamen a peccatis Jeroboam filii Nabat, qui peccare fecit Israël, non recessit, nec dereliquit vitulos aureos qui erant in Bethel et in Dan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Dixit autem Dominus ad Jehu: Quia studiose egisti quod rectum erat, et placebat in oculis meis, et omnia quæ erant in corde meo fecisti contra domum Achab: filii tui usque ad quartam generationem sedebunt super thronum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Porro Jehu non custodivit ut ambularet in lege Domini Dei Israël in toto corde suo: non enim recessit a peccatis Jeroboam, qui peccare fecerat Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'In diebus illis cœpit Dominus tædere super Israël: percussitque eos Hazaël in universis finibus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'a Jordane contra orientalem plagam, omnem terram Galaad, et Gad, et Ruben, et Manasse, ab Aroër, quæ est super torrentem Arnon, et Galaad, et Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Reliqua autem verborum Jehu, et universa quæ fecit, et fortitudo ejus, nonne hæc scripta sunt in libro verborum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et dormivit Jehu cum patribus suis, sepelieruntque eum in Samaria: et regnavit Joachaz filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Dies autem quos regnavit Jehu super Israël, viginti et octo anni sunt in Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Athalia vero mater Ochoziæ, videns mortuum filium suum, surrexit, et interfecit omne semen regium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Tollens autem Josaba filia regis Joram, soror Ochoziæ, Joas filium Ochoziæ, furata est eum de medio filiorum regis qui interficiebantur, et nutricem ejus de triclinio: et abscondit eum a facie Athaliæ ut non interficeretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Eratque cum ea sex annis clam in domo Domini: porro Athalia regnavit super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Anno autem septimo misit Jojada, et assumens centuriones et milites, introduxit ad se in templum Domini, pepigitque cum eis fœdus: et adjurans eos in domo Domini, ostendit eis filium regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'et præcepit illis, dicens: Iste est sermo, quem facere debetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'tertia pars vestrum introëat sabbato, et observet excubias domus regis. Tertia autem pars sit ad portam Sur, et tertia pars sit ad portam quæ est post habitaculum scutariorum: et custodietis excubias domus Messa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Duæ vero partes e vobis, omnes egredientes sabbato, custodiant excubias domus Domini circa regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Et vallabitis eum, habentes arma in manibus vestris: si quis autem ingressus fuerit septum templi, interficiatur: eritisque cum rege introëunte et egrediente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Et fecerunt centuriones juxta omnia quæ præceperat eis Jojada sacerdos: et assumentes singuli viros suos qui ingrediebantur sabbatum, cum his qui egrediebantur sabbato, venerunt ad Jojadam sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Qui dedit eis hastas et arma regis David, quæ erant in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et steterunt singuli habentes arma in manu sua, a parte templi dextera usque ad partem sinistram altaris et ædis, circum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Produxitque filium regis, et posuit super eum diadema et testimonium: feceruntque eum regem, et unxerunt: et plaudentes manu, dixerunt: Vivat rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Audivit autem Athalia vocem populi currentis: et ingressa ad turbas in templum Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'vidit regem stantem super tribunal juxta morem, et cantores, et tubas prope eum, omnemque populum terræ lætantem, et canentem tubis: et scidit vestimenta sua, clamavitque: Conjuratio, conjuratio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Præcepit autem Jojada centurionibus qui erant super exercitum, et ait eis: Educite eam extra septa templi, et quicumque eam secutus fuerit, feriatur gladio. Dixerat enim sacerdos: Non occidatur in templo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Imposueruntque ei manus, et impegerunt eam per viam introitus equorum, juxta palatium, et interfecta est ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Pepigit ergo Jojada fœdus inter Dominum, et inter regem, et inter populum, ut esset populus Domini: et inter regem et populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Ingressusque est omnis populus terræ templum Baal, et destruxerunt aras ejus, et imagines contriverunt valide: Mathan quoque sacerdotem Baal occiderunt coram altari. Et posuit sacerdos custodias in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Tulitque centuriones, et Cerethi et Phelethi legiones, et omnem populum terræ, deduxeruntque regem de domo Domini: et venerunt per viam portæ scutariorum in palatium, et sedit super thronum regum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Lætatusque est omnis populus terræ, et civitas conquievit: Athalia autem occisa est gladio in domo regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Septemque annorum erat Joas, cum regnare cœpisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Anno septimo Jehu, regnavit Joas: et quadraginta annis regnavit in Jerusalem. Nomen matris ejus Sebia de Bersabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Fecitque Joas rectum coram Domino cunctis diebus quibus docuit eum Jojada sacerdos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Verumtamen excelsa non abstulit: adhuc enim populus immolabat, et adolebat in excelsis incensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Dixitque Joas ad sacerdotes: Omnem pecuniam sanctorum, quæ illata fuerit in templum Domini a prætereuntibus, quæ offertur pro pretio animæ, et quam sponte et arbitrio cordis sui inferunt in templum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'accipiant illam sacerdotes juxta ordinem suum, et instaurent sartatecta domus, si quid necessarium viderint instauratione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Igitur usque ad vigesimum tertium annum regis Joas, non instauraverunt sacerdotes sartatecta templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Vocavitque rex Joas Jojadam pontificem et sacerdotes, dicens eis: Quare sartatecta non instauratis templi? nolite ergo amplius accipere pecuniam juxta ordinem vestrum, sed ad instaurationem templi reddite eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Prohibitique sunt sacerdotes ultra accipere pecuniam a populo, et instaurare sartatecta domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Et tulit Jojada pontifex gazophylacium unum, aperuitque foramen desuper, et posuit illud juxta altare ad dexteram ingredientium domum Domini: mittebantque in eo sacerdotes qui custodiebant ostia, omnem pecuniam quæ deferebatur ad templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Cumque viderent nimiam pecuniam esse in gazophylacio, ascendebat scriba regis, et pontifex, effundebantque et numerabant pecuniam quæ inveniebatur in domo Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'et dabant eam juxta numerum atque mensuram in manu eorum qui præerant cæmentariis domus Domini: qui impendebant eam in fabris lignorum et in cæmentariis, iis qui operabantur in domo Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'et sartatecta faciebant: et in iis qui cædebant saxa, et ut emerent ligna, et lapides, qui excidebantur, ita ut impleretur instauratio domus Domini in universis quæ indigebant expensa ad muniendam domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Verumtamen non fiebant ex eadem pecunia hydriæ templi Domini, et fuscinulæ, et thuribula, et tubæ, et omne vas aureum et argenteum, de pecunia quæ inferebatur in templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Iis enim qui faciebant opus, dabatur ut instauraretur templum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'et non fiebat ratio iis hominibus qui accipiebant pecuniam ut distribuerent eam artificibus, sed in fide tractabant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Pecuniam vero pro delicto, et pecuniam pro peccatis non inferebant in templum Domini, quia sacerdotum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Tunc ascendit Hazaël rex Syriæ, et pugnabat contra Geth, cepitque eam: et direxit faciem suam ut ascenderet in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Quam ob rem tulit Joas rex Juda omnia sanctificata quæ consecraverant Josaphat, et Joram, et Ochozias, patres ejus reges Juda, et quæ ipse obtulerat: et universum argentum quod inveniri potuit in thesauris templi Domini et in palatio regis: misitque Hazaëli regi Syriæ, et recessit ab Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Reliqua autem sermonum Joas, et universa quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Surrexerunt autem servi ejus, et conjuraverunt inter se, percusseruntque Joas in domo Mello in descensu Sella.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Josachar namque filius Semaath, et Jozabad filius Somer servi ejus, percusserunt eum, et mortuus est: et sepelierunt eum cum patribus suis in civitate David: regnavitque Amasias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Anno vigesimo tertio Joas filii Ochoziæ regis Juda, regnavit Joachaz filius Jehu super Israël in Samaria decem et septem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et fecit malum coram Domino, secutusque est peccata Jeroboam filii Nabat, qui peccare fecit Israël, et non declinavit ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Iratusque est furor Domini contra Israël, et tradidit eos in manu Hazaël regis Syriæ, et in manu Benadad filii Hazaël, cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Deprecatus est autem Joachaz faciem Domini, et audivit eum Dominus: vidit enim angustiam Israël, quia attriverat eos rex Syriæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'et dedit Dominus salvatorem Israëli, et liberatus est de manu regis Syriæ: habitaveruntque filii Israël in tabernaculis suis sicut heri et nudiustertius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Verumtamen non recesserunt a peccatis domus Jeroboam, qui peccare fecit Israël, sed in ipsis ambulaverunt: siquidem et lucus permansit in Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Et non sunt derelicti Joachaz de populo nisi quinquaginta equites, et decem currus, et decem millia peditum: interfecerat enim eos rex Syriæ, et redegerat quasi pulverem in tritura areæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Reliqua autem sermonum Joachaz, et universa quæ fecit, et fortitudo ejus, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Dormivitque Joachaz cum patribus suis, et sepelierunt eum in Samaria: regnavitque Joas filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Anno trigesimo septimo Joas regis Juda, regnavit Joas filius Joachaz super Israël in Samaria sedecim annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et fecit quod malum est in conspectu Domini: non declinavit ab omnibus peccatis Jeroboam filii Nabat, qui peccare fecit Israël, sed in ipsis ambulavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Reliqua autem sermonum Joas, et universa quæ fecit, et fortitudo ejus, quomodo pugnaverit contra Amasiam regem Juda, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et dormivit Joas cum patribus suis: Jeroboam autem sedit super solium ejus. Porro Joas sepultus est in Samaria cum regibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Eliseus autem ægrotabat infirmitate, qua et mortuus est: descenditque ad eum Joas rex Israël, et flebat coram eo, dicebatque: Pater mi, pater mi, currus Israël et auriga ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Et ait illi Eliseus: Affer arcum et sagittas. Cumque attulisset ad eum arcum et sagittas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'dixit ad regem Israël: Pone manum tuam super arcum. Et cum posuisset ille manum suam, superposuit Eliseus manus suas manibus regis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'et ait: Aperi fenestram orientalem. Cumque aperuisset, dixit Eliseus: Jace sagittam. Et jecit. Et ait Eliseus: Sagitta salutis Domini, et sagitta salutis contra Syriam: percutiesque Syriam in Aphec, donec consumas eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Et ait: Tolle sagittas. Qui cum tulisset, rursum dixit ei: Percute jaculo terram. Et cum percussisset tribus vicibus, et stetisset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'iratus est vir Dei contra eum, et ait: Si percussisses quinquies, aut sexies, sive septies, percussisses Syriam usque ad consumptionem: nunc autem tribus vicibus percuties eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Mortuus est ergo Eliseus, et sepelierunt eum. Latrunculi autem de Moab venerunt in terram in ipso anno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Quidam autem sepelientes hominem, viderunt latrunculos, et projecerunt cadaver in sepulchro Elisei. Quod cum tetigisset ossa Elisei, revixit homo, et stetit super pedes suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Igitur Hazaël rex Syriæ afflixit Israël cunctis diebus Joachaz:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'et misertus est Dominus eorum, et reversus est ad eos propter pactum suum, quod habebat cum Abraham, et Isaac, et Jacob: et noluit disperdere eos, neque projicere penitus usque in præsens tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Mortuus est autem Hazaël rex Syriæ, et regnavit Benadad filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Porro Joas filius Joachaz tulit urbes de manu Benadad filii Hazaël, quas tulerat de manu Joachaz patris sui jure prælii: tribus vicibus percussit eum Joas, et reddidit civitates Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'In anno secundo Joas filii Joachaz regis Israël, regnavit Amasias filius Joas regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Viginti quinque annorum erat cum regnare cœpisset: viginti autem et novem annis regnavit in Jerusalem. Nomen matris ejus Joadan de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et fecit rectum coram Domino, verumtamen non ut David pater ejus. Juxta omnia quæ fecit Joas pater suus, fecit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'nisi hoc tantum, quod excelsa non abstulit: adhuc enim populus immolabat, et adolebat incensum in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Cumque obtinuisset regnum, percussit servos suos, qui interfecerant regem patrem suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'filios autem eorum qui occiderant, non occidit, juxta quod scriptum est in libro legis Moysi, sicut præcepit Dominus, dicens: Non morientur patres pro filiis, neque filii morientur pro patribus: sed unusquisque in peccato suo morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ipse percussit Edom in valle Salinarum decem millia, et apprehendit petram in prælio, vocavitque nomen ejus Jectehel usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tunc misit Amasias nuntios ad Joas filium Joachaz filii Jehu regis Israël, dicens: Veni, et videamus nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Remisitque Joas rex Israël ad Amasiam regem Juda, dicens: Carduus Libani misit ad cedrum quæ est in Libano, dicens: Da filiam tuam filio meo uxorem. Transieruntque bestiæ saltus quæ sunt in Libano, et conculcaverunt carduum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Percutiens invaluisti super Edom, et sublevavit te cor tuum: contentus esto gloria, et sede in domo tua: quare provocas malum, ut cadas tu et Judas tecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Et non acquievit Amasias. Ascenditque Joas rex Israël, et viderunt se, ipse et Amasias rex Juda, in Bethsames oppido Judæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Percussusque est Juda coram Israël, et fugerunt unusquisque in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Amasiam vero regem Juda, filium Joas filii Ochoziæ, cepit Joas rex Israël in Bethsames, et adduxit eum in Jerusalem: et interrupit murum Jerusalem, a porta Ephraim usque ad portam anguli, quadringentis cubitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Tulitque omne aurum et argentum, et universa vasa quæ inventa sunt in domo Domini et in thesauris regis, et obsides, et reversus est in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Reliqua autem verborum Joas quæ fecit, et fortitudo ejus qua pugnavit contra Amasiam regem Juda, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Dormivitque Joas cum patribus suis, et sepultus est in Samaria cum regibus Israël, et regnavit Jeroboam filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Vixit autem Amasias filius Joas rex Juda postquam mortuus est Joas filius Joachaz regis Israël, quindecim annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Reliqua autem sermonum Amasiæ, nonne hæc scripta sunt in libro sermonum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Factaque est contra eum conjuratio in Jerusalem: at ille fugit in Lachis. Miseruntque post eum in Lachis, et interfecerunt eum ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'et asportaverunt in equis, sepultusque est in Jerusalem cum patribus suis in civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Tulit autem universus populus Judæ Azariam annos natum sedecim, et constituerunt eum regem pro patre ejus Amasia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ipse ædificavit \'lath, et restituit eam Judæ, postquam dormivit rex cum patribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Anno quintodecimo Amasiæ filii Joas regis Juda, regnavit Jeroboam filius Joas regis Israël in Samaria, quadraginta et uno anno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et fecit quod malum est coram Domino: non recessit ab omnibus peccatis Jeroboam filii Nabat, qui peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ipse restituit terminos Israël ab introitu Emath usque ad mare solitudinis, juxta sermonem Domini Dei Israël quem locutus est per servum suum Jonam filium Amathi prophetam, qui erat de Geth, quæ est in Opher.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Vidit enim Dominus afflictionem Israël amaram nimis, et quod consumpti essent usque ad clausos carcere et extremos, et non esset qui auxiliaretur Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Nec locutus est Dominus ut deleret nomen Israël de sub cælo, sed salvavit eos in manu Jeroboam filii Joas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Reliqua autem sermonum Jeroboam, et universa quæ fecit, et fortitudo ejus qua præliatus est, et quomodo restituit Damascum et Emath Judæ in Israël, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Dormivitque Jeroboam cum patribus suis regibus Israël, et regnavit Zacharias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Anno vigesimo septimo Jeroboam regis Israël, regnavit Azarias filius Amasiæ regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Sedecim annorum erat cum regnare cœpisset, et quinquaginta duobus annis regnavit in Jerusalem: nomen matris ejus Jechelia de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Fecitque quod erat placitum coram Domino, juxta omnia quæ fecit Amasias pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Verumtamen excelsa non est demolitus: adhuc populus sacrificabat, et adolebat incensum in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Percussit autem Dominus regem, et fuit leprosus usque in diem mortis suæ, et habitabat in domo libera seorsum: Joatham vero filius regis gubernabat palatium, et judicabit populum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Reliqua autem sermonum Azariæ, et universa quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et dormivit Azarias cum patribus suis: sepelieruntque eum cum majoribus suis in civitate David, et regnavit Joatham filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Anno trigesimo octavo Azariæ regis Juda, regnavit Zacharias filius Jeroboam super Israël in Samaria sex mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et fecit quod malum est coram Domino, sicut fecerant patres ejus: non recessit a peccatis Jeroboam filii Nabat, qui peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Conjuravit autem contra eum Sellum filius Jabes: percussitque eum palam, et interfecit, regnavitque pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Reliqua autem verborum Zachariæ, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Iste est sermo Domini quem locutus est ad Jehu, dicens: Filii tui usque ad quartam generationem sedebunt super thronum Israël. Factumque est ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sellum filius Jabes regnavit trigesimo novo anno Azariæ regis Juda: regnavit autem uno mense in Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Et ascendit Manahem filius Gadi de Thersa, venitque in Samariam, et percussit Sellum filium Jabes in Samaria, et interfecit eum: regnavitque pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Reliqua autem verborum Sellum, et conjuratio ejus, per quam tetendit insidias, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tunc percussit Manahem Thapsam, et omnes qui erant in ea, et terminos ejus de Thersa: noluerant enim aperire ei: et interfecit omnes prægnantes ejus, et scidit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Anno trigesimo nono Azariæ regis Juda, regnavit Manahem filius Gadi super Israël decem annis in Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Fecitque quod erat malum coram Domino: non recessit a peccatis Jeroboam filii Nabat, qui peccare fecit Israël, cunctis diebus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Veniebat Phul rex Assyriorum in terram, et dabat Manahem Phul mille talenta argenti, ut esset ei in auxilium, et firmaret regnum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Indixitque Manahem argentum super Israël cunctis potentibus et divitibus, ut daret regi Assyriorum quinquaginta siclos argenti per singulos: reversusque est rex Assyriorum, et non est moratus in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Reliqua autem sermonum Manahem, et universa quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et dormivit Manahem cum patribus suis: regnavitque Phaceia filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Anno quinquagesimo Azariæ regis Juda, regnavit Phaceia filius Manahem super Israël in Samaria biennio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et fecit quod erat malum coram Domino: non recessit a peccatis Jeroboam filii Nabat, qui peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Conjuravit autem adversus eum Phacee filius Romeliæ, dux ejus, et percussit eum in Samaria in turre domus regiæ, juxta Argob et juxta Arie, et cum eo quinquaginta viros de filiis Galaaditarum: et interfecit eum, regnavitque pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Reliqua autem sermonum Phaceia, et universa quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Anno quinquagesimo secundo Azariæ regis Juda, regnavit Phacee filius Romeliæ super Israël in Samaria viginti annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Et fecit quod erat malum coram Domino: non recessit a peccatis Jeroboam filii Nabat, qui peccare fecit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'In diebus Phacee regis Israël, venit Theglathphalasar rex Assur, et cepit Ajon, et Abel Domum, Maacha et Janoë, et Cedes, et Asor, et Galaad, et Galilæam, et universam terram Nephthali: et transtulit eos in Assyrios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Conjuravit autem et tetendit insidias Osee filius Ela contra Phacee filium Romeliæ, et percussit eum, et interfecit: regnavitque pro eo vigesimo anno Joatham filii Oziæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Reliqua autem sermonum Phacee, et universa quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Anno secundo Phacee filii Romeliæ regis Israël, regnavit Joatham filius Oziæ regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Viginti quinque annorum erat cum regnare cœpisset, et sedecim annis regnavit in Jerusalem: nomen matris ejus Jerusa filia Sadoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Fecitque quod erat placitum coram Domino: juxta omnia quæ fecerat Ozias pater suus, operatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Verumtamen excelsa non abstulit: adhuc populus immolabat, et adolebat incensum in excelsis. Ipse ædificavit portam domus Domini sublimissimam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Reliqua autem sermonum Joatham, et universa quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'In diebus illis cœpit Dominus mittere in Judam Rasin regem Syriæ, et Phacee filium Romeliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et dormivit Joatham cum patribus suis, sepultusque est cum eis in civitate David patris sui: et regnavit Achaz filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Anno decimoseptimo Phacee filii Romeliæ, regnavit Achaz filius Joatham regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Viginti annorum erat Achaz cum regnare cœpisset, et sedecim annis regnavit in Jerusalem. Non fecit quod erat placitum in conspectu Domini Dei sui sicut David pater ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'sed ambulavit in via regum Israël: insuper et filium suum consecravit, transferens per ignem secundum idola gentium, quæ dissipavit Dominus coram filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Immolabat quoque victimas, et adolebat incensum in excelsis, et in collibus, et sub omni ligno frondoso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tunc ascendit Rasin rex Syriæ, et Phacee filius Romeliæ rex Israël, in Jerusalem ad præliandum: cumque obsiderent Achaz, non valuerunt superare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'In tempore illo restituit Rasin rex Syriæ, Ailam Syriæ, et ejecit Judæos de Aila: et Idumæi venerunt in Ailam, et habitaverunt ibi usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Misit autem Achaz nuntios ad Theglathphalasar regem Assyriorum, dicens: Servus tuus, et filius tuus ego sum: ascende, et salvum me fac de manu regis Syriæ, et de manu regis Israël, qui consurrexerunt adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Et cum collegisset argentum et aurum quod inveniri potuit in domo Domini et in thesauris regis, misit regi Assyriorum munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Qui et acquievit voluntati ejus: ascendit enim rex Assyriorum in Damascum, et vastavit eam, et transtulit habitatores ejus Cyrenen: Rasin autem interfecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Perrexitque rex Achaz in occursum Theglathphalasar regis Assyriorum in Damascum: cumque vidisset altare Damasci, misit rex Achaz ad Uriam sacerdotem exemplar ejus, et similitudinem juxta omne opus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Exstruxitque Urias sacerdos altare: juxta omnia quæ præceperat rex Achaz de Damasco, ita fecit sacerdos Urias donec veniret rex Achaz de Damasco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Cumque venisset rex de Damasco, vidit altare, et veneratus est illud: ascenditque et immolavit holocausta et sacrificium suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'et libavit libamina, et fudit sanguinem pacificorum quæ obtulerat super altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Porro altare æreum quod erat coram Domino, transtulit de facie templi, et de loco altaris, et de loco templi Domini: posuitque illud ex latere altaris ad aquilonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Præcepit quoque rex Achaz Uriæ sacerdoti, dicens: Super altare majus offer holocaustum matutinum, et sacrificium vespertinum, et holocaustum regis, et sacrificium ejus, et holocaustum universi populi terræ, et sacrificia eorum, et libamina eorum: et omnem sanguinem holocausti, et universum sanguinem victimæ super illud effundes: altare vero æreum erit paratum ad voluntatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Fecit igitur Urias sacerdos juxta omnia quæ præceperat rex Achaz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Tulit autem rex Achaz cælatas bases, et luterem qui erat desuper: et mare deposuit de bobus æreis qui sustentabant illud, et posuit super pavimentum stratum lapide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Musach quoque sabbati quod ædificaverat in templo: et ingressum regis exterius convertit in templum Domini propter regem Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Reliqua autem verborum Achaz quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Dormivitque Achaz cum patribus suis, et sepultus est cum eis in civitate David: et regnavit Ezechias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Anno duodecimo Achaz regis Juda, regnavit Osee filius Ela in Samaria super Israël novem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Fecitque malum coram Domino, sed non sicut reges Israël qui ante eum fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Contra hunc ascendit Salmanasar rex Assyriorum, et factus est ei Osee servus, reddebatque illi tributa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Cumque deprehendisset rex Assyriorum Osee, quod rebellare nitens misisset nuntios ad Sua regem \'gypti ne præstaret tributa regi Assyriorum sicut singulis annis solitus erat, obsedit eum, et vinctum misit in carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Pervagatusque est omnem terram: et ascendens Samariam, obsedit eam tribus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Anno autem nono Osee, cepit rex Assyriorum Samariam, et transtulit Israël in Assyrios: posuitque eos in Hala et in Habor juxta fluvium Gozan, in civitatibus Medorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Factum est enim, cum peccassent filii Israël Domino Deo suo, qui eduxerat eos de terra \'gypti, de manu Pharaonis regis \'gypti, coluerunt deos alienos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Et ambulaverunt juxta ritum gentium quas consumpserat Dominus in conspectu filiorum Israël et regum Israël, quia similiter fecerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et offenderunt filii Israël verbis non rectis Dominum Deum suum: et ædificaverunt sibi excelsa in cunctis urbibus suis, a turre custodum usque ad civitatem munitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Feceruntque sibi statuas et lucos in omni colle sublimi, et subter omne lignum nemorosum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'et adolebant ibi incensum super aras in morem gentium quas transtulerat Dominus a facie eorum: feceruntque verba pessima irritantes Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Et coluerunt immunditias de quibus præcepit eis Dominus ne facerent verbum hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Et testificatus est Dominus in Israël et in Juda per manum omnium prophetarum et videntium, dicens: Revertimini a viis vestris pessimis, et custodite præcepta mea et cæremonias, juxta omnem legem quam præcepi patribus vestris, et sicut misi ad vos in manu servorum meorum prophetarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Qui non audierunt, sed induraverunt cervicem suam juxta cervicem patrum suorum, qui noluerunt obedire Domino Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Et abjecerunt legitima ejus, et pactum quod pepigit cum patribus eorum, et testificationes quibus contestatus est eos: secutique sunt vanitates, et vane egerunt: et secuti sunt gentes quæ erant per circuitum eorum, super quibus præceperat Dominus eis ut non facerent sicut et illæ faciebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Et dereliquerunt omnia præcepta Domini Dei sui: feceruntque sibi conflatiles duos vitulos, et lucos, et adoraverunt universam militiam cæli: servieruntque Baal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'et consecraverunt filios suos et filias suas per ignem: et divinationibus inserviebant, et auguriis: et tradiderunt se ut facerent malum coram Domino, ut irritarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Iratusque est Dominus vehementer Israëli, et abstulit eos a conspectu suo, et non remansit nisi tribus Juda tantummodo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Sed nec ipse Juda custodivit mandata Domini Dei sui: verum ambulavit in erroribus Israël, quos operatus fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Projecitque Dominus omne semen Israël, et afflixit eos, et tradidit eos in manu diripientium, donec projiceret eos a facie sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'ex eo jam tempore quo scissus est Israël a domo David, et constituerunt sibi regem Jeroboam filium Nabat: separavit enim Jeroboam Israël a Domino, et peccare eos fecit peccatum magnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Et ambulaverunt filii Israël in universis peccatis Jeroboam quæ fecerat: et non recesserunt ab eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'usquequo Dominus auferret Israël a facie sua, sicut locutus fuerat in manu omnium servorum suorum prophetarum: translatusque est Israël de terra sua in Assyrios, usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Adduxit autem rex Assyriorum de Babylone, et de Cutha, et de Avah, et de Emath, et de Sepharvaim: et collocavit eos in civitatibus Samariæ pro filiis Israël: qui possederunt Samariam, et habitaverunt in urbibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Cumque ibi habitare cœpissent, non timebant Dominum: et immisit in eos Dominus leones, qui interficiebant eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Nuntiatumque est regi Assyriorum, et dictum: Gentes quas transtulisti, et habitare fecisti in civitatibus Samariæ, ignorant legitima Dei terræ: et immisit in eos Dominus leones, et ecce interficiunt eos, eo quod ignorent ritum Dei terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Præcepit autem rex Assyriorum, dicens: Ducite illuc unum de sacerdotibus quos inde captivos adduxistis, et vadat, et habitet cum eis: et doceat eos legitima Dei terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Igitur cum venisset unus de sacerdotibus his qui captivi ducti fuerant de Samaria, habitavit in Bethel, et docebat eos quomodo colerent Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Et unaquæque gens fabricata est deum suum: posueruntque eos in fanis excelsis quæ fecerant Samaritæ, gens et gens in urbibus suis, in quibus habitabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Viri enim Babylonii fecerunt Sochothbenoth: viri autem Cuthæi fecerunt Nergel: et viri de Emath fecerunt Asima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Porro Hevæi fecerunt Nebahaz et Tharthac. Hi autem qui erant de Sepharvaim, comburebant filios suos igni, Adramelech et Anamelech diis Sepharvaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'et nihilominus colebant Dominum. Fecerunt autem sibi de novissimis sacerdotes excelsorum, et ponebant eos in fanis sublimibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Et cum Dominum colerent, diis quoque suis serviebant juxta consuetudinem gentium, de quibus translati fuerant Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Usque in præsentem diem morem sequuntur antiquum: non timent Dominum, neque custodiunt cæremonias ejus, judicia, et legem, et mandatum, quod præceperat Dominus filiis Jacob, quem cognominavit Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'et percusserat cum eis pactum, et mandaverat eis, dicens: Nolite timere deos alienos, et non adoretis eos, neque colatis eos, et non immoletis eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'sed Dominum Deum vestrum, qui eduxit vos de terra \'gypti in fortitudine magna et in brachio extento, ipsum timete, et illum adorate, et ipsi immolate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Cæremonias quoque, et judicia, et legem, et mandatum, quod scripsit vobis, custodite ut faciatis cunctis diebus: et non timeatis deos alienos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Et pactum quod percussit vobiscum, nolite oblivisci: nec colatis deos alienos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'sed Dominum Deum vestrum timete, et ipse eruet vos de manu omnium inimicorum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Illi vero non audierunt, sed juxta consuetudinem suam pristinam perpetrabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Fuerunt igitur gentes istæ timentes quidem Dominum, sed nihilominus et idolis suis servientes: nam et filii eorum, et nepotes, sicut fecerunt patres sui, ita faciunt usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Anno tertio Osee filii Ela regis Israël, regnavit Ezechias filius Achaz regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Viginti quinque annorum erat cum regnare cœpisset, et viginti novem annis regnavit in Jerusalem: nomen matris ejus Abi filia Zachariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Fecitque quod erat bonum coram Domino, juxta omnia quæ fecerat David pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ipse dissipavit excelsa, et contrivit statuas, et succidit lucos, confregitque serpentem æneum quem fecerat Moyses: siquidem usque ad illud tempus filii Israël adolebant ei incensum: vocavitque nomen ejus Nohestan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'In Domino Deo Israël speravit: itaque post eum non fuit similis ei de cunctis regibus Juda, sed neque in his qui ante eum fuerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'et adhæsit Domino, et non recessit a vestigiis ejus, fecitque mandata ejus, quæ præceperat Dominus Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Unde et erat Dominus cum eo, et in cunctis ad quæ procedebat, sapienter se agebat. Rebellavit quoque contra regem Assyriorum, et non servivit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Ipse percussit Philisthæos usque ad Gazam, et omnes terminos eorum, a turre custodum usque ad civitatem munitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Anno quarto regis Ezechiæ, qui erat annus septimus Osee filii Ela regis Israël, ascendit Salmanasar rex Assyriorum in Samariam, et oppugnavit eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'et cepit. Nam post annos tres, anno sexto Ezechiæ, id est nono anno Osee regis Israël, capta est Samaria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'et transtulit rex Assyriorum Israël in Assyrios, collocavitque eos in Hala et in Habor fluviis Gozan in civitatibus Medorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'quia non audierunt vocem Domini Dei sui, sed prætergressi sunt pactum ejus: omnia quæ præceperat Moyses servus Domini non audierunt, neque fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Anno quartodecimo regis Ezechiæ, ascendit Sennacherib rex Assyriorum ad universas civitates Juda munitas, et cepit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Tunc misit Ezechias rex Juda nuntios ad regem Assyriorum in Lachis, dicens: Peccavi: recede a me, et omne quod imposueris mihi, feram. Indixit itaque rex Assyriorum Ezechiæ regi Judæ trecenta talenta argenti, et triginta talenta auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Deditque Ezechias omne argentum quod repertum fuerat in domo Domini et in thesauris regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'In tempore illo confregit Ezechias valvas templi Domini, et laminas auri quas ipse affixerat, et dedit eas regi Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Misit autem rex Assyriorum Tharthan, et Rabsaris, et Rabsacen de Lachis ad regem Ezechiam cum manu valida Jerusalem: qui cum ascendissent, venerunt Jerusalem, et steterunt juxta aquæductum piscinæ superioris, quæ est in via Agrifullonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Vocaveruntque regem: egressus est autem ad eos Eliacim filius Helciæ præpositus domus, et Sobna scriba, et Joahe filius Asaph a commentariis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Dixitque ad eos Rabsaces: Loquimini Ezechiæ: Hæc dicit rex magnus, rex Assyriorum: Quæ est ista fiducia, qua niteris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'forsitan inisti consilium, ut præpares te ad prælium. In quo confidis, ut audeas rebellare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'an speras in baculo arundineo atque confracto \'gypto, super quem, si incubuerit homo, comminutus ingredietur manum ejus, et perforabit eam? sic est Pharao rex \'gypti omnibus qui confidunt in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Quod si dixeritis mihi: In Domino Deo nostro habemus fiduciam: nonne iste est, cujus abstulit Ezechias excelsa et altaria, et præcepit Judæ et Jerusalem: Ante altare hoc adorabitis in Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nunc igitur transite ad dominum meum regem Assyriorum, et dabo vobis duo millia equorum, et videte an habere valeatis ascensores eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Et quomodo potestis resistere ante unum satrapam de servis domini mei minimis? an fiduciam habes in \'gypto propter currus et equites?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Numquid sine Domini voluntate ascendi ad locum istum, ut demolirer eum? Dominus dixit mihi: Ascende ad terram hanc, et demolire eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Dixerunt autem Eliacim filius Helciæ, et Sobna, et Joahe Rabsaci: Precamur ut loquaris nobis servis tuis syriace: siquidem intelligimus hanc linguam: et non loquaris nobis judaice, audiente populo qui est super murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Responditque eis Rabsaces, dicens: Numquid ad dominum tuum, et ad te misit me dominus meus, ut loquerer sermones hos, et non potius ad viros qui sedent super murum, ut comedant stercora sua, et bibant urinam suam vobiscum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Stetit itaque Rabsaces, et exclamavit voce magna judaice, et ait: Audite verba regis magni, regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Hæc dicit rex: Non vos seducat Ezechias: non enim poterit eruere vos de manu mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'neque fiduciam vobis tribuat super Dominum, dicens: Eruens liberabit nos Dominus, et non tradetur civitas hæc in manu regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Nolite audire Ezechiam. Hæc enim dicit rex Assyriorum: Facite mecum quod vobis est utile, et egredimini ad me: et comedet unusquisque de vinea sua, et de ficu sua: et bibetis aquas de cisternis vestris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'donec veniam, et transferam vos in terram quæ similis est terræ vestræ, in terram fructiferam, et fertilem vini, terram panis et vinearum, terram olivarum et olei ac mellis: et vivetis, et non moriemini. Nolite audire Ezechiam, qui vos decipit, dicens: Dominus liberabit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Numquid liberaverunt dii gentium terram suam de manu regis Assyriorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'ubi est deus Emath, et Arphad? ubi est deus Sepharvaim, Ana, et Ava? numquid liberaverunt Samariam de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Quinam illi sunt in universis diis terrarum, qui eruerunt regionem suam de manu mea, ut possit eruere Dominus Jerusalem de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Tacuit itaque populus, et non respondit ei quidquam: siquidem præceptum regis acceperant ut non responderent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Venitque Eliacim filius Helciæ, præpositus domus, et Sobna scriba, et Joahe filius Asaph a commentariis ad Ezechiam scissis vestibus, et nuntiaverunt ei verba Rabsacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Quæ cum audisset Ezechias rex, scidit vestimenta sua, et opertus est sacco, ingressusque est domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Et misit Eliacim præpositum domus, et Sobnam scribam, et senes de sacerdotibus, opertos saccis, ad Isaiam prophetam filium Amos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Qui dixerunt: Hæc dicit Ezechias: Dies tribulationis, et increpationis, et blasphemiæ dies iste: venerunt filii usque ad partum, et vires non habet parturiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Si forte audiat Dominus Deus tuus universa verba Rabsacis, quem misit rex Assyriorum dominus suus ut exprobraret Deum viventem et argueret verbis, quæ audivit Dominus Deus tuus: et fac orationem pro reliquiis quæ repertæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Venerunt ergo servi regis Ezechiæ ad Isaiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Dixitque eis Isaias: Hæc dicetis domino vestro: Hæc dicit Dominus: Noli timere a facie sermonum quos audisti, quibus blasphemaverunt pueri regis Assyriorum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Ecce ego immittam ei spiritum, et audiet nuntium, et revertetur in terram suam, et dejiciam eum gladio in terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Reversus est ergo Rabsaces, et invenit regem Assyriorum expugnantem Lobnam: audierat enim quod recessisset de Lachis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Cumque audisset de Tharaca rege \'thiopiæ, dicentes: Ecce egressus est ut pugnet adversum te: et iret contra eum, misit nuntios ad Ezechiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Hæc dicite Ezechiæ regi Juda: Non te seducat Deus tuus in quo habes fiduciam, neque dicas: Non tradetur Jerusalem in manus regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Tu enim ipse audisti quæ fecerunt reges Assyriorum universis terris, quomodo vastaverunt eas: num ergo solus poteris liberari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Numquid liberaverunt dii gentium singulos quos vastaverunt patres mei, Gozan videlicet, et Haran, et Reseph, et filios Eden qui erant in Thelassar?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'ubi est rex Emath, et rex Arphad, et rex civitatis Sepharvaim, Ana, et Ava?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Itaque cum accepisset Ezechias litteras de manu nuntiorum, et legisset eas, ascendit in domum Domini, et expandit eas coram Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'et oravit in conspectu ejus, dicens: Domine Deus Israël, qui sedes super cherubim, tu es Deus solus regum omnium terræ: tu fecisti cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Inclina aurem tuam, et audi: aperi, Domine, oculos tuos, et vide: audi omnia verba Sennacherib, qui misit ut exprobraret nobis Deum viventem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Vere, Domine, dissipaverunt reges Assyriorum gentes, et terras omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Et miserunt deos eorum in ignem: non enim erant dii, sed opera manuum hominum, ex ligno et lapide: et perdiderunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Nunc igitur Domine Deus noster, salvos nos fac de manu ejus, ut sciant omnia regna terræ quia tu es Dominus Deus solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Misit autem Isaias filius Amos ad Ezechiam, dicens: Hæc dicit Dominus Deus Israël: Quæ deprecatus es me super Sennacherib rege Assyriorum, audivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Iste est sermo, quem locutus est Dominus de eo: Sprevit te, et subsannavit te, virgo filia Sion: post tergum tuum caput movit, filia Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Cui exprobrasti, et quem blasphemasti? contra quem exaltasti vocem tuam, et elevasti in excelsum oculos tuos? Contra Sanctum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Per manum servorum tuorum exprobrasti Domino, et dixisti: In multitudine curruum meorum ascendi excelsa montium in summitate Libani, et succidi sublimes cedros ejus, et electas abietes illius. Et ingressus sum usque ad terminos ejus, et saltum Carmeli ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'ego succidi. Et bibi aquas alienas, et siccavi vestigiis pedum meorum omnes aquas clausas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Numquid non audisti quid ab initio fecerim? ex diebus antiquis plasmavi illud, et nunc adduxi: eruntque in ruinam collium pugnantium civitates munitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Et qui sedent in eis, humiles manu, contremuerunt et confusi sunt: facti sunt velut fœnum agri, et virens herba tectorum, quæ arefacta est antequam veniret ad maturitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Habitaculum tuum, et egressum tuum, et introitum tuum, et viam tuam ego præscivi, et furorem tuum contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Insanisti in me, et superbia tua ascendit in aures meas: ponam itaque circulum in naribus tuis, et camum in labiis tuis, et reducam te in viam per quam venisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Tibi autem, Ezechia, hoc erit signum: comede hoc anno quæ repereris: in secundo autem anno, quæ sponte nascuntur: porro in tertio anno seminate et metite: plantate vineas, et comedite fructum earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Et quodcumque reliquum fuerit de domo Juda, mittet radicem deorsum, et faciet fructum sursum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'De Jerusalem quippe egredientur reliquiæ, et quod salvetur de monte Sion: zelus Domini exercituum faciet hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Quam ob rem hæc dicit Dominus de rege Assyriorum: Non ingredietur urbem hanc, nec mittet in eam sagittam, nec occupabit eam clypeus, nec circumdabit eam munitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Per viam qua venit, revertetur: et civitatem hanc non ingredietur, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Protegamque urbem hanc, et salvabo eam propter me, et propter David servum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Factum est igitur in nocte illa, venit angelus Domini, et percussit in castris Assyriorum centum octoginta quinque millia. Cumque diluculo surrexisset, vidit omnia corpora mortuorum: et recedens abiit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'et reversus est Sennacherib rex Assyriorum, et mansit in Ninive.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Cumque adoraret in templo Nesroch deum suum, Adramelech et Sarasar filii ejus percusserunt eum gladio, fugeruntque in terram Armeniorum: et regnavit Asarhaddon filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'In diebus illis ægrotavit Ezechias usque ad mortem: et venit ad eum Isaias filius Amos propheta, dixitque ei: Hæc dicit Dominus Deus: Præcipe domui tuæ: morieris enim tu, et non vives.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Qui convertit faciem suam ad parietem, et oravit Dominum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Obsecro, Domine: memento, quæso, quomodo ambulaverim coram te in veritate, et in corde perfecto, et quod placitum est coram te fecerim. Flevit itaque Ezechias fletu magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Et antequam egrederetur Isaias mediam partem atrii, factus est sermo Domini ad eum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Revertere, et dic Ezechiæ duci populi mei: Hæc dicit Dominus Deus David patris tui: Audivi orationem tuam, et vidi lacrimas tuas, et ecce sanavi te: die tertio ascendes templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Et addam diebus tuis quindecim annos: sed et de manu regis Assyriorum liberabo te, et civitatem hanc: et protegam urbem istam propter me, et propter David servum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Dixitque Isaias: Afferte massam ficorum. Quam cum attulissent, et posuissent super ulcus ejus, curatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Dixerat autem Ezechias ad Isaiam: Quod erit signum, quia Dominus me sanabit, et quia ascensurus sum die tertia templum Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Cui ait Isaias: Hoc erit signum a Domino quod facturus sit Dominus sermonem quem locutus est: vis ut ascendat umbra decem lineis, an ut revertatur totidem gradibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Et ait Ezechias: Facile est umbram crescere decem lineis: nec hoc volo ut fiat, sed ut revertatur retrorsum decem gradibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Invocavit itaque Isaias propheta Dominum, et reduxit umbram per lineas quibus jam descenderat in horologio Achaz, retrorsum decem gradibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'In tempore illo misit Berodach Baladan, filius Baladan, rex Babyloniorum, litteras et munera ad Ezechiam: audierat enim quod ægrotasset Ezechias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Lætatus est autem in adventu eorum Ezechias, et ostendit eis domum aromatum, et aurum et argentum, et pigmenta varia, unguenta quoque, et domum vasorum suorum, et omnia quæ habere poterat in thesauris suis. Non fuit quod non monstraret eis Ezechias in domo sua, et in omni potestate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Venit autem Isaias propheta ad regem Ezechiam, dixitque ei: Quid dixerunt viri isti? aut unde venerunt ad te? Cui ait Ezechias: De terra longinqua venerunt ad me, de Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'At ille respondit: Quid viderunt in domo tua? Ait Ezechias: Omnia quæcumque sunt in domo mea, viderunt: nihil est quod non monstraverim eis in thesauris meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Dixit itaque Isaias Ezechiæ: Audi sermonem Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Ecce dies venient, et auferentur omnia quæ sunt in domo tua, et quæ condiderunt patres tui usque in diem hanc, in Babylonem: non remanebit quidquam, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Sed et de filiis tuis qui egredientur ex te, quos generabis, tollentur, et erunt eunuchi in palatio regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Dixit Ezechias ad Isaiam: Bonus sermo Domini quem locutus es: sit pax et veritas in diebus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Reliqua autem sermonum Ezechiæ, et omnis fortitudo ejus, et quomodo fecerit piscinam et aquæductum, et introduxerit aquas in civitatem, nonne hæc scripta sunt in libro sermonum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Dormivitque Ezechias cum patribus suis, et regnavit Manasses filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Duodecim annorum erat Manasses cum regnare cœpisset, et quinquaginta quinque annis regnavit in Jerusalem: nomen matris ejus Haphsiba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Fecitque malum in conspectu Domini, juxta idola gentium quas delevit Dominus a facie filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Conversusque est, et ædificavit excelsa quæ dissipaverat Ezechias pater ejus: et erexit aras Baal, et fecit lucos sicut fecerat Achab rex Israël, et adoravit omnem militiam cæli, et coluit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Exstruxitque aras in domo Domini, de qua dixit Dominus: In Jerusalem ponam nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Et exstruxit altaria universæ militiæ cæli in duobus atriis templi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Et traduxit filium suum per ignem: et ariolatus est, et observavit auguria, et fecit pythones, et aruspices multiplicavit, ut faceret malum coram Domino, et irritaret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Posuit quoque idolum luci quem fecerat, in templo Domini, super quod locutus est Dominus ad David, et ad Salomonem filium ejus: In templo hoc, et in Jerusalem quam elegi de cunctis tribubus Israël, ponam nomen meum in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Et ultra non faciam commoveri pedem Israël de terra quam dedi patribus eorum: si tamen custodierint opere omnia quæ præcepi eis, et universam legem quam mandavit eis servus meus Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Illi vero non audierunt: sed seducti sunt a Manasse, ut facerent malum super gentes quas contrivit Dominus a facie filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Locutusque est Dominus in manu servorum suorum prophetarum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Quia fecit Manasses rex Juda abominationes istas pessimas, super omnia quæ fecerunt Amorrhæi ante eum, et peccare fecit etiam Judam in immunditiis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'propterea hæc dicit Dominus Deus Israël: Ecce ego inducam mala super Jerusalem et Judam, ut quicumque audierit, tinniant ambæ aures ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Et extendam super Jerusalem funiculum Samariæ, et pondus domus Achab: et delebo Jerusalem, sicut deleri solent tabulæ: et delens vertam, et ducam crebrius stylum super faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Dimittam vero reliquias hæreditatis meæ, et tradam eas in manus inimicorum ejus, eruntque in vastitatem, et in rapinam cunctis adversariis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'eo quod fecerint malum coram me, et perseveraverint irritantes me, ex die qua egressi sunt patres eorum ex \'gypto usque ad hanc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Insuper et sanguinem innoxium fudit Manasses multum nimis, donec impleret Jerusalem usque ad os: absque peccatis suis quibus peccare fecit Judam, ut faceret malum coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Reliqua autem sermonum Manasse, ut universa quæ fecit, et peccatum ejus quod peccavit, nonne hæc scripta sunt in libro sermonum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Dormivitque Manasses cum patribus suis, et sepultus est in horto domus suæ, in horto Oza: et regnavit Amon filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Viginti duorum annorum erat Amon cum regnare cœpisset: duobus quoque annis regnavit in Jerusalem: nomen matris ejus Messalemeth filia Harus de Jeteba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Fecitque malum in conspectu Domini, sicut fecerat Manasses pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Et ambulavit in omni via per quam ambulaverat pater ejus, servivitque immunditiis quibus servierat pater ejus, et adoravit eas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'et dereliquit Dominum Deum patrum suorum, et non ambulavit in via Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Tetenderuntque ei insidias servi sui, et interfecerunt regem in domo sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Percussit autem populus terræ omnes qui conjuraverant contra regem Amon, et constituerunt sibi regem Josiam filium ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Reliqua autem sermonum Amon quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Sepelieruntque eum in sepulchro suo, in horto Oza: et regnavit Josias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Octo annorum erat Josias cum regnare cœpisset: triginta et uno anno regnavit in Jerusalem: nomen matris ejus Idida filia Hadaia de Besecath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Fecitque quod placitum erat coram Domino, et ambulavit per omnes vias David patris sui: non declinavit ad dexteram, sive ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Anno autem octavodecimo regis Josiæ, misit rex Saphan filium Aslia filii Messulam scribam templi Domini, dicens ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Vade ad Helciam sacerdotem magnum, ut confletur pecunia quæ illata est in templum Domini, quam collegerunt janitores templi a populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'deturque fabris per præpositos domus Domini, qui et distribuant eam his qui operantur in templo Domini, ad instauranda sartatecta templi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'tignariis videlicet et cæmentariis, et iis qui interrupta componunt: et ut emantur ligna, et lapides de lapicidinis, ad instaurandum templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Verumtamen non supputetur eis argentum quod accipiunt, sed in potestate habeant, et in fide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Dixit autem Helcias pontifex ad Saphan scribam: Librum legis reperi in domo Domini. Deditque Helcias volumen Saphan, qui et legit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Venit quoque Saphan scriba ad regem, et renuntiavit ei quod præceperat, et ait: Conflaverunt servi tui pecuniam quæ reperta est in domo Domini, et dederunt ut distribueretur fabris a præfectis operum templi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Narravit quoque Saphan scriba regi, dicens: Librum dedit mihi Helcias sacerdos. Quem cum legisset Saphan coram rege,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'et audisset rex verba libri legis Domini, scidit vestimenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et præcepit Helciæ sacerdoti, et Ahicam filio Saphan, et Achobor filio Micha, et Saphan scribæ, et Asaiæ servo regis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Ite et consulite Dominum super me, et super populo, et super omni Juda, de verbis voluminis istius, quod inventum est: magna enim ira Domini succensa est contra nos, quia non audierunt patres nostri verba libri hujus, ut facerent omne quod scriptum est nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Ierunt itaque Helcias sacerdos, et Ahicam, et Achobor, et Sapham, et Asaia, ad Holdam prophetidem, uxorem Sellum filii Thecuæ filii Araas custodis vestium, quæ habitabat in Jerusalem in Secunda: locutique sunt ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et illa respondit eis: Hæc dicit Dominus Deus Israël: Dicite viro qui misit vos ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Hæc dicit Dominus: Ecce ego adducam mala super locum istum, et super habitatores ejus, omnia verba legis quæ legit rex Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'quia dereliquerunt me, et sacrificaverunt diis alienis, irritantes me in cunctis operibus manuum suarum: et succendetur indignatio mea in loco hoc, et non extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Regi autem Juda, qui misit vos ut consuleretis Dominum, sic dicetis: Hæc dicit Dominus Deus Israël: Pro eo quod audisti verba voluminis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'et perterritum est cor tuum, et humiliatus es coram Domino, auditis sermonibus contra locum istum et habitatores ejus, quod videlicet fierent in stuporem et in maledictum: et scidisti vestimenta tua, et flevisti coram me, et ego audivi, ait Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'idcirco colligam te ad patres tuos, et colligeris ad sepulchrum tuum in pace, ut non videant oculi tui omnia mala quæ inducturus sum super locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Et renuntiaverunt regi quod dixerat. Qui misit: et congregati sunt ad eum omnes senes Juda et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Ascenditque rex templum Domini, et omnes viri Juda, universique qui habitabant in Jerusalem cum eo sacerdotes et prophetæ, et omnis populus a parvo usque ad magnum: legitque, cunctis audientibus, omnia verba libri fœderis, qui inventus est in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Stetitque rex super gradum: et fœdus percussit coram Domino, ut ambularent post Dominum, et custodirent præcepta ejus, et testimonia, et cæremonias in omni corde, et in tota anima, et suscitarent verba fœderis hujus, quæ scripta erant in libro illo: acquievitque populus pacto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Et præcepit rex Helciæ pontifici, et sacerdotibus secundi ordinis, et janitoribus, ut projicerent de templo Domini omnia vasa quæ facta fuerant Baal, et in luco, et universæ militiæ cæli: et combussit ea foris Jerusalem in convalle Cedron, et tulit pulverem eorum in Bethel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Et delevit aruspices quos posuerant reges Juda ad sacrificandum in excelsis per civitates Juda, et in circuitu Jerusalem: et eos qui adolebant incensum Baal, et soli, et lunæ, et duodecim signis, et omni militiæ cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Et efferri fecit lucum de domo Domini foras Jerusalem in convalle Cedron, et combussit eum ibi, et redegit in pulverem, et projecit super sepulchra vulgi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Destruxit quoque ædiculas effeminatorum quæ erant in domo Domini, pro quibus mulieres texebant quasi domunculas luci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Congregavitque omnes sacerdotes de civitatibus Juda, et contaminavit excelsa ubi sacrificabant sacerdotes de Gabaa usque Bersabee, et destruxit aras portarum in introitu ostii Josue principis civitatis, quod erat ad sinistram portæ civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Verumtamen non ascendebant sacerdotes excelsorum ad altare Domini in Jerusalem: sed tantum comedebant azyma in medio fratrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Contaminavit quoque Topheth, quod est in convalle filii Ennom, ut nemo consecraret filium suum aut filiam per ignem, Moloch.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Abstulit quoque equos quos dederant reges Juda soli in introitu templi Domini juxta exedram Nathanmelech eunuchi, qui erat in Pharurim: currus autem solis combussit igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Altaria quoque quæ erant super tecta cœnaculi Achaz, quæ fecerant reges Juda, et altaria quæ fecerat Manasses in duobus atriis templi Domini, destruxit rex, et cucurrit inde, et dispersit cinerem eorum in torrentem Cedron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Excelsa quoque, quæ erant in Jerusalem ad dexteram partem montis offensionis, quæ ædificaverat Salomon rex Israël Astaroth idolo Sidoniorum, et Chamos offensioni Moab, et Melchom abominationi filiorum Ammon, polluit rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Et contrivit statuas, et succidit lucos: replevitque loca eorum ossibus mortuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Insuper et altare quod erat in Bethel, et excelsum quod fecerat Jeroboam filius Nabat, qui peccare fecit Israël: et altare illud, et excelsum destruxit, atque combussit, et comminuit in pulverem, succenditque etiam lucum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Et conversus Josias, vidit ibi sepulchra quæ erant in monte: misitque et tulit ossa de sepulchris, et combussit ea super altare, et polluit illud juxta verbum Domini quod locutus est vir Dei, qui prædixerat verba hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et ait: Quis est titulus ille, quem video? Responderuntque ei cives urbis illius: Sepulchrum est hominis Dei, qui venit de Juda, et prædixit verba hæc, quæ fecisti super altare Bethel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et ait: Dimitte eum: nemo commoveat ossa ejus. Et intacta manserunt ossa illius cum ossibus prophetæ qui venerat de Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Insuper et omnia fana excelsorum quæ erant in civitatibus Samariæ, quæ fecerant reges Israël ad irritandum Dominum, abstulit Josias: et fecit eis secundum omnia opera quæ fecerat in Bethel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et occidit universos sacerdotes excelsorum qui erant ibi super altaria, et combussit ossa humana super ea: reversusque est Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Et præcepit omni populo, dicens: Facite Phase Domino Deo vestro, secundum quod scriptum est in libro fœderis hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Nec enim factum est Phase tale a diebus judicum qui judicaverunt Israël, et omnium dierum regum Israël et regum Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'sicut in octavodecimo anno regis Josiæ factum est Phase istud Domino in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Sed et pythones, et ariolos, et figuras idolorum, et immunditias, et abominationes, quæ fuerant in terra Juda et Jerusalem, abstulit Josias: ut statueret verba legis quæ scripta sunt in libro quem invenit Helcias sacerdos in templo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Similis illi non fuit ante eum rex, qui reverteretur ad Dominum in omni corde suo, et in tota anima sua, et in universa virtute sua juxta omnem legem Moysi: neque post eum surrexit similis illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Verumtamen non est aversus Dominus ab ira furoris sui magni quo iratus est furor ejus contra Judam propter irritationes quibus provocaverat eum Manasses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Dixit itaque Dominus: Etiam Judam auferam a facie mea, sicut abstuli Israël: et projiciam civitatem hanc quam elegi Jerusalem, et domum de qua dixi: Erit nomen meum ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Reliqua autem sermonum Josiæ, et universa quæ fecit, nonne hæc scripta sunt in libro verborum dierum regum Juda?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'In diebus ejus ascendit Pharao Nechao rex \'gypti contra regem Assyriorum ad flumen Euphraten, et abiit Josias rex in occursum ejus: et occisus est in Mageddo cum vidisset eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Et portaverunt eum servi sui mortuum de Mageddo: et pertulerunt in Jerusalem, et sepelierunt eum in sepulchro suo. Tulitque populus terræ Joachaz filium Josiæ: et unxerunt eum, et constituerunt eum regem pro patre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Viginti trium annorum erat Joachaz cum regnare cœpisset, et tribus mensibus regnavit in Jerusalem: nomen matris ejus Amital filia Jeremiæ de Lobna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Et fecit malum coram Domino, juxta omnia quæ fecerant patres ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Vinxitque eum Pharao Nechao in Rebla, quæ est in terra Emath, ne regnaret in Jerusalem: et imposuit mulctam terræ centum talentis argenti, et talento auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Regemque constituit Pharao Nechao Eliacim filium Josiæ pro Josia patre ejus: vertitque nomen ejus Joakim. Porro Joachaz tulit, et duxit in \'gyptum, et mortuus est ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Argentum autem et aurum dedit Joakim Pharaoni, cum indixisset terræ per singulos, ut conferretur juxta præceptum Pharaonis: et unumquemque juxta vires suas exegit, tam argentum quam aurum, de populo terræ, ut daret Pharaoni Nechao.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Viginti quinque annorum erat Joakim cum regnare cœpisset, et undecim annis regnavit in Jerusalem: nomen matris ejus Zebida filia Phadaia de Ruma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Et fecit malum coram Domino juxta omnia quæ fecerant patres ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'In diebus ejus ascendit Nabuchodonosor rex Babylonis, et factus est ei Joakim servus tribus annis: et rursum rebellavit contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Immisitque ei Dominus latrunculos Chaldæorum, et latrunculos Syriæ, et latrunculos Moab, et latrunculos filiorum Ammon: et immisit eos in Judam ut disperderent eum, juxta verbum Domini quod locutus fuerat per servos suos prophetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Factum est autem hoc per verbum Domini contra Judam, ut auferret eum coram se propter peccata Manasse universa quæ fecit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'et propter sanguinem innoxium quem effudit, et implevit Jerusalem cruore innocentium: et ob hanc rem noluit Dominus propitiari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Reliqua autem sermonum Joakim, et universa quæ fecit, nonne hæc scripta sunt in libro sermonum dierum regum Juda? Et dormivit Joakim cum patribus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'et regnavit Joachin filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Et ultra non addidit rex \'gypti ut egrederetur de terra sua: tulerat enim rex Babylonis, a rivo \'gypti usque ad fluvium Euphraten, omnia quæ fuerant regis \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Decem et octo annorum erat Joachin cum regnare cœpisset, et tribus mensibus regnavit in Jerusalem: nomen matris ejus Nohesta filia Elnathan de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Et fecit malum coram Domino, juxta omnia quæ fecerat pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'In tempore illo ascenderunt servi Nabuchodonosor regis Babylonis in Jerusalem, et circumdata est urbs munitionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Venitque Nabuchodonosor rex Babylonis ad civitatem cum servis suis ut oppugnarent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Egressusque est Joachin rex Juda ad regem Babylonis, ipse et mater ejus, et servi ejus, et principes ejus, et eunuchi ejus: et suscepit eum rex Babylonis anno octavo regni sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et protulit inde omnes thesauros domus Domini, et thesauros domus regiæ: et concidit universa vasa aurea quæ fecerat Salomon rex Israël in templo Domini juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et transtulit omnem Jerusalem, et universos principes, et omnes fortes exercitus, decem millia, in captivitatem, et omnem artificem et clusorem: nihilque relictum est, exceptis pauperibus populi terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Transtulit quoque Joachin in Babylonem, et matrem regis, et uxores regis, et eunuchos ejus: et judices terræ duxit in captivitatem de Jerusalem in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Et omnes viros robustos, septem millia, et artifices, et clusores mille, omnes viros fortes et bellatores: duxitque eos rex Babylonis captivos in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et constituit Matthaniam patruum ejus pro eo: imposuitque nomen ei Sedeciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Vigesimum et primum annum ætatis habebat Sedecias cum regnare cœpisset, et undecim annis regnavit in Jerusalem: nomen matris ejus erat Amital filia Jeremiæ de Lobna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Et fecit malum coram Domino, juxta omnia quæ fecerat Joakim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Irascebatur enim Dominus contra Jerusalem et contra Judam, donec projiceret eos a facie sua: recessitque Sedecias a rege Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Factum est autem anno nono regni ejus, mense decimo, decima die mensis, venit Nabuchodonosor rex Babylonis, ipse et omnis exercitus ejus, in Jerusalem, et circumdederunt eam: et exstruxerunt in circuitu ejus munitiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et clausa est civitas atque vallata usque ad undecimum annum regis Sedeciæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'nona die mensis: prævaluitque fames in civitate, nec erat panis populo terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Et interrupta est civitas: et omnes viri bellatores nocte fugerunt per viam portæ quæ est inter duplicem murum ad hortum regis. Porro Chaldæi obsidebant in circuitu civitatem. Fugit itaque Sedecias per viam quæ ducit ad campestria solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Et persecutus est exercitus Chaldæorum regem, comprehenditque eum in planitie Jericho: et omnes bellatores qui erant cum eo, dispersi sunt, et reliquerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Apprehensum ergo regem duxerunt ad regem Babylonis in Reblatha: qui locutus est cum eo judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Filios autem Sedeciæ occidit coram eo, et oculos ejus effodit, vinxitque eum catenis, et adduxit in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Mense quinto, septima die mensis, ipse est annus nonusdecimus regis Babylonis, venit Nabuzardan princeps exercitus, servus regis Babylonis, in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Et succendit domum Domini, et domum regis: et domos Jerusalem, omnemque domum combussit igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Et muros Jerusalem in circuitu destruxit omnis exercitus Chaldæorum, qui erat cum principe militum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Reliquam autem populi partem quæ remanserat in civitate, et perfugas qui transfugerant ad regem Babylonis, et reliquum vulgus transtulit Nabuzardan princeps militiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Et de pauperibus terræ reliquit vinitores et agricolas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Columnas autem æreas quæ erant in templo Domini, et bases, et mare æreum quod erat in domo Domini, confregerunt Chaldæi, et transtulerunt æs omne in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ollas quoque æreas, et trullas, et tridentes, et scyphos, et mortariola, et omnia vasa ærea, in quibus ministrabant, tulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Necnon et thuribula, et phialas: quæ aurea, aurea, et quæ argentea, argentea tulit princeps militiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'id est, columnas duas, mare unum, et bases quas fecerat Salomon in templo Domini: non erat pondus æris omnium vasorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Decem et octo cubitos altitudinis habebat columna una: et capitellum æreum super se altitudinis trium cubitorum: et retiaculum, et malogranata super capitellum columnæ, omnia ærea: similem et columna secunda habebat ornatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Tulit quoque princeps militiæ Saraiam sacerdotem primum, et Sophoniam sacerdotem secundum, et tres janitores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Et de civitate eunuchum unum, qui erat præfectus super bellatores viros: et quinque viros de his qui steterant coram rege, quos reperit in civitate: et Sopher principem exercitus, qui probabat tyrones de populo terræ: et sexaginta viros e vulgo, qui inventi fuerant in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Quos tollens Nabuzardan princeps militum, duxit ad regem Babylonis in Reblatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Percussitque eos rex Babylonis, et interfecit eos in Reblatha in terra Emath: et translatus est Juda de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Populo autem qui relictus erat in terra Juda, quem dimiserat Nabuchodonosor rex Babylonis, præfecit Godoliam filium Ahicam filii Saphan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Quod cum audissent omnes duces militum, ipsi et viri qui erant cum eis, videlicet quod constituisset rex Babylonis Godoliam, venerunt ad Godoliam in Maspha, Ismahel filius Nathaniæ, et Johanan filius Caree, et Saraia filius Thanehumeth Netophathites, et Jezonias filius Maachathi, ipsi et socii eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Juravitque Godolias ipsis et sociis eorum, dicens: Nolite timere servire Chaldæis: manete in terra, et servite regi Babylonis, et bene erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Factum est autem in mense septimo, venit Ismahel filius Nathaniæ filii Elisama de semine regio, et decem viri cum eo: percusseruntque Godoliam, qui et mortuus est: sed et Judæos et Chaldæos qui erant cum eo in Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Consurgensque omnis populus a parvo usque ad magnum, et principes militum, venerunt in \'gyptum timentes Chaldæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Factum est vero in anno trigesimo septimo transmigrationis Joachin regis Juda, mense duodecimo, vigesima septima die mensis: sublevavit Evilmerodach rex Babylonis, anno quo regnare cœperat, caput Joachin regis Juda de carcere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Et locutus est ei benigne, et posuit thronum ejus super thronum regum qui erant cum eo in Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Et mutavit vestes ejus quas habuerat in carcere, et comedebat panem semper in conspectu ejus cunctis diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Annonam quoque constituit ei sine intermissione, quæ et dabatur ei a rege per singulos dies omnibus diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Cainan, Malaleel, Jared,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Mathusale, Lamech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noë, Sem, Cham, et Japtheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Filii Japheth: Gomer, et Magog, et Madai, et Javan, Thubal, Mosoch, Thiras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Porro filii Gomer: Ascenez, et Riphath, et Thogorma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Filii autem Javan: Elisa et Tharsis, Cethim et Dodanim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Filii Cham: Chus, et Mesraim, et Phut, et Chanaan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Filii autem Chus: Saba, et Hevila, Sabatha, et Regma, et Sabathacha. Porro filii Regma: Saba, et Dadan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Chus autem genuit Nemrod: iste cœpit esse potens in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mesraim vero genuit Ludim, et Anamim, et Laabim, et Nephtuim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Phetrusim quoque, et Casluim: de quibus egressi sunt Philisthiim, et Caphtorim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Chanaan vero genuit Sidonem primogenitum suum, Hethæum quoque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'et Jebusæum, et Amorrhæum, et Gergesæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hevæumque et Aracæum, et Sinæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Aradium quoque, et Samaræum, et Hamathæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Filii Sem: \'lam, et Assur, et Arphaxad, et Lud, et Aram, et Hus, et Hul, et Gether, et Mosoch.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arphaxad autem genuit Sale, qui et ipse genuit Heber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Porro Heber nati sunt duo filii: nomen uni Phaleg, quia in diebus ejus divisa est terra; et nomen fratris ejus Jectan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Jectan autem genuit Elmodad, et Saleph, et Asarmoth, et Jare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Adoram quoque, et Huzal, et Decla,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Hebal etiam, et Abimaël, et Saba, necnon');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'et Ophir, et Hevila, et Jobab: omnes isti filii Jectan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphaxad, Sale,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Phaleg, Ragau,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nachor, Thare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram: iste est Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Filii autem Abraham, Isaac et Ismahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Et hæ generationes eorum. Primogenitus Ismahelis, Nabaioth, et Cedar, et Adbeel, et Mabsam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'et Masma, et Duma, Massa, Hadad, et Thema,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphis, Cedma: hi sunt filii Ismahelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Filii autem Ceturæ concubinæ Abraham, quos genuit: Zamran, Jecsan, Madan, Madian, Jesboc, et Sue. Porro filii Jecsan: Saba, et Dadan. Filii autem Dadan: Assurim, et Latussim, et Laomim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Filii autem Madian: Epha, et Epher, et Henoch, et Abida, et Eldaa: omnes hi filii Ceturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Genuit autem Abraham Isaac: cujus fuerunt filii Esau, et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Filii Esau: Eliphaz, Rahuel, Jehus, Ihelom, et Core.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Filii Eliphaz: Theman, Omar, Sephi, Gathan, Cenez, Thamna, Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Filii Rahuel: Nahath, Zara, Samma, Meza.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Filii Seir: Lotan, Sobal, Sebeon, Ana, Dison, Eser, Disan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Filii Lotan: Hori, Homam. Soror autem Lotan fuit Thamna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Filii Sobal: Alian, et Manahath, et Ebal, Sephi et Onam. Filii Sebeon: Aja et Ana. Filii Ana: Dison.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Filii Dison: Hamram, et Heseban, et Jethran, et Charan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Filii Eser: Balaan, et Zavan, et Jacan. Filii Disan: Hus et Aran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Isti sunt reges qui imperaverunt in terra Edom, antequam esset rex super filios Israël. Bale filius Beor: et nomen civitatis ejus, Denaba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Mortuus est autem Bale, et regnavit pro eo Jobab filius Zare de Bosra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Cumque et Jobab fuisset mortuus, regnavit pro eo Husam de terra Themanorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Obiit quoque et Husam, et regnavit pro eo Adad filius Badad, qui percussit Madian in terra Moab: et nomen civitatis ejus Avith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Cumque et Adad fuisset mortuus, regnavit pro eo Semla de Masreca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Sed et Semla mortuus est, et regnavit pro eo Saul de Rohoboth, quæ juxta amnem sita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Mortuo quoque Saul, regnavit pro eo Balanan filius Achobor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Sed et hic mortuus est, et regnavit pro eo Adad: cujus urbis nomen fuit Phau, et appellata est uxor ejus Meetabel filia Matred filiæ Mezaab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Adad autem mortuo, duces pro regibus in Edom esse cœperunt: dux Thamna, dux Alva, dux Jetheth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'dux Oolibama, dux Ela, dux Phinon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'dux Cenez, dux Theman, dux Mabsar,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'dux Magdiel, dux Hiram: hi duces Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Filii autem Israël: Ruben, Simeon, Levi, Juda, Issachar, et Zabulon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, Benjamin, Nephthali, Gad, et Aser.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Filii Juda: Her, Onan, et Sela: hi tres nati sunt ei de filia Sue Chananitide. Fuit autem Her primogenitus Juda malus coram Domino, et occidit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Thamar autem nurus ejus peperit ei Phares et Zara: omnes ergo filii Juda, quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Filii autem Phares: Hesron et Hamul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Filii quoque Zaræ: Zamri, et Ethan, et Eman, Chalchal quoque, et Dara, simul quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Filii Charmi: Achar, qui turbavit Israël, et peccavit in furto anathematis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Filii Ethan: Azarias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Filii autem Hesron qui nati sunt ei: Jerameel, et Ram, et Calubi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Porro Ram genuit Aminadab. Aminadab autem genuit Nahasson, principem filiorum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahasson quoque genuit Salma, de quo ortus est Booz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Booz vero genuit Obed, qui et ipse genuit Isai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai autem genuit primogenitum Eliab, secundum Abinadab, tertium Simmaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'quartum Nathanaël, quintum Raddai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'sextum Asom, septimum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Quorum sorores fuerunt Sarvia et Abigail. Filii Sarviæ: Abisai, Joab, et Asaël, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail autem genuit Amasa, cujus pater fuit Jether Ismahelites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Caleb vero filius Hesron accepit uxorem nomine Azuba, de qua genuit Jerioth: fueruntque filii ejus Jaser, et Sobab, et Ardon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Cumque mortua fuisset Azuba, accepit uxorem Caleb Ephratha, quæ peperit ei Hur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Porro Hur genuit Uri, et Uri genuit Bezeleel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Post hæc ingressus est Hesron ad filiam Machir patris Galaad, et accepit eam cum esset annorum sexaginta: quæ peperit ei Segub.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Sed et Segub genuit Jair, et possedit viginti tres civitates in terra Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Cepitque Gessur et Aram oppida Jair, et Canath, et viculos ejus sexaginta civitatum: omnes isti filii Machir patris Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Cum autem mortuus esset Hesron, ingressus est Caleb ad Ephratha. Habuit quoque Hesron uxorem Abia, quæ peperit ei Assur patrem Thecuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Nati sunt autem filii Jerameel primogeniti Hesron, Ram primogenitus ejus, et Buna, et Aram, et Asom, et Achia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Duxit quoque uxorem alteram Jerameel, nomine Atara, quæ fuit mater Onam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Sed et filii Ram primogeniti Jerameel fuerunt Moos, Jamin, et Achar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Onam autem habuit filios Semei et Jada. Filii autem Semei: Nadab et Abisur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Nomen vero uxoris Abisur, Abihail, quæ peperit ei Ahobban et Molid.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Filii autem Nadab fuerunt Saled et Apphaim. Mortuus est autem Saled absque liberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Filius vero Apphaim, Jesi: qui Jesi genuit Sesan. Porro Sesan genuit Oholai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Filii autem Jada fratris Semei: Jether, et Jonathan. Sed et Jether mortuus est absque liberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Porro Jonathan genuit Phaleth, et Ziza. Isti fuerunt filii Jerameel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesan autem non habuit filios, sed filias: et servum ægyptium nomine Jeraa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Deditque ei filiam suam uxorem: quæ peperit ei Ethei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Ethei autem genuit Nathan, et Nathan genuit Zabad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad quoque genuit Ophlal, et Ophlal genuit Obed.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed genuit Jehu, Jehu genuit Azariam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarias genuit Helles, et Helles genuit Elasa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa genuit Sisamoi, Sisamoi genuit Sellum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sellum genuit Icamiam, Icamia autem genuit Elisama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Filii autem Caleb fratris Jerameel: Mesa primogenitus ejus; ipse est pater Ziph: et filii Maresa patris Hebron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Porro filii Hebron, Core, et Taphua, et Recem, et Samma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Samma autem genuit Raham, patrem Jercaam, et Recem genuit Sammai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Filius Sammai, Maon: et Maon pater Bethsur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Epha autem concubina Caleb peperit Haran, et Mosa, et Gezez. Porro Haran genuit Gezez.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Filii autem Jahaddai, Regom, et Joathan, et Gesan, et Phalet, et Epha, et Saaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Concubina Caleb Maacha, peperit Saber, et Tharana.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Genuit autem Saaph pater Madmena Sue, patrem Machbena et patrem Gabaa. Filia vero Caleb fuit Achsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Hi erant filii Caleb, filii Hur primogeniti Ephratha, Sobal pater Cariathiarim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma pater Bethlehem, Hariph pater Bethgader.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Fuerunt autem filii Sobal patris Cariathiarim, qui videbat dimidium requietionum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Et de cognatione Cariathiarim, Jethrei, et Aphuthei, et Semathei, et Maserei. Ex his egressi sunt Saraitæ, et Esthaolitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Filii Salma, Bethlehem, et Netophathi, coronæ domus Joab, et dimidium requietionis Sarai:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'cognationes quoque scribarum habitantium in Jabes, canentes atque resonantes, et in tabernaculis commorantes. Hi sunt Cinæi, qui venerunt de Calore patris domus Rechab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'David vero hos habuit filios, qui ei nati sunt in Hebron: primogenitum Amnon ex Achinoam Jezrahelitide, secundum Daniel de Abigail Carmelitide,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'tertium Absalom filium Maacha filiæ Tholmai regis Gessur, quartum Adoniam filium Aggith,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'quintum Saphathiam ex Abital, sextum Jethraham de Egla uxore sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Sex ergo nati sunt ei in Hebron, ubi regnavit septem annis et sex mensibus. Triginta autem et tribus annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Porro in Jerusalem nati sunt ei filii, Simmaa, et Sobab, et Nathan, et Salomon, quatuor de Bethsabee filia Ammiel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Jebaar quoque et Elisama,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'et Eliphaleth, et Noge, et Nepheg, et Japhia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'necnon Elisama, et Eliada, et Elipheleth, novem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'omnes hi, filii David absque filiis concubinarum: habueruntque sororem Thamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Filius autem Salomonis, Roboam: cujus Abia filius genuit Asa. De hoc quoque natus est Josaphat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'pater Joram: qui Joram genuit Ochoziam, ex quo ortus est Joas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'et hujus Amasias filius genuit Azariam. Porro Azariæ filius Joatham');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'procreavit Achaz patrem Ezechiæ, de quo natus est Manasses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Sed et Manasses genuit Amon patrem Josiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Filii autem Josiæ fuerunt: primogenitus Johanan, secundus Joakim, tertius Sedecias, quartus Sellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'De Joakim natus est Jechonias, et Sedecias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Filii Jechoniæ fuerunt: Asir, Salathiel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Melchiram, Phadaia, Senneser, et Jecemia, Sama, et Nadabia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'De Phadaia orti sunt Zorobabel et Semei. Zorobabel genuit Mosollam, Hananiam, et Salomith sororem eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Hasaban quoque, et Ohol, et Barachian, et Hasadian, Josabhesed, quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Filius autem Hananiæ, Phaltias pater Jeseiæ, cujus filius Raphaia: hujus quoque filius, Arnan, de quo natus est Obdia, cujus filius fuit Sechenias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Filius Secheniæ, Semeia: cujus filii Hattus, et Jegaal, et Baria, et Naaria, et Saphat, sex numero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Filius Naariæ, Elioënai, et Ezechias, et Ezricam, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Filii Elioënai, Oduia, et Eliasub, et Pheleia, et Accub, et Johanan, et Dalaia, et Anani, septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Filii Juda: Phares, Hesron, et Charmi, et Hur, et Sobal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Raia vero filius Sobal genuit Jahath, de quo nati sunt Ahumai, et Laad: hæ cognationes Sarathi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ista quoque stirps Etam: Jezrahel, et Jesema, et Jedebos. Nomen quoque sororis eorum, Asalelphuni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Phanuel autem pater Gedor, et Ezer pater Hosa: isti sunt filii Hur primogeniti Ephratha patris Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Assur vero patri Thecuæ erant duæ uxores, Halaa et Naara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Peperit autem ei Naara, Oozam, et Hepher, et Themani, et Ahasthari: isti sunt filii Naara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Porro filii Halaa, Sereth, Isaar et Ethnan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Cos autem genuit Anob, et Soboba, et cognationem Aharehel filii Arum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Fuit autem Jabes inclytus præ fratribus suis, et mater ejus vocavit nomen illius Jabes, dicens: Quia peperi eum in dolore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Invocavit vero Jabes Deum Israël, dicens: Si benedicens benedixeris mihi, et dilataveris terminos meos, et fuerit manus tua mecum, et feceris me a malitia non opprimi. Et præstitit Deus quæ precatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Caleb autem frater Sua genuit Mahir, qui fuit pater Esthon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Porro Esthon genuit Bethrapha, et Phesse, et Tehinna patrem urbis Naas: hi sunt viri Recha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Filii autem Cenez, Othoniel, et Saraia. Porro filii Othoniel, Hathath, et Maonathi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Maonathi genuit Ophra, Saraia autem genuit Joab patrem Vallis artificum: ibi quippe artifices erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Filii vero Caleb filii Jephone, Hir, et Ela, et Naham. Filii quoque Ela: Cenez.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Filii quoque Jaleleel: Ziph, et Zipha, Thiria, et Asraël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Et filii Ezra, Jether, et Mered, et Epher, et Jalon, genuitque Mariam, et Sammai, et Jesba patrem Esthamo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Uxor quoque ejus Judaia, peperit Jared patrem Gedor, et Heber patrem Socho, et Icuthiel patrem Zanoë: hi autem filii Bethiæ filiæ Pharaonis, quam accepit Mered.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Et filii uxoris Odaiæ sororis Naham patris Ceila, Garmi, et Esthamo, qui fuit de Machathi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Filii quoque Simon, Amnon, et Rinna filius Hanan, et Thilon. Et filii Jesi, Zoheth, et Benzoheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Filii Sela, filii Juda: Her pater Lecha, et Laada pater Maresa, et cognationes domus operantium byssum in domo juramenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Et qui stare fecit solem, virique Mendacii, et Securus, et Incendens, qui principes fuerunt in Moab, et qui reversi sunt in Lahem: hæc autem verba vetera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Hi sunt figuli habitantes in plantationibus et in sepibus, apud regem in operibus ejus: commoratique sunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Filii Simeon: Namuel et Jamin, Jarib, Zara, Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Sellum filius ejus, Mapsam filius ejus, Masma filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Filii Masma: Hamuel filius ejus, Zachur filius ejus, Semei filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Filii Semei sedecim, et filiæ sex: fratres autem ejus non habuerunt filios multos, et universa cognatio non potuit adæquare summam filiorum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Habitaverunt autem in Bersabee, et Molada, et Hasarsuhal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'et in Bala, et in Asom, et in Tholad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'et in Bathuel, et in Horma, et in Siceleg,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'et in Bethmarchaboth, et in Hasarsusim, et in Bethberai, et in Saarim: hæ civitates eorum usque ad regem David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Villæ quoque eorum: Etam, et Aën, Remmon, et Thochen, et Asan, civitates quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Et universi viculi eorum per circuitum civitatum istarum usque ad Baal: hæc est habitatio eorum, et sedium distributio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Mosobab quoque et Jemlech, et Josa filius Amasiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'et Joël, et Jehu filius Josabiæ filii Saraiæ filii Asiel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'et Elioënai, et Jacoba, et Isuhaia, et Asaia, et Adiel, et Ismiel, et Banaia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ziza quoque filius Sephei filii Allon filii Idaia filii Semri filii Samaia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Isti sunt nominati principes in cognationibus suis, et in domo affinitatum suarum multiplicati sunt vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et profecti sunt ut ingrederentur in Gador usque ad orientem vallis, et ut quærerent pascua gregibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Inveneruntque pascuas uberes, et valde bonas, et terram latissimam et quietam et fertilem, in qua ante habitaverant de stirpe Cham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Hi ergo venerunt, quos supra descripsimus nominatim, in diebus Ezechiæ regis Juda: et percusserunt tabernacula eorum, et habitatores qui inventi fuerant ibi, et deleverunt eos usque in præsentem diem: habitaveruntque pro eis, quoniam uberrimas pascuas ibidem repererunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'De filiis quoque Simeon abierunt in montem Seir viri quingenti, habentes principes Phalthiam et Naariam et Raphaiam et Oziel filios Jesi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'et percusserunt reliquias, quæ evadere potuerant, Amalecitarum, et habitaverunt ibi pro eis usque ad diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Filii quoque Ruben primogeniti Israël. (Ipse quippe fuit primogenitus ejus: sed cum violasset thorum patris sui, data sunt primogenita ejus filiis Joseph filii Israël, et non est ille reputatus in primogenitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Porro Judas, qui erat fortissimus inter fratres suos, de stirpe ejus principes germinati sunt: primogenita autem reputata sunt Joseph.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Filii ergo Ruben primogeniti Israël: Enoch, et Phallu, Esron, et Carmi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Filii Joël: Samia filius ejus, Gog filius ejus, Semei filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Micha filius ejus, Reia filius ejus, Baal filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Beera filius ejus, quem captivum duxit Thelgathphalnasar rex Assyriorum, et fuit princeps in tribu Ruben.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Fratres autem ejus, et universa cognatio ejus, quando numerabantur per familias suas, habuerunt principes Jehiel, et Zachariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Porro Bala filius Azaz filii Samma filii Joël, ipse habitavit in Aroër usque ad Nebo, et Beelmeon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Contra orientalem quoque plagam habitavit usque ad introitum eremi, et flumen Euphraten. Multum quippe jumentorum numerum possidebant in terra Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'In diebus autem Saul præliati sunt contra Agareos, et interfecerunt illos, habitaveruntque pro eis in tabernaculis eorum, in omni plaga quæ respicit ad orientem Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Filii vero Gad e regione eorum habitaverunt in terra Basan usque Selcha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joël in capite, et Saphan secundus: Janai autem et Saphat in Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Fratres vero eorum secundum domos cognationum suarum, Michaël, et Mosollam, et Sebe, et Jorai, et Jachan, et Zie, et Heber, septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Hi filii Abihail, filii Huri, filii Jara, filii Galaad, filii Michaël, filii Jesesi, filii Jeddo, filii Buz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Fratres quoque, filii Abdiel filii Guni, princeps domus in familiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Et habitaverunt in Galaad, et in Basan, et in viculis ejus, et in cunctis suburbanis Saron, usque ad terminos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Omnes hi numerati sunt in diebus Joathan regis Juda, et in diebus Jeroboam regis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Filii Ruben, et Gad, et dimidiæ tribus Manasse, viri bellatores, scuta portantes et gladios, et tendentes arcum, eruditique ad prælia, quadraginta quatuor millia et septingenti sexaginta, procedentes ad pugnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Dimicaverunt contra Agareos: Ituræi vero, et Naphis, et Nodab');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'præbuerunt eis auxilium. Traditique sunt in manus eorum Agarei, et universi qui fuerant cum eis, quia Deum invocaverunt cum præliarentur: et exaudivit eos, eo quod credidissent in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Ceperuntque omnia quæ possederant, camelorum quinquaginta millia, et ovium ducenta quinquaginta millia, et asinos duo millia, et animas hominum centum millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Vulnerati autem multi corruerunt: fuit enim bellum Domini. Habitaveruntque pro eis usque ad transmigrationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Filii quoque dimidiæ tribus Manasse possederunt terram a finibus Basan usque Baal, Hermon, et Sanir, et montem Hermon: ingens quippe numerus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et hi fuerunt principes domus cognationis eorum: Epher, et Jesi, et Eliel, et Ezriel, et Jeremia, et Odoia, et Jediel, viri fortissimi et potentes, et nominati duces in familiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Reliquerunt autem Deum patrum suorum, et fornicati sunt post deos populorum terræ, quos abstulit Deus coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Et suscitavit Deus Israël spiritum Phul regis Assyriorum, et spiritum Thelgathphalnasar regis Assur: et transtulit Ruben, et Gad, et dimidiam tribum Manasse, et adduxit eos in Lahela, et in Habor, et Ara, et fluvium Gozan, usque ad diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Filii Levi: Gerson, Caath, et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Filii Caath: Amram, Isaar, Hebron, et Oziel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Filii Amram: Aaron, Moyses, et Maria. Filii Aaron: Nadab et Abiu, Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar genuit Phinees, et Phinees genuit Abisue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisue vero genuit Bocci, et Bocci genuit Ozi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ozi genuit Zaraiam, et Zaraias genuit Meraioth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Porro Meraioth genuit Amariam, et Amarias genuit Achitob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Achitob genuit Sadoc, et Sadoc genuit Achimaas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Achimaas genuit Azariam, Azarias genuit Johanan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan genuit Azariam: ipse est qui sacerdotio functus est in domo quam ædificavit Salomon in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Genuit autem Azarias Amariam, et Amarias genuit Achitob,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Achitob genuit Sadoc, et Sadoc genuit Sellum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sellum genuit Helciam, et Helcias genuit Azariam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarias genuit Saraiam, et Saraias genuit Josedec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Porro Josedec egressus est, quando transtulit Dominus Judam et Jerusalem per manus Nabuchodonosor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Filii ergo Levi: Gersom, Caath, et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Et hæc nomina filiorum Gersom: Lobni, et Semei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Filii Caath: Amram, et Isaar, et Hebron, et Oziel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Filii Merari: Moholi et Musi. Hæ autem cognationes Levi secundum familias eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersom: Lobni filius ejus, Jahath filius ejus, Zamma filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Joah filius ejus, Addo filius ejus, Zara filius ejus, Jethrai filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Filii Caath: Aminadab filius ejus, Core filius ejus, Asir filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elcana filius ejus, Abiasaph filius ejus, Asir filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Thahath filius ejus, Uriel filius ejus, Ozias filius ejus, Saul filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Filii Elcana, Amasai et Achimoth');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'et Elcana. Filii Elcana: Sophai filius ejus, Nahath filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Eliab filius ejus, Jeroham filius ejus, Elcana filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Filii Samuel: primogenitus Vasseni, et Abia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Filii autem Merari, Moholi: Lobni filius ejus, Semei filius ejus, Oza filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Sammaa filius ejus, Haggia filius ejus, Asaia filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Isti sunt quos constituit David super cantores domus Domini, ex quo collocata est arca:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'et ministrabant coram tabernaculo testimonii, canentes donec ædificaret Salomon domum Domini in Jerusalem: stabant autem juxta ordinem suum in ministerio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Hi vero sunt qui assistebant cum filiis suis, de filiis Caath, Hemam cantor filius Johel, filii Samuel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'filii Elcana, filii Jeroham, filii Eliel, filii Thohu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'filii Suph, filii Elcana, filii Mahath, filii Amasai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'filii Elcana, filii Johel, filii Azariæ, filii Sophoniæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'filii Thahath, filii Asir, filii Abiasaph, filii Core,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'filii Isaar, filii Caath, filii Levi, filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Et frater ejus Asaph, qui stabat a dextris ejus, Asaph filius Barachiæ, filii Samaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'filii Michaël, filii Basaiæ, filii Melchiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'filii Athanai, filii Zara, filii Adaia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'filii Ethan, filii Zamma, filii Semei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'filii Jeth, filii Gersom, filii Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Filii autem Merari fratres eorum, ad sinistram, Ethan filius Cusi, filii Abdi, filii Maloch,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'filii Hasabiæ, filii Amasiæ, filii Helciæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'filii Amasai, filii Boni, filii Somer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'filii Moholi, filii Musi, filii Merari, filii Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Fratres quoque eorum Levitæ, qui ordinati sunt in cunctum ministerium tabernaculi domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Aaron vero et filii ejus adolebant incensum super altare holocausti, et super altare thymiamatis, in omne opus Sancti sanctorum: et ut precarentur pro Israël juxta omnia quæ præceperat Moyses servus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Hi sunt autem filii Aaron: Eleazar filius ejus, Phinees filius ejus, Abisue filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bocci filius ejus, Ozi filius ejus, Zarahia filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Meraioth filius ejus, Amarias filius ejus, Achitob filius ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Sadoc filius ejus, Achimaas filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Et hæc habitacula eorum per vicos atque confinia, filiorum scilicet Aaron, juxta cognationes Caathitarum: ipsis enim sorte contigerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Dederunt igitur eis Hebron in terra Juda, et suburbana ejus per circuitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'agros autem civitatis, et villas, Caleb filio Jephone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Porro filiis Aaron dederunt civitates ad confugiendum Hebron, et Lobna, et suburbana ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Jether quoque, et Esthemo cum suburbanis suis, sed et Helon, et Dabir cum suburbanis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asan quoque, et Bethsemes, et suburbana earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'De tribu autem Benjamin, Gabee et suburbana ejus, et Almath cum suburbanis suis, Anathoth quoque cum suburbanis suis: omnes civitates, tredecim, per cognationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Filiis autem Caath residuis de cognatione sua dederunt ex dimidia tribu Manasse in possessionem urbes decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Porro filiis Gersom per cognationes suas de tribu Issachar, et de tribu Aser, et de tribu Nephthali, et de tribu Manasse in Basan, urbes tredecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Filiis autem Merari per cognationes suas de tribu Ruben, et de tribu Gad, et de tribu Zabulon, dederunt sorte civitates duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Dederunt quoque filii Israël Levitis civitates, et suburbana earum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'dederuntque per sortem, ex tribu filiorum Juda, et ex tribu filiorum Simeon, et ex tribu filiorum Benjamin urbes has, quas vocaverunt nominibus suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'et his, qui erant de cognatione filiorum Caath, fueruntque civitates in terminis eorum de tribu Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Dederunt ergo eis urbes ad confugiendum, Sichem cum suburbanis suis in monte Ephraim, et Gazer cum suburbanis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jecmaam quoque cum suburbanis suis, et Bethoron similiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'necnon et Helon cum suburbanis suis, et Gethremmon in eumdem modum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Porro ex dimidia tribu Manasse, Aner et suburbana ejus, Balaam et suburbana ejus: his videlicet, qui de cognatione filiorum Caath reliqui erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Filiis autem Gersom de cognatione dimidiæ tribus Manasse, Gaulon in Basan, et suburbana ejus, et Astaroth cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'De tribu Issachar, Cedes et suburbanis suis, et Dabereth cum suburbanis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoth quoque et suburbana ejus, et Anem cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'De tribu vero Aser: Masal cum suburbanis suis, et Abdon similiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hucac quoque et suburbana ejus, et Rohob cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Porro de tribu Nephthali, Cedes in Galilæa et suburbana ejus, Hamon cum suburbanis suis, et Cariathaim et suburbana ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Filiis autem Merari residuis: de tribu Zabulon, Remmono et suburbana ejus, et Thabor cum suburbanis sus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'trans Jordanem quoque ex adverso Jericho contra orientem Jordanis, de tribu Ruben, Bosor in solitudine cum suburbanis suis, et Jassa cum suburbanis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Cademoth quoque et suburbana ejus, et Mephaat cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Necnon et de tribu Gad, Ramoth in Galaad et suburbana ejus, et Manaim cum suburbanis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'sed et Hesebon cum suburbanis suis, et Jezer cum suburbanis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Porro filii Issachar: Thola, et Phua, Jasub, et Simeron, quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Filii Thola: Ozi, et Raphaia, et Jeriel, et Jemai, et Jebsem, et Samuel, principes per domos cognationum suarum. De stirpe Thola viri fortissimi numerati sunt in diebus David, viginti duo millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Filii Ozi: Izrahia, de quo nati sunt Michaël, et Obadia, et Joël, et Jesia, quinque omnes principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Cumque eis per familias et populos suos, accincti ad prælium, viri fortissimi, triginta sex millia: multas enim habuerunt uxores, et filios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Fratres quoque eorum per omnem cognationem Issachar robustissimi ad pugnandum, octoginta septem millia numerati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Filii Benjamin: Bela, et Bechor, et Jadihel, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Filii Bela: Esbon, et Ozi, et Oziel, et Jerimoth, et Urai, quinque principes familiarum, et ad pugnandum robustissimi: numerus autem eorum, viginti duo millia et triginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Porro filii Bechor: Zamira, et Joas, et Eliezer, et Elioënai, et Amri, et Jerimoth, et Abia, et Anathoth, et Almath: omnes hi filii Bechor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Numerati sunt autem per familias suas principes cognationum suarum ad bella fortissimi, viginti millia et ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Porro filii Jadihel: Balan. Filii autem Balan: Jehus, et Benjamin, et Aod, et Chanana, et Zethan, et Tharsis, et Ahisahar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'omnes hi filii Jadihel, principes cognationum suarum viri fortissimi, decem et septem millia et ducenti ad prælium procedentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Sepham quoque et Hapham filii Hir: et Hasim filii Aher.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Filii autem Nephthali: Jaziel, et Guni, et Jeser, et Sellum, filii Bala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Porro filius Manasse, Esriel: concubinaque ejus Syra peperit Machir patrem Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Machir autem accepit uxores filiis suis Happhim, et Saphan: et habuit sororem nomine Maacha: nomen autem secundi, Salphaad, natæque sunt Salphaad filiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et peperit Maacha uxor Machir filium, vocavitque nomen ejus Phares: porro nomen fratris ejus, Sares: et filii ejus, Ulam, et Recen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Filius autem Ulam, Badan: hi sunt filii Galaad, filii Machir, filii Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Soror autem ejus Regina peperit Virum decorum, et Abiezer, et Mohola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Erant autem filii Semida, Ahin, et Sechem, et Leci, et Aniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Filii autem Ephraim: Suthala, Bared filius ejus, Thahath filius ejus, Elada filius ejus, Thahath filius ejus, hujus filius Zabad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'et hujus filius Suthula, et hujus filius Ezer et Elad: occiderunt autem eos viri Geth indigenæ, quia descenderant ut invaderent possessiones eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Luxit igitur Ephraim pater eorum multis diebus, et venerunt fratres ejus ut consolarentur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Ingressusque est ad uxorem suam: quæ concepit, et peperit filium, et vocavit nomen ejus Beria, eo quod in malis domus ejus ortus esset:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'filia autem ejus fuit Sara, quæ ædificavit Bethoron inferiorem et superiorem, et Ozensara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Porro filius ejus Rapha, et Reseph, et Thale, de quo natus est Thaan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'qui genuit Laadan: hujus quoque filius Ammiud, qui genuit Elisama,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'de quo ortus est Nun, qui habuit filium Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Possessio autem eorum et habitatio, Bethel cum filiabus suis, et contra orientem Noran, ad occidentalem plagam Gazer et filiæ ejus, Sichem quoque cum filiabus suis, usque ad Aza cum filiabus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Juxta filios quoque Manasse, Bethsan et filias ejus, Thanach et filias ejus, Mageddo et filias ejus, Dor et filias ejus: in his habitaverunt filii Joseph, filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Filii Aser: Jemna, et Jesua, et Jessui, et Baria, et Sara soror eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Filii autem Baria: Heber, et Melchiel: ipse est pater Barsaith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber autem genuit Jephlat, et Somer, et Hotham, et Suaa sororem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Filii Jephlat: Phosech, et Chamaal, et Asoth: hi filii Jephlat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Porro filii Somer: Ahi, et Roaga, et Haba, et Aram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Filii autem Helem fratris ejus: Supha, et Jemna, et Selles, et Amal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Filii Supha: Sue, Harnapher, et Sual, et Beri, et Jamra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bosor, et Hod, et Samma, et Salusa, et Jethran, et Bera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Filii Jether: Jephone, et Phaspha, et Ara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Filii autem Olla: Aree, et Haniel, et Resia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Omnes hi filii Aser, principes cognationum, electi atque fortissimi duces ducum: numerus autem eorum ætatis quæ apta esset ad bellum, viginti sex millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin autem genuit Bale primogenitum suum, Asbel secundum, Ahara tertium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nohaa quartum, et Rapha quintum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Fueruntque filii Bale: Addar, et Gera, et Abiud,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisue quoque et Naaman, et Ahoë,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'sed et Gera, et Sephuphan, et Huram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Hi sunt filii Ahod, principes cognationum habitantium in Gabaa, qui translati sunt in Manahath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naaman autem, et Achia, et Gera, ipse transtulit eos, et genuit Osa, et Ahiud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Porro Saharaim genuit in regione Moab, postquam dimisit Husim et Bara uxores suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Genuit autem de Hodes uxore sua Jobab, et Sebia, et Mosa, et Molchom,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jehus quoque, et Sechia, et Marma: hi sunt filii ejus principes in familiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Mehusim vero genuit Abitob et Elphaal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Porro filii Elphaal: Heber, et Misaam, et Samad: hic ædificavit Ono, et Lod, et filias ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Baria autem et Sama principes cognationum habitantium in Ajalon: hi fugaverunt habitatores Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Et Ahio, et Sesac, et Jerimoth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'et Zabadia, et Arod, et Heder,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michaël quoque, et Jespha, et Joha filii Baria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Et Zabadia, et Mosollam, et Hezeci, et Heber,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'et Jesamari, et Jezlia, et Jobab filii Elphaal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'et Jacim, et Zechri, et Zabdi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'et Elioënai, et Selethai, et Eliel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'et Adaia, et Baraia, et Samarath, filii Semei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Et Jespham, et Heber, et Eliel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'et Abdon, et Zechri, et Hanan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'et Hanania, et \'lam, et Anathothia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'et Jephdaia, et Phanuel, filii Sesac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Et Samsari, et Sohoria, et Otholia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'et Jersia, et Elia, et Zechri, filii Jeroham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Hi patriarchæ, et cognationum principes, qui habitaverunt in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'In Gabaon autem habitaverunt Abigabaon, et nomen uxoris ejus Maacha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'filiusque ejus primogenitus Abdon, et Sur, et Cis, et Baal, et Nadab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor quoque, et Ahio, et Zacher, et Macelloth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'et Macelloth genuit Samaa: habitaveruntque ex adverso fratrum suorum in Jerusalem cum fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner autem genuit Cis, et Cis genuit Saul. Porro Saul genuit Jonathan, et Melchisua, et Abinadab, et Esbaal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Filius autem Jonathan, Meribbaal: et Meribbaal genuit Micha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Filii Micha, Phithon, et Melech, et Tharaa, et Ahaz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Ahaz genuit Joada, et Joada genuit Alamath, et Azmoth, et Zamri: porro Zamri genuit Mosa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'et Mosa genuit Banaa, cujus filius fuit Rapha, de quo ortus est Elasa, qui genuit Asel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Porro Asel sex filii fuerunt his nominibus: Ezricam, Bocru, Ismahel, Saria, Obdia, et Hanan: omnes hi filii Asel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Filii autem Esec fratris ejus, Ulam primogenitus, et Jehus secundus, et Eliphalet tertius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Fueruntque filii Ulam viri robustissimi, et magno robore tendentes arcum: et multos habentes filios ac nepotes, usque ad centum quinquaginta. Omnes hi filii Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Universus ergo Israël dinumeratus est, et summa eorum scripta est in libro regum Israël et Juda: translatique sunt in Babylonem propter delictum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Qui autem habitaverunt primi in possessionibus et in urbibus suis: Israël, et sacerdotes, et Levitæ, et Nathinæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Commorati sunt in Jerusalem de filiis Juda, et de filiis Benjamin, de filiis quoque Ephraim, et Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Othei filius Ammiud, filii Amri, filii Omrai, filii Bonni, de filiis Phares filii Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et de Siloni: Asaia primogenitus, et filii ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'De filiis autem Zara, Jehuel, et fratres eorum, sexcenti nonaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Porro de filiis Benjamin: Salo filius Mosollam, filii Oduia, filii Asana,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'et Jobania filius Jeroham, et Ela filius Ozi, filii Mochori, et Mosollam filius Saphatiæ, filii Rahuel, filii Jebaniæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'et fratres eorum per familias suas, nongenti quinquaginta sex. Omnes hi principes cognationum per domos patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'De sacerdotibus autem: Jedaia, Jojarib, et Jachin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarias quoque filius Helciæ, filii Mosollam, filii Sadoc, filii Maraioth, filii Achitob, pontifex domus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Porro Adaias filius Jeroham, filii Phassur, filii Melchiæ, et Maasai filius Adiel filii Jezra, filii Mosollam, filii Mosollamith, filii Emmer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Fratres quoque eorum principes per familias suas, mille septingenti sexaginta, fortissimi robore ad faciendum opus ministerii in domo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'De Levitis autem: Semeia filius Hassub filii Ezricam, filii Hasebia de filiis Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bacbacar quoque carpentarius, et Galal, et Mathania filius Micha, filii Zechri, filii Asaph:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'et Obdia filius Semeiæ, filii Galal, filii Idithun: et Barachia filius Asa, filii Elcana, qui habitavit in atriis Netophati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Janitores autem: Sellum, et Accub, et Telmon, et Ahimam: et frater eorum Sellum princeps,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'usque ad illud tempus, in porta regis ad orientem, observabant per vices suas de filiis Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Sellum vero filius Core filii Abiasaph, filii Core, cum fratribus suis, et domo patris sui, hi sunt Coritæ super opera ministerii, custodes vestibulorum tabernaculi: et familiæ eorum per vices castrorum Domini custodientes introitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Phinees autem filius Eleazari erat dux eorum coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Porro Zacharias filius Mosollamia, janitor portæ tabernaculi testimonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Omnes hi electi in ostiarios per portas, ducenti duodecim: et descripti in villis propriis, quos constituerunt David, et Samuel videns, in fide sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'tam ipsos quam filios eorum, in ostiis domus Domini et in tabernaculo vicibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Per quatuor ventos erant ostiarii: id est, ad orientem, et ad occidentem, et ad aquilonem, et ad austrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Fratres autem eorum in viculis morabantur, et veniebant in sabbatis suis de tempore usque ad tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'His quatuor Levitis creditus erat omnis numerus janitorum, et erant super exedras et thesauros domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Per gyrum quoque templi Domini morabantur in custodiis suis: ut cum tempus fuisset, ipsi mane aperirent fores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'De horum genere erant et super vasa ministerii: ad numerum enim et inferebantur vasa, et efferebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'De ipsis et qui credita habebant utensilia sanctuarii, præerant similæ, et vino, et oleo, et thuri, et aromatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Filii autem sacerdotum unguenta ex aromatibus conficiebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et Mathathias Levites primogenitus Sellum Coritæ, præfectus erat eorum quæ in sartagine frigebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Porro de filiis Caath fratribus eorum, super panes erant propositionis, ut semper novos per singula sabbata præpararent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Hi sunt principes cantorum per familias Levitarum, qui in exedris morabantur, ut die ac nocte jugiter suo ministerio deservirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Capita Levitarum, per familias suas principes, manserunt in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'In Gabaon autem commorati sunt pater Gabaon Jehiel, et nomen uxoris ejus Maacha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Filius primogenitus ejus Abdon, et Sur, et Cis, et Baal, et Ner, et Nadab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor quoque, et Ahio, et Zacharias, et Macelloth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Porro Macelloth genuit Samaan: isti habitaverunt e regione fratrum suorum in Jerusalem cum fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner autem genuit Cis, et Cis genuit Saul, et Saul genuit Jonathan, et Melchisua, et Abinadab, et Esbaal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Filius autem Jonathan, Meribbaal: et Meribbaal genuit Micha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Porro filii Micha, Phithon, et Melech, et Tharaa, et Ahaz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahaz autem genuit Jara, et Jara genuit Alamath, et Azmoth, et Zamri. Zamri autem genuit Mosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Mosa vero genuit Banaa, cujus filius Raphaia, genuit Elasa, de quo ortus est Asel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Porro Asel sex filios habuit, his nominibus: Ezricam, Bocru, Ismahel, Saria, Obdia, Hanan: hi sunt filii Asel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Philisthiim autem pugnabant contra Israël, fugeruntque viri Israël Palæsthinos, et ceciderunt vulnerati in monte Gelboë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Cumque appropinquassent Philisthæi, persequentes Saul et filios ejus, percusserunt Jonathan, et Abinadab, et Melchisua filios Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et aggravatum est prælium contra Saul, inveneruntque eum sagittarii, et vulneraverunt jaculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Et dixit Saul ad armigerum suum: Evagina gladium tuum, et interfice me, ne forte veniant incircumcisi isti, et illudant mihi. Noluit autem armiger ejus hoc facere, timore perterritus: arripuit ergo Saul ensem, et irruit in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Quod cum vidisset armiger ejus, videlicet mortuum esse Saul, irruit etiam ipse in gladium suum, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Interiit ergo Saul: et tres filii ejus, et omnis domus illius pariter concidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Quod cum vidissent viri Israël qui habitabant in campestribus, fugerunt: et Saul ac filiis ejus mortuis, dereliquerunt urbes suas, et huc illucque dispersi sunt: veneruntque Philisthiim, et habitaverunt in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Die igitur altero detrahentes Philisthiim spolia cæsorum, invenerunt Saul et filios ejus jacentes in monte Gelboë.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Cumque spoliassent eum, et amputassent caput, armisque nudassent, miserunt in terram suam, ut circumferretur, et ostenderetur idolorum templis, et populis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'arma autem ejus consecraverunt in fano dei sui, et caput affixerunt in templo Dagon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Hoc cum audissent viri Jabes Galaad, omnia scilicet quæ Philisthiim fecerant super Saul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'consurrexerunt singuli virorum fortium, et tulerunt cadavera Saul et filiorum ejus: attuleruntque ea in Jabes, et sepelierunt ossa eorum subter quercum, quæ erat in Jabes, et jejunaverunt septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Mortuus est ergo Saul propter iniquitates suas, eo quod prævaricatus sit mandatum Domini quod præceperat, et non custodierit illud: sed insuper etiam pythonissam consuluerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'nec speraverit in Domino: propter quod interfecit eum, et transtulit regnum ejus ad David filium Isai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Congregatus est igitur omnis Israël ad David in Hebron, dicens: Os tuum sumus, et caro tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Heri quoque et nudiustertius cum adhuc regnaret Saul, tu eras qui educebas et introducebas Israël: tibi enim dixit Dominus Deus tuus: Tu pasces populum meum Israël, et tu eris princeps super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Venerunt ergo omnes majores natu Israël ad regem in Hebron, et iniit David cum eis fœdus coram Domino: unxeruntque eum regem super Israël, juxta sermonem Domini quem locutus est in manu Samuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Abiit quoque David et omnis Israël in Jerusalem: hæc est Jebus, ubi erant Jebusæi habitatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Dixeruntque qui habitabant in Jebus ad David: Non ingredieris huc. Porro David cepit arcem Sion, quæ est civitas David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'dixitque: Omnis qui percusserit Jebusæum in primis, erit princeps et dux. Ascendit igitur primus Joab filius Sarviæ, et factus est princeps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Habitavit autem David in arce, et idcirco appellata est civitas David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, '\'dificavitque urbem in circuitu a Mello usque ad gyrum; Joab autem reliqua urbis exstruxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Proficiebatque David vadens et crescens, et Dominus exercituum erat cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Hi principes virorum fortium David, qui adjuverunt eum ut rex fieret super omnem Israël, juxta verbum Domini quod locutus est ad Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Et iste numerus robustorum David: Jesbaam filius Hachamoni princeps inter triginta: iste levavit hastam suam super trecentos vulneratos una vice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Et post eum Eleazar filius patrui ejus Ahohites, qui erat inter tres potentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Iste fuit cum David in Phesdomim, quando Philisthiim congregati sunt ad locum illum in prælium: et erat ager regionis illius plenus hordeo, fugeratque populus a facie Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Hi steterunt in medio agri, et defenderunt eum: cumque percussissent Philisthæos, dedit Dominus salutem magnam populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Descenderunt autem tres de triginta principibus ad petram, in qua erat David, ad speluncam Odollam, quando Philisthiim fuerant castrametati in valle Raphaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Porro David erat in præsidio, et statio Philisthinorum in Bethlehem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Desideravit igitur David, et dixit: O si quis daret mihi aquam de cisterna Bethlehem, quæ est in porta!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Tres ergo isti per media castra Philisthinorum perrexerunt, et hauserunt aquam de cisterna Bethlehem quæ erat in porta, et attulerunt ad David ut biberet. Qui noluit, sed magis libavit illam Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'dicens: Absit ut in conspectu Dei mei hoc faciam, et sanguinem istorum virorum bibam: quia in periculo animarum suarum attulerunt mihi aquam. Et ob hanc causam noluit bibere: hæc fecerunt tres robustissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai quoque frater Joab ipse erat princeps trium, et ipse levavit hastam suam contra trecentos vulneratos, et ipse erat inter tres nominatissimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'et inter tres secundos inclytus, et princeps eorum: verumtamen usque ad tres primos non pervenerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Banaias filius Jojadæ viri robustissimi, qui multa opera perpetrarat, de Cabseel: ipse percussit duos ariel Moab, et ipse descendit et interfecit leonem in media cisterna tempore nivis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Et ipse percussit virum ægyptium, cujus statura erat quinque cubitorum, et habebat lanceam ut liciatorium texentium: descendit igitur ad eum cum virga, et rapuit hastam quam tenebat manu, et interfecit eum hasta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Hæc fecit Banaias filius Jojadæ, qui erat inter tres robustos nominatissimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'inter triginta primus, verumtamen ad tres usque non pervenerat: posuit autem eum David ad auriculam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Porro fortissimi viri in exercitu, Asahel frater Joab, et Elchanan filius patrui ejus de Bethlehem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth Arorites, Helles Pharonites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira filius Acces Thecuites, Abiezer Anathothites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sobbochai Husathites, Ilai Ahohites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai Netophathites, Heled filius Baana Netophathites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ethai filius Ribai de Gabaath filiorum Benjamin, Banaia Pharatonites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai de torrente Gaas, Abiel Arbathites, Azmoth Bauramites, Eliaba Salabonites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Filii Assem Gezonites, Jonathan filius Sage Ararites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Ahiam filius Sachar Ararites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Eliphal filius Ur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher Mecherathites, Ahia Phelonites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hesro Carmelites, Naarai filius Asbai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joël frater Nathan, Mibahar filius Agarai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selec Ammonites, Naharai Berothites armiger Joab filii Sarviæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira Jethræus, Gareb Jethræus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urias Hethæus, Zabad filius Oholi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina filius Siza Rubenites princeps Rubenitarum, et cum eo triginta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan filius Maacha, et Josaphat Mathanites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ozia Astarothites, Samma, et Jehiel filii Hotham Arorites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jedihel filius Samri, et Joha frater ejus Thosaites,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Mahumites, et Jeribai, et Josaia filii Elnaëm, et Jethma Moabites, Eliel, et Obed, et Jasiel de Masobia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Hi quoque venerunt ad David in Siceleg, cum adhuc fugeret Saul filium Cis, qui erant fortissimi et egregii pugnatores,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'tendentes arcum, et utraque manu fundis saxa jacientes, et dirigentes sagittas, de fratribus Saul ex Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Princeps Ahiecer, et Joas filii Samaa Gabaathites, et Jaziel, et Phallet filii Azmoth, et Baracha, et Jehu Anathotites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Samaias quoque Gabaonites fortissimus inter triginta et super triginta. Jeremias, et Jeheziel, et Johanan, et Jezabad Gaderothites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Et Eluzai, et Jerimuth, et Baalia, et Samaria, et Saphatia Haruphites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elcana, et Jesia, et Azareel, et Joëzer, et Jesbaam de Carehim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joëla quoque, et Zabadia filii Jeroham de Gedor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Sed et de Gaddi transfugerunt ad David cum lateret in deserto, viri robustissimi, et pugnatores optimi, tenentes clypeum et hastam: facies eorum quasi facies leonis, et veloces quasi capreæ in montibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer princeps, Obdias secundus, Eliab tertius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Masmana quartus, Jeremias quintus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Ethi sextus, Eliel septimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Johanan octavus, Elzebad nonus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremias decimus, Machbanai undecimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Hi de filiis Gad principes exercitus: novissimus centum militibus præerat, et maximus mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Isti sunt qui transierunt Jordanem mense primo, quando inundare consuevit super ripas suas: et omnes fugaverunt qui morabantur in vallibus ad orientalem plagam et occidentalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Venerunt autem et de Benjamin et de Juda ad præsidium in quo morabatur David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Egressusque est David obviam eis, et ait: Si pacifice venistis ad me ut auxiliemini mihi, cor meum jungatur vobis: si autem insidiamini mihi pro adversariis meis, cum ego iniquitatem in manibus non habeam, videat Deus patrum nostrorum, et judicet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Spiritus vero induit Amasai principem inter triginta, et ait: Tui sumus, o David, et tecum, fili Isai. Pax, pax tibi, et pax adjutoribus tuis: te enim adjuvat Deus tuus. Suscepit ergo eos David, et constituit principes turmæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Porro de Manasse transfugerunt ad David, quando veniebat cum Philisthiim adversus Saul ut pugnaret: et non dimicavit cum eis, quia inito consilio remiserunt eum principes Philisthinorum, dicentes: Periculo capitis nostri revertetur ad dominum suum Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Quando igitur reversus est in Siceleg, transfugerunt ad eum de Manasse, Ednas, et Jozabad, et Jedihel, et Michaël, et Ednas, et Jozabad, et Eliu, et Salathi, principes millium in Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Hi præbuerunt auxilium David adversus latrunculos: omnes enim erant viri fortissimi, et facti sunt principes in exercitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Sed et per singulos dies veniebant ad David ad auxiliandum ei, usque dum fieret grandis numerus, quasi exercitus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Iste quoque est numerus principum exercitus qui venerunt ad David cum esset in Hebron, ut transferrent regnum Saul ad eum, juxta verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Filii Juda portantes clypeum et hastam, sex millia octingenti expediti ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'De filiis Simeon virorum fortissimorum ad pugnandum, septem millia centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'De filiis Levi, quatuor millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Jojoda quoque princeps de stirpe Aaron, et cum eo tria millia septingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Sadoc etiam puer egregiæ indolis, et domus patris ejus, principes viginti duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'De filiis autem Benjamin fratribus Saul, tria millia: magna enim pars eorum adhuc sequebatur domum Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Porro de filiis Ephraim viginti millia octingenti, fortissimi robore, viri nominati in cognationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Et ex dimidia tribu Manasse, decem et octo millia, singuli per nomina sua, venerunt ut constituerent regem David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'De filiis quoque Issachar viri eruditi, qui noverant singula tempora ad præcipiendum quid facere deberet Israël, principes ducenti: omnis autem reliqua tribus eorum consilium sequebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Porro de Zabulon qui egrediebantur ad prælium, et stabant in acie instructi armis bellicis, quinquaginta millia venerunt in auxilium, non in corde duplici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Et de Nephthali, principes mille, et cum eis instructi clypeo et hasta, triginta et septem millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'De Dan etiam præparati ad prælium, viginti octo millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Et de Aser egredientes ad pugnam, et in acie provocantes, quadraginta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Trans Jordanem autem de filiis Ruben, et de Gad, et dimidia parte tribus Manasse, instructi armis bellicis, centum viginti millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Omnes isti viri bellatores expediti ad pugnandum, corde perfecto venerunt in Hebron, ut constituerent regem David super universum Israël: sed et omnes reliqui ex Israël uno corde erant, ut rex fieret David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Fueruntque ibi apud David tribus diebus comedentes et bibentes: præparaverant enim eis fratres sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Sed et qui juxta eos erant, usque ad Issachar, et Zabulon, et Nephthali, afferebant panes in asinis, et camelis, et mulis, et bobus ad vescendum: farinam, palathas, uvam passam, vinum, oleum, boves, arietes ad omnem copiam: gaudium quippe erat in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Iniit autem consilium David cum tribunis, et centurionibus, et universis principibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'et ait ad omnem cœtum Israël: Si placet vobis, et a Domino Deo nostro egreditur sermo quem loquor, mittamus ad fratres nostros reliquos in universas regiones Israël, et ad sacerdotes et Levitas qui habitant in suburbanis urbium, ut congregentur ad nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'et reducamus arcam Dei nostri ad nos: non enim requisivimus eam in diebus Saul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et respondit universa multitudo ut ita fieret: placuerat enim sermo omni populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Congregavit ergo David cunctum Israël, a Sihor \'gypti usque dum ingrediaris Emath, ut adduceret arcam Dei de Cariathiarim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et ascendit David, et omnis vir Israël, ad collem Cariathiarim, qui est in Juda, ut afferret inde arcam Domini Dei sedentis super cherubim, ubi invocatum est nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Imposueruntque arcam Dei super plaustrum novum, de domo Abinadab: Oza autem, et frater ejus minabant plaustrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Porro David, et universus Israël, ludebant coram Deo omni virtute in canticis, et in citharis, et psalteriis, et tympanis, et cymbalis, et tubis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Cum autem pervenisset ad aream Chidon, tetendit Oza manum suam, ut sustentaret arcam: bos quippe lasciviens paululum inclinaverat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Iratus est itaque Dominus contra Ozam, et percussit eum, eo quod tetigisset arcam: et mortuus est ibi coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Contristatusque est David, eo quod divisisset Dominus Ozam: vocavitque locum illum Divisio Ozæ, usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et timuit Deum tunc temporis, dicens: Quomodo possum ad me introducere arcam Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'et ob hanc causam non adduxit eam ad se, hoc est, in civitatem David, sed avertit in domum Obededom Gethæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Mansit ergo arca Dei in domo Obededom tribus mensibus: et benedixit Dominus domui ejus, et omnibus quæ habebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Misit quoque Hiram rex Tyri nuntios ad David, et ligna cedrina, et artifices parietum, lignorumque, ut ædificarent ei domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Cognovitque David quod confirmasset eum Dominus in regem super Israël, et sublevatum esset regnum suum super populum ejus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Accepit quoque David alias uxores in Jerusalem, genuitque filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Et hæc nomina eorum, qui nati sunt ei in Jerusalem: Samua, et Sobab, Nathan, et Salomon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jebahar, et Elisua, et Eliphalet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga quoque, et Napheg, et Japhia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, et Baaliada, et Eliphalet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Audientes autem Philisthiim eo quod unctus esset David regem super universum Israël, ascenderunt omnes ut quærerent eum: quod cum audisset David, egressus est obviam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Porro Philisthiim venientes, diffusi sunt in valle Raphaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Consuluitque David Dominum, dicens: Si ascendam ad Philisthæos, et si trades eos in manu mea? Et dixit ei Dominus: Ascende, et tradam eos in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Cumque illi ascendissent in Baalpharasim, percussit eos ibi David, et dixit: Divisit Deus inimicos meos per manum meam, sicut dividuntur aquæ: et idcirco vocatum est nomen illius loci Baalpharasim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Dereliqueruntque ibi deos suos, quos David jussit exuri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Alia etiam vice Philisthiim irruerunt, et diffusi sunt in valle.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Consuluitque rursum David Deum, et dixit ei Deus: Non ascendas post eos: recede ab eis, et venies contra illos ex adverso pyrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Cumque audieris sonitum gradientis in cacumine pyrorum, tunc egredieris ad bellum: egressus est enim Deus ante te, ut percutiat castra Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Fecit ergo David sicut præceperat ei Deus, et percussit castra Philisthinorum, de Gabaon usque Gazera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Divulgatumque est nomen David in universis regionibus, et Dominus dedit pavorem ejus super omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Fecit quoque sibi domos in civitate David: et ædificavit locum arcæ Dei, tetenditque ei tabernaculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tunc dixit David: Illicitum est ut a quocumque portetur arca Dei nisi a Levitis, quos elegit Dominus ad portandum eam, et ad ministrandum sibi usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Congregavitque universum Israël in Jerusalem, ut afferretur arca Dei in locum suum, quem præparaverat ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'necnon et filios Aaron, et Levitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'De filiis Caath, Uriel princeps fuit, et fratres ejus centum viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'De filiis Merari, Asaia princeps: et fratres ejus ducenti viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'De filiis Gersom, Joël princeps: et fratres ejus centum triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'De filiis Elisaphan, Semeias princeps: et fratres ejus ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'De filiis Hebron, Eliel princeps: et fratres ejus octoginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'De filiis Oziel, Aminadab princeps: et fratres ejus centum duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Vocavitque David Sadoc et Abiathar sacerdotes, et Levitas, Uriel, Asaiam, Joël, Semeiam, Eliel, et Aminadab:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'et dixit ad eos: Vos, qui estis principes familiarum Leviticarum, sanctificamini cum fratribus vestris, et afferte arcam Domini Dei Israël ad locum qui ei præparatus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'ne ut a principio, quia non eratis præsentes, percussit nos Dominus; sic et nunc fiat, illicitum quid nobis agentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Sanctificati sunt ergo sacerdotes et Levitæ ut portarent arcam Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et tulerunt filii Levi arcam Dei, sicut præceperat Moyses juxta verbum Domini, humeris suis in vectibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Dixitque David principibus Levitarum, ut constituerent de fratribus suis cantores in organis musicorum, nablis videlicet, et lyris, et cymbalis, ut resonaret in excelsis sonitus lætitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Constitueruntque Levitas: Heman filium Joël, et de fratribus ejus Asaph filium Barachiæ: de filiis vero Merari, fratribus eorum: Ethan filium Casaiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Et cum eis fratres eorum: in secundo ordine, Zachariam, et Ben, et Jaziel, et Semiramoth, et Jahiel, et Ani, Eliab, et Banaiam, et Maasiam, et Mathathiam, et Eliphalu, et Maceniam, et Obededom, et Jehiel, janitores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Porro cantores, Heman, Asaph, et Ethan, in cymbalis æneis concrepantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zacharias autem, et Oziel, et Semiramoth, et Jahiel, et Ani, et Eliab, et Maasias, et Banaias in nablis arcana cantabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Porro Mathathias, et Eliphalu, et Macenias, et Obededom, et Jehiel, et Ozaziu, in citharis pro octava canebant epinicion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Chonenias autem princeps Levitarum, prophetiæ præerat, ad præcinendam melodiam: erat quippe valde sapiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Et Barachias, et Elcana, janitores arcæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Porro Sebenias, et Josaphat, et Nathanaël, et Amasai, et Zacharias, et Banaias, et Eliezer sacerdotes, clangebant tubis coram arca Dei: et Obededom et Jehias erant janitores arcæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Igitur David, et omnes majores natu Israël, et tribuni, ierunt ad deportandam arcam fœderis Domini de domo Obededom cum lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Cumque adjuvisset Deus Levitas qui portabant arcam fœderis Domini, immolabantur septem tauri, et septem arietes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Porro David erat indutus stola byssina, et universi Levitæ qui portabant arcam, cantoresque, et Chonenias princeps prophetiæ inter cantores: David autem etiam indutus erat ephod lineo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Universusque Israël deducebant arcam fœderis Domini in jubilo, et sonitu buccinæ, et tubis, et cymbalis, et nablis, et citharis concrepantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Cumque pervenisset arca fœderis Domini usque ad civitatem David, Michol filia Saul prospiciens per fenestram vidit regem David saltantem atque ludentem, et despexit eum in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Attulerunt igitur arcam Dei, et constituerunt eam in medio tabernaculi quod tetenderat ei David: et obtulerunt holocausta et pacifica coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Cumque complesset David offerens holocausta et pacifica, benedixit populo in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Et divisit universis per singulos, a viro usque ad mulierem, tortam panis, et partem assæ carnis bubalæ, et frixam oleo similam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Constituitque coram arca Domini de Levitis, qui ministrarent, et recordarentur operum ejus, et glorificarent atque laudarent Dominum Deum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph principem, et secundum ejus Zachariam: porro Jahiel, et Semiramoth, et Jehiel, et Mathathiam, et Eliab, et Banaiam, et Obededom: Jehiel super organa psalterii et lyras: Asaph autem ut cymbalis personaret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Banaiam vero et Jaziel sacerdotes canere tuba jugiter coram arca fœderis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'In illo die fecit David principem ad confitendum Domino Asaph et fratres ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Confitemini Domino, et invocate nomen ejus: notas facite in populis adinventiones ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Cantate ei, et psallite ei, et narrate omnia mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Laudate nomen sanctum ejus: lætetur cor quærentium Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Quærite Dominum, et virtutem ejus: quærite faciem ejus semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Recordamini mirabilium ejus quæ fecit; signorum illius, et judiciorum oris ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'semen Israël servi ejus, filii Jacob electi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Ipse Dominus Deus noster: in universa terra judicia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Recordamini in sempiternum pacti ejus: sermonis quem præcepit in mille generationes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'quem pepigit cum Abraham, et juramenti illius cum Isaac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Et constituit illud Jacob in præceptum, et Israël in pactum sempiternum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'dicens: Tibi dabo terram Chanaan, funiculum hæreditatis vestræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'cum essent pauci numero, parvi et coloni ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Et transierunt de gente in gentem, et de regno ad populum alterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Non dimisit quemquam calumniari eos, sed increpavit pro eis reges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Nolite tangere christos meos, et in prophetis meis nolite malignari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Cantate Domino omnis terra; annuntiate ex die in diem salutare ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'narrate in gentibus gloriam ejus; in cunctis populis mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Quia magnus Dominus, et laudabilis nimis, et horribilis super omnes deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Omnes enim dii populorum idola: Dominus autem cælos fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Confessio et magnificentia coram eo: fortitudo et gaudium in loco ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Afferte Domino, familiæ populorum: afferte Domino gloriam et imperium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Date Domino gloriam; nomini ejus levate sacrificium, et venite in conspectu ejus: et adorate Dominum in decore sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Commoveatur a facie ejus omnis terra: ipse enim fundavit orbem immobilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Lætentur cæli, et exultet terra, et dicant in nationibus: Dominus regnavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Tonet mare et plenitudo ejus; exultent agri, et omnia quæ in eis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tunc laudabunt ligna saltus coram Domino: quia venit judicare terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Confitemini Domino, quoniam bonus: quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Et dicite: Salva nos, Deus salvator noster, et congrega nos, et erue de gentibus: ut confiteamur nomini sancto tuo, et exultemus in carminibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Benedictus Dominus Deus Israël, ab æterno usque in æternum. Et dicat omnis populo: Amen, et hymnum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Reliquit itaque ibi coram arca fœderis Domini Asaph et fratres ejus, ut ministrarent in conspectu arcæ jugiter per singulos dies, et vices suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Porro Obededom, et fratres ejus sexaginta octo: et Obededom filium Idithun, et Hosa, constituit janitores;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Sadoc autem sacerdotem, et fratres ejus sacerdotes, coram tabernaculo Domini in excelso quod erat in Gabaon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'ut offerrent holocausta Domino super altare holocautomatis jugiter, mane et vespere, juxta omnia quæ scripta sunt in lege Domini, quam præcepit Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Et post eum Heman, et Idithun, et reliquos electos, unumquemque vocabulo suo ad confitendum Domino, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Heman quoque et Idithun canentes tuba, et quatientes cymbala et omnia musicorum organa ad canendum Deo: filios autem Idithun fecit esse portarios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Reversusque est omnis populus in domum suam: et David, ut benediceret etiam domui suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Cum autem habitaret David in domo sua, dixit ad Nathan prophetam: Ecce ego habito in domo cedrina: arca autem fœderis Domini sub pellibus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et ait Nathan ad David: Omnia quæ in corde tuo sunt, fac: Deus enim tecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Igitur nocte illa factus est sermo Dei ad Nathan, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Vade, et loquere David servo meo: Hæc dicit Dominus: Non ædificabis tu mihi domum ad habitandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Neque enim mansi in domo ex eo tempore quo eduxi Israël usque ad diem hanc: sed fui semper mutans loca tabernaculi, et in tentorio');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'manens cum omni Israël. Numquid locutus sum saltem uni judicum Israël, quibus præceperam ut pascerent populum meum, et dixi: Quare non ædificastis mihi domum cedrinam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Nunc itaque sic loqueris ad servum meum David: Hæc dicit Dominus exercituum: Ego tuli te, cum in pascuis sequereris gregem, ut esses dux populi mei Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'et fui tecum quocumque perrexisti, et interfeci omnes inimicos tuos coram te, fecique tibi nomen quasi unius magnorum qui celebrantur in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Et dedi locum populo meo Israël: plantabitur, et habitabit in eo, et ultra non commovebitur: nec filii iniquitatis atterent eos, sicut a principio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'ex diebus quibus dedi judices populo meo Israël, et humiliavi universos inimicos tuos. Annuntio ergo tibi, quod ædificaturus sit tibi Dominus domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Cumque impleveris dies tuos ut vadas ad patres tuos, suscitabo semen tuum post te, quod erit de filiis tuis: et stabiliam regnum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Ipse ædificabit mihi domum, et firmabo solium ejus usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ego ero ei in patrem, et ipse erit mihi in filium: et misericordiam meam non auferam ab eo, sicut abstuli ab eo qui ante te fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Et statuam eum in domo mea, et in regno meo usque in sempiternum: et thronus ejus erit firmissimus in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Juxta omnia verba hæc, et juxta universam visionem istam, sic locutus est Nathan ad David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Cumque venisset rex David, et sedisset coram Domino, dixit: Quis ego sum, Domine Deus, et quæ domus mea, ut præstares mihi talia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'sed et hoc parum visum est in conspectu tuo, ideoque locutus es super domum servi tui etiam in futurum: et fecisti me spectabilem super omnes homines, Domine Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Quid ultra addere potest David, cum ita glorificaveris servum tuum, et cognoveris eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Domine, propter famulum tuum juxta cor tuum fecisti omnem magnificentiam hanc, et nota esse voluisti universa magnalia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Domine, non est similis tui, et non est alius deus absque te, ex omnibus quos audivimus auribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Quis enim est alius, ut populus tuus Israël, gens una in terra, ad quam perrexit Deus ut liberaret et faceret populum sibi, et magnitudine sua atque terroribus ejiceret nationes a facie ejus, quem de \'gypto liberarat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Et posuisti populum tuum Israël tibi in populum usque in æternum, et tu, Domine, factus es Deus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nunc igitur Domine, sermo quem locutus es famulo tuo et super domum ejus confirmetur in perpetuum, et fac sicut locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Permaneatque et magnificetur nomen tuum usque in sempiternum, et dicatur: Dominus exercituum Deus Israël, et domus David servi ejus permanens coram eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Tu enim, Domine Deus meus, revelasti auriculam servi tui, ut ædificares ei domum: et idcirco invenit servus tuus fiduciam, ut oret coram te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nunc ergo Domine, tu es Deus, et locutus es ad servum tuum tanta beneficia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Et cœpisti benedicere domui servi tui, ut sit semper coram te: te enim, Domine, benedicente, benedicta erit in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Factum est autem post hæc, ut percuteret David Philisthiim, et humiliaret eos, et tolleret Geth et filias ejus de manu Philisthiim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'percuteretque Moab, et fierent Moabitæ servi David, offerentes ei munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Eo tempore percussit David etiam Adarezer regem Soba regionis Hemath, quando perrexit ut dilataret imperium suum usque ad flumen Euphraten.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Cepit ergo David mille quadrigas ejus, et septem millia equitum, ac viginti millia virorum peditum, subnervavitque omnes equos curruum, exceptis centum quadrigis, quas reservavit sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Supervenit autem et Syrus Damascenus, ut auxilium præberet Adarezer regi Soba: sed et hujus percussit David viginti duo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Et posuit milites in Damasco, ut Syria quoque serviret sibi, et offerret munera. Adjuvitque eum Dominus in cunctis ad quæ perrexerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Tulit quoque David pharetras aureas, quas habuerant servi Adarezer, et attulit eas in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Necnon de Thebath et Chun urbibus Adarezer æris plurimum, de quo fecit Salomon mare æneum, et columnas, et vasa ænea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Quod cum audisset Thou rex Hemath, percussisse videlicet David omnem exercitum Adarezer regis Soba,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'misit Adoram filium suum ad regem David, ut postularet ab eo pacem, et congratularetur ei quod percussisset et expugnasset Adarezer: adversarius quippe erat Thou Adarezer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Sed et omnia vasa aurea, et argentea, et ænea consecravit David rex Domino, cum argento et auro quod tulerat ex universis gentibus, tam de Idumæa, et Moab, et filiis Ammon, quam de Philisthiim et Amalec.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abisai vero filius Sarviæ percussit Edom in valle Salinarum, decem et octo millia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'et constituit in Edom præsidium, ut serviret Idumæa David: salvavitque Dominus David in cunctis ad quæ perrexerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Regnavit ergo David super universum Israël, et faciebat judicium atque justitiam cuncto populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Porro Joab filius Sarviæ erat super exercitum, et Josaphat filius Ahilud a commentariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sadoc autem filius Achitob, et Ahimelech filius Abiathar, sacerdotes: et Susa, scriba:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Banaias quoque filius Jojadæ super legiones Cerethi et Phelethi: porro filii David, primi ad manum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Accidit autem ut moreretur Naas rex filiorum Ammon, et regnaret filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Dixitque David: Faciam misericordiam cum Hanon filio Naas: præstitit enim mihi pater ejus gratiam. Misitque David nuntios ad consolandum eum super morte patris sui. Qui cum pervenissent in terram filiorum Ammon ut consolarentur Hanon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'dixerunt principes filiorum Ammon ad Hanon: Tu forsitan putas, quod David honoris causa in patrem tuum miserit qui consolentur te: nec animadvertis quod ut explorent, et investigent, et scrutentur terram tuam, venerint ad te servi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Igitur Hanon pueros David decalvavit, et rasit, et præcidit tunicas eorum a natibus usque ad pedes, et dimisit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Qui cum abiissent, et hoc mandassent David, misit in occursum eorum (grandem enim contumeliam sustinuerant) et præcepit ut manerent in Jericho, donec cresceret barba eorum, et tunc reverterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Videntes autem filii Ammon quod injuriam fecissent David, tam Hanon quam reliquus populus, miserunt mille talenta argenti, ut conducerent sibi de Mesopotamia, et de Syria Maacha, et de Soba currus et equites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Conduxeruntque triginta duo millia curruum, et regem Maacha cum populo ejus. Qui cum venissent, castrametati sunt e regione Medaba. Filii quoque Ammon congregati de urbibus suis venerunt ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Quod cum audisset David, misit Joab, et omnem exercitum virorum fortium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'egressique filii Ammon, direxerunt aciem juxta portam civitatis; reges autem, qui ad auxilium ejus venerant, separatim in agro steterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Igitur Joab, intelligens bellum ex adverso et post tergum contra se fieri, elegit viros fortissimos de universo Israël, et perrexit contra Syrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Reliquam autem partem populi dedit sub manu Abisai fratris sui: et perrexerunt contra filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Dixitque: Si vicerit me Syrus, auxilio eris mihi: si autem superaverint te filii Ammon, ero tibi in præsidium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Confortare, et agamus viriliter pro populo nostro, et pro urbibus Dei nostri: Dominus autem, quod in conspectu suo bonum est, faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Perrexit ergo Joab et populus qui cum eo erat, contra Syrum ad prælium: et fugavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Porro filii Ammon videntes quod fugisset Syrus, ipsi quoque fugerunt Abisai fratrem ejus, et ingressi sunt civitatem: reversusque est etiam Joab in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Videns autem Syrus quod cecidisset coram Israël, misit nuntios, et adduxit Syrum, qui erat trans fluvium: Sophach autem princeps militiæ Adarezer erat dux eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Quod cum nuntiatum esset David, congregavit universum Israël, et transivit Jordanem, irruitque in eos et direxit ex adverso aciem, illis contra pugnantibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Fugit autem Syrus Israël, et interfecit David de Syris septem millia curruum, et quadraginta millia peditum, et Sophach exercitus principem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Videntes autem servi Adarezer se ab Israël esse superatos, transfugerunt ad David, et servierunt ei: noluitque ultra Syria auxilium præbere filiis Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Factum est autem post anni circulum, eo tempore quo solent reges ad bella procedere, congregavit Joab exercitum, et robur militiæ, et vastavit terram filiorum Ammon: perrexitque et obsedit Rabba. Porro David manebat in Jerusalem, quando Joab percussit Rabba et destruxit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Tulit autem David coronam Melchom de capite ejus, et invenit in ea auri pondo talentum, et pretiosissimas gemmas, fecitque sibi inde diadema: manubias quoque urbis plurimas tulit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'populum autem, qui erat in ea, eduxit, et fecit super eos tribulas, et trahas, et ferrata carpenta transire, ita ut dissecarentur et contererentur. Sic fecit David cunctis urbibus filiorum Ammon: et reversus est cum omni populo suo in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Post hæc initum est bellum in Gazer adversum Philisthæos, in quo percussit Sobochai Husathites, Saphai de genere Raphaim, et humiliavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Aliud quoque bellum gestum est adversus Philisthæos, in quo percussit Adeodatus filius Saltus Bethlehemites fratrem Goliath Gethæi, cujus hastæ lignum erat quasi liciatorium texentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Sed et aliud bellum accidit in Geth, in quo fuit homo longissimus, senos habens digitos, id est, simul viginti quatuor: qui et ipse de Rapha fuerat stirpe generatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Hic blasphemavit Israël: et percussit eum Jonathan filius Samaa fratris David. Hi sunt filii Rapha in Geth, qui ceciderunt in manu David et servorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Consurrexit autem Satan contra Israël, et concitavit David ut numeraret Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Dixitque David ad Joab et ad principes populi: Ite, et numerate Israël a Bersabee usque Dan: et afferte mihi numerum ut sciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Responditque Joab: Augeat Dominus populum suum centuplum quam sunt: nonne, domine mi rex, omnes servi tui sunt? quare hoc quærit dominus meus, quod in peccatum reputetur Israëli?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Sed sermo regis magis prævaluit: egressusque est Joab, et circuivit universum Israël: et reversus est Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'deditque David numerum eorum quos circuierat: et inventus est omnis numerus Israël, mille millia et centum millia virorum educentium gladium: de Juda autem quadringenta septuaginta millia bellatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Nam Levi et Benjamin non numeravit: eo quod Joab invitus exsequeretur regis imperium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Displicuit autem Deo quod jussum erat: et percussit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Dixitque David ad Deum: Peccavi nimis ut hoc facerem: obsecro, aufer iniquitatem servi tui, quia insipienter egi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et locutus est Dominus ad Gad videntem Davidis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Vade, et loquere ad David, et dic ei: Hæc dicit Dominus: Trium tibi optionem do: unum, quod volueris, elige, et faciam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Cumque venisset Gad ad David, dixit ei: Hæc dicit Dominus: Elige, quod volueris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'aut tribus annis famem; aut tribus mensibus te fugere hostes tuos, et gladium eorum non posse evadere; aut tribus diebus gladium Domini, et pestilentiam versari in terra, et angelum Domini interficere in universis finibus Israël: nunc igitur vide quid respondeam ei qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Et dixit David ad Gad: Ex omni parte me angustiæ premunt: sed melius mihi est ut incidam in manus Domini, quia multæ sunt miserationes ejus, quam in manus hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Misit ergo Dominus pestilentiam in Israël: et ceciderunt de Israël septuaginta millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Misit quoque angelum in Jerusalem ut percuteret eam: cumque percuteretur, vidit Dominus, et misertus est super magnitudine mali: et imperavit angelo qui percutiebat: Sufficit, jam cesset manus tua. Porro angelus Domini stabat juxta aream Ornan Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Levansque David oculos suos, vidit angelum Domini stantem inter cælum et terram, et evaginatum gladium in manu ejus, et versum contra Jerusalem: et ceciderunt tam ipse quam majores natu, vestiti ciliciis, proni in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Dixitque David ad Deum: Nonne ego sum, qui jussi ut numeraretur populus? ego, qui peccavi? ego, qui malum feci? iste grex, quid commeruit? Domine Deus meus, vertatur, obsecro, manus tua in me, et in domum patris mei: populus autem tuus non percutiatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Angelus autem Domini præcepit Gad ut diceret Davidi ut ascenderet, exstrueretque altare Domino Deo in area Ornan Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Ascendit ergo David juxta sermonem Gad, quem locutus ei fuerat ex nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Porro Ornan cum suspexisset et vidisset angelum, quatuorque filii ejus cum eo, absconderunt se: nam eo tempore terebat in area triticum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Igitur cum veniret David ad Ornan, conspexit eum Ornan, et processit ei obviam de area, et adoravit eum pronus in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Dixitque ei David: Da mihi locum areæ tuæ, ut ædificem in ea altare Domino: ita ut quantum valet argenti accipias, et cesset plaga a populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Dixit autem Ornan ad David: Tolle, et faciat dominus meus rex quodcumque ei placet: sed et boves do in holocaustum, et tribulas in ligna, et triticum in sacrificium: omnia libens præbebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Dixitque ei rex David: Nequaquam ita fiet, sed argentum dabo quantum valet: neque enim tibi auferre debeo, et sic offerre Domino holocausta gratuita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Dedit ergo David Ornan pro loco siclos auri justissimi ponderis sexcentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Et ædificavit ibi altare Domino, obtulitque holocausta et pacifica, et invocavit Dominum; et exaudivit eum in igne de cælo super altare holocausti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Præcepitque Dominus angelo, et convertit gladium suum in vaginam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Protinus ergo David, videns quod exaudisset eum Dominus in area Ornan Jebusæi, immolavit ibi victimas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Tabernaculum autem Domini, quod fecerat Moyses in deserto, et altare holocaustorum, ea tempestate erat in excelso Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Et non prævaluit David ire ad altare ut ibi obsecraret Deum: nimio enim fuerat in timore perterritus, videns gladium angeli Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Dixitque David: Hæc est domus Dei, et hoc altare in holocaustum Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Et præcepit ut congregarentur omnes proselyti de terra Israël, et constituit ex eis latomos ad cædendos lapides et poliendos, ut ædificaretur domus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Ferrum quoque plurimum ad clavos januarum, et ad commissuras atque juncturas, præparavit David: et æris pondus innumerabile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Ligna quoque cedrina non poterant æstimari, quæ Sidonii et Tyrii deportaverant ad David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Et dixit David: Solomon filius meus puer parvulus est et delicatus: domus autem, quam ædificari volo Domino, talis esse debet ut in cunctis regionibus nominetur: præparabo ergo ei necessaria. Et ob hanc causam ante mortem suam omnes præparavit impensas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Vocavitque Salomonem filium suum, et præcepit ei ut ædificaret domum Domino Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Dixitque David ad Salomonem: Fili mi, voluntatis meæ fuit ut ædificarem domum nomini Domini Dei mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'sed factus est sermo Domini ad me, dicens: Multum sanguinem effudisti, et plurima bella bellasti: non poteris ædificare domum nomini meo, tanto effuso sanguine coram me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'filius qui nascetur tibi, erit vir quietissimus: faciam enim eum requiescere ab omnibus inimicis suis per circuitum: et ob hanc causam Pacificus vocabitur: et pacem et otium dabo in Israël cunctis diebus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Ipse ædificabit domum nomini meo, et ipse erit mihi in filium, et ego ero illi in patrem: firmaboque solium regni ejus super Israël in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nunc ergo fili mi, sit Dominus tecum, et prosperare, et ædifica domum Domino Deo tuo sicut locutus est de te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Det quoque Dominus prudentiam et sensum ut regere possis Israël, et custodire legem Domini Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tunc enim proficere poteris, si custodieris mandata et judicia quæ præcepit Dominus Moysi ut doceret Israël. Confortare, et viriliter age: ne timeas, neque paveas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Ecce ego in paupertate mea præparavi impensas domus Domini, auri talenta centum millia, et argenti mille millia talentorum: æris vero et ferri non est pondus, vincitur enim numerus magnitudine; ligna et lapides præparavi ad universa impendia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Habes quoque plurimos artifices, latomos, et cæmentarios, artificesque lignorum, et omnium artium ad faciendum opus prudentissimos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'in auro et argento et ære et ferro, cujus non est numerus. Surge igitur et fac, et erit Dominus tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Præcepit quoque David cunctis principibus Israël ut adjuvarent Salomonem filium suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Cernitis, inquiens, quod Dominus Deus vester vobiscum sit, et dederit vobis requiem per circuitum, et tradiderit omnes inimicos vestros in manus vestras, et subjecta sit terra coram Domino, et coram populo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Præbete igitur corda vestra et animas vestras, ut quæratis Dominum Deum vestrum: et consurgite, et ædificate sanctuarium Domino Deo, ut introducatur arca fœderis Domini, et vasa Domino consecrata, in domum quæ ædificatur nomini Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Igitur David, senex et plenus dierum, regem constituit Salomonem filium suum super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Et congregavit omnes principes Israël, et sacerdotes atque Levitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Numeratique sunt Levitæ a triginta annis et supra: et inventa sunt triginta octo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Ex his electi sunt, et distributi in ministerium domus Domini, viginti quatuor millia: præpositorum autem et judicum, sex millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Porro quatuor millia janitores, et totidem psaltæ, canentes Domino in organis quæ fecerat ad canendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Et distribuit eos David per vices filiorum Levi, Gerson videlicet, et Caath, et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Filii Gerson: Leedan, et Semei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Filii Leedan: princeps Jahiel, et Zethan, et Joël, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Filii Semei: Salomith, et Hosiel, et Aran, tres: isti principes familiarum Leedan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Porro filii Semei: Leheth, et Ziza, et Jaus, et Baria: isti filii Semei, quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Erat autem Leheth prior, Ziza secundus: porro Jaus et Baria non habuerunt plurimos filios, et idcirco in una familia, unaque domo computati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Filii Caath: Amram, et Isaar, Hebron, et Oziel, quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Filii Amram: Aaron et Moyses. Separatusque est Aaron ut ministraret in Sancto sanctorum, ipse et filii ejus in sempiternum, et adoleret incensum Domino secundum ritum suum, ac benediceret nomini ejus in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Moysi quoque hominis Dei filii annumerati sunt in tribu Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Filii Moysi: Gersom et Eliezer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Filii Gersom: Subuel primus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Fuerunt autem filii Eliezer: Rohobia primus: et non erant Eliezer filii alii. Porro filii Rohobia multiplicati sunt nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Filii Isaar: Salomith primus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Filii Hebron: Jeriau primus, Amarias secundus, Jahaziel tertius, Jecmaam quartus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Filii Oziel: Micha primus, Jesia secundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Filii Merari: Moholi, et Musi. Filii Moholi: Eleazar et Cis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Mortuus est autem Eleazar, et non habuit filios, sed filias: acceperuntque eas filii Cis fratres earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Filii Musi: Moholi, et Eder, et Jerimoth, tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Hi filii Levi in cognationibus et familiis suis, principes per vices, et numerum capitum singulorum qui faciebant opera ministerii domus Domini, a viginti annis et supra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Dixit enim David: Requiem dedit Dominus Deus Israël populo suo, et habitationem Jerusalem usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Nec erit officii Levitarum ut ultra portent tabernaculum et omnia vasa ejus ad ministrandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Juxta præcepta quoque David novissima, supputabitur numerus filiorum Levi a viginti annis et supra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Et erunt sub manu filiorum Aaron in cultum domus Domini, in vestibulis, et in exedris, et in loco purificationis, et in sanctuario, et in universis operibus ministerii templi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Sacerdotes autem, super panes propositionis, et ad similæ sacrificium, et ad lagana azyma, et sartaginem, et ad torrendum, et super omne pondus atque mensuram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Levitæ vero ut stent mane ad confitendum et canendum Domino: similiterque ad vesperam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'tam in oblatione holocaustorum Domini, quam in sabbatis et calendis et solemnitatibus reliquis juxta numerum et cæremonias uniuscujusque rei, jugiter coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Et custodiant observationes tabernaculi fœderis, et ritum sanctuarii, et observationem filiorum Aaron fratrum suorum, ut ministrent in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Porro filiis Aaron hæ partitiones erant. Filii Aaron: Nadab, et Abiu, et Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Mortui sunt autem Nadab et Abiu ante patrem suum absque liberis: sacerdotioque functus est Eleazar, et Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Et divisit eos David, id est, Sadoc de filiis Eleazari, et Ahimelech de filiis Ithamar, secundum vices suas et ministerium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Inventique sunt multo plures filii Eleazar in principibus viris, quam filii Ithamar. Divisit autem eis, hoc est, filiis Eleazar, principes per familias sedecim: et filiis Ithamar per familias et domos suas octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Porro divisit utrasque inter se familias sortibus: erant enim principes sanctuarii, et principes Dei, tam de filiis Eleazar quam de filiis Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Descripsitque eos Semeias filius Nathanaël scriba Levites, coram rege et principibus, et Sadoc sacerdote, et Ahimelech filio Abiathar, principibus quoque familiarum sacerdotalium, et Leviticarum: unam domum, quæ ceteris præerat, Eleazar: et alteram domum, quæ sub se habebat ceteros, Ithamar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Exivit autem sors prima Jojarib, secunda Jedei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'tertia Harim, quarta Seorim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'quinta Melchia, sexta Maiman,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'septima Accos, octava Abia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'nona Jesua, decima Sechenia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'undecima Eliasib, duodecima Jacim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'tertiadecima Hoppha, decimaquarta Isbaab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'decimaquinta Belga, decimasexta Emmer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'decimaseptima Hezir, decimaoctava Aphses,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'decimanona Pheteia, vigesima Hezechiel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'vigesima prima Jachin, vigesima secunda Gamul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'vigesima tertia Dalaiau, vigesima quarta Maaziau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Hæ vices eorum secundum ministeria sua, ut ingrediantur domum Domini, et juxta ritum suum sub manu Aaron patris eorum, sicut præceperat Dominus Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Porro filiorum Levi qui reliqui fuerant, de filiis Amram erat Subaël, et de filiis Subaël, Jehedeia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'De filiis quoque Rohobiæ, princeps Jesias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Isaari vero filius Salemoth, filiusque Salemoth Jahath:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'filiusque ejus Jeriau primus, Amarias secundus, Jahaziel tertius, Jecmaan quartus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Filius Oziel, Micha: filius Micha, Samir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Frater Micha, Jesia: filiusque Jesiæ, Zacharias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Filii Merari: Moholi, et Musi. Filius Oziau: Benno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Filius quoque Merari: Oziau, et Soam, et Zachur, et Hebri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Porro Moholi filius, Eleazar, qui non habebat liberos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Filius vero Cis, Jerameel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Filii Musi: Moholi, Eder et Jerimoth: isti filii Levi secundum domos familiarum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Miseruntque et ipsi sortes contra fratres suos filios Aaron coram David rege, et Sadoc, et Ahimelech, et principibus familiarum sacerdotalium et Leviticarum, tam majores quam minores: omnes sors æqualiter dividebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Igitur David et magistratus exercitus segregaverunt in ministerium filios Asaph, et Heman, et Idithun, qui prophetarent in citharis, et psalteriis, et cymbalis secundum numerum suum, dedicato sibi officio servientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'De filiis Asaph: Zachur, et Joseph, et Nathania, et Asarela, filii Asaph: sub manu Asaph prophetantis juxta regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Porro Idithun: filii Idithun, Godolias, Sori, Jeseias, et Hasabias, et Mathathias, sex, sub manu patris sui Idithun, qui in cithara prophetabat super confitentes et laudantes Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Heman quoque: filii Heman, Bocciau, Mathaniau, Oziel, Subuel, et Jerimoth, Hananias, Hanani, Eliatha, Geddelthi, et Romemthiezer, et Jesbacassa, Mellothi, Othir, Mahazioth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'omnes isti filii Heman videntis regis in sermonibus Dei, ut exaltaret cornu: deditque Deus Heman filios quatuordecim, et filias tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Universi sub manu patris sui ad cantandum in templo Domini distributi erant, in cymbalis, et psalteriis, et citharis, in ministeria domus Domini juxta regem: Asaph videlicet, et Idithun, et Heman.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Fuit autem numerus eorum cum fratribus suis, qui erudiebant canticum Domini, cuncti doctores, ducenti octoginta octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Miseruntque sortes per vices suas, ex æquo tam major quam minor, doctus pariter et indoctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Egressaque est sors prima Joseph, qui erat de Asaph. Secunda Godoliæ, ipsi et filiis ejus, et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Tertia Zachur, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Quarta Isari, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Quinta Nathaniæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Sexta Bocciau, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Septima Isreela, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Octava Jesaiæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Nona Mathaniæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Decima Semeiæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Undecima Azareel, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Duodecima Hasabiæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Tertiadecima Subaël, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Quartadecima Mathathiæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Quintadecima Jerimoth, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Sextadecima Hananiæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Septimadecima Jesbacassæ, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Octavadecima Hanani, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Nonadecima Mellothi, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Vigesima Eliatha, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Vigesima prima Othir, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Vigesima secunda Geddelthi, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Vigesima tertia Mahazioth, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Vigesima quarta Romemthiezer, filiis et fratribus ejus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Divisiones autem janitorum: de Coritis Meselemia, filius Core, de filiis Asaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Filii Meselemiæ: Zacharias primogenitus, Jadihel secundus, Zabadias tertius, Jathanaël quartus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, '\'lam quintus, Johanan sextus, Elioënai septimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Filii autem Obededom: Semeias primogenitus, Jozabad secundus, Joaha tertius, Sachar quartus, Nathanaël quintus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel sextus, Issachar septimus, Phollathi octavus: quia benedixit illi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Semei autem filio ejus nati sunt filii, præfecti familiarum suarum: erant enim viri fortissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Filii ergo Semeiæ: Othni, et Raphaël, et Obed, Elzabad, fratres ejus viri fortissimi: Eliu quoque et Samachias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Omnes hi, de filiis Obededom: ipsi, et filii et fratres eorum, fortissimi ad ministrandum, sexaginta duo de Obededom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Porro Meselemiæ filii, et fratres eorum robustissimi, decem et octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'De Hosa autem, id est, de filiis Merari: Semri princeps (non enim habuerat primogenitum, et idcirco posuerat eum pater ejus in principem),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Helcias secundus, Tabelias tertius, Zacharias quartus: omnes hi filii et fratres Hosa, tredecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Hi divisi sunt in janitores, ut semper principes custodiarum, sicut et fratres eorum ministrarent in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Missæ sunt ergo sortes ex æquo, et parvis et magnis, per familias suas in unamquamque portarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Cecidit ergo sors orientalis, Selemiæ. Porro Zachariæ filio ejus, viro prudentissimo et erudito, sortito obtigit plaga septentrionalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obededom vero et filiis ejus ad austrum: in qua parte domus erat seniorum concilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Sephim et Hosa ad occidentem, juxta portam, quæ ducit ad viam ascensionis: custodia contra custodiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Ad orientem vero Levitæ sex: et ad aquilonem, quatuor per diem: atque ad meridiem similiter in die quatuor: et ubi erat concilium bini et bini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'In cellulis quoque janitorum ad occidentem quatuor in via, binique per cellulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Hæ sunt divisiones janitorum filiorum Core et Merari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Porro Achias erat super thesauros domus Dei, et vasa sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Filii Ledan, filii Gersonni: de Ledan principes familiarum Ledan, et Gersonni, Jehieli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Filii Jehieli: Zathan, et Joël fratres ejus super thesauros domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Amramitis, et Isaaritis, et Hebronitis, et Ozihelitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Subaël autem filius Gersom filii Moysi, præpositus thesauris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Fratres quoque ejus Eliezer, cujus filius Rahabia, et hujus filius Isaias, et hujus filius Joram, hujus quoque filius Zechri, et hujus filius Selemith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ipse Selemith, et fratres ejus, super thesauros sanctorum quæ sanctificavit David rex, et principes familiarum, et tribuni, et centuriones, et duces exercitus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'de bellis et manubiis præliorum, quæ consecraverant ad instaurationem et supellectilem templi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Hæc autem universa sanctificavit Samuel videns, et Saul filius Cis, et Abner filius Ner, et Joab filius Sarviæ: omnes qui sanctificaverant ea per manum Selemith et fratrum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Isaaritis vero præerat Chonenias, et filii ejus ad opera forinsecus super Israël ad docendum et judicandum eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Porro de Hebronitis Hasabias, et fratres ejus viri fortissimi, mille septingenti præerant Israëli trans Jordanem contra occidentem, in cunctis operibus Domini, et in ministerium regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Hebronitarum autem princeps fuit Jeria secundum familias et cognationes eorum. Quadragesimo anno regni David recensiti sunt, et inventi sunt viri fortissimi in Jazer Galaad,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'fratresque ejus robustioris ætatis, duo millia septingenti principes familiarum. Præposuit autem eos David rex Rubenitis, et Gadditis, et dimidiæ tribui Manasse, in omne ministerium Dei et regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Filii autem Israël secundum numerum suum, principes familiarum, tribuni, et centuriones, et præfecti, qui ministrabant regi juxta turmas suas, ingredientes et egredientes per singulos menses in anno, viginti quatuor millibus singuli præerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Primæ turmæ in primo mense Jesboam præerat filius Zabdiel, et sub eo viginti quatuor millia;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'de filiis Phares, princeps cunctorum principum in exercitu mense primo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Secundi mensis habebat turmam Dudia Ahohites, et post se alter nomine Macelloth, qui regebat partem exercitus viginti quatuor millium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Dux quoque turmæ tertiæ in mense tertio erat Banaias filius Jojadæ sacerdos: et in divisione sua viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ipse est Banaias fortissimus inter triginta, et super triginta: præerat autem turmæ ipsius Amizabad filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Quartus, mense quarto, Asahel frater Joab, et Zabadias filius ejus post eum: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Quintus, mense quinto, princeps Samaoth Jezerites: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Sextus, mense sexto, Hira filius Acces Thecuites: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Septimus, mense septimo, Helles Phallonites de filiis Ephraim: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Octavus, mense octavo, Sobochai Husathites de stirpe Zarahi: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Nonus, mense nono, Abiezer Anathothites de filiis Jemini: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Decimus, mense decimo, Marai, et ipse Netophathites de stirpe Zarai: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Undecimus, mense undecimo, Banaias Pharathonites de filiis Ephraim: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Duodecimus, mense duodecimo, Holdai Netophathites, de stirpe Gothoniel: et in turma ejus viginti quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Porro tribubus præerant Israël, Rubenitis, dux Eliezer filius Zechri: Simeonitis, dux Saphatias filius Maacha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Levitis, Hasabias filius Camuel: Aaronitis, Sadoc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Juda, Eliu frater David: Issachar, Amri filius Michaël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Zabulonitis, Jesmaias filius Abdiæ: Nephthalitibus, Jerimoth filius Ozriel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'filiis Ephraim, Osee filius Ozaziu: dimidiæ tribui Manasse, Joël filius Phadaiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'et dimidiæ tribui Manasse in Galaad, Jaddo filius Zachariæ: Benjamin autem, Jasiel filius Abner:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Dan vero, Ezrihel filius Jeroham: hi principes filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Noluit autem David numerare eos a viginti annis inferius: quia dixerat Dominus ut multiplicaret Israël quasi stellas cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab filius Sarviæ cœperat numerare, nec complevit: quia super hoc ira irruerat in Israël, et idcirco numerus eorum qui fuerant recensiti, non est relatus in fastos regis David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Super thesauros autem regis fuit Azmoth filius Adiel: his autem thesauris, qui erant in urbibus, et in vicis, et in turribus, præsidebat Jonathan filius Oziæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Operi autem rustico, et agricolis qui exercebant terram, præerat Ezri filius Chelub:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'vinearumque cultoribus, Semeias Romathites: cellis autem vinariis, Zabdias Aphonites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nam super oliveta et ficeta quæ erant in campestribus, Balanam Gederites: super apothecas autem olei, Joas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Porro armentis quæ pascebantur in Saron, præpositus fuit Setrai Saronites: et super boves in vallibus, Saphat filius Adli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'super camelos vero, Ubil Ismahelites: et super asinos, Jadias Meronathites:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'super oves quoque, Jaziz Agareus: omnes hi, principes substantiæ regis David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonathan autem patruus David, consiliarius, vir prudens et litteratus: ipse et Jahiel filius Hachamoni erant cum filiis regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitophel etiam consiliarius regis, et Chusai Arachites amicus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Post Achitophel fuit Jojada filius Banaiæ, et Abiathar. Princeps autem exercitus regis erat Joab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Convocavit igitur David omnes principes Israël, duces tribuum, et præpositos turmarum, qui ministrabant regi: tribunos quoque et centuriones, et qui præerant substantiæ et possessionibus regis, filiosque suos cum eunuchis, et potentes et robustissimos quosque in exercitu Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Cumque surrexisset rex, et stetisset, ait: Audite me, fratres mei et populus meus: cogitavi ut ædificarem domum, in qua requiesceret arca fœderis Domini, et scabellum pedum Dei nostri: et ad ædificandum, omnia præparavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Deus autem dixit mihi: Non ædificabis domum nomini meo, eo quod sis vir bellator, et sanguinem fuderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Sed elegit Dominus Deus Israël me de universa domo patris mei, ut essem rex super Israël in sempiternum: de Juda enim elegit principes: porro de domo Juda, domum patris mei, et de filiis patris mei placuit ei ut me eligeret regem super cunctum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Sed et de filiis meis (filios enim mihi multos dedit Dominus) elegit Salomonem filium meum ut sederet in throno regni Domini super Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'dixitque mihi: Salomon filius tuus ædificabit domum meam, et atria mea: ipsum enim elegi mihi in filium, et ego ero ei in patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Et firmabo regnum ejus usque in æternum, si perseveraverit facere præcepta mea et judicia, sicut et hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nunc ergo coram universo cœtu Israël audiente Deo nostro, custodite, et perquirite cuncta mandata Domini Dei nostri: ut possideatis terram bonam, et relinquatis eam filiis vestris post vos usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Tu autem, Salomon fili mi, scito Deum patris tui, et servito ei corde perfecto, animo voluntario: omnia enim corda scrutatur Dominus, et universas mentium cogitationes intelligit. Si quæsieris eum, invenies: si autem dereliqueris eum, projiciet te in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Nunc ergo quia elegit te Dominus ut ædificares domum sanctuarii, confortare, et perfice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Dedit autem David Salomoni filio suo descriptionem porticus, et templi, et cellariorum, et cœnaculi, et cubiculorum in adytis, et domus propitiationis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'necnon et omnium quæ cogitaverat atriorum et exedrarum per circuitum in thesauros domus Domini, et in thesauros sanctorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'divisionumque sacerdotalium et Leviticarum, in omnia opera domus Domini, et in universa vasa ministerii templi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Aurum in pondere per singula vasa ministerii. Argenti quoque pondus pro vasorum et operum diversitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Sed et in candelabra aurea, et ad lucernas eorum, aurum pro mensura uniuscujusque candelabri et lucernarum. Similiter et in candelabra argentea, et in lucernas eorum, pro diversitate mensuræ, pondus argenti tradidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Aurum quoque dedit in mensas propositionis pro diversitate mensarum: similiter et argentum in alias mensas argenteas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Ad fuscinulas quoque, et phialas, et thuribula ex auro purissimo, et leunculos aureos pro qualitate mensuræ pondus distribuit in leunculum et leunculum. Similiter et in leones argenteos diversum argenti pondus separavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Altari autem, in quo adoletur incensum, aurum purissimum dedit: ut ex ipso fieret similitudo quadrigæ cherubim extendentium alas, et velantium arcam fœderis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Omnia, inquit, venerunt scripta manu Domini ad me, ut intelligerem universa opera exemplaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Dixit quoque David Salomoni filio suo: Viriliter age, et confortare, et fac: ne timeas, et ne paveas: Dominus enim Deus meus tecum erit, et non dimittet te nec derelinquet, donec perficias omne opus ministerii domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Ecce divisiones sacerdotum et Levitarum: in omne ministerium domus Domini assistunt tibi, et parati sunt, et noverunt tam principes quam populus facere omnia præcepta tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Locutusque est David rex ad omnem ecclesiam: Salomonem filium meum unum elegit Deus, adhuc puerum et tenellum: opus namque grande est, neque enim homini præparatur habitatio, sed Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Ego autem totis viribus meis præparavi impensas domus Dei mei. Aurum ad vasa aurea, et argentum in argentea, æs in ænea, ferrum in ferrea, ligna ad lignea: et lapides onychinos, et quasi stibinos, et diversorum colorum, omnemque pretiosum lapidem, et marmor Parium abundantissime:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'et super hæc quæ obtuli in domum Dei mei de peculio meo aurum et argentum, do in templum Dei mei, exceptis his quæ præparavi in ædem sanctam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Tria millia talenta auri de auro Ophir, et septem millia talentorum argenti probatissimi ad deaurandos parietes templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Et ubicumque opus est aurum de auro, et ubicumque opus est argentum de argento, opera fiant per manus artificum: et si quis sponte offert, impleat manum suam hodie, et offerat quod voluerit Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Polliciti sunt itaque principes familiarum, et proceres tribuum Israël, tribuni quoque, et centuriones, et principes possessionum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Dederuntque in opera domus Dei auri talenta quinque millia, et solidos decem millia: argenti talenta decem millia, et æris talenta decem et octo millia: ferri quoque centum millia talentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Et apud quemcumque inventi sunt lapides, dederunt in thesauros domus Domini per manum Jahiel Gersonitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Lætatusque est populus cum vota sponte promitterent, quia corde toto offerebant ea Domino: sed et David rex lætatus est gaudio magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Et benedixit Domino coram universa multitudine, et ait: Benedictus es, Domine Deus Israël patris nostri, ab æterno in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tua est, Domine, magnificentia, et potentia, et gloria, atque victoria: et tibi laus: cuncta enim quæ in cælo sunt et in terra, tua sunt: tuum, Domine, regnum, et tu es super omnes principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Tuæ divitiæ, et tua est gloria: tu dominaris omnium. In manu tua virtus et potentia: in manu tua magnitudo, et imperium omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nunc igitur Deus noster, confitemur tibi, et laudamus nomen tuum inclytum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Quis ego, et quis populus meus, ut possimus hæc tibi universa promittere? Tua sunt omnia: et quæ de manu tua accepimus, dedimus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Peregrini enim sumus coram te, et advenæ, sicut omnes patres nostri. Dies nostri quasi umbra super terram, et nulla est mora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Domine Deus noster, omnis hæc copia quam paravimus ut ædificaretur domus nomini sancto tuo, de manu tua est, et tua sunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Scio, Deus meus, quod probes corda, et simplicitatem diligas, unde et ego in simplicitate cordis mei lætus obtuli universa hæc: et populum tuum qui hic repertus est, vidi cum ingenti gaudio tibi offerre donaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Domine Deus Abraham, et Isaac, et Israël patrum nostrorum, custodi in æternum hanc voluntatem cordis eorum, et semper in venerationem tui mens ista permaneat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Salomoni quoque filio meo da cor perfectum, ut custodiat mandata tua, testimonia tua, et cæremonias tuas, et faciat universa: et ædificet ædem, cujus impensas paravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Præcepit autem David universæ ecclesiæ: Benedicite Domino Deo nostro. Et benedixit omnis ecclesia Domino Deo patrum suorum: et inclinaverunt se, et adoraverunt Deum, et deinde regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Immolaveruntque victimas Domino: et obtulerunt holocausta die sequenti, tauros mille, arietes mille, agnos mille cum libaminibus suis, et universo ritu abundantissime in omnem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et comederunt, et biberunt coram Domino in die illo cum grandi lætitia. Et unxerunt secundo Salomonem filium David. Unxerunt autem eum Domino in principem, et Sadoc in pontificem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Seditque Salomon super solium Domini in regem pro David patre suo, et cunctis placuit: et paruit illi omnis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Sed et universi principes, et potentes, et cuncti filii regis David dederunt manum, et subjecti fuerunt Salomoni regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Magnificavit ergo Dominus Salomonem super omnem Israël: et dedit illi gloriam regni, qualem nullus habuit ante eum rex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Igitur David filius Isai regnavit super universum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Et dies quibus regnavit super Israël, fuerunt quadraginta anni: in Hebron regnavit septem annis, et in Jerusalem annis triginta tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Et mortuus est in senectute bona, plenus dierum, et divitiis, et gloria: et regnavit Salomon filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Gesta autem David regis priora et novissima scripta sunt in libro Samuelis videntis, et in libro Nathan prophetæ, atque in volumine Gad videntis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'universique regni ejus, et fortitudinis, et temporum quæ transierunt sub eo, sive in Israël, sive in cunctis regnis terrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Confortatus est ergo Salomon filius David in regno suo, et Dominus Deus ejus erat cum eo, et magnificavit eum in excelsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Præcepitque Salomon universo Israëli, tribunis, et centurionibus, et ducibus, et judicibus omnis Israël, et principibus familiarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'et abiit cum universa multitudine in excelsum Gabaon, ubi erat tabernaculum fœderis Dei, quod fecit Moyses famulus Dei in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Arcam autem Dei adduxerat David de Cariathiarim in locum quem præparaverat ei, et ubi fixerat illi tabernaculum, hoc est, in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Altare quoque æneum quod fabricatus fuerat Beseleel filius Uri filii Hur, ibi erat coram tabernaculo Domini: quod et requisivit Salomon, et omnis ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Ascenditque Salomon ad altare æneum, coram tabernaculo fœderis Domini, et obtulit in eo mille hostias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Ecce autem in ipsa nocte apparuit ei Deus, dicens: Postula quod vis, ut dem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Dixitque Salomon Deo: Tu fecisti cum David patre meo misericordiam magnam, et constituisti me regem pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Nunc ergo Domine Deus, impleatur sermo tuus quem pollicitus es David patri meo: tu enim me fecisti regem super populum tuum multum, qui tam innumerabilis est quam pulvis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Da mihi sapientiam et intelligentiam, ut ingrediar et egrediar coram populo tuo: quis enim potest hunc populum tuum digne, qui tam grandis est, judicare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Dixit autem Deus ad Salomonem: Quia hoc magis placuit cordi tuo, et non postulasti divitias, et substantiam, et gloriam, neque animas eorum qui te oderant, sed nec dies vitæ plurimos: petisti autem sapientiam et scientiam, ut judicare possis populum meum super quem constitui te regem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'sapientia et scientia data sunt tibi: divitias autem et substantiam et gloriam dabo tibi, ita ut nullus in regibus nec ante te nec post te fuerit similis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Venit ergo Salomon ab excelso Gabaon in Jerusalem coram tabernaculo fœderis, et regnavit super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Congregavitque sibi currus et equites, et facti sunt ei mille quadringenti currus, et duodecim millia equitum: et fecit eos esse in urbibus quadrigarum, et cum rege in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Præbuitque rex argentum et aurum in Jerusalem quasi lapides, et cedros quasi sycomoros quæ nascuntur in campestribus multitudine magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Adducebantur autem ei equi de \'gypto et de Coa a negotiatoribus regis, qui ibant et emebant pretio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'quadrigam equorum sexcentis argenteis, et equum centum quinquaginta: similiter de universis regnis Hethæorum, et a regibus Syriæ emptio celebrabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Decrevit autem Salomon ædificare domum nomini Domini, et palatium sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Et numeravit septuaginta millia virorum portantium humeris, et octoginta millia qui cæderent lapides in montibus, præpositosque eorum tria millia sexcentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Misit quoque ad Hiram regem Tyri, dicens: Sicut egisti cum David patre meo, et misisti ei ligna cedrina ut ædificaret sibi domum, in qua et habitavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'sic fac mecum ut ædificem domum nomini Domini Dei mei, ut consecrem eam ad adolendum incensum coram illo, et fumiganda aromata, et ad propositionem panum sempiternam, et ad holocautomata mane, et vespere, sabbatis quoque, et neomeniis, et solemnitatibus Domini Dei nostri in sempiternum, quæ mandata sunt Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Domus enim quam ædificare cupio, magna est: magnus est enim Deus noster super omnes deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Quis ergo poterit prævalere, ut ædificet ei dignam domum? si cælum, et cæli cælorum, capere eum nequeunt, quantus ego sum, ut possim ædificare ei domum? sed ad hoc tantum, ut adoleatur incensum coram illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Mitte ergo mihi virum eruditum, qui noverit operari in auro, et argento, ære, et ferro, purpura, coccino, et hyacintho: et qui sciat sculpere cælaturas cum his artificibus quos mecum habeo in Judæa, et Jerusalem, quos præparavit David pater meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Sed et ligna cedrina mitte mihi, et arceuthina, et pinea de Libano: scio enim quod servi tui noverint cædere ligna de Libano: et erunt servi mei cum servis tuis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'ut parentur mihi ligna plurima. Domus enim quam cupio ædificare, magna est nimis, et inclyta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Præterea operariis qui cæsuri sunt ligna, servis tuis, dabo in cibaria tritici coros viginti millia, et hordei coros totidem, et vini viginti millia metretas, olei quoque sata viginti millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Dixit autem Hiram rex Tyri per litteras quas miserat Salomoni: Quia dilexit Dominus populum suum, idcirco te regnare fecit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et addidit, dicens: Benedictus Dominus Deus Israël, qui fecit cælum et terram: qui dedit David regi filium sapientem et eruditum et sensatum atque prudentem, ut ædificaret domum Domino, et palatium sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Misi ergo tibi virum prudentem et scientissimum Hiram patrem meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'filium mulieris de filiabus Dan, cujus pater fuit Tyrius, qui novit operari in auro, et argento, ære, et ferro, et marmore, et lignis, in purpura quoque, et hyacintho, et bysso, et coccino: et qui scit cælare omnem sculpturam, et adinvenire prudenter quodcumque in opere necessarium est cum artificibus tuis, et cum artificibus domini mei David patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Triticum ergo, et hordeum, et oleum, et vinum, quæ pollicitus es, domine mi, mitte servis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Nos autem cædemus ligna de Libano, quot necessaria habueris, et applicabimus ea ratibus per mare in Joppe: tuum autem erit transferre ea in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Numeravit igitur Salomon omnes viros proselytos qui erant in terra Israël, post dinumerationem quam dinumeravit David pater ejus, et inventi sunt centum quinquaginta millia, et tria millia sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Fecitque ex eis septuaginta millia qui humeris onera portarent, et octoginta millia qui lapides in montibus cæderent: tria autem millia et sexcentos præpositos operum populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Et cœpit Salomon ædificare domum Domini in Jerusalem in monte Moria, qui demonstratus fuerat David patri ejus, in loco quem paraverat David in area Ornan Jebusæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Cœpit autem ædificare mense secundo, anno quarto regni sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Et hæc sunt fundamenta quæ jecit Salomon, ut ædificaret domum Dei: longitudinis cubitos in mensura prima sexaginta, latitudinis cubitos viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Porticum vero ante frontem, quæ tendebatur in longum juxta mensuram latitudinis domus, cubitorum viginti: porro altitudo centum viginti cubitorum erat: et deauravit eam intrinsecus auro mundissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Domum quoque majorem texit tabulis ligneis abiegnis, et laminas auri obrizi affixit per totum: sculpsitque in ea palmas, et quasi catenulas se invicem complectentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Stravit quoque pavimentum templi pretiosissimo marmore, decore multo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Porro aurum erat probatissimum, de cujus laminis texit domum, et trabes ejus, et postes, et parietes, et ostia: et cælavit cherubim in parietibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Fecit quoque domum Sancti sanctorum: longitudinem juxta latitudinem domus cubitorum viginti: et latitudinem similiter viginti cubitorum: et laminis aureis texit eam, quasi talentis sexcentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Sed et clavos fecit aureos, ita ut singuli clavi siclos quinquagenos appenderent: cœnacula quoque texit auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Fecit etiam in domo Sancti sanctorum cherubim duos, opere statuario: et texit eos auro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Alæ cherubim viginti cubitis extendebantur, ita ut una ala haberet cubitos quinque et tangeret parietem domus: et altera quinque cubitos habens, alam tangeret alterius cherub.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Similiter cherub alterius ala, quinque habebat cubitos, et tangebat parietem: et ala ejus altera quinque cubitorum, alam cherub alterius contingebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Igitur alæ utriusque cherubim expansæ erant et extendebantur per cubitos viginti: ipsi autem stabant erectis pedibus, et facies eorum erant versæ ad exteriorem domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Fecit quoque velum ex hyacintho, purpura, cocco, et bysso: et intexuit ei cherubim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Ante fores etiam templi duas columnas, quæ triginta et quinque cubitos habebant altitudinis: porro capita earum, quinque cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Necnon et quasi catenulas in oraculo, et superposuit eas capitibus columnarum: malogranata etiam centum, quæ catenulis interposuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Ipsas quoque columnas posuit in vestibulo templi, unam a dextris, et alteram a sinistris: eam quæ a dextris erat, vocavit Jachin: et quæ ad lævam, Booz.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Fecit quoque altare æneum viginti cubitorum longitudinis, et viginti cubitorum latitudinis, et decem cubitorum altitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Mare etiam fusile decem cubitis a labio usque ad labium, rotundum per circuitum: quinque cubitos habebat altitudinis, et funiculus triginta cubitorum ambiebat gyrum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Similitudo quoque boum erat subter illud, et decem cubitis quædam extrinsecus cælaturæ, quasi duobus versibus alvum maris circuibant. Boves autem erant fusiles:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'et ipsum mare super duodecim boves impositum erat, quorum tres respiciebant ad aquilonem, et alii tres ad occidentem: porro tres alii meridiem, et tres qui reliqui erant, orientem, habentes mare superpositum: posteriora autem boum erant intrinsecus sub mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Porro vastitas ejus habebat mensuram palmi, et labium illius erat quasi labium calicis, vel repandi lilii: capiebatque tria millia metretas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Fecit quoque conchas decem: et posuit quinque a dextris, et quinque a sinistris, ut lavarent in eis omnia quæ in holocaustum oblaturi erant: porro in mari sacerdotes lavabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Fecit autem et candelabra aurea decem secundum speciem qua jussa erant fieri: et posuit ea in templo, quinque a dextris, et quinque a sinistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Necnon et mensas decem: et posuit eas in templo, quinque a dextris, et quinque a sinistris: phialas quoque aureas centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Fecit etiam atrium sacerdotum, et basilicam grandem: et ostia in basilica, quæ texit ære.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Porro mare posuit in latere dextro contra orientem ad meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Fecit autem Hiram lebetes, et creagras, et phialas: et complevit omne opus regis in domo Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'hoc est, columnas duas, et epistylia, et capita, et quasi quædam retiacula, quæ capita tegerent super epistylia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Malogranata quoque quadringenta, et retiacula duo ita ut bini ordines malogranatorum singulis retiaculis jungerentur, quæ protegerent epistylia, et capita columnarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Bases etiam fecit, et conchas, quas superposuit basibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'mare unum, boves quoque duodecim sub mari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'et lebetes, et creagras, et phialas. Omnia vasa fecit Salomoni Hiram pater ejus in domo Domini ex ære mundissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'In regione Jordanis, fudit ea rex in argillosa terra inter Sochot et Saredatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Erat autem multitudo vasorum innumerabilis, ita ut ignoraretur pondus æris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Fecitque Salomon omnia vasa domus Dei, et altare aureum, et mensas, et super eas panes propositionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'candelabra quoque cum lucernis suis ut lucerent ante oraculum juxta ritum ex auro purissimo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'et florentia quædam, et lucernas, et forcipes aureos: omnia de auro mundissimo facta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Thymiateria quoque, et thuribula, et phialas, et mortariola ex auro purissimo. Et ostia cælavit templi interioris, id est, in Sancta sanctorum: et ostia templi forinsecus aurea. Sicque completum est omne opus quod fecit Salomon in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Intulit igitur Salomon omnia quæ voverat David pater suus: argentum, et aurum, et universa vasa posuit in thesauris domus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Post quæ congregavit majores natu Israël, et cunctos principes tribuum, et capita familiarum de filiis Israël in Jerusalem, ut adducerent arcam fœderis Domini de civitate David, quæ est Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Venerunt itaque ad regem omnes viri Israël in die solemni mensis septimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Cumque venissent cuncti seniorum Israël, portaverunt Levitæ arcam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'et intulerunt eam, et omnem paraturam tabernaculi. Porro vasa sanctuarii, quæ erant in tabernaculo, portaverunt sacerdotes cum Levitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Rex autem Salomon, et universus cœtus Israël, et omnes qui fuerunt congregati ante arcam, immolabant arietes et boves absque ullo numero: tanta enim erat multitudo victimarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et intulerunt sacerdotes arcam fœderis Domini in locum suum, id est, ad oraculum templi, in Sancta sanctorum subter alas cherubim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'ita ut cherubim expanderent alas suas super locum in quo posita erat arca, et ipsam arcam tegerent cum vectibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Vectium autem quibus portabatur arca, quia paululum longiores erant, capita parebant ante oraculum: si vero quis paululum fuisset extrinsecus, eos videre non poterat. Fuit itaque arca ibi usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Nihilque erat aliud in arca, nisi duæ tabulæ quas posuerat Moyses in Horeb, quando legem dedit Dominus filiis Israël egredientibus ex \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Egressis autem sacerdotibus de sanctuario (omnes enim sacerdotes qui ibi potuerant inveniri, sanctificati sunt: nec adhuc in illo tempore vices et ministeriorum ordo inter eos divisus erat),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'tam Levitæ quam cantores, id est, et qui sub Asaph erant, et qui sub Eman, et qui sub Idithun, filii et fratres eorum vestiti byssinis, cymbalis, et psalteriis, et citharis concrepabant, stantes ad orientalem plagam altaris: et cum eis sacerdotes centum viginti canentes tubis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Igitur cunctis pariter, et tubis, et voce, et cymbalis, et organis, et diversi generis musicorum concinentibus, et vocem in sublime tollentibus, longe sonitus audiebatur, ita ut cum Dominum laudare cœpissent et dicere: Confitemini Domino quoniam bonus, quoniam in æternum misericordia ejus: impleretur domus Dei nube,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'nec possent sacerdotes stare et ministrare propter caliginem. Compleverat enim gloria Domini domum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tunc Salomon ait: Dominus pollicitus est ut habitaret in caligine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'ego autem ædificavi domum nomini ejus, ut habitaret ibi in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Et convertit rex faciem suam, et benedixit universæ multitudini Israël (nam omnis turba stabat intenta), et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Benedictus Dominus Deus Israël, qui quod locutus est David patri meo, opere complevit, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'A die qua eduxi populum meum de terra \'gypti, non elegi civitatem de cunctis tribubus Israël ut ædificaretur in ea domus nomini meo, neque elegi quemquam alium virum ut esset dux in populo Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'sed elegi Jerusalem ut sit nomen meum in ea, et elegi David ut constituerem eum super populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Cumque fuisset voluntatis David patris mei ut ædificaret domum nomini Domini Dei Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'dixit Dominus ad eum: Quia hæc fuit voluntas tua, ut ædificares domum nomini meo, bene quidem fecisti hujuscemodi habere voluntatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'sed non tu ædificabis domum: verum filius tuus, qui egredietur de lumbis tuis, ipse ædificabit domum nomini meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Complevit ergo Dominus sermonem suum quem locutus fuerat: et ego surrexi pro David patre meo, et sedi super thronum Israël, sicut locutus est Dominus: et ædificavi domum nomini Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Et posui in ea arcam in qua est pactum Domini quod pepigit cum filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Stetit ergo coram altari Domini ex adverso universæ multitudinis Israël, et extendit manus suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Siquidem fecerat Salomon basim æneam, et posuerat eam in medio basilicæ, habentem quinque cubitos longitudinis, et quinque cubitos latitudinis, et tres cubitos altitudinis: stetitque super eam, et deinceps flexis genibus contra universam multitudinem Israël, et palmis in cælum levatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'ait: Domine Deus Israël, non est similis tui deus in cælo et in terra: qui custodis pactum et misericordiam cum servis tuis qui ambulant coram te in toto corde suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'qui præstitisti servo tuo David patri meo quæcumque locutus fueras ei: et quæ ore promiseras, opere complesti, sicut et præsens tempus probat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nunc ergo Domine Deus Israël, imple servo tuo patri meo David quæcumque locutus es, dicens: Non deficiet ex te vir coram me, qui sedeat super thronum Israël: ita tamen si custodierint filii tui vias suas, et ambulaverint in lege mea, sicut et tu ambulasti coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Et nunc Domine Deus Israël, firmetur sermo tuus quem locutus es servo tuo David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Ergone credibile est ut habitet Deus cum hominibus super terram? si cælum et cæli cælorum non te capiunt, quanto magis domus ista quam ædificavi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Sed ad hoc tantum facta est, ut respicias orationem servi tui, et obsecrationem ejus, Domine Deus meus, et audias preces quas fundit famulus tuus coram te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'ut aperias oculos tuos super domum istam diebus ac noctibus, super locum in quo pollicitus es ut invocaretur nomen tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'et exaudires orationem quam servus tuus orat in eo: et exaudias preces famuli tui, et populi tui Israël. Quicumque oraverit in loco isto, exaudi de habitaculo tuo, id est, de cælis, et propitiare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Si peccaverit quispiam in proximum suum, et jurare contra eum paratus venerit, seque maledicto constrinxerit coram altari in domo ista:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'tu audies de cælo, et facies judicium servorum tuorum, ita ut reddas iniquo viam suam in caput proprium, et ulciscaris justum, retribuens ei secundum justitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Si superatus fuerit populus tuus Israël ab inimicis (peccabunt enim tibi), et conversi egerint pœnitentiam, et obsecraverint nomen tuum, et fuerint deprecati in loco isto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'tu exaudies de cælo: et propitiare peccato populi tui Israël, et reduc eos in terram quam dedisti eis, et patribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Si clauso cælo pluvia non fluxerit propter peccata populi, et deprecati te fuerint in loco isto, et confessi nomini tuo, et conversi a peccatis suis, cum eos afflixeris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'exaudi de cælo, Domine, et dimitte peccata servis tuis et populi tui Israël, et doce eos viam bonam, per quam ingrediantur: et da pluviam terræ quam dedisti populo tuo ad possidendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Fames si orta fuerit in terra, et pestilentia, ærugo, et aurugo, et locusta, et bruchus: et hostes, vastatis regionibus, portas obsederint civitatis, omnisque plaga et infirmitas presserit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'si quis de populo tuo Israël fuerit deprecatus, cognoscens plagam et infirmitatem suam, et expanderit manus suas in domo hac,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'tu exaudies de cælo, de sublimi scilicet habitaculo tuo: et propitiare, et redde unicuique secundum vias suas, quas nosti eum habere in corde suo (tu enim solus nosti corda filiorum hominum):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'ut timeant te, et ambulent in viis tuis cunctis diebus quibus vivunt super faciem terræ quam dedisti patribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Externum quoque, qui non est de populo tuo Israël, si venerit de terra longinqua propter nomen tuum magnum, et propter manum tuam robustam, et brachium tuum extentum, et adoraverit in loco isto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'tu exaudies de cælo firmissimo habitaculo tuo, et facies cuncta pro quibus invocaverit te ille peregrinus: ut sciant omnes populi terræ nomen tuum, et timeant te sicut populus tuus Israël, et cognoscant quia nomen tuum invocatum est super domum hanc quam ædificavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Si egressus fuerit populus tuus ad bellum contra adversarios suos per viam in qua miseris eos, adorabunt te contra viam in qua civitas hæc est, quam elegisti, et domus quam ædificavi nomini tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'tu exaudies de cælo preces eorum, et obsecrationem: et ulciscaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Si autem peccaverint tibi (neque enim est homo qui non peccet), et iratus fueris eis, et tradideris hostibus, et captivos duxerint eos in terram longinquam, vel certe quæ juxta est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'et conversi in corde suo in terra ad quam captivi ducti fuerant, egerint pœnitentiam, et deprecati te fuerint in terra captivitatis suæ, dicentes: Peccavimus: inique fecimus, injuste egimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'et reversi fuerint ad te in toto corde suo, et in tota anima sua, in terra captivitatis suæ ad quam ducti sunt, adorabunt te contra viam terræ suæ, quam dedisti patribus eorum, et urbis quam elegisti, et domus quam ædificavi nomini tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'tu exaudies de cælo, hoc est, de firmo habitaculo tuo, preces eorum: et facias judicium, et dimittas populo tuo, quamvis peccatori:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'tu es enim Deus meus: aperiantur, quæso, oculi tui, et aures tuæ intentæ sint ad orationem quæ fit in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Nunc igitur consurge, Domine Deus, in requiem tuam, tu et arca fortitudinis tuæ: sacerdotes tui, Domine Deus, induantur salutem, et sancti tui lætentur in bonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Domine Deus, ne averteris faciem christi tui: memento misericordiarum David servi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Cumque complesset Salomon fundens preces, ignis descendit de cælo, et devoravit holocausta et victimas: et majestas Domini implevit domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Nec poterant sacerdotes ingredi templum Domini, eo quod implesset majestas Domini templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Sed et omnes filii Israël videbant descendentem ignem, et gloriam Domini super domum: et corruentes proni in terram super pavimentum stratum lapide, adoraverunt, et laudaverunt Dominum, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Rex autem et omnis populus immolabant victimas coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Mactavit igitur rex Salomon hostias, boum viginti duo millia, arietum centum viginti millia: et dedicavit domum Dei rex, et universus populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Sacerdotes autem stabant in officiis suis, et Levitæ in organis carminum Domini, quæ fecit David rex ad laudandum Dominum: Quoniam in æternum misericordia ejus, hymnos David canentes per manus suas: porro sacerdotes canebant tubis ante eos, cunctusque Israël stabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Sanctificavit quoque Salomon medium atrii ante templum Domini: obtulerat enim ibi holocausta et adipes pacificorum: quia altare æneum quod fecerat, non poterat sustinere holocausta et sacrificia et adipes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Fecit ergo Salomon solemnitatem in tempore illo septem diebus, et omnis Israël cum eo, ecclesia magna valde, ab introitu Emath usque ad torrentem \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Fecitque die octavo collectam, eo quod dedicasset altare septem diebus, et solemnitatem celebrasset diebus septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Igitur in die vigesimo tertio mensis septimi, dimisit populos ad tabernacula sua, lætantes atque gaudentes super bono quod fecerat Dominus Davidi, et Salomoni, et Israëli populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Complevitque Salomon domum Domini, et domum regis, et omnia quæ disposuerat in corde suo ut faceret in domo Domini, et in domo sua, et prosperatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Apparuit autem ei Dominus nocte, et ait: Audivi orationem tuam, et elegi locum istum mihi in domum sacrificii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Si clausero cælum, et pluvia non fluxerit, et mandavero et præcepero locustæ ut devoret terram, et misero pestilentiam in populum meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'conversus autem populus meus, super quos invocatum est nomen meum, deprecatus me fuerit, et exquisierit faciem meam, et egerit pœnitentiam a viis suis pessimis: et ego exaudiam de cælo, et propitius ero peccatis eorum, et sanabo terram eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Oculi quoque mei erunt aperti, et aures meæ erectæ ad orationem ejus, qui in loco isto oraverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Elegi enim, et sanctificavi locum istum, ut sit nomen meum ibi in sempiternum, et permaneant oculi mei et cor meum ibi cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Tu quoque si ambulaveris coram me, sicut ambulaverit David pater tuus, et feceris juxta omnia quæ præcepi tibi, et justitias meas judiciaque servaveris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'suscitabo thronum regni tui, sicut pollicitus sum David patri tuo, dicens: Non auferetur de stirpe tua vir qui sit princeps in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Si autem aversi fueritis, et dereliqueritis justitias meas, et præcepta mea quæ proposui vobis, et abeuntes servieritis diis alienis, et adoraveritis eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'evellam vos de terra mea quam dedi vobis: et domum hanc, quam sanctificavi nomini meo, projiciam a facie mea, et tradam eam in parabolam, et in exemplum cunctis populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et domus ista erit in proverbium universis transeuntibus, et dicent stupentes: Quare fecit Dominus sic terræ huic, et domui huic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Respondebuntque: Quia dereliquerunt Dominum Deum patrum suorum, qui eduxit eos de terra \'gypti, et apprehenderunt deos alienos, et adoraverunt eos, et coluerunt: idcirco venerunt super eos universa hæc mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Expletis autem viginti annis postquam ædificavit Salomon domum Domini et domum suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'civitates quas dederat Hiram Salomoni, ædificavit, et habitare ibi fecit filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Abiit quoque in Emath Suba, et obtinuit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Et ædificavit Palmyram in deserto, et alias civitates munitissimas ædificavit in Emath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Exstruxitque Bethoron superiorem, et Bethoron inferiorem, civitates muratas habentes portas et vectes et seras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Balaath etiam et omnes urbes firmissimas quæ fuerunt Salomonis, cunctasque urbes quadrigarum, et urbes equitum. Omnia quæcumque voluit Salomon atque disposuit, ædificavit in Jerusalem, et in Libano, et in universa terra potestatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Omnem populum qui derelictus fuerat de Hethæis, et Amorrhæis, et Pherezæis, et Hevæis, et Jebusæis, qui non erant de stirpe Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'de filiis eorum, et de posteris, quos non interfecerant filii Israël, subjugavit Salomon in tributarios, usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Porro de filiis Israël non posuit ut servirent operibus regis: ipsi enim erant viri bellatores, et duces primi, et principes quadrigarum et equitum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Omnes autem principes exercitus regis Salomonis fuerunt ducenti quinquaginta, qui erudiebant populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Filiam vero Pharaonis transtulit de civitate David in domum quam ædificaverat ei. Dixit enim rex: Non habitabit uxor mea in domo David regis Israël, eo quod sanctificata sit: quia ingressa est in eam arca Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tunc obtulit Salomon holocausta Domino super altare Domini, quod exstruxerat ante porticum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'ut per singulos dies offerretur in eo juxta præceptum Moysi in sabbatis et in calendis, et in festis diebus, ter per annum, id est, in solemnitate azymorum, et in solemnitatem hebdomadarum, et in solemnitate tabernaculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Et constituit juxta dispositionem David patris sui officia sacerdotum in ministeriis suis, et Levitas in ordine suo, ut laudarent et ministrarent coram sacerdotibus juxta ritum uniuscujusque diei, et janitores in divisionibus suis per portam et portam: sic enim præceperat David homo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Nec prætergressi sunt de mandatis regis tam sacerdotes quam Levitæ, ex omnibus quæ præceperat, et in custodiis thesaurorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Omnes impensas præparatas habuit Salomon ex eo die quo fundavit domum Domini usque in diem quo perfecit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tunc abiit Salomon in Asiongaber, et in Ailath ad oram maris Rubri, quæ est in terra Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Misit autem ei Hiram per manus servorum suorum naves, et nautas gnaros maris, et abierunt cum servis Salomonis in Ophir, tuleruntque inde quadringenta quinquaginta talenta auri, et attulerunt ad regem Salomonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Regina quoque Saba, cum audisset famam Salomonis, venit ut tentaret eum in ænigmatibus in Jerusalem, cum magnis opibus et camelis, qui portabant aromata, et auri plurimum, gemmasque pretiosas. Cumque venisset ad Salomonem, locuta est ei quæcumque erant in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et exposuit ei Salomon omnia quæ proposuerat: nec quidquam fuit, quod non perspicuum ei fecerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Quæ postquam vidit, sapientiam scilicet Salomonis, et domum quam ædificaverat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'necnon et cibaria mensæ ejus, et habitacula servorum, et officia ministrorum ejus, et vestimenta eorum, pincernas quoque et vestes eorum, et victimas quas immolabat in domo Domini: non erat præ stupore ultra in ea spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Dixitque ad regem: Verus est sermo quem audieram in terra mea de virtutibus et sapientia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Non credebam narrantibus donec ipsa venissem, et vidissent oculi mei, et probassem vix medietatem sapientiæ tuæ mihi fuisse narratam: vicisti famam virtutibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Beati viri tui, et beati servi tui, qui assistunt coram te omni tempore, et audiunt sapientiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Sit Dominus Deus tuus benedictus, qui voluit te ordinare super thronum suum, regem Domini Dei tui. Quia diligit Deus Israël, et vult servare eum in æternum, idcirco posuit te super eum regem ut facias judicia atque justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Dedit autem regi centum viginti talenta auri, et aromata multa nimis, et gemmas pretiosissimas: non fuerunt aromata talia, ut hæc quæ dedit regina Saba regi Salomoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Sed et servi Hiram cum servis Salomonis attulerunt aurum de Ophir, et ligna thyina, et gemmas pretiosissimas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'de quibus fecit rex, de lignis scilicet thyinis, gradus in domo Domini, et in domo regia, citharas quoque, et psalteria cantoribus: numquam visa sunt in terra Juda ligna talia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Rex autem Salomon dedit reginæ Saba cuncta quæ voluit, et quæ postulavit, et multo plura quam attulerat ad eum: quæ reversa abiit in terram suam cum servis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Erat autem pondus auri quod afferebatur Salomoni per singulos annos, sexcenta sexaginta sex talenta auri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'excepta ea summa quam legati diversarum gentium et negotiatores afferre consueverant, omnesque reges Arabiæ, et satrapæ terrarum, qui comportabant aurum et argentum Salomoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Fecit igitur rex Salomon ducentas hastas aureas de summa sexcentorum aureorum, qui in singulis hastis expendebantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'trecenta quoque scuta aurea trecentorum aureorum, quibus tegebantur singula scuta: posuitque ea rex in armentario, quod erat consitum nemore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Fecit quoque rex solium eburneum grande, et vestivit illud auro mundissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Sex quoque gradus, quibus ascendebatur ad solium, et scabellum aureum, et brachiola duo altrinsecus, et duos leones stantes juxta brachiola,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'sed et alios duodecim leunculos stantes super sex gradus ex utraque parte: non fuit tale solium in universis regnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Omnia quoque vasa convivii regis erant aurea, et vasa domus saltus Libani ex auro purissimo. Argentum enim in diebus illis pro nihilo reputabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Siquidem naves regis ibant in Tharsis cum servis Hiram, semel in annis tribus: et deferebant inde aurum, et argentum, et ebur, et simias, et pavos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Magnificatus est igitur Salomon super omnes reges terræ præ divitiis et gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Omnesque reges terrarum desiderabant videre faciem Salomonis, ut audirent sapientiam quam dederat Deus in corde ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'et deferebant ei munera, vasa argentea et aurea, et vestes, et arma, et aromata, equos, et mulos, per singulos annos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Habuit quoque Salomon quadraginta millia equorum in stabulis, et curruum equitumque duodecim millia: constituitque eos in urbibus quadrigarum, et ubi erat rex in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Exercuit etiam potestatem super cunctos reges a flumine Euphrate usque ad terram Philisthinorum, et usque ad terminos \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Tantamque copiam præbuit argenti in Jerusalem quasi lapidum: et cedrorum tantam multitudinem velut sycomororum quæ gignuntur in campestribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Adducebantur autem ei equi de \'gypto, cunctisque regionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Reliqua autem operum Salomonis priorum et novissimorum scripta sunt in verbis Nathan prophetæ, et in libris Ahiæ Silonitis, in visione quoque Addo videntis contra Jeroboam filium Nabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Regnavit autem Salomon in Jerusalem super omnem Israël quadraginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Dormivitque cum patribus suis, et sepelierunt eum in civitate David: regnavitque Roboam filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Profectus est autem Roboam in Sichem: illuc enim cunctus Israël convenerat ut constituerent eum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Quod cum audisset Jeroboam filius Nabat, qui erat in \'gypto (fugerat quippe illuc ante Salomonem), statim reversus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Vocaveruntque eum, et venit cum universo Israël: et locuti sunt ad Roboam, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Pater tuus durissimo jugo nos pressit: tu leviora impera patre tuo, qui nobis imposuit gravem servitutem, et paululum de onere subleva, ut serviamus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Qui ait: Post tres dies revertimini ad me. Cumque abiisset populus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'iniit consilium cum senibus qui steterant coram patre ejus Salomone dum adhuc viveret, dicens: Quid datis consilii ut respondeam populo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Qui dixerunt ei: Si placueris populo huic, et leniveris eos verbis clementibus, servient tibi omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'At ille reliquit consilium senum, et cum juvenibus tractare cœpit, qui cum eo nutriti fuerant, et erant in comitatu illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Dixitque ad eos: Quid vobis videtur? vel respondere quid debeo populo huic, qui dixit mihi: Subleva jugum quod imposuit nobis pater tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'At illi responderunt ut juvenes, et nutriti cum eo in deliciis, atque dixerunt: Sic loqueris populo qui dixit tibi: Pater tuus aggravavit jugum nostrum, tu subleva: et sic respondebis ei: Minimus digitus meus grossior est lumbis patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Pater meus imposuit vobis grave jugum, et ego majus pondus apponam; pater meus cecidit vos flagellis, ego vero cædam vos scorpionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Venit ergo Jeroboam et universus populus ad Roboam die tertio, sicut præceperat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Responditque rex dura, derelicto consilio seniorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'locutusque est juxta juvenum voluntatem: Pater meus grave vobis imposuit jugum, quod ego gravius faciam; pater meus cecidit vos flagellis, ego vero cædam vos scorpionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Et non acquievit populi precibus: erat enim voluntatis Dei ut compleretur sermo ejus quem locutus fuerat per manum Ahiæ Silonitis ad Jeroboam filium Nabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Populus autem universus rege duriora dicente, sic locutus est ad eum: Non est nobis pars in David, neque hæreditas in filio Isai. Revertere in tabernacula tua, Israël; tu autem pasce domum tuam David. Et abiit Israël in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Super filios autem Israël qui habitabant in civitatibus Juda, regnavit Roboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Misitque rex Roboam Aduram, qui præerat tributis, et lapidaverunt eum filii Israël, et mortuus est: porro rex Roboam currum festinavit ascendere, et fugit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Recessitque Israël a domo David, usque ad diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Venit autem Roboam in Jerusalem, et convocavit universam domum Juda et Benjamin, centum octoginta millia electorum atque bellantium, ut dimicaret contra Israël, et converteret ad se regnum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Factusque est sermo Domini ad Semeiam hominem Dei, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Loquere ad Roboam filium Salomonis regem Juda, et ad universum Israël, qui est in Juda et Benjamin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Hæc dicit Dominus: Non ascendetis, neque pugnabitis contra fratres vestros: revertatur unusquisque in domum suam, quia mea hoc gestum est voluntate. Qui cum audissent sermonem Domini, reversi sunt, nec perrexerunt contra Jeroboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Habitavit autem Roboam in Jerusalem, et ædificavit civitates muratas in Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Exstruxitque Bethlehem, et Etam, et Thecue,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bethsur quoque, et Socho, et Odollam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'necnon et Geth, et Maresa, et Ziph,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'sed et Aduram, et Lachis, et Azeca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Saraa quoque, et Ajalon, et Hebron, quæ erant in Juda et Benjamin, civitates munitissimas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Cumque clausisset eas muris, posuit in eis principes, ciborumque horrea, hoc est, olei, et vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Sed et in singulis urbibus fecit armamentarium scutorum et hastarum, firmavitque eas summa diligentia, et imperavit super Judam et Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Sacerdotes autem et Levitæ qui erant in universo Israël, venerunt ad eum de cunctis sedibus suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'relinquentes suburbana et possessiones suas, et transeuntes ad Judam et Jerusalem: eo quod abjecisset eos Jeroboam et posteri ejus, ne sacerdotio Domini fungerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Qui constituit sibi sacerdotes excelsorum, et dæmoniorum, vitulorumque quos fecerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Sed et de cunctis tribubus Israël, quicumque dederant cor suum ut quærerent Dominum Deum Israël, venerunt in Jerusalem ad immolandum victimas suas coram Domino Deo patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et roboraverunt regnum Juda, et confirmaverunt Roboam filium Salomonis per tres annos: ambulaverunt enim in viis David et Salomonis, annis tantum tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Duxit autem Roboam uxorem Mahalath filiam Jerimoth filii David: Abihail quoque filiam Eliab filii Isai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'quæ peperit ei filios Jehus, et Somoriam, et Zoom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Post hanc quoque accepit Maacha filiam Absalom, quæ peperit ei Abia, et Ethai, et Ziza, et Salomith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Amavit autem Roboam Maacha filiam Absalom super omnes uxores suas et concubinas: nam uxores decem et octo duxerat, concubinas autem sexaginta: et genuit viginti octo filios, et sexaginta filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Constituit vero in capite Abiam filium Maacha ducem super omnes fratres suos: ipsum enim regem facere cogitabat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'quia sapientior fuit, et potentior super omnes filios ejus, et in cunctis finibus Juda et Benjamin, et in universis civitatibus muratis: præbuitque eis escas plurimas, et multas petivit uxores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Cumque roboratum fuisset regnum Roboam et confortatum, dereliquit legem Domini, et omnis Israël cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Anno autem quinto regni Roboam, ascendit Sesac rex \'gypti in Jerusalem (quia peccaverant Domino)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'cum mille ducentis curribus, et sexaginta millibus equitum: nec erat numerus vulgi quod venerat cum eo ex \'gypto, Libyes scilicet, et Troglodytæ, et \'thiopes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Cepitque civitates munitissimas in Juda, et venit usque in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Semeias autem propheta ingressus est ad Roboam, et principes Juda qui congregati fuerant in Jerusalem, fugientes Sesac: dixitque ad eos: Hæc dicit Dominus: Vos reliquistis me, et ego reliqui vos in manu Sesac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Consternatique principes Israël et rex, dixerunt: Justus est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Cumque vidisset Dominus quod humiliati essent, factus est sermo Domini ad Semeiam, dicens: Quia humiliati sunt, non disperdam eos, daboque eis pauxillum auxilii, et non stillabit furor meus super Jerusalem per manum Sesac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Verumtamen servient ei, ut sciant distantiam servitutis meæ, et servitutis regni terrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Recessit itaque Sesac rex \'gypti ab Jerusalem, sublatis thesauris domus Domini et domus regis: omniaque secum tulit, et clypeos aureos quos fecerat Salomon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'pro quibus fecit rex æneos, et tradidit illos principibus scutariorum, qui custodiebant vestibulum palatii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Cumque introiret rex domum Domini, veniebant scutarii et tollebant eos, iterumque referebant eos ad armamentarium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Verumtamen quia humiliati sunt, aversa est ab eis ira Domini, nec deleti sunt penitus: siquidem et in Juda inventa sunt opera bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Confortatus est ergo rex Roboam in Jerusalem, atque regnavit: quadraginta autem et unius anni erat cum regnare cœpisset, et decem et septem annis regnavit in Jerusalem, urbe quam elegit Dominus ut confirmaret nomen suum ibi, de cunctis tribubus Israël: nomen autem matris ejus Naama Ammanitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Fecit autem malum, et non præparavit cor suum ut quæreret Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Opera vero Roboam prima et novissima scripta sunt in libris Semeiæ prophetæ, et Addo videntis, et diligenter exposita: pugnaveruntque adversum se Roboam et Jeroboam cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et dormivit Roboam cum patribus suis, sepultusque est in civitate David: et regnavit Abia filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Anno octavodecimo regis Jeroboam, regnavit Abia super Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tribus annis regnavit in Jerusalem, nomenque matris ejus Michaia filia Uriel de Gabaa: et erat bellum inter Abiam et Jeroboam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Cumque iniisset Abia certamen, et haberet bellicosissimos viros, et electorum quadringenta millia: Jeroboam instruxit econtra aciem octingenta millia virorum, qui et ipsi electi erant, et ad bella fortissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Stetit ergo Abia super montem Semeron, qui erat in Ephraim, et ait: Audi, Jeroboam, et omnis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Num ignoratis quod Dominus Deus Israël dederit regnum David super Israël in sempiternum, ipsi et filiis ejus in pactum salis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Et surrexit Jeroboam filius Nabat, servus Salomonis filii David, et rebellavit contra dominum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Congregatique sunt ad eum viri vanissimi, et filii Belial, et prævaluerunt contra Roboam filium Salomonis: porro Roboam erat rudis, et corde pavido, nec potuit resistere eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Nunc ergo vos dicitis quod resistere possitis regno Domini, quod possidet per filios David, habetisque grandem populi multitudinem, atque vitulos aureos quos fecit vobis Jeroboam in deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Et ejecistis sacerdotes Domini, filios Aaron, atque Levitas, et fecistis vobis sacerdotes sicut omnes populi terrarum: quicumque venerit, et initiaverit manum suam in tauro de bobus, et in arietibus septem, fit sacerdos eorum qui non sunt dii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Noster autem Dominus, Deus est, quem non relinquimus, sacerdotesque ministrant Domino, de filiis Aaron, et Levitæ sunt in ordine suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'holocausta quoque offerunt Domino per singulos dies mane et vespere, et thymiama juxta legis præcepta confectum, et proponuntur panes in mensa mundissima, estque apud nos candelabrum aureum, et lucernæ ejus, ut accendantur semper ad vesperam: nos quippe custodimus præcepta Domini Dei nostri, quem vos reliquistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Ergo in exercitu nostro dux Deus est, et sacerdotes ejus, qui clangunt tubis, et resonant contra vos: filii Israël, nolite pugnare contra Dominum Deum patrum vestrorum, quia non vobis expedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Hæc illo loquente, Jeroboam retro moliebatur insidias. Cumque ex adverso hostium staret, ignorantem Judam suo ambiebat exercitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Respiciensque Judas, vidit instare bellum ex adverso et post tergum, et clamavit ad Dominum, ac sacerdotes tubis canere cœperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Omnesque viri Juda vociferati sunt: et ecce illis clamantibus, perterruit Deus Jeroboam, et omnem Israël qui stabat ex adverso Abia et Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Fugeruntque filii Israël Judam, et tradidit eos Deus in manu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Percussit ergo eos Abia et populus ejus plaga magna: et corruerunt vulnerati ex Israël quingenta millia virorum fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Humiliatique sunt filii Israël in tempore illo, et vehementissime confortati filii Juda, eo quod sperassent in Domino Deo patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Persecutus est autem Abia fugientem Jeroboam, et cepit civitates ejus, Bethel et filias ejus, et Jesana cum filiabus suis, Ephron quoque et filias ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'nec valuit ultra resistere Jeroboam in diebus Abia: quem percussit Dominus, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Igitur Abia, confortato imperio suo, accepit uxores quatuordecim: procreavitque viginti duos filios, et sedecim filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Reliqua autem sermonum Abia, viarumque et operum ejus, scripta sunt diligentissime in libro Addo prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Dormivit autem Abia cum patribus suis, et sepelierunt eum in civitate David: regnavitque Asa filius ejus pro eo, in cujus diebus quievit terra annis decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Fecit autem Asa quod bonum et placitum erat in conspectu Dei sui, et subvertit altaria peregrini cultus, et excelsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Et confregit statuas, lucosque succidit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'et præcepit Judæ ut quæreret Dominum Deum patrum suorum, et faceret legem, et universa mandata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'et abstulit de cunctis urbibus Juda aras et fana, et regnavit in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, '\'dificavit quoque urbes munitas in Juda, quia quietus erat, et nulla temporibus ejus bella surrexerant, pacem Domino largiente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Dixit autem Judæ: \'dificemus civitates istas, et vallemus muris, et roboremus turribus, et portis, et seris, donec a bellis quieta sunt omnia, eo quod quæsierimus Dominum Deum patrum nostrorum, et dederit nobis pacem per gyrum. \'dificaverunt igitur, et nullum in exstruendo impedimentum fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Habuit autem Asa in exercitu suo portantium scuta et hastas de Juda trecenta millia, de Benjamin vero scutariorum et sagittariorum ducenta octoginta millia: omnes isti viri fortissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Egressus est autem contra eos Zara \'thiops cum exercitu suo, decies centena millia, et curribus trecentis: et venit usque Maresa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Porro Asa perrexit obviam ei, et instruxit aciem ad bellum in valle Sephata, quæ est juxta Maresa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'et invocavit Dominum Deum, et ait: Domine, non est apud te ulla distantia, utrum in paucis auxilieris, an in pluribus. Adjuva nos, Domine Deus noster: in te enim, et in tuo nomine habentes fiduciam, venimus contra hanc multitudinem. Domine, Deus noster tu es: non prævaleat contra te homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Exterruit itaque Dominus \'thiopes coram Asa et Juda: fugeruntque \'thiopes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Et persecutus est eos Asa, et populus qui cum eo erat, usque Gerara: et ruerunt \'thiopes usque ad internecionem, quia Domino cædente contriti sunt, et exercitu illius præliante. Tulerunt ergo spolia multa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'et percusserunt civitates omnes per circuitum Geraræ: grandis quippe cunctos terror invaserat: et diripuerunt urbes, et multam prædam asportaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Sed et caulas ovium destruentes, tulerunt pecorum infinitam multitudinem, et camelorum: reversique sunt in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Azarias autem filius Oded, facto in se spiritu Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'egressus est in occursum Asa, et dixit ei: Audite me, Asa, et omnis Juda et Benjamin: Dominus vobiscum, quia fuistis cum eo. Si quæsieritis eum, invenietis: si autem dereliqueritis eum, derelinquet vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Transibant autem multi dies in Israël absque Deo vero, et absque sacerdote doctore, et absque lege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Cumque reversi fuerint in angustia sua ad Dominum Deum Israël, et quæsierint eum, reperient eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'In tempore illo, non erit pax egredienti et ingredienti, sed terrores undique in cunctis habitatoribus terrarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'pugnavit enim gens contra gentem, et civitas contra civitatem, quia Dominus conturbabit eos in omni angustia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Vos ergo confortamini, et non dissolvantur manus vestræ: erit enim merces operi vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Quod cum audisset Asa, verba scilicet, et prophetiam Azariæ filii Oded prophetæ, confortatus est, et abstulit idola de omni terra Juda et de Benjamin, et ex urbibus quas ceperat, montis Ephraim: et dedicavit altare Domini quod erat ante porticum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Congregavitque universum Judam et Benjamin, et advenas cum eis de Ephraim, et de Manasse, et de Simeon: plures enim ad eum confugerant ex Israël, videntes quod Dominus Deus illius esset cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Cumque venissent in Jerusalem mense tertio, anno decimoquinto regni Asa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'immolaverunt Domino in die illa de manubiis et præda quam adduxerant, boves septingentos, et arietes septem millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Et intravit ex more ad corroborandum fœdus ut quærerent Dominum Deum patrum suorum in toto corde, et in tota anima sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Si quis autem, inquit, non quæsierit Dominum Deum Israël, moriatur, a minimo usque ad maximum, a viro usque ad mulierem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Juraveruntque Domino voce magna in jubilo, et in clangore tubæ, et in sonitu buccinarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'omnes qui erant in Juda, cum execratione: in omni enim corde suo juraverunt, et in tota voluntate quæsierunt eum, et invenerunt: præstititque eis Dominus requiem per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Sed et Maacham matrem Asa regis ex augusto deposuit imperio, eo quod fecisset in luco simulacrum Priapi: quod omne contrivit, et in frustra comminuens combussit in torrente Cedron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Excelsa autem derelicta sunt in Israël: attamen cor Asa erat perfectum cunctis diebus ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'eaque quæ voverat pater suus, et ipse, intulit in domum Domini, argentum, et aurum, vasorumque diversam supellectilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Bellum vero non fuit usque ad trigesimum quintum annum regni Asa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Anno autem trigesimo sexto regni ejus, ascendit Baasa rex Israël in Judam, et muro circumdabat Rama, ut nullus tute posset egredi et ingredi de regno Asa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Protulit ergo Asa argentum et aurum de thesauris domus Domini, et de thesauris regis, misitque ad Benadad regem Syriæ, qui habitabat in Damasco, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Fœdus inter me et te est; pater quoque meus et pater tuus habuere concordiam: quam ob rem misi tibi argentum et aurum, ut rupto fœdere quod habes cum Baasa rege Israël, facias eum a me recedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Quo comperto, Benadad misit principes exercituum suorum ad urbes Israël: qui percusserunt Ahion, et Dan, et Abelmaim, et universas urbes Nephthali muratas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Quod cum audisset Baasa, desiit ædificare Rama, et intermisit opus suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Porro Asa rex assumpsit universum Judam, et tulerunt lapides de Rama, et ligna quæ ædificationi præparaverat Baasa, ædificavitque ex eis Gabaa et Maspha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'In tempore illo venit Hanani propheta ad Asa regem Juda, et dixit ei: Quia habuisti fiduciam in rege Syriæ, et non in Domino Deo tuo, idcirco evasit Syriæ regis exercitus de manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Nonne \'thiopes et Libyes multo plures erant quadrigis, et equitibus, et multitudine nimia, quos cum Domino credidisses, tradidit in manu tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Oculi enim Domini contemplantur universam terram, et præbent fortitudinem his qui corde perfecto credunt in eum. Stulte igitur egisti, et propter hoc ex præsenti tempore adversum te bella consurgent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Iratusque Asa adversus videntem, jussit eum mitti in nervum: valde quippe super hoc fuerat indignatus: et interfecit de populo in tempore illo plurimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Opera autem Asa prima et novissima scripta sunt in libro regum Juda et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, '\'grotavit etiam Asa anno trigesimo nono regni sui, dolore pedum vehementissimo, et nec in infirmitate sua quæsivit Dominum, sed magis in medicorum arte confisus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Dormivitque cum patribus suis, et mortuus est anno quadragesimo primo regni sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et sepelierunt eum in sepulchro suo quod foderat sibi in civitate David: posueruntque eum super lectum suum plenum aromatibus et unguentibus meretriciis, quæ erant pigmentariorum arte confecta, et combusserunt super eum ambitione nimia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Regnavit autem Josaphat filius ejus pro eo, et invaluit contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Constituitque militum numeros in cunctis urbibus Juda quæ erant vallatæ muris. Præsidiaque disposuit in terra Juda, et in civitatibus Ephraim quas ceperat Asa pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et fuit Dominus cum Josaphat, quia ambulavit in viis David patris sui primis: et non speravit in Baalim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sed in Deo patris sui: et perrexit in præceptis illius, et non juxta peccata Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Confirmavitque Dominus regnum in manu ejus, et dedit omnis Juda munera Josaphat: factæque sunt ei infinitæ divitiæ, et multa gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Cumque sumpsisset cor ejus audaciam propter vias Domini, etiam excelsa et lucos de Juda abstulit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Tertio autem anno regni sui misit de principibus suis Benhail, et Obdiam, et Zachariam, et Nathanaël, et Michæam, ut docerent in civitatibus Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'et cum eis Levitas Semeiam, et Nathaniam, et Zabadiam, Asaël quoque, et Semiramoth, et Jonathan, Adoniamque et Thobiam, et Thobadoniam Levitas, et cum eis Elisama, et Joran sacerdotes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'docebantque populum in Juda, habentes librum legis Domini, et circuibant cunctas urbes Juda, atque erudiebant populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Itaque factus est pavor Domini super omnia regna terrarum quæ erant per gyrum Juda, nec audebant bellare contra Josaphat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Sed et Philisthæi Josaphat munera deferebant, et vectigal argenti: Arabes quoque adducebant pecora, arietum septem millia septingenta, et hircorum totidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Crevit ergo Josaphat, et magnificatus est usque in sublime: atque ædificavit in Juda domos ad instar turrium, urbesque muratas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Et multa opera paravit in urbibus Juda: viri quoque bellatores et robusti erant in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'quorum iste numerus per domos atque familias singulorum: in Juda principes exercitus, Ednas dux, et cum eo robustissimi viri trecenta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Post hunc Johanan princeps, et cum eo ducenta octoginta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Post istum quoque Amasias filius Zechri, consecratus Domino, et cum eo ducenta millia virorum fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Hunc sequebatur robustus ad prælia Eliada, et cum eo tenentium arcum et clypeum ducenta millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Post istum etiam Jozabad, et cum eo centum octoginta millia expeditorum militum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Hi omnes erant ad manum regis, exceptis aliis quos posuerat in urbibus muratis in universo Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Fuit ergo Josaphat dives et inclytus multum, et affinitate conjunctus est Achab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Descenditque post annos ad eum in Samariam: ad cujus adventum mactavit Achab arietes et boves plurimos, ipsi, et populo qui venerat cum eo: persuasitque illi ut ascenderet in Ramoth Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Dixitque Achab rex Israël ad Josaphat regem Juda: Veni mecum in Ramoth Galaad. Cui ille respondit: Ut ego, et tu: sicut populus tuus, sic et populus meus: tecumque erimus in bello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Dixitque Josaphat ad regem Israël: Consule, obsecro, impræsentiarum sermonem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Congregavit igitur rex Israël prophetarum quadringentos viros, et dixit ad eos: In Ramoth Galaad ad bellandum ire debemus, an quiescere? At illi: Ascende, inquiunt, et tradet Deus in manu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Dixitque Josaphat: Numquid non est hic prophetes Domini, ut ab illo etiam requiramus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et ait rex Israël ad Josaphat: Est vir unus a quo possumus quærere Domini voluntatem: sed ego odi eum, quia non prophetat mihi bonum, sed malum omni tempore: est autem Michæas filius Jemla. Dixitque Josaphat: Ne loquaris, rex, hoc modo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Vocavit ergo rex Israël unum de eunuchis, et dixit ei: Voca cito Michæam filium Jemla.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Porro rex Israël, et Josaphat rex Juda, uterque sedebant in solio suo, vestiti cultu regio: sedebant autem in area juxta portam Samariæ, omnesque prophetæ vaticinabantur coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Sedecias vero filius Chanaana fecit sibi cornua ferrea, et ait: Hæc dicit Dominus: His ventilabis Syriam, donec conteras eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Omnesque prophetæ similiter prophetabant, atque dicebant: Ascende in Ramoth Galaad, et prosperaberis, et tradet eos Dominus in manu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Nuntius autem qui ierat ad vocandum Michæam, ait illi: En verba omnium prophetarum uno ore bona regi annuntiant: quæso ergo te ut et sermo tuus ab eis non dissentiat, loquarisque prospera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Cui respondit Michæas: Vivit Dominus, quia quodcumque dixerit mihi Deus meus, hoc loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Venit ergo ad regem. Cui rex ait: Michæa, ire debemus in Ramoth Galaad ad bellandum, an quiescere? Cui ille respondit: Ascendite: cuncta enim prospera evenient, et tradentur hostes in manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Dixitque rex: Iterum atque iterum te adjuro, ut mihi non loquaris, nisi quod verum est in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'At ille ait: Vidi universum Israël dispersum in montibus, sicut oves absque pastore: et dixit Dominus: Non habent isti dominos: revertatur unusquisque in domum suam in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Et ait rex Israël ad Josaphat: Nonne dixi tibi quod non prophetaret iste mihi quidquam boni, sed ea quæ mala sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'At ille: Idcirco, ait, audite verbum Domini: vidi Dominum sedentem in solio suo, et omnem exercitum cæli assistentem ei a dextris et a sinistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Et dixit Dominus: Quis decipiet Achab regem Israël ut ascendat et corruat in Ramoth Galaad? Cumque diceret unus hoc modo, et alter alio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'processit spiritus, et stetit coram Domino, et ait: Ego decipiam eum. Cui Dominus: In quo, inquit, decipies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'At ille respondit: Egrediar, et ero spiritus mendax in ore omnium prophetarum ejus. Dixitque Dominus: Decipies, et prævalebis: egredere, et fac ita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nunc igitur, ecce Dominus dedit spiritum mendacii in ore omnium prophetarum tuorum, et Dominus locutus est de te mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Accessit autem Sedecias filius Chanaana, et percussit Michææ maxillam, et ait: Per quam viam transivit spiritus Domini a me, ut loqueretur tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Dixitque Michæas: Tu ipse videbis in die illo, quando ingressus fueris cubiculum de cubiculo ut abscondaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Præcepit autem rex Israël, dicens: Tollite Michæam, et ducite eum ad Amon principem civitatis, et ad Joas filium Amelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Et dicetis: Hæc dicit rex: Mittite hunc in carcerem, et date ei panis modicum, et aquæ pauxillum, donec revertar in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Dixitque Michæas: Si reversus fueris in pace, non est locutus Dominus in me. Et ait: Audite, omnes populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Igitur ascenderunt rex Israël et Josaphat rex Juda in Ramoth Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Dixitque rex Israël ad Josaphat: Mutabo habitum, et sic ad pugnam vadam: tu autem induere vestibus tuis. Mutatoque rex Israël habitu, venit ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Rex autem Syriæ præceperat ducibus equitatus sui, dicens: Ne pugnetis contra minimum aut contra maximum, nisi contra solum regem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Itaque cum vidissent principes equitatus Josaphat, dixerunt: Rex Israël est iste. Et circumdederunt eum dimicantes: at ille clamavit ad Dominum, et auxiliatus est ei, atque avertit eos ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Cum enim vidissent duces equitatus quod non esset rex Israël, reliquerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Accidit autem ut unus e populo sagittam in incertum jaceret, et percuteret regem Israël inter cervicem et scapulas. At ille aurigæ suo ait: Converte manum tuam, et educ me de acie, quia vulneratus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Et finita est pugna in die illo: porro rex Israël stabat in curru suo contra Syros usque ad vesperam, et mortuus est occidente sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Reversus est autem Josaphat rex Juda in domum suam pacifice in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Cui occurrit Jehu filius Henani videns, et ait ad eum: Impio præbes auxilium, et his qui oderunt Dominum amicitia jungeris, et idcirco iram quidem Domini merebaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'sed bona opera inventa sunt in te, eo quod abstuleris lucos de terra Juda, et præparaveris cor tuum ut requireres Dominum Deum patrum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Habitavit ergo Josaphat in Jerusalem, rursumque egressus est ad populum de Bersabee usque ad montem Ephraim, et revocavit eos ad Dominum Deum patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Constituitque judices terræ in cunctis civitatibus Juda munitis per singula loca,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'et præcipiens judicibus: Videte, ait, quid faciatis: non enim hominis exercetis judicium, sed Domini: et quodcumque judicaveritis, in vos redundabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Sit timor Domini vobiscum, et cum diligentia cuncta facite: non est enim apud Dominum Deum nostrum iniquitas, nec personarum acceptio, nec cupido munerum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'In Jerusalem quoque constituit Josaphat Levitas, et sacerdotes, et principes familiarum ex Israël, ut judicium et causam Domini judicarent habitatoribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Præcepitque eis, dicens: Sic agetis in timore Domini fideliter et corde perfecto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Omnem causam quæ venerit ad vos fratrum vestrorum, qui habitant in urbibus suis inter cognationem et cognationem, ubicumque quæstio est de lege, de mandato, de cæremoniis, de justificationibus: ostendite eis, ut non peccent in Dominum, et ne veniat ira super vos et super fratres vestros: sic ergo agentes non peccabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Amarias autem sacerdos et pontifex vester in his quæ ad Deum pertinent, præsidebit: porro Zabadias filius Ismahel, qui est dux in domo Juda, super ea opera erit quæ ad regis officium pertinent: habetisque magistros Levitas coram vobis. Confortamini, et agite diligenter, et erit Dominus vobiscum in bonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Post hæc congregati sunt filii Moab et filii Ammon, et cum eis de Ammonitis, ad Josaphat, ut pugnarent contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Veneruntque nuntii, et indicaverunt Josaphat, dicentes: Venit contra te multitudo magna de his locis quæ trans mare sunt, et de Syria: et ecce consistunt in Asasonthamar, quæ est Engaddi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Josaphat autem timore perterritus, totum se contulit ad rogandum Dominum, et prædicavit jejunium universo Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Congregatusque est Judas ad deprecandum Dominum: sed et omnes de urbibus suis venerunt ad obsecrandum eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Cumque stetisset Josaphat in medio cœtu Juda et Jerusalem, in domo Domini ante atrium novum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'ait: Domine Deus patrum nostrorum, tu es Deus in cælo, et dominaris cunctis regnis gentium: in manu tua est fortitudo et potentia, nec quisquam tibi potest resistere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Nonne tu, Deus noster, interfecisti omnes habitatores terræ hujus coram populo tuo Israël, et dedisti eam semini Abraham amici tui in sempiternum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Habitaveruntque in ea, et exstruxerunt in illa sanctuarium nomini tuo, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Si irruerint super nos mala, gladius judicii, pestilentia, et fames, stabimus coram domo hac in conspectu tuo, in qua invocatum est nomen tuum: et clamabimus ad te in tribulationibus nostris, et exaudies, salvosque facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Nunc igitur, ecce filii Ammon, et Moab, et mons Seir, per quos non concessisti Israël ut transirent quando egrediebantur de \'gypto, sed declinaverunt ab eis, et non interfecerunt illos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'e contrario agunt, et nituntur ejicere nos de possessione quam tradidisti nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Deus noster, ergo non judicabis eos? in nobis quidem non est tanta fortitudo, ut possimus huic multitudini resistere, quæ irruit super nos. Sed cum ignoremus quid agere debeamus, hoc solum habemus residui, ut oculos nostros dirigamus ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Omnis vero Juda stabat coram Domino cum parvulis, et uxoribus, et liberis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Erat autem Jahaziel filius Zachariæ filii Banaiæ filii Jehiel filii Mathaniæ, Levites de filiis Asaph, super quem factus est spiritus Domini, in medio turbæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'et ait: Attendite, omnis Juda, et qui habitatis Jerusalem, et tu, rex Josaphat: hæc dicit Dominus vobis: Nolite timere, nec paveatis hanc multitudinem: non est enim vestra pugna, sed Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Cras descendetis contra eos: ascensuri enim sunt per clivum nomine Sis, et invenietis illos in summitate torrentis qui est contra solitudinem Jeruel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Non eritis vos qui dimicabitis, sed tantummodo confidenter state, et videbitis auxilium Domini super vos, o Juda et Jerusalem: nolite timere, nec paveatis: cras egrediemini contra eos, et Dominus erit vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Josaphat ergo, et Juda, et omnes habitatores Jerusalem ceciderunt proni in terram coram Domino, et adoraverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Porro Levitæ de filiis Caath et de filiis Core laudabant Dominum Deum Israël voce magna in excelsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Cumque mane surrexissent, egressi sunt per desertum Thecue: profectisque eis, stans Josaphat in medio eorum, dixit: Audite me, viri Juda, et omnes habitatores Jerusalem: credite in Domino Deo vestro, et securi eritis: credite prophetis ejus, et cuncta evenient prospera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Deditque consilium populo, et statuit cantores Domini ut laudarent eum in turmis suis, et antecederent exercitum, ac voce consona dicerent: Confitemini Domino quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Cumque cœpissent laudes canere, vertit Dominus insidias eorum in semetipsos, filiorum scilicet Ammon, et Moab, et montis Seir, qui egressi fuerant ut pugnarent contra Judam: et percussi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Namque filii Ammon et Moab consurrexerunt adversum habitatores montis Seir, ut interficerent et delerent eos: cumque hoc opere perpetrassent, etiam in semetipsos versi, mutuis concidere vulneribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Porro Juda, cum venisset ad speculam quæ respicit solitudinem, vidit procul omnem late regionem plenam cadaveribus, nec superesse quemquam qui necem potuisset evadere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Venit ergo Josaphat, et omnis populus cum eo, ad detrahenda spolia mortuorum: inveneruntque inter cadavera variam supellectilem, vestes quoque, et vasa pretiosissima, et diripuerunt ita ut omnia portare non possent, nec per tres dies spolia auferre præ prædæ magnitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Die autem quarto congregati sunt in Valle benedictionis: etenim quoniam ibi benedixerant Domino, vocaverunt locum illum Vallis benedictionis usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Reversusque est omnis vir Juda, et habitatores Jerusalem, et Josaphat ante eos, in Jerusalem cum lætitia magna, eo quod dedisset eis Dominus gaudium de inimicis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Ingressique sunt in Jerusalem cum psalteriis, et citharis, et tubis in domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Irruit autem pavor Domini super universa regna terrarum cum audissent quod pugnasset Dominus contra inimicos Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Quievitque regnum Josaphat, et præbuit ei Deus pacem per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Regnavit igitur Josaphat super Judam, et erat triginta quinque annorum cum regnare cœpisset: viginti autem et quinque annis regnavit in Jerusalem, et nomen matris ejus Azuba filia Selahi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Et ambulavit in via patris suis Asa, nec declinavit ab ea, faciens quæ placita erant coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Verumtamen excelsa non abstulit, et adhuc populus non direxerat cor suum ad Dominum Deum patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Reliqua autem gestorum Josaphat priorum et novissimorum scripta sunt in verbis Jehu filii Hanani, quæ digessit in libros regum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Post hæc iniit amicitias Josaphat rex Juda cum Ochozia rege Israël, cujus opera fuerunt impiissima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Et particeps fuit ut facerent naves quæ irent in Tharsis: feceruntque classem in Asiongaber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Prophetavit autem Eliezer filius Dodau de Maresa ad Josaphat, dicens: Quia habuisti fœdus cum Ochozia, percussit Dominus opera tua, contritæque sunt naves, nec potuerunt ire in Tharsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Dormivit autem Josaphat cum patribus suis, et sepultus est cum eis in civitate David: regnavitque Joram filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Qui habuit fratres filios Josaphat, Azariam, et Jahiel, et Zachariam, et Azariam, et Michaël, et Saphatiam: omnes hi filii Josaphat regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Deditque eis pater suus multa munera argenti et auri, et pensitationes, cum civitatibus munitissimis in Juda: regnum autem tradidit Joram, eo quod esset primogenitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Surrexit ergo Joram super regnum patris sui: cumque se confirmasset, occidit omnes fratres suos gladio, et quosdam de principibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Triginta duorum annorum erat Joram cum regnare cœpisset, et octo annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Ambulavitque in viis regum Israël, sicut egerat domus Achab: filia quippe Achab erat uxor ejus: et fecit malum in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Noluit autem Dominus disperdere domum David propter pactum quod inierat cum eo: et quia promiserat ut daret ei lucernam, et filiis ejus omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'In diebus illis rebellavit Edom, ne esset subditus Judæ, et constituit sibi regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Cumque transisset Joram cum principibus suis, et cuncto equitatu qui erat secum, surrexit nocte, et percussit Edom, qui se circumdederat, et omnes duces equitatus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Attamen rebellavit Edom, ne esset sub ditione Juda usque ad hanc diem: eo tempore et Lobna recessit ne esset sub manu illius. Dereliquerat enim Dominum Deum patrum suorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'insuper et excelsa fabricatus est in urbibus Juda, et fornicari fecit habitatores Jerusalem, et prævaricari Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Allatæ sunt autem ei litteræ ab Elia propheta, in quibus scriptum erat: Hæc dicit Dominus Deus David patris tui: Quoniam non ambulasti in viis Josaphat patris tui, et in viis Asa regis Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'sed incessisti per iter regum Israël, et fornicari fecisti Judam et habitatores Jerusalem, imitatus fornicationem domus Achab, insuper et fratres tuos, domum patris tui, meliores te, occidisti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'ecce Dominus percutiet te plaga magna cum populo tuo, et filiis, et uxoribus tuis, universaque substantia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Tu autem ægrotabis pessimo languore uteri tui, donec egrediantur vitalia tua paulatim per singulos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Suscitavit ergo Dominus contra Joram spiritum Philisthinorum, et Arabum qui confines sunt \'thiopibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'et ascenderunt in terram Juda, et vastaverunt eam, diripueruntque cunctam substantiam quæ inventa est in domo regis, insuper et filios ejus, et uxores: nec remansit ei filius, nisi Joachaz, qui minimus natu erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Et super hæc omnia percussit eum Dominus alvi languore insanabili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Cumque diei succederet dies, et temporum spatia volverentur, duorum annorum expletus est circulus: et sic longa consumptus tabe, ita ut egereret etiam viscera sua, languore pariter, et vita caruit. Mortuusque est in infirmitate pessima, et non fecit ei populus secundum morem combustionis exequias, sicut fecerat majoribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Triginta duorum annorum fuit cum regnare cœpisset, et octo annis regnavit in Jerusalem. Ambulavitque non recte, et sepelierunt eum in civitate David, verumtamen non in sepulchro regum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Constituerunt autem habitatores Jerusalem Ochoziam filium ejus minimum regem pro eo: omnes enim majores natu, qui ante eum fuerant, interfecerant latrones Arabum qui irruerant in castra: regnavitque Ochozias filius Joram regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Quadraginta duorum annorum erat Ochozias cum regnare cœpisset, et uno anno regnavit in Jerusalem: et nomen matris ejus Athalia filia Amri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Sed et ipse ingressus est per vias domus Achab: mater enim ejus impulit eum ut impie ageret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Fecit igitur malum in conspectu Domini, sicut domus Achab: ipsi enim fuerunt ei consiliarii post mortem patris sui, in interitum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'ambulavitque in consiliis eorum. Et perrexit cum Joram filio Achab rege Israël in bellum contra Hazaël regem Syriæ in Ramoth Galaad: vulneraveruntque Syri Joram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Qui reversus est ut curaretur in Jezrahel: multas enim plagas acceperat in supradicto certamine. Igitur Ochozias filius Joram rex Juda descendit ut inviseret Joram filium Achab in Jezrahel ægrotantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Voluntatis quippe fuit Dei adversus Ochoziam, ut veniret ad Joram: et cum venisset, et egrederetur cum eo adversum Jehu filium Namsi, quem unxit Dominus ut deleret domum Achab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Cum ergo everteret Jehu domum Achab, invenit principes Juda, et filios fratrum Ochoziæ, qui ministrabant ei, et interfecit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Ipsum quoque perquirens Ochoziam, comprehendit latitantem in Samaria: adductumque ad se, occidit: et sepelierunt eum, eo quod esset filius Josaphat, qui quæsierat Dominum in toto corde suo. Nec erat ultra spes aliqua ut de stirpe quis regnaret Ochoziæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'siquidem Athalia mater ejus, videns quod mortuus esset filius suus, surrexit, et interfecit omnem stirpem regiam domus Joram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Porro Josabeth filia regis tulit Joas filium Ochoziæ, et furata est eum de medio filiorum regis, cum interficerentur: absconditque eum cum nutrice sua in cubiculo lectulorum: Josabeth autem, quæ absconderat eum, erat filia regis Joram, uxor Jojadæ pontificis, soror Ochoziæ: et idcirco Athalia non interfecit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Fuit ergo cum eis in domo Dei absconditus sex annis, quibus regnavit Athalia super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Anno autem septimo, confortatus Jojada, assumpsit centuriones, Azariam videlicet filium Jeroham, et Ismahel filium Johanan, Azariam quoque filium Obed, et Maasiam filium Adaiæ, et Elisaphat filium Zechri: et iniit cum eis fœdus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Qui circumeuntes Judam, congregaverunt Levitas de cunctis urbibus Juda, et principes familiarum Israël, veneruntque in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Iniit ergo omnis multitudo pactum in domo Dei cum rege, dixitque ad eos Jojada: Ecce filius regis regnabit, sicut locutus est Dominus super filios David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Iste est ergo sermo quem facietis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'tertia pars vestrum qui veniunt ad sabbatum, sacerdotum, et Levitarum, et janitorum erit in portis: tertia vero pars ad domum regis: et tertia ad portam quæ appellatur Fundamenti: omne vero reliquum vulgus sit in atriis domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Nec quispiam alius ingrediatur domum Domini, nisi sacerdotes, et qui ministrant de Levitis: ipsi tantummodo ingrediantur, quia sanctificati sunt: et omne reliquum vulgus observet custodias Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Levitæ autem circumdent regem, habentes singuli arma sua (et siquis alius ingressus fuerit templum, interficiatur), sintque cum rege et intrante et egrediente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Fecerunt ergo Levitæ, et universus Juda, juxta omnia quæ præceperat Jojada pontifex: et assumpserunt singuli viros qui sub se erant, et veniebant per ordinem sabbati, cum his qui impleverant sabbatum et egressuri erant: siquidem Jojada pontifex non dimiserat abire turmas quæ sibi per singulas hebdomadas succedere consueverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Deditque Jojada sacerdos centurionibus lanceas, clypeosque et peltas regis David, quas consecraverat in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Constituitque omnem populum tenentium pugiones a parte templi dextra, usque ad partem templi sinistram, coram altari et templo, per circuitum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Et eduxerunt filium regis, et imposuerunt ei diadema et testimonium, dederuntque in manu ejus tenendam legem, et constituerunt eum regem: unxit quoque illum Jojada pontifex, et filii ejus: imprecatique sunt ei, atque dixerunt: Vivat rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Quod cum audisset Athalia, vocem scilicet currentium atque laudantium regem, ingressa est ad populum in templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Cumque vidisset regem stantem super gradum in introitu, et principes, turmasque circa eum, omnemque populum terræ gaudentem, atque clangentem tubis, et diversi generis organis concinentem, vocemque laudantium, scidit vestimenta sua, et ait: Insidiæ, insidiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Egressus autem Jojada pontifex ad centuriones et principes exercitus, dixit eis: Educite illam extra septa templi, et interficiatur foris gladio. Præcepitque sacerdos ne occideretur in domo Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'et imposuerunt cervicibus ejus manus: cumque intrasset portam equorum domus regis, interfecerunt eam ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Pepigit autem Jojada fœdus inter se, universumque populum, et regem, ut esset populus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Itaque ingressus est omnis populus domum Baal, et destruxerunt eam, et altaria ac simulacra illius confregerunt: Mathan quoque sacerdotem Baal interfecerunt ante aras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Constituit autem Jojada præpositos in domo Domini sub manibus sacerdotum et Levitarum quos distribuit David in domo Domini, ut offerrent holocausta Domino, sicut scriptum est in lege Moysi, in gaudio et canticis, juxta dispositionem David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Constituit quoque janitores in portis domus Domini, ut non ingrederetur eam immundus in omni re.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Assumpsitque centuriones, et fortissimos viros, ac principes populi, et omne vulgus terræ, et fecerunt descendere regem de domo Domini, et introire per medium portæ superioris in domum regis, et collocaverunt eum in solio regali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Lætatusque est omnis populus terræ, et urbs quievit: porro Athalia interfecta est gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Septem annorum erat Joas cum regnare cœpisset, et quadraginta annis regnavit in Jerusalem: nomen matris ejus Sebia de Bersabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Fecitque quod bonum est coram Domino cunctis diebus Jojadæ sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Accepit autem ei Jojada uxores duas, e quibus genuit filios et filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Post quæ placuit Joas ut instauraret domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Congregavitque sacerdotes et Levitas, et dixit eis: Egredimini ad civitates Juda, et colligite de universo Israël pecuniam ad sartatecta templi Dei vestri per singulos annos, festinatoque hoc facite. Porro Levitæ egere negligentius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Vocavitque rex Jojadam principem, et dixit ei: Quare tibi non fuit curæ, ut cogeres Levitas inferre de Juda et de Jerusalem pecuniam quæ constituta est a Moyse servo Domini, ut inferret eam omnis multitudo Israël in tabernaculum testimonii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Athalia enim impiissima, et filii ejus, destruxerunt domum Dei, et de universis quæ sanctificata fuerant in templo Domini, ornaverunt fanum Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Præcepit ergo rex, et fecerunt arcam: posueruntque eam juxta portam domus Domini forinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Et prædicatum est in Juda et Jerusalem ut deferrent singuli pretium Domino, quod constituit Moyses servus Dei super omnem Israël in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Lætatique sunt cuncti principes, et omnis populus, et ingressi contulerunt in arcam Domini, atque miserunt ita ut impleretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Cumque tempus esset ut deferrent arcam coram rege per manus Levitarum (videbant enim multam pecuniam), ingrediebatur scriba regis, et quem primus sacerdos constituerat, effundebantque pecuniam quæ erat in arca, porro arcam reportabant ad locum suum: sicque faciebant per singulos dies. Et congregata est infinita pecunia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'quam dederunt rex et Jojada his qui præerant operibus domus Domini: at illi conducebant ex ea cæsores lapidum, et artifices operum singulorum ut instaurarent domum Domini: fabros quoque ferri et æris, ut quod cadere cœperat, fulciretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Egeruntque hi qui operabantur industrie, et obducebatur parietum cicatrix per manus eorum, ac suscitaverunt domum Domini in statum pristinum, et firmiter eam stare fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Cumque complessent omnia opera, detulerunt coram rege et Jojada reliquam partem pecuniæ: de qua facta sunt vasa templi in ministerium, et ad holocausta, phialæ quoque, et cetera vasa aurea et argentea: offerebantur holocausta in domo Domini jugiter cunctis diebus Jojadæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Senuit autem Jojada plenus dierum, et mortuus est cum esset centum triginta annorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'sepelieruntque eum in civitate David cum regibus, eo quod fecisset bonum cum Israël, et cum domo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Postquam autem obiit Jojada, ingressi sunt principes Juda, et adoraverunt regem: qui delinitus obsequiis eorum, acquievit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et dereliquerunt templum Domini Dei patrum suorum, servieruntque lucis et sculptilibus: et facta est ira contra Judam et Jerusalem propter hoc peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Mittebatque eis prophetas ut reverterentur ad Dominum, quos protestantes illi audire nolebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Spiritus itaque Dei induit Zachariam filium Jojadæ sacerdotem, et stetit in conspectu populi, et dixit eis: Hæc dicit Dominus Deus: Quare transgredimini præceptum Domini, quod vobis non proderit, et dereliquistis Dominum ut derelinqueret vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Qui congregati adversus eum, miserunt lapides juxta regis imperium in atrio domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Et non est recordatus Joas rex misericordiæ quam fecerat Jojada pater illius secum, sed interfecit filium ejus. Qui cum moreretur, ait: Videat Dominus, et requirat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Cumque evolutus esset annus, ascendit contra eum exercitus Syriæ: venitque in Judam et Jerusalem, et interfecit cunctos principes populi, atque universam prædam miserunt regi in Damascum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Et certe cum permodicus venisset numerus Syrorum, tradidit Dominus in manibus eorum infinitam multitudinem, eo quod dereliquissent Dominum Deum patrum suorum: in Joas quoque ignominiosa exercuere judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et abeuntes dimiserunt eum in languoribus magnis: surrexerunt autem contra eum servi sui in ultionem sanguinis filii Jojadæ sacerdotis, et occiderunt eum in lectulo suo, et mortuus est: sepelieruntque eum in civitate David, sed non in sepulchris regum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Insidiati vero sunt ei Zabad filius Semaath Ammanitidis, et Jozabad filius Semmarith Moabitidis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Porro filii ejus, ac summa pecuniæ quæ adunata fuerat sub eo, et instauratio domus Dei, scripta sunt diligentius in libro regum: regnavit autem Amasias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Viginti quinque annorum erat Amasias cum regnare cœpisset, et viginti novem annis regnavit in Jerusalem: nomen matris ejus Joadan de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Fecitque bonum in conspectu Domini, verumtamen non in corde perfecto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Cumque roboratum sibi videret imperium, jugulavit servos qui occiderant regem patrem suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'sed filios eorum non interfecit, sicut scriptum est in libro legis Moysi, ubi præcepit Dominus, dicens: Non occidentur patres pro filiis, neque filii pro patribus suis, sed unusquisque in suo peccato morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Congregavit igitur Amasias Judam, et constituit eos per familias, tribunosque et centuriones in universo Juda et Benjamin: et recensuit a viginti annis supra, invenitque trecenta millia juvenum qui egrederentur ad pugnam, et tenerent hastam et clypeum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'mercede quoque conduxit de Israël centum millia robustorum, centum talentis argenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Venit autem homo Dei ad illum, et ait: O rex, ne egrediatur tecum exercitus Israël: non est enim Dominus cum Israël, et cunctis filiis Ephraim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'quod si putas in robore exercitus bella consistere, superari te faciet Deus ab hostibus: Dei quippe est et adjuvare, et in fugam convertere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Dixitque Amasias ad hominem Dei: Quid ergo fiet de centum talentis, quæ dedi militibus Israël? Et respondit ei homo Dei: Habet Dominus unde tibi dare possit multo his plura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Separavit itaque Amasias exercitum qui venerat ad eum ex Ephraim, ut reverteretur in locum suum: at illi contra Judam vehementer irati, reversi sunt in regionem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Porro Amasias confidenter eduxit populum suum, et abiit in vallem Salinarum, percussitque filios Seir decem millia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'et alia decem millia virorum ceperunt filii Juda, et adduxerunt ad præruptum cujusdam petræ, præcipitaveruntque eos de summo in præceps: qui universi crepuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'At ille exercitus quem remiserat Amasias ne secum iret ad prælium, diffusus est in civitatibus Juda, a Samaria usque ad Bethoron, et interfectis tribus millibus, diripuit prædam magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Amasias vero post cædem Idumæorum, et allatos deos filiorum Seir, statuit illos in deos sibi, et adorabat eos, et illis adolebat incensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Quam ob rem iratus Dominus contra Amasiam misit ad illum prophetam, qui diceret ei: Cur adorasti deos qui non liberaverunt populum suum de manu tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Cumque hæc ille loqueretur, respondit ei: Num consiliarius regis es? quiesce, ne interficiam te. Discedensque propheta: Scio, inquit, quod cogitaverit Deus occidere te quia fecisti hoc malum, et insuper non acquievisti consilio meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Igitur Amasias rex Juda inito pessimo consilio, misit ad Joas filium Joachaz filii Jehu regem Israël, dicens: Veni, videamus nos mutuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'At ille remisit nuntios, dicens: Carduus qui est in Libano misit ad cedrum Libani, dicens: Da filiam tuam filio meo uxorem: et ecce bestiæ quæ erant in silva Libani, transierunt, et conculcaverunt carduum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Dixisti: Percussi Edom, et idcirco erigitur cor tuum in superbiam: sede in domo tua: cur malum adversum te provocas, ut cadas et tu, et Juda tecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Noluit audire Amasias, eo quod Domini esset voluntas ut traderetur in manus hostium propter deos Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Ascendit igitur Joas rex Israël, et mutuos sibi præbuere conspectus: Amasias autem rex Juda erat in Bethsames Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'corruitque Juda coram Israël, et fugit in tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Porro Amasiam regem Juda, filium Joas filii Joachaz, cepit Joas rex Israël in Bethsames, et adduxit in Jerusalem: destruxitque murum ejus a porta Ephraim usque ad portam anguli quadringentis cubitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Omne quoque aurum et argentum, et universa vasa quæ repererat in domo Dei, et apud Obededom in thesauris etiam domus regiæ, necnon et filios obsidum, reduxit in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Vixit autem Amasias filius Joas rex Juda, postquam mortuus est Joas filius Joachaz rex Israël, quindecim annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Reliqua autem sermonum Amasiæ priorum et novissimorum scripta sunt in libro regum Juda et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Qui postquam recessit a Domino, tetenderunt ei insidias in Jerusalem. Cumque fugisset in Lachis, miserunt, et interfecerunt eum ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Reportantesque super equos, sepelierunt eum cum patribus suis in civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Omnis autem populus Juda filium ejus Oziam, annorum sedecim, constituit regem pro Amasia patre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ipse ædificavit Ailath, et restituit eam ditioni Juda, postquam dormivit rex cum patribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sedecim annorum erat Ozias cum regnare cœpisset, et quinquaginta duobus annis regnavit in Jerusalem: nomen matris ejus Jechelia de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Fecitque quod erat rectum in oculis Domini, juxta omnia quæ fecerat Amasias pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Et exquisivit Dominum in diebus Zachariæ intelligentis et videntis Deum: cumque requireret Dominum, direxit eum in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Denique egressus est, et pugnavit contra Philisthiim, et destruxit murum Geth, et murum Jabniæ, murumque Azoti: ædificavit quoque oppida in Azoto et in Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et adjuvit eum Deus contra Philisthiim, et contra Arabes qui habitabant in Gurbaal, et contra Ammonitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Appendebantque Ammonitæ munera Oziæ: et divulgatum est nomen ejus usque ad introitum \'gypti propter crebras victorias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, '\'dificavitque Ozias turres in Jerusalem super portam anguli, et super portam vallis, et reliquas in eodem muri latere, firmavitque eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Exstruxit etiam turres in solitudine, et effodit cisternas plurimas, eo quod haberet multa pecora tam in campestribus quam in eremi vastitate: vineas quoque habuit et vinitores, in montibus et in Carmelo: erat quippe homo agriculturæ deditus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Fuit autem exercitus bellatorum ejus, qui procedebant ad prælia sub manu Jehiel scribæ, Maasiæque doctoris, et sub manu Hananiæ, qui erat de ducibus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Omnisque numerus principum per familias, virorum fortium duorum millium sexcentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Et sub eis universus exercitus trecentorum et septem millium quingentorum, qui erant apti ad bella, et pro rege contra adversarios dimicabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Præparavit quoque eis Ozias, id est, cuncto exercitui, clypeos, et hastas, et galeas, et loricas, arcusque et fundas ad jaciendos lapides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Et fecit in Jerusalem diversi generis machinas, quas in turribus collocavit et in angulis murorum, ut mitterent sagittas, et saxa grandia: egressumque est nomen ejus procul, eo quod auxiliaretur ei Dominus, et corroborasset illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Sed cum roboratus esset, elevatum est cor ejus in interitum suum, et neglexit Dominum Deum suum: ingressusque templum Domini, adolere voluit incensum super altare thymiamatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Statimque ingressus post eum Azarias sacerdos, et cum eo sacerdotes Domini octoginta, viri fortissimi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'restiterunt regi, atque dixerunt: Non est tui officii, Ozia, ut adoleas incensum Domino, sed sacerdotum, hoc est, filiorum Aaron, qui consecrati sunt ad hujuscemodi ministerium: egredere de sanctuario, ne contempseris: quia non reputabitur tibi in gloriam hoc a Domino Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Iratusque Ozias, tenens in manu thuribulum ut adoleret incensum, minabatur sacerdotibus. Statimque orta est lepra in fronte ejus coram sacerdotibus, in domo Domini super altare thymiamatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Cumque respexisset eum Azarias pontifex, et omnes reliqui sacerdotes, viderunt lepram in fronte ejus, et festinato expulerunt eum. Sed et ipse perterritus, acceleravit egredi, eo quod sensisset illico plagam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Fuit igitur Ozias rex leprosus usque ad diem mortis suæ, et habitavit in domo separata plenus lepra, ob quam ejectus fuerat de domo Domini. Porro Joatham filius ejus rexit domum regis, et judicabat populum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Reliqua autem sermonum Oziæ priorum et novissimorum scripsit Isaias filius Amos propheta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Dormivitque Ozias cum patribus suis, et sepelierunt eum in agro regalium sepulchrorum, eo quod esset leprosus: regnavitque Joatham filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Viginti quinque annorum erat Joatham cum regnare cœpisset, et sedecim annis regnavit in Jerusalem: nomen matris ejus Jerusa filia Sadoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Fecitque quod rectum erat coram Domino, juxta omnia quæ fecerat Ozias pater suus, excepto quod non est ingressus templum Domini: et adhuc populus delinquebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ipse ædificavit portam domus Domini excelsam, et in muro Ophel multa construxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Urbes quoque ædificavit in montibus Juda, et in saltibus castella et turres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Ipse pugnavit contra regem filiorum Ammon, et vicit eos, dederuntque ei filii Ammon in tempore illo centum talenta argenti, et decem millia coros tritici, ac totidem coros hordei: hæc ei præbuerunt filii Ammon in anno secundo et tertio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Corroboratusque est Joatham, eo quod direxisset vias suas coram Domino Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Reliqua autem sermonum Joatham, et omnes pugnæ ejus et opera, scripta sunt in libro regum Israël et Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Viginti quinque annorum erat cum regnare cœpisset, et sedecim annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Dormivitque Joatham cum patribus suis, et sepelierunt eum in civitate David: et regnavit Achaz filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Viginti annorum erat Achaz cum regnare cœpisset, et sedecim annis regnavit in Jerusalem. Non fecit rectum in conspectu Domini sicut David pater ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'sed ambulavit in viis regum Israël, insuper et statuas fudit Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Ipse est qui adolevit incensum in valle Benennom, et lustravit filios suos in igne juxta ritum gentium quas interfecit Dominus in adventu filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Sacrificabat quoque, et thymiama succendebat in excelsis, et in collibus, et sub omni ligno frondoso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Tradiditque eum Dominus Deus ejus in manu regis Syriæ, qui percussit eum, magnamque prædam cepit de ejus imperio, et adduxit in Damascum: manibus quoque regis Israël traditus est, et percussus plaga grandi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Occiditque Phacee filius Romeliæ, de Juda centum viginti millia in die uno, omnes viros bellatores: eo quod reliquissent Dominum Deum patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Eodem tempore occidit Zechri, vir potens ex Ephraim, Maasiam filium regis, et Ezricam ducem domus ejus, Elcanam quoque secundum a rege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Ceperuntque filii Israël de fratribus suis ducenta millia mulierum, puerorum, et puellarum, et infinitam prædam: pertuleruntque eam in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Ea tempestate erat ibi propheta Domini, nomine Oded: qui egressus obviam exercitui venienti in Samariam, dixit eis: Ecce iratus Dominus Deus patrum vestrorum contra Juda, tradidit eos in manibus vestris, et occidistis eos atrociter, ita ut ad cælum pertingeret vestra crudelitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Insuper filios Juda et Jerusalem vultis vobis subjicere in servos et ancillas: quod nequaquam facto opus est: peccastis enim super hoc Domino Deo vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Sed audite consilium meum, et reducite captivos quos adduxistis de fratribus vestris, quia magnus furor Domini imminet vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Steterunt itaque viri de principibus filiorum Ephraim, Azarias filius Johanan, Barachias filius Mosollamoth, Ezechias filius Sellum, et Amasa filius Adali, contra eos qui veniebant de prælio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'et dixerunt eis: Non introducetis huc captivos, ne peccemus Domino. Quare vultis adjicere super peccata nostra, et vetera cumulare delicta? grande quippe peccatum est, et ira furoris Domini imminet super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Dimiseruntque viri bellatores prædam, et universa quæ ceperant, coram principibus, et omni multitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Steteruntque viri quos supra memoravimus, et apprehendentes captivos, omnesque qui nudi erant, vestierunt de spoliis: cumque vestissent eos, et calceassent, et refecissent cibo ac potu, unxissentque propter laborem, et adhibuissent eis curam: quicumque ambulare non poterant, et erant imbecillo corpore, imposuerunt eos jumentis, et adduxerunt Jericho civitatem palmarum ad fratres eorum, ipsique reversi sunt in Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Tempore illo misit rex Achaz ad regem Assyriorum, postulans auxilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Veneruntque Idumæi, et percusserunt multos ex Juda, et ceperunt prædam magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Philisthiim quoque diffusi sunt per urbes campestres, et ad meridiem Juda: ceperuntque Bethsames, et Ajalon, et Gaderoth, Socho quoque, et Thamnan, et Gamzo, cum viculis suis, et habitaverunt in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Humiliaverat enim Dominus Judam propter Achaz regem Juda, eo quod nudasset eum auxilio, et contemptui habuisset Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Adduxitque contra eum Thelgathphalnasar regem Assyriorum, qui et afflixit eum, et nullo resistente vastavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Igitur Achaz, spoliata domo Domini, et domo regum ac principum, dedit regi Assyriorum munera, et tamen nihil ei profuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Insuper et tempore angustiæ suæ auxit contemptum in Dominum, ipse per se rex Achaz,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'immolavit diis Damasci victimas percussoribus suis, et dixit: Dii regum Syriæ auxiliantur eis, quos ego placabo hostiis, et aderunt mihi: cum e contrario ipsi fuerint ruinæ ei, et universo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Direptis itaque Achaz omnibus vasis domus Dei, atque confractis, clausit januas templi Dei, et fecit sibi altaria in universis angulis Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'In omnibus quoque urbibus Juda exstruxit aras ad cremandum thus, atque ad iracundiam provocavit Dominum Deum patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Reliqua autem sermonum ejus, et omnium operum suorum priorum et novissimorum, scripta sunt in libro regum Juda et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Dormivitque Achaz cum patribus suis, et sepelierunt eum in civitate Jerusalem: neque enim receperunt eum in sepulchra regum Israël. Regnavitque Ezechias filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Igitur Ezechias regnare cœpit, cum viginti quinque esset annorum, et viginti novem annis regnavit in Jerusalem: nomen matris ejus Abia filia Zachariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Fecitque quod erat placitum in conspectu Domini, juxta omnia quæ fecerat David pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Ipse, anno et mense primo regni sui, aperuit valvas domus Domini, et instauravit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Adduxitque sacerdotes atque Levitas, et congregavit eos in plateam orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Dixitque ad eos: Audite me, Levitæ, et sanctificamini: mundate domum Domini Dei patrum vestrorum, et auferte omnem immunditiam de sanctuario.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Peccaverunt patres nostri, et fecerunt malum in conspectu Domini Dei nostri, derelinquentes eum: averterunt facies suas a tabernaculo Domini, et præbuerunt dorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Clauserunt ostia quæ erant in porticu, et extinxerunt lucernas, incensumque non adoleverunt, et holocausta non obtulerunt in sanctuario Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Concitatus est itaque furor Domini super Judam et Jerusalem, tradiditque eos in commotionem, et in interitum, et in sibilum, sicut ipsi cernitis oculis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'En corruerunt patres nostri gladiis: filii nostri, et filiæ nostræ, et conjuges captivæ ductæ sunt propter hoc scelus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nunc ergo placet mihi ut ineamus fœdus cum Domino Deo Israël, et avertet a nobis furorem iræ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Filii mei, nolite negligere: vos elegit Dominus ut stetis coram eo, et ministretis illi, colatisque eum, et cremetis ei incensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Surrexerunt ergo Levitæ: Mahath filius Amasai, et Joël filius Azariæ de filiis Caath: porro de filiis Merari, Cis filius Abdi, et Azarias filius Jalaleel. De filiis autem Gersom, Joah filius Zemma, et Eden filius Joah.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'At vero de filiis Elisaphan, Samri, et Jahiel. De filiis quoque Asaph, Zacharias, et Mathanias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'necnon de filiis Heman, Jahiel, et Semei: sed et de filiis Idithun, Semeias, et Oziel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Congregaveruntque fratres suos, et sanctificati sunt, et ingressi sunt juxta mandatum regis et imperium Domini, ut expiarent domum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Sacerdotes quoque ingressi templum Domini ut sanctificarent illud, extulerunt omnem immunditiam quam intro repererant in vestibulo domus Domini: quam tulerunt Levitæ, et asportaverunt ad torrentem Cedron foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Cœperunt autem prima die mensis primi mundare, et in die octavo ejusdem mensis ingressi sunt porticum templi Domini, expiaveruntque templum diebus octo, et in die sextadecima mensis ejusdem, quod cœperant, impleverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Ingressi quoque sunt ad Ezechiam regem, et dixerunt ei: Sanctificavimus omnem domum Domini, et altare holocausti, vasaque ejus, necnon et mensam propositionis cum omnibus vasis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'cunctamque templi supellectilem, quam polluerat rex Achaz in regno suo, postquam prævaricatus est: et ecce exposita sunt omnia coram altare Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Consurgensque diluculo Ezechias rex, adunavit omnes principes civitatis, et ascendit in domum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'obtuleruntque simul tauros septem, et arietes septem, agnos septem, et hircos septem pro peccato, pro regno, pro sanctuario, pro Juda: dixitque sacerdotibus filiis Aaron, ut offerrent super altare Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Mactaverunt igitur tauros, et susceperunt sanguinem sacerdotes, et fuderunt illum super altare: mactaverunt etiam arietes, et illorum sanguinem super altare fuderunt, immolaveruntque agnos, et fuderunt super altare sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Applicuerunt hircos pro peccato coram rege, et universa multitudine, imposueruntque manus suas super eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'et immolaverunt illos sacerdotes, et asperserunt sanguinem eorum coram altare pro piaculo universi Israëlis: pro omni quippe Israël præceperat rex ut holocaustum fieret, et pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Constituit quoque Levitas in domo Domini cum cymbalis, et psalteriis, et citharis secundum dispositionem David regis, et Gad videntis, et Nathan prophetæ: siquidem Domini præceptum fuit per manum prophetarum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Steteruntque Levitæ tenentes organa David, et sacerdotes tubas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Et jussit Ezechias ut offerrent holocausta super altare: cumque offerrentur holocausta, cœperunt laudes canere Domino, et clangere tubis, atque in diversis organis quæ David rex Israël præparaverat, concrepare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Omni autem turba adorante, cantores, et ii qui tenebant tubas, erant in officio suo donec compleretur holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Cumque finita esset oblatio, incurvatus est rex, et omnes qui erant cum eo, et adoraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Præcepitque Ezechias et principes Levitis, ut laudarent Dominum sermonibus David, et Asaph videntis: qui laudaverunt eum magna lætitia, et incurvato genu adoraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Ezechias autem etiam hæc addidit: Implestis manus vestras Domino: accedite, et offerte victimas et laudes in domo Domini. Obtulit ergo universa multitudo hostias, et laudes, et holocausta, mente devota.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Porro numerus holocaustorum quæ obtulit multitudo, hic fuit: tauros septuaginta, arietes centum, agnos ducentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Sanctificaveruntque Domino boves sexcentos, et oves tria millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Sacerdotes vero pauci erant, nec poterant sufficere ut pelles holocaustorum detraherent: unde et Levitæ fratres eorum adjuverunt eos, donec impleretur opus, et sanctificarentur antistites: Levitæ quippe faciliori ritu sanctificantur quam sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Fuerunt ergo holocausta plurima, adipes pacificorum, et libamina holocaustorum: et completus est cultus domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Lætatusque est Ezechias et omnis populus, eo quod ministerium Domini esset expletum: de repente quippe hoc fieri placuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Misit quoque Ezechias ad omnem Israël et Judam: scripsitque epistolas ad Ephraim et Manassen ut venirent ad domum Domini in Jerusalem, et facerent Phase Domino Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Inito ergo consilio regis et principum, et universi cœtus Jerusalem, decreverunt ut facerent Phase mense secundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Non enim potuerant facere in tempore suo, quia sacerdotes qui possent sufficere, sanctificati non fuerant, et populus nondum congregatus fuerat in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Placuitque sermo regi, et omni multitudini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Et decreverunt ut mitterent nuntios in universum Israël, de Bersabee usque Dan, ut venirent, et facerent Phase Domino Deo Israël in Jerusalem: multi enim non fecerant sicut lege præscriptum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Perrexeruntque cursores cum epistolis ex regis imperio, et principum ejus, in universum Israël et Judam, juxta id quod rex jusserat, prædicantes: Filii Israël, revertimini ad Dominum Deum Abraham, et Isaac, et Israël: et revertetur ad reliquias quæ effugerunt manum regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Nolite fieri sicut patres vestri et fratres, qui recesserunt a Domino Deo patrum suorum, qui tradidit eos in interitum, ut ipsi cernitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nolite indurare cervices vestras, sicut patres vestri: tradite manus Domino, et venite ad sanctuarium ejus quod sanctificavit in æternum: servite Domino Deo patrum vestrorum, et avertetur a vobis ira furoris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Si enim vos reversi fueritis ad Dominum, fratres vestri et filii habebunt misericordiam coram dominis suis, qui illos duxerunt captivos, et revertentur in terram hanc: pius enim et clemens est Dominus Deus vester, et non avertet faciem suam a vobis, si reversi fueritis ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Igitur cursores pergebant velociter de civitate in civitatem per terram Ephraim et Manasse usque ad Zabulon, illis irridentibus et subsannantibus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Attamen quidam viri ex Aser, et Manasse, et Zabulon acquiescentes consilio, venerunt Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'In Juda vero facta est manus Domini ut daret eis cor unum, ut facerent juxta præceptum regis et principum verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Congregatique sunt in Jerusalem populi multi ut facerent solemnitatem azymorum, in mense secundo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'et surgentes destruxerunt altaria quæ erant in Jerusalem, atque universa in quibus idolis adolebatur incensum, subvertentes, projecerunt in torrentem Cedron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Immolaverunt autem Phase quartadecima die mensis secundi. Sacerdotes quoque atque Levitæ tandem sanctificati, obtulerunt holocausta in domo Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'steteruntque in ordine suo juxta dispositionem et legem Moysi hominis Dei: sacerdotes vero suscipiebant effundendum sanguinem de manibus Levitarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'eo quod multa turba sanctificata non esset: et idcirco immolarent Levitæ Phase his qui non occurrerant sanctificari Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Magna etiam pars populi de Ephraim, et Manasse, et Issachar, et Zabulon, quæ sanctificata non fuerat, comedit Phase non juxta quod scriptum est: et oravit pro eis Ezechias, dicens: Dominus bonus propitiabitur');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'cunctis, qui in toto corde requirunt Dominum Deum patrum suorum: et non imputabit eis quod minus sanctificati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Quem exaudivit Dominus, et placatus est populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Feceruntque filii Israël, qui inventi sunt in Jerusalem, solemnitatem azymorum septem diebus in lætitia magna, laudantes Dominum per singulos dies: Levitæ quoque et sacerdotes per organa quæ suo officio congruebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et locutus est Ezechias ad cor omnium Levitarum qui habebant intelligentiam bonam super Domino: et comederunt septem diebus solemnitatis, immolantes victimas pacificorum, et laudantes Dominum Deum patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Placuitque universæ multitudini ut celebrarent etiam alios dies septem: quod et fecerunt cum ingenti gaudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Ezechias enim rex Juda præbuerat multitudini mille tauros, et septem millia ovium: principes vero dederant populo tauros mille, et oves decem millia: sanctificata est ergo sacerdotum plurima multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et hilaritate perfusa omnis turba Juda, tam sacerdotum et Levitarum, quam universæ frequentiæ quæ venerat ex Israël: proselytorum quoque de terra Israël, et habitantium in Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Factaque est grandis celebritas in Jerusalem, qualis a diebus Salomonis filii David regis Israël in ea urbe non fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Surrexerunt autem sacerdotes atque Levitæ benedicentes populo: et exaudita est vox eorum, pervenitque oratio in habitaculum sanctum cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Cumque hæc fuissent rite celebrata, egressus est omnis Israël qui inventus fuerat in urbibus Juda, et fregerunt simulacra, succideruntque lucos, demoliti sunt excelsa, et altaria destruxerunt, non solum de universo Juda et Benjamin, sed et de Ephraim quoque et Manasse, donec penitus everterent: reversique sunt omnes filii Israël in possessiones et civitates suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezechias autem constituit turmas sacerdotales et Leviticas per divisiones suas, unumquemque in officio proprio, tam sacerdotum videlicet quam Levitarum, ad holocausta et pacifica, ut ministrarent et confiterentur, canerentque in portis castrorum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Pars autem regis erat, ut de propria ejus substantia offerretur holocaustum, mane semper et vespere: sabbatis quoque, et calendis, et solemnitatibus ceteris, sicut scriptum est in lege Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Præcepit etiam populo habitantium Jerusalem ut darent partes sacerdotibus et Levitis, ut possent vacare legi Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Quod cum percrebruisset in auribus multitudinis, plurimas obtulere primitias filii Israël frumenti, vini, et olei: mellis quoque, et omnium quæ gignit humus, decimas obtulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Sed et filii Israël et Juda qui habitabant in urbibus Juda, obtulerunt decimas boum et ovium, decimasque sanctorum quæ voverant Domino Deo suo: atque universa portantes, fecerunt acervos plurimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Mense tertio cœperunt acervorum jacere fundamenta, et mense septimo compleverunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Cumque ingressi fuissent Ezechias et principes ejus, viderunt acervos, et benedixerunt Domino ac populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Interrogavitque Ezechias sacerdotes et Levitas, cur ita jacerent acervi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Respondit illi Azarias sacerdos primus de stirpe Sadoc, dicens: Ex quo cœperunt offerri primitiæ in domo Domini, comedimus, et saturati sumus, et remanserunt plurima, eo quod benedixerit Dominus populo suo: reliquarum autem copia est ista, quam cernis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Præcepit igitur Ezechias ut præpararent horrea in domo Domini. Quod cum fecissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'intulerunt tam primitias quam decimas, et quæcumque voverant, fideliter. Fuit autem præfectus eorum Chonenias Levita, et Semei frater ejus secundus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'post quem Jahiel, et Azarias, et Nahath, et Asaël, et Jerimoth, Jozabad quoque, et Eliel, et Jesmachias, et Mahath, et Banaias, præpositi sub manibus Choneniæ et Semei fratris ejus, ex imperio Ezechiæ regis et Azariæ pontificis domus Dei, ad quos omnia pertinebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Core vero filius Jemna Levites, et janitor orientalis portæ, præpositus erat iis quæ sponte offerebantur Domino, primitiisque et consecratis in Sancta sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Et sub cura ejus Eden, et Benjamin, Jesue, et Semeias, Amarias quoque, et Sechenias in civitatibus sacerdotum, ut fideliter distribuerent fratribus suis partes, minoribus atque majoribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'exceptis maribus ab annis tribus et supra, cunctis qui ingrediebantur templum Domini, et quidquid per singulos dies conducebat in ministerio, atque observationibus juxta divisiones suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'sacerdotibus per familias, et Levitis a vigesimo anno et supra, per ordines et turmas suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'universæque multitudini tam uxoribus quam liberis eorum utriusque sexus, fideliter cibi de his quæ sanctificata fuerant, præbebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Sed et filiorum Aaron per agros, et suburbana urbium singularum, dispositi erant viri, qui partes distribuerent universo sexui masculino de sacerdotibus et Levitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Fecit ergo Ezechias universa quæ diximus in omni Juda: operatusque est bonum et rectum, et verum coram Domino Deo suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'in universa cultura ministerii domus Domini, juxta legem et cæremonias, volens requirere Deum suum in toto corde suo: fecitque, et prosperatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Post quæ et hujuscemodi veritatem, venit Sennacherib rex Assyriorum, et ingressus Judam, obsedit civitates munitas, volens eas capere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Quod cum vidisset Ezechias, venisse scilicet Sennacherib, et totum belli impetum verti contra Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'inito cum principibus consilio, virisque fortissimis, ut obturarent capita fontium qui erant extra urbem: et hoc omnium decernente sententia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'congregavit plurimam multitudinem, et obturaverunt cunctos fontes, et rivum qui fluebat in medio terræ, dicentes: Ne veniant reges Assyriorum, et inveniant aquarum abundantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, '\'dificavit quoque, agens industrie, omnem murum qui fuerat dissipatus, et exstruxit turres desuper, et forinsecus alterum murum: instauravitque Mello in civitate David, et fecit universi generis armaturam et clypeos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'constituitque principes bellatorum in exercitu, et convocavit universos in platea portæ civitatis, ac locutus est ad cor eorum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Viriliter agite, et confortamini: nolite timere, nec paveatis regem Assyriorum, et universam multitudinem quæ est cum eo: multo enim plures nobiscum sunt, quam cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Cum illo enim est brachium carneum: nobiscum Dominus Deus noster, qui auxiliator est noster, pugnatque pro nobis. Confortatusque est populus hujuscemodi verbis Ezechiæ regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Quæ postquam gesta sunt, misit Sennacherib rex Assyriorum servos suos in Jerusalem (ipse enim cum universo exercitu obsidebat Lachis) ad Ezechiam regem Juda, et ad omnem populum qui erat in urbe, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Hæc dicit Sennacherib rex Assyriorum: In quo habentes fiduciam sedetis obsessi in Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'num Ezechias decipit vos, ut tradat morti in fame et siti, affirmans quod Dominus Deus vester liberet vos de manu regis Assyriorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Numquid non iste est Ezechias, qui destruxit excelsa illius, et altaria, et præcepit Juda et Jerusalem, dicens: Coram altari uno adorabitis, et in ipso comburetis incensum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'an ignoratis quæ ego fecerim, et patres mei, cunctis terrarum populis? numquid prævaluerunt dii gentium, omniumque terrarum, liberare regionem suam de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Quis est de universis diis gentium, quas vastaverunt patres mei, qui potuerit eruere populum suum de manu mea, ut possit etiam Deus vester eruere vos de hac manu?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'non vos ergo decipiat Ezechias, nec vana persuasione deludat, neque credatis ei. Si enim nullus potuit deus cunctarum gentium atque regnorum liberare populum suum de manu mea, et de manu patrum meorum, consequenter nec Deus vester poterit eruere vos de manu mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Sed et alia multa locuti sunt servi ejus contra Dominum Deum, et contra Ezechiam servum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Epistolas quoque scripsit plenas blasphemiæ in Dominum Deum Israël, et locutus est adversus eum: Sicut dii gentium ceterarum non potuerunt liberare populum suum de manu mea, sic et Deus Ezechiæ eruere non poterit populum suum de manu ista.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Insuper et clamore magno, lingua judaica, contra populum qui sedebat in muris Jerusalem, personabat, ut terreret eos, et caperet civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Locutusque est contra Deum Jerusalem, sicut adversum deos populorum terræ, opera manuum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Oraverunt igitur Ezechias rex, et Isaias filius Amos prophetes, adversum hanc blasphemiam, ac vociferati sunt usque in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Et misit Dominus angelum, qui percussit omnem virum robustum, et bellatorem, et principem exercitus regis Assyriorum: reversusque est cum ignominia in terram suam. Cumque ingressus esset domum dei sui, filii qui egressi fuerant de utero ejus interfecerunt eum gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Salvavitque Dominus Ezechiam et habitatores Jerusalem de manu Sennacherib regis Assyriorum, et de manu omnium, et præstitit eis quietem per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Multi etiam deferebant hostias et sacrificia Domino in Jerusalem, et munera Ezechiæ regi Juda: qui exaltatus est post hæc coram cunctis gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'In diebus illis ægrotavit Ezechias usque ad mortem, et oravit Dominum: exaudivitque eum, et dedit ei signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Sed non juxta beneficia quæ acceperat, retribuit, quia elevatum est cor ejus: et facta est contra eum ira, et contra Judam et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Humiliatusque est postea, eo quod exaltatum fuisset cor ejus, tam ipse quam habitatores Jerusalem: et idcirco non venit super eos ira Domini in diebus Ezechiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Fuit autem Ezechias dives, et inclytus valde, et thesauros sibi plurimos congregavit argenti, et auri, et lapidis pretiosi, aromatum, et armorum universi generis, et vasorum magni pretii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Apothecas quoque frumenti, vini, et olei, et præsepia omnium jumentorum, caulasque pecorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'et urbes ædificavit sibi: habebat quippe greges ovium et armentorum innumerabiles, eo quod dedisset ei Dominus substantiam multam nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ipse est Ezechias, qui obturavit superiorem fontem aquarum Gihon, et avertit eas subter ad occidentem urbis David: in omnibus operibus suis fecit prospere quæ voluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Attamen in legatione principum Babylonis, qui missi fuerant ad eum ut interrogarent de portento quod acciderat super terram, dereliquit eum Deus ut tentaretur, et nota fierent omnia quæ erant in corde ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Reliqua autem sermonum Ezechiæ, et misericordiarum ejus, scripta sunt in visione Isaiæ filii Amos prophetæ, et in libro regum Juda et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Dormivitque Ezechias cum patribus suis, et sepelierunt eum super sepulchra filiorum David: et celebravit ejus exequias universus Juda, et omnes habitatores Jerusalem: regnavitque Manasses filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Duodecim annorum erat Manasses cum regnare cœpisset, et quinquaginta quinque annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Fecit autem malum coram Domino, juxta abominationes gentium quas subvertit Dominus coram filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'et conversus instauravit excelsa quæ demolitus fuerat Ezechias pater ejus: construxitque aras Baalim, et fecit lucos, et adoravit omnem militiam cæli, et coluit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, '\'dificavit quoque altaria in domo Domini, de qua dixerat Dominus: In Jerusalem erit nomen meum in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, '\'dificavit autem ea cuncto exercitui cæli in duobus atriis domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Transireque fecit filios suos per ignem in valle Benennom: observabat somnia, sectabatur auguria, maleficis artibus inserviebat, habebat secum magos et incantatores, multaque mala operatus est coram Domino ut irritaret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Sculptile quoque et conflatile signum posuit in domo Dei, de qua locutus est Deus ad David, et ad Salomonem filium ejus, dicens: In domo hac, et in Jerusalem quam elegi de cunctis tribubus Israël, ponam nomen meum in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Et moveri non faciam pedem Israël de terra quam tradidi patribus eorum: ita dumtaxat si custodierint facere quæ præcepi eis, cunctamque legem, et cæremonias atque judicia, per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Igitur Manasses seduxit Judam, et habitatores Jerusalem, ut facerent malum super omnes gentes quas subverterat Dominus a facie filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Locutusque est Dominus ad eum, et ad populum illius, et attendere noluerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Idcirco superinduxit eis principes exercitus regis Assyriorum: ceperuntque Manassen, et vinctum catenis atque compedibus duxerunt in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Qui postquam coangustatus est, oravit Dominum Deum suum: et egit pœnitentiam valde coram Deo patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Deprecatusque est eum, et obsecravit intente: et exaudivit orationem ejus, reduxitque eum Jerusalem in regnum suum, et cognovit Manasses quod Dominus ipse esset Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Post hæc ædificavit murum extra civitatem David ad occidentem Gihon in convalle, ab introitu portæ piscium per circuitum usque ad Ophel, et exaltavit illum vehementer: constituitque principes exercitus in cunctis civitatibus Juda munitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'et abstulit deos alienos, et simulacrum de domo Domini: aras quoque, quas fecerat in monte domus Domini et in Jerusalem: et projecit omnia extra urbem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Porro instauravit altare Domini, et immolavit super illud victimas, et pacifica, et laudem: præcepitque Judæ ut serviret Domino Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Attamen adhuc populus immolabat in excelsis Domino Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Reliqua autem gestorum Manasse, et obsecratio ejus ad Deum suum, verba quoque videntium qui loquebantur ad eum in nomine Domini Dei Israël, continentur in sermonibus regum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Oratio quoque ejus et exauditio, et cuncta peccata atque contemptus, loca etiam in quibus ædificavit excelsa, et fecit lucos et statuas antequam ageret pœnitentiam, scripta sunt in sermonibus Hozai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Dormivit ergo Manasses cum patribus suis, et sepelierunt eum in domo sua: regnavitque pro eo filius ejus Amon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Viginti duorum annorum erat Amon cum regnare cœpisset, et duobus annis regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Fecitque malum in conspectu Domini, sicut fecerat Manasses pater ejus: et cunctis idolis quæ Manasses fuerat fabricatus, immolavit atque servivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Et non est reveritus faciem Domini, sicut reveritus est Manasses pater ejus, et multo majora deliquit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Cumque conjurassent adversus eum servi sui, interfecerunt eum in domo sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Porro reliqua populi multitudo, cæsis iis qui Amon percusserant, constituit regem Josiam filium ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Octo annorum erat Josias cum regnare cœpisset, et triginta et uno anno regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Fecitque quod erat rectum in conspectu Domini, et ambulavit in viis David patris sui: non declinavit neque ad dextram, neque ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Octavo autem anno regni sui, cum adhuc esset puer, cœpit quærere Deum patris sui David: et duodecimo anno postquam regnare cœperat, mundavit Judam et Jerusalem ab excelsis, et lucis, simulacrisque et sculptilibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Destruxeruntque coram eo aras Baalim, et simulacra quæ superposita fuerant, demoliti sunt: lucos etiam et sculptilia succidit atque comminuit, et super tumulos eorum qui eis immolare consueverant, fragmenta dispersit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Ossa præterea sacerdotum combussit in altaribus idolorum, mundavitque Judam et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Sed et in urbibus Manasse, et Ephraim, et Simeon, usque Nephthali, cuncta subvertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Cumque altaria dissipasset, et lucos et sculptilia contrivisset in frustra, cunctaque delubra demolitus esset de universa terra Israël, reversus est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Igitur anno octavodecimo regni sui, mundata jam terra et templo Domini, misit Saphan filium Eseliæ, et Maasiam principem civitatis, et Joha filium Joachaz a commentariis, ut instaurarent domum Domini Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Qui venerunt ad Helciam sacerdotem magnum: acceptamque ab eo pecuniam quæ illata fuerat in domum Domini, et quam congregaverant Levitæ, et janitores de Manasse, et Ephraim, et universis reliquiis Israël, ab omni quoque Juda, et Benjamin, et habitatoribus Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'tradiderunt in manibus eorum qui præerant operariis in domo Domini, ut instaurarent templum, et infirma quæque sarcirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'At illi dederunt eam artificibus et cæmentariis, ut emerent lapides de lapicidinis, et ligna ad commissuras ædificii, et ad contignationem domorum quas destruxerant reges Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Qui fideliter cuncta faciebant. Erant autem præpositi operantium Jahath et Abdias de filiis Merari, Zacharias et Mosollam de filiis Caath, qui urgebant opus: omnes Levitæ scientes organis canere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Super eos vero qui ad diversos usus onera portabant, erant scribæ, et magistri de Levitis, janitores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Cumque efferrent pecuniam quæ illata fuerat in templum Domini, reperit Helcias sacerdos librum legis Domini per manum Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Et ait ad Saphan scribam: Librum legis inveni in domo Domini: et tradidit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'At ille intulit volumen ad regem, et nuntiavit ei, dicens: Omnia quæ dedisti in manu servorum tuorum, ecce complentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Argentum quod repertum est in domo Domini, conflaverunt, datumque est præfectis artificum, et diversa opera fabricantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Præterea tradidit mihi Helcias sacerdos hunc librum. Quem cum rege præsente recitasset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'audissetque ille verba legis, scidit vestimenta sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'et præcepit Helciæ, et Ahicam filio Saphan, et Abdon filio Micha, Saphan quoque scribæ, et Asaæ servo regis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Ite, et orate Dominum pro me, et pro reliquiis Israël et Juda, super universis sermonibus libri istius, qui repertus est: magnus enim furor Domini stillavit super nos, eo quod non custodierint patres nostri verba Domini ut facerent omnia quæ scripta sunt in isto volumine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Abiit ergo Helcias, et hi qui simul a rege missi fuerant, ad Oldam prophetidem, uxorem Sellum filii Thecuath filii Hasra custodis vestium, quæ habitabat in Jerusalem in Secunda: et locuti sunt ei verba quæ supra narravimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'At illa respondit eis: Hæc dicit Dominus Deus Israël: Dicite viro qui misit vos ad me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Hæc dicit Dominus: Ecce ego inducam mala super locum istum et super habitatores ejus, cunctaque maledicta quæ scripta sunt in libro hoc, quem legerunt coram rege Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Quia dereliquerunt me, et sacrificaverunt diis alienis, ut me ad iracundiam provocarent in cunctis operibus manuum suarum, idcirco stillabit furor meus super locum istum, et non extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Ad regem autem Juda, qui misit vos pro Domino deprecando, sic loquimini: Hæc dicit Dominus Deus Israël: Quoniam audisti verba voluminis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'atque emollitum est cor tuum, et humiliatus es in conspectu Dei super his quæ dicta sunt contra locum hunc et habitatores Jerusalem, reveritusque faciem meam scidisti vestimenta tua, et flevisti coram me: ego quoque exaudivi te, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Jam enim colligam te ad patres tuos, et infereris in sepulchrum tuum in pace: nec videbunt oculi tui omne malum quod ego inducturus sum super locum istum, et super habitatores ejus. Retulerunt itaque regi cuncta quæ dixerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'At ille convocatis universis majoribus natu Juda et Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'ascendit in domum Domini, unaque omnes viri Juda et habitatores Jerusalem, sacerdotes et Levitæ, et cunctus populus a minimo usque ad maximum. Quibus audientibus in domo Domini, legit rex omnia verba voluminis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'et stans in tribunali suo, percussit fœdus coram Domino ut ambularet post eum, et custodiret præcepta, et testimonia, et justificationes ejus in toto corde suo, et in tota anima sua, faceretque quæ scripta sunt in volumine illo, quod legerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Adjuravit quoque super hoc omnes qui reperti fuerant in Jerusalem et Benjamin: et fecerunt habitatores Jerusalem juxta pactum Domini Dei patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Abstulit ergo Josias cunctas abominationes de universis regionibus filiorum Israël: et fecit omnes qui residui erant in Israël, servire Domino Deo suo. Cunctis diebus ejus non recesserunt a Domino Deo patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Fecit autem Josias in Jerusalem Phase Domino, quod immolatum est quartadecima die mensis primi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'et constituit sacerdotes in officiis suis, hortatusque est eos ut ministrarent in domo Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Levitis quoque, ad quorum eruditionem omnis Israël sanctificabatur Domino, locutus est: Ponite arcam in sanctuario templi, quod ædificavit Salomon filius David rex Israël, nequaquam enim eam ultra portabitis: nunc autem ministrate Domino Deo vestro, et populo ejus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Et præparate vos per domos et cognationes vestras in divisionibus singulorum, sicut præcepit David rex Israël, et descripsit Salomon filius ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Et ministrate in sanctuario per familias turmasque Leviticas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'et sanctificati immolate Phase: fratres etiam vestros, ut possint juxta verba quæ locutus est Dominus in manu Moysi facere, præparate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Dedit præterea Josias omni populo qui ibi fuerat inventus in solemnitate Phase, agnos et hædos de gregibus et reliqui pecoris triginta millia, boum quoque tria millia: hæc de regis universa substantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Duces quoque ejus sponte quod voverant, obtulerunt, tam populo quam sacerdotibus et Levitis. Porro Helcias, et Zacharias, et Jahiel principes domus Domini dederunt sacerdotibus ad faciendum Phase pecora commixtim duo millia sexcenta, et boves trecentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Chonenias autem, et Semeias, etiam Nathanaël fratres ejus, necnon Hasabias, et Jehiel, et Jozabad principes Levitarum, dederunt ceteris Levitis ad celebrandum Phase quinque millia pecorum, et boves quingentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Præparatumque est ministerium, et steterunt sacerdotes in officio suo: Levitæ quoque in turmis, juxta regis imperium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Et immolatum est Phase: asperseruntque sacerdotes manu sua sanguinem, et Levitæ detraxerunt pelles holocaustorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'et separaverunt ea ut darent per domos et familias singulorum, et offerrentur Domino, sicut scriptum est in libro Moysi: de bobus quoque fecerunt similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et assaverunt Phase super ignem, juxta quod in lege scriptum est: pacificas vero hostias coxerunt in lebetibus, et cacabis, et ollis, et festinato distribuerunt universæ plebi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'sibi autem et sacerdotibus postea paraverunt, nam in oblatione holocaustorum et adipum usque ad noctem sacerdotes fuerunt occupati, unde Levitæ sibi et sacerdotibus filiis Aaron paraverunt novissimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Porro cantores filii Asaph stabant in ordine suo, juxta præceptum David, et Asaph, et Heman, et Idithun prophetarum regis: janitores vero per portas singulas observabant, ita ut nec puncto quidem discederent a ministerio: quam ob rem et fratres eorum Levitæ paraverunt eis cibos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Omnis igitur cultura Domini rite completa est in die illa, ut facerent Phase, et offerrent holocausta super altare Domini, juxta præceptum regis Josiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Feceruntque filii Israël, qui reperti fuerant ibi, Phase in tempore illo, et solemnitatem azymorum septem diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Non fuit Phase simile huic in Israël a diebus Samuelis prophetæ: sed nec quisquam de cunctis regibus Israël fecit Phase sicut Josias, sacerdotibus, et Levitis, et omni Judæ et Israël qui repertus fuerat, et habitantibus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Octavodecimo anno regni Josiæ hoc Phase celebratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Postquam instauraverat Josias templum, ascendit Nechao rex \'gypti ad pugnandum in Charcamis juxta Euphraten: et processit in occursum ejus Josias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'At ille, missis ad eum nuntiis, ait: Quid mihi et tibi est, rex Juda? non adversum te hodie venio, sed contra aliam pugno domum, ad quam me Deus festinato ire præcepit: desine adversum Deum facere, qui mecum est, ne interficiat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Noluit Josias reverti, sed præparavit contra eum bellum, nec acquievit sermonibus Nechao ex ore Dei: verum perrexit ut dimicaret in campo Mageddo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Ibique vulneratus a sagittariis, dixit pueris suis: Educite me de prælio, quia oppido vulneratus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Qui transtulerunt eum de curru in alterum currum, qui sequebatur eum more regio, et asportaverunt eum in Jerusalem: mortuusque est, et sepultus in mausoleo patrum suorum, et universus Juda et Jerusalem luxerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremias maxime: cujus omnes cantores atque cantatrices, usque in præsentem diem, lamentationes super Josiam replicant, et quasi lex obtinuit in Israël: Ecce scriptum fertur in lamentationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Reliqua autem sermonum Josiæ, et misericordiarum ejus, quæ lege præcepta sunt Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'opera quoque illius prima et novissima, scripta sunt in libro regum Juda et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tulit ergo populus terræ Joachaz filium Josiæ, et constituit regem pro patre suo in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Viginti trium annorum erat Joachaz cum regnare cœpisset, et tribus mensibus regnavit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Amovit autem eum rex \'gypti cum venisset in Jerusalem, et condemnavit terram centum talentis argenti, et talento auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Constituitque pro eo regem Eliakim fratrem ejus super Judam et Jerusalem, et vertit nomen ejus Joakim: ipsum vero Joachaz tulit secum, et abduxit in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Viginti quinque annorum erat Joakim cum regnare cœpisset, et undecim annis regnavit in Jerusalem: fecitque malum coram Domino Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Contra hunc ascendit Nabuchodonosor rex Chaldæorum, et vinctum catenis duxit in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Ad quam et vasa Domini transtulit, et posuit ea in templo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Reliqua autem verborum Joakim, et abominationum ejus quas operatus est, et quæ inventa sunt in eo, continentur in libro regum Juda et Israël. Regnavit autem Joachin filius ejus pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Octo annorum erat Joachin cum regnare cœpisset, et tribus mensibus ac decem diebus regnavit in Jerusalem: fecitque malum in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Cumque anni circulus volveretur, misit Nabuchodonosor rex, qui adduxerunt eum in Babylonem, asportatis simul pretiosissimis vasis domus Domini. Regem vero constituit Sedeciam patruum ejus super Judam et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Viginti et unius anni erat Sedecias cum regnare cœpisset, et undecim annis regnavit in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'fecitque malum in oculis Domini Dei sui, nec erubuit faciem Jeremiæ prophetæ, loquentis ad se ex ore Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'A rege quoque Nabuchodonosor recessit, qui adjuraverat eum per Deum: et induravit cervicem suam et cor ut non reverteretur ad Dominum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Sed et universi principes sacerdotum et populus prævaricati sunt inique juxta universas abominationes gentium, et polluerunt domum Domini quam sanctificaverat sibi in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Mittebat autem Dominus Deus patrum suorum ad illos per manum nuntiorum suorum de nocte consurgens, et quotidie commonens: eo quod parceret populo et habitaculo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'At illi subsannabant nuntios Dei, et parvipendebant sermones ejus, illudebantque prophetis, donec ascenderet furor Domini in populum ejus, et esset nulla curatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Adduxit enim super eos regem Chaldæorum, et interfecit juvenes eorum gladio in domo sanctuarii sui: non est misertus adolescentis, et virginis, et senis, nec decrepiti quidem, sed omnes tradidit in manibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Universaque vasa domus Domini, tam majora quam minora, et thesauros templi, et regis, et principum, transtulit in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Incenderunt hostes domum Dei, destruxeruntque murum Jerusalem: universas turres combusserunt, et quidquid pretiosum fuerat, demoliti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Si quis evaserat gladium, ductus in Babylonem servivit regi et filiis ejus, donec imperaret rex Persarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'et compleretur sermo Domini ex ore Jeremiæ, et celebraret terra sabbata sua: cunctis enim diebus desolationis egit sabbatum usque dum complerentur septuaginta anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Anno autem primo Cyri regis Persarum, ad explendum sermonem Domini quem locutus fuerat per os Jeremiæ, suscitavit Dominus spiritum Cyri regis Persarum: qui jussit prædicari in universo regno suo, etiam per scripturam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Hæc dicit Cyrus rex Persarum: Omnia regna terræ dedit mihi Dominus Deus cæli, et ipse præcepit mihi ut ædificarem ei domum in Jerusalem, quæ est in Judæa: quis ex vobis est in omni populo ejus? sit Dominus Deus suus cum eo, et ascendat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'In anno primo Cyri regis Persarum, ut compleretur verbum Domini ex ore Jeremiæ, suscitavit Dominus spiritum Cyri regis Persarum: et traduxit vocem in omni regno suo, etiam per scripturam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Hæc dicit Cyrus rex Persarum: Omnia regna terræ dedit mihi Dominus Deus cæli, et ipse præcepit mihi ut ædificarem ei domum in Jerusalem, quæ est in Judæa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Quis est in vobis de universo populo ejus? Sit Deus illius cum ipso. Ascendat in Jerusalem, quæ est in Judæa, et ædificet domum Domini Dei Israël: ipse est Deus qui est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Et omnes reliqui in cunctis locis ubicumque habitant, adjuvent eum viri de loco suo argento et auro, et substantia, et pecoribus, excepto quod voluntarie offerunt templo Dei, quod est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Et surrexerunt principes patrum de Juda et Benjamin, et sacerdotes, et Levitæ, et omnis cujus Deus suscitavit spiritum, ut ascenderent ad ædificandum templum Domini, quod erat in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Universique qui erant in circuitu, adjuverunt manus eorum in vasis argenteis et aureis, in substantia et jumentis, in supellectili, exceptis his quæ sponte obtulerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Rex quoque Cyrus protulit vasa templi Domini, quæ tulerat Nabuchodonosor de Jerusalem, et posuerat ea in templo dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Protulit autem ea Cyrus rex Persarum per manum Mithridatis filii Gazabar, et annumeravit ea Sassabasar principi Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Et hic est numerus eorum: phialæ aureæ triginta, phialæ argenteæ mille, cultri viginti novem, scyphi aurei triginta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'scyphi argentei secundi quadringenti decem, vasa alia mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Omnia vasa aurea et argentea quinque millia quadringenta: universa tulit Sassabasar cum his qui ascendebant de transmigratione Babylonis in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Hi sunt autem provinciæ filii, qui ascenderunt de captivitate, quam transtulerat Nabuchodonosor rex Babylonis in Babylonem, et reversi sunt in Jerusalem et Judam, unusquisque in civitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Qui venerunt cum Zorobabel, Josue, Nehemia, Saraia, Rahelaia, Mardochai, Belsan, Mesphar, Beguai, Rehum, Baana. Numerus virorum populi Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'filii Pharos duo millia centum septuaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Filii Sephatia, trecenti septuaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Filii Area, septingenti septuaginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Filii Phahath Moab, filiorum Josue: Joab, duo millia octingenti duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Filii \'lam, mille ducenti quinquaginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Filii Zethua, nongenti quadraginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Filii Zachai, septingenti sexaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Filii Bani, sexcenti quadraginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Filii Bebai, sexcenti viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Filii Azgad, mille ducenti viginti duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Filii Adonicam, sexcenti sexaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Filii Beguai, duo millia quinquaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Filii Adin, quadringenti quinquaginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Filii Ather, qui erant ex Ezechia, nonaginta octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Filii Besai, trecenti viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Filii Jora, centum duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Filii Hasum, ducenti viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Filii Gebbar, nonaginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Filii Bethlehem, centum viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Viri Netupha, quinquaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Viri Anathoth, centum viginti octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Filii Azmaveth, quadraginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Filii Cariathiarim, Cephira et Beroth, septingenti quadraginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Filii Rama et Gabaa, sexcenti viginti unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Viri Machmas, centum viginti duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Viri Bethel et Hai, ducenti viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Filii Nebo, quinquaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Filii Megbis, centum quinquaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Filii \'lam alterius, mille ducenti quinquaginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Filii Harim, trecenti viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Filii Lod Hadid, et Ono, septingenti viginti quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Filii Jericho, trecenti quadraginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Filii Senaa, tria millia sexcenti triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Sacerdotes: filii Jadaia in domo Josue, nongenti septuaginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Filii Emmer, mille quinquaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Filii Pheshur, mille ducenti quadraginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Filii Harim, mille decem et septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Levitæ: filii Josue et Cedmihel filiorum Odoviæ, septuaginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Cantores: filii Asaph, centum viginti octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Filii janitorum: filii Sellum, filii Ater, filii Telmon, filii Accub, filii Hatitha, filii Sobai: universi centum triginta novem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Nathinæi: filii Siha, filii Hasupha, filii Tabbaoth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'filii Ceros, filii Siaa, filii Phadon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'filii Lebana, filii Hagaba, filii Accub,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'filii Hagab, filii Semlai, filii Hanan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'filii Gaddel, filii Gaher, filii Raaia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'filii Rasin, filii Necoda, filii Gazam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'filii Aza, filii Phasea, filii Besee,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'filii Asena, filii Munim, filii Nephusim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'filii Bacbuc, filii Hacupha, filii Harhur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'filii Besluth, filii Mahida, filii Harsa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'filii Bercos, filii Sisara, filii Thema,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'filii Nasia, filii Hatipha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'filii servorum Salomonis, filii Sotai, filii Sophereth, filii Pharuda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'filii Jala, filii Dercon, filii Geddel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'filii Saphatia, filii Hatil, filii Phochereth, qui erant de Asebaim, filii Ami:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'omnes Nathinæi, et filii servorum Salomonis, trecenti nonaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Et hi qui ascenderunt de Thelmala, Thelharsa, Cherub, et Adon, et Emer: et non potuerunt indicare domum patrum suorum et semen suum, utrum ex Israël essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Filii Dalaia, filii Tobia, filii Necoda, sexcenti quinquaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Et de filiis sacerdotum: filii Hobia, filii Accos, filii Berzellai, qui accepit de filiabus Berzellai Galaaditis, uxorem, et vocatus est nomine eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'hi quæsierunt scripturam genealogiæ suæ, et non invenerunt, et ejecti sunt de sacerdotio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Et dixit Athersatha eis ut non comederent de Sancto sanctorum, donec surgeret sacerdos doctus atque perfectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Omnis multitudo quasi unus, quadraginta duo millia trecenti sexaginta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'exceptis servis eorum, et ancillis, qui erant septem millia trecenti triginta septem: et in ipsis cantores atque cantatrices ducenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Equi eorum septingenti triginta sex, muli eorum, ducenti quadraginta quinque,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'cameli eorum, quadringenti triginta quinque, asini eorum, sex millia septingenti viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Et de principibus patrum, cum ingrederentur templum Domini, quod est in Jerusalem, sponte obtulerunt in domum Dei ad exstruendam eam in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Secundum vires suas dederunt impensas operis, auri solidos sexaginta millia et mille, argenti mnas quinque millia, et vestes sacerdotales centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Habitaverunt ergo sacerdotes, et Levitæ, et de populo, et cantores, et janitores, et Nathinæi, in urbibus suis, universusque Israël in civitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Jamque venerat mensis septimus, et erant filii Israël in civitatibus suis: congregatus est ergo populus quasi vir unus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Et surrexit Josue filius Josedec, et fratres ejus sacerdotes, et Zorobabel filius Salathiel, et fratres ejus, et ædificaverunt altare Dei Israël ut offerrent in eo holocautomata, sicut scriptum est in lege Moysi viri Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Collocaverunt autem altare Dei super bases suas, deterrentibus eos per circuitum populis terrarum: et obtulerunt super illud holocaustum Domino mane et vespere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Feceruntque solemnitatem tabernaculorum, sicut scriptum est, et holocaustum diebus singulis per ordinem secundum præceptum opus diei in die suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Et post hæc holocaustum juge, tam in calendis quam in universis solemnitatibus Domini quæ erant consecratæ, et in omnibus in quibus ultro offerebatur munus Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'A primo die mensis septimi cœperunt offerre holocaustum Domino: porro templum Dei nondum fundatum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Dederunt autem pecunias latomis et cæmentariis: cibum quoque, et potum, et oleum Sidoniis Tyriisque, ut deferrent ligna cedrina de Libano ad mare Joppe, juxta quod præceperat Cyrus rex Persarum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Anno autem secundo adventus eorum ad templum Dei in Jerusalem, mense secundo, cœperunt Zorobabel filius Salathiel, et Josue filius Josedec, et reliqui de fratribus eorum sacerdotes, et Levitæ, et omnes qui venerant de captivitate in Jerusalem, et constituerunt Levitas a viginti annis et supra, ut urgerent opus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Stetitque Josue et filii ejus et fratres ejus, Cedmihel et filii ejus, et filii Juda, quasi vir unus, ut instarent super eos qui faciebant opus in templo Dei: filii Henadad, et filii eorum, et fratres eorum Levitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Fundato igitur a cæmentariis templo Domini, steterunt sacerdotes in ornatu suo cum tubis, et Levitæ filii Asaph in cymbalis, ut laudarent Deum per manus David regis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Et concinebant in hymnis, et confessione Domino: Quoniam bonus, quoniam in æternum misericordia ejus super Israël. Omnis quoque populus vociferabatur clamore magno in laudando Dominum, eo quod fundatum esset templum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Plurimi etiam de sacerdotibus et Levitis, et principes patrum, et seniores, qui viderant templum prius cum fundatum esset, et hoc templum, in oculis eorum, flebant voce magna: et multi vociferantes in lætitia, elevabant vocem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Nec poterat quisquam agnoscere vocem clamoris lætantium, et vocem fletus populi: commistim enim populus vociferabatur clamore magno, et vox audiebatur procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Audierunt autem hostes Judæ et Benjamin, quia filii captivitatis ædificarent templum Domino Deo Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'et accedentes ad Zorobabel, et ad principes patrum, dixerunt eis: \'dificemus vobiscum, quia ita ut vos, quærimus Deum vestrum: ecce nos immolavimus victimas a diebus Asor Haddan regis Assur, qui adduxit nos huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Et dixit eis Zorobabel, et Josue, et reliqui principes patrum Israël: Non est vobis et nobis ut ædificemus domum Deo nostro, sed nos ipsi soli ædificabimus Domino Deo nostro, sicut præcepit nobis Cyrus rex Persarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Factum est igitur ut populus terræ impediret manus populi Judæ, et turbaret eos in ædificando.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Conduxerunt autem adversus eos consiliatores, ut destruerent consilium eorum omnibus diebus Cyri regis Persarum, et usque ad regnum Darii regis Persarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'In regno autem Assueri, in principio regni ejus, scripserunt accusationem adversus habitatores Judæ et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Et in diebus Artaxerxis scripsit Beselam, Mithridates, et Thabeel, et reliqui qui erant in consilio eorum, ad Artaxerxem regem Persarum: epistola autem accusationis scripta erat syriace, et legebatur sermone syro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Reum Beelteem, et Samsai scriba, scripserunt epistolam unam de Jerusalem Artaxerxi regi, hujuscemodi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Reum Beelteem, et Samsai scriba, et reliqui consiliatores eorum, Dinæi, et Apharsathachæi, Terphalæi, Apharsæi, Erchuæi, Babylonii, Susanechæi, Dievi, et \'lamitæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'et ceteri de gentibus, quas transtulit Asenaphar magnus et gloriosus, et habitare eas fecit in civitatibus Samariæ, et in reliquis regionibus trans flumen in pace');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, '(hoc est exemplar epistolæ, quam miserunt ad eum), Artaxerxi regi, servi tui, viri qui sunt trans fluvium, salutem dicunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Notum sit regi quia Judæi, qui ascenderunt a te ad nos, venerunt in Jerusalem civitatem rebellem et pessimam, quam ædificant exstruentes muros ejus, et parietes componentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Nunc igitur notum sit regi, quia si civitas illa ædificata fuerit, et muri ejus instaurati, tributum, et vectigal, et annuos reditus non dabunt, et usque ad reges hæc noxa perveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Nos autem memores salis, quod in palatio comedimus, et quia læsiones regis videre nefas ducimus, idcirco misimus et nuntiavimus regi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'ut recenseas in libris historiarum patrum tuorum, et invenies scriptum in commentariis: et scies quoniam urbs illa, urbs rebellis est, et nocens regibus et provinciis, et bella concitantur in ea ex diebus antiquis: quam ob rem et civitas ipsa destructa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nuntiamus nos regi, quoniam si civitas illa ædificata fuerit, et muri ipsius instaurati, possessionem trans fluvium non habebis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Verbum misit rex ad Reum Beelteem, et Samsai scribam, et ad reliquos, qui erant in consilio eorum habitatores Samariæ, et ceteris trans fluvium, salutem dicens et pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Accusatio, quam misistis ad nos, manifeste lecta est coram me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'et a me præceptum est: et recensuerunt, inveneruntque quoniam civitas illa a diebus antiquis adversum reges rebellat, et seditiones, et prælia concitantur in ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'nam et reges fortissimi fuerunt in Jerusalem, qui et dominati sunt omni regioni quæ trans fluvium est: tributum quoque et vectigal, et reditus accipiebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Nunc ergo audite sententiam: prohibeatis viros illos, ut urbs illa non ædificetur donec si forte a me jussum fuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Videte ne negligenter hoc impleatis, et paulatim crescat malum contra reges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Itaque exemplum edicti Artaxerxis regis lectum est coram Reum Beelteem, et Samsai scriba, et consiliariis eorum: et abierunt festini in Jerusalem ad Judæos, et prohibuerunt eos in brachio et robore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Tunc intermissum est opus domus Domini in Jerusalem, et non fiebat usque ad annum secundum regni Darii regis Persarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Prophetaverunt autem Aggæus propheta, et Zacharias filius Addo, prophetantes ad Judæos qui erant in Judæa et Jerusalem, in nomine Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tunc surrexerunt Zorobabel filius Salathiel, et Josue filius Josedec, et cœperunt ædificare templum Dei in Jerusalem, et cum eis prophetæ Dei adjuvantes eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'In ipso autem tempore venit ad eos Thathanai, qui erat dux trans flumen, et Stharbuzanai, et consiliarii eorum: sicque dixerunt eis: Quis dedit vobis consilium ut domum hanc ædificaretis, et muros ejus instauraretis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Ad quod respondimus eis, quæ essent nomina hominum auctorum ædificationis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Oculus autem Dei eorum factus est super senes Judæorum, et non potuerunt inhibere eos. Placuitque ut res ad Darium referretur, et tunc satisfacerent adversus accusationem illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Exemplar epistolæ, quam misit Thathanai dux regionis trans flumen, et Stharbuzanai, et consiliatores ejus Arphasachæi, qui erant trans flumen, ad Darium regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Sermo, quem miserant ei, sic scriptus erat: Dario regi pax omnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Notum sit regi, isse nos ad Judæam provinciam, ad domum Dei magni, quæ ædificatur lapide impolito, et ligna ponuntur in parietibus: opusque illud diligenter exstruitur, et crescit in manibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Interrogavimus ergo senes illos, et ita diximus eis: Quis dedit vobis potestatem ut domum hanc ædificaretis, et muros hos instauraretis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Sed et nomina eorum quæsivimus ab eis, ut nuntiaremus tibi: scripsimusque nomina eorum virorum, qui sunt principes in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Hujuscemodi autem sermonem responderunt nobis dicentes: Nos sumus servi Dei cæli et terræ, et ædificamus templum, quod erat exstructum ante hos annos multos, quodque rex Israël magnus ædificaverat, et exstruxerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Postquam autem ad iracundiam provocaverunt patres nostri Deum cæli, tradidit eos in manus Nabuchodonosor regis Babylonis Chaldæi, domum quoque hanc destruxit, et populum ejus transtulit in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Anno autem primo Cyri regis Babylonis, Cyrus rex proposuit edictum ut domus Dei hæc ædificaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Nam et vasa templi Dei aurea et argentea, quæ Nabuchodonosor tulerat de templo, quod erat in Jerusalem, et asportaverat ea in templum Babylonis, protulit Cyrus rex de templo Babylonis, et data sunt Sassabasar vocabulo, quem et principem constituit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'dixitque ei: Hæc vasa tolle, et vade, et pone ea in templo, quod est in Jerusalem, et domus Dei ædificetur in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tunc itaque Sassabasar ille venit et posuit fundamenta templi Dei in Jerusalem, et ex eo tempore usque nunc ædificatur, et necdum completum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Nunc ergo si videtur regi bonum, recenseat in bibliotheca regis, quæ est in Babylone, utrumnam a Cyro rege jussum fuerit ut ædificaretur domus Dei in Jerusalem, et voluntatem regis super hac re mittat ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tunc Darius rex præcepit: et recensuerunt in bibliotheca librorum, qui erant repositi in Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Et inventum est in Ecbatanis, quod est castrum in Medena provincia, volumen unum: talisque scriptus erat in eo commentarius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Anno primo Cyri regis, Cyrus rex decrevit ut domus Dei ædificaretur, quæ est in Jerusalem, in loco ubi immolent hostias, et ut ponant fundamenta supportantia altitudinem cubitorum sexaginta, et latitudinem cubitorum sexaginta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'ordines de lapidibus impolitis tres, et sic ordines de lignis novis: sumptus autem de domo regis dabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Sed et vasa templi Dei aurea et argentea, quæ Nabuchodonosor tulerat de templo Jerusalem, et attulerat ea in Babylonem, reddantur, et referantur in templum in Jerusalem in locum suum, quæ et posita sunt in templo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Nunc ergo Thathanai dux regionis, quæ est trans flumen, Stharbuzanai, et consiliarii vestri Apharsachæi, qui estis trans flumen, procul recedite ab illis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'et dimittite fieri templum Dei illud a duce Judæorum, et a senioribus eorum, ut domum Dei illam ædificent in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Sed et a me præceptum est quid oporteat fieri a presbyteris Judæorum illis ut ædificetur domus Dei, scilicet ut de arca regis, id est, de tributis quæ dantur de regione trans flumen, studiose sumptus dentur viris illis, ne impediatur opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Quod si necesse fuerit, et vitulos, et agnos, et hædos in holocaustum Deo cæli, frumentum, sal, vinum, et oleum, secundum ritum sacerdotum, qui sunt in Jerusalem, detur eis per singulos dies, ne sit in aliquo querimonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Et offerant oblationes Deo cæli, orentque pro vita regis, et filiorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'A me ergo positum est decretum: ut omnis homo qui hanc mutaverit jussionem, tollatur lignum de domum ipsius, et erigatur, et configatur in eo, domus autem ejus publicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Deus autem, qui habitare fecit nomen suum ibi, dissipet omnia regna, et populum qui extenderit manum suam ut repugnet, et dissipet domum Dei illam, quæ est in Jerusalem. Ego Darius statui decretum, quod studiose impleri volo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Igitur Thathanai dux regionis trans flumen, et Stharbuzanai, et consiliarii ejus, secundum quod præceperat Darius rex, sic diligenter executi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Seniores autem Judæorum ædificabant, et prosperabantur juxta prophetiam Aggæi prophetæ, et Zachariæ filii Addo: et ædificaverunt et construxerunt, jubente Deo Israël, et jubente Cyro, et Dario, et Artaxerxe regibus Persarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'et compleverunt domum Dei istam, usque ad diem tertium mensis Adar, qui est annus sextus regni Darii regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Fecerunt autem filii Israël sacerdotes et Levitæ, et reliqui filiorum transmigrationis, dedicationem domus Dei in gaudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Et obtulerunt in dedicationem domus Dei, vitulos centum, arietes ducentos, agnos quadringentos, hircos caprarum pro peccato totius Israël duodecim, juxta numerum tribuum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Et statuerunt sacerdotes in ordinibus suis, et Levitas in vicibus suis, super opera Dei in Jerusalem, sicut scriptum est in libro Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Fecerunt autem filii Israël transmigrationis Pascha, quartadecima die mensis primi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Purificati enim fuerant sacerdotes et Levitæ quasi unus: omnes mundi ad immolandum Pascha universis filiis transmigrationis, et fratribus suis sacerdotibus, et sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Et comederunt filii Israël, qui reversi fuerant de transmigratione, et omnes qui se separaverant a coinquinatione gentium terræ ad eos, ut quærerent Dominum Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Et fecerunt solemnitatem azymorum septem diebus in lætitia, quoniam lætificaverat eos Dominus, et converterat cor regis Assur ad eos, ut adjuvaret manus eorum in opere domus Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Post hæc autem verba in regno Artaxerxis regis Persarum, Esdras filius Saraiæ, filii Azariæ, filii Helciæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'filii Sellum, filii Sadoc, filii Achitob,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'filii Amariæ, filii Azariæ, filii Maraioth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'filii Zarahiæ, filii Ozi, filii Bocci,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'filii Abisue, filii Phinees, filii Eleazar, filii Aaron sacerdotis ab initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Ipse Esdras ascendit de Babylone, et ipse scriba velox in lege Moysi, quam Dominus Deus dedit Israël: et dedit ei rex secundum manum Domini Dei ejus super eum, omnem petitionem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Et ascenderunt de filiis Israël, et de filiis sacerdotum, et de filiis Levitarum, et de cantoribus, et de janitoribus, et de Nathinæis, in Jerusalem, anno septimo Artaxerxis regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Et venerunt in Jerusalem mense quinto, ipse est annus septimus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Quia in primo die mensis primi cœpit ascendere de Babylone, et in primo die mensis quinti venit in Jerusalem, juxta manum Dei sui bonam super se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Esdras enim paravit cor suum, ut investigaret legem Domini, et faceret et doceret in Israël præceptum et judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Hoc est autem exemplar epistolæ edicti, quod dedit rex Artaxerxes Esdræ sacerdoti, scribæ erudito in sermonibus et præceptis Domini, et cæremoniis ejus in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxes rex regum Esdræ sacerdoti scribæ legis Dei cæli doctissimo, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'A me decretum est, ut cuicumque placuerit in regno meo de populo Israël, et de sacerdotibus ejus, et de Levitis, ire in Jerusalem, tecum vadat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'A facie enim regis, et septem consiliatorum ejus, missus es, ut visites Judæam et Jerusalem in lege Dei tui, quæ est in manu tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'et ut feras argentum et aurum quod rex, et consiliatores ejus, sponte obtulerunt Deo Israël, cujus in Jerusalem tabernaculum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Et omne argentum et aurum quodcumque inveneris in universa provincia Babylonis, et populus offerre voluerit, et de sacerdotibus quæ sponte obtulerint domui Dei sui, quæ est in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'libere accipe, et studiose eme de hac pecunia vitulos, arietes, agnos, et sacrificia, et libamina eorum, et offer ea super altare templi Dei vestri, quod est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Sed et si quid tibi et fratribus tuis placuerit de reliquo argento et auro ut faciatis, juxta voluntatem Dei vestri facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Vasa quoque, quæ dantur tibi in ministerium domus Dei tui, trade in conspectu Dei in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Sed et cetera, quibus opus fuerit in domum Dei tui, quantumcumque necesse est ut expendas, dabitur de thesauro, et de fisco regis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'et a me. Ego Artaxerxes rex, statui atque decrevi omnibus custodibus arcæ publicæ, qui sunt trans flumen, ut quodcumque petierit a vobis Esdras sacerdos, scriba legis Dei cæli, absque mora detis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'usque ad argenti talenta centum, et usque ad frumenti coros centum, et usque ad vini batos centum, et usque ad batos olei centum, sal vero absque mensura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Omne quod ad ritum Dei cæli pertinet, tribuatur diligenter in domo Dei cæli: ne forte irascatur contra regnum regis, et filiorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Vobis quoque notum facimus de universis sacerdotibus, et Levitis, et cantoribus, et janitoribus, Nathinæis, et ministris domus Dei hujus, ut vectigal, et tributum, et annonas non habeatis potestatem imponendi super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Tu autem Esdra, secundum sapientiam Dei tui, quæ est in manu tua, constitue judices et præsides, ut judicent omni populo qui est trans flumen, his videlicet qui noverunt legem Dei tui: sed et imperitos docete libere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Et omnis qui non fecerit legem Dei tui, et legem regis, diligenter, judicium erit de eo sive in mortem, sive in exilium, sive in condemnationem substantiæ ejus, vel certe in carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Benedictus Dominus Deus patrum nostrorum, qui dedit hoc in corde regis ut glorificaret domum Domini quæ est in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'et in me inclinavit misericordiam suam coram rege et consiliatoribus ejus, et universis principibus regis potentibus: et ego confortatus manu Domini Dei mei, quæ erat in me, congregavi de Israël principes qui ascenderent mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Hi sunt ergo principes familiarum, et genealogia eorum, qui ascenderunt mecum in regno Artaxerxis regis de Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'De filiis Phinees, Gersom. De filiis Ithamar, Daniel. De filiis David, Hattus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'De filiis Secheniæ, filiis Pharos, Zacharias: et cum eo numerati sunt viri centum quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'De filiis Phahath Moab, Elioënai filius Zarehe, et cum eo ducenti viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'De filiis Secheniæ, filius Ezechiel, et cum eo trecenti viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'De filiis Adan, Abed filius Jonathan, et cum eo quinquaginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'De filiis Alam, Isaias filius Athaliæ, et cum eo septuaginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'De filiis Saphatiæ, Zebedia filius Michaël, et cum eo octoginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'De filiis Joab, Obedia filius Jahiel, et cum eo ducenti decem et octo viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'De filiis Selomith, filius Josphiæ, et cum eo centum sexaginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'De filiis Bebai, Zacharias filius Bebai, et cum eo viginti octo viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'De filiis Azgad, Johanan filius Eccetan, et cum eo centum et decem viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'De filiis Adonicam, qui erant novissimi: et hæc nomina eorum: Elipheleth, et Jehiel, et Samaias, et cum eis sexaginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'De filii Begui, Uthai et Zachur, et cum eis septuaginta viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Congregavi autem eos ad fluvium qui decurrit ad Ahava, et mansimus ibi tribus diebus: quæsivique in populo et in sacerdotibus de filiis Levi, et non inveni ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Itaque misi Eliezer, et Ariel, et Semeiam, et Elnathan, et Jarib, et alterum Elnathan, et Nathan, et Zachariam, et Mosollam principes: et Jojarib, et Elnathan sapientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Et misi eos ad Eddo, qui est primus in Chasphiæ loco, et posui in ore eorum verba, quæ loquerentur ad Eddo, et fratres ejus Nathinæos in loco Chasphiæ, ut adducerent nobis ministros domus Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Et adduxerunt nobis per manum Dei nostri bonam super nos, virum doctissimum de filiis Moholi filii Levi, filii Israël, et Sarabiam et filios ejus et fratres ejus decem et octo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'et Hasabiam, et cum eo Isaiam de filiis Merari, fratresque ejus, et filios ejus viginti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'et de Nathinæis, quos dederat David et principes ad ministeria Levitarum, Nathinæos ducentos viginti: omnes hi suis nominibus vocabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Et prædicavi ibi jejunium juxta fluvium Ahava, ut affligeremur coram Domino Deo nostro, et peteremus ab eo viam rectam nobis et filiis nostris, universæque substantiæ nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Erubui enim petere a rege auxilium et equites, qui defenderent nos ab inimico in via: quia dixeramus regi: Manus Dei nostri est super omnes qui quærunt eum in bonitate: et imperium ejus, et fortitudo ejus, et furor, super omnes qui derelinquunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Jejunavimus autem, et rogavimus Deum nostrum per hoc: et evenit nobis prospere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Et separavi de principibus sacerdotum duodecim, Sarabiam, et Hasabiam, et cum eis de fratribus eorum decem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'appendique eis argentum et aurum, et vasa consecrata domus Dei nostri, quæ obtulerat rex et consiliatores ejus, et principes ejus, universusque Israël eorum qui inventi fuerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'et appendi in manibus eorum argenti talenta sexcenta quinquaginta, et vasa argentea centum, auri centum talenta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'et crateres aureos viginti, qui habebant solidos millenos, et vasa æris fulgentis optimi duo, pulchra ut aurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Et dixi eis: Vos sancti Domini, et vasa sancta, et argentum et aurum, quod sponte oblatum est Domino Deo patrum nostrorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'vigilate et custodite, donec appendatis coram principibus sacerdotum, et Levitarum, et ducibus familiarum Israël in Jerusalem, in thesaurum domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Susceperunt autem sacerdotes et Levitæ pondus argenti, et auri, et vasorum, ut deferrent Jerusalem in domum Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Promovimus ergo a flumine Ahava duodecimo die mensis primi ut pergeremus Jerusalem: et manus Dei nostri fuit super nos, et liberavit nos de manu inimici et insidiatoris in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Et venimus Jerusalem, et mansimus ibi tribus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Die autem quarta appensum est argentum, et aurum, et vasa in domo Dei nostri per manum Meremoth filii Uriæ sacerdotis, et cum eo Eleazar filius Phinees, cumque eis Jozabed filius Josue, et Noadaia filius Bennoi Levitæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'juxta numerum et pondus omnium: descriptumque est omne pondus in tempore illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Sed et qui venerant de captivitate filii transmigrationis, obtulerunt holocautomata Deo Israël, vitulos duodecim pro omni populo Israël, arietes nonaginta sex, agnos septuaginta septem, hircos pro peccato duodecim: omnia in holocaustum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Dederunt autem edicta regis satrapis qui erant de conspectu regis, et ducibus trans flumen, et elevaverunt populum et domum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Postquam autem hæc completa sunt, accesserunt ad me principes, dicentes: Non est separatus populus Israël, sacerdotes et Levitæ, a populis terrarum et abominationibus eorum: Chananæi videlicet, et Hethæi, et Pherezæi, et Jebusæi, et Ammonitarum, et Moabitarum, et \'gyptiorum, et Amorrhæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'tulerunt enim de filiabus eorum sibi et filiis suis, et commiscuerunt semen sanctum cum populis terrarum: manus etiam principum et magistratuum fuit in transgressione hac prima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Cumque audissem sermonem istum, scidi pallium meum et tunicam, et evelli capillos capitis mei et barbæ, et sedi mœrens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Convenerunt autem ad me omnes qui timebant verbum Dei Israël, pro transgressione eorum qui de captivitate venerant, et ego sedebam tristis usque ad sacrificium vespertinum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'et in sacrificio vespertino, surrexi de afflictione mea, et scisso pallio et tunica, curvavi genua mea, et expandi manus meas ad Dominum Deum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Et dixi: Deus meus, confundor et erubesco levare faciem meam ad te: quoniam iniquitates nostræ multiplicatæ sunt super caput nostrum, et delicta nostra creverunt usque ad cælum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'a diebus patrum nostrorum: sed et nos ipsi peccavimus graviter usque ad diem hanc, et in iniquitatibus nostris traditi sumus ipsi, et reges nostri, et sacerdotes nostri, in manum regum terrarum, et in gladium, et in captivitatem, et in rapinam, et in confusionem vultus, sicut et die hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Et nunc quasi parum et ad momentum facta est deprecatio nostra apud Dominum Deum nostrum, ut dimitterentur nobis reliquiæ, et daretur nobis paxillus in loco sancto ejus, et illuminaret oculos nostros Deus noster, et daret nobis vitam modicam in servitute nostra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'quia servi sumus, et in servitute nostra non dereliquit nos Deus noster, sed inclinavit super nos misericordiam coram rege Persarum, ut daret nobis vitam, et sublimaret domum Dei nostri, et exstrueret solitudines ejus, et daret nobis sepem in Juda et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Et nunc quid dicemus, Deus noster, post hæc? Quia dereliquimus mandata tua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'quæ præcepisti in manu servorum tuorum prophetarum, dicens: Terra, ad quam vos ingredimini ut possideatis eam, terra immunda est juxta immunditiam populorum, ceterarumque terrarum, abominationibus eorum qui repleverunt eam ab ore usque ad os in coinquinatione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Nunc ergo filias vestras ne detis filiis eorum, et filias eorum ne accipiatis filiis vestris, et non quæratis pacem eorum et prosperitatem eorum usque in æternum: ut confortemini, et comedatis quæ bona sunt terræ, et hæredes habeatis filios vestros usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Et post omnia quæ venerunt super nos in operibus nostris pessimis, et in delicto nostro magno, quia tu, Deus noster, liberasti nos de iniquitate nostra, et dedisti nobis salutem sicut est hodie,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'ut non converteremur, et irrita faceremus mandata tua, neque matrimonia jungeremus cum populis abominationum istarum. Numquid iratus es nobis usque ad consummationem, ne dimitteres nobis reliquias ad salutem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Domine Deus Israël, justus es tu: quoniam derelicti sumus, qui salvaremur sicut die hac. Ecce coram te sumus in delicto nostro: non enim stari potest coram te super hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Sic ergo orante Esdra, et implorante eo et flente, et jacente ante templum Dei, collectus est ad eum de Israël cœtus grandis nimis virorum et mulierum et puerorum, et flevit populus fletu multo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Et respondit Sechenias filius Jehiel de filiis \'lam, et dixit Esdræ: Nos prævaricati sumus in Deum nostrum, et duximus uxores alienigenas de populis terræ: et nunc, si est pœnitentia in Israël super hoc,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'percutiamus fœdus cum Domino Deo nostro, ut projiciamus universas uxores, et eos qui de his nati sunt, juxta voluntatem Domini, et eorum qui timent præceptum Domini Dei nostri: secundum legem fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Surge, tuum est decernere, nosque erimus tecum: confortare, et fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Surrexit ergo Esdras, et adjuravit principes sacerdotum et Levitarum, et omnem Israël, ut facerent secundum verbum hoc: et juraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Et surrexit Esdras ante domum Dei, et abiit ad cubiculum Johanan filii Eliasib, et ingressus est illuc: panem non comedit, et aquam non bibit: lugebat enim transgressionem eorum, qui venerant de captivitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Et missa est vox in Juda et in Jerusalem omnibus filiis transmigrationis, ut congregarentur in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'et omnis qui non venerit in tribus diebus juxta consilium principum et seniorum, auferetur universa substantia ejus, et ipse abjicietur de cœtu transmigrationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Convenerunt igitur omnes viri Juda et Benjamin in Jerusalem tribus diebus: ipse est mensis nonus, vigesimo die mensis: et sedit omnis populus in platea domus Dei, trementes pro peccato, et pluviis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Et surrexit Esdras sacerdos, et dixit ad eos: Vos transgressi estis, et duxistis uxores alienigenas, ut adderetis super delictum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Et nunc date confessionem Domino Deo patrum vestrorum, et facite placitum ejus, et separamini a populis terræ, et ab uxoribus alienigenis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Et respondit universa multitudo, dixitque voce magna: Juxta verbum tuum ad nos, sic fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Verumtamen quia populus multus est, et tempus pluviæ, et non sustinemus stare foris, et opus non est diei unius vel duorum (vehementer quippe peccavimus in sermone isto),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'constituantur principes in universa multitudine: et omnes in civitatibus nostris qui duxerunt uxores alienigenas veniant in temporibus statutis, et cum his seniores per civitatem et civitatem, et judices ejus, donec avertatur ira Dei nostri a nobis super peccato hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Igitur Jonathan filius Azahel, et Jaasia filius Thecue, steterunt super hoc, et Messollam et Sebethai Levites adjuverunt eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'feceruntque sic filii transmigrationis. Et abierunt Esdras sacerdos, et viri principes familiarum, in domos patrum suorum, et omnes per nomina sua, et sederunt in die primo mensis decimi ut quærerent rem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Et consummati sunt omnes viri, qui duxerant uxores alienigenas, usque ad diem primam mensis primi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Et inventi sunt de filiis sacerdotum qui duxerant uxores alienigenas. De filiis Josue filii Josedec, et fratres ejus, Maasia, et Eliezer, et Jarib, et Godolia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Et dederunt manus suas ut ejicerent uxores suas, et pro delicto suo arietem de ovibus offerrent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Et de filiis Emmer, Hanani, et Zebedia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Et de filiis Harim, Maasia, et Elia, et Semeia, et Jehiel, et Ozias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Et de filiis Pheshur, Elioënai, Maasia, Ismaël, Nathanaël, Jozabed, et Elasa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Et de filiis Levitarum, Jozabed, et Semei, et Celaia, ipse est Calita, Phataia, Juda, et Eliezer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Et de cantoribus, Eliasib. Et de janitoribus, Sellum, et Telem, et Uri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Et ex Israël, de filiis Pharos, Remeia, et Jesia, et Melchia, et Miamin, et Eliezer, et Melchia, et Banea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Et de filiis \'lam, Mathania, Zacharias, et Jehiel, et Abdi, et Jerimoth, et Elia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Et de filiis Zethua, Elioënai, Eliasib, Mathania, et Jerimuth, et Zabad, et Aziza.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Et de filiis Bebai, Johanan, Hanania, Zabbai, Athalai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Et de filiis Bani, Mosollam, et Melluch, et Adaia, Jasub, et Saal, et Ramoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Et de filiis Phahath Moab, Edna, et Chalal, Banaias, et Maasias, Mathanias, Beseleel, Bennui, et Manasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Et de filiis Herem, Eliezer, Josue, Melchias, Semeias, Simeon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Maloch, Samarias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Et de filiis Hasom, Mathanai, Mathatha, Zabad, Eliphelet, Jermai, Manasse, Semei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'De filiis Bani, Maadi, Amram, et Vel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Baneas, et Badaias, Cheliau,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vania, Marimuth, et Eliasib,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mathanias, Mathanai, et Jasi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'et Bani, et Bennui, Semei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'et Salmias, et Nathan, et Adaias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'et Mechnedebai, Sisai, Sarai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Ezrel, et Selemiau, Semeria,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sellum, Amaria, Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'De filiis Nebo, Jehiel, Mathathias, Zabad, Zabina, Jeddu, et Joël, et Banaia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Omnes hi acceperant uxores alienigenas, et fuerunt ex eis mulieres, quæ pepererant filios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Verba Nehemiæ filii Helchiæ. Et factum est in mense Casleu, anno vigesimo, et ego eram in Susis castro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Et venit Hanani, unus de fratribus meis, ipse et viri ex Juda: et interrogavi eos de Judæis qui remanserant, et supererant de captivitate, et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Et dixerunt mihi: Qui remanserunt, et relicti sunt de captivitate ibi in provincia, in afflictione magna sunt, et in opprobrio: et murus Jerusalem dissipatus est, et portæ ejus combustæ sunt igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Cumque audissem verba hujuscemodi, sedi, et flevi, et luxi diebus multis: jejunabam, et orabam ante faciem Dei cæli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'et dixi: Quæso, Domine Deus cæli fortis, magne atque terribilis, qui custodis pactum et misericordiam cum his qui te diligunt, et custodiunt mandata tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'fiant aures tuæ auscultantes, et oculi tui aperti, ut audias orationem servi tui, quam ego oro coram te hodie nocte et die pro filiis Israël servis tuis: et confiteor pro peccatis filiorum Israël, quibus peccaverunt tibi: ego et domus patris mei peccavimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'vanitate seducti sumus, et non custodivimus mandatum tuum, et cæremonias, et judicia quæ præcepisti Moysi famulo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Memento verbi quod mandasti Moysi servo tuo, dicens: Cum transgressi fueritis, ego dispergam vos in populos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'et si revertamini ad me, et custodiatis præcepta mea, et faciatis ea: etiamsi abducti fueritis ad extrema cæli, inde congregabo vos, et reducam in locum quem elegi ut habitaret nomen meum ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Et ipsi servi tui, et populus tuus, quos redemisti in fortitudine tua magna, et in manu tua valida.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Obsecro, Domine, sit auris tua attendens ad orationem servi tui, et ad orationem servorum tuorum, qui volunt timere nomen tuum: et dirige servum tuum hodie, et da ei misericordiam ante virum hunc. Ego enim eram pincerna regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Factum est autem in mense Nisan, anno vigesimo Artaxerxis regis: et vinum erat ante eum, et levavi vinum, et dedi regi: et eram quasi languidus ante faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Dixitque mihi rex: Quare vultus tuus tristis est, cum te ægrotum non videam? non est hoc frustra, sed malum nescio quod in corde tuo est. Et timui valde, ac nimis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'et dixi regi: Rex, in æternum vive: quare non mœreat vultus meus, quia civitas domus sepulchrorum patris mei deserta est, et portæ ejus combustæ sunt igni?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Et ait mihi rex: Pro qua re postulas? Et oravi Deum cæli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'et dixi ad regem: Si videtur regi bonum, et si placet servus tuus ante faciem tuam, ut mittas me in Judæam ad civitatem sepulchri patris mei, et ædificabo eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Dixitque mihi rex, et regina quæ sedebat juxta eum: Usque ad quod tempus erit iter tuum, et quando reverteris? Et placuit ante vultum regis, et misit me: et constitui ei tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Et dixi regi: Si regi videtur bonum, epistolas det mihi ad duces regionis trans flumen, ut traducant me, donec veniam in Judæam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'et epistolam ad Asaph custodem saltus regis, ut det mihi ligna, ut tegere possim portas turris domus, et muros civitatis, et domum quam ingressus fuero. Et dedit mihi rex juxta manum Dei mei bonam mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Et veni ad duces regionis trans flumen, dedique eis epistolas regis. Miserat autem rex mecum principes militum, et equites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Et audierunt Sanaballat Horonites, et Tobias servus Ammanites: et contristati sunt afflictione magna, quod venisset homo qui quæreret prosperitatem filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Et veni Jerusalem, et eram ibi tribus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Et surrexi nocte ego, et viri pauci mecum, et non indicavi cuiquam quid Deus dedisset in corde meo ut facerem in Jerusalem: et jumentum non erat mecum, nisi animal cui sedebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Et egressus sum per portam vallis nocte, et ante fontem draconis, et ad portam stercoris, et considerabam murum Jerusalem dissipatum, et portas ejus consumptas igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Et transivi ad portam fontis, et ad aquæductum regis, et non erat locus jumento cui sedebam ut transiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Et ascendi per torrentem nocte, et considerabam murum, et reversus veni ad portam vallis, et redii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Magistratus autem nesciebant quo abiissem, aut quid ego facerem: sed et Judæis, et sacerdotibus, et optimatibus, et magistratibus, et reliquis qui faciebant opus, usque ad id loci nihil indicaveram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Et dixi eis: Vos nostis afflictionem in qua sumus: quia Jerusalem deserta est, et portæ ejus consumptæ sunt igni: venite, et ædificemus muros Jerusalem, et non simus ultra opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Et indicavi eis manum Dei mei, quod esset bona mecum, et verba regis quæ locutus esset mihi, et aio: Surgamus, et ædificemus. Et confortatæ sunt manus eorum in bono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Audierunt autem Sanaballat Horonites, et Tobias servus Ammanites, et Gosem Arabs, et subsannaverunt nos, et despexerunt, dixeruntque: Quæ est hæc res quam facitis? numquid contra regem vos rebellatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Et reddidi eis sermonem, dixique ad eos: Deus cæli ipse nos juvat, et nos servi ejus sumus: surgamus et ædificemus: vobis autem non est pars, et justitia, et memoria in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Et surrexit Eliasib sacerdos magnus, et fratres ejus sacerdotes, et ædificaverunt portam gregis: ipsi sanctificaverunt eam, et statuerunt valvas ejus, et usque ad turrim centum cubitorum sanctificaverunt eam, usque ad turrim Hananeel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et juxta eum ædificaverunt viri Jericho: et juxta eum ædificavit Zachur filius Amri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Portam autem piscium ædificaverunt filii Asnaa: ipsi texerunt eam, et statuerunt valvas ejus, et seras, et vectes. Et juxta eos ædificavit Marimuth filius Uriæ, filii Accus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et juxta eum ædificavit Mosollam filius Barachiæ, filii Mesezebel: et juxta eos ædificavit Sadoc filius Baana.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Et juxta eos ædificaverunt Thecueni: optimates autem eorum non supposuerunt colla sua in opere Domini sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Et portam veterem ædificaverunt Jojada filius Phasea, et Mosollam filius Besodia: ipsi texerunt eam, et statuerunt valvas ejus, et seras, et vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et juxta eos ædificaverunt Meltias Gabaonites, et Jadon Meronathites, viri de Gabaon et Maspha, pro duce qui erat in regione trans flumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Et juxta eum ædificavit Eziel filius Araia aurifex: et juxta eum ædificavit Ananias filius pigmentarii: et dimiserunt Jerusalem usque ad murum plateæ latioris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Et juxta eum ædificavit Raphaia filius Hur, princeps vici Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Et juxta eum ædificavit Jedaia filius Haromaph contra domum suam: et juxta eum ædificavit Hattus filius Haseboniæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Mediam partem vici ædificavit Melchias filius Herem, et Hasub filius Phahath Moab, et turrim furnorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et juxta eum ædificavit Sellum filius Alohes, princeps mediæ partis vici Jerusalem, ipse et filiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Et portam vallis ædificavit Hanun, et habitatores Zanoë: ipsi ædificaverunt eam, et statuerunt valvas ejus, et seras, et vectes, et mille cubitos in muro usque ad portam sterquilinii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Et portam sterquilinii ædificavit Melchias filius Rechab, princeps vici Bethacharam: ipse ædificavit eam, et statuit valvas ejus, et seras, et vectes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Et portam fontis ædificavit Sellum filius Cholhoza, princeps pagi Maspha: ipse ædificavit eam, et texit, et statuit valvas ejus, et seras, et vectes, et muros piscinæ Siloë in hortum regis, et usque ad gradus qui descendunt de civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Post eum ædificavit Nehemias filius Azboc, princeps dimidiæ partis vici Bethsur, usque contra sepulchrum David, et usque ad piscinam quæ grandi opere constructa est, et usque ad domum fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Post eum ædificaverunt Levitæ, Rehum filius Benni: post eum ædificavit Hasebias princeps dimidiæ partis vici Ceilæ in vico suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Post eum ædificaverunt fratres eorum: Bavai filius Enadad, princeps dimidiæ partis Ceilæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'et ædificavit juxta eum Azer filius Josue, princeps Maspha, mensuram secundam, contra ascensum firmissimi anguli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Post eum in monte ædificavit Baruch filius Zachai mensuram secundam, ab angulo usque ad portam domus Eliasib sacerdotis magni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Post eum ædificavit Merimuth filius Uriæ filii Haccus, mensuram secundam, a porta domus Eliasib, donec extenderetur domus Eliasib.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Et post eum ædificaverunt sacerdotes, viri de campestribus Jordanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Post eum ædificavit Benjamin et Hasub contra domum suam: et post eum ædificavit Azarias filius Maasiæ filii Ananiæ contra domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Post eum ædificavit Bennui filius Henadad mensuram secundam, a domo Azariæ usque ad flexuram, et usque ad angulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Phalel filius Ozi contra flexuram, et turrim quæ eminet de domo regis excelsa, id est, in atrio carceris: post eum Phadaia filius Pharos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Nathinæi autem habitabant in Ophel usque contra portam aquarum ad orientem, et turrim quæ prominebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Post eum ædificaverunt Thecueni mensuram secundam e regione, a turre magna et eminente usque ad murum templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Sursum autem a porta equorum ædificaverunt sacerdotes, unusquisque contra domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Post eos ædificavit Sadoc filius Emmer contra domum suam. Et post eum ædificavit Semaia filius Secheniæ, custos portæ orientalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Post eum ædificavit Hanania filius Selemiæ, et Hanun filius Seleph sextus, mensuram secundam: post eum ædificavit Mosollam filius Barachiæ, contra gazophylacium suum. Post eum ædificavit Melchias filius aurificis usque ad domum Nathinæorum, et scruta vendentium contra portam judicialem, et usque ad cœnaculum anguli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Et inter cœnaculum anguli in porta gregis, ædificaverunt aurifices et negotiatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Factum est autem, cum audisset Sanaballat quod ædificaremus murum, iratus est valde: et motus nimis subsannavit Judæos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'et dixit coram fratribus suis, et frequentia Samaritanorum: Quid Judæi faciunt imbecilles? num dimittent eos gentes? num sacrificabunt, et complebunt in una die? numquid ædificare poterunt lapides de acervis pulveris, qui combusti sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Sed et Tobias Ammanites, proximus ejus, ait: \'dificent: si ascenderit vulpes, transiliet murum eorum lapideum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Audi, Deus noster, quia facti sumus despectui: converte opprobrium super caput eorum, et da eos in despectionem in terra captivitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Ne operias iniquitatem eorum, et peccatum eorum coram facie tua non deleatur, quia irriserunt ædificantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Itaque ædificavimus murum, et conjunximus totum usque ad partem dimidiam: et provocatum est cor populi ad operandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Factum est autem, cum audisset Sanaballat, et Tobias, et Arabes, et Ammanitæ, et Azotii, quod obducta esset cicatrix muri Jerusalem, et quod cœpissent interrupta concludi, irati sunt nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Et congregati sunt omnes pariter ut venirent, et pugnarent contra Jerusalem, et molirentur insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Et oravimus Deum nostrum, et posuimus custodes super murum die ac nocte contra eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Dixit autem Judas: Debilitata est fortitudo portantis, et humus nimia est, et nos non poterimus ædificare murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Et dixerunt hostes nostri: Nesciant, et ignorent donec veniamus in medium eorum, et interficiamus eos, et cessare faciamus opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Factum est autem venientibus Judæis qui habitabant juxta eos, et dicentibus nobis per decem vices, ex omnibus locis quibus venerant ad nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'statui in loco post murum per circuitum populum in ordinem cum gladiis suis, et lanceis, et arcubus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Et perspexi atque surrexi: et aio ad optimates et magistratus, et ad reliquam partem vulgi: Nolite timere a facie eorum: Domini magni et terribilis mementote, et pugnate pro fratribus vestris, filiis vestris, et filiabus vestris, et uxoribus vestris, et domibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Factum est autem, cum audissent inimici nostri nuntiatum esse nobis, dissipavit Deus consilium eorum. Et reversi sumus omnes ad muros, unusquisque ad opus suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Et factum est a die illa, media pars juvenum eorum faciebat opus, et media parata erat ad bellum: et lanceæ, et scuta, et arcus, et loricæ, et principes post eos in omni domo Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, '\'dificantium in muro, et portantium onera, et imponentium: una manu sua faciebat opus, et altera tenebat gladium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'ædificentium enim unusquisque gladio erat accinctus renes. Et ædificabant, et clangebant buccina juxta me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Et dixi ad optimates, et ad magistratus, et ad reliquam partem vulgi: Opus grande est et latum, et nos separati sumus in muro procul alter ab altero:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'in loco quocumque audieritis clangorem tubæ, illuc concurrite ad nos: Deus noster pugnabit pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Et nos ipsi faciamus opus, et media pars nostrum teneat lanceas ab ascensu auroræ donec egrediantur astra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'In tempore quoque illo dixi populo: Unusquisque cum puero suo maneat in medio Jerusalem, et sint nobis vices per noctem et diem ad operandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Ego autem et fratres mei, et pueri mei, et custodes, qui erant post me, non deponebamus vestimenta nostra: unusquisque tantum nudabatur ad baptismum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Et factus est clamor populi et uxorum ejus magnus adversus fratres suos Judæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Et erant qui dicerent: Filii nostri et filiæ nostræ multæ sunt nimis: accipiamus pro pretio eorum frumentum, et comedamus, et vivamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Et erant qui dicerent: Agros nostros, et vineas, et domus nostras opponamus, et accipiamus frumentum in fame.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Et alii dicebant: Mutuo sumamus pecunias in tributa regis, demusque agros nostros et vineas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'et nunc sicut carnes fratrum nostrorum, sic carnes nostræ sunt: et sicut filii eorum, ita et filii nostri: ecce nos subjugamus filios nostros et filias nostras in servitutem, et de filiabus nostris sunt famulæ, nec habemus unde possint redimi: et agros nostros et vineas nostras alii possident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Et iratus sum nimis cum audissem clamorem eorum secundum verba hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'cogitavitque cor meum mecum, et increpavi optimates et magistratus, et dixi eis: Usurasne singuli a fratribus vestris exigitis? Et congregavi adversum eos concionem magnam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'et dixi eis: Nos, ut scitis, redemimus fratres nostros Judæos, qui venditi fuerant gentibus secundum possibilitatem nostram: et vos igitur vendetis fratres vestros, et redimemus eos? Et siluerunt, nec invenerunt quid responderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Dixique ad eos: Non est bona res quam facitis: quare non in timore Dei nostri ambulastis, ne exprobretur nobis a gentibus inimicis nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Et ego, et fratres mei, et pueri mei commodavimus plurimis pecuniam et frumentum. Non repetamus in commune istud: æs alienum concedamus quod debetur nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Reddite eis hodie agros suos, et vineas suas, et oliveta sua, et domos suas: quin potius et centesimum pecuniæ, frumenti, vini et olei, quam exigere soletis ab eis, date pro illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Et dixerunt: Reddemus, et ab eis nihil quæremus: sicque faciemus ut loqueris. Et vocavi sacerdotes, et adjuravi eos ut facerent juxta quod dixeram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Insuper excussi sinum meum, et dixi: Sic excutiat Deus omnem virum qui non compleverit verbum istud, de domo sua, et de laboribus suis: sic excutiatur, et vacuus fiat. Et dixit universa multitudo: Amen: et laudaverunt Deum. Fecit ergo populus sicut erat dictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'A die autem illa, qua præceperat rex mihi ut essem dux in terra Juda, ab anno vigesimo usque ad annum trigesimum secundum Artaxerxis regis per annos duodecim, ego et fratres mei annonas quæ ducibus debebantur non comedimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Duces autem primi, qui fuerant ante me, gravaverunt populum, et acceperunt ab eis in pane, et vino, et pecunia, quotidie siclos quadraginta: sed et ministri eorum depresserunt populum. Ego autem non feci ita propter timorem Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'quin potius in opere muri ædificavi, et agrum non emi, et omnes pueri mei congregati ad opus erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Judæi quoque et magistratus centum quinquaginta viri, et qui veniebant ad nos de gentibus quæ in circuitu nostro sunt, in mensa mea erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Parabatur autem mihi per dies singulos bos unus, arietes sex electi, exceptis volatilibus, et inter dies decem vina diversa, et alia multa tribuebam: insuper et annonas ducatus mei non quæsivi: valde enim attenuatus erat populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Memento mei, Deus meus, in bonum, secundum omnia quæ feci populo huic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Factum est autem, cum audisset Sanaballat, et Tobias, et Gossem Arabs, et ceteri inimici nostri, quod ædificassem ego murum, et non esset in ipso residua interruptio (usque ad tempus autem illud valvas non posueram in portis),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'miserunt Sanaballat et Gossem ad me, dicentes: Veni, et percutiamus fœdus pariter in viculis in campo Ono. Ipsi autem cogitabant ut facerent mihi malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Misi ergo ad eos nuntios, dicens: Opus grande ego facio, et non possum descendere, ne forte negligatur cum venero, et descendero ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Miserunt autem ad me secundum verbum hoc per quatuor vices: et respondi eis juxta sermonem priorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Et misit ad me Sanaballat juxta verbum prius quinta vice puerum suum, et epistolam habebat in manu sua scriptam hoc modo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'In gentibus auditum est, et Gossem dixit, quod tu et Judæi cogitetis rebellare, et propterea ædifices murum, et levare te velis super eos regem: propter quam causam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'et prophetas posueris, qui prædicent de te in Jerusalem, dicentes: Rex in Judæa est. Auditurus est rex verba hæc: idcirco nunc veni, ut ineamus consilium pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Et misi ad eos, dicens: Non est factum secundum verba hæc, quæ tu loqueris: de corde enim tuo tu componis hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Omnes enim hi terrebant nos, cogitantes quod cessarent manus nostræ ab opere, et quiesceremus: quam ob causam magis confortavi manus meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Et ingressus sum domum Semaiæ filii Dalaiæ filii Metabeel secreto. Qui ait: Tractemus nobiscum in domo Dei in medio templi, et claudamus portas ædis: quia venturi sunt ut interficiant te, et nocte venturi sunt ad occidendum te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Et dixi: Num quisquam similis mei fugit? et quis ut ego ingredietur templum, et vivet? non ingrediar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Et intellexi quod Deus non misisset eum, sed quasi vaticinans locutus esset ad me, et Tobias et Sanaballat conduxissent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Acceperat enim pretium, ut territus facerem, et peccarem, et haberent malum quod exprobrarent mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Memento mei, Domine, pro Tobia et Sanaballat, juxta opera eorum talia: sed et Noadiæ prophetæ, et ceterorum prophetarum, qui terrebant me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Completus est autem murus vigesimo quinto die mensis Elul, quinquaginta duobus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Factum est ergo cum audissent omnes inimici nostri, ut timerent universæ gentes quæ erant in circuitu nostro, et conciderent intra semetipsos, et scirent quod a Deo factum esset opus hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Sed et in diebus illis multæ optimatum Judæorum epistolæ mittebantur ad Tobiam, et a Tobia veniebant ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Multi enim erant in Judæa habentes juramentum ejus, quia gener erat Secheniæ filii Area, et Johanan filius ejus acceperat filiam Mosollam filii Barachiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'sed et laudabant eum coram me, et verba mea nuntiabant ei: et Tobias mittebat epistolas ut terreret me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Postquam autem ædificatus est murus, et posui valvas, et recensui janitores, et cantores, et Levitas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'præcepi Hanani fratri meo, et Hananiæ principi domus de Jerusalem (ipse enim quasi vir verax et timens Deum plus ceteris videbatur),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'et dixi eis: Non aperiantur portæ Jerusalem usque ad calorem solis. Cumque adhuc assisterent, clausæ portæ sunt, et oppilatæ: et posui custodes de habitatoribus Jerusalem, singulos per vices suas, et unumquemque contra domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Civitas autem erat lata nimis et grandis, et populus parvus in medio ejus, et non erant domus ædificatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Deus autem dedit in corde meo, et congregavi optimates, et magistratus, et vulgus, ut recenserem eos: et inveni librum census eorum qui ascenderant primum, et inventum est scriptum in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Isti filii provinciæ, qui ascenderunt de captivitate migrantium, quos transtulerat Nabuchodonosor rex Babylonis, et reversi sunt in Jerusalem et in Judæam, unusquisque in civitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Qui venerunt cum Zorobabel, Josue, Nehemias, Azarias, Raamias, Nahamani, Mardochæus, Belsam, Mespharath, Begoai, Nahum, Baana. Numerus virorum populi Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'filii Pharos, duo millia centum septuaginta duo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'filii Saphatia, trecenti septuaginta duo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'filii Area, sexcenti quinquaginta duo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'filii Phahathmoab filiorum Josue et Joab, duo millia octingenti decem et octo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'filii \'lam, mille ducenti quinquaginta quatuor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'filii Zethua, octingenti quadraginta quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'filii Zachai, septingenti sexaginta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'filii Bannui, sexcenti quadraginta octo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'filii Bebai, sexcenti viginti octo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'filii Azgad, duo millia trecenti viginti duo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'filii Adonicam, sexcenti sexaginta septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'filii Beguai, duo millia sexaginta septem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'filii Adin, sexcenti quinquaginta quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'filii Ater, filii Hezeciæ, nonaginta octo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'filii Hasem, trecenti viginti octo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'filii Besai, trecenti viginti quatuor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'filii Hareph, centum duodecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'filii Gabaon, nonaginta quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'filii Bethlehem et Netupha, centum octoginta octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Viri Anathoth, centum viginti octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Viri Bethazmoth, quadraginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Viri Cariathiarim, Cephira, et Beroth, septingenti quadraginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Viri Rama et Geba, sexcenti viginti unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Viri Machmas, centum viginti duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Viri Bethel et Hai, centum viginti tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Viri Nebo alterius, quinquaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Viri \'lam alterius, mille ducenti quinquaginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Filii Harem, trecenti viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Filii Jericho, trecenti quadraginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Filii Lod Hadid et Ono, septingenti viginti unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Filii Senaa, tria millia nongenti triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Sacerdotes: filii Idaia in domo Josue, nongenti septuaginta tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Filii Emmer, mille quinquaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Filii Phashur, mille ducenti quadraginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Filii Arem, mille decem et septem. Levitæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'filii Josue et Cedmihel filiorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Oduiæ, septuaginta quatuor. Cantores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'filii Asaph, centum quadraginta octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Janitores: filii Sellum, filii Ater, filii Telmon, filii Accub, filii Hatita, filii Sobai: centum triginta octo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Nathinæi: filii Soha, filii Hasupha, filii Tebbaoth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'filii Ceros, filii Siaa, filii Phadon, filii Lebana, filii Hagaba, filii Selmai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'filii Hanan, filii Geddel, filii Gaher,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'filii Raaia, filii Rasin, filii Necoda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'filii Gezem, filii Aza, filii Phasea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'filii Besai, filii Munim, filii Nephussim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'filii Bacbuc, filii Hacupha, filii Harhur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'filii Besloth, filii Mahida, filii Harsa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'filii Bercos, filii Sisara, filii Thema,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'filii Nasia, filii Hatipha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'filii servorum Salomonis, filii Sothai, filii Sophereth, filii Pharida,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'filii Jahala, filii Darcon, filii Jeddel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'filii Saphatia, filii Hatil, filii Phochereth, qui erat ortus ex Sabaim filio Amon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Omnes Nathinæi, et filii servorum Salomonis, trecenti nonaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Hi sunt autem qui ascenderunt de Thelmela, Thelharsa, Cherub, Addon, et Emmer: et non potuerunt indicare domum patrum suorum, et semen suum, utrum ex Israël essent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'filii Dalaia, filii Tobia, filii Necoda, sexcenti quadraginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Et de sacerdotibus, filii Habia, filii Accos, filii Berzellai, qui accepit de filiabus Berzellai Galaaditis uxorem, et vocatus est nomine eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Hi quæsierunt scripturam suam in censu, et non invenerunt: et ejecti sunt de sacerdotio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Dixitque Athersatha eis ut non manducarent de Sanctis sanctorum, donec staret sacerdos doctus et eruditus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Omnis multitudo quasi vir unus quadraginta duo millia trecenti sexaginta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'absque servis et ancillis eorum, qui erant septem millia trecenti triginta septem, et inter eos cantores et cantatrices, ducenti quadraginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Equi eorum, septingenti triginta sex: muli eorum, ducenti quadraginta quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'cameli eorum, quadringenti triginta quinque: asini, sex millia septingenti viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Nonnulli autem de principibus familiarum dederunt in opus. Athersatha dedit in thesaurum auri drachmas mille, phialas quinquaginta, tunicas sacerdotales quingentas triginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Et de principibus familiarum dederunt in thesaurum operis, auri drachmas viginti millia, et argenti mnas duo millia ducentas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Et quod dedit reliquus populus, auri drachmas viginti millia, et argenti mnas duo millia, et tunicas sacerdotales sexaginta septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Habitaverunt autem sacerdotes, et Levitæ, et janitores, et cantores, et reliquum vulgus, et Nathinæi, et omnis Israël, in civitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Et venerat mensis septimus: filii autem Israël erant in civitatibus suis. Congregatusque est omnis populus quasi vir unus ad plateam quæ est ante portam aquarum: et dixerunt Esdræ scribæ ut afferret librum legis Moysi, quam præceperat Dominus Israëli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Attulit ergo Esdras sacerdos legem coram multitudine virorum et mulierum, cunctisque qui poterant intelligere, in die prima mensis septimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Et legit in eo aperte in platea quæ erat ante portam aquarum, de mane usque ad mediam diem, in conspectu virorum et mulierum, et sapientium: et aures omnis populi erant erectæ ad librum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Stetit autem Esdras scriba super gradum ligneum, quem fecerat ad loquendum: et steterunt juxta eum Mathathias, et Semeia, et Ania, et Uria, et Helcia, et Maasia, ad dexteram ejus: et ad sinistram, Phadaia, Misaël, et Melchia, et Hasum, et Hasbadana, Zacharia, et Mosollam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et aperuit Esdras librum coram omni populo: super universum quippe populum eminebat: et cum aperuisset eum, stetit omnis populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Et benedixit Esdras Domino Deo magno: et respondit omnis populus: Amen, amen, elevans manus suas: et incurvati sunt, et adoraverunt Deum proni in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Porro Josue, et Bani, et Serebia, Jamin, Accub, Septhai, Odia, Maasia, Celita, Azarias, Jozabed, Hanan, Phalaia, Levitæ, silentium faciebant in populo ad audiendam legem: populus autem stabat in gradu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et legerunt in libro legis Dei distincte, et aperte ad intelligendum: et intellexerunt cum legeretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Dixit autem Nehemias (ipse est Athersatha) et Esdras sacerdos et scriba, et Levitæ interpretantes universo populo: Dies sanctificatus est Domino Deo nostro: nolite lugere, et nolite flere. Flebat enim omnis populus cum audiret verba legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Et dixit eis: Ite, comedite pinguia, et bibite mulsum, et mittite partes his qui non præparaverunt sibi, quia sanctus dies Domini est: et nolite contristari: gaudium etenim Domini est fortitudo nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Levitæ autem silentium faciebant in omni populo, dicentes: Tacete, quia dies sanctus est, et nolite dolere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Abiit itaque omnis populus ut comederet, et biberet, et mitteret partes, et faceret lætitiam magnam: quia intellexerant verba quæ docuerat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et in die secundo congregati sunt principes familiarum universi populi, sacerdotes et Levitæ, ad Esdram scribam, ut interpretaretur eis verba legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Et invenerunt scriptum in lege præcepisse Dominum in manu Moysi ut habitent filii Israël in tabernaculis in die solemni, mense septimo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'et ut prædicent, et divulgent vocem in universis urbibus suis, et in Jerusalem, dicentes: Egredimini in montem, et afferte frondes olivæ, et frondes ligni pulcherrimi, frondes myrti, et ramos palmarum, et frondes ligni nemorosi, ut fiant tabernacula, sicut scriptum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Et egressus est populus, et attulerunt. Feceruntque sibi tabernacula unusquisque in domate suo: et in atriis suis, et in atriis domus Dei, et in platea portæ aquarum, et in platea portæ Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Fecit ergo universa ecclesia eorum qui redierant de captivitate, tabernacula, et habitaverunt in tabernaculis: non enim fecerant a diebus Josue filii Nun taliter filii Israël usque ad diem illum. Et fuit lætitia magna nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Legit autem in libro legis Dei per dies singulos, a die primo usque ad diem novissimum. Et fecerunt solemnitatem septem diebus, et in die octavo collectam juxta ritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'In die autem vigesimo quarto mensis hujus, convenerunt filii Israël in jejunio et in saccis, et humus super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Et separatum est semen filiorum Israël ab omni filio alienigena: et steterunt, et confitebantur peccata sua, et iniquitates patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Et consurrexerunt ad standum: et legerunt in volumine legis Domini Dei sui, quater in die, et quater confitebantur, et adorabant Dominum Deum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Surrexerunt autem super gradum Levitarum Josue, et Bani, et Cedmihel, Sabania, Bonni, Sarebias, Bani, et Chanani: et clamaverunt voce magna ad Dominum Deum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et dixerunt Levitæ Josue, et Cedmihel, Bonni, Hasebnia, Serebia, Odaia, Sebnia, Phathathia: Surgite, benedicite Domino Deo vestro ab æterno usque in æternum: et benedicant nomini gloriæ tuæ excelso in omni benedictione et laude.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu ipse, Domine, solus, tu fecisti cælum, et cælum cælorum, et omnem exercitum eorum: terram, et universa quæ in ea sunt: maria, et omnia quæ in eis sunt: et tu vivificas omnia hæc, et exercitus cæli te adorat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu ipse, Domine Deus, qui elegisti Abram, et eduxisti eum de igne Chaldæorum, et posuisti nomen ejus Abraham:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'et invenisti cor ejus fidele coram te, et percussisti cum eo fœdus ut dares ei terram Chananæi, Hethæi, et Amorrhæi, et Pherezæi, et Jebusæi, et Gergesæi, ut dares semini ejus: et implesti verba tua, quoniam justus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Et vidisti afflictionem patrum nostrorum in \'gypto, clamoremque eorum audisti super mare Rubrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Et dedisti signa atque portenta in Pharaone, et in universis servis ejus, et in omni populo terræ illius: cognovisti enim quia superbe egerant contra eos: et fecisti tibi nomen, sicut et in hac die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Et mare divisisti ante eos, et transierunt per medium maris in sicco: persecutores autem eorum projecisti in profundum, quasi lapidem in aquas validas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Et in columna nubis ductor eorum fuisti per diem, et in columna ignis per noctem, ut appareret eis via per quam ingrediebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Ad montem quoque Sinai descendisti, et locutus es cum eis de cælo, et dedisti eis judicia recta, et legem veritatis, cæremonias, et præcepta bona:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'et sabbatum sanctificatum tuum ostendisti eis: et mandata, et cæremonias, et legem præcepisti eis in manu Moysi servi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Panem quoque de cælo dedisti eis in fame eorum, et aquam de petra eduxisti eis sitientibus, et dixisti eis ut ingrederentur et possiderent terram, super quam levasti manum tuam ut traderes eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ipsi vero et patres nostri superbe egerunt, et induraverunt cervices suas, et non audierunt mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Et noluerunt audire, et non sunt recordati mirabilium tuorum quæ feceras eis. Et induraverunt cervices suas, et dederunt caput ut converterentur ad servitutem suam, quasi per contentionem. Tu autem, Deus propitius, clemens, et misericors, longanimis, et multæ miserationis, non dereliquisti eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'et quidem cum fecissent sibi vitulum conflatilem, et dixissent: Iste est deus tuus, qui eduxit te de \'gypto: feceruntque blasphemias magnas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'tu autem in misericordiis tuis multis non dimisisti eos in deserto: columna nubis non recessit ab eis per diem ut duceret eos in viam, et columna ignis per noctem ut ostenderet eis iter per quod ingrederentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Et spiritum tuum bonum dedisti, qui doceret eos: et manna tuum non prohibuisti ab ore eorum, et aquam dedisti eis in siti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Quadraginta annis pavisti eos in deserto, nihilque eis defuit: vestimenta eorum non inveteraverunt, et pedes eorum non sunt attriti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Et dedisti eis regna, et populos, et partitus es eis sortes: et possederunt terram Sehon, et terram regis Hesebon, et terram Og regis Basan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Et multiplicasti filios eorum sicut stellas cæli, et adduxisti eos ad terram de qua dixeras patribus eorum ut ingrederentur et possiderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Et venerunt filii, et possederunt terram, et humiliasti coram eis habitatores terræ Chananæos, et dedisti eos in manu eorum, et reges eorum, et populos terræ, ut facerent eis sicut placebant illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Ceperunt itaque urbes munitas et humum pinguem, et possederunt domos plenas cunctis bonis: cisternas ab aliis fabricatas, vineas, et oliveta, et ligna pomifera multa: et comederunt, et saturati sunt, et impinguati sunt, et abundaverunt deliciis in bonitate tua magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Provocaverunt autem te ad iracundiam, et recesserunt a te, et projecerunt legem tuam post terga sua: et prophetas tuos occiderunt, qui contestabantur eos ut reverterentur ad te: feceruntque blasphemias grandes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Et dedisti eos in manu hostium suorum, et afflixerunt eos. Et in tempore tribulationis suæ clamaverunt ad te, et tu de cælo audisti, et secundum miserationes tuas multas dedisti eis salvatores, qui salvarent eos de manu hostium suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Cumque requievissent, reversi sunt ut facerent malum in conspectu tuo, et dereliquisti eos in manu inimicorum suorum, et possederunt eos. Conversique sunt, et clamaverunt ad te: tu autem de cælo exaudisti, et liberasti eos in misericordiis tuis, multis temporibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Et contestatus es eos ut reverterentur ad legem tuam. Ipsi vero superbe egerunt, et non audierunt mandata tua, et in judiciis tuis peccaverunt, quæ faciet homo, et vivet in eis: et dederunt humerum recedentem, et cervicem suam induraverunt, nec audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Et protraxisti super eos annos multos, et contestatus es eos in spiritu tuo per manum prophetarum tuorum: et non audierunt, et tradidisti eos in manu populorum terrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'In misericordiis autem tuis plurimis non fecisti eos in consumptionem, nec dereliquisti eos: quoniam Deus miserationum et clemens es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nunc itaque Deus noster magne, fortis et terribilis, custodiens pactum et misericordiam, ne avertas a facie tua omnem laborem, qui invenit nos, reges nostros, et principes nostros, et sacerdotes nostros, et prophetas nostros, et patres nostros, et omnem populum tuum a diebus regis Assur usque in diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Et tu justus es in omnibus quæ venerunt super nos: quia veritatem fecisti, nos autem impie egimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Reges nostri, principes nostri, sacerdotes nostri et patres nostri non fecerunt legem tuam, et non attenderunt mandata tua, et testimonia tua quæ testificatus es in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Et ipsi in regnis suis, et in bonitate tua multa quam dederas eis, et in terra latissima et pingui quam tradideras in conspectu eorum, non servierunt tibi, nec reversi sunt a studiis suis pessimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Ecce nos ipsi hodie servi sumus: et terra quam dedisti patribus nostris ut comederent panem ejus, et quæ bona sunt ejus, et nos ipsi servi sumus in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Et fruges ejus multiplicantur regibus quos posuisti super nos propter peccata nostra: et corporibus nostris dominantur, et jumentis nostris secundum voluntatem suam: et in tribulatione magna sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Super omnibus ergo his nos ipsi percutimus fœdus, et scribimus: et signant principes nostri, Levitæ nostri, et sacerdotes nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Signatores autem fuerunt Nehemias, Athersatha filius Hachelai, et Sedecias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Saraias, Azarias, Jeremias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pheshur, Amarias, Melchias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebenia, Melluch,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harem, Merimuth, Obdias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Genthon, Baruch,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mosollam, Abia, Miamin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazia, Belgai, Semeia: hi sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Porro Levitæ, Josue filius Azaniæ, Bennui de filiis Henadad, Cedmihel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'et fratres eorum, Sebenia, Odaia, Celita, Phalaia, Hanan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rohob, Hasebia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zachur, Serebia, Sabania,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Odaia, Bani, Baninu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Capita populi, Pharos, Phahathmoab, \'lam, Zethu, Bani,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bonni, Azgad, Bebai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonia, Begoai, Adin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hezecia, Azur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Odaia, Hasum, Besai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hareph, Anathoth, Nebai,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Megphias, Mosollam, Hazir,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesizabel, Sadoc, Jeddua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pheltia, Hanan, Anaia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Osee, Hanania, Hasub,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Alohes, Phalea, Sobec,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasebna, Maasia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Echaia, Hanan, Anan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Melluch, Haran, Baana.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Et reliqui de populo, sacerdotes, Levitæ, janitores, et cantores, Nathinæi, et omnes qui se separaverunt de populis terrarum ad legem Dei, uxores eorum, filii eorum, et filiæ eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'omnes qui poterant sapere spondentes pro fratribus suis, optimates eorum, et qui veniebant ad pollicendum et jurandum ut ambularent in lege Dei, quam dederat in manu Moysi servi Dei: ut facerent et custodirent universa mandata Domini Dei nostri, et judicia ejus et cæremonias ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'et ut non daremus filias nostras populo terræ, et filias eorum non acciperemus filiis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Populi quoque terræ, qui important venalia, et omnia ad usum, per diem sabbati ut vendant, non accipiemus ab eis in sabbato et in die sanctificato. Et dimittemus annum septimum, et exactionem universæ manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Et statuemus super nos præcepta, ut demus tertiam partem sicli per annum ad opus domus Dei nostri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'ad panes propositionis, et ad sacrificium sempiternum, et in holocaustum sempiternum in sabbatis, in calendis, in solemnitatibus, et in sanctificatis, et pro peccato: ut exoretur pro Israël, et in omnem usum domus Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Sortes ergo misimus super oblationem lignorum inter sacerdotes, et Levitas, et populum, ut inferrentur in domum Dei nostri per domos patrum nostrorum, per tempora, a temporibus anni usque ad annum: ut arderent super altare Domini Dei nostri, sicut scriptum est in lege Moysi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'et ut afferremus primogenita terræ nostræ, et primitiva universi fructus omnis ligni, ab anno in annum, in domo Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'et primitiva filiorum nostrorum et pecorum nostrorum, sicut scriptum est in lege, et primitiva boum nostrorum et ovium nostrarum, ut offerrentur in domo Dei nostri, sacerdotibus qui ministrant in domo Dei nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'et primitias ciborum nostrorum, et libaminum nostrorum, et poma omnis ligni, vindemiæ quoque et olei, afferemus sacerdotibus ad gazophylacium Dei nostri, et decimam partem terræ nostræ Levitis. Ipsi Levitæ decimas accipient ex omnibus civitatibus operum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Erit autem sacerdos filius Aaron cum Levitis in decimis Levitarum, et Levitæ offerent decimam partem decimæ suæ in domo Dei nostri ad gazophylacium in domum thesauri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Ad gazophylacium enim deportabunt filii Israël, et filii Levi, primitias frumenti, vini, et olei: et ibi erunt vasa sanctificata, et sacerdotes, et cantores, et janitores, et ministri: et non dimittemus domum Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Habitaverunt autem principes populi in Jerusalem: reliqua vero plebs misit sortem, ut tollerent unam partem de decem qui habitaturi essent in Jerusalem civitate sancta, novem vero partes in civitatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Benedixit autem populus omnibus viris qui se sponte obtulerant ut habitarent in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Hi sunt itaque principes provinciæ qui habitaverunt in Jerusalem, et in civitatibus Juda. Habitavit autem unusquisque in possessione sua, in urbibus suis, Israël, sacerdotes, Levitæ, Nathinæi, et filii servorum Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Et in Jerusalem habitaverunt de filiis Juda, et de filiis Benjamin: de filiis Juda, Athaias filius Aziam, filii Zachariæ, filii Amariæ, filii Saphatiæ, filii Melaleel: de filiis Phares,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Maasia filius Baruch, filius Cholhoza, filius Hazia, filius Adaia, filius Jojarib, filius Zachariæ, filius Silonitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'omnes hi filii Phares, qui habitaverunt in Jerusalem, quadringenti sexaginta octo viri fortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Hi sunt autem filii Benjamin: Sellum filius Mosollam, filius Joëd, filius Phadaia, filius Colaia, filius Masia, filius Etheel, filius Isaia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'et post eum Gebbai, Sellai, nongenti viginti octo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'et Joël filius Zechri præpositus eorum, et Judas filius Senua super civitatem secundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Et de sacerdotibus, Idaia filius Joarib, Jachin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Saraia filius Helciæ, filius Mosollam, filius Sadoc, filius Meraioth, filius Achitob princeps domus Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'et fratres eorum facientes opera templi: octingenti viginti duo. Et Adaia filius Jeroham, filius Phelelia, filius Amsi, filius Zachariæ, filius Pheshur, filius Melchiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'et fratres ejus principes patrum: ducenti quadraginta duo. Et Amassai filius Azreel, filius Ahazi, filius Mosollamoth, filius Emmer,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'et fratres eorum potentes nimis: centum viginti octo, et præpositus eorum Zabdiel filius potentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Et de Levitis, Semeia filius Hasub, filius Azaricam, filius Hasabia, filius Boni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'et Sabathai et Jozabed, super omnia opera quæ erant forinsecus in domo Dei, a principibus Levitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Et Mathania filius Micha, filius Zebedei, filius Asaph, princeps ad laudandum et ad confitendum in oratione, et Becbecia secundus de fratribus ejus, et Abda filius Samua, filius Galal, filius Idithun:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'omnes Levitæ in civitate sancta ducenti octoginta quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Et janitores, Accub, Telmon, et fratres eorum, qui custodiebant ostia: centum septuaginta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Et reliqui ex Israël sacerdotes et Levitæ in universis civitatibus Juda, unusquisque in possessione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Et Nathinæi, qui habitabant in Ophel, et Siaha, et Gaspha de Nathinæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Et episcopus Levitarum in Jerusalem, Azzi filius Bani, filius Hasabiæ, filius Mathaniæ, filius Michæ. De filiis Asaph, cantores in ministerio domus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Præceptum quippe regis super eos erat, et ordo in cantoribus per dies singulos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'et Phathahia filius Mesezebel, de filiis Zara filii Juda in manu regis, juxta omne verbum populi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'et in domibus per omnes regiones eorum. De filiis Juda habitaverunt in Cariatharbe et in filiabus ejus: et in Dibon, et in filiabus ejus: et in Cabseel, et in viculis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'et in Jesue, et in Molada, et in Bethphaleth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'et in Hasersual, et in Bersabee, et in filiabus ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'et in Siceleg, et in Mochona, et in filiabus ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'et in Remmon, et in Saraa, et in Jerimuth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoa, Odollam, et in villis earum, Lachis et regionibus ejus, et Azeca, et filiabus ejus. Et manserunt in Bersabee usque ad vallem Ennom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Filii autem Benjamin, a Geba, Mechmas, et Hai, et Bethel, et filiabus ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anathoth, Nob, Anania,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Asor, Rama, Gethaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Seboim, et Neballat, Lod,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'et Ono valle artificum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Et de Levitis portiones Judæ et Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Hi sunt autem sacerdotes et Levitæ, qui ascenderunt cum Zorobabel filio Salathiel, et Josue: Saraia, Jeremias, Esdras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Melluch, Hattus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sebenias, Rheum, Merimuth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Addo, Genthon, Abia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miamin, Madia, Belga,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semeia, et Jojarib, Idaia, Sellum, Amoc, Helcias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Idaia. Isti principes sacerdotum, et fratres eorum in diebus Josue.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Porro Levitæ, Jesua, Bennui, Cedmihel, Sarebia, Juda, Mathanias, super hymnos ipsi et fratres eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'et Becbecia atque Hanni, et fratres eorum, unusquisque in officio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Josue autem genuit Joacim, et Joacim genuit Eliasib, et Eliasib genuit Jojada,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'et Jojada genuit Jonathan, et Jonathan genuit Jeddoa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'In diebus autem Joacim erant sacerdotes et principes familiarum: Saraiæ, Maraia: Jeremiæ, Hanania:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Esdræ, Mosollam: Amariæ, Johanan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Milicho, Jonathan: Sebeniæ, Joseph:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Haram, Edna: Maraioth, Helci:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Adaiæ, Zacharia: Genthon, Mosollam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abiæ, Zechri: Miamin et Moadiæ, Phelti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Belgæ, Sammua: Semaiæ, Jonathan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Jojarib, Mathanai: Jodaiæ, Azzi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Sellai, Celai: Amoc, Heber:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Helciæ, Hasebia: Idaiæ, Nathanaël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Levitæ in diebus Eliasib, et Jojada, et Johanan, et Jeddoa, scripti principes familiarum, et sacerdotes in regno Darii Persæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Filii Levi principes familiarum, scripti in libro verborum dierum, et usque ad dies Jonathan, filii Eliasib.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Et principes Levitarum, Hasebia, Serebia, et Josue filius Cedmihel: et fratres eorum per vices suas, ut laudarent et confiterentur juxta præceptum David viri Dei, et observarent æque per ordinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mathania, et Becbecia, Obedia, Mosollam, Telmon, Accub, custodes portarum et vestibulorum ante portas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Hi in diebus Joacim filii Josue, filii Josedec, et in diebus Nehemiæ ducis, et Esdræ sacerdotis scribæque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'In dedicatione autem muri Jerusalem, requisierunt Levitas de omnibus locis suis ut adducerent eos in Jerusalem, et facerent dedicationem et lætitiam in actione gratiarum, et cantico, et in cymbalis, psalteriis, et citharis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Congregati sunt autem filii cantorum de campestribus circa Jerusalem, et de villis Nethuphathi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'et de domo Galgal, et de regionibus Geba et Azmaveth: quoniam villas ædificaverunt sibi cantores in circuitu Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Et mundati sunt sacerdotes et Levitæ, et mundaverunt populum, et portas, et murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Ascendere autem feci principes Juda super murum, et statui duos magnos choros laudantium. Et ierunt ad dexteram super murum ad portam sterquilinii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Et ivit post eos Osaias, et media pars principum Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'et Azarias, Esdras, et Mosollam, Judas, et Benjamin, et Semeia, et Jeremias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Et de filiis sacerdotum in tubis, Zacharias filius Jonathan, filius Semeiæ, filius Mathaniæ, filius Michaiæ, filius Zechur, filius Asaph,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'et fratres ejus Semeia, et Azareel, Malalai, Galalai, Maai, Nathanaël, et Judas, et Hanani, in vasis cantici David viri Dei: et Esdras scriba ante eos in porta fontis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Et contra eos ascenderunt in gradibus civitatis David in ascensu muri super domum David, et usque ad portam aquarum ad orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Et chorus secundus gratias referentium ibat ex adverso, et ego post eum, et media pars populi super murum, et super turrim furnorum, et usque ad murum latissimum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'et super portam Ephraim, et super portam antiquam, et super portam piscium et turrim Hananeel, et turrim Emath, et usque ad portam gregis: et steterunt in porta custodiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'steteruntque duo chori laudantium in domo Dei, et ego, et dimidia pars magistratuum mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Et sacerdotes, Eliachim, Maasia, Miamin, Michea, Elioënai, Zacharia, Hanania in tubis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'et Maasia, et Semeia, et Eleazar, et Azzi, et Johanan, et Melchia, et \'lam, et Ezer. Et clare cecinerunt cantores, et Jezraia præpositus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'et immolaverunt in die illa victimas magnas, et lætati sunt: Deus enim lætificaverat eos lætitia magna: sed et uxores eorum et liberi gavisi sunt, et audita est lætitia Jerusalem procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Recensuerunt quoque in die illa viros super gazophylacia thesauri ad libamina, et ad primitias, et ad decimas, ut introferrent per eos principes civitatis in decore gratiarum actionis, sacerdotes et Levitas: quia lætificatus est Juda in sacerdotibus et Levitis adstantibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Et custodierunt observationem Dei sui, et observationem expiationis, et cantores, et janitores juxta præceptum David, et Salomonis filii ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'quia in diebus David et Asaph ab exordio erant principes constituti cantorum in carmine laudantium et confitentium Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Et omnis Israël in diebus Zorobabel et in diebus Nehemiæ, dabant partes cantoribus et janitoribus per dies singulos, et sanctificabant Levitas, et Levitæ sanctificabant filios Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'In die autem illo, lectum est in volumine Moysi, audiente populo: et inventum est scriptum in eo, quod non debeant introire Ammonites et Moabites in ecclesiam Dei usque in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'eo quod non occurrerint filiis Israël cum pane et aqua, et conduxerint adversum eos Balaam ad maledicendum eis: et convertit Deus noster maledictionem in benedictionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Factum est autem, cum audissent legem, separaverunt omnem alienigenam ab Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Et super hoc erat Eliasib sacerdos, qui fuerat præpositus in gazophylacio domus Dei nostri, et proximus Tobiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Fecit ergo sibi gazophylacium grande, et ibi erant ante eum reponentes munera, et thus, et vasa, et decimam frumenti, vini, et olei, partes Levitarum, et cantorum, et janitorum, et primitias sacerdotales.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'In omnibus autem his non fui in Jerusalem, quia anno trigesimo secundo Artaxerxis regis Babylonis veni ad regem, et in fine dierum rogavi regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Et veni in Jerusalem, et intellexi malum quod fecerat Eliasib Tobiæ, ut faceret ei thesaurum in vestibulis domus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Et malum mihi visum est valde. Et projeci vasa domus Tobiæ foras de gazophylacio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'præcepique et emundaverunt gazophylacia: et retuli ibi vasa domus Dei, sacrificium, et thus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Et cognovi quod partes Levitarum non fuissent datæ, et fugisset unusquisque in regionem suam de Levitis, et cantoribus, et de his qui ministrabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'et egi causam adversus magistratus, et dixi: Quare dereliquimus domum Dei? et congregavi eos, et feci stare in stationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Et omnis Juda apportabat decimam frumenti, vini, et olei, in horrea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Et constituimus super horrea Selemiam sacerdotem, et Sadoc scribam, et Phadaiam de Levitis, et juxta eos Hanan filium Zachur, filium Mathaniæ: quoniam fideles comprobati sunt, et ipsis creditæ sunt partes fratrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Memento mei, Deus meus, pro hoc, et ne deleas miserationes meas quas feci in domo Dei mei, et in cæremoniis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'In diebus illis vidi in Juda calcantes torcularia in sabbato, portantes acervos, et onerantes super asinos vinum, et uvas, et ficus, et omne onus, et inferentes in Jerusalem, die sabbati. Et contestatus sum ut in die qua vendere liceret, venderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Et Tyrii habitaverunt in ea, inferentes pisces, et omnia venalia: et vendebant in sabbatis filiis Juda in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Et objurgavi optimates Juda, et dixi eis: Quæ est hæc res mala quam vos facitis, et profanatis diem sabbati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'numquid non hæc fecerunt patres nostri, et adduxit Deus noster super nos omne malum hoc, et super civitatem hanc? et vos additis iracundiam super Israël violando sabbatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Factum est autem, cum quievissent portæ Jerusalem in die sabbati, dixi: et clauserunt januas, et præcepi ut non aperirent eas usque post sabbatum: et de pueris meis constitui super portas, ut nullus inferret onus in die sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Et manserunt negotiatores, et vendentes universa venalia, foris Jerusalem semel et bis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Et contestatus sum eos, et dixi eis: Quare manetis ex adverso muri? si secundo hoc feceritis, manum mittam in vos. Itaque ex tempore illo non venerunt in sabbato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Dixi quoque Levitis ut mundarentur, et venirent ad custodiendas portas, et sanctificandam diem sabbati: et pro hoc ergo memento mei, Deus meus, et parce mihi secundum multitudinem miserationum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Sed et in diebus illis vidi Judæos ducentes uxores Azotidas, Ammonitidas, et Moabitidas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Et filii eorum ex media parte loquebantur azotice, et nesciebant loqui judaice, et loquebantur juxta linguam populi et populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Et objurgavi eos, et maledixi. Et cecidi ex eis viros, et decalvavi eos, et adjuravi in Deo ut non darent filias suas filiis eorum, et non acciperent de filiabus eorum filiis suis et sibimetipsis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Numquid non in hujuscemodi re peccavit Salomon rex Israël? et certe in gentibus multis non erat rex similis ei, et dilectus Deo suo erat, et posuit eum Deus regem super omnem Israël: et ipsum ergo duxerunt ad peccatum mulieres alienigenæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Numquid et nos inobedientes faciemus omne malum grande hoc ut prævaricemur in Deo nostro, et ducamus uxores peregrinas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'De filiis autem Jojada filii Eliasib sacerdotis magni, gener erat Sanaballat Horonites, quem fugavi a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Recordare, Domine Deus meus, adversum eos qui polluunt sacerdotium, jusque sacerdotale et Leviticum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Igitur mundavi eos ab omnibus alienigenis, et constitui ordines sacerdotum et Levitarum, unumquemque in ministerio suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'et in oblatione lignorum in temporibus constitutis, et in primitivis: memento mei, Deus meus, in bonum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Tobias ex tribu et civitate Nephthali (quæ est in superioribus Galilææ supra Naasson, post viam quæ ducit ad occidentem, in sinistro habens civitatem Sephet)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'cum captus esset in diebus Salmanasar regis Assyriorum, in captivitate tamen positus, viam veritatis non deseruit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'ita ut omnia quæ habere poterat, quotidie concaptivis fratribus, qui erant ex ejus genere, impertiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Cumque esset junior omnibus in tribu Nephthali, nihil tamen puerile gessit in opere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Denique, cum irent omnes ad vitulos aureos quos Jeroboam fecerat rex Israël, hic solus fugiebat consortia omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Sed pergebat in Jerusalem ad templum Domini, et ibi adorabat Dominum Deum Israël, omnia primitiva sua et decimas suas fideliter offerens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'ita ut in tertio anno proselytis et advenis ministraret omnem decimationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Hæc et his similia secundum legem Dei puerulus observabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Cum vero factus esset vir, accepit uxorem Annam de tribu sua, genuitque ex ea filium, nomen suum imponens ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'quem ab infantia timere Deum docuit, et abstinere ab omni peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Igitur, cum per captivitatem devenisset cum uxore sua et filio in civitatem Niniven cum omni tribu sua');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, '(cum omnes ederent ex cibis gentilium), iste custodivit animam suam, et numquam contaminatus est in escis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Et quoniam memor fuit Domini in toto corde suo, dedit illi Deus gratiam in conspectu Salmanasar regis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'et dedit illi potestatem quocumque vellet ire, habens libertatem quæcumque facere voluisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Pergebat ergo ad omnes qui erant in captivitate, et monita salutis dabat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Cum autem venisset in Rages civitatem Medorum, et ex his quibus honoratus fuerat a rege, habuisset decem talenta argenti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'et cum in multa turba generis sui Gabelum egentem videret, qui erat ex tribu ejus, sub chirographo dedit illi memoratum pondus argenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Post multum vero temporis, mortuo Salmanasar rege, cum regnaret Sennacherib filius ejus pro eo, et filios Israël exosos haberet in conspectu suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Tobias quotidie pergebat per omnem cognationem suam, et consolabatur eos, dividebatque unicuique, prout poterat, de facultatibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'esurientes alebat, nudisque vestimenta præbebat, et mortuis atque occisis sepulturam sollicitus exhibebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Denique cum reversus esset rex Sennacherib, fugiens a Judæa plagam quam circa eum fecerat Deus propter blasphemiam suam, et iratus multos occideret ex filiis Israël, Tobias sepeliebat corpora eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'At ubi nuntiatum est regi, jussit eum occidi, et tulit omnem substantiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 23, 'Tobias vero cum filio suo et cum uxore suo fugiens, nudus latuit, quia multi diligebant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 24, 'Post dies vero quadraginta quinque occiderunt regem filii ipsius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 25, 'et reversus est Tobias in domum suam, omnisque facultas ejus restituta est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Post hæc vero, cum esset dies festus Domini, et factum esset prandium bonum in domo Tobiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'dixit filio suo: Vade, et adduc aliquos de tribu nostra, timentes Deum, ut epulentur nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Cumque abiisset, reversus nuntiavit ei unum ex filiis Israël jugulatum jacere in platea. Statimque exiliens de accubitu suo, relinquens prandium, jejunus pervenit ad corpus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'tollensque illud portavit ad domum suam occulte, ut dum sol occubuisset, caute sepeliret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Cumque occultasset corpus, manducavit panem cum luctu et tremore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'memorans illum sermonem, quem dixit Dominus per Amos prophetam: Dies festi vestri convertentur in lamentationem et luctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Cum vero sol occubuisset, abiit, et sepelivit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Arguebant autem eum omnes proximi ejus, dicentes: Jam hujus rei causa interfici jussus es, et vix effugisti mortis imperium, et iterum sepelis mortuos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Sed Tobias plus timens Deum quam regem, rapiebat corpora occisorum, et occultabat in domo sua, et mediis noctibus sepeliebat ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Contigit autem ut quadam die fatigatus a sepultura, veniens in domum suam, jactasset se juxta parietem, et obdormisset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'et ex nido hirundinum dormienti illi calida stercora inciderent super oculos ejus, fieretque cæcus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Hanc autem tentationem ideo permisit Dominus evenire illi, ut posteris daretur exemplum patientiæ ejus, sicut et sancti Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Nam cum ab infantia sua semper Deum timuerit, et mandata ejus custodierit, non est contristatus contra Deum quod plaga cæcitatis evenerit ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'sed immobilis in Dei timore permansit, agens gratias Deo omnibus diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Nam sicut beato Job insultabant reges, ita isti parentes et cognati ejus irridebant vitam ejus, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ubi est spes tua, pro qua eleemosynas et sepulturas faciebas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Tobias vero increpabat eos, dicens: Nolite ita loqui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'quoniam filii sanctorum sumus, et vitam illam expectamus, quam Deus daturus est his qui fidem suam numquam mutant ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Anna vero uxor ejus ibat ad opus textrinum quotidie, et de labore manuum suarum victum quem consequi poterat, deferebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Unde factum est ut hædum caprarum accipiens detulisset domi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'cujus cum vocem balantis vir ejus audisset, dixit: Videte, ne forte furtivus sit: reddite eum dominis suis, quia non licet nobis aut edere ex furto aliquid, aut contingere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Ad hæc uxor ejus irata respondit: Manifeste vana facta est spes tua, et eleemosynæ tuæ modo apparuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Atque his et aliis hujuscemodi verbis exprobrabat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Tunc Tobias ingemuit, et cœpit orare cum lacrimis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'dicens: Justus es, Domine, et omnia judicia tua justa sunt, et omnes viæ tuæ, misericordia, et veritas, et judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Et nunc Domine, memor esto mei, et ne vindictam sumas de peccatis meis, neque reminiscaris delicta mea, vel parentum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Quoniam non obedivimus præceptis tuis, ideo traditi sumus in direptionem, et captivitatem, et mortem, et in fabulam, et in improperium omnibus nationibus in quibus dispersisti nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et nunc Domine, magna judicia tua, quia non egimus secundum præcepta tua, et non ambulavimus sinceriter coram te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Et nunc Domine, secundum voluntatem tuam fac mecum, et præcipe in pace recipi spiritum meum: expedit enim mihi mori magis quam vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Eadem itaque die, contigit ut Sara filia Raguelis in Rages civitate Medorum et ipsa audiret improperium ab una ex ancillis patris sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'quoniam tradita fuerat septem viris, et dæmonium nomine Asmodæus occiderat eos, mox ut ingressi fuissent ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ergo cum pro culpa sua increparet puellam, respondit ei, dicens: Amplius ex te non videamus filium aut filiam super terram, interfectrix virorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Numquid et occidere me vis, sicut jam occidisti septem viros? Ad hanc vocem perrexit in superius cubiculum domus suæ: et tribus diebus, et tribus noctibus non manducavit, neque bibit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'sed in oratione persistens cum lacrimis deprecabatur Deum, ut ab isto improperio liberaret eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Factum est autem die tertia, dum compleret orationem, benedicens Dominum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'dixit: Benedictum est nomen tuum, Deus patrum nostrorum: qui cum iratus fueris, misericordiam facies, et in tempore tribulationis peccata dimittis his qui invocant te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Ad te, Domine, faciem meam converto; ad te oculos meos dirigo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Peto, Domine, ut de vinculo improperii hujus absolvas me, aut certe desuper terram eripias me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 16, 'Tu scis, Domine, quia numquam concupivi virum, et mundam servavi animam meam ab omni concupiscentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 17, 'Numquam cum ludentibus miscui me, neque cum his qui in levitate ambulant, participem me præbui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 18, 'Virum autem cum timore tuo, non cum libidine mea, consensi suscipere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 19, 'Et, aut ego indigna fui illis, aut illi forsitan me non fuerunt digni, quia forsitan viro alii conservasti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 20, 'Non est enim in hominis potestate consilium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 21, 'Hoc autem pro certo habet omnis qui te colit: quod vita ejus, si in probatione fuerit, coronabitur; si autem in tribulatione fuerit, liberabitur; et si in correptione fuerit, ad misericordiam tuam venire licebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 22, 'Non enim delectaris in perditionibus nostris: quia post tempestatem tranquillum facis, et post lacrimationem et fletum, exultationem infundis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 23, 'Sit nomen tuum, Deus Israël, benedictum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 24, 'In illo tempore exauditæ sunt preces amborum in conspectu gloriæ summi Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 25, 'et missus est angelus Domini sanctus Raphaël ut curaret eos ambos, quorum uno tempore sunt orationes in conspectu Domini recitatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Igitur cum Tobias putaret orationem suam exaudiri ut mori potuisset, vocavit ad se Tobiam filium suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'dixitque ei: Audi, fili mi, verba oris mei, et ea in corde tuo quasi fundamentum construe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Cum acceperit Deus animam meam, corpus meum sepeli: et honorem habebis matri tuæ omnibus diebus vitæ ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'memor enim esse debes, quæ et quanta pericula passa sit propter te in utero suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Cum autem et ipsa compleverit tempus vitæ suæ, sepelias eam circa me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Omnibus autem diebus vitæ tuæ in mente habeto Deum: et cave ne aliquando peccato consentias, et prætermittas præcepta Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Ex substantia tua fac eleemosynam, et noli avertere faciem tuam ab ullo paupere: ita enim fiet ut nec a te avertatur facies Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Quomodo potueris, ita esto misericors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Si multum tibi fuerit, abundanter tribue: si exiguum tibi fuerit, etiam exiguum libenter impertiri stude.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Præmium enim bonum tibi thesaurizas in die necessitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'quoniam eleemosyna ab omni peccato et a morte liberat, et non patietur animam ire in tenebras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Fiducia magna erit coram summo Deo, eleemosyna omnibus facientibus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Attende tibi, fili mi, ab omni fornicatione, et præter uxorem tuam numquam patiaris crimen scire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Superbiam numquam in tuo sensu aut in tuo verbo dominari permittas: in ipsa enim initium sumpsit omnis perditio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Quicumque tibi aliquid operatus fuerit, statim ei mercedem restitue, et merces mercenarii tui apud te omnino non remaneat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Quod ab alio oderis fieri tibi, vide ne tu aliquando alteri facias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Panem tuum cum esurientibus et egenis comede, et de vestimentis tuis nudos tege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 18, 'Panem tuum et vinum tuum super sepulturam justi constitue, et noli ex eo manducare et bibere cum peccatoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 19, 'Consilium semper a sapiente perquire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 20, 'Omni tempore benedic Deum: et pete ab eo ut vias tuas dirigat, et omnia consilia tua in ipso permaneant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 21, 'Indico etiam tibi, fili mi, dedisse me decem talenta argenti, dum adhuc infantulus esses, Gabelo, in Rages civitate Medorum, et chirographum ejus apud me habeo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 22, 'et ideo perquire quomodo ad eum pervenias, et recipias ab eo supra memoratum pondus argenti, et restituas ei chirographum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 23, 'Noli timere, fili mi: pauperem quidem vitam gerimus, sed multa bona habebimus si timuerimus Deum, et recesserimus ab omni peccato, et fecerimus bene.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Tunc respondit Tobias patri suo, et dixit: Omnia quæcumque præcepisti mihi faciam, pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Quomodo autem pecuniam hanc requiram, ignoro: ille me nescit, et ego eum ignoro: quod signum dabo ei? sed neque viam per quam pergatur illuc aliquando cognovi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Tunc pater suus respondit illi, et dixit: Chirographum quidem illius penes me habeo: quod dum illi ostenderis, statim restituet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Sed perge nunc, et inquire tibi aliquem fidelem virum, qui eat tecum salva mercede sua, ut dum adhuc vivo, recipias eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Tunc egressus Tobias, invenit juvenem splendidum stantem præcinctum, et quasi paratum ad ambulandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et ignorans quod angelus Dei esset, salutavit eum, et dixit: Unde te habemus, bone juvenis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'At ille respondit: Ex filiis Israël. Et Tobias dixit ei: Nosti viam quæ ducit in regionem Medorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Cui respondit: Novi: et omnia itinera ejus frequenter ambulavi, et mansi apud Gabelum fratrem nostrum, qui moratur in Rages civitate Medorum, quæ posita est in monte Ecbatanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Cui Tobias ait: Sustine me obsecro, donec hæc ipsa nuntiem patri meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Tunc ingressus Tobias, indicavit universa hæc patri suo. Super quæ admiratus pater, rogavit ut introiret ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Ingressus itaque salutavit eum, et dixit: Gaudium tibi sit semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Et ait Tobias: Quale gaudium mihi erit, qui in tenebris sedeo, et lumen cæli non video?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Cui ait juvenis: Forti animo esto: in proximo est ut a Deo cureris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Dixit itaque illi Tobias: Numquid poteris perducere filium meum ad Gabelum in Rages civitatem Medorum? et cum redieris, restituam tibi mercedem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 15, 'Et dixit ei angelus: Ego ducam, et reducam eum ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 16, 'Cui Tobias respondit: Rogo te, indica mihi de qua domo aut de qua tribu es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 17, 'Cui Raphaël angelus dixit: Genus quæris mercenarii, an ipsum mercenarium qui cum filio tuo eat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 18, 'sed ne forte sollicitum te reddam, ego sum Azarias Ananiæ magni filius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 19, 'Et Tobias respondit: Ex magno genere es tu. Sed peto ne irascaris quod voluerim cognoscere genus tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 20, 'Dixit autem illi angelus: Ego sanum ducam, et sanum tibi reducam filium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 21, 'Respondens autem Tobias, ait: Bene ambuletis, et sit Deus in itinere vestro, et angelus ejus comitetur vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 22, 'Tunc paratis omnibus quæ erant in via portanda, fecit Tobias vale patri suo et matri suæ, et ambulaverunt ambo simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 23, 'Cumque profecti essent, cœpit mater ejus flere, et dicere: Baculum senectutis nostræ tulisti, et transmisisti a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 24, 'Numquam fuisset ipsa pecunia, pro qua misisti eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 25, 'sufficiebat enim nobis paupertas nostra, ut divitias computaremus hoc, quod videbamus filium nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 26, 'Dixitque ei Tobias: Noli flere: salvus perveniet filius noster, et salvus revertetur ad nos, et oculi tui videbunt illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 27, 'Credo enim quod angelus Dei bonus comitetur ei, et bene disponat omnia quæ circa eum geruntur, ita ut cum gaudio revertatur ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 28, 'Ad hanc vocem cessavit mater ejus flere, et tacuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Profectus est autem Tobias, et canis secutus est eum, et mansit prima mansione juxta fluvium Tigris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Et exivit ut lavaret pedes suos, et ecce piscis immanis exivit ad devorandum eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Quem expavescens Tobias clamavit voce magna, dicens: Domine, invadit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Et dixit ei angelus: Apprehende branchiam ejus, et trahe eum ad te. Quod cum fecisset, attraxit eum in siccum, et palpitare cœpit ante pedes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Tunc dixit ei angelus: Exentera hunc piscem, et cor ejus, et fel, et jecur repone tibi: sunt enim hæc necessaria ad medicamenta utiliter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Quod cum fecisset, assavit carnes ejus, et secum tulerunt in via: cetera salierunt, quæ sufficerent eis, quousque pervenirent in Rages civitatem Medorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Tunc interrogavit Tobias angelum, et dixit ei: Obsecro te, Azaria frater, ut dicas mihi quod remedium habebunt ista, quæ de pisce servare jussisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Et respondens angelus, dixit ei: Cordis ejus particulam si super carbones ponas, fumus ejus extricat omne genus dæmoniorum sive a viro, sive a muliere, ita ut ultra non accedat ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Et fel valet ad ungendos oculos in quibus fuerit albugo, et sanabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Et dixit ei Tobias: Ubi vis ut maneamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Respondensque angelus, ait: Est hic Raguel nomine, vir propinquus de tribu tua, et hic habet filiam nomine Saram, sed neque masculum neque feminam ullam habet aliam præter eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Tibi debetur omnis substantia ejus, et oportet eam te accipere conjugem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Pete ergo eam a patre ejus, et dabit tibi eam in uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Tunc respondit Tobias, et dixit: Audio quia tradita est septem viris, et mortui sunt: sed et hoc audivi, quia dæmonium occidit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 15, 'Timeo ergo, ne forte et mihi hæc eveniant: et cum sim unicus parentibus meis, deponam senectutem illorum cum tristitia ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 16, 'Tunc angelus Raphaël dixit ei: Audi me, et ostendam tibi qui sunt, quibus prævalere potest dæmonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 17, 'Hi namque qui conjugium ita suscipiunt, ut Deum a se et a sua mente excludant, et suæ libidini ita vacent sicut equus et mulus quibus non est intellectus: habet potestatem dæmonium super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 18, 'Tu autem cum acceperis eam, ingressus cubiculum, per tres dies continens esto ab ea, et nihil aliud nisi orationibus vacabis cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 19, 'Ipsa autem nocte, incenso jecore piscis, fugabitur dæmonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 20, 'Secunda vero nocte in copulatione sanctorum patriarcharum admitteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 21, 'Tertia autem nocte, benedictionem consequeris, ut filii ex vobis procreentur incolumes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 22, 'Transacta autem tertia nocte, accipies virginem cum timore Domini, amore filiorum magis quam libidine ductus, ut in semine Abrahæ benedictionem in filiis consequaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Ingressi sunt autem ad Raguelem, et suscepit eos Raguel cum gaudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Intuensque Tobiam Raguel, dixit Annæ uxori suæ: Quam similis est juvenis iste consobrino meo!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Et cum hæc dixisset, ait: Unde estis juvenes fratres nostri? At illi dixerunt: Ex tribu Nephthali sumus, ex captivitate Ninive.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Dixitque illis Raguel: Nostis Tobiam fratrem meum? Qui dixerunt: Novimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Cumque multa bona loqueretur de eo, dixit angelus ad Raguelem: Tobias, de quo interrogas, pater istius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Et misit se Raguel, et cum lacrimis osculatus est eum, et plorans supra collum ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'dixit: Benedictio sit tibi, fili mi, quia boni et optimi viri filius es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Et Anna uxor ejus, et Sara ipsorum filia, lacrimatæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Postquam autem locuti sunt, præcepit Raguel occidi arietem, et parari convivium. Cumque hortaretur eos discumbere ad prandium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Tobias dixit: Hic ego hodie non manducabo neque bibam, nisi prius petitionem meam confirmes, et promittas mihi dare Saram filiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 11, 'Quo audito verbo Raguel expavit, sciens quid evenerit illis septem viris qui ingressi sunt ad eam: et timere cœpit ne forte et hunc similiter contingeret. Et cum nutaret, et non daret petenti ullum responsum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 12, 'dixit ei angelus: Noli timere dare eam isti, quoniam huic timenti Deum debetur conjux filia tua: propterea alius non potuit habere illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 13, 'Tunc dixit Raguel: Non dubito quod Deus preces et lacrimas meas in conspectu suo admiserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 14, 'Et credo quoniam ideo fecit vos venire ad me, ut ista conjungeretur cognationi suæ secundum legem Moysi: et nunc noli dubium gerere quod tibi eam tradam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 15, 'Et apprehendens dexteram filiæ suæ, dexteræ Tobiæ tradidit, dicens: Deus Abraham, et Deus Isaac, et Deus Jacob vobiscum sit, et ipse conjungat vos, impleatque benedictionem suam in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 16, 'Et accepta carta, fecerunt conscriptionem conjugii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 17, 'Et post hæc epulati sunt, benedicentes Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 18, 'Vocavitque Raguel ad se Annam uxorem suam, et præcepit ei ut præpararet alterum cubiculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 19, 'Et introduxit illuc Saram filiam suam, et lacrimata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 20, 'Dixitque ei: Forti animo esto, filia mea: Dominus cæli det tibi gaudium pro tædio quod perpessa es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Postquam vero cœnaverunt, introduxerunt juvenem ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Recordatus itaque Tobias sermonum angeli, protulit de cassidili suo partem jecoris, posuitque eam super carbones vivos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Tunc Raphaël angelus apprehendit dæmonium, et religavit illud in deserto superioris \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Tunc hortatus est virginem Tobias, dixitque ei: Sara, exsurge, et deprecemur Deum hodie, et cras, et secundum cras: quia his tribus noctibus Deo jungimur; tertia autem transacta nocte, in nostro erimus conjugio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Filii quippe sanctorum sumus, et non possumus ita conjungi sicut gentes quæ ignorant Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Surgentes autem pariter, instanter orabant ambo simul, ut sanitas daretur eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Dixitque Tobias: Domine Deus patrum nostrorum, benedicant te cæli et terræ, mareque et fontes, et flumina, et omnes creaturæ tuæ quæ in eis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Tu fecisti Adam de limo terræ, dedistique ei adjutorium Hevam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Et nunc Domine, tu scis quia non luxuriæ causa accipio sororem meam conjugem, sed sola posteritatis dilectione, in qua benedicatur nomen tuum in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Dixit quoque Sara: Miserere nobis Domine, miserere nobis, et consenescamus ambo pariter sani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Et factum est circa pullorum cantum, accersiri jussit Raguel servos suos, et abierunt cum eo pariter ut foderent sepulchrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Dicebat enim: Ne forte simili modo evenerit ei, quo et ceteris illis septem viris qui sunt ingressi ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Cumque parassent fossam, reversus Raguel ad uxorem suam, dixit ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Mitte unam de ancillis tuis, et videat si mortuus est, ut sepeliam eum antequam illucescat dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'At illa misit unam ex ancillis suis. Quæ ingressa cubiculum, reperit eos salvos et incolumes, secum pariter dormientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Et reversa nuntiavit bonum nuntium: et benedixerunt Dominum, Raguel videlicet et Anna uxor ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'et dixerunt: Benedicimus te, Domine Deus Israël, quia non contigit quemadmodum putabamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 18, 'Fecisti enim nobiscum misericordiam tuam, et exclusisti a nobis inimicum persequentem nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 19, 'Misertus es autem duobus unicis. Fac eos, Domine, plenius benedicere te, et sacrificium tibi laudis tuæ et suæ sanitatis offerre, ut cognoscat universitas gentium quia tu es Deus solus in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 20, 'Statimque præcepit servis suis Raguel ut replerent fossam quam fecerant priusquam elucesceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 21, 'Uxori autem suæ dixit ut instrueret convivium, et præpararet omnia quæ in cibos erant iter agentibus necessaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 22, 'Duas quoque pingues vaccas, et quatuor arietes, occidi fecit, et parari epulas omnibus vicinis suis, cunctisque amicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 23, 'Et adjuravit Raguel Tobiam ut duas hebdomadas moraretur apud se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 24, 'De omnibus autem quæ possidebat Raguel, dimidiam partem dedit Tobiæ, et fecit scripturam, ut pars dimidia quæ supererat, post obitum eorum Tobiæ dominio deveniret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Tunc vocavit Tobias angelum ad se, quem quidem hominem existimabat, dixitque ei: Azaria frater, peto ut auscultes verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Si meipsum tradam tibi servum, non ero condignus providentiæ tuæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'tamen obsecro te ut assumas tibi animalia sive servitia, et vadas ad Gabelum in Rages civitatem Medorum, reddasque ei chirographum suum, et recipias ab eo pecuniam, et roges eum venire ad nuptias meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Scis enim ipse quoniam numerat pater meus dies, et si tardavero una die plus, contristatur anima ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Et certe vides quomodo adjuravit me Raguel, cujus adjuramentum spernere non possum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Tunc Raphaël assumens quatuor ex servis Raguelis, et duos camelos, in Rages civitatem Medorum perrexit: et inveniens Gabelum, reddidit ei chirographum suum, et recepit ab eo omnem pecuniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Indicavitque ei de Tobia filio Tobiæ omnia quæ gesta sunt, fecitque eum secum venire ad nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Cumque ingressus esset domum Raguelis, invenit Tobiam discumbentem: et exiliens, osculati sunt se invicem: et flevit Gabelus, benedixitque Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'et dixit: Benedicat te Deus Israël, quia filius es optimi viri et justi, et timentis Deum, et eleemosynas facientis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'et dicatur benedictio super uxorem tuam, et super parentes vestros,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'et videatis filios vestros, et filios filiorum vestrorum, usque in tertiam et quartam generationem: et sit semen vestrum benedictum a Deo Israël, qui regnat in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Cumque omnes dixissent: Amen: accesserunt ad convivium: sed et cum timore Domini nuptiarum convivium exercebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Cum vero moras faceret Tobias, causa nuptiarum, sollicitus erat pater ejus Tobias, dicens: Putas quare moratur filius meus, aut quare detentus est ibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Putasne Gabelus mortuus est, et nemo reddet illi pecuniam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Cœpit autem contristari nimis ipse, et Anna uxor ejus cum eo: et cœperunt ambo simul flere, eo quod die statuto minime reverteretur filius eorum ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 4, 'Flebat igitur mater ejus irremediabilibus lacrimis, atque dicebat: Heu, heu me, fili mi! ut quid te misimus peregrinari, lumen oculorum nostrorum, baculum senectutis nostræ, solatium vitæ nostræ, spem posteritatis nostræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 5, 'omnia simul in te uno habentes, te non debuimus dimittere a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 6, 'Cui dicebat Tobias: Tace, et noli turbari: sanus est filius noster: satis fidelis est vir ille, cum quo misimus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 7, 'Illa autem nullo modo consolari poterat, sed quotidie exiliens circumspiciebat, et circuibat vias omnes per quas spes remeandi videbatur, ut procul videret eum, si fieri posset, venientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 8, 'At vero Raguel dicebat ad generum suum: Mane hic, et ego mittam nuntium salutis de te ad Tobiam patrem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 9, 'Cui Tobias ait: Ego novi quia pater meus et mater mea modo dies computant, et cruciatur spiritus eorum in ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 10, 'Cumque verbis multis rogaret Raguel Tobiam, et ille eum nulla ratione vellet audire, tradidit ei Saram, et dimidiam partem omnis substantiæ suæ in pueris, in puellis, in pecudibus, in camelis, et in vaccis, et in pecunia multa: et salvum atque gaudentem dimisit eum a se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 11, 'dicens: Angelus Domini sanctus sit in itinere vestro, perducatque vos incolumes, et inveniatis omnia recte circa parentes vestros, et videant oculi mei filios vestros priusquam moriar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 12, 'Et apprehendentes parentes filiam suam, osculati sunt eam: et dimiserunt ire,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 13, 'monentes eam honorare soceros, diligere maritum, regere familiam, gubernare domum, et seipsam irreprehensibilem exhibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 1, 'Cumque reverterentur, pervenerunt ad Charan, quæ est in medio itinere contra Niniven, undecimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 2, 'Dixitque angelus: Tobia frater, scis quemadmodum reliquisti patrem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 3, 'Si placet itaque tibi, præcedamus, et lento gradu sequantur iter nostrum familiæ, simul cum conjuge tua, et cum animalibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 4, 'Cumque hoc placuisset ut irent, dixit Raphaël ad Tobiam: Tolle tecum ex felle piscis: erit enim necessarium. Tulit itaque Tobias ex felle illo, et abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 5, 'Anna autem sedebat secus viam quotidie in supercilio montis, unde respicere poterat de longinquo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 6, 'Et dum ex eodem loco specularetur adventum ejus, vidit a longe, et illico agnovit venientem filium suum: currensque nuntiavit viro suo, dicens: Ecce venit filius tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 7, 'Dixitque Raphaël ad Tobiam: At ubi introieris domum tuam, statim adora Dominum Deum tuum: et gratias agens ei, accede ad patrem tuum, et osculare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 8, 'Statimque lini super oculos ejus ex felle isto piscis, quod portas tecum: scias enim quoniam mox aperientur oculi ejus, et videbit pater tuus lumen cæli, et in aspectu tuo gaudebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 9, 'Tunc præcucurrit canis, qui simul fuerat in via: et quasi nuntius adveniens, blandimento suæ caudæ gaudebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 10, 'Et consurgens cæcus pater ejus, cœpit offendens pedibus currere: et data manu puero, occurrit obviam filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 11, 'Et suscipiens osculatus est eum cum uxore sua, et cœperunt ambo flere præ gaudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 12, 'Cumque adorassent Deum, et gratias egissent, consederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 13, 'Tunc sumens Tobias de felle piscis, linivit oculos patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 14, 'Et sustinuit quasi dimidiam fere horam: et cœpit albugo ex oculis ejus, quasi membrana ovi, egredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 15, 'Quam apprehendens Tobias, traxit ab oculis ejus: statimque visum recepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 16, 'Et glorificabant Deum, ipse videlicet et uxor ejus, et omnes qui sciebant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 17, 'Dicebatque Tobias: Benedico te, Domine Deus Israël, quia tu castigasti me, et tu salvasti me: et ecce ego video Tobiam filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 18, 'Ingressa est etiam post septem dies Sara uxor filii ejus et omnis familia sana, et pecora, et cameli, et pecunia multa uxoris; sed et illa pecunia, quam receperat a Gabelo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 19, 'Et narravit parentibus suis omnia beneficia Dei, quæ fecisset circa eum per hominem qui eum duxerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 20, 'Veneruntque Achior et Nabath consobrini Tobiæ gaudentes ad Tobiam, et congratulantes ei de omnibus bonis quæ circa illum ostenderat Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 11, 21, 'Et per septem dies epulantes, omnes cum gaudio magno gavisi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 1, 'Tunc vocavit ad se Tobias filium suum, dixitque ei: Quid possumus dare viro isti sancto, qui venit tecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 2, 'Respondens Tobias, dixit patri suo: Pater, quam mercedem dabimus ei? aut quid dignum poterit esse beneficiis ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 3, 'Me duxit et reduxit sanum, pecuniam a Gabelo ipse recepit, uxorem ipse me habere fecit, et dæmonium ab ea ipse compescuit: gaudium parentibus ejus fecit, meipsum a devoratione piscis eripuit, te quoque videre fecit lumen cæli, et bonis omnibus per eum repleti sumus. Quid illi ad hæc poterimus dignum dare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 4, 'Sed peto te, pater mi, ut roges eum, si forte dignabitur medietatem de omnibus quæ allata sunt, sibi assumere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 5, 'Et vocantes eum, pater scilicet et filius, tulerunt eum in partem: et rogare cœperunt ut dignaretur dimidiam partem omnium quæ attulerant acceptam habere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 6, 'Tunc dixit eis occulte: Benedicite Deum cæli, et coram omnibus viventibus confitemini ei, quia fecit vobiscum misericordiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 7, 'Etenim sacramentum regis abscondere bonum est: opera autem Dei revelare et confiteri honorificum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 8, 'Bona est oratio cum jejunio, et eleemosyna magis quam thesauros auri recondere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 9, 'quoniam eleemosyna a morte liberat, et ipsa est quæ purgat peccata, et facit invenire misericordiam et viam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 10, 'Qui autem faciunt peccatum et iniquitatem, hostes sunt animæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 11, 'Manifesto ergo vobis veritatem, et non abscondam a vobis occultum sermonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 12, 'Quando orabas cum lacrimis, et sepeliebas mortuos, et derelinquebas prandium tuum, et mortuos abscondebas per diem in domo tua, et nocte sepeliebas eos, ego obtuli orationem tuam Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 13, 'Et quia acceptus eras Deo, necesse fuit ut tentatio probaret te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 14, 'Et nunc misit me Dominus ut curarem te, et Saram uxorem filii tui a dæmonio liberarem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 15, 'Ego enim sum Raphaël angelus, unus ex septem qui adstamus ante Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 16, 'Cumque hæc audissent, turbati sunt, et trementes ceciderunt super terram in faciem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 17, 'Dixitque eis angelus: Pax vobis: nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 18, 'Etenim cum essem vobiscum, per voluntatem Dei eram: ipsum benedicite, et cantate illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 19, 'Videbar quidem vobiscum manducare et bibere: sed ego cibo invisibili, et potu qui ab hominibus videri non potest, utor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 20, 'Tempus est ergo ut revertar ad eum qui me misit: vos autem benedicite Deum, et narrate omnia mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 21, 'Et cum hæc dixisset, ab aspectu eorum ablatus est, et ultra eum videre non potuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 12, 22, 'Tunc prostrati per horas tres in faciem, benedixerunt Deum: et exsurgentes narraverunt omnia mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 1, 'Aperiens autem Tobias senior os suum, benedixit Dominum, et dixit: Magnus es, Domine, in æternum, et in omnia sæcula regnum tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 2, 'quoniam tu flagellas, et salvas; deducis ad inferos, et reducis: et non est qui effugiat manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 3, 'Confitemini Domino, filii Israël, et in conspectu gentium laudate eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 4, 'quoniam ideo dispersit vos inter gentes quæ ignorant eum, ut vos enarretis mirabilia ejus, et faciatis scire eos quia non est alius deus omnipotens præter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 5, 'Ipse castigavit nos propter iniquitates nostras, et ipse salvabit nos propter misericordiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 6, 'Aspicite ergo quæ fecit nobiscum, et cum timore et tremore confitemini illi: regemque sæculorum exaltate in operibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 7, 'Ego autem in terra captivitatis meæ confitebor illi: quoniam ostendit majestatem suam in gentem peccatricem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 8, 'Convertimini itaque peccatores, et facite justitiam coram Deo, credentes quod faciat vobiscum misericordiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 9, 'Ego autem et anima mea in eo lætabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 10, 'Benedicite Dominum omnes electi ejus: agite dies lætitiæ, et confitemini illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 11, 'Jerusalem civitas Dei, castigavit te Dominus in operibus manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 12, 'Confitere Domino in bonis tuis, et benedic Deum sæculorum: ut reædificet in te tabernaculum suum, et revocet ad te omnes captivos, et gaudeas in omnia sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 13, 'Luce splendida fulgebis, et omnes fines terræ adorabunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 14, 'Nationes ex longinquo ad te venient, et munera deferentes adorabunt in te Dominum, et terram tuam in sanctificationem habebunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 15, 'nomen enim magnum invocabunt in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 16, 'Maledicti erunt qui contempserint te, et condemnati erunt omnes qui blasphemaverint te: benedictique erunt qui ædificaverint te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 17, 'Tu autem lætaberis in filiis tuis, quoniam omnes benedicentur, et congregabuntur ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 18, 'Beati omnes qui diligunt te, et qui gaudent super pace tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 19, 'Anima mea, benedic Dominum, quoniam liberavit Jerusalem civitatem suam a cunctis tribulationibus ejus Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 20, 'Beatus ero si fuerint reliquiæ seminis mei ad videndam claritatem Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 21, 'Portæ Jerusalem ex sapphiro et smaragdo ædificabuntur, et ex lapide pretioso omnis circuitus murorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 22, 'Ex lapide candido et mundo omnes plateæ ejus sternentur, et per vicos ejus alleluja cantabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 13, 23, 'Benedictus Dominus, qui exaltavit eam, et sit regnum ejus in sæcula sæculorum super eam. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 1, 'Et consummati sunt sermones Tobiæ. Et postquam illuminatus est Tobias, vixit annis quadraginta duobus, et vidit filios nepotum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 2, 'Completis itaque annis centum duobus, sepultus est honorifice in Ninive.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 3, 'Quinquaginta namque et sex annorum lumen oculorum amisit, sexagenarius vero recepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 4, 'Reliquum vero vitæ suæ in gaudio fuit, et cum bono profectu timoris Dei perrexit in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 5, 'In hora autem mortis suæ vocavit ad se Tobiam filium suum, et septem juvenes filios ejus nepotes suos, dixitque eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 6, 'Prope erit interitus Ninive: non enim excidit verbum Domini: et fratres nostri, qui dispersi sunt a terra Israël, revertentur ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 7, 'Omnis autem deserta terra ejus replebitur, et domus Dei, quæ in ea incensa est, iterum reædificabitur: ibique revertentur omnes timentes Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 8, 'et relinquent gentes idola sua, et venient in Jerusalem, et inhabitabunt in ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 9, 'et gaudebunt in ea omnes reges terræ, adorantes regem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 10, 'Audite ergo, filii mei, patrem vestrum: servite Domino in veritate, et inquirite ut faciatis quæ placita sunt illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 11, 'et filiis vestris mandate ut faciant justitias et eleemosynas, ut sint memores Dei, et benedicant eum in omni tempore in veritate, et in tota virtute sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 12, 'Nunc ergo filii, audite me, et nolite manere hic: sed quacumque die sepelieritis matrem vestram circa me in uno sepulchro, ex eo dirigite gressus vestros ut exeatis hinc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 13, 'video enim quia iniquitas ejus finem dabit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 14, 'Factum est autem post obitum matris suæ, Tobias abscessit ex Ninive cum uxore sua, et filiis, et filiorum filiis, et reversus est ad soceros suos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 15, 'invenitque eos incolumes in senectute bona: et curam eorum gessit, et ipse clausit oculos eorum: et omnem hæreditatem domus Raguelis ipse percepit: viditque quintam generationem, filios filiorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 16, 'Et completis annis nonaginta novem in timore Domini, cum gaudio sepelierunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 14, 17, 'Omnis autem cognatio ejus et omnis generatio ejus in bona vita et in sancta conversatione permansit, ita ut accepti essent tam Deo quam hominibus, et cunctis habitantibus in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Arphaxad itaque, rex Medorum, subjugaverat multas gentes imperio suo, et ipse ædificavit civitatem potentissimam, quam appellavit Ecbatanis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'ex lapidibus quadratis et sectis: fecit muros ejus in altitudinem cubitorum septuaginta, et in latitudinem cubitorum triginta: turres vero ejus posuit in altitudinem cubitorum centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Per quadrum vero earum latus utrumque vicenorum pedum spatio tendebatur, posuitque portas ejus in altitudinem turrium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'et gloriabatur quasi potens in potentia exercitus sui, et in gloria quadrigarum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Anno igitur duodecimo regni sui, Nabuchodonosor rex Assyriorum, qui regnabat in Ninive civitate magna, pugnavit contra Arphaxad, et obtinuit eum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'in campo magno qui appellatur Ragau, circa Euphraten, et Tigrin, et Jadason, in campo Erioch regis Elicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Tunc exaltatum est regnum Nabuchodonosor, et cor ejus elevatum est: et misit ad omnes qui habitabant in Cilicia, et Damasco, et Libano,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'et ad gentes quæ sunt in Carmelo et Cedar, et inhabitantes Galilæam in campo magno Esdrelon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'et ad omnes qui erant in Samaria, et trans flumen Jordanem usque ad Jerusalem, et omnem terram Jesse quousque perveniatur ad terminos \'thiopiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Ad hos omnes misit nuntios Nabuchodonosor rex Assyriorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'qui omnes uno animo contradixerunt, et remiserunt eos vacuos, et sine honore abjecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Tunc indignatus Nabuchodonosor rex adversus omnem terram illam, juravit per thronum et regnum suum quod defenderet se de omnibus regionibus his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Anno tertiodecimo Nabuchodonosor regis, vigesima et secunda die mensis primi, factum est verbum in domo Nabuchodonosor regis Assyriorum ut defenderet se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Vocavitque omnes majores natu, omnesque duces et bellatores suos, et habuit cum eis mysterium consilii sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'dixitque cogitationem suam in eo esse, ut omnem terram suo subjugaret imperio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Quod dictum cum placuisset omnibus, vocavit Nabuchodonosor rex Holofernem principem militiæ suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'et dixit ei: Egredere adversus omne regnum occidentis, et contra eos præcipue, qui contempserunt imperium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Non parcet oculus tuus ulli regno, omnemque urbem munitam subjugabis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Tunc Holofernes vocavit duces et magistratus virtutis Assyriorum, et dinumeravit viros in expeditionem sicut præcepit ei rex, centum viginti millia peditum pugnatorum, et equitum sagittariorum duodecim millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Omnemque expeditionem suam fecit præire in multitudine innumerabilium camelorum, cum his quæ exercitibus sufficerent copiose, boum quoque armenta, gregesque ovium, quorum non erat numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Frumentum ex omni Syria in transitu suo parari constituit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Aurum vero et argentum de domo regis assumpsit multum nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et profectus est ipse, et omnis exercitus cum quadrigis, et equitibus, et sagittariis: qui cooperuerunt faciem terræ sicut locustæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Cumque pertransisset fines Assyriorum, venit ad magnos montes Ange, qui sunt a sinistro Ciliciæ: ascenditque omnia castella eorum, et obtinuit omnem munitionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Effregit autem civitatem opinatissimam Melothi, prædavitque omnes filios Tharsis et filios Ismaël qui erant contra faciem deserti, et ad austrum terræ Cellon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 14, 'Et transivit Euphraten, et venit in Mesopotamiam: et fregit omnes civitates excelsas quæ erant ibi, a torrente Mambre usquequo perveniatur ad mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 15, 'et occupavit terminos ejus, a Cilicia usque ad fines Japheth qui sunt ad austrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 16, 'Abduxitque omnes filios Madian, et prædavit omnem locupletationem eorum, omnesque resistentes sibi occidit in ore gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 17, 'Et post hæc descendit in campos Damasci in diebus messis, et succendit omnia sata, omnesque arbores, et vineas fecit incidi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 18, 'et cecidit timor illius super omnes inhabitantes terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Tunc miserunt legatos suos universarum urbium ac provinciarum reges ac principes, Syriæ scilicet Mesopotamiæ, et Syriæ Sobal, et Libyæ, atque Ciliciæ: qui venientes ad Holofernem, dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Desinat indignatio tua circa nos: melius est enim ut viventes serviamus Nabuchodonosor regi magno, et subditi simus tibi, quam morientes cum interitu nostro ipsi servitutis nostræ damna patiamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Omnis civitas nostra, omnisque possessio, omnes montes, et colles, et campi, et armenta boum, gregesque ovium, et caprarum, equorumque et camelorum, et universæ facultates nostræ atque familiæ, in conspectu tuo sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'sint omnia nostra sub lege tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Nos, et filii nostri, servi tui sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Veni nobis pacificus dominus, et utere servitio nostro, sicut placuerit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Tunc descendit de montibus cum equitibus in virtute magna, et obtinuit omnem civitatem, et omnem inhabitantem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'De universis autem urbibus assumpsit sibi auxiliarios viros fortes, et electos ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Tantusque metus provinciis illis incubuit, ut universarum urbium habitatores principes et honorati simul cum populis exirent obviam venienti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'excipientes eum cum coronis et lampadibus, ducentes choros in tympanis et tibiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Nec ista tamen facientes, ferocitatem ejus pectoris mitigare potuerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'nam et civitates eorum destruxit, et lucos eorum excidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Præceperat enim illi Nabuchodonosor rex, ut omnes deos terræ exterminaret, videlicet ut ipse solus diceretur deus ab his nationibus quæ potuissent Holofernis potentia subjugari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Pertransiens autem Syriam Sobal, et omnem Apameam, omnemque Mesopotamiam, venit ad Idumæos in terram Gabaa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'accepitque civitates eorum, et sedit ibi per triginta dies, in quibus diebus adunari præcepit universum exercitum virtutis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Tunc audientes hæc filii Israël qui habitabant in terra Juda, timuerunt valde a facie ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Tremor et horror invasit sensus eorum, ne hoc faceret Jerusalem et templo Domini, quod fecerat ceteris civitatibus et templis earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Et miserunt in omnem Samariam per circuitum usque Jericho, et præoccupaverunt omnes vertices montium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'et muris circumdederunt vicos suos, et congregaverunt frumenta in præparationem pugnæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Sacerdos etiam Eliachim scripsit ad universos qui erant contra Esdrelon, quæ est contra faciem campi magni juxta Dothain, et universos per quos viæ transitus esse poterat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'ut obtinerent ascensus montium, per quos via esse poterat ad Jerusalem, et illic custodirent ubi angustum iter esse poterat inter montes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Et fecerunt filii Israël secundum quod constituerat eis sacerdos Domini Eliachim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Et clamavit omnis populus ad Dominum instantia magna, et humiliaverunt animas suas in jejuniis et orationibus, ipsi et mulieres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Et induerunt se sacerdotes ciliciis, et infantes prostraverunt contra faciem templi Domini, et altare Domini operuerunt cilicio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'et clamaverunt ad Dominum Deum Israël unanimiter ne darentur in prædam infantes eorum, et uxores eorum in divisionem, et civitates eorum in exterminium, et sancta eorum in pollutionem, et fierent opprobrium gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Tunc Eliachim sacerdos Domini magnus circuivit omnem Israël, allocutusque est eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'dicens: Scitote quoniam exaudiet Dominus preces vestras, si manentes permanseritis in jejuniis et orationibus in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Memores estote Moysi servi Domini, qui Amalec confidentem in virtute sua, et in potentia sua, et in exercitu suo, et in clypeis suis, et in curribus suis, et in equitibus suis, non ferro pugnando, sed precibus sanctis orando dejecit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'sic erunt universi hostes Israël, si perseveraveritis in hoc opere quod cœpistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Ad hanc igitur exhortationem ejus deprecantes Dominum, permanebant in conspectu Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'ita ut etiam hi qui offerebant Domino holocausta, præcincti ciliciis offerrent sacrificia Domino, et erat cinis super capita eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Et ex toto corde suo omnes orabant Deum, ut visitaret populum suum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Nuntiatumque est Holoferni principi militiæ Assyriorum, quod filii Israël præpararent se ad resistendum, ac montium itinera conclusissent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'et furore nimio exarsit in iracundia magna, vocavitque omnes principes Moab et duces Ammon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'et dixit eis: Dicite mihi quis sit populus iste, qui montana obsidet: aut quæ, et quales, et quantæ sint civitates eorum: quæ etiam sit virtus eorum, aut quæ sit multitudo eorum, vel quis rex militiæ illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'et quare præ omnibus qui habitant in oriente, isti contempserunt nos, et non exierunt obviam nobis ut susciperent nos cum pace?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Tunc Achior dux omnium filiorum Ammon respondens, ait: Si digneris audire, domine mi, dicam veritatem in conspectu tuo de populo isto qui in montanis habitat, et non egredietur verbum falsum ex ore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Populus iste ex progenie Chaldæorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Hic primum in Mesopotamia habitavit, quoniam noluerunt sequi deos patrum suorum, qui erant in terra Chaldæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Deserentes itaque cæremonias patrum suorum, quæ in multitudine deorum erant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'unum Deum cæli coluerunt, qui et præcepit eis ut exirent inde et habitarent in Charan. Cumque operuisset omnem terram fames, descenderunt in \'gyptum, illicque per quadringentos annos sic multiplicati sunt, ut dinumerari eorum non posset exercitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Cumque gravaret eos rex \'gypti, atque in ædificationibus urbium suarum in luto et latere subjugasset eos, clamaverunt ad Dominum suum, et percussit totam terram \'gypti plagis variis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Cumque ejecissent eos \'gyptii a se, et cessasset plaga ab eis, et iterum eos vellent capere, et ad suum servitium revocare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'fugientibus his, Deus cæli mare aperuit, ita ut hinc inde aquæ quasi murus solidarentur, et isti pede sicco fundum maris perambulando transirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'In quo loco dum innumerabilis exercitus \'gyptiorum eos persequeretur, ita aquis coopertus est, ut non remaneret vel unus, qui factum posteris nuntiaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Egressi vero mare Rubrum, deserta Sina montis occupaverunt, in quibus numquam homo habitare potuit, vel filius hominis requievit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Illic fontes amari obdulcati sunt eis ad bibendum, et per annos quadraginta annonam de cælo consecuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Ubicumque ingressi sunt sine arcu et sagitta, et absque scuto et gladio, Deus eorum pugnavit pro eis, et vicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Et non fuit qui insultaret populo isti, nisi quando recessit a cultu Domini Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Quotiescumque autem præter ipsum Deum suum, alterum coluerunt, dati sunt in prædam, et in gladium, et in opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Quotiescumque autem pœnituerunt se recessisse a cultura Dei sui, dedit eis Deus cæli virtutem resistendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Denique Chananæum regem, et Jebusæum, et Pherezæum, et Hethæum, et Hevæum, et Amorrhæum, et omnes potentes in Hesebon prostraverunt, et terras eorum et civitates eorum ipsi possederunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'et usque dum non peccarent in conspectu Dei sui, erant cum illis bona: Deus enim illorum odit iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Nam et ante hos annos cum recessissent a via quam dederat illis Deus ut ambularent in ea, exterminati sunt præliis a multis nationibus, et plurimi eorum captivi abducti sunt in terram non suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Nuper autem reversi ad Dominum Deum suum, ex dispersione qua dispersi fuerant, adunati sunt, et ascenderunt montana hæc omnia, et iterum possident Jerusalem, ubi sunt sancta eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Nunc ergo mi domine, perquire si est aliqua iniquitas eorum in conspectu Dei eorum: ascendamus ad illos, quoniam tradens tradet illos Deus eorum tibi, et subjugati erunt sub jugo potentiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Si vero non est offensio populi hujus coram Deo suo, non poterimus resistere illis, quoniam Deus eorum defendet illos: et erimus in opprobrium universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Et factum est, cum cessasset loqui Achior verba hæc, irati sunt omnes magnates Holofernis, et cogitabant interficere eum, dicentes ad alterutrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Quis est iste, qui filios Israël posse dicat resistere regi Nabuchodonosor et exercitibus ejus, homines inermes, et sine virtute, et sine peritia artis pugnæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 28, 'Ut ergo agnoscat Achior quoniam fallit nos, ascendamus in montana: et cum capti fuerint potentes eorum, tunc cum eisdem gladio transverberabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 29, 'ut sciat omnis gens quoniam Nabuchodonosor deus terræ est, et præter ipsum alius non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Factum est autem cum cessassent loqui, indignatus Holofernes vehementer, dixit ad Achior:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Quoniam prophetasti nobis, dicens quod gens Israël defendatur a Deo suo, ut ostendam tibi quoniam non est deus nisi Nabuchodonosor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'cum percusserimus eos omnes, sicut hominem unum, tunc et ipse cum illis Assyriorum gladio interibis, et omnis Israël tecum perditione disperiet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'et probabis quoniam Nabuchodonosor dominus sit universæ terræ: tuncque gladius militiæ meæ transiet per latera tua, et confixus cades inter vulneratos Israël, et non respirabis ultra, donec extermineris cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Porro autem si prophetiam tuam veram existimas, non concidat vultus tuus: et pallor qui faciem tuam obtinet abscedat a te, si verba mea hæc putas impleri non posse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Ut autem noveris quia simul cum illis hæc experieris, ecce ex hac hora illorum populo sociaberis, ut, dum dignas mei gladii pœnas exceperint, ipse simul ultioni subjaceas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Tunc Holofernes præcepit servis suis ut comprehenderent Achior, et perducerent eum in Bethuliam, et traderent eum in manus filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Et accipientes eum servi Holofernis, profecti sunt per campestria: sed cum appropinquassent ad montana, exierunt contra eos fundibularii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Illi autem divertentes a latere montis, ligaverunt Achior ad arborem manibus et pedibus, et sic vinctum restibus dimiserunt eum, et reversi sunt ad dominum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Porro filii Israël descendentes de Bethulia, venerunt ad eum: quem solventes, duxerunt ad Bethuliam, atque in medium populi illum statuentes, percunctati sunt quid rerum esset quod illum vinctum Assyrii reliquissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'In diebus illis erant illic principes Ozias filius Micha de tribu Simeon, et Charmi, qui et Gothoniel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'In medio itaque seniorum, et in conspectu omnium, Achior dixit omnia quæ locutus ipse fuerat ab Holoferne interrogatus: et qualiter populus Holofernis voluisset propter hoc verbum interficere eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'et quemadmodum ipse Holofernes iratus jusserit eum Israëlitis hac de causa tradi, ut dum vicerit filios Israël, tunc et ipsum Achior diversis jubeat interire suppliciis, propter hoc quod dixisset: Deus cæli defensor eorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Cumque Achior universa hæc exposuisset, omnis populus cecidit in faciem, adorantes Dominum, et communi lamentatione et fletu unanimes preces suas Domino effuderunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'dicentes: Domine Deus cæli et terræ, intuere superbiam eorum, et respice ad nostram humilitatem, et faciem sanctorum tuorum attende, et ostende quoniam non derelinquis præsumentes de te: et præsumentes de se, et de sua virtute gloriantes, humilias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Finito itaque fletu, et per totam diem oratione populorum completa, consolati sunt Achior,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'dicentes: Deus patrum nostrorum, cujus tu virtutem prædicasti, ipse tibi hanc dabit vicissitudinem, ut eorum magis tu interitum videas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Cum vero Dominus Deus noster dederit hanc libertatem servis suis, sit et tecum Deus in medio nostri: ut sicut placuerit tibi, ita cum tuis omnibus converseris nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Tunc Ozias, finito consilio, suscepit eum in domum suam, et fecit ei cœnam magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Et vocatis omnibus presbyteris, simul expleto jejunio refecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Postea vero convocatus est omnis populus, et per totam noctem intra ecclesiam oraverunt, petentes auxilium a Deo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Holofernes autem altera die præcepit exercitibus suis ut ascenderent contra Bethuliam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Erant autem pedites bellatorum centum viginti millia, et equites viginti duo millia, præter præparationes virorum illorum quos occupaverat captivitas, et abducti fuerant de provinciis et urbibus universæ juventutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Omnes paraverunt se pariter ad pugnam contra filios Israël, et venerunt per crepidinem montis usque ad apicem, qui respicit super Dothain, a loco qui dicitur Belma usque ad Chelmon, qui est contra Esdrelon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Filii autem Israël, ut viderunt multitudinem illorum, prostraverunt se super terram, mittentes cinerem super capita sua, unanimes orantes ut Deus Israël misericordiam suam ostenderet super populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Et assumentes arma sua bellica, sederunt per loca quæ ad angusti itineris tramitem dirigunt inter montosa, et erant custodientes ea tota die et nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Porro Holofernes, dum circuit per gyrum, reperit quod fons qui influebat, aquæductum illorum a parte australi extra civitatem dirigeret: et incidi præcepit aquæductum illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Erant tamen non longe a muris fontes, ex quibus furtim videbantur haurire aquam ad refocillandum potius quam ad potandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Sed filii Ammon et Moab accesserunt ad Holofernem, dicentes: Filii Israël non in lancea nec in sagitta confidunt, sed montes defendunt illos, et muniunt illos colles in præcipitio constituti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Ut ergo sine congressione pugnæ possis superare eos, pone custodes fontium, ut non hauriant aquam ex eis, et sine gladio interficies eos, vel certe fatigati tradent civitatem suam, quam putant in montibus positam superari non posse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Et placuerunt verba hæc coram Holoferne et coram satellitibus ejus, et constituit per gyrum centenarios per singulos fontes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Cumque ista custodia per dies viginti fuisset expleta, defecerunt cisternæ et collectiones aquarum omnibus habitantibus Bethuliam, ita ut non esset intra civitatem unde satiarentur vel una die, quoniam ad mensuram dabatur populis aqua quotidie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Tunc ad Oziam congregati omnes viri feminæque, juvenes et parvuli, omnes simul una voce');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'dixerunt: Judicet Deus inter nos et te, quoniam fecisti in nos mala, nolens loqui pacifice cum Assyriis, et propter hoc vendidit nos Deus in manibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Et ideo non est qui adjuvet, cum prosternamur ante oculos eorum in siti, et perditione magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Et nunc congregate universos qui in civitate sunt, ut sponte tradamus nos omnes populo Holofernis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Melius est enim ut captivi benedicamus Dominum viventes, quam moriamur, et simus opprobrium omni carni, cum viderimus uxores nostras et infantes nostros mori ante oculos nostros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Contestamur hodie cælum et terram, et Deum patrum nostrorum, qui ulciscitur nos secundum peccata nostra, ut jam tradatis civitatem in manu militiæ Holofernis, et sit finis noster brevis in ore gladii, qui longior efficitur in ariditate sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Et cum hæc dixissent, factus est fletus et ululatus magnus in ecclesia ab omnibus, et per multas horas una voce clamaverunt ad Deum, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Peccavimus cum patribus nostris: injuste egimus, iniquitatem fecimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Tu, quia pius es, miserere nostri, aut in tuo flagello vindica iniquitates nostras, et noli tradere confitentes te populo qui ignorat te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'ut non dicant inter gentes: Ubi est Deus eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 22, 'Et cum fatigati ex his clamoribus et his fletibus lassati siluissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 23, 'exsurgens Ozias infusus lacrimis, dixit: \'quo animo estote, fratres, et hos quinque dies expectemus a Domino misericordiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 24, 'Forsitan enim indignationem suam abscindet, et dabit gloriam nomini suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 25, 'Si autem transactis quinque diebus non venerit adjutorium, faciemus hæc verba quæ locuti estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Et factum est cum audisset hæc verba Judith vidua, quæ erat filia Merari filii Idox filii Joseph filii Oziæ filii Elai filii Jamnor filii Gedeon filii Raphaim filii Achitob filii Melchiæ filii Enan filii Nathaniæ filii Salathiel filii Simeon filii Ruben,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'et vir ejus fuit Manasses, qui mortuus est in diebus messis hordeaceæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'instabat enim super alligantes manipulos in campo, et venit æstus super caput ejus, et mortuus est in Bethulia civitate sua, et sepultus est illic cum patribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Erat autem Judith relicta ejus vidua jam annis tribus et mensibus sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Et in superioribus domus suæ fecit sibi secretum cubiculum, in quo cum puellis suis clausa morabatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'et habens super lumbos suos cilicium, jejunabat omnibus diebus vitæ suæ, præter sabbata et neomenias et festa domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Erat autem eleganti aspectu nimis, cui vir suus reliquerat divitias multas, et familiam copiosam, ac possessiones armentis boum, et gregibus ovium plenas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Et erat hæc in omnibus famosissima, quoniam timebat Dominum valde, nec erat qui loqueretur de illa verbum malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Hæc itaque cum audisset quoniam Ozias promisisset quod transacto quinto die traderet civitatem, misit ad presbyteros Chabri et Charmi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Et venerunt ad illam, et dixit illis: Quod est hoc verbum, in quo consensit Ozias, ut tradat civitatem Assyriis si intra quinque dies non venerit vobis adjutorium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'et qui estis vos, qui tentatis Dominum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'non est iste sermo qui misericordiam provocet, sed potius qui iram excitet, et furorem accendat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Posuistis vos tempus miserationis Domini, et in arbitrium vestrum, diem constituistis ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sed quia patiens Dominus est, in hoc ipso pœniteamus, et indulgentiam ejus fusis lacrimis postulemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'non enim quasi homo sic Deus comminabitur, neque sicut filius hominis ad iracundiam inflammabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Et ideo humiliemus illi animas nostras, et in spiritu constituti humiliato, servientes illi');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'dicamus flentes Domino, ut secundum voluntatem suam sic faciat nobiscum misericordiam suam: ut sicut conturbatum est cor nostrum in superbia eorum, ita etiam de nostra humilitate gloriemur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'quoniam non sumus secuti peccata patrum nostrorum, qui dereliquerunt Deum suum, et adoraverunt deos alienos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'pro quo scelere dati sunt in gladium, et in rapinam, et in confusionem inimicis suis: nos autem alterum deum nescimus præter ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Expectemus humiles consolationem ejus, et exquiret sanguinem nostrum de afflictionibus inimicorum nostrorum, et humiliabit omnes gentes, quæcumque insurgunt contra nos, et faciet illas sine honore Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Et nunc fratres, quoniam vos estis presbyteri in populo Dei, et ex vobis pendet anima illorum, ad eloquium vestrum corda eorum erigite, ut memores sint quia tentati sunt patres nostri, ut probarentur si vere colerent Deum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Memores esse debent quomodo pater noster Abraham tentatus est, et per multas tribulationes probatus, Dei amicus effectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 23, 'Sic Isaac, sic Jacob, sic Moyses, et omnes qui placuerunt Deo, per multas tribulationes transierunt fideles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 24, 'Illi autem qui tentationes non susceperunt cum timore Domini, et impatientiam suam et improperium murmurationis suæ contra Dominum protulerunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 25, 'exterminati sunt ab exterminatore, et a serpentibus perierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 26, 'Et nos ergo non ulciscamur nos pro his quæ patimur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 27, 'sed reputantes peccatis nostris hæc ipsa supplicia minora esse flagella Domini, quibus quasi servi corripimur ad emendationem, et non ad perditionem nostram evenisse credamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 28, 'Et dixerunt illi Ozias et presbyteri: Omnia quæ locuta es, vera sunt, et non est in sermonibus tuis ulla reprehensio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 29, 'Nunc ergo ora pro nobis, quoniam mulier sancta es, et timens Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 30, 'Et dixit illis Judith: Sicut quod potui loqui, Dei esse cognoscitis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 31, 'ita quod facere disposui, probate si ex Deo est, et orate ut firmum faciat Deus consilium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 32, 'Stabitis vos ad portam nocte ista, et ego exeam cum abra mea: et orate, ut sicut dixistis, in diebus quinque respiciat Dominus populum suum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 33, 'Vos autem nolo ut scrutemini actum meum, et usque dum renuntiem vobis, nihil aliud fiat, nisi oratio pro me ad Dominum Deum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 34, 'Et dixit ad eam Ozias princeps Juda: Vade in pace, et Dominus sit tecum in ultionem inimicorum nostrorum. Et revertentes abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Quibus ascendentibus, Judith ingressa est oratorium suum: et induens se cilicio, posuit cinerem super caput suum: et prosternens se Domino, clamabat ad Dominum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Domine Deus patris mei Simeon, qui dedisti illi gladium in defensionem alienigenarum, qui violatores extiterunt in coinquinatione sua, et denudaverunt femur virginis in confusionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'et dedisti mulieres illorum in prædam, et filias illorum in captivitatem: et omnem prædam in divisionem servis tuis, qui zelaverunt zelum tuum: subveni, quæso te, Domine Deus meus, mihi viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Tu enim fecisti priora, et illa post illa cogitasti: et hoc factum est quod ipse voluisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Omnes enim viæ tuæ paratæ sunt, et tua judicia in tua providentia posuisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Respice castra Assyriorum nunc, sicut tunc castra \'gyptiorum videre dignatus es, quando post servos tuos armati currebant, confidentes in quadrigis, et in equitatu suo, et in multitudine bellatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Sed aspexisti super castra eorum, et tenebræ fatigaverunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Tenuit pedes eorum abyssus, et aquæ operuerunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Sic fiant et isti, Domine, qui confidunt in multitudine sua, et in curribus suis, et in contis, et in scutis, et in sagittis suis, et in lanceis gloriantur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'et nesciunt quia tu ipse es Deus noster, qui conteris bella ab initio, et Dominus nomen est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Erige brachium tuum sicut ab initio, et allide virtutem illorum in virtute tua: cadat virtus eorum in iracundia tua, qui promittunt se violare sancta tua, et polluere tabernaculum nominis tui, et dejicere gladio suo cornu altaris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Fac, Domine, ut gladio proprio ejus superbia amputetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'capiatur laqueo oculorum suorum in me, et percuties eum ex labiis caritatis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Da mihi in animo constantiam ut contemnam illum, et virtutem, ut evertam illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Erit enim hoc memoriale nominis tui, cum manus feminæ dejecerit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Non enim in multitudine est virtus tua, Domine, neque in equorum viribus voluntas tua est, nec superbi ab initio placuerunt tibi: sed humilium et mansuetorum semper tibi placuit deprecatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Deus cælorum, creator aquarum, et Dominus totius creaturæ, exaudi me miseram deprecantem, et de tua misericordia præsumentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Memento, Domine, testamenti tui, et da verbum in ore meo, et in corde meo consilium corrobora, ut domus tua in sanctificatione tua permaneat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'et omnes gentes agnoscant quia tu es Deus, et non est alius præter te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Factum est autem, cum cessasset clamare ad Dominum, surrexit de loco in quo jacuerat prostrata ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Vocavitque abram suam, et descendens in domum suam, abstulit a se cilicium, et exuit se vestimentis viduitatis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'et lavit corpus suum, et unxit se myro optimo, et discriminavit crinem capitis sui, et imposuit mitram super caput suum, et induit se vestimentis jucunditatis suæ, induitque sandalia pedibus suis, assumpsitque dextraliola, et lilia, et inaures, et annulos, et omnibus ornamentis suis ornavit se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Cui etiam Dominus contulit splendorem: quoniam omnis ista compositio non ex libidine, sed ex virtute pendebat: et ideo Dominus hanc in illam pulchritudinem ampliavit, ut incomparabili decore omnium oculis appareret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Imposuit itaque abræ suæ ascoperam vini, et vas olei, et polentam, et palathas, et panes, et caseum, et profecta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Cumque venissent ad portam civitatis, invenerunt expectantem Oziam et presbyteros civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Qui cum vidissent eam, stupentes mirati sunt nimis pulchritudinem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Nihil tamen interrogantes eam, dimiserunt transire, dicentes: Deus patrum nostrorum det tibi gratiam, et omne consilium tui cordis sua virtute corroboret, ut glorietur super te Jerusalem, et sit nomen tuum in numero sanctorum et justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Et dixerunt hi qui illic erant omnes una voce: Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Judith vero orans Dominum, transivit per portas, ipsa et abra ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Factum est autem cum descenderet montem, circa ortum diei, occurrerunt ei exploratores Assyriorum, et tenuerunt eam, dicentes: Unde venis? aut quo vadis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Quæ respondit: Filia sum Hebræorum, ideo ego fugi a facie eorum, quoniam futurum agnovi quod dentur vobis in deprædationem, pro eo quod contemnentes vos, noluerunt ultro tradere seipsos ut invenirent misericordiam in conspectu vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Hac de causa cogitavi mecum, dicens: Vadam ad faciem principis Holofernis, ut indicem illi secreta illorum, et ostendam illi quo aditu possit obtinere eos, ita ut non cadat vir unus de exercitu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Et cum audissent viri illi verba ejus, considerabant faciem ejus, et erat in oculis eorum stupor, quoniam pulchritudinem ejus mirabantur nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Et dixerunt ad eam: Conservasti animam tuam, eo quod tale reperisti consilium, ut descenderes ad dominum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Hoc autem scias, quoniam cum steteris in conspectu ejus, bene tibi faciet, et eris gratissima in corde ejus. Duxeruntque illam ad tabernaculum Holofernis, annuntiantes eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Cumque intrasset ante faciem ejus, statim captus est in suis oculis Holofernes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Dixeruntque ad eum satellites ejus: Quis contemnat populum Hebræorum, qui tam decoras mulieres habent, ut non pro his merito pugnare contra eos debeamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Videns itaque Judith Holofernem sedentem in conopeo, quod erat ex purpura, et auro, et smaragdo, et lapidibus pretiosis intextum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'et cum in faciem ejus intendisset, adoravit eum, prosternens se super terram. Et elevaverunt eam servi Holofernis, jubente domino suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Tunc Holofernes dixit ei: \'quo animo esto, et noli pavere in corde tuo: quoniam ego numquam nocui viro qui voluit servire Nabuchodonosor regi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'populus autem tuus, si non contempsisset me, non levassem lanceam meam super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Nunc autem dic mihi, qua ex causa recessisti ab illis, et placuit tibi ut venires ad nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Et dixit illi Judith: Sume verba ancillæ tuæ, quoniam si secutus fueris verba ancillæ tuæ, perfectam rem faciet Dominus tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Vivit enim Nabuchodonosor rex terræ, et vivit virtus ejus, quæ est in te ad correptionem omnium animarum errantium: quoniam non solum homines serviunt illi per te, sed et bestiæ agri obtemperant illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Nuntiatur enim animi tui industria universis gentibus, et indicatum est omni sæculo quoniam tu solus bonus et potens es in omni regno ejus: et disciplina tua omnibus provinciis prædicatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Nec hoc latet, quod locutus est Achior, nec illud ignoratur, quod ei jusseris evenire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Constat enim Deum nostrum sic peccatis offensum, ut mandaverit per prophetas suos ad populum quod tradat eum pro peccatis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Et quoniam sciunt se offendisse Deum suum filii Israël, tremor tuus super ipsos est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Insuper etiam fames invasit eos, et ab ariditate aquæ jam inter mortuos computantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Denique hoc ordinant, ut interficient pecora sua, et bibant sanguinem eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'et sancta Domini Dei sui, quæ præcepit Deus non contingi, in frumento, vino, et oleo, hæc cogitaverunt impendere, et volunt consumere quæ nec manibus deberent contingere: ergo quoniam hæc faciunt, certum est quod in perditionem dabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Quod ego ancilla tua cognoscens, fugi ab illis, et misit me Dominus hæc ipsa nuntiare tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Ego enim ancilla tua Deum colo, etiam nunc apud te: et exiet ancilla tua, et orabo Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'et dicet mihi quando eis reddat peccatum suum, et veniens nuntiabo tibi, ita ut ego adducam te per mediam Jerusalem, et habebis omnem populum Israël, sicut oves quibus non est pastor, et non latrabit vel unus canis contra te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'quoniam hæc mihi dicta sunt per providentiam Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'et quoniam iratus est illis Deus, hæc ipsa missa sum nuntiare tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Placuerunt autem omnia verba hæc coram Holoferne, et coram pueris ejus, et mirabantur sapientiam ejus, et dicebant alter ad alterum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Non est talis mulier super terram in aspectu, in pulchritudine, et in sensu verborum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Et dixit ad illam Holofernes: Benefecit Deus, qui misit te ante populum, ut des illum tu in manibus nostris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 21, 'et quoniam bona est promissio tua, si fecerit mihi hoc Deus tuus, erit et Deus meus, et tu in domo Nabuchodonosor magna eris, et nomen tuum nominabitur in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Tunc jussit eam introire ubi repositi erant thesauri ejus, et jussit illic manere eam, et constituit quid daretur illi de convivio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Cui respondit Judith, et dixit: Nunc non potero manducare ex his quæ mihi præcipis tribui, ne veniat super me offensio: ex his autem quæ mihi detuli, manducabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Cui Holofernes ait: Si defecerint tibi ista, quæ tecum detulisti, quid faciemus tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Et dixit Judith: Vivit anima tua, domine meus, quoniam non expendet omnia hæc ancilla tua, donec faciat Deus in manu mea hæc quæ cogitavi. Et induxerunt illam servi ejus in tabernaculum quod præceperat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Et petiit dum introiret, ut daretur ei copia nocte et ante lucem egrediendi foras ad orationem, et deprecandi Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Et præcepit cubiculariis suis ut sicut placeret illi, exiret et introiret ad adorandum Deum suum per triduum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'et exibat noctibus in vallem Bethuliæ, et baptizabat se in fonte aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Et ut ascendebat, orabat Dominum Deum Israël ut dirigeret viam ejus ad liberationem populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Et introiens, munda manebat in tabernaculo usque dum acciperet escam suam in vespere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Et factum est, in quarto die Holofernes fecit cœnam servis suis, et dixit ad Vagao eunuchum suum: Vade, et suade Hebræam illam ut sponte consentiat habitare mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Fœdum est enim apud Assyrios, si femina irrideat virum agendo ut immunis ab eo transeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Tunc introivit Vagao ad Judith, et dixit: Non vereatur bona puella introire ad dominum meum, ut honorificetur ante faciem ejus, ut manducet cum eo, et bibat vinum in jucunditate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Cui Judith respondit: Quæ ego sum, ut contradicam domino meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'omne quod erit ante oculos ejus bonum et optimum, faciam. Quidquid autem illi placuerit, hoc mihi erit optimum omnibus diebus vitæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Et surrexit, et ornavit se vestimento suo, et ingressa stetit ante faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Cor autem Holofernes concussum est: erat enim ardens in concupiscentia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Et dixit ad eam Holofernes: Bibe nunc, et accumbe in jucunditate, quoniam invenisti gratiam coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Et dixit Judith: Bibam, domine, quoniam magnificata est anima mea hodie præ omnibus diebus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Et accepit, et manducavit et bibit coram ipso ea quæ paraverat illi ancilla ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Et jucundus factus est Holofernes ad eam, bibitque vinum multum nimis, quantum numquam biberat in vita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Ut autem sero factum est, festinaverunt servi illius ad hospitia sua, et conclusit Vagao ostia cubiculi, et abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Erant autem omnes fatigati a vino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'eratque Judith sola in cubiculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Porro Holofernes jacebat in lecto, nimia ebrietate sopitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Dixitque Judith puellæ suæ ut staret foris ante cubiculum, et observaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Stetitque Judith ante lectum, orans cum lacrimis, et labiorum motu in silentio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'dicens: Confirma me, Domine Deus Israël, et respice in hac hora ad opera manuum mearum, ut, sicut promisisti, Jerusalem civitatem tuam erigas: et hoc quod credens per te posse fieri cogitavi, perficiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Et cum hæc dixisset, accessit ad columnam quæ erat ad caput lectuli ejus, et pugionem ejus, qui in ea ligatus pendebat, exsolvit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Cumque evaginasset illum, apprehendit comam capitis ejus, et ait: Confirma me, Domine Deus, in hac hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Et percussit bis in cervicem ejus, et abscidit caput ejus, et abstulit conopeum ejus a columnis, et evolvit corpus ejus truncum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Et post pusillum exivit, et tradidit caput Holofernis ancillæ suæ, et jussit ut mitteret illud in peram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Et exierunt duæ, secundum consuetudinem suam, quasi ad orationem, et transierunt castra, et gyrantes vallem, venerunt ad portam civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Et dixit Judith a longe custodibus murorum: Aperite portas, quoniam nobiscum est Deus, qui fecit virtutem in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Et factum est cum audissent viri vocem ejus, vocaverunt presbyteros civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Et concurrerunt ad eam omnes, a minimo usque ad maximum: quoniam sperabant eam jam non esse venturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Et accendentes luminaria, congyraverunt circa eam universi: illa autem ascendens in eminentiorem locum, jussit fieri silentium. Cumque omnes tacuissent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'dixit Judith: Laudate Dominum Deum nostrum, qui non deseruit sperantes in se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'et in me ancilla sua adimplevit misericordiam suam, quam promisit domui Israël: et interfecit in manu mea hostem populi sui hac nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Et proferens de pera caput Holofernis, ostendit illis, dicens: Ecce caput Holofernis principis militiæ Assyriorum, et ecce conopeum illius, in quo recumbebat in ebrietate sua, ubi per manum feminæ percussit illum Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Vivit autem ipse Dominus, quoniam custodivit me angelus ejus et hinc euntem, et ibi commorantem, et inde huc revertentem, et non permisit me Dominus ancillam suam coinquinari, sed sine pollutione peccati revocavit me vobis gaudentem in victoria sua, in evasione mea, et in liberatione vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Confitemini illi omnes, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Universi autem adorantes Dominum, dixerunt ad eam: Benedixit te Dominus in virtute sua, quia per te ad nihilum redegit inimicos nostros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Porro Ozias princeps populi Israël dixit ad eam: Benedicta es tu, filia, a Domino Deo excelso præ omnibus mulieribus super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Benedictus Dominus, qui creavit cælum et terram, qui te direxit in vulnera capitis principis inimicorum nostrorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'quia hodie nomen tuum ita magnificavit, ut non recedat laus tua de ore hominum qui memores fuerint virtutis Domini in æternum, pro quibus non pepercisti animæ tuæ propter angustias et tribulationem generis tui, sed subvenisti ruinæ ante conspectum Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Et dixit omnis populus: Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Porro Achior vocatus venit, et dixit ei Judith: Deus Israël, cui tu testimonium dedisti quod ulciscatur se de inimicis suis, ipse caput omnium incredulorum incidit hac nocte in manu mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Et ut probes quia ita est, ecce caput Holofernis, qui in contemptu superbiæ suæ Deum Israël contempsit, et tibi interitum minabatur, dicens: Cum captus fuerit populus Israël, gladio perforari præcipiam latera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 29, 'Videns autem Achior caput Holofernis, angustiatus præ pavore cecidit in faciem suam super terram, et æstuavit anima ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 30, 'Postea vero quam resumpto spiritu recreatus est, procidit ad pedes ejus, et adoravit eam, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 31, 'Benedicta tu a Deo tuo in omni tabernaculo Jacob, quoniam in omni gente quæ audierit nomen tuum, magnificabitur super te Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Dixit autem Judith ad omnem populum: Audite me, fratres: suspendite caput hoc super muros nostros:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'et erit, cum exierit sol, accipiat unusquisque arma sua, et exite cum impetu, non ut descendatis deorsum, sed quasi impetum facientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Tunc exploratores necesse erit ut fugiant ad principem suum excitandum ad pugnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Cumque duces eorum cucurrerint ad tabernaculum Holofernis, et invenerint eum truncum in suo sanguine volutatum, decidet super eos timor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Cumque cognoveritis fugere eos, ite post illos securi, quoniam Dominus conteret eos sub pedibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Tunc Achior, videns virtutem quam fecit Deus Israël, relicto gentilitatis ritu, credidit Deo, et circumcidit carnem præputii sui, et appositus est ad populum Israël, et omnis successio generis ejus usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Mox autem ut ortus est dies, suspenderunt super muros caput Holofernis, accepitque unusquisque vir arma sua, et egressi sunt cum grandi strepitu et ululatu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Quod videntes exploratores, ad tabernaculum Holofernis cucurrerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Porro hi qui in tabernaculo erant, venientes, et ante ingressum cubiculi perstrepentes, excitandi gratia, inquietudinem arte moliebantur, ut non ab excitantibus, sed a sonantibus Holofernes evigilaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Nullus enim audebat cubiculum virtutis Assyriorum pulsando aut intrando aperire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Sed cum venissent ejus duces ac tribuni, et universi majores exercitus regis Assyriorum, dixerunt cubiculariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Intrate, et excitate illum, quoniam egressi mures de cavernis suis, ausi sunt provocare nos ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Tunc ingressus Vagao cubiculum ejus, stetit ante cortinam, et plausum fecit manibus suis: suspicabatur enim illum cum Judith dormire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Sed cum nullum motum jacentis sensu aurium caperet, accessit proximans ad cortinam, et elevans eam, vidensque cadaver absque capite Holofernis in suo sanguine tabefactum jacere super terram, exclamavit voce magna cum fletu, et scidit vestimenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Et ingressus tabernaculum Judith, non invenit eam, et exiliit foras ad populum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'et dixit: Una mulier hebræa fecit confusionem in domo regis Nabuchodonosor: ecce enim Holofernes jacet in terra, et caput ejus non est in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Quod cum audissent principes virtutis Assyriorum, sciderunt omnes vestimenta sua, et intolerabilis timor et tremor cecidit super eos, et turbati sunt animi eorum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Et factus est clamor incomparabilis in medio castrorum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Cumque omnis exercitus decollatum Holofernem audisset, fugit mens et consilium ab eis, et solo tremore et metu agitati, fugæ præsidium sumunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'ita ut nullus loqueretur cum proximo suo, sed inclinato capite, relictis omnibus, evadere festinabant Hebræos, quos armatos super se venire audiebant, fugientes per vias camporum et semitas collium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Videntes itaque filii Israël fugientes, secuti sunt illos. Descenderuntque clangentes tubis, et ululantes post ipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Et quoniam Assyrii non adunati, in fugam ibant præcipites: filii autem Israël uno agmine persequentes debilitabant omnes quos invenire potuissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Misit itaque Ozias nuntios per omnes civitates et regiones Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Omnis itaque regio, omnisque urbs electam juventutem armatam misit post eos, et persecuti sunt eos in ore gladii, quousque pervenirent ad extremitatem finium suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Reliqui autem qui erant in Bethulia, ingressi sunt castra Assyriorum, et prædam quam fugientes Assyrii reliquerant, abstulerunt, et onustati sunt valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hi vero qui victores reversi sunt ad Bethuliam, omnia quæ erant illorum attulerunt secum, ita ut non esset numerus in pecoribus et jumentis et universis mobilibus eorum, ut a minimo usque ad maximum omnes divites fierent de prædationibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Joacim autem summus pontifex de Jerusalem venit in Bethuliam cum universis presbyteris suis ut videret Judith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Quæ cum exisset ad illum, benedixerunt eam omnes una voce, dicentes: Tu gloria Jerusalem; tu lætitia Israël; tu honorificentia populi nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'quia fecisti viriliter, et confortatum est cor tuum, eo quod castitatem amaveris, et post virum tuum, alterum nescieris: ideo et manus Domini confortavit te, et ideo eris benedicta in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Et dixit omnis populus: Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Per dies autem triginta, vix collecta sunt spolia Assyriorum a populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Porro autem universa quæ Holofernis peculiaria fuisse probata sunt, dederunt Judith in auro, et argento, et vestibus, et gemmis, et omni supellectili: et tradita sunt omnia illi a populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Et omnes populi gaudebant cum mulieribus, et virginibus, et juvenibus, in organis et citharis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Tunc cantavit canticum hoc Domino Judith, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Incipite Domino in tympanis; cantate Domino in cymbalis; modulamini illi psalmum novum: exaltate, et invocate nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Dominus conterens bella, Dominus nomen est illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Qui posuit castra sua in medio populi sui, ut eriperet nos de manu omnium inimicorum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Venit Assur ex montibus ab aquilone in multitudine fortitudinis suæ: cujus multitudo obturavit torrentes, et equi eorum cooperuerunt valles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Dixit se incensurum fines meos, et juvenes meos occisurum gladio; infantes meos dare in prædam, et virgines in captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Dominus autem omnipotens nocuit eum, et tradidit eum in manus feminæ, et confodit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Non enim cecidit potens eorum a juvenibus, nec filii Titan percusserunt eum, nec excelsi gigantes opposuerunt se illi: sed Judith filia Merari in specie faciei suæ dissolvit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Exuit enim se vestimento viduitatis, et induit se vestimento lætitiæ in exultatione filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Unxit faciem suam unguento, et colligavit cincinnos suos mitra; accepit stolam novam ad decipiendum illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Sandalia ejus rapuerunt oculos ejus; pulchritudo ejus captivam fecit animam ejus: amputavit pugione cervicem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Horruerunt Persæ constantiam ejus, et Medi audaciam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Tunc ululaverunt castra Assyriorum, quando apparuerunt humiles mei, arescentes in siti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Filii puellarum compunxerunt eos, et sicut pueros fugientes occiderunt eos: perierunt in prælio a facie Domini Dei mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Hymnum cantemus Domino; hymnum novum cantemus Deo nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Adonai Domine, magnus es tu, et præclarus in virtute tua: et quem superare nemo potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Tibi serviat omnis creatura tua, quia dixisti, et facta sunt; misisti spiritum tuum, et creata sunt: et non est qui resistat voci tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Montes a fundamentis movebuntur cum aquis; petræ, sicut cera, liquescent ante faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Qui autem timent te, magni erunt apud te per omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Væ genti insurgenti super genus meum: Dominus enim omnipotens vindicabit in eis; in die judicii visitabit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Dabit enim ignem et vermes in carnes eorum, ut urantur et sentiant usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Et factum est post hæc, omnis populus post victoriam venit in Jerusalem adorare Dominum: et mox ut purificati sunt, obtulerunt omnes holocausta, et vota, et repromissiones suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 23, 'Porro Judith universa vasa bellica Holofernis, quæ dedit illi populus, et conopeum quod ipsa sustulerat de cubili ipsius, obtulit in anathema oblivionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 24, 'Erat autem populus jucundus secundum faciem sanctorum: et per tres menses gaudium hujus victoriæ celebratum est cum Judith.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 25, 'Post dies autem illos, unusquisque rediit in domum suam: et Judith magna facta est in Bethulia, et præclarior erat universæ terræ Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 26, 'Erat enim virtuti castitas adjuncta, ita ut non cognosceret virum omnibus diebus vitæ suæ, ex quo defunctus est Manasses vir ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 27, 'Erat autem, diebus festis, procedens cum magna gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 28, 'Mansit autem in domo viri sui annos centum quinque, et dimisit abram suam liberam: et defuncta est ac sepulta cum viro suo in Bethulia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 29, 'Luxitque illam omnis populus diebus septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 30, 'In omni autem spatio vitæ ejus non fuit qui perturbaret Israël, et post mortem ejus annis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 31, 'Dies autem victoriæ hujus festivitatis ab Hebræis in numero sanctorum dierum accipitur, et colitur a Judæis ex illo tempore usque in præsentem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'In diebus Assueri, qui regnavit ab India usque \'thiopiam super centum viginti septem provincias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'quando sedit in solio regni sui, Susan civitas regni ejus exordium fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Tertio igitur anno imperii sui fecit grande convivium cunctis principibus et pueris suis, fortissimis Persarum, et Medorum inclytis, et præfectis provinciarum coram se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'ut ostenderet divitias gloriæ regni sui, ac magnitudinem atque jactantiam potentiæ suæ, multo tempore, centum videlicet et octoginta diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Cumque implerentur dies convivii, invitavit omnem populum, qui inventus est in Susan, a maximo usque ad minimum: et jussit septem diebus convivium præparari in vestibulo horti, et nemoris quod regio cultu et manu consitum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Et pendebant ex omni parte tentoria ærii coloris et carbasini ac hyacinthini, sustentata funibus byssinis atque purpureis, qui eburneis circulis inserti erant, et columnis marmoreis fulciebantur. Lectuli quoque aurei et argentei, super pavimentum smaragdino et pario stratum lapide, dispositi erant: quod mira varietate pictura decorabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 7, 'Bibebant autem qui invitati erant aureis poculis, et aliis atque aliis vasis cibi inferebantur. Vinum quoque, ut magnificentia regia dignum erat, abundans, et præcipuum ponebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 8, 'Nec erat qui nolentes cogeret ad bibendum, sed sicut rex statuerat, præponens mensis singulos de principibus suis ut sumeret unusquisque quod vellet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 9, 'Vasthi quoque regina fecit convivium feminarum in palatio, ubi rex Assuerus manere consueverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 10, 'Itaque die septimo, cum rex esset hilarior, et post nimiam potationem incaluisset mero, præcepit Maumam, et Bazatha, et Harbona, et Bagatha, et Abgatha, et Zethar, et Charchas, septem eunuchis qui in conspectu ejus ministrabant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 11, 'ut introducerent reginam Vasthi coram rege, posito super caput ejus diademate, ut ostenderet cunctis populis et principibus pulchritudinem illius: erat enim pulchra valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 12, 'Quæ renuit, et ad regis imperium quod per eunuchos mandaverat, venire contempsit. Unde iratus rex, et nimio furore succensus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 13, 'interrogavit sapientes, qui ex more regio semper ei aderant, et illorum faciebat cuncta consilio, scientium leges, ac jura majorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 14, '(erant autem primi et proximi, Charsena, et Sethar, et Admatha, et Tharsis, et Mares, et Marsana, et Mamuchan, septem duces Persarum, atque Medorum, qui videbant faciem regis, et primi post eum residere soliti erant):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 15, 'cui sententiæ Vasthi regina subjaceret, quæ Assueri regis imperium, quod per eunuchos mandaverat, facere noluisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 16, 'Responditque Mamuchan, audiente rege atque principibus: Non solum regem læsit regina Vasthi, sed et omnes populos et principes qui sunt in cunctis provinciis regis Assueri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 17, 'Egredietur enim sermo reginæ ad omnes mulieres, ut contemnant viros suos, et dicant: Rex Assuerus jussit ut regina Vasthi intraret ad eum, et illa noluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 18, 'Atque hoc exemplo omnes principum conjuges Persarum atque Medorum parvipendent imperia maritorum: unde regis justa est indignatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 19, 'Si tibi placet, egrediatur edictum a facie tua, et scribatur juxta legem Persarum atque Medorum, quam præteriri illicitum est, ut nequaquam ultra Vasthi ingrediatur ad regem, sed regnum illius altera, quæ melior est illa, accipiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 20, 'Et hoc in omne (quod latissimum est) provinciarum tuarum divulgetur imperium, et cunctæ uxores, tam majorum quam minorum, deferant maritis suis honorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 21, 'Placuit consilium ejus regi et principibus: fecitque rex juxta consilium Mamuchan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 22, 'et misit epistolas ad universas provincias regni sui, ut quæque gens audire et legere poterat, diversis linguis et litteris, esse viros principes ac majores in domibus suis: et hoc per cunctos populos divulgari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'His ita gestis, postquam regis Assueri indignatio deferbuerat, recordatus est Vasthi, et quæ fecisset, vel quæ passa esset:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'dixeruntque pueri regis ac ministri ejus: Quærantur regi puellæ virgines ac speciosæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'et mittantur qui considerent per universas provincias puellas speciosas et virgines: et adducant eas ad civitatem Susan, et tradant eas in domum feminarum sub manu Egei eunuchi, qui est præpositus et custos mulierum regiarum: et accipiant mundum muliebrem, et cetera ad usus necessaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Et quæcumque inter omnes oculis regis placuerit, ipsa regnet pro Vasthi. Placuit sermo regi: et ita, ut suggesserant, jussit fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Erat vir Judæus in Susan civitate, vocabulo Mardochæus filius Jair, filii Semei, filii Cis, de stirpe Jemini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'qui translatus fuerat de Jerusalem eo tempore quo Jechoniam regem Juda Nabuchodonosor rex Babylonis transtulerat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'qui fuit nutritius filiæ fratris sui Edissæ, quæ altero nomine vocabatur Esther, et utrumque parentem amiserat: pulchra nimis, et decora facie. Mortuisque patre ejus ac matre, Mardochæus sibi eam adoptavit in filiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Cumque percrebruisset regis imperium, et juxta mandatum illius multæ pulchræ virgines adducerentur Susan, et Egeo traderentur eunucho, Esther quoque inter ceteras puellas ei tradita est, ut servaretur in numero feminarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Quæ placuit ei, et invenit gratiam in conspectu illius. Et præcepit eunucho, ut acceleraret mundum muliebrem, et traderet ei partes suas, et septem puellas speciosissimas de domo regis, et tam ipsam quam pedissequas ejus ornaret atque excoleret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Quæ noluit indicare ei populum et patriam suam: Mardochæus enim præceperat ei, ut de hac re omnino reticeret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'qui deambulabat quotidie ante vestibulum domus, in qua electæ virgines servabantur, curam agens salutis Esther, et scire volens quid ei accideret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Cum autem venisset tempus singularum per ordinem puellarum ut intrarent ad regem, expletis omnibus quæ ad cultum muliebrem pertinebant, mensis duodecimus vertebatur: ita dumtaxat, ut sex mensibus oleo ungerentur myrrhino, et aliis sex quibusdam pigmentis et aromatibus uterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 13, 'Ingredientesque ad regem, quidquid postulassent ad ornatum pertinens, accipiebant: et ut eis placuerat, compositæ de triclinio feminarum ad regis cubiculum transibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 14, 'Et quæ intraverat vespere, egrediebatur mane, atque inde in secundas ædes deducebatur, quæ sub manu Susagazi eunuchi erant, qui concubinis regis præsidebat: nec habebat potestatem ad regem ultra redeundi, nisi voluisset rex, et eam venire jussisset ex nomine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 15, 'Evoluto autem tempore per ordinem, instabat dies quo Esther filia Abihail fratris Mardochæi, quam sibi adoptaverat in filiam, deberet intrare ad regem. Quæ non quæsivit muliebrem cultum, sed quæcumque voluit Egeus eunuchus custos virginum, hæc ei ad ornatum dedit. Erat enim formosa valde, et incredibili pulchritudine: omnium oculis gratiosa et amabilis videbatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 16, 'Ducta est itaque ad cubiculum regis Assueri mense decimo, qui vocatur Tebeth, septimo anno regni ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 17, 'Et adamavit eam rex plus quam omnes mulieres, habuitque gratiam et misericordiam coram eo super omnes mulieres: et posuit diadema regni in capite ejus, fecitque eam regnare in loco Vasthi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 18, 'Et jussit convivium præparari permagnificum cunctis principibus et servis suis pro conjunctione et nuptiis Esther. Et dedit requiem universis provinciis, ac dona largitus est juxta magnificentiam principalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 19, 'Cumque secundo quærerentur virgines et congregarentur, Mardochæus manebat ad januam regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 20, 'necdum prodiderat Esther patriam et populum suum, juxta mandatum ejus. Quidquid enim ille præcipiebat, observabat Esther: et ita cuncta faciebat ut eo tempore solita erat, quo eam parvulam nutriebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 21, 'Eo igitur tempore, quo Mardochæus ad regis januam morabatur, irati sunt Bagathan et Thares duo eunuchi regis, qui janitores erant, et in primo palatii limine præsidebant: volueruntque insurgere in regem, et occidere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 22, 'Quod Mardochæum non latuit, statimque nuntiavit reginæ Esther: et illa regi ex nomine Mardochæi, qui ad se rem detulerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 23, 'Quæsitum est, et inventum: et appensus est uterque eorum in patibulo. Mandatumque est historiis, et annalibus traditum coram rege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Post hæc rex Assuerus exaltavit Aman filium Amadathi, qui erat de stirpe Agag: et posuit solium ejus super omnes principes quos habebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Cunctique servi regis, qui in foribus palatii versabantur, flectebant genua, et adorabant Aman: sic enim præceperat eis imperator: solus Mardochæus non flectebat genu, neque adorabat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Cui dixerunt pueri regis, qui ad fores palatii præsidebant: Cur præter ceteros non observas mandatum regis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Cumque hoc crebrius dicerent, et ille nollet audire, nuntiaverunt Aman, scire cupientes utrum perseveraret in sententia: dixerat enim eis se esse Judæum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Quod cum audisset Aman, et experimento probasset quod Mardochæus non flecteret sibi genu, nec se adoraret, iratus est valde,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'et pro nihilo duxit in unum Mardochæum mittere manus suas: audierat enim quod esset gentis Judææ; magisque voluit omnem Judæorum, qui erant in regno Assueri, perdere nationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Mense primo (cujus vocabulum est Nisan), anno duodecimo regni Assueri, missa est sors in urnam, quæ hebraice dicitur phur, coram Aman, quo die et quo mense gens Judæorum deberet interfici: et exivit mensis duodecimus, qui vocatur Adar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Dixitque Aman regi Assuero: Est populus per omnes provincias regni tui dispersus, et a se mutuo separatus, novis utens legibus et cæremoniis, insuper et regis scita contemnens: et optime nosti quod non expediat regno tuo ut insolescat per licentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Si tibi placet, decerne, ut pereat, et decem millia talentorum appendam arcariis gazæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 10, 'Tulit ergo rex annulum, quo utebatur, de manu sua, et dedit eum Aman filio Amadathi de progenie Agag, hosti Judæorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 11, 'dixitque ad eum: Argentum, quod tu polliceris, tuum sit; de populo age quod tibi placet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 12, 'Vocatique sunt scribæ regis mense primo Nisan, tertiadecima die ejusdem mensis: et scriptum est, ut jusserat Aman, ad omnes satrapas regis, et judices provinciarum, diversarumque gentium, ut quæque gens legere poterat et audire pro varietate linguarum ex nomine regis Assueri: et litteræ signatæ ipsius annulo');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 13, 'missæ sunt per cursores regis ad universas provincias, ut occiderent atque delerent omnes Judæos, a puero usque ad senem, parvulos et mulieres, uno die, hoc est tertiodecimo mensis duodecimi, qui vocatur Adar; et bona eorum diriperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 14, 'Summa autem epistolarum hæc fuit, ut omnes provinciæ scirent, et pararent se ad prædictam diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 15, 'Festinabant cursores, qui missi erant, regis imperium explere. Statimque in Susan pependit edictum, rege et Aman celebrante convivium, et cunctis Judæis, qui in urbe erant, flentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Quæ cum audisset Mardochæus, scidit vestimenta sua, et indutus est sacco, spargens cinerem capiti: et in platea mediæ civitatis voce magna clamabat, ostendens amaritudinem animi sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'et hoc ejulatu usque ad fores palatii gradiens. Non enim erat licitum indutum sacco aulam regis intrare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'In omnibus quoque provinciis, oppidis, ac locis, ad quæ crudele regis dogma pervenerat, planctus ingens erat apud Judæos, jejunium, ululatus, et fletus, sacco et cinere multis pro strato utentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Ingressæ autem sunt puellæ Esther et eunuchi, nuntiaveruntque ei. Quod audiens consternata est, et vestem misit, ut ablato sacco induerent eum: quam accipere noluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Accitoque Athach eunucho, quem rex ministrum ei dederat, præcepit ei ut iret ad Mardochæum, et disceret ab eo cur hoc faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Egressusque Athach, ivit ad Mardochæum stantem in platea civitatis, ante ostium palatii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'qui indicavit ei omnia quæ acciderant: quomodo Aman promisisset ut in thesauros regis pro Judæorum nece inferret argentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Exemplar quoque edicti, quod pendebat in Susan, dedit ei, ut reginæ ostenderet, et moneret eam ut intraret ad regem et deprecaretur eum pro populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Regressus Athach, nuntiavit Esther omnia quæ Mardochæus dixerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 10, 'Quæ respondit ei, et jussit ut diceret Mardochæo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 11, 'Omnes servi regis, et cunctæ, quæ sub ditione ejus sunt, norunt provinciæ, quod sive vir, sive mulier non vocatus, interius atrium regis intraverit, absque ulla cunctatione statim interficiatur: nisi forte rex auream virgam ad eum tetenderit pro signo clementiæ, atque ita possit vivere. Ego igitur quomodo ad regem intrare potero, quæ triginta jam diebus non sum vocata ad eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 12, 'Quod cum audisset Mardochæus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 13, 'rursum mandavit Esther, dicens: Ne putes quod animam tuam tantum liberes, quia in domo regis es præ cunctis Judæis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 14, 'si enim nunc silueris, per aliam occasionem liberabuntur Judæi: et tu, et domus patris tui, peribitis. Et quis novit utrum idcirco ad regnum veneris, ut in tali tempore parareris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 15, 'Rursumque Esther hæc Mardochæo verba mandavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 16, 'Vade, et congrega omnes Judæos quos in Susan repereris, et orate pro me. Non comedatis et non bibatis tribus diebus et tribus noctibus: et ego cum ancillis meis similiter jejunabo, et tunc ingrediar ad regem contra legem faciens, non vocata, tradensque me morti et periculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 17, 'Ivit itaque Mardochæus, et fecit omnia quæ ei Esther præceperat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Die autem tertio induta est Esther regalibus vestimentis, et stetit in atrio domus regiæ, quod erat interius, contra basilicam regis: at ille sedebat super solium suum in consistorio palatii contra ostium domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Cumque vidisset Esther reginam stantem, placuit oculis ejus, et extendit contra eam virgam auream, quam tenebat manu: quæ accedens, osculata est summitatem virgæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Dixitque ad eam rex: Quid vis, Esther regina? quæ est petitio tua? etiam si dimidiam partem regni petieris, dabitur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'At illa respondit: Si regi placet, obsecro ut venias ad me hodie, et Aman tecum, ad convivium quod paravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Statimque rex: Vocate, inquit, cito Aman ut Esther obediat voluntati. Venerunt itaque rex et Aman ad convivium, quod eis regina paraverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Dixitque ei rex, postquam vinum biberat abundanter: Quid petis ut detur tibi? et pro qua re postulas? etiam si dimidiam partem regni mei petieris, impetrabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Cui respondit Esther: Petitio mea, et preces sunt istæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'si inveni in conspectu regis gratiam, et si regi placet ut det mihi quod postulo, et meam impleat petitionem: veniat rex et Aman ad convivium quod paravi eis, et cras aperiam regi voluntatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Egressus est itaque illo die Aman lætus et alacer. Cumque vidisset Mardochæum sedentem ante fores palatii, et non solum non assurrexisse sibi, sed nec motum quidem de loco sessionis suæ, indignatus est valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'et dissimulata ira reversus in domum suam, convocavit ad se amicos suos, et Zares uxorem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'et exposuit illis magnitudinem divitiarum suarum, filiorumque turbam, et quanta eum gloria super omnes principes et servos suos rex elevasset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Et post hæc ait: Regina quoque Esther nullum alium vocavit ad convivium cum rege præter me: apud quam etiam cras cum rege pransurus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Et cum hæc omnia habeam, nihil me habere puto, quamdiu videro Mardochæum Judæum sedentem ante fores regias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 14, 'Responderuntque ei Zares uxor ejus, et ceteri amici: Jube parari excelsam trabem, habentem altitudinis quinquaginta cubitos, et dic mane regi ut appendatur super eam Mardochæus, et sic ibis cum rege lætus ad convivium. Placuit ei consilium, et jussit excelsam parari crucem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Noctem illam duxit rex insomnem, jussitque sibi afferri historias et annales priorum temporum. Quæ cum illo præsente legerentur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'ventum est ad illum locum ubi scriptum erat quomodo nuntiasset Mardochæus insidias Bagathan et Thares eunuchorum, regem Assuerum jugulare cupientium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Quod cum audisset rex, ait: Quid pro hac fide honoris ac præmii Mardochæus consecutus est? Dixerunt ei servi illius ac ministri: Nihil omnino mercedis accepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Statimque rex: Quis est, inquit, in atrio? Aman quippe interius atrium domus regiæ intraverat, ut suggereret regi, et juberet Mardochæum affigi patibulo, quod ei fuerat præparatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Responderunt pueri: Aman stat in atrio. Dixitque rex: Ingrediatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Cumque esset ingressus, ait illi: Quid debet fieri viro, quem rex honorare desiderat? Cogitans autem in corde suo Aman, et reputans quod nullum alium rex, nisi se, vellet honorare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'respondit: Homo, quem rex honorare cupit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'debet indui vestibus regiis, et imponi super equum, qui de sella regis est, et accipere regium diadema super caput suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'et primus de regiis principibus ac tyrannis teneat equum ejus, et per plateam civitatis incedens clamet, et dicat: Sic honorabitur, quemcumque voluerit rex honorare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Dixitque ei rex: Festina, et sumpta stola et equo, fac, ut locutus es, Mardochæo Judæo, qui sedet ante fores palatii. Cave ne quidquam de his, quæ locutus es, prætermittas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Tulit itaque Aman stolam et equum, indutumque Mardochæum in platea civitatis, et impositum equo præcedebat, atque clamabat: Hoc honore condignus est, quemcumque rex voluerit honorare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 12, 'Reversusque est Mardochæus ad januam palatii: et Aman festinavit ire in domum suam, lugens et operto capite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 13, 'narravitque Zares uxori suæ, et amicis, omnia quæ evenissent sibi. Cui responderunt sapientes quos habebat in consilio, et uxor ejus: Si de semine Judæorum est Mardochæus, ante quem cadere cœpisti, non poteris ei resistere, sed cades in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 14, 'Adhuc illis loquentibus, venerunt eunuchi regis, et cito eum ad convivium, quod regina paraverat, pergere compulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Intravit itaque rex et Aman, ut biberent cum regina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Dixitque ei rex etiam secunda die, postquam vino incaluerat: Quæ est petitio tua, Esther, ut detur tibi? et quid vis fieri? etiam si dimidiam partem regni mei petieris, impetrabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Ad quem illa respondit: Si inveni gratiam in oculis tuis o rex, et si tibi placet, dona mihi animam meam pro qua rogo, et populum meum pro quo obsecro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Traditi enim sumus ego et populus meus, ut conteramur, jugulemur, et pereamus. Atque utinam in servos et famulas venderemur: esset tolerabile malum, et gemens tacerem: nunc autem hostis noster est, cujus crudelitas redundat in regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Respondensque rex Assuerus, ait: Quis est iste, et cujus potentiæ, ut hæc audeat facere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Dixitque Esther: Hostis et inimicus noster pessimus iste est Aman. Quod ille audiens, illico obstupuit, vultum regis ac reginæ ferre non sustinens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Rex autem iratus surrexit, et de loco convivii intravit in hortum arboribus consitum. Aman quoque surrexit ut rogaret Esther reginam pro anima sua: intellexit enim a rege sibi paratum malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Qui cum reversus esset de horto nemoribus consito, et intrasset convivii locum, reperit Aman super lectulum corruisse in quo jacebat Esther, et ait: Etiam reginam vult opprimere, me præsente, in domo mea. Necdum verbum de ore regis exierat, et statim operuerunt faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Dixitque Harbona, unus de eunuchis, qui stabant in ministerio regis: En lignum quod paraverat Mardochæo, qui locutus est pro rege, stat in domo Aman, habens altitudinis quinquaginta cubitos. Cui dixit rex: Appendite eum in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Suspensus est itaque Aman in patibulo quod paraverat Mardochæo: et regis ira quievit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Die illo dedit rex Assuerus Esther reginæ domum Aman adversarii Judæorum, et Mardochæus ingressus est ante faciem regis. Confessa est enim ei Esther quod esset patruus suus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Tulitque rex annulum, quem ab Aman recipi jusserat, et tradidit Mardochæo. Esther autem constituit Mardochæum super domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Nec his contenta, procidit ad pedes regis, flevitque, et locuta ad eum oravit ut malitiam Aman Agagitæ, et machinationes ejus pessimas quas excogitaverat contra Judæos, juberet irritas fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'At ille ex more sceptrum aureum protendit manu, quo signum clementiæ monstrabatur: illaque consurgens stetit ante eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'et ait: Si placet regi, et si inveni gratiam in oculis ejus, et deprecatio mea non ei videtur esse contraria, obsecro ut novis epistolis, veteres Aman litteræ, insidiatoris et hostis Judæorum, quibus eos in cunctis regis provinciis perire præceperat, corrigantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Quomodo enim potero sustinere necem et interfectionem populi mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Responditque rex Assuerus Esther reginæ, et Mardochæo Judæo: Domum Aman concessi Esther, et ipsum jussi affigi cruci, quia ausus est manum mittere in Judæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Scribite ergo Judæis, sicut vobis placet, regis nomine, signantes litteras annulo meo. Hæc enim consuetudo erat, ut epistolis, quæ ex regis nomine mittebantur et illius annulo signatæ erant, nemo auderet contradicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Accitisque scribis et librariis regis (erat autem tempus tertii mensis, qui appellatur Siban) vigesima et tertia die illius scriptæ sunt epistolæ, ut Mardochæus voluerat, ad Judæos, et ad principes, procuratoresque et judices, qui centum viginti septem provinciis ab India usque ad \'thiopiam præsidebant: provinciæ atque provinciæ, populo et populo juxta linguas et litteras suas, et Judæis, prout legere poterant et audire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Ipsæque epistolæ, quæ regis nomine mittebantur, annulo ipsius obsignatæ sunt, et missæ per veredarios: qui per omnes provincias discurrentes, veteres litteras novis nuntiis prævenirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 11, 'Quibus imperavit rex, ut convenirent Judæos per singulas civitates, et in unum præciperent congregari ut starent pro animabus suis, et omnes inimicos suos cum conjugibus ac liberis et universis domibus, interficerent atque delerent, et spolia eorum diriperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 12, 'Et constituta est per omnes provincias una ultionis dies, id est tertiadecima mensis duodecimi Adar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 13, 'Summaque epistolæ hæc fuit, ut in omnibus terris ac populis qui regis Assueri subjacebant imperio, notum fieret paratos esse Judæos ad capiendam vindictam de hostibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 14, 'Egressique sunt veredarii celeres nuntia perferentes, et edictum regis pependit in Susan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 15, 'Mardochæus autem de palatio et de conspectu regis egrediens, fulgebat vestibus regiis, hyacinthinis videlicet et æriis, coronam auream portans in capite, et amictus serico pallio atque purpureo. Omnisque civitas exultavit atque lætata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 16, 'Judæis autem nova lux oriri visa est, gaudium, honor, et tripudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 17, 'Apud omnes populos, urbes, atque provincias, quocumque regis jussa veniebant, mira exultatio, epulæ atque convivia, et festus dies: in tantum ut plures alterius gentis et sectæ eorum religioni et cæremoniis jungerentur. Grandis enim cunctos judaici nominis terror invaserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Igitur duodecimi mensis, quem Adar vocari ante jam diximus, tertiadecima die, quando cunctis Judæis interfectio parabatur, et hostes eorum inhiabant sanguini, versa vice Judæi superiores esse cœperunt, et se de adversariis vindicare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Congregatique sunt per singulas civitates, oppida, et loca, ut extenderent manum contra inimicos, et persecutores suos. Nullusque ausus est resistere, eo quod omnes populos magnitudinis eorum formido penetrarat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Nam et provinciarum judices, et duces, et procuratores, omnisque dignitas quæ singulis locis ac operibus præerat, extollebant Judæos timore Mardochæi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'quem principem esse palatii, et plurimum posse cognoverant: fama quoque nominis ejus crescebat quotidie, et per cunctorum ora volitabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Itaque percusserunt Judæi inimicos suos plaga magna, et occiderunt eos, reddentes eis quod sibi paraverant facere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'in tantum ut etiam in Susan quingentos viros interficerent, extra decem filios Aman Agagitæ hostis Judæorum: quorum ista sunt nomina:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Pharsandatha, et Delphon, et Esphatha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'et Phoratha, et Adalia, et Aridatha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'et Phermesta, et Arisai, et Aridai, et Jezatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Quos cum occidissent, prædas de substantiis eorum tangere noluerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Statimque numerus eorum, qui occisi erant in Susan, ad regem relatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Qui dixit reginæ: In urbe Susan interfecerunt Judæi quingentos viros, et alios decem filios Aman: quantam putas eos exercere cædem in universis provinciis? quid ultra postulas, et quid vis ut fieri jubeam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Cui illa respondit: Si regi placet, detur potestas Judæis, ut sicut fecerunt hodie in Susan, sic et cras faciant, et decem filii Aman in patibulis suspendantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Præcepitque rex ut ita fieret. Statimque in Susan pependit edictum, et decem filii Aman suspensi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Congregatis Judæis quartadecima die mensis Adar, interfecti sunt in Susan trecenti viri: nec eorum ab illis direpta substantia est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Sed et per omnes provincias quæ ditioni regis subjacebant, pro animabus suis steterunt Judæi, interfectis hostibus ac persecutoribus suis: in tantum ut septuaginta quinque millia occisorum implerentur, et nullus de substantiis eorum quidquam contingeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Dies autem tertiusdecimus mensis Adar primus apud omnes interfectionis fuit, et quartadecima die cædere desierunt. Quem constituerunt esse solemnem, ut in eo omni tempore deinceps vacarent epulis, gaudio, atque conviviis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'At hi, qui in urbe Susan cædem exercuerant, tertiodecimo et quartodecimo die ejusdem mensis in cæde versati sunt: quintodecimo autem die percutere desierunt. Et idcirco eumdem diem constituerunt solemnem epularum atque lætitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Hi vero Judæi, qui in oppidis non muratis ac villis morabantur, quartumdecimum diem mensis Adar conviviorum et gaudii decreverunt, ita ut exultent in eo, et mittant sibi mutuo partes epularum et ciborum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Scripsit itaque Mardochæus omnia hæc, et litteris comprehensa misit ad Judæos qui in omnibus regis provinciis morabantur, tam in vicino positis, quam procul,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'ut quartamdecimam et quintamdecimam diem mensis Adar pro festis susciperent, et revertente semper anno solemni celebrarent honore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 22, 'quia in ipsis diebus se ulti sunt Judæi de inimicis suis, et luctus atque tristitia in hilaritatem gaudiumque conversa sunt, essentque dies isti epularum atque lætitiæ, et mitterent sibi invicem ciborum partes, et pauperibus munuscula largirentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 23, 'Susceperuntque Judæi in solemnem ritum cuncta quæ eo tempore facere cœperant, et quæ Mardochæus litteris facienda mandaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 24, 'Aman enim, filius Amadathi stirpis Agag, hostis et adversarius Judæorum, cogitavit contra eos malum, ut occideret illos atque deleret: et misit phur, quod nostra lingua vertitur in sortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 25, 'Et postea ingressa est Esther ad regem, obsecrans ut conatus ejus litteris regis irriti fierent, et malum quod contra Judæos cogitaverat, reverteretur in caput ejus. Denique et ipsum et filios ejus affixerunt cruci,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 26, 'atque ex illo tempore dies isti appellati sunt phurim, id est sortium: eo quod phur, id est sors, in urnam missa fuerit. Et cuncta quæ gesta sunt, epistolæ, id est, libri hujus volumine, continentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 27, 'quæque sustinuerunt, et quæ deinceps immutata sunt, susceperunt Judæi super se et semen suum, et super cunctos qui religioni eorum voluerunt copulari, ut nulli liceat duos hos dies absque solemnitate transigere, quos scriptura testatur, et certa expetunt tempora, annis sibi jugiter succedentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 28, 'Isti sunt dies, quos nulla umquam delebit oblivio, et per singulas generationes cunctæ in toto orbe provinciæ celebrabunt: nec est ulla civitas, in qua dies phurim, id est sortium, non observentur a Judæis, et ab eorum progenie, quæ his cæremoniis obligata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 29, 'Scripseruntque Esther regina filia Abihail, et Mardochæus Judæus, etiam secundam epistolam, ut omni studio dies ista solemnis sanciretur in posterum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 30, 'et miserunt ad omnes Judæos qui in centum viginti septem provinciis regis Assueri versabantur, ut haberent pacem, et susciperent veritatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 31, 'observantes dies sortium, et suo tempore cum gaudio celebrarent: sicut constituerant Mardochæus et Esther, et illi observanda susceperunt a se, et a semine suo, jejunia, et clamores, et sortium dies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 32, 'et omnia quæ libri hujus, qui vocatur Esther, historia continentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Rex vero Assuerus omnem terram et cunctas maris insulas fecit tributarias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'cujus fortitudo et imperium, et dignitas atque sublimitas, qua exaltavit Mardochæum, scripta sunt in libris Medorum, atque Persarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'et quomodo Mardochæus judaici generis secundus a rege Assuero fuerit, et magnus apud Judæos, et acceptabilis plebi fratrum suorum, quærens bona populo suo, et loquens ea quæ ad pacem seminis sui pertinerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Dixitque Mardochæus: A Deo facta sunt ista.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Recordatus sum somnii quod videram, hæc eadem significantis: nec eorum quidquam irritum fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Parvus fons, qui crevit in fluvium, et in lucem solemque conversus est, et in aquas plurimas redundavit: Esther est quam rex accepit uxorem, et voluit esse reginam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Duo autem dracones: ego sum, et Aman.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Gentes, quæ convenerant: hi sunt, qui conati sunt delere nomen Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Gens autem mea Israël est, quæ clamavit ad Dominum, et salvum fecit Dominus populum suum: liberavitque nos ab omnibus malis, et fecit signa magna atque portenta inter gentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'et duas sortes esse præcepit, unam populi Dei, et alteram cunctarum gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Venitque utraque sors in statutum ex illo jam tempore diem coram Deo universis gentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'et recordatus est Dominus populi sui, ac misertus est hæreditatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Et observabuntur dies isti in mense Adar quartadecima et quintadecima die ejusdem mensis, cum omni studio et gaudio, in unum cœtum populi congregati, in cunctas deinceps generationes populi Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Anno quarto regnantibus Ptolemæo et Cleopatra, attulerunt Dosithæus, qui se sacerdotem et Levitici generis ferebat, et Ptolemæus filius ejus, hanc epistolam phurim, quam dixerunt interpretatum esse Lysimachum Ptolemæi filium in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Anno secundo, regnante Artaxerxe maximo, prima die mensis Nisan, vidit somnium Mardochæus filius Jairi, filii Semei, filii Cis, de tribu Benjamin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'homo Judæus, qui habitabat in urbe Susis, vir magnus, et inter primos aulæ regiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Erat autem de eo numero captivorum, quos transtulerat Nabuchodonosor rex Babylonis de Jerusalem cum Jechonia rege Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Et hoc ejus somnium fuit: apparuerunt voces, et tumultus, et tonitrua, et terræmotus, et conturbatio super terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'et ecce duo dracones magni, paratique contra se in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Ad quorum clamorem cunctæ concitatæ sunt nationes, ut pugnarent contra gentem justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 8, 'Fuitque dies illa tenebrarum et discriminis, tribulationis et angustiæ, et ingens formido super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 9, 'Conturbataque est gens justorum timentium mala sua, et præparata ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 10, 'Clamaveruntque ad Deum: et illis vociferantibus, fons parvus creavit in fluvium maximum, et in aquas plurimas redundavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 11, 'Lux et sol ortus est, et humiles exaltati sunt, et devoraverunt inclytos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 12, 'Quod cum vidisset Mardochæus, et surrexisset de strato, cogitabat quid Deus facere vellet: et fixum habebat in animo, scire cupiens quid significaret somnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Morabatur autem eo tempore in aula regis cum Bagatha et Thara eunuchis regis, qui janitores erant palatii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Cumque intellexisset cogitationes eorum, et curas diligentius pervidisset, didicit quod conarentur in regem Artaxerxem manus mittere, et nuntiavit super eo regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Qui de utroque, habita quæstione, confessos jussit duci ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Rex autem quod gestum erat, scripsit in commentariis: sed et Mardochæus rei memoriam litteris tradidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Præcepitque ei rex, ut in aula palatii moraretur, datis ei pro delatione muneribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Aman vero filius Amadathi Bugæus erat gloriosissimus coram rege, et voluit nocere Mardochæo et populo ejus pro duobus eunuchis regis qui fuerant interfecti. Et diripuerunt bona, vel substantias eorum. Epistolæ autem hoc exemplar fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Rex maximus Artaxerxes ab India usque \'thiopiam, centum viginti septem provinciarum principibus et ducibus qui ejus imperio subjecti sunt, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Cum plurimis gentibus imperarem, et universum orbem meæ ditioni subjugassem, volui nequaquam abuti potentiæ magnitudine, sed clementia et lenitate gubernare subjectos, ut absque ullo terrore vitam silentio transigentes, optata cunctis mortalibus pace fruerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Quærente autem me a consiliariis meis quomodo posset hoc impleri, unus qui sapientia et fide ceteros præcellebat, et erat post regem secundus, Aman nomine,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'indicavit mihi in toto orbe terrarum populum esse dispersum, qui novis uteretur legibus, et, contra omnium gentium consuetudinem faciens, regum jussa contemneret, et universarum concordiam nationum sua dissensione violaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Quod cum didicissemus, videntes unam gentem rebellem adversus omne hominum genus perversis uti legibus, nostrisque jussionibus contraire, et turbare subjectarum nobis provinciarum pacem atque concordiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'jussimus ut quoscumque Aman, qui omnibus provinciis præpositus est et secundus a rege, et quem patris loco colimus, monstraverit, cum conjugibus ac liberis deleantur ab inimicis suis, nullusque eorum misereatur, quartadecima die duodecimi mensis Adar anni præsentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 7, 'ut nefarii homines uno die ad inferos descendentes, reddant imperio nostro pacem, quam turbaverant. Pergensque Mardochæus, fecit omnia quæ ei mandaverat Esther.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 8, 'Mardochæus autem deprecatus est Dominum, memor omnium operum ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 9, 'et dixit: Domine, Domine rex omnipotens, in ditione enim tua cuncta sunt posita, et non est qui possit tuæ resistere voluntati, si decreveris salvare Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 10, 'Tu fecisti cælum et terram, et quidquid cæli ambitu continetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 11, 'Dominus omnium es, nec est qui resistat majestati tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 12, 'Cuncta nosti, et scis quia non pro superbia et contumelia, et aliqua gloriæ cupiditate, fecerim hoc, ut non adorarem Aman superbissimum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 13, '(libenter enim pro salute Israël etiam vestigia pedum ejus deosculari paratus essem),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 14, 'sed timui ne honorem Dei mei transferrem ad hominem, et ne quemquam adorarem, excepto Deo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 15, 'Et nunc, Domine rex, Deus Abraham, miserere populi tui, quia volunt nos inimici nostri perdere, et hæreditatem tuam delere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 16, 'Ne despicias partem tuam, quam redemisti tibi de \'gypto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 17, 'Exaudi deprecationem meam, et propitius esto sorti et funiculo tuo, et converte luctum nostrum in gaudium, ut viventes laudemus nomen tuum, Domine: et ne claudas ora te canentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 18, 'Omnis quoque Israël pari mente et obsecratione clamavit ad Dominum, eo quod eis certa mors impenderet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Esther quoque regina confugit ad Dominum, pavens periculum quod imminebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Cumque deposuisset vestes regias, fletibus et luctui apta indumenta suscepit, et pro unguentis variis, cinere et stercore implevit caput, et corpus suum humiliavit jejuniis: omniaque loca, in quibus antea lætari consueverat, crinium laceratione complevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Et deprecabatur Dominum Deum Israël, dicens: Domine mi, qui rex noster es solus, adjuva me solitariam, et cujus præter te nullus est auxiliator alius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Periculum meum in manibus meis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Audivi a patre meo quod tu, Domine, tulisses Israël de cunctis gentibus, et patres nostros ex omnibus retro majoribus suis, ut possideres hæreditatem sempiternam, fecistique eis sicut locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Peccavimus in conspectu tuo, et idcirco tradidisti nos in manus inimicorum nostrorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'coluimus enim deos eorum. Justus es Domine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 8, 'et nunc non eis sufficit, quod durissima nos opprimunt servitute, sed robur manuum suarum, idolorum potentiæ deputantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 9, 'volunt tua mutare promissa, et delere hæreditatem tuam, et claudere ora laudantium te, atque extinguere gloriam templi et altaris tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 10, 'ut aperiant ora gentium, et laudent idolorum fortitudinem, et prædicent carnalem regem in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 11, 'Ne tradas, Domine, sceptrum tuum his, qui non sunt, ne rideant ad ruinam nostram: sed converte consilium eorum super eos, et eum qui in nos cœpit sævire, disperde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 12, 'Memento, Domine, et ostende te nobis in tempore tribulationis nostræ, et da mihi fiduciam, Domine rex deorum, et universæ potestatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 13, 'tribue sermonem compositum in ore meo in conspectu leonis, et transfer cor illius in odium hostis nostri, ut et ipse pereat, et ceteri qui ei consentiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 14, 'Nos autem libera manu tua, et adjuva me, nullum aliud auxilium habentem nisi te, Domine, qui habes omnium scientiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 15, 'et nosti quia oderim gloriam iniquorum, et detester cubile incircumcisorum, et omnis alienigenæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 16, 'Tu scis necessitatem meam, quod abominer signum superbiæ et gloriæ meæ, quod est super caput meum in diebus ostentationis meæ, et detester illud quasi pannum menstruatæ, et non portem in diebus silentii mei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 17, 'et quod non comederim in mensa Aman, nec mihi placuerit convivium regis, et non biberim vinum libaminum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 18, 'et numquam lætata sit ancilla tua, ex quo huc translata sum usque in præsentem diem, nisi in te, Domine Deus Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 19, 'Deus fortis super omnes, exaudi vocem eorum qui nullam aliam spem habent, et libera nos de manu iniquorum, et erue me a timore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Et mandavit ei (haud dubium quin esset Mardochæus) ut ingrederetur ad regem, et rogaret pro populo suo et pro patria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Memorare, inquit, dierum humilitatis tuæ, quomodo nutrita sis in manu mea, quia Aman secundus a rege locutus est contra nos in mortem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'et tu invoca Dominum, et loquere regi pro nobis, et libera nos de morte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Die autem tertio deposuit vestimenta ornatus sui, et circumdata est gloria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Cumque regio fulgeret habitu, et invocasset omnium rectorem et salvatorem Deum, assumpsit duas famulas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 6, 'et super unam quidem innitebatur, quasi præ deliciis et nimia teneritudine corpus suum ferre non sustinens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 7, 'altera autem famularum sequebatur dominam, defluentia in humum indumenta sustentans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 8, 'Ipsa autem roseo colore vultum perfusa, et gratis ac nitentibus oculis, tristem celabat animum, et nimio timore contractum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 9, 'Ingressa igitur cuncta per ordinem ostia, stetit contra regem, ubi ille residebat super solium regni sui, indutus vestibus regiis, auroque fulgens, et pretiosis lapidibus: eratque terribilis aspectu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 10, 'Cumque elevasset faciem, et ardentibus oculis furorem pectoris indicasset, regina corruit, et in pallorem colore mutato, lassum super ancillulam reclinavit caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 11, 'Convertitque Deus spiritum regis in mansuetudinem, et festinus ac metuens exilivit de solio, et sustentans eam ulnis suis donec rediret ad se, his verbis blandiebatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 12, 'Quid habes, Esther? ego sum frater tuus: noli metuere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 13, 'Non morieris: non enim pro te, sed pro omnibus hæc lex constituta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 14, 'Accede igitur, et tange sceptrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 15, 'Cumque illa reticeret, tulit auream virgam, et posuit super collum ejus, et osculatus est eam, et ait: Cur mihi non loqueris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 16, 'Quæ respondit: Vidi te, domine, quasi angelum Dei, et conturbatum est cor meum præ timore gloriæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 17, 'Valde enim mirabilis es, domine, et facies tua plena est gratiarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 18, 'Cumque loqueretur, rursus corruit, et pene exanimata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 19, 'Rex autem turbabatur, et omnes ministri ejus consolabantur eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Rex magnus Artaxerxes ab India usque \'thiopiam, centum viginti septem provinciarum ducibus ac principibus qui nostræ jussioni obediunt, salutem dicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Multi bonitate principum et honore, qui in eos collatus est, abusi sunt in superbiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'et non solum subjectos regibus nituntur opprimere, sed datam sibi gloriam non ferentes, in ipsos qui dederunt, moliuntur insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Nec contenti sunt gratias non agere beneficiis, et humanitatis in se jura violare, sed Dei quoque cuncta cernentis arbitrantur se posse fugere sententiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Et in tantum vesaniæ proruperunt, ut eos qui credita sibi officia diligenter observant, et ita cuncta agunt ut omnium laude digni sint, mendaciorum cuniculis conentur subvertere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'dum aures principum simplices, et ex sua natura alios æstimantes, callida fraude decipiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Quæ res et ex veteribus probatur historiis, et ex his quæ geruntur quotidie, quomodo malis quorumdam suggestionibus regum studia depraventur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Unde providendum est paci omnium provinciarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Nec putare debetis, si diversa jubeamus, ex animi nostri venire levitate, sed pro qualitate et necessitate temporum, ut reipublicæ poscit utilitas, ferre sententiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Et ut manifestius quod dicimus intelligatis, Aman filius Amadathi, et animo et gente Macedo, alienusque a Persarum sanguine, et pietatem nostram sua crudelitate commaculans, peregrinus a nobis susceptus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'et tantam in se expertus humanitatem, ut pater noster vocaretur, et adoraretur ab omnibus post regem secundus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 12, 'qui in tantum arrogantiæ tumorem sublatus est, ut regno privare nos niteretur et spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 13, 'Nam Mardochæum, cujus fide et beneficiis vivimus, et consortem regni nostri Esther cum omni gente sua, novis quibusdam atque inauditis machinis expetivit in mortem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 14, 'hoc cogitans ut illis interfectis, insidiaretur nostræ solitudini, et regnum Persarum transferret in Macedonas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 15, 'Nos autem a pessimo mortalium Judæos neci destinatos, in nulla penitus culpa reperimus, sed e contrario justis utentes legibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 16, 'et filios altissimi et maximi semperque viventis Dei, cujus beneficio et patribus nostris et nobis regnum est traditum, et usque hodie custoditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 17, 'Unde eas litteras, quas sub nomine nostro ille direxerat, sciatis esse irritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 18, 'Pro quo scelere ante portas hujus urbis, id est, Susan, et ipse qui machinatus est, et omnis cognatio ejus pendet in patibulis: non nobis, sed Deo reddente ei quod meruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 19, 'Hoc autem edictum, quod nunc mittimus, in cunctis urbibus proponatur, ut liceat Judæis uti legibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 20, 'Quibus debetis esse adminiculo, ut eos qui se ad necem eorum paraverant, possint interficere tertiadecima die mensis duodecimi, qui vocatur Adar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 21, 'Hanc enim diem, Deus omnipotens, mœroris et luctus, eis vertit in gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 22, 'Unde et vos inter ceteros festos dies, hanc habetote diem, et celebrate eam cum omni lætitia, ut et in posterum cognoscatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 23, 'omnes qui fideliter Persis obediunt, dignam pro fide recipere mercedem; qui autem insidiantur regno eorum, perire pro scelere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 24, 'Omnis autem provincia et civitas quæ noluerit solemnitatis hujus esse particeps, gladio et igne pereat, et sic deleatur, ut non solum hominibus, sed etiam bestiis invia sit in sempiternum, pro exemplo contemptus et inobedientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Vir erat in terra Hus, nomine Job: et erat vir ille simplex, et rectus, ac timens Deum, et recedens a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Natique sunt ei septem filii, et tres filiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Et fuit possessio ejus septem millia ovium, et tria millia camelorum, quingenta quoque juga boum, et quingentæ asinæ, ac familia multa nimis: eratque vir ille magnus inter omnes orientales.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Et ibant filii ejus, et faciebant convivium per domos, unusquisque in die suo. Et mittentes vocabant tres sorores suas, ut comederent et biberent cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Cumque in orbem transissent dies convivii, mittebat ad eos Job, et sanctificabat illos: consurgensque diluculo, offerebat holocausta pro singulis. Dicebat enim: Ne forte peccaverint filii mei, et benedixerint Deo in cordibus suis. Sic faciebat Job cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Quadam autem die, cum venissent filii Dei ut assisterent coram Domino, affuit inter eos etiam Satan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Cui dixit Dominus: Unde venis? Qui respondens, ait: Circuivi terram, et perambulavi eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Dixitque Dominus ad eum: Numquid considerasti servum meum Job, quod non sit ei similis in terra, homo simplex et rectus, ac timens Deum, et recedens a malo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Cui respondens Satan, ait: Numquid Job frustra timet Deum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'nonne tu vallasti eum, ac domum ejus, universamque substantiam per circuitum; operibus manuum ejus benedixisti, et possessio ejus crevit in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'sed extende paululum manum tuam et tange cuncta quæ possidet, nisi in faciem benedixerit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Dixit ergo Dominus ad Satan: Ecce universa quæ habet in manu tua sunt: tantum in eum ne extendas manum tuam. Egressusque est Satan a facie Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Cum autem quadam die filii et filiæ ejus comederent et biberent vinum in domo fratris sui primogeniti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'nuntius venit ad Job, qui diceret: Boves arabant, et asinæ pascebantur juxta eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'et irruerunt Sabæi, tuleruntque omnia, et pueros percusserunt gladio: et evasi ego solus, ut nuntiarem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Cumque adhuc ille loqueretur, venit alter, et dixit: Ignis Dei cecidit e cælo, et tactas oves puerosque consumpsit: et effugi ego solus, ut nuntiarem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Sed et illo adhuc loquente, venit alius, et dixit: Chaldæi fecerunt tres turmas, et invaserunt camelos, et tulerunt eos, necnon et pueros percusserunt gladio: et ego fugi solus, ut nuntiarem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Adhuc loquebatur ille, et ecce alius intravit, et dixit: Filiis tuis et filiabus vescentibus et bibentibus vinum in domo fratris sui primogeniti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'repente ventus vehemens irruit a regione deserti, et concussit quatuor angulos domus: quæ corruens oppressit liberos tuos, et mortui sunt: et effugi ego solus, ut nuntiarem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Tunc surrexit Job, et scidit vestimenta sua: et tonso capite corruens in terram, adoravit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'et dixit: Nudus egressus sum de utero matris meæ, et nudus revertar illuc. Dominus dedit, Dominus abstulit; sicut Domino placuit, ita factum est. Sit nomen Domini benedictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'In omnibus his non peccavit Job labiis suis, neque stultum quid contra Deum locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Factum est autem, cum quadam die venissent filii Dei, et starent coram Domino, venisset quoque Satan inter eos, et staret in conspectu ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'ut diceret Dominus ad Satan: Unde venis? Qui respondens ait: Circuivi terram, et perambulavi eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Et dixit Dominus ad Satan: Numquid considerasti servum meum Job, quod non sit ei similis in terra, vir simplex et rectus, ac timens Deum, et recedens a malo, et adhuc retinens innocentiam? tu autem commovisti me adversus eum, ut affligerem eum frustra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Cui respondens Satan, ait: Pellem pro pelle, et cuncta quæ habet homo dabit pro anima sua;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'alioquin mitte manum tuam, et tange os ejus et carnem, et tunc videbis quod in faciem benedicat tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Dixit ergo Dominus ad Satan: Ecce in manu tua est: verumtamen animam illius serva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Egressus igitur Satan a facie Domini, percussit Job ulcere pessimo, a planta pedis usque ad verticem ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'qui testa saniem radebat, sedens in sterquilinio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Dixit autem illi uxor sua: Adhuc tu permanes in simplicitate tua? Benedic Deo, et morere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Qui ait ad illam: Quasi una de stultis mulieribus locuta es: si bona suscepimus de manu Dei, mala quare non suscipiamus? In omnibus his non peccavit Job labiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Igitur audientes tres amici Job omne malum quod accidisset ei, venerunt singuli de loco suo, Eliphaz Themanites, et Baldad Suhites, et Sophar Naamathites. Condixerant enim ut pariter venientes visitarent eum, et consolarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Cumque elevassent procul oculos suos, non cognoverunt eum, et exclamantes ploraverunt, scissisque vestibus sparserunt pulverem super caput suum in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Et sederunt cum eo in terra septem diebus et septem noctibus: et nemo loquebatur ei verbum: videbant enim dolorem esse vehementem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Post hæc aperuit Job os suum, et maledixit diei suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'et locutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Pereat dies in qua natus sum, et nox in qua dictum est: Conceptus est homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Dies ille vertatur in tenebras: non requirat eum Deus desuper, et non illustretur lumine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Obscurent eum tenebræ et umbra mortis; occupet eum caligo, et involvatur amaritudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Noctem illam tenebrosus turbo possideat; non computetur in diebus anni, nec numeretur in mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Sit nox illa solitaria, nec laude digna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Maledicant ei qui maledicunt diei, qui parati sunt suscitare Leviathan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Obtenebrentur stellæ caligine ejus; expectet lucem, et non videat, nec ortum surgentis auroræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Quia non conclusit ostia ventris qui portavit me, nec abstulit mala ab oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Quare non in vulva mortuus sum? egressus ex utero non statim perii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Quare exceptus genibus? cur lactatus uberibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Nunc enim dormiens silerem, et somno meo requiescerem');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'cum regibus et consulibus terræ, qui ædificant sibi solitudines;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'aut cum principibus qui possident aurum, et replent domos suas argento;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'aut sicut abortivum absconditum non subsisterem, vel qui concepti non viderunt lucem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ibi impii cessaverunt a tumultu, et ibi requieverunt fessi robore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Et quondam vincti pariter sine molestia, non audierunt vocem exactoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Parvus et magnus ibi sunt, et servus liber a domino suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Quare misero data est lux, et vita his qui in amaritudine animæ sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'qui expectant mortem, et non venit, quasi effodientes thesaurum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'gaudentque vehementer cum invenerint sepulchrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'viro cujus abscondita est via et circumdedit eum Deus tenebris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Antequam comedam, suspiro; et tamquam inundantes aquæ, sic rugitus meus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'quia timor quem timebam evenit mihi, et quod verebar accidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Nonne dissimulavi? nonne silui? nonne quievi? et venit super me indignatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Respondens autem Eliphaz Themanites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Si cœperimus loqui tibi, forsitan moleste accipies; sed conceptum sermonem tenere quis poterit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Ecce docuisti multos, et manus lassas roborasti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'vacillantes confirmaverunt sermones tui, et genua trementia confortasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Nunc autem venit super te plaga, et defecisti; tetigit te, et conturbatus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ubi est timor tuus, fortitudo tua, patientia tua, et perfectio viarum tuarum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Recordare, obsecro te, quis umquam innocens periit? aut quando recti deleti sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Quin potius vidi eos qui operantur iniquitatem, et seminant dolores, et metunt eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'flante Deo perisse, et spiritu iræ ejus esse consumptos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Rugitus leonis, et vox leænæ, et dentes catulorum leonum contriti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Tigris periit, eo quod non haberet prædam, et catuli leonis dissipati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Porro ad me dictum est verbum absconditum, et quasi furtive suscepit auris mea venas susurri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'In horrore visionis nocturnæ, quando solet sopor occupare homines,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'pavor tenuit me, et tremor, et omnia ossa mea perterrita sunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'et cum spiritus, me præsente, transiret, inhorruerunt pili carnis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Stetit quidam, cujus non agnoscebam vultum, imago coram oculis meis, et vocem quasi auræ lenis audivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Numquid homo, Dei comparatione, justificabitur? aut factore suo purior erit vir?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Ecce qui serviunt ei, non sunt stabiles, et in angelis suis reperit pravitatem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'quanto magis hi qui habitant domos luteas, qui terrenum habent fundamentum, consumentur velut a tinea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'De mane usque ad vesperam succidentur; et quia nullus intelligit, in æternum peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Qui autem reliqui fuerint, auferentur ex eis; morientur, et non in sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Voca ergo, si est qui tibi respondeat, et ad aliquem sanctorum convertere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Vere stultum interficit iracundia, et parvulum occidit invidia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Ego vidi stultum firma radice, et maledixi pulchritudini ejus statim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Longe fient filii ejus a salute, et conterentur in porta, et non erit qui eruat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Cujus messem famelicus comedet, et ipsum rapiet armatus, et bibent sitientes divitias ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Nihil in terra sine causa fit, et de humo non oritur dolor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Homo nascitur ad laborem, et avis ad volatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Quam ob rem ego deprecabor Dominum, et ad Deum ponam eloquium meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'qui facit magna et inscrutabilia, et mirabilia absque numero;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'qui dat pluviam super faciem terræ, et irrigat aquis universa;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'qui ponit humiles in sublime, et mœrentes erigit sospitate;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'qui dissipat cogitationes malignorum, ne possint implere manus eorum quod cœperant;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'qui apprehendit sapientes in astutia eorum, et consilium pravorum dissipat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Per diem incurrent tenebras, et quasi in nocte, sic palpabunt in meridie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Porro salvum faciet egenum a gladio oris eorum, et de manu violenti pauperem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Et erit egeno spes; iniquitas autem contrahet os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Beatus homo qui corripitur a Deo: increpationem ergo Domini ne reprobes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'quia ipse vulnerat, et medetur; percutit, et manus ejus sanabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'In sex tribulationibus liberabit te, et in septima non tanget te malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'In fame eruet te de morte, et in bello de manu gladii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'A flagello linguæ absconderis, et non timebis calamitatem cum venerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'In vastitate et fame ridebis, et bestias terræ non formidabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Sed cum lapidibus regionum pactum tuum, et bestiæ terræ pacificæ erunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 24, 'Et scies quod pacem habeat tabernaculum tuum; et visitans speciem tuam, non peccabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 25, 'Scies quoque quoniam multiplex erit semen tuum, et progenies tua quasi herba terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 26, 'Ingredieris in abundantia sepulchrum, sicut infertur acervus tritici in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 27, 'Ecce hoc, ut investigavimus, ita est: quod auditum, mente pertracta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Respondens autem Job, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Utinam appenderentur peccata mea quibus iram merui, et calamitas quam patior, in statera!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Quasi arena maris hæc gravior appareret; unde et verba mea dolore sunt plena:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'quia sagittæ Domini in me sunt, quarum indignatio ebibit spiritum meum; et terrores Domini militant contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Numquid rugiet onager cum habuerit herbam? aut mugiet bos cum ante præsepe plenum steterit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'aut poterit comedi insulsum, quod non est sale conditum? aut potest aliquis gustare quod gustatum affert mortem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Quæ prius nolebat tangere anima mea, nunc, præ angustia, cibi mei sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Quis det ut veniat petitio mea, et quod expecto tribuat mihi Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'et qui cœpit, ipse me conterat; solvat manum suam, et succidat me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Et hæc mihi sit consolatio, ut affligens me dolore, non parcat, nec contradicam sermonibus Sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Quæ est enim fortitudo mea, ut sustineam? aut quis finis meus, ut patienter agam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Nec fortitudo lapidum fortitudo mea, nec caro mea ænea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Ecce non est auxilium mihi in me, et necessarii quoque mei recesserunt a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Qui tollit ab amico suo misericordiam, timorem Domini derelinquit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Fratres mei præterierunt me, sicut torrens qui raptim transit in convallibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Qui timent pruinam, irruet super eos nix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Tempore quo fuerint dissipati, peribunt; et ut incaluerit, solventur de loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Involutæ sunt semitæ gressuum eorum; ambulabunt in vacuum, et peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Considerate semitas Thema, itinera Saba, et expectate paulisper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Confusi sunt, quia speravi: venerunt quoque usque ad me, et pudore cooperti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Nunc venistis; et modo videntes plagam meam, timetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Numquid dixi: Afferte mihi, et de substantia vestra donate mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'vel: Liberate me de manu hostis, et de manu robustorum eruite me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Docete me, et ego tacebo: et si quid forte ignoravi, instruite me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Quare detraxistis sermonibus veritatis, cum e vobis nullus sit qui possit arguere me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Ad increpandum tantum eloquia concinnatis, et in ventum verba profertis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Super pupillum irruitis, et subvertere nitimini amicum vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Verumtamen quod cœpistis explete: præbete aurem, et videte an mentiar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Respondete, obsecro, absque contentione; et loquentes id quod justum est, judicate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Et non invenietis in lingua mea iniquitatem, nec in faucibus meis stultitia personabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Militia est vita hominis super terram, et sicut dies mercenarii dies ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Sicut servus desiderat umbram, et sicut mercenarius præstolatur finem operis sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'sic et ego habui menses vacuos, et noctes laboriosas enumeravi mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Si dormiero, dicam: Quando consurgam? et rursum expectabo vesperam, et replebor doloribus usque ad tenebras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Induta est caro mea putredine, et sordibus pulveris cutis mea aruit et contracta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Dies mei velocius transierunt quam a texente tela succiditur, et consumpti sunt absque ulla spe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Memento quia ventus est vita mea, et non revertetur oculus meus ut videat bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Nec aspiciet me visus hominis; oculi tui in me, et non subsistam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Sicut consumitur nubes, et pertransit, sic qui descenderit ad inferos, non ascendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Nec revertetur ultra in domum suam, neque cognoscet eum amplius locus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Quapropter et ego non parcam ori meo: loquar in tribulatione spiritus mei; confabulabor cum amaritudine animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Numquid mare ego sum, aut cetus, quia circumdedisti me carcere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Si dixero: Consolabitur me lectulus meus, et relevabor loquens mecum in strato meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'terrebis me per somnia, et per visiones horrore concuties.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Quam ob rem elegit suspendium anima mea, et mortem ossa mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Desperavi: nequaquam ultra jam vivam: parce mihi, nihil enim sunt dies mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Quid est homo, quia magnificas eum? aut quid apponis erga eum cor tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Visitas eum diluculo, et subito probas illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Usquequo non parcis mihi, nec dimittis me ut glutiam salivam meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Peccavi; quid faciam tibi, o custos hominum? quare posuisti me contrarium tibi, et factus sum mihimetipsi gravis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Cur non tollis peccatum meum, et quare non aufers iniquitatem meam? ecce nunc in pulvere dormiam, et si mane me quæsieris, non subsistam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Respondens autem Baldad Suhites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Usquequo loqueris talia, et spiritus multiplex sermones oris tui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Numquid Deus supplantat judicium? aut Omnipotens subvertit quod justum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Etiam si filii tui peccaverunt ei, et dimisit eos in manu iniquitatis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'tu tamen si diluculo consurrexeris ad Deum, et Omnipotentem fueris deprecatus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'si mundus et rectus incesseris: statim evigilabit ad te, et pacatum reddet habitaculum justitiæ tuæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'in tantum ut si priora tua fuerint parva, et novissima tua multiplicentur nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Interroga enim generationem pristinam, et diligenter investiga patrum memoriam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, '(hesterni quippe sumus, et ignoramus, quoniam sicut umbra dies nostri sunt super terram),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'et ipsi docebunt te, loquentur tibi, et de corde suo proferent eloquia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Numquid vivere potest scirpus absque humore? aut crescere carectum sine aqua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Cum adhuc sit in flore, nec carpatur manu, ante omnes herbas arescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Sic viæ omnium qui obliviscuntur Deum, et spes hypocritæ peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Non ei placebit vecordia sua, et sicut tela aranearum fiducia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Innitetur super domum suam, et non stabit; fulciet eam, et non consurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Humectus videtur antequam veniat sol, et in ortu suo germen ejus egredietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Super acervum petrarum radices ejus densabuntur, et inter lapides commorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Si absorbuerit eum de loco suo, negabit eum, et dicet: Non novi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Hæc est enim lætitia viæ ejus, ut rursum de terra alii germinentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Deus non projiciet simplicem, nec porriget manum malignis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'donec impleatur risu os tuum, et labia tua jubilo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Qui oderunt te induentur confusione, et tabernaculum impiorum non subsistet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Et respondens Job, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Vere scio quod ita sit, et quod non justificetur homo compositus Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Si voluerit contendere cum eo, non poterit ei respondere unum pro mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Sapiens corde est, et fortis robore: quis restitit ei, et pacem habuit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Qui transtulit montes, et nescierunt hi quos subvertit in furore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Qui commovet terram de loco suo, et columnæ ejus concutiuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Qui præcipit soli, et non oritur, et stellas claudit quasi sub signaculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Qui extendit cælos solus, et graditur super fluctus maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Qui facit Arcturum et Oriona, et Hyadas et interiora austri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Qui facit magna, et incomprehensibilia, et mirabilia, quorum non est numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Si venerit ad me, non videbo eum; si abierit, non intelligam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Si repente interroget, quis respondebit ei? vel quis dicere potest: Cur ita facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Deus, cujus iræ nemo resistere potest, et sub quo curvantur qui portant orbem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Quantus ergo sum ego, ut respondeam ei, et loquar verbis meis cum eo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'qui etiam si habuero quippiam justum, non respondebo: sed meum judicem deprecabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Et cum invocantem exaudierit me, non credo quod audierit vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'In turbine enim conteret me, et multiplicabit vulnera mea, etiam sine causa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Non concedit requiescere spiritum meum, et implet me amaritudinibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 19, 'Si fortitudo quæritur, robustissimus est; si æquitas judicii, nemo audet pro me testimonium dicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 20, 'Si justificare me voluero, os meum condemnabit me; si innocentem ostendero, pravum me comprobabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 21, 'Etiam si simplex fuero, hoc ipsum ignorabit anima mea, et tædebit me vitæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 22, 'Unum est quod locutus sum: et innocentem et impium ipse consumit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 23, 'Si flagellat, occidat semel, et non de pœnis innocentum rideat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 24, 'Terra data est in manus impii; vultum judicum ejus operit. Quod si non ille est, quis ergo est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 25, 'Dies mei velociores fuerunt cursore; fugerunt, et non viderunt bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 26, 'Pertransierunt quasi naves poma portantes; sicut aquila volans ad escam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 27, 'Cum dixero: Nequaquam ita loquar: commuto faciem meam, et dolore torqueor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 28, 'Verebar omnia opera mea, sciens quod non parceres delinquenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 29, 'Si autem et sic impius sum, quare frustra laboravi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 30, 'Si lotus fuero quasi aquis nivis, et fulserint velut mundissimæ manus meæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 31, 'tamen sordibus intinges me, et abominabuntur me vestimenta mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 32, 'Neque enim viro qui similis mei est, respondebo; nec qui mecum in judicio ex æquo possit audiri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 33, 'Non est qui utrumque valeat arguere, et ponere manum suam in ambobus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 34, 'Auferat a me virgam suam, et pavor ejus non me terreat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 35, 'Loquar, et non timebo eum; neque enim possum metuens respondere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Tædet animam meam vitæ meæ; dimittam adversum me eloquium meum: loquar in amaritudine animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Dicam Deo: Noli me condemnare; indica mihi cur me ita judices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Numquid bonum tibi videtur, si calumnieris me, et opprimas me opus manuum tuarum, et consilium impiorum adjuves?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Numquid oculi carnei tibi sunt? aut sicut videt homo, et tu videbis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Numquid sicut dies hominis dies tui, et anni tui sicut humana sunt tempora,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'ut quæras iniquitatem meam, et peccatum meum scruteris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'et scias quia nihil impium fecerim, cum sit nemo qui de manu tua possit eruere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Manus tuæ fecerunt me, et plasmaverunt me totum in circuitu: et sic repente præcipitas me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Memento, quæso, quod sicut lutum feceris me, et in pulverem reduces me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Nonne sicut lac mulsisti me, et sicut caseum me coagulasti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Pelle et carnibus vestisti me; ossibus et nervis compegisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Vitam et misericordiam tribuisti mihi, et visitatio tua custodivit spiritum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Licet hæc celes in corde tuo, tamen scio quia universorum memineris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Si peccavi, et ad horam pepercisti mihi, cur ab iniquitate mea mundum me esse non pateris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Et si impius fuero, væ mihi est; et si justus, non levabo caput, saturatus afflictione et miseria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Et propter superbiam quasi leænam capies me, reversusque mirabiliter me crucias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Instauras testes tuos contra me, et multiplicas iram tuam adversum me, et pœnæ militant in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Quare de vulva eduxisti me? qui utinam consumptus essem, ne oculus me videret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Fuissem quasi non essem, de utero translatus ad tumulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Numquid non paucitas dierum meorum finietur brevi? dimitte ergo me, ut plangam paululum dolorem meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'antequam vadam, et non revertar, ad terram tenebrosam, et opertam mortis caligine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'terram miseriæ et tenebrarum, ubi umbra mortis et nullus ordo, sed sempiternus horror inhabitat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Respondens autem Sophar Naamathites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Numquid qui multa loquitur, non et audiet? aut vir verbosus justificabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Tibi soli tacebunt homines? et cum ceteros irriseris, a nullo confutaberis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Dixisti enim: Purus est sermo meus, et mundus sum in conspectu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Atque utinam Deus loqueretur tecum, et aperiret labia sua tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'ut ostenderet tibi secreta sapientiæ, et quod multiplex esset lex ejus: et intelligeres quod multo minora exigaris ab eo quam meretur iniquitas tua!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Forsitan vestigia Dei comprehendes, et usque ad perfectum Omnipotentem reperies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Excelsior cælo est, et quid facies? profundior inferno, et unde cognosces?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Longior terra mensura ejus, et latior mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Si subverterit omnia, vel in unum coarctaverit, quis contradicet ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Ipse enim novit hominum vanitatem; et videns iniquitatem, nonne considerat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Vir vanus in superbiam erigitur, et tamquam pullum onagri se liberum natum putat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Tu autem firmasti cor tuum, et expandisti ad eum manus tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Si iniquitatem quæ est in manu tua abstuleris a te, et non manserit in tabernaculo tuo injustitia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'tunc levare poteris faciem tuam absque macula; et eris stabilis, et non timebis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Miseriæ quoque oblivisceris, et quasi aquarum quæ præterierunt recordaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Et quasi meridianus fulgor consurget tibi ad vesperam; et cum te consumptum putaveris, orieris ut lucifer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Et habebis fiduciam, proposita tibi spe: et defossus securus dormies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Requiesces, et non erit qui te exterreat; et deprecabuntur faciem tuam plurimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Oculi autem impiorum deficient, et effugium peribit ab eis: et spes illorum abominatio animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Respondens autem Job, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Ergo vos estis soli homines, et vobiscum morietur sapientia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Et mihi est cor sicut et vobis, nec inferior vestri sum; quis enim hæc quæ nostis ignorat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Qui deridetur ab amico suo, sicut ego, invocabit Deum, et exaudiet eum: deridetur enim justi simplicitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Lampas contempta apud cogitationes divitum parata ad tempus statutum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Abundant tabernacula prædonum, et audacter provocant Deum, cum ipse dederit omnia in manus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Nimirum interroga jumenta, et docebunt te; et volatilia cæli, et indicabunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Loquere terræ, et respondebit tibi, et narrabunt pisces maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Quis ignorat quod omnia hæc manus Domini fecerit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'In cujus manu anima omnis viventis, et spiritus universæ carnis hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Nonne auris verba dijudicat? et fauces comedentis, saporem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'In antiquis est sapientia, et in multo tempore prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Apud ipsum est sapientia et fortitudo; ipse habet consilium et intelligentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Si destruxerit, nemo est qui ædificet; si incluserit hominem, nullus est qui aperiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Si continuerit aquas, omnia siccabuntur; et si emiserit eas, subvertent terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Apud ipsum est fortitudo et sapientia; ipse novit et decipientem, et eum qui decipitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Adducit consiliarios in stultum finem, et judices in stuporem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Balteum regum dissolvit, et præcingit fune renes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Ducit sacerdotes inglorios, et optimates supplantat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'commutans labium veracium, et doctrinam senum auferens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Effundit despectionem super principes, eos qui oppressi fuerant relevans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Qui revelat profunda de tenebris, et producit in lucem umbram mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Qui multiplicat gentes, et perdit eas, et subversas in integrum restituit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Qui immutat cor principum populi terræ, et decipit eos ut frustra incedant per invium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'palpabunt quasi in tenebris, et non in luce, et errare eos faciet quasi ebrios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Ecce omnia hæc vidit oculus meus, et audivit auris mea, et intellexi singula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Secundum scientiam vestram et ego novi: nec inferior vestri sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Sed tamen ad Omnipotentem loquar, et disputare cum Deo cupio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'prius vos ostendens fabricatores mendacii, et cultores perversorum dogmatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Atque utinam taceretis, ut putaremini esse sapientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Audite ergo correptionem meam, et judicium labiorum meorum attendite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Numquid Deus indiget vestro mendacio, ut pro illo loquamini dolos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'numquid faciem ejus accipitis, et pro Deo judicare nitimini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'aut placebit ei quem celare nihil potest? aut decipietur, ut homo, vestris fraudulentiis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ipse vos arguet, quoniam in abscondito faciem ejus accipitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Statim ut se commoverit, turbabit vos, et terror ejus irruet super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Memoria vestra comparabitur cineri, et redigentur in lutum cervices vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Tacete paulisper, ut loquar quodcumque mihi mens suggesserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Quare lacero carnes meas dentibus meis, et animam meam porto in manibus meis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Etiam si occiderit me, in ipso sperabo: verumtamen vias meas in conspectu ejus arguam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Et ipse erit salvator meus: non enim veniet in conspectu ejus omnis hypocrita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Audite sermonem meum, et ænigmata percipite auribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Si fuero judicatus, scio quod justus inveniar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Quis est qui judicetur mecum? veniat: quare tacens consumor?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Duo tantum ne facias mihi, et tunc a facie tua non abscondar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'manum tuam longe fac a me, et formido tua non me terreat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Voca me, et ego respondebo tibi: aut certe loquar, et tu responde mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Quantas habeo iniquitates et peccata? scelera mea et delicta ostende mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Cur faciem tuam abscondis, et arbitraris me inimicum tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Contra folium, quod vento rapitur, ostendis potentiam tuam, et stipulam siccam persequeris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 26, 'scribis enim contra me amaritudines, et consumere me vis peccatis adolescentiæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 27, 'Posuisti in nervo pedem meum, et observasti omnes semitas meas, et vestigia pedum meorum considerasti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 28, 'qui quasi putredo consumendus sum, et quasi vestimentum quod comeditur a tinea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Homo natus de muliere, brevi vivens tempore, repletur multis miseriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Qui quasi flos egreditur et conteritur, et fugit velut umbra, et numquam in eodem statu permanet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Et dignum ducis super hujuscemodi aperire oculos tuos, et adducere eum tecum in judicium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Quis potest facere mundum de immundo conceptum semine? nonne tu qui solus es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Breves dies hominis sunt: numerus mensium ejus apud te est: constituisti terminos ejus, qui præteriri non poterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Recede paululum ab eo, ut quiescat, donec optata veniat, sicut mercenarii, dies ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Lignum habet spem: si præcisum fuerit, rursum virescit, et rami ejus pullulant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Si senuerit in terra radix ejus, et in pulvere emortuus fuerit truncus illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'ad odorem aquæ germinabit, et faciet comam, quasi cum primum plantatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Homo vero cum mortuus fuerit, et nudatus, atque consumptus, ubi, quæso, est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Quomodo si recedant aquæ de mari, et fluvius vacuefactus arescat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'sic homo, cum dormierit, non resurget: donec atteratur cælum, non evigilabit, nec consurget de somno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Quis mihi hoc tribuat, ut in inferno protegas me, et abscondas me donec pertranseat furor tuus, et constituas mihi tempus in quo recorderis mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Putasne mortuus homo rursum vivat? cunctis diebus quibus nunc milito, expecto donec veniat immutatio mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Vocabis me, et ego respondebo tibi: operi manuum tuarum porriges dexteram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Tu quidem gressus meos dinumerasti: sed parce peccatis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Signasti quasi in sacculo delicta mea, sed curasti iniquitatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Mons cadens defluit, et saxum transfertur de loco suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'lapides excavant aquæ, et alluvione paulatim terra consumitur: et hominem ergo similiter perdes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Roborasti eum paululum, ut in perpetuum transiret: immutabis faciem ejus, et emittes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Sive nobiles fuerint filii ejus, sive ignobiles, non intelliget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Attamen caro ejus, dum vivet, dolebit, et anima illius super semetipso lugebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Respondens autem Eliphaz Themanites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Numquid sapiens respondebit quasi in ventum loquens, et implebit ardore stomachum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Arguis verbis eum qui non est æqualis tibi, et loqueris quod tibi non expedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Quantum in te est, evacuasti timorem, et tulisti preces coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Docuit enim iniquitas tua os tuum, et imitaris linguam blasphemantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Condemnabit te os tuum, et non ego: et labia tua respondebunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Numquid primus homo tu natus es, et ante colles formatus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'numquid consilium Dei audisti, et inferior te erit ejus sapientia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Quid nosti quod ignoremus? quid intelligis quod nesciamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Et senes et antiqui sunt in nobis, multo vetustiores quam patres tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Numquid grande est ut consoletur te Deus? sed verba tua prava hoc prohibent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Quid te elevat cor tuum, et quasi magna cogitans attonitos habes oculos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Quid tumet contra Deum spiritus tuus, ut proferas de ore tuo hujuscemodi sermones?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Quid est homo ut immaculatus sit, et ut justus appareat natus de muliere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Ecce inter sanctos ejus nemo immutabilis, et cæli non sunt mundi in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Quanto magis abominabilis et inutilis homo, qui bibit quasi aquam iniquitatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Ostendam tibi: audi me: quod vidi, narrabo tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Sapientes confitentur, et non abscondunt patres suos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'quibus solis data est terra, et non transivit alienus per eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Cunctis diebus suis impius superbit, et numerus annorum incertus est tyrannidis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Sonitus terroris semper in auribus illius: et cum pax sit, ille semper insidias suspicatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Non credit quod reverti possit de tenebris ad lucem, circumspectans undique gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Cum se moverit ad quærendum panem, novit quod paratus sit in manu ejus tenebrarum dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Terrebit eum tribulatio, et angustia vallabit eum, sicut regem qui præparatur ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Tetendit enim adversus Deum manum suam, et contra Omnipotentem roboratus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Cucurrit adversus eum erecto collo, et pingui cervice armatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Operuit faciem ejus crassitudo, et de lateribus ejus arvina dependet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Habitavit in civitatibus desolatis, et in domibus desertis, quæ in tumulos sunt redactæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Non ditabitur, nec perseverabit substantia ejus, nec mittet in terra radicem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Non recedet de tenebris: ramos ejus arefaciet flamma, et auferetur spiritu oris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Non credet, frustra errore deceptus, quod aliquo pretio redimendus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Antequam dies ejus impleantur peribit, et manus ejus arescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Lædetur quasi vinea in primo flore botrus ejus, et quasi oliva projiciens florem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 34, 'Congregatio enim hypocritæ sterilis, et ignis devorabit tabernacula eorum qui munera libenter accipiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 35, 'Concepit dolorem, et peperit iniquitatem, et uterus ejus præparat dolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Respondens autem Job, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Audivi frequenter talia: consolatores onerosi omnes vos estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Numquid habebunt finem verba ventosa? aut aliquid tibi molestum est, si loquaris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Poteram et ego similia vestri loqui, atque utinam esset anima vestra pro anima mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'consolarer et ego vos sermonibus, et moverem caput meum super vos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'roborarem vos ore meo, et moverem labia mea, quasi parcens vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Sed quid agam? Si locutus fuero, non quiescet dolor meus, et si tacuero, non recedet a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Nunc autem oppressit me dolor meus, et in nihilum redacti sunt omnes artus mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Rugæ meæ testimonium dicunt contra me, et suscitatur falsiloquus adversus faciem meam, contradicens mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Collegit furorem suum in me, et comminans mihi, infremuit contra me dentibus suis: hostis meus terribilibus oculis me intuitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Aperuerunt super me ora sua, et exprobrantes percusserunt maxillam meam: satiati sunt pœnis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Conclusit me Deus apud iniquum, et manibus impiorum me tradidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Ego ille quondam opulentus, repente contritus sum: tenuit cervicem meam, confregit me, et posuit me sibi quasi in signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Circumdedit me lanceis suis; convulneravit lumbos meos: non pepercit, et effudit in terra viscera mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Concidit me vulnere super vulnus: irruit in me quasi gigas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Saccum consui super cutem meam, et operui cinere carnem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Facies mea intumuit a fletu, et palpebræ meæ caligaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Hæc passus sum absque iniquitate manus meæ, cum haberem mundas ad Deum preces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Terra, ne operias sanguinem meum, neque inveniat in te locum latendi clamor meus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'ecce enim in cælo testis meus, et conscius meus in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Verbosi amici mei: ad Deum stillat oculus meus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'atque utinam sic judicaretur vir cum Deo, quomodo judicatur filius hominis cum collega suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Ecce enim breves anni transeunt, et semitam per quam non revertar ambulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Spiritus meus attenuabitur; dies mei breviabuntur: et solum mihi superest sepulchrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Non peccavi, et in amaritudinibus moratur oculus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Libera me, Domine, et pone me juxta te, et cujusvis manus pugnet contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Cor eorum longe fecisti a disciplina: propterea non exaltabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Prædam pollicetur sociis, et oculi filiorum ejus deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Posuit me quasi in proverbium vulgi, et exemplum sum coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Caligavit ab indignatione oculus meus, et membra mea quasi in nihilum redacta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Stupebunt justi super hoc, et innocens contra hypocritam suscitabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Et tenebit justus viam suam, et mundis manibus addet fortitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Igitur omnes vos convertimini, et venite, et non inveniam in vobis ullum sapientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Dies mei transierunt; cogitationes meæ dissipatæ sunt, torquentes cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Noctem verterunt in diem, et rursum post tenebras spero lucem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Si sustinuero, infernus domus mea est, et in tenebris stravi lectulum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Putredini dixi: Pater meus es; Mater mea, et soror mea, vermibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Ubi est ergo nunc præstolatio mea? et patientiam meam quis considerat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'In profundissimum infernum descendent omnia mea: putasne saltem ibi erit requies mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Respondens autem Baldad Suhites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Usque ad quem finem verba jactabitis? intelligite prius, et sic loquamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Quare reputati sumus ut jumenta, et sorduimus coram vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Qui perdis animam tuam in furore tuo, numquid propter te derelinquetur terra, et transferentur rupes de loco suo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Nonne lux impii extinguetur, nec splendebit flamma ignis ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Lux obtenebrescet in tabernaculo illius, et lucerna quæ super eum est extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Arctabuntur gressus virtutis ejus, et præcipitabit eum consilium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Immisit enim in rete pedes suos, et in maculis ejus ambulat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Tenebitur planta illius laqueo, et exardescet contra eum sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Abscondita est in terra pedica ejus, et decipula illius super semitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Undique terrebunt eum formidines, et involvent pedes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Attenuetur fame robur ejus, et inedia invadat costas illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Devoret pulchritudinem cutis ejus; consumat brachia illius primogenita mors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Avellatur de tabernaculo suo fiducia ejus, et calcet super eum, quasi rex, interitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Habitent in tabernaculo illius socii ejus qui non est; aspergatur in tabernaculo ejus sulphur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Deorsum radices ejus siccentur: sursum autem atteratur messis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Memoria illius pereat de terra, et non celebretur nomen ejus in plateis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Expellet eum de luce in tenebras, et de orbe transferet eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Non erit semen ejus, neque progenies in populo suo, nec ullæ reliquiæ in regionibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'In die ejus stupebunt novissimi, et primos invadet horror.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Hæc sunt ergo tabernacula iniqui, et iste locus ejus qui ignorat Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Respondens autem Job, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Usquequo affligitis animam meam, et atteritis me sermonibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'En decies confunditis me, et non erubescitis opprimentes me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Nempe etsi ignoravi, mecum erit ignorantia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'At vos contra me erigimini, et arguitis me opprobriis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Saltem nunc intelligite quia Deus non æquo judicio afflixerit me, et flagellis suis me cinxerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Ecce clamabo, vim patiens, et nemo audiet; vociferabor, et non est qui judicet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Semitam meam circumsepsit, et transire non possum: et in calle meo tenebras posuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Spoliavit me gloria mea, et abstulit coronam de capite meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Destruxit me undique, et pereo: et quasi evulsæ arbori abstulit spem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Iratus est contra me furor ejus, et sic me habuit quasi hostem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Simul venerunt latrones ejus, et fecerunt sibi viam per me, et obsederunt in gyro tabernaculum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Fratres meos longe fecit a me, et noti mei quasi alieni recesserunt a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Dereliquerunt me propinqui mei, et qui me noverant obliti sunt mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Inquilini domus meæ et ancillæ meæ sicut alienum habuerunt me, et quasi peregrinus fui in oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Servum meum vocavi, et non respondit: ore proprio deprecabar illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Halitum meum exhorruit uxor mea, et orabam filios uteri mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Stulti quoque despiciebant me: et cum ab eis recessissem, detrahebant mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Abominati sunt me quondam consiliarii mei, et quem maxime diligebam, aversatus est me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Pelli meæ, consumptis carnibus, adhæsit os meum, et derelicta sunt tantummodo labia circa dentes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Miseremini mei, miseremini mei saltem vos, amici mei, quia manus Domini tetigit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Quare persequimini me sicut Deus, et carnibus meis saturamini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Quis mihi tribuat ut scribantur sermones mei? quis mihi det ut exarentur in libro');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'stylo ferreo et plumbi lamina, vel celte sculpantur in silice?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Scio enim quod redemptor meus vivit, et in novissimo die de terra surrecturus sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'et rursum circumdabor pelle mea, et in carne mea videbo Deum meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'quem visurus sum ego ipse, et oculi mei conspecturi sunt, et non alius: reposita est hæc spes mea in sinu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Quare ergo nunc dicitis: Persequamur eum, et radicem verbi inveniamus contra eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Fugite ergo a facie gladii, quoniam ultor iniquitatum gladius est: et scitote esse judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Respondens autem Sophar Naamathites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Idcirco cogitationes meæ variæ succedunt sibi, et mens in diversa rapitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Doctrinam qua me arguis audiam, et spiritus intelligentiæ meæ respondebit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Hoc scio a principio, ex quo positus est homo super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'quod laus impiorum brevis sit, et gaudium hypocritæ ad instar puncti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Si ascenderit usque ad cælum superbia ejus, et caput ejus nubes tetigerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'quasi sterquilinium in fine perdetur, et qui eum viderant, dicent: Ubi est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Velut somnium avolans non invenietur: transiet sicut visio nocturna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Oculus qui eum viderat non videbit, neque ultra intuebitur eum locus suus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Filii ejus atterentur egestate, et manus illius reddent ei dolorem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Ossa ejus implebuntur vitiis adolescentiæ ejus, et cum eo in pulvere dormient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Cum enim dulce fuerit in ore ejus malum, abscondet illud sub lingua sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Parcet illi, et non derelinquet illud, et celabit in gutture suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Panis ejus in utero illius vertetur in fel aspidum intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Divitias quas devoravit evomet, et de ventre illius extrahet eas Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Caput aspidum suget, et occidet eum lingua viperæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, '(Non videat rivulos fluminis, torrentes mellis et butyri.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Luet quæ fecit omnia, nec tamen consumetur: juxta multitudinem adinventionum suarum, sic et sustinebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Quoniam confringens nudavit pauperes: domum rapuit, et non ædificavit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Nec est satiatus venter ejus: et cum habuerit quæ concupierat, possidere non poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Non remansit de cibo ejus, et propterea nihil permanebit de bonis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Cum satiatus fuerit, arctabitur: æstuabit, et omnis dolor irruet super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Utinam impleatur venter ejus, ut emittat in eum iram furoris sui, et pluat super illum bellum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Fugiet arma ferrea, et irruet in arcum æreum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Eductus, et egrediens de vagina sua, et fulgurans in amaritudine sua: vadent et venient super eum horribiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Omnes tenebræ absconditæ sunt in occultis ejus; devorabit eum ignis qui non succenditur: affligetur relictus in tabernaculo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Revelabunt cæli iniquitatem ejus, et terra consurget adversus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Apertum erit germen domus illius: detrahetur in die furoris Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Hæc est pars hominis impii a Deo, et hæreditas verborum ejus a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Respondens autem Job, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Audite, quæso, sermones meos, et agite pœnitentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Sustinete me, et ego loquar: et post mea, si videbitur, verba, ridete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Numquid contra hominem disputatio mea est, ut merito non debeam contristari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Attendite me et obstupescite, et superponite digitum ori vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Et ego, quando recordatus fuero, pertimesco, et concutit carnem meam tremor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Quare ergo impii vivunt, sublevati sunt, confortatique divitiis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Semen eorum permanet coram eis: propinquorum turba et nepotum in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Domus eorum securæ sunt et pacatæ, et non est virga Dei super illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Bos eorum concepit, et non abortivit: vacca peperit, et non est privata fœtu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Egrediuntur quasi greges parvuli eorum, et infantes eorum exultant lusibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Tenent tympanum et citharam, et gaudent ad sonitum organi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Ducunt in bonis dies suos, et in puncto ad inferna descendunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Qui dixerunt Deo: Recede a nobis, et scientiam viarum tuarum nolumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Quis est Omnipotens, ut serviamus ei? et quid nobis prodest si oraverimus illum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Verumtamen quia non sunt in manu eorum bona sua, consilium impiorum longe sit a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Quoties lucerna impiorum extinguetur, et superveniet eis inundatio, et dolores dividet furoris sui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Erunt sicut paleæ ante faciem venti, et sicut favilla quam turbo dispergit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Deus servabit filiis illius dolorem patris, et cum reddiderit, tunc sciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Videbunt oculi ejus interfectionem suam, et de furore Omnipotentis bibet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Quid enim ad eum pertinet de domo sua post se, et si numerus mensium ejus dimidietur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Numquid Deus docebit quispiam scientiam, qui excelsos judicat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Iste moritur robustus et sanus, dives et felix:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'viscera ejus plena sunt adipe, et medullis ossa illius irrigantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'alius vero moritur in amaritudine animæ absque ullis opibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'et tamen simul in pulvere dormient, et vermes operient eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Certe novi cogitationes vestras, et sententias contra me iniquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Dicitis enim: Ubi est domus principis? et ubi tabernacula impiorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Interrogate quemlibet de viatoribus, et hæc eadem illum intelligere cognoscetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'quia in diem perditionis servatur malus, et ad diem furoris ducetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Quis arguet coram eo viam ejus? et quæ fecit, quis reddet illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 32, 'Ipse ad sepulchra ducetur, et in congerie mortuorum vigilabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 33, 'Dulcis fuit glareis Cocyti, et post se omnem hominem trahet, et ante se innumerabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 34, 'Quomodo igitur consolamini me frustra, cum responsio vestra repugnare ostensa sit veritati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Respondens autem Eliphaz Themanites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Numquid Deo potest comparari homo, etiam cum perfectæ fuerit scientiæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Quid prodest Deo, si justus fueris? aut quid ei confers, si immaculata fuerit via tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Numquid timens arguet te, et veniet tecum in judicium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'et non propter malitiam tuam plurimam, et infinitas iniquitates tuas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Abstulisti enim pignus fratrum tuorum sine causa, et nudos spoliasti vestibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Aquam lasso non dedisti, et esurienti subtraxisti panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'In fortitudine brachii tui possidebas terram, et potentissimus obtinebas eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Viduas dimisisti vacuas, et lacertos pupillorum comminuisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Propterea circumdatus es laqueis, et conturbat te formido subita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Et putabas te tenebras non visurum, et impetu aquarum inundantium non oppressum iri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'an non cogitas quod Deus excelsior cælo sit, et super stellarum verticem sublimetur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Et dicis: Quid enim novit Deus? et quasi per caliginem judicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Nubes latibulum ejus, nec nostra considerat, et circa cardines cæli perambulat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Numquid semitam sæculorum custodire cupis, quam calcaverunt viri iniqui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'qui sublati sunt ante tempus suum, et fluvius subvertit fundamentum eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Qui dicebant Deo: Recede a nobis: et quasi nihil posset facere Omnipotens, æstimabant eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'cum ille implesset domos eorum bonis: quorum sententia procul sit a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Videbunt justi, et lætabuntur, et innocens subsannabit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'nonne succisa est erectio eorum? et reliquias eorum devoravit ignis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Acquiesce igitur ei, et habeto pacem, et per hæc habebis fructus optimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Suscipe ex ore illius legem, et pone sermones ejus in corde tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Si reversus fueris ad Omnipotentem, ædificaberis, et longe facies iniquitatem a tabernaculo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Dabit pro terra silicem, et pro silice torrentes aureos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Eritque Omnipotens contra hostes tuos, et argentum coacervabitur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Tunc super Omnipotentem deliciis afflues, et elevabis ad Deum faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Rogabis eum, et exaudiet te, et vota tua reddes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Decernes rem, et veniet tibi, et in viis tuis splendebit lumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Qui enim humiliatus fuerit, erit in gloria, et qui inclinaverit oculos, ipse salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 30, 'Salvabitur innocens: salvabitur autem in munditia manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Respondens autem Job, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Nunc quoque in amaritudine est sermo meus, et manus plagæ meæ aggravata est super gemitum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Quis mihi tribuat ut cognoscam et inveniam illum, et veniam usque ad solium ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ponam coram eo judicium, et os meum replebo increpationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'ut sciam verba quæ mihi respondeat, et intelligam quid loquatur mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Nolo multa fortitudine contendat mecum, nec magnitudinis suæ mole me premat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Proponat æquitatem contra me, et perveniat ad victoriam judicium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Si ad orientem iero, non apparet; si ad occidentem, non intelligam eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Si ad sinistram, quid agam? non apprehendam eum; si me vertam ad dexteram, non videbo illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ipse vero scit viam meam, et probavit me quasi aurum quod per ignem transit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Vestigia ejus secutus est pes meus: viam ejus custodivi, et non declinavi ex ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'A mandatis labiorum ejus non recessi, et in sinu meo abscondi verba oris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ipse enim solus est, et nemo avertere potest cogitationem ejus: et anima ejus quodcumque voluit, hoc fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Cum expleverit in me voluntatem suam, et alia multa similia præsto sunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Et idcirco a facie ejus turbatus sum, et considerans eum, timore sollicitor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Deus mollivit cor meum, et Omnipotens conturbavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Non enim perii propter imminentes tenebras, nec faciem meam operuit caligo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ab Omnipotente non sunt abscondita tempora: qui autem noverunt eum, ignorant dies illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Alii terminos transtulerunt; diripuerunt greges, et paverunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Asinum pupillorum abegerunt, et abstulerunt pro pignore bovem viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Subverterunt pauperum viam, et oppresserunt pariter mansuetos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Alii quasi onagri in deserto egrediuntur ad opus suum: vigilantes ad prædam, præparant panem liberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Agrum non suum demetunt, et vineam ejus, quem vi oppresserint, vindemiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Nudos dimittunt homines, indumenta tollentes, quibus non est operimentum in frigore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'quos imbres montium rigant, et non habentes velamen, amplexantur lapides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Vim fecerunt deprædantes pupillos, et vulgum pauperem spoliaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Nudis et incedentibus absque vestitu, et esurientibus tulerunt spicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Inter acervos eorum meridiati sunt, qui calcatis torcularibus sitiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'De civitatibus fecerunt viros gemere, et anima vulneratorum clamavit: et Deus inultum abire non patitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Ipsi fuerunt rebelles lumini: nescierunt vias ejus, nec reversi sunt per semitas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Mane primo consurgit homicida; interficit egenum et pauperem: per noctem vero erit quasi fur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Oculus adulteri observat caliginem, dicens: Non me videbit oculus: et operiet vultum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Perfodit in tenebris domos, sicut in die condixerant sibi, et ignoraverunt lucem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Si subito apparuerit aurora, arbitrantur umbram mortis: et sic in tenebris quasi in luce ambulant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Levis est super faciem aquæ: maledicta sit pars ejus in terra, nec ambulet per viam vinearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ad nimium calorem transeat ab aquis nivium, et usque ad inferos peccatum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Obliviscatur ejus misericordia; dulcedo illius vermes: non sit in recordatione, sed conteratur quasi lignum infructuosum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Pavit enim sterilem quæ non parit, et viduæ bene non fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Detraxit fortes in fortitudine sua, et cum steterit, non credet vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Dedit ei Deus locum pœnitentiæ, et ille abutitur eo in superbiam: oculi autem ejus sunt in viis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Elevati sunt ad modicum, et non subsistent: et humiliabuntur sicut omnia, et auferentur, et sicut summitates spicarum conterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Quod si non est ita, quis me potest arguere esse mentitum, et ponere ante Deum verba mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Respondens autem Baldad Suhites, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Potestas et terror apud eum est, qui facit concordiam in sublimibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Numquid est numerus militum ejus? et super quem non surget lumen illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Numquid justificari potest homo comparatus Deo? aut apparere mundus natus de muliere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Ecce luna etiam non splendet, et stellæ non sunt mundæ in conspectu ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'quanto magis homo putredo, et filius hominis vermis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Respondens autem Job dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Cujus adjutor es? numquid imbecillis? et sustentas brachium ejus qui non est fortis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Cui dedisti consilium? forsitan illi qui non habet sapientiam: et prudentiam tuam ostendisti plurimam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Quem docere voluisti? nonne eum qui fecit spiramentum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Ecce gigantes gemunt sub aquis, et qui habitant cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Nudus est infernus coram illo, et nullum est operimentum perditioni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Qui extendit aquilonem super vacuum, et appendit terram super nihilum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Qui ligat aquas in nubibus suis, ut non erumpant pariter deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Qui tenet vultum solii sui, et expandit super illud nebulam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Terminum circumdedit aquis, usque dum finiantur lux et tenebræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Columnæ cæli contremiscunt, et pavent ad nutum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'In fortitudine illius repente maria congregata sunt, et prudentia ejus percussit superbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Spiritus ejus ornavit cælos, et obstetricante manu ejus, eductus est coluber tortuosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Ecce hæc ex parte dicta sunt viarum ejus: et cum vix parvam stillam sermonis ejus audierimus, quis poterit tonitruum magnitudinis illius intueri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Addidit quoque Job, assumens parabolam suam, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Vivit Deus, qui abstulit judicium meum, et Omnipotens, qui ad amaritudinem adduxit animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Quia donec superest halitus in me, et spiritus Dei in naribus meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'non loquentur labia mea iniquitatem, nec lingua mea meditabitur mendacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Absit a me ut justos vos esse judicem: donec deficiam, non recedam ab innocentia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Justificationem meam, quam cœpi tenere, non deseram: neque enim reprehendit me cor meum in omni vita mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Sit ut impius, inimicus meus, et adversarius meus quasi iniquus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Quæ est enim spes hypocritæ, si avare rapiat, et non liberet Deus animam ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Numquid Deus audiet clamorem ejus, cum venerit super eum angustia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'aut poterit in Omnipotente delectari, et invocare Deum omni tempore?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Docebo vos per manum Dei quæ Omnipotens habeat, nec abscondam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Ecce vos omnes nostis: et quid sine causa vana loquimini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Hæc est pars hominis impii apud Deum, et hæreditas violentorum, quam ob Omnipotente suscipient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Si multiplicati fuerint filii ejus, in gladio erunt, et nepotes ejus non saturabuntur pane:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'qui reliqui fuerint ex eo sepelientur in interitu, et viduæ illius non plorabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Si comportaverit quasi terram argentum, et sicut lutum præparaverit vestimenta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'præparabit quidem, sed justus vestietur illis, et argentum innocens dividet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, '\'dificavit sicut tinea domum suam, et sicut custos fecit umbraculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Dives, cum dormierit, nihil secum auferet: aperiet oculos suos, et nihil inveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Apprehendet eum quasi aqua inopia: nocte opprimet eum tempestas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Tollet eum ventus urens, et auferet, et velut turbo rapiet eum de loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Et mittet super eum, et non parcet: de manu ejus fugiens fugiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Stringet super eum manus suas, et sibilabit super illum, intuens locum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Habet argentum venarum suarum principia, et auro locus est in quo conflatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Ferrum de terra tollitur, et lapis solutus calore in æs vertitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Tempus posuit tenebris, et universorum finem ipse considerat: lapidem quoque caliginis et umbram mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Dividit torrens a populo peregrinante eos quos oblitus est pes egentis hominis, et invios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Terra de qua oriebatur panis, in loco suo igni subversa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Locus sapphiri lapides ejus, et glebæ illius aurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Semitam ignoravit avis, nec intuitus est eam oculus vulturis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Non calcaverunt eam filii institorum, nec pertransivit per eam leæna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Ad silicem extendit manum suam: subvertit a radicibus montes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'In petris rivos excidit, et omne pretiosum vidit oculus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Profunda quoque fluviorum scrutatus est, et abscondita in lucem produxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Sapientia vero ubi invenitur? et quis est locus intelligentiæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Nescit homo pretium ejus, nec invenitur in terra suaviter viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Abyssus dicit: Non est in me, et mare loquitur: Non est mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Non dabitur aurum obrizum pro ea, nec appendetur argentum in commutatione ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Non conferetur tinctis Indiæ coloribus, nec lapidi sardonycho pretiosissimo vel sapphiro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Non adæquabitur ei aurum vel vitrum, nec commutabuntur pro ea vasa auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Excelsa et eminentia non memorabuntur comparatione ejus: trahitur autem sapientia de occultis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Non adæquabitur ei topazius de \'thiopia, nec tincturæ mundissimæ componetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Unde ergo sapientia venit? et quis est locus intelligentiæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Abscondita est ab oculis omnium viventium: volucres quoque cæli latet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Perditio et mors dixerunt: Auribus nostris audivimus famam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Deus intelligit viam ejus, et ipse novit locum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Ipse enim fines mundi intuetur, et omnia quæ sub cælo sunt respicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Qui fecit ventis pondus, et aquas appendit in mensura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Quando ponebat pluviis legem, et viam procellis sonantibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'tunc vidit illam et enarravit, et præparavit, et investigavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Et dixit homini: Ecce timor Domini, ipsa est sapientia; et recedere a malo, intelligentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Addidit quoque Job, assumens parabolam suam, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quis mihi tribuat ut sim juxta menses pristinos, secundum dies quibus Deus custodiebat me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Quando splendebat lucerna ejus super caput meum, et ad lumen ejus ambulabam in tenebris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'sicut fui in diebus adolescentiæ meæ, quando secreto Deus erat in tabernaculo meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'quando erat Omnipotens mecum, et in circuitu meo pueri mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'quando lavabam pedes meos butyro, et petra fundebat mihi rivos olei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'quando procedebam ad portam civitatis, et in platea parabant cathedram mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Videbant me juvenes, et abscondebantur: et senes assurgentes stabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Principes cessabant loqui, et digitum superponebant ori suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Vocem suam cohibebant duces, et lingua eorum gutturi suo adhærebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Auris audiens beatificabat me, et oculus videns testimonium reddebat mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'eo quod liberassem pauperem vociferantem, et pupillum cui non esset adjutor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Benedictio perituri super me veniebat, et cor viduæ consolatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Justitia indutus sum, et vestivi me, sicut vestimento et diademate, judicio meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Oculus fui cæco, et pes claudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Pater eram pauperum, et causam quam nesciebam diligentissime investigabam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Conterebam molas iniqui, et de dentibus illius auferebam prædam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Dicebamque: In nidulo meo moriar, et sicut palma multiplicabo dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Radix mea aperta est secus aquas, et ros morabitur in messione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Gloria mea semper innovabitur, et arcus meus in manu mea instaurabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Qui me audiebant, expectabant sententiam, et intenti tacebant ad consilium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Verbis meis addere nihil audebant, et super illos stillabat eloquium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Expectabant me sicut pluviam, et os suum aperiebant quasi ad imbrem serotinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Siquando ridebam ad eos, non credebant: et lux vultus mei non cadebat in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Si voluissem ire ad eos, sedebam primus: cumque sederem quasi rex, circumstante exercitu, eram tamen mœrentium consolator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Nunc autem derident me juniores tempore, quorum non dignabar patres ponere cum canibus gregis mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'quorum virtus manuum mihi erat pro nihilo, et vita ipsa putabantur indigni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'egestate et fame steriles, qui rodebant in solitudine, squallentes calamitate et miseria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Et mandebant herbas, et arborum cortices, et radix juniperorum erat cibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'qui de convallibus ista rapientes, cum singula reperissent, ad ea cum clamore currebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'In desertis habitabant torrentium, et in cavernis terræ, vel super glaream:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'qui inter hujuscemodi lætabantur, et esse sub sentibus delicias computabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'filii stultorum et ignobilium, et in terra penitus non parentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Nunc in eorum canticum versus sum, et factus sum eis in proverbium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Abominantur me, et longe fugiunt a me, et faciem meam conspuere non verentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Pharetram enim suam aperuit, et afflixit me, et frenum posuit in os meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Ad dexteram orientis calamitates meæ illico surrexerunt: pedes meos subverterunt, et oppresserunt quasi fluctibus semitis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Dissipaverunt itinera mea; insidiati sunt mihi, et prævaluerunt: et non fuit qui ferret auxilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Quasi rupto muro, et aperta janua, irruerunt super me, et ad meas miserias devoluti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Redactus sum in nihilum: abstulisti quasi ventus desiderium meum, et velut nubes pertransiit salus mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Nunc autem in memetipso marcescit anima mea, et possident me dies afflictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Nocte os meum perforatur doloribus, et qui me comedunt, non dormiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'In multitudine eorum consumitur vestimentum meum, et quasi capitio tunicæ succinxerunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Comparatus sum luto, et assimilatus sum favillæ et cineri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Clamo ad te, et non exaudis me: sto, et non respicis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Mutatus es mihi in crudelem, et in duritia manus tuæ adversaris mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Elevasti me, et quasi super ventum ponens; elisisti me valide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Scio quia morti trades me, ubi constituta est domus omni viventi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Verumtamen non ad consumptionem eorum emittis manum tuam: et si corruerint, ipse salvabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Flebam quondam super eo qui afflictus erat, et compatiebatur anima mea pauperi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Expectabam bona, et venerunt mihi mala: præstolabar lucem, et eruperunt tenebræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Interiora mea efferbuerunt absque ulla requie: prævenerunt me dies afflictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Mœrens incedebam sine furore; consurgens, in turba clamabam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Frater fui draconum, et socius struthionum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Cutis mea denigrata est super me, et ossa mea aruerunt præ caumate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Versa est in luctum cithara mea, et organum meum in vocem flentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Pepigi fœdus cum oculis meis, ut ne cogitarem quidem de virgine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Quam enim partem haberet in me Deus desuper, et hæreditatem Omnipotens de excelsis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Numquid non perditio est iniquo, et alienatio operantibus injustitiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Nonne ipse considerat vias meas, et cunctos gressus meos dinumerat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Si ambulavi in vanitate, et festinavit in dolo pes meus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'appendat me in statera justa, et sciat Deus simplicitatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Si declinavit gressus meus de via, et si secutum est oculos meos cor meum, et si manibus meis adhæsit macula,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'seram, et alius comedat, et progenies mea eradicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Si deceptum est cor meum super muliere, et si ad ostium amici mei insidiatus sum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'scortum alterius sit uxor mea, et super illam incurventur alii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Hoc enim nefas est, et iniquitas maxima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ignis est usque ad perditionem devorans, et omnia eradicans genimina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Si contempsi subire judicium cum servo meo et ancilla mea, cum disceptarent adversum me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'quid enim faciam cum surrexerit ad judicandum Deus? et cum quæsierit, quid respondebo illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Numquid non in utero fecit me, qui et illum operatus est, et formavit me in vulva unus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Si negavi quod volebant pauperibus, et oculos viduæ expectare feci;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'si comedi buccellam meam solus, et non comedit pupillus ex ea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, '(quia ab infantia mea crevit mecum miseratio, et de utero matris meæ egressa est mecum);');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'si despexi pereuntem, eo quod non habuerit indumentum, et absque operimento pauperem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'si non benedixerunt mihi latera ejus, et de velleribus ovium mearum calefactus est;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'si levavi super pupillum manum meam, etiam cum viderem me in porta superiorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'humerus meus a junctura sua cadat, et brachium meum cum suis ossibus confringatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Semper enim quasi tumentes super me fluctus timui Deum, et pondus ejus ferre non potui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Si putavi aurum robur meum, et obrizo dixi: Fiducia mea;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'si lætatus sum super multis divitiis meis, et quia plurima reperit manus mea;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'si vidi solem cum fulgeret, et lunam incedentem clare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'et lætatum est in abscondito cor meum, et osculatus sum manum meam ore meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'quæ est iniquitas maxima, et negatio contra Deum altissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Si gavisus sum ad ruinam ejus qui me oderat, et exsultavi quod invenisset eum malum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'non enim dedi ad peccandum guttur meum, ut expeterem maledicens animam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Si non dixerunt viri tabernaculi mei: Quis det de carnibus ejus, ut saturemur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 32, 'foris non mansit peregrinus: ostium meum viatori patuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 33, 'Si abscondi quasi homo peccatum meum, et celavi in sinu meo iniquitatem meam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 34, 'si expavi ad multitudinem nimiam, et despectio propinquorum terruit me: et non magis tacui, nec egressus sum ostium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 35, 'Quis mihi tribuat auditorem, ut desiderium meum audiat Omnipotens, et librum scribat ipse qui judicat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 36, 'ut in humero meo portem illum, et circumdem illum quasi coronam mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 37, 'Per singulos gradus meos pronuntiabo illum, et quasi principi offeram eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 38, 'Si adversum me terra mea clamat, et cum ipsa sulci ejus deflent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 39, 'si fructus ejus comedi absque pecunia, et animam agricolarum ejus afflixi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 40, 'pro frumento oriatur mihi tribulus, et pro hordeo spina. Finita sunt verba Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 1, 'Omiserunt autem tres viri isti respondere Job, eo quod justus sibi videretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 2, 'Et iratus indignatusque est Eliu filius Barachel Buzites, de cognatione Ram: iratus est autem adversum Job, eo quod justum se esse diceret coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 3, 'Porro adversum amicos ejus indignatus est, eo quod non invenissent responsionem rationabilem, sed tantummodo condemnassent Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 4, 'Igitur Eliu expectavit Job loquentem, eo quod seniores essent qui loquebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 5, 'Cum autem vidisset quod tres respondere non potuissent, iratus est vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 6, 'Respondensque Eliu filius Barachel Buzites, dixit: Junior sum tempore, vos autem antiquiores: idcirco, demisso capite, veritus sum vobis indicare meam sententiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 7, 'Sperabam enim quod ætas prolixior loqueretur, et annorum multitudo doceret sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 8, 'Sed, ut video, spiritus est in hominibus, et inspiratio Omnipotentis dat intelligentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 9, 'Non sunt longævi sapientes, nec senes intelligunt judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 10, 'Ideo dicam: Audite me: ostendam vobis etiam ego meam sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 11, 'Expectavi enim sermones vestros; audivi prudentiam vestram, donec disceptaremini sermonibus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 12, 'et donec putabam vos aliquid dicere, considerabam: sed, ut video, non est qui possit arguere Job, et respondere ex vobis sermonibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 13, 'Ne forte dicatis: Invenimus sapientiam: Deus projecit eum, non homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 14, 'Nihil locutus est mihi: et ego non secundum sermones vestros respondebo illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 15, 'Extimuerunt, nec responderunt ultra, abstuleruntque a se eloquia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 16, 'Quoniam igitur expectavi, et non sunt locuti: steterunt, nec ultra responderunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 17, 'respondebo et ego partem meam, et ostendam scientiam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 18, 'Plenus sum enim sermonibus, et coarctat me spiritus uteri mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 19, 'En venter meus quasi mustum absque spiraculo, quod lagunculas novas disrumpit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 20, 'Loquar, et respirabo paululum: aperiam labia mea, et respondebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 21, 'Non accipiam personam viri, et Deum homini non æquabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 32, 22, 'Nescio enim quamdiu subsistam, et si post modicum tollat me factor meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 1, 'Audi igitur, Job, eloquia mea, et omnes sermones meos ausculta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 2, 'Ecce aperui os meum: loquatur lingua mea in faucibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 3, 'Simplici corde meo sermones mei, et sententiam puram labia mea loquentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 4, 'Spiritus Dei fecit me, et spiraculum Omnipotentis vivificavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 5, 'Si potes, responde mihi, et adversus faciem meam consiste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 6, 'Ecce, et me sicut et te fecit Deus, et de eodem luto ego quoque formatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 7, 'Verumtamen miraculum meum non te terreat, et eloquentia mea non sit tibi gravis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 8, 'Dixisti ergo in auribus meis, et vocem verborum tuorum audivi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 9, 'Mundus sum ego, et absque delicto: immaculatus, et non est iniquitas in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 10, 'Quia querelas in me reperit, ideo arbitratus est me inimicum sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 11, 'Posuit in nervo pedes meos; custodivit omnes semitas meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 12, 'Hoc est ergo in quo non es justificatus: respondebo tibi, quia major sit Deus homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 13, 'Adversus eum contendis, quod non ad omnia verba responderit tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 14, 'Semel loquitur Deus, et secundo idipsum non repetit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 15, 'Per somnium, in visione nocturna, quando irruit sopor super homines, et dormiunt in lectulo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 16, 'tunc aperit aures virorum, et erudiens eos instruit disciplina,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 17, 'ut avertat hominem ab his quæ facit, et liberet eum de superbia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 18, 'eruens animam ejus a corruptione, et vitam illius ut non transeat in gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 19, 'Increpat quoque per dolorem in lectulo, et omnia ossa ejus marcescere facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 20, 'Abominabilis ei fit in vita sua panis, et animæ illius cibus ante desiderabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 21, 'Tabescet caro ejus, et ossa, quæ tecta fuerant, nudabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 22, 'Appropinquavit corruptioni anima ejus, et vita illius mortiferis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 23, 'Si fuerit pro eo angelus loquens, unus de millibus, ut annuntiet hominis æquitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 24, 'miserebitur ejus, et dicet: Libera eum, ut non descendat in corruptionem: inveni in quo ei propitier.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 25, 'Consumpta est caro ejus a suppliciis: revertatur ad dies adolescentiæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 26, 'Deprecabitur Deum, et placabilis ei erit: et videbit faciem ejus in jubilo, et reddet homini justitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 27, 'Respiciet homines, et dicet: Peccavi, et vere deliqui, et ut eram dignus, non recepi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 28, 'Liberavit animam suam, ne pergeret in interitum, sed vivens lucem videret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 29, 'Ecce hæc omnia operatur Deus tribus vicibus per singulos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 30, 'ut revocet animas eorum a corruptione, et illuminet luce viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 31, 'Attende, Job, et audi me: et tace, dum ego loquor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 32, 'Si autem habes quod loquaris, responde mihi: loquere, volo enim te apparere justum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 33, 33, 'Quod si non habes, audi me: tace, et docebo te sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 1, 'Pronuntians itaque Eliu, etiam hæc locutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 2, 'Audite, sapientes, verba mea: et eruditi, auscultate me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 3, 'Auris enim verba probat, et guttur escas gustu dijudicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 4, 'Judicium eligamus nobis, et inter nos videamus quid sit melius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 5, 'Quia dixit Job: Justus sum, et Deus subvertit judicium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 6, 'In judicando enim me mendacium est: violenta sagitta mea absque ullo peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 7, 'Quis est vir ut est Job, qui bibit subsannationem quasi aquam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 8, 'qui graditur cum operantibus iniquitatem, et ambulat cum viris impiis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 9, 'Dixit enim: Non placebit vir Deo, etiam si cucurrerit cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 10, 'Ideo, viri cordati, audite me: absit a Deo impietas, et ab Omnipotente iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 11, 'Opus enim hominis reddet ei, et juxta vias singulorum restituet eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 12, 'Vere enim Deus non condemnabit frustra, nec Omnipotens subvertet judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 13, 'Quem constituit alium super terram? aut quem posuit super orbem quem fabricatus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 14, 'Si direxerit ad eum cor suum, spiritum illius et flatum ad se trahet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 15, 'Deficiet omnis caro simul, et homo in cinerem revertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 16, 'Si habes ergo intellectum, audi quod dicitur, et ausculta vocem eloquii mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 17, 'numquid qui non amat judicium sanari potest? et quomodo tu eum qui justus est in tantum condemnas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 18, 'Qui dicit regi: Apostata; qui vocat duces impios;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 19, 'qui non accipit personas principum, nec cognovit tyrannum cum disceptaret contra pauperem: opus enim manuum ejus sunt universi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 20, 'Subito morientur, et in media nocte turbabuntur populi: et pertransibunt, et auferent violentum absque manu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 21, 'Oculi enim ejus super vias hominum, et omnes gressus eorum considerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 22, 'Non sunt tenebræ, et non est umbra mortis, ut abscondantur ibi qui operantur iniquitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 23, 'neque enim ultra in hominis potestate est, ut veniat ad Deum in judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 24, 'Conteret multos, et innumerabiles, et stare faciet alios pro eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 25, 'Novit enim opera eorum, et idcirco inducet noctem, et conterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 26, 'Quasi impios percussit eos in loco videntium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 27, 'qui quasi de industria recesserunt ab eo, et omnes vias ejus intelligere noluerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 28, 'ut pervenire facerent ad eum clamorem egeni, et audiret vocem pauperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 29, 'Ipso enim concedente pacem, quis est qui condemnet? ex quo absconderit vultum, quis est qui contempletur eum, et super gentes, et super omnes homines?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 30, 'Qui regnare facit hominem hypocritam propter peccata populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 31, 'Quia ergo ego locutus sum ad Deum, te quoque non prohibebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 32, 'Si erravi, tu doce me; si iniquitatem locutus sum, ultra non addam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 33, 'Numquid a te Deus expetit eam, quia displicuit tibi? tu enim cœpisti loqui, et non ego: quod si quid nosti melius, loquere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 34, 'Viri intelligentes loquantur mihi, et vir sapiens audiat me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 35, 'Job autem stulte locutus est, et verba illius non sonant disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 36, 'Pater mi, probetur Job usque ad finem: ne desinas ab homine iniquitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 34, 37, 'quia addit super peccata sua blasphemiam, inter nos interim constringatur: et tunc ad judicium provocet sermonibus suis Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 1, 'Igitur Eliu hæc rursum locutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 2, 'Numquid æqua tibi videtur tua cogitatio, ut diceres: Justior sum Deo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 3, 'Dixisti enim: Non tibi placet quod rectum est: vel quid tibi proderit, si ego peccavero?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 4, 'Itaque ego respondebo sermonibus tuis, et amicis tuis tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 5, 'Suspice cælum, et intuere: et contemplare æthera quod altior te sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 6, 'Si peccaveris, quid ei nocebis? et si multiplicatæ fuerint iniquitates tuæ, quid facies contra eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 7, 'Porro si juste egeris, quid donabis ei? aut quid de manu tua accipiet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 8, 'Homini qui similis tui est, nocebit impietas tua: et filium hominis adjuvabit justitia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 9, 'Propter multitudinem calumniatorum clamabunt, et ejulabunt propter vim brachii tyrannorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 10, 'Et non dixit: Ubi est Deus qui fecit me, qui dedit carmina in nocte;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 11, 'qui docet nos super jumenta terræ, et super volucres cæli erudit nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 12, 'Ibi clamabunt, et non exaudiet, propter superbiam malorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 13, 'Non ergo frustra audiet Deus, et Omnipotens causas singulorum intuebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 14, 'Etiam cum dixeris: Non considerat: judicare coram illo, et expecta eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 15, 'Nunc enim non infert furorem suum, nec ulciscitur scelus valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 35, 16, 'Ergo Job frustra aperit os suum, et absque scientia verba multiplicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 1, 'Addens quoque Eliu, hæc locutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 2, 'Sustine me paululum, et indicabo tibi: adhuc enim habeo quod pro Deo loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 3, 'Repetam scientiam meam a principio, et operatorem meum probabo justum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 4, 'Vere enim absque mendacio sermones mei, et perfecta scientia probabitur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 5, 'Deus potentes non abjicit, cum et ipse sit potens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 6, 'sed non salvat impios, et judicium pauperibus tribuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 7, 'Non auferet a justo oculos suos: et reges in solio collocat in perpetuum, et illi eriguntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 8, 'Et si fuerint in catenis, et vinciantur funibus paupertatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 9, 'indicabit eis opera eorum, et scelera eorum, quia violenti fuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 10, 'Revelabit quoque aurem eorum, ut corripiat: et loquetur, ut revertantur ab iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 11, 'Si audierint et observaverint, complebunt dies suos in bono, et annos suos in gloria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 12, 'si autem non audierint, transibunt per gladium, et consumentur in stultitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 13, 'Simulatores et callidi provocant iram Dei, neque clamabunt cum vincti fuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 14, 'Morietur in tempestate anima eorum, et vita eorum inter effeminatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 15, 'Eripiet de angustia sua pauperem, et revelabit in tribulatione aurem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 16, 'Igitur salvabit te de ore angusto latissime, et non habente fundamentum subter se: requies autem mensæ tuæ erit plena pinguedine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 17, 'Causa tua quasi impii judicata est: causam judiciumque recipies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 18, 'Non te ergo superet ira ut aliquem opprimas: nec multitudo donorum inclinet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 19, 'Depone magnitudinem tuam absque tribulatione, et omnes robustos fortitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 20, 'Ne protrahas noctem, ut ascendant populi pro eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 21, 'Cave ne declines ad iniquitatem: hanc enim cœpisti sequi post miseriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 22, 'Ecce Deus excelsus in fortitudine sua, et nullus ei similis in legislatoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 23, 'Quis poterit scrutari vias ejus? aut quis potest ei dicere: Operatus es iniquitatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 24, 'Memento quod ignores opus ejus, de quo cecinerunt viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 25, 'Omnes homines vident eum: unusquisque intuetur procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 26, 'Ecce Deus magnus vincens scientiam nostram: numerus annorum ejus inæstimabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 27, 'Qui aufert stillas pluviæ, et effundit imbres ad instar gurgitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 28, 'qui de nubibus fluunt quæ prætexunt cuncta desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 29, 'Si voluerit extendere nubes quasi tentorium suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 30, 'et fulgurare lumine suo desuper, cardines quoque maris operiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 31, 'Per hæc enim judicat populos, et dat escas multis mortalibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 32, 'In manibus abscondit lucem, et præcepit ei ut rursus adveniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 36, 33, 'Annuntiat de ea amico suo, quod possessio ejus sit, et ad eam possit ascendere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 1, 'Super hoc expavit cor meum, et emotum est de loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 2, 'Audite auditionem in terrore vocis ejus, et sonum de ore illius procedentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 3, 'Subter omnes cælos ipse considerat, et lumen illius super terminos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 4, 'Post eum rugiet sonitus; tonabit voce magnitudinis suæ: et non investigabitur, cum audita fuerit vox ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 5, 'Tonabit Deus in voce sua mirabiliter, qui facit magna et inscrutabilia;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 6, 'qui præcipit nivi ut descendat in terram, et hiemis pluviis, et imbri fortitudinis suæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 7, 'qui in manu omnium hominum signat, ut noverint singuli opera sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 8, 'Ingredietur bestia latibulum, et in antro suo morabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 9, 'Ab interioribus egredietur tempestas, et ab Arcturo frigus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 10, 'Flante Deo, concrescit gelu, et rursum latissimæ funduntur aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 11, 'Frumentum desiderat nubes, et nubes spargunt lumen suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 12, 'Quæ lustrant per circuitum, quocumque eas voluntas gubernantis duxerit, ad omne quod præceperit illis super faciem orbis terrarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 13, 'sive in una tribu, sive in terra sua, sive in quocumque loco misericordiæ suæ eas jusserit inveniri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 14, 'Ausculta hæc, Job: sta, et considera mirabilia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 15, 'Numquid scis quando præceperit Deus pluviis, ut ostenderent lucem nubium ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 16, 'Numquid nosti semitas nubium magnas, et perfectas scientias?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 17, 'Nonne vestimenta tua calida sunt, cum perflata fuerit terra austro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 18, 'Tu forsitan cum eo fabricatus es cælos, qui solidissimi quasi ære fusi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 19, 'Ostende nobis quid dicamus illi: nos quippe involvimur tenebris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 20, 'Quis narrabit ei quæ loquor? etiam si locutus fuerit homo, devorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 21, 'At nunc non vident lucem: subito aër cogetur in nubes, et ventus transiens fugabit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 22, 'Ab aquilone aurum venit, et ad Deum formidolosa laudatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 23, 'Digne eum invenire non possumus: magnus fortitudine, et judicio, et justitia: et enarrari non potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 37, 24, 'Ideo timebunt eum viri, et non audebunt contemplari omnes qui sibi videntur esse sapientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 1, 'Respondens autem Dominus Job de turbine, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 2, 'Quis est iste involvens sententias sermonibus imperitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 3, 'Accinge sicut vir lumbos tuos: interrogabo te, et responde mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 4, 'Ubi eras quando ponebam fundamenta terræ? indica mihi, si habes intelligentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 5, 'Quis posuit mensuras ejus, si nosti? vel quis tetendit super eam lineam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 6, 'Super quo bases illius solidatæ sunt? aut quis demisit lapidem angularem ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 7, 'cum me laudarent simul astra matutina, et jubilarent omnes filii Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 8, 'Quis conclusit ostiis mare, quando erumpebat quasi de vulva procedens;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 9, 'cum ponerem nubem vestimentum ejus, et caligine illud quasi pannis infantiæ obvolverem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 10, 'Circumdedi illud terminis meis, et posui vectem et ostia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 11, 'et dixi: Usque huc venies, et non procedes amplius, et hic confringes tumentes fluctus tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 12, 'Numquid post ortum tuum præcepisti diluculo, et ostendisti auroræ locum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 13, 'Et tenuisti concutiens extrema terræ, et excussisti impios ex ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 14, 'Restituetur ut lutum signaculum, et stabit sicut vestimentum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 15, 'auferetur ab impiis lux sua, et brachium excelsum confringetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 16, 'Numquid ingressus es profunda maris, et in novissimis abyssi deambulasti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 17, 'Numquid apertæ sunt tibi portæ mortis, et ostia tenebrosa vidisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 18, 'Numquid considerasti latitudinem terræ? indica mihi, si nosti, omnia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 19, 'in qua via lux habitet, et tenebrarum quis locus sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 20, 'ut ducas unumquodque ad terminos suos, et intelligas semitas domus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 21, 'Sciebas tunc quod nasciturus esses, et numerum dierum tuorum noveras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 22, 'Numquid ingressus es thesauros nivis, aut thesauros grandinis aspexisti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 23, 'quæ præparavi in tempus hostis, in diem pugnæ et belli?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 24, 'Per quam viam spargitur lux, dividitur æstus super terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 25, 'Quis dedit vehementissimo imbri cursum, et viam sonantis tonitrui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 26, 'ut plueret super terram absque homine in deserto, ubi nullus mortalium commoratur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 27, 'ut impleret inviam et desolatam, et produceret herbas virentes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 28, 'Quis est pluviæ pater? vel quis genuit stillas roris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 29, 'De cujus utero egressa est glacies? et gelu de cælo quis genuit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 30, 'In similitudinem lapidis aquæ durantur, et superficies abyssi constringitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 31, 'Numquid conjungere valebis micantes stellas Pleiadas, aut gyrum Arcturi poteris dissipare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 32, 'Numquid producis luciferum in tempore suo, et vesperum super filios terræ consurgere facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 33, 'Numquid nosti ordinem cæli, et pones rationem ejus in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 34, 'Numquid elevabis in nebula vocem tuam, et impetus aquarum operiet te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 35, 'Numquid mittes fulgura, et ibunt, et revertentia dicent tibi: Adsumus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 36, 'Quis posuit in visceribus hominis sapientiam? vel quis dedit gallo intelligentiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 37, 'Quis enarrabit cælorum rationem? et concentum cæli quis dormire faciet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 38, 'Quando fundebatur pulvis in terra, et glebæ compingebantur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 39, 'Numquid capies leænæ prædam, et animam catulorum ejus implebis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 40, 'quando cubant in antris, et in specubus insidiantur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 38, 41, 'Quis præparat corvo escam suam, quando pulli ejus clamant ad Deum, vagantes, eo quod non habeant cibos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 1, 'Numquid nosti tempus partus ibicum in petris, vel parturientes cervas observasti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 2, 'Dinumerasti menses conceptus earum, et scisti tempus partus earum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 3, 'Incurvantur ad fœtum, et pariunt, et rugitus emittunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 4, 'Separantur filii earum, et pergunt ad pastum: egrediuntur, et non revertuntur ad eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 5, 'Quis dimisit onagrum liberum, et vincula ejus quis solvit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 6, 'cui dedi in solitudine domum, et tabernacula ejus in terra salsuginis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 7, 'Contemnit multitudinem civitatis: clamorem exactoris non audit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 8, 'Circumspicit montes pascuæ suæ, et virentia quæque perquirit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 9, 'Numquid volet rhinoceros servire tibi, aut morabitur ad præsepe tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 10, 'Numquid alligabis rhinocerota ad arandum loro tuo, aut confringet glebas vallium post te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 11, 'Numquid fiduciam habebis in magna fortitudine ejus, et derelinques ei labores tuos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 12, 'Numquid credes illi quod sementem reddat tibi, et aream tuam congreget?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 13, 'Penna struthionis similis est pennis herodii et accipitris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 14, 'Quando derelinquit ova sua in terra, tu forsitan in pulvere calefacies ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 15, 'Obliviscitur quod pes conculcet ea, aut bestia agri conterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 16, 'Duratur ad filios suos, quasi non sint sui: frustra laboravit, nullo timore cogente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 17, 'Privavit enim eam Deus sapientia, nec dedit illi intelligentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 18, 'Cum tempus fuerit, in altum alas erigit: deridet equum et ascensorem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 19, 'Numquid præbebis equo fortitudinem, aut circumdabis collo ejus hinnitum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 20, 'Numquid suscitabis eum quasi locustas? gloria narium ejus terror.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 21, 'Terram ungula fodit; exultat audacter: in occursum pergit armatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 22, 'Contemnit pavorem, nec cedit gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 23, 'Super ipsum sonabit pharetra; vibrabit hasta et clypeus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 24, 'fervens et fremens sorbet terram, nec reputat tubæ sonare clangorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 25, 'Ubi audierit buccinam, dicit: Vah! procul odoratur bellum: exhortationem ducum, et ululatum exercitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 26, 'Numquid per sapientiam tuam plumescit accipiter, expandens alas suas ad austrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 27, 'Numquid ad præceptum tuum elevabitur aquila, et in arduis ponet nidum suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 28, 'In petris manet, et in præruptis silicibus commoratur, atque inaccessis rupibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 29, 'Inde contemplatur escam, et de longe oculi ejus prospiciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 30, 'Pulli ejus lambent sanguinem: et ubicumque cadaver fuerit, statim adest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 31, 'Et adjecit Dominus, et locutus est ad Job:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 32, 'Numquid qui contendit cum Deo, tam facile conquiescit? utique qui arguit Deum, debet respondere ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 33, 'Respondens autem Job Domino, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 34, 'Qui leviter locutus sum, respondere quid possum? manum meam ponam super os meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 39, 35, 'Unum locutus sum, quod utinam non dixissem: et alterum, quibus ultra non addam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 1, 'Respondens autem Dominus Job de turbine, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 2, 'Accinge sicut vir lumbos tuos: interrogabo te, et indica mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 3, 'Numquid irritum facies judicium meum, et condemnabis me, ut tu justificeris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 4, 'Et si habes brachium sicut Deus? et si voce simili tonas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 5, 'Circumda tibi decorem, et in sublime erigere, et esto gloriosus, et speciosis induere vestibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 6, 'Disperge superbos in furore tuo, et respiciens omnem arrogantem humilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 7, 'Respice cunctos superbos, et confunde eos, et contere impios in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 8, 'Absconde eos in pulvere simul, et facies eorum demerge in foveam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 9, 'Et ego confitebor quod salvare te possit dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 10, 'Ecce behemoth quem feci tecum, fœnum quasi bos comedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 11, 'Fortitudo ejus in lumbis ejus, et virtus illius in umbilico ventris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 12, 'Stringit caudam suam quasi cedrum; nervi testiculorum ejus perplexi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 13, 'Ossa ejus velut fistulæ æris; cartilago illius quasi laminæ ferreæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 14, 'Ipse est principium viarum Dei: qui fecit eum applicabit gladium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 15, 'Huic montes herbas ferunt: omnes bestiæ agri ludent ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 16, 'Sub umbra dormit in secreto calami, et in locis humentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 17, 'Protegunt umbræ umbram ejus: circumdabunt eum salices torrentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 18, 'Ecce absorbebit fluvium, et non mirabitur, et habet fiduciam quod influat Jordanis in os ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 19, 'In oculis ejus quasi hamo capiet eum, et in sudibus perforabit nares ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 20, 'An extrahere poteris Leviathan hamo, et fune ligabis linguam ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 21, 'Numquid pones circulum in naribus ejus, aut armilla perforabis maxillam ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 22, 'Numquid multiplicabit ad te preces, aut loquetur tibi mollia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 23, 'Numquid feriet tecum pactum, et accipies eum servum sempiternum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 24, 'Numquid illudes ei quasi avi, aut ligabis eum ancillis tuis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 25, 'Concident eum amici? divident illum negotiatores?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 26, 'Numquid implebis sagenas pelle ejus, et gurgustium piscium capite illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 27, 'Pone super eum manum tuam: memento belli, nec ultra addas loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 40, 28, 'Ecce spes ejus frustrabitur eum, et videntibus cunctis præcipitabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 1, 'Non quasi crudelis suscitabo eum: quis enim resistere potest vultui meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 2, 'Quis ante dedit mihi, ut reddam ei? omnia quæ sub cælo sunt, mea sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 3, 'Non parcam ei, et verbis potentibus, et ad deprecandum compositis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 4, 'Quis revelabit faciem indumenti ejus? et in medium oris ejus quis intrabit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 5, 'Portas vultus ejus quis aperiet? per gyrum dentium ejus formido.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 6, 'Corpus illius quasi scuta fusilia, compactum squamis se prementibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 7, 'Una uni conjungitur, et ne spiraculum quidem incedit per eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 8, 'Una alteri adhærebit, et tenentes se nequaquam separabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 9, 'Sternutatio ejus splendor ignis, et oculi ejus ut palpebræ diluculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 10, 'De ore ejus lampades procedunt, sicut tædæ ignis accensæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 11, 'De naribus ejus procedit fumus, sicut ollæ succensæ atque ferventis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 12, 'Halitus ejus prunas ardere facit, et flamma de ore ejus egreditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 13, 'In collo ejus morabitur fortitudo, et faciem ejus præcedit egestas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 14, 'Membra carnium ejus cohærentia sibi: mittet contra eum fulmina, et ad locum alium non ferentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 15, 'Cor ejus indurabitur tamquam lapis, et stringetur quasi malleatoris incus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 16, 'Cum sublatus fuerit, timebunt angeli, et territi purgabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 17, 'Cum apprehenderit eum gladius, subsistere non poterit, neque hasta, neque thorax:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 18, 'reputabit enim quasi paleas ferrum, et quasi lignum putridum æs.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 19, 'Non fugabit eum vir sagittarius: in stipulam versi sunt ei lapides fundæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 20, 'Quasi stipulam æstimabit malleum, et deridebit vibrantem hastam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 21, 'Sub ipso erunt radii solis, et sternet sibi aurum quasi lutum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 22, 'Fervescere faciet quasi ollam profundum mare, et ponet quasi cum unguenta bulliunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 23, 'Post eum lucebit semita: æstimabit abyssum quasi senescentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 24, 'Non est super terram potestas quæ comparetur ei, qui factus est ut nullum timeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 41, 25, 'Omne sublime videt: ipse est rex super universos filios superbiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 1, 'Respondens autem Job Domino, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 2, 'Scio quia omnia potes, et nulla te latet cogitatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 3, 'Quis est iste qui celat consilium absque scientia? ideo insipienter locutus sum, et quæ ultra modum excederent scientiam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 4, 'Audi, et ego loquar: interrogabo te, et responde mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 5, 'Auditu auris audivi te: nunc autem oculus meus videt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 6, 'Idcirco ipse me reprehendo, et ago pœnitentiam in favilla et cinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 7, 'Postquam autem locutus est Dominus verba hæc ad Job, dixit ad Eliphaz Themanitem: Iratus est furor meus in te, et in duos amicos tuos, quoniam non estis locuti coram me rectum, sicut servus meus Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 8, 'Sumite ergo vobis septem tauros et septem arietes, et ite ad servum meum Job, et offerte holocaustum pro vobis: Job autem servus meus orabit pro vobis. Faciem ejus suscipiam, ut non vobis imputetur stultitia: neque enim locuti estis ad me recta, sicut servus meus Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 9, 'Abierunt ergo Eliphaz Themanites, et Baldad Suhites, et Sophar Naamathites, et fecerunt sicut locutus fuerat Dominus ad eos: et suscepit Dominus faciem Job.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 10, 'Dominus quoque conversus est ad pœnitentiam Job, cum oraret ille pro amicis suis: et addidit Dominus omnia quæcumque fuerant Job, duplicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 11, 'Venerunt autem ad eum omnes fratres sui, et universæ sorores suæ, et cuncti qui noverant eum prius, et comederunt cum eo panem in domo ejus: et moverunt super eum caput, et consolati sunt eum super omni malo quod intulerat Dominus super eum: et dederunt ei unusquisque ovem unam, et inaurem auream unam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 12, 'Dominus autem benedixit novissimis Job magis quam principio ejus: et facta sunt ei quatuordecim millia ovium, et sex millia camelorum, et mille juga boum, et mille asinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 13, 'Et fuerunt ei septem filii, et tres filiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 14, 'Et vocavit nomen unius Diem, et nomen secundæ Cassiam, et nomen tertiæ Cornustibii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 15, 'Non sunt autem inventæ mulieres speciosæ sicut filiæ Job in universa terra: deditque eis pater suus hæreditatem inter fratres earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 42, 16, 'Vixit autem Job post hæc centum quadraginta annis, et vidit filios suos, et filios filiorum suorum usque ad quartam generationem: et mortuus est senex, et plenus dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Beatus vir qui non abiit in consilio impiorum, et in via peccatorum non stetit, et in cathedra pestilentiæ non sedit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'sed in lege Domini voluntas ejus, et in lege ejus meditabitur die ac nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Et erit tamquam lignum quod plantatum est secus decursus aquarum, quod fructum suum dabit in tempore suo: et folium ejus non defluet; et omnia quæcumque faciet prosperabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Non sic impii, non sic; sed tamquam pulvis quem projicit ventus a facie terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Ideo non resurgent impii in judicio, neque peccatores in concilio justorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'quoniam novit Dominus viam justorum, et iter impiorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Quare fremuerunt gentes, et populi meditati sunt inania?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Astiterunt reges terræ, et principes convenerunt in unum adversus Dominum, et adversus christum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Dirumpamus vincula eorum, et projiciamus a nobis jugum ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Qui habitat in cælis irridebit eos, et Dominus subsannabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Tunc loquetur ad eos in ira sua, et in furore suo conturbabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Ego autem constitutus sum rex ab eo super Sion, montem sanctum ejus, prædicans præceptum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Dominus dixit ad me: Filius meus es tu; ego hodie genui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Postula a me, et dabo tibi gentes hæreditatem tuam, et possessionem tuam terminos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Reges eos in virga ferrea, et tamquam vas figuli confringes eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Et nunc, reges, intelligite; erudimini, qui judicatis terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Servite Domino in timore, et exsultate ei cum tremore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Apprehendite disciplinam, nequando irascatur Dominus, et pereatis de via justa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Cum exarserit in brevi ira ejus, beati omnes qui confidunt in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Psalmus David, cum fugeret a facie Absalom filii sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Domine, quid multiplicati sunt qui tribulant me? Multi insurgunt adversum me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'multi dicunt animæ meæ: Non est salus ipsi in Deo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Tu autem Domine, susceptor meus es, gloria mea, et exaltans caput meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Voce mea ad Dominum clamavi; et exaudivit me de monte sancto suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Ego dormivi, et soporatus sum; et exsurrexi, quia Dominus suscepit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Non timebo millia populi circumdantis me. Exsurge, Domine; salvum me fac, Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Quoniam tu percussisti omnes adversantes mihi sine causa; dentes peccatorum contrivisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Domini est salus; et super populum tuum benedictio tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'In finem, in carminibus. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Cum invocarem exaudivit me Deus justitiæ meæ, in tribulatione dilatasti mihi. Miserere mei, et exaudi orationem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Filii hominum, usquequo gravi corde? ut quid diligitis vanitatem, et quæritis mendacium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Et scitote quoniam mirificavit Dominus sanctum suum; Dominus exaudiet me cum clamavero ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Irascimini, et nolite peccare; quæ dicitis in cordibus vestris, in cubilibus vestris compungimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Sacrificate sacrificium justitiæ, et sperate in Domino. Multi dicunt: Quis ostendit nobis bona?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Signatum est super nos lumen vultus tui, Domine: dedisti lætitiam in corde meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'A fructu frumenti, vini, et olei sui, multiplicati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'In pace in idipsum dormiam, et requiescam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'quoniam tu, Domine, singulariter in spe constituisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'In finem, pro ea quæ hæreditatem consequitur. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Verba mea auribus percipe, Domine; intellige clamorem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Intende voci orationis meæ, rex meus et Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Quoniam ad te orabo, Domine: mane exaudies vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Mane astabo tibi, et videbo quoniam non Deus volens iniquitatem tu es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Neque habitabit juxta te malignus, neque permanebunt injusti ante oculos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Odisti omnes qui operantur iniquitatem; perdes omnes qui loquuntur mendacium. Virum sanguinum et dolosum abominabitur Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Ego autem in multitudine misericordiæ tuæ introibo in domum tuam; adorabo ad templum sanctum tuum in timore tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Domine, deduc me in justitia tua: propter inimicos meos dirige in conspectu tuo viam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Quoniam non est in ore eorum veritas; cor eorum vanum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Sepulchrum patens est guttur eorum; linguis suis dolose agebant: judica illos, Deus. Decidant a cogitationibus suis; secundum multitudinem impietatum eorum expelle eos, quoniam irritaverunt te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Et lætentur omnes qui sperant in te; in æternum exsultabunt, et habitabis in eis. Et gloriabuntur in te omnes qui diligunt nomen tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'quoniam tu benedices justo. Domine, ut scuto bonæ voluntatis tuæ coronasti nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'In finem, in carminibus. Psalmus David. Pro octava.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Domine, ne in furore tuo arguas me, neque in ira tua corripias me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Miserere mei, Domine, quoniam infirmus sum; sana me, Domine, quoniam conturbata sunt ossa mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Et anima mea turbata est valde; sed tu, Domine, usquequo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Convertere, Domine, et eripe animam meam; salvum me fac propter misericordiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Quoniam non est in morte qui memor sit tui; in inferno autem quis confitebitur tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Laboravi in gemitu meo; lavabo per singulas noctes lectum meum: lacrimis meis stratum meum rigabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Turbatus est a furore oculus meus; inveteravi inter omnes inimicos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Discedite a me omnes qui operamini iniquitatem, quoniam exaudivit Dominus vocem fletus mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Exaudivit Dominus deprecationem meam; Dominus orationem meam suscepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Erubescant, et conturbentur vehementer, omnes inimici mei; convertantur, et erubescant valde velociter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Psalmus David, quem cantavit Domino pro verbis Chusi, filii Jemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Domine Deus meus, in te speravi; salvum me fac ex omnibus persequentibus me, et libera me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'nequando rapiat ut leo animam meam, dum non est qui redimat, neque qui salvum faciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Domine Deus meus, si feci istud, si est iniquitas in manibus meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'si reddidi retribuentibus mihi mala, decidam merito ab inimicis meis inanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Persequatur inimicus animam meam, et comprehendat; et conculcet in terra vitam meam, et gloriam meam in pulverem deducat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Exsurge, Domine, in ira tua, et exaltare in finibus inimicorum meorum: et exsurge, Domine Deus meus, in præcepto quod mandasti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'et synagoga populorum circumdabit te: et propter hanc in altum regredere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Dominus judicat populos. Judica me, Domine, secundum justitiam meam, et secundum innocentiam meam super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Consumetur nequitia peccatorum, et diriges justum, scrutans corda et renes, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Justum adjutorium meum a Domino, qui salvos facit rectos corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Deus judex justus, fortis, et patiens; numquid irascitur per singulos dies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Nisi conversi fueritis, gladium suum vibrabit; arcum suum tetendit, et paravit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Et in eo paravit vasa mortis, sagittas suas ardentibus effecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Ecce parturiit injustitiam; concepit dolorem, et peperit iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Lacum aperuit, et effodit eum; et incidit in foveam quam fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Convertetur dolor ejus in caput ejus, et in verticem ipsius iniquitas ejus descendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Confitebor Domino secundum justitiam ejus, et psallam nomini Domini altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'In finem, pro torcularibus. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Domine, Dominus noster, quam admirabile est nomen tuum in universa terra! quoniam elevata est magnificentia tua super cælos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ex ore infantium et lactentium perfecisti laudem propter inimicos tuos, ut destruas inimicum et ultorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Quoniam videbo cælos tuos, opera digitorum tuorum, lunam et stellas quæ tu fundasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Quid est homo, quod memor es ejus? aut filius hominis, quoniam visitas eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Minuisti eum paulominus ab angelis; gloria et honore coronasti eum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'et constituisti eum super opera manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Omnia subjecisti sub pedibus ejus, oves et boves universas, insuper et pecora campi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'volucres cæli, et pisces maris qui perambulant semitas maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Domine, Dominus noster, quam admirabile est nomen tuum in universa terra!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'In finem, pro occultis filii. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Confitebor tibi, Domine, in toto corde meo; narrabo omnia mirabilia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Lætabor et exsultabo in te; psallam nomini tuo, Altissime.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'In convertendo inimicum meum retrorsum; infirmabuntur, et peribunt a facie tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Quoniam fecisti judicium meum et causam meam; sedisti super thronum, qui judicas justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Increpasti gentes, et periit impius: nomen eorum delesti in æternum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Inimici defecerunt frameæ in finem, et civitates eorum destruxisti. Periit memoria eorum cum sonitu;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'et Dominus in æternum permanet. Paravit in judicio thronum suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'et ipse judicabit orbem terræ in æquitate: judicabit populos in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Et factus est Dominus refugium pauperi; adjutor in opportunitatibus, in tribulatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Et sperent in te qui noverunt nomen tuum, quoniam non dereliquisti quærentes te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Psallite Domino qui habitat in Sion; annuntiate inter gentes studia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'quoniam requirens sanguinem eorum recordatus est; non est oblitus clamorem pauperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Miserere mei, Domine: vide humilitatem meam de inimicis meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'qui exaltas me de portis mortis, ut annuntiem omnes laudationes tuas in portis filiæ Sion:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'exultabo in salutari tuo. Infixæ sunt gentes in interitu quem fecerunt; in laqueo isto quem absconderunt comprehensus est pes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Cognoscetur Dominus judicia faciens; in operibus manuum suarum comprehensus est peccator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Convertantur peccatores in infernum, omnes gentes quæ obliviscuntur Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 19, 'Quoniam non in finem oblivio erit pauperis; patientia pauperum non peribit in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 20, 'Exsurge, Domine; non confortetur homo: judicentur gentes in conspectu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 21, 'Constitue, Domine, legislatorem super eos, ut sciant gentes quoniam homines sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 22, 'Ut quid, Domine, recessisti longe; despicis in opportunitatibus, in tribulatione?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 23, 'Dum superbit impius, incenditur pauper: comprehenduntur in consiliis quibus cogitant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 24, 'Quoniam laudatur peccator in desideriis animæ suæ, et iniquus benedicitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 25, 'Exacerbavit Dominum peccator: secundum multitudinem iræ suæ, non quæret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 26, 'Non est Deus in conspectu ejus; inquinatæ sunt viæ illius in omni tempore. Auferuntur judicia tua a facie ejus; omnium inimicorum suorum dominabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 27, 'Dixit enim in corde suo: Non movebor a generatione in generationem, sine malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 28, 'Cujus maledictione os plenum est, et amaritudine, et dolo; sub lingua ejus labor et dolor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 29, 'Sedet in insidiis cum divitibus in occultis, ut interficiat innocentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 30, 'Oculi ejus in pauperem respiciunt; insidiatur in abscondito, quasi leo in spelunca sua. Insidiatur ut rapiat pauperem; rapere pauperem dum attrahit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 31, 'In laqueo suo humiliabit eum; inclinabit se, et cadet cum dominatus fuerit pauperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 32, 'Dixit enim in corde suo: Oblitus est Deus; avertit faciem suam, ne videat in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 33, 'Exsurge, Domine Deus, exaltetur manus tua; ne obliviscaris pauperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 34, 'Propter quid irritavit impius Deum? dixit enim in corde suo: Non requiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 35, 'Vides, quoniam tu laborem et dolorem consideras, ut tradas eos in manus tuas. Tibi derelictus est pauper; orphano tu eris adjutor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 36, 'Contere brachium peccatoris et maligni; quæretur peccatum illius, et non invenietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 37, 'Dominus regnabit in æternum, et in sæculum sæculi; peribitis, gentes, de terra illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 38, 'Desiderium pauperum exaudivit Dominus; præparationem cordis eorum audivit auris tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 39, 'judicare pupillo et humili, ut non apponat ultra magnificare se homo super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'In Domino confido; quomodo dicitis animæ meæ: Transmigra in montem sicut passer?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Quoniam ecce peccatores intenderunt arcum; paraverunt sagittas suas in pharetra, ut sagittent in obscuro rectos corde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'quoniam quæ perfecisti destruxerunt; justus autem, quid fecit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Dominus in templo sancto suo; Dominus in cælo sedes ejus. Oculi ejus in pauperem respiciunt; palpebræ ejus interrogant filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Dominus interrogat justum et impium; qui autem diligit iniquitatem, odit animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Pluet super peccatores laqueos; ignis et sulphur, et spiritus procellarum, pars calicis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Quoniam justus Dominus, et justitias dilexit: æquitatem vidit vultus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'In finem, pro octava. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Salvum me fac, Domine, quoniam defecit sanctus, quoniam diminutæ sunt veritates a filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Vana locuti sunt unusquisque ad proximum suum; labia dolosa, in corde et corde locuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Disperdat Dominus universa labia dolosa, et linguam magniloquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Qui dixerunt: Linguam nostram magnificabimus; labia nostra a nobis sunt. Quis noster dominus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Propter miseriam inopum, et gemitum pauperum, nunc exsurgam, dicit Dominus. Ponam in salutari; fiducialiter agam in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Eloquia Domini, eloquia casta; argentum igne examinatum, probatum terræ, purgatum septuplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Tu, Domine, servabis nos, et custodies nos a generatione hac in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'In circuitu impii ambulant: secundum altitudinem tuam multiplicasti filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'In finem. Psalmus David. Usquequo, Domine, oblivisceris me in finem? usquequo avertis faciem tuam a me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'quamdiu ponam consilia in anima mea; dolorem in corde meo per diem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'usquequo exaltabitur inimicus meus super me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Respice, et exaudi me, Domine Deus meus. Illumina oculos meos, ne umquam obdormiam in morte;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'nequando dicat inimicus meus: Prævalui adversus eum. Qui tribulant me exsultabunt si motus fuero;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ego autem in misericordia tua speravi. Exsultabit cor meum in salutari tuo. Cantabo Domino qui bona tribuit mihi; et psallam nomini Domini altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 1, 'In finem. Psalmus David. Dixit insipiens in corde suo: Non est Deus. Corrupti sunt, et abominabiles facti sunt in studiis suis; non est qui faciat bonum, non est usque ad unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 2, 'Dominus de cælo prospexit super filios hominum, ut videat si est intelligens, aut requirens Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 3, 'Omnes declinaverunt, simul inutiles facti sunt. Non est qui faciat bonum, non est usque ad unum. Sepulchrum patens est guttur eorum; linguis suis dolose agebant. Venenum aspidum sub labiis eorum, quorum os maledictione et amaritudine plenum est; veloces pedes eorum ad effundendum sanguinem. Contritio et infelicitas in viis eorum, et viam pacis non cognoverunt; non est timor Dei ante oculos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 4, 'Nonne cognoscent omnes qui operantur iniquitatem, qui devorant plebem meam sicut escam panis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 5, 'Dominum non invocaverunt; illic trepidaverunt timore, ubi non erat timor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 6, 'Quoniam Dominus in generatione justa est: consilium inopis confudistis, quoniam Dominus spes ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 13, 7, 'Quis dabit ex Sion salutare Israël? Cum averterit Dominus captivitatem plebis suæ, exsultabit Jacob, et lætabitur Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 1, 'Psalmus David. Domine, quis habitabit in tabernaculo tuo? aut quis requiescet in monte sancto tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 2, 'Qui ingreditur sine macula, et operatur justitiam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 3, 'qui loquitur veritatem in corde suo: qui non egit dolum in lingua sua, nec fecit proximo suo malum, et opprobrium non accepit adversus proximos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 4, 'Ad nihilum deductus est in conspectu ejus malignus; timentes autem Dominum glorificat. Qui jurat proximo suo, et non decipit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 14, 5, 'qui pecuniam suam non dedit ad usuram, et munera super innocentem non accepit: qui facit hæc non movebitur in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 1, 'Tituli inscriptio, ipsi David. Conserva me, Domine, quoniam speravi in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 2, 'Dixi Domino: Deus meus es tu, quoniam bonorum meorum non eges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 3, 'Sanctis qui sunt in terra ejus, mirificavit omnes voluntates meas in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 4, 'Multiplicatæ sunt infirmitates eorum: postea acceleraverunt. Non congregabo conventicula eorum de sanguinibus, nec memor ero nominum eorum per labia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 5, 'Dominus pars hæreditatis meæ, et calicis mei: tu es qui restitues hæreditatem meam mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 6, 'Funes ceciderunt mihi in præclaris; etenim hæreditas mea præclara est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 7, 'Benedicam Dominum qui tribuit mihi intellectum; insuper et usque ad noctem increpuerunt me renes mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 8, 'Providebam Dominum in conspectu meo semper: quoniam a dextris est mihi, ne commovear.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 9, 'Propter hoc lætatum est cor meum, et exsultavit lingua mea; insuper et caro mea requiescet in spe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 10, 'Quoniam non derelinques animam meam in inferno, nec dabis sanctum tuum videre corruptionem. Notas mihi fecisti vias vitæ; adimplebis me lætitia cum vultu tuo: delectationes in dextera tua usque in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 15, 11, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 1, 'Oratio David. Exaudi, Domine, justitiam meam; intende deprecationem meam. Auribus percipe orationem meam, non in labiis dolosis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 2, 'De vultu tuo judicium meum prodeat; oculi tui videant æquitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 3, 'Probasti cor meum, et visitasti nocte; igne me examinasti, et non est inventa in me iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 4, 'Ut non loquatur os meum opera hominum: propter verba labiorum tuorum, ego custodivi vias duras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 5, 'Perfice gressus meos in semitis tuis, ut non moveantur vestigia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 6, 'Ego clamavi, quoniam exaudisti me, Deus; inclina aurem tuam mihi, et exaudi verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 7, 'Mirifica misericordias tuas, qui salvos facis sperantes in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 8, 'A resistentibus dexteræ tuæ custodi me ut pupillam oculi. Sub umbra alarum tuarum protege me');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 9, 'a facie impiorum qui me afflixerunt. Inimici mei animam meam circumdederunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 10, 'adipem suum concluserunt: os eorum locutum est superbiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 11, 'Projicientes me nunc circumdederunt me; oculos suos statuerunt declinare in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 12, 'Susceperunt me sicut leo paratus ad prædam, et sicut catulus leonis habitans in abditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 13, 'Exsurge, Domine: præveni eum, et supplanta eum: eripe animam meam ab impio; frameam tuam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 14, 'ab inimicis manus tuæ. Domine, a paucis de terra divide eos in vita eorum; de absconditis tuis adimpletus est venter eorum. Saturati sunt filiis, et dimiserunt reliquias suas parvulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 16, 15, 'Ego autem in justitia apparebo conspectui tuo; satiabor cum apparuerit gloria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 1, 'In finem. Puero Domini David, qui locutus est Domino verba cantici hujus, in die qua eripuit eum Dominus de manu omnium inimicorum ejus, et de manu Saul, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 2, 'Diligam te, Domine, fortitudo mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 3, 'Dominus firmamentum meum, et refugium meum, et liberator meus. Deus meus adjutor meus, et sperabo in eum; protector meus, et cornu salutis meæ, et susceptor meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 4, 'Laudans invocabo Dominum, et ab inimicis meis salvus ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 5, 'Circumdederunt me dolores mortis, et torrentes iniquitatis conturbaverunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 6, 'Dolores inferni circumdederunt me; præoccupaverunt me laquei mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 7, 'In tribulatione mea invocavi Dominum, et ad Deum meum clamavi: et exaudivit de templo sancto suo vocem meam; et clamor meus in conspectu ejus introivit in aures ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 8, 'Commota est, et contremuit terra; fundamenta montium conturbata sunt, et commota sunt: quoniam iratus est eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 9, 'Ascendit fumus in ira ejus, et ignis a facie ejus exarsit; carbones succensi sunt ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 10, 'Inclinavit cælos, et descendit, et caligo sub pedibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 11, 'Et ascendit super cherubim, et volavit; volavit super pennas ventorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 12, 'Et posuit tenebras latibulum suum; in circuitu ejus tabernaculum ejus, tenebrosa aqua in nubibus aëris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 13, 'Præ fulgore in conspectu ejus nubes transierunt; grando et carbones ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 14, 'Et intonuit de cælo Dominus, et Altissimus dedit vocem suam: grando et carbones ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 15, 'Et misit sagittas suas, et dissipavit eos; fulgura multiplicavit, et conturbavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 16, 'Et apparuerunt fontes aquarum, et revelata sunt fundamenta orbis terrarum, ab increpatione tua, Domine, ab inspiratione spiritus iræ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 17, 'Misit de summo, et accepit me; et assumpsit me de aquis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 18, 'Eripuit me de inimicis meis fortissimis, et ab his qui oderunt me. Quoniam confortati sunt super me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 19, 'prævenerunt me in die afflictionis meæ: et factus est Dominus protector meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 20, 'Et eduxit me in latitudinem; salvum me fecit, quoniam voluit me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 21, 'et retribuet mihi Dominus secundum justitiam meam, et secundum puritatem manuum mearum retribuet mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 22, 'quia custodivi vias Domini, nec impie gessi a Deo meo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 23, 'quoniam omnia judicia ejus in conspectu meo, et justitias ejus non repuli a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 24, 'Et ero immaculatus cum eo; et observabo me ab iniquitate mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 25, 'Et retribuet mihi Dominus secundum justitiam meam, et secundum puritatem manuum mearum in conspectu oculorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 26, 'Cum sancto sanctus eris, et cum viro innocente innocens eris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 27, 'et cum electo electus eris, et cum perverso perverteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 28, 'Quoniam tu populum humilem salvum facies, et oculos superborum humiliabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 29, 'Quoniam tu illuminas lucernam meam, Domine; Deus meus, illumina tenebras meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 30, 'Quoniam in te eripiar a tentatione; et in Deo meo transgrediar murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 31, 'Deus meus, impolluta via ejus; eloquia Domini igne examinata: protector est omnium sperantium in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 32, 'Quoniam quis deus præter Dominum? aut quis deus præter Deum nostrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 33, 'Deus qui præcinxit me virtute, et posuit immaculatam viam meam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 34, 'qui perfecit pedes meos tamquam cervorum, et super excelsa statuens me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 35, 'qui docet manus meas ad prælium. Et posuisti, ut arcum æreum, brachia mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 36, 'et dedisti mihi protectionem salutis tuæ: et dextera tua suscepit me, et disciplina tua correxit me in finem, et disciplina tua ipsa me docebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 37, 'Dilatasti gressus meos subtus me, et non sunt infirmata vestigia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 38, 'Persequar inimicos meos, et comprehendam illos; et non convertar donec deficiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 39, 'Confringam illos, nec poterunt stare; cadent subtus pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 40, 'Et præcinxisti me virtute ad bellum, et supplantasti insurgentes in me subtus me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 41, 'Et inimicos meos dedisti mihi dorsum, et odientes me disperdidisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 42, 'Clamaverunt, nec erat qui salvos faceret; ad Dominum, nec exaudivit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 43, 'Et comminuam eos ut pulverem ante faciem venti; ut lutum platearum delebo eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 44, 'Eripies me de contradictionibus populi; constitues me in caput gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 45, 'Populus quem non cognovi servivit mihi; in auditu auris obedivit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 46, 'Filii alieni mentiti sunt mihi, filii alieni inveterati sunt, et claudicaverunt a semitis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 47, 'Vivit Dominus, et benedictus Deus meus, et exaltetur Deus salutis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 48, 'Deus qui das vindictas mihi, et subdis populos sub me; liberator meus de inimicis meis iracundis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 49, 'Et ab insurgentibus in me exaltabis me; a viro iniquo eripies me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 50, 'Propterea confitebor tibi in nationibus, Domine, et nomini tuo psalmum dicam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 17, 51, 'magnificans salutes regis ejus, et faciens misericordiam christo suo David, et semini ejus usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 2, 'Cæli enarrant gloriam Dei, et opera manuum ejus annuntiat firmamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 3, 'Dies diei eructat verbum, et nox nocti indicat scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 4, 'Non sunt loquelæ, neque sermones, quorum non audiantur voces eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 5, 'In omnem terram exivit sonus eorum, et in fines orbis terræ verba eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 6, 'In sole posuit tabernaculum suum; et ipse tamquam sponsus procedens de thalamo suo. Exsultavit ut gigas ad currendam viam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 7, 'a summo cælo egressio ejus. Et occursus ejus usque ad summum ejus; nec est qui se abscondat a calore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 8, 'Lex Domini immaculata, convertens animas; testimonium Domini fidele, sapientiam præstans parvulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 9, 'Justitiæ Domini rectæ, lætificantes corda; præceptum Domini lucidum, illuminans oculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 10, 'Timor Domini sanctus, permanens in sæculum sæculi; judicia Domini vera, justificata in semetipsa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 11, 'desiderabilia super aurum et lapidem pretiosum multum, et dulciora super mel et favum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 12, 'Etenim servus tuus custodit ea; in custodiendis illis retributio multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 13, 'Delicta quis intelligit? ab occultis meis munda me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 14, 'et ab alienis parce servo tuo. Si mei non fuerint dominati, tunc immaculatus ero, et emundabor a delicto maximo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 18, 15, 'Et erunt ut complaceant eloquia oris mei, et meditatio cordis mei in conspectu tuo semper. Domine, adjutor meus, et redemptor meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 2, 'Exaudiat te Dominus in die tribulationis; protegat te nomen Dei Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 3, 'Mittat tibi auxilium de sancto, et de Sion tueatur te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 4, 'Memor sit omnis sacrificii tui, et holocaustum tuum pingue fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 5, 'Tribuat tibi secundum cor tuum, et omne consilium tuum confirmet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 6, 'Lætabimur in salutari tuo; et in nomine Dei nostri magnificabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 7, 'Impleat Dominus omnes petitiones tuas; nunc cognovi quoniam salvum fecit Dominus christum suum. Exaudiet illum de cælo sancto suo, in potentatibus salus dexteræ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 8, 'Hi in curribus, et hi in equis; nos autem in nomine Domini Dei nostri invocabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 9, 'Ipsi obligati sunt, et ceciderunt; nos autem surreximus, et erecti sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 19, 10, 'Domine, salvum fac regem, et exaudi nos in die qua invocaverimus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 2, 'Domine, in virtute tua lætabitur rex, et super salutare tuum exsultabit vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 3, 'Desiderium cordis ejus tribuisti ei, et voluntate labiorum ejus non fraudasti eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 4, 'Quoniam prævenisti eum in benedictionibus dulcedinis; posuisti in capite ejus coronam de lapide pretioso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 5, 'Vitam petiit a te, et tribuisti ei longitudinem dierum, in sæculum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 6, 'Magna est gloria ejus in salutari tuo; gloriam et magnum decorem impones super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 7, 'Quoniam dabis eum in benedictionem in sæculum sæculi; lætificabis eum in gaudio cum vultu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 8, 'Quoniam rex sperat in Domino, et in misericordia Altissimi non commovebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 9, 'Inveniatur manus tua omnibus inimicis tuis; dextera tua inveniat omnes qui te oderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 10, 'Pones eos ut clibanum ignis in tempore vultus tui: Dominus in ira sua conturbabit eos, et devorabit eos ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 11, 'Fructum eorum de terra perdes, et semen eorum a filiis hominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 12, 'quoniam declinaverunt in te mala; cogitaverunt consilia quæ non potuerunt stabilire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 13, 'Quoniam pones eos dorsum; in reliquiis tuis præparabis vultum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 20, 14, 'Exaltare, Domine, in virtute tua; cantabimus et psallemus virtutes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 1, 'In finem, pro susceptione matutina. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 2, 'Deus, Deus meus, respice in me: quare me dereliquisti? longe a salute mea verba delictorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 3, 'Deus meus, clamabo per diem, et non exaudies; et nocte, et non ad insipientiam mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 4, 'Tu autem in sancto habitas, laus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 5, 'In te speraverunt patres nostri; speraverunt, et liberasti eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 6, 'Ad te clamaverunt, et salvi facti sunt; in te speraverunt, et non sunt confusi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 7, 'Ego autem sum vermis, et non homo; opprobrium hominum, et abjectio plebis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 8, 'Omnes videntes me deriserunt me; locuti sunt labiis, et moverunt caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 9, 'Speravit in Domino, eripiat eum: salvum faciat eum, quoniam vult eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 10, 'Quoniam tu es qui extraxisti me de ventre, spes mea ab uberibus matris meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 11, 'In te projectus sum ex utero; de ventre matris meæ Deus meus es tu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 12, 'ne discesseris a me, quoniam tribulatio proxima est, quoniam non est qui adjuvet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 13, 'Circumdederunt me vituli multi; tauri pingues obsederunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 14, 'Aperuerunt super me os suum, sicut leo rapiens et rugiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 15, 'Sicut aqua effusus sum, et dispersa sunt omnia ossa mea: factum est cor meum tamquam cera liquescens in medio ventris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 16, 'Aruit tamquam testa virtus mea, et lingua mea adhæsit faucibus meis: et in pulverem mortis deduxisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 17, 'Quoniam circumdederunt me canes multi; concilium malignantium obsedit me. Foderunt manus meas et pedes meos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 18, 'dinumeraverunt omnia ossa mea. Ipsi vero consideraverunt et inspexerunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 19, 'Diviserunt sibi vestimenta mea, et super vestem meam miserunt sortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 20, 'Tu autem, Domine, ne elongaveris auxilium tuum a me; ad defensionem meam conspice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 21, 'Erue a framea, Deus, animam meam, et de manu canis unicam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 22, 'Salva me ex ore leonis, et a cornibus unicornium humilitatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 23, 'Narrabo nomen tuum fratribus meis; in medio ecclesiæ laudabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 24, 'Qui timetis Dominum, laudate eum; universum semen Jacob, glorificate eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 25, 'Timeat eum omne semen Israël, quoniam non sprevit, neque despexit deprecationem pauperis, nec avertit faciem suam a me: et cum clamarem ad eum, exaudivit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 26, 'Apud te laus mea in ecclesia magna; vota mea reddam in conspectu timentium eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 27, 'Edent pauperes, et saturabuntur, et laudabunt Dominum qui requirunt eum: vivent corda eorum in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 28, 'Reminiscentur et convertentur ad Dominum universi fines terræ; et adorabunt in conspectu ejus universæ familiæ gentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 29, 'quoniam Domini est regnum, et ipse dominabitur gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 30, 'Manducaverunt et adoraverunt omnes pingues terræ; in conspectu ejus cadent omnes qui descendunt in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 31, 'Et anima mea illi vivet; et semen meum serviet ipsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 21, 32, 'Annuntiabitur Domino generatio ventura; et annuntiabunt cæli justitiam ejus populo qui nascetur, quem fecit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 1, 'Psalmus David. Dominus regit me, et nihil mihi deerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 2, 'in loco pascuæ, ibi me collocavit. Super aquam refectionis educavit me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 3, 'animam meam convertit. Deduxit me super semitas justitiæ propter nomen suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 4, 'Nam etsi ambulavero in medio umbræ mortis, non timebo mala, quoniam tu mecum es. Virga tua, et baculus tuus, ipsa me consolata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 5, 'Parasti in conspectu meo mensam adversus eos qui tribulant me; impinguasti in oleo caput meum: et calix meus inebrians, quam præclarus est!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 22, 6, 'Et misericordia tua subsequetur me omnibus diebus vitæ meæ; et ut inhabitem in domo Domini in longitudinem dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 1, 'Prima sabbati. Psalmus David. Domini est terra, et plenitudo ejus; orbis terrarum, et universi qui habitant in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 2, 'Quia ipse super maria fundavit eum, et super flumina præparavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 3, 'Quis ascendet in montem Domini? aut quis stabit in loco sancto ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 4, 'Innocens manibus et mundo corde, qui non accepit in vano animam suam, nec juravit in dolo proximo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 5, 'hic accipiet benedictionem a Domino, et misericordiam a Deo salutari suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 6, 'Hæc est generatio quærentium eum, quærentium faciem Dei Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 7, 'Attollite portas, principes, vestras, et elevamini, portæ æternales, et introibit rex gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 8, 'Quis est iste rex gloriæ? Dominus fortis et potens, Dominus potens in prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 9, 'Attollite portas, principes, vestras, et elevamini, portæ æternales, et introibit rex gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 23, 10, 'Quis est iste rex gloriæ? Dominus virtutum ipse est rex gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 1, 'In finem. Psalmus David. Ad te, Domine, levavi animam meam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 2, 'Deus meus, in te confido; non erubescam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 3, 'Neque irrideant me inimici mei: etenim universi qui sustinent te, non confundentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 4, 'Confundantur omnes iniqua agentes supervacue. Vias tuas, Domine, demonstra mihi, et semitas tuas edoce me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 5, 'Dirige me in veritate tua, et doce me, quia tu es Deus salvator meus, et te sustinui tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 6, 'Reminiscere miserationum tuarum, Domine, et misericordiarum tuarum quæ a sæculo sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 7, 'Delicta juventutis meæ, et ignorantias meas, ne memineris. Secundum misericordiam tuam memento mei tu, propter bonitatem tuam, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 8, 'Dulcis et rectus Dominus; propter hoc legem dabit delinquentibus in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 9, 'Diriget mansuetos in judicio; docebit mites vias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 10, 'Universæ viæ Domini, misericordia et veritas, requirentibus testamentum ejus et testimonia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 11, 'Propter nomen tuum, Domine, propitiaberis peccato meo; multum est enim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 12, 'Quis est homo qui timet Dominum? legem statuit ei in via quam elegit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 13, 'Anima ejus in bonis demorabitur, et semen ejus hæreditabit terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 14, 'Firmamentum est Dominus timentibus eum; et testamentum ipsius ut manifestetur illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 15, 'Oculi mei semper ad Dominum, quoniam ipse evellet de laqueo pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 16, 'Respice in me, et miserere mei, quia unicus et pauper sum ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 17, 'Tribulationes cordis mei multiplicatæ sunt: de necessitatibus meis erue me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 18, 'Vide humilitatem meam et laborem meum, et dimitte universa delicta mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 19, 'Respice inimicos meos, quoniam multiplicati sunt, et odio iniquo oderunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 20, 'Custodi animam meam, et erue me: non erubescam, quoniam speravi in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 21, 'Innocentes et recti adhæserunt mihi, quia sustinui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 24, 22, 'Libera, Deus, Israël ex omnibus tribulationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 1, 'In finem. Psalmus David. Judica me, Domine, quoniam ego in innocentia mea ingressus sum, et in Domino sperans non infirmabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 2, 'Proba me, Domine, et tenta me; ure renes meos et cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 3, 'Quoniam misericordia tua ante oculos meos est, et complacui in veritate tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 4, 'Non sedi cum concilio vanitatis, et cum iniqua gerentibus non introibo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 5, 'Odivi ecclesiam malignantium, et cum impiis non sedebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 6, 'Lavabo inter innocentes manus meas, et circumdabo altare tuum, Domine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 7, 'ut audiam vocem laudis, et enarrem universa mirabilia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 8, 'Domine, dilexi decorem domus tuæ, et locum habitationis gloriæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 9, 'Ne perdas cum impiis, Deus, animam meam, et cum viris sanguinum vitam meam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 10, 'in quorum manibus iniquitates sunt; dextera eorum repleta est muneribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 11, 'Ego autem in innocentia mea ingressus sum; redime me, et miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 25, 12, 'Pes meus stetit in directo; in ecclesiis benedicam te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 1, 'Psalmus David, priusquam liniretur. Dominus illuminatio mea et salus mea: quem timebo? Dominus protector vitæ meæ: a quo trepidabo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 2, 'Dum appropiant super me nocentes ut edant carnes meas, qui tribulant me inimici mei, ipsi infirmati sunt et ceciderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 3, 'Si consistant adversum me castra, non timebit cor meum; si exsurgat adversum me prælium, in hoc ego sperabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 4, 'Unam petii a Domino, hanc requiram, ut inhabitem in domo Domini omnibus diebus vitæ meæ; ut videam voluptatem Domini, et visitem templum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 5, 'Quoniam abscondit me in tabernaculo suo; in die malorum protexit me in abscondito tabernaculi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 6, 'In petra exaltavit me, et nunc exaltavit caput meum super inimicos meos. Circuivi, et immolavi in tabernaculo ejus hostiam vociferationis; cantabo, et psalmum dicam Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 7, 'Exaudi, Domine, vocem meam, qua clamavi ad te; miserere mei, et exaudi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 8, 'Tibi dixit cor meum: Exquisivit te facies mea; faciem tuam, Domine, requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 9, 'Ne avertas faciem tuam a me; ne declines in ira a servo tuo. Adjutor meus esto; ne derelinquas me, neque despicias me, Deus salutaris meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 10, 'Quoniam pater meus et mater mea dereliquerunt me; Dominus autem assumpsit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 11, 'Legem pone mihi, Domine, in via tua, et dirige me in semitam rectam, propter inimicos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 12, 'Ne tradideris me in animas tribulantium me, quoniam insurrexerunt in me testes iniqui, et mentita est iniquitas sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 13, 'Credo videre bona Domini in terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 26, 14, 'Expecta Dominum, viriliter age: et confortetur cor tuum, et sustine Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 1, 'Psalmus ipsi David. Ad te, Domine, clamabo; Deus meus, ne sileas a me: nequando taceas a me, et assimilabor descendentibus in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 2, 'Exaudi, Domine, vocem deprecationis meæ dum oro ad te; dum extollo manus meas ad templum sanctum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 3, 'Ne simul trahas me cum peccatoribus, et cum operantibus iniquitatem ne perdas me; qui loquuntur pacem cum proximo suo, mala autem in cordibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 4, 'Da illis secundum opera eorum, et secundum nequitiam adinventionum ipsorum. Secundum opera manuum eorum tribue illis; redde retributionem eorum ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 5, 'Quoniam non intellexerunt opera Domini, et in opera manuum ejus destrues illos, et non ædificabis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 6, 'Benedictus Dominus, quoniam exaudivit vocem deprecationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 7, 'Dominus adjutor meus et protector meus; in ipso speravit cor meum, et adjutus sum: et refloruit caro mea, et ex voluntate mea confitebor ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 8, 'Dominus fortitudo plebis suæ, et protector salvationum christi sui est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 27, 9, 'Salvum fac populum tuum, Domine, et benedic hæreditati tuæ; et rege eos, et extolle illos usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 1, 'Psalmus David, in consummatione tabernaculi. Afferte Domino, filii Dei, afferte Domino filios arietum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 2, 'Afferte Domino gloriam et honorem; afferte Domino gloriam nomini ejus; adorate Dominum in atrio sancto ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 3, 'Vox Domini super aquas; Deus majestatis intonuit: Dominus super aquas multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 4, 'Vox Domini in virtute; vox Domini in magnificentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 5, 'Vox Domini confringentis cedros, et confringet Dominus cedros Libani:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 6, 'et comminuet eas, tamquam vitulum Libani, et dilectus quemadmodum filius unicornium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 7, 'Vox Domini intercidentis flammam ignis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 8, 'vox Domini concutientis desertum: et commovebit Dominus desertum Cades.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 9, 'Vox Domini præparantis cervos: et revelabit condensa, et in templo ejus omnes dicent gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 10, 'Dominus diluvium inhabitare facit, et sedebit Dominus rex in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 28, 11, 'Dominus virtutem populo suo dabit; Dominus benedicet populo suo in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 1, 'Psalmus cantici, in dedicatione domus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 2, 'Exaltabo te, Domine, quoniam suscepisti me, nec delectasti inimicos meos super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 3, 'Domine Deus meus, clamavi ad te, et sanasti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 4, 'Domine, eduxisti ab inferno animam meam; salvasti me a descendentibus in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 5, 'Psallite Domino, sancti ejus; et confitemini memoriæ sanctitatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 6, 'Quoniam ira in indignatione ejus, et vita in voluntate ejus: ad vesperum demorabitur fletus, et ad matutinum lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 7, 'Ego autem dixi in abundantia mea: Non movebor in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 8, 'Domine, in voluntate tua præstitisti decori meo virtutem; avertisti faciem tuam a me, et factus sum conturbatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 9, 'Ad te, Domine, clamabo, et ad Deum meum deprecabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 10, 'Quæ utilitas in sanguine meo, dum descendo in corruptionem? numquid confitebitur tibi pulvis, aut annuntiabit veritatem tuam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 11, 'Audivit Dominus, et misertus est mei; Dominus factus est adjutor meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 12, 'Convertisti planctum meum in gaudium mihi; conscidisti saccum meum, et circumdedisti me lætitia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 29, 13, 'ut cantet tibi gloria mea, et non compungar. Domine Deus meus, in æternum confitebor tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 1, 'In finem. Psalmus David, pro extasi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 2, 'In te, Domine, speravi; non confundar in æternum: in justitia tua libera me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 3, 'Inclina ad me aurem tuam; accelera ut eruas me. Esto mihi in Deum protectorem, et in domum refugii, ut salvum me facias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 4, 'quoniam fortitudo mea et refugium meum es tu; et propter nomen tuum deduces me et enutries me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 5, 'Educes me de laqueo hoc quem absconderunt mihi, quoniam tu es protector meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 6, 'In manus tuas commendo spiritum meum; redemisti me, Domine Deus veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 7, 'Odisti observantes vanitates supervacue; ego autem in Domino speravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 8, 'Exsultabo, et lætabor in misericordia tua, quoniam respexisti humilitatem meam; salvasti de necessitatibus animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 9, 'Nec conclusisti me in manibus inimici: statuisti in loco spatioso pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 10, 'Miserere mei, Domine, quoniam tribulor; conturbatus est in ira oculus meus, anima mea, et venter meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 11, 'Quoniam defecit in dolore vita mea, et anni mei in gemitibus. Infirmata est in paupertate virtus mea, et ossa mea conturbata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 12, 'Super omnes inimicos meos factus sum opprobrium, et vicinis meis valde, et timor notis meis; qui videbant me foras fugerunt a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 13, 'Oblivioni datus sum, tamquam mortuus a corde; factus sum tamquam vas perditum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 14, 'quoniam audivi vituperationem multorum commorantium in circuitu. In eo dum convenirent simul adversum me, accipere animam meam consiliati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 15, 'Ego autem in te speravi, Domine; dixi: Deus meus es tu;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 16, 'in manibus tuis sortes meæ: eripe me de manu inimicorum meorum, et a persequentibus me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 17, 'Illustra faciem tuam super servum tuum; salvum me fac in misericordia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 18, 'Domine, non confundar, quoniam invocavi te. Erubescant impii, et deducantur in infernum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 19, 'muta fiant labia dolosa, quæ loquuntur adversus justum iniquitatem, in superbia, et in abusione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 20, 'Quam magna multitudo dulcedinis tuæ, Domine, quam abscondisti timentibus te; perfecisti eis qui sperant in te in conspectu filiorum hominum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 21, 'Abscondes eos in abscondito faciei tuæ a conturbatione hominum; proteges eos in tabernaculo tuo, a contradictione linguarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 22, 'Benedictus Dominus, quoniam mirificavit misericordiam suam mihi in civitate munita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 23, 'Ego autem dixi in excessu mentis meæ: Projectus sum a facie oculorum tuorum: ideo exaudisti vocem orationis meæ, dum clamarem ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 24, 'Diligite Dominum, omnes sancti ejus, quoniam veritatem requiret Dominus, et retribuet abundanter facientibus superbiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 30, 25, 'Viriliter agite, et confortetur cor vestrum, omnes qui speratis in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 1, 'Ipsi David intellectus. Beati quorum remissæ sunt iniquitates, et quorum tecta sunt peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 2, 'Beatus vir cui non imputavit Dominus peccatum, nec est in spiritu ejus dolus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 3, 'Quoniam tacui, inveteraverunt ossa mea, dum clamarem tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 4, 'Quoniam die ac nocte gravata est super me manus tua, conversus sum in ærumna mea, dum configitur spina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 5, 'Delictum meum cognitum tibi feci, et injustitiam meam non abscondi. Dixi: Confitebor adversum me injustitiam meam Domino; et tu remisisti impietatem peccati mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 6, 'Pro hac orabit ad te omnis sanctus in tempore opportuno. Verumtamen in diluvio aquarum multarum, ad eum non approximabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 7, 'Tu es refugium meum a tribulatione quæ circumdedit me; exsultatio mea, erue me a circumdantibus me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 8, 'Intellectum tibi dabo, et instruam te in via hac qua gradieris; firmabo super te oculos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 9, 'Nolite fieri sicut equus et mulus, quibus non est intellectus. In camo et freno maxillas eorum constringe, qui non approximant ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 10, 'Multa flagella peccatoris; sperantem autem in Domino misericordia circumdabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 31, 11, 'Lætamini in Domino, et exsultate, justi; et gloriamini, omnes recti corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 1, 'Psalmus David. Exsultate, justi, in Domino; rectos decet collaudatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 2, 'Confitemini Domino in cithara; in psalterio decem chordarum psallite illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 3, 'Cantate ei canticum novum; bene psallite ei in vociferatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 4, 'Quia rectum est verbum Domini, et omnia opera ejus in fide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 5, 'Diligit misericordiam et judicium; misericordia Domini plena est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 6, 'Verbo Domini cæli firmati sunt, et spiritu oris ejus omnis virtus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 7, 'Congregans sicut in utre aquas maris; ponens in thesauris abyssos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 8, 'Timeat Dominum omnis terra; ab eo autem commoveantur omnes inhabitantes orbem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 9, 'Quoniam ipse dixit, et facta sunt; ipse mandavit et creata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 10, 'Dominus dissipat consilia gentium; reprobat autem cogitationes populorum, et reprobat consilia principum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 11, 'Consilium autem Domini in æternum manet; cogitationes cordis ejus in generatione et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 12, 'Beata gens cujus est Dominus Deus ejus; populus quem elegit in hæreditatem sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 13, 'De cælo respexit Dominus; vidit omnes filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 14, 'De præparato habitaculo suo respexit super omnes qui habitant terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 15, 'qui finxit sigillatim corda eorum; qui intelligit omnia opera eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 16, 'Non salvatur rex per multam virtutem, et gigas non salvabitur in multitudine virtutis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 17, 'Fallax equus ad salutem; in abundantia autem virtutis suæ non salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 18, 'Ecce oculi Domini super metuentes eum, et in eis qui sperant super misericordia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 19, 'ut eruat a morte animas eorum, et alat eos in fame.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 20, 'Anima nostra sustinet Dominum, quoniam adjutor et protector noster est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 21, 'Quia in eo lætabitur cor nostrum, et in nomine sancto ejus speravimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 32, 22, 'Fiat misericordia tua, Domine, super nos, quemadmodum speravimus in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 1, 'Davidi, cum immutavit vultum suum coram Achimelech, et dimisit eum, et abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 2, 'Benedicam Dominum in omni tempore; semper laus ejus in ore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 3, 'In Domino laudabitur anima mea: audiant mansueti, et lætentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 4, 'Magnificate Dominum mecum, et exaltemus nomen ejus in idipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 5, 'Exquisivi Dominum, et exaudivit me; et ex omnibus tribulationibus meis eripuit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 6, 'Accedite ad eum, et illuminamini; et facies vestræ non confundentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 7, 'Iste pauper clamavit, et Dominus exaudivit eum, et de omnibus tribulationibus ejus salvavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 8, 'Immittet angelus Domini in circuitu timentium eum, et eripiet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 9, 'Gustate et videte quoniam suavis est Dominus; beatus vir qui sperat in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 10, 'Timete Dominum, omnes sancti ejus, quoniam non est inopia timentibus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 11, 'Divites eguerunt, et esurierunt; inquirentes autem Dominum non minuentur omni bono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 12, 'Venite, filii; audite me: timorem Domini docebo vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 13, 'Quis est homo qui vult vitam; diligit dies videre bonos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 14, 'Prohibe linguam tuam a malo, et labia tua ne loquantur dolum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 15, 'Diverte a malo, et fac bonum; inquire pacem, et persequere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 16, 'Oculi Domini super justos, et aures ejus in preces eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 17, 'Vultus autem Domini super facientes mala, ut perdat de terra memoriam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 18, 'Clamaverunt justi, et Dominus exaudivit eos; et ex omnibus tribulationibus eorum liberavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 19, 'Juxta est Dominus iis qui tribulato sunt corde, et humiles spiritu salvabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 20, 'Multæ tribulationes justorum; et de omnibus his liberabit eos Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 21, 'Custodit Dominus omnia ossa eorum: unum ex his non conteretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 22, 'Mors peccatorum pessima; et qui oderunt justum delinquent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 33, 23, 'Redimet Dominus animas servorum suorum, et non delinquent omnes qui sperant in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 1, 'Ipsi David. Judica, Domine, nocentes me; expugna impugnantes me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 2, 'Apprehende arma et scutum, et exsurge in adjutorium mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 3, 'Effunde frameam, et conclude adversus eos qui persequuntur me; dic animæ meæ: Salus tua ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 4, 'Confundantur et revereantur quærentes animam meam; avertantur retrorsum et confundantur cogitantes mihi mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 5, 'Fiant tamquam pulvis ante faciem venti, et angelus Domini coarctans eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 6, 'Fiat via illorum tenebræ et lubricum, et angelus Domini persequens eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 7, 'Quoniam gratis absconderunt mihi interitum laquei sui; supervacue exprobraverunt animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 8, 'Veniat illi laqueus quem ignorat, et captio quam abscondit apprehendat eum, et in laqueum cadat in ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 9, 'Anima autem mea exsultabit in Domino, et delectabitur super salutari suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 10, 'Omnia ossa mea dicent: Domine, quis similis tibi? eripiens inopem de manu fortiorum ejus; egenum et pauperem a diripientibus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 11, 'Surgentes testes iniqui, quæ ignorabam interrogabant me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 12, 'Retribuebant mihi mala pro bonis, sterilitatem animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 13, 'Ego autem, cum mihi molesti essent, induebar cilicio; humiliabam in jejunio animam meam, et oratio mea in sinu meo convertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 14, 'Quasi proximum et quasi fratrem nostrum sic complacebam; quasi lugens et contristatus sic humiliabar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 15, 'Et adversum me lætati sunt, et convenerunt; congregata sunt super me flagella, et ignoravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 16, 'Dissipati sunt, nec compuncti; tentaverunt me, subsannaverunt me subsannatione; frenduerunt super me dentibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 17, 'Domine, quando respicies? Restitue animam meam a malignitate eorum; a leonibus unicam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 18, 'Confitebor tibi in ecclesia magna; in populo gravi laudabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 19, 'Non supergaudeant mihi qui adversantur mihi inique, qui oderunt me gratis, et annuunt oculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 20, 'Quoniam mihi quidem pacifice loquebantur; et in iracundia terræ loquentes, dolos cogitabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 21, 'Et dilataverunt super me os suum; dixerunt: Euge, euge! viderunt oculi nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 22, 'Vidisti, Domine: ne sileas; Domine, ne discedas a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 23, 'Exsurge et intende judicio meo, Deus meus; et Dominus meus, in causam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 24, 'Judica me secundum justitiam tuam, Domine Deus meus, et non supergaudeant mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 25, 'Non dicant in cordibus suis: Euge, euge, animæ nostræ; nec dicant: Devoravimus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 26, 'Erubescant et revereantur simul qui gratulantur malis meis; induantur confusione et reverentia qui magna loquuntur super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 27, 'Exsultent et lætentur qui volunt justitiam meam; et dicant semper: Magnificetur Dominus, qui volunt pacem servi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 34, 28, 'Et lingua mea meditabitur justitiam tuam; tota die laudem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 1, 'In finem. Servo Domini ipsi David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 2, 'Dixit injustus ut delinquat in semetipso: non est timor Dei ante oculos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 3, 'Quoniam dolose egit in conspectu ejus, ut inveniatur iniquitas ejus ad odium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 4, 'Verba oris ejus iniquitas, et dolus; noluit intelligere ut bene ageret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 5, 'Iniquitatem meditatus est in cubili suo; astitit omni viæ non bonæ: malitiam autem non odivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 6, 'Domine, in cælo misericordia tua, et veritas tua usque ad nubes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 7, 'Justitia tua sicut montes Dei; judicia tua abyssus multa. Homines et jumenta salvabis, Domine,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 8, 'quemadmodum multiplicasti misericordiam tuam, Deus. Filii autem hominum in tegmine alarum tuarum sperabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 9, 'Inebriabuntur ab ubertate domus tuæ, et torrente voluptatis tuæ potabis eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 10, 'quoniam apud te est fons vitæ, et in lumine tuo videbimus lumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 11, 'Prætende misericordiam tuam scientibus te, et justitiam tuam his qui recto sunt corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 12, 'Non veniat mihi pes superbiæ, et manus peccatoris non moveat me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 35, 13, 'Ibi ceciderunt qui operantur iniquitatem; expulsi sunt, nec potuerunt stare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 1, 'Psalmus ipsi David. Noli æmulari in malignantibus, neque zelaveris facientes iniquitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 2, 'quoniam tamquam fœnum velociter arescent, et quemadmodum olera herbarum cito decident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 3, 'Spera in Domino, et fac bonitatem; et inhabita terram, et pasceris in divitiis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 4, 'Delectare in Domino, et dabit tibi petitiones cordis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 5, 'Revela Domino viam tuam, et spera in eo, et ipse faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 6, 'Et educet quasi lumen justitiam tuam, et judicium tuum tamquam meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 7, 'Subditus esto Domino, et ora eum. Noli æmulari in eo qui prosperatur in via sua; in homine faciente injustitias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 8, 'Desine ab ira, et derelinque furorem; noli æmulari ut maligneris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 9, 'Quoniam qui malignantur exterminabuntur; sustinentes autem Dominum, ipsi hæreditabunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 10, 'Et adhuc pusillum, et non erit peccator; et quæres locum ejus, et non invenies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 11, 'Mansueti autem hæreditabunt terram, et delectabuntur in multitudine pacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 12, 'Observabit peccator justum, et stridebit super eum dentibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 13, 'Dominus autem irridebit eum, quoniam prospicit quod veniet dies ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 14, 'Gladium evaginaverunt peccatores; intenderunt arcum suum: ut dejiciant pauperem et inopem, ut trucident rectos corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 15, 'Gladius eorum intret in corda ipsorum, et arcus eorum confringatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 16, 'Melius est modicum justo, super divitias peccatorum multas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 17, 'quoniam brachia peccatorum conterentur: confirmat autem justos Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 18, 'Novit Dominus dies immaculatorum, et hæreditas eorum in æternum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 19, 'Non confundentur in tempore malo, et in diebus famis saturabuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 20, 'quia peccatores peribunt. Inimici vero Domini mox ut honorificati fuerint et exaltati, deficientes quemadmodum fumus deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 21, 'Mutuabitur peccator, et non solvet; justus autem miseretur et tribuet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 22, 'quia benedicentes ei hæreditabunt terram; maledicentes autem ei disperibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 23, 'Apud Dominum gressus hominis dirigentur, et viam ejus volet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 24, 'Cum ceciderit, non collidetur, quia Dominus supponit manum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 25, 'Junior fui, etenim senui; et non vidi justum derelictum, nec semen ejus quærens panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 26, 'Tota die miseretur et commodat; et semen illius in benedictione erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 27, 'Declina a malo, et fac bonum, et inhabita in sæculum sæculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 28, 'quia Dominus amat judicium, et non derelinquet sanctos suos: in æternum conservabuntur. Injusti punientur, et semen impiorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 29, 'Justi autem hæreditabunt terram, et inhabitabunt in sæculum sæculi super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 30, 'Os justi meditabitur sapientiam, et lingua ejus loquetur judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 31, 'Lex Dei ejus in corde ipsius, et non supplantabuntur gressus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 32, 'Considerat peccator justum, et quærit mortificare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 33, 'Dominus autem non derelinquet eum in manibus ejus, nec damnabit eum cum judicabitur illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 34, 'Exspecta Dominum, et custodi viam ejus, et exaltabit te ut hæreditate capias terram: cum perierint peccatores, videbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 35, 'Vidi impium superexaltatum, et elevatum sicut cedros Libani:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 36, 'et transivi, et ecce non erat; et quæsivi eum, et non est inventus locus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 37, 'Custodi innocentiam, et vide æquitatem, quoniam sunt reliquiæ homini pacifico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 38, 'Injusti autem disperibunt simul; reliquiæ impiorum interibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 39, 'Salus autem justorum a Domino; et protector eorum in tempore tribulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 36, 40, 'Et adjuvabit eos Dominus, et liberabit eos; et eruet eos a peccatoribus, et salvabit eos, quia speraverunt in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 1, 'Psalmus David, in rememorationem de sabbato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 2, 'Domine, ne in furore tuo arguas me, neque in ira tua corripias me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 3, 'quoniam sagittæ tuæ infixæ sunt mihi, et confirmasti super me manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 4, 'Non est sanitas in carne mea, a facie iræ tuæ; non est pax ossibus meis, a facie peccatorum meorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 5, 'quoniam iniquitates meæ supergressæ sunt caput meum, et sicut onus grave gravatæ sunt super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 6, 'Putruerunt et corruptæ sunt cicatrices meæ, a facie insipientiæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 7, 'Miser factus sum et curvatus sum usque in finem; tota die contristatus ingrediebar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 8, 'Quoniam lumbi mei impleti sunt illusionibus, et non est sanitas in carne mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 9, 'Afflictus sum, et humiliatus sum nimis; rugiebam a gemitu cordis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 10, 'Domine, ante te omne desiderium meum, et gemitus meus a te non est absconditus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 11, 'Cor meum conturbatum est; dereliquit me virtus mea, et lumen oculorum meorum, et ipsum non est mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 12, 'Amici mei et proximi mei adversum me appropinquaverunt, et steterunt; et qui juxta me erant, de longe steterunt: et vim faciebant qui quærebant animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 13, 'Et qui inquirebant mala mihi, locuti sunt vanitates, et dolos tota die meditabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 14, 'Ego autem, tamquam surdus, non audiebam; et sicut mutus non aperiens os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 15, 'Et factus sum sicut homo non audiens, et non habens in ore suo redargutiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 16, 'Quoniam in te, Domine, speravi; tu exaudies me, Domine Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 17, 'Quia dixi: Nequando supergaudeant mihi inimici mei; et dum commoventur pedes mei, super me magna locuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 18, 'Quoniam ego in flagella paratus sum, et dolor meus in conspectu meo semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 19, 'Quoniam iniquitatem meam annuntiabo, et cogitabo pro peccato meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 20, 'Inimici autem mei vivunt, et confirmati sunt super me: et multiplicati sunt qui oderunt me inique.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 21, 'Qui retribuunt mala pro bonis detrahebant mihi, quoniam sequebar bonitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 22, 'Ne derelinquas me, Domine Deus meus; ne discesseris a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 37, 23, 'Intende in adjutorium meum, Domine Deus salutis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 1, 'In finem, ipsi Idithun. Canticum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 2, 'Dixi: Custodiam vias meas: ut non delinquam in lingua mea. Posui ori meo custodiam, cum consisteret peccator adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 3, 'Obmutui, et humiliatus sum, et silui a bonis; et dolor meus renovatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 4, 'Concaluit cor meum intra me; et in meditatione mea exardescet ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 5, 'Locutus sum in lingua mea: Notum fac mihi, Domine, finem meum, et numerum dierum meorum quis est, ut sciam quid desit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 6, 'Ecce mensurabiles posuisti dies meos, et substantia mea tamquam nihilum ante te. Verumtamen universa vanitas, omnis homo vivens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 7, 'Verumtamen in imagine pertransit homo; sed et frustra conturbatur: thesaurizat, et ignorat cui congregabit ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 8, 'Et nunc quæ est exspectatio mea: nonne Dominus? et substantia mea apud te est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 9, 'Ab omnibus iniquitatibus meis erue me: opprobrium insipienti dedisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 10, 'Obmutui, et non aperui os meum, quoniam tu fecisti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 11, 'amove a me plagas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 12, 'A fortitudine manus tuæ ego defeci in increpationibus: propter iniquitatem corripuisti hominem. Et tabescere fecisti sicut araneam animam ejus: verumtamen vane conturbatur omnis homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 13, 'Exaudi orationem meam, Domine, et deprecationem meam; auribus percipe lacrimas meas. Ne sileas, quoniam advena ego sum apud te, et peregrinus sicut omnes patres mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 38, 14, 'Remitte mihi, ut refrigerer priusquam abeam et amplius non ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 1, 'In finem. Psalmus ipsi David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 2, 'Exspectans exspectavi Dominum, et intendit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 3, 'Et exaudivit preces meas, et eduxit me de lacu miseriæ et de luto fæcis. Et statuit super petram pedes meos, et direxit gressus meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 4, 'Et immisit in os meum canticum novum, carmen Deo nostro. Videbunt multi, et timebunt, et sperabunt in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 5, 'Beatus vir cujus est nomen Domini spes ejus, et non respexit in vanitates et insanias falsas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 6, 'Multa fecisti tu, Domine Deus meus, mirabilia tua; et cogitationibus tuis non est qui similis sit tibi. Annuntiavi et locutus sum: multiplicati sunt super numerum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 7, 'Sacrificium et oblationem noluisti; aures autem perfecisti mihi. Holocaustum et pro peccato non postulasti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 8, 'tunc dixi: Ecce venio. In capite libri scriptum est de me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 9, 'ut facerem voluntatem tuam. Deus meus, volui, et legem tuam in medio cordis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 10, 'Annuntiavi justitiam tuam in ecclesia magna; ecce labia mea non prohibebo: Domine, tu scisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 11, 'Justitiam tuam non abscondi in corde meo; veritatem tuam et salutare tuum dixi; non abscondi misericordiam tuam et veritatem tuam a concilio multo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 12, 'Tu autem, Domine, ne longe facias miserationes tuas a me; misericordia tua et veritas tua semper susceperunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 13, 'Quoniam circumdederunt me mala quorum non est numerus; comprehenderunt me iniquitates meæ, et non potui ut viderem. Multiplicatæ sunt super capillos capitis mei, et cor meum dereliquit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 14, 'Complaceat tibi, Domine, ut eruas me; Domine, ad adjuvandum me respice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 15, 'Confundantur et revereantur simul, qui quærunt animam meam ut auferant eam; convertantur retrorsum et revereantur, qui volunt mihi mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 16, 'Ferant confestim confusionem suam, qui dicunt mihi: Euge, euge!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 17, 'Exsultent et lætentur super te omnes quærentes te; et dicant semper: Magnificetur Dominus, qui diligunt salutare tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 39, 18, 'Ego autem mendicus sum et pauper; Dominus sollicitus est mei. Adjutor meus et protector meus tu es; Deus meus, ne tardaveris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 1, 'In finem. Psalmus ipsi David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 2, 'Beatus qui intelligit super egenum et pauperem: in die mala liberabit eum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 3, 'Dominus conservet eum, et vivificet eum, et beatum faciat eum in terra, et non tradat eum in animam inimicorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 4, 'Dominus opem ferat illi super lectum doloris ejus; universum stratum ejus versasti in infirmitate ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 5, 'Ego dixi: Domine, miserere mei; sana animam meam, quia peccavi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 6, 'Inimici mei dixerunt mala mihi: Quando morietur, et peribit nomen ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 7, 'Et si ingrediebatur ut videret, vana loquebatur; cor ejus congregavit iniquitatem sibi. Egrediebatur foras et loquebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 8, 'In idipsum adversum me susurrabant omnes inimici mei; adversum me cogitabant mala mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 9, 'Verbum iniquum constituerunt adversum me: Numquid qui dormit non adjiciet ut resurgat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 10, 'Etenim homo pacis meæ in quo speravi, qui edebat panes meos, magnificavit super me supplantationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 11, 'Tu autem, Domine, miserere mei, et resuscita me; et retribuam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 12, 'In hoc cognovi quoniam voluisti me, quoniam non gaudebit inimicus meus super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 13, 'Me autem propter innocentiam suscepisti; et confirmasti me in conspectu tuo in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 40, 14, 'Benedictus Dominus Deus Israël a sæculo et usque in sæculum. Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 1, 'In finem. Intellectus filiis Core.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 2, 'Quemadmodum desiderat cervus ad fontes aquarum, ita desiderat anima mea ad te, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 3, 'Sitivit anima mea ad Deum fortem, vivum; quando veniam, et apparebo ante faciem Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 4, 'Fuerunt mihi lacrimæ meæ panes die ac nocte, dum dicitur mihi quotidie: Ubi est Deus tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 5, 'Hæc recordatus sum, et effudi in me animam meam, quoniam transibo in locum tabernaculi admirabilis, usque ad domum Dei, in voce exsultationis et confessionis, sonus epulantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 6, 'Quare tristis es, anima mea? et quare conturbas me? Spera in Deo, quoniam adhuc confitebor illi, salutare vultus mei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 7, 'et Deus meus. Ad meipsum anima mea conturbata est: propterea memor ero tui de terra Jordanis et Hermoniim a monte modico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 8, 'Abyssus abyssum invocat, in voce cataractarum tuarum; omnia excelsa tua, et fluctus tui super me transierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 9, 'In die mandavit Dominus misericordiam suam, et nocte canticum ejus; apud me oratio Deo vitæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 10, 'Dicam Deo: Susceptor meus es; quare oblitus es mei? et quare contristatus incedo, dum affligit me inimicus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 11, 'Dum confringuntur ossa mea, exprobraverunt mihi qui tribulant me inimici mei, dum dicunt mihi per singulos dies: Ubi est Deus tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 41, 12, 'Quare tristis es, anima mea? et quare conturbas me? Spera in Deo, quoniam adhuc confitebor illi, salutare vultus mei, et Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 1, 'Psalmus David. Judica me, Deus, et discerne causam meam de gente non sancta: ab homine iniquo et doloso erue me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 2, 'Quia tu es, Deus, fortitudo mea: quare me repulisti? et quare tristis incedo, dum affligit me inimicus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 3, 'Emitte lucem tuam et veritatem tuam: ipsa me deduxerunt, et adduxerunt in montem sanctum tuum, et in tabernacula tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 4, 'Et introibo ad altare Dei, ad Deum qui lætificat juventutem meam. Confitebor tibi in cithara, Deus, Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 5, 'Quare tristis es, anima mea? et quare conturbas me? Spera in Deo, quoniam adhuc confitebor illi, salutare vultus mei, et Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 42, 6, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 1, 'In finem. Filiis Core ad intellectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 2, 'Deus, auribus nostris audivimus, patres nostri annuntiaverunt nobis, opus quod operatus es in diebus eorum, et in diebus antiquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 3, 'Manus tua gentes disperdidit, et plantasti eos; afflixisti populos, et expulisti eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 4, 'Nec enim in gladio suo possederunt terram, et brachium eorum non salvavit eos: sed dextera tua et brachium tuum, et illuminatio vultus tui, quoniam complacuisti in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 5, 'Tu es ipse rex meus et Deus meus, qui mandas salutes Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 6, 'In te inimicos nostros ventilabimus cornu, et in nomine tuo spernemus insurgentes in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 7, 'Non enim in arcu meo sperabo, et gladius meus non salvabit me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 8, 'salvasti enim nos de affligentibus nos, et odientes nos confudisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 9, 'In Deo laudabimur tota die, et in nomine tuo confitebimur in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 10, 'Nunc autem repulisti et confudisti nos, et non egredieris, Deus, in virtutibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 11, 'Avertisti nos retrorsum post inimicos nostros, et qui oderunt nos diripiebant sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 12, 'Dedisti nos tamquam oves escarum, et in gentibus dispersisti nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 13, 'Vendidisti populum tuum sine pretio, et non fuit multitudo in commutationibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 14, 'Posuisti nos opprobrium vicinis nostris; subsannationem et derisum his qui sunt in circuitu nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 15, 'Posuisti nos in similitudinem gentibus; commotionem capitis in populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 16, 'Tota die verecundia mea contra me est, et confusio faciei meæ cooperuit me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 17, 'a voce exprobrantis et obloquentis, a facie inimici et persequentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 18, 'Hæc omnia venerunt super nos; nec obliti sumus te, et inique non egimus in testamento tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 19, 'Et non recessit retro cor nostrum; et declinasti semitas nostras a via tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 20, 'quoniam humiliasti nos in loco afflictionis, et cooperuit nos umbra mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 21, 'Si obliti sumus nomen Dei nostri, et si expandimus manus nostras ad deum alienum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 22, 'nonne Deus requiret ista? ipse enim novit abscondita cordis. Quoniam propter te mortificamur tota die; æstimati sumus sicut oves occisionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 23, 'Exsurge; quare obdormis, Domine? exsurge, et ne repellas in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 24, 'Quare faciem tuam avertis? oblivisceris inopiæ nostræ et tribulationis nostræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 25, 'Quoniam humiliata est in pulvere anima nostra; conglutinatus est in terra venter noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 43, 26, 'Exsurge, Domine, adjuva nos, et redime nos propter nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 1, 'In finem, pro iis qui commutabuntur. Filiis Core, ad intellectum. Canticum pro dilecto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 2, 'Eructavit cor meum verbum bonum: dico ego opera mea regi. Lingua mea calamus scribæ velociter scribentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 3, 'Speciosus forma præ filiis hominum, diffusa est gratia in labiis tuis: propterea benedixit te Deus in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 4, 'Accingere gladio tuo super femur tuum, potentissime.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 5, 'Specie tua et pulchritudine tua intende, prospere procede, et regna, propter veritatem, et mansuetudinem, et justitiam; et deducet te mirabiliter dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 6, 'Sagittæ tuæ acutæ: populi sub te cadent, in corda inimicorum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 7, 'Sedes tua, Deus, in sæculum sæculi; virga directionis virga regni tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 8, 'Dilexisti justitiam, et odisti iniquitatem; propterea unxit te Deus, Deus tuus, oleo lætitiæ, præ consortibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 9, 'Myrrha, et gutta, et casia a vestimentis tuis, a domibus eburneis; ex quibus delectaverunt te');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 10, 'filiæ regum in honore tuo. Astitit regina a dextris tuis in vestitu deaurato, circumdata varietate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 11, 'Audi, filia, et vide, et inclina aurem tuam; et obliviscere populum tuum, et domum patris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 12, 'Et concupiscet rex decorem tuum, quoniam ipse est Dominus Deus tuus, et adorabunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 13, 'Et filiæ Tyri in muneribus vultum tuum deprecabuntur; omnes divites plebis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 14, 'Omnis gloria ejus filiæ regis ab intus, in fimbriis aureis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 15, 'circumamicta varietatibus. Adducentur regi virgines post eam; proximæ ejus afferentur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 16, 'Afferentur in lætitia et exsultatione; adducentur in templum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 17, 'Pro patribus tuis nati sunt tibi filii; constitues eos principes super omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 44, 18, 'Memores erunt nominis tui in omni generatione et generationem: propterea populi confitebuntur tibi in æternum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 1, 'In finem, filiis Core, pro arcanis. Psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 2, 'Deus noster refugium et virtus; adjutor in tribulationibus quæ invenerunt nos nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 3, 'Propterea non timebimus dum turbabitur terra, et transferentur montes in cor maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 4, 'Sonuerunt, et turbatæ sunt aquæ eorum; conturbati sunt montes in fortitudine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 5, 'Fluminis impetus lætificat civitatem Dei: sanctificavit tabernaculum suum Altissimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 6, 'Deus in medio ejus, non commovebitur; adjuvabit eam Deus mane diluculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 7, 'Conturbatæ sunt gentes, et inclinata sunt regna: dedit vocem suam, mota est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 8, 'Dominus virtutum nobiscum; susceptor noster Deus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 9, 'Venite, et videte opera Domini, quæ posuit prodigia super terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 10, 'auferens bella usque ad finem terræ. Arcum conteret, et confringet arma, et scuta comburet igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 11, 'Vacate, et videte quoniam ego sum Deus; exaltabor in gentibus, et exaltabor in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 45, 12, 'Dominus virtutum nobiscum; susceptor noster Deus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 1, 'In finem, pro filiis Core. Psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 2, 'Omnes gentes, plaudite manibus; jubilate Deo in voce exsultationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 3, 'quoniam Dominus excelsus, terribilis, rex magnus super omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 4, 'Subjecit populos nobis, et gentes sub pedibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 5, 'Elegit nobis hæreditatem suam; speciem Jacob quam dilexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 6, 'Ascendit Deus in jubilo, et Dominus in voce tubæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 7, 'Psallite Deo nostro, psallite; psallite regi nostro, psallite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 8, 'quoniam rex omnis terræ Deus, psallite sapienter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 9, 'Regnabit Deus super gentes; Deus sedet super sedem sanctam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 46, 10, 'Principes populorum congregati sunt cum Deo Abraham, quoniam dii fortes terræ vehementer elevati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 1, 'Psalmus cantici. Filiis Core, secunda sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 2, 'Magnus Dominus et laudabilis nimis, in civitate Dei nostri, in monte sancto ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 3, 'Fundatur exsultatione universæ terræ mons Sion; latera aquilonis, civitas regis magni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 4, 'Deus in domibus ejus cognoscetur cum suscipiet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 5, 'Quoniam ecce reges terræ congregati sunt; convenerunt in unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 6, 'Ipsi videntes, sic admirati sunt, conturbati sunt, commoti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 7, 'Tremor apprehendit eos; ibi dolores ut parturientis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 8, 'in spiritu vehementi conteres naves Tharsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 9, 'Sicut audivimus, sic vidimus, in civitate Domini virtutum, in civitate Dei nostri: Deus fundavit eam in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 10, 'Suscepimus, Deus, misericordiam tuam in medio templi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 11, 'Secundum nomen tuum, Deus, sic et laus tua in fines terræ; justitia plena est dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 12, 'Lætetur mons Sion, et exsultent filiæ Judæ, propter judicia tua, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 13, 'Circumdate Sion, et complectimini eam; narrate in turribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 14, 'Ponite corda vestra in virtute ejus, et distribuite domos ejus, ut enarretis in progenie altera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 47, 15, 'Quoniam hic est Deus, Deus noster in æternum, et in sæculum sæculi: ipse reget nos in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 1, 'In finem, filiis Core. Psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 2, 'Audite hæc, omnes gentes; auribus percipite, omnes qui habitatis orbem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 3, 'quique terrigenæ et filii hominum, simul in unum dives et pauper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 4, 'Os meum loquetur sapientiam, et meditatio cordis mei prudentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 5, 'Inclinabo in parabolam aurem meam; aperiam in psalterio propositionem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 6, 'Cur timebo in die mala? iniquitas calcanei mei circumdabit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 7, 'Qui confidunt in virtute sua, et in multitudine divitiarum suarum, gloriantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 8, 'Frater non redimit, redimet homo: non dabit Deo placationem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 9, 'et pretium redemptionis animæ suæ. Et laborabit in æternum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 10, 'et vivet adhuc in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 11, 'Non videbit interitum, cum viderit sapientes morientes: simul insipiens et stultus peribunt. Et relinquent alienis divitias suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 12, 'et sepulchra eorum domus illorum in æternum; tabernacula eorum in progenie et progenie: vocaverunt nomina sua in terris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 13, 'Et homo, cum in honore esset, non intellexit. Comparatus est jumentis insipientibus, et similis factus est illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 14, 'Hæc via illorum scandalum ipsis; et postea in ore suo complacebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 15, 'Sicut oves in inferno positi sunt: mors depascet eos. Et dominabuntur eorum justi in matutino; et auxilium eorum veterascet in inferno a gloria eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 16, 'Verumtamen Deus redimet animam meam de manu inferi, cum acceperit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 17, 'Ne timueris cum dives factus fuerit homo, et cum multiplicata fuerit gloria domus ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 18, 'quoniam, cum interierit, non sumet omnia, neque descendet cum eo gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 19, 'Quia anima ejus in vita ipsius benedicetur; confitebitur tibi cum benefeceris ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 20, 'Introibit usque in progenies patrum suorum; et usque in æternum non videbit lumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 48, 21, 'Homo, cum in honore esset, non intellexit. Comparatus est jumentis insipientibus, et similis factus est illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 1, 'Psalmus Asaph. Deus deorum Dominus locutus est, et vocavit terram a solis ortu usque ad occasum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 2, 'Ex Sion species decoris ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 3, 'Deus manifeste veniet; Deus noster, et non silebit. Ignis in conspectu ejus exardescet; et in circuitu ejus tempestas valida.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 4, 'Advocabit cælum desursum, et terram, discernere populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 5, 'Congregate illi sanctos ejus, qui ordinant testamentum ejus super sacrificia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 6, 'Et annuntiabunt cæli justitiam ejus, quoniam Deus judex est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 7, 'Audi, populus meus, et loquar; Israël, et testificabor tibi: Deus, Deus tuus ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 8, 'Non in sacrificiis tuis arguam te; holocausta autem tua in conspectu meo sunt semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 9, 'Non accipiam de domo tua vitulos, neque de gregibus tuis hircos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 10, 'quoniam meæ sunt omnes feræ silvarum, jumenta in montibus, et boves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 11, 'Cognovi omnia volatilia cæli, et pulchritudo agri mecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 12, 'Si esuriero, non dicam tibi: meus est enim orbis terræ et plenitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 13, 'Numquid manducabo carnes taurorum? aut sanguinem hircorum potabo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 14, 'Immola Deo sacrificium laudis, et redde Altissimo vota tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 15, 'Et invoca me in die tribulationis: eruam te, et honorificabis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 16, 'Peccatori autem dixit Deus: Quare tu enarras justitias meas? et assumis testamentum meum per os tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 17, 'Tu vero odisti disciplinam, et projecisti sermones meos retrorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 18, 'Si videbas furem, currebas cum eo; et cum adulteris portionem tuam ponebas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 19, 'Os tuum abundavit malitia, et lingua tua concinnabat dolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 20, 'Sedens adversus fratrem tuum loquebaris, et adversus filium matris tuæ ponebas scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 21, 'Hæc fecisti, et tacui. Existimasti inique quod ero tui similis: arguam te, et statuam contra faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 22, 'Intelligite hæc, qui obliviscimini Deum, nequando rapiat, et non sit qui eripiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 49, 23, 'Sacrificium laudis honorificabit me, et illic iter quo ostendam illi salutare Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 1, 'In finem. Psalmus David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 2, 'cum venit ad eum Nathan propheta, quando intravit ad Bethsabee.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 3, 'Miserere mei, Deus, secundum magnam misericordiam tuam; et secundum multitudinem miserationum tuarum, dele iniquitatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 4, 'Amplius lava me ab iniquitate mea, et a peccato meo munda me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 5, 'Quoniam iniquitatem meam ego cognosco, et peccatum meum contra me est semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 6, 'Tibi soli peccavi, et malum coram te feci; ut justificeris in sermonibus tuis, et vincas cum judicaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 7, 'Ecce enim in iniquitatibus conceptus sum, et in peccatis concepit me mater mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 8, 'Ecce enim veritatem dilexisti; incerta et occulta sapientiæ tuæ manifestasti mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 9, 'Asperges me hyssopo, et mundabor; lavabis me, et super nivem dealbabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 10, 'Auditui meo dabis gaudium et lætitiam, et exsultabunt ossa humiliata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 11, 'Averte faciem tuam a peccatis meis, et omnes iniquitates meas dele.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 12, 'Cor mundum crea in me, Deus, et spiritum rectum innova in visceribus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 13, 'Ne projicias me a facie tua, et spiritum sanctum tuum ne auferas a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 14, 'Redde mihi lætitiam salutaris tui, et spiritu principali confirma me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 15, 'Docebo iniquos vias tuas, et impii ad te convertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 16, 'Libera me de sanguinibus, Deus, Deus salutis meæ, et exsultabit lingua mea justitiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 17, 'Domine, labia mea aperies, et os meum annuntiabit laudem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 18, 'Quoniam si voluisses sacrificium, dedissem utique; holocaustis non delectaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 19, 'Sacrificium Deo spiritus contribulatus; cor contritum et humiliatum, Deus, non despicies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 20, 'Benigne fac, Domine, in bona voluntate tua Sion, ut ædificentur muri Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 50, 21, 'Tunc acceptabis sacrificium justitiæ, oblationes et holocausta; tunc imponent super altare tuum vitulos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 1, 'In finem. Intellectus David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 2, 'cum venit Doëg Idumæus, et nuntiavit Sauli: Venit David in domum Achimelech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 3, 'Quid gloriaris in malitia, qui potens es in iniquitate?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 4, 'Tota die injustitiam cogitavit lingua tua; sicut novacula acuta fecisti dolum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 5, 'Dilexisti malitiam super benignitatem; iniquitatem magis quam loqui æquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 6, 'Dilexisti omnia verba præcipitationis; lingua dolosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 7, 'Propterea Deus destruet te in finem; evellet te, et emigrabit te de tabernaculo tuo, et radicem tuam de terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 8, 'Videbunt justi, et timebunt; et super eum ridebunt, et dicent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 9, 'Ecce homo qui non posuit Deum adjutorem suum; sed speravit in multitudine divitiarum suarum, et prævaluit in vanitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 10, 'Ego autem, sicut oliva fructifera in domo Dei; speravi in misericordia Dei, in æternum et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 51, 11, 'Confitebor tibi in sæculum, quia fecisti; et exspectabo nomen tuum, quoniam bonum est in conspectu sanctorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 1, 'In finem, pro Maëleth intelligentiæ David. Dixit insipiens in corde suo: Non est Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 2, 'Corrupti sunt, et abominabiles facti sunt in iniquitatibus; non est qui faciat bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 3, 'Deus de cælo prospexit super filios hominum, ut videat si est intelligens, aut requirens Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 4, 'Omnes declinaverunt; simul inutiles facti sunt: non est qui faciat bonum, non est usque ad unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 5, 'Nonne scient omnes qui operantur iniquitatem, qui devorant plebem meam ut cibum panis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 6, 'Deum non invocaverunt; illic trepidaverunt timore, ubi non erat timor. Quoniam Deus dissipavit ossa eorum qui hominibus placent: confusi sunt, quoniam Deus sprevit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 52, 7, 'Quis dabit ex Sion salutare Israël? cum converterit Deus captivitatem plebis suæ, exsultabit Jacob, et lætabitur Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 1, 'In finem, in carminibus. Intellectus David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 2, 'cum venissent Ziphæi, et dixissent ad Saul: Nonne David absconditus est apud nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 3, 'Deus, in nomine tuo salvum me fac, et in virtute tua judica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 4, 'Deus, exaudi orationem meam; auribus percipe verba oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 5, 'Quoniam alieni insurrexerunt adversum me, et fortes quæsierunt animam meam, et non proposuerunt Deum ante conspectum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 6, 'Ecce enim Deus adjuvat me, et Dominus susceptor est animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 7, 'Averte mala inimicis meis; et in veritate tua disperde illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 8, 'Voluntarie sacrificabo tibi, et confitebor nomini tuo, Domine, quoniam bonum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 53, 9, 'Quoniam ex omni tribulatione eripuisti me, et super inimicos meos despexit oculus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 1, 'In finem, in carminibus. Intellectus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 2, 'Exaudi, Deus, orationem meam, et ne despexeris deprecationem meam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 3, 'intende mihi, et exaudi me. Contristatus sum in exercitatione mea, et conturbatus sum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 4, 'a voce inimici, et a tribulatione peccatoris. Quoniam declinaverunt in me iniquitates, et in ira molesti erant mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 5, 'Cor meum conturbatum est in me, et formido mortis cecidit super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 6, 'Timor et tremor venerunt super me, et contexerunt me tenebræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 7, 'Et dixi: Quis dabit mihi pennas sicut columbæ, et volabo, et requiescam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 8, 'Ecce elongavi fugiens, et mansi in solitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 9, 'Exspectabam eum qui salvum me fecit a pusillanimitate spiritus, et tempestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 10, 'Præcipita, Domine; divide linguas eorum: quoniam vidi iniquitatem et contradictionem in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 11, 'Die ac nocte circumdabit eam super muros ejus iniquitas; et labor in medio ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 12, 'et injustitia: et non defecit de plateis ejus usura et dolus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 13, 'Quoniam si inimicus meus maledixisset mihi, sustinuissem utique. Et si is qui oderat me super me magna locutus fuisset, abscondissem me forsitan ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 14, 'Tu vero homo unanimis, dux meus, et notus meus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 15, 'qui simul mecum dulces capiebas cibos; in domo Dei ambulavimus cum consensu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 16, 'Veniat mors super illos, et descendant in infernum viventes: quoniam nequitiæ in habitaculis eorum, in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 17, 'Ego autem ad Deum clamavi, et Dominus salvabit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 18, 'Vespere, et mane, et meridie, narrabo, et annuntiabo; et exaudiet vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 19, 'Redimet in pace animam meam ab his qui appropinquant mihi: quoniam inter multos erant mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 20, 'Exaudiet Deus, et humiliabit illos, qui est ante sæcula. Non enim est illis commutatio, et non timuerunt Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 21, 'Extendit manum suam in retribuendo; contaminaverunt testamentum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 22, 'divisi sunt ab ira vultus ejus, et appropinquavit cor illius. Molliti sunt sermones ejus super oleum; et ipsi sunt jacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 23, 'Jacta super Dominum curam tuam, et ipse te enutriet; non dabit in æternum fluctuationem justo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 54, 24, 'Tu vero, Deus, deduces eos in puteum interitus. Viri sanguinum et dolosi non dimidiabunt dies suos; ego autem sperabo in te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 1, 'In finem, pro populo qui a sanctis longe factus est. David in tituli inscriptionem, cum tenuerunt eum Allophyli in Geth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 2, 'Miserere mei, Deus, quoniam conculcavit me homo; tota die impugnans, tribulavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 3, 'Conculcaverunt me inimici mei tota die, quoniam multi bellantes adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 4, 'Ab altitudine diei timebo: ego vero in te sperabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 5, 'In Deo laudabo sermones meos; in Deo speravi: non timebo quid faciat mihi caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 6, 'Tota die verba mea execrabantur; adversum me omnes cogitationes eorum in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 7, 'Inhabitabunt, et abscondent; ipsi calcaneum meum observabunt. Sicut sustinuerunt animam meam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 8, 'pro nihilo salvos facies illos; in ira populos confringes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 9, 'Deus, vitam meam annuntiavi tibi; posuisti lacrimas meas in conspectu tuo, sicut et in promissione tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 10, 'tunc convertentur inimici mei retrorsum. In quacumque die invocavero te, ecce cognovi quoniam Deus meus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 11, 'In Deo laudabo verbum; in Domino laudabo sermonem. In Deo speravi: non timebo quid faciat mihi homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 12, 'In me sunt, Deus, vota tua, quæ reddam, laudationes tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 55, 13, 'quoniam eripuisti animam meam de morte, et pedes meos de lapsu, ut placeam coram Deo in lumine viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 1, 'In finem, ne disperdas. David in tituli inscriptionem, cum fugeret a facie Saul in speluncam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 2, 'Miserere mei, Deus, miserere mei, quoniam in te confidit anima mea. Et in umbra alarum tuarum sperabo, donec transeat iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 3, 'Clamabo ad Deum altissimum, Deum qui benefecit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 4, 'Misit de cælo, et liberavit me; dedit in opprobrium conculcantes me. Misit Deus misericordiam suam et veritatem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 5, 'et eripuit animam meam de medio catulorum leonum. Dormivi conturbatus. Filii hominum dentes eorum arma et sagittæ, et lingua eorum gladius acutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 6, 'Exaltare super cælos, Deus, et in omnem terram gloria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 7, 'Laqueum paraverunt pedibus meis, et incurvaverunt animam meam. Foderunt ante faciem meam foveam, et inciderunt in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 8, 'Paratum cor meum, Deus, paratum cor meum; cantabo, et psalmum dicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 9, 'Exsurge, gloria mea; exsurge, psalterium et cithara: exsurgam diluculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 10, 'Confitebor tibi in populis, Domine, et psalmum dicam tibi in gentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 11, 'quoniam magnificata est usque ad cælos misericordia tua, et usque ad nubes veritas tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 56, 12, 'Exaltare super cælos, Deus, et super omnem terram gloria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 1, 'In finem, ne disperdas. David in tituli inscriptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 2, 'Si vere utique justitiam loquimini, recta judicate, filii hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 3, 'Etenim in corde iniquitates operamini; in terra injustitias manus vestræ concinnant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 4, 'Alienati sunt peccatores a vulva; erraverunt ab utero: locuti sunt falsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 5, 'Furor illis secundum similitudinem serpentis, sicut aspidis surdæ et obturantis aures suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 6, 'quæ non exaudiet vocem incantantium, et venefici incantantis sapienter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 7, 'Deus conteret dentes eorum in ore ipsorum; molas leonum confringet Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 8, 'Ad nihilum devenient tamquam aqua decurrens; intendit arcum suum donec infirmentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 9, 'Sicut cera quæ fluit auferentur; supercecidit ignis, et non viderunt solem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 10, 'Priusquam intelligerent spinæ vestræ rhamnum, sicut viventes sic in ira absorbet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 11, 'Lætabitur justus cum viderit vindictam; manus suas lavabit in sanguine peccatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 57, 12, 'Et dicet homo: Si utique est fructus justo, utique est Deus judicans eos in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 1, 'In finem, ne disperdas. David in tituli inscriptionem, quando misit Saul et custodivit domum ejus ut eum interficeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 2, 'Eripe me de inimicis meis, Deus meus, et ab insurgentibus in me libera me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 3, 'Eripe me de operantibus iniquitatem, et de viris sanguinum salva me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 4, 'Quia ecce ceperunt animam meam; irruerunt in me fortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 5, 'Neque iniquitas mea, neque peccatum meum, Domine; sine iniquitate cucurri, et direxi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 6, 'Exsurge in occursum meum, et vide: et tu, Domine Deus virtutum, Deus Israël, intende ad visitandas omnes gentes: non miserearis omnibus qui operantur iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 7, 'Convertentur ad vesperam, et famem patientur ut canes: et circuibunt civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 8, 'Ecce loquentur in ore suo, et gladius in labiis eorum: quoniam quis audivit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 9, 'Et tu, Domine, deridebis eos; ad nihilum deduces omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 10, 'Fortitudinem meam ad te custodiam, quia, Deus, susceptor meus es:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 11, 'Deus meus misericordia ejus præveniet me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 12, 'Deus ostendet mihi super inimicos meos: ne occidas eos, nequando obliviscantur populi mei. Disperge illos in virtute tua, et depone eos, protector meus, Domine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 13, 'delictum oris eorum, sermonem labiorum ipsorum; et comprehendantur in superbia sua. Et de execratione et mendacio annuntiabuntur');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 14, 'in consummatione: in ira consummationis, et non erunt. Et scient quia Deus dominabitur Jacob, et finium terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 15, 'Convertentur ad vesperam, et famem patientur ut canes: et circuibunt civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 16, 'Ipsi dispergentur ad manducandum; si vero non fuerint saturati, et murmurabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 17, 'Ego autem cantabo fortitudinem tuam, et exsultabo mane misericordiam tuam: quia factus es susceptor meus, et refugium meum in die tribulationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 58, 18, 'Adjutor meus, tibi psallam, quia Deus susceptor meus es; Deus meus, misericordia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 1, 'In finem, pro his qui immutabuntur, in tituli inscriptionem ipsi David, in doctrinam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 2, 'cum succendit Mesopotamiam Syriæ et Sobal, et convertit Joab, et percussit Idumæam in valle Salinarum duodecim millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 3, 'Deus, repulisti nos, et destruxisti nos; iratus es, et misertus es nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 4, 'Commovisti terram, et conturbasti eam; sana contritiones ejus, quia commota est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 5, 'Ostendisti populo tuo dura; potasti nos vino compunctionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 6, 'Dedisti metuentibus te significationem, ut fugiant a facie arcus; ut liberentur dilecti tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 7, 'Salvum fac dextera tua, et exaudi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 8, 'Deus locutus est in sancto suo: lætabor, et partibor Sichimam; et convallem tabernaculorum metibor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 9, 'Meus est Galaad, et meus est Manasses; et Ephraim fortitudo capitis mei. Juda rex meus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 10, 'Moab olla spei meæ. In Idumæam extendam calceamentum meum: mihi alienigenæ subditi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 11, 'Quis deducet me in civitatem munitam? quis deducet me usque in Idumæam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 12, 'nonne tu, Deus, qui repulisti nos? et non egredieris, Deus, in virtutibus nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 13, 'Da nobis auxilium de tribulatione, quia vana salus hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 59, 14, 'In Deo faciemus virtutem; et ipse ad nihilum deducet tribulantes nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 1, 'In finem. In hymnis David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 2, 'Exaudi, Deus, deprecationem meam; intende orationi meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 3, 'A finibus terræ ad te clamavi, dum anxiaretur cor meum; in petra exaltasti me. Deduxisti me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 4, 'quia factus es spes mea: turris fortitudinis a facie inimici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 5, 'Inhabitabo in tabernaculo tuo in sæcula; protegar in velamento alarum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 6, 'Quoniam tu, Deus meus, exaudisti orationem meam; dedisti hæreditatem timentibus nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 7, 'Dies super dies regis adjicies; annos ejus usque in diem generationis et generationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 8, 'Permanet in æternum in conspectu Dei: misericordiam et veritatem ejus quis requiret?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 60, 9, 'Sic psalmum dicam nomini tuo in sæculum sæculi, ut reddam vota mea de die in diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 1, 'In finem, pro Idithun. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 2, 'Nonne Deo subjecta erit anima mea? ab ipso enim salutare meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 3, 'Nam et ipse Deus meus et salutaris meus; susceptor meus, non movebor amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 4, 'Quousque irruitis in hominem? interficitis universi vos, tamquam parieti inclinato et maceriæ depulsæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 5, 'Verumtamen pretium meum cogitaverunt repellere; cucurri in siti: ore suo benedicebant, et corde suo maledicebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 6, 'Verumtamen Deo subjecta esto, anima mea, quoniam ab ipso patientia mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 7, 'quia ipse Deus meus et salvator meus, adjutor meus, non emigrabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 8, 'In Deo salutare meum et gloria mea; Deus auxilii mei, et spes mea in Deo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 9, 'Sperate in eo, omnis congregatio populi; effundite coram illo corda vestra: Deus adjutor noster in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 10, 'Verumtamen vani filii hominum, mendaces filii hominum in stateris, ut decipiant ipsi de vanitate in idipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 11, 'Nolite sperare in iniquitate, et rapinas nolite concupiscere; divitiæ si affluant, nolite cor apponere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 12, 'Semel locutus est Deus; duo hæc audivi: quia potestas Dei est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 61, 13, 'et tibi, Domine, misericordia: quia tu reddes unicuique juxta opera sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 1, 'Psalmus David, cum esset in deserto Idumææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 2, 'Deus, Deus meus, ad te de luce vigilo. Sitivit in te anima mea; quam multipliciter tibi caro mea!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 3, 'In terra deserta, et invia, et inaquosa, sic in sancto apparui tibi, ut viderem virtutem tuam et gloriam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 4, 'Quoniam melior est misericordia tua super vitas, labia mea laudabunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 5, 'Sic benedicam te in vita mea, et in nomine tuo levabo manus meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 6, 'Sicut adipe et pinguedine repleatur anima mea, et labiis exsultationis laudabit os meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 7, 'Si memor fui tui super stratum meum, in matutinis meditabor in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 8, 'Quia fuisti adjutor meus, et in velamento alarum tuarum exsultabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 9, 'Adhæsit anima mea post te; me suscepit dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 10, 'Ipsi vero in vanum quæsierunt animam meam: introibunt in inferiora terræ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 11, 'tradentur in manus gladii: partes vulpium erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 62, 12, 'Rex vero lætabitur in Deo; laudabuntur omnes qui jurant in eo: quia obstructum est os loquentium iniqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 2, 'Exaudi, Deus, orationem meam cum deprecor; a timore inimici eripe animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 3, 'Protexisti me a conventu malignantium, a multitudine operantium iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 4, 'Quia exacuerunt ut gladium linguas suas; intenderunt arcum rem amaram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 5, 'ut sagittent in occultis immaculatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 6, 'Subito sagittabunt eum, et non timebunt; firmaverunt sibi sermonem nequam. Narraverunt ut absconderent laqueos; dixerunt: Quis videbit eos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 7, 'Scrutati sunt iniquitates; defecerunt scrutantes scrutinio. Accedet homo ad cor altum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 8, 'et exaltabitur Deus. Sagittæ parvulorum factæ sunt plagæ eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 9, 'et infirmatæ sunt contra eos linguæ eorum. Conturbati sunt omnes qui videbant eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 10, 'et timuit omnis homo. Et annuntiaverunt opera Dei, et facta ejus intellexerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 63, 11, 'Lætabitur justus in Domino, et sperabit in eo, et laudabuntur omnes recti corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 1, 'In finem. Psalmus David, canticum Jeremiæ et Ezechielis populo transmigrationis, cum inciperent exire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 2, 'Te decet hymnus, Deus, in Sion, et tibi reddetur votum in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 3, 'Exaudi orationem meam; ad te omnis caro veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 4, 'Verba iniquorum prævaluerunt super nos, et impietatibus nostris tu propitiaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 5, 'Beatus quem elegisti et assumpsisti: inhabitabit in atriis tuis. Replebimur in bonis domus tuæ; sanctum est templum tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 6, 'mirabile in æquitate. Exaudi nos, Deus, salutaris noster, spes omnium finium terræ, et in mari longe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 7, 'Præparans montes in virtute tua, accinctus potentia;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 8, 'qui conturbas profundum maris, sonum fluctuum ejus. Turbabuntur gentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 9, 'et timebunt qui habitant terminos a signis tuis; exitus matutini et vespere delectabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 10, 'Visitasti terram, et inebriasti eam; multiplicasti locupletare eam. Flumen Dei repletum est aquis; parasti cibum illorum: quoniam ita est præparatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 11, 'Rivos ejus inebria; multiplica genimina ejus: in stillicidiis ejus lætabitur germinans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 12, 'Benedices coronæ anni benignitatis tuæ, et campi tui replebuntur ubertate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 13, 'Pinguescent speciosa deserti, et exsultatione colles accingentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 64, 14, 'Induti sunt arietes ovium, et valles abundabunt frumento; clamabunt, etenim hymnum dicent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 1, 'In finem. Canticum psalmi resurrectionis. Jubilate Deo, omnis terra;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 2, 'psalmum dicite nomini ejus; date gloriam laudi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 3, 'Dicite Deo: Quam terribilia sunt opera tua, Domine! in multitudine virtutis tuæ mentientur tibi inimici tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 4, 'Omnis terra adoret te, et psallat tibi; psalmum dicat nomini tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 5, 'Venite, et videte opera Dei: terribilis in consiliis super filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 6, 'Qui convertit mare in aridam; in flumine pertransibunt pede: ibi lætabimur in ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 7, 'Qui dominatur in virtute sua in æternum; oculi ejus super gentes respiciunt: qui exasperant non exaltentur in semetipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 8, 'Benedicite, gentes, Deum nostrum, et auditam facite vocem laudis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 9, 'qui posuit animam meam ad vitam, et non dedit in commotionem pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 10, 'Quoniam probasti nos, Deus; igne nos examinasti, sicut examinatur argentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 11, 'Induxisti nos in laqueum; posuisti tribulationes in dorso nostro;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 12, 'imposuisti homines super capita nostra. Transivimus per ignem et aquam, et eduxisti nos in refrigerium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 13, 'Introibo in domum tuam in holocaustis; reddam tibi vota mea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 14, 'quæ distinxerunt labia mea: et locutum est os meum in tribulatione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 15, 'Holocausta medullata offeram tibi, cum incenso arietum; offeram tibi boves cum hircis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 16, 'Venite, audite, et narrabo, omnes qui timetis Deum, quanta fecit animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 17, 'Ad ipsum ore meo clamavi, et exaltavi sub lingua mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 18, 'Iniquitatem si aspexi in corde meo, non exaudiet Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 19, 'Propterea exaudivit Deus, et attendit voci deprecationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 65, 20, 'Benedictus Deus, qui non amovit orationem meam, et misericordiam suam a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 1, 'In finem, in hymnis. Psalmus cantici David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 2, 'Deus misereatur nostri, et benedicat nobis; illuminet vultum suum super nos, et misereatur nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 3, 'ut cognoscamus in terra viam tuam, in omnibus gentibus salutare tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 4, 'Confiteantur tibi populi, Deus: confiteantur tibi populi omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 5, 'Lætentur et exsultent gentes, quoniam judicas populos in æquitate, et gentes in terra dirigis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 6, 'Confiteantur tibi populi, Deus: confiteantur tibi populi omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 7, 'Terra dedit fructum suum: benedicat nos Deus, Deus noster!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 66, 8, 'Benedicat nos Deus, et metuant eum omnes fines terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 1, 'In finem. Psalmus cantici ipsi David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 2, 'Exsurgat Deus, et dissipentur inimici ejus; et fugiant qui oderunt eum a facie ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 3, 'Sicut deficit fumus, deficiant; sicut fluit cera a facie ignis, sic pereant peccatores a facie Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 4, 'Et justi epulentur, et exsultent in conspectu Dei, et delectentur in lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 5, 'Cantate Deo; psalmum dicite nomini ejus: iter facite ei qui ascendit super occasum. Dominus nomen illi; exsultate in conspectu ejus. Turbabuntur a facie ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 6, 'patris orphanorum, et judicis viduarum; Deus in loco sancto suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 7, 'Deus qui inhabitare facit unius moris in domo; qui educit vinctos in fortitudine, similiter eos qui exasperant, qui habitant in sepulchris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 8, 'Deus, cum egredereris in conspectu populi tui, cum pertransires in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 9, 'terra mota est, etenim cæli distillaverunt, a facie Dei Sinai, a facie Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 10, 'Pluviam voluntariam segregabis, Deus, hæreditati tuæ; et infirmata est, tu vero perfecisti eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 11, 'Animalia tua habitabunt in ea; parasti in dulcedine tua pauperi, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 12, 'Dominus dabit verbum evangelizantibus, virtute multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 13, 'Rex virtutum dilecti, dilecti; et speciei domus dividere spolia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 14, 'Si dormiatis inter medios cleros, pennæ columbæ deargentatæ, et posteriora dorsi ejus in pallore auri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 15, 'Dum discernit cælestis reges super eam, nive dealbabuntur in Selmon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 16, 'Mons Dei, mons pinguis: mons coagulatus, mons pinguis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 17, 'Ut quid suspicamini, montes coagulatos? mons in quo beneplacitum est Deo habitare in eo; etenim Dominus habitabit in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 18, 'Currus Dei decem millibus multiplex, millia lætantium; Dominus in eis in Sina, in sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 19, 'Ascendisti in altum, cepisti captivitatem, accepisti dona in hominibus; etenim non credentes inhabitare Dominum Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 20, 'Benedictus Dominus die quotidie: prosperum iter faciet nobis Deus salutarium nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 21, 'Deus noster, Deus salvos faciendi; et Domini, Domini exitus mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 22, 'Verumtamen Deus confringet capita inimicorum suorum, verticem capilli perambulantium in delictis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 23, 'Dixit Dominus: Ex Basan convertam, convertam in profundum maris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 24, 'ut intingatur pes tuus in sanguine; lingua canum tuorum ex inimicis, ab ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 25, 'Viderunt ingressus tuos, Deus, ingressus Dei mei, regis mei, qui est in sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 26, 'Prævenerunt principes conjuncti psallentibus, in medio juvencularum tympanistriarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 27, 'In ecclesiis benedicite Deo Domino de fontibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 28, 'Ibi Benjamin adolescentulus, in mentis excessu; principes Juda, duces eorum; principes Zabulon, principes Nephthali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 29, 'Manda, Deus, virtuti tuæ; confirma hoc, Deus, quod operatus es in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 30, 'A templo tuo in Jerusalem, tibi offerent reges munera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 31, 'Increpa feras arundinis; congregatio taurorum in vaccis populorum: ut excludant eos qui probati sunt argento. Dissipa gentes quæ bella volunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 32, 'Venient legati ex \'gypto; \'thiopia præveniet manus ejus Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 33, 'Regna terræ, cantate Deo; psallite Domino; psallite Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 34, 'Qui ascendit super cælum cæli, ad orientem: ecce dabit voci suæ vocem virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 35, 'Date gloriam Deo super Israël; magnificentia ejus et virtus ejus in nubibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 67, 36, 'Mirabilis Deus in sanctis suis; Deus Israël ipse dabit virtutem et fortitudinem plebi suæ. Benedictus Deus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 1, 'In finem, pro iis qui commutabuntur. David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 2, 'Salvum me fac, Deus, quoniam intraverunt aquæ usque ad animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 3, 'Infixus sum in limo profundi et non est substantia. Veni in altitudinem maris, et tempestas demersit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 4, 'Laboravi clamans, raucæ factæ sunt fauces meæ; defecerunt oculi mei, dum spero in Deum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 5, 'Multiplicati sunt super capillos capitis mei qui oderunt me gratis. Confortati sunt qui persecuti sunt me inimici mei injuste; quæ non rapui, tunc exsolvebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 6, 'Deus, tu scis insipientiam meam; et delicta mea a te non sunt abscondita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 7, 'Non erubescant in me qui exspectant te, Domine, Domine virtutum; non confundantur super me qui quærunt te, Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 8, 'Quoniam propter te sustinui opprobrium; operuit confusio faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 9, 'Extraneus factus sum fratribus meis, et peregrinus filiis matris meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 10, 'Quoniam zelus domus tuæ comedit me, et opprobria exprobrantium tibi ceciderunt super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 11, 'Et operui in jejunio animam meam, et factum est in opprobrium mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 12, 'Et posui vestimentum meum cilicium; et factus sum illis in parabolam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 13, 'Adversum me loquebantur qui sedebant in porta, et in me psallebant qui bibebant vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 14, 'Ego vero orationem meam ad te, Domine; tempus beneplaciti, Deus. In multitudine misericordiæ tuæ, exaudi me in veritate salutis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 15, 'Eripe me de luto, ut non infigar; libera me ab iis qui oderunt me, et de profundis aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 16, 'Non me demergat tempestas aquæ, neque absorbeat me profundum, neque urgeat super me puteus os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 17, 'Exaudi me, Domine, quoniam benigna est misericordia tua; secundum multitudinem miserationum tuarum respice in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 18, 'Et ne avertas faciem tuam a puero tuo; quoniam tribulor, velociter exaudi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 19, 'Intende animæ meæ, et libera eam; propter inimicos meos, eripe me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 20, 'Tu scis improperium meum, et confusionem meam, et reverentiam meam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 21, 'in conspectu tuo sunt omnes qui tribulant me. Improperium exspectavit cor meum et miseriam: et sustinui qui simul contristaretur, et non fuit; et qui consolaretur, et non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 22, 'Et dederunt in escam meam fel, et in siti mea potaverunt me aceto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 23, 'Fiat mensa eorum coram ipsis in laqueum, et in retributiones, et in scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 24, 'Obscurentur oculi eorum, ne videant, et dorsum eorum semper incurva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 25, 'Effunde super eos iram tuam, et furor iræ tuæ comprehendat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 26, 'Fiat habitatio eorum deserta, et in tabernaculis eorum non sit qui inhabitet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 27, 'Quoniam quem tu percussisti persecuti sunt, et super dolorem vulnerum meorum addiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 28, 'Appone iniquitatem super iniquitatem eorum, et non intrent in justitiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 29, 'Deleantur de libro viventium, et cum justis non scribantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 30, 'Ego sum pauper et dolens; salus tua, Deus, suscepit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 31, 'Laudabo nomen Dei cum cantico, et magnificabo eum in laude:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 32, 'et placebit Deo super vitulum novellum, cornua producentem et ungulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 33, 'Videant pauperes, et lætentur; quærite Deum, et vivet anima vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 34, 'quoniam exaudivit pauperes Dominus, et vinctos suos non despexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 35, 'Laudent illum cæli et terra; mare, et omnia reptilia in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 36, 'Quoniam Deus salvam faciet Sion, et ædificabuntur civitates Juda, et inhabitabunt ibi, et hæreditate acquirent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 68, 37, 'Et semen servorum ejus possidebit eam; et qui diligunt nomen ejus habitabunt in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 1, 'In finem. Psalmus David in rememorationem, quod salvum fecerit eum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 2, 'Deus, in adjutorium meum intende; Domine, ad adjuvandum me festina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 3, 'Confundantur, et revereantur, qui quærunt animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 4, 'Avertantur retrorsum, et erubescant, qui volunt mihi mala; avertantur statim erubescentes qui dicunt mihi: Euge, euge!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 5, 'Exsultent et lætentur in te omnes qui quærunt te; et dicant semper: Magnificetur Dominus, qui diligunt salutare tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 69, 6, 'Ego vero egenus et pauper sum; Deus, adjuva me. Adjutor meus et liberator meus es tu; Domine, ne moreris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 1, 'Psalmus David, filiorum Jonadab, et priorum captivorum. In te, Domine, speravi; non confundar in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 2, 'In justitia tua libera me, et eripe me: inclina ad me aurem tuam, et salva me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 3, 'Esto mihi in Deum protectorem, et in locum munitum, ut salvum me facias: quoniam firmamentum meum et refugium meum es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 4, 'Deus meus, eripe me de manu peccatoris, et de manu contra legem agentis, et iniqui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 5, 'quoniam tu es patientia mea, Domine; Domine, spes mea a juventute mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 6, 'In te confirmatus sum ex utero; de ventre matris meæ tu es protector meus; in te cantatio mea semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 7, 'Tamquam prodigium factus sum multis; et tu adjutor fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 8, 'Repleatur os meum laude, ut cantem gloriam tuam, tota die magnitudinem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 9, 'Ne projicias me in tempore senectutis; cum defecerit virtus mea, ne derelinquas me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 10, 'Quia dixerunt inimici mei mihi, et qui custodiebant animam meam consilium fecerunt in unum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 11, 'dicentes: Deus dereliquit eum: persequimini et comprehendite eum, quia non est qui eripiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 12, 'Deus, ne elongeris a me; Deus meus, in auxilium meum respice.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 13, 'Confundantur et deficiant detrahentes animæ meæ; operiantur confusione et pudore qui quærunt mala mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 14, 'Ego autem semper sperabo, et adjiciam super omnem laudem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 15, 'Os meum annuntiabit justitiam tuam, tota die salutare tuum. Quoniam non cognovi litteraturam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 16, 'introibo in potentias Domini; Domine, memorabor justitiæ tuæ solius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 17, 'Deus, docuisti me a juventute mea; et usque nunc pronuntiabo mirabilia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 18, 'Et usque in senectam et senium, Deus, ne derelinquas me, donec annuntiem brachium tuum generationi omni quæ ventura est, potentiam tuam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 19, 'et justitiam tuam, Deus, usque in altissima; quæ fecisti magnalia, Deus: quis similis tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 20, 'Quantas ostendisti mihi tribulationes multas et malas! et conversus vivificasti me, et de abyssis terræ iterum reduxisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 21, 'Multiplicasti magnificentiam tuam; et conversus consolatus es me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 22, 'Nam et ego confitebor tibi in vasis psalmi veritatem tuam, Deus; psallam tibi in cithara, sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 23, 'Exsultabunt labia mea cum cantavero tibi; et anima mea quam redemisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 70, 24, 'Sed et lingua mea tota die meditabitur justitiam tuam, cum confusi et reveriti fuerint qui quærunt mala mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 1, 'Psalmus, in Salomonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 2, 'Deus, judicium tuum regi da, et justitiam tuam filio regis; judicare populum tuum in justitia, et pauperes tuos in judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 3, 'Suscipiant montes pacem populo, et colles justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 4, 'Judicabit pauperes populi, et salvos faciet filios pauperum, et humiliabit calumniatorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 5, 'Et permanebit cum sole, et ante lunam, in generatione et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 6, 'Descendet sicut pluvia in vellus, et sicut stillicidia stillantia super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 7, 'Orietur in diebus ejus justitia, et abundantia pacis, donec auferatur luna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 8, 'Et dominabitur a mari usque ad mare, et a flumine usque ad terminos orbis terrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 9, 'Coram illo procident \'thiopes, et inimici ejus terram lingent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 10, 'Reges Tharsis et insulæ munera offerent; reges Arabum et Saba dona adducent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 11, 'et adorabunt eum omnes reges terræ; omnes gentes servient ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 12, 'Quia liberabit pauperem a potente, et pauperem cui non erat adjutor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 13, 'Parcet pauperi et inopi, et animas pauperum salvas faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 14, 'Ex usuris et iniquitate redimet animas eorum, et honorabile nomen eorum coram illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 15, 'Et vivet, et dabitur ei de auro Arabiæ; et adorabunt de ipso semper, tota die benedicent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 16, 'Et erit firmamentum in terra in summis montium; superextolletur super Libanum fructus ejus, et florebunt de civitate sicut fœnum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 17, 'Sit nomen ejus benedictum in sæcula; ante solem permanet nomen ejus. Et benedicentur in ipso omnes tribus terræ; omnes gentes magnificabunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 18, 'Benedictus Dominus Deus Israël, qui facit mirabilia solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 19, 'Et benedictum nomen majestatis ejus in æternum, et replebitur majestate ejus omnis terra. Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 71, 20, 'Defecerunt laudes David, filii Jesse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 1, 'Psalmus Asaph. Quam bonus Israël Deus, his qui recto sunt corde!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 2, 'Mei autem pene moti sunt pedes, pene effusi sunt gressus mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 3, 'quia zelavi super iniquos, pacem peccatorum videns.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 4, 'Quia non est respectus morti eorum, et firmamentum in plaga eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 5, 'In labore hominum non sunt, et cum hominibus non flagellabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 6, 'Ideo tenuit eos superbia; operti sunt iniquitate et impietate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 7, 'Prodiit quasi ex adipe iniquitas eorum; transierunt in affectum cordis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 8, 'Cogitaverunt et locuti sunt nequitiam; iniquitatem in excelso locuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 9, 'Posuerunt in cælum os suum, et lingua eorum transivit in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 10, 'Ideo convertetur populus meus hic, et dies pleni invenientur in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 11, 'Et dixerunt: Quomodo scit Deus, et si est scientia in excelso?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 12, 'Ecce ipsi peccatores, et abundantes in sæculo obtinuerunt divitias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 13, 'Et dixi: Ergo sine causa justificavi cor meum, et lavi inter innocentes manus meas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 14, 'et fui flagellatus tota die, et castigatio mea in matutinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 15, 'Si dicebam: Narrabo sic; ecce nationem filiorum tuorum reprobavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 16, 'Existimabam ut cognoscerem hoc; labor est ante me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 17, 'donec intrem in sanctuarium Dei, et intelligam in novissimis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 18, 'Verumtamen propter dolos posuisti eis; dejecisti eos dum allevarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 19, 'Quomodo facti sunt in desolationem? subito defecerunt: perierunt propter iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 20, 'Velut somnium surgentium, Domine, in civitate tua imaginem ipsorum ad nihilum rediges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 21, 'Quia inflammatum est cor meum, et renes mei commutati sunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 22, 'et ego ad nihilum redactus sum, et nescivi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 23, 'ut jumentum factus sum apud te, et ego semper tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 24, 'Tenuisti manum dexteram meam, et in voluntate tua deduxisti me, et cum gloria suscepisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 25, 'Quid enim mihi est in cælo? et a te quid volui super terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 26, 'Defecit caro mea et cor meum; Deus cordis mei, et pars mea, Deus in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 27, 'Quia ecce qui elongant se a te peribunt; perdidisti omnes qui fornicantur abs te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 72, 28, 'Mihi autem adhærere Deo bonum est; ponere in Domino Deo spem meam: ut annuntiem omnes prædicationes tuas in portis filiæ Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 1, 'Intellectus Asaph. Ut quid, Deus, repulisti in finem, iratus est furor tuus super oves pascuæ tuæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 2, 'Memor esto congregationis tuæ, quam possedisti ab initio. Redemisti virgam hæreditatis tuæ, mons Sion, in quo habitasti in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 3, 'Leva manus tuas in superbias eorum in finem: quanta malignatus est inimicus in sancto!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 4, 'Et gloriati sunt qui oderunt te in medio solemnitatis tuæ; posuerunt signa sua, signa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 5, 'et non cognoverunt sicut in exitu super summum. Quasi in silva lignorum securibus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 6, 'exciderunt januas ejus in idipsum; in securi et ascia dejecerunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 7, 'Incenderunt igni sanctuarium tuum; in terra polluerunt tabernaculum nominis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 8, 'Dixerunt in corde suo cognatio eorum simul: Quiescere faciamus omnes dies festos Dei a terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 9, 'Signa nostra non vidimus; jam non est propheta; et nos non cognoscet amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 10, 'Usquequo, Deus, improperabit inimicus? irritat adversarius nomen tuum in finem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 11, 'Ut quid avertis manum tuam, et dexteram tuam de medio sinu tuo in finem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 12, 'Deus autem rex noster ante sæcula: operatus est salutem in medio terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 13, 'Tu confirmasti in virtute tua mare; contribulasti capita draconum in aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 14, 'Tu confregisti capita draconis; dedisti eum escam populis \'thiopum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 15, 'Tu dirupisti fontes et torrentes; tu siccasti fluvios Ethan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 16, 'Tuus est dies, et tua est nox; tu fabricatus es auroram et solem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 17, 'Tu fecisti omnes terminos terræ; æstatem et ver tu plasmasti ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 18, 'Memor esto hujus: inimicus improperavit Domino, et populus insipiens incitavit nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 19, 'Ne tradas bestiis animas confitentes tibi, et animas pauperum tuorum ne obliviscaris in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 20, 'Respice in testamentum tuum, quia repleti sunt qui obscurati sunt terræ domibus iniquitatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 21, 'Ne avertatur humilis factus confusus; pauper et inops laudabunt nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 22, 'Exsurge, Deus, judica causam tuam; memor esto improperiorum tuorum, eorum quæ ab insipiente sunt tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 73, 23, 'Ne obliviscaris voces inimicorum tuorum: superbia eorum qui te oderunt ascendit semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 1, 'In finem, ne corrumpas. Psalmus cantici Asaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 2, 'Confitebimur tibi, Deus, confitebimur, et invocabimus nomen tuum; narrabimus mirabilia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 3, 'Cum accepero tempus, ego justitias judicabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 4, 'Liquefacta est terra et omnes qui habitant in ea: ego confirmavi columnas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 5, 'Dixi iniquis: Nolite inique agere: et delinquentibus: Nolite exaltare cornu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 6, 'nolite extollere in altum cornu vestrum; nolite loqui adversus Deum iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 7, 'Quia neque ab oriente, neque ab occidente, neque a desertis montibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 8, 'quoniam Deus judex est. Hunc humiliat, et hunc exaltat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 9, 'quia calix in manu Domini vini meri, plenus misto. Et inclinavit ex hoc in hoc; verumtamen fæx ejus non est exinanita: bibent omnes peccatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 10, 'Ego autem annuntiabo in sæculum; cantabo Deo Jacob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 74, 11, 'et omnia cornua peccatorum confringam, et exaltabuntur cornua justi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 1, 'In finem, in laudibus. Psalmus Asaph, canticum ad Assyrios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 2, 'Notus in Judæa Deus; in Israël magnum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 3, 'Et factus est in pace locus ejus, et habitatio ejus in Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 4, 'Ibi confregit potentias arcuum, scutum, gladium, et bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 5, 'Illuminans tu mirabiliter a montibus æternis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 6, 'turbati sunt omnes insipientes corde. Dormierunt somnum suum, et nihil invenerunt omnes viri divitiarum in manibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 7, 'Ab increpatione tua, Deus Jacob, dormitaverunt qui ascenderunt equos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 8, 'Tu terribilis es; et quis resistet tibi? ex tunc ira tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 9, 'De cælo auditum fecisti judicium: terra tremuit et quievit');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 10, 'cum exsurgeret in judicium Deus, ut salvos faceret omnes mansuetos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 11, 'Quoniam cogitatio hominis confitebitur tibi, et reliquiæ cogitationis diem festum agent tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 12, 'Vovete et reddite Domino Deo vestro, omnes qui in circuitu ejus affertis munera: terribili,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 75, 13, 'et ei qui aufert spiritum principum: terribili apud reges terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 1, 'In finem, pro Idithun. Psalmus Asaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 2, 'Voce mea ad Dominum clamavi; voce mea ad Deum, et intendit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 3, 'In die tribulationis meæ Deum exquisivi; manibus meis nocte contra eum, et non sum deceptus. Renuit consolari anima mea;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 4, 'memor fui Dei, et delectatus sum, et exercitatus sum, et defecit spiritus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 5, 'Anticipaverunt vigilias oculi mei; turbatus sum, et non sum locutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 6, 'Cogitavi dies antiquos, et annos æternos in mente habui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 7, 'Et meditatus sum nocte cum corde meo, et exercitabar, et scopebam spiritum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 8, 'Numquid in æternum projiciet Deus? aut non apponet ut complacitior sit adhuc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 9, 'aut in finem misericordiam suam abscindet, a generatione in generationem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 10, 'aut obliviscetur misereri Deus? aut continebit in ira sua misericordias suas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 11, 'Et dixi: Nunc cœpi; hæc mutatio dexteræ Excelsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 12, 'Memor fui operum Domini, quia memor ero ab initio mirabilium tuorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 13, 'et meditabor in omnibus operibus tuis, et in adinventionibus tuis exercebor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 14, 'Deus, in sancto via tua: quis deus magnus sicut Deus noster?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 15, 'Tu es Deus qui facis mirabilia: notam fecisti in populis virtutem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 16, 'Redemisti in brachio tuo populum tuum, filios Jacob et Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 17, 'Viderunt te aquæ, Deus; viderunt te aquæ, et timuerunt: et turbatæ sunt abyssi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 18, 'Multitudo sonitus aquarum; vocem dederunt nubes. Etenim sagittæ tuæ transeunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 19, 'vox tonitrui tui in rota. Illuxerunt coruscationes tuæ orbi terræ; commota est, et contremuit terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 20, 'In mari via tua, et semitæ tuæ in aquis multis, et vestigia tua non cognoscentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 76, 21, 'Deduxisti sicut oves populum tuum, in manu Moysi et Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 1, 'Intellectus Asaph. Attendite, popule meus, legem meam; inclinate aurem vestram in verba oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 2, 'Aperiam in parabolis os meum; loquar propositiones ab initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 3, 'Quanta audivimus, et cognovimus ea, et patres nostri narraverunt nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 4, 'Non sunt occultata a filiis eorum in generatione altera, narrantes laudes Domini et virtutes ejus, et mirabilia ejus quæ fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 5, 'Et suscitavit testimonium in Jacob, et legem posuit in Israël, quanta mandavit patribus nostris nota facere ea filiis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 6, 'ut cognoscat generatio altera: filii qui nascentur et exsurgent, et narrabunt filiis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 7, 'ut ponant in Deo spem suam, et non obliviscantur operum Dei, et mandata ejus exquirant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 8, 'ne fiant, sicut patres eorum, generatio prava et exasperans; generatio quæ non direxit cor suum, et non est creditus cum Deo spiritus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 9, 'Filii Ephrem, intendentes et mittentes arcum, conversi sunt in die belli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 10, 'Non custodierunt testamentum Dei, et in lege ejus noluerunt ambulare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 11, 'Et obliti sunt benefactorum ejus, et mirabilium ejus quæ ostendit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 12, 'Coram patribus eorum fecit mirabilia in terra \'gypti, in campo Taneos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 13, 'Interrupit mare, et perduxit eos, et statuit aquas quasi in utre:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 14, 'et deduxit eos in nube diei, et tota nocte in illuminatione ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 15, 'Interrupit petram in eremo, et adaquavit eos velut in abysso multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 16, 'Et eduxit aquam de petra, et deduxit tamquam flumina aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 17, 'Et apposuerunt adhuc peccare ei; in iram excitaverunt Excelsum in inaquoso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 18, 'Et tentaverunt Deum in cordibus suis, ut peterent escas animabus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 19, 'Et male locuti sunt de Deo; dixerunt: Numquid poterit Deus parare mensam in deserto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 20, 'quoniam percussit petram, et fluxerunt aquæ, et torrentes inundaverunt. Numquid et panem poterit dare, aut parare mensam populo suo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 21, 'Ideo audivit Dominus et distulit; et ignis accensus est in Jacob, et ira ascendit in Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 22, 'quia non crediderunt in Deo, nec speraverunt in salutari ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 23, 'Et mandavit nubibus desuper, et januas cæli aperuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 24, 'Et pluit illis manna ad manducandum, et panem cæli dedit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 25, 'Panem angelorum manducavit homo; cibaria misit eis in abundantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 26, 'Transtulit austrum de cælo, et induxit in virtute sua africum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 27, 'Et pluit super eos sicut pulverem carnes, et sicut arenam maris volatilia pennata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 28, 'Et ceciderunt in medio castrorum eorum, circa tabernacula eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 29, 'Et manducaverunt, et saturati sunt nimis, et desiderium eorum attulit eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 30, 'non sunt fraudati a desiderio suo. Adhuc escæ eorum erant in ore ipsorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 31, 'et ira Dei ascendit super eos: et occidit pingues eorum, et electos Israël impedivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 32, 'In omnibus his peccaverunt adhuc, et non crediderunt in mirabilibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 33, 'Et defecerunt in vanitate dies eorum, et anni eorum cum festinatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 34, 'Cum occideret eos, quærebant eum et revertebantur, et diluculo veniebant ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 35, 'Et rememorati sunt quia Deus adjutor est eorum, et Deus excelsus redemptor eorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 36, 'Et dilexerunt eum in ore suo, et lingua sua mentiti sunt ei;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 37, 'cor autem eorum non erat rectum cum eo, nec fideles habiti sunt in testamento ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 38, 'Ipse autem est misericors, et propitius fiet peccatis eorum, et non disperdet eos. Et abundavit ut averteret iram suam, et non accendit omnem iram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 39, 'Et recordatus est quia caro sunt, spiritus vadens et non rediens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 40, 'Quoties exacerbaverunt eum in deserto; in iram concitaverunt eum in inaquoso?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 41, 'Et conversi sunt, et tentaverunt Deum, et sanctum Israël exacerbaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 42, 'Non sunt recordati manus ejus, die qua redemit eos de manu tribulantis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 43, 'sicut posuit in \'gypto signa sua, et prodigia sua in campo Taneos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 44, 'et convertit in sanguinem flumina eorum, et imbres eorum, ne biberent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 45, 'Misit in eos cœnomyiam, et comedit eos, et ranam, et disperdidit eos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 46, 'et dedit ærugini fructus eorum, et labores eorum locustæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 47, 'et occidit in grandine vineas eorum, et moros eorum in pruina;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 48, 'et tradidit grandini jumenta eorum, et possessionem eorum igni;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 49, 'misit in eos iram indignationis suæ, indignationem, et iram, et tribulationem, immissiones per angelos malos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 50, 'Viam fecit semitæ iræ suæ: non pepercit a morte animabus eorum, et jumenta eorum in morte conclusit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 51, 'et percussit omne primogenitum in terra \'gypti; primitias omnis laboris eorum in tabernaculis Cham:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 52, 'et abstulit sicut oves populum suum, et perduxit eos tamquam gregem in deserto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 53, 'et deduxit eos in spe, et non timuerunt, et inimicos eorum operuit mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 54, 'Et induxit eos in montem sanctificationis suæ, montem quem acquisivit dextera ejus; et ejecit a facie eorum gentes, et sorte divisit eis terram in funiculo distributionis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 55, 'et habitare fecit in tabernaculis eorum tribus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 56, 'Et tentaverunt, et exacerbaverunt Deum excelsum, et testimonia ejus non custodierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 57, 'Et averterunt se, et non servaverunt pactum: quemadmodum patres eorum, conversi sunt in arcum pravum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 58, 'In iram concitaverunt eum in collibus suis, et in sculptilibus suis ad æmulationem eum provocaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 59, 'Audivit Deus, et sprevit, et ad nihilum redegit valde Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 60, 'Et repulit tabernaculum Silo, tabernaculum suum, ubi habitavit in hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 61, 'Et tradidit in captivitatem virtutem eorum, et pulchritudinem eorum in manus inimici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 62, 'Et conclusit in gladio populum suum, et hæreditatem suam sprevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 63, 'Juvenes eorum comedit ignis, et virgines eorum non sunt lamentatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 64, 'Sacerdotes eorum in gladio ceciderunt, et viduæ eorum non plorabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 65, 'Et excitatus est tamquam dormiens Dominus, tamquam potens crapulatus a vino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 66, 'Et percussit inimicos suos in posteriora; opprobrium sempiternum dedit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 67, 'Et repulit tabernaculum Joseph, et tribum Ephraim non elegit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 68, 'sed elegit tribum Juda, montem Sion, quem dilexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 69, 'Et ædificavit sicut unicornium sanctificium suum, in terra quam fundavit in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 70, 'Et elegit David, servum suum, et sustulit eum de gregibus ovium; de post fœtantes accepit eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 71, 'pascere Jacob servum suum, et Israël hæreditatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 77, 72, 'Et pavit eos in innocentia cordis sui, et in intellectibus manuum suarum deduxit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 1, 'Psalmus Asaph. Deus, venerunt gentes in hæreditatem tuam; polluerunt templum sanctum tuum; posuerunt Jerusalem in pomorum custodiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 2, 'Posuerunt morticina servorum tuorum escas volatilibus cæli; carnes sanctorum tuorum bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 3, 'Effuderunt sanguinem eorum tamquam aquam in circuitu Jerusalem, et non erat qui sepeliret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 4, 'Facti sumus opprobrium vicinis nostris; subsannatio et illusio his qui in circuitu nostro sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 5, 'Usquequo, Domine, irasceris in finem? accendetur velut ignis zelus tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 6, 'Effunde iram tuam in gentes quæ te non noverunt, et in regna quæ nomen tuum non invocaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 7, 'quia comederunt Jacob, et locum ejus desolaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 8, 'Ne memineris iniquitatum nostrarum antiquarum; cito anticipent nos misericordiæ tuæ, quia pauperes facti sumus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 9, 'Adjuva nos, Deus salutaris noster, et propter gloriam nominis tui, Domine, libera nos: et propitius esto peccatis nostris, propter nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 10, 'Ne forte dicant in gentibus: Ubi est Deus eorum? et innotescat in nationibus coram oculis nostris ultio sanguinis servorum tuorum qui effusus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 11, 'Introëat in conspectu tuo gemitus compeditorum; secundum magnitudinem brachii tui posside filios mortificatorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 12, 'et redde vicinis nostris septuplum in sinu eorum; improperium ipsorum quod exprobraverunt tibi, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 78, 13, 'Nos autem populus tuus, et oves pascuæ tuæ, confitebimur tibi in sæculum; in generationem et generationem annuntiabimus laudem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 1, 'In finem, pro iis qui commutabuntur. Testimonium Asaph, psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 2, 'Qui regis Israël, intende; qui deducis velut ovem Joseph. Qui sedes super cherubim, manifestare');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 3, 'coram Ephraim, Benjamin, et Manasse. Excita potentiam tuam, et veni, ut salvos facias nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 4, 'Deus, converte nos, et ostende faciem tuam, et salvi erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 5, 'Domine Deus virtutum, quousque irasceris super orationem servi tui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 6, 'cibabis nos pane lacrimarum, et potum dabis nobis in lacrimis in mensura?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 7, 'Posuisti nos in contradictionem vicinis nostris, et inimici nostri subsannaverunt nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 8, 'Deus virtutum, converte nos, et ostende faciem tuam, et salvi erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 9, 'Vineam de \'gypto transtulisti: ejecisti gentes, et plantasti eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 10, 'Dux itineris fuisti in conspectu ejus; plantasti radices ejus, et implevit terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 11, 'Operuit montes umbra ejus, et arbusta ejus cedros Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 12, 'Extendit palmites suos usque ad mare, et usque ad flumen propagines ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 13, 'Ut quid destruxisti maceriam ejus, et vindemiant eam omnes qui prætergrediuntur viam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 14, 'Exterminavit eam aper de silva, et singularis ferus depastus est eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 15, 'Deus virtutum, convertere, respice de cælo, et vide, et visita vineam istam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 16, 'et perfice eam quam plantavit dextera tua, et super filium hominis quem confirmasti tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 17, 'Incensa igni et suffossa, ab increpatione vultus tui peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 18, 'Fiat manus tua super virum dexteræ tuæ, et super filium hominis quem confirmasti tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 19, 'Et non discedimus a te: vivificabis nos, et nomen tuum invocabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 79, 20, 'Domine Deus virtutum, converte nos, et ostende faciem tuam, et salvi erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 1, 'In finem, pro torcularibus. Psalmus ipsi Asaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 2, 'Exsultate Deo adjutori nostro; jubilate Deo Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 3, 'Sumite psalmum, et date tympanum; psalterium jucundum cum cithara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 4, 'Buccinate in neomenia tuba, in insigni die solemnitatis vestræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 5, 'quia præceptum in Israël est, et judicium Deo Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 6, 'Testimonium in Joseph posuit illud, cum exiret de terra \'gypti; linguam quam non noverat, audivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 7, 'Divertit ab oneribus dorsum ejus; manus ejus in cophino servierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 8, 'In tribulatione invocasti me, et liberavi te. Exaudivi te in abscondito tempestatis; probavi te apud aquam contradictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 9, 'Audi, populus meus, et contestabor te. Israël, si audieris me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 10, 'non erit in te deus recens, neque adorabis deum alienum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 11, 'Ego enim sum Dominus Deus tuus, qui eduxi te de terra \'gypti. Dilata os tuum, et implebo illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 12, 'Et non audivit populus meus vocem meam, et Israël non intendit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 13, 'Et dimisi eos secundum desideria cordis eorum; ibunt in adinventionibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 14, 'Si populus meus audisset me, Israël si in viis meis ambulasset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 15, 'pro nihilo forsitan inimicos eorum humiliassem, et super tribulantes eos misissem manum meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 16, 'Inimici Domini mentiti sunt ei, et erit tempus eorum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 80, 17, 'Et cibavit eos ex adipe frumenti, et de petra melle saturavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 1, 'Psalmus Asaph. Deus stetit in synagoga deorum; in medio autem deos dijudicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 2, 'Usquequo judicatis iniquitatem, et facies peccatorum sumitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 3, 'Judicate egeno et pupillo; humilem et pauperem justificate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 4, 'Eripite pauperem, et egenum de manu peccatoris liberate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 5, 'Nescierunt, neque intellexerunt; in tenebris ambulant: movebuntur omnia fundamenta terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 6, 'Ego dixi: Dii estis, et filii Excelsi omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 7, 'Vos autem sicut homines moriemini, et sicut unus de principibus cadetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 81, 8, 'Surge, Deus, judica terram, quoniam tu hæreditabis in omnibus gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 1, 'Canticum Psalmi Asaph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 2, 'Deus, quis similis erit tibi? ne taceas, neque compescaris, Deus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 3, 'quoniam ecce inimici tui sonuerunt, et qui oderunt te extulerunt caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 4, 'Super populum tuum malignaverunt consilium, et cogitaverunt adversus sanctos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 5, 'Dixerunt: Venite, et disperdamus eos de gente, et non memoretur nomen Israël ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 6, 'Quoniam cogitaverunt unanimiter; simul adversum te testamentum disposuerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 7, 'tabernacula Idumæorum et Ismahelitæ, Moab et Agareni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 8, 'Gebal, et Ammon, et Amalec; alienigenæ cum habitantibus Tyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 9, 'Etenim Assur venit cum illis: facti sunt in adjutorium filiis Lot.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 10, 'Fac illis sicut Madian et Sisaræ, sicut Jabin in torrente Cisson.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 11, 'Disperierunt in Endor; facti sunt ut stercus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 12, 'Pone principes eorum sicut Oreb, et Zeb, et Zebee, et Salmana: omnes principes eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 13, 'qui dixerunt: Hæreditate possideamus sanctuarium Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 14, 'Deus meus, pone illos ut rotam, et sicut stipulam ante faciem venti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 15, 'Sicut ignis qui comburit silvam, et sicut flamma comburens montes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 16, 'ita persequeris illos in tempestate tua, et in ira tua turbabis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 17, 'Imple facies eorum ignominia, et quærent nomen tuum, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 18, 'Erubescant, et conturbentur in sæculum sæculi, et confundantur, et pereant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 82, 19, 'Et cognoscant quia nomen tibi Dominus: tu solus Altissimus in omni terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 1, 'In finem, pro torcularibus filiis Core. Psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 2, 'Quam dilecta tabernacula tua, Domine virtutum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 3, 'Concupiscit, et deficit anima mea in atria Domini; cor meum et caro mea exsultaverunt in Deum vivum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 4, 'Etenim passer invenit sibi domum, et turtur nidum sibi, ubi ponat pullos suos: altaria tua, Domine virtutum, rex meus, et Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 5, 'Beati qui habitant in domo tua, Domine; in sæcula sæculorum laudabunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 6, 'Beatus vir cujus est auxilium abs te: ascensiones in corde suo disposuit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 7, 'in valle lacrimarum, in loco quem posuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 8, 'Etenim benedictionem dabit legislator; ibunt de virtute in virtutem: videbitur Deus deorum in Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 9, 'Domine Deus virtutum, exaudi orationem meam; auribus percipe, Deus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 10, 'Protector noster, aspice, Deus, et respice in faciem christi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 11, 'Quia melior est dies una in atriis tuis super millia; elegi abjectus esse in domo Dei mei magis quam habitare in tabernaculis peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 12, 'Quia misericordiam et veritatem diligit Deus: gratiam et gloriam dabit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 83, 13, 'Non privabit bonis eos qui ambulant in innocentia: Domine virtutum, beatus homo qui sperat in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 1, 'In finem, filiis Core. Psalmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 2, 'Benedixisti, Domine, terram tuam; avertisti captivitatem Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 3, 'Remisisti iniquitatem plebis tuæ; operuisti omnia peccata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 4, 'Mitigasti omnem iram tuam; avertisti ab ira indignationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 5, 'Converte nos, Deus salutaris noster, et averte iram tuam a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 6, 'Numquid in æternum irasceris nobis? aut extendes iram tuam a generatione in generationem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 7, 'Deus, tu conversus vivificabis nos, et plebs tua lætabitur in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 8, 'Ostende nobis, Domine, misericordiam tuam, et salutare tuum da nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 9, 'Audiam quid loquatur in me Dominus Deus, quoniam loquetur pacem in plebem suam, et super sanctos suos, et in eos qui convertuntur ad cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 10, 'Verumtamen prope timentes eum salutare ipsius, ut inhabitet gloria in terra nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 11, 'Misericordia et veritas obviaverunt sibi; justitia et pax osculatæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 12, 'Veritas de terra orta est, et justitia de cælo prospexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 13, 'Etenim Dominus dabit benignitatem, et terra nostra dabit fructum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 84, 14, 'Justitia ante eum ambulabit, et ponet in via gressus suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 1, 'Oratio ipsi David. Inclina, Domine, aurem tuam et exaudi me, quoniam inops et pauper sum ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 2, 'Custodi animam meam, quoniam sanctus sum; salvum fac servum tuum, Deus meus, sperantem in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 3, 'Miserere mei, Domine, quoniam ad te clamavi tota die;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 4, 'lætifica animam servi tui, quoniam ad te, Domine, animam meam levavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 5, 'Quoniam tu, Domine, suavis et mitis, et multæ misericordiæ omnibus invocantibus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 6, 'Auribus percipe, Domine, orationem meam, et intende voci deprecationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 7, 'In die tribulationis meæ clamavi ad te, quia exaudisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 8, 'Non est similis tui in diis, Domine, et non est secundum opera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 9, 'Omnes gentes quascumque fecisti venient, et adorabunt coram te, Domine, et glorificabunt nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 10, 'Quoniam magnus es tu, et faciens mirabilia; tu es Deus solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 11, 'Deduc me, Domine, in via tua, et ingrediar in veritate tua; lætetur cor meum, ut timeat nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 12, 'Confitebor tibi, Domine Deus meus, in toto corde meo, et glorificabo nomen tuum in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 13, 'quia misericordia tua magna est super me, et eruisti animam meam ex inferno inferiori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 14, 'Deus, iniqui insurrexerunt super me, et synagoga potentium quæsierunt animam meam: et non proposuerunt te in conspectu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 15, 'Et tu, Domine Deus, miserator et misericors; patiens, et multæ misericordiæ, et verax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 16, 'Respice in me, et miserere mei; da imperium tuum puero tuo, et salvum fac filium ancillæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 85, 17, 'Fac mecum signum in bonum, ut videant qui oderunt me, et confundantur: quoniam tu, Domine, adjuvisti me, et consolatus es me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 1, 'Filiis Core. Psalmus cantici. Fundamenta ejus in montibus sanctis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 2, 'diligit Dominus portas Sion super omnia tabernacula Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 3, 'Gloriosa dicta sunt de te, civitas Dei!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 4, 'Memor ero Rahab et Babylonis, scientium me; ecce alienigenæ, et Tyrus, et populus \'thiopum, hi fuerunt illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 5, 'Numquid Sion dicet: Homo et homo natus est in ea, et ipse fundavit eam Altissimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 6, 'Dominus narrabit in scripturis populorum et principum, horum qui fuerunt in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 86, 7, 'Sicut lætantium omnium habitatio est in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 1, 'Canticum Psalmi, filiis Core, in finem, pro Maheleth ad respondendum. Intellectus Eman Ezrahitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 2, 'Domine, Deus salutis meæ, in die clamavi et nocte coram te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 3, 'Intret in conspectu tuo oratio mea, inclina aurem tuam ad precem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 4, 'Quia repleta est malis anima mea, et vita mea inferno appropinquavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 5, '\'stimatus sum cum descendentibus in lacum, factus sum sicut homo sine adjutorio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 6, 'inter mortuos liber; sicut vulnerati dormientes in sepulchris, quorum non es memor amplius, et ipsi de manu tua repulsi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 7, 'Posuerunt me in lacu inferiori, in tenebrosis, et in umbra mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 8, 'Super me confirmatus est furor tuus, et omnes fluctus tuos induxisti super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 9, 'Longe fecisti notos meos a me; posuerunt me abominationem sibi. Traditus sum, et non egrediebar;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 10, 'oculi mei languerunt præ inopia. Clamavi ad te, Domine, tota die; expandi ad te manus meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 11, 'Numquid mortuis facies mirabilia? aut medici suscitabunt, et confitebuntur tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 12, 'Numquid narrabit aliquis in sepulchro misericordiam tuam, et veritatem tuam in perditione?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 13, 'Numquid cognoscentur in tenebris mirabilia tua? et justitia tua in terra oblivionis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 14, 'Et ego ad te, Domine, clamavi, et mane oratio mea præveniet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 15, 'Ut quid, Domine, repellis orationem meam; avertis faciem tuam a me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 16, 'Pauper sum ego, et in laboribus a juventute mea; exaltatus autem, humiliatus sum et conturbatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 17, 'In me transierunt iræ tuæ, et terrores tui conturbaverunt me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 18, 'circumdederunt me sicut aqua tota die; circumdederunt me simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 87, 19, 'Elongasti a me amicum et proximum, et notos meos a miseria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 1, 'Intellectus Ethan Ezrahitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 2, 'Misericordias Domini in æternum cantabo; in generationem et generationem annuntiabo veritatem tuam in ore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 3, 'Quoniam dixisti: In æternum misericordia ædificabitur in cælis; præparabitur veritas tua in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 4, 'Disposui testamentum electis meis; juravi David servo meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 5, 'Usque in æternum præparabo semen tuum, et ædificabo in generationem et generationem sedem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 6, 'Confitebuntur cæli mirabilia tua, Domine; etenim veritatem tuam in ecclesia sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 7, 'Quoniam quis in nubibus æquabitur Domino; similis erit Deo in filiis Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 8, 'Deus, qui glorificatur in consilio sanctorum, magnus et terribilis super omnes qui in circuitu ejus sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 9, 'Domine Deus virtutum, quis similis tibi? potens es, Domine, et veritas tua in circuitu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 10, 'Tu dominaris potestati maris; motum autem fluctuum ejus tu mitigas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 11, 'Tu humiliasti, sicut vulneratum, superbum; in brachio virtutis tuæ dispersisti inimicos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 12, 'Tui sunt cæli, et tua est terra: orbem terræ, et plenitudinem ejus tu fundasti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 13, 'aquilonem et mare tu creasti. Thabor et Hermon in nomine tuo exsultabunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 14, 'tuum brachium cum potentia. Firmetur manus tua, et exaltetur dextera tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 15, 'justitia et judicium præparatio sedis tuæ: misericordia et veritas præcedent faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 16, 'Beatus populus qui scit jubilationem: Domine, in lumine vultus tui ambulabunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 17, 'et in nomine tuo exsultabunt tota die, et in justitia tua exaltabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 18, 'Quoniam gloria virtutis eorum tu es, et in beneplacito tuo exaltabitur cornu nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 19, 'Quia Domini est assumptio nostra, et sancti Israël regis nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 20, 'Tunc locutus es in visione sanctis tuis, et dixisti: Posui adjutorium in potente, et exaltavi electum de plebe mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 21, 'Inveni David, servum meum; oleo sancto meo unxi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 22, 'Manus enim mea auxiliabitur ei, et brachium meum confortabit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 23, 'Nihil proficiet inimicus in eo, et filius iniquitatis non apponet nocere ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 24, 'Et concidam a facie ipsius inimicos ejus, et odientes eum in fugam convertam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 25, 'Et veritas mea et misericordia mea cum ipso, et in nomine meo exaltabitur cornu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 26, 'Et ponam in mari manum ejus, et in fluminibus dexteram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 27, 'Ipse invocabit me: Pater meus es tu, Deus meus, et susceptor salutis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 28, 'Et ego primogenitum ponam illum, excelsum præ regibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 29, 'In æternum servabo illi misericordiam meam, et testamentum meum fidele ipsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 30, 'Et ponam in sæculum sæculi semen ejus, et thronum ejus sicut dies cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 31, 'Si autem dereliquerint filii ejus legem meam, et in judiciis meis non ambulaverint;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 32, 'si justitias meas profanaverint, et mandata mea non custodierint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 33, 'visitabo in virga iniquitates eorum, et in verberibus peccata eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 34, 'misericordiam autem meam non dispergam ab eo, neque nocebo in veritate mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 35, 'neque profanabo testamentum meum: et quæ procedunt de labiis meis non faciam irrita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 36, 'Semel juravi in sancto meo, si David mentiar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 37, 'semen ejus in æternum manebit. Et thronus ejus sicut sol in conspectu meo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 38, 'et sicut luna perfecta in æternum, et testis in cælo fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 39, 'Tu vero repulisti et despexisti; distulisti christum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 40, 'Evertisti testamentum servi tui; profanasti in terra sanctuarium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 41, 'Destruxisti omnes sepes ejus; posuisti firmamentum ejus formidinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 42, 'Diripuerunt eum omnes transeuntes viam; factus est opprobrium vicinis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 43, 'Exaltasti dexteram deprimentium eum; lætificasti omnes inimicos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 44, 'Avertisti adjutorium gladii ejus, et non es auxiliatus ei in bello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 45, 'Destruxisti eum ab emundatione, et sedem ejus in terram collisisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 46, 'Minorasti dies temporis ejus; perfudisti eum confusione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 47, 'Usquequo, Domine, avertis in finem? exardescet sicut ignis ira tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 48, 'Memorare quæ mea substantia: numquid enim vane constituisti omnes filios hominum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 49, 'Quis est homo qui vivet et non videbit mortem? eruet animam suam de manu inferi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 50, 'Ubi sunt misericordiæ tuæ antiquæ, Domine, sicut jurasti David in veritate tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 51, 'Memor esto, Domine, opprobrii servorum tuorum, quod continui in sinu meo, multarum gentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 52, 'quod exprobraverunt inimici tui, Domine; quod exprobraverunt commutationem christi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 88, 53, 'Benedictus Dominus in æternum. Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 1, 'Oratio Moysi, hominis Dei. Domine, refugium factus es nobis a generatione in generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 2, 'Priusquam montes fierent, aut formaretur terra et orbis, a sæculo et usque in sæculum tu es, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 3, 'Ne avertas hominem in humilitatem: et dixisti: Convertimini, filii hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 4, 'Quoniam mille anni ante oculos tuos tamquam dies hesterna quæ præteriit: et custodia in nocte');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 5, 'quæ pro nihilo habentur, eorum anni erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 6, 'Mane sicut herba transeat; mane floreat, et transeat; vespere decidat, induret, et arescat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 7, 'Quia defecimus in ira tua, et in furore tuo turbati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 8, 'Posuisti iniquitates nostras in conspectu tuo; sæculum nostrum in illuminatione vultus tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 9, 'Quoniam omnes dies nostri defecerunt, et in ira tua defecimus. Anni nostri sicut aranea meditabuntur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 10, 'dies annorum nostrorum in ipsis septuaginta anni. Si autem in potentatibus octoginta anni, et amplius eorum labor et dolor; quoniam supervenit mansuetudo, et corripiemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 11, 'Quis novit potestatem iræ tuæ, et præ timore tuo iram tuam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 12, 'dinumerare? Dexteram tuam sic notam fac, et eruditos corde in sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 13, 'Convertere, Domine; usquequo? et deprecabilis esto super servos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 14, 'Repleti sumus mane misericordia tua; et exsultavimus, et delectati sumus omnibus diebus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 15, 'Lætati sumus pro diebus quibus nos humiliasti; annis quibus vidimus mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 16, 'Respice in servos tuos et in opera tua, et dirige filios eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 89, 17, 'Et sit splendor Domini Dei nostri super nos, et opera manuum nostrarum dirige super nos, et opus manuum nostrarum dirige.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 1, 'Laus cantici David. Qui habitat in adjutorio Altissimi, in protectione Dei cæli commorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 2, 'Dicet Domino: Susceptor meus es tu, et refugium meum; Deus meus, sperabo in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 3, 'Quoniam ipse liberavit me de laqueo venantium, et a verbo aspero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 4, 'Scapulis suis obumbrabit tibi, et sub pennis ejus sperabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 5, 'Scuto circumdabit te veritas ejus: non timebis a timore nocturno;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 6, 'a sagitta volante in die, a negotio perambulante in tenebris, ab incursu, et dæmonio meridiano.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 7, 'Cadent a latere tuo mille, et decem millia a dextris tuis; ad te autem non appropinquabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 8, 'Verumtamen oculis tuis considerabis, et retributionem peccatorum videbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 9, 'Quoniam tu es, Domine, spes mea; Altissimum posuisti refugium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 10, 'Non accedet ad te malum, et flagellum non appropinquabit tabernaculo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 11, 'Quoniam angelis suis mandavit de te, ut custodiant te in omnibus viis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 12, 'In manibus portabunt te, ne forte offendas ad lapidem pedem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 13, 'Super aspidem et basiliscum ambulabis, et conculcabis leonem et draconem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 14, 'Quoniam in me speravit, liberabo eum; protegam eum, quoniam cognovit nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 15, 'Clamabit ad me, et ego exaudiam eum; cum ipso sum in tribulatione: eripiam eum, et glorificabo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 90, 16, 'Longitudine dierum replebo eum, et ostendam illi salutare meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 1, 'Psalmus cantici, in die sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 2, 'Bonum est confiteri Domino, et psallere nomini tuo, Altissime:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 3, 'ad annuntiandum mane misericordiam tuam, et veritatem tuam per noctem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 4, 'in decachordo, psalterio; cum cantico, in cithara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 5, 'Quia delectasti me, Domine, in factura tua; et in operibus manuum tuarum exsultabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 6, 'Quam magnificata sunt opera tua, Domine! nimis profundæ factæ sunt cogitationes tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 7, 'Vir insipiens non cognoscet, et stultus non intelliget hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 8, 'Cum exorti fuerint peccatores sicut fœnum, et apparuerint omnes qui operantur iniquitatem, ut intereant in sæculum sæculi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 9, 'tu autem Altissimus in æternum, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 10, 'Quoniam ecce inimici tui, Domine, quoniam ecce inimici tui peribunt; et dispergentur omnes qui operantur iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 11, 'Et exaltabitur sicut unicornis cornu meum, et senectus mea in misericordia uberi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 12, 'Et despexit oculus meus inimicos meos, et in insurgentibus in me malignantibus audiet auris mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 13, 'Justus ut palma florebit; sicut cedrus Libani multiplicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 14, 'Plantati in domo Domini, in atriis domus Dei nostri florebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 15, 'Adhuc multiplicabuntur in senecta uberi, et bene patientes erunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 91, 16, 'ut annuntient quoniam rectus Dominus Deus noster, et non est iniquitas in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 92, 1, 'Laus cantici ipsi David, in die ante sabbatum, quando fundata est terra. Dominus regnavit, decorem indutus est: indutus est Dominus fortitudinem, et præcinxit se. Etenim firmavit orbem terræ, qui non commovebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 92, 2, 'Parata sedes tua ex tunc; a sæculo tu es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 92, 3, 'Elevaverunt flumina, Domine, elevaverunt flumina vocem suam; elevaverunt flumina fluctus suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 92, 4, 'a vocibus aquarum multarum. Mirabiles elationes maris; mirabilis in altis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 92, 5, 'Testimonia tua credibilia facta sunt nimis; domum tuam decet sanctitudo, Domine, in longitudinem dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 1, 'Psalmus ipsi David, quarta sabbati. Deus ultionum Dominus; Deus ultionum libere egit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 2, 'Exaltare, qui judicas terram; redde retributionem superbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 3, 'Usquequo peccatores, Domine, usquequo peccatores gloriabuntur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 4, 'effabuntur et loquentur iniquitatem; loquentur omnes qui operantur injustitiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 5, 'Populum tuum, Domine, humiliaverunt, et hæreditatem tuam vexaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 6, 'Viduam et advenam interfecerunt, et pupillos occiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 7, 'Et dixerunt: Non videbit Dominus, nec intelliget Deus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 8, 'Intelligite, insipientes in populo; et stulti, aliquando sapite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 9, 'Qui plantavit aurem non audiet? aut qui finxit oculum non considerat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 10, 'Qui corripit gentes non arguet, qui docet hominem scientiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 11, 'Dominus scit cogitationes hominum, quoniam vanæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 12, 'Beatus homo quem tu erudieris, Domine, et de lege tua docueris eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 13, 'ut mitiges ei a diebus malis, donec fodiatur peccatori fovea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 14, 'Quia non repellet Dominus plebem suam, et hæreditatem suam non derelinquet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 15, 'quoadusque justitia convertatur in judicium: et qui juxta illam, omnes qui recto sunt corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 16, 'Quis consurget mihi adversus malignantes? aut quis stabit mecum adversus operantes iniquitatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 17, 'Nisi quia Dominus adjuvit me, paulominus habitasset in inferno anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 18, 'Si dicebam: Motus est pes meus: misericordia tua, Domine, adjuvabat me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 19, 'Secundum multitudinem dolorum meorum in corde meo, consolationes tuæ lætificaverunt animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 20, 'Numquid adhæret tibi sedes iniquitatis, qui fingis laborem in præcepto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 21, 'Captabunt in animam justi, et sanguinem innocentem condemnabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 22, 'Et factus est mihi Dominus in refugium, et Deus meus in adjutorium spei meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 93, 23, 'Et reddet illis iniquitatem ipsorum, et in malitia eorum disperdet eos: disperdet illos Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 1, 'Laus cantici ipsi David. Venite, exsultemus Domino; jubilemus Deo salutari nostro;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 2, 'præoccupemus faciem ejus in confessione, et in psalmis jubilemus ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 3, 'quoniam Deus magnus Dominus, et rex magnus super omnes deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 4, 'Quia in manu ejus sunt omnes fines terræ, et altitudines montium ipsius sunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 5, 'quoniam ipsius est mare, et ipse fecit illud, et siccam manus ejus formaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 6, 'Venite, adoremus, et procidamus, et ploremus ante Dominum qui fecit nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 7, 'quia ipse est Dominus Deus noster, et nos populus pascuæ ejus, et oves manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 8, 'Hodie si vocem ejus audieritis, nolite obdurare corda vestra');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 9, 'sicut in irritatione, secundum diem tentationis in deserto, ubi tentaverunt me patres vestri: probaverunt me, et viderunt opera mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 10, 'Quadraginta annis offensus fui generationi illi, et dixi: Semper hi errant corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 94, 11, 'Et isti non cognoverunt vias meas: ut juravi in ira mea: Si introibunt in requiem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 1, 'Canticum ipsi David, quando domus ædificabatur post captivitatem. Cantate Domino canticum novum; cantate Domino omnis terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 2, 'Cantate Domino, et benedicite nomini ejus; annuntiate de die in diem salutare ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 3, 'Annuntiate inter gentes gloriam ejus; in omnibus populis mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 4, 'Quoniam magnus Dominus, et laudabilis nimis: terribilis est super omnes deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 5, 'Quoniam omnes dii gentium dæmonia; Dominus autem cælos fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 6, 'Confessio et pulchritudo in conspectu ejus; sanctimonia et magnificentia in sanctificatione ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 7, 'Afferte Domino, patriæ gentium, afferte Domino gloriam et honorem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 8, 'afferte Domino gloriam nomini ejus. Tollite hostias, et introite in atria ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 9, 'adorate Dominum in atrio sancto ejus. Commoveatur a facie ejus universa terra;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 10, 'dicite in gentibus, quia Dominus regnavit. Etenim correxit orbem terræ, qui non commovebitur; judicabit populos in æquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 11, 'Lætentur cæli, et exsultet terra; commoveatur mare et plenitudo ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 12, 'gaudebunt campi, et omnia quæ in eis sunt. Tunc exsultabunt omnia ligna silvarum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 95, 13, 'a facie Domini, quia venit, quoniam venit judicare terram. Judicabit orbem terræ in æquitate, et populos in veritate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 1, 'Huic David, quando terra ejus restituta est. Dominus regnavit: exsultet terra; lætentur insulæ multæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 2, 'Nubes et caligo in circuitu ejus; justitia et judicium correctio sedis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 3, 'Ignis ante ipsum præcedet, et inflammabit in circuitu inimicos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 4, 'Illuxerunt fulgura ejus orbi terræ; vidit, et commota est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 5, 'Montes sicut cera fluxerunt a facie Domini; a facie Domini omnis terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 6, 'Annuntiaverunt cæli justitiam ejus, et viderunt omnes populi gloriam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 7, 'Confundantur omnes qui adorant sculptilia, et qui gloriantur in simulacris suis. Adorate eum omnes angeli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 8, 'Audivit, et lætata est Sion, et exsultaverunt filiæ Judæ propter judicia tua, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 9, 'Quoniam tu Dominus altissimus super omnem terram; nimis exaltatus es super omnes deos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 10, 'Qui diligitis Dominum, odite malum: custodit Dominus animas sanctorum suorum; de manu peccatoris liberabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 11, 'Lux orta est justo, et rectis corde lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 96, 12, 'Lætamini, justi, in Domino, et confitemini memoriæ sanctificationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 1, 'Psalmus ipsi David. Cantate Domino canticum novum, quia mirabilia fecit. Salvavit sibi dextera ejus, et brachium sanctum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 2, 'Notum fecit Dominus salutare suum; in conspectu gentium revelavit justitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 3, 'Recordatus est misericordiæ suæ, et veritatis suæ domui Israël. Viderunt omnes termini terræ salutare Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 4, 'Jubilate Deo, omnis terra; cantate, et exsultate, et psallite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 5, 'Psallite Domino in cithara; in cithara et voce psalmi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 6, 'in tubis ductilibus, et voce tubæ corneæ. Jubilate in conspectu regis Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 7, 'moveatur mare, et plenitudo ejus; orbis terrarum, et qui habitant in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 8, 'Flumina plaudent manu; simul montes exsultabunt');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 97, 9, 'a conspectu Domini: quoniam venit judicare terram. Judicabit orbem terrarum in justitia, et populos in æquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 1, 'Psalmus ipsi David. Dominus regnavit: irascantur populi; qui sedet super cherubim: moveatur terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 2, 'Dominus in Sion magnus, et excelsus super omnes populos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 3, 'Confiteantur nomini tuo magno, quoniam terribile et sanctum est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 4, 'et honor regis judicium diligit. Tu parasti directiones; judicium et justitiam in Jacob tu fecisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 5, 'Exaltate Dominum Deum nostrum, et adorate scabellum pedum ejus, quoniam sanctum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 6, 'Moyses et Aaron in sacerdotibus ejus, et Samuel inter eos qui invocant nomen ejus: invocabant Dominum, et ipse exaudiebat eos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 7, 'in columna nubis loquebatur ad eos. Custodiebant testimonia ejus, et præceptum quod dedit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 8, 'Domine Deus noster, tu exaudiebas eos; Deus, tu propitius fuisti eis, et ulciscens in omnes adinventiones eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 98, 9, 'Exaltate Dominum Deum nostrum, et adorate in monte sancto ejus, quoniam sanctus Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 99, 1, 'Psalmus in confessione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 99, 2, 'Jubilate Deo, omnis terra; servite Domino in lætitia. Introite in conspectu ejus in exsultatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 99, 3, 'Scitote quoniam Dominus ipse est Deus; ipse fecit nos, et non ipsi nos: populus ejus, et oves pascuæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 99, 4, 'Introite portas ejus in confessione; atria ejus in hymnis: confitemini illi. Laudate nomen ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 99, 5, 'quoniam suavis est Dominus, in æternum misericordia ejus, et usque in generationem et generationem veritas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 1, 'Psalmus ipsi David. Misericordiam et judicium cantabo tibi, Domine; psallam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 2, 'et intelligam in via immaculata: quando venies ad me? Perambulabam in innocentia cordis mei, in medio domus meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 3, 'Non proponebam ante oculos meos rem injustam; facientes prævaricationes odivi; non adhæsit mihi');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 4, 'cor pravum; declinantem a me malignum non cognoscebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 5, 'Detrahentem secreto proximo suo, hunc persequebar: superbo oculo, et insatiabili corde, cum hoc non edebam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 6, 'Oculi mei ad fideles terræ, ut sedeant mecum; ambulans in via immaculata, hic mihi ministrabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 7, 'Non habitabit in medio domus meæ qui facit superbiam; qui loquitur iniqua non direxit in conspectu oculorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 100, 8, 'In matutino interficiebam omnes peccatores terræ, ut disperderem de civitate Domini omnes operantes iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 1, 'Oratio pauperis, cum anxius fuerit, et in conspectu Domini effuderit precem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 2, 'Domine, exaudi orationem meam, et clamor meus ad te veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 3, 'Non avertas faciem tuam a me: in quacumque die tribulor, inclina ad me aurem tuam; in quacumque die invocavero te, velociter exaudi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 4, 'Quia defecerunt sicut fumus dies mei, et ossa mea sicut cremium aruerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 5, 'Percussus sum ut fœnum, et aruit cor meum, quia oblitus sum comedere panem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 6, 'A voce gemitus mei adhæsit os meum carni meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 7, 'Similis factus sum pellicano solitudinis; factus sum sicut nycticorax in domicilio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 8, 'Vigilavi, et factus sum sicut passer solitarius in tecto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 9, 'Tota die exprobrabant mihi inimici mei, et qui laudabant me adversum me jurabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 10, 'quia cinerem tamquam panem manducabam, et potum meum cum fletu miscebam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 11, 'a facie iræ et indignationis tuæ: quia elevans allisisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 12, 'Dies mei sicut umbra declinaverunt, et ego sicut fœnum arui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 13, 'Tu autem, Domine, in æternum permanes, et memoriale tuum in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 14, 'Tu exsurgens misereberis Sion, quia tempus miserendi ejus, quia venit tempus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 15, 'quoniam placuerunt servis tuis lapides ejus, et terræ ejus miserebuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 16, 'Et timebunt gentes nomen tuum, Domine, et omnes reges terræ gloriam tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 17, 'quia ædificavit Dominus Sion, et videbitur in gloria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 18, 'Respexit in orationem humilium et non sprevit precem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 19, 'Scribantur hæc in generatione altera, et populus qui creabitur laudabit Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 20, 'Quia prospexit de excelso sancto suo; Dominus de cælo in terram aspexit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 21, 'ut audiret gemitus compeditorum; ut solveret filios interemptorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 22, 'ut annuntient in Sion nomen Domini, et laudem ejus in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 23, 'in conveniendo populos in unum, et reges, ut serviant Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 24, 'Respondit ei in via virtutis suæ: Paucitatem dierum meorum nuntia mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 25, 'ne revoces me in dimidio dierum meorum, in generationem et generationem anni tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 26, 'Initio tu, Domine, terram fundasti, et opera manuum tuarum sunt cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 27, 'Ipsi peribunt, tu autem permanes; et omnes sicut vestimentum veterascent. Et sicut opertorium mutabis eos, et mutabuntur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 28, 'tu autem idem ipse es, et anni tui non deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 101, 29, 'Filii servorum tuorum habitabunt, et semen eorum in sæculum dirigetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 1, 'Ipsi David. Benedic, anima mea, Domino, et omnia quæ intra me sunt nomini sancto ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 2, 'Benedic, anima mea, Domino, et noli oblivisci omnes retributiones ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 3, 'Qui propitiatur omnibus iniquitatibus tuis; qui sanat omnes infirmitates tuas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 4, 'qui redimit de interitu vitam tuam; qui coronat te in misericordia et miserationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 5, 'qui replet in bonis desiderium tuum; renovabitur ut aquilæ juventus tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 6, 'faciens misericordias Dominus, et judicium omnibus injuriam patientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 7, 'Notas fecit vias suas Moysi; filiis Israël voluntates suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 8, 'Miserator et misericors Dominus: longanimis, et multum misericors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 9, 'Non in perpetuum irascetur, neque in æternum comminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 10, 'Non secundum peccata nostra fecit nobis, neque secundum iniquitates nostras retribuit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 11, 'Quoniam secundum altitudinem cæli a terra, corroboravit misericordiam suam super timentes se;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 12, 'quantum distat ortus ab occidente, longe fecit a nobis iniquitates nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 13, 'Quomodo miseretur pater filiorum, misertus est Dominus timentibus se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 14, 'Quoniam ipse cognovit figmentum nostrum; recordatus est quoniam pulvis sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 15, 'Homo, sicut fœnum dies ejus; tamquam flos agri, sic efflorebit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 16, 'quoniam spiritus pertransibit in illo, et non subsistet, et non cognoscet amplius locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 17, 'Misericordia autem Domini ab æterno, et usque in æternum super timentes eum. Et justitia illius in filios filiorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 18, 'his qui servant testamentum ejus, et memores sunt mandatorum ipsius ad faciendum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 19, 'Dominus in cælo paravit sedem suam, et regnum ipsius omnibus dominabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 20, 'Benedicite Domino, omnes angeli ejus: potentes virtute, facientes verbum illius, ad audiendam vocem sermonum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 21, 'Benedicite Domino, omnes virtutes ejus; ministri ejus, qui facitis voluntatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 102, 22, 'Benedicite Domino, omnia opera ejus: in omni loco dominationis ejus, benedic, anima mea, Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 1, 'Ipsi David. Benedic, anima mea, Domino: Domine Deus meus, magnificatus es vehementer. Confessionem et decorem induisti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 2, 'amictus lumine sicut vestimento. Extendens cælum sicut pellem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 3, 'qui tegis aquis superiora ejus: qui ponis nubem ascensum tuum; qui ambulas super pennas ventorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 4, 'qui facis angelos tuos spiritus, et ministros tuos ignem urentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 5, 'Qui fundasti terram super stabilitatem suam: non inclinabitur in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 6, 'Abyssus sicut vestimentum amictus ejus; super montes stabunt aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 7, 'Ab increpatione tua fugient; a voce tonitrui tui formidabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 8, 'Ascendunt montes, et descendunt campi, in locum quem fundasti eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 9, 'Terminum posuisti quem non transgredientur, neque convertentur operire terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 10, 'Qui emittis fontes in convallibus; inter medium montium pertransibunt aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 11, 'Potabunt omnes bestiæ agri; expectabunt onagri in siti sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 12, 'Super ea volucres cæli habitabunt; de medio petrarum dabunt voces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 13, 'Rigans montes de superioribus suis; de fructu operum tuorum satiabitur terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 14, 'producens fœnum jumentis, et herbam servituti hominum, ut educas panem de terra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 15, 'et vinum lætificet cor hominis: ut exhilaret faciem in oleo, et panis cor hominis confirmet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 16, 'Saturabuntur ligna campi, et cedri Libani quas plantavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 17, 'illic passeres nidificabunt: herodii domus dux est eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 18, 'Montes excelsi cervis; petra refugium herinaciis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 19, 'Fecit lunam in tempora; sol cognovit occasum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 20, 'Posuisti tenebras, et facta est nox; in ipsa pertransibunt omnes bestiæ silvæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 21, 'catuli leonum rugientes ut rapiant, et quærant a Deo escam sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 22, 'Ortus est sol, et congregati sunt, et in cubilibus suis collocabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 23, 'Exibit homo ad opus suum, et ad operationem suam usque ad vesperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 24, 'Quam magnificata sunt opera tua, Domine! omnia in sapientia fecisti; impleta est terra possessione tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 25, 'Hoc mare magnum et spatiosum manibus; illic reptilia quorum non est numerus: animalia pusilla cum magnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 26, 'Illic naves pertransibunt; draco iste quem formasti ad illudendum ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 27, 'Omnia a te expectant ut des illis escam in tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 28, 'Dante te illis, colligent; aperiente te manum tuam, omnia implebuntur bonitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 29, 'Avertente autem te faciem, turbabuntur; auferes spiritum eorum, et deficient, et in pulverem suum revertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 30, 'Emittes spiritum tuum, et creabuntur, et renovabis faciem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 31, 'Sit gloria Domini in sæculum; lætabitur Dominus in operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 32, 'Qui respicit terram, et facit eam tremere; qui tangit montes, et fumigant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 33, 'Cantabo Domino in vita mea; psallam Deo meo quamdiu sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 34, 'Jucundum sit ei eloquium meum; ego vero delectabor in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 103, 35, 'Deficiant peccatores a terra, et iniqui, ita ut non sint. Benedic, anima mea, Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 1, 'Alleluja. Confitemini Domino, et invocate nomen ejus; annuntiate inter gentes opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 2, 'Cantate ei, et psallite ei; narrate omnia mirabilia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 3, 'Laudamini in nomine sancto ejus; lætetur cor quærentium Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 4, 'Quærite Dominum, et confirmamini; quærite faciem ejus semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 5, 'Mementote mirabilium ejus quæ fecit; prodigia ejus, et judicia oris ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 6, 'semen Abraham servi ejus; filii Jacob electi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 7, 'Ipse Dominus Deus noster; in universa terra judicia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 8, 'Memor fuit in sæculum testamenti sui; verbi quod mandavit in mille generationes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 9, 'quod disposuit ad Abraham, et juramenti sui ad Isaac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 10, 'et statuit illud Jacob in præceptum, et Israël in testamentum æternum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 11, 'dicens: Tibi dabo terram Chanaan, funiculum hæreditatis vestræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 12, 'cum essent numero brevi, paucissimi, et incolæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 13, 'Et pertransierunt de gente in gentem, et de regno ad populum alterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 14, 'Non reliquit hominem nocere eis: et corripuit pro eis reges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 15, 'Nolite tangere christos meos, et in prophetis meis nolite malignari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 16, 'Et vocavit famem super terram, et omne firmamentum panis contrivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 17, 'Misit ante eos virum: in servum venumdatus est, Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 18, 'Humiliaverunt in compedibus pedes ejus; ferrum pertransiit animam ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 19, 'donec veniret verbum ejus. Eloquium Domini inflammavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 20, 'Misit rex, et solvit eum; princeps populorum, et dimisit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 21, 'Constituit eum dominum domus suæ, et principem omnis possessionis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 22, 'ut erudiret principes ejus sicut semetipsum, et senes ejus prudentiam doceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 23, 'Et intravit Israël in \'gyptum, et Jacob accola fuit in terra Cham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 24, 'Et auxit populum suum vehementer, et firmavit eum super inimicos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 25, 'Convertit cor eorum, ut odirent populum ejus, et dolum facerent in servos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 26, 'Misit Moysen servum suum; Aaron quem elegit ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 27, 'Posuit in eis verba signorum suorum, et prodigiorum in terra Cham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 28, 'Misit tenebras, et obscuravit; et non exacerbavit sermones suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 29, 'Convertit aquas eorum in sanguinem, et occidit pisces eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 30, 'Edidit terra eorum ranas in penetralibus regum ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 31, 'Dixit, et venit cœnomyia et ciniphes in omnibus finibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 32, 'Posuit pluvias eorum grandinem: ignem comburentem in terra ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 33, 'Et percussit vineas eorum, et ficulneas eorum, et contrivit lignum finium eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 34, 'Dixit, et venit locusta, et bruchus cujus non erat numerus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 35, 'et comedit omne fœnum in terra eorum, et comedit omnem fructum terræ eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 36, 'Et percussit omne primogenitum in terra eorum, primitias omnis laboris eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 37, 'Et eduxit eos cum argento et auro, et non erat in tribubus eorum infirmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 38, 'Lætata est \'gyptus in profectione eorum, quia incubuit timor eorum super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 39, 'Expandit nubem in protectionem eorum, et ignem ut luceret eis per noctem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 40, 'Petierunt, et venit coturnix, et pane cæli saturavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 41, 'Dirupit petram, et fluxerunt aquæ: abierunt in sicco flumina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 42, 'Quoniam memor fuit verbi sancti sui, quod habuit ad Abraham puerum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 43, 'Et eduxit populum suum in exsultatione, et electos suos in lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 44, 'Et dedit illis regiones gentium, et labores populorum possederunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 104, 45, 'ut custodiant justificationes ejus, et legem ejus requirant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 1, 'Alleluja. Confitemini Domino, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 2, 'Quis loquetur potentias Domini; auditas faciet omnes laudes ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 3, 'Beati qui custodiunt judicium, et faciunt justitiam in omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 4, 'Memento nostri, Domine, in beneplacito populi tui; visita nos in salutari tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 5, 'ad videndum in bonitate electorum tuorum; ad lætandum in lætitia gentis tuæ: ut lauderis cum hæreditate tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 6, 'Peccavimus cum patribus nostris: injuste egimus; iniquitatem fecimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 7, 'Patres nostri in \'gypto non intellexerunt mirabilia tua; non fuerunt memores multitudinis misericordiæ tuæ. Et irritaverunt ascendentes in mare, mare Rubrum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 8, 'et salvavit eos propter nomen suum, ut notam faceret potentiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 9, 'Et increpuit mare Rubrum et exsiccatum est, et deduxit eos in abyssis sicut in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 10, 'Et salvavit eos de manu odientium, et redemit eos de manu inimici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 11, 'Et operuit aqua tribulantes eos; unus ex eis non remansit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 12, 'Et crediderunt verbis ejus, et laudaverunt laudem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 13, 'Cito fecerunt; obliti sunt operum ejus: et non sustinuerunt consilium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 14, 'Et concupierunt concupiscentiam in deserto, et tentaverunt Deum in inaquoso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 15, 'Et dedit eis petitionem ipsorum, et misit saturitatem in animas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 16, 'Et irritaverunt Moysen in castris; Aaron, sanctum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 17, 'Aperta est terra, et deglutivit Dathan, et operuit super congregationem Abiron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 18, 'Et exarsit ignis in synagoga eorum: flamma combussit peccatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 19, 'Et fecerunt vitulum in Horeb, et adoraverunt sculptile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 20, 'Et mutaverunt gloriam suam in similitudinem vituli comedentis fœnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 21, 'Obliti sunt Deum qui salvavit eos; qui fecit magnalia in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 22, 'mirabilia in terra Cham, terribilia in mari Rubro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 23, 'Et dixit ut disperderet eos, si non Moyses, electus ejus, stetisset in confractione in conspectu ejus, ut averteret iram ejus, ne disperderet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 24, 'Et pro nihilo habuerunt terram desiderabilem; non crediderunt verbo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 25, 'Et murmuraverunt in tabernaculis suis; non exaudierunt vocem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 26, 'Et elevavit manum suam super eos ut prosterneret eos in deserto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 27, 'et ut dejiceret semen eorum in nationibus, et dispergeret eos in regionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 28, 'Et initiati sunt Beelphegor, et comederunt sacrificia mortuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 29, 'Et irritaverunt eum in adinventionibus suis, et multiplicata est in eis ruina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 30, 'Et stetit Phinees, et placavit, et cessavit quassatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 31, 'Et reputatum est ei in justitiam, in generationem et generationem usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 32, 'Et irritaverunt eum ad aquas contradictionis, et vexatus est Moyses propter eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 33, 'quia exacerbaverunt spiritum ejus, et distinxit in labiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 34, 'Non disperdiderunt gentes quas dixit Dominus illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 35, 'et commisti sunt inter gentes, et didicerunt opera eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 36, 'et servierunt sculptilibus eorum, et factum est illis in scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 37, 'Et immolaverunt filios suos et filias suas dæmoniis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 38, 'Et effuderunt sanguinem innocentem, sanguinem filiorum suorum et filiarum suarum, quas sacrificaverunt sculptilibus Chanaan. Et infecta est terra in sanguinibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 39, 'et contaminata est in operibus eorum: et fornicati sunt in adinventionibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 40, 'Et iratus est furore Dominus in populum suum, et abominatus est hæreditatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 41, 'Et tradidit eos in manus gentium; et dominati sunt eorum qui oderunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 42, 'Et tribulaverunt eos inimici eorum, et humiliati sunt sub manibus eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 43, 'sæpe liberavit eos. Ipsi autem exacerbaverunt eum in consilio suo, et humiliati sunt in iniquitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 44, 'Et vidit cum tribularentur, et audivit orationem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 45, 'Et memor fuit testamenti sui, et pœnituit eum secundum multitudinem misericordiæ suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 46, 'et dedit eos in misericordias, in conspectu omnium qui ceperant eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 47, 'Salvos nos fac, Domine Deus noster, et congrega nos de nationibus: ut confiteamur nomini sancto tuo, et gloriemur in laude tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 105, 48, 'Benedictus Dominus Deus Israël, a sæculo et usque in sæculum; et dicet omnis populus: Fiat, fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 1, 'Alleluja. Confitemini Domino, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 2, 'Dicant qui redempti sunt a Domino, quos redemit de manu inimici, et de regionibus congregavit eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 3, 'a solis ortu, et occasu, ab aquilone, et mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 4, 'Erraverunt in solitudine, in inaquoso; viam civitatis habitaculi non invenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 5, 'Esurientes et sitientes, anima eorum in ipsis defecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 6, 'Et clamaverunt ad Dominum cum tribularentur, et de necessitatibus eorum eripuit eos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 7, 'et deduxit eos in viam rectam, ut irent in civitatem habitationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 8, 'Confiteantur Domino misericordiæ ejus, et mirabilia ejus filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 9, 'Quia satiavit animam inanem, et animam esurientem satiavit bonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 10, 'Sedentes in tenebris et umbra mortis; vinctos in mendicitate et ferro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 11, 'Quia exacerbaverunt eloquia Dei, et consilium Altissimi irritaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 12, 'Et humiliatum est in laboribus cor eorum; infirmati sunt, nec fuit qui adjuvaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 13, 'Et clamaverunt ad Dominum cum tribularentur; et de necessitatibus eorum liberavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 14, 'Et eduxit eos de tenebris et umbra mortis, et vincula eorum dirupit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 15, 'Confiteantur Domino misericordiæ ejus, et mirabilia ejus filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 16, 'Quia contrivit portas æreas, et vectes ferreos confregit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 17, 'Suscepit eos de via iniquitatis eorum; propter injustitias enim suas humiliati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 18, 'Omnem escam abominata est anima eorum, et appropinquaverunt usque ad portas mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 19, 'Et clamaverunt ad Dominum cum tribularentur, et de necessitatibus eorum liberavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 20, 'Misit verbum suum, et sanavit eos, et eripuit eos de interitionibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 21, 'Confiteantur Domino misericordiæ ejus, et mirabilia ejus filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 22, 'Et sacrificent sacrificium laudis, et annuntient opera ejus in exsultatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 23, 'Qui descendunt mare in navibus, facientes operationem in aquis multis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 24, 'ipsi viderunt opera Domini, et mirabilia ejus in profundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 25, 'Dixit, et stetit spiritus procellæ, et exaltati sunt fluctus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 26, 'Ascendunt usque ad cælos, et descendunt usque ad abyssos; anima eorum in malis tabescebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 27, 'Turbati sunt, et moti sunt sicut ebrius, et omnis sapientia eorum devorata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 28, 'Et clamaverunt ad Dominum cum tribularentur; et de necessitatibus eorum eduxit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 29, 'Et statuit procellam ejus in auram, et siluerunt fluctus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 30, 'Et lætati sunt quia siluerunt; et deduxit eos in portum voluntatis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 31, 'Confiteantur Domino misericordiæ ejus, et mirabilia ejus filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 32, 'Et exaltent eum in ecclesia plebis, et in cathedra seniorum laudent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 33, 'Posuit flumina in desertum, et exitus aquarum in sitim;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 34, 'terram fructiferam in salsuginem, a malitia inhabitantium in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 35, 'Posuit desertum in stagna aquarum, et terram sine aqua in exitus aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 36, 'Et collocavit illic esurientes, et constituerunt civitatem habitationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 37, 'et seminaverunt agros et plantaverunt vineas, et fecerunt fructum nativitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 38, 'Et benedixit eis, et multiplicati sunt nimis; et jumenta eorum non minoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 39, 'Et pauci facti sunt et vexati sunt, a tribulatione malorum et dolore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 40, 'Effusa est contemptio super principes: et errare fecit eos in invio, et non in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 41, 'Et adjuvit pauperem de inopia, et posuit sicut oves familias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 42, 'Videbunt recti, et lætabuntur; et omnis iniquitas oppilabit os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 106, 43, 'Quis sapiens, et custodiet hæc, et intelliget misericordias Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 1, 'Canticum Psalmi, ipsi David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 2, 'Paratum cor meum, Deus, paratum cor meum; cantabo, et psallam in gloria mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 3, 'Exsurge, gloria mea; exsurge, psalterium et cithara; exsurgam diluculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 4, 'Confitebor tibi in populis, Domine, et psallam tibi in nationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 5, 'quia magna est super cælos misericordia tua, et usque ad nubes veritas tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 6, 'Exaltare super cælos, Deus, et super omnem terram gloria tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 7, 'ut liberentur dilecti tui. Salvum fac dextera tua, et exaudi me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 8, 'Deus locutus est in sancto suo: Exsultabo, et dividam Sichimam; et convallem tabernaculorum dimetiar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 9, 'Meus est Galaad, et meus est Manasses, et Ephraim susceptio capitis mei. Juda rex meus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 10, 'Moab lebes spei meæ: in Idumæam extendam calceamentum meum; mihi alienigenæ amici facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 11, 'Quis deducet me in civitatem munitam? quis deducet me usque in Idumæam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 12, 'nonne tu, Deus, qui repulisti nos? et non exibis, Deus, in virtutibus nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 13, 'Da nobis auxilium de tribulatione, quia vana salus hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 107, 14, 'In Deo faciemus virtutem; et ipse ad nihilum deducet inimicos nostros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 2, 'Deus, laudem meam ne tacueris, quia os peccatoris et os dolosi super me apertum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 3, 'Locuti sunt adversum me lingua dolosa, et sermonibus odii circumdederunt me: et expugnaverunt me gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 4, 'Pro eo ut me diligerent, detrahebant mihi; ego autem orabam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 5, 'Et posuerunt adversum me mala pro bonis, et odium pro dilectione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 6, 'Constitue super eum peccatorem, et diabolus stet a dextris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 7, 'Cum judicatur, exeat condemnatus; et oratio ejus fiat in peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 8, 'Fiant dies ejus pauci, et episcopatum ejus accipiat alter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 9, 'Fiant filii ejus orphani, et uxor ejus vidua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 10, 'Nutantes transferantur filii ejus et mendicent, et ejiciantur de habitationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 11, 'Scrutetur fœnerator omnem substantiam ejus, et diripiant alieni labores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 12, 'Non sit illi adjutor, nec sit qui misereatur pupillis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 13, 'Fiant nati ejus in interitum; in generatione una deleatur nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 14, 'In memoriam redeat iniquitas patrum ejus in conspectu Domini, et peccatum matris ejus non deleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 15, 'Fiant contra Dominum semper, et dispereat de terra memoria eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 16, 'pro eo quod non est recordatus facere misericordiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 17, 'et persecutus est hominem inopem et mendicum, et compunctum corde, mortificare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 18, 'Et dilexit maledictionem, et veniet ei; et noluit benedictionem, et elongabitur ab eo. Et induit maledictionem sicut vestimentum; et intravit sicut aqua in interiora ejus, et sicut oleum in ossibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 19, 'Fiat ei sicut vestimentum quo operitur, et sicut zona qua semper præcingitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 20, 'Hoc opus eorum qui detrahunt mihi apud Dominum, et qui loquuntur mala adversus animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 21, 'Et tu, Domine, Domine, fac mecum propter nomen tuum, quia suavis est misericordia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 22, 'Libera me, quia egenus et pauper ego sum, et cor meum conturbatum est intra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 23, 'Sicut umbra cum declinat ablatus sum, et excussus sum sicut locustæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 24, 'Genua mea infirmata sunt a jejunio, et caro mea immutata est propter oleum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 25, 'Et ego factus sum opprobrium illis; viderunt me, et moverunt capita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 26, 'Adjuva me, Domine Deus meus; salvum me fac secundum misericordiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 27, 'Et sciant quia manus tua hæc, et tu, Domine, fecisti eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 28, 'Maledicent illi, et tu benedices: qui insurgunt in me confundantur; servus autem tuus lætabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 29, 'Induantur qui detrahunt mihi pudore, et operiantur sicut diploide confusione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 30, 'Confitebor Domino nimis in ore meo, et in medio multorum laudabo eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 108, 31, 'quia astitit a dextris pauperis, ut salvam faceret a persequentibus animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 1, 'Psalmus David. Dixit Dominus Domino meo: Sede a dextris meis, donec ponam inimicos tuos scabellum pedum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 2, 'Virgam virtutis tuæ emittet Dominus ex Sion: dominare in medio inimicorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 3, 'Tecum principium in die virtutis tuæ in splendoribus sanctorum: ex utero, ante luciferum, genui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 4, 'Juravit Dominus, et non pœnitebit eum: Tu es sacerdos in æternum secundum ordinem Melchisedech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 5, 'Dominus a dextris tuis; confregit in die iræ suæ reges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 6, 'Judicabit in nationibus, implebit ruinas; conquassabit capita in terra multorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 109, 7, 'De torrente in via bibet; propterea exaltabit caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 1, 'Alleluja. Confitebor tibi, Domine, in toto corde meo, in consilio justorum, et congregatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 2, 'Magna opera Domini: exquisita in omnes voluntates ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 3, 'Confessio et magnificentia opus ejus, et justitia ejus manet in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 4, 'Memoriam fecit mirabilium suorum, misericors et miserator Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 5, 'Escam dedit timentibus se; memor erit in sæculum testamenti sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 6, 'Virtutem operum suorum annuntiabit populo suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 7, 'ut det illis hæreditatem gentium. Opera manuum ejus veritas et judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 8, 'Fidelia omnia mandata ejus, confirmata in sæculum sæculi, facta in veritate et æquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 9, 'Redemptionem misit populo suo; mandavit in æternum testamentum suum. Sanctum et terribile nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 110, 10, 'Initium sapientiæ timor Domini; intellectus bonus omnibus facientibus eum: laudatio ejus manet in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 1, 'Alleluja, reversionis Aggæi et Zachariæ. Beatus vir qui timet Dominum: in mandatis ejus volet nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 2, 'Potens in terra erit semen ejus; generatio rectorum benedicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 3, 'Gloria et divitiæ in domo ejus, et justitia ejus manet in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 4, 'Exortum est in tenebris lumen rectis: misericors, et miserator, et justus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 5, 'Jucundus homo qui miseretur et commodat; disponet sermones suos in judicio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 6, 'quia in æternum non commovebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 7, 'In memoria æterna erit justus; ab auditione mala non timebit. Paratum cor ejus sperare in Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 8, 'confirmatum est cor ejus; non commovebitur donec despiciat inimicos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 9, 'Dispersit, dedit pauperibus; justitia ejus manet in sæculum sæculi: cornu ejus exaltabitur in gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 111, 10, 'Peccator videbit, et irascetur; dentibus suis fremet et tabescet: desiderium peccatorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 1, 'Alleluja. Laudate, pueri, Dominum; laudate nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 2, 'Sit nomen Domini benedictum ex hoc nunc et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 3, 'A solis ortu usque ad occasum laudabile nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 4, 'Excelsus super omnes gentes Dominus, et super cælos gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 5, 'Quis sicut Dominus Deus noster, qui in altis habitat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 6, 'et humilia respicit in cælo et in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 7, 'Suscitans a terra inopem, et de stercore erigens pauperem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 8, 'ut collocet eum cum principibus, cum principibus populi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 112, 9, 'Qui habitare facit sterilem in domo, matrem filiorum lætantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 1, 'Alleluja. In exitu Israël de \'gypto, domus Jacob de populo barbaro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 2, 'facta est Judæa sanctificatio ejus; Israël potestas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 3, 'Mare vidit, et fugit; Jordanis conversus est retrorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 4, 'Montes exsultaverunt ut arietes, et colles sicut agni ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 5, 'Quid est tibi, mare, quod fugisti? et tu, Jordanis, quia conversus es retrorsum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 6, 'montes, exsultastis sicut arietes? et colles, sicut agni ovium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 7, 'A facie Domini mota est terra, a facie Dei Jacob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 8, 'qui convertit petram in stagna aquarum, et rupem in fontes aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 9, 'Non nobis, Domine, non nobis, sed nomini tuo da gloriam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 10, 'super misericordia tua et veritate tua; nequando dicant gentes: Ubi est Deus eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 11, 'Deus autem noster in cælo; omnia quæcumque voluit fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 12, 'Simulacra gentium argentum et aurum, opera manuum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 13, 'Os habent, et non loquentur; oculos habent, et non videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 14, 'Aures habent, et non audient; nares habent, et non odorabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 15, 'Manus habent, et non palpabunt; pedes habent, et non ambulabunt; non clamabunt in gutture suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 16, 'Similes illis fiant qui faciunt ea, et omnes qui confidunt in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 17, 'Domus Israël speravit in Domino; adjutor eorum et protector eorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 18, 'Domus Aaron speravit in Domino; adjutor eorum et protector eorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 19, 'Qui timent Dominum speraverunt in Domino; adjutor eorum et protector eorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 20, 'Dominus memor fuit nostri, et benedixit nobis. Benedixit domui Israël; benedixit domui Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 21, 'Benedixit omnibus qui timent Dominum, pusillis cum majoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 22, 'Adjiciat Dominus super vos, super vos et super filios vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 23, 'Benedicti vos a Domino, qui fecit cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 24, 'Cælum cæli Domino; terram autem dedit filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 25, 'Non mortui laudabunt te, Domine, neque omnes qui descendunt in infernum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 113, 26, 'sed nos qui vivimus, benedicimus Domino, ex hoc nunc et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 1, 'Alleluja. Dilexi, quoniam exaudiet Dominus vocem orationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 2, 'Quia inclinavit aurem suam mihi, et in diebus meis invocabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 3, 'Circumdederunt me dolores mortis; et pericula inferni invenerunt me. Tribulationem et dolorem inveni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 4, 'et nomen Domini invocavi: o Domine, libera animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 5, 'Misericors Dominus et justus, et Deus noster miseretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 6, 'Custodiens parvulos Dominus; humiliatus sum, et liberavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 7, 'Convertere, anima mea, in requiem tuam, quia Dominus benefecit tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 8, 'quia eripuit animam meam de morte, oculos meos a lacrimis, pedes meos a lapsu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 114, 9, 'Placebo Domino in regione vivorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 1, 'Alleluja. Credidi, propter quod locutus sum; ego autem humiliatus sum nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 2, 'Ego dixi in excessu meo: Omnis homo mendax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 3, 'Quid retribuam Domino pro omnibus quæ retribuit mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 4, 'Calicem salutaris accipiam, et nomen Domini invocabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 5, 'Vota mea Domino reddam coram omni populo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 6, 'Pretiosa in conspectu Domini mors sanctorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 7, 'O Domine, quia ego servus tuus; ego servus tuus, et filius ancillæ tuæ. Dirupisti vincula mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 8, 'tibi sacrificabo hostiam laudis, et nomen Domini invocabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 9, 'Vota mea Domino reddam in conspectu omnis populi ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 115, 10, 'in atriis domus Domini, in medio tui, Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 116, 1, 'Alleluja. Laudate Dominum, omnes gentes; laudate eum, omnes populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 116, 2, 'Quoniam confirmata est super nos misericordia ejus, et veritas Domini manet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 1, 'Alleluja. Confitemini Domino, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 2, 'Dicat nunc Israël: Quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 3, 'Dicat nunc domus Aaron: Quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 4, 'Dicant nunc qui timent Dominum: Quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 5, 'De tribulatione invocavi Dominum, et exaudivit me in latitudine Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 6, 'Dominus mihi adjutor; non timebo quid faciat mihi homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 7, 'Dominus mihi adjutor, et ego despiciam inimicos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 8, 'Bonum est confidere in Domino, quam confidere in homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 9, 'Bonum est sperare in Domino, quam sperare in principibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 10, 'Omnes gentes circuierunt me, et in nomine Domini, quia ultus sum in eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 11, 'Circumdantes circumdederunt me, et in nomine Domini, quia ultus sum in eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 12, 'Circumdederunt me sicut apes, et exarserunt sicut ignis in spinis: et in nomine Domini, quia ultus sum in eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 13, 'Impulsus eversus sum, ut caderem, et Dominus suscepit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 14, 'Fortitudo mea et laus mea Dominus, et factus est mihi in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 15, 'Vox exsultationis et salutis in tabernaculis justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 16, 'Dextera Domini fecit virtutem; dextera Domini exaltavit me: dextera Domini fecit virtutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 17, 'Non moriar, sed vivam, et narrabo opera Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 18, 'Castigans castigavit me Dominus, et morti non tradidit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 19, 'Aperite mihi portas justitiæ: ingressus in eas confitebor Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 20, 'Hæc porta Domini: justi intrabunt in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 21, 'Confitebor tibi quoniam exaudisti me, et factus es mihi in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 22, 'Lapidem quem reprobaverunt ædificantes, hic factus est in caput anguli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 23, 'A Domino factum est istud, et est mirabile in oculis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 24, 'Hæc est dies quam fecit Dominus; exsultemus, et lætemur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 25, 'O Domine, salvum me fac; o Domine, bene prosperare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 26, 'Benedictus qui venit in nomine Domini: benediximus vobis de domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 27, 'Deus Dominus, et illuxit nobis. Constituite diem solemnem in condensis, usque ad cornu altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 28, 'Deus meus es tu, et confitebor tibi; Deus meus es tu, et exaltabo te. Confitebor tibi quoniam exaudisti me, et factus es mihi in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 117, 29, 'Confitemini Domino, quoniam bonus, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 1, 'Alleluja. Beati immaculati in via, qui ambulant in lege Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 2, 'Beati qui scrutantur testimonia ejus; in toto corde exquirunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 3, 'Non enim qui operantur iniquitatem in viis ejus ambulaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 4, 'Tu mandasti mandata tua custodiri nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 5, 'Utinam dirigantur viæ meæ ad custodiendas justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 6, 'Tunc non confundar, cum perspexero in omnibus mandatis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 7, 'Confitebor tibi in directione cordis, in eo quod didici judicia justitiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 8, 'Justificationes tuas custodiam; non me derelinquas usquequaque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 9, 'In quo corrigit adolescentior viam suam? in custodiendo sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 10, 'In toto corde meo exquisivi te; ne repellas me a mandatis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 11, 'In corde meo abscondi eloquia tua, ut non peccem tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 12, 'Benedictus es, Domine; doce me justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 13, 'In labiis meis pronuntiavi omnia judicia oris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 14, 'In via testimoniorum tuorum delectatus sum, sicut in omnibus divitiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 15, 'In mandatis tuis exercebor, et considerabo vias tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 16, 'In justificationibus tuis meditabor: non obliviscar sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 17, 'Retribue servo tuo, vivifica me, et custodiam sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 18, 'Revela oculos meos, et considerabo mirabilia de lege tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 19, 'Incola ego sum in terra: non abscondas a me mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 20, 'Concupivit anima mea desiderare justificationes tuas in omni tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 21, 'Increpasti superbos; maledicti qui declinant a mandatis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 22, 'Aufer a me opprobrium et contemptum, quia testimonia tua exquisivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 23, 'Etenim sederunt principes, et adversum me loquebantur; servus autem tuus exercebatur in justificationibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 24, 'Nam et testimonia tua meditatio mea est, et consilium meum justificationes tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 25, 'Adhæsit pavimento anima mea: vivifica me secundum verbum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 26, 'Vias meas enuntiavi, et exaudisti me; doce me justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 27, 'Viam justificationum tuarum instrue me, et exercebor in mirabilibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 28, 'Dormitavit anima mea præ tædio: confirma me in verbis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 29, 'Viam iniquitatis amove a me, et de lege tua miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 30, 'Viam veritatis elegi; judicia tua non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 31, 'Adhæsi testimoniis tuis, Domine; noli me confundere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 32, 'Viam mandatorum tuorum cucurri, cum dilatasti cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 33, 'Legem pone mihi, Domine, viam justificationum tuarum, et exquiram eam semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 34, 'Da mihi intellectum, et scrutabor legem tuam, et custodiam illam in toto corde meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 35, 'Deduc me in semitam mandatorum tuorum, quia ipsam volui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 36, 'Inclina cor meum in testimonia tua, et non in avaritiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 37, 'Averte oculos meos, ne videant vanitatem; in via tua vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 38, 'Statue servo tuo eloquium tuum in timore tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 39, 'Amputa opprobrium meum quod suspicatus sum, quia judicia tua jucunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 40, 'Ecce concupivi mandata tua: in æquitate tua vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 41, 'Et veniat super me misericordia tua, Domine; salutare tuum secundum eloquium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 42, 'Et respondebo exprobrantibus mihi verbum, quia speravi in sermonibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 43, 'Et ne auferas de ore meo verbum veritatis usquequaque, quia in judiciis tuis supersperavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 44, 'Et custodiam legem tuam semper, in sæculum et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 45, 'Et ambulabam in latitudine, quia mandata tua exquisivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 46, 'Et loquebar in testimoniis tuis in conspectu regum, et non confundebar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 47, 'Et meditabar in mandatis tuis, quæ dilexi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 48, 'Et levavi manus meas ad mandata tua, quæ dilexi, et exercebar in justificationibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 49, 'Memor esto verbi tui servo tuo, in quo mihi spem dedisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 50, 'Hæc me consolata est in humilitate mea, quia eloquium tuum vivificavit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 51, 'Superbi inique agebant usquequaque; a lege autem tua non declinavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 52, 'Memor fui judiciorum tuorum a sæculo, Domine, et consolatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 53, 'Defectio tenuit me, pro peccatoribus derelinquentibus legem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 54, 'Cantabiles mihi erant justificationes tuæ in loco peregrinationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 55, 'Memor fui nocte nominis tui, Domine, et custodivi legem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 56, 'Hæc facta est mihi, quia justificationes tuas exquisivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 57, 'Portio mea, Domine, dixi custodire legem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 58, 'Deprecatus sum faciem tuam in toto corde meo; miserere mei secundum eloquium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 59, 'Cogitavi vias meas, et converti pedes meos in testimonia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 60, 'Paratus sum, et non sum turbatus, ut custodiam mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 61, 'Funes peccatorum circumplexi sunt me, et legem tuam non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 62, 'Media nocte surgebam ad confitendum tibi, super judicia justificationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 63, 'Particeps ego sum omnium timentium te, et custodientium mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 64, 'Misericordia tua, Domine, plena est terra; justificationes tuas doce me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 65, 'Bonitatem fecisti cum servo tuo, Domine, secundum verbum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 66, 'Bonitatem, et disciplinam, et scientiam doce me, quia mandatis tuis credidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 67, 'Priusquam humiliarer ego deliqui: propterea eloquium tuum custodivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 68, 'Bonus es tu, et in bonitate tua doce me justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 69, 'Multiplicata est super me iniquitas superborum; ego autem in toto corde meo scrutabor mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 70, 'Coagulatum est sicut lac cor eorum; ego vero legem tuam meditatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 71, 'Bonum mihi quia humiliasti me, ut discam justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 72, 'Bonum mihi lex oris tui, super millia auri et argenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 73, 'Manus tuæ fecerunt me, et plasmaverunt me: da mihi intellectum, et discam mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 74, 'Qui timent te videbunt me et lætabuntur, quia in verba tua supersperavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 75, 'Cognovi, Domine, quia æquitas judicia tua, et in veritate tua humiliasti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 76, 'Fiat misericordia tua ut consoletur me, secundum eloquium tuum servo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 77, 'Veniant mihi miserationes tuæ, et vivam, quia lex tua meditatio mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 78, 'Confundantur superbi, quia injuste iniquitatem fecerunt in me; ego autem exercebor in mandatis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 79, 'Convertantur mihi timentes te, et qui noverunt testimonia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 80, 'Fiat cor meum immaculatum in justificationibus tuis, ut non confundar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 81, 'Defecit in salutare tuum anima mea, et in verbum tuum supersperavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 82, 'Defecerunt oculi mei in eloquium tuum, dicentes: Quando consolaberis me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 83, 'Quia factus sum sicut uter in pruina; justificationes tuas non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 84, 'Quot sunt dies servi tui? quando facies de persequentibus me judicium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 85, 'Narraverunt mihi iniqui fabulationes, sed non ut lex tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 86, 'Omnia mandata tua veritas: inique persecuti sunt me, adjuva me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 87, 'Paulominus consummaverunt me in terra; ego autem non dereliqui mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 88, 'Secundum misericordiam tuam vivifica me, et custodiam testimonia oris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 89, 'In æternum, Domine, verbum tuum permanet in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 90, 'In generationem et generationem veritas tua; fundasti terram, et permanet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 91, 'Ordinatione tua perseverat dies, quoniam omnia serviunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 92, 'Nisi quod lex tua meditatio mea est, tunc forte periissem in humilitate mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 93, 'In æternum non obliviscar justificationes tuas, quia in ipsis vivificasti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 94, 'Tuus sum ego; salvum me fac: quoniam justificationes tuas exquisivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 95, 'Me exspectaverunt peccatores ut perderent me; testimonia tua intellexi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 96, 'Omnis consummationis vidi finem, latum mandatum tuum nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 97, 'Quomodo dilexi legem tuam, Domine! tota die meditatio mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 98, 'Super inimicos meos prudentem me fecisti mandato tuo, quia in æternum mihi est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 99, 'Super omnes docentes me intellexi, quia testimonia tua meditatio mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 100, 'Super senes intellexi, quia mandata tua quæsivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 101, 'Ab omni via mala prohibui pedes meos, ut custodiam verba tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 102, 'A judiciis tuis non declinavi, quia tu legem posuisti mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 103, 'Quam dulcia faucibus meis eloquia tua! super mel ori meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 104, 'A mandatis tuis intellexi; propterea odivi omnem viam iniquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 105, 'Lucerna pedibus meis verbum tuum, et lumen semitis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 106, 'Juravi et statui custodire judicia justitiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 107, 'Humiliatus sum usquequaque, Domine; vivifica me secundum verbum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 108, 'Voluntaria oris mei beneplacita fac, Domine, et judicia tua doce me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 109, 'Anima mea in manibus meis semper, et legem tuam non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 110, 'Posuerunt peccatores laqueum mihi, et de mandatis tuis non erravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 111, 'Hæreditate acquisivi testimonia tua in æternum, quia exsultatio cordis mei sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 112, 'Inclinavi cor meum ad faciendas justificationes tuas in æternum, propter retributionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 113, 'Iniquos odio habui, et legem tuam dilexi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 114, 'Adjutor et susceptor meus es tu, et in verbum tuum supersperavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 115, 'Declinate a me, maligni, et scrutabor mandata Dei mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 116, 'Suscipe me secundum eloquium tuum, et vivam, et non confundas me ab exspectatione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 117, 'Adjuva me, et salvus ero, et meditabor in justificationibus tuis semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 118, 'Sprevisti omnes discedentes a judiciis tuis, quia injusta cogitatio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 119, 'Prævaricantes reputavi omnes peccatores terræ; ideo dilexi testimonia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 120, 'Confige timore tuo carnes meas; a judiciis enim tuis timui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 121, 'Feci judicium et justitiam: non tradas me calumniantibus me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 122, 'Suscipe servum tuum in bonum: non calumnientur me superbi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 123, 'Oculi mei defecerunt in salutare tuum, et in eloquium justitiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 124, 'Fac cum servo tuo secundum misericordiam tuam, et justificationes tuas doce me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 125, 'Servus tuus sum ego: da mihi intellectum, ut sciam testimonia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 126, 'Tempus faciendi, Domine: dissipaverunt legem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 127, 'Ideo dilexi mandata tua super aurum et topazion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 128, 'Propterea ad omnia mandata tua dirigebar; omnem viam iniquam odio habui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 129, 'Mirabilia testimonia tua: ideo scrutata est ea anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 130, 'Declaratio sermonum tuorum illuminat, et intellectum dat parvulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 131, 'Os meum aperui, et attraxi spiritum: quia mandata tua desiderabam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 132, 'Aspice in me, et miserere mei, secundum judicium diligentium nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 133, 'Gressus meos dirige secundum eloquium tuum, et non dominetur mei omnis injustitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 134, 'Redime me a calumniis hominum ut custodiam mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 135, 'Faciem tuam illumina super servum tuum, et doce me justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 136, 'Exitus aquarum deduxerunt oculi mei, quia non custodierunt legem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 137, 'Justus es, Domine, et rectum judicium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 138, 'Mandasti justitiam testimonia tua, et veritatem tuam nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 139, 'Tabescere me fecit zelus meus, quia obliti sunt verba tua inimici mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 140, 'Ignitum eloquium tuum vehementer, et servus tuus dilexit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 141, 'Adolescentulus sum ego et contemptus; justificationes tuas non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 142, 'Justitia tua, justitia in æternum, et lex tua veritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 143, 'Tribulatio et angustia invenerunt me; mandata tua meditatio mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 144, '\'quitas testimonia tua in æternum: intellectum da mihi, et vivam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 145, 'Clamavi in toto corde meo: exaudi me, Domine; justificationes tuas requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 146, 'Clamavi ad te; salvum me fac: ut custodiam mandata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 147, 'Præveni in maturitate, et clamavi: quia in verba tua supersperavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 148, 'Prævenerunt oculi mei ad te diluculo, ut meditarer eloquia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 149, 'Vocem meam audi secundum misericordiam tuam, Domine, et secundum judicium tuum vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 150, 'Appropinquaverunt persequentes me iniquitati: a lege autem tua longe facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 151, 'Prope es tu, Domine, et omnes viæ tuæ veritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 152, 'Initio cognovi de testimoniis tuis, quia in æternum fundasti ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 153, 'Vide humilitatem meam, et eripe me, quia legem tuam non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 154, 'Judica judicium meum, et redime me: propter eloquium tuum vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 155, 'Longe a peccatoribus salus, quia justificationes tuas non exquisierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 156, 'Misericordiæ tuæ multæ, Domine; secundum judicium tuum vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 157, 'Multi qui persequuntur me, et tribulant me; a testimoniis tuis non declinavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 158, 'Vidi prævaricantes et tabescebam, quia eloquia tua non custodierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 159, 'Vide quoniam mandata tua dilexi, Domine: in misericordia tua vivifica me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 160, 'Principium verborum tuorum veritas; in æternum omnia judicia justitiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 161, 'Principes persecuti sunt me gratis, et a verbis tuis formidavit cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 162, 'Lætabor ego super eloquia tua, sicut qui invenit spolia multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 163, 'Iniquitatem odio habui, et abominatus sum, legem autem tuam dilexi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 164, 'Septies in die laudem dixi tibi, super judicia justitiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 165, 'Pax multa diligentibus legem tuam, et non est illis scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 166, 'Exspectabam salutare tuum, Domine, et mandata tua dilexi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 167, 'Custodivit anima mea testimonia tua, et dilexit ea vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 168, 'Servavi mandata tua et testimonia tua, quia omnes viæ meæ in conspectu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 169, 'Appropinquet deprecatio mea in conspectu tuo, Domine; juxta eloquium tuum da mihi intellectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 170, 'Intret postulatio mea in conspectu tuo; secundum eloquium tuum eripe me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 171, 'Eructabunt labia mea hymnum, cum docueris me justificationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 172, 'Pronuntiabit lingua mea eloquium tuum, quia omnia mandata tua æquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 173, 'Fiat manus tua ut salvet me, quoniam mandata tua elegi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 174, 'Concupivi salutare tuum, Domine, et lex tua meditatio mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 175, 'Vivet anima mea, et laudabit te, et judicia tua adjuvabunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 118, 176, 'Erravi sicut ovis quæ periit: quære servum tuum, quia mandata tua non sum oblitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 1, 'Canticum graduum. Ad Dominum cum tribularer clamavi, et exaudivit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 2, 'Domine, libera animam meam a labiis iniquis et a lingua dolosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 3, 'Quid detur tibi, aut quid apponatur tibi ad linguam dolosam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 4, 'Sagittæ potentis acutæ, cum carbonibus desolatoriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 5, 'Heu mihi, quia incolatus meus prolongatus est! habitavi cum habitantibus Cedar;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 6, 'multum incola fuit anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 119, 7, 'Cum his qui oderunt pacem eram pacificus; cum loquebar illis, impugnabant me gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 1, 'Canticum graduum. Levavi oculos meos in montes, unde veniet auxilium mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 2, 'Auxilium meum a Domino, qui fecit cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 3, 'Non det in commotionem pedem tuum, neque dormitet qui custodit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 4, 'Ecce non dormitabit neque dormiet qui custodit Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 5, 'Dominus custodit te; Dominus protectio tua super manum dexteram tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 6, 'Per diem sol non uret te, neque luna per noctem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 7, 'Dominus custodit te ab omni malo; custodiat animam tuam Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 120, 8, 'Dominus custodiat introitum tuum et exitum tuum, ex hoc nunc et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 1, 'Canticum graduum. Lætatus sum in his quæ dicta sunt mihi: In domum Domini ibimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 2, 'Stantes erant pedes nostri in atriis tuis, Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 3, 'Jerusalem, quæ ædificatur ut civitas, cujus participatio ejus in idipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 4, 'Illuc enim ascenderunt tribus, tribus Domini: testimonium Israël, ad confitendum nomini Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 5, 'Quia illic sederunt sedes in judicio, sedes super domum David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 6, 'Rogate quæ ad pacem sunt Jerusalem, et abundantia diligentibus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 7, 'Fiat pax in virtute tua, et abundantia in turribus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 8, 'Propter fratres meos et proximos meos, loquebar pacem de te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 121, 9, 'Propter domum Domini Dei nostri, quæsivi bona tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 122, 1, 'Canticum graduum. Ad te levavi oculos meos, qui habitas in cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 122, 2, 'Ecce sicut oculi servorum in manibus dominorum suorum; sicut oculi ancillæ in manibus dominæ suæ: ita oculi nostri ad Dominum Deum nostrum, donec misereatur nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 122, 3, 'Miserere nostri, Domine, miserere nostri, quia multum repleti sumus despectione;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 122, 4, 'quia multum repleta est anima nostra opprobrium abundantibus, et despectio superbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 1, 'Canticum graduum. Nisi quia Dominus erat in nobis, dicat nunc Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 2, 'nisi quia Dominus erat in nobis: cum exsurgerent homines in nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 3, 'forte vivos deglutissent nos; cum irasceretur furor eorum in nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 4, 'forsitan aqua absorbuisset nos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 5, 'torrentem pertransivit anima nostra; forsitan pertransisset anima nostra aquam intolerabilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 6, 'Benedictus Dominus, qui non dedit nos in captionem dentibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 7, 'Anima nostra sicut passer erepta est de laqueo venantium; laqueus contritus est, et nos liberati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 123, 8, 'Adjutorium nostrum in nomine Domini, qui fecit cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 124, 1, 'Canticum graduum. Qui confidunt in Domino, sicut mons Sion: non commovebitur in æternum, qui habitat');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 124, 2, 'in Jerusalem. Montes in circuitu ejus; et Dominus in circuitu populi sui, ex hoc nunc et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 124, 3, 'Quia non relinquet Dominus virgam peccatorum super sortem justorum: ut non extendant justi ad iniquitatem manus suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 124, 4, 'benefac, Domine, bonis, et rectis corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 124, 5, 'Declinantes autem in obligationes, adducet Dominus cum operantibus iniquitatem. Pax super Israël!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 1, 'Canticum graduum. In convertendo Dominus captivitatem Sion, facti sumus sicut consolati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 2, 'Tunc repletum est gaudio os nostrum, et lingua nostra exsultatione. Tunc dicent inter gentes: Magnificavit Dominus facere cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 3, 'Magnificavit Dominus facere nobiscum; facti sumus lætantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 4, 'Converte, Domine, captivitatem nostram, sicut torrens in austro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 5, 'Qui seminant in lacrimis, in exsultatione metent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 6, 'Euntes ibant et flebant, mittentes semina sua. Venientes autem venient cum exsultatione, portantes manipulos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 125, 7, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 126, 1, 'Canticum graduum Salomonis. Nisi Dominus ædificaverit domum, in vanum laboraverunt qui ædificant eam. Nisi Dominus custodierit civitatem, frustra vigilat qui custodit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 126, 2, 'Vanum est vobis ante lucem surgere: surgite postquam sederitis, qui manducatis panem doloris. Cum dederit dilectis suis somnum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 126, 3, 'ecce hæreditas Domini, filii; merces, fructus ventris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 126, 4, 'Sicut sagittæ in manu potentis, ita filii excussorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 126, 5, 'Beatus vir qui implevit desiderium suum ex ipsis: non confundetur cum loquetur inimicis suis in porta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 1, 'Canticum graduum. Beati omnes qui timent Dominum, qui ambulant in viis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 2, 'Labores manuum tuarum quia manducabis: beatus es, et bene tibi erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 3, 'Uxor tua sicut vitis abundans in lateribus domus tuæ; filii tui sicut novellæ olivarum in circuitu mensæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 4, 'Ecce sic benedicetur homo qui timet Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 5, 'Benedicat tibi Dominus ex Sion, et videas bona Jerusalem omnibus diebus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 127, 6, 'Et videas filios filiorum tuorum: pacem super Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 1, 'Canticum graduum. Sæpe expugnaverunt me a juventute mea, dicat nunc Israël;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 2, 'sæpe expugnaverunt me a juventute mea: etenim non potuerunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 3, 'Supra dorsum meum fabricaverunt peccatores; prolongaverunt iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 4, 'Dominus justus concidit cervices peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 5, 'Confundantur, et convertantur retrorsum omnes qui oderunt Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 6, 'Fiant sicut fœnum tectorum, quod priusquam evellatur exaruit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 7, 'de quo non implevit manum suam qui metit, et sinum suum qui manipulos colligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 128, 8, 'Et non dixerunt qui præteribant: Benedictio Domini super vos. Benediximus vobis in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 1, 'Canticum graduum. De profundis clamavi ad te, Domine;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 2, 'Domine, exaudi vocem meam. Fiant aures tuæ intendentes in vocem deprecationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 3, 'Si iniquitates observaveris, Domine, Domine, quis sustinebit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 4, 'Quia apud te propitiatio est; et propter legem tuam sustinui te, Domine. Sustinuit anima mea in verbo ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 5, 'speravit anima mea in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 6, 'A custodia matutina usque ad noctem, speret Israël in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 7, 'Quia apud Dominum misericordia, et copiosa apud eum redemptio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 129, 8, 'Et ipse redimet Israël ex omnibus iniquitatibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 130, 1, 'Canticum graduum David. Domine, non est exaltatum cor meum, neque elati sunt oculi mei, neque ambulavi in magnis, neque in mirabilibus super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 130, 2, 'Si non humiliter sentiebam, sed exaltavi animam meam: sicut ablactatus est super matre sua, ita retributio in anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 130, 3, 'Speret Israël in Domino, ex hoc nunc et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 1, 'Canticum graduum. Memento, Domine, David, et omnis mansuetudinis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 2, 'sicut juravit Domino; votum vovit Deo Jacob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 3, 'Si introiero in tabernaculum domus meæ; si ascendero in lectum strati mei;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 4, 'si dedero somnum oculis meis, et palpebris meis dormitationem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 5, 'et requiem temporibus meis, donec inveniam locum Domino, tabernaculum Deo Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 6, 'Ecce audivimus eam in Ephrata; invenimus eam in campis silvæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 7, 'Introibimus in tabernaculum ejus; adorabimus in loco ubi steterunt pedes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 8, 'Surge, Domine, in requiem tuam, tu et arca sanctificationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 9, 'Sacerdotes tui induantur justitiam, et sancti tui exsultent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 10, 'Propter David servum tuum non avertas faciem christi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 11, 'Juravit Dominus David veritatem, et non frustrabitur eam: De fructu ventris tui ponam super sedem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 12, 'Si custodierint filii tui testamentum meum, et testimonia mea hæc quæ docebo eos, et filii eorum usque in sæculum sedebunt super sedem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 13, 'Quoniam elegit Dominus Sion: elegit eam in habitationem sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 14, 'Hæc requies mea in sæculum sæculi; hic habitabo, quoniam elegi eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 15, 'Viduam ejus benedicens benedicam; pauperes ejus saturabo panibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 16, 'Sacerdotes ejus induam salutari, et sancti ejus exsultatione exsultabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 17, 'Illuc producam cornu David; paravi lucernam christo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 131, 18, 'Inimicos ejus induam confusione; super ipsum autem efflorebit sanctificatio mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 132, 1, 'Canticum graduum David. Ecce quam bonum et quam jucundum, habitare fratres in unum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 132, 2, 'Sicut unguentum in capite, quod descendit in barbam, barbam Aaron, quod descendit in oram vestimenti ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 132, 3, 'sicut ros Hermon, qui descendit in montem Sion. Quoniam illic mandavit Dominus benedictionem, et vitam usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 133, 1, 'Canticum graduum. Ecce nunc benedicite Dominum, omnes servi Domini: qui statis in domo Domini, in atriis domus Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 133, 2, 'In noctibus extollite manus vestras in sancta, et benedicite Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 133, 3, 'Benedicat te Dominus ex Sion, qui fecit cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 1, 'Alleluja. Laudate nomen Domini; laudate, servi, Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 2, 'qui statis in domo Domini, in atriis domus Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 3, 'Laudate Dominum, quia bonus Dominus; psallite nomini ejus, quoniam suave.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 4, 'Quoniam Jacob elegit sibi Dominus; Israël in possessionem sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 5, 'Quia ego cognovi quod magnus est Dominus, et Deus noster præ omnibus diis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 6, 'Omnia quæcumque voluit Dominus fecit, in cælo, in terra, in mari et in omnibus abyssis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 7, 'Educens nubes ab extremo terræ, fulgura in pluviam fecit; qui producit ventos de thesauris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 8, 'Qui percussit primogenita \'gypti, ab homine usque ad pecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 9, 'Et misit signa et prodigia in medio tui, \'gypte: in Pharaonem, et in omnes servos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 10, 'Qui percussit gentes multas, et occidit reges fortes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 11, 'Sehon, regem Amorrhæorum, et Og, regem Basan, et omnia regna Chanaan:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 12, 'et dedit terram eorum hæreditatem, hæreditatem Israël populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 13, 'Domine, nomen tuum in æternum; Domine, memoriale tuum in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 14, 'Quia judicabit Dominus populum suum, et in servis suis deprecabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 15, 'Simulacra gentium argentum et aurum, opera manuum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 16, 'Os habent, et non loquentur; oculos habent, et non videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 17, 'Aures habent, et non audient; neque enim est spiritus in ore ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 18, 'Similes illis fiant qui faciunt ea, et omnes qui confidunt in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 19, 'Domus Israël, benedicite Domino; domus Aaron, benedicite Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 20, 'Domus Levi, benedicite Domino; qui timetis Dominum, benedicite Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 134, 21, 'Benedictus Dominus ex Sion, qui habitat in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 1, 'Alleluja. Confitemini Domino, quoniam bonus, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 2, 'Confitemini Deo deorum, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 3, 'Confitemini Domino dominorum, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 4, 'Qui facit mirabilia magna solus, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 5, 'Qui fecit cælos in intellectu, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 6, 'Qui firmavit terram super aquas, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 7, 'Qui fecit luminaria magna, quoniam in æternum misericordia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 8, 'solem in potestatem diei, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 9, 'lunam et stellas in potestatem noctis, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 10, 'Qui percussit \'gyptum cum primogenitis eorum, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 11, 'Qui eduxit Israël de medio eorum, quoniam in æternum misericordia ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 12, 'in manu potenti et brachio excelso, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 13, 'Qui divisit mare Rubrum in divisiones, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 14, 'et eduxit Israël per medium ejus, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 15, 'et excussit Pharaonem et virtutem ejus in mari Rubro, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 16, 'Qui traduxit populum suum per desertum, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 17, 'Qui percussit reges magnos, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 18, 'et occidit reges fortes, quoniam in æternum misericordia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 19, 'Sehon, regem Amorrhæorum, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 20, 'et Og, regem Basan, quoniam in æternum misericordia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 21, 'et dedit terram eorum hæreditatem, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 22, 'hæreditatem Israël, servo suo, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 23, 'Quia in humilitate nostra memor fuit nostri, quoniam in æternum misericordia ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 24, 'et redemit nos ab inimicis nostris, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 25, 'Qui dat escam omni carni, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 26, 'Confitemini Deo cæli, quoniam in æternum misericordia ejus. Confitemini Domino dominorum, quoniam in æternum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 135, 27, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 1, 'Psalmus David, Jeremiæ. Super flumina Babylonis illic sedimus et flevimus, cum recordaremur Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 2, 'In salicibus in medio ejus suspendimus organa nostra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 3, 'quia illic interrogaverunt nos, qui captivos duxerunt nos, verba cantionum; et qui abduxerunt nos: Hymnum cantate nobis de canticis Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 4, 'Quomodo cantabimus canticum Domini in terra aliena?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 5, 'Si oblitus fuero tui, Jerusalem, oblivioni detur dextera mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 6, 'Adhæreat lingua mea faucibus meis, si non meminero tui; si non proposuero Jerusalem in principio lætitiæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 7, 'Memor esto, Domine, filiorum Edom, in die Jerusalem: qui dicunt: Exinanite, exinanite usque ad fundamentum in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 8, 'Filia Babylonis misera! beatus qui retribuet tibi retributionem tuam quam retribuisti nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 136, 9, 'Beatus qui tenebit, et allidet parvulos tuos ad petram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 1, 'Ipsi David. Confitebor tibi, Domine, in toto corde meo, quoniam audisti verba oris mei. In conspectu angelorum psallam tibi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 2, 'adorabo ad templum sanctum tuum, et confitebor nomini tuo: super misericordia tua et veritate tua; quoniam magnificasti super omne, nomen sanctum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 3, 'In quacumque die invocavero te, exaudi me; multiplicabis in anima mea virtutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 4, 'Confiteantur tibi, Domine, omnes reges terræ, quia audierunt omnia verba oris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 5, 'Et cantent in viis Domini, quoniam magna est gloria Domini;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 6, 'quoniam excelsus Dominus, et humilia respicit, et alta a longe cognoscit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 7, 'Si ambulavero in medio tribulationis, vivificabis me; et super iram inimicorum meorum extendisti manum tuam, et salvum me fecit dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 137, 8, 'Dominus retribuet pro me. Domine, misericordia tua in sæculum; opera manuum tuarum ne despicias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 1, 'In finem, psalmus David. Domine, probasti me, et cognovisti me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 2, 'tu cognovisti sessionem meam et resurrectionem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 3, 'Intellexisti cogitationes meas de longe; semitam meam et funiculum meum investigasti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 4, 'et omnes vias meas prævidisti, quia non est sermo in lingua mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 5, 'Ecce, Domine, tu cognovisti omnia, novissima et antiqua. Tu formasti me, et posuisti super me manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 6, 'Mirabilis facta est scientia tua ex me; confortata est, et non potero ad eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 7, 'Quo ibo a spiritu tuo? et quo a facie tua fugiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 8, 'Si ascendero in cælum, tu illic es; si descendero in infernum, ades.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 9, 'Si sumpsero pennas meas diluculo, et habitavero in extremis maris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 10, 'etenim illuc manus tua deducet me, et tenebit me dextera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 11, 'Et dixi: Forsitan tenebræ conculcabunt me; et nox illuminatio mea in deliciis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 12, 'Quia tenebræ non obscurabuntur a te, et nox sicut dies illuminabitur: sicut tenebræ ejus, ita et lumen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 13, 'Quia tu possedisti renes meos; suscepisti me de utero matris meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 14, 'Confitebor tibi, quia terribiliter magnificatus es; mirabilia opera tua, et anima mea cognoscit nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 15, 'Non est occultatum os meum a te, quod fecisti in occulto; et substantia mea in inferioribus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 16, 'Imperfectum meum viderunt oculi tui, et in libro tuo omnes scribentur. Dies formabuntur, et nemo in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 17, 'Mihi autem nimis honorificati sunt amici tui, Deus; nimis confortatus est principatus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 18, 'Dinumerabo eos, et super arenam multiplicabuntur. Exsurrexi, et adhuc sum tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 19, 'Si occideris, Deus, peccatores, viri sanguinum, declinate a me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 20, 'quia dicitis in cogitatione: Accipient in vanitate civitates tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 21, 'Nonne qui oderunt te, Domine, oderam, et super inimicos tuos tabescebam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 22, 'Perfecto odio oderam illos, et inimici facti sunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 23, 'Proba me, Deus, et scito cor meum; interroga me, et cognosce semitas meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 138, 24, 'Et vide si via iniquitatis in me est, et deduc me in via æterna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 1, 'In finem. Psalmus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 2, 'Eripe me, Domine, ab homine malo; a viro iniquo eripe me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 3, 'Qui cogitaverunt iniquitates in corde, tota die constituebant prælia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 4, 'Acuerunt linguas suas sicut serpentis; venenum aspidum sub labiis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 5, 'Custodi me, Domine, de manu peccatoris, et ab hominibus iniquis eripe me. Qui cogitaverunt supplantare gressus meos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 6, 'absconderunt superbi laqueum mihi. Et funes extenderunt in laqueum; juxta iter, scandalum posuerunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 7, 'Dixi Domino: Deus meus es tu; exaudi, Domine, vocem deprecationis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 8, 'Domine, Domine, virtus salutis meæ, obumbrasti super caput meum in die belli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 9, 'Ne tradas me, Domine, a desiderio meo peccatori: cogitaverunt contra me; ne derelinquas me, ne forte exaltentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 10, 'Caput circuitus eorum: labor labiorum ipsorum operiet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 11, 'Cadent super eos carbones; in ignem dejicies eos: in miseriis non subsistent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 12, 'Vir linguosus non dirigetur in terra; virum injustum mala capient in interitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 13, 'Cognovi quia faciet Dominus judicium inopis, et vindictam pauperum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 139, 14, 'Verumtamen justi confitebuntur nomini tuo, et habitabunt recti cum vultu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 1, 'Psalmus David. Domine, clamavi ad te: exaudi me; intende voci meæ, cum clamavero ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 2, 'Dirigatur oratio mea sicut incensum in conspectu tuo; elevatio manuum mearum sacrificium vespertinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 3, 'Pone, Domine, custodiam ori meo, et ostium circumstantiæ labiis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 4, 'Non declines cor meum in verba malitiæ, ad excusandas excusationes in peccatis; cum hominibus operantibus iniquitatem, et non communicabo cum electis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 5, 'Corripiet me justus in misericordia, et increpabit me: oleum autem peccatoris non impinguet caput meum. Quoniam adhuc et oratio mea in beneplacitis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 6, 'absorpti sunt juncti petræ judices eorum. Audient verba mea, quoniam potuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 7, 'Sicut crassitudo terræ erupta est super terram, dissipata sunt ossa nostra secus infernum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 8, 'Quia ad te, Domine, Domine, oculi mei; in te speravi, non auferas animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 9, 'Custodi me a laqueo quem statuerunt mihi, et a scandalis operantium iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 140, 10, 'Cadent in retiaculo ejus peccatores: singulariter sum ego, donec transeam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 1, 'Intellectus David, cum esset in spelunca, oratio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 2, 'Voce mea ad Dominum clamavi, voce mea ad Dominum deprecatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 3, 'Effundo in conspectu ejus orationem meam, et tribulationem meam ante ipsum pronuntio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 4, 'in deficiendo ex me spiritum meum, et tu cognovisti semitas meas. In via hac qua ambulabam absconderunt laqueum mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 5, 'Considerabam ad dexteram, et videbam, et non erat qui cognosceret me: periit fuga a me, et non est qui requirat animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 6, 'Clamavi ad te, Domine; dixi: Tu es spes mea, portio mea in terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 7, 'Intende ad deprecationem meam, quia humiliatus sum nimis. Libera me a persequentibus me, quia confortati sunt super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 141, 8, 'Educ de custodia animam meam ad confitendum nomini tuo; me exspectant justi donec retribuas mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 1, 'Psalmus David, quando persequebatur eum Absalom filius ejus. Domine, exaudi orationem meam; auribus percipe obsecrationem meam in veritate tua; exaudi me in tua justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 2, 'Et non intres in judicium cum servo tuo, quia non justificabitur in conspectu tuo omnis vivens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 3, 'Quia persecutus est inimicus animam meam; humiliavit in terra vitam meam; collocavit me in obscuris, sicut mortuos sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 4, 'Et anxiatus est super me spiritus meus; in me turbatum est cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 5, 'Memor fui dierum antiquorum; meditatus sum in omnibus operibus tuis: in factis manuum tuarum meditabar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 6, 'Expandi manus meas ad te; anima mea sicut terra sine aqua tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 7, 'Velociter exaudi me, Domine; defecit spiritus meus. Non avertas faciem tuam a me, et similis ero descendentibus in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 8, 'Auditam fac mihi mane misericordiam tuam, quia in te speravi. Notam fac mihi viam in qua ambulem, quia ad te levavi animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 9, 'Eripe me de inimicis meis, Domine: ad te confugi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 10, 'Doce me facere voluntatem tuam, quia Deus meus es tu. Spiritus tuus bonus deducet me in terram rectam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 11, 'Propter nomen tuum, Domine, vivificabis me: in æquitate tua, educes de tribulatione animam meam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 142, 12, 'et in misericordia tua disperdes inimicos meos, et perdes omnes qui tribulant animam meam, quoniam ego servus tuus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 1, 'Psalmus David. Adversus Goliath. Benedictus Dominus Deus meus, qui docet manus meas ad prælium, et digitos meos ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 2, 'Misericordia mea et refugium meum; susceptor meus et liberator meus; protector meus, et in ipso speravi, qui subdit populum meum sub me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 3, 'Domine, quid est homo, quia innotuisti ei? aut filius hominis, quia reputas eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 4, 'Homo vanitati similis factus est; dies ejus sicut umbra prætereunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 5, 'Domine, inclina cælos tuos, et descende; tange montes, et fumigabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 6, 'Fulgura coruscationem, et dissipabis eos; emitte sagittas tuas, et conturbabis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 7, 'Emitte manum tuam de alto: eripe me, et libera me de aquis multis, de manu filiorum alienorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 8, 'quorum os locutum est vanitatem, et dextera eorum dextera iniquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 9, 'Deus, canticum novum cantabo tibi; in psalterio decachordo psallam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 10, 'Qui das salutem regibus, qui redemisti David servum tuum de gladio maligno,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 11, 'eripe me, et erue me de manu filiorum alienorum, quorum os locutum est vanitatem, et dextera eorum dextera iniquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 12, 'Quorum filii sicut novellæ plantationes in juventute sua; filiæ eorum compositæ, circumornatæ ut similitudo templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 13, 'Promptuaria eorum plena, eructantia ex hoc in illud; oves eorum fœtosæ, abundantes in egressibus suis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 14, 'boves eorum crassæ. Non est ruina maceriæ, neque transitus, neque clamor in plateis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 143, 15, 'Beatum dixerunt populum cui hæc sunt; beatus populus cujus Dominus Deus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 1, 'Laudatio ipsi David. Exaltabo te, Deus meus rex, et benedicam nomini tuo in sæculum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 2, 'Per singulos dies benedicam tibi, et laudabo nomen tuum in sæculum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 3, 'Magnus Dominus, et laudabilis nimis, et magnitudinis ejus non est finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 4, 'Generatio et generatio laudabit opera tua, et potentiam tuam pronuntiabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 5, 'Magnificentiam gloriæ sanctitatis tuæ loquentur, et mirabilia tua narrabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 6, 'Et virtutem terribilium tuorum dicent, et magnitudinem tuam narrabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 7, 'Memoriam abundantiæ suavitatis tuæ eructabunt, et justitia tua exsultabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 8, 'Miserator et misericors Dominus: patiens, et multum misericors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 9, 'Suavis Dominus universis, et miserationes ejus super omnia opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 10, 'Confiteantur tibi, Domine, omnia opera tua, et sancti tui benedicant tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 11, 'Gloriam regni tui dicent, et potentiam tuam loquentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 12, 'ut notam faciant filiis hominum potentiam tuam, et gloriam magnificentiæ regni tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 13, 'Regnum tuum regnum omnium sæculorum; et dominatio tua in omni generatione et generationem. Fidelis Dominus in omnibus verbis suis, et sanctus in omnibus operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 14, 'Allevat Dominus omnes qui corruunt, et erigit omnes elisos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 15, 'Oculi omnium in te sperant, Domine, et tu das escam illorum in tempore opportuno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 16, 'Aperis tu manum tuam, et imples omne animal benedictione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 17, 'Justus Dominus in omnibus viis suis, et sanctus in omnibus operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 18, 'Prope est Dominus omnibus invocantibus eum, omnibus invocantibus eum in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 19, 'Voluntatem timentium se faciet, et deprecationem eorum exaudiet, et salvos faciet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 20, 'Custodit Dominus omnes diligentes se, et omnes peccatores disperdet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 144, 21, 'Laudationem Domini loquetur os meum; et benedicat omnis caro nomini sancto ejus in sæculum, et in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 1, 'Alleluja, Aggæi et Zachariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 2, 'Lauda, anima mea, Dominum. Laudabo Dominum in vita mea; psallam Deo meo quamdiu fuero. Nolite confidere in principibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 3, 'in filiis hominum, in quibus non est salus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 4, 'Exibit spiritus ejus, et revertetur in terram suam; in illa die peribunt omnes cogitationes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 5, 'Beatus cujus Deus Jacob adjutor ejus, spes ejus in Domino Deo ipsius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 6, 'qui fecit cælum et terram, mare, et omnia quæ in eis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 7, 'Qui custodit veritatem in sæculum; facit judicium injuriam patientibus; dat escam esurientibus. Dominus solvit compeditos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 8, 'Dominus illuminat cæcos. Dominus erigit elisos; Dominus diligit justos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 9, 'Dominus custodit advenas, pupillum et viduam suscipiet, et vias peccatorum disperdet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 145, 10, 'Regnabit Dominus in sæcula; Deus tuus, Sion, in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 1, 'Alleluja. Laudate Dominum, quoniam bonus est psalmus; Deo nostro sit jucunda, decoraque laudatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 2, '\'dificans Jerusalem Dominus, dispersiones Israëlis congregabit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 3, 'qui sanat contritos corde, et alligat contritiones eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 4, 'qui numerat multitudinem stellarum, et omnibus eis nomina vocat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 5, 'Magnus Dominus noster, et magna virtus ejus, et sapientiæ ejus non est numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 6, 'Suscipiens mansuetos Dominus; humilians autem peccatores usque ad terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 7, 'Præcinite Domino in confessione; psallite Deo nostro in cithara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 8, 'Qui operit cælum nubibus, et parat terræ pluviam; qui producit in montibus fœnum, et herbam servituti hominum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 9, 'qui dat jumentis escam ipsorum, et pullis corvorum invocantibus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 10, 'Non in fortitudine equi voluntatem habebit, nec in tibiis viri beneplacitum erit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 146, 11, 'Beneplacitum est Domino super timentes eum, et in eis qui sperant super misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 1, 'Alleluja. Lauda, Jerusalem, Dominum; lauda Deum tuum, Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 2, 'Quoniam confortavit seras portarum tuarum; benedixit filiis tuis in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 3, 'Qui posuit fines tuos pacem, et adipe frumenti satiat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 4, 'Qui emittit eloquium suum terræ: velociter currit sermo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 5, 'Qui dat nivem sicut lanam; nebulam sicut cinerem spargit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 6, 'Mittit crystallum suam sicut buccellas: ante faciem frigoris ejus quis sustinebit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 7, 'Emittet verbum suum, et liquefaciet ea; flabit spiritus ejus, et fluent aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 8, 'Qui annuntiat verbum suum Jacob, justitias et judicia sua Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 147, 9, 'Non fecit taliter omni nationi, et judicia sua non manifestavit eis. Alleluja.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 1, 'Alleluja. Laudate Dominum de cælis; laudate eum in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 2, 'Laudate eum, omnes angeli ejus; laudate eum, omnes virtutes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 3, 'Laudate eum, sol et luna; laudate eum, omnes stellæ et lumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 4, 'Laudate eum, cæli cælorum; et aquæ omnes quæ super cælos sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 5, 'laudent nomen Domini. Quia ipse dixit, et facta sunt; ipse mandavit, et creata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 6, 'Statuit ea in æternum, et in sæculum sæculi; præceptum posuit, et non præteribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 7, 'Laudate Dominum de terra, dracones et omnes abyssi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 8, 'ignis, grando, nix, glacies, spiritus procellarum, quæ faciunt verbum ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 9, 'montes, et omnes colles; ligna fructifera, et omnes cedri;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 10, 'bestiæ, et universa pecora; serpentes, et volucres pennatæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 11, 'reges terræ et omnes populi; principes et omnes judices terræ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 12, 'juvenes et virgines; senes cum junioribus, laudent nomen Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 13, 'quia exaltatum est nomen ejus solius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 148, 14, 'Confessio ejus super cælum et terram; et exaltavit cornu populi sui. Hymnus omnibus sanctis ejus; filiis Israël, populo appropinquanti sibi. Alleluja.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 1, 'Alleluja. Cantate Domino canticum novum; laus ejus in ecclesia sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 2, 'Lætetur Israël in eo qui fecit eum, et filii Sion exsultent in rege suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 3, 'Laudent nomen ejus in choro; in tympano et psalterio psallant ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 4, 'Quia beneplacitum est Domino in populo suo, et exaltabit mansuetos in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 5, 'Exsultabunt sancti in gloria; lætabuntur in cubilibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 6, 'Exaltationes Dei in gutture eorum, et gladii ancipites in manibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 7, 'ad faciendam vindictam in nationibus, increpationes in populis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 8, 'ad alligandos reges eorum in compedibus, et nobiles eorum in manicis ferreis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 149, 9, 'ut faciant in eis judicium conscriptum: gloria hæc est omnibus sanctis ejus. Alleluja.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 1, 'Alleluja. Laudate Dominum in sanctis ejus; laudate eum in firmamento virtutis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 2, 'Laudate eum in virtutibus ejus; laudate eum secundum multitudinem magnitudinis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 3, 'Laudate eum in sono tubæ; laudate eum in psalterio et cithara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 4, 'Laudate eum in tympano et choro; laudate eum in chordis et organo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 5, 'Laudate eum in cymbalis benesonantibus; laudate eum in cymbalis jubilationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 150, 6, 'Omnis spiritus laudet Dominum! Alleluja.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Parabolæ Salomonis, filii David, regis Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'ad sciendam sapientiam et disciplinam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'ad intelligenda verba prudentiæ, et suscipiendam eruditionem doctrinæ, justitiam, et judicium, et æquitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'ut detur parvulis astutia, adolescenti scientia et intellectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Audiens sapiens, sapientior erit, et intelligens gubernacula possidebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Animadvertet parabolam et interpretationem, verba sapientum et ænigmata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Timor Domini principium sapientiæ; sapientiam atque doctrinam stulti despiciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Audi, fili mi, disciplinam patris tui, et ne dimittas legem matris tuæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'ut addatur gratia capiti tuo, et torques collo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Fili mi, si te lactaverint peccatores, ne acquiescas eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Si dixerint: Veni nobiscum, insidiemur sanguini; abscondamus tendiculas contra insontem frustra;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'deglutiamus eum sicut infernus viventem, et integrum quasi descendentem in lacum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'omnem pretiosam substantiam reperiemus; implebimus domos nostras spoliis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'sortem mitte nobiscum, marsupium unum sit omnium nostrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'fili mi, ne ambules cum eis; prohibe pedem tuum a semitis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'pedes enim illorum ad malum currunt, et festinant ut effundant sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Frustra autem jacitur rete ante oculos pennatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 18, 'Ipsi quoque contra sanguinem suum insidiantur, et moliuntur fraudes contra animas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 19, 'Sic semitæ omnis avari: animas possidentium rapiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 20, 'Sapientia foris prædicat; in plateis dat vocem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 21, 'in capite turbarum clamitat; in foribus portarum urbis profert verba sua, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 22, 'Usquequo, parvuli, diligitis infantiam, et stulti ea quæ sibi sunt noxia cupient, et imprudentes odibunt scientiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 23, 'convertimini ad correptionem meam. En proferam vobis spiritum meum, et ostendam vobis verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 24, 'Quia vocavi, et renuistis; extendi manum meam, et non fuit qui aspiceret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 25, 'despexistis omne consilium meum, et increpationes meas neglexistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 26, 'Ego quoque in interitu vestro ridebo, et subsannabo cum vobis id quod timebatis advenerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 27, 'Cum irruerit repentina calamitas, et interitus quasi tempestas ingruerit; quando venerit super vos tribulatio et angustia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 28, 'tunc invocabunt me, et non exaudiam; mane consurgent, et non invenient me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 29, 'eo quod exosam habuerint disciplinam, et timorem Domini non susceperint,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 30, 'nec acquieverint consilio meo, et detraxerint universæ correptioni meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 31, 'Comedent igitur fructus viæ suæ, suisque consiliis saturabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 32, 'Aversio parvulorum interficiet eos, et prosperitas stultorum perdet illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 33, 'Qui autem me audierit, absque terrore requiescet, et abundantia perfruetur, timore malorum sublato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Fili mi, si susceperis sermones meos, et mandata mea absconderis penes te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'ut audiat sapientiam auris tua, inclina cor tuum ad cognoscendam prudentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Si enim sapientiam invocaveris, et inclinaveris cor tuum prudentiæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'si quæsieris eam quasi pecuniam, et sicut thesauros effoderis illam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'tunc intelliges timorem Domini, et scientiam Dei invenies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'quia Dominus dat sapientiam, et ex ore ejus prudentia et scientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Custodiet rectorum salutem, et proteget gradientes simpliciter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'servans semitas justitiæ, et vias sanctorum custodiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Tunc intelliges justitiam, et judicium, et æquitatem, et omnem semitam bonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Si intraverit sapientia cor tuum, et scientia animæ tuæ placuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'consilium custodiet te, et prudentia servabit te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'ut eruaris a via mala, et ab homine qui perversa loquitur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'qui relinquunt iter rectum, et ambulant per vias tenebrosas;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'qui lætantur cum malefecerint, et exsultant in rebus pessimis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'quorum viæ perversæ sunt, et infames gressus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Ut eruaris a muliere aliena, et ab extranea quæ mollit sermones suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'et relinquit ducem pubertatis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 18, 'et pacti Dei sui oblita est. Inclinata est enim ad mortem domus ejus, et ad inferos semitæ ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 19, 'Omnes qui ingrediuntur ad eam non revertentur, nec apprehendent semitas vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 20, 'Ut ambules in via bona, et calles justorum custodias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 21, 'qui enim recti sunt habitabunt in terra, et simplices permanebunt in ea;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 22, 'impii vero de terra perdentur, et qui inique agunt auferentur ex ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Fili mi, ne obliviscaris legis meæ, et præcepta mea cor tuum custodiat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'longitudinem enim dierum, et annos vitæ, et pacem, apponent tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Misericordia et veritas te non deserant; circumda eas gutturi tuo, et describe in tabulis cordis tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'et invenies gratiam, et disciplinam bonam, coram Deo et hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Habe fiduciam in Domino ex toto corde tuo, et ne innitaris prudentiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'In omnibus viis tuis cogita illum, et ipse diriget gressus tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Ne sis sapiens apud temetipsum; time Deum, et recede a malo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'sanitas quippe erit umbilico tuo, et irrigatio ossium tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Honora Dominum de tua substantia, et de primitiis omnium frugum tuarum da ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'et implebuntur horrea tua saturitate, et vino torcularia tua redundabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Disciplinam Domini, fili mi, ne abjicias, nec deficias cum ab eo corriperis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 12, 'quem enim diligit Dominus, corripit, et quasi pater in filio complacet sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 13, 'Beatus homo qui invenit sapientiam, et qui affluit prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 14, 'Melior est acquisitio ejus negotiatione argenti, et auri primi et purissimi fructus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 15, 'Pretiosior est cunctis opibus, et omnia quæ desiderantur huic non valent comparari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 16, 'Longitudo dierum in dextera ejus, et in sinistra illius divitiæ et gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 17, 'Viæ ejus viæ pulchræ, et omnes semitæ illius pacificæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 18, 'Lignum vitæ est his qui apprehenderint eam, et qui tenuerit eam beatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 19, 'Dominus sapientia fundavit terram; stabilivit cælos prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 20, 'Sapientia illius eruperunt abyssi, et nubes rore concrescunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 21, 'Fili mi, ne effluant hæc ab oculis tuis. Custodi legem atque consilium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 22, 'et erit vita animæ tuæ, et gratia faucibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 23, 'Tunc ambulabis fiducialiter in via tua, et pes tuus non impinget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 24, 'Si dormieris, non timebis; quiesces, et suavis erit somnus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 25, 'Ne paveas repentino terrore, et irruentes tibi potentias impiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 26, 'Dominus enim erit in latere tuo, et custodiet pedem tuum, ne capiaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 27, 'Noli prohibere benefacere eum qui potest: si vales, et ipse benefac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 28, 'Ne dicas amico tuo: Vade, et revertere: cras dabo tibi: cum statim possis dare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 29, 'Ne moliaris amico tuo malum, cum ille in te habeat fiduciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 30, 'Ne contendas adversus hominem frustra, cum ipse tibi nihil mali fecerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 31, 'Ne æmuleris hominem injustum, nec imiteris vias ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 32, 'quia abominatio Domini est omnis illusor, et cum simplicibus sermocinatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 33, 'Egestas a Domino in domo impii; habitacula autem justorum benedicentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 34, 'Ipse deludet illusores, et mansuetis dabit gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 35, 'Gloriam sapientes possidebunt; stultorum exaltatio ignominia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Audite, filii, disciplinam patris, et attendite ut sciatis prudentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Donum bonum tribuam vobis: legem meam ne derelinquatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Nam et ego filius fui patris mei, tenellus et unigenitus coram matre mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Et docebat me, atque dicebat: Suscipiat verba mea cor tuum; custodi præcepta mea, et vives.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Posside sapientiam, posside prudentiam: ne obliviscaris, neque declines a verbis oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Ne dimittas eam, et custodiet te: dilige eam, et conservabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Principium sapientiæ: posside sapientiam, et in omni possessione tua acquire prudentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Arripe illam, et exaltabit te; glorificaberis ab ea cum eam fueris amplexatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Dabit capiti tuo augmenta gratiarum, et corona inclyta proteget te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Audi, fili mi, et suscipe verba mea, ut multiplicentur tibi anni vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Viam sapientiæ monstrabo tibi; ducam te per semitas æquitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'quas cum ingressus fueris, non arctabuntur gressus tui, et currens non habebis offendiculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tene disciplinam, ne dimittas eam; custodi illam, quia ipsa est vita tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Ne delecteris in semitis impiorum, nec tibi placeat malorum via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Fuge ab ea, nec transeas per illam; declina, et desere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Non enim dormiunt nisi malefecerint, et rapitur somnus ab eis nisi supplantaverint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 17, 'Comedunt panem impietatis, et vinum iniquitatis bibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 18, 'Justorum autem semita quasi lux splendens procedit, et crescit usque ad perfectam diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 19, 'Via impiorum tenebrosa; nesciunt ubi corruant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 20, 'Fili mi, ausculta sermones meos, et ad eloquia mea inclina aurem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 21, 'Ne recedant ab oculis tuis: custodi ea in medio cordis tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 22, 'vita enim sunt invenientibus ea, et universæ carni sanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 23, 'Omni custodia serva cor tuum, quia ex ipso vita procedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 24, 'Remove a te os pravum, et detrahentia labia sint procul a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 25, 'Oculi tui recta videant, et palpebræ tuæ præcedant gressus tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 26, 'Dirige semitam pedibus tuis, et omnes viæ tuæ stabilientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 27, 'Ne declines ad dexteram neque ad sinistram; averte pedem tuum a malo: vias enim quæ a dextris sunt novit Dominus: perversæ vero sunt quæ a sinistris sunt. Ipse autem rectos faciet cursus tuos, itinera autem tua in pace producet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Fili mi, attende ad sapientiam meam, et prudentiæ meæ inclina aurem tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'ut custodias cogitationes, et disciplinam labia tua conservent. Ne attendas fallaciæ mulieris;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'favus enim distillans labia meretricis, et nitidius oleo guttur ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'novissima autem illius amara quasi absinthium, et acuta quasi gladius biceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Pedes ejus descendunt in mortem, et ad inferos gressus illius penetrant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Per semitam vitæ non ambulant; vagi sunt gressus ejus et investigabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Nunc ergo fili mi, audi me, et ne recedas a verbis oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Longe fac ab ea viam tuam, et ne appropinques foribus domus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Ne des alienis honorem tuum, et annos tuos crudeli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'ne forte impleantur extranei viribus tuis, et labores tui sint in domo aliena,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'et gemas in novissimis, quando consumpseris carnes tuas et corpus tuum, et dicas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Cur detestatus sum disciplinam, et increpationibus non acquievit cor meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'nec audivi vocem docentium me, et magistris non inclinavi aurem meam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'pene fui in omni malo, in medio ecclesiæ et synagogæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Bibe aquam de cisterna tua, et fluenta putei tui;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'deriventur fontes tui foras, et in plateis aquas tuas divide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 17, 'Habeto eas solus, nec sint alieni participes tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 18, 'Sit vena tua benedicta, et lætare cum muliere adolescentiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 19, 'Cerva carissima, et gratissimus hinnulus: ubera ejus inebrient te in omni tempore; in amore ejus delectare jugiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 20, 'Quare seduceris, fili mi, ab aliena, et foveris in sinu alterius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 21, 'Respicit Dominus vias hominis, et omnes gressus ejus considerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 22, 'Iniquitates suas capiunt impium, et funibus peccatorum suorum constringitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 23, 'Ipse morietur, quia non habuit disciplinam, et in multitudine stultitiæ suæ decipietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Fili mi, si spoponderis pro amico tuo, defixisti apud extraneum manum tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'illaqueatus es verbis oris tui, et captus propriis sermonibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Fac ergo quod dico, fili mi, et temetipsum libera, quia incidisti in manum proximi tui. Discurre, festina, suscita amicum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Ne dederis somnum oculis tuis, nec dormitent palpebræ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Eruere quasi damula de manu, et quasi avis de manu aucupis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Vade ad formicam, o piger, et considera vias ejus, et disce sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Quæ cum non habeat ducem, nec præceptorem, nec principem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'parat in æstate cibum sibi, et congregat in messe quod comedat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Usquequo, piger, dormies? quando consurges e somno tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Paululum dormies, paululum dormitabis, paululum conseres manus ut dormias;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'et veniet tibi quasi viator egestas, et pauperies quasi vir armatus. Si vero impiger fueris, veniet ut fons messis tua, et egestas longe fugiet a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Homo apostata, vir inutilis, graditur ore perverso;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'annuit oculis, terit pede, digito loquitur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 14, 'pravo corde machinatur malum, et omni tempore jurgia seminat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 15, 'Huic extemplo veniet perditio sua, et subito conteretur, nec habebit ultra medicinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 16, 'Sex sunt quæ odit Dominus, et septimum detestatur anima ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 17, 'oculos sublimes, linguam mendacem, manus effundentes innoxium sanguinem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 18, 'cor machinans cogitationes pessimas, pedes veloces ad currendum in malum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 19, 'proferentem mendacia testem fallacem, et eum qui seminat inter fratres discordias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 20, 'Conserva, fili mi, præcepta patris tui, et ne dimittas legem matris tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 21, 'Liga ea in corde tuo jugiter, et circumda gutturi tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 22, 'Cum ambulaveris, gradiantur tecum; cum dormieris, custodiant te: et evigilans loquere cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 23, 'Quia mandatum lucerna est, et lex lux, et via vitæ increpatio disciplinæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 24, 'ut custodiant te a muliere mala, et a blanda lingua extraneæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 25, 'Non concupiscat pulchritudinem ejus cor tuum, nec capiaris nutibus illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 26, 'pretium enim scorti vix est unius panis, mulier autem viri pretiosam animam capit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 27, 'Numquid potest homo abscondere ignem in sinu suo, ut vestimenta illius non ardeant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 28, 'aut ambulare super prunas, ut non comburantur plantæ ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 29, 'sic qui ingreditur ad mulierem proximi sui, non erit mundus cum tetigerit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 30, 'Non grandis est culpa cum quis furatus fuerit: furatur enim ut esurientem impleat animam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 31, 'deprehensus quoque reddet septuplum, et omnem substantiam domus suæ tradet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 32, 'Qui autem adulter est, propter cordis inopiam perdet animam suam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 33, 'turpitudinem et ignominiam congregat sibi, et opprobrium illius non delebitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 34, 'quia zelus et furor viri non parcet in die vindictæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 35, 'nec acquiescet cujusquam precibus, nec suscipiet pro redemptione dona plurima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Fili mi, custodi sermones meos, et præcepta mea reconde tibi. Fili,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'serva mandata mea, et vives; et legem meam quasi pupillam oculi tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'liga eam in digitis tuis, scribe illam in tabulis cordis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Dic sapientiæ: Soror mea es, et prudentiam voca amicam tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'ut custodiant te a muliere extranea, et ab aliena quæ verba sua dulcia facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'De fenestra enim domus meæ per cancellos prospexi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'et video parvulos; considero vecordem juvenem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'qui transit per plateam juxta angulum et prope viam domus illius graditur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'in obscuro, advesperascente die, in noctis tenebris et caligine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Et ecce occurrit illi mulier ornatu meretricio, præparata ad capiendas animas: garrula et vaga,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'quietis impatiens, nec valens in domo consistere pedibus suis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'nunc foris, nunc in plateis, nunc juxta angulos insidians.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Apprehensumque deosculatur juvenem, et procaci vultu blanditur, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Victimas pro salute vovi; hodie reddidi vota mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 15, 'idcirco egressa sum in occursum tuum, desiderans te videre, et reperi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 16, 'Intexui funibus lectulum meum; stravi tapetibus pictis ex \'gypto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 17, 'aspersi cubile meum myrrha, et aloë, et cinnamomo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 18, 'Veni, inebriemur uberibus, et fruamur cupitis amplexibus donec illucescat dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 19, 'Non est enim vir in domo sua: abiit via longissima:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 20, 'sacculum pecuniæ secum tulit; in die plenæ lunæ reversurus est in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 21, 'Irretivit eum multis sermonibus, et blanditiis labiorum protraxit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 22, 'Statim eam sequitur quasi bos ductus ad victimam, et quasi agnus lasciviens, et ignorans quod ad vincula stultus trahatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 23, 'donec transfigat sagitta jecur ejus, velut si avis festinet ad laqueum, et nescit quod de periculo animæ illius agitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 24, 'Nunc ergo, fili mi, audi me, et attende verbis oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 25, 'Ne abstrahatur in viis illius mens tua, neque decipiaris semitis ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 26, 'multos enim vulneratos dejecit, et fortissimi quique interfecti sunt ab ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 27, 'Viæ inferi domus ejus, penetrantes in interiora mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Numquid non sapientia clamitat, et prudentia dat vocem suam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'In summis excelsisque verticibus supra viam, in mediis semitis stans,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'juxta portas civitatis, in ipsis foribus loquitur, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'O viri, ad vos clamito, et vox mea ad filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Intelligite, parvuli, astutiam, et insipientes, animadvertite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Audite, quoniam de rebus magnis locutura sum, et aperientur labia mea ut recta prædicent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Veritatem meditabitur guttur meum, et labia mea detestabuntur impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Justi sunt omnes sermones mei: non est in eis pravum quid, neque perversum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'recti sunt intelligentibus, et æqui invenientibus scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Accipite disciplinam meam, et non pecuniam; doctrinam magis quam aurum eligite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'melior est enim sapientia cunctis pretiosissimis, et omne desiderabile ei non potest comparari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ego sapientia, habito in consilio, et eruditis intersum cogitationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Timor Domini odit malum: arrogantiam, et superbiam, et viam pravam, et os bilingue, detestor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Meum est consilium et æquitas; mea est prudentia, mea est fortitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 15, 'Per me reges regnant, et legum conditores justa decernunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 16, 'per me principes imperant, et potentes decernunt justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 17, 'Ego diligentes me diligo, et qui mane vigilant ad me, invenient me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 18, 'Mecum sunt divitiæ et gloria, opes superbæ et justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 19, 'Melior est enim fructus meus auro et lapide pretioso, et genimina mea argento electo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 20, 'In viis justitiæ ambulo, in medio semitarum judicii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 21, 'ut ditem diligentes me, et thesauros eorum repleam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 22, 'Dominus possedit me in initio viarum suarum antequam quidquam faceret a principio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 23, 'Ab æterno ordinata sum, et ex antiquis antequam terra fieret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 24, 'Nondum erant abyssi, et ego jam concepta eram: necdum fontes aquarum eruperant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 25, 'necdum montes gravi mole constiterant: ante colles ego parturiebar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 26, 'Adhuc terram non fecerat, et flumina, et cardines orbis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 27, 'Quando præparabat cælos, aderam; quando certa lege et gyro vallabat abyssos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 28, 'quando æthera firmabat sursum, et librabat fontes aquarum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 29, 'quando circumdabat mari terminum suum, et legem ponebat aquis, ne transirent fines suos; quando appendebat fundamenta terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 30, 'cum eo eram, cuncta componens. Et delectabar per singulos dies, ludens coram eo omni tempore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 31, 'ludens in orbe terrarum; et deliciæ meæ esse cum filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 32, 'Nunc ergo, filii, audite me: beati qui custodiunt vias meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 33, 'Audite disciplinam, et estote sapientes, et nolite abjicere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 34, 'Beatus homo qui audit me, et qui vigilat ad fores meas quotidie, et observat ad postes ostii mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 35, 'Qui me invenerit, inveniet vitam, et hauriet salutem a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 36, 'Qui autem in me peccaverit, lædet animam suam; omnes qui me oderunt diligunt mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 1, 'Sapientia ædificavit sibi domum: excidit columnas septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 2, 'Immolavit victimas suas, miscuit vinum, et proposuit mensam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 3, 'Misit ancillas suas ut vocarent ad arcem et ad mœnia civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 4, 'Si quis est parvulus, veniat ad me. Et insipientibus locuta est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 5, 'Venite, comedite panem meum, et bibite vinum quod miscui vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 6, 'Relinquite infantiam, et vivite, et ambulate per vias prudentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 7, 'Qui erudit derisorem, ipse injuriam sibi facit, et qui arguit impium, sibi maculam generat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 8, 'Noli arguere derisorem, ne oderit te: argue sapientem, et diliget te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 9, 'Da sapienti occasionem, et addetur ei sapientia; doce justum, et festinabit accipere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 10, 'Principium sapientiæ timor Domini, et scientia sanctorum prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 11, 'Per me enim multiplicabuntur dies tui, et addentur tibi anni vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 12, 'Si sapiens fueris, tibimetipsi eris; si autem illusor, solus portabis malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 13, 'Mulier stulta et clamosa, plenaque illecebris, et nihil omnino sciens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 14, 'sedit in foribus domus suæ, super sellam in excelso urbis loco,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 15, 'ut vocaret transeuntes per viam, et pergentes itinere suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 16, 'Qui est parvulus declinet ad me. Et vecordi locuta est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 17, 'Aquæ furtivæ dulciores sunt, et panis absconditus suavior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 9, 18, 'Et ignoravit quod ibi sint gigantes, et in profundis inferni convivæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 1, 'Filius sapiens lætificat patrem, filius vero stultus mœstitia est matris suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 2, 'Nil proderunt thesauri impietatis, justitia vero liberabit a morte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 3, 'Non affliget Dominus fame animam justi, et insidias impiorum subvertet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 4, 'Egestatem operata est manus remissa; manus autem fortium divitias parat. Qui nititur mendaciis, hic pascit ventos; idem autem ipse sequitur aves volantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 5, 'Qui congregat in messe, filius sapiens est; qui autem stertit æstate, filius confusionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 6, 'Benedictio Domini super caput justi; os autem impiorum operit iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 7, 'Memoria justi cum laudibus, et nomen impiorum putrescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 8, 'Sapiens corde præcepta suscipit; stultus cæditur labiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 9, 'Qui ambulat simpliciter ambulat confidenter; qui autem depravat vias suas manifestus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 10, 'Qui annuit oculo dabit dolorem; et stultus labiis verberabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 11, 'Vena vitæ os justi, et os impiorum operit iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 12, 'Odium suscitat rixas, et universa delicta operit caritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 13, 'In labiis sapientis invenitur sapientia, et virga in dorso ejus qui indiget corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 14, 'Sapientes abscondunt scientiam; os autem stulti confusioni proximum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 15, 'Substantia divitis, urbs fortitudinis ejus; pavor pauperum egestas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 16, 'Opus justi ad vitam, fructus autem impii ad peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 17, 'Via vitæ custodienti disciplinam; qui autem increpationes relinquit, errat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 18, 'Abscondunt odium labia mendacia; qui profert contumeliam, insipiens est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 19, 'In multiloquio non deerit peccatum, qui autem moderatur labia sua prudentissimus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 20, 'Argentum electum lingua justi; cor autem impiorum pro nihilo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 21, 'Labia justi erudiunt plurimos; qui autem indocti sunt in cordis egestate morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 22, 'Benedictio Domini divites facit, nec sociabitur eis afflictio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 23, 'Quasi per risum stultus operatur scelus, sapientia autem est viro prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 24, 'Quod timet impius veniet super eum; desiderium suum justus dabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 25, 'Quasi tempestas transiens non erit impius; justus autem quasi fundamentum sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 26, 'Sicut acetum dentibus, et fumus oculis, sic piger his qui miserunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 27, 'Timor Domini apponet dies, et anni impiorum breviabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 28, 'Exspectatio justorum lætitia, spes autem impiorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 29, 'Fortitudo simplicis via Domini, et pavor his qui operantur malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 30, 'Justus in æternum non commovebitur, impii autem non habitabunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 31, 'Os justi parturiet sapientiam; lingua pravorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 10, 32, 'Labia justi considerant placita, et os impiorum perversa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 1, 'Statera dolosa abominatio est apud Dominum, et pondus æquum voluntas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 2, 'Ubi fuerit superbia, ibi erit et contumelia; ubi autem est humilitas, ibi et sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 3, 'Simplicitas justorum diriget eos, et supplantatio perversorum vastabit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 4, 'Non proderunt divitiæ in die ultionis; justitia autem liberabit a morte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 5, 'Justitia simplicis diriget viam ejus, et in impietate sua corruet impius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 6, 'Justitia rectorum liberabit eos, et in insidiis suis capientur iniqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 7, 'Mortuo homine impio, nulla erit ultra spes, et exspectatio sollicitorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 8, 'Justus de angustia liberatus est, et tradetur impius pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 9, 'Simulator ore decipit amicum suum; justi autem liberabuntur scientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 10, 'In bonis justorum exsultabit civitas, et in perditione impiorum erit laudatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 11, 'Benedictione justorum exaltabitur civitas, et ore impiorum subvertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 12, 'Qui despicit amicum suum indigens corde est; vir autem prudens tacebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 13, 'Qui ambulat fraudulenter, revelat arcana; qui autem fidelis est animi, celat amici commissum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 14, 'Ubi non est gubernator, populus corruet; salus autem, ubi multa consilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 15, 'Affligetur malo qui fidem facit pro extraneo; qui autem cavet laqueos securus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 16, 'Mulier gratiosa inveniet gloriam, et robusti habebunt divitias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 17, 'Benefacit animæ suæ vir misericors; qui autem crudelis est, etiam propinquos abjicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 18, 'Impius facit opus instabile, seminanti autem justitiam merces fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 19, 'Clementia præparat vitam, et sectatio malorum mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 20, 'Abominabile Domino cor pravum, et voluntas ejus in iis qui simpliciter ambulant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 21, 'Manus in manu non erit innocens malus; semen autem justorum salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 22, 'Circulus aureus in naribus suis, mulier pulchra et fatua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 23, 'Desiderium justorum omne bonum est; præstolatio impiorum furor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 24, 'Alii dividunt propria, et ditiores fiunt; alii rapiunt non sua, et semper in egestate sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 25, 'Anima quæ benedicit impinguabitur, et qui inebriat, ipse quoque inebriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 26, 'Qui abscondit frumenta maledicetur in populis; benedictio autem super caput vendentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 27, 'Bene consurgit diluculo qui quærit bona; qui autem investigator malorum est, opprimetur ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 28, 'Qui confidit in divitiis suis corruet: justi autem quasi virens folium germinabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 29, 'Qui conturbat domum suam possidebit ventos, et qui stultus est serviet sapienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 30, 'Fructus justi lignum vitæ, et qui suscipit animas sapiens est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 11, 31, 'Si justus in terra recipit, quanto magis impius et peccator!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 1, 'Qui diligit disciplinam diligit scientiam; qui autem odit increpationes insipiens est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 2, 'Qui bonus est hauriet gratiam a Domino; qui autem confidit in cogitationibus suis impie agit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 3, 'Non roborabitur homo ex impietate, et radix justorum non commovebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 4, 'Mulier diligens corona est viro suo; et putredo in ossibus ejus, quæ confusione res dignas gerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 5, 'Cogitationes justorum judicia, et consilia impiorum fraudulenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 6, 'Verba impiorum insidiantur sanguini; os justorum liberabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 7, 'Verte impios, et non erunt; domus autem justorum permanebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 8, 'Doctrina sua noscetur vir; qui autem vanus et excors est patebit contemptui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 9, 'Melior est pauper et sufficiens sibi quam gloriosus et indigens pane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 10, 'Novit justus jumentorum suorum animas; viscera autem impiorum crudelia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 11, 'Qui operatur terram suam satiabitur panibus; qui autem sectatur otium stultissimus est. Qui suavis est in vini demorationibus, in suis munitionibus relinquit contumeliam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 12, 'Desiderium impii munimentum est pessimorum; radix autem justorum proficiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 13, 'Propter peccata labiorum ruina proximat malo; effugiet autem justus de angustia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 14, 'De fructu oris sui unusquisque replebitur bonis, et juxta opera manuum suarum retribuetur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 15, 'Via stulti recta in oculis ejus; qui autem sapiens est audit consilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 16, 'Fatuus statim indicat iram suam; qui autem dissimulat injuriam callidus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 17, 'Qui quod novit loquitur, index justitiæ est; qui autem mentitur, testis est fraudulentus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 18, 'Est qui promittit, et quasi gladio pungitur conscientiæ: lingua autem sapientium sanitas est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 19, 'Labium veritatis firmum erit in perpetuum; qui autem testis est repentinus, concinnat linguam mendacii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 20, 'Dolus in corde cogitantium mala; qui autem pacis ineunt consilia, sequitur eos gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 21, 'Non contristabit justum quidquid ei acciderit: impii autem replebuntur malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 22, 'Abominatio est Domino labia mendacia; qui autem fideliter agunt placent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 23, 'Homo versatus celat scientiam, et cor insipientium provocat stultitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 24, 'Manus fortium dominabitur; quæ autem remissa est, tributis serviet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 25, 'Mœror in corde viri humiliabit illum, et sermone bono lætificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 26, 'Qui negligit damnum propter amicum, justus est; iter autem impiorum decipiet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 27, 'Non inveniet fraudulentus lucrum, et substantia hominis erit auri pretium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 12, 28, 'In semita justitiæ vita; iter autem devium ducit ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 1, 'Filius sapiens doctrina patris; qui autem illusor est non audit cum arguitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 2, 'De fructu oris sui homo satiabitur bonis: anima autem prævaricatorum iniqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 3, 'Qui custodit os suum custodit animam suam; qui autem inconsideratus est ad loquendum, sentiet mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 4, 'Vult et non vult piger; anima autem operantium impinguabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 5, 'Verbum mendax justus detestabitur; impius autem confundit, et confundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 6, 'Justitia custodit innocentis viam, impietas autem peccatorem supplantat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 7, 'Est quasi dives, cum nihil habeat, et est quasi pauper, cum in multis divitiis sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 8, 'Redemptio animæ viri divitiæ suæ; qui autem pauper est, increpationem non sustinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 9, 'Lux justorum lætificat: lucerna autem impiorum extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 10, 'Inter superbos semper jurgia sunt; qui autem agunt omnia cum consilio, reguntur sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 11, 'Substantia festinata minuetur; quæ autem paulatim colligitur manu, multiplicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 12, 'Spes quæ differtur affligit animam; lignum vitæ desiderium veniens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 13, 'Qui detrahit alicui rei, ipse se in futurum obligat; qui autem timet præceptum, in pace versabitur. Animæ dolosæ errant in peccatis: justi autem misericordes sunt, et miserantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 14, 'Lex sapientis fons vitæ, ut declinet a ruina mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 15, 'Doctrina bona dabit gratiam; in itinere contemptorum vorago.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 16, 'Astutus omnia agit cum consilio; qui autem fatuus est aperit stultitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 17, 'Nuntius impii cadet in malum; legatus autem fidelis, sanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 18, 'Egestas et ignominia ei qui deserit disciplinam; qui autem acquiescit arguenti glorificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 19, 'Desiderium si compleatur delectat animam; detestantur stulti eos qui fugiunt mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 20, 'Qui cum sapientibus graditur sapiens erit; amicus stultorum similis efficietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 21, 'Peccatores persequitur malum, et justis retribuentur bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 22, 'Bonus reliquit hæredes filios et nepotes, et custoditur justo substantia peccatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 23, 'Multi cibi in novalibus patrum, et aliis congregantur absque judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 24, 'Qui parcit virgæ odit filium suum; qui autem diligit illum instanter erudit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 13, 25, 'Justus comedit et replet animam suam; venter autem impiorum insaturabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 1, 'Sapiens mulier ædificat domum suam; insipiens exstructam quoque manibus destruet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 2, 'Ambulans recto itinere, et timens Deum, despicitur ab eo qui infami graditur via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 3, 'In ore stulti virga superbiæ; labia autem sapientium custodiunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 4, 'Ubi non sunt boves, præsepe vacuum est; ubi autem plurimæ segetes, ibi manifesta est fortitudo bovis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 5, 'Testis fidelis non mentitur; profert autem mendacium dolosus testis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 6, 'Quærit derisor sapientiam, et non invenit; doctrina prudentium facilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 7, 'Vade contra virum stultum, et nescit labia prudentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 8, 'Sapientia callidi est intelligere viam suam, et imprudentia stultorum errans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 9, 'Stultus illudet peccatum, et inter justos morabitur gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 10, 'Cor quod novit amaritudinem animæ suæ, in gaudio ejus non miscebitur extraneus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 11, 'Domus impiorum delebitur: tabernacula vero justorum germinabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 12, 'Est via quæ videtur homini justa, novissima autem ejus deducunt ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 13, 'Risus dolore miscebitur, et extrema gaudii luctus occupat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 14, 'Viis suis replebitur stultus, et super eum erit vir bonus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 15, 'Innocens credit omni verbo; astutus considerat gressus suos. Filio doloso nihil erit boni; servo autem sapienti prosperi erunt actus, et dirigetur via ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 16, 'Sapiens timet, et declinat a malo; stultus transilit, et confidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 17, 'Impatiens operabitur stultitiam, et vir versutus odiosus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 18, 'Possidebunt parvuli stultitiam, et exspectabunt astuti scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 19, 'Jacebunt mali ante bonos, et impii ante portas justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 20, 'Etiam proximo suo pauper odiosus erit: amici vero divitum multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 21, 'Qui despicit proximum suum peccat; qui autem miseretur pauperis beatus erit. Qui credit in Domino misericordiam diligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 22, 'Errant qui operantur malum; misericordia et veritas præparant bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 23, 'In omni opere erit abundantia; ubi autem verba sunt plurima, ibi frequenter egestas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 24, 'Corona sapientium divitiæ eorum; fatuitas stultorum imprudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 25, 'Liberat animas testis fidelis, et profert mendacia versipellis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 26, 'In timore Domini fiducia fortitudinis, et filiis ejus erit spes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 27, 'Timor Domini fons vitæ, ut declinent a ruina mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 28, 'In multitudine populi dignitas regis, et in paucitate plebis ignominia principis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 29, 'Qui patiens est multa gubernatur prudentia; qui autem impatiens est exaltat stultitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 30, 'Vita carnium sanitas cordis; putredo ossium invidia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 31, 'Qui calumniatur egentem exprobrat factori ejus; honorat autem eum qui miseretur pauperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 32, 'In malitia sua expelletur impius: sperat autem justus in morte sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 33, 'In corde prudentis requiescit sapientia, et indoctos quosque erudiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 34, 'Justitia elevat gentem; miseros autem facit populos peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 14, 35, 'Acceptus est regi minister intelligens; iracundiam ejus inutilis sustinebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 1, 'Responsio mollis frangit iram; sermo durus suscitat furorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 2, 'Lingua sapientium ornat scientiam; os fatuorum ebullit stultitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 3, 'In omni loco, oculi Domini contemplantur bonos et malos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 4, 'Lingua placabilis lignum vitæ; quæ autem immoderata est conteret spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 5, 'Stultus irridet disciplinam patris sui; qui autem custodit increpationes astutior fiet. In abundanti justitia virtus maxima est: cogitationes autem impiorum eradicabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 6, 'Domus justi plurima fortitudo, et in fructibus impii conturbatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 7, 'Labia sapientium disseminabunt scientiam; cor stultorum dissimile erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 8, 'Victimæ impiorum abominabiles Domino; vota justorum placabilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 9, 'Abominatio est Domino via impii; qui sequitur justitiam diligitur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 10, 'Doctrina mala deserenti viam vitæ; qui increpationes odit, morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 11, 'Infernus et perditio coram Domino; quanto magis corda filiorum hominum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 12, 'Non amat pestilens eum qui se corripit, nec ad sapientes graditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 13, 'Cor gaudens exhilarat faciem; in mœrore animi dejicitur spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 14, 'Cor sapientis quærit doctrinam, et os stultorum pascitur imperitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 15, 'Omnes dies pauperis, mali; secura mens quasi juge convivium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 16, 'Melius est parum cum timore Domini, quam thesauri magni et insatiabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 17, 'Melius est vocari ad olera cum caritate, quam ad vitulum saginatum cum odio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 18, 'Vir iracundus provocat rixas; qui patiens est mitigat suscitatas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 19, 'Iter pigrorum quasi sepes spinarum; via justorum absque offendiculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 20, 'Filius sapiens lætificat patrem, et stultus homo despicit matrem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 21, 'Stultitia gaudium stulto, et vir prudens dirigit gressus suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 22, 'Dissipantur cogitationes ubi non est consilium; ubi vero sunt plures consiliarii, confirmantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 23, 'Lætatur homo in sententia oris sui, et sermo opportunus est optimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 24, 'Semita vitæ super eruditum, ut declinet de inferno novissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 25, 'Domum superborum demolietur Dominus, et firmos faciet terminos viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 26, 'Abominatio Domini cogitationes malæ, et purus sermo pulcherrimus firmabitur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 27, 'Conturbat domum suam qui sectatur avaritiam; qui autem odit munera, vivet. Per misericordiam et fidem purgantur peccata: per timorem autem Domini declinat omnis a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 28, 'Mens justi meditatur obedientiam; os impiorum redundat malis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 29, 'Longe est Dominus ab impiis, et orationes justorum exaudiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 30, 'Lux oculorum lætificat animam; fama bona impinguat ossa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 31, 'Auris quæ audit increpationes vitæ in medio sapientium commorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 32, 'Qui abjicit disciplinam despicit animam suam; qui autem acquiescit increpationibus possessor est cordis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 15, 33, 'Timor Domini disciplina sapientiæ, et gloriam præcedit humilitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 1, 'Hominis est animam præparare, et Domini gubernare linguam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 2, 'Omnes viæ hominis patent oculis ejus; spirituum ponderator est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 3, 'Revela Domino opera tua, et dirigentur cogitationes tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 4, 'Universa propter semetipsum operatus est Dominus; impium quoque ad diem malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 5, 'Abominatio Domini est omnis arrogans; etiamsi manus ad manum fuerit, non est innocens. Initium viæ bonæ facere justitiam; accepta est autem apud Deum magis quam immolare hostias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 6, 'Misericordia et veritate redimitur iniquitas, et in timore Domini declinatur a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 7, 'Cum placuerint Domino viæ hominis, inimicos quoque ejus convertet ad pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 8, 'Melius est parum cum justitia quam multi fructus cum iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 9, 'Cor hominis disponit viam suam, sed Domini est dirigere gressus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 10, 'Divinatio in labiis regis; in judicio non errabit os ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 11, 'Pondus et statera judicia Domini sunt, et opera ejus omnes lapides sacculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 12, 'Abominabiles regi qui agunt impie, quoniam justitia firmatur solium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 13, 'Voluntas regum labia justa; qui recta loquitur diligetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 14, 'Indignatio regis nuntii mortis, et vir sapiens placabit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 15, 'In hilaritate vultus regis vita, et clementia ejus quasi imber serotinus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 16, 'Posside sapientiam, quia auro melior est, et acquire prudentiam, quia pretiosior est argento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 17, 'Semita justorum declinat mala; custos animæ suæ servat viam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 18, 'Contritionem præcedit superbia, et ante ruinam exaltatur spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 19, 'Melius est humiliari cum mitibus quam dividere spolia cum superbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 20, 'Eruditus in verbo reperiet bona, et qui sperat in Domino beatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 21, 'Qui sapiens est corde appellabitur prudens, et qui dulcis eloquio majora percipiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 22, 'Fons vitæ eruditio possidentis; doctrina stultorum fatuitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 23, 'Cor sapientis erudiet os ejus, et labiis ejus addet gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 24, 'Favus mellis composita verba; dulcedo animæ sanitas ossium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 25, 'Est via quæ videtur homini recta, et novissima ejus ducunt ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 26, 'Anima laborantis laborat sibi, quia compulit eum os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 27, 'Vir impius fodit malum, et in labiis ejus ignis ardescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 28, 'Homo perversus suscitat lites, et verbosus separat principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 29, 'Vir iniquus lactat amicum suum, et ducit eum per viam non bonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 30, 'Qui attonitis oculis cogitat prava, mordens labia sua perficit malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 31, 'Corona dignitatis senectus, quæ in viis justitiæ reperietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 32, 'Melior est patiens viro forti, et qui dominatur animo suo expugnatore urbium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 16, 33, 'Sortes mittuntur in sinum, sed a Domino temperantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 1, 'Melior est buccella sicca cum gaudio quam domus plena victimis cum jurgio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 2, 'Servus sapiens dominabitur filiis stultis, et inter fratres hæreditatem dividet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 3, 'Sicut igne probatur argentum et aurum camino, ita corda probat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 4, 'Malus obedit linguæ iniquæ, et fallax obtemperat labiis mendacibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 5, 'Qui despicit pauperem exprobrat factori ejus, et qui ruina lætatur alterius non erit impunitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 6, 'Corona senum filii filiorum, et gloria filiorum patres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 7, 'Non decent stultum verba composita, nec principem labium mentiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 8, 'Gemma gratissima exspectatio præstolantis; quocumque se vertit, prudenter intelligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 9, 'Qui celat delictum quærit amicitias; qui altero sermone repetit, separat fœderatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 10, 'Plus proficit correptio apud prudentem, quam centum plagæ apud stultum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 11, 'Semper jurgia quærit malus: angelus autem crudelis mittetur contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 12, 'Expedit magis ursæ occurrere raptis fœtibus, quam fatuo confidenti in stultitia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 13, 'Qui reddit mala pro bonis, non recedet malum de domo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 14, 'Qui dimittit aquam caput est jurgiorum, et antequam patiatur contumeliam judicium deserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 15, 'Qui justificat impium, et qui condemnat justum, abominabilis est uterque apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 16, 'Quid prodest stulto habere divitias, cum sapientiam emere non possit? Qui altum facit domum suam quærit ruinam, et qui evitat discere incidet in mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 17, 'Omni tempore diligit qui amicus est, et frater in angustiis comprobatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 18, 'Stultus homo plaudet manibus, cum spoponderit pro amico suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 19, 'Qui meditatur discordias diligit rixas, et qui exaltat ostium quærit ruinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 20, 'Qui perversi cordis est non inveniet bonum, et qui vertit linguam incidet in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 21, 'Natus est stultus in ignominiam suam; sed nec pater in fatuo lætabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 22, 'Animus gaudens ætatem floridam facit; spiritus tristis exsiccat ossa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 23, 'Munera de sinu impius accipit, ut pervertat semitas judicii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 24, 'In facie prudentis lucet sapientia; oculi stultorum in finibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 25, 'Ira patris filius stultus, et dolor matris quæ genuit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 26, 'Non est bonum damnum inferre justo, nec percutere principem qui recta judicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 27, 'Qui moderatur sermones suos doctus et prudens est, et pretiosi spiritus vir eruditus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 17, 28, 'Stultus quoque, si tacuerit, sapiens reputabitur, et si compresserit labia sua, intelligens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 1, 'Occasiones quærit qui vult recedere ab amico: omni tempore erit exprobrabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 2, 'Non recipit stultus verba prudentiæ, nisi ea dixeris quæ versantur in corde ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 3, 'Impius, cum in profundum venerit peccatorum, contemnit; sed sequitur eum ignominia et opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 4, 'Aqua profunda verba ex ore viri, et torrens redundans fons sapientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 5, 'Accipere personam impii non est bonum, ut declines a veritate judicii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 6, 'Labia stulti miscent se rixis, et os ejus jurgia provocat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 7, 'Os stulti contritio ejus, et labia ipsius ruina animæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 8, 'Verba bilinguis quasi simplicia, et ipsa perveniunt usque ad interiora ventris. Pigrum dejicit timor; animæ autem effeminatorum esurient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 9, 'Qui mollis et dissolutus est in opere suo frater est sua opera dissipantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 10, 'Turris fortissima nomen Domini; ad ipsum currit justus, et exaltabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 11, 'Substantia divitis urbs roboris ejus, et quasi murus validus circumdans eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 12, 'Antequam conteratur, exaltatur cor hominis, et antequam glorificetur, humiliatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 13, 'Qui prius respondet quam audiat, stultum se esse demonstrat, et confusione dignum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 14, 'Spiritus viri sustentat imbecillitatem suam; spiritum vero ad irascendum facilem quis poterit sustinere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 15, 'Cor prudens possidebit scientiam, et auris sapientium quærit doctrinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 16, 'Donum hominis dilatat viam ejus, et ante principes spatium ei facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 17, 'Justus prior est accusator sui: venit amicus ejus, et investigabit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 18, 'Contradictiones comprimit sors, et inter potentes quoque dijudicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 19, 'Frater qui adjuvatur a fratre quasi civitas firma, et judicia quasi vectes urbium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 20, 'De fructu oris viri replebitur venter ejus, et genimina labiorum ipsius saturabunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 21, 'Mors et vita in manu linguæ; qui diligunt eam comedent fructus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 22, 'Qui invenit mulierem bonam invenit bonum, et hauriet jucunditatem a Domino. Qui expellit mulierem bonam expellit bonum; qui autem tenet adulteram stultus est et impius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 23, 'Cum obsecrationibus loquetur pauper, et dives effabitur rigide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 18, 24, 'Vir amabilis ad societatem magis amicus erit quam frater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 1, 'Melior est pauper qui ambulat in simplicitate sua quam dives torquens labia sua, et insipiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 2, 'Ubi non est scientia animæ, non est bonum, et qui festinus est pedibus offendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 3, 'Stultitia hominis supplantat gressus ejus, et contra Deum fervet animo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 4, 'Divitiæ addunt amicos plurimos; a paupere autem et hi quos habuit separantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 5, 'Testis falsus non erit impunitus, et qui mendacia loquitur non effugiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 6, 'Multi colunt personam potentis, et amici sunt dona tribuentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 7, 'Fratres hominis pauperis oderunt eum; insuper et amici procul recesserunt ab eo. Qui tantum verba sectatur nihil habebit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 8, 'qui autem possessor est mentis diligit animam suam, et custos prudentiæ inveniet bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 9, 'Falsus testis non erit impunitus, et qui loquitur mendacia peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 10, 'Non decent stultum deliciæ, nec servum dominari principibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 11, 'Doctrina viri per patientiam noscitur, et gloria ejus est iniqua prætergredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 12, 'Sicut fremitus leonis, ita et regis ira, et sicut ros super herbam, ita et hilaritas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 13, 'Dolor patris filius stultus, et tecta jugiter perstillantia litigiosa mulier.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 14, 'Domus et divitiæ dantur a parentibus; a Domino autem proprie uxor prudens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 15, 'Pigredo immittit soporem, et anima dissoluta esuriet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 16, 'Qui custodit mandatum custodit animam suam; qui autem negligit viam suam mortificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 17, 'Fœneratur Domino qui miseretur pauperis, et vicissitudinem suam reddet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 18, 'Erudi filium tuum; ne desperes: ad interfectionem autem ejus ne ponas animam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 19, 'Qui impatiens est sustinebit damnum, et cum rapuerit, aliud apponet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 20, 'Audi consilium, et suscipe disciplinam, ut sis sapiens in novissimis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 21, 'Multæ cogitationes in corde viri; voluntas autem Domini permanebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 22, 'Homo indigens misericors est, et melior est pauper quam vir mendax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 23, 'Timor Domini ad vitam, et in plenitudine commorabitur absque visitatione pessima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 24, 'Abscondit piger manum suam sub ascella, nec ad os suum applicat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 25, 'Pestilente flagellato stultus sapientior erit; si autem corripueris sapientem, intelliget disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 26, 'Qui affligit patrem, et fugat matrem, ignominiosus est et infelix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 27, 'Non cesses, fili, audire doctrinam, nec ignores sermones scientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 28, 'Testis iniquus deridet judicium, et os impiorum devorat iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 19, 29, 'Parata sunt derisoribus judicia, et mallei percutientes stultorum corporibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 1, 'Luxuriosa res vinum, et tumultuosa ebrietas: quicumque his delectatur non erit sapiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 2, 'Sicut rugitus leonis, ita et terror regis: qui provocat eum peccat in animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 3, 'Honor est homini qui separat se a contentionibus; omnes autem stulti miscentur contumeliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 4, 'Propter frigus piger arare noluit; mendicabit ergo æstate, et non dabitur illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 5, 'Sicut aqua profunda, sic consilium in corde viri; sed homo sapiens exhauriet illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 6, 'Multi homines misericordes vocantur; virum autem fidelem quis inveniet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 7, 'Justus qui ambulat in simplicitate sua beatos post se filios derelinquet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 8, 'Rex qui sedet in solio judicii dissipat omne malum intuitu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 9, 'Quis potest dicere: Mundum est cor meum; purus sum a peccato?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 10, 'Pondus et pondus, mensura et mensura: utrumque abominabile est apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 11, 'Ex studiis suis intelligitur puer, si munda et recta sint opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 12, 'Aurem audientem, et oculum videntem: Dominus fecit utrumque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 13, 'Noli diligere somnum, ne te egestas opprimat: aperi oculos tuos, et saturare panibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 14, 'Malum est, malum est, dicit omnis emptor; et cum recesserit, tunc gloriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 15, 'Est aurum et multitudo gemmarum, et vas pretiosum labia scientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 16, 'Tolle vestimentum ejus qui fidejussor extitit alieni, et pro extraneis aufer pignus ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 17, 'Suavis est homini panis mendacii, et postea implebitur os ejus calculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 18, 'Cogitationes consiliis roborantur, et gubernaculis tractanda sunt bella.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 19, 'Ei qui revelat mysteria, et ambulat fraudulenter, et dilatat labia sua, ne commiscearis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 20, 'Qui maledicit patri suo et matri, extinguetur lucerna ejus in mediis tenebris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 21, 'hæreditas ad quam festinatur in principio, in novissimo benedictione carebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 22, 'Ne dicas: Reddam malum: exspecta Dominum, et liberabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 23, 'Abominatio est apud Dominum pondus et pondus; statera dolosa non est bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 24, 'A Domino diriguntur gressus viri: quis autem hominum intelligere potest viam suam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 25, 'Ruina est homini devorare sanctos, et post vota retractare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 26, 'Dissipat impios rex sapiens, et incurvat super eos fornicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 27, 'Lucerna Domini spiraculum hominis, quæ investigat omnia secreta ventris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 28, 'Misericordia et veritas custodiunt regem, et roboratur clementia thronus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 29, 'Exsultatio juvenum fortitudo eorum, et dignitas senum canities.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 20, 30, 'Livor vulneris absterget mala, et plagæ in secretioribus ventris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 1, 'Sicut divisiones aquarum, ita cor regis in manu Domini: quocumque voluerit, inclinabit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 2, 'Omnis via viri recta sibi videtur: appendit autem corda Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 3, 'Facere misericordiam et judicium magis placet Domino quam victimæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 4, 'Exaltatio oculorum est dilatatio cordis; lucerna impiorum peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 5, 'Cogitationes robusti semper in abundantia; omnis autem piger semper in egestate est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 6, 'Qui congregat thesauros lingua mendacii vanus et excors est, et impingetur ad laqueos mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 7, 'Rapinæ impiorum detrahent eos, quia noluerunt facere judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 8, 'Perversa via viri aliena est; qui autem mundus est, rectum opus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 9, 'Melius est sedere in angulo domatis, quam cum muliere litigiosa, et in domo communi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 10, 'Anima impii desiderat malum: non miserebitur proximo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 11, 'Mulctato pestilente, sapientior erit parvulus, et si sectetur sapientem, sumet scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 12, 'Excogitat justus de domo impii, ut detrahat impios a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 13, 'Qui obturat aurem suam ad clamorem pauperis, et ipse clamabit, et non exaudietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 14, 'Munus absconditum extinguit iras, et donum in sinu indignationem maximam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 15, 'Gaudium justo est facere judicium, et pavor operantibus iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 16, 'Vir qui erraverit a via doctrinæ in cœtu gigantum commorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 17, 'Qui diligit epulas in egestate erit; qui amat vinum et pinguia non ditabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 18, 'Pro justo datur impius, et pro rectis iniquus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 19, 'Melius est habitare in terra deserta quam cum muliere rixosa et iracunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 20, 'Thesaurus desiderabilis, et oleum in habitaculo justi: et imprudens homo dissipabit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 21, 'Qui sequitur justitiam et misericordiam inveniet vitam, justitiam, et gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 22, 'Civitatem fortium ascendit sapiens, et destruxit robur fiduciæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 23, 'Qui custodit os suum et linguam suam custodit ab angustiis animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 24, 'Superbus et arrogans vocatur indoctus, qui in ira operatur superbiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 25, 'Desideria occidunt pigrum: noluerunt enim quidquam manus ejus operari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 26, 'Tota die concupiscit et desiderat; qui autem justus est, tribuet, et non cessabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 27, 'Hostiæ impiorum abominabiles, quia offeruntur ex scelere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 28, 'Testis mendax peribit; vir obediens loquetur victoriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 29, 'Vir impius procaciter obfirmat vultum suum; qui autem rectus est corrigit viam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 30, 'Non est sapientia, non est prudentia, non est consilium contra Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 21, 31, 'Equus paratur ad diem belli; Dominus autem salutem tribuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 1, 'Melius est nomen bonum quam divitiæ multæ; super argentum et aurum gratia bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 2, 'Dives et pauper obviaverunt sibi: utriusque operator est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 3, 'Callidus vidit malum, et abscondit se; innocens pertransiit, et afflictus est damno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 4, 'Finis modestiæ timor Domini, divitiæ, et gloria, et vita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 5, 'Arma et gladii in via perversi; custos autem animæ suæ longe recedit ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 6, 'Proverbium est: adolescens juxta viam suam; etiam cum senuerit, non recedet ab ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 7, 'Dives pauperibus imperat, et qui accipit mutuum servus est fœnerantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 8, 'Qui seminat iniquitatem metet mala, et virga iræ suæ consummabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 9, 'Qui pronus est ad misericordiam benedicetur: de panibus enim suis dedit pauperi. Victoriam et honorem acquiret qui dat munera; animam autem aufert accipientium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 10, 'Ejice derisorem, et exibit cum eo jurgium, cessabuntque causæ et contumeliæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 11, 'Qui diligit cordis munditiam, propter gratiam labiorum suorum habebit amicum regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 12, 'Oculi Domini custodiunt scientiam, et supplantantur verba iniqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 13, 'Dicit piger: Leo est foris; in medio platearum occidendus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 14, 'Fovea profunda os alienæ: cui iratus est Dominus, incidet in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 15, 'Stultitia colligata est in corde pueri, et virga disciplinæ fugabit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 16, 'Qui calumniatur pauperem ut augeat divitias suas, dabit ipse ditiori, et egebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 17, 'Inclina aurem tuam, et audi verba sapientium: appone autem cor ad doctrinam meam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 18, 'quæ pulchra erit tibi cum servaveris eam in ventre tuo, et redundabit in labiis tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 19, 'ut sit in Domino fiducia tua, unde et ostendi eam tibi hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 20, 'Ecce descripsi eam tibi tripliciter, in cogitationibus et scientia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 21, 'ut ostenderem tibi firmitatem et eloquia veritatis, respondere ex his illis qui miserunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 22, 'Non facias violentiam pauperi quia pauper est, neque conteras egenum in porta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 23, 'quia judicabit Dominus causam ejus, et configet eos qui confixerunt animam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 24, 'Noli esse amicus homini iracundo, neque ambules cum viro furioso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 25, 'ne forte discas semitas ejus, et sumas scandalum animæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 26, 'Noli esse cum his qui defigunt manus suas, et qui vades se offerunt pro debitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 27, 'si enim non habes unde restituas, quid causæ est ut tollat operimentum de cubili tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 28, 'Ne transgrediaris terminos antiquos, quos posuerunt patres tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 22, 29, 'Vidisti virum velocem in opere suo? coram regibus stabit, nec erit ante ignobiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 1, 'Quando sederis ut comedas cum principe, diligenter attende quæ apposita sunt ante faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 2, 'Et statue cultrum in gutture tuo: si tamen habes in potestate animam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 3, 'Ne desideres de cibis ejus, in quo est panis mendacii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 4, 'Noli laborare ut diteris, sed prudentiæ tuæ pone modum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 5, 'Ne erigas oculos tuos ad opes quas non potes habere, quia facient sibi pennas quasi aquilæ, et volabunt in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 6, 'Ne comedas cum homine invido, et ne desideres cibos ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 7, 'quoniam in similitudinem arioli et conjectoris æstimat quod ignorat. Comede et bibe, dicet tibi; et mens ejus non est tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 8, 'Cibos quos comederas evomes, et perdes pulchros sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 9, 'In auribus insipientium ne loquaris, qui despicient doctrinam eloquii tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 10, 'Ne attingas parvulorum terminos, et agrum pupillorum ne introëas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 11, 'propinquus enim illorum fortis est, et ipse judicabit contra te causam illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 12, 'Ingrediatur ad doctrinam cor tuum, et aures tuæ ad verba scientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 13, 'Noli subtrahere a puero disciplinam: si enim percusseris eum virga, non morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 14, 'Tu virga percuties eum, et animam ejus de inferno liberabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 15, 'Fili mi, si sapiens fuerit animus tuus, gaudebit tecum cor meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 16, 'et exsultabunt renes mei, cum locuta fuerint rectum labia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 17, 'Non æmuletur cor tuum peccatores, sed in timore Domini esto tota die:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 18, 'quia habebis spem in novissimo, et præstolatio tua non auferetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 19, 'Audi, fili mi, et esto sapiens, et dirige in via animum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 20, 'Noli esse in conviviis potatorum, nec in comessationibus eorum qui carnes ad vescendum conferunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 21, 'quia vacantes potibus et dantes symbola consumentur, et vestietur pannis dormitatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 22, 'Audi patrem tuum, qui genuit te, et ne contemnas cum senuerit mater tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 23, 'Veritatem eme, et noli vendere sapientiam, et doctrinam, et intelligentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 24, 'Exsultat gaudio pater justi; qui sapientem genuit, lætabitur in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 25, 'Gaudeat pater tuus et mater tua, et exsultet quæ genuit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 26, 'Præbe, fili mi, cor tuum mihi, et oculi tui vias meas custodiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 27, 'Fovea enim profunda est meretrix, et puteus angustus aliena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 28, 'Insidiatur in via quasi latro, et quos incautos viderit, interficiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 29, 'Cui væ? cujus patri væ? cui rixæ? cui foveæ? cui sine causa vulnera? cui suffusio oculorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 30, 'nonne his qui commorantur in vino, et student calicibus epotandis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 31, 'Ne intuearis vinum quando flavescit, cum splenduerit in vitro color ejus: ingreditur blande,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 32, 'sed in novissimo mordebit ut coluber, et sicut regulus venena diffundet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 33, 'Oculi tui videbunt extraneas, et cor tuum loquetur perversa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 34, 'Et eris sicut dormiens in medio mari, et quasi sopitus gubernator, amisso clavo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 23, 35, 'Et dices: Verberaverunt me, sed non dolui; traxerunt me, et ego non sensi. Quando evigilabo, et rursus vina reperiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 1, 'Ne æmuleris viros malos, nec desideres esse cum eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 2, 'quia rapinas meditatur mens eorum, et fraudes labia eorum loquuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 3, 'Sapientia ædificabitur domus, et prudentia roborabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 4, 'In doctrina replebuntur cellaria, universa substantia pretiosa et pulcherrima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 5, 'Vir sapiens fortis est, et vir doctus robustus et validus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 6, 'quia cum dispositione initur bellum, et erit salus ubi multa consilia sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 7, 'Excelsa stulto sapientia; in porta non aperiet os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 8, 'Qui cogitat mala facere stultus vocabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 9, 'cogitatio stulti peccatum est, et abominatio hominum detractor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 10, 'Si desperaveris lassus in die angustiæ, imminuetur fortitudo tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 11, 'Erue eos qui ducuntur ad mortem, et qui trahuntur ad interitum, liberare ne cesses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 12, 'Si dixeris: Vires non suppetunt; qui inspector est cordis ipse intelligit: et servatorem animæ tuæ nihil fallit, reddetque homini juxta opera sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 13, 'Comede, fili mi, mel, quia bonum est, et favum dulcissimum gutturi tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 14, 'Sic et doctrina sapientiæ animæ tuæ: quam cum inveneris, habebis in novissimis spem, et spes tua non peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 15, 'Ne insidieris, et quæras impietatem in domo justi, neque vastes requiem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 16, 'Septies enim cadet justus, et resurget: impii autem corruent in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 17, 'Cum ceciderit inimicus tuus ne gaudeas, et in ruina ejus ne exsultet cor tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 18, 'ne forte videat Dominus, et displiceat ei, et auferat ab eo iram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 19, 'Ne contendas cum pessimis, nec æmuleris impios:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 20, 'quoniam non habent futurorum spem mali, et lucerna impiorum extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 21, 'Time Dominum, fili mi, et regem, et cum detractoribus non commiscearis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 22, 'quoniam repente consurget perditio eorum, et ruinam utriusque quis novit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 23, 'Hæc quoque sapientibus. Cognoscere personam in judicio non est bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 24, 'Qui dicunt impio: Justus es: maledicent eis populi, et detestabuntur eos tribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 25, 'Qui arguunt eum laudabuntur, et super ipsos veniet benedictio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 26, 'Labia deosculabitur qui recta verba respondet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 27, 'Præpara foris opus tuum, et diligenter exerce agrum tuum, ut postea ædifices domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 28, 'Ne sis testis frustra contra proximum tuum, nec lactes quemquam labiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 29, 'Ne dicas: Quomodo fecit mihi, sic faciam ei; reddam unicuique secundum opus suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 30, 'Per agrum hominis pigri transivi, et per vineam viri stulti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 31, 'et ecce totum repleverant urticæ, et operuerant superficiem ejus spinæ, et maceria lapidum destructa erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 32, 'Quod cum vidissem, posui in corde meo, et exemplo didici disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 33, 'Parum, inquam, dormies, modicum dormitabis; pauxillum manus conseres ut quiescas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 24, 34, 'et veniet tibi quasi cursor egestas, et mendicitas quasi vir armatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 1, 'Hæ quoque parabolæ Salomonis, quas transtulerunt viri Ezechiæ regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 2, 'Gloria Dei est celare verbum, et gloria regum investigare sermonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 3, 'Cælum sursum, et terra deorsum, et cor regum inscrutabile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 4, 'Aufer rubiginem de argento, et egredietur vas purissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 5, 'Aufer impietatem de vultu regis, et firmabitur justitia thronus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 6, 'Ne gloriosus appareas coram rege, et in loco magnorum ne steteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 7, 'Melius est enim ut dicatur tibi: Ascende huc, quam ut humilieris coram principe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 8, 'Quæ viderunt oculi tui ne proferas in jurgio cito, ne postea emendare non possis, cum dehonestaveris amicum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 9, 'Causam tuam tracta cum amico tuo, et secretum extraneo ne reveles:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 10, 'ne forte insultet tibi cum audierit, et exprobrare non cesset. Gratia et amicitia liberant: quas tibi serva, ne exprobrabilis fias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 11, 'Mala aurea in lectis argenteis, qui loquitur verbum in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 12, 'Inauris aurea, et margaritum fulgens, qui arguit sapientem et aurem obedientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 13, 'Sicut frigus nivis in die messis, ita legatus fidelis ei qui misit eum: animam ipsius requiescere facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 14, 'Nubes, et ventus, et pluviæ non sequentes, vir gloriosus et promissa non complens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 15, 'Patientia lenietur princeps, et lingua mollis confringet duritiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 16, 'Mel invenisti: comede quod sufficit tibi, ne forte satiatus evomas illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 17, 'Subtrahe pedem tuum de domo proximi tui, nequando satiatus oderit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 18, 'Jaculum, et gladius, et sagitta acuta, homo qui loquitur contra proximum suum falsum testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 19, 'Dens putridus, et pes lassus, qui sperat super infideli in die angustiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 20, 'et amittit pallium in die frigoris. Acetum in nitro, qui cantat carmina cordi pessimo. Sicut tinea vestimento, et vermis ligno, ita tristitia viri nocet cordi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 21, 'Si esurierit inimicus tuus, ciba illum; si sitierit, da ei aquam bibere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 22, 'prunas enim congregabis super caput ejus, et Dominus reddet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 23, 'Ventus aquilo dissipat pluvias, et facies tristis linguam detrahentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 24, 'Melius est sedere in angulo domatis quam cum muliere litigiosa et in domo communi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 25, 'Aqua frigida animæ sitienti, et nuntius bonus de terra longinqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 26, 'Fons turbatus pede et vena corrupta, justus cadens coram impio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 27, 'Sicut qui mel multum comedit non est ei bonum, sic qui scrutator est majestatis opprimetur a gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 25, 28, 'Sicut urbs patens et absque murorum ambitu, ita vir qui non potest in loquendo cohibere spiritum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 1, 'Quomodo nix in æstate, et pluviæ in messe, sic indecens est stulto gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 2, 'Sicut avis ad alia transvolans, et passer quolibet vadens, sic maledictum frustra prolatum in quempiam superveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 3, 'Flagellum equo, et camus asino, et virga in dorso imprudentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 4, 'Ne respondeas stulto juxta stultitiam suam, ne efficiaris ei similis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 5, 'Responde stulto juxta stultitiam suam, ne sibi sapiens esse videatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 6, 'Claudus pedibus, et iniquitatem bibens, qui mittit verba per nuntium stultum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 7, 'Quomodo pulchras frustra habet claudus tibias, sic indecens est in ore stultorum parabola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 8, 'Sicut qui mittit lapidem in acervum Mercurii, ita qui tribuit insipienti honorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 9, 'Quomodo si spina nascatur in manu temulenti, sic parabola in ore stultorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 10, 'Judicium determinat causas, et qui imponit stulto silentium iras mitigat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 11, 'Sicut canis qui revertitur ad vomitum suum, sic imprudens qui iterat stultitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 12, 'Vidisti hominem sapientem sibi videri? magis illo spem habebit insipiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 13, 'Dicit piger: Leo est in via, et leæna in itineribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 14, 'Sicut ostium vertitur in cardine suo, ita piger in lectulo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 15, 'Abscondit piger manum sub ascella sua, et laborat si ad os suum eam converterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 16, 'Sapientior sibi piger videtur septem viris loquentibus sententias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 17, 'Sicut qui apprehendit auribus canem, sic qui transit impatiens et commiscetur rixæ alterius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 18, 'Sicut noxius est qui mittit sagittas et lanceas in mortem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 19, 'ita vir fraudulenter nocet amico suo, et cum fuerit deprehensus dicit: Ludens feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 20, 'Cum defecerint ligna extinguetur ignis, et susurrone subtracto, jurgia conquiescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 21, 'Sicut carbones ad prunas, et ligna ad ignem, sic homo iracundus suscitat rixas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 22, 'Verba susurronis quasi simplicia, et ipsa perveniunt ad intima ventris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 23, 'Quomodo si argento sordido ornare velis vas fictile, sic labia tumentia cum pessimo corde sociata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 24, 'Labiis suis intelligitur inimicus, cum in corde tractaverit dolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 25, 'Quando submiserit vocem suam, ne credideris ei, quoniam septem nequitiæ sunt in corde illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 26, 'Qui operit odium fraudulenter, revelabitur malitia ejus in consilio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 27, 'Qui fodit foveam incidet in eam, et qui volvit lapidem revertetur ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 26, 28, 'Lingua fallax non amat veritatem, et os lubricum operatur ruinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 1, 'Ne glorieris in crastinum, ignorans quid superventura pariat dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 2, 'Laudet te alienus, et non os tuum; extraneus, et non labia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 3, 'Grave est saxum, et onerosa arena, sed ira stulti utroque gravior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 4, 'Ira non habet misericordiam nec erumpens furor, et impetum concitati ferre quis poterit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 5, 'Melior est manifesta correptio quam amor absconditus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 6, 'Meliora sunt vulnera diligentis quam fraudulenta oscula odientis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 7, 'Anima saturata calcabit favum, et anima esuriens etiam amarum pro dulci sumet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 8, 'Sicut avis transmigrans de nido suo, sic vir qui derelinquit locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 9, 'Unguento et variis odoribus delectatur cor, et bonis amici consiliis anima dulcoratur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 10, 'Amicum tuum et amicum patris tui ne dimiseris, et domum fratris tui ne ingrediaris in die afflictionis tuæ. Melior est vicinus juxta quam frater procul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 11, 'Stude sapientiæ, fili mi, et lætifica cor meum, ut possis exprobranti respondere sermonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 12, 'Astutus videns malum, absconditus est: parvuli transeuntes sustinuerunt dispendia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 13, 'Tolle vestimentum ejus qui spopondit pro extraneo, et pro alienis aufer ei pignus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 14, 'Qui benedicit proximo suo voce grandi, de nocte consurgens maledicenti similis erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 15, 'Tecta perstillantia in die frigoris et litigiosa mulier comparantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 16, 'Qui retinet eam quasi qui ventum teneat, et oleum dexteræ suæ vocabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 17, 'Ferrum ferro exacuitur, et homo exacuit faciem amici sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 18, 'Qui servat ficum comedet fructus ejus, et qui custos est domini sui glorificabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 19, 'Quomodo in aquis resplendent vultus prospicientium, sic corda hominum manifesta sunt prudentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 20, 'Infernus et perditio numquam implentur: similiter et oculi hominum insatiabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 21, 'Quomodo probatur in conflatorio argentum et in fornace aurum, sic probatur homo ore laudantis. Cor iniqui inquirit mala, cor autem rectum inquirit scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 22, 'Si contuderis stultum in pila quasi ptisanas feriente desuper pilo, non auferetur ab eo stultitia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 23, 'Diligenter agnosce vultum pecoris tui, tuosque greges considera:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 24, 'non enim habebis jugiter potestatem, sed corona tribuetur in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 25, 'Aperta sunt prata, et apparuerunt herbæ virentes, et collecta sunt fœna de montibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 26, 'Agni ad vestimentum tuum, et hædi ad agri pretium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 27, 27, 'Sufficiat tibi lac caprarum in cibos tuos, et in necessaria domus tuæ, et ad victum ancillis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 1, 'Fugit impius nemine persequente; justus autem, quasi leo confidens, absque terrore erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 2, 'Propter peccata terræ multi principes ejus; et propter hominis sapientiam, et horum scientiam quæ dicuntur, vita ducis longior erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 3, 'Vir pauper calumnians pauperes similis est imbri vehementi in quo paratur fames.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 4, 'Qui derelinquunt legem laudant impium; qui custodiunt, succenduntur contra eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 5, 'Viri mali non cogitant judicium; qui autem inquirunt Dominum animadvertunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 6, 'Melior est pauper ambulans in simplicitate sua quam dives in pravis itineribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 7, 'Qui custodit legem filius sapiens est; qui autem comessatores pascit confundit patrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 8, 'Qui coacervat divitias usuris et fœnore, liberali in pauperes congregat eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 9, 'Qui declinat aures suas ne audiat legem, oratio ejus erit execrabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 10, 'Qui decipit justos in via mala, in interitu suo corruet, et simplices possidebunt bona ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 11, 'Sapiens sibi videtur vir dives; pauper autem prudens scrutabitur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 12, 'In exsultatione justorum multa gloria est; regnantibus impiis, ruinæ hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 13, 'Qui abscondit scelera sua non dirigetur; qui autem confessus fuerit et reliquerit ea, misericordiam consequetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 14, 'Beatus homo qui semper est pavidus; qui vero mentis est duræ corruet in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 15, 'Leo rugiens et ursus esuriens, princeps impius super populum pauperem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 16, 'Dux indigens prudentia multos opprimet per calumniam; qui autem odit avaritiam, longi fient dies ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 17, 'Hominem qui calumniatur animæ sanguinem, si usque ad lacum fugerit, nemo sustinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 18, 'Qui ambulat simpliciter salvus erit; qui perversis graditur viis concidet semel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 19, 'Qui operatur terram suam satiabitur panibus; qui autem sectatur otium replebitur egestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 20, 'Vir fidelis multum laudabitur; qui autem festinat ditari non erit innocens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 21, 'Qui cognoscit in judicio faciem non bene facit; iste et pro buccella panis deserit veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 22, 'Vir qui festinat ditari, et aliis invidet, ignorat quod egestas superveniet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 23, 'Qui corripit hominem gratiam postea inveniet apud eum, magis quam ille qui per linguæ blandimenta decipit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 24, 'Qui subtrahit aliquid a patre suo et a matre, et dicit hoc non esse peccatum, particeps homicidæ est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 25, 'Qui se jactat et dilatat, jurgia concitat; qui vero sperat in Domino sanabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 26, 'Qui confidit in corde suo stultus est; qui autem graditur sapienter, ipse salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 27, 'Qui dat pauperi non indigebit; qui despicit deprecantem sustinebit penuriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 28, 28, 'Cum surrexerint impii, abscondentur homines; cum illi perierint, multiplicabuntur justi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 1, 'Viro qui corripientem dura cervice contemnit, repentinus ei superveniet interitus, et eum sanitas non sequetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 2, 'In multiplicatione justorum lætabitur vulgus; cum impii sumpserint principatum, gemet populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 3, 'Vir qui amat sapientiam lætificat patrem suum; qui autem nutrit scorta perdet substantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 4, 'Rex justus erigit terram; vir avarus destruet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 5, 'Homo qui blandis fictisque sermonibus loquitur amico suo rete expandit gressibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 6, 'Peccantem virum iniquum involvet laqueus, et justus laudabit atque gaudebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 7, 'Novit justus causam pauperum; impius ignorat scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 8, 'Homines pestilentes dissipant civitatem; sapientes vero avertunt furorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 9, 'Vir sapiens si cum stulto contenderit, sive irascatur, sive rideat, non inveniet requiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 10, 'Viri sanguinum oderunt simplicem; justi autem quærunt animam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 11, 'Totum spiritum suum profert stultus; sapiens differt, et reservat in posterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 12, 'Princeps qui libenter audit verba mendacii, omnes ministros habet impios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 13, 'Pauper et creditor obviaverunt sibi: utriusque illuminator est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 14, 'Rex qui judicat in veritate pauperes, thronus ejus in æternum firmabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 15, 'Virga atque correptio tribuit sapientiam; puer autem qui dimittitur voluntati suæ confundit matrem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 16, 'In multiplicatione impiorum multiplicabuntur scelera, et justi ruinas eorum videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 17, 'Erudi filium tuum, et refrigerabit te, et dabit delicias animæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 18, 'Cum prophetia defecerit, dissipabitur populus; qui vero custodit legem beatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 19, 'Servus verbis non potest erudiri, quia quod dicis intelligit, et respondere contemnit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 20, 'Vidisti hominem velocem ad loquendum? stultitia magis speranda est quam illius correptio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 21, 'Qui delicate a pueritia nutrit servum suum postea sentiet eum contumacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 22, 'Vir iracundus provocat rixas, et qui ad indignandum facilis est erit ad peccandum proclivior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 23, 'Superbum sequitur humilitas, et humilem spiritu suscipiet gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 24, 'Qui cum fure participat odit animam suam; adjurantem audit, et non indicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 25, 'Qui timet hominem cito corruet; qui sperat in Domino sublevabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 26, 'Multi requirunt faciem principis, et judicium a Domino egreditur singulorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 29, 27, 'Abominantur justi virum impium, et abominantur impii eos qui in recta sunt via. Verbum custodiens filius extra perditionem erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 1, 'Verba Congregantis, filii Vomentis. Visio quam locutus est vir cum quo est Deus, et qui Deo secum morante confortatus, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 2, 'Stultissimus sum virorum, et sapientia hominum non est mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 3, 'Non didici sapientiam, et non novi scientiam sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 4, 'Quis ascendit in cælum, atque descendit? quis continuit spiritum in manibus suis? quis colligavit aquas quasi in vestimento? quis suscitavit omnes terminos terræ? quod nomen est ejus, et quod nomen filii ejus, si nosti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 5, 'Omnis sermo Dei ignitus: clypeus est sperantibus in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 6, 'Ne addas quidquam verbis illius, et arguaris, inveniarisque mendax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 7, 'Duo rogavi te: ne deneges mihi antequam moriar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 8, 'vanitatem et verba mendacia longe fac a me; mendicitatem et divitias ne dederis mihi: tribue tantum victui meo necessaria,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 9, 'ne forte satiatus illiciar ad negandum, et dicam: Quis est Dominus? aut egestate compulsus, furer, et perjurem nomen Dei mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 10, 'Ne accuses servum ad dominum suum, ne forte maledicat tibi, et corruas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 11, 'Generatio quæ patri suo maledicit, et quæ matri suæ non benedicit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 12, 'generatio quæ sibi munda videtur, et tamen non est lota a sordibus suis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 13, 'generatio cujus excelsi sunt oculi, et palpebræ ejus in alta surrectæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 14, 'generatio quæ pro dentibus gladios habet, et commandit molaribus suis, ut comedat inopes de terra, et pauperes ex hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 15, 'Sanguisugæ duæ sunt filiæ, dicentes: Affer, affer. Tria sunt insaturabilia, et quartum quod numquam dicit: Sufficit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 16, 'Infernus, et os vulvæ, et terra quæ non satiatur aqua: ignis vero numquam dicit: Sufficit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 17, 'Oculum qui subsannat patrem, et qui despicit partum matris suæ, effodiant eum corvi de torrentibus, et comedant eum filii aquilæ!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 18, 'Tria sunt difficilia mihi, et quartum penitus ignoro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 19, 'viam aquilæ in cælo, viam colubri super petram, viam navis in medio mari, et viam viri in adolescentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 20, 'Talis est et via mulieris adulteræ, quæ comedit, et tergens os suum dicit: Non sum operata malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 21, 'Per tria movetur terra, et quartum non potest sustinere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 22, 'per servum, cum regnaverit; per stultum, cum saturatus fuerit cibo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 23, 'per odiosam mulierem, cum in matrimonio fuerit assumpta; et per ancillam, cum fuerit hæres dominæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 24, 'Quatuor sunt minima terræ, et ipsa sunt sapientiora sapientibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 25, 'formicæ, populus infirmus, qui præparat in messe cibum sibi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 26, 'lepusculus, plebs invalida, qui collocat in petra cubile suum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 27, 'regem locusta non habet, et egreditur universa per turmas suas;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 28, 'stellio manibus nititur, et moratur in ædibus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 29, 'Tria sunt quæ bene gradiuntur, et quartum quod incedit feliciter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 30, 'leo, fortissimus bestiarum, ad nullius pavebit occursum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 31, 'gallus succinctus lumbos; et aries; nec est rex, qui resistat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 32, 'Est qui stultus apparuit postquam elevatus est in sublime; si enim intellexisset, ori suo imposuisset manum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 30, 33, 'Qui autem fortiter premit ubera ad eliciendum lac exprimit butyrum; et qui vehementer emungit elicit sanguinem; et qui provocat iras producit discordias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 1, 'Verba Lamuelis regis. Visio qua erudivit eum mater sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 2, 'Quid, dilecte mi? quid, dilecte uteri mei? quid, dilecte votorum meorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 3, 'Ne dederis mulieribus substantiam tuam, et divitias tuas ad delendos reges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 4, 'Noli regibus, o Lamuel, noli regibus dare vinum, quia nullum secretum est ubi regnat ebrietas;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 5, 'et ne forte bibant, et obliviscantur judiciorum, et mutent causam filiorum pauperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 6, 'Date siceram mœrentibus, et vinum his qui amaro sunt animo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 7, 'Bibant, et obliviscantur egestatis suæ, et doloris sui non recordentur amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 8, 'Aperi os tuum muto, et causis omnium filiorum qui pertranseunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 9, 'Aperi os tuum, decerne quod justum est, et judica inopem et pauperem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 10, 'Mulierem fortem quis inveniet? procul et de ultimis finibus pretium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 11, 'Confidit in ea cor viri sui, et spoliis non indigebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 12, 'Reddet ei bonum, et non malum, omnibus diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 13, 'Quæsivit lanam et linum, et operata est consilia manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 14, 'Facta est quasi navis institoris, de longe portans panem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 15, 'Et de nocte surrexit, deditque prædam domesticis suis, et cibaria ancillis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 16, 'Consideravit agrum, et emit eum; de fructu manuum suarum plantavit vineam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 17, 'Accinxit fortitudine lumbos suos, et roboravit brachium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 18, 'Gustavit, et vidit quia bona est negotiatio ejus; non extinguetur in nocte lucerna ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 19, 'Manum suam misit ad fortia, et digiti ejus apprehenderunt fusum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 20, 'Manum suam aperuit inopi, et palmas suas extendit ad pauperem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 21, 'Non timebit domui suæ a frigoribus nivis; omnes enim domestici ejus vestiti sunt duplicibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 22, 'Stragulatam vestem fecit sibi; byssus et purpura indumentum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 23, 'Nobilis in portis vir ejus, quando sederit cum senatoribus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 24, 'Sindonem fecit, et vendidit, et cingulum tradidit Chananæo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 25, 'Fortitudo et decor indumentum ejus, et ridebit in die novissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 26, 'Os suum aperuit sapientiæ, et lex clementiæ in lingua ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 27, 'Consideravit semitas domus suæ, et panem otiosa non comedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 28, 'Surrexerunt filii ejus, et beatissimam prædicaverunt; vir ejus, et laudavit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 29, 'Multæ filiæ congregaverunt divitias; tu supergressa es universas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 30, 'Fallax gratia, et vana est pulchritudo: mulier timens Dominum, ipsa laudabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 31, 31, 'Date ei de fructu manuum suarum, et laudent eam in portis opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Verba Ecclesiastæ, filii David, regis Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Vanitas vanitatum, dixit Ecclesiastes; vanitas vanitatum, et omnia vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Quid habet amplius homo de universo labore suo quo laborat sub sole?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Generatio præterit, et generatio advenit; terra autem in æternum stat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Oritur sol et occidit, et ad locum suum revertitur; ibique renascens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'gyrat per meridiem, et flectitur ad aquilonem. Lustrans universa in circuitu pergit spiritus, et in circulos suos revertitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Omnia flumina intrant in mare, et mare non redundat; ad locum unde exeunt flumina revertuntur ut iterum fluant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Cunctæ res difficiles; non potest eas homo explicare sermone. Non saturatur oculus visu, nec auris auditu impletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Quid est quod fuit? Ipsum quod futurum est. Quid est quod factum est? Ipsum quod faciendum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Nihil sub sole novum, nec valet quisquam dicere: Ecce hoc recens est: jam enim præcessit in sæculis quæ fuerunt ante nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Non est priorum memoria; sed nec eorum quidem quæ postea futura sunt erit recordatio apud eos qui futuri sunt in novissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Ego Ecclesiastes fui rex Israël in Jerusalem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'et proposui in animo meo quærere et investigare sapienter de omnibus quæ fiunt sub sole. Hanc occupationem pessimam dedit Deus filiis hominum, ut occuparentur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vidi cuncta quæ fiunt sub sole, et ecce universa vanitas et afflictio spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Perversi difficile corriguntur, et stultorum infinitus est numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Locutus sum in corde meo, dicens: Ecce magnus effectus sum, et præcessi omnes sapientia qui fuerunt ante me in Jerusalem; et mens mea contemplata est multa sapienter, et didici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Dedique cor meum ut scirem prudentiam atque doctrinam, erroresque et stultitiam; et agnovi quod in his quoque esset labor et afflictio spiritus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'eo quod in multa sapientia multa sit indignatio; et qui addit scientiam, addit et laborem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Dixi ego in corde meo: Vadam, et affluam deliciis, et fruar bonis; et vidi quod hoc quoque esset vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Risum reputavi errorem, et gaudio dixi: Quid frustra deciperis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Cogitavi in corde meo abstrahere a vino carnem meam, ut animam meam transferrem ad sapientiam, devitaremque stultitiam, donec viderem quid esset utile filiis hominum, quo facto opus est sub sole numero dierum vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Magnificavi opera mea, ædificavi mihi domos, et plantavi vineas;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'feci hortos et pomaria, et consevi ea cuncti generis arboribus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'et exstruxi mihi piscinas aquarum, ut irrigarem silvam lignorum germinantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Possedi servos et ancillas, multamque familiam habui: armenta quoque, et magnos ovium greges, ultra omnes qui fuerunt ante me in Jerusalem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'coacervavi mihi argentum et aurum, et substantias regum ac provinciarum; feci mihi cantores et cantatrices, et delicias filiorum hominum, scyphos, et urceos in ministerio ad vina fundenda;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'et supergressus sum opibus omnes qui ante me fuerunt in Jerusalem: sapientia quoque perseveravit mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Et omnia quæ desideraverunt oculi mei non negavi eis, nec prohibui cor meum quin omni voluptate frueretur, et oblectaret se in his quæ præparaveram; et hanc ratus sum partem meam si uterer labore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Cumque me convertissem ad universa opera quæ fecerant manus meæ, et ad labores in quibus frustra sudaveram, vidi in omnibus vanitatem et afflictionem animi, et nihil permanere sub sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Transivi ad contemplandam sapientiam, erroresque, et stultitiam. (Quid est, inquam, homo, ut sequi possit regem, factorem suum?)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Et vidi quod tantum præcederet sapientia stultitiam, quantum differt lux a tenebris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Sapientis oculi in capite ejus; stultus in tenebris ambulat: et didici quod unus utriusque esset interitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Et dixi in corde meo: Si unus et stulti et meus occasus erit, quid mihi prodest quod majorem sapientiæ dedi operam? Locutusque cum mente mea, animadverti quod hoc quoque esset vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Non enim erit memoria sapientis similiter ut stulti in perpetuum, et futura tempora oblivione cuncta pariter operient: moritur doctus similiter ut indoctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Et idcirco tæduit me vitæ meæ, videntem mala universa esse sub sole, et cuncta vanitatem et afflictionem spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Rursus detestatus sum omnem industriam meam, qua sub sole studiosissime laboravi, habiturus hæredem post me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'quem ignoro utrum sapiens an stultus futurus sit, et dominabitur in laboribus meis, quibus desudavi et sollicitus fui: et est quidquam tam vanum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Unde cessavi, renuntiavitque cor meum ultra laborare sub sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Nam cum alius laboret in sapientia, et doctrina, et sollicitudine, homini otioso quæsita dimittit; et hoc ergo vanitas et magnum malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Quid enim proderit homini de universo labore suo, et afflictione spiritus, qua sub sole cruciatus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 23, 'Cuncti dies ejus doloribus et ærumnis pleni sunt, nec per noctem mente requiescit. Et hoc nonne vanitas est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 24, 'Nonne melius est comedere et bibere, et ostendere animæ suæ bona de laboribus suis? et hoc de manu Dei est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 25, 'Quis ita devorabit et deliciis affluet ut ego?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 26, 'Homini bono in conspectu suo dedit Deus sapientiam, et scientiam, et lætitiam; peccatori autem dedit afflictionem et curam superfluam, ut addat, et congreget, et tradat ei qui placuit Deo; sed et hoc vanitas est, et cassa sollicitudo mentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Omnia tempus habent, et suis spatiis transeunt universa sub cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Tempus nascendi, et tempus moriendi; tempus plantandi, et tempus evellendi quod plantatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Tempus occidendi, et tempus sanandi; tempus destruendi, et tempus ædificandi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Tempus flendi, et tempus ridendi; tempus plangendi, et tempus saltandi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Tempus spargendi lapides, et tempus colligendi, tempus amplexandi, et tempus longe fieri ab amplexibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Tempus acquirendi, et tempus perdendi; tempus custodiendi, et tempus abjiciendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Tempus scindendi, et tempus consuendi; tempus tacendi, et tempus loquendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Tempus dilectionis, et tempus odii; tempus belli, et tempus pacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Quid habet amplius homo de labore suo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Vidi afflictionem quam dedit Deus filiis hominum, ut distendantur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Cuncta fecit bona in tempore suo, et mundum tradidit disputationi eorum, ut non inveniat homo opus quod operatus est Deus ab initio usque ad finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Et cognovi quod non esset melius nisi lætari, et facere bene in vita sua;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'omnis enim homo qui comedit et bibit, et videt bonum de labore suo, hoc donum Dei est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Didici quod omnia opera quæ fecit Deus perseverent in perpetuum; non possumus eis quidquam addere, nec auferre, quæ fecit Deus ut timeatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Quod factum est, ipsum permanet; quæ futura sunt jam fuerunt, et Deus instaurat quod abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Vidi sub sole in loco judicii impietatem, et in loco justitiæ iniquitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'et dixi in corde meo: Justum et impium judicabit Deus, et tempus omnis rei tunc erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Dixi in corde meo de filiis hominum, ut probaret eos Deus, et ostenderet similes esse bestiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Idcirco unus interitus est hominis et jumentorum, et æqua utriusque conditio. Sicut moritur homo, sic et illa moriuntur. Similiter spirant omnia, et nihil habet homo jumento amplius: cuncta subjacent vanitati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'et omnia pergunt ad unum locum. De terra facta sunt, et in terram pariter revertuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Quis novit si spiritus filiorum Adam ascendat sursum, et si spiritus jumentorum descendat deorsum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Et deprehendi nihil esse melius quam lætari hominem in opere suo, et hanc esse partem illius. Quis enim eum adducet ut post se futura cognoscat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Verti me ad alia, et vidi calumnias quæ sub sole geruntur, et lacrimas innocentium, et neminem consolatorem, nec posse resistere eorum violentiæ, cunctorum auxilio destitutos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'et laudavi magis mortuos quam viventes;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'et feliciorem utroque judicavi qui necdum natus est, nec vidit mala quæ sub sole fiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Rursum contemplatus sum omnes labores hominum, et industrias animadverti patere invidiæ proximi; et in hoc ergo vanitas et cura superflua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Stultus complicat manus suas, et comedit carnes suas, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Melior est pugillus cum requie, quam plena utraque manus cum labore et afflictione animi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 7, 'Considerans, reperi et aliam vanitatem sub sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 8, 'Unus est, et secundum non habet, non filium, non fratrem, et tamen laborare non cessat, nec satiantur oculi ejus divitiis; nec recogitat, dicens: Cui laboro, et fraudo animam meam bonis? In hoc quoque vanitas est et afflictio pessima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 9, 'Melius est ergo duos esse simul quam unum; habent enim emolumentum societatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 10, 'Si unus ceciderit, ab altero fulcietur. Væ soli, quia cum ceciderit, non habet sublevantem se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 11, 'Et si dormierint duo, fovebuntur mutuo; unus quomodo calefiet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 12, 'Et si quispiam prævaluerit contra unum, duo resistunt ei; funiculus triplex difficile rumpitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 13, 'Melior est puer pauper et sapiens, rege sene et stulto, qui nescit prævidere in posterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 14, 'Quod de carcere catenisque interdum quis egrediatur ad regnum; et alius, natus in regno, inopia consumatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 15, 'Vidi cunctos viventes qui ambulant sub sole cum adolescente secundo, qui consurget pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 16, 'Infinitus numerus est populi omnium qui fuerunt ante eum, et qui postea futuri sunt non lætabuntur in eo; sed et hoc vanitas et afflictio spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 17, 'Custodi pedem tuum ingrediens domum Dei, et appropinqua ut audias. Multo enim melior est obedientia quam stultorum victimæ, qui nesciunt quid faciunt mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Ne temere quid loquaris, neque cor tuum sit velox ad proferendum sermonem coram Deo. Deus enim in cælo, et tu super terram; idcirco sint pauci sermones tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Multas curas sequuntur somnia, et in multis sermonibus invenietur stultitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Si quid vovisti Deo, ne moreris reddere: displicet enim ei infidelis et stulta promissio, sed quodcumque voveris redde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'multoque melius est non vovere, quam post votum promissa non reddere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Ne dederis os tuum ut peccare facias carnem tuam, neque dicas coram angelo: Non est providentia: ne forte iratus Deus contra sermones tuos dissipet cuncta opera manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Ubi multa sunt somnia, plurimæ sunt vanitates, et sermones innumeri; tu vero Deum time.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Si videris calumnias egenorum, et violenta judicia, et subverti justitiam in provincia, non mireris super hoc negotio: quia excelso excelsior est alius, et super hos quoque eminentiores sunt alii;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'et insuper universæ terræ rex imperat servienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Avarus non implebitur pecunia, et qui amat divitias fructum non capiet ex eis; et hoc ergo vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Ubi multæ sunt opes, multi et qui comedunt eas. Et quid prodest possessori, nisi quod cernit divitias oculis suis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Dulcis est somnus operanti, sive parum sive multum comedat; saturitas autem divitis non sinit eum dormire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Est et alia infirmitas pessima quam vidi sub sole: divitiæ conservatæ in malum domini sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Pereunt enim in afflictione pessima: generavit filium qui in summa egestate erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Sicut egressus est nudus de utero matris suæ, sic revertetur, et nihil auferet secum de labore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Miserabilis prorsus infirmitas: quomodo venit, sic revertetur. Quid ergo prodest ei quod laboravit in ventum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'cunctis diebus vitæ suæ comedit in tenebris, et in curis multis, et in ærumna atque tristitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Hoc itaque visum est mihi bonum, ut comedat quis et bibat, et fruatur lætitia ex labore suo quo laboravit ipse sub sole, numero dierum vitæ suæ quos dedit ei Deus; et hæc est pars illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Et omni homini cui dedit Deus divitias atque substantiam, potestatemque ei tribuit ut comedat ex eis, et fruatur parte sua, et lætetur de labore suo: hoc est donum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Non enim satis recordabitur dierum vitæ suæ, eo quod Deus occupet deliciis cor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Est et aliud malum quod vidi sub sole, et quidem frequens apud homines:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'vir cui dedit Deus divitias, et substantiam, et honorem, et nihil deest animæ suæ ex omnibus quæ desiderat; nec tribuit ei potestatem Deus ut comedat ex eo, sed homo extraneus vorabit illud: hoc vanitas et miseria magna est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Si genuerit quispiam centum liberos, et vixerit multos annos, et plures dies ætatis habuerit, et anima illius non utatur bonis substantiæ suæ, sepulturaque careat: de hoc ergo pronuntio quod melior illo sit abortivus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Frustra enim venit, et pergit ad tenebras, et oblivione delebitur nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Non vidit solem, neque cognovit distantiam boni et mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Etiam si duobus millibus annis vixerit, et non fuerit perfruitus bonis, nonne ad unum locum properant omnia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Omnis labor hominis in ore ejus; sed anima ejus non implebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Quid habet amplius sapiens a stulto? et quid pauper, nisi ut pergat illuc ubi est vita?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Melius est videre quod cupias, quam desiderare quod nescias. Sed et hoc vanitas est, et præsumptio spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Qui futurus est, jam vocatum est nomen ejus; et scitur quod homo sit, et non possit contra fortiorem se in judicio contendere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Verba sunt plurima, multamque in disputando habentia vanitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Quid necesse est homini majora se quærere, cum ignoret quid conducat sibi in vita sua, numero dierum peregrinationis suæ, et tempore quod velut umbra præterit? aut quis ei poterit indicare quod post eum futurum sub sole sit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Melius est nomen bonum quam unguenta pretiosa, et dies mortis die nativitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Melius est ire ad domum luctus quam ad domum convivii; in illa enim finis cunctorum admonetur hominum, et vivens cogitat quid futurum sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Melior est ira risu, quia per tristitiam vultus corrigitur animus delinquentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Cor sapientium ubi tristitia est, et cor stultorum ubi lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Melius est a sapiente corripi, quam stultorum adulatione decipi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'quia sicut sonitus spinarum ardentium sub olla, sic risus stulti. Sed et hoc vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Calumnia conturbat sapientem, et perdet robur cordis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Melior est finis orationis quam principium. Melior est patiens arrogante.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Ne sis velox ad irascendum, quia ira in sinu stulti requiescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Ne dicas: Quid putas causæ est quod priora tempora meliora fuere quam nunc sunt? stulta enim est hujuscemodi interrogatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Utilior est sapientia cum divitiis, et magis prodest videntibus solem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Sicut enim protegit sapientia, sic protegit pecunia; hoc autem plus habet eruditio et sapientia, quod vitam tribuunt possessori suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Considera opera Dei, quod nemo possit corrigere quem ille despexerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'In die bona fruere bonis, et malam diem præcave; sicut enim hanc, sic et illam fecit Deus, ut non inveniat homo contra eum justas querimonias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Hæc quoque vidi in diebus vanitatis meæ: justus perit in justitia sua, et impius multo vivit tempore in malitia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Noli esse justus multum, neque plus sapias quam necesse est, ne obstupescas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Ne impie agas multum, et noli esse stultus, ne moriaris in tempore non tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Bonum est te sustentare justum: sed et ab illo ne subtrahas manum tuam; quia qui timet Deum nihil negligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Sapientia confortavit sapientem super decem principes civitatis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'non est enim homo justus in terra qui faciat bonum et non peccet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Sed et cunctis sermonibus qui dicuntur ne accomodes cor tuum, ne forte audias servum tuum maledicentem tibi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'scit enim conscientia tua quia et tu crebro maledixisti aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Cuncta tentavi in sapientia. Dixi: Sapiens efficiar: et ipsa longius recessit a me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'multo magis quam erat. Et alta profunditas, quis inveniet eam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 26, 'Lustravi universa animo meo, ut scirem et considerarem, et quærerem sapientiam, et rationem, et ut cognoscerem impietatem stulti, et errorem imprudentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 27, 'et inveni amariorem morte mulierem, quæ laqueus venatorum est, et sagena cor ejus; vincula sunt manus illius. Qui placet Deo effugiet illam; qui autem peccator est capietur ab illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 28, 'Ecce hoc inveni, dixit Ecclesiastes, unum et alterum ut invenirem rationem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 29, 'quam adhuc quærit anima mea, et non inveni. Virum de mille unum reperi; mulierem ex omnibus non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 30, 'Solummodo hoc inveni, quod fecerit Deus hominem rectum, et ipse se infinitis miscuerit quæstionibus. Quis talis ut sapiens est? et quis cognovit solutionem verbi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Sapientia hominis lucet in vultu ejus, et potentissimus faciem illius commutabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Ego os regis observo, et præcepta juramenti Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Ne festines recedere a facie ejus, neque permaneas in opere malo: quia omne quod voluerit faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Et sermo illius potestate plenus est, nec dicere ei quisquam potest: Quare ita facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Qui custodit præceptum non experietur quidquam mali. Tempus et responsionem cor sapientis intelligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Omni negotio tempus est, et opportunitas: et multa hominis afflictio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'quia ignorat præterita, et futura nullo scire potest nuntio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Non est in hominis potestate prohibere spiritum, nec habet potestatem in die mortis: nec sinitur quiescere ingruente bello, neque salvabit impietas impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Omnia hæc consideravi, et dedi cor meum in cunctis operibus quæ fiunt sub sole. Interdum dominatur homo homini in malum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Vidi impios sepultos, qui etiam cum adhuc viverent in loco sancto erant, et laudabantur in civitate quasi justorum operum. Sed et hoc vanitas est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Etenim quia non profertur cito contra malos sententia, absque timore ullo filii hominum perpetrant mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Attamen peccator ex eo quod centies facit malum, et per patientiam sustentatur; ego cognovi quod erit bonum timentibus Deum, qui verentur faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Non sit bonum impio, nec prolongentur dies ejus, sed quasi umbra transeant qui non timent faciem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Est et alia vanitas quæ fit super terram: sunt justi quibus mala proveniunt quasi opera egerint impiorum: et sunt impii qui ita securi sunt quasi justorum facta habeant. Sed et hoc vanissimum judico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Laudavi igitur lætitiam; quod non esset homini bonum sub sole, nisi quod comederet, et biberet, atque gauderet, et hoc solum secum auferret de labore suo, in diebus vitæ suæ quos dedit ei Deus sub sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Et apposui cor meum ut scirem sapientiam, et intelligerem distentionem quæ versatur in terra. Est homo qui diebus et noctibus somnum non capit oculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Et intellexi quod omnium operum Dei nullam possit homo invenire rationem eorum quæ fiunt sub sole; et quanto plus laboraverit ad quærendum, tanto minus inveniat: etiam si dixerit sapiens se nosse, non poterit reperire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Omnia hæc tractavi in corde meo, ut curiose intelligerem. Sunt justi atque sapientes, et opera eorum in manu Dei; et tamen nescit homo utrum amore an odio dignus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Sed omnia in futurum servantur incerta, eo quod universa æque eveniant justo et impio, bono et malo, mundo et immundo, immolanti victimas et sacrificia contemnenti. Sicut bonus, sic et peccator; ut perjurus, ita et ille qui verum dejerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Hoc est pessimum inter omnia quæ sub sole fiunt: quia eadem cunctis eveniunt. Unde et corda filiorum hominum implentur malitia et contemptu in vita sua, et post hæc ad inferos deducentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Nemo est qui semper vivat, et qui hujus rei habeat fiduciam; melior est canis vivus leone mortuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Viventes enim sciunt se esse morituros; mortui vero nihil noverunt amplius, nec habent ultra mercedem, quia oblivioni tradita est memoria eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Amor quoque, et odium, et invidiæ simul perierunt; nec habent partem in hoc sæculo, et in opere quod sub sole geritur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Vade ergo, et comede in lætitia panem tuum, et bibe cum gaudio vinum tuum, quia Deo placent opera tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Omni tempore sint vestimenta tua candida, et oleum de capite tuo non deficiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Perfruere vita cum uxore quam diligis, cunctis diebus vitæ instabilitatis tuæ, qui dati sunt tibi sub sole omni tempore vanitatis tuæ: hæc est enim pars in vita et in labore tuo quo laboras sub sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Quodcumque facere potest manus tua, instanter operare, quia nec opus, nec ratio, nec sapientia, nec scientia erunt apud inferos, quo tu properas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Verti me ad aliud, et vidi sub sole nec velocium esse cursum, nec fortium bellum, nec sapientium panem, nec doctorum divitias, nec artificum gratiam; sed tempus casumque in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Nescit homo finem suum; sed sicut pisces capiuntur hamo, et sicut aves laqueo comprehenduntur, sic capiuntur homines in tempore malo, cum eis extemplo supervenerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Hanc quoque sub sole vidi sapientiam, et probavi maximam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'civitas parva, et pauci in ea viri; venit contra eam rex magnus, et vallavit eam, exstruxitque munitiones per gyrum, et perfecta est obsidio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Inventusque est in ea vir pauper et sapiens, et liberavit urbem per sapientiam suam; et nullus deinceps recordatus est hominis illius pauperis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Et dicebam ego meliorem esse sapientiam fortitudine. Quomodo ergo sapientia pauperis contempta est, et verba ejus non sunt audita?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Verba sapientium audiuntur in silentio, plus quam clamor principis inter stultos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Melior est sapientia quam arma bellica; et qui in uno peccaverit, multa bona perdet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Muscæ morientes perdunt suavitatem unguenti. Pretiosior est sapientia et gloria, parva et ad tempus stultitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Cor sapientis in dextera ejus, et cor stulti in sinistra illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Sed et in via stultus ambulans, cum ipse insipiens sit, omnes stultos æstimat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Si spiritus potestatem habentis ascenderit super te, locum tuum ne demiseris, quia curatio faciet cessare peccata maxima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Est malum quod vidi sub sole, quasi per errorem egrediens a facie principis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'positum stultum in dignitate sublimi, et divites sedere deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Vidi servos in equis, et principes ambulantes super terram quasi servos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Qui fodit foveam incidet in eam, et qui dissipat sepem mordebit eum coluber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Qui transfert lapides affligetur in eis, et qui scindit ligna vulnerabitur ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Si retusum fuerit ferrum, et hoc non ut prius, sed hebetatum fuerit, multo labore exacuetur, et post industriam sequetur sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Si mordeat serpens in silentio, nihil eo minus habet qui occulte detrahit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Verba oris sapientis gratia, et labia insipientis præcipitabunt eum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'initium verborum ejus stultitia, et novissimum oris illius error pessimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Stultus verba multiplicat. Ignorat homo quid ante se fuerit; et quid post se futurum sit, quis ei poterit indicare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Labor stultorum affliget eos, qui nesciunt in urbem pergere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Væ tibi, terra, cujus rex puer est, et cujus principes mane comedunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Beata terra cujus rex nobilis est, et cujus principes vescuntur in tempore suo, ad reficiendum, et non ad luxuriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'In pigritiis humiliabitur contignatio, et in infirmitate manuum perstillabit domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'In risum faciunt panem et vinum ut epulentur viventes; et pecuniæ obediunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'In cogitatione tua regi ne detrahas, et in secreto cubiculi tui ne maledixeris diviti: quia et aves cæli portabunt vocem tuam, et qui habet pennas annuntiabit sententiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Mitte panem tuum super transeuntes aquas, quia post tempora multa invenies illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Da partem septem necnon et octo, quia ignoras quid futurum sit mali super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Si repletæ fuerint nubes, imbrem super terram effundent. Si ceciderit lignum ad austrum aut ad aquilonem, in quocumque loco ceciderit, ibi erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Qui observat ventum non seminat; et qui considerat nubes numquam metet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Quomodo ignoras quæ sit via spiritus, et qua ratione compingantur ossa in ventre prægnantis, sic nescis opera Dei, qui fabricator est omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Mane semina semen tuum, et vespere ne cesset manus tua: quia nescis quid magis oriatur, hoc aut illud; et si utrumque simul, melius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Dulce lumen, et delectabile est oculis videre solem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Si annis multis vixerit homo, et in his omnibus lætatus fuerit, meminisse debet tenebrosi temporis, et dierum multorum, qui cum venerint, vanitatis arguentur præterita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Lætare ergo, juvenis, in adolescentia tua, et in bono sit cor tuum in diebus juventutis tuæ: et ambula in viis cordis tui, et in intuitu oculorum tuorum, et scito quod pro omnibus his adducet te Deus in judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Aufer iram a corde tuo, et amove malitiam a carne tua: adolescentia enim et voluptas vana sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Memento Creatoris tui in diebus juventutis tuæ, antequam veniat tempus afflictionis, et appropinquent anni de quibus dicas: Non mihi placent;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'antequam tenebrescat sol, et lumen, et luna, et stellæ, et revertantur nubes post pluviam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'quando commovebuntur custodes domus, et nutabunt viri fortissimi, et otiosæ erunt molentes in minuto numero, et tenebrescent videntes per foramina;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'et claudent ostia in platea, in humilitate vocis molentis, et consurgent ad vocem volucris, et obsurdescent omnes filiæ carminis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'excelsa quoque timebunt, et formidabunt in via. Florebit amygdalus, impinguabitur locusta, et dissipabitur capparis, quoniam ibit homo in domum æternitatis suæ, et circuibunt in platea plangentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Antequam rumpatur funiculus argenteus, et recurrat vitta aurea, et conteratur hydria super fontem, et confringatur rota super cisternam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 7, 'et revertatur pulvis in terram suam unde erat, et spiritus redeat ad Deum, qui dedit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 8, 'Vanitas vanitatum, dixit Ecclesiastes, et omnia vanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 9, 'Cumque esset sapientissimus Ecclesiastes, docuit populum, et enarravit quæ fecerat; et investigans composuit parabolas multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 10, 'Quæsivit verba utilia, et conscripsit sermones rectissimos ac veritate plenos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 11, 'Verba sapientium sicut stimuli, et quasi clavi in altum defixi, quæ per magistrorum consilium data sunt a pastore uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 12, 'His amplius, fili mi, ne requiras. Faciendi plures libros nullus est finis; frequensque meditatio, carnis afflictio est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 13, 'Finem loquendi pariter omnes audiamus. Deum time, et mandata ejus observa: hoc est enim omnis homo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 14, 'et cuncta quæ fiunt adducet Deus in judicium pro omni errato, sive bonum, sive malum illud sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Osculetur me osculo oris sui; quia meliora sunt ubera tua vino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'fragrantia unguentis optimis. Oleum effusum nomen tuum; ideo adolescentulæ dilexerunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Trahe me, post te curremus in odorem unguentorum tuorum. Introduxit me rex in cellaria sua; exsultabimus et lætabimur in te, memores uberum tuorum super vinum. Recti diligunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Nigra sum, sed formosa, filiæ Jerusalem, sicut tabernacula Cedar, sicut pelles Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Nolite me considerare quod fusca sim, quia decoloravit me sol. Filii matris meæ pugnaverunt contra me; posuerunt me custodem in vineis: vineam meam non custodivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Indica mihi, quem diligit anima mea, ubi pascas, ubi cubes in meridie, ne vagari incipiam post greges sodalium tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Si ignoras te, o pulcherrima inter mulieres, egredere, et abi post vestigia gregum, et pasce hædos tuos juxta tabernacula pastorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Equitatui meo in curribus Pharaonis assimilavi te, amica mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Pulchræ sunt genæ tuæ sicut turturis; collum tuum sicut monilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Murenulas aureas faciemus tibi, vermiculatas argento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Dum esset rex in accubitu suo, nardus mea dedit odorem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Fasciculus myrrhæ dilectus meus mihi; inter ubera mea commorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Botrus cypri dilectus meus mihi in vineis Engaddi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Ecce tu pulchra es, amica mea! ecce tu pulchra es! Oculi tui columbarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Ecce tu pulcher es, dilecte mi, et decorus! Lectulus noster floridus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Tigna domorum nostrarum cedrina, laquearia nostra cypressina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Ego flos campi, et lilium convallium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Sicut lilium inter spinas, sic amica mea inter filias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Sicut malus inter ligna silvarum, sic dilectus meus inter filios. Sub umbra illius quem desideraveram sedi, et fructus ejus dulcis gutturi meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Introduxit me in cellam vinariam; ordinavit in me caritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Fulcite me floribus, stipate me malis, quia amore langueo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Læva ejus sub capite meo, et dextera illius amplexabitur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Adjuro vos, filiæ Jerusalem, per capreas cervosque camporum, ne suscitetis, neque evigilare faciatis dilectam, quoadusque ipsa velit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Vox dilecti mei; ecce iste venit, saliens in montibus, transiliens colles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Similis est dilectus meus capreæ, hinnuloque cervorum. En ipse stat post parietem nostrum, respiciens per fenestras, prospiciens per cancellos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'En dilectus meus loquitur mihi. Surge, propera, amica mea, columba mea, formosa mea, et veni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'jam enim hiems transiit; imber abiit, et recessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Flores apparuerunt in terra nostra; tempus putationis advenit: vox turturis audita est in terra nostra;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'ficus protulit grossos suos; vineæ florentes dederunt odorem suum. Surge, amica mea, speciosa mea, et veni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'columba mea, in foraminibus petræ, in caverna maceriæ, ostende mihi faciem tuam, sonet vox tua in auribus meis: vox enim tua dulcis, et facies tua decora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Capite nobis vulpes parvulas quæ demoliuntur vineas: nam vinea nostra floruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Dilectus meus mihi, et ego illi, qui pascitur inter lilia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'donec aspiret dies, et inclinentur umbræ. Revertere; similis esto, dilecte mi, capreæ, hinnuloque cervorum super montes Bether.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'In lectulo meo, per noctes, quæsivi quem diligit anima mea: quæsivi illum, et non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Surgam, et circuibo civitatem: per vicos et plateas quæram quem diligit anima mea: quæsivi illum, et non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Invenerunt me vigiles qui custodiunt civitatem: Num quem diligit anima mea vidistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Paululum cum pertransissem eos, inveni quem diligit anima mea: tenui eum, nec dimittam, donec introducam illum in domum matris meæ, et in cubiculum genetricis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Adjuro vos, filiæ Jerusalem, per capreas cervosque camporum, ne suscitetis, neque evigilare faciatis dilectam, donec ipsa velit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Quæ est ista quæ ascendit per desertum sicut virgula fumi ex aromatibus myrrhæ, et thuris, et universi pulveris pigmentarii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'En lectulum Salomonis sexaginta fortes ambiunt ex fortissimis Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'omnes tenentes gladios, et ad bella doctissimi: uniuscujusque ensis super femur suum propter timores nocturnos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Ferculum fecit sibi rex Salomon de lignis Libani;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'columnas ejus fecit argenteas, reclinatorium aureum, ascensum purpureum; media caritate constravit, propter filias Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Egredimini et videte, filiæ Sion, regem Salomonem in diademate quo coronavit illum mater sua in die desponsationis illius, et in die lætitiæ cordis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Quam pulchra es, amica mea! quam pulchra es! Oculi tui columbarum, absque eo quod intrinsecus latet. Capilli tui sicut greges caprarum quæ ascenderunt de monte Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Dentes tui sicut greges tonsarum quæ ascenderunt de lavacro; omnes gemellis fœtibus, et sterilis non est inter eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Sicut vitta coccinea labia tua, et eloquium tuum dulce. Sicut fragmen mali punici, ita genæ tuæ, absque eo quod intrinsecus latet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Sicut turris David collum tuum, quæ ædificata est cum propugnaculis; mille clypei pendent ex ea, omnis armatura fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Duo ubera tua sicut duo hinnuli, capreæ gemelli, qui pascuntur in liliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Donec aspiret dies, et inclinentur umbræ, vadam ad montem myrrhæ, et ad collem thuris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Tota pulchra es, amica mea, et macula non est in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Veni de Libano, sponsa mea: veni de Libano, veni, coronaberis: de capite Amana, de vertice Sanir et Hermon, de cubilibus leonum, de montibus pardorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Vulnerasti cor meum, soror mea, sponsa; vulnerasti cor meum in uno oculorum tuorum, et in uno crine colli tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Quam pulchræ sunt mammæ tuæ, soror mea sponsa! pulchriora sunt ubera tua vino, et odor unguentorum tuorum super omnia aromata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Favus distillans labia tua, sponsa; mel et lac sub lingua tua: et odor vestimentorum tuorum sicut odor thuris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Hortus conclusus soror mea, sponsa, hortus conclusus, fons signatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Emissiones tuæ paradisus malorum punicorum, cum pomorum fructibus, cypri cum nardo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Nardus et crocus, fistula et cinnamomum, cum universis lignis Libani; myrrha et aloë, cum omnibus primis unguentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Fons hortorum, puteus aquarum viventium, quæ fluunt impetu de Libano.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Surge, aquilo, et veni, auster: perfla hortum meum, et fluant aromata illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Veniat dilectus meus in hortum suum, et comedat fructum pomorum suorum. Veni in hortum meum, soror mea, sponsa; messui myrrham meam cum aromatibus meis; comedi favum cum melle meo; bibi vinum meum cum lacte meo; comedite, amici, et bibite, et inebriamini, carissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ego dormio, et cor meum vigilat. Vox dilecti mei pulsantis: Aperi mihi, soror mea, amica mea, columba mea, immaculata mea, quia caput meum plenum est rore, et cincinni mei guttis noctium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Expoliavi me tunica mea: quomodo induar illa? lavi pedes meos: quomodo inquinabo illos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Dilectus meus misit manum suam per foramen, et venter meus intremuit ad tactum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Surrexi ut aperirem dilecto meo; manus meæ stillaverunt myrrham, et digiti mei pleni myrrha probatissima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Pessulum ostii mei aperui dilecto meo, at ille declinaverat, atque transierat. Anima mea liquefacta est, ut locutus est; quæsivi, et non inveni illum; vocavi, et non respondit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Invenerunt me custodes qui circumeunt civitatem; percusserunt me, et vulneraverunt me. Tulerunt pallium meum mihi custodes murorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Adjuro vos, filiæ Jerusalem, si inveneritis dilectum meum, ut nuntietis ei quia amore langueo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Qualis est dilectus tuus ex dilecto, o pulcherrima mulierum? qualis est dilectus tuus ex dilecto, quia sic adjurasti nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Dilectus meus candidus et rubicundus; electus ex millibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Caput ejus aurum optimum; comæ ejus sicut elatæ palmarum, nigræ quasi corvus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Oculi ejus sicut columbæ super rivulos aquarum, quæ lacte sunt lotæ, et resident juxta fluenta plenissima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Genæ illius sicut areolæ aromatum, consitæ a pigmentariis. Labia ejus lilia, distillantia myrrham primam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Manus illius tornatiles, aureæ, plenæ hyacinthis. Venter ejus eburneus, distinctus sapphiris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Crura illius columnæ marmoreæ quæ fundatæ sunt super bases aureas. Species ejus ut Libani, electus ut cedri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Guttur illius suavissimum, et totus desiderabilis. Talis est dilectus meus, et ipse est amicus meus, filiæ Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Quo abiit dilectus tuus, o pulcherrima mulierum? quo declinavit dilectus tuus? et quæremus eum tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Dilectus meus descendit in hortum suum ad areolam aromatum, ut pascatur in hortis, et lilia colligat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Ego dilecto meo, et dilectus meus mihi, qui pascitur inter lilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Pulchra es, amica mea; suavis, et decora sicut Jerusalem; terribilis ut castrorum acies ordinata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Averte oculos tuos a me, quia ipsi me avolare fecerunt. Capilli tui sicut grex caprarum quæ apparuerunt de Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Dentes tui sicut grex ovium quæ ascenderunt de lavacro: omnes gemellis fœtibus, et sterilis non est in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Sicut cortex mali punici, sic genæ tuæ, absque occultis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Sexaginta sunt reginæ, et octoginta concubinæ, et adolescentularum non est numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Una est columba mea, perfecta mea, una est matris suæ, electa genetrici suæ. Viderunt eam filiæ, et beatissimam prædicaverunt; reginæ et concubinæ, et laudaverunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Quæ est ista quæ progreditur quasi aurora consurgens, pulchra ut luna, electa ut sol, terribilis ut castrorum acies ordinata?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Descendi in hortum nucum, ut viderem poma convallium, et inspicerem si floruisset vinea, et germinassent mala punica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Nescivi: anima mea conturbavit me, propter quadrigas Aminadab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Revertere, revertere, Sulamitis! revertere, revertere ut intueamur te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Quid videbis in Sulamite, nisi choros castrorum? Quam pulchri sunt gressus tui in calceamentis, filia principis! Juncturæ femorum tuorum sicut monilia quæ fabricata sunt manu artificis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Umbilicus tuus crater tornatilis, numquam indigens poculis. Venter tuus sicut acervus tritici vallatus liliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Duo ubera tua sicut duo hinnuli, gemelli capreæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Collum tuum sicut turris eburnea; oculi tui sicut piscinæ in Hesebon quæ sunt in porta filiæ multitudinis. Nasus tuus sicut turris Libani, quæ respicit contra Damascum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Caput tuum ut Carmelus; et comæ capitis tui sicut purpura regis vincta canalibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Quam pulchra es, et quam decora, carissima, in deliciis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Statura tua assimilata est palmæ, et ubera tua botris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Dixi: Ascendam in palmam, et apprehendam fructus ejus; et erunt ubera tua sicut botri vineæ, et odor oris tui sicut malorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Guttur tuum sicut vinum optimum, dignum dilecto meo ad potandum, labiisque et dentibus illius ad ruminandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Ego dilecto meo, et ad me conversio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Veni, dilecte mi, egrediamur in agrum, commoremur in villis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Mane surgamus ad vineas: videamus si floruit vinea, si flores fructus parturiunt, si floruerunt mala punica; ibi dabo tibi ubera mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Mandragoræ dederunt odorem in portis nostris omnia poma: nova et vetera, dilecte mi, servavi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Quis mihi det te fratrem meum, sugentem ubera matris meæ, ut inveniam te foris, et deosculer te, et jam me nemo despiciat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Apprehendam te, et ducam in domum matris meæ: ibi me docebis, et dabo tibi poculum ex vino condito, et mustum malorum granatorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Læva ejus sub capite meo, et dextera illius amplexabitur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Adjuro vos, filiæ Jerusalem, ne suscitetis, neque evigilare faciatis dilectam, donec ipsa velit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Quæ est ista quæ ascendit de deserto, deliciis affluens, innixa super dilectum suum? Sub arbore malo suscitavi te; ibi corrupta est mater tua, ibi violata est genitrix tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Pone me ut signaculum super cor tuum, ut signaculum super brachium tuum, quia fortis est ut mors dilectio, dura sicut infernus æmulatio: lampades ejus lampades ignis atque flammarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Aquæ multæ non potuerunt extinguere caritatem, nec flumina obruent illam. Si dederit homo omnem substantiam domus suæ pro dilectione, quasi nihil despiciet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Soror nostra parva, et ubera non habet; quid faciemus sorori nostræ in die quando alloquenda est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Si murus est, ædificemus super eum propugnacula argentea; si ostium est, compingamus illud tabulis cedrinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Ego murus, et ubera mea sicut turris, ex quo facta sum coram eo, quasi pacem reperiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Vinea fuit pacifico in ea quæ habet populos: tradidit eam custodibus; vir affert pro fructu ejus mille argenteos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Vinea mea coram me est. Mille tui pacifici, et ducenti his qui custodiunt fructus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Quæ habitas in hortis, amici auscultant; fac me audire vocem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Fuge, dilecte mi, et assimilare capreæ, hinnuloque cervorum super montes aromatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Diligite justitiam, qui judicatis terram. Sentite de Domino in bonitate, et in simplicitate cordis quærite illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'quoniam invenitur ab his qui non tentant illum, apparet autem eis qui fidem habent in illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Perversæ enim cogitationes separant a Deo; probata autem virtus corripit insipientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Quoniam in malevolam animam non introibit sapientia, nec habitabit in corpore subdito peccatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Spiritus enim sanctus disciplinæ effugiet fictum, et auferet se a cogitationibus quæ sunt sine intellectu, et corripietur a superveniente iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Benignus est enim spiritus sapientiæ, et non liberabit maledicum a labiis suis: quoniam renum illius testis est Deus, et cordis illius scrutator est verus, et linguæ ejus auditor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Quoniam spiritus Domini replevit orbem terrarum, et hoc quod continet omnia, scientiam habet vocis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Propter hoc qui loquitur iniqua non potest latere, nec præteriet illum corripiens judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'In cogitationibus enim impii interrogatio erit; sermonum autem illius auditio ad Deum veniet, ad correptionem iniquitatum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Quoniam auris zeli audit omnia, et tumultus murmurationum non abscondetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Custodite ergo vos a murmuratione quæ nihil prodest, et a detractione parcite linguæ: quoniam sermo obscurus in vacuum non ibit, os autem quod mentitur occidit animam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Nolite zelare mortem in errore vitæ vestræ, neque acquiratis perditionem in operibus manuum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Quoniam Deus mortem non fecit, nec lætatur in perditione vivorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Creavit enim ut essent omnia, et sanabiles fecit nationes orbis terrarum: et non est in illis medicamentum exterminii, nec inferorum regnum in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Justitia enim perpetua est, et immortalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Impii autem manibus et verbis accersierunt illam, et æstimantes illam amicam, defluxerunt; et sponsiones posuerunt ad illam, quoniam digni sunt qui sint ex parte illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Dixerunt enim cogitantes apud se non recte: Exiguum et cum tædio est tempus vitæ nostræ, et non est refrigerium in fine hominis, et non est qui agnitus sit reversus ab inferis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Quia ex nihilo nati sumus, et post hoc erimus tamquam non fuerimus. Quoniam fumus flatus est in naribus nostris, et sermo scintilla ad commovendum cor nostrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'qua extincta, cinis erit corpus nostrum, et spiritus diffundetur tamquam mollis aër; et transibit vita nostra tamquam vestigium nubis, et sicut nebula dissolvetur quæ fugata est a radiis solis, et a calore illius aggravata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Et nomen nostrum oblivionem accipiet per tempus, et nemo memoriam habebit operum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Umbræ enim transitus est tempus nostrum, et non est reversio finis nostri: quoniam consignata est, et nemo revertitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Venite ergo, et fruamur bonis quæ sunt, et utamur creatura tamquam in juventute celeriter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Vino pretioso et unguentis nos impleamus, et non prætereat nos flos temporis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Coronemus nos rosis antequam marcescant; nullum pratum sit quod non pertranseat luxuria nostra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'nemo nostrum exsors sit luxuriæ nostræ. Ubique relinquamus signa lætitiæ, quoniam hæc est pars nostra, et hæc est sors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Opprimamus pauperem justum, et non parcamus viduæ, nec veterani revereamur canos multi temporis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'sit autem fortitudo nostra lex justitiæ; quod enim infirmum est, inutile invenitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Circumveniamus ergo justum, quoniam inutilis est nobis, et contrarius est operibus nostris, et improperat nobis peccata legis, et diffamat in nos peccata disciplinæ nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Promittit se scientiam Dei habere, et filium Dei se nominat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Factus est nobis in traductionem cogitationum nostrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Gravis est nobis etiam ad videndum, quoniam dissimilis est aliis vita illius, et immutatæ sunt viæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Tamquam nugaces æstimati sumus ab illo, et abstinet se a viis nostris tamquam ab immunditiis, et præfert novissima justorum, et gloriatur patrem se habere Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Videamus ergo si sermones illius veri sint, et tentemus quæ ventura sunt illi, et sciemus quæ erunt novissima illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Si enim est verus filius Dei, suscipiet illum, et liberabit eum de manibus contrariorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Contumelia et tormento interrogemus eum, ut sciamus reverentiam ejus, et probemus patientiam illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Morte turpissima condemnemus eum; erit enim ei respectus ex sermonibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Hæc cogitaverunt, et erraverunt: excæcavit enim illos malitia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Et nescierunt sacramenta Dei: neque mercedem speraverunt justitiæ, nec judicaverunt honorem animarum sanctarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 23, 'Quoniam Deus creavit hominem inexterminabilem, et ad imaginem similitudinis suæ fecit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 24, 'Invidia autem diaboli mors introivit in orbem terrarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 25, 'imitantur autem illum qui sunt ex parte illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Justorum autem animæ in manu Dei sunt, et non tanget illos tormentum mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Visi sunt oculis insipientium mori, et æstimata est afflictio exitus illorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'et quod a nobis est iter exterminium; illi autem sunt in pace:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'etsi coram hominibus tormenta passi sunt, spes illorum immortalitate plena est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'In paucis vexati sunt, in multis bene disponentur, quoniam Deus tentavit eos, et invenit illos dignos se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Tamquam aurum in fornace probavit illos, et quasi holocausti hostiam accepit illos, et in tempore erit respectus illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Fulgebunt justi et tamquam scintillæ in arundineto discurrent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Judicabunt nationes, et dominabuntur populis, et regnabit Dominus illorum in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Qui confidunt in illo intelligent veritatem, et fideles in dilectione acquiescent illi, quoniam donum et pax est electis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Impii autem secundum quæ cogitaverunt correptionem habebunt: qui neglexerunt justum, et a Domino recesserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Sapientiam enim et disciplinam qui abjicit infelix est: et vacua est spes illorum, et labores sine fructu, et inutilia opera eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Mulieres eorum insensatæ sunt, et nequissimi filii eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Maledicta creatura eorum, quoniam felix est sterilis; et incoinquinata, quæ nescivit thorum in delicto, habebit fructum in respectione animarum sanctarum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'et spado qui non operatus est per manus suas iniquitatem, nec cogitavit adversus Deum nequissima: dabitur enim illi fidei donum electum, et sors in templo Dei acceptissima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Bonorum enim laborum gloriosus est fructus, et quæ non concidat radix sapientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Filii autem adulterorum in inconsummatione erunt, et ab iniquo thoro semen exterminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Et si quidem longæ vitæ erunt, in nihilum computabuntur, et sine honore erit novissima senectus illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'et si celerius defuncti fuerint, non habebunt spem, nec in die agnitionis allocutionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Nationis enim iniquæ diræ sunt consummationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'O quam pulchra est casta generatio, cum claritate! immortalis est enim memoria illius, quoniam et apud Deum nota est, et apud homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Cum præsens est, imitantur illam, et desiderant eam cum se eduxerit; et in perpetuum coronata triumphat, incoinquinatorum certaminum præmium vincens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Multigena autem impiorum multitudo non erit utilis, et spuria vitulamina non dabunt radices altas, nec stabile firmamentum collocabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Etsi in ramis in tempore germinaverint, infirmiter posita, a vento commovebuntur, et a nimietate ventorum eradicabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Confringentur enim rami inconsummati; et fructus illorum inutiles et acerbi ad manducandum, et ad nihilum apti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Ex iniquis enim somnis filii qui nascuntur, testes sunt nequitiæ adversus parentes in interrogatione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Justus autem si morte præoccupatus fuerit, in refrigerio erit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'senectus enim venerabilis est non diuturna, neque annorum numero computata: cani autem sunt sensus hominis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'et ætas senectutis vita immaculata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Placens Deo factus est dilectus, et vivens inter peccatores translatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Raptus est, ne malitia mutaret intellectum ejus, aut ne fictio deciperet animam illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Fascinatio enim nugacitatis obscurat bona, et inconstantia concupiscentiæ transvertit sensum sine malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Consummatus in brevi, explevit tempora multa;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'placita enim erat Deo anima illius: propter hoc properavit educere illum de medio iniquitatum. Populi autem videntes, et non intelligentes, nec ponentes in præcordiis talia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'quoniam gratia Dei et misericordia est in sanctos ejus, et respectus in electos illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Condemnat autem justus mortuus vivos impios, et juventus celerius consummata longam vitam injusti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Videbunt enim finem sapientis, et non intelligent quid cogitaverit de illo Deus, et quare munierit illum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Videbunt, et contemnent eum; illos autem Dominus irridebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Et erunt post hæc decidentes sine honore, et in contumelia inter mortuos in perpetuum: quoniam disrumpet illos inflatos sine voce, et commovebit illos a fundamentis, et usque ad supremum desolabuntur, et erunt gementes, et memoria illorum peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Venient in cogitatione peccatorum suorum timidi, et traducent illos ex adverso iniquitates ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Tunc stabunt justi in magna constantia adversus eos qui se angustiaverunt, et qui abstulerunt labores eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Videntes turbabuntur timore horribili, et mirabuntur in subitatione insperatæ salutis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'dicentes intra se, pœnitentiam agentes, et præ angustia spiritus gementes: Hi sunt quos habuimus aliquando in derisum, et in similitudinem improperii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Nos insensati, vitam illorum æstimabamus insaniam, et finem illorum sine honore;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'ecce quomodo computati sunt inter filios Dei, et inter sanctos sors illorum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Ergo erravimus a via veritatis, et justitiæ lumen non luxit nobis, et sol intelligentiæ non est ortus nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Lassati sumus in via iniquitatis et perditionis, et ambulavimus vias difficiles: viam autem Domini ignoravimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Quid nobis profuit superbia? aut divitiarum jactantia quid contulit nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Transierunt omnia illa tamquam umbra, et tamquam nuntius percurrens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'et tamquam navis quæ pertransit fluctuantem aquam, cujus cum præterierit non est vestigium invenire, neque semitam carinæ illius in fluctibus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'aut tamquam avis quæ transvolat in aëre, cujus nullum invenitur argumentum itineris, sed tantum sonitus alarum verberans levem ventum, et scindens per vim itineris aërem: commotis alis transvolavit, et post hoc nullum signum invenitur itineris illius;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'aut tamquam sagitta emissa in locum destinatum, divisus aër continuo in se reclusus est, ut ignoretur transitus illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'sic et nos nati continuo desivimus esse; et virtutis quidem nullum signum valuimus ostendere, in malignitate autem nostra consumpti sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Talia dixerunt in inferno hi qui peccaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'quoniam spes impii tamquam lanugo est quæ a vento tollitur, et tamquam spuma gracilis quæ a procella dispergitur, et tamquam fumus qui a vento diffusus est, et tamquam memoria hospitis unius diei prætereuntis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Justi autem in perpetuum vivent, et apud Dominum est merces eorum, et cogitatio illorum apud Altissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Ideo accipient regnum decoris, et diadema speciei de manu Domini: quoniam dextera sua teget eos, et brachio sancto suo defendet illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Accipiet armaturam zelus illius, et armabit creaturam ad ultionem inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Induet pro thorace justitiam, et accipiet pro galea judicium certum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'sumet scutum inexpugnabile æquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Acuet autem duram iram in lanceam, et pugnabit cum illo orbis terrarum contra insensatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Ibunt directe emissiones fulgurum, et tamquam a bene curvato arcu nubium exterminabuntur, et ad certum locum insilient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 23, 'Et a petrosa ira plenæ mittentur grandines; excandescet in illos aqua maris, et flumina concurrent duriter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 24, 'Contra illos stabit spiritus virtutis, et tamquam turbo venti dividet illos; et ad eremum perducet omnem terram iniquitas illorum, et malignitas evertet sedes potentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 1, 'Melior est sapientia quam vires, et vir prudens quam fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 2, 'Audite ergo, reges, et intelligite; discite, judices finium terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 3, 'Præbete aures, vos qui continetis multitudines, et placetis vobis in turbis nationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 4, 'Quoniam data est a Domino potestas vobis, et virtus ab Altissimo: qui interrogabit opera vestra, et cogitationes scrutabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 5, 'Quoniam cum essetis ministri regni illius, non recte judicastis, nec custodistis legem justitiæ, neque secundum voluntatem Dei ambulastis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 6, 'Horrende et cito apparebit vobis, quoniam judicium durissimum his qui præsunt fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 7, 'Exiguo enim conceditur misericordia; potentes autem potenter tormenta patientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 8, 'Non enim subtrahet personam cujusquam Deus, nec verebitur magnitudinem ejus cujusquam, quoniam pusillum et magnum ipse fecit, et æqualiter cura est illi de omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 9, 'Fortioribus autem fortior instat cruciatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 10, 'Ad vos ergo, reges, sunt hi sermones mei: ut discatis sapientiam, et non excidatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 11, 'Qui enim custodierint justa juste, justificabuntur; et qui didicerint ista, invenient quid respondeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 12, 'Concupiscite ergo sermones meos; diligite illos, et habebitis disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 13, 'Clara est, et quæ numquam marcescit, sapientia: et facile videtur ab his qui diligunt eam, et invenitur ab his qui quærunt illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 14, 'Præoccupat qui se concupiscunt, ut illis se prior ostendat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 15, 'Qui de luce vigilaverit ad illam non laborabit; assidentem enim illam foribus suis inveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 16, 'Cogitare ergo de illa sensus est consummatus, et qui vigilaverit propter illam cito securus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 17, 'Quoniam dignos se ipsa circuit quærens, et in viis ostendit se hilariter, et in omni providentia occurrit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 18, 'Initium enim illius verissima est disciplinæ concupiscentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 19, 'Cura ergo disciplinæ dilectio est, et dilectio custodia legum illius est; custoditio autem legum consummatio incorruptionis est;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 20, 'incorruptio autem facit esse proximum Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 21, 'Concupiscentia itaque sapientiæ deducit ad regnum perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 22, 'Si ergo delectamini sedibus et sceptris, o reges populi, diligite sapientiam, ut in perpetuum regnetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 23, 'diligite lumen sapientiæ, omnes qui præestis populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 24, 'Quid est autem sapientia, et quemadmodum facta sit, referam, et non abscondam a vobis sacramenta Dei: sed ab initio nativitatis investigabo, et ponam in lucem scientiam illius, et non præteribo veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 25, 'Neque cum invidia tabescente iter habebo, quoniam talis homo non erit particeps sapientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 26, 'Multitudo autem sapientium sanitas est orbis terrarum, et rex sapiens stabilimentum populi est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 6, 27, 'Ergo accipite disciplinam per sermones meos, et proderit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 1, 'Sum quidem et ego mortalis homo, similis omnibus, et ex genere terreni illius qui prior factus est: et in ventre matris figuratus sum caro;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 2, 'decem mensium tempore coagulatus sum in sanguine: ex semine hominis, et delectamento somni conveniente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 3, 'Et ego natus accepi communem aërem, et in similiter factam decidi terram, et primam vocem similem omnibus emisi plorans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 4, 'In involumentis nutritus sum, et curis magnis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 5, 'nemo enim ex regibus aliud habuit nativitatis initium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 6, 'Unus ergo introitus est omnibus ad vitam, et similis exitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 7, 'Propter hoc optavi, et datus est mihi sensus; et invocavi, et venit in me spiritus sapientiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 8, 'et præposui illam regnis et sedibus, et divitias nihil esse duxi in comparatione illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 9, 'Nec comparavi illi lapidem pretiosum, quoniam omne aurum in comparatione illius arena est exigua, et tamquam lutum æstimabitur argentum in conspectu illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 10, 'Super salutem et speciem dilexi illam, et proposui pro luce habere illam, quoniam inextinguibile est lumen illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 11, 'Venerunt autem mihi omnia bona pariter cum illa, et innumerabilis honestas per manus illius;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 12, 'et lætatus sum in omnibus, quoniam antecedebat me ista sapientia, et ignorabam quoniam horum omnium mater est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 13, 'Quam sine fictione didici, et sine invidia communico, et honestatem illius non abscondo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 14, 'Infinitus enim thesaurus est hominibus; quo qui usi sunt, participes facti sunt amicitiæ Dei, propter disciplinæ dona commendati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 15, 'Mihi autem dedit Deus dicere ex sententia, et præsumere digna horum quæ mihi dantur: quoniam ipse sapientiæ dux est, et sapientium emendator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 16, 'In manu enim illius et nos et sermones nostri, et omnis sapientia, et operum scientia, et disciplina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 17, 'Ipse enim dedit mihi horum quæ sunt scientiam veram, ut sciam dispositionem orbis terrarum, et virtutes elementorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 18, 'initium, et consummationem, et medietatem temporum, vicissitudinum permutationes, et commutationes temporum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 19, 'anni cursus, et stellarum dispositiones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 20, 'naturas animalium, et iras bestiarum, vim ventorum, et cogitationes hominum, differentias virgultorum, et virtutes radicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 21, 'Et quæcumque sunt absconsa et improvisa didici: omnium enim artifex docuit me sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 22, 'Est enim in illa spiritus intelligentiæ, sanctus, unicus, multiplex, subtilis, disertus, mobilis, incoinquinatus, certus, suavis, amans bonum, acutus, quem nihil vetat, benefaciens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 23, 'humanus, benignus, stabilis, certus, securus, omnem habens virtutem, omnia prospiciens, et qui capiat omnes spiritus, intelligibilis, mundus, subtilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 24, 'Omnibus enim mobilibus mobilior est sapientia: attingit autem ubique propter suam munditiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 25, 'Vapor est enim virtutis Dei, et emanatio quædam est claritatis omnipotentis Dei sincera, et ideo nihil inquinatum in eam incurrit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 26, 'candor est enim lucis æternæ, et speculum sine macula Dei majestatis, et imago bonitatis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 27, 'Et cum sit una, omnia potest; et in se permanens omnia innovat: et per nationes in animas sanctas se transfert; amicos Dei et prophetas constituit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 28, 'Neminem enim diligit Deus, nisi eum qui cum sapientia inhabitat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 29, 'Est enim hæc speciosior sole, et super omnem dispositionem stellarum: luci comparata, invenitur prior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 7, 30, 'Illi enim succedit nox; sapientiam autem non vincit malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 1, 'Attingit ergo a fine usque ad finem fortiter, et disponit omnia suaviter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 2, 'Hanc amavi, et exquisivi a juventute mea, et quæsivi sponsam mihi eam assumere, et amator factus sum formæ illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 3, 'Generositatem illius glorificat, contubernium habens Dei; sed et omnium Dominus dilexit illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 4, 'Doctrix enim est disciplinæ Dei, et electrix operum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 5, 'Et si divitiæ appetuntur in vita, quid sapientia locupletius quæ operatur omnia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 6, 'Si autem sensus operatur, quis horum quæ sunt magis quam illa est artifex?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 7, 'Et si justitiam quis diligit, labores hujus magnas habent virtutes: sobrietatem enim et prudentiam docet, et justitiam, et virtutem, quibus utilius nihil est in vita hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 8, 'Et si multitudinem scientiæ desiderat quis, scit præterita, et de futuris æstimat; scit versutias sermonum, et dissolutiones argumentorum; signa et monstra scit antequam fiant, et eventus temporum et sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 9, 'Proposui ergo hanc adducere mihi ad convivendum, sciens quoniam mecum communicabit de bonis, et erit allocutio cogitationis et tædii mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 10, 'Habebo propter hanc claritatem ad turbas, et honorem apud seniores juvenis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 11, 'et acutus inveniar in judicio, et in conspectu potentium admirabilis ero, et facies principum mirabuntur me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 12, 'tacentem me sustinebunt, et loquentem me respicient, et sermocinante me plura, manus ori suo imponent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 13, 'Præterea habebo per hanc immortalitatem, et memoriam æternam his qui post me futuri sunt relinquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 14, 'Disponam populos, et nationes mihi erunt subditæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 15, 'timebunt me audientes reges horrendi. In multitudine videbor bonus, et in bello fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 16, 'Intrans in domum meam, conquiescam cum illa: non enim habet amaritudinem conversatio illius, nec tædium convictus illius, sed lætitiam et gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 17, 'Hæc cogitans apud me et commemorans in corde meo, quoniam immortalitas est in cognatione sapientiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 18, 'et in amicitia illius delectatio bona, et in operibus manuum illius honestas sine defectione, et in certamine loquelæ illius sapientia, et præclaritas in communicatione sermonum ipsius: circuibam quærens, ut mihi illam assumerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 19, 'Puer autem eram ingeniosus, et sortitus sum animam bonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 20, 'Et cum essem magis bonus, veni ad corpus incoinquinatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 8, 21, 'Et ut scivi quoniam aliter non possem esse continens, nisi Deus det; et hoc ipsum erat sapientiæ, scire cujus esset hoc donum: adii Dominum, et deprecatus sum illum, et dixi ex totis præcordiis meis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 1, 'Deus patrum meorum, et Domine misericordiæ, qui fecisti omnia verbo tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 2, 'et sapientia tua constituisti hominem, ut dominaretur creaturæ quæ a te facta est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 3, 'ut disponat orbem terrarum in æquitate et justitia, et in directione cordis judicium judicet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 4, 'da mihi sedium tuarum assistricem sapientiam, et noli me reprobare a pueris tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 5, 'quoniam servus tuus sum ego, et filius ancillæ tuæ; homo infirmus, et exigui temporis, et minor ad intellectum judicii et legum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 6, 'Nam etsi quis erit consummatus inter filios hominum, si ab illo abfuerit sapientia tua, in nihilum computabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 7, 'Tu elegisti me regem populo tuo, et judicem filiorum tuorum et filiarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 8, 'et dixisti me ædificare templum in monte sancto tuo, et in civitate habitationis tuæ altare: similitudinem tabernaculi sancti tui quod præparasti ab initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 9, 'Et tecum sapientia tua, quæ novit opera tua, quæ et affuit tunc cum orbem terrarum faceres, et sciebat quid esset placitum oculis tuis, et quid directum in præceptis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 10, 'Mitte illam de cælis sanctis tuis, et a sede magnitudinis tuæ, ut mecum sit et mecum laboret, ut sciam quid acceptum sit apud te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 11, 'scit enim illa omnia, et intelligit, et deducet me in operibus meis sobrie, et custodiet me in sua potentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 12, 'Et erunt accepta opera mea, et disponam populum tuum juste, et ero dignus sedium patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 13, 'Quis enim hominum poterit scire consilium Dei? aut quis poterit cogitare quid velit Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 14, 'Cogitationes enim mortalium timidæ, et incertæ providentiæ nostræ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 15, 'corpus enim quod corrumpitur aggravat animam, et terrena inhabitatio deprimit sensum multa cogitantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 16, 'Et difficile æstimamus quæ in terra sunt, et quæ in prospectu sunt invenimus cum labore: quæ autem in cælis sunt, quis investigabit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 17, 'Sensum autem tuum, quis sciet, nisi tu dederis sapientiam, et miseris spiritum sanctum tuum de altissimis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 18, 'et sic correctæ sint semitæ eorum qui sunt in terris, et quæ tibi placent didicerint homines?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 9, 19, 'Nam per sapientiam sanati sunt quicumque placuerunt tibi, Domine, a principio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 1, 'Hæc illum qui primus formatus est a Deo patre orbis terrarum, cum solus esset creatus, custodivit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 2, 'et eduxit illum a delicto suo, et dedit illi virtutem continendi omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 3, 'Ab hac ut recessit injustus in ira sua, per iram homicidii fraterni deperiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 4, 'Propter quem cum aqua deleret terram, sanavit iterum sapientia, per contemptibile lignum justum gubernans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 5, 'Hæc et in consensu nequitiæ, cum se nationes contulissent, scivit justum, et conservavit sine querela Deo, et in filii misericordia fortem custodivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 6, 'Hæc justum a pereuntibus impiis liberavit fugientem, descendente igne in Pentapolim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 7, 'quibus in testimonium nequitiæ fumigabunda constat deserta terra, et incerto tempore fructus habentes arbores: et incredibilis animæ memoria stans figmentum salis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 8, 'Sapientiam enim prætereuntes, non tantum in hoc lapsi sunt ut ignorarent bona, sed et insipientiæ suæ reliquerunt hominibus memoriam, ut in his quæ peccaverunt nec latere potuissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 9, 'Sapientia autem hos qui se observant a doloribus liberavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 10, 'Hæc profugum iræ fratris justum deduxit per vias rectas, et ostendit illi regnum Dei, et dedit illi scientiam sanctorum; honestavit illum in laboribus, et complevit labores illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 11, 'In fraude circumvenientium illum affuit illi, et honestum fecit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 12, 'Custodivit illum ab inimicis, et a seductoribus tutavit illum: et certamen forte dedit illi ut vinceret, et sciret quoniam omnium potentior est sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 13, 'Hæc venditum justum non dereliquit, sed a peccatoribus liberavit eum; descenditque cum illo in foveam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 14, 'et in vinculis non dereliquit illum, donec afferret illi sceptrum regni, et potentiam adversus eos qui eum deprimebant: et mendaces ostendit qui maculaverunt illum, et dedit illi claritatem æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 15, 'Hæc populum justum et semen sine querela liberavit a nationibus quæ illum deprimebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 16, 'Intravit in animam servi Dei, et stetit contra reges horrendos in portentis et signis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 17, 'Et reddidit justis mercedem laborum suorum, et deduxit illos in via mirabili: et fuit illis in velamento diei, et in luce stellarum per noctem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 18, 'transtulit illos per mare Rubrum, et transvexit illos per aquam nimiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 19, 'Inimicos autem illorum demersit in mare, et ab altitudine inferorum eduxit illos. Ideo justi tulerunt spolia impiorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 20, 'et decantaverunt, Domine, nomen sanctum tuum, et victricem manum tuam laudaverunt pariter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 10, 21, 'quoniam sapientia aperuit os mutorum, et linguas infantium fecit disertas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 1, 'Direxit opera eorum in manibus prophetæ sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 2, 'Iter fecerunt per deserta quæ non habitabantur, et in locis desertis fixerunt casas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 3, 'Steterunt contra hostes, et de inimicis se vindicaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 4, 'Sitierunt, et invocaverunt te, et data est illis aqua de petra altissima, et requies sitis de lapide duro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 5, 'Per quæ enim pœnas passi sunt inimici illorum a defectione potus sui, et in eis cum abundarent filii Israël lætati sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 6, 'per hæc, cum illis deessent, bene cum illis actum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 7, 'Nam pro fonte quidem sempiterni fluminis, humanum sanguinem dedisti injustis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 8, 'Qui cum minuerentur in traductione infantium occisorum, dedisti illis abundantem aquam insperate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 9, 'ostendens per sitim quæ tunc fuit, quemadmodum tuos exaltares, et adversarios illorum necares.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 10, 'Cum enim tentati sunt, et quidem cum misericordia disciplinam accipientes, scierunt quemadmodum cum ira judicati impii tormenta paterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 11, 'Hos quidem tamquam pater monens probasti; illos autem tamquam durus rex interrogans condemnasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 12, 'Absentes enim, et præsentes, similiter torquebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 13, 'Duplex enim illos acceperat tædium et gemitus, cum memoria præteritorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 14, 'Cum enim audirent per sua tormenta bene secum agi, commemorati sunt Dominum, admirantes in finem exitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 15, 'Quem enim in expositione prava projectum deriserunt, in finem eventus mirati sunt, non similiter justis sitientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 16, 'Pro cogitationibus autem insensatis iniquitatis illorum, quod quidam errantes colebant mutos serpentes et bestias supervacuas, immisisti illis multitudinem mutorum animalium in vindictam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 17, 'ut scirent quia per quæ peccat quis, per hæc et torquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 18, 'Non enim impossibilis erat omnipotens manus tua, quæ creavit orbem terrarum ex materia invisa, immittere illis multitudinem ursorum, aut audaces leones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 19, 'aut novi generis ira plenas ignotas bestias, aut vaporem ignium spirantes, aut fumi odorem proferentes, aut horrendas ab oculis scintillas emittentes;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 20, 'quarum non solum læsura poterat illos exterminare, sed et aspectus per timorem occidere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 21, 'Sed et sine his uno spiritu poterant occidi, persecutionem passi ab ipsis factis suis, et dispersi per spiritum virtutis tuæ: sed omnia in mensura, et numero et pondere disposuisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 22, 'Multum enim valere, tibi soli supererat semper: et virtuti brachii tui quis resistet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 23, 'Quoniam tamquam momentum stateræ, sic est ante te orbis terrarum, et tamquam gutta roris antelucani quæ descendit in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 24, 'Sed misereris omnium, quia omnia potes; et dissimulas peccata hominum, propter pœnitentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 25, 'Diligis enim omnia quæ sunt, et nihil odisti eorum quæ fecisti; nec enim odiens aliquid constituisti aut fecisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 26, 'Quomodo autem posset aliquid permanere, nisi tu voluisses? aut quod a te vocatum non esset conservaretur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 11, 27, 'Parcis autem omnibus, quoniam tua sunt, Domine, qui amas animas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 1, 'O quam bonus et suavis est, Domine, spiritus tuus in omnibus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 2, 'Ideoque eos qui exerrant partibus corripis, et de quibus peccant admones et alloqueris, ut relicta malitia credant in te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 3, 'Illos enim antiquos inhabitatores terræ sanctæ tuæ, quos exhorruisti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 4, 'quoniam odibilia opera tibi faciebant per medicamina et sacrificia injusta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 5, 'et filiorum suorum necatores sine misericordia, et comestores viscerum hominum, et devoratores sanguinis a medio sacramento tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 6, 'et auctores parentes animarum inauxiliatarum, perdere voluisti per manus parentum nostrorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 7, 'ut dignam perciperent peregrinationem puerorum Dei, quæ tibi omnium carior est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 8, 'Sed et his tamquam hominibus pepercisti, et misisti antecessores exercitus tui vespas, ut illos paulatim exterminarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 9, 'Non quia impotens eras in bello subjicere impios justis, aut bestiis sævis, aut verbo duro simul exterminare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 10, 'sed partibus judicans, dabas locum pœnitentiæ, non ignorans quoniam nequam est natio eorum, et naturalis malitia ipsorum, et quoniam non poterat mutari cogitatio illorum in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 11, 'Semen enim erat maledictum ab initio; nec timens aliquem, veniam dabas peccatis illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 12, 'Quis enim dicet tibi: Quid fecisti? aut quis stabit contra judicium tuum? aut quis in conspectu tuo veniet vindex iniquorum hominum? aut quis tibi imputabit, si perierint nationes quas tu fecisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 13, 'Non enim est alius deus quam tu, cui cura est de omnibus, ut ostendas quoniam non injuste judicas judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 14, 'Neque rex, neque tyrannus in conspectu tuo inquirent de his quos perdidisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 15, 'Cum ergo sis justus, juste omnia disponis; ipsum quoque qui non debet puniri, condemnare, exterum æstimas a tua virtute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 16, 'Virtus enim tua justitiæ initium est, et ob hoc quod Dominus es, omnibus te parcere facis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 17, 'Virtutem enim ostendis tu, qui non crederis esse in virtute consummatus, et horum qui te nesciunt audaciam traducis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 18, 'Tu autem dominator virtutis, cum tranquillitate judicas, et cum magna reverentia disponis nos: subest enim tibi, cum volueris posse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 19, 'Docuisti autem populum tuum per talia opera, quoniam oportet justum esse et humanum; et bonæ spei fecisti filios tuos, quoniam judicans das locum in peccatis pœnitentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 20, 'Si enim inimicos servorum tuorum, et debitos morti, cum tanta cruciasti attentione, dans tempus et locum per quæ possent mutari a malitia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 21, 'cum quanta diligentia judicasti filios tuos, quorum parentibus juramenta et conventiones dedisti bonarum promissionum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 22, 'Cum ergo das nobis disciplinam, inimicos nostros multipliciter flagellas, ut bonitatem tuam cogitemus judicantes, et cum de nobis judicatur, speremus misericordiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 23, 'Unde et illis qui in vita sua insensate et injuste vixerunt, per hæc quæ coluerunt dedisti summa tormenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 24, 'Etenim in erroris via diutius erraverunt, deos æstimantes hæc quæ in animalibus sunt supervacua, infantium insensatorum more viventes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 25, 'Propter hoc tamquam pueris insensatis judicium in derisum dedisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 26, 'Qui autem ludibriis et increpationibus non sunt correcti, dignum Dei judicium experti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 12, 27, 'In quibus enim patientes indignabantur per hæc quos putabant deos, in ipsis cum exterminarentur videntes, illum quem olim negabant se nosse, verum Deum agnoverunt; propter quod et finis condemnationis eorum venit super illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 1, 'Vani autem sunt omnes homines in quibus non subest scientia Dei; et de his quæ videntur bona, non potuerunt intelligere eum qui est, neque operibus attendentes agnoverunt quis esset artifex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 2, 'sed aut ignem, aut spiritum, aut citatum aërem, aut gyrum stellarum, aut nimiam aquam, aut solem et lunam, rectores orbis terrarum deos putaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 3, 'Quorum si specie delectati, deos putaverunt, sciant quanto his dominator eorum speciosior est: speciei enim generator hæc omnia constituit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 4, 'Aut si virtutem et opera eorum mirati sunt, intelligant ab illis quoniam qui hæc fecit fortior est illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 5, 'a magnitudine enim speciei et creaturæ cognoscibiliter poterit creator horum videri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 6, 'Sed tamen adhuc in his minor est querela; et hi enim fortasse errant, Deum quærentes, et volentes invenire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 7, 'Etenim cum in operibus illius conversentur inquirunt, et persuasum habent quoniam bona sunt quæ videntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 8, 'Iterum autem nec his debet ignosci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 9, 'Si enim tantum potuerunt scire ut possent æstimare sæculum, quomodo hujus Dominum non facilius invenerunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 10, 'Infelices autem sunt, et inter mortuos spes illorum est, qui appellaverunt deos opera manuum hominum: aurum et argentum, artis inventionem, et similitudines animalium, aut lapidem inutilem, opus manus antiquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 11, 'Aut si quis artifex faber de silva lignum rectum secuerit, et hujus docte eradat omnem corticem, et arte sua usus diligenter fabricet vas utile in conversationem vitæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 12, 'reliquiis autem ejus operis ad præparationem escæ abutatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 13, 'et reliquum horum quod ad nullos usus facit, lignum curvum et vorticibus plenum sculpat diligenter per vacuitatem suam, et per scientiam suæ artis figuret illud, et assimilet illud imagini hominis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 14, 'aut alicui ex animalibus illud comparet: perliniens rubrica, et rubicundum faciens fuco colorem illius, et omnem maculam quæ in illo est perliniens;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 15, 'et faciat ei dignam habitationem, et in pariete ponens illud, et confirmans ferro');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 16, 'ne forte cadat, prospiciens illi: sciens quoniam non potest adjuvare se: imago enim est, et opus est illi adjutorium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 17, 'Et de substantia sua, et de filiis suis, et de nuptiis votum faciens inquirit: non erubescit loqui cum illo qui sine anima est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 18, 'Et pro sanitate quidem infirmum deprecatur, et pro vita rogat mortuum, et in adjutorium inutilem invocat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 13, 19, 'Et pro itinere petit ab eo qui ambulare non potest; et de acquirendo, et de operando, et de omnium rerum eventu, petit ab eo qui in omnibus est inutilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 1, 'Iterum alius navigare cogitans, et per feros fluctus iter facere incipiens, ligno portante se, fragilius lignum invocat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 2, 'Illud enim cupiditas acquirendi excogitavit, et artifex sapientia fabricavit sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 3, 'Tua autem, Pater, providentia gubernat: quoniam dedisti et in mari viam, et inter fluctus semitam firmissimam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 4, 'ostendens quoniam potens es ex omnibus salvare, etiam si sine arte aliquis adeat mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 5, 'Sed ut non essent vacua sapientiæ tuæ opera, propter hoc etiam et exiguo ligno credunt homines animas suas, et transeuntes mare per ratem liberati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 6, 'Sed et ab initio cum perirent superbi gigantes, spes orbis terrarum ad ratem confugiens, remisit sæculo semen nativitatis quæ manu tua erat gubernata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 7, 'Benedictum est enim lignum per quod fit justitia;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 8, 'per manus autem quod fit idolum, maledictum est et ipsum, et qui fecit illud: quia ille quidem operatus est, illud autem cum esset fragile, deus cognominatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 9, 'Similiter autem odio sunt Deo impius et impietas ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 10, 'etenim quod factum est, cum illo qui fecit tormenta patietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 11, 'Propter hoc et in idolis nationum non erit respectus, quoniam creaturæ Dei in odium factæ sunt, et in tentationem animabus hominum, et in muscipulam pedibus insipientium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 12, 'Initium enim fornicationis est exquisitio idolorum, et adinventio illorum corruptio vitæ est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 13, 'neque enim erant ab initio, neque erunt in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 14, 'Supervacuitas enim hominum hæc advenit in orbem terrarum, et ideo brevis illorum finis est inventus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 15, 'Acerbo enim luctu dolens pater, cito sibi rapti filii fecit imaginem; et illum qui tunc quasi homo mortuus fuerat, nunc tamquam deum colere cœpit, et constituit inter servos suos sacra et sacrificia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 16, 'Deinde interveniente tempore, convalescente iniqua consuetudine, hic error tamquam lex custoditus est, et tyrannorum imperio colebantur figmenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 17, 'Et hos quos in palam homines honorare non poterant propter hoc quod longe essent, e longinquo figura eorum allata, evidentem imaginem regis quem honorare volebant fecerunt, ut illum qui aberat, tamquam præsentem colerent sua sollicitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 18, 'Provexit autem ad horum culturam et hos qui ignorabant artificis eximia diligentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 19, 'Ille enim, volens placere illi qui se assumpsit, elaboravit arte sua ut similitudinem in melius figuraret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 20, 'Multitudo autem hominum, abducta per speciem operis, eum qui ante tempus tamquam homo honoratus fuerat, nunc deum æstimaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 21, 'Et hæc fuit vitæ humanæ deceptio, quoniam aut affectui aut regibus deservientes homines, incommunicabile nomen lapidibus et lignis imposuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 22, 'Et non suffecerat errasse eos circa Dei scientiam, sed et in magno viventes inscientiæ bello, tot et tam magna mala pacem appellant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 23, 'Aut enim filios suos sacrificantes, aut obscura sacrificia facientes, aut insaniæ plenas vigilias habentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 24, 'neque vitam, neque nuptias mundas jam custodiunt: sed alius alium per invidiam occidit, aut adulterans contristat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 25, 'et omnia commista sunt: sanguis, homicidium, furtum et fictio, corruptio et infidelitas, turbatio et perjurium, tumultus bonorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 26, 'Dei immemoratio, animarum inquinatio, nativitatis immutatio, nuptiarum inconstantia, inordinatio mœchiæ et impudicitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 27, 'Infandorum enim idolorum cultura omnis mali causa est, et initium et finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 28, 'Aut enim dum lætantur insaniunt, aut certe vaticinantur falsa, aut vivunt injuste, aut pejerant cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 29, 'Dum enim confidunt in idolis quæ sine anima sunt, male jurantes noceri se non sperant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 30, 'Utraque ergo illis evenient digne, quoniam male senserunt de Deo, attendentes idolis, et juraverunt injuste, in dolo contemnentes justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 14, 31, 'Non enim juratorum virtus, sed peccantium pœna, perambulat semper injustorum prævaricationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 1, 'Tu autem, Deus noster, suavis et verus es, patiens, et in misericordia disponens omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 2, 'Etenim si peccaverimus, tui sumus, scientes magnitudinem tuam; et si non peccaverimus, scimus quoniam apud te sumus computati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 3, 'Nosse enim te, consummata justitia est; et scire justitiam et virtutem tuam, radix est immortalitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 4, 'Non enim in errorem induxit nos hominum malæ artis excogitatio, nec umbra picturæ labor sine fructu, effigies sculpta per varios colores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 5, 'cujus aspectus insensato dat concupiscentiam, et diligit mortuæ imaginis effigiem sine anima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 6, 'Malorum amatores digni sunt qui spem habeant in talibus, et qui faciunt illos, et qui diligunt, et qui colunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 7, 'Sed et figulus mollem terram premens, laboriose fingit ad usus nostros unumquodque vas; et de eodem luto fingit quæ munda sunt in usum vasa, et similiter quæ his sunt contraria: horum autem vasorum quis sit usus, judex est figulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 8, 'Et cum labore vano deum fingit de eodem luto ille qui paulo ante de terra factus fuerat, et post pusillum reducit se unde acceptus est, repetitus animæ debitum quam habebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 9, 'Sed cura est illi non quia laboraturus est, nec quoniam brevis illi vita est: sed concertatur aurificibus et argentariis; sed et ærarios imitatur, et gloriam præfert, quoniam res supervacuas fingit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 10, 'Cinis est enim cor ejus, et terra supervacua spes illius, et luto vilior vita ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 11, 'quoniam ignoravit qui se finxit, et qui inspiravit illi animam quæ operatur, et qui insufflavit ei spiritum vitalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 12, 'Sed et æstimaverunt ludum esse vitam nostram, et conversationem vitæ compositam ad lucrum, et oportere undecumque etiam ex malo acquirere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 13, 'Hic enim scit se super omnes delinquere, qui ex terræ materia fragilia vasa et sculptilia fingit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 14, 'Omnes enim insipientes, et infelices supra modum animæ superbi, sunt inimici populi tui, et imperantes illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 15, 'quoniam omnia idola nationum deos æstimaverunt, quibus neque oculorum usus est ad videndum, neque nares ad percipiendum spiritum, neque aures ad audiendum, neque digiti manuum ad tractandum, sed et pedes eorum pigri ad ambulandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 16, 'Homo enim fecit illos; et qui spiritum mutuatus est, is finxit illos. Nemo enim sibi similem homo poterit deum fingere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 17, 'Cum enim sit mortalis, mortuum fingit manibus iniquis. Melior enim est ipse his quos colit, quia ipse quidem vixit, cum esset mortalis, illi autem numquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 18, 'Sed et animalia miserrima colunt; insensata enim comparata his, illis sunt deteriora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 15, 19, 'Sed nec aspectu aliquis ex his animalibus bona potest conspicere: effugerunt autem Dei laudem et benedictionem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 1, 'Propter hæc et per his similia passi sunt digne tormenta, et per multitudinem bestiarum exterminati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 2, 'Pro quibus tormentis bene disposuisti populum tuum, quibus dedisti concupiscentiam delectamenti sui novum saporem, escam parans eis ortygometram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 3, 'ut illi quidem, concupiscentes escam propter ea quæ illis ostensa et missa sunt, etiam a necessaria concupiscentia averterentur. Hi autem in brevi inopes facti, novam gustaverunt escam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 4, 'Oportebat enim illis sine excusatione quidem supervenire interitum exercentibus tyrannidem; his autem tantum ostendere quemadmodum inimici eorum exterminabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 5, 'Etenim cum illis supervenit sæva bestiarum ira, morsibus perversorum colubrorum exterminabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 6, 'Sed non in perpetuum ira tua permansit, sed ad correptionem in brevi turbati sunt, signum habentes salutis ad commemorationem mandati legis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 7, 'Qui enim conversus est, non per hoc quod videbat sanabatur, sed per te, omnium salvatorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 8, 'In hoc autem ostendisti inimicis nostris quia tu es qui liberas ab omni malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 9, 'Illos enim locustarum et muscarum occiderunt morsus, et non est inventa sanitas animæ illorum, quia digni erant ab hujuscemodi exterminari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 10, 'Filios autem tuos nec draconum venenatorum vicerunt dentes: misericordia enim tua adveniens sanabat illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 11, 'In memoria enim sermonum tuorum examinabantur, et velociter salvabantur: ne in altam incidentes oblivionem non possent tuo uti adjutorio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 12, 'Etenim neque herba, neque malagma sanavit eos: sed tuus, Domine, sermo, qui sanat omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 13, 'Tu es enim, Domine, qui vitæ et mortis habes potestatem, et deducis ad portas mortis, et reducis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 14, 'Homo autem occidit quidem per malitiam; et cum exierit spiritus, non revertetur, nec revocabit animam quæ recepta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 15, 'Sed tuam manum effugere impossibile est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 16, 'Negantes enim te nosse impii, per fortitudinem brachii tui flagellati sunt: novis aquis, et grandinibus, et pluviis persecutionem passi, et per ignem consumpti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 17, 'Quod enim mirabile erat, in aqua, quæ omnia extinguit, plus ignis valebat: vindex est enim orbis justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 18, 'Quodam enim tempore mansuetabatur ignis, ne comburerentur quæ ad impios missa erant animalia, sed ut ipsi videntes scirent quoniam Dei judicio patiuntur persecutionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 19, 'Et quodam tempore in aqua supra virtutem ignis exardescebat undique, ut iniquæ terræ nationem exterminaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 20, 'Pro quibus angelorum esca nutrivisti populum tuum, et paratum panem de cælo præstitisti illis sine labore, omne delectamentum in se habentem, et omnis saporis suavitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 21, 'Substantia enim tua dulcedinem tuam, quam in filios habes, ostendebat; et deserviens uniuscujusque voluntati, ad quod quisque volebat convertebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 22, 'Nix autem et glacies sustinebant vim ignis, et non tabescebant: ut scirent quoniam fructus inimicorum exterminabat ignis ardens in grandine et pluvia coruscans;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 23, 'hic autem iterum ut nutrirentur justi, etiam suæ virtutis oblitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 24, 'Creatura enim tibi factori deserviens, exardescit in tormentum adversus injustos, et lenior fit ad benefaciendum pro his qui in te confidunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 25, 'Propter hoc et tunc in omnia transfigurata, omnium nutrici gratiæ tuæ deserviebat, ad voluntatem eorum qui a te desiderabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 26, 'ut scirent filii tui quos dilexisti, Domine, quoniam non nativitatis fructus pascunt homines, sed sermo tuus hos qui in te crediderint conservat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 27, 'Quod enim ab igne non poterat exterminari, statim ab exiguo radio solis calefactum tabescebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 28, 'ut notum omnibus esset quoniam oportet prævenire solem ad benedictionem tuam, et ad ortum lucis te adorare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 16, 29, 'Ingrati enim spes tamquam hibernalis glacies tabescet, et disperiet tamquam aqua supervacua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 1, 'Magna sunt enim judicia tua, Domine, et inenarrabilia verba tua: propter hoc indisciplinatæ animæ erraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 2, 'Dum enim persuasum habent iniqui posse dominari nationi sanctæ, vinculis tenebrarum et longæ noctis compediti, inclusi sub tectis, fugitivi perpetuæ providentiæ jacuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 3, 'Et dum putant se latere in obscuris peccatis, tenebroso oblivionis velamento dispersi sunt, paventes horrende, et cum admiratione nimia perturbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 4, 'Neque enim quæ continebat illos spelunca sine timore custodiebat, quoniam sonitus descendens perturbabat illos, et personæ tristes illis apparentes pavorem illis præstabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 5, 'Et ignis quidem nulla vis poterat illis lumen præbere, nec siderum limpidæ flammæ illuminare poterant illam noctem horrendam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 6, 'Apparebat autem illis subitaneus ignis, timore plenus; et timore perculsi illius quæ non videbatur faciei, æstimabant deteriora esse quæ videbantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 7, 'Et magicæ artis appositi erant derisus, et sapientiæ gloriæ correptio cum contumelia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 8, 'Illi enim qui promittebant timores et perturbationes expellere se ab anima languente, hi cum derisu pleni timore languebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 9, 'Nam etsi nihil illos ex monstris perturbabat, transitu animalium et serpentium sibilatione commoti, tremebundi peribant, et aërem quem nulla ratione quis effugere posset, negantes se videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 10, 'Cum sit enim timida nequitia, dat testimonium condemnationis: semper enim præsumit sæva, perturbata conscientia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 11, 'nihil enim est timor nisi proditio cogitationis auxiliorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 12, 'Et dum ab intus minor est exspectatio, majorem computat inscientiam ejus causæ, de qua tormentum præstat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 13, 'Illi autem qui impotentem vere noctem, et ab infimis et ab altissimis inferis supervenientem, eumdem somnum dormientes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 14, 'aliquando monstrorum exagitabantur timore, aliquando animæ deficiebant traductione: subitaneus enim illis et insperatus timor supervenerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 15, 'Deinde si quisquam ex illis decidisset, custodiebatur in carcere sine ferro reclusus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 16, 'Si enim rusticus quis erat, aut pastor, aut agri laborum operarius præoccupatus esset, ineffugibilem sustinebat necessitatem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 17, 'una enim catena tenebrarum omnes erant colligati. Sive spiritus sibilans, aut inter spissos arborum ramos avium sonus suavis, aut vis aquæ decurrentis nimium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 18, 'aut sonus validus præcipitatarum petrarum, aut ludentium animalium cursus invisus, aut mugientium valida bestiarum vox, aut resonans de altissimis montibus echo: deficientes faciebant illos præ timore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 19, 'Omnis enim orbis terrarum limpido illuminabatur lumine, et non impeditis operibus continebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 17, 20, 'Solis autem illis superposita erat gravis nox, imago tenebrarum quæ superventura illis erat: ipsi ergo sibi erant graviores tenebris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 1, 'Sanctis autem tuis maxima erat lux, et horum quidem vocem audiebant, sed figuram non videbant. Et quia non et ipsi eadem passi erant, magnificabant te;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 2, 'et qui ante læsi erant, quia non lædebantur, gratias agebant, et ut esset differentia, donum petebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 3, 'Propter quod ignis ardentem columnam ducem habuerunt ignotæ viæ, et solem sine læsura boni hospitii præstitisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 4, 'Digni quidem illi carere luce, et pati carcerem tenebrarum, qui inclusos custodiebant filios tuos, per quos incipiebat incorruptum legis lumen sæculo dari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 5, 'Cum cogitarent justorum occidere infantes, et uno exposito filio et liberato, in traductionem illorum, multitudinem filiorum abstulisti, et pariter illos perdidisti in aqua valida.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 6, 'Illa enim nox ante cognita est a patribus nostris, ut vere scientes quibus juramentis crediderunt, animæquiores essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 7, 'Suscepta est autem a populo tuo sanitas quidem justorum, injustorum autem exterminatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 8, 'Sicut enim læsisti adversarios, sic et nos provocans magnificasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 9, 'Absconse enim sacrificabant justi pueri bonorum, et justitiæ legem in concordia disposuerunt; similiter et bona et mala recepturos justos, patrum jam decantantes laudes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 10, 'Resonabat autem inconveniens inimicorum vox, et flebilis audiebatur planctus ploratorum infantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 11, 'Simili autem pœna servus cum domino afflictus est, et popularis homo regi similia passus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 12, 'Similiter ergo omnes, uno nomine mortis, mortuos habebant innumerabiles: nec enim ad sepeliendum vivi sufficiebant, quoniam uno momento quæ erat præclarior natio illorum exterminata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 13, 'De omnibus enim non credentes, propter veneficia; tunc vero primum cum fuit exterminium primogenitorum, spoponderunt populum Dei esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 14, 'Cum enim quietum silentium contineret omnia, et nox in suo cursu medium iter haberet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 15, 'omnipotens sermo tuus de cælo, a regalibus sedibus, durus debellator in mediam exterminii terram prosilivit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 16, 'gladius acutus insimulatum imperium tuum portans: et stans, replevit omnia morte, et usque ad cælum attingebat stans in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 17, 'Tunc continuo visus somniorum malorum turbaverunt illos, et timores supervenerunt insperati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 18, 'Et alius alibi projectus semivivus, propter quam moriebatur causam demonstrabat mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 19, 'Visiones enim quæ illos turbaverunt hæc præmonebant, ne inscii quare mala patiebantur perirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 20, 'Tetigit autem tunc et justos tentatio mortis, et commotio in eremo facta est multitudinis: sed non diu permansit ira tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 21, 'Prosperans enim homo sine querela deprecari pro populis, proferens servitutis suæ scutum, orationem et per incensum deprecationem allegans, restitit iræ, et finem imposuit necessitati, ostendens quoniam tuus est famulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 22, 'Vicit autem turbas non in virtute corporis, nec armaturæ potentia: sed verbo illum qui se vexabat subjecit, juramenta parentum et testamentum commemorans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 23, 'Cum enim jam acervatim cecidissent super alterutrum mortui, interstitit, et amputavit impetum, et divisit illam quæ ad vivos ducebat viam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 24, 'In veste enim poderis quam habebat, totus erat orbis terrarum; et parentum magnalia in quatuor ordinibus lapidum erant sculpta, et magnificentia tua in diademate capitis illius sculpta erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 18, 25, 'His autem cessit qui exterminabat, et hæc extimuit: erat enim sola tentatio iræ sufficiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 1, 'Impiis autem usque in novissimum sine misericordia ira supervenit. Præsciebat enim et futura illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 2, 'quoniam cum ipsi permisissent ut se educerent, et cum magna sollicitudine præmisissent illos, consequebantur illos, pœnitentia acti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 3, 'Adhuc enim inter manus habentes luctum, et deplorantes ad monumenta mortuorum, aliam sibi assumpserunt cogitationem inscientiæ, et quos rogantes projecerant, hos tamquam fugitivos persequebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 4, 'Ducebat enim illos ad hunc finem digna necessitas; et horum quæ acciderant commemorationem amittebant, ut quæ deerant tormentis repleret punitio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 5, 'et populus quidem tuus mirabiliter transiret, illi autem novam mortem invenirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 6, 'Omnis enim creatura ad suum genus ab initio refigurabatur, deserviens tuis præceptis, ut pueri tui custodirentur illæsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 7, 'Nam nubes castra eorum obumbrabat, et ex aqua quæ ante erat, terra arida apparuit, et in mari Rubro via sine impedimento, et campus germinans de profundo nimio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 8, 'per quem omnis natio transivit quæ tegebatur tua manu, videntes tua mirabilia et monstra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 9, 'Tamquam enim equi depaverunt escam, et tamquam agni exsultaverunt, magnificantes te, Domine, qui liberasti illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 10, 'Memores enim erant adhuc eorum quæ in incolatu illorum facta fuerant: quemadmodum pro natione animalium eduxit terra muscas, et pro piscibus eructavit fluvius multitudinem ranarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 11, 'Novissime autem viderunt novam creaturam avium, cum, adducti concupiscentia, postulaverunt escas epulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 12, 'In allocutione enim desiderii ascendit illis de mari ortygometra: et vexationes peccatoribus supervenerunt, non sine illis quæ ante facta erant argumentis per vim fulminum: juste enim patiebantur secundum suas nequitias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 13, 'Etenim detestabiliorem inhospitalitatem instituerunt: alii quidem ignotos non recipiebant advenas; alii autem bonos hospites in servitutem redigebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 14, 'Et non solum hæc, sed et alius quidam respectus illorum erat, quoniam inviti recipiebant extraneos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 15, 'Qui autem cum lætitia receperunt hos qui eisdem usi erant justitiis, sævissimis afflixerunt doloribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 16, 'Percussi sunt autem cæcitate: sicut illi in foribus justi, cum subitaneis cooperti essent tenebris, unusquisque transitum ostii sui quærebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 17, 'In se enim elementa dum convertuntur, sicut in organo qualitatis sonus immutatur, et omnia suum sonum custodiunt: unde æstimari ex ipso visu certo potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 18, 'Agrestia enim in aquatica convertebantur, et quæcumque erant natantia, in terram transibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 19, 'Ignis in aqua valebat supra suam virtutem, et aqua extinguentis naturæ obliviscebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 19, 20, 'Flammæ e contrario corruptibilium animalium non vexaverunt carnes coambulantium, nec dissolvebant illam, quæ facile dissolvebatur sicut glacies, bonam escam. In omnibus enim magnificasti populum tuum, Domine, et honorasti, et non despexisti, in omni tempore et in omni loco assistens eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Omnis sapientia a Domino Deo est: et cum illo fuit semper, et est ante ævum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Arenam maris, et pluviæ guttas, et dies sæculi, quis dinumeravit? altitudinem cæli, et latitudinem terræ, et profundum abyssi, quis dimensus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'sapientiam Dei præcedentem omnia, quis investigavit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Prior omnium creata est sapientia, et intellectus prudentiæ ab ævo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Fons sapientiæ verbum Dei in excelsis, et ingressus illius mandata æterna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Radix sapientiæ cui revelata est? et astutias illius quis agnovit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'disciplina sapientiæ cui revelata est et manifestata? et multiplicationem ingressus illius quis intellexit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Unus est altissimus, Creator omnipotens, et rex potens et metuendus nimis, sedens super thronum illius, et dominans Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Ipse creavit illam in Spiritu Sancto, et vidit, et dinumeravit, et mensus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'et effudit illam super omnia opera sua, et super omnem carnem, secundum datum suum, et præbuit illam diligentibus se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Timor Domini gloria, et gloriatio, et lætitia, et corona exsultationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Timor Domini delectabit cor, et dabit lætitiam, et gaudium, et longitudinem dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Timenti Dominum bene erit in extremis, et in die defunctionis suæ benedicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Dilectio Dei honorabilis sapientia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'quibus autem apparuerit in visu diligunt eam in visione, et in agnitione magnalium suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Initium sapientiæ timor Domini: et cum fidelibus in vulva concreatus est: cum electis feminis graditur, et cum justis et fidelibus agnoscitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Timor Domini scientiæ religiositas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'religiositas custodiet et justificabit cor; jucunditatem atque gaudium dabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Timenti Dominum bene erit, et in diebus consummationis illius benedicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Plenitudo sapientiæ est timere Deum, et plenitudo a fructibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Omnem domum illius implebit a generationibus, et receptacula a thesauris illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Corona sapientiæ timor Domini, replens pacem et salutis fructum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'et vidit, et dinumeravit eam: utraque autem sunt dona Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Scientiam et intellectum prudentiæ sapientia compartietur, et gloriam tenentium se exaltat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Radix sapientiæ est timere Dominum, et rami illius longævi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'In thesauris sapientiæ intellectus et scientiæ religiositas: execratio autem peccatoribus sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Timor Domini expellit peccatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'nam qui sine timore est non poterit justificari: iracundia enim animositatis illius subversio illius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 29, 'Usque in tempus sustinebit patiens, et postea redditio jucunditatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 30, 'Bonus sensus usque in tempus abscondet verba illius, et labia multorum enarrabunt sensum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 31, 'In thesauris sapientiæ significatio disciplinæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 32, 'execratio autem peccatori cultura Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 33, 'Fili, concupiscens sapientiam, conserva justitiam, et Deus præbebit illam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 34, 'Sapientia enim et disciplina timor Domini: et quod beneplacitum est illi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 35, 'fides et mansuetudo, et adimplebit thesauros illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 36, 'Ne sis incredibilis timori Domini, et ne accesseris ad illum duplici corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 37, 'Ne fueris hypocrita in conspectu hominum, et non scandalizeris in labiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 38, 'Attende in illis, ne forte cadas, et adducas animæ tuæ inhonorationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 39, 'et revelet Deus absconsa tua, et in medio synagogæ elidat te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 40, 'quoniam accessisti maligne ad Dominum, et cor tuum plenum est dolo et fallacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Fili, accedens ad servitutem Dei sta in justitia et timore, et præpara animam tuam ad tentationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Deprime cor tuum, et sustine: inclina aurem tuam, et suscipe verba intellectus: et ne festines in tempore obductionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Sustine sustentationes Dei: conjungere Deo, et sustine, ut crescat in novissimo vita tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Omne quod tibi applicitum fuerit accipe: et in dolore sustine, et in humilitate tua patientiam habe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'quoniam in igne probatur aurum et argentum, homines vero receptibiles in camino humiliationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Crede Deo, et recuperabit te: et dirige viam tuam, et spera in illum: serva timorem illius, et in illo veterasce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Metuentes Dominum, sustinete misericordiam ejus: et non deflectatis ab illo, ne cadatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Qui timetis Dominum, credite illi, et non evacuabitur merces vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Qui timetis Dominum, sperate in illum, et in oblectationem veniet vobis misericordia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Qui timetis Dominum, diligite illum, et illuminabuntur corda vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 11, 'Respicite, filii, nationes hominum: et scitote quia nullus speravit in Domino et confusus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 12, 'Quis enim permansit in mandatis ejus, et derelictus est? aut quis invocavit eum, et despexit illum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 13, 'Quoniam pius et misericors est Deus, et remittet in die tribulationis peccata, et protector est omnibus exquirentibus se in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 14, 'Væ duplici corde, et labiis scelestis, et manibus malefacientibus, et peccatori terram ingredienti duabus viis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 15, 'Væ dissolutis corde, qui non credunt Deo, et ideo non protegentur ab eo!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 16, 'Væ his qui perdiderunt sustinentiam, et qui dereliquerunt vias rectas, et diverterunt in vias pravas!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 17, 'Et quid facient cum inspicere cœperit Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 18, 'Qui timent Dominum non erunt incredibiles verbo illius: et qui diligunt illum conservabunt viam illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 19, 'Qui timent Dominum inquirent quæ beneplacita sunt ei, et qui diligunt eum replebuntur lege ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 20, 'Qui timent Dominum præparabunt corda sua, et in conspectu illius sanctificabunt animas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 21, 'Qui timent Dominum custodiunt mandata illius, et patientiam habebunt usque ad inspectionem illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 22, 'dicentes: Si pœnitentiam non egerimus, incidemus in manus Domini, et non in manus hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 23, 'Secundum enim magnitudinem ipsius, sic et misericordia illius cum ipso est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Filii sapientiæ ecclesia justorum, et natio illorum obedientia et dilectio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Judicium patris audite, filii, et sic facite, ut salvi sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Deus enim honoravit patrem in filiis: et judicium matris exquirens, firmavit in filios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Qui diligit Deum exorabit pro peccatis, et continebit se ab illis, et in oratione dierum exaudietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Et sicut qui thesaurizat, ita et qui honorificat matrem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Qui honorat patrem suum jucundabitur in filiis, et in die orationis suæ exaudietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Qui honorat patrem suum vita vivet longiore, et qui obedit patri refrigerabit matrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Qui timet Dominum honorat parentes, et quasi dominis serviet his qui se genuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'In opere, et sermone, et omni patientia, honora patrem tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'ut superveniat tibi benedictio ab eo, et benedictio illius in novissimo maneat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Benedictio patris firmat domos filiorum: maledictio autem matris eradicat fundamenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Ne glorieris in contumelia patris tui: non enim est tibi gloria ejus confusio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Gloria enim hominis ex honore patris sui, et dedecus filii pater sine honore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Fili, suscipe senectam patris tui, et non contristes eum in vita illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'et si defecerit sensu, veniam da, et ne spernas eum in virtute tua: eleemosyna enim patris non erit in oblivione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Nam pro peccato matris restituetur tibi bonum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'et in justitia ædificabitur tibi, et in die tribulationis commemorabitur tui, et sicut in sereno glacies, solventur peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quam malæ famæ est qui derelinquit patrem, et est maledictus a Deo qui exasperat matrem!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Fili, in mansuetudine opera tua perfice, et super hominum gloriam diligeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Quanto magnus es, humilia te in omnibus, et coram Deo invenies gratiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'quoniam magna potentia Dei solius, et ab humilibus honoratur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Altiora te ne quæsieris, et fortiora te ne scrutatus fueris: sed quæ præcepit tibi Deus, illa cogita semper, et in pluribus operibus ejus ne fueris curiosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Non est enim tibi necessarium ea, quæ abscondita sunt, videre oculis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'In supervacuis rebus noli scrutari multipliciter, et in pluribus operibus ejus non eris curiosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Plurima enim super sensum hominum ostensa sunt tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'multos quoque supplantavit suspicio illorum, et in vanitate detinuit sensus illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Cor durum habebit male in novissimo, et qui amat periculum in illo peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 28, 'Cor ingrediens duas vias non habebit successus, et pravus corde in illis scandalizabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 29, 'Cor nequam gravabitur in doloribus, et peccator adjiciet ad peccandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 30, 'Synagogæ superborum non erit sanitas, frutex enim peccati radicabitur in illis, et non intelligetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 31, 'Cor sapientis intelligitur in sapientia, et auris bona audiet cum omni concupiscentia sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 32, 'Sapiens cor et intelligibile abstinebit se a peccatis, et in operibus justitiæ successus habebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 33, 'Ignem ardentem exstinguit aqua, et eleemosyna resistit peccatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 34, 'et Deus prospector est ejus qui reddit gratiam: meminit ejus in posterum, et in tempore casus sui inveniet firmamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Fili, eleemosynam pauperis ne defraudes, et oculos tuos ne transvertas a paupere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Animam esurientem ne despexeris, et non exasperes pauperem in inopia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Cor inopis ne afflixeris, et non protrahas datum angustianti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Rogationem contribulati ne abjicias, et non avertas faciem tuam ab egeno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ab inope ne avertas oculos tuos propter iram: et non relinquas quærentibus tibi retro maledicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Maledicentis enim tibi in amaritudine animæ, exaudietur deprecatio illius: exaudiet autem eum qui fecit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Congregationi pauperum affabilem te facito: et presbytero humilia animam tuam, et magnato humilia caput tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Declina pauperi sine tristitia aurem tuam, et redde debitum tuum, et responde illi pacifica in mansuetudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Libera eum qui injuriam patitur de manu superbi, et non acide feras in anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'In judicando esto pupillis misericors ut pater, et pro viro matri illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'et eris tu velut filius Altissimi obediens, et miserebitur tui magis quam mater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Sapientia filiis suis vitam inspirat: et suscipit inquirentes se, et præibit in via justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Et qui illam diligit, diligit vitam, et qui vigilaverint ad illam complectentur placorem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Qui tenuerint illam, vitam hæreditabunt: et quo introibit benedicet Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Qui serviunt ei obsequentes erunt sancto: et eos qui diligunt illam, diligit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Qui audit illam judicabit gentes: et qui intuetur illam permanebit confidens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Si crediderit ei, hæreditabit illam, et erunt in confirmatione creaturæ illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 18, 'quoniam in tentatione ambulat cum eo, et in primis eligit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 19, 'Timorem, et metum, et probationem inducet super illum: et cruciabit illum in tribulatione doctrinæ suæ, donec tentet eum in cogitationibus suis, et credat animæ illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 20, 'Et firmabit illum, et iter adducet directum ad illum, et lætificabit illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 21, 'et denudabit absconsa sua illi, et thesaurizabit super illum scientiam et intellectum justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 22, 'Si autem oberraverit, derelinquet eum, et tradet eum in manus inimici sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 23, 'Fili, conserva tempus, et devita a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 24, 'Pro anima tua ne confundaris dicere verum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 25, 'est enim confusio adducens peccatum, et est confusio adducens gloriam et gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 26, 'Ne accipias faciem adversus faciem tuam, nec adversus animam tuam mendacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 27, 'Ne reverearis proximum tuum in casu suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 28, 'nec retineas verbum in tempore salutis. Non abscondas sapientiam tuam in decore suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 29, 'in lingua enim sapientia dignoscitur: et sensus, et scientia, et doctrina in verbo sensati, et firmamentum in operibus justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 30, 'Non contradicas verbo veritatis ullo modo, et de mendacio ineruditionis tuæ confundere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 31, 'Non confundaris confiteri peccata tua, et ne subjicias te omni homini pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 32, 'Noli resistere contra faciem potentis, nec coneris contra ictum fluvii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 33, 'Pro justitia agonizare pro anima tua, et usque ad mortem certa pro justitia: et Deus expugnabit pro te inimicos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 34, 'Noli citatus esse in lingua tua, et inutilis, et remissus in operibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 35, 'Noli esse sicut leo in domo tua, evertens domesticos tuos, et opprimens subjectos tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 36, 'Non sit porrecta manus tua ad accipiendum, et ad dandum collecta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Noli attendere ad possessiones iniquas, et ne dixeris: Est mihi sufficiens vita: nihil enim proderit in tempore vindictæ et obductionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ne sequaris in fortitudine tua concupiscentiam cordis tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'et ne dixeris: Quomodo potui? aut, Quis me subjiciet propter facta mea? Deus enim vindicans vindicabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Ne dixeris: Peccavi: et quid mihi accidit triste? Altissimus enim est patiens redditor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'De propitiatio peccato noli esse sine metu, neque adjicias peccatum super peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Et ne dicas: Miseratio Domini magna est, multitudinis peccatorum meorum miserebitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'misericordia enim et ira ab illo cito proximant, et in peccatores respicit ira illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Non tardes converti ad Dominum, et ne differas de die in diem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'subito enim veniet ira illius, et in tempore vindictæ disperdet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Noli anxius esse in divitiis injustis: non enim proderunt tibi in die obductionis et vindictæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Non ventiles te in omnem ventum, et non eas in omnem viam: sic enim omnis peccator probatur in duplici lingua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Esto firmus in via Domini, et in veritate sensus tui et scientia: et prosequatur te verbum pacis et justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Esto mansuetus ad audiendum verbum, ut intelligas, et cum sapientia proferas responsum verum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Si est tibi intellectus, responde proximo: sin autem, sit manus tua super os tuum, ne capiaris in verbo indisciplinato, et confundaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Honor et gloria in sermone sensati: lingua vero imprudentis subversio est ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Non appelleris susurro, et lingua tua ne capiaris et confundaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'super furem enim est confusio et pœnitentia, et denotatio pessima super bilinguem: susurratori autem odium, et inimicitia, et contumelia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 18, 'Justifica pusillum et magnum similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Noli fieri pro amico inimicus proximo: improperium enim et contumeliam malus hæreditabit: et omnis peccator invidus et bilinguis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Non te extollas in cogitatione animæ tuæ velut taurus, ne forte elidatur virtus tua per stultitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'et folia tua comedat, et fructus tuos perdat, et relinquaris velut lignum aridum in eremo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Anima enim nequam disperdet qui se habet, et in gaudium inimicis dat illum, et deducet in sortem impiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Verbum dulce multiplicat amicos et mitigat inimicos, et lingua eucharis in bono homine abundat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Multi pacifici sint tibi: et consiliarius sit tibi unus de mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Si possides amicum, in tentatione posside eum, et ne facile credas ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Est enim amicus secundum tempus suum, et non permanebit in die tribulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Et est amicus qui convertitur ad inimicitiam, et est amicus qui odium et rixam et convitia denudabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Est autem amicus socius mensæ, et non permanebit in die necessitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Amicus si permanserit fixus, erit tibi quasi coæqualis, et in domesticis tuis fiducialiter aget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Si humiliaverit se contra te, et a facie tua absconderit se, unanimem habebis amicitiam bonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Ab inimicis tuis separare, et ab amicis tuis attende.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Amicus fidelis protectio fortis: qui autem invenit illum, invenit thesaurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 15, 'Amico fideli nulla est comparatio, et non est digna ponderatio auri et argenti contra bonitatem fidei illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 16, 'Amicus fidelis medicamentum vitæ et immortalitatis: et qui metuunt Dominum, invenient illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 17, 'Qui timet Deum æque habebit amicitiam bonam, quoniam secundum illum erit amicus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 18, 'Fili, a juventute tua excipe doctrinam, et usque ad canos invenies sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 19, 'Quasi is qui arat et seminat accede ad eam, et sustine bonos fructus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 20, 'In opere enim ipsius exiguum laborabis, et cito edes de generationibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 21, 'Quam aspera est nimium sapientia indoctis hominibus! et non permanebit in illa excors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 22, 'Quasi lapidis virtus probatio erit in illis: et non demorabuntur projicere illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 23, 'Sapientia enim doctrinæ secundum nomen est ejus, et non est multis manifestata: quibus autem cognita est, permanet usque ad conspectum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 24, 'Audi, fili, et accipe consilium intellectus, et ne abjicias consilium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 25, 'Injice pedem tuum in compedes illius, et in torques illius collum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 26, 'Subjice humerum tuum, et porta illam, et ne acedieris vinculis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 27, 'In omni animo tuo accede ad illam, et in omni virtute tua conserva vias ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 28, 'Investiga illam, et manifestabitur tibi: et continens factus, ne derelinquas eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 29, 'in novissimis enim invenies requiem in ea, et convertetur tibi in oblectationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 30, 'Et erunt tibi compedes ejus in protectionem fortitudinis et bases virtutis, et torques illius in stolam gloriæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 31, 'decor enim vitæ est in illa, et vincula illius alligatura salutaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 32, 'Stolam gloriæ indues eam, et coronam gratulationis superpones tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 33, 'Fili, si attenderis mihi, disces: et si accommodaveris animum tuum, sapiens eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 34, 'Si inclinaveris aurem tuam, excipies doctrinam: et si dilexeris audire, sapiens eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 35, 'In multitudine presbyterorum prudentium sta, et sapientiæ illorum ex corde conjungere, ut omnem narrationem Dei possis audire, et proverbia laudis non effugiant a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 36, 'Et si videris sensatum, evigila ad eum, et gradus ostiorum illius exterat pes tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 37, 'Cogitatum tuum habe in præceptis Dei, et in mandatis illius maxime assiduus esto: et ipse dabit tibi cor, et concupiscentia sapientiæ dabitur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Noli facere mala, et non te apprehendent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'discede ab iniquo, et deficient mala abs te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Fili, non semines mala in sulcis injustitiæ, et non metes ea in septuplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Noli quærere a Domino ducatum, neque a rege cathedram honoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Non te justifices ante Deum, quoniam agnitor cordis ipse est: et penes regem noli velle videri sapiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Noli quærere fieri judex, nisi valeas virtute irrumpere iniquitates: ne forte extimescas faciem potentis, et ponas scandalum in æquitate tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Non pecces in multitudinem civitatis, nec te immittas in populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'neque alliges duplicia peccata, nec enim in uno eris immunis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Noli esse pusillanimis in animo tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'exorare et facere eleemosynam ne despicias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Ne dicas: In multitudine munerum meorum respiciet Deus, et offerente me Deo altissimo, munera mea suscipiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Non irrideas hominem in amaritudine animæ: est enim qui humiliat et exaltat circumspector Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Noli amare mendacium adversus fratrem tuum, neque in amicum similiter facias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Noli velle mentiri omne mendacium: assiduitas enim illius non est bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Noli verbosus esse in multitudine presbyterorum, et non iteres verbum in oratione tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Non oderis laboriosa opera, et rusticationem creatam ab Altissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Non te reputes in multitudine indisciplinatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Memento iræ, quoniam non tardabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Humilia valde spiritum tuum, quoniam vindicta carnis impii ignis et vermis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Noli prævaricari in amicum pecuniam differentem, neque fratrem carissimum auro spreveris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Noli discedere a muliere sensata et bona, quam sortitus es in timore Domini: gratia enim verecundiæ illius super aurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Non lædas servum in veritate operantem, neque mercenarium dantem animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Servus sensatus sit tibi dilectus quasi anima tua: non defraudes illum libertate, neque inopem derelinquas illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Pecora tibi sunt, attende illis: et si sunt utilia, perseverent apud te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Filii tibi sunt? erudi illos, et curva illos a pueritia illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Filiæ tibi sunt? serva corpus illarum, et non ostendas hilarem faciem tuam ad illas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Trade filiam, et grande opus feceris: et homini sensato da illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 28, 'Mulier si est tibi secundum animam tuam, non projicias illam: et odibili non credas te. In toto corde tuo');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 29, 'honora patrem tuum, et gemitus matris tuæ ne obliviscaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 30, 'memento quoniam nisi per illos natus non fuisses: et retribue illis, quomodo et illi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 31, 'In tota anima tua time Dominum, et sacerdotes illius sanctifica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 32, 'In omni virtute tua dilige eum qui te fecit, et ministros ejus ne derelinquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 33, 'Honora Deum ex tota anima tua, et honorifica sacerdotes, et propurga te cum brachiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 34, 'Da illis partem, sicut mandatum est tibi, primitiarum et purgationis, et de negligentia tua purga te cum paucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 35, 'Datum brachiorum tuorum, et sacrificium sanctificationis offeres Domino, et initia sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 36, 'Et pauperi porrige manum tuam, ut perficiatur propitiatio et benedictio tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 37, 'Gratia dati in conspectu omnis viventis, et mortuo non prohibeas gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 38, 'Non desis plorantibus in consolatione, et cum lugentibus ambula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 39, 'Non te pigeat visitare infirmum: ex his enim in dilectione firmaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 40, 'In omnibus operibus tuis memorare novissima tua, et in æternum non peccabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Non litiges cum homine potente, ne forte incidas in manus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Non contendas cum viro locuplete, ne forte contra te constituat litem tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'multos enim perdidit aurum et argentum, et usque ad cor regum extendit et convertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Non litiges cum homine linguato, et non strues in ignem illius ligna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Non communices homini indocto, ne male de progenie tua loquatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Ne despicias hominem avertentem se a peccato, neque improperes ei: memento quoniam omnes in correptione sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Ne spernas hominem in sua senectute, etenim ex nobis senescunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Noli de mortuo inimico tuo gaudere: sciens quoniam omnes morimur, et in gaudium nolumus venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Ne despicias narrationem presbyterorum sapientium, et in proverbiis eorum conversare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'ab ipsis enim disces sapientiam et doctrinam intellectus, et servire magnatis sine querela.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Non te prætereat narratio seniorum, ipsi enim didicerunt a patribus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'quoniam ab ipsis disces intellectum, et in tempore necessitatis dare responsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Non incendas carbones peccatorum arguens eos, et ne incendaris flamma ignis peccatorum illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Ne contra faciem stes contumeliosi, ne sedeat quasi insidiator ori tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Noli fœnerari homini fortiori te: quod si fœneraveris, quasi perditum habe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Non spondeas super virtutem tuam: quod si spoponderis, quasi restituens cogita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Non judices contra judicem, quoniam secundum quod justum est judicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Cum audace non eas in via, ne forte gravet mala sua in te: ipse enim secundum voluntatem suam vadit, et simul cum stultitia illius peries.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 19, 'Cum iracundo non facias rixam, et cum audace non eas in desertum: quoniam quasi nihil est ante illum sanguis, et ubi non est adjutorium, elidet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 20, 'Cum fatuis consilium non habeas: non enim poterunt diligere nisi quæ eis placent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 21, 'Coram extraneo ne facias consilium: nescis enim quid pariet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 22, 'Non omni homini cor tuum manifestes, ne forte inferat tibi gratiam falsam, et convicietur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Non zeles mulierem sinus tui, ne ostendat super te malitiam doctrinæ nequam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Non des mulieri potestatem animæ tuæ, ne ingrediatur in virtutem tuam, et confundaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Ne respicias mulierem multivolam, ne forte incidas in laqueos illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Cum saltatrice ne assiduus sis, nec audias illam, ne forte pereas in efficacia illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Virginem ne conspicias, ne forte scandalizeris in decore illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Ne des fornicariis animam tuam in ullo, ne perdas te et hæreditatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Noli circumspicere in vicis civitatis, nec oberraveris in plateis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Averte faciem tuam a muliere compta, et ne circumspicias speciem alienam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Propter speciem mulieris multi perierunt: et ex hoc concupiscentia quasi ignis exardescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Omnis mulier quæ est fornicaria, quasi stercus in via conculcabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Speciem mulieris alienæ multi admirati, reprobi facti sunt: colloquium enim illius quasi ignis exardescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 12, 'Cum aliena muliere ne sedeas omnino, nec accumbas cum ea super cubitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 13, 'et non alterceris cum illa in vino, ne forte declinet cor tuum in illam, et sanguine tuo labaris in perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 14, 'Ne derelinquas amicum antiquum: novus enim non erit similis illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 15, 'Vinum novum amicus novus: veterascet, et cum suavitate bibes illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 16, 'Non zeles gloriam et opes peccatoris: non enim scis quæ futura sit illius subversio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 17, 'Non placeat tibi injuria injustorum, sciens quoniam usque ad inferos non placebit impius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 18, 'Longe abesto ab homine potestatem habente occidendi, et non suspicaberis timorem mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 19, 'Et si accesseris ad illum, noli aliquid committere, ne forte auferat vitam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 20, 'Communionem mortis scito, quoniam in medio laqueorum ingredieris, et super dolentium arma ambulabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 21, 'Secundum virtutem tuam cave te a proximo tuo, et cum sapientibus et prudentibus tracta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 22, 'Viri justi sint tibi convivæ, et in timore Dei sit tibi gloriatio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 23, 'et in sensu sit tibi cogitatus Dei, et omnis enarratio tua in præceptis Altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 24, 'In manu artificum opera laudabuntur, et princeps populi in sapientia sermonis sui, in sensu vero seniorum verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 25, 'Terribilis est in civitate sua homo linguosus: et temerarius in verbo suo odibilis erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Judex sapiens judicabit populum suum, et principatus sensati stabilis erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Secundum judicem populi, sic et ministri ejus: et qualis rector est civitatis, tales et inhabitantes in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Rex insipiens perdet populum suum: et civitates inhabitabuntur per sensum potentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'In manu Dei potestas terræ: et utilem rectorem suscitabit in tempus super illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'In manu Dei prosperitas hominis, et super faciem scribæ imponet honorem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Omnis injuriæ proximi ne memineris, et nihil agas in operibus injuriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Odibilis coram Deo est et hominibus superbia, et execrabilis omnis iniquitas gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Regnum a gente in gentem transfertur propter injustitias, et injurias, et contumelias, et diversos dolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Avaro autem nihil est scelestius. Quid superbit terra et cinis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Nihil est iniquius quam amare pecuniam: hic enim et animam suam venalem habet, quoniam in vita sua projecit intima sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Omnis potentatus brevis vita; languor prolixior gravat medicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Brevem languorem præcidit medicus: sic et rex hodie est, et cras morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Cum enim morietur homo, hæreditabit serpentes, et bestias, et vermes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Initium superbiæ hominis apostatare a Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'quoniam ab eo qui fecit illum recessit cor ejus, quoniam initium omnis peccati est superbia. Qui tenuerit illam adimplebitur maledictis, et subvertet eum in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Propterea exhonoravit Dominus conventus malorum, et destruxit eos usque in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Sedes ducum superborum destruxit Deus, et sedere fecit mites pro eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Radices gentium superbarum arefecit Deus, et plantavit humiles ex ipsis gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Terras gentium evertit Dominus, et perdidit eas usque ad fundamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Arefecit ex ipsis, et disperdidit eos, et cessare fecit memoriam eorum a terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Memoria superborum perdidit Deus, et reliquit memoriam humilium sensu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Non est creata hominibus superbia, neque iracundia nationi mulierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 23, 'Semen hominum honorabitur hoc, quod timet Deum: semen autem hoc exhonorabitur, quod præterit mandata Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 24, 'In medio fratrum rector illorum in honore: et qui timent Dominum erunt in oculis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 25, 'Gloria divitum, honoratorum, et pauperum, timor Dei est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 26, 'Noli despicere hominem justum pauperem, et noli magnificare virum peccatorem divitem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 27, 'Magnus, et judex, et potens est in honore: et non est major illo qui timet Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 28, 'Servo sensato liberi servient: et vir prudens et disciplinatus non murmurabit correptus, et inscius non honorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 29, 'Noli extollere te in faciendo opere tuo, et noli cunctari in tempore angustiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 30, 'Melior est qui operatur et abundat in omnibus, quam qui gloriatur et eget pane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 31, 'Fili, in mansuetudine serva animam tuam, et da illi honorem secundum meritum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 32, 'Peccantem in animam suam quis justificabit? et quis honorificabit exhonorantem animam suam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 33, 'Pauper gloriatur per disciplinam et timorem suum: et est homo qui honorificatur propter substantiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 34, 'Qui autem gloriatur in paupertate, quanto magis in substantia! et qui gloriatur in substantia, paupertatem vereatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Sapientia humiliati exaltabit caput illius, et in medio magnatorum consedere illum faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Non laudes virum in specie sua, neque spernas hominem in visu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Brevis in volatilibus est apis, et initium dulcoris habet fructus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'In vestitu ne glorieris umquam, nec in die honoris tui extollaris: quoniam mirabilia opera Altissimi solius, et gloriosa, et absconsa, et invisa opera illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Multi tyranni sederunt in throno: et insuspicabilis portavit diadema.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Multi potentes oppressi sunt valide, et gloriosi traditi sunt in manus alterorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Priusquam interroges, ne vituperes quemquam: et cum interrogaveris, corripe juste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Priusquam audias, ne respondeas verbum: et in medio sermonum ne adjicias loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'De ea re quæ te non molestat, ne certeris: et in judicio peccantium ne consistas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Fili, ne in multis sint actus tui: et si dives fueris, non eris immunis a delicto. Si enim secutus fueris, non apprehendes: et non effugies, si præcucurreris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Est homo laborans et festinans, et dolens: impius, et tanto magis non abundabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Est homo marcidus egens recuperatione, plus deficiens virtute, et abundans paupertate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'et oculus Dei respexit illum in bono, et erexit eum ab humilitate ipsius, et exaltavit caput ejus: et mirati sunt in illo multi, et honoraverunt Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Bona et mala, vita et mors, paupertas et honestas, a Deo sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'sapientia, et disciplina, et scientia legis, apud Deum: dilectio, et viæ bonorum, apud ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Error et tenebræ peccatoribus concreata sunt: qui autem exsultant in malis consenescunt in malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Datio Dei permanet justis, et profectus illius successus habebit in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Est qui locupletatur parce agendo, et hæc est pars mercedis illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'In eo quod dicit: Inveni requiem mihi, et nunc manducabo de bonis meis solus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'et nescit quod tempus præteriet, et mors appropinquet, et relinquat omnia aliis, et morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Sta in testamento tuo, et in illo colloquere, et in opere mandatorum tuorum veterasce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Ne manseris in operibus peccatorum: confide autem in Deo, et mane in loco tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Facile est enim in oculis Dei subito honestare pauperem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Benedictio Dei in mercedem justi festinat, et in hora veloci processus illius fructificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Ne dicas: Quid est mihi opus? et quæ erunt mihi ex hoc bona?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 26, 'Ne dicas: Sufficiens mihi sum: et quid ex hoc pessimabor?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 27, 'In die bonorum ne immemor sis malorum, et in die malorum ne immemor sis bonorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 28, 'quoniam facile est coram Deo in die obitus retribuere unicuique secundum vias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 29, 'Malitia horæ oblivionem facit luxuriæ magnæ, et in fine hominis denudatio operum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 30, 'Ante mortem ne laudes hominem quemquam: quoniam in filiis suis agnoscitur vir.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 31, 'Non omnem hominem inducas in domum tuam: multæ enim sunt insidiæ dolosi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 32, 'Sicut enim eructant præcordia fœtentium, et sicut perdix inducitur in caveam, et ut caprea in laqueum: sic et cor superborum, et sicut prospector videns casum proximi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 33, 'Bona enim in mala convertens insidiatur, et in electis imponet maculam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 34, 'A scintilla una augetur ignis, et ab uno doloso augetur sanguis: homo vero peccator sanguini insidiatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 35, 'Attende tibi a pestifero, fabricat enim mala, ne inducat super te subsannationem in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 36, 'Admitte ad te alienigenam: et subvertet te in turbine, et abalienabit te a tuis propriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Si benefeceris, scito cui feceris, et erit gratia in bonis tuis multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Benefac justo, et invenies retributionem magnam: et si non ab ipso, certe a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Non est enim ei bene qui assiduus est in malis, et eleemosynas non danti: quoniam et Altissimus odio habet peccatores, et misertus est pœnitentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Da misericordi, et ne suscipias peccatorem: et impiis et peccatoribus reddet vindictam, custodiens eos in diem vindictæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Da bono, et non receperis peccatorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Benefac humili, et non dederis impio: prohibe panes illi dari, ne in ipsis potentior te sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'nam duplicia mala invenies in omnibus bonis quæcumque feceris illi, quoniam et Altissimus odio habet peccatores, et impiis reddet vindictam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Non agnoscetur in bonis amicus, et non abscondetur in malis inimicus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'In bonis viri, inimici illius in tristitia: et in malitia illius, amicus agnitus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Non credas inimico tuo in æternum: sicut enim æramentum æruginat nequitia illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'et si humiliatus vadat curvus, adjice animum tuum, et custodi te ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Non statuas illum penes te, nec sedeat ad dexteram tuam, ne forte conversus in locum tuum, inquirat cathedram tuam, et in novissimo agnosces verba mea, et in sermonibus meis stimuleris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Quis miserebitur incantatori a serpente percusso, et omnibus qui appropiant bestiis? et sic qui comitatur cum viro iniquo, et obvolutus est in peccatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Una hora tecum permanebit: si autem declinaveris, non supportabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'In labiis suis indulcat inimicus, et in corde suo insidiatur ut subvertat te in foveam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'In oculis suis lacrimatur inimicus, et si invenerit tempus, non satiabitur sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Et si incurrerint tibi mala, invenies eum illic priorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'In oculis suis lacrimatur inimicus, et quasi adjuvans suffodiet plantas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Caput suum movebit, et plaudet manu, et multa susurrans commutabit vultum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Qui tetigerit picem inquinabitur ab ea: et qui communicaverit superbo induet superbiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Pondus super se tollat qui honestiori se communicat, et ditiori te ne socius fueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Quid communicabit cacabus ad ollam? quando enim se colliserint, confringetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Dives injuste egit, et fremet: pauper autem læsus tacebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Si largitus fueris, assumet te: et si non habueris, derelinquet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Si habes, convivet tecum, et evacuabit te: et ipse non dolebit super te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Si necessarius illi fueris, supplantabit te, et subridens spem dabit, narrans tibi bona, et dicet: Quid opus est tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Et confundet te in cibis suis, donec te exinaniat bis et ter: et in novissimo deridebit te, et postea videns derelinquet te, et caput suum movebit ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Humiliare Deo, et exspecta manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Attende ne seductus in stultitiam humilieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Noli esse humilis in sapientia tua, ne humiliatus in stultitiam seducaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Advocatus a potentiore, discede: ex hoc enim magis te advocabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Ne improbus sis, ne impingaris: et ne longe sis ab eo, ne eas in oblivionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Ne retineas ex æquo loqui cum illo, nec credas multis verbis illius: ex multa enim loquela tentabit te, et subridens interrogabit te de absconditis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Immitis animus illius conservabit verba tua: et non parcet de malitia, et de vinculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Cave tibi, et attende diligenter auditui tuo, quoniam cum subversione tua ambulas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'audiens vero illa, quasi in somnis vide, et vigilabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Omni vita tua dilige Deum, et invoca illum in salute tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Omne animal diligit simile sibi, sic et omnis homo proximum sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Omnis caro ad similem sibi conjungetur, et omnis homo simili sui sociabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Si communicabit lupus agno aliquando, sic peccator justo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Quæ communicatio sancto homini ad canem? aut quæ pars diviti ad pauperem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Venatio leonis onager in eremo: sic et pascua divitum sunt pauperes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 24, 'Et sicut abominatio est superbo humilitas, sic et execratio divitis pauper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 25, 'Dives commotus confirmatur ab amicis suis: humilis autem cum ceciderit, expelletur et a notis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 26, 'Diviti decepto multi recuperatores: locutus est superbia, et justificaverunt illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 27, 'Humilis deceptus est, insuper et arguitur: locutus est sensate, et non est datus ei locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 28, 'Dives locutus est, et omnes tacuerunt, et verbum illius usque ad nubes perducent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 29, 'Pauper locutus est, et dicunt: Quis est hic? et si offenderit, subvertent illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 30, 'Bona est substantia cui non est peccatum in conscientia: et nequissima paupertas in ore impii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 31, 'Cor hominis immutat faciem illius, sive in bona, sive in mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 32, 'Vestigium cordis boni et faciem bonam difficile invenies, et cum labore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Beatus vir qui non est lapsus verbo ex ore suo, et non est stimulatus in tristitia delicti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Felix qui non habuit animi sui tristitiam, et non excidit a spe sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Viro cupido et tenaci sine ratione est substantia: et homini livido ad quid aurum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Qui acervat ex animo suo injuste, aliis congregat, et in bonis illius alius luxuriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Qui sibi nequam est, cui alii bonus erit? et non jucundabitur in bonis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Qui sibi invidet, nihil est illo nequius: et hæc redditio est malitiæ illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Et si bene fecerit, ignoranter et non volens facit: et in novissimo manifestat malitiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Nequam est oculus lividi: et avertens faciem suam, et despiciens animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Insatiabilis oculus cupidi in parte iniquitatis: non satiabitur donec consumat arefaciens animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Oculus malus ad mala, et non saturabitur pane, sed indigens et in tristitia erit super mensam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Fili, si habes, benefac tecum, et Deo dignas oblationes offer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Memor esto quoniam mors non tardat, et testamentum inferorum, quia demonstratum est tibi: testamentum enim hujus mundi morte morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Ante mortem benefac amico tuo, et secundum vires tuas exporrigens da pauperi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Non defrauderis a die bono, et particula boni doni non te prætereat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Nonne aliis relinques dolores et labores tuos in divisione sortis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Da et accipe, et justifica animam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ante obitum tuum operare justitiam, quoniam non est apud inferos invenire cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Omnis caro sicut fœnum veterascet, et sicut folium fructificans in arbore viridi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Alia generantur, et alia dejiciuntur: sic generatio carnis et sanguinis, alia finitur, et alia nascitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Omne opus corruptibile in fine deficiet, et qui illud operatur ibit cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Et omne opus electum justificabitur, et qui operatur illud honorabitur in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Beatus vir qui in sapientia morabitur, et qui in justitia sua meditabitur, et in sensu cogitabit circumspectionem Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'qui excogitat vias illius in corde suo, et in absconditis suis intelligens, vadens post illam quasi investigator, et in viis illius consistens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 24, 'qui respicit per fenestras illius, et in januis illius audiens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 25, 'qui requiescit juxta domum illius, et in parietibus illius figens palum, statuet casulam suam ad manus illius, et requiescent in casula illius bona per ævum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 26, 'Statuet filios suos sub tegmine illius, et sub ramis ejus morabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 27, 'Protegetur sub tegmine illius a fervore, et in gloria ejus requiescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Qui timet Deum faciet bona, et qui continens est justitiæ apprehendet illam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'et obviabit illi quasi mater honorificata, et quasi mulier a virginitate suscipiet illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Cibabit illum pane vitæ et intellectus, et aqua sapientiæ salutaris potabit illum: et firmabitur in illo, et non flectetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'et continebit illum, et non confundetur: et exaltabit illum apud proximos suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'et in medio ecclesiæ aperiet os ejus, et adimplebit illum spiritu sapientiæ et intellectus, et stola gloriæ vestiet illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Jucunditatem et exsultationem thesaurizabit super illum, et nomine æterno hæreditabit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Homines stulti non apprehendent illam, et homines sensati obviabunt illi. Homines stulti non videbunt eam: longe enim abest a superbia et dolo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Viri mendaces non erunt illius memores: et viri veraces invenientur in illa, et successum habebunt usque ad inspectionem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 9, 'Non est speciosa laus in ore peccatoris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 10, 'quoniam a Deo profecta est sapientia. Sapientiæ enim Dei astabit laus, et in ore fideli abundabit, et Dominator dabit eam illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 11, 'Non dixeris: Per Deum abest: quæ enim odit ne feceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 12, 'Non dicas: Ille me implanavit: non enim necessarii sunt ei homines impii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 13, 'Omne execramentum erroris odit Dominus, et non erit amabile timentibus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 14, 'Deus ab initio constituit hominem, et reliquit illum in manu consilii sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 15, 'adjecit mandata et præcepta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 16, 'Si volueris mandata servare, conservabunt te, et in perpetuum fidem placitam facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 17, 'Apposuit tibi aquam et ignem, ad quod volueris porrige manum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 18, 'Ante hominem vita et mors, bonum et malum: quod placuerit ei dabitur illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 19, 'quoniam multa sapientia Dei, et fortis in potentia, videns omnes sine intermissione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 20, 'Oculi Domini ad timentes eum, et ipse agnoscit omnem operam hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 21, 'Nemini mandavit impie agere, et nemini dedit spatium peccandi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 22, 'non enim concupiscit multitudinem filiorum infidelium et inutilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Ne jucunderis in filiis impiis, si multiplicentur: nec oblecteris super ipsos, si non est timor Dei in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Non credas vitæ illorum, et ne respexeris in labores eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Melior est enim unus timens Deum, quam mille filii impii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'et utile est mori sine filiis, quam relinquere filios impios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Ab uno sensato inhabitabitur patria: tribus impiorum deseretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Multa talia vidit oculis meus, et fortiora horum audivit auris mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'In synagoga peccantium exardebit ignis, et in gente incredibili exardescet ira.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Non exoraverunt pro peccatis suis antiqui gigantes, qui destructi sunt confidentes suæ virtuti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Et non pepercit peregrinationi Lot, et execratus est eos præ superbia verbi illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Non misertus est illis, gentem totam perdens, et extollentem se in peccatis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Et sicut sexcenta millia peditum, qui congregati sunt in duritia cordis sui: et si unus fuisset cervicatus, mirum si fuisset immunis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Misericordia enim et ira est cum illo: potens exoratio, et effundens iram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Secundum misericordiam suam, sic correptio illius homines secundum opera sua judicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Non effugiet in rapina peccator, et non retardabit sufferentia misericordiam facientis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Omnis misericordia faciet locum unicuique, secundum meritum operum suorum, et secundum intellectum peregrinationis ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Non dicas: A Deo abscondar: et ex summo, quis mei memorabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'in populo magno non agnoscar: quæ est enim anima mea in tam immensa creatura?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Ecce cælum et cæli cælorum, abyssus, et universa terra, et quæ in eis sunt, in conspectu illius commovebuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Montes simul, et colles, et fundamenta terræ, cum conspexerit illa Deus, tremore concutientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Et in omnibus his insensatum est cor, et omne cor intelligitur ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Et vias illius quis intelligit, et procellam quam nec oculus videbit hominis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Nam plurima illius opera sunt in absconsis: sed opera justitiæ ejus quis enuntiabit, aut quis sustinebit? longe enim est testamentum a quibusdam, et interrogatio omnium in consummatione est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Qui minoratur corde cogitat inania, et vir imprudens et errans cogitat stulta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Audi me, fili, et disce disciplinam sensus, et in verbis meis attende in corde tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'et dicam in æquitate disciplinam, et scrutabor enarrare sapientiam: et in verbis meis attende in corde tuo, et dico in æquitate spiritus virtutes quas posuit Deus in opera sua ab initio, et in veritate enuntio scientiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'In judicio Dei opera ejus ab initio, et ab institutione ipsorum distinxit partes illorum, et initia eorum in gentibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Ornavit in æternum opera illorum: nec esurierunt, nec laboraverunt, et non destiterunt ab operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Unusquisque proximum sibi non angustiabit in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'non sis incredibilis verbo illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Post hæc Deus in terram respexit, et implevit illam bonis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'anima omnis vitalis denuntiavit ante faciem ipsius, et in ipsam iterum reversio illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Deus creavit de terra hominem, et secundum imaginem suam fecit illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'et iterum convertit illum in ipsam, et secundum se vestivit illum virtute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Numerum dierum et tempus dedit illi, et dedit illi potestatem eorum quæ sunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Posuit timorem illius super omnem carnem, et dominatus est bestiarum et volatilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Creavit ex ipso adjutorium simile sibi: consilium, et linguam, et oculos, et aures, et cor dedit illis excogitandi, et disciplina intellectus replevit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Creavit illis scientiam spiritus, sensu implevit cor illorum, et mala et bona ostendit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Posuit oculum suum super corda illorum, ostendere illis magnalia operum suorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'ut nomen sanctificationis collaudent, et gloriari in mirabilibus illius; ut magnalia enarrent operum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Addidit illis disciplinam, et legem vitæ hæreditavit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Testamentum æternum constituit cum illis, et justitiam et judicia sua ostendit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Et magnalia honoris ejus vidit oculus illorum, et honorem vocis audierunt aures illorum. Et dixit illis: Attendite ab omni iniquo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Et mandavit illis unicuique de proximo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Viæ illorum coram ipso sunt semper: non sunt absconsæ ab oculis ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'In unamquamque gentem præposuit rectorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'et pars Dei Israël facta est manifesta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Et omnia opera illorum velut sol in conspectu Dei: et oculi ejus sine intermissione inspicientes in viis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Non sunt absconsa testamenta per iniquitatem illorum, et omnes iniquitates eorum in conspectu Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Eleemosyna viri quasi signaculum cum ipso, et gratiam hominis quasi pupillam conservabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Et postea resurget, et retribuet illis retributionem, unicuique in caput ipsorum, et convertet in interiores partes terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Pœnitentibus autem dedit viam justitiæ, et confirmavit deficientes sustinere, et destinavit illis sortem veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Convertere ad Dominum, et relinque peccata tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'precare ante faciem Domini, et minue offendicula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Revertere ad Dominum, et avertere ab injustitia tua, et nimis odito execrationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'et cognosce justitias et judicia Dei, et sta in sorte propositionis, et orationis altissimi Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 25, 'In partes vade sæculi sancti, cum vivis et dantibus confessionem Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 26, 'Non demoreris in errore impiorum: ante mortem confitere: a mortuo, quasi nihil, perit confessio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 27, 'Confiteberis vivens, vivus et sanus confiteberis: et laudabis Deum, et gloriaberis in miserationibus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 28, 'Quam magna misericordia Domini, et propitiatio illius convertentibus ad se!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 29, 'Nec enim omnia possunt esse in hominibus, quoniam non est immortalis filius hominis, et in vanitate malitiæ placuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 30, 'Quid lucidius sole? et hic deficiet; aut quid nequius quam quod excogitavit caro et sanguis? et hoc arguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 31, 'Virtutem altitudinis cæli ipse conspicit: et omnes homines terra et cinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Qui vivet in æternum creavit omnia simul. Deus solus justificabitur, et manet invictus rex in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Quis sufficit enarrare opera illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'quis enim investigabit magnalia ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'virtutem autem magnitudinis ejus quis enuntiabit? aut quis adjiciet enarrare misericordiam ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Non est minuere neque adjicere, nec est invenire magnalia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Cum consummaverit homo, tunc incipiet: et cum quieverit, aporiabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Quid est homo? et quæ est gratia illius? et quid bonum aut quid nequam illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Numerus dierum hominum, ut multum centum anni, quasi gutta aquæ maris deputati sunt: et sicut calculus arenæ, sic exigui anni in die ævi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Propter hoc patiens est Deus in illis, et effundit super eos misericordiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Vidit præsumptionem cordis eorum, quoniam mala est: et cognovit subversionem illorum, quoniam nequam est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Ideo adimplevit propitiationem suam in illis, et ostendit eis viam æquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Miseratio hominis circa proximum suum: misericordia autem Dei super omnem carnem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Qui misericordiam habet, docet et erudit quasi pastor gregem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Miseretur excipientis doctrinam miserationis, et qui festinat in judiciis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Fili, in bonis non des querelam, et in omni dato non des tristitiam verbi mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Nonne ardorem refrigerabit ros? sic et verbum melius quam datum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Nonne ecce verbum super datum bonum? sed utraque cum homine justificato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Stultus acriter improperabit: et datus indisciplinati tabescere facit oculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Ante judicium para justitiam tibi, et antequam loquaris, disce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Ante languorem adhibe medicinam: et ante judicium interroga teipsum, et in conspectu Dei invenies propitiationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Ante languorem humilia te, et in tempore infirmitatis ostende conversationem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Non impediaris orare semper, et ne verearis usque ad mortem justificari, quoniam merces Dei manet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Ante orationem præpara animam tuam, et noli esse quasi homo qui tentat Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Memento iræ in die consummationis, et tempus retributionis in conversatione faciei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Memento paupertatis in tempore abundantiæ, et necessitatum paupertatis in die divitiarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'A mane usque ad vesperam immutabitur tempus, et hæc omnia citata in oculis Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Homo sapiens in omnibus metuet, et in diebus delictorum attendet ab inertia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Omnis astutus agnoscit sapientiam, et invenienti eam dabit confessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Sensati in verbis et ipsi sapienter egerunt, et intellexerunt veritatem et justitiam, et impluerunt proverbia et judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Post concupiscentias tuas non eas, et a voluntate tua avertere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Si præstes animæ tuæ concupiscentias ejus, faciat te in gaudium inimicis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Ne oblecteris in turbis nec in modicis: assidua enim est commissio illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 33, 'Ne fueris mediocris in contentione ex fœnore, et est tibi nihil in sacculo: eris enim invidus vitæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Operarius ebriosus non locupletabitur: et qui spernit modica paulatim decidet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Vinum et mulieres apostatare faciunt sapientes, et arguent sensatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Et qui se jungit fornicariis erit nequam: putredo et vermes hæreditabunt illum: et extolletur in exemplum majus, et tolletur de numero anima ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Qui credit cito levis corde est, et minorabitur: et qui delinquit in animam suam, insuper habebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Qui gaudet iniquitate, denotabitur: et qui odit correptionem, minuetur vita: et qui odit loquacitatem, extinguit malitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Qui peccat in animam suam, pœnitebit: et qui jucundatur in malitia, denotabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Ne iteres verbum nequam et durum, et non minoraberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Amico et inimico noli narrare sensum tuum: et si est tibi delictum, noli denudare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'audiet enim te, et custodiet te, et quasi defendens peccatum, odiet te, et sic aderit tibi semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Audisti verbum adversus proximum tuum? commoriatur in te, fidens quoniam non te dirumpet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'A facie verbi parturit fatuus, tamquam gemitus partus infantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Sagitta infixa femori carnis, sic verbum in corde stulti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Corripe amicum, ne forte non intellexerit, et dicat: Non feci: aut, si fecerit, ne iterum addat facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Corripe proximum, ne forte non dixerit: et si dixerit, ne forte iteret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 15, 'Corripe amicum, sæpe enim fit commissio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 16, 'et non omni verbo credas. Est qui labitur lingua, sed non ex animo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 17, 'quis est enim qui non deliquerit in lingua sua? Corripe proximum antequam commineris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 18, 'et da locum timori Altissimi: quia omnis sapientia timor Dei, et in illa timere Deum, et in omni sapientia dispositio legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 19, 'Et non est sapientia nequitiæ disciplina, et non est cogitatus peccatorum prudentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 20, 'Est nequitia, et in ipsa execratio, et est insipiens qui minuitur sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 21, 'Melior est homo qui minuitur sapientia, et deficiens sensu, in timore, quam qui abundat sensu, et transgreditur legem Altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 22, 'Est solertia certa, et ipsa iniqua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 23, 'et est qui emittit verbum certum enarrans veritatem. Est qui nequiter humiliat se, et interiora ejus plena sunt dolo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 24, 'et est qui se nimium submittit a multa humilitate: et est qui inclinat faciem suam, et fingit se non videre quod ignoratum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 25, 'et si ab imbecillitate virium vetetur peccare, si invenerit tempus malefaciendi, malefaciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 26, 'Ex visu cognoscitur vir, et ab occursu faciei cognoscitur sensatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 27, 'Amictus corporis, et risus dentium, et ingressus hominis, enuntiant de illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 28, 'Est correptio mendax in ira contumeliosi, et est judicium quod non probatur esse bonum: et est tacens, et ipse est prudens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Quam bonum est arguere, quam irasci, et confitentem in oratione non prohibere!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Concupiscentia spadonis devirginabit juvenculam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'sic qui facit per vim judicium iniquum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Quam bonum est correptum manifestare pœnitentiam! sic enim effugies voluntarium peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Est tacens qui invenitur sapiens: et est odibilis qui procax est ad loquendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Est tacens non habens sensum loquelæ: et est tacens sciens tempus aptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Homo sapiens tacebit usque ad tempus: lascivus autem et imprudens non servabunt tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Qui multis utitur verbis lædet animam suam: et qui potestatem sibi sumit injuste, odietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Est processio in malis viro indisciplinato, et est inventio in detrimentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Est datum quod non est utile, et est datum cujus retributio duplex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Est propter gloriam minoratio, et est qui ab humilitate levabit caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Est qui multa redimat modico pretio, et restituens ea in septuplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Sapiens in verbis seipsum amabilem facit: gratiæ autem fatuorum effundentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Datus insipientis non erit utilis tibi: oculi enim illius septemplices sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Exigua dabit, et multa improperabit: et apertio oris illius inflammatio est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Hodie fœneratur quis, et cras expetit: odibilis est homo hujusmodi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Fatuo non erit amicus, et non erit gratia bonis illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'qui enim edunt panem illius, falsæ linguæ sunt. Quoties et quanti irridebunt eum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'neque enim quod habendum erat directo sensu distribuit; similiter et quod non erat habendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Lapsus falsæ linguæ quasi qui in pavimento cadens: sic casus malorum festinanter veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Homo acharis quasi fabula vana, in ore indisciplinatorum assidua erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Ex ore fatui reprobabitur parabola: non enim dicit illam in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Est qui vetatur peccare præ inopia, et in requie sua stimulabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Est qui perdet animam suam præ confusione, et ab imprudenti persona perdet eam: personæ autem acceptione perdet se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Est qui præ confusione promittit amico, et lucratus est eum inimicum gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Opprobrium nequam in homine mendacium: et in ore indisciplinatorum assidue erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Potior fur quam assiduitas viri mendacis: perditionem autem ambo hæreditabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Mores hominum mendacium sine honore, et confusio illorum cum ipsis sine intermissione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Sapiens in verbis producet seipsum, et homo prudens placebit magnatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Qui operatur terram suam inaltabit acervum frugum, et qui operatur justitiam, ipse exaltabitur: qui vero placet magnatis effugiet iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Xenia et dona excæcant oculos judicum, et quasi mutus, in ore avertit correptiones eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Sapientia absconsa, et thesaurus invisus, quæ utilitas in utrisque?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Melior est qui celat insipientiam suam, quam homo qui abscondit sapientiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Fili, peccasti, non adjicias iterum: sed et de pristinis deprecare, ut tibi dimittantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Quasi a facie colubri fuge peccata: et si accesseris ad illa, suscipient te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Dentes leonis dentes ejus, interficientes animas hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Quasi rhomphæa bis acuta omnis iniquitas: plagæ illius non est sanitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Objurgatio et injuriæ annullabunt substantiam, et domus quæ nimis locuples est annullabitur superbia: sic substantia superbi eradicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Deprecatio pauperis ex ore usque ad aures ejus perveniet, et judicium festinato adveniet illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Qui odit correptionem vestigium est peccatoris, et qui timet Deum convertetur ad cor suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Notus a longe potens lingua audaci, et sensatus scit labi se ab ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Qui ædificat domum suam impendiis alienis, quasi qui colligit lapides suos in hieme.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Stupa collecta synagoga peccantium, et consummatio illorum flamma ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Via peccatorum complanata lapidibus: et in fine illorum inferi, et tenebræ, et pœnæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Qui custodit justitiam, continebit sensum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Consummatio timoris Dei, sapientia et sensus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Non erudietur qui non est sapiens in bono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Est autem sapientia quæ abundat in malo, et non est sensus ubi est amaritudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Scientia sapientis tamquam inundatio abundabit, et consilium illius sicut fons vitæ permanet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Cor fatui quasi vas confractum, et omnem sapientiam non tenebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Verbum sapiens quodcumque audierit scius, laudabit, et ad se adjiciet: audivit luxuriosus, et displicebit illi, et projiciet illud post dorsum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Narratio fatui quasi sarcina in via: nam in labiis sensati invenietur gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Os prudentis quæritur in ecclesia, et verba illius cogitabunt in cordibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Tamquam domus exterminata, sic fatuo sapientia: et scientia insensati inenarrabilia verba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Compedes in pedibus, stulto doctrina: et quasi vincula manuum super manum dextram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Fatuus in risu exaltat vocem suam: vir autem sapiens vix tacite ridebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Ornamentum aureum prudenti doctrina, et quasi brachiale in brachio dextro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Pes fatui facilis in domum proximi: et homo peritus confundetur a persona potentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Stultus a fenestra respiciet in domum: vir autem eruditus foris stabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Stultitia hominis auscultare per ostium: et prudens gravabitur contumelia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Labia imprudentium stulta narrabunt; verba autem prudentium statera ponderabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'In ore fatuorum cor illorum, et in corde sapientium os illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Dum maledicit impius diabolum, maledicit ipse animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Susurro coinquinabit animam suam, et in omnibus odietur, et qui cum eo manserit odiosus erit: tacitus et sensatus honorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'In lapide luteo lapidatus est piger: et omnes loquentur super aspernationem illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'De stercore boum lapidatus est piger: et omnis qui tetigerit eum excutiet manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Confusio patris est de filio indisciplinato: filia autem in deminoratione fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Filia prudens hæreditas viro suo: nam quæ confundit, in contumeliam fit genitoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Patrem et virum confundit audax, et ab impiis non minorabitur: ab utrisque autem inhonorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Musica in luctu importuna narratio: flagella et doctrina in omni tempore sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Qui docet fatuum, quasi qui conglutinat testam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Qui narrat verbum non audienti, quasi qui excitat dormientem de gravi somno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Cum dormiente loquitur qui enarrat stulto sapientiam: et in fine narrationis dicit: Quis est hic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Supra mortuum plora, defecit enim lux ejus: et supra fatuum plora, defecit enim sensus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Modicum plora super mortuum, quoniam requievit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'nequissimi enim nequissima vita super mortem fatui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Luctus mortui septem dies: fatui autem et impii omnes dies vitæ illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Cum stulto ne multum loquaris, et cum insensato ne abieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Serva te ab illo, ut non molestiam habeas, et non coinquinaberis peccato illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Deflecte ab illo, et invenies requiem, et non acediaberis in stultitia illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Super plumbum quid gravabitur? et quod illi aliud nomen quam fatuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Arenam, et salem, et massam ferri facilius est ferre quam hominem imprudentem, et fatuum, et impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Loramentum ligneum colligatum in fundamento ædificii non dissolvetur, sic et cor confirmatum in cogitatione consilii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Cogitatus sensati in omni tempore metu non depravabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Sicut pali in excelsis, et cæmenta sine impensa posita, contra faciem venti non permanebunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'sic et cor timidum in cogitatione stulti contra impetum timoris non resistet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Sicut cor trepidum in cogitatione fatui omni tempore non metuet, sic et qui in præceptis Dei permanet semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Pungens oculum deducit lacrimas, et qui pungit cor profert sensum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Mittens lapidem in volatilia, dejiciet illa: sic et qui conviciatur amico, dissolvit amicitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ad amicum etsi produxeris gladium, non desperes: est enim regressus. Ad amicum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'si aperueris os triste, non timeas: est enim concordatio: excepto convitio, et improperio, et superbia, et mysterii revelatione, et plaga dolosa: in his omnibus effugiet amicus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Fidem posside cum amico in paupertate illius, ut et in bonis illius læteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'In tempore tribulationis illius permane illi fidelis, ut et in hæreditate illius cohæres sis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Ante ignem camini vapor et fumus ignis inaltatur: sic et ante sanguinem maledicta, et contumeliæ, et minæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Amicum salutare non confundar, a facie illius non me abscondam: et si mala mihi evenerint per illum, sustinebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 32, 'Omnis qui audiet cavebit se ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 33, 'Quis dabit ori meo custodiam, et super labia mea signaculum certum, ut non cadam ab ipsis, et lingua mea perdat me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Domine, pater et dominator vitæ meæ, ne derelinquas me in consilio eorum, nec sinas me cadere in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Quis superponet in cogitatu meo flagella, et in corde meo doctrinam sapientiæ, ut ignorationibus eorum non parcant mihi, et non appareant delicta eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'et ne adincrescant ignorantiæ meæ, et multiplicentur delicta mea, et peccata mea abundent, et incidam in conspectu adversariorum meorum, et gaudeat super me inimicus meus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Domine, pater et Deus vitæ meæ, ne derelinquas me in cogitatu illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Extollentiam oculorum meorum ne dederis mihi, et omne desiderium averte a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Aufer a me ventris concupiscentias, et concubitus concupiscentiæ ne apprehendant me, et animæ irreverenti et infrunitæ ne tradas me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Doctrinam oris audite, filii: et qui custodierit illam non periet labiis, nec scandalizabitur in operibus nequissimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'In vanitate sua apprehenditur peccator: et superbus et maledicus scandalizabitur in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Jurationi non assuescat os tuum: multi enim casus in illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Nominatio vero Dei non sit assidua in ore tuo, et nominibus sanctorum non admiscearis, quoniam non erit immunis ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Sicut enim servus interrogatus assidue a livore non minuitur, sic omnis jurans et nominans in toto a peccato non purgabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Vir multum jurans implebitur iniquitate, et non discedet a domo illius plaga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Et si frustraverit, delictum illius super ipsum erit: et si dissimulaverit, delinquit dupliciter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'et si in vacuum juraverit, non justificabitur: replebitur enim retributione domus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Est et alia loquela contraria morti: non inveniatur in hæreditate Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Etenim a misericordibus omnia hæc auferentur, et in delictis non volutabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Indisciplinatæ loquelæ non assuescat os tuum: est enim in illa verbum peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Memento patris et matris tuæ: in medio enim magnatorum consistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'ne forte obliviscatur te Deus in conspectu illorum, et assiduitate tua infatuatus, improperium patiaris, et maluisses non nasci, et diem nativitatis tuæ maledicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Homo assuetus in verbis improperii in omnibus diebus suis non erudietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Duo genera abundant in peccatis, et tertium adducit iram et perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Anima calida quasi ignis ardens, non extinguetur donec aliquid glutiat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'et homo nequam in ore carnis suæ non desinet donec incendat ignem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Homini fornicario omnis panis dulcis: non fatigabitur transgrediens usque ad finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Omnis homo qui transgreditur lectum suum, contemnens in animam suam, et dicens: Quis me videt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Tenebræ circumdant me, et parietes cooperiunt me, et nemo circumspicit me: quem vereor? delictorum meorum non memorabitur Altissimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Et non intelligit quoniam omnia videt oculus illius, quoniam expellit a se timorem Dei hujusmodi hominis timor, et oculi hominum timentes illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'et non cognovit quoniam oculi Domini multo plus lucidiores sunt super solem, circumspicientes omnes vias hominum, et profundum abyssi, et hominum corda, intuentes in absconditas partes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Domino enim Deo antequam crearentur omnia sunt agnita: sic et post perfectum respicit omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Hic in plateis civitatis vindicabitur, et quasi pullus equinus fugabitur, et ubi non speravit apprehendetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Et erit dedecus omnibus, eo quod non intellexerit timorem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Sic et mulier omnis relinquens virum suum, et statuens hæreditatem ex alieno matrimonio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'primo enim in lege Altissimi incredibilis fuit: secundo in virum suum deliquit: tertio in adulterio fornicata est, et ex alio viro filios statuit sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Hæc in ecclesiam adducetur, et in filios ejus respicietur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'non tradent filii ejus radices, et rami ejus non dabunt fructum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'derelinquet in maledictum memoriam ejus, et dedecus illius non delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Et agnoscent qui derelicti sunt, quoniam nihil melius est quam timor Dei, et nihil dulcius quam respicere in mandatis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Gloria magna est sequi Dominum: longitudo enim dierum assumetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Sapientia laudabit animam suam, et in Deo honorabitur, et in medio populi sui gloriabitur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'et in ecclesiis Altissimi aperiet os suum, et in conspectu virtutis illius gloriabitur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'et in medio populi sui exaltabitur, et in plenitudine sancta admirabitur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'et in multitudine electorum habebit laudem, et inter benedictos benedicetur, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Ego ex ore Altissimi prodivi, primogenita ante omnem creaturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Ego feci in cælis ut oriretur lumen indeficiens, et sicut nebula texi omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Ego in altissimis habitavi, et thronus meus in columna nubis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Gyrum cæli circuivi sola, et profundum abyssi penetravi: in fluctibus maris ambulavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Et in omni terra steti: et in omni populo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'et in omni gente primatum habui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'et omnium excellentium et humilium corda virtute calcavi. Et in his omnibus requiem quæsivi, et in hæreditate Domini morabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Tunc præcepit, et dixit mihi Creator omnium: et qui creavit me, requievit in tabernaculo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Et dixit mihi: In Jacob inhabita, et in Israël hæreditare, et in electis meis mitte radices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ab initio et ante sæcula creata sum, et usque ad futurum sæculum non desinam: et in habitatione sancta coram ipso ministravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Et sic in Sion firmata sum, et in civitate sanctificata similiter requievi, et in Jerusalem potestas mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Et radicavi in populo honorificato, et in parte Dei mei hæreditas illius, et in plenitudine sanctorum detentio mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Quasi cedrus exaltata sum in Libano, et quasi cypressus in monte Sion:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'quasi palma exaltata sum in Cades, et quasi plantatio rosæ in Jericho:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'quasi oliva speciosa in campis, et quasi platanus exaltata sum juxta aquam in plateis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Sicut cinnamomum et balsamum aromatizans odorem dedi; quasi myrrha electa dedi suavitatem odoris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'et quasi storax, et galbanus, et ungula, et gutta, et quasi Libanus non incisus vaporavi habitationem meam, et quasi balsamum non mistum odor meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Ego quasi terebinthus extendi ramos meos, et rami mei honoris et gratiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Ego quasi vitis fructificavi suavitatem odoris: et flores mei fructus honoris et honestatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Ego mater pulchræ dilectionis, et timoris, et agnitionis, et sanctæ spei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'In me gratia omnis viæ et veritatis: in me omnis spes vitæ et virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Transite ad me, omnes qui concupiscitis me, et a generationibus meis implemini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'spiritus enim meus super mel dulcis, et hæreditas mea super mel et favum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 28, 'Memoria mea in generationes sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 29, 'Qui edunt me, adhuc esurient, et qui bibunt me, adhuc sitient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 30, 'Qui audit me non confundetur, et qui operantur in me non peccabunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 31, 'qui elucidant me, vitam æternam habebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 32, 'Hæc omnia liber vitæ, et testamentum Altissimi, et agnitio veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 33, 'Legem mandavit Moyses in præceptis justitiarum, et hæreditatem domui Jacob, et Israël promissiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 34, 'Posuit David, puero suo, excitare regem ex ipso fortissimum, et in throno honoris sedentem in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 35, 'Qui implet quasi Phison sapientiam, et sicut Tigris in diebus novorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 36, 'qui adimplet quasi Euphrates sensum, qui multiplicat quasi Jordanis in tempore messis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 37, 'qui mittit disciplinam sicut lucem, et assistens quasi Gehon in die vindemiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 38, 'Qui perficit primus scire ipsam, et infirmior non investigabit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 39, 'A mari enim abundavit cogitatio ejus, et consilium illius ab abysso magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 40, 'Ego sapientia effudi flumina:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 41, 'ego quasi trames aquæ immensæ de fluvio: ego quasi fluvii dioryx, et sicut aquæductus exivi de paradiso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 42, 'Dixi: Rigabo hortum meum plantationum, et inebriabo prati mei fructum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 43, 'Et ecce factus est mihi trames abundans, et fluvius meus appropinquavit ad mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 44, 'quoniam doctrinam quasi antelucanum illumino omnibus, et enarrabo illam usque ad longinquum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 45, 'Penetrabo omnes inferiores partes terræ, et inspiciam omnes dormientes, et illuminabo omnes sperantes in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 46, 'Adhuc doctrinam quasi prophetiam effundam, et relinquam illam quærentibus sapientiam, et non desinam in progenies illorum usque in ævum sanctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 47, 'Videte quoniam non soli mihi laboravi, sed omnibus exquirentibus veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'In tribus placitum est spiritui meo, quæ sunt probata coram Deo et hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'concordia fratrum, et amor proximorum, et vir et mulier bene sibi consentientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Tres species odivit anima mea, et aggravor valde animæ illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'pauperem superbum, divitem mendacem, senem fatuum et insensatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Quæ in juventute tua non congregasti, quomodo in senectute tua invenies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Quam speciosum canitiei judicium, et presbyteris cognoscere consilium!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Quam speciosa veteranis sapientia, et gloriosus intellectus et consilium!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Corona senum multa peritia, et gloria illorum timor Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Novem insuspicabilia cordis magnificavi: et decimum dicam in lingua hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'homo qui jucundatur in filiis, vivens et videns subversionem inimicorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Beatus qui habitat cum muliere sensata, et qui lingua sua non est lapsus, et qui non servivit indignis se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Beatus qui invenit amicum verum, et qui enarrat justitiam auri audienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Quam magnus qui invenit sapientiam et scientiam! sed non est super timentem Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Timor Dei super omnia se superposuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Beatus homo cui donatum est habere timorem Dei: qui tenet illum, cui assimilabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Timor Dei initium dilectionis ejus: fidei autem initium agglutinandum est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Omnis plaga tristitia cordis est, et omnis malitia nequitia mulieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 18, 'Et omnem plagam, et non plagam videbit cordis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 19, 'et omnem nequitiam, et non nequitiam mulieris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 20, 'et omnem obductum, et non obductum odientium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 21, 'et omnem vindictam, et non vindictam inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 22, 'Non est caput nequius super caput colubri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 23, 'et non est ira super iram mulieris. Commorari leoni et draconi placebit, quam habitare cum muliere nequam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 24, 'Nequitia mulieris immutat faciem ejus: et obcæcat vultum suum tamquam ursus, et quasi saccum ostendit. In medio proximorum ejus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 25, 'ingemuit vir ejus, et audiens suspiravit modicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 26, 'Brevis omnis malitia super malitiam mulieris: sors peccatorum cadat super illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 27, 'Sicut ascensus arenosus in pedibus veterani, sic mulier linguata homini quieto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 28, 'Ne respicias in mulieris speciem, et non concupiscas mulierem in specie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 29, 'Mulieris ira, et irreverentia, et confusio magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 30, 'Mulier si primatum habeat, contraria est viro suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 31, 'Cor humile, et facies tristis, et plaga cordis, mulier nequam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 32, 'Manus debiles et genua dissoluta, mulier quæ non beatificat virum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 33, 'A muliere initium factum est peccati, et per illam omnes morimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 34, 'Non des aquæ tuæ exitum, nec modicum: nec mulieri nequam veniam prodeundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 35, 'Si non ambulaverit ad manum tuam, confundet te in conspectu inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 36, 'A carnibus tuis abscinde illam, ne semper te abutatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Mulieris bonæ beatus vir: numerus enim annorum illius duplex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Mulier fortis oblectat virum suum, et annos vitæ illius in pace implebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Pars bona mulier bona, in parte timentium Deum dabitur viro pro factis bonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'divitis autem et pauperis cor bonum, in omni tempore vultus illorum hilaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'A tribus timuit cor meum, et in quarto facies mea metuit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'delaturam civitatis, et collectionem populi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'calumniam mendacem super mortem omnia gravia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'dolor cordis et luctus, mulier zelotypa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'In muliere zelotypa flagellum linguæ, omnibus communicans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Sicut boum jugum quod movetur, ita et mulier nequam: qui tenet illam quasi qui apprehendit scorpionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Mulier ebriosa ira magna, et contumelia: et turpitudo illius non tegetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Fornicatio mulieris in extollentia oculorum, et in palpebris illius agnoscetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'In filia non avertente se, firma custodiam, ne inventa occasione utatur se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Ab omni irreverentia oculorum ejus cave, et ne mireris si te neglexerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Sicut viator sitiens ad fontem os aperiet, et ab omni aqua proxima bibet, et contra omnem palum sedebit, et contra omnem sagittam aperiet pharetram donec deficiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Gratia mulieris sedulæ delectabit virum suum, et ossa illius impinguabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Disciplina illius datum Dei est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Mulier sensata et tacita, non est immutatio eruditæ animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Gratia super gratiam mulier sancta et pudorata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Omnis autem ponderatio non est digna continentis animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Sicut sol oriens mundo in altissimis Dei, sic mulieris bonæ species in ornamentum domus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 22, 'Lucerna splendens super candelabrum sanctum, et species faciei super ætatem stabilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 23, 'Columnæ aureæ super bases argenteas, et pedes firmi super plantas stabilis mulieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 24, 'Fundamenta æterna supra petram solidam, et mandata Dei in corde mulieris sanctæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 25, 'In duobus contristatum est cor meum, et in tertio iracundia mihi advenit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 26, 'vir bellator deficiens per inopiam; et vir sensatus contemptus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 27, 'et qui transgreditur a justitia ad peccatum: Deus paravit eum ad rhomphæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 28, 'Duæ species difficiles et periculosæ mihi apparuerunt: difficile exuitur negotians a negligentia, et non justificabitur caupo a peccatis labiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Propter inopiam multi deliquerunt: et qui quærit locupletari avertit oculum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Sicut in medio compaginis lapidum palus figitur, sic et inter medium venditionis et emptionis angustiabitur peccatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'conteretur cum delinquente delictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Si non in timore Domini tenueris te instanter, cito subvertetur domus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Sicut in percussura cribri remanebit pulvis, sic aporia hominis in cogitatu illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Vasa figuli probat fornax, et homines justos tentatio tribulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Sicut rusticatio de ligno ostendit fructum illius, sic verbum ex cogitatu cordis hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Ante sermonem non laudes virum: hæc enim tentatio est hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Si sequaris justitiam, apprehendes illam, et indues quasi poderem honoris: et inhabitabis cum ea, et proteget te in sempiternum, et in die agnitionis invenies firmamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Volatilia ad sibi similia conveniunt: et veritas ad eos qui operantur illam revertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Leo venationi insidiatur semper: sic peccata operantibus iniquitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Homo sanctus in sapientia manet sicut sol: nam stultus sicut luna mutatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'In medio insensatorum serva verbum tempori: in medio autem cogitantium assiduus esto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Narratio peccantium odiosa, et risus illorum in deliciis peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Loquela multum jurans horripilationem capiti statuet, et irreverentia ipsius obturatio aurium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Effusio sanguinis in rixa superborum, et maledictio illorum auditus gravis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Qui denudat arcana amici fidem perdit, et non inveniet amicum ad animum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Dilige proximum, et conjungere fide cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Quod si denudaveris absconsa illius, non persequeris post eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Sicut enim homo qui perdit amicum suum, sic et qui perdit amicitiam proximi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Et sicut qui dimittit avem de manu sua, sic dereliquisti proximum tuum, et non eum capies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Non illum sequaris, quoniam longe abest: effugit enim quasi caprea de laqueo, quoniam vulnerata est anima ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'ultra eum non poteris colligare. Et maledicti est concordatio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'denudare autem amici mysteria, desperatio est animæ infelicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Annuens oculo fabricat iniqua, et nemo eum abjiciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'In conspectu oculorum tuorum condulcabit os suum, et super sermones tuos admirabitur: novissime autem pervertet os suum, et in verbis tuis dabit scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Multa odivi, et non coæquavi ei, et Dominus odiet illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Qui in altum mittit lapidem, super caput ejus cadet: et plaga dolosa dolosi dividet vulnera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Et qui foveam fodit incidet in eam: et qui statuit lapidem proximo offendet in eo: et qui laqueum alii ponit, peribit in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Facienti nequissimum consilium, super ipsum devolvetur, et non agnoscet unde adveniat illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Illusio et improperium superborum, et vindicta sicut leo insidiabitur illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Laqueo peribunt qui oblectantur casu justorum, dolor autem consumet illos antequam moriantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Ira et furor utraque execrabilia sunt, et vir peccator continens erit illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Qui vindicari vult, a Domino inveniet vindictam, et peccata illius servans servabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Relinque proximo tuo nocenti te, et tunc deprecanti tibi peccata solventur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Homo homini reservat iram, et a Deo quærit medelam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'in hominem similem sibi non habet misericordiam, et de peccatis suis deprecatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Ipse cum caro sit reservat iram, et propitiationem petit a Deo: quis exorabit pro delictis illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Memento novissimorum, et desine inimicari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'tabitudo enim et mors imminent in mandatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Memorare timorem Dei, et non irascaris proximo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Memorare testamentum Altissimi, et despice ignorantiam proximi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Abstine te a lite, et minues peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Homo enim iracundus incendit litem, et vir peccator turbabit amicos, et in medio pacem habentium immittet inimicitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Secundum enim ligna silvæ sic ignis exardescit: et secundum virtutem hominis sic iracundia illius erit, et secundum substantiam suam exaltabit iram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Certamen festinatum incendit ignem, et lis festinans effundit sanguinem: et lingua testificans adducit mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Si sufflaveris in scintillam, quasi ignis exardebit: et si exspueris super illam, extinguetur: utraque ex ore proficiscuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Susurro et bilinguis maledictus, multos enim turbabit pacem habentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Lingua tertia multos commovit, et dispersit illos de gente in gentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Civitates muratas divitum destruxit, et domus magnatorum effodit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Virtutes populorum concidit, et gentes fortes dissolvit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Lingua tertia mulieres viratas ejecit, et privavit illas laboribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Qui respicit illam non habebit requiem, nec habebit amicum in quo requiescat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Flagelli plaga livorem facit: plaga autem linguæ comminuet ossa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Multi ceciderunt in ore gladii: sed non sic quasi qui interierunt per linguam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Beatus qui tectus est a lingua nequam, qui in iracundiam illius non transivit, et qui non attraxit jugum illius, et in vinculis ejus non est ligatus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'jugum enim illius jugum ferreum est, et vinculum illius vinculum æreum est;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'mors illius mors nequissima: et utilis potius infernus quam illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Perseverantia illius non permanebit, sed obtinebit vias injustorum, et in flamma sua non comburet justos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 27, 'Qui relinquunt Deum incident in illam, et exardebit in illis, et non extinguetur, et immittetur in illos quasi leo, et quasi pardus lædet illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 28, 'Sepi aures tuas spinis: linguam nequam noli audire: et ori tuo facito ostia et seras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 29, 'Aurum tuum et argentum tuum confla, et verbis tuis facito stateram, et frenos ori tuo rectos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 30, 'et attende ne forte labaris in lingua, et cadas in conspectu inimicorum insidiantium tibi, et sit casus tuus insanabilis in mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Qui facit misericordiam fœneratur proximo suo: et qui prævalet manu mandata servat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Fœnerare proximo tuo in tempore necessitatis illius: et iterum redde proximo in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Confirma verbum, et fideliter age cum illo: et in omni tempore invenies quod tibi necessarium est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Multi quasi inventionem æstimaverunt fœnus, et præstiterunt molestiam his qui se adjuverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Donec accipiant, osculantur manus dantis, et in promissionibus humiliant vocem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'et in tempore redditionis postulabit tempus, et loquetur verba tædii et murmurationum, et tempus causabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Si autem potuerit reddere, adversabitur: solidi vix reddet dimidium, et computabit illud quasi inventionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'sin autem, fraudabit illum pecunia sua, et possidebit illum inimicum gratis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'et convitia et maledicta reddet illi, et pro honore et beneficio reddet illi contumeliam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Multi non causa nequitiæ non fœnerati sunt, sed fraudari gratis timuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Verumtamen super humilem animo fortior esto, et pro eleemosyna non trahas illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Propter mandatum assume pauperem, et propter inopiam ejus ne dimittas eum vacuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Perde pecuniam propter fratrem et amicum tuum, et non abscondas illam sub lapide in perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Pone thesaurum tuum in præceptis Altissimi, et proderit tibi magis quam aurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Conclude eleemosynam in corde pauperis, et hæc pro te exorabit ab omni malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Super scutum potentis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'et super lanceam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'adversus inimicum tuum pugnabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Vir bonus fidem facit pro proximo suo: et qui perdiderit confusionem derelinquet sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Gratiam fidejussoris ne obliviscaris: dedit enim pro te animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Repromissorem fugit peccator et immundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 22, 'Bona repromissoris sibi ascribit peccator: et ingratus sensu derelinquet liberantem se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 23, 'Vir repromittit de proximo suo: et cum perdiderit reverentiam, derelinquetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 24, 'Repromissio nequissima multos perdidit dirigentes, et commovit illos quasi fluctus maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 25, 'Viros potentes gyrans migrare fecit, et vagati sunt in gentibus alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 26, 'Peccator transgrediens mandatum Domini incidet in promissionem nequam: et qui conatur multa agere incidet in judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 27, 'Recupera proximum secundum virtutem tuam, et attende tibi ne incidas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 28, 'Initium vitæ hominis, aqua et panis, et vestimentum, et domus protegens turpitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 29, 'Melior est victus pauperis sub tegmine asserum quam epulæ splendidæ in peregre sine domicilio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 30, 'Minimum pro magno placeat tibi, et improperium peregrinationis non audies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 31, 'Vita nequam hospitandi de domo in domum: et ubi hospitabitur non fiducialiter aget, nec aperiet os.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 32, 'Hospitabitur, et pascet, et potabit ingratos, et ad hæc amara audiet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 33, 'transi, hospes, et orna mensam, et quæ in manu habes ciba ceteros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 34, 'Exi a facie honoris amicorum meorum: necessitudine domus meæ hospitio mihi factus est frater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 35, 'Gravia hæc homini habenti sensum: correptio domus, et improperium fœneratoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Qui diligit filium suum assiduat illi flagella, ut lætetur in novissimo suo, et non palpet proximorum ostia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Qui docet filium suum laudabitur in illo, et in medio domesticorum in illo gloriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Qui docet filium suum in zelum mittit inimicum, et in medio amicorum gloriabitur in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Mortuus est pater ejus, et quasi non est mortuus: similem enim reliquit sibi post se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'In vita sua vidit, et lætatus est in illo: in obitu suo non est contristatus, nec confusus est coram inimicis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'reliquit enim defensorem domus contra inimicos, et amicis reddentem gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Pro animabus filiorum colligabit vulnera sua, et super omnem vocem turbabuntur viscera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Equus indomitus evadit durus, et filius remissus evadet præceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Lacta filium, et paventem te faciet: lude cum eo, et contristabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Non corrideas illi, ne doleas, et in novissimo obstupescent dentes tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Non des illi potestatem in juventute, et ne despicias cogitatus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Curva cervicem ejus in juventute, et tunde latera ejus dum infans est, ne forte induret, et non credat tibi, et erit tibi dolor animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Doce filium tuum, et operare in illo, ne in turpitudinem illius offendas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Melior est pauper sanus, et fortis viribus, quam dives imbecillis et flagellatus malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Salus animæ in sanctitate justitiæ melior est omni auro et argento: et corpus validum quam census immensus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Non est census super censum salutis corporis, et non est oblectamentum super cordis gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Melior est mors quam vita amara, et requies æterna quam languor perseverans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Bona abscondita in ore clauso, quasi appositiones epularum circumpositæ sepulchro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Quid proderit libatio idolo? nec enim manducabit, nec odorabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Sic qui effugatur a Domino, portans mercedes iniquitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'videns oculis et ingemiscens, sicut spado complectens virginem, et suspirans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Tristitiam non des animæ tuæ, et non affligas temetipsum in consilio tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Jucunditas cordis, hæc est vita hominis, et thesaurus sine defectione sanctitatis: et exsultatio viri est longævitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Miserere animæ tuæ placens Deo, et contine: congrega cor tuum in sanctitate ejus, et tristitiam longe repelle a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Multos enim occidit tristitia, et non est utilitas in illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Zelus et iracundia minuunt dies, et ante tempus senectam adducet cogitatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 27, 'Splendidum cor et bonum in epulis est: epulæ enim illius diligenter fiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Vigilia honestatis tabefaciet carnes, et cogitatus illius auferet somnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Cogitatus præscientiæ avertit sensum, et infirmitas gravis sobriam facit animam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Laboravit dives in congregatione substantiæ, et in requie sua replebitur bonis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Laboravit pauper in diminutione victus, et in fine inops fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Qui aurum diligit non justificabitur, et qui insequitur consumptionem replebitur ex ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Multi dati sunt in auri casus, et facta est in specie ipsius perditio illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Lignum offensionis est aurum sacrificantium: væ illis qui sectantur illud! et omnis imprudens deperiet in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Beatus dives qui inventus est sine macula, et qui post aurum non abiit, nec speravit in pecunia et thesauris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Quis est hic? et laudabimus eum: fecit enim mirabilia in vita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Qui probatus est in illo, et perfectus est, erit illi gloria æterna: qui potuit transgredi, et non est transgressus; facere mala, et non fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Ideo stabilita sunt bona illius in Domino, et eleemosynas illius enarrabit omnis ecclesia sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Supra mensam magnam sedisti? non aperias super illam faucem tuam prior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Non dicas sic: Multa sunt, quæ super illam sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Memento quoniam malus est oculus nequam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Nequius oculo quid creatum est? ideo ab omni facie sua lacrimabitur, cum viderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Ne extendas manum tuam prior, et invidia contaminatus erubescas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Ne comprimaris in convivio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Intellige quæ sunt proximi tui ex teipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 19, 'Utere quasi homo frugi his quæ tibi apponuntur: ne, cum manducas multum, odio habearis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 20, 'Cessa prior causa disciplinæ: et noli nimius esse, ne forte offendas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 21, 'Et si in medio multorum sedisti, prior illis ne extendas manum tuam, nec prior poscas bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 22, 'Quam sufficiens est homini erudito vinum exiguum! et in dormiendo non laborabis ab illo, et non senties dolorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 23, 'Vigilia, cholera et tortura viro infrunito,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 24, 'somnus sanitatis in homine parco: dormiet usque mane, et anima illius cum ipso delectabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 25, 'Et si coactus fueris in edendo multum, surge e medio, evome, et refrigerabit te, et non adduces corpori tuo infirmitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 26, 'Audi me, fili, et ne spernas me, et in novissimo invenies verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 27, 'In omnibus operibus tuis esto velox, et omnis infirmitas non occurret tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 28, 'Splendidum in panibus benedicent labia multorum, et testimonium veritatis illius fidele.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 29, 'Nequissimo in pane murmurabit civitas, et testimonium nequitiæ illius verum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 30, 'Diligentes in vino noli provocare: multos enim exterminavit vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 31, 'Ignis probat ferrum durum: sic vinum corda superborum arguet in ebrietate potatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 32, '\'qua vita hominibus vinum in sobrietate: si bibas illud moderate, eris sobrius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 33, 'Quæ vita est ei qui minuitur vino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 34, 'Quid defraudat vitam? mors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 35, 'Vinum in jucunditatem creatum est, et non in ebrietatem ab initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 36, 'Exsultatio animæ et cordis vinum moderate potatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 37, 'Sanitas est animæ et corpori sobrius potus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 38, 'Vinum multum potatum irritationem, et iram, et ruinas multas facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 39, 'Amaritudo animæ vinum multum potatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 40, 'Ebrietatis animositas, imprudentis offensio, minorans virtutem, et faciens vulnera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 41, 'In convivio vini non arguas proximum, et non despicias eum in jucunditate illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 42, 'Verba improperii non dicas illi, et non premas illum repetendo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Rectorem te posuerunt? noli extolli: esto in illis quasi unus ex ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Curam illorum habe, et sic conside, et omni cura tua explicita recumbe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'ut læteris propter illos, et ornamentum gratiæ accipias coronam, et dignationem consequaris corrogationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Loquere major natu: decet enim te');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'primum verbum diligenti scientia, et non impedias musicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Ubi auditus non est, non effundas sermonem, et importune noli extolli in sapientia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Gemmula carbunculi in ornamento auri, et comparatio musicorum in convivio vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Sicut in fabricatione auri signum est smaragdi, sic numerus musicorum in jucundo et moderato vino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Audi tacens, et pro reverentia accedet tibi bona gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Adolescens, loquere in tua causa vix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Si bis interrogatus fueris, habeat caput responsum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'In multis esto quasi inscius, et audi tacens simul et quærens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'In medio magnatorum non præsumas: et ubi sunt senes non multum loquaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Ante grandinem præibit coruscatio: et ante verecundiam præibit gratia, et pro reverentia accedet tibi bona gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Et hora surgendi non te trices: præcurre autem prior in domum tuam, et illic avocare, et illic lude,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'et age conceptiones tuas, et non in delictis et verbo superbo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'et super his omnibus benedicito Dominum, qui fecit, et inebriantem te ab omnibus bonis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Qui timet Dominum excipiet doctrinam ejus: et qui vigilaverint ad illum invenient benedictionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Qui quærit legem replebitur ab ea, et qui insidiose agit scandalizabitur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Qui timent Dominum invenient judicium justum, et justitias quasi lumen accendent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Peccator homo vitabit correptionem, et secundum voluntatem suam inveniet comparationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Vir consilii non disperdet intelligentiam: alienus et superbus non pertimescet timorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'etiam postquam fecit cum eo sine consilio, et suis insectationibus arguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Fili, sine consilio nihil facias, et post factum non pœnitebis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'In via ruinæ non eas, et non offendes in lapides: nec credas te viæ laboriosæ, ne ponas animæ tuæ scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Et a filiis tuis cave, et a domesticis tuis attende.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'In omni opere tuo crede ex fide animæ tuæ, hoc est enim conservatio mandatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Qui credit Deo attendit mandatis: et qui confidit in illo non minorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Timenti Dominum non occurrent mala: sed in tentatione Deus illum conservabit, et liberabit a malis. Sapiens non odit mandata et justitias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'et non illidetur quasi in procella navis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Homo sensatus credit legi Dei, et lex illi fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Qui interrogationem manifestat parabit verbum, et sic deprecatus exaudietur: et conservabit disciplinam, et tunc respondebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Præcordia fatui quasi rota carri, et quasi axis versatilis cogitatus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Equus emissarius, sic et amicus subsannator: sub omni supra sedente hinnit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Quare dies diem superat, et iterum lux lucem, et annus annum a sole?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'A Domini scientia separati sunt, facto sole, et præceptum custodiente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Et immutavit tempora, et dies festos ipsorum, et in illis dies festos celebraverunt ad horam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Ex ipsis exaltavit et magnificavit Deus, et ex ipsis posuit in numerum dierum: et omnes homines de solo et ex terra unde creatus est Adam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'In multitudine disciplinæ Dominus separavit eos, et immutavit vias eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ex ipsis benedixit et exaltavit, et ex ipsis sanctificavit, et ad se applicavit, et ex ipsis maledixit, et humiliavit, et convertit illos a separatione ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Quasi lutum figuli in manu ipsius, plasmare illud et disponere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Omnes viæ ejus secundum dispositionem ejus: sic homo in manu illius qui se fecit, et reddet illi secundum judicium suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Contra malum bonum est, et contra mortem vita: sic et contra virum justum peccator, et sic intuere in omnia opera Altissimi, duo et duo, et unum contra unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Et ego novissimus evigilavi, et quasi qui colligit acinos post vindemiatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'In benedictione Dei et ipse speravi, et quasi qui vindemiat replevi torcular.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Respicite quoniam non mihi soli laboravi, sed omnibus exquirentibus disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Audite me, magnates et omnes populi: et rectores ecclesiæ, auribus percipite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Filio et mulieri, fratri et amico, non des potestatem super te in vita tua: et non dederis alii possessionem tuam, ne forte pœniteat te, et depreceris pro illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Dum adhuc superes et aspiras, non immutabit te omnis caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Melius est enim ut filii tui te rogent, quam te respicere in manus filiorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'In omnibus operibus tuis præcellens esto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Ne dederis maculam in gloria tua. In die consummationis dierum vitæ tuæ, et in tempore exitus tui, distribue hæreditatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Cibaria, et virga, et onus asino: panis, et disciplina, et opus servo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Operatur in disciplina, et quærit requiescere: laxa manus illi, et quærit libertatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Jugum et lorum curvant collum durum, et servum inclinant operationes assiduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Servo malevolo tortura et compedes: mitte illum in operationem, ne vacet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'multam enim malitiam docuit otiositas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'In opera constitue eum: sic enim condecet illum. Quod si non obaudierit, curva illum compedibus, et non amplifices super omnem carnem: verum sine judicio nihil facias grave.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Si est tibi servus fidelis, sit tibi quasi anima tua: quasi fratrem sic eum tracta, quoniam in sanguine animæ comparasti illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Si læseris eum injuste, in fugam convertetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'et si extollens discesserit, quem quæras et in qua via quæras illum nescis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Vana spes et mendacium viro insensato: et somnia extollunt imprudentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Quasi qui apprehendit umbram et persequitur ventum, sic et qui attendit ad visa mendacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Hoc secundum hoc visio somniorum, ante faciem hominis similitudo hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Ab immundo, quid mundabitur? et a mendace, quid verum dicetur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Divinatio erroris, et auguria mendacia, et somnia malefacientium, vanitas est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'et sicut parturientis, cor tuum phantasias patitur. Nisi ab Altissimo fuerit emissa visitatio, ne dederis in illis cor tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'multos enim errare fecerunt somnia, et exciderunt sperantes in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Sine mendacio consummabitur verbum legis, et sapientia in ore fidelis complanabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Qui non est tentatus quid scit? vir in multis expertus cogitabit multa: et qui multa didicit enarrabit intellectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Qui non est expertus pauca recognoscit: qui autem in multis factus est, multiplicat malitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Qui tentatus non est qualia scit? qui implanatus est abundabit nequitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Multa vidi errando, et plurimas verborum consuetudines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Aliquoties usque ad mortem periclitatus sum horum causa, et liberatus sum gratia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Spiritus timentium Deum quæritur, et in respectu illius benedicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Spes enim illorum in salvantem illos, et oculi Dei in diligentes se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Qui timet Dominum nihil trepidabit: et non pavebit, quoniam ipse est spes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Timentis Dominum, beata est anima ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ad quem respicit, et quis est fortitudo ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Oculi Domini super timentes eum: protector potentiæ, firmamentum virtutis, tegimen ardoris, et umbraculum meridiani:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'deprecatio offensionis, et adjutorium casus: exaltans animam, et illuminans oculos, dans sanitatem, et vitam, et benedictionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Immolantis ex iniquo oblatio est maculata, et non sunt beneplacitæ subsannationes injustorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Dominus solus sustinentibus se in via veritatis et justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Dona iniquorum non probat Altissimus, nec respicit in oblationes iniquorum, nec in multitudine sacrificiorum eorum propitiabitur peccatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Qui offert sacrificium ex substantia pauperum, quasi qui victimat filium in conspectu patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Panis egentium vita pauperum est: qui defraudat illum homo sanguinis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Qui aufert in sudore panem, quasi qui occidit proximum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Qui effundit sanguinem, et qui fraudem facit mercenario, fratres sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Unus ædificans, et unus destruens: quid prodest illis, nisi labor?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Unus orans, et unus maledicens: cujus vocem exaudiet Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Qui baptizatur a mortuo, et iterum tangit eum, quid proficit lavatio illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Sic homo qui jejunat in peccatis suis, et iterum eadem faciens: quid proficit humiliando se? orationem illius quis exaudiet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Qui conservat legem multiplicat oblationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Sacrificium salutare est attendere mandatis, et discedere ab omni iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Et propitiationem litare sacrificii super injustitias: et deprecatio pro peccatis, recedere ab injustitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Retribuet gratiam qui offert similaginem: et qui facit misericordiam offert sacrificium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Beneplacitum est Domino recedere ab iniquitate: et deprecatio pro peccatis recedere ab injustitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Non apparebis ante conspectum Domini vacuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'hæc enim omnia propter mandatum Dei fiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Oblatio justi impinguat altare, et odor suavitatis est in conspectu Altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Sacrificium justi acceptum est, et memoriam ejus non obliviscetur Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Bono animo gloriam redde Deo, et non minuas primitias manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'In omni dato hilarem fac vultum tuum, et in exsultatione sanctifica decimas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Da Altissimo secundum datum ejus, et in bono oculo adinventionem facito manuum tuarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'quoniam Dominus retribuens est, et septies tantum reddet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Noli offerre munera prava, non enim suscipiet illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Et noli inspicere sacrificum injustum, quoniam Dominus judex est, et non est apud illum gloria personæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 16, 'Non accipiet Dominus personam in pauperem, et deprecationem læsi exaudiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 17, 'Non despiciet preces pupilli, nec viduam, si effundat loquelam gemitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 18, 'Nonne lacrimæ viduæ ad maxillam descendunt, et exclamatio ejus super deducentem eas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 19, 'A maxilla enim ascendunt usque ad cælum, et Dominus exauditor non delectabitur in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 20, 'Qui adorat Deum in oblectatione suscipietur, et deprecatio illius usque ad nubes propinquabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 21, 'Oratio humiliantis se nubes penetrabit, et donec propinquet non consolabitur, et non discedet donec Altissimus aspiciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 22, 'Et Dominus non elongabit: et judicabit justos, et faciet judicium: et Fortissimus non habebit in illis patientiam, ut contribulet dorsum ipsorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 23, 'et gentibus reddet vindictam, donec tollat plenitudinem superborum, et sceptra iniquorum contribulet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 24, 'donec reddat hominibus secundum actus suos, et secundum opera Adæ, et secundum præsumptionem illius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 25, 'donec judicet judicium plebis suæ, et oblectabit justos misericordia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 26, 'Speciosa misericordia Dei in tempore tribulationis, quasi nubes pluviæ in tempore siccitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Miserere nostri, Deus omnium, et respice nos, et ostende nobis lucem miserationum tuarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'et immitte timorem tuum super gentes quæ non exquisierunt te, ut cognoscant quia non est deus nisi tu, et enarrent magnalia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Alleva manum tuam super gentes alienas, ut videant potentiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Sicut enim in conspectu eorum sanctificatus es in nobis, sic in conspectu nostro magnificaberis in eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'ut cognoscant te, sicut et nos cognovimus quoniam non est deus præter te, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Innova signa, et immuta mirabilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Glorifica manum et brachium dextrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Excita furorem, et effunde iram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Tolle adversarium, et afflige inimicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Festina tempus, et memento finis, ut enarrent mirabilia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'In ira flammæ devoretur qui salvatur: et qui pessimant plebem tuam inveniant perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Contere caput principum inimicorum, dicentium: Non est alius præter nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Congrega omnes tribus Jacob, ut cognoscant quia non est deus nisi tu, et enarrent magnalia tua, et hæreditabis eos sicut ab initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Miserere plebi tuæ, super quam invocatum est nomen tuum, et Israël quem coæquasti primogenito tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Miserere civitati sanctificationis tuæ, Jerusalem, civitati requiei tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Reple Sion inenarrabilibus verbis tuis, et gloria tua populum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Da testimonium his qui ab initio creaturæ tuæ sunt, et suscita prædicationes quas locuti sunt in nomine tuo prophetæ priores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Da mercedem sustinentibus te, ut prophetæ tui fideles inveniantur: et exaudi orationes servorum tuorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'secundum benedictionem Aaron de populo tuo: et dirige nos in viam justitiæ, et sciant omnes qui habitant terram quia tu es Deus conspector sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Omnem escam manducabit venter: et est cibus cibo melior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Fauces contingunt cibum feræ, et cor sensatum verba mendacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Cor pravum dabit tristitiam, et homo peritus resistet illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Omnem masculum excipiet mulier: et est filia melior filia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Species mulieris exhilarat faciem viri sui, et super omnem concupiscentiam hominis superducit desiderium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Si est lingua curationis, est et mitigationis et misericordiæ: non est vir illius secundum filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Qui possidet mulierem bonam inchoat possessionem: adjutorium secundum illum est, et columna ut requies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ubi non est sepes, diripietur possessio: et ubi non est mulier, ingemiscit egens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Quis credit ei qui non habet nidum, et deflectens ubicumque obscuraverit, quasi succinctus latro exiliens de civitate in civitatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Omnis amicus dicet: Et ego amicitiam copulavi: sed est amicus solo nomine amicus. Nonne tristitia inest usque ad mortem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'sodalis autem et amicus ad inimicitiam convertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'O præsumptio nequissima, unde creata es cooperire aridam malitia et dolositate illius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Sodalis amico conjucundatur in oblectationibus, et in tempore tribulationis adversarius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Sodalis amico condolet causa ventris, et contra hostem accipiet scutum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Non obliviscaris amici tui in animo tuo, et non immemor sis illius in opibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Noli consiliari cum eo qui tibi insidiatur, et a zelantibus te absconde consilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Omnis consiliarius prodit consilium, sed est consiliarius in semetipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'A consiliario serva animam tuam: prius scito quæ sit illius necessitas: et ipse enim animo suo cogitabit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'ne forte mittat sudem in terram, et dicat tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Bona est via tua: et stet e contrario videre quid tibi eveniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Cum viro irreligioso tracta de sanctitate, et cum injusto de justitia, et cum muliere de ea quæ æmulatur, cum timido de bello, cum negotiatore de trajectione, cum emptore de venditione, cum viro livido de gratiis agendis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'cum impio de pietate, cum inhonesto de honestate, cum operario agrario de omni opere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'cum operario annuali de consummatione anni, cum servo pigro de multa operatione. Non attendas his in omni consilio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'sed cum viro sancto assiduus esto, quemcumque cognoveris observantem timorem Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'cujus anima est secundum animam tuam, et qui, cum titubaveris in tenebris, condolebit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Cor boni consilii statue tecum: non est enim tibi aliud pluris illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Anima viri sancti enuntiat aliquando vera, quam septem circumspectores sedentes in excelso ad speculandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Et in his omnibus deprecare Altissimum, ut dirigat in veritate viam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Ante omnia opera verbum verax præcedat te, et ante omnem actum consilium stabile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Verbum nequam immutabit cor: ex quo partes quatuor oriuntur: bonum et malum, vita et mors: et dominatrix illorum est assidua lingua. Est vir astutus multorum eruditor, et animæ suæ inutilis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Vir peritus multos erudivit, et animæ suæ suavis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Qui sophistice loquitur odibilis est: in omni re defraudabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Non est illi data a Domino gratia, omni enim sapientia defraudatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Est sapiens animæ suæ sapiens, et fructus sensus illius laudabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Vir sapiens plebem suam erudit, et fructus sensus illius fideles sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Vir sapiens implebitur benedictionibus, et videntes illum laudabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Vita viri in numero dierum: dies autem Israël innumerabiles sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 29, 'Sapiens in populo hæreditabit honorem, et nomen illius erit vivens in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 30, 'Fili, in vita tua tenta animam tuam, et si fuerit nequam non des illi potestatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 31, 'non enim omnia omnibus expediunt, et non omni animæ omne genus placet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 32, 'Noli avidus esse in omni epulatione, et non te effundas super omnem escam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 33, 'in multis enim escis erit infirmitas, et aviditas appropinquabit usque ad choleram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 34, 'Propter crapulam multi obierunt: qui autem abstinens est adjiciet vitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Honora medicum propter necessitatem: etenim illum creavit Altissimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'A Deo est enim omnis medela, et a rege accipiet donationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Disciplina medici exaltabit caput illius, et in conspectu magnatorum collaudabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Altissimus creavit de terra medicamenta, et vir prudens non abhorrebit illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Nonne a ligno indulcata est aqua amara?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Ad agnitionem hominum virtus illorum: et dedit hominibus scientiam Altissimus, honorari in mirabilibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'In his curans mitigabit dolorem: et unguentarius faciet pigmenta suavitatis, et unctiones conficiet sanitatis: et non consummabuntur opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Pax enim Dei super faciem terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Fili, in tua infirmitate ne despicias teipsum: sed ora Dominum, et ipse curabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Averte a delicto, et dirige manus, et ab omni delicto munda cor tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Da suavitatem et memoriam similaginis, et impingua oblationem, et da locum medico:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'etenim illum Dominus creavit, et non discedat a te, quia opera ejus sunt necessaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Est enim tempus quando in manus illorum incurras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'ipsi vero Dominum deprecabuntur, ut dirigat requiem eorum, et sanitatem, propter conversationem illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Qui delinquit in conspectu ejus qui fecit eum, incidet in manus medici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Fili, in mortuum produc lacrimas, et quasi dira passus incipe plorare: et secundum judicium contege corpus illius, et non despicias sepulturam illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Propter delaturam autem amare fer luctum illius uno die, et consolare propter tristitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'et fac luctum secundum meritum ejus uno die, vel duobus, propter detractionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'a tristitia enim festinat mors, et cooperit virtutem, et tristitia cordis flectit cervicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'In abductione permanet tristitia, et substantia inopis secundum cor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Ne dederis in tristitia cor tuum, sed repelle eam a te, et memento novissimorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Noli oblivisci, neque enim est conversio: et huic nihil proderis, et teipsum pessimabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Memor esto judicii mei: sic enim erit et tuum: mihi heri, et tibi hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 24, 'In requie mortui requiescere fac memoriam ejus, et consolare illum in exitu spiritus sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 25, 'Sapientia scribæ in tempore vacuitatis, et qui minoratur actu sapientiam percipiet, qua sapientia replebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 26, 'Qui tenet aratrum, et qui gloriatur in jaculo, stimulo boves agitat, et conversatur in operibus eorum, et enarratio ejus in filiis taurorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 27, 'Cor suum dabit ad versandos sulcos, et vigilia ejus in sagina vaccarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 28, 'Sic omnis faber et architectus, qui noctem tamquam diem transigit: qui sculpit signacula sculptilia, et assiduitas ejus variat picturam: cor suum dabit in similitudinem picturæ, et vigilia sua perficiet opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 29, 'Sic faber ferrarius sedens juxta incudem, et considerans opus ferri: vapor ignis uret carnes ejus, et in calore fornacis concertatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 30, 'Vox mallei innovat aurem ejus, et contra similitudinem vasis oculus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 31, 'Cor suum dabit in consummationem operum, et vigilia sua ornabit in perfectionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 32, 'Sic figulus sedens ad opus suum, convertens pedibus suis rotam, qui in sollicitudine positus est semper propter opus suum, et in numero est omnis operatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 33, 'In brachio suo formabit lutum, et ante pedes suos curvabit virtutem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 34, 'Cor suum dabit ut consummet linitionem, et vigilia sua mundabit fornacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 35, 'Omnes hi in manibus suis speraverunt, et unusquisque in arte sua sapiens est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 36, 'Sine his omnibus non ædificatur civitas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 37, 'et non inhabitabunt, nec inambulabunt, et in ecclesiam non transilient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 38, 'Super sellam judicis non sedebunt, et testamentum judicii non intelligent, neque palam facient disciplinam et judicium, et in parabolis non invenientur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 39, 'sed creaturam ævi confirmabunt: et deprecatio illorum in operatione artis, accomodantes animam suam, et conquirentes in lege Altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Sapientiam omnium antiquorum exquiret sapiens, et in prophetis vacabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Narrationem virorum nominatorum conservabit, et in versutias parabolarum simul introibit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Occulta proverbiorum exquiret, et in absconditis parabolarum conversabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'In medio magnatorum ministrabit, et in conspectu præsidis apparebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'In terram alienigenarum gentium pertransiet: bona enim et mala in hominibus tentabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Cor suum tradet ad vigilandum diluculo ad Dominum, qui fecit illum, et in conspectu Altissimi deprecabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Aperiet os suum in oratione, et pro delictis suis deprecabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Si enim Dominus magnus voluerit, spiritu intelligentiæ replebit illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'et ipse tamquam imbres mittet eloquia sapientiæ suæ, et in oratione confitebitur Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'et ipse diriget consilium ejus, et disciplinam, et in absconditis suis consiliabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Ipse palam faciet disciplinam doctrinæ suæ, et in lege testamenti Domini gloriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Collaudabunt multi sapientiam ejus, et usque in sæculum non delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Non recedet memoria ejus, et nomen ejus requiretur a generatione in generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Sapientiam ejus enarrabunt gentes, et laudem ejus enuntiabit ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Si permanserit, nomen derelinquet plus quam mille: et si requieverit, proderit illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Adhuc consiliabor ut enarrem: ut furore enim repletus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'In voce dicit: Obaudite me, divini fructus, et quasi rosa plantata super rivos aquarum fructificate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Quasi Libanus odorem suavitatis habete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Florete flores quasi lilium: et date odorem, et frondete in gratiam: et collaudate canticum, et benedicite Dominum in operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Date nomini ejus magnificentiam, et confitemini illi in voce labiorum vestrorum, et in canticis labiorum, et citharis: et sic dicetis in confessione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Opera Domini universa bona valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'In verbo ejus stetit aqua sicut congeries: et in sermone oris illius sicut exceptoria aquarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'quoniam in præcepto ipsius placor fit, et non est minoratio in salute ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Opera omnis carnis coram illo, et non est quidquam absconditum ab oculis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'A sæculo usque in sæculum respicit, et nihil est mirabile in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Non est dicere: Quid est hoc, aut quid est istud? omnia enim in tempore suo quærentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Benedictio illius quasi fluvius inundavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Quomodo cataclysmus aridam inebriavit, sic ira ipsius gentes quæ non exquisierunt eum hæreditabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Quomodo convertit aquas in siccitatem, et siccata est terra, et viæ illius viis illorum directæ sunt, sic peccatoribus offensiones in ira ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 30, 'Bona bonis creata sunt ab initio: sic nequissimis bona et mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 31, 'Initium necessariæ rei vitæ hominum, aqua, ignis, et ferrum, sal, lac, et panis similagineus, et mel, et botrus uvæ, et oleum, et vestimentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 32, 'Hæc omnia sanctis in bona, sic et impiis et peccatoribus in mala convertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 33, 'Sunt spiritus qui ad vindictam creati sunt, et in furore suo confirmaverunt tormenta sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 34, 'In tempore consummationis effundent virtutem, et furorem ejus qui fecit illos placabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 35, 'Ignis, grando, fames, et mors, omnia hæc ad vindictam creata sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 36, 'bestiarum dentes, et scorpii, et serpentes, et rhomphæa vindicans in exterminium impios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 37, 'In mandatis ejus epulabuntur: et super terram in necessitatem præparabuntur, et in temporibus suis non præterient verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 38, 'Propterea ab initio confirmatus sum, et consiliatus sum, et cogitavi, et scripta dimisi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 39, 'Omnia opera Domini bona, et omne opus hora sua subministrabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 40, 'Non est dicere: Hoc illo nequius est: omnia enim in tempore suo comprobabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 41, 'Et nunc in omni corde et ore collaudate, et benedicite nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Occupatio magna creata est omnibus hominibus, et jugum grave super filios Adam, a die exitus de ventre matris eorum usque in diem sepulturæ in matrem omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Cogitationes eorum, et timores cordis, adinventio exspectationis, et dies finitionis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'a residente super sedem gloriosam, usque ad humiliatum in terra et cinere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'ab eo qui utitur hyacintho et portat coronam, usque ad eum qui operitur lino crudo: furor, zelus, tumultus, fluctuatio, et timor mortis, iracundia perseverans, et contentio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'et in tempore refectionis in cubili, somnus noctis immutat scientiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Modicum tamquam nihil in requie, et ab eo in somnis, quasi in die respectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Conturbatus est in visu cordis sui, tamquam qui evaserit in die belli: in tempore salutis suæ exsurrexit, et admirans ad nullum timorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'cum omni carne, ab homine usque ad pecus, et super peccatores septuplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Ad hæc mors, sanguis, contentio, et rhomphæa, oppressiones, fames, et contritio, et flagella:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'super iniquos creata sunt hæc omnia: et propter illos factus est cataclysmus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Omnia quæ de terra sunt in terram convertentur, et omnes aquæ in mare revertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Omne munus et iniquitas delebitur, et fides in sæculum stabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Substantiæ injustorum sicut fluvius siccabuntur, et sicut tonitruum magnum in pluvia personabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'In aperiendo manus suas lætabitur: sic prævaricatores in consummatione tabescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Nepotes impiorum non multiplicabunt ramos: et radices immundæ super cacumen petræ sonant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Super omnem aquam viriditas, et ad oram fluminis ante omne fœnum evelletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Gratia sicut paradisus in benedictionibus, et misericordia in sæculum permanet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Vita sibi sufficientis operarii condulcabitur, et in ea invenies thesaurum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Filii et ædificatio civitatis confirmabit nomen: et super hæc mulier immaculata computabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Vinum et musica lætificant cor: et super utraque dilectio sapientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Tibiæ et psalterium suavem faciunt melodiam: et super utraque lingua suavis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Gratiam et speciem desiderabit oculus tuus: et super hæc virides sationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Amicus et sodalis in tempore convenientes, et super utrosque mulier cum viro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Fratres in adjutorium in tempore tribulationis: et super eos misericordia liberabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Aurum et argentum est constitutio pedum: et super utrumque consilium beneplacitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Facultates et virtutes exaltant cor, et super hæc timor Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Non est in timore Domini minoratio: et non est in eo inquirere adjutorium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Timor Domini sicut paradisus benedictionis, et super omnem gloriam operuerunt illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Fili, in tempore vitæ tuæ ne indigeas: melius est enim mori quam indigere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Vir respiciens in mensam alienam, non est vita ejus in cogitatione victus: alit enim animam suam cibis alienis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'vir autem disciplinatus et eruditus custodiet se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'In ore imprudentis condulcabitur inopia, et in ventre ejus ignis ardebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'O mors, quam amara est memoria tua homini pacem habenti in substantiis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'viro quieto, et cujus viæ directæ sunt in omnibus, et adhuc valenti accipere cibum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'O mors, bonum est judicium tuum homini indigenti, et qui minoratur viribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'defecto ætate, et cui de omnibus cura est, et incredibili, qui perdit patientiam!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Noli metuere judicium mortis: memento quæ ante te fuerunt, et quæ superventura sunt tibi: hoc judicium a Domino omni carni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Et quid superveniet tibi in beneplacito Altissimi? sive decem, sive centum, sive mille anni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'non est enim in inferno accusatio vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Filii abominationum fiunt filii peccatorum, et qui conversantur secus domos impiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Filiorum peccatorum periet hæreditas, et cum semine illorum assiduitas opprobrii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'De patre impio queruntur filii, quoniam propter illum sunt in opprobrio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Væ vobis, viri impii, qui dereliquistis legem Domini Altissimi!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Et si nati fueritis, in maledictione nascemini: et si mortui fueritis, in maledictione erit pars vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Omnia quæ de terra sunt in terram convertentur: sic impii a maledicto in perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Luctus hominum in corpore ipsorum: nomen autem impiorum delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Curam habe de bono nomine: hoc enim magis permanebit tibi quam mille thesauri pretiosi et magni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Bonæ vitæ numerus dierum: bonum autem nomen permanebit in ævum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Disciplinam in pace conservate, filii: sapientia enim abscondita, et thesaurus invisus, quæ utilitas in utrisque?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Melior est homo qui abscondit stultitiam suam, quam homo qui abscondit sapientiam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Verumtamen reveremini in his quæ procedunt de ore meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'non est enim bonum omnem reverentiam observare, et non omnia omnibus bene placent in fide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Erubescite a patre et a matre de fornicatione: et a præsidente et a potente de mendacio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'a principe et a judice de delicto: a synagoga et plebe de iniquitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'a socio et amico de injustitia, et de loco in quo habitas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'de furto, de veritate Dei, et testamento: de discubitu in panibus, et ab obfuscatione dati et accepti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'a salutantibus de silentio, a respectu mulieris fornicariæ, et ab aversione vultus cognati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Ne avertas faciem a proximo tuo, et ab auferendo partem et non restituendo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 27, 'Ne respicias mulierem alieni viri, et ne scruteris ancillam ejus, neque steteris ad lectum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 28, 'Ab amicis de sermonibus improperii: et cum dederis, ne improperes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Non duplices sermonem auditus de revelatione sermonis absconditi: et eris vere sine confusione, et invenies gratiam in conspectu omnium hominum. Ne pro his omnibus confundaris, et ne accipias personam ut delinquas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'de lege Altissimi, et testamento, et de judicio justificare impium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'de verbo sociorum et viatorum, et de datione hæreditatis amicorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'de æqualitate stateræ et ponderum, de acquisitione multorum et paucorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'de corruptione emptionis et negotiatorum, et de multa disciplina filiorum, et servo pessimo latus sanguinare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Super mulierem nequam bonum est signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Ubi manus multæ sunt, claude: et quodcumque trades, numera et appende: datum vero et acceptum omne describe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'De disciplina insensati et fatui, et de senioribus qui judicantur ab adolescentibus: et eris eruditus in omnibus, et probabilis in conspectu omnium vivorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Filia patris abscondita est vigilia, et sollicitudo ejus aufert somnum: ne forte in adolescentia sua adulta efficiatur, et cum viro commorata odibilis fiat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'nequando polluatur in virginitate sua, et in paternis suis gravida inveniatur: ne forte cum viro commorata transgrediatur, aut certe sterilis efficiatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Super filiam luxuriosam confirma custodiam, nequando faciat te in opprobrium venire inimicis, a detractione in civitate, et objectione plebis, et confundat te in multitudine populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Omni homini noli intendere in specie, et in medio mulierum noli commorari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'de vestimentis enim procedit tinea, et a muliere iniquitas viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Melior est enim iniquitas viri quam mulier benefaciens, et mulier confundens in opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Memor ero igitur operum Domini, et quæ vidi annuntiabo. In sermonibus Domini opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Sol illuminans per omnia respexit, et gloria Domini plenum est opus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Nonne Dominus fecit sanctos enarrare omnia mirabilia sua, quæ confirmavit Dominus omnipotens stabiliri in gloria sua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Abyssum et cor hominum investigavit, et in astutia eorum excogitavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Cognovit enim Dominus omnem scientiam, et inspexit in signum ævi, annuntians quæ præterierunt et quæ superventura sunt, revelans vestigia occultorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Non præterit illum omnis cogitatus, et non abscondit se ab eo ullus sermo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 21, 'Magnalia sapientiæ suæ decoravit, qui est ante sæculum et usque in sæculum: neque adjectum est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 22, 'neque minuitur, et non eget alicujus consilio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 23, 'Quam desiderabilia omnia opera ejus! et tamquam scintilla quæ est considerare!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 24, 'Omnia hæc vivunt, et manent in sæculum, et in omni necessitate omnia obaudiunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 25, 'Omnia duplicia, unum contra unum, et non fecit quidquam deesse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 26, 'Uniuscujusque confirmavit bona: et quis satiabitur videns gloriam ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Altitudinis firmamentum pulchritudo ejus est, species cæli in visione gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Sol in aspectu annuntians in exitu, vas admirabile, opus Excelsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'In meridiano exurit terram, et in conspectu ardoris ejus quis poterit sustinere? fornacem custodiens in operibus ardoris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'tripliciter sol exurens montes, radios igneos exsufflans, et refulgens radiis suis obcæcat oculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Magnus Dominus qui fecit illum, et in sermonibus ejus festinavit iter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Et luna in omnibus in tempore suo, ostensio temporis, et signum ævi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'A luna signum diei festi: luminare quod minuitur in consummatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Mensis secundum nomen ejus est, crescens mirabiliter in consummatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Vas castrorum in excelsis, in firmamento cæli resplendens gloriose.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Species cæli gloria stellarum: mundum illuminans in excelsis Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'In verbis Sancti stabunt ad judicium, et non deficient in vigiliis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Vide arcum, et benedic eum qui fecit illum: valde speciosus est in splendore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Gyravit cælum in circuitu gloriæ suæ: manus Excelsi aperuerunt illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Imperio suo acceleravit nivem, et accelerat coruscationes emittere judicii sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Propterea aperti sunt thesauri, et evolaverunt nebulæ sicut aves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'In magnitudine sua posuit nubes, et confracti sunt lapides grandinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'In conspectu ejus commovebuntur montes, et in voluntate ejus aspirabit notus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Vox tonitrui ejus verberavit terram, tempestas aquilonis, et congregatio spiritus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'et sicut avis deponens ad sedendum, aspergit nivem, et sicut locusta demergens descensus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Pulchritudinem candoris ejus admirabitur oculus, et super imbrem ejus expavescet cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Gelu sicut salem effundet super terram: et dum gelaverit, fiet tamquam cacumina tribuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Frigidus ventus aquilo flavit, et gelavit crystallus ab aqua: super omnem congregationem aquarum requiescet, et sicut lorica induet se aquis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'et devorabit montes, et exuret desertum, et extinguet viride, sicut igne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Medicina omnium in festinatione nebulæ: et ros obvians ab ardore venienti humilem efficiet eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'In sermone ejus siluit ventus, et cogitatione sua placavit abyssum: et plantavit in illa Dominus insulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Qui navigant mare enarrent pericula ejus, et audientes auribus nostris admirabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Illic præclara opera et mirabilia, varia bestiarum genera, et omnium pecorum, et creatura belluarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 28, 'Propter ipsum confirmatus est itineris finis, et in sermone ejus composita sunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 29, 'Multa dicemus, et deficiemus in verbis: consummatio autem sermonum ipse est in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 30, 'Gloriantes ad quid valebimus? ipse enim omnipotens super omnia opera sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 31, 'Terribilis Dominus, et magnus vehementer, et mirabilis potentia ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 32, 'Glorificantes Dominum quantumcumque potueritis, supervalebit enim adhuc: et admirabilis magnificentia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 33, 'Benedicentes Dominum, exaltate illum quantum potestis: major enim est omni laude.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 34, 'Exaltantes eum, replemini virtute, ne laboretis, non enim comprehendetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 35, 'Quis videbit eum et enarrabit? et quis magnificabit eum sicut est ab initio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 36, 'Multa abscondita sunt majora his: pauca enim vidimus operum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 37, 'Omnia autem Dominus fecit, et pie agentibus dedit sapientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Laudemus viros gloriosos, et parentes nostros in generatione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Multam gloriam fecit Dominus: magnificentia sua a sæculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Dominantes in potestatibus suis, homines magni virtute et prudentia sua præditi, nuntiantes in prophetis dignitatem prophetarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'et imperantes in præsenti populo, et virtute prudentiæ populis sanctissima verba:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'in peritia sua requirentes modos musicos, et narrantes carmina Scripturarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'homines divites in virtute, pulchritudinis studium habentes, pacificantes in domibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Omnes isti in generationibus gentis suæ gloriam adepti sunt, et in diebus suis habentur in laudibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Qui de illis nati sunt reliquerunt nomen narrandi laudes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Et sunt quorum non est memoria: perierunt quasi qui non fuerint: et nati sunt quasi non nati, et filii ipsorum cum ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Sed illi viri misericordiæ sunt, quorum pietates non defuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Cum semine eorum permanent bona:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'hæreditas sancta nepotes eorum, et in testamentis stetit semen eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'et filii eorum propter illos usque in æternum manent: semen eorum et gloria eorum non derelinquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Corpora ipsorum in pace sepulta sunt, et nomen eorum vivit in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Sapientiam ipsorum narrent populi, et laudem eorum nuntiet ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Enoch placuit Deo, et translatus est in paradisum, ut det gentibus pœnitentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Noë inventus est perfectus, justus, et in tempore iracundiæ factus est reconciliatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Ideo dimissum est reliquum terræ, cum factum est diluvium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Testamenta sæculi posita sunt apud illum, ne deleri possit diluvio omnis caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Abraham magnus pater multitudinis gentium, et non est inventus similis illi in gloria: qui conservavit legem Excelsi, et fuit in testamento cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'In carne ejus stare fecit testamentum, et in tentatione inventus est fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Ideo jurejurando dedit illi gloriam in gente sua, crescere illum quasi terræ cumulum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'et ut stellas exaltare semen ejus, et hæreditare illos a mari usque ad mare, et a flumine usque ad terminos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Et in Isaac eodem modo fecit, propter Abraham patrem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Benedictionem omnium gentium dedit illi Dominus, et testamentum confirmavit super caput Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Agnovit eum in benedictionibus suis, et dedit illi hæreditatem, et divisit illi partem in tribubus duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Et conservavit illi homines misericordiæ, invenientes gratiam in oculis omnis carnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Dilectus Deo et hominibus Moyses, cujus memoria in benedictione est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Similem illum fecit in gloria sanctorum, et magnificavit eum in timore inimicorum, et in verbis suis monstra placavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Glorificavit illum in conspectu regum, et jussit illi coram populo suo, et ostendit illi gloriam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'In fide et lenitate ipsius sanctum fecit illum, et elegit eum ex omni carne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Audivit enim eum, et vocem ipsius, et induxit illum in nubem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Et dedit illi coram præcepta, et legem vitæ et disciplinæ, docere Jacob testamentum suum, et judicia sua Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Excelsum fecit Aaron fratrem ejus, et similem sibi, de tribu Levi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Statuit ei testamentum æternum, et dedit illi sacerdotium gentis, et beatificavit illum in gloria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'et circumcinxit eum zona gloriæ, et induit eum stolam gloriæ, et coronavit eum in vasis virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Circumpedes, et femoralia, et humerale posuit ei: et cinxit illum tintinnabulis aureis plurimis in gyro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'dare sonitum in incessu suo, auditum facere sonitum in templo in memoriam filiis gentis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Stolam sanctam auro, et hyacintho, et purpura, opus textile viri sapientis, judicio et veritate præditi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'torto cocco opus artificis gemmis pretiosis figuratis in ligatura auri, et opere lapidarii sculptis, in memoriam secundum numerum tribuum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Corona aurea super mitram ejus expressa signo sanctitatis, et gloria honoris: opus virtutis, et desideria oculorum ornata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Sic pulchra ante ipsum non fuerunt talia usque ad originem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Non est indutus illa alienigena aliquis, sed tantum filii ipsius soli, et nepotes ejus per omne tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Sacrificia ipsius consumpta sunt igne quotidie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Complevit Moyses manus ejus, et unxit illum oleo sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Factum est illi in testamentum æternum, et semini ejus, sicut dies cæli, fungi sacerdotio, et habere laudem, et glorificare populum suum in nomine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Ipsum elegit ab omni vivente, offerre sacrificium Deo, incensum, et bonum odorem, in memoriam placare pro populo suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'et dedit illi in præceptis suis potestatem, in testamentis judiciorum: docere Jacob testimonia, et in lege sua lucem dare Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Quia contra illum steterunt alieni, et propter invidiam circumdederunt illum homines in deserto, qui erant cum Dathan et Abiron, et congregatio Core in iracundia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Vidit Dominus Deus, et non placuit illi, et consumpti sunt in impetu iracundiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Fecit illis monstra, et consumpsit illos in flamma ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Et addidit Aaron gloriam, et dedit illi hæreditatem, et primitias frugum terræ divisit illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 26, 'Panem ipsis in primis paravit in satietatem: nam et sacrificia Domini edent, quæ dedit illi et semini ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 27, 'Ceterum in terra gentes non hæreditabit, et pars non est illi in gente: ipse est enim pars ejus, et hæreditas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 28, 'Phinees, filius Eleazari, tertius in gloria est, imitando eum in timore Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 29, 'et stare in reverentia gentis: in bonitate et alacritate animæ suæ placuit Deo pro Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 30, 'Ideo statuit illi testamentum pacis, principem sanctorum et gentis suæ, ut sit illi et semini ejus sacerdotii dignitas in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 31, 'Et testamentum David regi filio Jesse de tribu Juda, hæreditas ipsi et semini ejus: ut daret sapientiam in cor nostrum, judicare gentem suam in justitia, ne abolerentur bona ipsorum: et gloriam ipsorum in gentem eorum æternam fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Fortis in bello Jesus Nave, successor Moysi in prophetis, qui fuit magnus secundum nomen suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'maximus in salutem electorum Dei, expugnare insurgentes hostes, ut consequeretur hæreditatem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Quam gloriam adeptus est in tollendo manus suas, et jactando contra civitates rhomphæas!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Quis ante illum sic restitit? nam hostes ipse Dominus perduxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'An non in iracundia ejus impeditus est sol, et una dies facta est quasi duo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Invocavit Altissimum potentem, in oppugnando inimicos undique: et audivit illum magnus et sanctus Deus, in saxis grandinis virtutis valde fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Impetum fecit contra gentem hostilem, et in descensu perdidit contrarios:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'ut cognoscant gentes potentiam ejus, quia contra Deum pugnare non est facile. Et secutus est a tergo potentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'et in diebus Moysi misericordiam fecit, ipse, et Caleb filius Jephone, stare contra hostem, et prohibere gentem a peccatis, et perfringere murmur malitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Et ipsi duo constituti a periculo liberati sunt a numero sexcentorum millium peditum, inducere illos in hæreditatem, in terram quæ manat lac et mel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Et dedit Dominus ipsi Caleb fortitudinem, et usque in senectutem permansit illi virtus, ut ascenderet in excelsum terræ locum, et semen ipsius obtinuit hæreditatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'ut viderent omnes filii Israël quia bonum est obsequi sancto Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Et judices singuli suo nomine, quorum non est corruptum cor, qui non aversi sunt a Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'ut sit memoria illorum in benedictione, et ossa eorum pullulent de loco suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'et nomen eorum permaneat in æternum, permanens ad filios illorum, sanctorum virorum gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Dilectus a Domino Deo suo Samuel, propheta Domini, renovavit imperium, et unxit principes in gente sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'In lege Domini congregationem judicavit, et vidit Deus Jacob: et in fide sua probatus est propheta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'et cognitus est in verbis suis fidelis, quia vidit Deum lucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Et invocavit Dominum omnipotentem, in oppugnando hostes circumstantes undique, in oblatione agni inviolati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Et intonuit de cælo Dominus, et in sonitu magno auditam fecit vocem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'et contrivit principes Tyriorum, et omnes duces Philisthiim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'et ante tempus finis vitæ suæ et sæculi, testimonium præbuit in conspectu Domini et christi: pecunias et usque ad calceamenta ab omni carne non accepit, et non accusavit illum homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Et post hoc dormivit: et notum fecit regi, et ostendit illi finem vitæ suæ: et exaltavit vocem suam de terra in prophetia, delere impietatem gentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Post hæc surrexit Nathan, propheta in diebus David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Et quasi adeps separatus a carne, sic David a filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Cum leonibus lusit quasi cum agnis, et in ursis similiter fecit sicut in agnis ovium, in juventute sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Numquid non occidit gigantem, et abstulit opprobrium de gente?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'In tollendo manum, saxo fundæ dejecit exsultationem Goliæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'nam invocavit Dominum omnipotentem, et dedit in dextera ejus tollere hominem fortem in bello, et exaltare cornu gentis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Sic in decem millibus glorificavit eum: et laudavit eum in benedictionibus Domini, in offerendo illi coronam gloriæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'contrivit enim inimicos undique, et extirpavit Philisthiim contrarios usque in hodiernum diem: contrivit cornu ipsorum usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'In omni opere dedit confessionem Sancto, et Excelso in verbo gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'De omni corde suo laudavit Dominum: et dilexit Deum, qui fecit illum, et dedit illi contra inimicos potentiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'et stare fecit cantores contra altare, et in sono eorum dulces fecit modos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Et dedit in celebrationibus decus, et ornavit tempora usque ad consummationem vitæ, ut laudarent nomen sanctum Domini, et amplificarent mane Dei sanctitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Dominus purgavit peccata ipsius, et exaltavit in æternum cornu ejus: et dedit illi testamentum regni, et sedem gloriæ in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Post ipsum surrexit filius sensatus, et propter illum dejecit omnem potentiam inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Salomon imperavit in diebus pacis, cui subjecit Deus omnes hostes, ut conderet domum in nomine suo, et pararet sanctitatem in sempiternum. Quemadmodum eruditus es in juventute tua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'et impletus es, quasi flumen, sapientia, et terram retexit anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Et replesti in comparationibus ænigmata: ad insulas longe divulgatum est nomen tuum, et dilectus es in pace tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'In cantilenis, et proverbiis, et comparationibus, et interpretationibus, miratæ sunt terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'et in nomine Domini Dei, cui est cognomen Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Collegisti quasi auricalcum aurum, et ut plumbum complesti argentum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'et inclinasti femora tua mulieribus: potestatem habuisti in corpore tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Dedisti maculam in gloria tua, et profanasti semen tuum, inducere iracundiam ad liberos tuos, et incitari stultitiam tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'ut faceres imperium bipartitum, et ex Ephraim imperare imperium durum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 24, 'Deus autem non derelinquet misericordiam suam: et non corrumpet, nec delebit opera sua, neque perdet a stirpe nepotes electi sui, et semen ejus qui diligit Dominum non corrumpet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 25, 'Dedit autem reliquum Jacob, et David de ipsa stirpe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 26, 'Et finem habuit Salomon cum patribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 27, 'Et dereliquit post se de semine suo, gentis stultitiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 28, 'et imminutum a prudentia, Roboam, qui avertit gentem consilio suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 29, 'et Jeroboam filium Nabat, qui peccare fecit Israël, et dedit viam peccandi Ephraim: et plurima redundaverunt peccata ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 30, 'Valde averterunt illos a terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 31, 'Et quæsivit omnes nequitias, usque dum perveniret ad illos defensio, et ab omnibus peccatis liberavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Et surrexit Elias propheta quasi ignis, et verbum ipsius quasi facula ardebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Qui induxit in illos famem: et irritantes illum invidia sua pauci facti sunt: non enim poterant sustinere præcepta Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Verbo Domini continuit cælum, et dejecit de cælo ignem ter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Sic amplificatus est Elias in mirabilibus suis. Et quis potest similiter sic gloriari tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'qui sustulisti mortuum ab inferis de sorte mortis, in verbo Domini Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'qui dejecisti reges ad pernicem, et confregisti facile potentiam ipsorum, et gloriosos de lecto suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'qui audis in Sina judicium, et in Horeb judicia defensionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'qui ungis reges ad pœnitentiam, et prophetas facis successores post te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'qui receptus es in turbine ignis, in curru equorum igneorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'qui scriptus es in judiciis temporum, lenire iracundiam Domini, conciliare cor patris ad filium, et restituere tribus Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Beati sunt qui te viderunt, et in amicitia tua decorati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Nam nos vita vivimus tantum: post mortem autem non erit tale nomen nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Elias quidem in turbine tectus est, et in Eliseo completus est spiritus ejus: in diebus suis non pertimuit principem, et potentia nemo vicit illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'nec superavit illum verbum aliquod, et mortuum prophetavit corpus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'In vita sua fecit monstra, et in morte mirabilia operatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'In omnibus istis non pœnituit populus, et non recesserunt a peccatis suis, usque dum ejecti sunt de terra sua, et dispersi sunt in omnem terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'et relicta est gens perpauca, et princeps in domo David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Quidam ipsorum fecerunt quod placeret Deo: alii autem multa commiserunt peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Ezechias munivit civitatem suam, et induxit in medium ipsius aquam: et fodit ferro rupem, et ædificavit ad aquam puteum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'In diebus ipsius ascendit Sennacherib, et misit Rabsacen, et sustulit manum suam contra illos: et extulit manum suam in Sion, et superbus factus est potentia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Tunc mota sunt corda et manus ipsorum: et doluerunt quasi parturientes mulieres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Et invocaverunt Dominum misericordem, et expandentes manus suas extulerunt ad cælum: et Sanctus, Dominus Deus, audivit cito vocem ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Non est commemoratus peccatorum illorum, neque dedit illos inimicis suis: sed purgavit eos in manu Isaiæ sancti prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Dejecit castra Assyriorum, et contrivit illos angelus Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'nam fecit Ezechias quod placuit Deo, et fortiter ivit in via David patris sui, quam mandavit illi Isaias, propheta magnus, et fidelis in conspectu Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'In diebus ipsius retro rediit sol, et addidit regi vitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Spiritu magno vidit ultima, et consolatus est lugentes in Sion usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Ostendit futura, et abscondita antequam evenirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 1, 'Memoria Josiæ in compositionem odoris facta opus pigmentarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 2, 'In omni ore quasi mel indulcabitur ejus memoria, et ut musica in convivio vini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 3, 'Ipse est directus divinitus in pœnitentiam gentis, et tulit abominationes impietatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 4, 'Et gubernavit ad Dominum cor ipsius, et in diebus peccatorum corroboravit pietatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 5, 'Præter David et Ezechiam et Josiam, omnes peccatum commiserunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 6, 'nam reliquerunt legem Altissimi reges Juda, et contempserunt timorem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 7, 'Dederunt enim regnum suum aliis, et gloriam suam alienigenæ genti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 8, 'Incenderunt electam sanctitatis civitatem, et desertas fecerunt vias ipsius in manu Jeremiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 9, 'Nam male tractaverunt illum qui a ventre matris consecratus est propheta, evertere, et eruere, et perdere, et iterum ædificare, et renovare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 10, 'Ezechiel, qui vidit conspectum gloriæ quam ostendit illi in curru cherubim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 11, 'Nam commemoratus est inimicorum in imbre, benefacere illis qui ostenderunt rectas vias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 12, 'Et duodecim prophetarum ossa pullulent de loco suo: nam corroboraverunt Jacob, et redemerunt se in fide virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 13, 'Quomodo amplificemus Zorobabel? nam et ipse quasi signum in dextera manu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 14, 'sic et Jesum filium Josedec, qui in diebus suis ædificaverunt domum, et exaltaverunt templum sanctum Domino, paratum in gloriam sempiternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 15, 'Et Nehemias in memoriam multi temporis, qui erexit nobis muros eversos, et stare fecit portas et seras, qui erexit domos nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 16, 'Nemo natus est in terra qualis Henoch, nam et ipse receptus est a terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 17, 'neque ut Joseph, qui natus est homo princeps fratrum, firmamentum gentis, rector fratrum, stabilimentum populi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 18, 'et ossa ipsius visitata sunt, et post mortem prophetaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 49, 19, 'Seth et Sem apud homines gloriam adepti sunt, et super omnem animam in origine Adam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 1, 'Simon, Oniæ filius, sacerdos magnus, qui in vita sua suffulsit domum, et in diebus suis corroboravit templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 2, 'Templi etiam altitudo ab ipso fundata est, duplex ædificatio, et excelsi parietes templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 3, 'In diebus ipsius emanaverunt putei aquarum, et quasi mare adimpleti sunt supra modum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 4, 'Qui curavit gentem suam, et liberavit eam a perditione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 5, 'qui prævaluit amplificare civitatem, qui adeptus est gloriam in conversatione gentis, et ingressum domus et atrii amplificavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 6, 'Quasi stella matutina in medio nebulæ, et quasi luna plena, in diebus suis lucet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 7, 'et quasi sol refulgens, sic ille effulsit in templo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 8, 'Quasi arcus refulgens inter nebulas gloriæ, et quasi flos rosarum in diebus vernis, et quasi lilia quæ sunt in transitu aquæ, et quasi thus redolens in diebus æstatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 9, 'quasi ignis effulgens, et thus ardens in igne:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 10, 'quasi vas auri solidum, ornatum omni lapide pretioso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 11, 'quasi oliva pullulans, et cypressus in altitudinem se extollens, in accipiendo ipsum stolam gloriæ, et vestiri eum in consummationem virtutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 12, 'In ascensu altaris sancti gloriam dedit sanctitatis amictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 13, 'In accipiendo autem partes de manu sacerdotum, et ipse stans juxta aram: et circa illum corona fratrum: quasi plantatio cedri in monte Libano,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 14, 'sic circa illum steterunt quasi rami palmæ: et omnes filii Aaron in gloria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 15, 'Oblatio autem Domini in manibus ipsorum coram omni synagoga Israël: et consummatione fungens in ara, amplificare oblationem excelsi Regis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 16, 'porrexit manum suam in libatione, et libavit de sanguine uvæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 17, 'Effudit in fundamento altaris odorem divinum excelso Principi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 18, 'Tunc exclamaverunt filii Aaron, in tubis productilibus sonuerunt: et auditam fecerunt vocem magnam in memoriam coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 19, 'Tunc omnis populus simul properaverunt, et ceciderunt in faciem super terram, adorare Dominum Deum suum, et dare preces omnipotenti Deo excelso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 20, 'Et amplificaverunt psallentes in vocibus suis, et in magna domo auctus est sonus suavitatis plenus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 21, 'Et rogavit populus Dominum excelsum in prece, usque dum perfectus est honor Domini, et munus suum perfecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 22, 'Tunc descendens, manus suas extulit in omne congregationem filiorum Israël, dare gloriam Deo a labiis suis, et in nomine ipsius gloriari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 23, 'et iteravit orationem suam, volens ostendere virtutem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 24, 'Et nunc orate Deum omnium, qui magna fecit in omni terra, qui auxit dies nostros a ventre matris nostræ, et fecit nobiscum secundum suam misericordiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 25, 'det nobis jucunditatem cordis, et fieri pacem in diebus nostris in Israël per dies sempiternos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 26, 'credere Israël nobiscum esse Dei misericordiam, ut liberet nos in diebus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 27, 'Duas gentes odit anima mea: tertia autem non est gens quam oderim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 28, 'qui sedent in monte Seir, et Philisthiim, et stultus populus qui habitat in Sichimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 29, 'Doctrinam sapientiæ et disciplinæ scripsit in codice isto Jesus, filius Sirach, Jerosolymita, qui renovavit sapientiam de corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 30, 'Beatus qui in istis versatur bonis: qui ponit illa in corde suo, sapiens erit semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 50, 31, 'Si enim hæc fecerit, ad omnia valebit, quia lux Dei vestigium ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 1, 'Oratio Jesu filii Sirach. Confitebor tibi, Domine rex, et collaudabo te Deum salvatorem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 2, 'Confitebor nomini tuo, quoniam adjutor et protector factus es mihi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 3, 'et liberasti corpus meum a perditione: a laqueo linguæ iniquæ, et a labiis operantium mendacium: et in conspectu astantium factus es mihi adjutor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 4, 'Et liberasti me, secundum multitudinem misericordiæ nominis tui, a rugientibus præparatis ad escam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 5, 'de manibus quærentium animam meam, et de portis tribulationum quæ circumdederunt me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 6, 'a pressura flammæ quæ circumdedit me, et in medio ignis non sum æstuatus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 7, 'de altitudine ventris inferi, et a lingua coinquinata, et a verbo mendacii, a rege iniquo, et a lingua injusta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 8, 'Laudabit usque ad mortem anima mea Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 9, 'et vita mea appropinquans erat in inferno deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 10, 'Circumdederunt me undique, et non erat qui adjuvaret: respiciens eram ad adjutorium hominum, et non erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 11, 'Memoratus sum misericordiæ tuæ Domine, et operationis tuæ, quæ a sæculo sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 12, 'quoniam eruis sustinentes te, Domine, et liberas eos de manibus gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 13, 'Exaltasti super terram habitationem meam, et pro morte defluente deprecatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 14, 'Invocavi Dominum patrem Domini mei, ut non derelinquat me in die tribulationis meæ, et in tempore superborum, sine adjutorio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 15, 'Laudabo nomen tuum assidue, et collaudabo illud in confessione: et exaudita est oratio mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 16, 'et liberasti me de perditione, et eripuisti me de tempore iniquo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 17, 'Propterea confitebor, et laudem dicam tibi, et benedicam nomini Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 18, 'Cum adhuc junior essem, priusquam oberrarem, quæsivi sapientiam palam in oratione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 19, 'Ante templum postulabam pro illis, et usque in novissimis inquiram eam: et effloruit tamquam præcox uva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 20, 'Lætatum est cor meum in ea: ambulavit pes meus iter rectum: a juventute mea investigabam eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 21, 'Inclinavi modico aurem meam, et excepi illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 22, 'Multam inveni in meipso sapientiam, et multum profeci in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 23, 'Danti mihi sapientiam dabo gloriam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 24, 'consiliatus sum enim ut facerem illam. Zelatus sum bonum, et non confundar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 25, 'Colluctata est anima mea in illa, et in faciendo eam confirmatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 26, 'Manus meas extendi in altum, et insipientiam ejus luxi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 27, 'animam meam direxi ad illam, et in agnitione inveni eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 28, 'Possedi cum ipsa cor ab initio: propter hoc, non derelinquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 29, 'Venter meus conturbatus est quærendo illam: propterea bonam possidebo possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 30, 'Dedit mihi Dominus linguam mercedem meam, et in ipsa laudabo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 31, 'Appropiate ad me, indocti, et congregate vos in domum disciplinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 32, 'Quid adhuc retardatis? et quid dicitis in his? animæ vestræ sitiunt vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 33, 'Aperui os meum, et locutus sum: Comparate vobis sine argento,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 34, 'et collum vestrum subjicite jugo: et suscipiat anima vestra disciplinam: in proximo est enim invenire eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 35, 'Videte oculis vestris, quia modicum laboravi, et inveni mihi multam requiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 36, 'Assumite disciplinam in multo numero argenti, et copiosum aurum possidete in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 37, 'Lætetur anima vestra in misericordia ejus, et non confundemini in laude ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 51, 38, 'Operamini opus vestrum ante tempus, et dabit vobis mercedem vestram in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Visio Isaiæ, filii Amos, quam vidit super Judam et Jerusalem, in diebus Oziæ, Joathan, Achaz, et Ezechiæ, regum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Audite, cæli, et auribus percipe, terra, quoniam Dominus locutus est. Filios enutrivi, et exaltavi; ipsi autem spreverunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Cognovit bos possessorem suum, et asinus præsepe domini sui; Israël autem me non cognovit, et populus meus non intellexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Væ genti peccatrici, populo gravi iniquitate, semini nequam, filiis sceleratis! dereliquerunt Dominum; blasphemaverunt Sanctum Israël; abalienati sunt retrorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Super quo percutiam vos ultra, addentes prævaricationem? omne caput languidum, et omne cor mœrens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'A planta pedis usque ad verticem, non est in eo sanitas; vulnus, et livor, et plaga tumens, non est circumligata, nec curata medicamine, neque fota oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Terra vestra deserta; civitates vestræ succensæ igni: regionem vestram coram vobis alieni devorant, et desolabitur sicut in vastitate hostili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Et derelinquetur filia Sion ut umbraculum in vinea, et sicut tugurium in cucumerario, et sicut civitas quæ vastatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Nisi Dominus exercituum reliquisset nobis semen, quasi Sodoma fuissemus, et quasi Gomorrha similes essemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Audite verbum Domini, principes Sodomorum; percipite auribus legem Dei nostri, populus Gomorrhæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Quo mihi multitudinem victimarum vestrarum? dicit Dominus. Plenus sum: holocausta arietum, et adipem pinguium, et sanguinem vitulorum et agnorum et hircorum, nolui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Cum veniretis ante conspectum meum, quis quæsivit hæc de manibus vestris, ut ambularetis in atriis meis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Ne offeratis ultra sacrificium frustra: incensum abominatio est mihi. Neomeniam et sabbatum, et festivitates alias, non feram; iniqui sunt cœtus vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Calendas vestras, et solemnitates vestras odivit anima mea: facta sunt mihi molesta; laboravi sustinens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Et cum extenderitis manus vestras, avertam oculos meos a vobis, et cum multiplicaveritis orationem, non exaudiam: manus enim vestræ sanguine plenæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Lavamini, mundi estote; auferte malum cogitationum vestrarum ab oculis meis: quiescite agere perverse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'discite benefacere; quærite judicium, subvenite oppresso, judicate pupillo, defendite viduam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Et venite, et arguite me, dicit Dominus. Si fuerint peccata vestra ut coccinum, quasi nix dealbabuntur; et si fuerint rubra quasi vermiculus, velut lana alba erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Si volueritis, et audieritis me, bona terræ comeditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Quod si nolueritis, et me ad iracundiam provocaveritis, gladius devorabit vos, quia os Domini locutum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Quomodo facta est meretrix civitas fidelis, plena judicii? justitia habitavit in ea, nunc autem homicidæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 22, 'Argentum tuum versum est in scoriam; vinum tuum mistum est aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 23, 'Principes tui infideles, socii furum. Omnes diligunt munera, sequuntur retributiones. Pupillo non judicant, et causa viduæ non ingreditur ad illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 24, 'Propter hoc ait Dominus, Deus exercituum, Fortis Israël: Heu! consolabor super hostibus meis, et vindicabor de inimicis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 25, 'Et convertam manum meam ad te, et excoquam ad puram scoriam tuam, et auferam omne stannum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 26, 'Et restituam judices tuos ut fuerunt prius, et consiliarios tuos sicut antiquitus; post hæc vocaberis civitas justi, urbs fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 27, 'Sion in judicio redimetur, et reducent eam in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 28, 'Et conteret scelestos, et peccatores simul; et qui dereliquerunt Dominum consumentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 29, 'Confundentur enim ab idolis quibus sacrificaverunt, et erubescetis super hortis quos elegeratis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 30, 'cum fueritis velut quercus defluentibus foliis, et velut hortus absque aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 31, 'Et erit fortitudo vestra ut favilla stuppæ, et opus vestrum quasi scintilla, et succendetur utrumque simul, et non erit qui extinguat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Verbum quod vidit Isaias, filius Amos, super Juda et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Et erit in novissimis diebus: præparatus mons domus Domini in vertice montium, et elevabitur super colles; et fluent ad eum omnes gentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'et ibunt populi multi, et dicent: Venite, et ascendamus ad montem Domini, et ad domum Dei Jacob; et docebit nos vias suas, et ambulabimus in semitis ejus, quia de Sion exibit lex, et verbum Domini de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Et judicabit gentes, et arguet populos multos; et conflabunt gladios suos in vomeres, et lanceas suas in falces. Non levabit gens contra gentem gladium, nec exercebuntur ultra ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Domus Jacob, venite, et ambulemus in lumine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Projecisti enim populum tuum, domum Jacob, quia repleti sunt ut olim, et augeres habuerunt ut Philisthiim, et pueris alienis adhæserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Repleta est terra argento et auro, et non est finis thesaurorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Et repleta est terra ejus equis, et innumerabiles quadrigæ ejus. Et repleta est terra ejus idolis; opus manuum suarum adoraverunt, quod fecerunt digiti eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Et incurvavit se homo, et humiliatus est vir; ne ergo dimittas eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Ingredere in petram, et abscondere in fossa humo a facie timoris Domini, et a gloria majestatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Oculi sublimes hominis humiliati sunt, et incurvabitur altitudo virorum; exaltabitur autem Dominus solus in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Quia dies Domini exercituum super omnem superbum, et excelsum, et super omnem arrogantem, et humiliabitur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'et super omnes cedros Libani sublimes et erectas, et super omnes quercus Basan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'et super omnes montes excelsos, et super omnes colles elevatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'et super omnem turrim excelsam, et super omnem murum munitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'et super omnes naves Tharsis, et super omne quod visu pulchrum est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'et incurvabitur sublimitas hominum, et humiliabitur altitudo virorum, et elevabitur Dominus solus in die illa;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'et idola penitus conterentur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'et introibunt in speluncas petrarum, et in voragines terræ, a facie formidinis Domini et a gloria majestatis ejus, cum surrexerit percutere terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'In die illa projiciet homo idola argenti sui, et simulacra auri sui, quæ fecerat sibi ut adoraret, talpas et vespertiliones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Et ingreditur scissuras petrarum et in cavernas saxorum, a facie formidinis Domini, et a gloria majestatis ejus, cum surrexerit percutere terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Quiescite ergo ab homine, cujus spiritus in naribus ejus est, quia excelsus reputatus est ipse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Ecce enim Dominator, Dominus exercituum, auferet a Jerusalem et a Juda validum et fortem, omne robur panis, et omne robor aquæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'fortem, et virum bellatorem, judicem, et prophetam, et ariolum, et senem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'principem super quinquaginta, et honorabilem vultu et consiliarium, et sapientem de architectis, et prudentem eloquii mystici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Et dabo pueros principes eorum, et effeminati dominabuntur eis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'et irruet populus, vir ad virum, et unusquisque ad proximum suum; tumultuabitur puer contra senem, et ignobilis contra nobilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Apprehendet enim vir fratrem suum, domesticum patris sui: Vestimentum tibi est, princeps esto noster, ruina autem hæc sub manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Respondebit in die illa, dicens: Non sum medicus, et in domo mea non est panis neque vestimentum: nolite constituere me principem populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Ruit enim Jerusalem, et Judas concidit, quia lingua eorum et adinventiones eorum contra Dominum, ut provocarent oculos majestatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Agnitio vultus eorum respondit eis; et peccatum suum quasi Sodoma prædicaverunt, nec absconderunt. Væ animæ eorum, quoniam reddita sunt eis mala!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Dicite justo quoniam bene, quoniam fructum adinventionum suarum comedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Væ impio in malum! retributio enim manuum ejus fiet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Populum meum exactores sui spoliaverunt, et mulieres dominatæ sunt eis. Popule meus, qui te beatum dicunt, ipsi te decipiunt, et viam gressuum tuorum dissipant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Stat ad judicandum Dominus, et stat ad judicandos populos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Dominus ad judicium veniet cum senibus populi sui, et principibus ejus; vos enim depasti estis vineam, et rapina pauperis in domo vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Quare atteritis populum meum, et facies pauperum commolitis? dicit Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Et dixit Dominus: Pro eo quod elevatæ sunt filiæ Sion, et ambulaverunt extento collo, et nutibus oculorum ibant, et plaudebant, ambulabant pedibus suis, et composito gradu incedebant;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'decalvabit Dominus verticem filiarum Sion, et Dominus crinem earum nudabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'In die illa auferet Dominus ornamentum calceamentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'et lunulas, et torques, et monilia, et armillas, et mitras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'et discriminalia, et periscelidas, et murenulas, et olfactoriola, et inaures,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'et annulos, et gemmas in fronte pendentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'et mutatoria, et palliola, et linteamina, et acus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'et specula, et sindones, et vittas, et theristra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Et erit pro suavi odore fœtor, et pro zona funiculus, et pro crispanti crine calvitium, et pro fascia pectorali cilicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Pulcherrimi quoque viri tui gladio cadent, et fortes tui in prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Et mœrebunt atque lugebunt portæ ejus, et desolata in terra sedebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Et apprehendent septem mulieres virum unum in die illa, dicentes: Panem nostrum comedemus, et vestimentis nostris operiemur: tantummodo invocetur nomen tuum super nos; aufer opprobrium nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'In die illa, erit germen Domini in magnificentia et gloria, et fructus terræ sublimis, et exsultatio his qui salvati fuerint de Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Et erit: omnis qui relictus fuerit in Sion, et residuus in Jerusalem, Sanctus vocabitur, omnis qui scriptus est in vita in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Si abluerit Dominus sordes filiarum Sion, et sanguinem Jerusalem laverit de medio ejus, in spiritu judicii, et spiritu ardoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Et creabit Dominus super omnem locum montis Sion, et ubi invocatus est, nubem per diem et fumum, et splendorem ignis flammantis in nocte: super omnem enim gloriam protectio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Et tabernaculum erit in umbraculum, diei ab æstu, et in securitatem et absconsionem a turbine et a pluvia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Cantabo dilecto meo canticum patruelis mei vineæ suæ. Vinea facta est dilecto meo in cornu filio olei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Et sepivit eam, et lapides elegit ex illa, et plantavit eam electam; et ædificavit turrim in medio ejus, et torcular exstruxit in ea; et exspectavit ut faceret uvas, et fecit labruscas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Nunc ergo, habitatores Jerusalem et viri Juda, judicate inter me et vineam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Quid est quod debui ultra facere vineæ meæ, et non feci ei? an quod exspectavi ut faceret uvas, et fecit labruscas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Et nunc ostendam vobis quid ego faciam vineæ meæ: auferam sepem ejus, et erit in direptionem; diruam maceriam ejus, et erit in conculcationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Et ponam eam desertam; non putabitur et non fodietur: et ascendent vepres et spinæ, et nubibus mandabo ne pluant super eam imbrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Vinea enim Domini exercituum domus Israël est; et vir Juda germen ejus delectabile: et exspectavi ut faceret judicium, et ecce iniquitas; et justitiam, et ecce clamor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Væ qui conjungitis domum ad domum, et agrum agro copulatis usque ad terminum loci! Numquid habitabitis vos soli in medio terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'In auribus meis sunt hæc, dicit Dominus exercituum; nisi domus multæ desertæ fuerint, grandes et pulchræ, absque habitatore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Decem enim jugera vinearum facient lagunculam unam, et triginta modii sementis facient modios tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Væ qui consurgitis mane ad ebrietatem sectandam, et potandum usque ad vesperam, ut vino æstuetis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Cithara, et lyra, et tympanum, et tibia, et vinum in conviviis vestris; et opus Domini non respicitis, nec opera manuum ejus consideratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Propterea captivus ductus est populus meus, quia non habuit scientiam, et nobiles ejus interierunt fame, et multitudo ejus siti exaruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Propterea dilatavit infernus animam suam, et aperuit os suum absque ullo termino; et descendent fortes ejus, et populus ejus, et sublimes gloriosique ejus, ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Et incurvabitur homo, et humiliabitur vir, et oculi sublimium deprimentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Et exaltabitur Dominus exercituum in judicio; et Deus sanctus sanctificabitur in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Et pascentur agni juxta ordinem suum, et deserta in ubertatem versa advenæ comedent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Væ qui trahitis iniquitatem in funiculis vanitatis, et quasi vinculum plaustri peccatum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'qui dicitis: Festinet, et cito veniat opus ejus, ut videamus; et appropiet, et veniat consilium sancti Israël, et sciemus illud!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Væ qui dicitis malum bonum, et bonum malum; ponentes tenebras lucem, et lucem tenebras; ponentes amarum in dulce, et dulce in amarum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Væ qui sapientes estis in oculis vestris, et coram vobismetipsis prudentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Væ qui potentes estis ad bibendum vinum, et viri fortes ad miscendam ebrietatem!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'qui justificatis impium pro muneribus, et justitiam justi aufertis ab eo!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Propter hoc, sicut devorat stipulam lingua ignis, et calor flammæ exurit, sic radix eorum quasi favilla erit, et germen eorum ut pulvis ascendet; abjecerunt enim legem Domini exercituum, et eloquium sancti Israël blasphemaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Ideo iratus est furor Domini in populum suum, et extendit manum suam super eum, et percussit eum: et conturbati sunt montes, et facta sunt morticina eorum quasi stercus in medio platearum. In his omnibus non est adversus furor ejus, sed adhuc manus ejus extenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Et elevabit signum in nationibus procul, et sibilabit ad eum de finibus terræ: et ecce festinus velociter veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Non est deficiens neque laborans in eo; non dormitabit, neque dormiet; neque solvetur cingulum renum ejus, nec rumpetur corrigia calceamenti ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Sagittæ ejus acutæ, et omnes arcus ejus extenti. Ungulæ equorum ejus ut silex, et rotæ ejus quasi impetus tempestatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Rugitus ejus ut leonis; rugiet ut catuli leonum: et frendet, et tenebit prædam, et amplexabitur, et non erit qui eruat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Et sonabit super eum in die illa sicut sonitus maris: aspiciemus in terram, et ecce tenebræ tribulationis, et lux obtenebrata est in caligine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'In anno quo mortuus est rex Ozias, vidi Dominum sedentem super solium excelsum et elevatum; et ea quæ sub ipso erant replebant templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Seraphim stabant super illud: sex alæ uni, et sex alæ alteri; duabus velabant faciem ejus, et duabus velabant pedes ejus, et duabus volabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Et clamabant alter ad alterum, et dicebant: Sanctus, sanctus, sanctus Dominus, Deus exercituum; plena est omnis terra gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Et commota sunt superliminaria cardinum a voce clamantis, et domus repleta est fumo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Et dixi: Væ mihi, quia tacui, quia vir pollutus labiis ego sum, et in medio populi polluta labia habentis ego habito, et regem Dominum exercituum vidi oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Et volavit ad me unus de seraphim, et in manu ejus calculus, quem forcipe tulerat de altari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'et tetigit os meum, et dixit: Ecce tetigit hoc labia tua, et auferetur iniquitas tua, et peccatum tuum mundabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Et audivi vocem Domini dicentis: Quem mittam? et quis ibit nobis? Et dixi: Ecce ego, mitte me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Et dixit: Vade, et dices populo huic: Audite audientes, et nolite intelligere; et videte visionem, et nolite cognoscere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Excæca cor populi hujus, et aures ejus aggrava, et oculos ejus claude: ne forte videat oculis suis, et auribus suis audiat, et corde suo intelligat, et convertatur, et sanem eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Et dixi: Usquequo, Domine? Et dixit: Donec desolentur civitates absque habitatore, et domus sine homine, et terra relinquetur deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Et longe faciet Dominus homines, et multiplicabitur quæ derelicta fuerat in medio terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Et adhuc in ea decimatio, et convertetur, et erit in ostensionem sicut terebinthus, et sicut quercus quæ expandit ramos suos; semen sanctum erit id quod steterit in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Et factum est in diebus Achaz, filii Joathan, filii Oziæ, regis Juda, ascendit Rasin, rex Syriæ, et Phacee, filius Romeliæ, rex Israël, in Jerusalem, ad præliandum contra eam: et non potuerunt');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'debellare eam. Et nuntiaverunt domui David, dicentes: Requievit Syria super Ephraim. Et commotum est cor ejus, et cor populi ejus, sicut moventur ligna silvarum a facie venti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Et dixit Dominus ad Isaiam: Egredere in occursum Achaz, tu et qui derelictus est Jasub, filius tuus, ad extremum aquæductus piscinæ superioris in via agri Fullonis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'et dices ad eum: Vide ut sileas; noli timere, et cor tuum ne formidet a duabus caudis titionum fumigantium istorum, in ira furoris Rasin, regis Syriæ, et filii Romeliæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'eo quod consilium inierit contra te Syria in malum, Ephraim, et filius Romeliæ, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Ascendamus ad Judam, et suscitemus eum, et avellamus eum ad nos, et ponamus regem in medio ejus filium Tabeel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Hæc dicit Dominus Deus: Non stabit, et non erit istud;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'sed caput Syriæ Damascus, et caput Damasci Rasin; et adhuc sexaginta et quinque anni, et desinet Ephraim esse populus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'et caput Ephraim Samaria, et caput Samariæ filius Romeliæ. Si non credideritis, non permanebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Et adjecit Dominus loqui ad Achaz, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Pete tibi signum a Domino Deo tuo, in profundum inferni, sive in excelsum supra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Et dixit Achaz: Non petam, et non tentabo Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Et dixit: Audite ergo, domus David. Numquid parum vobis est molestos esse hominibus, quia molesti estis et Deo meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Propter hoc dabit Dominus ipse vobis signum: ecce virgo concipiet, et pariet filium, et vocabitur nomen ejus Emmanuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Butyrum et mel comedet, ut sciat reprobare malum, et eligere bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Quia antequam sciat puer reprobare malum et eligere bonum, derelinquetur terra quam tu detestaris a facie duorum regum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Adducet Dominus super te, et super populum tuum, et super domum patris tui, dies qui non venerunt a diebus separationis Ephraim a Juda, cum rege Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Et erit in die illa: sibilabit Dominus muscæ quæ est in extremo fluminum \'gypti, et api quæ est in terra Assur;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'et venient, et requiescent omnes in torrentibus vallium, et in cavernis petrarum, et in omnibus frutetis, et in universis foraminibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'In die illa radet Dominus in novacula conducta in his qui trans flumen sunt, in rege Assyriorum, caput et pilos pedum, et barbam universam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Et erit in die illa: nutriet homo vaccam boum, et duas oves,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'et præ ubertate lactis comedet butyrum; butyrum enim et mel manducabit omnis qui relictus fuerit in medio terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Et erit in die illa: omnis locus ubi fuerint mille vites, mille argenteis, in spinas et in vepres erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Cum sagittis et arcu ingredientur illuc: vepres enim et spinæ erunt in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Et omnes montes qui in sarculo sarrientur, non veniet illuc terror spinarum et veprium: et erit in pascua bovis, et in conculcationem pecoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Et dixit Dominus ad me: Sume tibi librum grandem, et scribe in eo stylo hominis: Velociter spolia detrahe, cito prædare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Et adhibui mihi testes fideles, Uriam sacerdotem, et Zachariam, filium Barachiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'et accessi ad prophetissam, et concepit, et peperit filium. Et dixit Dominus ad me: Voca nomen ejus: Accelera spolia detrahere; Festina prædari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'quia antequam sciat puer vocare patrem suum et matrem suam, auferetur fortitudo Damasci, et spolia Samariæ, coram rege Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Et adjecit Dominus loqui ad me adhuc, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Pro eo quod abjecit populus iste aquas Siloë, quæ vadunt cum silentio, et assumpsit magis Rasin, et filium Romeliæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'propter hoc ecce Dominus adducet super eos aquas fluminis fortes et multas, regem Assyriorum, et omnem gloriam ejus, et ascendet super omnes rivos ejus, et fluet super universas ripas ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'et ibit per Judam, inundans, et transiens: usque ad collum veniet. Et erit extensio alarum ejus implens latitudinem terræ tuæ, o Emmanuel!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Congregamini, populi, et vincimini; et audite, universæ procul terræ: confortamini, et vincimini; accingite vos, et vincimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Inite consilium, et dissipabitur; loquimini verbum, et non fiet: quia nobiscum Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Hæc enim ait Dominus ad me: Sicut in manu forti erudivit me, ne irem in via populi hujus, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Non dicatis: Conjuratio; omnia enim quæ loquitur populus iste, conjuratio est: et timorem ejus ne timeatis, neque paveatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Dominum exercituum ipsum sanctificate; ipse pavor vester, et ipse terror vester:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'et erit vobis in sanctificationem; in lapidem autem offensionis, et in petram scandali, duabus domibus Israël; in laqueum et in ruinam habitantibus Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Et offendent ex eis plurimi, et cadent, et conterentur, et irretientur, et capientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Liga testimonium, signa legem in discipulis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Et exspectabo Dominum qui abscondit faciem suam a domo Jacob, et præstolabor eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Ecce ego et pueri mei quos dedit mihi Dominus in signum, et in portentum Israël a Domino exercituum, qui habitat in monte Sion:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'et cum dixerint ad vos: Quærite a pythonibus et a divinis qui strident in incantationibus suis: numquid non populus a Deo suo requiret, pro vivis a mortuis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'ad legem magis et ad testimonium. Quod si non dixerint juxta verbum hoc, non erit eis matutina lux.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Et transibit per eam, corruet, et esuriet; et cum esurierit, irascetur. Et maledicet regi suo, et Deo suo, et suscipiet sursum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'et ad terram intuebitur; et ecce tribulatio et tenebræ, dissolutio et angustia, et caligo persequens, et non poterit avolare de angustia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Primo tempore alleviata est terra Zabulon et terra Nephthali: et novissimo aggravata est via maris trans Jordanem Galilææ gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Populus qui ambulabat in tenebris, vidit lucem magnam; habitantibus in regione umbræ mortis, lux orta est eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Multiplicasti gentem, et non magnificasti lætitiam. Lætabuntur coram te, sicut qui lætantur in messe; sicut exsultant victores capta præda, quando dividunt spolia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Jugum enim oneris ejus, et virgam humeri ejus, et sceptrum exactoris ejus superasti, sicut in die Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Quia omnis violentia prædatio cum tumultu, et vestimentum mistum sanguine, erit in combustionem, et cibus ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Parvulus enim natus est nobis, et filius datus est nobis, et factus est principatus super humerum ejus: et vocabitur nomen ejus, Admirabilis, Consiliarius, Deus, Fortis, Pater futuri sæculi, Princeps pacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Multiplicabitur ejus imperium, et pacis non erit finis; super solium David, et super regnum ejus sedebit, ut confirmet illud et corroboret in judicio et justitia, amodo et usque in sempiternum: zelus Domini exercituum faciet hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Verbum misit Dominus in Jacob, et cecidit in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Et sciet omnis populus Ephraim, et habitantes Samariam, in superbia et magnitudine cordis dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Lateres ceciderunt, sed quadris lapidibus ædificabimus; sycomoros succiderunt, sed cedros immutabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Et elevabit Dominus hostes Rasin super eum, et inimicos ejus in tumultum vertet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Syriam ab oriente, et Philisthiim ab occidente; et devorabunt Israël toto ore. In omnibus his non est aversus furor ejus, sed adhuc manus ejus extenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Et populus non est reversus ad percutientem se, et Dominum exercituum non inquisierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Et disperdet Dominus ab Israël caput et caudam, incurvantem et refrenantem, die una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Longævus et honorabilis, ipse est caput; et propheta docens mendacium, ipse est cauda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Et erunt qui beatificant populum istum, seducentes; et qui beatificantur, præcipitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Propter hoc super adolescentulis ejus non lætabitur Dominus, et pupillorum ejus et viduarum non miserebitur: quia omnis hypocrita est et nequam, et universum os locutum est stultitiam; in omnibus his non est aversus furor ejus, sed adhuc manus ejus extenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Succensa est enim quasi ignis impietas: veprem et spinam vorabit, et succendetur in densitate saltus, et convolvetur superbia fumi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'In ira Domini exercituum conturbata est terra, et erit populus quasi esca ignis; vir fratri suo non parcet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Et declinabit ad dexteram, et esuriet; et comedet ad sinistram, et non saturabitur; unusquisque carnem brachii sui vorabit: Manasses Ephraim, et Ephraim Manassen; simul ipsi contra Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'In omnibus his non est aversus furor ejus, sed adhuc manus ejus extenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Væ qui condunt leges iniquas, et scribentes injustitiam scripserunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'ut opprimerent in judicio pauperes, et vim facerent causæ humilium populi mei; ut essent viduæ præda eorum, et pupillos diriperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Quid facietis in die visitationis, et calamitatis de longe venientis? ad cujus confugietis auxilium? et ubi derelinquetis gloriam vestram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'ne incurvemini sub vinculo, et cum interfectis cadatis? Super omnibus his non est aversus furor ejus, sed adhuc manus ejus extenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Væ Assur! virga furoris mei et baculus ipse est; in manu eorum indignatio mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Ad gentem fallacem mittam eum, et contra populum furoris mei mandabo illi, ut auferat spolia, et diripiat prædam, et ponat illum in conculcationem quasi lutum platearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ipse autem non sic arbitrabitur, et cor ejus non ita existimabit; sed ad conterendum erit cor ejus, et ad internecionem gentium non paucarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Dicet enim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Numquid non principes mei simul reges sunt? numquid non ut Charcamis, sic Calano? et ut Arphad, sic Emath? numquid non ut Damascus, sic Samaria?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Quomodo invenit manus mea regna idoli, sic et simulacra eorum de Jerusalem et de Samaria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Numquid non sicut feci Samariæ et idolis ejus, sic faciam Jerusalem et simulacris ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Et erit, cum impleverit Dominus cuncta opera sua in monte Sion et in Jerusalem, visitabo super fructum magnifici cordis regis Assur, et super gloriam altitudinis oculorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Dixit enim: In fortitudine manus meæ feci, et in sapientia mea intellexi; et abstuli terminos populorum, et principes eorum deprædatus sum, et detraxi quasi potens in sublimi residentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Et invenit quasi nidum manus mea fortitudinem populorum; et sicut colliguntur ova quæ derelicta sunt, sic universam terram ego congregavi; et non fuit qui moveret pennam, et aperiret os, et ganniret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Numquid gloriabitur securis contra eum qui secat in ea? aut exaltabitur serra contra eum a quo trahitur? Quomodo si elevetur virga contra elevantem se, et exaltetur baculus, qui utique lignum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Propter hoc mittet Dominator, Dominus exercituum, in pinguibus ejus tenuitatem; et subtus gloriam ejus succensa ardebit quasi combustio ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Et erit lumen Israël in igne, et Sanctus ejus in flamma; et succendetur, et devorabitur spina ejus et vepres in die una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Et gloria saltus ejus, et carmeli ejus, ab anima usque ad carnem consumetur; et erit terrore profugus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Et reliquiæ ligni saltus ejus præ paucitate numerabuntur, et puer scribet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Et erit in die illa: non adjiciet residuum Israël, et hi qui fugerint de domo Jacob, inniti super eo qui percutit eos; sed innitetur super Dominum, Sanctum Israël, in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Reliquiæ convertentur; reliquiæ, inquam, Jacob ad Deum fortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 22, 'Si enim fuerit populus tuus, Israël, quasi arena maris, reliquiæ convertentur ex eo; consummatio abbreviata inundabit justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 23, 'Consummationem enim et abbreviationem Dominus Deus exercituum faciet in medio omnis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 24, 'Propter hoc, hæc dicit Dominus Deus exercituum: Noli timere, populus meus, habitator Sion, ab Assur: in virga percutiet te, et baculum suum levabit super te, in via \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 25, 'Adhuc enim paululum modicumque, et consummabitur indignatio et furor meus super scelus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 26, 'Et suscitabit super eum Dominus exercituum flagellum, juxta plagam Madian in petra Oreb: et virgam suam super mare, et levabit eam in via \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 27, 'Et erit in die illa: auferetur onus ejus de humero tuo et jugum ejus de collo tuo, et computrescet jugum a facie olei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 28, 'Veniet in Ajath, transibit in Magron, apud Machmas commendabit vasa sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 29, 'Transierunt cursim, Gaba sedes nostra; obstupuit Rama, Gabaath Saulis fugit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 30, 'Hinni voce tua, filia Gallim, attende Laisa, paupercula Anathoth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 31, 'Migravit Medemena; habitatores Gabim, confortamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 32, 'Adhuc dies est ut in Nobe stetur; agitabit manum suam super montem filiæ Sion, collem Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 33, 'Ecce Dominator, Dominus exercituum, confringet lagunculam in terrore; et excelsi statura succidentur, et sublimes humiliabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 34, 'Et subvertentur condensa saltus ferro; et Libanus cum excelsis cadet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Et egredietur virga de radice Jesse, et flos de radice ejus ascendet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Et requiescet super eum spiritus Domini: spiritus sapientiæ et intellectus, spiritus consilii et fortitudinis, spiritus scientiæ et pietatis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'et replebit eum spiritus timoris Domini. Non secundum visionem oculorum judicabit, neque secundum auditum aurium arguet;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'sed judicabit in justitia pauperes, et arguet in æquitate pro mansuetis terræ; et percutiet terram virga oris sui, et spiritu labiorum suorum interficiet impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Et erit justitia cingulum lumborum ejus, et fides cinctorium renum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Habitabit lupus cum agno, et pardus cum hædo accubabit; vitulus, et leo, et ovis, simul morabuntur, et puer parvulus minabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Vitulus et ursus pascentur, simul requiescent catuli eorum; et leo quasi bos comedet paleas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Et delectabitur infans ab ubere super foramine aspidis; et in caverna reguli qui ablactatus fuerit manum suam mittet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Non nocebunt, et non occident in universo monte sancto meo, quia repleta est terra scientia Domini, sicut aquæ maris operientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'In die illa radix Jesse, qui stat in signum populorum, ipsum gentes deprecabuntur, et erit sepulchrum ejus gloriosum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Et erit in die illa: adjiciet Dominus secundo manum suam ad possidendum residuum populi sui, quod relinquetur ab Assyriis, et ab \'gypto, et a Phetros, et ab \'thiopia, et ab \'lam, et a Sennaar, et ab Emath, et ab insulis maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Et levabit signum in nationes, et congregabit profugos Israël, et dispersos Juda colliget a quatuor plagis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Et auferetur zelus Ephraim, et hostes Juda peribunt; Ephraim non æmulabitur Judam, et Judas non pugnabit contra Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Et volabunt in humeros Philisthiim per mare, simul prædabuntur filios orientis; Idumæa et Moab præceptum manus eorum, et filii Ammon obedientes erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Et desolabit Dominus linguam maris \'gypti, et levabit manum suam super flumen in fortitudine spiritus sui; et percutiet eum in septem rivis, ita ut transeant per eum calceati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Et erit via residuo populo meo qui relinquetur ab Assyriis, sicut fuit Israëli in die illa qua ascendit de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Et dices in die illa: Confitebor tibi, Domine, quoniam iratus es mihi; conversus est furor tuus, et consolatus es me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Ecce Deus salvator meus; fiducialiter agam, et non timebo: quia fortitudo mea et laus mea Dominus, et factus est mihi in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Haurietis aquas in gaudio de fontibus salvatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Et dicetis in die illa: Confitemini Domino et invocate nomen ejus; notas facite in populis adinventiones ejus; mementote quoniam excelsum est nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Cantate Domino, quoniam magnifice fecit; annuntiate hoc in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Exsulta et lauda, habitatio Sion, quia magnus in medio tui Sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 1, 'Onus Babylonis, quod vidit Isaias, filius Amos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 2, 'Super montem caliginosum levate signum: exaltate vocem, levate manum, et ingrediantur portas duces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 3, 'Ego mandavi sanctificatis meis, et vocavi fortes meos in ira mea, exsultantes in gloria mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 4, 'Vox multitudinis in montibus, quasi populorum frequentium; vox sonitus regum, gentium congregatarum. Dominus exercituum præcepit militiæ belli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 5, 'venientibus de terra procul, a summitate cæli; Dominus, et vasa furoris ejus, ut disperdat omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 6, 'Ululate, quia prope est dies Domini; quasi vastitas a Domino veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 7, 'Propter hoc omnes manus dissolventur, et omne cor hominis contabescet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 8, 'et conteretur. Torsiones et dolores tenebunt; quasi parturiens dolebunt: unusquisque ad proximum suum stupebit, facies combustæ vultus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 9, 'Ecce dies Domini veniet, crudelis, et indignationis plenus, et iræ, furorisque, ad ponendam terram in solitudinem, et peccatores ejus conterendos de ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 10, 'Quoniam stellæ cæli, et splendor earum, non expandent lumen suum; obtenebratus est sol in ortu suo, et luna non splendebit in lumine suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 11, 'Et visitabo super orbis mala, et contra impios iniquitatem eorum; et quiescere faciam superbiam infidelium, et arrogantiam fortium humiliabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 12, 'Pretiosior erit vir auro, et homo mundo obrizo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 13, 'Super hoc cælum turbabo; et movebitur terra de loco suo, propter indignationem Domini exercituum, et propter diem iræ furoris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 14, 'Et erit quasi damula fugiens, et quasi ovis, et non erit qui congreget. Unusquisque ad populum suum convertetur, et singuli ad terram suam fugient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 15, 'Omnis qui inventus fuerit occidetur, et omnis qui supervenerit cadet in gladio;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 16, 'infantes eorum allidentur in oculis eorum, diripientur domus eorum, et uxores eorum violabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 17, 'Ecce ego suscitabo super eos Medos, qui argentum non quærant, nec aurum velint;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 18, 'sed sagittis parvulos interficient, et lactantibus uteris non miserebuntur, et super filios non parcet oculus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 19, 'Et erit Babylon illa gloriosa in regnis, inclyta superbia Chaldæorum, sicut subvertit Dominus Sodomam et Gomorrham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 20, 'Non habitabitur usque in finem, et non fundabitur usque ad generationem et generationem; nec ponet ibi tentoria Arabs, nec pastores requiescent ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 21, 'Sed requiescent ibi bestiæ, et replebuntur domus eorum draconibus, et habitabunt ibi struthiones, et pilosi saltabunt ibi;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 13, 22, 'et respondebunt ibi ululæ in ædibus ejus, et sirenes in delubris voluptatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 1, 'Prope est ut veniat tempus ejus, et dies ejus non elongabuntur. Miserebitur enim Dominus Jacob, et eliget adhuc de Israël, et requiescere eos faciet super humum suam; adjungetur advena ad eos, et adhærebit domui Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 2, 'Et tenebunt eos populi, et adducent eos in locum suum; et possidebit eos domus Israël super terram Domini in servos et ancillas: et erunt capientes eos qui se ceperant, et subjicient exactores suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 3, 'Et erit in die illa: cum requiem dederit tibi Deus a labore tuo, et a concussione tua, et a servitute dura qua ante servisti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 4, 'sumes parabolam istam contra regem Babylonis, et dices: Quomodo cessavit exactor; quievit tributum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 5, 'Contrivit Dominus baculum impiorum, virgam dominantium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 6, 'cædentem populos in indignatione plaga insanabili, subjicientem in furore gentes, persequentem crudeliter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 7, 'Conquievit et siluit omnis terra, gavisa est et exsultavit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 8, 'abietes quoque lætatæ sunt super te, et cedri Libani: ex quo dormisti, non ascendet qui succidat nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 9, 'Infernus subter conturbatus est in occursum adventus tui; suscitavit tibi gigantes. Omnes principes terræ surrexerunt de soliis suis, omnes principes nationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 10, 'Universi respondebunt, et dicent tibi: Et tu vulneratus es sicut et nos; nostri similis effectus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 11, 'Detracta est ad inferos superbia tua, concidit cadaver tuum; subter te sternetur tinea, et operimentum tuum erunt vermes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 12, 'Quomodo cecidisti de cælo, Lucifer, qui mane oriebaris? corruisti in terram, qui vulnerabas gentes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 13, 'Qui dicebas in corde tuo: In cælum conscendam, super astra Dei exaltabo solium meum; sedebo in monte testamenti, in lateribus aquilonis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 14, 'ascendam super altitudinem nubium, similis ero Altissimo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 15, 'Verumtamen ad infernum detraheris, in profundum laci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 16, 'Qui te viderint, ad te inclinabuntur, teque prospicient: Numquid iste est vir qui conturbavit terram, qui concussit regna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 17, 'qui posuit orbem desertum, et urbes ejus destruxit, vinctis ejus non aperuit carcerem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 18, 'Omnes reges gentium universi dormierunt in gloria, vir in domo sua;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 19, 'tu autem projectus es de sepulchro tuo, quasi stirps inutilis pollutus, et obvolutus cum his qui interfecti sunt gladio, et descenderunt ad fundamenta laci, quasi cadaver putridum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 20, 'Non habebis consortium, neque cum eis in sepultura; tu enim terram tuam disperdidisti, tu populum tuum occidisti: non vocabitur in æternum semen pessimorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 21, 'Præparate filios ejus occisioni, in iniquitate patrum suorum: non consurgent, nec hæreditabunt terram, neque implebunt faciem orbis civitatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 22, 'Et consurgam super eos, dicit Dominus exercituum; et perdam Babylonis nomen, et reliquias, et germen, et progeniem, dicit Dominus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 23, 'et ponam eam in possessionem ericii, et in paludes aquarum, et scopabo eam in scopa terens, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 24, 'Juravit Dominus exercituum, dicens: Si non, ut putavi, ita erit; et quomodo mente tractavi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 25, 'sic eveniet: ut conteram Assyrium in terra mea, et in montibus meis conculcem eum; et auferetur ab eis jugum ejus, et onus illius ab humero eorum tolletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 26, 'Hoc consilium quod cogitavi super omnem terram; et hæc est manus extenta super universas gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 27, 'Dominus enim exercituum decrevit; et quis poterit infirmare? et manus ejus extenta; et quis avertet eam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 28, 'In anno quo mortuus est rex Achaz, factum est onus istud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 29, 'Ne lætaris, Philisthæa omnis tu, quoniam comminuta est virga percussoris tui; de radice enim colubri egredietur regulus, et semen ejus absorbens volucrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 30, 'Et pascentur primogeniti pauperum, et pauperes fiducialiter requiescent; et interire faciam in fame radicem tuam, et reliquias tuas interficiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 31, 'Ulula, porta; clama civitas; prostrata est Philisthæa omnis; ab aquilone enim fumus veniet, et non est qui effugiet agmen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 14, 32, 'Et quid respondebitur nuntiis gentis? Quia Dominus fundavit Sion, et in ipso sperabunt pauperes populi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 1, 'Onus Moab. Quia nocte vastata est Ar Moab, conticuit; quia nocte vastatus est murus Moab, conticuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 2, 'Ascendit domus, et Dibon ad excelsa, in planctum super Nabo; et super Medaba, Moab ululavit; in cunctis capitibus ejus calvitium, et omnis barba radetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 3, 'In triviis ejus accincti sunt sacco; super tecta ejus et in plateis ejus omnis ululatus descendit in fletum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 4, 'Clamabit Hesebon et Eleale, usque Jasa audita est vox eorum; super hoc expediti Moab ululabunt, anima ejus ululabit sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 5, 'Cor meum ad Moab clamabit; vectes ejus usque ad Segor, vitulam conternantem; per ascensum enim Luith flens ascendet, et in via Oronaim clamorem contritionis levabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 6, 'Aquæ enim Nemrim desertæ erunt, quia aruit herba, defecit germen, viror omnis interiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 7, 'Secundum magnitudinem operis, et visitatio eorum: ad torrentem Salicum ducent eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 8, 'Quoniam circuivit clamor terminum Moab; usque ad Gallim ululatus ejus, et usque ad puteum Elim clamor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 15, 9, 'Quia aquæ Dibon repletæ sunt sanguine; ponam enim super Dibon additamenta; his qui fugerint de Moab leonem, et reliquiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 1, 'Emitte agnum, Domine, dominatorem terræ, de petra deserti ad montem filiæ Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 2, 'Et erit: sicut avis fugiens, et pulli de nido avolantes, sic erunt filiæ Moab in transcensu Arnon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 3, 'Ini consilium, coge concilium; pone quasi noctem umbram tuam in meridie; absconde fugientes, et vagos ne prodas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 4, 'Habitabunt apud te profugi mei; Moab, esto latibulum eorum a facie vastatoris: finitus est enim pulvis, consummatus est miser, defecit qui conculcabat terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 5, 'Et præparabitur in misericordia solium, et sedebit super illud in veritate in tabernaculo David, judicans et quærens judicium, et velociter reddens quod justum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 6, 'Audivimus superbiam Moab: superbus est valde; superbia ejus, et arrogantia ejus, et indignatio ejus plus quam fortitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 7, 'Idcirco ululabit Moab ad Moab; universus ululabit: his qui lætantur super muros cocti lateris, loquimini plagas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 8, 'Quoniam suburbana Hesebon deserta sunt, et vineam Sabama domini gentium exciderunt: flagella ejus usque ad Jazer pervenerunt, erraverunt in deserto; propagines ejus relictæ sunt, transierunt mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 9, 'Super hoc plorabo in fletu Jazer vineam Sabama; inebriabo de lacrima mea, Hesebon et Eleale, quoniam super vindemiam tuam et super messem tuam vox calcantium irruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 10, 'Et auferetur lætitia et exsultatio de Carmelo, et in vineis non exsultabit neque jubilabit. Vinum in torculari non calcabit qui calcare consueverat; vocem calcantium abstuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 11, 'Super hoc venter meus ad Moab quasi cithara sonabit, et viscera mea ad murum cocti lateris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 12, 'Et erit: cum apparuerit quod laboravit Moab super excelsis suis, ingredietur ad sancta sua ut obsecret, et non valebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 13, 'Hoc verbum quod locutus est Dominus ad Moab ex tunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 16, 14, 'Et nunc locutus est Dominus, dicens: In tribus annis, quasi anni mercenarii, auferetur gloria Moab super omni populo multo, et relinquetur parvus et modicus, nequaquam multus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 1, 'Onus Damasci. Ecce Damascus desinet esse civitas, et erit sicut acervus lapidum in ruina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 2, 'Derelictæ civitates Aroër gregibus erunt, et requiescent ibi, et non erit qui exterreat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 3, 'Et cessabit adjutorium ab Ephraim, et regnum a Damasco; et reliquiæ Syriæ sicut gloria filiorum Israël erunt, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 4, 'Et erit in die illa: attenuabitur gloria Jacob, et pinguedo carnis ejus marcescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 5, 'Et erit sicut congregans in messe quod restiterit, et brachium ejus spicas leget; et erit sicut quærens spicas in valle Raphaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 6, 'Et relinquetur in eo sicut racemus et sicut excussio oleæ duarum vel trium olivarum in summitate rami, sive quatuor aut quinque in cacuminibus ejus fructus ejus, dicit Dominus Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 7, 'In die illa inclinabitur homo ad factorem suum, et oculi ejus ad Sanctum Israël respicient;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 8, 'et non inclinabitur ad altaria quæ fecerunt manus ejus; et quæ operati sunt digiti ejus non respiciet lucos et delubra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 9, 'In die illa erunt civitates fortitudinis ejus derelictæ sicut aratra, et segetes quæ derelictæ sunt a facie filiorum Israël; et eris deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 10, 'Quia oblitus es Dei salvatoris tui, et fortis adjutoris tui non es recordata: propterea plantabis plantationem fidelem, et germen alienum seminabis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 11, 'in die plantationis tuæ labrusca, et mane semen tuum florebit; ablata est messis in die hæreditatis, et dolebit graviter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 12, 'Væ multitudini populorum multorum, ut multitudo maris sonantis; et tumultus turbarum, sicut sonitus aquarum multarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 13, 'Sonabunt populi sicut sonitus aquarum inundantium, et increpabit eum, et fugiet procul; et rapietur sicut pulvis montium a facie venti, et sicut turbo coram tempestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 17, 14, 'In tempore vespere, et ecce turbatio; in matutino, et non subsistet. Hæc est pars eorum qui vastaverunt nos, et sors diripientium nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 1, 'Væ terræ cymbalo alarum, quæ est trans flumina \'thiopiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 2, 'qui mittit in mare legatos, et in vasis papyri super aquas. Ite, angeli veloces, ad gentem convulsam et dilaceratam; ad populum terribilem, post quem non est alius; ad gentem exspectantem et conculcatam, cujus diripuerunt flumina terram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 3, 'Omnes habitatores orbis, qui moramini in terra, cum elevatum fuerit signum in montibus, videbitis, et clangorem tubæ audietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 4, 'Quia hæc dicit Dominus ad me: Quiescam et considerabo in loco meo, sicut meridiana lux clara est, et sicut nubes roris in die messis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 5, 'Ante messem enim totus effloruit, et immatura perfectio germinabit; et præcidentur ramusculi ejus falcibus, et quæ derelicta fuerint abscindentur et excutientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 6, 'Et relinquentur simul avibus montium et bestiis terræ; et æstate perpetua erunt super eum volucres, et omnes bestiæ terræ super illum hiemabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 18, 7, 'In tempore illo deferetur munus Domino exercituum a populo divulso et dilacerato, a populo terribili, post quem non fuit alius; a gente exspectante, exspectante et conculcata, cujus diripuerunt flumina terram ejus; ad locum nominis Domini exercituum, montem Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 1, 'Onus \'gypti. Ecce Dominus ascendet super nubem levem, et ingredietur \'gyptum, et commovebuntur simulacra \'gypti a facie ejus, et cor \'gypti tabescet in medio ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 2, 'et concurrere faciam \'gyptios adversus \'gyptios; et pugnabit vir contra fratrem suum, et vir contra amicum suum, civitas adversus civitatem, regnum adversus regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 3, 'Et dirumpetur spiritus \'gypti in visceribus ejus, et consilium ejus præcipitabo; et interrogabunt simulacra sua, et divinos suos, et pythones, et ariolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 4, 'Et tradam \'gyptum in manu dominorum crudelium, et rex fortis dominabitur eorum, ait Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 5, 'Et arescet aqua de mari, et fluvius desolabitur atque siccabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 6, 'Et deficient flumina, attenuabuntur et siccabuntur rivi aggerum, calamus et juncus marcescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 7, 'Nudabitur alveus rivi a fonte suo, et omnis sementis irrigua siccabitur, arescet, et non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 8, 'Et mœrebunt piscatores, et lugebunt omnes mittentes in flumen hamum; et expandentes rete super faciem aquarum emarcescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 9, 'Confundentur qui operabantur linum, pectentes et texentes subtilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 10, 'Et erunt irrigua ejus flaccentia: omnes qui faciebant lacunas ad capiendos pisces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 11, 'Stulti principes Taneos, sapientes consiliarii Pharaonis dederunt consilium insipiens. Quomodo dicetis Pharaoni: Filius sapientium ego, filius regum antiquorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 12, 'Ubi nunc sunt sapientes tui? annuntient tibi, et indicent quid cogitaverit Dominus exercituum super \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 13, 'Stulti facti sunt principes Taneos, emarcuerunt principes Mempheos; deceperunt \'gyptum, angulum populorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 14, 'Dominus miscuit in medio ejus spiritum vertiginis; et errare fecerunt \'gyptum in omni opere suo, sicut errat ebrius et vomens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 15, 'Et non erit \'gypto opus quod faciat caput et caudam, incurvantem et refrenantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 16, 'In die illa erit \'gyptus quasi mulieres; et stupebunt, et timebunt a facie commotionis manus Domini exercituum, quam ipse movebit super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 17, 'Et erit terra Juda \'gypto in pavorem; omnis qui illius fuerit recordatus pavebit a facie consilii Domini exercituum, quod ipse cogitavit super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 18, 'In die illa erunt quinque civitates in terra \'gypti loquentes lingua Chanaan, et jurantes per Dominum exercituum: Civitas solis vocabitur una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 19, 'In die illa erit altare Domini in medio terræ \'gypti, et titulus Domini juxta terminum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 20, 'Erit in signum et in testimonium Domino exercituum in terra \'gypti; clamabunt enim ad Dominum a facie tribulationis, et mittet eis salvatorem et propugnatorem qui liberet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 21, 'Et cognoscetur Dominus ab \'gypto, et cognoscent \'gyptii Dominum in die illa; et colent eum in hostiis et in muneribus; et vota vovebunt Domino, et solvent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 22, 'Et percutiet Dominus \'gyptum plaga, et sanabit eam; et revertentur ad Dominum, et placabitur eis, et sanabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 23, 'In die illa erit via de \'gypto in Assyrios; et intrabit Assyrius \'gyptum, et \'gyptius in Assyrios, et servient \'gyptii Assur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 24, 'In die illa erit Israël tertius \'gyptio et Assyrio; benedictio in medio terræ');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 19, 25, 'cui benedixit Dominus exercituum, dicens: Benedictus populus meus \'gypti, et opus manuum mearum Assyrio; hæreditas autem mea Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 1, 'In anno quo ingressus est Thathan in Azotum, cum misisset eum Sargon, rex Assyriorum, et pugnasset contra Azotum, et cepisset eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 2, 'in tempore illo locutus est Dominus in manu Isaiæ, filii Amos, dicens: Vade, et solve saccum de lumbis tuis, et calceamenta tua tolle de pedibus tuis. Et fecit sic, vadens nudus et discalceatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 3, 'Et dixit Dominus: Sicut ambulavit servus meus Isaias nudus et discalceatus, trium annorum signum et portentum erit super \'gyptum et super \'thiopiam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 4, 'sic minabit rex Assyriorum captivitatem \'gypti, et transmigrationem \'thiopiæ, juvenum et senum, nudam et discalceatam, discoopertis natibus, ad ignominiam \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 5, 'Et timebunt, et confundentur ab \'thiopia spe sua, et ab \'gypto gloria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 20, 6, 'Et dicet habitator insulæ hujus in die illa: Ecce hæc erat spes nostra, ad quos confugimus in auxilium, ut liberarent nos a facie regis Assyriorum: et quomodo effugere poterimus nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 1, 'Onus deserti maris. Sicut turbines ab africo veniunt, de deserto venit, de terra horribili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 2, 'Visio dura nuntiata est mihi: qui incredulus est infideliter agit; et qui depopulator est vastat. Ascende, \'lam; obside, Mede; omnem gemitum ejus cessare feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 3, 'Propterea repleti sunt lumbi mei dolore; angustia possedit me sicut angustia parturientis; corrui cum audirem, conturbatus sum cum viderem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 4, 'Emarcuit cor meum; tenebræ stupefecerunt me: Babylon dilecta mea posita est mihi in miraculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 5, 'Pone mensam, contemplare in specula comedentes et bibentes: surgite, principes, arripite clypeum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 6, 'Hæc enim dixit mihi Dominus: Vade, et pone speculatorem, et quodcumque viderit annuntiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 7, 'Et vidit currum duorum equitum, ascensorem asini, et ascensorem cameli; et contemplatus est diligenter multo intuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 8, 'Et clamavit leo: Super speculam Domini ego sum, stans jugiter per diem; et super custodiam meam ego sum, stans totis noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 9, 'Ecce iste venit ascensor vir bigæ equitum; et respondit, et dixit: Cecidit, cecidit Babylon, et omnia sculptilia deorum ejus contrita sunt in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 10, 'Tritura mea et filii areæ meæ, quæ audivi a Domino exercituum, Deo Israël, annuntiavi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 11, 'Onus Duma. Ad me clamat ex Seir: Custos, quid de nocte? custos, quid de nocte?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 12, 'Dixit custos: Venit mane et nox; si quæritis, quærite; convertimini, venite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 13, 'Onus in Arabia. In saltu ad vesperam dormietis, in semitis Dedanim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 14, 'Occurrentes sitienti ferte aquam, qui habitatis terram austri; cum panibus occurrite fugienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 15, 'A facie enim gladiorum fugerunt, a facie gladii imminentis, a facie arcus extenti, a facie gravis prælii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 16, 'Quoniam hæc dicit Dominus ad me: Adhuc in uno anno, quasi in anno mercenarii, et auferetur omnis gloria Cedar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 21, 17, 'Et reliquiæ numeri sagittariorum fortium de filiis Cedar imminuentur; Dominus enim Deus Israël locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 1, 'Onus vallis Visionis. Quidnam quoque tibi est, quia ascendisti et tu omnis in tecta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 2, 'Clamoris plena, urbs frequens, civitas exsultans; interfecti tui, non interfecti gladio, nec mortui in bello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 3, 'Cuncti principes tui fugerunt simul dureque ligati sunt; omnes qui inventi sunt vincti sunt pariter; procul fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 4, 'Propterea dixi: Recedite a me: amare flebo; nolite incumbere ut consolemini me super vastitate filiæ populi mei;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 5, 'dies enim interfectionis, et conculcationis, et fletuum, Domino Deo exercituum, in valle Visionis, scrutans murum, et magnificus super montem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 6, 'Et \'lam sumpsit pharetram, currum hominis equitis, et parietem nudavit clypeus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 7, 'Et erunt electæ valles tuæ plenæ quadrigarum, et equites ponent sedes suas in porta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 8, 'Et revelabitur operimentum Judæ, et videbis in die illa armamentarium domus saltus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 9, 'Et scissuras civitatis David videbitis, quia multiplicatæ sunt; et congregastis aquas piscinæ inferioris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 10, 'et domos Jerusalem numerastis, et destruxistis domos ad muniendum murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 11, 'Et lacum fecistis inter duos muros ad aquam piscinæ veteris; et non suspexistis ad eum qui fecerat eam, et operatorem ejus de longe non vidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 12, 'Et vocabit Dominus Deus exercituum in die illa ad fletum, et ad planctum, ad calvitium, et ad cingulum sacci;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 13, 'et ecce gaudium et lætitia, occidere vitulos et jugulare arietes, comedere carnes, et bibere vinum: comedamus et bibamus, cras enim moriemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 14, 'Et revelata est in auribus meis vox Domini exercituum: Si dimittetur iniquitas hæc vobis donec moriamini, dicit Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 15, 'Hæc dicit Dominus Deus exercituum: Vade, ingredere ad eum qui habitat in tabernaculo, ad Sobnam, præpositum templi, et dices ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 16, 'Quid tu hic, aut quasi quis hic? quia excidisti tibi hic sepulchrum, excidisti in excelso memoriale diligenter, in petra tabernaculum tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 17, 'Ecce Dominus asportari te faciet, sicut asportatur gallus gallinaceus; et quasi amictum, sic sublevabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 18, 'Coronas coronabit te tribulatione; quasi pilam mittet te in terram latam et spatiosam; ibi morieris, et ibi erit currus gloriæ tuæ, ignominia domus domini tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 19, 'Et expellam te de statione tua, et de ministerio tuo deponam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 20, 'Et erit in die illa: vocabo servum meum Eliacim, filium Helciæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 21, 'et induam illum tunica tua, et cingulo tuo confortabo eum, et potestatem tuam dabo in manu ejus; et erit quasi pater habitantibus Jerusalem et domui Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 22, 'Et dabo clavem domus David super humerum ejus; et aperiet, et non erit qui claudat; et claudet, et non erit qui aperiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 23, 'Et figam illum paxillum in loco fideli, et erit in solium gloriæ domui patris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 24, 'Et suspendent super eum omnem gloriam domus patris ejus; vasorum diversa genera, omne vas parvulum, a vasis craterarum usque ad omne vas musicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 22, 25, 'In die illa, dicit Dominus exercituum, auferetur paxillus qui fixus fuerat in loco fideli, et frangetur, et cadet, et peribit quod pependerat in eo, quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 1, 'Onus Tyri. Ululate, naves maris, quia vastata est domus unde venire consueverant: de terra Cethim revelatum est eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 2, 'Tacete, qui habitatis in insula; negotiatores Sidonis, transfretantes mare, repleverunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 3, 'In aquis multis semen Nili; messis fluminis fruges ejus: et facta est negotiatio gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 4, 'Erubesce, Sidon; ait enim mare, fortitudo maris, dicens: Non parturivi, et non peperi, et non enutrivi juvenes, nec ad incrementum perduxi virgines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 5, 'Cum auditum fuerit in \'gypto, dolebunt cum audierint de Tiro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 6, 'Transite maria, ululate, qui habitatis in insula!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 7, 'Numquid non vestra hæc est, quæ gloriabatur a diebus pristinis in antiquitate sua? Ducent eam pedes sui longe ad peregrinandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 8, 'Quis cogitavit hoc super Tyrum quondam coronatam, cujus negotiatores principes, institores ejus inclyti terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 9, 'Dominus exercituum cogitavit hoc, ut detraheret superbiam omnis gloriæ, et ad ignominiam deduceret universos inclytos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 10, 'Transi terram tuam quasi flumen, filia maris! non est cingulum ultra tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 11, 'Manum suam extendit super mare; conturbavit regna. Dominus mandavit adversus Chanaan, ut contereret fortes ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 12, 'et dixit: Non adjicies ultra ut glorieris, calumniam sustinens virgo filia Sidonis: in Cethim consurgens transfreta: ibi quoque non erit requies tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 13, 'Ecce terra Chaldæorum, talis populus non fuit: Assur fundavit eam; in captivitatem traduxerunt robustos ejus, suffoderunt domos ejus, posuerunt eam in ruinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 14, 'Ululate, naves maris, quia devastata est fortitudo vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 15, 'Et erit in die illa: in oblivione eris, o Tyre! septuaginta annis, sicut dies regis unius; post septuaginta autem annos erit Tyro quasi canticum meretricis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 16, 'Sume citharam, circui civitatem, meretrix oblivioni tradita: bene cane, frequenta canticum, ut memoria tui sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 17, 'Et erit post septuaginta annos: visitabit Dominus Tyrum, et reducet eam ad mercedes suas, et rursum fornicabitur cum universis regnis terræ super faciem terræ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 23, 18, 'et erunt negotiationes ejus et mercedes ejus sanctificatæ Domino: non condentur neque reponentur, quia his qui habitaverint coram Domino erit negotiatio ejus, ut manducent in saturitatem, et vestiantur usque ad vetustatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 1, 'Ecce Dominus dissipabit terram: et nudabit eam, et affliget faciem ejus, et disperget habitatores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 2, 'Et erit sicut populus, sic sacerdos; et sicut servus, sic dominus ejus; sicut ancilla, sic domina ejus; sicut emens, sic ille qui vendit; sicut fœnerator, sic is qui mutuum accipit; sicut qui repetit, sic qui debet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 3, 'Dissipatione dissipabitur terra, et direptione prædabitur; Dominus enim locutus est verbum hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 4, 'Luxit, et defluxit terra, et infirmata est; defluxit orbis, infirmata est altitudo populi terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 5, 'Et terra infecta est ab habitatoribus suis, quia transgressi sunt leges, mutaverunt jus, dissipaverunt fœdus sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 6, 'Propter hoc maledictio vorabit terram, et peccabunt habitatores ejus; ideoque insanient cultores ejus, et relinquentur homines pauci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 7, 'Luxit vindemia, infirmata est vitis, ingemuerunt omnes qui lætabantur corde;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 8, 'cessavit gaudium tympanorum, quievit sonitus lætantium, conticuit dulcedo citharæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 9, 'Cum cantico non bibent vinum; amara erit potio bibentibus illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 10, 'Attrita est civitas vanitatis, clausa est omnis domus, nullo introëunte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 11, 'Clamor erit super vino in plateis, deserta est omnia lætitia, translatum est gaudium terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 12, 'Relicta est in urbe solitudo, et calamitas opprimet portas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 13, 'Quia hæc erunt in medio terræ in medio populorum, quomodo si paucæ olivæ quæ remanserunt excutiantur ex olea et racemi, cum fuerit finita vindemia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 14, 'Hi levabunt vocem suam, atque laudabunt: cum glorificatus fuerit Dominus, hinnient de mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 15, 'Propter hoc in doctrinis glorificate Dominum; in insulis maris nomen Domini Dei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 16, 'A finibus terræ laudes audivimus, gloriam Justi. Et dixi: Secretum meum mihi, secretum meum mihi. Væ mihi! prævaricantes prævaricati sunt, et prævaricatione transgressorum prævaricati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 17, 'Formido, et fovea, et laqueus super te, qui habitator es terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 18, 'Et erit: qui fugerit a voce formidinis cadet in foveam; et qui se explicaverit de fovea tenebitur laqueo; quia cataractæ de excelsis apertæ sunt et concutientur fundamenta terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 19, 'Confractione confringetur terra, contritione conteretur terra, commotione commovebitur terra;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 20, 'agitatione agitabitur terra sicut ebrius, et auferetur quasi tabernaculum unius noctis; et gravabit eam iniquitas sua, et corruet, et non adjiciet ut resurgat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 21, 'Et erit: in die illa visitabit Dominus super militiam cæli in excelso, et super reges terræ qui sunt super terram;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 22, 'et congregabuntur in congregatione unius fascis in lacum, et claudentur ibi in carcere, et post multos dies visitabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 24, 23, 'Et erubescet luna, et confundetur sol, cum regnaverit Dominus exercituum in monte Sion et in Jerusalem et in conspectu senum suorum fuerit glorificatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 1, 'Domine, Deus meus es tu; exaltabo te, et confitebor nomini tuo: quoniam fecisti mirabilia, cogitationes antiquas fideles. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 2, 'Quia posuisti civitatem in tumulum, urbem fortem in ruinam, domum alienorum: ut non sit civitas, et in sempiternum non ædificetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 3, 'Super hoc laudabit te populus fortis; civitas gentium robustarum timebit te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 4, 'quia factus es fortitudo pauperi, fortitudo egeno in tribulatione sua, spes a turbine, umbraculum ab æstu; spiritus enim robustorum quasi turbo impellens parietem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 5, 'Sicut æstus in siti, tumultum alienorum humiliabis; et quasi calore sub nube torrente, propaginem fortium marcescere facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 6, 'Et faciet Dominus exercituum omnibus populis in monte hoc convivium pinguium, convivium vindemiæ, pinguium medullatorum, vindemiæ defæcatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 7, 'Et præcipitabit in monte isto faciem vinculi colligati super omnes populos, et telam quam orditus est super omnes nationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 8, 'Præcipitabit mortem in sempiternum; et auferet Dominus Deus lacrimam ab omni facie, et opprobrium populi sui auferet de universa terra: quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 9, 'Et dicet in die illa: Ecce Deus noster iste; exspectavimus eum, et salvabit nos; iste Dominus, sustinuimus eum: exsultabimus, et lætabimur in salutari ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 10, 'Quia requiescet manus Domini in monte isto; et triturabitur Moab sub eo, sicuti teruntur paleæ in plaustro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 11, 'Et extendet manus suas sub eo sicut extendit natans ad natandum; et humiliabit gloriam ejus cum allisione manuum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 25, 12, 'Et munimenta sublimium murorum tuorum concident, et humiliabuntur, et detrahentur in terram usque ad pulverem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 1, 'In die illa cantabitur canticum istud in terra Juda: Urbs fortitudinis nostræ Sion; salvator ponetur in ea murus et antemurale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 2, 'Aperite portas, et ingrediatur gens justa, custodiens veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 3, 'Vetus error abiit: servabis pacem; pacem, quia in te speravimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 4, 'Sperastis in Domino in sæculis æternis; in Domino Deo forti in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 5, 'Quia incurvabit habitantes in excelso; civitatem sublimem humiliabit: humiliabit eam usque ad terram, detrahet eam usque ad pulverem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 6, 'Conculcabit eam pes, pedes pauperis, gressus egenorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 7, 'Semita justi recta est, rectus callis justi ad ambulandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 8, 'Et in semita judiciorum tuorum, Domine, sustinuimus te: nomen tuum et memoriale tuum in desiderio animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 9, 'Anima mea desideravit te in nocte, sed et spiritu meo in præcordiis meis de mane vigilabo ad te. Cum feceris judicia tua in terra, justitiam discent habitatores orbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 10, 'Misereamur impio, et non discet justitiam; in terra sanctorum iniqua gessit, et non videbit gloriam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 11, 'Domine, exaltetur manus tua, et non videant; videant, et confundantur zelantes populi; et ignis hostes tuos devoret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 12, 'Domine, dabis pacem nobis: omnia enim opera nostra operatus es nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 13, 'Domine Deus noster, possederunt nos domini absque te; tantum in te recordemur nominis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 14, 'Morientes non vivant, gigantes non resurgant: propterea visitasti et contrivisti eos, et perdidisti omnem memoriam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 15, 'Indulsisti genti, Domine, indulsisti genti, numquid glorificatus es? elongasti omnes terminos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 16, 'Domine, in angustia requisierunt te, in tribulatione murmuris doctrina tua eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 17, 'Sicut quæ concipit, cum appropinquaverit ad partum, dolens clamat in doloribus suis, sic facti sumus a facie tua, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 18, 'Concepimus, et quasi parturivimus, et peperimus spiritum. Salutes non fecimus in terra; ideo non ceciderunt habitatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 19, 'Vivent mortui tui, interfecti mei resurgent. Expergiscimini, et laudate, qui habitatis in pulvere, quia ros lucis ros tuus, et terram gigantum detrahes in ruinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 20, 'Vade, populus meus, intra in cubicula tua; claude ostia tua super te, abscondere modicum ad momentum, donec pertranseat indignatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 26, 21, 'Ecce enim Dominus egredietur de loco suo, ut visitet iniquitatem habitatoris terræ contra eum; et revelabit terra sanguinem suum, et non operiet ultra interfectos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 1, 'In die illa visitabit Dominus in gladio suo duro, et grandi, et forti, super Leviathan, serpentem vectem, et super Leviathan, serpentem tortuosum, et occidet cetum qui in mari est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 2, 'In die illa vinea meri cantabit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 3, 'Ego Dominus qui servo eam; repente propinabo ei. Ne forte visitetur contra eam, nocte et die servo eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 4, 'Indignatio non est mihi. Quis dabit me spinam et veprem in prælio? gradiar super eam, succendam eam pariter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 5, 'An potius tenebit fortitudinem meam? faciet pacem mihi, pacem faciet mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 6, 'Qui ingrediuntur impetu ad Jacob, florebit et germinabit Israël, et implebunt faciem orbis semine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 7, 'Numquid juxta plagam percutientis se percussit eum? aut sicut occidit interfectos ejus, sic occisus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 8, 'In mensura contra mensuram, cum abjecta fuerit, judicabis eam; meditatus est in spiritu suo duro per diem æstus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 9, 'Idcirco super hoc dimittetur iniquitas domui Jacob; et iste omnis fructus: ut auferatur peccatum ejus, cum posuerit omnes lapides altaris sicut lapides cineris allisos: non stabunt luci et delubra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 10, 'Civitas enim munita desolata erit; speciosa relinquetur, et dimittetur quasi desertum; ibi pascetur vitulus, et ibi accubabit, et consumet summitates ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 11, 'In siccitate messes illius conterentur. Mulieres venientes, et docentes eam; non est enim populus sapiens: propterea non miserebitur ejus qui fecit eum, et qui formavit eum non parcet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 12, 'Et erit: in die illa percutiet Dominus ab alveo fluminis usque ad torrentem \'gypti; et vos congregabimini unus et unus, filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 27, 13, 'Et erit: in die illa clangetur in tuba magna; et venient qui perditi fuerant de terra Assyriorum, et qui ejecti erant in terra \'gypti, et adorabunt Dominum in monte sancto in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 1, 'Væ coronæ superbiæ, ebriis Ephraim, et flori decidenti, gloriæ exsultationis ejus, qui erant in vertice vallis pinguissimæ, errantes a vino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 2, 'Ecce validus et fortis Dominus sicut impetus grandinis; turbo confringens, sicut impetus aquarum multarum inundantium et emissarum super terram spatiosam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 3, 'Pedibus conculcabitur corona superbiæ ebriorum Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 4, 'Et erit flos decidens gloriæ exsultationis ejus, qui est super verticem vallis pinguium, quasi temporaneum ante maturitatem autumni, quod, cum aspexerit videns, statim ut manu tenuerit, devorabit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 5, 'In die illa erit Dominus exercituum corona gloriæ, et sertum exsultationis residuo populi sui;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 6, 'et spiritus judicii sedenti super judicium, et fortitudo revertentibus de bello ad portam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 7, 'Verum hi quoque præ vino nescierunt, et præ ebrietate erraverunt; sacerdos et propheta nescierunt præ ebrietate; absorpti sunt a vino, erraverunt in ebrietate, nescierunt videntem, ignoraverunt judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 8, 'Omnes enim mensæ repletæ sunt vomitu sordiumque, ita ut non esset ultra locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 9, 'Quem docebit scientiam? et quem intelligere faciet auditum? Ablactatos a lacte, avulsos ab uberibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 10, 'Quia manda, remanda; manda, remanda; exspecta, reexspecta; exspecta, reexspecta; modicum ibi, modicum ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 11, 'In loquela enim labii, et lingua altera loquetur ad populum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 12, 'Cui dixit: Hæc est requies mea, reficite lassum; et hoc est meum refrigerium: et noluerunt audire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 13, 'Et erit eis verbum Domini: Manda, remanda; manda, remanda; exspecta, reexspecta; exspecta, reexspecta; modicum ibi, modicum ibi; ut vadant, et cadant retrorsum, et conterantur, et illaqueentur, et capiantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 14, 'Propter hoc audite verbum Domini, viri illusores, qui dominamini super populum meum, qui est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 15, 'Dixistis enim: Percussimus fœdus cum morte, et cum inferno fecimus pactum: flagellum inundans cum transierit, non veniet super nos quia posuimus mendacium spem nostram, et mendacio protecti sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 16, 'Idcirco hæc dicit Dominus Deus: Ecce ego mittam in fundamentis Sion lapidem, lapidem probatum, angularem, pretiosum, in fundamento fundatum; qui crediderit, non festinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 17, 'Et ponam in pondere judicium, et justitiam in mensura; et subvertet grando spem mendacii, et protectionem aquæ inundabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 18, 'Et delebitur fœdus vestrum cum morte, et pactum vestrum cum inferno non stabit: flagellum inundans cum transierit, eritis ei in conculcationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 19, 'Quandocumque pertransierit, tollet vos, quoniam in mane diluculo pertransibit in die et in nocte; et tantummodo sola vexatio intellectum dabit auditui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 20, 'Coangustatum est enim stratum, ita ut alter decidat; et pallium breve utrumque operire non potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 21, 'Sicut enim in monte divisionum stabit Dominus; sicut in valle quæ est in Gabaon irascetur, ut faciat opus suum, alienum opus ejus: ut operetur opus suum, peregrinum est opus ejus ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 22, 'Et nunc nolite illudere, ne forte constringantur vincula vestra; consummationem enim et abbreviationem audivi a Domino Deo exercituum, super universam terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 23, 'Auribus percipite, et audite vocem meam: attendite, et audite eloquium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 24, 'Numquid tota die arabit arans ut serat? proscindet et sarriet humum suam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 25, 'Nonne cum adæquaverit faciem ejus, seret gith et cyminum sparget? et ponet triticum per ordinem, et hordeum, et milium, et viciam in finibus suis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 26, 'Et erudiet illum in judicio; Deus suus docebit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 27, 'Non enim in serris triturabitur gith, nec rota plaustri super cyminum circuibit; sed in virga excutietur gith, et cyminum in baculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 28, 'Panis autem comminuetur; verum non in perpetuum triturans triturabit illum, neque vexabit eum rota plaustri, neque ungulis suis comminuet eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 28, 29, 'Et hoc a Domino Deo exercituum exivit, ut mirabile faceret consilium, et magnificaret justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 1, 'Væ Ariel, Ariel civitas, quam expugnavit David! additus est annus ad annum: solemnitates evolutæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 2, 'Et circumvallabo Ariel, et erit tristis et mœrens, et erit mihi quasi Ariel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 3, 'Et circumdabo quasi sphæram in circuitu tuo, et jaciam contra te aggerem, et munimenta ponam in obsidionem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 4, 'Humiliaberis, de terra loqueris, et de humo audietur eloquium tuum; et erit quasi pythonis de terra vox tua, et de humo eloquium tuum mussitabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 5, 'Et erit sicut pulvis tenuis multitudo ventilantium te, et sicut favilla pertransiens multitudo eorum qui contra te prævaluerunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 6, 'eritque repente confestim. A Domino exercituum visitabitur in tonitruo, et commotione terræ, et voce magna turbinis et tempestatis, et flammæ ignis devorantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 7, 'Et erit sicut somnium visionis nocturnæ multitudo omnium gentium quæ dimicaverunt contra Ariel, et omnes qui militaverunt, et obsederunt, et prævaluerunt adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 8, 'Et sicut somniat esuriens, et comedit, cum autem fuerit expergefactus, vacua est anima ejus; et sicut somniat sitiens et bibit, et postquam fuerit expergefactus, lassus adhuc sitit, et anima ejus vacua est: sic erit multitudo omnium gentium quæ dimicaverunt contra montem Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 9, 'Obstupescite et admiramini; fluctuate et vacillate; inebriamini, et non a vino; movemini, et non ab ebrietate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 10, 'Quoniam miscuit vobis Dominus spiritum soporis; claudet oculos vestros: prophetas et principes vestros, qui vident visiones, operiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 11, 'Et erit vobis visio omnium sicut verba libri signati, quem cum dederint scienti litteras, dicent: Lege istum: et respondebit: Non possum, signatus est enim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 12, 'Et dabitur liber nescienti litteras, diceturque ei: Lege; et respondebit: Nescio litteras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 13, 'Et dixit Dominus: Eo quod appropinquat populus iste ore suo, et labiis suis glorificat me, cor autem ejus longe est a me, et timuerunt me mandato hominum et doctrinis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 14, 'ideo ecce ego addam ut admirationem faciam populo huic miraculo grandi et stupendo; peribit enim sapientia a sapientibus ejus, et intellectus prudentium ejus abscondetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 15, 'Væ qui profundi estis corde, ut a Domino abscondatis consilium; quorum sunt in tenebris opera, et dicunt: Quis videt nos? et quis novit nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 16, 'Perversa est hæc vestra cogitatio; quasi si lutum contra figulum cogitet, et dicat opus factori suo: Non fecisti me; et figmentum dicat fictori suo: Non intelligis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 17, 'Nonne adhuc in modico et in brevi convertetur Libanus in carmel, et carmel in saltum reputabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 18, 'Et audient in die illa surdi verba libri, et de tenebris et caligine oculi cæcorum videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 19, 'Et addent mites in Domino lætitiam, et pauperes homines in Sancto Israël exsultabunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 20, 'quoniam defecit qui prævalebat, consummatus est illusor, et succisi sunt omnes qui vigilabant super iniquitatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 21, 'qui peccare faciebant homines in verbo, et arguentem in porta supplantabant, et declinaverunt frustra a justo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 22, 'Propter hoc, hæc dicit Dominus ad domum Jacob, qui redemit Abraham: Non modo confundetur Jacob, nec modo vultus ejus erubescet;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 23, 'sed cum viderit filios suos, opera manuum mearum in medio sui sanctificantes nomen meum, et sanctificabunt Sanctum Jacob, et Deum Israël prædicabunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 29, 24, 'et scient errantes spiritu intellectum, et mussitatores discent legem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 1, 'Væ filii desertores, dicit Dominus, ut faceretis consilium, et non ex me, et ordiremini telam, et non per spiritum meum, ut adderetis peccatum super peccatum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 2, 'qui ambulatis ut descendatis in \'gyptum, et os meum non interrogastis, sperantes auxilium in fortitudine Pharaonis, et habentes fiduciam in umbra \'gypti!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 3, 'Et erit vobis fortitudo Pharaonis in confusionem, et fiducia umbræ \'gypti in ignominiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 4, 'Erant enim in Tani principes tui, et nuntii tui usque ad Hanes pervenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 5, 'Omnes confusi sunt super populo qui eis prodesse non potuit: non fuerunt in auxilium et in aliquam utilitatem, sed in confusionem et in opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 6, 'Onus jumentorum austri. In terra tribulationis et angustiæ leæna, et leo ex eis, vipera et regulus volans; portantes super humeros jumentorum divitias suas, et super gibbum camelorum thesauros suos, ad populum qui eis prodesse non poterit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 7, '\'gyptus enim frustra et vane auxiliabitur. Ideo clamavi super hoc: Superbia tantum est, quiesce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 8, 'Nunc ergo ingressus, scribe ei super buxum, et in libro diligenter exara illud, et erit in die novissimo in testimonium usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 9, 'Populus enim ad iracundiam provocans est: et filii mendaces, filii nolentes audire legem Dei;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 10, 'qui dicunt videntibus: Nolite videre, et aspicientibus: Nolite aspicere nobis ea quæ recta sunt; loquimini nobis placentia: videte nobis errores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 11, 'Auferte a me viam; declinate a me semitam; cesset a facie nostra Sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 12, 'Propterea hæc dicit Sanctus Israël: Pro eo quod reprobastis verbum hoc, et sperastis in calumnia et in tumultu, et innixi estis super eo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 13, 'propterea erit vobis iniquitas hæc sicut interruptio cadens, et requisita in muro excelso, quoniam subito, dum non speratur, veniet contritio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 14, 'Et comminuetur sicut conteritur lagena figuli contritione pervalida, et non invenietur de fragmentis ejus testa in qua portetur igniculus de incendio, aut hauriatur parum aquæ de fovea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 15, 'Quia hæc dicit Dominus Deus, Sanctus Israël: Si revertamini et quiescatis, salvi eritis; in silentio et in spe erit fortitudo vestra. Et noluistis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 16, 'et dixistis: Nequaquam, sed ad equos fugiemus: ideo fugietis; et: Super veloces ascendemus: ideo velociores erunt qui persequentur vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 17, 'Mille homines a facie terroris unius; et a facie terroris quinque fugietis, donec relinquamini quasi malus navis in vertice montis, et quasi signum super collem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 18, 'Propterea exspectat Dominus ut misereatur vestri; et ideo exaltabitur parcens vobis, quia Deus judicii Dominus: beati omnes qui exspectant eum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 19, 'Populus enim Sion habitabit in Jerusalem: plorans nequaquam plorabis: miserans miserebitur tui, ad vocem clamoris tui: statim ut audierit, respondebit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 20, 'Et dabit vobis Dominus panem arctum, et aquam brevem; et non faciet avolare a te ultra doctorem tuum; et erunt oculi tui videntes præceptorem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 21, 'Et aures tuæ audient verbum post tergum monentis: Hæc est via; ambulate in ea, et non declinetis neque ad dexteram, neque ad sinistram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 22, 'Et contaminabis laminas sculptilium argenti tui, et vestimentum conflatilis auri tui, et disperges ea sicut immunditiam menstruatæ. Egredere, dices ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 23, 'Et dabitur pluvia semini tuo, ubicumque seminaveris in terra, et panis frugum terræ erit uberrimus et pinguis; pascetur in possessione tua in die illo agnus spatiose,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 24, 'et tauri tui, et pulli asinorum, qui operantur terram, commistum migma comedent sicut in area ventilatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 25, 'Et erunt super omnem montem excelsum, et super omnem collem elevatum, rivi currentium aquarum, in die interfectionis multorum, cum ceciderint turres:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 26, 'et erit lux lunæ sicut lux solis, et lux solis erit septempliciter sicut lux septem dierum, in die qua alligaverit Dominus vulnus populi sui, et percussuram plagæ ejus sanaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 27, 'Ecce nomen Domini venit de longinquo, ardens furor ejus, et gravis ad portandum; labia ejus repleta sunt indignatione, et lingua ejus quasi ignis devorans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 28, 'Spiritus ejus velut torrens inundans usque ad medium colli, ad perdendas gentes in nihilum, et frenum erroris quod erat in maxillis populorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 29, 'Canticum erit vobis sicut nox sanctificatæ solemnitatis, et lætitia cordis sicut qui pergit cum tibia, ut intret in montem Domini ad Fortem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 30, 'Et auditam faciet Dominus gloriam vocis suæ, et terrorem brachii sui ostendet in comminatione furoris, et flamma ignis devorantis: allidet in turbine, et in lapide grandinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 31, 'A voce enim Domini pavebit Assur virga percussus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 32, 'Et erit transitus virgæ fundatus, quam requiescere faciet Dominus super eum in tympanis et citharis; et in bellis præcipuis expugnabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 30, 33, 'Præparata est enim ab heri Topheth, a rege præparata, profunda, et dilatata. Nutrimenta ejus, ignis et ligna multa; flatus Domini sicut torrens sulphuris succendens eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 1, 'Væ qui descendunt in \'gyptum ad auxilium, in equis sperantes, et habentes fiduciam super quadrigis, quia multæ sunt; et super equitibus, quia prævalidi nimis; et non sunt confisi super Sanctum Israël, et Dominum non requisierunt!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 2, 'Ipse autem sapiens adduxit malum, et verba sua non abstulit; et consurget contra domum pessimorum, et contra auxilium operantium iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 3, '\'gyptus homo, et non deus; et equi eorum caro, et non spiritus; et Dominus inclinabit manum suam, et corruet auxiliator, et cadet cui præstatur auxilium, simulque omnes consumentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 4, 'Quia hæc dicit Dominus ad me: Quomodo si rugiat leo et catulus leonis super prædam suam; et cum occurrerit ei multitudo pastorum, a voce eorum non formidabit, et a multitudine eorum non pavebit: sic descendet Dominus exercituum ut prælietur super montem Sion et super collem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 5, 'Sicut aves volantes, sic proteget Dominus exercituum Jerusalem, protegens et liberans, transiens et salvans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 6, 'Convertimini, sicut in profundum recesseratis, filii Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 7, 'In die enim illa abjiciet vir idola argenti sui, et idola auri sui, quæ fecerunt vobis manus vestræ in peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 8, 'Et cadet Assur in gladio non viri, et gladius non hominis vorabit eum: et fugiet non a facie gladii, et juvenes ejus vectigales erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 31, 9, 'Et fortitudo ejus a terrore transibit, et pavebunt fugientes principes ejus, dixit Dominus: cujus ignis est in Sion et caminus ejus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 1, 'Ecce in justitia regnabit rex, et principes in judicio præerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 2, 'Et erit vir sicut qui absconditur a vento, et celat se a tempestate; sicut rivi aquarum in siti, et umbra petræ prominentis in terra deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 3, 'Non caligabunt oculi videntium, et aures audientium diligenter auscultabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 4, 'Et cor stultorum intelliget scientiam, et lingua balborum velociter loquetur et plane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 5, 'Non vocabitur ultra is qui insipiens est, princeps, neque fraudulentus appellabitur major;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 6, 'stultus enim fatua loquetur, et cor ejus faciet iniquitatem, ut perficiat simulationem, et loquatur ad Dominum fraudulenter, et vacuam faciat animam esurientis, et potum sitienti auferat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 7, 'Fraudulenti vasa pessima sunt; ipse enim cogitationes concinnavit ad perdendos mites in sermone mendacii, cum loqueretur pauper judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 8, 'Princeps vero ea quæ digna sunt principe cogitabit, et ipse super duces stabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 9, 'Mulieres opulentæ, surgite, et audite vocem meam; filiæ confidentes, percipite auribus eloquium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 10, 'Post dies enim et annum, vos conturbabimini confidentes; consummata est enim vindemia, collectio ultra non veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 11, 'Obstupescite, opulentæ; conturbamini, confidentes: exuite vos et confundimini; accingite lumbos vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 12, 'Super ubera plangite, super regione desiderabili, super vinea fertili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 13, 'Super humum populi mei spinæ et vepres ascendent: quanto magis super omnes domos gaudii civitatis exultantis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 14, 'Domus enim dimissa est, multitudo urbis relicta est, tenebræ et palpatio factæ sunt super speluncas usque in æternum; gaudium onagrorum, pascua gregum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 15, 'Donec effundatur super nos spiritus de excelso, et erit desertum in carmel, et carmel in saltum reputabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 16, 'Et habitabit in solitudine judicium, et justitia in carmel sedebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 17, 'Et erit opus justitiæ pax, et cultus justitiæ silentium, et securitas usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 18, 'Et sedebit populus meus in pulchritudine pacis, et in tabernaculis fiduciæ, et in requie opulenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 19, 'Grando autem in descensione saltus, et humilitate humiliabitur civitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 32, 20, 'Beati qui seminatis super omnes aquas, immittentes pedem bovis et asini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 1, 'Væ qui prædaris! nonne et ipse prædaberis? et qui spernis, nonne et ipse sperneris? Cum consummaveris deprædationem, deprædaberis; cum fatigatus desieris contemnere, contemneris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 2, 'Domine, miserere nostri, te enim exspectavimus; esto brachium nostrum in mane, et salus nostra in tempore tribulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 3, 'A voce angeli fugerunt populi, et ab exaltatione tua dispersæ sunt gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 4, 'Et congregabuntur spolia vestra sicut colligitur bruchus, velut cum fossæ plenæ fuerint de eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 5, 'Magnificatus est Dominus, quoniam habitavit in excelso; implevit Sion judicio et justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 6, 'Et erit fides in temporibus tuis: divitiæ salutis sapientia et scientia; timor Domini ipse est thesaurus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 7, 'Ecce videntes clamabunt foris; angeli pacis amare flebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 8, 'Dissipatæ sunt viæ, cessavit transiens per semitam: irritum factum est pactum, projecit civitates, non reputavit homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 9, 'Luxit et elanguit terra; confusus est Libanus, et obsorduit: et factus est Saron sicut desertum, et concussa est Basan, et Carmelus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 10, 'Nunc consurgam, dicit Dominus; nunc exaltabor, nunc sublevabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 11, 'Concipietis ardorem, parietis stipulam; spiritus vester ut ignis vorabit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 12, 'Et erunt populi quasi de incendio cinis; spinæ congregatæ igni comburentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 13, 'Audite, qui longe estis, quæ fecerim; et cognoscite, vicini, fortitudinem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 14, 'Conterriti sunt in Sion peccatores; possedit tremor hypocritas. Quis poterit habitare de vobis cum igne devorante? quis habitabit ex vobis cum ardoribus sempiternis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 15, 'Qui ambulat in justitiis et loquitur veritatem, qui projicit avaritiam ex calumnia, et excutit manus suas ab omni munere, qui obturat aures suas ne audiat sanguinem, et claudit oculos suos ne videat malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 16, 'Iste in excelsis habitabit; munimenta saxorum sublimitas ejus: panis ei datus est, aquæ ejus fideles sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 17, 'Regem in decore suo videbunt oculi ejus, cernent terram de longe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 18, 'Cor tuum meditabitur timorem: ubi est litteratus? ubi legis verba ponderans? ubi doctor parvulorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 19, 'Populum impudentem non videbis, populum alti sermonis, ita ut non possis intelligere disertitudinem linguæ ejus, in quo nulla est sapientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 20, 'Respice, Sion, civitatem solemnitatis nostræ: oculi tui videbunt Jerusalem, habitationem opulentam, tabernaculum quod nequaquam transferri poterit; nec auferentur clavi ejus in sempiternum, et omnes funiculi ejus non rumpentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 21, 'quia solummodo ibi magnificus est Dominus noster: locus fluviorum rivi latissimi et patentes: non transibit per eum navis remigum, neque trieris magna transgredietur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 22, 'Dominus enim judex noster, Dominus legifer noster, Dominus rex noster, ipse salvabit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 23, 'Laxati sunt funiculi tui, et non prævalebunt; sic erit malus tuus ut dilatare signum non queas. Tunc dividentur spolia prædarum multarum; claudi diripient rapinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 33, 24, 'Nec dicet vicinus: Elangui; populus qui habitat in ea, auferetur ab eo iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 1, 'Accedite, gentes, et audite; et populi, attendite: audiat terra, et plenitudo ejus; orbis, et omne germen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 2, 'Quia indignatio Domini super omnes gentes, et furor super universam militiam eorum: interfecit eos, et dedit eos in occisionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 3, 'Interfecti eorum projicientur, et de cadaveribus eorum ascendet fœtor; tabescent montes a sanguine eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 4, 'Et tabescet omnis militia cælorum, et complicabuntur sicut liber cæli: et omnis militia eorum defluet, sicut defluit folium de vinea et de ficu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 5, 'Quoniam inebriatus est in cælo gladius meus; ecce super Idumæam descendet, et super populum interfectionis meæ, ad judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 6, 'Gladius Domini repletus est sanguine, incrassatus est adipe, de sanguine agnorum et hircorum, de sanguine medullatorum arietum: victima enim Domini in Bosra, et interfectio magna in terra Edom.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 7, 'Et descendent unicornes cum eis, et tauri cum potentibus; inebriabitur terra eorum sanguine, et humus eorum adipe pinguium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 8, 'Quia dies ultionis Domini, annus retributionum judicii Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 9, 'Et convertentur torrentes ejus in picem, et humus ejus in sulphur; et erit terra ejus in picem ardentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 10, 'Nocte et die non extinguetur, in sempiternum ascendet fumus ejus, a generatione in generationem desolabitur, in sæcula sæculorum non erit transiens per eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 11, 'Et possidebunt illam onocrotalus et ericius; ibis et corvus habitabunt in ea: et extendetur super eam mensura, ut redigatur ad nihilum, et perpendiculum in desolationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 12, 'Nobiles ejus non erunt ibi; regem potius invocabunt, et omnes principes ejus erunt in nihilum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 13, 'Et orientur in domibus ejus spinæ et urticæ, et paliurus in munitionibus ejus; et erit cubile draconum, et pascua struthionum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 14, 'Et occurrent dæmonia onocentauris, et pilosus clamabit alter ad alterum; ibi cubavit lamia, et invenit sibi requiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 15, 'Ibi habuit foveam ericius, et enutrivit catulos, et circumfodit, et fovit in umbra ejus; illuc congregati sunt milvi, alter ad alterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 16, 'Requirite diligenter in libro Domini, et legite: Unum ex eis non defuit, alter alterum non quæsivit; quia quod ex ore meo procedit, ille mandavit, et spiritus ejus ipse congregavit ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 34, 17, 'Et ipse misit eis sortem, et manus ejus divisit eam illis in mensuram: usque in æternum possidebunt eam; in generationem et generationem habitabunt in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 1, 'Lætabitur deserta et invia, et exsultabit solitudo, et florebit quasi lilium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 2, 'Germinans germinabit, et exsultabit lætabunda et laudans: gloria Libani data est ei, decor Carmeli et Saron; ipsi videbunt gloriam Domini, et decorem Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 3, 'Confortate manus dissolutas, et genua debilia roborate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 4, 'Dicite pusillanimis: Confortamini, et nolite timere: ecce Deus vester ultionem adducet retributionis; Deus ipse veniet, et salvabit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 5, 'Tunc aperientur oculi cæcorum, et aures surdorum patebunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 6, 'tunc saliet sicut cervus claudus, et aperta erit lingua mutorum: quia scissæ sunt in deserto aquæ, et torrentes in solitudine;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 7, 'et quæ erat arida, erit in stagnum, et sitiens in fontes aquarum. In cubilibus, in quibus prius dracones habitabant, orietur viror calami et junci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 8, 'Et erit ibi semita et via, et via sancta vocabitur: non transibit per eam pollutus, et hæc erit vobis directa via, ita ut stulti non errent per eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 9, 'Non erit ibi leo, et mala bestia non ascendet per eam, nec invenietur ibi; et ambulabunt qui liberati fuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 35, 10, 'Et redempti a Domino convertentur, et venient in Sion cum laude, et lætitia sempiterna super caput eorum: gaudium et lætitiam obtinebunt, et fugiet dolor et gemitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 1, 'Et factum est in quartodecimo anno regis Ezechiæ, ascendit Sennacherib, rex Assyriorum, super omnes civitates Juda munitas, et cepit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 2, 'Et misit rex Assyriorum Rabsacen de Lachis in Jerusalem, ad regem Ezechiam in manu gravi: et stetit in aquæductu piscinæ superioris in via Agri fullonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 3, 'Et egressus est ad eum Eliacim, filius Helciæ, qui erat super domum, et Sobna scriba, et Joahe filius Asaph, a commentariis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 4, 'Et dixit ad eos Rabsaces: Dicite Ezechiæ: Hæc dicit rex magnus, rex Assyriorum: Quæ est ista fiducia qua confidis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 5, 'aut quo consilio vel fortitudine rebellare disponis? super quem habes fiduciam, quia recessisti a me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 6, 'Ecce confidis super baculum arundineum confractum istum, super \'gyptum; cui si innixus fuerit homo, intrabit in manum ejus, et perforabit eam: sic Pharao, rex \'gypti, omnibus qui confidunt in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 7, 'Quod si responderis mihi: In Domino Deo nostro confidimus; nonne ipse est cujus abstulit Ezechias excelsa et altaria, et dixit Judæ et Jerusalem: Coram altari isto adorabitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 8, 'Et nunc trade te domino meo, regi Assyriorum, et dabo tibi duo millia equorum, nec poteris ex te præbere ascensores eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 9, 'et quomodo sustinebis faciem judicis unius loci ex servis domini mei minoribus? Quod si confidis in \'gypto, in quadrigis et in equitibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 10, 'et nunc numquid sine Domino ascendi ad terram istam, ut disperderem eam? Dominus dixit ad me: Ascende super terram istam, et disperde eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 11, 'Et dixit Eliacim, et Sobna, et Joahe, ad Rabsacen: Loquere ad servos tuos syra lingua; intelligimus enim; ne loquaris ad nos judaice in auribus populi qui est super murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 12, 'Et dixit ad eos Rabsaces: Numquid ad dominum tuum et ad te misit me dominus meus, ut loquerer omnia verba ista? et non potius ad viros qui sedent in muro, ut comedant stercora sua, et bibant urinam pedum suorum vobiscum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 13, 'Et stetit Rabsaces, et clamavit voce magna judaice, et dixit: Audite verba regis magni, regis Assyriorum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 14, 'Hæc dicit rex: Non seducat vos Ezechias, quia non poterit eruere vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 15, 'Et non vobis tribuat fiduciam Ezechias super Domino, dicens: Eruens liberabit nos Dominus: non dabitur civitas ista in manu regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 16, 'Nolite audire Ezechiam; hæc enim dicit rex Assyriorum: Facite mecum benedictionem, et egredimini ad me, et comedite unusquisque vineam suam, et unusquisque ficum suam, et bibite unusquisque aquam cisternæ suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 17, 'donec veniam, et tollam vos ad terram quæ est ut terra vestra, terram frumenti et vini, terram panum et vinearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 18, 'Nec conturbet vos Ezechias, dicens: Dominus liberabit nos. Numquid liberaverunt dii gentium unusquisque terram suam de manu regis Assyriorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 19, 'Ubi est deus Emath et Arphad? ubi est deus Sepharvaim? numquid liberaverunt Samariam de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 20, 'Quis est ex omnibus diis terrarum istarum qui eruerit terram suam de manu mea, ut eruat Dominus Jerusalem de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 21, 'Et siluerunt, et non responderunt ei verbum. Mandaverat enim rex, dicens: Ne respondeatis ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 36, 22, 'Et ingressus est Eliacim, filius Helciæ, qui erat super domum, et Sobna scriba, et Joahe filius Asaph, a commentariis, ad Ezechiam, scissis vestibus, et nuntiaverunt ei verba Rabsacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 1, 'Et factum est, cum audisset rex Ezechias, scidit vestimenta sua, et obvolutus est sacco, et intravit in domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 2, 'Et misit Eliacim, qui erat super domum, et Sobnam scribam, et seniores de sacerdotibus, opertos saccis, ad Isaiam, filium Amos, prophetam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 3, 'et dixerunt ad eum: Hæc dicit Ezechias: Dies tribulationis, et correptionis, et blasphemiæ, dies hæc; quia venerunt filii usque ad partum, et virtus non est pariendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 4, 'Si quomodo audiat Dominus Deus tuus verba Rabsacis, quem misit rex Assyriorum dominus suus ad blasphemandum Deum viventem et exprobrandum sermonibus quos audivit Dominus Deus tuus: leva ergo orationem pro reliquiis quæ repertæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 5, 'Et venerunt servi regis Ezechiæ ad Isaiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 6, 'Et dixit ad eos Isaias: Hæc dicetis domino vestro: Hæc dicit Dominus: Ne timeas a facie verborum quæ audisti, quibus blasphemaverunt pueri regis Assyriorum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 7, 'Ecce ego dabo ei spiritum, et audiet nuntium, et revertetur ad terram suam, et corruere eum faciam gladio in terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 8, 'Reversus est autem Rabsaces, et invenit regem Assyriorum præliantem adversus Lobnam: audierat enim quia profectus esset de Lachis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 9, 'Et audivit de Tharaca rege \'thiopiæ, dicentes: Egressus est ut pugnet contra te. Quod cum audisset, misit nuntios ad Ezechiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 10, 'Hæc dicetis Ezechiæ regi Judæ, loquentes: Non te decipiat Deus tuus in quo tu confidis, dicens: Non dabitur Jerusalem in manu regis Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 11, 'Ecce tu audisti omnia quæ fecerunt reges Assyriorum omnibus terris, quas subverterunt: et tu poteris liberari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 12, 'Numquid eruerunt eos dii gentium quos subverterunt patres mei, Gozam, et Haram, et Reseph, et filios Eden qui erant in Thalassar?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 13, 'Ubi est rex Emath, et rex Arphad, et rex urbis Sepharvaim, Ana, et Ava?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 14, 'Et tulit Ezechias libros de manu nuntiorum, et legit eos, et ascendit in domum Domini, et expandit eos Ezechias coram Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 15, 'et oravit Ezechias ad Dominum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 16, 'Domine exercituum, Deus Israël, qui sedes super cherubim, tu es Deus solus omnium regnorum terræ: tu fecisti cælum et terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 17, 'Inclina, Domine, aurem tuam, et audi; aperi, Domine, oculos tuos, et vide: et audi omnia verba Sennacherib, quæ misit ad blasphemandum Deum viventem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 18, 'Vere enim, Domine, desertas fecerunt reges Assyriorum terras, et regiones earum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 19, 'et dederunt deos earum igni: non enim erant dii, sed opera manuum hominum, lignum et lapis, et comminuerunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 20, 'Et nunc, Domine Deus noster, salva nos de manu ejus, et cognoscant omnia regna terræ quia tu es Dominus solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 21, 'Et misit Isaias, filius Amos, ad Ezechiam, dicens: Hæc dicit Dominus Deus Israël: Pro quibus rogasti me de Sennacherib, rege Assyriorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 22, 'hoc est verbum quod locutus est Dominus super eum: Despexit te et subsannavit te, virgo filia Sion; post te caput movit, filia Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 23, 'Cui exprobrasti? et quem blasphemasti? et super quem exaltasti vocem, et levasti altitudinem oculorum tuorum? ad Sanctum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 24, 'In manu servorum tuorum exprobrasti Domino, et dixisti: In multitudine quadrigarum mearum ego ascendi altitudinem montium juga Libani; et succidam excelsa cedrorum ejus, et electas abietes illius, et introibo altitudinem summitatis ejus, saltum Carmeli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 25, 'Ego fodi, et bibi aquam, et exsiccavi vestigio pedis mei omnes rivos aggerum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 26, 'Numquid non audisti quæ olim fecerim ei? Ex diebus antiquis ego plasmavi illud; et nunc adduxi, et factum est in eradicationem collium compugnantium, et civitatum munitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 27, 'Habitatores earum breviata manu contremuerunt, et confusi sunt. Facti sunt sicut fœnum agri, et gramen pascuæ, et herba tectorum, quæ exaruit antequam maturesceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 28, 'Habitationem tuam, et egressum tuum, et introitum tuum cognovi, et insaniam tuam contra me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 29, 'Cum fureres adversum me, superbia tua ascendit in aures meas. Ponam ergo circulum in naribus tuis, et frenum in labiis tuis, et reducam te in viam per quem venisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 30, 'Tibi autem hoc erit signum: comede hoc anno quæ sponte nascuntur, et in anno secundo pomis vescere; in anno autem tertio seminate et metite, et plantate vineas, et comedite fructum earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 31, 'Et mittet id quod salvatum fuerit de domo Juda, et quod reliquum est, radicem deorsum, et faciet fructum sursum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 32, 'quia de Jerusalem exibunt reliquiæ, et salvatio de monte Sion: zelus Domini exercituum faciet istud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 33, 'Propterea hæc dicit Dominus de rege Assyriorum: Non intrabit civitatem hanc, et non jaciet ibi sagittam, et non occupabit eam clypeus, et non mittet in circuitu ejus aggerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 34, 'In via qua venit, per eam revertetur, et civitatem hanc non ingredietur, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 35, 'Et protegam civitatem istam, ut salvem eam propter me, et propter David, servum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 36, 'Egressus est autem angelus Domini, et percussit in castris Assyriorum centum octoginta quinque millia. Et surrexerunt mane, et ecce omnes cadavera mortuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 37, 'Et egressus est, et abiit, et reversus est Sennacherib, rex Assyriorum, et habitavit in Ninive.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 37, 38, 'Et factum est, cum adoraret in templo Nesroch deum suum, Adramelech et Sarasar, filii ejus, percusserunt eum gladio, fugeruntque in terram Ararat; et regnavit Asarhaddon, filius ejus, pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 1, 'In diebus illis ægrotavit Ezechias usque ad mortem; et introivit ad eum Isaias, filius Amos, propheta, et dixit ei: Hæc dicit Dominus: Dispone domui tuæ, quia morieris tu, et non vives.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 2, 'Et convertit Ezechias faciem suam ad parietem, et oravit ad Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 3, 'et dixit: Obsecro, Domine, memento, quæso, quomodo ambulaverim coram te in veritate et in corde perfecto, et quod bonum est in oculis tuis fecerim. Et flevit Ezechias fletu magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 4, 'Et factum est verbum Domini ad Isaiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 5, 'Vade, et dic Ezechiæ: Hæc dicit Dominus Deus David patris tui: Audivi orationem tuam, et vidi lacrimas tuas; ecce ego adjiciam super dies tuos quindecim annos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 6, 'et de manu regis Assyriorum eruam te, et civitatem istam, et protegam eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 7, 'Hoc autem tibi erit signum a Domino, quia faciet Dominus verbum hoc quod locutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 8, 'ecce ego reverti faciam umbram linearum per quas descenderat in horologio Achaz in sole, retrorsum decem lineis. Et reversus est sol decem lineis per gradus quos descenderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 9, 'Scriptura Ezechiæ, regis Juda, cum ægrotasset et convaluisset de infirmitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 10, 'Ego dixi in dimidio dierum meorum: Vadam ad portas inferi; quæsivi residuum annorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 11, 'Dixi: Non videbo Dominum Deum in terra viventium; non aspiciam hominem ultra, et habitatorem quietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 12, 'Generatio mea ablata est, et convoluta est a me, quasi tabernaculum pastorum. Præcisa est velut a texente vita mea; dum adhuc ordirer, succidit me: de mane usque ad vesperam finies me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 13, 'Sperabam usque ad mane; quasi leo, sic contrivit omnia ossa mea: de mane usque ad vesperam finies me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 14, 'Sicut pullus hirundinis, sic clamabo; meditabor ut columba. Attenuati sunt oculi mei, suspicientes in excelsum. Domine, vim patior: responde pro me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 15, 'Quid dicam, aut quid respondebit mihi, cum ipse fecerit? Recogitabo tibi omnes annos meos in amaritudine animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 16, 'Domine, si sic vivitur, et in talibus vita spiritus mei, corripies me, et vivificabis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 17, 'Ecce in pace amaritudo mea amarissima. Tu autem eruisti animam meam ut non periret; projecisti post tergum tuum omnia peccata mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 18, 'Quia non infernus confitebitur tibi, neque mors laudabit te: non exspectabunt qui descendunt in lacum veritatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 19, 'Vivens, vivens ipse confitebitur tibi, sicut et ego hodie; pater filiis notam faciet veritatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 20, 'Domine, salvum me fac! et psalmos nostros cantabimus cunctis diebus vitæ nostræ in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 21, 'Et jussit Isaias ut tollerent massam de ficis, et cataplasmarent super vulnus, et sanaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 38, 22, 'Et dixit Ezechias: Quod erit signum quia ascendam in domum Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 1, 'In tempore illo misit Merodach Baladan, filius Baladan, rex Babylonis, libros et munera ad Ezechiam: audierat enim quod ægrotasset et convaluisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 2, 'Lætatus est autem super eis Ezechias, et ostendit eis cellam aromatum, et argenti, et auri, et odoramentorum, et unguenti optimi, et omnes apothecas supellectilis suæ, et universa quæ inventa sunt in thesauris ejus. Non fuit verbum quod non ostenderet eis Ezechias in domo sua, et in omni potestate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 3, 'Introivit autem Isaias propheta ad Ezechiam regem, et dixit ei: Quid dixerunt viri isti, et unde venerunt ad te? Et dixit Ezechias: De terra longinqua venerunt ad me, de Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 4, 'Et dixit: Quid viderunt in domo tua? Et dixit Ezechias: Omnia quæ in domo mea sunt viderunt; non fuit res quam non ostenderim eis in thesauris meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 5, 'Et dixit Isaias ad Ezechiam: Audi verbum Domini exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 6, 'Ecce dies venient, et auferentur omnia quæ in domo tua sunt, et quæ thesaurizaverunt patres tui usque ad diem hanc, in Babylonem; non relinquetur quidquam, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 7, 'Et de filiis tuis, qui exibunt de te, quos genueris, tollent, et erunt eunuchi in palatio regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 39, 8, 'Et dixit Ezechias ad Isaiam: Bonum verbum Domini, quod locutus est. Et dixit: Fiat tantum pax et veritas in diebus meis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 1, 'Consolamini, consolamini, popule meus, dicit Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 2, 'Loquimini ad cor Jerusalem, et advocate eam, quoniam completa est malitia ejus, dimissa est iniquitas illius: suscepit de manu Domini duplicia pro omnibus peccatis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 3, 'Vox clamantis in deserto: Parate viam Domini, rectas facite in solitudine semitas Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 4, 'Omnis vallis exaltabitur, et omnis mons et collis humiliabitur, et erunt prava in directa, et aspera in vias planas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 5, 'et revelabitur gloria Domini, et videbit omnis caro pariter quod os Domini locutum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 6, 'Vox dicentis: Clama. Et dixi: Quid clamabo? Omnis caro fœnum, et omnis gloria ejus quasi flos agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 7, 'Exsiccatum est fœnum, et cecidit flos, quia spiritus Domini sufflavit in eo. Vere fœnum est populus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 8, 'exsiccatum est fœnum, et cecidit flos; verbum autem Domini nostri manet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 9, 'Super montem excelsum ascende, tu qui evangelizas Sion; exalta in fortitudine vocem tuam, qui evangelizas Jerusalem: exalta, noli timere. Dic civitatibus Juda: Ecce Deus vester:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 10, 'ecce Dominus Deus in fortitudine veniet, et brachium ejus dominabitur: ecce merces ejus cum eo, et opus illius coram illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 11, 'Sicut pastor gregem suum pascet, in brachio suo congregabit agnos, et in sinu suo levabit; fœtas ipse portabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 12, 'Quis mensus est pugillo aquas, et cælos palmo ponderavit? quis appendit tribus digitis molem terræ, et libravit in pondere montes, et colles in statera?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 13, 'Quis adjuvit spiritum Domini? aut quis consiliarius ejus fuit, et ostendit illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 14, 'cum quo iniit consilium, et instruxit eum, et docuit eum semitam justitiæ, et erudivit eum scientiam, et viam prudentiæ ostendit illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 15, 'Ecce gentes quasi stilla situlæ, et quasi momentum stateræ reputatæ sunt; ecce insulæ quasi pulvis exiguus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 16, 'Et Libanus non sufficiet ad succendendum, et animalia ejus non sufficient ad holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 17, 'Omnes gentes quasi non sint, sic sunt coram eo, et quasi nihilum et inane reputatæ sunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 18, 'Cui ergo similem fecisti Deum? aut quam imaginem ponetis ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 19, 'Numquid sculptile conflavit faber? aut aurifex auro figuravit illud, et laminis argenteis argentarius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 20, 'Forte lignum et imputribile elegit; artifex sapiens quærit quomodo statuat simulacrum, quod non moveatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 21, 'Numquid non scitis? numquid non audistis? numquid non annuntiatum est vobis ab initio? numquid non intellexistis fundamenta terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 22, 'Qui sedet super gyrum terræ, et habitatores ejus sunt quasi locustæ; qui extendit velut nihilum cælos, et expandit eos sicut tabernaculum ad inhabitandum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 23, 'qui dat secretorum scrutatores quasi non sint, judices terræ velut inane fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 24, 'Et quidem neque plantatus, neque satus, neque radicatus in terra truncus eorum; repente flavit in eos, et aruerunt, et turbo quasi stipulam auferet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 25, 'Et cui assimilastis me, et adæquastis? dicit Sanctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 26, 'Levate in excelsum oculos vestros, et videte quis creavit hæc: qui educit in numero militiam eorum, et omnes ex nomine vocat; præ multitudine fortitudinis et roboris, virtutisque ejus, neque unum reliquum fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 27, 'Quare dicis, Jacob, et loqueris, Israël: Abscondita est via mea a Domino, et a Deo meo judicium meum transivit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 28, 'Numquid nescis, aut non audisti? Deus sempiternus Dominus, qui creavit terminos terræ: non deficiet, neque laborabit, nec est investigatio sapientiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 29, 'Qui dat lasso virtutem, et his qui non sunt, fortitudinem et robur multiplicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 30, 'Deficient pueri, et laborabunt, et juvenes in infirmitate cadent;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 40, 31, 'qui autem sperant in Domino mutabunt fortitudinem, assument pennas sicut aquilæ: current et non laborabunt, ambulabunt et non deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 1, 'Taceant ad me insulæ, et gentes mutent fortitudinem: accedant, et tunc loquantur; simul ad judicium propinquemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 2, 'Quis suscitavit ab oriente Justum, vocavit eum ut sequeretur se? Dabit in conspectu ejus gentes, et reges obtinebit: dabit quasi pulverem gladio ejus, sicut stipulam vento raptam arcui ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 3, 'Persequetur eos, transibit in pace: semita in pedibus ejus non apparebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 4, 'Quis hæc operatus est, et fecit, vocans generationes ab exordio? Ego Dominus: primus et novissimus ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 5, 'Viderunt insulæ, et timuerunt; extrema terræ obstupuerunt: appropinquaverunt, et accesserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 6, 'Unusquisque proximo suo auxiliabitur, et fratri suo dicet: Confortare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 7, 'Confortavit faber ærarius percutiens malleo eum, qui cudebat tunc temporis, dicens: Glutino bonum est; et confortavit eum clavis, ut non moveretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 8, 'Et tu, Israël, serve meus, Jacob quem elegi, semen Abraham amici mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 9, 'in quo apprehendi te ab extremis terræ, et a longinquis ejus vocavi te, et dixi tibi: Servus meus es tu: elegi te, et non abjeci te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 10, 'Ne timeas, quia ego tecum sum; ne declines, quia ego Deus tuus: confortavi te, et auxiliatus sum tibi, et suscepit te dextera Justi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 11, 'Ecce confundentur et erubescent omnes qui pugnant adversum te; erunt quasi non sint, et peribunt viri qui contradicunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 12, 'Quæres eos, et non invenies, viros rebelles tuos; erunt quasi non sint, et veluti consumptio homines bellantes adversum te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 13, 'Quia ego Dominus Deus tuus, apprehendens manum tuam, dicensque tibi: Ne timeas: ego adjuvi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 14, 'Noli timere, vermis Jacob, qui mortui estis ex Israël: ego auxiliatus sum tibi, dicit Dominus, et redemptor tuus Sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 15, 'Ego posui te quasi plaustrum triturans novum, habens rostra serrantia; triturabis montes, et comminues, et colles quasi pulverem pones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 16, 'Ventilabis eos, et ventus tollet, et turbo disperget eos; et tu exsultabis in Domino, in Sancto Israël lætaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 17, 'Egeni et pauperes quærunt aquas, et non sunt; lingua eorum siti aruit. Ego Dominus exaudiam eos, Deus Israël, non derelinquam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 18, 'Aperiam in supinis collibus flumina, et in medio camporum fontes: ponam desertum in stagna aquarum, et terram inviam in rivos aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 19, 'Dabo in solitudinem cedrum, et spinam, et myrtum, et lignum olivæ; ponam in deserto abietem, ulmum, et buxum simul:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 20, 'ut videant, et sciant, et recogitent, et intelligant pariter, quia manus Domini fecit hoc, et Sanctus Israël creavit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 21, 'Prope facite judicium vestrum, dicit Dominus; Afferte, si quid forte habetis, dicit rex Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 22, 'Accedant, et nuntient nobis quæcumque ventura sunt; priora quæ fuerunt, nuntiate, et ponemus cor nostrum, et sciemus novissima eorum; et quæ ventura sunt, indicate nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 23, 'Annuntiate quæ ventura sunt in futurum, et sciemus quia dii estis vos; bene quoque aut male, si potestis, facite, et loquamur et videamus simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 24, 'Ecce vos estis ex nihilo, et opus vestrum ex eo quod non est: abominatio est qui elegit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 25, 'Suscitavi ab aquilone, et veniet ab ortu solis: vocabit nomen meum, et adducet magistratus quasi lutum, et velut plastes conculcans humum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 26, 'Quis annuntiavit ab exordio ut sciamus, et a principio ut dicamus: Justus es? Non est neque annuntians, neque prædicens, neque audiens sermones vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 27, 'Primus ad Sion dicet: Ecce adsunt, et Jerusalem evangelistam dabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 28, 'Et vidi, et non erat neque ex istis quisquam qui iniret consilium, et interrogatus responderet verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 41, 29, 'Ecce omnes injusti, et vana opera eorum; ventus et inane simulacra eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 1, 'Ecce servus meus, suscipiam eum; electus meus, complacuit sibi in illo anima mea: dedi spiritum meum super eum: judicium gentibus proferet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 2, 'Non clamabit, neque accipiet personam, nec audietur vox ejus foris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 3, 'Calamum quassatum non conteret, et linum fumigans non extinguet: in veritate educet judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 4, 'Non erit tristis, neque turbulentus, donec ponat in terra judicium; et legem ejus insulæ exspectabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 5, 'Hæc dicit Dominus Deus, creans cælos, et extendens eos; firmans terram, et quæ germinant ex ea; dans flatum populo qui est super eam, et spiritum calcantibus eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 6, 'Ego Dominus vocavi te in justitia, et apprehendi manum tuam, et servavi te: et dedi te in fœdus populi, in lucem gentium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 7, 'ut aperires oculos cæcorum, et educeres de conclusione vinctum, de domo carceris sedentes in tenebris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 8, 'Ego Dominus, hoc est nomen meum; gloriam meam alteri non dabo, et laudem meam sculptilibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 9, 'Quæ prima fuerunt, ecce venerunt; nova quoque ego annuntio: antequam oriantur, audita vobis faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 10, 'Cantate Domino canticum novum, laus ejus ab extremis terræ, qui descenditis in mare, et plenitudo ejus; insulæ, et habitatores earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 11, 'Sublevetur desertum et civitates ejus. In domibus habitabit Cedar: laudate, habitatores petræ; de vertice montium clamabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 12, 'Ponent Domino gloriam, et laudem ejus in insulis nuntiabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 13, 'Dominus sicut fortis egredietur, sicut vir præliator suscitabit zelum; vociferabitur, et clamabit: super inimicos suos confortabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 14, 'Tacui semper, silui, patiens fui: sicut parturiens loquar; dissipabo, et absorbebo simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 15, 'Desertos faciam montes et colles, et omne gramen eorum exsiccabo; et ponam flumina in insulas, et stagna arefaciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 16, 'Et ducam cæcos in viam quam nesciunt, et in semitis quas ignoraverunt ambulare eos faciam; ponam tenebras coram eis in lucem, et prava in recta; hæc verba feci eis, et non dereliqui eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 17, 'Conversi sunt retrorsum, confundantur confusione, qui confidunt in sculptili; qui dicunt conflatili: Vos dii nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 18, 'Surdi, audite, et cæci, intuemini ad videndum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 19, 'Quis cæcus, nisi servus meus; et surdus, nisi ad quem nuntios meos misi? quis cæcus, nisi qui venundatus est? et quis cæcus, nisi servus Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 20, 'Qui vides multa, nonne custodies? qui apertas habes aures, nonne audies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 21, 'Et Dominus voluit ut sanctificaret eum, et magnificaret legem, et extolleret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 22, 'Ipse autem populus direptus, et vastatus; laqueus juvenum omnes, et in domibus carcerum absconditi sunt; facti sunt in rapinam, nec est qui eruat; in direptionem, nec est qui dicat: Redde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 23, 'Quis est in vobis qui audiat hoc, attendat, et auscultet futura?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 24, 'Quis dedit in direptionem Jacob, et Israël vastantibus? nonne Dominus ipse, cui peccavimus? Et noluerunt in viis ejus ambulare, et non audierunt legem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 42, 25, 'Et effudit super eum indignationem furoris sui, et forte bellum; et combussit eum in circuitu, et non cognovit; et succendit eum, et non intellexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 1, 'Et nunc hæc dicit Dominus creans te, Jacob, et formans te, Israël: Noli timere, quia redemi te, et vocavi te nomine tuo: meus es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 2, 'Cum transieris per aquas, tecum ero, et flumina non operient te; cum ambulaveris in igne, non combureris, et flamma non ardebit in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 3, 'Quia ego Dominus Deus tuus, Sanctus Israël, salvator tuus, dedi propitiationem tuam \'gyptum, \'thopiam, et Saba, pro te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 4, 'Ex quo honorabilis factus es in oculis meis, et gloriosus, ego dilexi te, et dabo homines pro te, et populos pro anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 5, 'Noli timere, quia ego tecum sum; ab oriente adducam semen tuum, et ab occidente congregabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 6, 'Dicam aquiloni: Da; et austro: Noli prohibere: affer filios meos de longinquo, et filias meas ab extremis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 7, 'Et omnem qui invocat nomen meum, in gloriam meam creavi eum, formavi eum, et feci eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 8, 'Educ foras populum cæcum, et oculos habentem; surdum, et aures ei sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 9, 'Omnes gentes congregatæ sunt simul, et collectæ sunt tribus. Quis in vobis annuntiet istud, et quæ prima sunt audire nos faciet? Dent testes eorum, justificentur, et audiant, et dicant: Vere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 10, 'Vos testes mei, dicit Dominus, et servus meus quem elegi: ut sciatis, et credatis mihi, et intelligatis quia ego ipse sum; ante me non est formatus Deus, et post me non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 11, 'Ego sum, ego sum Dominus, et non est absque me salvator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 12, 'Ego annuntiavi, et salvavi; auditum feci, et non fuit in vobis alienus: vos testes mei, dicit Dominus, et ego Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 13, 'Et ab initio ego ipse, et non est qui de manu mea eruat. Operabor, et quis avertet illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 14, 'Hæc dicit Dominus, redemptor vester, Sanctus Israël: Propter vos misi in Babylonem, et detraxi vectes universos, et Chaldæos in navibus suis gloriantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 15, 'Ego Dominus, Sanctus vester, creans Israël, rex vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 16, 'Hæc dicit Dominus, qui dedit in mari viam, et in aquis torrentibus semitam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 17, 'qui eduxit quadrigam et equum, agmen et robustum: simul obdormierunt, nec resurgent; contriti sunt quasi linum, et extincti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 18, 'Ne memineritis priorum, et antiqua ne intueamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 19, 'Ecce ego facio nova, et nunc orientur, utique cognoscetis ea: ponam in deserto viam, et in invio flumina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 20, 'Glorificabit me bestia agri, dracones, et struthiones: quia dedi in deserto aquas, flumina in invio, ut darem potum populo meo, electo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 21, 'Populum istum formavi mihi: laudem meam narrabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 22, 'Non me invocasti, Jacob, nec laborasti in me, Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 23, 'Non obtulisti mihi arietem holocausti tui, et victimis tuis non glorificasti me; non te servire feci in oblatione, nec laborem tibi præbui in thure.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 24, 'Non emisti mihi argento calamum, et adipe victimarum tuarum non inebriasti me: verumtamen servire me fecisti in peccatis tuis; præbuisti mihi laborem in iniquitatibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 25, 'Ego sum, ego sum ipse qui deleo iniquitates tuas propter me, et peccatorum tuorum non recordabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 26, 'Reduc me in memoriam, et judicemur simul: narra si quid habes ut justificeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 27, 'Pater tuus primus peccavit, et interpretes tui prævaricati sunt in me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 43, 28, 'et contaminavi principes sanctos; dedi ad internecionem Jacob, et Israël in blasphemiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 1, 'Et nunc audi, Jacob, serve meus, et Israël, quem elegi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 2, 'Hæc dicit Dominus faciens et formans te, ab utero auxiliator tuus: Noli timere, serve meus Jacob, et rectissime, quem elegi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 3, 'Effundam enim aquas super sitientem, et fluenta super aridam; effundam spiritum meum super semen tuum, et benedictionem meam super stirpem tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 4, 'et germinabunt inter herbas, quasi salices juxta præterfluentes aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 5, 'Iste dicet: Domini ego sum; et ille vocabit in nomine Jacob; et hic scribet manu sua: Domino, et in nomine Israël assimilabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 6, 'Hæc dicit Dominus, rex Israël, et redemptor ejus, Dominus exercituum: Ego primus, et ego novissimus, et absque me non est deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 7, 'Quis similis mei? vocet, et annuntiet: et ordinem exponat mihi, ex quo constitui populum antiquum; ventura et quæ futura sunt annuntient eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 8, 'Nolite timere, neque conturbemini: ex tunc audire te feci, et annuntiavi; vos estis testes mei. Numquid est Deus absque me, et formator quem ego non noverim?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 9, 'Plastæ idoli omnes nihil sunt, et amantissima eorum non proderunt eis. Ipsi sunt testes eorum, quia non vident, neque intelligunt, ut confundantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 10, 'Quis formavit deum, et sculptile conflavit ad nihil utile?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 11, 'Ecce omnes participes ejus confundentur, fabri enim sunt ex hominibus; convenient omnes, stabunt et pavebunt, et confundentur simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 12, 'Faber ferrarius lima operatus est, in prunis et in malleis formavit illud, et operatus est in brachio fortitudinis suæ; esuriet et deficiet, non bibet aquam et lassescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 13, 'Artifex lignarius extendit normam, formavit illud in runcina, fecit illud in angularibus, et in circino tornavit illud, et fecit imaginem viri quasi speciosum hominem habitantem in domo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 14, 'succidit cedros, tulit ilicem, et quercum, quæ steterat inter ligna saltus; plantavit pinum, quam pluvia nutrivit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 15, 'et facta est hominibus in focum; sumpsit ex eis, et calefactus est; et succendit et coxit panes; de reliquo autem operatus est deum et adoravit; fecit sculptile, et curvatus est ante illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 16, 'Medium ejus combussit igni, et de medio ejus carnes comedit; coxit pulmentum, et saturatus est, et calefactus est, et dixit: Vah! calefactus sum, vidi focum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 17, 'reliquum autem ejus deum fecit et sculptile sibi; curvatur ante illud, et adorat illud, et obsecrat, dicens: Libera me, quia deus meus es tu!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 18, 'Nescierunt, neque intellexerunt; obliti enim sunt ne videant oculi eorum, et ne intelligant corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 19, 'Non recogitant in mente sua, neque cognoscunt, neque sentiunt, ut dicant: Medietatem ejus combussi igni, et coxi super carbones ejus panes; coxi carnes et comedi, et de reliquo ejus idolum faciam? ante truncum ligni procidam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 20, 'Pars ejus cinis est; cor insipiens adoravit illud, et non liberabit animam suam: neque dicet: Forte mendacium est in dextera mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 21, 'Memento horum Jacob, et Israël, quoniam servus meus es tu. Formavi te; servus meus es tu, Israël, ne obliviscaris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 22, 'Delevi ut nubem iniquitates tuas, et quasi nebulam peccata tua: revertere ad me, quoniam redemi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 23, 'Laudate, cæli, quoniam misericordiam fecit Dominus; jubilate, extrema terræ; resonate, montes, laudationem, saltus et omne lignum ejus, quoniam redemit Dominus Jacob, et Israël gloriabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 24, 'Hæc dicit Dominus, redemptor tuus, et formator tuus ex utero: Ego sum Dominus, faciens omnia, extendens cælos solus, stabiliens terram, et nullus mecum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 25, 'irrita faciens signa divinorum, et ariolos in furorem vertens; convertens sapientes retrorsum, et scientiam eorum stultam faciens;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 26, 'suscitans verbum servi sui, et consilium nuntiorum suorum complens; qui dico Jerusalem: Habitaberis, et civitatibus Juda: \'dificabimini, et deserta ejus suscitabo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 27, 'qui dico profundo: Desolare, et flumina tua arefaciam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 44, 28, 'qui dico Cyro: Pastor meus es, et omnem voluntatem meam complebis; qui dico Jerusalem: \'dificaberis, et templo: Fundaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 1, 'Hæc dicit Dominus christo meo Cyro, cujus apprehendi dexteram, ut subjiciam ante faciem ejus gentes, et dorsa regum vertam, et aperiam coram eo januas, et portæ non claudentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 2, 'Ego ante te ibo, et gloriosos terræ humiliabo; portas æreas conteram, et vectes ferreos confringam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 3, 'et dabo tibi thesauros absconditos, et arcana secretorum, ut scias quia ego Dominus, qui voco nomen tuum, Deus Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 4, 'propter servum meum Jacob, et Israël, electum meum; et vocavi te nomine tuo: assimilavi te, et non cognovisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 5, 'Ego Dominus, et non est amplius; extra me non est deus; accinxi te, et non cognovisti me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 6, 'ut sciant hi qui ab ortu solis et qui ab occidente, quoniam absque me non est: ego Dominus, et non est alter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 7, 'formans lucem et creans tenebras, faciens pacem et creans malum: ego Dominus faciens omnia hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 8, 'Rorate, cæli, desuper, et nubes pluant justum; aperiatur terra, et germinet Salvatorem, et justitia oriatur simul: ego Dominus creavi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 9, 'Væ qui contradicit fictori suo, testa de samiis terræ! Numquid dicet lutum figulo suo: Quid facis, et opus tuum absque manibus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 10, 'Væ qui dicit patri: Quid generas? et mulieri: Quid parturis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 11, 'Hæc dicit Dominus, Sanctus Israël, plastes ejus: Ventura interrogate me; super filios meos et super opus manuum mearum mandate mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 12, 'Ego feci terram, et hominem super eam creavi ego: manus meæ tetenderunt cælos, et omni militiæ eorum mandavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 13, 'Ego suscitavi eum ad justitiam, et omnes vias ejus dirigam; ipse ædificabit civitatem meam, et captivitatem meam dimittet, non in pretio neque in muneribus, dicit Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 14, 'Hæc dicit Dominus: Labor \'gypti, et negotiatio \'thiopiæ, et Sabaim viri sublimes ad te transibunt, et tui erunt; post te ambulabunt, vincti manicis pergent, et te adorabunt, teque deprecabuntur. Tantum in te est Deus, et non est absque te deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 15, 'Vere tu es Deus absconditus, Deus Israël, salvator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 16, 'Confusi sunt, et erubuerunt omnes: simul abierunt in confusionem fabricatores errorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 17, 'Israël salvatus est in Domino salute æterna; non confundemini, et non erubescetis usque in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 18, 'Quia hæc dicit Dominus creans cælos, ipse Deus formans terram et faciens eam, ipse plastes ejus; non in vanum creavit eam: ut habitaretur formavit eam: Ego Dominus, et non est alius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 19, 'Non in abscondito locutus sum, in loco terræ tenebroso; non dixi semini Jacob frustra: Quærite me: ego Dominus loquens justitiam, annuntians recta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 20, 'Congregamini, et venite, et accedite simul qui salvati estis ex gentibus: nescierunt qui levant lignum sculpturæ suæ, et rogant deum non salvantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 21, 'Annuntiate, et venite, et consiliamini simul. Quis auditum fecit hoc ab initio, ex tunc prædixit illud? numquid non ego Dominus, et non est ultra deus absque me? Deus justus, et salvans non est præter me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 22, 'Convertimini ad me, et salvi eritis, omnes fines terræ, quia ego Deus, et non est alius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 23, 'In memetipso juravi; egredietur de ore meo justitiæ verbum, et non revertetur: quia mihi curvabitur omne genu, et jurabit omnis lingua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 24, 'Ergo in Domino, dicet, meæ sunt justitiæ et imperium; ad eum venient, et confundentur omnes qui repugnant ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 25, 'In Domino justificabitur, et laudabitur omne semen Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 45, 26, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 1, 'Confractus est Bel, contritus est Nabo; facta sunt simulacra eorum bestiis et jumentis, onera vestra gravi pondere usque ad lassitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 2, 'Contabuerunt, et contrita sunt simul; non potuerunt salvare portantem, et anima eorum in captivitatem ibit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 3, 'Audite me, domus Jacob, et omne residuum domus Israël; qui portamini a meo utero, qui gestamini a mea vulva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 4, 'Usque ad senectam ego ipse, et usque ad canos ego portabo; ego feci, et ego feram; ego portabo, et salvabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 5, 'Cui assimilastis me, et adæquastis, et comparastis me, et fecistis similem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 6, 'Qui confertis aurum de sacculo, et argentum statera ponderatis, conducentes aurificem ut faciat deum, et procidunt, et adorant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 7, 'Portant illum in humeris gestantes, et ponentes in loco suo, et stabit, ac de loco suo non movebitur: sed et cum clamaverint ad eum, non audiet; de tribulatione non salvabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 8, 'Mementote istud, et confundamini; redite, prævaricatores, ad cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 9, 'Recordamini prioris sæculi, quoniam ego sum Deus, et non est ultra deus, nec est similis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 10, 'Annuntians ab exordio novissimum, et ab initio quæ necdum facta sunt, dicens: Consilium meum stabit, et omnis voluntas mea fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 11, 'Vocans ab oriente avem, et de terra longinqua virum voluntatis meæ: et locutus sum, et adducam illud; creavi et faciam illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 12, 'Audite me, duro corde, qui longe estis a justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 46, 13, 'Prope feci justitiam meam, non elongabitur, et salus mea non morabitur. Dabo in Sion salutem, et in Israël gloriam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 1, 'Descende, sede in pulvere, virgo filia Babylon: sede in terra; non est solium filiæ Chaldæorum, quia ultra non vocaberis mollis et tenera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 2, 'Tolle molam, et mole farinam; denuda turpitudinem tuam; discooperi humerum, revela crura, transi flumina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 3, 'Revelabitur ignominia tua, et videbitur opprobrium tuum; ultionem capiam, et non resistet mihi homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 4, 'Redemptor noster, Dominus exercituum nomen illius, Sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 5, 'Sede tacens, et intra in tenebras, filia Chaldæorum, quia non vocaberis ultra domina regnorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 6, 'Iratus sum super populum meum: contaminavi hæreditatem meam, et dedi eos in manu tua: non posuisti eis misericordias; super senem aggravasti jugum tuum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 7, 'Et dixisti: In sempiternum ero domina. Non posuisti hæc super cor tuum, neque recordata es novissimi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 8, 'Et nunc audi hæc delicata, et habitans confidenter, quæ dicis in corde tuo: Ego sum, et non est præter me amplius; non sedebo vidua, et ignorabo sterilitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 9, 'Venient tibi duo hæc subito in die una, sterilitas et viduitas: universa venerunt super te, propter multitudinem maleficiorum tuorum, et propter duritiam incantatorum tuorum vehementem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 10, 'Et fiduciam habuisti in malitia tua, et dixisti: Non est qui videat me. Sapientia tua et scientia tua, hæc decepit te. Et dixisti in corde tuo: Ego sum, et præter me non est altera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 11, 'Veniet super te malum, et nescies ortum ejus; et irruet super te calamitas quam non poteris expiare; veniet super te repente miseria quam nescies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 12, 'Sta cum incantatoribus tuis et cum multitudine maleficiorum tuorum, in quibus laborasti ab adolescentia tua, si forte quod prosit tibi, aut si possis fieri fortior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 13, 'Defecisti in multitudine consiliorum tuorum. Stent, et salvent te augures cæli, qui contemplabantur sidera, et supputabant menses, ut ex eis annuntiarent ventura tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 14, 'Ecce facti sunt quasi stipula, ignis combussit eos; non liberabunt animam suam de manu flammæ; non sunt prunæ quibus calefiant, nec focus ut sedeant ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 47, 15, 'Sic facta sunt tibi in quibuscumque laboraveras: negotiatores tui ab adolescentia tua, unusquisque in via sua erraverunt; non est qui salvet te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 1, 'Audite hæc, domus Jacob, qui vocamini nomine Israël, et de aquis Juda existis; qui juratis in nomine Domini, et Dei Israël recordamini non in veritate neque in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 2, 'De civitate enim sancta vocati sunt, et super Deum Israël constabiliti sunt: Dominus exercituum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 3, 'Priora ex tunc annuntiavi, et ex ore meo exierunt, et audita feci ea: repente operatus sum, et venerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 4, 'Scivi enim quia durus es tu, et nervus ferreus cervix tua, et frons tua ærea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 5, 'Prædixi tibi ex tunc; antequam venirent, indicavi tibi, ne forte diceres: Idola mea fecerunt hæc, et sculptilia mea et conflatilia mandaverunt ista.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 6, 'Quæ audisti, vide omnia; vos autem, num annuntiastis? Audita feci tibi nova ex tunc, et conservata sunt quæ nescis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 7, 'Nunc creata sunt et non ex tunc; et ante diem, et non audisti ea, ne forte dicas: Ecce ego cognovi ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 8, 'Neque audisti, neque cognovisti, neque ex tunc aperta est auris tua: scio enim quia prævaricans prævaricaberis, et transgressorem ex utero vocavi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 9, 'Propter nomen meum longe faciam furorem meum, et laude mea infrenabo te, ne intereas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 10, 'Ecce excoxi te, sed non quasi argentum; elegi te in camino paupertatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 11, 'Propter me, propter me faciam, ut non blasphemer; et gloriam meam alteri non dabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 12, 'Audi me, Jacob, et Israël, quem ego voco: ego ipse, ego primus, et ego novissimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 13, 'Manus quoque mea fundavit terram, et dextera mea mensa est cælos; ego vocabo eos, et stabunt simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 14, 'Congregamini, omnes vos, et audite: quis de eis annuntiavit hæc? Dominus dilexit eum, faciet voluntatem suam in Babylone, et brachium suum in Chaldæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 15, 'Ego, ego locutus sum, et vocavi eum; adduxi eum, et directa est via ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 16, 'Accedite ad me et audite hoc: non a principio in abscondito locutus sum: ex tempore antequam fieret, ibi eram: et nunc Dominus Deus misit me, et spiritus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 17, 'Hæc dicit Dominus, redemptor tuus, Sanctus Israël: Ego Dominus Deus tuus, docens te utilia, gubernans te in via qua ambulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 18, 'Utinam attendisses mandata mea: facta fuisset sicut flumen pax tua, et justitia tua sicut gurgites maris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 19, 'et fuisset quasi arena semen tuum, et stirps uteri tui ut lapilli ejus; non interisset et non fuisset attritum nomen ejus a facie mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 20, 'Egredimini de Babylone, fugite a Chaldæis, in voce exsultationis annuntiate: auditum facite hoc, et efferte illud usque ad extrema terræ. Dicite: Redemit Dominus servum suum Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 21, 'Non sitierunt in deserto, cum educeret eos: aquam de petra produxit eis, et scidit petram, et fluxerunt aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 48, 22, 'Non est pax impiis, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 1, 'Audite, insulæ, et attendite, populi de longe: Dominus ab utero vocavit me; de ventre matris meæ recordatus est nominis mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 2, 'Et posuit os meum quasi gladium acutum, in umbra manus suæ protexit me, et posuit me sicut sagittam electam: in pharetra sua abscondit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 3, 'Et dixit mihi: Servus meus es tu Israël, quia in te gloriabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 4, 'Et ego dixi: In vacuum laboravi; sine causa et vane fortitudinem meam consumpsi: ergo judicium meum cum Domino, et opus meum cum Deo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 5, 'Et nunc dicit Dominus, formans me ex utero servum sibi, ut reducam Jacob ad eum, et Israël non congregabitur; et glorificatus sum in oculis Domini, et Deus meus factus est fortitudo mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 6, 'Et dixit: Parum est ut sis mihi servus ad suscitandas tribus Jacob, et fæces Israël convertendas: ecce dedi te in lucem gentium, ut sis salus mea usque ad extremum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 7, 'Hæc dicit Dominus, redemptor Israël, Sanctus ejus, ad contemptibilem animam, ad abominatam gentem, ad servum dominorum: Reges videbunt, et consurgent principes, et adorabunt propter Dominum, quia fidelis est, et Sanctum Israël qui elegit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 8, 'Hæc dicit Dominus: In tempore placito exaudivi te, et in die salutis auxiliatus sum tui: et servavi te, et dedi te in fœdus populi, ut suscitares terram, et possideres hæreditates dissipatas;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 9, 'ut diceres his qui vincti sunt: Exite, et his qui in tenebris: Revelamini. Super vias pascentur, et in omnibus planis pascua eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 10, 'Non esurient neque sitient, et non percutiet eos æstus et sol, quia miserator eorum reget eos, et ad fontes aquarum potabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 11, 'Et ponam omnes montes meos in viam, et semitæ meæ exaltabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 12, 'Ecce isti de longe venient, et ecce illi ab aquilone et mari, et isti de terra australi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 13, 'Laudate, cæli, et exsulta, terra; jubilate, montes, laudem, quia consolatus est Dominus populum suum, et pauperum suorum miserebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 14, 'Et dixit Sion: Dereliquit me Dominus, et Dominus oblitus est mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 15, 'Numquid oblivisci potest mulier infantem suum, ut non misereatur filio uteri sui? Etsi illa oblita fuerit, ego tamen non obliviscar tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 16, 'Ecce in manibus meis descripsi te; muri tui coram oculis meis semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 17, 'Venerunt structores tui; destruentes te et dissipantes a te exibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 18, 'Leva in circuitu oculos tuos, et vide: omnes isti congregati sunt, venerunt tibi. Vivo ego, dicit Dominus, quia omnibus his velut ornamento vestieris, et circumdabis tibi eos quasi sponsa;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 19, 'quia deserta tua, et solitudines tuæ, et terra ruinæ tuæ, nunc angusta erunt præ habitatoribus; et longe fugabuntur qui absorbebant te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 20, 'Adhuc dicent in auribus tuis filii sterilitatis tuæ: Angustus est mihi locus; fac spatium mihi ut habitem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 21, 'Et dices in corde tuo: Quis genuit mihi istos? ego sterilis et non pariens, transmigrata, et captiva; et istos quis enutrivit? ego destituta et sola; et isti ubi erant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 22, 'Hæc dicit Dominus Deus: Ecce levabo ad gentes manum meam, et ad populos exaltabo signum meum: et afferent filios tuos in ulnis, et filias tuas super humeros portabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 23, 'Et erunt reges nutritii tui, et reginæ nutrices tuæ; vultu in terram demisso adorabunt te, et pulverem pedum tuorum lingent. Et scies quia ego Dominus, super quo non confundentur qui exspectant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 24, 'Numquid tolletur a forti præda? aut quod captum fuerit a robusto, salvum esse poterit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 25, 'Quia hæc dicit Dominus: Equidem, et captivitas a forti tolletur, et quod ablatum fuerit a robusto, salvabitur. Eos vero qui judicaverunt te, ego judicabo, et filios tuos ego salvabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 49, 26, 'Et cibabo hostes tuos carnibus suis, et quasi musto, sanguine suo inebriabuntur, et sciet omnis caro quia ego Dominus salvans te, et redemptor tuus fortis Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 1, 'Hæc dicit Dominus: Quis est hic liber repudii matris vestræ, quo dimisi eam? aut quis est creditor meus, cui vendidi vos? Ecce in iniquitatibus vestris venditi estis, et in sceleribus vestris dimisi matrem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 2, 'Quia veni, et non erat vir; vocavi, et non erat qui audiret. Numquid abbreviata et parvula facta est manus mea, ut non possim redimere? aut non est in me virtus ad liberandum? Ecce in increpatione mea desertum faciam mare, ponam flumina in siccum; computrescent pisces sine aqua, et morientur in siti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 3, 'Induam cælos tenebris, et saccum ponam operimentum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 4, 'Dominus dedit mihi linguam eruditam, ut sciam sustentare eum qui lassus est verbo. Erigit mane, mane erigit mihi aurem, ut audiam quasi magistrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 5, 'Dominus Deus aperuit mihi aurem, ego autem non contradico: retrorsum non abii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 6, 'Corpus meum dedi percutientibus, et genas meas vellentibus; faciem meam non averti ab increpantibus et conspuentibus in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 7, 'Dominus Deus auxiliator meus, ideo non sum confusus; ideo posui faciem meam ut petram durissimam, et scio quoniam non confundar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 8, 'Juxta est qui justificat me; quis contradicet mihi? Stemus simul; quis est adversarius meus? accedat ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 9, 'Ecce Dominus Deus auxiliator meus; quis est qui condemnet me? Ecce omnes quasi vestimentum conterentur; tinea comedet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 10, 'Quis ex vobis timens Dominum, audiens vocem servi sui? Qui ambulavit in tenebris, et non est lumen ei, speret in nomine Domini, et innitatur super Deum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 50, 11, 'Ecce vos omnes accendentes ignem, accincti flammis: ambulate in lumine ignis vestri, et in flammis quas succendistis; de manu mea factum est hoc vobis: in doloribus dormietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 1, 'Audite me, qui sequimini quod justum est, et quæritis Dominum; attendite ad petram unde excisi estis, et ad cavernam laci de qua præcisi estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 2, 'Attendite ad Abraham, patrem vestrum, et ad Saram, quæ peperit vos: quia unum vocavi eum, et benedixi ei, et multiplicavi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 3, 'Consolabitur ergo Dominus Sion, et consolabitur omnes ruinas ejus: et ponet desertum ejus quasi delicias, et solitudinem ejus quasi hortum Domini. Gaudium et lætitia invenietur in ea, gratiarum actio et vox laudis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 4, 'Attendite ad me, popule meus, et tribus mea, me audite: quia lex a me exiet, et judicium meum in lucem populorum requiescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 5, 'Prope est justus meus, egressus est salvator meus, et brachia mea populos judicabunt; me insulæ exspectabunt, et brachium meum sustinebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 6, 'Levate in cælum oculos vestros, et videte sub terra deorsum: quia cæli sicut fumus liquescent, et terra sicut vestimentum atteretur, et habitatores ejus sicut hæc interibunt: salus autem mea in sempiternum erit, et justitia mea non deficiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 7, 'Audite me, qui scitis justum, populus meus, lex mea in corde eorum: nolite timere opprobrium hominum, et blasphemias eorum ne metuatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 8, 'sicut enim vestimentum, sic comedet eos vermis, et sicut lanam, sic devorabit eos tinea: salus autem mea in sempiternum erit, et justitia mea in generationes generationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 9, 'Consurge, consurge, induere fortitudinem, brachium Domini! consurge sicut in diebus antiquis, in generationibus sæculorum. Numquid non tu percussisti superbum, vulnerasti draconem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 10, 'numquid non tu siccasti mare, aquam abyssi vehementis; qui posuisti profundum maris viam, ut transirent liberati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 11, 'Et nunc qui redempti sunt a Domino, revertentur, et venient in Sion laudantes, et lætitia sempiterna super capita eorum: gaudium et lætitiam tenebunt; fugiet dolor et gemitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 12, 'Ego, ego ipse consolabor vos. Quis tu, ut timeres ab homine mortali, et a filio hominis qui quasi fœnum ita arescet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 13, 'Et oblitus es Domini, factoris tui, qui tetendit cælos et fundavit terram; et formidasti jugiter tota die a facie furoris ejus qui te tribulabat, et paraverat ad perdendum. Ubi nunc est furor tribulantis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 14, 'Cito veniet gradiens ad aperiendum; et non interficiet usque ad internecionem, nec deficiet panis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 15, 'Ego autem sum Dominus Deus tuus, qui conturbo mare, et intumescunt fluctus ejus: Dominus exercituum nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 16, 'Posui verba mea in ore tuo, et in umbra manus meæ protexi te, ut plantes cælos, et fundes terram, et dicas ad Sion: Populus meus es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 17, 'Elevare, elevare, consurge, Jerusalem, quæ bibisti de manu Domini calicem iræ ejus; usque ad fundum calicis soporis bibisti, et potasti usque ad fæces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 18, 'Non est qui sustentet eam, ex omnibus filiis quos genuit; et non est qui apprehendat manum ejus, ex omnibus filiis quos enutrivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 19, 'Duo sunt quæ occurrerunt tibi; quis contristabitur super te? Vastitas, et contritio, et fames, et gladius; quis consolabitur te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 20, 'Filii tui projecti sunt, dormierunt in capite omnium viarum sicut oryx illaqueatus, pleni indignatione Domini, increpatione Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 21, 'Idcirco audi hoc, paupercula, et ebria non a vino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 22, 'Hæc dicit dominator tuus Dominus, et Deus tuus, qui pugnabit pro populo suo: Ecce tuli de manu tua calicem soporis, fundum calicis indignationis meæ: non adjicies ut bibas illum ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 51, 23, 'Et ponam illum in manu eorum qui te humiliaverunt, et dixerunt animæ tuæ: Incurvare, ut transeamus; et posuisti ut terram corpus tuum, et quasi viam transeuntibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 1, 'Consurge, consurge, induere fortitudine tua, Sion! induere vestimentis gloriæ tuæ, Jerusalem, civitas Sancti, quia non adjiciet ultra ut pertranseat per te incircumcisus et immundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 2, 'Excutere de pulvere, consurge; sede, Jerusalem! solve vincula colli tui, captiva filia Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 3, 'Quia hæc dicit Dominus: Gratis venundati estis, et sine argento redimemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 4, 'Quia hæc dicit Dominus Deus: In \'gyptum descendit populus meus in principio, ut colonus esset ibi, et Assur absque ulla causa calumniatus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 5, 'Et nunc quid mihi est hic, dicit Dominus, quoniam ablatus est populus meus gratis? Dominatores ejus inique agunt, dicit Dominus, et jugiter tota die nomen meum blasphematur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 6, 'Propter hoc sciet populus meus nomen meum in die illa: quia ego ipse qui loquebar, ecce adsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 7, 'Quam pulchri super montes pedes annuntiantis et prædicantis pacem; annuntiantis bonum, prædicantis salutem, dicentis Sion: Regnabit Deus tuus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 8, 'Vox speculatorum tuorum: levaverunt vocem, simul laudabunt, quia oculo ad oculum videbunt cum converterit Dominus Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 9, 'Gaudete, et laudate simul, deserta Jerusalem, quia consolatus est Dominus populum suum; redemit Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 10, 'Paravit Dominus brachium sanctum suum in oculis omnium gentium; et videbunt omnes fines terræ salutare Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 11, 'Recedite, recedite; exite inde, pollutum nolite tangere; exite de medio ejus; mundamini, qui fertis vasa Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 12, 'Quoniam non in tumultu exibitis, nec in fuga properabitis; præcedet enim vos Dominus, et congregabit vos Deus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 13, 'Ecce intelliget servus meus, exaltabitur et elevabitur, et sublimis erit valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 14, 'Sicut obstupuerunt super te multi, sic inglorius erit inter viros aspectus ejus, et forma ejus inter filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 52, 15, 'Iste asperget gentes multas; super ipsum continebunt reges os suum: quia quibus non est narratum de eo viderunt, et qui non audierunt contemplati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 1, 'Quis credidit auditui nostro? et brachium Domini cui revelatum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 2, 'Et ascendet sicut virgultum coram eo, et sicut radix de terra sitienti. Non est species ei, neque decor, et vidimus eum, et non erat aspectus, et desideravimus eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 3, 'despectum, et novissimum virorum, virum dolorum, et scientem infirmitatem, et quasi absconditus vultus ejus et despectus, unde nec reputavimus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 4, 'Vere languores nostros ipse tulit, et dolores nostros ipse portavit; et nos putavimus eum quasi leprosum, et percussum a Deo, et humiliatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 5, 'Ipse autem vulneratus est propter iniquitates nostras; attritus est propter scelera nostra: disciplina pacis nostræ super eum, et livore ejus sanati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 6, 'Omnes nos quasi oves erravimus, unusquisque in viam suam declinavit: et posuit Dominus in eo iniquitatem omnium nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 7, 'Oblatus est quia ipse voluit, et non aperuit os suum; sicut ovis ad occisionem ducetur, et quasi agnus coram tondente se obmutescet, et non aperiet os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 8, 'De angustia, et de judicio sublatus est. Generationem ejus quis enarrabit? quia abscissus est de terra viventium: propter scelus populi mei percussi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 9, 'Et dabit impios pro sepultura, et divitem pro morte sua, eo quod iniquitatem non fecerit, neque dolus fuerit in ore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 10, 'Et Dominus voluit conterere eum in infirmitate. Si posuerit pro peccato animam suam, videbit semen longævum, et voluntas Domini in manu ejus dirigetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 11, 'Pro eo quod laboravit anima ejus, videbit et saturabitur. In scientia sua justificabit ipse justus servus meus multos, et iniquitates eorum ipse portabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 53, 12, 'Ideo dispertiam ei plurimos, et fortium dividet spolia, pro eo quod tradidit in mortem animam suam, et cum sceleratis reputatus est, et ipse peccata multorum tulit, et pro transgressoribus rogavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 1, 'Lauda, sterilis, quæ non paris; decanta laudem, et hinni, quæ non pariebas: quoniam multi filii desertæ magis quam ejus quæ habet virum, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 2, 'Dilata locum tentorii tui, et pelles tabernaculorum tuorum extende: ne parcas: longos fac funiculos tuos, et clavos tuos consolida.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 3, 'Ad dexteram enim et ad lævam penetrabis, et semen tuum gentes hæreditabit, et civitates desertas inhabitabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 4, 'Noli timere, quia non confunderis, neque erubesces; non enim te pudebit, quia confusionis adolescentiæ tuæ oblivisceris, et opprobrii viduitatis tuæ non recordaberis amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 5, 'Quia dominabitur tui qui fecit te, Dominus exercituum nomen ejus, et redemptor tuus, Sanctus Israël: Deus omnis terræ vocabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 6, 'Quia ut mulierem derelictam et mœrentem spiritu vocavit te Dominus, et uxorem ab adolescentia abjectam, dixit Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 7, 'Ad punctum in modico dereliqui te, et in miserationibus magnis congregabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 8, 'In momento indignationis abscondi faciem meam parumper a te; et in misericordia sempiterna misertus sum tui, dixit redemptor tuus, Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 9, 'Sicut in diebus Noë istud mihi est, cui juravi ne inducerem aquas Noë ultra super terram; sic juravi ut non irascar tibi, et non increpem te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 10, 'Montes enim commovebuntur, et colles contremiscent; misericordia autem mea non recedet a te, et fœdus pacis meæ non movebitur, dixit miserator tuus Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 11, 'Paupercula, tempestate convulsa absque ulla consolatione, ecce ego sternam per ordinem lapides tuos, et fundabo te in sapphiris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 12, 'et ponam jaspidem propugnacula tua, et portas tuas in lapides sculptos, et omnes terminos tuos in lapides desiderabiles;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 13, 'universos filios tuos doctos a Domino, et multitudinem pacis filiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 14, 'Et in justitia fundaberis: recede procul a calumnia, quia non timebis, et a pavore, quia non appropinquabit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 15, 'Ecce accola veniet qui non erat mecum, advena quondam tuus adjungetur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 16, 'Ecce ego creavi fabrum sufflantem in igne prunas, et proferentem vas in opus suum; et ego creavi interfectorem ad disperdendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 54, 17, 'Omne vas quod fictum est contra te, non dirigetur, et omnem linguam resistentem tibi in judicio, judicabis. Hæc est hæreditas servorum Domini, et justitia eorum apud me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 1, 'Omnes sitientes, venite ad aquas, et qui non habetis argentum, properate, emite, et comedite: venite, emite absque argento et absque ulla commutatione vinum et lac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 2, 'Quare appenditis argentum non in panibus, et laborem vestrum non in saturitate? Audite, audientes me, et comedite bonum, et delectabitur in crassitudine anima vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 3, 'Inclinate aurem vestram, et venite ad me; audite, et vivet anima vestra, et feriam vobiscum pactum sempiternum, misericordias David fideles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 4, 'Ecce testem populis dedi eum, ducem ac præceptorem gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 5, 'Ecce gentem quam nesciebas vocabis, et gentes quæ te non cognoverunt ad te current, propter Dominum Deum tuum, et Sanctum Israël, quia glorificavit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 6, 'Quærite Dominum dum inveniri potest; invocate eum dum prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 7, 'Derelinquat impius viam suam, et vir iniquus cogitationes suas, et revertatur ad Dominum, et miserebitur ejus; et ad Deum nostrum, quoniam multus est ad ignoscendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 8, 'Non enim cogitationes meæ cogitationes vestræ, neque viæ vestræ viæ meæ, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 9, 'Quia sicut exaltantur cæli a terra, sic exaltatæ sunt viæ meæ a viis vestris, et cogitationes meæ a cogitationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 10, 'Et quomodo descendit imber et nix de cælo, et illuc ultra non revertitur, sed inebriat terram, et infundit eam, et germinare eam facit, et dat semen serenti, et panem comedenti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 11, 'sic erit verbum meum quod egredietur de ore meo; non revertetur ad me vacuum, sed faciet quæcumque volui, et prosperabitur in his ad quæ misi illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 12, 'Quia in lætitia egrediemini, et in pace deducemini; montes et colles cantabunt coram vobis laudem, et omnia ligna regionis plaudent manu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 55, 13, 'Pro saliunca ascendet abies, et pro urtica crescet myrtus; et erit Dominus nominatus in signum æternum quod non auferetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 1, 'Hæc dicit Dominus: Custodite judicium, et facite justitiam, quia juxta est salus mea ut veniat, et justitia mea ut reveletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 2, 'Beatus vir qui facit hoc, et filius hominis qui apprehendet istud, custodiens sabbatum ne polluat illud, custodiens manus suas ne faciat omne malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 3, 'Et non dicat filius advenæ qui adhæret Domino, dicens: Separatione dividet me Dominus a populo suo; et non dicat eunuchus: Ecce ego lignum aridum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 4, 'Quia hæc dicit Dominus eunuchis: Qui custodierint sabbata mea, et elegerint quæ ego volui, et tenuerint fœdus meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 5, 'dabo eis in domo mea et in muris meis locum, et nomen melius a filiis et filiabus: nomen sempiternum dabo eis, quod non peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 6, 'Et filios advenæ, qui adhærent Domino, ut colant eum, et diligant nomen ejus, ut sint ei in servos; omnem custodientem sabbatum ne polluat illud, et tenentem fœdus meum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 7, 'adducam eos in montem sanctum meum, et lætificabo eos in domo orationis meæ; holocausta eorum et victimæ eorum placebunt mihi super altari meo, quia domus mea domus orationis vocabitur cunctis populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 8, 'Ait Dominus Deus, qui congregat dispersos Israël: Adhuc congregabo ad eum congregatos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 9, 'Omnes bestiæ agri, venite ad devorandum, universæ bestiæ saltus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 10, 'Speculatores ejus cæci omnes; nescierunt universi: canes muti non valentes latrare, videntes vana, dormientes, et amantes somnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 11, 'Et canes imprudentissimi nescierunt saturitatem; ipsi pastores ignoraverunt intelligentiam: omnes in viam suam declinaverunt; unusquisque ad avaritiam suam, a summo usque ad novissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 56, 12, 'Venite, sumamus vinum, et impleamur ebrietate; et erit sicut hodie, sic et cras, et multo amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 1, 'Justus perit, et non est qui recogitet in corde suo; et viri misericordiæ colliguntur, quia non est qui intelligat: a facie enim malitiæ collectus est justus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 2, 'Veniat pax; requiescat in cubili suo qui ambulavit in directione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 3, 'Vos autem accedite huc, filii auguratricis, semen adulteri et fornicariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 4, 'Super quem lusistis? super quem dilatastis os, et ejecistis linguam? Numquid non vos filii scelesti, semen mendax,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 5, 'qui consolamini in diis subter omne lignum frondosum, immolantes parvulos in torrentibus, subter eminentes petras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 6, 'In partibus torrentis pars tua; hæc est sors tua: et ipsis effudisti libamen, obtulisti sacrificium. Numquid super his non indignabor?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 7, 'Super montem excelsum et sublimem posuisti cubile tuum, et illuc ascendisti ut immolares hostias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 8, 'Et post ostium, et retro postem, posuisti memoriale tuum. Quia juxta me discooperuisti, et suscepisti adulterum, dilatasti cubile tuum, et pepigisti cum eis fœdus; dilexisti stratum eorum manu aperta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 9, 'Et ornasti te regi unguento, et multiplicasti pigmenta tua. Misisti legatos tuos procul, et humiliata es usque ad inferos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 10, 'In multitudine viæ tuæ laborasti; non dixisti: Quiescam. Vitam manus tuæ invenisti; propterea non rogasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 11, 'Pro quo sollicita timuisti, quia mentita es, et mei non es recordata, neque cogitasti in corde tuo? Quia ego tacens et quasi non videns, et mei oblita es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 12, 'Ego annuntiabo justitiam tuam, et opera tua non proderunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 13, 'Cum clamaveris, liberent te congregati tui, et omnes eos auferet ventus, tollet aura. Qui autem fiduciam habet mei, hæreditabit terram, et possidebit montem sanctum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 14, 'Et dicam: Viam facite, præbete iter; declinate de semita, auferte offendicula de via populi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 15, 'Quia hæc dicit Excelsus, et Sublimis, habitans æternitatem, et sanctum nomen ejus: in excelso et in sancto habitans, et cum contrito et humili spiritu: ut vivificet spiritum humilium, et vivificet cor contritorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 16, 'Non enim in sempiternum litigabo, neque usque ad finem irascar, quia spiritus a facie mea egredietur, et flatus ego faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 17, 'Propter iniquitatem avaritiæ ejus iratus sum, et percussi eum. Abscondi a te faciem meam, et indignatus sum; et abiit vagus in via cordis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 18, 'Vias ejus vidi, et sanavi eum; et reduxi eum, et reddidi consolationes ipsi, et lugentibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 19, 'Creavi fructum labiorum pacem; pacem ei qui longe est et qui prope, dixit Dominus, et sanavi eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 20, 'Impii autem quasi mare fervens, quod quiescere non potest, et redundant fluctus ejus in conculcationem et lutum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 57, 21, 'Non est pax impiis, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 1, 'Clama, ne cesses, quasi tuba exalta vocem tuam, et annuntia populo meo scelera eorum, et domui Jacob peccata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 2, 'Me etenim de die in diem quærunt, et scire vias meas volunt, quasi gens quæ justitiam fecerit, et judicium Dei sui non dereliquerit. Rogant me judicia justitiæ; appropinquare Deo volunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 3, 'Quare jejunavimus, et non aspexisti; humiliavimus animas nostras, et nescisti? Ecce in die jejunii vestri invenitur voluntas vestra, et omnes debitores vestros repetitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 4, 'Ecce ad lites et contentiones jejunatis, et percutitis pugno impie. Nolite jejunare sicut usque ad hanc diem, ut audiatur in excelso clamor vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 5, 'Numquid tale est jejunium quod elegi, per diem affligere hominem animam suam? numquid contorquere quasi circulum caput suum, et saccum et cinerem sternere? numquid istud vocabis jejunium, et diem acceptabilem Domino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 6, 'Nonne hoc est magis jejunium quod elegi? Dissolve colligationes impietatis, solve fasciculos deprimentes, dimitte eos qui confracti sunt liberos, et omne onus dirumpe;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 7, 'frange esurienti panem tuum, et egenos vagosque induc in domum tuam; cum videris nudum, operi eum, et carnem tuam ne despexeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 8, 'Tunc erumpet quasi mane lumen tuum; et sanitas tua citius orietur, et anteibit faciem tuam justitia tua, et gloria Domini colliget te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 9, 'Tunc invocabis, et Dominus exaudiet; clamabis, et dicet: Ecce adsum. Si abstuleris de medio tui catenam, et desieris extendere digitum et loqui quod non prodest;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 10, 'cum effuderis esurienti animam tuam, et animam afflictam repleveris, orietur in tenebris lux tua, et tenebræ tuæ erunt sicut meridies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 11, 'Et requiem tibi dabit Dominus semper, et implebit splendoribus animam tuam, et ossa tua liberabit; et eris quasi hortus irriguus, et sicut fons aquarum cujus non deficient aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 12, 'Et ædificabuntur in te deserta sæculorum, fundamenta generationis et generationis suscitabis; et vocaberis ædificator sepium, avertens semitas in quietem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 13, 'Si averteris a sabbato pedem tuum facere voluntatem tuam in die sancto meo, et vocaveris sabbatum delicatum, et sanctum Domini gloriosum, et glorificaveris eum dum non facis vias tuas, et non invenitur voluntas tua, ut loquaris sermonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 58, 14, 'tunc delectaberis super Domino, et sustollam te super altitudines terræ, et cibabo te hæreditate Jacob patris tui: os enim Domini locutum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 1, 'Ecce non est abbreviata manus Domini, ut salvare nequeat, neque aggravata est auris ejus, ut non exaudiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 2, 'Sed iniquitates vestræ diviserunt inter vos et Deum vestrum; et peccata vestra absconderunt faciem ejus a vobis, ne exaudiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 3, 'Manus enim vestræ pollutæ sunt sanguine, et digiti vestri iniquitate; labia vestra locuta sunt mendacium, et lingua vestra iniquitatem fatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 4, 'Non est qui invocet justitiam, neque est qui judicet vere: sed confidunt in nihilo, et loquuntur vanitates; conceperunt laborem, et pepererunt iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 5, 'Ova aspidum ruperunt, et telas araneæ texuerunt. Qui comederit de ovis eorum, morietur; et quod confotum est, erumpet in regulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 6, 'Telæ eorum non erunt in vestimentum, neque operientur operibus suis; opera eorum opera inutilia, et opus iniquitatis in manibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 7, 'Pedes eorum ad malum currunt, et festinant ut effundant sanguinem innocentem; cogitationes eorum cogitationes inutiles: vastitas et contritio in viis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 8, 'Viam pacis nescierunt, et non est judicium in gressibus eorum; semitæ eorum incurvatæ sunt eis: omnis qui calcat in eis, ignorat pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 9, 'Propter hoc elongatum est judicium a nobis, et non apprehendet nos justitia. Exspectavimus lucem, et ecce tenebræ; splendorem, et in tenebris ambulavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 10, 'Palpavimus sicut cæci parietem, et quasi absque oculis attrectavimus: impegimus meridie quasi in tenebris; in caliginosis quasi mortui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 11, 'Rugiemus quasi ursi omnes, et quasi columbæ meditantes gememus: exspectavimus judicium, et non est; salutem, et elongata est a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 12, 'Multiplicatæ sunt enim iniquitates nostræ coram te, et peccata nostra responderunt nobis, quia scelera nostra nobiscum et iniquitates nostras cognovimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 13, 'Peccare et mentiri contra Dominum, et aversi sumus ne iremus post tergum Dei nostri, ut loqueremur calumniam et transgressionem; concepimus et locuti sumus de corde verba mendacii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 14, 'Et conversum est retrorsum judicium, et justitia longe stetit, quia corruit in platea veritas, et æquitas non potuit ingredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 15, 'Et facta est veritas in oblivionem, et qui recessit a malo, prædæ patuit. Et vidit Dominus, et malum apparuit in oculis ejus, quia non est judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 16, 'Et vidit quia non est vir, et aporiatus est, quia non est qui occurrat; et salvavit sibi brachium suum, et justitia ejus ipsa confirmavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 17, 'Indutus est justitia ut lorica, et galea salutis in capite ejus; indutus est vestimentis ultionis, et opertus est quasi pallio zeli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 18, 'sicut ad vindictam quasi ad retributionem indignationis hostibus suis, et vicissitudinem inimicis suis; insulis vicem reddet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 19, 'Et timebunt qui ab occidente nomen Domini, et qui ab ortu solis gloriam ejus, cum venerit quasi fluvius violentus quem spiritus Domini cogit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 20, 'et venerit Sion redemptor, et eis qui redeunt ab iniquitate in Jacob, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 59, 21, 'Hoc fœdus meum cum eis, dicit Dominus: spiritus meus qui est in te, et verba mea quæ posui in ore tuo, non recedent de ore tuo, et de ore seminis tui, et de ore seminis seminis tui, dicit Dominus, amodo et usque in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 1, 'Surge, illuminare, Jerusalem, quia venit lumen tuum, et gloria Domini super te orta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 2, 'Quia ecce tenebræ operient terram, et caligo populos; super te autem orietur Dominus, et gloria ejus in te videbitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 3, 'Et ambulabunt gentes in lumine tuo, et reges in splendore ortus tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 4, 'Leva in circuitu oculos tuos, et vide: omnes isti congregati sunt, venerunt tibi; filii tui de longe venient et filiæ tuæ de latere surgent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 5, 'Tunc videbis, et afflues; mirabitur et dilatabitur cor tuum: quando conversa fuerit ad te multitudo maris; fortitudo gentium venerit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 6, 'Inundatio camelorum operiet te, dromedarii Madian et Epha; omnes de Saba venient, aurum et thus deferentes, et laudem Domino annuntiantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 7, 'Omne pecus Cedar congregabitur tibi; arietes Nabaioth ministrabunt tibi: offerentur super placabili altari meo, et domum majestatis meæ glorificabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 8, 'Qui sunt isti qui ut nubes volant, et quasi columbæ ad fenestras suas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 9, 'Me enim insulæ exspectant, et naves maris in principio, ut adducam filios tuos de longe; argentum eorum, et aurum eorum cum eis, nomini Domini Dei tui, et Sancto Israël, quia glorificavit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 10, 'Et ædificabunt filii peregrinorum muros tuos, et reges eorum ministrabunt tibi; in indignatione enim mea percussi te, et in reconciliatione mea misertus sum tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 11, 'Et aperientur portæ tuæ jugiter; die ac nocte non claudentur, ut afferatur ad te fortitudo gentium, et reges earum adducantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 12, 'Gens enim et regnum quod non servierit tibi peribit, et gentes solitudine vastabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 13, 'Gloria Libani ad te veniet, abies, et buxus, et pinus simul ad ornandum locum sanctificationis meæ; et locum pedum meorum glorificabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 14, 'Et venient ad te curvi filii eorum qui humiliaverunt te, et adorabunt vestigia pedum tuorum omnes qui detrahebant tibi: et vocabunt te civitatem Domini, Sion Sancti Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 15, 'Pro eo quod fuisti derelicta et odio habita, et non erat qui per te transiret: ponam te in superbiam sæculorum, gaudium in generationem et generationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 16, 'et suges lac gentium, et mamilla regum lactaberis; et scies quia ego Dominus salvans te, et redemptor tuus, Fortis Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 17, 'Pro ære afferam aurum, et pro ferro afferam argentum, et pro lignis æs, et pro lapidibus ferrum: et ponam visitationem tuam pacem, et præpositos tuos justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 18, 'Non audietur ultra iniquitas in terra tua; vastitas et contritio in terminis tuis: et occupabit salus muros tuos, et portas tuas laudatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 19, 'Non erit tibi amplius sol ad lucendum per diem, nec splendor lunæ illuminabit te: sed erit tibi Dominus in lucem sempiternam, et Deus tuus in gloriam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 20, 'Non occidet ultra sol tuus, et luna tua non minuetur, quia erit tibi Dominus in lucem sempiternam, et complebuntur dies luctus tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 21, 'Populus autem tuus omnes justi; in perpetuum hæreditabunt terram: germen plantationis meæ, opus manus meæ ad glorificandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 60, 22, 'Minimus erit in mille, et parvulus in gentem fortissimam. Ego Dominus in tempore ejus subito faciam istud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 1, 'Spiritus Domini super me, eo quod unxerit Dominus me; ad annuntiandum mansuetis misit me, ut mederer contritis corde, et prædicarem captivis indulgentiam, et clausis apertionem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 2, 'ut prædicarem annum placabilem Domino, et diem ultionis Deo nostro; ut consolarer omnes lugentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 3, 'ut ponerem lugentibus Sion, et darem eis coronam pro cinere, oleum gaudii pro luctu, pallium laudis pro spiritu mœroris; et vocabuntur in ea fortes justitiæ, plantatio Domini ad glorificandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 4, 'Et ædificabunt deserta a sæculo, et ruinas antiquas erigent, et instaurabunt civitates desertas, dissipatas in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 5, 'Et stabunt alieni, et pascent pecora vestra, et filii peregrinorum agricolæ et vinitores vestri erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 6, 'Vos autem sacerdotes Domini vocabimini: Ministri Dei nostri, dicetur vobis, fortitudinem gentium comedetis, et in gloria earum superbietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 7, 'Pro confusione vestra duplici et rubore, laudabunt partem suam; propter hoc in terra sua duplicia possidebunt, lætitia sempiterna erit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 8, 'Quia ego Dominus diligens judicium, et odio habens rapinam in holocausto; et dabo opus eorum in veritate, et fœdus perpetuum feriam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 9, 'Et scient in gentibus semen eorum, et germen eorum in medio populorum; omnes qui viderint eos cognoscent illos, quia isti sunt semen cui benedixit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 10, 'Gaudens gaudebo in Domino, et exsultabit anima mea in Deo meo, quia induit me vestimentis salutis, et indumento justitiæ circumdedit me, quasi sponsum decoratum corona, et quasi sponsam ornatam monilibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 61, 11, 'Sicut enim terra profert germen suum, et sicut hortus semen suum germinat, sic Dominus Deus germinabit justitiam et laudem coram universis gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 1, 'Propter Sion non tacebo, et propter Jerusalem non quiescam, donec egrediatur ut splendor justus ejus, et salvator ejus ut lampas accendatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 2, 'Et videbunt gentes justum tuum, et cuncti reges inclytum tuum; et vocabitur tibi nomen novum, quod os Domini nominabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 3, 'Et eris corona gloriæ in manu Domini, et diadema regni in manu Dei tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 4, 'Non vocaberis ultra Derelicta, et terra tua non vocabitur amplius Desolata; sed vocaberis, Voluntas mea in ea, et terra tua Inhabitata, quia complacuit Domino in te, et terra tua inhabitabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 5, 'Habitabit enim juvenis cum virgine, et habitabunt in te filii tui; et gaudebit sponsus super sponsam, et gaudebit super te Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 6, 'Super muros tuos, Jerusalem, constitui custodes; tota die et tota nocte in perpetuum non tacebunt. Qui reminiscimini Domini, ne taceatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 7, 'et ne detis silentium ei, donec stabiliat et donec ponat Jerusalem laudem in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 8, 'Juravit Dominus in dextera sua, et in brachio fortitudinis suæ: Si dedero triticum tuum ultra cibum inimicis tuis; et si biberint filii alieni vinum tuum in quo laborasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 9, 'Quia qui congregant illud, comedent, et laudabunt Dominum; et qui comportant illud, bibent in atriis sanctis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 10, 'Transite, transite per portas, præparate viam populo: planum facite iter, eligite lapides, et elevate signum ad populos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 11, 'Ecce Dominus auditum fecit in extremis terræ: Dicite filiæ Sion: Ecce Salvator tuus venit; ecce merces ejus cum eo, et opus ejus coram illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 62, 12, 'Et vocabunt eos, Populus sanctus, redempti a Domino; tu autem vocaberis, Quæsita civitas, et non Derelicta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 1, 'Quis est iste, qui venit de Edom, tinctis vestibus de Bosra? iste formosus in stola sua, gradiens in multitudine fortitudinis suæ? Ego qui loquor justitiam, et propugnator sum ad salvandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 2, 'Quare ergo rubrum est indumentum tuum, et vestimenta tua sicut calcantium in torculari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 3, 'Torcular calcavi solus, et de gentibus non est vir mecum; calcavi eos in furore meo, et conculcavi eos in ira mea: et aspersus est sanguis eorum super vestimenta mea, et omnia indumenta mea inquinavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 4, 'Dies enim ultionis in corde meo; annus redemptionis meæ venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 5, 'Circumspexi, et non erat auxiliator; quæsivi, et non fuit qui adjuvaret: et salvavit mihi brachium meum, et indignatio mea ipsa auxiliata est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 6, 'Et conculcavi populos in furore meo, et inebriavi eos in indignatione mea, et detraxi in terram virtutem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 7, 'Miserationum Domini recordabor; laudem Domini super omnibus quæ reddidit nobis Dominus, et super multitudinem bonorum domui Israël, quæ largitus est eis secundum indulgentiam suam, et secundum multitudinem misericordiarum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 8, 'Et dixit: Verumtamen populus meus est, filii non negantes; et factus est eis salvator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 9, 'In omni tribulatione eorum non est tribulatus, et angelus faciei ejus salvavit eos: in dilectione sua et in indulgentia sua ipse redemit eos, et portavit eos, et elevavit eos cunctis diebus sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 10, 'Ipsi autem ad iracundiam provocaverunt, et afflixerunt spiritum Sancti ejus: et conversus est eis in inimicum, et ipse debellavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 11, 'Et recordatus est dierum sæculi Moysi, et populi sui. Ubi est qui eduxit eos de mari cum pastoribus gregis sui? Ubi est qui posuit in medio ejus spiritum Sancti sui;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 12, 'qui eduxit ad dexteram Moysen, brachio majestatis suæ; qui scidit aquas ante eos, ut faceret sibi nomen sempiternum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 13, 'qui eduxit eos per abyssos, quasi equum in deserto non impingentem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 14, 'Quasi animal in campo descendens, spiritus Domini ductor ejus fuit. Sic adduxisti populum tuum, ut faceres tibi nomen gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 15, 'Attende de cælo, et vide de habitaculo sancto tuo, et gloriæ tuæ. Ubi est zelus tuus, et fortitudo tua, multitudo viscerum tuorum et miserationum tuarum? Super me continuerunt se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 16, 'Tu enim pater noster: et Abraham nescivit nos, et Israël ignoravit nos: tu, Domine, pater noster, redemptor noster, a sæculo nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 17, 'Quare errare nos fecisti, Domine, de viis tuis; indurasti cor nostrum ne timeremus te? Convertere propter servos tuos, tribus hæreditatis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 18, 'Quasi nihilum possederunt populum sanctum tuum: hostes nostri conculcaverunt sanctificationem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 63, 19, 'Facti sumus quasi in principio, cum non dominareris nostri, neque invocaretur nomen tuum super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 1, 'Utinam dirumperes cælos, et descenderes; a facie tua montes defluerent;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 2, 'sicut exustio ignis tabescerent, aquæ arderent igni: ut notum fieret nomen tuum inimicis tuis; a facie tua gentes turbarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 3, 'Cum feceris mirabilia, non sustinebimus; descendisti, et a facie tua montes defluxerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 4, 'A sæculo non audierunt, neque auribus perceperunt; oculus non vidit, Deus, absque te, quæ præparasti exspectantibus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 5, 'Occurristi lætanti, et facienti justitiam; in viis tuis recordabuntur tui. Ecce tu iratus es, et peccavimus; in ipsis fuimus semper, et salvabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 6, 'Et facti sumus ut immundus omnes nos, et quasi pannus menstruatæ universæ justitiæ nostræ; et cecidimus quasi folium universi, et iniquitates nostræ quasi ventus abstulerunt nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 7, 'Non est qui invocet nomen tuum; qui consurgat, et teneat te. Abscondisti faciem tuam a nobis, et allisisti nos in manu iniquitatis nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 8, 'Et nunc, Domine, pater noster es tu, nos vero lutum; et fictor noster tu, et opera manuum tuarum omnes nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 9, 'Ne irascaris, Domine, satis, et ne ultra memineris iniquitatis nostræ; ecce, respice, populus tuus omnes nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 10, 'Civitas Sancti tui facta est deserta, Sion deserta facta est, Jerusalem desolata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 11, 'Domus sanctificationis nostræ et gloriæ nostræ, ubi laudaverunt te patres nostri, facta est in exustionem ignis, et omnia desiderabilia nostra versa sunt in ruinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 64, 12, 'Numquid super his continebis te, Domine; tacebis, et affliges nos vehementer?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 1, 'Quæsierunt me qui ante non interrogabant; invenerunt qui non quæsierunt me. Dixi: Ecce ego, ecce ego, ad gentem quæ non invocabat nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 2, 'Expandi manus meas tota die ad populum incredulum, qui graditur in via non bona post cogitationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 3, 'Populus qui ad iracundiam provocat me ante faciem meam semper; qui immolant in hortis, et sacrificant super lateres;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 4, 'qui habitant in sepulchris, et in delubris idolorum dormiunt; qui comedunt carnem suillam, et jus profanum in vasis eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 5, 'qui dicunt: Recede a me, non appropinques mihi, quia immundus es. Isti fumus erunt in furore meo, ignis ardens tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 6, 'Ecce scriptum est coram me: Non tacebo, sed reddam, et retribuam in sinum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 7, 'Iniquitates vestras, et iniquitates patrum vestrorum simul, dicit Dominus; qui sacrificaverunt super montes, et super colles exprobraverunt mihi; et remetiar opus eorum primum in sinu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 8, 'Hæc dicit Dominus: Quomodo si inveniatur granum in botro, et dicatur: Ne dissipes illud, quoniam benedictio est: sic faciam propter servos meos, ut non disperdam totum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 9, 'Et educam de Jacob semen, et de Juda possidentem montes meos; et hæreditabunt eam electi mei, et servi mei habitabunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 10, 'Et erunt campestria in caulas gregum, et vallis Achor in cubile armentorum, populo meo qui requisierunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 11, 'Et vos qui dereliquistis Dominum, qui obliti estis montem sanctum meum, qui ponitis fortunæ mensam, et libatis super eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 12, 'numerabo vos in gladio, et omnes in cæde corruetis: pro eo quod vocavi, et non respondistis; locutus sum, et non audistis; et faciebatis malum in oculis meis, et quæ nolui elegistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 13, 'Propter hoc hæc dicit Dominus Deus: Ecce servi mei comedent, et vos esurietis; ecce servi mei bibent, et vos sitietis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 14, 'ecce servi mei lætabuntur, et vos confundemini; ecce servi mei laudabunt præ exsultatione cordis, et vos clamabitis præ dolore cordis, et præ contritione spiritus ululabitis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 15, 'et dimittetis nomen vestrum in juramentum electis meis; et interficiet te Dominus Deus, et servos suos vocabit nomine alio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 16, 'in quo qui benedictus est super terram benedicetur in Deo, amen, et qui jurat in terra jurabit in Deo, amen: quia oblivioni traditæ sunt angustiæ priores, et quia absconditæ sunt ab oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 17, 'Ecce enim ego creo cælos novos, et terram novam; et non erunt in memoria priora, et non ascendent super cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 18, 'Sed gaudebitis et exsultabitis usque in sempiternum in his quæ ego creo: quia ecce ego creo Jerusalem exsultationem, et populum ejus gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 19, 'Et exsultabo in Jerusalem, et gaudebo in populo meo, et non audietur in eo ultra vox fletus et vox clamoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 20, 'Non erit ibi amplius infans dierum, et senex qui non impleat dies suos, quoniam puer centum annorum morietur, et peccator centum annorum maledictus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 21, 'Et ædificabunt domos, et habitabunt; et plantabunt vineas, et comedent fructus earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 22, 'Non ædificabunt, et alius habitabit; non plantabunt, et alius comedet: secundum enim dies ligni erunt dies populi mei, et opera manuum eorum inveterabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 23, 'Electi mei non laborabunt frustra, neque generabunt in conturbatione, quia semen benedictorum Domini est, et nepotes eorum cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 24, 'Eritque antequam clament, ego exaudiam; adhuc illis loquentibus, ego audiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 65, 25, 'Lupus et agnus pascentur simul, leo et bos comedent paleas, et serpenti pulvis panis ejus. Non nocebunt, neque occident in omni monte sancto meo, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 1, 'Hæc dicit Dominus: Cælum sedes mea, terra autem scabellum pedum meorum. Quæ est ista domus quam ædificabitis mihi? et quis est iste locus quietis meæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 2, 'Omnia hæc manus mea fecit, et facta sunt universa ista, dicit Dominus; ad quem autem respiciam, nisi ad pauperculum, et contritum spiritu, et trementem sermones meos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 3, 'Qui immolat bovem, quasi qui interficiat virum; qui mactat pecus, quasi qui excerebret canem; qui offert oblationem, quasi qui sanguinem suillum offerat; qui recordatur thuris, quasi qui benedicat idolo. Hæc omnia elegerunt in viis suis, et in abominationibus suis anima eorum delectata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 4, 'Unde et ego eligam illusiones eorum, et quæ timebant adducam eis; quia vocavi, et non erat qui responderet; locutus sum, et non audierunt; feceruntque malum in oculis meis, et quæ nolui elegerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 5, 'Audite verbum Domini, qui tremitis ad verbum ejus. Dixerunt fratres vestri odientes vos, et abjicientes propter nomen meum: Glorificetur Dominus, et videbimus in lætitia vestra; ipsi autem confundentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 6, 'Vox populi de civitate, vox de templo, vox Domini reddentis retributionem inimicis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 7, 'Antequam parturiret, peperit; antequam veniret partus ejus, peperit masculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 8, 'Quis audivit umquam tale? et quis vidit huic simile? numquid parturiet terra in die una, aut parietur gens simul, quia parturivit et peperit Sion filios suos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 9, 'Numquid ego qui alios parere facio, ipse non pariam? dicit Dominus. Si ego, qui generationem ceteris tribuo, sterilis ero? ait Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 10, 'Lætamini cum Jerusalem et exsultate in ea, omnes qui diligitis eam; gaudete cum ea gaudio, universi qui lugetis super eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 11, 'ut sugatis et repleamini ab ubere consolationis ejus; ut mulgeatis et deliciis affluatis ab omnimoda gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 12, 'Quia hæc dicit Dominus: Ecce ego declinabo super eam quasi fluvium pacis, et quasi torrentem inundantem gloriam gentium, quam sugetis: ad ubera portabimini, et super genua blandientur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 13, 'Quomodo si cui mater blandiatur, ita ego consolabor vos, et in Jerusalem consolabimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 14, 'Videbitis, et gaudebit cor vestrum, et ossa vestra quasi herba germinabunt: et cognoscetur manus Domini servis ejus, et indignabitur inimicis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 15, 'Quia ecce Dominus in igne veniet, et quasi turbo quadrigæ ejus, reddere in indignatione furorem suum et increpationem suam in flamma ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 16, 'quia in igne Dominus dijudicabit, et in gladio suo ad omnem carnem; et multiplicabuntur interfecti a Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 17, 'qui sanctificabantur et mundos se putabant in hortis post januam intrinsecus, qui comedebant carnem suillam, et abominationem et murem: simul consumentur, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 18, 'Ego autem opera eorum et cogitationes eorum venio ut congregem, cum omnibus gentibus et linguis: et venient, et videbunt gloriam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 19, 'Et ponam in eis signum, et mittam ex eis qui salvati fuerint, ad gentes in mare, in Africam, et Lydiam, tendentes sagittam; in Italiam et Græciam, ad insulas longe, ad eos qui non audierunt de me, et non viderunt gloriam meam. Et annuntiabunt gloriam meam gentibus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 20, 'et adducent omnes fratres vestros de cunctis gentibus donum Domino, in equis, et in quadrigis, et in lecticis, et in mulis, et in carrucis, ad montem sanctum meum Jerusalem, dicit Dominus: quomodo si inferant filii Israël munus in vase mundo in domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 21, 'Et assumam ex eis in sacerdotes et Levitas, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 22, 'Quia sicut cæli novi et terra nova, quæ ego facio stare coram me, dicit Dominus, sic stabit semen vestrum et nomen vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 23, 'Et erit mensis ex mense, et sabbatum ex sabbato: veniet omnis caro ut adoret coram facie mea, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 66, 24, 'Et egredientur, et videbunt cadavera virorum qui prævaricati sunt in me; vermis eorum non morietur, et ignis eorum non extinguetur: et erunt usque ad satietatem visionis omni carni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Verba Jeremiæ filii Helciæ, de sacerdotibus qui fuerunt in Anathoth, in terra Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Quod factum est verbum Domini ad eum in diebus Josiæ filii Amon, regis Juda, in tertiodecimo anno regni ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Et factum est in diebus Joakim filii Josiæ, regis Juda, usque ad consummationem undecimi anni Sedeciæ, filii Josiæ, regis Juda, usque ad transmigrationem Jerusalem, in mense quinto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Priusquam te formarem in utero, novi te, et antequam exires de vulva, sanctificavi te, et prophetam in gentibus dedi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Et dixi: A, a, a, Domine Deus, ecce nescio loqui, quia puer ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Et dixit Dominus ad me: Noli dicere: Puer sum: quoniam ad omnia quæ mittam te ibis, et universa quæcumque mandavero tibi loqueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Ne timeas a facie eorum, quia tecum ego sum ut eruam te, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Et misit Dominus manum suam, et tetigit os meum, et dixit Dominus ad me: Ecce dedi verba mea in ore tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'ecce constitui te hodie super gentes et super regna, ut evellas, et destruas, et disperdas, et dissipes, et ædifices, et plantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Et factum est verbum Domini ad me, dicens: Quid tu vides, Jeremia? Et dixi: Virgam vigilantem ego video.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 12, 'Et dixit Dominus ad me: Bene vidisti: quia vigilabo ego super verbo meo, ut faciam illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 13, 'Et factum est verbum Domini secundo ad me, dicens: Quid tu vides? Et dixi: Ollam succensam ego video, et faciem ejus a facie aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 14, 'Et dixit Dominus ad me: Ab aquilone pandetur malum super omnes habitatores terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 15, 'quia ecce ego convocabo omnes cognationes regnorum aquilonis, ait Dominus: et venient, et ponent unusquisque solium suum in introitu portarum Jerusalem, et super omnes muros ejus in circuitu, et super universas urbes Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 16, 'et loquar judicia mea cum eis super omnem malitiam eorum qui dereliquerunt me, et libaverunt diis alienis, et adoraverunt opus manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 17, 'Tu ergo, accinge lumbos tuos, et surge, et loquere ad eos omnia quæ ego præcipio tibi. Ne formides a facie eorum, nec enim timere te faciam vultum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 18, 'Ego quippe dedi te hodie in civitatem munitam, et in columnam ferream, et in murum æreum, super omnem terram, regibus Juda, principibus ejus, et sacerdotibus, et populo terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 19, 'Et bellabunt adversum te, et non prævalebunt, quia ego tecum sum, ait Dominus, ut liberem te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Vade, et clama in auribus Jerusalem, dicens: Hæc dicit Dominus: Recordatus sum tui, miserans adolescentiam tuam, et caritatem desponsationis tuæ, quando secuta es me in deserto, in terra quæ non seminatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Sanctus Israël Domino, primitiæ frugum ejus: omnes qui devorant eum delinquunt: mala venient super eos, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Audite verbum Domini, domus Jacob, et omnes cognationes domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Hæc dicit Dominus: Quid invenerunt patres vestri in me iniquitatis, quia elongaverunt a me, et ambulaverunt post vanitatem, et vani facti sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Et non dixerunt: Ubi est Dominus qui ascendere nos fecit de terra \'gypti; qui traduxit nos per desertum, per terram inhabitabilem et inviam, per terram sitis, et imaginem mortis, per terram in qua non ambulavit vir, neque habitavit homo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Et induxi vos in terram Carmeli, ut comederetis fructum ejus et optima illius: et ingressi contaminastis terram meam, et hæreditatem meam posuistis in abominationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Sacerdotes non dixerunt: Ubi est Dominus? et tenentes legem nescierunt me, et pastores prævaricati sunt in me, et prophetæ prophetaverunt in Baal, et idola secuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Propterea adhuc judicio contendam vobiscum, ait Dominus, et cum filiis vestris disceptabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Transite ad insulas Cethim, et videte: et in Cedar mittite, et considerate vehementer: et videte si factum est hujuscemodi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'si mutavit gens deos suos, et certe ipsi non sunt dii: populus vero meus mutavit gloriam suam in idolum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Obstupescite, cæli, super hoc, et portæ ejus, desolamini vehementer, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Duo enim mala fecit populus meus: me dereliquerunt fontem aquæ vivæ, et foderunt sibi cisternas, cisternas dissipatas, quia continere non valent aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Numquid servus est Israël, aut vernaculus? quare ergo factus est in prædam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Super eum rugierunt leones, et dederunt vocem suam: posuerunt terram ejus in solitudinem. Civitates ejus exustæ sunt, et non est qui habitet in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Filii quoque Mempheos et Taphnes constupraverunt te usque ad verticem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Numquid non istud factum est tibi, quia dereliquisti Dominum Deum tuum eo tempore quo ducebat te per viam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Et nunc quid tibi vis in via \'gypti, ut bibas aquam turbidam? et quid tibi cum via Assyriorum, ut bibas aquam fluminis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Arguet te malitia tua, et aversio tua increpabit te. Scito et vide quia malum et amarum est reliquisse te Dominum Deum tuum, et non esse timorem mei apud te, dicit Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'A sæculo confregisti jugum meum: rupisti vincula mea, et dixisti: Non serviam. In omni enim colle sublimi, et sub omni ligno frondoso, tu prosternebaris meretrix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Ego autem plantavi te vineam electam, omne semen verum: quomodo ergo conversa es mihi in pravum, vinea aliena?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Si laveris te nitro, et multiplicaveris tibi herbam borith, maculata es in iniquitate tua coram me, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Quomodo dicis: Non sum polluta; post Baalim non ambulavi? Vide vias tuas in convalle; scito quid feceris: cursor levis explicans vias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'Onager assuetus in solitudine, in desiderio animæ suæ attraxit ventum amoris sui: nullus avertet eam: omnes qui quærunt eam non deficient: in menstruis ejus invenient eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Prohibe pedem tuum a nuditate, et guttur tuum a siti. Et dixisti: Desperavi: nequaquam faciam: adamavi quippe alienos, et post eos ambulabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 26, 'Quomodo confunditur fur quando deprehenditur, sic confusi sunt domus Israël, ipsi et reges eorum, principes, et sacerdotes, et prophetæ eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 27, 'dicentes ligno: Pater meus es tu: et lapidi: Tu me genuisti. Verterunt ad me tergum et non faciem, et in tempore afflictionis suæ dicent: Surge, et libera nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 28, 'Ubi sunt dii tui quos fecisti tibi? surgant, et liberent te in tempore afflictionis tuæ: secundum numerum quippe civitatum tuarum erant dii tui, Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 29, 'Quid vultis mecum judicio contendere? omnes dereliquistis me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 30, 'Frustra percussi filios vestros: disciplinam non receperunt. Devoravit gladius vester prophetas vestros: quasi leo vastator');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 31, 'generatio vestra. Videte verbum Domini: numquid solitudo factus sum Israëli, aut terra serotina? quare ergo dixit populus meus: Recessimus; non veniemus ultra ad te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 32, 'Numquid obliviscetur virgo ornamenti sui, aut sponsa fasciæ pectoralis suæ? populus vero meus oblitus est mei diebus innumeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 33, 'Quid niteris bonam ostendere viam tuam ad quærendam dilectionem, quæ insuper et malitias tuas docuisti vias tuas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 34, 'et in alis tuis inventus est sanguis animarum pauperum et innocentum? non in fossis inveni eos, sed in omnibus quæ supra memoravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 35, 'Et dixisti: Absque peccato et innocens ego sum, et propterea avertatur furor tuus a me. Ecce ego judicio contendam tecum, eo quod dixeris: Non peccavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 36, 'Quam vilis facta es nimis, iterans vias tuas! et ab \'gypto confunderis, sicut confusa es ab Assur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 37, 'Nam et ab ista egredieris, et manus tuæ erunt super caput tuum: quoniam obtrivit Dominus confidentiam tuam, et nihil habebis prosperum in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Vulgo dicitur: Si dimiserit vir uxorem suam, et recedens ab eo duxerit virum alterum, numquid revertetur ad eam ultra? numquid non polluta et contaminata erit mulier illa? Tu autem fornicata es cum amatoribus multis: tamen revertere ad me, dicit Dominus, et ego suscipiam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Leva oculos tuos in directum, et vide ubi non prostrata sis. In viis sedebas, exspectans eos quasi latro in solitudine: et polluisti terram in fornicationibus tuis, et in malitiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Quam ob rem prohibitæ sunt stillæ pluviarum, et serotinus imber non fuit. Frons mulieris meretricis facta est tibi; noluisti erubescere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Ergo saltem amodo voca me: Pater meus, dux virginitatis meæ tu es:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'numquid irasceris in perpetuum, aut perseverabis in finem? ecce locuta es, et fecisti mala, et potuisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 6, 'Et dixit Dominus ad me in diebus Josiæ regis: Numquid vidisti quæ fecerit aversatrix Israël? Abiit sibimet super omnem montem excelsum, et sub omni ligno frondoso, et fornicata est ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 7, 'Et dixi, cum fecisset hæc omnia: Ad me revertere: et non est reversa. Et vidit prævaricatrix soror ejus Juda');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 8, 'quia pro eo quod mœchata esset aversatrix Israël, dimisissem eam, et dedissem ei libellum repudii: et non timuit prævaricatrix Juda soror ejus, sed abiit, et fornicata est etiam ipsa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 9, 'et facilitate fornicationis suæ contaminavit terram, et mœchata est cum lapide et ligno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 10, 'et in omnibus his non est reversa ad me prævaricatrix soror ejus Juda in toto corde suo, sed in mendacio, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 11, 'Et dixit Dominus ad me: Justificavit animam suam aversatrix Israël, comparatione prævaricatricis Judæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 12, 'Vade, et clama sermones istos contra aquilonem, et dices: Revertere, aversatrix Israël, ait Dominus, et non avertam faciem meam a vobis, quia sanctus ego sum, dicit Dominus, et non irascar in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 13, 'Verumtamen scito iniquitatem tuam, quia in Dominum Deum tuum prævaricata es, et dispersisti vias tuas alienis sub omni ligno frondoso, et vocem meam non audisti, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 14, 'Convertimini, filii revertentes, dicit Dominus, quia ego vir vester: et assumam vos unum de civitate, et duos de cognatione, et introducam vos in Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 15, 'Et dabo vobis pastores juxta cor meum, et pascent vos scientia et doctrina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 16, 'Cumque multiplicati fueritis, et creveritis in terra in diebus illis, ait Dominus, non dicent ultra: Arca testamenti Domini: neque ascendet super cor, neque recordabuntur illius, nec visitabitur, nec fiet ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 17, 'In tempore illo vocabunt Jerusalem solium Domini: et congregabuntur ad eam omnes gentes in nomine Domini in Jerusalem, et non ambulabunt post pravitatem cordis sui pessimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 18, 'In diebus illis ibit domus Juda ad domum Israël, et venient simul de terra aquilonis ad terram quam dedi patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 19, 'Ego autem dixi: Quomodo ponam te in filios, et tribuam tibi terram desiderabilem, hæreditatem præclaram exercituum gentium? Et dixi: Patrem vocabis me, et post me ingredi non cessabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 20, 'Sed quomodo si contemnat mulier amatorem suum, sic contempsit me domus Israël, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 21, 'Vox in viis audita est, ploratus et ululatus filiorum Israël: quoniam iniquam fecerunt viam suam; obliti sunt Domini Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 22, 'Convertimini, filii revertentes, et sanabo aversiones vestras. Ecce nos venimus ad te: tu enim es Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 23, 'Vere mendaces erant colles, et multitudo montium: vere in Domino Deo nostro salus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 24, 'Confusio comedit laborem patrum nostrorum ab adolescentia nostra: greges eorum, et armenta eorum, filios eorum, et filias eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 25, 'Dormiemus in confusione nostra, et operiet nos ignominia nostra: quoniam Domino Deo nostro peccavimus nos, et patres nostri, ab adolescentia nostra usque ad diem hanc: et non audivimus vocem Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Si reverteris, Israël, ait Dominus, ad me convertere: si abstuleris offendicula tua a facie mea, non commoveberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Et jurabis: Vivit Dominus in veritate, et in judicio, et in justitia: et benedicent eum gentes, ipsumque laudabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Hæc enim dicit Dominus viro Juda et Jerusalem: Novate vobis novale, et nolite serere super spinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Circumcidimini Domino, et auferte præputia cordium vestrorum, viri Juda, et habitatores Jerusalem: ne forte egrediatur ut ignis indignatio mea, et succendatur, et non sit qui extinguat, propter malitiam cogitationum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Annuntiate in Juda, et in Jerusalem auditum facite: loquimini, et canite tuba in terra, clamate fortiter, et dicite: Congregamini, et ingrediamur civitates munitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Levate signum in Sion; confortamini, nolite stare: quia malum ego adduco ab aquilone, et contritionem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Ascendit leo de cubili suo, et prædo gentium se levavit: egressus est de loco suo ut ponat terram tuam in solitudinem: civitates tuæ vastabuntur, remanentes absque habitatore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Super hoc accingite vos ciliciis; plangite, et ululate: quia non est aversa ira furoris Domini a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Et erit in die illa, dicit Dominus: peribit cor regis, et cor principum, et obstupescent sacerdotes, et prophetæ consternabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Et dixi: Heu! heu! heu! Domine Deus, ergone decepisti populum istum et Jerusalem, dicens: Pax erit vobis: et ecce pervenit gladius usque ad animam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'In tempore illo dicetur populo huic et Jerusalem: Ventus urens in viis quæ sunt in deserto viæ filiæ populi mei, non ad ventilandum et ad purgandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Spiritus plenus ex his veniet mihi, et nunc ego loquar judicia mea cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Ecce quasi nubes ascendet, et quasi tempestas currus ejus: velociores aquilis equi illius. Væ nobis, quoniam vastati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Lava a malitia cor tuum, Jerusalem, ut salva fias: usquequo morabuntur in te cogitationes noxiæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Vox enim annuntiantis a Dan, et notum facientis idolum de monte Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Dicite gentibus: Ecce auditum est in Jerusalem custodes venire de terra longinqua, et dare super civitates Juda vocem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'quasi custodes agrorum facti sunt super eam in gyro, quia me ad iracundiam provocavit, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Viæ tuæ et cogitationes tuæ fecerunt hæc tibi: ista malitia tua, quia amara, quia tetigit cor tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Ventrem meum, ventrem meum doleo; sensus cordis mei turbati sunt in me. Non tacebo, quoniam vocem buccinæ audivit anima mea, clamorem prælii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 20, 'Contritio super contritionem vocata est, et vastata est omnis terra: repente vastata sunt tabernacula mea; subito pelles meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 21, 'Usquequo videbo fugientem; audiam vocem buccinæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 22, 'Quia stultus populus meus me non cognovit: filii insipientes sunt et vecordes: sapientes sunt ut faciant mala, bene autem facere nescierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 23, 'Aspexi terram, et ecce vacua erat et nihili; et cælos, et non erat lux in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 24, 'Vidi montes, et ecce movebantur: et omnes colles conturbati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 25, 'Intuitus sum, et non erat homo: et omne volatile cæli recessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 26, 'Aspexi, et ecce Carmelus desertus, et omnes urbes ejus destructæ sunt a facie Domini, et a facie iræ furoris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 27, 'Hæc enim dicit Dominus: Deserta erit omnis terra, sed tamen consummationem non faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 28, 'Lugebit terra, et mœrebunt cæli desuper, eo quod locutus sum. Cogitavi, et non pœnituit me, nec aversus sum ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 29, 'A voce equitis et mittentis sagittam fugit omnis civitas: ingressi sunt ardua, et ascenderunt rupes: universæ urbes derelictæ sunt, et non habitat in eis homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 30, 'Tu autem vastata, quid facies? cum vestieris te coccino, cum ornata fueris monili aureo, et pinxeris stibio oculos tuos, frustra componeris: contempserunt te amatores tui; animam tuam quærent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 31, 'Vocem enim quasi parturientis audivi, angustias ut puerperæ: vox filiæ Sion intermorientis, expandentisque manus suas: Væ mihi, quia defecit anima mea propter interfectos!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Circuite vias Jerusalem, et aspicite, et considerate, et quærite in plateis ejus, an inveniatis virum facientem judicium, et quærentem fidem: et propitius ero ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Quod si etiam: Vivit Dominus, dixerint, et hoc falso jurabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Domine, oculi tui respiciunt fidem: percussisti eos, et non doluerunt; attrivisti eos, et renuerunt accipere disciplinam: induraverunt facies suas supra petram, et noluerunt reverti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ego autem dixi: Forsitan pauperes sunt et stulti, ignorantes viam Domini, judicium Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Ibo igitur ad optimates, et loquar eis: ipsi enim cognoverunt viam Domini, judicium Dei sui: et ecce magis hi simul confregerunt jugum; ruperunt vincula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Idcirco percussit eos leo de silva; lupus ad vesperam vastavit eos: pardus vigilans super civitates eorum: omnis qui egressus fuerit ex eis capietur: quia multiplicatæ sunt prævaricationes eorum; confortatæ sunt aversiones eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Super quo propitius tibi esse potero? filii tui dereliquerunt me, et jurant in his qui non sunt dii. Saturavi eos, et mœchati sunt, et in domo meretricis luxuriabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Equi amatores et emissarii facti sunt: unusquisque ad uxorem proximi sui hinniebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Numquid super his non visitabo, dicit Dominus, et in gente tali non ulciscetur anima mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Ascendite muros ejus, et dissipate: consummationem autem nolite facere: auferte propagines ejus, quia non sunt Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Prævaricatione enim prævaricata est in me domus Israël, et domus Juda, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Negaverunt Dominum, et dixerunt: Non est ipse: neque veniet super nos malum: gladium et famem non videbimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Prophetæ fuerunt in ventum locuti, et responsum non fuit in eis: hæc ergo evenient illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Hæc dicit Dominus Deus exercituum: Quia locuti estis verbum istud, ecce ego do verba mea in ore tuo in ignem, et populum istum in ligna, et vorabit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ecce ego adducam super vos gentem de longinquo, domus Israël, ait Dominus: gentem robustam, gentem antiquam, gentem cujus ignorabis linguam, nec intelliges quid loquatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 16, 'Pharetra ejus quasi sepulchrum patens; universi fortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 17, 'Et comedet segetes tuas et panem tuum; devorabit filios tuos et filias tuas; comedet gregem tuum et armenta tua; comedet vineam tuam et ficum tuam: et conteret urbes munitas tuas, in quibus tu habes fiduciam, gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 18, 'Verumtamen in diebus illis, ait Dominus, non faciam vos in consummationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 19, 'Quod si dixeritis: Quare fecit nobis Dominus Deus noster hæc omnia? dices ad eos: Sicut dereliquistis me, et servistis deo alieno in terra vestra, sic servietis alienis in terra non vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 20, 'Annuntiate hoc domui Jacob, et auditum facite in Juda, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 21, 'Audi, popule stulte, qui non habes cor: qui habentes oculos, non videtis; et aures, et non auditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 22, 'Me ergo non timebitis, ait Dominus, et a facie mea non dolebitis? qui posui arenam terminum mari, præceptum sempiternum quod non præteribit: et commovebuntur, et non poterunt; et intumescent fluctus ejus, et non transibunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 23, 'Populo autem huic factum est cor incredulum et exasperans: recesserunt, et abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 24, 'Et non dixerunt in corde suo: Metuamus Dominum Deum nostrum, qui dat nobis pluviam temporaneam et serotinam in tempore suo, plenitudinem annuæ messis custodientem nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 25, 'Iniquitates vestræ declinaverunt hæc, et peccata vestra prohibuerunt bonum a vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 26, 'quia inventi sunt in populo meo impii insidiantes quasi aucupes, laqueos ponentes et pedicas ad capiendos viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 27, 'Sicut decipula plena avibus, sic domus eorum plenæ dolo: ideo magnificati sunt et ditati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 28, 'Incrassati sunt et impinguati, et præterierunt sermones meos pessime. Causam viduæ non judicaverunt, causam pupilli non direxerunt, et judicium pauperum non judicaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 29, 'Numquid super his non visitabo, dicit Dominus, aut super gentem hujuscemodi non ulciscetur anima mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 30, 'Stupor et mirabilia facta sunt in terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 31, 'prophetæ prophetabant mendacium, et sacerdotes applaudebant manibus suis, et populus meus dilexit talia. Quid igitur fiet in novissimo ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Confortamini, filii Benjamin, in medio Jerusalem: et in Thecua clangite buccina, et super Bethacarem levate vexillum, quia malum visum est ab aquilone, et contritio magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Speciosæ et delicatæ assimilavi filiam Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Ad eam venient pastores et greges eorum; fixerunt in ea tentoria in circuitu: pascet unusquisque eos qui sub manu sua sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Sanctificate super eam bellum: consurgite, et ascendamus in meridie: væ nobis, quia declinavit dies; quia longiores factæ sunt umbræ vesperi!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Surgite, et ascendamus in nocte, et dissipemus domus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Quia hæc dicit Dominus exercituum: Cædite lignum ejus, et fundite circa Jerusalem aggerem. Hæc est civitas visitationis: omnis calumnia in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Sicut frigidam fecit cisterna aquam suam, sic frigidam fecit malitiam suam. Iniquitas et vastitas audietur in ea, coram me semper infirmitas et plaga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Erudire, Jerusalem, ne forte recedat anima mea a te; ne forte ponam te desertam, terram inhabitabilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Hæc dicit Dominus exercituum: Usque ad racemum colligent quasi in vinea reliquias Israël. Converte manum tuam quasi vindemiator ad cartallum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Cui loquar, et quem contestabor ut audiat? ecce incircumcisæ aures eorum, et audire non possunt: ecce verbum Domini factum est eis in opprobrium, et non suscipient illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Idcirco furore Domini plenus sum; laboravi sustinens. Effunde super parvulum foris, et super consilium juvenum simul: vir enim cum muliere capietur; senex cum pleno dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 12, 'Et transibunt domus eorum ad alteros, agri et uxores pariter, quia extendam manum meam super habitantes terram, dicit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 13, 'a minore quippe usque ad majorem omnes avaritiæ student, et a propheta usque ad sacerdotem cuncti faciunt dolum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 14, 'Et curabant contritionem filiæ populi mei cum ignominia, dicentes: Pax, pax! et non erat pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 15, 'Confusi sunt, quia abominationem fecerunt: quin potius confusione non sunt confusi, et erubescere nescierunt. Quam ob rem cadent inter ruentes: in tempore visitationis suæ corruent, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 16, 'Hæc dicit Dominus: State super vias, et videte, et interrogate de semitis antiquis quæ sit via bona, et ambulate in ea: et invenietis refrigerium animabus vestris. Et dixerunt: Non ambulabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 17, 'Et constitui super vos speculatores: Audite vocem tubæ. Et dixerunt: Non audiemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 18, 'Ideo audite, gentes, et cognosce, congregatio, quanta ego faciam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 19, 'Audi, terra: ecce ego adducam mala super populum istum, fructum cogitationum ejus: quia verba mea non audierunt, et legem meam projecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 20, 'Ut quid mihi thus de Saba affertis, et calamum suave olentem de terra longinqua? Holocautomata vestra non sunt accepta, et victimæ vestræ non placuerunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 21, 'Propterea hæc dicit Dominus: Ecce ego dabo in populum istum ruinas: et ruent in eis patres et filii simul; vicinus et proximus peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 22, 'Hæc dicit Dominus: Ecce populus venit de terra aquilonis, et gens magna consurget a finibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 23, 'Sagittam et scutum arripiet: crudelis est et non miserebitur. Vox ejus quasi mare sonabit: et super equos ascendent, præparati quasi vir ad prælium adversum te, filia Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 24, 'Audivimus famam ejus; dissolutæ sunt manus nostræ: tribulatio apprehendit nos, dolores ut parturientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 25, 'Nolite exire ad agros, et in via ne ambuletis, quoniam gladius inimici, pavor in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 26, 'Filia populi mei, accingere cilicio, et conspergere cinere: luctum unigeniti fac tibi, planctum amarum, quia repente veniet vastator super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 27, 'Probatorem dedi te in populo meo robustum: et scies, et probabis viam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 28, 'Omnes isti principes declinantes, ambulantes fraudulenter, æs et ferrum: universi corrupti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 29, 'Defecit sufflatorium; in igne consumptum est plumbum: frustra conflavit conflator, malitiæ enim eorum non sunt consumptæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 30, 'Argentum reprobum vocate eos, quia Dominus projecit illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Verbum quod factum est ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Sta in porta domus Domini, et prædica ibi verbum istud, et dic: Audite verbum Domini, omnis Juda, qui ingredimini per portas has ut adoretis Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Hæc dicit Dominus exercituum, Deus Israël: Bonas facite vias vestras, et studia vestra, et habitabo vobiscum in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Nolite confidere in verbis mendacii, dicentes: Templum Domini, templum Domini, templum Domini est!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Quoniam si bene direxeritis vias vestras, et studia vestra; si feceritis judicium inter virum et proximum ejus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'advenæ, et pupillo, et viduæ non feceritis calumniam, nec sanguinem innocentem effuderitis in loco hoc, et post deos alienos non ambulaveritis in malum vobismetipsis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'habitabo vobiscum in loco isto, in terra quam dedi patribus vestris a sæculo et usque in sæculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ecce vos confiditis vobis in sermonibus mendacii, qui non proderunt vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'furari, occidere, adulterari, jurare mendaciter, libare Baalim, et ire post deos alienos quos ignoratis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'et venistis, et stetistis coram me in domo hac, in qua invocatum est nomen meum, et dixistis: Liberati sumus, eo quod fecerimus omnes abominationes istas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Numquid ergo spelunca latronum facta est domus ista, in qua invocatum est nomen meum in oculis vestris? Ego, ego sum: ego vidi, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Ite ad locum meum in Silo, ubi habitavit nomen meum a principio, et videte quæ fecerim ei propter malitiam populi mei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Et nunc, quia fecistis omnia opera hæc, dicit Dominus, et locutus sum ad vos mane consurgens, et loquens, et non audistis: et vocavi vos, et non respondistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'faciam domui huic, in qua invocatum est nomen meum, et in qua vos habetis fiduciam, et loco quem dedi vobis et patribus vestris, sicut feci Silo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'et projiciam vos a facie mea sicut projeci omnes fratres vestros, universum semen Ephraim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Tu ergo, noli orare pro populo hoc, nec assumas pro eis laudem et orationem: et non obsistas mihi, quia non exaudiam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 17, 'Nonne vides quid isti faciunt in civitatibus Juda, et in plateis Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 18, 'Filii colligunt ligna, et patres succendunt ignem, et mulieres conspergunt adipem, ut faciant placentas reginæ cæli, et libent diis alienis, et me ad iracundiam provocent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 19, 'Numquid me ad iracundiam provocant? dicit Dominus; nonne semetipsos in confusionem vultus sui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 20, 'Ideo hæc dicit Dominus Deus: Ecce furor meus et indignatio mea conflatur super locum istum, super viros, et super jumenta, et super lignum regionis, et super fruges terræ: et succendetur, et non extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 21, 'Hæc dicit Dominus exercituum, Deus Israël: Holocautomata vestra addite victimis vestris, et comedite carnes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 22, 'quia non sum locutus cum patribus vestris, et non præcepi eis, in die qua eduxi eos de terra \'gypti, de verbo holocautomatum et victimarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 23, 'sed hoc verbum præcepi eis, dicens: Audite vocem meam, et ero vobis Deus, et vos eritis mihi populus: et ambulate in omni via quam mandavi vobis, ut bene sit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 24, 'Et non audierunt, nec inclinaverunt aurem suam: sed abierunt in voluntatibus et in pravitate cordis sui mali: factique sunt retrorsum, et non in ante,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 25, 'a die qua egressi sunt patres eorum de terra \'gypti usque ad diem hanc. Et misi ad vos omnes servos meos prophetas per diem, consurgens diluculo, et mittens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 26, 'et non audierunt me, nec inclinaverunt aurem suam: sed induraverunt cervicem suam, et pejus operati sunt quam patres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 27, 'Et loqueris ad eos omnia verba hæc, et non audient te: et vocabis eos, et non respondebunt tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 28, 'Et dices ad eos: Hæc est gens quæ non audivit vocem Domini Dei sui, nec recepit disciplinam; periit fides, et ablata est de ore eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 29, 'Tonde capillum tuum, et projice, et sume in directum planctum: quia projecit Dominus et reliquit generationem furoris sui;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 30, 'quia fecerunt filii Juda malum in oculis meis, dicit Dominus. Posuerunt offendicula sua in domo in qua invocatum est nomen meum, ut polluerent eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 31, 'et ædificaverunt excelsa Topheth, quæ est in valle filii Ennom, ut incenderent filios suos et filias suas igni, quæ non præcepi, nec cogitavi in corde meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 32, 'Ideo ecce dies venient, dicit Dominus, et non dicetur amplius Topheth, et vallis filii Ennom, sed vallis interfectionis: et sepelient in Topheth, eo quod non sit locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 33, 'Et erit morticinum populi hujus in cibos volucribus cæli et bestiis terræ, et non erit qui abigat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 34, 'Et quiescere faciam de urbibus Juda, et de plateis Jerusalem, vocem gaudii et vocem lætitiæ, vocem sponsi et vocem sponsæ: in desolationem enim erit terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'In illo tempore, ait Dominus, ejicient ossa regum Juda, et ossa principum ejus, et ossa sacerdotum, et ossa prophetarum, et ossa eorum qui habitaverunt Jerusalem, de sepulchris suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'et expandent ea ad solem, et lunam, et omnem militiam cæli, quæ dilexerunt, et quibus servierunt, et post quæ ambulaverunt, et quæ quæsierunt, et adoraverunt. Non colligentur, et non sepelientur: in sterquilinium super faciem terræ erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Et eligent magis mortem quam vitam, omnes qui residui fuerint de cognatione hac pessima, in universis locis quæ derelicta sunt, ad quæ ejeci eos, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Et dices ad eos: Hæc dicit Dominus: Numquid qui cadit non resurget? et qui aversus est non revertetur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Quare ergo aversus est populus iste in Jerusalem aversione contentiosa? Apprehenderunt mendacium, et noluerunt reverti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Attendi, et auscultavi: nemo quod bonum est loquitur; nullus est qui agat pœnitentiam super peccato suo, dicens: Quid feci? Omnes conversi sunt ad cursum suum, quasi equus impetu vadens ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Milvus in cælo cognovit tempus suum: turtur, et hirundo, et ciconia custodierunt tempus adventus sui: populus autem meus non cognovit judicium Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Quomodo dicitis: Sapientes nos sumus, et lex Domini nobiscum est? vere mendacium operatus est stylus mendax scribarum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Confusi sunt sapientes; perterriti et capti sunt: verbum enim Domini projecerunt, et sapientia nulla est in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Propterea dabo mulieres eorum exteris, agros eorum hæredibus, quia a minimo usque ad maximum omnes avaritiam sequuntur: a propheta usque ad sacerdotem cuncti faciunt mendacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Et sanabant contritionem filiæ populi mei ad ignominiam, dicentes: Pax, pax! cum non esset pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Confusi sunt, quia abominationem fecerunt: quinimmo confusione non sunt confusi, et erubescere nescierunt. Idcirco cadent inter corruentes: in tempore visitationis suæ corruent, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Congregans congregabo eos, ait Dominus. Non est uva in vitibus, et non sunt ficus in ficulnea: folium defluxit, et dedi eis quæ prætergressa sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Quare sedemus? convenite, et ingrediamur civitatem munitam, et sileamus ibi: quia Dominus Deus noster silere nos fecit, et potum dedit nobis aquam fellis: peccavimus enim Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 15, 'Exspectavimus pacem, et non erat bonum: tempus medelæ, et ecce formido.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 16, 'A Dan auditus est fremitus equorum ejus; a voce hinnituum pugnatorum ejus commota est omnis terra: et venerunt, et devoraverunt terram et plenitudinem ejus; urbem et habitatores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 17, 'Quia ecce ego mittam vobis serpentes regulos, quibus non est incantatio: et mordebunt vos, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 18, 'Dolor meus super dolorem, in me cor meum mœrens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 19, 'Ecce vox clamoris filiæ populi mei de terra longinqua: Numquid Dominus non est in Sion? aut rex ejus non est in ea? Quare ergo me ad iracundiam concitaverunt in sculptilibus suis, et in vanitatibus alienis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 20, 'Transiit messis, finita est æstas, et nos salvati non sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 21, 'Super contritione filiæ populi mei contritus sum, et contristatus: stupor obtinuit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 22, 'Numquid resina non est in Galaad? aut medicus non est ibi? quare igitur non est obducta cicatrix filiæ populi mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Quis dabit capiti meo aquam, et oculis meis fontem lacrimarum, et plorabo die ac nocte interfectos filiæ populi mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Quis dabit me in solitudine diversorium viatorum, et derelinquam populum meum, et recedam ab eis? quia omnes adulteri sunt, cœtus prævaricatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Et extenderunt linguam suam quasi arcum mendacii et non veritatis: confortati sunt in terra, quia de malo ad malum egressi sunt, et me non cognoverunt, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Unusquisque se a proximo suo custodiat, et in omni fratre suo non habeat fiduciam: quia omnis frater supplantans supplantabit, et omnis amicus fraudulenter incedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Et vir fratrem suum deridebit, et veritatem non loquentur: docuerunt enim linguam suam loqui mendacium; ut inique agerent laboraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Habitatio tua in medio doli: in dolo renuerunt scire me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Propterea hæc dicit Dominus exercituum: Ecce ego conflabo, et probabo eos: quid enim aliud faciam a facie filiæ populi mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Sagitta vulnerans lingua eorum, dolum locuta est. In ore suo pacem cum amico suo loquitur, et occulte ponit ei insidias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Numquid super his non visitabo, dicit Dominus, aut in gente hujusmodi non ulciscetur anima mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Super montes assumam fletum ac lamentum, et super speciosa deserti planctum, quoniam incensa sunt, eo quod non sit vir pertransiens, et non audierunt vocem possidentis: a volucre cæli usque ad pecora transmigraverunt et recesserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Et dabo Jerusalem in acervos arenæ, et cubilia draconum: et civitates Juda dabo in desolationem, eo quod non sit habitator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Quis est vir sapiens qui intelligat hoc, et ad quem verbum oris Domini fiat, ut annuntiet istud, quare perierit terra, et exusta sit quasi desertum, eo quod non sit qui pertranseat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Et dixit Dominus: Quia dereliquerunt legem meam quam dedi eis, et non audierunt vocem meam, et non ambulaverunt in ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'et abierunt post pravitatem cordis sui, et post Baalim, quod didicerunt a patribus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'idcirco hæc dicit Dominus exercituum, Deus Israël: Ecce ego cibabo populum istum absinthio, et potum dabo eis aquam fellis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Et dispergam eos in gentibus quas non noverunt ipsi et patres eorum, et mittam post eos gladium, donec consumantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Hæc dicit Dominus exercituum, Deus Israël: Contemplamini, et vocate lamentatrices, et veniant: et ad eas quæ sapientes sunt mittite, et properent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 18, 'festinent, et assumant super nos lamentum: deducant oculi nostri lacrimas, et palpebræ nostræ defluant aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 19, 'Quia vox lamentationis audita est de Sion: Quomodo vastati sumus, et confusi vehementer? quia dereliquimus terram; quoniam dejecta sunt tabernacula nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 20, 'Audite ergo, mulieres, verbum Domini, et assumant aures vestræ sermonem oris ejus, et docete filias vestras lamentum, et unaquæque proximam suam planctum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 21, 'quia ascendit mors per fenestras nostras; ingressa est domos nostras, disperdere parvulos deforis, juvenes de plateis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 22, 'Loquere: Hæc dicit Dominus: Et cadet morticinum hominis quasi stercus super faciem regionis, et quasi fœnum post tergum metentis, et non est qui colligat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 23, 'Hæc dicit Dominus: Non glorietur sapiens in sapientia sua, et non glorietur fortis in fortitudine sua, et non glorietur dives in divitiis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 24, 'sed in hoc glorietur, qui gloriatur, scire et nosse me, quia ego sum Dominus qui facio misericordiam, et judicium, et justitiam in terra: hæc enim placent mihi, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 25, 'Ecce dies veniunt, dicit Dominus, et visitabo super omnem qui circumcisum habet præputium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 26, 'super \'gyptum, et super Juda, et super Edom, et super filios Ammon, et super Moab; et super omnes qui attonsi sunt in comam, habitantes in deserto: quia omnes gentes habent præputium, omnis autem domus Israël incircumcisi sunt corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Audite verbum quod locutus est Dominus super vos, domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Hæc dicit Dominus: Juxta vias gentium nolite discere, et a signis cæli nolite metuere, quæ timent gentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'quia leges populorum vanæ sunt. Quia lignum de saltu præcidit opus manus artificis in ascia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'argento et auro decoravit illud: clavis et malleis compegit, ut non dissolvatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'in similitudinem palmæ fabricata sunt, et non loquentur: portata tollentur, quia incedere non valent. Nolite ergo timere ea, quia nec male possunt facere, nec bene.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Non est similis tui, Domine: magnus es tu, et magnum nomen tuum in fortitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Quis non timebit te, o Rex gentium? tuum est enim decus: inter cunctos sapientes gentium, et in universis regnis eorum, nullus est similis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Pariter insipientes et fatui probabuntur: doctrina vanitatis eorum lignum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Argentum involutum de Tharsis affertur, et aurum de Ophaz: opus artificis et manus ærarii. Hyacinthus et purpura indumentum eorum: opus artificum universa hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Dominus autem Deus verus est, ipse Deus vivens, et rex sempiternus. Ab indignatione ejus commovebitur terra, et non sustinebunt gentes comminationem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Sic ergo dicetis eis: Dii qui cælos et terram non fecerunt, pereant de terra et de his quæ sub cælo sunt!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Qui facit terram in fortitudine sua, præparat orbem in sapientia sua, et prudentia sua extendit cælos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'ad vocem suam dat multitudinem aquarum in cælo, et elevat nebulas ab extremitatibus terræ: fulgura in pluviam facit, et educit ventum de thesauris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Stultus factus est omnis homo a scientia: confusus est artifex omnis in sculptili, quoniam falsum est quod conflavit, et non est spiritus in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Vana sunt, et opus risu dignum: in tempore visitationis suæ peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 16, 'Non est his similis pars Jacob: qui enim formavit omnia, ipse est, et Israël virga hæreditatis ejus: Dominus exercituum nomen illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 17, 'Congrega de terra confusionem tuam, quæ habitas in obsidione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 18, 'quia hæc dicit Dominus: Ecce ego longe projiciam habitatores terræ in hac vice, et tribulabo eos ita ut inveniantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 19, 'Væ mihi super contritione mea: pessima plaga mea. Ego autem dixi: Plane hæc infirmitas mea est, et portabo illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 20, 'Tabernaculum meum vastatum est; omnes funiculi mei dirupti sunt: filii mei exierunt a me, et non subsistunt. Non est qui extendat ultra tentorium meum, et erigat pelles meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 21, 'Quia stulte egerunt pastores, et Dominum non quæsierunt: propterea non intellexerunt, et omnis grex eorum dispersus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 22, 'Vox auditionis ecce venit, et commotio magna de terra aquilonis: ut ponat civitates Juda solitudinem, et habitaculum draconum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 23, 'Scio, Domine, quia non est hominis via ejus, nec viri est ut ambulet, et dirigat gressus suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 24, 'Corripe me, Domine, verumtamen in judicio, et non in furore tuo, ne forte ad nihilum redigas me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 25, 'Effunde indignationem tuam super gentes quæ non cognoverunt te, et super provincias quæ nomen tuum non invocaverunt: quia comederunt Jacob, et devoraverunt eum, et consumpserunt illum, et decus ejus dissipaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Verbum quod factum est a Domino ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Audite verba pacti hujus, et loquimini ad viros Juda, et ad habitatores Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'et dices ad eos: Hæc dicit Dominus Deus Israël: Maledictus vir qui non audierit verba pacti hujus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'quod præcepi patribus vestris, in die qua eduxi eos de terra \'gypti, de fornace ferrea, dicens: Audite vocem meam, et facite omnia quæ præcipio vobis, et eritis mihi in populum, et ego ero vobis in Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'ut suscitem juramentum quod juravi patribus vestris, daturum me eis terram fluentem lacte et melle, sicut est dies hæc. Et respondi, et dixi: Amen, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Et dixit Dominus ad me: Vociferare omnia verba hæc in civitatibus Juda, et foris Jerusalem, dicens: Audite verba pacti hujus, et facite illa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'quia contestans contestatus sum patres vestros, in die qua eduxi eos de terra \'gypti, usque ad diem hanc: mane consurgens contestatus sum, et dixi: Audite vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Et non audierunt, nec inclinaverunt aurem suam, sed abierunt, unusquisque in pravitate cordis sui mali: et induxi super eos omnia verba pacti hujus quod præcepi ut facerent, et non fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Et dixit Dominus ad me: Inventa est conjuratio in viris Juda et in habitatoribus Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Reversi sunt ad iniquitates patrum suorum priores, qui noluerunt audire verba mea: et hi ergo abierunt post deos alienos, ut servirent eis: irritum fecerunt domus Israël et domus Juda pactum meum quod pepigi cum patribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Quam ob rem hæc dicit Dominus: Ecce ego inducam super eos mala de quibus exire non poterunt: et clamabunt ad me, et non exaudiam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Et ibunt civitates Juda et habitatores Jerusalem, et clamabunt ad deos quibus libant, et non salvabunt eos in tempore afflictionis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 13, 'Secundum numerum enim civitatum tuarum erant dii tui, Juda: et secundum numerum viarum Jerusalem, posuisti aras confusionis, aras ad libandum Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 14, 'Tu ergo noli orare pro populo hoc, et ne assumas pro eis laudem et orationem, quia non exaudiam in tempore clamoris eorum ad me, in tempore afflictionis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 15, 'Quid est, quod dilectus meus in domo mea fecit scelera multa? numquid carnes sanctæ auferent a te malitias tuas, in quibus gloriata es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 16, 'Olivam uberem, pulchram, fructiferam, speciosam, vocavit Dominus nomen tuum: ad vocem loquelæ, grandis exarsit ignis in ea, et combusta sunt fruteta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 17, 'Et Dominus exercituum, qui plantavit te, locutus est super te malum, pro malis domus Israël, et domus Juda, quæ fecerunt sibi ad irritandum me, libantes Baalim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 18, 'Tu autem, Domine, demonstrasti mihi, et cognovi: tunc ostendisti mihi studia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 19, 'Et ego quasi agnus mansuetus, qui portatur ad victimam: et non cognovi quia cogitaverunt super me consilia, dicentes: Mittamus lignum in panem ejus, et eradamus eum de terra viventium, et nomen ejus non memoretur amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 20, 'Tu autem, Domine Sabaoth, qui judicas juste, et probas renes et corda, videam ultionem tuam ex eis: tibi enim revelavi causam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 21, 'Propterea hæc dicit Dominus ad viros Anathoth, qui quærunt animam tuam, et dicunt: Non prophetabis in nomine Domini, et non morieris in manibus nostris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 22, 'propterea hæc dicit Dominus exercituum: Ecce ego visitabo super eos: juvenes morientur in gladio; filii eorum et filiæ eorum morientur in fame.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 23, 'Et reliquiæ non erunt ex eis: inducam enim malum super viros Anathoth, annum visitationis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Justus quidem tu es, Domine, si disputem tecum: verumtamen justa loquar ad te: Quare via impiorum prosperatur; bene est omnibus qui prævaricantur et inique agunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Plantasti eos, et radicem miserunt: proficiunt, et faciunt fructum: prope es tu ori eorum, et longe a renibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Et tu, Domine, nosti me, vidisti me, et probasti cor meum tecum. Congrega eos quasi gregem ad victimam, et sanctifica eos in die occisionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Usquequo lugebit terra, et herba omnis regionis siccabitur, propter malitiam habitantium in ea? Consumptum est animal, et volucre, quoniam dixerunt: Non videbit novissima nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Si cum peditibus currens laborasti, quomodo contendere poteris cum equis? cum autem in terra pacis securus fueris, quid facies in superbia Jordanis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Nam et fratres tui, et domus patris tui, etiam ipsi pugnaverunt adversum te, et clamaverunt post te plena voce: ne credas eis, cum locuti fuerint tibi bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Reliqui domum meam; dimisi hæreditatem meam: dedi dilectam animam meam in manu inimicorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Facta est mihi hæreditas mea quasi leo in silva: dedit contra me vocem, ideo odivi eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Numquid avis discolor hæreditas mea mihi? numquid avis tincta per totum? Venite, congregamini, omnes bestiæ terræ: properate ad devorandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Pastores multi demoliti sunt vineam meam, conculcaverunt partem meam, dederunt portionem meam desiderabilem in desertum solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Posuerunt eam in dissipationem, luxitque super me: desolatione desolata est omnis terra, quia nullus est qui recogitet corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Super omnes vias deserti venerunt vastatores, quia gladius Domini devorabit: ab extremo terræ usque ad extremum ejus, non est pax universæ carni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Seminaverunt triticum, et spinas messuerunt: hæreditatem acceperunt, et non eis proderit. Confundemini a fructibus vestris propter iram furoris Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Hæc dicit Dominus adversum omnes vicinos meos pessimos, qui tangunt hæreditatem quam distribui populo meo Israël: Ecce ego evellam eos de terra sua, et domum Juda evellam de medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Et cum evulsero eos, convertar, et miserebor eorum, et reducam eos: virum ad hæreditatem suam, et virum in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 16, 'Et erit: si eruditi didicerint vias populi mei, ut jurent in nomine meo: Vivit Dominus! sicut docuerunt populum meum jurare in Baal, ædificabuntur in medio populi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 17, 'Quod si non audierint, evellam gentem illam evulsione et perditione, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Hæc dicit Dominus ad me: Vade, et posside tibi lumbare lineum, et pones illud super lumbos tuos, et in aquam non inferes illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Et possedi lumbare juxta verbum Domini, et posui circa lumbos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Et factus est sermo Domini ad me secundo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Tolle lumbare quod possedisti, quod est circa lumbos tuos: et surgens vade ad Euphraten, et absconde ibi illud in foramine petræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Et abii, et abscondi illud in Euphrate, sicut præceperat mihi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Et factum est post dies plurimos, dixit Dominus ad me: Surge, vade ad Euphraten, et tolle inde lumbare quod præcepi tibi ut absconderes illud ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Et abii ad Euphraten, et fodi, et tuli lumbare de loco ubi absconderam illud: et ecce computruerat lumbare, ita ut nulli usui aptum esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Hæc dicit Dominus: Sic putrescere faciam superbiam Juda, et superbiam Jerusalem multam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'populum istum pessimum qui nolunt audire verba mea, et ambulant in pravitate cordis sui, abieruntque post deos alienos ut servirent eis et adorarent eos: et erunt sicut lumbare istud, quod nulli usui aptum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Sicut enim adhæret lumbare ad lumbos viri, sic agglutinavi mihi omnem domum Israël, et omnem domum Juda, dicit Dominus, ut essent mihi in populum, et in nomen, et in laudem, et in gloriam: et non audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Dices ergo ad eos sermonem istum: Hæc dicit Dominus Deus Israël: Omnis laguncula implebitur vino. Et dicent ad te: Numquid ignoramus quia omnis laguncula implebitur vino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Et dices ad eos: Hæc dicit Dominus: Ecce ego implebo omnes habitatores terræ hujus, et reges qui sedent de stirpe David super thronum ejus, et sacerdotes, et prophetas, et omnes habitatores Jerusalem, ebrietate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Et dispergam eos virum a fratre suo, et patres et filios pariter, ait Dominus. Non parcam, et non concedam: neque miserebor, ut non disperdam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Audite, et auribus percipite: nolite elevari, quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Date Domino Deo vestro gloriam antequam contenebrescat, et antequam offendant pedes vestri ad montes caliginosos: exspectabitis lucem, et ponet eam in umbram mortis, et in caliginem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 17, 'Quod si hoc non audieritis, in abscondito plorabit anima mea a facie superbiæ: plorans plorabit, et deducet oculus meus lacrimam, quia captus est grex Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 18, 'Dic regi et dominatrici: Humiliamini, sedete, quoniam descendit de capite vestro corona gloriæ vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 19, 'Civitates austri clausæ sunt, et non est qui aperiat: translata est omnis Juda transmigratione perfecta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 20, 'Levate oculos vestros et videte, qui venitis ab aquilone: ubi est grex qui datus est tibi, pecus inclytum tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 21, 'Quid dices cum visitaverit te? tu enim docuisti eos adversum te, et erudisti in caput tuum. Numquid non dolores apprehendent te, quasi mulierem parturientem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 22, 'Quod si dixeris in corde tuo: Quare venerunt mihi hæc? propter multitudinem iniquitatis tuæ revelata sunt verecundiora tua, pollutæ sunt plantæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 23, 'Si mutare potest \'thiops pellem suam, aut pardus varietates suas, et vos poteritis benefacere, cum didiceritis malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 24, 'Et disseminabo eos quasi stipulam quæ vento raptatur in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 25, 'Hæc sors tua, parsque mensuræ tuæ a me, dicit Dominus, quia oblita es mei, et confisa es in mendacio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 26, 'Unde et ego nudavi femora tua contra faciem tuam, et apparuit ignominia tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 27, 'adulteria tua, et hinnitus tuus, scelus fornicationis tuæ: super colles in agro vidi abominationes tuas. Væ tibi, Jerusalem! non mundaberis post me: usquequo adhuc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Quod factum est verbum Domini ad Jeremiam, de sermonibus siccitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Luxit Judæa, et portæ ejus corruerunt, et obscuratæ sunt in terra, et clamor Jerusalem ascendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Majores miserunt minores suos ad aquam: venerunt ad hauriendum. Non invenerunt aquam: reportaverunt vasa sua vacua. Confusi sunt, et afflicti, et operuerunt capita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Propter terræ vastitatem, quia non venit pluvia in terram, confusi sunt agricolæ: operuerunt capita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Nam et cerva in agro peperit, et reliquit, quia non erat herba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Et onagri steterunt in rupibus; traxerunt ventum quasi dracones: defecerunt oculi eorum, quia non erat herba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Si iniquitates nostræ responderint nobis, Domine, fac propter nomen tuum: quoniam multæ sunt aversiones nostræ: tibi peccavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Exspectatio Israël, salvator ejus in tempore tribulationis, quare quasi colonus futurus es in terra, et quasi viator declinans ad manendum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'quare futurus es velut vir vagus, ut fortis qui non potest salvare? Tu autem in nobis es, Domine, et nomen tuum invocatum est super nos: ne derelinquas nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Hæc dicit Dominus populo huic, qui dilexit movere pedes suos, et non quievit, et Domino non placuit: Nunc recordabitur iniquitatum eorum, et visitabit peccata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 11, 'Et dixit Dominus ad me: Noli orare pro populo isto in bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 12, 'Cum jejunaverint, non exaudiam preces eorum, et si obtulerint holocautomata et victimas, non suscipiam ea: quoniam gladio, et fame, et peste consumam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 13, 'Et dixi: A, a, a, Domine Deus: prophetæ dicunt eis: Non videbitis gladium, et fames non erit in vobis: sed pacem veram dabit vobis in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 14, 'Et dicit Dominus ad me: Falso prophetæ vaticinantur in nomine meo: non misi eos, et non præcepi eis, neque locutus sum ad eos. Visionem mendacem, et divinationem, et fraudulentiam, et seductionem cordis sui, prophetant vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 15, 'Idcirco hæc dicit Dominus de prophetis qui prophetant in nomine meo, quos ego non misi, dicentes: Gladius et fames non erit in terra hac: In gladio et fame consumentur prophetæ illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 16, 'Et populi quibus prophetant erunt projecti in viis Jerusalem præ fame et gladio, et non erit qui sepeliat eos: ipsi et uxores eorum, filii et filiæ eorum: et effundam super eos malum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 17, 'Et dices ad eos verbum istud: Deducant oculi mei lacrimam per noctem et diem, et non taceant, quoniam contritione magna contrita est virgo filia populi mei, plaga pessima vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 18, 'Si egressus fuero ad agros, ecce occisi gladio: et si introiero in civitatem, ecce attenuati fame. Propheta quoque et sacerdos abierunt in terram quam ignorabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 19, 'Numquid projiciens abjecisti Judam? aut Sion abominata est anima tua? quare ergo percussisti nos ita ut nulla sit sanitas? Exspectavimus pacem, et non est bonum: et tempus curationis, et ecce turbatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 20, 'Cognovimus, Domine, impietates nostras, iniquitates patrum nostrorum, quia peccavimus tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 21, 'Ne des nos in opprobrium, propter nomen tuum, neque facias nobis contumeliam solii gloriæ tuæ: recordare, ne irritum facias fœdus tuum nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 22, 'Numquid sunt in sculptilibus gentium qui pluant? aut cæli possunt dare imbres? nonne tu es Dominus Deus noster, quem exspectavimus? tu enim fecisti omnia hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 1, 'Et dixit Dominus ad me: Si steterit Moyses et Samuel coram me, non est anima mea ad populum istum: ejice illos a facie mea, et egrediantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 2, 'Quod si dixerint ad te: Quo egrediemur? dices ad eos: Hæc dicit Dominus: Qui ad mortem, ad mortem, et qui ad gladium, ad gladium, et qui ad famem, ad famem, et qui ad captivitatem, ad captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 3, 'Et visitabo super eos quatuor species, dicit Dominus: gladium ad occisionem, et canes ad lacerandum, et volatilia cæli et bestias terræ ad devorandum et dissipandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 4, 'Et dabo eos in fervorem universis regnis terræ, propter Manassen filium Ezechiæ regis Juda, super omnibus quæ fecit in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 5, 'Quis enim miserebitur tui, Jerusalem, aut quis contristabitur pro te? aut quis ibit ad rogandum pro pace tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 6, 'Tu reliquisti me, dicit Dominus; retrorsum abiisti: et extendam manum meam super te, et interficiam te: laboravi rogans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 7, 'Et dispergam eos ventilabro in portis terræ: interfeci et disperdidi populum meum, et tamen a viis suis non sunt reversi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 8, 'Multiplicatæ sunt mihi viduæ ejus super arenam maris: induxi eis super matrem adolescentis vastatorem meridie: misi super civitates repente terrorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 9, 'Infirmata est quæ peperit septem; defecit anima ejus: occidit ei sol cum adhuc esset dies: confusa est, et erubuit: et residuos ejus in gladium dabo in conspectu inimicorum eorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 10, 'Væ mihi, mater mea! quare genuisti me, virum rixæ, virum discordiæ in universa terra? Non fœneravi, nec fœneravit mihi quisquam: omnes maledicunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 11, 'Dicit Dominus: Si non reliquiæ tuæ in bonum, si non occurri tibi in tempore afflictionis, et in tempore tribulationis adversus inimicum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 12, 'Numquid fœderabitur ferrum ferro ab aquilone, et æs?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 13, 'Divitias tuas et thesauros tuos in direptionem dabo gratis, in omnibus peccatis tuis, et in omnibus terminis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 14, 'Et adducam inimicos tuos de terra quam nescis, quia ignis succensus est in furore meo: super vos ardebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 15, 'Tu scis, Domine: recordare mei, et visita me, et tuere me ab his qui persequuntur me. Noli in patientia tua suscipere me: scito quoniam sustinui propter te opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 16, 'Inventi sunt sermones tui, et comedi eos: et factum est mihi verbum tuum in gaudium et in lætitiam cordis mei, quoniam invocatum est nomen tuum super me, Domine Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 17, 'Non sedi in concilio ludentium, et gloriatus sum a facie manus tuæ: solus sedebam, quoniam comminatione replesti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 18, 'Quare factus est dolor meus perpetuus, et plaga mea desperabilis renuit curari? facta est mihi quasi mendacium aquarum infidelium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 19, 'Propter hoc hæc dicit Dominus: Si converteris, convertam te, et ante faciem meam stabis: et si separaveris pretiosum a vili, quasi os meum eris: convertentur ipsi ad te, et tu non converteris ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 20, 'Et dabo te populo huic in murum æreum fortem: et bellabunt adversum te, et non prævalebunt, quia ego tecum sum ut salvem te, et eruam te, dicit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 15, 21, 'et liberabo te de manu pessimorum, et redimam te de manu fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 2, 'Non accipies uxorem, et non erunt tibi filii et filiæ in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 3, 'Quia hæc dicit Dominus super filios et filias qui generantur in loco isto, et super matres eorum, quæ genuerunt eos, et super patres eorum, de quorum stirpe sunt nati in terra hac:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 4, 'Mortibus ægrotationum morientur: non plangentur, et non sepelientur: in sterquilinium super faciem terræ erunt, et gladio et fame consumentur: et erit cadaver eorum in escam volatilibus cæli et bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 5, 'Hæc enim dicit Dominus: Ne ingrediaris domum convivii, neque vadas ad plangendum, neque consoleris eos, quia abstuli pacem meam a populo isto, dicit Dominus, misericordiam et miserationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 6, 'Et morientur grandes et parvi in terra ista: non sepelientur, neque plangentur, et non se incident, neque calvitium fiet pro eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 7, 'Et non frangent inter eos lugenti panem ad consolandum super mortuo, et non dabunt eis potum calicis ad consolandum super patre suo et matre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 8, 'Et domum convivii non ingrediaris, ut sedeas cum eis, et comedas, et bibas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 9, 'Quia hæc dicit Dominus exercituum, Deus Israël: Ecce ego auferam de loco isto, in oculis vestris, et in diebus vestris, vocem gaudii et vocem lætitiæ, vocem sponsi et vocem sponsæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 10, 'Et cum annuntiaveris populo huic omnia verba hæc, et dixerint tibi: Quare locutus est Dominus super nos omne malum grande istud? quæ iniquitas nostra, et quod peccatum nostrum, quod peccavimus Domino Deo nostro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 11, 'dices ad eos: Quia dereliquerunt me patres vestri, ait Dominus, et abierunt post deos alienos, et servierunt eis, et adoraverunt eos, et me dereliquerunt, et legem meam non custodierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 12, 'Sed et vos pejus operati estis quam patres vestri: ecce enim ambulat unusquisque post pravitatem cordis sui mali, ut me non audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 13, 'Et ejiciam vos de terra hac in terram quam ignoratis, vos et patres vestri: et servietis ibi diis alienis, die ac nocte, qui non dabunt vobis requiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 14, 'Propterea ecce dies veniunt, dicit Dominus, et non dicetur ultra: Vivit Dominus qui eduxit filios Israël de terra \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 15, 'sed: Vivit Dominus qui eduxit filios Israël de terra aquilonis, et de universis terris ad quas ejeci eos: et reducam eos in terram suam, quam dedi patribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 16, 'Ecce ego mittam piscatores multos, dicit Dominus, et piscabuntur eos: et post hæc mittam eis multos venatores, et venabuntur eos de omni monte, et de omni colle, et de cavernis petrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 17, 'Quia oculi mei super omnes vias eorum: non sunt absconditæ a facie mea, et non fuit occultata iniquitas eorum ab oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 18, 'Et reddam primum duplices iniquitates et peccata eorum, quia contaminaverunt terram meam in morticinis idolorum suorum, et abominationibus suis impleverunt hæreditatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 19, 'Domine, fortitudo mea, et robur meum, et refugium meum in die tribulationis, ad te gentes venient ab extremis terræ, et dicent: Vere mendacium possederunt patres nostri, vanitatem quæ eis non profuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 20, 'Numquid faciet sibi homo deos, et ipsi non sunt dii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 16, 21, 'Idcirco ecce ego ostendam eis per vicem hanc, ostendam eis manum meam, et virtutem meam, et scient quia nomen mihi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 1, 'Peccatum Juda scriptum est stylo ferreo in ungue adamantino, exaratum super latitudinem cordis eorum, et in cornibus ararum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 2, 'Cum recordati fuerint filii eorum ararum suarum, et lucorum suorum, lignorumque frondentium, in montibus excelsis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 3, 'sacrificantes in agro: fortitudinem tuam, et omnes thesauros tuos in direptionem dabo; excelsa tua propter peccata in universis finibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 4, 'Et relinqueris sola ab hæreditate tua, quam dedi tibi, et servire te faciam inimicis tuis in terra quam ignoras: quoniam ignem succendisti in furore meo: usque in æternum ardebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 5, 'Hæc dicit Dominus: Maledictus homo qui confidit in homine, et ponit carnem brachium suum, et a Domino recedit cor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 6, 'Erit enim quasi myricæ in deserto, et non videbit cum venerit bonum: sed habitabit in siccitate in deserto, in terra salsuginis et inhabitabili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 7, 'Benedictus vir qui confidit in Domino, et erit Dominus fiducia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 8, 'Et erit quasi lignum quod transplantatur super aquas, quod ad humorem mittit radices suas, et non timebit cum venerit æstus: et erit folium ejus viride, et in tempore siccitatis non erit sollicitum, nec aliquando desinet facere fructum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 9, 'Pravum est cor omnium, et inscrutabile: quis cognoscet illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 10, 'Ego Dominus scrutans cor, et probans renes: qui do unicuique juxta viam suam, et juxta fructum adinventionum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 11, 'Perdix fovit quæ non peperit: fecit divitias, et non in judicio: in dimidio dierum suorum derelinquet eas, et in novissimo suo erit insipiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 12, 'Solium gloriæ altitudinis a principio, locus sanctificationis nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 13, 'Exspectatio Israël, Domine, omnes qui te derelinquunt confundentur: recedentes a te, in terra scribentur, quoniam dereliquerunt venam aquarum viventium Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 14, 'Sana me, Domine, et sanabor: salvum me fac, et salvus ero: quoniam laus mea tu es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 15, 'Ecce ipsi dicunt ad me: Ubi est verbum Domini? veniat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 16, 'et ego non sum turbatus, te pastorem sequens: et diem hominis non desideravi, tu scis: quod egressum est de labiis meis, rectum in conspectu tuo fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 17, 'Non sis tu mihi formidini: spes mea tu in die afflictionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 18, 'Confundantur qui me persequuntur, et non confundar ego: paveant illi, et non paveam ego: induc super eos diem afflictionis, et duplici contritione contere eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 19, 'Hæc dicit Dominus ad me: Vade, et sta in porta filiorum populi, per quam ingrediuntur reges Juda, et egrediuntur, et in cunctis portis Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 20, 'et dices ad eos: Audite verbum Domini, reges Juda, et omnis Juda, cunctique habitatores Jerusalem, qui ingredimini per portas istas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 21, 'Hæc dicit Dominus: Custodite animas vestras, et nolite portare pondera in die sabbati, nec inferatis per portas Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 22, 'et nolite ejicere onera de domibus vestris in die sabbati, et omne opus non facietis: sanctificate diem sabbati, sicut præcepi patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 23, 'Et non audierunt, nec inclinaverunt aurem suam: sed induraverunt cervicem suam, ne audirent me, et ne acciperent disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 24, 'Et erit: si audieritis me, dicit Dominus, ut non inferatis onera per portas civitatis hujus in die sabbati: et si sanctificaveritis diem sabbati, ne faciatis in eo omne opus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 25, 'ingredientur per portas civitatis hujus reges et principes, sedentes super solium David, et ascendentes in curribus et equis, ipsi et principes eorum, viri Juda, et habitatores Jerusalem: et habitabitur civitas hæc in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 26, 'Et venient de civitatibus Juda, et de circuitu Jerusalem, et de terra Benjamin, et de campestribus, et de montuosis, et ab austro, portantes holocaustum, et victimam, et sacrificium, et thus, et inferent oblationem in domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 17, 27, 'Si autem non audieritis me ut sanctificetis diem sabbati, et ne portetis onus, et ne inferatis per portas Jerusalem in die sabbati, succendam ignem in portis ejus, et devorabit domos Jerusalem, et non extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 1, 'Verbum quod factum est ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 2, 'Surge, et descende in domum figuli, et ibi audies verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 3, 'Et descendi in domum figuli, et ecce ipse faciebat opus super rotam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 4, 'Et dissipatum est vas quod ipse faciebat e luto manibus suis: conversusque fecit illud vas alterum, sicut placuerat in oculis ejus ut faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 5, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 6, 'Numquid sicut figulus iste, non potero vobis facere, domus Israël? ait Dominus: ecce sicut lutum in manu figuli, sic vos in manu mea, domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 7, 'Repente loquar adversum gentem et adversus regnum, ut eradicem, et destruam, et disperdam illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 8, 'si pœnitentiam egerit gens illa a malo suo quod locutus sum adversus eam, agam et ego pœnitentiam super malo quod cogitavi ut facerem ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 9, 'Et subito loquar de gente et de regno, ut ædificem et plantem illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 10, 'Si fecerit malum in oculis meis, ut non audiat vocem meam, pœnitentiam agam super bono quod locutus sum ut facerem ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 11, 'Nunc ergo dic viro Juda, et habitatoribus Jerusalem, dicens: Hæc dicit Dominus: Ecce ego fingo contra vos malum, et cogito contra vos cogitationem: revertatur unusquisque a via sua mala, et dirigite vias vestras et studia vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 12, 'Qui dixerunt: Desperavimus: post cogitationes enim nostras ibimus, et unusquisque pravitatem cordis sui mali faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 13, 'Ideo hæc dicit Dominus: Interrogate gentes: Quis audivit talia horribilia, quæ fecit nimis virgo Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 14, 'Numquid deficiet de petra agri nix Libani? aut evelli possunt aquæ erumpentes frigidæ, et defluentes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 15, 'Quia oblitus est mei populus meus, frustra libantes, et impingentes in viis suis, in semitis sæculi, ut ambularent per eas in itinere non trito,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 16, 'ut fieret terra eorum in desolationem, et in sibilum sempiternum: omnis qui præterierit per eam obstupescet, et movebit caput suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 17, 'Sicut ventus urens dispergam eos coram inimico: dorsum, et non faciem, ostendam eis in die perditionis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 18, 'Et dixerunt: Venite, et cogitemus contra Jeremiam cogitationes: non enim peribit lex a sacerdote, neque consilium a sapiente, nec sermo a propheta: venite, et percutiamus eum lingua, et non attendamus ad universos sermones ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 19, 'Attende, Domine, ad me, et audi vocem adversariorum meorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 20, 'Numquid redditur pro bono malum, quia foderunt foveam animæ meæ? Recordare quod steterim in conspectu tuo ut loquerer pro eis bonum, et averterem indignationem tuam ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 21, 'Propterea da filios eorum in famem, et deduc eos in manus gladii: fiant uxores eorum absque liberis, et viduæ: et viri earum interficiantur morte: juvenes eorum confodiantur gladio in prælio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 22, 'audiatur clamor de domibus eorum: adduces enim super eos latronem repente, quia foderunt foveam ut caperent me, et laqueos absconderunt pedibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 18, 23, 'Tu autem, Domine, scis omne consilium eorum adversum me in mortem: ne propitieris iniquitati eorum, et peccatum eorum a facie tua non deleatur: fiant corruentes in conspectu tuo; in tempore furoris tui abutere eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 1, 'Hæc dicit Dominus: Vade, et accipe lagunculam figuli testeam a senioribus populi et a senioribus sacerdotum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 2, 'et egredere ad vallem filii Ennom, quæ est juxta introitum portæ fictilis: et prædicabis ibi verba quæ ego loquar ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 3, 'Et dices: Audite verbum Domini, reges Juda, et habitatores Jerusalem. Hæc dicit Dominus exercituum, Deus Israël: Ecce ego inducam afflictionem super locum istum, ita ut omnis qui audierit illam, tinniant aures ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 4, 'eo quod dereliquerint me, et alienum fecerint locum istum, et libaverunt in eo diis alienis quos nescierunt, ipsi et patres eorum, et reges Juda: et repleverunt locum istum sanguine innocentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 5, 'et ædificaverunt excelsa Baalim, ad comburendos filios suos igni in holocaustum Baalim: quæ non præcepi, nec locutus sum, nec ascenderunt in cor meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 6, 'Propterea ecce dies veniunt, dicit Dominus, et non vocabitur amplius locus iste Topheth, et vallis filii Ennom, sed vallis occisionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 7, 'Et dissipabo consilium Juda et Jerusalem in loco isto, et subvertam eos gladio in conspectu inimicorum suorum, et in manu quærentium animas eorum: et dabo cadavera eorum escam volatilibus cæli et bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 8, 'Et ponam civitatem hanc in stuporem, et in sibilum: omnis qui præterierit per eam obstupescet, et sibilabit super universa plaga ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 9, 'Et cibabo eos carnibus filiorum suorum et carnibus filiarum suarum: et unusquisque carnem amici sui comedet in obsidione, et in angustia in qua concludent eos inimici eorum, et qui quærunt animas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 10, 'Et conteres lagunculam in oculis virorum qui ibunt tecum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 11, 'et dices ad eos: Hæc dicit Dominus exercituum: Sic conteram populum istum, et civitatem istam, sicut conteritur vas figuli, quod non potest ultra instaurari: et in Topheth sepelientur, eo quod non sit alius locus ad sepeliendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 12, 'Sic faciam loco huic, ait Dominus, et habitatoribus ejus, et ponam civitatem istam sicut Topheth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 13, 'Et erunt domus Jerusalem, et domus regum Juda, sicut locus Topheth, immundæ, omnes domus in quarum domatibus sacrificaverunt omni militiæ cæli, et libaverunt libamina diis alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 14, 'Venit autem Jeremias de Topheth, quo miserat eum Dominus ad prophetandum, et stetit in atrio domus Domini, et dixit ad omnem populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 19, 15, 'Hæc dicit Dominus exercituum, Deus Israël: Ecce ego inducam super civitatem hanc, et super omnes urbes ejus, universa mala quæ locutus sum adversum eam, quoniam induraverunt cervicem suam ut non audirent sermones meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 1, 'Et audivit Phassur filius Emmer, sacerdos, qui constitutus erat princeps in domo Domini, Jeremiam prophetantem sermones istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 2, 'Et percussit Phassur Jeremiam prophetam, et misit eum in nervum quod erat in porta Benjamin superiori, in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 3, 'Cumque illuxisset in crastinum, eduxit Phassur Jeremiam de nervo, et dixit ad eum Jeremias: Non Phassur vocavit Dominus nomen tuum, sed Pavorem undique.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 4, 'Quia hæc dicit Dominus: Ecce ego dabo te in pavorem, te et omnes amicos tuos: et corruent gladio inimicorum suorum, et oculi tui videbunt: et omnem Judam dabo in manum regis Babylonis, et traducet eos in Babylonem, et percutiet eos gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 5, 'Et dabo universam substantiam civitatis hujus, et omnem laborem ejus, omneque pretium, et cunctos thesauros regum Juda dabo in manu inimicorum eorum: et diripient eos, et tollent, et ducent in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 6, 'Tu autem, Phassur, et omnes habitatores domus tuæ, ibitis in captivitatem: et in Babylonem venies, et ibi morieris, ibique sepelieris tu, et omnes amici tui, quibus prophetasti mendacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 7, 'Seduxisti me, Domine, et seductus sum: fortior me fuisti, et invaluisti: factus sum in derisum tota die; omnes subsannant me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 8, 'Quia jam olim loquor, vociferans iniquitatem, et vastitatem clamito: et factus est mihi sermo Domini in opprobrium, et in derisum tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 9, 'Et dixi: Non recordabor ejus, neque loquar ultra in nomine illius: et factus est in corde meo quasi ignis exæstuans, claususque in ossibus meis, et defeci, ferre non sustinens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 10, 'Audivi enim contumelias multorum, et terrorem in circuitu: Persequimini, et persequamur eum, ab omnibus viris qui erant pacifici mei, et custodientes latus meum: si quomodo decipiatur, et prævaleamus adversus eum, et consequamur ultionem ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 11, 'Dominus autem mecum est, quasi bellator fortis: idcirco qui persequuntur me cadent, et infirmi erunt: confundentur vehementer, quia non intellexerunt opprobrium sempiternum, quod numquam delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 12, 'Et tu, Domine exercituum, probator justi, qui vides renes et cor, videam, quæso, ultionem tuam ex eis: tibi enim revelavi causam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 13, 'Cantate Domino, laudate Dominum, quia liberavit animam pauperis de manu malorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 14, 'Maledicta dies in qua natus sum! dies in qua peperit me mater mea non sit benedicta!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 15, 'Maledictus vir qui annuntiavit patri meo, dicens: Natus est tibi puer masculus, et quasi gaudio lætificavit eum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 16, 'Sit homo ille ut sunt civitates quæ subvertit Dominus, et non pœnituit eum: audiat clamorem mane, et ululatum in tempore meridiano,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 17, 'qui non me interfecit a vulva, ut fieret mihi mater mea sepulchrum, et vulva ejus conceptus æternus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 20, 18, 'Quare de vulva egressus sum, ut viderem laborem et dolorem, et consumerentur in confusione dies mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 1, 'Verbum quod factum est ad Jeremiam a Domino, quando misit ad eum rex Sedecias Phassur filium Melchiæ, et Sophoniam filium Maasiæ sacerdotem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 2, 'Interroga pro nobis Dominum, quia Nabuchodonosor, rex Babylonis, præliatur adversum nos: si forte faciat Dominus nobiscum secundum omnia mirabilia sua, et recedat a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 3, 'Et dixit Jeremias ad eos: Sic dicetis Sedeciæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 4, 'Hæc dicit Dominus Deus Israël: Ecce ego convertam vasa belli quæ in manibus vestris sunt, et quibus vos pugnatis adversum regem Babylonis et Chaldæos qui obsident vos in circuitu murorum: et congregabo ea in medio civitatis hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 5, 'Et debellabo ego vos in manu extenta, et in brachio forti, et in furore, et in indignatione, et in ira grandi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 6, 'Et percutiam habitatores civitatis hujus: homines et bestiæ pestilentia magna morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 7, 'Et post hæc, ait Dominus, dabo Sedeciam regem Juda, et servos ejus, et populum ejus, et qui derelicti sunt in civitate hac a peste, et gladio, et fame, in manu Nabuchodonosor regis Babylonis, et in manu inimicorum eorum, et in manu quærentium animam eorum: et percutiet eos in ore gladii, et non flectetur, neque parcet, nec miserebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 8, 'Et ad populum hunc dices: Hæc dicit Dominus: Ecce ego do coram vobis viam vitæ, et viam mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 9, 'Qui habitaverit in urbe hac morietur gladio, et fame, et peste: qui autem egressus fuerit, et transfugerit ad Chaldæos qui obsident vos, vivet, et erit ei anima sua quasi spolium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 10, 'Posui enim faciem meam super civitatem hanc in malum, et non in bonum, ait Dominus: in manu regis Babylonis dabitur, et exuret eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 11, 'Et domui regis Juda: Audite verba Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 12, 'domus David. Hæc dicit Dominus: Judicate mane judicium, et eruite vi oppressum de manu calumniantis, ne forte egrediatur ut ignis indignatio mea, et succendatur, et non sit qui extinguat, propter malitiam studiorum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 13, 'Ecce ego ad te, habitatricem vallis solidæ atque campestris, ait Dominus: qui dicitis: Quis percutiet nos? et quis ingredietur domos nostras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 21, 14, 'Et visitabo super vos juxta fructum studiorum vestrorum, dicit Dominus: et succendam ignem in saltu ejus, et devorabit omnia in circuitu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 1, 'Hæc dicit Dominus: Descende in domum regis Juda, et loqueris ibi verbum hoc,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 2, 'et dices: Audi verbum Domini, rex Juda, qui sedes super solium David: tu et servi tui, et populus tuus, qui ingredimini per portas istas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 3, 'Hæc dicit Dominus: Facite judicium et justitiam, et liberate vi oppressum de manu calumniatoris: et advenam, et pupillum, et viduam nolite contristare, neque opprimatis inique, et sanguinem innocentem ne effundatis in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 4, 'Si enim facientes feceritis verbum istud, ingredientur per portas domus hujus reges sedentes de genere David super thronum ejus, et ascendentes currus et equos, ipsi, et servi, et populus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 5, 'Quod si non audieritis verba hæc: in memetipso juravi, dicit Dominus, quia in solitudinem erit domus hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 6, 'Quia hæc dicit Dominus super domum regis Juda: Galaad, tu mihi caput Libani, si non posuero te solitudinem, urbes inhabitabiles!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 7, 'Et sanctificabo super te, interficientem virum et arma ejus: et succident electas cedros tuas, et præcipitabunt in ignem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 8, 'Et pertransibunt gentes multæ per civitatem hanc, et dicet unusquisque proximo suo: Quare fecit Dominus sic civitati huic grandi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 9, 'Et respondebunt: Eo quod dereliquerint pactum Domini Dei sui, et adoraverint deos alienos, et servierint eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 10, 'Nolite flere mortuum, neque lugeatis super eum fletu: plangite eum qui egreditur, quia non revertetur ultra, nec videbit terram nativitatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 11, 'Quia hæc dicit Dominus ad Sellum, filium Josiæ, regem Juda, qui regnavit pro Josia patre suo, qui egressus est de loco isto: Non revertetur huc amplius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 12, 'sed in loco ad quem transtuli eum, ibi morietur, et terram istam non videbit amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 13, 'Væ qui ædificat domum suam in injustitia, et cœnacula sua non in judicio: amicum suum opprimet frustra, et mercedem ejus non reddet ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 14, 'qui dicit: \'dificabo mihi domum latam, et cœnacula spatiosa: qui aperit sibi fenestras et facit laquearia cedrina, pingitque sinopide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 15, 'Numquid regnabis quoniam confers te cedro? pater tuus numquid non comedit et bibit, et fecit judicium et justitiam tunc cum bene erat ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 16, 'Judicavit causam pauperis et egeni in bonum suum: numquid non ideo quia cognovit me? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 17, 'Tui vero oculi et cor ad avaritiam, et ad sanguinem innocentem fundendum, et ad calumniam, et ad cursum mali operis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 18, 'Propterea hæc dicit Dominus ad Joakim, filium Josiæ, regem Juda: Non plangent eum: Væ frater! et væ soror! non concrepabunt ei: Væ domine! et væ inclyte!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 19, 'Sepultura asini sepelietur, putrefactus et projectus extra portas Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 20, 'Ascende Libanum, et clama, et in Basan da vocem tuam: et clama ad transeuntes, quia contriti sunt omnes amatores tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 21, 'Locutus sum ad te in abundantia tua, et dixisti: Non audiam: hæc est via tua ab adolescentia tua, quia non audisti vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 22, 'Omnes pastores tuos pascet ventus, et amatores tui in captivitatem ibunt: et tunc confunderis, et erubesces ab omni malitia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 23, 'Quæ sedes in Libano, et nidificas in cedris, quomodo congemuisti cum venissent tibi dolores, quasi dolores parturientis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 24, 'Vivo ego, dicit Dominus, quia si fuerit Jechonias filius Joakim regis Juda annulus in manu dextera mea, inde evellam eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 25, 'et dabo te in manu quærentium animam tuam, et in manu quorum tu formidas faciem, et in manu Nabuchodonosor regis Babylonis, et in manu Chaldæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 26, 'et mittam te, et matrem tuam quæ genuit te, in terram alienam, in qua nati non estis, ibique moriemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 27, 'Et in terram ad quam ipsi levant animam suam ut revertantur illuc, non revertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 28, 'Numquid vas fictile atque contritum vir iste Jechonias? numquid vas absque omni voluptate? quare abjecti sunt ipse et semen ejus, et projecti in terram quam ignoraverunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 29, 'Terra, terra, terra, audi sermonem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 22, 30, 'Hæc dicit Dominus: Scribe virum istum sterilem, virum qui in diebus suis non prosperabitur: nec enim erit de semine ejus vir qui sedeat super solium David, et potestatem habeat ultra in Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 1, 'Væ pastoribus qui disperdunt et dilacerant gregem pascuæ meæ! dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 2, 'Ideo hæc dicit Dominus Deus Israël ad pastores qui pascunt populum meum: Vos dispersistis gregem meum, et ejecistis eos, et non visitastis eos: ecce ego visitabo super vos malitiam studiorum vestrorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 3, 'Et ego congregabo reliquias gregis mei de omnibus terris ad quas ejecero eos illuc: et convertam eos ad rura sua, et crescent et multiplicabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 4, 'Et suscitabo super eos pastores, et pascent eos: non formidabunt ultra, et non pavebunt, et nullus quæretur ex numero, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 5, 'Ecce dies veniunt, dicit Dominus, et suscitabo David germen justum: et regnabit rex, et sapiens erit, et faciet judicium et justitiam in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 6, 'In diebus illis salvabitur Juda, et Israël habitabit confidenter: et hoc est nomen quod vocabunt eum: Dominus justus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 7, 'Propter hoc ecce dies veniunt, dicit Dominus, et non dicent ultra: Vivit Dominus, qui eduxit filios Israël de terra \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 8, 'sed: Vivit Dominus, qui eduxit et adduxit semen domus Israël de terra aquilonis, et de cunctis terris ad quas ejeceram eos illuc, et habitabunt in terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 9, 'Ad prophetas: Contritum est cor meum in medio mei; contremuerunt omnia ossa mea: factus sum quasi vir ebrius, et quasi homo madidus a vino, a facie Domini, et a facie verborum sanctorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 10, 'Quia adulteris repleta est terra, quia a facie maledictionis luxit terra, arefacta sunt arva deserti: factus est cursus eorum malus, et fortitudo eorum dissimilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 11, 'Propheta namque et sacerdos polluti sunt, et in domo mea inveni malum eorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 12, 'Idcirco via eorum erit quasi lubricum in tenebris: impellentur enim, et corruent in ea: afferam enim super eos mala, annum visitationis eorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 13, 'Et in prophetis Samariæ vidi fatuitatem: prophetabant in Baal, et decipiebant populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 14, 'Et in prophetis Jerusalem vidi similitudinem adulterantium, et iter mendacii: et confortaverunt manus pessimorum, ut non converteretur unusquisque a malitia sua: facti sunt mihi omnes ut Sodoma, et habitatores ejus quasi Gomorrha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 15, 'Propterea hæc dicit Dominus exercituum ad prophetas: Ecce ego cibabo eos absinthio, et potabo eos felle: a prophetis enim Jerusalem egressa est pollutio super omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 16, 'Hæc dicit Dominus exercituum: Nolite audire verba prophetarum qui prophetant vobis, et decipiunt vos: visionem cordis sui loquuntur, non de ore Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 17, 'Dicunt his qui blasphemant me: Locutus est Dominus: Pax erit vobis: et omni qui ambulat in pravitate cordis sui dixerunt: Non veniet super vos malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 18, 'Quis enim affuit in consilio Domini, et vidit, et audivit sermonem ejus? quis consideravit verbum illius, et audivit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 19, 'Ecce turbo Dominicæ indignationis egredietur, et tempestas erumpens super caput impiorum veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 20, 'Non revertetur furor Domini, usque dum faciat et usque dum compleat cogitationem cordis sui: in novissimis diebus intelligetis consilium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 21, 'Non mittebam prophetas, et ipsi currebant: non loquebar ad eos, et ipsi prophetabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 22, 'Si stetissent in consilio meo, et nota fecissent verba mea populo meo, avertissem utique eos a via sua mala, et a cogitationibus suis pessimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 23, 'Putasne Deus e vicino ego sum, dicit Dominus, et non Deus de longe?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 24, 'Si occultabitur vir in absconditis, et ego non videbo eum? dicit Dominus. Numquid non cælum et terram ego impleo? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 25, 'Audivi quæ dixerunt prophetæ prophetantes in nomine meo mendacium, atque dicentes: Somniavi, somniavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 26, 'Usquequo istud est in corde prophetarum vaticinantium mendacium, et prophetantium seductiones cordis sui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 27, 'Qui volunt facere ut obliviscatur populus meus nominis mei, propter somnia eorum quæ narrat unusquisque ad proximum suum, sicut obliti sunt patres eorum nominis mei propter Baal?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 28, 'Propheta qui habet somnium, narret somnium: et qui habet sermonem meum, loquatur sermonem meum vere. Quid paleis ad triticum? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 29, 'Numquid non verba mea sunt quasi ignis, dicit Dominus, et quasi malleus conterens petram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 30, 'Propterea ecce ego ad prophetas, ait Dominus, qui furantur verba mea unusquisque a proximo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 31, 'Ecce ego ad prophetas, ait Dominus, qui assumunt linguas suas, et aiunt: Dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 32, 'Ecce ego ad prophetas somniantes mendacium, ait Dominus, qui narraverunt ea, et seduxerunt populum meum in mendacio suo et in miraculis suis, cum ego non misissem eos, nec mandassem eis: qui nihil profuerunt populo huic, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 33, 'Si igitur interrogaverit te populus iste, vel propheta, aut sacerdos, dicens: Quod est onus Domini? dices ad eos: Vos estis onus: projiciam quippe vos, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 34, 'Et propheta, et sacerdos, et populus qui dicit: Onus Domini: visitabo super virum illum et super domum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 35, 'Hæc dicetis unusquisque ad proximum, et ad fratrem suum: Quid respondit Dominus? et quid locutus est Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 36, 'Et onus Domini ultra non memorabitur: quia onus erit unicuique sermo suus, et pervertistis verba Dei viventis, Domini exercituum, Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 37, 'Hæc dices ad prophetam: Quid respondit tibi Dominus? et quid locutus est Dominus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 38, 'Si autem onus Domini dixeritis, propter hoc hæc dicit Dominus: Quia dixistis sermonem istum: Onus Domini, et misi ad vos dicens: Nolite dicere: Onus Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 39, 'propterea ecce ego tollam vos portans, et derelinquam vos, et civitatem quam dedi vobis et patribus vestris, a facie mea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 23, 40, 'et dabo vos in opprobrium sempiternum, et in ignominiam æternam, quæ numquam oblivione delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 1, 'Ostendit mihi Dominus: et ecce duo calathi pleni ficis, positi ante templum Domini, postquam transtulit Nabuchodonosor rex Babylonis Jechoniam filium Joakim, regem Juda, et principes ejus, et fabrum, et inclusorem, de Jerusalem, et adduxit eos in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 2, 'Calathus unus ficus bonas habebat nimis, ut solent ficus esse primi temporis: et calathus unus ficus habebat malas nimis, quæ comedi non poterant eo quod essent malæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 3, 'Et dixit Dominus ad me: Quid tu vides, Jeremia? Et dixi: Ficus, ficus bonas, bonas valde: et malas, malas valde, quæ comedi non possunt eo quod sint malæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 4, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 5, 'Hæc dicit Dominus Deus Israël: Sicut ficus hæ bonæ, sic cognoscam transmigrationem Juda, quam emisi de loco isto in terram Chaldæorum, in bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 6, 'Et ponam oculos meos super eos ad placandum, et reducam eos in terram hanc: et ædificabo eos, et non destruam: et plantabo eos, et non evellam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 7, 'Et dabo eis cor ut sciant me, quia ego sum Dominus: et erunt mihi in populum, et ego ero eis in Deum, quia revertentur ad me in toto corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 8, 'Et sicut ficus pessimæ quæ comedi non possunt eo quod sint malæ, hæc dicit Dominus: Sic dabo Sedeciam regem Juda, et principes ejus, et reliquos de Jerusalem, qui remanserunt in urbe hac, et qui habitant in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 9, 'Et dabo eos in vexationem, afflictionemque omnibus regnis terræ, in opprobrium, et in parabolam, et in proverbium, et in maledictionem in universis locis ad quæ ejeci eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 24, 10, 'Et mittam in eis gladium, et famem, et pestem, donec consumantur de terra quam dedi eis et patribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 1, 'Verbum quod factum est ad Jeremiam, de omni populo Juda, in anno quarto Joakim filii Josiæ regis Juda (ipse est annus primus Nabuchodonosor regis Babylonis),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 2, 'quod locutus est Jeremias propheta ad omnem populum Juda, et ad universos habitatores Jerusalem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 3, 'A tertiodecimo anno Josiæ filii Amon regis Juda, usque ad diem hanc, iste tertius et vigesimus annus, factum est verbum Domini ad me, et locutus sum ad vos, de nocte consurgens et loquens, et non audistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 4, 'Et misit Dominus ad vos omnes servos suos prophetas, consurgens diluculo, mittensque: et non audistis, neque inclinastis aures vestras ut audiretis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 5, 'cum diceret: Revertimini unusquisque a via sua mala, et a pessimis cogitationibus vestris, et habitabitis in terra quam dedit Dominus vobis et patribus vestris, a sæculo et usque in sæculum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 6, 'et nolite ire post deos alienos, ut serviatis eis, adoretisque eos: neque me ad iracundiam provocetis in operibus manuum vestrarum, et non affligam vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 7, 'Et non audistis me, dicit Dominus, ut me ad iracundiam provocaretis in operibus manuum vestrarum, in malum vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 8, 'Propterea hæc dicit Dominus exercituum: Pro eo quod non audistis verba mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 9, 'ecce ego mittam et assumam universas cognationes aquilonis, ait Dominus, et Nabuchodonosor regem Babylonis servum meum, et adducam eos super terram istam, et super habitatores ejus, et super omnes nationes quæ in circuitu illius sunt: et interficiam eos, et ponam eos in stuporem et in sibilum, et in solitudines sempiternas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 10, 'Perdamque ex eis vocem gaudii et vocem lætitiæ, vocem sponsi et vocem sponsæ, vocem molæ et lumen lucernæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 11, 'Et erit universa terra hæc in solitudinem, et in stuporem: et servient omnes gentes istæ regi Babylonis septuaginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 12, 'Cumque impleti fuerint septuaginta anni, visitabo super regem Babylonis et super gentem illam, dicit Dominus, iniquitatem eorum, et super terram Chaldæorum, et ponam illam in solitudines sempiternas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 13, 'Et adducam super terram illam omnia verba mea, quæ locutus sum contra eam, omne quod scriptum est in libro isto, quæcumque prophetavit Jeremias adversum omnes gentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 14, 'quia servierunt eis, cum essent gentes multæ, et reges magni: et reddam eis secundum opera eorum, et secundum facta manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 15, 'Quia sic dicit Dominus exercituum, Deus Israël: Sume calicem vini furoris hujus de manu mea, et propinabis de illo cunctis gentibus ad quas ego mittam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 16, 'Et bibent, et turbabuntur et insanient a facie gladii quem ego mittam inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 17, 'Et accepi calicem de manu Domini, et propinavi cunctis gentibus ad quas misit me Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 18, 'Jerusalem, et civitatibus Juda, et regibus ejus, et principibus ejus, ut darem eos in solitudinem, et in stuporem, et in sibilum, et in maledictionem, sicut est dies ista:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 19, 'Pharaoni regi \'gypti, et servis ejus, et principibus ejus, et omni populo ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 20, 'et universis generaliter: cunctis regibus terræ Ausitidis, et cunctis regibus terræ Philisthiim, et Ascaloni, et Gazæ, et Accaron, et reliquiis Azoti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 21, 'et Idumææ, et Moab, et filiis Ammon:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 22, 'et cunctis regibus Tyri, et universis regibus Sidonis, et regibus terræ insularum qui sunt trans mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 23, 'et Dedan, et Thema, et Buz, et universis qui attonsi sunt in comam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 24, 'et cunctis regibus Arabiæ, et cunctis regibus occidentis, qui habitant in deserto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 25, 'et cunctis regibus Zambri, et cunctis regibus Elam, et cunctis regibus Medorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 26, 'cunctis quoque regibus aquilonis, de prope et de longe, unicuique contra fratrem suum: et omnibus regnis terræ quæ super faciem ejus sunt: et rex Sesach bibet post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 27, 'Et dices ad eos: Hæc dicit Dominus exercituum, Deus Israël: Bibite, et inebriamini, et vomite: et cadite, neque surgatis a facie gladii quem ego mittam inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 28, 'Cumque noluerint accipere calicem de manu tua ut bibant, dices ad eos: Hæc dicit Dominus exercituum: Bibentes bibetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 29, 'quia ecce in civitate in qua invocatum est nomen meum ego incipiam affligere, et vos quasi innocentes et immunes eritis? non eritis immunes: gladium enim ego voco super omnes habitatores terræ, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 30, 'Et tu prophetabis ad eos omnia verba hæc, et dices ad illos: Dominus de excelso rugiet, et de habitaculo sancto suo dabit vocem suam: rugiens rugiet super decorem suum: celeuma quasi calcantium concinetur adversus omnes habitatores terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 31, 'Pervenit sonitus usque ad extrema terræ, quia judicium Domino cum gentibus: judicatur ipse cum omni carne. Impios tradidi gladio, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 32, 'Hæc dicit Dominus exercituum: Ecce afflictio egredietur de gente in gentem, et turbo magnus egredietur a summitatibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 33, 'Et erunt interfecti Domini in die illa, a summo terræ usque ad summum ejus: non plangentur, et non colligentur, neque sepelientur: in sterquilinium super faciem terræ jacebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 34, 'Ululate, pastores, et clamate, et aspergite vos cinere, optimates gregis: quia completi sunt dies vestri ut interficiamini, et dissipationes vestræ: et cadetis quasi vasa pretiosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 35, 'Et peribit fuga a pastoribus, et salvatio ab optimatibus gregis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 36, 'Vox clamoris pastorum, et ululatus optimatum gregis, quia vastavit Dominus pascua eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 37, 'et conticuerunt arva pacis a facie iræ furoris Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 25, 38, 'Dereliquit quasi leo umbraculum suum, quia facta est terra eorum in desolationem a facie iræ columbæ, et a facie iræ furoris Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 1, 'In principio regni Joakim filii Josiæ regis Juda, factum est verbum istud a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 2, 'Hæc dicit Dominus: Sta in atrio domus Domini, et loqueris ad omnes civitates Juda, de quibus veniunt ut adorent in domo Domini universos sermones quos ego mandavi tibi ut loquaris ad eos: noli subtrahere verbum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 3, 'si forte audiant, et convertantur unusquisque a via sua mala, et pœniteat me mali quod cogito facere eis propter malitiam studiorum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 4, 'Et dices ad eos: Hæc dicit Dominus: Si non audieritis me, ut ambuletis in lege mea quam dedi vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 5, 'ut audiatis sermones servorum meorum prophetarum quos ego misi ad vos, de nocte consurgens, et dirigens, et non audistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 6, 'dabo domum istam sicut Silo, et urbem hanc dabo in maledictionem cunctis gentibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 7, 'Et audierunt sacerdotes, et prophetæ, et omnis populus, Jeremiam loquentem verba hæc in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 8, 'Cumque complesset Jeremias, loquens omnia quæ præceperat ei Dominus ut loqueretur ad universum populum, apprehenderunt eum sacerdotes, et prophetæ, et omnis populus, dicens: Morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 9, 'Quare prophetavit in nomine Domini, dicens: Sicut Silo erit domus hæc, et urbs ista desolabitur eo quod non sit habitator? Et congregatus est omnis populus adversus Jeremiam in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 10, 'Et audierunt principes Juda verba hæc, et ascenderunt de domo regis in domum Domini, et sederunt in introitu portæ domus Domini novæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 11, 'Et locuti sunt sacerdotes et prophetæ ad principes, et ad omnem populum, dicentes: Judicium mortis est viro huic, quia prophetavit adversus civitatem istam, sicut audistis auribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 12, 'Et ait Jeremias ad omnes principes, et ad universum populum, dicens: Dominus misit me ut prophetarem ad domum istam, et ad civitatem hanc, omnia verba quæ audistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 13, 'Nunc ergo bonas facite vias vestras et studia vestra, et audite vocem Domini Dei vestri, et pœnitebit Dominum mali quod locutus est adversum vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 14, 'Ego autem ecce in manibus vestris sum: facite mihi quod bonum et rectum est in oculis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 15, 'Verumtamen scitote et cognoscite quod, si occideritis me, sanguinem innocentem tradetis contra vosmetipsos, et contra civitatem istam, et habitatores ejus: in veritate enim misit me Dominus ad vos, ut loquerer in auribus vestris omnia verba hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 16, 'Et dixerunt principes et omnis populus ad sacerdotes et ad prophetas: Non est viro huic judicium mortis, quia in nomine Domini Dei nostri locutus est ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 17, 'Surrexerunt ergo viri de senioribus terræ, et dixerunt ad omnem cœtum populi, loquentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 18, 'Michæas de Morasthi fuit propheta in diebus Ezechiæ regis Juda, et ait ad omnem populum Juda, dicens: Hæc dicit Dominus exercituum: Sion quasi ager arabitur, et Jerusalem in acervum lapidum erit, et mons domus in excelsa silvarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 19, 'Numquid morte condemnavit eum Ezechias rex Juda, et omnis Juda? numquid non timuerunt Dominum, et deprecati sunt faciem Domini, et pœnituit Dominum mali quod locutus fuerat adversum eos? Itaque nos facimus malum grande contra animas nostras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 20, 'Fuit quoque vir prophetans in nomine Domini, Urias filius Semei de Cariathiarim, et prophetavit adversus civitatem istam, et adversus terram hanc, juxta omnia verba Jeremiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 21, 'Et audivit rex Joakim, et omnes potentes et principes ejus, verba hæc, et quæsivit rex interficere eum: et audivit Urias, et timuit, fugitque, et ingressus est \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 22, 'Et misit rex Joakim viros in \'gyptum, Elnathan filium Achobor, et viros cum eo, in \'gyptum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 23, 'et eduxerunt Uriam de \'gypto, et adduxerunt eum ad regem Joakim, et percussit eum gladio, et projecit cadaver ejus in sepulchris vulgi ignobilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 26, 24, 'Igitur manus Ahicam filii Saphan fuit cum Jeremia, ut non traderetur in manus populi, et interficerent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 1, 'In principio regni Joakim filii Josiæ regis Juda, factum est verbum istud ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 2, 'Hæc dicit Dominus ad me: Fac tibi vincula et catenas, et pones eas in collo tuo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 3, 'et mittes eas ad regem Edom, et ad regem Moab, et ad regem filiorum Ammon, et ad regem Tyri, et ad regem Sidonis, in manu nuntiorum qui venerunt Jerusalem ad Sedeciam regem Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 4, 'Et præcipies eis ut ad dominos suos loquantur: Hæc dicit Dominus exercituum, Deus Israël: Hæc dicetis ad dominos vestros:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 5, 'Ego feci terram, et homines, et jumenta quæ sunt super faciem terræ, in fortitudine mea magna, et in brachio meo extento, et dedi eam ei qui placuit in oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 6, 'Et nunc itaque ego dedi omnes terras istas in manu Nabuchodonosor regis Babylonis servi mei: insuper et bestias agri dedi ei, ut serviant illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 7, 'et servient ei omnes gentes, et filio ejus, et filio filii ejus, donec veniat tempus terræ ejus et ipsius: et servient ei gentes multæ et reges magni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 8, 'Gens autem et regnum quod non servierit Nabuchodonosor regi Babylonis, et quicumque non curvaverit collum suum sub jugo regis Babylonis, in gladio, et in fame, et in peste visitabo super gentem illam, ait Dominus, donec consumam eos in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 9, 'Vos ergo nolite audire prophetas vestros, et divinos, et somniatores, et augures, et maleficos, qui dicunt vobis: Non servietis regi Babylonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 10, 'quia mendacium prophetant vobis, ut longe vos faciant de terra vestra, et ejiciant vos, et pereatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 11, 'Porro gens quæ subjecerit cervicem suam sub jugo regis Babylonis, et servierit ei, dimittam eam in terra sua, dicit Dominus, et colet eam, et habitabit in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 12, 'Et ad Sedeciam regem Juda locutus sum secundum omnia verba hæc, dicens: Subjicite colla vestra sub jugo regis Babylonis, et servite ei et populo ejus, et vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 13, 'Quare moriemini, tu et populus tuus, gladio, et fame, et peste, sicut locutus est Dominus ad gentem quæ servire noluerit regi Babylonis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 14, 'Nolite audire verba prophetarum dicentium vobis: Non servietis regi Babylonis: quia mendacium ipsi loquuntur vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 15, 'quia non misi eos, ait Dominus, et ipsi prophetant in nomine meo mendaciter, ut ejiciant vos, et pereatis, tam vos quam prophetæ qui vaticinantur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 16, 'Et ad sacerdotes, et ad populum istum, locutus sum, dicens: Hæc dicit Dominus: Nolite audire verba prophetarum vestrorum, qui prophetant vobis, dicentes: Ecce vasa Domini revertentur de Babylone nunc cito: mendacium enim prophetant vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 17, 'Nolite ergo audire eos: sed servite regi Babylonis, ut vivatis: quare datur hæc civitas in solitudinem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 18, 'Et si prophetæ sunt, et est verbum Domini in eis, occurrant Domino exercituum, ut non veniant vasa quæ derelicta fuerant in domo Domini, et in domo regis Juda, et in Jerusalem, in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 19, 'Quia hæc dicit Dominus exercituum ad columnas, et ad mare, et ad bases, et ad reliqua vasorum quæ remanserunt in civitate hac,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 20, 'quæ non tulit Nabuchodonosor rex Babylonis cum transferret Jechoniam filium Joakim regem Juda de Jerusalem in Babylonem, et omnes optimates Juda et Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 21, 'quia hæc dicit Dominus exercituum, Deus Israël, ad vasa quæ derelicta sunt in domo Domini, et in domo regis Juda et Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 27, 22, 'In Babylonem transferentur, et ibi erunt usque ad diem visitationis suæ, dicit Dominus, et afferri faciam ea, et restitui in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 1, 'Et factum est in anno illo, in principio regni Sedeciæ regis Juda, in anno quarto, in mense quinto, dixit ad me Hananias filius Azur, propheta de Gabaon, in domo Domini, coram sacerdotibus et omni populo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 2, 'Hæc dicit Dominus exercituum, Deus Israël: Contrivi jugum regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 3, 'Adhuc duo anni dierum, et ego referri faciam ad locum istum omnia vasa domus Domini, quæ tulit Nabuchodonosor rex Babylonis de loco isto, et transtulit ea in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 4, 'Et Jechoniam filium Joakim regem Juda, et omnem transmigrationem Juda, qui ingressi sunt in Babylonem, ego convertam ad locum istum, ait Dominus: conteram enim jugum regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 5, 'Et dixit Jeremias propheta ad Hananiam prophetam, in oculis sacerdotum, et in oculis omnis populi qui stabat in domo Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 6, 'et ait Jeremias propheta: Amen! sic faciat Dominus: suscitet Dominus verba tua quæ prophetasti, ut referantur vasa in domum Domini, et omnis transmigratio de Babylone ad locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 7, 'Verumtamen audi verbum hoc quod ego loquor in auribus tuis, et in auribus universi populi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 8, 'prophetæ qui fuerunt ante me et ante te, ab initio, et prophetaverunt super terras multas et super regna magna de prælio, et de afflictione, et de fame:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 9, 'propheta qui vaticinatus est pacem, cum venerit verbum ejus, scietur propheta quem misit Dominus in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 10, 'Et tulit Hananias propheta catenam de collo Jeremiæ prophetæ, et confregit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 11, 'Et ait Hananias in conspectu omnis populi, dicens: Hæc dicit Dominus: Sic confringam jugum Nabuchodonosor regis Babylonis, post duos annos dierum de collo omnium gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 12, 'Et abiit Jeremias propheta in viam suam. Et factum est verbum Domini ad Jeremiam, postquam confregit Hananias propheta catenam de collo Jeremiæ prophetæ, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 13, 'Vade, et dices Hananiæ: Hæc dicit Dominus: Catenas ligneas contrivisti, et facies pro eis catenas ferreas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 14, 'Quia hæc dicit Dominus exercituum, Deus Israël: Jugum ferreum posui super collum cunctarum gentium istarum, ut serviant Nabuchodonosor regi Babylonis, et servient ei: insuper et bestias terræ dedi ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 15, 'Et dixit Jeremias propheta ad Hananiam prophetam: Audi, Hanania: non misit te Dominus, et tu confidere fecisti populum istum in mendacio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 16, 'Idcirco hæc dicit Dominus: Ecce ego mittam te a facie terræ: hoc anno morieris: adversum enim Dominum locutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 28, 17, 'Et mortuus est Hananias propheta in anno illo, mense septimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 1, 'Et hæc sunt verba libri quem misit Jeremias propheta de Jerusalem ad reliquias seniorum transmigrationis, et ad sacerdotes, et ad prophetas, et ad omnem populum quem traduxerat Nabuchodonosor de Jerusalem in Babylonem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 2, 'postquam egressus est Jechonias rex, et domina, et eunuchi, et principes Juda et Jerusalem, et faber et inclusor, de Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 3, 'in manu Elasa filii Saphan, et Gamariæ filii Helciæ, quos misit Sedecias rex Juda ad Nabuchodonosor regem Babylonis in Babylonem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 4, 'Hæc dicit Dominus exercituum, Deus Israël, omni transmigrationi quam transtuli de Jerusalem in Babylonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 5, '\'dificate domos, et habitate: et plantate hortos, et comedite fructum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 6, 'Accipite uxores, et generate filios et filias: et date filiis vestris uxores, et filias vestras date viris, et pariant filios et filias: et multiplicamini ibi, et nolite esse pauci numero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 7, 'Et quærite pacem civitatis ad quam transmigrare vos feci, et orate pro ea ad Dominum, quia in pace illius erit pax vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 8, 'Hæc enim dicit Dominus exercituum, Deus Israël: Non vos seducant prophetæ vestri qui sunt in medio vestrum, et divini vestri, et ne attendatis ad somnia vestra quæ vos somniatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 9, 'quia falso ipsi prophetant vobis in nomine meo, et non misi eos, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 10, 'Quia hæc dicit Dominus: Cum cœperint impleri in Babylone septuaginta anni, visitabo vos, et suscitabo super vos verbum meum bonum, ut reducam vos ad locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 11, 'Ego enim scio cogitationes quas ego cogito super vos, ait Dominus, cogitationes pacis et non afflictionis, ut dem vobis finem et patientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 12, 'Et invocabitis me, et ibitis: et orabitis me, et ego exaudiam vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 13, 'Quæretis me, et invenietis, cum quæsieritis me in toto corde vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 14, 'Et inveniar a vobis, ait Dominus: et reducam captivitatem vestram, et congregabo vos de universis gentibus et de cunctis locis ad quæ expuli vos, dicit Dominus, et reverti vos faciam de loco ad quem transmigrare vos feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 15, 'Quia dixistis: Suscitavit nobis Dominus prophetas in Babylone:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 16, 'quia hæc dicit Dominus ad regem qui sedet super solium David, et ad omnem populum habitatorem urbis hujus, ad fratres vestros qui non sunt egressi vobiscum in transmigrationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 17, 'hæc dicit Dominus exercituum: Ecce mittam in eos gladium, et famem, et pestem: et ponam eos quasi ficus malas, quæ comedi non possunt eo quod pessimæ sint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 18, 'et persequar eos in gladio, et in fame, et in pestilentia: et dabo eos in vexationem universis regnis terræ: in maledictionem, et in stuporem, et in sibilum, et in opprobrium cunctis gentibus ad quas ego ejeci eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 19, 'eo quod non audierint verba mea, dicit Dominus, quæ misit ad eos per servos meos prophetas, de nocte consurgens et mittens: et non audistis, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 20, 'Vos ergo audite verbum Domini, omnis transmigratio quam emisi de Jerusalem in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 21, 'Hæc dicit Dominus exercituum, Deus Israël, ad Achab filium Coliæ, et ad Sedeciam filium Maasiæ, qui prophetant vobis in nomine meo mendaciter: Ecce ego tradam eos in manus Nabuchodonosor regis Babylonis, et percutiet eos in oculis vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 22, 'et assumetur ex eis maledictio omni transmigrationi Juda quæ est in Babylone, dicentium: Ponat te Dominus sicut Sedeciam et sicut Achab, quos frixit rex Babylonis in igne:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 23, 'pro eo quod fecerint stultitiam in Israël, et mœchati sunt in uxores amicorum suorum, et locuti sunt verbum in nomine meo mendaciter, quod non mandavi eis. Ego sum judex et testis, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 24, 'Et ad Semeiam Nehelamiten dices:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 25, 'Hæc dicit Dominus exercituum, Deus Israël: Pro eo quod misisti in nomine tuo libros ad omnem populum qui est in Jerusalem, et ad Sophoniam filium Maasiæ sacerdotem, et ad universos sacerdotes, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 26, 'Dominus dedit te sacerdotem pro Jojade sacerdote, ut sis dux in domo Domini, super omnem virum arreptitium et prophetantem, ut mittas eum in nervum et in carcerem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 27, 'et nunc quare non increpasti Jeremiam Anathothiten, qui prophetat vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 28, 'Quia super hoc misit in Babylonem ad nos, dicens: Longum est: ædificate domos, et habitate: et plantate hortos, et comedite fructus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 29, 'Legit ergo Sophonias sacerdos librum istum in auribus Jeremiæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 30, 'Et factum est verbum Domini ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 31, 'Mitte ad omnem transmigrationem, dicens: Hæc dicit Dominus ad Semeiam Nehelamiten: Pro eo quod prophetavit vobis Semeias, et ego non misi eum, et fecit vos confidere in mendacio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 29, 32, 'idcirco hæc dicit Dominus: Ecce ego visitabo super Semeiam Nehelamiten, et super semen ejus: non erit ei vir sedens in medio populi hujus, et non videbit bonum quod ego faciam populo meo, ait Dominus, quia prævaricationem locutus est adversus Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 1, 'Hoc verbum quod factum est ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 2, 'Hæc dicit Dominus Deus Israël, dicens: Scribe tibi omnia verba quæ locutus sum ad te, in libro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 3, 'Ecce enim dies veniunt, dicit Dominus, et convertam conversionem populi mei Israël et Juda, ait Dominus: et convertam eos ad terram quam dedi patribus eorum, et possidebunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 4, 'Et hæc verba quæ locutus est Dominus ad Israël et ad Judam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 5, 'Quoniam hæc dicit Dominus: Vocem terroris audivimus: formido, et non est pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 6, 'Interrogate, et videte si generat masculus: quare ergo vidi omnis viri manum super lumbum suum, quasi parturientis, et conversæ sunt universæ facies in auruginem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 7, 'Væ! quia magna dies illa, nec est similis ejus: tempusque tribulationis est Jacob, et ex ipso salvabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 8, 'Et erit in die illa, ait Dominus exercituum: conteram jugum ejus de collo tuo, et vincula ejus dirumpam, et non dominabuntur ei amplius alieni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 9, 'sed servient Domino Deo suo, et David regi suo, quem suscitabo eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 10, 'Tu ergo ne timeas, serve meus Jacob, ait Dominus, neque paveas, Israël: quia ecce ego salvabo te de terra longinqua, et semen tuum de terra captivitatis eorum: et revertetur Jacob, et quiescet, et cunctis affluet bonis, et non erit quem formidet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 11, 'quoniam tecum ego sum, ait Dominus, ut salvem te. Faciam enim consummationem in cunctis gentibus in quibus dispersi te: te autem non faciam in consummationem: sed castigabo te in judicio, ut non videaris tibi innoxius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 12, 'Quia hæc dicit Dominus: Insanabilis fractura tua; pessima plaga tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 13, 'non est qui judicet judicium tuum ad alligandum: curationum utilitas non est tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 14, 'Omnes amatores tui obliti sunt tui, teque non quærent: plaga enim inimici percussi te castigatione crudeli: propter multitudinem iniquitatis tuæ dura facta sunt peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 15, 'Quid clamas super contritione tua? insanabilis est dolor tuus: propter multitudinem iniquitatis tuæ, et propter dura peccata tua, feci hæc tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 16, 'Propterea omnes qui comedunt te devorabuntur, et universi hostes tui in captivitatem ducentur: et qui te vastant vastabuntur, cunctosque prædatores tuos dabo in prædam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 17, 'Obducam enim cicatricem tibi, et a vulneribus tuis sanabo te, dicit Dominus. Quia ejectam vocaverunt te, Sion: hæc est, quæ non habebat requirentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 18, 'Hæc dicit Dominus: Ecce ego convertam conversionem tabernaculorum Jacob, et tectis ejus miserebor: et ædificabitur civitas in excelso suo, et templum juxta ordinem suum fundabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 19, 'et egredietur de eis laus, voxque ludentium. Et multiplicabo eos, et non minuentur: et glorificabo eos, et non attenuabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 20, 'Et erunt filii ejus sicut a principio, et cœtus ejus coram me permanebit, et visitabo adversum omnes qui tribulant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 21, 'Et erit dux ejus ex eo, et princeps de medio ejus producetur: et applicabo eum, et accedet ad me. Quis enim iste est qui applicet cor suum ut appropinquet mihi? ait Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 22, 'et eritis mihi in populum, et ego ero vobis in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 23, 'Ecce turbo Domini, furor egrediens, procella ruens: in capite impiorum conquiescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 30, 24, 'Non avertet iram indignationis Dominus, donec faciat et compleat cogitationem cordis sui: in novissimo dierum intelligetis ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 1, 'In tempore illo, dicit Dominus, ero Deus universis cognationibus Israël, et ipsi erunt mihi in populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 2, 'Hæc dicit Dominus: Invenit gratiam in deserto populus qui remanserat a gladio: vadet ad requiem suam Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 3, 'Longe Dominus apparuit mihi. Et in caritate perpetua dilexi te: ideo attraxi te, miserans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 4, 'Rursumque ædificabo te, et ædificaberis, virgo Israël: adhuc ornaberis tympanis tuis, et egredieris in choro ludentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 5, 'Adhuc plantabis vineas in montibus Samariæ: plantabunt plantantes, et donec tempus veniat, non vindemiabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 6, 'Quia erit dies in qua clamabunt custodes in monte Ephraim: Surgite, et ascendamus in Sion ad Dominum Deum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 7, 'Quia hæc dicit Dominus: Exsultate in lætitia, Jacob, et hinnite contra caput gentium: personate, et canite, et dicite: Salva, Domine, populum tuum, reliquias Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 8, 'Ecce ego adducam eos de terra aquilonis, et congregabo eos ab extremis terræ: inter quos erunt cæcus et claudus, prægnans et pariens simul, cœtus magnus revertentium huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 9, 'In fletu venient, et in misericordia reducam eos: et adducam eos per torrentes aquarum in via recta, et non impingent in ea, quia factus sum Israëli pater, et Ephraim primogenitus meus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 10, 'Audite verbum Domini, gentes, et annuntiate in insulis quæ procul sunt, et dicite: Qui dispersit Israël congregabit eum, et custodiet eum sicut pastor gregem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 11, 'Redemit enim Dominus Jacob, et liberavit eum de manu potentioris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 12, 'Et venient, et laudabunt in monte Sion: et confluent ad bona Domini, super frumento, et vino, et oleo, et fœtu pecorum et armentorum: eritque anima eorum quasi hortus irriguus, et ultra non esurient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 13, 'Tunc lætabitur virgo in choro, juvenes et senes simul: et convertam luctum eorum in gaudium, et consolabor eos, et lætificabo a dolore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 14, 'Et inebriabo animam sacerdotum pinguedine, et populus meus bonis meis adimplebitur, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 15, 'Hæc dicit Dominus: Vox in excelso audita est lamentationis: luctus, et fletus Rachel plorantis filios suos, et nolentis consolari super eis, quia non sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 16, 'Hæc dicit Dominus: Quiescat vox tua a ploratu, et oculi tui a lacrimis, quia est merces operi tuo, ait Dominus, et revertentur de terra inimici:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 17, 'et est spes novissimis tuis, ait Dominus, et revertentur filii ad terminos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 18, 'Audiens audivi Ephraim transmigrantem: Castigasti me, et eruditus sum, quasi juvenculus indomitus: converte me, et convertar, quia tu Dominus Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 19, 'Postquam enim convertisti me, egi pœnitentiam: et postquam ostendisti mihi, percussi femur meum. Confusus sum, et erubui, quoniam sustinui opprobrium adolescentiæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 20, 'Si filius honorabilis mihi Ephraim, si puer delicatus! quia ex quo locutus sum de eo, adhuc recordabor ejus. Idcirco conturbata sunt viscera mea super eum: miserans miserebor ejus, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 21, 'Statue tibi speculam; pone tibi amaritudines; dirige cor tuum in viam rectam in qua ambulasti: revertere, virgo Israël, revertere ad civitates tuas istas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 22, 'Usquequo deliciis dissolveris, filia vaga? quia creavit Dominus novum super terram: femina circumdabit virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 23, 'Hæc dicit Dominus exercituum, Deus Israël: Adhuc dicent verbum istud in terra Juda et in urbibus ejus, cum convertero captivitatem eorum: Benedicat tibi Dominus, pulchritudo justitiæ, mons sanctus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 24, 'et habitabunt in eo Judas et omnes civitates ejus simul, agricolæ et minantes greges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 25, 'Quia inebriavi animam lassam, et omnem animam esurientem saturavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 26, 'Ideo quasi de somno suscitatus sum: et vidi, et somnus meus dulcis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 27, 'Ecce dies veniunt, dicit Dominus, et seminabo domum Israël et domum Juda semine hominum et semine jumentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 28, 'Et sicut vigilavi super eos ut evellerem, et demolirer, et dissiparem, et disperderem, et affligerem, sic vigilabo super eos ut ædificem et plantem, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 29, 'In diebus illis non dicent ultra: Patres comederunt uvam acerbam, et dentes filiorum obstupuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 30, 'Sed unusquisque in iniquitate sua morietur: omnis homo qui comederit uvam acerbam, obstupescent dentes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 31, 'Ecce dies venient, dicit Dominus, et feriam domui Israël et domui Juda fœdus novum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 32, 'non secundum pactum quod pepigi cum patribus eorum in die qua apprehendi manum eorum ut educerem eos de terra \'gypti, pactum quod irritum fecerunt: et ego dominatus sum eorum, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 33, 'Sed hoc erit pactum quod feriam cum domo Israël post dies illos, dicit Dominus: dabo legem meam in visceribus eorum, et in corde eorum scribam eam, et ero eis in Deum, et ipsi erunt mihi in populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 34, 'et non docebit ultra vir proximum suum et vir fratrem suum, dicens: Cognosce Dominum: omnes enim cognoscent me, a minimo eorum usque ad maximum, ait Dominus: quia propitiabor iniquitati eorum, et peccati eorum non memorabor amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 35, 'Hæc dicit Dominus qui dat solem in lumine diei, ordinem lunæ et stellarum in lumine noctis: qui turbat mare, et sonant fluctus ejus: Dominus exercituum nomen illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 36, 'Si defecerint leges istæ coram me, dicit Dominus, tunc et semen Israël deficiet, ut non sit gens coram me cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 37, 'Hæc dicit Dominus: Si mensurari potuerint cæli sursum, et investigari fundamenta terræ deorsum, et ego abjiciam universum semen Israël, propter omnia quæ fecerunt, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 38, 'Ecce dies veniunt, dicit Dominus, et ædificabitur civitas Domino, a turre Hananeel usque ad portam anguli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 39, 'Et exibit ultra norma mensuræ in conspectu ejus super collem Gareb, et circuibit Goatha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 31, 40, 'et omnem vallem cadaverum, et cineris, et universam regionem mortis usque ad torrentem Cedron, et usque ad angulum portæ equorum orientalis, Sanctum Domini: non evelletur, et non destruetur ultra in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 1, 'Verbum quod factum est ad Jeremiam a Domino, in anno decimo Sedeciæ regis Juda, ipse est annus decimusoctavus Nabuchodonosor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 2, 'Tunc exercitus regis Babylonis obsidebat Jerusalem, et Jeremias propheta erat clausus in atrio carceris qui erat in domo regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 3, 'Clauserat enim eum Sedecias rex Juda, dicens: Quare vaticinaris, dicens: Hæc dicit Dominus: Ecce ego dabo civitatem istam in manus regis Babylonis, et capiet eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 4, 'et Sedecias rex Juda non effugiet de manu Chaldæorum, sed tradetur in manus regis Babylonis: et loquetur os ejus cum ore illius, et oculi ejus oculos illius videbunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 5, 'et in Babylonem ducet Sedeciam, et ibi erit donec visitem eum, ait Dominus: si autem dimicaveritis adversum Chaldæos, nihil prosperum habebitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 6, 'Et dixit Jeremias: Factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 7, 'Ecce Hanameel filius Sellum, patruelis tuus, veniet ad te, dicens: Eme tibi agrum meum qui est in Anathoth, tibi enim competit ex propinquitate ut emas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 8, 'Et venit ad me Hanameel filius patrui mei, secundum verbum Domini, ad vestibulum carceris, et ait ad me: Posside agrum meum qui est in Anathoth, in terra Benjamin, quia tibi competit hæreditas, et tu propinquus es ut possideas. Intellexi autem quod verbum Domini esset:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 9, 'et emi agrum ab Hanameel filio patrui mei, qui est in Anathoth, et appendi ei argentum: septem stateres, et decem argenteos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 10, 'Et scripsi in libro, et signavi, et adhibui testes, et appendi argentum in statera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 11, 'Et accepi librum possessionis signatum, et stipulationes, et rata, et signa forinsecus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 12, 'et dedi librum possessionis Baruch filio Neri filii Maasiæ, in oculis Hanameel patruelis mei, in oculis testium qui scripti erant in libro emptionis, et in oculis omnium Judæorum qui sedebant in atrio carceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 13, 'Et præcepi Baruch coram eis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 14, 'Hæc dicit Dominus exercituum, Deus Israël: Sume libros istos, librum emptionis hunc signatum, et librum hunc qui apertus est, et pone illos in vase fictili, ut permanere possint diebus multis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 15, 'hæc enim dicit Dominus exercituum, Deus Israël: Adhuc possidebuntur domus, et agri, et vineæ in terra ista.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 16, 'Et oravi ad Dominum, postquam tradidi librum possessionis Baruch filio Neri, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 17, 'Heu! heu! heu! Domine Deus, ecce tu fecisti cælum et terram in fortitudine tua magna, et in brachio tuo extento: non erit tibi difficile omne verbum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 18, 'qui facis misericordiam in millibus, et reddis iniquitatem patrum in sinum filiorum eorum post eos: fortissime, magne, et potens, Dominus exercituum nomen tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 19, 'Magnus consilio, et incomprehensibilis cogitatu: cujus oculi aperti sunt super omnes vias filiorum Adam, ut reddas unicuique secundum vias suas, et secundum fructum adinventionum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 20, 'Qui posuisti signa et portenta in terra \'gypti usque ad diem hanc, et in Israël, et in hominibus, et fecisti tibi nomen sicut est dies hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 21, 'Et eduxisti populum tuum Israël de terra \'gypti, in signis et in portentis, et in manu robusta et in brachio extento, et in terrore magno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 22, 'et dedisti eis terram hanc, quam jurasti patribus eorum ut dares eis, terram fluentem lacte et melle.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 23, 'Et ingressi sunt, et possederunt eam, et non obedierunt voci tuæ, et in lege tua non ambulaverunt: omnia quæ mandasti eis ut facerent non fecerunt, et evenerunt eis omnia mala hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 24, 'Ecce munitiones exstructæ sunt adversum civitatem ut capiatur, et urbs data est in manus Chaldæorum qui præliantur adversus eam, a facie gladii, et famis, et pestilentiæ: et quæcumque locutus es, acciderunt, ut tu ipse cernis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 25, 'Et tu dicis mihi, Domine Deus: Eme agrum argento, et adhibe testes, cum urbs data sit in manus Chaldæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 26, 'Et factum est verbum Domini ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 27, 'Ecce ego Dominus Deus universæ carnis: numquid mihi difficile erit omne verbum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 28, 'Propterea hæc dicit Dominus: Ecce ego tradam civitatem istam in manus Chaldæorum, et in manus regis Babylonis, et capient eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 29, 'Et venient Chaldæi præliantes adversum urbem hanc, et succendent eam igni, et comburent eam, et domos in quarum domatibus sacrificabant Baal, et libabant diis alienis libamina ad irritandum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 30, 'Erant enim filii Israël et filii Juda jugiter facientes malum in oculis meis ab adolescentia sua: filii Israël, qui usque nunc exacerbant me in opere manuum suarum, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 31, 'Quia in furore et in indignatione mea facta est mihi civitas hæc, a die qua ædificaverunt eam usque ad diem istam qua auferetur de conspectu meo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 32, 'propter malitiam filiorum Israël et filiorum Juda, quam fecerunt ad iracundiam me provocantes, ipsi et reges eorum, principes eorum, et sacerdotes eorum, et prophetæ eorum, viri Juda et habitatores Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 33, 'Et verterunt ad me terga, et non facies, cum docerem eos diluculo et erudirem, et nollent audire, ut acciperent disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 34, 'Et posuerunt idola sua in domo in qua invocatum est nomen meum, ut polluerent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 35, 'Et ædificaverunt excelsa Baal quæ sunt in valle filii Ennom, ut initiarent filios suos et filias suas Moloch, quod non mandavi eis, nec ascendit in cor meum ut facerent abominationem hanc: et in peccatum deducerent Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 36, 'Et nunc propter ista, hæc dicit Dominus Deus Israël ad civitatem hanc, de qua vos dicitis quod tradetur in manus regis Babylonis, in gladio, et in fame, et in peste:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 37, 'Ecce ego congregabo eos de universis terris ad quas ejeci eos in furore meo, et in ira mea, et in indignatione grandi: et reducam eos ad locum istum, et habitare eos faciam confidenter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 38, 'et erunt mihi in populum, et ego ero eis in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 39, 'Et dabo eis cor unum, et viam unam, ut timeant me universis diebus, et bene sit eis, et filiis eorum post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 40, 'Et feriam eis pactum sempiternum, et non desinam eis benefacere: et timorem meum dabo in corde eorum, ut non recedant a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 41, 'Et lætabor super eis, cum bene eis fecero: et plantabo eos in terra ista in veritate, in toto corde meo et in tota anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 42, 'Quia hæc dicit Dominus: Sicut adduxi super populum istum omne malum hoc grande, sic adducam super eos omne bonum quod ego loquor ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 43, 'Et possidebuntur agri in terra ista, de qua vos dicitis quod deserta sit, eo quod non remanserit homo et jumentum, et data sit in manus Chaldæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 32, 44, 'Agri ementur pecunia, et scribentur in libro, et imprimetur signum, et testis adhibebitur, in terra Benjamin et in circuitu Jerusalem, in civitatibus Juda, et in civitatibus montanis, et in civitatibus campestribus, et in civitatibus quæ ad austrum sunt, quia convertam captivitatem eorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 1, 'Et factum est verbum Domini ad Jeremiam secundo, cum adhuc clausus esset in atrio carceris, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 2, 'Hæc dicit Dominus, qui facturus est, et formaturus illud, et paraturus: Dominus nomen ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 3, 'Clama ad me, et exaudiam te, et annuntiabo tibi grandia et firma quæ nescis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 4, 'Quia hæc dicit Dominus Deus Israël ad domos urbis hujus, et ad domos regis Juda, quæ destructæ sunt, et ad munitiones, et ad gladium');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 5, 'venientium ut dimicent cum Chaldæis, et impleant eas cadaveribus hominum quos percussi in furore meo et in indignatione mea, abscondens faciem meam a civitate hac, propter omnem malitiam eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 6, 'Ecce ego obducam eis cicatricem et sanitatem, et curabo eos, et revelabo illis deprecationem pacis et veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 7, 'Et convertam conversionem Juda et conversionem Jerusalem, et ædificabo eos sicut a principio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 8, 'Et emundabo illos ab omni iniquitate sua in qua peccaverunt mihi, et propitius ero cunctis iniquitatibus eorum, in quibus dereliquerunt mihi et spreverunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 9, 'Et erit mihi in nomen, et in gaudium, et in laudem, et in exsultationem cunctis gentibus terræ, quæ audierint omnia bona quæ ego facturus sum eis: et pavebunt et turbabuntur in universis bonis, et in omni pace quam ego faciam eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 10, 'Hæc dicit Dominus: Adhuc audietur in loco isto quem vos dicitis esse desertum, eo quod non sit homo nec jumentum in civitatibus Juda, et foris Jerusalem, quæ desolatæ sunt, absque homine, et absque habitatore, et absque pecore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 11, 'vox gaudii et vox lætitiæ, vox sponsi et vox sponsæ, vox dicentium: Confitemini Domino exercituum, quoniam bonus Dominus, quoniam in æternum misericordia ejus: et portantium vota in domum Domini: reducam enim conversionem terræ sicut a principio, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 12, 'Hæc dicit Dominus exercituum: Adhuc erit in loco isto deserto, absque homine et absque jumento, et in cunctis civitatibus ejus, habitaculum pastorum accubantium gregum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 13, 'In civitatibus montuosis, et in civitatibus campestribus, et in civitatibus quæ ad austrum sunt, et in terra Benjamin, et in circuitu Jerusalem, et in civitatibus Juda, adhuc transibunt greges ad manum numerantis, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 14, 'Ecce dies veniunt, dicit Dominus, et suscitabo verbum bonum quod locutus sum ad domum Israël et ad domum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 15, 'In diebus illis et in tempore illo germinare faciam David germen justitiæ, et faciet judicium et justitiam in terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 16, 'in diebus illis salvabitur Juda, et Jerusalem habitabit confidenter: et hoc est nomen quod vocabunt eum: Dominus justus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 17, 'Quia hæc dicit Dominus: Non interibit de David vir qui sedeat super thronum domus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 18, 'et de sacerdotibus et de Levitis non interibit vir a facie mea, qui offerat holocautomata, et incendat sacrificum, et cædat victimas omnibus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 19, 'Et factum est verbum Domini ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 20, 'Hæc dicit Dominus: Si irritum potest fieri pactum meum cum die, et pactum meum cum nocte, ut non sit dies et nox in tempore suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 21, 'et pactum meum irritum esse poterit cum David servo meo, ut non sit ex eo filius qui regnet in throno ejus, et Levitæ et sacerdotes ministri mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 22, 'Sicuti enumerari non possunt stellæ cæli, et metiri arena maris, sic multiplicabo semen David servi mei, et Levitas ministros meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 23, 'Et factum est verbum Domini ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 24, 'Numquid non vidisti quid populus hic locutus sit, dicens: Duæ cognationes quas elegerat Dominus abjectæ sunt? et populum meum despexerunt, eo quod non sit ultra gens coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 25, 'Hæc dicit Dominus: Si pactum meum inter diem et noctem, et leges cælo et terræ non posui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 33, 26, 'equidem et semen Jacob et David servi mei projiciam, ut non assumam de semine ejus principes seminis Abraham, Isaac, et Jacob: reducam enim conversionem eorum, et miserebor eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 1, 'Verbum quod factum est ad Jeremiam a Domino quando Nabuchodonosor rex Babylonis, et omnis exercitus ejus, universaque regna terræ quæ erant sub potestate manus ejus, et omnes populi, bellabant contra Jerusalem, et contra omnes urbes ejus, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 2, 'Hæc dicit Dominus Deus Israël: Vade, et loquere ad Sedeciam regem Juda, et dices ad eum: Hæc dicit Dominus: Ecce ego tradam civitatem hanc in manus regis Babylonis, et succendet eam igni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 3, 'et tu non effugies de manu ejus, sed comprehensione capieris, et in manu ejus traderis: et oculi tui oculos regis Babylonis videbunt, et os ejus cum ore tuo loquetur, et Babylonem introibis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 4, 'Attamen audi verbum Domini, Sedecia, rex Juda: Hæc dicit Dominus ad te: Non morieris in gladio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 5, 'sed in pace morieris: et secundum combustiones patrum tuorum, regum priorum qui fuerunt ante te, sic comburent te: et: Væ domine, plangent te: quia verbum ego locutus sum, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 6, 'Et locutus est Jeremias propheta ad Sedeciam regem Juda universa verba hæc in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 7, 'Et exercitus regis Babylonis pugnabat contra Jerusalem, et contra omnes civitates Juda quæ reliquæ erant, contra Lachis et contra Azecha: hæ enim supererant de civitatibus Juda, urbes munitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 8, 'Verbum quod factum est ad Jeremiam a Domino, postquam percussit rex Sedecias fœdus cum omni populo in Jerusalem, prædicans');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 9, 'ut dimitteret unusquisque servum suum et unusquisque ancillam suam, Hebræum et Hebræam, liberos, et nequaquam dominarentur eis, id est, in Judæo et fratre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 10, 'Audierunt ergo omnes principes et universus populus qui inierant pactum ut dimitteret unusquisque servum suum et unusquisque ancillam suam liberos, et ultra non dominarentur eis: audierunt igitur, et dimiserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 11, 'Et conversi sunt deinceps: et retraxerunt servos et ancillas suas quos dimiserant liberos, et subjugaverunt in famulos et famulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 12, 'Et factum est verbum Domini ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 13, 'Hæc dicit Dominus Deus Israël: Ego percussi fœdus cum patribus vestris in die qua eduxi eos de terra \'gypti, de domo servitutis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 14, 'Cum completi fuerint septem anni, dimittat unusquisque fratrem suum Hebræum, qui venditus est ei: et serviet tibi sex annis, et dimittes eum a te liberum: et non audierunt patres vestri me, nec inclinaverunt aurem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 15, 'Et conversi estis vos hodie, et fecistis quod rectum est in oculis meis, ut prædicaretis libertatem unusquisque ad amicum suum: et inistis pactum in conspectu meo, in domo in qua invocatum est nomen meum super eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 16, 'et reversi estis, et commaculastis nomen meum, et reduxistis unusquisque servum suum et unusquisque ancillam suam quos dimiseratis ut essent liberi et suæ potestatis, et subjugastis eos ut sint vobis servi et ancillæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 17, 'Propterea hæc dicit Dominus: Vos non audistis me, ut prædicaretis libertatem unusquisque fratri suo et unusquisque amico suo: ecce ego prædico vobis libertatem, ait Dominus, ad gladium, ad pestem, et ad famem, et dabo vos in commotionem cunctis regnis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 18, 'Et dabo viros qui prævaricantur fœdus meum, et non observaverunt verba fœderis quibus assensi sunt in conspectu meo, vitulum quem conciderunt in duas partes, et transierunt inter divisiones ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 19, 'principes Juda et principes Jerusalem, eunuchi et sacerdotes, et omnis populus terræ, qui transierunt inter divisiones vituli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 20, 'et dabo eos in manus inimicorum suorum, et in manus quærentium animam eorum, et erit morticinum eorum in escam volatilibus cæli et bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 21, 'Et Sedeciam regem Juda, et principes ejus, dabo in manus inimicorum suorum, et in manus quærentium animas eorum, et in manus exercituum regis Babylonis, qui recesserunt a vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 34, 22, 'Ecce ego præcipio, dicit Dominus, et reducam eos in civitatem hanc, et præliabuntur adversus eam, et capient eam, et incendent igni: et civitates Juda dabo in solitudinem, eo quod non sit habitator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 1, 'Verbum quod factum est ad Jeremiam a Domino in diebus Joakim filii Josiæ regis Juda, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 2, 'Vade ad domum Rechabitarum, et loquere eis, et introduces eos in domum Domini, in unam exedram thesaurorum, et dabis eis bibere vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 3, 'Et assumpsi Jezoniam filium Jeremiæ filii Habsaniæ, et fratres ejus, et omnes filios ejus, et universam domum Rechabitarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 4, 'et introduxi eos in domum Domini, ad gazophylacium filiorum Hanan filii Jegedeliæ hominis Dei, quod erat juxta gazophylacium principum, super thesaurum Maasiæ filii Sellum, qui erat custos vestibuli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 5, 'et posui coram filiis domus Rechabitarum scyphos plenos vino, et calices, et dixi ad eos: Bibite vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 6, 'Qui responderunt Non bibemus vinum, quia Jonadab filius Rechab, pater noster, præcepit nobis, dicens: Non bibetis vinum, vos et filii vestri, usque in sempiternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 7, 'et domum non ædificabitis, et sementem non seretis, et vineas non plantabitis, nec habebitis: sed in tabernaculis habitabitis cunctis diebus vestris, ut vivatis diebus multis super faciem terræ in qua vos peregrinamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 8, 'Obedivimus ergo voci Jonadab filii Rechab, patris nostri, in omnibus quæ præcepit nobis, ita ut non biberemus vinum cunctis diebus nostris, nos, et mulieres nostræ, filii, et filiæ nostræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 9, 'et non ædificaremus domos ad habitandum: et vineam, et agrum, et sementem non habuimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 10, 'sed habitavimus in tabernaculis, et obedientes fuimus juxta omnia quæ præcepit nobis Jonadab pater noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 11, 'Cum autem ascendisset Nabuchodonosor rex Babylonis ad terram nostram, diximus: Venite, et ingrediamur Jerusalem a facie exercitus Chaldæorum, et a facie exercitus Syriæ: et mansimus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 12, 'Et factum est verbum Domini ad Jeremiam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 13, 'Hæc dicit Dominus exercituum, Deus Israël: Vade, et dic viris Juda et habitatoribus Jerusalem: Numquid non recipietis disciplinam, ut obediatis verbis meis? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 14, 'Prævaluerunt sermones Jonadab filii Rechab quos præcepit filiis suis ut non biberent vinum, et non biberunt usque ad diem hanc, quia obedierunt præcepto patris sui: ego autem locutus sum ad vos, de mane consurgens et loquens, et non obedistis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 15, 'Misique ad vos omnes servos meos prophetas, consurgens diluculo mittensque, et dicens: Convertimini unusquisque a via sua pessima, et bona facite studia vestra: et nolite sequi deos alienos, neque colatis eos, et habitabitis in terra quam dedi vobis et patribus vestris: et non inclinastis aurem vestram, neque audistis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 16, 'Firmaverunt igitur filii Jonadab filii Rechab præceptum patris sui quod præceperat eis: populus autem iste non obedivit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 17, 'Idcirco hæc dicit Dominus exercituum, Deus Israël: Ecce ego adducam super Juda et super omnes habitatores Jerusalem universam afflictionem quam locutus sum adversum illos, eo quod locutus sum ad illos, et non audierunt; vocavi illos, et non responderunt mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 18, 'Domui autem Rechabitarum dixit Jeremias: Hæc dicit Dominus exercituum, Deus Israël: Pro eo quod obedistis præcepto Jonadab patris vestri, et custodistis omnia mandata ejus, et fecistis universa quæ præcepit vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 35, 19, 'propterea hæc dicit Dominus exercituum, Deus Israël: Non deficiet vir de stirpe Jonadab filii Rechab, stans in conspectu meo cunctis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 1, 'Et factum est in anno quarto Joakim filii Josiæ regis Juda, factum est verbum hoc ad Jeremiam a Domino, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 2, 'Tolle volumen libri, et scribes in eo omnia verba quæ locutus sum tibi adversum Israël et Judam, et adversum omnes gentes, a die qua locutus sum ad te ex diebus Josiæ usque ad diem hanc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 3, 'si forte, audiente domo Juda universa mala quæ ego cogito facere eis, revertatur unusquisque a via sua pessima, et propitius ero iniquitati et peccato eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 4, 'Vocavit ergo Jeremias Baruch filium Neriæ: et scripsit Baruch ex ore Jeremiæ omnes sermones Domini quos locutus est ad eum, in volumine libri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 5, 'et præcepit Jeremias Baruch, dicens: Ego clausus sum, nec valeo ingredi domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 6, 'Ingredere ergo tu, et lege de volumine in quo scripsisti ex ore meo verba Domini, audiente populo in domo Domini, in die jejunii: insuper et audiente universo Juda qui veniunt de civitatibus suis, leges eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 7, 'si forte cadat oratio eorum in conspectu Domini, et revertatur unusquisque a via sua pessima: quoniam magnus furor et indignatio est quam locutus est Dominus adversus populum hunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 8, 'Et fecit Baruch filius Neriæ juxta omnia quæ præceperat ei Jeremias propheta, legens ex volumine sermones Domini in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 9, 'Factum est autem in anno quinto Joakim filii Josiæ regis Juda, in mense nono: prædicaverunt jejunium in conspectu Domini omni populo in Jerusalem, et universæ multitudini quæ confluxerat de civitatibus Juda in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 10, 'Legitque Baruch ex volumine sermones Jeremiæ in domo Domini, in gazophylacio Gamariæ filii Saphan scribæ, in vestibulo superiori, in introitu portæ novæ domus Domini, audiente omni populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 11, 'Cumque audisset Michæas filius Gamariæ filii Saphan omnes sermones Domini ex libro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 12, 'descendit in domum regis, ad gazophylacium scribæ, et ecce ibi omnes principes sedebant: Elisama scriba, et Dalaias filius Semeiæ, et Elnathan filius Achobor, et Gamarias filius Saphan, et Sedecias filius Hananiæ, et universi principes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 13, 'et nuntiavit eis Michæas omnia verba quæ audivit, legente Baruch ex volumine in auribus populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 14, 'Miserunt itaque omnes principes ad Baruch Judi filium Nathaniæ filii Selemiæ filii Chusi, dicentes: Volumen ex quo legisti, audiente populo, sume in manu tua, et veni. Tulit ergo Baruch filius Neriæ volumen in manu sua, et venit ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 15, 'et dixerunt ad eum: Sede, et lege hæc in auribus nostris. Et legit Baruch in auribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 16, 'Igitur cum audissent omnia verba, obstupuerunt unusquisque ad proximum suum, et dixerunt ad Baruch: Nuntiare debemus regi omnes sermones istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 17, 'Et interrogaverunt eum, dicentes: Indica nobis quomodo scripsisti omnes sermones istos ex ore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 18, 'Dixit autem eis Baruch: Ex ore suo loquebatur quasi legens ad me omnes sermones istos, et ego scribebam in volumine atramento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 19, 'Et dixerunt principes ad Baruch: Vade, et abscondere, tu et Jeremias, et nemo sciat ubi sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 20, 'Et ingressi sunt ad regem in atrium: porro volumen commendaverunt in gazophylacio Elisamæ scribæ, et nuntiaverunt, audiente rege, omnes sermones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 21, 'Misitque rex Judi ut sumeret volumen: qui tollens illud de gazophylacio Elisamæ scribæ, legit, audiente rege et universis principibus qui stabant circa regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 22, 'Rex autem sedebat in domo hiemali, in mense nono, et posita erat arula coram eo plena prunis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 23, 'Cumque legisset Judi tres pagellas vel quatuor, scidit illud scalpello scribæ, et projecit in ignem qui erat super arulam, donec consumeretur omne volumen igni qui erat in arula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 24, 'Et non timuerunt, neque sciderunt vestimenta sua, rex et omnes servi ejus qui audierunt universos sermones istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 25, 'Verumtamen Elnathan, et Dalaias, et Gamarias, contradixerunt regi, ne combureret librum: et non audivit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 26, 'Et præcepit rex Jeremiel filio Amelech, et Saraiæ filio Ezriel, et Selemiæ filio Abdeel, ut comprehenderent Baruch scribam, et Jeremiam prophetam: abscondit autem eos Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 27, 'Et factum est verbum Domini ad Jeremiam prophetam, postquam combusserat rex volumen et sermones quos scripserat Baruch ex ore Jeremiæ, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 28, 'Rursum tolle volumen aliud, et scribe in eo omnes sermones priores qui erant in primo volumine, quod combussit Joakim rex Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 29, 'Et ad Joakim regem Juda dices: Hæc dicit Dominus: Tu combussisti volumen illud, dicens: Quare scripsisti in eo annuntians: Festinus veniet rex Babylonis, et vastabit terram hanc, et cessare faciet ex illa hominem et jumentum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 30, 'Propterea hæc dicit Dominus contra Joakim regem Juda: Non erit ex eo qui sedeat super solium David: et cadaver ejus projicietur ad æstum per diem, et ad gelu per noctem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 31, 'Et visitabo contra eum, et contra semen ejus, et contra servos ejus, iniquitates suas: et adducam super eos, et super habitatores Jerusalem, et super viros Juda, omne malum quod locutus sum ad eos, et non audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 36, 32, 'Jeremias autem tulit volumen aliud, et dedit illud Baruch filio Neriæ scribæ: qui scripsit in eo ex ore Jeremiæ omnes sermones libri quem combusserat Joakim rex Juda igni: et insuper additi sunt sermones multo plures quam antea fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 1, 'Et regnavit rex Sedecias filius Josiæ pro Jechonia filio Joakim, quem constituit regem Nabuchodonosor rex Babylonis in terra Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 2, 'et non obedivit ipse, et servi ejus, et populus terræ, verbis Domini, quæ locutus est in manu Jeremiæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 3, 'Et misit rex Sedecias Juchal filium Selemiæ, et Sophoniam filium Maasiæ, sacerdotem, ad Jeremiam prophetam, dicens: Ora pro nobis Dominum Deum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 4, 'Jeremias autem libere ambulabat in medio populi: non enim miserant eum in custodiam carceris. Igitur exercitus Pharaonis egressus est de \'gypto, et audientes Chaldæi qui obsidebant Jerusalem, hujuscemodi nuntium, recesserunt ab Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 5, 'Et factum est verbum Domini ad Jeremiam prophetam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 6, 'Hæc dicit Dominus Deus Israël: Sic dicetis regi Juda, qui misit vos ad me interrogandum: Ecce exercitus Pharaonis, qui egressus est vobis in auxilium, revertetur in terram suam in \'gyptum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 7, 'et redient Chaldæi, et bellabunt contra civitatem hanc, et capient eam, et succendent eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 8, 'Hæc dicit Dominus: Nolite decipere animas vestras, dicentes: Euntes abibunt, et recedent a nobis Chaldæi: quia non abibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 9, 'Sed etsi percusseritis omnem exercitum Chaldæorum qui præliantur adversum vos, et derelicti fuerint ex eis aliqui vulnerati, singuli de tentorio suo consurgent, et incendent civitatem hanc igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 10, 'Ergo cum recessisset exercitus Chaldæorum ab Jerusalem, propter exercitum Pharaonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 11, 'egressus est Jeremias de Jerusalem ut iret in terram Benjamin, et divideret ibi possessionem in conspectu civium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 12, 'Cumque pervenisset ad portam Benjamin, erat ibi custos portæ per vices, nomine Jerias filius Selemiæ filii Hananiæ: et apprehendit Jeremiam prophetam, dicens: Ad Chaldæos profugis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 13, 'Et respondit Jeremias: Falsum est: non fugio ad Chaldæos. Et non audivit eum, sed comprehendit Jerias Jeremiam, et adduxit eum ad principes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 14, 'quam ob rem irati principes contra Jeremiam, cæsum eum miserunt in carcerem qui erat in domo Jonathan scribæ: ipse enim præpositus erat super carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 15, 'Itaque ingressus est Jeremias in domum laci et in ergastulum: et sedit ibi Jeremias diebus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 16, 'Mittens autem Sedecias rex, tulit eum: et interrogavit eum in domo sua abscondite, et dixit: Putasne est sermo a Domino? Et dixit Jeremias: Est: et ait: In manus regis Babylonis traderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 17, 'Et dixit Jeremias ad regem Sedeciam: Quid peccavi tibi, et servis tuis, et populo tuo, quia misisti me in domum carceris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 18, 'ubi sunt prophetæ vestri, qui prophetabant vobis, et dicebant: Non veniet rex Babylonis super vos, et super terram hanc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 19, 'Nunc ergo audi, obsecro, domine mi rex: valeat deprecatio mea in conspectu tuo, et ne me remittas in domum Jonathan scribæ, ne moriar ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 37, 20, 'Præcepit ergo rex Sedecias ut traderetur Jeremias in vestibulo carceris, et daretur ei torta panis quotidie, excepto pulmento, donec consumerentur omnes panes de civitate: et mansit Jeremias in vestibulo carceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 1, 'Audivit autem Saphatias filius Mathan, et Gedelias filius Phassur, et Juchal filius Selemiæ, et Phassur filius Melchiæ, sermones quos Jeremias loquebatur ad omnem populum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 2, 'Hæc dicit Dominus: Quicumque manserit in civitate hac, morietur gladio, et fame, et peste: qui autem profugerit ad Chaldæos, vivet, et erit anima ejus sospes et vivens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 3, 'Hæc dicit Dominus: Tradendo tradetur civitas hæc in manu exercitus regis Babylonis, et capiet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 4, 'Et dixerunt principes regi: Rogamus ut occidatur homo iste: de industria enim dissolvit manus virorum bellantium qui remanserunt in civitate hac, et manus universi populi, loquens ad eos juxta verba hæc: siquidem homo iste non quærit pacem populo huic, sed malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 5, 'Et dixit rex Sedecias: Ecce ipse in manibus vestris est: nec enim fas est regem vobis quidquam negare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 6, 'Tulerunt ergo Jeremiam, et projecerunt eum in lacum Melchiæ filii Amelech, qui erat in vestibulo carceris: et submiserunt Jeremiam funibus in lacum, in quo non erat aqua, sed lutum: descendit itaque Jeremias in cœnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 7, 'Audivit autem Abdemelech \'thiops, vir eunuchus, qui erat in domo regis, quod misissent Jeremiam in lacum. Porro rex sedebat in porta Benjamin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 8, 'et egressus est Abdemelech de domo regis, et locutus est ad regem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 9, 'Domine mi rex, male fecerunt viri isti omnia quæcumque perpetrarunt contra Jeremiam prophetam, mittentes eum in lacum, ut moriatur ibi fame: non sunt enim panes ultra in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 10, 'Præcepit itaque rex Abdemelech \'thiopi, dicens: Tolle tecum hinc triginta viros, et leva Jeremiam prophetam de lacu, antequam moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 11, 'Assumptis ergo Abdemelech secum viris, ingressus est domum regis, quæ erat sub cellario, et tulit inde veteres pannos, et antiqua quæ computruerant, et submisit ea ad Jeremiam in lacum per funiculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 12, 'Dixitque Abdemelech \'thiops ad Jeremiam: Pone veteres pannos, et hæc scissa et putrida, sub cubito manuum tuarum, et super funes. Fecit ergo Jeremias sic,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 13, 'et extraxerunt Jeremiam funibus, et eduxerunt eum de lacu: mansit autem Jeremias in vestibulo carceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 14, 'Et misit rex Sedecias, et tulit ad se Jeremiam prophetam ad ostium tertium quod erat in domo Domini: et dixit rex ad Jeremiam: Interrogo ego te sermonem, ne abscondas a me aliquid.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 15, 'Dixit autem Jeremias ad Sedeciam: Si annuntiavero tibi, numquid non interficies me? et si consilium dedero tibi, non me audies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 16, 'Juravit ergo rex Sedecias Jeremiæ clam, dicens: Vivit Dominus, qui fecit nobis animam hanc, si occidero te, et si tradidero te in manus virorum istorum qui quærunt animam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 17, 'Et dixit Jeremias ad Sedeciam: Hæc dicit Dominus exercituum, Deus Israël: Si profectus exieris ad principes regis Babylonis, vivet anima tua, et civitas hæc non succendetur igni: et salvus eris tu, et domus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 18, 'Si autem non exieris ad principes regis Babylonis, tradetur civitas hæc in manus Chaldæorum, et succendent eam igni: et tu non effugies de manu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 19, 'Et dixit rex Sedecias ad Jeremiam: Sollicitus sum propter Judæos qui transfugerunt ad Chaldæos, ne forte tradar in manus eorum, et illudant mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 20, 'Respondit autem Jeremias: Non te tradent. Audi, quæso, vocem Domini, quam ego loquor ad te, et bene tibi erit, et vivet anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 21, 'Quod si nolueris egredi, iste est sermo quem ostendit mihi Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 22, 'ecce omnes mulieres quæ remanserunt in domo regis Juda educentur ad principes regis Babylonis, et ipsæ dicent: Seduxerunt te, et prævaluerunt adversum te, viri pacifici tui: demerserunt in cœno et in lubrico pedes tuos, et recesserunt a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 23, 'Et omnes uxores tuæ et filii tui educentur ad Chaldæos: et non effugies manus eorum, sed in manu regis Babylonis capieris, et civitatem hanc comburet igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 24, 'Dixit ergo Sedecias ad Jeremiam: Nullus sciat verba hæc, et non morieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 25, 'Si autem audierint principes quia locutus sum tecum, et venerint ad te, et dixerint tibi: Indica nobis quid locutus sis cum rege: ne celes nos, et non te interficiemus: et quid locutus est tecum rex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 26, 'dices ad eos: Prostravi ego preces meas coram rege, ne me reduci juberet in domum Jonathan, et ibi morerer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 27, 'Venerunt ergo omnes principes ad Jeremiam, et interrogaverunt eum, et locutus est eis juxta omnia verba quæ præceperat ei rex: et cessaverunt ab eo: nihil enim fuerat auditum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 38, 28, 'Mansit vero Jeremias in vestibulo carceris usque ad diem quo capta est Jerusalem: et factum est ut caperetur Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 1, 'Anno nono Sedeciæ regis Juda, mense decimo, venit Nabuchodonosor rex Babylonis, et omnis exercitus ejus, ad Jerusalem, et obsidebant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 2, 'Undecimo autem anno Sedeciæ, mense quarto, quinta mensis, aperta est civitas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 3, 'et ingressi sunt omnes principes regis Babylonis, et sederunt in porta media: Neregel, Sereser, Semegarnabu, Sarsachim, Rabsares, Neregel, Sereser, Rebmag, et omnes reliqui principes regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 4, 'Cumque vidisset eos Sedecias rex Juda, et omnes viri bellatores, fugerunt: et egressi sunt nocte de civitate per viam horti regis, et per portam quæ erat inter duos muros, et egressi sunt ad viam deserti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 5, 'Persecutus est autem eos exercitus Chaldæorum, et comprehenderunt Sedeciam in campo solitudinis Jerichontinæ, et captum adduxerunt ad Nabuchodonosor regem Babylonis, in Reblatha, quæ est in terra Emath: et locutus est ad eum judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 6, 'Et occidit rex Babylonis filios Sedeciæ in Reblatha, in oculis ejus: et omnes nobiles Juda occidit rex Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 7, 'Oculos quoque Sedeciæ eruit, et vinxit eum compedibus ut duceretur in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 8, 'Domum quoque regis et domum vulgi succenderunt Chaldæi igni, et murum Jerusalem subverterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 9, 'Et reliquias populi qui remanserant in civitate, et perfugas qui transfugerant ad eum, et superfluos vulgi qui remanserant, transtulit Nabuzardan, magister militum, in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 10, 'Et de plebe pauperum, qui nihil penitus habebant, dimisit Nabuzardan magister militum in terra Juda, et dedit eis vineas et cisternas in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 11, 'Præceperat autem Nabuchodonosor rex Babylonis de Jeremia Nabuzardan magistro militum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 12, 'Tolle illum, et pone super eum oculos tuos, nihilque ei mali facias: sed ut voluerit, sic facias ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 13, 'Misit ergo Nabuzardan princeps militiæ, et Nabusezban, et Rabsares, et Neregel, et Sereser, et Rebmag, et omnes optimates regis Babylonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 14, 'miserunt, et tulerunt Jeremiam de vestibulo carceris, et tradiderunt eum Godoliæ filio Ahicam filii Saphan, ut intraret in domum, et habitaret in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 15, 'Ad Jeremiam autem factus fuerat sermo Domini, cum clausus esset in vestibulo carceris, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 16, 'Vade, et dic Abdemelech \'thiopi, dicens: Hæc dicit Dominus exercituum, Deus Israël: Ecce ego inducam sermones meos super civitatem hanc in malum, et non in bonum, et erunt in conspectu tuo in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 17, 'Et liberabo te in die illa, ait Dominus, et non traderis in manus virorum quos tu formidas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 39, 18, 'sed eruens liberabo te, et gladio non cades, sed erit tibi anima tua in salutem, quia in me habuisti fiduciam, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 1, 'Sermo qui factus est ad Jeremiam a Domino, postquam dimissus est a Nabuzardan magistro militiæ de Rama, quando tulit eum vinctum catenis in medio omnium qui migrabant de Jerusalem et Juda, et ducebantur in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 2, 'Tollens ergo princeps militiæ Jeremiam, dixit ad eum: Dominus Deus tuus locutus est malum hoc super locum istum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 3, 'et adduxit, et fecit Dominus sicut locutus est, quia peccastis Domino, et non audistis vocem ejus: et factus est vobis sermo hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 4, 'Nunc ergo ecce solvi te hodie de catenis quæ sunt in manibus tuis: si placet tibi ut venias mecum in Babylonem, veni, et ponam oculos meos super te: si autem displicet tibi venire mecum in Babylonem, reside: ecce omnis terra in conspectu tuo est: quod elegeris, et quo placuerit tibi ut vadas, illuc perge:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 5, 'et mecum noli venire, sed habita apud Godoliam filium Ahicam filii Saphan, quem præposuit rex Babylonis civitatibus Juda: habita ergo cum eo in medio populi: vel quocumque placuerit tibi ut vadas, vade. Dedit quoque ei magister militiæ cibaria et munuscula, et dimisit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 6, 'Venit autem Jeremias ad Godoliam filium Ahicam in Masphath, et habitavit cum eo in medio populi qui relictus fuerat in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 7, 'Cumque audissent omnes principes exercitus, qui dispersi fuerant per regiones, ipsi et socii eorum, quod præfecisset rex Babylonis Godoliam filium Ahicam terræ, et quod commendasset ei viros, et mulieres, et parvulos, et de pauperibus terræ, qui non fuerant translati in Babylonem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 8, 'venerunt ad Godoliam in Masphath, et Ismahel filius Nathaniæ, et Johanan et Jonathan filii Caree, et Sareas filius Thanehumeth, et filii Ophi, qui erant de Netophathi, et Jezonias filius Maachathi, ipsi et viri eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 9, 'Et juravit eis Godolias filius Ahicam filii Saphan, et comitibus eorum, dicens: Nolite timere servire Chaldæis: habitate in terra, et servite regi Babylonis, et bene erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 10, 'Ecce ego habito in Masphath, ut respondeam præcepto Chaldæorum qui mittuntur ad nos: vos autem colligite vindemiam, et messem, et oleum, et condite in vasis vestris, et manete in urbibus vestris quas tenetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 11, 'Sed et omnes Judæi qui erant in Moab, et in filiis Ammon, et in Idumæa, et in universis regionibus, audito quod dedisset rex Babylonis reliquias in Judæa, et quod præposuisset super eos Godoliam filium Ahicam filii Saphan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 12, 'reversi sunt, inquam, omnes Judæi de universis locis ad quæ profugerant, et venerunt in terram Juda ad Godoliam in Masphath, et collegerunt vinum et messem multam nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 13, 'Johanan autem filius Caree, et omnes principes exercitus qui dispersi fuerant in regionibus, venerunt ad Godoliam in Masphath,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 14, 'et dixerunt ei: Scito quod Baalis, rex filiorum Ammon, misit Ismahel filium Nathaniæ percutere animam tuam. Et non credidit eis Godolias filius Ahicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 15, 'Johanan autem filius Caree dixit ad Godoliam seorsum in Masphath, loquens: Ibo, et percutiam Ismahel filium Nathaniæ, nullo sciente, ne interficiat animam tuam, et dissipentur omnes Judæi qui congregati sunt ad te, et peribunt reliquiæ Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 40, 16, 'Et ait Godolias filius Ahicam ad Johanan filium Caree: Noli facere verbum hoc: falsum enim tu loqueris de Ismahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 1, 'Et factum est in mense septimo, venit Ismahel filius Nathaniæ filii Elisama, de semine regali, et optimates regis, et decem viri cum eo, ad Godoliam filium Ahicam, in Masphath, et comederunt ibi panes simul in Masphath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 2, 'Surrexit autem Ismahel filius Nathaniæ, et decem viri qui cum eo erant, et percusserunt Godoliam filium Ahicam filii Saphan gladio, et interfecerunt eum quem præfecerat rex Babylonis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 3, 'Omnes quoque Judæos qui erant cum Godolia in Masphath, et Chaldæos qui reperti sunt ibi, et viros bellatores, percussit Ismahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 4, 'Secundo autem die postquam occiderat Godoliam, nullo adhuc sciente,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 5, 'venerunt viri de Sichem, et de Silo, et de Samaria, octoginta viri, rasi barba, et scissis vestibus, et squallentes: et munera et thus habebant in manu, ut offerrent in domo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 6, 'Egressus ergo Ismahel filius Nathaniæ in occursum eorum de Masphath, incedens et plorans ibat: cum autem occurrisset eis, dixit ad eos: Venite ad Godoliam filium Ahicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 7, 'Qui cum venissent ad medium civitatis, interfecit eos Ismahel filius Nathaniæ circa medium laci, ipse et viri qui erant cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 8, 'Decem autem viri reperti sunt inter eos, qui dixerunt ad Ismahel: Noli occidere nos, quia habemus thesauros in agro, frumenti, et hordei, et olei, et mellis: et cessavit, et non interfecit eos cum fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 9, 'Lacus autem in quem projecerat Ismahel omnia cadavera virorum quos percussit propter Godoliam, ipse est quem fecit rex Asa propter Baasa regem Israël: ipsum replevit Ismahel filius Nathaniæ occisis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 10, 'Et captivas duxit Ismahel omnes reliquias populi qui erant in Masphath, filias regis, et universum populum qui remanserat in Masphath, quos commendaverat Nabuzardan princeps militiæ, Godoliæ filio Ahicam: et cepit eos Ismahel filius Nathaniæ, et abiit ut transiret ad filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 11, 'Audivit autem Johanan filius Caree, et omnes principes bellatorum qui erant cum eo, omne malum quod fecerat Ismahel filius Nathaniæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 12, 'et assumptis universis viris, profecti sunt ut bellarent adversum Ismahel filium Nathaniæ: et invenerunt eum ad aquas multas quæ sunt in Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 13, 'Cumque vidisset omnis populus qui erat cum Ismahel Johanan filium Caree, et universos principes bellatorum qui erant cum eo, lætati sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 14, 'et reversus est omnis populus quem ceperat Ismahel, in Masphath, reversusque abiit ad Johanan filium Caree.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 15, 'Ismahel autem filius Nathaniæ fugit cum octo viris a facie Johanan, et abiit ad filios Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 16, 'Tulit ergo Johanan filius Caree, et omnes principes bellatorum qui erant cum eo, universas reliquias vulgi quas reduxerat ab Ismahel filio Nathaniæ de Masphath, postquam percussit Godoliam filium Ahicam: fortes viros ad prælium, et mulieres, et pueros, et eunuchos, quos reduxerat de Gabaon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 17, 'Et abierunt, et sederunt peregrinantes in Chamaam, quæ est juxta Bethlehem, ut pergerent, et introirent \'gyptum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 41, 18, 'a facie Chaldæorum: timebant enim eos, quia percusserat Ismahel filius Nathaniæ Godoliam filium Ahicam, quem præposuerat rex Babylonis in terra Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 1, 'Et accesserunt omnes principes bellatorum, et Johanan filius Caree, et Jezonias filius Osaiæ, et reliquum vulgus, a parvo usque ad magnum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 2, 'dixeruntque ad Jeremiam prophetam: Cadat oratio nostra in conspectu tuo, et ora pro nobis ad Dominum Deum tuum, pro universis reliquiis istis, quia derelicti sumus pauci de pluribus, sicut oculi tui nos intuentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 3, 'et annuntiet nobis Dominus Deus tuus viam per quam pergamus, et verbum quod faciamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 4, 'Dixit autem ad eos Jeremias propheta: Audivi. Ecce ego oro ad Dominum Deum vestrum secundum verba vestra: omne verbum quodcumque responderit mihi indicabo vobis, nec celabo vos quidquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 5, 'Et illi dixerunt ad Jeremiam: Sit Dominus inter nos testis veritatis et fidei, si non juxta omne verbum in quo miserit te Dominus Deus tuus ad nos, sic faciemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 6, 'sive bonum est, sive malum, voci Domini Dei nostri, ad quem mittimus te, obediemus, ut bene sit nobis cum audierimus vocem Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 7, 'Cum autem completi essent decem dies, factum est verbum Domini ad Jeremiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 8, 'vocavitque Johanan filium Caree, et omnes principes bellatorum qui erant cum eo, et universum populum, a minimo usque ad magnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 9, 'Et dixit ad eos: Hæc dicit Dominus Deus Israël, ad quem misistis me ut prosternerem preces vestras in conspectu ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 10, 'Si quiescentes manseritis in terra hac, ædificabo vos, et non destruam: plantabo, et non evellam: jam enim placatus sum super malo quod feci vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 11, 'Nolite timere a facie regis Babylonis, quem vos pavidi formidatis: nolite metuere eum, dicit Dominus, quia vobiscum sum ego ut salvos vos faciam, et eruam de manu ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 12, 'et dabo vobis misericordias, et miserebor vestri, et habitare vos faciam in terra vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 13, 'Si autem dixeritis vos: Non habitabimus in terra ista, nec audiemus vocem Domini Dei nostri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 14, 'dicentes: Nequaquam, sed ad terram \'gypti pergemus, ubi non videbimus bellum, et clangorem tubæ non audiemus, et famem non sustinebimus, et ibi habitabimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 15, 'propter hoc nunc audite verbum Domini, reliquiæ Juda: Hæc dicit Dominus exercituum, Deus Israël: Si posueritis faciem vestram ut ingrediamini \'gyptum, et intraveritis ut ibi habitetis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 16, 'gladius quem vos formidatis ibi comprehendet vos in terra \'gypti: et fames, pro qua estis solliciti, adhærebit vobis in \'gypto, et ibi moriemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 17, 'Omnesque viri qui posuerunt faciem suam ut ingrediantur \'gyptum, ut habitent ibi, morientur gladio, et fame, et peste: nullus de eis remanebit, nec effugiet a facie mali quod ego afferam super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 18, 'Quia hæc dicit Dominus exercituum, Deus Israël: Sicut conflatus est furor meus et indignatio mea super habitatores Jerusalem, sic conflabitur indignatio mea super vos cum ingressi fueritis \'gyptum: et eritis in jusjurandum, et in stuporem, et in maledictum, et in opprobrium, et nequaquam ultra videbitis locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 19, 'Verbum Domini super vos, reliquiæ Juda: Nolite intrare \'gyptum: scientes scietis, quia obtestatus sum vos hodie,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 20, 'quia decepistis animas vestras. Vos enim misistis me ad Dominum Deum nostrum, dicentes: Ora pro nobis ad Dominum Deum nostrum, et juxta omnia quæcumque dixerit tibi Dominus Deus noster, sic annuntia nobis, et faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 21, 'Et annuntiavi vobis hodie, et non audistis vocem Domini Dei vestri super universis pro quibus misit me ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 42, 22, 'Nunc ergo scientes scietis quia gladio, et fame, et peste moriemini in loco ad quem voluistis intrare ut habitaretis ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 1, 'Factum est autem, cum complesset Jeremias loquens ad populum universos sermones Domini Dei eorum, pro quibus miserat eum Dominus Deus eorum ad illos, omnia verba hæc,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 2, 'dixit Azarias filius Osaiæ, et Johanan filius Caree, et omnes viri superbi, dicentes ad Jeremiam: Mendacium tu loqueris: non misit te Dominus Deus noster, dicens: Ne ingrediamini \'gyptum ut habitetis illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 3, 'Sed Baruch filius Neriæ incitat te adversum nos, ut tradat nos in manus Chaldæorum, ut interficiat nos, et traduci faciat in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 4, 'Et non audivit Johanan filius Caree, et omnes principes bellatorum, et universus populus, vocem Domini, ut manerent in terra Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 5, 'Sed tollens Johanan filius Caree, et universi principes bellatorum, universos reliquiarum Juda, qui reversi fuerant de cunctis gentibus ad quas fuerant ante dispersi, ut habitarent in terra Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 6, 'viros, et mulieres, et parvulos, et filias regis, et omnem animam quam reliquerat Nabuzardan princeps militiæ cum Godolia filio Ahicam filii Saphan, et Jeremiam prophetam, et Baruch filium Neriæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 7, 'et ingressi sunt terram \'gypti, quia non obedierunt voci Domini, et venerunt usque ad Taphnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 8, 'Et factus est sermo Domini ad Jeremiam in Taphnis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 9, 'Sume lapides grandes in manu tua, et abscondes eos in crypta quæ est sub muro latericio in porta domus Pharaonis in Taphnis, cernentibus viris Judæis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 10, 'et dices ad eos: Hæc dicit Dominus exercituum, Deus Israël: Ecce ego mittam et assumam Nabuchodonosor regem Babylonis, servum meum: et ponam thronum ejus super lapides istos quos abscondi, et statuet solium suum super eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 11, 'veniensque percutiet terram \'gypti, quos in mortem, in mortem, et quos in captivitatem, in captivitatem, et quos in gladium, in gladium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 12, 'et succendet ignem in delubris deorum \'gypti, et comburet ea, et captivos ducet illos, et amicietur terra \'gypti sicut amicitur pastor pallio suo, et egredietur inde in pace:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 43, 13, 'et conteret statuas domus solis quæ sunt in terra \'gypti, et delubra deorum \'gypti comburet igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 1, 'Verbum quod factum est per Jeremiam ad omnes Judæos qui habitabant in terra \'gypti, habitantes in Magdalo, et in Taphnis, et in Memphis, et in terra Phatures, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 2, 'Hæc dicit Dominus exercituum, Deus Israël: Vos vidistis omne malum istud quod adduxi super Jerusalem, et super omnes urbes Juda: et ecce desertæ sunt hodie, et non est in eis habitator,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 3, 'propter malitiam quam fecerunt ut me ad iracundiam provocarent, et irent ut sacrificarent, et colerent deos alienos quos nesciebant, et illi, et vos, et patres vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 4, 'Et misi ad vos omnes servos meos prophetas, de nocte consurgens, mittensque et dicens: Nolite facere verbum abominationis hujuscemodi, quam odivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 5, 'Et non audierunt, nec inclinaverunt aurem suam, ut converterentur a malis suis, et non sacrificarent diis alienis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 6, 'Et conflata est indignatio mea et furor meus, et succensa est in civitatibus Juda, et in plateis Jerusalem: et versæ sunt in solitudinem et vastitatem secundum diem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 7, 'Et nunc hæc dicit Dominus exercituum, Deus Israël: Quare vos facitis malum grande hoc contra animas vestras, ut intereat ex vobis vir et mulier, parvulus et lactens, de medio Judæ, nec relinquatur vobis quidquam residuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 8, 'provocantes me in operibus manuum vestrarum, sacrificando diis alienis in terra \'gypti, in quam ingressi estis ut habitetis ibi: et dispereatis, et sitis in maledictionem et in opprobrium cunctis gentibus terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 9, 'Numquid obliti estis mala patrum vestrorum, et mala regum Juda, et mala uxorum ejus, et mala vestra, et mala uxorum vestrarum, quæ fecerunt in terra Juda, et in regionibus Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 10, 'Non sunt mundati usque ad diem hanc: et non timuerunt, et non ambulaverunt in lege Domini, et in præceptis meis quæ dedi coram vobis et coram patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 11, 'Ideo hæc dicit Dominus exercituum, Deus Israël: Ecce ego ponam faciem meam in vobis in malum: et disperdam omnem Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 12, 'Et assumam reliquias Judæ, qui posuerunt facies suas ut ingrederentur terram \'gypti, et habitarent ibi, et consumentur omnes in terra \'gypti: cadent in gladio, et in fame, et consumentur a minimo usque ad maximum: in gladio et in fame morientur, et erunt in jusjurandum, et in miraculum, et in maledictionem, et in opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 13, 'Et visitabo super habitatores terræ \'gypti sicut visitavi super Jerusalem, in gladio, et fame, et peste:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 14, 'et non erit qui effugiat, et sit residuus de reliquiis Judæorum qui vadunt ut peregrinentur in terra \'gypti, et revertantur in terram Juda, ad quam ipsi elevant animas suas ut revertantur, et habitent ibi: non revertentur, nisi qui fugerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 15, 'Responderunt autem Jeremiæ omnes viri scientes quod sacrificarent uxores eorum diis alienis, et universæ mulieres quarum stabat multitudo grandis, et omnis populus habitantium in terra \'gypti in Phatures, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 16, 'Sermonem quem locutus es ad nos in nomine Domini, non audiemus ex te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 17, 'sed facientes faciemus omne verbum quod egredietur de ore nostro, ut sacrificemus reginæ cæli, et libemus ei libamina, sicut fecimus nos et patres nostri, reges nostri et principes nostri, in urbibus Juda, et in plateis Jerusalem: et saturati sumus panibus, et bene nobis erat, malumque non vidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 18, 'Ex eo autem tempore quo cessavimus sacrificare reginæ cæli, et libare ei libamina, indigemus omnibus, et gladio et fame consumpti sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 19, 'Quod si nos sacrificamus reginæ cæli, et libamus ei libamina, numquid sine viris nostris fecimus ei placentas ad colendum eam, et libandum ei libamina?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 20, 'Et dixit Jeremias ad omnem populum, adversum viros, et adversum mulieres, et adversum universam plebem, qui responderant ei verbum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 21, 'Numquid non sacrificium quod sacrificastis in civitatibus Juda, et in plateis Jerusalem, vos et patres vestri, reges vestri, et principes vestri, et populus terræ, horum recordatus est Dominus, et ascendit super cor ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 22, 'Et non poterat Dominus ultra portare propter malitiam studiorum vestrorum, et propter abominationes quas fecistis: et facta est terra vestra in desolationem, et in stuporem, et in maledictum, eo quod non sit habitator, sicut est dies hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 23, 'Propterea quod sacrificaveritis idolis, et peccaveritis Domino, et non audieritis vocem Domini, et in lege, et in præceptis, et in testimoniis ejus non ambulaveritis, idcirco evenerunt vobis mala hæc, sicut est dies hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 24, 'Dixit autem Jeremias ad omnem populum, et ad universas mulieres: Audite verbum Domini, omnis Juda qui estis in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 25, 'Hæc inquit Dominus exercituum, Deus Israël, dicens: Vos et uxores vestræ locuti estis ore vestro, et manibus vestris implestis, dicentes: Faciamus vota nostra quæ vovimus, ut sacrificemus reginæ cæli, et libemus ei libamina. Implestis vota vestra, et opere perpetrastis ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 26, 'Ideo audite verbum Domini, omnis Juda qui habitatis in terra \'gypti: Ecce ego juravi in nomine meo magno, ait Dominus, quia nequaquam ultra vocabitur nomen meum ex ore omnis viri Judæi, dicentis: Vivit Dominus Deus, in omni terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 27, 'Ecce ego vigilabo super eos in malum, et non in bonum: et consumentur omnes viri Juda qui sunt in terra \'gypti gladio et fame, donec penitus consumantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 28, 'Et qui fugerint gladium, revertentur de terra \'gypti in terram Juda viri pauci: et scient omnes reliquiæ Juda, ingredientium terram \'gypti ut habitent ibi, cujus sermo compleatur, meus an illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 29, 'Et hoc vobis signum, ait Dominus, quod visitem ego super vos in loco isto, ut sciatis quia vere complebuntur sermones mei contra vos in malum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 44, 30, 'hæc dicit Dominus: Ecce ego tradam Pharaonem Ephree regem \'gypti in manu inimicorum ejus, et in manu quærentium animam illius, sicut tradidi Sedeciam regem Juda in manu Nabuchodonosor regis Babylonis inimici sui, et quærentis animam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 1, 'Verbum quod locutus est Jeremias propheta ad Baruch filium Neriæ, cum scripsisset verba hæc in libro ex ore Jeremiæ, anno quarto Joakim filii Josiæ regis Juda, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 2, 'Hæc dicit Dominus Deus Israël ad te, Baruch:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 3, 'Dixisti: Væ misero mihi! quoniam addidit Dominus dolorem dolori meo: laboravi in gemitu meo, et requiem non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 4, 'Hæc dicit Dominus: Sic dices ad eum: Ecce quos ædificavi, ego destruo, et quos plantavi, ego evello, et universam terram hanc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 45, 5, 'et tu quæris tibi grandia? noli quærere, quia ecce ego adducam malum super omnem carnem, ait Dominus, et dabo tibi animam tuam in salutem in omnibus locis ad quæcumque perrexeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 1, 'Quod factum est verbum Domini ad Jeremiam prophetam contra gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 2, 'Ad \'gyptum, adversum exercitum Pharaonis Nechao regis \'gypti, qui erat juxta fluvium Euphraten in Charcamis, quem percussit Nabuchodonosor rex Babylonis, in quarto anno Joakim filii Josiæ regis Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 3, 'Præparate scutum et clypeum, et procedite ad bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 4, 'Jungite equos, et ascendite, equites: state in galeis, polite lanceas, induite vos loricis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 5, 'Quid igitur? vidi ipsos pavidos, et terga vertentes, fortes eorum cæsos: fugerunt conciti, nec respexerunt: terror undique, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 6, 'Non fugiat velox, nec salvari se putet fortis: ad aquilonem juxta flumen Euphraten victi sunt, et ruerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 7, 'Quis est iste, qui quasi flumen ascendit, et veluti fluviorum intumescunt gurgites ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 8, '\'gyptus fluminis instar ascendit, et velut flumina movebuntur fluctus ejus, et dicet: Ascendens operiam terram: perdam civitatem, et habitatores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 9, 'Ascendite equos, et exsultate in curribus, et procedant fortes, \'thiopia et Libyes tenentes scutum, et Lydii arripientes et jacientes sagittas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 10, 'Dies autem ille Domini Dei exercituum dies ultionis, ut sumat vindictam de inimicis suis: devorabit gladius, et saturabitur, et inebriabitur sanguine eorum: victima enim Domini Dei exercituum in terra aquilonis juxta flumen Euphraten.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 11, 'Ascende in Galaad, et tolle resinam, virgo filia \'gypti: frustra multiplicas medicamina: sanitas non erit tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 12, 'Audierunt gentes ignominiam tuam, et ululatus tuus replevit terram: quia fortis impegit in fortem, et ambo pariter conciderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 13, 'Verbum quod locutus est Dominus ad Jeremiam prophetam, super eo quod venturus esset Nabuchodonosor rex Babylonis, et percussurus terram \'gypti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 14, 'Annuntiate \'gypto, et auditum facite in Magdalo, et resonet in Memphis, et in Taphnis: dicite: Sta, et præpara te, quia devorabit gladius ea quæ per circuitum tuum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 15, 'Quare computruit fortis tuus? non stetit, quoniam Dominus subvertit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 16, 'Multiplicavit ruentes, ceciditque vir ad proximum suum, et dicent: Surge, et revertamur ad populum nostrum, et ad terram nativitatis nostræ, a facie gladii columbæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 17, 'Vocate nomen Pharaonis regis \'gypti: tumultum adduxit tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 18, 'Vivo ego, inquit Rex (Dominus exercituum nomen ejus), quoniam sicut Thabor in montibus, et sicut Carmelus in mari, veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 19, 'Vasa transmigrationis fac tibi, habitatrix filia \'gypti: quia Memphis in solitudinem erit, et deseretur, et inhabitabilis erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 20, 'Vitula elegans atque formosa \'gyptus, stimulator ab aquilone veniet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 21, 'Mercenarii quoque ejus, qui versabantur in medio ejus quasi vituli saginati, versi sunt, et fugerunt simul, nec stare potuerunt: quia dies interfectionis eorum venit super eos, tempus visitationis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 22, 'Vox ejus quasi æris sonabit: quoniam cum exercitu properabunt, et cum securibus venient ei quasi cædentes ligna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 23, 'Succiderunt saltum ejus, ait Dominus, qui supputari non potest: multiplicati sunt super locustas, et non est eis numerus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 24, 'Confusa est filia \'gypti, et tradita in manu populi aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 25, 'Dixit Dominus exercituum, Deus Israël: Ecce ego visitabo super tumultum Alexandriæ, et super Pharaonem, et super \'gyptum, et super deos ejus, et super reges ejus, et super Pharaonem, et super eos qui confidunt in eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 26, 'et dabo eos in manu quærentium animam eorum, et in manu Nabuchodonosor regis Babylonis, et in manu servorum ejus: et post hæc habitabitur sicut diebus pristinis, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 27, 'Et tu ne timeas, serve meus Jacob, et ne paveas, Israël: quia ecce ego salvum te faciam de longinquo, et semen tuum de terra captivitatis tuæ: et revertetur Jacob, et requiescet, et prosperabitur, et non erit qui exterreat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 46, 28, 'Et tu noli timere, serve meus Jacob, ait Dominus, quia tecum ego sum: quia ego consumam cunctas gentes ad quas ejeci te, te vero non consumam: sed castigabo te in judicio, nec quasi innocenti parcam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 1, 'Quod factum est verbum Domini ad Jeremiam prophetam contra Palæstinos, antequam percuteret Pharao Gazam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 2, 'Hæc dicit Dominus: Ecce aquæ ascendunt ab aquilone, et erunt quasi torrens inundans, et operient terram et plenitudinem ejus, urbem et habitatores ejus. Clamabunt homines, et ululabunt omnes habitatores terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 3, 'a strepitu pompæ armorum, et bellatorum ejus, a commotione quadrigarum ejus, et multitudine rotarum illius. Non respexerunt patres filios manibus dissolutis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 4, 'pro adventu diei in quo vastabuntur omnes Philisthiim, et dissipabitur Tyrus et Sidon cum omnibus reliquis auxiliis suis: depopulatus est enim Dominus Palæstinos, reliquias insulæ Cappadociæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 5, 'Venit calvitium super Gazam; conticuit Ascalon, et reliquiæ vallis earum: usquequo concideris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 6, 'O mucro Domini, usquequo non quiesces? ingredere in vaginam tuam, refrigerare, et sile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 47, 7, 'Quomodo quiescet, cum Dominus præceperit ei adversus Ascalonem, et adversus maritimas ejus regiones, ibique condixerit illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 1, 'Ad Moab. Hæc dicit Dominus exercituum, Deus Israël: Væ super Nabo, quoniam vastata est, et confusa! capta est Cariathaim, confusa est fortis, et tremuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 2, 'Non est ultra exsultatio in Moab contra Hesebon: cogitaverunt malum: Venite, et disperdamus eam de gente. Ergo silens conticesces, sequeturque te gladius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 3, 'Vox clamoris de Oronaim, vastitas et contritio magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 4, 'Contrita est Moab: annuntiate clamorem parvulis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 5, 'Per ascensum enim Luith plorans ascendet in fletu, quoniam in descensu Oronaim hostes ululatum contritionis audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 6, 'Fugite, salvate animas vestras, et eritis quasi myricæ in deserto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 7, 'pro eo enim quod habuisti fiduciam in munitionibus tuis et in thesauris tuis, tu quoque capieris: et ibit Chamos in transmigrationem, sacerdotes ejus et principes ejus simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 8, 'Et veniet prædo ad omnem urbem, et urbs nulla salvabitur: et peribunt valles, et dissipabuntur campestria, quoniam dixit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 9, 'Date florem Moab, quia florens egredietur: et civitates ejus desertæ erunt, et inhabitabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 10, 'Maledictus qui facit opus Domini fraudulenter, et maledictus qui prohibet gladium suum a sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 11, 'Fertilis fuit Moab ab adolescentia sua, et requievit in fæcibus suis: nec transfusus est de vase in vas, et in transmigrationem non abiit: idcirco permansit gustus ejus in eo, et odor ejus non est immutatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 12, 'Propterea ecce dies veniunt, dicit Dominus, et mittam ei ordinatores et stratores laguncularum: et sternent eum, et vasa ejus exhaurient, et lagunculas eorum collident.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 13, 'Et confundetur Moab a Chamos sicut confusa est domus Israël a Bethel, in qua habebat fiduciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 14, 'Quomodo dicitis: Fortes sumus, et viri robusti ad præliandum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 15, 'Vastata est Moab, et civitates illius succiderunt, et electi juvenes ejus descenderunt in occisionem, ait Rex: Dominus exercituum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 16, 'Prope est interitus Moab ut veniat, et malum ejus velociter accurret nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 17, 'Consolamini eum, omnes qui estis in circuitu ejus: et universi qui scitis nomen ejus, dicite: Quomodo confracta est virga fortis, baculus gloriosus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 18, 'Descende de gloria, et sede in siti, habitatio filiæ Dibon, quoniam vastator Moab ascendit ad te: dissipavit munitiones tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 19, 'In via sta, et prospice, habitatio Aroër: interroga fugientem, et ei qui evasit dic: Quid accidit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 20, 'Confusus est Moab, quoniam victus est. Ululate, et clamate: annuntiate in Arnon, quoniam vastata est Moab,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 21, 'et judicium venit ad terram campestrem, super Helon, et super Jasa, et super Mephaath,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 22, 'et super Dibon, et super Nabo, et super domum Deblathaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 23, 'et super Cariathaim, et super Bethgamul, et super Bethmaon,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 24, 'et super Carioth, et super Bosra, et super omnes civitates terræ Moab, quæ longe et quæ prope sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 25, 'Abscissum est cornu Moab, et brachium ejus contritum est, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 26, 'Inebriate eum, quoniam contra Dominum erectus est: et allidet manum Moab in vomitu suo, et erit in derisum etiam ipse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 27, 'Fuit enim in derisum tibi Israël: quasi inter fures reperisses eum: propter verba ergo tua quæ adversum illum locutus es, captivus duceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 28, 'Relinquite civitates, et habitate in petra, habitatores Moab: et estote quasi columba nidificans in summo ore foraminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 29, 'Audivimus superbiam Moab: superbus est valde: sublimitatem ejus, et arrogantiam, et superbiam, et altitudinem cordis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 30, 'Ego scio, ait Dominus, jactantiam ejus, et quod non sit juxta eam virtus ejus, nec juxta quod poterat conata sit facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 31, 'Ideo super Moab ejulabo, et ad Moab universam clamabo, ad viros muri fictilis lamentantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 32, 'de planctu Jazer plorabo tibi, vinea Sabama. Propagines tuæ transierunt mare; usque ad mare Jazer pervenerunt: super messem tuam et vindemiam tuam prædo irruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 33, 'Ablata est lætitia et exsultatio de Carmelo et de terra Moab, et vinum de torcularibus sustuli: nequaquam calcator uvæ solitum celeuma cantabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 34, 'De clamore Hesebon usque Eleale et Jasa, dederunt vocem suam; a Segor usque ad Oronaim, vitula conternante: aquæ quoque Nemrim pessimæ erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 35, 'Et auferam de Moab, ait Dominus, offerentem in excelsis, et sacrificantem diis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 36, 'Propterea cor meum ad Moab quasi tibiæ resonabit, et cor meum ad viros muri fictilis dabit sonitum tibiarum: quia plus fecit quam potuit, idcirco perierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 37, 'Omne enim caput calvitium, et omnis barba rasa erit: in cunctis manibus colligatio, et super omne dorsum cilicium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 38, 'super omnia tecta Moab, et in plateis ejus, omnis planctus: quoniam contrivi Moab sicut vas inutile, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 39, 'Quomodo victa est, et ululaverunt? quomodo dejecit cervicem Moab, et confusus est? eritque Moab in derisum, et in exemplum omnibus in circuitu suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 40, 'Hæc dicit Dominus: Ecce quasi aquila volabit, et extendet alas suas ad Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 41, 'Capta est Carioth, et munitiones comprehensæ sunt: et erit cor fortium Moab in die illa sicut cor mulieris parturientis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 42, 'et cessabit Moab esse populus, quoniam contra Dominum gloriatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 43, 'Pavor, et fovea, et laqueus super te, o habitator Moab, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 44, 'Qui fugerit a facie pavoris cadet in foveam, et qui conscenderit de fovea capietur laqueo: adducam enim super Moab annum visitationis eorum, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 45, 'In umbra Hesebon steterunt de laqueo fugientes, quia ignis egressus est de Hesebon, et flamma de medio Seon: et devorabit partem Moab, et verticem filiorum tumultus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 46, 'Væ tibi, Moab: periisti, popule Chamos, quia comprehensi sunt filii tui et filiæ tuæ in captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 48, 47, 'Et convertam captivitatem Moab in novissimis diebus, ait Dominus. Hucusque judicia Moab.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 1, 'Ad filios Ammon. Hæc dicit Dominus: Numquid non filii sunt Israël, aut hæres non est ei? cur igitur hæreditate possedit Melchom Gad, et populus ejus in urbibus ejus habitavit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 2, 'Ideo ecce dies veniunt, dicit Dominus, et auditum faciam super Rabbath filiorum Ammon fremitum prælii, et erit in tumultum dissipata, filiæque ejus igni succendentur, et possidebit Israël possessores suos, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 3, 'Ulula, Hesebon, quoniam vastata est Hai; clamate, filiæ Rabbath: accingite vos ciliciis, plangite et circuite per sepes, quoniam Melchom in transmigrationem ducetur, sacerdotes ejus et principes ejus simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 4, 'Quid gloriaris in vallibus? defluxit vallis tua, filia delicata, quæ confidebas in thesauris tuis, et dicebas: Quis veniet ad me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 5, 'Ecce ego inducam super te terrorem, ait Dominus Deus exercituum, ab omnibus qui sunt in circuitu tuo: et dispergemini singuli a conspectu vestro, nec erit qui congreget fugientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 6, 'Et post hæc reverti faciam captivos filiorum Ammon, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 7, 'Ad Idumæam. Hæc dicit Dominus exercituum: Numquid non ultra est sapientia in Theman? periit consilium a filiis; inutilis facta est sapientia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 8, 'Fugite, et terga vertite; descendite in voraginem, habitatores Dedan: quoniam perditionem Esau adduxi super eum, tempus visitationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 9, 'Si vindemiatores venissent super te, non reliquissent racemum: si fures in nocte rapuissent quod sufficeret sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 10, 'Ego vero discooperui Esau: revelavi abscondita ejus, et celari non poterit: vastatum est semen ejus, et fratres ejus, et vicini ejus, et non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 11, 'Relinque pupillos tuos: ego faciam eos vivere: et viduæ tuæ in me sperabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 12, 'Quia hæc dicit Dominus: Ecce quibus non erat judicium ut biberent calicem, bibentes bibent: et tu, quasi innocens relinqueris? non eris innocens, sed bibens bibes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 13, 'Quia per memetipsum juravi, dicit Dominus, quod in solitudinem, et in opprobrium, et in desertum, et in maledictionem erit Bosra, et omnes civitates ejus erunt in solitudines sempiternas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 14, 'Auditum audivi a Domino, et legatus ad gentes missus est: Congregamini, et venite contra eam, et consurgamus in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 15, 'Ecce enim parvulum dedi te in gentibus, contemptibilem inter homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 16, 'Arrogantia tua decepit te, et superbia cordis tui, qui habitas in cavernis petræ, et apprehendere niteris altitudinem collis: cum exaltaveris quasi aquila nidum tuum, inde detraham te, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 17, 'Et erit Idumæa deserta: omnis qui transibit per eam stupebit, et sibilabit super omnes plagas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 18, 'Sicut subversa est Sodoma et Gomorrha, et vicinæ ejus, ait Dominus: non habitabit ibi vir, et non incolet eam filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 19, 'Ecce quasi leo ascendet de superbia Jordanis ad pulchritudinem robustam, quia subito currere faciam eum ad illam. Et quis erit electus, quem præponam ei? quis enim similis mei? et quis sustinebit me? et quis est iste pastor, qui resistat vultui meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 20, 'Propterea audite consilium Domini quod iniit de Edom, et cogitationes ejus quas cogitavit de habitatoribus Theman: si non dejecerint eos parvuli gregis, nisi dissipaverint cum eis habitaculum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 21, 'A voce ruinæ eorum commota est terra; clamor in mari Rubro auditus est vocis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 22, 'Ecce quasi aquila ascendet, et avolabit, et expandet alas suas super Bosran: et erit cor fortium Idumææ in die illa quasi cor mulieris parturientis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 23, 'Ad Damascum. Confusa est Emath et Arphad, quia auditum pessimum audierunt: turbati sunt in mari; præ sollicitudine quiescere non potuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 24, 'Dissoluta est Damascus, versa est in fugam: tremor apprehendit eam, angustia et dolores tenuerunt eam quasi parturientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 25, 'Quomodo dereliquerunt civitatem laudabilem, urbem lætitiæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 26, 'Ideo cadent juvenes ejus in plateis ejus, et omnes viri prælii conticescent in die illa, ait Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 27, 'Et succendam ignem in muro Damasci, et devorabit mœnia Benadad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 28, 'Ad Cedar, et ad regna Asor, quæ percussit Nabuchodonosor rex Babylonis. Hæc dicit Dominus: Surgite, et ascendite ad Cedar, et vastate filios orientis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 29, 'Tabernacula eorum, et greges eorum capient: pelles eorum, et omnia vasa eorum, et camelos eorum tollent sibi, et vocabunt super eos formidinem in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 30, 'Fugite, abite vehementer, in voraginibus sedete, qui habitatis Asor, ait Dominus: iniit enim contra vos Nabuchodonosor rex Babylonis consilium, et cogitavit adversum vos cogitationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 31, 'Consurgite, et ascendite ad gentem quietam, et habitantem confidenter, ait Dominus: non ostia, nec vectes eis: soli habitant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 32, 'Et erunt cameli eorum in direptionem, et multitudo jumentorum in prædam: et dispergam eos in omnem ventum, qui sunt attonsi in comam, et ex omni confinio eorum adducam interitum super eos, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 33, 'Et erit Asor in habitaculum draconum, deserta usque in æternum: non manebit ibi vir, nec incolet eam filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 34, 'Quod facum est verbum Domini ad Jeremiam prophetam adversus \'lam, in principio regni Sedeciæ regis Juda, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 35, 'Hæc dicit Dominus exercituum: Ecce ego confringam arcum \'lam, et summam fortitudinem eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 36, 'et inducam super \'lam quatuor ventos a quatuor plagis cæli, et ventilabo eos in omnes ventos istos, et non erit gens ad quam non perveniant profugi \'lam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 37, 'Et pavere faciam \'lam coram inimicis suis, et in conspectu quærentium animam eorum: et adducam super eos malum, iram furoris mei, dicit Dominus, et mittam post eos gladium donec consumam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 38, 'Et ponam solium meum in \'lam, et perdam inde reges et principes, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 49, 39, 'In novissimis autem diebus reverti faciam captivos \'lam, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 1, 'Verbum quod locutus est Dominus de Babylone et de terra Chaldæorum, in manu Jeremiæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 2, 'Annuntiate in gentibus, et auditum facite: levate signum, prædicate, et nolite celare: dicite: Capta est Babylon, confusus est Bel, victus est Merodach, confusa sunt sculptilia ejus, superata sunt idola eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 3, 'Quoniam ascendit contra eam gens ab aquilone, quæ ponet terram ejus in solitudinem, et non erit qui habitet in ea ab homine usque ad pecus: et moti sunt, et abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 4, 'In diebus illis, et in tempore illo, ait Dominus, venient filii Israël ipsi et filii Juda simul: ambulantes et flentes properabunt, et Dominum Deum suum quærent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 5, 'in Sion interrogabunt viam, huc facies eorum: venient, et apponentur ad Dominum fœdere sempiterno, quod nulla oblivione delebitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 6, 'Grex perditus factus est populus meus: pastores eorum seduxerunt eos, feceruntque vagari in montibus: de monte in collem transierunt; obliti sunt cubilis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 7, 'Omnes qui invenerunt comederunt eos, et hostes eorum dixerunt: Non peccavimus: pro eo quod peccaverunt Domino decori justitiæ, et exspectationi patrum eorum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 8, 'Recedite de medio Babylonis, et de terra Chaldæorum egredimini, et estote quasi hædi ante gregem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 9, 'Quoniam ecce ego suscito, et adducam in Babylonem congregationem gentium magnarum de terra aquilonis, et præparabuntur adversus eam, et inde capietur: sagitta ejus quasi viri fortis interfectoris: non revertetur vacua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 10, 'Et erit Chaldæa in prædam: omnes vastantes eam replebuntur, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 11, 'Quoniam exsultatis, et magna loquimini, diripientes hæreditatem meam: quoniam effusi estis sicut vituli super herbam, et mugistis sicut tauri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 12, 'confusa est mater vestra nimis, et adæquata pulveri, quæ genuit vos: ecce novissima erit in gentibus, deserta, invia, et arens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 13, 'Ab ira Domini non habitabitur, sed redigetur tota in solitudinem: omnis qui transibit per Babylonem stupebit, et sibilabit super universis plagis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 14, 'Præparamini contra Babylonem per circuitum, omnes qui tenditis arcum: debellate eam, non parcatis jaculis, quia Domino peccavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 15, 'Clamate adversus eam, ubique dedit manum: ceciderunt fundamenta ejus, destructi sunt muri ejus, quoniam ultio Domini est: ultionem accipite de ea: sicut fecit, facite ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 16, 'Disperdite satorem de Babylone, et tenentem falcem in tempore messis: a facie gladii columbæ unusquisque ad populum suum convertetur, et singuli ad terram suam fugient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 17, 'Grex dispersus Israël: leones ejecerunt eum. Primus comedit eum rex Assur: iste novissimus exossavit eum Nabuchodonosor rex Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 18, 'Propterea hæc dicit Dominus exercituum, Deus Israël: Ecce ego visitabo regem Babylonis et terram ejus, sicut visitavi regem Assur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 19, 'et reducam Israël ad habitaculum suum: et pascetur Carmelum et Basan, et in monte Ephraim et Galaad saturabitur anima ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 20, 'In diebus illis, et in tempore illo, ait Dominus, quæretur iniquitas Israël, et non erit, et peccatum Juda, et non invenietur: quoniam propitius ero eis quos reliquero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 21, 'Super terram dominantium ascende, et super habitatores ejus visita: dissipa, et interfice quæ post eos sunt, ait Dominus, et fac juxta omnia quæ præcepi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 22, 'Vox belli in terra, et contritio magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 23, 'Quomodo confractus est et contritus malleus universæ terræ? quomodo versa est in desertum Babylon in gentibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 24, 'Illaqueavi te, et capta es, Babylon, et nesciebas: inventa es et apprehensa, quoniam Dominum provocasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 25, 'Aperuit Dominus thesaurum suum, et protulit vasa iræ suæ, quoniam opus est Domino Deo exercituum, in terra Chaldæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 26, 'Venite ad eam ab extremis finibus; aperite ut exeant qui conculcent eam: tollite de via lapides, et redigite in acervos: et interficite eam, nec sit quidquam reliquum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 27, 'Dissipate universos fortes ejus: descendant in occisionem: væ eis, quia venit dies eorum, tempus visitationis eorum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 28, 'Vox fugientium, et eorum qui evaserunt de terra Babylonis, ut annuntient in Sion ultionem Domini Dei nostri, ultionem templi ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 29, 'Annuntiate in Babylonem plurimis, omnibus qui tendunt arcum: consistite adversus eam per gyrum, et nullus evadat: reddite ei secundum opus suum: juxta omnia quæ fecit, facite illi, quia contra Dominum erecta est, adversum Sanctum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 30, 'Idcirco cadent juvenes ejus in plateis ejus, et omnes viri bellatores ejus conticescent in die illa, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 31, 'Ecce ego ad te, superbe! dicit Dominus Deus exercituum: quia venit dies tuus, tempus visitationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 32, 'Et cadet superbus, et corruet, et non erit qui suscitet eum: et succendam ignem in urbibus ejus, et devorabit omnia in circuitu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 33, 'Hæc dicit Dominus exercituum: Calumniam sustinent filii Israël, et filii Juda simul: omnes qui ceperunt eos, tenent: nolunt dimittere eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 34, 'Redemptor eorum fortis, Dominus exercituum nomen ejus: judicio defendet causam eorum, ut exterreat terram, et commoveat habitatores Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 35, 'Gladius ad Chaldæos, ait Dominus, et ad habitatores Babylonis, et ad principes, et ad sapientes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 36, 'Gladius ad divinos ejus, qui stulti erunt: gladius ad fortes illius, qui timebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 37, 'Gladius ad equos ejus, et ad currus ejus, et ad omne vulgus quod est in medio ejus: et erunt quasi mulieres: gladius ad thesauros ejus, qui diripientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 38, 'Siccitas super aquas ejus erit, et arescent, quia terra sculptilium est, et in portentis gloriantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 39, 'Propterea habitabunt dracones cum faunis ficariis, et habitabunt in ea struthiones: et non inhabitabitur ultra usque in sempiternum, nec exstruetur usque ad generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 40, 'Sicut subvertit Dominus Sodomam et Gomorrham, et vicinas ejus, ait Dominus, non habitabit ibi vir, et non incolet eam filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 41, 'Ecce populus venit ab aquilone, et gens magna, et reges multi consurgent a finibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 42, 'Arcum et scutum apprehendent: crudeles sunt, et immisericordes: vox eorum quasi mare sonabit, et super equos ascendent, sicut vir paratus ad prælium contra te, filia Babylon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 43, 'Audivit rex Babylonis famam eorum, et dissolutæ sunt manus ejus: angustia apprehendit eum, dolor quasi parturientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 44, 'Ecce quasi leo ascendet, de superbia Jordanis ad pulchritudinem robustam, quia subito currere faciam eum ad illam. Et quis erit electus, quem præponam ei? quis est enim similis mei? et quis sustinebit me? et quis est iste pastor, qui resistat vultui meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 45, 'Propterea audite consilium Domini quod mente concepit adversum Babylonem, et cogitationes ejus quas cogitavit super terram Chaldæorum: nisi detraxerint eos parvuli gregum, nisi dissipatum fuerit cum ipsis habitaculum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 50, 46, 'A voce captivitatis Babylonis commota est terra, et clamor inter gentes auditus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 1, 'Hæc dicit Dominus: Ecce ego suscitabo super Babylonem et super habitatores ejus, qui cor suum levaverunt contra me, quasi ventum pestilentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 2, 'et mittam in Babylonem ventilatores, et ventilabunt eam et demolientur terram ejus, quoniam venerunt super eam undique in die afflictionis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 3, 'Non tendat qui tendit arcum suum, et non ascendat loricatus: nolite parcere juvenibus ejus; interficite omnem militiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 4, 'Et cadent interfecti in terra Chaldæorum, et vulnerati in regionibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 5, 'Quoniam non fuit viduatus Israël et Juda a Deo suo, Domino exercituum, terra autem eorum repleta est delicto a Sancto Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 6, 'Fugite de medio Babylonis, et salvet unusquisque animam suam: nolite tacere super iniquitatem ejus, quoniam tempus ultionis est a Domino: vicissitudinem ipse retribuet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 7, 'Calix aureus Babylon in manu Domini, inebrians omnem terram: de vino ejus biberunt gentes, et ideo commotæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 8, 'Subito cecidit Babylon, et contrita est. Ululate super eam: tollite resinam ad dolorem ejus, si forte sanetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 9, 'Curavimus Babylonem, et non est sanata: derelinquamus eam, et eamus unusquisque in terram suam: quoniam pervenit usque ad cælos judicium ejus, et elevatum est usque ad nubes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 10, 'Protulit Dominus justitias nostras: venite, et narremus in Sion opus Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 11, 'Acuite sagittas, implete pharetras: suscitavit Dominus spiritum regum Medorum: et contra Babylonem mens ejus est ut perdat eam, quoniam ultio Domini est, ultio templi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 12, 'Super muros Babylonis levate signum, augete custodiam, levate custodes, præparate insidias: quia cogitavit Dominus, et fecit quæcumque locutus est contra habitatores Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 13, 'Quæ habitas super aquas multas, locuples in thesauris: venit finis tuus, pedalis præcisionis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 14, 'Juravit Dominus exercituum per animam suam: Quoniam replebo te hominibus quasi brucho, et super te celeuma cantabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 15, 'Qui fecit terram in fortitudine sua, præparavit orbem in sapientia sua, et prudentia sua extendit cælos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 16, 'Dante eo vocem, multiplicantur aquæ in cælo: qui levat nubes ab extremo terræ, fulgura in pluviam fecit, et produxit ventum de thesauris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 17, 'Stultus factus est omnis homo a scientia; confusus est omnis conflator in sculptili: quia mendax est conflatio eorum, nec est spiritus in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 18, 'Vana sunt opera, et risu digna: in tempore visitationis suæ peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 19, 'Non sicut hæc, pars Jacob, quia qui fecit omnia ipse est: et Israël sceptrum hæreditatis ejus: Dominus exercituum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 20, 'Collidis tu mihi vasa belli: et ego collidam in te gentes, et disperdam in te regna:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 21, 'et collidam in te equum et equitem ejus: et collidam in te currum et ascensorem ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 22, 'et collidam in te virum et mulierem: et collidam in te senem et puerum: et collidam in te juvenem et virginem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 23, 'et collidam in te pastorem et gregem ejus: et collidam in te agricolam et jugales ejus: et collidam in te duces et magistratus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 24, 'et reddam Babyloni, et cunctis habitatoribus Chaldææ, omne malum suum quod fecerunt in Sion, in oculis vestris, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 25, 'Ecce ego ad te, mons pestifer, ait Dominus, qui corrumpis universam terram: et extendam manum meam super te, et evolvam te de petris, et dabo te in montem combustionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 26, 'et non tollent de te lapidem in angulum, et lapidem in fundamenta: sed perditus in æternum eris, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 27, 'Levate signum in terra, clangite buccina in gentibus, sanctificate super eam gentes, annuntiate contra illam regibus Ararat, Menni, et Ascenez: numerate contra eam Taphsar, adducite equum quasi bruchum aculeatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 28, 'Sanctificate contra eam gentes, reges Mediæ, duces ejus, et universos magistratus ejus, cunctamque terram potestatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 29, 'Et commovebitur terra et conturbabitur, quia evigilabit contra Babylonem cogitatio Domini, ut ponat terram Babylonis desertam et inhabitabilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 30, 'Cessaverunt fortes Babylonis a prælio; habitaverunt in præsidiis: devoratum est robur eorum, et facti sunt quasi mulieres: incensa sunt tabernacula ejus, contriti sunt vectes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 31, 'Currens obviam currenti veniet, et nuntius obvius nuntianti, ut annuntiet regi Babylonis quia capta est civitas ejus a summo usque ad summum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 32, 'Et vada præoccupata sunt, et paludes incensæ sunt igni, et viri bellatores conturbati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 33, 'Quia hæc dicit Dominus exercituum, Deus Israël: Filia Babylonis quasi area, tempus trituræ ejus: adhuc modicum, et veniet tempus messionis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 34, 'Comedit me, devoravit me Nabuchodonosor rex Babylonis: reddidit me quasi vas inane, absorbuit me quasi draco, replevit ventrem suum teneritudine mea, et ejecit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 35, 'Iniquitas adversum me et caro mea super Babylonem, dicit habitatio Sion: et sanguis meus super habitatores Chaldææ, dicit Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 36, 'Propterea hæc dicit Dominus: Ecce ego judicabo causam tuam, et ulciscar ultionem tuam: et desertum faciam mare ejus, et siccabo venam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 37, 'Et erit Babylon in tumulos, habitatio draconum, stupor et sibilus, eo quod non sit habitator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 38, 'Simul ut leones rugient; excutient comas veluti catuli leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 39, 'In calore eorum ponam potus eorum, et inebriabo eos ut sopiantur, et dormiant somnum sempiternum, et non consurgant, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 40, 'Deducam eos quasi agnos ad victimam, et quasi arietes cum hædis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 41, 'Quomodo capta est Sesach, et comprehensa est inclyta universæ terræ! quomodo facta est in stuporem Babylon inter gentes!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 42, 'Ascendit super Babylonem mare: multitudine fluctuum ejus operta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 43, 'Factæ sunt civitates ejus in stuporem, terra inhabitabilis et deserta, terra in qua nullus habitet, nec transeat per eam filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 44, 'Et visitabo super Bel in Babylone, et ejiciam quod absorbuerat de ore ejus: et non confluent ad eum ultra gentes, siquidem et murus Babylonis corruet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 45, 'Egredimini de medio ejus, populus meus, ut salvet unusquisque animam suam ab ira furoris Domini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 46, 'et ne forte mollescat cor vestrum, et timeatis auditum qui audietur in terra: et veniet in anno auditio, et post hunc annum auditio, et iniquitas in terra, et dominator super dominatorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 47, 'Propterea ecce dies veniunt, et visitabo super sculptilia Babylonis, et omnis terra ejus confundetur, et universi interfecti ejus cadent in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 48, 'Et laudabunt super Babylonem cæli et terra, et omnia quæ in eis sunt: quia ab aquilone venient ei prædones, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 49, 'Et quomodo fecit Babylon, ut caderent occisi in Israël, sic de Babylone cadent occisi in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 50, 'Qui fugistis gladium, venite, nolite stare: recordamini procul Domini, et Jerusalem ascendat super cor vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 51, 'Confusi sumus, quoniam audivimus opprobrium: operuit ignominia facies nostras, quia venerunt alieni super sanctificationem domus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 52, 'Propterea ecce dies veniunt, ait Dominus, et visitabo super sculptilia ejus, et in omni terra ejus mugiet vulneratus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 53, 'Si ascenderit Babylon in cælum, et firmaverit in excelso robur suum, a me venient vastatores ejus, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 54, 'Vox clamoris de Babylone, et contritio magna de terra Chaldæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 55, 'quoniam vastavit Dominus Babylonem, et perdidit ex ea vocem magnam: et sonabunt fluctus eorum quasi aquæ multæ; dedit sonitum vox eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 56, 'quia venit super eam, id est super Babylonem, prædo, et apprehensi sunt fortes ejus, et emarcuit arcus eorum, quia fortis ultor Dominus reddens retribuet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 57, 'Et inebriabo principes ejus, et sapientes ejus, et duces ejus, et magistratus ejus, et fortes ejus: et dormient somnum sempiternum, et non expergiscentur, ait Rex (Dominus exercituum nomen ejus).');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 58, 'Hæc dicit Dominus exercituum: Murus Babylonis ille latissimus suffossione suffodietur, et portæ ejus excelsæ igni comburentur, et labores populorum ad nihilum, et gentium in ignem erunt, et disperibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 59, 'Verbum quod præcepit Jeremias propheta Saraiæ filio Neriæ filii Maasiæ, cum pergeret cum Sedecia rege in Babylonem, in anno quarto regni ejus: Saraias autem erat princeps prophetiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 60, 'Et scripsit Jeremias omne malum quod venturum erat super Babylonem, in libro uno: omnia verba hæc quæ scripta sunt contra Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 61, 'Et dixit Jeremias ad Saraiam: Cum veneris in Babylonem, et videris, et legeris omnia verba hæc,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 62, 'dices: Domine, tu locutus es contra locum istum, ut disperderes eum, ne sit qui in eo habitet, ab homine usque ad pecus, et ut sit perpetua solitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 63, 'Cumque compleveris legere librum istum, ligabis ad eum lapidem, et projicies illum in medium Euphraten,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 51, 64, 'et dices: Sic submergetur Babylon, et non consurget a facie afflictionis quam ego adduco super eam, et dissolvetur. Hucusque verba Jeremiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 1, 'Filius viginti et unius anni erat Sedecias cum regnare cœpisset, et undecim annis regnavit in Jerusalem. Et nomen matris ejus Amital filia Jeremiæ de Lobna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 2, 'Et fecit malum in oculis Domini, juxta omnia quæ fecerat Joakim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 3, 'quoniam furor Domini erat in Jerusalem et in Juda, usquequo projiceret eos a facie sua: et recessit Sedecias a rege Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 4, 'Factum est autem in anno nono regni ejus, in mense decimo, decima mensis, venit Nabuchodonosor rex Babylonis, ipse et omnis exercitus ejus, adversus Jerusalem: et obsederunt eam, et ædificaverunt contra eam munitiones in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 5, 'Et fuit civitas obsessa usque ad undecimum annum regis Sedeciæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 6, 'Mense autem quarto, nona mensis, obtinuit fames civitatem, et non erant alimenta populo terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 7, 'Et dirupta est civitas, et omnes viri bellatores ejus fugerunt, exieruntque de civitate nocte, per viam portæ quæ est inter duos muros, et ducit ad hortum regis, Chaldæis obsidentibus urbem in gyro, et abierunt per viam quæ ducit in eremum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 8, 'Persecutus est autem Chadæorum exercitus regem, et apprehenderunt Sedeciam in deserto quod est juxta Jericho: et omnis comitatus ejus diffugit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 9, 'Cumque comprehendissent regem, adduxerunt eum ad regem Babylonis in Reblatha, quæ est in terra Emath, et locutus est ad eum judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 10, 'Et jugulavit rex Babylonis filios Sedeciæ in oculis ejus, sed et omnes principes Juda occidit in Reblatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 11, 'Et oculos Sedeciæ eruit, et vinxit eum compedibus, et adduxit eum rex Babylonis in Babylonem, et posuit eum in domo carceris usque ad diem mortis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 12, 'In mense autem quinto, decima mensis, ipse est annus nonusdecimus Nabuchodonosor regis Babylonis, venit Nabuzardan princeps militiæ, qui stabat coram rege Babylonis, in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 13, 'et incendit domum Domini, et domum regis, et omnes domos Jerusalem: et omnem domum magnam igni combussit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 14, 'et totum murum Jerusalem per circuitum destruxit cunctus exercitus Chaldæorum qui erat cum magistro militiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 15, 'De pauperibus autem populi, et de reliquo vulgo quod remanserat in civitate, et de perfugis qui transfugerant ad regem Babylonis, et ceteros de multitudine transtulit Nabuzardan princeps militiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 16, 'De pauperibus vero terræ reliquit Nabuzardan princeps militiæ vinitores et agricolas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 17, 'Columnas quoque æreas quæ erant in domo Domini, et bases, et mare æneum quod erat in domo Domini, confregerunt Chaldæi, et tulerunt omne æs eorum in Babylonem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 18, 'et lebetes, et creagras, et psalteria, et phialas, et mortariola, et omnia vasa ærea quæ in ministerio fuerant, tulerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 19, 'et hydrias, et thymiamateria, et urceos, et pelves, et candelabra, et mortaria, et cyathos, quotquot aurea, aurea, et quotquot argentea, argentea, tulit magister militiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 20, 'et columnas duas, et mare unum, et vitulos duodecim æreos qui erant sub basibus quas fecerat rex Salomon in domo Domini. Non erat pondus æris omnium horum vasorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 21, 'De columnis autem decem et octo cubiti altitudinis erant in columna una, et funiculus duodecim cubitorum circuibat eam: porro grossitudo ejus quatuor digitorum, et intrinsecus cava erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 22, 'Et capitella super utramque ærea: altitudo capitelli unius quinque cubitorum, et retiacula et malogranata super coronam in circuitu, omnia ærea: similiter columnæ secundæ, et malogranata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 23, 'Et fuerunt malogranata nonaginta sex dependentia: et omnia malogranata centum, retiaculis circumdabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 24, 'Et tulit magister militiæ Saraiam sacerdotem primum, et Sophoniam sacerdotem secundum, et tres custodes vestibuli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 25, 'et de civitate tulit eunuchum unum, qui erat præpositus super viros bellatores: et septem viros de his qui videbant faciem regis, qui inventi sunt in civitate: et scribam principem militum, qui probabat tyrones: et sexaginta viros de populo terræ, qui inventi sunt in medio civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 26, 'Tulit autem eos Nabuzardan magister militiæ, et duxit eos ad regem Babylonis in Reblatha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 27, 'et percussit eos rex Babylonis, et interfecit eos in Reblatha in terra Emath: et translatus est Juda de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 28, 'Iste est populus quem transtulit Nabuchodonosor: in anno septimo, Judæos tria millia et viginti tres:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 29, 'in anno octavodecimo Nabuchodonosor, de Jerusalem animas octingentas triginta duas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 30, 'in anno vigesimo tertio Nabuchodonosor, transtulit Nabuzardan magister militiæ animas Judæorum septingentas quadraginta quinque. Omnes ergo animæ, quatuor millia sexcentæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 31, 'Et factum est in trigesimo septimo anno transmigrationis Joachin regis Juda, duodecimo mense, vigesima quinta mensis, elevavit Evilmerodach rex Babylonis, ipso anno regni sui, caput Joachin regis Juda, et eduxit eum de domo carceris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 32, 'Et locutus est cum eo bona, et posuit thronum ejus super thronos regum qui erant post se in Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 33, 'Et mutavit vestimenta carceris ejus, et comedebat panem coram eo semper cunctis diebus vitæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 52, 34, 'Et cibaria ejus, cibaria perpetua dabantur ei a rege Babylonis, statuta per singulos dies, usque ad diem mortis suæ, cunctis diebus vitæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Quomodo sedet sola civitas plena populo! Facta est quasi vidua domina gentium; princeps provinciarum facta est sub tributo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Plorans ploravit in nocte, et lacrimæ ejus in maxillis ejus: non est qui consoletur eam ex omnibus caris ejus; omnes amici ejus spreverunt eam, et facti sunt ei inimici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Migravit Judas propter afflictionem, et multitudinem servitutis; habitavit inter gentes, nec invenit requiem: omnes persecutores ejus apprehenderunt eam inter angustias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Viæ Sion lugent, eo quod non sint qui veniant ad solemnitatem: omnes portæ ejus destructæ, sacerdotes ejus gementes; virgines ejus squalidæ, et ipsa oppressa amaritudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Facti sunt hostes ejus in capite; inimici ejus locupletati sunt: quia Dominus locutus est super eam propter multitudinem iniquitatum ejus. Parvuli ejus ducti sunt in captivitatem ante faciem tribulantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Et egressus est a filia Sion omnis decor ejus; facti sunt principes ejus velut arietes non invenientes pascua, et abierunt absque fortitudine ante faciem subsequentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Recordata est Jerusalem dierum afflictionis suæ, et prævaricationis, omnium desiderabilium suorum, quæ habuerat a diebus antiquis, cum caderet populus ejus in manu hostili, et non esset auxiliator: viderunt eam hostes, et deriserunt sabbata ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Peccatum peccavit Jerusalem, propterea instabilis facta est; omnes qui glorificabant eam spreverunt illam, quia viderunt ignominiam ejus: ipsa autem gemens conversa est retrorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Sordes ejus in pedibus ejus, nec recordata est finis sui; deposita est vehementer, non habens consolatorem. Vide, Domine, afflictionem meam, quoniam erectus est inimicus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Manum suam misit hostis ad omnia desiderabilia ejus, quia vidit gentes ingressas sanctuarium suum, de quibus præceperas ne intrarent in ecclesiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Omnis populus ejus gemens, et quærens panem; dederunt pretiosa quæque pro cibo ad refocillandam animam. Vide, Domine, et considera quoniam facta sum vilis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'O vos omnes qui transitis per viam, attendite, et videte si est dolor sicut dolor meus! quoniam vindemiavit me, ut locutus est Dominus, in die iræ furoris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'De excelso misit ignem in ossibus meis, et erudivit me: expandit rete pedibus meis, convertit me retrorsum; posuit me desolatam, tota die mœrore confectam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Vigilavit jugum iniquitatum mearum; in manu ejus convolutæ sunt, et impositæ collo meo. Infirmata est virtus mea: dedit me Dominus in manu de qua non potero surgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Abstulit omnes magnificos meos Dominus de medio mei; vocavit adversum me tempus ut contereret electos meos. Torcular calcavit Dominus virgini filiæ Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Idcirco ego plorans, et oculus meus deducens aquas, quia longe factus est a me consolator, convertens animam meam. Facti sunt filii mei perditi, quoniam invaluit inimicus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Expandit Sion manus suas; non est qui consoletur eam. Mandavit Dominus adversum Jacob in circuitu ejus hostes ejus; facta est Jerusalem quasi polluta menstruis inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Justus est Dominus, quia os ejus ad iracundiam provocavi. Audite, obsecro, universi populi, et videte dolorem meum: virgines meæ et juvenes mei abierunt in captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Vocavi amicos meos, et ipsi deceperunt me; sacerdotes mei et senes mei in urbe consumpti sunt, quia quæsierunt cibum sibi ut refocillarent animam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Vide, Domine, quoniam tribulor: conturbatus est venter meus, subversum est cor meum in memetipsa, quoniam amaritudine plena sum. Foris interfecit gladius, et domi mors similis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 21, 'Audierunt quia ingemisco ego, et non est qui consoletur me; omnes inimici mei audierunt malum meum, lætati sunt quoniam tu fecisti: adduxisti diem consolationis, et fient similes mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 22, 'Ingrediatur omne malum eorum coram te: et vindemia eos, sicut vindemiasti me propter omnes iniquitates meas: multi enim gemitus mei, et cor meum mœrens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Quomodo obtexit caligine in furore suo Dominus filiam Sion; projecit de cælo in terram inclytam Israël, et non est recordatus scabelli pedum suorum in die furoris sui!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Præcipitavit Dominus, nec pepercit omnia speciosa Jacob: destruxit in furore suo munitiones virginis Juda, et dejecit in terram; polluit regnum et principes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Confregit in ira furoris sui omne cornu Israël; avertit retrorsum dexteram suam a facie inimici, et succendit in Jacob quasi ignem flammæ devorantis in gyro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Tetendit arcum suum quasi inimicus, firmavit dexteram suam quasi hostis, et occidit omne quod pulchrum erat visu in tabernaculo filiæ Sion; effudit quasi ignem indignationem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Factus est Dominus velut inimicus, præcipitavit Israël: præcipitavit omnia mœnia ejus, dissipavit munitiones ejus, et replevit in filia Juda humiliatum et humiliatam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Et dissipavit quasi hortum tentorium suum; demolitus est tabernaculum suum. Oblivioni tradidit Dominus in Sion festivitatem et sabbatum; et in opprobrium, et in indignationem furoris sui, regem et sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Repulit Dominus altare suum; maledixit sanctificationi suæ: tradidit in manu inimici muros turrium ejus. Vocem dederunt in domo Domini sicut in die solemni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Cogitavit Dominus dissipare murum filiæ Sion; tetendit funiculum suum, et non avertit manum suam a perditione: luxitque antemurale, et murus pariter dissipatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Defixæ sunt in terra portæ ejus, perdidit et contrivit vectes ejus; regem ejus et principes ejus in gentibus: non est lex, et prophetæ ejus non invenerunt visionem a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Sederunt in terra, conticuerunt senes filiæ Sion; consperserunt cinere capita sua, accincti sunt ciliciis: abjecerunt in terram capita sua virgines Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Defecerunt præ lacrimis oculi mei, conturbata sunt viscera mea; effusum est in terra jecur meum super contritione filiæ populi mei, cum deficeret parvulus et lactens in plateis oppidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Matribus suis dixerunt: Ubi est triticum et vinum? cum deficerent quasi vulnerati in plateis civitatis, cum exhalarent animas suas in sinu matrum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Cui comparabo te, vel cui assimilabo te, filia Jerusalem? cui exæquabo te, et consolabor te, virgo, filia Sion? magna est enim velut mare contritio tua: quis medebitur tui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Prophetæ tui viderunt tibi falsa et stulta; nec aperiebant iniquitatem tuam, ut te ad pœnitentiam provocarent; viderunt autem tibi assumptiones falsas, et ejectiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Plauserunt super te manibus omnes transeuntes per viam; sibilaverunt et moverunt caput suum super filiam Jerusalem: Hæccine est urbs, dicentes, perfecti decoris, gaudium universæ terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Aperuerunt super te os suum omnes inimici tui: sibilaverunt, et fremuerunt dentibus, et dixerunt: Devorabimus: en ista est dies quam exspectabamus; invenimus, vidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Fecit Dominus quæ cogitavit; complevit sermonem suum, quem præceperat a diebus antiquis: destruxit, et non pepercit, et lætificavit super te inimicum, et exaltavit cornu hostium tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Clamavit cor eorum ad Dominum super muros filiæ Sion: Deduc quasi torrentem lacrimas per diem et noctem; non des requiem tibi, neque taceat pupilla oculi tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Consurge, lauda in nocte, in principio vigiliarum; effunde sicut aquam cor tuum ante conspectum Domini: leva ad eum manus tuas pro anima parvulorum tuorum, qui defecerunt in fame in capite omnium compitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Vide, Domine, et considera quem vindemiaveris ita. Ergone comedent mulieres fructum suum, parvulos ad mensuram palmæ? si occiditur in sanctuario Domini sacerdos et propheta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Jacuerunt in terra foris puer et senex; virgines meæ et juvenes mei ceciderunt in gladio: interfecisti in die furoris tui, percussisti, nec misertus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Vocasti quasi ad diem solemnem, qui terrerent me de circuitu; et non fuit in die furoris Domini qui effugeret, et relinqueretur: quos educavi et enutrivi, inimicus meus consumpsit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Ego vir videns paupertatem meam in virga indignationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Me minavit, et adduxit in tenebras, et non in lucem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Tantum in me vertit et convertit manum suam tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Vetustam fecit pellem meam et carnem meam; contrivit ossa mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, '\'dificavit in gyro meo, et circumdedit me felle et labore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'In tenebrosis collocavit me, quasi mortuos sempiternos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Circumædificavit adversum me, ut non egrediar; aggravavit compedem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Sed et cum clamavero, et rogavero, exclusit orationem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Conclusit vias meas lapidibus quadris; semitas meas subvertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Ursus insidians factus est mihi, leo in absconditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Semitas meas subvertit, et confregit me; posuit me desolatam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Tetendit arcum suum, et posuit me quasi signum ad sagittam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Misit in renibus meis filias pharetræ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Factus sum in derisum omni populo meo, canticum eorum tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Replevit me amaritudinibus; inebriavit me absinthio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Et fregit ad numerum dentes meos; cibavit me cinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Et repulsa est a pace anima mea; oblitus sum bonorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Et dixi: Periit finis meus, et spes mea a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Recordare paupertatis, et transgressionis meæ, absinthii et fellis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Memoria memor ero, et tabescet in me anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Hæc recolens in corde meo, ideo sperabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 22, 'Misericordiæ Domini, quia non sumus consumpti; quia non defecerunt miserationes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 23, 'Novi diluculo, multa est fides tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 24, 'Pars mea Dominus, dixit anima mea; propterea exspectabo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 25, 'Bonus est Dominus sperantibus in eum, animæ quærenti illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 26, 'Bonum est præstolari cum silentio salutare Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 27, 'Bonum est viro cum portaverit jugum ab adolescentia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 28, 'Sedebit solitarius, et tacebit, quia levavit super se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 29, 'Ponet in pulvere os suum, si forte sit spes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 30, 'Dabit percutienti se maxillam: saturabitur opprobriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 31, 'Quia non repellet in sempiternum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 32, 'Quia si abjecit, et miserebitur, secundum multitudinem misericordiarum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 33, 'Non enim humiliavit ex corde suo et abjecit filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 34, 'Ut conteret sub pedibus suis omnes vinctos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 35, 'Ut declinaret judicium viri in conspectu vultus Altissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 36, 'Ut perverteret hominem in judicio suo; Dominus ignoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 37, 'Quis est iste qui dixit ut fieret, Domino non jubente?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 38, 'Ex ore Altissimi non egredientur nec mala nec bona?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 39, 'Quid murmuravit homo vivens, vir pro peccatis suis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 40, 'Scrutemur vias nostras, et quæramus, et revertamur ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 41, 'Levemus corda nostra cum manibus ad Dominum in cælos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 42, 'Nos inique egimus, et ad iracundiam provocavimus; idcirco tu inexorabilis es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 43, 'Operuisti in furore, et percussisti nos; occidisti, nec pepercisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 44, 'Opposuisti nubem tibi, ne transeat oratio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 45, 'Eradicationem et abjectionem posuisti me in medio populorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 46, 'Aperuerunt super nos os suum omnes inimici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 47, 'Formido et laqueus facta est nobis vaticinatio, et contritio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 48, 'Divisiones aquarum deduxit oculus meus, in contritione filiæ populi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 49, 'Oculus meus afflictus est, nec tacuit, eo quod non esset requies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 50, 'Donec respiceret et videret Dominus de cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 51, 'Oculus meus deprædatus est animam meam in cunctis filiabus urbis meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 52, 'Venatione ceperunt me quasi avem inimici mei gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 53, 'Lapsa est in lacum vita mea, et posuerunt lapidem super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 54, 'Inundaverunt aquæ super caput meum; dixi: Perii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 55, 'Invocavi nomen tuum, Domine, de lacu novissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 56, 'Vocem meam audisti; ne avertas aurem tuam a singultu meo et clamoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 57, 'Appropinquasti in die quando invocavi te; dixisti: Ne timeas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 58, 'Judicasti, Domine, causam animæ meæ, redemptor vitæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 59, 'Vidisti, Domine, iniquitatem illorum adversum me: judica judicium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 60, 'Vidisti omnem furorem, universas cogitationes eorum adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 61, 'Audisti opprobrium eorum, Domine, omnes cogitationes eorum adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 62, 'Labia insurgentium mihi, et meditationes eorum adversum me tota die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 63, 'Sessionem eorum et resurrectionem eorum vide; ego sum psalmus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 64, 'Redes eis vicem, Domine, juxta opera manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 65, 'Dabis eis scutum cordis, laborem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 66, 'Persequeris in furore, et conteres eos sub cælis, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'Quomodo obscuratum est aurum, mutatus est color optimus! dispersi sunt lapides sanctuarii in capite omnium platearum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'Filii Sion inclyti, et amicti auro primo: quomodo reputati sunt in vasa testea, opus manuum figuli!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'Sed et lamiæ nudaverunt mammam, lactaverunt catulos suos: filia populi mei crudelis quasi struthio in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Adhæsit lingua lactentis ad palatum ejus in siti; parvuli petierunt panem, et non erat qui frangeret eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'Qui vescebantur voluptuose, interierunt in viis; qui nutriebantur in croceis, amplexati sunt stercora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'Et major effecta est iniquitas filiæ populi mei peccato Sodomorum, quæ subversa est in momento, et non ceperunt in ea manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Candidiores Nazaræi ejus nive, nitidiores lacte, rubicundiores ebore antiquo, sapphiro pulchriores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'Denigrata est super carbones facies eorum et non sunt cogniti in plateis; adhæsit cutis eorum ossibus: aruit, et facta est quasi lignum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Melius fuit occisis gladio quam interfectis fame, quoniam isti extabuerunt consumpti a sterilitate terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Manus mulierum misericordium coxerunt filios suos; facti sunt cibus earum in contritione filiæ populi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Complevit Dominus furorem suum, effudit iram indignationis suæ: et succendit ignem in Sion, et devoravit fundamenta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Non crediderunt reges terræ, et universi habitatores orbis, quoniam ingrederetur hostis et inimicus per portas Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Propter peccata prophetarum ejus, et iniquitates sacerdotum ejus, qui effuderunt in medio ejus sanguinem justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Erraverunt cæci in plateis, polluti sunt in sanguine; cumque non possent, tenuerunt lacinias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Recedite polluti, clamaverunt eis; recedite, abite, nolite tangere: jurgati quippe sunt, et commoti dixerunt inter gentes: Non addet ultra ut habitet in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'Facies Domini divisit eos, non addet ut respiciat eos; facies sacerdotum non erubuerunt, neque senum miserti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, 'Cum adhuc subsisteremus, defecerunt oculi nostri ad auxilium nostrum vanum; cum respiceremus attenti ad gentem quæ salvare non poterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, 'Lubricaverunt vestigia nostra in itinere platearum nostrarum; appropinquavit finis noster, completi sunt dies nostri, quia venit finis noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'Velociores fuerunt persecutores nostri aquilis cæli; super montes persecuti sunt nos, in deserto insidiati sunt nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Spiritus oris nostri, christus Dominus, captus est in peccatis nostris, cui diximus: In umbra tua vivemus in gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'Gaude et lætare, filia Edom, quæ habitas in terra Hus! ad te quoque perveniet calix: inebriaberis, atque nudaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 22, 'Completa est iniquitas tua, filia Sion: non addet ultra ut transmigret te. Visitavit iniquitatem tuam, filia Edom; discooperuit peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 1, 'Recordare, Domine, quid acciderit nobis; intuere et respice opprobrium nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 2, 'Hæreditas nostra versa est ad alienos, domus nostræ ad extraneos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 3, 'Pupilli facti sumus absque patre, matres nostræ quasi viduæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 4, 'Aquam nostram pecunia bibimus; ligna nostra pretio comparavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 5, 'Cervicibus nostris minabamur, lassis non dabatur requies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 6, '\'gypto dedimus manum et Assyriis, ut saturaremur pane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 7, 'Patres nostri peccaverunt, et non sunt: et nos iniquitates eorum portavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 8, 'Servi dominati sunt nostri: non fuit qui redimeret de manu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 9, 'In animabus nostris afferebamus panem nobis, a facie gladii in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 10, 'Pellis nostra quasi clibanus exusta est, a facie tempestatum famis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 11, 'Mulieres in Sion humiliaverunt, et virgines in civitatibus Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 12, 'Principes manu suspensi sunt; facies senum non erubuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 13, 'Adolescentibus impudice abusi sunt, et pueri in ligno corruerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 14, 'Senes defecerunt de portis, juvenes de choro psallentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 15, 'Defecit gaudium cordis nostri; versus est in luctum chorus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 16, 'Cecidit corona capitis nostri: væ nobis, quia peccavimus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 17, 'Propterea mœstum factum est cor nostrum; ideo contenebrati sunt oculi nostri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 18, 'propter montem Sion quia disperiit; vulpes ambulaverunt in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 19, 'Tu autem, Domine, in æternum permanebis, solium tuum in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 20, 'Quare in perpetuum oblivisceris nostri, derelinques nos in longitudine dierum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 21, 'Converte nos, Domine, ad te, et convertemur; innova dies nostros, sicut a principio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 5, 22, 'Sed projiciens repulisti nos: iratus es contra nos vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Et hæc verba libri quæ scripsit Baruch filius Neriæ, filii Maasiæ, filii Sedeciæ, filii Sedei, filii Helciæ, in Babylonia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'in anno quinto, in septimo die mensis, in tempore quo ceperunt Chaldæi Jerusalem, et succenderunt eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Et legit Baruch verba libri hujus ad aures Jechoniæ filii Joakim regis Juda, et ad aures universi populi venientis ad librum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'et ad aures potentium, filiorum regum, et ad aures presbyterorum, et ad aures populi, a minimo usque ad maximum eorum, omnium habitantium in Babylonia, ad flumen Sodi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Qui audientes plorabant, et jejunabant, et orabant in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Et collegerunt pecuniam, secundum quod potuit uniuscujusque manus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'et miserunt in Jerusalem ad Joakim filium Helciæ filii Salom sacerdotem, et ad sacerdotes, et ad omnem populum qui inventi sunt cum eo in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'cum acciperet vasa templi Domini, quæ ablata fuerant de templo, revocare in terram Juda, decima die mensis Sivan, vasa argentea quæ fecit Sedecias filius Josiæ rex Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'posteaquam cepisset Nabuchodonosor rex Babylonis Jechoniam, et principes, et cunctos potentes, et populum terræ, ab Jerusalem, et duxit eos vinctos in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Et dixerunt: Ecce misimus ad vos pecunias, de quibus emite holocautomata et thus: et facite manna, et offerte pro peccato, ad aram Domini Dei nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'et orate pro vita Nabuchodonosor regis Babylonis, et pro vita Baltassar filii ejus, ut sint dies eorum sicut dies cæli super terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'et ut det Dominus virtutem nobis, et illuminet oculos nostros, ut vivamus sub umbra Nabuchodonosor regis Babylonis, et sub umbra Baltassar filii ejus, et serviamus eis multis diebus, et inveniamus gratiam in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Et pro nobis ipsis orate ad Dominum Deum nostrum, quia peccavimus Domino Deo nostro, et non est aversus furor ejus a nobis usque in hunc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Et legite librum istum quem misimus ad vos recitari in templo Domini, in die solemni et in die opportuno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'et dicetis: Domino Deo nostro justitia, nobis autem confusio faciei nostræ, sicut est dies hæc omni Juda, et habitantibus in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 16, 'regibus nostris, et principibus nostris, et sacerdotibus nostris, et prophetis nostris, et patribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 17, 'Peccavimus ante Dominum Deum nostrum, et non credidimus, diffidentes in eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 18, 'et non fuimus subjectibiles illi, et non audivimus vocem Domini Dei nostri, ut ambularemus in mandatis ejus, quæ dedit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 19, 'A die qua eduxit patres nostros de terra \'gypti, usque ad diem hanc, eramus incredibiles ad Dominum Deum nostrum: et dissipati recessimus, ne audiremus vocem ipsius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 20, 'et adhæserunt nobis multa mala et maledictiones quæ constituit Dominus Moysi servo suo, qui eduxit patres nostros de terra \'gypti, dare nobis terram fluentem lac et mel, sicut hodierna die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 21, 'Et non audivimus vocem Domini Dei nostri, secundum omnia verba prophetarum quos misit ad nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 22, 'et abivimus unusquisque in sensum cordis nostri maligni, operari diis alienis, facientes mala ante oculos Domini Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Propter quod statuit Dominus Deus noster verbum suum, quod locutus est ad nos, et ad judices nostros qui judicaverunt Israël, et ad reges nostros, et ad principes nostros, et ad omnem Israël et Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'ut adduceret Dominus super nos mala magna, quæ non sunt facta sub cælo quemadmodum facta sunt in Jerusalem, secundum quæ scripta sunt in lege Moysi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'et manducaret homo carnes filii sui et carnes filiæ suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Et dedit eos sub manu regum omnium qui sunt in circuitu nostro, in improperium et in desolationem in omnibus populis in quibus nos dispersit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'et facti sumus subtus, et non supra, quia peccavimus Domino Deo nostro, non obaudiendo voci ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Domino Deo nostro justitia, nobis autem et patribus nostris confusio faciei, sicut est dies hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'quia locutus est Dominus super nos omnia mala hæc quæ venerunt super nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'et non sumus deprecati faciem Domini Dei nostri, ut reverteremur unusquisque nostrum a viis nostris pessimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Et vigilavit Dominus in malis, et adduxit ea super nos: quia justus est Dominus in omnibus operibus suis quæ mandavit nobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'et non audivimus vocem ipsius ut iremus in præceptis Domini, quæ dedit ante faciem nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Et nunc, Domine Deus Israël, qui eduxisti populum tuum de terra \'gypti in manu valida, et in signis, et in prodigiis, et in virtute tua magna, et in brachio excelso, et fecisti tibi nomen sicut est dies iste:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'peccavimus, impie egimus, inique gessimus, Domine Deus noster, in omnibus justitiis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Avertatur ira tua a nobis, quia derelicti sumus pauci inter gentes ubi dispersisti nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Exaudi, Domine, preces nostras et orationes nostras, et educ nos propter te, et da nobis invenire gratiam ante faciem eorum qui nos abduxerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'ut sciat omnis terra quia tu es Dominus Deus noster, et quia nomen tuum invocatum est super Israël, et super genus ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Respice, Domine, de domo sancta tua in nos, et inclina aurem tuam, et exaudi nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 17, 'Aperi oculos tuos et vide: quia non mortui qui sunt in inferno, quorum spiritus acceptus est a visceribus suis, dabunt honorem et justificationem Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 18, 'sed anima quæ tristis est super magnitudine mali, et incedit curva et infirma, et oculi deficientes, et anima esuriens, dat tibi gloriam et justitiam Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 19, 'Quia non secundum justitias patrum nostrorum nos fundimus preces et petimus misericordiam ante conspectum tuum, Domine Deus noster:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 20, 'sed quia misisti iram tuam et furorem tuum super nos, sicut locutus es in manu puerorum tuorum prophetarum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 21, 'Sic dicit Dominus: Inclinate humerum vestrum et cervicem vestram, et opera facite regi Babylonis, et sedebitis in terra quam dedi patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 22, 'Quod si non audieritis vocem Domini Dei vestri, operari regi Babyloniæ, defectionem vestram faciam de civitatibus Juda, et a foris Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 23, 'et auferam a vobis vocem jucunditatis et vocem gaudii, et vocem sponsi et vocem sponsæ, et erit omnis terra sine vestigio ab inhabitantibus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 24, 'Et non audierunt vocem tuam, ut operarentur regi Babylonis: et statuisti verba tua, quæ locutus es in manibus puerorum tuorum prophetarum, ut transferrentur ossa regum nostrorum et ossa patrum nostrorum de loco suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 25, 'et ecce projecta sunt in calore solis et in gelu noctis, et mortui sunt in doloribus pessimis, in fame et in gladio, et in emissione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 26, 'Et posuisti templum in quo invocatum est nomen tuum in ipso sicut hæc dies, propter iniquitatem domus Israël et domus Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 27, 'Et fecisti in nobis, Domine Deus noster, secundum omnem bonitatem tuam et secundum omnem miserationem tuam illam magnam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 28, 'sicut locutus es in manu pueri tui Moysi, in die qua præcepisti ei scribere legem tuam coram filiis Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 29, 'dicens: Si non audieritis vocem meam, multitudo hæc magna convertetur in minimam inter gentes, quo ego eos dispergam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 30, 'quia scio quod me non audiet populus: populus est enim dura cervice. Et convertetur ad cor suum in terra captivitatis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 31, 'et scient quia ego sum Dominus Deus eorum: et dabo eis cor, et intelligent; aures, et audient:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 32, 'et laudabunt me in terra captivitatis suæ, et memores erunt nominis mei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 33, 'et avertent se a dorso suo duro, et a malignitatibus suis: quia reminiscentur viam patrum suorum, qui peccaverunt in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 34, 'Et revocabo illos in terram quam juravi patribus eorum, Abraham, Isaac, et Jacob: et dominabuntur ejus, et multiplicabo eos, et non minorabuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 35, 'et statuam illis testamentum alterum sempiternum, ut sim illis in Deum, et ipsi erunt mihi in populum: et non movebo amplius populum meum, filios Israël, a terra quam dedi illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Et nunc, Domine omnipotens, Deus Israël, anima in angustiis, et spiritus anxius clamat ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Audi, Domine, et miserere, quia Deus es misericors: et miserere nostri, quia peccavimus ante te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'quia tu sedes in sempiternum, et nos, peribimus in ævum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Domine omnipotens, Deus Israël, audi nunc orationem mortuorum Israël, et filiorum ipsorum qui peccaverunt ante te, et non audierunt vocem Domini Dei sui, et agglutinata sunt nobis mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Noli meminisse iniquitatum patrum nostrorum, sed memento manus tuæ et nominis tui in tempore isto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'quia tu es Dominus Deus noster, et laudabimus te, Domine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'quia propter hoc dedisti timorem tuum in cordibus nostris, et ut invocemus nomen tuum, et laudemus te in captivitate nostra, quia convertimur ab iniquitate patrum nostrorum, qui peccaverunt ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Et ecce nos in captivitate nostra sumus hodie, qua nos dispersisti in improperium, et in maledictum, et in peccatum, secundum omnes iniquitates patrum nostrorum, qui recesserunt a te, Domine Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Audi, Israël, mandata vitæ: auribus percipe, ut scias prudentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Quid est, Israël, quod in terra inimicorum es,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'inveterasti in terra aliena, coinquinatus es cum mortuis, deputatus es cum descendentibus in infernum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Dereliquisti fontem sapientiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'nam si in via Dei ambulasses, habitasses utique in pace sempiterna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Disce ubi sit prudentia, ubi sit virtus, ubi sit intellectus, ut scias simul ubi sit longiturnitas vitæ et victus, ubi sit lumen oculorum, et pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Quis invenit locum ejus? et quis intravit in thesauros ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 16, 'Ubi sunt principes gentium, et qui dominantur super bestias quæ sunt super terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 17, 'qui in avibus cæli ludunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 18, 'qui argentum thesaurizant, et aurum, in quo confidunt homines, et non est finis acquisitionis eorum? qui argentum fabricant, et solliciti sunt, nec est inventio operum illorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 19, 'Exterminati sunt, et ad inferos descenderunt, et alii loco eorum surrexerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 20, 'Juvenes viderunt lumen, et habitaverunt super terram, viam autem disciplinæ ignoraverunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 21, 'neque intellexerunt semitas ejus, neque filii eorum susceperunt eam: a facie ipsorum longe facta est;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 22, 'non est audita in terra Chanaan, neque visa est in Theman.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 23, 'Filii quoque Agar, qui exquirunt prudentiam quæ de terra est, negotiatores Merrhæ et Theman, et fabulatores, et exquisitores prudentiæ et intelligentiæ: viam autem sapientiæ nescierunt, neque commemorati sunt semitas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 24, 'O Israël, quam magna est domus Dei, et ingens locus possessionis ejus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 25, 'magnus est, et non habet finem: excelsus, et immensus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 26, 'Ibi fuerunt gigantes nominati illi, qui ab initio fuerunt, statura magna, scientes bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 27, 'Non hos elegit Dominus, neque viam disciplinæ invenerunt: propterea perierunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 28, 'et quoniam non habuerunt sapientiam, interierunt propter suam insipientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 29, 'Quis ascendit in cælum, et accepit eam, et eduxit eam de nubibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 30, 'Quis transfretavit mare, et invenit illam, et attulit illam super aurum electum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 31, 'Non est qui possit scire vias ejus, neque qui exquirat semitas ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 32, 'sed qui scit universa novit eam, et adinvenit eam prudentia sua qui præparavit terram in æterno tempore: et replevit eam pecudibus et quadrupedibus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 33, 'qui emittit lumen, et vadit, et vocavit illud, et obedit illi in tremore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 34, 'Stellæ autem dederunt lumen in custodiis suis, et lætatæ sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 35, 'vocatæ sunt, et dixerunt: Adsumus, et luxerunt ei cum jucunditate, qui fecit illas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 36, 'Hic est Deus noster, et non æstimabitur alius adversus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 37, 'Hic adinvenit omnem viam disciplinæ, et tradidit illam Jacob puero suo, et Israël dilecto suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 38, 'Post hæc in terris visus est, et cum hominibus conversatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Hic liber mandatorum Dei, et lex quæ est in æternum: omnes qui tenent eam pervenient ad vitam: qui autem dereliquerunt eam, in mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Convertere, Jacob, et apprehende eam: ambula per viam ad splendorem ejus contra lumen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Ne tradas alteri gloriam tuam, et dignitatem tuam genti alienæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Beati sumus, Israël, quia quæ Deo placent manifesta sunt nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Animæquior esto, populus Dei, memorabilis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'venundati estis gentibus non in perditionem: sed propter quod in ira ad iracundiam provocastis Deum, traditi estis adversariis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Exacerbastis enim eum qui fecit vos, Deum æternum, immolantes dæmoniis, et non Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Obliti enim estis Deum qui nutrivit vos, et contristastis nutricem vestram Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Vidit enim iracundiam a Deo venientem vobis, et dixit: Audite, confines Sion: adduxit enim mihi Deus luctum magnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Vidi enim captivitatem populi mei, filiorum meorum et filiarum, quam superduxit illis \'ternus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Nutrivi enim illos cum jucunditate; dimisi autem illos cum fletu et luctu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Nemo gaudeat super me viduam et desolatam: a multis derelicta sum propter peccata filiorum meorum, quia declinaverunt a lege Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Justitias autem ipsius nescierunt, nec ambulaverunt per vias mandatorum Dei, neque per semitas veritatis ejus cum justitia ingressi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 14, 'Veniant confines Sion, et memorentur captivitatem filiorum et filiarum mearum, quam superduxit illis \'ternus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 15, 'Adduxit enim super illos gentem de longinquo, gentem improbam, et alterius linguæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 16, 'qui non sunt reveriti senem, neque puerorum miserti sunt, et abduxerunt dilectos viduæ, et a filiis unicam desolaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 17, 'Ego autem, quid possum adjuvare vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 18, 'qui enim adduxit super vos mala, ipse vos eripiet de manibus inimicorum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 19, 'Ambulate, filii, ambulate: ego enim derelicta sum sola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 20, 'Exui me stola pacis, indui autem me sacco obsecrationis, et clamabo ad Altissimum in diebus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 21, 'Animæquiores estote, filii; clamate ad Dominum, et eripiet vos de manu principum inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 22, 'Ego enim speravi in æternum salutem vestram, et venit mihi gaudium a Sancto, super misericordia quæ veniet vobis ab æterno salutari nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 23, 'Emisi enim vos cum luctu et ploratu: reducet autem vos mihi Dominus cum gaudio et jucunditate in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 24, 'Sicut enim viderunt vicinæ Sion captivitatem vestram a Deo, sic videbunt et in celeritate salutem vestram a Deo, quæ superveniet vobis cum honore magno et splendore æterno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 25, 'Filii, patienter sustinete iram quæ supervenit vobis: persecutus est enim te inimicus tuus: sed cito videbis perditionem ipsius, et super cervices ipsius ascendes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 26, 'Delicati mei ambulaverunt vias asperas: ducti sunt enim ut grex direptus ab inimicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 27, 'Animæquiores estote, filii, et proclamate ad Dominum: erit enim memoria vestra ab eo qui duxit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 28, 'Sicut enim fuit sensus vester ut erraretis a Deo, decies tantum iterum convertentes requiretis eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 29, 'qui enim induxit vobis mala, ipse rursum adducet vobis sempiternam jucunditatem cum salute vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 30, 'Animæquior esto, Jerusalem: exhortatur enim te, qui te nominavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 31, 'Nocentes peribunt, qui te vexaverunt: et qui gratulati sunt in tua ruina, punientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 32, 'Civitates quibus servierunt filii tui, punientur, et quæ accepit filios tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 33, 'Sicut enim gavisa est in tua ruina, et lætata est in casu tuo, sic contristabitur in sua desolatione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 34, 'et amputabitur exsultatio multitudinis ejus, et gaudimonium ejus erit in luctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 35, 'Ignis enim superveniet ei ab \'terno in longiturnis diebus, et habitabitur a dæmoniis in multitudine temporis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 36, 'Circumspice, Jerusalem, ad orientem, et vide jucunditatem a Deo tibi venientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 37, 'Ecce enim veniunt filii tui, quos dimisisti dispersos: veniunt collecti ab oriente usque ad occidentem, in verbo Sancti, gaudentes in honorem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Exue te, Jerusalem, stola luctus et vexationis tuæ, et indue te decore, et honore ejus, quæ a Deo tibi est, sempiternæ gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Circumdabit te Deus diploide justitiæ, et imponet mitram capiti honoris æterni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Deus enim ostendet splendorem suum in te, omni qui sub cælo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Nominabitur enim tibi nomen tuum a Deo in sempiternum: pax justitiæ, et honor pietatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Exsurge, Jerusalem, et sta in excelso: et circumspice ad orientem, et vide collectos filios tuos ab oriente sole usque ad occidentem, in verbo Sancti, gaudentes Dei memoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Exierunt enim abs te pedibus ducti ab inimicis: adducet autem illos Dominus ad te portatos in honore sicut filios regni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'constituit enim Deus humiliare omnem montem excelsum et rupes perennes, et convalles replere in æqualitatem terræ, ut ambulet Israël diligenter in honorem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Obumbraverunt autem et silvæ, et omne lignum suavitatis Israël ex mandato Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Adducet enim Deus Israël cum jucunditate in lumine majestatis suæ, cum misericordia et justitia quæ est ex ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Propter peccata quæ peccastis ante Deum, abducemini in Babyloniam captivi a Nabuchodonosor rege Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Ingressi itaque in Babylonem, eritis ibi annis plurimis, et temporibus longis, usque ad generationes septem: post hoc autem educam vos inde cum pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Nunc autem videbitis in Babylonia deos aureos et argenteos, et lapideos et ligneos, in humeris portari, ostentantes metum gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Videte ergo ne et vos similes efficiamini factis alienis, et metuatis, et metus vos capiat in ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Visa itaque turba de retro et ab ante, adorantes dicite in cordibus vestris: Te oportet adorari, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Angelus enim meus vobiscum est: ipse autem exquiram animas vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Nam lingua ipsorum polita a fabro; ipsa etiam inaurata et inargentata: falsa sunt, et non possunt loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Et sicut virgini amanti ornamenta, ita accepto auro fabricati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Coronas certe aureas habent super capita sua dii illorum: unde subtrahunt sacerdotes ab eis aurum et argentum, et erogant illud in semetipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Dant autem et ex ipso prostitutis, et meretrices ornant: et iterum cum receperint illud a meretricibus, ornant deos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Hi autem non liberantur ab ærugine et tinea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Opertis autem illis veste purpurea, extergunt faciem ipsorum propter pulverem domus qui est plurimus inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Sceptrum autem habet ut homo, sicut judex regionis, qui in se peccantem non interficit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Habet etiam in manu gladium et securim, se autem de bello et a latronibus non liberat. Unde vobis notum sit quia non sunt dii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 15, 'non ergo timueritis eos. Sicut enim vas hominis confractum inutile efficitur, tales sunt et dii illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 16, 'Constitutis illis in domo, oculi eorum pleni sunt pulvere a pedibus introëuntium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 17, 'Et sicut alicui qui regem offendit circumseptæ sunt januæ, aut sicut ad sepulchrum adductum mortuum: ita tutantur sacerdotes ostia clausuris et seris, ne a latronibus expolientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 18, 'Lucernas accendunt illis, et quidem multas, ex quibus nullam videre possunt: sunt autem sicut trabes in domo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 19, 'Corda vero eorum dicunt elingere serpentes qui de terra sunt, dum comedunt eos, et vestimentum ipsorum, et non sentiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 20, 'Nigræ fiunt facies eorum a fumo qui in domo fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 21, 'Supra corpus eorum et supra caput eorum volant noctuæ, et hirundines, et aves etiam, similiter et cattæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 22, 'Unde sciatis quia non sunt dii: ne ergo timueritis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 23, 'Aurum etiam quod habent ad speciem est: nisi aliquis exterserit æruginem, non fulgebunt: neque enim dum conflarentur, sentiebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 24, 'Ex omni pretio empta sunt, in quibus spiritus non inest ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 25, 'Sine pedibus, in humeris portantur, ostentantes ignobilitatem suam hominibus: confundantur etiam qui colunt ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 26, 'Propterea si ceciderint in terram, a semetipsis non consurgunt: neque si quis eum statuerit rectum, per semetipsum stabit: sed sicut mortuis munera eorum illis apponentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 27, 'Hostias illorum vendunt sacerdotes ipsorum, et abutuntur: similiter et mulieres eorum decerpentes, neque infirmo, neque mendicanti, aliquid impertiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 28, 'De sacrificiis eorum fœtæ et menstruatæ contingunt. Sciens itaque ex his quia non sunt dii, ne timeatis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 29, 'Unde enim vocantur dii? quia mulieres apponunt diis argenteis, et aureis, et ligneis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 30, 'et in domibus eorum sacerdotes sedent habentes tunicas scissas, et capita et barbam rasam, quorum capita nuda sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 31, 'Rugiunt autem clamantes contra deos suos sicut in cœna mortui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 32, 'Vestimenta eorum auferunt sacerdotes, et vestiunt uxores suas et filios suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 33, 'Neque si quid mali patiuntur ab aliquo, neque si quid boni, poterunt retribuere: neque regem constituere possunt, neque auferre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 34, 'Similiter neque dare divitias possunt, neque malum retribuere. Si quis illis votum voverit et non reddiderit, neque hoc requirunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 35, 'Hominem a morte non liberant, neque infirmum a potentiori eripiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 36, 'Hominem cæcum ad visum non restituunt; de necessitate hominem non liberabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 37, 'Viduæ non miserebuntur, neque orphanis benefacient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 38, 'Lapidibus de monte similes sunt dii illorum, lignei, et lapidei, et aurei, et argentei: qui autem colunt ea, confundentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 39, 'Quomodo ergo æstimandum est aut dicendum illos esse deos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 40, 'Adhuc enim ipsis Chaldæis non honorantibus ea: qui cum audierint mutum non posse loqui, offerunt illud ad Bel, postulantes ab eo loqui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 41, 'quasi possint sentire qui non habent motum! Et ipsi, cum intellexerint, relinquent ea: sensum enim non habent ipsi dii illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 42, 'Mulieres autem circumdatæ funibus in viis sedent, succendentes ossa olivarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 43, 'cum autem aliqua ex ipsis, attracta ab aliquo transeunte, dormierit cum eo, proximæ suæ exprobrat quod ea non sit digna habita, sicut ipsa, neque funis ejus diruptus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 44, 'Omnia autem quæ illi fiunt, falsa sunt: quomodo æstimandum aut dicendum est illos esse deos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 45, 'A fabris autem et ab aurificibus facta sunt: nihil aliud erunt, nisi id quod volunt esse sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 46, 'Artifices etiam ipsi, qui ea faciunt, non sunt multi temporis: numquid ergo possunt ea, quæ fabricata sunt ab ipsis, esse dii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 47, 'Reliquerunt autem falsa et opprobrium postea futuris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 48, 'Nam cum supervenerit illis prælium et mala, cogitant sacerdotes apud se ubi se abscondant cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 49, 'Quomodo ergo sentiri debeant quoniam dii sunt, qui nec de bello se liberant, neque de malis se eripiunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 50, 'Nam cum sint lignea, inaurata et inargentata, scietur postea quia falsa sunt ab universis gentibus et regibus: quæ manifesta sunt quia non sunt dii, sed opera manuum hominum, et nullum Dei opus cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 51, 'Unde ergo notum est quia non sunt dii, sed opera manuum hominum, et nullum Dei opus in ipsis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 52, 'Regem regioni non suscitant, neque pluviam hominibus dabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 53, 'Judicium quoque non discernent, neque regiones liberabunt ab injuria, quia nihil possunt, sicut corniculæ inter medium cæli et terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 54, 'Etenim cum inciderit ignis in domum deorum ligneorum, argenteorum et aureorum, sacerdotes quidem ipsorum fugient, et liberabuntur: ipsi vero sicut trabes in medio comburentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 55, 'Regi autem et bello non resistent. Quomodo ergo æstimandum est aut recipiendum quia dii sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 56, 'Non a furibus, neque a latronibus se liberabunt dii lignei, et lapidei, et inaurati, et inargentati: quibus hi qui fortiores sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 57, 'aurum et argentum, et vestimentum quo operti sunt, auferent illis, et abibunt, nec sibi auxilium ferent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 58, 'Itaque melius est esse regem ostentantem virtutem suam, aut vas in domo utile, in quo gloriabitur qui possidet illud, vel ostium in domo, quod custodit quæ in ipsa sunt, quam falsi dii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 59, 'Sol quidem et luna ac sidera, cum sint splendida et emissa ad utilitates, obaudiunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 60, 'similiter et fulgur cum apparuerit, perspicuum est: idipsum autem et spiritus in omni regione spirat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 61, 'et nubes, quibus cum imperatum fuerit a Deo perambulare universum orbem, perficiunt quod imperatum est eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 62, 'ignis etiam missus desuper, ut consumat montes et silvas, facit quod præceptum est ei: hæc autem neque speciebus, neque virtutibus, uni eorum similia sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 63, 'Unde neque existimandum est, neque dicendum illos esse deos, quando non possunt neque judicium judicare, neque quidquam facere hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 64, 'Scientes itaque quia non sunt dii, ne ergo timueritis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 65, 'Neque enim regibus maledicent, neque benedicent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 66, 'Signa etiam in cælo gentibus non ostendunt: neque ut sol lucebunt, neque illuminabunt ut luna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 67, 'Bestiæ meliores sunt illis, quæ possunt fugere sub tectum ac prodesse sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 68, 'Nullo itaque modo nobis est manifestum quia sunt dii: propter quod ne timeatis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 69, 'Nam sicut in cucumerario formido nihil custodit, ita sunt dii illorum lignei, et argentei, et inaurati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 70, 'Eodem modo et in horto spina alba, supra quam omnis avis sedet, similiter et mortuo projecto in tenebris, similes sunt dii illorum lignei, et inaurati, et inargentati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 71, 'A purpura quoque et murice, quæ supra illos tineant, scietis itaque quia non sunt dii: ipsi etiam postremo comeduntur, et erunt opprobrium in regione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 72, 'Melior est homo justus qui non habet simulacra, nam erit longe ab opprobriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Et factum est in trigesimo anno, in quarto, in quinta mensis, cum essem in medio captivorum juxta fluvium Chobar, aperti sunt cæli, et vidi visiones Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'In quinta mensis, ipse est annus quintus transmigrationis regis Joachin,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'factum est verbum Domini ad Ezechielem filium Buzi sacerdotem, in terra Chaldæorum, secus flumen Chobar: et facta est super eum ibi manus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Et vidi, et ecce ventus turbinis veniebat ab aquilone, et nubes magna, et ignis involvens, et splendor in circuitu ejus: et de medio ejus, quasi species electri, id est, de medio ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'et in medio ejus similitudo quatuor animalium. Et hic aspectus eorum, similitudo hominis in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Quatuor facies uni, et quatuor pennæ uni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Pedes eorum, pedes recti, et planta pedis eorum quasi planta pedis vituli: et scintillæ quasi aspectus æris candentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Et manus hominis sub pennis eorum, in quatuor partibus: et facies et pennas per quatuor partes habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Junctæque erant pennæ eorum alterius ad alterum: non revertebantur cum incederent, sed unumquodque ante faciem suam gradiebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Similitudo autem vultus eorum, facies hominis et facies leonis a dextris ipsorum quatuor, facies autem bovis a sinistris ipsorum quatuor, et facies aquilæ desuper ipsorum quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Facies eorum et pennæ eorum extentæ desuper: duæ pennæ singulorum jungebantur, et duæ tegebant corpora eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Et unumquodque eorum coram facie sua ambulabat: ubi erat impetus spiritus, illuc gradiebantur, nec revertebantur cum ambularent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Et similitudo animalium, aspectus eorum quasi carbonum ignis ardentium, et quasi aspectus lampadarum: hæc erat visio discurrens in medio animalium, splendor ignis, et de igne fulgur egrediens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Et animalia ibant et revertebantur, in similitudinem fulguris coruscantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Cumque aspicerem animalia, apparuit rota una super terram juxta animalia, habens quatuor facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Et aspectus rotarum et opus earum quasi visio maris: et una similitudo ipsarum quatuor: et aspectus earum et opera quasi sit rota in medio rotæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Per quatuor partes earum euntes ibant, et non revertebantur cum ambularent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Statura quoque erat rotis, et altitudo, et horribilis aspectus: et totum corpus oculis plenum in circuitu ipsarum quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Cumque ambularent animalia, ambulabant pariter et rotæ juxta ea: et cum elevarentur animalia de terra, elevabantur simul et rotæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Quocumque ibat spiritus, illuc, eunte spiritu, et rotæ pariter elevabantur sequentes eum: spiritus enim vitæ erat in rotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Cum euntibus ibant, et cum stantibus stabant: et cum elevatis a terra, pariter elevabantur et rotæ sequentes ea, quia spiritus vitæ erat in rotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 22, 'Et similitudo super capita animalium firmamenti, quasi aspectus crystalli horribilis, et extenti super capita eorum desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 23, 'Sub firmamento autem pennæ eorum rectæ alterius ad alterum: unumquodque duabus alis velabat corpus suum, et alterum similiter velabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 24, 'Et audiebam sonum alarum, quasi sonum aquarum multarum, quasi sonum sublimis Dei: cum ambularent, quasi sonus erat multitudinis ut sonus castrorum: cumque starent, demittebantur pennæ eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 25, 'Nam cum fieret vox super firmamentum quod erat super caput eorum, stabant, et submittebant alas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 26, 'Et super firmamentum quod erat imminens capiti eorum, quasi aspectus lapidis sapphiri similitudo throni: et super similitudinem throni similitudo quasi aspectus hominis desuper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 27, 'Et vidi quasi speciem electri, velut aspectum ignis, intrinsecus ejus per circuitum: a lumbis ejus et desuper, et a lumbis ejus usque deorsum, vidi quasi speciem ignis splendentis in circuitu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 28, 'velut aspectum arcus cum fuerit in nube in die pluviæ. Hic erat aspectus splendoris per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 1, 'Hæc visio similitudinis gloriæ Domini. Et vidi, et cecidi in faciem meam, et audivi vocem loquentis, et dixit ad me: Fili hominis, sta super pedes tuos, et loquar tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 2, 'Et ingressus est in me spiritus postquam locutus est mihi, et statuit me supra pedes meos: et audivi loquentem ad me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 3, 'et dicentem: Fili hominis, mitto ego te ad filios Israël, ad gentes apostatrices quæ recesserunt a me: ipsi et patres eorum prævaricati sunt pactum meum usque ad diem hanc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 4, 'et filii dura facie et indomabili corde sunt, ad quos ego mitto te. Et dices ad eos: Hæc dicit Dominus Deus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 5, 'si forte vel ipsi audiant, et si forte quiescant, quoniam domus exasperans est: et scient quia propheta fuerit in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 6, 'Tu ergo, fili hominis, ne timeas eos, neque sermones eorum metuas, quoniam increduli et subversores sunt tecum, et cum scorpionibus habitas. Verba eorum ne timeas, et vultus eorum ne formides, quia domus exasperans est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 7, 'Loqueris ergo verba mea ad eos, si forte audiant, et quiescant: quoniam irritatores sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 8, 'Tu autem, fili hominis, audi quæcumque loquor ad te, et noli esse exasperans, sicut domus exasperatrix est: aperi os tuum, et comede quæcumque ego do tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 2, 9, 'Et vidi: et ecce manus missa ad me, in qua erat involutus liber: et expandit illum coram me, qui erat scriptus intus et foris: et scriptæ erant in eo lamentationes, et carmen, et væ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 1, 'Et dixit ad me: Fili hominis, quodcumque inveneris, comede: comede volumen istud, et vadens loquere ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 2, 'Et aperui os meum, et cibavit me volumine illo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 3, 'et dixit ad me: Fili hominis, venter tuus comedet, et viscera tua complebuntur volumine isto quod ego do tibi. Et comedi illud, et factum est in ore meo sicut mel dulce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 4, 'Et dixit ad me: Fili hominis, vade ad domum Israël, et loqueris verba mea ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 5, 'Non enim ad populum profundi sermonis et ignotæ linguæ tu mitteris ad domum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 6, 'neque ad populos multos profundi sermonis et ignotæ linguæ, quorum non possis audire sermones: et si ad illos mittereris, ipsi audirent te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 7, 'domus autem Israël nolunt audire te, quia nolunt audire me: omnis quippe domus Israël attrita fronte est, et duro corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 8, 'Ecce dedi faciem tuam valentiorem faciebus eorum, et frontem tuam duriorem frontibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 9, 'ut adamantem et ut silicem dedi faciem tuam: ne timeas eos, neque metuas a facie eorum, quia domus exasperans est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 10, 'Et dixit ad me: Fili hominis, omnes sermones meos quos ego loquor ad te, assume in corde tuo, et auribus tuis audi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 11, 'et vade, ingredere ad transmigrationem, ad filios populi tui, et loqueris ad eos: et dices eis: Hæc dicit Dominus Deus: si forte audiant et quiescant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 12, 'Et assumpsit me spiritus, et audivi post me vocem commotionis magnæ: Benedicta gloria Domini de loco suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 13, 'et vocem alarum animalium percutientium alteram ad alteram, et vocem rotarum sequentium animalia, et vocem commotionis magnæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 14, 'Spiritus quoque levavit me, et assumpsit me: et abii amarus in indignatione spiritus mei: manus enim Domini erat mecum, confortans me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 15, 'Et veni ad transmigrationem, ad acervum novarum frugum, ad eos qui habitabant juxta flumen Chobar: et sedi ubi illi sedebant, et mansi ibi septem diebus mœrens in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 16, 'Cum autem pertransissent septem dies, factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 17, 'Fili hominis, speculatorem dedi te domui Israël, et audies de ore meo verbum, et annuntiabis eis ex me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 18, 'Si, dicente me ad impium: Morte morieris, non annuntiaveris ei, neque locutus fueris ut avertatur a via sua impia et vivat, ipse impius in iniquitate sua morietur, sanguinem autem ejus de manu tua requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 19, 'Si autem tu annuntiaveris impio, et ille non fuerit conversus ab impietate sua et a via sua impia, ipse quidem in iniquitate sua morietur: tu autem animam tuam liberasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 20, 'Sed et si conversus justus a justitia sua fuerit, et fecerit iniquitatem, ponam offendiculum coram eo: ipse morietur quia non annuntiasti ei. In peccato suo morietur, et non erunt in memoria justitiæ ejus quas fecit: sanguinem vero ejus de manu tua requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 21, 'Si autem tu annuntiaveris justo ut non peccet justus, et ille non peccaverit, vivens vivet, quia annuntiasti ei, et tu animam tuam liberasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 22, 'Et facta est super me manus Domini, et dixit ad me: Surgens egredere in campum, et ibi loquar tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 23, 'Et surgens egressus sum in campum: et ecce ibi gloria Domini stabat, quasi gloria quam vidi juxta fluvium Chobar: et cecidi in faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 24, 'Et ingressus est in me spiritus, et statuit me super pedes meos, et locutus est mihi, et dixit ad me: Ingredere, et includere in medio domus tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 25, 'Et tu, fili hominis, ecce data sunt super te vincula, et ligabunt te in eis, et non egredieris de medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 26, 'Et linguam tuam adhærere faciam palato tuo, et eris mutus, nec quasi vir objurgans, quia domus exasperans est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 3, 27, 'Cum autem locutus fuero tibi, aperiam os tuum, et dices ad eos: Hæc dicit Dominus Deus: Qui audit, audiat, et qui quiescit, quiescat: quia domus exasperans est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 1, 'Et tu, fili hominis, sume tibi laterem, et pones eum coram te, et describes in eo civitatem Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 2, 'Et ordinabis adversus eam obsidionem, et ædificabis munitiones, et comportabis aggerem, et dabis contra eam castra, et pones arietes in gyro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 3, 'Et tu sume tibi sartaginem ferream, et pones eam in murum ferreum inter te et inter civitatem: et obfirmabis faciem tuam ad eam, et erit in obsidionem, et circumdabis eam: signum est domui Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 4, 'Et tu dormies super latus tuum sinistrum, et pones iniquitates domus Israël super eo, numero dierum quibus dormies super illud: et assumes iniquitatem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 5, 'Ego autem dedi tibi annos iniquitatis eorum, numero dierum trecentos et nonaginta dies: et portabis iniquitatem domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 6, 'Et cum compleveris hæc, dormies super latus tuum dexterum secundo, et assumes iniquitatem domus Juda quadraginta diebus: diem pro anno, diem, inquam, pro anno, dedi tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 7, 'Et ad obsidionem Jerusalem convertes faciem tuam, et brachium tuum erit extentum: et prophetabis adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 8, 'Ecce circumdedi te vinculis: et non te convertes a latere tuo in latus aliud, donec compleas dies obsidionis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 9, 'Et tu, sume tibi frumentum, et hordeum, et fabam, et lentem, et milium, et viciam: et mittes ea in vas unum, et facies tibi panes numero dierum quibus dormies super latus tuum: trecentis et nonaginta diebus comedes illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 10, 'Cibus autem tuus, quo vesceris, erit in pondere viginti stateres in die: a tempore usque ad tempus comedes illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 11, 'Et aquam in mensura bibes, sextam partem hin: a tempore usque ad tempus bibes illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 12, 'Et quasi subcinericium hordeaceum comedes illud, et stercore quod egreditur de homine operies illud in oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 13, 'Et dixit Dominus: Sic comedent filii Israël panem suum pollutum inter gentes ad quas ejiciam eos. Et dixi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 14, 'A, a, a, Domine Deus, ecce anima mea non est polluta: et morticinum, et laceratum a bestiis non comedi ab infantia mea usque nunc, et non est ingressa in os meum omnis caro immunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 15, 'Et dixit ad me: Ecce dedi tibi fimum boum pro stercoribus humanis, et facies panem tuum in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 16, 'Et dixit ad me: Fili hominis, ecce ego conteram baculum panis in Jerusalem, et comedent panem in pondere et in sollicitudine, et aquam in mensura et in angustia bibent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 4, 17, 'ut deficientibus pane et aqua, corruat unusquisque ad fratrem suum, et contabescant in iniquitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 1, 'Et tu, fili hominis, sume tibi gladium acutum, radentem pilos, et assumes eum et duces per caput tuum et per barbam tuam, et assumes tibi stateram ponderis et divides eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 2, 'Tertiam partem igni combures in medio civitatis, juxta completionem dierum obsidionis, et assumes tertiam partem, et concides gladio in circuitu ejus: tertiam vero aliam disperges in ventum, et gladium nudabo post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 3, 'Et sumes inde parvum numerum, et ligabis eos in summitate pallii tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 4, 'et ex eis rursum tolles, et projicies eos in medio ignis, et combures eos igni, et ex eo egredietur ignis in omnem domum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 5, 'Hæc dicit Dominus Deus: Ista est Jerusalem: in medio gentium posui eam, et in circuitu ejus terras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 6, 'Et contempsit judicia mea, ut plus esset impia quam gentes, et præcepta mea ultra quam terræ quæ in circuitu ejus sunt: judicia enim mea projecerunt, et in præceptis meis non ambulaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 7, 'Idcirco hæc dicit Dominus Deus: Quia superastis gentes quæ in circuitu vestro sunt, et in præceptis meis non ambulastis, et judicia mea non fecistis, et juxta judicia gentium quæ in circuitu vestro sunt non estis operati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 8, 'ideo hæc dicit Dominus Deus: Ecce ego ad te, et ipse ego faciam in medio tui judicia in oculis gentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 9, 'et faciam in te quod non feci, et quibus similia ultra non faciam, propter omnes abominationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 10, 'Ideo patres comedent filios in medio tui, et filii comedent patres suos: et faciam in te judicia, et ventilabo universas reliquias tuas in omnem ventum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 11, 'Idcirco vivo ego, dicit Dominus Deus, nisi pro eo quod sanctum meum violasti in omnibus offensionibus tuis et in cunctis abominationibus tuis, ego quoque confringam: et non parcet oculus meus, et non miserebor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 12, 'Tertia pars tui peste morietur, et fame consumetur in medio tui, et tertia pars tui in gladio cadet in circuitu tuo: tertiam vero partem tuam in omnem ventum dispergam, et gladium evaginabo post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 13, 'Et complebo furorem meum, et requiescere faciam indignationem meam in eis, et consolabor: et scient quia ego Dominus locutus sum in zelo meo, cum implevero indignationem meam in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 14, 'Et dabo te in desertum, et in opprobrium gentibus quæ in circuitu tuo sunt, in conspectu omnis prætereuntis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 15, 'et eris opprobrium et blasphemia, exemplum et stupor in gentibus quæ in circuitu tuo sunt, cum fecero in te judicia in furore, et in indignatione, et in increpationibus iræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 16, 'Ego Dominus locutus sum: quando misero sagittas famis pessimas in eos, quæ erunt mortiferæ, et quas mittam ut disperdam vos: et famem congregabo super vos, et conteram in vobis baculum panis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 5, 17, 'et immittam in vos famem et bestias pessimas, usque ad internecionem: et pestilentia et sanguis transibunt per te, et gladium inducam super te. Ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 2, 'Fili hominis, pone faciem tuam ad montes Israël, et prophetabis ad eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 3, 'et dices: Montes Israël, audite verbum Domini Dei. Hæc dicit Dominus Deus montibus et collibus, rupibus et vallibus: Ecce ego inducam super vos gladium, et disperdam excelsa vestra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 4, 'et demoliar aras vestras, et confringentur simulacra vestra, et dejiciam interfectos vestros ante idola vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 5, 'et dabo cadavera filiorum Israël ante faciem simulacrorum vestrorum, et dispergam ossa vestra circum aras vestras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 6, 'in omnibus habitationibus vestris urbes desertæ erunt, et excelsa demolientur et dissipabuntur: et interibunt aræ vestræ, et confringentur, et cessabunt idola vestra, et conterentur delubra vestra, et delebuntur opera vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 7, 'et cadet interfectus in medio vestri, et scietis quia ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 8, 'Et relinquam in vobis eos qui fugerint gladium in gentibus, cum dispersero vos in terris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 9, 'et recordabuntur mei liberati vestri in gentibus ad quas captivi ducti sunt: quia contrivi cor eorum fornicans et recedens a me, et oculos eorum fornicantes post idola sua: et displicebunt sibimet super malis quæ fecerunt in universis abominationibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 10, 'Et scient quia ego Dominus non frustra locutus sum, ut facerem eis malum hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 11, 'Hæc dicit Dominus Deus: Percute manum tuam et allide pedem tuum, et dic: Heu! ad omnes abominationes malorum domus Israël: quia gladio, fame et peste ruituri sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 12, 'Qui longe est, peste morietur: qui autem prope, gladio corruet: et qui relictus fuerit et obsessus, fame morietur: et complebo indignationem meam in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 13, 'Et scietis quia ego Dominus, cum fuerint interfecti vestri in medio idolorum vestrorum, in circuitu ararum vestrarum, in omni colle excelso, et in cunctis summitatibus montium, et subtus omne lignum nemorosum, et subtus universam quercum frondosam, locum ubi accenderunt thura redolentia universis idolis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 6, 14, 'Et extendam manum meam super eos: et faciam terram desolatam et destitutam, a deserto Deblatha, in omnibus habitationibus eorum: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 2, 'Et tu, fili hominis, hæc dicit Dominus Deus terræ Israël: Finis venit: venit finis super quatuor plagas terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 3, 'Nunc finis super te, et immittam furorem meum in te: et judicabo te juxta vias tuas, et ponam contra te omnes abominationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 4, 'Et non parcet oculus meus super te, et non miserebor: sed vias tuas ponam super te, et abominationes tuæ in medio tui erunt, et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 5, 'Hæc dicit Dominus Deus: Afflictio una, afflictio ecce venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 6, 'Finis venit, venit finis: evigilavit adversum te, ecce venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 7, 'Venit contritio super te, qui habitas in terra: venit tempus, prope est dies occisionis, et non gloriæ montium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 8, 'Nunc de propinquo effundam iram meam super te, et complebo furorem meum in te: et judicabo te juxta vias tuas, et imponam tibi omnia scelera tua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 9, 'et non parcet oculus meus, nec miserebor: sed vias tuas imponam tibi, et abominationes tuæ in medio tui erunt, et scietis quia ego sum Dominus percutiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 10, 'Ecce dies, ecce venit: egressa est contritio, floruit virga, germinavit superbia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 11, 'iniquitas surrexit in virga impietatis: non ex eis, et non ex populo, neque ex sonitu eorum: et non erit requies in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 12, 'Venit tempus, appropinquavit dies: qui emit, non lætetur, et qui vendit, non lugeat: quia ira super omnem populum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 13, 'Quia qui vendit, ad id quod vendidit non revertetur: et adhuc in viventibus vita eorum: visio enim ad omnem multitudinem ejus non regredietur, et vir in iniquitate vitæ suæ non confortabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 14, 'Canite tuba, præparentur omnes: et non est qui vadat ad prælium: ira enim mea super universum populum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 15, 'Gladium foris, et pestis et fames intrinsecus: qui in agro est, gladio morietur, et qui in civitate, pestilentia et fame devorabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 16, 'Et salvabuntur qui fugerint ex eis: et erunt in montibus quasi columbæ convallium omnes trepidi, unusquisque in iniquitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 17, 'Omnes manus dissolventur, et omnia genua fluent aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 18, 'Et accingent se ciliciis, et operiet eos formido: et in omni facie confusio, et in universis capitibus eorum calvitium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 19, 'Argentum eorum foras projicietur, et aurum eorum in sterquilinium erit: argentum eorum et aurum eorum non valebit liberare eos in die furoris Domini: animam suam non saturabunt, et ventres eorum non implebuntur, quia scandalum iniquitatis eorum factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 20, 'Et ornamentum monilium suorum in superbiam posuerunt, et imagines abominationum suarum et simulacrorum fecerunt ex eo: propter hoc dedi eis illud in immunditiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 21, 'Et dabo illud in manus alienorum ad diripiendum, et impiis terræ in prædam, et contaminabunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 22, 'Et avertam faciem meam ab eis, et violabunt arcanum meum: et introibunt in illud emissarii, et contaminabunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 23, 'Fac conclusionem, quoniam terra plena est judicio sanguinum, et civitas plena iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 24, 'Et adducam pessimos de gentibus, et possidebunt domos eorum: et quiescere faciam superbiam potentium, et possidebunt sanctuaria eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 25, 'Angustia superveniente, requirent pacem, et non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 26, 'Conturbatio super conturbationem veniet, et auditus super auditum: et quærent visionem de propheta, et lex peribit a sacerdote, et consilium a senioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 7, 27, 'Rex lugebit, et princeps induetur mœrore, et manus populi terræ conturbabuntur: secundum viam eorum faciam eis, et secundum judicia eorum judicabo eos, et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 1, 'Et factum est in anno sexto, in sexto mense, in quinta mensis, ego sedebam in domo mea, et senes Juda sedebant coram me, et cecidit ibi super me manus Domini Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 2, 'Et vidi: et ecce similitudo quasi aspectus ignis: ab aspectu lumborum ejus et deorsum, ignis: et a lumbis ejus et sursum, quasi aspectus splendoris, ut visio electri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 3, 'Et emissa similitudo manus apprehendit me in cincinno capitis mei, et elevavit me spiritus inter terram et cælum: et adduxit me in Jerusalem, in visione Dei, juxta ostium interius quod respiciebat ad aquilonem, ubi erat statutum idolum zeli ad provocandam æmulationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 4, 'Et ecce ibi gloria Dei Israël, secundum visionem quam videram in campo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 5, 'Et dixit ad me: Fili hominis, leva oculos tuos ad viam aquilonis. Et levavi oculos meos ad viam aquilonis, et ecce ab aquilone portæ altaris idolum zeli in ipso introitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 6, 'Et dixit ad me: Fili hominis, putasne vides tu quid isti faciunt, abominationes magnas quas domus Israël facit hic, ut procul recedam a sanctuario meo? et adhuc conversus videbis abominationes majores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 7, 'Et introduxit me ad ostium atrii, et vidi, et ecce foramen unum in pariete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 8, 'Et dixit ad me: Fili hominis, fode parietem. Et cum fodissem parietem, apparuit ostium unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 9, 'Et dixit ad me: Ingredere, et vide abominationes pessimas quas isti faciunt hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 10, 'Et ingressus vidi, et ecce omnis similitudo reptilium et animalium, abominatio, et universa idola domus Israël, depicta erant in pariete in circuitu per totum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 11, 'et septuaginta viri de senioribus domus Israël: et Jezonias filius Saphan stabat in medio eorum stantium ante picturas: et unusquisque habebat thuribulum in manu sua, et vapor nebulæ de thure consurgebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 12, 'Et dixit ad me: Certe vides, fili hominis, quæ seniores domus Israël faciunt in tenebris, unusquisque in abscondito cubiculi sui: dicunt enim: Non videt Dominus nos; dereliquit Dominus terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 13, 'Et dixit ad me: Adhuc conversus videbis abominationes majores, quas isti faciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 14, 'Et introduxit me per ostium portæ domus Domini quod respiciebat ad aquilonem, et ecce ibi mulieres sedebant plangentes Adonidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 15, 'Et dixit ad me: Certe vidisti, fili hominis: adhuc conversus videbis abominationes majores his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 16, 'Et introduxit me in atrium domus Domini interius, et ecce in ostio templi Domini, inter vestibulum et altare, quasi viginti quinque viri dorsa habentes contra templum Domini, et facies ad orientem: et adorabant ad ortum solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 17, 'Et dixit ad me: Certe vidisti, fili hominis: numquid leve est hoc domui Juda, ut facerent abominationes istas quas fecerunt hic, quia replentes terram iniquitate, conversi sunt ad irritandum me? et ecce applicant ramum ad nares suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 8, 18, 'Ergo et ego faciam in furore: non parcet oculus meus, nec miserebor: et cum clamaverint ad aures meas voce magna, non exaudiam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 1, 'Et clamavit in auribus meis voce magna, dicens: Appropinquaverunt visitationes urbis, et unusquisque vas interfectionis habet in manu sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 2, 'Et ecce sex viri veniebant de via portæ superioris, quæ respicit ad aquilonem, et uniuscujusque vas interitus in manu ejus: vir quoque unus in medio eorum vestitus erat lineis, et atramentarium scriptoris ad renes ejus: et ingressi sunt, et steterunt juxta altare æreum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 3, 'Et gloria Domini Israël assumpta est de cherub, quæ erat super eum ad limen domus: et vocavit virum qui indutus erat lineis, et atramentarium scriptoris habebat in lumbis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 4, 'et dixit Dominus ad eum: Transi per mediam civitatem, in medio Jerusalem, et signa thau super frontes virorum gementium et dolentium super cunctis abominationibus quæ fiunt in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 5, 'Et illis dixit, audiente me: Transite per civitatem sequentes eum, et percutite: non parcat oculus vester, neque misereamini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 6, 'senem, adolescentulum et virginem, parvulum et mulieres interficite usque ad internecionem: omnem autem super quem videritis thau, ne occidatis: et a sanctuario meo incipite. Cœperunt ergo a viris senioribus, qui erant ante faciem domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 7, 'Et dixit ad eos: Contaminate domum, et implete atria interfectis; egredimini. Et egressi sunt, et percutiebant eos qui erant in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 8, 'Et cæde completa, remansi ego, ruique super faciem meam, et clamans aio: Heu! heu! heu! Domine Deus: ergone disperdes omnes reliquias Israël, effundens furorem tuum super Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 9, 'Et dixit ad me: Iniquitas domus Israël et Juda magna est nimis valde, et repleta est terra sanguinibus, et civitas repleta est aversione: dixerunt enim: Dereliquit Dominus terram, et Dominus non videt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 10, 'Igitur et meus non parcet oculus, neque miserebor: viam eorum super caput eorum reddam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 9, 11, 'Et ecce vir qui erat indutus lineis, qui habebat atramentarium in dorso suo, respondit verbum, dicens: Feci sicut præcepisti mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 1, 'Et vidi: et ecce in firmamento quod erat super caput cherubim, quasi lapis sapphirus, quasi species similitudinis solii, apparuit super ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 2, 'Et dixit ad virum qui indutus erat lineis, et ait: Ingredere in medio rotarum quæ sunt subtus cherubim, et imple manum tuam prunis ignis quæ sunt inter cherubim, et effunde super civitatem. Ingressusque est in conspectu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 3, 'Cherubim autem stabant a dextris domus cum ingrederetur vir, et nubes implevit atrium interius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 4, 'Et elevata est gloria Domini desuper cherub ad limen domus: et repleta est domus nube, et atrium repletum est splendore gloriæ Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 5, 'Et sonitus alarum cherubim audiebatur usque ad atrium exterius, quasi vox Dei omnipotentis loquentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 6, 'Cumque præcepisset viro qui indutus erat lineis, dicens: Sume ignem de medio rotarum quæ sunt inter cherubim: ingressus ille stetit juxta rotam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 7, 'Et extendit cherub manum de medio cherubim ad ignem qui erat inter cherubim, et sumpsit, et dedit in manus ejus qui indutus erat lineis: qui accipiens egressus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 8, 'Et apparuit in cherubim similitudo manus hominis subtus pennas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 9, 'Et vidi: et ecce quatuor rotæ juxta cherubim: rota una juxta cherub unum, et rota alia juxta cherub unum: species autem rotarum erat quasi visio lapidis chrysolithi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 10, 'et aspectus earum similitudo una quatuor, quasi sit rota in medio rotæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 11, 'Cumque ambularent, in quatuor partes gradiebantur, et non revertebantur ambulantes: sed ad locum ad quem ire declinabat quæ prima erat, sequebantur et ceteræ, nec convertebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 12, 'Et omne corpus earum, et colla, et manus, et pennæ, et circuli, plena erant oculis in circuitu quatuor rotarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 13, 'Et rotas istas vocavit volubiles, audiente me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 14, 'Quatuor autem facies habebat unum: facies una, facies cherub, et facies secunda, facies hominis: et in tertio facies leonis, et in quarto facies aquilæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 15, 'Et elevata sunt cherubim: ipsum est animal quod videram juxta fluvium Chobar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 16, 'Cumque ambularent cherubim, ibant pariter et rotæ juxta ea: et cum elevarent cherubim alas suas ut exaltarentur de terra, non residebant rotæ, sed et ipsæ juxta erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 17, 'Stantibus illis stabant, et cum elevatis elevabantur: spiritus enim vitæ erat in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 18, 'Et egressa est gloria Domini a limine templi, et stetit super cherubim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 19, 'Et elevantia cherubim alas suas, exaltata sunt a terra coram me: et illis egredientibus, rotæ quoque subsecutæ sunt: et stetit in introitu portæ domus Domini orientalis, et gloria Dei Israël erat super ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 20, 'Ipsum est animal quod vidi subter Deum Israël juxta fluvium Chobar, et intellexi quia cherubim essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 21, 'Quatuor vultus uni, et quatuor alæ uni: et similitudo manus hominis sub alis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 10, 22, 'Et similitudo vultuum eorum, ipsi vultus quos videram juxta fluvium Chobar, et intuitus eorum, et impetus singulorum ante faciem suam ingredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 1, 'Et elevavit me spiritus, et introduxit me ad portam domus Domini orientalem, quæ respicit ad solis ortum: et ecce in introitu portæ viginti quinque viri: et vidi in medio eorum Jezoniam filium Azur, et Pheltiam filium Banaiæ, principes populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 2, 'Dixitque ad me: Fili hominis, hi sunt viri qui cogitant iniquitatem, et tractant consilium pessimum in urbe ista,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 3, 'dicentes: Nonne dudum ædificatæ sunt domus? hæc est lebes, nos autem carnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 4, 'Idcirco vaticinare de eis, vaticinare, fili hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 5, 'Et irruit in me spiritus Domini, et dixit ad me: Loquere: Hæc dicit Dominus: Sic locuti estis, domus Israël, et cogitationes cordis vestri ego novi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 6, 'Plurimos occidistis in urbe hac, et implestis vias ejus interfectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 7, 'Propterea hæc dicit Dominus Deus: Interfecti vestri, quos posuistis in medio ejus, hi sunt carnes, et hæc est lebes: et educam vos de medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 8, 'Gladium metuistis, et gladium inducam super vos, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 9, 'Et ejiciam vos de medio ejus, daboque vos in manu hostium, et faciam in vobis judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 10, 'Gladio cadetis: in finibus Israël judicabo vos, et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 11, 'Hæc non erit vobis in lebetem, et vos non eritis in medio ejus in carnes: in finibus Israël judicabo vos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 12, 'et scietis quia ego Dominus: quia in præceptis meis non ambulastis, et judicia mea non fecistis, sed juxta judicia gentium quæ in circuitu vestro sunt estis operati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 13, 'Et factum est cum prophetarem, Pheltias filius Banaiæ mortuus est: et cecidi in faciem meam clamans voce magna, et dixi: Heu! heu! heu! Domine Deus, consummationem tu facis reliquiarum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 14, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 15, 'Fili hominis, fratres tui, fratres tui, viri propinqui tui, et omnis domus Israël, universi quibus dixerunt habitatores Jerusalem: Longe recedite a Domino: nobis data est terra in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 16, 'Propterea hæc dicit Dominus Deus: Quia longe feci eos in gentibus, et quia dispersi eos in terris: ero eis in sanctificationem modicam in terris ad quas venerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 17, 'Propterea loquere: Hæc dicit Dominus Deus: Congregabo vos de populis, et adunabo de terris in quibus dispersi estis, daboque vobis humum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 18, 'Et ingredientur illuc, et auferent omnes offensiones, cunctasque abominationes ejus de illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 19, 'Et dabo eis cor unum, et spiritum novum tribuam in visceribus eorum: et auferam cor lapideum de carne eorum, et dabo eis cor carneum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 20, 'ut in præceptis meis ambulent, et judicia mea custodiant, faciantque ea, et sint mihi in populum, et ego sim eis in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 21, 'Quorum cor post offendicula et abominationes suas ambulat, horum viam in capite suo ponam, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 22, 'Et elevaverunt cherubim alas suas, et rotæ cum eis, et gloria Dei Israël erat super ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 23, 'et ascendit gloria Domini de medio civitatis, stetitque super montem qui est ad orientem urbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 24, 'Et spiritus levavit me, adduxitque in Chaldæam ad transmigrationem, in visione, in spiritu Dei: et sublata est a me visio quam videram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 11, 25, 'Et locutus sum ad transmigrationem omnia verba Domini quæ ostenderat mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 2, 'Fili hominis, in medio domus exasperantis tu habitas: qui oculos habent ad videndum, et non vident, et aures ad audiendum, et non audiunt: quia domus exasperans est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 3, 'Tu ergo, fili hominis, fac tibi vasa transmigrationis, et transmigrabis per diem coram eis. Transmigrabis autem de loco tuo ad locum alterum in conspectu eorum, si forte aspiciant, quia domus exasperans est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 4, 'et efferes foras vasa tua quasi vasa transmigrantis per diem in conspectu eorum: tu autem egredieris vespere coram eis, sicut egreditur migrans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 5, 'Ante oculos eorum perfode tibi parietem, et egredieris per eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 6, 'In conspectu eorum in humeris portaberis; in caligine effereris: faciem tuam velabis, et non videbis terram, quia portentum dedi te domui Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 7, 'Feci ergo sicut præceperat mihi Dominus: vasa mea protuli quasi vasa transmigrantis per diem, et vespere perfodi mihi parietem manu: et in caligine egressus sum, in humeris portatus in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 8, 'Et factus est sermo Domini mane ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 9, 'Fili hominis, numquid non dixerunt ad te domus Israël, domus exasperans: Quid tu facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 10, 'Dic ad eos: Hæc dicit Dominus Deus: Super ducem onus istud, qui est in Jerusalem, et super omnem domum Israël, quæ est in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 11, 'Dic: Ego portentum vestrum: quomodo feci, sic fiet illis: in transmigrationem et in captivitatem ibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 12, 'Et dux qui est in medio eorum, in humeris portabitur; in caligine egredietur: parietem perfodient, ut educant eum; facies ejus operietur, ut non videat oculo terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 13, 'Et extendam rete meum super eum, et capietur in sagena mea: et adducam eum in Babylonem, in terram Chaldæorum, et ipsam non videbit: ibique morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 14, 'Et omnes qui circa eum sunt, præsidium ejus, et agmina ejus, dispergam in omnem ventum, et gladium evaginabo post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 15, 'Et scient quia ego Dominus, quando dispersero illos in gentibus, et disseminavero eos in terris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 16, 'Et relinquam ex eis viros paucos a gladio, et fame, et pestilentia, ut enarrent omnia scelera eorum in gentibus ad quas ingredientur, et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 17, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 18, 'Fili hominis, panem tuum in conturbatione comede, sed et aquam tuam in festinatione et mœrore bibe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 19, 'Et dices ad populum terræ: Hæc dicit Dominus Deus ad eos qui habitant in Jerusalem, in terra Israël: Panem suum in sollicitudine comedent, et aquam suam in desolatione bibent: ut desoletur terra a multitudine sua, propter iniquitatem omnium qui habitant in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 20, 'Et civitates quæ nunc habitantur, desolatæ erunt, terraque deserta, et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 21, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 22, 'Fili hominis, quod est proverbium istud vobis in terra Israël, dicentium: In longum differentur dies, et peribit omnis visio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 23, 'Ideo dic ad eos: Hæc dicit Dominus Deus: Quiescere faciam proverbium istud, neque vulgo dicetur ultra in Israël: et loquere ad eos quod appropinquaverint dies, et sermo omnis visionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 24, 'Non enim erit ultra omnis visio cassa, neque divinatio ambigua in medio filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 25, 'quia ego Dominus loquar, et quodcumque locutus fuero verbum, fiet, et non prolongabitur amplius: sed in diebus vestris, domus exasperans, loquar verbum, et faciam illud, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 26, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 27, 'Fili hominis, ecce domus Israël dicentium: Visio quam hic videt, in dies multos et in tempora longa iste prophetat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 12, 28, 'Propterea dic ad eos: Hæc dicit Dominus Deus: Non prolongabitur ultra omnis sermo meus: verbum quod locutus fuero, complebitur, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 2, 'Fili hominis, vaticinare ad prophetas Israël qui prophetant, et dices prophetantibus de corde suo: Audite verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 3, 'Hæc dicit Dominus Deus: Væ prophetis insipientibus, qui sequuntur spiritum suum, et nihil vident!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 4, 'Quasi vulpes in desertis prophetæ tui, Israël, erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 5, 'Non ascendistis ex adverso, neque opposuistis murum pro domo Israël, ut staretis in prælio in die Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 6, 'Vident vana, et divinant mendacium, dicentes: Ait Dominus, cum Dominus non miserit eos: et perseveraverunt confirmare sermonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 7, 'Numquid non visionem cassam vidistis, et divinationem mendacem locuti estis, et dicitis: Ait Dominus, cum ego non sim locutus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 8, 'Propterea hæc dicit Dominus Deus: Quia locuti estis vana, et vidistis mendacium, ideo ecce ego ad vos, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 9, 'Et erit manus mea super prophetas qui vident vana, et divinant mendacium: in consilio populi mei non erunt, et in scriptura domus Israël non scribentur, nec in terram Israël ingredientur, et scietis quia ego Dominus Deus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 10, 'eo quod deceperint populum meum, dicentes: Pax, et non est pax: et ipse ædificabat parietem, illi autem liniebant eum luto absque paleis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 11, 'Dic ad eos qui liniunt absque temperatura, quod casurus sit: erit enim imber inundans, et dabo lapides prægrandes desuper irruentes, et ventum procellæ dissipantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 12, 'Siquidem ecce cecidit paries: numquid non dicetur vobis: Ubi est litura quam linistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 13, 'Propterea hæc dicit Dominus Deus: Et erumpere faciam spiritum tempestatum in indignatione mea, et imber inundans in furore meo erit, et lapides grandes in ira in consumptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 14, 'Et destruam parietem quem linistis absque temperamento, et adæquabo eum terræ, et revelabitur fundamentum ejus: et cadet, et consumetur in medio ejus, et scietis quia ego sum Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 15, 'Et complebo indignationem meam in pariete, et in his qui liniunt eum absque temperamento: dicamque vobis: Non est paries, et non sunt qui liniunt eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 16, 'prophetæ Israël, qui prophetant ad Jerusalem, et vident ei visionem pacis, et non est pax, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 17, 'Et tu, fili hominis, pone faciem tuam contra filias populi tui quæ prophetant de corde suo: et vaticinare super eas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 18, 'et dic: Hæc dicit Dominus Deus: Væ quæ consuunt pulvillos sub omni cubito manus, et faciunt cervicalia sub capite universæ ætatis ad capiendas animas: et cum caperent animas populi mei, vivificabant animas eorum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 19, 'Et violabant me ad populum meum propter pugillum hordei, et fragmen panis, ut interficerent animas quæ non moriuntur, et vivificarent animas quæ non vivunt, mentientes populo meo credenti mendaciis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 20, 'Propter hoc hæc dicit Dominus Deus: Ecce ego ad pulvillos vestros, quibus vos capitis animas volantes: et dirumpam eos de brachiis vestris, et dimittam animas quas vos capitis, animas ad volandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 21, 'Et dirumpam cervicalia vestra, et liberabo populum meum de manu vestra, neque erunt ultra in manibus vestris ad prædandum: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 22, 'Pro eo quod mœrere fecistis cor justi mendaciter, quem ego non contristavi, et confortastis manus impii, ut non reverteretur a via sua mala, et viveret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 13, 23, 'propterea vana non videbitis, et divinationes non divinabitis amplius, et eruam populum meum de manu vestra: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 1, 'Et venerunt ad me viri seniorum Israël, et sederunt coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 2, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 3, 'Fili hominis, viri isti posuerunt immunditias suas in cordibus suis, et scandalum iniquitatis suæ statuerunt contra faciem suam: numquid interrogatus respondebo eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 4, 'Propter hoc loquere eis, et dices ad eos: Hæc dicit Dominus Deus: Homo, homo de domo Israël, qui posuerit immunditias suas in corde suo, et scandalum iniquitatis suæ statuerit contra faciem suam, et venerit ad prophetam interrogans per eum me: ego Dominus respondebo ei in multitudine immunditiarum suarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 5, 'ut capiatur domus Israël in corde suo, quo recesserunt a me in cunctis idolis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 6, 'Propterea dic ad domum Israël: Hæc dicit Dominus Deus: Convertimini, et recedite ab idolis vestris, et ab universis contaminationibus vestris avertite facies vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 7, 'Quia homo, homo de domo Israël, et de proselytis quicumque advena fuerit in Israël, si alienatus fuerit a me, et posuerit idola sua in corde suo, et scandalum iniquitatis suæ statuerit contra faciem suam, et venerit ad prophetam ut interroget per eum me: ego Dominus respondebo ei per me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 8, 'et ponam faciem meam super hominem illum, et faciam eum in exemplum et in proverbium, et disperdam eum de medio populi mei: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 9, 'Et propheta cum erraverit, et locutus fuerit verbum, ego Dominus decepi prophetam illum, et extendam manum meam super illum, et delebo eum de medio populi mei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 10, 'Et portabunt iniquitatem suam: juxta iniquitatem interrogantis, sic iniquitas prophetæ erit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 11, 'ut non erret ultra domus Israël a me, neque polluatur in universis prævaricationibus suis: sed sint mihi in populum, et ego sim eis in Deum, ait Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 12, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 13, 'Fili hominis, terra cum peccaverit mihi, ut prævaricetur prævaricans, extendam manum meam super eam, et conteram virgam panis ejus, et immittam in eam famem, et interficiam de ea hominem et jumentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 14, 'Et si fuerint tres viri isti in medio ejus, Noë, Daniel, et Job, ipsi justitia sua liberabunt animas suas, ait Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 15, 'Quod si et bestias pessimas induxero super terram ut vastem eam, et fuerit invia, eo quod non sit pertransiens propter bestias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 16, 'tres viri isti si fuerint in ea, vivo ego, dicit Dominus Deus, quia nec filios nec filias liberabunt, sed ipsi soli liberabuntur, terra autem desolabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 17, 'Vel si gladium induxero super terram illam, et dixero gladio: Transi per terram: et interfecero de ea hominem et jumentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 18, 'et tres viri isti fuerint in medio ejus: vivo ego, dicit Dominus Deus, non liberabunt filios neque filias, sed ipsi soli liberabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 19, 'Si autem et pestilentiam immisero super terram illam, et effudero indignationem meam super eam in sanguine, ut auferam ex ea hominem et jumentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 20, 'et Noë, et Daniel, et Job fuerint in medio ejus: vivo ego, dicit Dominus Deus, quia filium et filiam non liberabunt, sed ipsi justitia sua liberabunt animas suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 21, 'Quoniam hæc dicit Dominus Deus: Quod etsi quatuor judicia mea pessima, gladium, et famem, ac bestias malas, et pestilentiam, immisero in Jerusalem, ut interficiam de ea hominem et pecus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 22, 'tamen relinquetur in ea salvatio educentium filios et filias: ecce ipsi ingredientur ad vos, et videbitis viam eorum et adinventiones eorum, et consolabimini super malo quod induxi in Jerusalem, in omnibus quæ importavi super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 14, 23, 'Et consolabuntur vos, cum videritis viam eorum et adinventiones eorum: et cognoscetis quod non frustra fecerim omnia quæ feci in ea, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 2, 'Fili hominis, quid fiet de ligno vitis, ex omnibus lignis nemorum quæ sunt inter ligna silvarum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 3, 'numquid tolletur de ea lignum ut fiat opus, aut fabricabitur de ea paxillus ut dependeat in eo quodcumque vas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 4, 'Ecce igni datum est in escam: utramque partem ejus consumpsit ignis, et medietas ejus redacta est in favillam: numquid utile erit ad opus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 5, 'Etiam cum esset integrum, non erat aptum ad opus: quanto magis cum illud ignis devoraverit et combusserit, nihil ex eo fiet operis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 6, 'Propterea hæc dicit Dominus Deus: Quomodo lignum vitis inter ligna silvarum, quod dedi igni ad devorandum, sic tradam habitatores Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 7, 'Et ponam faciem meam in eos: de igne egredientur, et ignis consumet eos: et scietis quia ego Dominus, cum posuero faciem meam in eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 15, 8, 'et dedero terram inviam et desolatam, eo quod prævaricatores extiterint, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 2, 'Fili hominis, notas fac Jerusalem abominationes suas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 3, 'et dices: Hæc dicit Dominus Deus Jerusalem: Radix tua et generatio tua de terra Chanaan: pater tuus Amorrhæus, et mater tua Cethæa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 4, 'Et quando nata es, in die ortus tui non est præcisus umbilicus tuus, et aqua non es lota in salutem, nec sale salita, nec involuta pannis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 5, 'Non pepercit super te oculus, ut faceret tibi unum de his, misertus tui: sed projecta es super faciem terræ in abjectione animæ tuæ in die qua nata es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 6, 'Transiens autem per te, vidi te conculcari in sanguine tuo: et dixi tibi cum esses in sanguine tuo: Vive, dixi, inquam, tibi: in sanguine tuo vive.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 7, 'Multiplicatam quasi germen agri dedi te: et multiplicata es, et grandis effecta, et ingressa es, et pervenisti ad mundum muliebrem: ubera tua intumuerunt, et pilus tuus germinavit: et eras nuda, et confusione plena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 8, 'Et transivi per te, et vidi te: et ecce tempus tuum, tempus amantium: et expandi amictum meum super te, et operui ignominiam tuam: et juravi tibi, et ingressus sum pactum tecum, ait Dominus Deus, et facta es mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 9, 'Et lavi te aqua, et emundavi sanguinem tuum ex te, et unxi te oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 10, 'Et vestivi te discoloribus, et calceavi te janthino, et cinxi te bysso, et indui te subtilibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 11, 'et ornavi te ornamento, et dedi armillas in manibus tuis, et torquem circa collum tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 12, 'et dedi inaurem super os tuum, et circulos auribus tuis, et coronam decoris in capite tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 13, 'Et ornata es auro et argento, et vestita es bysso et polymito et multicoloribus: similam, et mel, et oleum comedisti: et decora facta es vehementer nimis, et profecisti in regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 14, 'Et egressum est nomen tuum in gentes propter speciem tuam, quia perfecta eras in decore meo quem posueram super te, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 15, 'Et habens fiduciam in pulchritudine tua, fornicata es in nomine tuo: et exposuisti fornicationem tuam omni transeunti, ut ejus fieres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 16, 'Et sumens de vestimentis tuis, fecisti tibi excelsa hinc inde consuta, et fornicata es super eis sicut non est factum, neque futurum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 17, 'Et tulisti vasa decoris tui de auro meo atque argento meo, quæ dedi tibi, et fecisti tibi imagines masculinas, et fornicata es in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 18, 'Et sumpsisti vestimenta tua multicoloria, et operuisti illas, et oleum meum et thymiama meum posuisti coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 19, 'Et panem meum quem dedi tibi, similam, et oleum, et mel, quibus enutrivi te, posuisti in conspectu eorum in odorem suavitatis: et factum est, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 20, 'Et tulisti filios tuos et filias tuas quas generasti mihi, et immolasti eis ad devorandum. Numquid parva est fornicatio tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 21, 'Immolasti filios meos, et dedisti, illos consecrans, eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 22, 'Et post omnes abominationes tuas et fornicationes, non es recordata dierum adolescentiæ tuæ, quando eras nuda et confusione plena, conculcata in sanguine tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 23, 'Et accidit post omnem malitiam tuam (væ, væ tibi! ait Dominus Deus),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 24, 'et ædificasti tibi lupanar, et fecisti tibi prostibulum in cunctis plateis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 25, 'Ad omne caput viæ ædificasti signum prostitutionis tuæ, et abominabilem fecisti decorem tuum: et divisisti pedes tuos omni transeunti, et multiplicasti fornicationes tuas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 26, 'et fornicata es cum filiis \'gypti, vicinis tuis, magnarum carnium: et multiplicasti fornicationem tuam ad irritandum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 27, 'Ecce ego extendam manum meam super te, et auferam justificationem tuam, et dabo te in animas odientium te filiarum Palæstinarum, quæ erubescunt in via tua scelerata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 28, 'Et fornicata es in filiis Assyriorum eo quod necdum fueris expleta: et postquam fornicata es, nec sic es satiata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 29, 'et multiplicasti fornicationem tuam in terra Chanaan cum Chaldæis, et nec sic satiata es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 30, 'In quo mundabo cor tuum, ait Dominus Deus, cum facias omnia hæc opera mulieris meretricis et procacis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 31, 'Quia fabricasti lupanar tuum in capite omnis viæ, et excelsum tuum fecisti in omni platea: nec facta es quasi meretrix fastidio augens pretium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 32, 'sed quasi mulier adultera, quæ super virum suum inducit alienos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 33, 'Omnibus meretricibus dantur mercedes: tu autem dedisti mercedes cunctis amatoribus tuis, et dona donabas eis, ut intrarent ad te undique ad fornicandum tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 34, 'Factumque est in te contra consuetudinem mulierum in fornicationibus tuis, et post te non erit fornicatio: in eo enim quod dedisti mercedes, et mercedes non accepisti, factum est in te contrarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 35, 'Propterea, meretrix, audi verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 36, 'Hæc dicit Dominus Deus: Quia effusum est æs tuum et revelata est ignominia tua in fornicationibus tuis super amatores tuos, et super idola abominationum tuarum, in sanguine filiorum tuorum quos dedisti eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 37, 'ecce ego congregabo omnes amatores tuos quibus commista es, et omnes quos dilexisti, cum universis quos oderas: et congregabo eos super te undique, et nudabo ignominiam tuam coram eis, et videbunt omnem turpitudinem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 38, 'Et judicabo te judiciis adulterarum, et effundentium sanguinem: et dabo te in sanguinem furoris et zeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 39, 'Et dabo te in manus eorum, et destruent lupanar tuum, et demolientur prostibulum tuum: et denudabunt te vestimentis tuis, et auferent vasa decoris tui, et derelinquent te nudam, plenamque ignominia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 40, 'et adducent super te multitudinem, et lapidabunt te lapidibus, et trucidabunt te gladiis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 41, 'et comburent domos tuas igni, et facient in te judicia in oculis mulierum plurimarum. Et desines fornicari, et mercedes ultra non dabis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 42, 'et requiescet indignatio mea in te, et auferetur zelus meus a te: et quiescam, nec irascar amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 43, 'Eo quod non fueris recordata dierum adolescentiæ tuæ, et provocasti me in omnibus his, quapropter et ego vias tuas in capite tuo dedi, ait Dominus Deus, et non feci juxta scelera tua in omnibus abominationibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 44, 'Ecce omnis qui dicit vulgo proverbium, in te assumet illud, dicens: Sicut mater, ita et filia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 45, 'Filia matris tuæ es tu, quæ projecit virum suum et filios suos: et soror sororum tuarum es tu, quæ projecerunt viros suos et filios suos: mater vestra Cethæa, et pater vester Amorrhæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 46, 'Et soror tua major, Samaria, ipsa et filiæ ejus, quæ habitant ad sinistram tuam: soror autem tua minor te, quæ habitat a dextris tuis, Sodoma, et filiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 47, 'Sed nec in viis earum ambulasti, neque secundum scelera earum fecisti pauxillum minus: pene sceleratiora fecisti illis in omnibus viis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 48, 'Vivo ego, dicit Dominus Deus, quia non fecit Sodoma soror tua, ipsa et filiæ ejus, sicut fecisti tu et filiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 49, 'Ecce hæc fuit iniquitas Sodomæ sororis tuæ: superbia, saturitas panis et abundantia, et otium ipsius et filiarum ejus: et manum egeno et pauperi non porrigebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 50, 'et elevatæ sunt, et fecerunt abominationes coram me: et abstuli eas sicut vidisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 51, 'Et Samaria dimidium peccatorum tuorum non peccavit: sed vicisti eas sceleribus tuis, et justificasti sorores tuas in omnibus abominationibus tuis quas operata es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 52, 'Ergo et tu porta confusionem tuam, quæ vicisti sorores tuas peccatis tuis, sceleratius agens ab eis: justificatæ sunt enim a te: ergo et tu confundere, et porta ignominiam tuam, quæ justificasti sorores tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 53, 'Et convertam restituens eas conversione Sodomorum cum filiabus suis, et conversione Samariæ et filiarum ejus, et convertam reversionem tuam in medio earum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 54, 'ut portes ignominiam tuam, et confundaris in omnibus quæ fecisti consolans eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 55, 'Et soror tua Sodoma et filiæ ejus revertentur ad antiquitatem suam, et Samaria et filiæ ejus revertentur ad antiquitatem suam, et tu et filiæ tuæ revertemini ad antiquitatem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 56, 'Non fuit autem Sodoma soror tua audita in ore tuo in die superbiæ tuæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 57, 'antequam revelaretur malitia tua, sicut hoc tempore in opprobrium filiarum Syriæ, et cunctarum in circuitu tuo filiarum Palæstinarum quæ ambiunt te per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 58, 'Scelus tuum et ignominiam tuam tu portasti, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 59, 'Quia hæc dicit Dominus Deus: Et faciam tibi sicut despexisti juramentum, ut irritum faceres pactum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 60, 'et recordabor ego pacti mei tecum in diebus adolescentiæ tuæ, et suscitabo tibi pactum sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 61, 'Et recordaberis viarum tuarum, et confunderis, cum receperis sorores tuas te majores cum minoribus tuis: et dabo eas tibi in filias, sed non ex pacto tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 62, 'Et suscitabo ego pactum meum tecum, et scies quia ego Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 16, 63, 'ut recorderis, et confundaris, et non sit tibi ultra aperire os præ confusione tua, cum placatus tibi fuero in omnibus quæ fecisti, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 2, 'Fili hominis, propone ænigma, et narra parabolam ad domum Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 3, 'et dices: Hæc dicit Dominus Deus: Aquila grandis magnarum alarum, longo membrorum ductu, plena plumis et varietate, venit ad Libanum, et tulit medullam cedri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 4, 'Summitatem frondium ejus avulsit, et transportavit eam in terram Chanaan: in urbe negotiatorum posuit illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 5, 'Et tulit de semine terræ, et posuit illud in terra pro semine, ut firmaret radicem super aquas multas: in superficie posuit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 6, 'Cumque germinasset, crevit in vineam latiorem, humili statura, respicientibus ramis ejus ad eam, et radices ejus sub illa erant: facta est ergo vinea, et fructificavit in palmites, et emisit propagines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 7, 'Et facta est aquila altera grandis, magnis alis, multisque plumis: et ecce vinea ista quasi mittens radices suas ad eam, palmites suos extendit ad illam, ut irrigaret eam de areolis germinis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 8, 'In terra bona super aquas multas plantata est, ut faciat frondes, et portet fructum, ut sit in vineam grandem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 9, 'Dic: Hæc dicit Dominus Deus: Ergone prosperabitur? nonne radices ejus evellet, et fructus ejus distringet, et siccabit omnes palmites germinis ejus, et arescet, et non in brachio grandi, neque in populo multo, ut evelleret eam radicitus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 10, 'Ecce plantata est: ergone prosperabitur? nonne, cum tetigerit eam ventus urens, siccabitur, et in areis germinis sui arescet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 11, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 12, 'Dic ad domum exasperantem: Nescitis quid ista significent? Dic: Ecce venit rex Babylonis in Jerusalem, et assumet regem et principes ejus, et adducet eos ad semetipsum in Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 13, 'Et tollet de semine regni, ferietque cum eo fœdus, et ab eo accipiet jusjurandum. Sed et fortes terræ tollet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 14, 'ut sit regnum humile, et non elevetur, sed custodiat pactum ejus, et servet illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 15, 'Qui recedens ab eo misit nuntios ad \'gyptum, ut daret sibi equos et populum multum: numquid prosperabitur, vel consequetur salutem, qui fecit hæc? et qui dissolvit pactum, numquid effugiet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 16, 'Vivo ego, dicit Dominus Deus, quoniam in loco regis qui constituit eum regem, cujus fecit irritum juramentum, et solvit pactum quod habebat cum eo, in medio Babylonis morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 17, 'Et non in exercitu grandi, neque in populo multo, faciet contra eum Pharao prælium: in jactu aggeris, et in exstructione vallorum, ut interficiat animas multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 18, 'Spreverat enim juramentum, ut solveret fœdus, et ecce dedit manum suam: et cum omnia hæc fecerit, non effugiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 19, 'Propterea hæc dicit Dominus Deus: Vivo ego, quoniam juramentum quod sprevit, et fœdus quod prævaricatus est, ponam in caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 20, 'Et expandam super eum rete meum, et comprehendetur in sagena mea: et adducam eum in Babylonem, et judicabo eum ibi in prævaricatione qua despexit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 21, 'Et omnes profugi ejus, cum universo agmine suo, gladio cadent: residui autem in omnem ventum dispergentur: et scietis quia ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 22, 'Hæc dicit Dominus Deus: Et sumam ego de medulla cedri sublimis, et ponam: de vertice ramorum ejus tenerum distringam, et plantabo super montem excelsum et eminentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 23, 'In monte sublimi Israël plantabo illud, et erumpet in germen, et faciet fructum, et erit in cedrum magnam: et habitabunt sub ea omnes volucres, et universum volatile sub umbra frondium ejus nidificabit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 17, 24, 'et scient omnia ligna regionis quia ego Dominus humiliavi lignum sublime, et exaltavi lignum humile; et siccavi lignum viride, et frondere feci lignum aridum. Ego Dominus locutus sum, et feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 2, 'Quid est quod inter vos parabolam vertitis in proverbium istud in terra Israël, dicentes: Patres comederunt uvam acerbam, et dentes filiorum obstupescunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 3, 'Vivo ego, dicit Dominus Deus, si erit ultra vobis parabola hæc in proverbium in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 4, 'Ecce omnes animæ meæ sunt: ut anima patris, ita et anima filii mea est: anima quæ peccaverit, ipsa morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 5, 'Et vir si fuerit justus, et fecerit judicium et justitiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 6, 'in montibus non comederit, et oculos suos non levaverit ad idola domus Israël: et uxorem proximi sui non violaverit, et ad mulierem menstruatam non accesserit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 7, 'et hominem non contristaverit, pignus debitori reddiderit, per vim nihil rapuerit: panem suum esurienti dederit, et nudum operuerit vestimento:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 8, 'ad usuram non commodaverit, et amplius non acceperit: ab iniquitate averterit manum suam, et judicium verum fecerit inter virum et virum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 9, 'in præceptis meis ambulaverit, et judicia mea custodierit, ut faciat veritatem: hic justus est; vita vivet, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 10, 'Quod si genuerit filium latronem, effundentem sanguinem, et fecerit unum de istis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 11, 'et hæc quidem omnia non facientem, sed in montibus comedentem, et uxorem proximi sui polluentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 12, 'egenum et pauperem contristantem, rapientem rapinas, pignus non reddentem, et ad idola levantem oculos suos, abominationem facientem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 13, 'ad usuram dantem, et amplius accipientem: numquid vivet? Non vivet: cum universa hæc detestanda fecerit, morte morietur; sanguis ejus in ipso erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 14, 'Quod si genuerit filium, qui videns omnia peccata patris sui quæ fecit, timuerit, et non fecerit simile eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 15, 'super montes non comederit, et oculos suos non levaverit ad idola domus Israël, et uxorem proximi sui non violaverit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 16, 'et virum non contristaverit, pignus non retinuerit, et rapinam non rapuerit: panem suum esurienti dederit, et nudum operuerit vestimento:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 17, 'a pauperis injuria averterit manum suam, usuram et superabundantiam non acceperit, judicia mea fecerit, in præceptis meis ambulaverit: hic non morietur in iniquitate patris sui, sed vita vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 18, 'Pater ejus, quia calumniatus est, et vim fecit fratri, et malum operatus est in medio populi sui, ecce mortuus est in iniquitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 19, 'Et dicitis: Quare non portavit filius iniquitatem patris? Videlicet quia filius judicium et justitiam operatus est, omnia præcepta mea custodivit, et fecit illa, vivet vita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 20, 'Anima quæ peccaverit, ipsa morietur: filius non portabit iniquitatem patris, et pater non portabit iniquitatem filii: justitia justi super eum erit, et impietas impii erit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 21, 'Si autem impius egerit pœnitentiam ab omnibus peccatis suis quæ operatus est, et custodierit omnia præcepta mea, et fecerit judicium et justitiam, vita vivet, et non morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 22, 'Omnium iniquitatum ejus quas operatus est, non recordabor: in justitia sua quam operatus est, vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 23, 'Numquid voluntatis meæ est mors impii, dicit Dominus Deus, et non ut convertatur a viis suis, et vivat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 24, 'Si autem averterit se justus a justitia sua, et fecerit iniquitatem secundum omnes abominationes quas operari solet impius, numquid vivet? Omnes justitiæ ejus quas fecerat, non recordabuntur: in prævaricatione qua prævaricatus est, et in peccato suo quod peccavit, in ipsis morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 25, 'Et dixistis: Non est æqua via Domini! Audite ergo, domus Israël: numquid via mea non est æqua, et non magis viæ vestræ pravæ sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 26, 'Cum enim averterit se justus a justitia sua, et fecerit iniquitatem, morietur in eis: in injustitia quam operatus est morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 27, 'Et cum averterit se impius ab impietate sua quam operatus est, et fecerit judicium et justitiam, ipse animam suam vivificabit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 28, 'considerans enim, et avertens se ab omnibus iniquitatibus suis quas operatus est, vita vivet, et non morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 29, 'Et dicunt filii Israël: Non est æqua via Domini! Numquid viæ meæ non sunt æquæ, domus Israël, et non magis viæ vestræ pravæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 30, 'Idcirco unumquemque juxta vias suas judicabo, domus Israël, ait Dominus Deus. Convertimini, et agite pœnitentiam ab omnibus iniquitatibus vestris, et non erit vobis in ruinam iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 31, 'Projicite a vobis omnes prævaricationes vestras in quibus prævaricati estis, et facite vobis cor novum, et spiritum novum: et quare moriemini, domus Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 18, 32, 'Quia nolo mortem morientis, dicit Dominus Deus: revertimini, et vivite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 1, 'Et tu assume planctum super principes Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 2, 'et dices: Quare mater tua leæna inter leones cubavit? in medio leunculorum enutrivit catulos suos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 3, 'Et eduxit unum de leunculis suis, et leo factus est: et didicit capere prædam, hominemque comedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 4, 'Et audierunt de eo gentes: et non absque vulneribus suis ceperunt eum, et adduxerunt eum in catenis in terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 5, 'Quæ cum vidisset quoniam infirmata est, et periit exspectatio ejus, tulit unum de leunculis suis; leonem constituit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 6, 'Qui incedebat inter leones, et factus est leo: et didicit prædam capere, et homines devorare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 7, 'didicit viduas facere, et civitates earum in desertum adducere: et desolata est terra et plenitudo ejus a voce rugitus illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 8, 'Et convenerunt adversus eum gentes undique de provinciis, et expanderunt super eum rete suum: in vulneribus earum captus est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 9, 'et miserunt eum in caveam: in catenis adduxerunt eum ad regem Babylonis, miseruntque eum in carcerem, ne audiretur vox ejus ultra super montes Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 10, 'Mater tua quasi vinea in sanguine tuo super aquam plantata est: fructus ejus et frondes ejus creverunt ex aquis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 11, 'Et factæ sunt ei virgæ solidæ in sceptra dominantium, et exaltata est statura ejus inter frondes, et vidit altitudinem suam in multitudine palmitum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 12, 'Et evulsa est in ira, in terramque projecta, et ventus urens siccavit fructum ejus: marcuerunt et arefactæ sunt virgæ roboris ejus: ignis comedit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 13, 'Et nunc transplantata est in desertum, in terra invia et sitienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 19, 14, 'Et egressus est ignis de virga ramorum ejus, qui fructum ejus comedit: et non fuit in ea virga fortis, sceptrum dominantium. Planctus est, et erit in planctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 1, 'Et factum est in anno septimo, in quinto, in decima mensis, venerunt viri de senioribus Israël ut interrogarent Dominum, et sederunt coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 2, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 3, 'Fili hominis, loquere senioribus Israël, et dices ad eos: Hæc dicit Dominus Deus: Numquid ad interrogandum me vos venistis? vivo ego quia non respondebo vobis, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 4, 'Si judicas eos, si judicas, fili hominis, abominationes patrum eorum ostende eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 5, 'Et dices ad eos: Hæc dicit Dominus Deus: In die qua elegi Israël, et levavi manum meam pro stirpe domus Jacob, et apparui eis in terra \'gypti, et levavi manum meam pro eis, dicens: Ego Dominus Deus vester:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 6, 'in die illa levavi manum meam pro eis ut educerem eos de terra \'gypti, in terram quam provideram eis, fluentem lacte et melle, quæ est egregia inter omnes terras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 7, 'Et dixi ad eos: Unusquisque offensiones oculorum suorum abjiciat, et in idolis \'gypti nolite pollui: ego Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 8, 'Et irritaverunt me, nolueruntque me audire: unusquisque abominationes oculorum suorum non projecit, nec idola \'gypti reliquerunt. Et dixi ut effunderem indignationem meam super eos, et implerem iram meam in eis, in medio terræ \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 9, 'Et feci propter nomen meum, ut non violaretur coram gentibus in quarum medio erant, et inter quas apparui eis ut educerem eos de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 10, 'Ejeci ergo eos de terra \'gypti, et eduxi eos in desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 11, 'Et dedi eis præcepta mea, et judicia mea ostendi eis, quæ faciens homo vivet in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 12, 'Insuper et sabbata mea dedi eis, ut essent signum inter me et eos, et scirent quia ego Dominus sanctificans eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 13, 'Et irritaverunt me domus Israël in deserto: in præceptis meis non ambulaverunt, et judicia mea projecerunt, quæ faciens homo vivet in eis, et sabbata mea violaverunt vehementer. Dixi ergo ut effunderem furorem meum super eos in deserto, et consumerem eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 14, 'et feci propter nomen meum, ne violaretur coram gentibus de quibus ejeci eos in conspectu earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 15, 'Ego igitur levavi manum meam super eos in deserto, ne inducerem eos in terram quam dedi eis, fluentem lacte et melle, præcipuam terrarum omnium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 16, 'quia judicia mea projecerunt, et in præceptis meis non ambulaverunt, et sabbata mea violaverunt: post idola enim cor eorum gradiebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 17, 'Et pepercit oculus meus super eos, ut non interficerem eos: nec consumpsi eos in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 18, 'Dixi autem ad filios eorum in solitudine: In præceptis patrum vestrorum nolite incedere, nec judicia eorum custodiatis, nec in idolis eorum polluamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 19, 'Ego Dominus Deus vester: in præceptis meis ambulate: judicia mea custodite, et facite ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 20, 'et sabbata mea sanctificate, ut sint signum inter me et vos, et sciatis quia ego sum Dominus Deus vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 21, 'Et exacerbaverunt me filii: in præceptis meis non ambulaverunt, et judicia mea non custodierunt ut facerent ea, quæ cum fecerit homo, vivet in eis, et sabbata mea violaverunt. Et comminatus sum ut effunderem furorem meum super eos, et implerem iram meam in eis in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 22, 'Averti autem manum meam, et feci propter nomen meum, ut non violaretur coram gentibus de quibus ejeci eos in oculis earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 23, 'Iterum levavi manum meam in eos in solitudine, ut dispergerem illos in nationes, et ventilarem in terras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 24, 'eo quod judicia mea non fecissent, et præcepta mea reprobassent, et sabbata mea violassent, et post idola patrum suorum fuissent oculi eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 25, 'Ergo et ego dedi eis præcepta non bona, et judicia in quibus non vivent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 26, 'Et pollui eos in muneribus suis, cum offerrent omne quod aperit vulvam, propter delicta sua: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 27, 'Quam ob rem loquere ad domum Israël, fili hominis, et dices ad eos: Hæc dicit Dominus Deus: Adhuc et in hoc blasphemaverunt me patres vestri, cum sprevissent me contemnentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 28, 'et induxissem eos in terram super quam levavi manum meam ut darem eis: viderunt omnem collem excelsum, et omne lignum nemorosum, et immolaverunt ibi victimas suas, et dederunt ibi irritationem oblationis suæ, et posuerunt ibi odorem suavitatis suæ, et libaverunt libationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 29, 'Et dixi ad eos: Quid est excelsum, ad quod vos ingredimini? et vocatum est nomen ejus Excelsum usque ad hanc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 30, 'Propterea dic ad domum Israël: Hæc dicit Dominus Deus: Certe in via patrum vestrorum vos polluimini, et post offendicula eorum vos fornicamini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 31, 'et in oblatione donorum vestrorum, cum traducitis filios vestros per ignem, vos polluimini in omnibus idolis vestris usque hodie: et ego respondebo vobis, domus Israël? Vivo ego, dicit Dominus Deus, quia non respondebo vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 32, 'Neque cogitatio mentis vestræ fiet, dicentium: Erimus sicut gentes et sicut cognationes terræ, ut colamus ligna et lapides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 33, 'Vivo ego, dicit Dominus Deus, quoniam in manu forti, et in brachio extento, et in furore effuso, regnabo super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 34, 'Et educam vos de populis, et congregabo vos de terris in quibus dispersi estis: in manu valida, et in brachio extento, et in furore effuso, regnabo super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 35, 'Et adducam vos in desertum populorum, et judicabor vobiscum ibi facie ad faciem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 36, 'Sicut judicio contendi adversum patres vestros in deserto terræ \'gypti, sic judicabo vos, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 37, 'Et subjiciam vos sceptro meo, et inducam vos in vinculis fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 38, 'Et eligam de vobis transgressores et impios, et de terra incolatus eorum educam eos, et in terram Israël non ingredientur: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 39, 'Et vos, domus Israël, hæc dicit Dominus Deus: Singuli post idola vestra ambulate, et servite eis. Quod si et in hoc non audieritis me, et nomen meum sanctum pollueritis ultra in muneribus vestris et in idolis vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 40, 'in monte sancto meo, in monte excelso Israël, ait Dominus Deus, ibi serviet mihi omnis domus Israël: omnes, inquam, in terra in qua placebunt mihi: et ibi quæram primitias vestras, et initium decimarum vestrarum, in omnibus sanctificationibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 41, 'In odorem suavitatis suscipiam vos, cum eduxero vos de populis, et congregavero vos de terris in quas dispersi estis: et sanctificabor in vobis in oculis nationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 42, 'Et scietis quia ego Dominus, cum induxero vos ad terram Israël, in terram pro qua levavi manum meam ut darem eam patribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 43, 'Et recordabimini ibi viarum vestrarum, et omnium scelerum vestrorum, quibus polluti estis in eis: et displicebitis vobis in conspectu vestro, in omnibus malitiis vestris quas fecistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 44, 'Et scietis quia ego Dominus, cum benefecero vobis propter nomen meum, et non secundum vias vestras malas, neque secundum scelera vestra pessima, domus Israël, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 45, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 46, 'Fili hominis, pone faciem tuam contra viam austri, et stilla ad africum, et propheta ad saltum agri meridiani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 47, 'Et dices saltui meridiano: Audi verbum Domini: Hæc dicit Dominus Deus: Ecce ego succendam in te ignem, et comburam in te omne lignum viride, et omne lignum aridum: non extinguetur flamma succensionis: et comburetur in ea omnis facies ab austro usque ad aquilonem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 48, 'et videbit universa caro quia ego Dominus succendi eam, nec extinguetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 20, 49, 'Et dixi: A, a, a, Domine Deus: ipsi dicunt de me: Numquid non per parabolas loquitur iste?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 2, 'Fili hominis, pone faciem tuam ad Jerusalem, et stilla ad sanctuaria, et propheta contra humum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 3, 'Et dices terræ Israël: Hæc dicit Dominus Deus: Ecce ego ad te, et ejiciam gladium meum de vagina sua, et occidam in te justum et impium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 4, 'Pro eo autem quod occidi in te justum et impium, idcirco egredietur gladius meus de vagina sua ad omnem carnem, ab austro usque ad aquilonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 5, 'ut sciat omnis caro quia ego Dominus, eduxi gladium meum de vagina sua irrevocabilem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 6, 'Et tu, fili hominis, ingemisce in contritione lumborum, et in amaritudinibus ingemisce coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 7, 'Cumque dixerint ad te: Quare tu gemis? dices: Pro auditu: quia venit, et tabescet omne cor, et dissolventur universæ manus, et infirmabitur omnis spiritus, et per cuncta genua fluent aquæ: ecce venit, et fiet, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 8, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 9, 'Fili hominis, propheta, et dices: Hæc dicit Dominus Deus: loquere: Gladius, gladius exacutus est, et limatus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 10, 'ut cædat victimas, exacutus est: ut splendeat, limatus est: qui moves sceptrum filii mei, succidisti omne lignum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 11, 'Et dedi eum ad levigandum, ut teneatur manu: iste exacutus est gladius, et iste limatus est, ut sit in manu interficientis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 12, 'Clama et ulula, fili hominis, quia hic factus est in populo meo, hic in cunctis ducibus Israël qui fugerant: gladio traditi sunt cum populo meo: idcirco plaude super femur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 13, 'quia probatus est: et hoc, cum sceptrum subverterit, et non erit, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 14, 'Tu ergo, fili hominis, propheta, et percute manu ad manum: et duplicetur gladius, ac triplicetur gladius interfectorum: hic est gladius occisionis magnæ, qui obstupescere eos facit');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 15, 'et corde tabescere, et multiplicat ruinas. In omnibus portis eorum dedi conturbationem gladii acuti, et limati ad fulgendum, amicti ad cædem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 16, 'Exacuere, vade ad dexteram sive ad sinistram, quocumque faciei tuæ est appetitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 17, 'Quin et ego plaudam manu ad manum, et implebo indignationem meam: ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 18, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 19, 'Et tu, fili hominis, pone tibi duas vias, ut veniat gladius regis Babylonis: de terra una egredientur ambæ: et manu capiet conjecturam; in capite viæ civitatis conjiciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 20, 'Viam pones ut veniat gladius ad Rabbath filiorum Ammon, et ad Judam in Jerusalem munitissimam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 21, 'Stetit enim rex Babylonis in bivio, in capite duarum viarum, divinationem quærens, commiscens sagittas: interrogavit idola, exta consuluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 22, 'Ad dexteram ejus facta est divinatio super Jerusalem, ut ponat arietes, ut aperiat os in cæde, ut elevet vocem in ululatu, ut ponat arietes contra portas, ut comportet aggerem, ut ædificet munitiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 23, 'Eritque quasi consulens frustra oraculum in oculis eorum, et sabbatorum otium imitans: ipse autem recordabitur iniquitatis ad capiendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 24, 'Idcirco hæc dicit Dominus Deus: Pro eo quod recordati estis iniquitatis vestræ, et revelastis prævaricationes vestras, et apparuerunt peccata vestra in omnibus cogitationibus vestris, pro eo, inquam, quod recordati estis, manu capiemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 25, 'Tu autem, profane, impie dux Israël, cujus venit dies in tempore iniquitatis præfinita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 26, 'hæc dicit Dominus Deus: Aufer cidarim, tolle coronam: nonne hæc est quæ humilem sublevavit, et sublimem humiliavit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 27, 'Iniquitatem, iniquitatem, iniquitatem ponam eam: et hoc non factum est, donec veniret cujus est judicium, et tradam ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 28, 'Et tu, fili hominis, propheta, et dic: Hæc dicit Dominus Deus ad filios Ammon, et ad opprobrium eorum: et dices: Mucro, mucro, evaginate ad occidendum: limate ut interficias et fulgeas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 29, 'cum tibi viderentur vana, et divinarentur mendacia, ut dareris super colla vulneratorum impiorum, quorum venit dies in tempore iniquitatis præfinita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 30, 'Revertere ad vaginam tuam, in loco in quo creatus es: in terra nativitatis tuæ judicabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 31, 'Et effundam super te indignationem meam; in igne furoris mei sufflabo in te: daboque te in manus hominum insipientium, et fabricantium interitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 21, 32, 'Igni eris cibus; sanguis tuus erit in medio terræ; oblivioni traderis: quia ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 2, 'Et tu, fili hominis, nonne judicas, nonne judicas civitatem sanguinum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 3, 'Et ostendes ei omnes abominationes suas, et dices: Hæc dicit Dominus Deus: Civitas effundens sanguinem in medio sui, ut veniat tempus ejus: et quæ fecit idola contra semetipsam, ut pollueretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 4, 'In sanguine tuo, qui a te effusus est, deliquisti, et in idolis tuis, quæ fecisti, polluta es: et appropinquare fecisti dies tuos, et adduxisti tempus annorum tuorum: propterea dedi te opprobrium gentibus, et irrisionem universis terris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 5, 'Quæ juxta sunt, et quæ procul a te, triumphabunt de te, sordida, nobilis, grandis interitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 6, 'Ecce principes Israël singuli in brachio suo fuerunt in te, ad effundendum sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 7, 'Patrem et matrem contumeliis affecerunt: in te advenam calumniati sunt in medio tui: pupillum et viduam contristaverunt apud te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 8, 'Sanctuaria mea sprevisti, et sabbata mea polluisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 9, 'Viri detractores fuerunt in te ad effundendum sanguinem, et super montes comederunt in te: scelus operati sunt in medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 10, 'Verecundiora patris discooperuerunt in te; immunditiam menstruatæ humiliaverunt in te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 11, 'et unusquisque in uxorem proximi sui operatus est abominationem, et socer nurum suam polluit nefarie: frater sororem suam, filiam patris sui, oppressit in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 12, 'Munera acceperunt apud te ad effundendum sanguinem: usuram et superabundantiam accepisti, et avare proximos tuos calumniabaris: meique oblita es, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 13, 'Ecce complosi manus meas super avaritiam tuam quam fecisti, et super sanguinem qui effusus est in medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 14, 'Numquid sustinebit cor tuum, aut prævalebunt manus tuæ, in diebus quos ego faciam tibi? Ego Dominus locutus sum, et faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 15, 'Et dispergam te in nationes, et ventilabo te in terras, et deficere faciam immunditiam tuam a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 16, 'Et possidebo te in conspectu gentium: et scies quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 17, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 18, 'Fili hominis, versa est mihi domus Israël in scoriam: omnes isti æs, et stannum, et ferrum, et plumbum in medio fornacis: scoria argenti facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 19, 'Propterea hæc dicit Dominus Deus: Eo quod versi estis omnes in scoriam, propterea ecce ego congregabo vos in medio Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 20, 'congregatione argenti, et æris, et stanni, et ferri, et plumbi, in medio fornacis, ut succendam in ea ignem ad conflandum. Sic congregabo in furore meo, et in ira mea: et requiescam, et conflabo vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 21, 'Et congregabo vos, et succendam vos in igne furoris mei, et conflabimini in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 22, 'Ut conflatur argentum in medio fornacis, sic eritis in medio ejus: et scietis quia ego Dominus cum effuderim indignationem meam super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 23, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 24, 'Fili hominis, dic ei: Tu es terra immunda, et non compluta in die furoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 25, 'Conjuratio prophetarum in medio ejus: sicut leo rugiens, rapiensque prædam, animas devoraverunt: opes et pretium acceperunt: viduas ejus multiplicaverunt in medio illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 26, 'Sacerdotes ejus contempserunt legem meam, et polluerunt sanctuaria mea: inter sanctum et profanum non habuerunt distantiam, et inter pollutum et mundum non intellexerunt: et a sabbatis meis averterunt oculos suos, et coinquinabar in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 27, 'Principes ejus in medio illius quasi lupi rapientes prædam ad effundendum sanguinem, et ad perdendas animas, et avare ad sectanda lucra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 28, 'Prophetæ autem ejus liniebant eos absque temperamento, videntes vana, et divinantes eis mendacium, dicentes: Hæc dicit Dominus Deus: cum Dominus non sit locutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 29, 'Populi terræ calumniabantur calumniam, et rapiebant violenter: egenum et pauperem affligebant, et advenam opprimebant calumnia absque judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 30, 'Et quæsivi de eis virum qui interponeret sepem, et staret oppositus contra me pro terra, ne dissiparem eam: et non inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 22, 31, 'Et effudi super eos indignationem meam; in igne iræ meæ consumpsi eos: viam eorum in caput eorum reddidi, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 2, 'Fili hominis, duæ mulieres filiæ matris unius fuerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 3, 'et fornicatæ sunt in \'gypto, in adolescentia sua fornicatæ sunt: ibi subacta sunt ubera earum, et fractæ sunt mammæ pubertatis earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 4, 'Nomina autem earum, Oolla major, et Ooliba soror ejus minor: et habui eas, et pepererunt filios et filias. Porro earum nomina, Samaria Oolla, et Jerusalem Ooliba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 5, 'Fornicata est igitur super me Oolla, et insanivit in amatores suos, in Assyrios propinquantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 6, 'vestitos hyacintho, principes et magistratus, juvenes cupidinis, universos equites, ascensores equorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 7, 'Et dedit fornicationes suas super eos electos, filios Assyriorum universos: et in omnibus in quos insanivit, in immunditiis eorum polluta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 8, 'Insuper et fornicationes suas, quas habuerat in \'gypto, non reliquit: nam et illi dormierunt cum ea in adolescentia ejus, et illi confregerunt ubera pubertatis ejus, et effuderunt fornicationem suam super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 9, 'Propterea tradidi eam in manus amatorum suorum, in manus filiorum Assur, super quorum insanivit libidine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 10, 'Ipsi discooperuerunt ignominiam ejus, filios et filias ejus tulerunt, et ipsam occiderunt gladio: et factæ sunt famosæ mulieres, et judicia perpetraverunt in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 11, 'Quod cum vidisset soror ejus Ooliba, plus quam illa insanivit libidine, et fornicationem suam super fornicationem sororis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 12, 'ad filios Assyriorum præbuit impudenter, ducibus et magistratibus ad se venientibus, indutis veste varia, equitibus qui vectabantur equis, et adolescentibus forma cunctis egregia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 13, 'Et vidi quod polluta esset via una ambarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 14, 'Et auxit fornicationes suas: cumque vidisset viros depictos in pariete, imagines Chaldæorum expressas coloribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 15, 'et accinctos balteis renes, et tiaras tinctas in capitibus eorum, formam ducum omnium, similitudinem filiorum Babylonis, terræque Chaldæorum, in qua orti sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 16, 'insanivit super eos concupiscentia oculorum suorum, et misit nuntios ad eos in Chaldæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 17, 'Cumque venissent ad eam filii Babylonis ad cubile mammarum, polluerunt eam stupris suis: et polluta est ab eis, et saturata est anima ejus ab illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 18, 'Denudavit quoque fornicationes suas, et discooperuit ignominiam suam: et recessit anima mea ab ea, sicut recesserat anima mea a sorore ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 19, 'multiplicavit enim fornicationes suas, recordans dies adolescentiæ suæ, quibus fornicata est in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 20, 'Et insanivit libidine super concubitum eorum, quorum carnes sunt ut carnes asinorum, et sicut fluxus equorum fluxus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 21, 'Et visitasti scelus adolescentiæ tuæ, quando subacta sunt in \'gypto ubera tua, et confractæ sunt mammæ pubertatis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 22, 'Propterea, Ooliba, hæc dicit Dominus Deus: Ecce ego suscitabo omnes amatores tuos contra te, de quibus satiata est anima tua, et congregabo eos adversum te in circuitu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 23, 'filios Babylonis, et universos Chaldæos, nobiles, tyrannosque, et principes, omnes filios Assyriorum, juvenes forma egregia, duces et magistratus universos, principes principum, et nominatos ascensores equorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 24, 'et venient super te instructi curru et rota, multitudo populorum: lorica, et clypeo, et galea armabuntur contra te undique: et dabo coram eis judicium, et judicabunt te judiciis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 25, 'Et ponam zelum meum in te, quem exercent tecum in furore: nasum tuum et aures tuas præcident, et quæ remanserint, gladio concident. Ipsi filios tuos et filias tuas capient, et novissimum tuum devorabitur igni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 26, 'et denudabunt te vestimentis tuis, et tollent vasa gloriæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 27, 'Et requiescere faciam scelus tuum de te, et fornicationem tuam de terra \'gypti: nec levabis oculos tuos ad eos, et \'gypti non recordaberis amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 28, 'Quia hæc dicit Dominus Deus: Ecce ego tradam te in manus eorum quos odisti, in manus de quibus satiata est anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 29, 'Et agent tecum in odio, et tollent omnes labores tuos, et dimittent te nudam et ignominia plenam: et revelabitur ignominia fornicationum tuarum, scelus tuum, et fornicationes tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 30, 'Fecerunt hæc tibi, quia fornicata es post gentes inter quas polluta es in idolis earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 31, 'In via sororis tuæ ambulasti, et dabo calicem ejus in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 32, 'Hæc dicit Dominus Deus: Calicem sororis tuæ bibes profundum et latum: eris in derisum et in subsannationem quæ est capacissima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 33, 'Ebrietate et dolore repleberis: calice mœroris et tristitiæ, calice sororis tuæ Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 34, 'Et bibes illum, et epotabis usque ad fæces: et fragmenta ejus devorabis, et ubera tua lacerabis, quia ego locutus sum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 35, 'Propterea hæc dicit Dominus Deus: Quia oblita es mei, et projecisti me post corpus tuum, tu quoque porta scelus tuum et fornicationes tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 36, 'Et ait Dominus ad me, dicens: Fili hominis, numquid judicas Oollam et Oolibam, et annuntias eis scelera earum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 37, 'Quia adulteratæ sunt, et sanguis in manibus earum, et cum idolis suis fornicatæ sunt: insuper et filios suos quos genuerunt mihi, obtulerunt eis ad devorandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 38, 'Sed et hoc fecerunt mihi: polluerunt sanctuarium meum in die illa, et sabbata mea profanaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 39, 'Cumque immolarent filios suos idolis suis, et ingrederentur sanctuarium meum in die illa ut polluerent illud, etiam hæc fecerunt in medio domus meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 40, 'Miserunt ad viros venientes de longe, ad quos nuntium miserant: itaque ecce venerunt quibus te lavisti, et circumlinisti stibio oculos tuos, et ornata es mundo muliebri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 41, 'Sedisti in lecto pulcherrimo, et mensa ornata est ante te: thymiama meum et unguentum meum posuisti super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 42, 'Et vox multitudinis exsultantis erat in ea: et in viris, qui de multitudine hominum adducebantur, et veniebant de deserto, posuerunt armillas in manibus eorum, et coronas speciosas in capitibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 43, 'Et dixi ei, quæ attrita est in adulteriis: Nunc fornicabitur in fornicatione sua etiam hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 44, 'Et ingressi sunt ad eam quasi ad mulierem meretricem: sic ingrediebantur ad Oollam et Oolibam, mulieres nefarias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 45, 'Viri ergo justi sunt: hi judicabunt eas judicio adulterarum, et judicio effundentium sanguinem: quia adulteræ sunt, et sanguis in manibus earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 46, 'Hæc enim dicit Dominus Deus: Adduc ad eas multitudinem, et trade eas in tumultum et in rapinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 47, 'Et lapidentur lapidibus populorum, et confodiantur gladiis eorum: filios et filias earum interficient, et domos earum igne succendent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 48, 'Et auferam scelus de terra, et discent omnes mulieres ne faciant secundum scelus earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 23, 49, 'Et dabunt scelus vestrum super vos, et peccata idolorum vestrorum portabitis: et scietis quia ego Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 1, 'Et factum est verbum Domini ad me in anno nono, in mense decimo, decima die mensis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 2, 'Fili hominis, scribe tibi nomen diei hujus, in qua confirmatus est rex Babylonis adversum Jerusalem hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 3, 'Et dices per proverbium ad domum irritatricem parabolam, et loqueris ad eos: Hæc dicit Dominus Deus: Pone ollam; pone, inquam, et mitte in eam aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 4, 'Congere frusta ejus in eam, omnem partem bonam, femur et armum, electa et ossibus plena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 5, 'Pinguissimum pecus assume, compone quoque strues ossium sub ea: efferbuit coctio ejus, et discocta sunt ossa illius in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 6, 'Propterea hæc dicit Dominus Deus: Væ civitati sanguinum, ollæ cujus rubigo in ea est, et rubigo ejus non exivit de ea! per partes et per partes suas ejice eam: non cecidit super eam sors.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 7, 'Sanguis enim ejus in medio ejus est; super limpidissimam petram effudit illum: non effudit illum super terram, ut possit operiri pulvere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 8, 'Ut superinducerem indignationem meam, et vindicta ulciscerer, dedi sanguinem ejus super petram limpidissimam, ne operiretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 9, 'Propterea hæc dicit Dominus Deus: Væ civitati sanguinum, cujus ego grandem faciam pyram!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 10, 'Congere ossa, quæ igne succendam: consumentur carnes, et coquetur universa compositio, et ossa tabescent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 11, 'Pone quoque eam super prunas vacuam, ut incalescat, et liquefiat æs ejus, et confletur in medio ejus inquinamentum ejus, et consumatur rubigo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 12, 'Multo labore sudatum est, et non exivit de ea nimia rubigo ejus, neque per ignem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 13, 'Immunditia tua execrabilis, quia mundare te volui, et non es mundata a sordibus tuis: sed nec mundaberis prius, donec quiescere faciam indignationem meam in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 14, 'Ego Dominus locutus sum: veniet, et faciam: non transeam, nec parcam, nec placabor: juxta vias tuas, et juxta adinventiones tuas judicabo te, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 15, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 16, 'Fili hominis, ecce ego tollo a te desiderabile oculorum tuorum in plaga: et non planges, neque plorabis, neque fluent lacrimæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 17, 'Ingemisce tacens: mortuorum luctum non facies: corona tua circumligata sit tibi, et calceamenta tua erunt in pedibus tuis: nec amictu ora velabis, nec cibos lugentium comedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 18, 'Locutus sum ergo ad populum mane, et mortua est uxor mea vespere: fecique mane sicut præceperat mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 19, 'Et dixit ad me populus: Quare non indicas nobis quid ista significent quæ tu facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 20, 'Et dixi ad eos: Sermo Domini factus est ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 21, 'Loquere domui Israël: Hæc dicit Dominus Deus: Ecce ego polluam sanctuarium meum, superbiam imperii vestri, et desiderabile oculorum vestrorum, et super quo pavet anima vestra: filii vestri et filiæ vestræ quas reliquistis, gladio cadent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 22, 'Et facietis sicut feci: ora amictu non velabitis, et cibos lugentium non comedetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 23, 'coronas habebitis in capitibus vestris, et calceamenta in pedibus: non plangetis, neque flebitis, sed tabescetis in iniquitatibus vestris, et unusquisque gemet ad fratrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 24, 'Eritque Ezechiel vobis in portentum: juxta omnia quæ fecit, facietis cum venerit istud: et scietis quia ego Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 25, 'Et tu, fili hominis, ecce in die qua tollam ab eis fortitudinem eorum, et gaudium dignitatis, et desiderium oculorum eorum, super quo requiescunt animæ eorum, filios et filias eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 26, 'in die illa, cum venerit fugiens ad te ut annuntiet tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 24, 27, 'in die, inquam illa, aperietur os tuum cum eo qui fugit, et loqueris, et non silebis ultra: erisque eis in portentum, et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 2, 'Fili hominis, pone faciem tuam contra filios Ammon, et prophetabis de eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 3, 'Et dices filiis Ammon: Audite verbum Domini Dei. Hæc dicit Dominus Deus: Pro eo quod dixisti: Euge, euge, super sanctuarium meum, quia pollutum est; et super terram Israël, quoniam desolata est; et super domum Juda, quoniam ducti sunt in captivitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 4, 'idcirco ego tradam te filiis orientalibus in hæreditatem: et collocabunt caulas suas in te, et ponent in te tentoria sua: ipsi comedent fruges tuas, et ipsi bibent lac tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 5, 'Daboque Rabbath in habitaculum camelorum, et filios Ammon in cubile pecorum: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 6, 'Quia hæc dicit Dominus Deus: Pro eo quod plausisti manu et percussisti pede, et gavisa es ex toto affectu super terram Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 7, 'idcirco ecce ego extendam manum meam super te, et tradam te in direptionem gentium, et interficiam te de populis, et perdam de terris, et conteram: et scies quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 8, 'Hæc dicit Dominus Deus: Pro eo quod dixerunt Moab et Seir: Ecce sicut omnes gentes, domus Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 9, 'idcirco ecce ego aperiam humerum Moab de civitatibus, de civitatibus, inquam, ejus, et de finibus ejus, inclytas terræ Bethiesimoth, et Beelmeon, et Cariathaim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 10, 'filiis orientis cum filiis Ammon, et dabo eam in hæreditatem, ut non sit ultra memoria filiorum Ammon in gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 11, 'Et in Moab faciam judicia, et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 12, 'Hæc dicit Dominus Deus: Pro eo quod fecit Idumæa ultionem ut se vindicaret de filiis Juda, peccavitque delinquens, et vindictam expetivit de eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 13, 'idcirco hæc dicit Dominus Deus: Extendam manum meam super Idumæam, et auferam de ea hominem et jumentum, et faciam eam desertam ab austro: et qui sunt in Dedan, gladio cadent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 14, 'Et dabo ultionem meam super Idumæam per manum populi mei Israël: et facient in Edom juxta iram meam et furorem meum, et scient vindictam meam, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 15, 'Hæc dicit Dominus Deus: Pro eo quod fecerunt Palæstini vindictam, et ulti se sunt toto animo, interficientes, et implentes inimicitias veteres,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 16, 'propterea hæc dicit Dominus Deus: Ecce ego extendam manum meam super Palæstinos, et interficiam interfectores, et perdam reliquias maritimæ regionis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 25, 17, 'faciamque in eis ultiones magnas, arguens in furore: et scient quia ego Dominus, cum dedero vindictam meam super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 1, 'Et factum est in undecimo anno, prima mensis: factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 2, 'Fili hominis, pro eo quod dixit Tyrus de Jerusalem: Euge, confractæ sunt portæ populorum, conversa est ad me: implebor; deserta est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 3, 'propterea hæc dicit Dominus Deus: Ecce ego super te, Tyre, et ascendere faciam ad te gentes multas, sicut ascendit mare fluctuans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 4, 'Et dissipabunt muros Tyri, et destruent turres ejus: et radam pulverem ejus de ea, et dabo eam in limpidissimam petram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 5, 'Siccatio sagenarum erit in medio maris, quia ego locutus sum, ait Dominus Deus: et erit in direptionem gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 6, 'Filiæ quoque ejus quæ sunt in agro, gladio interficientur: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 7, 'Quia hæc dicit Dominus Deus: Ecce ego adducam ad Tyrum Nabuchodonosor regem Babylonis ab aquilone, regem regum, cum equis, et curribus, et equitibus, et cœtu, populoque magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 8, 'Filias tuas quæ sunt in agro, gladio interficiet, et circumdabit te munitionibus, et comportabit aggerem in gyro, et elevabit contra te clypeum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 9, 'et vineas et arietes temperabit in muros tuos, et turres tuas destruet in armatura sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 10, 'Inundatione equorum ejus operiet te pulvis eorum: a sonitu equitum, et rotarum, et curruum, movebuntur muri tui, cum ingressus fuerit portas tuas quasi per introitum urbis dissipatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 11, 'Ungulis equorum suorum conculcabit omnes plateas tuas: populum tuum gladio cædet, et statuæ tuæ nobiles in terram corruent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 12, 'Vastabunt opes tuas, diripient negotiationes tuas, et destruent muros tuos, et domos tuas præclaras subvertent: et lapides tuos, et ligna tua, et pulverem tuum in medio aquarum ponent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 13, 'Et quiescere faciam multitudinem canticorum tuorum: et sonitus cithararum tuarum non audietur amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 14, 'Et dabo te in limpidissimam petram, siccatio sagenarum eris, nec ædificaberis ultra, quia ego locutus sum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 15, 'Hæc dicit Dominus Deus Tyro: Numquid non a sonitu ruinæ tuæ, et gemitu interfectorum tuorum, cum occisi fuerint in medio tui, commovebuntur insulæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 16, 'Et descendent de sedibus suis omnes principes maris, et auferent exuvias suas, et vestimenta sua varia abjicient, et induentur stupore: in terra sedebunt, et attoniti super repentino casu tuo admirabuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 17, 'et assumentes super te lamentum, dicent tibi: Quomodo peristi, quæ habitas in mari, urbs inclyta, quæ fuisti fortis in mari cum habitatoribus tuis, quos formidabant universi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 18, 'Nunc stupebunt naves in die pavoris tui, et turbabuntur insulæ in mari, eo quod nullus egrediatur ex te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 19, 'Quia hæc dicit Dominus Deus: Cum dedero te urbem desolatam, sicut civitates quæ non habitantur; et adduxero super te abyssum, et operuerint te aquæ multæ;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 20, 'et detraxero te cum his qui descendunt in lacum ad populum sempiternum; et collocavero te in terra novissima sicut solitudines veteres, cum his qui deducuntur in lacum, ut non habiteris; porro cum dedero gloriam in terra viventium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 26, 21, 'in nihilum redigam te, et non eris: et requisita non invenieris ultra in sempiternum, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 2, 'Tu ergo, fili hominis, assume super Tyrum lamentum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 3, 'et dices Tyro, quæ habitat in introitu maris, negotiationi populorum ad insulas multas: Hæc dicit Dominus Deus: O Tyre, tu dixisti: Perfecti decoris ego sum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 4, 'et in corde maris sita. Finitimi tui qui te ædificaverunt, impleverunt decorem tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 5, 'abietibus de Sanir exstruxerunt te cum omnibus tabulatis maris: cedrum de Libano tulerunt ut facerent tibi malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 6, 'Quercus de Basan dolaverunt in remos tuos, et transtra tua fecerunt tibi ex ebore indico, et prætoriola de insulis Italiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 7, 'Byssus varia de \'gypto texta est tibi in velum ut poneretur in malo: hyacinthus et purpura de insulis Elisa facta sunt operimentum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 8, 'Habitatores Sidonis et Aradii fuerunt remiges tui: sapientes tui, Tyre, facti sunt gubernatores tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 9, 'Senes Giblii et prudentes ejus habuerunt nautas ad ministerium variæ supellectilis tuæ: omnes naves maris, et nautæ earum, fuerunt in populo negotiationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 10, 'Persæ, et Lydii, et Libyes erant in exercitu tuo viri bellatores tui: clypeum et galeam suspenderunt in te pro ornatu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 11, 'Filii Aradii cum exercitu tuo erant super muros tuos in circuitu: sed et Pigmæi qui erant in turribus tuis, pharetras suas suspenderunt in muris tuis per gyrum: ipsi compleverunt pulchritudinem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 12, 'Carthaginenses negotiatores tui, a multitudine cunctarum divitiarum, argento, ferro, stanno, plumboque repleverunt nundinas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 13, 'Græcia, Thubal, et Mosoch, ipsi institores tui: mancipia, et vasa ærea advexerunt populo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 14, 'De domo Thogorma, equos, et equites, et mulos adduxerunt ad forum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 15, 'Filii Dedan negotiatores tui; insulæ multæ, negotiatio manus tuæ: dentes eburneos et hebeninos commutaverunt in pretio tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 16, 'Syrus negotiator tuus propter multitudinem operum tuorum: gemmam, et purpuram, et scutulata, et byssum, et sericum, et chodchod proposuerunt in mercatu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 17, 'Juda et terra Israël, ipsi institores tui in frumento primo: balsamum, et mel, et oleum, et resinam proposuerunt in nundinis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 18, 'Damascenus negotiator tuus in multitudine operum tuorum, in multitudine diversarum opum, in vino pingui, in lanis coloris optimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 19, 'Dan, et Græcia, et Mosel, in nundinis tuis proposuerunt ferrum fabrefactum: stacte et calamus in negotiatione tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 20, 'Dedan institores tui in tapetibus ad sedendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 21, 'Arabia et universi principes Cedar, ipsi negotiatores manus tuæ: cum agnis, et arietibus, et hædis, venerunt ad te negotiatores tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 22, 'Venditores Saba et Reema, ipsi negotiatores tui: cum universis primis aromatibus, et lapide pretioso, et auro, quod proposuerunt in mercatu tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 23, 'Haran, et Chene, et Eden, negotiatores tui; Saba, Assur, et Chelmad venditores tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 24, 'Ipsi negotiatores tui multifariam, involucris hyacinthi, et polymitorum, gazarumque pretiosarum, quæ obvolutæ et astrictæ erant funibus: cedros quoque habebant in negotiationibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 25, 'Naves maris, principes tui in negotiatione tua: et repleta es, et glorificata nimis in corde maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 26, 'In aquis multis adduxerunt te remiges tui: ventus auster contrivit te in corde maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 27, 'Divitiæ tuæ, et thesauri tui, et multiplex instrumentum tuum: nautæ tui et gubernatores tui, qui tenebant supellectilem tuam, et populo tuo præerant: viri quoque bellatores tui, qui erant in te, cum universa multitudine tua quæ est in medio tui, cadent in corde maris in die ruinæ tuæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 28, 'a sonitu clamoris gubernatorum tuorum conturbabuntur classes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 29, 'Et descendent de navibus suis omnes qui tenebant remum: nautæ et universi gubernatores maris in terra stabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 30, 'Et ejulabunt super te voce magna: et clamabunt amare, et superjacient pulverem capitibus suis, et cinere conspergentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 31, 'Et radent super te calvitium, et accingentur ciliciis: et plorabunt te in amaritudine animæ, ploratu amarissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 32, 'Et assument super te carmen lugubre, et plangent te: Quæ est ut Tyrus, quæ obmutuit in medio maris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 33, 'Quæ in exitu negotiationum tuarum de mari implesti populos multos: in multitudine divitiarum tuarum, et populorum tuorum, ditasti reges terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 34, 'Nunc contrita es a mari: in profundis aquarum opes tuæ, et omnis multitudo tua quæ erat in medio tui, ceciderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 35, 'Universi habitatores insularum obstupuerunt super te, et reges earum omnes tempestate perculsi mutaverunt vultus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 27, 36, 'Negotiatores populorum sibilaverunt super te: ad nihilum deducta es, et non eris usque in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 2, 'Fili hominis, dic principi Tyri: Hæc dicit Dominus Deus: Eo quod elevatum est cor tuum, et dixisti: Deus ego sum, et in cathedra Dei sedi in corde maris, cum sis homo, et non deus: et dedisti cor tuum quasi cor Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 3, 'ecce sapientior es tu Daniele: omne secretum non est absconditum a te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 4, 'in sapientia et prudentia tua fecisti tibi fortitudinem, et acquisisti aurum et argentum in thesauris tuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 5, 'in multitudine sapientiæ tuæ, et in negotiatione tua multiplicasti tibi fortitudinem, et elevatum est cor tuum in robore tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 6, 'propterea hæc dicit Dominus Deus: Eo quod elevatum est cor tuum quasi cor dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 7, 'idcirco ecce ego adducam super te alienos, robustissimos gentium: et nudabunt gladios suos super pulchritudinem sapientiæ tuæ, et polluent decorem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 8, 'Interficient, et detrahent te: et morieris in interitu occisorum in corde maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 9, 'Numquid dicens loqueris: Deus ego sum, coram interficientibus te, cum sis homo, et non deus, in manu occidentium te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 10, 'Morte incircumcisorum morieris in manu alienorum, quia ego locutus sum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 11, 'Et factus est sermo Domini ad me, dicens: Fili hominis, leva planctum super regem Tyri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 12, 'et dices ei: Hæc dicit Dominus Deus: Tu signaculum similitudinis, plenus sapientia, et perfectus decore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 13, 'In deliciis paradisi Dei fuisti: omnis lapis pretiosus operimentum tuum, sardius, topazius, et jaspis, chrysolithus, et onyx, et beryllus, sapphirus, et carbunculus, et smaragdus: aurum, opus decoris tui: et foramina tua, in die qua conditus es, præparata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 14, 'Tu cherub extentus, et protegens, et posui te in monte sancto Dei: in medio lapidum ignitorum ambulasti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 15, 'perfectus in viis tuis a die conditionis tuæ, donec inventa est iniquitas in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 16, 'In multitudine negotiationis tuæ repleta sunt interiora tua iniquitate, et peccasti: et ejeci te de monte Dei, et perdidi te, o cherub protegens, de medio lapidum ignitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 17, 'Et elevatum est cor tuum in decore tuo; perdidisti sapientiam tuam in decore tuo: in terram projeci te; ante faciem regum dedi te ut cernerent te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 18, 'In multitudine iniquitatum tuarum, et iniquitate negotiationis tuæ, polluisti sanctificationem tuam: producam ergo ignem de medio tui, qui comedat te, et dabo te in cinerem super terram, in conspectu omnium videntium te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 19, 'Omnes qui viderint te in gentibus, obstupescent super te: nihili factus es, et non eris in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 20, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 21, 'Fili hominis, pone faciem tuam contra Sidonem, et prophetabis de ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 22, 'et dices: Hæc dicit Dominus Deus: Ecce ego ad te, Sidon, et glorificabor in medio tui: et scient quia ego Dominus, cum fecero in ea judicia, et sanctificatus fuero in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 23, 'Et immittam ei pestilentiam, et sanguinem in plateis ejus: et corruent interfecti in medio ejus gladio per circuitum, et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 24, 'Et non erit ultra domui Israël offendiculum amaritudinis, et spina dolorem inferens undique per circuitum eorum qui adversantur eis: et scient quia ego Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 25, 'Hæc dicit Dominus Deus: Quando congregavero domum Israël de populis in quibus dispersi sunt, sanctificabor in eis coram gentibus: et habitabunt in terra sua, quam dedi servo meo Jacob:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 28, 26, 'et habitabunt in ea securi, et ædificabunt domos, et plantabunt vineas, et habitabunt confidenter, cum fecero judicia in omnibus qui adversantur eis per circuitum: et scient quia ego Dominus Deus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 1, 'In anno decimo, decimo mense, undecima die mensis, factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 2, 'Fili hominis, pone faciem tuam contra Pharaonem regem \'gypti, et prophetabis de eo, et de \'gypto universa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 3, 'Loquere, et dices: Hæc dicit Dominus Deus: Ecce ego ad te, Pharao rex \'gypti, draco magne, qui cubas in medio fluminum tuorum, et dicis: Meus est fluvius, et ego feci memetipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 4, 'Et ponam frenum in maxillis tuis, et agglutinabo pisces fluminum tuorum squamis tuis, et extraham te de medio fluminum tuorum, et universi pisces tui squamis tuis adhærebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 5, 'Et projiciam te in desertum, et omnes pisces fluminis tui: super faciem terræ cades; non colligeris, neque congregaberis: bestiis terræ et volatilibus cæli dedi te ad devorandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 6, 'Et scient omnes habitatores \'gypti quia ego Dominus, pro eo quod fuisti baculus arundineus domui Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 7, 'quando apprehenderunt te manu, et confractus es, et lacerasti omnem humerum eorum: et innitentibus eis super te comminutus es, et dissolvisti omnes renes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 8, 'Propterea hæc dicit Dominus Deus: Ecce ego adducam super te gladium, et interficiam de te hominem et jumentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 9, 'Et erit terra \'gypti in desertum et in solitudinem: et scient quia ego Dominus, pro eo quod dixeris: Fluvius meus est, et ego feci eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 10, 'Idcirco ecce ego ad te, et ad flumina tua: daboque terram \'gypti in solitudines, gladio dissipatam, a turre Syenes usque ad terminos \'thiopiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 11, 'Non pertransibit eam pes hominis, neque pes jumenti gradietur in ea, et non habitabitur quadraginta annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 12, 'Daboque terram \'gypti desertam in medio terrarum desertarum, et civitates ejus in medio urbium subversarum, et erunt desolatæ quadraginta annis: et dispergam \'gyptios in nationes, et ventilabo eos in terras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 13, 'Quia hæc dicit Dominus Deus: Post finem quadraginta annorum congregabo \'gyptum de populis in quibus dispersi fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 14, 'Et reducam captivitatem \'gypti, et collocabo eos in terra Phathures, in terra nativitatis suæ, et erunt ibi in regnum humile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 15, 'Inter cetera regna erit humillima, et non elevabitur ultra super nationes, et imminuam eos ne imperent gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 16, 'Neque erunt ultra domui Israël in confidentia, docentes iniquitatem ut fugiant, et sequantur eos: et scient quia ego Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 17, 'Et factum est in vigesimo et septimo anno, in primo, in una mensis: factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 18, 'Fili hominis, Nabuchodonosor rex Babylonis servire fecit exercitum suum servitute magna adversum Tyrum: omne caput decalvatum, et omnis humerus depilatus est: et merces non est reddita ei, neque exercitui ejus, de Tyro, pro servitute qua servivit mihi adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 19, 'Propterea hæc dicit Dominus Deus: Ecce ego dabo Nabuchodonosor regem Babylonis in terra \'gypti: et accipiet multitudinem ejus, et deprædabitur manubias ejus, et diripiet spolia ejus: et erit merces exercitui illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 20, 'et operi quo servivit adversus eam: dedi ei terram \'gypti pro eo quod laboraverit mihi, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 29, 21, 'In die illo pullulabit cornu domui Israël, et tibi dabo apertum os in medio eorum, et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 2, 'Fili hominis, propheta, et dic: Hæc dicit Dominus Deus: Ululate: Væ, væ diei!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 3, 'quia juxta est dies, et appropinquat dies Domini, dies nubis: tempus gentium erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 4, 'Et veniet gladius in \'gyptum, et erit pavor in \'thiopia, cum ceciderint vulnerati in \'gypto, et ablata fuerit multitudo illius, et destructa fundamenta ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 5, '\'thiopia, et Libya, et Lydi, et omne reliquum vulgus, et Chub, et filii terræ fœderis, cum eis gladio cadent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 6, 'Hæc dicit Dominus Deus: Et corruent fulcientes \'gyptum, et destruetur superbia imperii ejus: a turre Syenes gladio cadent in ea, ait Dominus Deus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 7, 'Et dissipabuntur in medio terrarum desolatarum, et urbes ejus in medio civitatum desertarum erunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 8, 'et scient quia ego Dominus, cum dedero ignem in \'gypto, et attriti fuerint omnes auxiliatores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 9, 'In die illa egredientur nuntii a facie mea in trieribus ad conterendam \'thiopiæ confidentiam: et erit pavor in eis in die \'gypti, quia absque dubio veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 10, 'Hæc dicit Dominus Deus: Cessare faciam multitudinem \'gypti in manu Nabuchodonosor regis Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 11, 'Ipse et populus ejus cum eo, fortissimi gentium, adducentur ad disperdendam terram: et evaginabunt gladios suos super \'gyptum, et implebunt terram interfectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 12, 'Et faciam alveos fluminum aridos, et tradam terram in manus pessimorum: et dissipabo terram et plenitudinem ejus manu alienorum: ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 13, 'Hæc dicit Dominus Deus: Et disperdam simulacra, et cessare faciam idola de Memphis: et dux de terra \'gypti non erit amplius, et dabo terrorem in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 14, 'Et disperdam terram Phathures, et dabo ignem in Taphnis, et faciam judicia in Alexandria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 15, 'Et effundam indignationem meam super Pelusium, robur \'gypti, et interficiam multitudinem Alexandriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 16, 'Et dabo ignem in \'gypto: quasi parturiens dolebit Pelusium, et Alexandria erit dissipata, et in Memphis angustiæ quotidianæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 17, 'Juvenes Heliopoleos et Bubasti gladio cadent, et ipsæ captivæ ducentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 18, 'Et in Taphnis nigrescet dies, cum contrivero ibi sceptra \'gypti, et defecerit in ea superbia potentiæ ejus: ipsam nubes operiet, filiæ autem ejus in captivitatem ducentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 19, 'Et judicia faciam in \'gypto: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 20, 'Et factum est in undecimo anno, in primo mense, in septima mensis: factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 21, 'Fili hominis, brachium Pharaonis regis \'gypti confregi, et ecce non est obvolutum ut restitueretur ei sanitas, ut ligaretur pannis, et fasciaretur linteolis, ut recepto robore posset tenere gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 22, 'Propterea hæc dicit Dominus Deus: Ecce ego ad Pharaonem regem \'gypti, et comminuam brachium ejus forte, sed confractum: et dejiciam gladium de manu ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 23, 'et dispergam \'gyptum in gentibus, et ventilabo eos in terris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 24, 'Et confortabo brachia regis Babylonis, daboque gladium meum in manu ejus, et confringam brachia Pharaonis, et gement gemitibus interfecti coram facie ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 25, 'Et confortabo brachia regis Babylonis, et brachia Pharaonis concident: et scient quia ego Dominus, cum dedero gladium meum in manu regis Babylonis, et extenderit eum super terram \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 30, 26, 'Et dispergam \'gyptum in nationes, et ventilabo eos in terras: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 1, 'Et factum est in anno undecimo, tertio mense, una mensis: factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 2, 'Fili hominis, dic Pharaoni regi \'gypti et populo ejus: Cui similis factus es in magnitudine tua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 3, 'ecce Assur quasi cedrus in Libano, pulcher ramis, et frondibus nemorosus, excelsusque altitudine, et inter condensas frondes elevatum est cacumen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 4, 'Aquæ nutrierunt illum; abyssus exaltavit illum: flumina ejus manabant in circuitu radicum ejus, et rivos suos emisit ad universa ligna regionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 5, 'Propterea elevata est altitudo ejus super omnia ligna regionis, et multiplicata sunt arbusta ejus, et elevati sunt rami ejus præ aquis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 6, 'Cumque extendisset umbram suam, in ramis ejus fecerunt nidos omnia volatilia cæli: et sub frondibus ejus genuerunt omnes bestiæ saltuum, et sub umbraculo illius habitabat cœtus gentium plurimarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 7, 'Eratque pulcherrimus in magnitudine sua, et in dilatatione arbustorum suorum: erat enim radix illius juxta aquas multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 8, 'Cedri non fuerunt altiores illo in paradiso Dei; abietes non adæquaverunt summitatem ejus, et platani non fuerunt æquæ frondibus illius: omne lignum paradisi Dei non est assimilatum illi, et pulchritudini ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 9, 'Quoniam speciosum feci eum, et multis condensisque frondibus, et æmulata sunt eum omnia ligna voluptatis quæ erant in paradiso Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 10, 'Propterea hæc dicit Dominus Deus: Pro eo quod sublimatus est in altitudine, et dedit summitatem suam virentem atque condensam, et elevatum est cor ejus in altitudine sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 11, 'tradidi eum in manu fortissimi gentium: faciens faciet ei: juxta impietatem ejus ejeci eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 12, 'Et succident eum alieni, et crudelissimi nationum, et projicient eum super montes: et in cunctis convallibus corruent rami ejus, et confringentur arbusta ejus in universis rupibus terræ: et recedent de umbraculo ejus omnes populi terræ, et relinquent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 13, 'In ruina ejus habitaverunt omnia volatilia cæli, et in ramis ejus fuerunt universæ bestiæ regionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 14, 'Quam ob rem non elevabuntur in altitudine sua omnia ligna aquarum, nec ponent sublimitatem suam inter nemorosa atque frondosa, nec stabunt in sublimitate sua omnia quæ irrigantur aquis: quia omnes traditi sunt in mortem ad terram ultimam, in medio filiorum hominum, ad eos qui descendunt in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 15, 'Hæc dicit Dominus Deus: In die quando descendit ad inferos, induxi luctum: operui eum abysso, et prohibui flumina ejus, et coërcui aquas multas: contristatus est super eum Libanus, et omnia ligna agri concussa sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 16, 'A sonitu ruinæ ejus commovi gentes cum deducerem eum ad infernum cum his qui descendebant in lacum: et consolata sunt in terra infima omnia ligna voluptatis egregia atque præclara in Libano, universa quæ irrigabantur aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 17, 'Nam et ipsi cum eo descendent in infernum ad interfectos gladio: et brachium uniuscujusque sedebit sub umbraculo ejus in medio nationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 31, 18, 'Cui assimilatus es, o inclyte atque sublimis inter ligna voluptatis? ecce deductus es cum lignis voluptatis ad terram ultimam: in medio incircumcisorum dormies, cum eis qui interfecti sunt gladio: ipse est Pharao, et omnis multitudo ejus, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 1, 'Et factum est, duodecimo anno, in mense duodecimo, in una mensis: factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 2, 'Fili hominis, assume lamentum super Pharaonem regem \'gypti, et dices ad eum: Leoni gentium assimilatus es, et draconi qui est in mari: et ventilabas cornu in fluminibus tuis, et conturbabas aquas pedibus tuis, et conculcabas flumina earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 3, 'Propterea hæc dicit Dominus Deus: Expandam super te rete meum in multitudine populorum multorum, et extraham te in sagena mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 4, 'Et projiciam te in terram; super faciem agri abjiciam te: et habitare faciam super te omnia volatilia cæli, et saturabo de te bestias universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 5, 'Et dabo carnes tuas super montes, et implebo colles tuos sanie tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 6, 'Et irrigabo terram fœtore sanguinis tui super montes, et valles implebuntur ex te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 7, 'Et operiam, cum extinctus fueris, cælum, et nigrescere faciam stellas ejus: solem nube tegam, et luna non dabit lumen suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 8, 'Omnia luminaria cæli mœrere faciam super te, et dabo tenebras super terram tuam, dicit Dominus Deus, cum ceciderint vulnerati tui in medio terræ, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 9, 'Et irritabo cor populorum multorum, cum induxero contritionem tuam in gentibus super terras quas nescis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 10, 'Et stupescere faciam super te populos multos, et reges eorum horrore nimio formidabunt super te, cum volare cœperit gladius meus super facies eorum: et obstupescent repente singuli pro anima sua in die ruinæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 11, 'Quia hæc dicit Dominus Deus: Gladius regis Babylonis veniet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 12, 'In gladiis fortium dejiciam multitudinem tuam: inexpugnabiles omnes gentes hæ, et vastabunt superbiam \'gypti, et dissipabitur multitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 13, 'Et perdam omnia jumenta ejus, quæ erant super aquas plurimas: et non conturbabit eas pes hominis ultra, neque ungula jumentorum turbabit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 14, 'Tunc purissimas reddam aquas eorum, et flumina eorum quasi oleum adducam, ait Dominus Deus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 15, 'cum dedero terram \'gypti desolatam: deseretur autem terra a plenitudine sua quando percussero omnes habitatores ejus: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 16, 'Planctus est, et plangent eum: filiæ gentium plangent eum: super \'gyptum et super multitudinem ejus plangent eum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 17, 'Et factum est in duodecimo anno, in quintadecima mensis: factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 18, 'Fili hominis, cane lugubre super multitudinem \'gypti: et detrahe eam ipsam, et filias gentium robustarum, ad terram ultimam, cum his qui descendunt in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 19, 'Quo pulchrior es? descende, et dormi cum incircumcisis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 20, 'In medio interfectorum gladio cadent; gladius datus est: attraxerunt eam et omnes populos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 21, 'Loquentur ei potentissimi robustorum de medio inferni, qui cum auxiliatoribus ejus descenderunt, et dormierunt incircumcisi interfecti gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 22, 'Ibi Assur, et omnis multitudo ejus: in circuitu illius sepulchra ejus, omnes interfecti, et qui ceciderunt gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 23, 'Quorum data sunt sepulchra in novissimis laci, et facta est multitudo ejus per gyrum sepulchri ejus: universi interfecti, cadentesque gladio, qui dederant quondam formidinem in terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 24, 'Ibi \'lam, et omnis multitudo ejus per gyrum sepulchri sui: omnes hi interfecti, ruentesque gladio, qui descenderunt incircumcisi ad terram ultimam; qui posuerunt terrorem suum in terra viventium, et portaverunt ignominiam suam cum his qui descendunt in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 25, 'In medio interfectorum posuerunt cubile ejus in universis populis ejus: in circuitu ejus sepulchrum illius: omnes hi incircumcisi, interfectique gladio. Dederunt enim terrorem suum in terra viventium, et portaverunt ignominiam suam cum his qui descendunt in lacum: in medio interfectorum positi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 26, 'Ibi Mosoch et Thubal, et omnis multitudo ejus: in circuitu ejus sepulchra illius: omnes hi incircumcisi, interfectique et cadentes gladio, quia dederunt formidinem suam in terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 27, 'Et non dormient cum fortibus, cadentibusque, et incircumcisis, qui descenderunt ad infernum cum armis suis, et posuerunt gladios suos sub capitibus suis, et fuerunt iniquitates eorum in ossibus eorum: quia terror fortium facti sunt in terra viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 28, 'Et tu ergo in medio incircumcisorum contereris, et dormies cum interfectis gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 29, 'Ibi Idumæa, et reges ejus, et omnes duces ejus, qui dati sunt cum exercitu suo cum interfectis gladio, et qui cum incircumcisis dormierunt, et cum his qui descendunt in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 30, 'Ibi principes aquilonis omnes, et universi venatores, qui deducti sunt cum interfectis, paventes, et in sua fortitudine confusi: qui dormierunt incircumcisi cum interfectis gladio, et portaverunt confusionem suam cum his qui descendunt in lacum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 31, 'Vidit eos Pharao, et consolatus est super universa multitudine sua, quæ interfecta est gladio: Pharao, et omnis exercitus ejus, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 32, 32, 'Quia dedi terrorem meum in terra viventium, et dormivit in medio incircumcisorum cum interfectis gladio: Pharao, et omnis multitudo ejus, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 2, 'Fili hominis, loquere ad filios populi tui, et dices ad eos: Terra, cum induxero super eam gladium, et tulerit populus terræ virum unum de novissimis suis, et constituerit eum super se speculatorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 3, 'et ille viderit gladium venientem super terram, et cecinerit buccina, et annuntiaverit populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 4, 'audiens autem quisquis ille est sonitum buccinæ, et non se observaverit, veneritque gladius, et tulerit eum: sanguis ipsius super caput ejus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 5, 'Sonum buccinæ audivit, et non se observavit: sanguis ejus in ipso erit. Si autem se custodierit, animam suam salvabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 6, 'Quod si speculator viderit gladium venientem, et non insonuerit buccina, et populus se non custodierit, veneritque gladius, et tulerit de eis animam: ille quidem in iniquitate sua captus est; sanguinem autem ejus de manu speculatoris requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 7, 'Et tu, fili hominis, speculatorem dedi te domui Israël: audiens ergo ex ore meo sermonem, annuntiabis eis ex me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 8, 'Si me dicente ad impium: Impie, morte morieris: non fueris locutus ut se custodiat impius a via sua, ipse impius in iniquitate sua morietur; sanguinem autem ejus de manu tua requiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 9, 'Si autem annuntiante te ad impium ut a viis suis convertatur, non fuerit conversus a via sua, ipse in iniquitate sua morietur, porro tu animam tuam liberasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 10, 'Tu ergo, fili hominis, dic ad domum Israël: Sic locuti estis, dicentes: Iniquitates nostræ et peccata nostra super nos sunt, et in ipsis nos tabescimus: quomodo ergo vivere poterimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 11, 'Dic ad eos: Vivo ego, dicit Dominus Deus, nolo mortem impii, sed ut convertatur impius a via sua, et vivat. Convertimini, convertimini a viis vestris pessimis, et quare moriemini, domus Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 12, 'Tu itaque, fili hominis, dic ad filios populi tui: Justitia justi non liberabit eum, in quacumque die peccaverit, et impietas impii non nocebit ei, in quacumque die conversus fuerit ab impietate sua: et justus non poterit vivere in justitia sua, in quacumque die peccaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 13, 'Etiamsi dixero justo quod vita vivat, et confisus in justitia sua fecerit iniquitatem, omnes justitiæ ejus oblivioni tradentur, et in iniquitate sua quam operatus est, in ipsa morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 14, 'Si autem dixero impio: Morte morieris: et egerit pœnitentiam a peccato suo, feceritque judicium et justitiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 15, 'et pignus restituerit ille impius, rapinamque reddiderit, in mandatis vitæ ambulaverit, nec fecerit quidquam injustum: vita vivet, et non morietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 16, 'Omnia peccata ejus quæ peccavit, non imputabuntur ei: judicium et justitiam fecit: vita vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 17, 'Et dixerunt filii populi tui: Non est æqui ponderis via Domini: et ipsorum via injusta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 18, 'Cum enim recesserit justus a justitia sua, feceritque iniquitates, morietur in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 19, 'Et cum recesserit impius ab impietate sua, feceritque judicium et justitiam, vivet in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 20, 'Et dicitis: Non est recta via Domini. Unumquemque juxta vias suas judicabo de vobis, domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 21, 'Et factum est in duodecimo anno, in decimo mense, in quinta mensis transmigrationis nostræ, venit ad me qui fugerat de Jerusalem, dicens: Vastata est civitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 22, 'Manus autem Domini facta fuerat ad me vespere, antequam veniret qui fugerat: aperuitque os meum donec veniret ad me mane: et aperto ore meo, non silui amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 23, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 24, 'Fili hominis, qui habitant in ruinosis his super humum Israël, loquentes aiunt: Unus erat Abraham, et hæreditate possedit terram: nos autem multi sumus: nobis data est terra in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 25, 'Idcirco dices ad eos: Hæc dicit Dominus Deus: Qui in sanguine comeditis, et oculos vestros levatis ad immunditias vestras, et sanguinem funditis, numquid terram hæreditate possidebitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 26, 'stetistis in gladiis vestris, fecistis abominationes, et unusquisque uxorem proximi sui polluit: et terram hæreditate possidebitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 27, 'Hæc dices ad eos: Sic dicit Dominus Deus: Vivo ego, quia qui in ruinosis habitant, gladio cadent: et qui in agro est, bestiis tradetur ad devorandum: qui autem in præsidiis et speluncis sunt, peste morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 28, 'Et dabo terram in solitudinem et in desertum, et deficiet superba fortitudo ejus: et desolabuntur montes Israël, eo quod nullus sit qui per eos transeat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 29, 'et scient quia ego Dominus, cum dedero terram eorum desolatam et desertam, propter universas abominationes suas quas operati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 30, 'Et tu, fili hominis, filii populi tui, qui loquuntur de te juxta muros et in ostiis domorum, et dicunt unus ad alterum, vir ad proximum suum, loquentes: Venite, et audiamus quis sit sermo egrediens a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 31, 'Et veniunt ad te, quasi si ingrediatur populus, et sedent coram te populus meus: et audiunt sermones tuos, et non faciunt eos: quia in canticum oris sui vertunt illos, et avaritiam suam sequitur cor eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 32, 'Et es eis quasi carmen musicum, quod suavi dulcique sono canitur: et audiunt verba tua, et non faciunt ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 33, 33, 'Et cum venerit quod prædictum est (ecce enim venit), tunc scient quod prophetes fuerit inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 1, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 2, 'Fili hominis, propheta de pastoribus Israël: propheta, et dices pastoribus: Hæc dicit Dominus Deus: Væ pastoribus Israël, qui pascebant semetipsos! nonne greges a pastoribus pascuntur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 3, 'Lac comedebatis, et lanis operiebamini, et quod crassum erat occidebatis: gregem autem meum non pascebatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 4, 'Quod infirmum fuit non consolidastis, et quod ægrotum non sanastis: quod confractum est non alligastis, et quod abjectum est non reduxistis, et quod perierat non quæsistis: sed cum austeritate imperabatis eis, et cum potentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 5, 'Et dispersæ sunt oves meæ, eo quod non esset pastor: et factæ sunt in devorationem omnium bestiarum agri, et dispersæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 6, 'Erraverunt greges mei in cunctis montibus, et in universo colle excelso: et super omnem faciem terræ dispersi sunt greges mei, et non erat qui requireret: non erat, inquam, qui requireret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 7, 'Propterea, pastores, audite verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 8, 'Vivo ego, dicit Dominus Deus, quia pro eo quod facti sunt greges mei in rapinam, et oves meæ in devorationem omnium bestiarum agri, eo quod non esset pastor: neque enim quæsierunt pastores mei gregem meum, sed pascebant pastores semetipsos, et greges meos non pascebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 9, 'propterea, pastores, audite verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 10, 'Hæc dicit Dominus Deus: Ecce ego ipse super pastores: requiram gregem meum de manu eorum, et cessare faciam eos, ut ultra non pascant gregem, nec pascant amplius pastores semetipsos: et liberabo gregem meum de ore eorum, et non erit ultra eis in escam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 11, 'Quia hæc dicit Dominus Deus: Ecce ego ipse requiram oves meas, et visitabo eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 12, 'Sicut visitat pastor gregem suum, in die quando fuerit in medio ovium suarum dissipatarum, sic visitabo oves meas, et liberabo eas de omnibus locis in quibus dispersæ fuerant in die nubis et caliginis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 13, 'Et educam eas de populis, et congregabo eas de terris, et inducam eas in terram suam, et pascam eas in montibus Israël, in rivis, et in cunctis sedibus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 14, 'In pascuis uberrimis pascam eas, et in montibus excelsis Israël erunt pascua earum: ibi requiescent in herbis virentibus, et in pascuis pinguibus pascentur super montes Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 15, 'Ego pascam oves meas, et ego eas accubare faciam, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 16, 'Quod perierat requiram, et quod abjectum erat reducam, et quod confractum fuerat alligabo, et quod infirmum fuerat consolidabo, et quod pingue et forte custodiam: et pascam illas in judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 17, 'Vos autem, greges mei, hæc dicit Dominus Deus: Ecce ego judico inter pecus et pecus, arietum et hircorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 18, 'Nonne satis vobis erat pascua bona depasci? insuper et reliquias pascuarum vestrarum conculcastis pedibus vestris: et cum purissimam aquam biberetis, reliquam pedibus vestris turbabatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 19, 'et oves meæ his quæ conculcata pedibus vestris fuerant, pascebantur: et quæ pedes vestri turbaverant, hæc bibebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 20, 'Propterea hæc dicit Dominus Deus ad vos: Ecce ego ipse judico inter pecus pingue et macilentum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 21, 'pro eo quod lateribus et humeris impingebatis, et cornibus vestris ventilabatis omnia infirma pecora, donec dispergerentur foras,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 22, 'salvabo gregem meum, et non erit ultra in rapinam, et judicabo inter pecus et pecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 23, 'Et suscitabo super eas pastorem unum qui pascat eas, servum meum David: ipse pascet eas, et ipse erit eis in pastorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 24, 'Ego autem Dominus ero eis in Deum, et servus meus David princeps in medio eorum: ego Dominus locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 25, 'Et faciam cum eis pactum pacis, et cessare faciam bestias pessimas de terra: et qui habitant in deserto, securi dormient in saltibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 26, 'Et ponam eos in circuitu collis mei benedictionem, et deducam imbrem in tempore suo: pluviæ benedictionis erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 27, 'Et dabit lignum agri fructum suum, et terra dabit germen suum, et erunt in terra sua absque timore: et scient quia ego Dominus, cum contrivero catenas jugi eorum, et eruero eos de manu imperantium sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 28, 'Et non erunt ultra in rapinam in gentibus, neque bestiæ terræ devorabunt eos: sed habitabunt confidenter absque ullo terrore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 29, 'Et suscitabo eis germen nominatum, et non erunt ultra imminuti fame in terra, neque portabunt ultra opprobrium gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 30, 'Et scient quia ego Dominus Deus eorum cum eis, et ipsi populus meus domus Israël, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 34, 31, 'Vos autem, greges mei, greges pascuæ meæ, homines estis: et ego Dominus Deus vester, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 2, 'Fili hominis, pone faciem tuam adversum montem Seir, et prophetabis de eo, et dices illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 3, 'Hæc dicit Dominus Deus: Ecce ego ad te, mons Seir: et extendam manum meam super te, et dabo te desolatum atque desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 4, 'Urbes tuas demoliar, et tu desertus eris: et scies quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 5, 'Eo quod fueris inimicus sempiternus, et concluseris filios Israël in manus gladii in tempore afflictionis eorum, in tempore iniquitatis extremæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 6, 'propterea vivo ego, dicit Dominus Deus, quoniam sanguini tradam te, et sanguis te persequetur: et cum sanguinem oderis, sanguis persequetur te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 7, 'Et dabo montem Seir desolatum atque desertum, et auferam de eo euntem et redeuntem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 8, 'Et implebo montes ejus occisorum suorum: in collibus tuis, et in vallibus tuis atque in torrentibus, interfecti gladio cadent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 9, 'In solitudines sempiternas tradam te, et civitates tuæ non habitabuntur: et scietis quia ego Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 10, 'Eo quod dixeris: Duæ gentes et duæ terræ meæ erunt, et hæreditate possidebo eas, cum Dominus esset ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 11, 'propterea vivo ego, dicit Dominus Deus, quia faciam juxta iram tuam, et secundum zelum tuum, quem fecisti odio habens eos: et notus efficiar per eos, cum te judicavero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 12, 'Et scies quia ego Dominus audivi universa opprobria tua quæ locutus es de montibus Israël, dicens: Deserti nobis ad devorandum dati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 13, 'Et insurrexistis super me ore vestro, et derogastis adversum me verba vestra: ego audivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 14, 'Hæc dicit Dominus Deus: Lætante universa terra, in solitudinem te redigam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 35, 15, 'sicuti gavisus es super hæreditatem domus Israël eo quod fuerit dissipata, sic faciam tibi: dissipatus eris, mons Seir, et Idumæa omnis: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 1, 'Tu autem, fili hominis, propheta super montes Israël, et dices: Montes Israël, audite verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 2, 'Hæc dicit Dominus Deus: Eo quod dixerit inimicus de vobis: Euge, altitudines sempiternæ in hæreditatem datæ sunt nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 3, 'propterea vaticinare, et dic: Hæc dicit Dominus Deus: Pro eo quod desolati estis, et conculcati per circuitum, et facti in hæreditatem reliquis gentibus, et ascendistis super labium linguæ et opprobrium populi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 4, 'propterea, montes Israël, audite verbum Domini Dei. Hæc dicit Dominus Deus montibus et collibus, torrentibus, vallibusque et desertis, parietinis et urbibus derelictis, quæ depopulatæ sunt et subsannatæ a reliquis gentibus per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 5, 'Propterea hæc dicit Dominus Deus: Quoniam in igne zeli mei locutus sum de reliquis gentibus, et de Idumæa universa, quæ dederunt terram meam sibi in hæreditatem cum gaudio, et toto corde et ex animo, et ejecerunt eam ut vastarent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 6, 'idcirco vaticinare super humum Israël, et dices montibus et collibus, jugis et vallibus: Hæc dicit Dominus Deus: Ecce ego in zelo meo et in furore meo locutus sum, eo quod confusionem gentium sustinueritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 7, 'Idcirco hæc dicit Dominus Deus: Ego levavi manum meam, ut gentes quæ in circuitu vestro sunt, ipsæ confusionem suam portent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 8, 'Vos autem, montes Israël, ramos vestros germinetis, et fructum vestrum afferatis populo meo Israël: prope enim est ut veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 9, 'Quia ecce ego ad vos, et convertar ad vos: et arabimini, et accipietis sementem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 10, 'Et multiplicabo in vobis homines, omnemque domum Israël: et habitabuntur civitates, et ruinosa instaurabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 11, 'Et replebo vos hominibus et jumentis, et multiplicabuntur, et crescent: et habitare vos faciam sicut a principio, bonisque donabo majoribus quam habuistis ab initio: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 12, 'Et adducam super vos homines, populum meum Israël, et hæreditate possidebunt te: et eris eis in hæreditatem, et non addes ultra ut absque eis sis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 13, 'Hæc dicit Dominus Deus: Pro eo quod dicunt de vobis: Devoratrix hominum es, et suffocans gentem tuam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 14, 'propterea homines non comedes amplius, et gentem tuam non necabis ultra, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 15, 'Nec auditam faciam in te amplius confusionem gentium, et opprobrium populorum nequaquam portabis: et gentem tuam non amittes amplius, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 16, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 17, 'Fili hominis, domus Israël habitaverunt in humo sua, et polluerunt eam in viis suis et in studiis suis: juxta immunditiam menstruatæ facta est via eorum coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 18, 'Et effudi indignationem meam super eos pro sanguine quem fuderunt super terram, et in idolis suis polluerunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 19, 'Et dispersi eos in gentes, et ventilati sunt in terras: juxta vias eorum et adinventiones eorum judicavi eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 20, 'Et ingressi sunt ad gentes ad quas introierunt: et polluerunt nomen sanctum meum, cum diceretur de eis: Populus Domini iste est, et de terra ejus egressi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 21, 'Et peperci nomini sancto meo, quod polluerat domus Israël in gentibus ad quas ingressi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 22, 'Idcirco dices domui Israël: Hæc dicit Dominus Deus: Non propter vos ego faciam, domus Israël, sed propter nomen sanctum meum, quod polluistis in gentibus ad quas intrastis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 23, 'Et sanctificabo nomen meum magnum quod pollutum est inter gentes, quod polluistis in medio earum: ut sciant gentes quia ego Dominus, ait Dominus exercituum, cum sanctificatus fuero in vobis coram eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 24, 'Tollam quippe vos de gentibus, et congregabo vos de universis terris, et adducam vos in terram vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 25, 'Et effundam super vos aquam mundam, et mundabimini ab omnibus inquinamentis vestris, et ab universis idolis vestris mundabo vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 26, 'Et dabo vobis cor novum, et spiritum novum ponam in medio vestri: et auferam cor lapideum de carne vestra, et dabo vobis cor carneum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 27, 'Et spiritum meum ponam in medio vestri: et faciam ut in præceptis meis ambuletis, et judicia mea custodiatis et operemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 28, 'Et habitabitis in terra quam dedi patribus vestris: et eritis mihi in populum, et ego ero vobis in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 29, 'Et salvabo vos ex universis inquinamentis vestris: et vocabo frumentum et multiplicabo illud, et non imponam vobis famem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 30, 'Et multiplicabo fructum ligni, et genimina agri, ut non portetis ultra opprobrium famis in gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 31, 'Et recordabimini viarum vestrarum pessimarum, studiorumque non bonorum: et displicebunt vobis iniquitates vestræ et scelera vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 32, 'Non propter vos ego faciam, ait Dominus Deus, notum sit vobis: confundimini, et erubescite super viis vestris, domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 33, 'Hæc dicit Dominus Deus: In die qua mundavero vos ex omnibus iniquitatibus vestris, et inhabitari fecero urbes, et instauravero ruinosa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 34, 'et terra deserta fuerit exculta, quæ quondam erat desolata in oculis omnis viatoris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 35, 'dicent: Terra illa inculta facta est ut hortus voluptatis: et civitates desertæ, et destitutæ atque suffossæ, munitæ sederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 36, 'Et scient gentes quæcumque derelictæ fuerint in circuitu vestro, quia ego Dominus ædificavi dissipata, plantavique inculta: ego Dominus locutus sim, et fecerim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 37, 'Hæc dicit Dominus Deus: Adhuc in hoc invenient me domus Israël, ut faciam eis: multiplicabo eos sicut gregem hominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 36, 38, 'ut gregem sanctum, ut gregem Jerusalem in solemnitatibus ejus: sic erunt civitates desertæ, plenæ gregibus hominum: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 1, 'Facta est super me manus Domini, et eduxit me in spiritu Domini, et dimisit me in medio campi qui erat plenus ossibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 2, 'Et circumduxit me per ea in gyro: erant autem multa valde super faciem campi, siccaque vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 3, 'Et dixit ad me: Fili hominis, putasne vivent ossa ista? Et dixi: Domine Deus, tu nosti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 4, 'Et dixit ad me: Vaticinare de ossibus istis, et dices eis: Ossa arida, audite verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 5, 'Hæc dicit Dominus Deus ossibus his: Ecce ego intromittam in vos spiritum, et vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 6, 'Et dabo super vos nervos, et succrescere faciam super vos carnes, et superextendam in vobis cutem, et dabo vobis spiritum, et vivetis: et scietis quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 7, 'Et prophetavi sicut præceperat mihi: factus est autem sonitus, prophetante me, et ecce commotio: et accesserunt ossa ad ossa, unumquodque ad juncturam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 8, 'Et vidi, et ecce super ea nervi et carnes ascenderunt, et extenta est in eis cutis desuper: et spiritum non habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 9, 'Et dixit ad me: Vaticinare ad spiritum: vaticinare, fili hominis, et dices ad spiritum: Hæc dicit Dominus Deus: A quatuor ventis veni, spiritus, et insuffla super interfectos istos, et reviviscant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 10, 'Et prophetavi sicut præceperat mihi: et ingressus est in ea spiritus, et vixerunt: steteruntque super pedes suos, exercitus grandis nimis valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 11, 'Et dixit ad me: Fili hominis, ossa hæc universa, domus Israël est. Ipsi dicunt: Aruerunt ossa nostra, et periit spes nostra, et abscissi sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 12, 'Propterea vaticinare, et dices ad eos: Hæc dicit Dominus Deus: Ecce ego aperiam tumulos vestros, et educam vos de sepulchris vestris, populus meus, et inducam vos in terram Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 13, 'Et scietis quia ego Dominus, cum aperuero sepulchra vestra, et eduxero vos de tumulis vestris, popule meus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 14, 'et dedero spiritum meum in vobis, et vixeritis: et requiescere vos faciam super humum vestram, et scietis quia ego Dominus locutus sum, et feci, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 15, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 16, 'Et tu, fili hominis, sume tibi lignum unum, et scribe super illud: Judæ, et filiorum Israël sociorum ejus: et tolle lignum alterum, et scribe super illud: Joseph, ligno Ephraim, et cunctæ domui Israël sociorumque ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 17, 'Et adjunge illa unum ad alterum tibi in lignum unum: et erunt in unionem in manu tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 18, 'Cum autem dixerint ad te filii populi tui, loquentes: Nonne indicas nobis quid in his tibi velis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 19, 'loqueris ad eos: Hæc dicit Dominus Deus: Ecce ego assumam lignum Joseph, quod est in manu Ephraim, et tribus Israël, quæ sunt ei adjunctæ, et dabo eas pariter cum ligno Juda, et faciam eas in lignum unum: et erunt unum in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 20, 'Erunt autem ligna super quæ scripseris in manu tua in oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 21, 'Et dices ad eos: Hæc dicit Dominus Deus: Ecce ego assumam filios Israël de medio nationum ad quas abierunt: et congregabo eos undique, et adducam eos ad humum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 22, 'Et faciam eos in gentem unam in terra in montibus Israël, et rex unus erit omnibus imperans: et non erunt ultra duæ gentes, nec dividentur amplius in duo regna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 23, 'neque polluentur ultra in idolis suis, et abominationibus suis, et cunctis iniquitatibus suis: et salvos eos faciam de universis sedibus in quibus peccaverunt, et emundabo eos: et erunt mihi populus, et ego ero eis Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 24, 'Et servus meus David rex super eos, et pastor unus erit omnium eorum. In judiciis meis ambulabunt, et mandata mea custodient, et facient ea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 25, 'et habitabunt super terram quam dedi servo meo Jacob, in qua habitaverunt patres vestri: et habitabunt super eam ipsi, et filii eorum, et filii filiorum eorum, usque in sempiternum: et David servus meus princeps eorum in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 26, 'Et percutiam illis fœdus pacis: pactum sempiternum erit eis. Et fundabo eos, et multiplicabo, et dabo sanctificationem meam in medio eorum in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 27, 'Et erit tabernaculum meum in eis: et ero eis Deus, et ipsi erunt mihi populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 37, 28, 'Et scient gentes quia ego Dominus sanctificator Israël, cum fuerit sanctificatio mea in medio eorum in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 1, 'Et factus est sermo Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 2, 'Fili hominis, pone faciem tuam contra Gog, terram Magog, principem capitis Mosoch et Thubal, et vaticinare de eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 3, 'Et dices ad eum: Hæc dicit Dominus Deus: Ecce ego ad te, Gog, principem capitis Mosoch et Thubal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 4, 'Et circumagam te, et ponam frenum in maxillis tuis: et educam te, et omnem exercitum tuum, equos et equites vestitos loricis universos, multitudinem magnam, hastam et clypeum arripientium et gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 5, 'Persæ, \'thiopes, et Libyes cum eis, omnes scutati et galeati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 6, 'Gomer et universa agmina ejus, domus Thogorma, latera aquilonis, et totum robur ejus, populique multi tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 7, 'Præpara et instrue te, et omnem multitudinem tuam quæ coacervata est ad te: et esto eis in præceptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 8, 'Post dies multos visitaberis: in novissimo annorum venies ad terram quæ reversa est a gladio, et congregata est de populis multis ad montes Israël, qui fuerunt deserti jugiter: hæc de populis educta est, et habitabunt in ea confidenter universi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 9, 'Ascendens autem quasi tempestas venies, et quasi nubes, ut operias terram: tu et omnia agmina tua, et populi multi tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 10, 'Hæc dicit Dominus Deus: In die illa, ascendent sermones super cor tuum, et cogitabis cogitationem pessimam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 11, 'et dices: Ascendam ad terram absque muro: veniam ad quiescentes habitantesque secure: hi omnes habitant sine muro; vectes et portæ non sunt eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 12, 'ut diripias spolia, et invadas prædam; ut inferas manum tuam super eos qui deserti fuerant, et postea restituti, et super populum qui est congregatus ex gentibus, qui possidere cœpit et esse habitator umbilici terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 13, 'Saba, et Dedan, et negotiatores Tharsis, et omnes leones ejus, dicent tibi: Numquid ad sumenda spolia tu venis? ecce ad diripiendam prædam congregasti multitudinem tuam, ut tollas argentum et aurum, et auferas supellectilem atque substantiam, et diripias manubias infinitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 14, 'Propterea vaticinare, fili hominis, et dices ad Gog: Hæc dicit Dominus Deus: Numquid non in die illo, cum habitaverit populus meus Israël confidenter, scies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 15, 'Et venies de loco tuo a lateribus aquilonis, tu et populi multi tecum, ascensores equorum universi: cœtus magnus, et exercitus vehemens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 16, 'Et ascendes super populum meum Israël quasi nubes, ut operias terram. In novissimis diebus eris, et adducam te super terram meam: ut sciant gentes me cum sanctificatus fuero in te in oculis eorum, o Gog!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 17, 'Hæc dicit Dominus Deus: Tu ergo ille es, de quo locutus sum in diebus antiquis in manu servorum meorum prophetarum Israël, qui prophetaverunt in diebus illorum temporum, ut adducerem te super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 18, 'Et erit in die illa, in die adventus Gog super terram Israël, ait Dominus Deus, ascendet indignatio mea in furore meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 19, 'Et in zelo meo, in igne iræ meæ locutus sum, quia in die illa erit commotio magna super terram Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 20, 'et commovebuntur a facie mea pisces maris, et volucres cæli, et bestiæ agri, et omne reptile quod movetur super humum, cunctique homines qui sunt super faciem terræ: et subvertentur montes, et cadent sepes, et omnis murus corruet in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 21, 'Et convocabo adversus eum in cunctis montibus meis gladium, ait Dominus Deus: gladius uniuscujusque in fratrem suum dirigetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 22, 'Et judicabo eum peste, et sanguine, et imbre vehementi, et lapidibus immensis: ignem et sulphur pluam super eum, et super exercitum ejus, et super populos multos qui sunt cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 38, 23, 'Et magnificabor, et sanctificabor, et notus ero in oculis multarum gentium: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 1, 'Tu autem, fili hominis, vaticinare adversum Gog, et dices: Hæc dicit Dominus Deus: Ecce ego super te, Gog, principem capitis Mosoch et Thubal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 2, 'Et circumagam te, et educam te, et ascendere te faciam de lateribus aquilonis, et adducam te super montes Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 3, 'Et percutiam arcum tuum in manu sinistra tua, et sagittas tuas de manu dextera tua dejiciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 4, 'Super montes Israël cades tu, et omnia agmina tua, et populi tui qui sunt tecum: feris, avibus, omnique volatili et bestiis terræ dedi te ad devorandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 5, 'Super faciem agri cades, quia ego locutus sum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 6, 'Et immittam ignem in Magog, et in his qui habitant in insulis confidenter: et scient quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 7, 'Et nomen sanctum meum notum faciam in medio populi mei Israël, et non polluam nomen sanctum meum amplius: et scient gentes quia ego Dominus, Sanctus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 8, 'Ecce venit, et factum est, ait Dominus Deus: hæc est dies de qua locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 9, 'Et egredientur habitatores de civitatibus Israël, et succendent et comburent arma, clypeum et hastas, arcum et sagittas, et baculos manuum et contos: et succendent ea igni septem annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 10, 'Et non portabunt ligna de regionibus, neque succident de saltibus: quoniam arma succendent igni, et deprædabuntur eos quibus prædæ fuerant, et diripient vastatores suos, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 11, 'Et erit in die illa: dabo Gog locum nominatum sepulchrum in Israël, vallem viatorum ad orientem maris, quæ obstupescere faciet prætereuntes: et sepelient ibi Gog, et omnem multitudinem ejus, et vocabitur vallis multitudinis Gog.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 12, 'Et sepelient eos domus Israël, ut mundent terram septem mensibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 13, 'Sepeliet autem eum omnis populus terræ: et erit eis nominata dies in qua glorificatus sum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 14, 'Et viros jugiter constituent lustrantes terram, qui sepeliant et requirant eos qui remanserant super faciem terræ, ut emundent eam: post menses autem septem quærere incipient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 15, 'Et circuibunt peragrantes terram: cumque viderint os hominis, statuent juxta illud titulum, donec sepeliant illud pollinctores in valle multitudinis Gog.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 16, 'Nomen autem civitatis Amona: et mundabunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 17, 'Tu ergo, fili hominis, hæc dicit Dominus Deus: Dic omni volucri, et universis avibus, cunctisque bestiis agri: Convenite, properate, concurrite undique ad victimam meam quam ego immolo vobis, victimam grandem super montes Israël, ut comedatis carnem, et bibatis sanguinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 18, 'Carnes fortium comedetis, et sanguinem principum terræ bibetis: arietum, et agnorum, et hircorum, taurorumque et altilium, et pinguium omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 19, 'Et comedetis adipem in saturitatem, et bibetis sanguinem in ebrietatem, de victima quam ego immolabo vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 20, 'et saturabimini super mensam meam de equo, et equite forti, et de universis viris bellatoribus, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 21, 'Et ponam gloriam meam in gentibus: et videbunt omnes gentes judicium meum quod fecerim, et manum meam quam posuerim super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 22, 'Et scient domus Israël quia ego Dominus Deus eorum, a die illa et deinceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 23, 'Et scient gentes quoniam in iniquitate sua capta sit domus Israël, eo quod dereliquerint me, et absconderim faciem meam ab eis, et tradiderim eos in manus hostium, et ceciderint in gladio universi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 24, 'Juxta immunditiam eorum et scelus feci eis, et abscondi faciem meam ab illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 25, 'Propterea hæc dicit Dominus Deus: Nunc reducam captivitatem Jacob, et miserebor omnis domus Israël, et assumam zelum pro nomine sancto meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 26, 'Et portabunt confusionem suam, et omnem prævaricationem qua prævaricati sunt in me, cum habitaverint in terra sua confidenter, neminem formidantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 27, 'et reduxero eos de populis, et congregavero de terris inimicorum suorum, et sanctificatus fuero in eis, in oculis gentium plurimarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 28, 'Et scient quia ego Dominus Deus eorum, eo quod transtulerim eos in nationes, et congregaverim eos super terram suam, et non dereliquerim quemquam ex eis ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 39, 29, 'Et non abscondam ultra faciem meam ab eis, eo quod effuderim spiritum meum super omnem domum Israël, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 1, 'In vigesimo quinto anno transmigrationis nostræ, in exordio anni, decima mensis, quartodecimo anno postquam percussa est civitas, in ipsa hac die, facta est super me manus Domini, et adduxit me illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 2, 'In visionibus Dei adduxit me in terram Israël, et dimisit me super montem excelsum nimis, super quem erat quasi ædificium civitatis vergentis ad austrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 3, 'Et introduxit me illuc: et ecce vir cujus erat species quasi species æris, et funiculus lineus in manu ejus, et calamus mensuræ in manu ejus: stabat autem in porta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 4, 'Et locutus est ad me idem vir: Fili hominis, vide oculis tuis, et auribus tuis audi, et pone cor tuum in omnia quæ ego ostendam tibi, quia ut ostendantur tibi adductus es huc. Annuntia omnia quæ tu vides domui Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 5, 'Et ecce murus forinsecus in circuitu domus undique: et in manu viri calamus mensuræ sex cubitorum et palmo: et mensus est latitudinem ædificii calamo uno, altitudinem quoque calamo uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 6, 'Et venit ad portam quæ respiciebat viam orientalem, et ascendit per gradus ejus: et mensus est limen portæ calamo uno latitudinem, id est, limen unum calamo uno in latitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 7, 'Et thalamum uno calamo in longum, et uno calamo in latum: et inter thalamos, quinque cubitos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 8, 'Et limen portæ, juxta vestibulum portæ intrinsecus, calamo uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 9, 'Et mensus est vestibulum portæ octo cubitorum, et frontem ejus duobus cubitis: vestibulum autem portæ erat intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 10, 'Porro thalami portæ ad viam orientalem, tres hinc et tres inde: mensura una trium, et mensura una frontium ex utraque parte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 11, 'Et mensus est latitudinem liminis portæ decem cubitorum, et longitudinem portæ tredecim cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 12, 'Et marginem ante thalamos, cubiti unius, et cubitus unus finis utrimque: thalami autem sex cubitorum erant hinc et inde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 13, 'Et mensus est portam a tecto thalami usque ad tectum ejus, latitudinem viginti quinque cubitorum, ostium contra ostium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 14, 'Et fecit frontes per sexaginta cubitos, et ad frontem atrium portæ undique per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 15, 'Et ante faciem portæ quæ pertingebat usque ad faciem vestibuli portæ interioris, quinquaginta cubitos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 16, 'Et fenestras obliquas in thalamis et in frontibus eorum, quæ erant intra portam undique per circuitum: similiter autem erant et in vestibulis fenestræ per gyrum intrinsecus, et ante frontes pictura palmarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 17, 'Et eduxit me ad atrium exterius: et ecce gazophylacia, et pavimentum stratum lapide in atrio per circuitum: triginta gazophylacia in circuitu pavimenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 18, 'Et pavimentum in fronte portarum, secundum longitudinem portarum erat inferius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 19, 'Et mensus est latitudinem a facie portæ inferioris usque ad frontem atrii interioris extrinsecus: centum cubitos ad orientem et ad aquilonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 20, 'Portam quoque quæ respiciebat viam aquilonis atrii exterioris, mensus est tam in longitudine quam in latitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 21, 'Et thalamos ejus tres hinc et tres inde, et frontem ejus et vestibulum ejus secundum mensuram portæ prioris, quinquaginta cubitorum longitudinem ejus, et latitudinem viginti quinque cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 22, 'Fenestræ autem ejus, et vestibulum, et sculpturæ secundum mensuram portæ quæ respiciebat ad orientem: et septem graduum erat ascensus ejus, et vestibulum ante eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 23, 'Et porta atrii interioris contra portam aquilonis et orientalem: et mensus est a porta usque ad portam centum cubitos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 24, 'Et eduxit me ad viam australem: et ecce porta quæ respiciebat ad austrum: et mensus est frontem ejus et vestibulum ejus juxta mensuras superiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 25, 'Et fenestras ejus, et vestibula in circuitu, sicut fenestras ceteras: quinquaginta cubitorum longitudine, et latitudine viginti quinque cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 26, 'Et in gradibus septem ascendebatur ad eam, et vestibulum ante fores ejus: et cælatæ palmæ erant, una hinc, et altera inde, in fronte ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 27, 'Et porta atrii interioris in via australi: et mensus est a porta usque ad portam in via australi, centum cubitos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 28, 'Et introduxit me in atrium interius ad portam australem: et mensus est portam juxta mensuras superiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 29, 'Thalamum ejus, et frontem ejus, et vestibulum ejus eisdem mensuris, et fenestras ejus, et vestibulum ejus in circuitu, quinquaginta cubitos longitudinis, et latitudinis viginti quinque cubitos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 30, 'Et vestibulum per gyrum longitudine viginti quinque cubitorum, et latitudine quinque cubitorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 31, 'et vestibulum ejus ad atrium exterius, et palmas ejus in fronte: et octo gradus erant quibus ascendebatur per eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 32, 'Et introduxit me in atrium interius, per viam orientalem: et mensus est portam secundum mensuras superiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 33, 'Thalamum ejus, et frontem ejus, et vestibulum ejus, sicut supra: et fenestras ejus, et vestibula ejus in circuitu, longitudine quinquaginta cubitorum, et latitudine viginti quinque cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 34, 'Et vestibulum ejus, id est, atrii exterioris, et palmæ cælatæ in fronte ejus, hinc et inde: et in octo gradibus ascensus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 35, 'Et introduxit me ad portam quæ respiciebat ad aquilonem: et mensus est secundum mensuras superiores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 36, 'Thalamum ejus, et frontem ejus, et vestibulum ejus, et fenestras ejus per circuitum, longitudine quinquaginta cubitorum, et latitudine viginti quinque cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 37, 'Et vestibulum ejus respiciebat ad atrium exterius: et cælatura palmarum in fronte ejus, hinc et inde: et in octo gradibus ascensus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 38, 'Et per singula gazophylacia ostium in frontibus portarum: ibi lavabant holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 39, 'Et in vestibulo portæ, duæ mensæ hinc, et duæ mensæ inde, ut immoletur super eas holocaustum, et pro peccato et pro delicto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 40, 'Et ad latus exterius, quod ascendit ad ostium portæ quæ pergit ad aquilonem, duæ mensæ: et ad latus alterum, ante vestibulum portæ, duæ mensæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 41, 'quatuor mensæ hinc, et quatuor mensæ inde: per latera portæ octo mensæ erant, super quas immolabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 42, 'Quatuor autem mensæ ad holocaustum de lapidibus quadris exstructæ, longitudine cubiti unius et dimidii, et latitudine cubiti unius et dimidii, et altitudine cubiti unius: super quas ponant vasa in quibus immolatur holocaustum et victima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 43, 'Et labia earum palmi unius, reflexa intrinsecus per circuitum: super mensas autem carnes oblationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 44, 'Et extra portam interiorem, gazophylacia cantorum in atrio interiori, quod erat in latere portæ respicientis ad aquilonem: et facies eorum contra viam australem: una ex latere portæ orientalis, quæ respiciebat ad viam aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 45, 'Et dixit ad me: Hoc est gazophylacium quod respicit viam meridianam: sacerdotum erit, qui excubant in custodiis templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 46, 'Porro gazophylacium quod respicit ad viam aquilonis, sacerdotum erit, qui excubant ad ministerium altaris: isti sunt filii Sadoc, qui accedunt de filiis Levi ad Dominum ut ministrent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 47, 'Et mensus est atrium longitudine centum cubitorum, et latitudine centum cubitorum per quadrum: et altare ante faciem templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 48, 'Et introduxit me in vestibulum templi: et mensus est vestibulum quinque cubitis hinc, et quinque cubitis inde: et latitudinem portæ trium cubitorum hinc, et trium cubitorum inde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 40, 49, 'Longitudinem autem vestibuli viginti cubitorum, et latitudinem undecim cubitorum, et octo gradibus ascendebatur ad eam. Et columnæ erant in frontibus: una hinc, et altera inde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 1, 'Et introduxit me in templum, et mensus est frontes: sex cubitos latitudinis hinc, et sex cubitos latitudinis inde, latitudinem tabernaculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 2, 'Et latitudo portæ decem cubitorum erat: et latera portæ, quinque cubitis hinc, et quinque cubitis inde: et mensus est longitudinem ejus quadraginta cubitorum, et latitudinem viginti cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 3, 'Et introgressus intrinsecus, mensus est in fronte portæ duos cubitos: et portam, sex cubitorum: et latitudinem portæ septem cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 4, 'Et mensus est longitudinem ejus viginti cubitorum, et latitudinem ejus viginti cubitorum, ante faciem templi. Et dixit ad me: Hoc est Sanctum sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 5, 'Et mensus est parietem domus sex cubitorum: et latitudinem lateris quatuor cubitorum undique per circuitum domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 6, 'Latera autem, latus ad latus, bis triginta tria: et erant eminentia, quæ ingrederentur per parietem domus, in lateribus per circuitum, ut continerent, et non attingerent parietem templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 7, 'Et platea erat in rotundum, ascendens sursum per cochleam, et in cœnaculum templi deferebat per gyrum: idcirco latius erat templum in superioribus: et sic de inferioribus ascendebatur ad superiora in medium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 8, 'Et vidi in domo altitudinem per circuitum, fundata latera ad mensuram calami sex cubitorum spatio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 9, 'et latitudinem per parietem lateris forinsecus quinque cubitorum: et erat interior domus in lateribus domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 10, 'Et inter gazophylacia latitudinem viginti cubitorum in circuitu domus undique,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 11, 'et ostium lateris ad orationem: ostium unum ad viam aquilonis, et ostium unum ad viam australem: et latitudinem loci ad orationem, quinque cubitorum in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 12, 'Et ædificium, quod erat separatum, versumque ad viam respicientem ad mare, latitudinis septuaginta cubitorum: paries autem ædificii, quinque cubitorum latitudinis per circuitum: et longitudo ejus nonaginta cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 13, 'Et mensus est domus longitudinem, centum cubitorum: et quod separatum erat ædificium, et parietes ejus, longitudinis centum cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 14, 'Latitudo autem ante faciem domus, et ejus quod erat separatum contra orientem, centum cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 15, 'Et mensus est longitudinem ædificii contra faciem ejus, quod erat separatum ad dorsum: ethecas ex utraque parte centum cubitorum: et templum interius, et vestibula atrii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 16, 'Limina, et fenestras obliquas, et ethecas in circuitu per tres partes, contra uniuscujusque limen, stratumque ligno per gyrum in circuitu: terra autem usque ad fenestras, et fenestræ clausæ super ostia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 17, 'Et usque ad domum interiorem, et forinsecus per omnem parietem in circuitu, intrinsecus et forinsecus, ad mensuram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 18, 'Et fabrefacta cherubim et palmæ: et palma inter cherub et cherub, duasque facies habebat cherub.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 19, 'Faciem hominis juxta palmam ex hac parte, et faciem leonis juxta palmam ex alia parte: expressam per omnem domum in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 20, 'De terra usque ad superiora portæ, cherubim et palmæ cælatæ erant in pariete templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 21, 'Limen quadrangulum, et facies sanctuarii, aspectus contra aspectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 22, 'Altaris lignei trium cubitorum altitudo, et longitudo ejus duorum cubitorum: et anguli ejus, et longitudo ejus, et parietes ejus lignei. Et locutus est ad me: Hæc est mensa coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 23, 'Et duo ostia erant in templo et in sanctuario.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 24, 'Et in duobus ostiis ex utraque parte bina erant ostiola quæ in se invicem plicabantur: bina enim ostia erant ex utraque parte ostiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 25, 'Et cælata erant in ipsis ostiis templi cherubim, et sculpturæ palmarum, sicut in parietibus quoque expressæ erant: quam ob rem et grossiora erant ligna in vestibuli fronte forinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 41, 26, 'Super quæ fenestræ obliquæ, et similitudo palmarum hinc atque inde in humerulis vestibuli, secundum latera domus, latitudinemque parietum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 1, 'Et eduxit me in atrium exterius, per viam ducentem ad aquilonem, et introduxit me in gazophylacium quod erat contra separatum ædificium, et contra ædem vergentem ad aquilonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 2, 'In facie longitudinis, centum cubitos ostii aquilonis, et latitudinis quinquaginta cubitos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 3, 'contra viginti cubitos atrii interioris, et contra pavimentum stratum lapide atrii exterioris, ubi erat porticus juncta porticui triplici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 4, 'Et ante gazophylacia deambulatio decem cubitorum latitudinis, ad interiora respiciens viæ cubiti unius. Et ostia eorum ad aquilonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 5, 'ubi erant gazophylacia in superioribus humiliora, quia supportabant porticus quæ ex illis eminebant de inferioribus, et de mediis ædificii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 6, 'Tristega enim erant, et non habebant columnas, sicut erant columnæ atriorum: propterea eminebant de inferioribus, et de mediis a terra cubitis quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 7, 'Et peribolus exterior secundum gazophylacia, quæ erant in via atrii exterioris ante gazophylacia: longitudo ejus quinquaginta cubitorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 8, 'quia longitudo erat gazophylaciorum atrii exterioris quinquaginta cubitorum, et longitudo ante faciem templi, centum cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 9, 'Et erat subter gazophylacia hæc introitus ab oriente, ingredientium in ea de atrio exteriori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 10, 'In latitudine periboli atrii quod erat contra viam orientalem, in faciem ædificii separati, et erant ante ædificium gazophylacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 11, 'Et via ante faciem eorum, juxta similitudinem gazophylaciorum quæ erant in via aquilonis: secundum longitudinem eorum, sic et latitudo eorum, et omnis introitus eorum, et similitudines, et ostia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 12, 'Secundum ostia gazophylaciorum, quæ erant in via respiciente ad notum: ostium in capite viæ, quæ via erat ante vestibulum separatum per viam orientalem ingredientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 13, 'Et dixit ad me: Gazophylacia aquilonis, et gazophylacia austri, quæ sunt ante ædificium separatum, hæc sunt gazophylacia sancta, in quibus vescuntur sacerdotes qui appropinquant ad Dominum in Sancta sanctorum: ibi ponent Sancta sanctorum et oblationem pro peccato et pro delicto: locus enim sanctus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 14, 'Cum autem ingressi fuerint sacerdotes, non egredientur de sanctis in atrium exterius: et ibi reponent vestimenta sua in quibus ministrant, quia sancta sunt, vestienturque vestimentis aliis: et sic procedent ad populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 15, 'Cumque complesset mensuras domus interioris, eduxit me per viam portæ quæ respiciebat ad viam orientalem: et mensus est eam undique per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 16, 'Mensus est autem contra ventum orientalem calamo mensuræ, quingentos calamos in calamo mensuræ per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 17, 'Et mensus est contra ventum aquilonis quingentos calamos in calamo mensuræ per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 18, 'Et ad ventum australem mensus est quingentos calamos in calamo mensuræ per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 19, 'Et ad ventum occidentalem mensus est quingentos calamos in calamo mensuræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 42, 20, 'Per quatuor ventos mensus est murum ejus undique per circuitum, longitudinem quingentorum cubitorum, et latitudinem quingentorum cubitorum, dividentem inter sanctuarium et vulgi locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 1, 'Et duxit me ad portam quæ respiciebat ad viam orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 2, 'Et ecce gloria Dei Israël ingrediebatur per viam orientalem: et vox erat ei quasi vox aquarum multarum, et terra splendebat a majestate ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 3, 'Et vidi visionem secundum speciem quam videram quando venit ut disperderet civitatem, et species secundum aspectum quem videram juxta fluvium Chobar: et cecidi super faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 4, 'Et majestas Domini ingressa est templum per viam portæ quæ respiciebat ad orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 5, 'Et elevavit me spiritus, et introduxit me in atrium interius: et ecce repleta erat gloria Domini domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 6, 'Et audivi loquentem ad me de domo: et vir qui stabat juxta me');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 7, 'dixit ad me: Fili hominis, locus solii mei, et locus vestigiorum pedum meorum, ubi habito in medio filiorum Israël in æternum: et non polluent ultra domus Israël nomen sanctum meum, ipsi et reges eorum, in fornicationibus suis, et in ruinis regum suorum, et in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 8, 'Qui fabricati sunt limen suum juxta limen meum, et postes suos juxta postes meos, et murus erat inter me et eos: et polluerunt nomen sanctum meum in abominationibus quas fecerunt: propter quod consumpsi eos in ira mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 9, 'Nunc ergo repellant procul fornicationem suam et ruinas regum suorum a me, et habitabo in medio eorum semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 10, 'Tu autem, fili hominis, ostende domui Israël templum, et confundantur ab iniquitatibus suis, et metiantur fabricam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 11, 'et erubescant ex omnibus quæ fecerunt. Figuram domus, et fabricæ ejus, exitus et introitus, et omnem descriptionem ejus, et universa præcepta ejus, cunctumque ordinem ejus, et omnes leges ejus ostende eis, et scribes in oculis eorum, ut custodiant omnes descriptiones ejus, et præcepta illius, et faciant ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 12, 'Ista est lex domus in summitate montis: omnis finis ejus in circuitu, Sanctum sanctorum est. Hæc est ergo lex domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 13, 'Istæ autem mensuræ altaris in cubito verissimo, qui habebat cubitum et palmum: in sinu ejus erat cubitus, et cubitus in latitudine: et definitio ejus usque ad labium ejus, et in circuitu palmus unus: hæc quoque erat fossa altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 14, 'Et de sinu terræ usque ad crepidinem novissimam duo cubiti, et latitudo cubiti unius: et a crepidine minore usque ad crepidinem majorem quatuor cubiti, et latitudo cubiti unius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 15, 'Ipse autem ariel quatuor cubitorum, et ab ariel usque ad sursum cornua quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 16, 'Et ariel duodecim cubitorum in longitudine per duodecim cubitos latitudinis, quadrangulatum æquis lateribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 17, 'Et crepido quatuordecim cubitorum longitudinis per quatuordecim cubitos latitudinis in quatuor angulis ejus: et corona in circuitu ejus dimidii cubiti, et sinus ejus unius cubiti per circuitum: gradus autem ejus versi ad orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 18, 'Et dixit ad me: Fili hominis, hæc dicit Dominus Deus: Hi sunt ritus altaris, in quacumque die fuerit fabricatum, ut offeratur super illud holocaustum, et effundatur sanguis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 19, 'Et dabis sacerdotibus et Levitis qui sunt de semine Sadoc, qui accedunt ad me, ait Dominus Deus, ut offerant mihi vitulum de armento pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 20, 'Et assumens de sanguine ejus, pones super quatuor cornua ejus, et super quatuor angulos crepidinis, et super coronam in circuitu: et mundabis illud et expiabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 21, 'Et tolles vitulum qui oblatus fuerit pro peccato, et combures eum in separato loco domus, extra sanctuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 22, 'Et in die secunda offeres hircum caprarum immaculatum pro peccato: et expiabunt altare sicut expiaverunt in vitulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 23, 'Cumque compleveris expians illud, offeres vitulum de armento immaculatum, et arietem de grege immaculatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 24, 'Et offeres eos in conspectu Domini: et mittent sacerdotes super eos sal, et offerent eos holocaustum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 25, 'Septem diebus facies hircum pro peccato quotidie: et vitulum de armento, et arietem de pecoribus immaculatos offerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 26, 'Septem diebus expiabunt altare et mundabunt illud, et implebunt manum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 43, 27, 'Expletis autem diebus, in die octava et ultra, facient sacerdotes super altare holocausta vestra, et quæ pro pace offerunt: et placatus ero vobis, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 1, 'Et convertit me ad viam portæ sanctuarii exterioris, quæ respiciebat ad orientem: et erat clausa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 2, 'Et dixit Dominus ad me: Porta hæc clausa erit: non aperietur, et vir non transibit per eam, quoniam Dominus Deus Israël ingressus est per eam: eritque clausa');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 3, 'principi. Princeps ipse sedebit in ea, ut comedat panem coram Domino: per viam portæ vestibuli ingredietur, et per viam ejus egredietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 4, 'Et adduxit me per viam portæ aquilonis in conspectu domus: et vidi, et ecce implevit gloria Domini domum Domini: et cecidi in faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 5, 'Et dixit ad me Dominus: Fili hominis, pone cor tuum, et vide oculis tuis, et auribus tuis audi omnia quæ ego loquor ad te de universis cæremoniis domus Domini, et de cunctis legibus ejus: et pones cor tuum in viis templi per omnes exitus sanctuarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 6, 'Et dices ad exasperantem me domum Israël: Hæc dicit Dominus Deus: Sufficiant vobis omnia scelera vestra, domus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 7, 'eo quod inducitis filios alienos incircumcisos corde, et incircumcisos carne, ut sint in sanctuario meo, et polluant domum meam: et offertis panes meos, adipem et sanguinem, et dissolvitis pactum meum in omnibus sceleribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 8, 'Et non servastis præcepta sanctuarii mei, et posuistis custodes observationum mearum in sanctuario meo vobismetipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 9, 'Hæc dicit Dominus Deus: Omnis alienigena incircumcisus corde, et incircumcisus carne, non ingredietur sanctuarium meum: omnis filius alienus qui est in medio filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 10, 'Sed et Levitæ qui longe recesserunt a me in errore filiorum Israël, et erraverunt a me post idola sua, et portaverunt iniquitatem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 11, 'erunt in sanctuario meo æditui, et janitores portarum domus, et ministri domus: ipsi mactabunt holocausta et victimas populi, et ipsi stabunt in conspectu eorum ut ministrent eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 12, 'Pro eo quod ministraverunt illis in conspectu idolorum suorum, et facti sunt domui Israël in offendiculum iniquitatis: idcirco levavi manum meam super eos, ait Dominus Deus, et portabunt iniquitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 13, 'Et non appropinquabunt ad me ut sacerdotio fungantur mihi, neque accedent ad omne sanctuarium meum juxta Sancta sanctorum: sed portabunt confusionem suam, et scelera sua quæ fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 14, 'Et dabo eos janitores domus in omni ministerio ejus, et in universis quæ fient in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 15, 'Sacerdotes autem et Levitæ, filii Sadoc, qui custodierunt cæremonias sanctuarii mei, cum errarent filii Israël a me, ipsi accedent ad me ut ministrent mihi: et stabunt in conspectu meo, ut offerant mihi adipem et sanguinem, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 16, 'Ipsi ingredientur sanctuarium meum, et ipsi accedent ad mensam meam, ut ministrent mihi, et custodiant cæremonias meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 17, 'Cumque ingredientur portas atrii interioris, vestibus lineis induentur: nec ascendet super eos quidquam laneum, quando ministrant in portis atrii interioris et intrinsecus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 18, 'Vittæ lineæ erunt in capitibus eorum, et feminalia linea erunt in lumbis eorum, et non accingentur in sudore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 19, 'Cumque egredientur atrium exterius ad populum, exuent se vestimentis suis in quibus ministraverant, et reponent ea in gazophylacio sanctuarii: et vestient se vestimentis aliis, et non sanctificabunt populum in vestibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 20, 'Caput autem suum non radent, neque comam nutrient: sed tondentes attondent capita sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 21, 'Et vinum non bibet omnis sacerdos, quando ingressurus est atrium interius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 22, 'Et viduam et repudiatam non accipient uxores, sed virgines de semine domus Israël: sed et viduam quæ fuerit vidua a sacerdote, accipient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 23, 'Et populum meum docebunt quid sit inter sanctum et pollutum, et inter mundum et immundum ostendent eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 24, 'Et cum fuerit controversia, stabunt in judiciis meis, et judicabunt: leges meas et præcepta mea in omnibus solemnitatibus meis custodient, et sabbata mea sanctificabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 25, 'Et ad mortuum hominem non ingredientur, ne polluantur, nisi ad patrem et matrem, et filium et filiam, et fratrem, et sororem quæ alterum virum non habuerit: in quibus contaminabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 26, 'Et postquam fuerit emundatus, septem dies numerabuntur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 27, 'Et in die introitus sui in sanctuarium ad atrium interius, ut ministret mihi in sanctuario, offeret pro peccato suo, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 28, 'Non erit autem eis hæreditas: ego hæreditas eorum. Et possessionem non dabitis eis in Israël: ego enim possessio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 29, 'Victimam et pro peccato et pro delicto ipsi comedent, et omne votum in Israël ipsorum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 30, 'Et primitiva omnium primogenitorum, et omnia libamenta ex omnibus quæ offeruntur, sacerdotum erunt: et primitiva ciborum vestrorum dabitis sacerdoti, ut reponat benedictionem domui tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 44, 31, 'Omne morticinum, et captum a bestia, de avibus et de pecoribus, non comedent sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 1, 'Cumque cœperitis terram dividere sortito, separate primitias Domino, sanctificatum de terra, longitudine viginti quinque millia, et latitudine decem millia: sanctificatum erit in omni termino ejus per circuitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 2, 'Et erit ex omni parte sanctificatum quingentos per quingentos, quadrifariam per circuitum, et quinquaginta cubitis in suburbana ejus per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 3, 'Et a mensura ista mensurabis longitudinem viginti quinque millium, et latitudinem decem millium: et in ipso erit templum, Sanctumque sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 4, 'Sanctificatum de terra erit sacerdotibus ministris sanctuarii, qui accedunt ad ministerium Domini: et erit eis locus in domos, et in sanctuarium sanctitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 5, 'Viginti quinque autem millia longitudinis, et decem millia latitudinis erunt Levitis qui ministrant domui: ipsi possidebunt viginti gazophylacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 6, 'Et possessionem civitatis dabitis quinque millia latitudinis, et longitudinis viginti quinque millia, secundum separationem sanctuarii, omni domui Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 7, 'Principi quoque hinc et inde in separationem sanctuarii, et in possessionem civitatis, contra faciem separationis sanctuarii, et contra faciem possessionis urbis, a latere maris usque ad mare, et a latere orientis usque ad orientem: longitudinis autem juxta unamquamque partem, a termino occidentali usque ad terminum orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 8, 'De terra erit ei possessio in Israël, et non depopulabuntur ultra principes populum meum: sed terram dabunt domui Israël secundum tribus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 9, 'Hæc dicit Dominus Deus: Sufficiat vobis, principes Israël: iniquitatem et rapinas intermittite, et judicium et justitiam facite: separate confinia vestra a populo meo, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 10, 'Statera justa, et ephi justum, et batus justus erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 11, 'Ephi et batus æqualia et unius mensuræ erunt, ut capiat decimam partem cori batus, et decimam partem cori ephi: juxta mensuram cori erit æqua libratio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 12, 'Siclus autem viginti obolos habet: porro viginti sicli, et viginti quinque sicli, et quindecim sicli, mnam faciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 13, 'Et hæ sunt primitiæ quas tolletis: sextam partem ephi de coro frumenti, et sextam partem ephi de coro hordei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 14, 'Mensura quoque olei, batus olei, decima pars cori est: et decem bati corum faciunt, quia decem bati implent corum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 15, 'Et arietem unum de grege ducentorum, de his quæ nutriunt Israël, in sacrificium, et in holocaustum, et in pacifica, ad expiandum pro eis, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 16, 'Omnis populus terræ tenebitur primitiis his principi in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 17, 'Et super principem erunt holocausta, et sacrificium, et libamina, in solemnitatibus, et in calendis, et in sabbatis, et in universis solemnitatibus domus Israël: ipse faciet pro peccato sacrificium, et holocaustum, et pacifica, ad expiandum pro domo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 18, 'Hæc dicit Dominus Deus: In primo mense, una mensis, sumes vitulum de armento immaculatum, et expiabis sanctuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 19, 'Et tollet sacerdos de sanguine quod erit pro peccato, et ponet in postibus domus, et in quatuor angulis crepidinis altaris, et in postibus portæ atrii interioris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 20, 'Et sic facies in septima mensis, pro unoquoque qui ignoravit, et errore deceptus est: et expiabis pro domo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 21, 'In primo mense, quartadecima die mensis, erit vobis Paschæ solemnitas: septem diebus azyma comedentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 22, 'Et faciet princeps in die illa, pro se et pro universo populo terræ, vitulum pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 23, 'Et in septem dierum solemnitate faciet holocaustum Domino, septem vitulos et septem arietes immaculatos, quotidie septem diebus: et pro peccato hircum caprarum quotidie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 24, 'Et sacrificium ephi per vitulum, et ephi per arietem faciet, et olei hin per singula ephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 45, 25, 'Septimo mense, quintadecima die mensis, in solemnitate, faciet sicut supra dicta sunt per septem dies, tam pro peccato quam pro holocausto, et in sacrificio, et in oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 1, 'Hæc dicit Dominus Deus: Porta atrii interioris quæ respicit ad orientem, erit clausa sex diebus in quibus opus fit: die autem sabbati aperietur, sed et in die calendarum aperietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 2, 'Et intrabit princeps per viam vestibuli portæ deforis, et stabit in limine portæ: et facient sacerdotes holocaustum ejus, et pacifica ejus: et adorabit super limen portæ, et egredietur: porta autem non claudetur usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 3, 'Et adorabit populus terræ ad ostium portæ illius in sabbatis et in calendis coram Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 4, 'Holocaustum autem hoc offeret princeps Domino: in die sabbati, sex agnos immaculatos, et arietem immaculatum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 5, 'et sacrificium ephi per arietem, in agnis autem sacrificium quod dederit manus ejus, et olei hin per singula ephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 6, 'In die autem calendarum vitulum de armento immaculatum, et sex agni et arietes immaculati erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 7, 'Et ephi per vitulum, ephi quoque per arietem faciet sacrificium: de agnis autem sicut invenerit manus ejus, et olei hin per singula ephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 8, 'Cumque ingressurus est princeps, per viam vestibuli portæ ingrediatur, et per eamdem viam exeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 9, 'Et cum intrabit populus terræ in conspectu Domini in solemnitatibus, qui ingreditur per portam aquilonis ut adoret, egrediatur per viam portæ meridianæ: porro qui ingreditur per viam portæ meridianæ, egrediatur per viam portæ aquilonis. Non revertetur per viam portæ per quam ingressus est, sed e regione illius egredietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 10, 'Princeps autem in medio eorum cum ingredientibus ingredietur, et cum egredientibus egredietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 11, 'Et in nundinis, et in solemnitatibus, erit sacrificium ephi per vitulum, et ephi per arietem: agnis autem erit sacrificium sicut invenerit manus ejus, et olei hin per singula ephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 12, 'Cum autem fecerit princeps spontaneum holocaustum, aut pacifica voluntaria Domino, aperietur ei porta quæ respicit ad orientem, et faciet holocaustum suum et pacifica sua, sicut fieri solet in die sabbati: et egredietur, claudeturque porta postquam exierit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 13, 'Et agnum ejusdem anni immaculatum faciet holocaustum quotidie Domino: semper mane faciet illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 14, 'Et faciet sacrificium super eo cata mane mane sextam partem ephi, et de oleo tertiam partem hin, ut misceatur similæ: sacrificium Domino legitimum, juge atque perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 15, 'Faciet agnum, et sacrificium, et oleum cata mane mane, holocaustum sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 16, 'Hæc dicit Dominus Deus: Si dederit princeps donum alicui de filiis suis, hæreditas ejus filiorum suorum erit: possidebunt eam hæreditarie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 17, 'Si autem dederit legatum de hæreditate sua uni servorum suorum, erit illius usque ad annum remissionis, et revertetur ad principem: hæreditas autem ejus filiis ejus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 18, 'Et non accipiet princeps de hæreditate populi per violentiam, et de possessione eorum: sed de possessione sua hæreditatem dabit filiis suis, ut non dispergatur populus meus unusquisque a possessione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 19, 'Et introduxit me per ingressum qui erat ex latere portæ, in gazophylacia sanctuarii ad sacerdotes, quæ respiciebant ad aquilonem: et erat ibi locus vergens ad occidentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 20, 'Et dixit ad me: Iste est locus ubi coquent sacerdotes pro peccato et pro delicto: ubi coquent sacrificium, ut non efferant in atrium exterius, et sanctificetur populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 21, 'Et eduxit me in atrium exterius, et circumduxit me per quatuor angulos atrii: et ecce atriolum erat in angulo atrii, atriola singula per angulos atrii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 22, 'In quatuor angulis atrii atriola disposita, quadraginta cubitorum per longum, et triginta per latum: mensuræ unius quatuor erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 23, 'Et paries per circuitum ambiens quatuor atriola: et culinæ fabricatæ erant subter porticus per gyrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 46, 24, 'Et dixit ad me: Hæc est domus culinarum, in qua coquent ministri domus Domini victimas populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 1, 'Et convertit me ad portam domus, et ecce aquæ egrediebantur subter limen domus ad orientem: facies enim domus respiciebat ad orientem, aquæ autem descendebant in latus templi dextrum, ad meridiem altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 2, 'Et eduxit me per viam portæ aquilonis, et convertit me ad viam foras portam exteriorem, viam quæ respiciebat ad orientem: et ecce aquæ redundantes a latere dextro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 3, 'Cum egrederetur vir ad orientem, qui habebat funiculum in manu sua, et mensus est mille cubitos, et traduxit me per aquam usque ad talos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 4, 'Rursumque mensus est mille, et traduxit me per aquam usque ad genua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 5, 'Et mensus est mille, et traduxit me per aquam usque ad renes. Et mensus est mille, torrentem quem non potui pertransire, quoniam intumuerant aquæ profundi torrentis, qui non potest transvadari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 6, 'Et dixit ad me: Certe vidisti, fili hominis. Et eduxit me, et convertit ad ripam torrentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 7, 'Cumque me convertissem, ecce in ripa torrentis ligna multa nimis ex utraque parte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 8, 'Et ait ad me: Aquæ istæ quæ egrediuntur ad tumulos sabuli orientalis, et descendunt ad plana deserti, intrabunt mare et exibunt: et sanabuntur aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 9, 'Et omnis anima vivens quæ serpit quocumque venerit torrens, vivet: et erunt pisces multi satis, postquam venerint illuc aquæ istæ: et sanabuntur et vivent omnia ad quæ venerit torrens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 10, 'Et stabunt super illas piscatores: ab Engaddi usque ad Engallim siccatio sagenarum erit: plurimæ species erunt piscium ejus, sicut pisces maris magni, multitudinis nimiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 11, 'In littoribus autem ejus et in palustribus, non sanabuntur, quia in salinas dabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 12, 'Et super torrentem orietur in ripis ejus, ex utraque parte, omne lignum pomiferum: non defluet folium ex eo, et non deficiet fructus ejus: per singulos menses afferet primitiva, quia aquæ ejus de sanctuario egredientur: et erunt fructus ejus in cibum, et folia ejus ad medicinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 13, 'Hæc dicit Dominus Deus: Hic est terminus in quo possidebitis terram in duodecim tribubus Israël: quia Joseph duplicem funiculum habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 14, 'Possidebitis autem eam singuli æque ut frater suus, super quam levavi manum meam ut darem patribus vestris: et cadet terra hæc vobis in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 15, 'Hic est autem terminus terræ: ad plagam septentrionalem, a mari magno via Hethalon, venientibus Sedada,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 16, 'Emath, Berotha, Sabarim, quæ est inter terminum Damasci et confinium Emath, domus Tichon, quæ est juxta terminum Auran.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 17, 'Et erit terminus a mari usque ad atrium Enon, terminus Damasci: et ab aquilone ad aquilonem, terminus Emath plaga septentrionalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 18, 'Porro plaga orientalis de medio Auran, et de medio Damasci, et de medio Galaad, et de medio terræ Israël, Jordanis disterminans ad mare orientale. Metiemini etiam plagam orientalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 19, 'Plaga autem australis meridiana, a Thamar usque ad aquas contradictionis Cades, et torrens usque ad mare magnum: et hæc est plaga ad meridiem australis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 20, 'Et plaga maris, mare magnum a confinio per directum, donec venias Emath: hæc est plaga maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 21, 'Et dividetis terram istam vobis per tribus Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 22, 'et mittetis eam in hæreditatem vobis, et advenis qui accesserint ad vos, qui genuerint filios in medio vestrum: et erunt vobis sicut indigenæ inter filios Israël: vobiscum divident possessionem in medio tribuum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 47, 23, 'In tribu autem quacumque fuerit advena, ibi dabitis possessionem illi, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 1, 'Et hæc nomina tribuum a finibus aquilonis, juxta viam Hethalon, pergentibus Emath, atrium Enan terminus Damasci ad aquilonem, juxta viam Emath: et erit ei plaga orientalis mare, Dan una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 2, 'Et super terminum Dan, a plaga orientali usque ad plagam maris, Aser una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 3, 'Et super terminum Aser, a plaga orientali usque ad plagam maris, Nephthali una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 4, 'Et super terminum Nephthali, a plaga orientali usque ad plagam maris, Manasse una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 5, 'Et super terminum Manasse, a plaga orientali usque ad plagam maris, Ephraim una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 6, 'Et super terminum Ephraim, a plaga orientali usque ad plagam maris, Ruben una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 7, 'Et super terminum Ruben, a plaga orientali usque ad plagam maris, Juda una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 8, 'Et super terminum Juda, a plaga orientali usque ad plagam maris, erunt primitiæ quas separabitis, viginti quinque millibus latitudinis et longitudinis, sicuti singulæ partes a plaga orientali usque ad plagam maris: et erit sanctuarium in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 9, 'Primitiæ quas separabitis Domino, longitudo viginti quinque millibus, et latitudo decem millibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 10, 'Hæ autem erunt primitiæ sanctuarii sacerdotum, ad aquilonem longitudinis viginti quinque millia, et ad mare latitudinis decem millia, sed et ad orientem latitudinis decem millia, et ad meridiem longitudinis viginti quinque millia: et erit sanctuarium Domini in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 11, 'Sacerdotibus sanctuarium erit de filiis Sadoc, qui custodierunt cæremonias meas, et non erraverunt cum errarent filii Israël, sicut erraverunt et Levitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 12, 'Et erunt eis primitiæ de primitiis terræ Sanctum sanctorum, juxta terminum Levitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 13, 'Sed et Levitis similiter, juxta fines sacerdotum, viginti quinque millia longitudinis, et latitudinis decem millia. Omnis longitudo viginti et quinque millium, et latitudo decem millium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 14, 'Et non venundabunt ex eo, neque mutabunt: neque transferentur primitiæ terræ, quia sanctificatæ sunt Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 15, 'Quinque millia autem quæ supersunt in latitudine per viginti quinque millia, profana erunt urbis in habitaculum et in suburbana: et erit civitas in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 16, 'Et hæ mensuræ ejus: ad plagam septentrionalem, quingenta et quatuor millia: et ad plagam meridianam, quingenta et quatuor millia: et ad plagam orientalem, quingenta et quatuor millia: et ad plagam occidentalem, quingenta et quatuor millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 17, 'Erunt autem suburbana civitatis ad aquilonem, ducenta quinquaginta: et ad meridiem, ducenta quinquaginta: et ad orientem, ducenta quinquaginta: et ad mare, ducenta quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 18, 'Quod autem reliquum fuerit in longitudine secundum primitias sanctuarii, decem millia in orientem, et decem millia in occidentem, erunt sicut primitiæ sanctuarii: et erunt fruges ejus in panes his qui serviunt civitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 19, 'Servientes autem civitati, operabuntur ex omnibus tribubus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 20, 'Omnes primitiæ viginti quinque millium, per viginti quinque millia in quadrum, separabuntur in primitias sanctuarii, et in possessionem civitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 21, 'Quod autem reliquum fuerit, principis erit ex omni parte primitiarum sanctuarii, et possessionis civitatis e regione viginti quinque millium primitiarum usque ad terminum orientalem: sed et ad mare, e regione viginti quinque millium, usque ad terminum maris, similiter in partibus principis erit: et erunt primitiæ sanctuarii, et sanctuarium templi, in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 22, 'De possessione autem Levitarum, et de possessione civitatis in medio partium principis, erit inter terminum Juda et inter terminum Benjamin, et ad principem pertinebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 23, 'Et reliquis tribubus, a plaga orientali usque ad plagam occidentalem, Benjamin una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 24, 'Et contra terminum Benjamin, a plaga orientali usque ad plagam occidentalem, Simeon una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 25, 'Et super terminum Simeonis, a plaga orientali usque ad plagam occidentalem, Issachar una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 26, 'Et super terminum Issachar, a plaga orientali usque ad plagam occidentalem, Zabulon una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 27, 'Et super terminum Zabulon, a plaga orientali usque ad plagam maris, Gad una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 28, 'Et super terminum Gad, ad plagam austri in meridie: et erit finis de Thamar usque ad aquas contradictionis Cades: hæreditas contra mare magnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 29, 'Hæc est terra quam mittetis in sortem tribubus Israël, et hæ partitiones earum, ait Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 30, 'Et hi egressus civitatis: a plaga septentrionali, quingentos et quatuor millia mensurabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 31, 'Et portæ civitatis ex nominibus tribuum Israël: portæ tres a septentrione: porta Ruben una, porta Juda una, porta Levi una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 32, 'Et ad plagam orientalem, quingentos et quatuor millia, et portæ tres: porta Joseph una, porta Benjamin una, porta Dan una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 33, 'Et ad plagam meridianam, quingentos et quatuor millia metieris, et portæ tres: porta Simeonis una, porta Issachar una, porta Zabulon una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 34, 'Et ad plagam occidentalem, quingentos et quatuor millia, et portæ eorum tres: porta Gad una, porta Aser una, porta Nephthali una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 48, 35, 'Per circuitum, decem et octo millia: et nomen civitatis ex illa die, Dominus ibidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Anno tertio regni Joakim regis Juda, venit Nabuchodonosor, rex Babylonis, in Jerusalem, et obsedit eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'et tradidit Dominus in manu ejus Joakim, regem Juda, et partem vasorum domus Dei: et asportavit ea in terram Sennaar in domum dei sui, et vasa intulit in domum thesauri dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Et ait rex Asphenez præposito eunuchorum ut introduceret de filiis Israël, et de semine regio et tyrannorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'pueros in quibus nulla esset macula, decoros forma, et eruditos omni sapientia, cautos scientia, et doctos disciplina, et qui possent stare in palatio regis, ut doceret eos litteras et linguam Chaldæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Et constituit eis rex annonam per singulos dies de cibis suis, et de vino unde bibebat ipse, ut enutriti tribus annis, postea starent in conspectu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Fuerunt ergo inter eos de filiis Juda, Daniel, Ananias, Misaël, et Azarias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Et imposuit eis præpositus eunuchorum nomina: Danieli, Baltassar; Ananiæ, Sidrach; Misaëli, Misach; et Azariæ, Abdenago.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Proposuit autem Daniel in corde suo ne pollueretur de mensa regis, neque de vino potus ejus: et rogavit eunuchorum præpositum ne contaminaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Dedit autem Deus Danieli gratiam et misericordiam in conspectu principis eunuchorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Et ait princeps eunuchorum ad Danielem: Timeo ego dominum meum regem, qui constituit vobis cibum et potum: qui si viderit vultus vestros macilentiores præ ceteris adolescentibus coævis vestris, condemnabitis caput meum regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Et dixit Daniel ad Malasar, quem constituerat princeps eunuchorum super Danielem, Ananiam, Misaëlem, et Azariam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Tenta nos, obsecro, servos tuos, diebus decem, et dentur nobis legumina ad vescendum, et aqua ad bibendum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'et contemplare vultus nostros, et vultus puerorum, qui vescuntur cibo regio: et sicut videris, facies cum servis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Qui, audito sermone hujuscemodi, tentavit eos diebus decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Post dies autem decem, apparuerunt vultus eorum meliores, et corpulentiores præ omnibus pueris, qui vescebantur cibo regio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Porro Malasar tollebat cibaria, et vinum potus eorum: dabatque eis legumina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Pueris autem his dedit Deus scientiam et disciplinam, in omni libro et sapientia: Danieli autem intelligentiam omnium visionum et somniorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 18, 'Completis itaque diebus, post quos dixerat rex ut introducerentur, introduxit eos præpositus eunuchorum in conspectu Nabuchodonosor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 19, 'Cumque eis locutus fuisset rex, non sunt inventi tales de universis, ut Daniel, Ananias, Misaël, et Azarias: et steterunt in conspectu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 20, 'Et omne verbum sapientiæ et intellectus, quod sciscitatus est ab eis rex, invenit in eis decuplum super cunctos ariolos et magos qui erant in universo regno ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 21, 'Fuit autem Daniel usque ad annum primum Cyri regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'In anno secundo regni Nabuchodonosor, vidit Nabuchodonosor somnium, et conterritus est spiritus ejus, et somnium ejus fugit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Præcepit autem rex ut convocarentur arioli, et magi, et malefici, et Chaldæi, ut indicarent regi somnia sua. Qui cum venissent, steterunt coram rege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Et dixit ad eos rex: Vidi somnium, et mente confusus ignoro quid viderim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Responderuntque Chaldæi regi syriace: Rex, in sempiternum vive! dic somnium servis tuis, et interpretationem ejus indicabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Et respondens rex ait Chaldæis: Sermo recessit a me: nisi indicaveritis mihi somnium, et conjecturam ejus, peribitis vos, et domus vestræ publicabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Si autem somnium, et conjecturam ejus narraveritis, præmia, et dona, et honorem multum accipietis a me. Somnium igitur, et interpretationem ejus indicate mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Responderunt secundo, atque dixerunt: Rex somnium dicat servis suis, et interpretationem illius indicabimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Respondit rex, et ait: Certe novi quod tempus redimitis, scientes quod recesserit a me sermo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Si ergo somnium non indicaveritis mihi, una est de vobis sententia, quod interpretationem quoque fallacem, et deceptione plenam composueritis, ut loquamini mihi donec tempus pertranseat. Somnium itaque dicite mihi, ut sciam quod interpretationem quoque ejus veram loquamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Respondentes ergo Chaldæi coram rege, dixerunt: Non est homo super terram, qui sermonem tuum, rex, possit implere: sed neque regum quisquam magnus et potens verbum hujuscemodi sciscitatur ab omni ariolo, et mago, et Chaldæo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Sermo enim, quem tu quæris, rex, gravis est: nec reperietur quisquam qui indicet illum in conspectu regis, exceptis diis, quorum non est cum hominibus conversatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 12, 'Quo audito, rex, in furore et in ira magna, præcepit ut perirent omnes sapientes Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 13, 'Et egressa sententia, sapientes interficiebantur: quærebanturque Daniel et socii ejus, ut perirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 14, 'Tunc Daniel requisivit de lege atque sententia ab Arioch principe militiæ regis, qui egressus fuerat ad interficiendos sapientes Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 15, 'Et interrogavit eum, qui a rege potestatem acceperat, quam ob causam tam crudelis sententia a facie regis esset egressa. Cum ergo rem indicasset Arioch Danieli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 16, 'Daniel ingressus rogavit regem ut tempus daret sibi ad solutionem indicandam regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 17, 'Et ingressus est domum suam, Ananiæque et Misaëli et Azariæ, sociis suis, indicavit negotium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 18, 'ut quærerent misericordiam a facie Dei cæli super sacramento isto, et non perirent Daniel et socii ejus cum ceteris sapientibus Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 19, 'Tunc Danieli mysterium per visionem nocte revelatum est: et benedixit Daniel Deum cæli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 20, 'et locutus ait: Sit nomen Domini benedictum a sæculo et usque in sæculum: quia sapientia et fortitudo ejus sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 21, 'Et ipse mutat tempora, et ætates: transfert regna, atque constituit: dat sapientiam sapientibus, et scientiam intelligentibus disciplinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 22, 'Ipse revelat profunda et abscondita, et novit in tenebris constituta: et lux cum eo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 23, 'Tibi, Deus patrum nostrorum, confiteor, teque laudo, quia sapientiam et fortitudinem dedisti mihi, et nunc ostendisti mihi quæ rogavimus te, quia sermonem regis aperuisti nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 24, 'Post hæc Daniel ingressus ad Arioch, quem constituerat rex ut perderet sapientes Babylonis, sic ei locutus est: Sapientes Babylonis ne perdas: introduc me in conspectu regis, et solutionem regi narrabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 25, 'Tunc Arioch festinus introduxit Danielem ad regem, et dixit ei: Inveni hominem de filiis transmigrationis Juda, qui solutionem regi annuntiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 26, 'Respondit rex, et dixit Danieli, cujus nomen erat Baltassar: Putasne vere potes mihi indicare somnium, quod vidi, et interpretationem ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 27, 'Et respondens Daniel coram rege, ait: Mysterium, quod rex interrogat, sapientes, magi, arioli, et aruspices nequeunt indicare regi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 28, 'sed est Deus in cælo revelans mysteria, qui indicavit tibi, rex Nabuchodonosor, quæ ventura sunt in novissimis temporibus. Somnium tuum, et visiones capitis tui in cubili tuo hujuscemodi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 29, 'Tu, rex, cogitare cœpisti in strato tuo, quid esset futurum post hæc: et qui revelat mysteria, ostendit tibi quæ ventura sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 30, 'Mihi quoque non in sapientia, quæ est in me plus quam in cunctis viventibus, sacramentum hoc revelatum est: sed ut interpretatio regi manifesta fieret, et cogitationes mentis tuæ scires.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 31, 'Tu, rex, videbas, et ecce quasi statua una grandis: statua illa magna, et statura sublimis stabat contra te, et intuitus ejus erat terribilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 32, 'Hujus statuæ caput ex auro optimo erat, pectus autem et brachia de argento, porro venter et femora ex ære,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 33, 'tibiæ autem ferreæ: pedum quædam pars erat ferrea, quædam autem fictilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 34, 'Videbas ita, donec abscissus est lapis de monte sine manibus: et percussit statuam in pedibus ejus ferreis et fictilibus, et comminuit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 35, 'Tunc contrita sunt pariter ferrum, testa, æs, argentum, et aurum, et redacta quasi in favillam æstivæ areæ, quæ rapta sunt vento, nullusque locus inventus est eis: lapis autem, qui percusserat statuam, factus est mons magnus, et implevit universam terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 36, 'Hoc est somnium: interpretationem quoque ejus dicemus coram te, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 37, 'Tu rex regum es: et Deus cæli regnum, et fortitudinem, et imperium, et gloriam dedit tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 38, 'et omnia, in quibus habitant filii hominum, et bestiæ agri: volucres quoque cæli dedit in manu tua, et sub ditione tua universa constituit: tu es ergo caput aureum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 39, 'Et post te consurget regnum aliud minus te argenteum: et regnum tertium aliud æreum, quod imperabit universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 40, 'Et regnum quartum erit velut ferrum: quomodo ferrum comminuit, et domat omnia, sic comminuet, et conteret omnia hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 41, 'Porro quia vidisti pedum, et digitorum partem testæ figuli, et partem ferream, regnum divisum erit: quod tamen de plantario ferri orietur, secundum quod vidisti ferrum mistum testæ ex luto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 42, 'Et digitos pedum ex parte ferreos, et ex parte fictiles: ex parte regnum erit solidum, et ex parte contritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 43, 'Quod autem vidisti ferrum mistum testæ ex luto, commiscebuntur quidem humano semine, sed non adhærebunt sibi, sicut ferrum misceri non potest testæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 44, 'In diebus autem regnorum illorum suscitabit Deus cæli regnum, quod in æternum non dissipabitur, et regnum ejus alteri populo non tradetur: comminuet autem, et consumet universa regna hæc, et ipsum stabit in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 45, 'Secundum quod vidisti, quod de monte abscissus est lapis sine manibus, et comminuit testam, et ferrum, et æs, et argentum, et aurum, Deus magnus ostendit regi quæ ventura sunt postea: et verum est somnium, et fidelis interpretatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 46, 'Tunc rex Nabuchodonosor cecidit in faciem suam, et Danielem adoravit, et hostias, et incensum præcepit ut sacrificarent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 47, 'Loquens ergo rex, ait Danieli: Vere Deus vester Deus deorum est, et Dominus regum, et revelans mysteria: quoniam tu potuisti aperire hoc sacramentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 48, 'Tunc rex Danielem in sublime extulit, et munera multa et magna dedit ei: et constituit eum principem super omnes provincias Babylonis, et præfectum magistratuum super cunctos sapientes Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 49, 'Daniel autem postulavit a rege, et constituit super opera provinciæ Babylonis Sidrach, Misach, et Abdenago: ipse autem Daniel erat in foribus regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Nabuchodonosor rex fecit statuam auream, altitudine cubitorum sexaginta, latitudine cubitorum sex, et statuit eam in campo Dura, provinciæ Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Itaque Nabuchodonosor rex misit ad congregandos satrapas, magistratus, et judices, duces, et tyrannos, et præfectos, omnesque principes regionum, ut convenirent ad dedicationem statuæ quam erexerat Nabuchodonosor rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tunc congregati sunt satrapæ, magistratus, et judices, duces, et tyranni, et optimates, qui erant in potestatibus constituti, et universi principes regionum, ut convenirent ad dedicationem statuæ, quam erexerat Nabuchodonosor rex. Stabant autem in conspectu statuæ, quam posuerat Nabuchodonosor rex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'et præco clamabat valenter: Vobis dicitur populis, tribubus, et linguis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'in hora qua audieritis sonitum tubæ, et fistulæ, et citharæ, sambucæ, et psalterii, et symphoniæ, et universi generis musicorum, cadentes adorate statuam auream, quam constituit Nabuchodonosor rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Si quis autem non prostratus adoraverit, eadem hora mittetur in fornacem ignis ardentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Post hæc igitur, statim ut audierunt omnes populi sonitum tubæ, fistulæ, et citharæ, sambucæ, et psalterii, et symphoniæ, et omnis generis musicorum, cadentes omnes populi, tribus, et linguæ adoraverunt statuam auream, quam constituerat Nabuchodonosor rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Statimque in ipso tempore accedentes viri Chaldæi accusaverunt Judæos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'dixeruntque Nabuchodonosor regi: Rex, in æternum vive!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'tu, rex, posuisti decretum, ut omnis homo, qui audierit sonitum tubæ, fistulæ, et citharæ, sambucæ, et psalterii, et symphoniæ, et universi generis musicorum, prosternat se, et adoret statuam auream:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 11, 'si quis autem non procidens adoraverit, mittatur in fornacem ignis ardentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 12, 'Sunt ergo viri Judæi, quos constituisti super opera regionis Babylonis, Sidrach, Misach, et Abdenago: viri isti contempserunt, rex, decretum tuum: deos tuos non colunt, et statuam auream, quam erexisti, non adorant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 13, 'Tunc Nabuchodonosor, in furore et in ira, præcepit ut adducerentur Sidrach, Misach, et Abdenago: qui confestim adducti sunt in conspectu regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 14, 'Pronuntiansque Nabuchodonosor rex, ait eis: Verene Sidrach, Misach, et Abdenago, deos meos non colitis, et statuam auream, quam constitui, non adoratis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 15, 'nunc ergo si estis parati, quacumque hora audieritis sonitum tubæ, fistulæ, citharæ, sambucæ, et psalterii, et symphoniæ, omnisque generis musicorum, prosternite vos, et adorate statuam, quam feci: quod si non adoraveritis, eadem hora mittemini in fornacem ignis ardentis: et quis est Deus, qui eripiet vos de manu mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 16, 'Respondentes Sidrach, Misach, et Abdenago, dixerunt regi Nabuchodonosor: Non oportet nos de hac re respondere tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 17, 'Ecce enim Deus noster, quem colimus, potest eripere nos de camino ignis ardentis, et de manibus tuis, o rex, liberare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 18, 'Quod si noluerit, notum sit tibi, rex, quia deos tuos non colimus, et statuam auream, quam erexisti, non adoramus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 19, 'Tunc Nabuchodonosor repletus est furore, et aspectus faciei illius immutatus est super Sidrach, Misach, et Abdenago: et præcepit ut succenderetur fornax septuplum quam succendi consueverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 20, 'Et viris fortissimis de exercitu suo jussit ut ligatis pedibus Sidrach, Misach, et Abdenago, mitterent eos in fornacem ignis ardentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 21, 'Et confestim viri illi vincti, cum braccis suis, et tiaris, et calceamentis, et vestibus, missi sunt in medium fornacis ignis ardentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 22, 'nam jussio regis urgebat. Fornax autem succensa erat nimis: porro viros illos, qui miserant Sidrach, Misach, et Abdenago, interfecit flamma ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 23, 'Viri autem hi tres, id est, Sidrach, Misach, et Abdenago, ceciderunt in medio camino ignis ardentis, colligati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 24, 'Et ambulabant in medio flammæ, laudantes Deum, et benedicentes Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 25, 'Stans autem Azarias oravit sic, aperiensque os suum in medio ignis, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 26, 'Benedictus es, Domine Deus patrum nostrorum, et laudabile, et gloriosum nomen tuum in sæcula:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 27, 'quia justus es in omnibus, quæ fecisti nobis, et universa opera tua vera, et viæ tuæ rectæ, et omnia judicia tua vera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 28, 'Judicia enim vera fecisti juxta omnia, quæ induxisti super nos, et super civitatem sanctam patrum nostrorum Jerusalem: quia in veritate et in judicio induxisti omnia hæc propter peccata nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 29, 'Peccavimus enim, et inique egimus recedentes a te, et deliquimus in omnibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 30, 'et præcepta tua non audivimus, nec observavimus, nec fecimus sicut præceperas nobis ut bene nobis esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 31, 'Omnia ergo, quæ induxisti super nos, et universa quæ fecisti nobis, in vero judicio fecisti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 32, 'et tradidisti nos in manibus inimicorum nostrorum iniquorum, et pessimorum, prævaricatorumque, et regi injusto, et pessimo ultra omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 33, 'Et nunc non possumus aperire os: confusio, et opprobrium facti sumus servis tuis, et his qui colunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 34, 'Ne, quæsumus, tradas nos in perpetuum propter nomen tuum, et ne dissipes testamentum tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 35, 'neque auferas misericordiam tuam a nobis, propter Abraham, dilectum tuum, et Isaac, servum tuum, et Israël, sanctum tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 36, 'quibus locutus es pollicens quod multiplicares semen eorum sicut stellas cæli, et sicut arenam quæ est in littore maris;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 37, 'quia, Domine, imminuti sumus plus quam omnes gentes, sumusque humiles in universa terra hodie propter peccata nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 38, 'Et non est in tempore hoc princeps, et dux, et propheta, neque holocaustum, neque sacrificium, neque oblatio, neque incensum, neque locus primitiarum coram te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 39, 'ut possimus invenire misericordiam tuam, sed in animo contrito, et spiritu humilitatis suscipiamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 40, 'Sicut in holocausto arietum, et taurorum, et sicut in millibus agnorum pinguium, sic fiat sacrificium nostrum in conspectu tuo hodie, ut placeat tibi, quoniam non est confusio confidentibus in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 41, 'Et nunc sequimur te in toto corde; et timemus te, et quærimus faciem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 42, 'Nec confundas nos, sed fac nobiscum juxta mansuetudinem tuam, et secundum multitudinem misericordiæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 43, 'Et erue nos in mirabilibus tuis, et da gloriam nomini tuo, Domine;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 44, 'et confundantur omnes qui ostendunt servis tuis mala: confundantur in omni potentia tua, et robur eorum conteratur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 45, 'et sciant quia tu es Dominus Deus solus, et gloriosus super orbem terrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 46, 'Et non cessabant qui miserant eos ministri regis succendere fornacem, naphtha, et stuppa, et pice, et malleolis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 47, 'et effundebatur flamma super fornacem cubitis quadraginta novem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 48, 'et erupit, et incendit quos reperit juxta fornacem de Chaldæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 49, 'Angelus autem Domini descendit cum Azaria, et sociis ejus in fornacem: et excussit flammam ignis de fornace,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 50, 'et fecit medium fornacis quasi ventum roris flantem, et non tetigit eos omnino ignis, neque contristavit, nec quidquam molestiæ intulit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 51, 'Tunc hi tres quasi ex uno ore laudabant, et glorificabant, et benedicebant Deum in fornace, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 52, 'Benedictus es, Domine Deus patrum nostrorum: et laudabilis, et gloriosus, et superexaltatus in sæcula. Et benedictum nomen gloriæ tuæ sanctum: et laudabile, et superexaltatum in omnibus sæculis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 53, 'Benedictus es in templo sancto gloriæ tuæ: et superlaudabilis, et supergloriosus in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 54, 'Benedictus es in throno regni tui: et superlaudabilis, et superexaltatus in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 55, 'Benedictus es, qui intueris abyssos, et sedes super cherubim: et laudabilis, et superexaltatus in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 56, 'Benedictus es in firmamento cæli: et laudabilis et gloriosus in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 57, 'Benedicite, omnia opera Domini, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 58, 'Benedicite, angeli Domini, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 59, 'Benedicite, cæli, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 60, 'Benedicite, aquæ omnes, quæ super cælos sunt, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 61, 'Benedicite, omnes virtutes Domini, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 62, 'Benedicite, sol et luna, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 63, 'Benedicite, stellæ cæli, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 64, 'Benedicite, omnis imber et ros, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 65, 'Benedicite, omnes spiritus Dei, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 66, 'Benedicite, ignis et æstus, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 67, 'Benedicite, frigus et æstus, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 68, 'Benedicite, rores et pruina, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 69, 'Benedicite, gelu et frigus, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 70, 'Benedicite, glacies et nives, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 71, 'Benedicite, noctes et dies, Domino laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 72, 'Benedicite, lux et tenebræ, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 73, 'Benedicite, fulgura et nubes, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 74, 'Benedicat terra Dominum: laudet et superexaltet eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 75, 'Benedicite, montes et colles, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 76, 'Benedicite, universa germinantia in terra, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 77, 'Benedicite, fontes, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 78, 'Benedicite, maria et flumina, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 79, 'Benedicite, cete, et omnia quæ moventur in aquis, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 80, 'Benedicite, omnes volucres cæli, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 81, 'Benedicite, omnes bestiæ et pecora, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 82, 'Benedicite, filii hominum, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 83, 'Benedicat Israël Dominum: laudet et superexaltet eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 84, 'Benedicite, sacerdotes Domini, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 85, 'Benedicite, servi Domini, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 86, 'Benedicite, spiritus et animæ justorum, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 87, 'Benedicite, sancti et humiles corde, Domino: laudate et superexaltate eum in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 88, 'Benedicite, Anania, Azaria, Misaël, Domino: laudate et superexaltate eum in sæcula: quia eruit nos de inferno, et salvos fecit de manu mortis: et liberavit nos de medio ardentis flammæ, et de medio ignis eruit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 89, 'Confitemini Domino, quoniam bonus: quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 90, 'Benedicite, omnes religiosi, Domino Deo deorum: laudate et confitemini ei, quia in omnia sæcula misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 91, 'Tunc Nabuchodonosor rex obstupuit, et surrexit propere, et ait optimatibus suis: Nonne tres viros misimus in medium ignis compeditos? Qui respondentes regi, dixerunt: Vere, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 92, 'Respondit, et ait: Ecce ego video quatuor viros solutos, et ambulantes in medio ignis, et nihil corruptionis in eis est, et species quarti similis filio Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 93, 'Tunc accessit Nabuchodonosor ad ostium fornacis ignis ardentis, et ait: Sidrach, Misach, et Abdenago, servi Dei excelsi, egredimini, et venite. Statimque egressi sunt Sidrach, Misach, et Abdenago de medio ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 94, 'Et congregati satrapæ, et magistratus, et judices, et potentes regis contemplabantur viros illos, quoniam nihil potestatis habuisset ignis in corporibus eorum, et capillus capitis eorum non esset adustus, et sarabala eorum non fuissent immutata, et odor ignis non transisset per eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 95, 'Et erumpens Nabuchodonosor, ait: Benedictus Deus eorum, Sidrach videlicet, Misach, et Abdenago: qui misit angelum suum, et eruit servos suos, qui crediderunt in eum: et verbum regis immutaverunt, et tradiderunt corpora sua ne servirent, et ne adorarent omnem deum, excepto Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 96, 'A me ergo positum est hoc decretum: ut omnis populus, tribus, et lingua, quæcumque locuta fuerit blasphemiam contra Deum Sidrach, Misach, et Abdenago, dispereat, et domus ejus vastetur: neque enim est alius deus, qui possit ita salvare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 97, 'Tunc rex promovit Sidrach, Misach, et Abdenago in provincia Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 98, 'Nabuchodonosor rex, omnibus populis, gentibus, et linguis, qui habitant in universa terra, pax vobis multiplicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 99, 'Signa, et mirabilia fecit apud me Deus excelsus. Placuit ergo mihi prædicare');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 100, 'signa ejus, quia magna sunt: et mirabilia ejus, quia fortia: et regnum ejus regnum sempiternum, et potestas ejus in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Ego Nabuchodonosor quietus eram in domo mea, et florens in palatio meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'somnium vidi, quod perterruit me: et cogitationes meæ in strato meo, et visiones capitis mei conturbaverunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Et per me propositum est decretum ut introducerentur in conspectu meo cuncti sapientes Babylonis, et ut solutionem somnii indicarent mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Tunc ingrediebantur arioli, magi, Chaldæi, et aruspices, et somnium narravi in conspectu eorum: et solutionem ejus non indicaverunt mihi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'donec collega ingressus est in conspectu meo Daniel, cui nomen Baltassar secundum nomen dei mei, qui habet spiritum deorum sanctorum in semetipso: et somnium coram ipso locutus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Baltassar, princeps ariolorum, quoniam ego scio quod spiritum sanctorum deorum habeas in te, et omne sacramentum non est impossibile tibi: visiones somniorum meorum, quas vidi, et solutionem earum narra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Visio capitis mei in cubili meo: videbam, et ecce arbor in medio terræ, et altitudo ejus nimia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Magna arbor, et fortis, et proceritas ejus contingens cælum: aspectus illius erat usque ad terminos universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Folia ejus pulcherrima, et fructus ejus nimius: et esca universorum in ea. Subter eam habitabant animalia et bestiæ, et in ramis ejus conversabantur volucres cæli: et ex ea vescebatur omnis caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Videbam in visione capitis mei super stratum meum, et ecce vigil, et sanctus, de cælo descendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Clamavit fortiter, et sic ait: Succidite arborem, et præcidite ramos ejus: excutite folia ejus, et dispergite fructus ejus: fugiant bestiæ, quæ subter eam sunt, et volucres de ramis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 12, 'Verumtamen germen radicum ejus in terra sinite, et alligetur vinculo ferreo et æreo in herbis quæ foris sunt, et rore cæli tingatur, et cum feris pars ejus in herba terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 13, 'Cor ejus ab humano commutetur, et cor feræ detur ei: et septem tempora mutentur super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 14, 'In sententia vigilum decretum est, et sermo sanctorum, et petitio: donec cognoscant viventes quoniam dominatur Excelsus in regno hominum, et cuicumque voluerit, dabit illud, et humillimum hominem constituet super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 15, 'Hoc somnium vidi ego Nabuchodonosor rex: tu ergo Baltassar interpretationem narra festinus, quia omnes sapientes regni mei non queunt solutionem edicere mihi: tu autem potes, quia spiritus deorum sanctorum in te est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 16, 'Tunc Daniel, cujus nomen Baltassar, cœpit intra semetipsum tacitus cogitare quasi una hora: et cogitationes ejus conturbabant eum. Respondens autem rex, ait: Baltassar, somnium et interpretatio ejus non conturbent te. Respondit Baltassar, et dixit: Domine mi, somnium his, qui te oderunt, et interpretatio ejus hostibus tuis sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 17, 'Arborem, quam vidisti sublimem atque robustam, cujus altitudo pertingit ad cælum, et aspectus illius in omnem terram;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 18, 'et rami ejus pulcherrimi, et fructus ejus nimius, et esca omnium in ea, subter eam habitantes bestiæ agri, et in ramis ejus commorantes aves cæli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 19, 'tu es rex, qui magnificatus es, et invaluisti: et magnitudo tua crevit, et pervenit usque ad cælum, et potestas tua in terminos universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 20, 'Quod autem vidit rex vigilem, et sanctum descendere de cælo, et dicere: Succidite arborem, et dissipate illam, attamen germen radicum ejus in terra dimittite, et vinciatur ferro et ære in herbis foris, et rore cæli conspergatur, et cum feris sit pabulum ejus, donec septem tempora mutentur super eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 21, 'hæc est interpretatio sententiæ Altissimi, quæ pervenit super dominum meum regem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 22, 'Ejicient te ab hominibus, et cum bestiis ferisque erit habitatio tua, et fœnum ut bos comedes, et rore cæli infunderis: septem quoque tempora mutabuntur super te, donec scias quod dominetur Excelsus super regnum hominum, et cuicumque voluerit, det illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 23, 'Quod autem præcepit ut relinqueretur germen radicum ejus, id est arboris: regnum tuum tibi manebit postquam cognoveris potestatem esse cælestem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 24, 'Quam ob rem, rex, consilium meum placeat tibi, et peccata tua eleemosynis redime, et iniquitates tuas misericordiis pauperum: forsitan ignoscet delictis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 25, 'Omnia hæc venerunt super Nabuchodonosor regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 26, 'Post finem mensium duodecim, in aula Babylonis deambulabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 27, 'Responditque rex, et ait: Nonne hæc est Babylon magna, quam ego ædificavi in domum regni, in robore fortitudinis meæ, et in gloria decoris mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 28, 'Cumque sermo adhuc esset in ore regis, vox de cælo ruit: Tibi dicitur, Nabuchodonosor rex: Regnum tuum transibit a te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 29, 'et ab hominibus ejicient te, et cum bestiis et feris erit habitatio tua: fœnum quasi bos comedes, et septem tempora mutabuntur super te, donec scias quod dominetur Excelsus in regno hominum, et cuicumque voluerit, det illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 30, 'Eadem hora sermo completus est super Nabuchodonosor, et ex hominibus abjectus est, et fœnum ut bos comedit, et rore cæli corpus ejus infectum est, donec capilli ejus in similitudinem aquilarum crescerent, et ungues ejus quasi avium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 31, 'Igitur post finem dierum, ego Nabuchodonosor oculos meos ad cælum levavi, et sensus meus redditus est mihi: et Altissimo benedixi, et viventem in sempiternum laudavi et glorificavi: quia potestas ejus potestas sempiterna, et regnum ejus in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 32, 'Et omnes habitatores terræ apud eum in nihilum reputati sunt: juxta voluntatem enim suam facit tam in virtutibus cæli quam in habitatoribus terræ: et non est qui resistat manui ejus, et dicat ei: Quare fecisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 33, 'In ipso tempore sensus meus reversus est ad me, et ad honorem regni mei, decoremque perveni: et figura mea reversa est ad me, et optimates mei et magistratus mei requisierunt me, et in regno meo restitutus sum: et magnificentia amplior addita est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 34, 'Nunc igitur, ego Nabuchodonosor laudo, et magnifico, et glorifico regem cæli: quia omnia opera ejus vera, et viæ ejus judicia, et gradientes in superbia potest humiliare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 1, 'Baltassar rex fecit grande convivium optimatibus suis mille: et unusquisque secundum suam bibebat ætatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 2, 'Præcepit ergo jam temulentus ut afferrentur vasa aurea et argentea, quæ asportaverat Nabuchodonosor pater ejus de templo, quod fuit in Ierusalem, ut biberent in eis rex, et optimates ejus, uxoresque ejus, et concubinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 3, 'Tunc allata sunt vasa aurea, et argentea, quæ asportaverat de templo, quod fuerat in Ierusalem: et biberunt in eis rex, et optimates ejus, uxores et concubinæ illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 4, 'Bibebant vinum, et laudabant deos suos aureos et argenteos, æreos, ferreos, ligneosque et lapideos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 5, 'In eadem hora apparuerunt digiti, quasi manus hominis scribentis contra candelabrum in superficie parietis aulæ regiæ: et rex aspiciebat articulos manus scribentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 6, 'Tunc facies regis commutata est, et cogitationes ejus conturbabant eum: et compages renum ejus solvebantur, et genua ejus ad se invicem collidebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 7, 'Exclamavit itaque rex fortiter ut introducerent magos, Chaldæos, et aruspices. Et proloquens rex ait sapientibus Babylonis: Quicumque legerit scripturam hanc, et interpretationem ejus manifestam mihi fecerit, purpura vestietur, et torquem auream habebit in collo, et tertius in regno meo erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 8, 'Tunc ingressi omnes sapientes regis non potuerunt nec scripturam legere, nec interpretationem indicare regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 9, 'Unde rex Baltassar satis conturbatus est, et vultus illius immutatus est; sed et optimates ejus turbabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 10, 'Regina autem pro re, quæ acciderat regi et optimatibus ejus, domum convivii ingressa est: et proloquens ait: Rex, in æternum vive! non te conturbent cogitationes tuæ, neque facies tua immutetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 11, 'Est vir in regno tuo, qui spiritum deorum sanctorum habet in se, et in diebus patris tui scientia et sapientia inventæ sunt in eo: nam et rex Nabuchodonosor pater tuus principem magorum, incantatorum, Chaldæorum, et aruspicum constituit eum, pater, inquam, tuus, o rex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 12, 'quia spiritus amplior, et prudentia, intelligentiaque et interpretatio somniorum, et ostensio secretorum, ac solutio ligatorum inventæ sunt in eo, hoc est in Daniele: cui rex posuit nomen Baltassar. Nunc itaque Daniel vocetur, et interpretationem narrabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 13, 'Igitur introductus est Daniel coram rege: ad quem præfatus rex ait: Tu es Daniel de filiis captivitatis Judæ, quem adduxit pater meus rex de Judæa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 14, 'audivi de te, quoniam spiritum deorum habeas, et scientia, intelligentiaque ac sapientia ampliores inventæ sunt in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 15, 'Et nunc introgressi sunt in conspectu meo sapientes magi, ut scripturam hanc legerent, et interpretationem ejus indicarent mihi: et nequiverunt sensum hujus sermonis edicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 16, 'Porro ego audivi de te, quod possis obscura interpretari, et ligata dissolvere: si ergo vales scripturam legere, et interpretationem ejus indicare mihi, purpura vestieris, et torquem auream circa collum tuum habebis, et tertius in regno meo princeps eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 17, 'Ad quæ respondens Daniel, ait coram rege: Munera tua sint tibi, et dona domus tuæ alteri da: scripturam autem legam tibi, rex, et interpretationem ejus ostendam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 18, 'O rex, Deus altissimus regnum et magnificentiam, gloriam et honorem dedit Nabuchodonosor patri tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 19, 'Et propter magnificentiam, quam dederat ei, universi populi, tribus, et linguæ tremebant, et metuebant eum: quos volebat, interficiebat: et quos volebat, percutiebat: et quos volebat, exaltabat: et quos volebat, humiliabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 20, 'Quando autem elevatum est cor ejus, et spiritus illius obfirmatus est ad superbiam, depositus est de solio regni sui, et gloria ejus ablata est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 21, 'et a filiis hominum ejectus est, sed et cor ejus cum bestiis positum est, et cum onagris erat habitatio ejus: fœnum quoque ut bos comedebat, et rore cæli corpus ejus infectum est, donec cognosceret quod potestatem haberet Altissimus in regno hominum, et quemcumque voluerit, suscitabit super illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 22, 'Tu quoque, filius ejus Baltassar, non humiliasti cor tuum, cum scires hæc omnia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 23, 'sed adversum Dominatorem cæli elevatus es: et vasa domus ejus allata sunt coram te, et tu, et optimates tui, et uxores tuæ, et concubinæ tuæ vinum bibistis in eis: deos quoque argenteos, et aureos, et æreos, ferreos, ligneosque et lapideos, qui non vident, neque audiunt, neque sentiunt, laudasti: porro Deum, qui habet flatum tuum in manu sua, et omnes vias tuas, non glorificasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 24, 'Idcirco ab eo missus est articulus manus, quæ scripsit hoc quod exaratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 25, 'Hæc est autem scriptura, quæ digesta est: Mane, Thecel, Phares.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 26, 'Et hæc est interpretatio sermonis. Mane: numeravit Deus regnum tuum, et complevit illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 27, 'Thecel: appensus es in statera, et inventus es minus habens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 28, 'Phares: divisum est regnum tuum, et datum est Medis, et Persis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 29, 'Tunc, jubente rege, indutus est Daniel purpura, et circumdata est torques aurea collo ejus: et prædicatum est de eo quod haberet potestatem tertius in regno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 30, 'Eadem nocte interfectus est Baltassar rex Chaldæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 5, 31, 'Et Darius Medus successit in regnum, annos natus sexaginta duos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 1, 'Placuit Dario, et constituit super regnum satrapas centum viginti ut essent in toto regno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 2, 'Et super eos principes tres, ex quibus Daniel unus erat: ut satrapæ illis redderent rationem, et rex non sustineret molestiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 3, 'Igitur Daniel superabat omnes principes et satrapas, quia spiritus Dei amplior erat in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 4, 'Porro rex cogitabat constituere eum super omne regnum: unde principes, et satrapæ quærebant occasionem ut invenirent Danieli ex latere regis: nullamque causam, et suspicionem reperire potuerunt, eo quod fidelis esset, et omnis culpa, et suspicio non inveniretur in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 5, 'Dixerunt ergo viri illi: Non inveniemus Danieli huic aliquam occasionem, nisi forte in lege Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 6, 'Tunc principes et satrapæ surripuerunt regi, et sic locuti sunt ei: Dari rex, in æternum vive!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 7, 'consilium inierunt omnes principes regni tui, magistratus, et satrapæ, senatores, et judices, ut decretum imperatorium exeat, et edictum: ut omnis, qui petierit aliquam petitionem a quocumque deo et homine usque ad triginta dies, nisi a te, rex, mittatur in lacum leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 8, 'Nunc itaque rex, confirma sententiam, et scribe decretum: ut non immutetur quod statutum est a Medis et Persis, nec prævaricari cuiquam liceat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 9, 'Porro rex Darius proposuit edictum, et statuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 10, 'Quod cum Daniel comperisset, id est, constitutam legem, ingressus est domum suam: et fenestris apertis in cœnaculo suo contra Jerusalem tribus temporibus in die flectebat genua sua, et adorabat, confitebaturque coram Deo suo sicut et ante facere consueverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 11, 'Viri ergo illi curiosius inquirentes invenerunt Danielem orantem, et obsecrantem Deum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 12, 'Et accedentes locuti sunt regi super edicto: Rex, numquid non constituisti ut omnis homo qui rogaret quemquam de diis et hominibus usque ad dies triginta, nisi te, rex, mitteretur in lacum leonum? Ad quos respondens rex, ait: Verus est sermo juxta decretum Medorum atque Persarum, quod prævaricari non licet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 13, 'Tunc respondentes dixerunt coram rege: Daniel de filiis captivitatis Juda, non curavit de lege tua, et de edicto quod constituisti: sed tribus temporibus per diem orat obsecratione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 14, 'Quod verbum cum audisset rex, satis contristatus est: et pro Daniele posuit cor ut liberaret eum, et usque ad occasum solis laborabat ut erueret illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 15, 'Viri autem illi, intelligentes regem, dixerunt ei: Scito, rex, quia lex Medorum atque Persarum est ut omne decretum, quod constituerit rex, non liceat immutari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 16, 'Tunc rex præcepit, et adduxerunt Danielem, et miserunt eum in lacum leonum. Dixitque rex Danieli: Deus tuus, quem colis semper, ipse liberabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 17, 'Allatusque est lapis unus, et positus est super os laci: quem obsignavit rex annulo suo, et annulo optimatum suorum, ne quid fieret contra Danielem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 18, 'Et abiit rex in domum suam, et dormivit incœnatus, cibique non sunt allati coram eo, insuper et somnus recessit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 19, 'Tunc rex primo diluculo consurgens, festinus ad lacum leonum perrexit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 20, 'appropinquansque lacui, Danielem voce lacrimabili inclamavit, et affatus est eum: Daniel serve Dei viventis, Deus tuus, cui tu servis semper, putasne valuit te liberare a leonibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 21, 'Et Daniel regi respondens ait: Rex, in æternum vive!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 22, 'Deus meus misit angelum suum, et conclusit ora leonum, et non nocuerunt mihi: quia coram eo justitia inventa est in me: sed et coram te, rex, delictum non feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 23, 'Tunc vehementer rex gavisus est super eo, et Danielem præcepit educi de lacu: eductusque est Daniel de lacu, et nulla læsio inventa est in eo, quia credidit Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 24, 'Jubente autem rege, adducti sunt viri illi, qui accusaverant Danielem: et in lacum leonum missi sunt, ipsi, et filii, et uxores eorum: et non pervenerunt usque ad pavimentum laci, donec arriperent eos leones, et omnia ossa eorum comminuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 25, 'Tunc Darius rex scripsit universis populis, tribubus, et linguis habitantibus in universa terra: Pax vobis multiplicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 26, 'A me constitutum est decretum, ut in universo imperio et regno meo, tremiscant et paveant Deum Danielis: ipse est enim Deus vivens, et æternus in sæcula, et regnum ejus non dissipabitur, et potestas ejus usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 27, 'Ipse liberator atque salvator, faciens signa et mirabilia in cælo et in terra: qui liberavit Danielem de lacu leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 6, 28, 'Porro Daniel perseveravit usque ad regnum Darii, regnumque Cyri Persæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 1, 'Anno primo Baltassar regis Babylonis, Daniel somnium vidit: visio autem capitis ejus in cubili suo: et somnium scribens, brevi sermone comprehendit: summatimque perstringens, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 2, 'Videbam in visione mea nocte: et ecce quatuor venti cæli pugnabant in mari magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 3, 'Et quatuor bestiæ grandes ascendebant de mari diversæ inter se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 4, 'Prima quasi leæna, et alas habebat aquilæ: aspiciebam donec evulsæ sunt alæ ejus, et sublata est de terra, et super pedes quasi homo stetit; et cor hominis datum est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 5, 'Et ecce bestia alia similis urso in parte stetit: et tres ordines erant in ore ejus, et in dentibus ejus, et sic dicebant ei: Surge, comede carnes plurimas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 6, 'Post hæc aspiciebam, et ecce alia quasi pardus, et alas habebat quasi avis, quatuor super se: et quatuor capita erant in bestia, et potestas data est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 7, 'Post hæc aspiciebam in visione noctis, et ecce bestia quarta terribilis atque mirabilis, et fortis nimis: dentes ferreos habebat magnos, comedens atque comminuens, et reliqua pedibus suis conculcans: dissimilis autem erat ceteris bestiis quas videram ante eam, et habebat cornua decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 8, 'Considerabam cornua, et ecce cornu aliud parvulum ortum est de medio eorum: et tria de cornibus primis evulsa sunt a facie ejus: et ecce oculi, quasi oculi hominis erant in cornu isto, et os loquens ingentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 9, 'Aspiciebam donec throni positi sunt, et antiquus dierum sedit. Vestimentum ejus candidum quasi nix, et capilli capitis ejus quasi lana munda: thronus ejus flammæ ignis: rotæ ejus ignis accensus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 10, 'Fluvius igneus rapidusque egrediebatur a facie ejus. Millia millium ministrabant ei, et decies millies centena millia assistebant ei: judicium sedit, et libri aperti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 11, 'Aspiciebam propter vocem sermonum grandium, quos cornu illud loquebatur: et vidi quoniam interfecta esset bestia, et perisset corpus ejus, et traditum esset ad comburendum igni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 12, 'aliarum quoque bestiarum ablata esset potestas, et tempora vitæ constituta essent eis usque ad tempus et tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 13, 'Aspiciebam ergo in visione noctis, et ecce cum nubibus cæli quasi filius hominis veniebat, et usque ad antiquum dierum pervenit: et in conspectu ejus obtulerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 14, 'Et dedit ei potestatem, et honorem, et regnum: et omnes populi, tribus, et linguæ ipsi servient: potestas ejus, potestas æterna, quæ non auferetur: et regnum ejus, quod non corrumpetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 15, 'Horruit spiritus meus: ego Daniel territus sum in his, et visiones capitis mei conturbaverunt me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 16, 'Accessi ad unum de assistentibus, et veritatem quærebam ab eo de omnibus his. Qui dixit mihi interpretationem sermonum, et docuit me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 17, 'Hæ quatuor bestiæ magnæ, quatuor sunt regna, quæ consurgent de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 18, 'Suscipient autem regnum sancti Dei altissimi, et obtinebunt regnum usque in sæculum, et sæculum sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 19, 'Post hoc volui diligenter discere de bestia quarta, quæ erat dissimilis valde ab omnibus, et terribilis nimis: dentes et ungues ejus ferrei: comedebat, et comminuebat, et reliqua pedibus suis conculcabat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 20, 'et de cornibus decem, quæ habebat in capite, et de alio, quod ortum fuerat, ante quod ceciderant tria cornua: et de cornu illo, quod habebat oculos, et os loquens grandia, et majus erat ceteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 21, 'Aspiciebam, et ecce cornu illud faciebat bellum adversus sanctos, et prævalebat eis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 22, 'donec venit antiquus dierum, et judicium dedit sanctis Excelsi, et tempus advenit, et regnum obtinuerunt sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 23, 'Et sic ait: Bestia quarta, regnum quartum erit in terra, quod majus erit omnibus regnis, et devorabit universam terram, et conculcabit, et comminuet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 24, 'Porro cornua decem ipsius regni, decem reges erunt: et alius consurget post eos, et ipse potentior erit prioribus, et tres reges humiliabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 25, 'Et sermones contra Excelsum loquetur, et sanctos Altissimi conteret: et putabit quod possit mutare tempora, et leges: et tradentur in manu ejus usque ad tempus, et tempora, et dimidium temporis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 26, 'Et judicium sedebit, ut auferatur potentia, et conteratur, et dispereat usque in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 27, 'Regnum autem, et potestas, et magnitudo regni, quæ est subter omne cælum, detur populo sanctorum Altissimi: cujus regnum, regnum sempiternum est, et omnes reges servient ei, et obedient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 7, 28, 'Hucusque finis verbi. Ego Daniel multum cogitationibus meis conturbabar, et facies mea mutata est in me: verbum autem in corde meo conservavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 1, 'Anno tertio regni Baltassar regis, visio apparuit mihi. Ego Daniel, post id quod videram in principio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 2, 'vidi in visione mea, cum essem in Susis castro, quod est in \'lam regione: vidi autem in visione esse me super portam Ulai.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 3, 'Et levavi oculus meos, et vidi: et ecce aries unus stabat ante paludem, habens cornua excelsa, et unum excelsius altero atque succrescens. Postea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 4, 'vidi arietem cornibus ventilantem contra occidentem, et contra aquilonem, et contra meridiem, et omnes bestiæ non poterant resistere ei, neque liberari de manu ejus: fecitque secundum voluntatem suam, et magnificatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 5, 'Et ego intelligebam: ecce autem hircus caprarum veniebat ab occidente super faciem totius terræ, et non tangebat terram: porro hircus habebat cornu insigne inter oculos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 6, 'Et venit usque ad arietem illum cornutum, quem videram stantem ante portam, et cucurrit ad eum in impetu fortitudinis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 7, 'Cumque appropinquasset prope arietem, efferatus est in eum, et percussit arietem: et comminuit duo cornua ejus, et non poterat aries resistere ei: cumque eum misisset in terram, conculcavit, et nemo quibat liberare arietem de manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 8, 'Hircus autem caprarum magnus factus est nimis: cumque crevisset, fractum est cornu magnum, et orta sunt quatuor cornua subter illud per quatuor ventos cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 9, 'De uno autem ex eis egressum est cornu unum modicum: et factum est grande contra meridiem, et contra orientem, et contra fortitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 10, 'Et magnificatum est usque ad fortitudinem cæli: et dejecit de fortitudine, et de stellis, et conculcavit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 11, 'Et usque ad principem fortitudinis magnificatum est: et ab eo tulit juge sacrificium, et dejecit locum sanctificationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 12, 'Robur autem datum est ei contra juge sacrificium propter peccata: et prosternetur veritas in terra, et faciet, et prosperabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 13, 'Et audivi unum de sanctis loquentem: et dixit unus sanctus alteri nescio cui loquenti: Usquequo visio, et juge sacrificium, et peccatum desolationis quæ facta est: et sanctuarium, et fortitudo conculcabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 14, 'Et dixit ei: Usque ad vesperam et mane, dies duo millia trecenti: et mundabitur sanctuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 15, 'Factum est autem cum viderem ego Daniel visionem, et quærerem intelligentiam: ecce stetit in conspectu meo quasi species viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 16, 'Et audivi vocem viri inter Ulai: et clamavit, et ait: Gabriel, fac intelligere istam visionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 17, 'Et venit, et stetit juxta ubi ego stabam: cumque venisset, pavens corrui in faciem meam: et ait ad me: Intellige, fili hominis, quoniam in tempore finis complebitur visio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 18, 'Cumque loqueretur ad me, collapsus sum pronus in terram: et tetigit me, et statuit me in gradu meo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 19, 'dixitque mihi: Ego ostendam tibi quæ futura sunt in novissimo maledictionis: quoniam habet tempus finem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 20, 'Aries, quem vidisti habere cornua, rex Medorum est atque Persarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 21, 'Porro hircus caprarum, rex Græcorum est; et cornu grande, quod erat inter oculos ejus, ipse est rex primus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 22, 'Quod autem fracto illo surrexerunt quatuor pro eo: quatuor reges de gente ejus consurgent, sed non in fortitudine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 23, 'Et post regnum eorum, cum creverint iniquitates, consurget rex impudens facie, et intelligens propositiones;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 24, 'et roborabitur fortitudo ejus, sed non in viribus suis: et supra quam credi potest, universa vastabit, et prosperabitur, et faciet. Et interficiet robustos, et populum sanctorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 25, 'secundum voluntatem suam, et dirigetur dolus in manu ejus: et cor suum magnificabit, et in copia rerum omnium occidet plurimos: et contra principem principum consurget, et sine manu conteretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 26, 'Et visio vespere et mane, quæ dicta est, vera est: tu ergo visionem signa, quia post multos dies erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 8, 27, 'Et ego Daniel langui, et ægrotavi per dies: cumque surrexissem, faciebam opera regis, et stupebam ad visionem, et non erat qui interpretaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 1, 'In anno primo Darii filii Assueri de semine Medorum, qui imperavit super regnum Chaldæorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 2, 'anno uno regni ejus, ego Daniel intellexi in libris numerum annorum, de quo factus est sermo Domini ad Jeremiam prophetam, ut complerentur desolationis Jerusalem septuaginta anni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 3, 'Et posui faciem meam ad Dominum Deum meum rogare et deprecari in jejuniis, sacco, et cinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 4, 'Et oravi Dominum Deum meum, et confessus sum, et dixi: Obsecro, Domine Deus magne et terribilis, custodiens pactum, et misericordiam diligentibus te, et custodientibus mandata tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 5, 'peccavimus, iniquitatem fecimus, impie egimus, et recessimus: et declinavimus a mandatis tuis ac judiciis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 6, 'Non obedivimus servis tuis prophetis, qui locuti sunt in nomine tuo regibus nostris, principibus nostris, patribus nostris, omnique populo terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 7, 'Tibi, Domine, justitia: nobis autem confusio faciei, sicut est hodie viro Juda, et habitatoribus Jerusalem, et omni Israël, his qui prope sunt, et his qui procul in universis terris, ad quas ejecisti eos propter iniquitates eorum, in quibus peccaverunt in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 8, 'Domine, nobis confusio faciei, regibus nostris, principibus nostris, et patribus nostris, qui peccaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 9, 'Tibi autem Domino Deo nostro misericordia et propitiatio, quia recessimus a te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 10, 'et non audivimus vocem Domini Dei nostri ut ambularemus in lege ejus, quam posuit nobis per servos suos prophetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 11, 'Et omnis Israël prævaricati sunt legem tuam, et declinaverunt ne audirent vocem tuam: et stillavit super nos maledictio et detestatio quæ scripta est in libro Moysi servi Dei, quia peccavimus ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 12, 'Et statuit sermones suos, quos locutus est super nos et super principes nostros, qui judicaverunt nos, ut superinduceret in nos magnum malum, quale numquam fuit sub omni cælo, secundum quod factum est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 13, 'Sicut scriptum est in lege Moysi, omne malum hoc venit super nos: et non rogavimus faciem tuam, Domine Deus noster, ut reverteremur ab iniquitatibus nostris, et cogitaremus veritatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 14, 'Et vigilavit Dominus super malitiam, et adduxit eam super nos. Justus Dominus Deus noster in omnibus operibus suis, quæ fecit: non enim audivimus vocem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 15, 'Et nunc Domine Deus noster, qui eduxisti populum tuum de terra \'gypti in manu forti, et fecisti tibi nomen secundum diem hanc: peccavimus, iniquitatem fecimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 16, 'Domine, in omnem justitiam tuam avertatur, obsecro, ira tua et furor tuus a civitate tua Jerusalem, et monte sancto tuo. Propter peccata enim nostra, et iniquitates patrum nostrorum, Jerusalem et populus tuus in opprobrium sunt omnibus per circuitum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 17, 'Nunc ergo exaudi, Deus noster, orationem servi tui, et preces ejus: et ostende faciem tuam super sanctuarium tuum, quod desertum est propter temetipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 18, 'Inclina, Deus meus, aurem tuam, et audi: aperi oculos tuos, et vide desolationem nostram, et civitatem super quam invocatum est nomen tuum: neque enim in justificationibus nostris prosternimus preces ante faciem tuam, sed in miserationibus tuis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 19, 'Exaudi, Domine; placare Domine: attende et fac: ne moreris propter temetipsum, Deus meus, quia nomen tuum invocatum est super civitatem et super populum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 20, 'Cumque adhuc loquerer, et orarem, et confiterer peccata mea, et peccata populi mei Israël, et prosternerem preces meas in conspectu Dei mei, pro monte sancto Dei mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 21, 'adhuc me loquente in oratione, ecce vir Gabriel, quem videram in visione a principio, cito volans tetigit me in tempore sacrificii vespertini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 22, 'Et docuit me, et locutus est mihi, dixitque: Daniel, nunc egressus sum ut docerem te, et intelligeres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 23, 'Ab exordio precum tuarum egressus est sermo: ego autem veni ut indicarem tibi, quia vir desideriorum es: tu ergo animadverte sermonem, et intellige visionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 24, 'Septuaginta hebdomades abbreviatæ sunt super populum tuum et super urbem sanctam tuam, ut consummetur prævaricatio, et finem accipiat peccatum, et deleatur iniquitas, et adducatur justitia sempiterna, et impleatur visio et prophetia, et ungatur Sanctus sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 25, 'Scito ergo, et animadverte: ab exitu sermonis, ut iterum ædificetur Jerusalem, usque ad christum ducem, hebdomades septem, et hebdomades sexaginta duæ erunt: et rursum ædificabitur platea, et muri in angustia temporum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 26, 'Et post hebdomades sexaginta duas occidetur christus: et non erit ejus populus qui eum negaturus est. Et civitatem et sanctuarium dissipabit populus cum duce venturo: et finis ejus vastitas, et post finem belli statuta desolatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 9, 27, 'Confirmabit autem pactum multis hebdomada una: et in dimidio hebdomadis deficiet hostia et sacrificium: et erit in templo abominatio desolationis: et usque ad consummationem et finem perseverabit desolatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 1, 'Anno tertio Cyri regis Persarum, verbum revelatum est Danieli cognomento Baltassar, et verbum verum, et fortitudo magna: intellexitque sermonem: intelligentia enim est opus in visione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 2, 'In diebus illis ego Daniel lugebam trium hebdomadarum diebus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 3, 'panem desiderabilem non comedi, et caro et vinum non introierunt in os meum, sed neque unguento unctus sum, donec complerentur trium hebdomadarum dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 4, 'Die autem vigesima et quarta mensis primi, eram juxta fluvium magnum, qui est Tigris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 5, 'Et levavi oculos meos, et vidi: et ecce vir unus vestitus lineis, et renes ejus accincti auro obrizo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 6, 'et corpus ejus quasi chrysolithus, et facies ejus velut species fulguris, et oculi ejus ut lampas ardens: et brachia ejus, et quæ deorsum sunt usque ad pedes, quasi species æris candentis: et vox sermonum ejus ut vox multitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 7, 'Vidi autem ego Daniel solus visionem: porro viri qui erant mecum non viderunt, sed terror nimius irruit super eos, et fugerunt in absconditum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 8, 'Ego autem relictus solus vidi visionem grandem hanc: et non remansit in me fortitudo, sed et species mea immutata est in me, et emarcui, nec habui quidquam virium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 9, 'Et audivi vocem sermonum ejus: et audiens jacebam consternatus super faciem meam, et vultus meus hærebat terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 10, 'Et ecce manus tetigit me, et erexit me super genua mea, et super articulos manuum mearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 11, 'Et dixit ad me: Daniel vir desideriorum, intellige verba quæ ego loquor ad te, et sta in gradu tuo: nunc enim sum missus ad te. Cumque dixisset mihi sermonem istum, steti tremens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 12, 'Et ait ad me: Noli metuere, Daniel: quia ex die primo, quo posuisti cor tuum ad intelligendum ut te affligeres in conspectu Dei tui, exaudita sunt verba tua: et ego veni propter sermones tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 13, 'Princeps autem regni Persarum restitit mihi viginti et uno diebus: et ecce Michaël, unus de principibus primis, venit in adjutorium meum, et ego remansi ibi juxta regem Persarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 14, 'Veni autem ut docerem te quæ ventura sunt populo tuo in novissimis diebus, quoniam adhuc visio in dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 15, 'Cumque loqueretur mihi hujuscemodi verbis, dejeci vultum meum ad terram, et tacui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 16, 'Et ecce quasi similitudo filii hominis tetigit labia mea: et aperiens os meum locutus sum, et dixi ad eum, qui stabat contra me: Domine mi, in visione tua dissolutæ sunt compages meæ, et nihil in me remansit virium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 17, 'Et quomodo poterit servus domini mei loqui cum domino meo? nihil enim in me remansit virium, sed et halitus meus intercluditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 18, 'Rursum ergo tetigit me quasi visio hominis, et confortavit me,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 19, 'et dixit: Noli timere, vir desideriorum: pax tibi: confortare, et esto robustus. Cumque loqueretur mecum, convalui, et dixi: Loquere, domine mi, quia confortasti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 20, 'Et ait: Numquid scis quare venerim ad te? et nunc revertar ut prælier adversum principem Persarum. Cum ego egrederer, apparuit princeps Græcorum veniens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 10, 21, 'Verumtamen annuntiabo tibi quod expressum est in scriptura veritatis: et nemo est adjutor meus in omnibus his, nisi Michaël princeps vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 1, 'Ego autem ab anno primo Darii Medi stabam ut confortaretur et roboraretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 2, 'Et nunc veritatem annuntiabo tibi. Ecce adhuc tres reges stabunt in Perside, et quartus ditabitur opibus nimiis super omnes: et cum invaluerit divitiis suis, concitabit omnes adversum regnum Græciæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 3, 'Surget vero rex fortis, et dominabitur potestate multa, et faciet quod placuerit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 4, 'Et cum steterit, conteretur regnum ejus, et dividetur in quatuor ventos cæli: sed non in posteros ejus, neque secundum potentiam illius, qua dominatus est: lacerabitur enim regnum ejus etiam in externos, exceptis his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 5, 'Et confortabitur rex austri: et de principibus ejus prævalebit super eum, et dominabitur ditione: multa enim dominatio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 6, 'Et post finem annorum fœderabuntur: filiaque regis austri veniet ad regem aquilonis facere amicitiam, et non obtinebit fortitudinem brachii, nec stabit semen ejus: et tradetur ipsa, et qui adduxerunt eam adolescentes ejus, et qui confortabant eam in temporibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 7, 'Et stabit de germine radicum ejus plantatio: et veniet cum exercitu, et ingredietur provinciam regis aquilonis: et abutetur eis, et obtinebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 8, 'Insuper et deos eorum, et sculptilia, vasa quoque pretiosa argenti et auri, captiva ducet in \'gyptum: ipse prævalebit adversus regem aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 9, 'Et intrabit in regnum rex austri, et revertetur ad terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 10, 'Filii autem ejus provocabuntur, et congregabunt multitudinem exercituum plurimorum: et veniet properans, et inundans: et revertetur, et concitabitur, et congredietur cum robore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 11, 'Et provocatus rex austri egredietur, et pugnabit adversus regem aquilonis, et præparabit multitudinem nimiam, et dabitur multitudo in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 12, 'Et capiet multitudinem, et exaltabitur cor ejus, et dejiciet multa millia, sed non prævalebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 13, 'Convertetur enim rex aquilonis, et præparabit multitudinem multo majorem quam prius: et in fine temporum annorumque veniet properans cum exercitu magno, et opibus nimiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 14, 'Et in temporibus illis multi consurgent adversus regem austri: filii quoque prævaricatorum populi tui extollentur ut impleant visionem, et corruent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 15, 'Et venit rex aquilonis, et comportabit aggerem, et capiet urbes munitissimas: et brachia austri non sustinebunt, et consurgent electi ejus ad resistendum, et non erit fortitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 16, 'Et faciet veniens super eum juxta placitum suum, et non erit qui stet contra faciem ejus: et stabit in terra inclyta, et consumetur in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 17, 'Et ponet faciem suam ut veniat ad tenendum universum regnum ejus, et recta faciet cum eo: et filiam feminarum dabit ei, ut evertat illud: et non stabit, nec illius erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 18, 'Et convertet faciem suam ad insulas, et capiet multas: et cessare faciet principem opprobrii sui, et opprobrium ejus convertetur in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 19, 'Et convertet faciem suam ad imperium terræ suæ, et impinget, et corruet, et non invenietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 20, 'Et stabit in loco ejus vilissimus, et indignus decore regio: et in paucis diebus conteretur, non in furore, nec in prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 21, 'Et stabit in loco ejus despectus, et non tribuetur ei honor regius: et veniet clam, et obtinebit regnum in fraudulentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 22, 'Et brachia pugnantis expugnabuntur a facie ejus, et conterentur: insuper et dux fœderis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 23, 'Et post amicitias, cum eo faciet dolum: et ascendet, et superabit in modico populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 24, 'Et abundantes, et uberes urbes ingredietur: et faciet quæ non fecerunt patres ejus, et patres patrum ejus: rapinas, et prædam, et divitias eorum dissipabit, et contra firmissimas cogitationes inibit: et hoc usque ad tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 25, 'Et concitabitur fortitudo ejus, et cor ejus adversum regem austri in exercitu magno: et rex austri provocabitur ad bellum multis auxiliis, et fortibus nimis: et non stabunt, quia inibunt adversus eum consilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 26, 'Et comedentes panem cum eo, conterent illum, exercitusque ejus opprimetur: et cadent interfecti plurimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 27, 'Duorum quoque regum cor erit ut malefaciant, et ad mensam unam mendacium loquentur: et non proficient, quia adhuc finis in aliud tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 28, 'Et revertetur in terram suam cum opibus multis: et cor ejus adversum testamentum sanctum, et faciet, et revertetur in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 29, 'Statuto tempore revertetur, et veniet ad austrum: et non erit priori simile novissimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 30, 'Et venient super eum trieres, et Romani: et percutietur, et revertetur, et indignabitur contra testamentum sanctuarii, et faciet: reverteturque, et cogitabit adversum eos qui dereliquerunt testamentum sanctuarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 31, 'Et brachia ex eo stabunt, et polluent sanctuarium fortitudinis, et auferent juge sacrificium: et dabunt abominationem in desolationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 32, 'Et impii in testamentum simulabunt fraudulenter: populus autem sciens Deum suum, obtinebit, et faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 33, 'Et docti in populo docebunt plurimos: et ruent in gladio, et in flamma, et in captivitate, et in rapina dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 34, 'Cumque corruerint, sublevabuntur auxilio parvulo: et applicabuntur eis plurimi fraudulenter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 35, 'Et de eruditis ruent, ut conflentur, et eligantur, et dealbentur usque ad tempus præfinitum: quia adhuc aliud tempus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 36, 'Et faciet juxta voluntatem suam rex, et elevabitur, et magnificabitur adversus omnem deum: et adversus Deum deorum loquetur magnifica, et dirigetur, donec compleatur iracundia: perpetrata quippe est definitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 37, 'Et Deum patrum suorum non reputabit: et erit in concupiscentiis feminarum, nec quemquam deorum curabit, quia adversum universa consurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 38, 'Deum autem Maozim in loco suo venerabitur: et deum, quem ignoraverunt patres ejus, colet auro, et argento, et lapide pretioso, rebusque pretiosis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 39, 'Et faciet ut muniat Maozim cum deo alieno, quem cognovit, et multiplicabit gloriam, et dabit eis potestatem in multis, et terram dividet gratuito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 40, 'Et in tempore præfinito præliabitur adversus eum rex austri, et quasi tempestas veniet contra illum rex aquilonis in curribus, et in equitibus, et in classe magna, et ingredietur terras, et conteret, et pertransiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 41, 'Et introibit in terram gloriosam, et multæ corruent: hæ autem solæ salvabuntur de manu ejus, Edom, et Moab, et principium filiorum Ammon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 42, 'Et mittet manum suam in terras: et terra \'gypti non effugiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 43, 'Et dominabitur thesaurorum auri, et argenti, et in omnibus pretiosis \'gypti: per Libyam quoque, et \'thiopiam transibit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 44, 'Et fama turbabit eum ab oriente et ab aquilone: et veniet in multitudine magna ut conterat et interficiat plurimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 11, 45, 'Et figet tabernaculum suum Apadno inter maria, super montem inclytum et sanctum: et veniet usque ad summitatem ejus, et nemo auxiliabitur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 1, 'In tempore autem illo consurget Michaël princeps magnus, qui stat pro filiis populi tui: et veniet tempus quale non fuit ab eo ex quo gentes esse cœperunt usque ad tempus illud. Et in tempore illo salvabitur populus tuus, omnis qui inventus fuerit scriptus in libro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 2, 'Et multi de his qui dormiunt in terræ pulvere evigilabunt, alii in vitam æternam, et alii in opprobrium ut videant semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 3, 'Qui autem docti fuerint, fulgebunt quasi splendor firmamenti: et qui ad justitiam erudiunt multos, quasi stellæ in perpetuas æternitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 4, 'Tu autem Daniel, claude sermones, et signa librum usque ad tempus statutum: plurimi pertransibunt, et multiplex erit scientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 5, 'Et vidi ego Daniel, et ecce quasi duo alii stabant: unus hinc super ripam fluminis, et alius inde ex altera ripa fluminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 6, 'Et dixi viro qui erat indutus lineis, qui stabat super aquas fluminis: Usquequo finis horum mirabilium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 7, 'Et audivi virum qui indutus erat lineis, qui stabat super aquas fluminis, cum elevasset dexteram et sinistram suam in cælum, et jurasset per viventem in æternum, quia in tempus, et tempora, et dimidium temporis. Et cum completa fuerit dispersio manus populi sancti, complebuntur universa hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 8, 'Et ego audivi, et non intellexi. Et dixi: Domine mi, quid erit post hæc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 9, 'Et ait: Vade, Daniel, quia clausi sunt signatique sermones usque ad præfinitum tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 10, 'Eligentur, et dealbabuntur, et quasi ignis probabuntur multi: et impie agent impii, neque intelligent omnes impii: porro docti intelligent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 11, 'Et a tempore cum ablatum fuerit juge sacrificium, et posita fuerit abominatio in desolationem, dies mille ducenti nonaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 12, 'Beatus qui exspectat, et pervenit usque ad dies mille trecentos triginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 12, 13, 'Tu autem vade ad præfinitum: et requiesces, et stabis in sorte tua in finem dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 1, 'Et erat vir habitans in Babylone, et nomen ejus Joakim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 2, 'et accepit uxorem nomine Susannam, filiam Helciæ, pulchram nimis, et timentem Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 3, 'parentes enim illius, cum essent justi, erudierunt filiam suam secundum legem Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 4, 'Erat autem Joakim dives valde, et erat ei pomarium vicinum domui suæ: et ad ipsum confluebant Judæi, eo quod esset honorabilior omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 5, 'Et constituti sunt de populo duo senes judices in illo anno, de quibus locutus est Dominus: Quia egressa est iniquitas de Babylone a senioribus judicibus, qui videbantur regere populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 6, 'Isti frequentabant domum Joakim, et veniebant ad eos omnes qui habebant judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 7, 'Cum autem populus revertisset per meridiem, ingrediebatur Susanna, et deambulabat in pomario viri sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 8, 'Et videbant eam senes quotidie ingredientem et deambulantem, et exarserunt in concupiscentiam ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 9, 'et everterunt sensum suum, et declinaverunt oculos suos ut non viderent cælum, neque recordarentur judiciorum justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 10, 'Erant ergo ambo vulnerati amore ejus, nec indicaverunt sibi vicissim dolorem suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 11, 'erubescebant enim indicare sibi concupiscentiam suam, volentes concumbere cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 12, 'Et observabant quotidie sollicitius videre eam. Dixitque alter ad alterum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 13, 'Eamus domum, quia hora prandii est. Et egressi, recesserunt a se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 14, 'Cumque revertissent, venerunt in unum: et sciscitantes ab invicem causam, confessi sunt concupiscentiam suam: et tunc in communi statuerunt tempus quando eam possent invenire solam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 15, 'Factum est autem, cum observarent diem aptum, ingressa est aliquando sicut heri et nudiustertius, cum duabus solis puellis, voluitque lavari in pomario: æstus quippe erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 16, 'et non erat ibi quisquam, præter duos senes absconditos, et contemplantes eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 17, 'Dixit ergo puellis: Afferte mihi oleum, et smigmata, et ostia pomarii claudite, ut laver.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 18, 'Et fecerunt sicut præceperat: clauseruntque ostia pomarii, et egressæ sunt per posticum ut afferrent quæ jusserat; nesciebantque senes intus esse absconditos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 19, 'Cum autem egressæ essent puellæ, surrexerunt duo senes, et accurrerunt ad eam, et dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 20, 'Ecce ostia pomarii clausa sunt, et nemo nos videt, et nos in concupiscentia tui sumus: quam ob rem assentire nobis, et commiscere nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 21, 'Quod si nolueris, dicemus contra te testimonium, quod fuerit tecum juvenis, et ob hanc causam emiseris puellas a te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 22, 'Ingemuit Susanna, et ait: Angustiæ sunt mihi undique: si enim hoc egero, mors mihi est: si autem non egero, non effugiam manus vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 23, 'Sed melius est mihi absque opere incidere in manus vestras, quam peccare in conspectu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 24, 'Et exclamavit voce magna Susanna: exclamaverunt autem et senes adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 25, 'Et cucurrit unus ad ostia pomarii, et aperuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 26, 'Cum ergo audissent clamorem famuli domus in pomario, irruerunt per posticum ut viderent quidnam esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 27, 'Postquam autem senes locuti sunt, erubuerunt servi vehementer, quia numquam dictus fuerat sermo hujuscemodi de Susanna. Et facta est dies crastina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 28, 'Cumque venisset populus ad Joakim virum ejus, venerunt et duo presbyteri, pleni iniqua cogitatione adversus Susannam ut interficerent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 29, 'Et dixerunt coram populo: Mittite ad Susannam filiam Helciæ uxorem Joakim. Et statim miserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 30, 'Et venit cum parentibus, et filiis, et universis cognatis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 31, 'Porro Susanna erat delicata nimis, et pulchra specie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 32, 'At iniqui illi jusserunt ut discooperiretur (erat enim cooperta), ut vel sic satiarentur decore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 33, 'Flebant igitur sui, et omnes qui noverant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 34, 'Consurgentes autem duo presbyteri in medio populi, posuerunt manus suas super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 35, 'Quæ flens suspexit ad cælum: erat enim cor ejus fiduciam habens in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 36, 'Et dixerunt presbyteri: Cum deambularemus in pomario soli, ingressa est hæc cum duabus puellis: et clausit ostia pomarii, et dimisit a se puellas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 37, 'Venitque ad eam adolescens, qui erat absconditus, et concubuit cum ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 38, 'Porro nos cum essemus in angulo pomarii, videntes iniquitatem, cucurrimus ad eos, et vidimus eos pariter commisceri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 39, 'Et illum quidem non quivimus comprehendere, quia fortior nobis erat, et apertis ostiis exilivit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 40, 'hanc autem cum apprehendissemus, interrogavimus, quisnam esset adolescens, et noluit indicare nobis: hujus rei testes sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 41, 'Credidit eis multitudo quasi senibus et judicibus populi, et condemnaverunt eam ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 42, 'Exclamavit autem voce magna Susanna, et dixit: Deus æterne, qui absconditorum es cognitor, qui nosti omnia antequam fiant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 43, 'tu scis quoniam falsum testimonium tulerunt contra me: et ecce morior, cum nihil horum fecerim, quæ isti malitiose composuerunt adversum me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 44, 'Exaudivit autem Dominus vocem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 45, 'Cumque duceretur ad mortem, suscitavit Dominus spiritum sanctum pueri junioris, cujus nomen Daniel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 46, 'et exclamavit voce magna: Mundus ego sum a sanguine hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 47, 'Et conversus omnis populus ad eum, dixit: Quis est iste sermo, quem tu locutus es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 48, 'Qui cum staret in medio eorum, ait: Sic fatui filii Israël, non judicantes, neque quod verum est cognoscentes, condemnastis filiam Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 49, 'revertimini ad judicium, quia falsum testimonium locuti sunt adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 50, 'Reversus est ergo populus cum festinatione, et dixerunt ei senes: Veni, et sede in medio nostrum, et indica nobis: quia tibi Deus dedit honorem senectutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 51, 'Et dixit ad eos Daniel: Separate illos ab invicem procul, et dijudicabo eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 52, 'Cum ergo divisi essent alter ab altero, vocavit unum de eis, et dixit ad eum: Inveterate dierum malorum, nunc venerunt peccata tua, quæ operabaris prius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 53, 'judicans judicia injusta, innocentes opprimens, et dimittens noxios, dicente Domino: Innocentem et justum non interficies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 54, 'Nunc ergo, si vidisti eam, dic sub qua arbore videris eos colloquentes sibi. Qui ait: Sub schino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 55, 'Dixit autem Daniel: Recte mentitus es in caput tuum: ecce enim angelus Dei, accepta sententia ab eo, scindet te medium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 56, 'Et, amoto eo, jussit venire alium, et dixit ei: Semen Chanaan, et non Juda, species decepit te, et concupiscentia subvertit cor tuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 57, 'sic faciebatis filiabus Israël, et illæ timentes loquebantur vobis: sed filia Juda non sustinuit iniquitatem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 58, 'Nunc ergo, dic mihi sub qua arbore comprehenderis eos loquentes sibi. Qui ait: Sub prino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 59, 'Dixit autem ei Daniel: Recte mentitus es et tu in caput tuum: manet enim angelus Domini, gladium habens, ut secet te medium, et interficiat vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 60, 'Exclamavit itaque omnis cœtus voce magna, et benedixerunt Deum, qui salvat sperantes in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 61, 'Et consurrexerunt adversus duos presbyteros (convicerat enim eos Daniel ex ore suo falsum dixisse testimonium), feceruntque eis sicut male egerant adversus proximum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 62, 'ut facerent secundum legem Moysi. Et interfecerunt eos, et salvatus est sanguis innoxius in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 63, 'Helcias autem et uxor ejus laudaverunt Deum pro filia sua Susanna cum Joakim marito ejus, et cognatis omnibus, quia non esset inventa in ea res turpis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 64, 'Daniel autem factus est magnus in conspectu populi a die illa, et deinceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 13, 65, 'Et rex Astyages appositus est ad patres suos, et suscepit Cyrus Perses regnum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 1, 'Erat autem Daniel conviva regis, et honoratus super omnes amicos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 2, 'Erat quoque idolum apud Babylonios nomine Bel: et impendebantur in eo per dies singulos similæ artabæ duodecim, et oves quadraginta, vinique amphoræ sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 3, 'Rex quoque colebat eum, et ibat per singulos dies adorare eum: porro Daniel adorabat Deum suum. Dixitque ei rex: Quare non adoras Bel?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 4, 'Qui respondens ait ei: Quia non colo idola manufacta, sed viventem Deum, qui creavit cælum, et terram, et habet potestatem omnis carnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 5, 'Et dixit rex ad eum: Non videtur tibi esse Bel vivens deus? an non vides quanta comedat et bibat quotidie?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 6, 'Et ait Daniel arridens: Ne erres, rex: iste enim intrinsecus luteus est, et forinsecus æreus, neque comedit aliquando.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 7, 'Et iratus rex vocavit sacerdotes ejus, et ait eis: Nisi dixeritis mihi quis est qui comedat impensas has, moriemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 8, 'Si autem ostenderitis quoniam Bel comedat hæc, morietur Daniel, quia blasphemavit in Bel. Et dixit Daniel regi: Fiat juxta verbum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 9, 'Erant autem sacerdotes Bel septuaginta, exceptis uxoribus, et parvulis, et filiis. Et venit rex cum Daniele in templum Bel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 10, 'Et dixerunt sacerdotes Bel: Ecce nos egredimur foras: et tu, rex, pone escas, et vinum misce, et claude ostium, et signa annulo tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 11, 'et cum ingressus fueris mane, nisi inveneris omnia comesta a Bel, morte moriemur, vel Daniel qui mentitus est adversum nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 12, 'Contemnebant autem, quia fecerant sub mensa absconditum introitum, et per illum ingrediebantur semper, et devorabant ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 13, 'Factum est igitur postquam egressi sunt illi, rex posuit cibos ante Bel: præcepit Daniel pueris suis, et attulerunt cinerem, et cribravit per totum templum coram rege: et egressi clauserunt ostium, et signantes annulo regis abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 14, 'Sacerdotes autem ingressi sunt nocte juxta consuetudinem suam, et uxores et filii eorum, et comederunt omnia, et biberunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 15, 'Surrexit autem rex primo diluculo, et Daniel cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 16, 'Et ait rex: Salvane sunt signacula, Daniel? Qui respondit: Salva, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 17, 'Statimque cum aperuisset ostium, intuitus rex mensam, exclamavit voce magna: Magnus es, Bel, et non est apud te dolus quisquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 18, 'Et risit Daniel, et tenuit regem ne ingrederetur intro: et dixit: Ecce pavimentum: animadverte cujus vestigia sint hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 19, 'Et dixit rex: Video vestigia virorum, et mulierum, et infantium. Et iratus est rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 20, 'Tunc apprehendit sacerdotes, et uxores, et filios eorum: et ostenderunt ei abscondita ostiola, per quæ ingrediebantur, et consumebant quæ erant super mensam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 21, 'Occidit ergo illos rex, et tradidit Bel in potestatem Danielis: qui subvertit eum, et templum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 22, 'Et erat draco magnus in loco illo, et colebant eum Babylonii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 23, 'Et dixit rex Danieli: Ecce nunc non potes dicere quia iste non sit deus vivens: adora ergo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 24, 'Dixitque Daniel: Dominum Deum meum adoro, quia ipse est Deus vivens: iste autem non est deus vivens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 25, 'Tu autem, rex, da mihi potestatem, et interficiam draconem absque gladio et fuste. Et ait rex: Do tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 26, 'Tulit ergo Daniel picem, et adipem, et pilos, et coxit pariter: fecitque massas, et dedit in os draconis, et diruptus est draco. Et dixit: Ecce quem colebatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 27, 'Quod cum audissent Babylonii, indignati sunt vehementer: et congregati adversum regem, dixerunt: Judæus factus est rex: Bel destruxit, draconem interfecit, et sacerdotes occidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 28, 'Et dixerunt cum venissent ad regem: Trade nobis Danielem, alioquin interficiemus te, et domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 29, 'Vidit ergo rex quod irruerent in eum vehementer: et necessitate compulsus, tradidit eis Danielem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 30, 'Qui miserunt eum in lacum leonum, et erat ibi diebus sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 31, 'Porro in lacu erant leones septem, et dabantur eis duo corpora quotidie, et duæ oves: et tunc non data sunt eis, ut devorarent Danielem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 32, 'Erat autem Habacuc propheta in Judæa, et ipse coxerat pulmentum, et intriverat panes in alveolo: et ibat in campum ut ferret messoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 33, 'Dixitque angelus Domini ad Habacuc: Fer prandium quod habes in Babylonem Danieli, qui est in lacu leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 34, 'Et dixit Habacuc: Domine, Babylonem non vidi, et lacum nescio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 35, 'Et apprehendit eum angelus Domini in vertice ejus, et portavit eum capillo capitis sui, posuitque eum in Babylone supra lacum in impetu spiritus sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 36, 'Et clamavit Habacuc, dicens: Daniel serve Dei, tolle prandium quod misit tibi Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 37, 'Et ait Daniel: Recordatus es mei, Deus, et non dereliquisti diligentes te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 38, 'Surgensque Daniel comedit. Porro angelus Domini restituit Habacuc confestim in loco suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 39, 'Venit ergo rex die septimo ut lugeret Danielem: et venit ad lacum, et introspexit, et ecce Daniel sedens in medio leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 40, 'Et exclamavit voce magna rex, dicens: Magnus es, Domine Deus Danielis. Et extraxit eum de lacu leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 41, 'Porro illos, qui perditionis ejus causa fuerant, intromisit in lacum, et devorati sunt in momento coram eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 14, 42, 'Tunc rex ait: Paveant omnes habitantes in universa terra Deum Danielis: quia ipse est salvator, faciens signa et mirabilia in terra: qui liberavit Danielem de lacu leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Verbum Domini, quod factum est ad Osee, filium Beeri, in diebus Oziæ, Joathan, Achaz, Ezechiæ, regum Juda; et in diebus Jeroboam, filii Joas, regis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Principium loquendi Domino in Osee. Et dixit Dominus ad Osee: Vade, sume tibi uxorem fornicationum, et fac tibi filios fornicationum, quia fornicans fornicabitur terra a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Et abiit, et accepit Gomer, filiam Debelaim: et concepit, et peperit ei filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Et dixit Dominus ad eum: Voca nomen ejus Jezrahel, quoniam adhuc modicum, et visitabo sanguinem Jezrahel super domum Jehu, et quiescere faciam regnum domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Et in illa die conteram arcum Israël in valle Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Et concepit adhuc, et peperit filiam. Et dixit ei: Voca nomen ejus, Absque misericordia, quia non addam ultra misereri domui Israël, sed oblivione obliviscar eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Et domui Juda miserebor, et salvabo eos in Domino Deo suo; et non salvabo eos in arcu et gladio, et in bello, et in equis, et in equitibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Et ablactavit eam quæ erat Absque misericordia. Et concepit, et peperit filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Et dixit: Voca nomen ejus, Non populus meus, quia vos non populus meus, et ego non ero vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Et erit numerus filiorum Israël quasi arena maris, quæ sine mensura est, et non numerabitur. Et erit in loco ubi dicetur eis: Non populus meus vos: dicetur eis: Filii Dei viventis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Et congregabuntur filii Juda et filii Israël pariter; et ponent sibimet caput unum, et ascendent de terra, quia magnus dies Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Dicite fratribus vestris: Populus meus; et sorori vestræ: Misericordiam consecuta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Judicate matrem vestram, judicate, quoniam ipsa non uxor mea, et ego non vir ejus. Auferat fornicationes suas a facie sua, et adulteria sua de medio uberum suorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'ne forte expoliem eam nudam, et statuam eam secundum diem nativitatis suæ, et ponam eam quasi solitudinem, et statuam eam velut terram inviam, et interficiam eam siti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Et filiorum illius non miserebor, quoniam filii fornicationum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Quia fornicata est mater eorum, confusa est quæ concepit eos; quia dixit: Vadam post amatores meos, qui dant panes mihi, et aquas meas, lanam meam, et linum meum, oleum meum, et potum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Propter hoc ecce ego sepiam viam tuam spinis, et sepiam eam maceria, et semitas suas non inveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Et sequetur amatores suos, et non apprehendet eos; et quæret eos, et non inveniet: et dicet: Vadam, et revertar ad virum meum priorem, quia bene mihi erat tunc magis quam nunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Et hæc nescivit, quia ego dedi ei frumentum, et vinum, et oleum, et argentum multiplicavi ei, et aurum, quæ fecerunt Baal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Idcirco convertar, et sumam frumentum meum in tempore suo, et vinum meum in tempore suo. Et liberabo lanam meam et linum meum, quæ operiebant ignominiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Et nunc revelabo stultitiam ejus in oculis amatorum ejus; et vir non eruet eam de manu mea;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'et cessare faciam omne gaudium ejus, solemnitatem ejus, neomeniam ejus, sabbatum ejus, et omnia festa tempora ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Et corrumpam vineam ejus, et ficum ejus, de quibus dixit: Mercedes hæ meæ sunt, quas dederunt mihi amatores mei; et ponam eam in saltum, et comedet eam bestia agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Et visitabo super eam dies Baalim, quibus accendebat incensum, et ornabatur in aure sua, et monili suo. Et ibat post amatores suos, et mei obliviscebatur, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 14, 'Propter hoc ecce ego lactabo eam, et ducam eam in solitudinem, et loquar ad cor ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 15, 'Et dabo ei vinitores ejus ex eodem loco, et vallem Achor, ad aperiendam spem; et canet ibi juxta dies juventutis suæ, et juxta dies ascensionis suæ de terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 16, 'Et erit in die illa, ait Dominus: vocabit me, Vir meus, et non vocabit me ultra Baali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 17, 'Et auferam nomina Baalim de ore ejus, et non recordabitur ultra nominis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 18, 'Et percutiam cum eis fœdus in die illa, cum bestia agri, et cum volucre cæli, et cum reptili terræ; et arcum, et gladium, et bellum conteram de terra, et dormire eos faciam fiducialiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 19, 'Et sponsabo te mihi in sempiternum; et sponsabo te mihi in justitia, et judicio, et in misericordia, et in miserationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 20, 'Et sponsabo te mihi in fide; et scies quia ego Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 21, 'Et erit in die illa: exaudiam, dicit Dominus, exaudiam cælos, et illi exaudient terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 22, 'Et terra exaudiet triticum, et vinum, et oleum, et hæc exaudient Jezrahel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 23, 'Et seminabo eam mihi in terra, et miserebor ejus quæ fuit Absque misericordia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 24, 'Et dicam Non populo meo: Populus meus es tu; et ipse dicet: Deus meus es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Et dixit Dominus ad me: Adhuc vade, et dilige mulierem dilectam amico et adulteram, sicut diligit Dominus filios Israël, et ipsi respiciunt ad deos alienos, et diligunt vinacia uvarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Et fodi eam mihi quindecim argenteis, et coro hordei, et dimidio coro hordæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Et dixi ad eam: Dies multos exspectabis me; non fornicaberis, et non eris viro; sed et ego exspectabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Quia dies multos sedebunt filii Israël sine rege, et sine principe, et sine sacrificio, et sine altari, et sine ephod, et sine theraphim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Et post hæc revertentur filii Israël, et quærent Dominum Deum suum, et David regem suum: et pavebunt ad Dominum, et ad bonum ejus, in novissimo dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Audite verbum Domini, filii Israël, quia judicium Domino cum habitatoribus terræ: non est enim veritas, et non est misericordia, et non est scientia Dei in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Maledictum, et mendacium, et homicidium, et furtum, et adulterium inundaverunt, et sanguis sanguinem tetigit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Propter hoc lugebit terra, et infirmabitur omnis qui habitat in ea, in bestia agri, et in volucre cæli; sed et pisces maris congregabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Verumtamen unusquisque non judicet, et non arguatur vir: populus enim tuus sicut hi qui contradicunt sacerdoti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Et corrues hodie, et corruet etiam propheta tecum. Nocte tacere feci matrem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Conticuit populus meus, eo quod non habuerit scientiam: quia tu scientiam repulisti, repellam te, ne sacerdotio fungaris mihi; et oblita es legis Dei tui, obliviscar filiorum tuorum et ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Secundum multitudinem eorum sic peccaverunt mihi: gloriam eorum in ignominiam commutabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Peccata populi mei comedent, et ad iniquitatem eorum sublevabunt animas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Et erit sicut populus, sic sacerdos; et visitabo super eum vias ejus, et cogitationes ejus reddam ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Et comedent, et non saturabuntur; fornicati sunt, et non cessaverunt: quoniam Dominum dereliquerunt in non custodiendo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Fornicatio, et vinum, et ebrietas auferunt cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Populus meus in ligno suo interrogavit, et baculus ejus annuntiavit ei; spiritus enim fornicationum decepit eos, et fornicati sunt a Deo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Super capita montium sacrificabant, et super colles ascendebant thymiama; subtus quercum, et populum, et terebinthum, quia bona erat umbra ejus; ideo fornicabuntur filiæ vestræ, et sponsæ vestræ adulteræ erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Non visitabo super filias vestras cum fuerint fornicatæ, et super sponsas vestras cum adulteraverint, quoniam ipsi cum meretricibus conversabantur, et cum effeminatis sacrificabant; et populus non intelligens vapulabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 15, 'Si fornicaris tu, Israël, non delinquat saltem Juda; et nolite ingredi in Galgala, et ne ascenderitis in Bethaven, neque juraveritis: Vivit Dominus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 16, 'Quoniam sicut vacca lasciviens declinavit Israël; nunc pascet eos Dominus, quasi agnum in latitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 17, 'Particeps idolorum Ephraim: dimitte eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 18, 'Separatum est convivium eorum; fornicatione fornicati sunt: dilexerunt afferre ignominiam protectores ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 19, 'Ligavit eum spiritus in alis suis, et confundentur a sacrificiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Audite hoc, sacerdotes, et attendite, domus Israël, et domus regis, auscultate: quia vobis judicium est, quoniam laqueus facti estis speculationi, et rete expansum super Thabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Et victimas declinastis in profundum; et ego eruditor omnium eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Ego scio Ephraim, et Israël non est absconditus a me: quia nunc fornicatus est Ephraim; contaminatus est Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Non dabunt cogitationes suas ut revertantur ad Deum suum, quia spiritus fornicationum in medio eorum, et Dominum non cognoverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Et respondebit arrogantia Israël in facie ejus, et Israël et Ephraim ruent in iniquitate sua: ruet etiam Judas cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'In gregibus suis et in armentis suis vadent ad quærendum Dominum, et non invenient: ablatus est ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'In Dominum prævaricati sunt, quia filios alienos genuerunt: nunc devorabit eos mensis, cum partibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Clangite buccina in Gabaa, tuba in Rama; ululate in Bethaven, post tergum tuum, Benjamin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Ephraim in desolatione erit in die correptionis; in tribubus Israël ostendi fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Facti sunt principes Juda quasi assumentes terminum; super eos effundam quasi aquam iram meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Calumniam patiens est Ephraim, fractus judicio, quoniam cœpit abire post sordes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Et ego quasi tinea Ephraim, et quasi putredo domui Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Et vidit Ephraim languorem suum, et Juda vinculum suum; et abiit Ephraim ad Assur, et misit ad regem ultorem: et ipse non poterit sanare vos, nec solvere poterit a vobis vinculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Quoniam ego quasi leæna Ephraim, et quasi catulus leonis domui Juda. Ego, ego capiam, et vadam; tollam, et non est qui eruat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Vadens revertar ad locum meum, donec deficiatis, et quæratis faciem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'In tribulatione sua mane consurgent ad me: Venite, et revertamur ad Dominum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'quia ipse cepit, et sanabit nos; percutiet, et curabit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Vivificabit nos post duos dies; in die tertia suscitabit nos, et vivemus in conspectu ejus. Sciemus, sequemurque ut cognoscamus Dominum: quasi diluculum præparatus est egressus ejus, et veniet quasi imber nobis temporaneus et serotinus terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Quid faciam tibi, Ephraim? quid faciam tibi, Juda? misericordia vestra quasi nubes matutina, et quasi ros mane pertransiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Propter hoc dolavi in prophetis; occidi eos in verbis oris mei: et judicia tua quasi lux egredientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Quia misericordiam volui, et non sacrificium; et scientiam Dei plus quam holocausta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Ipsi autem sicut Adam transgressi sunt pactum: ibi prævaricati sunt in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Galaad civitas operantium idolum, supplantata sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Et quasi fauces virorum latronum, particeps sacerdotum, in via interficientium pergentes de Sichem: quia scelus operati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'In domo Israël vidi horrendum: ibi fornicationes Ephraim, contaminatus est Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Sed et Juda, pone messem tibi, cum convertero captivitatem populi mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Cum sanare vellem Israël, revelata est iniquitas Ephraim, et malitia Samariæ, quia operati sunt mendacium; et fur ingressus est spolians, latrunculus foris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Et ne forte dicant in cordibus suis, omnem malitiam eorum me recordatum, nunc circumdederunt eos adinventiones suæ: coram facie mea factæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'In malitia sua lætificaverunt regem, et in mendaciis suis principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Omnes adulterantes, quasi clibanus succensus a coquente; quievit paululum civitas a commistione fermenti, donec fermentaretur totum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Dies regis nostri: cœperunt principes furere a vino; extendit manum suam cum illusoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Quia applicuerunt quasi clibanum cor suum, cum insidiaretur eis; tota nocte dormivit coquens eos: mane ipse succensus quasi ignis flammæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Omnes calefacti sunt quasi clibanus, et devoraverunt judices suos: omnes reges eorum ceciderunt; non est qui clamat in eis ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ephraim in populis ipse commiscebatur; Ephraim factus est subcinericius panis, qui non reversatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Comederunt alieni robur ejus, et ipse nescivit; sed et cani effusi sunt in eo, et ipse ignoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Et humiliabitur superbia Israël in facie ejus; nec reversi sunt ad Dominum Deum suum, et non quæsierunt eum in omnibus his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Et factus est Ephraim quasi columba seducta non habens cor. \'gyptum invocabant; ad Assyrios abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Et cum profecti fuerint, expandam super eos rete meum: quasi volucrem cæli detraham eos; cædam eos secundum auditionem cœtus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Væ eis, quoniam recesserunt a me! vastabuntur, quia prævaricati sunt in me, et ego redemi eos, et ipsi locuti sunt contra me mendacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Et non clamaverunt ad me in corde suo, sed ululabant in cubilibus suis: super triticum et vinum ruminabant; recesserunt a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Et ego erudivi eos, et confortavi brachia eorum, et in me cogitaverunt malitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Reversi sunt ut essent absque jugo; facti sunt quasi arcus dolosus: cadent in gladio principes eorum, a furore linguæ suæ. Ista subsannatio eorum in terra \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 1, 'In gutture tuo sit tuba quasi aquila super domum Domini, pro eo quod transgressi sunt fœdus meum, et legem meam prævaricati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 2, 'Me invocabunt: Deus meus, cognovimus te Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 3, 'Projecit Israël bonum: inimicus persequetur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 4, 'Ipsi regnaverunt, et non ex me; principes exstiterunt, et non cognovi: argentum suum et aurum suum fecerunt sibi idola, ut interirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 5, 'Projectus est vitulus tuus, Samaria; iratus est furor meus in eos. Usquequo non poterunt emundari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 6, 'Quia ex Israël et ipse est: artifex fecit illum, et non est deus; quoniam in aranearum telas erit vitulus Samariæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 7, 'Quia ventum seminabunt, et turbinem metent: culmus stans non est in eo; germen non faciet farinam: quod etsi fecerit, alieni comedent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 8, 'Devoratus est Israël; nunc factus est in nationibus quasi vas immundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 9, 'Quia ipsi ascenderunt ad Assur, onager solitarius sibi; Ephraim munera dederunt amatoribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 10, 'Sed et cum mercede conduxerint nationes, nunc congregabo eos, et quiescent paulisper ab onere regis et principum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 11, 'Quia multiplicavit Ephraim altaria ad peccandum; factæ sunt ei aræ in delictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 12, 'Scribam ei multiplices leges meas, quæ velut alienæ computatæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 13, 'Hostias offerent, immolabunt carnes et comedent, et Dominus non suscipiet eas: nunc recordabitur iniquitatis eorum, et visitabit peccata eorum: ipsi in \'gyptum convertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 8, 14, 'Et oblitus est Israël factoris sui, et ædificavit delubra; et Judas multiplicavit urbes munitas; et mittam ignem in civitates ejus, et devorabit ædes illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 1, 'Noli lætari, Israël; noli exsultare sicut populi: quia fornicatus es a Deo tuo; dilexisti mercedem super omnes areas tritici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 2, 'Area et torcular non pascet eos, et vinum mentietur eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 3, 'non habitabunt in terra Domini. Reversus est Ephraim in \'gyptum, et in Assyriis pollutum comedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 4, 'Non libabunt Domino vinum, et non placebunt ei. Sacrificia eorum quasi panis lugentium; omnes qui comedent eum, contaminabuntur: quia panis eorum animæ ipsorum: non intrabit in domum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 5, 'Quid facietis in die solemni, in die festivitatis Domini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 6, 'Ecce enim profecti sunt a vastitate: \'gyptus congregabit eos; Memphis sepeliet eos: desiderabile argentum eorum urtica hæreditabit, lappa in tabernaculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 7, 'Venerunt dies visitationis, venerunt dies retributionis. Scitote, Israël, stultum prophetam, insanum virum spiritualem, propter multitudinem iniquitatis tuæ, et multitudinem amentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 8, 'Speculator Ephraim cum Deo meo, propheta laqueus ruinæ factus est super omnes vias ejus; insania in domo Dei ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 9, 'Profunde peccaverunt, sicut in diebus Gabaa. Recordabitur iniquitatis eorum, et visitabit peccata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 10, 'Quasi uvas in deserto inveni Israël, quasi prima poma ficulneæ in cacumine ejus vidi patres eorum: ipsi autem intraverunt ad Beelphegor, et abalienati sunt in confusionem, et facti sunt abominabiles sicut ea quæ dilexerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 11, 'Ephraim quasi avis avolavit; gloria eorum a partu, et ab utero, et a conceptu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 12, 'Quod etsi enutrierint filios suos, absque liberis eos faciam in hominibus; sed et væ eis cum recessero ab eis!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 13, 'Ephraim, ut vidi, Tyrus erat fundata in pulchritudine; et Ephraim educet ad interfectorem filios suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 14, 'Da eis, Domine. Quid dabis eis? da eis vulvam sine liberis, et ubera arentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 15, 'Omnes nequitiæ eorum in Galgal, quia ibi exosos habui eos. Propter malitiam adinventionum eorum, de domo mea ejiciam eos; non addam ut diligam eos: omnes principes eorum recedentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 16, 'Percussus est Ephraim; radix eorum exsiccata est: fructum nequaquam facient, quod etsi genuerint, interficiam amantissima uteri eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 9, 17, 'Abjiciet eos Deus meus, quia non audierunt eum, et erunt vagi in nationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 1, 'Vitis frondosa Israël, fructus adæquatus est ei: secundum multitudinem fructus sui multiplicavit altaria, juxta ubertatem terræ suæ exuberavit simulacris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 2, 'Divisum est cor eorum, nunc interibunt; ipse confringet simulacra eorum, depopulabitur aras eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 3, 'Quia nunc dicent: Non est rex nobis, non enim timemus Dominum; et rex quid faciet nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 4, 'Loquimini verba visionis inutilis, et ferietis fœdus; et germinabit quasi amaritudo judicium super sulcos agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 5, 'Vaccas Bethaven coluerunt habitatores Samariæ; quia luxit super eum populus ejus, et æditui ejus super eum exsultaverunt in gloria ejus, quia migravit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 6, 'Siquidem et ipse in Assur delatus est, munus regi ultori. Confusio Ephraim capiet, et confundetur Israël in voluntate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 7, 'Transire fecit Samaria regem suum quasi spumam super faciem aquæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 8, 'Et disperdentur excelsa idoli, peccatum Israël; lappa et tribulus ascendet super aras eorum: et dicent montibus: Operite nos, et collibus: Cadite super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 9, 'Ex diebus Gabaa peccavit Israël; ibi steterunt. Non comprehendet eos in Gabaa prælium super filios iniquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 10, 'Juxta desiderium meum corripiam eos: congregabuntur super eos populi, cum corripientur propter duas iniquitates suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 11, 'Ephraim vitula docta diligere trituram, et ego transivi super pulchritudinem colli ejus: ascendam super Ephraim, arabit Judas; confringet sibi sulcos Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 12, 'Seminate vobis in justitia, et metite in ore misericordiæ. Innovate vobis novale; tempus autem requirendi Dominum, cum venerit qui docebit vos justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 13, 'Arastis impietatem, iniquitatem messuistis: comedistis frugem mendacii, quia confisus es in viis tuis, in multitudine fortium tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 14, 'Consurget tumultus in populo tuo; et omnes munitiones tuæ vastabuntur, sicut vastatus est Salmana a domo ejus qui judicavit Baal in die prælii, matre super filios allisa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 10, 15, 'Sic fecit vobis Bethel, a facie malitiæ nequitiarum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 1, 'Sicut mane transiit, pertransiit rex Israël. Quia puer Israël, et dilexi eum; et ex \'gypto vocavi filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 2, 'Vocaverunt eos, sic abierunt a facie eorum; Baalim immolabant, et simulacris sacrificabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 3, 'Et ego quasi nutritius Ephraim: portabam eos in brachiis meis, et nescierunt quod curarem eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 4, 'In funiculis Adam traham eos, in vinculis caritatis; et ero eis quasi exaltans jugum super maxillas eorum, et declinavi ad eum ut vesceretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 5, 'Non revertetur in terram \'gypti, et Assur ipse rex ejus, quoniam noluerunt converti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 6, 'Cœpit gladius in civitatibus ejus, et consumet electos ejus, et comedet capita eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 7, 'Et populus meus pendebit ad reditum meum; jugum autem imponetur eis simul, quod non auferetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 8, 'Quomodo dabo te, Ephraim? protegam te, Israël? Quomodo dabo te sicut Adama, ponam te ut Seboim? Conversum est in me cor meum, pariter conturbata est pœnitudo mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 9, 'Non faciam furorem iræ meæ; non convertar ut disperdam Ephraim, quoniam Deus ego, et non homo; in medio tui sanctus, et non ingrediar civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 10, 'Post Dominum ambulabunt; quasi leo rugiet, quia ipse rugiet, et formidabunt filii maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 11, 'Et avolabunt quasi avis ex \'gypto, et quasi columba de terra Assyriorum: et collocabo eos in domibus suis, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 11, 12, 'Circumdedit me in negatione Ephraim, et in dolo domus Israël; Judas autem testis descendit cum Deo, et cum sanctis fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 1, 'Ephraim pascit ventum, et sequitur æstum; tota die mendacium et vastitatem multiplicat: et fœdus cum Assyriis iniit, et oleum in \'gyptum ferebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 2, 'Judicium ergo Domini cum Juda, et visitatio super Jacob: juxta vias ejus, et juxta adinventiones ejus reddet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 3, 'In utero supplantavit fratrem suum, et in fortitudine sua directus est cum angelo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 4, 'Et invaluit ad angelum, et confortatus est; flevit, et rogavit eum. In Bethel invenit eum, et ibi locutus est nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 5, 'Et Dominus Deus exercituum, Dominus memoriale ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 6, 'Et tu ad Deum tuum converteris; misericordiam et judicium custodi, et spera in Deo tuo semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 7, 'Chanaan, in manu ejus statera dolosa, calumniam dilexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 8, 'Et dixit Ephraim: Verumtamen dives effectus sum; inveni idolum mihi: omnes labores mei non invenient mihi iniquitatem quam peccavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 9, 'Et ego Dominus Deus tuus ex terra \'gypti: adhuc sedere te faciam in tabernaculis, sicut in diebus festivitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 10, 'Et locutus sum super prophetas, et ego visionem multiplicavi, et in manu prophetarum assimilatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 11, 'Si Galaad idolum, ergo frustra erant in Galgal bobus immolantes; nam et altaria eorum quasi acervi super sulcos agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 12, 'Fugit Jacob in regionem Syriæ, et servivit Israël in uxorem, et in uxorem servavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 13, 'In propheta autem eduxit Dominus Israël de \'gypto, et in propheta servatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 12, 14, 'Ad iracundiam me provocavit Ephraim in amaritudinibus suis: et sanguis ejus super eum veniet, et opprobrium ejus restituet ei Dominus suus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 1, 'Loquente Ephraim, horror invasit Israël; et deliquit in Baal, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 2, 'Et nunc addiderunt ad peccandum; feceruntque sibi conflatile de argento suo quasi similitudinem idolorum: factura artificum totum est: his ipsi dicunt: Immolate homines, vitulos adorantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 3, 'Idcirco erunt quasi nubes matutina, et sicut ros matutinus præteriens; sicut pulvis turbine raptus ex area, et sicut fumus de fumario.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 4, 'Ego autem Dominus Deus tuus, ex terra \'gypti; et Deum absque me nescies, et salvator non est præter me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 5, 'Ego cognovi te in deserto, in terra solitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 6, 'Juxta pascua sua adimpleti sunt et saturati sunt; et levaverunt cor suum, et obliti sunt mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 7, 'Et ego ero eis quasi leæna, sicut pardus in via Assyriorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 8, 'Occurram eis quasi ursa raptis catulis, et dirumpam interiora jecoris eorum, et consumam eos ibi quasi leo: bestia agri scindet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 9, 'Perditio tua, Israël: tantummodo in me auxilium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 10, 'Ubi est rex tuus? maxime nunc salvet te in omnibus urbibus tuis; et judices tui, de quibus dixisti: Da mihi regem et principes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 11, 'Dabo tibi regem in furore meo, et auferam in indignatione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 12, 'Colligata est iniquitas Ephraim; absconditum peccatum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 13, 'Dolores parturientis venient ei: ipse filius non sapiens: nunc enim non stabit in contritione filiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 14, 'De manu mortis liberabo eos; de morte redimam eos. Ero mors tua, o mors! morsus tuus ero, inferne! consolatio abscondita est ab oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 13, 15, 'Quia ipse inter fratres dividet: adducet urentem ventum Dominus de deserto ascendentem, et siccabit venas ejus, et desolabit fontem ejus: et ipse diripiet thesaurum omnis vasis desiderabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 1, 'Pereat Samaria, quoniam ad amaritudinem concitavit Deum suum! in gladio pereant, parvuli eorum elidantur, et fœtæ ejus discindantur!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 2, 'Convertere, Israël, ad Dominum Deum tuum, quoniam corruisti in iniquitate tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 3, 'Tollite vobiscum verba, et convertimini ad Dominum; et dicite ei: Omnem aufer iniquitatem, accipe bonum, et reddemus vitulos labiorum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 4, 'Assur non salvabit nos: super equum non ascendemus, nec dicemus ultra, Dii nostri opera manuum nostrarum: quia ejus, qui in te est, misereberis pupilli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 5, 'Sanabo contritiones eorum; diligam eos spontanee: quia aversus est furor meus ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 6, 'Ero quasi ros; Israël germinabit sicut lilium, et erumpet radix ejus ut Libani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 7, 'Ibunt rami ejus, et erit quasi oliva gloria ejus, et odor ejus ut Libani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 8, 'Convertentur sedentes in umbra ejus; vivent tritico, et germinabunt quasi vinea; memoriale ejus sicut vinum Libani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 9, 'Ephraim, quid mihi ultra idola? Ego exaudiam, et dirigam eum ego ut abietem virentem; ex me fructus tuus inventus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 14, 10, 'Quis sapiens, et intelliget ista? intelligens, et sciet hæc? quia rectæ viæ Domini, et justi ambulabunt in eis; prævaricatores vero corruent in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Verbum Domini, quod factum est ad Joël, filium Phatuel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Audite hoc, senes, et auribus percipite, omnes habitatores terræ: si factum est istud in diebus vestris, aut in diebus patrum vestrorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Super hoc filiis vestris narrate, et filii vestri filiis suis, et filii eorum generationi alteræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Residuum erucæ comedit locusta, et residuum locustæ comedit bruchus, et residuum bruchi comedit rubigo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Expergiscimini, ebrii, et flete et ululate, omnes qui bibitis vinum in dulcedine, quoniam periit ab ore vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Gens enim ascendit super terram meam, fortis et innumerabilis: dentes ejus ut dentes leonis, et molares ejus ut catuli leonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Posuit vineam meam in desertum, et ficum meam decorticavit; nudans spoliavit eam, et projecit: albi facti sunt rami ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Plange quasi virgo accincta sacco super virum pubertatis suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Periit sacrificium et libatio de domo Domini; luxerunt sacerdotes, ministri Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Depopulata est regio, luxit humus, quoniam devastatum est triticum, confusum est vinum, elanguit oleum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Confusi sunt agricolæ, ululaverunt vinitores super frumento et hordeo, quia periit messis agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Vinea confusa est, et ficus elanguit; malogranatum, et palma, et malum, et omnia ligna agri aruerunt, quia confusum est gaudium a filiis hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Accingite vos, et plangite, sacerdotes: ululate, ministri altaris; ingredimini, cubate in sacco, ministri Dei mei, quoniam interiit de domo Dei vestri sacrificium et libatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Sanctificate jejunium, vocate cœtum, congregate senes, omnes habitatores terræ in domum Dei vestri, et clamate ad Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'A, a, a, diei! quia prope est dies Domini, et quasi vastitas a potente veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 16, 'Numquid non coram oculis vestris alimenta perierunt de domo Dei nostri, lætitia et exsultatio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 17, 'Computruerunt jumenta in stercore suo, demolita sunt horrea, dissipatæ sunt apothecæ, quoniam confusum est triticum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 18, 'Quid ingemuit animal, mugierunt greges armenti? quia non est pascua eis; sed et greges pecorum disperierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 19, 'Ad te, Domine, clamabo, quia ignis comedit speciosa deserti, et flamma succendit omnia ligna regionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 20, 'Sed et bestiæ agri, quasi area sitiens imbrem, suspexerunt ad te, quoniam exsiccati sunt fontes aquarum, et ignis devoravit speciosa deserti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Canite tuba in Sion, ululate in monte sancto meo, conturbentur omnes habitatores terræ: quia venit dies Domini, quia prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Dies tenebrarum et caliginis, dies nubis et turbinis; quasi mane expansum super montes populus multus et fortis: similis ei non fuit a principio, et post eum non erit usque in annos generationis et generationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Ante faciem ejus ignis vorans, et post eum exurens flamma. Quasi hortus voluptatis terra coram eo, et post eum solitudo deserti, neque est qui effugiat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Quasi aspectus equorum, aspectus eorum; et quasi equites, sic current.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Sicut sonitus quadrigarum super capita montium exilient, sicut sonitus flammæ ignis devorantis stipulam, velut populus fortis præparatus ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'A facie ejus cruciabuntur populi; omnes vultus redigentur in ollam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Sicut fortes current; quasi viri bellatores ascendent murum: viri in viis suis gradientur, et non declinabunt a semitis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Unusquisque fratrem suum non coarctabit, singuli in calle suo ambulabunt; sed et per fenestras cadent, et non demolientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Urbem ingredientur, in muro current, domos conscendent, per fenestras intrabunt quasi fur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'A facie ejus contremuit terra, moti sunt cæli, sol et luna obtenebrati sunt, et stellæ retraxerunt splendorem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Et Dominus dedit vocem suam ante faciem exercitus sui, quia multa sunt nimis castra ejus, quia fortia et facientia verbum ejus: magnus enim dies Domini, et terribilis valde, et quis sustinebit eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Nunc ergo, dicit Dominus, convertimini ad me in toto corde vestro, in jejunio, et in fletu, et in planctu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Et scindite corda vestra, et non vestimenta vestra; et convertimini ad Dominum Deum vestrum, quia benignus et misericors est, patiens et multæ misericordiæ, et præstabilis super malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'Quis scit si convertatur, et ignoscat, et relinquat post se benedictionem, sacrificium et libamen Domino Deo vestro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 15, 'Canite tuba in Sion, sanctificate jejunium, vocate cœtum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 16, 'congregate populum, sanctificate ecclesiam, coadunate senes, congregate parvulos, et sugentes ubera; egrediatur sponsus de cubili suo, et sponsa de thalamo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 17, 'Inter vestibulum et altare plorabunt sacerdotes, ministri Domini, et dicent: Parce, Domine, parce populo tuo; et ne des hæreditatem tuam in opprobrium, ut dominentur eis nationes. Quare dicunt in populis: Ubi est Deus eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 18, 'Zelatus est Dominus terram suam, et pepercit populo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 19, 'Et respondit Dominus, et dixit populo suo: Ecce ego mittam vobis frumentum, et vinum, et oleum, et replebimini eis; et non dabo vos ultra opprobrium in gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 20, 'Et eum qui ab aquilone est procul faciam a vobis, et expellam eum in terram inviam et desertam: faciem ejus contra mare orientale, et extremum ejus ad mare novissimum: et ascendet fœtor ejus, et ascendet putredo ejus, quia superbe egit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 21, 'Noli timere, terra: exsulta, et lætare, quoniam magnificavit Dominus ut faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 22, 'Nolite timere, animalia regionis, quia germinaverunt speciosa deserti; quia lignum attulit fructum suum, ficus et vinea dederunt virtutem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 23, 'Et, filii Sion, exsultate, et lætamini in Domino Deo vestro, quia dedit vobis doctorem justitiæ, et descendere faciet ad vos imbrem matutinum et serotinum, sicut in principio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 24, 'Et implebuntur areæ frumento, et redundabunt torcularia vino et oleo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 25, 'Et reddam vobis annos, quos comedit locusta, bruchus, et rubigo, et eruca: fortitudo mea magna quam misi in vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 26, 'Et comedetis vescentes, et saturabimini; et laudabitis nomen Domini Dei vestri, qui fecit mirabilia vobiscum; et non confundetur populus meus in sempiternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 27, 'Et scietis quia in medio Israël ego sum, et ego Dominus Deus vester, et non est amplius; et non confundetur populus meus in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 28, 'Et erit post hæc: effundam spiritum meum super omnem carnem, et prophetabunt filii vestri et filiæ vestræ: senes vestri somnia somniabunt, et juvenes vestri visiones videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 29, 'Sed et super servos meos et ancillas in diebus illis effundam spiritum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 30, 'Et dabo prodigia in cælo et in terra, sanguinem, et ignem, et vaporem fumi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 31, 'Sol convertetur in tenebras, et luna in sanguinem, antequam veniat dies Domini magnus et horribilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 32, 'Et erit: omnis qui invocaverit nomen Domini, salvus erit: quia in monte Sion et in Jerusalem erit salvatio, sicut dixit Dominus, et in residuis quos Dominus vocaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Quia ecce in diebus illis, et in tempore illo, cum convertero captivitatem Juda et Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'congregabo omnes gentes, et deducam eas in vallem Josaphat; et disceptabo cum eis ibi super populo meo, et hæreditate mea Israël, quos disperserunt in nationibus, et terram meam diviserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Et super populum meum miserunt sortem; et posuerunt puerum in prostibulo, et puellam vendiderunt pro vino ut biberent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Verum quid mihi et vobis, Tyrus et Sidon, et omnis terminus Palæstinorum? numquid ultionem vos reddetis mihi? et si ulciscimini vos contra me, cito velociter reddam vicissitudinem vobis super caput vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Argentum enim meum et aurum tulistis, et desiderabilia mea et pulcherrima intulistis in delubra vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Et filios Juda et filios Jerusalem vendidistis filiis Græcorum, ut longe faceretis eos de finibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ecce ego suscitabo eos de loco in quo vendidistis eos, et convertam retributionem vestram in caput vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Et vendam filios vestros et filias vestras in manibus filiorum Juda, et venundabunt eos Sabæis, genti longinquæ, quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Clamate hoc in gentibus, sanctificate bellum, suscitate robustos: accedant, ascendant omnes viri bellatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Concidite aratra vestra in gladios, et ligones vestros in lanceas. Infirmus dicat: Quia fortis ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Erumpite, et venite, omnes gentes de circuitu, et congregamini; ibi occumbere faciet Dominus robustos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Consurgant, et ascendant gentes in vallem Josaphat, quia ibi sedebo ut judicem omnes gentes in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Mittite falces, quoniam maturavit messis; venite, et descendite, quia plenum est torcular, exuberant torcularia: quia multiplicata est malitia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Populi, populi, in valle concisionis, quia juxta est dies Domini in valle concisionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Sol et luna obtenebrati sunt, et stellæ retraxerunt splendorem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Et Dominus de Sion rugiet, et de Jerusalem dabit vocem suam, et movebuntur cæli et terra; et Dominus spes populi sui, et fortitudo filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Et scietis quia ego Dominus Deus vester, habitans in Sion monte sancto meo; et erit Jerusalem sancta, et alieni non transibunt per eam amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Et erit in die illa: stillabunt montes dulcedinem, et colles fluent lacte, et per omnes rivos Juda ibunt aquæ; et fons de domo Domini egredietur, et irrigabit torrentem spinarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, '\'gyptus in desolationem erit, et Idumæa in desertum perditionis, pro eo quod inique egerint in filios Juda, et effuderint sanguinem innocentem in terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 20, 'Et Judæa in æternum habitabitur, et Jerusalem in generationem et generationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 21, 'Et mundabo sanguinem eorum, quem non mundaveram; et Dominus commorabitur in Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Verba Amos, qui fuit in pastoribus de Thecue, quæ vidit super Israël in diebus Oziæ, regis Juda, et in diebus Jeroboam, filii Joas, regis Israël, ante duos annos terræmotus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Et dixit: Dominus de Sion rugiet, et de Jerusalem dabit vocem suam; et luxerunt speciosa pastorum, et exsiccatus est vertex Carmeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Hæc dicit Dominus: Super tribus sceleribus Damasci, et super quatuor non convertam eum, eo quod trituraverint in plaustris ferreis Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Et mittam ignem in domum Azaël, et devorabit domos Benadad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Et conteram vectem Damasci: et disperdam habitatorem de campo idoli, et tenentem sceptrum de domo voluptatis: et transferetur populus Syriæ Cyrenen, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Hæc dicit Dominus: Super tribus sceleribus Gazæ, et super quatuor non convertam eum, eo quod transtulerint captivitatem perfectam, ut concluderent eam in Idumæa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Et mittam ignem in murum Gazæ, et devorabit ædes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Et disperdam habitatorem de Azoto, et tenentem sceptrum de Ascalone: et convertam manum meam super Accaron, et peribunt reliqui Philisthinorum, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Hæc dicit Dominus: Super tribus sceleribus Tyri, et super quatuor non convertam eum, eo quod concluserint captivitatem perfectam in Idumæa, et non sint recordati fœderis fratrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Et mittam ignem in murum Tyri, et devorabit ædes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Hæc dicit Dominus: Super tribus sceleribus Edom, et super quatuor non convertam eum, eo quod persecutus sit in gladio fratrem suum, et violaverit misericordiam ejus, et tenuerit ultra furorem suum, et indignationem suam servaverit usque in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Mittam ignem in Theman, et devorabit ædes Bosræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Hæc dicit Dominus: Super tribus sceleribus filiorum Ammon, et super quatuor non convertam eum, eo quod dissecuerit prægnantes Galaad ad dilatandum terminum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Et succendam ignem in muro Rabba, et devorabit ædes ejus in ululatu in die belli, et in turbine in die commotionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Et ibit Melchom in captivitatem, ipse et principes ejus simul, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Hæc dicit Dominus: Super tribus sceleribus Moab, et super quatuor non convertam eum, eo quod incenderit ossa regis Idumææ usque ad cinerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Et mittam ignem in Moab, et devorabit ædes Carioth: et morietur in sonitu Moab, in clangore tubæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Et disperdam judicem de medio ejus, et omnes principes ejus interficiam cum eo, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Hæc dicit Dominus: Super tribus sceleribus Juda, et super quatuor non convertam eum, eo quod abjecerit legem Domini et mandata ejus non custodierit: deceperant enim eos idola sua, post quæ abierant patres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Et mittam ignem in Juda, et devorabit ædes Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Hæc dicit Dominus: Super tribus sceleribus Israël, et super quatuor non convertam eum, pro eo quod vendiderit pro argento justum, et pauperem pro calceamentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Qui conterunt super pulverem terræ capita pauperum, et viam humilium declinant: et filius ac pater ejus ierunt ad puellam, ut violarent nomen sanctum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Et super vestimentis pignoratis accubuerunt juxta omne altare, et vinum damnatorum bibebant in domo Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Ego autem exterminavi Amorrhæum a facie eorum, cujus altitudo, cedrorum altitudo ejus, et fortis ipse quasi quercus; et contrivi fructum ejus desuper, et radices ejus subter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Ego sum qui ascendere vos feci de terra \'gypti, et duxi vos in deserto quadraginta annis, ut possideretis terram Amorrhæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Et suscitavi de filiis vestris in prophetas, et de juvenibus vestris nazaræos. Numquid non ita est, filii Israël? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Et propinabitis nazaræis vinum, et prophetis mandabitis, dicentes: Ne prophetetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Ecce ego stridebo subter vos, sicut stridet plaustrum onustum fœno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Et peribit fuga a veloce, et fortis non obtinebit virtutem suam, et robustus non salvabit animam suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'et tenens arcum non stabit, et velox pedibus suis non salvabitur, et ascensor equi non salvabit animam suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'et robustus corde inter fortes nudus fugiet in illa die, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Audite verbum quod locutus est Dominus super vos, filii Israël, super omnem cognationem quam eduxi de terra \'gypti, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Tantummodo vos cognovi ex omnibus cognationibus terræ; idcirco visitabo super vos omnes iniquitates vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Numquid ambulabunt duo pariter, nisi convenerit eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'numquid rugiet leo in saltu, nisi habuerit prædam? numquid dabit catulus leonis vocem de cubili suo, nisi aliquid apprehenderit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'numquid cadet avis in laqueum terræ absque aucupe? numquid auferetur laqueus de terra antequam quid ceperit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'si clanget tuba in civitate, et populus non expavescet? si erit malum in civitate, quod Dominus non fecerit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Quia non facit Dominus Deus verbum, nisi revelaverit secretum suum ad servos suos prophetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Leo rugiet, quis non timebit? Dominus Deus locutus est, quis non prophetabit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Auditum facite in ædibus Azoti, et in ædibus terræ \'gypti, et dicite: Congregamini super montes Samariæ, et videte insanias multas in medio ejus, et calumniam patientes in penetralibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Et nescierunt facere rectum, dicit Dominus, thesaurizantes iniquitatem et rapinas in ædibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Propterea hæc dicit Dominus Deus: Tribulabitur et circuietur terra: et detrahetur ex te fortitudo tua, et diripientur ædes tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Hæc dicit Dominus: Quomodo si eruat pastor de ore leonis duo crura, aut extremum auriculæ, sic eruentur filii Israël, qui habitant in Samaria in plaga lectuli, et in Damasci grabato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Audite, et contestamini in domo Jacob, dicit Dominus Deus exercituum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'quia in die cum visitare cœpero prævaricationes Israël, super eum visitabo, et super altaria Bethel; et amputabuntur cornua altaris, et cadent in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Et percutiam domum hiemalem cum domo æstiva, et peribunt domus eburneæ, et dissipabuntur ædes multæ, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 1, 'Audite verbum hoc, vaccæ pingues, quæ estis in monte Samariæ, quæ calumniam facitis egenis et confringitis pauperes; quæ dicitis dominis vestris: Afferte, et bibemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 2, 'Juravit Dominus Deus in sancto suo, quia ecce dies venient super vos, et levabunt vos in contis, et reliquias vestras in ollis ferventibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 3, 'Et per aperturas exibitis altera contra alteram, et projiciemini in Armon, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 4, 'Venite ad Bethel, et impie agite; ad Galgalam, et multiplicate prævaricationem: et afferte mane victimas vestras, tribus diebus decimas vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 5, 'Et sacrificate de fermentato laudem, et vocate voluntarias oblationes, et annuntiate; sic enim voluistis, filii Israël, dicit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 6, 'Unde et ego dedi vobis stuporem dentium in cunctis urbibus vestris, et indigentiam panum in omnibus locis vestris; et non estis reversi ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 7, 'Ego quoque prohibui a vobis imbrem, cum adhuc tres menses superessent usque ad messem: et plui super unam civitatem, et super alteram civitatem non plui; pars una compluta est, et pars super quam non plui, aruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 8, 'Et venerunt duæ et tres civitates ad unam civitatem ut biberent aquam, et non sunt satiatæ; et non redistis ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 9, 'Percussi vos in vento urente, et in aurugine: multitudinem hortorum vestrorum et vinearum vestrarum, oliveta vestra et ficeta vestra comedit eruca: et non redistis ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 10, 'Misi in vos mortem in via \'gypti; percussi in gladio juvenes vestros, usque ad captivitatem equorum vestrorum, et ascendere feci putredinem castrorum vestrorum in nares vestras: et non redistis ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 11, 'Subverti vos sicut subvertit Deus Sodomam et Gomorrham, et facti estis quasi torris raptus ab incendio: et non redistis ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 12, 'Quapropter hæc faciam tibi, Israël: postquam autem hæc fecero tibi, præparare in occursum Dei tui, Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 4, 13, 'Quia ecce formans montes, et creans ventum, et annuntians homini eloquium suum, faciens matutinam nebulam, et gradiens super excelsa terræ: Dominus Deus exercituum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 1, 'Audite verbum istud, quod ego levo super vos planctum: domus Israël cecidit, et non adjiciet ut resurgat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 2, 'Virgo Israël projecta est in terram suam, non est qui suscitet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 3, 'Quia hæc dicit Dominus Deus: Urbs de qua egrediebantur mille, relinquentur in ea centum; et de qua egrediebantur centum, relinquentur in ea decem in domo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 4, 'Quia hæc dicit Dominus domui Israël: Quærite me, et vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 5, 'Et nolite quærere Bethel, et in Galgalam nolite intrare, et in Bersabee non transibitis, quia Galgala captiva ducetur, et Bethel erit inutilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 6, 'Quærite Dominum, et vivite (ne forte comburatur ut ignis domus Joseph, et devorabit, et non erit qui extinguat Bethel:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 7, 'qui convertitis in absinthium judicium, et justitiam in terra relinquitis):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 8, 'facientem Arcturum et Orionem, et convertentem in mane tenebras, et diem in noctem mutantem; qui vocat aquas maris, et effundit eas super faciem terræ; Dominus nomen est ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 9, 'qui subridet vastitatem super robustum, et depopulationem super potentem affert.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 10, 'Odio habuerunt corripientem in porta, et loquentem perfecte abominati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 11, 'Idcirco, pro eo quod diripiebatis pauperem, et prædam electam tollebatis ab eo, domos quadro lapide ædificabitis, et non habitabitis in eis; vineas plantabis amantissimas, et non bibetis vinum earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 12, 'Quia cognovi multa scelera vestra, et fortia peccata vestra: hostes justi, accipientes munus, et pauperes deprimentes in porta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 13, 'Ideo prudens in tempore illo tacebit, quia tempus malum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 14, 'Quærite bonum, et non malum, ut vivatis; et erit Dominus Deus exercituum vobiscum, sicut dixistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 15, 'Odite malum et diligite bonum, et constituite in porta judicium: si forte misereatur Dominus Deus exercituum reliquiis Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 16, 'Propterea hæc dicit Dominus Deus exercituum, dominator: In omnibus plateis planctus; et in cunctis quæ foris sunt, dicetur: Væ, væ! et vocabunt agricolam ad luctum, et ad planctum eos qui sciunt plangere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 17, 'Et in omnibus vineis erit planctus, quia pertransibo in medio tui, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 18, 'Væ desiderantibus diem Domini! ad quid eam vobis? Dies Domini ista, tenebræ, et non lux.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 19, 'Quomodo si fugiat vir a facie leonis, et occurrat ei ursus; et ingrediatur domum, et innitatur manu sua super parietem, et mordeat eum coluber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 20, 'Numquid non tenebræ dies Domini, et non lux; et caligo, et non splendor in ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 21, 'Odi, et projeci festivitates vestras, et non capiam odorem cœtuum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 22, 'Quod si obtuleritis mihi holocautomata, et munera vestra, non suscipiam; et vota pinguium vestrorum non respiciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 23, 'Aufer a me tumultum carminum tuorum; et cantica lyræ tuæ non audiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 24, 'Et revelabitur quasi aqua judicium, et justitia quasi torrens fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 25, 'Numquid hostias et sacrificium obtulistis mihi in deserto quadraginta annis, domus Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 26, 'et portastis tabernaculum Moloch vestro, et imaginem idolorum vestrorum, sidus dei vestri, quæ fecistis vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 5, 27, 'Et migrare vos faciam trans Damascum, dicit Dominus: Deus exercituum nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 1, 'Væ qui opulenti estis in Sion, et confiditis in monte Samariæ: optimates capita populorum, ingredientes pompatice domum Israël!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 2, 'Transite in Chalane, et videte, et ite inde in Emath magnam, et descendite in Geth Palæstinorum, et ad optima quæque regna horum: si latior terminus eorum termino vestro est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 3, 'Qui separati estis in diem malum, et appropinquatis solio iniquitatis;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 4, 'qui dormitis in lectis eburneis, et lascivitis in stratis vestris; qui comeditis agnum de grege, et vitulos de medio armenti;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 5, 'qui canitis ad vocem psalterii, sicut David putaverunt se habere vasa cantici,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 6, 'bibentes vinum in phialis, et optimo unguento delibuti, et nihil patiebantur super contritione Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 7, 'Quapropter nunc migrabunt in capite transmigrantium, et auferetur factio lascivientium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 8, 'Juravit Dominus Deus in anima sua, dicit Dominus Deus exercituum: Detestor ego superbiam Jacob, et domos ejus odi, et tradam civitatem cum habitatoribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 9, 'Quod si reliqui fuerint decem viri in domo una, et ipsi morientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 10, 'Et tollet eum propinquus suus, et comburet eum, ut efferat ossa de domo; et dicet ei, qui in penetralibus domus est: Numquid adhuc est penes te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 11, 'Et respondebit: Finis est. Et dicet ei: Tace, et non recorderis nominis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 12, 'Quia ecce Dominus mandabit, et percutiet domum majorem ruinis, et domum minorem scissionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 13, 'Numquid currere queunt in petris equi, aut arari potest in bubalis? quoniam convertistis in amaritudinem judicium, et fructum justitiæ in absinthium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 14, 'Qui lætamini in nihilo; qui dicitis: Numquid non in fortitudine nostra assumpsimus nobis cornua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 6, 15, 'Ecce enim suscitabo super vos, domus Israël, dicit Dominus Deus exercituum, gentem, et conteret vos ab introitu Emath usque ad torrentem deserti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 1, 'Hæc ostendit mihi Dominus Deus: et ecce fictor locustæ in principio germinantium serotini imbris, et ecce serotinus post tonsionem regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 2, 'Et factum est, cum consummasset comedere herbam terræ, dixi: Domine Deus, propitius esto, obsecro; quis suscitabit Jacob, quia parvulus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 3, 'Misertus est Dominus super hoc: Non erit, dixit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 4, 'Hæc ostendit mihi Dominus Deus: et ecce vocabat judicium ad ignem Dominus Deus; et devoravit abyssum multam, et comedit simul partem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 5, 'Et dixi: Domine Deus, quiesce, obsecro; quis suscitabit Jacob, quia parvulus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 6, 'Misertus est Dominus super hoc: Sed et istud non erit, dixit Dominus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 7, 'Hæc ostendit mihi Dominus: et ecce Dominus stans super murum litum, et in manu ejus trulla cæmentarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 8, 'Et dixit Dominus ad me: Quid tu vides, Amos? Et dixi: Trullam cæmentarii. Et dixit Dominus: Ecce ego ponam trullam in medio populi mei Israël; non adjiciam ultra superinducere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 9, 'Et demolientur excelsa idoli, et sanctificationes Israël desolabuntur, et consurgam super domum Jeroboam in gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 10, 'Et misit Amasias, sacerdos Bethel, ad Jeroboam, regem Israël, dicens: Rebellavit contra te Amos in medio domus Israël; non poterit terra sustinere universos sermones ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 11, 'Hæc enim dicit Amos: In gladio morietur Jeroboam, et Israël captivus migrabit de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 12, 'Et dixit Amasias ad Amos: Qui vides, gradere: fuge in terram Juda, et comede ibi panem, et prophetabis ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 13, 'Et in Bethel non adjicies ultra ut prophetes, quia sanctificatio regis est, et domus regni est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 14, 'Responditque Amos, et dixit ad Amasiam: Non sum propheta, et non sum filius prophetæ: sed armentarius ego sum vellicans sycomoros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 15, 'Et tulit me Dominus cum sequerer gregem, et dixit Dominus ad me: Vade, propheta ad populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 16, 'Et nunc audi verbum Domini: Tu dicis: Non prophetabis super Israël, et non stillabis super domum idoli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 7, 17, 'Propter hoc hæc dicit Dominus: Uxor tua in civitate fornicabitur, et filii tui et filiæ tuæ in gladio cadent, et humus tua funiculo metietur: et tu in terra polluta morieris, et Israël captivus migrabit de terra sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 1, 'Hæc ostendit mihi Dominus Deus: et ecce uncinus pomorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 2, 'Et dixit: Quid tu vides, Amos? Et dixi: Uncinum pomorum. Et dixit Dominus ad me: Venit finis super populum meum Israël; non adjiciam ultra ut pertranseam eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 3, 'Et stridebunt cardines templi in die illa, dicit Dominus Deus: multi morientur; in omni loco projicietur silentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 4, 'Audite hoc, qui conteritis pauperem, et deficere facitis egenos terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 5, 'dicentes: Quando transibit mensis, et venundabimus merces? et sabbatum, et aperiemus frumentum, ut imminuamus mensuram, et augeamus siclum, et supponamus stateras dolosas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 6, 'ut possideamus in argento egenos et pauperes pro calceamentis, et quisquilias frumenti vendamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 7, 'Juravit Dominus in superbiam Jacob: Si oblitus fuero usque ad finem omnia opera eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 8, 'Numquid super isto non commovebitur terra, et lugebit omnis habitator ejus, et ascendet quasi fluvius universus, et ejicicetur, et defluet, quasi rivus \'gypti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 9, 'Et erit in die illa, dicit Dominus Deus: occidet sol in meridie, et tenebrescere faciam terram in die luminis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 10, 'et convertam festivitates vestras in luctum, et omnia cantica vestra in planctum, et inducam super omne dorsum vestrum saccum, et super omne caput calvitium: et ponam eam quasi luctum unigeniti, et novissima ejus quasi diem amarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 11, 'Ecce dies veniunt, dicet Dominus, et mittam famem in terram: non famem panis, neque sitim aquæ, sed audiendi verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 12, 'Et commovebuntur a mari usque ad mare, et ab aquilone usque ad orientem: circuibunt quærentes verbum Domini, et non invenient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 13, 'In die illa deficient virgines pulchræ et adolescentes in siti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 8, 14, 'qui jurant in delicto Samariæ, et dicunt: Vivit Deus tuus, Dan, et vivit via Bersabee; et cadent, et non resurgent ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 1, 'Vidi Dominum stantem super altare, et dixit: Percute cardinem, et commoveantur superliminaria: avaritia enim in capite omnium, et novissimum eorum in gladio interficiam; non erit fuga eis. Fugient, et non salvabitur ex eis qui fugerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 2, 'Si descenderint usque ad infernum, inde manus mea educet eos; et si ascenderint usque in cælum, inde detraham eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 3, 'Et si absconditi fuerint in vertice Carmeli, inde scrutans auferam eos; et si celaverint se ab oculis meis in profundo maris, ibi mandabo serpenti, et mordebit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 4, 'Et si abierint in captivitatem coram inimicis suis, ibi mandabo gladio, et occidet eos: et ponam oculos meos super eos in malum, et non in bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 5, 'Et Dominus Deus exercituum, qui tangit terram, et tabescet, et lugebunt omnes habitantes in ea: et ascendet sicut rivus omnis, et defluet sicut fluvius \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 6, 'Qui ædificat in cælo ascensionem suam, et fasciculum suum super terram fundavit; qui vocat aquas maris, et effundit eas super faciem terræ: Dominus nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 7, 'Numquid non ut filii \'thiopum vos estis mihi, filii Israël? ait Dominus. Numquid non Israël ascendere feci de terra \'gypti, et Palæstinos de Cappadocia, et Syros de Cyrene?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 8, 'Ecce oculi Domini Dei super regnum peccans: et conteram illud a facie terræ; verumtamen conterens non conteram domum Jacob, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 9, 'Ecce enim mandabo ego, et concutiam in omnibus gentibus domum Israël, sicut concutitur triticum in cribro, et non cadet lapillus super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 10, 'In gladio morientur omnes peccatores populi mei, qui dicunt: Non appropinquabit, et non veniet super nos malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 11, 'In die illa suscitabo tabernaculum David, quod cecidit: et reædificabo aperturas murorum ejus, et ea quæ corruerant instaurabo: et reædificabo illud sicut in diebus antiquis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 12, 'ut possideant reliquias Idumææ, et omnes nationes: eo quod invocatum sit nomen meum super eos, dicit Dominus faciens hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 13, 'Ecce dies veniunt, dicit Dominus, et comprehendet arator messorem, et calcator uvæ mittentem semen: et stillabunt montes dulcedinem, et omnes colli culti erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 14, 'Et convertam captivitatem populi mei Israël; et ædificabunt civitates desertas, et inhabitabunt; et plantabunt vineas, et bibent vinum earum, et facient hortos, et comedent fructus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 9, 15, 'Et plantabo eos super humum suam, et non evellam eos ultra de terra sua, quam dedi eis, dicit Dominus Deus tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Visio Abdiæ. Hæc dicit Dominus Deus ad Edom: Auditum audivimus a Domino, et legatum ad gentes misit: surgite, et consurgamus adversus eum in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Ecce parvulum dedi te in gentibus: contemptibilis tu es valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Superbia cordis tui extulit te, habitantem in scissuris petrarum, exaltantem solium tuum; qui dicis in corde tuo: Quis detrahet me in terram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Si exaltatus fueris ut aquila, et si inter sidera posueris nidum tuum, inde detraham te, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Si fures introissent ad te, si latrones per noctem, quomodo conticuisses? nonne furati essent sufficientia sibi? Si vindemiatores introissent ad te, numquid saltem racemum reliquissent tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Quomodo scrutati sunt Esau; investigaverunt abscondita ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Usque ad terminum emiserunt te: omnes viri fœderis tui illuserunt tibi: invaluerunt adversum te viri pacis tuæ, qui comedunt tecum, ponent insidias subter te; non est prudentia in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Numquid non in die illa, dicit Dominus, perdam sapientes de Idumæa, et prudentiam de monte Esau?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Et timebunt fortes tui a meridie, ut intereat vir de monte Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Propter interfectionem, et propter iniquitatem in fratrem tuum Jacob, operiet te confusio, et peribis in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'In die cum stares adversus eum, quando capiebant alieni exercitum ejus, et extranei ingrediebantur portas ejus, et super Jerusalem mittebant sortem, tu quoque eras quasi unus ex eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Et non despicies in die fratris tui, in die peregrinationis ejus: et non lætaberis super filios Juda in die perditionis eorum: et non magnificabis os tuum in die angustiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Neque ingredieris portam populi mei in die ruinæ eorum; neque despicies et tu in malis ejus in die vastitatis illius. Et non emitteris adversus exercitum ejus in die vastitatis illius,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'neque stabis in exitibus ut interficias eos qui fugerint, et non concludes reliquos ejus in die tribulationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Quoniam juxta est dies Domini super omnes gentes: sicut fecisti, fiet tibi; retributionem tuam convertet in caput tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Quomodo enim bibistis super montem sanctum meum, bibent omnes gentes jugiter: et bibent, et absorbebunt, et erunt quasi non sint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Et in monte Sion erit salvatio, et erit sanctus; et possidebit domus Jacob eos qui se possederant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Et erit domus Jacob ignis, et domus Joseph flamma, et domus Esau stipula: et succendentur in eis, et devorabunt eos, et non erunt reliquiæ domus Esau, quia Dominus locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 19, 'Et hæreditabunt hi, qui ad austrum sunt, montem Esau, et qui in campestribus, Philisthiim: et possidebunt regionem Ephraim et regionem Samariæ, et Benjamin possidebit Galaad.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 20, 'Et transmigratio exercitus hujus filiorum Israël, omnia loca Chananæorum usque ad Sareptam: et transmigratio Jerusalem, quæ in Bosphoro est, possidebit civitates austri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 21, 'Et ascendent salvatores in montem Sion judicare montem Esau, et erit Domino regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Et factum est verbum Domini ad Jonam, filium Amathi, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Surge, et vade in Niniven, civitatem grandem, et prædica in ea, quia ascendit malitia ejus coram me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Et surrexit Jonas, ut fugeret in Tharsis a facie Domini, et descendit in Joppen: et invenit navem euntem in Tharsis, et dedit naulum ejus, et descendit in eam ut iret cum eis in Tharsis a facie Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Dominus autem misit ventum magnum in mare: et facta est tempestas magna in mari, et navis periclitabatur conteri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Et timuerunt nautæ, et clamaverunt viri ad deum suum, et miserunt vasa quæ erant in navi, in mare, ut alleviaretur ab eis; et Jonas descendit ad interiora navis, et dormiebat sopore gravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Et accessit ad eum gubernator, et dixit ei: Quid tu sopore deprimeris? surge, invoca Deum tuum, si forte recogitet Deus de nobis, et non pereamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Et dixit vir ad collegam suum: Venite et mittamus sortes, et sciamus quare hoc malum sit nobis. Et miserunt sortes, et cecidit sors super Jonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Et dixerunt ad eum: Indica nobis cujus causa malum istud sit nobis: quod est opus tuum? quæ terra tua, et quo vadis? vel ex quo populo es tu?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Et dixit ad eos: Hebræus ego sum, et Dominum Deum cæli ego timeo, qui fecit mare et aridam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Et timuerunt viri timore magno, et dixerunt ad eum: Quid hoc fecisti? cognoverunt enim viri quod a facie Domini fugeret, quia indicaverat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Et dixerunt ad eum: Quid faciemus tibi, et cessabit mare a nobis? quia mare ibat, et intumescebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Et dixit ad eos: Tollite me, et mittite in mare, et cessabit mare a vobis: scio enim ego quoniam propter me tempestas hæc grandis venit super vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Et remigabant viri ut reverterentur ad aridam, et non valebant, quia mare ibat, et intumescebat super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Et clamaverunt ad Dominum, et dixerunt: Quæsumus, Domine, ne pereamus in anima viri istius, et ne des super nos sanguinem innocentem: quia tu, Domine, sicut voluisti, fecisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Et tulerunt Jonam, et miserunt in mare: et stetit mare a fervore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 16, 'Et timuerunt viri timore magno Dominum: et immolaverunt hostias Domino, et voverunt vota.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Et præparavit Dominus piscem grandem ut deglutiret Jonam: et erat Jonas in ventre piscis tribus diebus et tribus noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Et oravit Jonas ad Dominum Deum suum de ventre piscis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'et dixit: Clamavi de tribulatione mea ad Dominum, et exaudivit me; de ventre inferi clamavi, et exaudisti vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Et projecisti me in profundum in corde maris, et flumen circumdedit me: omnes gurgites tui, et fluctus tui super me transierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Et ego dixi: Abjectus sum a conspectu oculorum tuorum; verumtamen rursus videbo templum sanctum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Circumdederunt me aquæ usque ad animam: abyssus vallavit me, pelagus operuit caput meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Ad extrema montium descendi; terræ vectes concluserunt me in æternum: et sublevabis de corruptione vitam meam, Domine Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Cum angustiaretur in me anima mea, Domini recordatus sum: ut veniat ad te oratio mea, ad templum sanctum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Qui custodiunt vanitates frustra, misericordiam suam derelinquunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Ego autem in voce laudis immolabo tibi: quæcumque vovi, reddam pro salute Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Et dixit Dominus pisci, et evomuit Jonam in aridam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 1, 'Et factum est verbum Domini ad Jonam secundo, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 2, 'Surge, et vade in Niniven, civitatem magnam, et prædica in ea prædicationem quam ego loquor ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 3, 'Et surrexit Jonas, et abiit in Niniven juxta verbum Domini: et Ninive erat civitas magna, itinere trium dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 4, 'Et cœpit Jonas introire in civitatem itinere diei unius: et clamavit, et dixit: Adhuc quadraginta dies, et Ninive subvertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 5, 'Et crediderunt viri Ninivitæ in Deum, et prædicaverunt jejunium, et vestiti sunt saccis, a majore usque ad minorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 6, 'Et pervenit verbum ad regem Ninive: et surrexit de solio suo, et abjecit vestimentum suum a se, et indutus est sacco, et sedit in cinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 7, 'Et clamavit, et dixit in Ninive ex ore regis et principum ejus, dicens: Homines, et jumenta, et boves, et pecora non gustent quidquam: nec pascantur, et aquam non bibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 8, 'Et operiantur saccis homines et jumenta, et clament ad Dominum in fortitudine: et convertatur vir a via sua mala, et ab iniquitate quæ est in manibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 9, 'Quis scit si convertatur et ignoscat Deus, et revertatur a furore iræ suæ, et non peribimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 3, 10, 'Et vidit Deus opera eorum, quia conversi sunt de via sua mala: et misertus est Deus super malitiam quam locutus fuerat ut faceret eis, et non fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 1, 'Et afflictus est Jonas afflictione magna, et iratus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 2, 'et oravit ad Dominum, et dixit: Obsecro, Domine, numquid non hoc est verbum meum cum adhuc essem in terra mea? propter hoc præoccupavi ut fugerem in Tharsis: scio enim quia tu Deus clemens et misericors es, patiens et multæ miserationis, et ignoscens super malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 3, 'Et nunc, Domine, tolle, quæso, animam meam a me, quia melior est mihi mors quam vita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 4, 'Et dixit Dominus: Putasne bene irasceris tu?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 5, 'Et egressus est Jonas de civitate, et sedit contra orientem civitatis: et fecit sibimet umbraculum ibi, et sedebat subter illud in umbra, donec videret quid accideret civitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 6, 'Et præparavit Dominus Deus hederam, et ascendit super caput Jonæ, ut esset umbra super caput ejus, et protegeret eum (laboraverat enim): et lætatus est Jonas super hedera lætitia magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 7, 'Et paravit Deus vermen ascensu diluculi in crastinum: et percussit hederam, et exaruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 8, 'Et cum ortus fuisset sol, præcepit Dominus vento calido et urenti: et percussit sol super caput Jonæ, et æstuabat: et petivit animæ suæ ut moreretur, et dixit: Melius est mihi mori quam vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 9, 'Et dixit Dominus ad Jonam: Putasne bene irasceris tu super hedera? Et dixit: Bene irascor ego usque ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 10, 'Et dixit Dominus: Tu doles super hederam in qua non laborasti, neque fecisti ut cresceret; quæ sub una nocte nata est, et sub una nocte periit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 4, 11, 'et ego non parcam Ninive, civitati magnæ, in qua sunt plus quam centum viginti millia hominum qui nesciunt quid sit inter dexteram et sinistram suam, et jumenta multa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Verbum Domini, quod factum est ad Michæam Morasthiten, in diebus Joathan, Achaz, et Ezechiæ, regum Juda, quod vidit super Samariam et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Audite, populi omnes, et attendat terra, et plenitudo ejus: et sit Dominus Deus vobis in testem, Dominus de templo sancto suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Quia ecce Dominus egredietur de loco suo, et descendet, et calcabit super excelsa terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Et consumentur montes subtus eum, et valles scindentur sicut cera a facie ignis, et sicut aquæ quæ decurrunt in præceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'In scelere Jacob omne istud, et in peccatis domus Israël. Quod scelus Jacob? nonne Samaria? et quæ excelsa Judæ? nonne Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Et ponam Samariam quasi acervum lapidum in agro, cum plantatur vinea; et detraham in vallem lapides ejus, et fundamenta ejus revelabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Et omnia sculptilia ejus concidentur, et omnes mercedes ejus comburentur igne, et omnia idola ejus ponam in perditionem, quia de mercedibus meretricis congregata sunt, et usque ad mercedem meretricis revertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Super hoc plangam, et ululabo; vadam spoliatus, et nudus; faciam planctum velut draconum, et luctum quasi struthionum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'quia desperata est plaga ejus, quia venit usque ad Judam; tetigit portam populi mei usque ad Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'In Geth nolite annuntiare; lacrimis ne ploretis; in domo pulveris pulvere vos conspergite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Et transite vobis, habitatio pulchra, confusa ignominia: non est egressa quæ habitat in exitu: planctum domus vicina accipiet ex vobis, quæ stetit sibimet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Quia infirmata est in bonum, quæ habitat in amaritudinibus; quia descendit malum a Domino in portam Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Tumultus quadrigæ stuporis habitanti Lachis: principium peccati est filiæ Sion, quia in te inventa sunt scelera Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Propterea dabit emissarios super hæreditatem Geth, domus mendacii in deceptionem regibus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Adhuc hæredem adducam tibi quæ habitas in Maresa; usque ad Odollam veniet gloria Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Decalvare, et tondere super filios deliciarum tuarum; dilata calvitium tuum sicut aquila, quoniam captivi ducti sunt ex te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Væ qui cogitatis inutile, et operamini malum in cubilibus vestris! In luce matutina faciunt illud, quoniam contra Deum est manus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Et concupierunt agros, et violenter tulerunt: et rapuerunt domos, et calumniabantur virum, et domum ejus: virum, et hæreditatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Idcirco hæc dicit Dominus: Ecce ego cogito super familiam istam malum, unde non auferetis colla vestra, et non ambulabitis superbi: quoniam tempus pessimum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'In die illa sumetur super vos parabola, et cantabitur canticum cum suavitate, dicentium: Depopulatione vastati sumus; pars populi mei commutata est: quomodo recedet a me, cum revertatur, qui regiones nostras dividat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Propter hoc non erit tibi mittens funiculum sortis in cœtu Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Ne loquamini loquentes; non stillabit super istos, non comprehendet confusio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Dicit domus Jacob: Numquid abbreviatus est spiritus Domini, aut tales sunt cogitationes ejus? nonne verba mea bona sunt cum eo qui recte graditur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'et e contrario populus meus in adversarium consurrexit. Desuper tunica pallium sustulistis: et eos qui transibant simpliciter convertistis in bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Mulieres populi mei ejecistis de domo deliciarum suarum; a parvulis earum tulistis laudem meam in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Surgite, et ite, quia non habetis hic requiem: propter immunditiam ejus corrumpetur putredine pessima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Utinam non essem vir habens spiritum, et mendacium potius loquerer! Stillabo tibi in vinum et in ebrietatem; et erit super quem stillatur populus iste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Congregatione congregabo, Jacob, totum te; in unum conducam reliquias Israël: pariter ponam illum quasi gregem in ovili, quasi pecus in medio caularum: tumultuabuntur a multitudine hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Ascendet enim pandens iter ante eos: divident, et transibunt portam, et ingredientur per eam: et transibit rex eorum coram eis, et Dominus in capite eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Et dixi: Audite, princeps Jacob, et duces domus Israël: numquid non vestrum est scire judicium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'qui odio habetis bonum, et diligitis malum; qui violenter tollitis pelles eorum desuper eis, et carnem eorum desuper ossibus eorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'qui comederunt carnem populi mei, et pellem eorum desuper excoriaverunt, et ossa eorum confregerunt, et conciderunt sicut in lebete, et quasi carnem in medio ollæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Tunc clamabunt ad Dominum, et non exaudiet eos, et abscondet faciem suam ab eis in tempore illo, sicut nequiter egerunt in adinventionibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Hæc dicit Dominus super prophetas, qui seducunt populum meum: qui mordent dentibus suis, et prædicant pacem; et si quis non dederit in ore eorum quippiam, sanctificant super eum prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Propterea nox vobis pro visione erit, et tenebræ vobis pro divinatione; et occumbet sol super prophetas, et obtenebrabitur super eos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Et confundentur qui vident visiones, et confundentur divini; et operient omnes vultos suos, quia non est responsum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Verumtamen ego repletus sum fortitudine spiritus Domini, judicio, et virtute, ut annuntiem Jacob scelus suum, et Israël peccatum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Audite hoc, principes domus Jacob, et judices domus Israël, qui abominamini judicium, et omnia recta pervertitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'qui ædificatis Sion in sanguinibus, et Jerusalem in iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 11, 'Principes ejus in muneribus judicabant, et sacerdotes ejus in mercede docebant, et prophetæ ejus in pecunia divinabant: et super Dominum requiescebant, dicentes: Numquid non Dominus in medio nostrum? non venient super nos mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 12, 'Propter hoc, causa vestri, Sion quasi ager arabitur, et Jerusalem quasi acervus lapidum erit, et mons templi in excelsa silvarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Et erit: in novissimo dierum erit mons domus Domini præparatus in vertice montium, et sublimis super colles: et fluent ad eum populi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'et properabunt gentes multæ, et dicent: Venite, ascendamus ad montem Domini, et ad domum Dei Jacob: et docebit nos de viis suis, et ibimus in semitis ejus, quia de Sion egredietur lex, et verbum Domini de Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Et judicabit inter populos multos, et corripiet gentes fortes usque in longinquum: et concident gladios suos in vomeres, et hastas suas in ligones: non sumet gens adversus gentem gladium, et non discent ultra belligerare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Et sedebit vir subtus vitem suam et subtus ficum suam, et non erit qui deterreat, quia os Domini exercituum locutum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Quia omnes populi ambulabunt unusquisque in nomine dei sui; nos autem ambulabimus in nomine Domini Dei nostri, in æternum et ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'In die illa, dicit Dominus, congregabo claudicantem, et eam quam ejeceram colligam, et quam afflixeram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'et ponam claudicantem in reliquias, et eam quæ laboraverat, in gentem robustam: et regnabit Dominus super eos in monte Sion, ex hoc nunc et usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Et tu, turris gregis nebulosa filiæ Sion, usque ad te veniet, et veniet potestas prima, regnum filiæ Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Nunc quare mœrore contraheris? numquid rex non est tibi, aut consiliarius tuus periit, quia comprehendit te dolor sicut parturientem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Dole et satage, filia Sion, quasi parturiens, quia nunc egredieris de civitate, et habitabis in regione, et venies usque ad Babylonem: ibi liberaberis, ibi redimet te Dominus de manu inimicorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Et nunc congregatæ sunt super te gentes multæ, quæ dicunt: Lapidetur, et aspiciat in Sion oculus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Ipsi autem non cognoverunt cogitationes Domini, et non intellexerunt consilium ejus, quia congregavit eos quasi fœnum areæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Surge, et tritura, filia Sion, quia cornu tuum ponam ferreum, et ungulas tuas ponam æreas; et comminues populos multos, et interficies Domino rapinas eorum, et fortitudinem eorum Domino universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Nunc vastaberis, filia latronis. Obsidionem posuerunt super nos: in virga percutient maxillam judicis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Et tu, Bethlehem Ephrata, parvulus es in millibus Juda; ex te mihi egredietur qui sit dominator in Israël, et egressus ejus ab initio, a diebus æternitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Propter hoc dabit eos usque ad tempus in quo parturiens pariet, et reliquiæ fratrum ejus convertentur ad filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Et stabit, et pascet in fortitudine Domini, in sublimitate nominis Domini Dei sui: et convertentur, quia nunc magnificabitur usque ad terminos terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Et erit iste pax: cum venerit Assyrius in terram nostram, et quando calcaverit domibus nostris, et suscitabimus super eum septem pastores et octo primates homines;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'et pascent terram Assur in gladio, et terram Nemrod in lanceis ejus, et liberabit ab Assur cum venerit in terram nostram, et cum calcaverit in finibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Et erunt reliquiæ Jacob in medio populorum multorum quasi ros a Domino, et quasi stillæ super herbam, quæ non exspectat virum, et non præstolatur filios hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Et erunt reliquiæ Jacob in gentibus, in medio populorum multorum, quasi leo in jumentis silvarum, et quasi catulus leonis in gregibus pecorum, qui cum transierit, et conculcaverit, et ceperit, non est qui eruat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Exaltabitur manus tua super hostes tuos, et omnes inimici tui interibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Et erit in die illa, dicit Dominus: auferam equos tuos de medio tui, et disperdam quadrigas tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Et perdam civitates terræ tuæ, et destruam omnes munitiones tuas: et auferam maleficia de manu tua, et divinationes non erunt in te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 12, 'et perire faciam sculptilia tua et statuas tuas de medio tui, et non adorabis ultra opera manuum tuarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 13, 'et evellam lucos tuos de medio tui, et conteram civitates tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 14, 'Et faciam, in furore et in indignatione, ultionem in omnibus gentibus quæ non audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Audite quæ Dominus loquitur: Surge, contende judicio adversum montes, et audiant colles vocem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Audiant montes judicium Domini, et fortia fundamenta terræ; quia judicium Domini cum populo suo, et cum Israël dijudicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Popule meus, quid feci tibi? aut quid molestus fui tibi? Responde mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Quia eduxi te de terra \'gypti, et de domo servientium liberavi te, et misi ante faciem tuam Moysen, et Aaron, et Mariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Popule meus, memento, quæso, quid cogitaverit Balach, rex Moab, et quid responderit ei Balaam, filius Beor, de Setim usque ad Galgalam, ut cognosceres justitias Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Quid dignum offeram Domino? curvabo genu Deo excelso? Numquid offeram ei holocautomata et vitulos anniculos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'numquid placari potest Dominus in millibus arietum, aut in multis millibus hircorum pinguium? numquid dabo primogenitum meum pro scelere meo, fructum ventris mei pro peccato animæ meæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Indicabo tibi, o homo, quid sit bonum, et quid Dominus requirat a te: utique facere judicium, et diligere misericordiam, et sollicitum ambulare cum Deo tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Vox Domini ad civitatem clamat, et salus erit timentibus nomen tuum: audite, tribus, et quis approbabit illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Adhuc ignis in domo impii thesauri iniquitatis, et mensura minor iræ plena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Numquid justificabo stateram impiam, et saccelli pondera dolosa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'In quibus divites ejus repleti sunt iniquitate, et habitantes in ea loquebantur mendacium, et lingua eorum fraudulenta in ore eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Et ego ergo cœpi percutere te perditione super peccatis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Tu comedes, et non saturaberis, et humiliatio tua in medio tui: et apprehendes, et non salvabis, et quos salvaveris, in gladium dabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Tu seminabis, et non metes: tu calcabis olivam, et non ungeris oleo; et mustum, et non bibes vinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 16, 'Et custodisti præcepta Amri, et omne opus domus Achab, et ambulasti in voluntatibus eorum: ut darem te in perditionem, et habitantes in ea in sibilum, et opprobrium populi mei portabitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Væ mihi, quia factus sum sicut qui colligit in autumno racemos vindemiæ! non est botrus ad comedendum, præcoquas ficus desideravit anima mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Periit sanctus de terra, et rectus in hominibus non est: omnes in sanguine insidiantur; vir fratrem suum ad mortem venatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Malum manuum suarum dicunt bonum: princeps postulat, et judex in reddendo est; et magnus locutus est desiderium animæ suæ, et conturbaverunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Qui optimus in eis est, quasi paliurus, et qui rectus, quasi spina de sepe. Dies speculationis tuæ, visitatio tua venit: nunc erit vastitas eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Nolite credere amico, et nolite confidere in duce: ab ea quæ dormit in sinu tuo custodi claustra oris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Quia filius contumeliam facit patri, et filia consurgit adversus matrem suam: nurus adversus socrum suam, et inimici hominis domestici ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ego autem ad Dominum aspiciam; exspectabo Deum, salvatorem meum: audiet me Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Ne læteris, inimica mea, super me, quia cecidi: consurgam cum sedero in tenebris: Dominus lux mea est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Iram Domini portabo, quoniam peccavi ei, donec causam meam judicet, et faciat judicium meum. Educet me in lucem: videbo justitiam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Et aspiciet inimica mea, et operietur confusione, quæ dicit ad me: Ubi est Dominus Deus tuus? Oculi mei videbunt in eam: nunc erit in conculcationem ut lutum platearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Dies, ut ædificentur maceriæ tuæ; in die illa longe fiet lex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'In die illa et usque ad te veniet de Assur, et usque ad civitates munitas, et a civitatibus munitis usque ad flumen, et ad mare de mari, et ad montem de monte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Et terra erit in desolationem propter habitatores suos, et propter fructum cogitationum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Pasce populum tuum in virga tua, gregem hæreditatis tuæ, habitantes solos, in saltu, in medio Carmeli. Pascentur Basan et Galaad juxta dies antiquos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 15, 'Secundum dies egressionis tuæ de terra \'gypti, ostendam ei mirabilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 16, 'Videbunt gentes, et confundentur super omni fortitudine sua. Ponent manum super os, aures eorum surdæ erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 17, 'Lingent pulverem sicut serpentes; velut reptilia terræ perturbabuntur in ædibus suis. Dominum Deum nostrum formidabunt, et timebunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 18, 'Quis, Deus, similis tui, qui aufers iniquitatem, et transis peccatum reliquiarum hæreditatis tuæ? Non immittet ultra furorem suum, quoniam volens misericordiam est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 19, 'Revertetur, et miserebitur nostri; deponet iniquitates nostras, et projiciet in profundum maris omnia peccata nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 20, 'Dabis veritatem Jacob, misericordiam Abraham, quæ jurasti patribus nostris a diebus antiquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Onus Ninive. Liber visionis Nahum Elcesæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Deus æmulator, et ulciscens Dominus: ulciscens Dominus, et habens furorem: ulciscens Dominus in hostes suos, et irascens ipse inimicis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Dominus patiens, et magnus fortitudine, et mundans non faciet innocentem. Dominus in tempestate et turbine viæ ejus, et nebulæ pulvis pedum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Increpans mare, et exsiccans illud, et omnia flumina ad desertum deducens. Infirmatus est Basan et Carmelus, et flos Libani elanguit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Montes commoti sunt ab eo, et colles desolati sunt: et contremuit terra a facie ejus, et orbis, et omnes habitantes in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ante faciem indignationis ejus quis stabit? et quis resistet in ira furoris ejus? Indignatio ejus effusa est ut ignis, et petræ dissolutæ sunt ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Bonus Dominus, et confortans in die tribulationis, et sciens sperantes in se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Et in diluvio prætereunte consummationem faciet loci ejus, et inimicos ejus persequentur tenebræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Quid cogitatis contra Dominum? Consummationem ipse faciet: non consurget duplex tribulatio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'quia sicut spinæ se invicem complectuntur, sic convivium eorum pariter potantium; consumentur quasi stipula ariditate plena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Ex te exibit cogitans contra Dominum malitiam, mente pertractans prævaricationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Hæc dicit Dominus: Si perfecti fuerint, et ita plures, sic quoque attondentur, et pertransibit: afflixi te, et non affligam te ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Et nunc conteram virgam ejus de dorso tuo, et vincula tua disrumpam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Et præcipiet super te Dominus; non seminabitur ex nomine tuo amplius: de domo Dei tui interficiam sculptile, et conflatile; ponam sepulchrum tuum, quia inhonoratus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 15, 'Ecce super montes pedes evangelizantis, et annuntiantis pacem. Celebra, Juda, festivitates tuas, et redde vota tua, quia non adjiciet ultra ut pertranseat in te Belial: universus interiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Ascendit qui dispergat coram te, qui custodiat obsidionem: contemplare viam, conforta lumbos, robora virtutem valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Quia reddidit Dominus superbiam Jacob, sicut superbiam Israël; quia vastatores dissipaverunt eos, et propagines eorum corruperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Clypeus fortium ejus ignitus, viri exercitus in coccineis; igneæ habenæ currus in die præparationis ejus, et agitatores consopiti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'In itineribus conturbati sunt; quadrigæ collisæ sunt in plateis: aspectus eorum quasi lampades, quasi fulgura discurrentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Recordabitur fortium suorum; ruent in itineribus suis: velociter ascendent muros ejus, et præparabitur umbraculum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Portæ fluviorum apertæ sunt, et templum ad solum dirutum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Et miles captivus abductus est, et ancillæ ejus minabantur gementes ut columbæ, murmurantes in cordibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Et Ninive quasi piscina aquarum aquæ ejus; ipsi vero fugerunt. State, state! et non est qui revertatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Diripite argentum, diripite aurum: et non est finis divitiarum ex omnibus vasis desiderabilibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Dissipata est, et scissa, et dilacerata; et cor tabescens, et dissolutio geniculorum, et defectio in cunctis renibus, et facies omnium eorum sicut nigredo ollæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Ubi est habitaculum leonum, et pascua catulorum leonum, ad quam ivit leo ut ingrederetur illuc catulus leonis, et non est qui exterreat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Leo cepit sufficienter catulis suis, et necavit leænis suis, et implevit præda speluncas suas, et cubile suum rapina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Ecce ego ad te, dicit Dominus exercituum, et succendam usque ad fumum quadrigas tuas, et leunculos tuos comedet gladius, et exterminabo de terra prædam tuam, et non audietur ultra vox nuntiorum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Væ civitas sanguinum, universa mendacii dilaceratione plena! non recedet a te rapina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Vox flagelli, et vox impetus rotæ, et equi frementis, et quadrigæ ferventis, et equitis ascendentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'et micantis gladii, et fulgurantis hastæ, et multitudinis interfectæ, et gravis ruinæ; nec est finis cadaverum, et corruent in corporibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Propter multitudinem fornicationum meretricis speciosæ, et gratæ, et habentis maleficia, quæ vendidit gentes in fornicationibus suis, et familias in maleficiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Ecce ego ad te, dicit Dominus exercituum, et revelabo pudenda tua in facie tua; et ostendam gentibus nuditatem tuam, et regnis ignominiam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Et projiciam super te abominationes, et contumeliis te afficiam, et ponam te in exemplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Et erit: omnis qui viderit te resiliet a te, et dicet: Vastata est Ninive. Quis commovebit super te caput? unde quæram consolatorem tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Numquid melior es Alexandria populorum, quæ habitat in fluminibus? aquæ in circuitu ejus; cujus divitiæ, mare; aquæ, muri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, '\'thiopia fortitudo ejus, et \'gyptus, et non est finis; Africa et Libyes fuerunt in auxilio tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Sed et ipsa in transmigrationem ducta est in captivitatem: parvuli ejus elisi sunt in capite omnium viarum, et super inclytos ejus miserunt sortem, et omnes optimates ejus confixi sunt in compedibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Et tu ergo inebriaberis, et eris despecta: et tu quæres auxilium ab inimico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Omnes munitiones tuæ sicut ficus cum grossis suis: si concussæ fuerint, cadent in os comedentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Ecce populus tuus mulieres in medio tui: inimicis tuis adapertione pandentur portæ terræ tuæ, devorabit ignis vectes tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Aquam propter obsidionem hauri tibi: exstrue munitiones tuas, intra in lutum, et calca, subigens tene laterem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Ibi comedet te ignis, peribis gladio, devorabit te ut bruchus: congregare ut bruchus, multiplicare ut locusta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Plures fecisti negotiationes tuas quam stellæ sint cæli; bruchus expansus est, et avolavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Custodes tui quasi locustæ, et parvuli tui quasi locustæ locustarum, quæ considunt in sepibus in die frigoris: sol ortus est, et avolaverunt, et non est cognitus locus earum ubi fuerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Dormitaverunt pastores tui, rex Assur, sepelientur principes tui: latitavit populus tuus in montibus, et non est qui congreget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Non est obscura contritio tua; pessima est plaga tua. Omnes qui audierunt auditionem tuam compresserunt manum super te: quia super quem non transiit malitia tua semper?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Onus quod vidit Habacuc propheta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Usquequo, Domine, clamabo, et non exaudies? vociferabor ad te, vim patiens, et non salvabis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Quare ostendisti mihi iniquitatem et laborem, videre prædam et injustitiam contra me? Et factum est judicium, et contradictio potentior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Propter hoc lacerata est lex, et non pervenit usque ad finem judicium; quia impius prævalet adversus justum, propterea egreditur judicium perversum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Aspicite in gentibus, et videte; admiramini, et obstupescite: quia opus factum est in diebus vestris, quod nemo credet cum narrabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Quia ecce ego suscitabo Chaldæos, gentem amaram et velocem, ambulantem super latitudinem terræ, ut possideat tabernacula non sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Horribilis et terribilis est: ex semetipsa judicium et onus ejus egredietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Leviores pardis equi ejus, et velociores lupis vespertinis: et diffundentur equites ejus: equites namque ejus de longe venient; volabunt quasi aquila festinans ad comedendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Omnes ad prædam venient, facies eorum ventus urens; et congregabit quasi arenam captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Et ipse de regibus triumphabit, et tyranni ridiculi ejus erunt; ipse super omnem munitionem ridebit, et comportabit aggerem, et capiet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Tunc mutabitur spiritus, et pertransibit, et corruet: hæc est fortitudo ejus dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Numquid non tu a principio, Domine, Deus meus, sancte meus, et non moriemur? Domine, in judicium posuisti eum, et fortem, ut corriperes, fundasti eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Mundi sunt oculi tui, ne videas malum, et respicere ad iniquitatem non poteris. Quare respicis super iniqua agentes, et taces devorante impio justiorem se?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Et facies homines quasi pisces maris, et quasi reptile non habens principem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Totum in hamo sublevavit, traxit illud in sagena sua, et congregavit in rete suum. Super hoc lætabitur, et exsultabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Propterea immolabit sagenæ suæ, et sacrificabit reti suo, quia in ipsis incrassata est pars ejus, et cibus ejus electus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Propter hoc ergo expandit sagenam suam, et semper interficere gentes non parcet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Super custodiam meam stabo, et figam gradum super munitionem: et contemplabor ut videam quid dicatur mihi, et quid respondeam ad arguentem me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Et respondit mihi Dominus, et dixit: Scribe visum, et explana eum super tabulas, ut percurrat qui legerit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Quia adhuc visus procul; et apparebit in finem, et non mentietur: si moram fecerit, exspecta illum, quia veniens veniet, et non tardabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Ecce qui incredulus est, non erit recta anima ejus in semetipso; justus autem in fide sua vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Et quomodo vinum potantem decipit, sic erit vir superbus, et non decorabitur: qui dilatavit quasi infernus animam suam, et ipse quasi mors, et non adimpletur: et congregabit ad se omnes gentes, et coacervabit ad se omnes populos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Numquid non omnes isti super eum parabolam sument, et loquelam ænigmatum ejus, et dicetur: Væ ei qui multiplicat non sua? usquequo et aggravat contra se densum lutum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Numquid non repente consurgent qui mordeant te, et suscitabuntur lacerantes te, et eris in rapinam eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Quia tu spoliasti gentes multas, spoliabunt te omnes qui reliqui fuerint de populis, propter sanguinem hominis, et iniquitatem terræ, civitatis, et omnium habitantium in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Væ qui congregat avaritiam malam domui suæ, ut sit in excelso nidus ejus, et liberari se putat de manu mali!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Cogitasti confusionem domui tuæ; concidisti populos multos, et peccavit anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Quia lapis de pariete clamabit, et lignum, quod inter juncturas ædificiorum est, respondebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Væ qui ædificat civitatem in sanguinibus, et præparat urbem in iniquitate!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Numquid non hæc sunt a Domino exercituum? laborabunt enim populi in multo igne, et gentes in vacuum, et deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Quia replebitur terra, ut cognoscant gloriam Domini, quasi aquæ operientes mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Væ qui potum dat amico suo mittens fel suum, et inebrians ut aspiciat nuditatem ejus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Repletus es ignominia pro gloria; bibe tu quoque, et consopire. Circumdabit te calix dexteræ Domini, et vomitus ignominiæ super gloriam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Quia iniquitas Libani operiet te, et vastitas animalium deterrebit eos de sanguinibus hominum, et iniquitate terræ, et civitatis, et omnium habitantium in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Quid prodest sculptile, quia sculpsit illud fictor suus, conflatile, et imaginem falsam? quia speravit in figmento fictor ejus, ut faceret simulacra muta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Væ qui dicit ligno: Expergiscere; Surge, lapidi tacenti! Numquid ipse docere poterit? ecce iste coopertus est auro et argento, et omnis spiritus non est in visceribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Dominus autem in templo sancto suo: sileat a facie ejus omnis terra!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Oratio Habacuc prophetæ, pro ignorantiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Domine, audivi auditionem tuam, et timui. Domine, opus tuum, in medio annorum vivifica illud; in medio annorum notum facies: cum iratus fueris, misericordiæ recordaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Deus ab austro veniet, et Sanctus de monte Pharan: operuit cælos gloria ejus, et laudis ejus plena est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Splendor ejus ut lux erit, cornua in manibus ejus: ibi abscondita est fortitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Ante faciem ejus ibit mors, et egredietur diabolus ante pedes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Stetit, et mensus est terram; aspexit, et dissolvit gentes, et contriti sunt montes sæculi: incurvati sunt colles mundi ab itineribus æternitatis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Pro iniquitate vidi tentoria \'thiopiæ; turbabuntur pelles terræ Madian.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Numquid in fluminibus iratus es, Domine? aut in fluminibus furor tuus? vel in mari indignatio tua? Qui ascendes super equos tuos, et quadrigæ tuæ salvatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Suscitans suscitabis arcum tuum, juramenta tribubus quæ locutus es; fluvios scindes terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Viderunt te, et doluerunt montes; gurges aquarum transiit: dedit abyssus vocem suam; altitudo manus suas levavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Sol et luna steterunt in habitaculo suo: in luce sagittarum tuarum ibunt, in splendore fulgurantis hastæ tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'In fremitu conculcabis terram; in furore obstupefacies gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Egressus es in salutem populi tui, in salutem cum christo tuo: percussisti caput de domo impii, denudasti fundamentum ejus usque ad collum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Maledixisti sceptris ejus, capiti bellatorum ejus, venientibus ut turbo ad dispergendum me: exsultatio eorum, sicut ejus qui devorat pauperem in abscondito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Viam fecisti in mari equis tuis, in luto aquarum multarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Audivi, et conturbatus est venter meus; a voce contremuerunt labia mea. Ingrediatur putredo in ossibus meis, et subter me scateat: ut requiescam in die tribulationis, ut ascendam ad populum accinctum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Ficus enim non florebit, et non erit germen in vineis; mentietur opus olivæ, et arva non afferent cibum: abscindetur de ovili pecus, et non erit armentum in præsepibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 18, 'Ego autem in Domino gaudebo; et exsultabo in Deo Jesu meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 19, 'Deus Dominus fortitudo mea, et ponet pedes meos quasi cervorum: et super excelsa mea deducet me victor in psalmis canentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Verbum Domini quod factum est ad Sophoniam, filium Chusi, filii Godoliæ, filii Amariæ, filii Ezeciæ, in diebus Josiæ, filii Amon, regis Judæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Congregans congregabo omnia a facie terræ, dicit Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'congregans hominem et pecus, congregans volatilia cæli et pisces maris: et ruinæ impiorum erunt, et disperdam homines a facie terræ, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Et extendam manum meam super Judam et super omnes habitantes Jerusalem: et disperdam de loco hoc reliquias Baal, et nomina ædituorum cum sacerdotibus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'et eos qui adorant super tecta militiam cæli, et adorant et jurant in Domino, et jurant in Melchom;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'et qui avertuntur de post tergum Domini, et qui non quæsierunt Dominum, nec investigaverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Silete a facie Domini Dei, quia juxta est dies Domini: quia præparavit Dominus hostiam; sanctificavit vocatos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Et erit: in die hostiæ Domini, visitabo super principes, et super filios regis, et super omnes qui induti sunt veste peregrina;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'et visitabo super omnem qui arroganter ingreditur super limen in die illa, qui complent domum Domini Dei sui iniquitate et dolo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Et erit in die illa, dicit Dominus, vox clamoris a porta piscium, et ululatus a Secunda, et contritio magna a collibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Ululate, habitatores Pilæ: conticuit omnis populus Chanaan, disperierunt omnes involuti argento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Et erit in tempore illo: scrutabor Jerusalem in lucernis, et visitabo super viros defixos in fæcibus suis, qui dicunt in cordibus suis: Non faciet bene Dominus, et non faciet male.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Et erit fortitudo eorum in direptionem, et domus eorum in desertum: et ædificabunt domos, et non habitabunt; et plantabunt vineas, et non bibent vinum earum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Juxta est dies Domini magnus: juxta est, et velox nimis. Vox diei Domini amara: tribulabitur ibi fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Dies iræ dies illa, dies tribulationis et angustiæ, dies calamitatis et miseriæ, dies tenebrarum et caliginis, dies nebulæ et turbinis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'dies tubæ et clangoris super civitates munitas, et super angulos excelsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Et tribulabo homines, et ambulabunt ut cæci, quia Domino peccaverunt; et effundetur sanguis eorum sicut humus, et corpora eorum sicut stercora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Sed et argentum eorum et aurum eorum non poterit liberare eos in die iræ Domini: in igne zeli ejus devorabitur omnis terra, quia consummationem cum festinatione faciet cunctis habitantibus terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Convenite, congregamini, gens non amabilis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'priusquam pariat jussio quasi pulverem transeuntem diem, antequam veniat super vos ira furoris Domini, antequam veniat super vos dies indignationis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Quærite Dominum, omnes mansueti terræ, qui judicium ejus estis operati; quærite justum, quærite mansuetum, si quomodo abscondamini in die furoris Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Quia Gaza destructa erit, et Ascalon in desertum: Azotum in meridie ejicient, et Accaron eradicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Væ qui habitatis funiculum maris, gens perditorum! verbum Domini super vos, Chanaan, terra Philisthinorum; et disperdam te, ita ut non sit inhabitator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Et erit funiculus maris requies pastorum, et caulæ pecorum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'et erit funiculus ejus qui remanserit de domo Juda: ibi pascentur, in domibus Ascalonis ad vesperam requiescent, quia visitabit eos Dominus Deus eorum, et avertet captivitatem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Audivi opprobrium Moab, et blasphemias filiorum Ammon, quæ exprobraverunt populo meo, et magnificati sunt super terminos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Propterea vivo ego, dicit Dominus exercituum, Deus Israël, quia Moab ut Sodoma erit, et filii Ammon quasi Gomorrha: siccitas spinarum, et acervi salis, et desertum usque in æternum: reliquiæ populi mei diripient eos, et residui gentis meæ possidebunt illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Hoc eis eveniet pro superbia sua, quia blasphemaverunt et magnificati sunt super populum Domini exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Horribilis Dominus super eos, et attenuabit omnes deos terræ: et adorabunt eum viri de loco suo, omnes insulæ gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Sed et vos, \'thiopes, interfecti gladio meo eritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Et extendet manum suam super aquilonem, et perdet Assur, et ponet speciosam in solitudinem, et in invium, et quasi desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Et accubabunt in medio ejus greges, omnes bestiæ gentium; et onocrotalus et ericius in liminibus ejus morabuntur: vox cantantis in fenestra, corvus in superliminari, quoniam attenuabo robur ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Hæc est civitas gloriosa habitans in confidentia, quæ dicebat in corde suo: Ego sum, et extra me non est alia amplius: quomodo facta est in desertum cubile bestiæ? omnis qui transit per eam sibilabit, et movebit manum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Væ provocatrix, et redempta civitas, columba!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'non audivit vocem, et non suscepit disciplinam; in Domino non est confisa, ad Deum suum non appropinquavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Principes ejus in medio ejus quasi leones rugientes; judices ejus lupi vespere, non relinquebant in mane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Prophetæ ejus vesani, viri infideles; sacerdotes ejus polluerunt sanctum, injuste egerunt contra legem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Dominus justus in medio ejus non faciet iniquitatem; mane, mane judicium suum dabit in lucem, et non abscondetur; nescivit autem iniquus confusionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Disperdidi gentes, et dissipati sunt anguli earum; desertas feci vias eorum, dum non est qui transeat; desolatæ sunt civitates eorum, non remanente viro, neque ullo habitatore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Dixi: Attamen timebis me, suscipies disciplinam; et non peribit habitaculum ejus, propter omnia in quibus visitavi eam: verumtamen diluculo surgentes corruperunt omnes cogitationes suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Quapropter exspecta me, dicit Dominus, in die resurrectionis meæ in futurum: quia judicium meum ut congregem gentes, et colligam regna, et effundam super eos indignationem meam, omnem iram furoris mei: in igne enim zeli mei devorabitur omnis terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Quia tunc reddam populis labium electum, ut invocent omnes in nomine Domini, et serviant ei humero uno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Ultra flumina \'thiopiæ, inde supplices mei; filii dispersorum meorum deferent munus mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'In die illa non confunderis super cunctis adinventionibus tuis, quibus prævaricata es in me, quia tunc auferam de medio tui magniloquos superbiæ tuæ, et non adjicies exaltari amplius in monte sancto meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Et derelinquam in medio tui populum pauperem et egenum: et sperabunt in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Reliquiæ Israël non facient iniquitatem, nec loquentur mendacium, et non invenietur in ore eorum lingua dolosa, quoniam ipsi pascentur, et accubabunt, et non erit qui exterreat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Lauda, filia Sion; jubila, Israël: lætare, et exsulta in omni corde, filia Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Abstulit Dominus judicium tuum; avertit inimicos tuos. Rex Israël Dominus in medio tui: non timebis malum ultra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'In die illa dicetur Jerusalem: Noli timere; Sion: Non dissolvantur manus tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Dominus Deus tuus in medio tui fortis, ipse salvabit: gaudebit super te in lætitia, silebit in dilectione sua, exsultabit super te in laude.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Nugas, qui a lege recesserant, congregabo, quia ex te erant: ut non ultra habeas super eis opprobrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Ecce ego interficiam omnes qui afflixerunt te in tempore illo: et salvabo claudicantem, et eam quæ ejecta fuerat congregabo: et ponam eos in laudem, et in nomen, in omni terra confusionis eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'in tempore illo quo adducam vos, et in tempore quo congregabo vos. Dabo enim vos in nomen, et in laudem omnibus populis terræ, cum convertero captivitatem vestram coram oculis vestris, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'In anno secundo Darii regis, in mense sexto, in die una mensis, factum est verbum Domini in manu Aggæi prophetæ, ad Zorobabel, filium Salathiel, ducem Juda, et ad Jesum, filium Josedec, sacerdotem magnum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Hæc ait Dominus exercituum, dicens: Populus iste dicit: Nondum venit tempus domus Domini ædificandæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Et factum est verbum Domini in manu Aggæi prophetæ, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Numquid tempus vobis est ut habitetis in domibus laqueatis, et domus ista deserta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Et nunc hæc dicit Dominus exercituum: Ponite corda vestra super vias vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Seminastis multum, et intulistis parum; comedistis, et non estis satiati; bibistis, et non estis inebriati; operuistis vos, et non estis calefacti; et qui mercedes congregavit, misit eas in sacculum pertusum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Hæc dicit Dominus exercituum: Ponite corda vestra super vias vestras;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'ascendite in montem, portate ligna, et ædificate domum: et acceptabilis mihi erit, et glorificabor, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Respexistis ad amplius, et ecce factum est minus; et intulistis in domum, et exsufflavi illud: quam ob causam? dicit Dominus exercituum: quia domus mea deserta est, et vos festinatis unusquisque in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Propter hoc super vos prohibiti sunt cæli ne darent rorem, et terra prohibita est ne daret germen suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'et vocavi siccitatem super terram, et super montes, et super triticum, et super vinum, et super oleum, et quæcumque profert humus, et super homines, et super jumenta, et super omnem laborem manuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Et audivit Zorobabel, filius Salathiel, et Jesus, filius Josedec, sacerdos magnus, et omnes reliquiæ populi, vocem Domini Dei sui, et verba Aggæi prophetæ, sicut misit eum Dominus Deus eorum ad eos, et timuit populus a facie Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Et dixit Aggæus, nuntius Domini de nuntiis Domini, populo dicens: Ego vobiscum sum, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Et suscitavit Dominus spiritum Zorobabel, filii Salathiel, ducis Juda, et spiritum Jesu, filii Josedec, sacerdotis magni, et spiritum reliquorum de omni populo: et ingressi sunt, et faciebant opus in domo Domini exercituum, Dei sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'In die vigesima et quarta mensis, in sexto mense, in anno secundo Darii regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'In septimo mense, vigesima et prima mensis, factum est verbum Domini in manu Aggæi prophetæ, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Loquere ad Zorobabel, filium Salathiel, ducem Juda, et ad Jesum, filium Josedec, sacerdotem magnum, et ad reliquos populi, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Quis in vobis est derelictus, qui vidit domum istam in gloria sua prima? et quid vos videtis hanc nunc? numquid non ita est, quasi non sit in oculis vestris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Et nunc confortare, Zorobabel, dicit Dominus; et confortare, Jesu, fili Josedec, sacerdos magne; et confortare, omnis populus terræ, dicit Dominus exercituum: et facite (quoniam ego vobiscum sum, dicit Dominus exercituum)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'verbum quod pepigi vobiscum cum egrederemini de terra \'gypti: et spiritus meus erit in medio vestrum: nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Quia hæc dicit Dominus exercituum: Adhuc unum modicum est, et ego commovebo cælum, et terram, et mare, et aridam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Et movebo omnes gentes, et veniet desideratus cunctis gentibus: et implebo domum istam gloria, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Meum est argentum, et meum est aurum, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Magna erit gloria domus istius novissimæ plus quam primæ, dicit Dominus exercituum: et in loco isto dabo pacem, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'In vigesima et quarta noni mensis, in anno secundo Darii regis, factum est verbum Domini ad Aggæum prophetam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Hæc dicit Dominus exercituum: Interroga sacerdotes legem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Si tulerit homo carnem sanctificatam in ora vestimenti sui, et tetigerit de summitate ejus panem, aut pulmentum, aut vinum, aut oleum, aut omnem cibum, numquid sanctificabitur? Respondentes autem sacerdotes, dixerunt: Non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Et dixit Aggæus: Si tetigerit pollutus in anima ex omnibus his, numquid contaminabitur? Et responderunt sacerdotes, et dixerunt: Contaminabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Et respondit Aggæus, et dixit: Sic populus iste, et sic gens ista ante faciem meam, dicit Dominus, et sic omne opus manuum eorum: et omnia quæ obtulerunt ibi, contaminata erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Et nunc ponite corda vestra a die hac et supra, antequam poneretur lapis super lapidem in templo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Cum accederetis ad acervum viginti modiorum, et fierent decem; et intraretis ad torcular, ut exprimeretis quinquaginta lagenas, et fiebant viginti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Percussi vos vento urente, et aurugine, et grandine omnia opera manuum vestrarum: et non fuit in vobis qui reverteretur ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Ponite corda vestra ex die ista, et in futurum, a die vigesima et quarta noni mensis: a die qua fundamenta jacta sunt templi Domini, ponite super cor vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Numquid jam semen in germine est, et adhuc vinea, et ficus, et malogranatum, et lignum olivæ non floruit? ex die ista benedicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Et factum est verbum Domini secundo ad Aggæum in vigesima et quarta mensis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Loquere ad Zorobabel ducem Juda, dicens: Ego movebo cælum pariter et terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'et subvertam solium regnorum, et conteram fortitudinem regni gentium: et subvertam quadrigam et ascensorem ejus, et descendent equi, et ascensores eorum, vir in gladio fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'In die illa, dicit Dominus exercituum, assumam te, Zorobabel, fili Salathiel, serve meus, dicit Dominus: et ponam te quasi signaculum, quia te elegi, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'In mense octavo, in anno secundo Darii regis, factum est verbum Domini ad Zachariam filium Barachiæ filii Addo prophetam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Iratus est Dominus super patres vestros iracundia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Et dices ad eos: Hæc dicit Dominus exercituum: Convertimini ad me, ait Dominus exercituum, et convertar ad vos, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Ne sitis sicut patres vestri, ad quos clamabant prophetæ priores, dicentes: Hæc dicit Dominus exercituum: Convertimini de viis vestris malis, et de cogitationibus vestris pessimis: et non audierunt, neque attenderunt ad me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Patres vestri, ubi sunt? et prophetæ numquid in sempiternum vivent?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Verumtamen verba mea, et legitima mea, quæ mandavi servis meis prophetis, numquid non comprehenderunt patres vestros, et conversi sunt, et dixerunt: Sicut cogitavit Dominus exercituum facere nobis secundum vias nostras, et secundum adinventiones nostras, fecit nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'In die vigesima et quarta undecimi mensis Sabath, in anno secundo Darii, factum est verbum Domini ad Zachariam filium Barachiæ filii Addo prophetam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Vidi per noctem, et ecce vir ascendens super equum rufum, et ipse stabat inter myrteta, quæ erant in profundo, et post eum equi rufi, varii, et albi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Et dixi: Quid sunt isti, domine mi? Et dixit ad me angelus qui loquebatur in me: Ego ostendam tibi quid sint hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Et respondit vir qui stabat inter myrteta, et dixit: Isti sunt quos misit Dominus ut perambulent terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Et responderunt angelo Domini, qui stabat inter myrteta, et dixerunt: Perambulavimus terram, et ecce omnis terra habitatur, et quiescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Et respondit angelus Domini, et dixit: Domine exercituum, usquequo tu non misereberis Jerusalem, et urbium Juda, quibus iratus es? iste jam septuagesimus annus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Et respondit Dominus angelo qui loquebatur in me verba bona, verba consolatoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et dixit ad me angelus qui loquebatur in me: Clama, dicens: Hæc dicit Dominus exercituum: Zelatus sum Jerusalem et Sion zelo magno,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'et ira magna ego irascor super gentes opulentas, quia ego iratus sum parum, ipsi vero adjuverunt in malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Propterea hæc dicit Dominus: Revertar ad Jerusalem in misericordiis, et domus mea ædificabitur in ea, ait Dominus exercituum, et perpendiculum extendetur super Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Adhuc clama, dicens: Hæc dicit Dominus exercituum: Adhuc affluent civitates meæ bonis, et consolabitur adhuc Dominus Sion, et eliget adhuc Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Et levavi oculos meos, et vidi, et ecce quatuor cornua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Et dixi ad angelum qui loquebatur in me: Quid sunt hæc? Et dixit ad me: Hæc sunt cornua quæ ventilaverunt Judam, et Israël, et Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Et ostendit mihi Dominus quatuor fabros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Et dixi: Quid isti veniunt facere? Qui ait, dicens: Hæc sunt cornua quæ ventilaverunt Judam per singulos viros, et nemo eorum levavit caput suum: et venerunt isti deterrere ea, ut dejiciant cornua gentium, quæ levaverunt cornu super terram Juda ut dispergerent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Et levavi oculos meos, et vidi, et ecce vir, et in manu ejus funiculus mensorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Et dixi: Quo tu vadis? Et dixit ad me: Ut metiar Jerusalem, et videam quanta sit latitudo ejus, et quanta longitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Et ecce angelus qui loquebatur in me egrediebatur, et angelus alius egrediebatur in occursum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'et dixit ad eum: Curre, loquere ad puerum istum, dicens: Absque muro habitabitur Jerusalem, præ multitudine hominum et jumentorum in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Et ego ero ei, ait Dominus, murus ignis in circuitu, et in gloria ero in medio ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'O, o, fugite de terra aquilonis, dicit Dominus, quoniam in quatuor ventos cæli dispersi vos, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'O Sion! fuge, quæ habitas apud filiam Babylonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'quia hæc dicit Dominus exercituum: Post gloriam misit me ad gentes quæ spoliaverunt vos: qui enim tetigerit vos, tangit pupillam oculi mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'quia ecce ego levo manum meam super eos, et erunt prædæ his qui serviebant sibi: et cognoscetis quia Dominus exercituum misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Lauda et lætare, filia Sion, quia ecce ego venio, et habitabo in medio tui, ait Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Et applicabuntur gentes multæ ad Dominum in die illa, et erunt mihi in populum, et habitabo in medio tui: et scies quia Dominus exercituum misit me ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Et possidebit Dominus Judam partem suam in terra sanctificata, et eliget adhuc Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Sileat omnis caro a facie Domini, quia consurrexit de habitaculo sancto suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Et ostendit mihi Dominus Jesum sacerdotem magnum, stantem coram angelo Domini: et Satan stabat a dextris ejus ut adversaretur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Et dixit Dominus ad Satan: Increpet Dominus in te, Satan! et increpet Dominus in te, qui elegit Jerusalem! numquid non iste torris est erutus de igne?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Et Jesus erat indutus vestibus sordidis, et stabat ante faciem angeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Qui respondit, et ait ad eos qui stabant coram se, dicens: Auferte vestimenta sordida ab eo. Et dixit ad eum: Ecce abstuli a te iniquitatem tuam, et indui te mutatoriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Et dixit: Ponite cidarim mundam super caput ejus. Et posuerunt cidarim mundam super caput ejus, et induerunt eum vestibus: et angelus Domini stabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Et contestabatur angelus Domini Jesum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Hæc dicit Dominus exercituum: Si in viis meis ambulaveris, et custodiam meam custodieris, tu quoque judicabis domum meam, et custodies atria mea, et dabo tibi ambulantes de his qui nunc hic assistunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Audi, Jesu sacerdos magne, tu et amici tui, qui habitant coram te, quia viri portendentes sunt: ecce enim ego adducam servum meum Orientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Quia ecce lapis quem dedi coram Jesu: super lapidem unum septem oculi sunt: ecce ego cælabo sculpturam ejus, ait Dominus exercituum, et auferam iniquitatem terræ illius in die una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'In die illa, dicit Dominus exercituum, vocabit vir amicum suum subter vitem et subter ficum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Et reversus est angelus qui loquebatur in me, et suscitavit me quasi virum qui suscitatur de somno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Et dixit ad me: Quid tu vides? Et dixi: Vidi, et ecce candelabrum aureum totum, et lampas ejus super caput ipsius, et septem lucernæ ejus super illud, et septem infusoria lucernis quæ erant super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Et duæ olivæ super illud: una a dextris lampadis, et una a sinistris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Et respondi, et aio ad angelum qui loquebatur in me, dicens: Quid sunt hæc, domine mi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Et respondit angelus qui loquebatur in me, et dixit ad me: Numquid nescis quid sunt hæc? Et dixi: Non, domine mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Et respondit, et ait ad me, dicens: Hoc est verbum Domini ad Zorobabel, dicens: Non in exercitu, nec in robore, sed in spiritu meo, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Quis tu, mons magne, coram Zorobabel? In planum: et educet lapidem primarium, et exæquabit gratiam gratiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Manus Zorobabel fundaverunt domum istam, et manus ejus perficient eam: et scietis quia Dominus exercituum misit me ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Quis enim despexit dies parvos? Et lætabuntur, et videbunt lapidem stanneum in manu Zorobabel. Septem isti oculi sunt Domini, qui discurrunt in universam terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Et respondi, et dixi ad eum: Quid sunt duæ olivæ istæ, ad dexteram candelabri, et ad sinistram ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Et respondi secundo, et dixi ad eum: Quid sunt duæ spicæ olivarum quæ sunt juxta duo rostra aurea in quibus sunt suffusoria ex auro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Et ait ad me, dicens: Numquid nescis quid sunt hæc? Et dixi: Non, domine mi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Et dixit: Isti sunt duo filii olei, qui assistunt Dominatori universæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Et conversus sum, et levavi oculos meos, et vidi, et ecce volumen volans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Et dixit ad me: Quid tu vides? Et dixi: Ego video volumen volans: longitudo ejus viginti cubitorum, et latitudo ejus decem cubitorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Et dixit ad me: Hæc est maledictio quæ egreditur super faciem omnis terræ: quia omnis fur, sicut ibi scriptum est, judicabitur, et omnis jurans ex hoc similiter judicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Educam illud, dicit Dominus exercituum: et veniet ad domum furis, et ad domum jurantis in nomine meo mendaciter: et commorabitur in medio domus ejus, et consumet eam, et ligna ejus, et lapides ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Et egressus est angelus qui loquebatur in me, et dixit ad me: Leva oculos tuos, et vide quid est hoc quod egreditur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Et dixi: Quidnam est? Et ait: Hæc est amphora egrediens. Et dixit: Hæc est oculus eorum in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Et ecce talentum plumbi portabatur, et ecce mulier una sedens in medio amphoræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Et dixit: Hæc est impietas. Et projecit eam in medio amphoræ, et misit massam plumbeam in os ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Et levavi oculos meos, et vidi: et ecce duæ mulieres egredientes: et spiritus in alis earum, et habebant alas quasi alas milvi, et levaverunt amphoram inter terram et cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Et dixi ad angelum qui loquebatur in me: Quo istæ deferunt amphoram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Et dixit ad me: Ut ædificetur ei domus in terra Sennaar, et stabiliatur, et ponatur ibi super basem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Et conversus sum, et levavi oculos meos, et vidi: et ecce quatuor quadrigæ egredientes de medio duorum montium: et montes, montes ærei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'In quadriga prima equi rufi, et in quadriga secunda equi nigri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'et in quadriga tertia equi albi, et in quadriga quarta equi varii et fortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Et respondi, et dixi ad angelum qui loquebatur in me: Quid sunt hæc, domine mi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Et respondit angelus, et ait ad me: Isti sunt quatuor venti cæli, qui egrediuntur ut stent coram Dominatore omnis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'In qua erant equi nigri, egrediebantur in terram aquilonis: et albi egressi sunt post eos, et varii egressi sunt ad terram austri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Qui autem erant robustissimi, exierunt, et quærebant ire et discurrere per omnem terram. Et dixit: Ite, perambulate terram: et perambulaverunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Et vocavit me, et locutus est ad me, dicens: Ecce qui egrediuntur in terram aquilonis, requiescere fecerunt spiritum meum in terra aquilonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Et factum est verbum Domini ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Sume a transmigratione, ab Holdai, et a Tobia, et ab Idaia: et venies tu in die illa, et intrabis domum Josiæ filii Sophoniæ, qui venerunt de Babylone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Et sumes aurum et argentum, et facies coronas, et pones in capite Jesu filii Josedec, sacerdotis magni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'et loqueris ad eum, dicens: Hæc ait Dominus exercituum, dicens: Ecce vir, Oriens nomen ejus, et subter eum orietur, et ædificabit templum Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Et ipse exstruet templum Domino: et ipse portabit gloriam, et sedebit, et dominabitur super solio suo: et erit sacerdos super solio suo, et consilium pacis erit inter illos duos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Et coronæ erunt Helem, et Tobiæ, et Idaiæ, et Hem filio Sophoniæ, memoriale in templo Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Et qui procul sunt, venient, et ædificabunt in templo Domini: et scietis quia Dominus exercituum misit me ad vos. Erit autem hoc, si auditu audieritis vocem Domini Dei vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Et factum est in anno quarto Darii regis, factum est verbum Domini ad Zachariam, in quarta mensis noni, qui est Casleu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Et miserunt ad domum Dei Sarasar et Rogommelech, et viri qui erant cum eo, ad deprecandam faciem Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'ut dicerent sacerdotibus domus Domini exercituum, et prophetis, loquentes: Numquid flendum est mihi in quinto mense, vel sanctificare me debeo, sicut jam feci multis annis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Et factum est verbum Domini exercituum ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Loquere ad omnem populum terræ, et ad sacerdotes, dicens: Cum jejunaretis, et plangeretis in quinto et septimo per hos septuaginta annos, numquid jejunium jejunastis mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'et cum comedistis et bibistis, numquid non vobis comedistis et vobismetipsis bibistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'numquid non sunt verba quæ locutus est Dominus in manu prophetarum priorum, cum adhuc Jerusalem habitaretur ut esset opulenta, ipsa et urbes in circuitu ejus, et ad austrum, et in campestribus habitaretur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Et factum est verbum Domini ad Zachariam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Hæc ait Dominus exercituum, dicens: Judicium verum judicate, et misericordiam et miserationes facite, unusquisque cum fratre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Et viduam, et pupillum, et advenam, et pauperem nolite calumniari: et malum vir fratri suo non cogitet in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Et noluerunt attendere, et averterunt scapulam recedentem, et aures suas aggravaverunt ne audirent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et cor suum posuerunt ut adamantem, ne audirent legem, et verba quæ misit Dominus exercituum in spiritu suo per manum prophetarum priorum: et facta est indignatio magna a Domino exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Et factum est sicut locutus est, et non audierunt: sic clamabunt et non exaudiam, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Et dispersi eos per omnia regna quæ nesciunt: et terra desolata est ab eis, eo quod non esset transiens et revertens: et posuerunt terram desiderabilem in desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Et factum est verbum Domini exercituum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Hæc dicit Dominus exercituum: Zelatus sum Sion zelo magno, et indignatione magna zelatus sum eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Hæc dicit Dominus exercituum: Reversus sum ad Sion, et habitabo in medio Jerusalem: et vocabitur Jerusalem civitas veritatis, et mons Domini exercituum mons sanctificatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Hæc dicit Dominus exercituum: Adhuc habitabunt senes et anus in plateis Jerusalem, et viri baculus in manu ejus præ multitudine dierum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Et plateæ civitatis complebuntur infantibus et puellis, ludentibus in plateis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Hæc dicit Dominus exercituum: Si videbitur difficile in oculis reliquiarum populi hujus in diebus illis, numquid in oculis meis difficile erit? dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Hæc dicit Dominus exercituum: Ecce ego salvabo populum meum de terra orientis et de terra occasus solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et adducam eos, et habitabunt in medio Jerusalem: et erunt mihi in populum, et ego ero eis in Deum, in veritate et in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Hæc dicit Dominus exercituum: Confortentur manus vestræ, qui auditis in his diebus sermones istos per os prophetarum, in die qua fundata est domus Domini exercituum, ut templum ædificaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Siquidem ante dies illos merces hominum non erat, nec merces jumentorum erat: neque introëunti, neque exeunti erat pax præ tribulatione: et dimisi omnes homines, unumquemque contra proximum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Nunc autem non juxta dies priores ego faciam reliquiis populi hujus, dicit Dominus exercituum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'sed semen pacis erit: vinea dabit fructum suum, et terra dabit germen suum, et cæli dabunt rorem suum: et possidere faciam reliquias populi hujus universa hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Et erit: sicut eratis maledictio in gentibus, domus Juda et domus Israël, sic salvabo vos, et eritis benedictio. Nolite timere; confortentur manus vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Quia hæc dicit Dominus exercituum: Sicut cogitavi ut affligerem vos, cum ad iracundiam provocassent patres vestri me, dicit Dominus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'et non sum misertus: sic conversus cogitavi, in diebus istis, ut benefaciam domui Juda et Jerusalem. Nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Hæc sunt ergo verba quæ facietis: loquimini veritatem unusquisque cum proximo suo: veritatem et judicium pacis judicate in portis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Et unusquisque malum contra amicum suum ne cogitetis in cordibus vestris, et juramentum mendax ne diligatis: omnia enim hæc sunt quæ odi, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Et factum est verbum Domini exercituum ad me, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Hæc dicit Dominus exercituum: Jejunium quarti, et jejunium quinti, et jejunium septimi, et jejunium decimi erit domui Juda in gaudium et lætitiam et in solemnitates præclaras. Veritatem tantum et pacem diligite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Hæc dicit Dominus exercituum, usquequo veniant populi et habitent in civitatibus multis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'et vadant habitatores, unus ad alterum, dicentes: Eamus, et deprecemur faciem Domini, et quæramus Dominum exercituum: vadam etiam ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Et venient populi multi, et gentes robustæ, ad quærendum Dominum exercituum in Jerusalem, et deprecandam faciem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Hæc dicit Dominus exercituum: In diebus illis, in quibus apprehendent decem homines ex omnibus linguis gentium, et apprehendent fimbriam viri Judæi, dicentes: Ibimus vobiscum: audivimus enim quoniam Deus vobiscum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Onus verbi Domini in terra Hadrach et Damasci requiei ejus, quia Domini est oculus hominis et omnium tribuum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Emath quoque in terminis ejus, et Tyrus, et Sidon: assumpserunt quippe sibi sapientiam valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Et ædificavit Tyrus munitionem suam, et coacervavit argentum quasi humum, et aurum ut lutum platearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Ecce Dominus possidebit eam: et percutiet in mari fortitudinem ejus, et hæc igni devorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Videbit Ascalon, et timebit, et Gaza, et dolebit nimis, et Accaron, quoniam confusa est spes ejus: et peribit rex de Gaza, et Ascalon non habitabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Et sedebit separator in Azoto, et disperdam superbiam Philisthinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Et auferam sanguinem ejus de ore ejus, et abominationes ejus de medio dentium ejus: et relinquetur etiam ipse Deo nostro, et erit quasi dux in Juda, et Accaron quasi Jebusæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Et circumdabo domum meam ex his qui militant mihi euntes et revertentes: et non transibit super eos ultra exactor, quia nunc vidi in oculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Exsulta satis, filia Sion; jubila, filia Jerusalem: ecce rex tuus veniet tibi justus, et salvator: ipse pauper, et ascendens super asinam et super pullum filium asinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Et disperdam quadrigam ex Ephraim, et equum de Jerusalem, et dissipabitur arcus belli: et loquetur pacem gentibus, et potestas ejus a mari usque ad mare, et a fluminibus usque ad fines terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Tu quoque in sanguine testamenti tui emisisti vinctos tuos de lacu in quo non est aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Convertimini ad munitionem, vincti spei: hodie quoque annuntians duplicia reddam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Quoniam extendi mihi Judam quasi arcum: implevi Ephraim: et suscitabo filios tuos, Sion, super filios tuos, Græcia: et ponam te quasi gladium fortium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Et Dominus Deus super eos videbitur, et exibit ut fulgur jaculum ejus: et Dominus Deus in tuba canet, et vadet in turbine austri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Dominus exercituum proteget eos: et devorabunt, et subjicient lapidibus fundæ: et bibentes inebriabuntur quasi a vino, et replebuntur ut phialæ, et quasi cornua altaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Et salvabit eos Dominus Deus eorum in die illa, ut gregem populi sui, quia lapides sancti elevabuntur super terram ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Quid enim bonum ejus est, et quid pulchrum ejus, nisi frumentum electorum, et vinum germinans virgines?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Petite a Domino pluviam in tempore serotino, et Dominus faciet nives: et pluviam imbris dabit eis, singulis herbam in agro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Quia simulacra locuta sunt inutile, et divini viderunt mendacium: et somniatores locuti sunt frustra, vane consolabantur: idcirco abducti sunt quasi grex: affligentur, quia non est eis pastor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Super pastores iratus est furor meus, et super hircos visitabo: quia visitavit Dominus exercituum gregem suum, domum Juda, et posuit eos quasi equum gloriæ suæ in bello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Ex ipso angulus, ex ipso paxillus, ex ipso arcus prælii, ex ipso egredietur omnis exactor simul.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Et erunt quasi fortes conculcantes lutum viarum in prælio, et bellabunt, quia Dominus cum eis: et confundentur ascensores equorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Et confortabo domum Juda, et domum Joseph salvabo: et convertam eos, quia miserebor eorum: et erunt sicut fuerunt quando non projeceram eos: ego enim Dominus Deus eorum, et exaudiam eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Et erunt quasi fortes Ephraim, et lætabitur cor eorum quasi a vino: et filii eorum videbunt, et lætabuntur, et exsultabit cor eorum in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Sibilabo eis, et congregabo illos, quia redemi eos: et multiplicabo eos sicut ante fuerant multiplicati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Et seminabo eos in populis, et de longe recordabuntur mei: et vivent cum filiis suis, et revertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Et reducam eos de terra \'gypti, et de Assyriis congregabo eos, et ad terram Galaad et Libani adducam eos, et non invenietur eis locus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'et transibit in maris freto, et percutiet in mari fluctus, et confundentur omnia profunda fluminis: et humiliabitur superbia Assur, et sceptrum \'gypti recedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Confortabo eos in Domino, et in nomine ejus ambulabunt, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Aperi, Libane, portas tuas, et comedat ignis cedros tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Ulula, abies, quia cecidit cedrus, quoniam magnifici vastati sunt: ululate, quercus Basan, quoniam succisus est saltus munitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Vox ululatus pastorum, quia vastata est magnificentia eorum: vox rugitus leonum, quoniam vastata est superbia Jordanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Hæc dicit Dominus Deus meus: Pasce pecora occisionis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'quæ qui possederant occidebant, et non dolebant, et vendebant ea, dicentes: Benedictus Dominus! divites facti sumus: et pastores eorum non parcebant eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Et ego non parcam ultra super habitantes terram, dicit Dominus: ecce ego tradam homines, unumquemque in manu proximi sui, et in manu regis sui: et concident terram, et non eruam de manu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Et pascam pecus occisionis propter hoc, o pauperes gregis! et assumpsi mihi duas virgas: unam vocavi Decorem, et alteram vocavi Funiculum: et pavi gregem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Et succidi tres pastores in mense uno, et contracta est anima mea in eis, siquidem et anima eorum variavit in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Et dixi: Non pascam vos: quod moritur, moriatur, et quod succiditur, succidatur: et reliqui devorent unusquisque carnem proximi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Et tuli virgam meam quæ vocabatur Decus, et abscidi eam, ut irritum facerem fœdus meum quod percussi cum omnibus populis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Et in irritum deductum est in die illa: et cognoverunt sic pauperes gregis, qui custodiunt mihi, quia verbum Domini est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Et dixi ad eos: Si bonum est in oculis vestris, afferte mercedem meam: et si non, quiescite. Et appenderunt mercedem meam triginta argenteos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Et dixit Dominus ad me: Projice illud ad statuarium, decorum pretium quo appretiatus sum ab eis. Et tuli triginta argenteos, et projeci illos in domum Domini, ad statuarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Et præcidi virgam meam secundam, quæ appellabatur Funiculus, ut dissolverem germanitatem inter Judam et Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Et dixit Dominus ad me: Adhuc sume tibi vasa pastoris stulti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Quia ecce ego suscitabo pastorem in terra, qui derelicta non visitabit, dispersum non quæret, et contritum non sanabit, et id quod stat non enutriet, et carnes pinguium comedet, et ungulas eorum dissolvet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'O pastor, et idolum derelinquens gregem: gladius super brachium ejus, et super oculum dextrum ejus: brachium ejus ariditate siccabitur, et oculus dexter ejus tenebrescens obscurabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Onus verbi Domini super Israël. Dicit Dominus extendens cælum, et fundans terram, et fingens spiritum hominis in eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Ecce ego ponam Jerusalem superliminare crapulæ omnibus populis in circuitu: sed et Juda erit in obsidione contra Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Et erit: in die illa ponam Jerusalem lapidem oneris cunctis populis: omnes qui levabunt eam concisione lacerabuntur, et colligentur adversus eam omnia regna terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'In die illa, dicit Dominus, percutiam omnem equum in stuporem, et ascensorem ejus in amentiam: et super domum Juda aperiam oculos meos, et omnem equum populorum percutiam cæcitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Et dicent duces Juda in corde suo: Confortentur mihi habitatores Jerusalem in Domino exercituum, Deo eorum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'In die illa ponam duces Juda sicut caminum ignis in lignis, et sicut facem ignis in fœno: et devorabunt ad dexteram et ad sinistram omnes populos in circuitu, et habitabitur Jerusalem rursus in loco suo in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Et salvabit Dominus tabernacula Juda, sicut in principio, ut non magnifice glorietur domus David, et gloria habitantium Jerusalem contra Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'In die illa proteget Dominus habitatores Jerusalem: et erit qui offenderit ex eis in die illa quasi David, et domus David quasi Dei, sicut angelus Domini in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Et erit in die illa: quæram conterere omnes gentes quæ veniunt contra Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Et effundam super domum David et super habitatores Jerusalem spiritum gratiæ et precum: et aspicient ad me quem confixerunt, et plangent eum planctu quasi super unigenitum, et dolebunt super eum, ut doleri solet in morte primogeniti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'In die illa, magnus erit planctus in Jerusalem, sicut planctus Adadremmon in campo Mageddon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Et planget terra: familiæ et familiæ seorsum: familiæ domus David seorsum, et mulieres eorum seorsum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'familiæ domus Nathan seorsum, et mulieres eorum seorsum: familiæ domus Levi seorsum, et mulieres eorum seorsum: familiæ Semei seorsum, et mulieres eorum seorsum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'omnes familiæ reliquæ, familiæ et familiæ seorsum, et mulieres eorum seorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'In die illa erit fons patens domui David et habitantibus Jerusalem, in ablutionem peccatoris et menstruatæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Et erit in die illa, dicit Dominus exercituum: disperdam nomina idolorum de terra, et non memorabuntur ultra: et pseudoprophetas, et spiritum immundum auferam de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Et erit: cum prophetaverit quispiam ultra, dicent ei pater ejus et mater ejus, qui genuerunt eum: Non vives, quia mendacium locutus es in nomine Domini: et configent eum pater ejus et mater ejus, genitores ejus, cum prophetaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Et erit: in die illa confundentur prophetæ, unusquisque ex visione sua cum prophetaverit: nec operientur pallio saccino, ut mentiantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'sed dicet: Non sum propheta: homo agricola ego sum, quoniam Adam exemplum meum ab adolescentia mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Et dicetur ei: Quid sunt plagæ istæ in medio manuum tuarum? Et dicet: His plagatus sum in domo eorum qui diligebant me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Framea, suscitare super pastorem meum, et super virum cohærentem mihi, dicit Dominus exercituum: percute pastorem, et dispergentur oves: et convertam manum meam ad parvulos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Et erunt in omni terra, dicit Dominus: partes duæ in ea dispergentur, et deficient: et tertia pars relinquetur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Et ducam tertiam partem per ignem, et uram eos sicut uritur argentum, et probabo eos sicut probatur aurum. Ipse vocabit nomen meum, et ego exaudiam eum. Dicam: Populus meus es: et ipse dicet: Dominus Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Ecce venient dies Domini, et dividentur spolia tua in medio tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Et congregabo omnes gentes ad Jerusalem in prælium: et capietur civitas, et vastabuntur domus, et mulieres violabuntur: et egredietur media pars civitatis in captivitatem, et reliquum populi non auferetur ex urbe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Et egredietur Dominus, et præliabitur contra gentes illas, sicut præliatus est in die certaminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Et stabunt pedes ejus in die illa super montem Olivarum, qui est contra Jerusalem ad orientem: et scindetur mons Olivarum ex media parte sui ad orientem et ad occidentem, prærupto grandi valde: et separabitur medium montis ad aquilonem, et medium ejus ad meridiem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Et fugietis ad vallem montium eorum, quoniam conjungetur vallis montium usque ad proximum: et fugietis sicut fugistis a facie terræmotus in diebus Oziæ regis Juda: et veniet Dominus Deus meus, omnesque sancti cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Et erit in die illa: non erit lux, sed frigus et gelu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Et erit dies una quæ nota est Domino, non dies neque nox: et in tempore vesperi erit lux.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Et erit in die illa: exibunt aquæ vivæ de Jerusalem: medium earum ad mare orientale, et medium earum ad mare novissimum: in æstate et in hieme erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Et erit Dominus rex super omnem terram: in die illa erit Dominus unus, et erit nomen ejus unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Et revertetur omnis terra usque ad desertum, de colle Remmon ad austrum Jerusalem: et exaltabitur, et habitabit in loco suo, a porta Benjamin usque ad locum portæ prioris, et usque ad portam angulorum, et a turre Hananeel usque ad torcularia regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Et habitabunt in ea, et anathema non erit amplius, sed sedebit Jerusalem secura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Et hæc erit plaga qua percutiet Dominus omnes gentes quæ pugnaverunt adversus Jerusalem: tabescet caro uniuscujusque stantis super pedes suos: et oculi ejus contabescent in foraminibus suis, et lingua eorum contabescet in ore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'In die illa erit tumultus Domini magnus in eis: et apprehendet vir manum proximi sui, et conseretur manus ejus super manum proximi sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Sed et Judas pugnabit adversus Jerusalem: et congregabuntur divitiæ omnium gentium in circuitu, aurum, et argentum, et vestes multæ satis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Et sic erit ruina equi, et muli, et cameli, et asini, et omnium jumentorum quæ fuerint in castris illis, sicut ruina hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Et omnes qui reliqui fuerint de universis gentibus quæ venerunt contra Jerusalem, ascendent ab anno in annum ut adorent regem, Dominum exercituum, et celebrent festivitatem tabernaculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Et erit: qui non ascenderit de familiis terræ ad Jerusalem ut adoret regem, Dominum exercituum, non erit super eos imber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Quod etsi familia \'gypti non ascenderit et non venerit, nec super eos erit: sed erit ruina, qua percutiet Dominus omnes gentes quæ non ascenderint ad celebrandam festivitatem tabernaculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Hoc erit peccatum \'gypti, et hoc peccatum omnium gentium quæ non ascenderint ad celebrandam festivitatem tabernaculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'In die illa, erit quod super frenum equi est, sanctum Domino: et erunt lebetes in domo Domini quasi phialæ coram altari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Et erit omnis lebes in Jerusalem et in Juda sanctificatus Domino exercituum: et venient omnes immolantes, et sument ex eis, et coquent in eis: et non erit mercator ultra in domo Domini exercituum in die illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Onus verbi Domini ad Israël in manu Malachiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Dilexi vos, dicit Dominus, et dixistis: In quo dilexisti nos? Nonne frater erat Esau Jacob? dicit Dominus: et dilexi Jacob,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Esau autem odio habui, et posui montes ejus in solitudinem, et hæreditatem ejus in dracones deserti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Quod si dixerit Idumæa: Destructi sumus, sed revertentes ædificabimus quæ destructa sunt: hæc dicit Dominus exercituum: Isti ædificabunt, et ego destruam: et vocabuntur termini impietatis, et populus cui iratus est Dominus usque in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Et oculi vestri videbunt, et vos dicetis: Magnificetur Dominus super terminum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Filius honorat patrem, et servus dominum suum. Si ergo pater ego sum, ubi est honor meus? et si Dominus ego sum, ubi est timor meus? dicit Dominus exercituum. Ad vos, o sacerdotes, qui despicitis nomen meum, et dixistis: In quo despeximus nomen tuum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Offertis super altare meum panem pollutum, et dicitis: In quo polluimus te? in eo quod dicitis: Mensa Domini despecta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Si offeratis cæcum ad immolandum, nonne malum est? et si offeratis claudum et languidum, nonne malum est? offer illud duci tuo, si placuerit ei, aut si susceperit faciem tuam, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Et nunc deprecamini vultum Dei ut misereatur vestri (de manu enim vestra factum est hoc), si quomodo suscipiat facies vestras, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Quis est in vobis qui claudat ostia, et incendat altare meum gratuito? non est mihi voluntas in vobis, dicit Dominus exercituum, et munus non suscipiam de manu vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Ab ortu enim solis usque ad occasum, magnum est nomen meum in gentibus, et in omni loco sacrificatur: et offertur nomini meo oblatio munda, quia magnum est nomen meum in gentibus, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Et vos polluistis illud in eo quod dicitis: Mensa Domini contaminata est, et quod superponitur contemptibilis est, cum igne qui illud devorat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Et dixistis: Ecce de labore, et exsufflastis illud, dicit Dominus exercituum: et intulistis de rapinis claudum et languidum, et intulistis munus: numquid suscipiam illud de manu vestra? dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Maledictus dolosus qui habet in grege suo masculum, et votum faciens immolat debile Domino: quia rex magnus ego, dicit Dominus exercituum, et nomen meum horribile in gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Et nunc ad vos mandatum hoc, o sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Si nolueritis audire, et si nolueritis ponere super cor, ut detis gloriam nomini meo, ait Dominus exercituum, mittam in vos egestatem, et maledicam benedictionibus vestris, et maledicam illis, quoniam non posuistis super cor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Ecce ego projiciam vobis brachium, et dispergam super vultum vestrum stercus solemnitatum vestrarum, et assumet vos secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Et scietis quia misi ad vos mandatum istud, ut esset pactum meum cum Levi, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Pactum meum fuit cum eo vitæ et pacis: et dedi ei timorem, et timuit me, et a facie nominis mei pavebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Lex veritatis fuit in ore ejus, et iniquitas non est inventa in labiis ejus: in pace et in æquitate ambulavit mecum, et multos avertit ab iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Labia enim sacerdotis custodient scientiam, et legem requirent ex ore ejus, quia angelus Domini exercituum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Vos autem recessistis de via, et scandalizastis plurimos in lege: irritum fecistis pactum Levi, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Propter quod et ego dedi vos contemptibiles, et humiles omnibus populis, sicut non servastis vias meas, et accepistis faciem in lege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Numquid non pater unus omnium nostrum? numquid non Deus unus creavit nos? quare ergo despicit unusquisque nostrum fratrem suum, violans pactum patrum nostrorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Transgressus est Juda, et abominatio facta est in Israël et in Jerusalem, quia contaminavit Juda sanctificationem Domini, quam dilexit, et habuit filiam dei alieni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Disperdet Dominus virum qui fecerit hoc, magistrum et discipulum, de tabernaculis Jacob, et offerentem munus Domino exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Et hoc rursum fecistis: operiebatis lacrimis altare Domini, fletu et mugitu, ita ut non respiciam ultra ad sacrificium, nec accipiam placabile quid de manu vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Et dixistis: Quam ob causam? Quia Dominus testificatus est inter te et uxorem pubertatis tuæ, quam tu despexisti: et hæc particeps tua, et uxor fœderis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Nonne unus fecit, et residuum spiritus ejus est? et quid unus quærit, nisi semen Dei? custodite ergo spiritum vestrum, et uxorem adolescentiæ tuæ noli despicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Cum odio habueris, dimitte, dicit Dominus Deus Israël: operiet autem iniquitas vestimentum ejus, dicit Dominus exercituum. Custodite spiritum vestrum, et nolite despicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Laborare fecistis Dominum in sermonibus vestris, et dixistis: In quo eum fecimus laborare? In eo quod dicitis: Omnis qui facit malum bonus est in conspectu Domini, et tales ei placent: aut certe ubi est Deus judicii?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Ecce ego mitto angelum meum, et præparabit viam ante faciem meam: et statim veniet ad templum suum Dominator quem vos quæritis, et angelus testamenti quem vos vultis. Ecce venit, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Et quis poterit cogitare diem adventus ejus, et quis stabit ad videndum eum? ipse enim quasi ignis conflans, et quasi herba fullonum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'et sedebit conflans, et emundans argentum: et purgabit filios Levi, et colabit eos quasi aurum et quasi argentum, et erunt Domino offerentes sacrificia in justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Et placebit Domino sacrificium Juda et Jerusalem, sicut dies sæculi, et sicut anni antiqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Et accedam ad vos in judicio, et ero testis velox maleficis, et adulteris, et perjuris, et qui calumniantur mercedem mercenarii, viduas et pupillos, et opprimunt peregrinum, nec timuerunt me, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Ego enim Dominus, et non mutor: et vos filii Jacob, non estis consumpti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'A diebus enim patrum vestrorum recessistis a legitimis meis, et non custodistis: revertimini ad me, et revertar ad vos, dicit Dominus exercituum. Et dixistis: In quo revertemur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Si affliget homo Deum, quia vos configitis me? Et dixistis: In quo configimus te? In decimis et in primitiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Et in penuria vos maledicti estis, et me vos configitis gens tota.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Inferte omnem decimam in horreum, et sit cibus in domo mea: et probate me super hoc, dicit Dominus: si non aperuero vobis cataractas cæli, et effudero vobis benedictionem usque ad abundantiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'et increpabo pro vobis devorantem, et non corrumpet fructum terræ vestræ, nec erit sterilis vinea in agro, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Et beatos vos dicent omnes gentes: eritis enim vos terra desiderabilis, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Invaluerunt super me verba vestra, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Et dixistis: Quid locuti sumus contra te? Dixistis: Vanus est qui servit Deo: et quod emolumentum quia custodivimus præcepta ejus, et quia ambulavimus tristes coram Domino exercituum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Ergo nunc beatos dicimus arrogantes: siquidem ædificati sunt facientes impietatem, et tentaverunt Deum, et salvi facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Tunc locuti sunt timentes Dominum, unusquisque cum proximo suo: et attendit Dominus, et audivit, et scriptus est liber monumenti coram eo timentibus Dominum, et cogitantibus nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Et erunt mihi, ait Dominus exercituum, in die qua ego facio, in peculium: et parcam eis, sicut parcit vir filio suo servienti sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Et convertemini, et videbitis quid sit inter justum et impium, et inter servientem Deo et non servientem ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Ecce enim dies veniet succensa quasi caminus: et erunt omnes superbi et omnes facientes impietatem stipula: et inflammabit eos dies veniens, dicit Dominus exercituum, quæ non derelinquet eis radicem et germen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Et orietur vobis timentibus nomen meum sol justitiæ, et sanitas in pennis ejus: et egrediemini, et salietis sicut vituli de armento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Et calcabitis impios, cum fuerint cinis sub planta pedum vestrorum, in die qua ego facio, dicit Dominus exercituum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mementote legis Moysi servi mei, quam mandavi ei in Horeb ad omnem Israël, præcepta et judicia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Ecce ego mittam vobis Eliam prophetam, antequam veniat dies Domini magnus et horribilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Et convertet cor patrum ad filios, et cor filiorum ad patres eorum: ne forte veniam, et percutiam terram anathemate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Et factum est, postquam percussit Alexander Philippi Macedo, qui primus regnavit in Græcia, egressus de terra Cethim, Darium regem Persarum et Medorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'constituit prælia multa, et obtinuit omnium munitiones, et interfecit reges terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'et pertransiit usque ad fines terræ: et accepit spolia multitudinis gentium, et siluit terra in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Et congregavit virtutem, et exercitum fortem nimis: et exaltatum est, et elevatum cor ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'et obtinuit regiones gentium, et tyrannos: et facti sunt illi in tributum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Et post hæc decidit in lectum, et cognovit quia moreretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Et vocavit pueros suos nobiles, qui secum erant nutriti a juventute: et divisit illis regnum suum, cum adhuc viveret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Et regnavit Alexander annis duodecim, et mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Et obtinuerunt pueri ejus regnum, unusquisque in loco suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'et imposuerunt omnes sibi diademata post mortem ejus, et filii eorum post eos annis multis, et multiplicata sunt mala in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Et exiit ex eis radix peccatrix, Antiochus illustris, filius Antiochi regis, qui fuerat Romæ obses: et regnavit in anno centesimo trigesimo septimo regni Græcorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'In diebus illis, exierunt ex Israël filii iniqui, et suaserunt multis, dicentes: Eamus, et disponamus testamentum cum gentibus, quæ circa nos sunt: quia ex quo recessimus ab eis, invenerunt nos multa mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Et bonus visus est sermo in oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Et destinaverunt aliqui de populo, et abierunt ad regem: et dedit illis potestatem ut facerent justitiam gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Et ædificaverunt gymnasium in Jerosolymis secundum leges nationum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'et fecerunt sibi præputia, et recesserunt a testamento sancto, et juncti sunt nationibus, et venundati sunt ut facerent malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Et paratum est regnum in conspectu Antiochi, et cœpit regnare in terra \'gypti ut regnaret super duo regna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Et intravit in \'gyptum in multitudine gravi, in curribus, et elephantis, et equitibus, et copiosa navium multitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'et constituit bellum adversus Ptolemæum regem \'gypti, et veritus est Ptolemæus a facie ejus, et fugit, et ceciderunt vulnerati multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Et comprehendit civitates munitas in terra \'gypti, et accepit spolia terræ \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Et convertit Antiochus, postquam percussit \'gyptum in centesimo et quadragesimo tertio anno: et ascendit ad Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'et ascendit Jerosolymam in multitudine gravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Et intravit in sanctificationem cum superbia, et accepit altare aureum, et candelabrum luminis, et universa vasa ejus, et mensam propositionis, et libatoria, et phialas, et mortariola aurea, et velum, et coronas, et ornamentum aureum, quod in facie templi erat: et comminuit omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Et accepit argentum, et aurum, et vasa concupiscibilia: et accepit thesauros occultos, quos invenit: et sublatis omnibus, abiit in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Et fecit cædem hominum, et locutus est in superbia magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Et factus est planctus magnus in Israël, et in omni loco eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'et ingemuerunt principes et seniores; virgines et juvenes infirmati sunt: et speciositas mulierum immutata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Omnis maritus sumpsit lamentum, et quæ sedebant in thoro maritali, lugebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'et commota est terra super habitantes in ea, et universa domus Jacob induit confusionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Et post duos annos dierum, misit rex principem tributorum in civitates Juda, et venit Jerusalem cum turba magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Et locutus est ad eos verba pacifica in dolo: et crediderunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Et irruit super civitatem repente, et percussit eam plaga magna, et perdidit populum multum ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 33, 'Et accepit spolia civitatis: et succendit eam igni, et destruxit domos ejus, et muros ejus in circuitu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 34, 'et captivas duxerunt mulieres, et natos et pecora possederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 35, 'Et ædificaverunt civitatem David muro magno et firmo, et turribus firmis, et facta est illis in arcem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 36, 'et posuerunt illic gentem peccatricem viros iniquos, et convaluerunt in ea: et posuerunt arma, et escas, et congregaverunt spolia Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 37, 'et reposuerunt illic: et facti sunt in laqueum magnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 38, 'Et factum est hoc ad insidias sanctificationi, et in diabolum malum in Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 39, 'et effuderunt sanguinem innocentem per circuitum sanctificationis, et contaminaverunt sanctificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 40, 'Et fugerunt habitatores Jerusalem propter eos, et facta est habitatio exterorum, et facta est extera semini suo, et nati ejus reliquerunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 41, 'Sanctificatio ejus desolata est sicut solitudo; dies festi ejus conversi sunt in luctum, sabbata ejus in opprobrium, honores ejus in nihilum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 42, 'Secundum gloriam ejus multiplicata est ignominia ejus, et sublimitas ejus conversa est in luctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 43, 'Et scripsit rex Antiochus omni regno suo ut esset omnis populus unus: et relinqueret unusquisque legem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 44, 'Et consenserunt omnes gentes secundum verbum regis Antiochi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 45, 'et multi ex Israël consenserunt servituti ejus, et sacrificaverunt idolis, et coinquinaverunt sabbatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 46, 'Et misit rex libros per manus nuntiorum in Jerusalem, et in omnes civitates Juda, ut sequerentur leges gentium terræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 47, 'et prohiberent holocausta et sacrificia, et placationes fieri in templo Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 48, 'et prohiberent celebrari sabbatum, et dies solemnes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 49, 'et jussit coinquinari sancta, et sanctum populum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 50, 'Et jussit ædificari aras, et templa, et idola, et immolari carnes suillas, et pecora communia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 51, 'et relinquere filios suos incircumcisos, et coinquinari animas eorum in omnibus immundis, et abominationibus, ita ut obliviscerentur legem, et immutarent omnes justificationes Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 52, 'et quicumque non fecissent secundum verbum regis Antiochi, morerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 53, 'Secundum omnia verba hæc scripsit omni regno suo: et præposuit principes populo, qui hæc fieri cogerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 54, 'Et jusserunt civitatibus Juda sacrificare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 55, 'Et congregati sunt multi de populo ad eos qui dereliquerant legem Domini, et fecerunt mala super terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 56, 'et effugaverunt populum Israël in abditis, et in absconditis fugitivorum locis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 57, 'Die quintadecima mensis Casleu, quinto et quadragesimo et centesimo anno, ædificavit rex Antiochus abominandum idolum desolationis super altare Dei, et per universas civitates Juda in circuitu ædificaverunt aras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 58, 'et ante januas domorum et in plateis incendebant thura, et sacrificabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 59, 'et libros legis Dei combusserunt igni, scindentes eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 60, 'et apud quemcumque inveniebantur libri testamenti Domini, et quicumque observabat legem Domini, secundum edictum regis trucidabant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 61, 'In virtute sua faciebant hæc populo Israël, qui inveniebatur in omni mense et mense in civitatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 62, 'Et quinta et vigesima die mensis sacrificabant super aram, quæ erat contra altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 63, 'Et mulieres, quæ circumcidebant filios suos, trucidabantur secundum jussum regis Antiochi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 64, 'et suspendebant pueros a cervicibus per universas domos eorum: et eos, qui circumciderant illos, trucidabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 65, 'Et multi de populo Israël definierunt apud se, ut non manducarent immunda: et elegerunt magis mori, quam cibis coinquinari immundis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 66, 'et noluerunt infringere legem Dei sanctam, et trucidati sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 67, 'et facta est ira magna super populum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'In diebus illis surrexit Mathathias filius Joannis filii Simeonis, sacerdos ex filiis Joarib, ab Jerusalem, et consedit in monte Modin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'et habebat filios quinque, Joannem, qui cognominabatur Gaddis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'et Simonem, qui cognominabatur Thasi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'et Judam, qui vocabatur Machabæus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'et Eleazarum, qui cognominabatur Abaron: et Jonathan, qui cognominabatur Apphus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'hi viderunt mala, quæ fiebant in populo Juda, et in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Et dixit Mathathias: Væ mihi! ut quid natus sum videre contritionem populi mei, et contritionem civitatis sanctæ, et sedere illic, cum datur in manibus inimicorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Sancta in manu extraneorum facta sunt: templum ejus sicut homo ignobilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Vasa gloriæ ejus captiva abducta sunt: trucidati sunt senes ejus in plateis, et juvenes ejus ceciderunt in gladio inimicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Quæ gens non hæreditavit regnum ejus et non obtinuit spolia ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Omnis compositio ejus ablata est. Quæ erat libera, facta est ancilla.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Et ecce sancta nostra, et pulchritudo nostra, et claritas nostra desolata est, et coinquinaverunt ea gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Quo ergo nobis adhuc vivere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Et scidit vestimenta sua Mathathias, et filii ejus: et operuerunt se ciliciis, et planxerunt valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Et venerunt illuc qui missi erant a rege Antiocho, ut cogerent eos, qui confugerant in civitatem Modin, immolare, et accendere thura, et a lege Dei discedere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Et multi de populo Israël consentientes accesserunt ad eos: sed Mathathias et filii ejus constanter steterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Et respondentes qui missi erant ab Antiocho, dixerunt Mathathiæ: Princeps, et clarissimus et magnus es in hac civitate, et ornatus filiis et fratribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'ergo accede prior, et fac jussum regis, sicut fecerunt omnes gentes, et viri Juda, et qui remanserunt in Jerusalem: et eris tu, et filii tui, inter amicos regis, et amplificatus auro, et argento, et muneribus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Et respondit Mathathias, et dixit magna voce: Etsi omnes gentes regi Antiocho obediunt, ut discedat unusquisque a servitute legis patrum suorum, et consentiat mandatis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'ego et filii mei, et fratres mei, obediemus legi patrum nostrorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'propitius sit nobis Deus: non est nobis utile relinquere legem, et justitias Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'non audiemus verba regis Antiochi, nec sacrificabimus transgredientes legis nostræ mandata, ut eamus altera via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Et ut cessavit loqui verba hæc, accessit quidam Judæus in omnium oculis sacrificare idolis super aram in civitate Modin, secundum jussum regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'et vidit Mathathias, et doluit, et contremuerunt renes ejus, et accensus est furor ejus secundum judicium legis, et insiliens trucidavit eum super aram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'sed et virum, quem rex Antiochus miserat, qui cogebat immolare, occidit in ipso tempore, et aram destruxit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'et zelatus est legem, sicut fecit Phinees Zamri filio Salomi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Et exclamavit Mathathias voce magna in civitate, dicens: Omnis qui zelum habet legis, statuens testamentum, exeat post me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Et fugit ipse, et filii ejus in montes, et reliquerunt quæcumque habebant in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Tunc descenderunt multi quærentes judicium, et justitiam, in desertum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 30, 'et sederunt ibi ipsi, et filii eorum, et mulieres eorum, et pecora eorum: quoniam inundaverunt super eos mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 31, 'Et renuntiatum est viris regis, et exercitui qui erat in Jerusalem civitate David, quoniam discessissent viri quidam, qui dissipaverunt mandatum regis, in loca occulta in deserto, et abiissent post illos multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 32, 'Et statim perrexerunt ad eos, et constituerunt adversus eos prælium in die sabbatorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 33, 'et dixerunt ad eos: Resistitis et nunc adhuc? exite, et facite secundum verbum regis Antiochi, et vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 34, 'Et dixerunt: Non exibimus, neque faciemus verbum regis, ut polluamus diem sabbatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 35, 'Et concitaverunt adversus eos prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 36, 'Et non responderunt eis, nec lapidem miserunt in eos, nec oppilaverunt loca occulta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 37, 'dicentes: Moriamur omnes in simplicitate nostra: et testes erunt super nos cælum et terra, quod injuste perditis nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 38, 'Et intulerunt illis bellum sabbatis: et mortui sunt ipsi, et uxores eorum, et filii eorum, et pecora eorum usque ad mille animas hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 39, 'Et cognovit Mathathias et amici ejus, et luctum habuerunt super eos valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 40, 'Et dixit vir proximo suo: Si omnes fecerimus sicut fratres nostri fecerunt, et non pugnaverimus adversus gentes pro animabus nostris et justificationibus nostris, nunc citius disperdent nos a terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 41, 'Et cogitaverunt in die illa, dicentes: Omnis homo, quicumque venerit ad nos in bello die sabbatorum, pugnemus adversus eum: et non moriemur omnes, sicut mortui sunt fratres nostri in occultis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 42, 'Tunc congregata est ad eos synagoga Assidæorum fortis viribus ex Israël, omnis voluntarius in lege:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 43, 'et omnes, qui fugiebant a malis, additi sunt ad eos, et facti sunt illis ad firmamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 44, 'Et collegerunt exercitum, et percusserunt peccatores in ira sua, et viros iniquos in indignatione sua: et ceteri fugerunt ad nationes, ut evaderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 45, 'Et circuivit Mathathias et amici ejus, et destruxerunt aras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 46, 'et circumciderunt pueros incircumcisos quotquot invenerunt in finibus Israël: et in fortitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 47, 'Et persecuti sunt filios superbiæ, et prosperatum est opus in manibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 48, 'et obtinuerunt legem de manibus gentium, et de manibus regum, et non dederunt cornu peccatori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 49, 'Et appropinquaverunt dies Mathathiæ moriendi, et dixit filiis suis: Nunc confortata est superbia, et castigatio, et tempus eversionis, et ira indignationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 50, 'Nunc ergo, o filii, æmulatores estote legis, et date animas vestras pro testamento patrum vestrorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 51, 'et mementote operum patrum, quæ fecerunt in generationibus suis: et accipietis gloriam magnam, et nomen æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 52, 'Abraham nonne in tentatione inventus est fidelis, et reputatum est ei ad justitiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 53, 'Joseph in tempore angustiæ suæ custodivit mandatum, et factus est dominus \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 54, 'Phinees pater noster, zelando zelum Dei, accepit testamentum sacerdotii æterni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 55, 'Jesus dum implevit verbum, factus est dux in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 56, 'Caleb dum testificatur in ecclesia, accepit hæreditatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 57, 'David in sua misericordia consecutus est sedem regni in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 58, 'Elias, dum zelat zelum legis, receptus est in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 59, 'Ananias et Azarias et Misaël credentes, liberati sunt de flamma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 60, 'Daniel in sua simplicitate liberatus est de ore leonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 61, 'Et ita cogitate per generationem et generationem: quia omnes qui sperant in eum, non infirmantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 62, 'Et a verbis viri peccatoris ne timueritis, quia gloria ejus stercus et vermis est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 63, 'hodie extollitur, et cras non invenietur: quia conversus est in terram suam, et cogitatio ejus periit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 64, 'Vos ergo filii, confortamini, et viriliter agite in lege: quia in ipsa gloriosi eritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 65, 'Et ecce Simon frater vester, scio quod vir consilii est: ipsum audite semper, et ipse erit vobis pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 66, 'Et Judas Machabæus, fortis viribus a juventute sua, sit vobis princeps militiæ, et ipse aget bellum populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 67, 'Et adducetis ad vos omnes factores legis: et vindicate vindictam populi vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 68, 'Retribuite retributionem gentibus, et intendite in præceptum legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 69, 'Et benedixit eos, et appositus est ad patres suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 70, 'Et defunctus est anno centesimo et quadragesimo sexto: et sepultus est a filiis suis in sepulchris patrum suorum in Modin, et planxerunt eum omnis Israël planctu magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Et surrexit Judas, qui vocabatur Machabæus, filius ejus, pro eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'et adjuvabant eum omnes fratres ejus, et universi qui se conjunxerant patri ejus, et præliabantur prælium Israël cum lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Et dilatavit gloriam populo suo, et induit se loricam sicut gigas, et succinxit se arma bellica sua in præliis, et protegebat castra gladio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Similis factus est leoni in operibus suis, et sicut catulus leonis rugiens in venatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Et persecutus est iniquos perscrutans eos: et qui conturbabant populum suum, eos succendit flammis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'et repulsi sunt inimici ejus præ timore ejus, et omnes operarii iniquitatis conturbati sunt: et directa est salus in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Et exacerbabat reges multos, et lætificabat Jacob in operibus suis, et in sæculum memoria ejus in benedictione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Et perambulavit civitates Juda, et perdidit impios ex eis, et avertit iram ab Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Et nominatus est usque ad novissimum terræ, et congregavit pereuntes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Et congregavit Apollonius gentes, et a Samaria virtutem multam et magnam ad bellandum contra Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Et cognovit Judas, et exiit obviam illi: et percussit, et occidit illum: et ceciderunt vulnerati multi, et reliqui fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Et accepit spolia eorum: et gladium Apollonii abstulit Judas, et erat pugnans in eo omnibus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Et audivit Seron princeps exercitus Syriæ, quod congregavit Judas congregationem fidelium, et ecclesiam secum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'et ait: Faciam mihi nomen, et glorificabor in regno, et debellabo Judam, et eos qui cum ipso sunt, qui spernebant verbum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Et præparavit se: et ascenderunt cum eo castra impiorum fortes auxiliarii ut facerent vindictam in filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Et appropinquaverunt usque ad Bethoron: et exivit Judas obviam illi cum paucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Ut autem viderunt exercitum venientem sibi obviam, dixerunt Judæ: Quomodo poterimus pauci pugnare contra multitudinem tantam, et tam fortem, et nos fatigati sumus jejunio hodie?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Et ait Judas: Facile est concludi multos in manus paucorum: et non est differentia in conspectu Dei cæli liberare in multis, et in paucis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'quoniam non in multitudine exercitus victoria belli, sed de cælo fortitudo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Ipsi veniunt ad nos in multitudine contumaci, et superbia, ut disperdant nos, et uxores nostras, et filios nostros, et ut spolient nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'nos vero pugnabimus pro animabus nostris, et legibus nostris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'et ipse Dominus conteret eos ante faciem nostram: vos autem ne timueritis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Ut cessavit autem loqui, insiluit in eos subito: et contritus est Seron et exercitus ejus in conspectu ipsius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'et persecutus est eum in descensu Bethoron usque in campum, et ceciderunt ex eis octingenti viri, reliqui autem fugerunt in terram Philisthiim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Et cecidit timor Judæ ac fratrum ejus, et formido super omnes gentes in circuitu eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'et pervenit ad regem nomen ejus, et de præliis Judæ narrabant omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Ut audivit autem rex Antiochus sermones istos, iratus est animo: et misit, et congregavit exercitum universi regni sui, castra fortia valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'et aperuit ærarium suum, et dedit stipendia exercitui in annum: et mandavit illis ut essent parati ad omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Et vidit quod defecit pecunia de thesauris suis, et tributa regionis modica propter dissensionem et plagam quam fecit in terra, ut tolleret legitima, quæ erant a primis diebus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'et timuit ne non haberet ut semel et bis, in sumptus et donaria, quæ dederat ante larga manu: et abundaverat super reges qui ante eum fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Et consternatus erat animo valde, et cogitavit ire in Persidem, et accipere tributa regionum, et congregare argentum multum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 32, 'Et reliquit Lysiam hominem nobilem de genere regali, super negotia regia, a flumine Euphrate usque ad flumen \'gypti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 33, 'et ut nutriret Antiochum filium suum, donec rediret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 34, 'Et tradidit ei medium exercitum, et elephantos: et mandavit ei de omnibus quæ volebat, et de inhabitantibus Judæam, et Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 35, 'et ut mitteret ad eos exercitum ad conterendam et extirpandam virtutem Israël, et reliquias Jerusalem, et auferendam memoriam eorum de loco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 36, 'et ut constitueret habitatores filios alienigenas in omnibus finibus eorum, et sorte distribueret terram eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 37, 'Et rex assumpsit partem exercitus residui, et exivit ab Antiochia civitate regni sui anno centesimo et quadragesimo septimo: et transfretavit Euphraten flumen, et perambulabat superiores regiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 38, 'Et elegit Lysias Ptolemæum filium Dorymini, et Nicanorem, et Gorgiam, viros potentes ex amicis regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 39, 'et misit cum eis quadraginta millia virorum, et septem millia equitum, ut venirent in terram Juda, et disperderent eam secundum verbum regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 40, 'Et processerunt cum universa virtute sua, et venerunt, et applicuerunt Emmaum in terra campestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 41, 'Et audierunt mercatores regionum nomen eorum: et acceperunt argentum, et aurum multum valde, et pueros, et venerunt in castra ut acciperent filios Israël in servos, et additi sunt ad eos exercitus Syriæ, et terræ alienigenarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 42, 'Et vidit Judas et fratres ejus, quia multiplicata sunt mala, et exercitus applicabant ad fines eorum: et cognoverunt verba regis, quæ mandavit populo facere in interitum et consummationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 43, 'et dixerunt unusquisque ad proximum suum: Erigamus dejectionem populi nostri, et pugnemus pro populo nostro, et sanctis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 44, 'Et congregatus est conventus ut essent parati in prælium, et ut orarent et peterent misericordiam et miserationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 45, 'Et Jerusalem non habitabatur, sed erat sicut desertum: non erat qui ingrederetur et egrederetur de natis ejus. Et sanctum conculcabatur: et filii alienigenarum erant in arce; ibi erat habitatio gentium: et ablata est voluptas a Jacob, et defecit ibi tibia et cithara.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 46, 'Et congregati sunt, et venerunt in Maspha contra Jerusalem, quia locus orationis erat in Maspha ante in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 47, 'Et jejunaverunt illa die, et induerunt se ciliciis, et cinerem imposuerunt capiti suo, et disciderunt vestimenta sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 48, 'et expanderunt libros legis, de quibus scrutabantur gentes similitudinem simulacrorum suorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 49, 'et attulerunt ornamenta sacerdotalia, et primitias, et decimas: et suscitaverunt Nazaræos, qui impleverant dies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 50, 'et clamaverunt voce magna in cælum, dicentes: Quid faciemus istis, et quo eos ducemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 51, 'et sancta tua conculcata sunt, et contaminata sunt, et sacerdotes tui facti sunt in luctum, et in humilitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 52, 'et ecce nationes convenerunt adversum nos ut nos disperdant: tu scis quæ cogitant in nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 53, 'Quomodo poterimus subsistere ante faciem eorum, nisi tu, Deus, adjuves nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 54, 'Et tubis exclamaverunt voce magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 55, 'Et post hæc constituit Judas duces populi, tribunos, et centuriones, et pentacontarchos, et decuriones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 56, 'Et dixit his, qui ædificabant domos, et sponsabant uxores, et plantabant vineas, et formidolosis, ut redirent unusquisque in domum suam secundum legem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 57, 'Et moverunt castra, et collocaverunt ad austrum Emmaum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 58, 'Et ait Judas: Accingimini, et estote filii potentes, et estote parati in mane, ut pugnetis adversus nationes has quæ convenerunt adversus nos disperdere nos, et sancta nostra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 59, 'quoniam melius est nos mori in bello, quam videre mala gentis nostræ, et sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 60, 'Sicut autem fuerit voluntas in cælo, sic fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Et assumpsit Gorgias quinque millia virorum, et mille equites electos: et moverunt castra nocte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'ut applicarent ad castra Judæorum, et percuterent eos subito: et filii, qui erant ex arce, erant illis duces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Et audivit Judas, et surrexit ipse et potentes percutere virtutem exercituum regis, qui erant in Emmaum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'adhuc enim dispersus erat exercitus a castris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Et venit Gorgias in castra Judæ noctu, et neminem invenit: et quærebat eos in montibus, quoniam dixit: Fugiunt hi a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Et cum dies factus esset, apparuit Judas in campo cum tribus millibus virorum tantum, qui tegumenta et gladios non habebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'et viderunt castra gentium valida, et loricatos et equitatus in circuitu eorum, et hi docti ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Et ait Judas viris, qui secum erant: Ne timueritis multitudinem eorum, et impetum eorum ne formidetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Mementote qualiter salvi facti sunt patres nostri in mari Rubro, cum sequeretur eos Pharao cum exercitu multo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Et nunc clamemus in cælum: et miserebitur nostri Dominus, et memor erit testamenti patrum nostrorum, et conteret exercitum istum ante faciem nostram hodie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'et scient omnes gentes quia est qui redimat et liberet Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Et elevaverunt alienigenæ oculos suos, et viderunt eos venientes ex adverso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Et exierunt de castris in prælium, et tuba cecinerunt hi qui erant cum Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Et congressi sunt: et contritæ sunt gentes, et fugerunt in campum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Novissimi autem omnes ceciderunt in gladio, et persecuti sunt eos usque Gezeron, et usque in campos Idumææ, et Azoti, et Jamniæ: et ceciderunt ex illis usque ad tria millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Et reversus est Judas, et exercitus ejus sequens eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Dixitque ad populum: Non concupiscatis spolia: quia bellum contra nos est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'et Gorgias et exercitus ejus prope nos in monte: sed state nunc contra inimicos nostros, et expugnate eos, et sumetis postea spolia securi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Et adhuc loquente Juda hæc, ecce apparuit pars quædam prospiciens de monte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Et vidit Gorgias quod in fugam conversi sunt sui, et succenderunt castra: fumus enim, qui videbatur, declarabat quod factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Quibus illi conspectis timuerunt valde, aspicientes simul et Judam, et exercitum in campo paratum ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Et fugerunt omnes in campum alienigenarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'et Judas reversus est ad spolia castrorum, et acceperunt aurum multum, et argentum, et hyacinthinum, et purpuram marinam, et opes magnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Et conversi, hymnum canebant, et benedicebant Deum in cælum, quoniam bonus est, quoniam in sæculum misericordia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Et facta est salus magna in Israël in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 26, 'Quicumque autem alienigenarum evaserunt, venerunt, et nuntiaverunt Lysiæ universa quæ acciderant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 27, 'Quibus ille auditis, consternatus animo deficiebat: quod non qualia voluit, talia contigerunt in Israël, et qualia mandavit rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 28, 'Et sequenti anno, congregavit Lysias virorum electorum sexaginta millia, et equitum quinque millia, ut debellaret eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 29, 'Et venerunt in Judæam, et castra posuerunt in Bethoron, et occurrit illis Judas cum decem millibus viris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 30, 'Et viderunt exercitum fortem, et oravit, et dixit: Benedictus es, salvator Israël, qui contrivisti impetum potentis in manu servi tui David, et tradidisti castra alienigenarum in manu Jonathæ filii Saul, et armigeri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 31, 'Conclude exercitum istum in manu populi tui Israël, et confundantur in exercitu suo et equitibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 32, 'Da illis formidinem, et tabefac audaciam virtutis eorum, et commoveantur contritione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 33, 'Dejice illos gladio diligentium te: et collaudent te omnes, qui noverunt nomen tuum, in hymnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 34, 'Et commiserunt prælium: et ceciderunt de exercitu Lysiæ quinque millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 35, 'Videns autem Lysias fugam suorum, et Judæorum audaciam, et quod parati sunt aut vivere, aut mori fortiter, abiit Antiochiam, et elegit milites, ut multiplicati rursus venirent in Judæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 36, 'Dixit autem Judas, et fratres ejus: Ecce contriti sunt inimici nostri: ascendamus nunc mundare sancta, et renovare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 37, 'Et congregatus est omnis exercitus, et ascenderunt in montem Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 38, 'Et viderunt sanctificationem desertam, et altare profanatum, et portas exustas, et in atriis virgulta nata sicut in saltu vel in montibus, et pastophoria diruta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 39, 'Et sciderunt vestimenta sua, et planxerunt planctu magno, et imposuerunt cinerem super caput suum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 40, 'et ceciderunt in faciem super terram, et exclamaverunt tubis signorum, et clamaverunt in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 41, 'Tunc ordinavit Judas viros ut pugnarent adversus eos qui erant in arce, donec emundarent sancta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 42, 'Et elegit sacerdotes sine macula, voluntatem habentes in lege Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 43, 'et mundaverunt sancta, et tulerunt lapides contaminationis in locum immundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 44, 'Et cogitavit de altari holocaustorum, quod profanatum erat, quid de eo faceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 45, 'Et incidit illis consilium bonum ut destruerent illud: ne forte illis esset in opprobrium, quia contaminaverunt illud gentes, et demoliti sunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 46, 'Et reposuerunt lapides in monte domus in loco apto, quoadusque veniret propheta, et responderet de eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 47, 'Et acceperunt lapides integros secundum legem, et ædificaverunt altare novum secundum illud quod fuit prius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 48, 'et ædificaverunt sancta, et quæ intra domum erant intrinsecus: et ædem, et atria sanctificaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 49, 'Et fecerunt vasa sancta nova, et intulerunt candelabrum, et altare incensorum, et mensam, in templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 50, 'Et incensum posuerunt super altare, et accenderunt lucernas quæ super candelabrum erant, et lucebant in templo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 51, 'Et posuerunt super mensam panes, et appenderunt vela, et consummaverunt omnia opera quæ fecerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 52, 'Et ante matutinum surrexerunt quinta et vigesima die mensis noni (hic est mensis Casleu) centesimi quadragesimi octavi anni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 53, 'et obtulerunt sacrificium secundum legem super altare holocaustorum novum, quod fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 54, 'Secundum tempus et secundum diem in qua contaminaverunt illud gentes, in ipsa renovatum est in canticis, et citharis, et cinyris, et in cymbalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 55, 'Et cecidit omnis populus in faciem, et adoraverunt, et benedixerunt in cælum eum, qui prosperavit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 56, 'Et fecerunt dedicationem altaris diebus octo, et obtulerunt holocausta cum lætitia, et sacrificium salutaris et laudis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 57, 'Et ornaverunt faciem templi coronis aureis et scutulis, et dedicaverunt portas et pastophoria, et imposuerunt eis januas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 58, 'Et facta est lætitia in populo magna valde, et aversum est opprobrium gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 59, 'Et statuit Judas, et fratres ejus, et universa ecclesia Israël, ut agatur dies dedicationis altaris in temporibus suis ab anno in annum per dies octo a quinta et vigesima die mensis Casleu, cum lætitia et gaudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 60, 'Et ædificaverunt in tempore illo montem Sion, et per circuitum muros altos et turres firmas, nequando venirent gentes, et conculcarent eum sicut antea fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 61, 'Et collocavit illic exercitum, ut servarent eum, et munivit eum ad custodiendum Bethsuram, ut haberet populus munitionem contra faciem Idumææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Et factum est, ut audierunt gentes in circuitu quia ædificatum est altare et sanctuarium sicut prius, iratæ sunt valde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'et cogitabant tollere genus Jacob, qui erant inter eos, et cœperunt occidere de populo, et persequi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Et debellabat Judas filios Esau in Idumæa, et eos qui erant in Acrabathane, quia circumsedebant Israëlitas: et percussit eos plaga magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Et recordatus est malitiam filiorum Bean, qui erant populo in laqueum et in scandalum, insidiantes ei in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Et conclusi sunt ab eo in turribus, et applicuit ad eos, et anathematizavit eos, et incendit turres eorum igni cum omnibus qui in eis erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Et transivit ad filios Ammon, et invenit manum fortem, et populum copiosum, et Timotheum ducem ipsorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'et commisit cum eis prælia multa, et contriti sunt in conspectu eorum, et percussit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'et cepit Gazer civitatem et filias ejus, et reversus est in Judæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Et congregatæ sunt gentes quæ sunt in Galaad adversus Israëlitas, qui erant in finibus eorum, ut tollerent eos: et fugerunt in Datheman munitionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Et miserunt litteras ad Judam et fratres ejus, dicentes: Congregatæ sunt adversum nos gentes per circuitum, ut nos auferant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'et parant venire, et occupare munitionem, in quam confugimus: et Timotheus est dux exercitus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Nunc ergo veni, et eripe nos de manibus eorum, quia cecidit multitudo de nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Et omnes fratres nostri, qui erant in locis Tubin, interfecti sunt: et captivas duxerunt uxores eorum, et natos, et spolia, et peremerunt illic fere mille viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Et adhuc epistolæ legebantur, et ecce alii nuntii venerunt de Galilæa conscissis tunicis, nuntiantes secundum verba hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'dicentes convenisse adversum se a Ptolemaida, et Tyro, et Sidone: et repleta est omnis Galilæa alienigenis, ut nos consumant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Ut audivit autem Judas et populus sermones istos, convenit ecclesia magna cogitare quid facerent fratribus suis, qui in tribulatione erant, et expugnabantur ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Dixitque Judas Simoni fratri suo: Elige tibi viros, et vade, et libera fratres tuos in Galilæa: ego autem et frater meus Jonathas ibimus in Galaaditim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Et reliquit Josephum filium Zachariæ, et Azariam, duces populi, cum residuo exercitu in Judæa ad custodiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'et præcepit illis, dicens: Præestote populo huic: et nolite bellum committere adversum gentes, donec revertamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Et partiti sunt Simoni viri tria millia, ut iret in Galilæam: Judæ autem octo millia in Galaaditim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Et abiit Simon in Galilæam, et commisit prælia multa cum gentibus: et contritæ sunt gentes a facie ejus, et persecutus est eos usque ad portam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 22, 'Ptolemaidis: et ceciderunt de gentibus fere tria millia virorum. Et accepit spolia eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 23, 'et assumpsit eos qui erant in Galilæa et in Arbatis, cum uxoribus, et natis, et omnibus quæ erant illis, et adduxit in Judæam cum lætitia magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 24, 'Et Judas Machabæus, et Jonathas frater ejus, transierunt Jordanem, et abierunt viam trium dierum per desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 25, 'Et occurrerunt eis Nabuthæi, et susceperunt eos pacifice, et narraverunt eis omnia quæ acciderant fratribus eorum in Galaaditide,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 26, 'et quia multi ex eis comprehensi sunt in Barasa, et Bosor, et in Alimis, et in Casphor, et Mageth, et Carnaim: hæ omnes civitates munitæ et magnæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 27, 'Sed et in ceteris civitatibus Galaaditidis tenentur comprehensi, et in crastinum constituerunt admovere exercitum civitatibus his, et comprehendere, et tollere eos in una die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 28, 'Et convertit Judas et exercitus ejus viam in desertum Bosor repente, et occupavit civitatem: et occidit omnem masculum in ore gladii, et accepit omnia spolia eorum, et succendit eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 29, 'Et surrexerunt inde nocte, et ibant usque ad munitionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 30, 'Et factum est diluculo, cum elevassent oculos suos, ecce populus multus, cujus non erat numerus, portantes scalas et machinas ut comprehenderent munitionem, et expugnarent eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 31, 'Et vidit Judas quia cœpit bellum, et clamor belli ascendit ad cælum sicut tuba, et clamor magnus de civitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 32, 'et dixit exercitui suo: Pugnate hodie pro fratribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 33, 'Et venit tribus ordinibus post eos, et exclamaverunt tubis, et clamaverunt in oratione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 34, 'Et cognoverunt castra Timothei quia Machabæus est, et refugerunt a facie ejus: et percusserunt eos plaga magna. Et ceciderunt ex eis in die illa fere octo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 35, 'Et divertit Judas in Maspha, et expugnavit, et cepit eam: et occidit omnem masculum ejus, et sumpsit spolia ejus, et succendit eam igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 36, 'Inde perrexit, et cepit Casbon, et Mageth, et Bosor, et reliquas civitates Galaaditidis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 37, 'Post hæc autem verba congregavit Timotheus exercitum alium, et castra posuit contra Raphon trans torrentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 38, 'Et misit Judas speculari exercitum: et renuntiaverunt ei, dicentes: Quia convenerunt ad eum omnes gentes quæ in circuitu nostro sunt, exercitus multus nimis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 39, 'et Arabas conduxerunt in auxilium sibi, et castra posuerunt trans torrentem, parati ad te venire in prælium. Et abiit Judas obviam illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 40, 'Et ait Timotheus principibus exercitus sui: Cum appropinquaverit Judas, et exercitus ejus, ad torrentem aquæ: si transierit ad nos prior, non poterimus sustinere eum, quia potens poterit adversum nos;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 41, 'si vero timuerit transire, et posuerit castra extra flumen, transfretamus ad eos, et poterimus adversus illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 42, 'Ut autem appropinquavit Judas ad torrentem aquæ, statuit scribas populi secus torrentem, et mandavit eis, dicens: Neminem hominem reliqueritis, sed veniant omnes in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 43, 'Et transfretavit ad illos prior, et omnis populus post eum, et contritæ sunt omnes gentes a facie eorum, et projecerunt arma sua, et fugerunt ad fanum, quod erat in Carnaim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 44, 'Et occupavit ipsam civitatem, et fanum succendit igni cum omnibus qui erant in ipso: et oppressa est Carnaim, et non potuit sustinere contra faciem Judæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 45, 'Et congregavit Judas universos Israëlitas, qui erant in Galaaditide, a minimo usque ad maximum, et uxores eorum, et natos, et exercitum magnum valde, ut venirent in terram Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 46, 'Et venerunt usque Ephron: et hæc civitas magna in ingressu posita, munita valde, et non erat declinare ab ea dextera vel sinistra, sed per mediam iter erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 47, 'Et incluserunt se qui erant in civitate, et obstruxerunt portas lapidibus: et misit ad eos Judas verbis pacificis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 48, 'dicens: Transeamus per terram vestram, ut eamus in terram nostram: et nemo vobis nocebit, tantum pedibus transibimus. Et nolebant eis aperire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 49, 'Et præcepit Judas prædicare in castris, ut applicarent unusquisque in quo erat loco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 50, 'et applicuerunt se viri virtutis, et oppugnavit civitatem illam tota die et tota nocte, et tradita est civitas in manu ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 51, 'et peremerunt omnem masculum in ore gladii, et eradicavit eam, et accepit spolia ejus: et transivit per totam civitatem super interfectos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 52, 'Et transgressi sunt Jordanem in campo magno, contra faciem Bethsan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 53, 'Et erat Judas congregans extremos, et exhortabatur populum per totam viam, donec venirent in terram Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 54, 'et ascenderunt in montem Sion cum lætitia, et gaudio, et obtulerunt holocausta, quod nemo ex eis cecidisset donec reverterentur in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 55, 'Et in diebus quibus erat Judas et Jonathas in terra Galaad, et Simon frater ejus in Galilæa contra faciem Ptolemaidis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 56, 'audivit Josephus Zachariæ filius, et Azarias princeps virtutis, res bene gestas, et prælia quæ facta sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 57, 'et dixit: Faciamus et ipsi nobis nomen, et eamus pugnare adversus gentes quæ in circuitu nostro sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 58, 'Et præcepit his qui erant in exercitu suo, et abierunt Jamniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 59, 'Et exivit Gorgias de civitate, et viri ejus obviam illis in pugnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 60, 'Et fugati sunt Josephus et Azarias usque in fines Judææ: et ceciderunt illo die de populo Israël ad duo millia viri, et facta est fuga magna in populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 61, 'quia non audierunt Judam, et fratres ejus, existimantes fortiter se facturos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 62, 'Ipsi autem non erant de semine virorum illorum, per quos salus facta est in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 63, 'Et viri Juda magnificati sunt valde in conspectu omnis Israël, et gentium omnium ubi audiebatur nomen eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 64, 'Et convenerunt ad eos fausta acclamantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 65, 'Et exivit Judas et fratres ejus, et expugnabant filios Esau in terra quæ ad austrum est, et percussit Chebron et filias ejus: et muros ejus, et turres succendit igni in circuitu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 66, 'Et movit castra ut iret in terram alienigenarum, et perambulabat Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 67, 'In die illa ceciderunt sacerdotes in bello, dum volunt fortiter facere, dum sine consilio exeunt in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 68, 'Et declinavit Judas in Azotum in terram alienigenarum, et diruit aras eorum, et sculptilia deorum ipsorum succendit igni: et cepit spolia civitatum, et reversus est in terram Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Et rex Antiochus perambulabat superiores regiones, et audivit esse civitatem Elymaidem in Perside nobilissimam, et copiosam in argento et auro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'templumque in ea locuples valde, et illic velamina aurea, et loricæ, et scuta, quæ reliquit Alexander Philippi rex Macedo, qui regnavit primus in Græcia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Et venit, et quærebat capere civitatem, et deprædari eam: et non potuit, quoniam innotuit sermo his qui erant in civitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'et insurrexerunt in prælium, et fugit inde, et abiit cum tristitia magna, et reversus est in Babyloniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Et venit qui nuntiaret ei in Perside, quia fugata sunt castra quæ erant in terra Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'et quia abiit Lysias cum virtute forti in primis, et fugatus est a facie Judæorum, et invaluerunt armis, et viribus, et spoliis multis, quæ ceperunt de castris, quæ exciderunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'et quia diruerunt abominationem, quam ædificaverat super altare quod erat in Jerusalem: et sanctificationem, sicut prius, circumdederunt muris excelsis, sed et Bethsuram civitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Et factum est ut audivit rex sermones istos, expavit, et commotus est valde: et decidit in lectum, et incidit in languorem præ tristitia, quia non factum est ei sicut cogitabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Et erat illic per dies multos, quia renovata est in eo tristitia magna, et arbitratus est se mori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Et vocavit omnes amicos suos, et dixit illis: Recessit somnus ab oculis meis, et concidi, et corrui corde præ sollicitudine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'et dixi in corde meo: In quantam tribulationem deveni, et in quos fluctus tristitiæ, in qua nunc sum: qui jucundus eram, et dilectus in potestate mea!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Nunc vero reminiscor malorum quæ feci in Jerusalem, unde et abstuli omnia spolia aurea et argentea quæ erant in ea, et misi auferre habitantes Judæam sine causa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Cognovi ergo quia propterea invenerunt me mala ista: et ecce pereo tristitia magna in terra aliena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Et vocavit Philippum, unum de amicis suis, et præposuit eum super universum regnum suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'et dedit ei diadema, et stolam suam, et annulum, ut adduceret Antiochum filium suum, et nutriret eum, et regnaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Et mortuus est illic Antiochus rex anno centesimo quadragesimo nono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Et cognovit Lysias quoniam mortuus est rex, et constituit regnare Antiochum filium ejus, quem nutrivit adolescentem: et vocavit nomen ejus Eupator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Et hi qui erant in arce, concluserant Israël in circuitu sanctorum: et quærebant eis mala semper, et firmamentum gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Et cogitavit Judas disperdere eos: et convocavit universum populum, ut obsiderent eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Et convenerunt simul, et obsederunt eos anno centesimo quinquagesimo, et fecerunt ballistas et machinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Et exierunt quidam ex eis qui obsidebantur: et adjunxerunt se illis aliqui impii ex Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'et abierunt ad regem, et dixerunt: Quousque non facis judicium, et vindicas fratres nostros?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Nos decrevimus servire patri tuo, et ambulare in præceptis ejus, et obsequi edictis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 24, 'et filii populi nostri propter hoc alienabant se a nobis, et quicumque inveniebantur ex nobis, interficiebantur, et hæreditates nostræ diripiebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 25, 'Et non ad nos tantum extenderunt manum, sed et in omnes fines nostros:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 26, 'et ecce applicuerunt hodie ad arcem Jerusalem occupare eam, et munitionem Bethsuram munierunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 27, 'et nisi præveneris eos velocius, majora quam hæc facient, et non poteris obtinere eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 28, 'Et iratus est rex, ut hæc audivit: et convocavit omnes amicos suos, et principes exercitus sui, et eos qui super equites erant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 29, 'sed et de regnis aliis et de insulis maritimis venerunt ad eum exercitus conductitii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 30, 'Et erat numerus exercitus ejus, centum millia peditum, et viginti millia equitum, et elephanti triginta duo, docti ad prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 31, 'Et venerunt per Idumæam, et applicuerunt ad Bethsuram, et pugnaverunt dies multos: et fecerunt machinas, et exierunt, et succenderunt eas igni, et pugnaverunt viriliter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 32, 'Et recessit Judas ab arce, et movit castra ad Bethzacharam contra castra regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 33, 'Et surrexit rex ante lucem, et concitavit exercitus in impetum contra viam Bethzacharam: et comparaverunt se exercitus in prælium, et tubis cecinerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 34, 'et elephantis ostenderunt sanguinem uvæ et mori, ad acuendos eos in prælium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 35, 'et diviserunt bestias per legiones, et astiterunt singulis elephantis mille viri in loricis concatenatis, et galeæ æreæ in capitibus eorum: et quingenti equites ordinati unicuique bestiæ electi erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 36, 'Hi ante tempus, ubicumque erat bestia, ibi erant: et quocumque ibat, ibant, et non discedebant ab ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 37, 'Sed et turres ligneæ super eos firmæ protegentes super singulas bestias: et super eas machinæ: et super singulas viri virtutis triginta duo, qui pugnabant desuper: et Indus magister bestiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 38, 'Et residuum equitatum hinc et inde statuit in duas partes, tubis exercitum commovere, et perurgere constipatos in legionibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 39, 'Et ut refulsit sol in clypeos aureos et æreos, resplenduerunt montes ab eis, et resplenduerunt sicut lampades ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 40, 'Et distincta est pars exercitus regis per montes excelsos, et alia per loca humilia: et ibant caute et ordinate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 41, 'Et commovebantur omnes inhabitantes terram a voce multitudinis, et incessu turbæ, et collisione armorum: erat enim exercitus magnus valde, et fortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 42, 'Et appropiavit Judas et exercitus ejus in prælium, et ceciderunt de exercitu regis sexcenti viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 43, 'Et vidit Eleazar filius Saura unam de bestiis loricatam loricis regis: et erat eminens super ceteras bestias, et visum est ei quod in ea esset rex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 44, 'et dedit se ut liberaret populum suum, et acquireret sibi nomen æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 45, 'Et cucurrit ad eam audacter in medio legionis, interficiens a dextris et a sinistris, et cadebant ab eo huc atque illuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 46, 'Et ivit sub pedes elephantis, et supposuit se ei, et occidit eum: et cecidit in terram super ipsum, et mortuus est illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 47, 'Et videntes virtutem regis, et impetum exercitus ejus, diverterunt se ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 48, 'Castra autem regis ascenderunt contra eos in Jerusalem, et applicuerunt castra regis ad Judæam, et montem Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 49, 'Et fecit pacem cum his qui erant in Bethsura: et exierunt de civitate, quia non erant eis ibi alimenta conclusis, quia sabbata erant terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 50, 'Et comprehendit rex Bethsuram: et constituit illic custodiam servare eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 51, 'Et convertit castra ad locum sanctificationis dies multos: et statuit illic ballistas, et machinas, et ignis jacula, et tormenta ad lapides jactandos, et spicula, et scorpios ad mittendas sagittas, et fundibula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 52, 'Fecerunt autem et ipsi machinas adversus machinas eorum, et pugnaverunt dies multos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 53, 'Escæ autem non erant in civitate, eo quod septimus annus esset: et qui remanserant in Judæa de gentibus, consumpserant reliquias eorum, quæ repositæ fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 54, 'Et remanserunt in sanctis viri pauci, quoniam obtinuerat eos fames: et dispersi sunt unusquisque in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 55, 'Et audivit Lysias quod Philippus, quem constituerat rex Antiochus cum adhuc viveret, ut nutriret Antiochum filium suum, et regnaret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 56, 'reversus esset a Perside et Media, et exercitus qui abierat cum ipso, et quia quærebat suscipere regni negotia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 57, 'festinavit ire, et dicere ad regem, et duces exercitus: Deficimus quotidie, et esca nobis modica est; et locus, quem obsidemus, est munitus, et incumbit nobis ordinare de regno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 58, 'Nunc itaque demus dextras hominibus istis, et faciamus cum illis pacem, et cum omni gente eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 59, 'et constituamus illis ut ambulent in legitimis suis sicut prius: propter legitima enim ipsorum, quæ despeximus, irati sunt, et fecerunt omnia hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 60, 'Et placuit sermo in conspectu regis et principum: et misit ad eos pacem facere, et receperunt illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 61, 'Et juravit illis rex et principes, et exierunt de munitione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 62, 'Et intravit rex montem Sion, et vidit munitionem loci: et rupit citius juramentum quod juravit, et mandavit destruere murum in gyro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 63, 'Et discessit festinanter, et reversus est Antiochiam, et invenit Philippum dominantem civitati: et pugnavit adversus eum, et occupavit civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Anno centesimo quinquagesimo primo, exiit Demetrius Seleuci filius ab urbe Roma, et ascendit cum paucis viris in civitatem maritimam, et regnavit illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Et factum est, ut ingressus est domum regni patrum suorum, comprehendit exercitus Antiochum et Lysiam, ut adducerent eos ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Et res ei innotuit, et ait: Nolite mihi ostendere faciem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Et occidit eos exercitus. Et sedit Demetrius super sedem regni sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Et venerunt ad eum viri iniqui et impii ex Israël: et Alcimus dux eorum, qui volebat fieri sacerdos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Et accusaverunt populum apud regem, dicentes: Perdidit Judas et fratres ejus omnes amicos tuos, et nos dispersit de terra nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Nunc ergo mitte virum, cui credis, ut eat, et videat exterminium omne quod fecit nobis, et regionibus regis: et puniat omnes amicos ejus, et adjutores eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Et elegit rex ex amicis suis Bacchidem, qui dominabatur trans flumen magnum in regno, et fidelem regi: et misit eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'ut videret exterminium quod fecit Judas: sed et Alcimum impium constituit in sacerdotium, et mandavit ei facere ultionem in filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Et surrexerunt, et venerunt cum exercitu magno in terram Juda: et miserunt nuntios, et locuti sunt ad Judam et ad fratres ejus verbis pacificis in dolo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Et non intenderunt sermonibus eorum: viderunt enim quia venerunt cum exercitu magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Et convenerunt ad Alcimum et Bacchidem congregatio scribarum requirere quæ justa sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'et primi, Assidæi qui erant in filiis Israël: et exquirebant ab eis pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Dixerunt enim: Homo sacerdos de semine Aaron venit; non decipiet nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'et locutus est cum eis verba pacifica, et juravit illis, dicens: Non inferemus vobis malum, neque amicis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Et crediderunt ei: et comprehendit ex eis sexaginta viros, et occidit eos in una die, secundum verbum quod scriptum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Carnes sanctorum tuorum, et sanguinem ipsorum effuderunt in circuitu Jerusalem, et non erat qui sepeliret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Et incubuit timor et tremor in omnem populum: quia dixerunt: Non est veritas, et judicium in eis: transgressi sunt enim constitutum, et jusjurandum quod juraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Et movit Bacchides castra ab Jerusalem, et applicuit in Bethzecha: et misit, et comprehendit multos ex eis qui a se effugerant: et quosdam de populo mactavit, et in puteum magnum projecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Et commisit regionem Alcimo, et reliquit cum eo auxilium in adjutorium ipsi. Et abiit Bacchides ad regem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'et satis agebat Alcimus pro principatu sacerdotii sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'et convenerunt ad eum omnes, qui perturbabant populum suum, et obtinuerunt terram Juda, et fecerunt plagam magnam in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Et vidit Judas omnia mala quæ fecit Alcimus et qui cum eo erant filiis Israël, multo plus quam gentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'et exiit in omnes fines Judææ in circuitu, et fecit vindictam in viros desertores, et cessaverunt ultra exire in regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Vidit autem Alcimus quod prævaluit Judas et qui cum eo erant, et cognovit quia non potest sustinere eos: et regressus est ad regem, et accusavit eos multis criminibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 26, 'Et misit rex Nicanorem, unum ex principibus suis nobilioribus, qui erat inimicitias exercens contra Israël: et mandavit ei evertere populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 27, 'Et venit Nicanor in Jerusalem cum exercitu magno, et misit ad Judam et ad fratres ejus verbis pacificis cum dolo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 28, 'dicens: Non sit pugna inter me et vos: veniam cum viris paucis, ut videam facies vestras cum pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 29, 'Et venit ad Judam, et salutaverunt se invicem pacifice: et hostes parati erant rapere Judam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 30, 'Et innotuit sermo Judæ quoniam cum dolo venerat ad eum: et conterritus est ab eo, et amplius noluit videre faciem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 31, 'Et cognovit Nicanor quoniam denudatum est consilium ejus: et exivit obviam Judæ in pugnam juxta Capharsalama.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 32, 'Et ceciderunt de Nicanoris exercitu fere quinque millia viri, et fugerunt in civitatem David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 33, 'Et post hæc verba ascendit Nicanor in montem Sion: et exierunt de sacerdotibus populi salutare eum in pace, et demonstrare ei holocautomata, quæ offerebantur pro rege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 34, 'Et irridens sprevit eos, et polluit: et locutus est superbe,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 35, 'et juravit cum ira, dicens: Nisi traditus fuerit Judas et exercitus ejus in manus meas, continuo cum regressus fuero in pace, succendam domum istam. Et exiit cum ira magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 36, 'Et intraverunt sacerdotes, et steterunt ante faciem altaris et templi, et flentes dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 37, 'Tu, Domine, elegisti domum istam ad invocandum nomen tuum in ea, ut esset domus orationis et obsecrationis populo tuo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 38, 'fac vindictam in homine isto et exercitu ejus, et cadant in gladio: memento blasphemias eorum, et ne dederis eis ut permaneant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 39, 'Et exiit Nicanor ab Jerusalem, et castra applicuit ad Bethoron: et occurrit illi exercitus Syriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 40, 'Et Judas applicuit in Adarsa cum tribus millibus viris: et oravit Judas, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 41, 'Qui missi erant a rege Sennacherib, Domine, quia blasphemaverunt te, exiit angelus, et percussit ex eis centum octoginta quinque millia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 42, 'sic contere exercitum istum in conspectu nostro hodie: et sciant ceteri quia male locutus est super sancta tua: et judica illum secundum malitiam illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 43, 'Et commiserunt exercitus prælium tertiadecima die mensis Adar: et contrita sunt castra Nicanoris, et cecidit ipse primus in prælio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 44, 'Ut autem vidit exercitus ejus quia cecidisset Nicanor, projecerunt arma sua, et fugerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 45, 'et persecuti sunt eos viam unius diei ab Adazer usquequo veniatur in Gazara, et tubis cecinerunt post eos cum significationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 46, 'et exierunt de omnibus castellis Judææ in circuitu, et ventilabant eos cornibus, et convertebantur iterum ad eos, et ceciderunt omnes gladio, et non est relictus ex eis nec unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 47, 'Et acceperunt spolia eorum in prædam: et caput Nicanoris amputaverunt, et dexteram ejus, quam extenderat superbe, et attulerunt, et suspenderunt contra Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 48, 'Et lætatus est populus valde, et egerunt diem illam in lætitia magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 49, 'Et constituit agi omnibus annis diem istam tertiadecima die mensis Adar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 50, 'Et siluit terra Juda dies paucos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Et audivit Judas nomen Romanorum, quia sunt potentes viribus, et acquiescunt ad omnia quæ postulantur ab eis, et quicumque accesserunt ad eos, statuerunt cum eis amicitias: et quia sunt potentes viribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Et audierunt prælia eorum, et virtutes bonas, quas fecerunt in Galatia, quia obtinuerunt eos, et duxerunt sub tributum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'et quanta fecerunt in regione Hispaniæ, et quod in potestatem redegerunt metalla argenti et auri, quæ illic sunt, et possederunt omnem locum consilio suo, et patientia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'locaque quæ longe erant valde ab eis, et reges, qui supervenerant eis ab extremis terræ, contriverunt, et percusserunt eos plaga magna: ceteri autem dant eis tributum omnibus annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Et Philippum et Persen Ceteorum regem, et ceteros qui adversum eos arma tulerant, contriverunt in bello, et obtinuerunt eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'et Antiochum magnum regem Asiæ, qui eis pugnam intulerat habens centum viginti elephantos, et equitatum, et currus, et exercitum magnum valde, contritum ab eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'et quia ceperunt eum vivum, et statuerunt ei ut daret ipse, et qui regnarent post ipsum, tributum magnum, et daret obsides, et constitutum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'et regionem Indorum, et Medos, et Lydos, de optimis regionibus eorum: et acceptas eas ab eis, dederunt Eumeni regi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'et quia qui erant apud Helladam, voluerunt ire, et tollere eos: et innotuit sermo his,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'et miserunt ad eos ducem unum, et pugnaverunt contra illos, et ceciderunt ex eis multi, et captivas duxerunt uxores eorum et filios, et diripuerunt eos, et terram eorum possederunt, et destruxerunt muros eorum, et in servitutem illos redegerunt usque in hunc diem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'et residua regna, et insulas, quæ aliquando restiterant illis, exterminaverunt, et in potestatem redegerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Cum amicis autem suis, et qui in ipsis requiem habebant, conservaverunt amicitiam, et obtinuerunt regna, quæ erant proxima, et quæ erant longe: quia quicumque audiebant nomen eorum, timebant eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'quibus vero vellent auxilio esse ut regnarent, regnabant: quos autem vellent, regno deturbabant: et exaltati sunt valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Et in omnibus istis nemo portabat diadema, nec induebatur purpura, ut magnificaretur in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Et quia curiam fecerunt sibi, et quotidie consulebant trecentos viginti consilium agentes semper de multitudine, ut quæ digna sunt, gerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'et committunt uni homini magistratum suum per singulos annos dominari universæ terræ suæ, et omnes obediunt uni, et non est invidia, neque zelus inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Et elegit Judas Eupolemum filium Joannis filii Jacob, et Jasonem filium Eleazari, et misit eos Romam constituere cum illis amicitiam et societatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'et ut auferrent ab eis jugum Græcorum, quia viderunt quod in servitutem premerent regnum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Et abierunt Romam viam multam valde, et introierunt curiam, et dixerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Judas Machabæus, et fratres ejus, et populus Judæorum, miserunt nos ad vos statuere vobiscum societatem et pacem, et conscribere nos socios et amicos vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Et placuit sermo in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Et hoc rescriptum est quod rescripserunt in tabulis æreis, et miserunt in Jerusalem, ut esset apud eos ibi memoriale pacis et societatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Bene sit Romanis, et genti Judæorum, in mari et in terra in æternum: gladiusque et hostis procul sit ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Quod si institerit bellum Romanis prius, aut omnibus sociis eorum in omni dominatione eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'auxilium feret gens Judæorum, prout tempus dictaverit, corde pleno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'et præliantibus non dabunt, neque subministrabunt triticum, arma, pecuniam, naves, sicut placuit Romanis: et custodient mandata eorum, nihil ab eis accipientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Similiter autem et si genti Judæorum prius acciderit bellum, adjuvabunt Romani ex animo, prout eis tempus permiserit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'et adjuvantibus non dabitur triticum, arma, pecunia, naves, sicut placuit Romanis: et custodient mandata eorum absque dolo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'secundum hæc verba constituerunt Romani populo Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Quod si post hæc verba hi aut illi addere aut demere ad hæc aliquid voluerint, facient ex proposito suo: et quæcumque addiderint, vel dempserint, rata erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Sed et de malis, quæ Demetrius rex fecit in eos, scripsimus ei, dicentes: Quare gravasti jugum tuum super amicos nostros, et socios Judæos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'si ergo iterum adierint nos, adversum te faciemus illis judicium, et pugnabimus tecum mari terraque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Interea, ut audivit Demetrius quia cecidit Nicanor et exercitus ejus in prælio, apposuit Bacchidem et Alcimum rursum mittere in Judæam, et dextrum cornu cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Et abierunt viam quæ ducit in Galgala, et castra posuerunt in Masaloth, quæ est in Arbellis: et occupaverunt eam, et peremerunt animas hominum multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'In mense primo anni centesimi et quinquagesimi secundi, applicuerunt exercitum ad Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'et surrexerunt, et abierunt in Beream viginti millia virorum, et duo millia equitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Et Judas posuerat castra in Laisa, et tria millia viri electi cum eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'et viderunt multitudinem exercitus, quia multi sunt, et timuerunt valde: et multi subtraxerunt se de castris, et non remanserunt ex eis nisi octingenti viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Et vidit Judas quod defluxit exercitus suus, et bellum perurgebat eum, et confractus est corde, quia non habebat tempus congregandi eos, et dissolutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Et dixit his qui residui erant: Surgamus, et eamus ad adversarios nostros, si poterimus pugnare adversus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Et avertebant eum, dicentes: Non poterimus, sed liberemus animas nostras modo, et revertamur ad fratres nostros, et tunc pugnabimus adversus eos: nos autem pauci sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Et ait Judas: Absit istam rem facere ut fugiamus ab eis: et si appropiavit tempus nostrum, moriamur in virtute propter fratres nostros, et non inferamus crimen gloriæ nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Et movit exercitus de castris, et steterunt illis obviam: et divisi sunt equites in duas partes, et fundibularii et sagittarii præibant exercitum, et primi certaminis omnes potentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Bacchides autem erat in dextro cornu, et proximavit legio ex duabus partibus, et clamabant tubis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'exclamaverunt autem et hi qui erant ex parte Judæ etiam ipsi, et commota est terra a voce exercituum: et commissum est prælium a mane usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Et vidit Judas quod firmior est pars exercitus Bacchidis in dextris, et convenerunt cum ipso omnes constantes corde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'et contrita est dextera pars ab eis, et persecutus est eos usque ad montem Azoti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Et qui in sinistro cornu erant, viderunt quod contritum est dextrum cornu, et secuti sunt post Judam, et eos qui cum ipso erant, a tergo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'et ingravatum est prælium, et ceciderunt vulnerati multi ex his et ex illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Et Judas cecidit, et ceteri fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Et Jonathas et Simon tulerunt Judam fratrem suum, et sepelierunt eum in sepulchro patrum suorum in civitate Modin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Et fleverunt eum omnis populus Israël planctu magno, et lugebant dies multos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'et dixerunt: Quomodo cecidit potens, qui salvum faciebat populum Israël!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Et cetera verba bellorum Judæ, et virtutum, quas fecit, et magnitudinis ejus, non sunt descripta: multa enim erant valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'Et factum est: post obitum Judæ emerserunt iniqui in omnibus finibus Israël, et exorti sunt omnes qui operabantur iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'In diebus illis facta est fames magna valde, et tradidit se Bacchidi omnis regio eorum cum ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Et elegit Bacchides viros impios, et constituit eos dominos regionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'et exquirebant, et perscrutabantur amicos Judæ, et adducebant eos ad Bacchidem, et vindicabat in illos, et illudebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Et facta est tribulatio magna in Israël, qualis non fuit ex die qua non est visus propheta in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Et congregati sunt omnes amici Judæ, et dixerunt Jonathæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Ex quo frater tuus Judas defunctus est, vir similis ei non est, qui exeat contra inimicos nostros, Bacchidem et eos qui inimici sunt gentis nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Nunc itaque, te hodie elegimus esse pro eo nobis in principem, et ducem ad bellandum bellum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Et suscepit Jonathas tempore illo principatum, et surrexit loco Judæ fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Et cognovit Bacchides, et quærebat eum occidere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Et cognovit Jonathas, et Simon frater ejus, et omnes qui cum eo erant: et fugerunt in desertum Thecuæ et consederunt ad aquam lacus Asphar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 34, 'Et cognovit Bacchides, et die sabbatorum venit ipse et omnis exercitus ejus trans Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 35, 'Et Jonathas misit fratrem suum ducem populi, et rogavit Nabuthæos amicos suos, ut commodarent illis apparatum suum, qui erat copiosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 36, 'Et exierunt filii Jambri ex Madaba, et comprehenderunt Joannem et omnia quæ habebat, et abierunt habentes ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 37, 'Post hæc verba, renuntiatum est Jonathæ et Simoni fratri ejus, quia filii Jambri faciunt nuptias magnas, et ducunt sponsam ex Madaba filiam unius de magnis principibus Chanaan cum ambitione magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 38, 'Et recordati sunt sanguinis Joannis fratris sui: et ascenderunt, et absconderunt se sub tegumento montis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 39, 'Et elevaverunt oculos suos, et viderunt: et ecce tumultus, et apparatus multus: et sponsus processit, et amici ejus, et fratres ejus obviam illis cum tympanis, et musicis, et armis multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 40, 'Et surrexerunt ad eos ex insidiis, et occiderunt eos, et ceciderunt vulnerati multi, et residui fugerunt in montes: et acceperunt omnia spolia eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 41, 'et conversæ sunt nuptiæ in luctum, et vox musicorum ipsorum in lamentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 42, 'Et vindicaverunt vindictam sanguinis fratris sui: et reversi sunt ad ripam Jordanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 43, 'Et audivit Bacchides, et venit die sabbatorum usque ad oram Jordanis in virtute magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 44, 'Et dixit ad suos Jonathas: Surgamus, et pugnemus contra inimicos nostros: non est enim hodie sicut heri et nudiustertius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 45, 'ecce enim bellum ex adverso, aqua vero Jordanis hinc et inde, et ripæ, et paludes, et saltus: et non est locus divertendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 46, 'Nunc ergo, clamate in cælum, ut liberemini de manu inimicorum vestrorum. Et commissum est bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 47, 'Et extendit Jonathas manum suam percutere Bacchidem, et divertit ab eo retro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 48, 'et desiliit Jonathas, et qui cum eo erant, in Jordanem, et transnataverunt ad eos Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 49, 'Et ceciderunt de parte Bacchidis die illa mille viri. Et reversi sunt in Jerusalem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 50, 'et ædificaverunt civitates munitas in Judæa, munitionem quæ erat in Jericho, et in Ammaum, et in Bethoron, et in Bethel, et Thamnata, et Phara, et Thopo muris excelsis, et portis, et seris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 51, 'Et posuit custodiam in eis, ut inimicitias exercerent in Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 52, 'et munivit civitatem Bethsuram, et Gazaram, et arcem, et posuit in eis auxilia, et apparatum escarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 53, 'et accepit filios principum regionis obsides, et posuit eos in arce in Jerusalem in custodiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 54, 'Et anno centesimo quinquagesimo tertio, mense secundo, præcepit Alcimus destrui muros domus sanctæ interioris, et destrui opera prophetarum: et cœpit destruere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 55, 'In tempore illo percussus est Alcimus: et impedita sunt opera illius, et occlusum est os ejus, et dissolutus est paralysi, nec ultra potuit loqui verbum, et mandare de domo sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 56, 'Et mortuus est Alcimus in tempore illo cum tormento magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 57, 'Et vidit Bacchides quoniam mortuus est Alcimus, et reversus est ad regem. Et siluit terra annis duobus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 58, 'Et cogitaverunt omnes iniqui, dicentes: Ecce Jonathas, et qui cum eo sunt, in silentio habitant confidenter: nunc ergo adducamus Bacchidem, et comprehendet eos omnes una nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 59, 'Et abierunt, et consilium ei dederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 60, 'Et surrexit ut veniret cum exercitu multo: et misit occulte epistolas sociis suis qui erant in Judæa, ut comprehenderent Jonathan, et eos qui cum eo erant: sed non potuerunt, quia innotuit eis consilium eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 61, 'Et apprehendit de viris regionis, qui principes erant malitiæ, quinquaginta viros, et occidit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 62, 'et secessit Jonathas, et Simon, et qui cum eo erant, in Bethbessen, quæ est in deserto: et exstruxit diruta ejus, et firmaverunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 63, 'Et cognovit Bacchides, et congregavit universam multitudinem suam: et his, qui de Judæa erant, denuntiavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 64, 'Et venit, et castra posuit desuper Bethbessen: et oppugnavit eam dies multos, et fecit machinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 65, 'Et reliquit Jonathas Simonem fratrem suum in civitate, et exiit in regionem, et venit cum numero:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 66, 'et percussit Odaren et fratres ejus, et filios Phaseron in tabernaculis ipsorum: et cœpit cædere, et crescere in virtutibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 67, 'Simon vero, et qui cum ipso erant, exierunt de civitate, et succenderunt machinas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 68, 'et pugnaverunt contra Bacchidem, et contritus est ab eis: et afflixerunt eum valde, quoniam consilium ejus et congressus ejus erat inanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 69, 'Et iratus contra viros iniquos, qui ei consilium dederant ut veniret in regionem ipsorum, multos ex eis occidit: ipse autem cogitavit cum reliquis abire in regionem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 70, 'Et cognovit Jonathas: et misit ad eum legatos componere pacem cum ipso, et reddere ei captivitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 71, 'Et libenter accepit, et fecit secundum verba ejus, et juravit se nihil facturum ei mali omnibus diebus vitæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 72, 'Et reddidit ei captivitatem, quam prius erat prædatus de terra Juda: et conversus abiit in terram suam, et non apposuit amplius venire in fines ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 73, 'Et cessavit gladius ex Israël: et habitavit Jonathas in Machmas, et cœpit Jonathas ibi judicare populum, et exterminavit impios ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Et anno centesimo sexagesimo, ascendit Alexander Antiochi filius, qui cognominatus est Nobilis, et occupavit Ptolemaidam: et receperunt eum, et regnavit illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Et audivit Demetrius rex, et congregavit exercitum copiosum valde, et exivit obviam illi in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Et misit Demetrius epistolam ad Jonathan verbis pacificis, ut magnificaret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Dixit enim: Anticipemus facere pacem cum eo, priusquam faciat cum Alexandro adversum nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'recordabitur enim omnium malorum, quæ fecimus in eum, et in fratrem ejus, et in gentem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Et dedit ei potestatem congregandi exercitum, et fabricare arma, et esse ipsum socium ejus: et obsides, qui erant in arce, jussit tradi ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Et venit Jonathas in Jerusalem, et legit epistolas in auditu omnis populi, et eorum qui in arce erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Et timuerunt timore magno, quoniam audierunt quod dedit ei rex potestatem congregandi exercitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Et traditi sunt Jonathæ obsides, et reddidit eos parentibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'et habitavit Jonathas in Jerusalem, et cœpit ædificare et innovare civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Et dixit facientibus opera ut exstruerent muros, et montem Sion in circuitu lapidibus quadratis ad munitionem: et ita fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Et fugerunt alienigenæ, qui erant in munitionibus quas Bacchides ædificaverat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'et reliquit unusquisque locum suum, et abiit in terram suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'tantum in Bethsura remanserunt aliqui ex his qui reliquerant legem et præcepta Dei: erat enim hæc eis ad refugium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et audivit Alexander rex promissa, quæ promisit Demetrius Jonathæ: et narraverunt ei prælia, et virtutes quas ipse fecit, et fratres ejus, et labores quos laboraverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'et ait: Numquid inveniemus aliquem virum talem? et nunc faciemus eum amicum, et socium nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Et scripsit epistolam, et misit ei secundum hæc verba, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Rex Alexander fratri Jonathæ salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Audivimus de te quod vir potens sis viribus, et aptus es ut sis amicus noster:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'et nunc constituimus te hodie summum sacerdotem gentis tuæ, et ut amicus voceris regis (et misit ei purpuram, et coronam auream) et quæ nostra sunt sentias nobiscum, et conserves amicitias ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Et induit se Jonathas stola sancta septimo mense, anno centesimo sexagesimo, in die solemni scenopegiæ: et congregavit exercitum, et fecit arma copiosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 22, 'Et audivit Demetrius verba ista, et contristatus est nimis, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 23, 'Quid hoc fecimus, quod præoccupavit nos Alexander apprehendere amicitiam Judæorum ad munimen sui?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 24, 'scribam et ego illis verba deprecatoria, et dignitates, et dona, ut sint mecum in adjutorium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 25, 'Et scripsit eis in hæc verba: Rex Demetrius genti Judæorum salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 26, 'Quoniam servastis ad nos pactum, et mansistis in amicitia nostra, et non accessistis ad inimicos nostros, audivimus, et gavisi sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 27, 'Et nunc perseverate adhuc conservare ad nos fidem, et retribuemus vobis bona pro his quæ fecistis nobiscum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 28, 'et remittemus vobis præstationes multas, et dabimus vobis donationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 29, 'Et nunc absolvo vos et omnes Judæos a tributis, et pretia salis indulgeo, et coronas remitto, et tertias seminis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 30, 'et dimidiam partem fructus ligni, quod est portionis meæ, relinquo vobis ex hodierno die, et deinceps, ne accipiatur a terra Juda, et a tribus civitatibus quæ additæ sunt illi ex Samaria et Galilæa; ex hodierna die et in totum tempus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 31, 'et Jerusalem sit sancta, et libera cum finibus suis: et decimæ et tributa ipsius sint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 32, 'Remitto etiam potestatem arcis, quæ est in Jerusalem: et do eam summo sacerdoti, ut constituat in ea viros quoscumque ipse elegerit, qui custodiant eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 33, 'Et omnem animam Judæorum, quæ captiva est a terra Juda in omni regno meo, relinquo liberam gratis, ut omnes a tributis solvantur, etiam pecorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 34, 'Et omnes dies solemnes, et sabbata, et neomeniæ, et dies decreti, et tres dies ante diem solemnem, et tres dies post diem solemnem, sint omnes immunitatis et remissionis omnibus Judæis, qui sunt in regno meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 35, 'et nemo habebit potestatem agere aliquid, et movere negotia adversus aliquem illorum in omni causa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 36, 'Et ascribantur ex Judæis in exercitu regis ad triginta millia virorum: et dabuntur illis copiæ ut oportet omnibus exercitibus regis, et ex eis ordinabuntur qui sint in munitionibus regis magni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 37, 'et ex his constituentur super negotia regni, quæ aguntur ex fide, et principes sint ex eis, et ambulent in legibus suis, sicut præcepit rex in terra Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 38, 'Et tres civitates, quæ additæ sunt Judææ ex regione Samariæ, cum Judæa reputentur: ut sint sub uno, et non obediant alii potestati, nisi summi sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 39, 'Ptolemaida et confines ejus, quas dedi donum sanctis qui sunt in Jerusalem, ad necessarios sumptus sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 40, 'Et ego do singulis annis quindecim millia siclorum argenti de rationibus regis, quæ me contingunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 41, 'et omne quod reliquum fuerit, quod non reddiderant qui super negotia erant annis prioribus, ex hoc dabunt in opera domus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 42, 'Et super hæc quinque millia siclorum argenti, quæ accipiebant de sanctorum ratione per singulos annos: et hæc ad sacerdotes pertineant, qui ministerio funguntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 43, 'Et quicumque confugerint in templum quod est Jerosolymis, et in omnibus finibus ejus, obnoxii regi in omni negotio dimittantur, et universa quæ sunt eis in regno meo, libera habeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 44, 'Et ad ædificanda vel restauranda opera sanctorum, sumptus dabuntur de ratione regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 45, 'et ad exstruendos muros Jerusalem, et communiendos in circuitu, sumptus dabuntur de ratione regis, et ad construendos muros in Judæa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 46, 'Ut audivit autem Jonathas et populus sermones istos, non crediderunt eis, nec receperunt eos: quia recordati sunt malitiæ magnæ, quam fecerat in Israël, et tribulaverat eos valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 47, 'Et complacuit eis in Alexandrum, quia ipse fuerat eis princeps sermonum pacis, et ipsi auxilium ferebant omnibus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 48, 'Et congregavit rex Alexander exercitum magnum, et admovit castra contra Demetrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 49, 'Et commiserunt prælium duo reges, et fugit exercitus Demetrii, et insecutus est eum Alexander, et incubuit super eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 50, 'Et invaluit prælium nimis, donec occidit sol: et cecidit Demetrius in die illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 51, 'Et misit Alexander ad Ptolemæum regem \'gypti legatos secundum hæc verba, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 52, 'Quoniam regressus sum in regnum meum, et sedi in sede patrum meorum, et obtinui principatum, et contrivi Demetrium, et possedi regionem nostram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 53, 'et commisi pugnam cum eo, et contritus est ipse et castra ejus a nobis, et sedimus in sede regni ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 54, 'et nunc statuamus ad invicem amicitiam: et da mihi filiam tuam uxorem, et ego ero gener tuus, et dabo tibi dona, et ipsi, digna te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 55, 'Et respondit rex Ptolemæus, dicens: Felix dies, in qua reversus es ad terram patrum tuorum, et sedisti in sede regni eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 56, 'Et nunc faciam tibi quod scripsisti: sed occurre mihi Ptolemaidam, ut videamus invicem nos, et spondeam tibi sicut dixisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 57, 'Et exivit Ptolemæus de \'gypto, ipse et Cleopatra filia ejus, et venit Ptolemaidam anno centesimo sexagesimo secundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 58, 'Et occurrit ei Alexander rex, et dedit ei Cleopatram filiam suam: et fecit nuptias ejus Ptolemaidæ, sicut reges in magna gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 59, 'Et scripsit rex Alexander Jonathæ, ut veniret obviam sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 60, 'Et abiit cum gloria Ptolemaidam, et occurrit ibi duobus regibus, et dedit illis argentum multum, et aurum, et dona: et invenit gratiam in conspectu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 61, 'Et convenerunt adversus eum viri pestilentes ex Israël, viri iniqui interpellantes adversus eum: et non intendit ad eos rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 62, 'Et jussit spoliari Jonathan vestibus suis, et indui eum purpura: et ita fecerunt. Et collocavit eum rex sedere secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 63, 'Dixitque principibus suis: Exite cum eo in medium civitatis, et prædicate, ut nemo adversus eum interpellet de ullo negotio, nec quisquam ei molestus sit de ulla ratione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 64, 'Et factum est, ut viderunt qui interpellabant gloriam ejus, quæ prædicabatur, et opertum eum purpura, fugerunt omnes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 65, 'et magnificavit eum rex, et scripsit eum inter primos amicos, et posuit eum ducem, et participem principatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 66, 'Et reversus est Jonathas in Jerusalem cum pace et lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 67, 'In anno centesimo sexagesimo quinto, venit Demetrius filius Demetrii a Creta in terram patrum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 68, 'Et audivit Alexander rex, et contristatus est valde, et reversus est Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 69, 'Et constituit Demetrius rex Apollonium ducem, qui præerat Cœlesyriæ: et congregavit exercitum magnum, et accessit ad Jamniam: et misit ad Jonathan summum sacerdotem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 70, 'dicens: Tu solus resistis nobis: ego autem factus sum in derisum, et in opprobrium, propterea quia tu potestatem adversum nos exerces in montibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 71, 'Nunc ergo si confidis in virtutibus tuis, descende ad nos in campum, et comparemus illic invicem: quia mecum est virtus bellorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 72, 'Interroga, et disce quis sum ego, et ceteri qui auxilio sunt mihi, qui et dicunt quia non potest stare pes vester ante faciem nostram, quia bis in fugam conversi sunt patres tui in terra sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 73, 'et nunc quomodo poteris sustinere equitatum et exercitum tantum in campo, ubi non est lapis, neque saxum, neque locus fugiendi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 74, 'Ut audivit autem Jonathas sermones Apollonii, motus est animo: et elegit decem millia virorum, et exiit ab Jerusalem, et occurrit ei Simon frater ejus in adjutorium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 75, 'et applicuerunt castra in Joppen, et exclusit eum a civitate, quia custodia Apollonii Joppe erat: et oppugnavit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 76, 'Et exterriti qui erant in civitate, aperuerunt ei, et obtinuit Jonathas Joppen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 77, 'Et audivit Apollonius, et admovit tria millia equitum, et exercitum multum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 78, 'Et abiit Azotum tamquam iter faciens, et statim exiit in campum, eo quod haberet multitudinem equitum, et confideret in eis. Et insecutus est eum Jonathas in Azotum, et commiserunt prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 79, 'Et reliquit Apollonius in castris mille equites post eos occulte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 80, 'Et cognovit Jonathas quoniam insidiæ sunt post se, et circuierunt castra ejus, et jecerunt jacula in populum a mane usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 81, 'Populus autem stabat, sicut præceperat Jonathas: et laboraverunt equi eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 82, 'Et ejecit Simon exercitum suum, et commisit contra legionem: equites enim fatigati erant: et contriti sunt ab eo, et fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 83, 'Et qui dispersi sunt per campum, fugerunt in Azotum, et intraverunt in Bethdagon idolum suum, ut ibi se liberarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 84, 'Et succendit Jonathas Azotum, et civitates quæ erant in circuitu ejus, et accepit spolia eorum, et templum Dagon: et omnes qui fugerunt in illud, succendit igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 85, 'Et fuerunt qui ceciderunt gladio, cum his qui succensi sunt, fere octo millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 86, 'Et movit inde Jonathas castra, et applicuit ea Ascalonem: et exierunt de civitate obviam illi in magna gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 87, 'Et reversus est Jonathas in Jerusalem cum suis, habentibus spolia multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 88, 'Et factum est, ut audivit Alexander rex sermones istos, addidit adhuc glorificare Jonathan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 89, 'Et misit ei fibulam auream, sicut consuetudo est dari cognatis regum. Et dedit ei Accaron, et omnes fines ejus, in possessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Et rex \'gypti congregavit exercitum, sicut arena quæ est circa oram maris, et naves multas: et quærebat obtinere regnum Alexandri dolo, et addere illud regno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Et exiit in Syriam verbis pacificis, et aperiebant ei civitates, et occurrebant ei: quia mandaverat Alexander rex exire ei obviam, eo quod socer suus esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Cum autem introiret civitatem Ptolemæus, ponebat custodias militum in singulis civitatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Et ut appropiavit Azoto, ostenderunt ei templum Dagon succensum igni, et Azotum, et cetera ejus demolita, et corpora projecta, et eorum, qui cæsi erant in bello, tumulos quos fecerant secus viam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Et narraverunt regi quia hæc fecit Jonathas, ut invidiam facerent ei: et tacuit rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Et occurrit Jonathas regi in Joppen cum gloria, et invicem se salutaverunt, et dormierunt illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Et abiit Jonathas cum rege usque ad fluvium qui vocatur Eleutherus: et reversus est in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Rex autem Ptolemæus obtinuit dominium civitatum usque Seleuciam maritimam, et cogitabat in Alexandrum consilia mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Et misit legatos ad Demetrium, dicens: Veni, componamus inter nos pactum, et dabo tibi filiam meam, quam habet Alexander, et regnabis in regno patris tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'pœnitet enim me quod dederim illi filiam meam: quæsivit enim me occidere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Et vituperavit eum, propterea quod concupierat regnum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Et abstulit filiam suam, et dedit eam Demetrio, et alienavit se ab Alexandro, et manifestæ sunt inimicitiæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Et intravit Ptolemæus Antiochiam, et imposuit duo diademata capiti suo, \'gypti et Asiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Alexander autem rex erat in Cilicia illis temporibus: quia rebellabant qui erant in locis illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Et audivit Alexander, et venit ad eum in bellum: et produxit Ptolemæus rex exercitum, et occurrit ei in manu valida, et fugavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Et fugit Alexander in Arabiam, ut ibi protegeretur: rex autem Ptolemæus exaltatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Et abstulit Zabdiel Arabs caput Alexandri, et misit Ptolemæo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Et rex Ptolemæus mortuus est in die tertia: et qui erant in munitionibus, perierunt ab his qui erant intra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Et regnavit Demetrius anno centesimo sexagesimo septimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'In diebus illis congregavit Jonathas eos qui erant in Judæa, ut expugnarent arcem quæ est in Jerusalem: et fecerunt contra eam machinas multas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Et abierunt quidam qui oderant gentem suam viri iniqui ad regem Demetrium, et renuntiaverunt ei quod Jonathas obsideret arcem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Et ut audivit, iratus est: et statim venit ad Ptolemaidam, et scripsit Jonathæ ne obsideret arcem, sed occurreret sibi ad colloquium festinato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Ut audivit autem Jonathas, jussit obsidere: et elegit de senioribus Israël, et de sacerdotibus, et dedit se periculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Et accepit aurum, et argentum, et vestem, et alia xenia multa, et abiit ad regem Ptolemaidam: et invenit gratiam in conspectu ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'et interpellabant adversus eum quidam iniqui ex gente sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Et fecit ei rex sicut fecerant ei qui ante eum fuerant: et exaltavit eum in conspectu omnium amicorum suorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'et statuit ei principatum sacerdotii, et quæcumque alia habuit prius pretiosa, et fecit eum principem amicorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Et postulavit Jonathas a rege ut immunem faceret Judæam, et tres toparchias, et Samariam et confines ejus: et promisit ei talenta trecenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Et consensit rex: et scripsit Jonathæ epistolas de his omnibus, hunc modum continentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Rex Demetrius fratri Jonathæ salutem, et genti Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Exemplum epistolæ, quam scripsimus Lastheni parenti nostro de vobis, misimus ad vos ut sciretis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Rex Demetrius Lastheni parenti salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Genti Judæorum amicis nostris, et conservantibus quæ justa sunt apud nos, decrevimus benefacere propter benignitatem ipsorum, quam erga nos habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Statuimus ergo illis omnes fines Judææ, et tres civitates, Lydan, et Ramathan, quæ additæ sunt Judææ ex Samaria, et omnes confines earum, sequestrari omnibus sacrificantibus in Jerosolymis pro his quæ ab eis prius accipiebat rex per singulos annos, et pro fructibus terræ et pomorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Et alia quæ ad nos pertinebant decimarum et tributorum ex hoc tempore, remittimus eis: et areas salinarum, et coronas, quæ nobis deferebantur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'omnia ipsis concedimus: et nihil horum irritum erit, ex hoc, et in omne tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 37, 'Nunc ergo curate facere horum exemplum, et detur Jonathæ, et ponatur in monte sancto, in loco celebri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 38, 'Et videns Demetrius rex quod siluit terra in conspectu suo, et nihil ei resistit, dimisit totum exercitum suum, unumquemque in locum suum, excepto peregrino exercitu, quem contraxit ab insulis gentium: et inimici erant ei omnes exercitus patrum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 39, 'Tryphon autem erat quidam partium Alexandri prius: et vidit quoniam omnis exercitus murmurabat contra Demetrium, et ivit ad Emalchuel Arabem, qui nutriebat Antiochum filium Alexandri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 40, 'et assidebat ei, ut traderet eum ipsi, ut regnaret loco patris sui: et enuntiavit ei quanta fecit Demetrius, et inimicitias exercituum ejus adversus illum. Et mansit ibi diebus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 41, 'Et misit Jonathas ad Demetrium regem, ut ejiceret eos qui in arce erant in Jerusalem, et qui in præsidiis erant: quia impugnabant Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 42, 'Et misit Demetrius ad Jonathan, dicens: Non hæc tantum faciam tibi, et genti tuæ, sed gloria illustrabo te, et gentem tuam, cum fuerit opportunum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 43, 'Nunc ergo recte feceris, si miseris in auxilium mihi viros: quia discessit omnis exercitus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 44, 'Et misit ei Jonathas tria millia virorum fortium Antiochiam: et venerunt ad regem, et delectatus est rex in adventu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 45, 'Et convenerunt qui erant de civitate, centum viginti millia virorum, et volebant interficere regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 46, 'Et fugit rex in aulam: et occupaverunt qui erant de civitate, itinera civitatis, et cœperunt pugnare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 47, 'Et vocavit rex Judæos in auxilium, et convenerunt omnes simul ad eum, et dispersi sunt omnes per civitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 48, 'et occiderunt in illa die centum millia hominum, et succenderunt civitatem, et ceperunt spolia multa in die illa, et liberaverunt regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 49, 'Et viderunt qui erant de civitate, quod obtinuissent Judæi civitatem sicut volebant: et infirmati sunt mente sua, et clamaverunt ad regem cum precibus, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 50, 'Da nobis dextras, et cessent Judæi oppugnare nos, et civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 51, 'Et projecerunt arma sua, et fecerunt pacem, et glorificati sunt Judæi in conspectu regis, et in conspectu omnium qui erant in regno ejus, et nominati sunt in regno: et regressi sunt in Jerusalem habentes spolia multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 52, 'Et sedit Demetrius rex in sede regni sui: et siluit terra in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 53, 'Et mentitus est omnia quæcumque dixit, et abalienavit se a Jonatha, et non retribuit ei secundum beneficia quæ sibi tribuerat, et vexabat eum valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 54, 'Post hæc autem reversus est Tryphon, et Antiochus cum eo puer adolescens, et regnavit, et imposuit sibi diadema.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 55, 'Et congregati sunt ad eum omnes exercitus, quos disperserat Demetrius, et pugnaverunt contra eum: et fugit, et terga vertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 56, 'Et accepit Tryphon bestias, et obtinuit Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 57, 'Et scripsit Antiochus adolescens Jonathæ, dicens: Constituo tibi sacerdotium, et constituo te super quatuor civitates, ut sis de amicis regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 58, 'Et misit illi vasa aurea in ministerium, et dedit ei potestatem bibendi in auro, et esse in purpura, et habere fibulam auream:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 59, 'et Simonem fratrem ejus constituit ducem a terminis Tyri usque ad fines \'gypti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 60, 'Et exiit Jonathas, et perambulabat trans flumen civitates: et congregatus est ad eum omnis exercitus Syriæ in auxilium, et venit Ascalonem, et occurrerunt ei honorifice de civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 61, 'Et abiit inde Gazam: et concluserunt se qui erant Gazæ: et obsedit eam, et succendit quæ erant in circuitu civitatis, et prædatus est ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 62, 'Et rogaverunt Gazenses Jonathan, et dedit illis dexteram: et accepit filios eorum obsides, et misit illos in Jerusalem: et perambulavit regionem usque Damascum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 63, 'Et audivit Jonathas quod prævaricati sunt principes Demetrii in Cades, quæ est in Galilæa, cum exercitu multo, volentes eum removere a negotio regni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 64, 'et occurrit illis: fratrem autem suum Simonem reliquit intra provinciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 65, 'Et applicuit Simon ad Bethsuram, et expugnabat eam diebus multis, et conclusit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 66, 'Et postulaverunt ab eo dextras accipere, et dedit illis: et ejecit eos inde, et cepit civitatem, et posuit in ea præsidium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 67, 'Et Jonathas et castra ejus applicuerunt ad aquam Genesar, et ante lucem vigilaverunt in campo Asor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 68, 'et ecce castra alienigenarum occurrebant in campo, et tendebant ei insidias in montibus: ipse autem occurrit ex adverso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 69, 'Insidiæ vero exsurrexerunt de locis suis, et commiserunt prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 70, 'Et fugerunt qui erant ex parte Jonathæ omnes, et nemo relictus est ex eis, nisi Mathathias filius Absolomi, et Judas filius Calphi, princeps militiæ exercitus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 71, 'Et scidit Jonathas vestimenta sua, et posuit terram in capite suo, et oravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 72, 'Et reversus est Jonathas ad eos in prælium, et convertit eos in fugam, et pugnaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 73, 'Et viderunt qui fugiebant partis illius, et reversi sunt ad eum, et insequebantur cum eo omnes usque Cades ad castra sua, et pervenerunt usque illuc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 74, 'et ceciderunt de alienigenis in die illa tria millia virorum: et reversus est Jonathas in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Et vidit Jonathas quia tempus eum juvat, et elegit viros, et misit eos Romam statuere et renovare cum eis amicitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'et ad Spartiatas, et ad alia loca misit epistolas secundum eamdem formam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'et abierunt Romam, et intraverunt curiam, et dixerunt: Jonathas summus sacerdos, et gens Judæorum miserunt nos, ut renovaremus amicitiam et societatem secundum pristinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Et dederunt illis epistolas ad ipsos per loca, ut deducerent eos in terram Juda cum pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Et hoc est exemplum epistolarum, quas scripsit Jonathas Spartiatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Jonathas summus sacerdos, et seniores gentis, et sacerdotes, et reliquus populus Judæorum, Spartiatis fratribus salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Jampridem missæ erant epistolæ ad Oniam summum sacerdotem ab Ario, qui regnabat apud vos, quoniam estis fratres nostri, sicut rescriptum continet, quod subjectum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Et suscepit Onias virum, qui missus fuerat, cum honore: et accepit epistolas, in quibus significabatur de societate et amicitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Nos cum nullo horum indigeremus, habentes solatio sanctos libros, qui sunt in manibus nostris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'maluimus mittere ad vos renovare fraternitatem et amicitiam, ne forte alieni efficiamur a vobis: multa enim tempora transierunt, ex quo misistis ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Nos ergo in omni tempore sine intermissione in diebus solemnibus, et ceteris, quibus oportet, memores sumus vestri in sacrificiis quæ offerimus, et in observationibus, sicut fas est, et decet meminisse fratrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Lætamur itaque de gloria vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Nos autem circumdederunt multæ tribulationes, et multa prælia, et impugnaverunt nos reges qui sunt in circuitu nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Noluimus ergo vobis molesti esse, neque ceteris sociis et amicis nostris in his præliis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'habuimus enim de cælo auxilium, et liberati sumus nos, et humiliati sunt inimici nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Elegimus itaque Numenium Antiochi filium, et Antipatrem Jasonis filium, et misimus ad Romanos renovare cum eis amicitiam et societatem pristinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Mandavimus itaque eis ut veniant etiam ad vos, et salutent vos, et reddant vobis epistolas nostras de innovatione fraternitatis nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Et nunc benefacietis respondentes nobis ad hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Et hoc est rescriptum epistolarum quod miserat Oniæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Arius rex Spartiatarum Oniæ sacerdoti magno salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Inventum est in scriptura de Spartiatis, et Judæis, quoniam sunt fratres, et quod sunt de genere Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 22, 'Et nunc ex quo hæc cognovimus, benefacitis scribentes nobis de pace vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 23, 'Sed et nos rescripsimus vobis: Pecora nostra, et possessiones nostræ, vestræ sunt: et vestræ, nostræ: mandavimus itaque hæc nuntiari vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 24, 'Et audivit Jonathas quoniam regressi sunt principes Demetrii cum exercitu multo supra quam prius, pugnare adversus eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 25, 'et exiit ab Jerusalem, et occurrit eis in Amathite regione: non enim dederat eis spatium ut ingrederentur regionem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 26, 'Et misit speculatores in castra eorum: et reversi renuntiaverunt quod constituunt supervenire illis nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 27, 'Cum occidisset autem sol, præcepit Jonathas suis vigilare, et esse in armis paratos ad pugnam tota nocte: et posuit custodes per circuitum castrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 28, 'Et audierunt adversarii quod paratus est Jonathas cum suis in bello: et timuerunt, et formidaverunt in corde suo: et accenderunt focos in castris suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 29, 'Jonathas autem, et qui cum eo erant, non cognoverunt usque mane: videbant autem luminaria ardentia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 30, 'et secutus est eos Jonathas, et non comprehendit eos: transierant enim flumen Eleutherum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 31, 'Et divertit Jonathas ad Arabas, qui vocantur Zabadæi: et percussit eos, et accepit spolia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 32, 'Et junxit, et venit Damascum, et perambulabat omnem regionem illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 33, 'Simon autem exiit, et venit usque ad Ascalonem, et ad proxima præsidia: et declinavit in Joppen, et occupavit eam');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 34, '(audivit enim quod vellent præsidium tradere partibus Demetrii), et posuit ibi custodes ut custodirent eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 35, 'Et reversus est Jonathas, et convocavit seniores populi, et cogitavit cum eis ædificare præsidia in Judæa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 36, 'et ædificare muros in Jerusalem, et exaltare altitudinem magnam inter medium arcis et civitatis, ut separaret eam a civitate, ut esset ipsa singulariter, et neque emant, neque vendant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 37, 'Et convenerunt ut ædificarent civitatem: et cecidit murus qui erat super torrentem ab ortu solis, et reparavit eum, qui vocatur Caphetetha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 38, 'et Simon ædificavit Adiada in Sephela, et munivit eam, et imposuit portas et seras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 39, 'Et cum cogitasset Tryphon regnare Asiæ, et assumere diadema, et extendere manum in Antiochum regem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 40, 'timens ne forte non permitteret eum Jonathas, sed pugnaret adversus eum, quærebat comprehendere eum, et occidere. Et exsurgens abiit in Bethsan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 41, 'Et exivit Jonathas obviam illi cum quadraginta millibus virorum electorum in prælium, et venit Bethsan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 42, 'Et vidit Tryphon quia venit Jonathas cum exercitu multo ut extenderet in eum manus: timuit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 43, 'et excepit eum cum honore, et commendavit eum omnibus amicis suis, et dedit ei munera: et præcepit exercitibus suis ut obedirent ei, sicut sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 44, 'Et dixit Jonathæ: Ut quid vexasti universum populum, cum bellum nobis non sit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 45, 'et nunc remitte eos in domos suas: elige autem tibi viros paucos, qui tecum sint, et veni mecum Ptolemaidam, et tradam eam tibi, et reliqua præsidia, et exercitum, et universos præpositos negotii: et conversus abibo: propterea enim veni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 46, 'Et credidit ei, et fecit sicut dixit: et dimisit exercitum, et abierunt in terram Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 47, 'Retinuit autem secum tria millia virorum: ex quibus remisit in Galilæam duo millia: mille autem venerunt cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 48, 'Ut autem intravit Ptolemaidam Jonathas, clauserunt portas civitatis Ptolemenses, et comprehenderunt eum: et omnes qui cum eo intraverant, gladio interfecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 49, 'Et misit Tryphon exercitum et equites in Galilæam et in campum magnum, ut perderent omnes socios Jonathæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 50, 'At illi cum cognovissent quia comprehensus est Jonathas, et periit, et omnes qui cum eo erant, hortati sunt semetipsos, et exierunt parati in prælium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 51, 'Et videntes hi qui insecuti fuerant, quia pro anima res est illis, reversi sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 52, 'illi autem venerunt omnes cum pace in terram Juda. Et planxerunt Jonathan, et eos qui cum ipso fuerant, valde: et luxit Israël luctu magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 53, 'Et quæsierunt omnes gentes quæ erant in circuitu eorum conterere eos: dixerunt enim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 54, 'Non habent principem et adjuvantem: nunc ergo expugnemus illos, et tollamus de hominibus memoriam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Et audivit Simon quod congregavit Tryphon exercitum copiosum ut veniret in terram Juda, et attereret eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Videns quia in tremore populus est, et in timore, ascendit Jerusalem, et congregavit populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'et adhortans dixit: Vos scitis quanta ego, et fratres mei, et domus patris mei, fecimus pro legibus et pro sanctis, prælia, et angustias quales vidimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'horum gratia perierunt fratres mei omnes propter Israël, et relictus sum ego solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Et nunc non mihi contingat parcere animæ meæ in omni tempore tribulationis: non enim melior sum fratribus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Vindicabo itaque gentem meam, et sancta, natos quoque nostros, et uxores: quia congregatæ sunt universæ gentes conterere nos inimicitiæ gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Et accensus est spiritus populi simul ut audivit sermones istos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'et responderunt voce magna, dicentes: Tu es dux noster loco Judæ, et Jonathæ fratris tui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'pugna prælium nostrum: et omnia, quæcumque dixeris nobis, faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Et congregans omnes viros bellatores, acceleravit consummare universos muros Jerusalem, et munivit eam in gyro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Et misit Jonathan filium Absalomi, et cum eo exercitum novum in Joppen, et ejectis his qui erant in ea, remansit illic ipse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Et movit Tryphon a Ptolemaida cum exercitu multo, ut veniret in terram Juda, et Jonathas cum eo in custodia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Simon autem applicuit in Addus contra faciem campi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Et ut cognovit Tryphon quia surrexit Simon loco fratris sui Jonathæ, et quia commissurus esset cum eo prælium, misit ad eum legatos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 15, 'dicens: Pro argento, quod debebat frater tuus Jonathas in ratione regis propter negotia quæ habuit, detinuimus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 16, 'Et nunc mitte argenti talenta centum, et duos filios ejus obsides, ut non dimissus fugiat a nobis, et remittemus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 17, 'Et cognovit Simon quia cum dolo loqueretur secum: jussit tamen dari argentum et pueros, ne inimicitiam magnam sumeret ad populum Israël, dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 18, 'Quia non misit ei argentum, et pueros, propterea periit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 19, 'Et misit pueros, et centum talenta: et mentitus est, et non dimisit Jonathan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 20, 'Et post hæc venit Tryphon intra regionem, ut contereret eam: et gyraverunt per viam quæ ducit Ador: et Simon et castra ejus ambulabant in omnem locum quocumque ibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 21, 'Qui autem in arce erant, miserunt ad Tryphonem legatos, ut festinaret venire per desertum, et mitteret illis alimonias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 22, 'Et paravit Tryphon omnem equitatum, ut veniret illa nocte: erat autem nix multa valde, et non venit in Galaaditim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 23, 'Et cum appropinquasset Bascaman, occidit Jonathan et filios ejus illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 24, 'Et convertit Tryphon, et abiit in terram suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 25, 'Et misit Simon, et accepit ossa Jonathæ fratris sui, et sepelivit ea in Modin civitate patrum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 26, 'Et planxerunt eum omnis Israël planctu magno, et luxerunt eum dies multos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 27, 'Et ædificavit Simon super sepulchrum patris sui et fratrum suorum ædificium altum visu, lapide polito retro et ante.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 28, 'Et statuit septem pyramidas, unam contra unam, patri et matri, et quatuor fratribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 29, 'et his circumposuit columnas magnas: et super columnas arma, ad memoriam æternam: et juxta arma naves sculptas, quæ viderentur ab omnibus navigantibus mare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 30, 'hoc est sepulchrum, quod fecit in Modin usque in hunc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 31, 'Tryphon autem cum iter faceret cum Antiocho rege adolescente, dolo occidit eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 32, 'et regnavit loco ejus, et imposuit sibi diadema Asiæ, et fecit plagam magnam in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 33, 'Et ædificavit Simon præsidia Judææ, muniens ea turribus excelsis, et muris magnis, et portis, et seris: et posuit alimenta in munitionibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 34, 'Et elegit Simon viros, et misit ad Demetrium regem ut faceret remissionem regioni: quia actus omnes Tryphonis per direptionem fuerant gesti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 35, 'Et Demetrius rex ad verba ista respondit ei, et scripsit epistolam talem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 36, 'Rex Demetrius Simoni summo sacerdoti et amico regum, et senioribus, et genti Judæorum, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 37, 'Coronam auream, et bahem, quam misistis, suscepimus: et parati sumus facere vobiscum pacem magnam, et scribere præpositis regis remittere vobis quæ indulsimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 38, 'Quæcumque enim constituimus, vobis constant: munitiones, quas ædificastis, vobis sint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 39, 'remittimus quoque ignorantias et peccata usque in hodiernum diem, et coronam quam debebatis: et si quid aliud erat tributarium in Jerusalem, jam non sit tributarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 40, 'Et si qui ex vobis apti sunt conscribi inter nostros, conscribantur, et sit inter nos pax.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 41, 'Anno centesimo septuagesimo, ablatum est jugum gentium ab Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 42, 'Et cœpit populus Israël scribere in tabulis, et gestis publicis, anno primo sub Simone summo sacerdote, magno duce, et principe Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 43, 'In diebus illis applicuit Simon ad Gazam, et circumdedit eam castris, et fecit machinas, et applicuit ad civitatem, et percussit turrem unam, et comprehendit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 44, 'Et eruperant qui erant intra machinam in civitatem, et factus est motus magnus in civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 45, 'Et ascenderunt qui erant in civitate cum uxoribus et filiis supra murum, scissis tunicis suis, et clamaverunt voce magna, postulantes a Simone dextras sibi dari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 46, 'et dixerunt: Non nobis reddas secundum malitias nostras, sed secundum misericordias tuas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 47, 'Et flexus Simon, non debellavit eos: ejecit tamen eos de civitate, et mundavit ædes in quibus fuerant simulacra, et tunc intravit in eam cum hymnis benedicens Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 48, 'et ejecta ab ea omni immunditia, collocavit in ea viros qui legem facerent: et munivit eam, et fecit sibi habitationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 49, 'Qui autem erant in arce Jerusalem, prohibebantur egredi et ingredi regionem, et emere ac vendere: et esurierunt valde, et multi ex eis fame perierunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 50, 'et clamaverunt ad Simonem ut dextras acciperent: et dedit illis: et ejecit eos inde, et mundavit arcem a contaminationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 51, 'et intraverunt in eam tertia et vigesima die secundi mensis, anno centesimo septuagesimo primo, cum laude, et ramis palmarum, et cinyris, et cymbalis, et nablis, et hymnis, et canticis, quia contritus est inimicus magnus ex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 52, 'Et constituit ut omnibus annis agerentur dies hi cum lætitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 53, 'Et munivit montem templi, qui erat secus arcem, et habitavit ibi ipse, et qui cum eo erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 54, 'Et vidit Simon Joannem filium suum, quod fortis prælii vir esset: et posuit eum ducem virtutum universarum: et habitavit in Gazaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Anno centesimo septuagesimo secundo, congregavit rex Demetrius exercitum suum, et abiit in Mediam ad contrahenda sibi auxilia, ut expugnaret Tryphonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Et audivit Arsaces rex Persidis et Mediæ, quia intravit Demetrius confines suos: et misit unum de principibus suis ut comprehenderet eum vivum, et adduceret eum ad se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Et abiit, et percussit castra Demetrii: et comprehendit eum, et duxit eum ad Arsacem, et posuit eum in custodiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Et siluit omnis terra Juda omnibus diebus Simonis, et quæsivit bona genti suæ: et placuit illis potestas ejus et gloria ejus omnibus diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Et cum omni gloria sua accepit Joppen in portum, et fecit introitum in insulis maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Et dilatavit fines gentis suæ, et obtinuit regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Et congregavit captivitatem multam, et dominatus est Gazaræ, et Bethsuræ, et arci: et abstulit immunditias ex ea, et non erat qui resisteret ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Et unusquisque colebat terram suam cum pace: et terra Juda dabat fructus suos, et ligna camporum fructum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Seniores in plateis sedebant omnes, et de bonis terræ tractabant, et juvenes induebant se gloriam, et stolas belli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Et civitatibus tribuebat alimonias, et constituebat eas ut essent vasa munitionis quoadusque nominatum est nomen gloriæ ejus usque ad extremum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Fecit pacem super terram, et lætatus est Israël lætitia magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Et sedit unusquisque sub vite sua, et sub ficulnea sua: et non erat qui eos terreret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Defecit impugnans eos super terram: reges contriti sunt in diebus illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Et confirmavit omnes humiles populi sui, et legem exquisivit, et abstulit omnem iniquum et malum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'sancta glorificavit, et multiplicavit vasa sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Et auditum est Romæ quia defunctus esset Jonathas, et usque in Spartiatas: et contristati sunt valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Ut audierunt autem quod Simon frater ejus factus esset summus sacerdos loco ejus, et ipse obtineret omnem regionem, et civitates in ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'scripserunt ad eum in tabulis æreis, ut renovarent amicitias et societatem quam fecerant cum Juda et cum Jonatha, fratribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Et lectæ sunt in conspectu ecclesiæ in Jerusalem. Et hoc exemplum epistolarum, quas Spartiatæ miserunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Spartianorum principes et civitates, Simoni sacerdoti magno, et senioribus, et sacerdotibus, et reliquo populo Judæorum, fratribus, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Legati, qui missi sunt ad populum nostrum, nuntiaverunt nobis de vestra gloria, et honore, ac lætitia: et gavisi sumus in introitu eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Et scripsimus quæ ab eis erant dicta in conciliis populi, sic: Numenius Antiochi, et Antipater Jasonis filius, legati Judæorum, venerunt ad nos, renovantes nobiscum amicitiam pristinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Et placuit populo excipere viros gloriose, et ponere exemplum sermonum eorum in segregatis populi libris, ut sit ad memoriam populo Spartiatarum. Exemplum autem horum scripsimus Simoni magno sacerdoti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 24, 'Post hæc autem misit Simon Numenium Romam, habentem clypeum aureum magnum, pondo mnarum mille, ad statuendam cum eis societatem. Cum autem audisset populus Romanus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 25, 'sermones istos, dixerunt: Quam gratiarum actionem reddemus Simoni, et filiis ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 26, 'restituit enim ipse fratres suos, et expugnavit inimicos Israël ab eis, et statuerunt ei libertatem, et descripserunt in tabulis æreis, et posuerunt in titulis in monte Sion.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 27, 'Et hoc est exemplum scripturæ: Octavadecima die mensis Elul, anno centesimo septuagesimo secundo, anno tertio sub Simone sacerdote magno in Asaramel,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 28, 'in conventu magno sacerdotum, et populi, et principum gentis, et seniorum regionis, nota facta sunt hæc: quoniam frequenter facta sunt prælia in regione nostra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 29, 'Simon autem Mathathiæ filius, ex filiis Jarib, et fratres ejus, dederunt se periculo, et restiterunt adversariis gentis suæ, ut starent sancta ipsorum, et lex: et gloria magna glorificaverunt gentem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 30, 'Et congregavit Jonathas gentem suam, et factus est illis sacerdos magnus, et appositus est ad populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 31, 'Et voluerunt inimici eorum calcare et atterere regionem ipsorum, et extendere manus in sancta eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 32, 'Tunc restitit Simon, et pugnavit pro gente sua, et erogavit pecunias multas, et armavit viros virtutis gentis suæ, et dedit illis stipendia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 33, 'et munivit civitates Judææ, et Bethsuram, quæ erat in finibus Judææ, ubi erant arma hostium antea: et posuit illic præsidium viros Judæos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 34, 'Et Joppen munivit, quæ erat ad mare, et Gazaram, quæ est in finibus Azoti, in qua hostes antea habitabant: et collocavit illic Judæos, et quæcumque apta erant ad correptionem eorum, posuit in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 35, 'Et vidit populus actum Simonis, et gloriam quam cogitabat facere genti suæ, et posuerunt eum ducem suum, et principem sacerdotum, eo quod ipse fecerat hæc omnia, et justitiam, et fidem, quam conservavit genti suæ, et exquisivit omni modo exaltare populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 36, 'Et in diebus ejus prosperatum est in manibus ejus, ut tollerentur gentes de regione ipsorum, et qui in civitate David erant, in Jerusalem in arce, de qua procedebant, et contaminabant omnia quæ in circuitu sanctorum sunt, et inferebant plagam magnam castitati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 37, 'et collocavit in ea viros Judæos ad tutamentum regionis, et civitatis, et exaltavit muros Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 38, 'Et rex Demetrius statuit illi summum sacerdotium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 39, 'Secundum hæc fecit eum amicum suum, et glorificavit eum gloria magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 40, 'Audivit enim quod appellati sunt Judæi a Romanis amici, et socii, et fratres, et quia susceperunt legatos Simonis gloriose,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 41, 'et quia Judæi et sacerdotes eorum consenserunt eum esse ducem suum, et summum sacerdotem in æternum, donec surgat propheta fidelis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 42, 'et ut sit super eos dux, et ut cura esset illi pro sanctis, et ut constitueret præpositos super opera eorum, et super regionem, et super arma, et super præsidia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 43, 'et cura sit illi de sanctis: et ut audiatur ab omnibus, et scribantur in nomine ejus omnes conscriptiones in regione: et ut operiatur purpura et auro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 44, 'et ne liceat ulli ex populo et ex sacerdotibus irritum facere aliquid horum, et contradicere his quæ ab eo dicuntur, aut convocare conventum in regione sine ipso, et vestiri purpura, et uti fibula aurea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 45, 'qui autem fecerit extra hæc, aut irritum fecerit aliquid horum, reus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 46, 'Et complacuit omni populo statuere Simonem, et facere secundum verba ista.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 47, 'Et suscepit Simon, et placuit ei ut summo sacerdotio fungeretur, et esset dux et princeps gentis Judæorum, et sacerdotum, et præesset omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 48, 'Et scripturam istam dixerunt ponere in tabulis æreis, et ponere eas in peribolo sanctorum, in loco celebri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 49, 'exemplum autem eorum ponere in ærario, ut habeat Simon, et filii ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Et misit rex Antiochus filius Demetrii epistolas ab insulis maris Simoni sacerdoti, et principi gentis Judæorum, et universæ genti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'et erant continentes hunc modum: Rex Antiochus Simoni sacerdoti magno, et genti Judæorum salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Quoniam quidem pestilentes obtinuerunt regnum patrum nostrorum, volo autem vendicare regnum, et restituere illud sicut erat antea: et electam feci multitudinem exercitus, et feci naves bellicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Volo autem procedere per regionem ut ulciscar in eos, qui corruperunt regionem nostram, et qui desolaverunt civitates multas in regno meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Nunc ergo statuo tibi omnes oblationes, quas remiserunt tibi ante me omnes reges, et quæcumque alia dona remiserunt tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'et permitto tibi facere percussuram proprii numismatis in regione tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Jerusalem autem sanctam esse, et liberam: et omnia arma, quæ fabricata sunt, et præsidia, quæ construxisti, quæ tenes, maneant tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Et omne debitum regis, et quæ futura sunt regi, ex hoc et in totum tempus remittuntur tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Cum autem obtinuerimus regnum nostrum, glorificabimus te, et gentem tuam, et templum, gloria magna, ita ut manifestetur gloria vestra in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Anno centesimo septuagesimo quarto exiit Antiochus in terram patrum suorum, et convenerunt ad eum omnes exercitus, ita ut pauci relicti essent cum Tryphone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Et insecutus est eum Antiochus rex, et venit Doram fugiens per maritimam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'sciebat enim quod congregata sunt mala in eum, et reliquit eum exercitus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'et applicuit Antiochus super Doram cum centum viginti millibus virorum belligeratorum, et octo millibus equitum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'et circuivit civitatem, et naves a mari accesserunt: et vexabant civitatem a terra et mari, et neminem sinebant ingredi vel egredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Venit autem Numenius, et qui cum eo fuerant, ab urbe Roma, habentes epistolas regibus et regionibus scriptas, in quibus continebantur hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Lucius consul Romanorum, Ptolemæo regi salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Legati Judæorum venerunt ad nos amici nostri, renovantes pristinam amicitiam et societatem, missi a Simone principe sacerdotum et populo Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Attulerunt autem et clypeum aureum mnarum mille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Placuit itaque nobis scribere regibus et regionibus, ut non inferant illis mala, neque impugnent eos, et civitates eorum, et regiones eorum: et ut non ferant auxilium pugnantibus adversus eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Visum autem est nobis accipere ab eis clypeum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Si qui ergo pestilentes refugerunt de regione ipsorum ad vos, tradite eos Simoni principi sacerdotum, ut vindicet in eos secundum legem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Hæc eadem scripta sunt Demetrio regi, et Attalo, et Ariarathi, et Arsaci,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'et in omnes regiones: et Lampsaco, et Spartiatis, et in Delum, et in Myndum, et in Sicyonem, et in Cariam, et in Samum, et in Pamphyliam, et in Lyciam, et in Alicarnassum, et in Coo, et in Siden, et in Aradon, et in Rhodum, et in Phaselidem, et in Gortynam, et Gnidum, et Cyprum, et Cyrenen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Exemplum autem eorum scripserunt Simoni principi sacerdotum, et populo Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Antiochus autem rex applicuit castra in Doram secundo, admovens ei semper manus, et machinas faciens: et conclusit Tryphonem, ne procederet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'et misit ad eum Simon duo millia virorum electorum in auxilium, et argentum, et aurum, et vasa copiosa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'et noluit ea accipere, sed rupit omnia, quæ pactus est cum eo antea, et alienavit se ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Et misit ad eum Athenobium unum de amicis suis, ut tractaret cum ipso, dicens: Vos tenetis Joppen, et Gazaram, et arcem, quæ est in Jerusalem, civitates regni mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'fines earum desolastis, et fecistis plagam magnam in terra, et dominati estis per loca multa in regno meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Nunc ergo tradite civitates quas occupastis, et tributa locorum in quibus dominati estis extra fines Judææ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'sin autem, date pro illis quingenta talenta argenti, et exterminii, quod exterminastis, et tributorum civitatum alia talenta quingenta: sin autem, veniemus, et expugnabimus vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Et venit Athenobius amicus regis in Jerusalem, et vidit gloriam Simonis, et claritatem in auro, et argento, et apparatum copiosum: et obstupuit, et retulit ei verba regis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Et respondit ei Simon, et dixit ei: Neque alienam terram sumpsimus, neque aliena detinemus: sed hæreditatem patrum nostrorum, quæ injuste ab inimicis nostris aliquo tempore possessa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 34, 'Nos vero tempus habentes, vindicamus hæreditatem patrum nostrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 35, 'Nam de Joppe et Gazara quæ expostulas, ipsi faciebant in populo plagam magnam, et in regione nostra: horum damus talenta centum. Et non respondit ei Athenobius verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 36, 'Reversus autem cum ira ad regem, renuntiavit ei verba ista, et gloriam Simonis, et universa quæ vidit, et iratus est rex ira magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 37, 'Tryphon autem fugit navi in Orthosiada.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 38, 'Et constituit rex Cendebæum ducem maritimum, et exercitum peditum et equitum dedit illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 39, 'Et mandavit illi movere castra contra faciem Judææ: et mandavit ei ædificare Gedorem, et obstruere portas civitatis, et debellare populum. Rex autem persequebatur Typhonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 40, 'Et pervenit Cendebæus Jamniam, et cœpit irritare plebem, et conculcare Judæam, et captivare populum, et interficere, et ædificare Gedorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 41, 'Et collocavit illic equites et exercitum, ut egressi perambularent viam Judææ, sicut constituit ei rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Et ascendit Joannes de Gazaris, et nuntiavit Simoni patri suo quæ fecit Cendebæus in populo ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Et vocavit Simon duos filios seniores, Judam et Joannem, et ait illis: Ego, et fratres mei, et domus patris mei expugnavimus hostes Israël ab adolescentia usque in hunc diem: et prosperatum est in manibus nostris liberare Israël aliquoties.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Nunc autem senui: sed estote loco meo, et fratres mei, et egressi pugnate pro gente nostra: auxilium vero de cælo vobiscum sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Et elegit de regione viginti millia virorum belligeratorum, et equites: et profecti sunt ad Cendebæum, et dormierunt in Modin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Et surrexerunt mane, et abierunt in campum: et ecce exercitus copiosus in obviam illis peditum et equitum: et fluvius torrens erat inter medium ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Et admovit castra contra faciem eorum ipse et populus ejus, et vidit populum trepidantem ad transfretandum torrentem: et transfretavit primus, et viderunt eum viri, et transierunt post eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Et divisit populum et equites in medio peditum: erat autem equitatus adversariorum copiosus nimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Et exclamaverunt sacris tubis, et in fugam conversus est Cendebæus et castra ejus: et ceciderunt ex eis multi vulnerati: residui autem in munitionem fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Tunc vulneratus est Judas frater Joannis: Joannes autem insecutus est eos, donec venit Cedronem, quam ædificavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'et fugerunt usque ad turres, quæ erant in agris Azoti, et succendit eas igni. Et ceciderunt ex illis duo millia virorum, et reversus est in Judæam in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Et Ptolemæus filius Abobi constitutus erat dux in campo Jericho, et habebat argentum et aurum multum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'erat enim gener summi sacerdotis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Et exaltatum est cor ejus, et volebat obtinere regionem, et cogitabat dolum adversus Simonem et filios ejus, ut tolleret eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Simon autem, perambulans civitates quæ erant in regione Judææ, et sollicitudinem gerens earum, descendit in Jericho ipse, et Mathathias filius ejus, et Judas, anno centesimo septuagesimo septimo, mense undecimo: hic est mensis Sabath.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Et suscepit eos filius Abobi in munitiunculam, quæ vocatur Doch, cum dolo, quam ædificavit: et fecit eis convivium magnum, et abscondit illic viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Et cum inebriatus esset Simon et filii ejus, surrexit Ptolemæus cum suis, et sumpserunt arma sua, et intraverunt in convivium: et occiderunt eum, et duos filios ejus, et quosdam pueros ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'et fecit deceptionem magnam in Israël, et reddidit mala pro bonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Et scripsit hæc Ptolemæus, et misit regi ut mitteret ei exercitum in auxilium, et traderet ei regionem, et civitates eorum, et tributa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Et misit alios in Gazaram tollere Joannem: et tribunis misit epistolas, ut venirent ad se, et daret eis argentum, et aurum, et dona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Et alios misit occupare Jerusalem et montem templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Et præcurrens quidam, nuntiavit Joanni in Gazara quia periit pater ejus et fratres ejus, et quia misit te quoque interfici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Ut audivit autem, vehementer expavit: et comprehendit viros, qui venerant perdere eum, et occidit eos: cognovit enim quia quærebant eum perdere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Et cetera sermonum Joannis, et bellorum ejus, et bonarum virtutum, quibus fortiter gessit, et ædificii murorum, quos exstruxit, et rerum gestarum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'ecce hæc scripta sunt in libro dierum sacerdotii ejus, ex quo factus est princeps sacerdotum post patrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Fratribus qui sunt per \'gyptum Judæis, salutem dicunt fratres qui sunt in Jerosolymis Judæi, et qui in regione Judææ, et pacem bonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Benefaciat vobis Deus, et meminerit testamenti sui, quod locutus est ad Abraham, et Isaac, et Jacob servorum suorum fidelium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'et det vobis cor omnibus ut colatis eum, et faciatis ejus voluntatem, corde magno et animo volenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Adaperiat cor vestrum in lege sua, et in præceptis suis, et faciat pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Exaudiat orationes vestras, et reconcilietur vobis, nec vos deserat in tempore malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Et nunc hic sumus orantes pro vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Regnante Demetrio, anno centesimo sexagesimo nono, nos Judæi scripsimus vobis in tribulatione et impetu qui supervenit nobis in istis annis, ex quo recessit Jason a sancta terra, et a regno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Portam succenderunt, et effuderunt sanguinem innocentem: et oravimus ad Dominum, et exauditi sumus, et obtulimus sacrificium et similaginem, et accendimus lucernas, et proposuimus panes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Et nunc frequentate dies scenopegiæ mensis Casleu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Anno centesimo octogesimo octavo, populus qui est Jerosolymis et in Judæa, senatusque et Judas, Aristobolo magistro Ptolemæi regis, qui est de genere christorum sacerdotum, et his qui in \'gypto sunt Judæis, salutem et sanitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'De magnis periculis a Deo liberati, magnifice gratias agimus ipsi, utpote qui adversus talem regem dimicavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ipse enim ebullire fecit de Perside eos qui pugnaverunt contra nos et sanctam civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Nam cum in Perside esset dux ipse, et cum ipso immensus exercitus, cecidit in templo Naneæ, consilio deceptus sacerdotum Naneæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Etenim cum ea habitaturus venit ad locum Antiochus et amici ejus, et ut acciperet pecunias multas dotis nomine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Cumque proposuissent eas sacerdotes Naneæ, et ipse cum paucis ingressus esset intra ambitum fani, clauserunt templum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'cum intrasset Antiochus: apertoque occulto aditu templi, mittentes lapides percusserunt ducem et eos qui cum eo erant: et diviserunt membratim, et capitibus amputatis foras projecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Per omnia benedictus Deus, qui tradidit impios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Facturi igitur quinta et vigesima die mensis Casleu purificationem templi, necessarium duximus significare vobis: ut et vos quoque agatis diem scenopegiæ, et diem ignis, qui datus est quando Nehemias ædificato templo et altari obtulit sacrificia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Nam cum in Persidem ducerentur patres nostri, sacerdotes qui tunc cultores Dei erant, acceptum ignem de altari occulte absconderunt in valle, ubi erat puteus altus et siccus, et in eo contutati sunt eum, ita ut omnibus ignotus esset locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Cum autem præterissent anni multi, et placuit Deo ut mitteretur Nehemias a rege Persidis, nepotes sacerdotum illorum qui absconderant, misit ad requirendum ignem: et sicut narraverunt nobis, non invenerunt ignem, sed aquam crassam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Et jussit eos haurire, et afferre sibi: et sacrificia quæ imposita erant, jussit sacerdos Nehemias aspergi ipsa aqua: et ligna, et quæ erant superposita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Utque hoc factum est, et tempus affuit quo sol refulsit, qui prius erat in nubilo, accensus est ignis magnus, ita ut omnes mirarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Orationem autem faciebant omnes sacerdotes, dum consummaretur sacrificium, Jonatha inchoante, ceteris autem respondentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Et Nehemiæ erat oratio hunc habens modum: Domine Deus omnium creator, terribilis et fortis, justus et misericors, qui solus est bonus rex,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'solus præstans, solus justus et omnipotens et æternus, qui liberas Israël de omni malo; qui fecisti patres electos, et sanctificasti eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'accipe sacrificium pro universo populo tuo Israël, et custodi partem tuam, et sanctifica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Congrega dispersionem nostram, libera eos qui serviunt gentibus, et contemptos et abominatos respice, ut sciant gentes quia tu es Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Afflige opprimentes nos, et contumeliam facientes in superbia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Constitue populum tuum in loco sancto tuo, sicut dixit Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Sacerdotes autem psallebant hymnos usquequo consumptum esset sacrificium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Cum autem consumptum esset sacrificium, ex residua aqua Nehemias jussit lapides majores perfundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 32, 'Quod ut factum est, ex eis flamma accensa est: sed ex lumine quod refulsit ab altari, consumpta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 33, 'Ut vero manifestata est res, renuntiatum est regi Persarum quod in loco in quo ignem absconderent hi qui translati fuerant sacerdotes, aqua apparuit, de qua Nehemias, et qui cum eo erant, purificaverunt sacrificia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 34, 'Considerans autem rex, et rem diligenter examinans, fecit ei templum, ut probaret quod factum erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 35, 'et cum probasset, sacerdotibus donavit multa bona, et alia atque alia munera: et accipiens manu sua, tribuebat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 36, 'Appellavit autem Nehemias hunc locum Nephthar, quod interpretatur Purificatio: vocatur autem apud plures Nephi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Invenitur autem in descriptionibus Jeremiæ prophetæ, quod jussit eos ignem accipere qui transmigrabant, ut significatum est, et ut mandavit transmigratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Et dedit illis legem, ne obliviscerentur præcepta Domini, et non exerrarent mentibus, videntes simulacra aurea et argentea, et ornamenta eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Et alia hujusmodi dicens, hortabatur ne legem amoverent a corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Erat autem in ipsa scriptura, quomodo tabernaculum et arcam jussit propheta divino responso ad se facto comitari secum, usquequo exiit in montem in quo Moyses ascendit, et vidit Dei hæreditatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Et veniens ibi Jeremias, invenit locum speluncæ: et tabernaculum, et arcam, et altare incensi intulit illuc, et ostium obstruxit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Et accesserunt quidam simul, qui sequebantur, ut notarent sibi locum: et non potuerunt invenire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Ut autem cognovit Jeremias, culpans illos dixit: Quod ignotus erit locus donec congreget Deus congregationem populi, et propitius fiat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'et tunc Dominus ostendet hæc, et apparebit majestas Domini, et nubes erit, sicut et Moysi manifestabatur, et sicut cum Salomon petiit ut locus sanctificaretur magno Deo, manifestabat hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Magnifice etenim sapientiam tractabat: et ut sapientiam habens, obtulit sacrificium dedicationis et consummationis templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Sicut et Moyses orabat ad Dominum, et descendit ignis de cælo et consumpsit holocaustum, sic et Salomon oravit, et descendit ignis de cælo et consumpsit holocaustum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Et dixit Moyses: Eo quod non sit comestum quod erat pro peccato, consumptum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Similiter et Salomon octo diebus celebravit dedicationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Inferebantur autem in descriptionibus et commentariis Nehemiæ hæc eadem: et ut construens bibliothecam congregavit de regionibus libros et prophetarum et David, et epistolas regum, et de donariis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Similiter autem et Judas ea quæ deciderant per bellum quod nobis acciderat, congregavit omnia, et sunt apud nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Si ergo desideratis hæc, mittite qui perferant vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Acturi itaque purificationem scripsimus vobis: bene ergo facietis, si egeritis hos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 17, 'Deus autem, qui liberavit populum suum, et reddidit hæreditatem omnibus, et regnum, et sacerdotium, et sanctificationem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 18, 'sicut promisit in lege, speramus quod cito nostri miserebitur, et congregavit de sub cælo in locum sanctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 19, 'Eripuit enim nos de magnis periculis, et locum purgavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 20, 'De Juda vero Machabæo, et fratribus ejus, et de templi magni purificatione, et de aræ dedicatione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 21, 'sed et de præliis quæ pertinent ad Antiochum Nobilem et filium ejus Eupatorem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 22, 'et de illuminationibus quæ de cælo factæ sunt ad eos qui pro Judæis fortiter fecerunt, ita ut universam regionem, cum pauci essent, vindicarent, et barbaram multitudinem fugarent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 23, 'et famosissimum in toto orbe templum recuperarent, et civitatem liberarent, et leges quæ abolitæ erant, restituerentur, Domino cum omni tranquillitate propitio facto illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 24, 'Itemque ab Jasone Cyrenæo quinque libris comprehensa tentavimus nos uno volumine breviare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 25, 'Considerantes enim multitudinem librorum, et difficultatem volentibus aggredi narrationes historiarum propter multitudinem rerum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 26, 'curavimus volentibus quidem legere, ut esset animi oblectatio: studiosis vero, ut facilius possint memoriæ commendare: omnibus autem legentibus utilitas conferatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 27, 'Et nobis quidem ipsis, qui hoc opus breviandi causa suscepimus, non facilem laborem, immo vero negotium plenum vigiliarum et sudoris assumpsimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 28, 'Sicut hi qui præparant convivium, et quærunt aliorum voluntati parere propter multorum gratiam, libenter laborem sustinemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 29, 'Veritatem quidem de singulis auctoribus concedentes, ipsi autem secundum datam formam brevitati studentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 30, 'Sicut enim novæ domus architecto de universa structura curandum est; ei vero qui pingere curat, quæ apta sunt ad ornatum exquirenda sunt: ita æstimandum est et in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 31, 'Etenim intellectum colligere, et ordinare sermonem, et curiosius partes singulas quasque disquirere, historiæ congruit auctori:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 32, 'brevitatem vero dictionis sectari, et executiones rerum vitare, brevianti concedendum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 33, 'Hinc ergo narrationem incipiemus: de præfatione tantum dixisse sufficiat. Stultum etenim est ante historiam effluere, in ipsa autem historia succingi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Igitur cum sancta civitas habitaretur in omni pace, leges etiam adhuc optime custodirentur, propter Oniæ pontificis pietatem, et animos odio habentes mala,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'fiebat ut et ipsi reges et principes locum summo honore dignum ducerent, et templum maximis muneribus illustrarent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'ita ut Seleucus Asiæ rex de redditibus suis præstaret omnes sumptus ad ministerium sacrificiorum pertinentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Simon autem de tribu Benjamin, præpositus templi constitutus, contendebat, obsistente sibi principe sacerdotum, iniquum aliquid in civitate moliri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Sed cum vincere Oniam non posset, venit ad Apollonium Tharsææ filium, qui eo tempore erat dux Cœlesyriæ et Phœnicis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'et nuntiavit ei pecuniis innumerabilibus plenum esse ærarium Jerosolymis, et communes copias immensas esse, quæ non pertinent ad rationem sacrificiorum: esse autem possibile sub potestate regis cadere universa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Cumque retulisset ad regem Apollonius de pecuniis quæ delatæ erant, illæ accitum Heliodorum, qui erat super negotia ejus, misit, cum mandatis ut prædictam pecuniam transportaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Statimque Heliodorus iter est agressus, specie quidem quasi per Cœlesyriam et Phœnicen civitates esset peragraturus, re vera autem regis propositum perfecturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Sed cum venisset Jerosolymam, et benigne a summo sacerdote in civitate esset exceptus, narravit de dato indicio pecuniarum, et cujus rei gratia adesset, aperuit: interrogabat autem si vere hæc ita essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Tunc summus sacerdos ostendit deposita esse hæc, et victualia viduarum et pupillorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'quædam vero esse Hircani Tobiæ viri valde eminentis, in his quæ detulerat impius Simon: universa autem argenti talenta esse quadringenta, et auri ducenta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'decipi vero eos qui credidissent loco et templo quod per universum mundum honoratur pro sui veneratione et sanctitate, omnino impossibile esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'At ille pro his quæ habebat in mandatis a rege, dicebat omni genere regi ea esse deferenda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Constituta autem die, intrabat de his Heliodorus ordinaturus. Non modica vero per universam civitatem erat trepidatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Sacerdotes autem ante altare cum stolis sacerdotalibus jactaverunt se, et invocabant de cælo eum qui de depositis legem posuit, ut his qui deposuerant ea salva custodiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Jam vero qui videbat summi sacerdotis vultum, mente vulnerabatur: facies enim et color immutatus declarabat internum animi dolorem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'circumfusa enim erat mœstitia quædam viro, et horror corporis, per quem manifestus aspicientibus dolor cordis ejus efficiebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Alii etiam gregatim de domibus confluebant, publica supplicatione obsecrantes, pro eo quod in contemptum locus esset venturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Accinctæque mulieres ciliciis pectus, per plateas confluebant: sed et virgines quæ conclusæ erant, procurrebant ad Oniam, aliæ autem ad muros, quædam vero per fenestras aspiciebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'universæ autem protendentes manus in cælum, deprecabantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'erat enim misera commistæ multitudinis, et magni sacerdotis in agone constituti exspectatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Et hi quidem invocabant omnipotentem Deum, ut credita sibi his qui crediderant, cum omni integritate conservarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Heliodorus autem, quod decreverat, perficiebat eodem loco ipse cum satellitibus circa ærarium præsens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 24, 'Sed spiritus omnipotentis Dei magnam fecit suæ ostensionis evidentiam, ita ut omnes qui ausi fuerant parere ei, ruentes Dei virtute, in dissolutionem et formidinem converterentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 25, 'Apparuit enim illis quidam equus terribilem habens sessorem, optimis operimentis adornatus: isque cum impetu Heliodoro priores calces elisit: qui autem ei sedebat, videbatur arma habere aurea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 26, 'Alii etiam apparuerunt duo juvenes virtute decori, optimi gloria, speciosique amictu: qui circumsteterunt eum, et ex utraque parte flagellabant, sine intermissione multis plagis verberantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 27, 'Subito autem Heliodorus concidit in terram, eumque multa caligine circumfusum rapuerunt, atque in sella gestatoria positum ejecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 28, 'Et is, qui cum multis cursoribus et satellitibus prædictum ingressus est ærarium, portabatur nullo sibi auxilium ferente, manifesta Dei cognita virtute:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 29, 'et ille quidem per divinam virtutem jacebat mutus, atque omni spe et salute privatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 30, 'Hi autem Dominum benedicebant, quia magnificabat locum suum: et templum, quod paulo ante timore ac tumultu erat plenum, apparente omnipotente Domino, gaudio et lætitia impletum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 31, 'Tunc vero ex amicis Heliodori quidam rogabant confestim Oniam, ut invocaret Altissimum ut vitam donaret ei qui in supremo spiritu erat constitutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 32, 'Considerans autem summus sacerdos ne forte rex suspicaretur malitiam aliquam ex Judæis circa Heliodorum consummatum, obtulit pro salute viri hostiam salutarem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 33, 'Cumque summus sacerdos exoraret, iidem juvenes eisdem vestibus amicti astantes Heliodoro, dixerunt: Oniæ sacerdoti gratias age: nam propter eum Dominus tibi vitam donavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 34, 'Tu autem a Deo flagellatus, nuntia omnibus magnalia Dei, et potestatem. Et his dictis, non comparuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 35, 'Heliodorus autem, hostia Deo oblata, et votis magnis promissis ei qui vivere illi concessit, et Oniæ gratias agens, recepto exercitu, repedabat ad regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 36, 'Testabatur autem omnibus ea quæ sub oculis suis viderat opera magni Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 37, 'Cum autem rex interrogasset Heliodorum, quis esset aptus adhuc semel Jerosolymam mitti, ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 38, 'Si quem habes hostem, aut regni tui insidiatorem, mitte illuc, et flagellatum eum recipies, si tamen evaserit: eo quod in loco sit vere Dei quædam virtus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 39, 'Nam ipse, qui habet in cælis habitationem, visitator et adjutor est loci illius, et venientes ad malefaciendum percutit ac perdit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 40, 'Igitur de Heliodoro et ærarii custodia ita res se habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Simon autem prædictus, pecuniarum et patriæ delator, male loquebatur de Onia, tamquam ipse Heliodorum instigasset ad hæc, et ipse fuisset incentor malorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'provisoremque civitatis, ac defensorem gentis suæ, et æmulatorem legis Dei, audebat insidiatorem regni dicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Sed cum inimicitiæ in tantum procederent ut etiam per quosdam Simonis necessarios homicidia fierent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'considerans Onias periculum contentionis, et Apollonium insanire, utpote ducem Cœlesyriæ et Phœnicis, ad augendam malitiam Simonis ad regem se contulit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'non ut civium accusator, sed communem utilitatem apud semetipsum universæ multitudinis considerans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Videbat enim sine regali providentia impossibile esse pacem rebus dari, nec Simonem posse cessare a stultitia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Sed post Seleuci vitæ excessum, cum suscepisset regnum Antiochus, qui Nobilis appellabatur, ambiebat Jason frater Oniæ summum sacerdotium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'adito rege, promittens ei argenti talenta trecenta sexaginta, et ex redditibus aliis talenta octoginta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'super hæc promittebat et alia centum quinquaginta, si potestati ejus concederetur, gymnasium et ephebiam sibi constituere, et eos qui in Jerosolymis erant, Antiochenos scribere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Quod cum rex annuisset, et obtinuisset principatum, statim ad gentilem ritum contribules suos transferre cœpit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'et amotis his quæ humanitatis causa Judæis a regibus fuerant constituta per Joannem patrem Eupolemi, qui apud Romanos de amicitia et societate functus est legatione legitima, civium jura destituens, prava instituta sanciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Etenim ausus est sub ipsa arce gymnasium constituere, et optimos quosque epheborum in lupanaribus ponere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Erat autem hoc non initium, sed incrementum quoddam, et profectus gentilis et alienigenæ conversationis, propter impii et non sacerdotis Jasonis nefarium, et inauditum scelus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'ita ut sacerdotes jam non circa altaris officia dediti essent, sed contempto templo et sacrificiis neglectis, festinarent participes fieri palæstræ et præbitionis ejus injustæ, et in exercitiis disci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Et patrios quidem honores nihil habentes, græcas glorias optimas arbitrabantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'quarum gratia periculosa eos contentio habebat, et eorum instituta æmulabantur, ac per omnia his consimiles esse cupiebant, quos hostes et peremptores habuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'In leges enim divinas impie agere impune non cedit: sed hoc tempus sequens declarabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Cum autem quinquennalis agon Tyri celebraretur, et rex præsens esset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'misit Jason facinorosus ab Jerosolymis viros peccatores, portantes argenti didrachmas trecentas in sacrificum Herculis: quas postulaverunt hi qui asportaverant ne in sacrificiis erogarentur, quia non oporteret, sed in alios sumptus eas deputari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Sed hæ oblatæ sunt quidem ab eo qui miserat in sacrificium Herculis: propter præsentes autem datæ sunt in fabricam navium triremium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Misso autem in \'gyptum Apollonio Mnesthei filio propter primates Ptolemæi Philometoris regis, cum cognovisset Antiochus alienum se a negotiis regni effectum, propriis utilitatibus consulens, profectus inde venit Joppen, et inde Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 22, 'Et magnifice ab Jasone et civitate susceptus, cum facularum luminibus et laudibus ingressus est: et inde in Phœnicen exercitum convertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 23, 'Et post triennii tempus, misit Jason Menelaum supradicti Simonis fratrem portantem pecunias regi, et de negotiis necessariis responsa perlaturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 24, 'At ille commendatus regi, cum magnificasset faciem potestatis ejus, in semetipsum retorsit summum sacerdotium, superponens Jasoni talenta argenti trecenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 25, 'Acceptisque a rege mandatis, venit, nihil quidem habens dignum sacerdotio: animos vero crudelis tyranni, et feræ beluæ iram gerens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 26, 'Et Jason quidem, qui proprium fratrem captivaverat, ipse deceptus profugus in Ammanitem expulsus est regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 27, 'Menelaus autem principatum quidem obtinuit: de pecuniis vero regi promissis, nihil agebat, cum exactionem faceret Sostratus, qui arci erat præpositus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 28, 'nam ad hunc exactio vectigalium pertinebant: quam ob causam utrique ad regem sunt evocati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 29, 'Et Menelaus amotus est a sacerdotio, succedente Lysimacho fratre suo: Sostratus autem prælatus est Cypriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 30, 'Et cum hæc agerentur, contigit Tharsenses et Mallotas seditionem movere, eo quod Antiochidi regis concubinæ dono essent dati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 31, 'Festinanter itaque rex venit sedare illos, relicto suffecto uno ex comitibus suis Andronico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 32, 'Ratus autem Menelaus accepisse se tempus opportunum, aurea quædam vasa e templo furatus donavit Andronico, et alia vendiderat Tyri, et per vicinas civitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 33, 'Quod cum certissime cognovisset Onias, arguebat eum, ipse in loco tuto se continens Antiochiæ secus Daphnem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 34, 'Unde Menelaus accedens ad Andronicum, rogabat ut Oniam interficeret. Qui cum venisset ad Oniam, et datis dextris cum jurejurando (quamvis esset ei suspectus) suasisset de asylo procedere, statim eum peremit, non veritus justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 35, 'Ob quam causam non solum Judæi, sed aliæ quoque nationes indignabantur, et moleste ferebant de nece tanti viri injusta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 36, 'Sed regressum regem de Ciliciæ locis adierunt Judæi apud Antiochiam, simul et Græci, conquerentes de iniqua nece Oniæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 37, 'Contristatus itaque animo Antiochus propter Oniam, et flexus ad misericordiam, lacrimas fudit, recordatus defuncti sobrietatem et modestiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 38, 'accensisque animis Andronicum purpura exutum, per totam civitatem jubet circumduci: et in eodem loco in quo in Oniam impietatem commiserat, sacrilegum vita privari, Domino illi condignam retribuente pœnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 39, 'Multis autem sacrilegiis in templo a Lysimacho commissis Menelai consilio, et divulgata fama, congregata est multitudo adversum Lysimachum multo jam auro exportato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 40, 'Turbis autem insurgentibus, et animis ira repletis, Lysimachus armatis fere tribus millibus iniquis manibus uti cœpit, duce quodam tyranno, ætate pariter et dementia provecto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 41, 'Sed ut intellexerunt conatum Lysimachi, alii lapides, alii fustes validos arripuere: quidam vero cinerem in Lysimachum jecere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 42, 'Et multi quidem vulnerati, quidam autem et prostrati, omnes vero in fugam conversi sunt: ipsum etiam sacrilegum secus ærarium interfecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 43, 'De his ergo cœpit judicium adversus Menelaum agitari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 44, 'Et cum venisset rex Tyrum, ad ipsum negotium detulerunt missi tres viri a senioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 45, 'Et cum superaretur Menelaus, promisit Ptolemæo multas pecunias dare ad suadendum regi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 46, 'Itaque Ptolemæus in quodam atrio positum quasi refrigerandi gratia regem adiit, et deduxit a sententia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 47, 'et Menelaum quidem universæ malitiæ reum criminibus absolvit: miseros autem qui, etiamsi apud Scythas causam dixissent, innocentes judicarentur, hos morte damnavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 48, 'Cito ergo injustam pœnam dederunt, qui pro civitate, et populo, et sacris vasis causam prosecuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 49, 'Quam ob rem Tyrii quoque indignati, erga sepulturam eorum liberalissimi extiterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 50, 'Menelaus autem, propter eorum qui in potentia erant avaritiam, permanebat in potestate, crescens in malitia ad insidias civium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Eodem tempore, Antiochus secundam profectionem paravit in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Contigit autem per universam Jerosolymorum civitatem videri diebus quadraginta per aëra equites discurrentes, auratas stolas habentes et hastis, quasi cohortes armatos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'et cursus equorum per ordines digestos, et congressiones fieri cominus, et scutorum motus, et galeatorum multitudinem gladiis districtis, et telorum jactus, et aureorum armorum splendorem, omnisque generis loricarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Quapropter omnes rogabant in bonum monstra converti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Sed cum falsus rumor exisset, tamquam vita excessisset Antiochus, assumptis Jason non minus mille viris, repente agressus est civitatem: et civibus ad murum convolantibus ad ultimum apprehensa civitate, Menelaus fugit in arcem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Jason vero non parcebat in cæde civibus suis, nec cogitabat prosperitatem adversum cognatos malum esse maximum, arbitrans hostium et non civium se trophæa capturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Et principatum quidem non obtinuit, finem vero insidiarum suarum confusionem accepit, et profugus iterum abiit in Ammanitem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Ad ultimum, in exitium sui conclusus ab Areta Arabum tyranno fugiens de civitate in civitatem, omnibus odiosus, ut refuga legum et execrabilis, ut patriæ et civium hostis, in \'gyptum extrusus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'et qui multos de patria sua expulerat, peregre periit, Lacedæmonas profectus, quasi pro cognatione ibi refugium habiturus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'et qui insepultos multos abjecerat, ipse et illamentatus et insepultus abjicitur, sepultura neque peregrina usus, neque patrio sepulchro participans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'His itaque gestis, suspicatus est rex societatem deserturos Judæos: et ob hoc profectus ex \'gypto efferatis animis, civitatem quidem armis cepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Jussit autem militibus interficere, nec parcere occursantibus, et per domos ascendentes trucidare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Fiebant ergo cædes juvenum ac seniorum, et mulierum et natorum exterminia, virginumque et parvulorum neces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 14, 'Erant autem toto triduo octoginta millia interfecti, quadraginta millia vincti, non minus autem venundati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 15, 'Sed nec ista sufficiunt: ausus est etiam intrare templum universa terra sanctius, Menelao ductore, qui legum et patriæ fuit proditor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 16, 'et scelestis manibus sumens sancta vasa, quæ ab aliis regibus et civitatibus erant posita ad ornatum loci, et gloriam, contrectabat indigne, et contaminabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 17, 'Ita alienatus mente Antiochus, non considerabat quod propter peccata habitantium civitatem, modicum Deus fuerat iratus: propter quod et accidit circa locum despectio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 18, 'alioquin nisi contigisset eos multis peccatis esse involutos, sicut Heliodorus, qui missus est a Seleuco rege ad expoliandum ærarium, etiam hic statim adveniens flagellatus, et repulsus utique fuisset ab audacia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 19, 'Verum non propter locum, gentem: sed propter gentem, locum Deus elegit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 20, 'Ideoque et ipse locus particeps factus est populi malorum: postea autem fiet socius bonorum, et qui derelictus in ira Dei omnipotentis est, iterum in magni Domini reconciliatione cum summa gloria exaltabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 21, 'Igitur Antiochus mille et octingentis ablatis de templo talentis, velociter Antiochiam regressus est, existimans se præ superbia terram ad navigandum, pelagus vero ad iter agendum deducturum propter mentis elationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 22, 'Reliquit autem et præpositos ad affligendam gentem: Jerosolymis quidem Philippum genere Phrygem, moribus crudeliorem eo ipso a quo constitutus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 23, 'in Garizim autem Andronicum et Menelaum, qui gravius quam ceteri imminebant civibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 24, 'Cumque appositus esset contra Judæos, misit odiosum principem Apollonium cum exercitu viginti et duobus millibus, præcipiens ei omnes perfectæ ætatis interficere, mulieres ac juvenes vendere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 25, 'Qui cum venisset Jerosolymam, pacem simulans, quievit usque ad diem sanctum sabbati: et tunc feriatis Judæis arma capere suis præcepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 26, 'Omnesque qui ad spectaculum processerant, trucidavit: et civitatem cum armatis discurrens, ingentem multitudinem peremit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 27, 'Judas autem Machabæus, qui decimus fuerat, secesserat in desertum locum, ibique inter feras vitam in montibus cum suis agebat: et fœni cibo vescentes, demorabantur, ne participes essent coinquinationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Sed non post multum temporis, misit rex senem quemdam Antiochenum, qui compelleret Judæos ut se transferrent a patriis et Dei legibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'contaminare etiam quod in Jerosolymis erat templum, et cognominare Jovis Olympii: et in Garizim, prout erant hi qui locum inhabitabant, Jovis hospitalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Pessima autem et universis gravis erat malorum incursio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'nam templum luxuria et comessationibus gentium erat plenum, et scortantium cum meretricibus: sacratisque ædibus mulieres se ultro ingerebant, intro ferentes ea quæ non licebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Altare etiam plenum erat illicitis, quæ legibus prohibebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Neque autem sabbata custodiebantur, neque dies solemnes patrii servabantur, nec simpliciter Judæum se esse quisquam confitebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Ducebantur autem cum amara necessitate in die natalis regis ad sacrificia: et cum Liberi sacra celebrarentur, cogebantur hedera coronati Libero circuire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Decretum autem exiit in proximas gentilium civitates, suggerentibus Ptolemæis, ut pari modo et ipsi adversus Judæos agerent, ut sacrificarent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'eos autem qui nollent transire ad instituta gentium, interficerent: erat ergo videre miseriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Duæ enim mulieres delatæ sunt natos suos circumcidisse: quas, infantibus ad ubera suspensis, cum publice per civitatem circumduxissent, per muros præcipitaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Alii vero, ad proximas coëuntes speluncas, et latenter sabbati diem celebrantes, cum indicati essent Philippo, flammis succensi sunt, eo quod verebantur propter religionem et observantiam manu sibimet auxilium ferre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Obsecro autem eos qui hunc librum lecturi sunt, ne abhorrescant propter adversos casus: sed reputent ea quæ acciderunt, non ad interitum, sed ad correptionem esse generis nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Etenim multo tempore non sinere peccatoribus ex sententia agere, sed statim ultiones adhibere, magni beneficii est indicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Non enim, sicut in aliis nationibus, Dominus patienter exspectat, ut eas cum judicii dies advenerit, in plenitudine peccatorum puniat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'ita et in nobis statuit ut, peccatis nostris in finem devolutis, ita demum in nos vindicet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Propter quod numquam quidem a nobis misericordiam suam amovet: corripiens vero in adversis, populum suum non dereliquit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Sed hæc nobis ad commonitionem legentium dicta sint paucis. Jam enim veniendum est ad narrationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Igitur Eleazarus, unus de primoribus scribarum, vir ætate provectus, et vultu decorus, aperto ore hians compellebatur carnem porcinam manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'At ille gloriosissimam mortem magis quam odibilem vitam complectens, voluntarie præibat ad supplicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Intuens autem quemadmodum oporteret accedere, patienter sustinens, destinavit non admittere illicita propter vitæ amorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 21, 'Hi autem qui astabant, iniqua miseratione commoti propter antiquam viri amicitiam, tollentes eum secreto rogabant afferri carnes quibus vesci ei licebat, ut simularetur manducasse sicut rex imperaverat de sacrificii carnibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 22, 'ut hoc facto, a morte liberaretur: et propter veterem viri amicitiam, hanc in eo faciebant humanitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 23, 'At ille cogitare cœpit ætatis ac senectutis suæ eminentiam dignam, et ingenitæ nobilitatis canitiem, atque a puero optimæ conversationis actus: et secundum sanctæ et a Deo conditæ legis constituta, respondit cito, dicens præmitti se velle in infernum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 24, 'Non enim ætati nostræ dignum est, inquit, fingere: ut multi adolescentium, arbitrantes Eleazarum nonaginta annorum transisse ad vitam alienigenarum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 25, 'et ipsi propter meam simulationem, et propter modicum corruptibilis vitæ tempus decipiantur, et per hoc maculam atque execrationem meæ senectuti conquiram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 26, 'Nam etsi in præsenti tempore suppliciis hominum eripiar, sed manum Omnipotentis nec vivus, nec defunctus, effugiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 27, 'Quam ob rem fortiter vita excedendo, senectute quidem dignus apparebo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 28, 'adolescentibus autem exemplum forte relinquam, si prompto animo ac fortiter pro gravissimis ac sanctissimis legibus honesta morte perfungar. His dictis, confestim ad supplicium trahebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 29, 'Hi autem qui eum ducebant, et paulo ante fuerant mitiores, in iram conversi sunt propter sermones ab eo dictos, quos illi per arrogantiam prolatos arbitrabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 30, 'Sed cum plagis perimeretur, ingemuit, et dixit: Domine, qui habes sanctam scientiam, manifeste tu scis quia cum a morte possem liberari, duros corporis sustineo dolores: secundum animam vero propter timorem tuum libenter hæc patior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 31, 'Et iste quidem hoc modo vita decessit, non solum juvenibus, sed et universæ genti memoriam mortis suæ ad exemplum virtutis et fortitudinis derelinquens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Contigit autem et septem fratres una cum matre sua apprehensos compelli a rege edere contra fas carnes porcinas, flagris et taureis cruciatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Unus autem ex illis, qui erat primus, sic ait: Quid quæris, et quid vis discere a nobis? parati sumus mori, magis quam patrias Dei leges prævaricari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Iratus itaque rex, jussit sartagines et ollas æneas succendi: quibus statim succensis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'jussit ei qui prior fuerat locutus amputari linguam, et cute capitis abstracta, summas quoque manus et pedes ei præscindi, ceteris ejus fratribus et matre inspicientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Et cum jam per omnia inutilis factus esset, jussit ignem admoveri, et adhuc spirantem torreri in sartagine: in qua cum diu cruciaretur, ceteri una cum matre invicem se hortabantur mori fortiter,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'dicentes: Dominus Deus aspiciet veritatem, et consolabitur in nobis, quemadmodum in protestatione cantici declaravit Moyses: Et in servis suis consolabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Mortuo itaque illo primo hoc modo, sequentem deducebant ad illudendum: et cute capitis ejus cum capillis abstracta, interrogabant si manducaret, priusquam toto corpore per membra singula puniretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'At ille respondens patria voce, dixit: Non faciam. Propter quod et iste, sequenti loco, primi tormenta suscepit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'et in ultimo spiritu constitutus, sic ait: Tu quidem scelestissime in præsenti vita nos perdis: sed Rex mundi defunctos nos pro suis legibus in æternæ vitæ resurrectione suscitabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Post hunc tertius illuditur, et linguam postulatus cito protulit, et manus constanter extendit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'et cum fiducia ait: E cælo ista possideo, sed propter Dei leges nunc hæc ipsa despicio, quoniam ab ipso me ea recepturum spero:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'ita ut rex, et qui cum ipso erant, mirarentur adolescentis animum, quod tamquam nihilum duceret cruciatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Et hoc ita defuncto, quartum vexabant similiter torquentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Et cum jam esset ad mortem, sic ait: Potius est ab hominibus morti datos spem exspectare a Deo, iterum ab ipso resuscitandos: tibi enim resurrectio ad vitam non erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Et cum admovissent quintum, vexabant eum. At ille respiciens in eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'dixit: Potestatem inter homines habens, cum sis corruptibilis, facis quod vis: noli autem putare genus nostrum a Deo esse derelictum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'tu autem patienter sustine, et videbis magnam potestatem ipsius, qualiter te et semen tuum torquebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Post hunc ducebant sextum, et is, mori incipiens, sic ait: Noli frustra errare: nos enim propter nosmetipsos hæc patimur, peccantes in Deum nostrum, et digna admiratione facta sunt in nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'tu autem ne existimes tibi impune futurum, quod contra Deum pugnare tentaveris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Supra modum autem mater mirabilis, et bonorum memoria digna, quæ pereuntes septem filios sub unius diei tempore conspiciens, bono animo ferebat propter spem quam in Deum habebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'singulos illorum hortabatur voce patria fortiter, repleta sapientia: et, femineæ cogitationi masculinum animum inserens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'dixit ad eos: Nescio qualiter in utero meo apparuistis, neque enim ego spiritum et animam donavi vobis et vitam, et singulorum membra non ego ipsa compegi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'sed enim mundi Creator, qui formavit hominis nativitatem, quique omnium invenit originem, et spiritum vobis iterum cum misericordia reddet et vitam, sicut nunc vosmetipsos despicitis propter leges ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Antiochus autem, contemni se arbitratus, simul et exprobrantis voce despecta, cum adhuc adolescentior superesset, non solum verbis hortabatur, sed et cum juramento affirmabat se divitem et beatum facturum, et translatum a patriis legibus amicum habiturum, et res necessarias ei præbiturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Sed ad hæc cum adolescens nequaquam inclinaretur, vocavit rex matrem, et suadebat ei ut adolescenti fieret in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Cum autem multis eam verbis esset hortatus, promisit suasurum se filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Itaque inclinata ad illum, irridens crudelem tyrannum, ait patria voce: Fili mi, miserere mei, quæ te in utero novem mensibus portavi, et lac triennio dedi et alui, et in ætatem istam perduxi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Peto, nate, ut aspicias ad cælum et terram, et ad omnia quæ in eis sunt, et intelligas quia ex nihilo fecit illa Deus, et hominum genus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'ita fiet, ut non timeas carnificem istum, sed dignus fratribus tuis effectus particeps, suscipe mortem, ut in illa miseratione cum fratribus tuis te recipiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Cum hæc illa adhuc diceret, ait adolescens: Quem sustinetis? non obedio præcepto regis, sed præcepto legis, quæ data est nobis per Moysen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Tu vero, qui inventor omnis malitiæ factus es in Hebræos, non effugies manum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Nos enim pro peccatis nostris hæc patimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Et si nobis propter increpationem et correptionem Dominus Deus noster modicum iratus est: sed iterum reconciliabitur servis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Tu autem, o sceleste, et omnium hominum flagitiosissime, noli frustra extolli vanis spebus in servos ejus inflammatus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'nondum enim omnipotentis Dei, et omnia inspicientis, judicium effugisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Nam fratres mei, modico nunc dolore sustentato, sub testamento æternæ vitæ effecti sunt: tu vero judicio Dei justas superbiæ tuæ pœnas exsolves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Ego autem, sicut fratres mei, animam et corpus meum trado pro patriis legibus, invocans Deum maturius genti nostræ propitium fieri, teque cum tormentis et verberibus confiteri quod ipse est Deus solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'In me vero et in fratribus meis desinet Omnipotentis ira, quæ super omne genus nostrum juste superducta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Tunc rex accensus ira in hunc, super omnes crudelius desævit, indigne ferens se derisum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Et hic itaque mundus obiit, per omnia in Domino confidens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 41, 'Novissime autem post filios, et mater consumpta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 42, 'Igitur de sacrificiis et de nimiis crudelitatibus satis dictum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Judas vero Machabæus, et qui cum illo erant, introibant latenter in castella: et convocantes cognatos et amicos, et eos qui permanserunt in Judaismo assumentes, eduxerunt ad se sex millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Et invocabant Dominum, ut respiceret in populum qui ab omnibus calcabatur, et misereretur templo quod contaminabatur ab impiis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'misereretur etiam exterminio civitatis, quæ esset illico complananda, et vocem sanguinis ad se clamantis audiret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'memoraretur quoque iniquissimas mortes parvulorum innocentum, et blasphemias nomini suo illatas, et indignaretur super his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'At Machabæus, congregata multitudine, intolerabilis gentibus efficiebatur: ira enim Domini in misericordiam conversa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Et superveniens castellis et civitatibus improvisus, succendebat eas: et opportuna loca occupans, non paucas hostium strages dabat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'maxime autem noctibus ad hujuscemodi excursus ferebatur, et fama virtutis ejus ubique diffundebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Videns autem Philippus paulatim virum ad profectum venire, ac frequentius res ei cedere propere, ad Ptolemæum ducem Cœlesyriæ et Phœnicis scripsit ut auxilium ferret regis negotiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'At ille velociter misit Nicanorem Patrocli de primoribus amicum, datis ei de permistis gentibus, armatis non minus viginti millibus, ut universum Judæorum genus deleret, adjuncto ei Gorgia viro militari, et in bellicis rebus experientissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Constituit autem Nicanor, ut regi tributum, quod Romanis erat dandum, duo millia talentorum de captivitate Judæorum suppleret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'statimque ad maritimas civitates misit, convocans ad coëmptionem Judaicorum mancipiorum, promittens se nonaginta mancipia talento distracturum, non respiciens ad vindictam quæ eum ab Omnipotente esset consecutura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Judas autem ubi comperit, indicavit his qui secum erant Judæis Nicanoris adventum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Ex quibus quidam formidantes, et non credentes Dei justitiæ, in fugam vertebantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 14, 'alii vero si quid eis supererat vendebant, simulque Dominum deprecabantur ut eriperet eos ab impio Nicanore, qui eos priusquam cominus veniret, vendiderat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 15, 'etsi non propter eos, propter testamentum tamen quod erat ad patres eorum, et propter invocationem sancti et magnifici nominis ejus super ipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 16, 'Convocatis autem Machabæus septem millibus qui cum ipso erant, rogabat ne hostibus reconciliarentur, neque metuerent inique venientium adversum se hostium multitudinem: sed fortiter contenderent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 17, 'ante oculos habentes contumeliam quæ loco sancto ab his injuste esset illata, itemque et ludibrio habitæ civitatis injuriam, adhuc etiam veterum instituta convulsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 18, 'Nam illi quidem armis confidunt, ait, simul et audacia: nos autem in omnipotente Domino, qui potest et venientes adversum nos, et universum mundum, uno nutu delere, confidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 19, 'Admonuit autem eos et de auxiliis Dei, quæ facta sunt erga parentes: et quod sub Sennacherib centum octoginta quinque millia perierunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 20, 'et de prælio quod eis adversus Galatas fuit in Babylonia, ut omnes, ubi ad rem ventum est, Macedonibus sociis hæsitantibus, ipsi sex millia soli peremerunt centum viginti millia, propter auxilium illis datum de cælo, et beneficia pro his plurima consecuti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 21, 'His verbis constantes effecti sunt, et pro legibus et patria mori parati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 22, 'Constituit itaque fratres suos duces utrique ordini, Simonem, et Josephum, et Jonathan, subjectis unicuique millenis et quingentenis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 23, 'Ad hoc etiam ab Esdra lecto illis sancto libro, et dato signo adjutorii Dei, in prima acie ipse dux commisit cum Nicanore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 24, 'Et facto sibi adjutore Omnipotente, interfecerunt super novem millia hominum: majorem autem partem exercitus Nicanoris vulneribus debilem factam fugere compulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 25, 'Pecuniis vero eorum, qui ad emptionem ipsorum venerant, sublatis, ipsos usquequaque persecuti sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 26, 'sed reversi sunt hora conclusi, nam erat ante sabbatum: quam ob causam non perseveraverunt insequentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 27, 'Arma autem ipsorum, et spolia congregantes, sabbatum agebant, benedicentes Dominum, qui liberavit eos in isto die, misericordiæ initium stillans in eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 28, 'Post sabbatum vero debilibus, et orphanis, et viduis diviserunt spolia: et residua ipsi cum suis habuere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 29, 'His itaque gestis, et communiter ab omnibus facta obsecratione, misericordem Dominum postulabant ut in finem servis suis reconciliaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 30, 'Et ex his qui cum Timotheo et Bacchide erant contra se contendentes, super viginti millia interfecerunt, et munitiones excelsas obtinuerunt: et plures prædas diviserunt, æquam portionem debilibus, pupillis, et viduis, sed et senioribus facientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 31, 'Et cum arma eorum diligenter collegissent, omnia composuerunt in locis opportunis: residua vero spolia Jerosolymam detulerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 32, 'et Philarchen, qui cum Timotheo erat, interfecerunt, virum scelestum, qui in multis Judæos afflixerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 33, 'Et cum epinicia agerent Jerosolymis, eum qui sacras januas incenderat, id est, Callisthenem, cum in quoddam domicilium refugisset, incenderunt, digna ei mercede pro impietatibus suis reddita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 34, 'Facinorosissimus autem Nicanor, qui mille negotiantes ad Judæorum venditionem adduxerat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 35, 'humiliatus auxilio Domini ab his quos nullos existimaverat, deposita veste gloriæ, per mediterranea fugiens, solus venit Antiochiam, summam infelicitatem de interitu sui exercitus consecutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 36, 'Et qui promiserat Romanis se tributum restituere de captivitate Jerosolymorum, prædicabat nunc protectorem Deum habere Judæos, et ob ipsum invulnerabiles esse, eo quod sequerentur leges ab ipso constitutas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Eodem tempore, Antiochus inhoneste revertebatur de Perside.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Intraverat enim in eam quæ dicitur Persepolis, et tentavit expoliare templum, et civitatem opprimere: sed multitudine ad arma concurrente, in fugam versi sunt: et ita contigit ut Antiochus post fugam turpiter rediret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Et cum venisset circa Ecbatanam, recognovit quæ erga Nicanorem et Timotheum gesta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Elatus autem in ira, arbitrabatur se injuriam illorum qui se fugaverant posse in Judæos retorquere: ideoque jussit agitari currum suum sine intermissione agens iter, cælesti eum judicio perurgente, eo quod ita superbe locutus est se venturum Jerosolymam, et congeriem sepulchri Judæorum eam facturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Sed qui universa conspicit Dominus Deus Israël, percussit eum insanabili et invisibili plaga. Ut enim finivit hunc ipsum sermonem, apprehendit eum dolor dirus viscerum, et amara internorum tormenta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'et quidem satis juste, quippe qui multis et novis cruciatibus aliorum torserat viscera, licet ille nullo modo a sua malitia cessaret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Super hoc autem superbia repletus, ignem spirans animo in Judæos, et præcipiens accelerari negotium, contigit illum impetu euntem de curru cadere, et gravi corporis collisione membra vexari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Isque qui sibi videbatur etiam fluctibus maris imperare, supra humanum modum superbia repletus, et montium altitudines in statera appendere, nunc humiliatus ad terram in gestatorio portabatur, manifestam Dei virtutem in semetipso contestans:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'ita ut de corpore impii vermes scaturirent, ac viventis in doloribus carnes ejus effluerent, odore etiam illius et fœtore exercitus gravaretur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'et qui paulo ante sidera cæli contingere se arbitrabatur, eum nemo poterat propter intolerantiam fœtoris portare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Hinc igitur cœpit ex gravi superbia deductus ad agnitionem sui venire, divina admonitus plaga, per momenta singula doloribus suis augmenta capientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Et cum nec ipse jam fœtorem suum ferre posset, ita ait: Justum est subditum esse Deo, et mortalem non paria Deo sentire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Orabat autem hic scelestus Dominum, a quo non esset misericordiam consecuturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Et civitatem, ad quam festinans veniebat ut eam ad solum deduceret ac sepulchrum congestorum faceret, nunc optat liberam reddere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'et Judæos, quos nec sepultura quidem se dignos habiturum, sed avibus ac feris diripiendos traditurum, et cum parvulis exterminaturum dixerat, æquales nunc Atheniensibus facturum pollicetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'templum etiam sanctum, quod prius expoliaverat, optimis donis ornaturum, et sancta vasa multiplicaturum, et pertinentes ad sacrificia sumptus de redditibus suis præstaturum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'super hæc, et Judæum se futurum, et omnem locum terræ perambulaturum, et prædicaturum Dei potestatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Sed non cessantibus doloribus (supervenerat enim in eum justum Dei judicium), desperans scripsit ad Judæos in modum deprecationis epistolam hæc continentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Optimis civibus Judæis plurimam salutem, et bene valere, et esse felices, rex et principes Antiochus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Si bene valetis, et filii vestri, et ex sententia vobis cuncta sunt, maximas agimus gratias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Et ego in infirmitate constitutus, vestri autem memor benigne reversus de Persidis locis, et infirmitate gravi apprehensus, necessarium duxi pro communi utilitate curam habere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'non desperans memetipsum, sed spem multam habens effugiendi infirmitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Respiciens autem quod et pater meus, quibus temporibus in locis superioribus ducebat exercitum, ostendit qui post se susciperet principatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'ut si quid contrarium accideret, aut difficile nuntiaretur, scientes hi qui in regionibus erant, cui esset rerum summa derelicta, non turbarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Ad hæc, considerans de proximo potentes quosque et vicinos temporibus insidiantes, et eventum exspectantes, designavi filium meum Antiochum regem, quem sæpe recurrens in superiora regna multis vestrum commendabam: et scripsi ad eum quæ subjecta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ora itaque vos, et peto memores beneficiorum publice et privatim, ut unusquisque conservet fidem ad me et ad filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Confido enim eum modeste et humane acturum, et sequentem propositum meum, et communem vobis fore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 28, 'Igitur homicida et blasphemus pessime percussus, et ut ipse alios tractaverat, peregre in montibus miserabili obitu vita functus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 29, 'Transferebat autem corpus Philippus collactaneus ejus: qui, metuens filium Antiochi, ad Ptolemæum Philometorem in \'gyptum abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Machabæus autem, et qui cum eo erant, Domino se protegente, templum quidem et civitatem recepit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'aras autem quas alienigenæ per plateas exstruxerant, itemque delubra demolitus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'et purgato templo, aliud altare fecerunt, et de ignitis lapidibus igne concepto sacrificia obtulerunt post biennium, et incensum, et lucernas, et panes propositionis posuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Quibus gestis, rogabant Dominum prostrati in terram, ne amplius talibus malis inciderent: sed et, siquando peccassent, ut ab ipso mitius corriperentur, et non barbaris ac blasphemis hominibus traderentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Qua die autem templum ab alienigenis pollutum fuerat, contigit eadem die purificationem fieri, vigesima quinta mensis qui fuit Casleu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Et cum lætitia diebus octo egerunt in modum tabernaculorum, recordantes quod ante modicum temporis diem solemnem tabernaculorum in montibus et in speluncis more bestiarum egerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Propter quod thyrsos, et ramos virides, et palmas præferebant ei qui prosperavit mundari locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Et decreverunt communi præcepto et decreto universæ genti Judæorum omnibus annis agere dies istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Et Antiochi quidem, qui appellatus est Nobilis, vitæ excessus ita se habuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Nunc autem de Eupatore Antiochi impii filio quæ gesta sunt narrabimus, breviantes mala quæ in bellis gesta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Hic enim suscepto regno, constituit super negotia regni Lysiam quemdam, Phœnicis et Syriæ militiæ principem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Nam Ptolemæus, qui dicebatur Macer, justi tenax erga Judæos esse constituit, et præcipue propter iniquitatem quæ facta erat in eos, et pacifice agere cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Sed ob hoc accusatus ab amicis apud Eupatorem, cum frequenter proditor audiret, eo quod Cyprum creditam sibi a Philometore deseruisset, et ad Antiochum Nobilem translatus etiam ab eo recessisset, veneno vitam finivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Gorgias autem cum esset dux locorum, assumptis advenis, frequenter Judæos debellabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Judæi vero qui tenebant opportunas munitiones, fugatos ab Jerosolymis suscipiebant, et bellare tentabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Hi vero qui erant cum Machabæo, per orationes Dominum rogantes ut esset sibi adjutor, impetum fecerunt in munitiones Idumæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'multaque vi insistentes, loca obtinuerunt, occurrentes interemerunt, et omnes simul non minus viginti millibus trucidaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Quidam autem cum confugissent in duas turres valde munitas, omnem apparatum ad repugnandum habentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Machabæus ad eorum expugnationem relicto Simone, et Josepho, itemque Zachæo, eisque qui cum ipsis erant satis multis, ipse ad eas quæ amplius perurgebant pugnas conversus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Hi vero qui cum Simone erant, cupiditate ducti, a quibusdam qui in turribus erant, suasi sunt pecunia: et septuaginta millibus didrachmis acceptis, dimiserunt quosdam effugere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Cum autem Machabæo nuntiatum esset quod factum est, principibus populi congregatis accusavit quod pecunia fratres vendidissent, adversariis eorum dimissis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Hos igitur proditores factos interfecit, et confestim duas turres occupavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Armis autem ac manibus omnia prospere agendo in duabus munitionibus plus quam viginti millia peremit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'At Timotheus, qui prius a Judæis fuerat superatus, convocato exercitu peregrinæ multitudinis, et congregato equitatu Asiano, advenit quasi armis Judæam capturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Machabæus autem et qui cum ipso erant, appropinquante illo, deprecabantur Dominum, caput terra aspergentes, lumbosque ciliciis præcincti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'ad altaris crepidinem provoluti, ut sibi propitius, inimicis autem eorum esset inimicus, et adversariis adversaretur, sicut lex dicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Et ita post orationem, sumptis armis, longius de civitate procedentes, et proximi hostibus effecti, resederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Primo autem solis ortu utrique commiserunt: isti quidem victoriæ et prosperitatis sponsorem cum virtute Dominum habentes: illi autem ducem belli animum habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Sed cum vehemens pugna esset, apparuerunt adversariis de cælo viri quinque in equis, frenis aureis decori, ducatum Judæis præstantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'ex quibus duo Machabæum medium habentes, armis suis circumseptum incolumem conservabant: in adversarios autem tela et fulmina jaciebant, ex quo et cæcitate confusi et repleti perturbatione, cadebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Interfecti sunt autem viginti millia quingenti, et equites sexcenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Timotheus vero confugit in Gazaram præsidium munitum, cui præerat Chæreas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Machabæus autem et qui cum eo erant, lætantes obsederunt præsidium diebus quatuor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 34, 'At hi qui intus erant, loci firmitate confisi, supra modum maledicebant, et sermones nefandos jactabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 35, 'Sed cum dies quinta illucesceret, viginti juvenes ex his qui cum Machabæo erant, accensi animis propter blasphemiam, viriliter accesserunt ad murum, et feroci animo incedentes ascendebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 36, 'sed et alii similiter ascendentes, turres portasque succendere aggressi sunt, atque ipsos maledicos vivos concremare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 37, 'Per continuum autem biduum præsidio vastato, Timotheum occultantem se in quodam repertum loco peremerunt: et fratrem illius Chæream et Apollophanem occiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 38, 'Quibus gestis, in hymnis et confessionibus benedicebant Dominum, qui magna fecit in Israël, et victoriam dedit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Sed parvo post tempore, Lysias procurator regis et propinquus, ac negotiorum præpositus, graviter ferens de his quæ acciderant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'congregatis octoginta millibus, et equitatu universo, veniebat adversus Judæos, existimans se civitatem quidem captam gentibus habitaculum facturum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'templum vero in pecuniæ quæstum, sicut cetera delubra gentium, habiturum, et per singulos annos venale sacerdotium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'nusquam recogitans Dei potestatem, sed mente effrenatus in multitudine peditum, et in millibus equitum, et in octoginta elephantis confidebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Ingressus autem Judæam, et appropians Bethsuræ, quæ erat in angusto loco, ab Jerosolyma intervallo quinque stadiorum, illud præsidium expugnabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Ut autem Machabæus et qui cum eo erant cognoverunt expugnari præsidia, cum fletu et lacrimis rogabant Dominum, et omnis turba simul, ut bonum angelum mitteret ad salutem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Et ipse primus Machabæus, sumptis armis, ceteros adhortatus est simul secum periculum subire, et ferre auxilium fratribus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Cumque pariter prompto animo procederent, Jerosolymis apparuit præcedens eos eques in veste candida, armis aureis hastam vibrans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Tunc omnes simul benedixerunt misericordem Dominum, et convaluerunt animis: non solum homines, sed et bestias ferocissimas, et muros ferreos parati penetrare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Ibant igitur prompti, de cælo habentes adjutorem et miserantem super eos Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Leonum autem more impetu irruentes in hostes, prostraverunt ex eis undecim millia peditum, et equitum mille sexcentos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'universos autem in fugam verterunt, plures autem ex eis vulnerati nudi evaserunt. Sed et ipse Lysias turpiter fugiens evasit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Et quia non insensatus erat, secum ipse reputans factam erga se diminutionem, et intelligens invictos esse Hebræos, omnipotentis Dei auxilio innitentes, misit ad eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'promisitque se consensurum omnibus quæ justa sunt, et regem compulsurum amicum fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Annuit autem Machabæus precibus Lysiæ, in omnibus utilitati consulens: et quæcumque Machabæus scripsit Lysiæ de Judæis, ea rex concessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Nam erant scriptæ Judæis epistolæ a Lysia quidem hunc modum continentes: Lysias populo Judæorum salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Joannes et Abesalom, qui missi fuerant a vobis, tradentes scripta, postulabant ut ea quæ per illos significabantur, implerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Quæcumque igitur regi potuerunt perferri, exposui: et quæ res permittebat, concessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Si igitur in negotiis fidem conservaveritis, et deinceps bonorum vobis causa esset, tentabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'De ceteris autem per singula verbo mandavi et istis, et his, qui a me missi sunt, colloqui vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Bene valete. Anno centesimo, quadragesimo octavo mensis Dioscori, die vigesima et quarta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Regis autem epistola ista continebat: Rex Antiochus Lysiæ fratri salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Patre nostro inter deos translato, nos volentes eos qui sunt in regno nostro sine tumultu agere, et rebus suis adhibere diligentiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'audivimus Judæos non consensisse patri meo ut transferrentur ad ritum Græcorum, sed tenere velle suum institutum, ac propterea postulare a nobis concedi sibi legitima sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Volentes igitur hanc quoque gentem quietam esse, statuentes judicavimus templum restitui illis, ut agerent secundum suorum majorum consuetudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Bene igitur feceris, si miseris ad eos et dexteram dederis: ut cognita nostra voluntate, bono animo sint, et utilitatibus propriis deserviant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Ad Judæos vero regis epistola talis erat: Rex Antiochus senatui Judæorum, et ceteris Judæis salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Si valetis, sic estis ut volumus: sed et ipsi bene valemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Adiit nos Menelaus, dicens velle vos descendere ad vestros, qui sunt apud nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'His igitur qui commeant usque ad diem trigesimum mensis Xanthici, damus dextras securitatis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'ut Judæi utantur cibis et legibus suis, sicut et prius: et nemo eorum ullo modo molestiam patiatur de his quæ per ignorantiam gesta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Misimus autem et Menelaum, qui vos alloquatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Valete. Anno centesimo quadragesimo octavo, Xanthici mensis quintadecima die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Miserunt autem etiam Romani epistolam, ita se habentem: Quintus Memmius et Titus Manilius legati Romanorum, populo Judæorum salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 35, 'De his quæ Lysias cognatus regis concessit vobis, et nos concessimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 36, 'De quibus autem ad regem judicavit referendum, confestim aliquem mittere, diligentius inter vos conferentes, ut decernamus, sicut congruit vobis: nos enim Antiochiam accedimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 37, 'Ideoque festinate rescribere, ut nos quoque sciamus cujus estis voluntatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 38, 'Bene valete. Anno centesimo quadragesimo octavo, quintadecima die mensis Xanthici.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'His factis pactionibus, Lysias pergebat ad regem, Judæi autem agriculturæ operam dabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Sed hi qui resederant, Timotheus, et Apollonius Gennæi filius, sed et Hieronymus, et Demophon super hos, et Nicanor Cypriarches, non sinebant eos in silentio agere et quiete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Joppitæ vero tale quoddam flagitium perpetrarunt: rogaverunt Judæos cum quibus habitabant, ascendere scaphas quas paraverant, cum uxoribus et filiis, quasi nullis inimicitiis inter eos subjacentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Secundum commune itaque decretum civitatis, et ipsis acquiescentibus, pacisque causa nihil suspectum habentibus: cum in altum processissent, submerserunt non minus ducentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Quam crudelitatem Judas in suæ gentis homines factam ut cognovit, præcepit viris qui erant cum ipso: et invocato justo judice Deo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'venit adversus interfectores fratrum, et portum quidem noctu succendit, scaphas exussit, eos autem qui ab igne refugerant, gladio peremit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Et cum hæc ita egisset, discessit quasi iterum reversurus, et universos Joppitas eradicaturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Sed cum cognovisset et eos qui erant Jamniæ, velle pari modo facere habitantibus secum Judæis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Jamnitis quoque nocte supervenit, et portum cum navibus succendit: ita ut lumen ignis appareret Jerosolymis a stadiis ducentis quadraginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Inde cum jam abiissent novem stadiis, et iter facerent ad Timotheum, commiserunt cum eo Arabes quinque millia viri, et equites quingenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Cumque pugna valida fieret, et auxilio Dei prospere cessisset, residui Arabes victi petebant a Juda dextram sibi dari, promittentes se pascua daturos, et in ceteris profuturos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Judas autem arbitratus vere in multis eos utiles, promisit pacem: dextrisque acceptis, discessere ad tabernacula sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Aggressus est autem et civitatem quamdam firmam pontibus murisque circumseptam, quæ a turbis habitabatur gentium promiscuarum: cui nomen Casphin.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Hi vero qui intus erant, confidentes in stabilitate murorum et apparatu alimoniarum, remissius agebant, maledictis lacessentes Judam et blasphemantes, ac loquentes quæ fas non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Machabæus autem, invocato magno mundi Principe, qui sine arietibus et machinis temporibus Jesu præcipitavit Jericho, irruit ferociter muris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'et capta civitate per Domini voluntatem, innumerabiles cædes fecit, ita ut adjacens stagnum stadiorum duorum latitudinis sanguine interfectorum fluere videretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Inde discesserunt stadia septingenta quinquaginta, et venerunt in Characa ad eos, qui dicuntur Tubianæi, Judæos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'et Timotheum quidem in illis locis non comprehenderunt, nulloque negotio perfecto regressus est, relicto in quodam loco firmissimo præsidio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Dositheus autem et Sosipater, qui erant duces cum Machabæo, peremerunt a Timotheo relictos in præsidio, decem millia viros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'At Machabæus, ordinatis circum se sex millibus, et constitutis per cohortes, adversus Timotheum processit, habentem secum centum viginti millia peditum, equitumque duo millia quingentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Cognito autem Judæ adventu, Timotheus præmisit mulieres et filios, et reliquum apparatum, in præsidium quod Carnion dicitur: erat enim inexpugnabile, et accessu difficile propter locorum angustias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Cumque cohors Judæ prima apparuisset, timor hostibus incussus est ex præsentia Dei, qui universa conspicit: et in fugam versi sunt alius ab alio, ita ut magis a suis dejicerentur, et gladiorum suorum ictibus debilitarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Judas autem vehementer instabat puniens profanos, et prostravit ex eis triginta millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Ipse vero Timotheus incidit in partes Dosithei et Sosipatris: et multis precibus postulabat ut vivus dimitteretur, eo quod multorum ex Judæis parentes haberet ac fratres, quos morte ejus decipi eveniret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Et cum fidem dedisset restituturum se eos secundum constitutum, illæsum eum dimiserunt propter fratrum salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Judas autem egressus est ad Carnion, interfectis viginti quinque millibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Post horum fugam et necem, movit exercitum ad Ephron civitatem munitam, in qua multitudo diversarum gentium habitabat: et robusti juvenes pro muris consistentes fortiter repugnabant: in hac autem machinæ multæ et telorum erat apparatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Sed cum Omnipotentem invocassent, qui potestate sua vires hostium confringit, ceperunt civitatem: et ex eis qui intus erant, viginti quinque millia prostraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Inde ad civitatem Scytharum abierunt, quæ ab Jerosolymis sexcentis stadiis aberat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Contestantibus autem his, qui apud Scythopolitas erant, Judæis, quod benigne ab eis haberentur, etiam temporibus infelicitatis quod modeste secum egerint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'gratias agentes eis, et exhortati etiam de cetero erga genus suum benignos esse, venerunt Jerosolymam die solemni septimanarum instante.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 32, 'Et post Pentecosten abierunt contra Gorgiam præpositum Idumææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 33, 'Exivit autem cum peditibus tribus millibus, et equitibus quadringentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 34, 'Quibus congressis, contigit paucos ruere Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 35, 'Dositheus vero quidam de Bacenoris eques, vir fortis, Gorgiam tenebat: et, cum vellet illum capere vivum, eques quidam de Thracibus irruit in eum, humerumque ejus amputavit: atque ita Gorgias effugit in Maresa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 36, 'At illis qui cum Esdrim erant diutius pugnantibus et fatigatis, invocavit Judas Dominum adjutorem et ducem belli fieri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 37, 'incipiens voce patria, et cum hymnis clamorem extollens, fugam Gorgiæ militibus incussit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 38, 'Judas autem collecto exercitu venit in civitatem Odollam: et cum septima dies superveniret, secundum consuetudinem purificati, in eodem loco sabbatum egerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 39, 'Et sequenti die venit cum suis Judas, ut corpora prostratorum tolleret, et cum parentibus poneret in sepulchris paternis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 40, 'Invenerunt autem sub tunicis interfectorum de donariis idolorum quæ apud Jamniam fuerunt, a quibus lex prohibet Judæos: omnibus ergo manifestum factum est, ob hanc causam eos corruisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 41, 'Omnes itaque benedixerunt justum judicium Domini, qui occulta fecerat manifesta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 42, 'atque ita ad preces conversi, rogaverunt ut id quod factum erat delictum oblivioni traderetur. At vero fortissimus Judas hortabatur populum conservare se sine peccato, sub oculis videntes quæ facta sunt pro peccatis eorum qui prostrati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 43, 'Et facta collatione, duodecim millia drachmas argenti misit Jerosolymam offerri pro peccatis mortuorum sacrificium, bene et religiose de resurrectione cogitans');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 44, '(nisi enim eos qui ceciderant resurrecturos speraret, superfluum videretur et vanum orare pro mortuis),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 45, 'et quia considerabat quod hi qui cum pietate dormitionem acceperant, optimam haberent repositam gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 46, 'Sancta ergo et salubris est cogitatio pro defunctis exorare, ut a peccatis solvantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Anno centesimo quadragesimo nono, cognovit Judas Antiochum Eupatorem venire cum multitudine adversus Judæam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'et cum eo Lysiam procuratorem et præpositum negotiorum, secum habentem peditum centum decem millia, et equitum quinque millia, et elephantos viginti duos, currus cum falcibus trecentos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Commiscuit autem se illis et Menelaus: et cum multa fallacia deprecabatur Antiochum, non pro patriæ salute, sed sperans se constitui in principatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Sed Rex regum suscitavit animos Antiochi in peccatorem: et suggerente Lysia hunc esse causam omnium malorum, jussit (ut eis est consuetudo) apprehensum in eodem loco necari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Erat autem in eodem loco turris quinquaginta cubitorum, aggestum undique habens cineris: hæc prospectum habebat in præceps.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Inde in cinerem dejici jussit sacrilegum, omnibus eum propellentibus ad interitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Et tali lege prævaricatorem legis contigit mori, nec terræ dari Menelaum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Et quidem satis juste: nam quia multa erga aram Dei delicta commisit, cujus ignis et cinis erat sanctus: ipse in cineris morte damnatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Sed rex mente effrenatus veniebat, nequiorem se patre suo Judæis ostensurus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Quibus Judas cognitis, præcepit populo ut die ac nocte Dominum invocarent, quo, sicut semper, et nunc adjuvaret eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'quippe qui lege, et patria, sanctoque templo privari vererentur: ac populum, qui nuper paululum respirasset, ne sineret blasphemis rursus nationibus subdi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Omnibus itaque simul id facientibus, et petentibus a Domino misericordiam cum fletu et jejuniis, per triduum continuum prostratis, hortatus est eos Judas ut se præpararent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Ipse vero cum senioribus cogitavit priusquam rex admoveret exercitum ad Judæam et obtineret civitatem, exire, et Domini judicio committere exitum rei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 14, 'Dans itaque potestatem omnium Deo mundi creatori, et exhortatus suos ut fortiter dimicarent, et usque ad mortem pro legibus, templo, civitate, patria, et civibus starent, circa Modin exercitum constituit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 15, 'Et dato signo suis Dei victoriæ, juvenibus fortissimis electis nocte aggressus aulam regiam, in castris interfecit viros quatuor millia, et maximum elephantorum cum his qui superpositi fuerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 16, 'summoque metu ac perturbatione hostium castra replentes, rebus prospere gestis, abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 17, 'Hoc autem factum est die illucescente, adjuvante eum Domini protectione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 18, 'Sed rex, accepto gustu audaciæ Judæorum, arte difficultatem locorum tentabat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 19, 'et Bethsuræ, quæ erat Judæorum præsidium munitum, castra admovebat: sed fugabatur, impingebat, minorabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 20, 'His autem qui intus erant, Judas necessaria mittebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 21, 'Enuntiavit autem mysteria hostibus Rhodocus quidam de judaico exercitu, qui requisitus comprehensus est, et conclusus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 22, 'Iterum rex sermonem habuit ad eos qui erant in Bethsuris: dextram dedit, accepit, abiit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 23, 'commisit cum Juda, superatus est. Ut autem cognovit rebellasse Philippum Antiochiæ, qui relictus erat super negotia, mente consternatus, Judæos deprecans, subditusque eis, jurat de omnibus quibus justum visum est: et reconciliatus obtulit sacrificium, honoravit templum, et munera posuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 24, 'Machabæum amplexatus est, et fecit eum a Ptolemaide usque ad Gerrenos ducem et principem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 25, 'Ut autem venit Ptolemaidam, graviter ferebant Ptolemenses amicitiæ conventionem, indignantes ne forte fœdus irrumperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 26, 'Tunc ascendit Lysias tribunal, et exposuit rationem, et populum sedavit, regressusque est Antiochiam: et hoc modo regis profectio et reditus processit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Sed post triennii tempus, cognovit Judas et qui cum eo erant Demetrium Seleuci cum multitudine valida et navibus per portam Tripolis ascendisse ad loca opportuna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'et tenuisse regiones adversus Antiochum, et ducem ejus Lysiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Alcimus autem quidam, qui summus sacerdos fuerat, sed voluntarie coinquinatus est temporibus commistionis, considerans nullo modo sibi esse salutem neque accessum ad altare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'venit ad regem Demetrium centesimo quinquagesimo anno, offerens ei coronam auream et palmam, super hæc et thallos, qui templi esse videbantur. Et ipsa quidem die siluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Tempus autem opportunum dementiæ suæ nactus, convocatus a Demetrio ad consilium, et interrogatus quibus rebus et consiliis Judæi niterentur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'respondit: Ipsi qui dicuntur Assidæi Judæorum, quibus præest Judas Machabæus, bella nutriunt, et seditiones movent, nec patiuntur regnum esse quietum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'nam et ego defraudatus parentum gloria (dico autem summo sacerdotio) huc veni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'primo quidem utilitatibus regis fidem servans, secundo autem etiam civibus consulens: nam illorum pravitate universum genus nostrum non minime vexatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Sed oro his singulis, o rex, cognitis, et regioni et generi, secundum humanitatem tuam pervulgatam omnibus, prospice:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'nam, quamdiu superest Judas, impossibile est pacem esse negotiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Talibus autem ab hoc dictis, et ceteri amici hostiliter se habentes adversus Judam, inflammaverunt Demetrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Qui statim Nicanorem præpositum elephantorum ducem misit in Judæam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'datis mandatis ut ipsum quidem Judam caperet: eos vero qui cum illo erant, dispergeret, et constitueret Alcimum maximi templi summum sacerdotem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Tunc gentes quæ de Judæa fugerant Judam, gregatim se Nicanori miscebant, miserias et clades Judæorum prosperitates rerum suarum existimantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Audito itaque Judæi Nicanoris adventu, et conventu nationum, conspersi terra rogabant eum qui populum suum constituit, ut in æternum custodiret, quique suam portionem signis evidentibus protegit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Imperante autem duce, statim inde moverunt, conveneruntque ad castellum Dessau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Simon vero frater Judæ commiserat cum Nicanore: sed conterritus est repentino adventu adversariorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Nicanor tamen, audiens virtutem comitum Judæ, et animi magnitudinem quam pro patriæ certaminibus habebant, sanguine judicium facere metuebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Quam ob rem præmisit Posidonium, et Theodotium, et Matthiam, ut darent dextras atque acciperent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Et cum diu de his consilium ageretur, et ipse dux ad multitudinem retulisset, omnium una fuit sententia amicitiis annuere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Itaque diem constituerunt, qua secreto inter se agerent: et singulis sellæ prolatæ sunt, et positæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Præcepit autem Judas armatos esse locis opportunis, ne forte ab hostibus repente mali aliquid oriretur: et congruum colloquium fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Morabatur autem Nicanor Jerosolymis, nihilque inique agebat: gregesque turbarum quæ congregatæ fuerant, dimisit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Habebat autem Judam semper carum ex animo, et erat viro inclinatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Rogavitque eum ducere uxorem, filiosque procreare. Nuptias fecit: quiete egit, communiterque vivebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Alcimus autem, videns caritatem illorum ad invicem et conventiones, venit ad Demetrium, et dicebat Nicanorem rebus alienis assentire, Judamque regni insidiatorem successorem sibi destinasse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Itaque rex exasperatus, et pessimis hujus criminationibus irritatus, scripsit Nicanori, dicens graviter quidem se ferre de amicitiæ conventione, jubere tamen Machabæum citius vinctum mittere Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Quibus cognitis, Nicanor consternabatur, et graviter ferebat, si ea quæ convenerant irrita faceret, nihil læsus a viro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'sed quia regi resistere non poterat, opportunitatem observabat qua præceptum perficeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'At Machabæus, videns secum austerius agere Nicanorem, et consuetum occursum ferocius exhibentem, intelligens non ex bono esse austeritatem istam, paucis suorum congregatis, occultavit se a Nicanore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Quod cum ille cognovit, fortiter se a viro præventum, venit ad maximum et sanctissimum templum: et sacerdotibus solitas hostias offerentibus, jussit sibi tradi virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Quibus cum juramento dicentibus nescire se ubi esset qui quærebatur, extendens manum ad templum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'juravit, dicens: Nisi Judam mihi vinctum tradideritis, istud Dei fanum in planitiem deducam, et altare effodiam, et templum hoc Libero patri consecrabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Et his dictis abiit. Sacerdotes autem protendentes manus in cælum, invocabant eum qui semper propugnator esset gentis ipsorum, hæc dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Tu, Domine universorum, qui nullius indiges, voluisti templum habitationis tuæ fieri in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Et nunc, Sancte sanctorum, omnium Domine, conserva in æternum impollutam domum istam, quæ nuper mundata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Razias autem quidam de senioribus ab Jerosolymis delatus est Nicanori, vir amator civitatis, et bene audiens: qui pro affectu pater Judæorum appellabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Hic multis temporibus continentiæ propositum tenuit in Judaismo, corpusque et animam tradere contentus pro perseverantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Volens autem Nicanor manifestare odium quod habebat in Judæos, misit milites quingentos ut eum comprehenderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Putabat enim, si illum decepisset, se cladem Judæis maximam illaturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 41, 'Turbis autem irruere in domum ejus, et januam dirumpere: atque ignem admovere cupientibus, cum jam comprehenderetur, gladio se petiit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 42, 'eligens nobiliter mori potius quam subditus fieri peccatoribus, et contra natales suos indignis injuriis agi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 43, 'Sed cum per festinationem non certo ictu plagam dedisset, et turbæ intra ostia irrumperent, recurrens audacter ad murum præcipitavit semetipsum viriliter in turbas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 44, 'quibus velociter locum dantibus casui ejus, venit per mediam cervicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 45, 'Et cum adhuc spiraret, accensus animo, surrexit, et cum sanguis ejus magno fluxu deflueret, et gravissimis vulneribus esset saucius, cursu turbam pertransiit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 46, 'et stans supra quamdam petram præruptam, et jam exsanguis effectus, complexus intestina sua, utrisque manibus projecit super turbas, invocans dominatorem vitæ ac spiritus ut hæc illi iterum redderet: atque ita vita defunctus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Nicanor autem, ut comperit Judam esse in locis Samariæ, cogitavit cum omni impetu die sabbati committere bellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Judæis vero qui illum per necessitatem sequebantur, dicentibus: Ne ita ferociter et barbare feceris, sed honorem tribue diei sanctificationis, et honora eum qui universa conspicit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'ille infelix interrogavit si est potens in cælo, qui imperavit agi diem sabbatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Et respondentibus illis: Est Dominus vivus ipse in cælo potens, qui jussit agi septimam diem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'at ille ait: Et ego potens sum super terram qui impero sumi arma, et negotia regis impleri. Tamen non obtinuit ut consilium perficeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Et Nicanor quidem cum summa superbia erectus, cogitaverat commune trophæum statuere de Juda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Machabæus autem semper confidebat cum omni spe auxilium sibi a Deo affuturum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'et hortabatur suos ne formidarent ad adventum nationum, sed in mente haberent adjutoria sibi facta de cælo, et nunc sperarent ab Omnipotente sibi affuturam victoriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Et allocutus eos de lege et prophetis, admonens etiam certamina quæ fecerant prius, promptiores constituit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'et ita animis eorum erectis simul ostendebat gentium fallaciam, et juramentorum prævaricationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Singulos autem illorum armavit, non clypei et hastæ munitione, sed sermonibus optimis et exhortationibus, exposito digno fide somnio, per quod universos lætificavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Erat autem hujuscemodi visus: Oniam, qui fuerat summus sacerdos, virum bonum et benignum, verecundum visu, modestum moribus, et eloquio decorum, et qui a puero in virtutibus exercitatus sit, manus protendentem orare pro omni populo Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Post hoc apparuisse et alium virum ætate et gloria mirabilem, et magni decoris habitudine circa illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Respondentem vero Oniam dixisse: Hic est fratrum amator, et populi Israël: hic est qui multum orat pro populo et universa sancta civitate, Jeremias propheta Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Extendisse autem Jeremiam dextram, et dedisse Judæ gladium aureum, dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Accipe sanctum gladium munus a Deo, in quo dejicies adversarios populi mei Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Exhortati itaque Judæ sermonibus bonis valde, de quibus extolli posset impetus, et animi juvenum confortari, statuerunt dimicare et confligere fortiter: ut virtus de negotiis judicaret, eo quod civitas sancta et templum periclitarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Erat enim pro uxoribus et filiis, itemque pro fratribus et cognatis, minor sollicitudo: maximus vero et primus pro sanctitate timor erat templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Sed et eos qui in civitate erant, non minima sollicitudo habebat pro his qui congressuri erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Et cum jam omnes sperarent judicium futurum, hostesque adessent atque exercitus esset ordinatus, bestiæ equitesque opportuno in loco compositi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'considerans Machabæus adventum multitudinis, et apparatum varium armorum, et ferocitatem bestiarum, extendens manus in cælum, prodigia facientem Dominum invocavit, qui non secundum armorum potentiam, sed prout ipsi placet, dat dignis victoriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Dixit autem invocans hoc modo: Tu Domine, qui misisti angelum tuum sub Ezechia rege Juda, et interfecisti de castris Sennacherib centum octoginta quinque millia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'et nunc, dominator cælorum, mitte angelum tuum bonum ante nos in timore et tremore magnitudinis brachii tui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'ut metuant qui cum blasphemia veniunt adversus sanctum populum tuum. Et hic quidem ita peroravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Nicanor autem et qui cum ipso erant, cum tubis et canticis admovebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Judas vero et qui cum eo erant, invocato Deo, per orationes congressi sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'manu quidem pugnantes, sed Dominum cordibus orantes, prostraverunt non minus triginta quinque millia, præsentia Dei magnifice delectati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Cumque cessassent, et cum gaudio redirent, cognoverunt Nicanorem ruisse cum armis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Facto itaque clamore, et perturbatione excitata, patria voce omnipotentem Dominum benedicebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Præcepit autem Judas, qui per omnia corpore et animo mori pro civibus paratus erat, caput Nicanoris, et manum cum humero abscissam, Jerosolymam perferri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Quo cum pervenisset, convocatis contribulibus et sacerdotibus ad altare, accersiit et eos qui in arce erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Et ostenso capite Nicanoris, et manu nefaria quam extendens contra domum sanctam omnipotentis Dei magnifice gloriatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Linguam etiam impii Nicanoris præcisam jussit particulatim avibus dari: manum autem dementis contra templum suspendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Omnes igitur cæli benedixerunt Dominum, dicentes: Benedictus qui locum suum incontaminatum servavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Suspendit autem Nicanoris caput in summa arce, ut evidens esset, et manifestum signum auxilii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Itaque omnes communi consilio decreverunt nullo modo diem istum absque celebritate præterire:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'habere autem celebritatem tertiadecima die mensis Adar, quod dicitur voce syriaca, pridie Mardochæi diei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Igitur his erga Nicanorem gestis, et ex illis temporibus ab Hebræis civitate possessa, ego quoque in his faciam finem sermonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Et si quidem bene, et ut historiæ competit, hoc et ipse velim: sin autem minus digne, concedendum est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Sicut enim vinum semper bibere, aut semper aquam, contrarium est; alternis autem uti, delectabile: ita legentibus si semper exactus sit sermo, non erit gratus. Hic ergo erit consummatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Liber generationis Jesu Christi filii David, filii Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Abraham genuit Isaac. Isaac autem genuit Jacob. Jacob autem genuit Judam, et fratres ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Judas autem genuit Phares, et Zaram de Thamar. Phares autem genuit Esron. Esron autem genuit Aram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Aram autem genuit Aminadab. Aminadab autem genuit Naasson. Naasson autem genuit Salmon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Salmon autem genuit Booz de Rahab. Booz autem genuit Obed ex Ruth. Obed autem genuit Jesse. Jesse autem genuit David regem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'David autem rex genuit Salomonem ex ea quæ fuit Uriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Salomon autem genuit Roboam. Roboam autem genuit Abiam. Abias autem genuit Asa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Asa autem genuit Josophat. Josophat autem genuit Joram. Joram autem genuit Oziam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Ozias autem genuit Joatham. Joatham autem genuit Achaz. Achaz autem genuit Ezechiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Ezechias autem genuit Manassen. Manasses autem genuit Amon. Amon autem genuit Josiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Josias autem genuit Jechoniam, et fratres ejus in transmigratione Babylonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Et post transmigrationem Babylonis: Jechonias genuit Salathiel. Salathiel autem genuit Zorobabel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Zorobabel autem genuit Abiud. Abiud autem genuit Eliacim. Eliacim autem genuit Azor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Azor autem genuit Sadoc. Sadoc autem genuit Achim. Achim autem genuit Eliud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Eliud autem genuit Eleazar. Eleazar autem genuit Mathan. Mathan autem genuit Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Jacob autem genuit Joseph virum Mariæ, de qua natus est Jesus, qui vocatur Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Omnes itaque generationes ab Abraham usque ad David, generationes quatuordecim: et a David usque ad transmigrationem Babylonis, generationes quatuordecim: et a transmigratione Babylonis usque ad Christum, generationes quatuordecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Christi autem generatio sic erat: cum esset desponsata mater ejus Maria Joseph, antequam convenirent inventa est in utero habens de Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Joseph autem vir ejus cum esset justus, et nollet eam traducere, voluit occulte dimittere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Hæc autem eo cogitante, ecce angelus Domini apparuit in somnis ei, dicens: Joseph, fili David, noli timere accipere Mariam conjugem tuam: quod enim in ea natum est, de Spiritu Sancto est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Pariet autem filium: et vocabis nomen ejus Jesum: ipse enim salvum faciet populum suum a peccatis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Hoc autem totum factum est, ut adimpleretur quod dictum est a Domino per prophetam dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Ecce virgo in utero habebit, et pariet filium: et vocabunt nomen ejus Emmanuel, quod est interpretatum Nobiscum Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Exsurgens autem Joseph a somno, fecit sicut præcepit ei angelus Domini, et accepit conjugem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 25, 'Et non cognoscebat eam donec peperit filium suum primogenitum: et vocavit nomen ejus Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Cum ergo natus esset Jesus in Bethlehem Juda in diebus Herodis regis, ecce magi ab oriente venerunt Jerosolymam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'dicentes: Ubi est qui natus est rex Judæorum? vidimus enim stellam ejus in oriente, et venimus adorare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Audiens autem Herodes rex, turbatus est, et omnis Jerosolyma cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Et congregans omnes principes sacerdotum, et scribas populi, sciscitabatur ab eis ubi Christus nasceretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'At illi dixerunt: In Bethlehem Judæ: sic enim scriptum est per prophetam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Et tu Bethlehem terra Juda, nequaquam minima es in principibus Juda: ex te enim exiet dux, qui regat populum meum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tunc Herodes clam vocatis magis diligenter didicit ab eis tempus stellæ, quæ apparuit eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'et mittens illos in Bethlehem, dixit: Ite, et interrogate diligenter de puero: et cum inveneritis, renuntiate mihi, ut et ego veniens adorem eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Qui cum audissent regem, abierunt, et ecce stella, quam viderant in oriente, antecedebat eos, usque dum veniens staret supra, ubi erat puer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Videntes autem stellam gavisi sunt gaudio magno valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Et intrantes domum, invenerunt puerum cum Maria matre ejus, et procidentes adoraverunt eum: et apertis thesauris suis obtulerunt ei munera, aurum, thus, et myrrham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Et responso accepto in somnis ne redirent ad Herodem, per aliam viam reversi sunt in regionem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Qui cum recessissent, ecce angelus Domini apparuit in somnis Joseph, dicens: Surge, et accipe puerum, et matrem ejus, et fuge in \'gyptum, et esto ibi usque dum dicam tibi. Futurum est enim ut Herodes quærat puerum ad perdendum eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Qui consurgens accepit puerum et matrem ejus nocte, et secessit in \'gyptum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'et erat ibi usque ad obitum Herodis: ut adimpleretur quod dictum est a Domino per prophetam dicentem: Ex \'gypto vocavi filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Tunc Herodes videns quoniam illusus esset a magis, iratus est valde, et mittens occidit omnes pueros, qui erant in Bethlehem, et in omnibus finibus ejus, a bimatu et infra secundum tempus, quod exquisierat a magis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Tunc adimpletum est quod dictum est per Jeremiam prophetam dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 18, 'Vox in Rama audita est ploratus, et ululatus multus: Rachel plorans filios suos, et noluit consolari, quia non sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 19, 'Defuncto autem Herode, ecce angelus Domini apparuit in somnis Joseph in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 20, 'dicens: Surge, et accipe puerum, et matrem ejus, et vade in terram Israël: defuncti sunt enim qui quærebant animam pueri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 21, 'Qui consurgens, accepit puerum, et matrem ejus, et venit in terram Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 22, 'Audiens autem quod Archelaus regnaret in Judæa pro Herode patre suo, timuit illo ire: et admonitus in somnis, secessit in partes Galilææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 23, 'Et veniens habitavit in civitate quæ vocatur Nazareth: ut adimpleretur quod dictum est per prophetas: Quoniam Nazaræus vocabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'In diebus autem illis venit Joannes Baptista prædicans in deserto Judææ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'et dicens: Pœnitentiam agite: appropinquavit enim regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Hic est enim, qui dictus est per Isaiam prophetam dicentem: Vox clamantis in deserto: Parate viam Domini; rectas facite semitas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ipse autem Joannes habebat vestimentum de pilis camelorum, et zonam pelliceam circa lumbos suos: esca autem ejus erat locustæ, et mel silvestre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Tunc exibat ad eum Jerosolyma, et omnis Judæa, et omnis regio circa Jordanem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'et baptizabantur ab eo in Jordane, confitentes peccata sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Videns autem multos pharisæorum, et sadducæorum, venientes ad baptismum suum, dixit eis: Progenies viperarum, quis demonstravit vobis fugere a ventura ira?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Facite ergo fructum dignum pœnitentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Et ne velitis dicere intra vos: Patrem habemus Abraham. Dico enim vobis quoniam potens est Deus de lapidibus istis suscitare filios Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Jam enim securis ad radicem arborum posita est. Omnis ergo arbor, quæ non facit fructum bonum, excidetur, et in ignem mittetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Ego quidem baptizo vos in aqua in pœnitentiam: qui autem post me venturus est, fortior me est, cujus non sum dignus calceamenta portare: ipse vos baptizabit in Spiritu Sancto, et igni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Cujus ventilabrum in manu sua: et permundabit aream suam: et congregabit triticum suum in horreum, paleas autem comburet igni inextinguibili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Tunc venit Jesus a Galilæa in Jordanem ad Joannem, ut baptizaretur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Joannes autem prohibebat eum, dicens: Ego a te debeo baptizari, et tu venis ad me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Respondens autem Jesus, dixit ei: Sine modo: sic enim decet nos implere omnem justitiam. Tunc dimisit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Baptizatus autem Jesus, confestim ascendit de aqua, et ecce aperti sunt ei cæli: et vidit Spiritum Dei descendentem sicut columbam, et venientem super se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Et ecce vox de cælis dicens: Hic est Filius meus dilectus, in quo mihi complacui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Tunc Jesus ductus est in desertum a Spiritu, ut tentaretur a diabolo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Et cum jejunasset quadraginta diebus, et quadraginta noctibus, postea esuriit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Et accedens tentator dixit ei: Si Filius Dei es, dic ut lapides isti panes fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Qui respondens dixit: Scriptum est: Non in solo pane vivit homo, sed in omni verbo, quod procedit de ore Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Tunc assumpsit eum diabolus in sanctam civitatem, et statuit eum super pinnaculum templi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'et dixit ei: Si Filius Dei es, mitte te deorsum. Scriptum est enim: Quia angelis suis mandavit de te, et in manibus tollent te, ne forte offendas ad lapidem pedem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Ait illi Jesus: Rursum scriptum est: Non tentabis Dominum Deum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Iterum assumpsit eum diabolus in montem excelsum valde: et ostendit ei omnia regna mundi, et gloriam eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'et dixit ei: Hæc omnia tibi dabo, si cadens adoraveris me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Tunc dicit ei Jesus: Vade Satana: Scriptum est enim: Dominum Deum tuum adorabis, et illi soli servies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Tunc reliquit eum diabolus: et ecce angeli accesserunt, et ministrabant ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Cum autem audisset Jesus quod Joannes traditus esset, secessit in Galilæam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'et, relicta civitate Nazareth, venit, et habitavit in Capharnaum maritima, in finibus Zabulon et Nephthalim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'ut adimpleretur quod dictum est per Isaiam prophetam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Terra Zabulon, et terra Nephthalim, via maris trans Jordanem, Galilæa gentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'populus, qui sedebat in tenebris, vidit lucem magnam: et sedentibus in regione umbræ mortis, lux orta est eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Exinde cœpit Jesus prædicare, et dicere: Pœnitentiam agite: appropinquavit enim regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Ambulans autem Jesus juxta mare Galilææ, vidit duos fratres, Simonem, qui vocatur Petrus, et Andream fratrem ejus, mittentes rete in mare (erant enim piscatores),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 19, 'et ait illis: Venite post me, et faciam vos fieri piscatores hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 20, 'At illi continuo relictis retibus secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 21, 'Et procedens inde, vidit alios duos fratres, Jacobum Zebedæi, et Joannem fratrem ejus, in navi cum Zebedæo patre eorum, reficientes retia sua: et vocavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 22, 'Illi autem statim relictis retibus et patre, secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 23, 'Et circuibat Jesus totam Galilæam, docens in synagogis eorum, et prædicans Evangelium regni: et sanans omnem languorem, et omnem infirmitatem in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 24, 'Et abiit opinio ejus in totam Syriam, et obtulerunt ei omnes male habentes, variis languoribus, et tormentis comprehensos, et qui dæmonia habebant, et lunaticos, et paralyticos, et curavit eos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 25, 'et secutæ sunt eum turbæ multæ de Galilæa, et Decapoli, et de Jerosolymis, et de Judæa, et de trans Jordanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Videns autem Jesus turbas, ascendit in montem, et cum sedisset, accesserunt ad eum discipuli ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'et aperiens os suum docebat eos dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Beati pauperes spiritu: quoniam ipsorum est regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Beati mites: quoniam ipsi possidebunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Beati qui lugent: quoniam ipsi consolabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Beati qui esuriunt et sitiunt justitiam: quoniam ipsi saturabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Beati misericordes: quoniam ipsi misericordiam consequentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Beati mundo corde: quoniam ipsi Deum videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Beati pacifici: quoniam filii Dei vocabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Beati qui persecutionem patiuntur propter justitiam: quoniam ipsorum est regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Beati estis cum maledixerint vobis, et persecuti vos fuerint, et dixerint omne malum adversum vos mentientes, propter me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'gaudete, et exsultate, quoniam merces vestra copiosa est in cælis. Sic enim persecuti sunt prophetas, qui fuerunt ante vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Vos estis sal terræ. Quod si sal evanuerit, in quo salietur? ad nihilum valet ultra, nisi ut mittatur foras, et conculcetur ab hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Vos estis lux mundi. Non potest civitas abscondi supra montem posita,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'neque accendunt lucernam, et ponunt eam sub modio, sed super candelabrum, ut luceat omnibus qui in domo sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Sic luceat lux vestra coram hominibus: ut videant opera vestra bona, et glorificent Patrem vestrum, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Nolite putare quoniam veni solvere legem aut prophetas: non veni solvere, sed adimplere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Amen quippe dico vobis, donec transeat cælum et terra, jota unum aut unus apex non præteribit a lege, donec omnia fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Qui ergo solverit unum de mandatis istis minimis, et docuerit sic homines, minimus vocabitur in regno cælorum: qui autem fecerit et docuerit, hic magnus vocabitur in regno cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Dico enim vobis, quia nisi abundaverit justitia vestra plus quam scribarum et pharisæorum, non intrabitis in regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Audistis quia dictum est antiquis: Non occides: qui autem occiderit, reus erit judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 22, 'Ego autem dico vobis: quia omnis qui irascitur fratri suo, reus erit judicio. Qui autem dixerit fratri suo, raca: reus erit concilio. Qui autem dixerit, fatue: reus erit gehennæ ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 23, 'Si ergo offers munus tuum ad altare, et ibi recordatus fueris quia frater tuus habet aliquid adversum te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 24, 'relinque ibi munus tuum ante altare, et vade prius reconciliari fratri tuo: et tunc veniens offeres munus tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 25, 'Esto consentiens adversario tuo cito dum es in via cum eo: ne forte tradat te adversarius judici, et judex tradat te ministro: et in carcerem mittaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 26, 'Amen dico tibi, non exies inde, donec reddas novissimum quadrantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 27, 'Audistis quia dictum est antiquis: Non mœchaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 28, 'Ego autem dico vobis: quia omnis qui viderit mulierem ad concupiscendum eam, jam mœchatus est eam in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 29, 'Quod si oculus tuus dexter scandalizat te, erue eum, et projice abs te: expedit enim tibi ut pereat unum membrorum tuorum, quam totum corpus tuum mittatur in gehennam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 30, 'Et si dextra manus tua scandalizat te, abscide eam, et projice abs te: expedit enim tibi ut pereat unum membrorum tuorum, quam totum corpus tuum eat in gehennam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 31, 'Dictum est autem: Quicumque dimiserit uxorem suam, det ei libellum repudii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 32, 'Ego autem dico vobis: quia omnis qui dimiserit uxorem suam, excepta fornicationis causa, facit eam mœchari: et qui dimissam duxerit, adulterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 33, 'Iterum audistis quia dictum est antiquis: Non perjurabis: reddes autem Domino juramenta tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 34, 'Ego autem dico vobis, non jurare omnino, neque per cælum, quia thronus Dei est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 35, 'neque per terram, quia scabellum est pedum ejus: neque per Jerosolymam, quia civitas est magni regis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 36, 'neque per caput tuum juraveris, quia non potes unum capillum album facere, aut nigrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 37, 'Sit autem sermo vester, est, est: non, non: quod autem his abundantius est, a malo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 38, 'Audistis quia dictum est: Oculum pro oculo, et dentem pro dente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 39, 'Ego autem dico vobis, non resistere malo: sed si quis te percusserit in dexteram maxillam tuam, præbe illi et alteram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 40, 'et ei, qui vult tecum judicio contendere, et tunicam tuam tollere, dimitte ei et pallium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 41, 'et quicumque te angariaverit mille passus, vade cum illo et alia duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 42, 'Qui petit a te, da ei: et volenti mutuari a te, ne avertaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 43, 'Audistis quia dictum est: Diliges proximum tuum, et odio habebis inimicum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 44, 'Ego autem dico vobis: diligite inimicos vestros, benefacite his qui oderunt vos, et orate pro persequentibus et calumniantibus vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 45, 'ut sitis filii Patris vestri, qui in cælis est: qui solem suum oriri facit super bonos et malos: et pluit super justos et injustos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 46, 'Si enim diligitis eos qui vos diligunt, quam mercedem habebitis? nonne et publicani hoc faciunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 47, 'Et si salutaveritis fratres vestros tantum, quid amplius facitis? nonne et ethnici hoc faciunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 48, 'Estote ergo vos perfecti, sicut et Pater vester cælestis perfectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Attendite ne justitiam vestram faciatis coram hominibus, ut videamini ab eis: alioquin mercedem non habebitis apud Patrem vestrum qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Cum ergo facis eleemosynam, noli tuba canere ante te, sicut hypocritæ faciunt in synagogis, et in vicis, ut honorificentur ab hominibus. Amen dico vobis, receperunt mercedem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Te autem faciente eleemosynam, nesciat sinistra tua quid faciat dextera tua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'ut sit eleemosyna tua in abscondito, et Pater tuus, qui videt in abscondito, reddet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Et cum oratis, non eritis sicut hypocritæ qui amant in synagogis et in angulis platearum stantes orare, ut videantur ab hominibus: amen dico vobis, receperunt mercedem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'Tu autem cum oraveris, intra in cubiculum tuum, et clauso ostio, ora Patrem tuum in abscondito: et Pater tuus, qui videt in abscondito, reddet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'Orantes autem, nolite multum loqui, sicut ethnici, putant enim quod in multiloquio suo exaudiantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Nolite ergo assimilari eis: scit enim Pater vester, quid opus sit vobis, antequam petatis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Sic ergo vos orabitis: Pater noster, qui es in cælis, sanctificetur nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Adveniat regnum tuum; fiat voluntas tua, sicut in cælo et in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Panem nostrum supersubstantialem da nobis hodie,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'et dimitte nobis debita nostra, sicut et nos dimittimus debitoribus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Et ne nos inducas in tentationem, sed libera nos a malo. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Si enim dimiseritis hominibus peccata eorum: dimittet et vobis Pater vester cælestis delicta vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Si autem non dimiseritis hominibus: nec Pater vester dimittet vobis peccata vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Cum autem jejunatis, nolite fieri sicut hypocritæ, tristes. Exterminant enim facies suas, ut appareant hominibus jejunantes. Amen dico vobis, quia receperunt mercedem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Tu autem, cum jejunas, unge caput tuum, et faciem tuam lava,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'ne videaris hominibus jejunans, sed Patri tuo, qui est in abscondito: et Pater tuus, qui videt in abscondito, reddet tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 19, 'Nolite thesaurizare vobis thesauros in terra: ubi ærugo, et tinea demolitur: et ubi fures effodiunt, et furantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 20, 'Thesaurizate autem vobis thesauros in cælo, ubi neque ærugo, neque tinea demolitur, et ubi fures non effodiunt, nec furantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 21, 'Ubi enim est thesaurus tuus, ibi est et cor tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 22, 'Lucerna corporis tui est oculus tuus. Si oculus tuus fuerit simplex, totum corpus tuum lucidum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 23, 'Si autem oculus tuus fuerit nequam, totum corpus tuum tenebrosum erit. Si ergo lumen, quod in te est, tenebræ sunt: ipsæ tenebræ quantæ erunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 24, 'Nemo potest duobus dominis servire: aut enim unum odio habebit, et alterum diliget: aut unum sustinebit, et alterum contemnet. Non potestis Deo servire et mammonæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 25, 'Ideo dico vobis, ne solliciti sitis animæ vestræ quid manducetis, neque corpori vestro quid induamini. Nonne anima plus est quam esca, et corpus plus quam vestimentum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 26, 'Respicite volatilia cæli, quoniam non serunt, neque metunt, neque congregant in horrea: et Pater vester cælestis pascit illa. Nonne vos magis pluris estis illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 27, 'Quis autem vestrum cogitans potest adjicere ad staturam suam cubitum unum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 28, 'Et de vestimento quid solliciti estis? Considerate lilia agri quomodo crescunt: non laborant, neque nent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 29, 'Dico autem vobis, quoniam nec Salomon in omni gloria sua coopertus est sicut unum ex istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 30, 'Si autem fœnum agri, quod hodie est, et cras in clibanum mittitur, Deus sic vestit, quanto magis vos modicæ fidei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 31, 'Nolite ergo solliciti esse, dicentes: Quid manducabimus, aut quid bibemus, aut quo operiemur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 32, 'hæc enim omnia gentes inquirunt. Scit enim Pater vester, quia his omnibus indigetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 33, 'Quærite ergo primum regnum Dei, et justitiam ejus: et hæc omnia adjicientur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 34, 'Nolite ergo solliciti esse in crastinum. Crastinus enim dies sollicitus erit sibi ipsi: sufficit diei malitia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Nolite judicare, ut non judicemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'In quo enim judicio judicaveritis, judicabimini: et in qua mensura mensi fueritis, remetietur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Quid autem vides festucam in oculo fratris tui, et trabem in oculo tuo non vides?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'aut quomodo dicis fratri tuo: Sine ejiciam festucam de oculo tuo, et ecce trabs est in oculo tuo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Hypocrita, ejice primum trabem de oculo tuo, et tunc videbis ejicere festucam de oculo fratris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Nolite dare sanctum canibus: neque mittatis margaritas vestras ante porcos, ne forte conculcent eas pedibus suis, et conversi dirumpant vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Petite, et dabitur vobis: quærite, et invenietis: pulsate, et aperietur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Omnis enim qui petit, accipit: et qui quærit, invenit: et pulsanti aperietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Aut quis est ex vobis homo, quem si petierit filius suus panem, numquid lapidem porriget ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'aut si piscem petierit, numquid serpentem porriget ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Si ergo vos, cum sitis mali, nostis bona data dare filiis vestris: quanto magis Pater vester, qui in cælis est, dabit bona petentibus se?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Omnia ergo quæcumque vultis ut faciant vobis homines, et vos facite illis. Hæc est enim lex, et prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Intrate per angustam portam: quia lata porta, et spatiosa via est, quæ ducit ad perditionem, et multi sunt qui intrant per eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Quam angusta porta, et arcta via est, quæ ducit ad vitam: et pauci sunt qui inveniunt eam!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Attendite a falsis prophetis, qui veniunt ad vos in vestimentis ovium, intrinsecus autem sunt lupi rapaces:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'a fructibus eorum cognoscetis eos. Numquid colligunt de spinis uvas, aut de tribulis ficus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 17, 'Sic omnis arbor bona fructus bonos facit: mala autem arbor malos fructus facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 18, 'Non potest arbor bona malos fructus facere: neque arbor mala bonos fructus facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 19, 'Omnis arbor, quæ non facit fructum bonum, excidetur, et in ignem mittetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 20, 'Igitur ex fructibus eorum cognoscetis eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 21, 'Non omnis qui dicit mihi, Domine, Domine, intrabit in regnum cælorum: sed qui facit voluntatem Patris mei, qui in cælis est, ipse intrabit in regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 22, 'Multi dicent mihi in illa die: Domine, Domine, nonne in nomine tuo prophetavimus, et in nomine tuo dæmonia ejecimus, et in nomine tuo virtutes multas fecimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 23, 'Et tunc confitebor illis: Quia numquam novi vos: discedite a me, qui operamini iniquitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 24, 'Omnis ergo qui audit verba mea hæc, et facit ea, assimilabitur viro sapienti, qui ædificavit domum suam supra petram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 25, 'et descendit pluvia, et venerunt flumina, et flaverunt venti, et irruerunt in domum illam, et non cecidit: fundata enim erat super petram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 26, 'Et omnis qui audit verba mea hæc, et non facit ea, similis erit viro stulto, qui ædificavit domum suam super arenam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 27, 'et descendit pluvia, et venerunt flumina, et flaverunt venti, et irruerunt in domum illam, et cecidit, et fuit ruina illius magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 28, 'Et factum est: cum consummasset Jesus verba hæc, admirabantur turbæ super doctrina ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 29, 'Erat enim docens eos sicut potestatem habens, et non sicut scribæ eorum, et pharisæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Cum autem descendisset de monte, secutæ sunt eum turbæ multæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'et ecce leprosus veniens, adorabat eum, dicens: Domine, si vis, potes me mundare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Et extendens Jesus manum, tetigit eum, dicens: Volo: mundare. Et confestim mundata est lepra ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Et ait illi Jesus: Vide, nemini dixeris: sed vade, ostende te sacerdoti, et offer munus, quod præcepit Moyses, in testimonium illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Cum autem introisset Capharnaum, accessit ad eum centurio, rogans eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'et dicens: Domine, puer meus jacet in domo paralyticus, et male torquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Et ait illi Jesus: Ego veniam, et curabo eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Et respondens centurio, ait: Domine, non sum dignus ut intres sub tectum meum: sed tantum dic verbo, et sanabitur puer meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Nam et ego homo sum sub potestate constitutus, habens sub me milites, et dico huic: Vade, et vadit: et alii: Veni, et venit: et servo meo: Fac hoc, et facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Audiens autem Jesus miratus est, et sequentibus se dixit: Amen dico vobis, non inveni tantam fidem in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Dico autem vobis, quod multi ab oriente et occidente venient, et recumbent cum Abraham, et Isaac, et Jacob in regno cælorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'filii autem regni ejicientur in tenebras exteriores: ibi erit fletus et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Et dixit Jesus centurioni: Vade, et sicut credidisti, fiat tibi. Et sanatus est puer in illa hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Et cum venisset Jesus in domum Petri, vidit socrum ejus jacentem, et febricitantem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'et tetigit manum ejus, et dimisit eam febris, et surrexit, et ministrabat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Vespere autem facto, obtulerunt ei multos dæmonia habentes: et ejiciebat spiritus verbo, et omnes male habentes curavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'ut adimpleretur quod dictum est per Isaiam prophetam, dicentem: Ipse infirmitates nostras accepit: et ægrotationes nostras portavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Videns autem Jesus turbas multas circum se, jussit ire trans fretum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Et accedens unus scriba, ait illi: Magister, sequar te, quocumque ieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Et dicit ei Jesus: Vulpes foveas habent, et volucres cæli nidos; Filius autem hominis non habet ubi caput reclinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Alius autem de discipulis ejus ait illi: Domine, permitte me primum ire, et sepelire patrem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Jesus autem ait illi: Sequere me, et dimitte mortuos sepelire mortuos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Et ascendente eo in naviculam, secuti sunt eum discipuli ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'et ecce motus magnus factus est in mari, ita ut navicula operiretur fluctibus: ipse vero dormiebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 25, 'Et accesserunt ad eum discipuli ejus, et suscitaverunt eum, dicentes: Domine, salva nos: perimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 26, 'Et dicit eis Jesus: Quid timidi estis, modicæ fidei? Tunc surgens imperavit ventis, et mari, et facta est tranquillitas magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 27, 'Porro homines mirati sunt, dicentes: Qualis est hic, quia venti et mare obediunt ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 28, 'Et cum venisset trans fretum in regionem Gerasenorum, occurrerunt ei duo habentes dæmonia, de monumentis exeuntes, sævi nimis, ita ut nemo posset transire per viam illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 29, 'Et ecce clamaverunt, dicentes: Quid nobis et tibi, Jesu fili Dei? Venisti huc ante tempus torquere nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 30, 'Erat autem non longe ab illis grex multorum porcorum pascens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 31, 'Dæmones autem rogabant eum, dicentes: Si ejicis nos hinc, mitte nos in gregem porcorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 32, 'Et ait illis: Ite. At illi exeuntes abierunt in porcos, et ecce impetu abiit totus grex per præceps in mare: et mortui sunt in aquis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 33, 'Pastores autem fugerunt: et venientes in civitatem, nuntiaverunt omnia, et de eis qui dæmonia habuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 34, 'Et ecce tota civitas exiit obviam Jesu: et viso eo, rogabant ut transiret a finibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Et ascendens in naviculam, transfretavit, et venit in civitatem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Et ecce offerebant ei paralyticum jacentem in lecto. Et videns Jesus fidem illorum, dixit paralytico: Confide fili, remittuntur tibi peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Et ecce quidam de scribis dixerunt intra se: Hic blasphemat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Et cum vidisset Jesus cogitationes eorum, dixit: Ut quid cogitatis mala in cordibus vestris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Quid est facilius dicere: Dimittuntur tibi peccata tua: an dicere: Surge, et ambula?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ut autem sciatis, quia Filius hominis habet potestatem in terra dimittendi peccata, tunc ait paralytico: Surge, tolle lectum tuum, et vade in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Et surrexit, et abiit in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Videntes autem turbæ timuerunt, et glorificaverunt Deum, qui dedit potestatem talem hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Et, cum transiret inde Jesus, vidit hominem sedentem in telonio, Matthæum nomine. Et ait illi: Sequere me. Et surgens, secutus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Et factum est, discumbente eo in domo, ecce multi publicani et peccatores venientes, discumbebant cum Jesu, et discipulis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Et videntes pharisæi, dicebant discipulis ejus: Quare cum publicanis et peccatoribus manducat magister vester?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'At Jesus audiens, ait: Non est opus valentibus medicus, sed male habentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Euntes autem discite quid est: Misericordiam volo, et non sacrificium. Non enim veni vocare justos, sed peccatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Tunc accesserunt ad eum discipuli Joannis, dicentes: Quare nos, et pharisæi, jejunamus frequenter: discipuli autem tui non jejunant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Et ait illis Jesus: Numquid possunt filii sponsi lugere, quamdiu cum illis est sponsus? Venient autem dies cum auferetur ab eis sponsus: et tunc jejunabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 16, 'Nemo autem immittit commissuram panni rudis in vestimentum vetus: tollit enim plenitudinem ejus a vestimento, et pejor scissura fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 17, 'Neque mittunt vinum novum in utres veteres: alioquin rumpuntur utres, et vinum effunditur, et utres pereunt. Sed vinum novum in utres novos mittunt: et ambo conservantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 18, 'Hæc illo loquente ad eos, ecce princeps unus accessit, et adorabat eum, dicens: Domine, filia mea modo defuncta est: sed veni, impone manum tuam super eam, et vivet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 19, 'Et surgens Jesus, sequebatur eum, et discipuli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 20, 'Et ecce mulier, quæ sanguinis fluxum patiebatur duodecim annis, accessit retro, et tetigit fimbriam vestimenti ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 21, 'Dicebat enim intra se: Si tetigero tantum vestimentum ejus, salva ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 22, 'At Jesus conversus, et videns eam, dixit: Confide, filia, fides tua te salvam fecit. Et salva facta est mulier ex illa hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 23, 'Et cum venisset Jesus in domum principis, et vidisset tibicines et turbam tumultuantem, dicebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 24, 'Recedite: non est enim mortua puella, sed dormit. Et deridebant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 25, 'Et cum ejecta esset turba, intravit: et tenuit manum ejus, et surrexit puella.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 26, 'Et exiit fama hæc in universam terram illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 27, 'Et transeunte inde Jesu, secuti sunt eum duo cæci, clamantes, et dicentes: Miserere nostri, fili David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 28, 'Cum autem venisset domum, accesserunt ad eum cæci. Et dicit eis Jesus: Creditis quia hoc possum facere vobis? Dicunt ei: Utique, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 29, 'Tunc tetigit oculos eorum, dicens: Secundum fidem vestram, fiat vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 30, 'Et aperti sunt oculi eorum: et comminatus est illis Jesus, dicens: Videte ne quis sciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 31, 'Illi autem exeuntes, diffamaverunt eum in tota terra illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 32, 'Egressis autem illis, ecce obtulerunt ei hominem mutum, dæmonium habentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 33, 'Et ejecto dæmonio, locutus est mutus, et miratæ sunt turbæ, dicentes: Numquam apparuit sic in Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 34, 'Pharisæi autem dicebant: In principe dæmoniorum ejicit dæmones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 35, 'Et circuibat Jesus omnes civitates, et castella, docens in synagogis eorum, et prædicans Evangelium regni, et curans omnem languorem, et omnem infirmitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 36, 'Videns autem turbas, misertus est eis: quia erant vexati, et jacentes sicut oves non habentes pastorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 37, 'Tunc dicit discipulis suis: Messis quidem multa, operarii autem pauci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 38, 'Rogate ergo Dominum messis, ut mittat operarios in messem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Et convocatis duodecim discipulis suis, dedit illis potestatem spirituum immundorum, ut ejicerent eos, et curarent omnem languorem, et omnem infirmitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Duodecim autem Apostolorum nomina sunt hæc. Primus, Simon, qui dicitur Petrus: et Andreas frater ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Jacobus Zebedæi, et Joannes frater ejus, Philippus, et Bartholomæus, Thomas, et Matthæus publicanus, Jacobus Alphæi, et Thaddæus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Simon Chananæus, et Judas Iscariotes, qui et tradidit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Hos duodecim misit Jesus, præcipiens eis, dicens: In viam gentium ne abieritis, et in civitates Samaritanorum ne intraveritis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'sed potius ite ad oves quæ perierunt domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Euntes autem prædicate, dicentes: Quia appropinquavit regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Infirmos curate, mortuos suscitate, leprosos mundate, dæmones ejicite: gratis accepistis, gratis date.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Nolite possidere aurum, neque argentum, neque pecuniam in zonis vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'non peram in via, neque duas tunicas, neque calceamenta, neque virgam: dignus enim est operarius cibo suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'In quamcumque autem civitatem aut castellum intraveritis, interrogate, quis in ea dignus sit: et ibi manete donec exeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Intrantes autem in domum, salutate eam, dicentes: Pax huic domui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Et siquidem fuerit domus illa digna, veniet pax vestra super eam: si autem non fuerit digna, pax vestra revertetur ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Et quicumque non receperit vos, neque audierit sermones vestros: exeuntes foras de domo, vel civitate, excutite pulverem de pedibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Amen dico vobis: Tolerabilius erit terræ Sodomorum et Gomorrhæorum in die judicii, quam illi civitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Ecce ego mitto vos sicut oves in medio luporum. Estote ergo prudentes sicut serpentes, et simplices sicut columbæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Cavete autem ab hominibus. Tradent enim vos in conciliis, et in synagogis suis flagellabunt vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'et ad præsides, et ad reges ducemini propter me in testimonium illis, et gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 19, 'Cum autem tradent vos, nolite cogitare quomodo, aut quid loquamini: dabitur enim vobis in illa hora, quid loquamini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 20, 'non enim vos estis qui loquimini, sed Spiritus Patris vestri, qui loquitur in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 21, 'Tradet autem frater fratrem in mortem, et pater filium: et insurgent filii in parentes, et morte eos afficient:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 22, 'et eritis odio omnibus propter nomen meum: qui autem perseveraverit usque in finem, hic salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 23, 'Cum autem persequentur vos in civitate ista, fugite in aliam. Amen dico vobis, non consummabitis civitates Israël, donec veniat Filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 24, 'Non est discipulus super magistrum, nec servus super dominum suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 25, 'sufficit discipulo ut sit sicut magister ejus, et servo, sicut dominus ejus. Si patremfamilias Beelzebub vocaverunt, quanto magis domesticos ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 26, 'Ne ergo timueritis eos. Nihil enim est opertum, quod non revelabitur: et occultum, quod non scietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 27, 'Quod dico vobis in tenebris, dicite in lumine: et quod in aure auditis, prædicate super tecta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 28, 'Et nolite timere eos qui occidunt corpus, animam autem non possunt occidere: sed potius timete eum, qui potest et animam et corpus perdere in gehennam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 29, 'Nonne duo passeres asse veneunt? et unus ex illis non cadet super terram sine Patre vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 30, 'Vestri autem capilli capitis omnes numerati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 31, 'Nolite ergo timere: multis passeribus meliores estis vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 32, 'Omnis ergo qui confitebitur me coram hominibus, confitebor et ego eum coram Patre meo, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 33, 'Qui autem negaverit me coram hominibus, negabo et ego eum coram Patre meo, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 34, 'Nolite arbitrari quia pacem venerim mittere in terram: non veni pacem mittere, sed gladium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 35, 'veni enim separare hominem adversus patrem suum, et filiam adversus matrem suam, et nurum adversus socrum suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 36, 'et inimici hominis, domestici ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 37, 'Qui amat patrem aut matrem plus quam me, non est me dignus: et qui amat filium aut filiam super me, non est me dignus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 38, 'Et qui non accipit crucem suam, et sequitur me, non est me dignus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 39, 'Qui invenit animam suam, perdet illam: et qui perdiderit animam suam propter me, inveniet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 40, 'Qui recipit vos, me recipit: et qui me recipit, recipit eum qui me misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 41, 'Qui recipit prophetam in nomine prophetæ, mercedem prophetæ accipiet: et qui recipit justum in nomine justi, mercedem justi accipiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 42, 'Et quicumque potum dederit uni ex minimis istis calicem aquæ frigidæ tantum in nomine discipuli: amen dico vobis, non perdet mercedem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Et factum est, cum consummasset Jesus, præcipiens duodecim discipulis suis, transiit inde ut doceret, et prædicaret in civitatibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Joannes autem cum audisset in vinculis opera Christi, mittens duos de discipulis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'ait illi: Tu es, qui venturus es, an alium exspectamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Et respondens Jesus ait illis: Euntes renuntiate Joanni quæ audistis, et vidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Cæci vident, claudi ambulant, leprosi mundantur, surdi audiunt, mortui resurgunt, pauperes evangelizantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'et beatus est, qui non fuerit scandalizatus in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Illis autem abeuntibus, cœpit Jesus dicere ad turbas de Joanne: Quid existis in desertum videre? arundinem vento agitatam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Sed quid existis videre? hominem mollibus vestitum? Ecce qui mollibus vestiuntur, in domibus regum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Sed quid existis videre? prophetam? Etiam dico vobis, et plus quam prophetam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Hic est enim de quo scriptum est: Ecce ego mitto angelum meum ante faciem tuam, qui præparabit viam tuam ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Amen dico vobis, non surrexit inter natos mulierum major Joanne Baptista: qui autem minor est in regno cælorum, major est illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'A diebus autem Joannis Baptistæ usque nunc, regnum cælorum vim patitur, et violenti rapiunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Omnes enim prophetæ et lex usque ad Joannem prophetaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'et si vultis recipere, ipse est Elias, qui venturus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Cui autem similem æstimabo generationem istam? Similis est pueris sedentibus in foro: qui clamantes coæqualibus');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'dicunt: Cecinimus vobis, et non saltastis: lamentavimus, et non planxistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Venit enim Joannes neque manducans, neque bibens, et dicunt: Dæmonium habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Venit Filius hominis manducans, et bibens, et dicunt: Ecce homo vorax, et potator vini, publicanorum et peccatorum amicus. Et justificata est sapientia a filiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Tunc cœpit exprobrare civitatibus, in quibus factæ sunt plurimæ virtutes ejus, quia non egissent pœnitentiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Væ tibi Corozain, væ tibi Bethsaida: quia, si in Tyro et Sidone factæ essent virtutes quæ factæ sunt in vobis, olim in cilicio et cinere pœnitentiam egissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Verumtamen dico vobis: Tyro et Sidoni remissius erit in die judicii, quam vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Et tu Capharnaum, numquid usque in cælum exaltaberis? usque in infernum descendes, quia si in Sodomis factæ fuissent virtutes quæ factæ sunt in te, forte mansissent usque in hanc diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Verumtamen dico vobis, quia terræ Sodomorum remissius erit in die judicii, quam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'In illo tempore respondens Jesus dixit: Confiteor tibi, Pater, Domine cæli et terræ, quia abscondisti hæc a sapientibus, et prudentibus, et revelasti ea parvulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Ita Pater: quoniam sic fuit placitum ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Omnia mihi tradita sunt a Patre meo. Et nemo novit Filium, nisi Pater: neque Patrem quis novit, nisi Filius, et cui voluerit Filius revelare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Venite ad me omnes qui laboratis, et onerati estis, et ego reficiam vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Tollite jugum meum super vos, et discite a me, quia mitis sum, et humilis corde: et invenietis requiem animabus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Jugum enim meum suave est, et onus meum leve.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'In illo tempore abiit Jesus per sata sabbato: discipuli autem ejus esurientes cœperunt vellere spicas, et manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Pharisæi autem videntes, dixerunt ei: Ecce discipuli tui faciunt quod non licet facere sabbatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'At ille dixit eis: Non legistis quid fecerit David, quando esuriit, et qui cum eo erant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'quomodo intravit in domum Dei, et panes propositionis comedit, quos non licebat ei edere, neque his qui cum eo erant, nisi solis sacerdotibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'aut non legistis in lege quia sabbatis sacerdotes in templo sabbatum violant, et sine crimine sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Dico autem vobis, quia templo major est hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Si autem sciretis, quid est: Misericordiam volo, et non sacrificium: numquam condemnassetis innocentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'dominus enim est Filius hominis etiam sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Et cum inde transisset, venit in synagogam eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Et ecce homo manum habens aridam, et interrogabant eum, dicentes: Si licet sabbatis curare? ut accusarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ipse autem dixit illis: Quis erit ex vobis homo, qui habeat ovem unam, et si ceciderit hæc sabbatis in foveam, nonne tenebit et levabit eam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Quanto magis melior est homo ove? itaque licet sabbatis benefacere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Tunc ait homini: Extende manum tuam. Et extendit, et restituta est sanitati sicut altera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Exeuntes autem pharisæi, consilium faciebant adversus eum, quomodo perderent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Jesus autem sciens recessit inde: et secuti sunt eum multi, et curavit eos omnes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'et præcepit eis ne manifestum eum facerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Ut adimpleretur quod dictum est per Isaiam prophetam, dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Ecce puer meus, quem elegi, dilectus meus, in quo bene complacuit animæ meæ. Ponam spiritum meum super eum, et judicium gentibus nuntiabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Non contendet, neque clamabit, neque audiet aliquis in plateis vocem ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'arundinem quassatam non confringet, et linum fumigans non extinguet, donec ejiciat ad victoriam judicium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'et in nomine ejus gentes sperabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 22, 'Tunc oblatus est ei dæmonium habens, cæcus, et mutus, et curavit eum ita ut loqueretur, et videret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 23, 'Et stupebant omnes turbæ, et dicebant: Numquid hic est filius David?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 24, 'Pharisæi autem audientes, dixerunt: Hic non ejicit dæmones nisi in Beelzebub principe dæmoniorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 25, 'Jesus autem sciens cogitationes eorum, dixit eis: Omne regnum divisum contra se desolabitur: et omnis civitas vel domus divisa contra se, non stabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 26, 'Et si Satanas Satanam ejicit, adversus se divisus est: quomodo ergo stabit regnum ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 27, 'Et si ego in Beelzebub ejicio dæmones, filii vestri in quo ejiciunt? ideo ipsi judices vestri erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 28, 'Si autem ego in Spiritu Dei ejicio dæmones, igitur pervenit in vos regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 29, 'Aut quomodo potest quisquam intrare in domum fortis, et vasa ejus diripere, nisi prius alligaverit fortem? et tunc domum illius diripiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 30, 'Qui non est mecum, contra me est; et qui non congregat mecum, spargit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 31, 'Ideo dico vobis: Omne peccatum et blasphemia remittetur hominibus, Spiritus autem blasphemia non remittetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 32, 'Et quicumque dixerit verbum contra Filium hominis, remittetur ei: qui autem dixerit contra Spiritum Sanctum, non remittetur ei, neque in hoc sæculo, neque in futuro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 33, 'Aut facite arborem bonam, et fructum ejus bonum: aut facite arborem malam, et fructum ejus malum: siquidem ex fructu arbor agnoscitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 34, 'Progenies viperarum, quomodo potestis bona loqui, cum sitis mali? ex abundantia enim cordis os loquitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 35, 'Bonus homo de bono thesauro profert bona: et malus homo de malo thesauro profert mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 36, 'Dico autem vobis quoniam omne verbum otiosum, quod locuti fuerint homines, reddent rationem de eo in die judicii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 37, 'Ex verbis enim tuis justificaberis et ex verbis tuis condemnaberis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 38, 'Tunc responderunt ei quidam de scribis et pharisæis, dicentes: Magister, volumus a te signum videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 39, 'Qui respondens ait illis: Generatio mala et adultera signum quærit: et signum non dabitur ei, nisi signum Jonæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 40, 'Sicut enim fuit Jonas in ventre ceti tribus diebus, et tribus noctibus, sic erit Filius hominis in corde terræ tribus diebus et tribus noctibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 41, 'Viri Ninivitæ surgent in judicio cum generatione ista, et condemnabunt eam: quia pœnitentiam egerunt in prædicatione Jonæ, et ecce plus quam Jonas hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 42, 'Regina austri surget in judicio cum generatione ista, et condemnabit eam: quia venit a finibus terræ audire sapientiam Salomonis, et ecce plus quam Salomon hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 43, 'Cum autem immundus spiritus exierit ab homine, ambulat per loca arida, quærens requiem, et non invenit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 44, 'Tunc dicit: Revertar in domum meam, unde exivi. Et veniens invenit eam vacantem, scopis mundatam, et ornatam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 45, 'Tunc vadit, et assumit septem alios spiritus secum nequiores se, et intrantes habitant ibi: et fiunt novissima hominis illius pejora prioribus. Sic erit et generationi huic pessimæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 46, 'Adhuc eo loquente ad turbas, ecce mater ejus et fratres stabant foris, quærentes loqui ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 47, 'Dixit autem ei quidam: Ecce mater tua, et fratres tui foris stant quærentes te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 48, 'At ipse respondens dicenti sibi, ait: Quæ est mater mea, et qui sunt fratres mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 49, 'Et extendens manum in discipulos suos, dixit: Ecce mater mea, et fratres mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 50, 'Quicumque enim fecerit voluntatem Patris mei, qui in cælis est, ipse meus frater, et soror, et mater est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'In illo die exiens Jesus de domo, sedebat secus mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Et congregatæ sunt ad eum turbæ multæ, ita ut naviculam ascendens sederet: et omnis turba stabat in littore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'et locutus est eis multa in parabolis, dicens: Ecce exiit qui seminat, seminare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Et dum seminat, quædam ceciderunt secus viam, et venerunt volucres cæli, et comederunt ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Alia autem ceciderunt in petrosa, ubi non habebant terram multam: et continuo exorta sunt, quia non habebant altitudinem terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'sole autem orto æstuaverunt; et quia non habebant radicem, aruerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Alia autem ceciderunt in spinas: et creverunt spinæ, et suffocaverunt ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Alia autem ceciderunt in terram bonam: et dabant fructum, aliud centesimum, aliud sexagesimum, aliud trigesimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Et accedentes discipuli dixerunt ei: Quare in parabolis loqueris eis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Qui respondens, ait illis: Quia vobis datum est nosse mysteria regni cælorum: illis autem non est datum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Qui enim habet, dabitur ei, et abundabit: qui autem non habet, et quod habet auferetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Ideo in parabolis loquor eis: quia videntes non vident, et audientes non audiunt, neque intelligunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Et adimpletur in eis prophetia Isaiæ, dicentis: Auditu audietis, et non intelligetis: et videntes videbitis, et non videbitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 15, 'Incrassatum est enim cor populi hujus, et auribus graviter audierunt, et oculos suos clauserunt: nequando videant oculis, et auribus audiant, et corde intelligant, et convertantur, et sanem eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 16, 'Vestri autem beati oculi quia vident, et aures vestræ quia audiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 17, 'Amen quippe dico vobis, quia multi prophetæ et justi cupierunt videre quæ videtis, et non viderunt: et audire quæ auditis, et non audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 18, 'Vos ergo audite parabolam seminantis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 19, 'Omnis qui audit verbum regni, et non intelligit, venit malus, et rapit quod seminatum est in corde ejus: hic est qui secus viam seminatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 20, 'Qui autem super petrosa seminatus est, hic est qui verbum audit, et continuo cum gaudio accipit illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 21, 'non habet autem in se radicem, sed est temporalis: facta autem tribulatione et persecutione propter verbum, continuo scandalizatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 22, 'Qui autem seminatus est in spinis, hic est qui verbum audit, et sollicitudo sæculi istius, et fallacia divitiarum suffocat verbum, et sine fructu efficitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 23, 'Qui vero in terram bonam seminatus est, hic est qui audit verbum, et intelligit, et fructum affert, et facit aliud quidem centesimum, aliud autem sexagesimum, aliud vero trigesimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 24, 'Aliam parabolam proposuit illis, dicens: Simile factum est regnum cælorum homini, qui seminavit bonum semen in agro suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 25, 'cum autem dormirent homines, venit inimicus ejus, et superseminavit zizania in medio tritici, et abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 26, 'Cum autem crevisset herba, et fructum fecisset, tunc apparuerunt et zizania.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 27, 'Accedentes autem servi patrisfamilias, dixerunt ei: Domine, nonne bonum semen seminasti in agro tuo? unde ergo habet zizania?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 28, 'Et ait illis: Inimicus homo hoc fecit. Servi autem dixerunt ei: Vis, imus, et colligimus ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 29, 'Et ait: Non: ne forte colligentes zizania, eradicetis simul cum eis et triticum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 30, 'Sinite utraque crescere usque ad messem, et in tempore messis dicam messoribus: Colligite primum zizania, et alligate ea in fasciculos ad comburendum: triticum autem congregate in horreum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 31, 'Aliam parabolam proposuit eis dicens: Simile est regnum cælorum grano sinapis, quod accipiens homo seminavit in agro suo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 32, 'quod minimum quidem est omnibus seminibus: cum autem creverit, majus est omnibus oleribus, et fit arbor, ita ut volucres cæli veniant, et habitent in ramis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 33, 'Aliam parabolam locutus est eis: Simile est regnum cælorum fermento, quod acceptum mulier abscondit in farinæ satis tribus, donec fermentatum est totum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 34, 'Hæc omnia locutus est Jesus in parabolis ad turbas: et sine parabolis non loquebatur eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 35, 'ut impleretur quod dictum erat per prophetam dicentem: Aperiam in parabolis os meum; eructabo abscondita a constitutione mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 36, 'Tunc, dimissis turbis, venit in domum: et accesserunt ad eum discipuli ejus, dicentes: Edissere nobis parabolam zizaniorum agri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 37, 'Qui respondens ait illis: Qui seminat bonum semen, est Filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 38, 'Ager autem est mundus. Bonum vero semen, hi sunt filii regni. Zizania autem, filii sunt nequam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 39, 'Inimicus autem, qui seminavit ea, est diabolus. Messis vero, consummatio sæculi est. Messores autem, angeli sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 40, 'Sicut ergo colliguntur zizania, et igni comburuntur: sic erit in consummatione sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 41, 'Mittet Filius hominis angelos suos, et colligent de regno ejus omnia scandala, et eos qui faciunt iniquitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 42, 'et mittent eos in caminum ignis. Ibi erit fletus et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 43, 'Tunc justi fulgebunt sicut sol in regno Patris eorum. Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 44, 'Simile est regnum cælorum thesauro abscondito in agro: quem qui invenit homo, abscondit, et præ gaudio illius vadit, et vendit universa quæ habet, et emit agrum illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 45, 'Iterum simile est regnum cælorum homini negotiatori, quærenti bonas margaritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 46, 'Inventa autem una pretiosa margarita, abiit, et vendidit omnia quæ habuit, et emit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 47, 'Iterum simile est regnum cælorum sagenæ missæ in mare, et ex omni genere piscium congreganti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 48, 'Quam, cum impleta esset, educentes, et secus littus sedentes, elegerunt bonos in vasa, malos autem foras miserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 49, 'Sic erit in consummatione sæculi: exibunt angeli, et separabunt malos de medio justorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 50, 'et mittent eos in caminum ignis: ibi erit fletus, et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 51, 'Intellexistis hæc omnia? Dicunt ei: Etiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 52, 'Ait illis: Ideo omnis scriba doctus in regno cælorum, similis est homini patrifamilias, qui profert de thesauro suo nova et vetera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 53, 'Et factum est, cum consummasset Jesus parabolas istas, transiit inde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 54, 'Et veniens in patriam suam, docebat eos in synagogis eorum, ita ut mirarentur, et dicerent: Unde huic sapientia hæc, et virtutes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 55, 'Nonne hic est fabri filius? nonne mater ejus dicitur Maria, et fratres ejus, Jacobus, et Joseph, et Simon, et Judas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 56, 'et sorores ejus, nonne omnes apud nos sunt? unde ergo huic omnia ista?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 57, 'Et scandalizabantur in eo. Jesus autem dixit eis: Non est propheta sine honore, nisi in patria sua, et in domo sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 58, 'Et non fecit ibi virtutes multas propter incredulitatem illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 1, 'In illo tempore audivit Herodes tetrarcha famam Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 2, 'et ait pueris suis: Hic est Joannes Baptista: ipse surrexit a mortuis, et ideo virtutes operantur in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 3, 'Herodes enim tenuit Joannem, et alligavit eum: et posuit in carcerem propter Herodiadem uxorem fratris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 4, 'Dicebat enim illi Joannes: Non licet tibi habere eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 5, 'Et volens illum occidere, timuit populum: quia sicut prophetam eum habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 6, 'Die autem natalis Herodis saltavit filia Herodiadis in medio, et placuit Herodi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 7, 'unde cum juramento pollicitus est ei dare quodcumque postulasset ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 8, 'At illa præmonita a matre sua: Da mihi, inquit, hic in disco caput Joannis Baptistæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 9, 'Et contristatus est rex: propter juramentum autem, et eos qui pariter recumbebant, jussit dari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 10, 'Misitque et decollavit Joannem in carcere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 11, 'Et allatum est caput ejus in disco, et datum est puellæ, et attulit matri suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 12, 'Et accedentes discipuli ejus, tulerunt corpus ejus, et sepelierunt illud: et venientes nuntiaverunt Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 13, 'Quod cum audisset Jesus, secessit inde in navicula, in locum desertum seorsum: et cum audissent turbæ, secutæ sunt eum pedestres de civitatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 14, 'Et exiens vidit turbam multam, et misertus est eis, et curavit languidos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 15, 'Vespere autem facto, accesserunt ad eum discipuli ejus, dicentes: Desertus est locus, et hora jam præteriit: dimitte turbas, ut euntes in castella, emant sibi escas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 16, 'Jesus autem dixit eis: Non habent necesse ire: date illis vos manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 17, 'Responderunt ei: Non habemus hic nisi quinque panes et duos pisces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 18, 'Qui ait eis: Afferte mihi illos huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 19, 'Et cum jussisset turbam discumbere super fœnum, acceptis quinque panibus et duobus piscibus, aspiciens in cælum benedixit, et fregit, et dedit discipulis panes, discipuli autem turbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 20, 'Et manducaverunt omnes, et saturati sunt. Et tulerunt reliquias, duodecim cophinos fragmentorum plenos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 21, 'Manducantium autem fuit numerus quinque millia virorum, exceptis mulieribus et parvulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 22, 'Et statim compulit Jesus discipulos ascendere in naviculam, et præcedere eum trans fretum, donec dimitteret turbas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 23, 'Et dimissa turba, ascendit in montem solus orare. Vespere autem facto solus erat ibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 24, 'navicula autem in medio mari jactabatur fluctibus: erat enim contrarius ventus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 25, 'Quarta enim vigilia noctis, venit ad eos ambulans super mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 26, 'Et videntes eum super mare ambulantem, turbati sunt, dicentes: Quia phantasma est. Et præ timore clamaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 27, 'Statimque Jesus locutus est eis, dicens: Habete fiduciam: ego sum, nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 28, 'Respondens autem Petrus, dixit: Domine, si tu es, jube me ad te venire super aquas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 29, 'At ipse ait: Veni. Et descendens Petrus de navicula, ambulabat super aquam ut veniret ad Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 30, 'Videns vero ventum validum, timuit: et cum cœpisset mergi, clamavit dicens: Domine, salvum me fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 31, 'Et continuo Jesus extendens manum, apprehendit eum: et ait illi: Modicæ fidei, quare dubitasti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 32, 'Et cum ascendissent in naviculam, cessavit ventus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 33, 'Qui autem in navicula erant, venerunt, et adoraverunt eum, dicentes: Vere Filius Dei es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 34, 'Et cum transfretassent, venerunt in terram Genesar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 35, 'Et cum cognovissent eum viri loci illius, miserunt in universam regionem illam, et obtulerunt ei omnes male habentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 14, 36, 'et rogabant eum ut vel fimbriam vestimenti ejus tangerent. Et quicumque tetigerunt, salvi facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 1, 'Tunc accesserunt ad eum ab Jerosolymis scribæ et pharisæi, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 2, 'Quare discipuli tui transgrediuntur traditionem seniorum? non enim lavant manus suas cum panem manducant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 3, 'Ipse autem respondens ait illis: Quare et vos transgredimini mandatum Dei propter traditionem vestram? Nam Deus dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 4, 'Honora patrem, et matrem: et, Qui maledixerit patri, vel matri, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 5, 'Vos autem dicitis: Quicumque dixerit patri, vel matri: Munus, quodcumque est ex me, tibi proderit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 6, 'et non honorificabit patrem suum, aut matrem suam: et irritum fecistis mandatum Dei propter traditionem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 7, 'Hypocritæ, bene prophetavit de vobis Isaias, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 8, 'Populus hic labiis me honorat: cor autem eorum longe est a me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 9, 'Sine causa autem colunt me, docentes doctrinas et mandata hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 10, 'Et convocatis ad se turbis, dixit eis: Audite, et intelligite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 11, 'Non quod intrat in os, coinquinat hominem: sed quod procedit ex ore, hoc coinquinat hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 12, 'Tunc accedentes discipuli ejus, dixerunt ei: Scis quia pharisæi audito verbo hoc, scandalizati sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 13, 'At ille respondens ait: Omnis plantatio, quam non plantavit Pater meus cælestis, eradicabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 14, 'Sinite illos: cæci sunt, et duces cæcorum; cæcus autem si cæco ducatum præstet, ambo in foveam cadunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 15, 'Respondens autem Petrus dixit ei: Edissere nobis parabolam istam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 16, 'At ille dixit: Adhuc et vos sine intellectu estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 17, 'Non intelligitis quia omne quod in os intrat, in ventrem vadit, et in secessum emittitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 18, 'Quæ autem procedunt de ore, de corde exeunt, et ea coinquinant hominem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 19, 'de corde enim exeunt cogitationes malæ, homicidia, adulteria, fornicationes, furta, falsa testimonia, blasphemiæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 20, 'hæc sunt, quæ coinquinant hominem. Non lotis autem manibus manducare, non coinquinat hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 21, 'Et egressus inde Jesus secessit in partes Tyri et Sidonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 22, 'Et ecce mulier chananæa a finibus illis egressa clamavit, dicens ei: Miserere mei, Domine fili David: filia mea male a dæmonio vexatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 23, 'Qui non respondit ei verbum. Et accedentes discipuli ejus rogabant eum dicentes: Dimitte eam: quia clamat post nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 24, 'Ipse autem respondens ait: Non sum missus nisi ad oves, quæ perierunt domus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 25, 'At illa venit, et adoravit eum, dicens: Domine, adjuva me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 26, 'Qui respondens ait: Non est bonum sumere panem filiorum, et mittere canibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 27, 'At illa dixit: Etiam Domine: nam et catelli edunt de micis quæ cadunt de mensa dominorum suorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 28, 'Tunc respondens Jesus, ait illi: O mulier, magna est fides tua: fiat tibi sicut vis. Et sanata est filia ejus ex illa hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 29, 'Et cum transisset inde Jesus, venit secus mare Galilææ: et ascendens in montem, sedebat ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 30, 'Et accesserunt ad eum turbæ multæ, habentes secum mutos, cæcos, claudos, debiles, et alios multos: et projecerunt eos ad pedes ejus, et curavit eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 31, 'ita ut turbæ mirarentur, videntes mutos loquentes, claudos ambulantes, cæcos videntes: et magnificabant Deum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 32, 'Jesus autem, convocatis discipulis suis, dixit: Misereor turbæ, quia triduo jam perseverant mecum, et non habent quod manducent: et dimittere eos jejunos nolo, ne deficiant in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 33, 'Et dicunt ei discipuli: Unde ergo nobis in deserto panes tantos, ut saturemus turbam tantam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 34, 'Et ait illis Jesus: Quot habetis panes? At illi dixerunt: Septem, et paucos pisciculos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 35, 'Et præcepit turbæ ut discumberent super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 36, 'Et accipiens septem panes, et pisces, et gratias agens, fregit, et dedit discipulis suis, et discipuli dederunt populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 37, 'Et comederunt omnes, et saturati sunt. Et quod superfuit de fragmentis, tulerunt septem sportas plenas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 38, 'Erant autem qui manducaverunt quatuor millia hominum, extra parvulos et mulieres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 15, 39, 'Et, dimissa turba, ascendit in naviculam: et venit in fines Magedan.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 1, 'Et accesserunt ad eum pharisæi et sadducæi tentantes: et rogaverunt eum ut signum de cælo ostenderet eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 2, 'At ille respondens, ait illis: Facto vespere dicitis: Serenum erit, rubicundum est enim cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 3, 'Et mane: Hodie tempestas, rutilat enim triste cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 4, 'Faciem ergo cæli dijudicare nostis: signa autem temporum non potestis scire? Generatio mala et adultera signum quærit: et signum non dabitur ei, nisi signum Jonæ prophetæ. Et relictis illis, abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 5, 'Et cum venissent discipuli ejus trans fretum, obliti sunt panes accipere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 6, 'Qui dixit illis: Intuemini, et cavete a fermento pharisæorum et sadducæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 7, 'At illi cogitabant intra se dicentes: Quia panes non accepimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 8, 'Sciens autem Jesus, dixit: Quid cogitatis intra vos modicæ fidei, quia panes non habetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 9, 'Nondum intelligitis, neque recordamini quinque panum in quinque millia hominum, et quot cophinos sumpsistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 10, 'neque septem panum in quatuor millia hominum, et quot sportas sumpsistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 11, 'Quare non intelligitis, quia non de pane dixi vobis: Cavete a fermento pharisæorum et sadducæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 12, 'Tunc intellexerunt quia non dixerit cavendum a fermento panum, sed a doctrina pharisæorum et sadducæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 13, 'Venit autem Jesus in partes Cæsareæ Philippi: et interrogabat discipulos suos, dicens: Quem dicunt homines esse Filium hominis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 14, 'At illi dixerunt: Alii Joannem Baptistam, alii autem Eliam, alii vero Jeremiam, aut unum ex prophetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 15, 'Dicit illis Jesus: Vos autem, quem me esse dicitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 16, 'Respondens Simon Petrus dixit: Tu es Christus, Filius Dei vivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 17, 'Respondens autem Jesus, dixit ei: Beatus es Simon Bar Jona: quia caro et sanguis non revelavit tibi, sed Pater meus, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 18, 'Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificabo Ecclesiam meam, et portæ inferi non prævalebunt adversus eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 19, 'Et tibi dabo claves regni cælorum. Et quodcumque ligaveris super terram, erit ligatum et in cælis: et quodcumque solveris super terram, erit solutum et in cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 20, 'Tunc præcepit discipulis suis ut nemini dicerent quia ipse esset Jesus Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 21, 'Exinde cœpit Jesus ostendere discipulis suis, quia oporteret eum ire Jerosolymam, et multa pati a senioribus, et scribis, et principibus sacerdotum, et occidi, et tertia die resurgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 22, 'Et assumens eum Petrus, cœpit increpare illum dicens: Absit a te, Domine: non erit tibi hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 23, 'Qui conversus, dixit Petro: Vade post me Satana, scandalum es mihi: quia non sapis ea quæ Dei sunt, sed ea quæ hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 24, 'Tunc Jesus dixit discipulis suis: Si quis vult post me venire, abneget semetipsum, et tollat crucem suam, et sequatur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 25, 'Qui enim voluerit animam suam salvam facere, perdet eam: qui autem perdiderit animam suam propter me, inveniet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 26, 'Quid enim prodest homini, si mundum universum lucretur, animæ vero suæ detrimentum patiatur? aut quam dabit homo commutationem pro anima sua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 27, 'Filius enim hominis venturus est in gloria Patris sui cum angelis suis: et tunc reddet unicuique secundum opera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 16, 28, 'Amen dico vobis, sunt quidam de hic stantibus, qui non gustabunt mortem, donec videant Filium hominis venientem in regno suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 1, 'Et post dies sex assumit Jesus Petrum, et Jacobum, et Joannem fratrem ejus, et ducit illos in montem excelsum seorsum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 2, 'et transfiguratus est ante eos. Et resplenduit facies ejus sicut sol: vestimenta autem ejus facta sunt alba sicut nix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 3, 'Et ecce apparuerunt illis Moyses et Elias cum eo loquentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 4, 'Respondens autem Petrus, dixit ad Jesum: Domine, bonum est nos hic esse: si vis, faciamus tria tabernacula, tibi unum, Moysi unum, et Eliæ unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 5, 'Adhuc eo loquente, ecce nubes lucida obumbravit eos. Et ecce vox de nube, dicens: Hic est Filius meus dilectus, in quo mihi bene complacui: ipsum audite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 6, 'Et audientes discipuli ceciderunt in faciem suam, et timuerunt valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 7, 'Et accessit Jesus, et tetigit eos: dixitque eis: Surgite, et nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 8, 'Levantes autem oculos suos, neminem viderunt, nisi solum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 9, 'Et descendentibus illis de monte, præcepit eis Jesus, dicens: Nemini dixeritis visionem, donec Filius hominis a mortuis resurgat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 10, 'Et interrogaverunt eum discipuli, dicentes: Quid ergo scribæ dicunt, quod Eliam oporteat primum venire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 11, 'At ille respondens, ait eis: Elias quidem venturus est, et restituet omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 12, 'Dico autem vobis, quia Elias jam venit, et non cognoverunt eum, sed fecerunt in eo quæcumque voluerunt. Sic et Filius hominis passurus est ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 13, 'Tunc intellexerunt discipuli, quia de Joanne Baptista dixisset eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 14, 'Et cum venisset ad turbam, accessit ad eum homo genibus provolutus ante eum, dicens: Domine, miserere filio meo, quia lunaticus est, et male patitur: nam sæpe cadit in ignem, et crebro in aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 15, 'Et obtuli eum discipulis tuis, et non potuerunt curare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 16, 'Respondens autem Jesus, ait: O generatio incredula, et perversa, quousque ero vobiscum? usquequo patiar vos? Afferte huc illum ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 17, 'Et increpavit illum Jesus, et exiit ab eo dæmonium, et curatus est puer ex illa hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 18, 'Tunc accesserunt discipuli ad Jesum secreto, et dixerunt: Quare nos non potuimus ejicere illum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 19, 'Dixit illis Jesus: Propter incredulitatem vestram. Amen quippe dico vobis, si habueritis fidem sicut granum sinapis, dicetis monti huic: Transi hinc illuc, et transibit, et nihil impossibile erit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 20, 'Hoc autem genus non ejicitur nisi per orationem et jejunium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 21, 'Conversantibus autem eis in Galilæa, dixit illis Jesus: Filius hominis tradendus est in manus hominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 22, 'et occident eum, et tertia die resurget. Et contristati sunt vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 23, 'Et cum venissent Capharnaum, accesserunt qui didrachma accipiebant ad Petrum, et dixerunt ei: Magister vester non solvit didrachma?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 24, 'Ait: Etiam. Et cum intrasset in domum, prævenit eum Jesus, dicens: Quid tibi videtur Simon? reges terræ a quibus accipiunt tributum vel censum? a filiis suis, an ab alienis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 25, 'Et ille dixit: Ab alienis. Dixit illi Jesus: Ergo liberi sunt filii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 17, 26, 'Ut autem non scandalizemus eos, vade ad mare, et mitte hamum: et eum piscem, qui primus ascenderit, tolle: et aperto ore ejus, invenies staterem: illum sumens, da eis pro me et te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 1, 'In illa hora accesserunt discipuli ad Jesum, dicentes: Quis, putas, major est in regno cælorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 2, 'Et advocans Jesus parvulum, statuit eum in medio eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 3, 'et dixit: Amen dico vobis, nisi conversi fueritis, et efficiamini sicut parvuli, non intrabitis in regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 4, 'Quicumque ergo humiliaverit se sicut parvulus iste, hic est major in regno cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 5, 'Et qui susceperit unum parvulum talem in nomine meo, me suscipit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 6, 'qui autem scandalizaverit unum de pusillis istis, qui in me credunt, expedit ei ut suspendatur mola asinaria in collo ejus, et demergatur in profundum maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 7, 'Væ mundo a scandalis! Necesse est enim ut veniant scandala: verumtamen væ homini illi, per quem scandalum venit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 8, 'Si autem manus tua, vel pes tuus scandalizat te, abscide eum, et projice abs te: bonum tibi est ad vitam ingredi debilem, vel claudum, quam duas manus vel duos pedes habentem mitti in ignem æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 9, 'Et si oculus tuus scandalizat te, erue eum, et projice abs te: bonum tibi est cum uno oculo in vitam intrare, quam duos oculos habentem mitti in gehennam ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 10, 'Videte ne contemnatis unum ex his pusillis: dico enim vobis, quia angeli eorum in cælis semper vident faciem Patris mei, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 11, 'Venit enim Filius hominis salvare quod perierat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 12, 'Quid vobis videtur? si fuerint alicui centum oves, et erravit una ex eis: nonne relinquit nonaginta novem in montibus, et vadit quærere eam quæ erravit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 13, 'Et si contigerit ut inveniat eam: amen dico vobis, quia gaudet super eam magis quam super nonaginta novem, quæ non erraverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 14, 'Sic non est voluntas ante Patrem vestrum, qui in cælis est, ut pereat unus de pusillis istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 15, 'Si autem peccaverit in te frater tuus, vade, et corripe eum inter te, et ipsum solum: si te audierit, lucratus eris fratrem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 16, 'Si autem te non audierit, adhibe tecum adhuc unum, vel duos, ut in ore duorum, vel trium testium stet omne verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 17, 'Quod si non audierit eos: dic ecclesiæ. Si autem ecclesiam non audierit, sit tibi sicut ethnicus et publicanus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 18, 'Amen dico vobis, quæcumque alligaveritis super terram, erunt ligata et in cælo: et quæcumque solveritis super terram, erunt soluta et in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 19, 'Iterum dico vobis, quia si duo ex vobis consenserint super terram, de omni re quamcumque petierint, fiet illis a Patre meo, qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 20, 'Ubi enim sunt duo vel tres congregati in nomine meo, ibi sum in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 21, 'Tunc accedens Petrus ad eum, dixit: Domine, quoties peccabit in me frater meus, et dimittam ei? usque septies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 22, 'Dicit illi Jesus: Non dico tibi usque septies: sed usque septuagies septies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 23, 'Ideo assimilatum est regnum cælorum homini regi, qui voluit rationem ponere cum servis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 24, 'Et cum cœpisset rationem ponere, oblatus est ei unus, qui debebat ei decem millia talenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 25, 'Cum autem non haberet unde redderet, jussit eum dominus ejus venundari, et uxorem ejus, et filios, et omnia quæ habebat, et reddi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 26, 'Procidens autem servus ille, orabat eum, dicens: Patientiam habe in me, et omnia reddam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 27, 'Misertus autem dominus servi illius, dimisit eum, et debitum dimisit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 28, 'Egressus autem servus ille invenit unum de conservis suis, qui debebat ei centum denarios: et tenens suffocavit eum, dicens: Redde quod debes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 29, 'Et procidens conservus ejus, rogabat eum, dicens: Patientiam habe in me, et omnia reddam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 30, 'Ille autem noluit: sed abiit, et misit eum in carcerem donec redderet debitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 31, 'Videntes autem conservi ejus quæ fiebant, contristati sunt valde: et venerunt, et narraverunt domino suo omnia quæ facta fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 32, 'Tunc vocavit illum dominus suus: et ait illi: Serve nequam, omne debitum dimisi tibi quoniam rogasti me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 33, 'nonne ergo oportuit et te misereri conservi tui, sicut et ego tui misertus sum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 34, 'Et iratus dominus ejus tradidit eum tortoribus, quoadusque redderet universum debitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 18, 35, 'Sic et Pater meus cælestis faciet vobis, si non remiseritis unusquisque fratri suo de cordibus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 1, 'Et factum est, cum consummasset Jesus sermones istos, migravit a Galilæa, et venit in fines Judææ trans Jordanem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 2, 'et secutæ sunt eum turbæ multæ, et curavit eos ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 3, 'Et accesserunt ad eum pharisæi tentantes eum, et dicentes: Si licet homini dimittere uxorem suam, quacumque ex causa?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 4, 'Qui respondens, ait eis: Non legistis, quia qui fecit hominem ab initio, masculum et feminam fecit eos? Et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 5, 'Propter hoc dimittet homo patrem, et matrem, et adhærebit uxori suæ, et erunt duo in carne una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 6, 'Itaque jam non sunt duo, sed una caro. Quod ergo Deus conjunxit, homo non separet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 7, 'Dicunt illi: Quid ergo Moyses mandavit dare libellum repudii, et dimittere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 8, 'Ait illis: Quoniam Moyses ad duritiam cordis vestri permisit vobis dimittere uxores vestras: ab initio autem non fuit sic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 9, 'Dico autem vobis, quia quicumque dimiserit uxorem suam, nisi ob fornicationem, et aliam duxerit, mœchatur: et qui dimissam duxerit, mœchatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 10, 'Dicunt ei discipuli ejus: Si ita est causa hominis cum uxore, non expedit nubere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 11, 'Qui dixit illis: Non omnes capiunt verbum istud, sed quibus datum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 12, 'Sunt enim eunuchi, qui de matris utero sic nati sunt: et sunt eunuchi, qui facti sunt ab hominibus: et sunt eunuchi, qui seipsos castraverunt propter regnum cælorum. Qui potest capere capiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 13, 'Tunc oblati sunt ei parvuli, ut manus eis imponeret, et oraret. Discipuli autem increpabant eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 14, 'Jesus vero ait eis: Sinite parvulos, et nolite eos prohibere ad me venire: talium est enim regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 15, 'Et cum imposuisset eis manus, abiit inde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 16, 'Et ecce unus accedens, ait illi: Magister bone, quid boni faciam ut habeam vitam æternam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 17, 'Qui dixit ei: Quid me interrogas de bono? Unus est bonus, Deus. Si autem vis ad vitam ingredi, serva mandata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 18, 'Dicit illi: Quæ? Jesus autem dixit: Non homicidium facies; non adulterabis; non facies furtum; non falsum testimonium dices;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 19, 'honora patrem tuum, et matrem tuam, et diliges proximum tuum sicut teipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 20, 'Dicit illi adolescens: Omnia hæc custodivi a juventute mea: quid adhuc mihi deest?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 21, 'Ait illi Jesus: Si vis perfectus esse, vade, vende quæ habes, et da pauperibus, et habebis thesaurum in cælo: et veni, sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 22, 'Cum audisset autem adolescens verbum, abiit tristis: erat enim habens multas possessiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 23, 'Jesus autem dixit discipulis suis: Amen dico vobis, quia dives difficile intrabit in regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 24, 'Et iterum dico vobis: Facilius est camelum per foramen acus transire, quam divitem intrare in regnum cælorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 25, 'Auditis autem his, discipuli mirabantur valde, dicentes: Quis ergo poterit salvus esse?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 26, 'Aspiciens autem Jesus, dixit illis: Apud homines hoc impossibile est: apud Deum autem omnia possibilia sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 27, 'Tunc respondens Petrus, dixit ei: Ecce nos reliquimus omnia, et secuti sumus te: quid ergo erit nobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 28, 'Jesus autem dixit illis: Amen dico vobis, quod vos, qui secuti estis me, in regeneratione cum sederit Filius hominis in sede majestatis suæ, sedebitis et vos super sedes duodecim, judicantes duodecim tribus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 29, 'Et omnis qui reliquerit domum, vel fratres, aut sorores, aut patrem, aut matrem, aut uxorem, aut filios, aut agros propter nomen meum, centuplum accipiet, et vitam æternam possidebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 19, 30, 'Multi autem erunt primi novissimi, et novissimi primi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 1, 'Simile est regnum cælorum homini patrifamilias, qui exiit primo mane conducere operarios in vineam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 2, 'Conventione autem facta cum operariis ex denario diurno, misit eos in vineam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 3, 'Et egressus circa horam tertiam, vidit alios stantes in foro otiosos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 4, 'et dixit illis: Ite et vos in vineam meam, et quod justum fuerit dabo vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 5, 'Illi autem abierunt. Iterum autem exiit circa sextam et nonam horam: et fecit similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 6, 'Circa undecimam vero exiit, et invenit alios stantes, et dicit illis: Quid hic statis tota die otiosi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 7, 'Dicunt ei: Quia nemo nos conduxit. Dicit illis: Ite et vos in vineam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 8, 'Cum sero autem factum esset, dicit dominus vineæ procuratori suo: Voca operarios, et redde illis mercedem incipiens a novissimis usque ad primos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 9, 'Cum venissent ergo qui circa undecimam horam venerant, acceperunt singulos denarios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 10, 'Venientes autem et primi, arbitrati sunt quod plus essent accepturi: acceperunt autem et ipsi singulos denarios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 11, 'Et accipientes murmurabant adversus patremfamilias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 12, 'dicentes: Hi novissimi una hora fecerunt, et pares illos nobis fecisti, qui portavimus pondus diei, et æstus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 13, 'At ille respondens uni eorum, dixit: Amice, non facio tibi injuriam: nonne ex denario convenisti mecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 14, 'Tolle quod tuum est, et vade: volo autem et huic novissimo dare sicut et tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 15, 'Aut non licet mihi quod volo, facere? an oculus tuus nequam est, quia ego bonus sum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 16, 'Sic erunt novissimi primi, et primi novissimi. Multi enim sunt vocati, pauci vero electi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 17, 'Et ascendens Jesus Jerosolymam, assumpsit duodecim discipulos secreto, et ait illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 18, 'Ecce ascendimus Jerosolymam, et Filius hominis tradetur principibus sacerdotum, et scribis, et condemnabunt eum morte,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 19, 'et tradent eum gentibus ad illudendum, et flagellandum, et crucifigendum, et tertia die resurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 20, 'Tunc accessit ad eum mater filiorum Zebedæi cum filiis suis, adorans et petens aliquid ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 21, 'Qui dixit ei: Quid vis? Ait illi: Dic ut sedeant hi duo filii mei, unus ad dexteram tuam, et unus ad sinistram in regno tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 22, 'Respondens autem Jesus, dixit: Nescitis quid petatis. Potestis bibere calicem, quem ego bibiturus sum? Dicunt ei: Possumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 23, 'Ait illis: Calicem quidem meum bibetis: sedere autem ad dexteram meam vel sinistram non est meum dare vobis, sed quibus paratum est a Patre meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 24, 'Et audientes decem, indignati sunt de duobus fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 25, 'Jesus autem vocavit eos ad se, et ait: Scitis quia principes gentium dominantur eorum: et qui majores sunt, potestatem exercent in eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 26, 'Non ita erit inter vos: sed quicumque voluerit inter vos major fieri, sit vester minister:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 27, 'et qui voluerit inter vos primus esse, erit vester servus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 28, 'Sicut Filius hominis non venit ministrari, sed ministrare, et dare animam suam redemptionem pro multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 29, 'Et egredientibus illis ab Jericho, secuta est eum turba multa,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 30, 'et ecce duo cæci sedentes secus viam audierunt quia Jesus transiret: et clamaverunt, dicentes: Domine, miserere nostri, fili David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 31, 'Turba autem increpabat eos ut tacerent. At illi magis clamabant, dicentes: Domine, miserere nostri, fili David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 32, 'Et stetit Jesus, et vocavit eos, et ait: Quid vultis ut faciam vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 33, 'Dicunt illi: Domine, ut aperiantur oculi nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 20, 34, 'Misertus autem eorum Jesus, tetigit oculos eorum. Et confestim viderunt, et secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 1, 'Et cum appropinquassent Jerosolymis, et venissent Bethphage ad montem Oliveti: tunc Jesus misit duos discipulos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 2, 'dicens eis: Ite in castellum, quod contra vos est, et statim invenietis asinam alligatam, et pullum cum ea: solvite, et adducite mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 3, 'et si quis vobis aliquid dixerit, dicite quia Dominus his opus habet: et confestim dimittet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 4, 'Hoc autem totum factum est, ut adimpleretur quod dictum est per prophetam dicentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 5, 'Dicite filiæ Sion: Ecce rex tuus venit tibi mansuetus, sedens super asinam, et pullum filium subjugalis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 6, 'Euntes autem discipuli fecerunt sicut præcepit illis Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 7, 'Et adduxerunt asinam, et pullum: et imposuerunt super eos vestimenta sua, et eum desuper sedere fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 8, 'Plurima autem turba straverunt vestimenta sua in via: alii autem cædebant ramos de arboribus, et sternebant in via:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 9, 'turbæ autem, quæ præcedebant, et quæ sequebantur, clamabant, dicentes: Hosanna filio David: benedictus, qui venit in nomine Domini: hosanna in altissimis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 10, 'Et cum intrasset Jerosolymam, commota est universa civitas, dicens: Quis est hic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 11, 'Populi autem dicebant: Hic est Jesus propheta a Nazareth Galilææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 12, 'Et intravit Jesus in templum Dei, et ejiciebat omnes vendentes et ementes in templo, et mensas numulariorum, et cathedras vendentium columbas evertit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 13, 'et dicit eis: Scriptum est: Domus mea domus orationis vocabitur: vos autem fecistis illam speluncam latronum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 14, 'Et accesserunt ad eum cæci, et claudi in templo: et sanavit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 15, 'Videntes autem principes sacerdotum et scribæ mirabilia quæ fecit, et pueros clamantes in templo, et dicentes: Hosanna filio David: indignati sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 16, 'et dixerunt ei: Audis quid isti dicunt? Jesus autem dixit eis: Utique. Numquam legistis: Quia ex ore infantium et lactentium perfecisti laudem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 17, 'Et relictis illis, abiit foras extra civitatem in Bethaniam: ibique mansit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 18, 'Mane autem revertens in civitatem, esuriit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 19, 'Et videns fici arborem unam secus viam, venit ad eam: et nihil invenit in ea nisi folia tantum, et ait illi: Numquam ex te fructus nascatur in sempiternum. Et arefacta est continuo ficulnea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 20, 'Et videntes discipuli, mirati sunt, dicentes: Quomodo continuo aruit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 21, 'Respondens autem Jesus, ait eis: Amen dico vobis, si habueritis fidem, et non hæsitaveritis, non solum de ficulnea facietis, sed et si monti huic dixeritis: Tolle, et jacta te in mare, fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 22, 'Et omnia quæcumque petieritis in oratione credentes, accipietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 23, 'Et cum venisset in templum, accesserunt ad eum docentem principes sacerdotum, et seniores populi, dicentes: In qua potestate hæc facis? et quis tibi dedit hanc potestatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 24, 'Respondens Jesus dixit eis: Interrogabo vos et ego unum sermonem: quem si dixeritis mihi, et ego vobis dicam in qua potestate hæc facio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 25, 'Baptismus Joannis unde erat? e cælo, an ex hominibus? At illi cogitabant inter se, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 26, 'Si dixerimus, e cælo, dicet nobis: Quare ergo non credidistis illi? Si autem dixerimus, ex hominibus, timemus turbam: omnes enim habebant Joannem sicut prophetam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 27, 'Et respondentes Jesu, dixerunt: Nescimus. Ait illis et ipse: Nec ego dico vobis in qua potestate hæc facio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 28, 'Quid autem vobis videtur? Homo quidam habebat duos filios, et accedens ad primum, dixit: Fili, vade hodie, operare in vinea mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 29, 'Ille autem respondens, ait: Nolo. Postea autem, pœnitentia motus, abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 30, 'Accedens autem ad alterum, dixit similiter. At ille respondens, ait: Eo, domine, et non ivit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 31, 'quis ex duobus fecit voluntatem patris? Dicunt ei: Primus. Dicit illis Jesus: Amen dico vobis, quia publicani et meretrices præcedent vos in regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 32, 'Venit enim ad vos Joannes in via justitiæ, et non credidistis ei: publicani autem et meretrices crediderunt ei: vos autem videntes nec pœnitentiam habuistis postea, ut crederetis ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 33, 'Aliam parabolam audite: Homo erat paterfamilias, qui plantavit vineam, et sepem circumdedit ei, et fodit in ea torcular, et ædificavit turrim, et locavit eam agricolis, et peregre profectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 34, 'Cum autem tempus fructuum appropinquasset, misit servos suos ad agricolas, ut acciperent fructus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 35, 'Et agricolæ, apprehensis servis ejus, alium ceciderunt, alium occiderunt, alium vero lapidaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 36, 'Iterum misit alios servos plures prioribus, et fecerunt illis similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 37, 'Novissime autem misit ad eos filium suum, dicens: Verebuntur filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 38, 'Agricolæ autem videntes filium dixerunt intra se: Hic est hæres, venite, occidamus eum, et habebimus hæreditatem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 39, 'Et apprehensum eum ejecerunt extra vineam, et occiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 40, 'Cum ergo venerit dominus vineæ, quid faciet agricolis illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 41, 'Aiunt illi: Malos male perdet: et vineam suam locabit aliis agricolis, qui reddant ei fructum temporibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 42, 'Dicit illis Jesus: Numquam legistis in Scripturis: Lapidem quem reprobaverunt ædificantes, hic factus est in caput anguli: a Domino factum est istud, et est mirabile in oculis nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 43, 'Ideo dico vobis, quia auferetur a vobis regnum Dei, et dabitur genti facienti fructus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 44, 'Et qui ceciderit super lapidem istum, confringetur: super quem vero ceciderit, conteret eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 45, 'Et cum audissent principes sacerdotum et pharisæi parabolas ejus, cognoverunt quod de ipsis diceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 21, 46, 'Et quærentes eum tenere, timuerunt turbas: quoniam sicut prophetam eum habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 1, 'Et respondens Jesus, dixit iterum in parabolis eis, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 2, 'Simile factum est regnum cælorum homini regi, qui fecit nuptias filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 3, 'Et misit servos suos vocare invitatos ad nuptias, et nolebant venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 4, 'Iterum misit alios servos, dicens: Dicite invitatis: Ecce prandium meum paravi, tauri mei et altilia occisa sunt, et omnia parata: venite ad nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 5, 'Illi autem neglexerunt: et abierunt, alius in villam suam, alius vero ad negotiationem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 6, 'reliqui vero tenuerunt servos ejus, et contumeliis affectos occiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 7, 'Rex autem cum audisset, iratus est: et missis exercitibus suis, perdidit homicidas illos, et civitatem illorum succendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 8, 'Tunc ait servis suis: Nuptiæ quidem paratæ sunt, sed qui invitati erant, non fuerunt digni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 9, 'ite ergo ad exitus viarum, et quoscumque inveneritis, vocate ad nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 10, 'Et egressi servi ejus in vias, congregaverunt omnes quos invenerunt, malos et bonos: et impletæ sunt nuptiæ discumbentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 11, 'Intravit autem rex ut videret discumbentes, et vidit ibi hominem non vestitum veste nuptiali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 12, 'Et ait illi: Amice, quomodo huc intrasti non habens vestem nuptialem? At ille obmutuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 13, 'Tunc dicit rex ministris: Ligatis manibus et pedibus ejus, mittite eum in tenebras exteriores: ibi erit fletus et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 14, 'Multi enim sunt vocati, pauci vero electi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 15, 'Tunc abeuntes pharisæi, consilium inierunt ut caperent eum in sermone.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 16, 'Et mittunt ei discipulos suos cum Herodianis, dicentes: Magister, scimus quia verax es, et viam Dei in veritate doces, et non est tibi cura de aliquo: non enim respicis personam hominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 17, 'dic ergo nobis quid tibi videtur, licet censum dare Cæsari, an non?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 18, 'Cognita autem Jesus nequitia eorum, ait: Quid me tentatis, hypocritæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 19, 'ostendite mihi numisma census. At illi obtulerunt ei denarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 20, 'Et ait illis Jesus: Cujus est imago hæc, et superscriptio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 21, 'Dicunt ei: Cæsaris. Tunc ait illis: Reddite ergo quæ sunt Cæsaris, Cæsari: et quæ sunt Dei, Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 22, 'Et audientes mirati sunt, et relicto eo abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 23, 'In illo die accesserunt ad eum sadducæi, qui dicunt non esse resurrectionem: et interrogaverunt eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 24, 'dicentes: Magister, Moyses dixit: Si quis mortuus fuerit non habens filium, ut ducat frater ejus uxorem illius, et suscitet semen fratri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 25, 'Erant autem apud nos septem fratres: et primus, uxore ducta, defunctus est: et non habens semen, reliquit uxorem suam fratri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 26, 'Similiter secundus, et tertius usque ad septimum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 27, 'Novissime autem omnium et mulier defuncta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 28, 'In resurrectione ergo cujus erit de septem uxor? omnes enim habuerunt eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 29, 'Respondens autem Jesus, ait illis: Erratis nescientes Scripturas, neque virtutem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 30, 'In resurrectione enim neque nubent, neque nubentur: sed erunt sicut angeli Dei in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 31, 'De resurrectione autem mortuorum non legistis quod dictum est a Deo dicente vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 32, 'Ego sum Deus Abraham, et Deus Isaac, et Deus Jacob? Non est Deus mortuorum, sed viventium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 33, 'Et audientes turbæ, mirabantur in doctrina ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 34, 'Pharisæi autem audientes quod silentium imposuisset sadducæis, convenerunt in unum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 35, 'et interrogavit eum unus ex eis legis doctor, tentans eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 36, 'Magister, quod est mandatum magnum in lege?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 37, 'Ait illi Jesus: Diliges Dominum Deum tuum ex toto corde tuo, et in tota anima tua, et in tota mente tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 38, 'Hoc est maximum, et primum mandatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 39, 'Secundum autem simile est huic: Diliges proximum tuum, sicut teipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 40, 'In his duobus mandatis universa lex pendet, et prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 41, 'Congregatis autem pharisæis, interrogavit eos Jesus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 42, 'dicens: Quid vobis videtur de Christo? cujus filius est? Dicunt ei: David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 43, 'Ait illis: Quomodo ergo David in spiritu vocat eum Dominum, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 44, 'Dixit Dominus Domino meo: Sede a dextris meis, donec ponam inimicos tuos scabellum pedum tuorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 45, 'Si ergo David vocat eum Dominum, quomodo filius ejus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 22, 46, 'Et nemo poterat ei respondere verbum: neque ausus fuit quisquam ex illa die eum amplius interrogare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 1, 'Tunc Jesus locutus est ad turbas, et ad discipulos suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 2, 'dicens: Super cathedram Moysi sederunt scribæ et pharisæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 3, 'Omnia ergo quæcumque dixerint vobis, servate, et facite: secundum opera vero eorum nolite facere: dicunt enim, et non faciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 4, 'Alligant enim onera gravia, et importabilia, et imponunt in humeros hominum: digito autem suo nolunt ea movere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 5, 'Omnia vero opera sua faciunt ut videantur ab hominibus: dilatant enim phylacteria sua, et magnificant fimbrias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 6, 'Amant autem primos recubitus in cœnis, et primas cathedras in synagogis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 7, 'et salutationes in foro, et vocari ab hominibus Rabbi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 8, 'Vos autem nolite vocari Rabbi: unus est enim magister vester, omnes autem vos fratres estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 9, 'Et patrem nolite vocare vobis super terram: unus est enim pater vester qui in cælis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 10, 'Nec vocemini magistri: quia magister vester unus est, Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 11, 'Qui major est vestrum, erit minister vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 12, 'Qui autem se exaltaverit, humiliabitur: et qui se humiliaverit, exaltabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 13, 'Væ autem vobis scribæ et pharisæi hypocritæ, quia clauditis regnum cælorum ante homines! vos enim non intratis, nec introëuntes sinitis intrare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 14, 'Væ vobis scribæ et pharisæi hypocritæ, quia comeditis domos viduarum, orationes longas orantes! propter hoc amplius accipietis judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 15, 'Væ vobis scribæ et pharisæi hypocritæ, quia circuitis mare, et aridam, ut faciatis unum proselytum, et cum fuerit factus, facitis eum filium gehennæ duplo quam vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 16, 'Væ vobis duces cæci, qui dicitis: Quicumque juraverit per templum, nihil est: qui autem juraverit in auro templi, debet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 17, 'Stulti et cæci: quid enim majus est? aurum, an templum, quod sanctificat aurum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 18, 'Et quicumque juraverit in altari, nihil est: quicumque autem juraverit in dono, quod est super illud, debet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 19, 'Cæci: quid enim majus est, donum, an altare, quod sanctificat donum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 20, 'Qui ergo jurat in altari, jurat in eo, et in omnibus quæ super illud sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 21, 'Et quicumque juraverit in templo, jurat in illo, et in eo qui habitat in ipso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 22, 'et qui jurat in cælo, jurat in throno Dei, et in eo qui sedet super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 23, 'Væ vobis scribæ et pharisæi hypocritæ, qui decimatis mentham, et anethum, et cyminum, et reliquistis quæ graviora sunt legis, judicium, et misericordiam, et fidem! hæc oportuit facere, et illa non omittere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 24, 'Duces cæci, excolantes culicem, camelum autem glutientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 25, 'Væ vobis scribæ et pharisæi hypocritæ, quia mundatis quod deforis est calicis et paropsidis; intus autem pleni estis rapina et immunditia!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 26, 'Pharisæe cæce, munda prius quod intus est calicis, et paropsidis, ut fiat id, quod deforis est, mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 27, 'Væ vobis scribæ et pharisæi hypocritæ, quia similes estis sepulchris dealbatis, quæ a foris parent hominibus speciosa, intus vero pleni sunt ossibus mortuorum, et omni spurcitia!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 28, 'Sic et vos a foris quidem paretis hominibus justi: intus autem pleni estis hypocrisi et iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 29, 'Væ vobis scribæ et pharisæi hypocritæ, qui ædificatis sepulchra prophetarum, et ornatis monumenta justorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 30, 'et dicitis: Si fuissemus in diebus patrum nostrorum, non essemus socii eorum in sanguine prophetarum!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 31, 'itaque testimonio estis vobismetipsis, quia filii estis eorum, qui prophetas occiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 32, 'Et vos implete mensuram patrum vestrorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 33, 'Serpentes, genimina viperarum, quomodo fugietis a judicio gehennæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 34, 'Ideo ecce ego mitto ad vos prophetas, et sapientes, et scribas, et ex illis occidetis, et crucifigetis, et ex eis flagellabitis in synagogis vestris, et persequemini de civitate in civitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 35, 'ut veniat super vos omnis sanguis justus, qui effusus est super terram, a sanguine Abel justi usque ad sanguinem Zachariæ, filii Barachiæ, quem occidistis inter templum et altare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 36, 'Amen dico vobis, venient hæc omnia super generationem istam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 37, 'Jerusalem, Jerusalem, quæ occidis prophetas, et lapidas eos, qui ad te missi sunt, quoties volui congregare filios tuos, quemadmodum gallina congregat pullos suos sub alas, et noluisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 38, 'Ecce relinquetur vobis domus vestra deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 23, 39, 'Dico enim vobis, non me videbitis amodo, donec dicatis: Benedictus, qui venit in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 1, 'Et egressus Jesus de templo, ibat. Et accesserunt discipuli ejus, ut ostenderent ei ædificationes templi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 2, 'Ipse autem respondens dixit illis: Videtis hæc omnia? amen dico vobis, non relinquetur hic lapis super lapidem, qui non destruatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 3, 'Sedente autem eo super montem Oliveti, accesserunt ad eum discipuli secreto, dicentes: Dic nobis, quando hæc erunt? et quod signum adventus tui, et consummationis sæculi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 4, 'Et respondens Jesus, dixit eis: Videte ne quis vos seducat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 5, 'multi enim venient in nomine meo, dicentes: Ego sum Christus: et multos seducent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 6, 'Audituri enim estis prælia, et opiniones præliorum. Videte ne turbemini: oportet enim hæc fieri, sed nondum est finis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 7, 'consurget enim gens in gentem, et regnum in regnum, et erunt pestilentiæ, et fames, et terræmotus per loca:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 8, 'hæc autem omnia initia sunt dolorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 9, 'Tunc tradent vos in tribulationem, et occident vos: et eritis odio omnibus gentibus propter nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 10, 'Et tunc scandalizabuntur multi, et invicem tradent, et odio habebunt invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 11, 'Et multi pseudoprophetæ surgent, et seducent multos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 12, 'Et quoniam abundavit iniquitas, refrigescet caritas multorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 13, 'qui autem perseveraverit usque in finem, hic salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 14, 'Et prædicabitur hoc Evangelium regni in universo orbe, in testimonium omnibus gentibus: et tunc veniet consummatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 15, 'Cum ergo videritis abominationem desolationis, quæ dicta est a Daniele propheta, stantem in loco sancto, qui legit, intelligat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 16, 'tunc qui in Judæa sunt, fugiant ad montes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 17, 'et qui in tecto, non descendat tollere aliquid de domo sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 18, 'et qui in agro, non revertatur tollere tunicam suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 19, 'Væ autem prægnantibus et nutrientibus in illis diebus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 20, 'Orate autem ut non fiat fuga vestra in hieme, vel sabbato:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 21, 'erit enim tunc tribulatio magna, qualis non fuit ab initio mundi usque modo, neque fiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 22, 'Et nisi breviati fuissent dies illi, non fieret salva omnis caro: sed propter electos breviabuntur dies illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 23, 'Tunc si quis vobis dixerit: Ecce hic est Christus, aut illic: nolite credere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 24, 'Surgent enim pseudochristi, et pseudoprophetæ: et dabunt signa magna, et prodigia, ita ut in errorem inducantur (si fieri potest) etiam electi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 25, 'Ecce prædixi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 26, 'Si ergo dixerint vobis: Ecce in deserto est, nolite exire; Ecce in penetralibus, nolite credere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 27, 'Sicut enim fulgur exit ab oriente, et paret usque in occidentem: ita erit et adventus Filii hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 28, 'Ubicumque fuerit corpus, illic congregabuntur et aquilæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 29, 'Statim autem post tribulationem dierum illorum sol obscurabitur, et luna non dabit lumen suum, et stellæ cadent de cælo, et virtutes cælorum commovebuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 30, 'et tunc parebit signum Filii hominis in cælo: et tunc plangent omnes tribus terræ: et videbunt Filium hominis venientem in nubibus cæli cum virtute multa et majestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 31, 'Et mittet angelos suos cum tuba, et voce magna: et congregabunt electos ejus a quatuor ventis, a summis cælorum usque ad terminos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 32, 'Ab arbore autem fici discite parabolam: cum jam ramus ejus tener fuerit, et folia nata, scitis quia prope est æstas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 33, 'ita et vos cum videritis hæc omnia, scitote quia prope est, in januis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 34, 'Amen dico vobis, quia non præteribit generatio hæc, donec omnia hæc fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 35, 'Cælum et terra transibunt, verba autem mea non præteribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 36, 'De die autem illa et hora nemo scit, neque angeli cælorum, nisi solus Pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 37, 'Sicut autem in diebus Noë, ita erit et adventus Filii hominis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 38, 'sicut enim erant in diebus ante diluvium comedentes et bibentes, nubentes et nuptum tradentes, usque ad eum diem, quo intravit Noë in arcam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 39, 'et non cognoverunt donec venit diluvium, et tulit omnes: ita erit et adventus Filii hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 40, 'Tunc duo erunt in agro: unus assumetur, et unus relinquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 41, 'Duæ molentes in mola: una assumetur, et una relinquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 42, 'Vigilate ergo, quia nescitis qua hora Dominus vester venturus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 43, 'Illud autem scitote, quoniam si sciret paterfamilias qua hora fur venturus esset, vigilaret utique, et non sineret perfodi domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 44, 'Ideo et vos estote parati: quia qua nescitis hora Filius hominis venturus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 45, 'Quis, putas, est fidelis servus, et prudens, quem constituit dominus suus super familiam suam ut det illis cibum in tempore?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 46, 'Beatus ille servus, quem cum venerit dominus ejus, invenerit sic facientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 47, 'Amen dico vobis, quoniam super omnia bona sua constituet eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 48, 'Si autem dixerit malus servus ille in corde suo: Moram fecit dominus meus venire:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 49, 'et cœperit percutere conservos suos, manducet autem et bibat cum ebriosis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 50, 'veniet dominus servi illius in die qua non sperat, et hora qua ignorat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 24, 51, 'et dividet eum, partemque ejus ponet cum hypocritis: illic erit fletus et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 1, 'Tunc simile erit regnum cælorum decem virginibus: quæ accipientes lampades suas exierunt obviam sponso et sponsæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 2, 'Quinque autem ex eis erant fatuæ, et quinque prudentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 3, 'sed quinque fatuæ, acceptis lampadibus, non sumpserunt oleum secum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 4, 'prudentes vero acceperunt oleum in vasis suis cum lampadibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 5, 'Moram autem faciente sponso, dormitaverunt omnes et dormierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 6, 'Media autem nocte clamor factus est: Ecce sponsus venit, exite obviam ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 7, 'Tunc surrexerunt omnes virgines illæ, et ornaverunt lampades suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 8, 'Fatuæ autem sapientibus dixerunt: Date nobis de oleo vestro, quia lampades nostræ extinguuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 9, 'Responderunt prudentes, dicentes: Ne forte non sufficiat nobis, et vobis, ite potius ad vendentes, et emite vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 10, 'Dum autem irent emere, venit sponsus: et quæ paratæ erant, intraverunt cum eo ad nuptias, et clausa est janua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 11, 'Novissime vero veniunt et reliquæ virgines, dicentes: Domine, domine, aperi nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 12, 'At ille respondens, ait: Amen dico vobis, nescio vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 13, 'Vigilate itaque, quia nescitis diem, neque horam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 14, 'Sicut enim homo peregre proficiscens, vocavit servos suos, et tradidit illis bona sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 15, 'Et uni dedit quinque talenta, alii autem duo, alii vero unum, unicuique secundum propriam virtutem: et profectus est statim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 16, 'Abiit autem qui quinque talenta acceperat, et operatus est in eis, et lucratus est alia quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 17, 'Similiter et qui duo acceperat, lucratus est alia duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 18, 'Qui autem unum acceperat, abiens fodit in terram, et abscondit pecuniam domini sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 19, 'Post multum vero temporis venit dominus servorum illorum, et posuit rationem cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 20, 'Et accedens qui quinque talenta acceperat, obtulit alia quinque talenta, dicens: Domine, quinque talenta tradidisti mihi, ecce alia quinque superlucratus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 21, 'Ait illi dominus ejus: Euge serve bone, et fidelis: quia super pauca fuisti fidelis, super multa te constituam; intra in gaudium domini tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 22, 'Accessit autem et qui duo talenta acceperat, et ait: Domine, duo talenta tradidisti mihi, ecce alia duo lucratus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 23, 'Ait illi dominus ejus: Euge serve bone, et fidelis: quia super pauca fuisti fidelis, super multa te constituam; intra in gaudium domini tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 24, 'Accedens autem et qui unum talentum acceperat, ait: Domine, scio quia homo durus es; metis ubi non seminasti, et congregas ubi non sparsisti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 25, 'et timens abii, et abscondi talentum tuum in terra: ecce habes quod tuum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 26, 'Respondens autem dominus ejus, dixit ei: Serve male, et piger, sciebas quia meto ubi non semino, et congrego ubi non sparsi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 27, 'oportuit ergo te committere pecuniam meam numulariis, et veniens ego recepissem utique quod meum est cum usura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 28, 'Tollite itaque ab eo talentum, et date ei qui habet decem talenta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 29, 'omni enim habenti dabitur, et abundabit: ei autem qui non habet, et quod videtur habere, auferetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 30, 'Et inutilem servum ejicite in tenebras exteriores: illic erit fletus, et stridor dentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 31, 'Cum autem venerit Filius hominis in majestate sua, et omnes angeli cum eo, tunc sedebit super sedem majestatis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 32, 'et congregabuntur ante eum omnes gentes, et separabit eos ab invicem, sicut pastor segregat oves ab hædis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 33, 'et statuet oves quidem a dextris suis, hædos autem a sinistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 34, 'Tunc dicet rex his qui a dextris ejus erunt: Venite benedicti Patris mei, possidete paratum vobis regnum a constitutione mundi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 35, 'esurivi enim, et dedistis mihi manducare: sitivi, et dedistis mihi bibere: hospes eram, et collegistis me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 36, 'nudus, et cooperuistis me: infirmus, et visitastis me: in carcere eram, et venistis ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 37, 'Tunc respondebunt ei justi, dicentes: Domine, quando te vidimus esurientem, et pavimus te: sitientem, et dedimus tibi potum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 38, 'quando autem te vidimus hospitem, et collegimus te: aut nudum, et cooperuimus te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 39, 'aut quando te vidimus infirmum, aut in carcere, et venimus ad te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 40, 'Et respondens rex, dicet illis: Amen dico vobis, quamdiu fecistis uni ex his fratribus meis minimis, mihi fecistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 41, 'Tunc dicet et his qui a sinistris erunt: Discedite a me maledicti in ignem æternum, qui paratus est diabolo, et angelis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 42, 'esurivi enim, et non dedistis mihi manducare: sitivi, et non dedistis mihi potum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 43, 'hospes eram, et non collegistis me: nudus, et non cooperuistis me: infirmus, et in carcere, et non visitastis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 44, 'Tunc respondebunt ei et ipsi, dicentes: Domine, quando te vidimus esurientem, aut sitientem, aut hospitem, aut nudum, aut infirmum, aut in carcere, et non ministravimus tibi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 45, 'Tunc respondebit illis, dicens: Amen dico vobis: Quamdiu non fecistis uni de minoribus his, nec mihi fecistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 25, 46, 'Et ibunt hi in supplicium æternum: justi autem in vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 1, 'Et factum est: cum consummasset Jesus sermones hos omnes, dixit discipulis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 2, 'Scitis quia post biduum Pascha fiet, et Filius hominis tradetur ut crucifigatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 3, 'Tunc congregati sunt principes sacerdotum, et seniores populi, in atrium principis sacerdotum, qui dicebatur Caiphas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 4, 'et consilium fecerunt ut Jesum dolo tenerent, et occiderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 5, 'Dicebant autem: Non in die festo, ne forte tumultus fieret in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 6, 'Cum autem Jesus esset in Bethania in domo Simonis leprosi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 7, 'accessit ad eum mulier habens alabastrum unguenti pretiosi, et effudit super caput ipsius recumbentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 8, 'Videntes autem discipuli, indignati sunt, dicentes: Ut quid perditio hæc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 9, 'potuit enim istud venundari multo, et dari pauperibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 10, 'Sciens autem Jesus, ait illis: Quid molesti estis huic mulieri? opus enim bonum operata est in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 11, 'Nam semper pauperes habetis vobiscum: me autem non semper habetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 12, 'Mittens enim hæc unguentum hoc in corpus meum, ad sepeliendum me fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 13, 'Amen dico vobis, ubicumque prædicatum fuerit hoc Evangelium in toto mundo, dicetur et quod hæc fecit in memoriam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 14, 'Tunc abiit unus de duodecim, qui dicebatur Judas Iscariotes, ad principes sacerdotum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 15, 'et ait illis: Quid vultis mihi dare, et ego vobis eum tradam? At illi constituerunt ei triginta argenteos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 16, 'Et exinde quærebat opportunitatem ut eum traderet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 17, 'Prima autem die azymorum accesserunt discipuli ad Jesum, dicentes: Ubi vis paremus tibi comedere Pascha?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 18, 'At Jesus dixit: Ite in civitatem ad quemdam, et dicite ei: Magister dicit: Tempus meum prope est, apud te facio Pascha cum discipulis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 19, 'Et fecerunt discipuli sicut constituit illis Jesus, et paraverunt Pascha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 20, 'Vespere autem facto, discumbebat cum duodecim discipulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 21, 'Et edentibus illis, dixit: Amen dico vobis, quia unus vestrum me traditurus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 22, 'Et contristati valde, cœperunt singuli dicere: Numquid ego sum Domine?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 23, 'At ipse respondens, ait: Qui intingit mecum manum in paropside, hic me tradet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 24, 'Filius quidem hominis vadit, sicut scriptum est de illo: væ autem homini illi, per quem Filius hominis tradetur! bonum erat ei, si natus non fuisset homo ille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 25, 'Respondens autem Judas, qui tradidit eum, dixit: Numquid ego sum Rabbi? Ait illi: Tu dixisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 26, 'Cœnantibus autem eis, accepit Jesus panem, et benedixit, ac fregit, deditque discipulis suis, et ait: Accipite, et comedite: hoc est corpus meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 27, 'Et accipiens calicem, gratias egit: et dedit illis, dicens: Bibite ex hoc omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 28, 'Hic est enim sanguis meus novi testamenti, qui pro multis effundetur in remissionem peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 29, 'Dico autem vobis: non bibam amodo de hoc genimine vitis usque in diem illum, cum illud bibam vobiscum novum in regno Patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 30, 'Et hymno dicto, exierunt in montem Oliveti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 31, 'Tunc dicit illis Jesus: Omnes vos scandalum patiemini in me in ista nocte. Scriptum est enim: Percutiam pastorem, et dispergentur oves gregis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 32, 'Postquam autem resurrexero, præcedam vos in Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 33, 'Respondens autem Petrus, ait illi: Et si omnes scandalizati fuerint in te, ego numquam scandalizabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 34, 'Ait illi Jesus: Amen dico tibi, quia in hac nocte, antequam gallus cantet, ter me negabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 35, 'Ait illi Petrus: Etiamsi oportuerit me mori tecum, non te negabo. Similiter et omnes discipuli dixerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 36, 'Tunc venit Jesus cum illis in villam, quæ dicitur Gethsemani, et dixit discipulis suis: Sedete hic donec vadam illuc, et orem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 37, 'Et assumpto Petro, et duobus filiis Zebedæi, cœpit contristari et mœstus esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 38, 'Tunc ait illis: Tristis est anima mea usque ad mortem: sustinete hic, et vigilate mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 39, 'Et progressus pusillum, procidit in faciem suam, orans, et dicens: Pater mi, si possibile est, transeat a me calix iste: verumtamen non sicut ego volo, sed sicut tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 40, 'Et venit ad discipulos suos, et invenit eos dormientes, et dicit Petro: Sic non potuistis una hora vigilare mecum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 41, 'Vigilate, et orate ut non intretis in tentationem. Spiritus quidem promptus est, caro autem infirma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 42, 'Iterum secundo abiit, et oravit, dicens: Pater mi, si non potest hic calix transire nisi bibam illum, fiat voluntas tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 43, 'Et venit iterum, et invenit eos dormientes: erant enim oculi eorum gravati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 44, 'Et relictis illis, iterum abiit, et oravit tertio, eumdem sermonem dicens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 45, 'Tunc venit ad discipulos suos, et dicit illis: Dormite jam, et requiescite: ecce appropinquavit hora, et Filius hominis tradetur in manus peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 46, 'Surgite, eamus: ecce appropinquavit qui me tradet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 47, 'Adhuc eo loquente, ecce Judas unus de duodecim venit, et cum eo turba multa cum gladiis et fustibus, missi a principibus sacerdotum, et senioribus populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 48, 'Qui autem tradidit eum, dedit illis signum, dicens: Quemcumque osculatus fuero, ipse est, tenete eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 49, 'Et confestim accedens ad Jesum, dixit: Ave Rabbi. Et osculatus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 50, 'Dixitque illi Jesus: Amice, ad quid venisti? Tunc accesserunt, et manus injecerunt in Jesum, et tenuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 51, 'Et ecce unus ex his qui erant cum Jesu, extendens manum, exemit gladium suum, et percutiens servum principis sacerdotum amputavit auriculam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 52, 'Tunc ait illi Jesus: Converte gladium tuum in locum suum: omnes enim, qui acceperint gladium, gladio peribunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 53, 'An putas, quia non possum rogare patrem meum, et exhibebit mihi modo plusquam duodecim legiones angelorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 54, 'Quomodo ergo implebuntur Scripturæ, quia sic oportet fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 55, 'In illa hora dixit Jesus turbis: Tamquam ad latronem existis cum gladiis et fustibus comprehendere me: quotidie apud vos sedebam docens in templo, et non me tenuistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 56, 'Hoc autem totum factum est, ut adimplerentur Scripturæ prophetarum. Tunc discipuli omnes, relicto eo, fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 57, 'At illi tenentes Jesum, duxerunt ad Caipham principem sacerdotum, ubi scribæ et seniores convenerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 58, 'Petrus autem sequebatur eum a longe, usque in atrium principis sacerdotum. Et ingressus intro, sedebat cum ministris, ut videret finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 59, 'Principes autem sacerdotum, et omne concilium, quærebant falsum testimonium contra Jesum, ut eum morti traderent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 60, 'et non invenerunt, cum multi falsi testes accessissent. Novissime autem venerunt duo falsi testes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 61, 'et dixerunt: Hic dixit: Possum destruere templum Dei, et post triduum reædificare illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 62, 'Et surgens princeps sacerdotum, ait illi: Nihil respondes ad ea, quæ isti adversum te testificantur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 63, 'Jesus autem tacebat. Et princeps sacerdotum ait illi: Adjuro te per Deum vivum, ut dicas nobis si tu es Christus Filius Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 64, 'Dicit illi Jesus: Tu dixisti. Verumtamen dico vobis, amodo videbitis Filium hominis sedentem a dextris virtutis Dei, et venientem in nubibus cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 65, 'Tunc princeps sacerdotum scidit vestimenta sua, dicens: Blasphemavit: quid adhuc egemus testibus? ecce nunc audistis blasphemiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 66, 'quid vobis videtur? At illi respondentes dixerunt: Reus est mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 67, 'Tunc exspuerunt in faciem ejus, et colaphis eum ceciderunt, alii autem palmas in faciem ejus dederunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 68, 'dicentes: Prophetiza nobis Christe, quis est qui te percussit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 69, 'Petrus vero sedebat foris in atrio: et accessit ad eum una ancilla, dicens: Et tu cum Jesu Galilæo eras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 70, 'At ille negavit coram omnibus, dicens: Nescio quid dicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 71, 'Exeunte autem illo januam, vidit eum alia ancilla, et ait his qui erant ibi: Et hic erat cum Jesu Nazareno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 72, 'Et iterum negavit cum juramento: Quia non novi hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 73, 'Et post pusillum accesserunt qui stabant, et dixerunt Petro: Vere et tu ex illis es: nam et loquela tua manifestum te facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 74, 'Tunc cœpit detestari et jurare quia non novisset hominem. Et continuo gallus cantavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 26, 75, 'Et recordatus est Petrus verbi Jesu, quod dixerat: Priusquam gallus cantet, ter me negabis. Et egressus foras, flevit amare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 1, 'Mane autem facto, consilium inierunt omnes principes sacerdotum et seniores populi adversus Jesum, ut eum morti traderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 2, 'Et vinctum adduxerunt eum, et tradiderunt Pontio Pilato præsidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 3, 'Tunc videns Judas, qui eum tradidit, quod damnatus esset, pœnitentia ductus, retulit triginta argenteos principibus sacerdotum, et senioribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 4, 'dicens: Peccavi, tradens sanguinem justum. At illi dixerunt: Quid ad nos? tu videris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 5, 'Et projectis argenteis in templo, recessit: et abiens laqueo se suspendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 6, 'Principes autem sacerdotum, acceptis argenteis, dixerunt: Non licet eos mittere in corbonam: quia pretium sanguinis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 7, 'Consilio autem inito, emerunt ex illis agrum figuli, in sepulturam peregrinorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 8, 'Propter hoc vocatus est ager ille, Haceldama, hoc est, Ager sanguinis, usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 9, 'Tunc impletum est quod dictum est per Jeremiam prophetam, dicentem: Et acceperunt triginta argenteos pretium appretiati, quem appretiaverunt a filiis Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 10, 'et dederunt eos in agrum figuli, sicut constituit mihi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 11, 'Jesus autem stetit ante præsidem, et interrogavit eum præses, dicens: Tu es rex Judæorum? Dicit illi Jesus: Tu dicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 12, 'Et cum accusaretur a principibus sacerdotum et senioribus, nihil respondit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 13, 'Tunc dicit illi Pilatus: Non audis quanta adversum te dicunt testimonia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 14, 'Et non respondit ei ad ullum verbum, ita ut miraretur præses vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 15, 'Per diem autem solemnem consueverat præses populo dimittere unum vinctum, quem voluissent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 16, 'habebat autem tunc vinctum insignem, qui dicebatur Barabbas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 17, 'Congregatis ergo illis, dixit Pilatus: Quem vultis dimittam vobis: Barabbam, an Jesum, qui dicitur Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 18, 'Sciebat enim quod per invidiam tradidissent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 19, 'Sedente autem illo pro tribunali, misit ad eum uxor ejus, dicens: Nihil tibi, et justo illi: multa enim passa sum hodie per visum propter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 20, 'Principes autem sacerdotum et seniores persuaserunt populis ut peterent Barabbam, Jesum vero perderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 21, 'Respondens autem præses, ait illis: Quem vultis vobis de duobus dimitti? At illi dixerunt: Barabbam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 22, 'Dicit illis Pilatus: Quid igitur faciam de Jesu, qui dicitur Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 23, 'Dicunt omnes: Crucifigatur. Ait illis præses: Quid enim mali fecit? At illi magis clamabant dicentes: Crucifigatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 24, 'Videns autem Pilatus quia nihil proficeret, sed magis tumultus fieret: accepta aqua, lavit manus coram populo, dicens: Innocens ego sum a sanguine justi hujus: vos videritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 25, 'Et respondens universus populus, dixit: Sanguis ejus super nos, et super filios nostros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 26, 'Tunc dimisit illis Barabbam: Jesum autem flagellatum tradidit eis ut crucifigeretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 27, 'Tunc milites præsidis suscipientes Jesum in prætorium, congregaverunt ad eum universam cohortem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 28, 'et exuentes eum, chlamydem coccineam circumdederunt ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 29, 'et plectentes coronam de spinis, posuerunt super caput ejus, et arundinem in dextera ejus. Et genu flexo ante eum, illudebant ei, dicentes: Ave rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 30, 'Et exspuentes in eum, acceperunt arundinem, et percutiebant caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 31, 'Et postquam illuserunt ei, exuerunt eum chlamyde, et induerunt eum vestimentis ejus, et duxerunt eum ut crucifigerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 32, 'Exeuntes autem invenerunt hominem Cyrenæum, nomine Simonem: hunc angariaverunt ut tolleret crucem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 33, 'Et venerunt in locum qui dicitur Golgotha, quod est Calvariæ locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 34, 'Et dederunt ei vinum bibere cum felle mistum. Et cum gustasset, noluit bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 35, 'Postquam autem crucifixerunt eum, diviserunt vestimenta ejus, sortem mittentes: ut impleretur quod dictum est per prophetam dicentem: Diviserunt sibi vestimenta mea, et super vestem meam miserunt sortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 36, 'Et sedentes servabant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 37, 'Et imposuerunt super caput ejus causam ipsius scriptam: Hic est Jesus rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 38, 'Tunc crucifixi sunt cum eo duo latrones: unus a dextris, et unus a sinistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 39, 'Prætereuntes autem blasphemabant eum moventes capita sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 40, 'et dicentes: Vah! qui destruis templum Dei, et in triduo illud reædificas: salva temetipsum: si Filius Dei es, descende de cruce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 41, 'Similiter et principes sacerdotum illudentes cum scribis et senioribus dicebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 42, 'Alios salvos fecit, seipsum non potest salvum facere: si rex Israël est, descendat nunc de cruce, et credimus ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 43, 'confidit in Deo: liberet nunc, si vult eum: dixit enim: Quia Filius Dei sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 44, 'Idipsum autem et latrones, qui crucifixi erant cum eo, improperabant ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 45, 'A sexta autem hora tenebræ factæ sunt super universam terram usque ad horam nonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 46, 'Et circa horam nonam clamavit Jesus voce magna, dicens: Eli, Eli, lamma sabacthani? hoc est: Deus meus, Deus meus, ut quid dereliquisti me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 47, 'Quidam autem illic stantes, et audientes, dicebant: Eliam vocat iste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 48, 'Et continuo currens unus ex eis, acceptam spongiam implevit aceto, et imposuit arundini, et dabat ei bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 49, 'Ceteri vero dicebant: Sine, videamus an veniat Elias liberans eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 50, 'Jesus autem iterum clamans voce magna, emisit spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 51, 'Et ecce velum templi scissum est in duas partes a summo usque deorsum: et terra mota est, et petræ scissæ sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 52, 'et monumenta aperta sunt: et multa corpora sanctorum, qui dormierant, surrexerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 53, 'Et exeuntes de monumentis post resurrectionem ejus, venerunt in sanctam civitatem, et apparuerunt multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 54, 'Centurio autem, et qui cum eo erant, custodientes Jesum, viso terræmotu, et his quæ fiebant, timuerunt valde, dicentes: Vere Filius Dei erat iste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 55, 'Erant autem ibi mulieres multæ a longe, quæ secutæ erant Jesum a Galilæa, ministrantes ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 56, 'inter quas erat Maria Magdalene, et Maria Jacobi, et Joseph mater, et mater filiorum Zebedæi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 57, 'Cum autem sero factum esset, venit quidam homo dives ab Arimathæa, nomine Joseph, qui et ipse discipulus erat Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 58, 'hic accessit ad Pilatum, et petiit corpus Jesu. Tunc Pilatus jussit reddi corpus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 59, 'Et accepto corpore, Joseph involvit illud in sindone munda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 60, 'et posuit illud in monumento suo novo, quod exciderat in petra. Et advolvit saxum magnum ad ostium monumenti, et abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 61, 'Erant autem ibi Maria Magdalene, et altera Maria, sedentes contra sepulchrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 62, 'Altera autem die, quæ est post Parasceven, convenerunt principes sacerdotum et pharisæi ad Pilatum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 63, 'dicentes: Domine, recordati sumus, quia seductor ille dixit adhuc vivens: Post tres dies resurgam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 64, 'Jube ergo custodiri sepulchrum usque in diem tertium: ne forte veniant discipuli ejus, et furentur eum, et dicant plebi: Surrexit a mortuis: et erit novissimus error pejor priore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 65, 'Ait illis Pilatus: Habetis custodiam, ite, custodite sicut scitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 27, 66, 'Illi autem abeuntes, munierunt sepulchrum, signantes lapidem, cum custodibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 1, 'Vespere autem sabbati, quæ lucescit in prima sabbati, venit Maria Magdalene, et altera Maria, videre sepulchrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 2, 'Et ecce terræmotus factus est magnus. Angelus enim Domini descendit de cælo: et accedens revolvit lapidem, et sedebat super eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 3, 'erat autem aspectus ejus sicut fulgur: et vestimentum ejus sicut nix.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 4, 'Præ timore autem ejus exterriti sunt custodes, et facti sunt velut mortui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 5, 'Respondens autem angelus dixit mulieribus: Nolite timere vos: scio enim, quod Jesum, qui crucifixus est, quæritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 6, 'Non est hic: surrexit enim, sicut dixit: venite, et videte locum ubi positus erat Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 7, 'Et cito euntes, dicite discipulis ejus quia surrexit: et ecce præcedit vos in Galilæam: ibi eum videbitis: ecce prædixi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 8, 'Et exierunt cito de monumento cum timore et gaudio magno, currentes nuntiare discipulis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 9, 'Et ecce Jesus occurrit illis, dicens: Avete. Illæ autem accesserunt, et tenuerunt pedes ejus, et adoraverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 10, 'Tunc ait illis Jesus: Nolite timere: ite, nuntiate fratribus meis ut eant in Galilæam; ibi me videbunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 11, 'Quæ cum abiissent, ecce quidam de custodibus venerunt in civitatem, et nuntiaverunt principibus sacerdotum omnia quæ facta fuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 12, 'Et congregati cum senioribus consilio accepto, pecuniam copiosam dederunt militibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 13, 'dicentes: Dicite quia discipuli ejus nocte venerunt, et furati sunt eum, nobis dormientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 14, 'Et si hoc auditum fuerit a præside, nos suadebimus ei, et securos vos faciemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 15, 'At illi, accepta pecunia, fecerunt sicut erant edocti. Et divulgatum est verbum istud apud Judæos, usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 16, 'Undecim autem discipuli abierunt in Galilæam in montem ubi constituerat illis Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 17, 'Et videntes eum adoraverunt: quidam autem dubitaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 18, 'Et accedens Jesus locutus est eis, dicens: Data est mihi omnis potestas in cælo et in terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 19, 'euntes ergo docete omnes gentes: baptizantes eos in nomine Patris, et Filii, et Spiritus Sancti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 28, 20, 'docentes eos servare omnia quæcumque mandavi vobis: et ecce ego vobiscum sum omnibus diebus, usque ad consummationem sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Initium Evangelii Jesu Christi, Filii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Sicut scriptum est in Isaia propheta: Ecce ego mitto angelum meum ante faciem tuam, qui præparabit viam tuam ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Vox clamantis in deserto: Parate viam Domini, rectas facite semitas ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Fuit Joannes in deserto baptizans, et prædicans baptismum pœnitentiæ in remissionem peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Et egrediebatur ad eum omnis Judææ regio, et Jerosolymitæ universi, et baptizabantur ab illo in Jordanis flumine, confitentes peccata sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Et erat Joannes vestitus pilis cameli, et zona pellicea circa lumbos ejus, et locustas et mel silvestre edebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Et prædicabat dicens: Venit fortior me post me, cujus non sum dignus procumbens solvere corrigiam calceamentorum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ego baptizavi vos aqua, ille vero baptizabit vos Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Et factum est: in diebus illis venit Jesus a Nazareth Galilææ: et baptizatus est a Joanne in Jordane.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Et statim ascendens de aqua, vidit cælos apertos, et Spiritum tamquam columbam descendentem, et manentem in ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Et vox facta est de cælis: Tu es Filius meus dilectus, in te complacui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Et statim Spiritus expulit eum in desertum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Et erat in deserto quadraginta diebus, et quadraginta noctibus: et tentabatur a Satana: eratque cum bestiis, et angeli ministrabant illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Postquam autem traditus est Joannes, venit Jesus in Galilæam, prædicans Evangelium regni Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'et dicens: Quoniam impletum est tempus, et appropinquavit regnum Dei: pœnitemini, et credite Evangelio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Et præteriens secus mare Galilææ, vidit Simonem, et Andream fratrem ejus, mittentes retia in mare (erant enim piscatores),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'et dixit eis Jesus: Venite post me, et faciam vos fieri piscatores hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Et protinus relictis retibus, secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Et progressus inde pusillum, vidit Jacobum Zebedæi, et Joannem fratrem ejus, et ipsos componentes retia in navi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'et statim vocavit illos. Et relicto patre suo Zebedæo in navi cum mercenariis, secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Et ingrediuntur Capharnaum: et statim sabbatis ingressus in synagogam, docebat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Et stupebant super doctrina ejus: erat enim docens eos quasi potestatem habens, et non sicut scribæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Et erat in synagoga eorum homo in spiritu immundo: et exclamavit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'dicens: Quid nobis et tibi, Jesu Nazarene? venisti perdere nos? scio qui sis, Sanctus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 25, 'Et comminatus est ei Jesus, dicens: Obmutesce, et exi de homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 26, 'Et discerpens eum spiritus immundus, et exclamans voce magna, exiit ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 27, 'Et mirati sunt omnes, ita ut conquirerent inter se dicentes: Quidnam est hoc? quænam doctrina hæc nova? quia in potestate etiam spiritibus immundis imperat, et obediunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 28, 'Et processit rumor ejus statim in omnem regionem Galilææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 29, 'Et protinus egredientes de synagoga, venerunt in domum Simonis et Andreæ, cum Jacobo et Joanne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 30, 'Decumbebat autem socrus Simonis febricitans: et statim dicunt ei de illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 31, 'Et accedens elevavit eam, apprehensa manu ejus: et continuo dimisit eam febris, et ministrabat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 32, 'Vespere autem facto cum occidisset sol, afferebant ad eum omnes male habentes, et dæmonia habentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 33, 'et erat omnis civitas congregata ad januam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 34, 'Et curavit multos, qui vexabantur variis languoribus, et dæmonia multa ejiciebat, et non sinebat ea loqui, quoniam sciebant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 35, 'Et diluculo valde surgens, egressus abiit in desertum locum, ibique orabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 36, 'Et prosecutus est eum Simon, et qui cum illo erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 37, 'Et cum invenissent eum, dixerunt ei: Quia omnes quærunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 38, 'Et ait illis: Eamus in proximos vicos, et civitates, ut et ibi prædicem: ad hoc enim veni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 39, 'Et erat prædicans in synagogis eorum, et in omni Galilæa, et dæmonia ejiciens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 40, 'Et venit ad eum leprosus deprecans eum: et genu flexo dixit ei: Si vis, potes me mundare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 41, 'Jesus autem misertus ejus, extendit manum suam: et tangens eum, ait illi: Volo: mundare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 42, 'Et cum dixisset, statim discessit ab eo lepra, et mundatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 43, 'Et comminatus est ei, statimque ejecit illum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 44, 'et dicit ei: Vide nemini dixeris: sed vade, ostende te principi sacerdotum, et offer pro emundatione tua, quæ præcepit Moyses in testimonium illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 45, 'At ille egressus cœpit prædicare, et diffamare sermonem, ita ut jam non posset manifeste introire in civitatem, sed foris in desertis locis esset, et conveniebant ad eum undique.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Et iterum intravit Capharnaum post dies,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'et auditum est quod in domo esset, et convenerunt multi, ita ut non caperet neque ad januam, et loquebatur eis verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Et venerunt ad eum ferentes paralyticum, qui a quatuor portabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Et cum non possent offerre eum illi præ turba, nudaverunt tectum ubi erat: et patefacientes submiserunt grabatum in quo paralyticus jacebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Cum autem vidisset Jesus fidem illorum, ait paralytico: Fili, dimittuntur tibi peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Erant autem illic quidam de scribis sedentes, et cogitantes in cordibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Quid hic sic loquitur? blasphemat. Quis potest dimittere peccata, nisi solus Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Quo statim cognito Jesus spiritu suo, quia sic cogitarent intra se, dicit illis: Quid ista cogitatis in cordibus vestris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Quid est facilius dicere paralytico: Dimittuntur tibi peccata: an dicere: Surge, tolle grabatum tuum, et ambula?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Ut autem sciatis quia Filius hominis habet potestatem in terra dimittendi peccata (ait paralytico),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'tibi dico: Surge, tolle grabatum tuum, et vade in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Et statim surrexit ille: et, sublato grabato, abiit coram omnibus, ita ut mirarentur omnes, et honorificent Deum, dicentes: Quia numquam sic vidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Et egressus est rursus ad mare, omnisque turba veniebat ad eum, et docebat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Et cum præteriret, vidit Levi Alphæi sedentem ad telonium, et ait illi: Sequere me. Et surgens secutus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Et factum est, cum accumberet in domo illius, multi publicani et peccatores simul discumbebant cum Jesu et discipulis ejus: erant enim multi, qui et sequebantur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Et scribæ et pharisæi videntes quia manducaret cum publicanis et peccatoribus, dicebant discipulis ejus: Quare cum publicanis et peccatoribus manducat et bibit Magister vester?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Hoc audito Jesus ait illis: Non necesse habent sani medico, sed qui male habent: non enim veni vocare justos, sed peccatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Et erant discipuli Joannis et pharisæi jejunantes: et veniunt, et dicunt illi: Quare discipuli Joannis et pharisæorum jejunant, tui autem discipuli non jejunant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Et ait illis Jesus: Numquid possunt filii nuptiarum, quamdiu sponsus cum illis est, jejunare? Quanto tempore habent secum sponsum, non possunt jejunare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Venient autem dies cum auferetur ab eis sponsus: et tunc jejunabunt in illis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nemo assumentum panni rudis assuit vestimento veteri: alioquin aufert supplementum novum a veteri, et major scissura fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 22, 'Et nemo mittit vinum novum in utres veteres: alioquin dirumpet vinum utres, et vinum effundetur, et utres peribunt: sed vinum novum in utres novos mitti debet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 23, 'Et factum est iterum cum Dominus sabbatis ambularet per sata, et discipuli ejus cœperunt progredi, et vellere spicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 24, 'Pharisæi autem dicebant ei: Ecce, quid faciunt sabbatis quod non licet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 25, 'Et ait illis: Numquam legistis quid fecerit David, quando necessitatem habuit, et esuriit ipse, et qui cum eo erant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 26, 'quomodo introivit in domum Dei sub Abiathar principe sacerdotum, et panes propositionis manducavit, quos non licebat manducare, nisi sacerdotibus, et dedit eis qui cum eo erant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 27, 'Et dicebat eis: Sabbatum propter hominem factum est, et non homo propter sabbatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 28, 'Itaque Dominus est Filius hominis, etiam sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Et introivit iterum in synagogam: et erat ibi homo habens manum aridam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Et observabant eum, si sabbatis curaret, ut accusarent illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Et ait homini habenti manum aridam: Surge in medium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Et dicit eis: Licet sabbatis benefacere, an male? animam salvam facere, an perdere? At illi tacebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Et circumspiciens eos cum ira, contristatus super cæcitate cordis eorum, dicit homini: Extende manum tuam. Et extendit, et restituta est manus illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Exeuntes autem pharisæi, statim cum Herodianis consilium faciebant adversus eum quomodo eum perderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Jesus autem cum discipulis suis secessit ad mare: et multa turba a Galilæa et Judæa secuta est eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'et ab Jerosolymis, et ab Idumæa, et trans Jordanem: et qui circa Tyrum et Sidonem multitudo magna, audientes quæ faciebat, venerunt ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Et dicit discipulis suis ut navicula sibi deserviret propter turbam, ne comprimerent eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'multos enim sanabat, ita ut irruerent in eum ut illum tangerent, quotquot habebant plagas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Et spiritus immundi, cum illum videbant, procidebant ei: et clamabant, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Tu es Filius Dei. Et vehementer comminabatur eis ne manifestarent illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Et ascendens in montem vocavit ad se quos voluit ipse: et venerunt ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Et fecit ut essent duodecim cum illo: et ut mitteret eos prædicare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Et dedit illis potestatem curandi infirmitates et ejiciendi dæmonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Et imposuit Simoni nomen Petrus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'et Jacobum Zebedæi, et Joannem fratrem Jacobi, et imposuit eis nomina Boanerges, quod est, Filii tonitrui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'et Andream, et Philippum, et Bartholomæum, et Matthæum, et Thomam, et Jacobum Alphæi, et Thaddæum, et Simonem Cananæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'et Judam Iscariotem, qui et tradidit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Et veniunt ad domum: et convenit iterum turba, ita ut non possent neque panem manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Et cum audissent sui, exierunt tenere eum: dicebant enim: Quoniam in furorem versus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Et scribæ, qui ab Jerosolymis descenderant, dicebant: Quoniam Beelzebub habet, et quia in principe dæmoniorum ejicit dæmonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Et convocatis eis in parabolis dicebat illis: Quomodo potest Satanas Satanam ejicere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Et si regnum in se dividatur, non potest regnum illud stare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Et si domus super semetipsam dispertiatur, non potest domus illa stare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Et si Satanas consurrexerit in semetipsum, dispertitus est, et non poterit stare, sed finem habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Nemo potest vasa fortis ingressus in domum diripere, nisi prius fortem alliget, et tunc domum ejus diripiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Amen dico vobis, quoniam omnia dimittentur filiis hominum peccata, et blasphemiæ quibus blasphemaverint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'qui autem blasphemaverit in Spiritum Sanctum, non habebit remissionem in æternum, sed reus erit æterni delicti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 30, 'Quoniam dicebant: Spiritum immundum habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 31, 'Et veniunt mater ejus et fratres: et foris stantes miserunt ad eum vocantes eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 32, 'et sedebat circa eum turba: et dicunt ei: Ecce mater tua et fratres tui foris quærunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 33, 'Et respondens eis, ait: Quæ est mater mea et fratres mei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 34, 'Et circumspiciens eos, qui in circuitu ejus sedebant, ait: Ecce mater mea et fratres mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 35, 'Qui enim fecerit voluntatem Dei, hic frater meus, et soror mea, et mater est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Et iterum cœpit docere ad mare: et congregata est ad eum turba multa, ita ut navim ascendens sederet in mari, et omnis turba circa mare super terram erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'et docebat eos in parabolis multa, et dicebat illis in doctrina sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Audite: ecce exiit seminans ad seminandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Et dum seminat, aliud cecidit circa viam, et venerunt volucres cæli, et comederunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Aliud vero cecidit super petrosa, ubi non habuit terram multam: et statim exortum est, quoniam non habebat altitudinem terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'et quando exortus est sol, exæstuavit: et eo quod non habebat radicem, exaruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Et aliud cecidit in spinas: et ascenderunt spinæ, et suffocaverunt illud, et fructum non dedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Et aliud cecidit in terram bonam: et dabat fructum ascendentem et crescentem, et afferebat unum triginta, unum sexaginta, et unum centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Et dicebat: Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Et cum esset singularis, interrogaverunt eum hi qui cum eo erant duodecim, parabolam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Et dicebat eis: Vobis datum est nosse mysterium regni Dei: illis autem, qui foris sunt, in parabolis omnia fiunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'ut videntes videant, et non videant: et audientes audiant, et non intelligant: nequando convertantur, et dimittantur eis peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Et ait illis: Nescitis parabolam hanc? Et quomodo omnes parabolas cognoscetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Qui seminat, verbum seminat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Hi autem sunt, qui circa viam, ubi seminatur verbum, et cum audierint, confestim venit Satanas, et aufert verbum, quod seminatum est in cordibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Et hi sunt similiter, qui super petrosa seminantur: qui cum audierint verbum, statim cum gaudio accipiunt illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'et non habent radicem in se, sed temporales sunt: deinde orta tribulatione et persecutione propter verbum, confestim scandalizantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Et alii sunt qui in spinas seminantur: hi sunt qui verbum audiunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'et ærumnæ sæculi, et deceptio divitiarum, et circa reliqua concupiscentiæ introëuntes suffocant verbum, et sine fructu efficitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Et hi sunt qui super terram bonam seminati sunt, qui audiunt verbum, et suscipiunt, et fructificant, unum triginta, unum sexaginta, et unum centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Et dicebat illis: Numquid venit lucerna ut sub modio ponatur, aut sub lecto? nonne ut super candelabrum ponatur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Non est enim aliquid absconditum, quod non manifestetur: nec factum est occultum, sed ut in palam veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Si quis habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Et dicebat illis: Videte quid audiatis. In qua mensura mensi fueritis, remetietur vobis, et adjicietur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Qui enim habet, dabitur illi: et qui non habet, etiam quod habet auferetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Et dicebat: Sic est regnum Dei, quemadmodum si homo jaciat sementem in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'et dormiat, et exsurgat nocte et die, et semen germinet, et increscat dum nescit ille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Ultro enim terra fructificat, primum herbam, deinde spicam, deinde plenum frumentum in spica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Et cum produxerit fructus, statim mittit falcem, quoniam adest messis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Et dicebat: Cui assimilabimus regnum Dei? aut cui parabolæ comparabimus illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Sicut granum sinapis, quod cum seminatum fuerit in terra, minus est omnibus seminibus, quæ sunt in terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 32, 'et cum seminatum fuerit, ascendit, et fit majus omnibus oleribus, et facit ramos magnos, ita ut possint sub umbra ejus aves cæli habitare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 33, 'Et talibus multis parabolis loquebatur eis verbum, prout poterant audire:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 34, 'sine parabola autem non loquebatur eis: seorsum autem discipulis suis disserebat omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 35, 'Et ait illis in illa die, cum sero esset factum: Transeamus contra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 36, 'Et dimittentes turbam, assumunt eum ita ut erat in navi: et aliæ naves erant cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 37, 'Et facta est procella magna venti, et fluctus mittebat in navim, ita ut impleretur navis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 38, 'Et erat ipse in puppi super cervical dormiens: et excitant eum, et dicunt illi: Magister, non ad te pertinet, quia perimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 39, 'Et exsurgens comminatus est vento, et dixit mari: Tace, obmutesce. Et cessavit ventus: et facta est tranquillitas magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 40, 'Et ait illis: Quid timidi estis? necdum habetis fidem? et timuerunt timore magno, et dicebant ad alterutrum: Quis, putas, est iste, quia et ventus et mare obediunt ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Et venerunt trans fretum maris in regionem Gerasenorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Et exeunti ei de navi, statim occurrit de monumentis homo in spiritu immundo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'qui domicilium habebat in monumentis, et neque catenis jam quisquam poterat eum ligare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'quoniam sæpe compedibus et catenis vinctus, dirupisset catenas, et compedes comminuisset, et nemo poterat eum domare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'et semper die ac nocte in monumentis, et in montibus erat, clamans, et concidens se lapidibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Videns autem Jesum a longe, cucurrit, et adoravit eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'et clamans voce magna dixit: Quid mihi et tibi, Jesu Fili Dei altissimi? adjuro te per Deum, ne me torqueas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Dicebat enim illi: Exi spiritus immunde ab homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Et interrogabat eum: Quod tibi nomen est? Et dicit ei: Legio mihi nomen est, quia multi sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Et deprecabatur eum multum, ne se expelleret extra regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Erat autem ibi circa montem grex porcorum magnus, pascens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Et deprecabantur eum spiritus, dicentes: Mitte nos in porcos ut in eos introëamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Et concessit eis statim Jesus. Et exeuntes spiritus immundi introierunt in porcos: et magno impetu grex præcipitatus est in mare ad duo millia, et suffocati sunt in mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Qui autem pascebant eos, fugerunt, et nuntiaverunt in civitatem et in agros. Et egressi sunt videre quid esset factum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'et veniunt ad Jesum: et vident illum qui a dæmonio vexabatur, sedentem, vestitum, et sanæ mentis, et timuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Et narraverunt illis, qui viderant, qualiter factum esset ei qui dæmonium habuerat, et de porcis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Et rogare cœperunt eum ut discederet de finibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Cumque ascenderet navim, cœpit illum deprecari, qui a dæmonio vexatus fuerat, ut esset cum illo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'et non admisit eum, sed ait illi: Vade in domum tuam ad tuos, et annuntia illis quanta tibi Dominus fecerit, et misertus sit tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Et abiit, et cœpit prædicare in Decapoli, quanta sibi fecisset Jesus: et omnes mirabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Et cum transcendisset Jesus in navi rursum trans fretum, convenit turba multa ad eum, et erat circa mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Et venit quidam de archisynagogis nomine Jairus, et videns eum procidit ad pedes ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'et deprecabatur eum multum, dicens: Quoniam filia mea in extremis est, veni, impone manum super eam, ut salva sit, et vivat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Et abiit cum illo, et sequebatur eum turba multa, et comprimebant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Et mulier, quæ erat in profluvio sanguinis annis duodecim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'et fuerat multa perpessa a compluribus medicis: et erogaverat omnia sua, nec quidquam profecerat, sed magis deterius habebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 27, 'cum audisset de Jesu, venit in turba retro, et tetigit vestimentum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 28, 'dicebat enim: Quia si vel vestimentum ejus tetigero, salva ero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 29, 'Et confestim siccatus est fons sanguinis ejus: et sensit corpore quia sanata esset a plaga.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 30, 'Et statim Jesus in semetipso cognoscens virtutem quæ exierat de illo, conversus ad turbam, aiebat: Quis tetigit vestimenta mea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 31, 'Et dicebant ei discipuli sui: Vides turbam comprimentem te, et dicis: Quis me tetigit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 32, 'Et circumspiciebat videre eam, quæ hoc fecerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 33, 'Mulier vero timens et tremens, sciens quod factum esset in se, venit et procidit ante eum, et dixit ei omnem veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 34, 'Ille autem dixit ei: Filia, fides tua te salvam fecit: vade in pace, et esto sana a plaga tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 35, 'Adhuc eo loquente, veniunt ab archisynagogo, dicentes: Quia filia tua mortua est: quid ultra vexas magistrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 36, 'Jesus autem audito verbo quod dicebatur, ait archisynagogo: Noli timere: tantummodo crede.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 37, 'Et non admisit quemquam se sequi nisi Petrum, et Jacobum, et Joannem fratrem Jacobi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 38, 'Et veniunt in domum archisynagogi, et videt tumultum, et flentes, et ejulantes multum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 39, 'Et ingressus, ait illis: Quid turbamini, et ploratis? puella non est mortua, sed dormit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 40, 'Et irridebant eum. Ipse vero ejectis omnibus assumit patrem, et matrem puellæ, et qui secum erant, et ingreditur ubi puella erat jacens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 41, 'Et tenens manum puellæ, ait illi: Talitha cumi, quod est interpretatum: Puella (tibi dico), surge.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 42, 'Et confestim surrexit puella, et ambulabat: erat autem annorum duodecim: et obstupuerunt stupore magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 43, 'Et præcepit illis vehementer ut nemo id sciret: et dixit dari illi manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Et egressus inde, abiit in patriam suam: et sequebantur eum discipuli sui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'et facto sabbato cœpit in synagoga docere: et multi audientes admirabantur in doctrina ejus, dicentes: Unde huic hæc omnia? et quæ est sapientia, quæ data est illi, et virtutes tales, quæ per manus ejus efficiuntur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Nonne hic est faber, filius Mariæ, frater Jacobi, et Joseph, et Judæ, et Simonis? nonne et sorores ejus hic nobiscum sunt? Et scandalizabantur in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Et dicebat illis Jesus: Quia non est propheta sine honore nisi in patria sua, et in domo sua, et in cognatione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Et non poterat ibi virtutem ullam facere, nisi paucos infirmos impositis manibus curavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'et mirabatur propter incredulitatem eorum, et circuibat castella in circuitu docens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Et vocavit duodecim: et cœpit eos mittere binos, et dabat illis potestatem spirituum immundorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Et præcepit eis ne quid tollerent in via, nisi virgam tantum: non peram, non panem, neque in zona æs,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'sed calceatos sandaliis, et ne induerentur duabus tunicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Et dicebat eis: Quocumque introieritis in domum, illic manete donec exeatis inde:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'et quicumque non receperint vos, nec audierint vos, exeuntes inde, excutite pulverem de pedibus vestris in testimonium illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Et exeuntes prædicabant ut pœnitentiam agerent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'et dæmonia multa ejiciebant, et ungebant oleo multos ægros, et sanabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Et audivit rex Herodes (manifestum enim factum est nomen ejus), et dicebat: Quia Joannes Baptista resurrexit a mortuis: et propterea virtutes operantur in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Alii autem dicebant: Quia Elias est; alii vero dicebant: Quia propheta est, quasi unus ex prophetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Quo audito Herodes ait: Quem ego decollavi Joannem, hic a mortuis resurrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Ipse enim Herodes misit, ac tenuit Joannem, et vinxit eum in carcere propter Herodiadem uxorem Philippi fratris sui, quia duxerat eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Dicebat enim Joannes Herodi: Non licet tibi habere uxorem fratris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 19, 'Herodias autem insidiabatur illi: et volebat occidere eum, nec poterat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 20, 'Herodes enim metuebat Joannem, sciens eum virum justum et sanctum: et custodiebat eum, et audito eo multa faciebat, et libenter eum audiebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 21, 'Et cum dies opportunus accidisset, Herodes natalis sui cœnam fecit principibus, et tribunis, et primis Galilææ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 22, 'cumque introisset filia ipsius Herodiadis, et saltasset, et placuisset Herodi, simulque recumbentibus, rex ait puellæ: Pete a me quod vis, et dabo tibi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 23, 'et juravit illi: Quia quidquid petieris dabo tibi, licet dimidium regni mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 24, 'Quæ cum exisset, dixit matri suæ: Quid petam? At illa dixit: Caput Joannis Baptistæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 25, 'Cumque introisset statim cum festinatione ad regem, petivit dicens: Volo ut protinus des mihi in disco caput Joannis Baptistæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 26, 'Et contristatus est rex: propter jusjurandum, et propter simul discumbentes, noluit eam contristare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 27, 'sed misso spiculatore præcepit afferri caput ejus in disco. Et decollavit eum in carcere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 28, 'et attulit caput ejus in disco: et dedit illud puellæ, et puella dedit matri suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 29, 'Quo audito, discipuli ejus venerunt, et tulerunt corpus ejus: et posuerunt illud in monumento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 30, 'Et convenientes Apostoli ad Jesum, renuntiaverunt ei omnia quæ egerant, et docuerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 31, 'Et ait illis: Venite seorsum in desertum locum, et requiescite pusillum. Erant enim qui veniebant et redibant multi: et nec spatium manducandi habebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 32, 'Et ascendentes in navim, abierunt in desertum locum seorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 33, 'Et viderunt eos abeuntes, et cognoverunt multi: et pedestres de omnibus civitatibus concurrerunt illuc, et prævenerunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 34, 'Et exiens vidit turbam multam Jesus: et misertus est super eos, quia erant sicut oves non habentes pastorem, et cœpit docere multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 35, 'Et cum jam hora multa fieret, accesserunt discipuli ejus, dicentes: Desertus est locus hic, et jam hora præteriit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 36, 'dimitte illos, ut euntes in proximas villas et vicos, emant sibi cibos, quos manducent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 37, 'Et respondens ait illis: Date illis vos manducare. Et dixerunt ei: Euntes emamus ducentis denariis panes, et dabimus illis manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 38, 'Et dicit eis: Quot panes habetis? ite, et videte. Et cum cognovissent, dicunt: Quinque, et duos pisces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 39, 'Et præcepit illis ut accumbere facerent omnes secundum contubernia super viride fœnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 40, 'Et discubuerunt in partes per centenos et quinquagenos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 41, 'Et acceptis quinque panibus et duobus piscibus, intuens in cælum, benedixit, et fregit panes, et dedit discipulis suis, ut ponerent ante eos: et duos pisces divisit omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 42, 'Et manducaverunt omnes, et saturati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 43, 'Et sustulerunt reliquias, fragmentorum duodecim cophinos plenos, et de piscibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 44, 'Erant autem qui manducaverunt quinque millia virorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 45, 'Et statim coëgit discipulos suos ascendere navim, ut præcederent eum trans fretum ad Bethsaidam, dum ipse dimitteret populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 46, 'Et cum dimisisset eos, abiit in montem orare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 47, 'Et cum sero esset, erat navis in medio mari et ipse solus in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 48, 'Et videns eos laborantes in remigando (erat enim ventus contrarius eis) et circa quartam vigiliam noctis venit ad eos ambulans supra mare: et volebat præterire eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 49, 'At illi ut viderunt eum ambulantem supra mare, putaverunt phantasma esse, et exclamaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 50, 'Omnes enim viderunt eum, et conturbati sunt. Et statim locutus est cum eis, et dixit eis: Confidite, ego sum: nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 51, 'Et ascendit ad illos in navim, et cessavit ventus. Et plus magis intra se stupebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 52, 'non enim intellexerunt de panibus: erat enim cor eorum obcæcatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 53, 'Et cum transfretassent, venerunt in terram Genesareth, et applicuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 54, 'Cumque egressi essent de navi, continuo cognoverunt eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 55, 'et percurrentes universam regionem illam, cœperunt in grabatis eos, qui se male habebant, circumferre, ubi audiebant eum esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 56, 'Et quocumque introibat, in vicos, vel in villas aut civitates, in plateis ponebant infirmos, et deprecabantur eum, ut vel fimbriam vestimenti ejus tangerent, et quotquot tangebant eum, salvi fiebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 1, 'Et conveniunt ad eum pharisæi, et quidam de scribis, venientes ab Jerosolymis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 2, 'Et cum vidissent quosdam ex discipulis ejus communibus manibus, id est non lotis, manducare panes, vituperaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 3, 'Pharisæi enim, et omnes Judæi, nisi crebro laverint manus, non manducant, tenentes traditionem seniorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 4, 'et a foro nisi baptizentur, non comedunt: et alia multa sunt, quæ tradita sunt illis servare, baptismata calicum, et urceorum, et æramentorum, et lectorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 5, 'et interrogabant eum pharisæi et scribæ: Quare discipuli tui non ambulant juxta traditionem seniorum, sed communibus manibus manducant panem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 6, 'At ille respondens, dixit eis: Bene prophetavit Isaias de vobis hypocritis, sicut scriptum est: Populus hic labiis me honorat, cor autem eorum longe est a me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 7, 'in vanum autem me colunt, docentes doctrinas, et præcepta hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 8, 'Relinquentes enim mandatum Dei, tenetis traditionem hominum, baptismata urceorum et calicum: et alia similia his facitis multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 9, 'Et dicebat illis: Bene irritum facitis præceptum Dei, ut traditionem vestram servetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 10, 'Moyses enim dixit: Honora patrem tuum, et matrem tuam. Et: Qui maledixerit patri, vel matri, morte moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 11, 'Vos autem dicitis: Si dixerit homo patri, aut matri, Corban (quod est donum) quodcumque ex me, tibi profuerit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 12, 'et ultra non dimittitis eum quidquam facere patri suo, aut matri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 13, 'rescindentes verbum Dei per traditionem vestram, quam tradidistis: et similia hujusmodi multa facitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 14, 'Et advocans iterum turbam, dicebat illis: Audite me omnes, et intelligite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 15, 'Nihil est extra hominem introiens in eum, quod possit eum coinquinare, sed quæ de homine procedunt illa sunt quæ communicant hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 16, 'Si quis habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 17, 'Et cum introisset in domum a turba, interrogabant eum discipuli ejus parabolam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 18, 'Et ait illis: Sic et vos imprudentes estis? Non intelligitis quia omne extrinsecus introiens in hominem, non potest eum communicare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 19, 'quia non intrat in cor ejus, sed in ventrum vadit, et in secessum exit, purgans omnes escas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 20, 'Dicebat autem, quoniam quæ de homine exeunt, illa communicant hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 21, 'Ab intus enim de corde hominum malæ cogitationes procedunt, adulteria, fornicationes, homicidia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 22, 'furta, avaritiæ, nequitiæ, dolus, impudicitiæ, oculus malus, blasphemia, superbia, stultitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 23, 'Omnia hæc mala ab intus procedunt, et communicant hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 24, 'Et inde surgens abiit in fines Tyri et Sidonis: et ingressus domum, neminem voluit scire, et non potuit latere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 25, 'Mulier enim statim ut audivit de eo, cujus filia habebat spiritum immundum, intravit, et procidit ad pedes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 26, 'Erat enim mulier gentilis, Syrophœnissa genere. Et rogabat eum ut dæmonium ejiceret de filia ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 27, 'Qui dixit illi: Sine prius saturari filios: non est enim bonum sumere panem filiorum, et mittere canibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 28, 'At illa respondit, et dixit illi: Utique Domine, nam et catelli comedunt sub mensa de micis puerorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 29, 'Et ait illi: Propter hunc sermonem vade: exiit dæmonium a filia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 30, 'Et cum abiisset domum suam, invenit puellam jacentem supra lectum, et dæmonium exiisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 31, 'Et iterum exiens de finibus Tyri, venit per Sidonem ad mare Galilææ inter medios fines Decapoleos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 32, 'Et adducunt ei surdum, et mutum, et deprecabantur eum, ut imponat illi manum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 33, 'Et apprehendens eum de turba seorsum, misit digitos suos in auriculas ejus: et exspuens, tetigit linguam ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 34, 'et suspiciens in cælum, ingemuit, et ait illi: Ephphetha, quod est, Adaperire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 35, 'Et statim apertæ sunt aures ejus, et solutum est vinculum linguæ ejus, et loquebatur recte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 36, 'Et præcepit illis ne cui dicerent. Quanto autem eis præcipiebat, tanto magis plus prædicabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 7, 37, 'et eo amplius admirabantur, dicentes: Bene omnia fecit: et surdos fecit audire, et mutos loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 1, 'In diebus illis iterum cum turba multa esset, nec haberent quod manducarent, convocatis discipulis, ait illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 2, 'Misereor super turbam: quia ecce jam triduo sustinent me, nec habent quod manducent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 3, 'et si dimisero eos jejunos in domum suam, deficient in via: quidam enim ex eis de longe venerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 4, 'Et responderunt ei discipuli sui: Unde illos quis poterit saturare panibus in solitudine?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 5, 'Et interrogavit eos: Quot panes habetis? Qui dixerunt: Septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 6, 'Et præcepit turbæ discumbere super terram. Et accipiens septem panes, gratias agens fregit, et dabat discipulis suis ut apponerent, et apposuerunt turbæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 7, 'Et habebant pisciculos paucos: et ipsos benedixit, et jussit apponi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 8, 'Et manducaverunt, et saturati sunt, et sustulerunt quod superaverat de fragmentis, septem sportas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 9, 'Erant autem qui manducaverunt, quasi quatuor millia: et dimisit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 10, 'Et statim ascendens navim cum discipulis suis, venit in partes Dalmanutha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 11, 'Et exierunt pharisæi, et cœperunt conquirere cum eo, quærentes ab illo signum de cælo, tentantes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 12, 'Et ingemiscens spiritu, ait: Quid generatio ista signum quærit? Amen dico vobis, si dabitur generationi isti signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 13, 'Et dimittens eos, ascendit iterum navim et abiit trans fretum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 14, 'Et obliti sunt panes sumere: et nisi unum panem non habebant secum in navi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 15, 'Et præcipiebat eis, dicens: Videte, et cavete a fermento pharisæorum, et fermento Herodis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 16, 'Et cogitabant ad alterutrum, dicentes: quia panes non habemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 17, 'Quo cognito, ait illis Jesus: Quid cogitatis, quia panes non habetis? nondum cognoscetis nec intelligitis? adhuc cæcatum habetis cor vestrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 18, 'oculos habentes non videtis? et aures habentes non auditis? nec recordamini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 19, 'quando quinque panes fregi in quinque millia: quot cophinos fragmentorum plenos sustulistis? Dicunt ei: Duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 20, 'Quando et septem panes in quatuor millia: quot sportas fragmentorum tulistis? Et dicunt ei: Septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 21, 'Et dicebat eis: Quomodo nondum intelligitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 22, 'Et veniunt Bethsaidam, et adducunt ei cæcum, et rogabant eum ut illum tangeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 23, 'Et apprehensa manu cæci, eduxit eum extra vicum: et exspuens in oculos ejus impositis manibus suis, interrogavit eum si quid videret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 24, 'Et aspiciens, ait: Video homines velut arbores ambulantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 25, 'Deinde iterum imposuit manus super oculos ejus: et cœpit videre: et restitutus est ita ut clare videret omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 26, 'Et misit illum in domum suam, dicens: Vade in domum tuam: et si in vicum introieris, nemini dixeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 27, 'Et egressus est Jesus, et discipuli ejus in castella Cæsareæ Philippi: et in via interrogabat discipulos suos, dicens eis: Quem me dicunt esse homines?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 28, 'Qui responderunt illi, dicentes: Joannem Baptistam, alii Eliam, alii vero quasi unum de prophetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 29, 'Tunc dicit illis: Vos vero quem me esse dicitis? Respondens Petrus, ait ei: Tu es Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 30, 'Et comminatus est eis, ne cui dicerent de illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 31, 'Et cœpit docere eos quoniam oportet Filium hominis pati multa, et reprobari a senioribus, et a summis sacerdotibus et scribis, et occidi: et post tres dies resurgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 32, 'Et palam verbum loquebatur. Et apprehendens eum Petrus, cœpit increpare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 33, 'Qui conversus, et videns discipulos suos, comminatus est Petro, dicens: Vade retro me Satana, quoniam non sapis quæ Dei sunt, sed quæ sunt hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 34, 'Et convocata turba cum discipulis suis, dixit eis: Si quis vult me sequi, deneget semetipsum: et tollat crucem suam, et sequatur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 35, 'Qui enim voluerit animam suam salvam facere, perdet eam: qui autem perdiderit animam suam propter me, et Evangelium, salvam faciet eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 36, 'Quid enim proderit homini, si lucretur mundum totum et detrimentum animæ suæ faciat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 37, 'Aut quid dabit homo commutationis pro anima sua?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 38, 'Qui enim me confusus fuerit, et verba mea in generatione ista adultera et peccatrice, et Filius hominis confundetur eum, cum venerit in gloria Patris sui cum angelis sanctis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 8, 39, 'Et dicebat illis: Amen dico vobis, quia sunt quidam de hic stantibus, qui non gustabunt mortem donec videant regnum Dei veniens in virtute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 1, 'Et post dies sex assumit Jesus Petrum, et Jacobum, et Joannem, et ducit illos in montem excelsum seorsum solos, et transfiguratus est coram ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 2, 'Et vestimenta ejus facta sunt splendentia, et candida nimis velut nix, qualia fullo non potest super terram candida facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 3, 'Et apparuit illis Elias cum Moyse: et erant loquentes cum Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 4, 'Et respondens Petrus, ait Jesu: Rabbi, bonum est nos hic esse: et faciamus tria tabernacula, tibi unum, et Moysi unum, et Eliæ unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 5, 'Non enim sciebat quid diceret: erant enim timore exterriti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 6, 'Et facta est nubes obumbrans eos: et venit vox de nube, dicens: Hic est Filius meus carissimus: audite illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 7, 'Et statim circumspicientes, neminem amplius viderunt, nisi Jesum tantum secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 8, 'Et descendentibus illis de monte, præcepit illis ne cuiquam quæ vidissent, narrarent: nisi cum Filius hominis a mortuis resurrexerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 9, 'Et verbum continuerunt apud se: conquirentes quid esset, cum a mortuis resurrexerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 10, 'Et interrogabant eum, dicentes: Quid ergo dicunt pharisæi et scribæ, quia Eliam oportet venire primum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 11, 'Qui respondens, ait illis: Elias cum venerit primo, restituet omnia: et quomodo scriptum est in Filium hominis, ut multa patiatur et contemnatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 12, 'Sed dico vobis quia et Elias venit (et fecerunt illi quæcumque voluerunt) sicut scriptum est de eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 13, 'Et veniens ad discipulos suos, vidit turbam magnam circa eos, et scribas conquirentes cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 14, 'Et confestim omnis populus videns Jesum, stupefactus est, et expaverunt, et accurrentes salutabant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 15, 'Et interrogavit eos: Quid inter vos conquiritis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 16, 'Et respondens unus de turba, dixit: Magister, attuli filium meum ad te habentem spiritum mutum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 17, 'qui ubicumque eum apprehenderit, allidit illum, et spumat, et stridet dentibus, et arescit: et dixi discipulis tuis ut ejicerent illum, et non potuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 18, 'Qui respondens eis, dixit: O generatio incredula, quamdiu apud vos ero? quamdiu vos patiar? afferte illum ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 19, 'Et attulerunt eum. Et cum vidisset eum, statim spiritus conturbavit illum: et elisus in terram, volutabatur spumans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 20, 'Et interrogavit patrem ejus: Quantum temporis est ex quo ei hoc accidit? At ille ait: Ab infantia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 21, 'et frequenter eum in ignem, et in aquas misit ut eum perderet: sed si quid potes, adjuva nos, misertus nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 22, 'Jesus autem ait illi: Si potes credere, omnia possibilia sunt credenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 23, 'Et continuo exclamans pater pueri, cum lacrimis aiebat: Credo, Domine; adjuva incredulitatem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 24, 'Et cum videret Jesus concurrentem turbam, comminatus est spiritui immundo, dicens illi: Surde et mute spiritus, ego præcipio tibi, exi ab eo: et amplius ne introëas in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 25, 'Et exclamans, et multum discerpens eum, exiit ab eo, et factus est sicut mortuus, ita ut multi dicerent: Quia mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 26, 'Jesus autem tenens manum ejus elevavit eum, et surrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 27, 'Et cum introisset in domum, discipuli ejus secreto interrogabant eum: Quare nos non potuimus ejicere eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 28, 'Et dixit illis: Hoc genus in nullo potest exire, nisi in oratione et jejunio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 29, 'Et inde profecti prætergrediebantur Galilæam: nec volebat quemquam scire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 30, 'Docebat autem discipulos suos, et dicebat illis: Quoniam Filius hominis tradetur in manus hominum, et occident eum, et occisus tertia die resurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 31, 'At illi ignorabant verbum: et timebant interrogare eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 32, 'Et venerunt Capharnaum. Qui cum domi essent, interrogabat eos: Quid in via tractabatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 33, 'At illi tacebant: siquidem in via inter se disputaverunt: quis eorum major esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 34, 'Et residens vocavit duodecim, et ait illis: Si quis vult primus esse, erit omnium novissimus, et omnium minister.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 35, 'Et accipiens puerum, statuit eum in medio eorum: quem cum complexus esset, ait illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 36, 'Quisquis unum ex hujusmodi pueris receperit in nomine meo, me recipit: et quicumque me susceperit, non me suscipit, sed eum qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 37, 'Respondit illi Joannes, dicens: Magister, vidimus quemdam in nomine tuo ejicientem dæmonia, qui non sequitur nos, et prohibuimus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 38, 'Jesus autem ait: Nolite prohibere eum: nemo est enim qui faciat virtutem in nomine meo, et possit cito male loqui de me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 39, 'qui enim non est adversum vos, pro vobis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 40, 'Quisquis enim potum dederit vobis calicem aquæ in nomine meo, quia Christi estis: amen dico vobis, non perdet mercedem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 41, 'Et quisquis scandalizaverit unum ex his pusillis credentibus in me: bonum est ei magis si circumdaretur mola asinaria collo ejus, et in mare mitteretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 42, 'Et si scandalizaverit te manus tua, abscide illam: bonum est tibi debilem introire in vitam, quam duas manus habentem ire in gehennam, in ignem inextinguibilem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 43, 'ubi vermis eorum non moritur, et ignis non extinguitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 44, 'Et si pes tuus te scandalizat, amputa illum: bonum est tibi claudum introire in vitam æternam, quam duos pedes habentem mitti in gehennam ignis inextinguibilis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 45, 'ubi vermis eorum non moritur, et ignis non extinguitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 46, 'Quod si oculus tuus scandalizat te, ejice eum: bonum est tibi luscum introire in regnum Dei, quam duos oculos habentem mitti in gehennam ignis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 47, 'ubi vermis eorum non moritur, et ignis non extinguitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 48, 'Omnis enim igne salietur, et omnis victima sale salietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 9, 49, 'Bonum est sal: quod si sal insulsum fuerit, in quo illud condietis? Habete in vobis sal, et pacem habete inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 1, 'Et inde exsurgens venit in fines Judææ ultra Jordanem: et conveniunt iterum turbæ ad eum: et sicut consueverat, iterum docebat illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 2, 'Et accedentes pharisæi interrogabant eum: Si licet viro uxorem dimittere: tentantes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 3, 'At ille respondens, dixit eis: Quid vobis præcepit Moyses?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 4, 'Qui dixerunt: Moyses permisit libellum repudii scribere, et dimittere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 5, 'Quibus respondens Jesus, ait: Ad duritiam cordis vestri scripsit vobis præceptum istud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 6, 'ab initio autem creaturæ masculum et feminam fecit eos Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 7, 'Propter hoc relinquet homo patrem suum et matrem, et adhærebit ad uxorem suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 8, 'et erunt duo in carne una. Itaque jam non sunt duo, sed una caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 9, 'Quod ergo Deus conjunxit, homo non separet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 10, 'Et in domo iterum discipuli ejus de eodem interrogaverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 11, 'Et ait illis: Quicumque dimiserit uxorem suam, et aliam duxerit, adulterium committit super eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 12, 'Et si uxor dimiserit virum suum, et alii nupserit, mœchatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 13, 'Et offerebant illi parvulos ut tangeret illos. Discipuli autem comminabantur offerentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 14, 'Quos cum videret Jesus, indigne tulit, et ait illis: Sinite parvulos venire ad me, et ne prohibueritis eos: talium enim est regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 15, 'Amen dico vobis: Quisquis non receperit regnum Dei velut parvulus, non intrabit in illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 16, 'Et complexans eos, et imponens manus super illos, benedicebat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 17, 'Et cum egressus esset in viam, procurrens quidam genu flexo ante eum, rogabat eum: Magister bone, quid faciam ut vitam æternam percipiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 18, 'Jesus autem dixit ei: Quid me dicis bonum? nemo bonus, nisi unus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 19, 'Præcepta nosti: ne adulteres, ne occidas, ne fureris, ne falsum testimonium dixeris, ne fraudem feceris, honora patrem tuum et matrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 20, 'At ille respondens, ait illi: Magister, hæc omnia observavi a juventute mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 21, 'Jesus autem intuitus eum, dilexit eum, et dixit ei: Unum tibi deest: vade, quæcumque habes vende, et da pauperibus, et habebis thesaurum in cælo: et veni, sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 22, 'Qui contristatus in verbo, abiit mœrens: erat enim habens multas possessiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 23, 'Et circumspiciens Jesus, ait discipulis suis: Quam difficile qui pecunias habent, in regnum Dei introibunt!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 24, 'Discipuli autem obstupescebant in verbis ejus. At Jesus rursus respondens ait illis: Filioli, quam difficile est, confidentes in pecuniis, in regnum Dei introire!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 25, 'Facilius est camelum per foramen acus transire, quam divitem intrare in regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 26, 'Qui magis admirabantur, dicentes ad semetipsos: Et quis potest salvus fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 27, 'Et intuens illos Jesus, ait: Apud homines impossibile est, sed non apud Deum: omnia enim possibilia sunt apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 28, 'Et cœpit ei Petrus dicere: Ecce nos dimisimus omnia, et secuti sumus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 29, 'Respondens Jesus, ait: Amen dico vobis: Nemo est qui reliquerit domum, aut fratres, aut sorores, aut patrem, aut matrem, aut filios, aut agros propter me et propter Evangelium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 30, 'qui non accipiat centies tantum, nunc in tempore hoc: domos, et fratres, et sorores, et matres, et filios, et agros, cum persecutionibus, et in sæculo futuro vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 31, 'Multi autem erunt primi novissimi, et novissimi primi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 32, 'Erant autem in via ascendentes Jerosolymam: et præcedebat illos Jesus, et stupebant: et sequentes timebant. Et assumens iterum duodecim, cœpit illis dicere quæ essent ei eventura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 33, 'Quia ecce ascendimus Jerosolymam, et Filius hominis tradetur principibus sacerdotum, et scribis, et senioribus, et damnabunt eum morte, et tradent eum gentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 34, 'et illudent ei, et conspuent eum, et flagellabunt eum, et interficient eum: et tertia die resurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 35, 'Et accedunt ad eum Jacobus et Joannes filii Zebedæi, dicentes: Magister, volumus ut quodcumque petierimus, facias nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 36, 'At ille dixit eis: Quid vultis ut faciam vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 37, 'Et dixerunt: Da nobis ut unus ad dexteram tuam, et alius ad sinistram tuam sedeamus in gloria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 38, 'Jesus autem ait eis: Nescitis quid petatis: potestis bibere calicem, quem ego bibo, aut baptismo, quo ego baptizor, baptizari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 39, 'At illi dixerunt ei: Possumus. Jesus autem ait eis: Calicem quidem, quem ego bibo, bibetis; et baptismo, quo ego baptizor, baptizabimini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 40, 'sedere autem ad dexteram meam, vel ad sinistram, non est meum dare vobis, sed quibus paratum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 41, 'Et audientes decem, cœperunt indignari de Jacobo et Joanne.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 42, 'Jesus autem vocans eos, ait illis: Scitis quia hi, qui videntur principari gentibus, dominantur eis: et principes eorum potestatem habent ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 43, 'Non ita est autem in vobis, sed quicumque voluerit fieri major, erit vester minister:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 44, 'et quicumque voluerit in vobis primus esse, erit omnium servus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 45, 'Nam et Filius hominis non venit ut ministraretur ei, sed ut ministraret, et daret animam suam redemptionem pro multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 46, 'Et veniunt Jericho: et proficiscente eo de Jericho, et discipulis ejus, et plurima multitudine, filius Timæi Bartimæus cæcus, sedebat juxta viam mendicans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 47, 'Qui cum audisset quia Jesus Nazarenus est, cœpit clamare, et dicere: Jesu fili David, miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 48, 'Et comminabantur ei multi ut taceret. At ille multo magis clamabat: Fili David, miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 49, 'Et stans Jesus præcepit illum vocari. Et vocant cæcum, dicentes ei: Animæquior esto: surge, vocat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 50, 'Qui projecto vestimento suo exiliens, venit ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 51, 'Et respondens Jesus dixit illi: Quid tibi vis faciam? Cæcus autem dixit ei: Rabboni, ut videam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 10, 52, 'Jesus autem ait illi: Vade, fides tua te salvum fecit. Et confestim vidit, et sequebatur eum in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 1, 'Et cum appropinquarent Jerosolymæ et Bethaniæ ad montem Olivarum, mittit duos ex discipulis suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 2, 'et ait illis: Ite in castellum, quod contra vos est, et statim introëuntes illuc, invenietis pullum ligatum, super quem nemo adhuc hominum sedit: solvite illum, et adducite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 3, 'Et si quis vobis dixerit: Quid facitis? dicite, quia Domino necessarius est: et continuo illum dimittet huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 4, 'Et abeuntes invenerunt pullum ligatum ante januam foris in bivio: et solvunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 5, 'Et quidam de illic stantibus dicebant illis: Quid facitis solventes pullum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 6, 'Qui dixerunt eis sicut præceperat illis Jesus, et dimiserunt eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 7, 'Et duxerunt pullum ad Jesum: et imponunt illi vestimenta sua, et sedit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 8, 'Multi autem vestimenta sua straverunt in via: alii autem frondes cædebant de arboribus, et sternebant in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 9, 'Et qui præibant, et qui sequebantur, clamabant, dicentes: Hosanna: benedictus qui venit in nomine Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 10, 'benedictum quod venit regnum patris nostri David: hosanna in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 11, 'Et introivit Jerosolymam in templum: et circumspectis omnibus, cum jam vespera esset hora, exiit in Bethaniam cum duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 12, 'Et alia die cum exirent a Bethania, esuriit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 13, 'Cumque vidisset a longe ficum habentem folia, venit si quid forte inveniret in ea: et cum venisset ad eam, nihil invenit præter folia: non enim erat tempus ficorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 14, 'Et respondens dixit ei: Jam non amplius in æternum ex te fructum quisquam manducet. Et audiebant discipuli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 15, 'Et veniunt in Jerosolymam. Et cum introisset in templum, cœpit ejicere vendentes et ementes in templo: et mensas numulariorum, et cathedras vendentium columbas evertit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 16, 'et non sinebat ut quisquam transferret vas per templum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 17, 'et docebat, dicens eis: Nonne scriptum est: Quia domus mea, domus orationis vocabitur omnibus gentibus? vos autem fecistis eam speluncam latronum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 18, 'Quo audito principes sacerdotum et scribæ, quærebant quomodo eum perderent: timebant enim eum, quoniam universa turba admirabatur super doctrina ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 19, 'Et cum vespera facta esset, egrediebatur de civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 20, 'Et cum mane transirent, viderunt ficum aridam factam a radicibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 21, 'Et recordatus Petrus, dixit ei: Rabbi, ecce ficus, cui maledixisti, aruit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 22, 'Et respondens Jesus ait illis: Habete fidem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 23, 'Amen dico vobis, quia quicumque dixerit huic monti: Tollere, et mittere in mare, et non hæsitaverit in corde suo, sed crediderit, quia quodcumque dixerit fiat, fiet ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 24, 'Propterea dico vobis, omnia quæcumque orantes petitis, credite quia accipietis, et evenient vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 25, 'Et cum stabitis ad orandum, dimittite si quid habetis adversus aliquem: ut et Pater vester, qui in cælis est, dimittat vobis peccata vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 26, 'Quod si vos non dimiseritis: nec Pater vester, qui in cælis est, dimittet vobis peccata vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 27, 'Et veniunt rursus Jerosolymam. Et cum ambularet in templo, accedunt ad eum summi sacerdotes, et scribæ, et seniores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 28, 'et dicunt ei: In qua potestate hæc facis? et quis dedit tibi hanc potestatem ut ista facias?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 29, 'Jesus autem respondens, ait illis: Interrogabo vos et ego unum verbum, et respondete mihi: et dicam vobis in qua potestate hæc faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 30, 'Baptismus Joannis, de cælo erat, an ex hominibus? Respondete mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 31, 'At illi cogitabant secum, dicentes: Si dixerimus: De cælo, dicet: Quare ergo non credidistis ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 32, 'Si dixerimus: Ex hominibus, timemus populum: omnes enim habebant Joannem quia vere propheta esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 11, 33, 'Et respondentes dicunt Jesu: Nescimus. Et respondens Jesus ait illis: Neque ego dico vobis in qua potestate hæc faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 1, 'Et cœpit illis in parabolis loqui: Vineam pastinavit homo, et circumdedit sepem, et fodit lacum, et ædificavit turrim, et locavit eam agricolis, et peregre profectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 2, 'Et misit ad agricolas in tempore servum ut ab agricolis acciperet de fructu vineæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 3, 'Qui apprehensum eum ceciderunt, et dimiserunt vacuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 4, 'Et iterum misit ad illos alium servum: et illum in capite vulneraverunt, et contumeliis affecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 5, 'Et rursum alium misit, et illum occiderunt: et plures alios: quosdam cædentes, alios vero occidentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 6, 'Adhuc ergo unum habens filium carissimum, et illum misit ad eos novissimum, dicens: Quia reverebuntur filium meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 7, 'Coloni autem dixerunt ad invicem: Hic est hæres: venite, occidamus eum: et nostra erit hæreditas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 8, 'Et apprehendentes eum, occiderunt: et ejecerunt extra vineam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 9, 'Quid ergo faciet dominus vineæ? Veniet, et perdet colonos, et dabit vineam aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 10, 'Nec scripturam hanc legistis: Lapidem quem reprobaverunt ædificantes, hic factus est in caput anguli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 11, 'a Domino factum est istud, et est mirabile in oculis nostris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 12, 'Et quærebant eum tenere: et timuerunt turbam: cognoverunt enim quoniam ad eos parabolam hanc dixerit. Et relicto eo abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 13, 'Et mittunt ad eum quosdam ex pharisæis, et herodianis, ut eum caperent in verbo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 14, 'Qui venientes dicunt ei: Magister, scimus quia verax es, et non curas quemquam: nec enim vides in faciem hominum, sed in veritate viam Dei doces. Licet dari tributum Cæsari, an non dabimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 15, 'Qui sciens versutiam illorum, ait illis: Quid me tentatis? afferte mihi denarium ut videam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 16, 'At illi attulerunt ei. Et ait illis: Cujus est imago hæc, et inscriptio? Dicunt ei: Cæsaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 17, 'Respondens autem Jesus dixit illis: Reddite igitur quæ sunt Cæsaris, Cæsari: et quæ sunt Dei, Deo. Et mirabantur super eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 18, 'Et venerunt ad eum sadducæi, qui dicunt resurrectionem non esse: et interrogabant eum, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 19, 'Magister, Moyses nobis scripsit, ut si cujus frater mortuus fuerit, et dimiserit uxorem, et filios non reliquerit, accipiat frater ejus uxorem ipsius, et resuscitet semen fratri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 20, 'Septem ergo fratres erant: et primus accepit uxorem, et mortuus est non relicto semine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 21, 'Et secundus accepit eam, et mortuus est: et nec iste reliquit semen. Et tertius similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 22, 'Et acceperunt eam similiter septem: et non reliquerunt semen. Novissima omnium defuncta est et mulier.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 23, 'In resurrectione ergo cum resurrexerint, cujus de his erit uxor? septem enim habuerunt eam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 24, 'Et respondens Jesus, ait illis: Nonne ideo erratis, non scientes Scripturas, neque virtutem Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 25, 'Cum enim a mortuis resurrexerint, neque nubent, neque nubentur, sed sunt sicut angeli in cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 26, 'De mortuis autem quod resurgant, non legistis in libro Moysi, super rubum, quomodo dixerit illi Deus, inquiens: Ego sum Deus Abraham, et Deus Isaac, et Deus Jacob?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 27, 'Non est Deus mortuorum, sed vivorum. Vos ergo multum erratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 28, 'Et accessit unus de scribis, qui audierat illos conquirentes, et videns quoniam bene illis responderit, interrogavit eum quod esset primum omnium mandatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 29, 'Jesus autem respondit ei: Quia primum omnium mandatum est: Audi Israël, Dominus Deus tuus, Deus unus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 30, 'et diliges Dominum Deum tuum ex toto corde tuo, et ex tota anima tua, et ex tota mente tua, et ex tota virtute tua. Hoc est primum mandatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 31, 'Secundum autem simile est illi: Diliges proximum tuum tamquam teipsum. Majus horum aliud mandatum non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 32, 'Et ait illi scriba: Bene, Magister, in veritate dixisti, quia unus est Deus, et non est alius præter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 33, 'Et ut diligatur ex toto corde, et ex toto intellectu, et ex tota anima, et ex tota fortitudine, et diligere proximum tamquam seipsum, majus est omnibus holocautomatibus, et sacrificiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 34, 'Jesus autem videns quod sapienter respondisset, dixit illi: Non es longe a regno Dei. Et nemo jam audebat eum interrogare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 35, 'Et respondens Jesus dicebat, docens in templo: Quomodo dicunt scribæ Christum filium esse David?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 36, 'Ipse enim David dicit in Spiritu Sancto: Dixit Dominus Domino meo: Sede a dextris meis, donec ponam inimicos tuos scabellum pedum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 37, 'Ipse ergo David dicit eum Dominum, et unde est filius ejus? Et multa turba eum libenter audivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 38, 'Et dicebat eis in doctrina sua: Cavete a scribis, qui volunt in stolis ambulare, et salutari in foro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 39, 'et in primis cathedris sedere in synagogis, et primos discubitus in cœnis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 40, 'qui devorant domos viduarum sub obtentu prolixæ orationis: hi accipient prolixius judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 41, 'Et sedens Jesus contra gazophylacium, aspiciebat quomodo turba jactaret æs in gazophylacium, et multi divites jactabant multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 42, 'Cum venisset autem vidua una pauper, misit duo minuta, quod est quadrans,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 43, 'et convocans discipulos suos, ait illis: Amen dico vobis, quoniam vidua hæc pauper plus omnibus misit, qui miserunt in gazophylacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 12, 44, 'Omnes enim ex eo, quod abundabat illis, miserunt: hæc vero de penuria sua omnia quæ habuit misit totum victum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 1, 'Et cum egrederetur de templo, ait illi unus ex discipulis suis: Magister, aspice quales lapides, et quales structuræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 2, 'Et respondens Jesus, ait illi: Vides has omnes magnas ædificationes? Non relinquetur lapis super lapidem, qui non destruatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 3, 'Et cum sederet in monte Olivarum contra templum, interrogabant eum separatim Petrus, et Jacobus, et Joannes, et Andreas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 4, 'Dic nobis, quando ista fient? et quod signum erit, quando hæc omnia incipient consummari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 5, 'Et respondens Jesus cœpit dicere illis: Videte ne quis vos seducat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 6, 'multi enim venient in nomine meo, dicentes quia ego sum: et multos seducent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 7, 'Cum audieritis autem bella, et opiniones bellorum, ne timueritis: oportet enim hæc fieri: sed nondum finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 8, 'Exsurget enim gens contra gentem, et regnum super regnum, et erunt terræmotus per loca, et fames. Initium dolorum hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 9, 'Videte autem vosmetipsos. Tradent enim vos in consiliis, et in synagogis vapulabitis, et ante præsides et reges stabitis propter me, in testimonium illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 10, 'Et in omnes gentes primum oportet prædicari Evangelium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 11, 'Et cum duxerint vos tradentes, nolite præcogitare quid loquamini: sed quod datum vobis fuerit in illa hora, id loquimini: non enim vos estis loquentes, sed Spiritus Sanctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 12, 'Tradet autem frater fratrem in mortem, et pater filium: et consurgent filii in parentes, et morte afficient eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 13, 'Et eritis odio omnibus propter nomen meum. Qui autem sustinuerit in finem, hic salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 14, 'Cum autem videritis abominationem desolationis stantem, ubi non debet, qui legit, intelligat: tunc qui in Judæa sunt, fugiant in montes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 15, 'et qui super tectum, ne descendat in domum, nec introëat ut tollat quid de domo sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 16, 'et qui in agro erit, non revertatur retro tollere vestimentum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 17, 'Væ autem prægnantibus et nutrientibus in illis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 18, 'Orate vero ut hieme non fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 19, 'Erunt enim dies illi tribulationes tales quales non fuerunt ab initio creaturæ, quam condidit Deus usque nunc, neque fient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 20, 'Et nisi breviasset Dominus dies, non fuisset salva omnis caro: sed propter electos, quos elegit, breviavit dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 21, 'Et tunc si quis vobis dixerit: Ecce hic est Christus, ecce illic, ne credideritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 22, 'Exsurgent enim pseudochristi et pseudoprophetæ, et dabunt signa et portenta ad seducendos, si fieri potest, etiam electos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 23, 'Vos ergo videte: ecce prædixi vobis omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 24, 'Sed in illis diebus, post tribulationem illam, sol contenebrabitur, et luna non dabit splendorem suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 25, 'et stellæ cæli erunt decidentes, et virtutes, quæ in cælis sunt, movebuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 26, 'Et tunc videbunt Filium hominis venientem in nubibus cum virtute multa et gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 27, 'Et tunc mittet angelos suos, et congregabit electos suos a quatuor ventis, a summo terræ usque ad summum cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 28, 'A ficu autem discite parabolam. Cum jam ramus ejus tener fuerit, et nata fuerint folia, cognoscitis quia in proximo sit æstas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 29, 'sic et vos cum videritis hæc fieri, scitote quod in proximo sit, in ostiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 30, 'Amen dico vobis, quoniam non transibit generatio hæc, donec omnia ista fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 31, 'Cælum et terra transibunt, verba autem mea non transibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 32, 'De die autem illo vel hora nemo scit, neque angeli in cælo, neque Filius, nisi Pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 33, 'Videte, vigilate, et orate: nescitis enim quando tempus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 34, 'Sicut homo qui peregre profectus reliquit domum suam, et dedit servis suis potestatem cujusque operis, et janitori præcepit ut vigilet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 35, 'vigilate ergo (nescitis enim quando dominus domus veniat: sero, an media nocte, an galli cantu, an mane),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 36, 'ne, cum venerit repente, inveniat vos dormientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 13, 37, 'Quod autem vobis dico, omnibus dico: Vigilate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 1, 'Erat autem Pascha et azyma post biduum: et quærebant summi sacerdotes et scribæ quomodo eum dolo tenerent, et occiderent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 2, 'Dicebant autem: Non in die festo, ne forte tumultus fieret in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 3, 'Et cum esset Bethaniæ in domo Simonis leprosi, et recumberet, venit mulier habens alabastrum unguenti nardi spicati pretiosi: et fracto alabastro, effudit super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 4, 'Erant autem quidam indigne ferentes intra semetipsos, et dicentes: Ut quid perditio ista unguenti facta est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 5, 'poterat enim unguentum istud venundari plus quam trecentis denariis, et dari pauperibus. Et fremebant in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 6, 'Jesus autem dixit: Sinite eam, quid illi molesti estis? Bonum opus operata est in me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 7, 'semper enim pauperes habetis vobiscum: et cum volueritis, potestis illis benefacere: me autem non semper habetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 8, 'Quod habuit hæc, fecit: prævenit ungere corpus meum in sepulturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 9, 'Amen dico vobis: Ubicumque prædicatum fuerit Evangelium istud in universo mundo, et quod fecit hæc, narrabitur in memoriam ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 10, 'Et Judas Iscariotes, unus de duodecim, abiit ad summos sacerdotes, ut proderet eum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 11, 'Qui audientes gavisi sunt: et promiserunt ei pecuniam se daturos. Et quærebat quomodo illum opportune traderet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 12, 'Et primo die azymorum quando Pascha immolabant, dicunt ei discipuli: Quo vis eamus, et paremus tibi ut manduces Pascha?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 13, 'Et mittit duos ex discipulis suis, et dicit eis: Ite in civitatem, et occurret vobis homo lagenam aquæ bajulans: sequimini eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 14, 'et quocumque introierit, dicite domino domus, quia magister dicit: Ubi est refectio mea, ubi Pascha cum discipulis meis manducem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 15, 'Et ipse vobis demonstrabit cœnaculum grande, stratum: et illic parate nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 16, 'Et abierunt discipuli ejus, et venerunt in civitatem: et invenerunt sicut dixerat illis, et paraverunt Pascha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 17, 'Vespere autem facto, venit cum duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 18, 'Et discumbentibus eis, et manducantibus, ait Jesus: Amen dico vobis, quia unus ex vobis tradet me, qui manducat mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 19, 'At illi cœperunt contristari, et dicere ei singulatim: Numquid ego?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 20, 'Qui ait illis: Unus ex duodecim, qui intingit mecum manum in catino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 21, 'Et Filius quidem hominis vadit sicut scriptum est de eo: væ autem homini illi per quem Filius hominis tradetur! bonum erat ei, si non esset natus homo ille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 22, 'Et manducantibus illis, accepit Jesus panem: et benedicens fregit, et dedit eis, et ait: Sumite, hoc est corpus meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 23, 'Et accepto calice, gratias agens dedit eis: et biberunt ex illo omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 24, 'Et ait illis: Hic est sanguis meus novi testamenti, qui pro multis effundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 25, 'Amen dico vobis, quia jam non bibam de hoc genimine vitis usque in diem illum, cum illud bibam novum in regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 26, 'Et hymno dicto exierunt in montem Olivarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 27, 'Et ait eis Jesus: Omnes scandalizabimini in me in nocte ista: quia scriptum est: Percutiam pastorem, et dispergentur oves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 28, 'Sed postquam resurrexero, præcedam vos in Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 29, 'Petrus autem ait illi: Et si omnes scandalizati fuerint in te, sed non ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 30, 'Et ait illi Jesus: Amen dico tibi, quia tu hodie in nocte hac, priusquam gallus vocem bis dederit, ter me es negaturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 31, 'At ille amplius loquebatur: Et si oportuerit me simul commori tibi, non te negabo. Similiter autem et omnes dicebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 32, 'Et veniunt in prædium, cui nomen Gethsemani. Et ait discipulis suis: Sedete hic donec orem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 33, 'Et assumit Petrum, et Jacobum, et Joannem secum: et cœpit pavere et tædere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 34, 'Et ait illis: Tristis est anima mea usque ad mortem: sustinete hic, et vigilate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 35, 'Et cum processisset paululum, procidit super terram, et orabat ut, si fieri posset, transiret ab eo hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 36, 'Et dixit: Abba pater, omnia tibi possibilia sunt: transfer calicem hunc a me: sed non quod ego volo, sed quod tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 37, 'Et venit, et invenit eos dormientes. Et ait Petro: Simon, dormis? non potuisti una hora vigilare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 38, 'vigilate et orate, ut non intretis in tentationem. Spiritus quidem promptus est, caro vero infirma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 39, 'Et iterum abiens oravit, eumdem sermonem dicens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 40, 'Et reversus, denuo invenit eos dormientes (erant enim oculi eorum gravati), et ignorabant quid responderent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 41, 'Et venit tertio, et ait illis: Dormite jam, et requiescite. Sufficit: venit hora: ecce Filius hominis tradetur in manus peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 42, 'Surgite, eamus: ecce qui me tradet, prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 43, 'Et, adhuc eo loquente, venit Judas Iscariotes unus de duodecim, et cum eo turba multa cum gladiis et lignis, a summis sacerdotibus, et scribis, et senioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 44, 'Dederat autem traditor ejus signum eis, dicens: Quemcumque osculatus fuero, ipse est, tenete eum, et ducite caute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 45, 'Et cum venisset, statim accedens ad eum, ait: Ave Rabbi: et osculatus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 46, 'At illi manus injecerunt in eum, et tenuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 47, 'Unus autem quidam de circumstantibus educens gladium, percussit servum summi sacerdotis, et amputavit illi auriculam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 48, 'Et respondens Jesus, ait illis: Tamquam ad latronem existis cum gladiis et lignis comprehendere me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 49, 'quotidie eram apud vos in templo docens, et non me tenuistis. Sed ut impleantur Scripturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 50, 'Tunc discipuli ejus relinquentes eum, omnes fugerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 51, 'Adolescens autem quidam sequebatur eum amictus sindone super nudo: et tenuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 52, 'At ille rejecta sindone, nudus profugit ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 53, 'Et adduxerunt Jesum ad summum sacerdotem: et convenerunt omnes sacerdotes, et scribæ, et seniores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 54, 'Petrus autem a longe secutus est eum usque intro in atrium summi sacerdotis: et sedebat cum ministris ad ignem, et calefaciebat se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 55, 'Summi vero sacerdotes et omne concilium quærebant adversus Jesum testimonium ut eum morti traderent: nec inveniebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 56, 'Multi enim testimonium falsum dicebant adversus eum: et convenientia testimonia non erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 57, 'Et quidam surgentes, falsum testimonium ferebant adversus eum, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 58, 'Quoniam nos audivimus eum dicentem: Ego dissolvam templum hoc manu factum, et per triduum aliud non manu factum ædificabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 59, 'Et non erat conveniens testimonium illorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 60, 'Et exsurgens summus sacerdos in medium, interrogavit Jesum, dicens: Non respondes quidquam ad ea quæ tibi objiciuntur ab his?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 61, 'Ille autem tacebat, et nihil respondit. Rursum summus sacerdos interrogabat eum, et dixit ei: Tu es Christus Filius Dei benedicti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 62, 'Jesus autem dixit illi: Ego sum: et videbitis Filium hominis sedentem a dextris virtutis Dei, et venientem cum nubibus cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 63, 'Summus autem sacerdos scindens vestimenta sua, ait: Quid adhuc desideramus testes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 64, 'Audistis blasphemiam: quid vobis videtur? Qui omnes condemnaverunt eum esse reum mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 65, 'Et cœperunt quidam conspuere eum, et velare faciem ejus, et colaphis eum cædere, et dicere ei: Prophetiza: et ministri alapis eum cædebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 66, 'Et cum esset Petrus in atrio deorsum, venit una ex ancillis summi sacerdotis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 67, 'et cum vidisset Petrum calefacientem se, aspiciens illum, ait: Et tu cum Jesu Nazareno eras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 68, 'At ille negavit, dicens: Neque scio, neque novi quid dicas. Et exiit foras ante atrium, et gallus cantavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 69, 'Rursus autem cum vidisset illum ancilla, cœpit dicere circumstantibus: Quia hic ex illis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 70, 'At ille iterum negavit. Et post pusillum rursus qui astabant, dicebant Petro: Vere ex illis es: nam et Galilæus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 71, 'Ille autem cœpit anathematizare et jurare: Quia nescio hominem istum, quem dicitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 14, 72, 'Et statim gallus iterum cantavit. Et recordatus est Petrus verbi quod dixerat ei Jesus: Priusquam gallus cantet bis, ter me negabis. Et cœpit flere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 1, 'Et confestim mane consilium facientes summi sacerdotes cum senioribus, et scribis, et universo concilio, vincientes Jesum, duxerunt, et tradiderunt Pilato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 2, 'Et interrogavit eum Pilatus: Tu es rex Judæorum? At ille respondens, ait illi: Tu dicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 3, 'Et accusabant eum summi sacerdotes in multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 4, 'Pilatus autem rursum interrogavit eum, dicens: Non respondes quidquam? vide in quantis te accusant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 5, 'Jesus autem amplius nihil respondit, ita ut miraretur Pilatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 6, 'Per diem autem festum solebat dimittere illis unum ex vinctis, quemcumque petissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 7, 'Erat autem qui dicebatur Barrabas, qui cum seditiosis erat vinctus, qui in seditione fecerat homicidium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 8, 'Et cum ascendisset turba, cœpit rogare, sicut semper faciebat illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 9, 'Pilatus autem respondit eis, et dixit: Vultis dimittam vobis regem Judæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 10, 'Sciebat enim quod per invidiam tradidissent eum summi sacerdotes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 11, 'Pontifices autem concitaverunt turbam, ut magis Barabbam dimitteret eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 12, 'Pilatus autem iterum respondens, ait illis: Quid ergo vultis faciam regi Judæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 13, 'At illi iterum clamaverunt: Crucifige eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 14, 'Pilatus vero dicebat illis: Quid enim mali fecit? At illi magis clamabant: Crucifige eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 15, 'Pilatus autem volens populo satisfacere, dimisit illis Barabbam, et tradidit Jesum flagellis cæsum, ut crucifigeretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 16, 'Milites autem duxerunt eum in atrium prætorii, et convocant totam cohortem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 17, 'et induunt eum purpura, et imponunt ei plectentes spineam coronam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 18, 'Et cœperunt salutare eum: Ave rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 19, 'Et percutiebant caput ejus arundine: et conspuebant eum, et ponentes genua, adorabant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 20, 'Et postquam illuserunt ei, exuerunt illum purpura, et induerunt eum vestimentis suis: et educunt illum ut crucifigerent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 21, 'Et angariaverunt prætereuntem quempiam, Simonem Cyrenæum venientem de villa, patrem Alexandri et Rufi, ut tolleret crucem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 22, 'Et perducunt illum in Golgotha locum: quod est interpretatum Calvariæ locus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 23, 'Et dabant ei bibere myrrhatum vinum: et non accepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 24, 'Et crucifigentes eum, diviserunt vestimenta ejus, mittentes sortem super eis, quis quid tolleret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 25, 'Erat autem hora tertia: et crucifixerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 26, 'Et erat titulus causæ ejus inscriptus: Rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 27, 'Et cum eo crucifigunt duos latrones: unum a dextris, et alium a sinistris ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 28, 'Et impleta est Scriptura, quæ dicit: Et cum iniquis reputatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 29, 'Et prætereuntes blasphemabant eum, moventes capita sua, et dicentes: Vah! qui destruis templum Dei, et in tribus diebus reædificas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 30, 'salvum fac temetipsum descendens de cruce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 31, 'Similiter et summi sacerdotes illudentes, ad alterutrum cum scribis dicebant: Alios salvos fecit; seipsum non potest salvum facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 32, 'Christus rex Israël descendat nunc de cruce, ut videamus, et credamus. Et qui cum eo crucifixi erant, convitiabantur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 33, 'Et facta hora sexta, tenebræ factæ sunt per totam terram usque in horam nonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 34, 'Et hora nona exclamavit Jesus voce magna, dicens: Eloi, eloi, lamma sabacthani? quod est interpretatum: Deus meus, Deus meus, ut quid dereliquisti me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 35, 'Et quidam de circumstantibus audientes, dicebant: Ecce Eliam vocat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 36, 'Currens autem unus, et implens spongiam aceto, circumponensque calamo, potum dabat ei, dicens: Sinite, videamus si veniat Elias ad deponendum eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 37, 'Jesus autem emissa voce magna expiravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 38, 'Et velum templi scissum est in duo, a summo usque deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 39, 'Videns autem centurio, qui ex adverso stabat, quia sic clamans expirasset, ait: Vere hic homo Filius Dei erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 40, 'Erant autem et mulieres de longe aspicientes: inter quas erat Maria Magdalene, et Maria Jacobi minoris, et Joseph mater, et Salome:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 41, 'et cum esset in Galilæa, sequebantur eum, et ministrabant ei, et aliæ multæ, quæ simul cum eo ascenderant Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 42, 'Et cum jam sero esset factum (quia erat parasceve, quod est ante sabbatum),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 43, 'venit Joseph ab Arimathæa nobilis decurio, qui et ipse erat exspectans regnum Dei, et audacter introivit ad Pilatum, et petiit corpus Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 44, 'Pilatus autem mirabatur si jam obiisset. Et accersito centurione, interrogavit eum si jam mortuus esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 45, 'Et cum cognovisset a centurione, donavit corpus Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 46, 'Joseph autem mercatus sindonem, et deponens eum involvit sindone, et posuit eum in monumento quod erat excisum de petra, et advolvit lapidem ad ostium monumenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 15, 47, 'Maria autem Magdalene et Maria Joseph aspiciebant ubi poneretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 1, 'Et cum transisset sabbatum, Maria Magdalene, et Maria Jacobi, et Salome emerunt aromata ut venientes ungerent Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 2, 'Et valde mane una sabbatorum, veniunt ad monumentum, orto jam sole.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 3, 'Et dicebant ad invicem: Quis revolvet nobis lapidem ab ostio monumenti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 4, 'Et respicientes viderunt revolutum lapidem. Erat quippe magnus valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 5, 'Et introëuntes in monumentum viderunt juvenem sedentem in dextris, coopertum stola candida, et obstupuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 6, 'Qui dicit illis: Nolite expavescere: Jesum quæritis Nazarenum, crucifixum: surrexit, non est hic, ecce locus ubi posuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 7, 'Sed ite, dicite discipulis ejus, et Petro, quia præcedit vos in Galilæam: ibi eum videbitis, sicut dixit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 8, 'At illæ exeuntes, fugerunt de monumento: invaserat enim eas tremor et pavor: et nemini quidquam dixerunt: timebant enim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 9, 'Surgens autem mane prima sabbati, apparuit primo Mariæ Magdalene, de qua ejecerat septem dæmonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 10, 'Illa vadens nuntiavit his, qui cum eo fuerant, lugentibus et flentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 11, 'Et illi audientes quia viveret, et visus esset ab ea, non crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 12, 'Post hæc autem duobus ex his ambulantibus ostensus est in alia effigie, euntibus in villam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 13, 'et illi euntes nuntiaverunt ceteris: nec illis crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 14, 'Novissime recumbentibus illis undecim apparuit: et exprobravit incredulitatem eorum et duritiam cordis: quia iis, qui viderant eum resurrexisse, non crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 15, 'Et dixit eis: Euntes in mundum universum prædicate Evangelium omni creaturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 16, 'Qui crediderit, et baptizatus fuerit, salvus erit: qui vero non crediderit, condemnabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 17, 'Signa autem eos qui crediderint, hæc sequentur: in nomine meo dæmonia ejicient: linguis loquentur novis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 18, 'serpentes tollent: et si mortiferum quid biberint, non eis nocebit: super ægros manus imponent, et bene habebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 19, 'Et Dominus quidem Jesus postquam locutus est eis, assumptus est in cælum, et sedet a dextris Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 16, 20, 'Illi autem profecti prædicaverunt ubique, Domino cooperante, et sermonem confirmante, sequentibus signis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Quoniam quidem multi conati sunt ordinare narrationem, quæ in nobis completæ sunt, rerum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'sicut tradiderunt nobis, qui ab initio ipsi viderunt, et ministri fuerunt sermonis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'visum est et mihi, assecuto omnia a principio diligenter, ex ordine tibi scribere, optime Theophile,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'ut cognoscas eorum verborum, de quibus eruditus es, veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Fuit in diebus Herodis, regis Judææ, sacerdos quidam nomine Zacharias de vice Abia, et uxor illius de filiabus Aaron, et nomen ejus Elisabeth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Erant autem justi ambo ante Deum, incedentes in omnibus mandatis et justificationibus Domini sine querela.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Et non erat illis filius, eo quod esset Elisabeth sterilis, et ambo processissent in diebus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Factum est autem, cum sacerdotio fungeretur in ordine vicis suæ ante Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'secundum consuetudinem sacerdotii, sorte exiit ut incensum poneret, ingressus in templum Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'et omnis multitudo populi erat orans foris hora incensi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Apparuit autem illi angelus Domini, stans a dextris altaris incensi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Et Zacharias turbatus est videns, et timor irruit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Ait autem ad illum angelus: Ne timeas, Zacharia, quoniam exaudita est deprecatio tua: et uxor tua Elisabeth pariet tibi filium, et vocabis nomen ejus Joannem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'et erit gaudium tibi, et exsultatio, et multi in nativitate ejus gaudebunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'erit enim magnus coram Domino: et vinum et siceram non bibet, et Spiritu Sancto replebitur adhuc ex utero matris suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'et multos filiorum Israël convertet ad Dominum Deum ipsorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'et ipse præcedet ante illum in spiritu et virtute Eliæ: ut convertat corda patrum in filios, et incredulos ad prudentiam justorum, parare Domino plebem perfectam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Et dixit Zacharias ad angelum: Unde hoc sciam? ego enim sum senex, et uxor mea processit in diebus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Et respondens angelus dixit ei: Ego sum Gabriel, qui asto ante Deum: et missus sum loqui ad te, et hæc tibi evangelizare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Et ecce eris tacens, et non poteris loqui usque in diem quo hæc fiant, pro eo quod non credidisti verbis meis, quæ implebuntur in tempore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Et erat plebs exspectans Zachariam: et mirabantur quod tardaret ipse in templo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Egressus autem non poterat loqui ad illos, et cognoverunt quod visionem vidisset in templo. Et ipse erat innuens illis, et permansit mutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Et factum est, ut impleti sunt dies officii ejus, abiit in domum suam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 24, 'post hos autem dies concepit Elisabeth uxor ejus, et occultabat se mensibus quinque, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 25, 'Quia sic fecit mihi Dominus in diebus, quibus respexit auferre opprobrium meum inter homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 26, 'In mense autem sexto, missus est angelus Gabriel a Deo in civitatem Galilææ, cui nomen Nazareth,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 27, 'ad virginem desponsatam viro, cui nomen erat Joseph, de domo David: et nomen virginis Maria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 28, 'Et ingressus angelus ad eam dixit: Ave gratia plena: Dominus tecum: benedicta tu in mulieribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 29, 'Quæ cum audisset, turbata est in sermone ejus, et cogitabat qualis esset ista salutatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 30, 'Et ait angelus ei: Ne timeas, Maria: invenisti enim gratiam apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 31, 'Ecce concipies in utero, et paries filium, et vocabis nomen ejus Jesum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 32, 'hic erit magnus, et Filius Altissimi vocabitur, et dabit illi Dominus Deus sedem David patris ejus: et regnabit in domo Jacob in æternum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 33, 'et regni ejus non erit finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 34, 'Dixit autem Maria ad angelum: Quomodo fiet istud, quoniam virum non cognosco?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 35, 'Et respondens angelus dixit ei: Spiritus Sanctus superveniet in te, et virtus Altissimi obumbrabit tibi. Ideoque et quod nascetur ex te sanctum, vocabitur Filius Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 36, 'Et ecce Elisabeth cognata tua, et ipsa concepit filium in senectute sua: et hic mensis sextus est illi, quæ vocatur sterilis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 37, 'quia non erit impossibile apud Deum omne verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 38, 'Dixit autem Maria: Ecce ancilla Domini: fiat mihi secundum verbum tuum. Et discessit ab illa angelus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 39, 'Exsurgens autem Maria in diebus illis, abiit in montana cum festinatione, in civitatem Juda:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 40, 'et intravit in domum Zachariæ, et salutavit Elisabeth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 41, 'Et factum est, ut audivit salutationem Mariæ Elisabeth, exsultavit infans in utero ejus: et repleta est Spiritu Sancto Elisabeth:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 42, 'et exclamavit voce magna, et dixit: Benedicta tu inter mulieres, et benedictus fructus ventris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 43, 'Et unde hoc mihi, ut veniat mater Domini mei ad me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 44, 'Ecce enim ut facta est vox salutationis tuæ in auribus meis, exsultavit in gaudio infans in utero meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 45, 'Et beata, quæ credidisti, quoniam perficientur ea, quæ dicta sunt tibi a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 46, 'Et ait Maria: Magnificat anima mea Dominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 47, 'et exsultavit spiritus meus in Deo salutari meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 48, 'Quia respexit humilitatem ancillæ suæ: ecce enim ex hoc beatam me dicent omnes generationes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 49, 'quia fecit mihi magna qui potens est: et sanctum nomen ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 50, 'et misericordia ejus a progenie in progenies timentibus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 51, 'Fecit potentiam in brachio suo: dispersit superbos mente cordis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 52, 'Deposuit potentes de sede, et exaltavit humiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 53, 'Esurientes implevit bonis: et divites dimisit inanes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 54, 'Suscepit Israël puerum suum, recordatus misericordiæ suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 55, 'sicut locutus est ad patres nostros, Abraham et semini ejus in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 56, 'Mansit autem Maria cum illa quasi mensibus tribus: et reversa est in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 57, 'Elisabeth autem impletum est tempus pariendi, et peperit filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 58, 'Et audierunt vicini et cognati ejus quia magnificavit Dominus misericordiam suam cum illa, et congratulabantur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 59, 'Et factum est in die octavo, venerunt circumcidere puerum, et vocabant eum nomine patris sui Zachariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 60, 'Et respondens mater ejus, dixit: Nequaquam, sed vocabitur Joannes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 61, 'Et dixerunt ad illam: Quia nemo est in cognatione tua, qui vocetur hoc nomine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 62, 'Innuebant autem patri ejus, quem vellet vocari eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 63, 'Et postulans pugillarem scripsit, dicens: Joannes est nomen ejus. Et mirati sunt universi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 64, 'Apertum est autem illico os ejus, et lingua ejus, et loquebatur benedicens Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 65, 'Et factus est timor super omnes vicinos eorum: et super omnia montana Judææ divulgabantur omnia verba hæc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 66, 'et posuerunt omnes qui audierant in corde suo, dicentes: Quis, putas, puer iste erit? etenim manus Domini erat cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 67, 'Et Zacharias pater ejus repletus est Spiritu Sancto: et prophetavit, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 68, 'Benedictus Dominus Deus Israël, quia visitavit, et fecit redemptionem plebis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 69, 'et erexit cornu salutis nobis in domo David pueri sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 70, 'sicut locutus est per os sanctorum, qui a sæculo sunt, prophetarum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 71, 'salutem ex inimicis nostris, et de manu omnium qui oderunt nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 72, 'ad faciendam misericordiam cum patribus nostris: et memorari testamenti sui sancti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 73, 'jusjurandum, quod juravit ad Abraham patrem nostrum, daturum se nobis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 74, 'ut sine timore, de manu inimicorum nostrorum liberati, serviamus illi');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 75, 'in sanctitate et justitia coram ipso, omnibus diebus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 76, 'Et tu puer, propheta Altissimi vocaberis: præibis enim ante faciem Domini parare vias ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 77, 'ad dandam scientiam salutis plebi ejus in remissionem peccatorum eorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 78, 'per viscera misericordiæ Dei nostri, in quibus visitavit nos, oriens ex alto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 79, 'illuminare his qui in tenebris et in umbra mortis sedent: ad dirigendos pedes nostros in viam pacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 80, 'Puer autem crescebat, et confortabatur spiritu: et erat in desertis usque in diem ostensionis suæ ad Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Factum est autem in diebus illis, exiit edictum a Cæsare Augusto ut describeretur universus orbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Hæc descriptio prima facta est a præside Syriæ Cyrino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'et ibant omnes ut profiterentur singuli in suam civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Ascendit autem et Joseph a Galilæa de civitate Nazareth in Judæam, in civitatem David, quæ vocatur Bethlehem: eo quod esset de domo et familia David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'ut profiteretur cum Maria desponsata sibi uxore prægnante.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Factum est autem, cum essent ibi, impleti sunt dies ut pareret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Et peperit filium suum primogenitum, et pannis eum involvit, et reclinavit eum in præsepio: quia non erat eis locus in diversorio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Et pastores erant in regione eadem vigilantes, et custodientes vigilias noctis super gregem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Et ecce angelus Domini stetit juxta illos, et claritas Dei circumfulsit illos, et timuerunt timore magno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Et dixit illis angelus: Nolite timere: ecce enim evangelizo vobis gaudium magnum, quod erit omni populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'quia natus est vobis hodie Salvator, qui est Christus Dominus, in civitate David.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Et hoc vobis signum: invenietis infantem pannis involutum, et positum in præsepio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Et subito facta est cum angelo multitudo militiæ cælestis laudantium Deum, et dicentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Gloria in altissimis Deo, et in terra pax hominibus bonæ voluntatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Et factum est, ut discesserunt ab eis angeli in cælum: pastores loquebantur ad invicem: Transeamus usque Bethlehem, et videamus hoc verbum, quod factum est, quod Dominus ostendit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Et venerunt festinantes: et invenerunt Mariam, et Joseph, et infantem positum in præsepio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Videntes autem cognoverunt de verbo, quod dictum erat illis de puero hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Et omnes qui audierunt, mirati sunt: et de his quæ dicta erant a pastoribus ad ipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Maria autem conservabat omnia verba hæc, conferens in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Et reversi sunt pastores glorificantes et laudantes Deum in omnibus quæ audierant et viderant, sicut dictum est ad illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Et postquam consummati sunt dies octo, ut circumcideretur puer, vocatum est nomen ejus Jesus, quod vocatum est ab angelo priusquam in utero conciperetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Et postquam impleti sunt dies purgationis ejus secundum legem Moysi, tulerunt illum in Jerusalem, ut sisterent eum Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 23, 'sicut scriptum est in lege Domini: Quia omne masculinum adaperiens vulvam, sanctum Domino vocabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 24, 'et ut darent hostiam secundum quod dictum est in lege Domini, par turturum, aut duos pullos columbarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 25, 'Et ecce homo erat in Jerusalem, cui nomen Simeon, et homo iste justus, et timoratus, exspectans consolationem Israël: et Spiritus Sanctus erat in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 26, 'Et responsum acceperat a Spiritu Sancto, non visurum se mortem, nisi prius videret Christum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 27, 'Et venit in spiritu in templum. Et cum inducerent puerum Jesum parentes ejus, ut facerent secundum consuetudinem legis pro eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 28, 'et ipse accepit eum in ulnas suas: et benedixit Deum, et dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 29, 'Nunc dimittis servum tuum Domine, secundum verbum tuum in pace:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 30, 'quia viderunt oculi mei salutare tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 31, 'quod parasti ante faciem omnium populorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 32, 'lumen ad revelationem gentium, et gloriam plebis tuæ Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 33, 'Et erat pater ejus et mater mirantes super his quæ dicebantur de illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 34, 'Et benedixit illis Simeon, et dixit ad Mariam matrem ejus: Ecce positus est hic in ruinam et in resurrectionem multorum in Israël, et in signum cui contradicetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 35, 'et tuam ipsius animam pertransibit gladius ut revelentur ex multis cordibus cogitationes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 36, 'Et erat Anna prophetissa, filia Phanuel, de tribu Aser: hæc processerat in diebus multis, et vixerat cum viro suo annis septem a virginitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 37, 'Et hæc vidua usque ad annos octoginta quatuor: quæ non discedebat de templo, jejuniis et obsecrationibus serviens nocte ac die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 38, 'Et hæc, ipsa hora superveniens, confitebatur Domino: et loquebatur de illo omnibus, qui exspectabant redemptionem Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 39, 'Et ut perfecerunt omnia secundum legem Domini, reversi sunt in Galilæam in civitatem suam Nazareth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 40, 'Puer autem crescebat, et confortabatur plenus sapientia: et gratia Dei erat in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 41, 'Et ibant parentes ejus per omnes annos in Jerusalem, in die solemni Paschæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 42, 'Et cum factus esset annorum duodecim, ascendentibus illis Jerosolymam secundum consuetudinem diei festi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 43, 'consummatisque diebus, cum redirent, remansit puer Jesus in Jerusalem, et non cognoverunt parentes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 44, 'Existimantes autem illum esse in comitatu, venerunt iter diei, et requirebant eum inter cognatos et notos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 45, 'Et non invenientes, regressi sunt in Jerusalem, requirentes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 46, 'Et factum est, post triduum invenerunt illum in templo sedentem in medio doctorum, audientem illos, et interrogantem eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 47, 'Stupebant autem omnes qui eum audiebant, super prudentia et responsis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 48, 'Et videntes admirati sunt. Et dixit mater ejus ad illum: Fili, quid fecisti nobis sic? ecce pater tuus et ego dolentes quærebamus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 49, 'Et ait ad illos: Quid est quod me quærebatis? nesciebatis quia in his quæ Patris mei sunt, oportet me esse?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 50, 'Et ipsi non intellexerunt verbum quod locutus est ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 51, 'Et descendit cum eis, et venit Nazareth: et erat subditus illis. Et mater ejus conservabat omnia verba hæc in corde suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 52, 'Et Jesus proficiebat sapientia, et ætate, et gratia apud Deum et homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Anno autem quintodecimo imperii Tiberii Cæsaris, procurante Pontio Pilato Judæam, tetrarcha autem Galilææ Herode, Philippo autem fratre ejus tetrarcha Iturææ, et Trachonitidis regionis, et Lysania Abilinæ tetrarcha,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'sub principibus sacerdotum Anna et Caipha: factum est verbum Domini super Joannem, Zachariæ filium, in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Et venit in omnem regionem Jordanis, prædicans baptismum pœnitentiæ in remissionem peccatorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'sicut scriptum est in libro sermonum Isaiæ prophetæ: Vox clamantis in deserto: Parate viam Domini; rectas facite semitas ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'omnis vallis implebitur, et omnis mons, et collis humiliabitur: et erunt prava in directa, et aspera in vias planas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'et videbit omnis caro salutare Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Dicebat ergo ad turbas quæ exibant ut baptizarentur ab ipso: Genimina viperarum, quis ostendit vobis fugere a ventura ira?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Facite ergo fructus dignos pœnitentiæ, et ne cœperitis dicere: Patrem habemus Abraham. Dico enim vobis quia potens est Deus de lapidibus istis suscitare filios Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Jam enim securis ad radicem arborum posita est. Omnis ergo arbor non faciens fructum bonum, excidetur, et in ignem mittetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Et interrogabant eum turbæ, dicentes: Quid ergo faciemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Respondens autem dicebat illis: Qui habet duas tunicas, det non habenti: et qui habet escas, similiter faciat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Venerunt autem et publicani ut baptizarentur, et dixerunt ad illum: Magister, quid faciemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'At ille dixit ad eos: Nihil amplius, quam quod constitutum est vobis, faciatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Interrogabant autem eum et milites, dicentes: Quid faciemus et nos? Et ait illis: Neminem concutiatis, neque calumniam faciatis: et contenti estote stipendiis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Existimante autem populo, et cogitantibus omnibus in cordibus suis de Joanne, ne forte ipse esset Christus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'respondit Joannes, dicens omnibus: Ego quidem aqua baptizo vos: veniet autem fortior me, cujus non sum dignus solvere corrigiam calceamentorum ejus: ipse vos baptizabit in Spiritu Sancto et igni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'cujus ventilabrum in manu ejus, et purgabit aream suam, et congregabit triticum in horreum suum, paleas autem comburet igni inextinguibili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Multa quidem et alia exhortans evangelizabat populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Herodes autem tetrarcha cum corriperetur ab illo de Herodiade uxore fratris sui, et de omnibus malis quæ fecit Herodes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'adjecit et hoc super omnia, et inclusit Joannem in carcere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Factum est autem cum baptizaretur omnis populus, et Jesu baptizato, et orante, apertum est cælum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 22, 'et descendit Spiritus Sanctus corporali specie sicut columba in ipsum: et vox de cælo facta est: Tu es filius meus dilectus, in te complacui mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 23, 'Et ipse Jesus erat incipiens quasi annorum triginta, ut putabatur, filius Joseph, qui fuit Heli, qui fuit Mathat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 24, 'qui fuit Levi, qui fuit Melchi, qui fuit Janne, qui fuit Joseph,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 25, 'qui fuit Mathathiæ, qui fuit Amos, qui fuit Nahum, qui fuit Hesli, qui fuit Nagge,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 26, 'qui fuit Mahath, qui fuit Mathathiæ, qui fuit Semei, qui fuit Joseph, qui fuit Juda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 27, 'qui fuit Joanna, qui fuit Resa, qui fuit Zorobabel, qui fuit Salathiel, qui fuit Neri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 28, 'qui fuit Melchi, qui fuit Addi, qui fuit Cosan, qui fuit Elmadan, qui fuit Her,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 29, 'qui fuit Jesu, qui fuit Eliezer, qui fuit Jorim, qui fuit Mathat, qui fuit Levi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 30, 'qui fuit Simeon, qui fuit Juda, qui fuit Joseph, qui fuit Jona, qui fuit Eliakim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 31, 'qui fuit Melea, qui fuit Menna, qui fuit Mathatha, qui fuit Natham, qui fuit David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 32, 'qui fuit Jesse, qui fuit Obed, qui fuit Booz, qui fuit Salmon, qui fuit Naasson,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 33, 'qui fuit Aminadab, qui fuit Aram, qui fuit Esron, qui fuit Phares, qui fuit Judæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 34, 'qui fuit Jacob, qui fuit Isaac, qui fuit Abrahæ, qui fuit Thare, qui fuit Nachor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 35, 'qui fuit Sarug, qui fuit Ragau, qui fuit Phaleg, qui fuit Heber, qui fuit Sale,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 36, 'qui fuit Cainan, qui fuit Arphaxad, qui fuit Sem, qui fuit Noë, qui fuit Lamech,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 37, 'qui fuit Methusale, qui fuit Henoch, qui fuit Jared, qui fuit Malaleel, qui fuit Cainan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 38, 'qui fuit Henos, qui fuit Seth, qui fuit Adam, qui fuit Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Jesus autem plenus Spiritu Sancto regressus est a Jordane: et agebatur a Spiritu in desertum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'diebus quadraginta, et tentabatur a diabolo. Et nihil manducavit in diebus illis: et consummatis illis esuriit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Dixit autem illi diabolus: Si Filius Dei es, dic lapidi huic ut panis fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Et respondit ad illum Jesus: Scriptum est: Quia non in solo pane vivit homo, sed in omni verbo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Et duxit illum diabolus in montem excelsum, et ostendit illi omnia regna orbis terræ in momento temporis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'et ait illi: Tibi dabo potestatem hanc universam, et gloriam illorum: quia mihi tradita sunt, et cui volo do illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Tu ergo si adoraveris coram me, erunt tua omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Et respondens Jesus, dixit illi: Scriptum est: Dominum Deum tuum adorabis, et illi soli servies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Et duxit illum in Jerusalem, et statuit eum super pinnam templi, et dixit illi: Si Filius Dei es, mitte te hinc deorsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Scriptum est enim quod angelis suis mandavit de te, ut conservent te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'et quia in manibus tollent te, ne forte offendas ad lapidem pedem tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Et respondens Jesus, ait illi: Dictum est: Non tentabis Dominum Deum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Et consummata omni tentatione, diabolus recessit ab illo, usque ad tempus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Et regressus est Jesus in virtute Spiritus in Galilæam, et fama exiit per universam regionem de illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Et ipse docebat in synagogis eorum, et magnificabatur ab omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Et venit Nazareth, ubi erat nutritus, et intravit secundum consuetudinem suam die sabbati in synagogam, et surrexit legere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Et traditus est illi liber Isaiæ prophetæ. Et ut revolvit librum, invenit locum ubi scriptum erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Spiritus Domini super me: propter quod unxit me, evangelizare pauperibus misit me, sanare contritos corde,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'prædicare captivis remissionem, et cæcis visum, dimittere confractos in remissionem, prædicare annum Domini acceptum et diem retributionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Et cum plicuisset librum, reddit ministro, et sedit. Et omnium in synagoga oculi erant intendentes in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Cœpit autem dicere ad illos: Quia hodie impleta est hæc scriptura in auribus vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Et omnes testimonium illi dabant: et mirabantur in verbis gratiæ, quæ procedebant de ore ipsius, et dicebant: Nonne hic est filius Joseph?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Et ait illis: Utique dicetis mihi hanc similitudinem: Medice cura teipsum: quanta audivimus facta in Capharnaum, fac et hic in patria tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Ait autem: Amen dico vobis, quia nemo propheta acceptus est in patria sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'In veritate dico vobis, multæ viduæ erant in diebus Eliæ in Israël, quando clausum est cælum annis tribus et mensibus sex, cum facta esset fames magna in omni terra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'et ad nullam illarum missus est Elias, nisi in Sarepta Sidoniæ, ad mulierem viduam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Et multi leprosi erant in Israël sub Eliseo propheta: et nemo eorum mundatus est nisi Naaman Syrus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Et repleti sunt omnes in synagoga ira, hæc audientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Et surrexerunt, et ejecerunt illum extra civitatem: et duxerunt illum usque ad supercilium montis, super quem civitas illorum erat ædificata, ut præcipitarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Ipse autem transiens per medium illorum, ibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Et descendit in Capharnaum civitatem Galilææ, ibique docebat illos sabbatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Et stupebant in doctrina ejus, quia in potestate erat sermo ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 33, 'Et in synagoga erat homo habens dæmonium immundum, et exclamavit voce magna,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 34, 'dicens: Sine, quid nobis et tibi, Jesu Nazarene? venisti perdere nos? scio te quis sis, Sanctus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 35, 'Et increpavit illum Jesus, dicens: Obmutesce, et exi ab eo. Et cum projecisset illum dæmonium in medium, exiit ab illo, nihilque illum nocuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 36, 'Et factus est pavor in omnibus, et colloquebantur ad invicem, dicentes: Quod est hoc verbum, quia in potestate et virtute imperat immundis spiritibus, et exeunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 37, 'Et divulgabatur fama de illo in omnem locum regionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 38, 'Surgens autem Jesus de synagoga, introivit in domum Simonis. Socrus autem Simonis tenebatur magnis febribus: et rogaverunt illum pro ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 39, 'Et stans super illam imperavit febri: et dimisit illam. Et continuo surgens, ministrabat illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 40, 'Cum autem sol occidisset, omnes qui habebant infirmos variis languoribus, ducebant illos ad eum. At ille singulis manus imponens, curabat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 41, 'Exibant autem dæmonia a multis clamantia, et dicentia: Quia tu es Filius Dei: et increpans non sinebat ea loqui: quia sciebant ipsum esse Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 42, 'Facta autem die egressus ibat in desertum locum, et turbæ requirebant eum, et venerunt usque ad ipsum: et detinebant illum ne discederet ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 43, 'Quibus ille ait: Quia et aliis civitatibus oportet me evangelizare regnum Dei: quia ideo missus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 44, 'Et erat prædicans in synagogis Galilææ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Factum est autem, cum turbæ irruerunt in eum ut audirent verbum Dei, et ipse stabat secus stagnum Genesareth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Et vidit duas naves stantes secus stagnum: piscatores autem descenderant, et lavabant retia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Ascendens autem in unam navim, quæ erat Simonis, rogavit eum a terra reducere pusillum. Et sedens docebat de navicula turbas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Ut cessavit autem loqui, dixit ad Simonem: Duc in altum, et laxate retia vestra in capturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Et respondens Simon, dixit illi: Præceptor, per totam noctem laborantes nihil cepimus: in verbo autem tuo laxabo rete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Et cum hoc fecissent, concluserunt piscium multitudinem copiosam: rumpebatur autem rete eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Et annuerunt sociis, qui erant in alia navi, ut venirent, et adjuvarent eos. Et venerunt, et impleverunt ambas naviculas, ita ut pene mergerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Quod cum videret Simon Petrus, procidit ad genua Jesu, dicens: Exi a me, quia homo peccator sum, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Stupor enim circumdederat eum, et omnes qui cum illo erant, in captura piscium, quam ceperant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'similiter autem Jacobum et Joannem, filios Zebedæi, qui erant socii Simonis. Et ait ad Simonem Jesus: Noli timere: ex hoc jam homines eris capiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Et subductis ad terram navibus, relictis omnibus, secuti sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Et factum est, cum esset in una civitatum, et ecce vir plenus lepra, et videns Jesum, et procidens in faciem, rogavit eum, dicens: Domine, si vis, potes me mundare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Et extendens manum, tetigit eum dicens: Volo: mundare. Et confestim lepra discessit ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Et ipse præcepit illi ut nemini diceret: sed, Vade, ostende te sacerdoti, et offer pro emundatione tua, sicut præcepit Moyses, in testimonium illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Perambulabat autem magis sermo de illo: et conveniebant turbæ multæ ut audirent, et curarentur ab infirmitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Ipse autem secedebat in desertum, et orabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Et factum est in una dierum, et ipse sedebat docens. Et erant pharisæi sedentes, et legis doctores, qui venerant ex omni castello Galilææ, et Judææ, et Jerusalem: et virtus Domini erat ad sanandum eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Et ecce viri portantes in lecto hominem, qui erat paralyticus: et quærebant eum inferre, et ponere ante eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Et non invenientes qua parte illum inferrent præ turba, ascenderunt supra tectum, et per tegulas summiserunt eum cum lecto in medium ante Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Quorum fidem ut vidit, dixit: Homo, remittuntur tibi peccata tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Et cœperunt cogitare scribæ et pharisæi, dicentes: Quis est hic, qui loquitur blasphemias? quis potest dimittere peccata, nisi solus Deus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ut cognovit autem Jesus cogitationes eorum, respondens, dixit ad illos: Quid cogitatis in cordibus vestris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Quid est facilius dicere: Dimittuntur tibi peccata: an dicere: Surge, et ambula?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Ut autem sciatis quia Filius hominis habet potestatem in terra dimittendi peccata, (ait paralytico) tibi dico, surge, tolle lectum tuum, et vade in domum tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Et confestim consurgens coram illis, tulit lectum in quo jacebat: et abiit in domum suam, magnificans Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Et stupor apprehendit omnes, et magnificabant Deum. Et repleti sunt timore, dicentes: Quia vidimus mirabilia hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Et post hæc exiit, et vidit publicanum nomine Levi, sedentem ad telonium, et ait illi: Sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Et relictis omnibus, surgens secutus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Et fecit ei convivium magnum Levi in domo sua: et erat turba multa publicanorum, et aliorum qui cum illis erant discumbentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Et murmurabant pharisæi et scribæ eorum, dicentes ad discipulos ejus: Quare cum publicanis et peccatoribus manducatis et bibitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Et respondens Jesus, dixit ad illos: Non egent qui sani sunt medico, sed qui male habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Non veni vocare justos, sed peccatores ad pœnitentiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'At illi dixerunt ad eum: Quare discipuli Joannis jejunant frequenter, et obsecrationes faciunt, similiter et pharisæorum: tui autem edunt et bibunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 34, 'Quibus ipse ait: Numquid potestis filios sponsi, dum cum illis est sponsus, facere jejunare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 35, 'Venient autem dies, cum ablatus fuerit ab illis sponsus: tunc jejunabunt in illis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 36, 'Dicebat autem et similitudinem ad illos: Quia nemo commissuram a novo vestimento immittit in vestimentum vetus: alioquin et novum rumpit, et veteri non convenit commissura a novo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 37, 'Et nemo mittit vinum novum in utres veteres: alioquin rumpet vinum novum utres, et ipsum effundetur, et utres peribunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 38, 'sed vinum novum in utres novos mittendum est, et utraque conservantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 39, 'Et nemo bibens vetus, statim vult novum: dicit enim: Vetus melius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Factum est autem in sabbato secundo, primo, cum transiret per sata, vellebant discipuli ejus spicas, et manducabant confricantes manibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Quidam autem pharisæorum, dicebant illis: Quid facitis quod non licet in sabbatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Et respondens Jesus ad eos, dixit: Nec hoc legistis quod fecit David, cum esurisset ipse, et qui cum illo erant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'quomodo intravit in domum Dei, et panes propositionis sumpsit, et manducavit, et dedit his qui cum ipso erant: quos non licet manducare nisi tantum sacerdotibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Et dicebat illis: Quia dominus est Filius hominis etiam sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Factum est autem in alio sabbato, ut intraret in synagogam, et doceret. Et erat ibi homo, et manus ejus dextra erat arida.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Observabant autem scribæ et pharisæi si in sabbato curaret, ut invenirent unde accusarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Ipse vero sciebat cogitationes eorum: et ait homini qui habebat manum aridam: Surge, et sta in medium. Et surgens stetit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Ait autem ad illos Jesus: Interrogo vos si licet sabbatis benefacere, an male: animam salvam facere, an perdere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Et circumspectis omnibus dixit homini: Extende manum tuam. Et extendit: et restituta est manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ipsi autem repleti sunt insipientia, et colloquebantur ad invicem, quidnam facerent Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Factum est autem in illis diebus, exiit in montem orare, et erat pernoctans in oratione Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Et cum dies factus esset, vocavit discipulos suos: et elegit duodecim ex ipsis (quos et apostolos nominavit):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Simonem, quem cognominavit Petrum, et Andream fratrem ejus, Jacobum, et Joannem, Philippum, et Bartholomæum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Matthæum, et Thomam, Jacobum Alphæi, et Simonem, qui vocatur Zelotes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'et Judam Jacobi, et Judam Iscariotem, qui fuit proditor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Et descendens cum illis, stetit in loco campestri, et turba discipulorum ejus, et multitudo copiosa plebis ab omni Judæa, et Jerusalem, et maritima, et Tyri, et Sidonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'qui venerant ut audirent eum, et sanarentur a languoribus suis. Et qui vexabantur a spiritibus immundis, curabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Et omnis turba quærebat eum tangere: quia virtus de illo exibat, et sanabat omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Et ipse elevatis oculis in discipulis suis, dicebat: Beati pauperes, quia vestrum est regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Beati qui nunc esuritis, quia saturabimini. Beati qui nunc fletis, quia ridebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Beati eritis cum vos oderint homines, et cum separaverint vos, et exprobraverint, et ejicerint nomen vestrum tamquam malum propter Filium hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Gaudete in illa die, et exsultate: ecce enim merces vestra multa est in cælo: secundum hæc enim faciebant prophetis patres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Verumtamen væ vobis divitibus, quia habetis consolationem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 25, 'Væ vobis, qui saturati estis: quia esurietis. Væ vobis, qui ridetis nunc: quia lugebitis et flebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 26, 'Væ cum benedixerint vobis homines: secundum hæc enim faciebant pseudoprophetis patres eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 27, 'Sed vobis dico, qui auditis: diligite inimicos vestros, benefacite his qui oderunt vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 28, 'Benedicite maledicentibus vobis, et orate pro calumniantibus vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 29, 'Et qui te percutit in maxillam, præbe et alteram. Et ab eo qui aufert tibi vestimentum, etiam tunicam noli prohibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 30, 'Omni autem petenti te, tribue: et qui aufert quæ tua sunt, ne repetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 31, 'Et prout vultis ut faciant vobis homines, et vos facite illis similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 32, 'Et si diligitis eos qui vos diligunt, quæ vobis est gratia? nam et peccatores diligentes se diligunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 33, 'Et si benefeceritis his qui vobis benefaciunt, quæ vobis est gratia? siquidem et peccatores hoc faciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 34, 'Et si mutuum dederitis his a quibus speratis recipere, quæ gratia est vobis? nam et peccatores peccatoribus fœnerantur, ut recipiant æqualia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 35, 'Verumtamen diligite inimicos vestros: benefacite, et mutuum date, nihil inde sperantes: et erit merces vestra multa, et eritis filii Altissimi, quia ipse benignus est super ingratos et malos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 36, 'Estote ergo misericordes sicut et Pater vester misericors est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 37, 'Nolite judicare, et non judicabimini: nolite condemnare, et non condemnabimini. Dimittite, et dimittemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 38, 'Date, et dabitur vobis: mensuram bonam, et confertam, et coagitatam, et supereffluentem dabunt in sinum vestrum. Eadem quippe mensura, qua mensi fueritis, remetietur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 39, 'Dicebat autem illis et similitudinem: Numquid potest cæcus cæcum ducere? nonne ambo in foveam cadunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 40, 'Non est discipulus super magistrum: perfectus autem omnis erit, si sit sicut magister ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 41, 'Quid autem vides festucam in oculo fratris tui, trabem autem, quæ in oculo tuo est, non consideras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 42, 'aut quomodo potes dicere fratri tuo: Frater, sine ejiciam festucam de oculo tuo: ipse in oculo tuo trabem non videns? Hypocrita, ejice primum trabem de oculo tuo: et tunc perspicies ut educas festucam de oculo fratris tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 43, 'Non est enim arbor bona, quæ facit fructus malos: neque arbor mala, faciens fructum bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 44, 'Unaquæque enim arbor de fructu suo cognoscitur. Neque enim de spinis colligunt ficus: neque de rubo vindemiant uvam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 45, 'Bonus homo de bono thesauro cordis sui profert bonum: et malus homo de malo thesauro profert malum. Ex abundantia enim cordis os loquitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 46, 'Quid autem vocatis me Domine, Domine: et non facitis quæ dico?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 47, 'Omnis qui venit ad me, et audit sermones meos, et facit eos, ostendam vobis cui similis sit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 48, 'similis est homini ædificanti domum, qui fodit in altum, et posuit fundamentum super petram: inundatione autem facta, illisum est flumen domui illi, et non potuit eam movere: fundata enim erat super petram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 49, 'Qui autem audit, et non facit, similis est homini ædificanti domum suam super terram sine fundamento: in quam illisus est fluvius, et continuo cecidit: et facta est ruina domus illius magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 1, 'Cum autem implesset omnia verba sua in aures plebis, intravit Capharnaum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 2, 'Centurionis autem cujusdam servus male habens, erat moriturus: qui illi erat pretiosus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 3, 'Et cum audisset de Jesu, misit ad eum seniores Judæorum, rogans eum ut veniret et salvaret servum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 4, 'At illi cum venissent ad Jesum, rogabant eum sollicite, dicentes ei: Quia dignus est ut hoc illi præstes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 5, 'diligit enim gentem nostram, et synagogam ipse ædificavit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 6, 'Jesus autem ibat cum illis. Et cum jam non longe esset a domo, misit ad eum centurio amicos, dicens: Domine, noli vexari: non enim sum dignus ut sub tectum meum intres:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 7, 'propter quod et meipsum non sum dignum arbitratus ut venirem ad te: sed dic verbo, et sanabitur puer meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 8, 'Nam et ego homo sum sub potestate constitutus, habens sub me milites: et dico huic, Vade, et vadit: et alii, Veni, et venit: et servo meo, Fac hoc, et facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 9, 'Quo audito Jesus miratus est: et conversus sequentibus se turbis, dixit: Amen dico vobis, nec in Israël tantam fidem inveni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 10, 'Et reversi, qui missi fuerant, domum, invenerunt servum, qui languerat, sanum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 11, 'Et factum est: deinceps ibat in civitatem quæ vocatur Naim: et ibant cum eo discipuli ejus et turba copiosa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 12, 'Cum autem appropinquaret portæ civitatis, ecce defunctus efferebatur filius unicus matris suæ: et hæc vidua erat: et turba civitatis multa cum illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 13, 'Quam cum vidisset Dominus, misericordia motus super eam, dixit illi: Noli flere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 14, 'Et accessit, et tetigit loculum. (Hi autem qui portabant, steterunt.) Et ait: Adolescens, tibi dico, surge.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 15, 'Et resedit qui erat mortuus, et cœpit loqui. Et dedit illum matri suæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 16, 'Accepit autem omnes timor: et magnificabant Deum, dicentes: Quia propheta magnus surrexit in nobis: et quia Deus visitavit plebem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 17, 'Et exiit hic sermo in universam Judæam de eo, et in omnem circa regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 18, 'Et nuntiaverunt Joanni discipuli ejus de omnibus his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 19, 'Et convocavit duos de discipulis suis Joannes, et misit ad Jesum, dicens: Tu es qui venturus es, an alium exspectamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 20, 'Cum autem venissent ad eum viri, dixerunt: Joannes Baptista misit nos ad te dicens: Tu es qui venturus es, an alium exspectamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 21, '(In ipsa autem hora multos curavit a languoribus, et plagis, et spiritibus malis, et cæcis multis donavit visum.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 22, 'Et respondens, dixit illis: Euntes renuntiate Joanni quæ audistis et vidistis: quia cæci vident, claudi ambulant, leprosi mundantur, surdi audiunt, mortui resurgunt, pauperes evangelizantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 23, 'et beatus est quicumque non fuerit scandalizatus in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 24, 'Et cum discessissent nuntii Joannis, cœpit de Joanne dicere ad turbas: Quid existis in desertum videre? arundinem vento agitatam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 25, 'Sed quid existis videre? hominem mollibus vestibus indutum? Ecce qui in veste pretiosa sunt et deliciis, in domibus regum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 26, 'Sed quid existis videre? prophetam? Utique dico vobis, et plus quam prophetam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 27, 'hic est, de quo scriptum est: Ecce mitto angelum meum ante faciem tuam, qui præparabit viam tuam ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 28, 'Dico enim vobis: major inter natos mulierum propheta Joanne Baptista nemo est: qui autem minor est in regno Dei, major est illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 29, 'Et omnis populus audiens et publicani, justificaverunt Deum, baptizati baptismo Joannis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 30, 'Pharisæi autem et legisperiti consilium Dei spreverunt in semetipsos, non baptizati ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 31, 'Ait autem Dominus: Cui ergo similes dicam homines generationis hujus? et cui similes sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 32, 'Similes sunt pueris sedentibus in foro, et loquentibus ad invicem, et dicentibus: Cantavimus vobis tibiis, et non saltastis: lamentavimus, et non plorastis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 33, 'Venit enim Joannes Baptista, neque manducans panem, neque bibens vinum, et dicitis: Dæmonium habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 34, 'Venit Filius hominis manducans, et bibens, et dicitis: Ecce homo devorator, et bibens vinum, amicus publicanorum et peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 35, 'Et justificata est sapientia ab omnibus filiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 36, 'Rogabat autem illum quidam de pharisæis ut manducaret cum illo. Et ingressus domum pharisæi discubuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 37, 'Et ecce mulier, quæ erat in civitate peccatrix, ut cognovit quod accubuisset in domo pharisæi, attulit alabastrum unguenti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 38, 'et stans retro secus pedes ejus, lacrimis cœpit rigare pedes ejus, et capillis capitis sui tergebat, et osculabatur pedes ejus, et unguento ungebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 39, 'Videns autem pharisæus, qui vocaverat eum, ait intra se dicens: Hic si esset propheta, sciret utique quæ et qualis est mulier, quæ tangit eum: quia peccatrix est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 40, 'Et respondens Jesus, dixit ad illum: Simon, habeo tibi aliquid dicere. At ille ait: Magister, dic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 41, 'Duo debitores erant cuidam fœneratori: unus debebat denarios quingentos, et alius quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 42, 'Non habentibus illis unde redderent, donavit utrisque. Quis ergo eum plus diligit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 43, 'Respondens Simon dixit: \'stimo quia is cui plus donavit. At ille dixit ei: Recte judicasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 44, 'Et conversus ad mulierem, dixit Simoni: Vides hanc mulierem? Intravi in domum tuam, aquam pedibus meis non dedisti: hæc autem lacrimis rigavit pedes meos, et capillis suis tersit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 45, 'Osculum mihi non dedisti: hæc autem ex quo intravit, non cessavit osculari pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 46, 'Oleo caput meum non unxisti: hæc autem unguento unxit pedes meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 47, 'Propter quod dico tibi: remittuntur ei peccata multa, quoniam dilexit multum. Cui autem minus dimittitur, minus diligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 48, 'Dixit autem ad illam: Remittuntur tibi peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 49, 'Et cœperunt qui simul accumbebant, dicere intra se: Quis est hic qui etiam peccata dimittit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 50, 'Dixit autem ad mulierem: Fides tua te salvam fecit: vade in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 1, 'Et factum est deinceps, et ipse iter faciebat per civitates, et castella prædicans, et evangelizans regnum Dei: et duodecim cum illo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 2, 'et mulieres aliquæ, quæ erant curatæ a spiritibus malignis et infirmantibus: Maria, quæ vocatur Magdalene, de qua septem dæmonia exierant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 3, 'et Joanna uxor Chusæ procuratoris Herodis, et Susanna, et aliæ multæ, quæ ministrabant ei de facultatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 4, 'Cum autem turba plurima convenirent, et de civitatibus properarent ad eum, dixit per similitudinem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 5, 'Exiit qui seminat, seminare semen suum. Et dum seminat, aliud cecidit secus viam, et conculcatum est, et volucres cæli comederunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 6, 'Et aliud cecidit supra petram: et natum aruit, quia non habebat humorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 7, 'Et aliud cecidit inter spinas, et simul exortæ spinæ suffocaverunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 8, 'Et aliud cecidit in terram bonam: et ortum fecit fructum centuplum. Hæc dicens clamabat: Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 9, 'Interrogabant autem eum discipuli ejus, quæ esset hæc parabola.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 10, 'Quibus ipse dixit: Vobis datum est nosse mysterium regni Dei, ceteris autem in parabolis: ut videntes non videant, et audientes non intelligant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 11, 'Est autem hæc parabola: Semen est verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 12, 'Qui autem secus viam, hi sunt qui audiunt: deinde venit diabolus, et tollit verbum de corde eorum, ne credentes salvi fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 13, 'Nam qui supra petram, qui cum audierint, cum gaudio suscipiunt verbum: et hi radices non habent: qui ad tempus credunt, et in tempore tentationis recedunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 14, 'Quod autem in spinas cecidit: hi sunt qui audierunt, et a sollicitudinibus, et divitiis, et voluptatibus vitæ euntes, suffocantur, et non referunt fructum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 15, 'Quod autem in bonam terram: hi sunt qui in corde bono et optimo audientes verbum retinent, et fructum afferunt in patientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 16, 'Nemo autem lucernam accendens, operit eam vase, aut subtus lectum ponit: sed supra candelabrum ponit, ut intrantes videant lumen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 17, 'Non est enim occultum, quod non manifestetur: nec absconditum, quod non cognoscatur, et in palam veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 18, 'Videte ergo quomodo audiatis? Qui enim habet, dabitur illi: et quicumque non habet, etiam quod putat se habere, auferetur ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 19, 'Venerunt autem ad illum mater et fratres ejus, et non poterant adire eum præ turba.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 20, 'Et nuntiatum est illi: Mater tua et fratres tui stant foris, volentes te videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 21, 'Qui respondens, dixit ad eos: Mater mea et fratres mei hi sunt, qui verbum Dei audiunt et faciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 22, 'Factum est autem in una dierum: et ipse ascendit in naviculam, et discipuli ejus, et ait ad illos: Transfretemus trans stagnum. Et ascenderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 23, 'Et navigantibus illis, obdormivit, et descendit procella venti in stagnum, et complebantur, et periclitabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 24, 'Accedentes autem suscitaverunt eum, dicentes: Præceptor, perimus. At ille surgens, increpavit ventum, et tempestatem aquæ, et cessavit: et facta est tranquillitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 25, 'Dixit autem illis: Ubi est fides vestra? Qui timentes, mirati sunt ad invicem, dicentes: Quis putas hic est, quia et ventis, et mari imperat, et obediunt ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 26, 'Et navigaverunt ad regionem Gerasenorum, quæ est contra Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 27, 'Et cum egressus esset ad terram, occurrit illi vir quidam, qui habebat dæmonium jam temporibus multis, et vestimento non induebatur, neque in domo manebat, sed in monumentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 28, 'Is, ut vidit Jesum, procidit ante illum: et exclamans voce magna, dixit: Quid mihi et tibi est, Jesu Fili Dei Altissimi? obsecro te, ne me torqueas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 29, 'Præcipiebat enim spiritui immundo ut exiret ab homine. Multis enim temporibus arripiebat illum, et vinciebatur catenis, et compedibus custoditus. Et ruptis vinculis agebatur a dæmonio in deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 30, 'Interrogavit autem illum Jesus, dicens: Quod tibi nomen est? At ille dixit: Legio: quia intraverant dæmonia multa in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 31, 'Et rogabant illum ne imperaret illis ut in abyssum irent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 32, 'Erat autem ibi grex porcorum multorum pascentium in monte: et rogabant eum, ut permitteret eis in illos ingredi. Et permisit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 33, 'Exierunt ergo dæmonia ab homine, et intraverunt in porcos: et impetu abiit grex per præceps in stagnum, et suffocatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 34, 'Quod ut viderunt factum qui pascebant, fugerunt, et nuntiaverunt in civitatem et in villas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 35, 'Exierunt autem videre quod factum est, et venerunt ad Jesum, et invenerunt hominem sedentem, a quo dæmonia exierant, vestitum ac sana mente, ad pedes ejus, et timuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 36, 'Nuntiaverunt autem illis et qui viderant, quomodo sanus factus esset a legione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 37, 'et rogaverunt illum omnis multitudo regionis Gerasenorum ut discederet ab ipsis: quia magno timore tenebantur. Ipse autem ascendens navim, reversus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 38, 'Et rogabat illum vir, a quo dæmonia exierant, ut cum eo esset. Dimisit autem eum Jesus, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 39, 'Redi in domum tuam, et narra quanta tibi fecit Deus. Et abiit per universam civitatem, prædicans quanta illi fecisset Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 40, 'Factum est autem cum rediisset Jesus, excepit illum turba: erunt enim omnes exspectantes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 41, 'Et ecce venit vir, cui nomen Jairus, et ipse princeps synagogæ erat: et cecidit ad pedes Jesu, rogans eum ut intraret in domum ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 42, 'quia unica filia erat ei fere annorum duodecim, et hæc moriebatur. Et contigit, dum iret, a turba comprimebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 43, 'Et mulier quædam erat in fluxu sanguinis ab annis duodecim, quæ in medicos erogaverat omnem substantiam suam, nec ab ullo potuit curari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 44, 'accessit retro, et tetigit fimbriam vestimenti ejus: et confestim stetit fluxus sanguinis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 45, 'Et ait Jesus: Quis est, qui me tetigit? Negantibus autem omnibus, dixit Petrus, et qui cum illo erant: Præceptor, turbæ te comprimunt, et affligunt, et dicis: Quis me tetigit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 46, 'Et dicit Jesus: Tetigit me aliquis: nam ego novi virtutem de me exiisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 47, 'Videns autem mulier, quia non latuit, tremens venit, et procidit ante pedes ejus: et ob quam causam tetigerit eum, indicavit coram omni populo: et quemadmodum confestim sanata sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 48, 'At ipse dixit ei: Filia, fides tua salvam te fecit: vade in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 49, 'Adhuc illo loquente, venit quidam ad principem synagogæ, dicens ei: Quia mortua est filia tua, noli vexare illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 50, 'Jesus autem, audito hoc verbo, respondit patri puellæ: Noli timere, crede tantum, et salva erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 51, 'Et cum venisset domum, non permisit intrare secum quemquam, nisi Petrum, et Jacobum, et Joannem, et patrem, et matrem puellæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 52, 'Flebant autem omnes, et plangebant illam. At ille dixit: Nolite flere: non est mortua puella, sed dormit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 53, 'Et deridebant eum, scientes quod mortua esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 54, 'Ipse autem tenens manum ejus clamavit, dicens: Puella, surge.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 55, 'Et reversus est spiritus ejus, et surrexit continuo. Et jussit illi dari manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 56, 'Et stupuerunt parentes ejus, quibus præcepit ne alicui dicerent quod factum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 1, 'Convocatis autem duodecim Apostolis, dedit illis virtutem et potestatem super omnia dæmonia, et ut languores curarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 2, 'Et misit illos prædicare regnum Dei, et sanare infirmos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 3, 'Et ait ad illos: Nihil tuleritis in via, neque virgam, neque peram, neque panem, neque pecuniam, neque duas tunicas habeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 4, 'Et in quamcumque domum intraveritis, ibi manete, et inde ne exeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 5, 'Et quicumque non receperint vos: exeuntes de civitate illa, etiam pulverem pedum vestrorum excutite in testimonium supra illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 6, 'Egressi autem circuibant per castella evangelizantes, et curantes ubique.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 7, 'Audivit autem Herodes tetrarcha omnia quæ fiebant ab eo, et hæsitabat eo quod diceretur');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 8, 'a quibusdam: Quia Joannes surrexit a mortuis: a quibusdam vero: Quia Elias apparuit: ab aliis autem: Quia propheta unus de antiquis surrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 9, 'Et ait Herodes: Joannem ego decollavi: quis est autem iste, de quo ego talia audio? Et quærebat videre eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 10, 'Et reversi Apostoli, narraverunt illi quæcumque fecerunt: et assumptis illis secessit seorsum in locum desertum, qui est Bethsaidæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 11, 'Quod cum cognovissent turbæ, secutæ sunt illum: et excepit eos, et loquebatur illis de regno Dei, et eos, qui cura indigebant, sanabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 12, 'Dies autem cœperat declinare, et accedentes duodecim dixerunt illi: Dimitte turbas, ut euntes in castella villasque quæ circa sunt, divertant, et inveniant escas: quia hic in loco deserto sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 13, 'Ait autem ad illos: Vos date illis manducare. At illi dixerunt: Non sunt nobis plus quam quinque panes et duo pisces: nisi forte nos eamus, et emamus in omnem hanc turbam escas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 14, 'Erant autem fere viri quinque millia. Ait autem ad discipulos suos: Facite illos discumbere per convivia quinquagenos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 15, 'Et ita fecerunt: et discumbere fecerunt omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 16, 'Acceptis autem quinque panibus et duobus piscibus, respexit in cælum, et benedixit illis: et fregit, et distribuit discipulis suis, ut ponerent ante turbas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 17, 'Et manducaverunt omnes, et saturati sunt. Et sublatum est quod superfuit illis, fragmentorum cophini duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 18, 'Et factum est cum solus esset orans, erant cum illo et discipuli: et interrogavit illos, dicens: Quem me dicunt esse turbæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 19, 'At illi responderunt, et dixerunt: Joannem Baptistam, alii autem Eliam, alii vero quia unus propheta de prioribus surrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 20, 'Dixit autem illis: Vos autem quem me esse dicitis? Respondens Simon Petrus, dixit: Christum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 21, 'At ille increpans illos, præcepit ne cui dicerent hoc,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 22, 'dicens: Quia oportet Filium hominis multa pati, et reprobari a senioribus, et principibus sacerdotum, et scribis, et occidi, et tertia die resurgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 23, 'Dicebat autem ad omnes: Si quis vult post me venire, abneget semetipsum, et tollat crucem suam quotidie, et sequatur me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 24, 'Qui enim voluerit animam suam salvam facere, perdet illam: nam qui perdiderit animam suam propter me, salvam faciet illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 25, 'Quid enim proficit homo, si lucretur universum mundum, se autem ipsum perdat, et detrimentum sui faciat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 26, 'Nam qui me erubuerit, et meos sermones: hunc Filius hominis erubescet cum venerit in majestate sua, et Patris, et sanctorum angelorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 27, 'Dico autem vobis vere: sunt aliqui hic stantes, qui non gustabunt mortem donec videant regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 28, 'Factum est autem post hæc verba fere dies octo, et assumpsit Petrum, et Jacobum, et Joannem, et ascendit in montem ut oraret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 29, 'Et facta est, dum oraret, species vultus ejus altera: et vestitus ejus albus et refulgens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 30, 'Et ecce duo viri loquebantur cum illo. Erant autem Moyses et Elias,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 31, 'visi in majestate: et dicebant excessum ejus, quem completurus erat in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 32, 'Petrus vero, et qui cum illo erant, gravati erant somno. Et evigilantes viderunt majestatem ejus, et duos viros qui stabant cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 33, 'Et factum est cum discederent ab illo, ait Petrus ad Jesum: Præceptor, bonum est nos hic esse: et faciamus tria tabernacula, unum tibi, et unum Moysi, et unum Eliæ: nesciens quid diceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 34, 'Hæc autem illo loquente, facta est nubes, et obumbravit eos: et timuerunt, intrantibus illis in nubem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 35, 'Et vox facta est de nube, dicens: Hic est Filius meus dilectus, ipsum audite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 36, 'Et dum fieret vox, inventus est Jesus solus. Et ipsi tacuerunt, et nemini dixerunt in illis diebus quidquam ex his quæ viderant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 37, 'Factum est autem in sequenti die, descendentibus illis de monte, occurrit illis turba multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 38, 'Et ecce vir de turba exclamavit, dicens: Magister, obsecro te, respice in filium meum quia unicus est mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 39, 'et ecce spiritus apprehendit eum, et subito clamat, et elidit, et dissipat eum cum spuma, et vix discedit dilanians eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 40, 'et rogavi discipulos tuos ut ejicerent illum, et non potuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 41, 'Respondens autem Jesus, dixit: O generatio infidelis, et perversa, usquequo ero apud vos, et patiar vos? adduc huc filium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 42, 'Et cum accederet, elisit illum dæmonium, et dissipavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 43, 'Et increpavit Jesus spiritum immundum, et sanavit puerum, et reddidit illum patri ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 44, 'Stupebant autem omnes in magnitudine Dei: omnibusque mirantibus in omnibus quæ faciebat, dixit ad discipulos suos: Ponite vos in cordibus vestris sermones istos: Filius enim hominis futurum est ut tradatur in manus hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 45, 'At illi ignorabant verbum istud, et erat velatum ante eos ut non sentirent illud: et timebant eum interrogare de hoc verbo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 46, 'Intravit autem cogitatio in eos quis eorum major esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 47, 'At Jesus videns cogitationes cordis illorum, apprehendit puerum, et statuit illum secus se,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 48, 'et ait illis: Quicumque susceperit puerum istum in nomine meo, me recipit: et quicumque me receperit, recipit eum qui me misit. Nam qui minor est inter vos omnes, hic major est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 49, 'Respondens autem Joannes dixit: Præceptor, vidimus quemdam in nomine tuo ejicientem dæmonia, et prohibuimus eum: quia non sequitur nobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 50, 'Et ait ad illum Jesus: Nolite prohibere: qui enim non est adversum vos, pro vobis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 51, 'Factum est autem dum complerentur dies assumptionis ejus, et ipse faciem suam firmavit ut iret in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 52, 'Et misit nuntios ante conspectum suum: et euntes intraverunt in civitatem Samaritanorum ut parerent illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 53, 'Et non receperunt eum, quia facies ejus erat euntis in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 54, 'Cum vidissent autem discipuli ejus Jacobus et Joannes, dixerunt: Domine, vis dicimus ut ignis descendat de cælo, et consumat illos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 55, 'Et conversus increpavit illos, dicens: Nescitis cujus spiritus estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 56, 'Filius hominis non venit animas perdere, sed salvare. Et abierunt in aliud castellum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 57, 'Factum est autem: ambulantibus illis in via, dixit quidam ad illum: Sequar te quocumque ieris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 58, 'Dixit illi Jesus: Vulpes foveas habent, et volucres cæli nidos: Filius autem hominis non habet ubi caput reclinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 59, 'Ait autem ad alterum: Sequere me: ille autem dixit: Domine, permitte mihi primum ire, et sepelire patrem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 60, 'Dixitque ei Jesus: Sine ut mortui sepeliant mortuos suos: tu autem vade, et annuntia regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 61, 'Et ait alter: Sequar te Domine, sed permitte mihi primum renuntiare his quæ domi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 62, 'Ait ad illum Jesus: Nemo mittens manum suam ad aratrum, et respiciens retro, aptus est regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 1, 'Post hæc autem designavit Dominus et alios septuaginta duos: et misit illos binos ante faciem suam in omnem civitatem et locum, quo erat ipse venturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 2, 'Et dicebat illis: Messis quidem multa, operarii autem pauci. Rogate ergo dominum messis ut mittat operarios in messem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 3, 'Ite: ecce ego mitto vos sicut agnos inter lupos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 4, 'Nolite portare sacculum, neque peram, neque calceamenta, et neminem per viam salutaveritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 5, 'In quamcumque domum intraveritis, primum dicite: Pax huic domui:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 6, 'et si ibi fuerit filius pacis, requiescet super illum pax vestra: sin autem, ad vos revertetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 7, 'In eadem autem domo manete, edentes et bibentes quæ apud illos sunt: dignus est enim operarius mercede sua. Nolite transire de domo in domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 8, 'Et in quamcumque civitatem intraveritis, et susceperint vos, manducate quæ apponuntur vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 9, 'et curate infirmos, qui in illa sunt, et dicite illis: Appropinquavit in vos regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 10, 'In quamcumque autem civitatem intraveritis, et non susceperint vos, exeuntes in plateas ejus, dicite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 11, 'Etiam pulverem, qui adhæsit nobis de civitate vestra, extergimus in vos: tamen hoc scitote, quia appropinquavit regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 12, 'Dico vobis, quia Sodomis in die illa remissius erit, quam illi civitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 13, 'Væ tibi Corozain! væ tibi Bethsaida! quia si in Tyro et Sidone factæ fuissent virtutes quæ factæ sunt in vobis, olim in cilicio et cinere sedentes pœniterent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 14, 'Verumtamen Tyro et Sidoni remissius erit in judicio, quam vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 15, 'Et tu Capharnaum, usque ad cælum exaltata, usque ad infernum demergeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 16, 'Qui vos audit, me audit: et qui vos spernit, me spernit. Qui autem me spernit, spernit eum qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 17, 'Reversi sunt autem septuaginta duo cum gaudio, dicentes: Domine, etiam dæmonia subjiciuntur nobis in nomine tuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 18, 'Et ait illis: Videbam Satanam sicut fulgor de cælo cadentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 19, 'Ecce dedi vobis potestatem calcandi supra serpentes, et scorpiones, et super omnem virtutem inimici: et nihil vobis nocebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 20, 'Verumtamen in hoc nolite gaudere quia spiritus vobis subjiciuntur: gaudete autem, quod nomina vestra scripta sunt in cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 21, 'In ipsa hora exsultavit Spiritu Sancto, et dixit: Confiteor tibi Pater, Domine cæli et terræ, quod abscondisti hæc a sapientibus et prudentibus, et revelasti ea parvulis. Etiam Pater: quoniam sic placuit ante te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 22, 'Omnia mihi tradita sunt a Patre meo. Et nemo scit quis sit Filius, nisi Pater: et quis sit Pater, nisi Filius, et cui voluerit Filius revelare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 23, 'Et conversus ad discipulos suos, dixit: Beati oculi qui vident quæ vos videtis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 24, 'Dico enim vobis quod multi prophetæ et reges voluerunt videre quæ vos videtis, et non viderunt: et audire quæ auditis, et non audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 25, 'Et ecce quidam legisperitus surrexit tentans illum, et dicens: Magister, quid faciendo vitam æternam possidebo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 26, 'At ille dixit ad eum: In lege quid scriptum est? quomodo legis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 27, 'Ille respondens dixit: Diliges Dominum Deum tuum ex toto corde tuo, et ex tota anima tua, et ex omnibus virtutibus tuis, et ex omni mente tua: et proximum tuum sicut teipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 28, 'Dixitque illi: Recte respondisti: hoc fac, et vives.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 29, 'Ille autem volens justificare seipsum, dixit ad Jesum: Et quis est meus proximus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 30, 'Suscipiens autem Jesus, dixit: Homo quidam descendebat ab Jerusalem in Jericho, et incidit in latrones, qui etiam despoliaverunt eum: et plagis impositis abierunt semivivo relicto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 31, 'Accidit autem ut sacerdos quidam descenderet eadem via: et viso illo præterivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 32, 'Similiter et Levita, cum esset secus locum, et videret eum, pertransiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 33, 'Samaritanus autem quidam iter faciens, venit secus eum: et videns eum, misericordia motus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 34, 'Et appropians alligavit vulnera ejus, infundens oleum et vinum: et imponens illum in jumentum suum, duxit in stabulum, et curam ejus egit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 35, 'Et altera die protulit duos denarios, et dedit stabulario, et ait: Curam illius habe: et quodcumque supererogaveris, ego cum rediero reddam tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 36, 'Quis horum trium videtur tibi proximus fuisse illi, qui incidit in latrones?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 37, 'At ille dixit: Qui fecit misericordiam in illum. Et ait illi Jesus: Vade, et tu fac similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 38, 'Factum est autem, dum irent, et ipse intravit in quoddam castellum: et mulier quædam, Martha nomine, excepit illum in domum suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 39, 'et huic erat soror nomine Maria, quæ etiam sedens secus pedes Domini, audiebat verbum illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 40, 'Martha autem satagebat circa frequens ministerium: quæ stetit, et ait: Domine, non est tibi curæ quod soror mea reliquit me solam ministrare? dic ergo illi ut me adjuvet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 41, 'Et respondens dixit illi Dominus: Martha, Martha, sollicita es, et turbaris erga plurima,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 42, 'porro unum est necessarium. Maria optimam partem elegit, quæ non auferetur ab ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 1, 'Et factum est: cum esset in quodam loco orans, ut cessavit, dixit unus ex discipulis ejus ad eum: Domine, doce nos orare, sicut docuit et Joannes discipulos suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 2, 'Et ait illis: Cum oratis, dicite: Pater, sanctificetur nomen tuum. Adveniat regnum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 3, 'Panem nostrum quotidianum da nobis hodie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 4, 'Et dimitte nobis peccata nostra, siquidem et ipsi dimittimus omni debenti nobis. Et ne nos inducas in tentationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 5, 'Et ait ad illos: Quis vestrum habebit amicum, et ibit ad illum media nocte, et dicet illi: Amice, commoda mihi tres panes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 6, 'quoniam amicus meus venit de via ad me, et non habeo quod ponam ante illum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 7, 'et ille de intus respondens dicat: Noli mihi molestus esse, jam ostium clausum est, et pueri mei mecum sunt in cubili: non possum surgere, et dare tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 8, 'Et si ille perseveraverit pulsans: dico vobis, etsi non dabit illi surgens eo quod amicus ejus sit, propter improbitatem tamen ejus surget, et dabit illi quotquot habet necessarios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 9, 'Et ego dico vobis: Petite, et dabitur vobis; quærite, et invenietis; pulsate, et aperietur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 10, 'Omnis enim qui petit, accipit: et qui quærit, invenit: et pulsanti aperietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 11, 'Quis autem ex vobis patrem petit panem, numquid lapidem dabit illi? aut piscem, numquid pro pisce serpentem dabit illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 12, 'aut si petierit ovum, numquid porriget illi scorpionem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 13, 'Si ergo vos, cum sitis mali, nostis bona data dare filiis vestris: quanto magis Pater vester de cælo dabit spiritum bonum petentibus se?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 14, 'Et erat ejiciens dæmonium, et illud erat mutum. Et cum ejecisset dæmonium, locutus est mutus, et admiratæ sunt turbæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 15, 'Quidam autem ex eis dixerunt: In Beelzebub principe dæmoniorum ejicit dæmonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 16, 'Et alii tentantes, signum de cælo quærebant ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 17, 'Ipse autem ut vidit cogitationes eorum, dixit eis: Omne regnum in seipsum divisum desolabitur, et domus supra domum cadet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 18, 'Si autem et Satanas in seipsum divisus est, quomodo stabit regnum ejus? quia dicitis in Beelzebub me ejicere dæmonia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 19, 'Si autem ego in Beelzebub ejicio dæmonia: filii vestri in quo ejiciunt? ideo ipsi judices vestri erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 20, 'Porro si in digito Dei ejicio dæmonia: profecto pervenit in vos regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 21, 'Cum fortis armatus custodit atrium suum, in pace sunt ea quæ possidet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 22, 'Si autem fortior eo superveniens vicerit eum, universa arma ejus auferet, in quibus confidebat, et spolia ejus distribuet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 23, 'Qui non est mecum, contra me est: et qui non colligit mecum, dispergit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 24, 'Cum immundus spiritus exierit de homine, ambulat per loca inaquosa, quærens requiem: et non inveniens dicit: Revertar in domum meam unde exivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 25, 'Et cum venerit, invenit eam scopis mundatam, et ornatam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 26, 'Tunc vadit, et assumit septem alios spiritus secum, nequiores se, et ingressi habitant ibi. Et fiunt novissima hominis illius pejora prioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 27, 'Factum est autem, cum hæc diceret: extollens vocem quædam mulier de turba dixit illi: Beatus venter qui te portavit, et ubera quæ suxisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 28, 'At ille dixit: Quinimmo beati, qui audiunt verbum Dei et custodiunt illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 29, 'Turbis autem concurrentibus cœpit dicere: Generatio hæc, generatio nequam est: signum quærit, et signum non dabitur ei, nisi signum Jonæ prophetæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 30, 'Nam sicut fuit Jonas signum Ninivitis, ita erit et Filius hominis generationi isti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 31, 'Regina austri surget in judicio cum viris generationis hujus, et condemnabit illos: quia venit a finibus terræ audire sapientiam Salomonis: et ecce plus quam Salomon hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 32, 'Viri Ninivitæ surgent in judicio cum generatione hac, et condemnabunt illam: quia pœnitentiam egerunt ad prædicationem Jonæ, et ecce plus quam Jonas hic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 33, 'Nemo lucernam accendit, et in abscondito ponit, neque sub modio: sed supra candelabrum, ut qui ingrediuntur, lumen videant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 34, 'Lucerna corporis tui est oculus tuus. Si oculus tuus fuerit simplex, totum corpus tuum lucidum erit: si autem nequam fuerit, etiam corpus tuum tenebrosum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 35, 'Vide ergo ne lumen quod in te est, tenebræ sint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 36, 'Si ergo corpus tuum totum lucidum fuerit, non habens aliquam partem tenebrarum, erit lucidum totum, et sicut lucerna fulgoris illuminabit te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 37, 'Et cum loqueretur, rogavit illum quidam pharisæus ut pranderet apud se. Et ingressus recubuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 38, 'Pharisæus autem cœpit intra se reputans dicere, quare non baptizatus esset ante prandium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 39, 'Et ait Dominus ad illum: Nunc vos pharisæi, quod deforis est calicis et catini, mundatis: quod autem intus est vestrum, plenum est rapina et iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 40, 'Stulti! nonne qui fecit quod deforis est, etiam id quod deintus est fecit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 41, 'Verumtamen quod superest, date eleemosynam: et ecce omnia munda sunt vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 42, 'Sed væ vobis, pharisæis, quia decimatis mentham, et rutam, et omne olus, et præteritis judicium et caritatem Dei: hæc autem oportuit facere, et illa non omittere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 43, 'Væ vobis, pharisæis, quia diligitis primas cathedras in synagogis, et salutationes in foro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 44, 'Væ vobis, quia estis ut monumenta, quæ non apparent, et homines ambulantes supra, nesciunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 45, 'Respondens autem quidam ex legisperitis, ait illi: Magister, hæc dicens etiam contumeliam nobis facis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 46, 'At ille ait: Et vobis legisperitis væ: quia oneratis homines oneribus, quæ portare non possunt, et ipsi uno digito vestro non tangitis sarcinas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 47, 'Væ vobis, qui ædificatis monumenta prophetarum: patres autem vestri occiderunt illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 48, 'Profecto testificamini quod consentitis operibus patrum vestrorum: quoniam ipsi quidem eos occiderunt, vos autem ædificatis eorum sepulchra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 49, 'Propterea et sapientia Dei dixit: Mittam ad illos prophetas, et apostolos, et ex illis occident, et persequentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 50, 'ut inquiratur sanguis omnium prophetarum, qui effusus est a constitutione mundi a generatione ista,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 51, 'a sanguine Abel, usque ad sanguinem Zachariæ, qui periit inter altare et ædem. Ita dico vobis, requiretur ab hac generatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 52, 'Væ vobis, legisperitis, quia tulistis clavem scientiæ: ipsi non introistis, et eos qui introibant, prohibuistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 53, 'Cum autem hæc ad illos diceret, cœperunt pharisæi et legisperiti graviter insistere, et os ejus opprimere de multis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 54, 'insidiantes ei, et quærentes aliquid capere de ore ejus, ut accusarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 1, 'Multis autem turbis circumstantibus, ita ut se invicem conculcarent, cœpit dicere ad discipulos suos: Attendite a fermento pharisæorum, quod est hypocrisis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 2, 'Nihil autem opertum est, quod non reveletur: neque absconditum, quod non sciatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 3, 'Quoniam quæ in tenebris dixistis, in lumine dicentur: et quod in aurem locuti estis in cubiculis, prædicabitur in tectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 4, 'Dico autem vobis amicis meis: Ne terreamini ab his qui occidunt corpus, et post hæc non habent amplius quid faciant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 5, 'Ostendam autem vobis quem timeatis: timete eum qui, postquam occiderit, habet potestatem mittere in gehennam: ita dico vobis, hunc timete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 6, 'Nonne quinque passeres veneunt dipondio, et unus ex illis non est in oblivione coram Deo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 7, 'sed et capilli capitis vestri omnes numerati sunt. Nolite ergo timere: multis passeribus pluris estis vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 8, 'Dico autem vobis: Omnis quicumque confessus fuerit me coram hominibus, et Filius hominis confitebitur illum coram angelis Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 9, 'qui autem negaverit me coram hominibus, negabitur coram angelis Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 10, 'Et omnis qui dicit verbum in Filium hominis, remittetur illi: ei autem qui in Spiritum Sanctum blasphemaverit, non remittetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 11, 'Cum autem inducent vos in synagogas, et ad magistratus, et potestates, nolite solliciti esse qualiter, aut quid respondeatis, aut quid dicatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 12, 'Spiritus enim Sanctus docebit vos in ipsa hora quid oporteat vos dicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 13, 'Ait autem ei quidam de turba: Magister, dic fratri meo ut dividat mecum hæreditatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 14, 'At ille dixit illi: Homo, quis me constituit judicem, aut divisorem super vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 15, 'Dixitque ad illos: Videte, et cavete ab omni avaritia: quia non in abundantia cujusquam vita ejus est ex his quæ possidet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 16, 'Dixit autem similitudinem ad illos, dicens: Hominis cujusdam divitis uberes fructus ager attulit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 17, 'et cogitabat intra se dicens: Quid faciam, quia non habeo quo congregem fructus meos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 18, 'Et dixit: Hoc faciam: destruam horrea mea, et majora faciam: et illuc congregabo omnia quæ nata sunt mihi, et bona mea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 19, 'et dicam animæ meæ: Anima, habes multa bona posita in annos plurimos: requiesce, comede, bibe, epulare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 20, 'Dixit autem illi Deus: Stulte, hac nocte animam tuam repetunt a te: quæ autem parasti, cujus erunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 21, 'Sic est qui sibi thesaurizat, et non est in Deum dives.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 22, 'Dixitque ad discipulos suos: Ideo dico vobis, nolite solliciti esse animæ vestræ quid manducetis, neque corpori quid induamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 23, 'Anima plus est quam esca, et corpus plus quam vestimentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 24, 'Considerate corvos, quia non seminant, neque metunt, quibus non est cellarium, neque horreum, et Deus pascit illos. Quanto magis vos pluris estis illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 25, 'Quis autem vestrum cogitando potest adjicere ad staturam suam cubitum unum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 26, 'Si ergo neque quod minimum est potestis, quid de ceteris solliciti estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 27, 'Considerate lilia quomodo crescunt: non laborant, neque nent: dico autem vobis, nec Salomon in omni gloria sua vestiebatur sicut unum ex istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 28, 'Si autem fœnum, quod hodie est in agro, et cras in clibanum mittitur, Deus sic vestit: quanto magis vos pusillæ fidei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 29, 'Et vos nolite quærere quid manducetis, aut quid bibatis: et nolite in sublime tolli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 30, 'hæc enim omnia gentes mundi quærunt. Pater autem vester scit quoniam his indigetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 31, 'Verumtamen quærite primum regnum Dei, et justitiam ejus: et hæc omnia adjicientur vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 32, 'Nolite timere pusillus grex, quia complacuit Patri vestro dare vobis regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 33, 'Vendite quæ possidetis, et date eleemosynam. Facite vobis sacculos, qui non veterascunt, thesaurum non deficientem in cælis: quo fur non appropriat, neque tinea corrumpit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 34, 'Ubi enim thesaurus vester est, ibi et cor vestrum erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 35, 'Sint lumbi vestri præcincti, et lucernæ ardentes in manibus vestris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 36, 'et vos similes hominibus exspectantibus dominum suum quando revertatur a nuptiis: ut, cum venerit et pulsaverit, confestim aperiant ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 37, 'Beati servi illi quos, cum venerit dominus, invenerit vigilantes: amen dico vobis, quod præcinget se, et faciet illos discumbere, et transiens ministrabit illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 38, 'Et si venerit in secunda vigilia, et si in tertia vigilia venerit, et ita invenerit, beati sunt servi illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 39, 'Hoc autem scitote, quoniam si sciret paterfamilias, qua hora fur veniret, vigilaret utique, et non sineret perfodi domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 40, 'Et vos estote parati: quia qua hora non putatis, Filius hominis veniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 41, 'Ait autem ei Petrus: Domine, ad nos dicis hanc parabolam, an et ad omnes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 42, 'Dixit autem Dominus: Quis, putas, est fidelis dispensator, et prudens, quem constituit dominus supra familiam suam, ut det illis in tempore tritici mensuram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 43, 'Beatus ille servus quem, cum venerit dominus, invenerit ita facientem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 44, 'Vere dico vobis, quoniam supra omnia quæ possidet, constituet illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 45, 'Quod si dixerit servus ille in corde suo: Moram facit dominus meus venire: et cœperit percutere servos, et ancillas, et edere, et bibere, et inebriari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 46, 'veniet dominus servi illius in die qua non sperat, et hora qua nescit, et dividet eum, partemque ejus cum infidelibus ponet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 47, 'Ille autem servus qui cognovit voluntatem domini sui, et non præparavit, et non facit secundum voluntatem ejus, vapulabit multis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 48, 'qui autem non cognovit, et fecit digna plagis, vapulabit paucis. Omni autem cui multum datum est, multum quæretur ab eo: et cui commendaverunt multum, plus petent ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 49, 'Ignem veni mittere in terram, et quid volo nisi ut accendatur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 50, 'Baptismo autem habeo baptizari: et quomodo coarctor usque dum perficiatur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 51, 'Putatis quia pacem veni dare in terram? non, dico vobis, sed separationem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 52, 'erunt enim ex hoc quinque in domo una divisi, tres in duos, et duo in tres');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 53, 'dividentur: pater in filium, et filius in patrem suum, mater in filiam, et filia in matrem, socrus in nurum suam, et nurus in socrum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 54, 'Dicebat autem et ad turbas: Cum videritis nubem orientem ab occasu, statim dicitis: Nimbus venit: et ita fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 55, 'Et cum austrum flantem, dicitis: Quia æstus erit: et fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 56, 'Hypocritæ! faciem cæli et terræ nostis probare: hoc autem tempus quomodo non probatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 57, 'quid autem et a vobis ipsis non judicatis quod justum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 58, 'Cum autem vadis cum adversario tuo ad principem, in via da operam liberari ab illo, ne forte trahat te ad judicem, et judex tradat te exactori, et exactor mittat te in carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 59, 'Dico tibi, non exies inde, donec etiam novissimum minutum reddas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 1, 'Aderant autem quidam ipso in tempore, nuntiantes illi de Galilæis, quorum sanguinem Pilatus miscuit cum sacrificiis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 2, 'Et respondens dixit illis: Putatis quod hi Galilæi præ omnibus Galilæis peccatores fuerint, quia talia passi sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 3, 'Non, dico vobis: sed nisi pœnitentiam habueritis, omnes similiter peribitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 4, 'Sicut illi decem et octo, supra quos cecidit turris in Siloë, et occidit eos: putatis quia et ipsi debitores fuerint præter omnes homines habitantes in Jerusalem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 5, 'Non, dico vobis: sed si pœnitentiam non egeritis, omnes similiter peribitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 6, 'Dicebat autem et hanc similitudinem: Arborem fici habebat quidam plantatam in vinea sua, et venit quærens fructum in illa, et non invenit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 7, 'Dixit autem ad cultorem vineæ: Ecce anni tres sunt ex quo venio quærens fructum in ficulnea hac, et non invenio: succide ergo illam: ut quid etiam terram occupat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 8, 'At ille respondens, dicit illi: Domine dimitte illam et hoc anno, usque dum fodiam circa illam, et mittam stercora,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 9, 'et siquidem fecerit fructum: sin autem, in futurum succides eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 10, 'Erat autem docens in synagoga eorum sabbatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 11, 'Et ecce mulier, quæ habebat spiritum infirmitatis annis decem et octo: et erat inclinata, nec omnino poterat sursum respicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 12, 'Quam cum videret Jesus, vocavit eam ad se, et ait illi: Mulier, dimissa es ab infirmitate tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 13, 'Et imposuit illi manus, et confestim erecta est, et glorificabat Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 14, 'Respondens autem archisynagogus, indignans quia sabbato curasset Jesus, dicebat turbæ: Sex dies sunt in quibus oportet operari: in his ergo venite, et curamini, et non in die sabbati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 15, 'Respondens autem ad illum Dominus, dixit: Hypocritæ, unusquisque vestrum sabbato non solvit bovem suum, aut asinum a præsepio, et ducit adaquare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 16, 'Hanc autem filiam Abrahæ, quam alligavit Satanas, ecce decem et octo annis, non oportuit solvi a vinculo isto die sabbati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 17, 'Et cum hæc diceret, erubescebant omnes adversarii ejus: et omnis populus gaudebat in universis, quæ gloriose fiebant ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 18, 'Dicebat ergo: Cui simile est regnum Dei, et cui simile æstimabo illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 19, 'Simile est grano sinapis, quod acceptum homo misit in hortum suum, et crevit, et factum est in arborem magnam: et volucres cæli requieverunt in ramis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 20, 'Et iterum dixit: Cui simile æstimabo regnum Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 21, 'Simile est fermento, quod acceptum mulier abscondit in farinæ sata tria, donec fermentaretur totum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 22, 'Et ibat per civitates et castella, docens, et iter faciens in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 23, 'Ait autem illi quidam: Domine, si pauci sunt, qui salvantur? Ipse autem dixit ad illos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 24, 'Contendite intrare per angustam portam: quia multi, dico vobis, quærent intrare, et non poterunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 25, 'Cum autem intraverit paterfamilias, et clauserit ostium, incipietis foris stare, et pulsare ostium, dicentes: Domine, aperi nobis: et respondens dicet vobis: Nescio vos unde sitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 26, 'tunc incipietis dicere: Manducavimus coram te, et bibimus, et in plateis nostris docuisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 27, 'Et dicet vobis: Nescio vos unde sitis: discedite a me omnes operarii iniquitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 28, 'Ibi erit fletus et stridor dentium: cum videritis Abraham, et Isaac, et Jacob, et omnes prophetas in regno Dei, vos autem expelli foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 29, 'Et venient ab oriente, et occidente, et aquilone, et austro, et accumbent in regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 30, 'Et ecce sunt novissimi qui erunt primi, et sunt primi qui erunt novissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 31, 'In ipsa die accesserunt quidam pharisæorum, dicentes illi: Exi, et vade hinc: quia Herodes vult te occidere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 32, 'Et ait illis: Ite, et dicite vulpi illi: Ecce ejicio dæmonia, et sanitates perficio hodie, et cras, et tertia die consummor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 33, 'Verumtamen oportet me hodie et cras et sequenti die ambulare: quia non capit prophetam perire extra Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 34, 'Jerusalem, Jerusalem, quæ occidis prophetas, et lapidas eos qui mittuntur ad te, quoties volui congregare filios tuos quemadmodum avis nidum suum sub pennis, et noluisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 35, 'Ecce relinquetur vobis domus vestra deserta. Dico autem vobis, quia non videbitis me donec veniat cum dicetis: Benedictus qui venit in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 1, 'Et factum est cum intraret Jesus in domum cujusdam principis pharisæorum sabbato manducare panem, et ipsi observabant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 2, 'Et ecce homo quidam hydropicus erat ante illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 3, 'Et respondens Jesus dixit ad legisperitos et pharisæos, dicens: Si licet sabbato curare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 4, 'At illi tacuerunt. Ipse vero apprehensum sanavit eum, ac dimisit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 5, 'Et respondens ad illos dixit: Cujus vestrum asinus, aut bos in puteum cadet, et non continuo extrahet illum die sabbati?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 6, 'Et non poterant ad hæc respondere illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 7, 'Dicebat autem et ad invitatos parabolam, intendens quomodo primos accubitus eligerent, dicens ad illos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 8, 'Cum invitatus fueris ad nuptias, non discumbas in primo loco, ne forte honoratior te sit invitatus ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 9, 'Et veniens is, qui te et illum vocavit, dicat tibi: Da huic locum: et tunc incipias cum rubore novissimum locum tenere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 10, 'Sed cum vocatus fueris, vade, recumbe in novissimo loco: ut, cum venerit qui te invitavit, dicat tibi: Amice, ascende superius. Tunc erit tibi gloria coram simul discumbentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 11, 'quia omnis, qui se exaltat, humiliabitur: et qui se humiliat, exaltabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 12, 'Dicebat autem et ei, qui invitaverat: Cum facis prandium, aut cœnam, noli vocare amicos tuos, neque fratres tuos, neque cognatos, neque vicinos divites: ne forte te et ipsi reinvitent, et fiat tibi retributio;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 13, 'sed cum facis convivium, voca pauperes, debiles, claudos, et cæcos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 14, 'et beatus eris, quia non habent retribuere tibi: retribuetur enim tibi in resurrectione justorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 15, 'Hæc cum audisset quidam de simul discumbentibus, dixit illi: Beatus qui manducabit panem in regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 16, 'At ipse dixit ei: Homo quidam fecit cœnam magnam, et vocavit multos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 17, 'Et misit servum suum hora cœnæ dicere invitatis ut venirent, quia jam parata sunt omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 18, 'Et cœperunt simul omnes excusare. Primus dixit ei: Villam emi, et necesse habeo exire, et videre illam: rogo te, habe me excusatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 19, 'Et alter dixit: Juga boum emi quinque, et eo probare illa: rogo te, habe me excusatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 20, 'Et alius dixit: Uxorem duxi, et ideo non possum venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 21, 'Et reversus servus nuntiavit hæc domino suo. Tunc iratus paterfamilias, dixit servo suo: Exi cito in plateas et vicos civitatis: et pauperes, ac debiles, et cæcos, et claudos introduc huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 22, 'Et ait servus: Domine, factum est ut imperasti, et adhuc locus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 23, 'Et ait dominus servo: Exi in vias, et sæpes: et compelle intrare, ut impleatur domus mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 24, 'Dico autem vobis quod nemo virorum illorum qui vocati sunt, gustabit cœnam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 25, 'Ibant autem turbæ multæ cum eo: et conversus dixit ad illos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 26, 'Si quis venit ad me, et non odit patrem suum, et matrem, et uxorem, et filios, et fratres, et sorores, adhuc autem et animam suam, non potest meus esse discipulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 27, 'Et qui non bajulat crucem suam, et venit post me, non potest meus esse discipulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 28, 'Quis enim ex vobis volens turrim ædificare, non prius sedens computat sumptus, qui necessarii sunt, si habeat ad perficiendum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 29, 'ne, posteaquam posuerit fundamentum, et non potuerit perficere, omnes qui vident, incipiant illudere ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 30, 'dicentes: Quia hic homo cœpit ædificare, et non potuit consummare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 31, 'Aut quis rex iturus committere bellum adversus alium regem, non sedens prius cogitat, si possit cum decem millibus occurrere ei, qui cum viginti millibus venit ad se?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 32, 'Alioquin adhuc illo longe agente, legationem mittens rogat ea quæ pacis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 33, 'Sic ergo omnis ex vobis, qui non renuntiat omnibus quæ possidet, non potest meus esse discipulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 34, 'Bonum est sal: si autem sal evanuerit, in quo condietur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 35, 'Neque in terram, neque in sterquilinium utile est, sed foras mittetur. Qui habet aures audiendi, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 1, 'Erant autem appropinquantes ei publicani, et peccatores ut audirent illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 2, 'Et murmurabant pharisæi, et scribæ, dicentes: Quia hic peccatores recipit, et manducat cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 3, 'Et ait ad illos parabolam istam dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 4, 'Quis ex vobis homo, qui habet centum oves, et si perdiderit unam ex illis, nonne dimittit nonaginta novem in deserto, et vadit ad illam quæ perierat, donec inveniat eam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 5, 'Et cum invenerit eam, imponit in humeros suos gaudens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 6, 'et veniens domum convocat amicos et vicinos, dicens illis: Congratulamini mihi, quia inveni ovem meam, quæ perierat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 7, 'Dico vobis quod ita gaudium erit in cælo super uno peccatore pœnitentiam agente, quam super nonaginta novem justis, qui non indigent pœnitentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 8, 'Aut quæ mulier habens drachmas decem, si perdiderit drachmam unam, nonne accendit lucernam, et everrit domum, et quærit diligenter, donec inveniat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 9, 'Et cum invenerit convocat amicas et vicinas, dicens: Congratulamini mihi, quia inveni drachmam quam perdideram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 10, 'Ita, dico vobis, gaudium erit coram angelis Dei super uno peccatore pœnitentiam agente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 11, 'Ait autem: Homo quidam habuit duos filios:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 12, 'et dixit adolescentior ex illis patri: Pater, da mihi portionem substantiæ, quæ me contingit. Et divisit illis substantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 13, 'Et non post multos dies, congregatis omnibus, adolescentior filius peregre profectus est in regionem longinquam, et ibi dissipavit substantiam suam vivendo luxuriose.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 14, 'Et postquam omnia consummasset, facta est fames valida in regione illa, et ipse cœpit egere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 15, 'Et abiit, et adhæsit uni civium regionis illius: et misit illum in villam suam ut pasceret porcos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 16, 'Et cupiebat implere ventrem suum de siliquis, quas porci manducabant: et nemo illi dabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 17, 'In se autem reversus, dixit: Quanti mercenarii in domo patris mei abundant panibus, ego autem hic fame pereo!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 18, 'surgam, et ibo ad patrem meum, et dicam ei: Pater, peccavi in cælum, et coram te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 19, 'jam non sum dignus vocari filius tuus: fac me sicut unum de mercenariis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 20, 'Et surgens venit ad patrem suum. Cum autem adhuc longe esset, vidit illum pater ipsius, et misericordia motus est, et accurrens cecidit super collum ejus, et osculatus est eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 21, 'Dixitque ei filius: Pater, peccavi in cælum, et coram te: jam non sum dignus vocari filius tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 22, 'Dixit autem pater ad servos suos: Cito proferte stolam primam, et induite illum, et date annulum in manum ejus, et calceamenta in pedes ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 23, 'et adducite vitulum saginatum, et occidite, et manducemus, et epulemur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 24, 'quia hic filius meus mortuus erat, et revixit: perierat, et inventus est. Et cœperunt epulari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 25, 'Erat autem filius ejus senior in agro: et cum veniret, et appropinquaret domui, audivit symphoniam et chorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 26, 'et vocavit unum de servis, et interrogavit quid hæc essent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 27, 'Isque dixit illi: Frater tuus venit, et occidit pater tuus vitulum saginatum, quia salvum illum recepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 28, 'Indignatus est autem, et nolebat introire. Pater ergo illius egressus, cœpit rogare illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 29, 'At ille respondens, dixit patri suo: Ecce tot annis servio tibi, et numquam mandatum tuum præterivi: et numquam dedisti mihi hædum ut cum amicis meis epularer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 30, 'Sed postquam filius tuus hic, qui devoravit substantiam suam cum meretricibus, venit, occidisti illi vitulum saginatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 31, 'At ipse dixit illi: Fili, tu semper mecum es, et omnia mea tua sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 32, 'epulari autem, et gaudere oportebat, quia frater tuus hic mortuus erat, et revixit; perierat, et inventus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 1, 'Dicebat autem et ad discipulos suos: Homo quidam erat dives, qui habebat villicum: et hic diffamatus est apud illum quasi dissipasset bona ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 2, 'Et vocavit illum, et ait illi: Quid hoc audio de te? redde rationem villicationis tuæ: jam enim non poteris villicare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 3, 'Ait autem villicus intra se: Quid faciam, quia dominus meus aufert a me villicationem? Fodere non valeo, mendicare erubesco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 4, 'Scio quid faciam, ut, cum amotus fuero a villicatione, recipiant me in domos suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 5, 'Convocatis itaque singulis debitoribus domini sui, dicebat primo: Quantum debes domino meo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 6, 'At ille dixit: Centum cados olei. Dixitque illi: Accipe cautionem tuam: et sede cito, scribe quinquaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 7, 'Deinde alii dixit: Tu vero quantum debes? Qui ait: Centum coros tritici. Ait illi: Accipe litteras tuas, et scribe octoginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 8, 'Et laudavit dominus villicum iniquitatis, quia prudenter fecisset: quia filii hujus sæculi prudentiores filiis lucis in generatione sua sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 9, 'Et ego vobis dico: facite vobis amicos de mammona iniquitatis: ut, cum defeceritis, recipiant vos in æterna tabernacula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 10, 'Qui fidelis est in minimo, et in majori fidelis est: et qui in modico iniquus est, et in majori iniquus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 11, 'Si ergo in iniquo mammona fideles non fuistis quod verum est, quis credet vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 12, 'Et si in alieno fideles non fuistis, quod vestrum est, quis dabit vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 13, 'Nemo servus potest duobus dominis servire: aut enim unum odiet, et alterum diliget: aut uni adhærebit, et alterum contemnet. Non potestis Deo servire et mammonæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 14, 'Audiebant autem omnia hæc pharisæi, qui erant avari: et deridebant illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 15, 'Et ait illis: Vos estis qui justificatis vos coram hominibus: Deus autem novit corda vestra: quia quod hominibus altum est, abominatio est ante Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 16, 'Lex et prophetæ usque ad Joannem: ex eo regnum Dei evangelizatur, et omnis in illud vim facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 17, 'Facilius est autem cælum et terram præterire, quam de lege unum apicem cadere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 18, 'Omnis qui dimittit uxorem suam et alteram ducit, mœchatur: et qui dimissam a viro ducit, mœchatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 19, 'Homo quidam erat dives, qui induebatur purpura et bysso, et epulabatur quotidie splendide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 20, 'Et erat quidam mendicus, nomine Lazarus, qui jacebat ad januam ejus, ulceribus plenus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 21, 'cupiens saturari de micis quæ cadebant de mensa divitis, et nemo illi dabat: sed et canes veniebant, et lingebant ulcera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 22, 'Factum est autem ut moreretur mendicus, et portaretur ab angelis in sinum Abrahæ. Mortuus est autem et dives, et sepultus est in inferno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 23, 'Elevans autem oculos suos, cum esset in tormentis, vidit Abraham a longe, et Lazarum in sinu ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 24, 'et ipse clamans dixit: Pater Abraham, miserere mei, et mitte Lazarum ut intingat extremum digiti sui in aquam, ut refrigeret linguam meam, quia crucior in hac flamma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 25, 'Et dixit illi Abraham: Fili, recordare quia recepisti bona in vita tua, et Lazarus similiter mala: nunc autem hic consolatur, tu vero cruciaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 26, 'et in his omnibus inter nos et vos chaos magnum firmatum est: ut hi qui volunt hinc transire ad vos, non possint, neque inde huc transmeare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 27, 'Et ait: Rogo ergo te, pater, ut mittas eum in domum patris mei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 28, 'habeo enim quinque fratres: ut testetur illis, ne et ipsi veniant in hunc locum tormentorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 29, 'Et ait illi Abraham: Habent Moysen et prophetas: audiant illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 30, 'At ille dixit: Non, pater Abraham: sed si quis ex mortuis ierit ad eos, pœnitentiam agent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 31, 'Ait autem illi: Si Moysen et prophetas non audiunt, neque si quis ex mortuis resurrexerit, credent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 1, 'Et ait ad discipulos suos: Impossibile est ut non veniant scandala: væ autem illi per quem veniunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 2, 'Utilius est illi si lapis molaris imponatur circa collum ejus, et projiciatur in mare quam ut scandalizet unum de pusillis istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 3, 'Attendite vobis: Si peccaverit in te frater tuus, increpa illum: et si pœnitentiam egerit, dimitte illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 4, 'Et si septies in die peccaverit in te, et septies in die conversus fuerit ad te, dicens: Pœnitet me, dimitte illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 5, 'Et dixerunt apostoli Domino: Adauge nobis fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 6, 'Dixit autem Dominus: Si habueritis fidem sicut granum sinapis, dicetis huic arbori moro: Eradicare, et transplantare in mare, et obediet vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 7, 'Quis autem vestrum habens servum arantem aut pascentem, qui regresso de agro dicat illi: Statim transi, recumbe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 8, 'et non dicat ei: Para quod cœnem, et præcinge te, et ministra mihi donec manducem, et bibam, et post hæc tu manducabis, et bibes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 9, 'Numquid gratiam habet servo illi, quia fecit quæ ei imperaverat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 10, 'non puto. Sic et vos cum feceritis omnia quæ præcepta sunt vobis, dicite: Servi inutiles sumus: quod debuimus facere, fecimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 11, 'Et factum est, dum iret in Jerusalem, transibat per mediam Samariam et Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 12, 'Et cum ingrederetur quoddam castellum, occurrerunt ei decem viri leprosi, qui steterunt a longe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 13, 'et levaverunt vocem, dicentes: Jesu præceptor, miserere nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 14, 'Quos ut vidit, dixit: Ite, ostendite vos sacerdotibus. Et factum est, dum irent, mundati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 15, 'Unus autem ex illis, ut vidit quia mundatus est, regressus est, cum magna voce magnificans Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 16, 'et cecidit in faciem ante pedes ejus, gratias agens: et hic erat Samaritanus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 17, 'Respondens autem Jesus, dixit: Nonne decem mundati sunt? et novem ubi sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 18, 'Non est inventus qui rediret, et daret gloriam Deo, nisi hic alienigena.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 19, 'Et ait illi: Surge, vade: quia fides tua te salvum fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 20, 'Interrogatus autem a pharisæis: Quando venit regnum Dei? respondens eis, dixit: Non venit regnum Dei cum observatione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 21, 'neque dicent: Ecce hic, aut ecce illic. Ecce enim regnum Dei intra vos est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 22, 'Et ait ad discipulos suos: Venient dies quando desideretis videre unum diem Filii hominis, et non videbitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 23, 'Et dicent vobis: Ecce hic, et ecce illic. Nolite ire, neque sectemini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 24, 'nam, sicut fulgur coruscans de sub cælo in ea quæ sub cælo sunt, fulget: ita erit Filius hominis in die sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 25, 'Primum autem oportet illum multa pati, et reprobari a generatione hac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 26, 'Et sicut factum est in diebus Noë, ita erit et in diebus Filii hominis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 27, 'edebant et bibebant: uxores ducebant et dabantur ad nuptias, usque in diem, qua intravit Noë in arcam: et venit diluvium, et perdidit omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 28, 'Similiter sicut factum est in diebus Lot: edebant et bibebant, emebant et vendebant, plantabant et ædificabant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 29, 'qua die autem exiit Lot a Sodomis, pluit ignem et sulphur de cælo, et omnes perdidit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 30, 'secundum hæc erit qua die Filius hominis revelabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 31, 'In illa hora, qui fuerit in tecto, et vasa ejus in domo, ne descendat tollere illa: et qui in agro, similiter non redeat retro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 32, 'Memores estote uxoris Lot.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 33, 'Quicumque quæsierit animam suam salvam facere, perdet illam: et quicumque perdiderit illam, vivificabit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 34, 'Dico vobis: In illa nocte erunt duo in lecto uno: unus assumetur, et alter relinquetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 35, 'duæ erunt molentes in unum: una assumetur, et altera relinquetur: duo in agro: unus assumetur, et alter relinquetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 36, 'Respondentes dicunt illi: Ubi Domine?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 17, 37, 'Qui dixit illis: Ubicumque fuerit corpus, illuc congregabuntur et aquilæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 1, 'Dicebat autem et parabolam ad illos, quoniam oportet semper orare et non deficere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 2, 'dicens: Judex quidam erat in quadam civitate, qui Deum non timebat, et hominem non reverebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 3, 'Vidua autem quædam erat in civitate illa, et veniebat ad eum, dicens: Vindica me de adversario meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 4, 'Et nolebat per multum tempus. Post hæc autem dixit intra se: Etsi Deum non timeo, nec hominem revereor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 5, 'tamen quia molesta est mihi hæc vidua, vindicabo illam, ne in novissimo veniens sugillet me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 6, 'Ait autem Dominus: Audite quid judex iniquitatis dicit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 7, 'Deus autem non faciet vindictam electorum suorum clamantium ad se die ac nocte, et patientiam habebit in illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 8, 'Dico vobis quia cito faciet vindictam illorum. Verumtamen Filius hominis veniens, putas, inveniet fidem in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 9, 'Dixit autem et ad quosdam qui in se confidebant tamquam justi, et aspernabantur ceteros, parabolam istam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 10, 'Duo homines ascenderunt in templum ut orarent: unus pharisæus et alter publicanus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 11, 'Pharisæus stans, hæc apud se orabat: Deus, gratias ago tibi, quia non sum sicut ceteri hominum: raptores, injusti, adulteri, velut etiam hic publicanus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 12, 'jejuno bis in sabbato, decimas do omnium quæ possideo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 13, 'Et publicanus a longe stans, nolebat nec oculos ad cælum levare: sed percutiebat pectus suum, dicens: Deus propitius esto mihi peccatori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 14, 'Dico vobis, descendit hic justificatus in domum suam ab illo: quia omnis qui se exaltat, humiliabitur, et qui se humiliat, exaltabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 15, 'Afferebant autem ad illum et infantes, ut eos tangeret. Quod cum viderent discipuli, increpabant illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 16, 'Jesus autem convocans illos, dixit: Sinite pueros venire ad me, et nolite vetare eos: talium est enim regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 17, 'Amen dico vobis, quicumque non acceperit regnum Dei sicut puer, non intrabit in illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 18, 'Et interrogavit eum quidam princeps, dicens: Magister bone, quid faciens vitam æternam possidebo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 19, 'Dixit autem ei Jesus: Quid me dicis bonum? nemo bonus nisi solus Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 20, 'Mandata nosti: non occides; non mœchaberis; non furtum facies; non falsum testimonium dices; honora patrem tuum et matrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 21, 'Qui ait: Hæc omnia custodivi a juventute mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 22, 'Quo audito, Jesus ait ei: Adhuc unum tibi deest: omnia quæcumque habes vende, et da pauperibus, et habebis thesaurum in cælo: et veni, sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 23, 'His ille auditis, contristatus est: quia dives erat valde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 24, 'Videns autem Jesus illum tristem factum, dixit: Quam difficile, qui pecunias habent, in regnum Dei intrabunt!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 25, 'facilius est enim camelum per foramen acus transire quam divitem intrare in regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 26, 'Et dixerunt qui audiebant: Et quis potest salvus fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 27, 'Ait illis: Quæ impossibilia sunt apud homines, possibilia sunt apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 28, 'Ait autem Petrus: Ecce nos dimisimus omnia et secuti sumus te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 29, 'Qui dixit eis: Amen dico vobis, nemo est qui reliquit domum, aut parentes, aut fratres, aut uxorem, aut filios propter regnum Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 30, 'et non recipiat multo plura in hoc tempore, et in sæculo venturo vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 31, 'Assumpsit autem Jesus duodecim, et ait illis: Ecce ascendimus Jerosolymam, et consummabuntur omnia quæ scripta sunt per prophetas de Filio hominis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 32, 'tradetur enim gentibus, et illudetur, et flagellabitur, et conspuetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 33, 'et postquam flagellaverint, occident eum, et tertia die resurget.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 34, 'Et ipsi nihil horum intellexerunt, et erat verbum istud absconditum ab eis, et non intelligebant quæ dicebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 35, 'Factum est autem, cum appropinquaret Jericho, cæcus quidam sedebat secus viam, mendicans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 36, 'Et cum audiret turbam prætereuntem, interrogabat quid hoc esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 37, 'Dixerunt autem ei quod Jesus Nazarenus transiret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 38, 'Et clamavit, dicens: Jesu, fili David, miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 39, 'Et qui præibant, increpabant eum ut taceret. Ipse vero multo magis clamabat: Fili David, miserere mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 40, 'Stans autem Jesus jussit illum adduci ad se. Et cum appropinquasset, interrogavit illum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 41, 'dicens: Quid tibi vis faciam? At ille dixit: Domine, ut videam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 42, 'Et Jesus dixit illi: Respice, fides tua te salvum fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 18, 43, 'Et confestim vidit, et sequebatur illum magnificans Deum. Et omnis plebs ut vidit, dedit laudem Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 1, 'Et ingressus perambulabat Jericho.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 2, 'Et ecce vir nomine Zachæus: et hic princeps erat publicanorum, et ipse dives:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 3, 'et quærebat videre Jesum, quis esset: et non poterat præ turba, quia statura pusillus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 4, 'Et præcurrens ascendit in arborem sycomorum ut videret eum: quia inde erat transiturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 5, 'Et cum venisset ad locum, suspiciens Jesus vidit illum, et dixit ad eum: Zachæe, festinans descende: quia hodie in domo tua oportet me manere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 6, 'Et festinans descendit, et excepit illum gaudens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 7, 'Et cum viderent omnes, murmurabant, dicentes quod ad hominem peccatorem divertisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 8, 'Stans autem Zachæus, dixit ad Dominum: Ecce dimidium bonorum meorum, Domine, do pauperibus: et si quid aliquem defraudavi, reddo quadruplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 9, 'Ait Jesus ad eum: Quia hodie salus domui huic facta est: eo quod et ipse filius sit Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 10, 'Venit enim Filius hominis quærere, et salvum facere quod perierat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 11, 'Hæc illis audientibus adjiciens, dixit parabolam, eo quod esset prope Jerusalem: et quia existimarent quod confestim regnum Dei manifestaretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 12, 'Dixit ergo: Homo quidam nobilis abiit in regionem longinquam accipere sibi regnum, et reverti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 13, 'Vocatis autem decem servis suis, dedit eis decem mnas, et ait ad illos: Negotiamini dum venio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 14, 'Cives autem ejus oderant eum: et miserunt legationem post illum, dicentes: Nolumus hunc regnare super nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 15, 'Et factum est ut rediret accepto regno: et jussit vocari servos, quibus dedit pecuniam, ut sciret quantum quisque negotiatus esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 16, 'Venit autem primus dicens: Domine, mna tua decem mnas acquisivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 17, 'Et ait illi: Euge bone serve, quia in modico fuisti fidelis, eris potestatem habens super decem civitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 18, 'Et alter venit, dicens: Domine, mna tua fecit quinque mnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 19, 'Et huic ait: Et tu esto super quinque civitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 20, 'Et alter venit, dicens: Domine, ecce mna tua, quam habui repositam in sudario:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 21, 'timui enim te, quia homo austerus es: tollis quod non posuisti, et metis quod non seminasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 22, 'Dicit ei: De ore tuo te judico, serve nequam. Sciebas quod ego homo austerus sum, tollens quod non posui, et metens quod non seminavi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 23, 'et quare non dedisti pecuniam meam ad mensam, ut ego veniens cum usuris utique exegissem illam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 24, 'Et astantibus dixit: Auferte ab illo mnam, et date illi qui decem mnas habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 25, 'Et dixerunt ei: Domine, habet decem mnas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 26, 'Dico autem vobis, quia omni habenti dabitur, et abundabit: ab eo autem qui non habet, et quod habet auferetur ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 27, 'Verumtamen inimicos meos illos, qui noluerunt me regnare super se, adducite huc: et interficite ante me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 28, 'Et his dictis, præcedebat ascendens Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 29, 'Et factum est, cum appropinquasset ad Bethphage et Bethaniam, ad montem qui vocatur Oliveti, misit duos discipulos suos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 30, 'dicens: Ite in castellum quod contra est: in quod introëuntes, invenietis pullum asinæ alligatum, cui nemo umquam hominum sedit: solvite illum, et adducite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 31, 'Et si quis vos interrogaverit: Quare solvitis? sic dicetis ei: Quia Dominus operam ejus desiderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 32, 'Abierunt autem qui missi erant: et invenerunt, sicut dixit illis, stantem pullum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 33, 'Solventibus autem illis pullum, dixerunt domini ejus ad illos: Quid solvitis pullum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 34, 'At illi dixerunt: Quia Dominus eum necessarium habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 35, 'Et duxerunt illum ad Jesum. Et jactantes vestimenta sua supra pullum, imposuerunt Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 36, 'Eunte autem illo, substernebant vestimenta sua in via:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 37, 'et cum appropinquaret jam ad descensum montis Oliveti, cœperunt omnes turbæ discipulorum gaudentes laudare Deum voce magna super omnibus, quas viderant, virtutibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 38, 'dicentes: Benedictus, qui venit rex in nomine Domini: pax in cælo, et gloria in excelsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 39, 'Et quidam pharisæorum de turbis dixerunt ad illum: Magister, increpa discipulos tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 40, 'Quibus ipse ait: Dico vobis, quia si hi tacuerint, lapides clamabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 41, 'Et ut appropinquavit, videns civitatem flevit super illam, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 42, 'Quia si cognovisses et tu, et quidem in hac die tua, quæ ad pacem tibi: nunc autem abscondita sunt ab oculis tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 43, 'Quia venient dies in te: et circumdabunt te inimici tui vallo, et circumdabunt te: et coangustabunt te undique:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 44, 'et ad terram prosternent te, et filios tuos, qui in te sunt, et non relinquent in te lapidem super lapidem: eo quod non cognoveris tempus visitationis tuæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 45, 'Et ingressus in templum, cœpit ejicere vendentes in illo, et ementes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 46, 'dicens illis: Scriptum est: Quia domus mea domus orationis est: vos autem fecistis illam speluncam latronum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 47, 'Et erat docens quotidie in templo. Principes autem sacerdotum, et scribæ, et princeps plebis quærebant illum perdere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 19, 48, 'et non inveniebant quid facerent illi. Omnis enim populus suspensus erat, audiens illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 1, 'Et factum est in una dierum, docente illo populum in templo, et evangelizante, convenerunt principes sacerdotum, et scribæ cum senioribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 2, 'et aiunt dicentes ad illum: Dic nobis in qua potestate hæc facis? aut quis est qui dedit tibi hanc potestatem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 3, 'Respondens autem Jesus, dixit ad illos: Interrogabo vos et ego unum verbum. Respondete mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 4, 'baptismus Joannis de cælo erat, an ex hominibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 5, 'At illi cogitabant intra se, dicentes: Quia si dixerimus: De cælo, dicet: Quare ergo non credidistis illi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 6, 'Si autem dixerimus: Ex hominibus, plebs universa lapidabit nos: certi sunt enim Joannem prophetam esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 7, 'Et responderunt se nescire unde esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 8, 'Et Jesus ait illis: Neque ego dico vobis in qua potestate hæc facio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 9, 'Cœpit autem dicere ad plebem parabolam hanc: Homo plantavit vineam, et locavit eam colonis: et ipse peregre fuit multis temporibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 10, 'Et in tempore misit ad cultores servum, ut de fructu vineæ darent illi. Qui cæsum dimiserunt eum inanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 11, 'Et addidit alterum servum mittere. Illi autem hunc quoque cædentes, et afficientes contumelia, dimiserunt inanem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 12, 'Et addidit tertium mittere: qui et illum vulnerantes ejecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 13, 'Dixit autem dominus vineæ: Quid faciam? Mittam filium meum dilectum: forsitan, cum hunc viderint, verebuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 14, 'Quem cum vidissent coloni, cogitaverunt intra se, dicentes: Hic est hæres, occidamus illum, ut nostra fiat hæreditas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 15, 'Et ejectum illum extra vineam, occiderunt. Quid ergo faciet illis dominus vineæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 16, 'veniet, et perdet colonos istos, et dabit vineam aliis. Quo audito, dixerunt illi: Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 17, 'Ille autem aspiciens eos, ait: Quid est ergo hoc quod scriptum est: Lapidem quem reprobaverunt ædificantes, hic factus est in caput anguli?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 18, 'Omnis qui ceciderit super illum lapidem, conquassabitur: super quem autem ceciderit, comminuet illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 19, 'Et quærebant principes sacerdotum et scribæ mittere in illum manus illa hora, et timuerunt populum: cognoverunt enim quod ad ipsos dixerit similitudinem hanc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 20, 'Et observantes miserunt insidiatores, qui se justos simularent, ut caperent eum in sermone, ut traderent illum principatui, et potestati præsidis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 21, 'Et interrogaverunt eum, dicentes: Magister, scimus quia recte dicis et doces: et non accipis personam, sed viam Dei in veritate doces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 22, 'Licet nobis tributum dare Cæsari, an non?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 23, 'Considerans autem dolum illorum, dixit ad eos: Quid me tentatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 24, 'ostendite mihi denarium. Cujus habet imaginem et inscriptionem? Respondentes dixerunt ei: Cæsaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 25, 'Et ait illis: Reddite ergo quæ sunt Cæsaris, Cæsari: et quæ sunt Dei, Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 26, 'Et non potuerunt verbum ejus reprehendere coram plebe: et mirati in responso ejus, tacuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 27, 'Accesserunt autem quidam sadducæorum, qui negant esse resurrectionem, et interrogaverunt eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 28, 'dicentes: Magister, Moyses scripsit nobis: Si frater alicujus mortuus fuerit habens uxorem, et hic sine liberis fuerit, ut accipiat eam frater ejus uxorem, et suscitet semen fratri suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 29, 'Septem ergo fratres erant: et primus accepit uxorem, et mortuus est sine filiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 30, 'Et sequens accepit illam, et ipse mortuus est sine filio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 31, 'Et tertius accepit illam. Similiter et omnes septem, et non reliquerunt semen, et mortui sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 32, 'Novissime omnium mortua est et mulier.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 33, 'In resurrectione ergo, cujus eorum erit uxor? siquidem septem habuerunt eam uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 34, 'Et ait illis Jesus: Filii hujus sæculi nubunt, et traduntur ad nuptias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 35, 'illi vero qui digni habebuntur sæculo illo, et resurrectione ex mortuis, neque nubent, neque ducent uxores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 36, 'neque enim ultra mori potuerunt: æquales enim angelis sunt, et filii sunt Dei, cum sint filii resurrectionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 37, 'Quia vero resurgant mortui, et Moyses ostendit secus rubum, sicut dicit Dominum, Deum Abraham, et Deum Isaac, et Deum Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 38, 'Deus autem non est mortuorum, sed vivorum: omnes enim vivunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 39, 'Respondentes autem quidam scribarum, dixerunt ei: Magister, bene dixisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 40, 'Et amplius non audebant eum quidquam interrogare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 41, 'Dixit autem ad illos: Quomodo dicunt Christum filium esse David?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 42, 'et ipse David dicit in libro Psalmorum: Dixit Dominus Domino meo: sede a dextris meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 43, 'donec ponam inimicos tuos scabellum pedum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 44, 'David ergo Dominum illum vocat: et quomodo filius ejus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 45, 'Audiente autem omni populo, dixit discipulis suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 46, 'Attendite a scribis, qui volunt ambulare in stolis, et amant salutationes in foro, et primas cathedras in synagogis, et primos discubitus in conviviis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 20, 47, 'qui devorant domos viduarum, simulantes longam orationem: hi accipient damnationem majorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 1, 'Respiciens autem, vidit eos qui mittebant munera sua in gazophylacium, divites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 2, 'Vidit autem et quamdam viduam pauperculam mittentem æra minuta duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 3, 'Et dixit: Vere dico vobis, quia vidua hæc pauper plus quam omnes misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 4, 'Nam omnes hi ex abundanti sibi miserunt in munera Dei: hæc autem ex eo quod deest illi, omnem victum suum quem habuit, misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 5, 'Et quibusdam dicentibus de templo quod bonis lapidibus et donis ornatum esset, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 6, 'Hæc quæ videtis, venient dies in quibus non relinquetur lapis super lapidem, qui non destruatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 7, 'Interrogaverunt autem illum, dicentes: Præceptor, quando hæc erunt, et quod signum cum fieri incipient?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 8, 'Qui dixit: Videte ne seducamini: multi enim venient in nomine meo, dicentes quia ego sum: et tempus appropinquavit: nolite ergo ire post eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 9, 'Cum autem audieritis prælia et seditiones, nolite terreri: oportet primum hæc fieri, sed nondum statim finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 10, 'Tunc dicebat illis: Surget gens contra gentem, et regnum adversus regnum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 11, 'Et terræmotus magni erunt per loca, et pestilentiæ, et fames, terroresque de cælo, et signa magna erunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 12, 'Sed ante hæc omnia injicient vobis manus suas, et persequentur tradentes in synagogas et custodias, trahentes ad reges et præsides propter nomen meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 13, 'continget autem vobis in testimonium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 14, 'Ponite ergo in cordibus vestris non præmeditari quemadmodum respondeatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 15, 'ego enim dabo vobis os et sapientiam, cui non poterunt resistere et contradicere omnes adversarii vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 16, 'Trademini autem a parentibus, et fratribus, et cognatis, et amicis, et morte afficient ex vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 17, 'et eritis odio omnibus propter nomen meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 18, 'et capillus de capite vestro non peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 19, 'In patientia vestra possidebitis animas vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 20, 'Cum autem videritis circumdari ab exercitu Jerusalem, tunc scitote quia appropinquavit desolatio ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 21, 'tunc qui in Judæa sunt, fugiant ad montes, et qui in medio ejus, discedant: et qui in regionibus, non intrent in eam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 22, 'quia dies ultionis hi sunt, ut impleantur omnia quæ scripta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 23, 'Væ autem prægnantibus et nutrientibus in illis diebus! erit enim pressura magna super terram, et ira populo huic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 24, 'Et cadent in ore gladii, et captivi ducentur in omnes gentes, et Jerusalem calcabitur a gentibus, donec impleantur tempora nationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 25, 'Et erunt signa in sole, et luna, et stellis, et in terris pressura gentium præ confusione sonitus maris, et fluctuum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 26, 'arescentibus hominibus præ timore, et exspectatione, quæ supervenient universo orbi: nam virtutes cælorum movebuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 27, 'et tunc videbunt Filium hominis venientem in nube cum potestate magna et majestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 28, 'His autem fieri incipientibus, respicite, et levate capita vestra: quoniam appropinquat redemptio vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 29, 'Et dixit illis similitudinem: Videte ficulneam, et omnes arbores:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 30, 'cum producunt jam ex se fructum, scitis quoniam prope est æstas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 31, 'Ita et vos cum videritis hæc fieri, scitote quoniam prope est regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 32, 'Amen dico vobis, quia non præteribit generatio hæc, donec omnia fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 33, 'Cælum et terra transibunt: verba autem mea non transibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 34, 'Attendite autem vobis, ne forte graventur corda vestra in crapula, et ebrietate, et curis hujus vitæ, et superveniat in vos repentina dies illa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 35, 'tamquam laqueus enim superveniet in omnes qui sedent super faciem omnis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 36, 'Vigilate itaque, omni tempore orantes, ut digni habeamini fugere ista omnia quæ futura sunt, et stare ante Filium hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 37, 'Erat autem diebus docens in templo: noctibus vero exiens, morabatur in monte qui vocatur Oliveti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 21, 38, 'Et omnis populus manicabat ad eum in templo audire eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 1, 'Appropinquabat autem dies festus azymorum, qui dicitur Pascha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 2, 'et quærebant principes sacerdotum, et scribæ, quomodo Jesum interficerent: timebant vero plebem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 3, 'Intravit autem Satanas in Judam, qui cognominabatur Iscariotes, unum de duodecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 4, 'et abiit, et locutus est cum principibus sacerdotum, et magistratibus, quemadmodum illum traderet eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 5, 'Et gavisi sunt, et pacti sunt pecuniam illi dare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 6, 'Et spopondit, et quærebat opportunitatem ut traderet illum sine turbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 7, 'Venit autem dies azymorum, in qua necesse erat occidi pascha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 8, 'Et misit Petrum et Joannem, dicens: Euntes parate nobis pascha, ut manducemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 9, 'At illi dixerunt: Ubi vis paremus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 10, 'Et dixit ad eos: Ecce introëuntibus vobis in civitatem occurret vobis homo quidam amphoram aquæ portans: sequimini eum in domum, in quam intrat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 11, 'et dicetis patrifamilias domus: Dicit tibi Magister: Ubi est diversorium, ubi pascha cum discipulis meis manducem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 12, 'Et ipse ostendet vobis cœnaculum magnum stratum, et ibi parate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 13, 'Euntes autem invenerunt sicut dixit illis, et paraverunt pascha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 14, 'Et cum facta esset hora, discubuit, et duodecim apostoli cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 15, 'Et ait illis: Desiderio desideravi hoc pascha manducare vobiscum, antequam patiar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 16, 'Dico enim vobis, quia ex hoc non manducabo illud, donec impleatur in regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 17, 'Et accepto calice gratias egit, et dixit: Accipite, et dividite inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 18, 'Dico enim vobis quod non bibam de generatione vitis donec regnum Dei veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 19, 'Et accepto pane gratias egit, et fregit, et dedit eis, dicens: Hoc est corpus meum, quod pro vobis datur: hoc facite in meam commemorationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 20, 'Similiter et calicem, postquam cœnavit, dicens: Hic est calix novum testamentum in sanguine meo, qui pro vobis fundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 21, 'Verumtamen ecce manus tradentis me, mecum est in mensa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 22, 'Et quidem Filius hominis, secundum quod definitum est, vadit: verumtamen væ homini illi per quem tradetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 23, 'Et ipsi cœperunt quærere inter se quis esset ex eis qui hoc facturus esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 24, 'Facta est autem et contentio inter eos, quis eorum videretur esse major.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 25, 'Dixit autem eis: Reges gentium dominantur eorum: et qui potestatem habent super eos, benefici vocantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 26, 'Vos autem non sic: sed qui major est in vobis, fiat sicut minor: et qui præcessor est, sicut ministrator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 27, 'Nam quis major est, qui recumbit, an qui ministrat? nonne qui recumbit? Ego autem in medio vestrum sum, sicut qui ministrat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 28, 'vos autem estis, qui permansistis mecum in tentationibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 29, 'Et ego dispono vobis sicut disposuit mihi Pater meus regnum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 30, 'ut edatis et bibatis super mensam meam in regno meo, et sedeatis super thronos judicantes duodecim tribus Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 31, 'Ait autem Dominus: Simon, Simon, ecce Satanas expetivit vos ut cribraret sicut triticum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 32, 'ego autem rogavi pro te ut non deficiat fides tua: et tu aliquando conversus, confirma fratres tuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 33, 'Qui dixit ei: Domine, tecum paratus sum et in carcerem et in mortem ire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 34, 'At ille dixit: Dico tibi, Petre, non cantabit hodie gallus, donec ter abneges nosse me. Et dixit eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 35, 'Quando misi vos sine sacculo, et pera, et calceamentis, numquid aliquid defuit vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 36, 'At illi dixerunt: Nihil. Dixit ergo eis: Sed nunc qui habet sacculum, tollat; similiter et peram: et qui non habet, vendat tunicam suam et emat gladium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 37, 'Dico enim vobis, quoniam adhuc hoc quod scriptum est, oportet impleri in me: Et cum iniquis deputatus est. Etenim ea quæ sunt de me finem habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 38, 'At illi dixerunt: Domine, ecce duo gladii hic. At ille dixit eis: Satis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 39, 'Et egressus ibat secundum consuetudinem in monte Olivarum. Secuti sunt autem illum et discipuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 40, 'Et cum pervenisset ad locum, dixit illis: Orate ne intretis in tentationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 41, 'Et ipse avulsus est ab eis quantum jactus est lapidis: et positis genibus orabat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 42, 'dicens: Pater, si vis, transfer calicem istum a me: verumtamen non mea voluntas, sed tua fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 43, 'Apparuit autem illi angelus de cælo, confortans eum. Et factus in agonia, prolixius orabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 44, 'Et factus est sudor ejus sicut guttæ sanguinis decurrentis in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 45, 'Et cum surrexisset ab oratione et venisset ad discipulos suos, invenit eos dormientes præ tristitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 46, 'Et ait illis: Quid dormitis? surgite, orate, ne intretis in tentationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 47, 'Adhuc eo loquente, ecce turba: et qui vocabatur Judas, unus de duodecim, antecedebat eos, et appropinquavit Jesu ut oscularetur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 48, 'Jesus autem dixit illi: Juda, osculo Filium hominis tradis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 49, 'Videntes autem hi qui circa ipsum erant, quod futurum erat, dixerunt ei: Domine, si percutimus in gladio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 50, 'Et percussit unus ex illis servum principis sacerdotum, et amputavit auriculam ejus dexteram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 51, 'Respondens autem Jesus, ait: Sinite usque huc. Et cum tetigisset auriculam ejus, sanavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 52, 'Dixit autem Jesus ad eos qui venerant ad se principes sacerdotum, et magistratus templi, et seniores: Quasi ad latronem existis cum gladiis et fustibus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 53, 'Cum quotidie vobiscum fuerim in templo, non extendistis manus in me: sed hæc est hora vestra, et potestas tenebrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 54, 'Comprehendentes autem eum, duxerunt ad domum principis sacerdotum: Petrus vero sequebatur a longe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 55, 'Accenso autem igne in medio atrii et circumsedentibus illis, erat Petrus in medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 56, 'Quem cum vidisset ancilla quædam sedentem ad lumen, et eum fuisset intuita, dixit: Et hic cum illo erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 57, 'At ille negavit eum, dicens: Mulier, non novi illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 58, 'Et post pusillum alius videns eum, dixit: Et tu de illis es. Petrus vero ait: O homo, non sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 59, 'Et intervallo facto quasi horæ unius, alius quidam affirmabat, dicens: Vere et hic cum illo erat: nam et Galilæus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 60, 'Et ait Petrus: Homo, nescio quid dicis. Et continuo, adhuc illo loquente, cantavit gallus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 61, 'Et conversus Dominus respexit Petrum, et recordatus est Petrus verbi Domini, sicut dixerat: Quia priusquam gallus cantet, ter me negabis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 62, 'Et egressus foras Petrus flevit amare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 63, 'Et viri qui tenebant illum, illudebant ei, cædentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 64, 'Et velaverunt eum, et percutiebant faciem ejus: et interrogabant eum, dicentes: Prophetiza, quis est, qui te percussit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 65, 'Et alia multa blasphemantes dicebant in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 66, 'Et ut factus est dies, convenerunt seniores plebis, et principes sacerdotum, et scribæ, et duxerunt illum in concilium suum, dicentes: Si tu es Christus, dic nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 67, 'Et ait illis: Si vobis dixero, non credetis mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 68, 'si autem et interrogavero, non respondebitis mihi, neque dimittetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 69, 'Ex hoc autem erit Filius hominis sedens a dextris virtutis Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 70, 'Dixerunt autem omnes: Tu ergo es Filius Dei? Qui ait: Vos dicitis, quia ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 22, 71, 'At illi dixerunt: Quid adhuc desideramus testimonium? ipsi enim audivimus de ore ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 1, 'Et surgens omnis multitudo eorum, duxerunt illum ad Pilatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 2, 'Cœperunt autem illum accusare, dicentes: Hunc invenimus subvertentem gentem nostram, et prohibentem tributa dare Cæsari, et dicentem se Christum regem esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 3, 'Pilatus autem interrogavit eum, dicens: Tu es rex Judæorum? At ille respondens ait: Tu dicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 4, 'Ait autem Pilatus ad principes sacerdotum et turbas: Nihil invenio causæ in hoc homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 5, 'At illi invalescebant, dicentes: Commovet populum docens per universam Judæam, incipiens a Galilæa usque huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 6, 'Pilatus autem audiens Galilæam, interrogavit si homo Galilæus esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 7, 'Et ut cognovit quod de Herodis potestate esset, remisit eum ad Herodem, qui et ipse Jerosolymis erat illis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 8, 'Herodes autem viso Jesu, gavisus est valde. Erat enim cupiens ex multo tempore videre eum, eo quod audierat multa de eo, et sperabat signum aliquod videre ab eo fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 9, 'Interrogabat autem eum multis sermonibus. At ipse nihil illi respondebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 10, 'Stabant autem principes sacerdotum et scribæ constanter accusantes eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 11, 'Sprevit autem illum Herodes cum exercitu suo: et illusit indutum veste alba, et remisit ad Pilatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 12, 'Et facti sunt amici Herodes et Pilatus in ipsa die: nam antea inimici erant ad invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 13, 'Pilatus autem, convocatis principibus sacerdotum, et magistratibus, et plebe,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 14, 'dixit ad illos: Obtulistis mihi hunc hominem, quasi avertentem populum, et ecce ego coram vobis interrogans, nullam causam inveni in homine isto ex his in quibus eum accusatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 15, 'Sed neque Herodes: nam remisi vos ad illum, et ecce nihil dignum morte actum est ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 16, 'Emendatum ergo illum dimittam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 17, 'Necesse autem habebat dimittere eis per diem festum unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 18, 'Exclamavit autem simul universa turba, dicens: Tolle hunc, et dimitte nobis Barabbam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 19, 'qui erat propter seditionem quamdam factam in civitate et homicidium missus in carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 20, 'Iterum autem Pilatus locutus est ad eos, volens dimittere Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 21, 'At illi succlamabant, dicentes: Crucifige, crucifige eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 22, 'Ille autem tertio dixit ad illos: Quid enim mali fecit iste? nullam causam mortis invenio in eo: corripiam ergo illum et dimittam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 23, 'At illi instabant vocibus magnis postulantes ut crucifigeretur: et invalescebant voces eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 24, 'Et Pilatus adjudicavit fieri petitionem eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 25, 'Dimisit autem illis eum qui propter homicidium et seditionem missus fuerat in carcerem, quem petebant: Jesum vero tradidit voluntati eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 26, 'Et cum ducerent eum, apprehenderunt Simonem quemdam Cyrenensem venientem de villa: et imposuerunt illi crucem portare post Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 27, 'Sequebatur autem illum multa turba populi et mulierum, quæ plangebant et lamentabantur eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 28, 'Conversus autem ad illas Jesus, dixit: Filiæ Jerusalem, nolite flere super me, sed super vos ipsas flete et super filios vestros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 29, 'Quoniam ecce venient dies in quibus dicent: Beatæ steriles, et ventres qui non genuerunt, et ubera quæ non lactaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 30, 'Tunc incipient dicere montibus: Cadite super nos; et collibus: Operite nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 31, 'Quia si in viridi ligno hæc faciunt, in arido quid fiet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 32, 'Ducebantur autem et alii duo nequam cum eo, ut interficerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 33, 'Et postquam venerunt in locum qui vocatur Calvariæ, ibi crucifixerunt eum: et latrones, unum a dextris, et alterum a sinistris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 34, 'Jesus autem dicebat: Pater, dimitte illis: non enim sciunt quid faciunt. Dividentes vero vestimenta ejus, miserunt sortes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 35, 'Et stabat populus spectans, et deridebant eum principes cum eis, dicentes: Alios salvos fecit, se salvum faciat, si hic est Christus Dei electus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 36, 'Illudebant autem ei et milites accedentes, et acetum offerentes ei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 37, 'et dicentes: Si tu es rex Judæorum, salvum te fac.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 38, 'Erat autem et superscriptio scripta super eum litteris græcis, et latinis, et hebraicis: Hic est rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 39, 'Unus autem de his, qui pendebant, latronibus, blasphemabat eum, dicens: Si tu es Christus, salvum fac temetipsum et nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 40, 'Respondens autem alter increpabat eum, dicens: Neque tu times Deum, quod in eadem damnatione es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 41, 'Et nos quidem juste, nam digna factis recipimus: hic vero nihil mali gessit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 42, 'Et dicebat ad Jesum: Domine, memento mei cum veneris in regnum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 43, 'Et dixit illi Jesus: Amen dico tibi: hodie mecum eris in paradiso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 44, 'Erat autem fere hora sexta, et tenebræ factæ sunt in universam terram usque ad horam nonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 45, 'Et obscuratus est sol, et velum templi scissum est medium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 46, 'Et clamans voce magna Jesus ait: Pater, in manus tuas commendo spiritum meum. Et hæc dicens, expiravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 47, 'Videns autem centurio quod factum fuerat, glorificavit Deum, dicens: Vere hic homo justus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 48, 'Et omnis turba eorum, qui simul aderant ad spectaculum istud, et videbant quæ fiebant, percutientes pectora sua revertebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 49, 'Stabant autem omnes noti ejus a longe, et mulieres, quæ secutæ eum erant a Galilæa, hæc videntes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 50, 'Et ecce vir nomine Joseph, qui erat decurio, vir bonus et justus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 51, 'hic non consenserat consilio, et actibus eorum: ab Arimathæa civitate Judææ, qui exspectabat et ipse regnum Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 52, 'hic accessit ad Pilatum et petiit corpus Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 53, 'et depositum involvit sindone, et posuit eum in monumento exciso, in quo nondum quisquam positus fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 54, 'Et dies erat parasceves, et sabbatum illucescebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 55, 'Subsecutæ autem mulieres, quæ cum eo venerant de Galilæa, viderunt monumentum, et quemadmodum positum erat corpus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 23, 56, 'Et revertentes paraverunt aromata, et unguenta: et sabbato quidem siluerunt secundum mandatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 1, 'Una autem sabbati valde diluculo venerunt ad monumentum, portantes quæ paraverant aromata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 2, 'et invenerunt lapidem revolutum a monumento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 3, 'Et ingressæ non invenerunt corpus Domini Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 4, 'Et factum est, dum mente consternatæ essent de isto, ecce duo viri steterunt secus illas in veste fulgenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 5, 'Cum timerent autem, et declinarent vultum in terram, dixerunt ad illas: Quid quæritis viventem cum mortuis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 6, 'non est hic, sed surrexit: recordamini qualiter locutus est vobis, cum adhuc in Galilæa esset,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 7, 'dicens: Quia oportet Filium hominis tradi in manus hominum peccatorum, et crucifigi, et die tertia resurgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 8, 'Et recordatæ sunt verborum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 9, 'Et regressæ a monumento nuntiaverunt hæc omnia illis undecim, et ceteris omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 10, 'Erat autem Maria Magdalene, et Joanna, et Maria Jacobi, et ceteræ quæ cum eis erant, quæ dicebant ad apostolos hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 11, 'Et visa sunt ante illos sicut deliramentum verba ista, et non crediderunt illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 12, 'Petrus autem surgens cucurrit ad monumentum: et procumbens vidit linteamina sola posita, et abiit secum mirans quod factum fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 13, 'Et ecce duo ex illis ibant ipsa die in castellum, quod erat in spatio stadiorum sexaginta ab Jerusalem, nomine Emmaus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 14, 'Et ipsi loquebantur ad invicem de his omnibus quæ acciderant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 15, 'Et factum est, dum fabularentur, et secum quærerent: et ipse Jesus appropinquans ibat cum illis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 16, 'oculi autem illorum tenebantur ne eum agnoscerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 17, 'Et ait ad illos: Qui sunt hi sermones, quos confertis ad invicem ambulantes, et estis tristes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 18, 'Et respondens unus, cui nomen Cleophas, dixit ei: Tu solus peregrinus es in Jerusalem, et non cognovisti quæ facta sunt in illa his diebus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 19, 'Quibus ille dixit: Quæ? Et dixerunt: De Jesu Nazareno, qui fuit vir propheta, potens in opere et sermone coram Deo et omni populo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 20, 'et quomodo eum tradiderunt summi sacerdotes et principes nostri in damnationem mortis, et crucifixerunt eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 21, 'nos autem sperabamus quia ipse esset redempturus Israël: et nunc super hæc omnia, tertia dies est hodie quod hæc facta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 22, 'Sed et mulieres quædam ex nostris terruerunt nos, quæ ante lucem fuerunt ad monumentum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 23, 'et non invento corpore ejus, venerunt, dicentes se etiam visionem angelorum vidisse, qui dicunt eum vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 24, 'Et abierunt quidam ex nostris ad monumentum: et ita invenerunt sicut mulieres dixerunt, ipsum vero non invenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 25, 'Et ipse dixit ad eos: O stulti, et tardi corde ad credendum in omnibus quæ locuti sunt prophetæ!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 26, 'Nonne hæc oportuit pati Christum, et ita intrare in gloriam suam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 27, 'Et incipiens a Moyse, et omnibus prophetis, interpretabatur illis in omnibus scripturis quæ de ipso erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 28, 'Et appropinquaverunt castello quo ibant: et ipse se finxit longius ire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 29, 'Et coëgerunt illum, dicentes: Mane nobiscum, quoniam advesperascit, et inclinata est jam dies. Et intravit cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 30, 'Et factum est, dum recumberet cum eis, accepit panem, et benedixit, ac fregit, et porrigebat illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 31, 'Et aperti sunt oculi eorum, et cognoverunt eum: et ipse evanuit ex oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 32, 'Et dixerunt ad invicem: Nonne cor nostrum ardens erat in nobis dum loqueretur in via, et aperiret nobis Scripturas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 33, 'Et surgentes eadem hora regressi sunt in Jerusalem: et invenerunt congregatos undecim, et eos qui cum illis erant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 34, 'dicentes: Quod surrexit Dominus vere, et apparuit Simoni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 35, 'Et ipsi narrabant quæ gesta erant in via, et quomodo cognoverunt eum in fractione panis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 36, 'Dum autem hæc loquuntur, stetit Jesus in medio eorum, et dicit eis: Pax vobis: ego sum, nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 37, 'Conturbati vero et conterriti, existimabant se spiritum videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 38, 'Et dixit eis: Quid turbati estis, et cogitationes ascendunt in corda vestra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 39, 'videte manus meas, et pedes, quia ego ipse sum; palpate et videte, quia spiritus carnem et ossa non habet, sicut me videtis habere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 40, 'Et cum hoc dixisset, ostendit eis manus et pedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 41, 'Adhuc autem illis non credentibus, et mirantibus præ gaudio, dixit: Habetis hic aliquid quod manducetur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 42, 'At illi obtulerunt ei partem piscis assi et favum mellis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 43, 'Et cum manducasset coram eis, sumens reliquias dedit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 44, 'Et dixit ad eos: Hæc sunt verba quæ locutus sum ad vos cum adhuc essem vobiscum, quoniam necesse est impleri omnia quæ scripta sunt in lege Moysi, et prophetis, et Psalmis de me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 45, 'Tunc aperuit illis sensum ut intelligerent Scripturas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 46, 'et dixit eis: Quoniam sic scriptum est, et sic oportebat Christum pati, et resurgere a mortuis tertia die:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 47, 'et prædicari in nomine ejus pœnitentiam, et remissionem peccatorum in omnes gentes, incipientibus ab Jerosolyma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 48, 'Vos autem testes estis horum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 49, 'Et ego mitto promissum Patris mei in vos; vos autem sedete in civitate, quoadusque induamini virtute ex alto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 50, 'Eduxit autem eos foras in Bethaniam, et elevatis manibus suis benedixit eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 51, 'Et factum est, dum benediceret illis, recessit ab eis, et ferebatur in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 52, 'Et ipsi adorantes regressi sunt in Jerusalem cum gaudio magno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 24, 53, 'et erant semper in templo, laudantes et benedicentes Deum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'In principio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Hoc erat in principio apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'In ipso vita erat, et vita erat lux hominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'et lux in tenebris lucet, et tenebræ eam non comprehenderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Fuit homo missus a Deo, cui nomen erat Joannes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Hic venit in testimonium ut testimonium perhiberet de lumine, ut omnes crederent per illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Non erat ille lux, sed ut testimonium perhiberet de lumine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Erat lux vera, quæ illuminat omnem hominem venientem in hunc mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'In mundo erat, et mundus per ipsum factus est, et mundus eum non cognovit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'In propria venit, et sui eum non receperunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Quotquot autem receperunt eum, dedit eis potestatem filios Dei fieri, his qui credunt in nomine ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'qui non ex sanguinibus, neque ex voluntate carnis, neque ex voluntate viri, sed ex Deo nati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Et Verbum caro factum est, et habitavit in nobis: et vidimus gloriam ejus, gloriam quasi unigeniti a Patre plenum gratiæ et veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Joannes testimonium perhibet de ipso, et clamat dicens: Hic erat quem dixi: Qui post me venturus est, ante me factus est: quia prior me erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Et de plenitudine ejus nos omnes accepimus, et gratiam pro gratia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'quia lex per Moysen data est, gratia et veritas per Jesum Christum facta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Deum nemo vidit umquam: unigenitus Filius, qui est in sinu Patris, ipse enarravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Et hoc est testimonium Joannis, quando miserunt Judæi ab Jerosolymis sacerdotes et Levitas ad eum ut interrogarent eum: Tu quis es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Et confessus est, et non negavit, et confessus est: Quia non sum ego Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Et interrogaverunt eum: Quid ergo? Elias es tu? Et dixit: Non sum. Propheta es tu? Et respondit: Non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Dixerunt ergo ei: Quis es ut responsum demus his qui miserunt nos? quid dicis de teipso?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ait: Ego vox clamantis in deserto: Dirigite viam Domini, sicut dixit Isaias propheta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Et qui missi fuerant, erant ex pharisæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Et interrogaverunt eum, et dixerunt ei: Quid ergo baptizas, si tu non es Christus, neque Elias, neque propheta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Respondit eis Joannes, dicens: Ego baptizo in aqua: medius autem vestrum stetit, quem vos nescitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Ipse est qui post me venturus est, qui ante me factus est: cujus ego non sum dignus ut solvam ejus corrigiam calceamenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Hæc in Bethania facta sunt trans Jordanem, ubi erat Joannes baptizans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Altera die vidit Joannes Jesum venientem ad se, et ait: Ecce agnus Dei, ecce qui tollit peccatum mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Hic est de quo dixi: Post me venit vir qui ante me factus est: quia prior me erat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 31, 'et ego nesciebam eum, sed ut manifestetur in Israël, propterea veni ego in aqua baptizans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 32, 'Et testimonium perhibuit Joannes, dicens: Quia vidi Spiritum descendentem quasi columbam de cælo, et mansit super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 33, 'Et ego nesciebam eum: sed qui misit me baptizare in aqua, ille mihi dixit: Super quem videris Spiritum descendentem, et manentem super eum, hic est qui baptizat in Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 34, 'Et ego vidi: et testimonium perhibui quia hic est Filius Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 35, 'Altera die iterum stabat Joannes, et ex discipulis ejus duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 36, 'Et respiciens Jesum ambulantem, dicit: Ecce agnus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 37, 'Et audierunt eum duo discipuli loquentem, et secuti sunt Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 38, 'Conversus autem Jesus, et videns eos sequentes se, dicit eis: Quid quæritis? Qui dixerunt ei: Rabbi (quod dicitur interpretatum Magister), ubi habitas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 39, 'Dicit eis: Venite et videte. Venerunt, et viderunt ubi maneret, et apud eum manserunt die illo: hora autem erat quasi decima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 40, 'Erat autem Andreas, frater Simonis Petri, unus ex duobus qui audierant a Joanne, et secuti fuerant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 41, 'Invenit hic primum fratrem suum Simonem, et dicit ei: Invenimus Messiam (quod est interpretatum Christus).');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 42, 'Et adduxit eum ad Jesum. Intuitus autem eum Jesus, dixit: Tu es Simon, filius Jona; tu vocaberis Cephas, quod interpretatur Petrus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 43, 'In crastinum voluit exire in Galilæam, et invenit Philippum. Et dicit ei Jesus: Sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 44, 'Erat autem Philippus a Bethsaida, civitate Andreæ et Petri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 45, 'Invenit Philippus Nathanaël, et dicit ei: Quem scripsit Moyses in lege, et prophetæ, invenimus Jesum filium Joseph a Nazareth.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 46, 'Et dixit ei Nathanaël: A Nazareth potest aliquid boni esse? Dicit ei Philippus: Veni et vide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 47, 'Vidit Jesus Nathanaël venientem ad se, et dicit de eo: Ecce vere Israëlita, in quo dolus non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 48, 'Dicit ei Nathanaël: Unde me nosti? Respondit Jesus, et dixit ei: Priusquam te Philippus vocavit, cum esses sub ficu, vidi te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 49, 'Respondit ei Nathanaël, et ait: Rabbi, tu es Filius Dei, tu es rex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 50, 'Respondit Jesus, et dixit ei: Quia dixi tibi: Vidi te sub ficu, credis; majus his videbis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 51, 'Et dicit ei: Amen, amen dico vobis, videbitis cælum apertum, et angelos Dei ascendentes, et descendentes supra Filium hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Et die tertia nuptiæ factæ sunt in Cana Galilææ, et erat mater Jesu ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Vocatus est autem et Jesus, et discipuli ejus, ad nuptias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Et deficiente vino, dicit mater Jesu ad eum: Vinum non habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Et dicit ei Jesus: Quid mihi et tibi est, mulier? nondum venit hora mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Dicit mater ejus ministris: Quodcumque dixerit vobis, facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Erant autem ibi lapideæ hydriæ sex positæ secundum purificationem Judæorum, capientes singulæ metretas binas vel ternas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Dicit eis Jesus: Implete hydrias aqua. Et impleverunt eas usque ad summum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Et dicit eis Jesus: Haurite nunc, et ferte architriclino. Et tulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Ut autem gustavit architriclinus aquam vinum factam, et non sciebat unde esset, ministri autem sciebant, qui hauserant aquam: vocat sponsum architriclinus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'et dicit ei: Omnis homo primum bonum vinum ponit et cum inebriati fuerint, tunc id, quod deterius est. Tu autem servasti bonum vinum usque adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Hoc fecit initium signorum Jesus in Cana Galilææ; et manifestavit gloriam suam, et crediderunt in eum discipuli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Post hoc descendit Capharnaum ipse, et mater ejus, et fratres ejus, et discipuli ejus: et ibi manserunt non multis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Et prope erat Pascha Judæorum, et ascendit Jesus Jerosolymam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'et invenit in templo vendentes boves, et oves, et columbas, et numularios sedentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Et cum fecisset quasi flagellum de funiculis, omnes ejecit de templo, oves quoque, et boves, et numulariorum effudit æs, et mensas subvertit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Et his qui columbas vendebant, dixit: Auferte ista hinc, et nolite facere domum patris mei, domum negotiationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Recordati sunt vero discipuli ejus quia scriptum est: Zelus domus tuæ comedit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Responderunt ergo Judæi, et dixerunt ei: Quod signum ostendis nobis, quia hæc facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Respondit Jesus, et dixit eis: Solvite templum hoc, et in tribus diebus excitabo illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Dixerunt ergo Judæi: Quadraginta et sex annis ædificatum est templum hoc, et tu in tribus diebus excitabis illud?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Ille autem dicebat de templo corporis sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Cum ergo resurrexisset a mortuis, recordati sunt discipuli ejus, quia hoc dicebat, et crediderunt scripturæ et sermoni quem dixit Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Cum autem esset Jerosolymis in Pascha in die festo, multi crediderunt in nomine ejus, videntes signa ejus, quæ faciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ipse autem Jesus non credebat semetipsum eis, eo quod ipse nosset omnes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'et quia opus ei non erat ut quis testimonium perhiberet de homine: ipse enim sciebat quid esset in homine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Erat autem homo ex pharisæis, Nicodemus nomine, princeps Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Hic venit ad Jesum nocte, et dixit ei: Rabbi, scimus quia a Deo venisti magister, nemo enim potest hæc signa facere, quæ tu facis, nisi fuerit Deus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Respondit Jesus, et dixit ei: Amen, amen dico tibi, nisi quis renatus fuerit denuo, non potest videre regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Dicit ad eum Nicodemus: Quomodo potest homo nasci, cum sit senex? numquid potest in ventrem matris suæ iterato introire et renasci?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Respondit Jesus: Amen, amen dico tibi, nisi quis renatus fuerit ex aqua, et Spiritu Sancto, non potest introire in regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Quod natum est ex carne, caro est: et quod natum est ex spiritu, spiritus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Non mireris quia dixi tibi: oportet vos nasci denuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Spiritus ubi vult spirat, et vocem ejus audis, sed nescis unde veniat, aut quo vadat: sic est omnis qui natus est ex spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Respondit Nicodemus, et dixit ei: Quomodo possunt hæc fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Respondit Jesus, et dixit ei: Tu es magister in Israël, et hæc ignoras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Amen, amen dico tibi, quia quod scimus loquimur, et quod vidimus testamur, et testimonium nostrum non accipitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Si terrena dixi vobis, et non creditis: quomodo, si dixero vobis cælestia, credetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Et nemo ascendit in cælum, nisi qui descendit de cælo, Filius hominis, qui est in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Et sicut Moyses exaltavit serpentem in deserto, ita exaltari oportet Filium hominis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'ut omnis qui credit in ipsum, non pereat, sed habeat vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Sic enim Deus dilexit mundum, ut Filium suum unigenitum daret: ut omnis qui credit in eum, non pereat, sed habeat vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Non enim misit Deus Filium suum in mundum, ut judicet mundum, sed ut salvetur mundus per ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Qui credit in eum, non judicatur; qui autem non credit, jam judicatus est: quia non credit in nomine unigeniti Filii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Hoc est autem judicium: quia lux venit in mundum, et dilexerunt homines magis tenebras quam lucem: erant enim eorum mala opera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Omnis enim qui male agit, odit lucem, et non venit ad lucem, ut non arguantur opera ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'qui autem facit veritatem, venit ad lucem, ut manifestentur opera ejus, quia in Deo sunt facta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 22, 'Post hæc venit Jesus et discipuli ejus in terram Judæam: et illic demorabatur cum eis, et baptizabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 23, 'Erat autem et Joannes baptizans, in \'nnon, juxta Salim: quia aquæ multæ erant illic, et veniebant et baptizabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 24, 'Nondum enim missus fuerat Joannes in carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 25, 'Facta est autem quæstio ex discipulis Joannis cum Judæis de purificatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 26, 'Et venerunt ad Joannem, et dixerunt ei: Rabbi, qui erat tecum trans Jordanem, cui tu testimonium perhibuisti, ecce hic baptizat, et omnes veniunt ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 27, 'Respondit Joannes, et dixit: Non potest homo accipere quidquam, nisi fuerit ei datum de cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 28, 'Ipsi vos mihi testimonium perhibetis, quod dixerim: Non sum ego Christus: sed quia missus sum ante illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 29, 'Qui habet sponsam, sponsus est: amicus autem sponsi, qui stat, et audit eum, gaudio gaudet propter vocem sponsi. Hoc ergo gaudium meum impletum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 30, 'Illum oportet crescere, me autem minui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 31, 'Qui desursum venit, super omnes est. Qui est de terra, de terra est, et de terra loquitur. Qui de cælo venit, super omnes est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 32, 'Et quod vidit, et audivit, hoc testatur: et testimonium ejus nemo accipit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 33, 'Qui accepit ejus testimonium signavit, quia Deus verax est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 34, 'Quem enim misit Deus, verba Dei loquitur: non enim ad mensuram dat Deus spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 35, 'Pater diligit Filium et omnia dedit in manu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 36, 'Qui credit in Filium, habet vitam æternam; qui autem incredulus est Filio, non videbit vitam, sed ira Dei manet super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Ut ergo cognovit Jesus quia audierunt pharisæi quod Jesus plures discipulos facit, et baptizat, quam Joannes');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, '(quamquam Jesus non baptizaret, sed discipuli ejus),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'reliquit Judæam, et abiit iterum in Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Oportebat autem eum transire per Samariam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Venit ergo in civitatem Samariæ, quæ dicitur Sichar, juxta prædium quod dedit Jacob Joseph filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Erat autem ibi fons Jacob. Jesus ergo fatigatus ex itinere, sedebat sic supra fontem. Hora erat quasi sexta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Venit mulier de Samaria haurire aquam. Dicit ei Jesus: Da mihi bibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, '(Discipuli enim ejus abierant in civitatem ut cibos emerent.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Dicit ergo ei mulier illa Samaritana: Quomodo tu, Judæus cum sis, bibere a me poscis, quæ sum mulier Samaritana? non enim coutuntur Judæi Samaritanis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Respondit Jesus, et dixit ei: Si scires donum Dei, et quis est qui dicit tibi: Da mihi bibere, tu forsitan petisses ab eo, et dedisset tibi aquam vivam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Dicit ei mulier: Domine, neque in quo haurias habes, et puteus altus est: unde ergo habes aquam vivam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Numquid tu major es patre nostro Jacob, qui dedit nobis puteum, et ipse ex eo bibit, et filii ejus, et pecora ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Respondit Jesus, et dixit ei: Omnis qui bibit ex aqua hac, sitiet iterum; qui autem biberit ex aqua quam ego dabo ei, non sitiet in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'sed aqua quam ego dabo ei, fiet in eo fons aquæ salientis in vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Dicit ad eum mulier: Domine, da mihi hanc aquam, ut non sitiam, neque veniam huc haurire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Dicit ei Jesus: Vade, voca virum tuum, et veni huc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Respondit mulier, et dixit: Non habeo virum. Dicit ei Jesus: Bene dixisti, quia non habeo virum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'quinque enim viros habuisti, et nunc, quem habes, non est tuus vir: hoc vere dixisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Dicit ei mulier: Domine, video quia propheta es tu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Patres nostri in monte hoc adoraverunt, et vos dicitis, quia Jerosolymis est locus ubi adorare oportet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Dicit ei Jesus: Mulier, crede mihi, quia venit hora, quando neque in monte hoc, neque in Jerosolymis adorabitis Patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Vos adoratis quod nescitis: nos adoramus quod scimus, quia salus ex Judæis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Sed venit hora, et nunc est, quando veri adoratores adorabunt Patrem in spiritu et veritate. Nam et Pater tales quærit, qui adorent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 24, 'Spiritus est Deus: et eos qui adorant eum, in spiritu et veritate oportet adorare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 25, 'Dicit ei mulier: Scio quia Messias venit (qui dicitur Christus): cum ergo venerit ille, nobis annuntiabit omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 26, 'Dicit ei Jesus: Ego sum, qui loquor tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 27, 'Et continuo venerunt discipuli ejus, et mirabantur quia cum muliere loquebatur. Nemo tamen dixit: Quid quæris? aut, Quid loqueris cum ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 28, 'Reliquit ergo hydriam suam mulier, et abiit in civitatem, et dicit illis hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 29, 'Venite, et videte hominem qui dixit mihi omnia quæcumque feci: numquid ipse est Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 30, 'Exierunt ergo de civitate et veniebant ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 31, 'Interea rogabant eum discipuli, dicentes: Rabbi, manduca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 32, 'Ille autem dicit eis: Ego cibum habeo manducare, quem vos nescitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 33, 'Dicebant ergo discipuli ad invicem: Numquid aliquis attulit ei manducare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 34, 'Dicit eis Jesus: Meus cibus est ut faciam voluntatem ejus qui misit me, ut perficiam opus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 35, 'Nonne vos dicitis quod adhuc quatuor menses sunt, et messis venit? Ecce dico vobis: levate oculos vestros, et videte regiones, quia albæ sunt jam ad messem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 36, 'Et qui metit, mercedem accipit, et congregat fructum in vitam æternam: ut et qui seminat, simul gaudeat, et qui metit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 37, 'In hoc enim est verbum verum: quia alius est qui seminat, et alius est qui metit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 38, 'Ego misi vos metere quod vos non laborastis: alii laboraverunt, et vos in labores eorum introistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 39, 'Ex civitate autem illa multi crediderunt in eum Samaritanorum, propter verbum mulieris testimonium perhibentis: Quia dixit mihi omnia quæcumque feci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 40, 'Cum venissent ergo ad illum Samaritani, rogaverunt eum ut ibi maneret. Et mansit ibi duos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 41, 'Et multo plures crediderunt in eum propter sermonem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 42, 'Et mulieri dicebant: Quia jam non propter tuam loquelam credimus: ipsi enim audivimus, et scimus quia hic est vere Salvator mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 43, 'Post duos autem dies exiit inde, et abiit in Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 44, 'Ipse enim Jesus testimonium perhibuit, quia propheta in sua patria honorem non habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 45, 'Cum ergo venisset in Galilæam, exceperunt eum Galilæi, cum omnia vidissent quæ fecerat Jerosolymis in die festo: et ipsi enim venerant ad diem festum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 46, 'Venit ergo iterum in Cana Galilææ, ubi fecit aquam vinum. Et erat quidam regulus, cujus filius infirmabatur Capharnaum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 47, 'Hic cum audisset quia Jesus adveniret a Judæa in Galilæam, abiit ad eum, et rogabat eum ut descenderet, et sanaret filium ejus: incipiebat enim mori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 48, 'Dixit ergo Jesus ad eum: Nisi signa et prodigia videritis, non creditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 49, 'Dicit ad eum regulus: Domine, descende priusquam moriatur filius meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 50, 'Dicit ei Jesus: Vade, filius tuus vivit. Credidit homo sermoni quem dixit ei Jesus, et ibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 51, 'Jam autem eo descendente, servi occurrerunt ei, et nuntiaverunt dicentes, quia filius ejus viveret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 52, 'Interrogabat ergo horam ab eis in qua melius habuerit. Et dixerunt ei: Quia heri hora septima reliquit eum febris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 53, 'Cognovit ergo pater, quia illa hora erat in qua dixit ei Jesus: Filius tuus vivit; et credidit ipse et domus ejus tota.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 54, 'Hoc iterum secundum signum fecit Jesus, cum venisset a Judæa in Galilæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 1, 'Post hæc erat dies festus Judæorum, et ascendit Jesus Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 2, 'Est autem Jerosolymis probatica piscina, quæ cognominatur hebraice Bethsaida, quinque porticus habens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 3, 'In his jacebat multitudo magna languentium, cæcorum, claudorum, aridorum, exspectantium aquæ motum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 4, 'Angelus autem Domini descendebat secundum tempus in piscinam, et movebatur aqua. Et qui prior descendisset in piscinam post motionem aquæ, sanus fiebat a quacumque detinebatur infirmitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 5, 'Erat autem quidam homo ibi triginta et octo annos habens in infirmitate sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 6, 'Hunc autem cum vidisset Jesus jacentem, et cognovisset quia jam multum tempus haberet, dicit ei: Vis sanus fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 7, 'Respondit ei languidus: Domine, hominem non habeo, ut, cum turbata fuerit aqua, mittat me in piscinam: dum venio enim ego, alius ante me descendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 8, 'Dicit ei Jesus: Surge, tolle grabatum tuum et ambula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 9, 'Et statim sanus factus est homo ille: et sustulit grabatum suum, et ambulabat. Erat autem sabbatum in die illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 10, 'Dicebant ergo Judæi illi qui sanatus fuerat: Sabbatum est, non licet tibi tollere grabatum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 11, 'Respondit eis: Qui me sanum fecit, ille mihi dixit: Tolle grabatum tuum et ambula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 12, 'Interrogaverunt ergo eum: Quis est ille homo qui dixit tibi: Tolle grabatum tuum et ambula?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 13, 'Is autem qui sanus fuerat effectus, nesciebat quis esset. Jesus enim declinavit a turba constituta in loco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 14, 'Postea invenit eum Jesus in templo, et dixit illi: Ecce sanus factus es; jam noli peccare, ne deterius tibi aliquid contingat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 15, 'Abiit ille homo, et nuntiavit Judæis quia Jesus esset, qui fecit eum sanum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 16, 'Propterea persequebantur Judæi Jesum, quia hæc faciebat in sabbato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 17, 'Jesus autem respondit eis: Pater meus usque modo operatur, et ego operor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 18, 'Propterea ergo magis quærebant eum Judæi interficere: quia non solum solvebat sabbatum, sed et patrem suum dicebat Deum, æqualem se faciens Deo. Respondit itaque Jesus, et dixit eis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 19, 'Amen, amen dico vobis: non potest Filius a se facere quidquam, nisi quod viderit Patrem facientem: quæcumque enim ille fecerit, hæc et Filius similiter facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 20, 'Pater enim diligit Filium, et omnia demonstrat ei quæ ipse facit: et majora his demonstrabit ei opera, ut vos miremini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 21, 'Sicut enim Pater suscitat mortuos, et vivificat, sic et Filius, quos vult, vivificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 22, 'Neque enim Pater judicat quemquam: sed omne judicium dedit Filio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 23, 'ut omnes honorificent Filium, sicut honorificant Patrem; qui non honorificat Filium, non honorificat Patrem, qui misit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 24, 'Amen, amen dico vobis, quia qui verbum meum audit, et credit ei qui misit me, habet vitam æternam, et in judicium non venit, sed transiit a morte in vitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 25, 'Amen, amen dico vobis, quia venit hora, et nunc est, quando mortui audient vocem Filii Dei: et qui audierint, vivent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 26, 'Sicut enim Pater habet vitam in semetipso, sic dedit et Filio habere vitam in semetipso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 27, 'et potestatem dedit ei judicium facere, quia Filius hominis est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 28, 'Nolite mirari hoc, quia venit hora in qua omnes qui in monumentis sunt audient vocem Filii Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 29, 'et procedent qui bona fecerunt, in resurrectionem vitæ; qui vero mala egerunt, in resurrectionem judicii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 30, 'Non possum ego a meipso facere quidquam. Sicut audio, judico: et judicium meum justum est, quia non quæro voluntatem meam, sed voluntatem ejus qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 31, 'Si ego testimonium perhibeo de meipso, testimonium meum non est verum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 32, 'Alius est qui testimonium perhibet de me: et scio quia verum est testimonium, quod perhibet de me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 33, 'Vos misistis ad Joannem, et testimonium perhibuit veritati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 34, 'Ego autem non ab homine testimonium accipio: sed hæc dico ut vos salvi sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 35, 'Ille erat lucerna ardens et lucens: vos autem voluistis ad horam exsultare in luce ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 36, 'Ego autem habeo testimonium majus Joanne. Opera enim quæ dedit mihi Pater ut perficiam ea: ipsa opera, quæ ego facio, testimonium perhibent de me, quia Pater misit me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 37, 'et qui misit me Pater, ipse testimonium perhibuit de me: neque vocem ejus umquam audistis, neque speciem ejus vidistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 38, 'et verbum ejus non habetis in vobis manens: quia quem misit ille, huic vos non creditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 39, 'Scrutamini Scripturas, quia vos putatis in ipsis vitam æternam habere: et illæ sunt quæ testimonium perhibent de me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 40, 'et non vultis venire ad me ut vitam habeatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 41, 'Claritatem ab hominibus non accipio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 42, 'Sed cognovi vos, quia dilectionem Dei non habetis in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 43, 'Ego veni in nomine Patris mei, et non accipitis me; si alius venerit in nomine suo, illum accipietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 44, 'Quomodo vos potestis credere, qui gloriam ab invicem accipitis, et gloriam quæ a solo Deo est, non quæritis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 45, 'Nolite putare quia ego accusaturus sim vos apud Patrem: est qui accusat vos Moyses, in quo vos speratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 46, 'Si enim crederetis Moysi, crederetis forsitan et mihi: de me enim ille scripsit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 47, 'Si autem illius litteris non creditis, quomodo verbis meis credetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 1, 'Post hæc abiit Jesus trans mare Galilææ, quod est Tiberiadis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 2, 'et sequebatur eum multitudo magna, quia videbant signa quæ faciebat super his qui infirmabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 3, 'Subiit ergo in montem Jesus et ibi sedebat cum discipulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 4, 'Erat autem proximum Pascha dies festus Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 5, 'Cum sublevasset ergo oculos Jesus, et vidisset quia multitudo maxima venit ad eum, dixit ad Philippum: Unde ememus panes, ut manducent hi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 6, 'Hoc autem dicebat tentans eum: ipse enim sciebat quid esset facturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 7, 'Respondit ei Philippus: Ducentorum denariorum panes non sufficiunt eis, ut unusquisque modicum quid accipiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 8, 'Dicit ei unus ex discipulis ejus, Andreas, frater Simonis Petri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 9, 'Est puer unus hic qui habet quinque panes hordeaceos et duos pisces: sed hæc quid sunt inter tantos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 10, 'Dixit ergo Jesus: Facite homines discumbere. Erat autem fœnum multum in loco. Discubuerunt ergo viri, numero quasi quinque millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 11, 'Accepit ergo Jesus panes: et cum gratias egisset, distribuit discumbentibus: similiter et ex piscibus quantum volebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 12, 'Ut autem impleti sunt, dixit discipulis suis: Colligite quæ superaverunt fragmenta, ne pereant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 13, 'Collegerunt ergo, et impleverunt duodecim cophinos fragmentorum ex quinque panibus hordeaceis, quæ superfuerunt his qui manducaverant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 14, 'Illi ergo homines cum vidissent quod Jesus fecerat signum, dicebant: Quia hic est vere propheta, qui venturus est in mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 15, 'Jesus ergo cum cognovisset quia venturi essent ut raperent eum, et facerent eum regem, fugit iterum in montem ipse solus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 16, 'Ut autem sero factum est, descenderunt discipuli ejus ad mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 17, 'Et cum ascendissent navim, venerunt trans mare in Capharnaum: et tenebræ jam factæ erant et non venerat ad eos Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 18, 'Mare autem, vento magno flante, exsurgebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 19, 'Cum remigassent ergo quasi stadia viginti quinque aut triginta, vident Jesum ambulantem supra mare, et proximum navi fieri, et timuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 20, 'Ille autem dicit eis: Ego sum, nolite timere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 21, 'Voluerunt ergo accipere eum in navim et statim navis fuit ad terram, in quam ibant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 22, 'Altera die, turba, quæ stabat trans mare, vidit quia navicula alia non erat ibi nisi una, et quia non introisset cum discipulis suis Jesus in navim, sed soli discipuli ejus abiissent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 23, 'aliæ vero supervenerunt naves a Tiberiade juxta locum ubi manducaverant panem, gratias agente Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 24, 'Cum ergo vidisset turba quia Jesus non esset ibi, neque discipuli ejus, ascenderunt in naviculas, et venerunt Capharnaum quærentes Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 25, 'Et cum invenissent eum trans mare, dixerunt ei: Rabbi, quando huc venisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 26, 'Respondit eis Jesus, et dixit: Amen, amen dico vobis: quæritis me non quia vidistis signa, sed quia manducastis ex panibus et saturati estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 27, 'Operamini non cibum, qui perit, sed qui permanet in vitam æternam, quem Filius hominis dabit vobis. Hunc enim Pater signavit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 28, 'Dixerunt ergo ad eum: Quid faciemus ut operemur opera Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 29, 'Respondit Jesus, et dixit eis: Hoc est opus Dei, ut credatis in eum quem misit ille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 30, 'Dixerunt ergo ei: Quod ergo tu facis signum ut videamus et credamus tibi? quid operaris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 31, 'Patres nostri manducaverunt manna in deserto, sicut scriptum est: Panem de cælo dedit eis manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 32, 'Dixit ergo eis Jesus: Amen, amen dico vobis: non Moyses dedit vobis panem de cælo, sed Pater meus dat vobis panem de cælo verum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 33, 'Panis enim Dei est, qui de cælo descendit, et dat vitam mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 34, 'Dixerunt ergo ad eum: Domine, semper da nobis panem hunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 35, 'Dixit autem eis Jesus: Ego sum panis vitæ: qui venit ad me, non esuriet, et qui credit in me, non sitiet umquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 36, 'Sed dixi vobis quia et vidistis me, et non creditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 37, 'Omne quod dat mihi Pater, ad me veniet: et eum qui venit ad me, non ejiciam foras:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 38, 'quia descendi de cælo, non ut faciam voluntatem meam, sed voluntatem ejus qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 39, 'Hæc est autem voluntas ejus qui misit me, Patris: ut omne quod dedit mihi, non perdam ex eo, sed resuscitem illud in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 40, 'Hæc est autem voluntas Patris mei, qui misit me: ut omnis qui videt Filium et credit in eum, habeat vitam æternam, et ego resuscitabo eum in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 41, 'Murmurabant ergo Judæi de illo, quia dixisset: Ego sum panis vivus, qui de cælo descendi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 42, 'et dicebant: Nonne hic est Jesus filius Joseph, cujus nos novimus patrem et matrem? quomodo ergo dicit hic: Quia de cælo descendi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 43, 'Respondit ergo Jesus, et dixit eis: Nolite murmurare in invicem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 44, 'nemo potest venire ad me, nisi Pater, qui misit me, traxerit eum; et ego resuscitabo eum in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 45, 'Est scriptum in prophetis: Et erunt omnes docibiles Dei. Omnis qui audivit a Patre, et didicit, venit ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 46, 'Non quia Patrem vidit quisquam, nisi is, qui est a Deo, hic vidit Patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 47, 'Amen, amen dico vobis: qui credit in me, habet vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 48, 'Ego sum panis vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 49, 'Patres vestri manducaverunt manna in deserto, et mortui sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 50, 'Hic est panis de cælo descendens: ut si quis ex ipso manducaverit, non moriatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 51, 'Ego sum panis vivus, qui de cælo descendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 52, 'Si quis manducaverit ex hoc pane, vivet in æternum: et panis quem ego dabo, caro mea est pro mundi vita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 53, 'Litigabant ergo Judæi ad invicem, dicentes: Quomodo potest hic nobis carnem suam dare ad manducandum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 54, 'Dixit ergo eis Jesus: Amen, amen dico vobis: nisi manducaveritis carnem Filii hominis, et biberitis ejus sanguinem, non habebitis vitam in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 55, 'Qui manducat meam carnem, et bibit meum sanguinem, habet vitam æternam: et ego resuscitabo eum in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 56, 'Caro enim mea vere est cibus: et sanguis meus, vere est potus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 57, 'qui manducat meam carnem et bibit meum sanguinem, in me manet, et ego in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 58, 'Sicut misit me vivens Pater, et ego vivo propter Patrem: et qui manducat me, et ipse vivet propter me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 59, 'Hic est panis qui de cælo descendit. Non sicut manducaverunt patres vestri manna, et mortui sunt. Qui manducat hunc panem, vivet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 60, 'Hæc dixit in synagoga docens, in Capharnaum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 61, 'Multi ergo audientes ex discipulis ejus, dixerunt: Durus est hic sermo, et quis potest eum audire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 62, 'Sciens autem Jesus apud semetipsum quia murmurarent de hoc discipuli ejus, dixit eis: Hoc vos scandalizat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 63, 'si ergo videritis Filium hominis ascendentem ubi erat prius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 64, 'Spiritus est qui vivificat: caro non prodest quidquam: verba quæ ego locutus sum vobis, spiritus et vita sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 65, 'Sed sunt quidam ex vobis qui non credunt. Sciebat enim ab initio Jesus qui essent non credentes, et quis traditurus esset eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 66, 'Et dicebat: Propterea dixi vobis, quia nemo potest venire ad me, nisi fuerit ei datum a Patre meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 67, 'Ex hoc multi discipulorum ejus abierunt retro: et jam non cum illo ambulabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 68, 'Dixit ergo Jesus ad duodecim: Numquid et vos vultis abire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 69, 'Respondit ergo ei Simon Petrus: Domine, ad quem ibimus? verba vitæ æternæ habes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 70, 'et nos credidimus, et cognovimus quia tu es Christus Filius Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 71, 'Respondit eis Jesus: Nonne ego vos duodecim elegi: et ex vobis unus diabolus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 72, 'Dicebat autem Judam Simonis Iscariotem: hic enim erat traditurus eum, cum esset unus ex duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 1, 'Post hæc autem ambulabat Jesus in Galilæam: non enim volebat in Judæam ambulare, quia quærebant eum Judæi interficere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 2, 'Erat autem in proximo dies festus Judæorum, Scenopegia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 3, 'Dixerunt autem ad eum fratres ejus: Transi hinc, et vade in Judæam, ut et discipuli tui videant opera tua, quæ facis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 4, 'Nemo quippe in occulto quid facit, et quærit ipse in palam esse: si hæc facis, manifesta teipsum mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 5, 'Neque enim fratres ejus credebant in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 6, 'Dicit ergo eis Jesus: Tempus meum nondum advenit: tempus autem vestrum semper est paratum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 7, 'Non potest mundus odisse vos: me autem odit, quia ego testimonium perhibeo de illo quod opera ejus mala sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 8, 'Vos ascendite ad diem festum hunc, ego autem non ascendo ad diem festum istum: quia meum tempus nondum impletum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 9, 'Hæc cum dixisset, ipse mansit in Galilæa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 10, 'Ut autem ascenderunt fratres ejus, tunc et ipse ascendit ad diem festum non manifeste, sed quasi in occulto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 11, 'Judæi ergo quærebant eum in die festo, et dicebant: Ubi est ille?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 12, 'Et murmur multum erat in turba de eo. Quidam enim dicebant: Quia bonus est. Alii autem dicebant: Non, sed seducit turbas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 13, 'Nemo tamen palam loquebatur de illo propter metum Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 14, 'Jam autem die festo mediante, ascendit Jesus in templum, et docebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 15, 'Et mirabantur Judæi, dicentes: Quomodo hic litteras scit, cum non didicerit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 16, 'Respondit eis Jesus, et dixit: Mea doctrina non est mea, sed ejus qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 17, 'Si quis voluerit voluntatem ejus facere, cognoscet de doctrina, utrum ex Deo sit, an ego a meipso loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 18, 'Qui a semetipso loquitur, gloriam propriam quærit; qui autem quærit gloriam ejus qui misit eum, hic verax est, et injustitia in illo non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 19, 'Nonne Moyses dedit vobis legem: et nemo ex vobis facit legem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 20, 'Quid me quæritis interficere? Respondit turba, et dixit: Dæmonium habes: quis te quærit interficere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 21, 'Respondit Jesus et dixit eis: Unum opus feci, et omnes miramini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 22, 'propterea Moyses dedit vobis circumcisionem (non quia ex Moyse est, sed ex patribus), et in sabbato circumciditis hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 23, 'Si circumcisionem accipit homo in sabbato, ut non solvatur lex Moysi: mihi indignamini quia totum hominem sanum feci in sabbato?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 24, 'Nolite judicare secundum faciem, sed justum judicium judicate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 25, 'Dicebant ergo quidam ex Jerosolymis: Nonne hic est, quem quærunt interficere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 26, 'et ecce palam loquitur, et nihil ei dicunt. Numquid vere cognoverunt principes quia hic est Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 27, 'Sed hunc scimus unde sit: Christus autem cum venerit, nemo scit unde sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 28, 'Clamabat ergo Jesus in templo docens, et dicens: Et me scitis, et unde sim scitis: et a meipso non veni, sed est verus qui misit me, quem vos nescitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 29, 'Ego scio eum: quia ab ipso sum, et ipse me misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 30, 'Quærebant ergo eum apprehendere: et nemo misit in illum manus, quia nondum venerat hora ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 31, 'De turba autem multi crediderunt in eum, et dicebant: Christus cum venerit, numquid plura signa faciet quam quæ hic facit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 32, 'Audierunt pharisæi turbam murmurantem de illo hæc: et miserunt principes et pharisæi ministros ut apprehenderent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 33, 'Dixit ergo eis Jesus: Adhuc modicum tempus vobiscum sum: et vado ad eum qui me misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 34, 'Quæretis me, et non invenietis: et ubi ego sum, vos non potestis venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 35, 'Dixerunt ergo Judæi ad semetipsos: Quo hic iturus est, quia non inveniemus eum? numquid in dispersionem gentium iturus est, et docturus gentes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 36, 'quis est hic sermo, quem dixit: Quæretis me, et non invenietis: et ubi sum ego, vos non potestis venire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 37, 'In novissimo autem die magno festivitatis stabat Jesus, et clamabat dicens: Si quis sitit, veniat ad me et bibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 38, 'Qui credit in me, sicut dicit Scriptura, flumina de ventre ejus fluent aquæ vivæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 39, 'Hoc autem dixit de Spiritu, quem accepturi erant credentes in eum: nondum enim erat Spiritus datus, quia Jesus nondum erat glorificatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 40, 'Ex illa ergo turba cum audissent hos sermones ejus, dicebant: Hic est vere propheta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 41, 'Alii dicebant: Hic est Christus. Quidam autem dicebant: Numquid a Galilæa venit Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 42, 'nonne Scriptura dicit: Quia ex semine David, et de Bethlehem castello, ubi erat David, venit Christus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 43, 'Dissensio itaque facta est in turba propter eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 44, 'Quidam autem ex ipsis volebant apprehendere eum: sed nemo misit super eum manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 45, 'Venerunt ergo ministri ad pontifices et pharisæos. Et dixerunt eis illi: Quare non adduxistis illum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 46, 'Responderunt ministri: Numquam sic locutus est homo, sicut hic homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 47, 'Responderunt ergo eis pharisæi: Numquid et vos seducti estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 48, 'numquid ex principibus aliquis credidit in eum, aut ex pharisæis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 49, 'sed turba hæc, quæ non novit legem, maledicti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 50, 'Dixit Nicodemus ad eos, ille qui venit ad eum nocte, qui unus erat ex ipsis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 51, 'Numquid lex nostra judicat hominem, nisi prius audierit ab ipso, et cognoverit quid faciat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 52, 'Responderunt, et dixerunt ei: Numquid et tu Galilæus es? scrutare Scripturas, et vide quia a Galilæa propheta non surgit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 53, 'Et reversi sunt unusquisque in domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 1, 'Jesus autem perrexit in montem Oliveti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 2, 'et diluculo iterum venit in templum, et omnis populus venit ad eum, et sedens docebat eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 3, 'Adducunt autem scribæ et pharisæi mulierem in adulterio deprehensam: et statuerunt eam in medio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 4, 'et dixerunt ei: Magister, hæc mulier modo deprehensa est in adulterio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 5, 'In lege autem Moyses mandavit nobis hujusmodi lapidare. Tu ergo quid dicis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 6, 'Hoc autem dicebant tentantes eum, ut possent accusare eum. Jesus autem inclinans se deorsum, digito scribebat in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 7, 'Cum ergo perseverarent interrogantes eum, erexit se, et dixit eis: Qui sine peccato est vestrum, primus in illam lapidem mittat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 8, 'Et iterum se inclinans, scribebat in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 9, 'Audientes autem unus post unum exibant, incipientes a senioribus: et remansit solus Jesus, et mulier in medio stans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 10, 'Erigens autem se Jesus, dixit ei: Mulier, ubi sunt qui te accusabant? nemo te condemnavit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 11, 'Quæ dixit: Nemo, Domine. Dixit autem Jesus: Nec ego te condemnabo: vade, et jam amplius noli peccare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 12, 'Iterum ergo locutus est eis Jesus, dicens: Ego sum lux mundi: qui sequitur me, non ambulat in tenebris, sed habebit lumen vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 13, 'Dixerunt ergo ei pharisæi: Tu de teipso testimonium perhibes; testimonium tuum non est verum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 14, 'Respondit Jesus, et dixit eis: Et si ego testimonium perhibeo de meipso, verum est testimonium meum: quia scio unde veni et quo vado; vos autem nescitis unde venio aut quo vado.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 15, 'Vos secundum carnem judicatis: ego non judico quemquam;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 16, 'et si judico ego, judicium meum verum est, quia solus non sum: sed ego et qui misit me, Pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 17, 'Et in lege vestra scriptum est, quia duorum hominum testimonium verum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 18, 'Ego sum qui testimonium perhibeo de meipso, et testimonium perhibet de me qui misit me, Pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 19, 'Dicebant ergo ei: Ubi est Pater tuus? Respondit Jesus: Neque me scitis, neque Patrem meum: si me sciretis, forsitan et Patrem meum sciretis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 20, 'Hæc verba locutus est Jesus in gazophylacio, docens in templo: et nemo apprehendit eum, quia necdum venerat hora ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 21, 'Dixit ergo iterum eis Jesus: Ego vado, et quæretis me, et in peccato vestro moriemini. Quo ego vado, vos non potestis venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 22, 'Dicebant ergo Judæi: Numquid interficiet semetipsum, quia dixit: Quo ego vado, vos non potestis venire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 23, 'Et dicebat eis: Vos de deorsum estis, ego de supernis sum. Vos de mundo hoc estis, ego non sum de hoc mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 24, 'Dixi ergo vobis quia moriemini in peccatis vestris: si enim non credideritis quia ego sum, moriemini in peccato vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 25, 'Dicebant ergo ei: Tu quis es? Dixit eis Jesus: Principium, qui et loquor vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 26, 'Multa habeo de vobis loqui, et judicare; sed qui me misit, verax est; et ego quæ audivi ab eo, hæc loquor in mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 27, 'Et non cognoverunt quia Patrem ejus dicebat Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 28, 'Dixit ergo eis Jesus: Cum exaltaveritis Filium hominis, tunc cognoscetis quia ego sum, et a meipso facio nihil, sed sicut docuit me Pater, hæc loquor:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 29, 'et qui me misit, mecum est, et non reliquit me solum: quia ego quæ placita sunt ei, facio semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 30, 'Hæc illo loquente, multi crediderunt in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 31, 'Dicebat ergo Jesus ad eos, qui crediderunt ei, Judæos: Si vos manseritis in sermone meo, vere discipuli mei eritis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 32, 'et cognoscetis veritatem, et veritas liberabit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 33, 'Responderunt ei: Semen Abrahæ sumus, et nemini servivimus umquam: quomodo tu dicis: Liberi eritis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 34, 'Respondit eis Jesus: Amen, amen dico vobis: quia omnis qui facit peccatum, servus est peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 35, 'Servus autem non manet in domo in æternum: filius autem manet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 36, 'Si ergo vos filius liberaverit, vere liberi eritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 37, 'Scio quia filii Abrahæ estis: sed quæritis me interficere, quia sermo meus non capit in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 38, 'Ego quod vidi apud Patrem meum, loquor: et vos quæ vidistis apud patrem vestrum, facitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 39, 'Responderunt, et dixerunt ei: Pater noster Abraham est. Dicit eis Jesus: Si filii Abrahæ estis, opera Abrahæ facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 40, 'Nunc autem quæritis me interficere, hominem, qui veritatem vobis locutus sum, quam audivi a Deo: hoc Abraham non fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 41, 'Vos facitis opera patris vestri. Dixerunt itaque ei: Nos ex fornicatione non sumus nati: unum patrem habemus Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 42, 'Dixit ergo eis Jesus: Si Deus pater vester esset, diligeretis utique et me; ego enim ex Deo processi, et veni: neque enim a meipso veni, sed ille me misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 43, 'Quare loquelam meam non cognoscitis? Quia non potestis audire sermonem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 44, 'Vos ex patre diabolo estis: et desideria patris vestri vultis facere. Ille homicida erat ab initio, et in veritate non stetit: quia non est veritas in eo: cum loquitur mendacium, ex propriis loquitur, quia mendax est, et pater ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 45, 'Ego autem si veritatem dico, non creditis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 46, 'Quis ex vobis arguet me de peccato? si veritatem dico vobis, quare non creditis mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 47, 'Qui ex Deo est, verba Dei audit. Propterea vos non auditis, quia ex Deo non estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 48, 'Responderunt ergo Judæi, et dixerunt ei: Nonne bene dicimus nos quia Samaritanus es tu, et dæmonium habes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 49, 'Respondit Jesus: Ego dæmonium non habeo: sed honorifico Patrem meum, et vos inhonorastis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 50, 'Ego autem non quæro gloriam meam: est qui quærat, et judicet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 51, 'Amen, amen dico vobis: si quis sermonem meum servaverit, mortem non videbit in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 52, 'Dixerunt ergo Judæi: Nunc cognovimus quia dæmonium habes. Abraham mortuus est, et prophetæ; et tu dicis: Si quis sermonem meum servaverit, non gustabit mortem in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 53, 'Numquid tu major es patre nostro Abraham, qui mortuus est? et prophetæ mortui sunt. Quem teipsum facis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 54, 'Respondit Jesus: Si ego glorifico meipsum, gloria mea nihil est: est Pater meus, qui glorificat me, quem vos dicitis quia Deus vester est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 55, 'et non cognovistis eum: ego autem novi eum. Et si dixero quia non scio eum, ero similis vobis, mendax. Sed scio eum, et sermonem ejus servo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 56, 'Abraham pater vester exsultavit ut videret diem meum: vidit, et gavisus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 57, 'Dixerunt ergo Judæi ad eum: Quinquaginta annos nondum habes, et Abraham vidisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 58, 'Dixit eis Jesus: Amen, amen dico vobis, antequam Abraham fieret, ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 59, 'Tulerunt ergo lapides, ut jacerent in eum: Jesus autem abscondit se, et exivit de templo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 1, 'Et præteriens Jesus vidit hominem cæcum a nativitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 2, 'et interrogaverunt eum discipuli ejus: Rabbi, quis peccavit, hic, aut parentes ejus, ut cæcus nasceretur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 3, 'Respondit Jesus: Neque hic peccavit, neque parentes ejus: sed ut manifestentur opera Dei in illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 4, 'Me oportet operari opera ejus qui misit me, donec dies est: venit nox, quando nemo potest operari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 5, 'quamdiu sum in mundo, lux sum mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 6, 'Hæc cum dixisset, exspuit in terram, et fecit lutum ex sputo, et linivit lutum super oculos ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 7, 'et dixit ei: Vade, lava in natatoria Siloë (quod interpretatur Missus). Abiit ergo, et lavit, et venit videns.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 8, 'Itaque vicini, et qui viderant eum prius quia mendicus erat, dicebant: Nonne hic est qui sedebat, et mendicabat? Alii dicebant: Quia hic est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 9, 'Alii autem: Nequaquam, sed similis est ei. Ille vero dicebat: Quia ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 10, 'Dicebant ergo ei: Quomodo aperti sunt tibi oculi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 11, 'Respondit: Ille homo qui dicitur Jesus, lutum fecit: et unxit oculos meos, et dixit mihi: Vade ad natatoria Siloë, et lava. Et abii, et lavi, et video.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 12, 'Et dixerunt ei: Ubi est ille? Ait: Nescio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 13, 'Adducunt eum ad pharisæos, qui cæcus fuerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 14, 'Erat autem sabbatum quando lutum fecit Jesus, et aperuit oculos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 15, 'Iterum ergo interrogabant eum pharisæi quomodo vidisset. Ille autem dixit eis: Lutum mihi posuit super oculos, et lavi, et video.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 16, 'Dicebant ergo ex pharisæis quidam: Non est hic homo a Deo, qui sabbatum non custodit. Alii autem dicebant: Quomodo potest homo peccator hæc signa facere? Et schisma erat inter eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 17, 'Dicunt ergo cæco iterum: Tu quid dicis de illo qui aperuit oculos tuos? Ille autem dixit: Quia propheta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 18, 'Non crediderunt ergo Judæi de illo, quia cæcus fuisset et vidisset, donec vocaverunt parentes ejus, qui viderat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 19, 'et interrogaverunt eos, dicentes: Hic est filius vester, quem vos dicitis quia cæcus natus est? quomodo ergo nunc videt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 20, 'Responderunt eis parentes ejus, et dixerunt: Scimus quia hic est filius noster, et quia cæcus natus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 21, 'quomodo autem nunc videat, nescimus: aut quis ejus aperuit oculos, nos nescimus; ipsum interrogate: ætatem habet, ipse de se loquatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 22, 'Hæc dixerunt parentes ejus, quoniam timebant Judæos: jam enim conspiraverunt Judæi, ut si quis eum confiteretur esse Christum, extra synagogam fieret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 23, 'Propterea parentes ejus dixerunt: Quia ætatem habet, ipsum interrogate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 24, 'Vocaverunt ergo rursum hominem qui fuerat cæcus, et dixerunt ei: Da gloriam Deo: nos scimus quia hic homo peccator est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 25, 'Dixit ergo eis ille: Si peccator est, nescio; unum scio, quia cæcus cum essem, modo video.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 26, 'Dixerunt ergo illi: Quid fecit tibi? quomodo aperuit tibi oculos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 27, 'Respondit eis: Dixi vobis jam, et audistis: quod iterum vultis audire? numquid et vos vultis discipuli ejus fieri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 28, 'Maledixerunt ergo ei, et dixerunt: Tu discipulus illius sis: nos autem Moysi discipuli sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 29, 'Nos scimus quia Moysi locutus est Deus; hunc autem nescimus unde sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 30, 'Respondit ille homo, et dixit eis: In hoc enim mirabile est quia vos nescitis unde sit, et aperuit meos oculos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 31, 'scimus autem quia peccatores Deus non audit: sed si quis Dei cultor est, et voluntatem ejus facit, hunc exaudit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 32, 'A sæculo non est auditum quia quis aperuit oculos cæci nati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 33, 'Nisi esset hic a Deo, non poterat facere quidquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 34, 'Responderunt, et dixerunt ei: In peccatis natus es totus, et tu doces nos? Et ejecerunt eum foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 35, 'Audivit Jesus quia ejecerunt eum foras: et cum invenisset eum, dixit ei: Tu credis in Filium Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 36, 'Respondit ille, et dixit: Quis est, Domine, ut credam in eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 37, 'Et dixit ei Jesus: Et vidisti eum, et qui loquitur tecum, ipse est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 38, 'At ille ait: Credo, Domine. Et procidens adoravit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 39, 'Et dixit Jesus: In judicium ego in hunc mundum veni: ut qui non vident videant, et qui vident cæci fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 40, 'Et audierunt quidam ex pharisæis qui cum ipso erant, et dixerunt ei: Numquid et nos cæci sumus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 41, 'Dixit eis Jesus: Si cæci essetis, non haberetis peccatum. Nunc vero dicitis, Quia videmus: peccatum vestrum manet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 1, 'Amen, amen dico vobis: qui non intrat per ostium in ovile ovium, sed ascendit aliunde, ille fur est et latro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 2, 'Qui autem intrat per ostium, pastor est ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 3, 'Huic ostiarius aperit, et oves vocem ejus audiunt, et proprias oves vocat nominatim, et educit eas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 4, 'Et cum proprias oves emiserit, ante eas vadit: et oves illum sequuntur, quia sciunt vocem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 5, 'Alienum autem non sequuntur, sed fugiunt ab eo: quia non noverunt vocem alienorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 6, 'Hoc proverbium dixit eis Jesus: illi autem non cognoverunt quid loqueretur eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 7, 'Dixit ergo eis iterum Jesus: Amen, amen dico vobis, quia ego sum ostium ovium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 8, 'Omnes quotquot venerunt, fures sunt, et latrones, et non audierunt eos oves.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 9, 'Ego sum ostium. Per me si quis introierit, salvabitur: et ingredietur, et egredietur, et pascua inveniet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 10, 'Fur non venit nisi ut furetur, et mactet, et perdat. Ego veni ut vitam habeant, et abundantius habeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 11, 'Ego sum pastor bonus. Bonus pastor animam suam dat pro ovibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 12, 'Mercenarius autem, et qui non est pastor, cujus non sunt oves propriæ, videt lupum venientem, et dimittit oves, et fugit: et lupus rapit, et dispergit oves;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 13, 'mercenarius autem fugit, quia mercenarius est, et non pertinet ad eum de ovibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 14, 'Ego sum pastor bonus: et cognosco meas, et cognoscunt me meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 15, 'Sicut novit me Pater, et ego agnosco Patrem: et animam meam pono pro ovibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 16, 'Et alias oves habeo, quæ non sunt ex hoc ovili: et illas oportet me adducere, et vocem meam audient, et fiet unum ovile et unus pastor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 17, 'Propterea me diligit Pater: quia ego pono animam meam, ut iterum sumam eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 18, 'Nemo tollit eam a me: sed ego pono eam a meipso, et potestatem habeo ponendi eam, et potestatem habeo iterum sumendi eam. Hoc mandatum accepi a Patre meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 19, 'Dissensio iterum facta est inter Judæos propter sermones hos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 20, 'Dicebant autem multi ex ipsis: Dæmonium habet, et insanit: quid eum auditis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 21, 'Alii dicebant: Hæc verba non sunt dæmonium habentis: numquid dæmonium potest cæcorum oculos aperire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 22, 'Facta sunt autem Encænia in Jerosolymis, et hiems erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 23, 'Et ambulabat Jesus in templo, in porticu Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 24, 'Circumdederunt ergo eum Judæi, et dicebant ei: Quousque animam nostram tollis? si tu es Christus, dic nobis palam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 25, 'Respondit eis Jesus: Loquor vobis, et non creditis: opera quæ ego facio in nomine Patris mei, hæc testimonium perhibent de me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 26, 'sed vos non creditis, quia non estis ex ovibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 27, 'Oves meæ vocem meam audiunt, et ego cognosco eas, et sequuntur me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 28, 'et ego vitam æternam do eis, et non peribunt in æternum, et non rapiet eas quisquam de manu mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 29, 'Pater meus quod dedit mihi, majus omnibus est: et nemo potest rapere de manu Patris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 30, 'Ego et Pater unum sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 31, 'Sustulerunt ergo lapides Judæi, ut lapidarent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 32, 'Respondit eis Jesus: Multa bona opera ostendi vobis ex Patre meo: propter quod eorum opus me lapidatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 33, 'Responderunt ei Judæi: De bono opere non lapidamus te, sed de blasphemia; et quia tu homo cum sis, facis teipsum Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 34, 'Respondit eis Jesus: Nonne scriptum est in lege vestra, Quia ego dixi: Dii estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 35, 'Si illos dixit deos, ad quos sermo Dei factus est, et non potest solvi Scriptura:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 36, 'quem Pater sanctificavit, et misit in mundum vos dicitis: Quia blasphemas, quia dixi: Filius Dei sum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 37, 'Si non facio opera Patris mei, nolite credere mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 38, 'Si autem facio: etsi mihi non vultis credere, operibus credite, ut cognoscatis, et credatis quia Pater in me est, et ego in Patre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 39, 'Quærebant ergo eum apprehendere: et exivit de manibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 40, 'Et abiit iterum trans Jordanem, in eum locum ubi erat Joannes baptizans primum, et mansit illic;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 41, 'et multi venerunt ad eum, et dicebant: Quia Joannes quidem signum fecit nullum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 42, 'Omnia autem quæcumque dixit Joannes de hoc, vera erant. Et multi crediderunt in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 1, 'Erat autem quidam languens Lazarus a Bethania, de castello Mariæ et Marthæ sororis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 2, '(Maria autem erat quæ unxit Dominum unguento, et extersit pedes ejus capillis suis: cujus frater Lazarus infirmabatur.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 3, 'Miserunt ergo sorores ejus ad eum dicentes: Domine, ecce quem amas infirmatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 4, 'Audiens autem Jesus dixit eis: Infirmitas hæc non est ad mortem, sed pro gloria Dei, ut glorificetur Filius Dei per eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 5, 'Diligebat autem Jesus Martham, et sororem ejus Mariam, et Lazarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 6, 'Ut ergo audivit quia infirmabatur, tunc quidem mansit in eodem loco duobus diebus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 7, 'deinde post hæc dixit discipulis suis: Eamus in Judæam iterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 8, 'Dicunt ei discipuli: Rabbi, nunc quærebant te Judæi lapidare, et iterum vadis illuc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 9, 'Respondit Jesus: Nonne duodecim sunt horæ diei? Si quis ambulaverit in die, non offendit, quia lucem hujus mundi videt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 10, 'si autem ambulaverit in nocte, offendit, quia lux non est in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 11, 'Hæc ait, et post hæc dixit eis: Lazarus amicus noster dormit: sed vado ut a somno excitem eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 12, 'Dixerunt ergo discipuli ejus: Domine, si dormit, salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 13, 'Dixerat autem Jesus de morte ejus: illi autem putaverunt quia de dormitione somni diceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 14, 'Tunc ergo Jesus dixit eis manifeste: Lazarus mortuus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 15, 'et gaudeo propter vos, ut credatis, quoniam non eram ibi, sed eamus ad eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 16, 'Dixit ergo Thomas, qui dicitur Didymus, ad condiscipulos: Eamus et nos, ut moriamur cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 17, 'Venit itaque Jesus: et invenit eum quatuor dies jam in monumento habentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 18, '(Erat autem Bethania juxta Jerosolymam quasi stadiis quindecim.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 19, 'Multi autem ex Judæis venerant ad Martham et Mariam, ut consolarentur eas de fratre suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 20, 'Martha ergo ut audivit quia Jesus venit, occurrit illi: Maria autem domi sedebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 21, 'Dixit ergo Martha ad Jesum: Domine, si fuisses hic, frater meus non fuisset mortuus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 22, 'sed et nunc scio quia quæcumque poposceris a Deo, dabit tibi Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 23, 'Dicit illi Jesus: Resurget frater tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 24, 'Dicit ei Martha: Scio quia resurget in resurrectione in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 25, 'Dixit ei Jesus: Ego sum resurrectio et vita: qui credit in me, etiam si mortuus fuerit, vivet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 26, 'et omnis qui vivit et credit in me, non morietur in æternum. Credis hoc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 27, 'Ait illi: Utique Domine, ego credidi quia tu es Christus, Filius Dei vivi, qui in hunc mundum venisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 28, 'Et cum hæc dixisset, abiit, et vocavit Mariam sororem suam silentio, dicens: Magister adest, et vocat te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 29, 'Illa ut audivit, surgit cito, et venit ad eum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 30, 'nondum enim venerat Jesus in castellum: sed erat adhuc in illo loco, ubi occurrerat ei Martha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 31, 'Judæi ergo, qui erant cum ea in domo, et consolabantur eam, cum vidissent Mariam quia cito surrexit, et exiit, secuti sunt eam dicentes: Quia vadit ad monumentum, ut ploret ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 32, 'Maria ergo, cum venisset ubi erat Jesus, videns eum, cecidit ad pedes ejus, et dicit ei: Domine, si fuisses hic, non esset mortuus frater meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 33, 'Jesus ergo, ut vidit eam plorantem, et Judæos, qui venerant cum ea, plorantes, infremuit spiritu, et turbavit seipsum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 34, 'et dixit: Ubi posuistis eum? Dicunt ei: Domine, veni, et vide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 35, 'Et lacrimatus est Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 36, 'Dixerunt ergo Judæi: Ecce quomodo amabat eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 37, 'Quidam autem ex ipsis dixerunt: Non poterat hic, qui aperuit oculos cæci nati, facere ut hic non moreretur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 38, 'Jesus ergo rursum fremens in semetipso, venit ad monumentum. Erat autem spelunca, et lapis superpositus erat ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 39, 'Ait Jesus: Tollite lapidem. Dicit ei Martha, soror ejus qui mortuus fuerat: Domine, jam fœtet, quatriduanus est enim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 40, 'Dicit ei Jesus: Nonne dixi tibi quoniam si credideris, videbis gloriam Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 41, 'Tulerunt ergo lapidem: Jesus autem, elevatis sursum oculis, dixit: Pater, gratias ago tibi quoniam audisti me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 42, 'Ego autem sciebam quia semper me audis, sed propter populum qui circumstat, dixi: ut credant quia tu me misisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 43, 'Hæc cum dixisset, voce magna clamavit: Lazare, veni foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 44, 'Et statim prodiit qui fuerat mortuus, ligatus pedes, et manus institis, et facies illius sudario erat ligata. Dixit eis Jesus: Solvite eum et sinite abire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 45, 'Multi ergo ex Judæis, qui venerant ad Mariam, et Martham, et viderant quæ fecit Jesus, crediderunt in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 46, 'Quidam autem ex ipsis abierunt ad pharisæos, et dixerunt eis quæ fecit Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 47, 'Collegerunt ergo pontifices et pharisæi concilium, et dicebant: Quid facimus, quia hic homo multa signa facit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 48, 'Si dimittimus eum sic, omnes credent in eum, et venient Romani, et tollent nostrum locum, et gentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 49, 'Unus autem ex ipsis, Caiphas nomine, cum esset pontifex anni illius, dixit eis: Vos nescitis quidquam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 50, 'nec cogitatis quia expedit vobis ut unus moriatur homo pro populo, et non tota gens pereat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 51, 'Hoc autem a semetipso non dixit: sed cum esset pontifex anni illius, prophetavit, quod Jesus moriturus erat pro gente,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 52, 'et non tantum pro gente, sed ut filios Dei, qui erant dispersi, congregaret in unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 53, 'Ab illo ergo die cogitaverunt ut interficerent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 54, 'Jesus ergo jam non in palam ambulabat apud Judæos, sed abiit in regionem juxta desertum, in civitatem quæ dicitur Ephrem, et ibi morabatur cum discipulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 55, 'Proximum autem erat Pascha Judæorum, et ascenderunt multi Jerosolymam de regione ante Pascha, ut sanctificarent seipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 56, 'Quærebant ergo Jesum, et colloquebantur ad invicem, in templo stantes: Quid putatis, quia non venit ad diem festum? Dederant autem pontifices et pharisæi mandatum ut si quis cognoverit ubi sit, indicet, ut apprehendant eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 57, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 1, 'Jesus ergo ante sex dies Paschæ venit Bethaniam, ubi Lazarus fuerat mortuus, quem suscitavit Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 2, 'Fecerunt autem ei cœnam ibi, et Martha ministrabat, Lazarus vero unus erat ex discumbentibus cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 3, 'Maria ergo accepit libram unguenti nardi pistici pretiosi, et unxit pedes Jesu, et extersit pedes ejus capillis suis: et domus impleta est ex odore unguenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 4, 'Dixit ergo unus ex discipulis ejus, Judas Iscariotes, qui erat eum traditurus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 5, 'Quare hoc unguentum non veniit trecentis denariis, et datum est egenis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 6, 'Dixit autem hoc, non quia de egenis pertinebat ad eum, sed quia fur erat, et loculos habens, ea quæ mittebantur, portabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 7, 'Dixit ergo Jesus: Sinite illam ut in diem sepulturæ meæ servet illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 8, 'Pauperes enim semper habetis vobiscum: me autem non semper habetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 9, 'Cognovit ergo turba multa ex Judæis quia illic est, et venerunt, non propter Jesum tantum, sed ut Lazarum viderent, quem suscitavit a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 10, 'Cogitaverunt autem principes sacerdotum ut et Lazarum interficerent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 11, 'quia multi propter illum abibant ex Judæis, et credebant in Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 12, 'In crastinum autem, turba multa quæ venerat ad diem festum, cum audissent quia venit Jesus Jerosolymam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 13, 'acceperunt ramos palmarum, et processerunt obviam ei, et clamabant: Hosanna, benedictus qui venit in nomine Domini, rex Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 14, 'Et invenit Jesus asellum, et sedit super eum, sicut scriptum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 15, 'Noli timere, filia Sion: ecce rex tuus venit sedens super pullum asinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 16, 'Hæc non cognoverunt discipuli ejus primum: sed quando glorificatus est Jesus, tunc recordati sunt quia hæc erant scripta de eo, et hæc fecerunt ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 17, 'Testimonium ergo perhibebat turba, quæ erat cum eo quando Lazarum vocavit de monumento, et suscitavit eum a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 18, 'Propterea et obviam venit ei turba: quia audierunt fecisse hoc signum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 19, 'Pharisæi ergo dixerunt ad semetipsos: Videtis quia nihil proficimus? ecce mundus totus post eum abiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 20, 'Erant autem quidam gentiles, ex his qui ascenderant ut adorarent in die festo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 21, 'Hi ergo accesserunt ad Philippum, qui erat a Bethsaida Galilææ, et rogabant eum, dicentes: Domine, volumus Jesum videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 22, 'Venit Philippus, et dicit Andreæ; Andreas rursum et Philippus dixerunt Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 23, 'Jesus autem respondit eis, dicens: Venit hora, ut clarificetur Filius hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 24, 'Amen, amen dico vobis, nisi granum frumenti cadens in terram, mortuum fuerit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 25, 'ipsum solum manet: si autem mortuum fuerit, multum fructum affert. Qui amat animam suam, perdet eam; et qui odit animam suam in hoc mundo, in vitam æternam custodit eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 26, 'Si quis mihi ministrat, me sequatur, et ubi sum ego, illic et minister meus erit. Si quis mihi ministraverit, honorificabit eum Pater meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 27, 'Nunc anima mea turbata est. Et quid dicam? Pater, salvifica me ex hac hora. Sed propterea veni in horam hanc:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 28, 'Pater, clarifica nomen tuum. Venit ergo vox de cælo: Et clarificavi, et iterum clarificabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 29, 'Turba ergo, quæ stabat, et audierat, dicebat tonitruum esse factum. Alii dicebant: Angelus ei locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 30, 'Respondit Jesus, et dixit: Non propter me hæc vox venit, sed propter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 31, 'Nunc judicium est mundi: nunc princeps hujus mundi ejicietur foras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 32, 'Et ego, si exaltatus fuero a terra, omnia traham ad meipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 33, '(Hoc autem dicebat, significans qua morte esset moriturus.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 34, 'Respondit ei turba: Nos audivimus ex lege, quia Christus manet in æternum: et quomodo tu dicis: Oportet exaltari Filium hominis? quis est iste Filius hominis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 35, 'Dixit ergo eis Jesus: Adhuc modicum, lumen in vobis est. Ambulate dum lucem habetis, ut non vos tenebræ comprehendant; et qui ambulat in tenebris, nescit quo vadat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 36, 'Dum lucem habetis, credite in lucem, ut filii lucis sitis. Hæc locutus est Jesus, et abiit et abscondit se ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 37, 'Cum autem tanta signa fecisset coram eis, non credebant in eum;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 38, 'ut sermo Isaiæ prophetæ impleretur, quem dixit: Domine, quis credidit auditui nostro? et brachium Domini cui revelatum est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 39, 'Propterea non poterant credere, quia iterum dixit Isaias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 40, 'Excæcavit oculos eorum, et induravit cor eorum ut non videant oculis, et non intelligant corde, et convertantur, et sanem eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 41, 'Hæc dixit Isaias, quando vidit gloriam ejus, et locutus est de eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 42, 'Verumtamen et ex principibus multi crediderunt in eum: sed propter pharisæos non confitebantur, ut e synagoga non ejicerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 43, 'Dilexerunt enim gloriam hominum magis quam gloriam Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 44, 'Jesus autem clamavit, et dixit: Qui credit in me, non credit in me, sed in eum qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 45, 'Et qui videt me, videt eum qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 46, 'Ego lux in mundum veni, ut omnis qui credit in me, in tenebris non maneat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 47, 'Et si quis audierit verba mea, et non custodierit, ego non judico eum; non enim veni ut judicem mundum, sed ut salvificem mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 48, 'Qui spernit me et non accipit verba mea, habet qui judicet eum. Sermo quem locutus sum, ille judicabit eum in novissimo die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 49, 'Quia ego ex meipso non sum locutus, sed qui misit me, Pater, ipse mihi mandatum dedit quid dicam et quid loquar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 50, 'Et scio quia mandatum ejus vita æterna est: quæ ergo ego loquor, sicut dixit mihi Pater, sic loquor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 1, 'Ante diem festum Paschæ, sciens Jesus quia venit hora ejus ut transeat ex hoc mundo ad Patrem: cum dilexisset suos, qui erant in mundo, in finem dilexit eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 2, 'Et cœna facta, cum diabolus jam misisset in cor ut traderet eum Judas Simonis Iscariotæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 3, 'sciens quia omnia dedit ei Pater in manus, et quia a Deo exivit, et ad Deum vadit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 4, 'surgit a cœna, et ponit vestimenta sua, et cum accepisset linteum, præcinxit se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 5, 'Deinde mittit aquam in pelvim, et cœpit lavare pedes discipulorum, et extergere linteo, quo erat præcinctus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 6, 'Venit ergo ad Simonem Petrum. Et dicit ei Petrus: Domine, tu mihi lavas pedes?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 7, 'Respondit Jesus, et dixit ei: Quod ego facio, tu nescis modo: scies autem postea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 8, 'Dicit ei Petrus: Non lavabis mihi pedes in æternum. Respondit ei Jesus: Si non lavero te, non habebis partem mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 9, 'Dicit ei Simon Petrus: Domine, non tantum pedes meos, sed et manus, et caput.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 10, 'Dicit ei Jesus: Qui lotus est, non indiget nisi ut pedes lavet, sed est mundus totus. Et vos mundi estis, sed non omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 11, 'Sciebat enim quisnam esset qui traderet eum; propterea dixit: Non estis mundi omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 12, 'Postquam ergo lavit pedes eorum, et accepit vestimenta sua, cum recubuisset iterum, dixit eis: Scitis quid fecerim vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 13, 'Vos vocatis me Magister et Domine, et bene dicitis: sum etenim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 14, 'Si ergo ego lavi pedes vestros, Dominus et Magister, et vos debetis alter alterius lavare pedes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 15, 'Exemplum enim dedi vobis, ut quemadmodum ego feci vobis, ita et vos faciatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 16, 'Amen, amen dico vobis: non est servus major domino suo: neque apostolus major est eo qui misit illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 17, 'Si hæc scitis, beati eritis si feceritis ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 18, 'Non de omnibus vobis dico: ego scio quos elegerim; sed ut adimpleatur Scriptura: Qui manducat mecum panem, levabit contra me calcaneum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 19, 'Amodo dico vobis, priusquam fiat: ut cum factum fuerit, credatis quia ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 20, 'Amen, amen dico vobis: qui accipit si quem misero, me accipit; qui autem me accipit, accipit eum qui me misit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 21, 'Cum hæc dixisset Jesus, turbatus est spiritu: et protestatus est, et dixit: Amen, amen dico vobis, quia unus ex vobis tradet me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 22, 'Aspiciebant ergo ad invicem discipuli, hæsitantes de quo diceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 23, 'Erat ergo recumbens unus ex discipulis ejus in sinu Jesu, quem diligebat Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 24, 'Innuit ergo huic Simon Petrus, et dixit ei: Quis est, de quo dicit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 25, 'Itaque cum recubuisset ille supra pectus Jesu, dicit ei: Domine, quis est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 26, 'Respondit Jesus: Ille est cui ego intinctum panem porrexero. Et cum intinxisset panem, dedit Judæ Simonis Iscariotæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 27, 'Et post buccellam, introivit in eum Satanas. Et dixit ei Jesus: Quod facis, fac citius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 28, 'Hoc autem nemo scivit discumbentium ad quid dixerit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 29, 'Quidam enim putabant, quia loculos habebat Judas, quod dixisset ei Jesus: Eme ea quæ opus sunt nobis ad diem festum: aut egenis ut aliquid daret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 30, 'Cum ergo accepisset ille buccellam, exivit continuo. Erat autem nox.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 31, 'Cum ergo exisset, dixit Jesus: Nunc clarificatus est Filius hominis, et Deus clarificatus est in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 32, 'Si Deus clarificatus est in eo, et Deus clarificabit eum in semetipso: et continuo clarificabit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 33, 'Filioli, adhuc modicum vobiscum sum. Quæretis me; et sicut dixi Judæis, quo ego vado, vos non potestis venire: et vobis dico modo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 34, 'Mandatum novum do vobis: ut diligatis invicem: sicut dilexi vos, ut et vos diligatis invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 35, 'In hoc cognoscent omnes quia discipuli mei estis, si dilectionem habueritis ad invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 36, 'Dicit ei Simon Petrus: Domine, quo vadis? Respondit Jesus: Quo ego vado non potes me modo sequi: sequeris autem postea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 37, 'Dicit ei Petrus: Quare non possum te sequi modo? animam meam pro te ponam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 38, 'Respondit ei Jesus: Animam tuam pro me pones? amen, amen dico tibi: non cantabit gallus, donec ter me neges.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 1, 'Non turbetur cor vestrum. Creditis in Deum, et in me credite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 2, 'In domo Patris mei mansiones multæ sunt; si quominus dixissem vobis: quia vado parare vobis locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 3, 'Et si abiero, et præparavero vobis locum, iterum venio, et accipiam vos ad meipsum: ut ubi sum ego, et vos sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 4, 'Et quo ego vado scitis, et viam scitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 5, 'Dicit ei Thomas: Domine, nescimus quo vadis: et quomodo possumus viam scire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 6, 'Dicit ei Jesus: Ego sum via, et veritas, et vita. Nemo venit ad Patrem, nisi per me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 7, 'Si cognovissetis me, et Patrem meum utique cognovissetis: et amodo cognoscetis eum, et vidistis eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 8, 'Dicit ei Philippus: Domine, ostende nobis Patrem, et sufficit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 9, 'Dicit ei Jesus: Tanto tempore vobiscum sum, et non cognovistis me? Philippe, qui videt me, videt et Patrem. Quomodo tu dicis: Ostende nobis Patrem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 10, 'Non creditis quia ego in Patre, et Pater in me est? Verba quæ ego loquor vobis, a meipso non loquor. Pater autem in me manens, ipse fecit opera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 11, 'Non creditis quia ego in Patre, et Pater in me est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 12, 'alioquin propter opera ipsa credite. Amen, amen dico vobis, qui credit in me, opera quæ ego facio, et ipse faciet, et majora horum faciet: quia ego ad Patrem vado.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 13, 'Et quodcumque petieritis Patrem in nomine meo, hoc faciam: ut glorificetur Pater in Filio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 14, 'Si quid petieritis me in nomine meo, hoc faciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 15, 'Si diligitis me, mandata mea servate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 16, 'et ego rogabo Patrem, et alium Paraclitum dabit vobis, ut maneat vobiscum in æternum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 17, 'Spiritum veritatis, quem mundus non potest accipere, quia non videt eum, nec scit eum: vos autem cognoscetis eum, quia apud vos manebit, et in vobis erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 18, 'Non relinquam vos orphanos: veniam ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 19, 'Adhuc modicum, et mundus me jam non videt. Vos autem videtis me: quia ego vivo, et vos vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 20, 'In illo die vos cognoscetis quia ego sum in Patre meo, et vos in me, et ego in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 21, 'Qui habet mandata mea, et servat ea: ille est qui diligit me. Qui autem diligit me, diligetur a Patre meo: et ego diligam eum, et manifestabo ei meipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 22, 'Dicit ei Judas, non ille Iscariotes: Domine, quid factum est, quia manifestaturus es nobis teipsum, et non mundo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 23, 'Respondit Jesus, et dixit ei: Si quis diligit me, sermonem meum servabit, et Pater meus diliget eum, et ad eum veniemus, et mansionem apud eum faciemus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 24, 'qui non diligit me, sermones meos non servat. Et sermonem, quem audistis, non est meus: sed ejus qui misit me, Patris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 25, 'Hæc locutus sum vobis apud vos manens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 26, 'Paraclitus autem Spiritus Sanctus, quem mittet Pater in nomine meo, ille vos docebit omnia, et suggeret vobis omnia quæcumque dixero vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 27, 'Pacem relinquo vobis, pacem meam do vobis: non quomodo mundus dat, ego do vobis. Non turbetur cor vestrum, neque formidet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 28, 'Audistis quia ego dixi vobis: Vado, et venio ad vos. Si diligeretis me, gauderetis utique, quia vado ad Patrem: quia Pater major me est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 29, 'Et nunc dixi vobis priusquam fiat: ut cum factum fuerit, credatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 30, 'Jam non multa loquar vobiscum: venit enim princeps mundi hujus, et in me non habet quidquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 31, 'Sed ut cognoscat mundus quia diligo Patrem, et sicut mandatum dedit mihi Pater, sic facio. Surgite, eamus hinc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 1, 'Ego sum vitis vera, et Pater meus agricola est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 2, 'Omnem palmitem in me non ferentem fructum, tollet eum, et omnem qui fert fructum, purgabit eum, ut fructum plus afferat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 3, 'Jam vos mundi estis propter sermonem quem locutus sum vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 4, 'Manete in me, et ego in vobis. Sicut palmes non potest ferre fructum a semetipso, nisi manserit in vite, sic nec vos, nisi in me manseritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 5, 'Ego sum vitis, vos palmites: qui manet in me, et ego in eo, hic fert fructum multum, quia sine me nihil potestis facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 6, 'Si quis in me non manserit, mittetur foras sicut palmes, et arescet, et colligent eum, et in ignem mittent, et ardet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 7, 'Si manseritis in me, et verba mea in vobis manserint, quodcumque volueritis petetis, et fiet vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 8, 'In hoc clarificatus est Pater meus, ut fructum plurimum afferatis, et efficiamini mei discipuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 9, 'Sicut dilexit me Pater, et ego dilexi vos. Manete in dilectione mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 10, 'Si præcepta mea servaveritis, manebitis in dilectione mea, sicut et ego Patris mei præcepta servavi, et maneo in ejus dilectione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 11, 'Hæc locutus sum vobis: ut gaudium meum in vobis sit, et gaudium vestrum impleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 12, 'Hoc est præceptum meum, ut diligatis invicem, sicut dilexi vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 13, 'Majorem hac dilectionem nemo habet, ut animam suam ponat quis pro amicis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 14, 'Vos amici mei estis, si feceritis quæ ego præcipio vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 15, 'Jam non dicam vos servos: quia servus nescit quid faciat dominus ejus. Vos autem dixi amicos: quia omnia quæcumque audivi a Patre meo, nota feci vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 16, 'Non vos me elegistis, sed ego elegi vos, et posui vos ut eatis, et fructum afferatis, et fructus vester maneat: ut quodcumque petieritis Patrem in nomine meo, det vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 17, 'Hæc mando vobis: ut diligatis invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 18, 'Si mundus vos odit, scitote quia me priorem vobis odio habuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 19, 'Si de mundo fuissetis, mundus quod suum erat diligeret: quia vero de mundo non estis, sed ego elegi vos de mundo, propterea odit vos mundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 20, 'Mementote sermonis mei, quem ego dixi vobis: non est servus major domino suo. Si me persecuti sunt, et vos persequentur; si sermonem meum servaverunt, et vestrum servabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 21, 'Sed hæc omnia facient vobis propter nomen meum: quia nesciunt eum qui misit me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 22, 'Si non venissem, et locutus fuissem eis, peccatum non haberent: nunc autem excusationem non habent de peccato suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 23, 'Qui me odit, et Patrem meum odit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 24, 'Si opera non fecissem in eis quæ nemo alius fecit, peccatum non haberent: nunc autem et viderunt, et oderunt et me, et Patrem meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 25, 'Sed ut adimpleatur sermo, qui in lege eorum scriptus est: Quia odio habuerunt me gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 26, 'Cum autem venerit Paraclitus, quem ego mittam vobis a Patre, Spiritum veritatis, qui a Patre procedit, ille testimonium perhibebit de me;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 27, 'et vos testimonium perhibebitis, quia ab initio mecum estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 1, 'Hæc locutus sum vobis, ut non scandalizemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 2, 'Absque synagogis facient vos: sed venit hora, ut omnis qui interficit vos arbitretur obsequium se præstare Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 3, 'Et hæc facient vobis, quia non noverunt Patrem, neque me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 4, 'Sed hæc locutus sum vobis, ut cum venerit hora eorum, reminiscamini quia ego dixi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 5, 'Hæc autem vobis ab initio non dixi, quia vobiscum eram. Et nunc vado ad eum qui misit me; et nemo ex vobis interrogat me: Quo vadis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 6, 'sed quia hæc locutus sum vobis, tristitia implevit cor vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 7, 'Sed ego veritatem dico vobis: expedit vobis ut ego vadam: si enim non abiero, Paraclitus non veniet ad vos; si autem abiero, mittam eum ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 8, 'Et cum venerit ille, arguet mundum de peccato, et de justitia, et de judicio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 9, 'De peccato quidem, quia non crediderunt in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 10, 'De justitia vero, quia ad Patrem vado, et jam non videbitis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 11, 'De judicio autem, quia princeps hujus mundi jam judicatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 12, 'Adhuc multa habeo vobis dicere, sed non potestis portare modo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 13, 'Cum autem venerit ille Spiritus veritatis, docebit vos omnem veritatem: non enim loquetur a semetipso, sed quæcumque audiet loquetur, et quæ ventura sunt annuntiabit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 14, 'Ille me clarificabit, quia de meo accipiet, et annuntiabit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 15, 'Omnia quæcumque habet Pater, mea sunt. Propterea dixi: quia de meo accipiet, et annuntiabit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 16, 'Modicum, et jam non videbitis me; et iterum modicum, et videbitis me: quia vado ad Patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 17, 'Dixerunt ergo ex discipulis ejus ad invicem: Quid est hoc quod dicit nobis: Modicum, et non videbitis me; et iterum modicum, et videbitis me, et quia vado ad Patrem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 18, 'Dicebant ergo: Quid est hoc quod dicit: Modicum? nescimus quid loquitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 19, 'Cognovit autem Jesus, quia volebant eum interrogare, et dixit eis: De hoc quæritis inter vos quia dixi: Modicum, et non videbitis me; et iterum modicum, et videbitis me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 20, 'Amen, amen dico vobis: quia plorabitis, et flebitis vos, mundus autem gaudebit; vos autem contristabimini, sed tristitia vestra vertetur in gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 21, 'Mulier cum parit, tristitiam habet, quia venit hora ejus; cum autem pepererit puerum, jam non meminit pressuræ propter gaudium, quia natus est homo in mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 22, 'Et vos igitur nunc quidem tristitiam habetis, iterum autem videbo vos, et gaudebit cor vestrum: et gaudium vestrum nemo tollet a vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 23, 'Et in illo die me non rogabitis quidquam. Amen, amen dico vobis: si quid petieritis Patrem in nomine meo, dabit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 24, 'Usque modo non petistis quidquam in nomine meo: petite, et accipietis, ut gaudium vestrum sit plenum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 25, 'Hæc in proverbiis locutus sum vobis. Venit hora cum jam non in proverbiis loquar vobis, sed palam de Patre annuntiabo vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 26, 'in illo die in nomine meo petetis: et non dico vobis quia ego rogabo Patrem de vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 27, 'ipse enim Pater amat vos, quia vos me amastis, et credidistis, quia ego a Deo exivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 28, 'Exivi a Patre, et veni in mundum: iterum relinquo mundum, et vado ad Patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 29, 'Dicunt ei discipuli ejus: Ecce nunc palam loqueris, et proverbium nullum dicis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 30, 'nunc scimus quia scis omnia, et non opus est tibi ut quis te interroget: in hoc credimus quia a Deo existi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 31, 'Respondit eis Jesus: Modo creditis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 32, 'ecce venit hora, et jam venit, ut dispergamini unusquisque in propria, et me solum relinquatis: et non sum solus, quia Pater mecum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 16, 33, 'Hæc locutus sum vobis, ut in me pacem habeatis. In mundo pressuram habebitis: sed confidite, ego vici mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 1, 'Hæc locutus est Jesus: et sublevatis oculis in cælum, dixit: Pater, venit hora: clarifica Filium tuum, ut Filius tuus clarificet te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 2, 'sicut dedisti ei potestatem omnis carnis, ut omne, quod dedisti ei, det eis vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 3, 'Hæc est autem vita æterna: ut cognoscant te, solum Deum verum, et quem misisti Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 4, 'Ego te clarificavi super terram: opus consummavi, quod dedisti mihi ut faciam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 5, 'et nunc clarifica me tu, Pater, apud temetipsum, claritate quam habui, priusquam mundus esset, apud te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 6, 'Manifestavi nomen tuum hominibus, quos dedisti mihi de mundo: tui erant, et mihi eos dedisti: et sermonem tuum servaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 7, 'Nunc cognoverunt quia omnia quæ dedisti mihi, abs te sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 8, 'quia verba quæ dedisti mihi, dedi eis: et ipsi acceperunt, et cognoverunt vere quia a te exivi, et crediderunt quia tu me misisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 9, 'Ego pro eis rogo; non pro mundo rogo, sed pro his quos dedisti mihi: quia tui sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 10, 'et mea omnia tua sunt, et tua mea sunt: et clarificatus sum in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 11, 'Et jam non sum in mundo, et hi in mundo sunt, et ego ad te venio. Pater sancte, serva eos in nomine tuo, quos dedisti mihi: ut sint unum, sicut et nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 12, 'Cum essem cum eis, ego servabam eos in nomine tuo. Quos dedisti mihi, custodivi: et nemo ex eis periit, nisi filius perditionis, ut Scriptura impleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 13, 'Nunc autem ad te venio: et hæc loquor in mundo, ut habeant gaudium meum impletum in semetipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 14, 'Ego dedi eis sermonem tuum, et mundus eos odio habuit, quia non sunt de mundo, sicut et ego non sum de mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 15, 'Non rogo ut tollas eos de mundo, sed ut serves eos a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 16, 'De mundo non sunt, sicut et ego non sum de mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 17, 'Sanctifica eos in veritate. Sermo tuus veritas est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 18, 'Sicut tu me misisti in mundum, et ego misi eos in mundum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 19, 'et pro eis ego sanctifico meipsum: ut sint et ipsi sanctificati in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 20, 'Non pro eis autem rogo tantum, sed et pro eis qui credituri sunt per verbum eorum in me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 21, 'ut omnes unum sint, sicut tu Pater in me, et ego in te, ut et ipsi in nobis unum sint: ut credat mundus, quia tu me misisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 22, 'Et ego claritatem, quam dedisti mihi, dedi eis: ut sint unum, sicut et nos unum sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 23, 'Ego in eis, et tu in me: ut sint consummati in unum: et cognoscat mundus quia tu me misisti, et dilexisti eos, sicut et me dilexisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 24, 'Pater, quos dedisti mihi, volo ut ubi sum ego, et illi sint mecum: ut videant claritatem meam, quam dedisti mihi: quia dilexisti me ante constitutionem mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 25, 'Pater juste, mundus te non cognovit, ego autem te cognovi: et hi cognoverunt, quia tu me misisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 17, 26, 'Et notum feci eis nomen tuum, et notum faciam: ut dilectio, qua dilexisti me, in ipsis sit, et ego in ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 1, 'Hæc cum dixisset Jesus, egressus est cum discipulis suis trans torrentem Cedron, ubi erat hortus, in quem introivit ipse, et discipuli ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 2, 'Sciebat autem et Judas, qui tradebat eum, locum: quia frequenter Jesus convenerat illuc cum discipulis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 3, 'Judas ergo cum accepisset cohortem, et a pontificibus et pharisæis ministros, venit illuc cum laternis, et facibus, et armis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 4, 'Jesus itaque sciens omnia quæ ventura erant super eum, processit, et dixit eis: Quem quæritis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 5, 'Responderunt ei: Jesum Nazarenum. Dicit eis Jesus: Ego sum. Stabat autem et Judas, qui tradebat eum, cum ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 6, 'Ut ergo dixit eis: Ego sum: abierunt retrorsum, et ceciderunt in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 7, 'Iterum ergo interrogavit eos: Quem quæritis? Illi autem dixerunt: Jesum Nazarenum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 8, 'Respondit Jesus: Dixi vobis, quia ego sum: si ergo me quæritis, sinite hos abire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 9, 'Ut impleretur sermo, quem dixit: Quia quos dedisti mihi, non perdidi ex eis quemquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 10, 'Simon ergo Petrus habens gladium eduxit eum: et percussit pontificis servum, et abscidit auriculam ejus dexteram. Erat autem nomen servo Malchus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 11, 'Dixit ergo Jesus Petro: Mitte gladium tuum in vaginam. Calicem, quem dedit mihi Pater, non bibam illum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 12, 'Cohors ergo, et tribunus, et ministri Judæorum comprehenderunt Jesum, et ligaverunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 13, 'Et adduxerunt eum ad Annam primum: erat enim socer Caiphæ, qui erat pontifex anni illius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 14, 'Erat autem Caiphas, qui consilium dederat Judæis: Quia expedit unum hominem mori pro populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 15, 'Sequebatur autem Jesum Simon Petrus, et alius discipulus. Discipulus autem ille erat notus pontifici, et introivit cum Jesu in atrium pontificis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 16, 'Petrus autem stabat ad ostium foris. Exivit ergo discipulus alius, qui erat notus pontifici, et dixit ostiariæ: et introduxit Petrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 17, 'Dicit ergo Petro ancilla ostiaria: Numquid et tu ex discipulis es hominis istius? Dicit ille: Non sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 18, 'Stabant autem servi et ministri ad prunas, quia frigus erat, et calefaciebant se: erat autem cum eis et Petrus stans, et calefaciens se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 19, 'Pontifex ergo interrogavit Jesum de discipulis suis, et de doctrina ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 20, 'Respondit ei Jesus: Ego palam locutus sum mundo: ego semper docui in synagoga, et in templo, quo omnes Judæi conveniunt, et in occulto locutus sum nihil.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 21, 'Quid me interrogas? interroga eos qui audierunt quid locutus sim ipsis: ecce hi sciunt quæ dixerim ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 22, 'Hæc autem cum dixisset, unus assistens ministrorum dedit alapam Jesu, dicens: Sic respondes pontifici?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 23, 'Respondit ei Jesus: Si male locutus sum, testimonium perhibe de malo: si autem bene, quid me cædis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 24, 'Et misit eum Annas ligatum ad Caipham pontificem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 25, 'Erat autem Simon Petrus stans, et calefaciens se. Dixerunt ergo ei: Numquid et tu ex discipulis ejus es? Negavit ille, et dixit: Non sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 26, 'Dicit ei unus ex servis pontificis, cognatus ejus, cujus abscidit Petrus auriculam: Nonne ego te vidi in horto cum illo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 27, 'Iterum ergo negavit Petrus: et statim gallus cantavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 28, 'Adducunt ergo Jesum a Caipha in prætorium. Erat autem mane: et ipsi non introierunt in prætorium, ut non contaminarentur, sed ut manducarent Pascha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 29, 'Exivit ergo Pilatus ad eos foras, et dixit: Quam accusationem affertis adversus hominem hunc?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 30, 'Responderunt, et dixerunt ei: Si non esset hic malefactor, non tibi tradidissemus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 31, 'Dixit ergo eis Pilatus: Accipite eum vos, et secundum legem vestram judicate eum. Dixerunt ergo ei Judæi: Nobis non licet interficere quemquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 32, 'Ut sermo Jesu impleretur, quem dixit, significans qua morte esset moriturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 33, 'Introivit ergo iterum in prætorium Pilatus: et vocavit Jesum, et dixit ei: Tu es rex Judæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 34, 'Respondit Jesus: A temetipso hoc dicis, an alii dixerunt tibi de me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 35, 'Respondit Pilatus: Numquid ego Judæus sum? gens tua et pontifices tradiderunt te mihi: quid fecisti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 36, 'Respondit Jesus: Regnum meum non est de hoc mundo. Si ex hoc mundo esset regnum meum, ministri mei utique decertarent ut non traderer Judæis: nunc autem regnum meum non est hinc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 37, 'Dixit itaque ei Pilatus: Ergo rex es tu? Respondit Jesus: Tu dicis quia rex sum ego. Ego in hoc natus sum, et ad hoc veni in mundum, ut testimonium perhibeam veritati: omnis qui est ex veritate, audit vocem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 38, 'Dicit ei Pilatus: Quid est veritas? Et cum hoc dixisset, iterum exivit ad Judæos, et dicit eis: Ego nullam invenio in eo causam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 39, 'Est autem consuetudo vobis ut unum dimittam vobis in Pascha: vultis ergo dimittam vobis regem Judæorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 18, 40, 'Clamaverunt ergo rursum omnes, dicentes: Non hunc, sed Barabbam. Erat autem Barabbas latro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 1, 'Tunc ergo apprehendit Pilatus Jesum, et flagellavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 2, 'Et milites plectentes coronam de spinis, imposuerunt capiti ejus: et veste purpurea circumdederunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 3, 'Et veniebant ad eum, et dicebant: Ave, rex Judæorum: et dabant ei alapas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 4, 'Exivit ergo iterum Pilatus foras, et dicit eis: Ecce adduco vobis eum foras, ut cognoscatis quia nullam invenio in eo causam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 5, '(Exivit ergo Jesus portans coronam spineam, et purpureum vestimentum.) Et dicit eis: Ecce homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 6, 'Cum ergo vidissent eum pontifices et ministri, clamabant, dicentes: Crucifige, crucifige eum. Dicit eis Pilatus: Accipite eum vos, et crucifigite: ego enim non invenio in eo causam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 7, 'Responderunt ei Judæi: Nos legem habemus, et secundum legem debet mori, quia Filium Dei se fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 8, 'Cum ergo audisset Pilatus hunc sermonem, magis timuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 9, 'Et ingressus est prætorium iterum: et dixit ad Jesum: Unde es tu? Jesus autem responsum non dedit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 10, 'Dicit ergo ei Pilatus: Mihi non loqueris? nescis quia potestatem habeo crucifigere te, et potestatem habeo dimittere te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 11, 'Respondit Jesus: Non haberes potestatem adversum me ullam, nisi tibi datum esset desuper. Propterea qui me tradidit tibi, majus peccatum habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 12, 'Et exinde quærebat Pilatus dimittere eum. Judæi autem clamabant dicentes: Si hunc dimittis, non es amicus Cæsaris. Omnis enim qui se regem facit, contradicit Cæsari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 13, 'Pilatus autem cum audisset hos sermones, adduxit foras Jesum: et sedit pro tribunali, in loco qui dicitur Lithostrotos, hebraice autem Gabbatha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 14, 'Erat autem parasceve Paschæ, hora quasi sexta, et dicit Judæis: Ecce rex vester.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 15, 'Illi autem clamabant: Tolle, tolle, crucifige eum. Dicit eis Pilatus: Regem vestrum crucifigam? Responderunt pontifices: Non habemus regem, nisi Cæsarem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 16, 'Tunc ergo tradidit eis illum ut crucifigeretur. Susceperunt autem Jesum, et eduxerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 17, 'Et bajulans sibi crucem exivit in eum, qui dicitur Calvariæ locum, hebraice autem Golgotha:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 18, 'ubi crucifixerunt eum, et cum eo alios duos hinc et hinc, medium autem Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 19, 'Scripsit autem et titulum Pilatus, et posuit super crucem. Erat autem scriptum: Jesus Nazarenus, Rex Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 20, 'Hunc ergo titulum multi Judæorum legerunt: quia prope civitatem erat locus, ubi crucifixus est Jesus, et erat scriptum hebraice, græce, et latine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 21, 'Dicebant ergo Pilato pontifices Judæorum: Noli scribere: Rex Judæorum: sed quia ipse dixit: Rex sum Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 22, 'Respondit Pilatus: Quod scripsi, scripsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 23, 'Milites ergo cum crucifixissent eum, acceperunt vestimenta ejus (et fecerunt quatuor partes, unicuique militi partem) et tunicam. Erat autem tunica inconsutilis, desuper contexta per totum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 24, 'Dixerunt ergo ad invicem: Non scindamus eam, sed sortiamur de illa cujus sit. Ut Scriptura impleretur, dicens: Partiti sunt vestimenta mea sibi: et in vestem meam miserunt sortem. Et milites quidem hæc fecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 25, 'Stabant autem juxta crucem Jesu mater ejus, et soror matris ejus, Maria Cleophæ, et Maria Magdalene.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 26, 'Cum vidisset ergo Jesus matrem, et discipulum stantem, quem diligebat, dicit matri suæ: Mulier, ecce filius tuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 27, 'Deinde dicit discipulo: Ecce mater tua. Et ex illa hora accepit eam discipulus in sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 28, 'Postea sciens Jesus quia omnia consummata sunt, ut consummaretur Scriptura, dixit: Sitio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 29, 'Vas ergo erat positum aceto plenum. Illi autem spongiam plenam aceto, hyssopo circumponentes, obtulerunt ori ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 30, 'Cum ergo accepisset Jesus acetum, dixit: Consummatum est. Et inclinato capite tradidit spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 31, 'Judæi ergo (quoniam parasceve erat) ut non remanerent in cruce corpora sabbato (erat enim magnus dies ille sabbati), rogaverunt Pilatum ut frangerentur eorum crura, et tollerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 32, 'Venerunt ergo milites: et primi quidem fregerunt crura, et alterius, qui crucifixus est cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 33, 'Ad Jesum autem cum venissent, ut viderunt eum jam mortuum, non fregerunt ejus crura,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 34, 'sed unus militum lancea latus ejus aperuit, et continuo exivit sanguis et aqua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 35, 'Et qui vidit, testimonium perhibuit: et verum est testimonium ejus. Et ille scit quia vera dicit: ut et vos credatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 36, 'Facta sunt enim hæc ut Scriptura impleretur: Os non comminuetis ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 37, 'Et iterum alia Scriptura dicit: Videbunt in quem transfixerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 38, 'Post hæc autem rogavit Pilatum Joseph ab Arimathæa (eo quod esset discipulus Jesu, occultus autem propter metum Judæorum), ut tolleret corpus Jesu. Et permisit Pilatus. Venit ergo, et tulit corpus Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 39, 'Venit autem et Nicodemus, qui venerat ad Jesum nocte primum, ferens mixturam myrrhæ et aloës, quasi libras centum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 40, 'Acceperunt ergo corpus Jesu, et ligaverunt illud linteis cum aromatibus, sicut mos est Judæis sepelire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 41, 'Erat autem in loco, ubi crucifixus est, hortus: et in horto monumentum novum, in quo nondum quisquam positus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 19, 42, 'Ibi ergo propter parasceven Judæorum, quia juxta erat monumentum, posuerunt Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 1, 'Una autem sabbati, Maria Magdalene venit mane, cum adhuc tenebræ essent, ad monumentum: et vidit lapidem sublatum a monumento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 2, 'Cucurrit ergo, et venit ad Simonem Petrum, et ad alium discipulum, quem amabat Jesus, et dicit illis: Tulerunt Dominum de monumento, et nescimus ubi posuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 3, 'Exiit ergo Petrus, et ille alius discipulus, et venerunt ad monumentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 4, 'Currebant autem duo simul, et ille alius discipulus præcucurrit citius Petro, et venit primus ad monumentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 5, 'Et cum se inclinasset, vidit posita linteamina: non tamen introivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 6, 'Venit ergo Simon Petrus sequens eum, et introivit in monumentum, et vidit linteamina posita,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 7, 'et sudarium, quod fuerat super caput ejus, non cum linteaminibus positum, sed separatim involutum in unum locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 8, 'Tunc ergo introivit et ille discipulus qui venerat primus ad monumentum: et vidit, et credidit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 9, 'nondum enim sciebant Scripturam, quia oportebat eum a mortuis resurgere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 10, 'Abierunt ergo iterum discipuli ad semetipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 11, 'Maria autem stabat ad monumentum foris, plorans. Dum ergo fleret, inclinavit se, et prospexit in monumentum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 12, 'et vidit duos angelos in albis sedentes, unum ad caput, et unum ad pedes, ubi positum fuerat corpus Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 13, 'Dicunt ei illi: Mulier, quid ploras? Dicit eis: Quia tulerunt Dominum meum: et nescio ubi posuerunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 14, 'Hæc cum dixisset, conversa est retrorsum, et vidit Jesum stantem: et non sciebat quia Jesus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 15, 'Dicit ei Jesus: Mulier, quid ploras? quem quæris? Illa existimans quia hortulanus esset, dicit ei: Domine, si tu sustulisti eum, dicito mihi ubi posuisti eum, et ego eum tollam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 16, 'Dicit ei Jesus: Maria. Conversa illa, dicit ei: Rabboni (quod dicitur Magister).');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 17, 'Dicit ei Jesus: Noli me tangere, nondum enim ascendi ad Patrem meum: vade autem ad fratres meos, et dic eis: Ascendo ad Patrem meum, et Patrem vestrum, Deum meum, et Deum vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 18, 'Venit Maria Magdalene annuntians discipulis: Quia vidi Dominum, et hæc dixit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 19, 'Cum ergo sero esset die illo, una sabbatorum, et fores essent clausæ, ubi erant discipuli congregati propter metum Judæorum: venit Jesus, et stetit in medio, et dixit eis: Pax vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 20, 'Et cum hoc dixisset, ostendit eis manus et latus. Gavisi sunt ergo discipuli, viso Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 21, 'Dixit ergo eis iterum: Pax vobis. Sicut misit me Pater, et ego mitto vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 22, 'Hæc cum dixisset, insufflavit, et dixit eis: Accipite Spiritum Sanctum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 23, 'quorum remiseritis peccata, remittuntur eis: et quorum retinueritis, retenta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 24, 'Thomas autem unus ex duodecim, qui dicitur Didymus, non erat cum eis quando venit Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 25, 'Dixerunt ergo ei alii discipuli: Vidimus Dominum. Ille autem dixit eis: Nisi videro in manibus ejus fixuram clavorum, et mittam digitum meum in locum clavorum, et mittam manum meam in latus ejus, non credam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 26, 'Et post dies octo, iterum erant discipuli ejus intus, et Thomas cum eis. Venit Jesus januis clausis, et stetit in medio, et dixit: Pax vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 27, 'Deinde dicit Thomæ: Infer digitum tuum huc, et vide manus meas, et affer manum tuam, et mitte in latus meum: et noli esse incredulus, sed fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 28, 'Respondit Thomas, et dixit ei: Dominus meus et Deus meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 29, 'Dixit ei Jesus: Quia vidisti me, Thoma, credidisti: beati qui non viderunt, et crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 30, 'Multa quidem et alia signa fecit Jesus in conspectu discipulorum suorum, quæ non sunt scripta in libro hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 20, 31, 'Hæc autem scripta sunt ut credatis, quia Jesus est Christus Filius Dei: et ut credentes, vitam habeatis in nomine ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 1, 'Postea manifestavit se iterum Jesus discipulis ad mare Tiberiadis. Manifestavit autem sic:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 2, 'erant simul Simon Petrus, et Thomas, qui dicitur Didymus, et Nathanaël, qui erat a Cana Galilææ, et filii Zebedæi, et alii ex discipulis ejus duo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 3, 'Dicit eis Simon Petrus: Vado piscari. Dicunt ei: Venimus et nos tecum. Et exierunt, et ascenderunt in navim: et illa nocte nihil prendiderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 4, 'Mane autem facto stetit Jesus in littore: non tamen cognoverunt discipuli quia Jesus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 5, 'Dixit ergo eis Jesus: Pueri, numquid pulmentarium habetis? Responderunt ei: Non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 6, 'Dicit eis: Mittite in dexteram navigii rete, et invenietis. Miserunt ergo: et jam non valebant illud trahere præ multitudine piscium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 7, 'Dixit ergo discipulus ille, quem diligebat Jesus, Petro: Dominus est. Simon Petrus cum audisset quia Dominus est, tunica succinxit se (erat enim nudus) et misit se in mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 8, 'Alii autem discipuli navigio venerunt (non enim longe erant a terra, sed quasi cubitis ducentis), trahentes rete piscium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 9, 'Ut ergo descenderunt in terram, viderunt prunas positas, et piscem superpositum, et panem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 10, 'Dicit eis Jesus: Afferte de piscibus, quos prendidistis nunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 11, 'Ascendit Simon Petrus et traxit rete in terram, plenum magnis piscibus centum quinquaginta tribus. Et cum tanti essent, non est scissum rete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 12, 'Dicit eis Jesus: Venite, prandete. Et nemo audebat discumbentium interrogare eum: Tu quis es? scientes, quia Dominus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 13, 'Et venit Jesus, et accipit panem, et dat eis, et piscem similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 14, 'Hoc jam tertio manifestatus est Jesus discipulis suis cum resurrexisset a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 15, 'Cum ergo prandissent, dicit Simoni Petro Jesus: Simon Joannis, diligis me plus his? Dicit ei: Etiam Domine, tu scis quia amo te. Dicit ei: Pasce agnos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 16, 'Dicit ei iterum: Simon Joannis, diligis me? Ait illi: Etiam Domine, tu scis quia amo te. Dicit ei: Pasce agnos meos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 17, 'Dicit ei tertio: Simon Joannis, amas me? Contristatus est Petrus, quia dixit ei tertio: Amas me? et dixit ei: Domine, tu omnia nosti, tu scis quia amo te. Dixit ei: Pasce oves meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 18, 'Amen, amen dico tibi: cum esses junior, cingebas te, et ambulabas ubi volebas: cum autem senueris, extendes manus tuas, et alius te cinget, et ducet quo tu non vis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 19, 'Hoc autem dixit significans qua morte clarificaturus esset Deum. Et cum hoc dixisset, dicit ei: Sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 20, 'Conversus Petrus vidit illum discipulum, quem diligebat Jesus, sequentem, qui et recubuit in cœna super pectus ejus, et dixit: Domine, quis est qui tradet te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 21, 'Hunc ergo cum vidisset Petrus, dixit Jesu: Domine, hic autem quid?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 22, 'Dicit ei Jesus: Sic eum volo manere donec veniam, quid ad te? tu me sequere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 23, 'Exiit ergo sermo iste inter fratres quia discipulus ille non moritur. Et non dixit ei Jesus: Non moritur, sed: Sic eum volo manere donec veniam, quid ad te?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 24, 'Hic est discipulus ille qui testimonium perhibet de his, et scripsit hæc: et scimus quia verum est testimonium ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 21, 25, 'Sunt autem et alia multa quæ fecit Jesus: quæ si scribantur per singula, nec ipsum arbitror mundum capere posse eos, qui scribendi sunt, libros.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Primum quidem sermonem feci de omnibus, o Theophile, quæ cœpit Jesus facere et docere');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'usque in diem qua præcipiens Apostolis per Spiritum Sanctum, quos elegit, assumptus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'quibus et præbuit seipsum vivum post passionem suam in multis argumentis, per dies quadraginta apparens eis, et loquens de regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Et convescens, præcepit eis ab Jerosolymis ne discederent, sed exspectarent promissionem Patris, quam audistis (inquit) per os meum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'quia Joannes quidem baptizavit aqua, vos autem baptizabimini Spiritu Sancto non post multos hos dies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Igitur qui convenerant, interrogabant eum, dicentes: Domine, si in tempore hoc restitues regnum Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Dixit autem eis: Non est vestrum nosse tempora vel momenta quæ Pater posuit in sua potestate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'sed accipietis virtutem supervenientis Spiritus Sancti in vos, et eritis mihi testes in Jerusalem, et in omni Judæa, et Samaria, et usque ad ultimum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Et cum hæc dixisset, videntibus illis, elevatus est: et nubes suscepit eum ab oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Cumque intuerentur in cælum euntem illum, ecce duo viri astiterunt juxta illos in vestibus albis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'qui et dixerunt: Viri Galilæi, quid statis aspicientes in cælum? Hic Jesus, qui assumptus est a vobis in cælum, sic veniet quemadmodum vidistis eum euntem in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Tunc reversi sunt Jerosolymam a monte qui vocatur Oliveti, qui est juxta Jerusalem, sabbati habens iter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Et cum introissent in cœnaculum, ascenderunt ubi manebant Petrus, et Joannes, Jacobus, et Andreas, Philippus, et Thomas, Bartholomæus, et Matthæus, Jacobus Alphæi, et Simon Zelotes, et Judas Jacobi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Hi omnes erant perseverantes unanimiter in oratione cum mulieribus, et Maria matre Jesu, et fratribus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'In diebus illis, exsurgens Petrus in medio fratrum, dixit (erat autem turba hominum simul, fere centum viginti):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Viri fratres, oportet impleri Scripturam quam prædixit Spiritus Sanctus per os David de Juda, qui fuit dux eorum qui comprehenderunt Jesum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'qui connumeratus erat in nobis, et sortitus est sortem ministerii hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Et hic quidem possedit agrum de mercede iniquitatis, et suspensus crepuit medius: et diffusa sunt omnia viscera ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Et notum factum est omnibus habitantibus Jerusalem, ita ut appellaretur ager ille, lingua eorum, Haceldama, hoc est, ager sanguinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Scriptum est enim in libro Psalmorum: Fiat commoratio eorum deserta, et non sit qui inhabitet in ea: et episcopatum ejus accipiat alter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Oportet ergo ex his viris qui nobiscum sunt congregati in omni tempore quo intravit et exivit inter nos Dominus Jesus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'incipiens a baptismate Joannis usque in diem qua assumptus est a nobis, testem resurrectionis ejus nobiscum fieri unum ex istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Et statuerunt duos, Joseph, qui vocabatur Barsabas, qui cognominatus est Justus, et Mathiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Et orantes dixerunt: Tu Domine, qui corda nosti omnium, ostende quem elegeris ex his duobus unum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'accipere locum ministerii hujus et apostolatus, de quo prævaricatus est Judas ut abiret in locum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Et dederunt sortes eis, et cecidit sors super Mathiam: et annumeratus est cum undecim Apostolis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Et cum complerentur dies Pentecostes, erant omnes pariter in eodem loco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'et factus est repente de cælo sonus, tamquam advenientis spiritus vehementis, et replevit totam domum ubi erant sedentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Et apparuerunt illis dispertitæ linguæ tamquam ignis, seditque supra singulos eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'et repleti sunt omnes Spiritu Sancto, et cœperunt loqui variis linguis, prout Spiritus Sanctus dabat eloqui illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Erant autem in Jerusalem habitantes Judæi, viri religiosi ex omni natione quæ sub cælo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Facta autem hac voce, convenit multitudo, et mente confusa est, quoniam audiebat unusquisque lingua sua illos loquentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Stupebant autem omnes, et mirabantur, dicentes: Nonne ecce omnes isti qui loquuntur, Galilæi sunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'et quomodo nos audivimus unusquisque linguam nostram in qua nati sumus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Parthi, et Medi, et \'lamitæ, et qui habitant Mespotamiam, Judæam, et Cappadociam, Pontum, et Asiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Phrygiam, et Pamphyliam, \'gyptum, et partes Libyæ quæ est circa Cyrenen: et advenæ Romani,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'Judæi quoque, et Proselyti, Cretes, et Arabes: audivimus eos loquentes nostris linguis magnalia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Stupebant autem omnes, et mirabantur ad invicem, dicentes: Quidnam vult hoc esse?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Alii autem irridentes dicebant: Quia musto pleni sunt isti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Stans autem Petrus cum undecim, levavit vocem suam, et locutus est eis: Viri Judæi, et qui habitatis Jerusalem universi, hoc vobis notum sit, et auribus percipite verba mea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Non enim, sicut vos æstimatis, hi ebrii sunt, cum sit hora diei tertia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'sed hoc est quod dictum est per prophetam Joël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Et erit in novissimis diebus, dicit Dominus, effundam de Spiritu meo super omnem carnem: et prophetabunt filii vestri et filiæ vestræ, et juvenes vestri visiones videbunt, et seniores vestri somnia somniabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Et quidem super servos meos, et super ancillas meas, in diebus illis effundam de Spiritu meo, et prophetabunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'et dabo prodigia in cælo sursum, et signa in terra deorsum, sanguinem, et ignem, et vaporem fumi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'sol convertetur in tenebras, et luna in sanguinem, antequam veniat dies Domini magnus et manifestus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Et erit: omnis quicumque invocaverit nomen Domini, salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Viri Israëlitæ, audite verba hæc: Jesum Nazarenum, virum approbatum a Deo in vobis, virtutibus, et prodigiis, et signis, quæ fecit Deus per illum in medio vestri, sicut et vos scitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'hunc, definito consilio et præscientia Dei traditum, per manus iniquorum affligentes interemistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 24, 'quem Deus suscitavit, solutis doloribus inferni, juxta quod impossibile erat teneri illum ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 25, 'David enim dicit in eum: Providebam Dominum in conspectu meo semper: quoniam a dextris est mihi, ne commovear:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 26, 'propter hoc lætatum est cor meum, et exsultavit lingua mea, insuper et caro mea requiescet in spe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 27, 'quoniam non derelinques animam meam in inferno, nec dabis sanctum tuum videre corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 28, 'Notas mihi fecisti vias vitæ: et replebis me jucunditate cum facie tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 29, 'Viri fratres, liceat audenter dicere ad vos de patriarcha David, quoniam defunctus est, et sepultus: et sepulchrum ejus est apud nos usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 30, 'Propheta igitur cum esset, et sciret quia jurejurando jurasset illi Deus de fructu lumbi ejus sedere super sedem ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 31, 'providens locutus est de resurrectione Christi, quia neque derelictus est in inferno, neque caro ejus vidit corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 32, 'Hunc Jesum resuscitavit Deus, cujus omnes nos testes sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 33, 'Dextera igitur Dei exaltatus, et promissione Spiritus Sancti accepta a Patre, effudit hunc, quem vos videtis et auditis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 34, 'Non enim David ascendit in cælum: dixit autem ipse: Dixit Dominus Domino meo: Sede a dextris meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 35, 'donec ponam inimicos tuos scabellum pedum tuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 36, 'Certissime sciat ergo omnis domus Israël, quia et Dominum eum et Christum fecit Deus hunc Jesum, quem vos crucifixistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 37, 'His autem auditis, compuncti sunt corde, et dixerunt ad Petrum et ad reliquos Apostolos: Quid faciemus, viri fratres?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 38, 'Petrus vero ad illos: Pœnitentiam, inquit, agite, et baptizetur unusquisque vestrum in nomine Jesu Christi in remissionem peccatorum vestrorum: et accipietis donum Spiritus Sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 39, 'Vobis enim est repromissio, et filiis vestris, et omnibus qui longe sunt, quoscumque advocaverit Dominus Deus noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 40, 'Aliis etiam verbis plurimis testificatus est, et exhortabatur eos, dicens: Salvamini a generatione ista prava.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 41, 'Qui ergo receperunt sermonem ejus, baptizati sunt: et appositæ sunt in die illa animæ circiter tria millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 42, 'Erant autem perseverantes in doctrina Apostolorum, et communicatione fractionis panis, et orationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 43, 'Fiebat autem omni animæ timor: multa quoque prodigia et signa per Apostolos in Jerusalem fiebant, et metus erat magnus in universis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 44, 'Omnes etiam qui credebant, erant pariter, et habebant omnia communia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 45, 'Possessiones et substantias vendebant, et dividebant illa omnibus, prout cuique opus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 46, 'Quotidie quoque perdurantes unanimiter in templo, et frangentes circa domos panem, sumebant cibum cum exsultatione et simplicitate cordis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 47, 'collaudantes Deum et habentes gratiam ad omnem plebem. Dominus autem augebat qui salvi fierent quotidie in idipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Petrus autem et Joannes ascendebant in templum ad horam orationis nonam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Et quidam vir, qui erat claudus ex utero matris suæ, bajulabatur: quem ponebant quotidie ad portam templi, quæ dicitur Speciosa, ut peteret eleemosynam ab introëuntibus in templum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Is cum vidisset Petrum et Joannem incipientes introire in templum, rogabat ut eleemosynam acciperet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Intuens autem in eum Petrus cum Joanne, dixit: Respice in nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'At ille intendebat in eos, sperans se aliquid accepturum ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Petrus autem dixit: Argentum et aurum non est mihi: quod autem habeo, hoc tibi do: in nomine Jesu Christi Nazareni surge, et ambula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'Et apprehensa manu ejus dextera, allevavit eum, et protinus consolidatæ sunt bases ejus et plantæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Et exiliens stetit, et ambulabat: et intravit cum illis in templum ambulans, et exiliens, et laudans Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Et vidit omnis populus eum ambulantem et laudantem Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Cognoscebant autem illum, quod ipse erat qui ad eleemosynam sedebat ad Speciosam portam templi: et impleti sunt stupore et extasi in eo quod contigerat illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Cum teneret autem Petrum et Joannem, cucurrit omnis populus ad eos ad porticum quæ appellatur Salomonis, stupentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Videns autem Petrus, respondit ad populum: Viri Israëlitæ, quid miramini in hoc, aut nos quid intuemini, quasi nostra virtute aut potestate fecerimus hunc ambulare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Deus Abraham, et Deus Isaac, et Deus Jacob, Deus patrum nostrorum glorificavit filium suum Jesum, quem vos quidem tradidistis, et negastis ante faciem Pilati, judicante illo dimitti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Vos autem sanctum et justum negastis, et petistis virum homicidam donari vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'auctorem vero vitæ interfecistis, quem Deus suscitavit a mortuis, cujus nos testes sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Et in fide nominis ejus, hunc quem vos vidistis et nostis, confirmavit nomen ejus: et fides, quæ per eum est, dedit integram sanitatem istam in conspectu omnium vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Et nunc, fratres, scio quia per ignorantiam fecistis, sicut et principes vestri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Deus autem, quæ prænuntiavit per os omnium prophetarum, pati Christum suum, sic implevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Pœnitemini igitur et convertimini, ut deleantur peccata vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'ut cum venerint tempora refrigerii a conspectu Domini, et miserit eum qui prædicatus est vobis, Jesum Christum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'quem oportet quidem cælum suscipere usque in tempora restitutionis omnium quæ locutus est Deus per os sanctorum suorum a sæculo prophetarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Moyses quidem dixit: Quoniam prophetam suscitabit vobis Dominus Deus vester de fratribus vestris, tamquam me: ipsum audietis juxta omnia quæcumque locutus fuerit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Erit autem: omnis anima quæ non audierit prophetam illum, exterminabitur de plebe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Et omnes prophetæ, a Samuel et deinceps, qui locuti sunt, annuntiaverunt dies istos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Vos estis filii prophetarum, et testamenti quod disposuit Deus ad patres nostros, dicens ad Abraham: Et in semine tuo benedicentur omnes familiæ terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 26, 'Vobis primum Deus suscitans filium suum, misit eum benedicentem vobis: ut convertat se unusquisque a nequitia sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Loquentibus autem illis ad populum, supervenerunt sacerdotes, et magistratus templi, et sadducæi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'dolentes quod docerent populum, et annuntiarent in Jesu resurrectionem ex mortuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'et injecerunt in eos manus, et posuerunt eos in custodiam in crastinum: erat enim jam vespera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Multi autem eorum qui audierant verbum, crediderunt: et factus est numerus virorum quinque millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Factum est autem in crastinum, ut congregarentur principes eorum, et seniores, et scribæ, in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'et Annas princeps sacerdotum, et Caiphas, et Joannes, et Alexander, et quotquot erant de genere sacerdotali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Et statuentes eos in medio, interrogabant: In qua virtute, aut in quo nomine fecistis hoc vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Tunc repletus Spiritu Sancto Petrus, dixit ad eos: Principes populi, et seniores, audite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'si nos hodie dijudicamur in benefacto hominis infirmi, in quo iste salvus factus est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'notum sit omnibus vobis, et omni plebi Israël, quia in nomine Domini nostri Jesu Christi Nazareni, quem vos crucifixistis, quem Deus suscitavit a mortuis, in hoc iste astat coram vobis sanus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Hic est lapis qui reprobatus est a vobis ædificantibus, qui factus est in caput anguli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'et non est in alio aliquo salus. Nec enim aliud nomen est sub cælo datum hominibus, in quo oporteat nos salvos fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Videntes autem Petri constantiam, et Joannis, comperto quod homines essent sine litteris, et idiotæ, admirabantur, et cognoscebant eos quoniam cum Jesu fuerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'hominem quoque videntes stantem cum eis, qui curatus fuerat, nihil poterant contradicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Jusserunt autem eos foras extra concilium secedere: et conferebant ad invicem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'dicentes: Quid faciemus hominibus istis? quoniam quidem notum signum factum est per eos omnibus habitantibus Jerusalem: manifestum est, et non possumus negare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Sed ne amplius divulgetur in populum, comminemur eis ne ultra loquantur in nomine hoc ulli hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Et vocantes eos, denuntiaverunt ne omnino loquerentur neque docerent in nomine Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 19, 'Petrus vero et Joannes respondentes, dixerunt ad eos: Si justum est in conspectu Dei vos potius audire quam Deum, judicate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 20, 'Non enim possumus quæ vidimus et audivimus non loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 21, 'At illi comminantes dimiserunt eos, non invenientes quomodo punirent eos propter populum: quia omnes clarificabant id quod factum fuerat in eo quod acciderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 22, 'Annorum enim erat amplius quadraginta homo, in quo factum fuerat signum istud sanitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 23, 'Dimissi autem venerunt ad suos, et annuntiaverunt eis quanta ad eos principes sacerdotum et seniores dixissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 24, 'Qui cum audissent, unanimiter levaverunt vocem ad Deum, et dixerunt: Domine, tu es qui fecisti cælum et terram, mare et omnia quæ in eis sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 25, 'qui Spiritu Sancto per os patris nostri David pueri tui dixisti: Quare fremuerunt gentes, et populi meditati sunt inania?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 26, 'Astiterunt reges terræ, et principes convenerunt in unum adversus Dominum, et adversus Christum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 27, 'Convenerunt enim vere in civitate ista adversus sanctum puerum tuum Jesum, quem unxisti, Herodes et Pontius Pilatus, cum gentibus et populis Israël,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 28, 'facere quæ manus tua et consilium tuum decreverunt fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 29, 'Et nunc, Domine, respice in minas eorum, et da servis tuis cum omni fiducia loqui verbum tuum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 30, 'in eo quod manum tuam extendas ad sanitates, et signa, et prodigia fieri per nomen sancti filii tui Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 31, 'Et cum orassent, motus est locus in quo erant congregati: et repleti sunt omnes Spiritu Sancto, et loquebantur verbum Dei cum fiducia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 32, 'Multitudinis autem credentium erat cor unum et anima una: nec quisquam eorum quæ possidebat, aliquid suum esse dicebat, sed erant illis omnia communia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 33, 'Et virtute magna reddebant Apostoli testimonium resurrectionis Jesu Christi Domini nostri: et gratia magna erat in omnibus illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 34, 'Neque enim quisquam egens erat inter illos. Quotquot enim possessores agrorum aut domorum erant, vendentes afferebant pretia eorum quæ vendebant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 35, 'et ponebant ante pedes Apostolorum. Dividebatur autem singulis prout cuique opus erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 36, 'Joseph autem, qui cognominatus est Barnabas ab Apostolis (quod est interpretatum, Filius consolationis), Levites, Cyprius genere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 37, 'cum haberet agrum, vendidit eum, et attulit pretium, et posuit ante pedes Apostolorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 1, 'Vir autem quidam nomine Ananias, cum Saphira uxore suo vendidit agrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 2, 'et fraudavit de pretio agri, conscia uxore sua: et afferens partem quamdam, ad pedes Apostolorum posuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 3, 'Dixit autem Petrus: Anania, cur tentavit Satanas cor tuum, mentiri te Spiritui Sancto, et fraudare de pretio agri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 4, 'nonne manens tibi manebat, et venundatum in tua erat potestate? quare posuisti in corde tuo hanc rem? non es mentitus hominibus, sed Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 5, 'Audiens autem Ananias hæc verba, cecidit, et expiravit. Et factus est timor magnus super omnes qui audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 6, 'Surgentes autem juvenes amoverunt eum, et efferentes sepelierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 7, 'Factum est autem quasi horarum trium spatium, et uxor ipsius, nesciens quod factum fuerat, introivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 8, 'Dixit autem ei Petrus: Dic mihi mulier, si tanti agrum vendidistis? At illa dixit: Etiam tanti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 9, 'Petrus autem ad eam: Quid utique convenit vobis tentare Spiritum Domini? Ecce pedes eorum qui sepelierunt virum tuum ad ostium, et efferent te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 10, 'Confestim cecidit ante pedes ejus, et expiravit. Intrantes autem juvenes invenerunt illam mortuam: et extulerunt, et sepelierunt ad virum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 11, 'Et factus est timor magnus in universa ecclesia, et in omnes qui audierunt hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 12, 'Per manus autem Apostolorum fiebant signa et prodigia multa in plebe. Et erant unanimiter omnes in porticu Salomonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 13, 'Ceterorum autem nemo audebat se conjungere illis: sed magnificabat eos populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 14, 'Magis autem augebatur credentium in Domino multitudo virorum ac mulierum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 15, 'ita ut in plateas ejicerent infirmos, et ponerent in lectulis et grabatis, ut, veniente Petro, saltem umbra illius obumbraret quemquam illorum, et liberarentur ab infirmitatibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 16, 'Concurrebat autem et multitudo vicinarum civitatum Jerusalem, afferentes ægros, et vexatos a spiritibus immundis: qui curabantur omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 17, 'Exsurgens autem princeps sacerdotum, et omnes qui cum illo erant (quæ est hæresis sadducæorum), repleti sunt zelo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 18, 'et injecerunt manus in Apostolos, et posuerunt eos in custodia publica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 19, 'Angelus autem Domini per noctem aperiens januas carceris, et educens eos, dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 20, 'Ite, et stantes loquimini in templo plebi omnia verba vitæ hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 21, 'Qui cum audissent, intraverunt diluculo in templum, et docebant. Adveniens autem princeps sacerdotum, et qui cum eo erant, convocaverunt concilium, et omnes seniores filiorum Israël: et miserunt ad carcerem ut adducerentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 22, 'Cum autem venissent ministri, et aperto carcere non invenissent illos, reversi nuntiaverunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 23, 'dicentes: Carcerem quidem invenimus clausum cum omni diligentia, et custodes stantes ante januas: aperientes autem neminem intus invenimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 24, 'Ut autem audierunt hos sermones magistratus templi et principes sacerdotum, ambigebant de illis quidnam fieret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 25, 'Adveniens autem quidam, nuntiavit eis: Quia ecce viri quos posuistis in carcerem, sunt in templo, stantes et docentes populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 26, 'Tunc abiit magistratus cum ministris, et adduxit illos sine vi: timebant enim populum ne lapidarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 27, 'Et cum adduxissent illos, statuerunt in concilio: et interrogavit eos princeps sacerdotum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 28, 'dicens: Præcipiendo præcepimus vobis ne doceretis in nomine isto, et ecce replestis Jerusalem doctrina vestra: et vultis inducere super nos sanguinem hominis istius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 29, 'Respondens autem Petrus et Apostoli, dixerunt: Obedire oportet Deo magis quam hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 30, 'Deus patrum nostrorum suscitavit Jesum, quem vos interemistis, suspendentes in ligno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 31, 'Hunc principem et salvatorem Deus exaltavit dextera sua ad dandam pœnitentiam Israëli, et remissionem peccatorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 32, 'et nos sumus testes horum verborum, et Spiritus Sanctus, quem dedit Deus omnibus obedientibus sibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 33, 'Hæc cum audissent, dissecabantur, et cogitabant interficere illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 34, 'Surgens autem quidam in concilio pharisæus, nomine Gamaliel, legis doctor, honorabilis universæ plebi, jussit foras ad breve homines fieri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 35, 'dixitque ad illos: Viri Israëlitæ, attendite vobis super hominibus istis quid acturi sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 36, 'Ante hos enim dies extitit Theodas, dicens se esse aliquem, cui consensit numerus virorum circiter quadringentorum: qui occisus est, et omnes qui credebant ei, dissipati sunt, et redacti ad nihilum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 37, 'Post hunc extitit Judas Galilæus in diebus professionis, et avertit populum post se: et ipse periit, et omnes quotquot consenserunt ei, dispersi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 38, 'Et nunc itaque dico vobis, discedite ab hominibus istis, et sinite illos: quoniam si est ex hominibus consilium hoc aut opus, dissolvetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 39, 'si vero ex Deo est, non poteritis dissolvere illud, ne forte et Deo repugnare inveniamini. Consenserunt autem illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 40, 'Et convocantes Apostolos, cæsis denuntiaverunt ne omnino loquerentur in nomine Jesu, et dimiserunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 41, 'Et illi quidem ibant gaudentes a conspectu concilii, quoniam digni habiti sunt pro nomine Jesu contumeliam pati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 5, 42, 'Omni autem die non cessabant in templo et circa domos, docentes et evangelizantes Christum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 1, 'In diebus illis, crescente numero discipulorum, factum est murmur Græcorum adversus Hebræos, eo quod despicerentur in ministerio quotidiano viduæ eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 2, 'Convocantes autem duodecim multitudinem discipulorum, dixerunt: Non est æquum nos derelinquere verbum Dei, et ministrare mensis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 3, 'Considerate ergo, fratres, viros ex vobis boni testimonii septem, plenos Spiritu Sancto et sapientia, quos constituamus super hoc opus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 4, 'Nos vero orationi et ministerio verbi instantes erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 5, 'Et placuit sermo coram omni multitudine. Et elegerunt Stephanum, virum plenum fide et Spiritu Sancto, et Philippum, et Prochorum, et Nicanorem, et Timonem, et Parmenam, et Nicolaum advenam Antiochenum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 6, 'Hos statuerunt ante conspectum Apostolorum: et orantes imposuerunt eis manus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 7, 'Et verbum Domini crescebat, et multiplicabatur numerus discipulorum in Jerusalem valde: multa etiam turba sacerdotum obediebat fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 8, 'Stephanus autem plenus gratia et fortitudine, faciebat prodigia et signa magna in populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 9, 'Surrexerunt autem quidam de synagoga quæ appellatur Libertinorum, et Cyrenensium, et Alexandrinorum, et eorum qui erant a Cilicia, et Asia, disputantes cum Stephano:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 10, 'et non poterant resistere sapientiæ, et Spiritui qui loquebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 11, 'Tunc summiserunt viros, qui dicerent se audivisse eum dicentem verba blasphemiæ in Moysen et in Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 12, 'Commoverunt itaque plebem, et seniores, et scribas: et concurrentes rapuerunt eum, et adduxerunt in concilium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 13, 'et statuerunt falsos testes, qui dicerent: Homo iste non cessat loqui verba adversus locum sanctum, et legem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 14, 'audivimus enim eum dicentem quoniam Jesus Nazarenus hic destruet locum istum, et mutabit traditiones quas tradidit nobis Moyses.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 6, 15, 'Et intuentes eum omnes qui sedebant in concilio, viderunt faciem ejus tamquam faciem angeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 1, 'Dixit autem princeps sacerdotum: Si hæc ita se habent?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 2, 'Qui ait: Viri fratres et patres, audite: Deus gloriæ apparuit patri nostro Abrahæ cum esset in Mesopotamia, priusquam moraretur in Charan,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 3, 'et dixit ad illum: Exi de terra tua, et de cognatione tua, et veni in terram quam monstravero tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 4, 'Tunc exiit de terra Chaldæorum, et habitavit in Charan. Et inde, postquam mortuus est pater ejus, transtulit illum in terram istam, in qua nunc vos habitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 5, 'Et non dedit illi hæreditatem in ea, nec passum pedis: sed repromisit dare illi eam in possessionem, et semini ejus post ipsum, cum non haberet filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 6, 'Locutus est autem ei Deus: Quia erit semen ejus accola in terra aliena, et servituti eos subjicient, et male tractabunt eos annis quadringentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 7, 'et gentem cui servierint, judicabo ego, dixit Dominus: et post hæc exibunt, et servient mihi in loco isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 8, 'Et dedit illi testamentum circumcisionis: et sic genuit Isaac, et circumcidit eum die octavo: et Isaac, Jacob: et Jacob, duodecim patriarchas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 9, 'Et patriarchæ æmulantes, Joseph vendiderunt in \'gyptum: et erat Deus cum eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 10, 'et eripuit eum ex omnibus tribulationibus ejus, et dedit ei gratiam et sapientiam in conspectu pharaonis regis \'gypti: et constituit eum præpositum super \'gyptum, et super omnem domum suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 11, 'Venit autem fames in universam \'gyptum et Chanaan, et tribulatio magna: et non inveniebant cibos patres nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 12, 'Cum audisset autem Jacob esse frumentum in \'gypto, misit patres nostros primum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 13, 'et in secundo cognitus est Joseph a fratribus suis, et manifestatum est Pharaoni genus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 14, 'Mittens autem Joseph, accersivit Jacob patrem suum et omnem cognationem suam, in animabus septuaginta quinque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 15, 'Et descendit Jacob in \'gyptum: et defunctus est ipse, et patres nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 16, 'Et translati sunt in Sichem, et positi sunt in sepulchro, quod emit Abraham pretio argenti a filiis Hemor filii Sichem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 17, 'Cum autem appropinquaret tempus promissionis quam confessus erat Deus Abrahæ, crevit populus, et multiplicatus est in \'gypto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 18, 'quoadusque surrexit alius rex in \'gypto, qui non sciebat Joseph.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 19, 'Hic circumveniens genus nostrum, afflixit patres nostros ut exponerent infantes suos, ne vivificarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 20, 'Eodem tempore natus est Moyses, et fuit gratus Deo: qui nutritus est tribus mensibus in domo patris sui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 21, 'Exposito autem illo, sustulit eum filia Pharaonis, et nutrivit eum sibi in filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 22, 'Et eruditus est Moyses omni sapientia \'gyptiorum, et erat potens in verbis et in operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 23, 'Cum autem impleretur ei quadraginta annorum tempus, ascendit in cor ejus ut visitaret fratres suos filios Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 24, 'Et cum vidisset quemdam injuriam patientem, vindicavit illum, et fecit ultionem ei qui injuriam sustinebat, percusso \'gyptio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 25, 'Existimabat autem intelligere fratres, quoniam Deus per manum ipsius daret salutem illis: at illi non intellexerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 26, 'Sequenti vero die apparuit illis litigantibus: et reconciliabat eos in pace, dicens: Viri, fratres estis: ut quid nocetis alterutrum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 27, 'Qui autem injuriam faciebat proximo, repulit eum, dicens: Quis te constituit principem et judicem super nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 28, 'Numquid interficere me tu vis, quemadmodum interfecisti heri \'gyptium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 29, 'Fugit autem Moyses in verbo isto: et factus est advena in terra Madian, ubi generavit filios duos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 30, 'Et expletis annis quadraginta, apparuit illi in deserto montis Sina angelus in igne flammæ rubi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 31, 'Moyses autem videns, admiratus est visum. Et accedente illo ut consideraret, facta est ad eum vox Domini, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 32, 'Ego sum Deus patrum tuorum, Deus Abraham, Deus Isaac, et Deus Jacob. Tremefactus autem Moyses, non audebat considerare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 33, 'Dixit autem illi Dominus: Solve calceamentum pedum tuorum: locus enim in quo stas, terra sancta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 34, 'Videns vidi afflictionem populi mei qui est in \'gypto, et gemitum eorum audivi, et descendi liberare eos. Et nunc veni, et mittam te in \'gyptum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 35, 'Hunc Moysen, quem negaverunt, dicentes: Quis te constituit principem et judicem? hunc Deus principem et redemptorem misit, cum manu angeli qui apparuit illi in rubo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 36, 'Hic eduxit illos faciens prodigia et signa in terra \'gypti, et in rubro mari, et in deserto annis quadraginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 37, 'Hic est Moyses, qui dixit filiis Israël: Prophetam suscitabit vobis Deus de fratribus vestris, tamquam me: ipsum audietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 38, 'Hic est qui fuit in ecclesia in solitudine cum angelo, qui loquebatur ei in monte Sina, et cum patribus nostris: qui accepit verba vitæ dare nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 39, 'Cui noluerunt obedire patres nostri: sed repulerunt, et aversi sunt cordibus suis in \'gyptum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 40, 'dicentes ad Aaron: Fac nobis deos qui præcedant nos: Moyses enim hic, qui eduxit nos de terra \'gypti, nescimus quid factum sit ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 41, 'Et vitulum fecerunt in diebus illis, et obtulerunt hostiam simulacro, et lætabantur in operibus manuum suarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 42, 'Convertit autem Deus, et tradidit eos servire militiæ cæli, sicut scriptum est in libro prophetarum: Numquid victimas et hostias obtulistis mihi annis quadraginta in deserto, domus Israël?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 43, 'Et suscepistis tabernaculum Moloch, et sidus dei vestri Rempham, figuras quas fecistis adorare eas: et transferam vos trans Babylonem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 44, 'Tabernaculum testimonii fuit cum patribus nostris in deserto, sicut disposuit illis Deus loquens ad Moysen, ut faceret illud secundum formam quam viderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 45, 'Quod et induxerunt, suscipientes patres nostri cum Jesu in possessionem gentium quas expulit Deus a facie patrum nostrorum, usque in diebus David,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 46, 'qui invenit gratiam ante Deum, et petiit ut inveniret tabernaculum Deo Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 47, 'Salomon autem ædificavit illi domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 48, 'Sed non Excelsus in manufactis habitat, sicut propheta dicit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 49, 'Cælum mihi sedes est: terra autem scabellum pedum meorum. Quam domum ædificabitis mihi? dicit Dominus: aut quis locus requietionis meæ est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 50, 'Nonne manus mea fecit hæc omnia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 51, 'Dura cervice, et incircumcisis cordibus et auribus, vos semper Spiritui Sancto resistitis: sicut patres vestri, ita et vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 52, 'Quem prophetarum non sunt persecuti patres vestri? et occiderunt eos qui prænuntiabant de adventu Justi, cujus vos nunc proditores et homicidæ fuistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 53, 'qui accepistis legem in dispositione angelorum, et non custodistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 54, 'Audientes autem hæc, dissecabantur cordibus suis, et stridebant dentibus in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 55, 'Cum autem esset plenus Spiritu Sancto, intendens in cælum, vidit gloriam Dei, et Jesum stantem a dextris Dei. Et ait: Ecce video cælos apertos, et Filium hominis stantem a dextris Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 56, 'Exclamantes autem voce magna continuerunt aures suas, et impetum fecerunt unanimiter in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 57, 'Et ejicientes eum extra civitatem, lapidabant: et testes deposuerunt vestimenta sua secus pedes adolescentis qui vocabatur Saulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 58, 'Et lapidabant Stephanum invocantem, et dicentem: Domine Jesu, suscipe spiritum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 7, 59, 'Positis autem genibus, clamavit voce magna, dicens: Domine, ne statuas illis hoc peccatum. Et cum hoc dixisset, obdormivit in Domino. Saulus autem erat consentiens neci ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 1, 'Facta est autem in illa die persecutio magna in ecclesia quæ erat Jerosolymis, et omnes dispersi sunt per regiones Judææ et Samariæ præter Apostolos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 2, 'Curaverunt autem Stephanum viri timorati, et fecerunt planctum magnum super eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 3, 'Saulus autem devastabat ecclesiam per domos intrans, et trahens viros ac mulieres, tradebat in custodiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 4, 'Igitur qui dispersi erant pertransibant, evangelizantes verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 5, 'Philippus autem descendens in civitatem Samariæ, prædicabat illis Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 6, 'Intendebant autem turbæ his quæ a Philippo dicebantur, unanimiter audientes, et videntes signa quæ faciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 7, 'Multi enim eorum qui habebant spiritus immundos, clamantes voce magna exibant. Multi autem paralytici et claudi curati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 8, 'Factum est ergo gaudium magnum in illa civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 9, 'Vir autem quidam nomine Simon, qui ante fuerat in civitate magus, seducens gentem Samariæ, dicens se esse aliquem magnum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 10, 'cui auscultabant omnes a minimo usque ad maximum, dicentes: Hic est virtus Dei, quæ vocatur magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 11, 'Attendebant autem eum: propter quod multo tempore magiis suis dementasset eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 12, 'Cum vero credidissent Philippo evangelizanti de regno Dei, in nomine Jesu Christi baptizabantur viri ac mulieres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 13, 'Tunc Simon et ipse credidit: et cum baptizatus esset, adhærebat Philippo. Videns etiam signa et virtutes maximas fieri, stupens admirabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 14, 'Cum autem audissent Apostoli qui erant Jerosolymis, quod recepisset Samaria verbum Dei, miserunt ad eos Petrum et Joannem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 15, 'Qui cum venissent, oraverunt pro ipsis ut acciperent Spiritum Sanctum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 16, 'nondum enim in quemquam illorum venerat, sed baptizati tantum erant in nomine Domini Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 17, 'Tunc imponebant manus super illos, et accipiebant Spiritum Sanctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 18, 'Cum vidisset autem Simon quia per impositionem manus Apostolorum daretur Spiritus Sanctus, obtulit eis pecuniam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 19, 'dicens: Date et mihi hanc potestatem, ut cuicumque imposuero manus, accipiat Spiritum Sanctum. Petrus autem dixit ad eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 20, 'Pecunia tua tecum sit in perditionem: quoniam donum Dei existimasti pecunia possideri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 21, 'Non est tibi pars neque sors in sermone isto: cor enim tuum non est rectum coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 22, 'Pœnitentiam itaque age ab hac nequitia tua: et roga Deum, si forte remittatur tibi hæc cogitatio cordis tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 23, 'In felle enim amaritudinis, et obligatione iniquitatis, video te esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 24, 'Respondens autem Simon, dixit: Precamini vos pro me ad Dominum, ut nihil veniat super me horum quæ dixistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 25, 'Et illi quidem testificati, et locuti verbum Domini, redibant Jerosolymam, et multis regionibus Samaritanorum evangelizabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 26, 'Angelus autem Domini locutus est ad Philippum, dicens: Surge, et vade contra meridianum, ad viam quæ descendit ab Jerusalem in Gazam: hæc est deserta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 27, 'Et surgens abiit. Et ecce vir \'thiops, eunuchus, potens Candacis reginæ \'thiopum, qui erat super omnes gazas ejus, venerat adorare in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 28, 'et revertebatur sedens super currum suum, legensque Isaiam prophetam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 29, 'Dixit autem Spiritus Philippo: Accede, et adjunge te ad currum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 30, 'Accurrens autem Philippus, audivit eum legentem Isaiam prophetam, et dixit: Putasne intelligis quæ legis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 31, 'Qui ait: Et quomodo possum, si non aliquis ostenderit mihi? Rogavitque Philippum ut ascenderet, et sederet secum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 32, 'Locus autem Scripturæ quem legebat, erat hic: Tamquam ovis ad occisionem ductus est: et sicut agnus coram tondente se, sine voce, sic non aperuit os suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 33, 'In humilitate judicium ejus sublatum est. Generationem ejus quis enarrabit? quoniam tolletur de terra vita ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 34, 'Respondens autem eunuchus Philippo, dixit: Obsecro te, de quo propheta dicit hoc? de se, an de alio aliquo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 35, 'Aperiens autem Philippus os suum, et incipiens a Scriptura ista, evangelizavit illi Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 36, 'Et dum irent per viam, venerunt ad quamdam aquam: et ait eunuchus: Ecce aqua: quid prohibet me baptizari?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 37, 'Dixit autem Philippus: Si credis ex toto corde, licet. Et respondens ait: Credo Filium Dei esse Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 38, 'Et jussit stare currum: et descenderunt uterque in aquam, Philippus et eunuchus, et baptizavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 39, 'Cum autem ascendissent de aqua, Spiritus Domini rapuit Philippum, et amplius non vidit eum eunuchus. Ibat autem per viam suam gaudens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 8, 40, 'Philippus autem inventus est in Azoto, et pertransiens evangelizabat civitatibus cunctis, donec veniret Cæsaream.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 1, 'Saulus autem adhuc spirans minarum et cædis in discipulos Domini, accessit ad principem sacerdotum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 2, 'et petiit ab eo epistolas in Damascum ad synagogas: ut si quos invenisset hujus viæ viros ac mulieres, vinctos perduceret in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 3, 'Et cum iter faceret, contigit ut appropinquaret Damasco: et subito circumfulsit eum lux de cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 4, 'Et cadens in terram audivit vocem dicentem sibi: Saule, Saule, quid me persequeris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 5, 'Qui dixit: Quis es, domine? Et ille: Ego sum Jesus, quem tu persequeris: durum est tibi contra stimulum calcitrare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 6, 'Et tremens ac stupens dixit: Domine, quid me vis facere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 7, 'Et Dominus ad eum: Surge, et ingredere civitatem, et ibi dicetur tibi quid te oporteat facere. Viri autem illi qui comitabantur cum eo, stabant stupefacti, audientes quidem vocem, neminem autem videntes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 8, 'Surrexit autem Saulus de terra, apertisque oculis nihil videbat. Ad manus autem illum trahentes, introduxerunt Damascum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 9, 'Et erat ibi tribus diebus non videns, et non manducavit, neque bibit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 10, 'Erat autem quidam discipulus Damasci, nomine Ananias: et dixit ad illum in visu Dominus: Anania. At ille ait: Ecce ego, Domine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 11, 'Et Dominus ad eum: Surge, et vade in vicum qui vocatur Rectus: et quære in domo Judæ Saulum nomine Tarsensem: ecce enim orat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 12, '(Et vidit virum Ananiam nomine, introëuntem, et imponentem sibi manus ut visum recipiat.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 13, 'Respondit autem Ananias: Domine, audivi a multis de viro hoc, quanta mala fecerit sanctis tuis in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 14, 'et hic habet potestatem a principibus sacerdotum alligandi omnes qui invocant nomen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 15, 'Dixit autem ad eum Dominus: Vade, quoniam vas electionis est mihi iste, ut portet nomen meum coram gentibus, et regibus, et filiis Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 16, 'Ego enim ostendam illi quanta oporteat eum pro nomine meo pati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 17, 'Et abiit Ananias, et introivit in domum: et imponens ei manus, dixit: Saule frater, Dominus misit me Jesus, qui apparuit tibi in via qua veniebas, ut videas, et implearis Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 18, 'Et confestim ceciderunt ab oculis ejus tamquam squamæ, et visum recepit: et surgens baptizatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 19, 'Et cum accepisset cibum, confortatus est. Fuit autem cum discipulis qui erant Damasci per dies aliquot.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 20, 'Et continuo in synagogis prædicabat Jesum, quoniam hic est Filius Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 21, 'Stupebant autem omnes qui audiebant, et dicebant: Nonne hic est qui expugnabat in Jerusalem eos qui invocabant nomen istud: et huc ad hoc venit, ut vinctos illos duceret ad principes sacerdotum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 22, 'Saulus autem multo magis convalescebat, et confundebat Judæos qui habitabant Damasci, affirmans quoniam hic est Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 23, 'Cum autem implerentur dies multi, consilium fecerunt in unum Judæi ut eum interficerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 24, 'Notæ autem factæ sunt Saulo insidiæ eorum. Custodiebant autem et portas die ac nocte, ut eum interficerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 25, 'Accipientes autem eum discipuli nocte, per murum dimiserunt eum, submittentes in sporta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 26, 'Cum autem venisset in Jerusalem, tentabat se jungere discipulis, et omnes timebant eum, non credentes quod esset discipulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 27, 'Barnabas autem apprehensum illum duxit ad Apostolos: et narravit illis quomodo in via vidisset Dominum, et quia locutus est ei, et quomodo in Damasco fiducialiter egerit in nomine Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 28, 'Et erat cum illis intrans et exiens in Jerusalem, et fiducialiter agens in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 29, 'Loquebatur quoque gentibus, et disputabat cum Græcis: illi autem quærebant occidere eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 30, 'Quod cum cognovissent fratres, deduxerunt eum Cæsaream, et dimiserunt Tarsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 31, 'Ecclesia quidem per totam Judæam, et Galilæam, et Samariam habebat pacem, et ædificabatur ambulans in timore Domini, et consolatione Sancti Spiritus replebatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 32, 'Factum est autem, ut Petrus dum pertransiret universos, deveniret ad sanctos qui habitabant Lyddæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 33, 'Invenit autem ibi hominem quemdam, nomine \'neam, ab annis octo jacentem in grabato, qui erat paralyticus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 34, 'Et ait illi Petrus: \'nea, sanat te Dominus Jesus Christus: surge, et sterne tibi. Et continuo surrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 35, 'Et viderunt eum omnes qui habitabant Lyddæ et Saronæ: qui conversi sunt ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 36, 'In Joppe autem fuit quædam discipula, nomine Tabitha, quæ interpretata dicitur Dorcas. Hæc erat plena operibus bonis et eleemosynis quas faciebat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 37, 'Factum est autem in diebus illis ut infirmata moreretur. Quam cum lavissent, posuerunt eam in cœnaculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 38, 'Cum autem prope esset Lydda ad Joppen, discipuli, audientes quia Petrus esset in ea, miserunt duos viros ad eum, rogantes: Ne pigriteris venire ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 39, 'Exsurgens autem Petrus, venit cum illis. Et cum advenisset, duxerunt illum in cœnaculum: et circumsteterunt illum omnes viduæ flentes, et ostendentes ei tunicas et vestes quas faciebat illis Dorcas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 40, 'Ejectis autem omnibus foras, Petrus ponens genua oravit: et conversus ad corpus, dixit: Tabitha, surge. At illa aperuit oculos suos: et viso Petro, resedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 41, 'Dans autem illi manum, erexit eam. Et cum vocasset sanctos et viduas, assignavit eam vivam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 42, 'Notum autem factum est per universam Joppen: et crediderunt multi in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 9, 43, 'Factum est autem ut dies multos moraretur in Joppe, apud Simonem quemdam coriarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 1, 'Vir autem quidam erat in Cæsarea, nomine Cornelius, centurio cohortis quæ dicitur Italica,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 2, 'religiosus, ac timens Deum cum omni domo sua, faciens eleemosynas multas plebi, et deprecans Deum semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 3, 'Is vidit in visu manifeste, quasi hora diei nona, angelum Dei introëuntem ad se, et dicentem sibi: Corneli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 4, 'At ille intuens eum, timore correptus, dixit: Quid est, domine? Dixit autem illi: Orationes tuæ et eleemosynæ tuæ ascenderunt in memoriam in conspectu Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 5, 'Et nunc mitte viros in Joppen, et accersi Simonem quemdam, qui cognominatur Petrus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 6, 'hic hospitatur apud Simonem quemdam coriarium, cujus est domus juxta mare: hic dicet tibi quid te oporteat facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 7, 'Et cum discessisset angelus qui loquebatur illi, vocavit duos domesticos suos, et militem metuentem Dominum ex his qui illi parebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 8, 'Quibus cum narrasset omnia, misit illos in Joppen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 9, 'Postera autem die, iter illis facientibus, et appropinquantibus civitati, ascendit Petrus in superiora ut oraret circa horam sextam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 10, 'Et cum esuriret, voluit gustare. Parantibus autem illis, cecidit super eum mentis excessus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 11, 'et vidit cælum apertum, et descendens vas quoddam, velut linteum magnum, quatuor initiis submitti de cælo in terram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 12, 'in quo erant omnia quadrupedia, et serpentia terræ, et volatilia cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 13, 'Et facta est vox ad eum: Surge, Petre: occide, et manduca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 14, 'Ait autem Petrus: Absit Domine, quia numquam manducavi omne commune et immundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 15, 'Et vox iterum secundo ad eum: Quod Deus purificavit, tu commune ne dixeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 16, 'Hoc autem factum est per ter: et statim receptum est vas in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 17, 'Et dum intra se hæsitaret Petrus quidnam esset visio quam vidisset, ecce viri qui missi erant a Cornelio, inquirentes domum Simonis astiterunt ad januam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 18, 'Et cum vocassent, interrogabant, si Simon qui cognominatur Petrus illic haberet hospitium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 19, 'Petro autem cogitante de visione, dixit Spiritus ei: Ecce viri tres quærunt te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 20, 'Surge itaque, descende, et vade cum eis nihil dubitans: quia ego misi illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 21, 'Descendens autem Petrus ad viros, dixit: Ecce ego sum, quem quæritis: quæ causa est, propter quam venistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 22, 'Qui dixerunt: Cornelius centurio, vir justus et timens Deum, et testimonium habens ab universa gente Judæorum, responsum accepit ab angelo sancto accersire te in domum suam, et audire verba abs te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 23, 'Introducens ergo eos, recepit hospitio. Sequenti autem die, surgens profectus est cum illis, et quidam ex fratribus ab Joppe comitati sunt eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 24, 'Altera autem die introivit Cæsaream. Cornelius vero exspectabat illos, convocatis cognatis suis et necessariis amicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 25, 'Et factum est cum introisset Petrus, obvius venit ei Cornelius, et procidens ad pedes ejus adoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 26, 'Petrus vero elevavit eum, dicens: Surge: et ego ipse homo sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 27, 'Et loquens cum illo intravit, et invenit multos qui convenerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 28, 'dixitque ad illos: Vos scitis quomodo abominatum sit viro Judæo conjungi aut accedere ad alienigenam: sed mihi ostendit Deus neminem communem aut immundum dicere hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 29, 'Propter quod sine dubitatione veni accersitus. Interrogo ergo, quam ob causam accersistis me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 30, 'Et Cornelius ait: A nudiusquarta die usque ad hanc horam, orans eram hora nona in domo mea, et ecce vir stetit ante me in veste candida, et ait:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 31, 'Corneli, exaudita est oratio tua, et eleemosynæ tuæ commemoratæ sunt in conspectu Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 32, 'Mitte ergo in Joppen, et accersi Simonem qui cognominatur Petrus: hic hospitatur in domo Simonis coriarii juxta mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 33, 'Confestim ergo misi ad te: et tu benefecisti veniendo. Nunc ergo omnes nos in conspectu tuo adsumus audire omnia quæcumque tibi præcepta sunt a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 34, 'Aperiens autem Petrus os suum, dixit: In veritate comperi quia non est personarum acceptor Deus;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 35, 'sed in omni gente qui timet eum, et operatur justitiam, acceptus est illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 36, 'Verbum misit Deus filiis Israël, annuntians pacem per Jesum Christum (hic est omnium Dominus).');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 37, 'Vos scitis quod factum est verbum per universam Judæam: incipiens enim a Galilæa post baptismum quod prædicavit Joannes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 38, 'Jesum a Nazareth: quomodo unxit eum Deus Spiritu Sancto, et virtute, qui pertransiit benefaciendo, et sanando omnes oppressos a diabolo, quoniam Deus erat cum illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 39, 'Et nos testes sumus omnium quæ fecit in regione Judæorum, et Jerusalem, quem occiderunt suspendentes in ligno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 40, 'Hunc Deus suscitavit tertia die, et dedit eum manifestum fieri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 41, 'non omni populo, sed testibus præordinatis a Deo: nobis, qui manducavimus et bibimus cum illo postquam resurrexit a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 42, 'Et præcepit nobis prædicare populo, et testificari, quia ipse est qui constitutus est a Deo judex vivorum et mortuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 43, 'Huic omnes prophetæ testimonium perhibent remissionem peccatorum accipere per nomen ejus omnes qui credunt in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 44, 'Adhuc loquente Petro verba hæc, cecidit Spiritus Sanctus super omnes qui audiebant verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 45, 'Et obstupuerunt ex circumcisione fideles qui venerant cum Petro, quia et in nationes gratia Spiritus Sancti effusa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 46, 'Audiebant enim illos loquentes linguis, et magnificantes Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 47, 'Tunc respondit Petrus: Numquid aquam quis prohibere potest ut non baptizentur hi qui Spiritum Sanctum acceperunt sicut et nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 10, 48, 'Et jussit eos baptizari in nomine Domini Jesu Christi. Tunc rogaverunt eum ut maneret apud eos aliquot diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 1, 'Audierunt autem Apostoli et fratres qui erant in Judæa, quoniam et gentes receperunt verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 2, 'Cum autem ascendisset Petrus Jerosolymam, disceptabant adversus illum qui erant ex circumcisione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 3, 'dicentes: Quare introisti ad viros præputium habentes, et manducasti cum illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 4, 'Incipiens autem Petrus exponebat illis ordinem, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 5, 'Ego eram in civitate Joppe orans, et vidi in excessu mentis visionem, descendens vas quoddam velut linteum magnum quatuor initiis summitti de cælo, et venit usque ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 6, 'In quod intuens considerabam, et vidi quadrupedia terræ, et bestias, et reptilia, et volatilia cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 7, 'Audivi autem et vocem dicentem mihi: Surge, Petre: occide, et manduca.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 8, 'Dixi autem: Nequaquam Domine: quia commune aut immundum numquam introivit in os meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 9, 'Respondit autem vox secundo de cælo: Quæ Deus mundavit, tu ne commune dixeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 10, 'Hoc autem factum est per ter: et recepta sunt omnia rursum in cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 11, 'Et ecce viri tres confestim astiterunt in domo in qua eram, missi a Cæsarea ad me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 12, 'Dixit autem Spiritus mihi ut irem cum illis, nihil hæsitans. Venerunt autem mecum et sex fratres isti, et ingressi sumus in domum viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 13, 'Narravit autem nobis quomodo vidisset angelum in domo sua, stantem et dicentem sibi: Mitte in Joppen, et accersi Simonem qui cognominatur Petrus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 14, 'qui loquetur tibi verba in quibus salvus eris tu, et universa domus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 15, 'Cum autem cœpissem loqui, cecidit Spiritus Sanctus super eos, sicut et in nos in initio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 16, 'Recordatus sum autem verbi Domini, sicut dicebat: Joannes quidem baptizavit aqua, vos autem baptizabimini Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 17, 'Si ergo eamdem gratiam dedit illis Deus, sicut et nobis qui credidimus in Dominum Jesum Christum: ego quis eram, qui possem prohibere Deum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 18, 'His auditis, tacuerunt: et glorificaverunt Deum, dicentes: Ergo et gentibus pœnitentiam dedit Deus ad vitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 19, 'Et illi quidem qui dispersi fuerant a tribulatione quæ facta fuerat sub Stephano, perambulaverunt usque Phœnicen, et Cyprum, et Antiochiam, nemini loquentes verbum, nisi solis Judæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 20, 'Erant autem quidam ex eis viri Cyprii et Cyrenæi, qui cum introissent Antiochiam, loquebantur et ad Græcos, annuntiantes Dominum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 21, 'Et erat manus Domini cum eis: multusque numerus credentium conversus est ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 22, 'Pervenit autem sermo ad aures ecclesiæ quæ erat Jerosolymis super istis: et miserunt Barnabam usque ad Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 23, 'Qui cum pervenisset, et vidisset gratiam Dei, gavisus est: et hortabatur omnes in proposito cordis permanere in Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 24, 'quia erat vir bonus, et plenus Spiritu Sancto, et fide. Et apposita est multa turba Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 25, 'Profectus est autem Barnabas Tarsum, ut quæreret Saulum: quem cum invenisset, perduxit Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 26, 'Et annum totum conversati sunt ibi in ecclesia: et docuerunt turbam multam, ita ut cognominarentur primum Antiochiæ discipuli, christiani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 27, 'In his autem diebus supervenerunt ab Jerosolymis prophetæ Antiochiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 28, 'et surgens unus ex eis nomine Agabus, significabat per spiritum famem magnam futuram in universo orbe terrarum, quæ facta est sub Claudio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 29, 'Discipuli autem, prout quis habebat, proposuerunt singuli in ministerium mittere habitantibus in Judæa fratribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 11, 30, 'quod et fecerunt, mittentes ad seniores per manus Barnabæ et Sauli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 1, 'Eodem autem tempore misit Herodes rex manus, ut affligeret quosdam de ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 2, 'Occidit autem Jacobum fratrem Joannis gladio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 3, 'Videns autem quia placeret Judæis, apposuit ut apprehenderet et Petrum. Erant autem dies Azymorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 4, 'Quem cum apprehendisset, misit in carcerem, tradens quatuor quaternionibus militum custodiendum, volens post Pascha producere eum populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 5, 'Et Petrus quidem servabatur in carcere. Oratio autem fiebat sine intermissione ab ecclesia ad Deum pro eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 6, 'Cum autem producturus eum esset Herodes, in ipsa nocte erat Petrus dormiens inter duos milites, vinctus catenis duabus: et custodes ante ostium custodiebant carcerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 7, 'Et ecce angelus Domini astitit, et lumen refulsit in habitaculo: percussoque latere Petri, excitavit eum, dicens: Surge velociter. Et ceciderunt catenæ de manibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 8, 'Dixit autem angelus ad eum: Præcingere, et calcea te caligas tuas. Et fecit sic. Et dixit illi: Circumda tibi vestimentum tuum, et sequere me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 9, 'Et exiens sequebatur eum, et nesciebat quia verum est, quod fiebat per angelum: existimabat autem se visum videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 10, 'Transeuntes autem primam et secundam custodiam, venerunt ad portam ferream, quæ ducit ad civitatem: quæ ultro aperta est eis. Et exeuntes processerunt vicum unum: et continuo discessit angelus ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 11, 'Et Petrus ad se reversus, dixit: Nunc scio vere quia misit Dominus angelum suum, et eripuit me de manu Herodis, et de omni exspectatione plebis Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 12, 'Consideransque venit ad domum Mariæ matris Joannis, qui cognominatus est Marcus, ubi erant multi congregati, et orantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 13, 'Pulsante autem eo ostium januæ, processit puella ad audiendum, nomine Rhode.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 14, 'Et ut cognovit vocem Petri, præ gaudio non aperuit januam, sed intro currens nuntiavit stare Petrum ante januam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 15, 'At illi dixerunt ad eam: Insanis. Illa autem affirmabat sic se habere. Illi autem dicebant: Angelus ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 16, 'Petrus autem perseverabat pulsans. Cum autem aperuissent, viderunt eum, et obstupuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 17, 'Annuens autem eis manu ut tacerent, narravit quomodo Dominus eduxisset eum de carcere, dixitque: Nuntiate Jacobo et fratribus hæc. Et egressus abiit in alium locum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 18, 'Facta autem die, erat non parva turbatio inter milites, quidnam factum esset de Petro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 19, 'Herodes autem cum requisisset eum et non invenisset, inquisitione facta de custodibus, jussit eos duci: descendensque a Judæa in Cæsaream, ibi commoratus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 20, 'Erat autem iratus Tyriis et Sidoniis. At illi unanimes venerunt ad eum, et persuaso Blasto, qui erat super cubiculum regis, postulabant pacem, eo quod alerentur regiones eorum ab illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 21, 'Statuto autem die Herodes vestitus veste regia sedit pro tribunali, et concionabatur ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 22, 'Populus autem acclamabat: Dei voces, et non hominis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 23, 'Confestim autem percussit eum angelus Domini, eo quod non dedisset honorem Deo: et consumptus a vermibus, expiravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 24, 'Verbum autem Domini crescebat, et multiplicabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 12, 25, 'Barnabas autem et Saulus reversi sunt ab Jerosolymis expleto ministerio assumpto Joanne, qui cognominatus est Marcus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 1, 'Erant autem in ecclesia quæ erat Antiochiæ, prophetæ et doctores, in quibus Barnabas, et Simon qui vocabatur Niger, et Lucius Cyrenensis, et Manahen, qui erat Herodis Tetrarchæ collactaneus, et Saulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 2, 'Ministrantibus autem illis Domino, et jejunantibus, dixit illis Spiritus Sanctus: Segregate mihi Saulum et Barnabam in opus ad quod assumpsi eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 3, 'Tunc jejunantes et orantes, imponentesque eis manus, dimiserunt illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 4, 'Et ipsi quidem missi a Spiritu Sancto abierunt Seleuciam: et inde navigaverunt Cyprum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 5, 'Et cum venissent Salaminam, prædicabant verbum Dei in synagogis Judæorum. Habebant autem et Joannem in ministerio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 6, 'Et cum perambulassent universam insulam usque Paphum, invenerunt quemdam virum magum pseudoprophetam, Judæum, cui nomen erat Barjesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 7, 'qui erat cum proconsule Sergio Paulo viro prudente. Hic, accersitis Barnaba et Saulo, desiderabat audire verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 8, 'Resistebat autem illis Elymas magus (sic enim interpretatur nomen ejus), quærens avertere proconsulem a fide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 9, 'Saulus autem, qui et Paulus, repletus Spiritu Sancto, intuens in eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 10, 'dixit: O plene omni dolo et omni fallacia, fili diaboli, inimice omnis justitiæ, non desinis subvertere vias Domini rectas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 11, 'Et nunc ecce manus Domini super te, et eris cæcus, non videns solem usque ad tempus. Et confestim cecidit in eum caligo et tenebræ: et circuiens quærebat qui ei manum daret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 12, 'Tunc proconsul cum vidisset factum, credidit admirans super doctrina Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 13, 'Et cum a Papho navigassent Paulus et qui cum eo erant, venerunt Pergen Pamphyliæ. Joannes autem discedens ab eis, reversus est Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 14, 'Illi vero pertranseuntes Pergen, venerunt Antiochiam Pisidiæ: et ingressi synagogam die sabbatorum, sederunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 15, 'Post lectionem autem legis et prophetarum, miserunt principes synagogæ ad eos, dicentes: Viri fratres, si quis est in vobis sermo exhortationis ad plebem, dicite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 16, 'Surgens autem Paulus, et manu silentium indicens, ait: Viri Israëlitæ, et qui timetis Deum, audite:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 17, 'Deus plebis Israël elegit patres nostros, et plebem exaltavit cum essent incolæ in terra \'gypti, et in brachio excelso eduxit eos ex ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 18, 'et per quadraginta annorum tempus mores eorum sustinuit in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 19, 'Et destruens gentes septem in terra Chanaan, sorte distribuit eis terram eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 20, 'quasi post quadringentos et quinquaginta annos: et post hæc dedit judices, usque ad Samuel prophetam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 21, 'Et exinde postulaverunt regem: et dedit illis Deus Saul filium Cis, virum de tribu Benjamin, annis quadraginta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 22, 'et amoto illo, suscitavit illis David regem: cui testimonium perhibens, dixit: Inveni David filium Jesse, virum secundum cor meum, qui faciet omnes voluntates meas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 23, 'Hujus Deus ex semine secundum promissionem eduxit Israël salvatorem Jesum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 24, 'prædicante Joanne ante faciem adventus ejus baptismum pœnitentiæ omni populo Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 25, 'Cum impleret autem Joannes cursum suum, dicebat: Quem me arbitramini esse, non sum ego: sed ecce venit post me, cujus non sum dignus calceamenta pedum solvere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 26, 'Viri fratres, filii generis Abraham, et qui in vobis timent Deum, vobis verbum salutis hujus missum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 27, 'Qui enim habitabant Jerusalem, et principes ejus hunc ignorantes, et voces prophetarum quæ per omne sabbatum leguntur, judicantes impleverunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 28, 'et nullam causam mortis invenientes in eo, petierunt a Pilato ut interficerent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 29, 'Cumque consummassent omnia quæ de eo scripta erant, deponentes eum de ligno, posuerunt eum in monumento.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 30, 'Deus vero suscitavit eum a mortuis tertia die: qui visus est per dies multos his');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 31, 'qui simul ascenderant cum eo de Galilæa in Jerusalem: qui usque nunc sunt testes ejus ad plebem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 32, 'Et nos vobis annuntiamus eam, quæ ad patres nostros repromissio facta est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 33, 'quoniam hanc Deus adimplevit filiis nostris resuscitans Jesum, sicut et in psalmo secundo scriptum est: Filius meus es tu, ego hodie genui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 34, 'Quod autem suscitavit eum a mortuis, amplius jam non reversurum in corruptionem, ita dixit: Quia dabo vobis sancta David fidelia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 35, 'Ideoque et alias dicit: Non dabis sanctum tuum videre corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 36, 'David enim in sua generatione cum administrasset, voluntati Dei dormivit: et appositus est ad patres suos, et vidit corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 37, 'Quem vero Deus suscitavit a mortuis, non vidit corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 38, 'Notum igitur sit vobis, viri fratres, quia per hunc vobis remissio peccatorum annuntiatur, et ab omnibus quibus non potuistis in lege Moysi justificari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 39, 'in hoc omnis qui credit, justificatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 40, 'Videte ergo ne superveniat vobis quod dictum est in prophetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 41, 'Videte contemptores, et admiramini, et disperdimini: quia opus operor ego in diebus vestris, opus quod non credetis, si quis enarraverit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 42, 'Exeuntibus autem illis rogabant ut sequenti sabbato loquerentur sibi verba hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 43, 'Cumque dimissa esset synagoga, secuti sunt multi Judæorum, et colentium advenarum, Paulum et Barnabam: qui loquentes suadebant eis ut permanerent in gratia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 44, 'Sequenti vero sabbato pene universa civitas convenit audire verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 45, 'Videntes autem turbas Judæi, repleti sunt zelo, et contradicebant his quæ a Paulo dicebantur, blasphemantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 46, 'Tunc constanter Paulus et Barnabas dixerunt: Vobis oportebat primum loqui verbum Dei: sed quoniam repellitis illud, et indignos vos judicatis æternæ vitæ, ecce convertimur ad gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 47, 'Sic enim præcepit nobis Dominus: Posui te in lucem gentium, ut sis in salutem usque ad extremum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 48, 'Audientes autem gentes, gavisæ sunt, et glorificabant verbum Domini: et crediderunt quotquot erant præordinati ad vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 49, 'Disseminabatur autem verbum Domini per universam regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 50, 'Judæi autem concitaverunt mulieres religiosas et honestas, et primos civitatis, et excitaverunt persecutionem in Paulum et Barnabam: et ejecerunt eos de finibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 51, 'At illi excusso pulvere pedum in eos, venerunt Iconium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 13, 52, 'Discipuli quoque replebantur gaudio, et Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 1, 'Factum est autem Iconii, ut simul introirent in synagogam Judæorum, et loquerentur, ita ut crederet Judæorum et Græcorum copiosa multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 2, 'Qui vero increduli fuerunt Judæi, suscitaverunt et ad iracundiam concitaverunt animas gentium adversus fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 3, 'Multo igitur tempore demorati sunt, fiducialiter agentes in Domino, testimonium perhibente verbo gratiæ suæ, dante signa et prodigia fieri per manus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 4, 'Divisa est autem multitudo civitatis: et quidam quidem erant cum Judæis, quidam vero cum Apostolis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 5, 'Cum autem factus esset impetus gentilium et Judæorum cum principibus suis, ut contumeliis afficerent, et lapidarent eos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 6, 'intelligentes confugerunt ad civitates Lycaoniæ Lystram et Derben, et universam in circuitu regionem, et ibi evangelizantes erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 7, 'Et quidam vir Lystris infirmus pedibus sedebat, claudus ex utero matris suæ, qui numquam ambulaverat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 8, 'Hic audivit Paulum loquentem. Qui intuitus eum, et videns quia fidem haberet ut salvus fieret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 9, 'dixit magna voce: Surge super pedes tuos rectus. Et exilivit, et ambulabat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 10, 'Turbæ autem cum vidissent quod fecerat Paulus, levaverunt vocem suam lycaonice, dicentes: Dii similes facti hominibus descenderunt ad nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 11, 'Et vocabant Barnabam Jovem, Paulum vero Mercurium: quoniam ipse erat dux verbi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 12, 'Sacerdos quoque Jovis, qui erat ante civitatem, tauros et coronas ante januas afferens, cum populis volebat sacrificare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 13, 'Quod ubi audierunt Apostoli, Barnabas et Paulus, conscissis tunicis suis exilierunt in turbas, clamantes');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 14, 'et dicentes: Viri, quid hæc facitis? et nos mortales sumus, similes vobis homines, annuntiantes vobis ab his vanis converti ad Deum vivum, qui fecit cælum, et terram, et mare, et omnia quæ in eis sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 15, 'qui in præteritis generationibus dimisit omnes gentes ingredi vias suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 16, 'Et quidem non sine testimonio semetipsum reliquit benefaciens de cælo, dans pluvias et tempora fructifera, implens cibo et lætitia corda nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 17, 'Et hæc dicentes, vix sedaverunt turbas ne sibi immolarent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 18, 'Supervenerunt autem quidam ab Antiochia et Iconio Judæi: et persuasis turbis, lapidantesque Paulum, traxerunt extra civitatem, existimantes eum mortuum esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 19, 'Circumdantibus autem eum discipulis, surgens intravit civitatem, et postera die profectus est cum Barnaba in Derben.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 20, 'Cumque evangelizassent civitati illi, et docuissent multos, reversi sunt Lystram, et Iconium, et Antiochiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 21, 'confirmantes animas discipulorum, exhortantesque ut permanerent in fide: et quoniam per multas tribulationes oportet nos intrare in regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 22, 'Et cum constituissent illis per singulas ecclesias presbyteros, et orassent cum jejunationibus, commendaverunt eos Domino, in quem crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 23, 'Transeuntesque Pisidiam, venerunt in Pamphyliam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 24, 'et loquentes verbum Domini in Perge, descenderunt in Attaliam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 25, 'et inde navigaverunt Antiochiam, unde erant traditi gratiæ Dei in opus quod compleverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 26, 'Cum autem venissent, et congregassent ecclesiam, retulerunt quanta fecisset Deus cum illis, et quia aperuisset gentibus ostium fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 14, 27, 'Morati sunt autem tempus non modicum cum discipulis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 1, 'Et quidam descendentes de Judæa docebant fratres: Quia nisi circumcidamini secundum morem Moysi, non potestis salvari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 2, 'Facta ergo seditione non minima Paulo et Barnabæ adversus illos, statuerunt ut ascenderent Paulus et Barnabas, et quidam alii ex aliis ad Apostolos et presbyteros in Jerusalem super hac quæstione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 3, 'Illi ergo deducti ab ecclesia pertransibant Phœnicen et Samariam, narrantes conversionem gentium: et faciebant gaudium magnum omnibus fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 4, 'Cum autem venissent Jerosolymam, suscepti sunt ab ecclesia, et ab Apostolis et senioribus, annuntiantes quanta Deus fecisset cum illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 5, 'Surrexerunt autem quidam de hæresi pharisæorum, qui crediderunt, dicentes quia oportet circumcidi eos, præcipere quoque servare legem Moysi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 6, 'Conveneruntque Apostoli et seniores videre de verbo hoc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 7, 'Cum autem magna conquisitio fieret, surgens Petrus dixit ad eos: Viri fratres, vos scitis quoniam ab antiquis diebus Deus in nobis elegit, per os meum audire gentes verbum Evangelii et credere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 8, 'Et qui novit corda Deus, testimonium perhibuit, dans illis Spiritum Sanctum, sicut et nobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 9, 'et nihil discrevit inter nos et illos, fide purificans corda eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 10, 'Nunc ergo quid tentatis Deum, imponere jugum super cervices discipulorum quod neque patres nostri, neque nos portare potuimus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 11, 'sed per gratiam Domini Jesu Christi credimus salvari, quemadmodum et illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 12, 'Tacuit autem omnis multitudo: et audiebant Barnabam et Paulum narrantes quanta Deus fecisset signa et prodigia in gentibus per eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 13, 'Et postquam tacuerunt, respondit Jacobus, dicens: Viri fratres, audite me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 14, 'Simon narravit quemadmodum primum Deus visitavit sumere ex gentibus populum nomini suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 15, 'Et huic concordant verba prophetarum: sicut scriptum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 16, 'Post hæc revertar, et reædificabo tabernaculum David quod decidit: et diruta ejus reædificabo, et erigam illud:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 17, 'ut requirant ceteri hominum Dominum, et omnes gentes super quas invocatum est nomen meum, dicit Dominus faciens hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 18, 'Notum a sæculo est Domino opus suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 19, 'Propter quod ego judico non inquietari eos qui ex gentibus convertuntur ad Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 20, 'sed scribere ad eos ut abstineant se a contaminationibus simulacrorum, et fornicatione, et suffocatis, et sanguine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 21, 'Moyses enim a temporibus antiquis habet in singulis civitatibus qui eum prædicent in synagogis, ubi per omne sabbatum legitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 22, 'Tunc placuit Apostolis et senioribus cum omni ecclesia eligere viros ex eis, et mittere Antiochiam cum Paulo et Barnaba: Judam, qui cognominabatur Barsabas, et Silam, viros primos in fratribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 23, 'scribentes per manus eorum: Apostoli et seniores fratres, his qui sunt Antiochiæ, et Syriæ, et Ciliciæ, fratribus ex gentibus, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 24, 'Quoniam audivimus quia quidam ex nobis exeuntes, turbaverunt vos verbis, evertentes animas vestras, quibus non mandavimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 25, 'placuit nobis collectis in unum eligere viros, et mittere ad vos cum carissimis nostris Barnaba et Paulo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 26, 'hominibus qui tradiderunt animas suas pro nomine Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 27, 'Misimus ergo Judam et Silam, qui et ipsi vobis verbis referent eadem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 28, 'Visum est enim Spiritui Sancto et nobis nihil ultra imponere vobis oneris quam hæc necessaria:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 29, 'ut abstineatis vos ab immolatis simulacrorum, et sanguine, et suffocato, et fornicatione: a quibus custodientes vos, bene agetis. Valete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 30, 'Illi ergo dimissi, descenderunt Antiochiam: et congregata multitudine tradiderunt epistolam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 31, 'Quam cum legissent, gavisi sunt super consolatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 32, 'Judas autem et Silas, et ipsi cum essent prophetæ, verbo plurimo consolati sunt fratres, et confirmaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 33, 'Facto autem ibi aliquanto tempore, dimissi sunt cum pace a fratribus ad eos qui miserant illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 34, 'Visum est autem Silæ ibi remanere: Judas autem solus abiit Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 35, 'Paulus autem et Barnabas demorabantur Antiochiæ, docentes et evangelizantes cum aliis pluribus verbum Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 36, 'Post aliquot autem dies, dixit ad Barnabam Paulus: Revertentes visitemus fratres per universas civitates in quibus prædicavimus verbum Domini, quomodo se habeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 37, 'Barnabas autem volebat secum assumere et Joannem, qui cognominabatur Marcus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 38, 'Paulus autem rogabat eum (ut qui discessisset ab eis de Pamphylia, et non isset cum eis in opus) non debere recipi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 39, 'Facta est autem dissensio, ita ut discederent ab invicem, et Barnabas quidem, assumpto Marco, navigaret Cyprum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 40, 'Paulus vero, electo Sila, profectus est, traditus gratiæ Dei a fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 15, 41, 'Perambulabat autem Syriam et Ciliciam, confirmans ecclesias: præcipiens custodire præcepta Apostolorum et seniorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 1, 'Pervenit autem Derben et Lystram. Et ecce discipulus quidam erat ibi nomine Timotheus, filius mulieris Judææ fidelis, patre gentili.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 2, 'Huic testimonium bonum reddebant qui in Lystris erant et Iconio fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 3, 'Hunc voluit Paulus secum proficisci: et assumens circumcidit eum propter Judæos qui erant in illis locis. Sciebant enim omnes quod pater ejus erat gentilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 4, 'Cum autem pertransirent civitates, tradebant eis custodiri dogmata quæ erant decreta ab Apostolis et senioribus qui erant Jerosolymis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 5, 'Et ecclesiæ quidem confirmabantur fide, et abundabunt numero quotidie.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 6, 'Transeuntes autem Phrygiam et Galatiæ regionem, vetati sunt a Spiritu Sancto loqui verbum Dei in Asia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 7, 'Cum venissent autem in Mysiam, tentabant ire in Bithyniam: et non permisit eos Spiritus Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 8, 'Cum autem pertransissent Mysiam, descenderunt Troadem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 9, 'et visio per noctem Paulo ostensa est: vir Macedo quidam erat stans et deprecans eum, et dicens: Transiens in Macedoniam, adjuva nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 10, 'Ut autem visum vidit, statim quæsivimus proficisci in Macedoniam, certi facti quod vocasset nos Deus evangelizare eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 11, 'Navigantes autem a Troade, recto cursu venimus Samothraciam, et sequenti die Neapolim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 12, 'et inde Philippos, quæ est prima partis Macedoniæ civitas, colonia. Eramus autem in hac urbe diebus aliquot, conferentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 13, 'Die autem sabbatorum egressi sumus foras portam juxta flumen, ubi videbatur oratio esse: et sedentes loquebamur mulieribus quæ convenerant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 14, 'Et quædam mulier nomine Lydia, purpuraria civitatis Thyatirenorum, colens Deum, audivit: cujus Dominus aperuit cor intendere his quæ dicebantur a Paulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 15, 'Cum autem baptizata esset, et domus ejus, deprecata est, dicens: Si judicastis me fidelem Domino esse, introite in domum meam, et manete. Et coëgit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 16, 'Factum est autem euntibus nobis ad orationem, puellam quamdam habentem spiritum pythonem obviare nobis, quæ quæstum magnum præstabat dominis suis divinando.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 17, 'Hæc subsecuta Paulum et nos, clamabat dicens: Isti homines servi Dei excelsi sunt, qui annuntiant vobis viam salutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 18, 'Hoc autem faciebat multis diebus. Dolens autem Paulus, et conversus, spiritui dixit: Præcipio tibi in nomine Jesu Christi exire ab ea. Et exiit eadem hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 19, 'Videntes autem domini ejus quia exivit spes quæstus eorum, apprehendentes Paulum et Silam, perduxerunt in forum ad principes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 20, 'et offerentes eos magistratibus, dixerunt: Hi homines conturbant civitatem nostram, cum sint Judæi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 21, 'et annuntiant morem quem non licet nobis suscipere neque facere, cum simus Romani.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 22, 'Et cucurrit plebs adversus eos: et magistratus, scissis tunicis eorum, jusserunt eos virgis cædi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 23, 'Et cum multas plagas eis imposuissent, miserunt eos in carcerem, præcipientes custodi ut diligenter custodiret eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 24, 'Qui cum tale præceptum accepisset, misit eos in interiorem carcerem, et pedes eorum strinxit ligno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 25, 'Media autem nocte Paulus et Silas orantes, laudabant Deum: et audiebant eos qui in custodia erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 26, 'Subito vero terræmotus factus est magnus, ita ut moverentur fundamenta carceris. Et statim aperta sunt omnia ostia: et universorum vincula soluta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 27, 'Expergefactus autem custos carceris, et videns januas apertas carceris, evaginato gladio volebat se interficere, æstimans fugisse vinctos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 28, 'Clamavit autem Paulus voce magna, dicens: Nihil tibi mali feceris: universi enim hic sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 29, 'Petitoque lumine, introgressus est: et tremefactus procidit Paulo et Silæ ad pedes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 30, 'et producens eos foras, ait: Domini, quid me oportet facere, ut salvus fiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 31, 'At illi dixerunt: Crede in Dominum Jesum, et salvus eris tu, et domus tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 32, 'Et locuti sunt ei verbum Domini cum omnibus qui erant in domo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 33, 'Et tollens eos in illa hora noctis, lavit plagas eorum: et baptizatus est ipse, et omnis domus ejus continuo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 34, 'Cumque perduxisset eos in domum suam, apposuit eis mensam, et lætatus est cum omni domo sua credens Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 35, 'Et cum dies factus esset, miserunt magistratus lictores, dicentes: Dimitte homines illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 36, 'Nuntiavit autem custos carceris verba hæc Paulo: Quia miserunt magistratus ut dimittamini: nunc igitur exeuntes, ite in pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 37, 'Paulus autem dixit eis: Cæsos nos publice, indemnatos homines Romanos, miserunt in carcerem: et nunc occulte nos ejiciunt? Non ita: sed veniant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 38, 'et ipsi nos ejiciant. Nuntiaverunt autem magistratibus lictores verba hæc. Timueruntque audito quod Romani essent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 39, 'et venientes deprecati sunt eos, et educentes rogabant ut egrederentur de urbe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 16, 40, 'Exeuntes autem de carcere, introierunt ad Lydiam: et visis fratribus consolati sunt eos, et profecti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 1, 'Cum autem perambulassent Amphipolim et Apolloniam, venerunt Thessalonicam, ubi erat synagoga Judæorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 2, 'Secundum consuetudinem autem Paulus introivit ad eos, et per sabbata tria disserebat eis de Scripturis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 3, 'adaperiens et insinuans quia Christum oportuit pati, et resurgere a mortuis: et quia hic est Jesus Christus, quem ego annuntio vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 4, 'Et quidam ex eis crediderunt et adjuncti sunt Paulo et Silæ: et de colentibus gentilibusque multitudo magna, et mulieres nobiles non paucæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 5, 'Zelantes autem Judæi, assumentesque de vulgo viros quosdam malos, et turba facta, concitaverunt civitatem: et assistentes domui Jasonis quærebant eos producere in populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 6, 'Et cum non invenissent eos, trahebant Jasonem et quosdam fratres ad principes civitatis, clamantes: Quoniam hi qui urbem concitant, et huc venerunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 7, 'quos suscepit Jason, et hi omnes contra decreta Cæsaris faciunt, regem alium dicentes esse, Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 8, 'Concitaverunt autem plebem et principes civitatis audientes hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 9, 'Et accepta satisfactione a Jasone et a ceteris, dimiserunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 10, 'Fratres vero confestim per noctem dimiserunt Paulum et Silam in Berœam. Qui cum venissent, in synagogam Judæorum introierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 11, 'Hi autem erant nobiliores eorum qui sunt Thessalonicæ, qui susceperunt verbum cum omni aviditate, quotidie scrutantes Scripturas, si hæc ita se haberent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 12, 'Et multi quidem crediderunt ex eis, et mulierum gentilium honestarum, et viri non pauci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 13, 'Cum autem cognovissent in Thessalonica Judæi quia et Berœæ prædicatum est a Paulo verbum Dei, venerunt et illuc commoventes, et turbantes multitudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 14, 'Statimque tunc Paulum dimiserunt fratres, ut iret usque ad mare: Silas autem et Timotheus remanserunt ibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 15, 'Qui autem deducebant Paulum, perduxerunt eum usque Athenas, et accepto mandato ab eo ad Silam et Timotheum ut quam celeriter venirent ad illum, profecti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 16, 'Paulus autem cum Athenis eos exspectaret, incitabatur spiritus ejus in ipso, videns idololatriæ deditam civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 17, 'Disputabat igitur in synagoga cum Judæis et colentibus, et in foro, per omnes dies ad eos qui aderant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 18, 'Quidam autem epicurei et stoici philosophi disserebant cum eo, et quidam dicebant: Quid vult seminiverbius hic dicere? Alii vero: Novorum dæmoniorum videtur annuntiator esse: quia Jesum et resurrectionem annuntiabat eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 19, 'Et apprehensum eum ad Areopagum duxerunt, dicentes: Possumus scire quæ est hæc nova, quæ a te dicitur, doctrina?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 20, 'nova enim quædam infers auribus nostris: volumus ergo scire quidnam velint hæc esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 21, '(Athenienses autem omnes, et advenæ hospites, ad nihil aliud vacabant nisi aut dicere aut audire aliquid novi.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 22, 'Stans autem Paulus in medio Areopagi, ait: Viri Athenienses, per omnia quasi superstitiosiores vos video.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 23, 'Præteriens enim, et videns simulacra vestra, inveni et aram in qua scriptum erat: Ignoto Deo. Quod ergo ignorantes colitis, hoc ego annuntio vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 24, 'Deus, qui fecit mundum, et omnia quæ in eo sunt, hic cæli et terræ cum sit Dominus, non in manufactis templis habitat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 25, 'nec manibus humanis colitur indigens aliquo, cum ipse det omnibus vitam, et inspirationem, et omnia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 26, 'fecitque ex uno omne genus hominum inhabitare super universam faciem terræ, definiens statuta tempora, et terminos habitationis eorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 27, 'quærere Deum si forte attrectent eum, aut inveniant, quamvis non longe sit ab unoquoque nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 28, 'In ipso enim vivimus, et movemur, et sumus: sicut et quidam vestrorum poëtarum dixerunt: Ipsius enim et genus sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 29, 'Genus ergo cum simus Dei, non debemus æstimare auro, aut argento, aut lapidi, sculpturæ artis, et cogitationis hominis, divinum esse simile.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 30, 'Et tempora quidem hujus ignorantiæ despiciens Deus, nunc annuntiat hominibus ut omnes ubique pœnitentiam agant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 31, 'eo quod statuit diem in quo judicaturus est orbem in æquitate, in viro in quo statuit, fidem præbens omnibus, suscitans eum a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 32, 'Cum audissent autem resurrectionem mortuorum, quidam quidem irridebant, quidam vero dixerunt: Audiemus te de hoc iterum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 33, 'Sic Paulus exivit de medio eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 17, 34, 'Quidam vero viri adhærentes ei, crediderunt: in quibus et Dionysius Areopagita, et mulier nomine Damaris, et alii cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 1, 'Post hæc egressus ab Athenis, venit Corinthum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 2, 'et inveniens quemdam Judæum nomine Aquilam, Ponticum genere, qui nuper venerat ab Italia, et Priscillam uxorem ejus (eo quod præcepisset Claudius discedere omnes Judæos a Roma), accessit ad eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 3, 'Et quia ejusdem erat artis, manebat apud eos, et operabatur. (Erant autem scenofactoriæ artis.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 4, 'Et disputabat in synagoga per omne sabbatum, interponens nomen Domini Jesu: suadebatque Judæis et Græcis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 5, 'Cum venissent autem de Macedonia Silas et Timotheus, instabat verbo Paulus, testificans Judæis esse Christum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 6, 'Contradicentibus autem eis, et blasphemantibus, excutiens vestimenta sua, dixit ad eos: Sanguis vester super caput vestrum: mundus ego: ex hoc ad gentes vadam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 7, 'Et migrans inde, intravit in domum cujusdam, nomine Titi Justi, colentis Deum, cujus domus erat conjuncta synagogæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 8, 'Crispus autem archisynagogus credidit Domino cum omni domo sua: et multi Corinthiorum audientes credebant, et baptizabantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 9, 'Dixit autem Dominus nocte per visionem Paulo: Noli timere, sed loquere, et ne taceas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 10, 'propter quod ego sum tecum, et nemo apponetur tibi ut noceat te: quoniam populus est mihi multus in hac civitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 11, 'Sedit autem ibi annum et sex menses, docens apud eos verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 12, 'Gallione autem proconsule Achaiæ, insurrexerunt uno animo Judæi in Paulum, et adduxerunt eum ad tribunal,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 13, 'dicentes: Quia contra legem hic persuadet hominibus colere Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 14, 'Incipiente autem Paulo aperire os, dixit Gallio ad Judæos: Si quidem esset iniquum aliquid aut facinus pessimum, o viri Judæi, recte vos sustinerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 15, 'Si vero quæstiones sunt de verbo, et nominibus, et lege vestra, vos ipsi videritis: judex ego horum nolo esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 16, 'Et minavit eos a tribunali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 17, 'Apprehendentes autem omnes Sosthenem principem synagogæ, percutiebant eum ante tribunal: et nihil eorum Gallioni curæ erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 18, 'Paulus vero cum adhuc sustinuisset dies multos fratribus valefaciens, navigavit in Syriam (et cum eo Priscilla et Aquila), qui sibi totonderat in Cenchris caput: habebat enim votum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 19, 'Devenitque Ephesum, et illos ibi reliquit. Ipse vero ingressus synagogam, disputabat cum Judæis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 20, 'Rogantibus autem eis ut ampliori tempore maneret, non consensit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 21, 'sed valefaciens, et dicens: Iterum revertar ad vos, Deo volente: profectus est ab Epheso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 22, 'Et descendens Cæsaream, ascendit, et salutavit ecclesiam, et descendit Antiochiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 23, 'Et facto ibi aliquanto tempore profectus est, perambulans ex ordine Galaticam regionem, et Phrygiam, confirmans omnes discipulos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 24, 'Judæus autem quidam, Apollo nomine, Alexandrinus genere, vir eloquens, devenit Ephesum, potens in scripturis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 25, 'Hic erat edoctus viam Domini: et fervens spiritu loquebatur, et docebat diligenter ea quæ sunt Jesu, sciens tantum baptisma Joannis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 26, 'Hic ergo cœpit fiducialiter agere in synagoga. Quem cum audissent Priscilla et Aquila, assumpserunt eum, et diligentius exposuerunt ei viam Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 27, 'Cum autem vellet ire Achaiam, exhortati fratres, scripserunt discipulis ut susciperent eum. Qui cum venisset, contulit multum his qui crediderant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 18, 28, 'Vehementer enim Judæos revincebat publice, ostendens per Scripturas esse Christum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 1, 'Factum est autem cum Apollo esset Corinthi, ut Paulus peragratis superioribus partibus veniret Ephesum, et inveniret quosdam discipulos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 2, 'dixitque ad eos: Si Spiritum Sanctum accepistis credentes? At illi dixerunt ad eum: Sed neque si Spiritus Sanctus est, audivimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 3, 'Ille vero ait: In quo ergo baptizati estis? Qui dixerunt: In Joannis baptismate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 4, 'Dixit autem Paulus: Joannes baptizavit baptismo pœnitentiæ populum, dicens in eum qui venturus esset post ipsum ut crederent, hoc est, in Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 5, 'His auditis, baptizati sunt in nomine Domini Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 6, 'Et cum imposuisset illis manus Paulus, venit Spiritus Sanctus super eos, et loquebantur linguis, et prophetabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 7, 'Erant autem omnes viri fere duodecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 8, 'Introgressus autem synagogam, cum fiducia loquebatur per tres menses, disputans et suadens de regno Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 9, 'Cum autem quidam indurarentur, et non crederent, maledicentes viam Domini coram multitudine, discedens ab eis, segregavit discipulos, quotidie disputans in schola tyranni cujusdam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 10, 'Hoc autem factum est per biennium, ita ut omnes qui habitabant in Asia audirent verbum Domini, Judæi atque gentiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 11, 'Virtutesque non quaslibet faciebat Deus per manum Pauli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 12, 'ita ut etiam super languidos deferrentur a corpore ejus sudaria et semicinctia, et recedebant ab eis languores, et spiritus nequam egrediebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 13, 'Tentaverunt autem quidam et de circumeuntibus Judæis exorcistis invocare super eos qui habebant spiritus malos nomen Domini Jesu, dicentes: Adjuro vos per Jesum, quem Paulus prædicat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 14, 'Erant autem quidam Judæi, Scevæ principis sacerdotum septem filii, qui hoc faciebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 15, 'Respondens autem spiritus nequam dixit eis: Jesum novi, et Paulum scio: vos autem qui estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 16, 'Et insiliens in eos homo, in quo erat dæmonium pessimum, et dominatus amborum, invaluit contra eos, ita ut nudi et vulnerati effugerent de domo illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 17, 'Hoc autem notum factum est omnibus Judæis, atque gentilibus qui habitabant Ephesi: et cecidit timor super omnes illos, et magnificabatur nomen Domini Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 18, 'Multique credentium veniebant, confitentes et annuntiantes actus suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 19, 'Multi autem ex eis, qui fuerant curiosa sectati, contulerunt libros, et combusserunt coram omnibus: et computatis pretiis illorum, invenerunt pecuniam denariorum quinquaginta millium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 20, 'Ita fortiter crescebat verbum Dei, et confirmabatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 21, 'His autem expletis, proposuit Paulus in Spiritu, transita Macedonia et Achaia, ire Jerosolymam, dicens: Quoniam postquam fuero ibi, oportet me et Romam videre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 22, 'Mittens autem in Macedoniam duos ex ministrantibus sibi, Timotheum et Erastum, ipse remansit ad tempus in Asia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 23, 'Facta est autem illo tempore turbatio non minima de via Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 24, 'Demetrius enim quidam nomine, argentarius, faciens ædes argenteas Dianæ, præstabat artificibus non modicum quæstum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 25, 'quos convocans, et eos qui hujusmodi erant opifices, dixit: Viri, scitis quia de hoc artificio est nobis acquisitio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 26, 'et videtis et auditis quia non solum Ephesi, sed pene totius Asiæ, Paulus hic suadens avertit multam turbam, dicens: Quoniam non sunt dii, qui manibus fiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 27, 'Non solum autem hæc periclitabitur nobis pars in redargutionem venire, sed et magnæ Dianæ templum in nihilum reputabitur, sed et destrui incipiet majestas ejus, quam tota Asia et orbis colit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 28, 'His auditis, repleti sunt ira, et exclamaverunt dicentes: Magna Diana Ephesiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 29, 'Et impleta est civitas confusione, et impetum fecerunt uno animo in theatrum, rapto Gajo et Aristarcho Macedonibus, comitibus Pauli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 30, 'Paulo autem volente intrare in populum, non permiserunt discipuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 31, 'Quidam autem et de Asiæ principibus, qui erant amici ejus, miserunt ad eum rogantes ne se daret in theatrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 32, 'alii autem aliud clamabant. Erat enim ecclesia confusa: et plures nesciebant qua ex causa convenissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 33, 'De turba autem detraxerunt Alexandrum, propellentibus eum Judæis. Alexander autem manu silentio postulato, volebat reddere rationem populo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 34, 'Quem ut cognoverunt Judæum esse, vox facta una est omnium, quasi per horas duas clamantium: Magna Diana Ephesiorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 35, 'Et cum sedasset scriba turbas, dixit: Viri Ephesii, quis enim est hominum, qui nesciat Ephesiorum civitatem cultricem esse magnæ Dianæ, Jovisque prolis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 36, 'Cum ergo his contradici non possit, oportet vos sedatos esse, et nihil temere agere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 37, 'Adduxistis enim homines istos, neque sacrilegos, neque blasphemantes deam vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 38, 'Quod si Demetrius et qui cum eo sunt artifices, habent adversus aliquem causam, conventus forenses aguntur, et proconsules sunt: accusent invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 39, 'Si quid autem alterius rei quæritis, in legitima ecclesia poterit absolvi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 19, 40, 'Nam et periclitamur argui seditionis hodiernæ, cum nullus obnoxius sit de quo possimus reddere rationem concursus istius. Et cum hæc dixisset, dimisit ecclesiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 1, 'Postquam autem cessavit tumultus, vocatis Paulus discipulis, et exhortatus eos, valedixit, et profectus est ut iret in Macedoniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 2, 'Cum autem perambulasset partes illas, et exhortatus eos fuisset multo sermone, venit ad Græciam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 3, 'ubi cum fecisset menses tres, factæ sunt illi insidiæ a Judæis navigaturo in Syriam: habuitque consilium ut reverteretur per Macedoniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 4, 'Comitatus est autem eum Sopater Pyrrhi Berœensis, Thessalonicensium vero Aristarchus, et Secundus, et Gajus Derbeus, et Timotheus: Asiani vero Tychicus et Trophimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 5, 'Hi cum præcessissent, sustinuerunt nos Troade:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 6, 'nos vero navigavimus post dies azymorum a Philippis, et venimus ad eos Troadem in diebus quinque, ubi demorati sumus diebus septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 7, 'Una autem sabbati cum convenissemus ad frangendum panem, Paulus disputabat cum eis profecturus in crastinum, protraxitque sermonem usque in mediam noctem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 8, 'Erant autem lampades copiosæ in cœnaculo, ubi eramus congregati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 9, 'Sedens autem quidam adolescens nomine Eutychus super fenestram, cum mergeretur somno gravi, disputante diu Paulo, ductus somno cecidit de tertio cœnaculo deorsum, et sublatus est mortuus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 10, 'Ad quem cum descendisset Paulus, incubuit super eum: et complexus dixit: Nolite turbari, anima enim ipsius in ipso est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 11, 'Ascendens autem, frangensque panem, et gustans, satisque allocutus usque in lucem, sic profectus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 12, 'Adduxerunt autem puerum viventem, et consolati sunt non minime.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 13, 'Nos autem ascendentes navem, navigavimus in Asson, inde suscepturi Paulum: sic enim disposuerat ipse per terram iter facturus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 14, 'Cum autem convenisset nos in Asson, assumpto eo, venimus Mitylenen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 15, 'Et inde navigantes, sequenti die venimus contra Chium, et alia applicuimus Samum, et sequenti die venimus Miletum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 16, 'Proposuerat enim Paulus transnavigare Ephesum, ne qua mora illi fieret in Asia. Festinabat enim, si possibile sibi esset, ut diem Pentecostes faceret Jerosolymis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 17, 'A Mileto autem mittens Ephesum, vocavit majores natu ecclesiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 18, 'Qui cum venissent ad eum, et simul essent, dixit eis: Vos scitis a prima die qua ingressus sum in Asiam, qualiter vobiscum per omne tempus fuerim,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 19, 'serviens Domino cum omni humilitate, et lacrimis, et tentationibus, quæ mihi acciderunt ex insidiis Judæorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 20, 'quomodo nihil subtraxerim utilium, quominus annuntiarem vobis et docerem vos, publice et per domos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 21, 'testificans Judæis atque gentilibus in Deum pœnitentiam, et fidem in Dominum nostrum Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 22, 'Et nunc ecce alligatus ego spiritu, vado in Jerusalem: quæ in ea ventura sint mihi, ignorans:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 23, 'nisi quod Spiritus Sanctus per omnes civitates mihi protestatur, dicens quoniam vincula et tribulationes Jerosolymis me manent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 24, 'Sed nihil horum vereor: nec facio animam meam pretiosiorem quam me, dummodo consummem cursum meum, et ministerium verbi quod accepi a Domino Jesu, testificari Evangelium gratiæ Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 25, 'Et nunc ecce ego scio quia amplius non videbitis faciem meam vos omnes, per quos transivi prædicans regnum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 26, 'Quapropter contestor vos hodierna die, quia mundus sum a sanguine omnium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 27, 'Non enim subterfugi, quominus annuntiarem omne consilium Dei vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 28, 'Attendite vobis, et universo gregi, in quo vos Spiritus Sanctus posuit episcopos regere ecclesiam Dei, quam acquisivit sanguine suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 29, 'Ego scio quoniam intrabunt post discessionem meam lupi rapaces in vos, non parcentes gregi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 30, 'Et ex vobisipsis exsurgent viri loquentes perversa, ut abducant discipulos post se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 31, 'Propter quod vigilate, memoria retinentes quoniam per triennium nocte et die non cessavi, cum lacrimis monens unumquemque vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 32, 'Et nunc commendo vos Deo, et verbo gratiæ ipsius, qui potens est ædificare, et dare hæreditatem in sanctificatis omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 33, 'Argentum, et aurum, aut vestem nullius concupivi, sicut');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 34, 'ipsi scitis: quoniam ad ea quæ mihi opus erant, et his qui mecum sunt, ministraverunt manus istæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 35, 'Omnia ostendi vobis, quoniam sic laborantes, oportet suscipere infirmos ac meminisse verbi Domini Jesu: quoniam ipse dixit: Beatius est magis dare, quam accipere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 36, 'Et cum hæc dixisset, positis genibus suis oravit cum omnibus illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 37, 'Magnus autem fletus factus est omnium: et procumbentes super collum Pauli, osculabantur eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 20, 38, 'dolentes maxime in verbo quod dixerat, quoniam amplius faciem ejus non essent visuri. Et deducebant eum ad navem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 1, 'Cum autem factum esset ut navigaremus abstracti ab eis, recto cursu venimus Coum, et sequenti die Rhodum, et inde Pataram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 2, 'Et cum invenissemus navem transfretantem in Phœnicen, ascendentes navigavimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 3, 'Cum apparuissemus autem Cypro, relinquentes eam ad sinistram, navigavimus in Syriam, et venimus Tyrum: ibi enim navis expositura erat onus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 4, 'Inventis autem discipulis, mansimus ibi diebus septem: qui Paulo dicebant per Spiritum ne ascenderet Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 5, 'Et expletis diebus, profecti ibamus, deducentibus nos omnibus cum uxoribus et filiis usque foras civitatem: et positis genibus in littore, oravimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 6, 'Et cum valefecissemus invicem, ascendimus navem: illi autem redierunt in sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 7, 'Nos vero navigatione expleta a Tyro descendimus Ptolemaidam: et salutatis fratribus, mansimus die una apud illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 8, 'Alia autem die profecti, venimus Cæsaream. Et intrantes domum Philippi evangelistæ, qui erat unus de septem, mansimus apud eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 9, 'Huic autem erant quatuor filiæ virgines prophetantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 10, 'Et cum moraremur per dies aliquot, supervenit quidam a Judæa propheta, nomine Agabus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 11, 'Is cum venisset ad nos, tulit zonam Pauli: et alligans sibi pedes et manus, dixit: Hæc dicit Spiritus Sanctus: Virum, cujus est zona hæc, sic alligabunt in Jerusalem Judæi, et tradent in manus gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 12, 'Quod cum audissemus, rogabamus nos, et qui loci illius erant, ne ascenderet Jerosolymam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 13, 'Tunc respondit Paulus, et dixit: Quid facitis flentes, et affligentes cor meum? Ego enim non solum alligari, sed et mori in Jerusalem paratus sum propter nomen Domini Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 14, 'Et cum ei suadere non possemus, quievimus, dicentes: Domini voluntas fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 15, 'Post dies autem istos, præparati ascendebamus in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 16, 'Venerunt autem et ex discipulis a Cæsarea nobiscum, adducentes secum apud quem hospitaremur Mnasonem quemdam Cyprium, antiquum discipulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 17, 'Et cum venissemus Jerosolymam, libenter exceperunt nos fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 18, 'Sequenti autem die introibat Paulus nobiscum ad Jacobum, omnesque collecti sunt seniores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 19, 'Quos cum salutasset, narrabat per singula quæ Deus fecisset in gentibus per ministerium ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 20, 'At illi cum audissent, magnificabant Deum, dixeruntque ei: Vides, frater, quot millia sunt in Judæis qui crediderunt, et omnes æmulatores sunt legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 21, 'Audierunt autem de te quia discessionem doceas a Moyse eorum qui per gentes sunt Judæorum, dicens non debere eos circumcidere filios suos, neque secundum consuetudinem ingredi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 22, 'Quid ergo est? utique oportet convenire multitudinem: audient enim te supervenisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 23, 'Hoc ergo fac quod tibi dicimus. Sunt nobis viri quatuor, votum habentes super se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 24, 'His assumptis, sanctifica te cum illis, et impende in illis ut radant capita: et scient omnes quia quæ de te audierunt, falsa sunt, sed ambulas et ipse custodiens legem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 25, 'De his autem qui crediderunt ex gentibus, nos scripsimus judicantes ut abstineant se ab idolis immolato, et sanguine, et suffocato, et fornicatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 26, 'Tunc Paulus, assumptis viris, postera die purificatus cum illis intravit in templum, annuntians expletionem dierum purificationis, donec offerretur pro unoquoque eorum oblatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 27, 'Dum autem septem dies consummarentur, hi qui de Asia erant Judæi, cum vidissent eum in templo, concitaverunt omnem populum, et injecerunt ei manus, clamantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 28, 'Viri Israëlitæ, adjuvate: hic est homo qui adversus populum, et legem, et locum hunc, omnes ubique docens, insuper et gentiles induxit in templum, et violavit sanctum locum istum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 29, 'Viderant enim Trophimum Ephesium in civitate cum ipso, quem æstimaverunt quoniam in templum introduxisset Paulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 30, 'Commotaque est civitas tota, et facta est concursio populi. Et apprehendentes Paulum, trahebant eum extra templum: et statim clausæ sunt januæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 31, 'Quærentibus autem eum occidere, nuntiatum est tribuno cohortis quia tota confunditur Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 32, 'Qui statim, assumptis militibus et centurionibus, decurrit ad illos. Qui cum vidissent tribunum et milites, cessaverunt percutere Paulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 33, 'Tunc accedens tribunus apprehendit eum, et jussit eum alligari catenis duabus: et interrogabat quis esset, et quid fecisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 34, 'Alii autem aliud clamabant in turba. Et cum non posset certum cognoscere præ tumultu, jussit duci eum in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 35, 'Et cum venisset ad gradus, contigit ut portaretur a militibus propter vim populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 36, 'Sequebatur enim multitudo populi, clamans: Tolle eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 37, 'Et cum cœpisset induci in castra Paulus, dicit tribuno: Si licet mihi loqui aliquid ad te? Qui dixit: Græce nosti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 38, 'nonne tu es \'gyptius, qui ante hos dies tumultum concitasti, et eduxisti in desertum quatuor millia virorum sicariorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 39, 'Et dixit ad eum Paulus: Ego homo sum quidem Judæus a Tarso Ciliciæ, non ignotæ civitatis municeps. Rogo autem te, permitte mihi loqui ad populum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 21, 40, 'Et cum ille permisisset, Paulus stans in gradibus annuit manu ad plebem, et magno silentio facto, allocutus est lingua hebræa, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 1, 'Viri fratres, et patres, audite quam ad vos nunc reddo rationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 2, 'Cum audissent autem quia hebræa lingua loqueretur ad illos, magis præstiterunt silentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 3, 'Et dicit: Ego sum vir Judæus, natus in Tarso Ciliciæ, nutritus autem in ista civitate, secus pedes Gamaliel eruditus juxta veritatem paternæ legis, æmulator legis, sicut et vos omnes estis hodie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 4, 'qui hanc viam persecutus sum usque ad mortem, alligans et tradens in custodias viros ac mulieres,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 5, 'sicut princeps sacerdotum mihi testimonium reddit, et omnes majores natu: a quibus et epistolas accipiens, ad fratres Damascum pergebam, ut adducerem inde vinctos in Jerusalem ut punirentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 6, 'Factum est autem, eunte me, et appropinquante Damasco media die, subito de cælo circumfulsit me lux copiosa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 7, 'et decidens in terram, audivi vocem dicentem mihi: Saule, Saule, quid me persequeris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 8, 'Ego autem respondi: Quis es, domine? Dixitque ad me: Ego sum Jesus Nazarenus, quem tu persequeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 9, 'Et qui mecum erant, lumen quidem viderunt, vocem autem non audierunt ejus qui loquebatur mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 10, 'Et dixi: Quid faciam, domine? Dominus autem dixit ad me: Surgens vade Damascum: et ibi tibi dicetur de omnibus quæ te oporteat facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 11, 'Et cum non viderem præ claritate luminis illius, ad manum deductus a comitibus, veni Damascum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 12, 'Ananias autem quidam vir secundum legem, testimonium habens ab omnibus cohabitantibus Judæis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 13, 'veniens ad me et astans, dixit mihi: Saule frater, respice. Et ego eadem hora respexi in eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 14, 'At ille dixit: Deus patrum nostrorum præordinavit te, ut cognosceres voluntatem ejus, et videres justum, et audires vocem ex ore ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 15, 'quia eris testis illius ad omnes homines eorum quæ vidisti et audisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 16, 'Et nunc quid moraris? Exsurge, et baptizare, et ablue peccata tua, invocato nomine ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 17, 'Factum est autem revertenti mihi in Jerusalem, et oranti in templo, fieri me in stupore mentis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 18, 'et videre illum dicentem mihi: Festina, et exi velociter ex Jerusalem: quoniam non recipient testimonium tuum de me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 19, 'Et ego dixi: Domine, ipsi sciunt quia ego eram concludens in carcerem, et cædens per synagogas eos qui credebant in te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 20, 'et cum funderetur sanguis Stephani testis tui, ego astabam, et consentiebam, et custodiebam vestimenta interficientium illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 21, 'Et dixit ad me: Vade, quoniam ego in nationes longe mittam te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 22, 'Audiebant autem eum usque ad hoc verbum, et levaverunt vocem suam, dicentes: Tolle de terra hujusmodi: non enim fas est eum vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 23, 'Vociferantibus autem eis, et projicientibus vestimenta sua, et pulverem jactantibus in aërem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 24, 'jussit tribunus induci eum in castra, et flagellis cædi, et torqueri eum, ut sciret propter quam causam sic acclamarent ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 25, 'Et cum astrinxissent eum loris, dicit astanti sibi centurioni Paulus: Si hominem Romanum et indemnatum licet vobis flagellare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 26, 'Quo audito, centurio accessit ad tribunum, et nuntiavit ei, dicens: Quid acturus es? hic enim homo civis Romanus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 27, 'Accedens autem tribunus, dixit illi: Dic mihi si tu Romanus es? At ille dixit: Etiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 28, 'Et respondit tribunus: Ego multa summa civilitatem hanc consecutus sum. Et Paulus ait: Ego autem et natus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 29, 'Protinus ergo discesserunt ab illo qui eum torturi erant. Tribunus quoque timuit postquam rescivit, quia civis Romanus esset, et quia alligasset eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 22, 30, 'Postera autem die volens scire diligentius qua ex causa accusaretur a Judæis, solvit eum, et jussit sacerdotes convenire, et omne concilium: et producens Paulum, statuit inter illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 1, 'Intendens autem in concilium Paulus, ait: Viri fratres, ego omni conscientia bona conversatus sum ante Deum usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 2, 'Princeps autem sacerdotum Ananias præcepit astantibus sibi percutere os ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 3, 'Tunc Paulus dixit ad eum: Percutiet te Deus, paries dealbate. Et tu sedens judicas me secundum legem, et contra legem jubes me percuti?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 4, 'Et qui astabant dixerunt: Summum sacerdotem Dei maledicis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 5, 'Dixit autem Paulus: Nesciebam, fratres, quia princeps est sacerdotum. Scriptum est enim: Principem populi tui non maledices.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 6, 'Sciens autem Paulus quia una pars esset sadducæorum, et altera pharisæorum, exclamavit in concilio: Viri fratres, ego pharisæus sum, filius pharisæorum: de spe et resurrectione mortuorum ego judicor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 7, 'Et cum hæc dixisset, facta est dissensio inter pharisæos et sadducæos, et soluta est multitudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 8, 'Sadducæi enim dicunt non esse resurrectionem, neque angelum, neque spiritum: pharisæi autem utraque confitentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 9, 'Factus est autem clamor magnus. Et surgentes quidam pharisæorum, pugnabant, dicentes: Nihil mali invenimus in homine isto: quid si spiritus locutus est ei, aut angelus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 10, 'Et cum magna dissensio facta esset, timens tribunus ne discerperetur Paulus ab ipsis, jussit milites descendere, et rapere eum de medio eorum, ac deducere eum in castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 11, 'Sequenti autem nocte assistens ei Dominus, ait: Constans esto: sicut enim testificatus es de me in Jerusalem, sic te oportet et Romæ testificari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 12, 'Facta autem die collegerunt se quidam ex Judæis, et devoverunt, se dicentes neque manducaturos, neque bibituros donec occiderent Paulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 13, 'Erant autem plus quam quadraginta viri qui hanc conjurationem fecerant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 14, 'qui accesserunt ad principes sacerdotum et seniores, et dixerunt: Devotione devovimus nos nihil gustaturos, donec occidamus Paulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 15, 'Nunc ergo vos notum facite tribuno cum concilio, ut producat illum ad vos, tamquam aliquid certius cognituri de eo. Nos vero priusquam appropiet, parati sumus interficere illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 16, 'Quod cum audisset filius sororis Pauli insidias, venit, et intravit in castra, nuntiavitque Paulo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 17, 'Vocans autem Paulus ad se unum ex centurionibus, ait: Adolescentem hunc perduc ad tribunum, habet enim aliquid indicare illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 18, 'Et ille quidem assumens eum duxit ad tribunum, et ait: Vinctus Paulus rogavit me hunc adolescentem perducere ad te, habentem aliquid loqui tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 19, 'Apprehendens autem tribunus manum illius, secessit cum eo seorsum, et interrogavit illum: Quid est quod habes indicare mihi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 20, 'Ille autem dixit: Judæis convenit rogare te ut crastina die producas Paulum in concilium, quasi aliquid certius inquisituri sint de illo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 21, 'tu vero ne credideris illis: insidiantur enim ei ex eis viri amplius quam quadraginta, qui se devoverunt non manducare, neque bibere donec interficiant eum: et nunc parati sunt, exspectantes promissum tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 22, 'Tribunus igitur dimisit adolescentem, præcipiens ne cui loqueretur quoniam hæc nota sibi fecisset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 23, 'Et vocatis duobus centurionibus, dixit illis: Parate milites ducentos ut eant usque Cæsaream, et equites septuaginta, et lancearios ducentos a tertia hora noctis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 24, 'et jumenta præparate ut imponentes Paulum, salvum perducerent ad Felicem præsidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 25, '(Timuit enim ne forte raperent eum Judæi, et occiderent, et ipse postea calumniam sustineret, tamquam accepturus pecuniam.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 26, 'Scribens epistolam continentem hæc: Claudius Lysias optimo præsidi Felici, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 27, 'Virum hunc comprehensum a Judæis, et incipientem interfici ab eis, superveniens cum exercitu eripui, cognito quia Romanus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 28, 'Volensque scire causam quam objiciebant illi, deduxi eum in concilium eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 29, 'Quem inveni accusari de quæstionibus legis ipsorum, nihil vero dignum morte aut vinculis habentem criminis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 30, 'Et cum mihi perlatum esset de insidiis quas paraverant illi, misi eum ad te, denuntians et accusatoribus ut dicant apud te. Vale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 31, 'Milites ergo secundum præceptum sibi assumentes Paulum, duxerunt per noctem in Antipatridem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 32, 'Et postera die dimissis equitibus ut cum eo irent, reversi sunt ad castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 33, 'Qui cum venissent Cæsaream, et tradidissent epistolam præsidi, statuerunt ante illum et Paulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 34, 'Cum legisset autem, et interrogasset de qua provincia esset, et cognoscens quia de Cilicia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 23, 35, 'Audiam te, inquit, cum accusatores tui venerint. Jussitque in prætorio Herodis custodiri eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 1, 'Post quinque autem dies descendit princeps sacerdotum Ananias, cum senioribus quibusdam, et Tertullo quodam oratore, qui adierunt præsidem adversus Paulum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 2, 'Et citato Paulo cœpit accusare Tertullus, dicens: Cum in multa pace agamus per te, et multa corrigantur per tuam providentiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 3, 'semper et ubique suscipimus, optime Felix, cum omni gratiarum actione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 4, 'Ne diutius autem te protraham, oro, breviter audias nos pro tua clementia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 5, 'Invenimus hunc hominem pestiferum, et concitantem seditiones omnibus Judæis in universo orbe, et auctorem seditionis sectæ Nazarenorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 6, 'qui etiam templum violare conatus est, quem et apprehensum voluimus secundum legem nostram judicare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 7, 'Superveniens autem tribunus Lysias, cum vi magna eripuit eum de manibus nostris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 8, 'jubens accusatores ejus ad te venire: a quo poteris ipse judicans, de omnibus istis cognoscere, de quibus nos accusamus eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 9, 'Adjecerunt autem et Judæi, dicentes hæc ita se habere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 10, 'Respondit autem Paulus (annuente sibi præside dicere): Ex multis annis te esse judicem genti huic sciens, bono animo pro me satisfaciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 11, 'Potes enim cognoscere quia non plus sunt mihi dies quam duodecim, ex quo ascendi adorare in Jerusalem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 12, 'et neque in templo invenerunt me cum aliquo disputantem, aut concursum facientem turbæ, neque in synagogis, neque in civitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 13, 'neque probare possunt tibi de quibus nunc me accusant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 14, 'Confiteor autem hoc tibi, quod secundum sectam quam dicunt hæresim, sic deservio Patri et Deo meo, credens omnibus quæ in lege et prophetis scripta sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 15, 'spem habens in Deum, quam et hi ipsi exspectant, resurrectionem futuram justorum et iniquorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 16, 'In hoc et ipse studeo sine offendiculo conscientiam habere ad Deum et ad homines semper.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 17, 'Post annos autem plures eleemosynas facturus in gentem meam, veni, et oblationes, et vota,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 18, 'in quibus invenerunt me purificatum in templo: non cum turba, neque cum tumultu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 19, 'Quidam autem ex Asia Judæi, quos oportebat apud te præsto esse, et accusare si quid haberent adversum me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 20, 'aut hi ipsi dicant si quid invenerunt in me iniquitatis cum stem in concilio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 21, 'nisi de una hac solummodo voce qua clamavi inter eos stans: Quoniam de resurrectione mortuorum ego judicor hodie a vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 22, 'Distulit autem illos Felix, certissime sciens de via hac, dicens: Cum tribunus Lysias descenderit, audiam vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 23, 'Jussitque centurioni custodire eum, et habere requiem, nec quemquam de suis prohibere ministrare ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 24, 'Post aliquot autem dies veniens Felix cum Drusilla uxore sua, quæ erat Judæa, vocavit Paulum, et audivit ab eo fidem quæ est in Christum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 25, 'Disputante autem illo de justitia, et castitate, et de judicio futuro, tremefactus Felix, respondit: Quod nunc attinet, vade: tempore autem opportuno accersam te:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 26, 'simul et sperans quod pecunia ei daretur a Paulo, propter quod et frequenter accersens eum, loquebatur cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 24, 27, 'Biennio autem expleto, accepit successorem Felix Portium Festum. Volens autem gratiam præstare Judæis Felix, reliquit Paulum vinctum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 1, 'Festus ergo cum venisset in provinciam, post triduum ascendit Jerosolymam a Cæsarea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 2, 'Adieruntque eum principes sacerdotum et primi Judæorum adversus Paulum: et rogabant eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 3, 'postulantes gratiam adversus eum, ut juberet perduci eum in Jerusalem, insidias tendentes ut interficerent eum in via.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 4, 'Festus autem respondit servari Paulum in Cæsarea: se autem maturius profecturum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 5, 'Qui ergo in vobis, ait, potentes sunt, descendentes simul, si quod est in viro crimen, accusent eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 6, 'Demoratus autem inter eos dies non amplius quam octo aut decem, descendit Cæsaream, et altera die sedit pro tribunali, et jussit Paulum adduci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 7, 'Qui cum perductus esset, circumsteterunt eum, qui ab Jerosolyma descenderant Judæi, multas et graves causas objicientes, quas non poterant probare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 8, 'Paulo rationem reddente: Quoniam neque in legem Judæorum, neque in templum, neque in Cæsarem quidquam peccavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 9, 'Festus autem volens gratiam præstare Judæis, respondens Paulo, dixit: Vis Jerosolymam ascendere, et ibi de his judicari apud me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 10, 'Dixit autem Paulus: Ad tribunal Cæsaris sto: ibi me oportet judicari: Judæis non nocui, sicut tu melius nosti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 11, 'Si enim nocui, aut dignum morte aliquid feci, non recuso mori: si vero nihil est eorum quæ hi accusant me, nemo potest me illis donare. Cæsarem appello.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 12, 'Tunc Festus cum concilio locutus, respondit: Cæsarem appellasti? ad Cæsarem ibis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 13, 'Et cum dies aliquot transacti essent, Agrippa rex et Bernice descenderunt Cæsaream ad salutandum Festum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 14, 'Et cum dies plures ibi demorarentur, Festus regi indicavit de Paulo, dicens: Vir quidam est derelictus a Felice vinctus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 15, 'de quo cum essem Jerosolymis, adierunt me principes sacerdotum et seniores Judæorum, postulantes adversus illum damnationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 16, 'Ad quos respondi: Quia non est Romanis consuetudo damnare aliquem hominem priusquam is qui accusatur præsentes habeat accusatores, locumque defendendi accipiat ad abluenda crimina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 17, 'Cum ergo huc convenissent sine ulla dilatione, sequenti die sedens pro tribunali, jussi adduci virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 18, 'De quo, cum stetissent accusatores, nullam causam deferebant, de quibus ego suspicabar malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 19, 'Quæstiones vero quasdam de sua superstitione habebant adversus eum, et de quodam Jesu defuncto, quem affirmabat Paulus vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 20, 'Hæsitans autem ego de hujusmodi quæstione, dicebam si vellet ire Jerosolymam, et ibi judicari de istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 21, 'Paulo autem appellante ut servaretur ad Augusti cognitionem, jussi servari eum, donec mittam eum ad Cæsarem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 22, 'Agrippa autem dixit ad Festum: Volebam et ipse hominem audire. Cras, inquit, audies eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 23, 'Altera autem die cum venisset Agrippa et Bernice cum multa ambitione, et introissent in auditorium cum tribunis et viris principalibus civitatis, jubente Festo, adductus est Paulus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 24, 'Et dicit Festus: Agrippa rex, et omnes qui simul adestis nobiscum viri, videtis hunc de quo omnis multitudo Judæorum interpellavit me Jerosolymis, petentes et acclamantes non oportere eum vivere amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 25, 'Ego vere comperi nihil dignum morte eum admisisse. Ipso autem hoc appellante ad Augustum, judicavi mittere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 26, 'De quo quid certum scribam domino, non habeo. Propter quod produxi eum ad vos, et maxime ad te, rex Agrippa, ut interrogatione facta habeam quid scribam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 25, 27, 'Sine ratione enim mihi videtur mittere vinctum, et causas ejus non significare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 1, 'Agrippa vero ad Paulum ait: Permittitur tibi loqui pro temetipso. Tunc Paulus extenta manu cœpit rationem reddere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 2, 'De omnibus quibus accusor a Judæis, rex Agrippa, æstimo me beatum apud te cum sim defensurus me hodie,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 3, 'maxime te sciente omnia, et quæ apud Judæos sunt consuetudines et quæstiones: propter quod obsecro patienter me audias.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 4, 'Et quidem vitam meam a juventute, quæ ab initio fuit in gente mea in Jerosolymis, noverunt omnes Judæi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 5, 'præscientes me ab initio (si velint testimonium perhibere) quoniam secundum certissimam sectam nostræ religionis vixi pharisæus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 6, 'Et nunc, in spe quæ ad patres nostros repromissionis facta est a Deo, sto judicio subjectus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 7, 'in quam duodecim tribus nostræ nocte ac die deservientes, sperant devenire. De qua spe accusor a Judæis, rex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 8, 'Quid incredibile judicatur apud vos, si Deus mortuos suscitat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 9, 'Et ego quidem existimaveram me adversus nomen Jesu Nazareni debere multa contraria agere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 10, 'quod et feci Jerosolymis, et multos sanctorum ego in carceribus inclusi, a principibus sacerdotum potestate accepta: et cum occiderentur, detuli sententiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 11, 'Et per omnes synagogas frequenter puniens eos, compellebam blasphemare: et amplius insaniens in eos, persequebar usque in exteras civitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 12, 'In quibus dum irem Damascum cum potestate et permissu principum sacerdotum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 13, 'die media in via vidi, rex, de cælo supra splendorem solis circumfulsisse me lumen, et eos qui mecum simul erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 14, 'Omnesque nos cum decidissemus in terram, audivi vocem loquentem mihi hebraica lingua: Saule, Saule, quid me persequeris? durum est tibi contra stimulum calcitrare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 15, 'Ego autem dixi: Quis es, domine? Dominus autem dixit: Ego sum Jesus, quem tu persequeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 16, 'Sed exsurge, et sta super pedes tuos: ad hoc enim apparui tibi, ut constituam te ministrum, et testem eorum quæ vidisti, et eorum quibus apparebo tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 17, 'eripiens te de populo et gentibus, in quas nunc ego mitto te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 18, 'aperire oculos eorum, ut convertantur a tenebris ad lucem, et de potestate Satanæ ad Deum, ut accipiant remissionem peccatorum, et sortem inter sanctos, per fidem quæ est in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 19, 'Unde, rex Agrippa, non fui incredulus cælesti visioni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 20, 'sed his qui sunt Damasci primum, et Jerosolymis, et in omnem regionem Judææ, et gentibus, annuntiabam, ut pœnitentiam agerent, et converterentur ad Deum, digna pœnitentiæ opera facientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 21, 'Hac ex causa me Judæi, cum essem in templo, comprehensum tentabant interficere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 22, 'Auxilio autem adjutus Dei usque in hodiernum diem, sto, testificans minori atque majori, nihil extra dicens quam ea quæ prophetæ locuti sunt futura esse, et Moyses,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 23, 'si passibilis Christus, si primus ex resurrectione mortuorum, lumen annuntiaturus est populo et gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 24, 'Hæc loquente eo, et rationem reddente, Festus magna voce dixit: Insanis, Paule: multæ te litteræ ad insaniam convertunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 25, 'Et Paulus: Non insanio, inquit, optime Feste, sed veritatis et sobrietatis verba loquor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 26, 'Scit enim de his rex, ad quem et constanter loquor: latere enim eum nihil horum arbitror. Neque enim in angulo quidquam horum gestum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 27, 'Credis, rex Agrippa, prophetis? Scio quia credis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 28, 'Agrippa autem ad Paulum: In modico suades me christianum fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 29, 'Et Paulus: Opto apud Deum, et in modico et in magno, non tantum te, sed etiam omnes qui audiunt hodie fieri tales, qualis et ego sum, exceptis vinculis his.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 30, 'Et exsurrexit rex, et præses, et Bernice, et qui assidebant eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 31, 'Et cum secessissent, loquebantur ad invicem, dicentes: Quia nihil morte aut vinculis dignum quid fecit homo iste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 26, 32, 'Agrippa autem Festo dixit: Dimitti poterat homo hic, si non appellasset Cæsarem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 1, 'Ut autem judicatum est navigare eum in Italiam, et tradi Paulum cum reliquis custodiis centurioni nomine Julio cohortis Augustæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 2, 'ascendentes navem Adrumetinam, incipientes navigare circa Asiæ loca, sustulimus, perseverante nobiscum Aristarcho Macedone Thessalonicensi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 3, 'Sequenti autem die devenimus Sidonem. Humane autem tractans Julius Paulum, permisit ad amicos ire, et curam sui agere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 4, 'Et inde cum sustulissemus, subnavigavimus Cyprum, propterea quod essent venti contrarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 5, 'Et pelagus Ciliciæ et Pamphyliæ navigantes, venimus Lystram, quæ est Lyciæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 6, 'et ibi inveniens centurio navem Alexandrinam navigantem in Italiam, transposuit nos in eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 7, 'Et cum multis diebus tarde navigaremus, et vix devenissemus contra Gnidum, prohibente nos vento, adnavigavimus Cretæ juxta Salmonem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 8, 'et vix juxta navigantes, venimus in locum quemdam qui vocatur Boniportus, cui juxta erat civitas Thalassa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 9, 'Multo autem tempore peracto, et cum jam non esset tuta navigatio eo quod et jejunium jam præteriisset, consolabatur eos Paulus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 10, 'dicens eis: Viri, video quoniam cum injuria et multo damno non solum oneris, et navis, sed etiam animarum nostrarum incipit esse navigatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 11, 'Centurio autem gubernatori et nauclero magis credebat, quam his quæ a Paulo dicebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 12, 'Et cum aptus portus non esset ad hiemandum, plurimi statuerunt consilium navigare inde, si quomodo possent, devenientes Phœnicen hiemare, portum Cretæ respicientem ad Africum et ad Corum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 13, 'Aspirante autem austro, æstimantes propositum se tenere, cum sustulissent de Asson, legebant Cretam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 14, 'Non post multum autem misit se contra ipsam ventus typhonicus, qui vocatur Euroaquilo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 15, 'Cumque arrepta esset navis, et non posset conari in ventum, data nave flatibus, ferebamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 16, 'In insulam autem quamdam decurrentes, quæ vocatur Cauda, potuimus vix obtinere scapham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 17, 'Qua sublata, adjutoriis utebantur, accingentes navem, timentes ne in Syrtim inciderent, summisso vase sic ferebantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 18, 'Valida autem nobis tempestate jactatis, sequenti die jactum fecerunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 19, 'et tertia die suis manibus armamenta navis projecerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 20, 'Neque autem sole, neque sideribus apparentibus per plures dies, et tempestate non exigua imminente, jam ablata erat spes omnis salutis nostræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 21, 'Et cum multa jejunatio fuisset, tunc stans Paulus in medio eorum, dixit: Oportebat quidem, o viri, audito me, non tollere a Creta, lucrique facere injuriam hanc et jacturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 22, 'Et nunc suadeo vobis bono animo esse: amissio enim nullius animæ erit ex vobis, præterquam navis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 23, 'Astitit enim mihi hac nocte angelus Dei, cujus sum ego, et cui deservio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 24, 'dicens: Ne timeas, Paule: Cæsari te oportet assistere: et ecce donavit tibi Deus omnes qui navigant tecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 25, 'Propter quod bono animo estote, viri: credo enim Deo quia sic erit, quemadmodum dictum est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 26, 'In insulam autem quamdam oportet nos devenire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 27, 'Sed posteaquam quartadecima nox supervenit, navigantibus nobis in Adria circa mediam noctem, suspicabantur nautæ apparere sibi aliquam regionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 28, 'Qui et summittentes bolidem, invenerunt passus viginti: et pusillum inde separati, invenerunt passus quindecim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 29, 'Timentes autem ne in aspera loca incideremus, de puppi mittentes anchoras quatuor, optabant diem fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 30, 'Nautis vero quærentibus fugere de navi, cum misissent scapham in mare, sub obtentu quasi inciperent a prora anchoras extendere,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 31, 'dixit Paulus centurioni et militibus: Nisi hi in navi manserint, vos salvi fieri non potestis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 32, 'Tunc absciderunt milites funes scaphæ, et passi sunt eam excidere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 33, 'Et cum lux inciperet fieri, rogabat Paulus omnes sumere cibum, dicens: Quartadecima die hodie exspectantes jejuni permanetis, nihil accipientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 34, 'Propter quod rogo vos accipere cibum pro salute vestra: quia nullius vestrum capillus de capite peribit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 35, 'Et cum hæc dixisset, sumens panem, gratias egit Deo in conspectu omnium: et cum fregisset, cœpit manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 36, 'Animæquiores autem facti omnes, et ipsi sumpserunt cibum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 37, 'Eramus vero universæ animæ in navi ducentæ septuaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 38, 'Et satiati cibo alleviabant navem, jactantes triticum in mare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 39, 'Cum autem dies factus esset, terram non agnoscebant: sinum vero quemdam considerabant habentem littus, in quem cogitabant si possent ejicere navem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 40, 'Et cum anchoras sustulissent, committebant se mari, simul laxantes juncturas gubernaculorum: et levato artemone secundum auræ flatum, tendebant ad littus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 41, 'Et cum incidissemus in locum dithalassum, impegerunt navem: et prora quidem fixa manebat immobilis, puppis vero solvebatur a vi maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 42, 'Militum autem consilium fuit ut custodias occiderent, ne quis cum enatasset, effugeret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 43, 'Centurio autem volens servare Paulum, prohibuit fieri: jussitque eos qui possent natare, emittere se primos, et evadere, et ad terram exire:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 27, 44, 'et ceteros, alios in tabulis ferebant, quosdam super ea quæ de navi erant. Et sic factum est, ut omnes animæ evaderent ad terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 1, 'Et cum evasissemus, tunc cognovimus quia Melita insula vocabatur. Barbari vero præstabant non modicam humanitatem nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 2, 'Accensa enim pyra, reficiebant nos omnes propter imbrem qui imminebat, et frigus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 3, 'Cum congregasset autem Paulus sarmentorum aliquantam multitudinem, et imposuisset super ignem, vipera a calore cum processisset, invasit manum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 4, 'Ut vero viderunt barbari pendentem bestiam de manu ejus, ad invicem dicebant: Utique homicida est homo hic, qui cum evaserit de mari, ultio non sinit eum vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 5, 'Et ille quidem excutiens bestiam in ignem, nihil mali passus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 6, 'At illi existimabant eum in tumorem convertendum, et subito casurum et mori. Diu autem illis exspectantibus, et videntibus nihil mali in eo fieri, convertentes se, dicebant eum esse deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 7, 'In locis autem illis erant prædia principis insulæ, nomine Publii, qui nos suscipiens, triduo benigne exhibuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 8, 'Contigit autem patrem Publii febribus et dysenteria vexatum jacere. Ad quem Paulus intravit: et cum orasset, et imposuisset ei manus, salvavit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 9, 'Quo facto, omnes qui in insula habebant infirmitates, accedebant, et curabantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 10, 'qui etiam multis honoribus nos honoraverunt, et navigantibus imposuerunt quæ necessaria erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 11, 'Post menses autem tres navigavimus in navi Alexandrina, quæ in insula hiemaverat, cui erat insigne Castorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 12, 'Et cum venissemus Syracusam, mansimus ibi triduo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 13, 'Inde circumlegentes devenimus Rhegium: et post unum diem, flante austro, secunda die venimus Puteolos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 14, 'ubi inventis fratribus rogati sumus manere apud eos dies septem: et sic venimus Romam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 15, 'Et inde cum audissent fratres, occurrerunt nobis usque ad Appii forum, ac tres Tabernas. Quos cum vidisset Paulus, gratias agens Deo, accepit fiduciam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 16, 'Cum autem venissemus Romam, permissum est Paulo manere sibimet cum custodiente se milite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 17, 'Post tertium autem diem convocavit primos Judæorum. Cumque convenissent, dicebat eis: Ego, viri fratres, nihil adversus plebem faciens, aut morem paternum, vinctus ab Jerosolymis traditus sum in manus Romanorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 18, 'qui cum interrogationem de me habuissent, voluerunt me dimittere, eo quod nulla esset causa mortis in me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 19, 'Contradicentibus autem Judæis, coactus sum appellare Cæsarem, non quasi gentem meam habens aliquid accusare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 20, 'Propter hanc igitur causam rogavi vos videre, et alloqui. Propter spem enim Israël catena hac circumdatus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 21, 'At illi dixerunt ad eum: Nos neque litteras accepimus de te a Judæa, neque adveniens aliquis fratrum nuntiavit, aut locutus est quid de te malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 22, 'Rogamus autem a te audire quæ sentis: nam de secta hac notum est nobis quia ubique ei contradicitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 23, 'Cum constituissent autem illi diem, venerunt ad eum in hospitium plurimi, quibus exponebat testificans regnum Dei, suadensque eis de Jesu ex lege Moysi et prophetis a mane usque ad vesperam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 24, 'Et quidam credebant his quæ dicebantur: quidam vero non credebant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 25, 'Cumque invicem non essent consentientes, discedebant, dicente Paulo unum verbum: Quia bene Spiritus Sanctus locutus est per Isaiam prophetam ad patres nostros,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 26, 'dicens: Vade ad populum istum, et dic ad eos: Aure audietis, et non intelligetis, et videntes videbitis, et non perspicietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 27, 'Incrassatum est enim cor populi hujus, et auribus graviter audierunt, et oculos suos compresserunt: ne forte videant oculis, et auribus audiant, et corde intelligant, et convertantur, et sanem eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 28, 'Notum ergo sit vobis, quoniam gentibus missum est hoc salutare Dei, et ipsi audient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 29, 'Et cum hæc dixisset, exierunt ab eo Judæi, multam habentes inter se quæstionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 30, 'Mansit autem biennio toto in suo conducto: et suscipiebat omnes qui ingrediebantur ad eum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 28, 31, 'prædicans regnum Dei, et docens quæ sunt de Domino Jesu Christo cum omni fiducia, sine prohibitione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus, servus Jesu Christi, vocatus Apostolus, segregatus in Evangelium Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'quod ante promiserat per prophetas suos in Scripturis sanctis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'de Filio suo, qui factus est ei ex semine David secundum carnem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'qui prædestinatus est Filius Dei in virtute secundum spiritum sanctificationis ex resurrectione mortuorum Jesu Christi Domini nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'per quem accepimus gratiam, et apostolatum ad obediendum fidei in omnibus gentibus pro nomine ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'in quibus estis et vos vocati Jesu Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'omnibus qui sunt Romæ, dilectis Dei, vocatis sanctis. Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Primum quidem gratias ago Deo meo per Jesum Christum pro omnibus vobis: quia fides vestra annuntiatur in universo mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Testis enim mihi est Deus, cui servio in spiritu meo in Evangelio Filii ejus, quod sine intermissione memoriam vestri facio');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'semper in orationibus meis: obsecrans, si quomodo tandem aliquando prosperum iter habeam in voluntate Dei veniendi ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Desidero enim videre vos, ut aliquid impertiar vobis gratiæ spiritualis ad confirmandos vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'id est, simul consolari in vobis per eam quæ invicem est, fidem vestram atque meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'Nolo autem vos ignorare fratres: quia sæpe proposui venire ad vos (et prohibitus sum usque adhuc) ut aliquem fructum habeam et in vobis, sicut et in ceteris gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Græcis ac barbaris, sapientibus, et insipientibus debitor sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, 'ita (quod in me) promptum est et vobis, qui Romæ estis, evangelizare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 16, 'Non enim erubesco Evangelium. Virtus enim Dei est in salutem omni credenti, Judæo primum, et Græco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 17, 'Justitia enim Dei in eo revelatur ex fide in fidem: sicut scriptum est: Justus autem ex fide vivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 18, 'Revelatur enim ira Dei de cælo super omnem impietatem, et injustitiam hominum eorum, qui veritatem Dei in injustitia detinent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 19, 'quia quod notum est Dei, manifestum est in illis. Deus enim illis manifestavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 20, 'Invisibilia enim ipsius, a creatura mundi, per ea quæ facta sunt, intellecta, conspiciuntur: sempiterna quoque ejus virtus, et divinitas: ita ut sint inexcusabiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 21, 'Quia cum cognovissent Deum, non sicut Deum glorificaverunt, aut gratias egerunt: sed evanuerunt in cogitationibus suis, et obscuratum est insipiens cor eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 22, 'dicentes enim se esse sapientes, stulti facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 23, 'Et mutaverunt gloriam incorruptibilis Dei in similitudinem imaginis corruptibilis hominis, et volucrum, et quadrupedum, et serpentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 24, 'Propter quod tradidit illos Deus in desideria cordis eorum, in immunditiam, ut contumeliis afficiant corpora sua in semetipsis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 25, 'qui commutaverunt veritatem Dei in mendacium: et coluerunt, et servierunt creaturæ potius quam Creatori, qui est benedictus in sæcula. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 26, 'Propterea tradidit illos Deus in passiones ignominiæ: nam feminæ eorum immutaverunt naturalem usum in eum usum qui est contra naturam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 27, 'Similiter autem et masculi, relicto naturali usu feminæ, exarserunt in desideriis suis in invicem, masculi in masculos turpitudinem operantes, et mercedem, quam oportuit, erroris sui in semetipsis recipientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 28, 'Et sicut non probaverunt Deum habere in notitia, tradidit illos Deus in reprobum sensum, ut faciant ea quæ non conveniunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 29, 'repletos omni iniquitate, malitia, fornicatione, avaritia, nequitia, plenos invidia, homicidio, contentione, dolo, malignitate: susurrones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 30, 'detractores, Deo odibiles, contumeliosos, superbos, elatos, inventores malorum, parentibus non obedientes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 31, 'insipientes, incompositos, sine affectione, absque fœdere, sine misericordia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 32, 'Qui cum justitiam Dei cognovissent, non intellexerunt quoniam qui talia agunt, digni sunt morte: et non solum qui ea faciunt, sed etiam qui consentiunt facientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Propter quod inexcusabilis es, o homo omnis qui judicas. In quo enim judicas alterum, teipsum condemnas: eadem enim agis quæ judicas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Scimus enim quoniam judicium Dei est secundum veritatem in eos qui talia agunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Existimas autem hoc, o homo, qui judicas eos qui talia agunt, et facis ea, quia tu effugies judicium Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'an divitias bonitatis ejus, et patientiæ, et longanimitatis contemnis? ignoras quoniam benignitas Dei ad pœnitentiam te adducit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Secundum autem duritiam tuam, et impœnitens cor, thesaurizas tibi iram in die iræ, et revelationis justi judicii Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'qui reddet unicuique secundum opera ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'iis quidem qui secundum patientiam boni operis, gloriam, et honorem, et incorruptionem quærunt, vitam æternam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'iis autem qui sunt ex contentione, et qui non acquiescunt veritati, credunt autem iniquitati, ira et indignatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Tribulatio et angustia in omnem animam hominis operantis malum, Judæi primum, et Græci:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'gloria autem, et honor, et pax omni operanti bonum, Judæo primum, et Græco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'non enim est acceptio personarum apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Quicumque enim sine lege peccaverunt, sine lege peribunt: et quicumque in lege peccaverunt, per legem judicabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Non enim auditores legis justi sunt apud Deum, sed factores legis justificabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Cum autem gentes, quæ legem non habent, naturaliter ea, quæ legis sunt, faciunt, ejusmodi legem non habentes, ipsi sibi sunt lex:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'qui ostendunt opus legis scriptum in cordibus suis, testimonium reddente illis conscientia ipsorum, et inter se invicem cogitationibus accusantibus, aut etiam defendentibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'in die, cum judicabit Deus occulta hominum, secundum Evangelium meum per Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Si autem tu Judæus cognominaris, et requiescis in lege, et gloriaris in Deo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'et nosti voluntatem ejus, et probas utiliora, instructus per legem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'confidis teipsum esse ducem cæcorum, lumen eorum qui in tenebris sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'eruditorem insipientium, magistrum infantium, habentem formam scientiæ, et veritatis in lege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 21, 'Qui ergo alium doces, teipsum non doces: qui prædicas non furandum, furaris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 22, 'qui dicis non mœchandum, mœcharis: qui abominaris idola, sacrilegium facis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 23, 'qui in lege gloriaris, per prævaricationem legis Deum inhonoras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 24, '(Nomen enim Dei per vos blasphematur inter gentes, sicut scriptum est.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 25, 'Circumcisio quidem prodest, si legem observes: si autem prævaricator legis sis, circumcisio tua præputium facta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 26, 'Si igitur præputium justitias legis custodiat, nonne præputium illius in circumcisionem reputabitur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 27, 'et judicabit id quod ex natura est præputium, legem consummans, te, qui per litteram et circumcisionem prævaricator legis es?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 28, 'Non enim qui in manifesto, Judæus est: neque quæ in manifesto, in carne, est circumcisio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 29, 'sed qui in abscondito, Judæus est: et circumcisio cordis in spiritu, non littera: cujus laus non ex hominibus, sed ex Deo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Quid ergo amplius Judæo est? aut quæ utilitas circumcisionis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Multum per omnem modum. Primum quidem quia credita sunt illis eloquia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Quid enim si quidam illorum non crediderunt? numquid incredulitas illorum fidem Dei evacuabit? Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Est autem Deus verax: omnis autem homo mendax, sicut scriptum est: Ut justificeris in sermonibus tuis: et vincas cum judicaris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Si autem iniquitas nostra justitiam Dei commendat, quid dicemus? Numquid iniquus est Deus, qui infert iram?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'secundum hominem dico. Absit. Alioquin quomodo judicabit Deus hunc mundum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Si enim veritas Dei in meo mendacio abundavit in gloriam ipsius: quid adhuc et ego tamquam peccator judicor?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'et non (sicut blasphemamur, et sicut aiunt quidam nos dicere) faciamus mala ut veniant bona: quorum damnatio justa est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Quid ergo? præcellimus eos? Nequaquam. Causati enim sumus Judæos et Græcos omnes sub peccato esse,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'sicut scriptum est: Quia non est justus quisquam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'non est intelligens, non est requirens Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Omnes declinaverunt, simul inutiles facti sunt: non est qui faciat bonum, non est usque ad unum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Sepulchrum patens est guttur eorum, linguis suis dolose agebant: venenum aspidum sub labiis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 14, 'quorum os maledictione, et amaritudine plenum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 15, 'veloces pedes eorum ad effundendum sanguinem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 16, 'contritio et infelicitas in viis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 17, 'et viam pacis non cognoverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 18, 'non est timor Dei ante oculos eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 19, 'Scimus autem quoniam quæcumque lex loquitur, iis, qui in lege sunt, loquitur: ut omne os obstruatur, et subditus fiat omnis mundus Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 20, 'quia ex operibus legis non justificabitur omnis caro coram illo. Per legem enim cognitio peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 21, 'Nunc autem sine lege justitia Dei manifestata est: testificata a lege et prophetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 22, 'Justitia autem Dei per fidem Jesu Christi in omnes et super omnes qui credunt in eum: non enim est distinctio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 23, 'omnes enim peccaverunt, et egent gloria Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 24, 'Justificati gratis per gratiam ipsius, per redemptionem quæ est in Christo Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 25, 'quem proposuit Deus propitiationem per fidem in sanguine ipsius, ad ostensionem justitiæ suæ propter remissionem præcedentium delictorum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 26, 'in sustentatione Dei, ad ostensionem justitiæ ejus in hoc tempore: ut sit ipse justus, et justificans eum, qui est ex fide Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 27, 'Ubi est ergo gloriatio tua? Exclusa est. Per quam legem? Factorum? Non: sed per legem fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 28, 'Arbitramur enim justificari hominem per fidem sine operibus legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 29, 'An Judæorum Deus tantum? nonne et gentium? Immo et gentium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 30, 'quoniam quidem unus est Deus, qui justificat circumcisionem ex fide, et præputium per fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 31, 'Legem ergo destruimus per fidem? Absit: sed legem statuimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Quid ergo dicemus invenisse Abraham patrem nostrum secundum carnem?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Si enim Abraham ex operibus justificatus est, habet gloriam, sed non apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Quid enim dicit Scriptura? Credidit Abraham Deo, et reputatum est illi ad justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Ei autem qui operatur, merces non imputatur secundum gratiam, sed secundum debitum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Ei vero qui non operatur, credenti autem in eum, qui justificat impium, reputatur fides ejus ad justitiam secundum propositum gratiæ Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Sicut et David dicit beatitudinem hominis, cui Deus accepto fert justitiam sine operibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Beati, quorum remissæ sunt iniquitates, et quorum tecta sunt peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Beatus vir, cui non imputavit Dominus peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Beatitudo ergo hæc in circumcisione tantum manet, an etiam in præputio? Dicimus enim quia reputata est Abrahæ fides ad justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Quomodo ergo reputata est? in circumcisione, an in præputio? Non in circumcisione, sed in præputio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Et signum accepit circumcisionis, signaculum justitiæ fidei, quæ est in præputio: ut sit pater omnium credentium per præputium, ut reputetur et illis ad justitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'et sit pater circumcisionis non iis tantum, qui sunt ex circumcisione, sed et iis qui sectantur vestigia fidei, quæ est in præputio patris nostri Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Non enim per legem promissio Abrahæ, aut semini ejus ut hæres esset mundi: sed per justitiam fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Si enim qui ex lege, hæredes sunt: exinanita est fides, abolita est promissio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Lex enim iram operatur. Ubi enim non est lex, nec prævaricatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Ideo ex fide, ut secundum gratiam firma sit promissio omni semini, non ei qui ex lege est solum, sed et ei qui ex fide est Abrahæ, qui pater est omnium nostrum');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, '(sicut scriptum est: Quia patrem multarum gentium posui te) ante Deum, cui credidit, qui vivificat mortuos, et vocat ea quæ non sunt, tamquam ea quæ sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'qui contra spem in spem credidit, ut fieret pater multarum gentium secundum quod dictum est ei: Sic erit semen tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 19, 'Et non infirmatus est fide, nec consideravit corpus suum emortuum, cum jam fere centum esset annorum, et emortuam vulvam Saræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 20, 'In repromissione etiam Dei non hæsitavit diffidentia, sed confortatus est fide, dans gloriam Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 21, 'plenissime sciens, quia quæcumque promisit, potens est et facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 22, 'Ideo et reputatum est illi ad justitiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 23, 'Non est autem scriptum tantum propter ipsum quia reputatum est illi ad justitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 24, 'sed et propter nos, quibus reputabitur credentibus in eum, qui suscitavit Jesum Christum Dominum nostrum a mortuis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 25, 'qui traditus est propter delicta nostra, et resurrexit propter justificationem nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Justificati ergo ex fide, pacem habeamus ad Deum per Dominum nostrum Jesum Christum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'per quem et habemus accessum per fidem in gratiam istam, in qua stamus, et gloriamur in spe gloriæ filiorum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Non solum autem, sed et gloriamur in tribulationibus: scientes quod tribulatio patientiam operatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'patientia autem probationem, probatio vero spem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'spes autem non confundit: quia caritas Dei diffusa est in cordibus nostris per Spiritum Sanctum, qui datus est nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ut quid enim Christus, cum adhuc infirmi essemus, secundum tempus, pro impiis mortuus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'vix enim pro justo quis moritur: nam pro bono forsitan quis audeat mori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Commendat autem caritatem suam Deus in nobis: quoniam cum adhuc peccatores essemus, secundum tempus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Christus pro nobis mortuus est: multo igitur magis nunc justificati in sanguine ipsius, salvi erimus ab ira per ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Si enim cum inimici essemus, reconciliati sumus Deo per mortem filii ejus: multo magis reconciliati, salvi erimus in vita ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Non solum autem: sed et gloriamur in Deo per Dominum nostrum Jesum Christum, per quem nunc reconciliationem accepimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Propterea sicut per unum hominem peccatum in hunc mundum intravit, et per peccatum mors, et ita in omnes homines mors pertransiit, in quo omnes peccaverunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Usque ad legem enim peccatum erat in mundo: peccatum autem non imputabatur, cum lex non esset.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Sed regnavit mors ab Adam usque ad Moysen etiam in eos qui non peccaverunt in similitudinem prævaricationis Adæ, qui est forma futuri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Sed non sicut delictum, ita et donum: si enim unius delicto multi mortui sunt: multo magis gratia Dei et donum in gratia unius hominis Jesu Christi in plures abundavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Et non sicut per unum peccatum, ita et donum. Nam judicium quidem ex uno in condemnationem: gratia autem ex multis delictis in justificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Si enim unius delicto mors regnavit per unum: multo magis abundantiam gratiæ, et donationis, et justitiæ accipientes, in vita regnabunt per unum Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Igitur sicut per unius delictum in omnes homines in condemnationem: sic et per unius justitiam in omnes homines in justificationem vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Sicut enim per inobedientiam unius hominis, peccatores constituti sunt multi: ita et per unius obeditionem, justi constituentur multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Lex autem subintravit ut abundaret delictum. Ubi autem abundavit delictum, superabundavit gratia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'ut sicut regnavit peccatum in mortem: ita et gratia regnet per justitiam in vitam æternam, per Jesum Christum Dominum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 1, 'Quid ergo dicemus? permanebimus in peccato ut gratia abundet?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 2, 'Absit. Qui enim mortui sumus peccato, quomodo adhuc vivemus in illo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 3, 'an ignoratis quia quicumque baptizati sumus in Christo Jesu, in morte ipsius baptizati sumus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 4, 'Consepulti enim sumus cum illo per baptismum in mortem: ut quomodo Christus surrexit a mortuis per gloriam Patris, ita et nos in novitate vitæ ambulemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 5, 'Si enim complantati facti sumus similitudini mortis ejus: simul et resurrectionis erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 6, 'Hoc scientes, quia vetus homo noster simul crucifixus est, ut destruatur corpus peccati, et ultra non serviamus peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 7, 'Qui enim mortuus est, justificatus est a peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 8, 'Si autem mortui sumus cum Christo, credimus quia simul etiam vivemus cum Christo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 9, 'scientes quod Christus resurgens ex mortuis jam non moritur: mors illi ultra non dominabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 10, 'Quod enim mortuus est peccato, mortuus est semel: quod autem vivit, vivit Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 11, 'Ita et vos existimate vos mortuos quidem esse peccato, viventes autem Deo, in Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 12, 'Non ergo regnet peccatum in vestro mortali corpore ut obediatis concupiscentiis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 13, 'Sed neque exhibeatis membra vestra arma iniquitatis peccato: sed exhibete vos Deo, tamquam ex mortuis viventes: et membra vestra arma justitiæ Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 14, 'Peccatum enim vobis non dominabitur: non enim sub lege estis, sed sub gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 15, 'Quid ergo? peccabimus, quoniam non sumus sub lege, sed sub gratia? Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 16, 'Nescitis quoniam cui exhibetis vos servos ad obediendum, servi estis ejus, cui obeditis, sive peccati ad mortem, sive obeditionis ad justitiam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 17, 'Gratias autem Deo quod fuistis servi peccati, obedistis autem ex corde in eam formam doctrinæ, in quam traditi estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 18, 'Liberati autem a peccato, servi facti estis justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 19, 'Humanum dico, propter infirmitatem carnis vestræ: sicut enim exhibuistis membra vestra servire immunditiæ, et iniquitati ad iniquitatem, ita nunc exhibete membra vestra servire justitiæ in sanctificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 20, 'Cum enim servi essetis peccati, liberi fuistis justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 21, 'Quem ergo fructum habuistis tunc in illis, in quibus nunc erubescitis? nam finis illorum mors est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 22, 'Nunc vero liberati a peccato, servi autem facti Deo, habetis fructum vestrum in sanctificationem, finem vero vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 6, 23, 'Stipendia enim peccati, mors. Gratia autem Dei, vita æterna, in Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 1, 'An ignoratis, fratres (scientibus enim legem loquor), quia lex in homine dominatur quanto tempore vivit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 2, 'Nam quæ sub viro est mulier, vivente viro, alligata est legi: si autem mortuus fuerit vir ejus, soluta est a lege viri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 3, 'Igitur, vivente viro, vocabitur adultera si fuerit cum alio viro: si autem mortuus fuerit vir ejus, liberata est a lege viri, ut non sit adultera si fuerit cum alio viro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 4, 'Itaque fratres mei, et vos mortificati estis legi per corpus Christi: ut sitis alterius, qui ex mortuis resurrexit, ut fructificemus Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 5, 'Cum enim essemus in carne, passiones peccatorum, quæ per legem erant, operabantur in membris nostris, ut fructificarent morti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 6, 'Nunc autem soluti sumus a lege mortis, in qua detinebamur, ita ut serviamus in novitate spiritus, et non in vetustate litteræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 7, 'Quid ergo dicemus? lex peccatum est? Absit. Sed peccatum non cognovi, nisi per legem: nam concupiscentiam nesciebam, nisi lex diceret: Non concupisces.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 8, 'Occasione autem accepta, peccatum per mandatum operatum est in me omnem concupiscentiam. Sine lege enim peccatum mortuum erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 9, 'Ego autem vivebam sine lege aliquando: sed cum venisset mandatum, peccatum revixit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 10, 'Ego autem mortuus sum: et inventum est mihi mandatum, quod erat ad vitam, hoc esse ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 11, 'Nam peccatum occasione accepta per mandatum, seduxit me, et per illud occidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 12, 'Itaque lex quidem sancta, et mandatum sanctum, et justum, et bonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 13, 'Quod ergo bonum est, mihi factum est mors? Absit. Sed peccatum, ut appareat peccatum, per bonum operatum est mihi mortem: ut fiat supra modum peccans peccatum per mandatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 14, 'Scimus enim quia lex spiritualis est: ego autem carnalis sum, venundatus sub peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 15, 'Quod enim operor, non intelligo: non enim quod volo bonum, hoc ago: sed quod odi malum, illud facio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 16, 'Si autem quod nolo, illud facio: consentio legi, quoniam bona est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 17, 'Nunc autem jam non ego operor illud, sed quod habitat in me peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 18, 'Scio enim quia non habitat in me, hoc est in carne mea, bonum. Nam velle, adjacet mihi: perficere autem bonum, non invenio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 19, 'Non enim quod volo bonum, hoc facio: sed quod nolo malum, hoc ago.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 20, 'Si autem quod nolo, illud facio: jam non ego operor illud, sed quod habitat in me, peccatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 21, 'Invenio igitur legem, volenti mihi facere bonum, quoniam mihi malum adjacet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 22, 'condelector enim legi Dei secundum interiorem hominem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 23, 'video autem aliam legem in membris meis, repugnantem legi mentis meæ, et captivantem me in lege peccati, quæ est in membris meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 24, 'Infelix ego homo, quis me liberabit de corpore mortis hujus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 7, 25, 'gratia Dei per Jesum Christum Dominum nostrum. Igitur ego ipse mente servio legi Dei: carne autem, legi peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 1, 'Nihil ergo nunc damnationis est iis qui sunt in Christo Jesu: qui non secundum carnem ambulant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 2, 'Lex enim spiritus vitæ in Christo Jesu liberavit me a lege peccati et mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 3, 'Nam quod impossibile erat legi, in quo infirmabatur per carnem: Deus Filium suum mittens in similitudinem carnis peccati et de peccato, damnavit peccatum in carne,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 4, 'ut justificatio legis impleretur in nobis, qui non secundum carnem ambulamus, sed secundum spiritum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 5, 'Qui enim secundum carnem sunt, quæ carnis sunt, sapiunt: qui vero secundum spiritum sunt, quæ sunt spiritus, sentiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 6, 'Nam prudentia carnis, mors est: prudentia autem spiritus, vita et pax:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 7, 'quoniam sapientia carnis inimica est Deo: legi enim Dei non est subjecta, nec enim potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 8, 'Qui autem in carne sunt, Deo placere non possunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 9, 'Vos autem in carne non estis, sed in spiritu: si tamen Spiritus Dei habitat in vobis. Si quis autem Spiritum Christi non habet, hic non est ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 10, 'Si autem Christus in vobis est, corpus quidem mortuum est propter peccatum, spiritus vero vivit propter justificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 11, 'Quod si Spiritus ejus, qui suscitavit Jesum a mortuis, habitat in vobis: qui suscitavit Jesum Christum a mortuis, vivificabit et mortalia corpora vestra, propter inhabitantem Spiritum ejus in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 12, 'Ergo fratres, debitores sumus non carni, ut secundum carnem vivamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 13, 'Si enim secundum carnem vixeritis, moriemini: si autem spiritu facta carnis mortificaveritis, vivetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 14, 'Quicumque enim Spiritu Dei aguntur, ii sunt filii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 15, 'Non enim accepistis spiritum servitutis iterum in timore, sed accepistis spiritum adoptionis filiorum, in quo clamamus: Abba (Pater).');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 16, 'Ipse enim Spiritus testimonium reddit spiritui nostro quod sumus filii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 17, 'Si autem filii, et hæredes: hæredes, quidem Dei, cohæredes autem Christi: si tamen compatimur ut et conglorificemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 18, 'Existimo enim quod non sunt condignæ passiones hujus temporis ad futuram gloriam, quæ revelabitur in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 19, 'Nam exspectatio creaturæ revelationem filiorum Dei exspectat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 20, 'Vanitati enim creatura subjecta est non volens, sed propter eum, qui subjecit eam in spe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 21, 'quia et ipsa creatura liberabitur a servitute corruptionis in libertatem gloriæ filiorum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 22, 'Scimus enim quod omnis creatura ingemiscit, et parturit usque adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 23, 'Non solum autem illa, sed et nos ipsi primitias spiritus habentes: et ipsi intra nos gemimus adoptionem filiorum Dei exspectantes, redemptionem corporis nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 24, 'Spe enim salvi facti sumus. Spes autem, quæ videtur, non est spes: nam quod videt quis, quid sperat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 25, 'Si autem quod non videmus, speramus: per patientiam exspectamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 26, 'Similiter autem et Spiritus adjuvat infirmitatem nostram: nam quid oremus, sicut oportet, nescimus: sed ipse Spiritus postulat pro nobis gemitibus inenarrabilibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 27, 'Qui autem scrutatur corda, scit quid desideret Spiritus: quia secundum Deum postulat pro sanctis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 28, 'Scimus autem quoniam diligentibus Deum omnia cooperantur in bonum, iis qui secundum propositum vocati sunt sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 29, 'Nam quos præscivit, et prædestinavit conformes fieri imaginis Filii sui, ut sit ipse primogenitus in multis fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 30, 'Quos autem prædestinavit, hos et vocavit: et quos vocavit, hos et justificavit: quos autem justificavit, illos et glorificavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 31, 'Quid ergo dicemus ad hæc? si Deus pro nobis, quis contra nos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 32, 'Qui etiam proprio Filio suo non pepercit, sed pro nobis omnibus tradidit illum: quomodo non etiam cum illo omnia nobis donavit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 33, 'Quis accusabit adversus electos Dei? Deus qui justificat,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 34, 'quis est qui condemnet? Christus Jesus, qui mortuus est, immo qui et resurrexit, qui est ad dexteram Dei, qui etiam interpellat pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 35, 'Quis ergo nos separabit a caritate Christi? tribulatio? an angustia? an fames? an nuditas? an periculum? an persecutio? an gladius?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 36, '(Sicut scriptum est: Quia propter te mortificamur tota die: æstimati sumus sicut oves occisionis.)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 37, 'Sed in his omnibus superamus propter eum qui dilexit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 38, 'Certus sum enim quia neque mors, neque vita, neque angeli, neque principatus, neque virtutes, neque instantia, neque futura, neque fortitudo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 8, 39, 'neque altitudo, neque profundum, neque creatura alia poterit nos separare a caritate Dei, quæ est in Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 1, 'Veritatem dico in Christo, non mentior: testimonium mihi perhibente conscientia mea in Spiritu Sancto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 2, 'quoniam tristitia mihi magna est, et continuus dolor cordi meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 3, 'Optabam enim ego ipse anathema esse a Christo pro fratribus meis, qui sunt cognati mei secundum carnem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 4, 'qui sunt Israëlitæ, quorum adoptio est filiorum, et gloria, et testamentum, et legislatio, et obsequium, et promissa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 5, 'quorum patres, et ex quibus est Christus secundum carnem, qui est super omnia Deus benedictus in sæcula. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 6, 'Non autem quod exciderit verbum Dei. Non enim omnes qui ex Israël sunt, ii sunt Israëlitæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 7, 'neque qui semen sunt Abrahæ, omnes filii: sed in Isaac vocabitur tibi semen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 8, 'id est, non qui filii carnis, hi filii Dei: sed qui filii sunt promissionis, æstimantur in semine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 9, 'Promissionis enim verbum hoc est: Secundum hoc tempus veniam: et erit Saræ filius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 10, 'Non solum autem illa: sed et Rebecca ex uno concubitu habens, Isaac patris nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 11, 'Cum enim nondum nati fuissent, aut aliquid boni egissent, aut mali (ut secundum electionem propositum Dei maneret),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 12, 'non ex operibus, sed ex vocante dictum est ei quia major serviet minori,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 13, 'sicut scriptum est: Jacob dilexi, Esau autem odio habui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 14, 'Quid ergo dicemus? numquid iniquitas apud Deum? Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 15, 'Moysi enim dicit: Miserebor cujus misereor: et misericordiam præstabo cujus miserebor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 16, 'Igitur non volentis, neque currentis, sed miserentis est Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 17, 'Dicit enim Scriptura Pharaoni: Quia in hoc ipsum excitavi te, ut ostendam in te virtutem meam: et ut annuntietur nomen meum in universa terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 18, 'Ergo cujus vult miseretur, et quem vult indurat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 19, 'Dicis itaque mihi: Quid adhuc queritur? voluntati enim ejus quis resistit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 20, 'O homo, tu quis es, qui respondeas Deo? numquid dicit figmentum ei qui se finxit: Quid me fecisti sic?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 21, 'an non habet potestatem figulus luti ex eadem massa facere aliud quidem vas in honorem, aliud vero in contumeliam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 22, 'Quod si Deus volens ostendere iram, et notum facere potentiam suam, sustinuit in multa patientia vasa iræ, apta in interitum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 23, 'ut ostenderet divitias gloriæ suæ in vasa misericordiæ, quæ præparavit in gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 24, 'Quos et vocavit nos non solum ex Judæis, sed etiam in gentibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 25, 'sicut in Osee dicit: Vocabo non plebem meam, plebem meam: et non dilectam, dilectam: et non misericordiam consecutam, misericordiam consecutam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 26, 'Et erit: in loco, ubi dictum est eis: Non plebs mea vos: ibi vocabuntur filii Dei vivi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 27, 'Isaias autem clamat pro Israël: Si fuerit numerus filiorum Israël tamquam arena maris, reliquiæ salvæ fient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 28, 'Verbum enim consummans, et abbrevians in æquitate: quia verbum breviatum faciet Dominus super terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 29, 'et sicut prædixit Isaias: Nisi Dominus Sabaoth reliquisset nobis semen, sicut Sodoma facti essemus, et sicut Gomorrha similes fuissemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 30, 'Quid ergo dicemus? Quod gentes, quæ non sectabantur justitiam, apprehenderunt justitiam: justitiam autem, quæ ex fide est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 31, 'Israël vero sectando legem justitiæ, in legem justitiæ non pervenit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 32, 'Quare? Quia non ex fide, sed quasi ex operibus: offenderunt enim in lapidem offensionis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 9, 33, 'sicut scriptum est: Ecce pono in Sion lapidem offensionis, et petram scandali: et omnis qui credit in eum, non confundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 1, 'Fratres, voluntas quidem cordis mei, et obsecratio ad Deum, fit pro illis in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 2, 'Testimonium enim perhibeo illis quod æmulationem Dei habent, sed non secundum scientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 3, 'Ignorantes enim justitiam Dei, et suam quærentes statuere, justitiæ Dei non sunt subjecti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 4, 'Finis enim legis, Christus, ad justitiam omni credenti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 5, 'Moyses enim scripsit, quoniam justitiam, quæ ex lege est, qui fecerit homo, vivet in ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 6, 'Quæ autem ex fide est justitia, sic dicit: Ne dixeris in corde tuo: Quis ascendet in cælum? id est, Christum deducere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 7, 'aut, Quis descendet in abyssum? hoc est, Christum a mortuis revocare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 8, 'Sed quid dicit Scriptura? Prope est verbum in ore tuo, et in corde tuo: hoc est verbum fidei, quod prædicamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 9, 'Quia si confitearis in ore tuo Dominum Jesum, et in corde tuo credideris quod Deus illum suscitavit a mortuis, salvus eris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 10, 'Corde enim creditur ad justitiam: ore autem confessio fit ad salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 11, 'Dicit enim Scriptura: Omnis qui credit in illum, non confundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 12, 'Non enim est distinctio Judæi et Græci: nam idem Dominus omnium, dives in omnes qui invocant illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 13, 'Omnis enim quicumque invocaverit nomen Domini, salvus erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 14, 'Quomodo ergo invocabunt, in quem non crediderunt? aut quomodo credent ei, quem non audierunt? quomodo autem audient sine prædicante?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 15, 'quomodo vero prædicabunt nisi mittantur? sicut scriptum est: Quam speciosi pedes evangelizantium pacem, evangelizantium bona!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 16, 'Sed non omnes obediunt Evangelio. Isaias enim dicit: Domine, quis credidit auditui nostro?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 17, 'Ergo fides ex auditu, auditus autem per verbum Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 18, 'Sed dico: Numquid non audierunt? Et quidem in omnem terram exivit sonus eorum, et in fines orbis terræ verba eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 19, 'Sed dico: Numquid Israël non cognovit? Primus Moyses dicit: Ego ad æmulationem vos adducam in non gentem: in gentem insipientem, in iram vos mittam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 20, 'Isaias autem audet, et dicit: Inventus sum a non quærentibus me: palam apparui iis qui me non interrogabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 10, 21, 'Ad Israël autem dicit: Tota die expandi manus meas ad populum non credentem, et contradicentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 1, 'Dico ergo: Numquid Deus repulit populum suum? Absit. Nam et ego Israëlita sum ex semine Abraham, de tribu Benjamin:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 2, 'non repulit Deus plebem suam, quam præscivit. An nescitis in Elia quid dicit Scriptura? quemadmodum interpellat Deum adversum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 3, 'Domine, prophetas tuos occiderunt, altaria tua suffoderunt: et ego relictus sum solus, et quærunt animam meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 4, 'Sed quid dicit illi divinum responsum? Reliqui mihi septem millia virorum, qui non curvaverunt genua ante Baal.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 5, 'Sic ergo et in hoc tempore reliquiæ secundum electionem gratiæ salvæ factæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 6, 'Si autem gratia, jam non ex operibus: alioquin gratia jam non est gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 7, 'Quid ergo? Quod quærebat Israël, hoc non est consecutus: electio autem consecuta est: ceteri vero excæcati sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 8, 'sicut scriptum est: Dedit illis Deus spiritum compunctionis: oculos ut non videant, et aures ut non audiant, usque in hodiernum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 9, 'Et David dicit: Fiat mensa eorum in laqueum, et in captionem, et in scandalum, et in retributionem illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 10, 'Obscurentur oculi eorum ne videant: et dorsum eorum semper incurva.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 11, 'Dico ergo: Numquid sic offenderunt ut caderent? Absit. Sed illorum delicto, salus est gentibus ut illos æmulentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 12, 'Quod si delictum illorum divitiæ sunt mundi, et diminutio eorum divitiæ gentium: quanto magis plenitudo eorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 13, 'Vobis enim dico gentibus: Quamdiu quidem ego sum gentium Apostolus, ministerium meum honorificabo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 14, 'si quomodo ad æmulandum provocem carnem meam, et salvos faciam aliquos ex illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 15, 'Si enim amissio eorum, reconciliatio est mundi: quæ assumptio, nisi vita ex mortuis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 16, 'Quod si delibatio sancta est, et massa: et si radix sancta, et rami.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 17, 'Quod si aliqui ex ramis fracti sunt, tu autem cum oleaster esses, insertus es in illis, et socius radicis, et pinguedinis olivæ factus es,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 18, 'noli gloriari adversus ramos. Quod si gloriaris: non tu radicem portas, sed radix te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 19, 'Dices ergo: Fracti sunt rami ut ego inserar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 20, 'Bene: propter incredulitatem fracti sunt. Tu autem fide stas: noli altum sapere, sed time.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 21, 'Si enim Deus naturalibus ramis non pepercit: ne forte nec tibi parcat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 22, 'Vide ergo bonitatem, et severitatem Dei: in eos quidem qui ceciderunt, severitatem: in te autem bonitatem Dei, si permanseris in bonitate, alioquin et tu excideris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 23, 'Sed et illi, si non permanserint in incredulitate, inserentur: potens est enim Deus iterum inserere illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 24, 'Nam si tu ex naturali excisus es oleastro, et contra naturam insertus es in bonam olivam: quanto magis ii qui secundum naturam inserentur suæ olivæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 25, 'Nolo enim vos ignorare, fratres, mysterium hoc (ut non sitis vobis ipsis sapientes), quia cæcitas ex parte contigit in Israël, donec plenitudo gentium intraret,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 26, 'et sic omnis Israël salvus fieret, sicut scriptum est: Veniet ex Sion, qui eripiat, et avertat impietatem a Jacob.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 27, 'Et hoc illis a me testamentum: cum abstulero peccata eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 28, 'Secundum Evangelium quidem, inimici propter vos: secundum electionem autem, carissimi propter patres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 29, 'Sine pœnitentia enim sunt dona et vocatio Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 30, 'Sicut enim aliquando et vos non credidistis Deo, nunc autem misericordiam consecuti estis propter incredulitatem illorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 31, 'ita et isti nunc non crediderunt in vestram misericordiam: ut et ipsi misericordiam consequantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 32, 'Conclusit enim Deus omnia in incredulitate, ut omnium misereatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 33, 'O altitudo divitiarum sapientiæ, et scientiæ Dei: quam incomprehensibilia sunt judicia ejus, et investigabiles viæ ejus!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 34, 'Quis enim cognovit sensum Domini? aut quis consiliarius ejus fuit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 35, 'aut quis prior dedit illi, et retribuetur ei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 11, 36, 'Quoniam ex ipso, et per ipsum, et in ipso sunt omnia: ipsi gloria in sæcula. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 1, 'Obsecro itaque vos fratres per misericordiam Dei, ut exhibeatis corpora vestra hostiam viventem, sanctam, Deo placentem, rationabile obsequium vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 2, 'Et nolite conformari huic sæculo, sed reformamini in novitate sensus vestri: ut probetis quæ sit voluntas Dei bona, et beneplacens, et perfecta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 3, 'Dico enim per gratiam quæ data est mihi, omnibus qui sunt inter vos, non plus sapere quam oportet sapere, sed sapere ad sobrietatem: et unicuique sicut Deus divisit mensuram fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 4, 'Sicut enim in uno corpore multa membra habemus, omnia autem membra non eumdem actum habent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 5, 'ita multi unum corpus sumus in Christo, singuli autem alter alterius membra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 6, 'Habentes autem donationes secundum gratiam, quæ data est nobis, differentes: sive prophetiam secundum rationem fidei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 7, 'sive ministerium in ministrando, sive qui docet in doctrina,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 8, 'qui exhortatur in exhortando, qui tribuit in simplicitate, qui præest in sollicitudine, qui miseretur in hilaritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 9, 'Dilectio sine simulatione: odientes malum, adhærentes bono:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 10, 'caritate fraternitatis invicem diligentes: honore invicem prævenientes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 11, 'sollicitudine non pigri: spiritu ferventes: Domino servientes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 12, 'spe gaudentes: in tribulatione patientes: orationi instantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 13, 'necessitatibus sanctorum communicantes: hospitalitatem sectantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 14, 'Benedicite persequentibus vos: benedicite, et nolite maledicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 15, 'Gaudere cum gaudentibus, flere cum flentibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 16, 'idipsum invicem sentientes: non alta sapientes, sed humilibus consentientes. Nolite esse prudentes apud vosmetipsos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 17, 'nulli malum pro malo reddentes: providentes bona non tantum coram Deo, sed etiam coram omnibus hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 18, 'Si fieri potest, quod ex vobis est, cum omnibus hominibus pacem habentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 19, 'non vosmetipsos defendentes carissimi, sed date locum iræ. Scriptum est enim: Mihi vindicta: ego retribuam, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 20, 'Sed si esurierit inimicus tuus, ciba illum: si sitit, potum da illi: hoc enim faciens, carbones ignis congeres super caput ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 12, 21, 'Noli vinci a malo, sed vince in bono malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 1, 'Omnis anima potestatibus sublimioribus subdita sit: non est enim potestas nisi a Deo: quæ autem sunt, a Deo ordinatæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 2, 'Itaque qui resistit potestati, Dei ordinationi resistit. Qui autem resistunt, ipsi sibi damnationem acquirunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 3, 'nam principes non sunt timori boni operis, sed mali. Vis autem non timere potestatem? Bonum fac: et habebis laudem ex illa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 4, 'Dei enim minister est tibi in bonum. Si autem malum feceris, time: non enim sine causa gladium portat. Dei enim minister est: vindex in iram ei qui malum agit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 5, 'Ideo necessitate subditi estote non solum propter iram, sed etiam propter conscientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 6, 'Ideo enim et tributa præstatis: ministri enim Dei sunt, in hoc ipsum servientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 7, 'Reddite ergo omnibus debita: cui tributum, tributum: cui vectigal, vectigal: cui timorem, timorem: cui honorem, honorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 8, 'Nemini quidquam debeatis, nisi ut invicem diligatis: qui enim diligit proximum, legem implevit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 9, 'Nam: Non adulterabis: non occides: non furaberis: non falsum testimonium dices: non concupisces: et si quod est aliud mandatum, in hoc verbo instauratur: diliges proximum tuum sicut teipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 10, 'Dilectio proximi malum non operatur. Plenitudo ergo legis est dilectio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 11, 'Et hoc scientes tempus: quia hora est jam nos de somno surgere. Nunc enim propior est nostra salus, quam cum credidimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 12, 'Nox præcessit, dies autem appropinquavit. Abjiciamus ergo opera tenebrarum, et induamur arma lucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 13, 'Sicut in die honeste ambulemus: non in comessationibus, et ebrietatibus, non in cubilibus, et impudicitiis, non in contentione, et æmulatione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 13, 14, 'sed induimini Dominum Jesum Christum, et carnis curam ne feceritis in desideriis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 1, 'Infirmum autem in fide assumite, non in disceptationibus cogitationum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 2, 'Alius enim credit se manducare omnia: qui autem infirmus est, olus manducet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 3, 'Is qui manducat, non manducantem non spernat: et qui non manducat, manducantem non judicet: Deus enim illum assumpsit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 4, 'Tu quis es, qui judicas alienum servum? domino suo stat, aut cadit: stabit autem: potens est enim Deus statuere illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 5, 'Nam alius judicat diem inter diem: alius autem judicat omnem diem: unusquisque in suo sensu abundet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 6, 'Qui sapit diem, Domino sapit, et qui manducat, Domino manducat: gratias enim agit Deo. Et qui non manducat, Domino non manducat, et gratias agit Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 7, 'Nemo enim nostrum sibi vivit, et nemo sibi moritur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 8, 'Sive enim vivemus, Domino vivimus: sive morimur, Domino morimur. Sive ergo vivimus, sive morimur, Domini sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 9, 'In hoc enim Christus mortuus est, et resurrexit: ut et mortuorum et vivorum dominetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 10, 'Tu autem quid judicas fratrem tuum? aut tu quare spernis fratrem tuum? omnes enim stabimus ante tribunal Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 11, 'Scriptum est enim: Vivo ego, dicit Dominus, quoniam mihi flectetur omne genu: et omnis lingua confitebitur Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 12, 'Itaque unusquisque nostrum pro se rationem reddet Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 13, 'Non ergo amplius invicem judicemus: sed hoc judicate magis, ne ponatis offendiculum fratri, vel scandalum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 14, 'Scio, et confido in Domino Jesu, quia nihil commune per ipsum, nisi ei qui existimat quid commune esset, illi commune est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 15, 'Si enim propter cibum frater tuus contristatur, jam non secundum caritatem ambulas. Noli cibo tuo illum perdere, pro quo Christus mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 16, 'Non ergo blasphemetur bonum nostrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 17, 'Non est enim regnum Dei esca et potus: sed justitia, et pax, et gaudium in Spiritu Sancto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 18, 'qui enim in hoc servit Christo, placet Deo, et probatus est hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 19, 'Itaque quæ pacis sunt, sectemur: et quæ ædificationis sunt, in invicem custodiamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 20, 'Noli propter escam destruere opus Dei, omnia quidem sunt munda: sed malum est homini, qui per offendiculum manducat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 21, 'Bonum est non manducare carnem, et non bibere vinum, neque in quo frater tuus offenditur, aut scandalizatur, aut infirmatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 22, 'Tu fidem habes? penes temetipsum habe coram Deo. Beatus qui non judicat semetipsum in eo quod probat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 14, 23, 'Qui autem discernit, si manducaverit, damnatus est: quia non ex fide. Omne autem, quod non est ex fide, peccatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 1, 'Debemus autem nos firmiores imbecillitates infirmorum sustinere, et non nobis placere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 2, 'Unusquisque vestrum proximo suo placeat in bonum, ad ædificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 3, 'Etenim Christus non sibi placuit, sed sicut scriptum est: Improperia improperantium tibi ceciderunt super me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 4, 'Quæcumque enim scripta sunt, ad nostram doctrinam scripta sunt: ut per patientiam, et consolationem Scripturarum, spem habeamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 5, 'Deus autem patientiæ et solatii det vobis idipsum sapere in alterutrum secundum Jesum Christum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 6, 'ut unanimes, uno ore honorificetis Deum et patrem Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 7, 'Propter quod suscipite invicem, sicut et Christus suscepit vos in honorem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 8, 'Dico enim Christum Jesum ministrum fuisse circumcisionis propter veritatem Dei, ad confirmandas promissiones patrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 9, 'gentes autem super misericordia honorare Deum, sicut scriptum est: Propterea confitebor tibi in gentibus, Domine, et nomini tuo cantabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 10, 'Et iterum dicit: Lætamini gentes cum plebe ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 11, 'Et iterum: Laudate omnes gentes Dominum: et magnificate eum omnes populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 12, 'Et rursus Isaias ait: Erit radix Jesse, et qui exsurget regere gentes, in eum gentes sperabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 13, 'Deus autem spei repleat vos omni gaudio, et pace in credendo: ut abundetis in spe, et virtute Spiritus Sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 14, 'Certus sum autem fratres mei et ego ipse de vobis, quoniam et ipsi pleni estis dilectione, repleti omni scientia, ita ut possitis alterutrum monere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 15, 'Audacius autem scripsi vobis fratres ex parte, tamquam in memoriam vos reducens: propter gratiam, quæ data est mihi a Deo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 16, 'ut sim minister Christi Jesu in gentibus: sanctificans Evangelium Dei, ut fiat oblatio gentium accepta, et sanctificata in Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 17, 'Habeo igitur gloriam in Christo Jesu ad Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 18, 'Non enim audeo aliquid loqui eorum, quæ per me non efficit Christus in obedientiam gentium, verbo et factis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 19, 'in virtute signorum, et prodigiorum, in virtute Spiritus Sancti: ita ut ab Jerusalem per circuitum usque ad Illyricum repleverim Evangelium Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 20, 'Sic autem prædicavi Evangelium hoc, non ubi nominatus est Christus, ne super alienum fundamentum ædificarem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 21, 'sed sicut scriptum est: Quibus non est annuntiatum de eo, videbunt: et qui non audierunt, intelligent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 22, 'Propter quod et impediebar plurimum venire ad vos, et prohibitus sum usque adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 23, 'Nunc vero ulterius locum non habens in his regionibus, cupiditatem autem habens veniendi ad vos ex multis jam præcedentibus annis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 24, 'cum in Hispaniam proficisci cœpero, spero quod præteriens videam vos, et a vobis deducar illuc, si vobis primum ex parte fruitus fuero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 25, 'Nunc igitur proficiscar in Jerusalem ministrare sanctis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 26, 'Probaverunt enim Macedonia et Achaia collationem aliquam facere in pauperes sanctorum, qui sunt in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 27, 'Placuit enim eis: et debitores sunt eorum. Nam si spiritualium eorum participes facti sunt gentiles, debent et in carnalibus ministrare illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 28, 'Hoc igitur cum consummavero, et assignavero eis fructum hunc, per vos proficiscar in Hispaniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 29, 'Scio autem quoniam veniens ad vos, in abundantia benedictionis Evangelii Christi veniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 30, 'Obsecro ergo vos fratres per Dominum nostrum Jesum Christum, et per caritatem Sancti Spiritus, ut adjuvetis me in orationibus vestris pro me ad Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 31, 'ut liberer ab infidelibus, qui sunt in Judæa, et obsequii mei oblatio accepta fiat in Jerusalem sanctis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 32, 'ut veniam ad vos in gaudio per voluntatem Dei, et refrigerer vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 15, 33, 'Deus autem pacis sit cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 1, 'Commendo autem vobis Phœben sororem nostram, quæ est in ministerio ecclesiæ, quæ est in Cenchris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 2, 'ut eam suscipiatis in Domino digne sanctis: et assistatis ei in quocumque negotio vestri indiguerit: etenim ipsa quoque astitit multis, et mihi ipsi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 3, 'Salutate Priscam et Aquilam, adjutores meos in Christo Jesu');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 4, '(qui pro anima mea suas cervices supposuerunt: quibus non solus ego gratias ago, sed et cunctæ ecclesiæ gentium),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 5, 'et domesticam ecclesiam eorum. Salutate Epænetum dilectum mihi, qui est primitivus Asiæ in Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 6, 'Salutate Mariam, quæ multum laboravit in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 7, 'Salutate Andronicum et Juniam, cognatos, et concaptivos meos: qui sunt nobiles in Apostolis, qui et ante me fuerunt in Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 8, 'Salutate Ampliatum dilectissimum mihi in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 9, 'Salutate Urbanum adjutorem nostrum in Christo Jesu, et Stachyn dilectum meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 10, 'Salutate Apellen probum in Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 11, 'Salutate eos qui sunt ex Aristoboli domo. Salutate Herodionem cognatum meum. Salutate eos qui sunt ex Narcisi domo, qui sunt in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 12, 'Salutate Tryphænam et Tryphosam, quæ laborant in Domino. Salutate Persidem carissimam, quæ multum laboravit in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 13, 'Salutate Rufum electum in Domino, et matrem ejus, et meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 14, 'Salutate Asyncritum, Phlegontem, Hermam, Patrobam, Hermen, et qui cum eis sunt, fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 15, 'Salutate Philologum et Juliam, Nereum, et sororem ejus, et Olympiadem, et omnes qui cum eis sunt, sanctos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 16, 'Salutate invicem in osculo sancto. Salutant vos omnes ecclesiæ Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 17, 'Rogo autem vos fratres, ut observetis eos qui dissensiones et offendicula, præter doctrinam, quam vos didicistis, faciunt, et declinate ab illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 18, 'Hujuscemodi enim Christo Domino nostro non serviunt, sed suo ventri: et per dulces sermones et benedictiones seducunt corda innocentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 19, 'Vestra enim obedientia in omnem locum divulgata est. Gaudeo igitur in vobis. Sed volo vos sapientes esse in bono, et simplices in malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 20, 'Deus autem pacis conterat Satanam sub pedibus vestris velociter. Gratia Domini nostri Jesu Christi vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 21, 'Salutat vos Timotheus adjutor meus, et Lucius, et Jason, et Sosipater cognati mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 22, 'Saluto vos ego Tertius, qui scripsi epistolam, in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 23, 'Salutat vos Cajus hospes meus, et universa ecclesia. Salutat vos Erastus arcarius civitatis, et Quartus, frater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 24, 'Gratia Domini nostri Jesu Christi cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 25, 'Ei autem, qui potens est vos confirmare juxta Evangelium meum, et prædicationem Jesu Christi, secundum revelationem mysterii temporibus æternis taciti');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 26, '(quod nunc patefactum est per Scripturas prophetarum secundum præceptum æterni Dei, ad obeditionem fidei), in cunctis gentibus cogniti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 16, 27, 'soli sapienti Deo, per Jesum Christum, cui honor et gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus vocatus Apostolus Jesu Christi per voluntatem Dei, et Sosthenes frater,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'ecclesiæ Dei, quæ est Corinthi, sanctificatis in Christo Jesu, vocatis sanctis, cum omnibus qui invocant nomen Domini nostri Jesu Christi, in omni loco ipsorum et nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Gratias ago Deo meo semper pro vobis in gratia Dei, quæ data est vobis in Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'quod in omnibus divites facti estis in illo, in omni verbo, et in omni scientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Sicut testimonium Christi confirmatum est in vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'ita ut nihil vobis desit in ulla gratia, exspectantibus revelationem Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'qui et confirmabit vos usque in finem sine crimine, in die adventus Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Fidelis Deus: per quem vocati estis in societatem filii ejus Jesu Christi Domini nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Obsecro autem vos fratres per nomen Domini nostri Jesu Christi: ut idipsum dicatis omnes, et non sint in vobis schismata: sitis autem perfecti in eodem sensu, et in eadem sententia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Significatum est enim mihi de vobis fratres mei ab iis, qui sunt Chloës, quia contentiones sunt inter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Hoc autem dico, quod unusquisque vestrum dicit: Ego quidem sum Pauli: ego autem Apollo: ego vero Cephæ: ego autem Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 13, 'Divisus est Christus? numquid Paulus crucifixus est pro vobis? aut in nomine Pauli baptizati estis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 14, 'Gratias ago Deo, quod neminem vestrum baptizavi, nisi Crispum et Caium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 15, 'ne quis dicat quod in nomine meo baptizati estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 16, 'Baptizavi autem et Stephanæ domum: ceterum nescio si quem alium baptizaverim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 17, 'Non enim misit me Christus baptizare, sed evangelizare: non in sapientia verbi, ut non evacuetur crux Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 18, 'Verbum enim crucis pereuntibus quidem stultitia est: iis autem qui salvi fiunt, id est nobis, Dei virtus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 19, 'Scriptum est enim: Perdam sapientiam sapientium, et prudentiam prudentium reprobabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 20, 'Ubi sapiens? ubi scriba? ubi conquisitor hujus sæculi? Nonne stultam fecit Deus sapientiam hujus mundi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 21, 'Nam quia in Dei sapientia non cognovit mundus per sapientiam Deum: placuit Deo per stultitiam prædicationis salvos facere credentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 22, 'Quoniam et Judæi signa petunt, et Græci sapientiam quærunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 23, 'nos autem prædicamus Christum crucifixum: Judæis quidem scandalum, gentibus autem stultitiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 24, 'ipsis autem vocatis Judæis, atque Græcis Christum Dei virtutem, et Dei sapientiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 25, 'quia quod stultum est Dei, sapientius est hominibus: et quod infirmum est Dei, fortius est hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 26, 'Videte enim vocationem vestram, fratres, quia non multi sapientes secundum carnem, non multi potentes, non multi nobiles:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 27, 'sed quæ stulta sunt mundi elegit Deus, ut confundat sapientes: et infirma mundi elegit Deus, ut confundat fortia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 28, 'et ignobilia mundi, et contemptibilia elegit Deus, et ea quæ non sunt, ut ea quæ sunt destrueret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 29, 'ut non glorietur omnis caro in conspectu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 30, 'Ex ipso autem vos estis in Christo Jesu, qui factus est nobis sapientia a Deo, et justitia, et sanctificatio, et redemptio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 31, 'ut quemadmodum scriptum est: Qui gloriatur, in Domino glorietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Et ego, cum venissem ad vos, fratres, veni non in sublimitate sermonis, aut sapientiæ, annuntians vobis testimonium Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Non enim judicavi me scire aliquid inter vos, nisi Jesum Christum, et hunc crucifixum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Et ego in infirmitate, et timore, et tremore multo fui apud vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'et sermo meus, et prædicatio mea non in persuasibilibus humanæ sapientiæ verbis, sed in ostensione spiritus et virtutis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'ut fides vestra non sit in sapientia hominum, sed in virtute Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Sapientiam autem loquimur inter perfectos: sapientiam vero non hujus sæculi, neque principum hujus sæculi, qui destruuntur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'sed loquimur Dei sapientiam in mysterio, quæ abscondita est, quam prædestinavit Deus ante sæcula in gloriam nostram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'quam nemo principum hujus sæculi cognovit: si enim cognovissent, numquam Dominum gloriæ crucifixissent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Sed sicut scriptum est: Quod oculus non vidit, nec auris audivit, nec in cor hominis ascendit, quæ præparavit Deus iis qui diligunt illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'nobis autem revelavit Deus per Spiritum suum: Spiritus enim omnia scrutatur, etiam profunda Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Quis enim hominum scit quæ sunt hominis, nisi spiritus hominis, qui in ipso est? ita et quæ Dei sunt, nemo cognovit, nisi Spiritus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Nos autem non spiritum hujus mundi accepimus, sed Spiritum qui ex Deo est, ut sciamus quæ a Deo donata sunt nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'quæ et loquimur non in doctis humanæ sapientiæ verbis, sed in doctrina Spiritus, spiritualibus spiritualia comparantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Animalis autem homo non percipit ea quæ sunt Spiritus Dei: stultitia enim est illi, et non potest intelligere: quia spiritualiter examinatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Spiritualis autem judicat omnia: et ipse a nemine judicatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Quis enim cognovit sensum Domini, qui instruat eum? nos autem sensum Christi habemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Et ego, fratres, non potui vobis loqui quasi spiritualibus, sed quasi carnalibus. Tamquam parvulis in Christo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'lac vobis potum dedi, non escam: nondum enim poteratis: sed nec nunc quidem potestis: adhuc enim carnales estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Cum enim sit inter vos zelus, et contentio: nonne carnales estis, et secundum hominem ambulatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Cum enim quis dicat: Ego quidem sum Pauli; alius autem: Ego Apollo: nonne homines estis? Quid igitur est Apollo? quid vero Paulus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'ministri ejus, cui credidistis, et unicuique sicut Dominus dedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Ego plantavi, Apollo rigavit: sed Deus incrementum dedit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Itaque neque qui plantat est aliquid, neque qui rigat: sed qui incrementum dat, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Qui autem plantat, et qui rigat, unum sunt. Unusquisque autem propriam mercedem accipiet, secundum suum laborem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Dei enim sumus adjutores: Dei agricultura estis, Dei ædificatio estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Secundum gratiam Dei, quæ data est mihi, ut sapiens architectus fundamentum posui: alius autem superædificat. Unusquisque autem videat quomodo superædificet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Fundamentum enim aliud nemo potest ponere præter id quod positum est, quod est Christus Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Si quis autem superædificat super fundamentum hoc, aurum, argentum, lapides pretiosos, ligna, fœnum, stipulam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'uniuscujusque opus manifestum erit: dies enim Domini declarabit, quia in igne revelabitur: et uniuscujusque opus quale sit, ignis probabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Si cujus opus manserit quod superædificavit, mercedem accipiet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Si cujus opus arserit, detrimentum patietur: ipse autem salvus erit, sic tamen quasi per ignem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Nescitis quia templum Dei estis, et Spiritus Dei habitat in vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Si quis autem templum Dei violaverit, disperdet illum Deus. Templum enim Dei sanctum est, quod estis vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Nemo se seducat: si quis videtur inter vos sapiens esse in hoc sæculo, stultus fiat ut sit sapiens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 19, 'Sapientia enim hujus mundi, stultitia est apud Deum. Scriptum est enim: Comprehendam sapientes in astutia eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 20, 'Et iterum: Dominus novit cogitationes sapientium quoniam vanæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 21, 'Nemo itaque glorietur in hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 22, 'Omnia enim vestra sunt, sive Paulus, sive Apollo, sive Cephas, sive mundus, sive vita, sive mors, sive præsentia, sive futura: omnia enim vestra sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 23, 'vos autem Christi: Christus autem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 1, 'Sic nos existimet homo ut ministros Christi, et dispensatores mysteriorum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 2, 'Hic jam quæritur inter dispensatores ut fidelis quis inveniatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 3, 'Mihi autem pro minimo est ut a vobis judicer, aut ab humano die: sed neque meipsum judico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 4, 'Nihil enim mihi conscius sum, sed non in hoc justificatus sum: qui autem judicat me, Dominus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 5, 'Itaque nolite ante tempus judicare, quoadusque veniat Dominus: qui et illuminabit abscondita tenebrarum, et manifestabit consilia cordium: et tunc laus erit unicuique a Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 6, 'Hæc autem, fratres, transfiguravi in me et Apollo, propter vos: ut in nobis discatis, ne supra quam scriptum est, unus adversus alterum infletur pro alio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 7, 'Quis enim te discernit? quid autem habes quod non accepisti? si autem accepisti, quid gloriaris quasi non acceperis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 8, 'Jam saturati estis, jam divites facti estis: sine nobis regnatis: et utinam regnetis, ut et nos vobiscum regnemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 9, 'Puto enim quod Deus nos Apostolos novissimos ostendit, tamquam morti destinatos: quia spectaculum facti sumus mundo, et angelis, et hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 10, 'Nos stulti propter Christum, vos autem prudentes in Christo: nos infirmi, vos autem fortes: vos nobiles, nos autem ignobiles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 11, 'Usque in hanc horam et esurimus, et sitimus, et nudi sumus, et colaphis cædimur, et instabiles sumus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 12, 'et laboramus operantes manibus nostris: maledicimur, et benedicimus: persecutionem patimur, et sustinemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 13, 'blasphemamur, et obsecramus: tamquam purgamenta hujus mundi facti sumus, omnium peripsema usque adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 14, 'Non ut confundam vos, hæc scribo, sed ut filios meos carissimos moneo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 15, 'Nam si decem millia pædagogorum habeatis in Christo, sed non multos patres. Nam in Christo Jesu per Evangelium ego vos genui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 16, 'Rogo ergo vos, imitatores mei estote, sicut et ego Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 17, 'Ideo misi ad vos Timotheum, qui est filius meus carissimus, et fidelis in Domino: qui vos commonefaciet vias meas, quæ sunt in Christo Jesu, sicut ubique in omni ecclesia doceo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 18, 'Tamquam non venturus sim ad vos, sic inflati sunt quidam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 19, 'Veniam autem ad vos cito, si Dominus voluerit: et cognoscam non sermonem eorum qui inflati sunt, sed virtutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 20, 'Non enim in sermone est regnum Dei, sed in virtute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 4, 21, 'Quid vultis? in virga veniam ad vos, an in caritate, et spiritu mansuetudinis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 1, 'Omnino auditur inter vos fornicatio, et talis fornicatio, qualis nec inter gentes, ita ut uxorem patris sui aliquis habeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 2, 'Et vos inflati estis: et non magis luctum habuistis ut tollatur de medio vestrum qui hoc opus fecit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 3, 'Ego quidem absens corpore, præsens autem spiritu, jam judicavi ut præsens eum, qui sic operatus est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 4, 'in nomine Domini nostri Jesu Christi, congregatis vobis et meo spiritu, cum virtute Domini nostri Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 5, 'tradere hujusmodi Satanæ in interitum carnis, ut spiritus salvus sit in die Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 6, 'Non est bona gloriatio vestra. Nescitis quia modicum fermentum totam massam corrumpit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 7, 'Expurgate vetus fermentum, ut sitis nova conspersio, sicut estis azymi. Etenim Pascha nostrum immolatus est Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 8, 'Itaque epulemur: non in fermento veteri, neque in fermento malitiæ et nequitiæ: sed in azymis sinceritatis et veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 9, 'Scripsi vobis in epistola: Ne commisceamini fornicariis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 10, 'non utique fornicariis hujus mundi, aut avaris, aut rapacibus, aut idolis servientibus: alioquin debueratis de hoc mundo exiisse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 11, 'Nunc autem scripsi vobis non commisceri: si is qui frater nominatur, est fornicator, aut avarus, aut idolis serviens, aut maledicus, aut ebriosus, aut rapax, cum ejusmodi nec cibum sumere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 12, 'Quid enim mihi de iis qui foris sunt, judicare? nonne de iis qui intus sunt, vos judicatis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 5, 13, 'nam eos qui foris sunt, Deus judicabit. Auferte malum ex vobis ipsis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 1, 'Audet aliquis vestrum habens negotium adversus alterum, judicari apud iniquos, et non apud sanctos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 2, 'an nescitis quoniam sancti de hoc mundo judicabunt? et si in vobis judicabitur mundus, indigni estis qui de minimis judicetis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 3, 'Nescitis quoniam angelos judicabimus? quanto magis sæcularia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 4, 'Sæcularia igitur judicia si habueritis: contemptibiles, qui sunt in ecclesia, illos constituite ad judicandum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 5, 'Ad verecundiam vestram dico. Sic non est inter vos sapiens quisquam, qui possit judicare inter fratrem suum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 6, 'Sed frater cum fratre judicio contendit: et hoc apud infideles?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 7, 'Jam quidem omnino delictum est in vobis, quod judicia habetis inter vos. Quare non magis injuriam accipitis? quare non magis fraudem patimini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 8, 'Sed vos injuriam facitis, et fraudatis: et hoc fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 9, 'An nescitis quia iniqui regnum Dei non possidebunt? Nolite errare: neque fornicarii, neque idolis servientes, neque adulteri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 10, 'neque molles, neque masculorum concubitores, neque fures, neque avari, neque ebriosi, neque maledici, neque rapaces regnum Dei possidebunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 11, 'Et hæc quidam fuistis: sed abluti estis, sed sanctificati estis, sed justificati estis in nomine Domini nostri Jesu Christi, et in Spiritu Dei nostri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 12, 'Omnia mihi licent, sed non omnia expediunt: omnia mihi licent, sed ego sub nullis redigar potestate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 13, 'Esca ventri, et venter escis: Deus autem et hunc et has destruet: corpus autem non fornicationi, sed Domino: et Dominus corpori.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 14, 'Deus vero et Dominum suscitavit: et nos suscitabit per virtutem suam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 15, 'Nescitis quoniam corpora vestra membra sunt Christi? Tollens ergo membra Christi, faciam membra meretricis? Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 16, 'An nescitis quoniam qui adhæret meretrici, unum corpus efficitur? Erunt enim (inquit) duo in carne una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 17, 'Qui autem adhæret Domino, unus spiritus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 18, 'Fugite fornicationem. Omne peccatum, quodcumque fecerit homo, extra corpus est: qui autem fornicatur, in corpus suum peccat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 19, 'An nescitis quoniam membra vestra, templum sunt Spiritus Sancti, qui in vobis est, quem habetis a Deo, et non estis vestri?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 6, 20, 'Empti enim estis pretio magno. Glorificate, et portate Deum in corpore vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 1, 'De quibus autem scripsistis mihi: Bonum est homini mulierem non tangere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 2, 'propter fornicationem autem unusquisque suam uxorem habeat, et unaquæque suum virum habeat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 3, 'Uxori vir debitum reddat: similiter autem et uxor viro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 4, 'Mulier sui corporis potestatem non habet, sed vir. Similiter autem et vir sui corporis potestatem non habet, sed mulier.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 5, 'Nolite fraudare invicem, nisi forte ex consensu ad tempus, ut vacetis orationi: et iterum revertimini in idipsum, ne tentet vos Satanas propter incontinentiam vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 6, 'Hoc autem dico secundum indulgentiam, non secundum imperium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 7, 'Volo enim omnes vos esse sicut meipsum: sed unusquisque proprium donum habet ex Deo: alius quidem sic, alius vero sic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 8, 'Dico autem non nuptis, et viduis: bonum est illis si sic permaneant, sicut et ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 9, 'Quod si non se continent, nubant. Melius est enim nubere, quam uri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 10, 'Iis autem qui matrimonio juncti sunt, præcipio non ego, sed Dominus, uxorem a viro non discedere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 11, 'quod si discesserit, manere innuptam, aut viro suo reconciliari. Et vir uxorem non dimittat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 12, 'Nam ceteris ego dico, non Dominus. Si quis frater uxorem habet infidelem, et hæc consentit habitare cum illo, non dimittat illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 13, 'Et si qua mulier fidelis habet virum infidelem, et hic consentit habitare cum illa, non dimittat virum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 14, 'sanctificatus est enim vir infidelis per mulierem fidelem, et sanctificata est mulier infidelis per virum fidelem: alioquin filii vestri immundi essent, nunc autem sancti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 15, 'Quod si infidelis discedit, discedat: non enim servituti subjectus est frater, aut soror in hujusmodi: in pace autem vocavit nos Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 16, 'Unde enim scis mulier, si virum salvum facies? aut unde scis vir, si mulierem salvam facies?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 17, 'Nisi unicuique sicut divisit Dominus, unumquemque sicut vocavit Deus, ita ambulet, et sicut in omnibus ecclesiis doceo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 18, 'Circumcisus aliquis vocatus est? non adducat præputium. In præputio aliquis vocatus est? non circumcidatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 19, 'Circumcisio nihil est, et præputium nihil est: sed observatio mandatorum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 20, 'Unusquisque in qua vocatione vocatus est, in ea permaneat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 21, 'Servus vocatus es? non sit tibi curæ: sed et si potes fieri liber, magis utere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 22, 'Qui enim in Domino vocatus est servus, libertus est Domini: similiter qui liber vocatus est, servus est Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 23, 'Pretio empti estis: nolite fieri servi hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 24, 'Unusquisque in quo vocatus est, fratres, in hoc permaneat apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 25, 'De virginibus autem præceptum Domini non habeo: consilium autem do, tamquam misericordiam consecutus a Domino, ut sim fidelis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 26, 'Existimo ergo hoc bonum esse propter instantem necessitatem, quoniam bonum est homini sic esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 27, 'Alligatus es uxori? noli quærere solutionem. Solutus es ab uxore? noli quærere uxorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 28, 'Si autem acceperis uxorem, non peccasti. Et si nupserit virgo, non peccavit: tribulationem tamen carnis habebunt hujusmodi. Ego autem vobis parco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 29, 'Hoc itaque dico, fratres: tempus breve est: reliquum est, ut et qui habent uxores, tamquam non habentes sint:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 30, 'et qui flent, tamquam non flentes: et qui gaudent, tamquam non gaudentes: et qui emunt, tamquam non possidentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 31, 'et qui utuntur hoc mundo, tamquam non utantur: præterit enim figura hujus mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 32, 'Volo autem vos sine sollicitudine esse. Qui sine uxore est, sollicitus est quæ Domini sunt, quomodo placeat Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 33, 'Qui autem cum uxore est, sollicitus est quæ sunt mundi, quomodo placeat uxori, et divisus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 34, 'Et mulier innupta, et virgo, cogitat quæ Domini sunt, ut sit sancta corpore, et spiritu. Quæ autem nupta est, cogitat quæ sunt mundi, quomodo placeat viro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 35, 'Porro hoc ad utilitatem vestram dico: non ut laqueum vobis injiciam, sed ad id, quod honestum est, et quod facultatem præbeat sine impedimento Dominum obsecrandi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 36, 'Si quis autem turpem se videri existimat super virgine sua, quod sit superadulta, et ita oportet fieri: quod vult faciat: non peccat, si nubat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 37, 'Nam qui statuit in corde suo firmus, non habens necessitatem, potestatem autem habens suæ voluntatis, et hoc judicavit in corde suo, servare virginem suam, bene facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 38, 'Igitur et qui matrimonio jungit virginem suam, bene facit: et qui non jungit, melius facit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 39, 'Mulier alligata est legi quanto tempore vir ejus vivit, quod si dormierit vir ejus, liberata est: cui vult nubat, tantum in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 7, 40, 'Beatior autem erit si sic permanserit secundum meum consilium: puto autem quod et ego Spiritum Dei habeam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 1, 'De iis autem quæ idolis sacrificantur, scimus quia omnes scientiam habemus. Scientia inflat, caritas vero ædificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 2, 'Si quis autem se existimat scire aliquid, nondum cognovit quemadmodum oporteat eum scire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 3, 'Si quis autem diligit Deum, hic cognitus est ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 4, 'De escis autem quæ idolis immolantur, scimus quia nihil est idolum in mundo, et quod nullus est Deus, nisi unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 5, 'Nam etsi sunt qui dicantur dii sive in cælo, sive in terra (siquidem sunt dii multi, et domini multi):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 6, 'nobis tamen unus est Deus, Pater, ex quo omnia, et nos in illum: et unus Dominus Jesus Christus, per quem omnia, et nos per ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 7, 'Sed non in omnibus est scientia. Quidam autem cum conscientia usque nunc idoli, quasi idolothytum manducant: et conscientia ipsorum cum sit infirma, polluitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 8, 'Esca autem nos non commendat Deo. Neque enim si manducaverimus, abundabimus: neque si non manducaverimus, deficiemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 9, 'Videte autem ne forte hæc licentia vestra offendiculum fiat infirmis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 10, 'Si enim quis viderit eum, qui habet scientiam, in idolio recumbentem: nonne conscientia ejus, cum sit infirma, ædificabitur ad manducandum idolothyta?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 11, 'Et peribit infirmus in tua scientia, frater, propter quem Christus mortuus est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 12, 'Sic autem peccantes in fratres, et percutientes conscientiam eorum infirmam, in Christum peccatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 8, 13, 'Quapropter si esca scandalizat fratrem meum, non manducabo carnem in æternum, ne fratrem meum scandalizem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 1, 'Non sum liber? non sum Apostolus? nonne Christum Jesum Dominum nostrum vidi? nonne opus meum vos estis in Domino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 2, 'Et si aliis non sum Apostolus, sed tamen vobis sum: nam signaculum apostolatus mei vos estis in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 3, 'Mea defensio apud eos qui me interrogant, hæc est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 4, 'Numquid non habemus potestatem manducandi et bibendi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 5, 'numquid non habemus potestatem mulierem sororem circumducendi sicut et ceteri Apostoli, et fratres Domini, et Cephas?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 6, 'aut ego solus, et Barnabas, non habemus potestatem hoc operandi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 7, 'Quis militat suis stipendiis umquam? quis plantat vineam, et de fructu ejus non edit? quis pascit gregem, et de lacte gregis non manducat?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 8, 'Numquid secundum hominem hæc dico? an et lex hæc non dicit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 9, 'Scriptum est enim in lege Moysi: Non alligabis os bovi trituranti. Numquid de bobus cura est Deo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 10, 'an propter nos utique hoc dicit? Nam propter nos scripta sunt: quoniam debet in spe qui arat, arare: et qui triturat, in spe fructus percipiendi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 11, 'Si nos vobis spiritualia seminavimus, magnum est si nos carnalia vestra metamus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 12, 'Si alii potestatis vestræ participes sunt, quare non potius nos? Sed non usi sumus hac potestate: sed omnia sustinemus, ne quod offendiculum demus Evangelio Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 13, 'Nescitis quoniam qui in sacrario operantur quæ de sacrario sunt, edunt: et qui altari deserviunt, cum altari participant?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 14, 'Ita et Dominus ordinavit iis qui Evangelium annuntiant, de Evangelio vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 15, 'Ego autem nullo horum usus sum. Non autem scripsi hæc ut ita fiant in me: bonum est enim mihi magis mori, quam ut gloriam meam quis evacuet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 16, 'Nam si evangelizavero, non est mihi gloria: necessitas enim mihi incumbit: væ enim mihi est, si non evangelizavero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 17, 'Si enim volens hoc ago, mercedem habeo: si autem invitus, dispensatio mihi credita est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 18, 'Quæ est ergo merces mea? ut Evangelium prædicans, sine sumptu ponam Evangelium, ut non abutar potestate mea in Evangelio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 19, 'Nam cum liber essem ex omnibus, omnium me servum feci, ut plures lucrifacerem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 20, 'Et factus sum Judæis tamquam Judæus, ut Judæos lucrarer:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 21, 'iis qui sub lege sunt, quasi sub lege essem (cum ipse non essem sub lege) ut eos qui sub lege erant, lucrifacerem: iis qui sine lege erant, tamquam sine lege essem (cum sine lege Dei non essem: sed in lege essem Christi) ut lucrifacerem eos qui sine lege erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 22, 'Factus sum infirmis infirmus, ut infirmos lucrifacerem. Omnibus omnia factus sum, ut omnes facerem salvos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 23, 'Omnia autem facio propter Evangelium: ut particeps ejus efficiar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 24, 'Nescitis quod ii qui in stadio currunt, omnes quidem currunt, sed unus accipit bravium? Sic currite ut comprehendatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 25, 'Omnis autem qui in agone contendit, ab omnibus se abstinet, et illi quidem ut corruptibilem coronam accipiant: nos autem incorruptam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 26, 'Ego igitur sic curro, non quasi in incertum: sic pugno, non quasi aërem verberans:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 9, 27, 'sed castigo corpus meum, et in servitutem redigo: ne forte cum aliis prædicaverim, ipse reprobus efficiar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 1, 'Nolo enim vos ignorare fratres, quoniam patres nostri omnes sub nube fuerunt, et omnes mare transierunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 2, 'et omnes in Moyse baptizati sunt in nube, et in mari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 3, 'et omnes eamdem escam spiritalem manducaverunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 4, 'et omnes eumdem potum spiritalem biberunt (bibebant autem de spiritali, consequente eos, petra: petra autem erat Christus):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 5, 'sed non in pluribus eorum beneplacitum est Deo: nam prostrati sunt in deserto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 6, 'Hæc autem in figura facta sunt nostri, ut non simus concupiscentes malorum, sicut et illi concupierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 7, 'Neque idololatræ efficiamini, sicut quidam ex ipsis: quemadmodum scriptum est: Sedit populus manducare, et bibere, et surrexerunt ludere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 8, 'Neque fornicemur, sicut quidam ex ipsis fornicati sunt, et ceciderunt una die viginti tria millia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 9, 'Neque tentemus Christum, sicut quidam eorum tentaverunt, et a serpentibus perierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 10, 'Neque murmuraveritis, sicut quidam eorum murmuraverunt, et perierunt ab exterminatore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 11, 'Hæc autem omnia in figura contingebant illis: scripta sunt autem ad correptionem nostram, in quos fines sæculorum devenerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 12, 'Itaque qui se existimat stare, videat ne cadat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 13, 'Tentatio vos non apprehendat nisi humana: fidelis autem Deus est, qui non patietur vos tentari supra id quod potestis, sed faciet etiam cum tentatione proventum ut possitis sustinere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 14, 'Propter quod, carissimi mihi, fugite ab idolorum cultura:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 15, 'ut prudentibus loquor, vos ipsi judicate quod dico.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 16, 'Calix benedictionis, cui benedicimus, nonne communicatio sanguinis Christi est? et panis quem frangimus, nonne participatio corporis Domini est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 17, 'Quoniam unus panis, unum corpus multi sumus, omnes qui de uno pane participamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 18, 'Videte Israël secundum carnem: nonne qui edunt hostias, participes sunt altaris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 19, 'Quid ergo? dico quod idolis immolatum sit aliquid? aut quod idolum, sit aliquid?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 20, 'Sed quæ immolant gentes, dæmoniis immolant, et non Deo. Nolo autem vos socios fieri dæmoniorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 21, 'non potestis calicem Domini bibere, et calicem dæmoniorum; non potestis mensæ Domini participes esse, et mensæ dæmoniorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 22, 'An æmulamur Dominum? numquid fortiores illo sumus? Omnia mihi licent, sed non omnia expediunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 23, 'Omnia mihi licent, sed non omnia ædificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 24, 'Nemo quod suum est quærat, sed quod alterius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 25, 'Omne quod in macello venit, manducate, nihil interrogantes propter conscientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 26, 'Domini est terra, et plenitudo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 27, 'Si quis vocat vos infidelium, et vultis ire: omne quod vobis apponitur, manducate, nihil interrogantes propter conscientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 28, 'Si quis autem dixerit: Hoc immolatum est idolis: nolite manducare propter illum qui indicavit, et propter conscientiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 29, 'conscientiam autem dico non tuam, sed alterius. Ut quid enim libertas mea judicatur ab aliena conscientia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 30, 'Si ego cum gratia participo, quid blasphemor pro eo quod gratias ago?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 31, 'Sive ergo manducatis, sive bibitis, sive aliud quid facitis: omnia in gloriam Dei facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 32, 'Sine offensione estote Judæis, et gentibus, et ecclesiæ Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 10, 33, 'sicut et ego per omnia omnibus placeo, non quærens quod mihi utile est, sed quod multis: ut salvi fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 1, 'Imitatores mei estote, sicut et ego Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 2, 'Laudo autem vos fratres quod per omnia mei memores estis: et sicut tradidi vobis, præcepta mea tenetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 3, 'Volo autem vos scire quod omnis viri caput, Christus est: caput autem mulieris, vir: caput vero Christi, Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 4, 'Omnis vir orans, aut prophetans velato capite, deturpat caput suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 5, 'Omnis autem mulier orans, aut prophetans non velato capite, deturpat caput suum: unum enim est ac si decalvetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 6, 'Nam si non velatur mulier, tondeatur. Si vero turpe est mulieri tonderi, aut decalvari, velet caput suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 7, 'Vir quidem non debet velare caput suum: quoniam imago et gloria Dei est, mulier autem gloria viri est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 8, 'Non enim vir ex muliere est, sed mulier ex viro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 9, 'Etenim non est creatus vir propter mulierem, sed mulier propter virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 10, 'Ideo debet mulier potestatem habere supra caput propter angelos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 11, 'Verumtamen neque vir sine muliere: neque mulier sine viro in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 12, 'Nam sicut mulier de viro, ita et vir per mulierem: omnia autem ex Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 13, 'Vos ipsi judicate: decet mulierem non velatam orare Deum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 14, 'Nec ipsa natura docet vos, quod vir quidem si comam nutriat, ignominia est illi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 15, 'mulier vero si comam nutriat, gloria est illi: quoniam capilli pro velamine ei dati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 16, 'Si quis autem videtur contentiosus esse: nos talem consuetudinem non habemus, neque ecclesia Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 17, 'Hoc autem præcipio: non laudans quod non in melius, sed in deterius convenitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 18, 'Primum quidem convenientibus vobis in ecclesiam, audio scissuras esse inter vos, et ex parte credo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 19, 'Nam oportet et hæreses esse, ut et qui probati sunt, manifesti fiant in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 20, 'Convenientibus ergo vobis in unum, jam non est Dominicam cœnam manducare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 21, 'Unusquisque enim suam cœnam præsumit ad manducandum, et alius quidem esurit, alius autem ebrius est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 22, 'Numquid domos non habetis ad manducandum, et bibendum? aut ecclesiam Dei contemnitis, et confunditis eos qui non habent? Quid dicam vobis? laudo vos? in hoc non laudo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 23, 'Ego enim accepi a Domino quod et tradidi vobis, quoniam Dominus Jesus in qua nocte tradebatur, accepit panem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 24, 'et gratias agens fregit, et dixit: Accipite, et manducate: hoc est corpus meum, quod pro vobis tradetur: hoc facite in meam commemorationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 25, 'Similiter et calicem, postquam cœnavit, dicens: Hic calix novum testamentum est in meo sanguine: hoc facite quotiescumque bibetis, in meam commemorationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 26, 'Quotiescumque enim manducabitis panem hunc, et calicem bibetis, mortem Domini annuntiabitis donec veniat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 27, 'Itaque quicumque manducaverit panem hunc, vel biberit calicem Domini indigne, reus erit corporis et sanguinis Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 28, 'Probet autem seipsum homo: et sic de pane illo edat, et de calice bibat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 29, 'Qui enim manducat et bibit indigne, judicium sibi manducat et bibit, non dijudicans corpus Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 30, 'Ideo inter vos multi infirmi et imbecilles, et dormiunt multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 31, 'Quod si nosmetipsos dijudicaremus, non utique judicaremur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 32, 'Dum judicamur autem, a Domino corripimur, ut non cum hoc mundo damnemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 33, 'Itaque fratres mei, cum convenitis ad manducandum, invicem exspectate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 11, 34, 'Si quis esurit, domi manducet, ut non in judicium conveniatis. Cetera autem, cum venero, disponam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 1, 'De spiritualibus autem, nolo vos ignorare fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 2, 'Scitis quoniam cum gentes essetis, ad simulacra muta prout ducebamini euntes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 3, 'Ideo notum vobis facio, quod nemo in Spiritu Dei loquens, dicit anathema Jesu. Et nemo potest dicere, Dominus Jesus, nisi in Spiritu Sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 4, 'Divisiones vero gratiarum sunt, idem autem Spiritus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 5, 'et divisiones ministrationum sunt, idem autem Dominus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 6, 'et divisiones operationum sunt, idem vero Deus qui operatur omnia in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 7, 'Unicuique autem datur manifestatio Spiritus ad utilitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 8, 'Alii quidem per Spiritum datur sermo sapientiæ: alii autem sermo scientiæ secundum eumdem Spiritum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 9, 'alteri fides in eodem Spiritu: alii gratia sanitatum in uno Spiritu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 10, 'alii operatio virtutum, alii prophetia, alii discretio spirituum, alii genera linguarum, alii interpretatio sermonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 11, 'Hæc autem omnia operatur unus atque idem Spiritus, dividens singulis prout vult.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 12, 'Sicut enim corpus unum est, et membra habet multa, omnia autem membra corporis cum sint multa, unum tamen corpus sunt: ita et Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 13, 'Etenim in uno Spiritu omnes nos in unum corpus baptizati sumus, sive Judæi, sive gentiles, sive servi, sive liberi: et omnes in uno Spiritu potati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 14, 'Nam et corpus non est unum membrum, sed multa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 15, 'Si dixerit pes: Quoniam non sum manus, non sum de corpore: num ideo non est de corpore?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 16, 'Et si dixerit auris: Quoniam non sum oculus, non sum de corpore: num ideo est de corpore?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 17, 'Si totum corpus oculus: ubi auditus? Si totum auditus: ubi odoratus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 18, 'Nunc autem posuit Deus membra, unumquodque eorum in corpore sicut voluit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 19, 'Quod si essent omnia unum membrum, ubi corpus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 20, 'Nunc autem multa quidem membra, unum autem corpus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 21, 'Non potest autem oculus dicere manui: Opera tua non indigeo: aut iterum caput pedibus: Non estis mihi necessarii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 22, 'Sed multo magis quæ videntur membra corporis infirmiora esse, necessariora sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 23, 'et quæ putamus ignobiliora membra esse corporis, his honorem abundantiorem circumdamus: et quæ inhonesta sunt nostra, abundantiorem honestatem habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 24, 'Honesta autem nostra nullius egent: sed Deus temperavit corpus, ei cui deerat, abundantiorem tribuendo honorem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 25, 'ut non sit schisma in corpore, sed idipsum pro invicem sollicita sint membra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 26, 'Et si quid patitur unum membrum, compatiuntur omnia membra: sive gloriatur unum membrum, congaudent omnia membra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 27, 'Vos autem estis corpus Christi, et membra de membro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 28, 'Et quosdam quidem posuit Deus in ecclesia primum apostolos, secundo prophetas, exinde doctores, deinde virtutes, exinde gratias curationum, opitulationes, gubernationes, genera linguarum, interpretationes sermonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 29, 'Numquid omnes apostoli? numquid omnes prophetæ? numquid omnes doctores?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 30, 'numquid omnes virtutes? numquid omnes gratiam habent curationum? numquid omnes linguis loquuntur? numquid omnes interpretantur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 12, 31, '\'mulamini autem charismata meliora. Et adhuc excellentiorem viam vobis demonstro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 1, 'Si linguis hominum loquar, et angelorum, caritatem autem non habeam, factus sum velut æs sonans, aut cymbalum tinniens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 2, 'Et si habuero prophetiam, et noverim mysteria omnia, et omnem scientiam: et si habuero omnem fidem ita ut montes transferam, caritatem autem non habuero, nihil sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 3, 'Et si distribuero in cibos pauperum omnes facultates meas, et si tradidero corpus meum ita ut ardeam, caritatem autem non habuero, nihil mihi prodest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 4, 'Caritas patiens est, benigna est. Caritas non æmulatur, non agit perperam, non inflatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 5, 'non est ambitiosa, non quærit quæ sua sunt, non irritatur, non cogitat malum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 6, 'non gaudet super iniquitate, congaudet autem veritati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 7, 'omnia suffert, omnia credit, omnia sperat, omnia sustinet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 8, 'Caritas numquam excidit: sive prophetiæ evacuabuntur, sive linguæ cessabunt, sive scientia destruetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 9, 'Ex parte enim cognoscimus, et ex parte prophetamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 10, 'Cum autem venerit quod perfectum est, evacuabitur quod ex parte est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 11, 'Cum essem parvulus, loquebar ut parvulus, sapiebam ut parvulus, cogitabam ut parvulus. Quando autem factus sum vir, evacuavi quæ erant parvuli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 12, 'Videmus nunc per speculum in ænigmate: tunc autem facie ad faciem. Nunc cognosco ex parte: tunc autem cognoscam sicut et cognitus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 13, 13, 'Nunc autem manent fides, spes, caritas, tria hæc: major autem horum est caritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 1, 'Sectamini caritatem, æmulamini spiritualia: magis autem ut prophetetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 2, 'Qui enim loquitur lingua, non hominibus loquitur, sed Deo: nemo enim audit. Spiritu autem loquitur mysteria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 3, 'Nam qui prophetat, hominibus loquitur ad ædificationem, et exhortationem, et consolationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 4, 'Qui loquitur lingua, semetipsum ædificat: qui autem prophetat, ecclesiam Dei ædificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 5, 'Volo autem omnes vos loqui linguis: magis autem prophetare. Nam major est qui prophetat, quam qui loquitur linguis; nisi forte interpretetur ut ecclesia ædificationem accipiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 6, 'Nunc autem, fratres, si venero ad vos linguis loquens: quid vobis prodero, nisi vobis loquar aut in revelatione, aut in scientia, aut in prophetia, aut in doctrina?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 7, 'Tamen quæ sine anima sunt vocem dantia, sive tibia, sive cithara; nisi distinctionem sonituum dederint, quomodo scietur id quod canitur, aut quod citharizatur?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 8, 'Etenim si incertam vocem det tuba, quis parabit se ad bellum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 9, 'Ita et vos per linguam nisi manifestum sermonem dederitis: quomodo scietur id quod dicitur? eritis enim in aëra loquentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 10, 'Tam multa, ut puta genera linguarum sunt in hoc mundo: et nihil sine voce est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 11, 'Si ergo nesciero virtutem vocis, ero ei, cui loquor, barbarus: et qui loquitur, mihi barbarus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 12, 'Sic et vos, quoniam æmulatores estis spirituum, ad ædificationem ecclesiæ quærite ut abundetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 13, 'Et ideo qui loquitur lingua, oret ut interpretetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 14, 'Nam si orem lingua, spiritus meus orat, mens autem mea sine fructu est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 15, 'Quid ergo est? Orabo spiritu, orabo et mente: psallam spiritu, psallam et mente.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 16, 'Ceterum si benedixeris spiritu, qui supplet locum idiotæ, quomodo dicet: Amen, super tuam benedictionem? quoniam quid dicas, nescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 17, 'Nam tu quidem bene gratias agis, sed alter non ædificatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 18, 'Gratias ago Deo meo, quod omnium vestrum lingua loquor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 19, 'Sed in ecclesia volo quinque verba sensu meo loqui, ut et alios instruam: quam decem millia verborum in lingua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 20, 'Fratres, nolite pueri effici sensibus, sed malitia parvuli estote: sensibus autem perfecti estote.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 21, 'In lege scriptum est: Quoniam in aliis linguis et labiis aliis loquar populo huic: et nec sic exaudient me, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 22, 'Itaque linguæ in signum sunt non fidelibus, sed infidelibus: prophetiæ autem non infidelibus, sed fidelibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 23, 'Si ergo conveniat universa ecclesia in unum, et omnes linguis loquantur, intrent autem idiotæ, aut infideles: nonne dicent quod insanitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 24, 'Si autem omnes prophetent, intret autem quis infidelis, vel idiota, convincitur ab omnibus, dijudicatur ab omnibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 25, 'occulta cordis ejus manifesta fiunt: et ita cadens in faciem adorabit Deum, pronuntians quod vere Deus in vobis sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 26, 'Quid ergo est, fratres? Cum convenitis, unusquisque vestrum psalmum habet, doctrinam habet, apocalypsim habet, linguam habet, interpretationem habet: omnia ad ædificationem fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 27, 'Sive lingua quis loquitur, secundum duos, aut ut multum tres, et per partes, et unus interpretatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 28, 'Si autem non fuerit interpres, taceat in ecclesia: sibi autem loquatur, et Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 29, 'Prophetæ autem duo, aut tres dicant, et ceteri dijudicent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 30, 'Quod si alii revelatum fuerit sedenti, prior taceat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 31, 'Potestis enim omnes per singulos prophetare: ut omnes discant, et omnes exhortentur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 32, 'et spiritus prophetarum prophetis subjecti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 33, 'Non enim est dissensionis Deus, sed pacis: sicut et in omnibus ecclesiis sanctorum doceo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 34, 'Mulieres in ecclesiis taceant, non enim permittitur eis loqui, sed subditas esse, sicut et lex dicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 35, 'Si quid autem volunt discere, domi viros suos interrogent. Turpe est enim mulieri loqui in ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 36, 'An a vobis verbum Dei processit? aut in vos solos pervenit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 37, 'Si quis videtur propheta esse, aut spiritualis, cognoscat quæ scribo vobis, quia Domini sunt mandata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 38, 'Si quis autem ignorat, ignorabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 39, 'Itaque fratres æmulamini prophetare: et loqui linguis nolite prohibere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 14, 40, 'Omnia autem honeste, et secundum ordinem fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 1, 'Notum autem vobis facio, fratres, Evangelium, quod prædicavi vobis, quod et accepistis, in quo et statis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 2, 'per quod et salvamini: qua ratione prædicaverim vobis, si tenetis, nisi frustra credidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 3, 'Tradidi enim vobis in primis quod et accepi: quoniam Christus mortuus est pro peccatis nostris secundum Scripturas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 4, 'et quia sepultus est, et quia resurrexit tertia die secundum Scripturas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 5, 'et quia visus est Cephæ, et post hoc undecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 6, 'deinde visus est plus quam quingentis fratribus simul: ex quibus multi manent usque adhuc, quidam autem dormierunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 7, 'deinde visus est Jacobo, deinde Apostolis omnibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 8, 'novissime autem omnium tamquam abortivo, visus est et mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 9, 'Ego enim sum minimus Apostolorum, qui non sum dignus vocari Apostolus, quoniam persecutus sum ecclesiam Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 10, 'Gratia autem Dei sum id quod sum, et gratia ejus in me vacua non fuit, sed abundantius illis omnibus laboravi: non ego autem, sed gratia Dei mecum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 11, 'sive enim ego, sive illi: sic prædicamus, et sic credidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 12, 'Si autem Christus prædicatur quod resurrexit a mortuis, quomodo quidam dicunt in vobis, quoniam resurrectio mortuorum non est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 13, 'Si autem resurrectio mortuorum non est: neque Christus resurrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 14, 'Si autem Christus non resurrexit, inanis est ergo prædicatio nostra, inanis est et fides vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 15, 'invenimur autem et falsi testes Dei: quoniam testimonium diximus adversus Deum quod suscitaverit Christum, quem non suscitavit, si mortui non resurgunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 16, 'Nam si mortui non resurgunt, neque Christus resurrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 17, 'Quod si Christus non resurrexit, vana est fides vestra: adhuc enim estis in peccatis vestris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 18, 'Ergo et qui dormierunt in Christo, perierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 19, 'Si in hac vita tantum in Christo sperantes sumus, miserabiliores sumus omnibus hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 20, 'Nunc autem Christus resurrexit a mortuis primitiæ dormientium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 21, 'quoniam quidem per hominem mors, et per hominem resurrectio mortuorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 22, 'Et sicut in Adam omnes moriuntur, ita et in Christo omnes vivificabuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 23, 'Unusquisque autem in suo ordine, primitiæ Christus: deinde ii qui sunt Christi, qui in adventu ejus crediderunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 24, 'Deinde finis: cum tradiderit regnum Deo et Patri, cum evacuaverit omnem principatum, et potestatem, et virtutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 25, 'Oportet autem illum regnare donec ponat omnes inimicos sub pedibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 26, 'Novissima autem inimica destruetur mors: omnia enim subjecit pedibus ejus. Cum autem dicat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 27, 'Omnia subjecta sunt ei, sine dubio præter eum qui subjecit ei omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 28, 'Cum autem subjecta fuerint illi omnia: tunc et ipse Filius subjectus erit ei, qui subjecit sibi omnia, ut sit Deus omnia in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 29, 'Alioquin quid facient qui baptizantur pro mortuis, si omnino mortui non resurgunt? ut quid et baptizantur pro illis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 30, 'ut quid et nos periclitamur omni hora?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 31, 'Quotidie morior per vestram gloriam, fratres, quam habeo in Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 32, 'Si secundum hominem ad bestias pugnavi Ephesi, quid mihi prodest, si mortui non resurgunt? Manducemus, et bibamus, cras enim moriemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 33, 'Nolite seduci: corrumpunt mores bonos colloquia mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 34, 'Evigilate justi, et nolite peccare: ignorantiam enim Dei quidam habent, ad reverentiam vobis loquor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 35, 'Sed dicet aliquis: Quomodo resurgunt mortui? qualive corpore venient?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 36, 'Insipiens, tu quod seminas non vivificatur, nisi prius moriatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 37, 'et quod seminas, non corpus, quod futurum est, seminas, sed nudum granum, ut puta tritici, aut alicujus ceterorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 38, 'Deus autem dat illi corpus sicut vult: ut unicuique seminum proprium corpus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 39, 'Non omnis caro, eadem caro: sed alia quidem hominum, alia vero pecorum, alia volucrum, alia autem piscium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 40, 'Et corpora cælestia, et corpora terrestria: sed alia quidem cælestium gloria, alia autem terrestrium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 41, 'Alia claritas solis, alia claritas lunæ, et alia claritas stellarum. Stella enim a stella differt in claritate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 42, 'sic et resurrectio mortuorum. Seminatur in corruptione, surget in incorruptione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 43, 'Seminatur in ignobilitate, surget in gloria: seminatur in infirmitate, surget in virtute:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 44, 'seminatur corpus animale, surget corpus spiritale. Si est corpus animale, est et spiritale, sicut scriptum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 45, 'Factus est primus homo Adam in animam viventem, novissimus Adam in spiritum vivificantem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 46, 'Sed non prius quod spiritale est, sed quod animale: deinde quod spiritale.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 47, 'Primus homo de terra, terrenus: secundus homo de cælo, cælestis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 48, 'Qualis terrenus, tales et terreni: et qualis cælestis, tales et cælestes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 49, 'Igitur, sicut portavimus imaginem terreni, portemus et imaginem cælestis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 50, 'Hoc autem dico, fratres: quia caro et sanguis regnum Dei possidere non possunt: neque corruptio incorruptelam possidebit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 51, 'Ecce mysterium vobis dico: omnes quidem resurgemus, sed non omnes immutabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 52, 'In momento, in ictu oculi, in novissima tuba: canet enim tuba, et mortui resurgent incorrupti: et nos immutabimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 53, 'Oportet enim corruptibile hoc induere incorruptionem: et mortale hoc induere immortalitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 54, 'Cum autem mortale hoc induerit immortalitatem, tunc fiet sermo, qui scriptus est: Absorpta est mors in victoria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 55, 'Ubi est mors victoria tua? ubi est mors stimulus tuus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 56, 'Stimulus autem mortis peccatum est: virtus vero peccati lex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 57, 'Deo autem gratias, qui dedit nobis victoriam per Dominum nostrum Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 15, 58, 'Itaque fratres mei dilecti, stabiles estote, et immobiles: abundantes in opere Domini semper, scientes quod labor vester non est inanis in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 1, 'De collectis autem, quæ fiunt in sanctos, sicut ordinavi ecclesiis Galatiæ, ita et vos facite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 2, 'Per unam sabbati unusquisque vestrum apud se seponat, recondens quod ei bene placuerit: ut non, cum venero, tunc collectæ fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 3, 'Cum autem præsens fuero, quos probaveritis per epistolas, hos mittam perferre gratiam vestram in Jerusalem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 4, 'Quod si dignum fuerit ut et ego eam, mecum ibunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 5, 'Veniam autem ad vos, cum Macedoniam pertransiero: nam Macedoniam pertransibo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 6, 'Apud vos autem forsitan manebo, vel etiam hiemabo: ut vos me deducatis quocumque iero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 7, 'Nolo enim vos modo in transitu videre, spero enim me aliquantulum temporis manere apud vos, si Dominus permiserit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 8, 'Permanebo autem Ephesi usque ad Pentecosten.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 9, 'Ostium enim mihi apertum est magnum, et evidens: et adversarii multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 10, 'Si autem venerit Timotheus, videte ut sine timore sit apud vos: opus enim Domini operatur, sicut et ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 11, 'Ne quis ergo illum spernat: deducite autem illum in pace, ut veniat ad me: exspecto enim illum cum fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 12, 'De Apollo autem fratre vobis notum facio, quoniam multum rogavi eum ut veniret ad vos cum fratribus: et utique non fuit voluntas ut nunc veniret: veniet autem, cum ei vacuum fuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 13, 'Vigilate, state in fide, viriliter agite, et confortamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 14, 'Omnia vestra in caritate fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 15, 'Obsecro autem vos fratres, nostis domum Stephanæ, et Fortunati, et Achaici: quoniam sunt primitiæ Achaiæ, et in ministerium sanctorum ordinaverunt seipsos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 16, 'ut et vos subditi sitis ejusmodi, et omni cooperanti, et laboranti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 17, 'Gaudeo autem in præsentia Stephanæ, et Fortunati, et Achaici: quoniam id, quod vobis deerat, ipsi suppleverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 18, 'refecerunt enim et meum spiritum, et vestrum. Cognoscite ergo qui hujusmodi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 19, 'Salutant vos ecclesiæ Asiæ. Salutant vos in Domino multum, Aquila et Priscilla cum domestica sua ecclesia: apud quos et hospitor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 20, 'Salutant vos omnes fratres. Salutate invicem in osculo sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 21, 'Salutatio, mea manu Pauli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 22, 'Si quis non amat Dominum nostrum Jesum Christum, sit anathema, Maran Atha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 23, 'Gratia Domini nostri Jesu Christi vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 16, 24, 'Caritas mea cum omnibus vobis in Christo Jesu. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, Apostolus Jesu Christi per voluntatem Dei, et Timotheus frater, ecclesiæ Dei, quæ est Corinthi cum omnibus sanctis, qui sunt in universa Achaia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Benedictus Deus et Pater Domini nostri Jesu Christi, Pater misericordiarum, et Deus totius consolationis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'qui consolatur nos in omni tribulatione nostra: ut possimus et ipsi consolari eos qui in omni pressura sunt, per exhortationem, qua exhortamur et ipsi a Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Quoniam sicut abundant passiones Christi in nobis: ita et per Christum abundat consolatio nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Sive autem tribulamur pro vestra exhortatione et salute, sive consolamur pro vestra consolatione, sive exhortamur pro vestra exhortatione et salute, quæ operatur tolerantiam earumdem passionum, quas et nos patimur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'ut spes nostra firma sit pro vobis: scientes quod sicut socii passionum estis, sic eritis et consolationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Non enim volumus ignorare vos, fratres, de tribulatione nostra, quæ facta est in Asia, quoniam supra modum gravati sumus supra virtutem, ita ut tæderet nos etiam vivere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Sed ipsi in nobismetipsis responsum mortis habuimus, ut non simus fidentes in nobis, sed in Deo, qui suscitat mortuos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'qui de tantis periculis nos eripuit, et eruit: in quem speramus quoniam et adhuc eripiet,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'adjuvantibus et vobis in oratione pro nobis: ut ex multorum personis, ejus quæ in nobis est donationis, per multos gratiæ agantur pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Nam gloria nostra hæc est: testimonium conscientiæ nostræ, quod in simplicitate cordis et sinceritate Dei, et non in sapientia carnali, sed in gratia Dei, conversati sumus in hoc mundo: abundantius autem ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Non enim alia scribimus vobis, quam quæ legistis, et cognovistis. Spero autem quod usque in finem cognoscetis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'sicut et cognovistis nos ex parte, quod gloria vestra sumus, sicut et vos nostra, in die Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Et hac confidentia volui prius venire ad vos, ut secundam gratiam haberetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'et per vos transire in Macedoniam, et iterum a Macedonia venire ad vos, et a vobis deduci in Judæam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Cum ergo hoc voluissem, numquid levitate usus sum? aut quæ cogito, secundum carnem cogito, ut sit apud me Est et Non?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Fidelis autem Deus, quia sermo noster, qui fuit apud vos, non est in illo Est et Non.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Dei enim Filius Jesus Christus, qui in vobis per nos prædicatus est, per me, et Silvanum, et Timotheum, non fuit Est et Non, sed Est in illo fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Quotquot enim promissiones Dei sunt, in illo Est: ideo et per ipsum Amen Deo ad gloriam nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 21, 'Qui autem confirmat nos vobiscum in Christo, et qui unxit nos Deus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 22, 'qui et signavit nos, et dedit pignus Spiritus in cordibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 23, 'Ego autem testem Deum invoco in animam meam, quod parcens vobis, non veni ultra Corinthum: non quia dominamur fidei vestæ, sed adjutores sumus gaudii vestri: nam fide statis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 24, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Statui autem hoc ipsum apud me, ne iterum in tristitia venirem ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Si enim ego contristo vos: et quis est, qui me lætificet, nisi qui contristatur ex me?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Et hoc ipsum scripsi vobis, ut non cum venero, tristitiam super tristitiam habeam, de quibus oportuerat me gaudere: confidens in omnibus vobis, quia meum gaudium, omnium vestrum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Nam ex multa tribulatione et angustia cordis scripsi vobis per multas lacrimas: non ut contristemini, sed ut sciatis, quam caritatem habeam abundantius in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Si quis autem contristavit, non me contristavit: sed ex parte, ut non onerem omnes vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Sufficit illi, qui ejusmodi est, objurgatio hæc, quæ fit a pluribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'ita ut e contrario magis donetis, et consolemini, ne forte abundantiori tristitia absorbeatur qui ejusmodi est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Propter quod obsecro vos, ut confirmetis in illum caritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Ideo enim et scripsi, ut cognoscam experimentum vestrum, an in omnibus obedientes sitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Cui autem aliquid donastis, et ego: nam et ego quod donavi, si quid donavi, propter vos in persona Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'ut non circumveniamur a Satana: non enim ignoramus cogitationes ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Cum venissem autem Troadem propter Evangelium Christi, et ostium mihi apertum esset in Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'non habui requiem spiritui meo, eo quod non invenerim Titum fratrem meum, sed valefaciens eis, profectus sum in Macedoniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Deo autem gratias, qui semper triumphat nos in Christo Jesu, et odorem notitiæ suæ manifestat per nos in omni loco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'quia Christi bonus odor sumus Deo in iis qui salvi fiunt, et in iis qui pereunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 16, 'aliis quidem odor mortis in mortem: aliis autem odor vitæ in vitam. Et ad hæc quis tam idoneus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 17, 'non enim sumus sicut plurimi, adulterantes verbum Dei, sed ex sinceritate, sed sicut ex Deo, coram Deo, in Christo loquimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Incipimus iterum nosmetipsos commendare? aut numquid egemus (sicut quidam) commendatitiis epistolis ad vos, aut ex vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Epistola nostra vos estis, scripta in cordibus nostris, quæ scitur, et legitur ab omnibus hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'manifestati quod epistola estis Christi, ministrata a nobis, et scripta non atramento, sed Spiritu Dei vivi: non in tabulis lapideis, sed in tabulis cordis carnalibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Fiduciam autem talem habemus per Christum ad Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'non quod sufficientes simus cogitare aliquid a nobis, quasi ex nobis: sed sufficientia nostra ex Deo est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'qui et idoneos nos fecit ministros novi testamenti: non littera, sed Spiritu: littera enim occidit, Spiritus autem vivificat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Quod si ministratio mortis litteris deformata in lapidibus fuit in gloria, ita ut non possent intendere filii Israël in faciem Moysi propter gloriam vultus ejus, quæ evacuatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'quomodo non magis ministratio Spiritus erit in gloria?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Nam si ministratio damnationis gloria est: multo magis abundat ministerium justitiæ in gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Nam nec glorificatum est, quod claruit in hac parte, propter excellentem gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Si enim quod evacuatur, per gloriam est: multo magis quod manet, in gloria est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Habentes igitur talem spem, multa fiducia utimur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'et non sicut Moyses ponebat velamen super faciem suam, ut non intenderent filii Israël in faciem ejus, quod evacuatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'sed obtusi sunt sensus eorum. Usque in hodiernum enim diem, idipsum velamen in lectione veteris testamenti manet non revelatum (quoniam in Christo evacuatur),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'sed usque in hodiernum diem, cum legitur Moyses, velamen positum est super cor eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Cum autem conversus fuerit ad Dominum, auferetur velamen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 17, 'Dominus autem Spiritus est: ubi autem Spiritus Domini, ibi libertas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 18, 'Nos vero omnes, revelata facie gloriam Domini speculantes, in eamdem imaginem transformamur a claritate in claritatem, tamquam a Domini Spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Ideo habentes administrationem, juxta quod misericordiam consecuti sumus, non deficimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'sed abdicamus occulta dedecoris, non ambulantes in astutia, neque adulterantes verbum Dei, sed in manifestatione veritatis commendantes nosmetipsos ad omnem conscientiam hominum coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Quod si etiam opertum est Evangelium nostrum, in iis, qui pereunt, est opertum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'in quibus Deus hujus sæculi excæcavit mentes infidelium, ut non fulgeat illis illuminatio Evangelii gloriæ Christi, qui est imago Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Non enim nosmetipsos prædicamus, sed Jesum Christum Dominum nostrum: nos autem servos vestros per Jesum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'quoniam Deus, qui dixit de tenebris lucem splendescere, ipse illuxit in cordibus nostris ad illuminationem scientiæ claritatis Dei, in facie Christi Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Habemus autem thesaurum istum in vasis fictilibus: ut sublimitas sit virtutis Dei, et non ex nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'In omnibus tribulationem patimur, sed non angustiamur: aporiamur, sed non destituimur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'persecutionem patimur, sed non derelinquimur: dejicimur, sed non perimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'semper mortificationem Jesu in corpore nostro circumferentes, ut et vita Jesu manifestetur in corporibus nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Semper enim nos, qui vivimus, in mortem tradimur propter Jesum: ut et vita Jesu manifestetur in carne nostra mortali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Ergo mors in nobis operatur, vita autem in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Habentes autem eumdem spiritum fidei, sicut scriptum est: Credidi, propter quod locutus sum: et nos credimus, propter quod et loquimur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'scientes quoniam qui suscitavit Jesum, et nos cum Jesu suscitabit, et constituet vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Omnia enim propter vos: ut gratia abundans, per multos in gratiarum actione, abundet in gloriam Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Propter quod non deficimus: sed licet is, qui foris est, noster homo corrumpatur, tamen is, qui intus est, renovatur de die in diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 17, 'Id enim, quod in præsenti est momentaneum et leve tribulationis nostræ, supra modum in sublimitate æternum gloriæ pondus operatur in nobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 18, 'non contemplantibus nobis quæ videntur, sed quæ non videntur. Quæ enim videntur, temporalia sunt: quæ autem non videntur, æterna sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Scimus enim quoniam si terrestris domus nostra hujus habitationis dissolvatur, quod ædificationem ex Deo habemus, domum non manufactam, æternam in cælis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Nam et in hoc ingemiscimus, habitationem nostram, quæ de cælo est, superindui cupientes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'si tamen vestiti, non nudi inveniamur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Nam et qui sumus in hoc tabernaculo, ingemiscimus gravati: eo quod nolumus expoliari, sed supervestiri, ut absorbeatur quod mortale est, a vita.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Qui autem efficit nos in hoc ipsum, Deus, qui dedit nobis pignus Spiritus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Audentes igitur semper, scientes quoniam dum sumus in corpore, peregrinamur a Domino');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, '(per fidem enim ambulamus, et non per speciem):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'audemus autem, et bonam voluntatem habemus magis peregrinari a corpore, et præsentes esse ad Dominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Et ideo contendimus, sive absentes, sive præsentes, placere illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Omnes enim nos manifestari oportet ante tribunal Christi, ut referat unusquisque propria corporis, prout gessit, sive bonum, sive malum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Scientes ergo timorem Domini, hominibus suademus, Deo autem manifesti sumus. Spero autem et in conscientiis vestris manifestos nos esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Non iterum commendamus nos vobis, sed occasionem damus vobis gloriandi pro nobis: ut habeatis ad eos qui in facie gloriantur, et non in corde.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Sive enim mente excedimus Deo: sive sobrii sumus, vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Caritas enim Christi urget nos: æstimantes hoc, quoniam si unus pro omnibus mortuus est, ergo omnes mortui sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'et pro omnibus mortuus est Christus: ut, et qui vivunt, jam non sibi vivant, sed ei qui pro ipsis mortuus est et resurrexit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Itaque nos ex hoc neminem novimus secundum carnem. Et si cognovimus secundum carnem Christum, sed nunc jam non novimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Si qua ergo in Christo nova creatura, vetera transierunt: ecce facta sunt omnia nova.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Omnia autem ex Deo, qui nos reconciliavit sibi per Christum: et dedit nobis ministerium reconciliationis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'quoniam quidem Deus erat in Christo mundum reconcilians sibi, non reputans illis delicta ipsorum, et posuit in nobis verbum reconciliationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Pro Christo ergo legatione fungimur, tamquam Deo exhortante per nos. Obsecramus pro Christo, reconciliamini Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Eum, qui non noverat peccatum, pro nobis peccatum fecit, ut nos efficeremur justitia Dei in ipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Adjuvantes autem exhortamur ne in vacuum gratiam Dei recipiatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Ait enim: Tempore accepto exaudivi te, et in die salutis adjuvi te. Ecce nunc tempus acceptabile, ecce nunc dies salutis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Nemini dantes ullam offensionem, ut non vituperetur ministerium nostrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'sed in omnibus exhibeamus nosmetipsos sicut Dei ministros in multa patientia, in tribulationibus, in necessitatibus, in angustiis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'in plagis, in carceribus, in seditionibus, in laboribus, in vigiliis, in jejuniis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'in castitate, in scientia, in longanimitate, in suavitate, in Spiritu Sancto, in caritate non ficta,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'in verbo veritatis, in virtute Dei, per arma justitiæ a dextris et a sinistris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'per gloriam, et ignobilitatem, per infamiam, et bonam famam: ut seductores, et veraces, sicut qui ignoti, et cogniti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'quasi morientes, et ecce vivimus: ut castigati, et non mortificati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'quasi tristes, semper autem gaudentes: sicut egentes, multos autem locupletantes: tamquam nihil habentes, et omnia possidentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Os nostrum patet ad vos, o Corinthii; cor nostrum dilatatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Non angustiamini in nobis: angustiamini autem in visceribus vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'eamdem autem habentes remunerationem, tamquam filiis dico, dilatamini et vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Nolite jugum ducere cum infidelibus. Quæ enim participatio justitiæ cum iniquitate? aut quæ societas luci ad tenebras?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'quæ autem conventio Christi ad Belial? aut quæ pars fideli cum infideli?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'qui autem consensus templo Dei cum idolis? vos enim estis templum Dei vivi, sicut dicit Deus: Quoniam inhabitabo in illis, et inambulabo inter eos, et ero illorum Deus, et ipsi erunt mihi populus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Propter quod exite de medio eorum, et separamini, dicit Dominus, et immundum ne tetigeritis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'et ego recipiam vos: et ero vobis in patrem, et vos eritis mihi in filios et filias, dicit Dominus omnipotens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 1, 'Has ergo habentes promissiones, carissimi, mundemus nos ab omni inquinamento carnis et spiritus, perficientes sanctificationem in timore Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 2, 'Capite nos. Neminem læsimus, neminem corrupimus, neminem circumvenimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 3, 'Non ad condemnationem vestram dico: prædiximus enim quod in cordibus nostris estis ad commoriendum et ad convivendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 4, 'Multa mihi fiducia est apud vos, multa mihi gloriatio pro vobis: repletus sum consolatione; superabundo gaudio in omni tribulatione nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 5, 'Nam et cum venissemus in Macedoniam, nullam requiem habuit caro nostra, sed omnem tribulationem passi sumus: foris pugnæ, intus timores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 6, 'Sed qui consolatur humiles, consolatus est nos Deus in adventu Titi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 7, 'Non solum autem in adventu ejus, sed etiam in consolatione, qua consolatus est in vobis, referens nobis vestrum desiderium, vestrum fletum, vestram æmulationem pro me, ita ut magis gauderem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 8, 'Quoniam etsi contristavi vos in epistola, non me pœnitet: etsi pœniteret, videns quod epistola illa (etsi ad horam) vos contristavit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 9, 'nunc gaudeo: non quia contristati estis, sed quia contristati estis ad pœnitentiam. Contristati enim estis ad Deum, ut in nullo detrimentum patiamini ex nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 10, 'Quæ enim secundum Deum tristitia est, pœnitentiam in salutem stabilem operatur: sæculi autem tristitia mortem operatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 11, 'Ecce enim hoc ipsum, secundum Deum contristari vos, quantam in vobis operatur sollicitudinem: sed defensionem, sed indignationem, sed timorem, sed desiderium, sed æmulationem, sed vindictam: in omnibus exhibuistis vos incontaminatos esse negotio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 12, 'Igitur, etsi scripsi vobis, non propter eum qui fecit injuriam, nec propter eum qui passus est: sed ad manifestandam sollicitudinem nostram, quam habemus pro vobis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 13, 'coram Deo: ideo consolati sumus. In consolatione autem nostra, abundantius magis gavisi sumus super gaudio Titi, quia refectus est spiritus ejus ab omnibus vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 14, 'et si quid apud illum de vobis gloriatus sum, non sum confusus: sed sicut omnia vobis in veritate locuti sumus, ita et gloriatio nostra, quæ fuit ad Titum, veritas facta est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 15, 'et viscera ejus abundantius in vobis sunt, reminiscentis omnium vestrum obedientiam: quomodo cum timore et tremore excepistis illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 7, 16, 'Gaudeo quod in omnibus confido in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 1, 'Notam autem facimus vobis, fratres, gratiam Dei, quæ data est in ecclesiis Macedoniæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 2, 'quod in multo experimento tribulationis abundantia gaudii ipsorum fuit, et altissima paupertas eorum, abundavit in divitias simplicitatis eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 3, 'quia secundum virtutem testimonium illis reddo, et supra virtutem voluntarii fuerunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 4, 'cum multa exhortatione obsecrantes nos gratiam, et communicationem ministerii, quod fit in sanctos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 5, 'Et non sicut speravimus, sed semetipsos dederunt primum Domino, deinde nobis per voluntatem Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 6, 'ita ut rogaremus Titum, ut quemadmodum cœpit, ita et perficiat in vobis etiam gratiam istam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 7, 'Sed sicut in omnibus abundatis fide, et sermone, et scientia, et omni sollicitudine, insuper et caritate vestra in nos, ut et in hac gratia abundetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 8, 'Non quasi imperans dico: sed per aliorum sollicitudinem, etiam vestræ caritatis ingenium bonum comprobans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 9, 'Scitis enim gratiam Domini nostri Jesu Christi, quoniam propter vos egenus factus est, cum esset dives, ut illius inopia vos divites essetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 10, 'Et consilium in hoc do: hoc enim vobis utile est, qui non solum facere, sed et velle cœpistis ab anno priore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 11, 'nunc vero et facto perficite: ut quemadmodum promptus est animus voluntatis, ita sit et perficiendi ex eo quod habetis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 12, 'Si enim voluntas prompta est, secundum id quod habet, accepta est, non secundum id quod non habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 13, 'Non enim ut aliis sit remissio, vobis autem tribulatio, sed ex æqualitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 14, 'In præsenti tempore vestra abundantia illorum inopiam suppleat: ut et illorum abundantia vestræ inopiæ sit supplementum, ut fiat æqualitas, sicut scriptum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 15, 'Qui multum, non abundavit: et qui modicum, non minoravit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 16, 'Gratias autem Deo, qui dedit eamdem sollicitudinem pro vobis in corde Titi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 17, 'quoniam exhortationem quidem suscepit: sed cum sollicitior esset, sua voluntate profectus est ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 18, 'Misimus etiam cum illo fratrem, cujus laus est in Evangelio per omnes ecclesias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 19, 'non solum autem, sed et ordinatus est ab ecclesiis comes peregrinationis nostræ in hanc gratiam, quæ ministratur a nobis ad Domini gloriam, et destinatam voluntatem nostram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 20, 'devitantes hoc, ne quis nos vituperet in hac plenitudine, quæ ministratur a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 21, 'Providemus enim bona non solum coram Deo, sed etiam coram hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 22, 'Misimus autem cum illis et fratrem nostrum, quem probavimus in multis sæpe sollicitum esse: nunc autem multo sollicitiorem, confidentia multa in vos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 23, 'sive pro Tito, qui est socius meus, et in vos adjutor, sive fratres nostri, Apostoli ecclesiarum, gloria Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 8, 24, 'Ostensionem ergo, quæ est caritatis vestræ, et nostræ gloriæ pro vobis, in illos ostendite in faciem ecclesiarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 1, 'Nam de ministerio, quod fit in sanctos ex abundanti est mihi scribere vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 2, 'Scio enim promptum animum vestrum: pro quo de vobis glorior apud Macedones. Quoniam et Achaia parata est ab anno præterito, et vestra æmulatio provocavit plurimos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 3, 'Misi autem fratres: ut ne quod gloriamur de vobis, evacuetur in hac parte, ut (quemadmodum dixi) parati sitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 4, 'ne cum venerint Macedones mecum, et invenerint vos imparatos, erubescamus nos (ut non dicamus vos) in hac substantia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 5, 'Necessarium ergo existimavi rogare fratres, ut præveniant ad vos, et præparent repromissam benedictionem hanc paratam esse sic, quasi benedictionem, non tamquam avaritiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 6, 'Hoc autem dico: qui parce seminat, parce et metet: et qui seminat in benedictionibus, de benedictionibus et metet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 7, 'Unusquisque, prout destinavit in corde suo, non ex tristitia, aut ex necessitate: hilarem enim datorem diligit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 8, 'Potens est autem Deus omnem gratiam abundare facere in vobis: ut in omnibus semper omnem sufficientiam habentes, abundetis in omne opus bonum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 9, 'sicut scriptum est: Dispersit, dedit pauperibus: justitia ejus manet in sæculum sæculi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 10, 'Qui autem administrat semen seminanti: et panem ad manducandum præstabit, et multiplicabit semen vestrum, et augebit incrementa frugum justitiæ vestræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 11, 'ut in omnibus locupletati abundetis in omnem simplicitatem, quæ operatur per nos gratiarum actionem Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 12, 'Quoniam ministerium hujus officii non solum supplet ea quæ desunt sanctis, sed etiam abundat per multas gratiarum actiones in Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 13, 'per probationem ministerii hujus, glorificantes Deum in obedientia confessionis vestræ, in Evangelium Christi, et simplicitate communicationis in illos, et in omnes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 14, 'et in ipsorum obsecratione pro vobis, desiderantium vos propter eminentem gratiam Dei in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 9, 15, 'Gratias Deo super inenarrabili dono ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 1, 'Ipse autem ego Paulus obsecro vos per mansuetudinem et modestiam Christi, qui in facie quidem humilis sum inter vos, absens autem confido in vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 2, 'Rogo autem vos ne præsens audeam per eam confidentiam, qua existimor audere in quosdam, qui arbitrantur nos tamquam secundum carnem ambulemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 3, 'In carne enim ambulantes, non secundum carnem militamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 4, 'Nam arma militiæ nostræ non carnalia sunt, sed potentia Deo ad destructionem munitionum, consilia destruentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 5, 'et omnem altitudinem extollentem se adversus scientiam Dei, et in captivitatem redigentes omnem intellectum in obsequium Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 6, 'et in promptu habentes ulcisci omnem inobedientiam, cum impleta fuerit vestra obedientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 7, 'Quæ secundum faciem sunt, videte. Si quis confidit sibi Christi se esse, hoc cogitet iterum apud se: quia sicut ipse Christi est, ita et nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 8, 'Nam etsi amplius aliquid gloriatus fuero de potestate nostra, quam dedit nobis Dominus in ædificationem, et non in destructionem vestram, non erubescam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 9, 'Ut autem non existimer tamquam terrere vos per epistolas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 10, 'quoniam quidem epistolæ, inquiunt, graves sunt et fortes: præsentia autem corporis infirma, et sermo contemptibilis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 11, 'hoc cogitet qui ejusmodi est, quia quales sumus verbo per epistolas absentes, tales et præsentes in facto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 12, 'Non enim audemus inserere, aut comparare nos quibusdam, qui seipsos commendant: sed ipsi in nobis nosmetipsos metientes, et comparantes nosmetipsos nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 13, 'Nos autem non in immensum gloriabimur, sed secundum mensuram regulæ, qua mensus est nobis Deus, mensuram pertingendi usque ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 14, 'Non enim quasi non pertingentes ad vos, superextendimus nos: usque ad vos enim pervenimus in Evangelio Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 15, 'Non in immensum gloriantes in alienis laboribus: spem autem habentes crescentis fidei vestræ, in vobis magnificari secundum regulam nostram in abundantiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 16, 'etiam in illa, quæ ultra vos sunt, evangelizare, non in aliena regula in iis quæ præparata sunt gloriari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 17, 'Qui autem gloriatur, in Domino glorietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 10, 18, 'Non enim qui seipsum commendat, ille probatus est: sed quem Deus commendat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 1, 'Utinam sustineretis modicum quid insipientiæ meæ, sed et supportare me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 2, 'æmulor enim vos Dei æmulatione. Despondi enim vos uni viro, virginem castam exhibere Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 3, 'Timeo autem ne sicut serpens Hevam seduxit astutia sua, ita corrumpantur sensus vestri, et excidant a simplicitate, quæ est in Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 4, 'Nam si is qui venit, alium Christum prædicat, quem non prædicavimus, aut alium spiritum accipitis, quem non accepistis: aut aliud Evangelium, quod non recepistis: recte pateremini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 5, 'Existimo enim nihil me minus fecisse a magnis Apostolis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 6, 'Nam etsi imperitus sermone, sed non scientia, in omnibus autem manifestati sumus vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 7, 'Aut numquid peccatum feci, meipsum humilians, ut vos exaltemini? quoniam gratis Evangelium Dei evangelizavi vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 8, 'Alias ecclesias expoliavi, accipiens stipendium ad ministerium vestrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 9, 'Et cum essem apud vos, et egerem, nulli onerosus fui: nam quod mihi deerat, suppleverunt fratres, qui venerunt a Macedonia: et in omnibus sine onere me vobis servavi, et servabo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 10, 'Est veritas Christi in me, quoniam hæc gloriatio non infringetur in me in regionibus Achaiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 11, 'Quare? quia non diligo vos? Deus scit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 12, 'Quod autem facio, et faciam: ut amputem occasionem eorum qui volunt occasionem, ut in quo gloriantur, inveniantur sicut et nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 13, 'Nam ejusmodi pseudoapostoli sunt operarii subdoli, transfigurantes se in apostolos Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 14, 'Et non mirum: ipse enim Satanas transfigurat se in angelum lucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 15, 'Non est ergo magnum, si ministri ejus transfigurentur velut ministri justitiæ: quorum finis erit secundum opera ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 16, 'Iterum dico (ne quis me putet insipientem esse, alioquin velut insipientem accipite me, ut et ego modicum quid glorier),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 17, 'quod loquor, non loquor secundum Deum, sed quasi in insipientia, in hac substantia gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 18, 'Quoniam multi gloriantur secundum carnem: et ego gloriabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 19, 'Libenter enim suffertis insipientes, cum sitis ipsi sapientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 20, 'Sustinetis enim si quis vos in servitutem redigit, si quis devorat, si quis accipit, si quis extollitur, si quis in faciem vos cædit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 21, 'Secundum ignobilitatem dico, quasi nos infirmi fuerimus in hac parte. In quo quis audet (in insipientia dico) audeo et ego:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 22, 'Hebræi sunt, et ego: Israëlitæ sunt, et ego: semen Abrahæ sunt, et ego.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 23, 'Ministri Christi sunt (ut minus sapiens dico), plus ego: in laboribus plurimis, in carceribus abundantius, in plagis supra modum, in mortibus frequenter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 24, 'A Judæis quinquies, quadragenas, una minus, accepi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 25, 'Ter virgis cæsus sum, semel lapidatus sum: ter naufragium feci, nocte et die in profundo maris fui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 26, 'in itineribus sæpe, periculis fluminum, periculis latronum, periculis ex genere, periculis ex gentibus, periculis in civitate, periculis in solitudine, periculis in mari, periculis in falsis fratribus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 27, 'in labore et ærumna, in vigiliis multis, in fame et siti, in jejuniis multis, in frigore et nuditate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 28, 'præter illa quæ extrinsecus sunt, instantia mea quotidiana, sollicitudo omnium ecclesiarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 29, 'Quis infirmatur, et ego non infirmor? quis scandalizatur, et ego non uror?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 30, 'Si gloriari oportet, quæ infirmitatis meæ sunt, gloriabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 31, 'Deus et Pater Domini nostri Jesu Christi, qui est benedictus in sæcula, scit quod non mentior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 32, 'Damasci præpositus gentis Aretæ regis custodiebat civitatem Damascenorum ut me comprehenderet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 11, 33, 'et per fenestram in sporta dimissus sum per murum, et sic effugi manus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 1, 'Si gloriari oportet (non expedit quidem), veniam autem ad visiones et revelationes Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 2, 'Scio hominem in Christo ante annos quatuordecim, sive in corpore nescio, sive extra corpus nescio, Deus scit, raptum hujusmodi usque ad tertium cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 3, 'Et scio hujusmodi hominem sive in corpore, sive extra corpus nescio, Deus scit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 4, 'quoniam raptus est in paradisum: et audivit arcana verba, quæ non licet homini loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 5, 'Pro hujusmodi gloriabor: pro me autem nihil gloriabor nisi in infirmitatibus meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 6, 'Nam etsi voluero gloriari, non ero insipiens: veritatem enim dicam: parco autem, ne quis me existimet supra id quod videt in me, aut aliquid audit ex me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 7, 'Et ne magnitudo revelationum extollat me, datus est mihi stimulus carnis meæ angelus Satanæ, qui me colaphizet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 8, 'Propter quod ter Dominum rogavi ut discederet a me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 9, 'et dixit mihi: Sufficit tibi gratia mea: nam virtus in infirmitate perficitur. Libenter igitur gloriabor in infirmitatibus meis, ut inhabitet in me virtus Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 10, 'Propter quod placeo mihi in infirmitatibus meis, in contumeliis, in necessitatibus, in persecutionibus, in angustiis pro Christo: cum enim infirmor, tunc potens sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 11, 'Factus sum insipiens, vos me coëgistis. Ego enim a vobis debui commendari: nihil enim minus fui ab iis, qui sunt supra modum Apostoli: tametsi nihil sum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 12, 'signa tamen apostolatus mei facta sunt super vos in omni patientia, in signis, et prodigiis, et virtutibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 13, 'Quid est enim, quod minus habuistis præ ceteris ecclesiis, nisi quod ego ipse non gravavi vos? donate mihi hanc injuriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 14, 'Ecce tertio hoc paratus sum venire ad vos: et non ero gravis vobis. Non enim quæro quæ vestra sunt, sed vos. Nec enim debent filii parentibus thesaurizare, sed parentes filiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 15, 'Ego autem libentissime impendam, et super impendar ipse pro animabus vestris: licet plus vos diligens, minus diligar.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 16, 'Sed esto: ego vos non gravavi: sed cum essem astutus, dolo vos cepi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 17, 'Numquid per aliquem eorum, quod misi ad vos, circumveni vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 18, 'Rogavi Titum, et misi cum illo fratrem. Numquid Titus vos circumvenit? nonne eodem spiritu ambulavimus? nonne iisdem vestigiis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 19, 'Olim putatis quod excusemus nos apud vos? coram Deo in Christo loquimur: omnia autem, carissimi, propter ædificationem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 20, 'Timeo enim ne forte cum venero, non quales volo, inveniam vos: et ego inveniar a vobis, qualem non vultis: ne forte contentiones, æmulationes, animositates, dissensiones, detractiones, susurrationes, inflationes, seditiones sint inter vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 12, 21, 'ne iterum cum venero, humiliet me Deus apud vos, et lugeam multos ex iis qui ante peccaverunt, et non egerunt pœnitentiam super immunditia, et fornicatione, et impudicitia, quam gesserunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 1, 'Ecce tertio hoc venio ad vos: in ore duorum vel trium testium stabit omne verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 2, 'Prædixi, et prædico, ut præsens, et nunc absens iis qui ante peccaverunt, et ceteris omnibus, quoniam si venero iterum, non parcam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 3, 'An experimentum quæritis ejus, qui in me loquitur Christus, qui in vobis non infirmatur, sed potens est in vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 4, 'Nam etsi crucifixus est ex infirmitate: sed vivit ex virtute Dei. Nam et nos infirmi sumus in illo: sed vivemus cum eo ex virtute Dei in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 5, 'Vosmetipsos tentate si estis in fide: ipsi vos probate. An non cognoscitis vosmetipsos quia Christus Jesus in vobis est? nisi forte reprobi estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 6, 'Spero autem quod cognoscetis, quia nos non sumus reprobi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 7, 'Oramus autem Deum ut nihil mali faciatis, non ut nos probati appareamus, sed ut vos quod bonum est faciatis: nos autem ut reprobi simus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 8, 'Non enim possumus aliquid adversus veritatem, sed pro veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 9, 'Gaudemus enim, quoniam nos infirmi sumus, vos autem potentes estis. Hoc et oramus, vestram consummationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 10, 'Ideo hæc absens scribo, ut non præsens durius agam secundum potestatem, quam Dominus dedit mihi in ædificationem, et non in destructionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 11, 'De cetero, fratres, gaudete, perfecti estote, exhortamini, idem sapite, pacem habete, et Deus pacis et dilectionis erit vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 12, 'Salutate invicem in osculo sancto. Salutant vos omnes sancti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 13, 13, 'Gratia Domini nostri Jesu Christi, et caritas Dei, et communicatio Sancti Spiritus sit cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, Apostolus non ab hominibus, neque per hominem, sed per Jesum Christum, et Deum Patrem, qui suscitavit eum a mortuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'et qui mecum sunt omnes fratres, ecclesiis Galatiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Gratia vobis, et pax a Deo Patre, et Domino nostro Jesu Christo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'qui dedit semetipsum pro peccatis nostris, ut eriperet nos de præsenti sæculo nequam, secundum voluntatem Dei et Patris nostri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'cui est gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Miror quod sic tam cito transferimini ab eo qui vos vocavit in gratiam Christi in aliud Evangelium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'quod non est aliud, nisi sunt aliqui qui vos conturbant, et volunt convertere Evangelium Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Sed licet nos aut angelus de cælo evangelizet vobis præterquam quod evangelizavimus vobis, anathema sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Sicut prædiximus, et nunc iterum dico: si quis vobis evangelizaverit præter id quod accepistis, anathema sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Modo enim hominibus suadeo, an Deo? an quæro hominibus placere? si adhuc hominibus placerem, Christi servus non essem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Notum enim vobis facio, fratres, Evangelium, quod evangelizatum est a me, quia non est secundum hominem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'neque enim ego ab homine accepi illud, neque didici, sed per revelationem Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Audistis enim conversationem meam aliquando in Judaismo: quoniam supra modum persequebar Ecclesiam Dei, et expugnabam illam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'et proficiebam in Judaismo supra multos coætaneos meos in genere meo, abundantius æmulator existens paternarum mearum traditionum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Cum autem placuit ei, qui me segregavit ex utero matris meæ, et vocavit per gratiam suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'ut revelaret Filium suum in me, ut evangelizarem illum in gentibus: continuo non acquievi carni et sanguini,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'neque veni Jerosolymam ad antecessores meos Apostolos: sed abii in Arabiam, et iterum reversus sum Damascum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'deinde post annos tres veni Jerosolymam videre Petrum, et mansi apud eum diebus quindecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 19, 'alium autem Apostolorum vidi neminem, nisi Jacobum fratrem Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 20, 'Quæ autem scribo vobis, ecce coram Deo, quia non mentior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 21, 'Deinde veni in partes Syriæ, et Ciliciæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 22, 'Eram autem ignotus facie ecclesiis Judææ, quæ erant in Christo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 23, 'tantum autem auditum habebant quoniam qui persequebatur nos aliquando, nunc evangelizat fidem, quam aliquando expugnabat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 24, 'et in me clarificabant Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Deinde post annos quatuordecim, iterum ascendi Jerosolymam cum Barnaba, assumpto et Tito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Ascendi autem secundum revelationem: et contuli cum illis Evangelium, quod prædico in gentibus, seorsum autem iis qui videbantur aliquid esse: ne forte in vacuum currerem, aut cucurrissem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Sed neque Titus, qui mecum erat, cum esset gentilis, compulsus est circumcidi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'sed propter subintroductos falsos fratres, qui subintroierunt explorare libertatem nostram, quam habemus in Christo Jesu, ut nos in servitutem redigerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Quibus neque ad horam cessimus subjectione, ut veritas Evangelii permaneat apud vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'ab iis autem, qui videbantur esse aliquid (quales aliquando fuerint, nihil mea interest: Deus personam hominis non accipit): mihi enim qui videbantur esse aliquid, nihil contulerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Sed e contra cum vidissent quod creditum est mihi Evangelium præputii, sicut et Petro circumcisionis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, '(qui enim operatus est Petro in apostolatum circumcisionis, operatus est et mihi inter gentes):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'et cum cognovissent gratiam, quæ data est mihi, Jacobus, et Cephas, et Joannes, qui videbantur columnæ esse, dextras dederunt mihi, et Barnabæ societatis: ut nos in gentes, ipsi autem in circumcisionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'tantum ut pauperum memores essemus, quod etiam sollicitus fui hoc ipsum facere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Cum autem venisset Cephas Antiochiam, in faciem ei restiti, quia reprehensibilis erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Prius enim quam venirent quidam a Jacobo, cum gentibus edebat: cum autem venissent, subtrahebat, et segregabat se, timens eos qui ex circumcisione erant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Et simulationi ejus consenserunt ceteri Judæi, ita ut et Barnabas duceretur ab eis in illam simulationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Sed cum vidissem quod non recte ambularent ad veritatem Evangelii, dixi Cephæ coram omnibus: Si tu, cum Judæus sis, gentiliter vivis, et non judaice: quomodo gentes cogis judaizare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Nos natura Judæi, et non ex gentibus peccatores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Scientes autem quod non justificatur homo ex operibus legis, nisi per fidem Jesu Christi: et nos in Christo Jesu credimus, ut justificemur ex fide Christi, et non ex operibus legis: propter quod ex operibus legis non justificabitur omnis caro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Quod si quærentes justificari in Christo, inventi sumus et ipsi peccatores, numquid Christus peccati minister est? Absit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Si enim quæ destruxi, iterum hæc ædifico: prævaricatorem me constituo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Ego enim per legem, legi mortuus sum, ut Deo vivam: Christo confixus sum cruci.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Vivo autem, jam non ego: vivit vero in me Christus. Quod autem nunc vivo in carne: in fide vivo Filii Dei, qui dilexit me, et tradidit semetipsum pro me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Non abjicio gratiam Dei. Si enim per legem justitia, ergo gratis Christus mortuus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'O insensati Galatæ, quis vos fascinavit non obedire veritati, ante quorum oculos Jesus Christus præscriptus est, in vobis crucifixus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Hoc solum a vobis volo discere: ex operibus legis Spiritum accepistis, an ex auditu fidei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'sic stulti estis, ut cum Spiritu cœperitis, nunc carne consummemini?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'tanta passi estis sine causa? si tamen sine causa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Qui ergo tribuit vobis Spiritum, et operatur virtutes in vobis: ex operibus legis, an ex auditu fidei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Sicut scriptum est: Abraham credidit Deo, et reputatum est illi ad justitiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'cognoscite ergo quia qui ex fide sunt, ii sunt filii Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Providens autem Scriptura quia ex fide justificat gentes Deus, prænuntiavit Abrahæ: Quia benedicentur in te omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Igitur qui ex fide sunt, benedicentur cum fideli Abraham.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Quicumque enim ex operibus legis sunt, sub maledicto sunt. Scriptum est enim: Maledictus omnis qui non permanserit in omnibus quæ scripta sunt in libro legis ut faciat ea.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Quoniam autem in lege nemo justificatur apud Deum, manifestum est: quia justus ex fide vivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Lex autem non est ex fide, sed: Qui fecerit ea, vivet in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Christus nos redemit de maledicto legis, factus pro nobis maledictum: quia scriptum est: Maledictus omnis qui pendet in ligno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'ut in gentibus benedictio Abrahæ fieret in Christo Jesu, ut pollicitationem Spiritus accipiamus per fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Fratres (secundum hominem dico) tamen hominis confirmatum testamentum nemo spernit, aut superordinat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Abrahæ dictæ sunt promissiones, et semini ejus. Non dicit: Et seminibus, quasi in multis: sed quasi in uno: Et semini tuo, qui est Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Hoc autem dico, testamentum confirmatum a Deo: quæ post quadringentos et triginta annos facta est lex, non irritum facit ad evacuandam promissionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 18, 'Nam si ex lege hæreditas, jam non ex promissione. Abrahæ autem per repromissionem donavit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 19, 'Quid igitur lex? Propter transgressiones posita est donec veniret semen, cui promiserat, ordinata per angelos in manu mediatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 20, 'Mediator autem unius non est: Deus autem unus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 21, 'Lex ergo adversus promissa Dei? Absit. Si enim data esset lex, quæ posset vivificare, vere ex lege esset justitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 22, 'Sed conclusit Scriptura omnia sub peccato, ut promissio ex fide Jesu Christi daretur credentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 23, 'Prius autem quam veniret fides, sub lege custodiebamur conclusi in eam fidem quæ revelanda erat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 24, 'Itaque lex pædagogus noster fuit in Christo, ut ex fide justificemur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 25, 'At ubi venit fides, jam non sumus sub pædagogo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 26, 'Omnes enim filii Dei estis per fidem, quæ est in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 27, 'Quicumque enim in Christo baptizati estis, Christum induistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 28, 'Non est Judæus, neque Græcus: non est servus, neque liber: non est masculus, neque femina. Omnes enim vos unum estis in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 29, 'Si autem vos Christi, ergo semen Abrahæ estis, secundum promissionem hæredes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Dico autem: quanto tempore hæres parvulus est, nihil differt a servo, cum sit dominus omnium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'sed sub tutoribus et actoribus est usque ad præfinitum tempus a patre:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'ita et nos cum essemus parvuli, sub elementis mundi eramus servientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'At ubi venit plenitudo temporis, misit Deus Filium suum factum ex muliere, factum sub lege,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'ut eos, qui sub lege erant, redimeret, ut adoptionem filiorum reciperemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Quoniam autem estis filii, misit Deus Spiritum Filii sui in corda vestra, clamantem: Abba, Pater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Itaque jam non est servus, sed filius: quod si filius, et hæres per Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Sed tunc quidem ignorantes Deum, iis, qui natura non sunt dii, serviebatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Nunc autem cum cognoveritis Deum, immo cogniti sitis a Deo: quomodo convertimini iterum ad infirma et egena elementa, quibus denuo servire vultis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Dies observatis, et menses, et tempora, et annos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Timeo vos, ne forte sine causa laboraverim in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Estote sicut ego, quia et ego sicut vos: fratres, obsecro vos. Nihil me læsistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Scitis autem quia per infirmitatem carnis evangelizavi vobis jampridem: et tentationem vestram in carne mea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'non sprevistis, neque respuistis: sed sicut angelum Dei excepistis me, sicut Christum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Ubi est ergo beatitudo vestra? testimonium enim perhibeo vobis, quia, si fieri posset, oculos vestros eruissetis, et dedissetis mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Ergo inimicus vobis factus sum, verum dicens vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, '\'mulantur vos non bene: sed excludere vos volunt, ut illos æmulemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Bonum autem æmulamini in bono semper: et non tantum cum præsens sum apud vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Filioli mei, quos iterum parturio, donec formetur Christus in vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'vellem autem esse apud vos modo, et mutare vocem meam: quoniam confundor in vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Dicite mihi qui sub lege vultis esse: legem non legistis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Scriptum est enim: Quoniam Abraham duos filios habuit: unum de ancilla, et unum de libera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 23, 'Sed qui de ancilla, secundum carnem natus est: qui autem de libera, per repromissionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 24, 'quæ sunt per allegoriam dicta. Hæc enim sunt duo testamenta. Unum quidem in monte Sina, in servitutem generans, quæ est Agar:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 25, 'Sina enim mons est in Arabia, qui conjunctus est ei quæ nunc est Jerusalem, et servit cum filiis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 26, 'Illa autem, quæ sursum est Jerusalem, libera est, quæ est mater nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 27, 'Scriptum est enim: Lætare, sterilis, quæ non paris; erumpe et clama, quæ non parturis: quia multi filii desertæ, magis quam ejus quæ habet virum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 28, 'Nos autem, fratres, secundum Isaac promissionis filii sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 29, 'Sed quomodo tunc is, qui secundum carnem natus fuerat, persequebatur eum qui secundum spiritum: ita et nunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 30, 'Sed quid dicit Scriptura? Ejice ancillam, et filium ejus: non enim hæres erit filius ancillæ cum filio liberæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 31, 'Itaque, fratres, non sumus ancillæ filii, sed liberæ: qua libertate Christus nos liberavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 1, 'State, et nolite iterum jugo servitutis contineri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 2, 'Ecce ego Paulus dico vobis: quoniam si circumcidamini, Christus vobis nihil proderit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 3, 'Testificor autem rursus omni homini circumcidenti se, quoniam debitor est universæ legis faciendæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 4, 'Evacuati estis a Christo, qui in lege justificamini: a gratia excidistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 5, 'Nos enim spiritu ex fide, spem justitiæ exspectamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 6, 'Nam in Christo Jesu neque circumcisio aliquid valet, neque præputium: sed fides, quæ per caritatem operatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 7, 'Currebatis bene: quis vos impedivit veritati non obedire?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 8, 'persuasio hæc non est ex eo, qui vocat vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 9, 'Modicum fermentum totam massam corrumpit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 10, 'Ego confido in vobis in Domino, quod nihil aliud sapietis: qui autem conturbat vos, portabit judicium, quicumque est ille.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 11, 'Ego autem, fratres, si circumcisionem adhuc prædico: quid adhuc persecutionem patior? ergo evacuatum est scandalum crucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 12, 'Utinam et abscindantur qui vos conturbant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 13, 'Vos enim in libertatem vocati estis, fratres: tantum ne libertatem in occasionem detis carnis, sed per caritatem Spiritus servite invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 14, 'Omnis enim lex in uno sermone impletur: Diliges proximum tuum sicut teipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 15, 'Quod si invicem mordetis, et comeditis: videte ne ab invicem consumamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 16, 'Dico autem: Spiritu ambulate, et desideria carnis non perficietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 17, 'Caro enim concupiscit adversus spiritum, spiritus autem adversus carnem: hæc enim sibi invicem adversantur, ut non quæcumque vultis, illa faciatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 18, 'Quod si Spiritu ducimini, non estis sub lege.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 19, 'Manifesta sunt autem opera carnis, quæ sunt fornicatio, immunditia, impudicitia, luxuria,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 20, 'idolorum servitus, veneficia, inimicitiæ, contentiones, æmulationes, iræ, rixæ, dissensiones, sectæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 21, 'invidiæ, homicidia, ebrietates, comessationes, et his similia, quæ prædico vobis, sicut prædixi: quoniam qui talia agunt, regnum Dei non consequentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 22, 'Fructus autem Spiritus est caritas, gaudium, pax, patientia, benignitas, bonitas, longanimitas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 23, 'mansuetudo, fides, modestia, continentia, castitas. Adversus hujusmodi non est lex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 24, 'Qui autem sunt Christi, carnem suam crucifixerunt cum vitiis et concupiscentiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 25, 'Si Spiritu vivimus, Spiritu et ambulemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 5, 26, 'Non efficiamur inanis gloriæ cupidi, invicem provocantes, invicem invidentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 1, 'Fratres, etsi præoccupatus fuerit homo in aliquo delicto, vos, qui spirituales estis, hujusmodi instruite in spiritu lenitatis, considerans teipsum, ne et tu tenteris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 2, 'Alter alterius onera portate, et sic adimplebitis legem Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 3, 'Nam si quis existimat se aliquid esse, cum nihil sit, ipse se seducit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 4, 'Opus autem suum probet unusquisque, et sic in semetipso tantum gloriam habebit, et non in altero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 5, 'Unusquisque enim onus suum portabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 6, 'Communicet autem is qui catechizatur verbo, ei qui se catechizat, in omnibus bonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 7, 'Nolite errare: Deus non irridetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 8, 'Quæ enim seminaverit homo, hæc et metet. Quoniam qui seminat in carne sua, de carne et metet corruptionem: qui autem seminat in spiritu, de spiritu metet vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 9, 'Bonum autem facientes, non deficiamus: tempore enim suo metemus non deficientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 10, 'Ergo dum tempus habemus, operemur bonum ad omnes, maxime autem ad domesticos fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 11, 'Videte qualibus litteris scripsi vobis mea manu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 12, 'Quicumque enim volunt placere in carne, hi cogunt vos circumcidi, tantum ut crucis Christi persecutionem non patiantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 13, 'Neque enim qui circumciduntur, legem custodiunt: sed volunt vos circumcidi, ut in carne vestra glorientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 14, 'Mihi autem absit gloriari, nisi in cruce Domini nostri Jesu Christi: per quem mihi mundus crucifixus est, et ego mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 15, 'In Christo enim Jesu neque circumcisio aliquid valet, neque præputium, sed nova creatura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 16, 'Et quicumque hanc regulam secuti fuerint, pax super illos, et misericordia, et super Israël Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 17, 'De cetero, nemo mihi molestus sit: ego enim stigmata Domini Jesu in corpore meo porto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 6, 18, 'Gratia Domini nostri Jesu Christi cum spiritu vestro, fratres. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus Apostolus Jesu Christi per voluntatem Dei, omnibus sanctis qui sunt Ephesi, et fidelibus in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Benedictus Deus et Pater Domini nostri Jesu Christi, qui benedixit nos in omni benedictione spirituali in cælestibus in Christo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'sicut elegit nos in ipso ante mundi constitutionem, ut essemus sancti et immaculati in conspectu ejus in caritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Qui prædestinavit nos in adoptionem filiorum per Jesum Christum in ipsum: secundum propositum voluntatis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'in laudem gloriæ gratiæ suæ, in qua gratificavit nos in dilecto Filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'In quo habemus redemptionem per sanguinem ejus, remissionem peccatorum secundum divitias gratiæ ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'quæ superabundavit in nobis in omni sapientia et prudentia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'ut notum faceret nobis sacramentum voluntatis suæ, secundum beneplacitum ejus, quod proposuit in eo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'in dispensatione plenitudinis temporum, instaurare omnia in Christo, quæ in cælis et quæ in terra sunt, in ipso;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'in quo etiam et nos sorte vocati sumus prædestinati secundum propositum ejus qui operatur omnia secundum consilium voluntatis suæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'ut simus in laudem gloriæ ejus nos, qui ante speravimus in Christo;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'in quo et vos, cum audissetis verbum veritatis, Evangelium salutis vestræ, in quo et credentes signati estis Spiritu promissionis Sancto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'qui est pignus hæreditatis nostræ, in redemptionem acquisitionis, in laudem gloriæ ipsius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Propterea et ego audiens fidem vestram, quæ est in Domino Jesu, et dilectionem in omnes sanctos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'non cesso gratias agens pro vobis, memoriam vestri faciens in orationibus meis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 17, 'ut Deus, Domini nostri Jesu Christi Pater gloriæ, det vobis spiritum sapientiæ et revelationis in agnitione ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 18, 'illuminatos oculos cordis vestri, ut sciatis quæ sit spes vocationis ejus, et quæ divitiæ gloriæ hæreditatis ejus in sanctis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 19, 'et quæ sit supereminens magnitudo virtutis ejus in nos, qui credimus secundum operationem potentiæ virtutis ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 20, 'quam operatus est in Christo, suscitans illum a mortuis, et constituens ad dexteram suam in cælestibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 21, 'supra omnem principatum, et potestatem, et virtutem, et dominationem, et omne nomen, quod nominatur non solum in hoc sæculo, sed etiam in futuro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 22, 'Et omnia subjecit sub pedibus ejus: et ipsum dedit caput supra omnem ecclesiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 23, 'quæ est corpus ipsius, et plenitudo ejus, qui omnia in omnibus adimpletur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Et vos, cum essetis mortui delictis et peccatis vestris,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'in quibus aliquando ambulastis secundum sæculum mundi hujus, secundum principem potestatis aëris hujus, spiritus, qui nunc operatur in filios diffidentiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'in quibus et nos omnes aliquando conversati sumus in desideriis carnis nostræ, facientes voluntatem carnis et cogitationum, et eramus natura filii iræ, sicut et ceteri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Deus autem, qui dives est in misericordia, propter nimiam caritatem suam, qua dilexit nos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'et cum essemus mortui peccatis, convivificavit nos in Christo (cujus gratia estis salvati),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'et conresuscitavit, et consedere fecit in cælestibus in Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'ut ostenderet in sæculis supervenientibus abundantes divitias gratiæ suæ, in bonitate super nos in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Gratia enim estis salvati per fidem, et hoc non ex vobis: Dei enim donum est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'non ex operibus, ut ne quis glorietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Ipsius enim sumus factura, creati in Christo Jesu in operibus bonis, quæ præparavit Deus ut in illis ambulemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Propter quod memores estote quod aliquando vos gentes in carne, qui dicimini præputium ab ea quæ dicitur circumcisio in carne, manu facta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'quia eratis illo in tempore sine Christo, alienati a conversatione Israël, et hospites testamentorum, promissionis spem non habentes, et sine Deo in hoc mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Nunc autem in Christo Jesu, vos, qui aliquando eratis longe, facti estis prope in sanguine Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Ipse enim est pax nostra, qui fecit utraque unum, et medium parietem maceriæ solvens, inimicitias in carne sua,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'legem mandatorum decretis evacuans, ut duos condat in semetipso in unum novum hominem, faciens pacem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 16, 'et reconciliet ambos in uno corpore, Deo per crucem, interficiens inimicitias in semetipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 17, 'Et veniens evangelizavit pacem vobis, qui longe fuistis, et pacem iis, qui prope.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 18, 'Quoniam per ipsum habemus accessum ambo in uno Spiritu ad Patrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 19, 'Ergo jam non estis hospites, et advenæ: sed estis cives sanctorum, et domestici Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 20, 'superædificati super fundamentum apostolorum, et prophetarum, ipso summo angulari lapide Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 21, 'in quo omnis ædificatio constructa crescit in templum sanctum in Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 22, 'in quo et vos coædificamini in habitaculum Dei in Spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Hujus rei gratia, ego Paulus vinctus Christi Jesu, pro vobis gentibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'si tamen audistis dispensationem gratiæ Dei, quæ data est mihi in vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'quoniam secundum revelationem notum mihi factum est sacramentum, sicut supra scripsi in brevi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'prout potestis legentes intelligere prudentiam meam in mysterio Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'quod aliis generationibus non est agnitum filiis hominum, sicuti nunc revelatum est sanctis apostolis ejus et prophetis in Spiritu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'gentes esse cohæredes, et concorporales, et comparticipes promissionis ejus in Christo Jesu per Evangelium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'cujus factus sum minister secundum donum gratiæ Dei, quæ data est mihi secundum operationem virtutis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Mihi omnium sanctorum minimo data est gratia hæc, in gentibus evangelizare investigabiles divitias Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'et illuminare omnes, quæ sit dispensatio sacramenti absconditi a sæculis in Deo, qui omnia creavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'ut innotescat principatibus et potestatibus in cælestibus per Ecclesiam, multiformis sapientia Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'secundum præfinitionem sæculorum, quam fecit in Christo Jesu Domino nostro:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'in quo habemus fiduciam, et accessum in confidentia per fidem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Propter quod peto ne deficiatis in tribulationibus meis pro vobis: quæ est gloria vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Hujus rei gratia flecto genua mea ad Patrem Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'ex quo omnis paternitas in cælis et in terra nominatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 16, 'ut det vobis secundum divitias gloriæ suæ, virtute corroborari per Spiritum ejus in interiorem hominem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 17, 'Christum habitare per fidem in cordibus vestris: in caritate radicati, et fundati,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 18, 'ut possitis comprehendere cum omnibus sanctis, quæ sit latitudo, et longitudo, et sublimitas, et profundum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 19, 'scire etiam supereminentem scientiæ caritatem Christi, ut impleamini in omnem plenitudinem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 20, 'Ei autem, qui potens est omnia facere superabundanter quam petimus aut intelligimus, secundum virtutem, quæ operatur in nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 21, 'ipsi gloria in Ecclesia, et in Christo Jesu, in omnes generationes sæculi sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 1, 'Obsecro itaque vos ego vinctus in Domino, ut digne ambuletis vocatione, qua vocati estis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 2, 'cum omni humilitate, et mansuetudine, cum patientia, supportantes invicem in caritate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 3, 'solliciti servare unitatem Spiritus in vinculo pacis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 4, 'Unum corpus, et unus Spiritus, sicut vocati estis in una spe vocationis vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 5, 'Unus Dominus, una fides, unum baptisma.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 6, 'Unus Deus et Pater omnium, qui est super omnes, et per omnia, et in omnibus nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 7, 'Unicuique autem nostrum data est gratia secundum mensuram donationis Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 8, 'Propter quod dicit: Ascendens in altum, captivam duxit captivitatem: dedit dona hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 9, 'Quod autem ascendit, quid est, nisi quia et descendit primum in inferiores partes terræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 10, 'Qui descendit, ipse est et qui ascendit super omnes cælos, ut impleret omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 11, 'Et ipse dedit quosdam quidem apostolos, quosdam autem prophetas, alios vero evangelistas, alios autem pastores et doctores,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 12, 'ad consummationem sanctorum in opus ministerii, in ædificationem corporis Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 13, 'donec occurramus omnes in unitatem fidei, et agnitionis Filii Dei, in virum perfectum, in mensuram ætatis plenitudinis Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 14, 'ut jam non simus parvuli fluctuantes, et circumferamur omni vento doctrinæ in nequitia hominum, in astutia ad circumventionem erroris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 15, 'Veritatem autem facientes in caritate, crescamus in illo per omnia, qui est caput Christus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 16, 'ex quo totum corpus compactum et connexum per omnem juncturam subministrationis, secundum operationem in mensuram uniuscujusque membri, augmentum corporis facit in ædificationem sui in caritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 17, 'Hoc igitur dico, et testificor in Domino, ut jam non ambuletis, sicut et gentes ambulant in vanitate sensus sui,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 18, 'tenebris obscuratum habentes intellectum, alienati a vita Dei per ignorantiam, quæ est in illis, propter cæcitatem cordis ipsorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 19, 'qui desperantes, semetipsos tradiderunt impudicitiæ, in operationem immunditiæ omnis in avaritiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 20, 'Vos autem non ita didicistis Christum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 21, 'si tamen illum audistis, et in ipso edocti estis, sicut est veritas in Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 22, 'deponere vos secundum pristinam conversationem veterem hominem, qui corrumpitur secundum desideria erroris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 23, 'Renovamini autem spiritu mentis vestræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 24, 'et induite novum hominem, qui secundum Deum creatus est in justitia, et sanctitate veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 25, 'Propter quod deponentes mendacium, loquimini veritatem unusquisque cum proximo suo: quoniam sumus invicem membra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 26, 'Irascimini, et nolite peccare: sol non occidat super iracundiam vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 27, 'Nolite locum dare diabolo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 28, 'qui furabatur, jam non furetur: magis autem laboret, operando manibus suis, quod bonum est, ut habeat unde tribuat necessitatem patienti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 29, 'Omnis sermo malus ex ore vestro non procedat: sed si quis bonus ad ædificationem fidei ut det gratiam audientibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 30, 'Et nolite contristare Spiritum Sanctum Dei: in quo signati estis in diem redemptionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 31, 'Omnis amaritudo, et ira, et indignatio, et clamor, et blasphemia tollatur a vobis cum omni malitia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 4, 32, 'Estote autem invicem benigni, misericordes, donantes invicem sicut et Deus in Christo donavit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 1, 'Estote ergo imitatores Dei, sicut filii carissimi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 2, 'et ambulate in dilectione, sicut et Christus dilexit nos, et tradidit semetipsum pro nobis, oblationem et hostiam Deo in odorem suavitatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 3, 'Fornicatio autem, et omnis immunditia, aut avaritia, nec nominetur in vobis, sicut decet sanctos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 4, 'aut turpitudo, aut stultiloquium, aut scurrilitas, quæ ad rem non pertinet: sed magis gratiarum actio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 5, 'Hoc enim scitote intelligentes: quod omnis fornicator, aut immundus, aut avarus, quod est idolorum servitus, non habet hæreditatem in regno Christi et Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 6, 'Nemo vos seducat inanibus verbis: propter hæc enim venit ira Dei in filios diffidentiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 7, 'Nolite ergo effici participes eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 8, 'Eratis enim aliquando tenebræ: nunc autem lux in Domino. Ut filii lucis ambulate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 9, 'fructus enim lucis est in omni bonitate, et justitia, et veritate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 10, 'probantes quid sit beneplacitum Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 11, 'et nolite communicare operibus infructuosis tenebrarum, magis autem redarguite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 12, 'Quæ enim in occulto fiunt ab ipsis, turpe est et dicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 13, 'Omnia autem, quæ arguuntur, a lumine manifestantur: omne enim, quod manifestatur, lumen est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 14, 'Propter quod dicit: Surge qui dormis, et exsurge a mortuis, et illuminabit te Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 15, 'Videte itaque, fratres, quomodo caute ambuletis: non quasi insipientes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 16, 'sed ut sapientes: redimentes tempus, quoniam dies mali sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 17, 'Propterea nolite fieri imprudentes, sed intelligentes quæ sit voluntas Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 18, 'Et nolite inebriari vino, in quo est luxuria, sed implemini Spiritu Sancto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 19, 'loquentes vobismetipsis in psalmis, et hymnis, et canticis spiritualibus, cantantes et psallentes in cordibus vestris Domino,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 20, 'gratias agentes semper pro omnibus in nomine Domini nostri Jesu Christi Deo et Patri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 21, 'subjecti invicem in timore Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 22, 'Mulieres viris suis subditæ sint, sicut Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 23, 'quoniam vir caput est mulieris, sicut Christus caput est Ecclesiæ: ipse, salvator corporis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 24, 'Sed sicut Ecclesia subjecta est Christo, ita et mulieres viris suis in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 25, 'Viri, diligite uxores vestras, sicut et Christus dilexit Ecclesiam, et seipsum tradidit pro ea,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 26, 'ut illam sanctificaret, mundans lavacro aquæ in verbo vitæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 27, 'ut exhiberet ipse sibi gloriosam Ecclesiam, non habentem maculam, aut rugam, aut aliquid hujusmodi, sed ut sit sancta et immaculata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 28, 'Ita et viri debent diligere uxores suas ut corpora sua. Qui suam uxorem diligit, seipsum diligit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 29, 'Nemo enim umquam carnem suam odio habuit: sed nutrit et fovet eam, sicut et Christus Ecclesiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 30, 'quia membra sumus corporis ejus, de carne ejus et de ossibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 31, 'Propter hoc relinquet homo patrem et matrem suam, et adhærebit uxori suæ, et erunt duo in carne una.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 32, 'Sacramentum hoc magnum est, ego autem dico in Christo et in Ecclesia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 5, 33, 'Verumtamen et vos singuli, unusquisque uxorem suam sicut seipsum diligat: uxor autem timeat virum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 1, 'Filii, obedite parentibus vestris in Domino: hoc enim justum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 2, 'Honora patrem tuum, et matrem tuam, quod est mandatum primum in promissione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 3, 'ut bene sit tibi, et sis longævus super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 4, 'Et vos patres, nolite ad iracundiam provocare filios vestros: sed educate illos in disciplina et correptione Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 5, 'Servi, obedite dominis carnalibus cum timore et tremore, in simplicitate cordis vestri, sicut Christo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 6, 'non ad oculum servientes, quasi hominibus placentes, sed ut servi Christi, facientes voluntatem Dei ex animo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 7, 'cum bona voluntate servientes, sicut Domino, et non hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 8, 'scientes quoniam unusquisque quodcumque fecerit bonum, hoc recipiet a Domino, sive servus, sive liber.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 9, 'Et vos domini, eadem facite illis, remittentes minas: scientes quia et illorum et vester Dominus est in cælis: et personarum acceptio non est apud eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 10, 'De cetero, fratres, confortamini in Domino, et in potentia virtutis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 11, 'Induite vos armaturam Dei, ut possitis stare adversus insidias diaboli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 12, 'quoniam non est nobis colluctatio adversus carnem et sanguinem, sed adversus principes, et potestates, adversus mundi rectores tenebrarum harum, contra spiritualia nequitiæ, in cælestibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 13, 'Propterea accipite armaturam Dei, ut possitis resistere in die malo, et in omnibus perfecti stare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 14, 'State ergo succincti lumbos vestros in veritate, et induti loricam justitiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 15, 'et calceati pedes in præparatione Evangelii pacis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 16, 'in omnibus sumentes scutum fidei, in quo possitis omnia tela nequissimi ignea extinguere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 17, 'et galeam salutis assumite, et gladium spiritus (quod est verbum Dei),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 18, 'per omnem orationem et obsecrationem orantes omni tempore in spiritu: et in ipso vigilantes in omni instantia et obsecratione pro omnibus sanctis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 19, 'et pro me, ut detur mihi sermo in apertione oris mei cum fiducia, notum facere mysterium Evangelii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 20, 'pro quo legatione fungor in catena, ita ut in ipso audeam, prout oportet me loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 21, 'Ut autem et vos sciatis quæ circa me sunt, quid agam, omnia vobis nota faciet Tychicus, carissimus frater, et fidelis minister in Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 22, 'quem misi ad vos in hoc ipsum, ut cognoscatis quæ circa nos sunt, et consoletur corda vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 23, 'Pax fratribus, et caritas cum fide a Deo Patre et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 6, 24, 'Gratia cum omnibus qui diligunt Dominum nostrum Jesum Christum in incorruptione. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus et Timotheus, servi Jesu Christi, omnibus sanctis in Christo Jesu, qui sunt Philippis, cum episcopis et diaconibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gratias ago Deo meo in omni memoria vestri,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'semper in cunctis orationibus meis pro omnibus vobis, cum gaudio deprecationem faciens,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'super communicatione vestra in Evangelio Christi a prima die usque nunc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Confidens hoc ipsum, quia qui cœpit in vobis opus bonum, perficiet usque in diem Christi Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'sicut est mihi justum hoc sentire pro omnibus vobis: eo quod habeam vos in corde, et in vinculis meis, et in defensione, et confirmatione Evangelii, socios gaudii mei omnes vos esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Testis enim mihi est Deus, quomodo cupiam omnes vos in visceribus Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Et hoc oro, ut caritas vestra magis ac magis abundet in scientia, et in omni sensu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'ut probetis potiora, ut sitis sinceri, et sine offensa in diem Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'repleti fructu justitiæ per Jesum Christum, in gloriam et laudem Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Scire autem vos volo fratres, quia quæ circa me sunt, magis ad profectum venerunt Evangelii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'ita ut vincula mea manifesta fierent in Christo in omni prætorio, et in ceteris omnibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'et plures e fratribus in Domino confidentes vinculis meis, abundantius auderent sine timore verbum Dei loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Quidam quidem et propter invidiam et contentionem: quidam autem et propter bonam voluntatem Christum prædicant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'quidam ex caritate, scientes quoniam in defensionem Evangelii positus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Quidam autem ex contentione Christum annuntiant non sincere, existimantes pressuram se suscitare vinculis meis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Quid enim? Dum omni modo sive per occasionem, sive per veritatem, Christus annuntietur: et in hoc gaudeo, sed et gaudebo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Scio enim quia hoc mihi proveniet ad salutem, per vestram orationem, et subministrationem Spiritus Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'secundum exspectationem et spem meam, quia in nullo confundar: sed in omni fiducia sicut semper, et nunc magnificabitur Christus in corpore meo, sive per vitam, sive per mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Mihi enim vivere Christus est, et mori lucrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Quod si vivere in carne, hic mihi fructus operis est, et quid eligam ignoro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Coarctor autem e duobus: desiderium habens dissolvi, et esse cum Christo, multo magis melius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'permanere autem in carne, necessarium propter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Et hoc confidens scio quia manebo, et permanebo omnibus vobis ad profectum vestrum, et gaudium fidei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 26, 'ut gratulatio vestra abundet in Christo Jesu in me, per meum adventum iterum ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 27, 'Tantum digne Evangelio Christi conversamini: ut sive cum venero, et videro vos, sive absens audiam de vobis, quia statis in uno spiritu unanimes, collaborantes fidei Evangelii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 28, 'et in nullo terreamini ab adversariis: quæ illis est causa perditionis, vobis autem salutis, et hoc a Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 29, 'quia vobis donatum est pro Christo, non solum ut in eum credatis, sed ut etiam pro illo patiamini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 30, 'idem certamen habentes, quale et vidistis in me, et nunc audistis de me.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'Si qua ergo consolatio in Christo, si quod solatium caritatis, si qua societas spiritus, si qua viscera miserationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'implete gaudium meum ut idem sapiatis, eamdem caritatem habentes, unanimes, idipsum sentientes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'nihil per contentionem, neque per inanem gloriam: sed in humilitate superiores sibi invicem arbitrantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'non quæ sua sunt singuli considerantes, sed ea quæ aliorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'Hoc enim sentite in vobis, quod et in Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, 'qui cum in forma Dei esset, non rapinam arbitratus est esse se æqualem Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'sed semetipsum exinanivit, formam servi accipiens, in similitudinem hominum factus, et habitu inventus ut homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'Humiliavit semetipsum factus obediens usque ad mortem, mortem autem crucis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Propter quod et Deus exaltavit illum, et donavit illi nomen, quod est super omne nomen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'ut in nomine Jesu omne genu flectatur cælestium, terrestrium et infernorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'et omnis lingua confiteatur, quia Dominus Jesus Christus in gloria est Dei Patris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Itaque carissimi mei (sicut semper obedistis), non ut in præsentia mei tantum, sed multo magis nunc in absentia mea, cum metu et tremore vestram salutem operamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'Deus est enim, qui operatur in vobis et velle, et perficere pro bona voluntate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Omnia autem facite sine murmurationibus et hæsitationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'ut sitis sine querela, et simplices filii Dei, sine reprehensione in medio nationis pravæ et perversæ: inter quos lucetis sicut luminaria in mundo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'verbum vitæ continentes ad gloriam meam in die Christi, quia non in vacuum cucurri, neque in vacuum laboravi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Sed et si immolor supra sacrificium, et obsequium fidei vestræ, gaudeo, et congratulor omnibus vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, 'Idipsum autem et vos gaudete, et congratulamini mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Spero autem in Domino Jesu, Timotheum me cito mittere ad vos: ut et ego bono animo sim, cognitis quæ circa vos sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'Neminem enim habeo tam unanimem, qui sincera affectione pro vobis sollicitus sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'Omnes enim quæ sua sunt quærunt, non quæ sunt Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'Experimentum autem ejus cognoscite, quia sicut patri filius, mecum servivit in Evangelio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'Hunc igitur spero me mittere ad vos, mox ut videro quæ circa me sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 24, 'Confido autem in Domino quoniam et ipse veniam ad vos cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 25, 'Necessarium autem existimavi Epaphroditum fratrem, et cooperatorem, et commilitonem meum, vestrum autem apostolum, et ministrum necessitatis meæ, mittere ad vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 26, 'quoniam quidem omnes vos desiderabat: et mœstus erat, propterea quod audieratis illum infirmatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 27, 'Nam et infirmatus est usque ad mortem: sed Deus misertus est ejus: non solum autem ejus, verum etiam et mei, ne tristitiam super tristitiam haberem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 28, 'Festinantius ergo misi illum, ut viso eo iterum gaudeatis, et ego sine tristitia sim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 29, 'Excipite itaque illum cum omni gaudio in Domino, et ejusmodi cum honore habetote;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 30, 'quoniam propter opus Christi usque ad mortem accessit, tradens animam suam ut impleret id quod ex vobis deerat erga meum obsequium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'De cetero, fratres mei, gaudete in Domino. Eadem vobis scribere, mihi quidem non pigrum, vobis autem necessarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'Videte canes, videte malos operarios, videte concisionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Nos enim sumus circumcisio, qui spiritu servimus Deo, et gloriamur in Christo Jesu, et non in carne fiduciam habentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'quamquam ego habeam confidentiam et in carne. Si quis alius videtur confidere in carne, ego magis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'circumcisus octavo die, ex genere Israël, de tribu Benjamin, Hebræus ex Hebræis, secundum legem pharisæus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'secundum æmulationem persequens Ecclesiam Dei, secundum justitiam, quæ in lege est, conversatus sine querela.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Sed quæ mihi fuerunt lucra, hæc arbitratus sum propter Christum detrimenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Verumtamen existimo omnia detrimentum esse propter eminentem scientiam Jesu Christi Domini mei: propter quem omnia detrimentum feci, et arbitror ut stercora, ut Christum lucrifaciam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'et inveniar in illo non habens meam justitiam, quæ ex lege est, sed illam, quæ ex fide est Christi Jesu: quæ ex Deo est justitia in fide,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'ad cognoscendum illum, et virtutem resurrectionis ejus, et societatem passionum illius: configuratus morti ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'si quo modo occurram ad resurrectionem, quæ est ex mortuis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'non quod jam acceperim, aut jam perfectus sim: sequor autem, si quomodo comprehendam in quo et comprehensus sum a Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'Fratres, ego me non arbitror comprehendisse. Unum autem, quæ quidem retro sunt obliviscens, ad ea vero quæ sunt priora, extendens meipsum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'ad destinatum persequor, ad bravium supernæ vocationis Dei in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Quicumque ergo perfecti sumus, hoc sentiamus: et si quid aliter sapitis, et hoc vobis Deus revelabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Verumtamen ad quod pervenimus ut idem sapiamus, et in eadem permaneamus regula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Imitatores mei estote, fratres, et observate eos qui ita ambulant, sicut habetis formam nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 18, 'Multi enim ambulant, quos sæpe dicebam vobis (nunc autem et flens dico) inimicos crucis Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 19, 'quorum finis interitus: quorum Deus venter est: et gloria in confusione ipsorum, qui terrena sapiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 20, 'Nostra autem conversatio in cælis est: unde etiam Salvatorem exspectamus Dominum nostrum Jesum Christum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 21, 'qui reformabit corpus humilitatis nostræ, configuratum corpori claritatis suæ, secundum operationem, qua etiam possit subjicere sibi omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Itaque fratres mei carissimi, et desideratissimi, gaudium meum, et corona mea: sic state in Domino, carissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'Evodiam rogo, et Syntychen deprecor, idipsum sapere in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Etiam rogo et te, germane compar, adjuva illas, quæ mecum laboraverunt in Evangelio cum Clemente, et ceteris adjutoribus meis, quorum nomina sunt in libro vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'Gaudete in Domino semper: iterum dico gaudete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Modestia vestra nota sit omnibus hominibus: Dominus prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'Nihil solliciti sitis: sed in omni oratione, et obsecratione, cum gratiarum actione petitiones vestræ innotescant apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Et pax Dei, quæ exuperat omnem sensum, custodiat corda vestra, et intelligentias vestras in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'De cetero fratres, quæcumque sunt vera, quæcumque pudica, quæcumque justa, quæcumque sancta, quæcumque amabilia, quæcumque bonæ famæ, siqua virtus, siqua laus disciplinæ, hæc cogitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'Quæ et didicistis, et accepistis, et audistis, et vidistis in me, hæc agite: et Deus pacis erit vobiscum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Gavisus sum autem in Domino vehementer, quoniam tandem aliquando refloruistis pro me sentire, sicut et sentiebatis: occupati autem eratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Non quasi propter penuriam dico: ego enim didici, in quibus sum, sufficiens esse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Scio et humiliari, scio et abundare (ubique et in omnibus institutus sum): et satiari, et esurire, et abundare, et penuriam pati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Omnia possum in eo qui me confortat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'Verumtamen bene fecistis, communicantes tribulationi meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, 'Scitis autem et vos Philippenses, quod in principio Evangelii, quando profectus sum a Macedonia, nulla mihi ecclesia communicavit in ratione dati et accepti, nisi vos soli:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'quia et Thessalonicam semel et bis in usum mihi misistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Non quia quæro datum, sed requiro fructum abundantem in ratione vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Habeo autem omnia, et abundo: repletus sum, acceptis ab Epaphrodito quæ misistis odorem suavitatis, hostiam acceptam, placentem Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'Deus autem meus impleat omne desiderium vestrum secundum divitias suas in gloria in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Deo autem et Patri nostro gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'Salutate omnem sanctum in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Salutant vos, qui mecum sunt, fratres. Salutant vos omnes sancti, maxime autem qui de Cæsaris domo sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Gratia Domini nostri Jesu Christi cum spiritu vestro. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Paulus Apostolus Jesu Christi per voluntatem Dei, et Timotheus frater:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'eis, qui sunt Colossis, sanctis, et fidelibus fratribus in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo. Gratias agimus Deo, et Patri Domini nostri Jesu Christi semper pro vobis orantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'audientes fidem vestram in Christo Jesu, et dilectionem quam habetis in sanctos omnes');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'propter spem, quæ reposita est vobis in cælis: quam audistis in verbo veritatis Evangelii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'quod pervenit ad vos, sicut et in universo mundo est, et fructificat, et crescit sicut in vobis, ex ea die, qua audistis, et cognovistis gratiam Dei in veritate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'sicut didicistis ab Epaphra carissimo conservo nostro, qui est fidelis pro vobis minister Christi Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'qui etiam manifestavit nobis dilectionem vestram in spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ideo et nos ex qua die audivimus, non cessamus pro vobis orantes, et postulantes ut impleamini agnitione voluntatis ejus, in omni sapientia et intellectu spiritali:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'ut ambuletis digne Deo per omnia placentes: in omni opere bono fructificantes, et crescentes in scientia Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'in omni virtute confortati secundum potentiam claritatis ejus, in omni patientia et longanimitate cum gaudio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'gratias agentes Deo Patri, qui dignos nos fecit in partem sortis sanctorum in lumine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'qui eripuit nos de potestate tenebrarum, et transtulit in regnum filii dilectionis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'in quo habemus redemptionem per sanguinem ejus, remissionem peccatorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'qui est imago Dei invisibilis, primogenitus omnis creaturæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'quoniam in ipso condita sunt universa in cælis, et in terra, visibilia, et invisibilia, sive throni, sive dominationes, sive principatus, sive potestates: omnia per ipsum et in ipso creata sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'et ipse est ante omnes, et omnia in ipso constant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'Et ipse est caput corporis Ecclesiæ, qui est principium, primogenitus ex mortuis: ut sit in omnibus ipse primatum tenens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'quia in ipso complacuit, omnem plenitudinem inhabitare:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'et per eum reconciliare omnia in ipsum, pacificans per sanguinem crucis ejus, sive quæ in terris, sive quæ in cælis sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Et vos cum essetis aliquando alienati, et inimici sensu in operibus malis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'nunc autem reconciliavit in corpore carnis ejus per mortem, exhibere vos sanctos, et immaculatos, et irreprehensibiles coram ipso:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'si tamen permanetis in fide fundati, et stabiles, et immobiles a spe Evangelii, quod audistis, quod prædicatum est in universa creatura, quæ sub cælo est, cujus factus sum ego Paulus minister.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'Qui nunc gaudeo in passionibus pro vobis, et adimpleo ea quæ desunt passionum Christi, in carne mea pro corpore ejus, quod est Ecclesia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'cujus factus sum ego minister secundum dispensationem Dei, quæ data est mihi in vos, ut impleam verbum Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'mysterium, quod absconditum fuit a sæculis, et generationibus, nunc autem manifestatum est sanctis ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 27, 'quibus voluit Deus notas facere divitias gloriæ sacramenti hujus in gentibus, quod est Christus, in vobis spes gloriæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 28, 'quem nos annuntiamus, corripientes omnem hominem, et docentes omnem hominem, in omni sapientia, ut exhibeamus omnem hominem perfectum in Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 29, 'in quo et laboro, certando secundum operationem ejus, quam operatur in me in virtute.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Volo enim vos scire qualem sollicitudinem habeam pro vobis, et pro iis qui sunt Laodiciæ, et quicumque non viderunt faciem meam in carne:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'ut consolentur corda ipsorum, instructi in caritate, et in omnes divitias plenitudinis intellectus, in agnitionem mysterii Dei Patris et Christi Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'in quo sunt omnes thesauri sapientiæ et scientiæ absconditi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Hoc autem dico, ut nemo vos decipiat in sublimitate sermonum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Nam etsi corpore absens sum, sed spiritu vobiscum sum: gaudens, et videns ordinem vestrum, et firmamentum ejus, quæ in Christo est, fidei vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Sicut ergo accepistis Jesum Christum Dominum, in ipso ambulate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'radicati, et superædificati in ipso, et confirmati fide, sicut et didicistis, abundantes in illo in gratiarum actione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Videte ne quis vos decipiat per philosophiam, et inanem fallaciam secundum traditionem hominum, secundum elementa mundi, et non secundum Christum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'quia in ipso inhabitat omnis plenitudo divinitatis corporaliter:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'et estis in illo repleti, qui est caput omnis principatus et potestatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'in quo et circumcisi estis circumcisione non manu facta in expoliatione corporis carnis, sed in circumcisione Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'consepulti ei in baptismo, in quo et resurrexistis per fidem operationis Dei, qui suscitavit illum a mortuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Et vos cum mortui essetis in delictis, et præputio carnis vestræ, convivificavit cum illo, donans vobis omnia delicta:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'delens quod adversus nos erat chirographum decreti, quod erat contrarium nobis, et ipsum tulit de medio, affigens illud cruci:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'et expolians principatus, et potestates traduxit confidenter, palam triumphans illos in semetipso.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Nemo ergo vos judicet in cibo, aut in potu, aut in parte diei festi, aut neomeniæ, aut sabbatorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'quæ sunt umbra futurorum: corpus autem Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Nemo vos seducat, volens in humilitate, et religione angelorum, quæ non vidit ambulans, frustra inflatus sensu carnis suæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'et non tenens caput, ex quo totum corpus per nexus, et conjunctiones subministratum, et constructum crescit in augmentum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Si ergo mortui estis cum Christo ab elementis hujus mundi: quid adhuc tamquam viventes in mundo decernitis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ne tetigeritis, neque gustaveritis, neque contrectaveritis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'quæ sunt omnia in interitum ipso usu, secundum præcepta et doctrinas hominum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'quæ sunt rationem quidem habentia sapientiæ in superstitione, et humilitate, et non ad parcendum corpori, non in honore aliquo ad saturitatem carnis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Igitur, si consurrexistis cum Christo: quæ sursum sunt quærite, ubi Christus est in dextera Dei sedens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'quæ sursum sunt sapite, non quæ super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Mortui enim estis, et vita vestra est abscondita cum Christo in Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Cum Christus apparuerit, vita vestra: tunc et vos apparebitis cum ipso in gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Mortificate ergo membra vestra, quæ sunt super terram: fornicationem, immunditiam, libidinem, concupiscentiam malam, et avaritiam, quæ est simulacrorum servitus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'propter quæ venit ira Dei super filios incredulitatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'in quibus et vos ambulastis aliquando, cum viveretis in illis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Nunc autem deponite et vos omnia: iram, indignationem, malitiam, blasphemiam, turpem sermonem de ore vestro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Nolite mentiri invicem, expoliantes vos veterem hominem cum actibus suis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'et induentes novum eum, qui renovatur in agnitionem secundum imaginem ejus qui creavit illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'ubi non est gentilis et Judæus, circumcisio et præputium, Barbarus et Scytha, servus et liber: sed omnia, et in omnibus Christus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Induite vos ergo, sicut electi Dei, sancti, et dilecti, viscera misericordiæ, benignitatem, humilitatem, modestiam, patientiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'supportantes invicem, et donantes vobismetipsis si quis adversus aliquem habet querelam: sicut et Dominus donavit vobis, ita et vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Super omnia autem hæc, caritatem habete, quod est vinculum perfectionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'et pax Christi exsultet in cordibus vestris, in qua et vocati estis in uno corpore: et grati estote.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Verbum Christi habitet in vobis abundanter, in omni sapientia, docentes, et commonentes vosmetipsos, psalmis, hymnis, et canticis spiritualibus, in gratia cantantes in cordibus vestris Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Omne, quodcumque facitis in verbo aut in opere, omnia in nomine Domini Jesu Christi, gratias agentes Deo et Patri per ipsum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Mulieres, subditæ estote viris, sicut oportet, in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Viri, diligite uxores vestras, et nolite amari esse ad illas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Filii, obedite parentibus per omnia: hoc enim placitum est in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Patres, nolite ad indignationem provocare filios vestros, ut non pusillo animo fiant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Servi, obedite per omnia dominis carnalibus, non ad oculum servientes, quasi hominibus placentes, sed in simplicitate cordis, timentes Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Quodcumque facitis, ex animo operamini sicut Domino, et non hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'scientes quod a Domino accipietis retributionem hæreditatis. Domino Christo servite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Qui enim injuriam facit, recipiet id quod inique gessit: et non est personarum acceptio apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Domini, quod justum est et æquum, servis præstate: scientes quod et vos Dominum habetis in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Orationi instate, vigilantes in ea in gratiarum actione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'orantes simul et pro nobis, ut Deus aperiat nobis ostium sermonis ad loquendum mysterium Christi (propter quod etiam vinctus sum),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'ut manifestem illud ita ut oportet me loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'In sapientia ambulate ad eos, qui foris sunt: tempus redimentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Sermo vester semper in gratia sale sit conditus, ut sciatis quomodo oporteat vos unicuique respondere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Quæ circa me sunt, omnia vobis nota faciet Tychicus, carissimus frater, et fidelis minister, et conservus in Domino:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'quem misi ad vos ad hoc ipsum, ut cognoscat quæ circa vos sunt, et consoletur corda vestra,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'cum Onesimo carissimo, et fideli fratre, qui ex vobis est. Omnia, quæ hic aguntur, nota facient vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Salutat vos Aristarchus concaptivus meus, et Marcus consobrinus Barnabæ, de quo accepistis mandata: si venerit ad vos, excipite illum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'et Jesus, qui dicitur Justus: qui sunt ex circumcisione: hi soli sunt adjutores mei in regno Dei, qui mihi fuerunt solatio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Salutat vos Epaphras, qui ex vobis est, servus Christi Jesu, semper sollicitus pro vobis in orationibus, ut stetis perfecti, et pleni in omni voluntate Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Testimonium enim illi perhibeo quod habet multum laborem pro vobis, et pro iis qui sunt Laodiciæ, et qui Hierapoli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Salutat vos Lucas, medicus carissimus, et Demas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Salutate fratres, qui sunt Laodiciæ, et Nympham, et quæ in domo ejus est, ecclesiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Et cum lecta fuerit apud vos epistola hæc, facite ut et in Laodicensium ecclesia legatur: et eam, quæ Laodicensium est, vos legatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'Et dicite Archippo: Vide ministerium, quod accepisti in Domino, ut illud impleas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Salutatio, mea manu Pauli. Memores estote vinculorum meorum. Gratia vobiscum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Paulus, et Silvanus, et Timotheus ecclesiæ Thessalonicensium in Deo Patre, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Gratia vobis, et pax. Gratias agimus Deo semper pro omnibus vobis, memoriam vestri facientes in orationibus nostris sine intermissione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'memores operis fidei vestræ, et laboris, et caritatis, et sustinentiæ spei Domini nostri Jesu Christi, ante Deum et Patrem nostrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'scientes, fratres dilecti a Deo, electionem vestram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'quia Evangelium nostrum non fuit ad vos in sermone tantum, sed et in virtute, et in Spiritu Sancto, et in plenitudine multa, sicut scitis quales fuerimus in vobis propter vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Et vos imitatores nostri facti estis, et Domini, excipientes verbum in tribulatione multa, cum gaudio Spiritus Sancti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'ita ut facti sitis forma omnibus credentibus in Macedonia, et in Achaia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'A vobis enim diffamatus est sermo Domini, non solum in Macedonia, et in Achaia, sed et in omni loco fides vestra, quæ est ad Deum, profecta est ita ut non sit nobis necesse quidquam loqui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Ipsi enim de nobis annuntiant qualem introitum habuerimus ad vos: et quomodo conversi estis ad Deum a simulacris, servire Deo vivo, et vero,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'et exspectare Filium ejus de cælis (quem suscitavit a mortuis) Jesum, qui eripuit nos ab ira ventura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Nam ipsi scitis, fratres, introitum nostrum ad vos, quia non inanis fuit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'sed ante passi, et contumeliis affecti (sicut scitis) in Philippis, fiduciam habuimus in Deo nostro, loqui ad vos Evangelium Dei in multa sollicitudine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Exhortatio enim nostra non de errore, neque de immunditia, neque in dolo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'sed sicut probati sumus a Deo ut crederetur nobis Evangelium: ita loquimur non quasi hominibus placentes, sed Deo, qui probat corda nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Neque enim aliquando fuimus in sermone adulationis, sicut scitis: neque in occasione avaritiæ: Deus testis est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'nec quærentes ab hominibus gloriam, neque a vobis, neque ab aliis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Cum possemus vobis oneri esse ut Christi apostoli: sed facti sumus parvuli in medio vestrum, tamquam si nutrix foveat filios suos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ita desiderantes vos, cupide volebamus tradere vobis non solum Evangelium Dei, sed etiam animas nostras: quoniam carissimi nobis facti estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Memores enim estis, fratres, laboris nostri, et fatigationis: nocte ac die operantes, ne quem vestrum gravaremus, prædicavimus in vobis Evangelium Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Vos testes estis, et Deus, quam sancte, et juste, et sine querela, vobis, qui credidistis, fuimus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'sicut scitis, qualiter unumquemque vestrum (sicut pater filios suos)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'deprecantes vos, et consolantes, testificati sumus, ut ambularetis digne Deo, qui vocavit vos in suum regnum et gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ideo et nos gratias agimus Deo sine intermissione: quoniam cum accepissetis a nobis verbum auditus Dei, accepistis illud, non ut verbum hominum, sed (sicut est vere) verbum Dei, qui operatur in vobis, qui credidistis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'vos enim imitatores facti estis, fratres, ecclesiarum Dei, quæ sunt in Judæa in Christo Jesu: quia eadem passi estis et vos a contribulibus vestris, sicut et ipsi a Judæis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'qui et Dominum occiderunt Jesum, et prophetas, et nos persecuti sunt, et Deo non placent, et omnibus hominibus adversantur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'prohibentes nos gentibus loqui ut salvæ fiant, ut impleant peccata sua semper: pervenit enim ira Dei super illos usque in finem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Nos autem fratres desolati a vobis ad tempus horæ, aspectu, non corde, abundantius festinavimus faciem vestram videre cum multo desiderio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'quoniam voluimus venire ad vos, ego quidem Paulus, et semel, et iterum: sed impedivit nos Satanas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Quæ est enim nostra spes aut gaudium, aut corona gloriæ? nonne vos ante Dominum nostrum Jesum Christum estis in adventu ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'vos enim estis gloria nostra et gaudium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Propter quod non sustinentes amplius, placuit nobis remanere Athenis, solis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'et misimus Timotheum fratrem nostrum, et ministrum Dei in Evangelio Christi, ad confirmandos vos, et exhortandos pro fide vestra:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'ut nemo moveatur in tribulationibus istis: ipsi enim scitis quod in hoc positi sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Nam et cum apud vos essemus, prædicebamus vobis passuros nos tribulationes, sicut et factum est, et scitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Propterea et ego amplius non sustinens, misi ad cognoscendam fidem vestram: ne forte tentaverit vos is qui tentat, et inanis fiat labor noster.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Nunc autem veniente Timotheo ad nos a vobis, et annuntiante nobis fidem et caritatem vestram, et quia memoriam nostri habetis bonam semper, desiderantes nos videre, sicut et nos quoque vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'ideo consolati sumus, fratres, in vobis in omni necessitate et tribulatione nostra, per fidem vestram,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'quoniam nunc vivimus, si vos statis in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Quam enim gratiarum actionem possumus Deo retribuere pro vobis in omni gaudio, quo gaudemus propter vos ante Deum nostrum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'nocte ac die abundantius orantes, ut videamus faciem vestram, et compleamus ea quæ desunt fidei vestræ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Ipse autem Deus, et Pater noster, et Dominus noster Jesus Christus, dirigat viam nostram ad vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Vos autem Dominus multiplicet, et abundare faciat caritatem vestram in invicem, et in omnes, quemadmodum et nos in vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'ad confirmanda corda vestra sine querela in sanctitate, ante Deum et Patrem nostrum, in adventu Domini nostri Jesu Christi cum omnibus sanctis ejus. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'De cetero ergo, fratres, rogamus vos et obsecramus in Domino Jesu, ut quemadmodum accepistis a nobis quomodo oporteat vos ambulare, et placere Deo, sic et ambuletis ut abundetis magis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Scitis enim quæ præcepta dederim vobis per Dominum Jesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Hæc est enim voluntas Dei, sanctificatio vestra: ut abstineatis vos a fornicatione,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'ut sciat unusquisque vestrum vas suum possidere in sanctificatione, et honore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'non in passione desiderii, sicut et gentes, quæ ignorant Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'et ne quis supergrediatur, neque circumveniat in negotio fratrem suum: quoniam vindex est Dominus de his omnibus, sicut prædiximus vobis, et testificati sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Non enim vocavit nos Deus in immunditiam, sed in sanctificationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Itaque qui hæc spernit, non hominem spernit, sed Deum: qui etiam dedit Spiritum suum Sanctum in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'De caritate autem fraternitatis non necesse habemus scribere vobis: ipsi enim vos a Deo didicistis ut diligatis invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Etenim illud facitis in omnes fratres in universa Macedonia. Rogamus autem vos, fratres, ut abundetis magis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'et operam detis ut quieti sitis, et ut vestrum negotium agatis, et operemini manibus vestris, sicut præcepimus vobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'et ut honeste ambuletis ad eos qui foris sunt: et nullius aliquid desideretis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nolumus autem vos ignorare fratres de dormientibus, ut non contristemini sicut et ceteri, qui spem non habent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Si enim credimus quod Jesus mortuus est, et resurrexit: ita et Deus eos qui dormierunt per Jesum, adducet cum eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Hoc enim vobis dicimus in verbo Domini, quia nos, qui vivimus, qui residui sumus in adventum Domini, non præveniemus eos qui dormierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Quoniam ipse Dominus in jussu, et in voce archangeli, et in tuba Dei descendet de cælo: et mortui, qui in Christo sunt, resurgent primi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Deinde nos, qui vivimus, qui relinquimur, simul rapiemur cum illis in nubibus obviam Christo in aëra, et sic semper cum Domino erimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Itaque consolamini invicem in verbis istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'De temporibus autem, et momentis, fratres, non indigetis ut scribamus vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Ipsi enim diligenter scitis quia dies Domini, sicut fur in nocte, ita veniet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'cum enim dixerint: Pax et securitas: tunc repentinus eis superveniet interitus, sicut dolor in utero habenti, et non effugient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Vos autem, fratres, non estis in tenebris, ut vos dies illa tamquam fur comprehendat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'omnes enim vos filii lucis estis, et filii diei: non sumus noctis, neque tenebrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Igitur non dormiamus sicut et ceteri, sed vigilemus, et sobrii simus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Qui enim dormiunt, nocte dormiunt: et qui ebrii sunt, nocte ebrii sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Nos autem, qui diei sumus, sobrii simus, induti loricam fidei et caritatis, et galeam spem salutis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'quoniam non posuit nos Deus in iram, sed in acquisitionem salutis per Dominum nostrum Jesum Christum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'qui mortuus est pro nobis: ut sive vigilemus, sive dormiamus, simul cum illo vivamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Propter quod consolamini invicem, et ædificate alterutrum, sicut et facitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Rogamus autem vos, fratres, ut noveritis eos qui laborant inter vos, et præsunt vobis in Domino, et monent vos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'ut habeatis illos abundantius in caritate propter opus illorum: pacem habete cum eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Rogamus autem vos, fratres, corripite inquietos, consolamini pusillanimes, suscipite infirmos, patientes estote ad omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Videte ne quis malum pro malo alicui reddat: sed semper quod bonum est sectamini in invicem, et in omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Semper gaudete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Sine intermissione orate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'In omnibus gratias agite: hæc est enim voluntas Dei in Christo Jesu in omnibus vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Spiritum nolite extinguere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Prophetias nolite spernere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Omnia autem probate: quod bonum est tenete.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Ab omni specie mala abstinete vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'Ipse autem Deus pacis sanctificet vos per omnia: ut integer spiritus vester, et anima, et corpus sine querela in adventu Domini nostri Jesu Christi servetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Fidelis est, qui vocavit vos: qui etiam faciet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Fratres, orate pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'Salutate fratres omnes in osculo sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'Adjuro vos per Dominum ut legatur epistola hæc omnibus sanctis fratribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Gratia Domini nostri Jesu Christi vobiscum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Paulus, et Sylvanus, et Timotheus, ecclesiæ Thessalonicensium in Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gratias agere debemus semper Deo pro vobis, fratres, ita ut dignum est, quoniam supercrescit fides vestra, et abundat caritas uniuscujusque vestrum in invicem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'ita ut et nos ipsi in vobis gloriemur in ecclesiis Dei, pro patientia vestra, et fide, et in omnibus persecutionibus vestris, et tribulationibus, quas sustinetis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'in exemplum justi judicii Dei, ut digni habeamini in regno Dei, pro quo et patimini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Si tamen justum est apud Deum retribuere tribulationem iis qui vos tribulant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'et vobis, qui tribulamini, requiem nobiscum in revelatione Domini Jesu de cælo cum angelis virtutis ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'in flamma ignis dantis vindictam iis qui non noverunt Deum, et qui non obediunt Evangelio Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'qui pœnas dabunt in interitu æternas a facie Domini, et a gloria virtutis ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'cum venerit glorificari in sanctis suis, et admirabilis fieri in omnibus, qui crediderunt, quia creditum est testimonium nostrum super vos in die illo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'In quo etiam oramus semper pro vobis: ut dignetur vos vocatione sua Deus noster, et impleat omnem voluntatem bonitatis, et opus fidei in virtute,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'ut clarificetur nomen Domini nostri Jesu Christi in vobis, et vos in illo secundum gratiam Dei nostri, et Domini Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Rogamus autem vos, fratres, per adventum Domini nostri Jesu Christi, et nostræ congregationis in ipsum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'ut non cito moveamini a vestro sensu, neque terreamini, neque per spiritum, neque per sermonem, neque per epistolam tamquam per nos missam, quasi instet dies Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Ne quis vos seducat ullo modo: quoniam nisi venerit discessio primum, et revelatus fuerit homo peccati filius perditionis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'qui adversatur, et extollitur supra omne, quod dicitur Deus, aut quod colitur, ita ut in templo Dei sedeat ostendens se tamquam sit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Non retinetis quod cum adhuc essem apud vos, hæc dicebam vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'et nunc quid detineat scitis, ut reveletur in suo tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Nam mysterium jam operatur iniquitatis: tantum ut qui tenet nunc, teneat, donec de medio fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Et tunc revelabitur ille iniquus, quem Dominus Jesus interficiet spiritu oris sui, et destruet illustratione adventus sui eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'cujus est adventus secundum operationem Satanæ in omni virtute, et signis, et prodigiis mendacibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'et in omni seductione iniquitatis iis qui pereunt: eo quod caritatem veritatis non receperunt ut salvi fierent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Ideo mittet illis Deus operationem erroris ut credant mendacio,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'ut judicentur omnes qui non crediderunt veritati, sed consenserunt iniquitati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Nos autem debemus gratias agere Deo semper pro vobis, fratres dilecti a Deo, quod elegerit vos Deus primitias in salutem in sanctificatione spiritus, et in fide veritatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'in qua et vocavit vos per Evangelium nostrum in acquisitionem gloriæ Domini nostri Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Itaque fratres, state: et tenete traditiones, quas didicistis, sive per sermonem, sive per epistolam nostram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Ipse autem Dominus noster Jesus Christus, et Deus et Pater noster, qui dilexit nos, et dedit consolationem æternam, et spem bonam in gratia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'exhortetur corda vestra, et confirmet in omni opere et sermone bono.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'De cetero fratres, orate pro nobis ut sermo Dei currat, et clarificetur, sicut et apud vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'et ut liberemur ab importunis, et malis hominibus: non enim omnium est fides.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Fidelis autem Deus est, qui confirmabit vos, et custodiet a malo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Confidimus autem de vobis, in Domino, quoniam quæ præcepimus, et facitis, et facietis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Dominus autem dirigat corda vestra in caritate Dei, et patientia Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Denuntiamus autem vobis, fratres, in nomine Domini nostri Jesu Christi, ut subtrahatis vos ab omni fratre ambulante inordinate, et non secundum traditionem, quam acceperunt a nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Ipsi enim scitis quemadmodum oporteat imitari nos: quoniam non inquieti fuimus inter vos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'neque gratis panem manducavimus ab aliquo, sed in labore, et in fatigatione, nocte et die operantes, ne quem vestrum gravaremus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Non quasi non habuerimus potestatem, sed ut nosmetipsos formam daremus vobis ad imitandum nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Nam et cum essemus apud vos, hoc denuntiabamus vobis: quoniam si quis non vult operari, nec manducet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Audivimus enim inter vos quosdam ambulare inquiete, nihil operantes, sed curiose agentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Iis autem, qui ejusmodi sunt, denuntiemus, et obsecramus in Domino Jesu Christo, ut cum silentio operantes, suum panem manducent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Vos autem, fratres, nolite deficere benefacientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Quod si quis non obedit verbo nostro per epistolam, hunc notate, et ne commisceamini cum illo ut confundatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'et nolite quasi inimicum existimare, sed corripite ut fratrem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Ipse autem Dominus pacis det vobis pacem sempiternam in omni loco. Dominus sit cum omnibus vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Salutatio, mea manu Pauli: quod est signum in omni epistola, ita scribo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Gratia Domini nostri Jesu Christi cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Paulus Apostolus Jesu Christi secundum imperium Dei Salvatoris nostri, et Christi Jesu spei nostræ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Timotheo dilecto filio in fide. Gratia, misericordia, et pax a Deo Patre, et Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Sicut rogavi te ut remaneres Ephesi cum irem in Macedoniam, ut denuntiares quibusdam ne aliter docerent,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'neque intenderent fabulis, et genealogiis interminatis: quæ quæstiones præstant magis quam ædificationem Dei, quæ est in fide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Finis autem præcepti est caritas de corde puro, et conscientia bona, et fide non ficta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'A quibus quidam aberrantes, conversi sunt in vaniloquium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'volentes esse legis doctores, non intelligentes neque quæ loquuntur, neque de quibus affirmant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Scimus autem quia bona est lex si quis ea legitime utatur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'sciens hoc quia lex justo non est posita, sed injustis, et non subditis, impiis, et peccatoribus, sceleratis, et contaminatis, parricidis, et matricidis, homicidis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'fornicariis, masculorum concubitoribus, plagiariis, mendacibus, et perjuris, et si quid aliud sanæ doctrinæ adversatur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'quæ est secundum Evangelium gloriæ beati Dei, quod creditum est mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Gratias ago ei, qui me confortavit, Christo Jesu Domino nostro, quia fidelem me existimavit, ponens in ministerio:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'qui prius blasphemus fui, et persecutor, et contumeliosus: sed misericordiam Dei consecutus sum, quia ignorans feci in incredulitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Superabundavit autem gratia Domini nostri cum fide, et dilectione, quæ est in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Fidelis sermo, et omni acceptione dignus: quod Christus Jesus venit in hunc mundum peccatores salvos facere, quorum primus ego sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Sed ideo misericordiam consecutus sum: ut in me primo ostenderet Christus Jesus omnem patientiam ad informationem eorum, qui credituri sunt illi, in vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Regi autem sæculorum immortali, invisibili, soli Deo honor et gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Hoc præceptum commendo tibi, fili Timothee, secundum præcedentes in te prophetias, ut milites in illis bonam militiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'habens fidem, et bonam conscientiam, quam quidam repellentes, circa fidem naufragaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'ex quibus est Hymenæus, et Alexander: quos tradidi Satanæ, ut discant non blasphemare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Obsecro igitur primum omnium fieri obsecrationes, orationes, postulationes, gratiarum actiones, pro omnibus hominibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'pro regibus, et omnibus qui in sublimitate sunt, ut quietam et tranquillam vitam agamus in omni pietate, et castitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'hoc enim bonum est, et acceptum coram Salvatore nostro Deo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'qui omnes homines vult salvos fieri, et ad agnitionem veritatis venire.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Unus enim Deus, unus et mediator Dei et hominum homo Christus Jesus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'qui dedit redemptionem semetipsum pro omnibus, testimonium temporibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'in quo positus sum ego prædicator, et Apostolus (veritatem dico, non mentior) doctor gentium in fide, et veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Volo ergo viros orare in omni loco, levantes puras manus sine ira et disceptatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Similiter et mulieres in habitu ornato, cum verecundia et sobrietate ornantes se, et non in tortis crinibus, aut auro, aut margaritis, vel veste pretiosa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'sed quod decet mulieres, promittentes pietatem per opera bona.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Mulier in silentio discat cum omni subjectione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Docere autem mulieri non permitto, neque dominari in virum: sed esse in silentio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Adam enim primus formatus est: deinde Heva:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'et Adam non est seductus: mulier autem seducta in prævaricatione fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Salvabitur autem per filiorum generationem, si permanserit in fide, et dilectione, et sanctificatione cum sobrietate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Fidelis sermo: si quis episcopatum desiderat, bonum opus desiderat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Oportet ergo episcopum irreprehensibilem esse, unius uxoris virum, sobrium, prudentem, ornatum, pudicum, hospitalem, doctorem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'non vinolentum, non percussorem, sed modestum: non litigiosum, non cupidum, sed');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'suæ domui bene præpositum: filios habentem subditos cum omni castitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Si quis autem domui suæ præesse nescit, quomodo ecclesiæ Dei diligentiam habebit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Non neophytum: ne in superbiam elatus, in judicium incidat diaboli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Oportet autem illum et testimonium habere bonum ab iis qui foris sunt, ut non in opprobrium incidat, et in laqueum diaboli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Diaconos similiter pudicos, non bilingues, non multo vino deditos, non turpe lucrum sectantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'habentes mysterium fidei in conscientia pura.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Et hi autem probentur primum: et sic ministrent, nullum crimen habentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Mulieres similiter pudicas, non detrahentes, sobrias, fideles in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Diaconi sint unius uxoris viri, qui filiis suis bene præsint, et suis domibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Qui enim bene ministraverint, gradum bonum sibi acquirent, et multam fiduciam in fide, quæ est in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Hæc tibi scribo, sperans me ad te venire cito:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'si autem tardavero, ut scias quomodo oporteat te in domo Dei conversari, quæ est ecclesia Dei vivi, columna et firmamentum veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Et manifeste magnum est pietatis sacramentum, quod manifestatum est in carne, justificatum est in spiritu, apparuit angelis, prædicatum est gentibus, creditum est in mundo, assumptum est in gloria.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Spiritus autem manifeste dicit, quia in novissimis temporibus discedent quidam a fide, attendentes spiritibus erroris, et doctrinis dæmoniorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'in hypocrisi loquentium mendacium, et cauteriatam habentium suam conscientiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'prohibentium nubere, abstinere a cibis, quod Deus creavit ad percipiendum cum gratiarum actione fidelibus, et iis qui cognoverunt veritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Quia omnis creatura Dei bona est, et nihil rejiciendum quod cum gratiarum actione percipitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'sanctificatur enim per verbum Dei, et orationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'Hæc proponens fratribus, bonus eris minister Christi Jesu enutritus verbis fidei, et bonæ doctrinæ, quam assecutus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Ineptas autem, et aniles fabulas devita: exerce autem teipsum ad pietatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Nam corporalis exercitatio, ad modicum utilis est: pietas autem ad omnia utilis est, promissionem habens vitæ, quæ nunc est, et futuræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Fidelis sermo, et omni acceptione dignus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'In hoc enim laboramus, et maledicimur, quia speramus in Deum vivum, qui est Salvator omnium hominum, maxime fidelium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Præcipe hæc, et doce.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Nemo adolescentiam tuam contemnat: sed exemplum esto fidelium in verbo, in conversatione, in caritate, in fide, in castitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Dum venio, attende lectioni, exhortationi, et doctrinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Noli negligere gratiam, quæ in te est, quæ data est tibi per prophetiam, cum impositione manuum presbyterii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Hæc meditare, in his esto: ut profectus tuus manifestus sit omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'Attende tibi, et doctrinæ: insta in illis. Hoc enim faciens, et teipsum salvum facies, et eos qui te audiunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Seniorem ne increpaveris, sed obsecra ut patrem: juvenes, ut fratres:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'anus, ut matres: juvenculas, ut sorores in omni castitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'viduas honora, quæ vere viduæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Si qua autem vidua filios, aut nepotes habet: discat primum domum suam regere, et mutuam vicem reddere parentibus: hoc enim acceptum est coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'Quæ autem vere vidua est, et desolata, speret in Deum, et instet obsecrationibus, et orationibus nocte ac die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Nam quæ in deliciis est, vivens mortua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'Et hoc præcipe, ut irreprehensibiles sint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Si quis autem suorum, et maxime domesticorum, curam non habet, fidem negavit, et est infideli deterior.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Vidua eligatur non minus sexaginta annorum, quæ fuerit unius viri uxor,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'in operibus bonis testimonium habens, si filios educavit, si hospitio recepit, si sanctorum pedes lavit, si tribulationem patientibus subministravit, si omne opus bonum subsecuta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Adolescentiores autem viduas devita: cum enim luxuriatæ fuerint in Christo, nubere volunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'habentes damnationem, quia primam fidem irritam fecerunt;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'simul autem et otiosæ discunt circuire domos: non solum otiosæ, sed et verbosæ, et curiosæ, loquentes quæ non oportet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Volo ergo juniores nubere, filios procreare, matresfamilias esse, nullam occasionem dare adversario maledicti gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Jam enim quædam conversæ sunt retro Satanam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Si quis fidelis habet viduas, subministret illis, et non gravetur ecclesia: ut iis quæ vere viduæ sunt, sufficiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Qui bene præsunt presbyteri, duplici honore digni habeantur: maxime qui laborant in verbo et doctrina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'Dicit enim Scriptura: Non alligabis os bovi trituranti. Et: Dignus est operarius mercede sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'Adversus presbyterum accusationem noli recipere, nisi sub duobus aut tribus testibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, 'Peccantes coram omnibus argue: ut et ceteri timorem habeant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Testor coram Deo et Christo Jesu, et electis angelis, ut hæc custodias sine præjudicio, nihil faciens in alteram partem declinando.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Manus cito nemini imposueris, neque communicaveris peccatis alienis. Teipsum castum custodi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'Noli adhuc aquam bibere, sed modico vino utere propter stomachum tuum, et frequentes tuas infirmitates.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'Quorumdam hominum peccata manifesta sunt, præcedentia ad judicium: quosdam autem et subsequuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, 'Similiter et facta bona, manifesta sunt: et quæ aliter se habent, abscondi non possunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'Quicumque sunt sub jugo servi, dominos suos omni honore dignos arbitrentur, ne nomen Domini et doctrina blasphemetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Qui autem fideles habent dominos, non contemnant, quia fratres sunt: sed magis serviant, quia fideles sunt et dilecti, qui beneficii participes sunt. Hæc doce, et exhortare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Si quis aliter docet, et non acquiescit sanis sermonibus Domini nostri Jesu Christi, et ei, quæ secundum pietatem est, doctrinæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'superbus est, nihil sciens, sed languens circa quæstiones, et pugnas verborum: ex quibus oriuntur invidiæ, contentiones, blasphemiæ, suspiciones malæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'conflictationes hominum mente corruptorum, et qui veritate privati sunt, existimantium quæstum esse pietatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'Est autem quæstus magnus pietas cum sufficientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Nihil enim intulimus in hunc mundum: haud dubium quod nec auferre quid possumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Habentes autem alimenta, et quibus tegamur, his contenti simus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'Nam qui volunt divites fieri, incidunt in tentationem, et in laqueum diaboli, et desideria multa inutilia, et nociva, quæ mergunt homines in interitum et perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'Radix enim omnium malorum est cupiditas: quam quidam appetentes erraverunt a fide, et inseruerunt se doloribus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Tu autem, o homo Dei, hæc fuge: sectare vero justitiam, pietatem, fidem, caritatem, patientiam, mansuetudinem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'Certa bonum certamen fidei, apprehende vitam æternam, in qua vocatus es, et confessus bonam confessionem coram multis testibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Præcipio tibi coram Deo, qui vivificat omnia, et Christo Jesu, qui testimonium reddidit sub Pontio Pilato, bonam confessionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'ut serves mandatum sine macula, irreprehensibile usque in adventum Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'quem suis temporibus ostendet beatus et solus potens, Rex regum, et Dominus dominantium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 16, 'qui solus habet immortalitatem, et lucem inhabitat inaccessibilem: quem nullus hominum vidit, sed nec videre potest: cui honor, et imperium sempiternum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 17, 'Divitibus hujus sæculi præcipe non sublime sapere, neque sperare in incerto divitiarum, sed in Deo vivo (qui præstat nobis omnia abunde ad fruendum)');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 18, 'bene agere, divites fieri in bonis operibus, facile tribuere, communicare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 19, 'thesaurizare sibi fundamentum bonum in futurum, ut apprehendant veram vitam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 20, 'O Timothee, depositum custodi, devitans profanas vocum novitates, et oppositiones falsi nominis scientiæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 21, 'quam quidam promittentes, circa fidem exciderunt. Gratia tecum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Paulus Apostolus Jesu Christi per voluntatem Dei, secundum promissionem vitæ, quæ est in Christo Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Timotheo carissimo filio: gratia, misericordia, pax a Deo Patre, et Christo Jesu Domino nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Gratias ago Deo, cui servio a progenitoribus in conscientia pura, quod sine intermissione habeam tui memoriam in orationibus meis, nocte ac die');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'desiderans te videre, memor lacrimarum tuarum, ut gaudio implear,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'recordationem accipiens ejus fidei, quæ est in te non ficta, quæ et habitavit primum in avia tua Loide, et matre tua Eunice, certus sum autem quod et in te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Propter quam causam admoneo te ut resuscites gratiam Dei, quæ est in te per impositionem manuum mearum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Non enim dedit nobis Deus spiritum timoris: sed virtutis, et dilectionis, et sobrietatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Noli itaque erubescere testimonium Domini nostri, neque me vinctum ejus: sed collabora Evangelio secundum virtutem Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'qui nos liberavit, et vocavit vocatione sua sancta, non secundum opera nostra, sed secundum propositum suum, et gratiam, quæ data est nobis in Christo Jesu ante tempora sæcularia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Manifestata est autem nunc per illuminationem Salvatoris nostri Jesu Christi, qui destruxit quidem mortem, illuminavit autem vitam, et incorruptionem per Evangelium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'in quo positus sum ego prædicator, et Apostolus, et magister gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'Ob quam causam etiam hæc patior, sed non confundor. Scio enim cui credidi, et certus sum quia potens est depositum meum servare in illum diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Formam habe sanorum verborum, quæ a me audisti in fide, et in dilectione in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Bonum depositum custodi per Spiritum Sanctum, qui habitat in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'Scis hoc, quod aversi sunt a me omnes, qui in Asia sunt, ex quibus est Phigellus, et Hermogenes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'Det misericordiam Dominus Onesiphori domui: quia sæpe me refrigeravit, et catenam meam non erubuit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'sed cum Romam venisset, sollicite me quæsivit, et invenit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'Det illi Dominus invenire misericordiam a Domino in illa die. Et quanta Ephesi ministravit mihi, tu melius nosti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Tu ergo fili mi, confortare in gratia, quæ est in Christo Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'et quæ audisti a me per multos testes, hæc commenda fidelibus hominibus, qui idonei erant et alios docere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Labora sicut bonus miles Christi Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Nemo militans Deo implicat se negotiis sæcularibus: ut ei placeat, cui se probavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Nam et qui certat in agone, non coronatur nisi legitime certaverit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Laborantem agricolam oportet primum de fructibus percipere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Intellige quæ dico: dabit enim tibi Dominus in omnibus intellectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Memor esto Dominum Jesum Christum resurrexisse a mortuis ex semine David, secundum Evangelium meum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'in quo laboro usque ad vincula, quasi male operans: sed verbum Dei non est alligatum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Ideo omnia sustineo propter electos, ut et ipsi salutem consequantur, quæ est in Christo Jesu, cum gloria cælesti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Fidelis sermo: nam si commortui sumus, et convivemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'si sustinebimus, et conregnabimus: si negaverimus, et ille negabit nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'si non credimus, ille fidelis permanet, negare seipsum non potest.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Hæc commone, testificans coram Domino. Noli contendere verbis: ad nihil enim utile est, nisi ad subversionem audientium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Sollicite cura teipsum probabilem exhibere Deo, operarium inconfusibilem, recte tractantem verbum veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Profana autem et vaniloquia devita: multum enim proficiunt ad impietatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'et sermo eorum ut cancer serpit: ex quibus est Hymenæus et Philetus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'qui a veritate exciderunt, dicentes resurrectionem esse jam factam, et subverterunt quorumdam fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Sed firmum fundamentum Dei stat, habens signaculum hoc: cognovit Dominus qui sunt ejus, et discedat ab iniquitate omnis qui nominat nomen Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'In magna autem domo non solum sunt vasa aurea, et argentea, sed et lignea, et fictilia: et quædam quidem in honorem, quædam autem in contumeliam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Si quis ergo emundaverit se ab istis, erit vas in honorem sanctificatum, et utile Domino ad omne opus bonum paratum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Juvenilia autem desideria fuge, sectare vero justitiam, fidem, spem, caritatem, et pacem cum iis qui invocant Dominum de corde puro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Stultas autem et sine disciplina quæstiones devita: sciens quia generant lites.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Servum autem Domini non oportet litigare: sed mansuetum esse ad omnes, docibilem, patientem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'cum modestia corripientem eos qui resistunt veritati, nequando Deus det illis pœnitentiam ad cognoscendam veritatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'et resipiscant a diaboli laqueis, a quo captivi tenentur ad ipsius voluntatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Hoc autem scito, quod in novissimis diebus instabunt tempora periculosa:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'erunt homines seipsos amantes, cupidi, elati, superbi, blasphemi, parentibus non obedientes, ingrati, scelesti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'sine affectione, sine pace, criminatores, incontinentes, immites, sine benignitate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'proditores, protervi, tumidi, et voluptatum amatores magis quam Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'habentes speciem quidem pietatis, virtutem autem ejus abnegantes. Et hos devita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'ex his enim sunt qui penetrant domos, et captivas ducunt mulierculas oneratas peccatis, quæ ducuntur variis desideriis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'semper discentes, et numquam ad scientiam veritatis pervenientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Quemadmodum autem Jannes et Mambres restiterunt Moysi: ita et hi resistunt veritati, homines corrupti mente, reprobi circa fidem;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'sed ultra non proficient: insipientia enim eorum manifesta erit omnibus, sicut et illorum fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Tu autem assecutus es meam doctrinam, institutionem, propositum, fidem, longanimitatem, dilectionem, patientiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'persecutiones, passiones: qualia mihi facta sunt Antiochiæ, Iconii, et Lystris: quales persecutiones sustinui, et ex omnibus eripuit me Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Et omnes, qui pie volunt vivere in Christo Jesu, persecutionem patientur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Mali autem homines et seductores proficient in pejus, errantes, et in errorem mittentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Tu vero permane in iis quæ didicisti, et credita sunt tibi: sciens a quo didiceris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'et quia ab infantia sacras litteras nosti, quæ te possunt instruere ad salutem, per fidem quæ est in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Omnis Scriptura divinitus inspirata utilis est ad docendum, ad arguendum, ad corripiendum, et erudiendum in justitia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'ut perfectus sit homo Dei, ad omne opus bonum instructus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Testificor coram Deo, et Jesu Christo, qui judicaturus est vivos et mortuos, per adventum ipsius, et regnum ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'prædica verbum, insta opportune, importune: argue, obsecra, increpa in omni patientia, et doctrina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Erit enim tempus, cum sanam doctrinam non sustinebunt, sed ad sua desideria coacervabunt sibi magistros, prurientes auribus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'et a veritate quidem auditum avertent, ad fabulas autem convertentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Tu vero vigila, in omnibus labora, opus fac evangelistæ, ministerium tuum imple. Sobrius esto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Ego enim jam delibor, et tempus resolutionis meæ instat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Bonum certamen certavi, cursum consummavi, fidem servavi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'In reliquo reposita est mihi corona justitiæ, quam reddet mihi Dominus in illa die, justus judex: non solum autem mihi, sed et iis, qui diligunt adventum ejus. Festina ad me venire cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Demas enim me reliquit, diligens hoc sæculum, et abiit Thessalonicam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Crescens in Galatiam, Titus in Dalmatiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Lucas est mecum solus. Marcum assume, et adduc tecum: est enim mihi utilis in ministerium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Tychicum autem misi Ephesum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Penulam, quam reliqui Troade apud Carpum, veniens affer tecum, et libros, maxime autem membranas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Alexander ærarius multa mala mihi ostendit: reddet illi Dominus secundum opera ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'quem et tu devita: valde enim restitit verbis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'In prima mea defensione nemo mihi affuit, sed omnes me dereliquerunt: non illis imputetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Dominus autem mihi astitit, et confortavit me, ut per me prædicatio impleatur, et audiant omnes gentes: et liberatus sum de ore leonis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Liberavit me Dominus ab omni opere malo: et salvum faciet in regnum suum cæleste, cui gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Saluta Priscam, et Aquilam, et Onesiphori domum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Erastus remansit Corinthi. Trophimum autem reliqui infirmum Mileti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Festina ante hiemem venire. Salutant te Eubulus, et Pudens, et Linus, et Claudia, et fratres omnes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Dominus Jesus Christus cum spiritu tuo. Gratia vobiscum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Paulus servus Dei, Apostolus autem Jesu Christi secundum fidem electorum Dei, et agnitionem veritatis, quæ secundum pietatem est');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'in spem vitæ æternæ, quam promisit qui non mentitur, Deus, ante tempora sæcularia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'manifestavit autem temporibus suis verbum suum in prædicatione, quæ credita est mihi secundum præceptum Salvatoris nostri Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Tito dilecto filio secundum communem fidem, gratia, et pax a Deo Patre, et Christo Jesu Salvatore nostro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Hujus rei gratia reliqui te Cretæ, ut ea quæ desunt, corrigas, et constituas per civitates presbyteros, sicut et ego disposui tibi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'si quis sine crimine est, unius uxoris vir, filios habens fideles, non in accusatione luxuriæ, aut non subditos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Oportet enim episcopum sine crimine esse, sicut Dei dispensatorem: non superbum, non iracundum, non vinolentum, non percussorem, non turpis lucri cupidum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'sed hospitalem, benignum, sobrium, justum, sanctum, continentem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'amplectentem eum, qui secundum doctrinam est, fidelem sermonem: ut potens sit exhortari in doctrina sana, et eos qui contradicunt, arguere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Sunt enim multi etiam inobedientes, vaniloqui, et seductores: maxime qui de circumcisione sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'quos oportet redargui: qui universas domos subvertunt, docentes quæ non oportet, turpis lucri gratia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Dixit quidam ex illis, proprius ipsorum propheta: Cretenses semper mendaces, malæ bestiæ, ventres pigri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Testimonium hoc verum est. Quam ob causam increpa illos dure, ut sani sint in fide,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'non intendentes judaicis fabulis, et mandatis hominum, aversantium se a veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'Omnia munda mundis: coinquinatis autem et infidelibus, nihil est mundum, sed inquinatæ sunt eorum et mens et conscientia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'Confitentur se nosse Deum, factis autem negant: cum sint abominati, et incredibiles, et ad omne opus bonum reprobi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'Tu autem loquere quæ decent sanam doctrinam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'senes ut sobrii sint, pudici, prudentes, sani in fide, in dilectione, in patientia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'anus similiter in habitu sancto, non criminatrices, non multo vino servientes, bene docentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'ut prudentiam doceant adolescentulas, ut viros suos ament, filios suos diligant,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'prudentes, castas, sobrias, domus curam habentes, benignas, subditas viris suis, ut non blasphemetur verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Juvenes similiter hortare ut sobrii sint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'In omnibus teipsum præbe exemplum bonorum operum, in doctrina, in integritate, in gravitate,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'verbum sanum, irreprehensibile: ut is qui ex adverso est, vereatur, nihil habens malum dicere de nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'Servos dominis suis subditos esse, in omnibus placentes, non contradicentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'non fraudantes, sed in omnibus fidem bonam ostendentes: ut doctrinam Salvatoris nostri Dei ornent in omnibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Apparuit enim gratia Dei Salvatoris nostri omnibus hominibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'erudiens nos, ut abnegantes impietatem, et sæcularia desideria, sobrie, et juste, et pie vivamus in hoc sæculo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'exspectantes beatam spem, et adventum gloriæ magni Dei, et Salvatoris nostri Jesu Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'qui dedit semetipsum pro nobis, ut nos redimeret ab omni iniquitate, et mundaret sibi populum acceptabilem, sectatorem bonorum operum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'Hæc loquere, et exhortare, et argue cum omni imperio. Nemo te contemnat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Admone illos principibus, et potestatibus subditos esse, dicto obedire, ad omne opus bonum paratos esse:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'neminem blasphemare, non litigiosos esse, sed modestos, omnem ostendentes mansuetudinem ad omnes homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Eramus enim aliquando et nos insipientes, increduli, errantes, servientes desideriis, et voluptatibus variis, in malitia et invidia agentes, odibiles, odientes invicem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Cum autem benignitas et humanitas apparuit Salvatoris nostri Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'non ex operibus justitiæ, quæ fecimus nos, sed secundum suam misericordiam salvos nos fecit per lavacrum regenerationis et renovationis Spiritus Sancti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'quem effudit in nos abunde per Jesum Christum Salvatorem nostrum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'ut justificati gratia ipsius, hæredes simus secundum spem vitæ æternæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Fidelis sermo est: et de his volo te confirmare: ut curent bonis operibus præesse qui credunt Deo. Hæc sunt bona, et utilia hominibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'Stultas autem quæstiones, et genealogias, et contentiones, et pugnas legis devita: sunt enim inutiles, et vanæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Hæreticum hominem post unam et secundam correptionem devita:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'sciens quia subversus est, qui ejusmodi est, et delinquit, cum sit proprio judicio condemnatus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Cum misero ad te Artemam, aut Tychicum, festina ad me venire Nicopolim: ibi enim statui hiemare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'Zenam legisperitum et Apollo sollicite præmitte, ut nihil illis desit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Discant autem et nostri bonis operibus præesse ad usus necessarios: ut non sint infructuosi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'Salutant te qui mecum sunt omnes: saluta eos qui nos amant in fide. Gratia Dei cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Paulus vinctus Christi Jesu, et Timotheus frater, Philemoni dilecto, et adjutori nostro,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'et Appiæ sorori carissimæ, et Archippo commilitoni nostro, et ecclesiæ, quæ in domo tua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Gratia vobis, et pax a Deo Patre nostro, et Domino Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Gratias ago Deo meo, semper memoriam tui faciens in orationibus meis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'audiens caritatem tuam, et fidem, quam habes in Domino Jesu, et in omnes sanctos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'ut communicatio fidei tuæ evidens fiat in agnitione omnis operis boni, quod est in vobis in Christo Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Gaudium enim magnum habui, et consolationem in caritate tua: quia viscera sanctorum requieverunt per te, frater.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Propter quod multam fiduciam habens in Christo Jesu imperandi tibi quod ad rem pertinet:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'propter caritatem magis obsecro, cum sis talis, ut Paulus senex, nunc autem et vinctus Jesu Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'obsecro te pro meo filio, quem genui in vinculis, Onesimo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'qui tibi aliquando inutilis fuit, nunc autem et mihi et tibi utilis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'quem remisi tibi. Tu autem illum, ut mea viscera, suscipe:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'quem ego volueram mecum detinere, ut pro te mihi ministraret in vinculis Evangelii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'sine consilio autem tuo nihil volui facere, uti ne velut ex necessitate bonum tuum esset, sed voluntarium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Forsitan enim ideo discessit ad horam a te, ut æternum illum reciperes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'jam non ut servum, sed pro servo carissimum fratrem, maxime mihi: quanto autem magis tibi et in carne, et in Domino?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Si ergo habes me socium, suscipe illum sicut me:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'si autem aliquid nocuit tibi, aut debet, hoc mihi imputa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Ego Paulus scripsi mea manu: ego reddam, ut non dicam tibi, quod et teipsum mihi debes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'ita, frater. Ego te fruar in Domino: refice viscera mea in Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Confidens in obedientia tua scripsi tibi: sciens quoniam et super id, quod dico, facies.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'Simul autem et para mihi hospitium: nam spero per orationes vestras donari me vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Salutat te Epaphras concaptivus meus in Christo Jesu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'Marcus, Aristarchus, Demas, et Lucas, adjutores mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 25, 'Gratia Domini nostri Jesu Christi cum spiritu vestro. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Multifariam, multisque modis olim Deus loquens patribus in prophetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'novissime, diebus istis locutus est nobis in Filio, quem constituit hæredem universorum, per quem fecit et sæcula:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'qui cum sit splendor gloriæ, et figura substantiæ ejus, portansque omnia verbo virtutis suæ, purgationem peccatorum faciens, sedet ad dexteram majestatis in excelsis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'tanto melior angelis effectus, quanto differentius præ illis nomen hæreditavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Cui enim dixit aliquando angelorum: Filius meus es tu, ego hodie genui te? Et rursum: Ego ero illi in patrem, et ipse erit mihi in filium?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Et cum iterum introducit primogenitum in orbem terræ, dicit: Et adorent eum omnes angeli Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Et ad angelos quidem dicit: Qui facit angelos suos spiritus, et ministros suos flammam ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Ad Filium autem: Thronus tuus Deus in sæculum sæculi: virga æquitatis, virga regni tui.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Dilexisti justitiam, et odisti iniquitatem: propterea unxit te Deus, Deus tuus, oleo exultationis præ participibus tuis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Et: Tu in principio, Domine, terram fundasti: et opera manuum tuarum sunt cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ipsi peribunt, tu autem permanebis, et omnes ut vestimentum veterascent:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'et velut amictum mutabis eos, et mutabuntur: tu autem idem ipse es, et anni tui non deficient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Ad quem autem angelorum dixit aliquando: Sede a dextris meis, quoadusque ponam inimicos tuos scabellum pedum tuorum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Nonne omnes sunt administratorii spiritus, in ministerium missi propter eos, qui hæreditatem capient salutis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Propterea abundantius oportet observare nos ea quæ audivimus, ne forte pereffluamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Si enim qui per angelos dictus est sermo, factus est firmus, et omnis prævaricatio, et inobedientia accepit justam mercedis retributionem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'quomodo nos effugiemus si tantam neglexerimus salutem? quæ cum initium accepisset enarrari per Dominum ab eis, qui audierunt, in nos confirmata est,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'contestante Deo signis et portentis, et variis virtutibus, et Spiritus Sancti distributionibus secundum suam voluntatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'Non enim angelis subjecit Deus orbem terræ futurum, de quo loquimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Testatus est autem in quodam loco quis, dicens: Quid est homo quod memor es ejus, aut filius hominis quoniam visitas eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'Minuisti eum paulo minus ab angelis: gloria et honore coronasti eum: et constituisti eum super opera manuum tuarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'Omnia subjecisti sub pedibus ejus. In eo enim quod omnia ei subjecit, nihil dimisit non subjectum ei. Nunc autem necdum videmus omnia subjecta ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'Eum autem, qui modico quam angeli minoratus est, videmus Jesum propter passionem mortis, gloria et honore coronatum: ut, gratia Dei, pro omnibus gustaret mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Decebat enim eum, propter quem omnia, et per quem omnia, qui multos filios in gloriam adduxerat, auctorem salutis eorum per passionem consummare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Qui enim sanctificat, et qui sanctificantur, ex uno omnes. Propter quam causam non confunditur fratres eos vocare, dicens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'Nuntiabo nomen tuum fratribus meis: in medio ecclesiæ laudabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'Et iterum: Ego ero fidens in eum. Et iterum: Ecce ego, et pueri mei, quos dedit mihi Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Quia ergo pueri communicaverunt carni, et sanguini, et ipse similiter participavit eisdem: ut per mortem destrueret eum qui habebat mortis imperium, id est, diabolum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'et liberaret eos qui timore mortis per totam vitam obnoxii erant servituti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'Nusquam enim angelos apprehendit, sed semen Abrahæ apprehendit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Unde debuit per omnia fratribus similari, ut misericors fieret, et fidelis pontifex ad Deum, ut repropitiaret delicta populi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'In eo enim, in quo passus est ipse et tentatus, potens est et eis, qui tentantur, auxiliari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Unde, fratres sancti, vocationis cælestis participes, considerate Apostolum, et pontificem confessionis nostræ Jesum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'qui fidelis est ei, qui fecit illum, sicut et Moyses in omni domo ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Amplioris enim gloriæ iste præ Moyse dignus est habitus, quanto ampliorem honorem habet domus, qui fabricavit illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Omnis namque domus fabricatur ab aliquo: qui autem omnia creavit, Deus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Et Moyses quidem fidelis erat in tota domo ejus tamquam famulus, in testimonium eorum, quæ dicenda erant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'Christus vero tamquam filius in domo sua: quæ domus sumus nos, si fiduciam, et gloriam spei usque ad finem, firmam retineamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'Quapropter sicut dicit Spiritus Sanctus: Hodie si vocem ejus audieritis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'nolite obdurare corda vestra, sicut in exacerbatione secundum diem tentationis in deserto,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'ubi tentaverunt me patres vestri: probaverunt, et viderunt opera mea');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'quadraginta annis: propter quod infensus fui generationi huic, et dixi: Semper errant corde. Ipsi autem non cognoverunt vias meas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'sicut juravi in ira mea: Si introibunt in requiem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Videte fratres, ne forte sit in aliquo vestrum cor malum incredulitatis, discedendi a Deo vivo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'sed adhortamini vosmetipsos per singulos dies, donec hodie cognominatur, ut non obduretur quis ex vobis fallacia peccati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Participes enim Christi effecti sumus, si tamen initium substantiæ ejus usque ad finem firmum retineamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'Dum dicitur: Hodie si vocem ejus audieritis, nolite obdurare corda vestra, quemadmodum in illa exacerbatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Quidam enim audientes exacerbaverunt: sed non universi qui profecti sunt ex \'gypto per Moysen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Quibus autem infensus est quadraginta annis? nonne illis qui peccaverunt, quorum cadavera prostrata sunt in deserto?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Quibus autem juravit non introire in requiem ipsius, nisi illis qui increduli fuerunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'Et videmus, quia non potuerunt introire propter incredulitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Timeamus ergo ne forte relicta pollicitatione introëundi in requiem ejus, existimetur aliquis ex vobis deesse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'Etenim et nobis nuntiatum est, quemadmodum et illis: sed non profuit illis sermo auditus, non admistus fidei ex iis quæ audierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Ingrediemur enim in requiem, qui credidimus: quemadmodum dixit: Sicut juravi in ira mea: Si introibunt in requiem meam: et quidem operibus ab institutione mundi perfectis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'Dixit enim in quodam loco de die septima sic: Et requievit Deus die septima ab omnibus operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'Et in isto rursum: Si introibunt in requiem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Quoniam ergo superest introire quosdam in illam, et ii, quibus prioribus annuntiatum est, non introierunt propter incredulitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'iterum terminat diem quemdam, Hodie, in David dicendo, post tantum temporis, sicut supra dictum est: Hodie si vocem ejus audieritis, nolite obdurare corda vestra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Nam si eis Jesus requiem præstitisset, numquam de alia loqueretur, posthac, die.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Itaque relinquitur sabbatismus populo Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'Qui enim ingressus est in requiem ejus, etiam ipse requievit ab operibus suis, sicut a suis Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Festinemus ergo ingredi in illam requiem: ut ne in idipsum quis incidat incredulitatis exemplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Vivus est enim sermo Dei, et efficax et penetrabilior omni gladio ancipiti: et pertingens usque ad divisionem animæ ac spiritus: compagum quoque ac medullarum, et discretor cogitationum et intentionum cordis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'Et non est ulla creatura invisibilis in conspectu ejus: omnia autem nuda et aperta sunt oculis ejus, ad quem nobis sermo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Habentes ergo pontificem magnum qui penetravit cælos, Jesum Filium Dei, teneamus confessionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Non enim habemus pontificem qui non possit compati infirmitatibus nostris: tentatum autem per omnia pro similitudine absque peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Adeamus ergo cum fiducia ad thronum gratiæ: ut misericordiam consequamur, et gratiam inveniamus in auxilio opportuno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, 'Omnis namque pontifex ex hominibus assumptus, pro hominibus constituitur in iis quæ sunt ad Deum, ut offerat dona, et sacrificia pro peccatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'qui condolere possit iis qui ignorant et errant: quoniam et ipse circumdatus est infirmitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'et propterea debet, quemadmodum pro populo, ita etiam et pro semetipso offerre pro peccatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'Nec quisquam sumit sibi honorem, sed qui vocatur a Deo, tamquam Aaron.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Sic et Christus non semetipsum clarificavit ut pontifex fieret: sed qui locutus est ad eum: Filius meus es tu, ego hodie genui te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, 'Quemadmodum et in alio loco dicit: Tu es sacerdos in æternum, secundum ordinem Melchisedech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'Qui in diebus carnis suæ preces, supplicationesque ad eum qui possit illum salvum facere a morte cum clamore valido, et lacrimis offerens, exauditus est pro sua reverentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'Et quidem cum esset Filius Dei, didicit ex iis, quæ passus est, obedientiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'et consummatus, factus est omnibus obtemperantibus sibi, causa salutis æternæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'appellatus a Deo pontifex juxta ordinem Melchisedech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, 'De quo nobis grandis sermo, et ininterpretabilis ad dicendum: quoniam imbecilles facti estis ad audiendum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Etenim cum deberetis magistri esse propter tempus, rursum indigetis ut vos doceamini quæ sint elementa exordii sermonum Dei: et facti estis quibus lacte opus sit, non solido cibo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'Omnis enim, qui lactis est particeps, expers est sermonis justitiæ: parvulus enim est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'Perfectorum autem est solidus cibus: eorum, qui pro consuetudine exercitatos habent sensus ad discretionem boni ac mali.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, 'Quapropter intermittentes inchoationis Christi sermonem, ad perfectiora feramur, non rursum jacientes fundamentum pœnitentiæ ab operibus mortuis, et fidei ad Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'baptismatum doctrinæ, impositionis quoque manuum, ac resurrectionis mortuorum, et judicii æterni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'Et hoc faciemus, si quidem permiserit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Impossibile est enim eos qui semel sunt illuminati, gustaverunt etiam donum cæleste, et participes facti sunt Spiritus Sancti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'gustaverunt nihilominus bonum Dei verbum, virtutesque sæculi venturi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'et prolapsi sunt; rursus renovari ad pœnitentiam, rursum crucifigentes sibimetipsis Filium Dei, et ostentui habentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'Terra enim sæpe venientem super se bibens imbrem, et generans herbam opportunam illis, a quibus colitur, accipit benedictionem a Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'proferens autem spinas ac tribulos, reproba est, et maledicto proxima: cujus consummatio in combustionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'Confidimus autem de vobis dilectissimi meliora, et viciniora saluti: tametsi ita loquimur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'Non enim injustus Deus, ut obliviscatur operis vestri, et dilectionis, quam ostendistis in nomine ipsius, qui ministrastis sanctis, et ministratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, 'Cupimus autem unumquemque vestrum eamdem ostentare sollicitudinem ad expletionem spei usque in finem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'ut non segnes efficiamini, verum imitatores eorum, qui fide, et patientia hæreditabunt promissiones.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Abrahæ namque promittens Deus, quoniam neminem habuit, per quem juraret, majorem, juravit per semetipsum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, 'dicens: Nisi benedicens benedicam te, et multiplicans multiplicabo te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'Et sic longanimiter ferens, adeptus est repromissionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Homines enim per majorem sui jurant: et omnis controversiæ eorum finis, ad confirmationem, est juramentum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, 'In quo abundantius volens Deus ostendere pollicitationis hæredibus, immobilitatem consilii sui, interposuit jusjurandum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, 'ut per duas res immobiles, quibus impossibile est mentiri Deum, fortissimum solatium habeamus, qui confugimus ad tenendam propositam spem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 19, 'quam sicut anchoram habemus animæ tutam ac firmam, et incedentem usque ad interiora velaminis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 20, 'ubi præcursor pro nobis introivit Jesus, secundum ordinem Melchisedech pontifex factus in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 1, 'Hic enim Melchisedech, rex Salem, sacerdos Dei summi, qui obviavit Abrahæ regresso a cæde regum, et benedixit ei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 2, 'cui et decimas omnium divisit Abraham: primum quidem qui interpretatur rex justitiæ: deinde autem et rex Salem, quod est, rex pacis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 3, 'sine patre, sine matre, sine genealogia, neque initium dierum, neque finem vitæ habens, assimilatus autem Filio Dei, manet sacerdos in perpetuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 4, 'Intuemini autem quantus sit hic, cui et decimas dedit de præcipuis Abraham patriarcha.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 5, 'Et quidem de filiis Levi sacerdotium accipientes, mandatum habent decimas sumere a populo secundum legem, id est, a fratribus suis: quamquam et ipsi exierint de lumbis Abrahæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 6, 'Cujus autem generatio non annumeratur in eis, decimas sumpsit ab Abraham, et hunc, qui habebat repromissiones, benedixit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 7, 'Sine ulla autem contradictione, quod minus est, a meliore benedicitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 8, 'Et hic quidem, decimas morientes homines accipiunt: ibi autem contestatur, quia vivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 9, 'Et (ut ita dictum sit) per Abraham, et Levi, qui decimas accepit, decimatus est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 10, 'adhuc enim in lumbis patris erat, quando obviavit ei Melchisedech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 11, 'Si ergo consummatio per sacerdotium Leviticum erat (populus enim sub ipso legem accepit) quid adhuc necessarium fuit secundum ordinem Melchisedech, alium surgere sacerdotem, et non secundum ordinem Aaron dici?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 12, 'Translato enim sacerdotio, necesse est ut et legis translatio fiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 13, 'In quo enim hæc dicuntur, de alia tribu est, de qua nullus altari præsto fuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 14, 'Manifestum est enim quod ex Juda ortus sit Dominus noster: in qua tribu nihil de sacerdotibus Moyses locutus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 15, 'Et amplius adhuc manifestum est: si secundum similitudinem Melchisedech exsurgat alius sacerdos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 16, 'qui non secundum legem mandati carnalis factus est, sed secundum virtutem vitæ insolubilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 17, 'Contestatur enim: Quoniam tu es sacerdos in æternum, secundum ordinem Melchisedech.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 18, 'Reprobatio quidem fit præcedentis mandati, propter infirmitatem ejus, et inutilitatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 19, 'nihil enim ad perfectum adduxit lex: introductio vero melioris spei, per quam proximamus ad Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 20, 'Et quantum est non sine jurejurando (alii quidem sine jurejurando sacerdotes facti sunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 21, 'hic autem cum jurejurando per eum, qui dixit ad illum: Juravit Dominus, et non pœnitebit eum: tu es sacerdos in æternum):');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 22, 'in tantum melioris testamenti sponsor factus est Jesus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 23, 'Et alii quidem plures facti sunt sacerdotes, idcirco quod morte prohiberentur permanere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 24, 'hic autem eo quod maneat in æternum, sempiternum habet sacerdotium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 25, 'Unde et salvare in perpetuum potest accedentes per semetipsum ad Deum: semper vivens ad interpellandum pro nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 26, 'Talis enim decebat ut nobis esset pontifex, sanctus, innocens, impollutus, segregatus a peccatoribus, et excelsior cælis factus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 27, 'qui non habet necessitatem quotidie, quemadmodum sacerdotes, prius pro suis delictis hostias offerre, deinde pro populi: hoc enim fecit semel, seipsum offerendo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 7, 28, 'Lex enim homines constituit sacerdotes infirmitatem habentes: sermo autem jurisjurandi, qui post legem est, Filium in æternum perfectum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 1, 'Capitulum autem super ea quæ dicuntur: Talem habemus pontificem, qui consedit in dextera sedis magnitudinis in cælis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 2, 'sanctorum minister, et tabernaculi veri, quod fixit Dominus, et non homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 3, 'Omnis enim pontifex ad offerendum munera, et hostias constituitur: unde necesse est et hunc habere aliquid, quod offerat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 4, 'Si ergo esset super terram, nec esset sacerdos: cum essent qui offerent secundum legem munera,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 5, 'qui exemplari, et umbræ deserviunt cælestium. Sicut responsum est Moysi, cum consummaret tabernaculum: Vide (inquit) omnia facito secundum exemplar, quod tibi ostensum est in monte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 6, 'Nunc autem melius sortitus est ministerium, quanto et melioris testamenti mediator est, quod in melioribus repromissionibus sancitum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 7, 'Nam si illud prius culpa vacasset, non utique secundi locus inquireretur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 8, 'Vituperans enim eos dicit: Ecce dies venient, dicit Dominus: et consummabo super domum Israël, et super domum Juda, testamentum novum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 9, 'non secundum testamentum quod feci patribus eorum in die qua apprehendi manum eorum ut educerem illos de terra \'gypti: quoniam ipsi non permanserunt in testamento meo: et ego neglexi eos, dicit Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 10, 'Quia hoc est testamentum quod disponam domui Israël post dies illos, dicit Dominus: dando leges meas in mentem eorum, et in corde eorum superscribam eas: et ero eis in Deum, et ipsi erunt mihi in populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 11, 'et non docebit unusquisque proximum suum, et unusquisque fratrem suum, dicens: Cognosce Dominum: quoniam omnes scient me a minore usque ad majorem eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 12, 'quia propitius ero iniquitatibus eorum, et peccatorum eorum jam non memorabor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 8, 13, 'Dicendo autem novum: veteravit prius. Quod autem antiquatur, et senescit, prope interitum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 1, 'Habuit quidem et prius justificationes culturæ, et Sanctum sæculare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 2, 'Tabernaculum enim factum est primum, in quo erant candelabra, et mensa, et propositio panum, quæ dicitur Sancta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 3, 'Post velamentum autem secundum, tabernaculum, quod dicitur Sancta sanctorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 4, 'aureum habens thuribulum, et arcam testamenti circumtectam ex omni parte auro, in qua urna aurea habens manna, et virga Aaron, quæ fronduerat, et tabulæ testamenti,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 5, 'superque eam erant cherubim gloriæ obumbrantia propitiatorium: de quibus non est modo dicendum per singula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 6, 'His vero ita compositis, in priori quidem tabernaculo semper introibant sacerdotes, sacrificiorum officia consummantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 7, 'in secundo autem semel in anno solus pontifex non sine sanguine, quem offert pro sua et populi ignorantia:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 8, 'hoc significante Spiritu Sancto, nondum propalatam esse sanctorum viam, adhuc priore tabernaculo habente statum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 9, 'quæ parabola est temporis instantis: juxta quam munera, et hostiæ offeruntur, quæ non possunt juxta conscientiam perfectum facere servientem, solummodo in cibis, et in potibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 10, 'et variis baptismatibus, et justitiis carnis usque ad tempus correctionis impositis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 11, 'Christus autem assistens pontifex futurorum bonorum, per amplius et perfectius tabernaculum, non manufactum, id est, non hujus creationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 12, 'neque per sanguinem hircorum aut vitulorum, sed per proprium sanguinem introivit semel in Sancta, æterna redemptione inventa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 13, 'Si enim sanguis hircorum et taurorum, et cinis vitulæ aspersus inquinatos sanctificat ad emundationem carnis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 14, 'quanto magis sanguis Christi, qui per Spiritum Sanctum semetipsum obtulit immaculatum Deo, emundabit conscientiam nostram ab operibus mortuis, ad serviendum Deo viventi?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 15, 'Et ideo novi testamenti mediator est: ut morte intercedente, in redemptionem earum prævaricationum, quæ erant sub priori testamento, repromissionem accipiant qui vocati sunt æternæ hæreditatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 16, 'Ubi enim testamentum est, mors necesse est intercedat testatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 17, 'Testamentum enim in mortuis confirmatum est: alioquin nondum valet, dum vivit qui testatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 18, 'Unde nec primum quidem sine sanguine dedicatum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 19, 'Lecto enim omni mandato legis a Moyse universo populo, accipiens sanguinem vitulorum et hircorum cum aqua, et lana coccinea, et hyssopo, ipsum quoque librum, et omnem populum aspersit,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 20, 'dicens: Hic sanguis testamenti, quod mandavit ad vos Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 21, 'Etiam tabernaculum et omnia vasa ministerii sanguine similiter aspersit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 22, 'Et omnia pene in sanguine secundum legem mundantur: et sine sanguinis effusione non fit remissio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 23, 'Necesse est ergo exemplaria quidem cælestium his mundari: ipsa autem cælestia melioribus hostiis quam istis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 24, 'Non enim in manufacta Sancta Jesus introivit exemplaria verorum: sed in ipsum cælum, ut appareat nunc vultui Dei pro nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 25, 'neque ut sæpe offerat semetipsum, quemadmodum pontifex intrat in Sancta per singulos annos in sanguine alieno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 26, 'alioquin oportebat eum frequenter pati ab origine mundi: nunc autem semel in consummatione sæculorum, ad destitutionem peccati, per hostiam suam apparuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 27, 'Et quemadmodum statutum est hominibus semel mori, post hoc autem judicium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 9, 28, 'sic et Christus semel oblatus est ad multorum exhaurienda peccata: secundo sine peccato apparebit exspectantibus se, in salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 1, 'Umbram enim habens lex futurorum bonorum, non ipsam imaginem rerum: per singulos annos, eisdem ipsis hostiis quas offerunt indesinenter, numquam potest accedentes perfectos facere:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 2, 'alioquin cessassent offerri: ideo quod nullam haberent ultra conscientiam peccati, cultores semel mundati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 3, 'sed in ipsis commemoratio peccatorum per singulos annos fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 4, 'Impossibile enim est sanguine taurorum et hircorum auferri peccata.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 5, 'Ideo ingrediens mundum dicit: Hostiam et oblationem noluisti: corpus autem aptasti mihi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 6, 'holocautomata pro peccato non tibi placuerunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 7, 'Tunc dixi: Ecce venio: in capite libri scriptum est de me: Ut faciam, Deus, voluntatem tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 8, 'Superius dicens: Quia hostias, et oblationes, et holocautomata pro peccato noluisti, nec placita sunt tibi, quæ secundum legem offeruntur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 9, 'tunc dixi: Ecce venio, ut faciam, Deus, voluntatem tuam: aufert primum, ut sequens statuat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 10, 'In qua voluntate sanctificati sumus per oblationem corporis Jesu Christi semel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 11, 'Et omnis quidem sacerdos præsto est quotidie ministrans, et easdem sæpe offerens hostias, quæ numquam possunt auferre peccata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 12, 'hic autem unam pro peccatis offerens hostiam, in sempiternum sedet in dextera Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 13, 'de cetero exspectans donec ponantur inimici ejus scabellum pedum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 14, 'Una enim oblatione, consummavit in sempiternum sanctificatos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 15, 'Contestatur autem nos et Spiritus Sanctus. Postquam enim dixit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 16, 'Hoc autem testamentum, quod testabor ad illos post dies illos, dicit Dominus, dando leges meas in cordibus eorum, et in mentibus eorum superscribam eas:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 17, 'et peccatorum, et iniquitatum eorum jam non recordabor amplius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 18, 'Ubi autem horum remissio: jam non est oblatio pro peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 19, 'Habentes itaque, fratres, fiduciam in introitu sanctorum in sanguine Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 20, 'quam initiavit nobis viam novam, et viventem per velamen, id est, carnem suam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 21, 'et sacerdotem magnum super domum Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 22, 'accedamus cum vero corde in plenitudine fidei, aspersi corda a conscientia mala, et abluti corpus aqua munda,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 23, 'teneamus spei nostræ confessionem indeclinabilem (fidelis enim est qui repromisit),');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 24, 'et consideremus invicem in provocationem caritatis, et bonorum operum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 25, 'non deserentes collectionem nostram, sicut consuetudinis est quibusdam, sed consolantes, et tanto magis quanto videritis appropinquantem diem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 26, 'Voluntarie enim peccantibus nobis post acceptam notitiam veritatis, jam non relinquitur pro peccatis hostia,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 27, 'terribilis autem quædam exspectatio judicii, et ignis æmulatio, quæ consumptura est adversarios.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 28, 'Irritam quis faciens legem Moysi, sine ulla miseratione duobus vel tribus testibus moritur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 29, 'quanto magis putatis deteriora mereri supplicia qui Filium Dei conculcaverit, et sanguinem testamenti pollutum duxerit, in quo sanctificatus est, et spiritui gratiæ contumeliam fecerit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 30, 'Scimus enim qui dixit: Mihi vindicta, et ego retribuam. Et iterum: Quia judicabit Dominus populum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 31, 'Horrendum est incidere in manus Dei viventis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 32, 'Rememoramini autem pristinos dies, in quibus illuminati, magnum certamen sustinuistis passionum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 33, 'et in altero quidem opprobriis et tribulationibus spectaculum facti: in altero autem socii taliter conversantium effecti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 34, 'Nam et vinctis compassi estis, et rapinam bonorum vestrorum cum gaudio suscepistis, cognoscentes vos habere meliorem et manentem substantiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 35, 'Nolite itaque amittere confidentiam vestram, quæ magnam habet remunerationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 36, 'Patientia enim vobis necessaria est: ut voluntatem Dei facientes, reportetis promissionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 37, 'Adhuc enim modicum aliquantulum, qui venturus est, veniet, et non tardabit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 38, 'Justus autem meus ex fide vivit: quod si subtraxerit se, non placebit animæ meæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 10, 39, 'Nos autem non sumus subtractionis filii in perditionem, sed fidei in acquisitionem animæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 1, 'Est autem fides sperandarum substantia rerum, argumentum non apparentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 2, 'In hac enim testimonium consecuti sunt senes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 3, 'Fide intelligimus aptata esse sæcula verbo Dei: ut ex invisibilibus visibilia fierent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 4, 'Fide plurimam hostiam Abel, quam Cain, obtulit Deo, per quam testimonium consecutus est esse justus, testimonium perhibente muneribus ejus Deo, et per illam defunctus adhuc loquitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 5, 'Fide Henoch translatus est ne videret mortem, et non inveniebatur, quia transtulit illum Deus: ante translationem enim testimonium habuit placuisse Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 6, 'Sine fide autem impossibile est placere Deo. Credere enim oportet accedentem ad Deum quia est, et inquirentibus se remunerator sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 7, 'Fide Noë responso accepto de iis quæ adhuc non videbantur, metuens aptavit arcam in salutem domus suæ, per quam damnavit mundum: et justitiæ, quæ per fidem est, hæres est institutus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 8, 'Fide qui vocatur Abraham obedivit in locum exire, quem accepturus erat in hæreditatem: et exiit, nesciens quo iret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 9, 'Fide demoratus est in terra repromissionis, tamquam in aliena, in casulis habitando cum Isaac et Jacob cohæredibus repromissionis ejusdem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 10, 'Exspectabat enim fundamenta habentem civitatem: cujus artifex et conditor Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 11, 'Fide et ipsa Sara sterilis virtutem in conceptionem seminis accepit, etiam præter tempus ætatis: quoniam fidelem credidit esse eum qui repromiserat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 12, 'Propter quod et ab uno orti sunt (et hoc emortuo) tamquam sidera cæli in multitudinem, et sicut arena, quæ est ad oram maris, innumerabilis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 13, 'Juxta fidem defuncti sunt omnes isti, non acceptis repromissionibus, sed a longe eas aspicientes, et salutantes, et confitentes quia peregrini et hospites sunt super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 14, 'Qui enim hæc dicunt, significant se patriam inquirere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 15, 'Et si quidem ipsius meminissent de qua exierunt, habebant utique tempus revertendi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 16, 'nunc autem meliorem appetunt, id est, cælestem. Ideo non confunditur Deus vocari Deus eorum: paravit enim illis civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 17, 'Fide obtulit Abraham Isaac, cum tentaretur, et unigenitum offerebat, qui susceperat repromissiones:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 18, 'ad quem dictum est: Quia in Isaac vocabitur tibi semen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 19, 'arbitrans quia et a mortuis suscitare potens est Deus: unde eum et in parabolam accepit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 20, 'Fide et de futuris benedixit Isaac Jacob et Esau.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 21, 'Fide Jacob, moriens, singulos filiorum Joseph benedixit: et adoravit fastigium virgæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 22, 'Fide Joseph, moriens, de profectione filiorum Israël memoratus est, et de ossibus suis mandavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 23, 'Fide Moyses, natus, occultatus est mensibus tribus a parentibus suis, eo quod vidissent elegantem infantem, et non timuerunt regis edictum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 24, 'Fide Moyses grandis factus negavit se esse filium filiæ Pharaonis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 25, 'magis eligens affligi cum populo Dei, quam temporalis peccati habere jucunditatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 26, 'majores divitias æstimans thesauro \'gyptiorum, improperium Christi: aspiciebat enim in remunerationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 27, 'Fide reliquit \'gyptum, non veritus animositatem regis: invisibilem enim tamquam videns sustinuit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 28, 'Fide celebravit Pascha, et sanguinis effusionem: ne qui vastabat primitiva, tangeret eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 29, 'Fide transierunt mare Rubrum tamquam per aridam terram: quod experti \'gyptii, devorati sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 30, 'Fide muri Jericho corruerunt, circuitu dierum septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 31, 'Fide Rahab meretrix non periit cum incredulis, excipiens exploratores cum pace.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 32, 'Et quid adhuc dicam? deficiet enim me tempus enarrantem de Gedeon, Barac, Samson, Jephte, David, Samuel, et prophetis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 33, 'qui per fidem vicerunt regna, operati sunt justitiam, adepti sunt repromissiones, obturaverunt ora leonum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 34, 'extinxerunt impetum ignis, effugerunt aciem gladii, convaluerunt de infirmitate, fortes facti sunt in bello, castra verterunt exterorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 35, 'acceperunt mulieres de resurrectione mortuos suos: alii autem distenti sunt non suscipientes redemptionem ut meliorem invenirent resurrectionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 36, 'Alii vero ludibria, et verbera experti, insuper et vincula, et carceres:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 37, 'lapidati sunt, secti sunt, tentati sunt, in occisione gladii mortui sunt, circuierunt in melotis, in pellibus caprinis, egentes, angustiati, afflicti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 38, 'quibus dignus non erat mundus: in solitudinibus errantes, in montibus, in speluncis, et in cavernis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 39, 'Et hi omnes testimonio fidei probati, non acceperunt repromissionem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 11, 40, 'Deo pro nobis melius aliquid providente, ut non sine nobis consummarentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 1, 'Ideoque et nos tantam habentes impositam nubem testium, deponentes omne pondus, et circumstans nos peccatum, per patientiam curramus ad propositum nobis certamen:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 2, 'aspicientes in auctorem fidei, et consummatorem Jesum, qui proposito sibi gaudio sustinuit crucem, confusione contempta, atque in dextera sedis Dei sedet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 3, 'Recogitate enim eum qui talem sustinuit a peccatoribus adversum semetipsum contradictionem: ut ne fatigemini, animis vestris deficientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 4, 'Nondum enim usque ad sanguinem restitistis, adversus peccatum repugnantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 5, 'et obliti estis consolationis, quæ vobis tamquam filiis loquitur, dicens: Fili mi, noli negligere disciplinam Domini: neque fatigeris dum ab eo argueris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 6, 'Quem enim diligit Dominus, castigat: flagellat autem omnem filium, quem recipit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 7, 'In disciplina perseverate. Tamquam filiis vobis offert se Deus: quis enim filius, quem non corripit pater?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 8, 'quod si extra disciplinam estis, cujus participes facti sunt omnes: ergo adulteri, et non filii estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 9, 'Deinde patres quidem carnis nostræ, eruditores habuimus, et reverebamur eos, non multo magis obtemperabimus Patri spirituum, et vivemus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 10, 'Et illi quidem in tempore paucorum dierum, secundum voluntatem suam erudiebant nos: hic autem ad id quod utile est in recipiendo sanctificationem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 11, 'Omnis autem disciplina in præsenti quidem videtur non esse gaudii, sed mœroris: postea autem fructum pacatissimum exercitatis per eam, reddet justitiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 12, 'Propter quod remissas manus, et soluta genua erigite,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 13, 'et gressus rectos facite pedibus vestris: ut non claudicans quis erret, magis autem sanetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 14, 'Pacem sequimini cum omnibus, et sanctimoniam, sine qua nemo videbit Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 15, 'contemplantes nequis desit gratiæ Dei: ne qua radix amaritudinis sursum germinans impediat, et per illam inquinentur multi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 16, 'Ne quis fornicator, aut profanus ut Esau: qui propter unam escam vendidit primitiva sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 17, 'scitote enim quoniam et postea cupiens hæreditare benedictionem, reprobatus est: non enim invenit pœnitentiæ locum, quamquam cum lacrimis inquisisset eam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 18, 'Non enim accessistis ad tractabilem montem, et accensibilem ignem, et turbinem, et caliginem, et procellam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 19, 'et tubæ sonum, et vocem verborum, quam qui audierunt, excusaverunt se, ne eis fieret verbum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 20, 'Non enim portabant quod dicebatur: Et si bestia tetigerit montem, lapidabitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 21, 'Et ita terribile erat quod videbatur. Moyses dixit: Exterritus sum, et tremebundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 22, 'Sed accessistis ad Sion montem, et civitatem Dei viventis, Jerusalem cælestem, et multorum millium angelorum frequentiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 23, 'et ecclesiam primitivorum, qui conscripti sunt in cælis, et judicem omnium Deum, et spiritus justorum perfectorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 24, 'et testamenti novi mediatorem Jesum, et sanguinis aspersionem melius loquentem quam Abel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 25, 'Videte ne recusetis loquentem. Si enim illi non effugerunt, recusantes eum, qui super terram loquebatur: multo magis nos, qui de cælis loquentem nobis avertimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 26, 'Cujus vox movit terram tunc: nunc autem repromittit, dicens: Adhuc semel, et ego movebo non solum terram, sed et cælum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 27, 'Quod autem, Adhuc semel, dicit: declarat mobilium translationem tamquam factorum, ut maneant ea quæ sunt immobilia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 28, 'Itaque regnum immobile suscipientes, habemus gratiam: per quam serviamus placentes Deo, cum metu et reverentia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 12, 29, 'Etenim Deus noster ignis consumens est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 1, 'Caritas fraternitatis maneat in vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 2, 'et hospitalitatem nolite oblivisci: per hanc enim latuerunt quidam, angelis hospitio receptis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 3, 'Mementote vinctorum, tamquam simul vincti: et laborantium, tamquam et ipsi in corpore morantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 4, 'Honorabile connubium in omnibus, et thorus immaculatus. Fornicatores enim, et adulteros judicabit Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 5, 'Sint mores sine avaritia, contenti præsentibus: ipse enim dixit: Non te deseram, neque derelinquam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 6, 'ita ut confidenter dicamus: Dominus mihi adjutor: non timebo quid faciat mihi homo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 7, 'Mementote præpositorum vestrorum, qui vobis locuti sunt verbum Dei: quorum intuentes exitum conversationis, imitamini fidem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 8, 'Jesus Christus heri, et hodie: ipse et in sæcula.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 9, 'Doctrinis variis et peregrinis nolite abduci. Optimum est enim gratia stabilire cor, non escis: quæ non profuerunt ambulantibus in eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 10, 'Habemus altare, de quo edere non habent potestatem, qui tabernaculo deserviunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 11, 'Quorum enim animalium infertur sanguis pro peccato in Sancta per pontificem, horum corpora cremantur extra castra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 12, 'Propter quod et Jesus, ut sanctificaret per suum sanguinem populum, extra portam passus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 13, 'Exeamus igitur ad eum extra castra, improperium ejus portantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 14, 'Non enim habemus hic manentem civitatem, sed futuram inquirimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 15, 'Per ipsum ergo offeramus hostiam laudis semper Deo, id est, fructum labiorum confitentium nomini ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 16, 'Beneficentiæ autem et communionis nolite oblivisci: talibus enim hostiis promeretur Deus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 17, 'Obedite præpositis vestris, et subjacete eis. Ipsi enim pervigilant quasi rationem pro animabus vestris reddituri, ut cum gaudio hoc faciant, et non gementes: hoc enim non expedit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 18, 'Orate pro nobis: confidimus enim quia bonam conscientiam habemus in omnibus bene volentes conversari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 19, 'Amplius autem deprecor vos hoc facere, quo celerius restituar vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 20, 'Deus autem pacis, qui eduxit de mortuis pastorem magnum ovium, in sanguine testamenti æterni, Dominum nostrum Jesum Christum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 21, 'aptet vos in omni bono, ut faciatis ejus voluntatem: faciens in vobis quod placeat coram se per Jesum Christum: cui est gloria in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 22, 'Rogo autem vos fratres, ut sufferatis verbum solatii. Etenim perpaucis scripsi vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 23, 'Cognoscite fratrem nostrum Timotheum dimissum: cum quo (si celerius venerit) videbo vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 24, 'Salutate omnes præpositos vestros, et omnes sanctos. Salutant vos de Italia fratres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 13, 25, 'Gratia cum omnibus vobis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jacobus, Dei et Domini nostri Jesu Christi servus, duodecim tribubus, quæ sunt in dispersione, salutem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Omne gaudium existimate fratres mei, cum in tentationes varias incideritis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'scientes quod probatio fidei vestræ patientiam operatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Patientia autem opus perfectum habet: ut sitis perfecti et integri in nullo deficientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Si quis autem vestrum indiget sapientia, postulet a Deo, qui dat omnibus affluenter, et non improperat: et dabitur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Postulet autem in fide nihil hæsitans: qui enim hæsitat, similis est fluctui maris, qui a vento movetur et circumfertur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'non ergo æstimet homo ille quod accipiat aliquid a Domino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Vir duplex animo inconstans est in omnibus viis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Glorietur autem frater humilis in exaltatione sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'dives autem in humilitate sua, quoniam sicut flos fœni transibit;');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'exortus est enim sol cum ardore, et arefecit fœnum, et flos ejus decidit, et decor vultus ejus deperiit: ita et dives in itineribus suis marcescet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Beatus vir qui suffert tentationem: quoniam cum probatus fuerit, accipiet coronam vitæ, quam repromisit Deus diligentibus se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Nemo cum tentatur, dicat quoniam a Deo tentatur: Deus enim intentator malorum est: ipse autem neminem tentat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Unusquisque vero tentatur a concupiscentia sua abstractus, et illectus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Deinde concupiscentia cum conceperit, parit peccatum: peccatum vero cum consummatum fuerit, generat mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Nolite itaque errare, fratres mei dilectissimi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Omne datum optimum, et omne donum perfectum desursum est, descendens a Patre luminum, apud quem non est transmutatio, nec vicissitudinis obumbratio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Voluntarie enim genuit nos verbo veritatis, ut simus initium aliquod creaturæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Scitis, fratres mei dilectissimi. Sit autem omnis homo velox ad audiendum: tardus autem ad loquendum, et tardus ad iram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Ira enim viri justitiam Dei non operatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'Propter quod abjicientes omnem immunditiam, et abundantiam malitiæ, in mansuetudine suscipite insitum verbum, quod potest salvare animas vestras.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, 'Estote autem factores verbi, et non auditores tantum: fallentes vosmetipsos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'Quia si quis auditor est verbi, et non factor, hic comparabitur viro consideranti vultum nativitatis suæ in speculo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 24, 'consideravit enim se, et abiit, et statim oblitus est qualis fuerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 25, 'Qui autem perspexerit in legem perfectam libertatis, et permanserit in ea, non auditor obliviosus factus, sed factor operis: hic beatus in facto suo erit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 26, 'Si quis autem putat se religiosum esse, non refrenans linguam suam, sed seducens cor suum, hujus vana est religio.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 27, 'Religio munda et immaculata apud Deum et Patrem, hæc est: visitare pupillos et viduas in tribulatione eorum, et immaculatum se custodire ab hoc sæculo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Fratres mei, nolite in personarum acceptione habere fidem Domini nostri Jesu Christi gloriæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Etenim si introierit in conventum vestrum vir aureum annulum habens in veste candida, introierit autem et pauper in sordido habitu,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'et intendatis in eum qui indutus est veste præclara, et dixeritis ei: Tu sede hic bene: pauperi autem dicatis: Tu sta illic; aut sede sub scabello pedum meorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'nonne judicatis apud vosmetipsos, et facti estis judices cogitationum iniquarum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Audite, fratres mei dilectissimi: nonne Deus elegit pauperes in hoc mundo, divites in fide, et hæredes regni, quod repromisit Deus diligentibus se?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'vos autem exhonorastis pauperem. Nonne divites per potentiam opprimunt vos, et ipsi trahunt vos ad judicia?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'nonne ipsi blasphemant bonum nomen, quod invocatum est super vos?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Si tamen legem perficitis regalem secundum Scripturas: Diliges proximum tuum sicut teipsum: bene facitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'si autem personas accipitis, peccatum operamini, redarguti a lege quasi transgressores.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Quicumque autem totam legem servaverit, offendat autem in uno, factus est omnium reus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Qui enim dixit: Non mœchaberis, dixit et: Non occides. Quod si non mœchaberis, occides autem, factus es transgressor legis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Sic loquimini, et sic facite sicut per legem libertatis incipientes judicari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Judicium enim sine misericordia illi qui non fecit misericordiam: superexaltat autem misericordia judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Quid proderit, fratres mei, si fidem quis dicat se habere, opera autem non habeat? numquid poterit fides salvare eum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Si autem frater et soror nudi sint, et indigeant victu quotidiano,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'dicat autem aliquis ex vobis illis: Ite in pace, calefacimini et saturamini: non dederitis autem eis quæ necessaria sunt corpori, quid proderit?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Sic et fides, si non habeat opera, mortua est in semetipsa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Sed dicet quis: Tu fidem habes, et ego opera habeo: ostende mihi fidem tuam sine operibus: et ego ostendam tibi ex operibus fidem meam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Tu credis quoniam unus est Deus: bene facis: et dæmones credunt, et contremiscunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Vis autem scire, o homo inanis, quoniam fides sine operibus mortua est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Abraham pater noster nonne ex operibus justificatus est, offerens Isaac filium suum super altare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Vides quoniam fides cooperabatur operibus illius: et ex operibus fides consummata est?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Et suppleta est Scriptura, dicens: Credidit Abraham Deo, et reputatum est illi ad justitiam, et amicus Dei appellatus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Videtis quoniam ex operibus justificatur homo, et non ex fide tantum?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Similiter et Rahab meretrix, nonne ex operibus justificata est, suscipiens nuntios, et alia via ejiciens?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Sicut enim corpus sine spiritu mortuum est, ita et fides sine operibus mortua est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Nolite plures magistri fieri fratres mei, scientes quoniam majus judicium sumitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'In multis enim offendimus omnes. Si quis in verbo non offendit, hic perfectus est vir: potest etiam freno circumducere totum corpus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Si autem equis frena in ora mittimus ad consentiendum nobis, et omne corpus illorum circumferimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Ecce et naves, cum magnæ sint, et a ventis validis minentur, circumferuntur a modico gubernaculo ubi impetus dirigentis voluerit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Ita et lingua modicum quidem membrum est, et magna exaltat. Ecce quantus ignis quam magnam silvam incendit!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Et lingua ignis est, universitas iniquitatis. Lingua constituitur in membris nostris, quæ maculat totum corpus, et inflammat rotam nativitatis nostræ inflammata a gehenna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Omnis enim natura bestiarum, et volucrum, et serpentium, et ceterorum domantur, et domita sunt a natura humana:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'linguam autem nullus hominum domare potest: inquietum malum, plena veneno mortifero.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'In ipsa benedicimus Deum et Patrem: et in ipsa maledicimus homines, qui ad similitudinem Dei facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ex ipso ore procedit benedictio et maledictio. Non oportet, fratres mei, hæc ita fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Numquid fons de eodem foramine emanat dulcem et amaram aquam?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Numquid potest, fratres mei, ficus uvas facere, aut vitis ficus? Sic neque salsa dulcem potest facere aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Quis sapiens et disciplinatus inter vos? Ostendat ex bona conversatione operationem suam in mansuetudine sapientiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Quod si zelum amarum habetis, et contentiones sint in cordibus vestris: nolite gloriari, et mendaces esse adversus veritatem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'non est enim ista sapientia desursum descendens: sed terrena, animalis, diabolica.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ubi enim zelus et contentio, ibi inconstantia et omne opus pravum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Quæ autem desursum est sapientia, primum quidem pudica est, deinde pacifica, modesta, suadibilis, bonis consentiens, plena misericordia et fructibus bonis, non judicans, sine simulatione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Fructus autem justitiæ, in pace seminatur, facientibus pacem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Unde bella et lites in vobis? nonne hinc: ex concupiscentiis vestris, quæ militant in membris vestris?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'concupiscitis, et non habetis: occiditis, et zelatis: et non potestis adipisci: litigatis, et belligeratis, et non habetis, propter quod non postulatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Petitis, et non accipitis: eo quod male petatis: ut in concupiscentiis vestris insumatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Adulteri, nescitis quia amicitia hujus mundi inimica est Dei? quicumque ergo voluerit amicus esse sæculi hujus, inimicus Dei constituitur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'An putatis quia inaniter Scriptura dicat: Ad invidiam concupiscit spiritus qui habitat in vobis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'majorem autem dat gratiam. Propter quod dicit: Deus superbis resistit, humilibus autem dat gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Subditi ergo estote Deo, resistite autem diabolo, et fugiet a vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Appropinquate Deo, et appropinquabit vobis. Emundate manus, peccatores: et purificate corda, duplices animo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Miseri estote, et lugete, et plorate: risus vester in luctum convertatur, et gaudium in mœrorem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Humiliamini in conspectu Domini, et exaltabit vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Nolite detrahere alterutrum fratres. Qui detrahit fratri, aut qui judicat fratrem suum, detrahit legi, et judicat legem. Si autem judicas legem, non es factor legis, sed judex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'Unus est legislator et judex, qui potest perdere et liberare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'Tu autem quis es, qui judicas proximum? Ecce nunc qui dicitis: Hodie, aut crastino ibimus in illam civitatem, et faciemus ibi quidem annum, et mercabimur, et lucrum faciemus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'qui ignoratis quid erit in crastino.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Quæ est enim vita vestra? vapor est ad modicum parens, et deinceps exterminabitur; pro eo ut dicatis: Si Dominus voluerit. Et: Si vixerimus, faciemus hoc, aut illud.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'Nunc autem exsultatis in superbiis vestris. Omnis exsultatio talis, maligna est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Scienti igitur bonum facere, et non facienti, peccatum est illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Agite nunc divites, plorate ululantes in miseriis vestris, quæ advenient vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Divitiæ vestræ putrefactæ sunt, et vestimenta vestra a tineis comesta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Aurum et argentum vestrum æruginavit: et ærugo eorum in testimonium vobis erit, et manducabit carnes vestras sicut ignis. Thesaurizastis vobis iram in novissimis diebus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Ecce merces operariorum, qui messuerunt regiones vestras, quæ fraudata est a vobis, clamat: et clamor eorum in aures Domini sabbaoth introivit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Epulati estis super terram, et in luxuriis enutristis corda vestra in die occisionis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Addixistis, et occidistis justum, et non restitit vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Patientes igitur estote, fratres, usque ad adventum Domini. Ecce agricola exspectat pretiosum fructum terræ, patienter ferens donec accipiat temporaneum et serotinum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Patientes igitur estote et vos, et confirmate corda vestra: quoniam adventus Domini appropinquavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Nolite ingemiscere, fratres, in alterutrum, ut non judicemini. Ecce judex ante januam assistit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Exemplum accipite, fratres, exitus mali, laboris, et patientiæ, prophetas qui locuti sunt in nomine Domini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Ecce beatificamus eos qui sustinuerunt. Sufferentiam Job audistis, et finem Domini vidistis, quoniam misericors Dominus est, et miserator.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Ante omnia autem, fratres mei, nolite jurare, neque per cælum, neque per terram, neque aliud quodcumque juramentum. Sit autem sermo vester: Est, est: Non, non: ut non sub judicio decidatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Tristatur aliquis vestrum? oret. \'quo animo est? psallat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Infirmatur quis in vobis? inducat presbyteros ecclesiæ, et orent super eum, ungentes eum oleo in nomine Domini:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'et oratio fidei salvabit infirmum, et alleviabit eum Dominus: et si in peccatis sit, remittentur ei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'Confitemini ergo alterutrum peccata vestra, et orate pro invicem ut salvemini: multum enim valet deprecatio justi assidua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Elias homo erat similis nobis passibilis: et oratione oravit ut non plueret super terram, et non pluit annos tres, et menses sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Et rursum oravit: et cælum dedit pluviam, et terra dedit fructum suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'Fratres mei, si quis ex vobis erraverit a veritate, et converterit quis eum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'scire debet quoniam qui converti fecerit peccatorem ab errore viæ suæ, salvabit animam ejus a morte, et operiet multitudinem peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Petrus Apostolus Jesu Christi, electis advenis dispersionis Ponti, Galatiæ, Cappadociæ, Asiæ, et Bithyniæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'secundum præscientiam Dei Patris, in sanctificationem Spiritus, in obedientiam, et aspersionem sanguinis Jesu Christi. Gratia vobis, et pax multiplicetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Benedictus Deus et Pater Domini nostri Jesu Christi, qui secundum misericordiam suam magnam regeneravit nos in spem vivam, per resurrectionem Jesu Christi ex mortuis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'in hæreditatem incorruptibilem, et incontaminatam, et immarcescibilem, conservatam in cælis in vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'qui in virtute Dei custodimini per fidem in salutem, paratam revelari in tempore novissimo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'In quo exsultabis, modicum nunc si oportet contristari in variis tentationibus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'ut probatio vestræ fidei multo pretiosior auro (quod per ignem probatur) inveniatur in laudem, et gloriam, et honorem in revelatione Jesu Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'quem cum non videritis, diligitis: in quem nunc quoque non videntes creditis: credentes autem exsultabitis lætitia inenarrabili, et glorificata:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'reportantes finem fidei vestræ, salutem animarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'De qua salute exquisierunt, atque scrutati sunt prophetæ, qui de futura in vobis gratia prophetaverunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'scrutantes in quod vel quale tempus significaret in eis Spiritus Christi: prænuntians eas quæ in Christo sunt passiones, et posteriores glorias:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'quibus revelatum est quia non sibimetipsis, vobis autem ministrabant ea quæ nunc nuntiata sunt vobis per eos qui evangelizaverunt vobis, Spiritu Sancto misso de cælo, in quem desiderant angeli prospicere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'Propter quod succincti lumbos mentis vestræ, sobrii, perfecte sperate in eam, quæ offertur vobis, gratiam, in revelationem Jesu Christi:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'quasi filii obedientiæ, non configurati prioribus ignorantiæ vestræ desideriis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'sed secundum eum qui vocavit vos, Sanctum: et ipsi in omni conversatione sancti sitis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'quoniam scriptum est: Sancti eritis, quoniam ego sanctus sum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'Et si patrem invocatis eum, qui sine acceptione personarum judicat secundum uniuscujusque opus, in timore incolatus vestri tempore conversamini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Scientes quod non corruptibilibus, auro vel argento, redempti estis de vana vestra conversatione paternæ traditionis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'sed pretioso sanguine quasi agni immaculati Christi, et incontaminati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'præcogniti quidem ante mundi constitutionem, manifestati autem novissimis temporibus propter vos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'qui per ipsum fideles estis in Deo, qui suscitavit eum a mortuis, et dedit ei gloriam, ut fides vestra et spes esset in Deo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'animas vestras castificantes in obedientia caritatis, in fraternitatis amore, simplici ex corde invicem diligite attentius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'renati non ex semine corruptibili, sed incorruptibili per verbum Dei vivi, et permanentis in æternum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'quia omnis caro ut fœnum: et omnis gloria ejus tamquam flos fœni: exaruit fœnum, et flos ejus decidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'Verbum autem Domini manet in æternum: hoc est autem verbum, quod evangelizatum est in vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Deponentes igitur omnem malitiam, et omnem dolum, et simulationes, et invidias, et omnes detractiones,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'sicut modo geniti infantes, rationabile, sine dolo lac concupiscite: ut in eo crescatis in salutem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'si tamen gustastis quoniam dulcis est Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'Ad quem accedentes lapidem vivum, ab hominibus quidem reprobatum, a Deo autem electum, et honorificatum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'et ipsi tamquam lapides vivi superædificamini, domus spiritualis, sacerdotium sanctum, offerre spirituales hostias, acceptabiles Deo per Jesum Christum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'Propter quod continet Scriptura: Ecce pono in Sion lapidem summum angularem, electum, pretiosum: et qui crediderit in eum, non confundetur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'Vobis igitur honor credentibus: non credentibus autem lapis, quem reprobaverunt ædificantes: hic factus est in caput anguli,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'et lapis offensionis, et petra scandali, his qui offendunt verbo, nec credunt in quo et positi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'Vos autem genus electum, regale sacerdotium, gens sancta, populus acquisitionis: ut virtutes annuntietis ejus qui de tenebris vos vocavit in admirabile lumen suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'Qui aliquando non populus, nunc autem populus Dei: qui non consecuti misericordiam, nunc autem misericordiam consecuti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'Carissimi, obsecro vos tamquam advenas et peregrinos abstinere vos a carnalibus desideriis, quæ militant adversus animam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'conversationem vestram inter gentes habentes bonam: ut in eo quod detrectant de vobis tamquam de malefactoribus, ex bonis operibus vos considerantes, glorificent Deum in die visitationis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'Subjecti igitur estote omni humanæ creaturæ propter Deum: sive regi quasi præcellenti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'sive ducibus tamquam ab eo missis ad vindictam malefactorum, laudem vero bonorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'quia sic est voluntas Dei, ut benefacientes obmutescere faciatis imprudentium hominum ignorantiam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'quasi liberi, et non quasi velamen habentes malitiæ libertatem, sed sicut servi Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'Omnes honorate: fraternitatem diligite: Deum timete: regem honorificate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'Servi, subditi estote in omni timore dominis, non tantum bonis et modestis, sed etiam dyscolis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'Hæc est enim gratia, si propter Dei conscientiam sustinet quis tristitias, patiens injuste.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'Quæ enim est gloria, si peccantes, et colaphizati suffertis? sed si bene facientes patienter sustinetis, hæc est gratia apud Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'In hoc enim vocati estis: quia et Christus passus est pro nobis, vobis relinquens exemplum ut sequamini vestigia ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'qui peccatum non fecit, nec inventus est dolus in ore ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 23, 'qui cum malediceretur, non maledicebat: cum pateretur, non comminabatur: tradebat autem judicanti se injuste:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 24, 'qui peccata nostra ipse pertulit in corpore suo super lignum; ut peccatis mortui, justitiæ vivamus: cujus livore sanati estis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 25, 'Eratis enim sicut oves errantes, sed conversi estis nunc ad pastorem, et episcopum animarum vestrarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'Similiter et mulieres subditæ sint viris suis: ut etsi qui non credunt verbo, per mulierem conversationem sine verbo lucrifiant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'considerantes in timore castam conversationem vestram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'Quarum non sit extrinsecus capillatura, aut circumdatio auri, aut indumenti vestimentorum cultus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'sed qui absconditus est cordis homo, in incorruptibilitate quieti, et modesti spiritus, qui est in conspectu Dei locuples.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'Sic enim aliquando et sanctæ mulieres, sperantes in Deo, ornabant se, subjectæ propriis viris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'Sicut Sara obediebat Abrahæ, dominum eum vocans: cujus estis filiæ benefacientes, et non pertimentes ullam perturbationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Viri similiter cohabitantes secundum scientiam, quasi infirmiori vasculo muliebri impartientes honorem, tamquam et cohæredibus gratiæ vitæ: ut non impediantur orationes vestræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'In fine autem omnes unanimes, compatientes fraternitatis amatores, misericordes, modesti, humiles:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'non reddentes malum pro malo, nec maledictum pro maledicto, sed e contrario benedicentes: quia in hoc vocati estis, ut benedictionem hæreditate possideatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'Qui enim vult vitam diligere, et dies videre bonos, coërceat linguam suam a malo, et labia ejus ne loquantur dolum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'Declinet a malo, et faciat bonum: inquirat pacem, et sequatur eam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'quia oculi Domini super justos, et aures ejus in preces eorum: vultus autem Domini super facientes mala.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Et quis est qui vobis noceat, si boni æmulatores fueritis?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'Sed et si quid patimini propter justitiam, beati. Timorem autem eorum ne timueritis, et non conturbemini.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Dominum autem Christum sanctificate in cordibus vestris, parati semper ad satisfactionem omni poscenti vos rationem de ea, quæ in vobis est, spe.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'Sed cum modestia, et timore, conscientiam habentes bonam: ut in eo, quod detrahunt vobis, confundantur, qui calumniantur vestram bonam in Christo conversationem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Melius est enim benefacientes (si voluntas Dei velit) pati, quam malefacientes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Quia et Christus semel pro peccatis nostris mortuus est, justus pro injustis, ut nos offerret Deo, mortificatus quidem carne, vivificatus autem spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'In quo et his, qui in carcere erant, spiritibus veniens prædicavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, 'qui increduli fuerant aliquando, quando exspectabant Dei patientiam in diebus Noë, cum fabricaretur arca: in qua pauci, id est octo animæ, salvæ factæ sunt per aquam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'Quod et vos nunc similis formæ salvos fecit baptisma: non carnis depositio sordium, sed conscientiæ bonæ interrogatio in Deum per resurrectionem Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 22, 'Qui est in dextera Dei, deglutiens mortem ut vitæ æternæ hæredes efficeremur: profectus in cælum subjectis sibi angelis, et potestatibus, et virtutibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, 'Christo igitur passo in carne, et vos eadem cogitatione armamini: quia qui passus est in carne, desiit a peccatis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'ut jam non desideriis hominum, sed voluntati Dei, quod reliquum est in carne vivat temporis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'Sufficit enim præteritum tempus ad voluntatem gentium consummandam his qui ambulaverunt in luxuriis, desideriis, vinolentiis, comessationibus, potationibus, et illicitis idolorum cultibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'In quo admirantur non concurrentibus vobis in eamdem luxuriæ confusionem, blasphemantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'Qui reddent rationem ei qui paratus est judicare vivos et mortuos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'Propter hoc enim et mortuis evangelizatum est: ut judicentur quidem secundum homines in carne, vivant autem secundum Deum in spiritu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, 'Omnium autem finis appropinquavit. Estote itaque prudentes, et vigilate in orationibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'Ante omnia autem, mutuam in vobismetipsis caritatem continuam habentes: quia caritas operit multitudinem peccatorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'Hospitales invicem sine murmuratione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Unusquisque, sicut accepit gratiam, in alterutrum illam administrantes, sicut boni dispensatores multiformis gratiæ Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Si quis loquitur, quasi sermones Dei: si quis ministrat, tamquam ex virtute, quam administrat Deus: ut in omnibus honorificetur Deus per Jesum Christum: cui est gloria et imperium in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'Carissimi, nolite peregrinari in fervore, qui ad tentationem vobis fit, quasi novi aliquid vobis contingat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'sed communicantes Christi passionibus gaudete, ut et in revelatione gloriæ ejus gaudeatis exsultantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'Si exprobramini in nomine Christi, beati eritis: quoniam quod est honoris, gloriæ, et virtutis Dei, et qui est ejus Spiritus, super vos requiescit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'Nemo autem vestrum patiatur ut homicida, aut fur, aut maledicus, aut alienorum appetitor.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'Si autem ut christianus, non erubescat: glorificet autem Deum in isto nomine:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, 'quoniam tempus est ut incipiat judicium a domo Dei. Si autem primum a nobis, quis finis eorum, qui non credunt Dei Evangelio?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'et si justus vix salvabitur, impius et peccator ubi parebunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'Itaque et hi, qui patiuntur secundum voluntatem Dei, fideli Creatori commendent animas suas in benefactis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 1, 'Seniores ergo, qui in vobis sunt, obsecro, consenior et testis Christi passionum: qui et ejus, quæ in futuro revelanda est, gloriæ communicator:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 2, 'pascite qui in vobis est gregem Dei, providentes non coacte, sed spontanee secundum Deum: neque turpis lucri gratia, sed voluntarie:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 3, 'neque ut dominantes in cleris, sed forma facti gregis ex animo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 4, 'Et cum apparuerit princeps pastorum, percipietis immarcescibilem gloriæ coronam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 5, 'Similiter adolescentes subditi estote senioribus. Omnes autem invicem humilitatem insinuate, quia Deus superbis resistit, humilibus autem dat gratiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 6, 'Humiliamini igitur sub potenti manu Dei, ut vos exaltet in tempore visitationis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 7, 'omnem sollicitudinem vestram projicientes in eum, quoniam ipsi cura est de vobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 8, 'Sobrii estote, et vigilate: quia adversarius vester diabolus tamquam leo rugiens circuit, quærens quem devoret:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 9, 'cui resistite fortes in fide: scientes eamdem passionem ei quæ in mundo est vestræ fraternitati fieri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 10, 'Deus autem omnis gratiæ, qui vocavit nos in æternam suam gloriam in Christo Jesu, modicum passos ipse perficiet, confirmabit, solidabitque.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 11, 'Ipsi gloria, et imperium in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 12, 'Per Silvanum fidelem fratrem vobis, ut arbitror, breviter scripsi: obsecrans et contestans, hanc esse veram gratiam Dei, in qua statis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 13, 'Salutat vos ecclesia quæ est in Babylone coëlecta, et Marcus filius meus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 5, 14, 'Salutate invicem in osculo sancto. Gratia vobis omnibus qui estis in Christo Jesu. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Simon Petrus, servus et apostolus Jesu Christi, iis qui coæqualem nobiscum sortiti sunt fidem in justitia Dei nostri, et Salvatoris Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'Gratia vobis, et pax adimpleatur in cognitione Dei, et Christi Jesu Domini nostri:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Quomodo omnia nobis divinæ virtutis suæ, quæ ad vitam et pietatem donata sunt, per cognitionem ejus, qui vocavit nos propria gloria, et virtute,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'per quem maxima, et pretiosa nobis promissa donavit: ut per hæc efficiamini divinæ consortes naturæ: fugientes ejus, quæ in mundo est, concupiscentiæ corruptionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'Vos autem curam omnem subinferentes, ministrate in fide vestra virtutem, in virtute autem scientiam,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'in scientia autem abstinentiam, in abstinentia autem patientiam, in patientia autem pietatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'in pietate autem amorem fraternitatis, in amore autem fraternitatis caritatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'Hæc enim si vobiscum adsint, et superent, non vacuos nec sine fructu vos constituent in Domini nostri Jesu Christi cognitione.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'Cui enim non præsto sunt hæc, cæcus est, et manu tentans, oblivionem accipiens purgationis veterum suorum delictorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'Quapropter fratres, magis satagite ut per bona opera certam vestram vocationem, et electionem faciatis: hæc enim facientes, non peccabitis aliquando.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'Sic enim abundanter ministrabitur vobis introitus in æternum regnum Domini nostri et Salvatoris Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'Propter quod incipiam vos semper commonere de his: et quidem scientes et confirmatos vos in præsenti veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'Justum autem arbitror quamdiu sum in hoc tabernaculo, suscitare vos in commonitione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'certus quod velox est depositio tabernaculi mei secundum quod et Dominus noster Jesus Christus significavit mihi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'Dabo autem operam et frequenter habere vos post obitum meum, ut horum memoriam faciatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Non enim doctas fabulas secuti notam fecimus vobis Domini nostri Jesu Christi virtutem et præsentiam: sed speculatores facti illius magnitudinis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Accipiens enim a Deo Patre honorem et gloriam, voce delapsa ad eum hujuscemodi a magnifica gloria: Hic est Filius meus dilectus, in quo mihi complacui, ipsum audite.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Et hanc vocem nos audivimus de cælo allatam, cum essemus cum ipso in monte sancto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Et habemus firmiorem propheticum sermonem: cui benefacitis attendentes quasi lucernæ lucenti in caliginoso loco donec dies elucescat, et lucifer oriatur in cordibus vestris:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'hoc primum intelligentes quod omnis prophetia Scripturæ propria interpretatione non fit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'Non enim voluntate humana allata est aliquando prophetia: sed Spiritu Sancto inspirati, locuti sunt sancti Dei homines.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Fuerunt vero et pseudoprophetæ in populo, sicut et in vobis erunt magistri mendaces, qui introducent sectas perditionis: et eum qui emit eos, Dominum negant, superducentes sibi celerem perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'Et multi sequentur eorum luxurias, per quos via veritatis blasphemabitur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'et in avaritia fictis verbis de vobis negotiabuntur: quibus judicium jam olim non cessat: et perditio eorum non dormitat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Si enim Deus angelis peccantibus non pepercit, sed rudentibus inferni detractos in tartarum tradidit cruciandos, in judicium reservari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Et originali mundo non pepercit, sed octavum Noë justitiæ præconem custodivit, diluvium mundo impiorum inducens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'Et civitates Sodomorum et Gomorrhæorum in cinerem redigens, eversione damnavit: exemplum eorum, qui impie acturi sunt, ponens:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'et justum Lot oppressum a nefandorum injuria, ac luxuriosa conversatione eripuit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'aspectu enim, et auditu justus erat: habitans apud eos, qui de die in diem animam justam iniquis operibus cruciabant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Novit Dominus pios de tentatione eripere: iniquos vero in diem judicii reservare cruciandos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'Magis autem eos, qui post carnem in concupiscentia immunditiæ ambulant, dominationemque contemnunt, audaces, sibi placentes, sectas non metuunt introducere blasphemantes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'ubi angeli fortitudine, et virtute cum sint majores, non portant adversum se execrabile judicium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'Hi vero velut irrationabilia pecora, naturaliter in captionem, et in perniciem in his quæ ignorant blasphemantes in corruptione sua peribunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'percipientes mercedem injustitiæ, voluptatem existimantes diei delicias: coinquinationes, et maculæ deliciis affluentes, in conviviis suis luxuriantes vobiscum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'oculos habentes plenos adulterii, et incessabilis delicti. Pellicientes animas instabiles, cor exercitatum avaritia habentes, maledictionis filii:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'derelinquentes rectam viam erraverunt, secuti viam Balaam ex Bosor, qui mercedem iniquitatis amavit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'correptionem vero habuit suæ vesaniæ: subjugale mutum animal, hominis voce loquens, prohibuit prophetæ insipientiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'Hi sunt fontes sine aqua, et nebulæ turbinibus exagitatæ, quibus caligo tenebrarum reservatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Superba enim vanitatis loquentes, pelliciunt in desideriis carnis luxuriæ eos, qui paululum effugiunt, qui in errore conversantur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'libertatem illis promittentes, cum ipsi servi sint corruptionem: a quo enim quis superatus est, hujus et servus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Si enim refugientes coinquinationes mundi in cognitione Domini nostri, et Salvatoris Jesu Christi, his rursus implicati superantur: facta sunt eis posteriora deteriora prioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, 'Melius enim erat illis non cognoscere viam justitiæ, quam post agnitionem, retrorsum converti ab eo, quod illis traditum est, sancto mandato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'Contigit enim eis illud veri proverbii: Canis reversus ad suum vomitum: et, Sus lota in volutabro luti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Hanc ecce vobis, carissimi, secundam scribo epistolam, in quibus vestram excito in commonitione sinceram mentem:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'ut memores sitis eorum, quæ prædixi, verborum, a sanctis prophetis et apostolorum vestrorum, præceptorum Domini et Salvatoris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Hoc primum scientes, quod venient in novissimis diebus in deceptione illusores, juxta proprias concupiscentias ambulantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'dicentes: Ubi est promissio, aut adventus ejus? ex quo enim patres dormierunt, omnia sic perseverant ab initio creaturæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'Latet enim eos hoc volentes, quod cæli erant prius, et terra de aqua, et per aquam consistens Dei verbo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'per quæ, ille tunc mundus aqua inundatus, periit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'Cæli autem, qui nunc sunt, et terra eodem verbo repositi sunt, igni reservati in diem judicii, et perditionis impiorum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Unum vero hoc non lateat vos, carissimi, quia unus dies apud Dominum sicut mille anni, et mille anni sicut dies unus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'Non tardat Dominus promissionem suam, sicut quidam existimant: sed patienter agit propter vos, nolens aliquos perire, sed omnes ad pœnitentiam reverti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'Adveniet autem dies Domini ut fur: in quo cæli magno impetu transient, elementa vero calore solventur, terra autem et quæ in ipsa sunt opera, exurentur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Cum igitur hæc omnia dissolvenda sunt, quales oportet vos esse in sanctis conversationibus, et pietatibus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'exspectantes, et properantes in adventum diei Domini, per quem cæli ardentes solventur, et elementa ignis ardore tabescent?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Novos vero cælos, et novam terram secundum promissa ipsius exspectamus, in quibus justitia habitat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Propter quod, carissimi, hæc exspectantes, satagite immaculati, et inviolati ei inveniri in pace:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'et Domini nostri longanimitatem, salutem arbitremini: sicut et carissimus frater noster Paulus secundum datam sibi sapientiam scripsit vobis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'sicut et omnibus epistolis, loquens in eis de his in quibus sunt quædam difficilia intellectu, quæ indocti et instabiles depravant, sicut et ceteras Scripturas, ad suam ipsorum perditionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Vos igitur fratres, præscientes custodite, ne insipientium errore traducti excidatis a propria firmitate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'crescite vero in gratia, et in cognitione Domini nostri, et Salvatoris Jesu Christi. Ipsi gloria et nunc, et in diem æternitatis. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Quod fuit ab initio, quod audivimus, quod vidimus oculis nostris, quod perspeximus, et manus nostræ contrectaverunt de verbo vitæ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'et vita manifestata est, et vidimus, et testamur, et annuntiamus vobis vitam æternam, quæ erat apud Patrem, et apparuit nobis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'quod vidimus et audivimus, annuntiamus vobis, ut et vos societatem habeatis nobiscum, et societas nostra sit cum Patre, et cum Filio ejus Jesu Christo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'Et hæc scribimus vobis ut gaudeatis, et gaudium vestrum sit plenum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'Et hæc est annuntiatio, quam audivimus ab eo, et annuntiamus vobis: quoniam Deus lux est, et tenebræ in eo non sunt ullæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'Si dixerimus quoniam societatem habemus cum eo, et in tenebris ambulamus, mentimur, et veritatem non facimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'Si autem in luce ambulamus sicut et ipse est in luce, societatem habemus ad invicem, et sanguis Jesu Christi, Filii ejus, emundat nos ab omni peccato.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Si dixerimus quoniam peccatum non habemus, ipsi nos seducimus, et veritas in nobis non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Si confiteamur peccata nostra: fidelis est, et justus, ut remittat nobis peccata nostra, et emundet nos ab omni iniquitate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'Si dixerimus quoniam non peccavimus, mendacem facimus eum, et verbum ejus non est in nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Filioli mei, hæc scribo vobis, ut non peccetis. Sed et si quis peccaverit, advocatum habemus apud Patrem, Jesum Christum justum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'et ipse est propitiatio pro peccatis nostris: non pro nostris autem tantum, sed etiam pro totius mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'Et in hoc scimus quoniam cognovimus eum, si mandata ejus observemus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Qui dicit se nosse eum, et mandata ejus non custodit, mendax est, et in hoc veritas non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Qui autem servat verbum ejus, vere in hoc caritas Dei perfecta est: et in hoc scimus quoniam in ipso sumus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Qui dicit se in ipso manere, debet, sicut ille ambulavit, et ipse ambulare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'Carissimi, non mandatum novum scribo vobis, sed mandatum vetus, quod habuistis ab initio. Mandatum vetus est verbum, quod audistis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'Iterum mandatum novum scribo vobis, quod verum est et in ipso, et in vobis: quia tenebræ transierunt, et verum lumen jam lucet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'Qui dicit se in luce esse, et fratrem suum odit, in tenebris est usque adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'Qui diligit fratrem suum, in lumine manet, et scandalum in eo non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'Qui autem odit fratrem suum, in tenebris est, et in tenebris ambulat, et nescit quo eat: quia tenebræ obcæcaverunt oculos ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'Scribo vobis, filioli, quoniam remittuntur vobis peccata propter nomen ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Scribo vobis, patres, quoniam cognovistis eum, qui ab initio est. Scribo vobis, adolescentes, quoniam vicistis malignum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'Scribo vobis, infantes, quoniam cognovistis patrem. Scribo vobis juvenes, quoniam fortes estis, et verbum Dei manet in vobis, et vicistis malignum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'Nolite diligere mundum, neque ea quæ in mundo sunt. Si quis diligit mundum, non est caritas Patris in eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'quoniam omne quod est in mundo, concupiscentia carnis est, et concupiscentia oculorum, et superbia vitæ: quæ non est ex Patre, sed ex mundo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Et mundus transit, et concupiscentia ejus: qui autem facit voluntatem Dei manet in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Filioli, novissima hora est: et sicut audistis quia antichristus venit, et nunc antichristi multi facti sunt; unde scimus, quia novissima hora est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Ex nobis prodierunt, sed non erant ex nobis, nam, si fuissent ex nobis, permansissent utique nobiscum: sed ut manifesti sint quoniam non sunt omnes ex nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'Sed vos unctionem habetis a Sancto, et nostis omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 21, 'Non scripsi vobis quasi ignorantibus veritatem, sed quasi scientibus eam: et quoniam omne mendacium ex veritate non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 22, 'Quis est mendax, nisi is qui negat quoniam Jesus est Christus? Hic est antichristus, qui negat Patrem, et Filium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 23, 'Omnis qui negat Filium, nec Patrem habet: qui confitetur Filium, et Patrem habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 24, 'Vos quod audistis ab initio, in vobis permaneat: si in vobis permanserit quod audistis ab initio, et vos in Filio et Patre manebitis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 25, 'Et hæc est repromissio, quam ipse pollicitus est nobis, vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 26, 'Hæc scripsi vobis de his, qui seducant vos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 27, 'Et vos unctionem, quam accepistis ab eo, maneat in vobis. Et non necesse habetis ut aliquis doceat vos: sed sicut unctio ejus docet vos de omnibus, et verum est, et non est mendacium. Et sicut docuit vos: manete in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 28, 'Et nunc, filioli, manete in eo: ut cum apparuerit, habeamus fiduciam, et non confundamur ab eo in adventu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 29, 'Si scitis quoniam justus est, scitote quoniam et omnis, qui facit justitiam, ex ipso natus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Videte qualem caritatem dedit nobis Pater, ut filii Dei nominemur et simus. Propter hoc mundus non novit nos: quia non novit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'Carissimi, nunc filii Dei sumus: et nondum apparuit quid erimus. Scimus quoniam cum apparuerit, similes ei erimus: quoniam videbimus eum sicuti est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'Et omnis qui habet hanc spem in eo, sanctificat se, sicut et ille sanctus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Omnis qui facit peccatum, et iniquitatem facit: et peccatum est iniquitas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'Et scitis quia ille apparuit ut peccata nostra tolleret: et peccatum in eo non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'Omnis qui in eo manet, non peccat: et omnis qui peccat, non vidit eum, nec cognovit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'Filioli, nemo vos seducat. Qui facit justitiam, justus est, sicut et ille justus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Qui facit peccatum, ex diabolo est: quoniam ab initio diabolus peccat. In hoc apparuit Filius Dei, ut dissolvat opera diaboli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Omnis qui natus est ex Deo, peccatum non facit: quoniam semen ipsius in eo manet, et non potest peccare, quoniam ex Deo natus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'In hoc manifesti sunt filii Dei, et filii diaboli. Omnis qui non est justus, non est ex Deo, et qui non diligit fratrem suum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'quoniam hæc est annuntiatio, quam audistis ab initio, ut diligatis alterutrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Non sicut Cain, qui ex maligno erat, et occidit fratrem suum. Et propter quid occidit eum? Quoniam opera ejus maligna erant: fratris autem ejus, justa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'Nolite mirari, fratres, si odit vos mundus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 14, 'Nos scimus quoniam translati sumus de morte ad vitam, quoniam diligimus fratres. Qui non diligit, manet in morte:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 15, 'omnis qui odit fratrem suum, homicida est. Et scitis quoniam omnis homicida non habet vitam æternam in semetipso manentem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 16, 'In hoc cognovimus caritatem Dei, quoniam ille animam suam pro nobis posuit: et nos debemus pro fratribus animas ponere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 17, 'Qui habuerit substantiam hujus mundi, et viderit fratrem suum necessitatem habere, et clauserit viscera sua ab eo: quomodo caritas Dei manet in eo?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 18, 'Filioli mei, non diligamus verbo neque lingua, sed opere et veritate:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 19, 'in hoc cognoscimus quoniam ex veritate sumus: et in conspectu ejus suadebimus corda nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 20, 'Quoniam si reprehenderit nos cor nostrum: major est Deus corde nostro, et novit omnia.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 21, 'Carissimi, si cor nostrum non reprehenderit nos, fiduciam habemus ad Deum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 22, 'et quidquid petierimus, accipiemus ab eo: quoniam mandata ejus custodimus, et ea, quæ sunt placita coram eo, facimus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 23, 'Et hoc est mandatum ejus: ut credamus in nomine Filii ejus Jesu Christi: et diligamus alterutrum, sicut dedit mandatum nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 24, 'Et qui servat mandata ejus, in illo manet, et ipse in eo: et in hoc scimus quoniam manet in nobis, de Spiritu quem dedit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Carissimi, nolite omni spiritui credere, sed probate spiritus si ex Deo sint: quoniam multi pseudoprophetæ exierunt in mundum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'In hoc cognoscitur Spiritus Dei: omnis spiritus qui confitetur Jesum Christum in carne venisse, ex Deo est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'et omnis spiritus qui solvit Jesum, ex Deo non est, et hic est antichristus, de quo audistis quoniam venit, et nunc jam in mundo est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'Vos ex Deo estis filioli, et vicistis eum, quoniam major est qui in vobis est, quam qui in mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'Ipsi de mundo sunt: ideo de mundo loquuntur, et mundus eos audit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'Nos ex Deo sumus. Qui novit Deum, audit nos; qui non est ex Deo, non audit nos: in hoc cognoscimus Spiritum veritatis, et spiritum erroris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Carissimi, diligamus nos invicem: quia caritas ex Deo est. Et omnis qui diligit, ex Deo natus est, et cognoscit Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Qui non diligit, non novit Deum: quoniam Deus caritas est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'In hoc apparuit caritas Dei in nobis, quoniam Filium suum unigenitum misit Deus in mundum, ut vivamus per eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'In hoc est caritas: non quasi nos dilexerimus Deum, sed quoniam ipse prior dilexit nos, et misit Filium suum propitiationem pro peccatis nostris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'Carissimi, si sic Deus dilexit nos: et nos debemus alterutrum diligere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'Deum nemo vidit umquam. Si diligamus invicem, Deus in nobis manet, et caritas ejus in nobis perfecta est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'In hoc cognoscimus quoniam in eo manemus, et ipse in nobis: quoniam de Spiritu suo dedit nobis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Et nos vidimus, et testificamur quoniam Pater misit Filium suum Salvatorem mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Quisquis confessus fuerit quoniam Jesus est Filius Dei, Deus in eo manet, et ipse in Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'Et nos cognovimus, et credidimus caritati, quam habet Deus in nobis. Deus caritas est: et qui manet in caritate, in Deo manet, et Deus in eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'In hoc perfecta est caritas Dei nobiscum, ut fiduciam habeamus in die judicii: quia sicut ille est, et nos sumus in hoc mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'Timor non est in caritate: sed perfecta caritas foras mittit timorem, quoniam timor pœnam habet: qui autem timet, non est perfectus in caritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 19, 'Nos ergo diligamus Deum, quoniam Deus prior dilexit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 20, 'Si quis dixerit: Quoniam diligo Deum, et fratrem suum oderit, mendax est. Qui enim non diligit fratrem suum quem vidit, Deum, quem non vidit, quomodo potest diligere?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 21, 'Et hoc mandatum habemus a Deo: ut qui diligit Deum, diligat et fratrem suum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 1, 'Omnis qui credit quoniam Jesus est Christus, ex Deo natus est. Et omnis qui diligit eum qui genuit, diligit et eum qui natus est ex eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 2, 'In hoc cognoscimus quoniam diligamus natos Dei, cum Deum diligamus, et mandata ejus faciamus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 3, 'Hæc est enim caritas Dei, ut mandata ejus custodiamus: et mandata ejus gravia non sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 4, 'Quoniam omne quod natum est ex Deo, vincit mundum: et hæc est victoria, quæ vincit mundum, fides nostra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 5, 'Quis est, qui vincit mundum, nisi qui credit quoniam Jesus est Filius Dei?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 6, 'Hic est, qui venit per aquam et sanguinem, Jesus Christus: non in aqua solum, sed in aqua et sanguine. Et Spiritus est, qui testificatur quoniam Christus est veritas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 7, 'Quoniam tres sunt, qui testimonium dant in cælo: Pater, Verbum, et Spiritus Sanctus: et hi tres unum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 8, 'Et tres sunt, qui testimonium dant in terra: spiritus, et aqua, et sanguis: et hi tres unum sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 9, 'Si testimonium hominum accipimus, testimonium Dei majus est: quoniam hoc est testimonium Dei, quod majus est, quoniam testificatus est de Filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 10, 'Qui credit in Filium Dei, habet testimonium Dei in se. Qui non credit Filio, mendacem facit eum: quia non credit in testimonium quod testificatus est Deus de Filio suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 11, 'Et hoc est testimonium, quoniam vitam æternam dedit nobis Deus: et hæc vita in Filio ejus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 12, 'Qui habet Filium, habet vitam: qui non habet Filium, vitam non habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 13, 'Hæc scribo vobis ut sciatis quoniam vitam habetis æternam, qui creditis in nomine Filii Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 14, 'Et hæc est fiducia, quam habemus ad eum: quia quodcumque petierimus, secundum voluntatem ejus, audit nos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 15, 'Et scimus quia audit nos quidquid petierimus: scimus quoniam habemus petitiones quas postulamus ab eo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 16, 'Qui scit fratrem suum peccare peccatum non ad mortem, petat, et dabitur ei vita peccanti non ad mortem. Est peccatum ad mortem: non pro illo dico ut roget quis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 17, 'Omnis iniquitas, peccatum est: et est peccatum ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 18, 'Scimus quia omnis qui natus est ex Deo, non peccat: sed generatio Dei conservat eum, et malignus non tangit eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 19, 'Scimus quoniam ex Deo sumus: et mundus totus in maligno positus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 20, 'Et scimus quoniam Filius Dei venit, et dedit nobis sensum ut cognoscamus verum Deum, et simus in vero Filio ejus. Hic est verus Deus, et vita æterna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 21, 'Filioli, custodite vos a simulacris. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Senior Electæ dominæ, et natis ejus, quos ego diligo in veritate, et non ego solus, sed et omnes qui cognoverunt veritatem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'propter veritatem, quæ permanet in nobis, et nobiscum erit in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'Sit vobiscum gratia, misericordia, pax a Deo Patre, et a Christo Jesu Filio Patris in veritate, et caritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'Gavisus sum valde, quoniam inveni de filiis tuis ambulantes in veritate, sicut mandatum accepimus a Patre.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'Et nunc rogo te domina, non tamquam mandatum novum scribens tibi, sed quod habuimus ab initio, ut diligamus alterutrum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'Et hæc est caritas, ut ambulemus secundum mandata ejus. Hoc est enim mandatum, ut quemadmodum audistis ab initio, in eo ambuletis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'Quoniam multi seductores exierunt in mundum, qui non confitentur Jesum Christum venisse in carnem: hic est seductor, et antichristus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'Videte vosmetipsos, ne perdatis quæ operati estis: sed ut mercedem plenam accipiatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Omnis qui recedit, et non permanet in doctrina Christi, Deum non habet: qui permanet in doctrina, hic et Patrem et Filium habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'Si quis venit ad vos, et hanc doctrinam non affert, nolite recipere eum in domum, nec Ave ei dixeritis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'Qui enim dicit illi Ave, communicat operibus ejus malignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'Plura habens vobis scribere, nolui per cartam et atramentum: spero enim me futurum apud vos, et os ad os loqui: ut gaudium vestrum plenum sit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 13, 'Salutant te filii sororis tuæ Electæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Senior Gajo carissimo, quem ego diligo in veritate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'Carissime, de omnibus orationem facio prospere te ingredi, et valere sicut prospere agit anima tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Gavisus sum valde venientibus fratribus, et testimonium perhibentibus veritati tuæ, sicut tu in veritate ambulas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'Majorem horum non habeo gratiam, quam ut audiam filios meos in veritate ambulare.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Carissime, fideliter facis quidquid operaris in fratres, et hoc in peregrinos,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'qui testimonium reddiderunt caritati tuæ in conspectu ecclesiæ: quos, benefaciens, deduces digne Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'Pro nomine enim ejus profecti sunt, nihil accipientes a gentibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Nos ergo debemus suscipere hujusmodi, ut cooperatores simus veritatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'Scripsissem forsitan ecclesiæ: sed is qui amat primatum gerere in eis, Diotrephes, non recipit nos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'propter hoc si venero, commonebo ejus opera, quæ facit, verbis malignis garriens in nos: et quasi non ei ista sufficiant, neque ipse suscipit fratres: et eos qui suscipiunt, prohibet, et de ecclesia ejicit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Carissime, noli imitari malum, sed quod bonum est. Qui benefacit, ex Deo est: qui malefacit, non vidit Deum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Demetrio testimonium redditur ab omnibus, et ab ipsa veritate, sed et nos testimonium perhibemus: et nosti quoniam testimonium nostrum verum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'Multa habui tibi scribere: sed nolui per atramentum et calamum scribere tibi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'Spero autem protinus te videre, et os ad os loquemur. Pax tibi. Salutant te amici. Saluta amicos nominatim.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, '');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Judas Jesu Christi servus, frater autem Jacobi, his qui sunt in Deo Patre dilectis, et Christo Jesu conservatis, et vocatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'Misericordia vobis, et pax, et caritas adimpleatur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Carissimi, omnem sollicitudinem faciens scribendi vobis de communi vestra salute, necesse habui scribere vobis: deprecans supercertari semel traditæ sanctis fidei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Subintroierunt enim quidam homines (qui olim præscripti sunt in hoc judicium) impii, Dei nostri gratiam transferentes in luxuriam, et solum Dominatorem, et Dominum nostrum Jesum Christum negantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Commonere autem vos volo, scientes semel omnia, quoniam Jesus populum de terra \'gypti salvans, secundo eos, qui non crediderunt, perdidit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'angelos vero, qui non servaverunt suum principatum, sed dereliquerunt suum domicilium, in judicium magni diei, vinculis æternis sub caligine reservavit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'Sicut Sodoma, et Gomorrha, et finitimæ civitates simili modo exfornicatæ, et abeuntes post carnem alteram, factæ sunt exemplum, ignis æterni pœnam sustinentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Similiter et hi carnem quidem maculant, dominationem autem spernunt, majestatem autem blasphemant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'Cum Michaël Archangelus cum diabolo disputans altercaretur de Moysi corpore, non est ausus judicium inferre blasphemiæ: sed dixit: Imperet tibi Dominus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'Hi autem quæcumque quidem ignorant, blasphemant: quæcumque autem naturaliter, tamquam muta animalia, norunt, in his corrumpuntur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'Væ illis, quia in via Cain abierunt, et errore Balaam mercede effusi sunt, et in contradictione Core perierunt!');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Hi sunt in epulis suis maculæ, convivantes sine timore, semetipsos pascentes, nubes sine aqua, quæ a ventis circumferentur, arbores autumnales, infructuosæ, bis mortuæ, eradicatæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'fluctus feri maris, despumantes suas confusiones, sidera errantia: quibus procella tenebrarum servata est in æternum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Prophetavit autem et de his septimus ab Adam Enoch, dicens: Ecce venit Dominus in sanctis millibus suis');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'facere judicium contra omnes, et arguere omnes impios de omnibus operibus impietatis eorum, quibus impie egerunt, et de omnibus duris, quæ locuti sunt contra Deum peccatores impii.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'Hi sunt murmuratores querulosi, secundum desideria sua ambulantes, et os eorum loquitur superba, mirantes personas quæstus causa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'Vos autem carissimi, memores estote verborum, quæ prædicta sunt ab apostolis Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, 'qui dicebant vobis, quoniam in novissimo tempore venient illusores, secundum desideria sua ambulantes in impietatibus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 19, 'Hi sunt, qui segregant semetipsos, animales, Spiritum non habentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 20, 'Vos autem carissimi superædificantes vosmetipsos sanctissimæ vestræ fidei, in Spiritu Sancto orantes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 21, 'vosmetipsos in dilectione Dei servate, exspectantes misericordiam Domini nostri Jesu Christi in vitam æternam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 22, 'Et hos quidem arguite judicatos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 23, 'illos vero salvate, de igne rapientes. Aliis autem miseremini in timore: odientes et eam, quæ carnalis est, maculatam tunicam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 24, 'Ei autem qui potens est vos conservare sine peccato et constituere ante conspectum gloriæ suæ immaculatos in exsultatione in adventu Domini nostri Jesu Christi,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 25, 'soli Deo Salvatori nostro, per Jesum Christum Dominum nostrum, gloria et magnificentia, imperium et potestas ante omne sæculum, et nunc, et in omnia sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Apocalypsis Jesu Christi, quam dedit illi Deus palam facere servis suis, quæ oportet fieri cito: et significavit, mittens per angelum suum servo suo Joanni,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'qui testimonium perhibuit verbo Dei, et testimonium Jesu Christi, quæcumque vidit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'Beatus qui legit, et audit verba prophetiæ hujus, et servat ea, quæ in ea scripta sunt: tempus enim prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'Joannes septem ecclesiis, quæ sunt in Asia. Gratia vobis, et pax ab eo, qui est, et qui erat, et qui venturus est: et a septem spiritibus qui in conspectu throni ejus sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'et a Jesu Christo, qui est testis fidelis, primogenitus mortuorum, et princeps regum terræ, qui dilexit nos, et lavit nos a peccatis nostris in sanguine suo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'et fecit nos regnum, et sacerdotes Deo et Patri suo: ipsi gloria et imperium in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Ecce venit cum nubibus, et videbit eum omnis oculus, et qui eum pupugerunt. Et plangent se super eum omnes tribus terræ. Etiam: amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'Ego sum alpha et omega, principium et finis, dicit Dominus Deus: qui est, et qui erat, et qui venturus est, omnipotens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'Ego Joannes frater vester, et particeps in tribulatione, et regno, et patientia in Christo Jesu: fui in insula, quæ appellatur Patmos, propter verbum Dei, et testimonium Jesu:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'fui in spiritu in Dominica die, et audivi post me vocem magnam tamquam tubæ,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'dicentis: Quod vides, scribe in libro: et mitte septem ecclesiis, quæ sunt in Asia, Epheso, et Smyrnæ, et Pergamo, et Thyatiræ, et Sardis, et Philadelphiæ, et Laodiciæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Et conversus sum ut viderem vocem, quæ loquebatur mecum: et conversus vidi septem candelabra aurea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'et in medio septem candelabrorum aureorum, similem Filio hominis vestitum podere, et præcinctum ad mamillas zona aurea:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'caput autem ejus, et capilli erant candidi tamquam lana alba, et tamquam nix, et oculi ejus tamquam flamma ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'et pedes ejus similes auricalco, sicut in camino ardenti, et vox illius tamquam vox aquarum multarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'et habebat in dextera sua stellas septem: et de ore ejus gladius utraque parte acutus exibat: et facies ejus sicut sol lucet in virtute sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 17, 'Et cum vidissem eum, cecidi ad pedes ejus tamquam mortuus. Et posuit dexteram suam super me, dicens: Noli timere: ego sum primus, et novissimus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 18, 'et vivus, et fui mortuus, et ecce sum vivens in sæcula sæculorum: et habeo claves mortis, et inferni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 19, 'Scribe ergo quæ vidisti, et quæ sunt, et quæ oportet fieri post hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 20, 'Sacramentum septem stellarum, quas vidisti in dextera mea, et septem candelabra aurea: septem stellæ, angeli sunt septem ecclesiarum: et candelabra septem, septem ecclesiæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Angelo Ephesi ecclesiæ scribe: Hæc dicit, qui tenet septem stellas in dextera sua, qui ambulat in medio septem candelabrorum aureorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Scio opera tua, et laborem, et patientiam tuam, et quia non potes sustinere malos: et tentasti eos, qui se dicunt apostolos esse, et non sunt: et invenisti eos mendaces:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'et patientiam habes, et sustinuisti propter nomen meum, et non defecisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'Sed habeo adversum te, quod caritatem tuam primam reliquisti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Memor esto itaque unde excideris: et age pœnitentiam, et prima opera fac: sin autem, venio tibi, et movebo candelabrum tuum de loco suo, nisi pœnitentiam egeris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Sed hoc habes, quia odisti facta Nicolaitarum, quæ et ego odi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis: Vincenti dabo edere de ligno vitæ, quod est in paradiso Dei mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'Et angelo Smyrnæ ecclesiæ scribe: Hæc dicit primus, et novissimus, qui fuit mortuus, et vivit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Scio tribulationem tuam, et paupertatem tuam, sed dives es: et blasphemaris ab his, qui se dicunt Judæos esse, et non sunt, sed sunt synagoga Satanæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Nihil horum timeas quæ passurus es. Ecce missurus est diabolus aliquos ex vobis in carcerem ut tentemini: et habebitis tribulationem diebus decem. Esto fidelis usque ad mortem, et dabo tibi coronam vitæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis: Qui vicerit, non lædetur a morte secunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'Et angelo Pergami ecclesiæ scribe: Hæc dicit qui habet rhomphæam utraque parte acutam:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'Scio ubi habitas, ubi sedes est Satanæ: et tenes nomen meum, et non negasti fidem meam. Et in diebus illis Antipas testis meus fidelis, qui occisus est apud vos ubi Satanas habitat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'Sed habeo adversus te pauca: quia habes illic tenentes doctrinam Balaam, qui docebat Balac mittere scandalum coram filiis Israël, edere, et fornicari:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'ita habes et tu tenentes doctrinam Nicolaitarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 16, 'Similiter pœnitentiam age: si quominus veniam tibi cito, et pugnabo cum illis in gladio oris mei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 17, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis: Vincenti dabo manna absconditum, et dabo illi calculum candidum: et in calculo nomen novum scriptum, quod nemo scit, nisi qui accipit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 18, 'Et angelo Thyatiræ ecclesiæ scribe: Hæc dicit Filius Dei, qui habet oculos tamquam flammam ignis, et pedes ejus similes auricalco:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 19, 'Novi opera tua, et fidem, et caritatem tuam, et ministerium, et patientiam tuam, et opera tua novissima plura prioribus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 20, 'Sed habeo adversus te pauca: quia permittis mulierem Jezabel, quæ se dicit propheten, docere, et seducere servos meos, fornicari, et manducare de idolothytis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 21, 'Et dedi illi tempus ut pœnitentiam ageret: et non vult pœnitere a fornicatione sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 22, 'Ecce mittam eam in lectum: et qui mœchantur cum ea, in tribulatione maxima erunt, nisi pœnitentiam ab operibus suis egerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 23, 'Et filios ejus interficiam in morte, et scient omnes ecclesiæ, quia ego sum scrutans renes, et corda: et dabo unicuique vestrum secundum opera sua. Vobis autem dico,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 24, 'et ceteris qui Thyatiræ estis: quicumque non habent doctrinam hanc, et qui non cognoverunt altitudines Satanæ, quemadmodum dicunt, non mittam super vos aliud pondus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 25, 'tamen id quod habetis, tenete donec veniam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 26, 'Et qui vicerit, et custodierit usque in finem opera mea, dabo illi potestatem super gentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 27, 'et reget eas in virga ferrea, et tamquam vas figuli confringentur,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 28, 'sicut et ego accepi a Patre meo: et dabo illi stellam matutinam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 29, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Et angelo ecclesiæ Sardis scribe: Hæc dicit qui habet septem spiritus Dei, et septem stellas: Scio opera tua, quia nomen habes quod vivas, et mortuus es.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'Esto vigilans, et confirma cetera, quæ moritura erant. Non enim invenio opera tua plena coram Deo meo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'In mente ergo habe qualiter acceperis, et audieris, et serva, et pœnitentiam age. Si ergo non vigilaveris, veniam ad te tamquam fur et nescies qua hora veniam ad te.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Sed habes pauca nomina in Sardis qui non inquinaverunt vestimenta sua: et ambulabunt mecum in albis, quia digni sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'Qui vicerit, sic vestietur vestimentis albis, et non delebo nomen ejus de libro vitæ, et confitebor nomen ejus coram Patre meo, et coram angelis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'Et angelo Philadelphiæ ecclesiæ scribe: Hæc dicit Sanctus et Verus, qui habet clavem David: qui aperit, et nemo claudit: claudit, et nemo aperit:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Scio opera tua. Ecce dedi coram te ostium apertum, quod nemo potest claudere: quia modicam habes virtutem, et servasti verbum meum, et non negasti nomen meum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Ecce dabo de synagoga Satanæ, qui dicunt se Judæos esse, et non sunt, sed mentiuntur: ecce faciam illos ut veniant, et adorent ante pedes tuos: et scient quia ego dilexi te,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'quoniam servasti verbum patientiæ meæ, et ego servabo te ab hora tentationis, quæ ventura est in orbem universum tentare habitantes in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'Ecce venio cito: tene quod habes, ut nemo accipiat coronam tuam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Qui vicerit, faciam illum columnam in templo Dei mei, et foras non egredietur amplius: et scribam super eum nomen Dei mei, et nomen civitatis Dei mei novæ Jerusalem, quæ descendit de cælo a Deo meo, et nomen meum novum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Et angelo Laodiciæ ecclesiæ scribe: Hæc dicit: Amen, testis fidelis et verus, qui est principium creaturæ Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Scio opera tua: quia neque frigidus es, neque calidus: utinam frigidus esses, aut calidus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 16, 'sed quia tepidus es, et nec frigidus, nec calidus, incipiam te evomere ex ore meo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 17, 'quia dicis: Quod dives sum, et locupletatus, et nullius egeo: et nescis quia tu es miser, et miserabilis, et pauper, et cæcus, et nudus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 18, 'Suadeo tibi emere a me aurum ignitum probatum, ut locuples fias, et vestimentis albis induaris, et non appareat confusio nuditatis tuæ, et collyrio inunge oculos tuos ut videas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 19, 'Ego quos amo, arguo, et castigo. \'mulare ergo, et pœnitentiam age.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 20, 'Ecce sto ad ostium, et pulso: si quis audierit vocem meam, et aperuerit mihi januam, intrabo ad illum, et cœnabo cum illo, et ipse mecum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 21, 'Qui vicerit, dabo ei sedere mecum in throno meo: sicut et ego vici, et sedi cum Patre meo in throno ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 22, 'Qui habet aurem, audiat quid Spiritus dicat ecclesiis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 1, 'Post hæc vidi: et ecce ostium apertum in cælo, et vox prima, quam audivi tamquam tubæ loquentis mecum, dicens: Ascende huc, et ostendam tibi quæ oportet fieri post hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 2, 'Et statim fui in spiritu: et ecce sedes posita erat in cælo, et supra sedem sedens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 3, 'Et qui sedebat similis erat aspectui lapidis jaspidis, et sardinis: et iris erat in circuitu sedis similis visioni smaragdinæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 4, 'Et in circuitu sedis sedilia viginti quatuor: et super thronos viginti quatuor seniores sedentes, circumamicti vestimentis albis, et in capitibus eorum coronæ aureæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 5, 'Et de throno procedebant fulgura, et voces, et tonitrua: et septem lampades ardentes ante thronum, qui sunt septem spiritus Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 6, 'Et in conspectu sedis tamquam mare vitreum simile crystallo: et in medio sedis, et in circuitu sedis quatuor animalia plena oculis ante et retro.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 7, 'Et animal primum simile leoni, et secundum animal simile vitulo, et tertium animal habens faciem quasi hominis, et quartum animal simile aquilæ volanti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 8, 'Et quatuor animalia, singula eorum habebant alas senas: et in circuitu, et intus plena sunt oculis: et requiem non habebant die ac nocte, dicentia: Sanctus, Sanctus, Sanctus Dominus Deus omnipotens, qui erat, et qui est, et qui venturus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 9, 'Et cum darent illa animalia gloriam, et honorem, et benedictionem sedenti super thronum, viventi in sæcula sæculorum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 10, 'procidebant viginti quatuor seniores ante sedentem in throno, et adorabant viventem in sæcula sæculorum, et mittebant coronas suas ante thronum, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 4, 11, 'Dignus es Domine Deus noster accipere gloriam, et honorem, et virtutem: quia tu creasti omnia, et propter voluntatem tuam erant, et creata sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 1, 'Et vidi in dextera sedentis supra thronum, librum scriptum intus et foris, signatum sigillis septem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 2, 'Et vidi angelum fortem, prædicantem voce magna: Quis est dignus aperire librum, et solvere signacula ejus?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 3, 'Et nemo poterat neque in cælo, neque in terra, neque subtus terram aperire librum, neque respicere illum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 4, 'Et ego flebam multum, quoniam nemo dignus inventus est aperire librum, nec videre eum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 5, 'Et unus de senioribus dixit mihi: Ne fleveris: ecce vicit leo de tribu Juda, radix David, aperire librum, et solvere septem signacula ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 6, 'Et vidi: et ecce in medio throni et quatuor animalium, et in medio seniorum, Agnum stantem tamquam occisum, habentem cornua septem, et oculos septem: qui sunt septem spiritus Dei, missi in omnem terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 7, 'Et venit: et accepit de dextera sedentis in throno librum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 8, 'Et cum aperuisset librum, quatuor animalia, et viginti quatuor seniores ceciderunt coram Agno, habentes singuli citharas, et phialas aureas plenas odoramentorum, quæ sunt orationes sanctorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 9, 'et cantabant canticum novum, dicentes: Dignus es, Domine, accipere librum, et aperire signacula ejus: quoniam occisus es, et redemisti nos Deo in sanguine tuo ex omni tribu, et lingua, et populo, et natione:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 10, 'et fecisti nos Deo nostro regnum, et sacerdotes: et regnabimus super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 11, 'Et vidi, et audivi vocem angelorum multorum in circuitu throni, et animalium, et seniorum: et erat numerus eorum millia millium,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 12, 'dicentium voce magna: Dignus est Agnus, qui occisus est, accipere virtutem, et divinitatem, et sapientiam, et fortitudinem, et honorem, et gloriam, et benedictionem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 13, 'Et omnem creaturam, quæ in cælo est, et super terram, et sub terra, et quæ sunt in mari, et quæ in eo: omnes audivi dicentes: Sedenti in throno, et Agno, benedictio et honor, et gloria, et potestas in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 5, 14, 'Et quatuor animalia dicebant: Amen. Et viginti quatuor seniores ceciderunt in facies suas: et adoraverunt viventem in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 1, 'Et vidi quod aperuisset Agnus unum de septem sigillis, et audivi unum de quatuor animalibus, dicens tamquam vocem tonitrui: Veni, et vide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 2, 'Et vidi: et ecce equus albus, et qui sedebat super illum, habebat arcum, et data est ei corona, et exivit vincens ut vinceret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 3, 'Et cum aperuisset sigillum secundum, audivi secundum animal, dicens: Veni, et vide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 4, 'Et exivit alius equus rufus: et qui sedebat super illum, datum est ei ut sumeret pacem de terra, et ut invicem se interficiant, et datus est ei gladius magnus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 5, 'Et cum aperuisset sigillum tertium, audivi tertium animal, dicens: Veni, et vide. Et ecce equus niger: et qui sedebat super illum, habebat stateram in manu sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 6, 'Et audivi tamquam vocem in medio quatuor animalium dicentium: Bilibris tritici denario et tres bilibres hordei denario, et vinum, et oleum ne læseris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 7, 'Et cum aperuisset sigillum quartum, audivi vocem quarti animalis dicentis: Veni, et vide.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 8, 'Et ecce equus pallidus: et qui sedebat super eum, nomen illi Mors, et infernus sequebatur eum, et data est illi potestas super quatuor partes terræ, interficere gladio, fame, et morte, et bestiis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 9, 'Et cum aperuisset sigillum quintum, vidi subtus altare animas interfectorum propter verbum Dei, et propter testimonium, quod habebant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 10, 'et clamabant voce magna, dicentes: Usquequo Domine (sanctus et verus), non judicas, et non vindicas sanguinem nostrum de iis qui habitant in terra?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 11, 'Et datæ sunt illis singulæ stolæ albæ: et dictum est illis ut requiescerent adhuc tempus modicum donec compleantur conservi eorum, et fratres eorum, qui interficiendi sunt sicut et illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 12, 'Et vidi cum aperuisset sigillum sextum: et ecce terræmotus magnus factus est, et sol factus est niger tamquam saccus cilicinus: et luna tota facta est sicut sanguis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 13, 'et stellæ de cælo ceciderunt super terram, sicut ficus emittit grossos suos cum a vento magno movetur:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 14, 'et cælum recessit sicut liber involutus: et omnis mons, et insulæ de locis suis motæ sunt:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 15, 'et reges terræ, et principes, et tribuni, et divites, et fortes, et omnis servus, et liber absconderunt se in speluncis, et in petris montium:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 16, 'et dicunt montibus, et petris: Cadite super nos, et abscondite nos a facie sedentis super thronum, et ab ira Agni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 6, 17, 'quoniam venit dies magnus iræ ipsorum: et quis poterit stare?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 1, 'Post hæc vidi quatuor angelos stantes super quatuor angulos terræ, tenentes quatuor ventos terræ, ne flarent super terram, neque super mare, neque in ullam arborem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 2, 'Et vidi alterum angelum ascendentem ab ortu solis, habentem signum Dei vivi: et clamavit voce magna quatuor angelis, quibus datum est nocere terræ et mari,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 3, 'dicens: Nolite nocere terræ, et mari, neque arboribus, quoadusque signemus servos Dei nostri in frontibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 4, 'Et audivi numerum signatorum, centum quadraginta quatuor millia signati, ex omni tribu filiorum Israël.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 5, 'Ex tribu Juda duodecim millia signati: ex tribu Ruben duodecim millia signati: ex tribu Gad duodecim millia signati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 6, 'ex tribu Aser duodecim millia signati: ex tribu Nephthali duodecim millia signati: ex tribu Manasse duodecim millia signati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 7, 'ex tribu Simeon duodecim millia signati: ex tribu Levi duodecim millia signati: ex tribu Issachar duodecim millia signati:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 8, 'ex tribu Zabulon duodecim millia signati: ex tribu Joseph duodecim millia signati: ex tribu Benjamin duodecim millia signati.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 9, 'Post hæc vidi turbam magnam, quam dinumerare nemo poterat, ex omnibus gentibus, et tribubus, et populis, et linguis: stantes ante thronum, et in conspectu Agni, amicti stolis albis, et palmæ in manibus eorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 10, 'et clamabant voce magna, dicentes: Salus Deo nostro, qui sedet super thronum, et Agno.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 11, 'Et omnes angeli stabant in circuitu throni, et seniorum, et quatuor animalium: et ceciderunt in conspectu throni in facies suas, et adoraverunt Deum,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 12, 'dicentes: Amen. Benedictio, et claritas, et sapientia, et gratiarum actio, honor, et virtus, et fortitudo Deo nostro in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 13, 'Et respondit unus de senioribus et dixit mihi: Hi, qui amicti sunt stolis albis, qui sunt? et unde venerunt?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 14, 'Et dixi illi: Domine mi, tu scis. Et dixit mihi: Hi sunt, qui venerunt de tribulatione magna, et laverunt stolas suas, et dealbaverunt eas in sanguine Agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 15, 'Ideo sunt ante thronum Dei, et serviunt ei die ac nocte in templo ejus: et qui sedet in throno, habitabit super illos:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 16, 'non esurient, neque sitient amplius, nec cadet super illos sol, neque ullus æstus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 7, 17, 'quoniam Agnus, qui in medio throni est, reget illos et deducet eos ad vitæ fontes aquarum, et absterget Deus omnem lacrimam ab oculis eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 1, 'Et cum aperuisset sigillum septimum, factum est silentium in cælo, quasi media hora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 2, 'Et vidi septem angelos stantes in conspectu Dei: et datæ sunt illis septem tubæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 3, 'Et alius angelus venit, et stetit ante altare habens thuribulum aureum: et data sunt illi incensa multa, ut daret de orationibus sanctorum omnium super altare aureum, quod est ante thronum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 4, 'Et ascendit fumus incensorum de orationibus sanctorum de manu angeli coram Deo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 5, 'Et accepit angelus thuribulum, et implevit illud de igne altaris, et misit in terram: et facta sunt tonitrua, et voces, et fulgura, et terræmotus magnus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 6, 'Et septem angeli, qui habebant septem tubas, præparaverunt se ut tuba canerent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 7, 'Et primus angelus tuba cecinit, et facta est grando, et ignis, mista in sanguine, et missum est in terram, et tertia pars terræ combusta est, et tertia pars arborum concremata est, et omne fœnum viride combustum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 8, 'Et secundus angelus tuba cecinit: et tamquam mons magnus igne ardens missus est in mare, et facta est tertia pars maris sanguis,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 9, 'et mortua est tertia pars creaturæ eorum, quæ habebant animas in mari, et tertia pars navium interiit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 10, 'Et tertius angelus tuba cecinit: et cecidit de cælo stella magna, ardens tamquam facula, et cecidit in tertiam partem fluminum, et in fontes aquarum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 11, 'et nomen stellæ dicitur Absinthium, et facta est tertia pars aquarum in absinthium; et multi hominum mortui sunt de aquis, quia amaræ factæ sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 12, 'Et quartus angelus tuba cecinit: et percussa est tertia pars solis, et tertia pars lunæ, et tertia pars stellarum, ita ut obscuraretur tertia pars eorum, et diei non luceret pars tertia, et noctis similiter.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 8, 13, 'Et vidi, et audivi vocem unius aquilæ volantis per medium cæli dicentis voce magna: Væ, væ, væ habitantibus in terra de ceteris vocibus trium angelorum, qui erant tuba canituri.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 1, 'Et quintus angelus tuba cecinit: et vidi stellam de cælo cecidisse in terram, et data est ei clavis putei abyssi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 2, 'Et aperuit puteum abyssi: et ascendit fumus putei, sicut fumus fornacis magnæ: et obscuratus est sol, et aër de fumo putei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 3, 'et de fumo putei exierunt locustæ in terram, et data est illis potestas, sicut habent potestatem scorpiones terræ:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 4, 'et præceptum est illis ne læderent fœnum terræ, neque omne viride, neque omnem arborem: nisi tantum homines, qui non habent signum Dei in frontibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 5, 'et datum est illis ne occiderent eos: sed ut cruciarent mensibus quinque: et cruciatus eorum, ut cruciatus scorpii cum percutit hominem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 6, 'Et in diebus illis quærent homines mortem, et non invenient eam: et desiderabunt mori, et fugiet mors ab eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 7, 'Et similitudines locustarum, similes equis paratis in prælium: et super capita earum tamquam coronæ similes auro: et facies earum tamquam facies hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 8, 'Et habebant capillos sicut capillos mulierum. Et dentes earum, sicut dentes leonum erant:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 9, 'et habebant loricas sicut loricas ferreas, et vox alarum earum sicut vox curruum equorum multorum currentium in bellum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 10, 'et habebant caudas similes scorpionum, et aculei erant in caudis earum: et potestas earum nocere hominibus mensibus quinque:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 11, 'et habebant super se regem angelum abyssi cui nomen hebraice Abaddon, græce autem Apollyon, latine habens nomen Exterminans.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 12, 'Væ unum abiit, et ecce veniunt adhuc duo væ post hæc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 13, 'Et sextus angelus tuba cecinit: et audivi vocem unam ex quatuor cornibus altaris aurei, quod est ante oculos Dei,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 14, 'dicentem sexto angelo, qui habebat tubam: Solve quatuor angelos, qui alligati sunt in flumine magno Euphrate.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 15, 'Et soluti sunt quatuor angeli, qui parati erant in horam, et diem, et mensem, et annum, ut occiderent tertiam partem hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 16, 'Et numerus equestris exercitus vicies millies dena millia. Et audivi numerum eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 17, 'Et ita vidi equos in visione: et qui sedebant super eos, habebant loricas igneas, et hyacinthinas, et sulphureas, et capita equorum erant tamquam capita leonum: et de ore eorum procedit ignis, et fumus, et sulphur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 18, 'Et ab his tribus plagis occisa est tertia pars hominum de igne, et de fumo, et sulphure, quæ procedebant de ore ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 19, 'Potestas enim equorum in ore eorum est, et in caudis eorum, nam caudæ eorum similes serpentibus, habentes capita: et in his nocent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 20, 'Et ceteri homines, qui non sunt occisi in his plagis, neque pœnitentiam egerunt de operibus manuum suarum, ut non adorarent dæmonia, et simulacra aurea, et argentea, et ærea, et lapidea, et lignea, quæ neque videre possunt, neque audire, neque ambulare,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 9, 21, 'et non egerunt pœnitentiam ab homicidiis suis, neque a veneficiis suis, neque a fornicatione sua, neque a furtis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 1, 'Et vidi alium angelum fortem descendentem de cælo amictum nube, et iris in capite ejus, et facies ejus erat ut sol, et pedes ejus tamquam columnæ ignis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 2, 'et habebat in manu sua libellum apertum: et posuit pedem suum dextrum super mare, sinistrum autem super terram:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 3, 'et clamavit voce magna, quemadmodum cum leo rugit. Et cum clamasset, locuta sunt septem tonitrua voces suas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 4, 'Et cum locuta fuissent septem tonitrua voces suas, ego scripturus eram: et audivi vocem de cælo dicentem mihi: Signa quæ locuta sunt septem tonitrua: et noli ea scribere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 5, 'Et angelus, quem vidi stantem super mare et super terram, levavit manum suam ad cælum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 6, 'et juravit per viventem in sæcula sæculorum, qui creavit cælum, et ea quæ in eo sunt: et terram, et ea quæ in ea sunt: et mare, et ea quæ in eo sunt: Quia tempus non erit amplius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 7, 'sed in diebus vocis septimi angeli, cum cœperit tuba canere, consummabitur mysterium Dei sicut evangelizavit per servos suos prophetas.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 8, 'Et audivi vocem de cælo iterum loquentem mecum, et dicentem: Vade, et accipe librum apertum de manu angeli stantis super mare, et super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 9, 'Et abii ad angelum, dicens ei, ut daret mihi librum. Et dixit mihi: Accipe librum, et devora illum: et faciet amaricari ventrem tuum, sed in ore tuo erit dulce tamquam mel.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 10, 'Et accepi librum de manu angeli, et devoravi illum: et erat in ore meo tamquam mel dulce, et cum devorassem eum, amaricatus est venter meus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 10, 11, 'et dixit mihi: Oportet te iterum prophetare gentibus, et populis, et linguis, et regibus multis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 1, 'Et datus est mihi calamus similis virgæ, et dictum est mihi: Surge, et metire templum Dei, et altare, et adorantes in eo:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 2, 'atrium autem, quod est foris templum, ejice foras, et ne metiaris illud: quoniam datum est gentibus, et civitatem sanctam calcabunt mensibus quadraginta duobus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 3, 'et dabo duobus testibus meis, et prophetabunt diebus mille ducentis sexaginta, amicti saccis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 4, 'Hi sunt duæ olivæ et duo candelabra in conspectu Domini terræ stantes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 5, 'Et si quis voluerit eos nocere, ignis exiet de ore eorum, et devorabit inimicos eorum: et si quis voluerit eos lædere, sic oportet eum occidi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 6, 'Hi habent potestatem claudendi cælum, ne pluat diebus prophetiæ ipsorum: et potestatem habent super aquas convertendi eas in sanguinem, et percutere terram omni plaga quotiescumque voluerint.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 7, 'Et cum finierint testimonium suum, bestia, quæ ascendit de abysso, faciet adversum eos bellum, et vincet illos, et occidet eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 8, 'Et corpora eorum jacebunt in plateis civitatis magnæ, quæ vocatur spiritualiter Sodoma, et \'gyptus, ubi et Dominus eorum crucifixus est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 9, 'Et videbunt de tribubus, et populis, et linguis, et gentibus corpora eorum per tres dies et dimidium: et corpora eorum non sinent poni in monumentis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 10, 'et inhabitantes terram gaudebunt super illos, et jucundabuntur: et munera mittent invicem, quoniam hi duo prophetæ cruciaverunt eos, qui habitabant super terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 11, 'Et post dies tres et dimidium, spiritus vitæ a Deo intravit in eos. Et steterunt super pedes suos, et timor magnus cecidit super eos qui viderunt eos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 12, 'Et audierunt vocem magnam de cælo, dicentem eis: Ascendite huc. Et ascenderunt in cælum in nube: et viderunt illos inimici eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 13, 'Et in illa hora factus est terræmotus magnus, et decima pars civitatis cecidit: et occisa sunt in terræmotu nomina hominum septem millia: et reliqui in timorem sunt missi, et dederunt gloriam Deo cæli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 14, 'Væ secundum abiit: et ecce væ tertium veniet cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 15, 'Et septimus angelus tuba cecinit: et factæ sunt voces magnæ in cælo dicentes: Factum est regnum hujus mundi, Domini nostri et Christi ejus, et regnabit in sæcula sæculorum. Amen.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 16, 'Et viginti quatuor seniores, qui in conspectu Dei sedent in sedibus suis, ceciderunt in facies suas, et adoraverunt Deum, dicentes:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 17, 'Gratias agimus tibi, Domine Deus omnipotens, qui es, et qui eras, et qui venturus es: quia accepisti virtutem tuam magnam, et regnasti.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 18, 'Et iratæ sunt gentes, et advenit ira tua et tempus mortuorum judicari, et reddere mercedem servis tuis prophetis, et sanctis, et timentibus nomen tuum pusillis et magnis, et exterminandi eos qui corruperunt terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 11, 19, 'Et apertum est templum Dei in cælo: et visa est arca testamenti ejus in templo ejus, et facta sunt fulgura, et voces, et terræmotus, et grando magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 1, 'Et signum magnum apparuit in cælo: mulier amicta sole, et luna sub pedibus ejus, et in capite ejus corona stellarum duodecim:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 2, 'et in utero habens, clamabat parturiens, et cruciabatur ut pariat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 3, 'Et visum est aliud signum in cælo: et ecce draco magnus rufus habens capita septem, et cornua decem: et in capitibus ejus diademata septem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 4, 'et cauda ejus trahebat tertiam partem stellarum cæli, et misit eas in terram: et draco stetit ante mulierem, quæ erat paritura, ut cum peperisset, filium ejus devoraret.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 5, 'Et peperit filium masculum, qui recturus erat omnes gentes in virga ferrea: et raptus est filius ejus ad Deum, et ad thronum ejus,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 6, 'et mulier fugit in solitudinem ubi habebat locum paratum a Deo, ut ibi pascant eam diebus mille ducentis sexaginta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 7, 'Et factum est prælium magnum in cælo: Michaël et angeli ejus præliabantur cum dracone, et draco pugnabat, et angeli ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 8, 'et non valuerunt, neque locus inventus est eorum amplius in cælo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 9, 'Et projectus est draco ille magnus, serpens antiquus, qui vocatur diabolus, et Satanas, qui seducit universum orbem: et projectus est in terram, et angeli ejus cum illo missi sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 10, 'Et audivi vocem magnam in cælo dicentem: Nunc facta est salus, et virtus, et regnum Dei nostri, et potestas Christi ejus: quia projectus est accusator fratrum nostrorum, qui accusabat illos ante conspectum Dei nostri die ac nocte.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 11, 'Et ipsi vicerunt eum propter sanguinem Agni, et propter verbum testimonii sui, et non dilexerunt animas suas usque ad mortem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 12, 'Propterea lætamini cæli, et qui habitatis in eis. Væ terræ, et mari, quia descendit diabolus ad vos habens iram magnam, sciens quod modicum tempus habet.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 13, 'Et postquam vidit draco quod projectus esset in terram, persecutus est mulierem, quæ peperit masculum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 14, 'et datæ sunt mulieri alæ duæ aquilæ magnæ ut volaret in desertum in locum suum, ubi alitur per tempus et tempora, et dimidium temporis a facie serpentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 15, 'Et misit serpens ex ore suo post mulierem, aquam tamquam flumen, ut eam faceret trahi a flumine.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 16, 'Et adjuvit terra mulierem, et aperuit terra os suum, et absorbuit flumen, quod misit draco de ore suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 17, 'Et iratus est draco in mulierem: et abiit facere prælium cum reliquis de semine ejus, qui custodiunt mandata Dei, et habent testimonium Jesu Christi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 12, 18, 'Et stetit supra arenam maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 1, 'Et vidi de mari bestiam ascendentem habentem capita septem, et cornua decem, et super cornua ejus decem diademata, et super capita ejus nomina blasphemiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 2, 'Et bestia, quam vidi, similis erat pardo, et pedes ejus sicut pedes ursi, et os ejus sicut os leonis. Et dedit illi draco virtutem suam, et potestatem magnam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 3, 'Et vidi unum de capitibus suis quasi occisum in mortem: et plaga mortis ejus curata est. Et admirata est universa terra post bestiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 4, 'Et adoraverunt draconem, qui dedit potestatem bestiæ: et adoraverunt bestiam, dicentes: Quis similis bestiæ? et quis poterit pugnare cum ea?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 5, 'Et datum est ei os loquens magna et blasphemias: et data est ei potestas facere menses quadraginta duos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 6, 'Et aperuit os suum in blasphemias ad Deum, blasphemare nomen ejus, et tabernaculum ejus, et eos qui in cælo habitant.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 7, 'Et est datum illi bellum facere cum sanctis, et vincere eos. Et data est illi potestas in omnem tribum, et populum, et linguam, et gentem,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 8, 'et adoraverunt eam omnes, qui inhabitant terram: quorum non sunt scripta nomina in libro vitæ Agni, qui occisus est ab origine mundi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 9, 'Si quis habet aurem, audiat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 10, 'Qui in captivitatem duxerit, in captivitatem vadet: qui in gladio occiderit, oportet eum gladio occidi. Hic est patientia, et fides sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 11, 'Et vidi aliam bestiam ascendentem de terra, et habebat cornua duo similia Agni, et loquebatur sicut draco.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 12, 'Et potestatem prioris bestiæ omnem faciebat in conspectu ejus: et fecit terram, et habitantes in ea, adorare bestiam primam, cujus curata est plaga mortis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 13, 'Et fecit signa magna, ut etiam ignem faceret de cælo descendere in terram in conspectu hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 14, 'Et seduxit habitantes in terra propter signa, quæ data sunt illi facere in conspectu bestiæ, dicens habitantibus in terra, ut faciant imaginem bestiæ, quæ habet plagam gladii, et vixit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 15, 'Et datum est illi ut daret spiritum imagini bestiæ, et ut loquatur imago bestiæ: et faciat ut quicumque non adoraverint imaginem bestiæ, occidantur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 16, 'Et faciet omnes pusillos, et magnos, et divites, et pauperes, et liberos, et servos habere caracterem in dextera manu sua, aut in frontibus suis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 17, 'et nequis possit emere, aut vendere, nisi qui habet caracterem, aut nomen bestiæ, aut numerum nominis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 13, 18, 'Hic sapientia est. Qui habet intellectum, computet numerum bestiæ. Numerus enim hominis est: et numerus ejus sexcenti sexaginta sex.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 1, 'Et vidi: et ecce Agnus stabat supra montem Sion, et cum eo centum quadraginta quatuor millia, habentes nomen ejus, et nomen Patris ejus scriptum in frontibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 2, 'Et audivi vocem de cælo, tamquam vocem aquarum multarum, et tamquam vocem tonitrui magni: et vocem, quam audivi, sicut citharœdorum citharizantium in citharis suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 3, 'Et cantabant quasi canticum novum ante sedem, et ante quatuor animalia, et seniores: et nemo poterat dicere canticum, nisi illa centum quadraginta quatuor millia, qui empti sunt de terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 4, 'Hi sunt, qui cum mulieribus non sunt coinquinati: virgines enim sunt. Hi sequuntur Agnum quocumque ierit. Hi empti sunt ex hominibus primitiæ Deo, et Agno:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 5, 'et in ore eorum non est inventum mendacium: sine macula enim sunt ante thronum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 6, 'Et vidi alterum angelum volantem per medium cæli, habentem Evangelium æternum, ut evangelizaret sedentibus super terram, et super omnem gentem, et tribum, et linguam, et populum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 7, 'dicens magna voce: Timete Dominum, et date illi honorem, quia venit hora judicii ejus: et adorate eum, qui fecit cælum, et terram, mare, et fontes aquarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 8, 'Et alius angelus secutus est dicens: Cecidit, cecidit Babylon illa magna: quæ a vino iræ fornicationis suæ potavit omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 9, 'Et tertius angelus secutus est illos, dicens voce magna: Si quis adoraverit bestiam, et imaginem ejus, et acceperit caracterem in fronte sua, aut in manu sua:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 10, 'et hic bibet de vino iræ Dei, quod mistum est mero in calice iræ ipsius, et cruciabitur igne, et sulphure in conspectu angelorum sanctorum, et ante conspectum Agni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 11, 'et fumus tormentorum eorum ascendet in sæcula sæculorum: nec habent requiem die ac nocte, qui adoraverunt bestiam, et imaginem ejus, et si quis acceperit caracterem nominis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 12, 'Hic patientia sanctorum est, qui custodiunt mandata Dei, et fidem Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 13, 'Et audivi vocem de cælo, dicentem mihi: Scribe: Beati mortui qui in Domino moriuntur. Amodo jam dicit Spiritus, ut requiescant a laboribus suis: opera enim illorum sequuntur illos.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 14, 'Et vidi: et ecce nubem candidam, et super nubem sedentem similem Filio hominis, habentem in capite suo coronam auream, et in manu sua falcem acutam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 15, 'Et alius angelus exivit de templo, clamans voce magna ad sedentem super nubem: Mitte falcem tuam, et mete, quia venit hora ut metatur, quoniam aruit messis terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 16, 'Et misit qui sedebat super nubem, falcem suam in terram, et demessa est terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 17, 'Et alius angelus exivit de templo, quod est in cælo, habens et ipse falcem acutam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 18, 'Et alius angelus exivit de altari, qui habebat potestatem supra ignem: et clamavit voce magna ad eum qui habebat falcem acutam, dicens: Mitte falcem tuam acutam, et vindemia botros vineæ terræ: quoniam maturæ sunt uvæ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 19, 'Et misit angelus falcem suam acutam in terram, et vindemiavit vineam terræ, et misit in lacum iræ Dei magnum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 14, 20, 'et calcatus est lacus extra civitatem, et exivit sanguis de lacu usque ad frenos equorum per stadia mille sexcenta.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 1, 'Et vidi aliud signum in cælo magnum et mirabile, angelos septem, habentes plagas septem novissimas: quoniam in illis consummata est ira Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 2, 'Et vidi tamquam mare vitreum mistum igne, et eos, qui vicerunt bestiam, et imaginem ejus, et numerum nominis ejus, stantes super mare vitreum, habentes citharas Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 3, 'et cantantes canticum Moysi servi Dei, et canticum Agni, dicentes: Magna et mirabilia sunt opera tua, Domine Deus omnipotens: justæ et veræ sunt viæ tuæ, Rex sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 4, 'Quis non timebit te, Domine, et magnificabit nomen tuum? quia solus pius es: quoniam omnes gentes venient, et adorabunt in conspectu tuo, quoniam judicia tua manifesta sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 5, 'Et post hæc vidi: et ecce apertum est templum tabernaculi testimonii in cælo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 6, 'et exierunt septem angeli habentes septem plagas de templo, vestiti lino mundo et candido, et præcincti circa pectora zonis aureis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 7, 'Et unum de quatuor animalibus dedit septem angelis septem phialas aureas, plenas iracundiæ Dei viventis in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 15, 8, 'Et impletum est templum fumo a majestate Dei, et de virtute ejus: et nemo poterat introire in templum, donec consummarentur septem plagæ septem angelorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 1, 'Et audivi vocem magnam de templo, dicentem septem angelis: Ite, et effundite septem phialas iræ Dei in terram.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 2, 'Et abiit primus, et effudit phialam suam in terram, et factum est vulnus sævum et pessimum in homines, qui habebant caracterem bestiæ, et in eos qui adoraverunt imaginem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 3, 'Et secundus angelus effudit phialam suam in mare, et factus est sanguis tamquam mortui: et omnis anima vivens mortua est in mari.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 4, 'Et tertius effudit phialam suam super flumina, et super fontes aquarum, et factus est sanguis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 5, 'Et audivi angelum aquarum dicentem: Justus es, Domine, qui es, et qui eras sanctus, qui hæc judicasti:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 6, 'quia sanguinem sanctorum et prophetarum effuderunt, et sanguinem eis dedisti bibere: digni enim sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 7, 'Et audivi alterum ab altari dicentem: Etiam Domine Deus omnipotens, vera et justa judicia tua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 8, 'Et quartus angelus effudit phialam suam in solem, et datum est illi æstu affligere homines, et igni:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 9, 'et æstuaverunt homines æstu magno, et blasphemaverunt nomen Dei habentis potestatem super has plagas, neque egerunt pœnitentiam ut darent illi gloriam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 10, 'Et quintus angelus effudit phialam suam super sedem bestiæ: et factum est regnum ejus tenebrosum, et commanducaverunt linguas suas præ dolore:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 11, 'et blasphemaverunt Deum cæli præ doloribus, et vulneribus suis, et non egerunt pœnitentiam ex operibus suis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 12, 'Et sextus angelus effudit phialam suam in flumen illud magnum Euphraten: et siccavit aquam ejus, ut præpararetur via regibus ab ortu solis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 13, 'Et vidi de ore draconis, et de ore bestiæ, et de ore pseudoprophetæ spiritus tres immundos in modum ranarum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 14, 'Sunt enim spiritus dæmoniorum facientes signa, et procedunt ad reges totius terræ congregare illos in prælium ad diem magnum omnipotentis Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 15, 'Ecce venio sicut fur. Beatus qui vigilat, et custodit vestimenta sua, ne nudus ambulet, et videant turpitudinem ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 16, 'Et congregabit illos in locum qui vocatur hebraice Armagedon.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 17, 'Et septimus angelus effudit phialam suam in aërem, et exivit vox magna de templo a throno, dicens: Factum est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 18, 'Et facta sunt fulgura, et voces, et tonitrua, et terræmotus factus est magnus, qualis numquam fuit ex quo homines fuerunt super terram: talis terræmotus, sic magnus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 19, 'Et facta est civitas magna in tres partes: et civitates gentium ceciderunt. Et Babylon magna venit in memoriam ante Deum, dare illi calicem vini indignationis iræ ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 20, 'Et omnis insula fugit, et montes non sunt inventi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 16, 21, 'Et grando magna sicut talentum descendit de cælo in homines: et blasphemaverunt Deum homines propter plagam grandinis: quoniam magna facta est vehementer.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 1, 'Et venit unus de septem angelis, qui habebant septem phialas, et locutus est mecum, dicens: Veni, ostendam tibi damnationem meretricis magnæ, quæ sedet super aquas multas,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 2, 'cum qua fornicati sunt reges terræ, et inebriati sunt qui inhabitant terram de vino prostitutionis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 3, 'Et abstulit me in spiritu in desertum. Et vidi mulierem sedentem super bestiam coccineam, plenam nominibus blasphemiæ, habentem capita septem, et cornua decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 4, 'Et mulier erat circumdata purpura, et coccino, et inaurata auro, et lapide pretioso, et margaritis, habens poculum aureum in manu sua, plenum abominatione, et immunditia fornicationis ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 5, 'Et in fronte ejus nomen scriptum: Mysterium: Babylon magna, mater fornicationum, et abominationum terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 6, 'Et vidi mulierem ebriam de sanguine sanctorum, et de sanguine martyrum Jesu. Et miratus sum cum vidissem illam admiratione magna.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 7, 'Et dixit mihi angelus: Quare miraris? ego dicam tibi sacramentum mulieris, et bestiæ, quæ portat eam, quæ habet capita septem, et cornua decem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 8, 'Bestia, quam vidisti, fuit, et non est, et ascensura est de abysso, et in interitum ibit: et mirabuntur inhabitantes terram (quorum non sunt scripta nomina in libro vitæ a constitutione mundi) videntes bestiam, quæ erat, et non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 9, 'Et hic est sensus, qui habet sapientiam. Septem capita, septem montes sunt, super quos mulier sedet, et reges septem sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 10, 'Quinque ceciderunt, unus est, et alius nondum venit: et cum venerit, oportet illum breve tempus manere.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 11, 'Et bestia, quæ erat, et non est: et ipsa octava est: et de septem est, et in interitum vadit.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 12, 'Et decem cornua, quæ vidisti, decem reges sunt: qui regnum nondum acceperunt, sed potestatem tamquam reges una hora accipient post bestiam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 13, 'Hi unum consilium habent, et virtutem, et potestatem suam bestiæ tradent.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 14, 'Hi cum Agno pugnabunt, et Agnus vincet illos: quoniam Dominus dominorum est, et Rex regum, et qui cum illo sunt, vocati, electi, et fideles.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 15, 'Et dixit mihi: Aquæ, quas vidisti ubi meretrix sedet, populi sunt, et gentes, et linguæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 16, 'Et decem cornua, quæ vidisti in bestia: hi odient fornicariam, et desolatam facient illam, et nudam, et carnes ejus manducabunt, et ipsam igni concremabunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 17, 'Deus enim dedit in corda eorum ut faciant quod placitum est illi: ut dent regnum suum bestiæ donec consummentur verba Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 17, 18, 'Et mulier, quam vidisti, est civitas magna, quæ habet regnum super reges terræ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 1, 'Et post hæc vidi alium angelum descendentem de cælo, habentem potestatem magnam: et terra illuminata est a gloria ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 2, 'Et exclamavit in fortitudine, dicens: Cecidit, cecidit Babylon magna: et facta est habitatio dæmoniorum, et custodia omnis spiritus immundi, et custodia omnis volucris immundæ, et odibilis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 3, 'quia de vino iræ fornicationis ejus biberunt omnes gentes: et reges terræ cum illa fornicati sunt: et mercatores terræ de virtute deliciarum ejus divites facti sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 4, 'Et audivi aliam vocem de cælo, dicentem: Exite de illa populus meus: ut ne participes sitis delictorum ejus, et de plagis ejus non accipiatis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 5, 'Quoniam pervenerunt peccata ejus usque ad cælum, et recordatus est Dominus iniquitatum ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 6, 'Reddite illi sicut et ipsa reddidit vobis: et duplicate duplicia secundum opera ejus: in poculo, quo miscuit, miscete illi duplum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 7, 'Quantum glorificavit se, et in deliciis fuit, tantum date illi tormentum et luctum: quia in corde suo dicit: Sedeo regina: et vidua non sum, et luctum non videbo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 8, 'Ideo in una die venient plagæ ejus, mors, et luctus, et fames, et igne comburetur: quia fortis est Deus, qui judicabit illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 9, 'Et flebunt, et plangent se super illam reges terræ, qui cum illa fornicati sunt, et in deliciis vixerunt, cum viderint fumum incendii ejus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 10, 'longe stantes propter timorem tormentorum ejus, dicentes: Væ, væ civitas illa magna Babylon, civitas illa fortis: quoniam una hora venit judicium tuum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 11, 'Et negotiatores terræ flebunt, et lugebunt super illam: quoniam merces eorum nemo emet amplius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 12, 'merces auri, et argenti, et lapidis pretiosi, et margaritæ, et byssi, et purpuræ, et serici, et cocci (et omne lignum thyinum, et omnia vasa eboris, et omnia vasa de lapide pretioso, et æramento, et ferro, et marmore,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 13, 'et cinnamomum) et odoramentorum, et unguenti, et thuris, et vini, et olei, et similæ, et tritici, et jumentorum, et ovium, et equorum, et rhedarum, et mancipiorum, et animarum hominum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 14, 'Et poma desiderii animæ tuæ discesserunt a te, et omnia pinguia et præclara perierunt a te, et amplius illa jam non invenient.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 15, 'Mercatores horum, qui divites facti sunt, ab ea longe stabunt propter timorem tormentorum ejus, flentes, ac lugentes,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 16, 'et dicentes: Væ, væ civitas illa magna, quæ amicta erat bysso, et purpura, et cocco, et deaurata erat auro, et lapide pretioso, et margaritis:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 17, 'quoniam una hora destitutæ sunt tantæ divitiæ, et omnis gubernator, et omnis qui in lacum navigat, et nautæ, et qui in mari operantur, longe steterunt,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 18, 'et clamaverunt videntes locum incendii ejus, dicentes: Quæ similis civitati huic magnæ?');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 19, 'et miserunt pulverem super capita sua, et clamaverunt flentes, et lugentes, dicentes: Væ, væ civitas illa magna, in qua divites facti sunt omnes, qui habebant naves in mari de pretiis ejus: quoniam una hora desolata est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 20, 'Exsulta super eam cælum, et sancti apostoli, et prophetæ: quoniam judicavit Deus judicium vestrum de illa.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 21, 'Et sustulit unus angelus fortis lapidem quasi molarem magnum, et misit in mare, dicens: Hoc impetu mittetur Babylon civitas illa magna, et ultra jam non invenietur.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 22, 'Et vox citharœdorum, et musicorum, et tibia canentium, et tuba non audietur in te amplius: et omnis artifex omnis artis non invenietur in te amplius: et vox molæ non audietur in te amplius:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 23, 'et lux lucernæ non lucebit in te amplius: et vox sponsi et sponsæ non audietur adhuc in te: quia mercatores tui erant principes terræ, quia in veneficiis tuis erraverunt omnes gentes.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 18, 24, 'Et in ea sanguis prophetarum et sanctorum inventus est: et omnium qui interfecti sunt in terra.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 1, 'Post hæc audivi quasi vocem turbarum multarum in cælo dicentium: Alleluja: salus, et gloria, et virtus Deo nostro est:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 2, 'quia vera et justa judicia sunt ejus, qui judicavit de meretrice magna, quæ corrupit terram in prostitutione sua, et vindicavit sanguinem servorum suorum de manibus ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 3, 'Et iterum dixerunt: Alleluja. Et fumus ejus ascendit in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 4, 'Et ceciderunt seniores viginti quatuor, et quatuor animalia, et adoraverunt Deum sedentem super thronum, dicentes: Amen: alleluja.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 5, 'Et vox de throno exivit, dicens: Laudem dicite Deo nostro omnes servi ejus: et qui timetis eum pusilli et magni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 6, 'Et audivi quasi vocem turbæ magnæ, et sicut vocem aquarum multarum, et sicut vocem tonitruorum magnorum, dicentium: Alleluja: quoniam regnavit Dominus Deus noster omnipotens.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 7, 'Gaudeamus, et exsultemus: et demus gloriam ei: quia venerunt nuptiæ Agni, et uxor ejus præparavit se.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 8, 'Et datum est illi ut cooperiat se byssino splendenti et candido. Byssinum enim justificationes sunt sanctorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 9, 'Et dixit mihi: Scribe: Beati qui ad cœnam nuptiarum Agni vocati sunt; et dixit mihi: Hæc verba Dei vera sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 10, 'Et cecidi ante pedes ejus, ut adorarem eum. Et dicit mihi: Vide ne feceris: conservus tuus sum, et fratrum tuorum habentium testimonium Jesu. Deum adora. Testimonium enim Jesu est spiritus prophetiæ.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 11, 'Et vidi cælum apertum, et ecce equus albus, et qui sedebat super eum, vocabatur Fidelis, et Verax, et cum justitia judicat et pugnat.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 12, 'Oculi autem ejus sicut flamma ignis, et in capite ejus diademata multa, habens nomen scriptum, quod nemo novit nisi ipse.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 13, 'Et vestitus erat veste aspersa sanguine: et vocatur nomen ejus: Verbum Dei.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 14, 'Et exercitus qui sunt in cælo, sequebantur eum in equis albis, vestiti byssino albo et mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 15, 'Et de ore ejus procedit gladius ex utraque parte acutus, ut in ipso percutiat gentes. Et ipse reget eas in virga ferrea: et ipse calcat torcular vini furoris iræ Dei omnipotentis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 16, 'Et habet in vestimento et in femore suo scriptum: Rex regum et Dominus dominantium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 17, 'Et vidi unum angelum stantem in sole, et clamavit voce magna, dicens omnibus avibus, quæ volabant per medium cæli: Venite, et congregamini ad cœnam magnam Dei:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 18, 'ut manducetis carnes regum, et carnes tribunorum, et carnes fortium, et carnes equorum, et sedentium in ipsis, et carnes omnium liberorum, et servorum, et pusillorum et magnorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 19, 'Et vidi bestiam, et reges terræ, et exercitus eorum congregatos ad faciendum prælium cum illo, qui sedebat in equo, et cum exercitu ejus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 20, 'Et apprehensa est bestia, et cum ea pseudopropheta: qui fecit signa coram ipso, quibus seduxit eos, qui acceperunt caracterem bestiæ, et qui adoraverunt imaginem ejus. Vivi missi sunt hi duo in stagnum ignis ardentis sulphure:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 19, 21, 'et ceteri occisi sunt in gladio sedentis super equum, qui procedit de ore ipsius: et omnes aves saturatæ sunt carnibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 1, 'Et vidi angelum descendentem de cælo, habentem clavem abyssi, et catenam magnam in manu sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 2, 'Et apprehendit draconem, serpentem antiquum, qui est diabolus, et Satanas, et ligavit eum per annos mille:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 3, 'et misit eum in abyssum, et clausit, et signavit super illum ut non seducat amplius gentes, donec consummentur mille anni: et post hæc oportet illum solvi modico tempore.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 4, 'Et vidi sedes, et sederunt super eas, et judicium datum est illis: et animas decollatorum propter testimonium Jesu, et propter verbum Dei, et qui non adoraverunt bestiam, neque imaginem ejus, nec acceperunt caracterem ejus in frontibus, aut in manibus suis, et vixerunt, et regnaverunt cum Christo mille annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 5, 'Ceteri mortuorum non vixerunt, donec consummentur mille anni. Hæc est resurrectio prima.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 6, 'Beatus, et sanctus, qui habet partem in resurrectione prima: in his secunda mors non habet potestatem: sed erunt sacerdotes Dei et Christi, et regnabunt cum illo mille annis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 7, 'Et cum consummati fuerint mille anni, solvetur Satanas de carcere suo, et exibit, et seducet gentes, quæ sunt super quatuor angulos terræ, Gog, et Magog, et congregabit eos in prælium, quorum numerus est sicut arena maris.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 8, 'Et ascenderunt super latitudinem terræ, et circuierunt castra sanctorum, et civitatem dilectam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 9, 'Et descendit ignis a Deo de cælo, et devoravit eos: et diabolus, qui seducebat eos, missus est in stagnum ignis, et sulphuris, ubi et bestia');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 10, 'et pseudopropheta cruciabuntur die ac nocte in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 11, 'Et vidi thronum magnum candidum, et sedentem super eum, a cujus conspectu fugit terra, et cælum, et locus non est inventus eis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 12, 'Et vidi mortuos, magnos et pusillos, stantes in conspectu throni, et libri aperti sunt: et alius liber apertus est, qui est vitæ: et judicati sunt mortui ex his, quæ scripta erant in libris, secundum opera ipsorum:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 13, 'et dedit mare mortuos, qui in eo erant: et mors et infernus dederunt mortuos suos, qui in ipsis erant: et judicatum est de singulis secundum opera ipsorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 14, 'Et infernus et mors missi sunt in stagnum ignis. Hæc est mors secunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 20, 15, 'Et qui non inventus est in libro vitæ scriptus, missus est in stagnum ignis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 1, 'Et vidi cælum novum et terram novam. Primum enim cælum, et prima terra abiit, et mare jam non est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 2, 'Et ego Joannes vidi sanctam civitatem Jerusalem novam descendentem de cælo a Deo, paratam sicut sponsam ornatam viro suo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 3, 'Et audivi vocem magnam de throno dicentem: Ecce tabernaculum Dei cum hominibus, et habitabit cum eis. Et ipsi populus ejus erunt, et ipse Deus cum eis erit eorum Deus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 4, 'et absterget Deus omnem lacrimam ab oculis eorum: et mors ultra non erit, neque luctus, neque clamor, neque dolor erit ultra, quia prima abierunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 5, 'Et dixit qui sedebat in throno: Ecce nova facio omnia. Et dixit mihi: Scribe, quia hæc verba fidelissima sunt, et vera.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 6, 'Et dixit mihi: Factum est: ego sum alpha et omega, initium et finis. Ego sitienti dabo de fonte aquæ vitæ, gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 7, 'Qui vicerit, possidebit hæc: et ero illi Deus, et ille erit mihi filius.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 8, 'Timidis autem, et incredulis, et execratis, et homicidis, et fornicatoribus, et veneficis, et idolatris, et omnibus mendacibus, pars illorum erit in stagno ardenti igne et sulphure: quod est mors secunda.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 9, 'Et venit unus de septem angelis habentibus phialas plenas septem plagis novissimis, et locutus est mecum, dicens: Veni, et ostendam tibi sponsam, uxorem Agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 10, 'Et sustulit me in spiritu in montem magnum et altum, et ostendit mihi civitatem sanctam Jerusalem descendentem de cælo a Deo,');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 11, 'habentem claritatem Dei: et lumen ejus simile lapidi pretioso tamquam lapidi jaspidis, sicut crystallum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 12, 'Et habebat murum magnum, et altum, habentem portas duodecim: et in portis angelos duodecim, et nomina inscripta, quæ sunt nomina duodecim tribuum filiorum Israël:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 13, 'ab oriente portæ tres, et ab aquilone portæ tres, et ab austro portæ tres, et ab occasu portæ tres.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 14, 'Et murus civitatis habens fundamenta duodecim, et in ipsis duodecim nomina duodecim apostolorum Agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 15, 'Et qui loquebatur mecum, habebat mensuram arundineam auream, ut metiretur civitatem, et portas ejus, et murum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 16, 'Et civitas in quadro posita est, et longitudo ejus tanta est quanta et latitudo: et mensus est civitatem de arundine aurea per stadia duodecim millia: et longitudo, et altitudo, et latitudo ejus æqualia sunt.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 17, 'Et mensus est murum ejus centum quadraginta quatuor cubitorum, mensura hominis, quæ est angeli.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 18, 'Et erat structura muri ejus ex lapide jaspide: ipsa vero civitas aurum mundum simile vitro mundo.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 19, 'Et fundamenta muri civitatis omni lapide pretioso ornata. Fundamentum primum, jaspis: secundum, sapphirus: tertium, calcedonius: quartum, smaragdus:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 20, 'quintum, sardonyx: sextum, sardius: septimum, chrysolithus: octavum, beryllus: nonum, topazius: decimum, chrysoprasus: undecimum, hyacinthus: duodecimum, amethystus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 21, 'Et duodecim portæ, duodecim margaritæ sunt, per singulas: et singulæ portæ erant ex singulis margaritis: et platea civitatis aurum mundum, tamquam vitrum perlucidum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 22, 'Et templum non vidi in ea: Dominus enim Deus omnipotens templum illius est, et Agnus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 23, 'Et civitas non eget sole neque luna ut luceant in ea, nam claritas Dei illuminavit eam, et lucerna ejus est Agnus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 24, 'Et ambulabunt gentes in lumine ejus: et reges terræ afferent gloriam suam et honorem in illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 25, 'Et portæ ejus non claudentur per diem: nox enim non erit illic.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 26, 'Et afferent gloriam et honorem gentium in illam.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 21, 27, 'Non intrabit in eam aliquod coinquinatum, aut abominationem faciens et mendacium, nisi qui scripti sunt in libro vitæ Agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 1, 'Et ostendit mihi fluvium aquæ vitæ, splendidum tamquam crystallum, procedentem de sede Dei et Agni.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 2, 'In medio plateæ ejus, et ex utraque parte fluminis, lignum vitæ, afferens fructus duodecim per menses singulos, reddens fructum suum et folia ligni ad sanitatem gentium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 3, 'Et omne maledictum non erit amplius: sed sedes Dei et Agni in illa erunt, et servi ejus servient illi.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 4, 'Et videbunt faciem ejus: et nomen ejus in frontibus eorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 5, 'Et nox ultra non erit: et non egebunt lumine lucernæ, neque lumine solis, quoniam Dominus Deus illuminabit illos, et regnabunt in sæcula sæculorum.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 6, 'Et dixit mihi: Hæc verba fidelissima sunt, et vera. Et Dominus Deus spirituum prophetarum misit angelum suum ostendere servis suis quæ oportet fieri cito.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 7, 'Et ecce venio velociter. Beatus, qui custodit verba prophetiæ libri hujus.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 8, 'Et ego Joannes, qui audivi, et vidi hæc. Et postquam audissem, et vidissem, cecidi ut adorarem ante pedes angeli, qui mihi hæc ostendebat:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 9, 'et dixit mihi: Vide ne feceris: conservus enim tuus sum, et fratrum tuorum prophetarum, et eorum qui servant verba prophetiæ libri hujus: Deum adora.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 10, 'Et dicit mihi: Ne signaveris verba prophetiæ libri hujus: tempus enim prope est.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 11, 'Qui nocet, noceat adhuc: et qui in sordibus est, sordescat adhuc: et qui justus est, justificetur adhuc: et sanctus, sanctificetur adhuc.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 12, 'Ecce venio cito, et merces mea mecum est, reddere unicuique secundum opera sua.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 13, 'Ego sum alpha et omega, primus et novissimus, principium et finis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 14, 'Beati, qui lavant stolas suas in sanguine Agni: ut sit potestas eorum in ligno vitæ, et per portas intrent in civitatem.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 15, 'Foris canes, et venefici, et impudici, et homicidæ, et idolis servientes, et omnis qui amat et facit mendacium.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 16, 'Ego Jesus misi angelum meum testificari vobis hæc in ecclesiis. Ego sum radix, et genus David, stella splendida et matutina.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 17, 'Et spiritus, et sponsa dicunt: Veni. Et qui audit, dicat: Veni. Et qui sitit, veniat: et qui vult, accipiat aquam vitæ, gratis.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 18, 'Contestor enim omni audienti verba prophetiæ libri hujus: si quis apposuerit ad hæc, apponet Deus super illum plagas scriptas in libro isto.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 19, 'Et si quis diminuerit de verbis libri prophetiæ hujus, auferet Deus partem ejus de libro vitæ, et de civitate sancta, et de his quæ scripta sunt in libro isto:');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 20, 'dicit qui testimonium perhibet istorum. Etiam venio cito: amen. Veni, Domine Jesu.');
INSERT INTO `VulgClementine_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 22, 21, 'Gratia Domini nostri Jesu Christi cum omnibus vobis. Amen.');
